INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8adfa2e-d0e3-42f4-a30a-62fbda3b6ed9', 'a7159cd2-dd97-45d6-a41a-7d6211f75072', 'Nutritional Value of Sainfoin Hay Compared with Alfalfa Hay', 'Ricardo J. Parker, B.R. Moss', 1981, 'Journal of Dairy Science', '10.3168/jds.s0022-0302(81)82555-6', 'https://doi.org/10.3168/jds.s0022-0302(81)82555-6', 'https://doi.org/10.3168/jds.s0022-0302(81)82555-6', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb3f3f31-f38f-4abd-9ba7-f3f14f1a490e', 'a7159cd2-dd97-45d6-a41a-7d6211f75072', 'Practical Measures for Reducing Risk of Alfalfa Bloat in Cattle', 'W. Majak, John Whitney Hall, Tim Angus McAllister', 2001, 'Journal of Range Management', '10.2307/4003120', 'https://doi.org/10.2307/4003120', 'https://repository.arizona.edu/bitstream/10150/643897/1/9647-9528-1-PB.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e8f78ed-e6a5-4e2d-a9c6-1832cf932a07', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Managing for Multifunctionality in Perennial Grain Crops', 'Ryan MR, Crews TE, Culman SW, DeHaan LR, Hayes RC, Jungers JM, Bakker MG', 2018, 'Bioscience', '10.1093/biosci/biy014', 'https://doi.org/10.1093/biosci/biy014', 'https://europepmc.org/articles/PMC5894082?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by-nc', 'Plant breeders are increasing yields and improving agronomic traits in several perennial grain crops, the first of which is now being incorporated into commercial food products. Integration strategies and management guidelines are needed to optimize production of these new crops, which differ substantially from both annual grain crops and perennial forages. To offset relatively low grain yields, perennial grain cropping systems should be multifunctional. Growing perennial grains for several years to regenerate soil health before rotating to annual crops and growing perennial grains on sloped land and ecologically sensitive areas to reduce soil erosion and nutrient losses are two strategies that can provide ecosystem services and support multifunctionality. Several perennial cereals can be used to produce both grain and forage, and these dual-purpose crops can be intercropped with legumes for additional benefits. Highly diverse perennial grain polycultures can further enhance ecosystem services, but increased management complexity might limit their adoption.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0b07c665-7f66-41d4-bb4f-6140c4fc11d4', 'a7159cd2-dd97-45d6-a41a-7d6211f75072', 'The role of bacteria in the root and crown rot complex of irrigated sainfoin (Onobrychis viciifolia Scop.) in Montana', 'Denis A. Gaudet', 1978, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/handle/1/5199', 'https://scholarworks.montana.edu/bitstreams/0e2c270d-9849-4dc4-a0fc-70b7729c00e2/download', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aefe82e5-f049-41bb-9add-533a3c0eda97', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Rate of herbicide resistant weed development: A Canadian Prairie case study', 'Sutherland C, Gleim S, Lubieniechi S, Smyth SJ', 2025, 'GM crops & food', '10.1080/21645698.2025.2477231', 'https://doi.org/10.1080/21645698.2025.2477231', 'https://europepmc.org/articles/PMC11901363?pdf=render', NULL, NULL, 11, NULL, 'prairies', 4, 'cc by', 'Genetically modified crop adoption in Canada has been the key driver in removing tillage as the lead form of weed control, due to increased weed control efficiency. Land use has transitioned from the use of summerfallow to continuous cropping, predominantly involving zero or minimum tillage practices. Prairie crop rotations have diversified away from mainly cereals to include three-year rotations of cereals, pulses, and oilseeds. Total herbicide volume applied has increased as crop production acres increased, but the rate of herbicide active ingredient applied per hectare has declined. Diverse crop rotations allow for weed control using herbicides with different modes of action, reducing selection pressure for resistant weed development. Herbicide-resistant weeds are an important concern for farmers, as the loss of key herbicides would make weed control exceedingly more difficult. The objective of this case study is to examine herbicide resistance weed development in the Canadian Prairies and to identify changes in resistance development following GM crop adoption.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3eae6232-3c00-45c8-a05c-7489e66be51d', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Recent Weed Control, Weed Management, and Integrated Weed Management', 'K. Neil Harker, John T. O’Donovan', 2013, 'Weed Technology', '10.1614/wt-d-12-00109.1', 'https://doi.org/10.1614/wt-d-12-00109.1', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/52F8DB68CF951B73F7AB477478A60C55/S0890037X00012549a.pdf/div-class-title-recent-weed-control-weed-management-and-integrated-weed-management-div.pdf', NULL, NULL, 11, NULL, 'alberta', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4179c410-9724-4fe0-b538-dff1188559f8', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'Diquat Used as a Preharvest Desiccant Affects Seed Germination of Spinach, Table Beet, and Coriander', 'Timothy W. Miller', 2002, 'HortScience', '10.21273/hortsci.37.7.1032', 'https://doi.org/10.21273/hortsci.37.7.1032', 'https://journals.ashs.org/downloadpdf/journals/hortsci/37/7/article-p1032.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
