INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('93b139bf-e8da-44ba-8be4-fdea9f88b6bd', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'Molecular Cloning of GA 2-Oxidase3 from Spinach and Its Ectopic Expression in Nicotiana sylvestris', 'Dong Ju Lee, Jan A. D. Zeevaart', 2005, 'PLANT PHYSIOLOGY', '10.1104/pp.104.056499', 'https://doi.org/10.1104/pp.104.056499', 'https://academic.oup.com/plphys/article-pdf/138/1/243/38707343/plphys_v138_1_243.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9696d629-cd61-483f-a637-b08731f756e3', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'Temperature desynchronizes sugar and organic acid metabolism in ripening grapevine fruits and remodels their transcriptome', 'Rienth M, Torregrosa L, Sarah G, Ardisson M, Brillouet JM, Romieu C', 2016, 'BMC plant biology', '10.1186/s12870-016-0850-0', 'https://doi.org/10.1186/s12870-016-0850-0', 'https://europepmc.org/articles/PMC4955140?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'BackgroundFruit composition at harvest is strongly dependent on the temperature during the grapevine developmental cycle. This raises serious concerns regarding the sustainability of viticulture and the socio-economic repercussions of global warming for many regions where the most heat-tolerant varieties are already cultivated. Despite recent progress, the direct and indirect effects of temperature on fruit development are far from being understood. Experimental limitations such as fluctuating environmental conditions, intra-cluster heterogeneity and the annual reproductive cycle introduce unquantifiable biases for gene expression and physiological studies with grapevine. In the present study, DRCF grapevine mutants (microvine) were grown under several temperature regimes in duly-controlled environmental conditions. A singly berry selection increased the accuracy of fruit phenotyping and subsequent gene expression analyses. The physiological and transcriptomic responses of five key stages sampled simultaneously at day and nighttime were studied by RNA-seq analysis.ResultsA total of 674 millions reads were sequenced from all experiments. Analysis of differential expression yielded in a total of 10 788 transcripts modulated by temperature. An acceleration of green berry development under higher temperature was correlated with the induction of several candidate genes linked to cell expansion. High temperatures impaired tannin synthesis and degree of galloylation at the transcriptomic levels. The timing of malate breakdown was delayed to mid-ripening in transgressively cool conditions, revealing unsuspected plasticity of berry primary metabolism. Specific ATPases and malate transporters displayed development and temperature-dependent expression patterns, besides less marked but significant regulation of other genes in the malate pathway.ConclusionThe present study represents, to our knowledge the first abiotic stress study performed on a fleshy fruits model using RNA-seq for transcriptomic analysis. It confirms that a careful stage selection and a rigorous control of environmental conditions are needed to address the long-term plasticity of berry development with respect to temperature. Original results revealed temperature-dependent regulation of key metabolic processes in the elaboration of berry composition. Malate breakdown no longer appears as an integral part of the veraison program, but as possibly triggered by an imbalance in cytoplasmic sugar, when efficient vacuolar storage is set on with ripening, in usual temperature conditions. Furthermore, variations in heat shock responsive genes that will be very valuable for further research on temperature adaptation of plants have been evidenced.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4232f2b1-fcb4-47ab-a4ca-08f3f560284a', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'The power of magnesium: unlocking the potential for increased yield, quality, and stress tolerance of horticultural crops', 'Ahmed N, Zhang B, Bozdar B, Chachar S, Rai M, Li J, Li Y, Hayat F', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1285512', 'https://doi.org/10.3389/fpls.2023.1285512', 'https://europepmc.org/articles/PMC10628537?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Magnesium (Mg2+) is pivotal for the vitality, yield, and quality of horticultural crops. Central to plant physiology, Mg2+ powers photosynthesis as an integral component of chlorophyll, bolstering growth and biomass accumulation. Beyond basic growth, it critically affects crop quality factors, from chlorophyll synthesis to taste, texture, and shelf life. However, Mg2 + deficiency can cripple yields and impede plant development. Magnesium Transporters (MGTs) orchestrate Mg2+ dynamics, with notable variations observed in horticultural species such as Cucumis sativus, Citrullus lanatus, and Citrus sinensis. Furthermore, Mg2+ is key in fortifying plants against environmental stressors and diseases by reinforcing cell walls and spurring the synthesis of defense substances. A burgeoning area of research is the application of magnesium oxide nanoparticles (MgO-NPs), which, owing to their nanoscale size and high reactivity, optimize nutrient uptake, and enhance plant growth and stress resilience. Concurrently, modern breeding techniques provide insights into Mg2+ dynamics to develop crops with improved Mg2+ efficiency and resilience to deficiency. Effective Mg2+ management through soil tests, balanced fertilization, and pH adjustments holds promise for maximizing crop health, productivity, and sustainability. This review unravels the nuanced intricacies of Mg2+ in plant physiology and genetics, and its interplay with external factors, serving as a cornerstone for those keen on harnessing its potential for horticultural excellence.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1a4bfc24-718d-4d8e-99ab-f5519a2cdf50', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'Weed Control in Cabbage, Table Beet and Spinach', 'Kassim Al‐Khatib', 1995, 'Research Exchange (Washington State University)', NULL, 'http://hdl.handle.net/2376/6835', 'http://hdl.handle.net/2376/6835', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b13460bb-afc9-4296-b4d0-e0cad632dd1d', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'RNA Interference Past and Future Applications in Plants', 'Koeppe S, Kawchuk L, Kalischuk M', 2023, 'International journal of molecular sciences', '10.3390/ijms24119755', 'https://doi.org/10.3390/ijms24119755', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10253773.1/PMC10253773.1.pdf', NULL, NULL, 18, NULL, 'canada', 3, 'cc by', 'Antisense RNA was observed to elicit plant disease resistance and post-translational gene silencing (PTGS). The universal mechanism of RNA interference (RNAi) was shown to be induced by double-stranded RNA (dsRNA), an intermediate produced during virus replication. Plant viruses with a single-stranded positive-sense RNA genome have been instrumental in the discovery and characterization of systemic RNA silencing and suppression. An increasing number of applications for RNA silencing have emerged involving the exogenous application of dsRNA through spray-induced gene silencing (SIGS) that provides specificity and environmentally friendly options for crop protection and improvement.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e09ca35-429c-4cf1-978d-60babf77270d', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'THE PATHOGENICITY OF FUSARIUM SPP. TO WHEAT STEM SAWFLY, Cephus cinctus NORTON (HYMENOPTERA: CEPHIDAE)', 'Zhitan Sun', 2008, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/2373', 'https://scholarworks.montana.edu/xmlui/handle/1/2373', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('47faf175-64ce-4350-a074-5005eb713a35', '0b11fb78-9d7f-4f36-9cbf-2b0671987901', 'Genetic diversity and population structure of a core collection of Mediterranean durum wheat accessions using DArTseq markers', 'Laribi M, Ben M''Barek S, Velasco-Cuervo SM, Hwang SF, Yahyaoui AH, Strelkov SE', 2025, 'BMC genomics', '10.1186/s12864-025-12232-2', 'https://doi.org/10.1186/s12864-025-12232-2', 'https://europepmc.org/articles/PMC12751644?pdf=render', NULL, NULL, 22, NULL, 'alberta', 4, 'cc by-nc-nd', 'BACKGROUND: Durum wheat was domesticated in the Fertile Crescent and later spread to the Mediterranean, where human and natural selection led to the establishment of local landraces. Since the 1970s, elite durum wheat varieties largely replaced these landraces. However, landraces continue to play an important role in broadening genetic diversity and contributing valuable traits to modern wheat, particularly in the Mediterranean region, which accounts for 45% of global durum wheat production. This study examined the genetic diversity and population structure of 258 durum wheat genotypes, comprising 125 landraces, 54 breeding lines, 43 cultivars, 34 accessions of uncertain improvement status, and two near-isogenic lines. These genotypes originate primarily from various countries in the Mediterranean basin, including Algeria (39 genotypes), Egypt (3), France (45), Israel (2), Italy (54), Jordan (2), Morocco (2), Portugal (51), Spain (50), Tunisia (6), and Turkey (4). RESULTS: The analysis was conducted using 8,015 single nucleotide polymorphism (SNP) markers and 28,200 SilicoDArT markers. Homoeologous A- and B-genome chromosomes exhibited distinct linkage disequilibrium (LD) decay patterns, confirming genetic differences between the two genomes for both SNP and SilicoDArT markers. SNP analysis identified two subpopulations among the tested accessions: Subpopulation 1 contained 34.11% of the accessions, Subpopulation 2 contained 39.53%, and 26.36% were classified as admixture. Similarly, SilicoDArT markers revealed two subpopulations, with 53.10% of accessions in Subpopulation 1, 27.91% in Subpopulation 2, and 18.99% classified as admixture. For SNP markers, Analysis of Molecular Variance (AMOVA) showed that genetic variation was 12.77% between populations, 74.86% among samples within populations, and 12.77% within samples. Discriminant Analysis of Principal Components (DAPC) identified nine groups. AMOVA based on DAPC population assignments indicated that genetic variation was 25.95% between populations, 61.30% among samples within populations, and 12.76% within samples. DAPC was most effective in distinguishing populations based on either their level of improvement or their geographical origin. CONCLUSIONS: This study highlighted the extent of genetic exchange in durum wheat among Mediterranean countries and further supported two primary dispersal pathways: the northern route (north and east of the Mediterranean basin) and the southern route, including North Africa and the Iberian Peninsula. The analyses demonstrated the efficiency of DArTseq markers in differentiating between genotypes and provided a more comprehensive view of available genetic resources, which can be leveraged in breeding programs to introgress beneficial alleles.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8d064e58-8978-477b-a01c-204764147a63', 'a5544507-eb31-436a-8a0f-062f76b8d396', 'Will buffer zones around schools in agricultural areas be adequate to protect children from the potential adverse effects of pesticide exposure?', 'Gunier RB, Bradman A, Harley KG, Eskenazi B', 2017, 'PLoS biology', '10.1371/journal.pbio.2004741', 'https://doi.org/10.1371/journal.pbio.2004741', 'https://europepmc.org/articles/PMC5739348?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by', 'California has proposed limiting agricultural pesticide use within 0.4 km of schools and childcare facilities. However, the 0.4-km buffer may not be appropriate for all pesticides because of differing toxicities, fate, and application methods. Living near pesticide use has been associated with poorer birth outcomes, neurodevelopment, and respiratory function in children. More research about exposures in schools, childcare facilities, and homes is needed. Despite incomplete science, this regulation is an important step to reduce potential exposures to children. The most vulnerable exposure period may be in utero, and future regulations should also aim to reduce exposures to pregnant women.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0a1aa106-769e-4858-ac0b-5f5c1b4da1dd', '0b11fb78-9d7f-4f36-9cbf-2b0671987901', 'Integrating multitrait physiological approaches to characterize salinity tolerance in bread wheat (Triticum aestivum L.) genotypes', 'Md. Mustafa Khan, Md. Abdul Karim, Md. Moynul Haque, M. A. Baset Mia, Naresh Chandra Deb Barma, Hela Znazen, Ahmed Gaber, Akbar Hossain', 2026, 'BMC Plant Biology', '10.1186/s12870-026-09756-4', 'https://doi.org/10.1186/s12870-026-09756-4', 'https://doi.org/10.1186/s12870-026-09756-4', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Soil salinity is a major constraint to wheat production because it disrupts plant water relations, photosynthesis, oxidative balance and yield formation. Although numerous physiological traits have been investigated individually, integrative approaches for evaluating coordinated physiological responses to salinity remain limited. This study investigated whether multitrait physiological integration could contribute to the characterization of salinity tolerance in the evaluated wheat genotypes using conventional physiological analyses together with cost–benefit slope analysis and the integrated physiological efficiency index (IPEridge). Results Three contrasting bread wheat genotypes [BAW 1147 (tolerant), BARI Gom 25 (moderately tolerant) and BARI Gom 28 (susceptible)] were evaluated under control, 5 and 10 dS m-1 electrical conductivity (EC) of the irrigation solution in a split-plot experiment arranged in a randomized complete block design. Water relations, gas exchange, photosynthetic pigments, compatible solute accumulation, oxidative stress, antioxidant defence and yield-related traits were assessed and physiological coordination was further evaluated using cost–benefit slope analysis and the integrated physiological efficiency index (IPEridge). Salinity (EC) of the irrigation solution reduced plant water status, photosynthetic performance, pigment stability and yield while increasing compatible solute accumulation, oxidative stress indicators and antioxidant enzyme activities. Among the evaluated genotypes, BAW 1147 generally maintained higher relative water content, photosynthetic rate, water use efficiency, chlorophyll content and grain yield, together with lower oxidative damage, than BARI Gom 25 and BARI Gom 28. Correlation analysis suggested stronger coordination among physiological and yield-related traits under saline irrigation conditions than under control conditions. Cost–benefit slope analysis revealed genotype- and irrigation solution EC-dependent differences in the relative contributions of the physiological response modules, whereas IPEridge values were generally higher in the tolerant genotype than in the moderately tolerant and susceptible genotypes. Conclusions The findings suggest that salinity tolerance in the evaluated wheat genotypes was associated with coordinated physiological responses rather than the performance of individual traits alone. The proposed cost–benefit slope analysis and IPEridge index may provide complementary quantitative approaches for characterizing multitrait physiological responses within the present dataset. However, further validation across larger and more diverse wheat populations and environmental conditions is required before their broader applicability can be established.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fb08d540-72cc-4d6f-a1b7-17e85b56aa2b', '0b11fb78-9d7f-4f36-9cbf-2b0671987901', 'Predicting wheat yield and grain quality with UAV multispectral imagery and deep learning', 'Billah MM, Maimaitijiang M, Kaushal S, Millett B, Khan SN, Halder J, Kleinjan J, Sehgal SK', 2026, 'Frontiers in plant science', '10.3389/fpls.2026.1812052', 'https://doi.org/10.3389/fpls.2026.1812052', 'https://europepmc.org/articles/PMC13253798?pdf=render', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc by', 'Bread wheat (Triticum aestivum L.) is a major staple crop, and timely, in-season prediction of grain yield (GY) and grain quality traits, grain protein content (GP), and grain test weight (TW), is critical for informed management and field-based high-throughput phenotyping (HTP). Unmanned Aerial Vehicle (UAV) remote sensing, coupled with artificial intelligence and deep learning (DL), offers a practical pathway for rapid, plot-scale trait estimation. Here, we investigate the value of multitemporal, multispectral UAV imagery for predicting winter wheat GY, GP, and TW, and we systematically compare two modeling paradigms: (1) handcrafted feature-based workflows that use plot-aggregated spectral and texture descriptors derived from UAV imagery, and (2) image-based, end-to-end workflows that learn directly from plot-level reflectance image chips. During the 2022 growing season, multispectral UAV data were collected repeatedly over seven experimental wheat sites in South Dakota, USA. For handcrafted feature-based modeling, we evaluated Support Vector Regression (SVR) and Random Forest Regression (RFR), along with DL models including a feedforward Deep Neural Network (DNN) and a one-dimensional Convolutional Neural Network (1D-CNN). For end-to-end image-based modeling, we implemented 2D-CNN, 3D-CNN, and a hybrid 2D-CNN-LSTM architecture to leverage both spatial information and multi-date dependencies. Our results show that: 1) the image-based modeling workflow yielded comparable to slightly better performance than the handcrafted feature-based modeling workflow across wheat GY, GP, and TW predictions; 2) 3D-CNN outperformed all other methods with R2 of 0.65, 0.61 and 0.69 for GY, GP and TW estimations, respectively; 3) multitemporal UAV data outperformed the data collected from a single growth stage; and UAV data from wheat Feekes 10 (booting) stage yielded slightly better estimation results compared to the data collected from other growing stages, with R2 of 0.62, 0.55, and 0.62 for GY, GP, and TW estimations, respectively. The results indicate that DL applied to high-resolution multitemporal and multispectral UAV imagery holds strong promise for predicting winter wheat yield and grain quality during the growing season, while also informing HTP efforts and site-specific management.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('17ea5e4a-6101-4bed-8fae-fe5c82d9fb7e', '0b11fb78-9d7f-4f36-9cbf-2b0671987901', 'Spatiotemporal responses of the crop water footprint and its associated benchmarks under different irrigation regimes to climate change scenarios in China', 'Z. Yue, Z. Yue, X. Ji, X. Ji, L. Zhuo, L. Zhuo, L. Zhuo, L. Zhuo', 2022, 'Hydrology and Earth System Sciences', '10.5194/hess-26-4637-2022', 'https://doi.org/10.5194/hess-26-4637-2022', 'https://hess.copernicus.org/articles/26/4637/2022/hess-26-4637-2022.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Adaptation to future climate change with limited water resources is a major global challenge to sustainable and sufficient crop production. However, the large-scale responses of the crop water footprint and its associated benchmarks under various irrigation regimes to future climate change scenarios remain unclear. The present study quantified the responses of the maize and wheat water footprint (WF) per unit yield (m3 t−1) as well as the corresponding WF benchmarks under two Representative Concentration Pathway (RCP) scenarios, RCP2.6 and RCP8.5, in the 2030s, 2050s, and 2080s at a 5 arcmin grid level in China. The AquaCrop model with the outputs of six global climate models from Phase 5 of the Coupled Model Intercomparison Project (CMIP5) as its input data was used to simulate the WFs of maize and wheat. The differences among rain-fed wheat and maize and furrow-, micro-, and sprinkler-irrigated wheat and maize were identified. Compared with the baseline year (2013), the maize WF will increase under both RCP2.6 and RCP8.5 (by 17 % and 13 %, respectively) until the 2080s. The wheat WF will increase under RCP2.6 (by 12 % until the 2080s) and decrease (by 12 %) under RCP8.5 until the 2080s, with a higher increase in the wheat yield and a decrease in the wheat WF due to the higher CO2 concentration in 2080s under RCP8.5. The WF will increase the most for rain-fed crops. Relative to rain-fed crops, micro-irrigation and sprinkler irrigation result in the smallest increases in the WF for maize and wheat, respectively. These water-saving management techniques will mitigate the negative impact of climate change more effectively. The WF benchmarks for maize and wheat in the humid zone (an approximate overall average of 680 m3 t−1 for maize and 873 m3 t−1 for wheat at the 20th percentile) are 13 %–32 % higher than those in the arid zone (which experiences an overall average of 601 m3 t−1 for maize and 753 m3 t−1 for wheat). The differences in the WF benchmarks among various irrigation regimes are more significant in the arid zone, where they can be as high as 57 % for the 20th percentile: WF benchmarks of 1020 m3 t−1 for sprinkler-irrigated wheat and 648 m3 t−1 for micro-irrigated wheat. Nevertheless, the WF benchmarks will not respond to climate changes as dramatically as the WF in the same area, especially in areas with limited agricultural development. The present study demonstrated that the observed different responses to climate change in terms of crop water consumption, water use efficiency, and WF benchmarks under different irrigation regimes cannot be ignored. It also lays the foundation for future investigations into the influences of irrigation methods, RCPs, and crop types on the WF and its benchmarks in response to climate change in all agricultural regions worldwide.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44408986-1286-484c-b31b-d1dfc96b4bf1', '2c9fdaa9-f285-4484-ac79-fa71d5d3dc64', 'Best management practices of a solar powered mini-pivot for irrigation of high value crops', 'Evan Derdall', 2008, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-09152008-112229', 'http://hdl.handle.net/10388/etd-09152008-112229', NULL, NULL, 256, NULL, 'prairies', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c12ea20d-71a0-4aa0-a7d1-46cf43ff0af9', '1827eac5-a2ed-4c11-95ed-472d62934515', 'Evaluation of Various Campylobacter-Specific Quantitative PCR (qPCR) Assays for Detection and Enumeration of Campylobacteraceae in Irrigation Water and Wastewater via a Miniaturized Most-Probable-Number-qPCR Assay', 'Banting GS, Braithwaite S, Scott C, Kim J, Jeon B, Ashbolt N, Ruecker N, Tymensen L', 2016, 'Applied and environmental microbiology', '10.1128/aem.00077-16', 'https://doi.org/10.1128/aem.00077-16', 'https://europepmc.org/articles/PMC4984289?pdf=render', NULL, NULL, 14, NULL, 'alberta', 4, 'cc by', 'UnlabelledCampylobacter spp. are the leading cause of bacterial gastroenteritis worldwide, and water is increasingly seen as a risk factor in transmission. Here we describe a most-probable-number (MPN)-quantitative PCR (qPCR) assay in which water samples are centrifuged and aliquoted into microtiter plates and the bacteria are enumerated by qPCR. We observed that commonly used Campylobacter molecular assays produced vastly different detection rates. In irrigation water samples, detection rates varied depending upon the PCR assay and culture method used, as follows: 0% by the de Boer Lv1-16S qPCR assay, 2.5% by the Van Dyke 16S and Jensen glyA qPCR assays, and 75% by the Linton 16S endpoint PCR when cultured at 37°C. Primer/probe specificity was the major confounder, with Arcobacter spp. routinely yielding false-positive results. The primers and PCR conditions described by Van Dyke et al. (M. I. Van Dyke, V. K. Morton, N. L. McLellan, and P. M. Huck, J Appl Microbiol 109:1053-1066, 2010, http://dx.doi.org/10.1111/j.1365-2672.2010.04730.x) proved to be the most sensitive and specific for Campylobacter detection in water. Campylobacter occurrence in irrigation water was found to be very low (ImportanceThe results of this study demonstrate the importance of assay validation upon data interpretation of environmental monitoring for Campylobacter when using molecular biology-based assays. Previous studies describing Campylobacter prevalence in Canada utilized primers that we have determined to be nonspecific due to their cross-amplification of Arcobacter spp. As such, Campylobacter prevalence may have been vastly overestimated in other studies. Additionally, the development of a quantitative assay described in this study will allow accurate determination of Campylobacter concentrations in environmental water samples, allowing more informed decisions to be made about water usage based on quantitative microbial risk assessment.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('99ae39fb-3f56-44aa-9892-015b55719233', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'AgriProfit$ business analysis & research program for Alberta beef producers', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-business-analysis-research-program-for-alberta-beef-producers', 'https://open.alberta.ca/dataset/23d70b34-ff4d-47ac-8fca-cb08daff7f89/resource/796c3f61-e818-4a4d-8076-9cd88625e97a/download/2015-agriprofit-information-bulletin-business-analysis-research-program-alberta-beef-producers.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Describes the purpose and activities of Alberta Agriculture & Rural Development''s AgriProfit$ program. The program regularly publishes a variety of economic and financial benchmarks, tools and applied research materials for agriculture industry clients.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('96722e50-7b1e-42e0-a2bd-d1059562eb93', 'a5544507-eb31-436a-8a0f-062f76b8d396', 'Phytochemicals as alternative fungicides for controlling plant diseases: A comprehensive review of their efficacy, commercial representatives, advantages, challenges for adoption, and possible solutions', 'Deresa EM, Diriba TF', 2023, 'Heliyon', '10.1016/j.heliyon.2023.e13810', 'https://doi.org/10.1016/j.heliyon.2023.e13810', 'https://europepmc.org/articles/PMC9984788?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc-nd', 'Fungal infections are responsible for about 70-80% of the losses in agricultural production brought on by microbial diseases. Synthetic fungicides have been employed to manage plant diseases caused by phytopathogenic fungi but their use has been criticized due to unfavorable side effects. As alternative strategies, botanical fungicides have caught the interest of many researchers in recent years. There are numerous experimental studies on the fungicidal activities of phytochemicals against phytopathogenic fungi, but there is not a thorough review article that summarizes these experimental studies. The purpose of this review is therefore to consolidate data from in vitro and in vivo studies on the antifungal activity of phytochemicals reported by various researchers. This paper describes antifungal activities of plant extracts and compounds against phytopathogenic fungi, approved botanical fungicides, their benefits, obstacles and mitigation strategies. Relevant sources were collected using online data bases such as Google Scholar, PubMed and Science Direct, and comprehensively reviewed for preparation of this manuscript. This review revealed that phytochemicals are effective to manage plant diseases caused by phytopathogenic fungi. Botanical fungicides are endowed with benefits such as resistance inhibition, being ecofriendly, effective, selective, and more affordable compared to synthetic fungicides. However, there are only small number of approved botanical fungicides due to the many challenges that hinder their adoption and utilization for a wider scale production. Farmers'' reluctance, lack of standardized formulation techniques, strict legislation, rapid degradation, and other factors hinder their adoption and utilization. The ways to address these challenges include increasing awareness among farmers, conducting more research to identify potential plants with fungicidal properties, standardizing extraction and formulation techniques, implementing the idea of plant breeding to increase bioactive agents, identifying favorable environments for site-specific plant species production, discovering synthetic analogues of the active ingredient to maintain quality standards, establishing reasonable regulation procedures and price points for a quicker market introduction. To put all these into practice, we recommend collaboration of regulatory agencies and researchers from a variety of fields.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df9475ab-e6dc-49e2-831b-72d792fd62cb', 'a5544507-eb31-436a-8a0f-062f76b8d396', 'Systemic insecticides (neonicotinoids and fipronil): trends, uses, mode of action and metabolites', 'Simon-Delso N, Amaral-Rogers V, Belzunces LP, Bonmatin JM, Chagnon M, Downs C, Furlan L, Gibbons DW', 2015, 'Environmental science and pollution research international', '10.1007/s11356-014-3470-y', 'https://doi.org/10.1007/s11356-014-3470-y', 'https://europepmc.org/articles/PMC4284386?pdf=render', NULL, NULL, 30, NULL, 'other', 1, 'cc by', 'Since their discovery in the late 1980s, neonicotinoid pesticides have become the most widely used class of insecticides worldwide, with large-scale applications ranging from plant protection (crops, vegetables, fruits), veterinary products, and biocides to invertebrate pest control in fish farming. In this review, we address the phenyl-pyrazole fipronil together with neonicotinoids because of similarities in their toxicity, physicochemical profiles, and presence in the environment. Neonicotinoids and fipronil currently account for approximately one third of the world insecticide market; the annual world production of the archetype neonicotinoid, imidacloprid, was estimated to be ca. 20,000 tonnes active substance in 2010. There were several reasons for the initial success of neonicotinoids and fipronil: (1) there was no known pesticide resistance in target pests, mainly because of their recent development, (2) their physicochemical properties included many advantages over previous generations of insecticides (i.e., organophosphates, carbamates, pyrethroids, etc.), and (3) they shared an assumed reduced operator and consumer risk. Due to their systemic nature, they are taken up by the roots or leaves and translocated to all parts of the plant, which, in turn, makes them effectively toxic to herbivorous insects. The toxicity persists for a variable period of time-depending on the plant, its growth stage, and the amount of pesticide applied. A wide variety of applications are available, including the most common prophylactic non-Good Agricultural Practices (GAP) application by seed coating. As a result of their extensive use and physicochemical properties, these substances can be found in all environmental compartments including soil, water, and air. Neonicotinoids and fipronil operate by disrupting neural transmission in the central nervous system of invertebrates. Neonicotinoids mimic the action of neurotransmitters, while fipronil inhibits neuronal receptors. In doing so, they continuously stimulate neurons leading ultimately to death of target invertebrates. Like virtually all insecticides, they can also have lethal and sublethal impacts on non-target organisms, including insect predators and vertebrates. Furthermore, a range of synergistic effects with other stressors have been documented. Here, we review extensively their metabolic pathways, showing how they form both compound-specific and common metabolites which can themselves be toxic. These may result in prolonged toxicity. Considering their wide commercial expansion, mode of action, the systemic properties in plants, persistence and environmental fate, coupled with limited information about the toxicity profiles of these compounds and their metabolites, neonicotinoids and fipronil may entail significant risks to the environment. A global evaluation of the potential collateral effects of their use is therefore timely. The present paper and subsequent chapters in this review of the global literature explore these risks and show a growing body of evidence that persistent, low concentrations of these insecticides pose serious risks of undesirable environmental impacts.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('62dad54a-b763-4ffc-8ffc-0e3617e7338d', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Custom grazing profit$ . . . profit planning tools in Alberta intensive grazing enterprise', 'Government of Alberta', 2002, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agdex-fs420-821-2', 'https://open.alberta.ca/dataset/a12bd4cf-422d-4d70-8f51-ae977f194636/resource/7f5bf478-4a71-4b6a-8847-d8d22ae447bd/download/420-821-2.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet provides economic information on establishing and operating a custom grazing enterprise beef cattle. The information was generated by a group of beef producers who arrived at consensus on investment, production, costs and revenues.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a988448e-820d-41ba-8e4f-61c39b8eee11', '38cd8d1c-5ea7-4769-a015-37060dce6d0c', 'Characterization of the Microbial Resistome in Conventional and "Raised Without Antibiotics" Beef and Dairy Production Systems', 'Rovira P, McAllister T, Lakin SM, Cook SR, Doster E, Noyes NR, Weinroth MD, Yang X', 2019, 'Frontiers in microbiology', '10.3389/fmicb.2019.01980', 'https://doi.org/10.3389/fmicb.2019.01980', 'https://europepmc.org/articles/PMC6736999?pdf=render', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc by', 'Metagenomic investigations have the potential to provide unprecedented insights into microbial ecologies, such as those relating to antimicrobial resistance (AMR). We characterized the microbial resistome in livestock operations raising cattle conventionally (CONV) or without antibiotic exposures (RWA) using shotgun metagenomics. Samples of feces, wastewater from catchment basins, and soil where wastewater was applied were collected from CONV and RWA feedlot and dairy farms. After DNA extraction and sequencing, shotgun metagenomic reads were aligned to reference databases for identification of bacteria (Kraken) and antibiotic resistance genes (ARGs) accessions (MEGARes). Differences in microbial resistomes were found across farms with different production practices (CONV vs. RWA), types of cattle (beef vs. dairy), and types of sample (feces vs. wastewater vs. soil). Feces had the greatest number of ARGs per sample (mean = 118 and 79 in CONV and RWA, respectively), with tetracycline efflux pumps, macrolide phosphotransferases, and aminoglycoside nucleotidyltransferases mechanisms of resistance more abundant in CONV than in RWA feces. Tetracycline and macrolide-lincosamide-streptogramin classes of resistance were more abundant in feedlot cattle than in dairy cow feces, whereas the β-lactam class was more abundant in dairy cow feces. Lack of congruence between ARGs and microbial communities (procrustes analysis) suggested that other factors (e.g., location of farms, cattle source, management practices, diet, horizontal ARGs transfer, and co-selection of resistance), in addition to antimicrobial use, could have impacted resistome profiles. For that reason, we could not establish a cause-effect relationship between antimicrobial use and AMR, although ARGs in feces and effluents were associated with drug classes used to treat animals according to farms'' records (tetracyclines and macrolides in feedlots, β-lactams in dairies), whereas ARGs in soil were dominated by multidrug resistance. Characterization of the "resistance potential" of animal-derived and environmental samples is the first step toward incorporating metagenomic approaches into AMR surveillance in agricultural systems. Further research is needed to assess the public-health risk associated with different microbial resistomes.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4d93f361-19bc-4f45-9d84-38d1ab63cf18', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Assessment of Brix refractometry to estimate immunoglobulin G concentration in beef cow colostrum', 'Gamsjäger L, Elsohaby I, Pearson JM, Levy M, Pajor EA, Haines DM, Windeyer MC', 2020, 'Journal of veterinary internal medicine', '10.1111/jvim.15805', 'https://doi.org/10.1111/jvim.15805', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7379009.1/PMC7379009.1.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'cc by-nc', 'BackgroundBrix refractometry can be used to assess colostral immunoglobulin G (IgG) concentration, but studies identifying Brix percentages to detect high- and low-IgG colostrum are lacking for beef cows and interlaboratory agreement is unknown.ObjectivesEvaluate Brix refractometer performance and interlaboratory agreement for assessing beef cow colostrum IgG concentration, including determination of thresholds to identify colostrum containing IgG concentrations AnimalsBeef cows (n = 416) from 11 cow-calf operations in Alberta, Canada.MethodsColostral IgG concentrations were measured using radial immunodiffusion (RID) and estimated by Brix refractometry for this retrospective study. Spearman correlation coefficients were assessed between RID and Brix refractometry. Likelihood ratios and misclassification cost-term analysis were used to determine optimal Brix percentages for detecting colostrum containing IgG concentrations ResultsBrix percentages obtained at 3 laboratories were positively correlated with IgG results (r = 0.72, 0.68, and 0.76, respectively). Colostrum Brix percentages of Conclusions and clinical importanceBrix refractometry shows good potential for reliably estimating IgG concentrations in beef cow colostrum across multiple laboratories and can be recommended to aid colostrum management decisions on farms.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0b268ae3-2174-4d86-ab2b-24c9518708e1', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Associations between prebreeding serum micronutrient concentrations and pregnancy outcome in beef cows', 'Leanne M Van De Weyer, S. Hendrick, Cheryl Waldner', 2011, 'Journal of the American Veterinary Medical Association', '10.2460/javma.238.10.1323', 'https://doi.org/10.2460/javma.238.10.1323', 'https://avmajournals.avma.org/downloadpdf/journals/javma/238/10/javma.238.10.1323.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e0fe44e4-0a53-42ba-be68-0ff1c3ef119d', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Identifying performance benchmarks and determinants for reproductive performance and calf survival using a longitudinal field study of cow-calf herds in western Canada', 'Waldner CL, Parker S, Campbell JR', 2019, 'PloS one', '10.1371/journal.pone.0219901', 'https://doi.org/10.1371/journal.pone.0219901', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6662034.1/PMC6662034.1.pdf', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'The cow-calf industry in North America is in a period of rapid consolidation with corresponding increases in herd sizes and changes in management. The objectives of this study were to examine longitudinal data on reproductive performance in cow-calf herds and identify benchmarks for the most critical measures and important sources of differences among herds. To address these questions, a surveillance network was established in western Canada to collect data between 2013 to 2017 privately owned cow-calf herds during calving (n = 105 herds) and at pregnancy testing (n = 94 herds). Data were summarized for a number of indices of herd performance. However, the values considered to be most reliable and accurate were the percentage of females not pregnant when tested by a veterinarian, the percentage of calves dead within 24 hours of birth, and the percentage of calves dead from 24 hours to weaning. The mean and variation between herds for heifers, measured using standard deviation, was greater than for cows for: non-pregnancy (cows 6.8% (mean)±3.4%(SD), heifers 9.7%±8.2%), calf death from birth to 24 hours (cows 2.1%±1.6%, heifers 3.6%±4.5%), and calf death from 24 hours to weaning (cows 2.5%±2.4%, heifers 2.9%±3.9%). Benchmarks or performance targets derived from the 25th percentiles of these data for both cows and heifers were <5% for non-pregnancy risk and <1% for calf loss within 24 hours of birth. The suggested benchmark for calf loss from 24 hours to weaning was <2% for cows and <1% for heifers. All outcomes consistently displayed greater variation between herds as compared to year to year differences within herds with the exception of calf loss before 24 hours in cows. The timing of the start of breeding season was a consistent source of variation in risks of non-pregnancy and calf losses. Cows bred in April or earlier to start calving in late December or January were at increased risk of low pregnancy percentages (p<0.001) and calf losses at birth (p<0.04), as well as increased calf loss before weaning in both cows and heifers (p<0.02). There was also an increase in the risk of non-pregnancy for cows and heifers (p<0.001) where first exposure to breeding was not until July or August. In contrast, the risks of calf loss within 24 hrs of birth (p<0.001) and from 24 hrs to weaning in cows (p<0.02) first exposed to breeding in July and August were significantly lower than for herds that had earlier breeding seasons.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b8a224e4-e61f-4ccd-b787-d779da3a317f', '38cd8d1c-5ea7-4769-a015-37060dce6d0c', 'Linking remote sensing with crop modeling for yield and nitrate leaching predictions in Minnesota', 'Tahir M, Mulla DJ', 2026, 'Journal of environmental quality', '10.1002/jeq2.70137', 'https://doi.org/10.1002/jeq2.70137', 'https://europepmc.org/articles/PMC12789989?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'Upscaling crop yield and nitrate-N leaching loss from experimental sites to large areas under alternative crop rotations is crucial for assessing strategies and setting goals to protect groundwater quality at a regional scale. Nitrogen (N) rate field trials were used to calibrate the Environmental Policy Integrated Climate (EPIC) model for continuous-corn (Zea mays L.) (C-C), corn-soybean (Glycine max L.) (C-Sb), and alfalfa (Medicago sativa L.)-corn (A-C), with or without rye (Secale cereale L.) cover crop. Satellite estimates of crop evapotranspiration (ETc) were used to upscale the EPIC model for crop yield and nitrate-N leaching, using the irrigation-water permitting data from 2010 to 2017 for 13,375 ha of sandy soils in Bonanza Valley, central Minnesota. Four alternative management scenarios were evaluated with EPIC: (1) reducing N fertilizer rate from the maximum return to N value (MRTN) (of 0.05 to a value of 0.1 (for the N price/crop value ratio), (2) adding rye cover crop at MRTN of 0.1, (3) irrigating with EPIC auto-trigger in scenario 2, and (4) converting 50% of C-C acreage in scenario 3 to A-C. Nash-Sutcliffe coefficients, normalized root-mean-square error, and R2 values based on ETc/crop yield for calibration and validation of the EPIC model ranged 0.95-0.54, 4.67-19.4, and 0.96-0.74; and 0.74-0.41, 7.99-23.4, and 0.88-0.55, respectively. Results indicate that corn yield at MRTN of 0.05 averaged 12.5, 13.2, and 13.4 t ha-1 under C-C, C-Sb, and A-C rotations, while yields at MRTN of 0.1 were reduced by 4.1%, 3.5%, and 3.3%, respectively. The baseline scenario of C-C, C-Sb, and A-C rotations at MRTN of 0.05 had annual nitrate-N leaching losses of 51.8, 45.5, and 31.4 kg ha-1, while MRTN of 0.1 reduced these losses by 9.1%, 5.0%, and 3.8%, respectively. Rye after corn and soybean reduced nitrate-N leaching losses in the MRTN of 0.1 scenario by 5.8% and 13.6%, respectively. EPIC auto-irrigation of corn, soybean, and alfalfa at MRTN of 0.1 reduced nitrate-N leaching losses with rye (relative to conventional irrigation) by 9.6%, 9.1%, and 8.5%, respectively. Further, replacing half of the C-C acreage with A-C rotation would provide a 6.1% reduction, resulting in a total reduction of 27.4% in nitrate-N leaching to groundwater when all alternative practices are combined. Overall, augmenting EPIC model with field-observed ancillary data and remote sensing successfully predicted the yield and NO3-N leaching losses under different crop rotations, indicating opportunities to upscale field-scale agroecosystem simulations, particularly if used to calculate NO3-N leaching on a long-term basis at the regional scales.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6056b663-29c3-450d-9601-de45504b4714', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', '13 Effects of an acclimation protocol during the handling events of the 7 d CO-synch + CIDR protocol on temperament and reproductive performance of Bos taurus commercial beef heifers', 'Nicholas W Wege Dias, Sydney H. Tastad, Joao Victor Chaves Silva, Santiago Paez Hurtado, Andréia Ferreira Machado, Victor Gomez-León, John R. Jaeger, Nicola Oosthuizen', 2024, 'Journal of Animal Science', '10.1093/jas/skae019.065', 'https://doi.org/10.1093/jas/skae019.065', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10908452/pdf/skae019.065.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb2b3c34-8655-4ce4-a0fc-3f99141ee91c', '2c9fdaa9-f285-4484-ac79-fa71d5d3dc64', 'Case study : using a VFD pump with a corner arm centre pivot', 'Government of Alberta', 2013, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/case-study-using-a-vfd-pump', 'https://open.alberta.ca/dataset/21cdb4a9-cc4c-477d-a1cc-c19f8e5c13cb/resource/e4038cc0-5f6b-43f8-a18f-153df3900215/download/af-case-study-vfd-pump-corner-arm-centre-pivot.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Investigates the potential energy savings that could be attained for an irrigation system by using a variable frequency drive on irrigation pumps.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b97bf9b9-9f5a-4b88-83e2-e1edf23714e8', '2c9fdaa9-f285-4484-ac79-fa71d5d3dc64', 'Police seizure of drugs without arrest among people who use drugs in Vancouver, Canada, before provincial ‘decriminalization’ of simple possession: a cohort study', 'Kanna Hayashi, Tyson Singh Kelsall, Caitlin Shane, Zishan Cui, Vancouver Area Network of Drug Users, M.-J. Milloy, Kora DeBeck, Thomas Kerr', 2023, 'Harm Reduction Journal', '10.1186/s12954-023-00833-7', 'https://doi.org/10.1186/s12954-023-00833-7', 'https://doi.org/10.1186/s12954-023-00833-7', NULL, NULL, NULL, NULL, 'canada', 3, 'open access (DOAJ)', 'Abstract Background Several jurisdictions in Canada have recently considered decriminalizing possession of illicit drugs for personal use (henceforth, simple possession) as part of their responses to the ongoing drug toxicity/overdose crisis. In this context, we sought to examine an early implementation case of a de facto depenalization policy of simple possession offences in Vancouver, Canada, that was enacted in 2006. Specifically, we characterized experiences of people who use drugs (PWUD) whose drugs were discretionally seized by police without arrest. Methods Data were derived from three prospective cohorts of community-recruited PWUD in Vancouver over 16 months in 2019–2021. We conducted multivariable generalized estimating equations analyses to determine the prevalence of and factors associated with drug seizure. Sub-analyses used data collected in 2009–2012 and examined the trends over time. Results Among 995 participants who were interviewed in 2019–2021, 63 (6.3%) had their drugs seized by police at least once in the past 6 months. In multivariable analyses, factors significantly associated with drug seizure included: homelessness (adjusted odds ratio [AOR]: 1.98; 95% confidence interval [CI] 1.09–3.61), working in the unregulated drug market (AOR: 4.93; 95% CI 2.87–8.49), and naloxone administration (AOR: 2.15; 95% CI 1.23–3.76). In 2009–2012, 67.8% reported having obtained new drugs immediately after having their drugs seized by police. Odds of drug seizure were not significantly different between the two time periods (2019–2021 vs. 2009–2012) (AOR: 0.93; 95% CI: 0.64–1.35). Conclusions Despite the depenalization policy, the Vancouver Police Department has continued to seize illicit drugs from PWUD, even in cases where no arrest occurred. This policing practice may create health and safety risks for PWUD as it forces PWUD to increase the engagement with the unregulated illicit drug market. Our findings support calls for abolishing this often-undocumented discretionary policing practice that may exacerbate ongoing health inequities and interfere with peer-based overdose prevention efforts.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a5ce0541-c27c-4cfb-963f-33d6fcfa9f94', '1ac6f7be-9352-4aed-a714-2590e193c83f', 'A bibliometric and visualization analysis of global research on saline-alkali soil microbiology', 'PEI Xiangli, XU Zhenghe, LIU Miao, XU Jing, XU Lirong, CONG Xin', 2026, 'Guan''gai paishui xuebao', '10.13522/j.cnki.ggps.2025242', 'https://doi.org/10.13522/j.cnki.ggps.2025242', 'https://www.ggpsxb.com/jgpxxb/ch/reader/create_pdf.aspx?file_no=20260311&year_id=2026&quarter_id=3&falg=1', NULL, NULL, NULL, NULL, 'canada', 3, 'open access (DOAJ)', '【Background and Objective】Soil salinization is a major constraint to sustainable agricultural production, and amending such soils with salt-tolerant microorganisms has been found to be effective in improving soil quality and enhancing crop tolerance to water and salinity stress. This paper analyzes international research in this area.【Method】Bibliometric analysis was conducted using VOSviewer and CiteSpace to systematically examine publications from 2004 to 2024 on saline-alkali soil microbiology retrieved from the China National Knowledge Infrastructure (CNKI, 652 articles) and the Web of Science Core Collection (WOS, 982 articles).【Result】Annual publications in saline–alkali soil microbiology showed a substantial increase during this period, with publications in English journals consistently and markedly overshadowing those in Chinese journals. China led the world, publishing 1 103 papers and collaborating with 26 countries, including Canada and the United Kingdom. Keyword clustering analysis showed that research hotspots in this field were: ①microbial community structure and its environmental drivers; ②mechanisms underlying plant-microbe interactions and their ecological functions; and ③ screening of salt-tolerant and growth-promoting microorganisms, as well as the mechanisms underlying biological remediation of saline-alkali soils. From 2004 to 2024, research on microbiology in saline-alkali soil can be divided into three stages: an early stage (2004—2015) emphasizing species identification and soil improvement; a middle stage (2016—2020) focusing on microbial community ecology and functional characterization; and the most recent stage (2021—2024) characterized by increased attention to the regulation of the microbe-soil-plant system.【Conclusion】Future research in saline-alkali soil microbiology will depend on international collaboration and interdisciplinary cooperation. Advances in multi-omics approaches, big data and artificial intelligence will enable systematic elucidation of microbial community assembly and functional regulation mechanisms, which will promote precision microbial management, functional strain development, and microbiome restoration. These advances will provide environmentally friendly solutions for remediating saline-alkali soils and sustaining agricultural production to meet the growing demand for food.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('973d3656-08b8-4f93-82c7-984f28d16bc7', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Cattle and Pigs Are Easy to Move and Handle Will Have Less Preslaughter Stress', 'Grandin, Temple', 2021, 'Foods 10(11):2583 (MDPI)', '10.3390/foods10112583', 'https://doi.org/10.3390/foods10112583', 'https://mdpi-res.com/d_attachment/foods/foods-10-02583/article_deploy/foods-10-02583.pdf', NULL, NULL, 8, NULL, 'other', 3, 'CC-BY 4.0', 'A short open-access review arguing that ease of movement at the facility is itself a welfare and meat-quality indicator. It names the distraction set - sharp shadows on the floor, reflections on shiny metal, a noisy vehicle near the lairage, air blowing out through the stun-box entrance toward approaching cattle - citing Willson et al. 2021, Grandin 2001 and Grandin 1996, and reports that illuminating a dark restrainer entrance facilitated cattle movement. Its most informative feature for this project is an absence: checked specifically, it contains no curved-versus-straight race content and no solid-sides content at all, which is itself evidence of how thin that part of the evidence base is in the author''s own most recent work.', '{behaviour,review,distractions,shadows,reflections,air-flow,lighting,no-curve-evidence,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd6b608a-93da-459a-926d-64507ddf0aa0', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'A critical review of fear tests used on cattle, pigs, sheep, poultry and horses', 'Forkman, Björn; Boissy, Alain; Meunier-Salaün, Marie-Christine; Canali, Elisabetta; Jones, R. Bryan', 2007, 'Physiology & Behavior 92(3):340-374', '10.1016/j.physbeh.2007.03.016', 'https://hal.inrae.fr/hal-02667943', 'https://hal.inrae.fr/hal-02667943/document', NULL, NULL, 36, NULL, 'other', 4, 'green open access repository copy (HAL INRAE); publisher version Elsevier', 'A systematic critical review of the fear-test literature across farm species, with species-by-species tables of test type, measures recorded and correlations. It establishes the taxonomy needed before reading any flight-zone claim: the Forced Approach Test, in which the human approaches and which is what flight distance measures, versus the Voluntary Approach Test, in which the animal is free to approach. Quoting Waiblinger et al., it warns that the forced approach test ''would probably increase the likelihood that an animal will respond more actively to the human whereas in the voluntary approach test, the chances of getting no response or a passive response would probably be higher'', and that researchers ''tend to use forced vs. voluntary approach tests uncritically''. It also records the Hargreaves and Hutson finding that gentling reduced sheep flight distance and heart rate yet failed to reduce aversion to shearing - the reason a small flight zone must not be read as a welfare pass.', '{behaviour,flight-distance-methodology,FAT-vs-VAT,fear-tests,review,measurement-validity}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('58816fa7-4a39-43b8-85e6-b93529b572e4', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'A Novel Method of Assessing Floor Friction in Cowsheds and Its Association with Cow Health', 'Sharma, Arvind; Kennedy, Uttara; Phillips, Clive J. C.', 2019, 'Animals 9(4):120 (MDPI)', '10.3390/ani9040120', 'https://doi.org/10.3390/ani9040120', 'https://mdpi-res.com/d_attachment/animals/animals-09-00120/article_deploy/animals-09-00120.pdf', NULL, NULL, 17, NULL, 'other', 4, 'CC-BY 4.0', 'A field-usable friction test applied across 54 cattle housing and yard facilities (earth, brick, concrete, stone) with 30 animals assessed per facility. Coefficient of friction ranged from 0.3 to 0.7, lowest on concrete and highest on earth. Higher-friction floors were associated with cows standing more and - the finding that matters most for a handling facility - being easier to approach, as well as with fewer cows having dirty hind limbs. That approachability result is the only direct behavioural link found between measured footing friction and handling, and it supports treating traction as a handling variable rather than only a lameness one. Useful alongside van der Tol et al.''s required-coefficient-of-friction concept, which establishes that concrete fails to supply enough friction during sudden stops and starts.', '{behaviour,flooring,coefficient-of-friction,traction,approachability,field-method,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e07453bd-32f6-49e1-a577-3d63174c170e', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'A Novel Protocol to Assess Acclimation Rate in Bos taurus Heifers during Yard Weaning', 'Monk, Jessica E.; Hine, Brad C.; Colditz, Ian G.; Lee, Caroline', 2018, 'Animals 8(4):51 (MDPI)', '10.3390/ani8040051', 'https://doi.org/10.3390/ani8040051', 'https://rune.une.edu.au/bitstreams/1bacfd67-7071-425c-afbd-bd440bbefcda/download', NULL, NULL, 15, NULL, 'other', 4, 'CC-BY 4.0', 'CSIRO work proposing that repeated flight-time measurement during yard weaning quantifies an animal''s acclimation rate - how quickly it habituates to handling in a given facility - rather than a static temperament score. This shifts the question from ''is this animal flighty?'' to ''does this yard let cattle settle?'', which is the question a corral designer actually wants answered. Directly applicable to a cow-calf operation''s weaning pens, where cattle meet the facility only a handful of times a year, and the right construct to pair with Lockwood et al. 2015''s finding that exit velocity falls 40% over four handlings while pen score barely moves.', '{behaviour,flight-time,acclimation-rate,yard-weaning,cow-calf,habituation,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f4d72c30-d569-4fe7-ad1b-561c17141340', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Adrenergic Tone as an Intermediary in the Temperament Syndrome Associated With Flight Speed in Beef Cattle', 'Ian G. Colditz', 2021, 'Frontiers in Animal Science', '10.3389/fanim.2021.652306', 'https://doi.org/10.3389/fanim.2021.652306', 'https://www.frontiersin.org/articles/10.3389/fanim.2021.652306/pdf', NULL, NULL, 22, NULL, 'other', 1, 'cc-by', 'The temperament of farm animals can influence their resilience to everyday variations within the managed production environment and has been under strong direct and indirect selection during the course of domestication. A prominent objective measure used for assessing temperament in beef cattle is the behavioral flight response to release from confinement in a crush or chute. This behavioral measure, termed flight speed (also known as escape velocity) is associated with physiological processes including body temperature, feeding behavior, growth rate, carcass composition, immune function, and health outcomes. This review examines the functional links between this suite of traits and adrenergic activity of the sympathetic nervous system and the adrenomedullary hormonal system. It is suggested that flight speed is the behavioral aspect of an underlying “flightiness” temperament syndrome, and that elevated adrenergic tone in animals with a high level of flightiness (i.e., flighty animals) tunes physiological activities toward a sustained “fight or flight” defense profile that reduces productivity and the capacity to flourish within the production environment. Nonetheless, despite a common influence of adrenergic tone on this suite of traits, variation in each trait is also influenced by other regulatory pathways and by the capacity of tissues to respond to a range of modulators in addition to adrenergic stimuli. It is suggested that tuning by adrenergic tone is an example of homeorhetic regulation that can help account for the persistent expression of behavioral and somatic traits associated with the flight speed temperament syndrome across the life of the animal. At a population level, temperament may modulate ecological fit within and across generations in the face of environmental variability and change. Associations of flight speed with the psychological affective state of the animal, and implications for welfare are also considered. The review will help advance understanding of the developmental biology and physiological regulation of temperament syndromes.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37ecdfa2-03d5-457c-a3d6-4b7bd4e9cf20', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Trifloxystrobin-triggered Drp1 hyperactivation biases mitophagy and imposes long-lasting SVCV susceptibility in teleost', 'Huan Wang, Yang Hu, Lei Liu, Jiong Chen', 2026, 'Journal of Virology', '10.1128/jvi.00445-26', 'https://doi.org/10.1128/jvi.00445-26', 'https://journals.asm.org/doi/10.1128/jvi.00445-26', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT Environmental pollutants are increasingly recognized as disease modifiers, reshaping host homeostasis and shifting host-pathogen dynamics toward higher infection risk in aquatic ecosystems. Here, we show that the widely used strobilurin fungicide trifloxystrobin (TFS) persistently erodes antiviral competence in fish and increases susceptibility to spring viremia of carp virus (SVCV) by driving dynamin-related protein 1 (Drp1)-mediated excessive mitophagy and sustained mitochondrial dysfunction. Using epithelioma papulosum cyprini (EPC) cells and zebrafish as complementary models, we find that environmentally plausible TFS exposures (2.5–25 μg/L) elevate SVCV permissiveness; notably, this phenotype resolves incompletely after chemical withdrawal. Transcriptomics revealed a dose-concordant shift toward stress/innate immune signaling and mitophagy programs, alongside broad repression of proliferative and DNA-repair pathways. Consistently, TFS induces persistent mitochondrial membrane depolarization, promotes fragmentation and ultrastructural deterioration, and increases mitochondria–lysosome coupling. Mechanistically, TFS elevates Drp1 abundance and Ser616 phosphorylation, promotes Drp1 recruitment to mitochondria, and sustains microtubule-associated protein 1 light chain 3B (LC3B)/lysosomal-associated membrane protein 2 (LAMP2) engagement, accompanied by persistent induction of core autophagy regulators (gabarap, atg5, wipi1, and ambra1) across extended recovery windows. In vivo, prolonged TFS exposure similarly yields durable enhancement of SVCV susceptibility even after long recovery periods, indicating incomplete restoration of host resistance. Together, these findings link a major agricultural fungicide to persistent Drp1-driven mitophagy overactivation and identify long-term antiviral resistance as an ecologically relevant endpoint for pesticide risk assessment and aquatic disease forecasting.IMPORTANCEViral diseases pose a significant challenge to sustainable aquaculture, and effective antiviral interventions remain limited. In this study, we reveal that trifloxystrobin, a widely used fungicide, induces mitochondrial dysfunction and Drp1-mediated excessive mitophagy, leading to long-term suppression of antiviral immune responses in fish. Importantly, this work identifies mitochondrial dynamics as a key determinant of viral susceptibility and demonstrates how environmental pollutants can reshape host-pathogen interactions. By linking mitophagy and Drp1 activation to increased spring viremia of carp virus susceptibility, our findings provide a novel perspective on how pollutants may exacerbate viral infections in aquaculture species. This work underscores the urgent need for ecosystem-based antiviral strategies and offers a mechanistic framework for assessing ecological risks posed by common agricultural chemicals, thereby informing environmental and disease management in aquaculture.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1b57715c-5986-41d5-b28b-d5cc3b5341ea', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Antimicrobial Sensitivity Testing of Mycoplasma bovis Isolates Derived from Western Canadian Feedlot Cattle', 'Jelinski M, Kinnear A, Gesy K, Andrés-Lasheras S, Zaheer R, Weese S, McAllister TA', 2020, 'Microorganisms', '10.3390/microorganisms8010124', 'https://doi.org/10.3390/microorganisms8010124', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7022776.1/PMC7022776.1.pdf', NULL, NULL, 23, NULL, 'prairies', 4, 'cc by', 'Mycoplasma bovis is particularly adept at evading the immune system, resulting in chronic infections of the lungs and joints of feedlot cattle. The chronicity of the lesions results in prolonged antimicrobial therapy, possibly exacerbating antimicrobial resistance. This cross-sectional study generated in vitro antimicrobial susceptibility testing (AST) data on 211 M. bovis isolates recovered from 159 healthy, diseased, and dead cattle, spanning the period of 2006-2018. Nine antimicrobials commonly administered to western Canadian feedlot cattle were assessed. The data were analyzed with non-parametric statistical tests with a level of significance of p p ≥ 0.124) and the lungs and deep nasal passages (p ≥ 0.157) of the same animals.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce256911-4b0f-46be-b317-a9bb4c73da0a', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Assessing cow-calf welfare. Part 2: Risk factors for beef cow health and behavior and stockperson handling', 'Simon, G. E.; Hoar, B. R.; Tucker, Cassandra B.', 2016, 'Journal of Animal Science 94(8):3488-3500', '10.2527/jas.2016-0309', 'https://academic.oup.com/jas/article/94/8/3488/4704287', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown (paywalled; no verifiable free copy located)', 'The most transferable on-farm dataset for a cow-calf operation, and the paper whose effect sizes should lead any outcome log the app builds. 30 California cow-calf ranches, with per-animal scoring of health, behaviour and stockperson actions analysed with mixed models for risk factors. Prodding an individual cow with an electric prod raised her odds of balking (odds ratio 11.0) and of vocalising (odds ratio 3.3), plus several stumbling and falling outcomes. Using a moving aid on a cow raised balking risk markedly (odds ratio 34.1), while moving cattle with hands across the herd lowered balking risk (odds ratio 0.3). The authors conclude that reducing electric-prod use is the key available handling improvement. It is cross-sectional, so these are associations rather than demonstrated causes, and facility-design variables are not separated from stockperson behaviour - but the effect sizes dwarf anything attributable to geometry anywhere in this review. Part 1 (Journal of Animal Science 94:3476-3487) benchmarks cow health, behaviour during handling, facilities and producer perspectives across the same ranches.', '{behaviour,cow-calf,on-farm,balking-odds-ratio,electric-prod,moving-aid,risk-factors,north-american,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('588414c4-c477-4a31-9167-5da20f97a0cd', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Assessment of stress during handling and transport', 'Grandin, Temple', 1997, 'Journal of Animal Science 75(1):249-257', '10.2527/1997.751249x', 'https://www.grandin.com/references/handle.stress.html', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'free-to-read author-hosted HTML at grandin.com (journal version paywalled)', 'The reference table of cortisol values for cattle handling, which is what lets a designer say whether a layout fault costs anything physiological. Baselines 0.5-9 ng/mL; headgate restraint 13 (hand-reared Holsteins, Lay et al. 1992a) to 63 (Mitchell et al. 1988); Angus by Hereford steers 28 versus Angus by Brahman steers 36 (Zavy et al. 1992); weanlings tested two weeks after weaning 24 versus on weaning day 46 (Crookshank et al. 1979, a measured weaning-day stress penalty); inversion onto the back for 103 s 93; electric prod on all cattle before stunning 63 median, with 38% of those cattle slipping (Cockram and Corley 1991). Grandin''s working guideline is that means above 70 ng/mL in steers or cows indicate rough handling or poor equipment, and that cortisol takes 10-20 minutes to peak. It also catalogues the habituation failures that matter most to a layout checker: Fell and Shutt 1986 found cortisol did not decline over repeated truck trips in which cattle fell down; Hargreaves and Hutson 1990 found no habituation to repeated sham shearing; Grandin et al. 1994 found that cattle hit hard by a headgate were more likely to resist entering the chute later - a single hardware fault producing durable avoidance; and Stookey et al. 1994 found cattle were less agitated when another animal was within 1 m in the chute. Notably this peer-reviewed review gives no flight-zone size and no point of balance at all.', '{behaviour,cortisol,habituation-failure,headgate,slipping,thresholds,review,companion-within-1m,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d941ff45-914b-4b14-9a1a-61d61c05ae12', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Association of Temperament and Acute Stress Responsiveness with Productivity, Feed Efficiency, and Methane Emissions in Beef Cattle: An Observational Study', 'Llonch P, Somarriba M, Duthie CA, Haskell MJ, Rooke JA, Troy S, Roehe R, Turner SP', 2016, 'Frontiers in veterinary science', '10.3389/fvets.2016.00043', 'https://doi.org/10.3389/fvets.2016.00043', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC4904008.1/PMC4904008.1.pdf', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'The aim of this study was to assess individual differences in temperament and stress response and quantify their impact on feed efficiency, performance, and methane (CH4) emissions in beef cattle. Eighty-four steers (castrated males) (Charolais or Luing) were used. Temperament was assessed using two standardized tests: restlessness when restrained [crush score (CS)] and flight speed (FS) on release from restraint. Over a 56-day period individual animal dry matter intake (DMI) and weekly body weight was measured. Ultrasound fat depth was measured at the end of 56 days. Average daily gain (ADG), feed conversion ratio (FCR), and residual feed intake (RFI) were calculated. After the 56-day test period, animals were transported in groups of six/week to respiration chamber facilities. Blood samples were taken before and 0, 3, 6, and 9 h after transport. Plasma cortisol, creatine kinase (CK), glucose, and free fatty acids (FFA) were determined to assess physiological stress response. Subsequently, CH4 emissions were measured over a 3-day period in individual respiration chambers. CS (1.7 ± 0.09) and FS (1.6 ± 0.60 m/s) were repeatable (0.63 and 0.51, respectively) and correlated (r = 0.36, P < 0.001). Plasma cortisol, CK, and FFA concentrations increased after transport (P = 0.038, P = 0.006, and P < 0.001, respectively). Temperament (CS) and CK concentration were correlated (r = 0.29; P = 0.015). The extreme group analysis reveals that excitable animals (FS; P = 0.032) and higher stress response (cortisol, P = 0.007; FFA, P = 0.007; and CK, P = 0.003) were associated with lower DMI. ADG was lower in more temperamental animals (CS, P = 0.097, and FS, P = 0.030). Fat depth was greater in steers showing calmer CS (P = 0.026) and lower plasma CK (P = 0.058). Temperament did not show any relationship with RFI or CH4 emissions. However, steers with higher cortisol showed improved feed efficiency (lower FCR and RFI) (P < 0.05) and greater CH4 emissions (P = 0.017). In conclusion, agitated temperament and higher stress responsiveness is detrimental to productivity. A greater stress response is associated with a reduction in feed intake that may both increase the efficiency of consumed feed and the ratio of CH4 emissions/unit of feed. Therefore, temperament and stress response should be considered when designing strategies to improve efficiency and mitigate CH4 emissions in beef cattle.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc255e93-d633-42a0-a13d-b88e703b4119', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Attenuation of Stress Responses to Human Handling Through Habituation in Goats', 'Tharun Tej Erukulla, Phaneendra Batchu, Priyanka Gurrapu, Arshad Shaik, Thomas H Terrill, Govind Kannan', 2025, 'Animals', '10.3390/ani15101385', 'https://doi.org/10.3390/ani15101385', 'https://www.mdpi.com/2076-2615/15/10/1385/pdf?version=1746880386', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Goats raised on pastures are seldom handled except for purposes such as weighing and providing veterinary care. Regular positive interactions with human caretakers have been reported to attenuate fear and stress responses to routine human handling; however, this has not been adequately studied in meat goats. This experiment was conducted to determine the effects of habituation to handling on behavioral, physiological, and metabolomic responses in goats when subjected to routine handling. Seventy-two male (uncastrated) Spanish goats (6 mo; BW = 25.2 ± 0.37 kg) were randomly allocated to one of two treatment (Trt) groups: (i) regularly handled by stroking the back of each goat before feeding time for 90 days (handled: H) or (ii) not subjected to handling during the same period, but all other conditions were the same (non-handled: NH). After the 90-day habituation period, the goats were subjected to an arena test in the presence of an observer. Immediately after the test, the goats were subjected to routine veterinary exams that involved blood sampling (0 min) and measuring heart rate (HR), respiratory rate (RR), rectal temperature (RT), and body weight (BW). Blood samples were also collected after the veterinary exam (20 min) to determine physiological and metabolomic responses. Data from the arena test were analyzed using a Mann–Whitney U Test, and blood physiological responses were analyzed using MIXED procedures in SAS with sampling time (Time) as a repeated measure. Unpaired t-tests showed that the increase in BW was higher in the H goats (p < 0.01) compared to the NH goats over the 90 d habituation period. The approach distance from the observer (p < 0.05) and frequency of urination (p < 0.05) were greater in the NH goats during the arena test. HR (p < 0.01) and RR (p < 0.01) were higher in the NH group compared to the H group. Plasma cortisol concentrations were higher at 20 min than at 0 min (p < 0.05), while epinephrine (p < 0.05), metanephrine, normetanephrine, phenylethylamine, and 5-methoxytryptamine concentrations were higher (p < 0.05) in the NH goats than in the H goats. A targeted metabolomics analysis showed that six of the eight affected amino acids were lower (p < 0.05), and six of the seven affected phosphatidylcholines were higher (p < 0.05) in the NH goats compared to the H goats. The results show that habituation reduces fear and stress responses to routine handling, in addition to increasing BW, which can improve the welfare of meat goats.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8fea6b8a-3852-40e1-b9dc-1e9d995b68d2', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Auditing animal welfare and making practical improvements in beef-, pork- and sheep-slaughter plants', 'Grandin, Temple', 2012, 'Animal Welfare 21(S2):29-34 (Humane Slaughter Association Centenary International Symposium proceedings)', '10.7120/096272812X13353700593400', 'https://www.cambridge.org/core/journals/animal-welfare/article/auditing-animal-welfare-and-making-practical-improvements-in-beef-pork-and-sheepslaughter-plants/6B188B76A764A58278ED8E8BF9E15AD9', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/6B188B76A764A58278ED8E8BF9E15AD9/S0962728600004656a.pdf/auditing_animal_welfare_and_making_practical_improvements_in_beef_pork_and_sheepslaughter_plants.pdf', NULL, NULL, 6, NULL, 'other', 4, 'CC-BY-NC-SA (open access)', 'Sets out the numerical audit framework and reports audit results, and is valuable here because it gives defensible pass/fail numbers inside an openly licensed paper. In 32 beef plants, cattle vocalising in the stunning area was 5% or less, with a pass threshold of 5% or less for cattle and pigs. Falling must be 1% or less to pass: 94% of beef plants and 86% of pork plants had zero falls, with a worst score of 2%. All 30 North American plants in one group stunned at least 95% of cattle with a single captive-bolt shot. Electric-goad use is a named critical control point. It discusses the practical fixes that reduce balking - lighting, noise reduction, visual barriers - without giving balking percentages.', '{behaviour,audit-thresholds,vocalisation,falling,slipping,electric-prod,practical-fixes,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8f1c9dcd-5770-4e85-874f-e566ec68dcb8', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Automated cattle counting using Mask R-CNN in quadcopter vision system', 'Beibei Xu, Wensheng Wang, Greg Falzon, Paul Kwan, Leifeng Guo, Guipeng Chen, L. Amy Tait, Derek A. Schneider', 2020, 'Computers and Electronics in Agriculture', '10.1016/j.compag.2020.105300', 'https://doi.org/10.1016/j.compag.2020.105300', 'https://rune.une.edu.au/bitstreams/fe3a401e-adfb-4bee-90ff-c1b290816016/download', NULL, NULL, 12, NULL, 'other', 1, 'cc-by-nc-nd', 'The accurate and reliable counting of animals in quadcopter acquired imagery is one of the most promising but challenging tasks in intelligent livestock management in the future. In this paper we demonstrate the application of the cutting-edge instance segmentation framework, Mask R-CNN, in the context of cattle counting in different situations such as extensive production pastures and also in intensive housing such as feedlots. The optimal IoU threshold (0.5) and the full-appearance detection for the algorithm in this study are verified through performance evaluation. Experimental results in this research show the framework’s potential to perform reliably in offline quadcopter vision systems with an accuracy of 94% in counting cattle on pastures and 92% in feedlots. Compared with the existing typical competing algorithms, Mask R-CNN outperforms both in the counting accuracy and average precision especially on the datasets with occlusion and overlapping. Our research shows promising steps towards the incorporation of artificial intelligence using quadcopters for enhanced management of animals.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f391738-9538-406a-87eb-742eacc3549f', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Beef Cattle Production Handbook, Chapter 11: Facilities (MP184)', 'University of Arkansas System Division of Agriculture, Cooperative Extension Service', 2017, 'University of Arkansas Division of Agriculture, publication MP184', NULL, 'https://www.uaex.uada.edu/publications/', 'https://www.uaex.uada.edu/publications/pdf/mp184/Chapter11.pdf', NULL, NULL, 5, NULL, 'other', 2, 'free-to-read publisher PDF (US land-grant extension; no explicit open licence)', 'A secondary extension reproduction of the same MWPS-derived working-facility dimensions as MP239 and Kentucky ID-13, inside a broader beef production handbook. Included only as a cross-check: where three or four independent extension services publish the same table with different numbers, the designer is on safer ground presenting a band than a single value. Superseded for working purposes by MP239 from the same institution.', '{behaviour,dimension-table,MWPS,cross-check,secondary,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f6292f38-748f-4c0e-b956-12abf954a8d8', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Behavioral agitation during handling of cattle is persistent over time', 'Grandin, Temple', 1993, 'Applied Animal Behaviour Science 36:1-9', '10.1016/0168-1591(93)90094-6', 'https://grandin.com/references/abstract-3.html', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'free-to-read author-hosted HTML abstract at grandin.com (journal version paywalled at Elsevier)', 'The measurement that tells a design tool what baseline to expect: some cattle never habituate, no matter how good the facility. 53 crossbred Gelbvieh by Simmental by Charolais bulls (about 260 kg at start) and 102 steers in three feedlot pens were restrained in a squeeze chute every 30 days for blood sampling under gentle handling with rare prod use. Five bulls (9%) were extremely agitated at every one of four consecutive restraints while 25 (47%) were calm at all four; six steers (6%) were always agitated over three sessions while 78 (76%) were always calm. Agitation was highly persistent, and the agitated animals were indistinguishable from pen-mates at rest. Grandin attributes the persistence to both prior rough handling at the ranch of origin and genetics, and recommends culling repeat offenders. She also notes that the same cattle all stayed calm on a double-rail restrainer conveyor at a 400 head per hour plant, which she attributes to constant physical contact between animals - consistent with the measured isolation and companion-animal literature. The design implication is that 6-9% of animals being difficult is the expected baseline, not evidence of a layout fault.', '{behaviour,habituation-failure,persistence,chute-score,culling,restrainer,design-for-the-tail,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4949dea3-0440-4416-84c9-785ea8580051', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Blood lactate and rectal temperature can predict exit velocity of beef feedlot steers', 'Andrew F. Williams, J.A. Boles, M. R. Herrygers, James G. Berardinelli, Michael Clinton Meyers, Jennifer M. Thomson', 2019, 'Translational Animal Science', '10.1093/tas/txz135', 'https://doi.org/10.1093/tas/txz135', 'https://academic.oup.com/tas/article-pdf/3/4/1530/33234230/txz135.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Abstract: Interest in beef cattle temperament has increased due to growing consumer awareness of animal welfare and increased concern for handler safety. Temperament measures are based on behavioral responses to a perceived stressor. Subjective chute scoring has been used to give a numeric value to temperament; however, the subjectivity and variability among observers have been questioned. To deal with the perceived subjectivity and variability, other researchers have used exit velocity. Researchers have related faster exit velocities to increased cortisol and plasma lactate. The objectives of this study were to compare temperament between feedlot steers and heifers and to confirm chute side measures of temperament relationship to physiological responses to stress. Body temperature, blood and plasma lactate, serum glucose, salivary and serum cortisol concentrations were measured on Bos taurus commercial crossbred feedlot cattle (n = 197). Fast, medium, and slow classifications were developed from exit velocities. Plasma lactate was significantly different between all exit velocity classes. Exit velocity and physiological measures indicated that heifers were more excitable (faster exit velocities (P = 0.003), higher plasma lactate concentrations (P = 0.03), and cortisol concentrations (P = 0.001)). Simple correlations among these variables indicated body temperature (heifers r = 0.44, P < 0.0001; steers r = 0.45, P < .0001), plasma lactate (heifers r = 0.52, P < 0.0001; steers r = 0.63, P < 0.0001), blood lactate (heifers r = 0.53, P < 0.001; steers r = 0.59, P < 0.001), and glucose (heifers r = 0.54, P < 0.001; steers r = 0.32, P <0.003) were all related to exit velocity. Cortisol measures were not correlated to exit velocity in steers but were in heifers. Linear models constructed and evaluated using the Akaike information criterion indicated that blood lactate in combination with rectal temperature were strong candidates to predict exit velocity. Using the discriminate function analysis, the model correctly categorized fast and slow classifications 69.23% and 61.54%, respectively, indicating that in combination measures of body temperature and blood lactate can potentially increase accuracy of temperament identification or replace exit velocity as a measure of temperament. The plasma lactate and rectal temperature have the potential to become strong objective measures to augment or replace exit velocity.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60490de1-e01b-416d-9e41-1e6c29b81075', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Bos indicus-cross feedlot cattle with excitable temperaments have tougher meat and a higher incidence of borderline dark cutters', 'Voisinet, B. D.; Grandin, Temple; O''Connor, S. F.; Tatum, J. D.; Deesing, M. J.', 1997, 'Meat Science 46(4):367-377', '10.1016/S0309-1740(97)00031-4', 'https://www.grandin.com/references/elsevier112097.html', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'free-to-read author-hosted HTML at grandin.com, with OCR errors (journal version paywalled at Elsevier)', 'The standard citation for the measured link between handling temperament and meat quality. Braford, Red Brangus and Simbrah feedlot cattle were chute-scored at routine weighings, fed to 9-13 mm backfat over the 12th rib, and slaughtered commercially. Temperament significantly affected the incidence of borderline dark cutters downgraded by a USDA grader (P=0.01) and Warner-Bratzler shear force at 14 days post mortem (P<0.001): the calmest cattle averaged 2.86 plus or minus 0.11 kg shear force versus 3.63 plus or minus 0.19 kg for those that struggled violently, and 40% of agitated cattle exceeded the 3.9 kg food-service acceptability threshold. A secondary extension summary puts dark cutters at 6.7% for calm-scored versus 25% for highly excitable animals, which should be verified against the paper before quoting. The breed effect does not transfer to a British-breed Alberta herd, but the shear-force and dark-cutter effect sizes are the figures everyone cites. The companion paper (Voisinet et al. 1997, Journal of Animal Science 75:892-896) establishes that calm cattle outgain excitable ones, and the number should be taken from that paper directly because Grandin''s own summaries of its effect size are typographically garbled in at least two places.', '{behaviour,temperament,tenderness,dark-cutters,chute-score,carcass,meat-quality,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e760f91f-4bbf-42a0-b9d6-208f5c012906', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Deciphering Cattle Temperament Measures Derived From a Four-Platform Standing Scale Using Genetic Factor Analytic Modeling', 'Yu H, Morota G, Celestino EF Jr, Dahlen CR, Wagner SA, Riley DG, Hulsman Hanna LL', 2020, 'Frontiers in genetics', '10.3389/fgene.2020.00599', 'https://doi.org/10.3389/fgene.2020.00599', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7304504.1/PMC7304504.1.pdf', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'The animal''s reaction to human handling (i.e., temperament) is critical for work safety, productivity, and welfare. Subjective phenotyping methods have been traditionally used in beef cattle production. Even so, subjective scales rely on the evaluator''s knowledge and interpretation of temperament, which may require substantial experience. Selection based on such subjective scores may not precisely change temperament preferences in cattle. The objectives of this study were to investigate the underlying genetic interrelationships among temperament measurements using genetic factor analytic modeling and validate a movement-based objective method (four-platform standing scale, FPSS) as a measure of temperament. Relationships among subjective methods of docility score (DS), temperament score (TS), 12 qualitative behavior assessment (QBA) attributes and objective FPSS including the standard deviation of total weight on FPSS over time (SSD) and coefficient of variation of SSD (CVSSD) were investigated using 1,528 calves at weaning age. An exploratory factor analysis (EFA) identified two latent variables account for TS and 12 QBA attributes, termed difficult and easy from their characteristics. Inclusion of DS in EFA was not a good fit because it was evaluated under restraint and other measures were not. A Bayesian confirmatory factor analysis inferred the difficult and easy scores discovered in EFA. This was followed by fitting a pedigree-based Bayesian multi-trait model to characterize the genetic interrelationships among difficult, easy, DS, SSD, and CVSSD. Estimates of heritability ranged from 0.18 to 0.4 with the posterior standard deviation averaging 0.06. The factors of difficult and easy exhibited a large negative genetic correlation of -0.92. Moderate genetic correlation was found between DS and difficult (0.36), easy (-0.31), SSD (0.42), and CVSSD (0.34) as well as FPSS with difficult (CVSSD: 0.35; SSD: 0.42) and easy (CVSSD: -0.35; SSD: -0.4). Correlation coefficients indicate selection could be performed with either and have similar outcomes. We contend that genetic factor analytic modeling provided a new approach to unravel the complexity of animal behaviors and FPSS-like measures could increase the efficiency of genetic selection by providing automatic, objective, and consistent phenotyping measures that could be an alternative of DS, which has been widely used in beef production.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49f5f485-ba70-404c-82b4-2f27eb83f10e', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Cattle Behavior and Handling Facility Design for Feedlots', 'Grandin, Temple (Iowa Beef Center, Iowa State University)', 2016, 'Iowa Beef Center, Iowa State University', NULL, 'https://www.iowabeefcenter.org/', 'https://www.iowabeefcenter.org/bch/CattleBehaviorFeedlot.pdf', NULL, NULL, 9, NULL, 'other', 4, 'free-to-read publisher PDF (university extension; no explicit open licence)', 'The verified-PDF vehicle through which many of Grandin''s observational rules reach producers, and therefore what a ranch crew has probably already read. Carries the flight-zone diagram, the point of balance, the blind spot behind, ''cattle have poor depth perception when they are moving with their heads up'', the drain-grate rule (''Draining grates in the middle of the floor will make cattle balk. A good drainage design is to slope the concrete floor in the squeeze chute area toward an open drainage ditch located outside the fences''), the snow-fence shade warning (''The zebra stripe shadows can cause balking''), the single-shadow warning (''A single shadow that falls across a scale or loading chute can disrupt handling''), the rule to extend the single-file chute 10 to 15 feet outside a building, and a full dimension set: crowd pen radius 12 ft recommended and 10 ft minimum, 30 degree funnel side, V-race 16-18 inch bottom and 32-36 inch top, straight race 26 inches for cows and 18-20 for calves, alleys 10 ft on foot, 12 ft foot plus horse and 14-16 ft horses only, ramp slope up to 20 degrees, stair rise 10 cm and tread 30-45 cm, solid belly rail 45 cm. Notably it carries neither the 45-60 degree handler angle nor any flight-zone figure in metres. Also recommends a straight rather than curved race where the race is used exclusively for loading.', '{behaviour,extension,balking,shadows,drain-grate,dimensions,crowd-pen,curved-race-claim,uphill,feedlot}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d8027d5c-8f5b-4d0b-b211-8f3c6a3fba10', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Cattle handling (Livestock Buildings Consultancy)', 'Meat and Livestock Commission, Livestock Buildings Consultancy, Queensway, Bletchley, Milton Keynes, England', 1980, 'Meat and Livestock Commission (publication undated)', NULL, 'http://www.grandin.com/references/design.construction.facilities.handling.cattle.html', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'unknown', 'Listed for provenance of the project''s single most-asked question. This undated industry pamphlet is the primary and only source for the 30 degree asymmetric funnel rule: Grandin 1997 cites it, and only it, for ''one side should be straight and the other side should be on a 30 degree angle'', and her later web pages repeat the attribution. No experiment, trial, measurement or dataset behind the rule was found, from the Meat and Livestock Commission or anyone else. The practical answer is therefore that the 30 degree figure is conventional engineering wisdom from a now-defunct UK marketing board''s buildings advisory service - the MLC was dissolved in 2008 and its Livestock Buildings Consultancy outputs do not appear to be archived online - repeated for three decades because it works in practice and nobody has tested it. The app should implement it, since it is the industry standard and the mechanism is plausible, but should label it as convention and emphasise the asymmetry rather than the exact angle, since nothing in any source distinguishes 30 degrees from 25 or 35. Year is recorded as 1980 as an approximation only; the publication carries no date, and no landing page or archived copy was located.', '{behaviour,funnel-angle,30-degrees,asymmetric,jamming,conventional-wisdom,no-experiment,provenance,unverifiable,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d41e9bd-9f36-4081-a2ff-f4a2ebfcdb8e', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Cattle handling design principles (Meat Technology Update 99/5)', 'CSIRO Meat Industry Services', 1999, 'CSIRO Meat Industry Services, Meat Technology Update 99/5', NULL, 'https://meatupdate.csiro.au/', 'https://meatupdate.csiro.au/data/MEAT_TECHNOLOGY_UPDATE_99-5.pdf', NULL, NULL, 5, NULL, 'other', 3, 'CSIRO publication; terms unknown', 'A short CSIRO technical bulletin setting out crowd-pen, race and ramp principles. Like the Queensland manual it states that in a race cattle will more readily follow a curved path than a straight one, as expert recommendation with no underlying experiment cited - which matters because CSIRO is in the same country and research tradition as the Vowles abstracts that are the only measured source, one of which found no significant difference.', '{behaviour,design-principles,curved-race-claim,crowd-pen,ramp,australian}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ac80090-f5a1-4e69-95c8-df9cc33c6e07', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Contemporary Knowledge on the Assessment of Temperament in Cattle and Its Impact on Production and Reproduction Including Some Immunological, Genetic and Metabolic Parameters', 'Jaśkowski JM, Jaśkowski BM, Herudzińska M, Tul O, Ciorga M', 2023, 'Animals : an open access journal from MDPI', '10.3390/ani13121944', 'https://doi.org/10.3390/ani13121944', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10295468.1/PMC10295468.1.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Temperament is associated with the well-being, health, production and reproduction of cattle. In order to increase the population of individuals with the desired temperament, its evaluation should be standardized and be made one of the obligatory elements of breeding and veterinary examination. A number of different tests are used for temperament assessment. In this article, the importance of temperament correlation with some metabolic, genetic, immunological, production and reproductive parameters have been shown, pointing at its influence on the economy and cattle handling. The most common methods for assessing the temperament of cattle are presented, including long-time scales of temperament assessment. At the same time, the relationship of the temperament of cattle with production efficiency, immunity and reproductive indicators has been shown, indicating that its correct assessment is an important aspect of the proper development of the herd and the associated economic growth.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5afd580a-fbbe-47b4-96b9-eae748f6b963', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Differences in evaluators and genetic parameter estimations using subjective measurements of beef cattle temperament', 'Elfren F. Celestino, Jordan K. Hieber, Carl Robertson Dahlen, David Greg Riley, Sarah Wagner, Lauren L Hulsman Hanna', 2019, 'Translational Animal Science', '10.1093/tas/txz084', 'https://doi.org/10.1093/tas/txz084', 'https://academic.oup.com/tas/article-pdf/3/Supplement_1/1769/33234007/txz084.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'When handled, cattle that are calm have greater average daily gain, increased feed efficiency, and pregnancy rates (Voisinet et al., 1997). Cattle with excitable temperament have impaired feedlot performance, poor carcass, and meat quality traits (Francisco et al., 2015). Temperament is associated with stress experienced during husbandry procedures (Sebastian et al., 2011). It is therefore, important to select cattle with calm temperament to improve production and reproductive traits. Objective temperament methods include exit velocity (Burrow et al., 1988) and movement measuring devices (Sebastian et al., 2011; Yu, 2016). Subjective methods include chute score (Grandin, 1993), pen score (Hearnshaw and Morris, 1984), and qualitative behavior attributes (QBA; Sant’Anna and Paranhos da Costa, 2013). There are concerns of evaluator bias due to evaluator experience and interpretation, where limited literature exists investigating if it affects genetic evaluations. The objective of this study was to 1) determine evaluator effect on subjective measures of temperament and 2) compare genetic parameter estimates when evaluator was included in the model. We hypothesize that evaluator has a significant effect for subjective measures of temperament and will affect genetic parameter estimations (heritability and breeding value ranking). All procedures were reviewed and approved by the Institutional Animal Care and Use Committee of North Dakota State University. Weaning age calves (n = 1,542) were used over a 4-yr period (2014: n = 420, 2015: n = 382, 2016: n= 337, and 2017: n = 403). Calves were produced by the North Dakota State University Central Grasslands Research Extension Center cow herd. This herd consists of roughly 425 Angus-based (AN) and Hereford-based (HP) females (mature cows and heifers) that are bred to either AN or HP bulls. Calf dams had unknown pedigree and breed composition if born prior to 2012. Some heifers born from 2012 to 2015 were retained for use in breeding, leading to a better estimation of breed composition since sire breed was known. Over the 4-yr period, dams were mated to either AN or HP bulls, except in the first year (AN only). These matings resulted in calves of eight breed types (%): 75 AN 25 Unknown (UN; n = 362), 50 AN 50 UN (n = 951), 50 HP 25 AN 25 UN (n = 147), 50 HP 50 UN (n = 31), 87.5 AN 12.5 UN (n = 30), 62.5 AN 25 HP 12.5 UN (n = 13), 50 AN 25 HP 25 UN (n = 4), and 50 HP 37.5 AN 12.5 UN (n = 4). On the basis of primary breed (50% or greater), this resulted in 1,360 AN- and 182 HP-influenced calves. Collection of docility score (DS), temperament score (TS), and QBA followed Hieber (2016). Briefly, DS was a scale of 1 to 6 with the head caught in the chute and TS ranged from 1 to 5, where the intermediate score (3) was removed to avoid choosing the median value (Sant’Anna and Paranhos da Costa, 2013). For QBA, evaluators scored each attribute (n = 12) on a 136-mm line to indicate the level of expression. The QBA score was the distance of the mark from the far left side measured with a digital fractional caliper (General Tools & Instruments, New York, NY). Evaluators per year (n = 6) were assigned to two of three methods to avoid fatigue in scoring (i.e., 4 evaluators per method). Calves entered the handling facility based on management group (young vs. old dams) and first encountered the Silencer chute (Moly Manufacturing Inc., Lorraine, KS), where weaning weight and DS were recorded. Calves then entered a four-platform standing scale that measured weight distribution 8 to 10 times per second before moving into a working pen where TS and QBA were evaluated. A handler was present so that evaluators could score specific attributes of TS and QBA. Principal component analysis (PCA) on QBA in SAS, v.9.4 (SAS Institute, Inc., Cary, NC) per evaluator produced the temperament index (TI) using the first principal component (PC; Sant’Anna and Paranhos da Costa, 2013). Each trait (n = 15) was evaluated in S', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('abd4fe6f-46c6-4d64-bc7d-60369daac768', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Application of DNA parentage testing and EnVigour HX™ to evaluate bull prolificacy and heifer performance in beef cattle breeding programs in Western Canada', 'Tess D Mills, Razie Khorshidi, Daalkhaijav Damiran, Mika Asai-Coakwell, D. Moya, Kathy Larson, H.A. Lardner', 2025, 'Translational Animal Science', '10.1093/tas/txaf129', 'https://doi.org/10.1093/tas/txaf129', 'https://academic.oup.com/tas/advance-article-pdf/doi/10.1093/tas/txaf129/64353851/txaf129.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'Abstract The use of multi-sire breeding pastures is a common practice in Western Canada for beef cattle management. However, the number of progenies sired by each bull may not be known or producers will not be sure if performance traits were passed on. Hybrid vigor is defined as the superiority of crossbred progeny over their parents’ average to increase production efficiency, longevity and reproductive rate of beef cows. A DNA parentage test was performed to identify relative sires to their progeny. Then, 109 bull prolificacy indexes (BPI) were calculated for 46 sires over 6 breeding seasons (some had more than one BPI). They ranged from 0.04 to 3.47, with values larger than one showing high prolific sires. Yearling sires had a significantly lower BPI value than 2-year-old and mature bulls. Regardless of the level of BPI, each sire produced the majority of all his born calves in the first cycle of the calving period (R2 = 0.89). This demonstrated the importance of identifying high BPI sires, as they showed a tendency to have a greater percentage of the first cycle born grand calves from their first cycle born heifers (R2 = 0.86). Also, they produced a greater number of grand calves from their retained daughters with a significant impact on total kg weaned (P < 0.01). The EnVigour HX™ test was applied to estimate the effect of bulls’ and heifers’ vigor scores (scores were based on percentage) on fertility and production traits. The breeder’s interest in the utilization of crossbred heifers and bulls positively affected the longevity of replacement females. There was a decrease in age at first calving relative to the EnVigour HX™ test commercialized suggestions per 10% increase in heifers’ vigor scores. Moreover, larger productivity was observed for average WW per calf and cow life productivity, which could be due to different genomic breed compositions between this study and the test animals. Overall, DNA parentage and EnVigour HX™ tests are essential tools for beef cattle production profitability. However, up to a 75% vigor score cutoff is suggested when selecting crossbred females with EnVigour HX™ to retain production and fertility efficiency in crossing with Beef Booster bulls.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('09725bcc-65d5-40a9-838e-ca2628069889', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effect of age at weaning on the physiological stress response and temperament of two beef cattle breeds', 'Mireia Blanco, Isabel Casasús, Jorge Palacio', 2008, 'animal', '10.1017/s1751731108002978', 'https://doi.org/10.1017/s1751731108002978', 'https://www.sciencedirect.com/science/article/pii/S1751731108002978/pdf', NULL, NULL, 10, NULL, 'other', 1, 'cc-by-nc-nd', 'The study was conducted to evaluate the effect of age at weaning and breed on the stress response of calves to weaning and their temperament. At calving, 14 Parda de Montaña calves and 14 Pirenaica calves were randomly assigned to either early weaning (at 90 days) or traditional weaning (at 150 days) treatment. During nursing, calves were allowed to suckle their dams twice a day for 30 min. After weaning, calves were placed in an adjacent barn without access to their dams, where they remained for 7 days. On day 8 after weaning, they were transported to a feedlot where they received an intensive diet. Blood samples were taken 168 h before weaning (baseline) and 6, 24, 48 and 168 h after weaning for cortisol, fibrinogen and haematology analyses, and temperament was measured 90 and 180 days after weaning with the flight speed test. Cortisol concentration increased after weaning, irrespective of age at weaning. Early-weaned calves had a lower fibrinogen baseline and a greater increase in fibrinogen concentrations 48 h after weaning than traditionally weaned calves. Moreover, fibrinogen concentration returned to baseline values 168 h after weaning in traditionally weaned calves, whereas it remained high in early-weaned calves. Concerning breed effects, Pirenaica calves had higher cortisol concentration and fibrinogen increments after weaning than Parda de Montaña calves. Slight alterations occurred after weaning in haematology, but all parameters returned to baseline values 168 h after weaning, with no significant effects of age at weaning or breed. Despite the absence of clinical signs, early-weaned calves of both breeds suffered marginal anaemia, according to haemoglobin values. Regardless of age at weaning, Pirenaica calves had greater reactivity to human presence than Parda de Montaña calves, according to their higher flight speed values measured. Finally, early-weaned calves were lighter than traditionally weaned calves at weaning, but had similar weight gains in the feedlot. Consequently, they needed an additional 40 days to reach the target weight, irrespective of breed. Therefore, age at weaning had no major effects on the stress response to weaning or temperament, but early weaning increased the length of the feedlot period. On the other hand, Pirenaica calves were more reactive than Parda de Montaña calves to the stress of weaning and human presence.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('887dd652-c802-4d70-bfd7-c8673879757f', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effect of Different Finishing Strategies and Steer Temperament on Animal Welfare and Instrumental Meat Tenderness', 'Del Campo M, Manteca X, Soares de Lima JM, Brito G, Hernández P, Sañudo C, Montossi F', 2021, 'Animals : an open access journal from MDPI', '10.3390/ani11030859', 'https://doi.org/10.3390/ani11030859', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC8002882.1/PMC8002882.1.pdf', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'The aim of this experiment was to evaluate the effect of different fattening systems from pasture to concentrate and temperament on animal welfare (AW) and meat quality (MQ). Eighty-four Hereford steers were randomly assigned to the following groups: T1, pasture (4% of animal live weight: LW); T2, pasture (3% LW) plus concentrate (0.6% LW); T3, pasture (3% LW) plus concentrate (1.2% LW); T4, an ad libitum concentrate treatment. Temperament was assessed by three individual tests: crush score, flight time, and exit speed, building a multicriterial temperament index (TIndex). The flight zone was also registered for each treatment. AW was assessed through the integration of indicators of productivity, physiology, and behavior, as well as by monitoring the health status within each treatment. Shear force was registered for MQ. Differences in average daily gain were due to the different energetic composition of the diets (T4 > T3 > T2 > T1) and were not attributable to animal welfare problems. Animals from T4 had the higher average daily gain (ADG) but welfare was negatively affected, being evident through physiological indicators, the restriction or deprivation of relevant behaviors, diet-related diseases, and mortality. T1, T2, and T3 did not appear to compromise animal welfare. However, strict preventive measures and monitoring should be taken during the habituation process and when using any new diet that includes concentrate, because of possible dietary diseases. Shear force values were lower in T1. None of the animals in our experiment were excitable or aggressive, but there was a positive response to handling in all treatments. In addition, regardless of diet, calmer animals had higher average daily gain and lower shear force values; thus, temperament appears to have a significant influence on productivity and meat quality.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2a1dcec3-c1cd-4ec8-8da4-fa8bb0e644aa', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effect of light on dairy cattle in farm conditions - a review', 'Adamczyk, Krzysztof; Herbut, Piotr; Godyń, Dorota; Angrecka, Sabina; Kupczyński, Robert; Vieira, Frederico Márcio Corrêa', 2024, 'Annals of Animal Science 24(4):1139-1151', '10.2478/aoas-2024-0052', 'https://reference-global.com/article/10.2478/aoas-2024-0052', 'https://reference-global.com/download/article/10.2478/aoas-2024-0052.pdf', NULL, NULL, 13, NULL, 'other', 4, 'CC-BY-NC-ND (Sciendo open access) - check before redistributing', 'The most citation-dense and freely verifiable source on bovine vision numbers found, and where the key acuity conversion lives: cattle visual acuity is approximately 1.3-2.5 cycles per degree against human acuity of 32.1-44.2 cpd in bright conditions, i.e. cattle resolve roughly one-twentieth of the spatial detail a human does. Also carries dichromacy with S- and ML-cones (Jacobs 1998); long versus short and medium discrimination but not short versus medium (Phillips and Lomas 2001); the horizontal oval pupil and horizontally aligned visual streak with vertical stimuli better detected (Rehkämper 2000; Brooks 1999; Kassab and Sugita 2000); a ''predominantly monocular visual field, with only a minor central binocular area'' and pointedly no degree figure; the choroidal tapetum fibrosum boosting dim-light sensitivity; 80-87% contralateral visual pathways and a left-eye bias for novel stimuli; the statement that ''due to limited visual acuity, shadows can appear as holes to cows''; Lindkvist 2023''s finding that cows navigate well even in darkness; Hirata 2019''s 2 m field-discrimination limit; the 50% inside/outside intensity disparity threshold (Marciniak 2008); and the Danish working, orientation and night lighting tables of 100/25/5 and 200/25/5 lux.', '{behaviour,vision,visual-acuity-cpd,dichromacy,visual-streak,shadows-as-holes,lux-thresholds,contrast-50-percent,review,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('abd89080-3b40-4c78-84d9-e5965786d6e8', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effect of neck injection and handler visibility on behavioral reactivity of beef steers', 'Müller, R.; Schwartzkopf-Genswein, Karen S.; Shah, M. A.; von Keyserlingk, Marina A. G.', 2008, 'Journal of Animal Science 86(5):1215-1222', '10.2527/jas.2007-0452', 'https://doi.org/10.2527/jas.2007-0452', NULL, NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'unknown (closed access)', 'The controlled test of the premise behind every ''use solid sides, block the animal''s vision'' recommendation in the design canon - a premise otherwise carried entirely by Grandin''s field observation. The study experimentally manipulated handler visibility, that is whether the restrained steer could see the person, alongside neck injection, and measured behavioural reactivity. Schwartzkopf-Genswein is at the Agriculture and Agri-Food Canada Lethbridge Research and Development Centre and von Keyserlingk at the University of British Columbia, so this is Canadian work on Alberta cattle and the most locally relevant measured anchor available for the solid-versus-see-through-sides question. Read alongside the measured counter-evidence - Stookey and Watts'' Y-maze result that cattle chose the race where they could see light through the side - which together support a directional rule: block the view of distractions and handlers AHEAD along the direction of travel, rather than demanding blanket solid sides.', '{behaviour,handler-visibility,solid-sides,controlled-experiment,AAFC-Lethbridge,southern-alberta,canadian,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c575423f-6e23-4745-aa8b-f8fc6fa4a7b2', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Flooring options to minimize lameness and optimize welfare', 'Rushen, Jeffrey; de Passillé, Anne Marie (Pacific Agri-Food Research Centre, Agriculture and Agri-Food Canada, Agassiz BC)', 2009, 'WCDS Advances in Dairy Technology 21:293-301 (University of Alberta)', NULL, 'https://wcds.ualberta.ca/', 'https://wcds.ualberta.ca/wcds/wp-content/uploads/sites/57/wcds_archive/Archive/2009/Manuscripts/FlooringOptions.pdf', NULL, NULL, 10, NULL, 'canada', 4, 'free-to-read conference proceedings PDF (University of Alberta WCDS)', 'The best free, Canadian-authored synthesis of cattle flooring and traction, reviewed by NFACC''s Scientist Committee, and the fastest route into the primary flooring literature. It states the three design conclusions a corral checker needs: flooring must be both compressible and high-traction; compressibility reduces slip risk more than surface friction does (Rushen and de Passille 2006, 16 cows over purpose-built walkways); and slurry on the floor reduces walking speed, makes cattle avoid the passage, raises slip and fall risk, increases the need for handlers to intervene - which directly reduces handling efficiency - and does its worst damage at starts, corners and obstacles, with added non-slip material not necessarily fixing it. It also tabulates the epidemiology: lameness prevalence 1% on straw yards, 20.1% solid concrete, 27.4% slatted concrete and 40.6% grooved concrete (Frankena et al. 2008); hoof disease 19.8% on concrete versus 2.9% on earth; sole haemorrhage 44.6% on concrete slats versus 4.6% on straw; and Bell''s 2004 British Columbia finding that large floor cracks and holes explain 15% of between-farm lesion variation. The design message is that grooving buys traction for handling at a measurable cost in standing surfaces, so groove the handling alleys and crowd pen, not the loafing areas.', '{behaviour,flooring,traction,compressibility,slurry,grooved-concrete,lameness,corners,AAFC,canadian}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8484815-a91e-4d64-b8d0-9159544e9a45', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'The investigation and evaluation of riparian management practices within the Manitoba landscape: off-stream watering systems', 'Ashley Rawluk', 2013, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/19452', 'http://hdl.handle.net/1993/19452', NULL, NULL, 225, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3999e8db-6bf0-4e69-8997-7a1d980ebaeb', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of acclimation to human interaction on performance, temperament, physiological responses, and pregnancy rates of Brahman-crossbred cows', 'Cooke, R. F.; Arthington, J. D.; Araujo, D. B.; Lamb, G. C.', 2009, 'Journal of Animal Science 87:4125-4132', '10.2527/jas.2009-2021', 'https://doi.org/10.2527/jas.2009-2021', 'https://fic.oregonstate.edu/sites/agscid7/files/eoarc/attachments/637.pdf', NULL, NULL, 10, NULL, 'other', 4, 'free-to-read publisher PDF hosted by Oregon State (ASAS copyright)', 'An important null result, and a direct caution against promising users that gentling will fix their flight speed. 395 Braford and Brahman by British cows over two consecutive years. Acclimated groups were visited twice weekly for 15 minutes from weaning in August to breeding in January by the same handler, who walked among the cows and hand-offered 0.05 kg of range cubes (deliberately nutritionally meaningless); controls stayed undisturbed on pasture. There was no treatment effect on chute score (P=0.94), pen score (P=0.59), exit velocity (P=0.88), composite temperament score (P=0.12), cortisol (P=0.68), haptoglobin (P=0.57) or IGF-I, yet acclimated Braford cows conceived earlier and at a higher rate in year 1 (P<0.01). Pearson correlations among cortisol, chute score, exit velocity and pen score ranged 0.34 to 0.75, all P<0.01. Low-intensity, non-chute acclimation changed reproduction but not the handling measures. The paper also documents the exit-score method, in which exit velocity is split into within-day quintiles with 1 the slowest.', '{behaviour,acclimation,habituation-failure,exit-velocity,chute-score,cortisol,correlations,null-result}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('94a28a4b-0356-4885-bf85-2508043cf52b', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of achromatic and chromatic lights on pupillary response, endocrinology, activity, and milk production in dairy cows', 'Lindkvist, Sofia; Ternman, Emma; Ferneborg, Sabine; Bånkestad, Daniel; Lindqvist, Jonatan; Ekesten, Björn; Agenäs, Sigrid', 2021, 'PLoS ONE 16(7):e0253776', '10.1371/journal.pone.0253776', 'https://doi.org/10.1371/journal.pone.0253776', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0253776&type=printable', NULL, NULL, 18, NULL, 'other', 3, 'CC-BY 4.0', 'Measures bovine pupillary response under achromatic and chromatic lights alongside endocrine, activity and production outcomes. Included because it is the nearest verifiable approach to adaptation data for cattle, and because the claim that ''cattle adapt slowly to rapid changes in lighting'' is asserted in every recent review but measured in none that could be reached - the bovine ERG literature does not report a recovery curve. This paper is the place to start if the ranch wants to pursue that gap, and the reason the designer should not encode a dark-adaptation time constant.', '{behaviour,vision,pupillary-response,light-spectrum,adaptation-proxy,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eb6a3d16-a785-4193-8953-805ed4dbfc89', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of cortisol levels on reproductive success in cattle of different temperaments during fixed-time artificial insemination (FTAI)', 'N. A. C. de Faria, José Pacheco-Lima, Maria Helena Moreira da Silva, Alfredo E. S. Borba, Fernando Moreira da Silva', 2023, 'Journal of Animal Behaviour and Biometeorology', '10.31893/jabb.2024002', 'https://doi.org/10.31893/jabb.2024002', 'https://malque.pub/ojs/index.php/jabb/article/download/550/988', NULL, NULL, 5, NULL, 'other', 1, 'cc-by-nc-nd', 'The present study was designed to assess the effect of stress on the reproductive performance of cattle. For this purpose, a total of 137 cows were divided into two groups: 65 belonging to the Azores Lydia breed and 72 crossing Aberdeen-Angus with Limousine, free of IBR, Chlamydia and BVD diseases and with a body condition score ranging from 2.75 to 4.0. Eight days before starting the experimental procedures, animals passed through the containment sleeve every other day for routine and human presence. For the synchronization protocol, a progesterone-impregnated controlled internal drug release (CIDR®) insert was placed intravaginally, and an injection of GnRH was given. After 7 days, PGF2α was administered, and the CIDR® was removed. Sixty hours after removal, cows were inseminated once after another injection of GnRH to induce ovulation, and pregnancy diagnosis was performed by ultrasonography 30 days after artificial insemination. Peripheral blood was collected in 5 ml tubes with a Z Serum Sep Clot Activator, and cortisol was measured using the IMMULITE 2000 Immunoassay System ®. Our results indicated significant differences (p≤0.05) in the cortisol levels among both groups (beef crossbred cows vs Azores Lydia) of 4.3±0.3 ng/dl and 5.8±0.4 ng/dl, respectively. The pregnancy results were also significantly different: 63.7% vs 45.6%, respectively, for beef crossbred and "Azores Lydia" cows. The present study clearly demonstrated a negative correlation between cortisol levels and pregnancy rates after fixed-time artificial insemination. The low levels of cortisol observed in the animals and particularly in the Azores Lydia breed, when compared to other studies carried out on these animals, must be due to the passage of the animals in the sleeve, allowing them to habituate to a routine, as well as to human presence.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ae119eb4-e32f-4988-86a5-f8dca9828285', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of drylot dimension and group size on growth, physiological, and puberty responses of replacement beef heifers', 'Prado, C. P.; Cooke, R. F.; Mackey, S. J.; Pickett, A. T.; Monteiro, G. A.; de Souza, I. S.; Daigle, C. L.; Harvey, K. M.', 2026, 'Translational Animal Science 10:txag097', '10.1093/tas/txag097', 'https://europepmc.org/articles/PMC13375395', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'CC-BY (no reachable PDF endpoint; Oxford Academic blocks automated requests, full text available as XML via Europe PMC REST)', 'The study that shows why a per-head area check is not sufficient on its own, and a rare controlled measurement on pen geometry. 240 heifers (75% Angus by 25% Brahman, 270 days, 232 kg) were assigned to 10 by 14 m drylot pens with 10 heifers (14 m2 per heifer), 10 by 28 m drylot pens with 20 heifers (also 14 m2 per heifer), or 1.38 ha pastures - so the two drylot treatments held space per head constant while varying absolute pen dimension and group size. Body weight gain did not differ (about 0.635 kg per day, P=0.67). But hair cortisol was higher in both drylots than on pasture on days 30 and 170, and higher in the small pen than in both the large pen and pasture on day 58; heat shock protein HSP-70 and HSP-72 mRNA expression were higher in the small pen; and puberty rate was higher in the larger pen than the small one from weeks 13-16 and 18-22. The authors conclude that increasing drylot dimension and group size attenuated physiological stress responses. For the designer this means pens should be checked against a minimum absolute dimension as well as m2 per head - two pens at the same allowance per animal are not equivalent.', '{behaviour,space-allowance,pen-dimension,group-size,controlled-trial,hair-cortisol,stocking-density,minimum-dimension,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('95f52cb4-7f15-4f76-9c88-eb90f0c3b8b4', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Frequent handling of grazing beef cattle maintained under the rotational stocking method improves temperament over time', 'Maria Camila Ceballos, Karen Camille Rocha Góis, Aline Cristina Sant’Anna, Mateus José Rodrigues Paranhos da Costa', 2016, 'Animal Production Science', '10.1071/an16025', 'https://doi.org/10.1071/an16025', 'https://www.publish.csiro.au/an/pdf/AN16025', NULL, NULL, 8, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('23235cd6-503f-438c-9b9e-c54f5727eb27', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of mirror-image exposure on heart rate and movement of isolated heifers', 'Piller, C. A. K.; Stookey, Joseph M.; Watts, Jon M.', 1999, 'Applied Animal Behaviour Science 63(2):93-102', NULL, 'https://refinementdatabase.org/publications/effects-of-mirror-image-exposure-on-heart-rate-and-movement-of-isolated-heifers', NULL, NULL, NULL, NULL, NULL, 'prairies', 4, 'unknown (Elsevier, closed access)', 'University of Saskatchewan work, and the most design-relevant isolation-mitigation experiment because it tests something a corral can actually contain. Heifers in social isolation were exposed to a mirror and compared with controls in visual isolation. Mirror exposure lowered heart rate and reduced movement, and the authors suggest a mirror reflection may reduce isolation stress for a heifer in a chute. Effects were strongest after the animals had been habituated over several days of exposure. The replication caveat the app must carry: a later dairy study (Applied Animal Behaviour Science, 2018, on whether access to an automated grooming brush and/or a mirror reduces the stress of dairy cows kept in social isolation) reported no indication of immediate stress reduction from brush or mirror use. The honest position is that a mirror is a cheap, plausible, Saskatchewan-tested mitigation that has not replicated in dairy cattle - worth offering as an option, not as a recommendation.', '{behaviour,isolation,mirror,heart-rate,movement,canadian,prairies,habituation,failed-replication,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d9639b37-9bfa-49a7-b988-7a26de558d42', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of Multivalent BRD Vaccine Treatment and Temperament on Performance and Feeding Behavior Responses to a BVDV1b Challenge in Beef Steers', 'Smith P, Carstens G, Runyan C, Ridpath J, Sawyer J, Herring A', 2021, 'Animals : an open access journal from MDPI', '10.3390/ani11072133', 'https://doi.org/10.3390/ani11072133', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC8300223.1/PMC8300223.1.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'This study examined the effects of multivalent respiratory vaccine treatment (VT) and animal temperament classification on feeding behavior traits, feed intake and animal performance in response to a bovine viral diarrhea virus (BVDV) challenge. Nellore-Angus crossbred steers (n = 360; initial body weight (BW) 330 ± 48 kg) were assigned to one of three vaccine treatments: non-vaccinated (NON), modified live (MLV) and killed (KV) regarding respiratory viral pathogens, and inoculated intranasally with the same BVDV1b strain. Cattle temperament categories were based on exit velocity. Overt clinical signs of respiratory disease were not observed, yet the frequency and duration of bunk visit events as well as traditional performance traits decreased (p p p p < 0.01) eating rates compared with KV- and non-vaccinated steers following BVDV challenge. Greater differences in most feeding behavior traits due to VT existed within calm vs. excitable steers. Respiratory vaccination can reduce the sub-clinical feeding behavior and performance effects of BVDV in cattle, and the same impacts may not occur across all temperament categories.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf067594-f258-46ba-bc91-c9f66249163b', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of temperament on growth, plasma cortisol concentrations and puberty attainment in Nelore beef heifers', 'Reinaldo Fernandes Cooke, Philipe Moriel, Bruno I Cappellozza, V.F.B. Miranda, Luiz Fernando Dias Batista, Eduardo Colombo, Vitor S M Ferreira, M.F. Miranda', 2018, 'animal', '10.1017/s1751731118002628', 'https://doi.org/10.1017/s1751731118002628', 'https://www.sciencedirect.com/science/article/pii/S1751731118002628/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Excitable temperament disrupts physiological events required for reproductive development in cattle, but no research has investigated the impacts of temperament on growth and puberty attainment in Bos indicus females. Hence, this experiment evaluated the effects of temperament on growth, plasma cortisol concentrations and puberty attainment in B. indicus heifers. A total of 170 Nelore heifers, weaned 4 months before the beginning of this experiment (days 0 to 91), were managed in two groups of 82 and 88 heifers each (mean ± SE; initial BW=238±2 kg, initial age=369±1 days across groups). Heifer temperament was evaluated via exit velocity on day 0. Individual exit score was calculated within each group by dividing exit velocity into quintiles and assigning heifers with a score from 1 to 5 (1=slowest; 5=fastest heifer). Heifers were classified according to exit score as adequate (ADQ, n=96; exit score⩽3) or excitable temperament (EXC, n=74; exit score>3). Heifer BW, body condition score (BCS) and blood samples were obtained on days 0, 31, 60 and 91. Heifer exit velocity and score were recorded again on days 31, 60 and 91. Ovarian transrectal ultrasonography was performed on days 0 and 10, 31 and 41, 60 and 70, 81 and 91 for puberty evaluation. Heifer was declared pubertal at the first 10-day interval in which a corpus luteum was detected. Exit velocity and exit score obtained on day 0 were correlated (r⩾0.64, P<0.01) with evaluations on days 31, 60 and 91. During the experiment, ADQ had greater (P<0.01) mean BCS and BW gain, and less (P<0.01) mean plasma cortisol concentration compared with EXC heifers. Temperament × time interactions were detected (P<0.01) for exit velocity and exit score, which were always greater (P<0.01) in EXC v. ADQ heifers. A temperament × time interaction was also detected (P=0.03) for puberty attainment, which was delayed in EXC v. ADQ heifers. At the end of the experiment, a greater (P<0.01) proportion of ADQ were pubertal compared with EXC heifers. In summary, B. indicus heifers classified as EXC had reduced growth, increased plasma cortisol concentrations and hindered puberty attainment compared to ADQ heifers. Moreover, exit velocity may serve as temperament selection criteria to optimize development of B. indicus replacement heifers.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7491e582-cd69-4952-a537-e8af53a2f118', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Effects of Temperament on the Reproduction of Beef Cattle', 'Alice Poggi Brandão, Reinaldo Fernandes Cooke', 2021, 'Animals', '10.3390/ani11113325', 'https://doi.org/10.3390/ani11113325', 'https://www.mdpi.com/2076-2615/11/11/3325/pdf?version=1637501415', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Temperament is often defined as the behavioral expression of animals in response to human interaction. Cattle temperament can be evaluated using an association of chute score and exit velocity, with cattle then classified as adequate or excitable temperament. To assess the impacts of temperament on various beef systems, these evaluation criteria were associated with productive and reproductive parameters of Bos taurus and B. indicus-influenced cattle. Consistently across studies, excitable cattle had greater plasma cortisol compared to animals with adequate temperament. Studies also reported that excitable beef females have poorer reproductive performance compared to calmer cohorts, including reduced annual pregnancy rates, decreased calving rate, weaning rate, and kg of calf weaned/cow exposed to breeding. Acclimating B. indicus × B. taurus or B. taurus heifers to human handling improved behavioral expression of temperament and hastened puberty attainment. However, similar benefits were not observed when mature cows were acclimated to human handling. Collectively, temperament of beef females measured via behavioral responses upon human handling impacts their reproductive and productive responses independent of breed type, and should be considered for optimal beef cattle production.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('973124a8-b786-47c4-9992-0741c89dee4b', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament and dominance relate to feeding behaviour and activity in beef cattle: implications for performance and methane emissions', 'Pol Llonch, Miguel Somarriba, Carol-Anne Duthie, S. Troy, R. Roehe, John Alfred Rooke, Marie J. Haskell, Simon P. Turner', 2018, 'animal', '10.1017/s1751731118000617', 'https://doi.org/10.1017/s1751731118000617', 'https://www.sciencedirect.com/science/article/pii/S1751731118000617/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'In beef cattle, feeding behaviour and activity are associated with feed efficiency and methane (CH4) emissions. This study aimed to understand the underlying traits responsible for the contribution of cattle behaviour to individual differences in feed efficiency, performance and CH4 emissions. A total of 84 steers (530±114 kg BW) of two different breeds (crossbreed Charolais and Luing) were used. The experiment was a 2×2×3 factorial design with breed, basal diets (concentrate v. mixed) and dietary treatments (no additive, calcium nitrate or rapeseed cake) as the main factors. The individual dry matter intake (DMI; kg) was recorded daily and the BW was measured weekly over a 56-day period. Ultrasound fat depth was measured on day 56. Based on the previous data, the indexes average daily gain, food conversion and residual feed intake (RFI) were calculated. The frequency of meals, the duration per visit and the time spent feeding per day were taken as feeding behaviour measures. Daily activity was measured using the number of steps, the number of standing bouts and the time standing per day. Agonistic interactions (including the number of contacts, aggressive interactions, and displacements per day) between steers at the feeders were assessed as indicators of dominance. Temperament was assessed using the crush score test (which measures restlessness when restrained) and the flight speed on release from restraint. Statistical analysis was performed using multivariate regression models. Steers that spent more time eating showed better feed efficiency (P=0.039), which can be due to greater secretion of saliva. Feeding time was longer with the mixed diet (P<0.001), Luings (P=0.009) and dominant steers (P=0.032). Higher activity (more steps) in the pen was associated with poorer RFI, possibly because of higher energy expenditure for muscle activity. Frequent meals contributed to a reduction in CH4 emissions per kg DMI. The meal frequency was higher with a mixed diet (P<0.001) and increased in more temperamental (P=0.003) and dominant (P=0.017) steers. In addition, feed intake was lower (P=0.032) in more temperamental steers. This study reveals that efficiency increases with a longer feeding time and CH4 emissions decrease with more frequent meals. As dominant steers eat more frequently and for longer, a reduction in competition at the feeder would improve both feed efficiency and CH4 emissions. Feed efficiency can also be improved through a reduction in activity. Selection for calmer cattle would reduce activity and increase feed intake, which may improve feed efficiency and promote growth, respectively.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f630ffab-029f-4934-b002-7785a261bc87', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Utilization of Stockpiled Perennial Forages in Winter Feeding Systems for Beef Cattle', 'Ruwini Gamage', 2014, 'HARVEST (University of Saskatchewan)', NULL, 'https://hdl.handle.net/10388/ETD-2014-04-1500', 'https://harvest.usask.ca/bitstreams/6afa385c-836b-425b-a882-06950ff3fcf5/download', NULL, NULL, 126, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('30380af4-084f-4459-be52-ffc22ec783ff', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Evaluation of exit velocity and serum markers of cattle temperament during the feedlot period in steers', 'Nicole C Burdick Sanchez, J W Dailey, Jeff A Carroll, Paul Rand Broadway, Kristin E Hales', 2026, 'Frontiers in Animal Science', '10.3389/fanim.2026.1864823', 'https://doi.org/10.3389/fanim.2026.1864823', 'https://www.frontiersin.org/journals/animal-science/articles/10.3389/fanim.2026.1864823/pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc-by', 'This study evaluated changes in exit velocity (EV) and blood stress and metabolic markers as they relate to cattle temperament during the feedlot period in beef steers. Steers [n = 245; 248 ± 24 kg incoming body weight (BW)] were received in two source blocks. Steers were processed on arrival (Initial; d0), interim (d126 for Block 1, d123 for Block 2), and final (d252 for Block 1, d242 for Block 2). At processing, BW and EV was recorded, and blood samples were collected. For this study, EV was the rate of speed of a steer traversing a distance of 2.37 m after exiting a working chute. Based on EV, steers were placed in temperament classifications [Calm (n = 47), Intermediate (n = 152), or Temperamental (n = 46)]. Blood samples from the 16 most Calm and 16 most Temperamental were analyzed for glucose, non-esterified fatty acids (NEFA), cortisol, lactate, and hematology. There was a treatment × time interaction ( P < 0.01) for EV. Exit velocity decreased over time ( P < 0.01) for Intermediate and Temperamental steers, while EV increased from initial to interim measurements before decreasing at final measurement in Calm steers ( P < 0.01). Exit velocity decreased as BW increased ( P < 0.01). The EV of Temperamental steers decreased at a faster rate than Intermediate steers as BW increased ( P < 0.01), and the EV of Calm steers was not affected by BW ( P = 0.52). There was a temperament × day interaction ( P ≤ 0.01) for hemoglobin and mean corpuscular volume, and a tendency ( P = 0.06) for a temperament × day interaction for hematocrit, platelets, and percentage of monocytes. Also, red blood cells were greater while mean corpuscular hemoglobin was less in Temperamental than Calm steers ( P ≤ 0.05). Serum cortisol, glucose, and lactate concentrations were greater ( P < 0.01) in Temperamental than Calm steers, while NEFA concentrations were not different ( P = 0.54). This study is one of the first to report effects of cattle temperament on hematological variables in steers during the feedlot of cattle production, and support previously reported serum biomarkers for temperament in cattle.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('89c281aa-3e4a-4a83-a218-ecb0c5686c62', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Evaluation of Handling Equipment Sound Pressure Levels as Stressors in Beef Cattle', 'Lyvers, Christina M.', 2013, 'MSc thesis, Biosystems and Agricultural Engineering, University of Kentucky (UKnowledge)', NULL, 'https://uknowledge.uky.edu/bae_etds/13/', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'free-to-read institutional repository (the advertised full-text download URL returns 403 to automated requests; exact terms unknown)', 'The only study that varied sound level and frequency systematically in cattle, and it is a null result that matters. 18 beef animals were exposed over six weeks to recorded sounds at two frequencies (1 kHz and 8 kHz) and three intensities (40, 80 and 120 dB), with heart rate, eye temperature and sudden movement measured. Results were mixed and the author concluded that none of the sound pressure levels tested clearly affected cattle stress. This is an important counterweight to the ''over 85 dB'' threshold that Grandin''s 2021 review attributes to this very thesis - the review asserts a threshold the underlying data do not demonstrate. The thesis is also the source of the frequently cited figure that commercial handling systems reach 99-115 dB. A designer should therefore flag noise sources and equipment types rather than enforce a decibel cut-off.', '{behaviour,noise,dB-thresholds,null-result,frequency,heart-rate,thesis,counter-evidence,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('19a41ac4-b273-40c5-9470-305cbef43680', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Evaluation of the inter-relationships of temperament, stress responsiveness and immune function in beef calves', 'R.A. Oliphint', 2006, 'OakTrust (Texas A&M University Libraries)', NULL, 'https://hdl.handle.net/1969.1/3981', 'https://hdl.handle.net/1969.1/3981', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cec06ad2-253a-4062-bd8c-ecbab28948b4', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Exploring dairy heifers'' consistency in social motivation in the absence or presence of conspecifics', 'Kappel, Sarah; Nogues, Emeline; Weary, Daniel M.; von Keyserlingk, Marina A. G.', 2025, 'PLoS ONE 20(10):e0334000', '10.1371/journal.pone.0334000', 'https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0334000', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0334000&type=printable', NULL, NULL, 17, NULL, 'canada', 3, 'CC-BY 4.0', 'University of British Columbia work, and a necessary brake on any attempt to score individual animals for isolation tolerance. 36 Holstein heifers were put through standardised social-isolation tests (novel arena, novel object and runway, each tested twice 14 days apart) plus a novel social-feed trade-off paradigm and a distribution test. The authors found no consistency between sociability measures derived from behaviour in the absence of conspecifics (vocalization, runway latency) and those derived in their presence (feeding time, social-feed trade-off score), and behaviours showed low repeatability even within the same social context. They conclude that individual differences in sociability are likely context-dependent and that sociability ''might not be a single trait, but rather a behavioral consequence''. The implication for software: an animal''s isolation response cannot be predicted from a prior test, so a lone-animal rule must apply to every animal rather than to a flagged subset.', '{behaviour,isolation,sociability,repeatability,context-dependent,no-individual-trait,canadian,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d7cd8a66-2a5c-4d6f-8bd6-16c332d78094', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Factors that impede animal movement at slaughter plants', 'Grandin, Temple', 1996, 'Journal of the American Veterinary Medical Association 209(4):757-759 (with companion American Association of Bovine Practitioners Proceedings 29:22-26)', NULL, 'https://grandin.com/welfare/general.session.html', NULL, NULL, NULL, NULL, NULL, 'canada', 5, 'free-to-read author-hosted HTML at grandin.com (journal version unknown)', 'The origin of the distraction checklist, and the only source giving frequencies for balking causes - based on a survey of Canadian slaughter operations, 33 for distractions and 29 systems for floors. Lighting too dim or too bright caused excessive balking in 5 of 33 operations (15%); ventilation air blowing toward approaching animals in 3 of 33 (9%); seeing movement or sparkling reflections in 8 of 33 (24%); high-pitched motor noise or hissing air exhausts in 8 of 33 (24%), of which five were hissing air and three motor whine. Air hissing from control valves caused balking in 4 of 12 beef plants (33%). Floors: 8 of 29 (27%) had excellent grip, 15 (52%) acceptable, and 6 (21%) were slick and unacceptable. Two plants (9%) had distractions severe enough that handlers prodded constantly. Note what is named as a distraction but given no frequency figure: shadows, drain grates, and changes of fencing or flooring type - so those rules remain observation even in the one paper that counts things. The conclusion is that simple changes to lighting and the elimination of air drafts and hissing greatly improve movement. Free full text with the survey tables is hosted on grandin.com as HTML, not PDF.', '{behaviour,balking-survey,distractions,lighting,air-draft,hissing,noise,flooring,slick-floor,percentages,canadian,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b63f0ac-a16e-4320-8c73-c3bb922b65ba', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Genetics of cattle temperament and its impact on livestock production and breeding – a review', 'Juliane Friedrich, Bodo Brand, M. Schwerin', 2015, 'Archives animal breeding/Archiv für Tierzucht', '10.5194/aab-58-13-2015', 'https://doi.org/10.5194/aab-58-13-2015', 'https://aab.copernicus.org/articles/58/13/2015/aab-58-13-2015.pdf', NULL, NULL, 9, NULL, 'other', 1, 'cc-by', 'Abstract. Cattle temperament, which describes individual behaviour differences with regard to a stressor or environmental challenge, is known for its impact on working safety, adaptability to new housing conditions, animal productivity and for evaluation of animal welfare. However, successful use of temperament in animal breeding and husbandry to improve keeping conditions in general or animal welfare in particular, requires the availability of informative and reproducible phenotypes and knowledge about the genetic modulation of these traits. However, the knowledge about genetic influences on cattle temperament is still limited. In this review, an outline is given for the interdependence between production systems and temperament as well as for the phenotyping of cattle temperament based on both behaviour tests and observations of behaviour under production conditions. In addition, the use of temperament as a selection criterion is discussed.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9218d950-3a6a-4850-9787-7feb2a573423', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Genome-Wide Association Study between Single Nucleotide Polymorphisms and Flight Speed in Nellore Cattle', 'Tiago S. Valente, Fernando Sebastian Baldi, Aline Cristina Sant’Anna, Lúcia Galvão de Albuquerque, Mateus José Rodrigues Paranhos da Costa', 2016, 'PLoS ONE', '10.1371/journal.pone.0156956', 'https://doi.org/10.1371/journal.pone.0156956', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0156956&type=printable', NULL, NULL, 18, NULL, 'other', 1, 'cc-by', 'INTRODUCTION: Cattle temperament is an important factor that affects the profitability of beef cattle enterprises, due to its relationship with productivity traits, animal welfare and labor safety. Temperament is a complex phenotype often assessed by measuring a series of behavioral traits, which result from the effects of multiple environmental and genetic factors, and their interactions. The aims of this study were to perform a genome-wide association study and detect genomic regions, potential candidate genes and their biological mechanisms underlying temperament, measured by flight speed (FS) test in Nellore cattle. MATERIALS AND METHODS: The genome-wide association study (GWAS) was performed using a single-step procedure (ssGBLUP) which combined simultaneously all 16,600 phenotypes from genotyped and non-genotyped animals, full pedigree information of 162,645 animals and 1,384 genotyped animals in one step. The animals were genotyped with High Density Bovine SNP BeadChip which contains 777,962 SNP markers. After quality control (QC) a total of 455,374 SNPs remained. RESULTS: Heritability estimated for FS was 0.21 ± 0.02. Consecutive SNPs explaining 1% or more of the total additive genetic variance were considered as windows associated with FS. Nine candidate regions located on eight different Bos taurus chromosomes (BTA) (1 at 73 Mb, 2 at 65 Mb, 5 at 22 Mb and 119 Mb, 9 at 98 Mb, 11 at 67 Mb, 15 at 16 Mb, 17 at 63 Kb, and 26 at 47 Mb) were identified. The candidate genes identified in these regions were NCKAP5 (BTA2), PARK2 (BTA9), ANTXR1 (BTA11), GUCY1A2 (BTA15), CPE (BTA17) and DOCK1 (BTA26). Among these genes PARK2, GUCY1A2, CPE and DOCK1 are related to dopaminergic system, memory formation, biosynthesis of peptide hormone and neurotransmitter and brain development, respectively. CONCLUSIONS: Our findings allowed us to identify nine genomic regions (SNP windows) associated with beef cattle temperament, measured by FS test. Within these windows, six promising candidate genes and their biological functions were identified. These results may contribute to a better comprehension into the genetic control of temperament expression in Nellore cattle.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0042850a-b608-4572-959e-1bb1077b7270', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'How Farm Animals React and Perceive Stressful Situations Such As Handling, Restraint, and Transport', 'Grandin, Temple; Shivley, Chelsey', 2015, 'Animals 5(4):1233-1251 (MDPI)', '10.3390/ani5040409', 'https://doi.org/10.3390/ani5040409', 'https://mdpi-res.com/d_attachment/animals/animals-05-00409/article_deploy/animals-05-00409.pdf', NULL, NULL, NULL, NULL, 'other', 3, 'CC-BY 4.0', 'An open-access review of how cattle, sheep and pigs perceive handling and restraint, useful mainly for calibrating expectations about effect sizes. Physiological stress after handling and restraint is highly variable, ranging from near baseline to extremely high between individuals, so a facility effect will be buried in animal variation unless sample sizes are large. Isolation from herd or flock mates is highly stressful to both sheep and cattle, which is the motivational basis for the ''they move back toward their herdmates'' rule. Reactive temperaments show higher cortisol, glucose and lactate and more agitation, and an animal carefully acclimated to handling may re-enter a restrainer willingly with very low cortisol.', '{behaviour,review,stress-physiology,individual-variation,herd-isolation,temperament,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e887dfc-ffd6-4860-8b49-02edb9303d7a', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Impact of the temperament of Nellore cows on the quality of handling and pregnancy rates in fixed-time artificial insemination', 'Paola Moretti Rueda, Aline Cristina Sant’Anna, Tiago S. Valente, Mateus José Rodrigues Paranhos da Costa', 2015, 'Livestock Science', '10.1016/j.livsci.2015.04.021', 'https://doi.org/10.1016/j.livsci.2015.04.021', 'https://www.sciencedirect.com/science/article/pii/S1871141315002218/pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('920286b5-d446-4a77-8946-c57610d19da8', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Individual differences in the reaction of beef cattle to situations involving social isolation, close proximity of humans, restraint and novelty', 'Kilgour, Robert J.; Melville, Gavin J.; Greenwood, Paul L.', 2006, 'Applied Animal Behaviour Science 99(1-2):21-40', '10.1016/j.applanim.2005.09.012', 'https://doi.org/10.1016/j.applanim.2005.09.012', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'unknown (Elsevier, closed access)', 'Measured within-herd variance in beef cattle responses to human proximity, social isolation, restraint and novelty, and the cleanest demonstration that this variance is large. The design consequence is the one a flagging engine most needs to internalise: a corral must work for the tail of the distribution, not the mean, because an engine tuned to average behaviour will pass layouts that fail the flightiest tenth of the herd. Read alongside Grandin 1993, which found 6-9% of animals violently agitated at every single restraint under gentle handling, and Kappel et al. 2025, which found that an individual''s isolation response is not even a stable trait and so cannot be pre-screened.', '{behaviour,individual-variation,human-proximity,isolation,restraint,novelty,beef-cattle,design-for-the-tail,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6494a9b0-b874-433c-ab8d-35097e86383d', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Interactions between Temperament, Stress, and Immune Function in Cattle', 'Nicole C Burdick Sanchez, R.D. Randel, Jeff A Carroll, Thomas H. Welsh', 2011, 'International Journal of Zoology', '10.1155/2011/373197', 'https://doi.org/10.1155/2011/373197', 'https://downloads.hindawi.com/journals/ijz/2011/373197.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'The detrimental effects caused by stressors encountered by animals during routine handling can pose economic problems for the livestock industry due to increased costs ultimately borne by the producer and the consumer. Stress adversely affects key physiological processes of the reproductive and immune systems. In recent years stress responsiveness has been associated with cattle behavior, specifically temperament. Cattle with more excitable temperaments, as measured by chute score, pen score, and exit velocity (flight speed), exhibit greater basal concentrations of glucocorticoids and catecholamines. Similar to stressed cattle, more temperamental cattle (i.e., cattle exhibiting greater exit velocity or pen and chute scores) have poorer growth performance, carcass characteristics, and immune responses. Thus, understanding the interrelationship of stress and temperament can help in the development of selection and management practices that reduce the negative influence of temperament on growth and productivity of cattle. This paper discusses the relationship between stress and temperament and the developing evidence of an effect of temperament on immune function of cattle that have been handled or restrained. Specifically, the paper discusses different methodologies used to measure temperament, including chute score, pen score, and exit velocity, and discusses the reaction of cattle to different stressors including handling and restraint.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('90909ac5-cf89-4d09-94e4-d1ff5a2228f8', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Whole-Genome Analysis of Escherichia coli from One Health Sources: Evaluating Genetic Relatedness and Antimicrobial Resistance Carriage', 'Butters A, Jovel J, Gow S, Waldner C, Checkley SL', 2025, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics14111151', 'https://doi.org/10.3390/antibiotics14111151', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12649636.1/PMC12649636.1.pdf', NULL, NULL, 26, NULL, 'alberta', 4, 'cc by', 'Background/Objectives: Due to the numerical dominance of environmental and commensal strains, understanding antimicrobial resistance (AMR) transmission in Escherichia coli requires consideration of non-clinical as well as pathogenic isolates. In this cross-sectional study, associations between the genetic context of non-clinical E. coli and AMR carriage are examined in isolates sampled from different niches within a One Health continuum. Methods: Two hundred eighty-eight E. coli isolates collected in Alberta, Canada (2018-2019) from wastewater, well water, feces of broiler chickens and feedlot cattle, and retail beef and chicken meat were selected from existing surveillance collections using a stratified random sampling structure. Using short-read whole genome assemblies, phylogenetic relationships were inferred from pan-genome multiple sequence alignments. Principal coordinate analysis and permutational analysis of variance (PERMANOVA) of a Jaccard dissimilarity matrix derived from gene presence/absence data were used to investigate contributions of source and AMR strata to observe genetic dissimilarity. Population clustering and gene under- or over-representation by source and cluster were also explored. Results: Minimal phylogenetic segregation of isolates was noted based on source or AMR strata, and both contributed significant but small proportions of observed genetic dissimilarity, with the largest proportion attributed to phylogroup. There was notable diversity of E. coli within and between sources; however, in some larger clusters, differential gene presence/absence was potentially linked to ecological niche rather than source of isolation. Conclusions: This study highlights the ecological complexity of AMR in E. coli in non-clinical contexts, offering a novel lens on how niche-specific factors can influence population structure and AMR carriage. It also provides insight into apparent discrepancies in the literature regarding clustering of E. coli by source. These findings support a more integrative One Health approach to AMR surveillance, emphasizing the need to account for microbial diversity and niche-specific adaptation across interconnected systems.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd5469d0-556e-4534-a878-10089b9a1347', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Livestock Handling Facilities (Illinois Grazing Manual fact sheet)', 'USDA Natural Resources Conservation Service', 2022, 'USDA Natural Resources Conservation Service', NULL, 'https://www.nrcs.usda.gov/', 'https://www.nrcs.usda.gov/sites/default/files/2022-09/Livestock-handling-Facilities-Designs.pdf', NULL, NULL, NULL, NULL, 'other', 3, 'US federal government work - effectively public domain', 'A US federal agency design sheet with layout drawings and dimensions. Its value here is one independent number: it specifies a minimum curved-race radius of 15 ft (approximately 4.6 m), which is a useful cross-check on Grandin''s 3.5-6 m band and sits at the upper end of it. Being a federal work, it is the only design-standard document in this set that is unambiguously free to redistribute.', '{behaviour,design-standards,radius,government,public-domain}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('af9ede61-b2af-484b-8bd5-7f343b382f43', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Livestock Handling Guide', 'Grandin, Temple (industry guide, hosted by Ohio State University Dairy Extension)', 2007, 'Meat and Poultry industry guide, hosted by Ohio State University', NULL, 'https://dairy.osu.edu/', 'https://dairy.osu.edu/sites/dairy/files/imce/PDF/Livestock_Handling_Guide_454101_7.pdf', NULL, NULL, 7, NULL, 'other', 3, 'unknown (free-to-read, university-hosted)', 'Sets 20 degrees as the maximum for permanent loading ramps and 25 degrees for portable or adjustable ramps, with lighting, flooring and crowd-pen guidance alongside. Included as an independent cross-check on the ramp-angle convention, which is otherwise carried entirely by Grandin''s own publications and by extension sheets derived from them.', '{behaviour,ramp-slope,lighting,flooring,design-standards}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b1767e38-f672-4bde-96f1-cf3bfb8a6e4c', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Livestock Psychology and Handling-Facility Design', 'Iowa Beef Center, Iowa State University', 2016, 'Iowa Beef Center, Iowa State University', NULL, 'https://www.iowabeefcenter.org/', 'https://www.iowabeefcenter.org/bch/HandlingFacility.pdf', NULL, NULL, 7, NULL, 'other', 3, 'free-to-read publisher PDF (university extension; no explicit open licence)', 'Companion extension handout to the feedlot behaviour sheet, covering crowd-pen and race layout rules plus the 20 degree maximum for non-adjustable livestock ramps, which it attributes to Grandin (1979). Useful mainly as an independent restatement of the same conventional dimension set, which helps establish where the published numbers agree and where they drift.', '{behaviour,extension,ramp-slope,design-rules,crowd-pen}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('12859b03-f5a7-4fd0-9609-b9219797698e', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Luminance and glare in indoor cattle-handling facilities', 'Klinglmair, K.; Stevens, K. B.; Gregory, Neville G.', 2011, 'Animal Welfare 20(2):263-269', '10.1017/S0962728600002748', 'https://www.cambridge.org/core/journals/animal-welfare/article/luminance-and-glare-in-indoor-cattlehandling-facilities/3FC0C1FBB81FB3F2F79382FEF20BAC8C', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown (paywalled; Cambridge redirects the PDF path to HTML and purchase is listed as temporarily unavailable)', 'The best-quantified light-and-balking result in the whole literature, and the natural basis for a glare-geometry check in a corral designer. The authors surveyed sources of glare and the range of luminance in eleven UK cattle abattoirs, then experimentally manipulated reflected glare from a footbath in a dairy milking parlour. Mean luminance fell from 240,000 cd/m2 outdoors to 100 cd/m2 in the stunning pen - a drop of roughly 2,400 to 1 along the animal''s path. In five of the eleven abattoirs, glare off wet floor surfaces was three times the luminance of adjacent darker areas and glare off shiny metal was ten times. In the parlour experiment, balking frequency rose significantly from 10% to 23% when reflected glare increased from 0 with no bulb to 873 cd/m2 with a 100 W bulb, and significantly fewer animals balked at the afternoon than the morning milking. Note that it reports luminance in cd/m2 only, with no lux values, so the units must not be converted loosely in software. This is the only controlled glare manipulation found, and it roughly doubled balking.', '{behaviour,balking,glare,luminance,wet-floor,shiny-metal,controlled-measurement,cd-per-m2,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('95871e74-6b09-4c3e-aba8-8fb6af99f959', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The behaviour and movement of cattle through single-file races', 'Vowles, W. J.; Eldridge, G. A.; Hollier, T. J.', 1984, 'Proceedings of the Australian Society of Animal Production 15:767', NULL, 'http://www.grandin.com/references/design.construction.facilities.handling.cattle.html', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown', 'The direct head-to-head test of straight versus curved single-file races, and it is a null result: with continuously moving livestock there was no significant difference between straight and curved races in run-through time. Grandin reports this herself in her 1997 review and reconciles it with the 1982 positive result by arguing that the curve helps only when animals are queued rather than moving continuously. A one-page conference abstract, so the sample, the race dimensions and the statistics cannot be inspected. This is the paper to cite when asked whether a straight race should be flagged as a layout fault - it says it should not, and the popular literature consistently omits it. No free PDF exists and no catalogue record was located; the citation is transcribed from the reference list of Grandin 1997.', '{behaviour,curved-race,straight-race,null-result,run-through-time,throughput,conference-abstract,evidence-base,must-cite,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e93d6245-f74d-4ea5-8ed6-25514a92cadc', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Measurement of Temperament in Beef Cattle and its Relationships to Animal Production Characteristics', 'T. Hefin Jones', 2013, 'The Atrium (University of Guelph)', NULL, 'http://hdl.handle.net/10214/7569', 'http://hdl.handle.net/10214/7569', NULL, NULL, 101, NULL, 'other', 1, 'cc-by-nd', 'This thesis is an investigation of the outcomes and relevance of three different temperament assessment techniques in beef cattle. In the first study, temperament of feedlot beef cattle (n = 708) was assessed using three techniques, chute temperament score, chute exit speed and exposed eye white percentage (EW), and the resulting outcomes were compared. Repeatability of these techniques was investigated at one farm location; repeated over two consecutive days. Lastly, the accuracy and repeatability of the technique used to determine EW was investigated. Results showed some significant, but low correlations between temperament assessment techniques; chute temperament score and chute exit speed (0.26561; P < 0.0001); chute temperament score and EW (0.13660; P = 0.0008); and chute exit speed and EW (-0.01443; P = 0.7340). The correlations between repeated measures varied depending on the technique used. Chute exit speed measured on day 1 and day 2 had the highest correlation among the 3 techniques (0.6605; P <0.0001), suggesting this may be the most consistent temperament assessment technique. Repeated measures of chute temperament score and exposed EW had low correlations between consecutive days (0.3656; P < 0.0001) and (0.1040; P = 0.0495), respectively. The correlation between repeated tracings of the same exposed EW image was 0.66129 (P < 0.0001) and 0.89157 (P < 0.0001) for image 1 and image 2, respectively. In the second part of the study, the temperament assessments from the three techniques for the same group of cattle were compared to select live animal body composition parameters, production efficiency traits and meat quality characteristics. Results indicated that as exposed EW increased by 1 percent, backfat decreased 0.0284 mm (P < 0.20); as chute exit speed increased by 1 m/s, marbling score increased by 0.349 (P < 0.0001); as chute temperament score increased by 1, depth of the loin muscle increased 0.742 mm (P < 0.005). As chute temperament score increased by 1, ADG increased by 0.181 kg/day (P < 0.05); and as exposed EW increased by 1 percent, ADG increased by 0.031 kg/day (P < 0.05). There was no significant relationship found between RFI or shear force and any of the three temperament assessment techniques. Overall findings indicate some temperament assessment techniques are related to specific parameters of interest, and in general, more agitated or reactive temperament cattle may take a longer time on feed to achieve desired backfat thickness for finishing, but have higher marbling scores and muscle depth at time of assessment.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('226f2140-3667-47d6-aca6-79f33a476b2f', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Methods of Assessing Cattle Temperament and Factors Affecting it: a review', 'Jože Smolinger, Dejan Škorjanc', 2021, 'Agricultura Scientia', '10.18690/agricultura.18.1-2.23-37.2021', 'https://doi.org/10.18690/agricultura.18.1-2.23-37.2021', 'https://journals.um.si/index.php/agricultura/article/download/1645/1409', NULL, NULL, 15, NULL, 'other', 1, 'cc-by-nc-nd', 'In animal husbandry, the herd should consist of animals that are well adapted to a particular environment, which allows a safe working environment and the achievement of optimal production and economic results. Animals react differently to both positive and negative factors of the environment. Individual response to novel situations can affect metabolism as well as various physiological systems. A number of biochemical characteristics can be used as markers for assessing temperament. Temperament can also be defined as a combination of characteristics or qualities that form individual distinctive character. In this review article, we present various methods of assessing cattle temperament, firstly, in environments familiar to the animal, such as the barn and milking parlor, secondly, in unfamiliar special rooms or arenas with special equipment and, thirdly, considering other possible effects on the expression of temperament. Measurement of stress markers in saliva, feces, and hair using noninvasive methods has also been described as one of the approaches to assess temperament. Knowledge of cattle temperament allows us to work safely, introduce appropriate adapted breeding technologies, and improve housing conditions, which, consequently, results in improved animal welfare.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4b325040-3b9d-422e-a956-e6dea36f7fb2', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'MP239 Cattle Working Facilities', 'University of Arkansas System Division of Agriculture, Cooperative Extension Service (adapted in part from R. Gill and R. Machen, Texas A&M AgriLife Extension)', 2015, 'University of Arkansas Division of Agriculture, publication MP239-PD-7-2015-RV', NULL, 'https://www.uaex.uada.edu/publications/pdf/MP239.pdf', 'https://www.uaex.uada.edu/publications/pdf/MP239.pdf', NULL, NULL, 49, NULL, 'other', 5, 'free-to-read publisher PDF (US land-grant extension publication; no explicit open licence)', 'The most complete single extension document for ranch-scale corral dimensions, in the imperial units the ranch thinks in, and the only one giving a full Bud Box dimension table alongside the classic working-facility table. Table 2 gives holding area 14/18/20 sq ft per head, crowding pen 6/10/12 sq ft per head, straight-sided working chute 18/22/26 inches at a minimum 20 ft length, sloping-sided chute bottom 15/15/16 inches and 20/24/28 inches at 4 ft height, chute and corral fence heights split by gentle versus wild cattle up to 72 inches, and loading chute width, length and rise plus ramp heights by vehicle type. The footnote gives the bull answer: add 4 inches to chute widths for bulls over 2,000-2,200 lb and cows over 1,300-1,400 lb. Table 1 gives Bud Box width and depth by handler mode (12 ft and minimum 20 ft on foot; 14 ft and 20-30 ft afoot and horseback; 16 ft and maximum 30 ft horseback). The text supplies crowd-alley capacity rules, the 12 ft two-mature-cow-body-lengths straight exit rule, the adjustable-alley range of 18-30 inches, the statement that calf injury occurs when calves can turn around in an alley sized for mature cattle, the ''never fill a crowding pen more than three-quarters full'' guideline, the isolation passage (''Many serious cattle-handling accidents have been caused by isolated, frantic cattle... A gentle calf will keep an excited calf calm''), and the rule that cows and preweaned calves must not be worked through the facility together.', '{behaviour,dimension-table,race-width,crowd-pen-area,bud-box,crowd-alley-capacity,turn-around,backup-stop,isolation,cow-calf-separate,imperial}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9496f43-d211-4145-9c4f-3848eb9c49b7', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Novel genes involved in the genetic architecture of temperament in Brahman cattle', 'Francisco Alejandro Paredes Sánchez, Ana María Sifuentes‐Rincón, Eduardo Casas, Williams Arellano‐Vera, Gaspar Manuel Parra‐Bracamonte, David Greg Riley, Thomas H. Welsh, R.D. Randel', 2020, 'PLoS ONE', '10.1371/journal.pone.0237825', 'https://doi.org/10.1371/journal.pone.0237825', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0237825&type=printable', NULL, NULL, 13, NULL, 'other', 1, 'public-domain', 'Cattle temperament is a complex and economically relevant trait. The objective of this study was to identify genomic regions and genes associated with cattle temperament. From a Brahman cattle population of 1,370 animals evaluated for temperament traits (Exit velocity-EV, Pen Score-PS, Temperament Score-TS), two groups of temperament-contrasting animals were identified based on their EV-average values ±1/2 standard deviation (SD). To be considered in the calm group, the EV of females ranged between 0.16-1.82 m/s (n = 50) and the EV of males ranged between 0.4-1.56 m/s (n = 48). Females were classified as temperamental if their EV ranged between 3.13-7.66 m/s (n = 46) and males were classified as temperamental if their EV ranged between 3.05-10.83 m/s (n = 45). Selected animals were genotyped using a total of 139,376 SNPs (GGP-HD-150K), evaluated for their association with EV. The Genome-Wide Association analysis (GWAS) identified fourteen SNPs: rs135340276, rs134895560, rs110190635, rs42949831, rs135982573, rs109393235, rs109531929, rs135087545, rs41839733, rs42486577, rs136661522, rs110882543, rs110864071, rs109722627, (P<8.1E-05), nine of them were located on intergenic regions, harboring seventeen genes, of which only ACER3, VRK2, FANCL and SLCO3A1 were considered candidate associated with bovine temperament due to their reported biological functions. Five SNPs were located at introns of the NRXN3, EXOC4, CACNG4 and SLC9A4 genes. The indicated candidate genes are implicated in a wide range of behavioural phenotypes and complex cognitive functions. The association of the fourteen SNPs on bovine temperament traits (EV, PS and TS) was evaluated; all these SNPs were significant for EV; only some were associated with PS and TS. Fourteen SNPs were associated with EV which allowed the identification of twenty-one candidate genes for Brahman temperament. From a functional point of view, the five intronic SNPs identified in this study, are candidates to address control of bovine temperament, further investigation will probe their role in expression of this trait.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87076187-1334-4a55-b810-b63ef18e01e1', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'PHENOTYPIC AND GENETIC RELATIONSHIPS AMONG TEMPERAMENT, IMMUNE, AND CARCASS TRAITS IN BEEF CATTLE', 'Kerri E. Bates', 2013, 'K-State Research Exchange (Kansas State University)', NULL, 'http://hdl.handle.net/2097/15888', 'http://hdl.handle.net/2097/15888', NULL, NULL, 74, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5fba32d8-a059-486f-ab11-853a415f2139', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Phenotypic relationships between residual feed intake, feeding behaviour and temperament in Western Canadian beef cattle', 'Lindsey Lippens', 2018, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/32975', 'http://hdl.handle.net/1993/32975', NULL, NULL, 180, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('30276551-16e4-48d6-a529-f808651967b3', '96fe7066-ae23-4d8a-b6d9-37a45e3ca699', 'Nutritional evaluation of forage barley varieties for silage', 'Puthenpurayil Sasidharannair, Jayakrishnannair', 2017, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/8183', 'http://hdl.handle.net/10388/8183', NULL, NULL, 213, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.86438+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d121b484-1670-4f2a-b9b9-2216c478eb48', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Practices and Applications of Convolutional Neural Network-Based Computer Vision Systems in Animal Farming: A Review', 'Guoming Li, Yanbo Huang, Zhiqian Chen, Gary D. Chesser, JOSEPH L. PURSWELL, John E. Linhoss, Yang Zhao', 2021, 'Sensors', '10.3390/s21041492', 'https://doi.org/10.3390/s21041492', 'https://www.mdpi.com/1424-8220/21/4/1492/pdf?version=1614326070', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Convolutional neural network (CNN)-based computer vision systems have been increasingly applied in animal farming to improve animal management, but current knowledge, practices, limitations, and solutions of the applications remain to be expanded and explored. The objective of this study is to systematically review applications of CNN-based computer vision systems on animal farming in terms of the five deep learning computer vision tasks: image classification, object detection, semantic/instance segmentation, pose estimation, and tracking. Cattle, sheep/goats, pigs, and poultry were the major farm animal species of concern. In this research, preparations for system development, including camera settings, inclusion of variations for data recordings, choices of graphics processing units, image preprocessing, and data labeling were summarized. CNN architectures were reviewed based on the computer vision tasks in animal farming. Strategies of algorithm development included distribution of development data, data augmentation, hyperparameter tuning, and selection of evaluation metrics. Judgment of model performance and performance based on architectures were discussed. Besides practices in optimizing CNN-based computer vision systems, system applications were also organized based on year, country, animal species, and purposes. Finally, recommendations on future research were provided to develop and improve CNN-based computer vision systems for improved welfare, environment, engineering, genetics, and management of farm animals.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec532d18-cc94-4abd-880e-7ded16d156eb', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Preslaughter stress in cattle II : management of preslaughter stress to improve carcass yield and grade in beef cattle', 'Government of Alberta', 1991, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/preslaughter-stress-cattle-ii-management-preslaughter-stress-improve-carcass-yield', 'https://open.alberta.ca/dataset/b4a6b770-fb0a-4ff7-a164-7b79093c6600/resource/d3179baf-a4a0-4a56-a3ea-62710a1def40/download/0163003308554-preslaughter-stress-cattle-ii-management-preslaughter-stress-improve-carcass-yield.pdf', NULL, NULL, 41, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study completed two experiments to evaluate the effectiveness of electrolyte supplementation in stabilizing cattle physiology following transportation. In Experiment 1, conducted at the Lacombe Research Station, 89 yearling beef bulls averaging 495 kilograms were assigned to one of four lairage treatments (zero, 12, 24, or 36 hours) after a four-hour road transport, and given or denied access to electrolyte drinks, with results showing delayed feed and water access led to elevated serum chloride, blood lactate, and urinary sodium, while electrolyte supplementation reduced live weight loss to 1.6 per cent. In Experiment 2, conducted at a commercial facility in Airdrie using 636 market-weight bulls, animals received different combinations of electrolyte or water treatments at the farm gate and/or abattoir, and those treated with electrolytes at both points or at the abattoir retained 1.1 to 1.3 per cent more carcass weight. These electrolyte-treated cattle also showed significantly fewer dark cutters (zero to 1.4 per cent) compared to 5.2 to 8.8 per cent in untreated groups. Findings from both trials indicated that electrolyte therapy improved physiological stability and helped reduce shrink in transported cattle.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('20ddf740-5aa2-403d-b6d6-7c93fbd1594c', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'PSXIV-25 Investigating the Relationship Between Maternal Protectiveness and Temperament in Beef Cattle', 'Corley D Rogers, Temple Grandin, T. E. Engle, S. L. Archibeque, Franklyn B. Garry', 2023, 'Journal of Animal Science', '10.1093/jas/skad281.627', 'https://doi.org/10.1093/jas/skad281.627', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10633735/pdf/skad281.627.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c70f183-519f-4514-884d-dab781f9aeb6', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Relationships among temperament, behavior, and growth during performance testing of bulls', 'Lockwood, S. A.; Kattesh, H. G.; Krawczel, P. D.; Kirkpatrick, F. D.; Saxton, A. M.; Rhinehart, J. D.; Wilkerson, J. B.', 2015, 'Journal of Animal Science 93', '10.2527/jas2015-9302', 'https://doi.org/10.2527/jas2015-9302', 'https://utbeef.tennessee.edu/wp-content/uploads/sites/127/2020/11/jas-0-0-jas.2015-9302-1.pdf', NULL, NULL, 7, NULL, 'other', 5, 'free-to-read publisher PDF hosted by University of Tennessee Extension (ASAS copyright)', 'The cleanest controlled measurement of habituation to a handling facility, in Angus cattle, and therefore directly transferable to a southern Alberta herd. 60 Angus bulls in six pens were pen-scored (1 docile to 5 very aggressive) on days -1, 27, 55 and 83 and run through a chute on days 0, 28, 56 and 84, with exit velocity timed over a fixed 1.83 m between infrared sensors and IceTag dataloggers on the fetlock recording steps, lying time and lying bouts. Exit velocity fell from 2.57 m/s on day 0 to 1.92, 1.59 and 1.53 m/s on days 28, 56 and 84 (P<0.05) - a 40% decline - while pen score barely changed (2.26 to 2.13); every bull exited more slowly on day 84 than day 0 (P<0.001). Pen-score-excitable bulls had greater frame score, average daily gain and backfat; exit-velocity-excitable bulls had smaller ribeye area. The authors attribute the exit-velocity decline to habituation and conclude that temperament must be reassessed in a novel environment with new handlers to separate true temperament from the ability to habituate. The practical lesson for a design tool: exit velocity moves, chute and pen scores do not, so use exit velocity if the app ever logs temperament.', '{behaviour,habituation,exit-velocity,Angus,chute,repeated-handling,pen-score,temperament}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e57e8c43-39c3-4e70-87f1-7b594eff8c32', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Researching Human-Cattle Interaction on Rangelands: Challenges and Potential Solutions', 'Creamer, Maggie; Horback, Kristina', 2021, 'Animals 11(3):725 (MDPI)', '10.3390/ani11030725', 'https://doi.org/10.3390/ani11030725', 'https://mdpi-res.com/d_attachment/animals/animals-11-00725/article_deploy/animals-11-00725.pdf', NULL, NULL, 19, NULL, 'other', 5, 'CC-BY 4.0', 'The paper closest to a southern Alberta cow-calf operation. It argues that the entire human-animal-relationship toolkit was built for confined cattle and does not transfer to rangeland, then proposes range-specific protocols: approach tests started at 10 m with the start distance adjusted to the herd''s flight-zone sensitivity; human-presence tests with an unfamiliar person within 10 m for 10 minutes; restraint tests starting 10 m away attempting to move the cow into a 2 m by 2 m marked area; testing during midday rest and drinking, near water and shade, or along grazing routes. It catalogues the existing measures and their flaws - chute score 1 to 6, explicitly subjective; exit velocity; the pen-corner docility test - and notes that domestication selected for reduced flight zones while producers deliberately retain a robust flight zone so cattle can still be herded. Critically, it gives NO numeric flight distance for range cattle: it treats that as the open problem, which is the strongest single argument against hard-coding the 50 m figure.', '{behaviour,rangeland,cow-calf,flight-distance,approach-test-protocol,measurement-gap,open-access}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('85642991-b49c-4388-b2e8-11989726ddf7', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament can be an indicator of feedlot performance and carcass merit in beef cattle', 'Kerri E. Bates, Robert L Weaber, Jennifer M Bormann, Daniel W. Moser, Janeen L. Salak‐Johnson, Christopher C. L. Chase, R. K. Peel, Hana Van Campen', 2014, 'Kansas Agricultural Experiment Station Research Reports', '10.4148/2378-5977.1458', 'https://doi.org/10.4148/2378-5977.1458', 'https://krex.k-state.edu/bitstreams/aa0c1c5c-3e2e-4bee-b118-0ea778f8fb3c/download', NULL, NULL, 5, NULL, 'northern_plains', 3, 'cc-by', 'Cattle producers historically have selected for docile temperaments simply for management convenience because calmer animals are conducive to safe environments for their peers as well as their handlers. As many producers would acknowledge, however, there seems to be a relationship between temperament and cattle health, and calmer cattle tend to frequent the working chute for treatment of disease less often. Positive correlations have been found in cattle between temperament traits (chute scores, pen scores, and chute exit velocities) and cortisol concentration in the blood, suggesting that more excitable cattle are easily stressed (Curley et al., 2006; Cooke et al., 2009). Curley et al. (2007) also found that easily excitable animals sustain elevated cortisol concentrations for a longer duration and have greater pituitary and adrenal responses following a stressor than calm cattle. Temperamental cattle have significantly higher mean temperament responses at all points (Oliphint, 2006). Higher basal serum cortisol concentrations may suggest that easily excitable cattle are chronically stressed (Curley et al., 2007), possibly resulting in a compromised immune system, illness, and decreased fat and protein deposition. This study was conducted to further investigate the relationships between cattle temperament (measured by chute score and exit velocity), immunological factors, and a range of economically relevant performance traits.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('098bd5b2-63b7-44cf-a188-2e3b1f05fdec', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament in beef cattle : methods of measurement, consistency and relationship to production', 'Thomas Sebastian', 2007, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-12112007-213618', 'http://hdl.handle.net/10388/etd-12112007-213618', NULL, NULL, 118, NULL, 'prairies', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c4c4d339-b539-4ce5-9f88-1ed23f8009b6', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament in beef cattle: Methods of measurement and their relationship to production', 'Thomas Sebastian, Jon M. Watts, Joseph M. Stookey, Fiona C. Buchanan, Cheryl Waldner', 2011, 'Canadian Journal of Animal Science', '10.4141/cjas2010-041', 'https://doi.org/10.4141/cjas2010-041', 'https://bioone.org/journals/canadian-journal-of-animal-science/volume-91/issue-4/CJAS2010-041/Temperament-in-beef-cattle--Methods-of-measurement-and-their/10.1139/CJAS2010-041.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7daf9454-c09f-4761-9f87-3064eb4bbf4a', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament PlaysKey Role in Cattle Health', 'Sandra Avant', 2013, 'Lincoln (University of Nebraska)', NULL, 'https://digitalcommons.unl.edu/usdaagresmag/8', 'http://digitalcommons.unl.edu/usdaagresmag/8', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a7db7084-b331-49e4-b21a-559954de4873', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament Type Specific Metabolite Profiles of the Prefrontal Cortex and Serum in Cattle', 'Bodo Brand, Frieder Hadlich, Bettina Brandt, Nicolas Schauer, Katharina L. Graunke, Jan Langbein, Dirk Repsilber, Siriluk Ponsuksili', 2015, 'PLoS ONE', '10.1371/journal.pone.0125044', 'https://doi.org/10.1371/journal.pone.0125044', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC4416037/pdf/pone.0125044.pdf', NULL, NULL, 21, NULL, 'other', 1, 'cc-by', 'In the past decade the number of studies investigating temperament in farm animals has increased greatly because temperament has been shown not only to affect handling but also reproduction, health and economically important production traits. However, molecular pathways underlying temperament and molecular pathways linking temperament to production traits, health and reproduction have yet to be studied in full detail. Here we report the results of metabolite profiling of the prefrontal cortex and serum of cattle with distinct temperament types that were performed to further explore their molecular divergence in the response to the slaughter procedure and to identify new targets for further research of cattle temperament. By performing an untargeted comprehensive metabolite profiling, 627 and 1097 metabolite features comprising 235 and 328 metabolites could be detected in the prefrontal cortex and serum, respectively. In total, 54 prefrontal cortex and 51 serum metabolite features were indicated to have a high relevance in the classification of temperament types by a sparse partial least square discriminant analysis. A clear discrimination between fearful/neophobic-alert, interested-stressed, subdued/uninterested-calm and outgoing/neophilic-alert temperament types could be observed based on the abundance of the identified relevant prefrontal cortex and serum metabolites. Metabolites with high relevance in the classification of temperament types revealed that the main differences between temperament types in the response to the slaughter procedure were related to the abundance of glycerophospholipids, fatty acyls and sterol lipids. Differences in the abundance of metabolites related to C21 steroid metabolism and oxidative stress indicated that the differences in the metabolite profiles of the four extreme temperament types could be the result of a temperament type specific regulation of molecular pathways that are known to be involved in the stress and fear response.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fb8a2f70-fa56-4a4f-9d03-7a3a8d887a76', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Temperament Upregulates Mitochondrial Enzymes and Negatively Affects Myofibrillar Fragmentation in Beef of Excitable Bos taurus indicus Cattle', 'Patricia Maloso Ramos, Eduardo Francisquine Delgado, Ana Cláudia da Silva, Nara Regina Brandão Cônsolo, Vinicius Laerte Silva Herreira, João Marcos Bovetto de Campos Valim, Fernanda Maria Marins Ocampos, Luiz Alberto Colnago', 2025, 'Metabolites', '10.3390/metabo15010024', 'https://doi.org/10.3390/metabo15010024', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11767555/pdf/metabolites-15-00024.pdf', NULL, NULL, 19, NULL, 'other', 1, 'cc-by', 'Background: Bos taurus indicus cattle is known to be temperamental and to produce beef with greater variability in terms of quality compared to beef of Bos taurus taurus. Cattle adaptability and resilience are of great importance to sustain beef production worldwide. Objective: The study aimed to understand early post-mortem metabolites among muscles with different fiber types profile of calm and excitable Nellore, as well as its relationship with fragmentation of beef aged up to 28 d. Methods: Animals were evaluated based on chute score and exit velocity to calculate a temperament index, which was used to classify them as calm or excitable. At slaughter, the pH and temperature declines of Triceps brachii (TB) and Longissimus lumborum (LL) were measured, muscles were sampled, and aged up to 28 d. Metabolites were determined, and sarcomere length and myofibrillar fragmentation index (MFI) were quantified. Metabolomics data were analyzed using a multivariate approach, while other traits were investigated through ANOVA. Results: The pH decline was affected by all three fixed effects investigated (temperament × muscle × time post-mortem: p = 0.016), while temperature decline was affected by muscle × time (p < 0.001). Metabolites differed among muscles and cattle temperament, with excitable cattle showing greater taurine abundance in LL, as well as greater creatine in TB 1 h post-mortem, based on the volcano plot. Sarcomere length and MFI results revealed faster and limited tenderization in excitable cattle beef. Conclusions: Altogether, results emphasized the upregulation of mitochondrial enzymes and reduced tenderization as determinants of inferior beef quality after prolonged aging in excitable cattle.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2eacb362-a008-4ed4-950f-8a7cca53f3d3', '96fe7066-ae23-4d8a-b6d9-37a45e3ca699', 'Nutritional value of suckler beef from temperate pasture systems', 'Lee MRF, McAuliffe GA, Tweed JKS, Griffith BA, Morgan SA, Rivero MJ, Harris P, Takahashi T', 2021, 'Animal : an international journal of animal bioscience', '10.1016/j.animal.2021.100257', 'https://doi.org/10.1016/j.animal.2021.100257', 'https://europepmc.org/articles/PMC8282502?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'The role of beef in human diets has been questioned over the last few decades, due largely to its typically high mass-based carbon footprint. However, recent advancements in sustainability literature challenge this paradigm based on the new theory that climate impacts of food commodities should be measured relative to their overall nutritional value rather than their nominal mass. This shift has opened a new opportunity for the global beef industry, and especially for pasture-based systems that can avoid food-feed competition for land and other resources, as beef is a nutritionally dense food. Nonetheless, the sector''s true capability to supply a wide range of nutrients for humans, consistently across multiple systems under multiple weather patterns, has not been well-documented. Using whole-system datasets from the North Wyke Farm Platform in the South West of England, we investigated the nutritional value of beef produced from the three most common pasture systems in temperate regions: permanent pasture (PP), grass and white clover (GWC) and a short-term monoculture grass ley (MG). Beef produced from these three pasture systems was analysed for key nutrients (fatty acids, minerals and vitamin E) over three production cycles (2015-2017) to determine potential differences between systems. Fatty acid, mineral and vitamin E profiles of the pasture and silage fed to each group were also assessed, with subtle differences between pastures reported. For beef, subtle differences were also observed between systems, with GWC having higher omega-6 polyunsaturated fatty acid (PUFA) concentrations than PP and MG. However, the overall nutritional quality of beef was found to be largely comparable across all systems, suggesting that temperate pasture-based beef can be classified as a single commodity in future sustainability assessments, regardless of specific sward types. A 100 g serving of temperate pasture-based beef was found to be a high source (>20% recommended daily intake: RDI) of protein, monounsaturated fatty acids, saturated fatty acids, vitamins - B2, B3, B12 and minerals - Fe, P, Zn; a good source (10-19% RDI) of vitamin - B6 and mineral - K; and a complementary source (5-9% RDI) of omega-3 PUFA, vitamin - B9 and minerals - Cu, Mg, Se. The nutritional value of a food item should be used in defining its environmental cost (e.g. carbon footprint) to make fair comparisons across different food groups (e.g. protein sources). Here, we showed that pasture-based beef had a nutrient indexed carbon footprint of between 0.19 and 0.23 Kg CO2-eq/1% RDI of key nutrients.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.86438+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9122a12a-f8bd-481a-be65-b27af532d57d', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The effect of approach direction and pace on flight distance of beef breeding cows', 'Kosako, T.; Fukasawa, M.; Kohari, D.; Oikawa, K.; Tsukada, H.', 2008, 'Animal Science Journal 79(6):722-726', '10.1111/j.1740-0929.2008.00586.x', 'https://onlinelibrary.wiley.com/doi/abs/10.1111/j.1740-0929.2008.00586.x', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown (Wiley, closed access)', 'The only controlled experiment on approach geometry versus flight distance that could be located, and it contradicts the standard claim in the handling literature. Five Japanese Black breeding cows were tested under a factorial design crossing three approach directions - FRONT toward the head, SIDE toward the foreleg and BACK diagonally toward a hind leg - with three paces of 1, 4 and 7 km/h, with flight distance defined as the shortest observer-to-cow distance at the moment of withdrawal. The flight distance in FRONT was significantly SHORTER than that in SIDE, and the faster an observer approached, the greater the flight distance. This directly contradicts the widely repeated claim that the flight zone is larger head-on, which Grandin attributes to Bud Williams by personal communication and which extension material states without citation. Caveats are real: n=5, one breed, tame breeding stock. But the designer should not hard-code ''head-on means a bigger flight zone'' as established fact, and the pace effect is the robust, defensible half of the result. The authors'' own conclusion is that the manner of approach must be standardised before flight-distance results can be shared between researchers.', '{behaviour,flight-distance,approach-angle,approach-pace,controlled-experiment,contradicts-convention,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9eef2eeb-6b84-4a92-a9b6-c94698350080', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The effect of mud on cattle motivation for feedlot or pasture environments (final report B.FLT.0158)', 'Lee, Caroline; Lea, Jim; Thomson, Peter; Pool, Kelsey; Colditz, Ian (CSIRO)', 2016, 'Meat & Livestock Australia Limited, final report B.FLT.0158', NULL, 'https://www.mla.com.au/research-and-development/reports/', 'https://www.mla.com.au/contentassets/55b7d00a8dbf4fa79d9217d7144cc600/b.flt.0158_final_report.pdf', NULL, NULL, 53, NULL, 'other', 4, 'MLA copyright - the report states reproduction in whole or part is prohibited without prior written consent, so cite and link rather than redistribute', 'A Y-maze preference experiment giving a clear, usable dose-response for mud underfoot. 60 cattle in two cohorts per pad score, with pad scores 1, 3 and 5 created artificially by hosing and stocking and defined against the Queensland feedlot pad class system (mud depth relative to hoof and leg), with IceQube fetlock accelerometers recording behaviour. Lying time was 9 hours 38 minutes at pad score 1 versus 7 hours 43 minutes at pad score 3.5 (P<0.0001) - nearly two hours of lying lost. Lying bouts were 12.2 per day versus 7.3 per day (P<0.0001). Standing and steps both changed significantly with pad score. Cattle lay 42 minutes per day longer in the paddock than the feedlot (P=0.0004). Preference for pasture was shown only when the feedlot was dry; at higher pad scores cattle showed no preference either way. The honest caveat is that depth was set by visual assessment against the class system rather than measured in millimetres - the published companion paper (Dickson et al. 2022) supplies the physical threshold, which is mud past the fetlock.', '{behaviour,mud,pad-score,lying-time,preference,feedlot,accelerometer,controlled-measurement}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2cc63f1-f121-48cc-afc4-2e06b9272e1d', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The exploration of a four-platform standing scale in the application of measuring temperament in beef cattle', 'Haipeng Yu', 2016, 'NDSU Repository (North Dakota State University)', NULL, 'https://hdl.handle.net/10365/27975', 'https://hdl.handle.net/10365/27975', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3cefbe53-fa96-4a41-aead-1aa803555c4d', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The Influence of Temperament on Body Temperature Response to Handling in Angus Cattle', 'Angela M. Lees, Hannah E. Salvin, Ian G. Colditz, Caroline Lee', 2020, 'Animals', '10.3390/ani10010172', 'https://doi.org/10.3390/ani10010172', 'https://www.mdpi.com/2076-2615/10/1/172/pdf?version=1579516753', NULL, NULL, 16, NULL, 'other', 1, 'cc-by', 'Previous studies have indicated that cattle with more excitable temperaments exhibit an increased stress response. The objective of this study was to investigate the relationship between temperament traits, handling, and stress-induced hyperthermia (SIH) in beef cattle. Rectal temperatures (TREC, °C) of 60 purebred Angus cattle (30 heifers, 30 steers; 235.2 ± 5.11 kg) were recorded at 20 s intervals from 30 min prior to handling until two hours post handling. All cattle were exposed to a standardized handling procedure consisting of (i) being restrained in a weighing box for 30 s; (ii) being held within the crush for 30 s; and then (iii) being restrained in a head bail for 60 s. Cattle temperaments were evaluated via three traits: (1) agitometer score (AG); (2) crush score (CS); and (3) flight speed (FS) during the handling procedure. Agitometer scores and FS measures were used to describe an AG category (AGCAT) and an FS category (FSCAT) that were used to classify animals into three temperament categories: 1, calm; 2, intermediate; and 3, temperamental. Pearson’s correlation coefficients were used to evaluate the associations between (i) AG, CS, FS, and TREC 30 min prior to entry into the weighing box (T-30) and then at 1 min intervals between time of entry into the weighing box (T0) until 10 min post-weighing (T10); and (ii) the relationship between AG, CS, and FS. The relationship between TREC and temperament traits over the 2.5 h were modeled by using a first-order autoregressive repeated measures model. Flight speed had strong to moderate associations with TREC at T-30 (r ≥ 0.37; p ≤ 0.006) and between T0 and T10 (r ≥ 0.36; p ≤ 0.01). There were moderate associations amongst TREC between T0 and T10 and CS (r ≥ 0.31; p ≤ 0.01). A weak relationship existed with CS (r = 0.16; p = 0.16). There were no associations between AG and TREC at T-30 (r ≥ −0.15; p = 0.84) or between T0 and T10 (r ≤ 0.04; p ≥ 0.4). Rectal temperature, irrespective of sex and temperament traits, was influenced by time (p < 0.0001), and maximum TREC (39.3 ± 0.04 °C) occurred between 4 and 5.7 min after entry into the weighing box. In addition, CS (p = 0.007) influenced TREC in these cattle. There were also time × temperament trait × sex interactions with the CS (p = 0.0003) and FSCAT (p = 0.043) categories; however, time × temperament trait interactions were not statistically significant. Results from this study suggest that cattle with excitable temperaments, as evaluated by FS and CS, have a greater increase in TREC. In addition, these results suggest that a relationship exists between basal TREC and FS and CS. Together, these results highlight that temperament, as assessed by FS and CS, influences both basal TREC and the peak temperature recorded following handling but does not influence the magnitude of change in TREC post handling.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce7ce350-c592-4abe-a656-53aff0bbe8c0', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The influence of yard design on the movement of animals', 'Vowles, W. J.; Hollier, T. J.', 1982, 'Proceedings of the Australian Society of Animal Production 14:597', NULL, 'https://agris.fao.org/search/en/records/64735bd808fd68d546029e85', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown', 'A one-page conference abstract, and the sole positive experimental source for the curved-race recommendation and for the much-quoted figure that circular crowding pens and curved races can reduce the time spent moving cattle by up to 50%. When cattle were queued waiting to enter a squeeze chute, the curved system was faster than the alternative. Two caveats make it weak evidence for curvature specifically: the comparison was of a complete package - a round crowd pen plus a curved race - so the curve is confounded with crowd-pen shape and fencing; and at one page its methods, sample size and statistics cannot be assessed. It also supplies, jointly with Grandin 1980, the recommended 3.5-6 m inside radius. Anyone encoding a curved-race rule in software should know that this is the paper it rests on, and should read it alongside Vowles et al. 1984a, which found no significant difference.', '{behaviour,curved-race,crowd-pen,throughput,time-to-move,confounded,conference-abstract,evidence-base,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('57785dc7-fc4b-48b0-82e6-53ce495c56a9', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The Locomotion of Dairy Cows in Passageways with Different Light Intensities', 'Phillips, Clive J. C.; Morris, I. D.; Lomas, C. A.; Lockwood, S. J.', 2000, 'Animal Welfare 9(4):421-431', '10.1017/S0962728600023009', 'https://doi.org/10.1017/S0962728600023009', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'unknown (Cambridge Core, closed access)', 'The only measured illuminance window for cattle locomotion found, and a useful target figure as distinct from a fault threshold. Two experiments. In the first, cows walked a dark versus a lit passageway on the way back from milking: in the dark they took shorter but more rapid steps, which the authors read as increasing stability. In the second, cows walked a cubicle passageway to a food reward with building intensity varying from 0 to 250 lux, with step length, stepping rate and leg-joint angles measured from video. Stepping rate again rose in the dark, giving a higher walking rate; the arcs of travel of the metacarpophalangeal joint and the fore- and hind-foot angles to the floor were reduced in the dark and were greatest at 119 lux; and the slowest walking rate was at 39 lux. The authors conclude that the optimum illumination for dairy cow locomotion may lie approximately between 39 and 119 lux. Read alongside Hitchcock and Hutson 1979 and Lindkvist et al. 2023, which between them show that absolute light level has little effect on willingness to move - so this window should inform lighting design, not generate a layout fault.', '{behaviour,lighting,lux-optimum,locomotion,gait,controlled-measurement,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('95330062-ffae-435b-9483-da3b0bd3e7b6', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The movement of farmed red deer through raceways', 'Grigor, C. M.; Goddard, P. J.; Littlewood, C. A.', 1997, 'Applied Animal Behaviour Science 52(1-2):171-178', '10.1016/S0168-1591(96)01118-9', 'https://www.sciencedirect.com/science/article/abs/pii/S0168159196011189', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'unknown (Elsevier, closed access)', 'The cleanest factorial experiment on race geometry in any ruminant, and its message is that the design literature''s priorities are backwards. Eight groups of six farmed red deer were each tested on all eight combinations of race width (0.5 m versus 1.5 m), race shape (straight versus curved) and light intensity (bright versus dim). Width dominated: entry time was 6.9 s narrow versus 2.7 s wide (P<0.001), with more overlapping of individuals in wide races. Race shape produced a significantly shorter latency to enter curved races than straight races (P<0.05) but had no significant effect on moving time or inter-animal spacing. Light intensity had no significant effect on moving time or spacing. The species caveat is real - deer are far more flighty than cattle - but this is the only study putting curvature, width and light in the same model, and it says width matters roughly 2.5 times more than shape while light intensity, as opposed to glare, matters not at all. Both nulls are directly useful to a designer deciding what to flag.', '{behaviour,curved-vs-straight,race-width,light-intensity,latency-to-enter,factorial,null-result,red-deer,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('903ad5fe-406f-46d8-9429-339ef67bddd2', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The movement of sheep around corners', 'Hutson, Geoff D.; Hitchcock, D. K.', 1978, 'Applied Animal Ethology 4(4):349-355', NULL, 'https://www.sciencedirect.com/science/journal/03043762', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'unknown (Elsevier, closed access)', 'Listed because it is the only corner-geometry experiment located in any species, and because the ''eliminate square corners'' rule that every corral guide repeats has no cattle experiment behind it at all. The result of this study could NOT be retrieved - ScienceDirect blocked every automated route and the session''s search budget was exhausted before it could be chased by another path - so no finding is characterised here. It is the highest-value remaining item for anyone wanting to put a number on the minimum corner angle a corral designer should enforce: at present the app will have to pick an angle and label it as its own convention rather than as evidence. A library request to Applied Animal Ethology volume 4 would settle it.', '{behaviour,corners,geometry,sheep,unretrieved,evidence-gap,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d54f5052-403b-4563-a6ca-0132a7b105d4', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The movement of sheep in a Y maze and the effect of light intensity on movement through a race', 'Hitchcock, D. K.; Hutson, Geoff D.', 1979, 'Australian Journal of Experimental Agriculture and Animal Husbandry 19', NULL, 'https://www.publish.csiro.au/an', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'unknown (closed access; CSIRO landing page could not be resolved)', 'A genuine factorial experiment and an important NULL result, which is why it belongs in the library even though it is sheep. Narrow and wide races were tested at four illumination levels - 1.4, 88, 350 and 1,400 lux - set independently on either side of a partition. Light intensity had little overall effect on movement; neither the degree of contrast between the two levels nor the direction of the transition, dark to bright or bright to dark, mattered; and strong light contrasts could not be used to draw sheep along a race. The only positive conclusion was that sheds should be well lit overall. Taken with Grigor et al. 1997 in red deer and Lindkvist et al. 2023 in dairy cows, this is the evidence base for the recommendation that a corral designer should flag glare and non-uniformity rather than absolute brightness or a plain dark-to-light step - and it means the widely repeated rule that ''animals move from darker to brighter areas'' failed when someone tested it directly. The companion paper on the movement of sheep on inclines, in the same journal and volume, is the only incline experiment located and its result could not be retrieved.', '{behaviour,lighting,lux,null-result,contrast,dark-to-light,race,sheep,factorial,counter-evidence,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4a75bca3-2141-4101-be79-3f70b4f31cef', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The Perception of Color by Cattle and its Influence on Behavior', 'Phillips, Clive J. C.; Lomas, C. A.', 2001, 'Journal of Dairy Science 84(4):807-813', '10.3168/jds.S0022-0302(01)74537-7', 'https://doi.org/10.3168/jds.S0022-0302(01)74537-7', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'free-to-read at publisher (bronze open access) but no verifiable direct PDF URL - journalofdairyscience.org and ScienceDirect both block automated requests', 'The methodologically decisive colour-vision study for cattle, and the basis for a hard design conclusion. Earlier work had not controlled stimulus intensity, so colour-discrimination conclusions were confounded with brightness. These authors first trained calves to discriminate light sources by INTENSITY, then matched intensities so that short, medium and long wavelengths were isoluminant to the calf. Calves then discriminated long from short (82% correct) and long from medium (89% correct), but had limited ability to separate short from medium: three of seven managed it over the first eight tests, after which all chose at random. Cattle''s upper wavelength limit is about 620 nm. Behaviour was then filmed under the isoluminant lights in novel-object, fear and handler tests: in the fear test calves got past a barrier and hid more quickly under medium (green) than short (blue) light and made the fewest movements under medium wavelength, and they were more active and more accommodating with handlers under long (red) wavelengths. The design conclusion is that cattle are dichromats who cannot reliably distinguish blue from green, so colour-coding a corral blue versus green is useless to the animal, and the variable to model is luminance contrast rather than hue.', '{behaviour,vision,colour-vision,isoluminant,dichromacy,wavelength-620nm,controlled-measurement,contrast,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('94126a1b-8cc3-4a4c-914a-c5ba6d1931b9', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The sensory world of cattle: Abilities, limitations, and perceptual challenges in human-designed environments', 'Rørvang, Maria Vilain; Meagher, Rebecca K.; Stenfelt, Johanna; Miller-Cushon, Emily K.; Ahmmad, Sheikh Rishad; Ceballos, Maria Camila', 2026, 'Applied Animal Behaviour Science 304:107117', '10.1016/j.applanim.2026.107117', 'https://doi.org/10.1016/j.applanim.2026.107117', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'CC-BY 4.0 (confirmed by Crossref and Unpaywall, but ScienceDirect returns 403 to automated requests and Unpaywall gives no direct PDF URL - worth a manual download)', 'The most comprehensive review of cattle sensory ability to date, and the current state of the art. It synthesises vision, hearing, olfaction, taste and touch, and argues that perception depends on context - cattle integrate sensory information with prior experience and emotional state, and the dominant sense shifts by situation. Its central thesis is exactly a corral designer''s thesis: mismatches between species-specific sensory capacity and human-designed environments drive behavioural responses, stress and poor human-animal interaction, and it presents a conceptual framework for assessing housing, handling routines and production practices from the animal''s perspective. Reported findings include a wide panoramic field of vision aiding predator detection, limited depth perception, slow adaptation to rapid lighting changes, and shadows, reflections and sharp contrasts causing uncertainty or fear. Notably, like Adamczyk et al. 2024, it does NOT put a degree figure on the visual field - which is itself strong evidence that the widely quoted 330 degree number has no primary cattle perimetry behind it. Co-author Maria Camila Ceballos is at the University of Calgary Faculty of Veterinary Medicine, making her the obvious local contact for the perimetry and light-adaptation gaps this review leaves open.', '{behaviour,vision,sensory-review,depth-perception,light-adaptation,design-framework,university-of-calgary,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc48ce99-063e-4c7f-b2c6-e58e56872d17', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'ECONOMICS OF CALF PRODUCTION WITH FOREIGN CATTLE BREED CROSSES IN THE PARKLAND REGION OF WESTERN CANADA', 'Elwin G. Smith, G. W. RAHNEFELD, K. K. Klein, J. E. Lawson', 1987, 'Canadian Journal of Animal Science', '10.4141/cjas87-101', 'https://doi.org/10.4141/cjas87-101', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas87-101', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf3dd4a0-fd90-46bd-86ea-e6773275f1ec', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The Stockman’s Scorecard: quantitative evaluation of beef cattle stockmanship', 'John Yost, Jarred W. Yates, Matt P Davis, Matthew E. Wilson', 2020, 'Translational Animal Science', '10.1093/tas/txaa175', 'https://doi.org/10.1093/tas/txaa175', 'https://academic.oup.com/tas/article-pdf/4/4/txaa175/35233846/txaa175.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Abstract An animal’s action, or inaction, is the direct result of a stockman’s action or inaction. The Stockman’s Scorecard is a novel observation instrument that has been proven to be a valid and reliable tool to measure the quality of beef cattle stockmanship. Specific handler actions have been weighted based on their perceived negative relationship to cattle stress from handling. The purpose of this article is to 1) document the initial use of the scorecard in a beef cattle feedlot setting and 2) provide further support to its validity by establishing an association with other quantitative and qualitative means of evaluating stockmanship. The Scorecard was used at 39 beef feedlots in Texas between March 2018 and April 2019. Eighty-four stockman were observed, and the average score received was 84.5 (SD = 14.73, range = 20 to 100). The most frequent mistakes observed were as follows: fills crowd pen/tub over half full (n = 39), slow to remove pressure (n = 29), uses unnecessary noise (n = 25), stands in front and taps rear (n = 24), and fails to regulate animal flow through a pinch point (n = 22). A strong negative association (ρ = −0.51) was found between the points deducted from the Noise and Physical Contact theme of the Scorecard and the number of animals touched with an electric prod from the BQA Feedyard Assessment. Moderate negative associations were found between the Scorecard final score and the number of animals that vocalize in the chute prior to procedures (ρ = −0.31). Those stockmen that scored above average on the Scorecard were qualitatively observed to be calm and quiet while working with the cattle (Kappa = 0.44). The qualitative disposition of cattle had little effect on the final score of stockmen using the Scorecard (Kappa = 0.17). The use of the Scorecard in a feedlot setting has demonstrated that as stockman scores decrease, there is an increase in the number of negative actions toward cattle and a negative behavioral response of the cattle themselves. Establishment of an association between a stockman’s score using the Stockman’s Scorecard and the animal-based observations from the BQA Feedyard Assessment further strengthens the validity of the Stockman’s Scorecard as a tool to measure the quality of beef cattle stockmanship. The Scorecard has application as a tool to identify specific stockmanship deficiencies in order to target stockmanship training.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7474558b-db8a-40ff-9d2d-43aec48827ae', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'The use of blood lactate concentration as an indicator of temperament and its impact on growth rate and tenderness of steaks from Simmental×Angus steers', 'J.A. Boles, K. S. Kohlbeck, Michael Clinton Meyers, Katarzyna Perz, Kathleen C. Davis, Jennifer M. Thomson', 2015, 'Meat Science', '10.1016/j.meatsci.2015.01.003', 'https://doi.org/10.1016/j.meatsci.2015.01.003', 'https://scholarworks.montana.edu/bitstreams/6967fe0c-903e-425a-a7e9-b05b342169f0/download', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dfa36b1e-fedd-4f51-8cb8-6b47deab9bb9', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Transporting cattle in 2020: research and regulation', 'Schwartzkopf-Genswein, Karen S. and colleagues (Agriculture and Agri-Food Canada, Lethbridge Research and Development Centre)', 2020, 'WCDS Advances in Dairy Technology, pp. 107-118 (University of Alberta)', NULL, 'https://wcds.ualberta.ca/', 'https://wcds.ualberta.ca/wp-content/uploads/sites/57/2020/03/p107-118-Schwartzkopf-Genswein-WCDS2020-TransportingCattleIn2020.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'free-to-read conference proceedings PDF (University of Alberta WCDS)', 'AAFC Lethbridge review, and the source of the one hard Canadian cold-weather number found anywhere in this review: González et al. (2012) reported that death in commercial cattle transported more than 400 km increased significantly when ambient temperature went below -15 C, while non-ambulatory risk rose above +30 C. Also reports Goldhawk et al. (2015) on winter transport of cull beef cows, where boarding raised in-transit ventilation but reduced ventilation and raised internal temperature and humidity during stationary periods - a reminder that stationary periods are where winter microclimate goes wrong, which applies equally to cattle held in a corral. Notes that bedding is required on journeys over 12 hours under CFIA 2019, that shrink rises about 0.04% per degree C of ambient temperature, and that calves and cull cows lose more than feeders.', '{behaviour,cold,transport,winter,mortality-threshold,shrink,AAFC-Lethbridge,canadian}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd7187d2-9ec5-4a03-9027-5e3f6560aa46', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Unraveling the phenotypic and genomic background of behavioral plasticity and temperament in North American Angus cattle', 'Amanda Botelho Alvarenga, Hinayah Rojas de Oliveira, Simon P. Turner, André Luiz Seccatto Garcia, Kelli Retallick, Stephen Paul Miller, Luiz F. Brito', 2023, 'Genetics Selection Evolution', '10.1186/s12711-023-00777-3', 'https://doi.org/10.1186/s12711-023-00777-3', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9850537/pdf/12711_2023_Article_777.pdf', NULL, NULL, 19, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Longitudinal records of temperament can be used for assessing behavioral plasticity, such as aptness to learn, memorize, or change behavioral responses based on affective state. In this study, we evaluated the phenotypic and genomic background of North American Angus cow temperament measured throughout their lifetime around the weaning season, including the development of a new indicator trait termed docility-based learning and behavioral plasticity. The analyses included 273,695 and 153,898 records for yearling (YT) and cow at weaning (CT) temperament, respectively, 723,248 animals in the pedigree, and 8784 genotyped animals. Both YT and CT were measured when the animal was loading into/exiting the chute. Moreover, CT was measured around the time in which the cow was separated from her calf. A random regression model fitting a first-order Legendre orthogonal polynomial was used to model the covariance structure of temperament and to assess the learning and behavioral plasticity (i.e., slope of the regression) of individual cows. This study provides, for the first time, a longitudinal perspective of the genetic and genomic mechanisms underlying temperament, learning, and behavioral plasticity in beef cattle. RESULTS: CT measured across years is heritable (0.38-0.53). Positive and strong genetic correlations (0.91-1.00) were observed among all CT age-group pairs and between CT and YT (0.84). Over 90% of the candidate genes identified overlapped among CT age-groups and the estimated effect of genomic markers located within important candidate genes changed over time. A small but significant genetic component was observed for learning and behavioral plasticity (heritability = 0.02 ± 0.002). Various candidate genes were identified, revealing the polygenic nature of the traits evaluated. The pathways and candidate genes identified are associated with steroid and glucocorticoid hormones, development delay, cognitive development, and behavioral changes in cattle and other species. CONCLUSIONS: Cow temperament is highly heritable and repeatable. The changes in temperament can be genetically improved by selecting animals with favorable learning and behavioral plasticity (i.e., habituation). Furthermore, the environment explains a large part of the variation in learning and behavioral plasticity, leading to opportunities to also improve the overall temperament by refining management practices. Moreover, behavioral plasticity offers opportunities to improve the long-term animal and handler welfare through habituation.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce86b722-47fb-403e-a169-f5b37dd02750', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Use of random regression to estimate genetic parameters of temperament across an age continuum in a crossbred cattle population1', 'Brittni P Littlejohn, David Greg Riley, Thomas H. Welsh, R.D. Randel, Scott T. Willard, RHONDA C. VANN', 2018, 'Journal of Animal Science', '10.1093/jas/sky180', 'https://doi.org/10.1093/jas/sky180', 'https://academic.oup.com/jas/article-pdf/96/7/2607/25109460/sky180.pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1f60586b-fe5f-4794-8efe-5aa7effd526c', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Using an observer rating method to assess the effects of rotational stocking method on beef cattle temperament over time', 'Karen Camille Rocha Góis, Maria Camila Ceballos, Aline Cristina Sant’Anna, Mateus José Rodrigues Paranhos da Costa', 2016, 'Revista Brasileira de Zootecnia', '10.1590/s1806-92902016000900001', 'https://doi.org/10.1590/s1806-92902016000900001', 'http://www.scielo.br/pdf/rbz/v45n9/1516-3598-rbz-45-09-00501.pdf', NULL, NULL, 8, NULL, 'other', 1, 'cc-by', 'The objectives of this study were to propose behavioral-based definitions for the adjectives used in an observer rating method, and to use this approach to characterize temperament over time in cattle kept under rotational stocking method. We also analyzed the feasibility of the rating method under commercial cattle farming conditions. We evaluated the temperament evolution of 1,979 pure and crossbred Nellore young bulls over time on three commercial farms located in Northeastern Pará State, Brazil. All animals were kept under a rotational stocking method. The observer rating method included 14 behaviorally predefined adjectives for which we defined the minimum and maximum scores. The first factor was considered a qualitative temperament index (QTI) ranging from ''relaxed''/''calm''/''comfortable'' to ''fearful''/''agitated''. According to the QTI, cattle temperament improved over time. For Farms A and B, QTI decreased over evaluations, and for Farm C, QTI did not differ from the first to the second evaluations, but decreased from the second assessment onwards. The observer rating method consisting of behaviorally pre-defined adjectives is an adequate indicator of cattle temperament that may be feasible under farm conditions. The method captures different aspects of cattle temperament and distinguishes between slight variations in cattle body language that successfully reveal temperament changes over time.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b32ef891-8426-4171-a921-127634e983ff', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Visual acuity of cattle determined by the method of discrimination learning', 'Entsu, S.; Dohi, H.; Yamada, A.', 1992, 'Applied Animal Behaviour Science 34(1-2):1-10', '10.1016/S0168-1591(05)80052-8', 'https://doi.org/10.1016/S0168-1591(05)80052-8', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown (Elsevier, closed access)', 'The primary measurement of bovine visual acuity, and the one vision number a geometry checker can actually compute with. Japanese Black heifers were trained to select the correct one of two simultaneously presented targets with left and right position randomised; once fully trained, acuity was determined two independent ways - by reducing target size (Test 1) and by increasing viewing distance (Test 2). Best decimal-acuity scores were 0.045/0.045 for Heifer 1, 0.083/0.083 for Heifer 2 and 0.063/0.064 for Heifer 3, the near-identical values across the two methods within each animal being the result''s main strength. Converted by Adamczyk et al. (2024) to roughly 1.3-2.5 cycles per degree, that is about one-twentieth of human acuity, or broadly a 20/200 to 20/400 equivalent. This tells a designer what size a feature must be, at a given distance, before cattle can resolve it at all - and it provides a measured mechanism for the shadow problem (shadows read as holes) that does not depend on the unmeasured depth-perception claim. For anything judged while the animal is moving, use instead Hirata et al. 2019''s field limit of about 2 m for low-contrast targets.', '{behaviour,vision,visual-acuity,discrimination-learning,primary-measurement,feature-size,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cea6f9e2-6325-47d1-be55-988dcdb67c2c', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Visual perception and stimulus orientation in cattle', 'Rehkämper, Gerd; Perrey, A.; Werner, C. W.; Opfermann-Rüngeler, C.; Görlach, Albert', 2000, 'Vision Research 40(18):2489-2497', '10.1016/S0042-6989(00)00113-3', 'https://doi.org/10.1016/S0042-6989(00)00113-3', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'unknown (Elsevier, closed access)', 'A measured orientation anisotropy in cattle vision, and a directly encodable design lever. Starting from the bovine eye''s oval, horizontally oriented pupil, the authors hypothesised that visual perception in such eyes differs for stimuli with vertically-separated details versus horizontally-separated details. Cattle solved the discrimination task better with VERTICALLY presented stimuli than horizontal ones, which the authors attribute to visual acuity and pupil anatomy. Adamczyk et al. (2024) summarise this as pupil shape and orientation enhancing the detection of vertical lines over horizontal lines, consistent with the horizontally aligned retinal visual streak documented by Brooks et al. (1999) and Kassab and Sugita (2000). The design implication is that vertical elements - a post, a vertical gate stile, a vertical stripe at a race entrance - are more detectable to cattle than horizontal ones, and conversely that horizontal rails and horizontal shadow bars are relatively poorly resolved.', '{behaviour,vision,stimulus-orientation,vertical-vs-horizontal,pupil-shape,visual-acuity,design-lever,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c416b23-33bd-47c1-ab36-40b2a822f22d', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Welfare and performance benefits of shade provision during summer for feedlot cattle in a temperate climatic zone', 'David W. Miller, A. Barnes, Teresa Collins, L. Pannier, Joshua W. Aleri, Shane Kevin Maloney, Fiona Anderson', 2024, 'Journal of Animal Science', '10.1093/jas/skae332', 'https://doi.org/10.1093/jas/skae332', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11604116/pdf/skae332.pdf', NULL, NULL, 22, NULL, 'other', 1, 'cc-by-nc-nd', 'There is increasing interest from cattle lot-feeders in the use of shade to mitigate the effects of a potential heat-stress event, though it is unclear whether the reported benefits of shade in previous studies conducted in more high-risk heat-stress zones are pertinent in cooler temperate zones. The objectives of this study were to measure the welfare and performance benefits of shade provision for lot-fed cattle at a commercial feedlot located in a mild heat-stress risk zone in Western Australia. Six blocks of black Angus (Bos taurus) steers were inducted into the feedlot over 6 time windows across a southern hemisphere summer, with 80 cattle per block housed in a partially shaded pen (providing 3.125 m2 of shade per animal) and 80 in an unshaded pen. Parameters assessed in 960 cattle over the first 70 d in the feedlot included weight gain, feed intake, and physiological and behavioral indices of overall health and welfare. Over the months of October to May in which the experiment was conducted, shaded cattle demonstrated a modest 0.13 kg overall increase in average daily gain across the 70-d feedlot period (P = 0.13). There was no difference in dry matter intake between any block or treatment. The physiological and behavioral markers of health and welfare revealed that, even during to the hottest times of the experiment, the cattle were quite able to thermoregulate, via increased panting and seeking shade (if available), to maintain physiological homeostasis. In addition, we measured the effect of heat stress and shade provision on the affective state of the cattle. Qualitative behavioral assessment was used to indicate that the cattle in the "no stress" temperature humidity index (THI) category and the shaded cattle in the "moderate stress" THI category displayed the most positive demeanor (P < 0.05), being described as more "settled and sociable", while the unshaded cattle in the "moderate stress" THI category and all cattle in the "severe stress" THI category were described as more "agitated/anxious" (P < 0.05). Overall, the findings from the present study suggest that there are definite welfare and modest performance benefits associated with providing cattle with shade in summer in a feedlot situated in a temperate climatic zone.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a44a0678-ab9f-4f9d-b6dc-31fe0f6d5539', '92d66d3c-2a01-4be0-9cad-66f9d8b00b70', 'Welfare Quality Assessment Protocol for Cattle', 'Welfare Quality Consortium', 2009, 'Welfare Quality Consortium, Lelystad', NULL, 'http://www.welfarequalitynetwork.net/', 'http://www.welfarequalitynetwork.net/media/1088/cattle_protocol_without_veal_calves.pdf', NULL, NULL, 142, NULL, 'other', 4, 'free-to-read publisher PDF', 'The on-farm welfare assessment protocol whose ''avoidance distance at the feeding place'' measure is the only fully standardised, reliability-tested flight-distance instrument in the literature. It specifies the method to the centimetre: start 3 m directly in front of the animal with its head through the feed rack, or up to 45 degrees to the rack from 3.5 m; approach at one step per second with steps of about 60 cm; hold the arm overhand at about 45 degrees from the body with the back of the hand toward the animal; make no eye contact, looking at the muzzle; walk until withdrawal or until you touch the muzzle; record hand-to-muzzle distance at 10 cm resolution over the range 300 cm down to 10 cm, or 0 cm if touchable. Individual bands are 0, under 50 cm, 50-100 cm and over 100 cm, weighted 0:3:11:26 into a herd index. Note its ceiling: 3 m. There is no validated instrument anywhere near the 50 m range-cow claim, and this protocol is the right basis for an on-ranch flight-zone calibration procedure.', '{behaviour,avoidance-distance,flight-zone,standardised-protocol,measurement-method,welfare-assessment}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b81c45d-a6ae-439b-890a-27bfdc2baa3d', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Reciprocal crossbreeding of Angus and Hereford cattle 3. Cow weight, reproduction, maternal performance, and lifetime production', 'C. A. Morris, R.Leyden Baker, D. L. Johnson, A. H. Carter, J. C. Hunter', 1987, 'New Zealand Journal of Agricultural Research', '10.1080/00288233.1987.10417957', 'https://doi.org/10.1080/00288233.1987.10417957', 'https://www.tandfonline.com/doi/pdf/10.1080/00288233.1987.10417957?needAccess=true', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d7191aac-d058-4307-91a8-c36dcf060fd3', '62d8f741-bc1d-452d-af19-eaa6ef237270', '1982 cow reproduction diary', 'Government of Alberta', 1982, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/1982-cow-reproduction-diary', 'https://open.alberta.ca/dataset/a3e7204a-f7ad-4f64-a1c5-94010a76f3b8/resource/cb6fda77-d7d6-4fc8-a6f5-1552ecb8dcfe/download/copal396-1982-cow-reproduction-diary.pdf', NULL, NULL, 166, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document was a cow reproduction diary produced by Alberta Agriculture in 1982 to support herd reproductive management. It was designed for daily recording of heat detection, breeding, calving, and cow comments across a full calendar year. The diary included monthly summary pages to assist with planning and predicting herd reproductive events. It also provided reference information on signs of heat and breeding due dates to guide accurate observation and record keeping.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8defb21-11bf-4642-ab74-a337e95133b5', '62d8f741-bc1d-452d-af19-eaa6ef237270', '4-H breeding record book : beef project', 'Government of Alberta', 1977, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4h-breeding-record-book-beef-project', 'https://open.alberta.ca/dataset/e1b168cd-12a3-47c7-b13d-e2ea2badd8e4/resource/e5d5bba0-1d51-4d9b-9494-1b31220e744e/download/163040850824-4h-breeding-record-book-beef-project.pdf', NULL, NULL, 28, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This guide provides a comprehensive record-keeping book for 4-H beef project members participating in either a Heifer Calf or Breeding Herd project. It includes sections for personal records, monthly comments, animal identification, weight records, feeding charts, and detailed cost and financial summaries. The resource aims to simplify calculations at the project''s conclusion and emphasizes the importance of accurate record-keeping for success in the beef industry. It also offers a heart girth-weight chart for estimating cattle weight, along with instructions for its use.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c2b224b-cba8-43de-adf6-e93ebb0adcaf', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'A randomised controlled trial investigating the effects of administering a non-steroidal anti-inflammatory drug to beef calves assisted at birth and risk factors associated with passive immunity, health, and growth', 'Pearson JM, Pajor E, Campbell J, Levy M, Caulkett N, Windeyer MC', 2019, 'Veterinary record open', '10.1136/vetreco-2019-000364', 'https://doi.org/10.1136/vetreco-2019-000364', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6803011.1/PMC6803011.1.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'cc by-nc', 'BackgroundThe objectives of this study were to investigate the impact of pain mitigation at birth to assisted beef calves and determine the risk factors associated with transfer of passive immunity (TPI), health, and growth.MethodsTwo hundred and thirty cow-calf pairs requiring calving assistance were enrolled. Calves were randomised to receive meloxicam (0.5 mg/kg) or an equivalent volume of placebo subcutaneously at birth. Calf blood samples were collected between one and seven days of age to determine serum immunoglobulin (IgG) concentration. Colostrum intake, treatment for disease, mortality, and weaning weights were recorded. Multilevel linear or logistic regression models were used to determine the effects of meloxicam and to identify risk factors.ResultsThere was no effect of meloxicam on serum IgG concentrations, average daily gain (ADG), or risk of inadequate TPI (serum IgG concentration 0.05). Bottle or tube feeding calves were associated with decreased serum IgG concentrations (P=0.01) compared with nursing. Calves with an incomplete tongue withdrawal reflex had higher odds of being treated for disease compared with those with complete withdrawal (P=0.009). Being born meconium-stained and having decreased serum IgG concentrations were associated with an increased risk of mortality (P=0.03). Being born of a mature cow, having a higher birth weight, and increased serum IgG concentrations were associated with greater ADG to weaning (PConclusionVigour assessment at birth along with good colostrum management may be important to improve TPI and health in high-risk calves such as those assisted at birth.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('abc4c25a-025d-45bf-a5b4-54684ca96402', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'An Expert Consensus Study Regarding Management Practices to Prevent Infectious Mortality in Preweaned Beef Calves in Western Canada', 'Sanguinetti VM, Adams C, Campbell J, Checkley SL, Windeyer C', 2024, 'Veterinary sciences', '10.3390/vetsci11100453', 'https://doi.org/10.3390/vetsci11100453', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11512374.1/PMC11512374.1.pdf', NULL, NULL, 13, NULL, 'alberta', 4, 'cc by', 'Disease prevention is a cornerstone of herd management for minimizing preweaning calf mortality. However, scientific evidence about the usefulness of practices in herds is scarce. The first objective was for a group of veterinarians to determine which practices are most useful considering their effectiveness, ease of implementation, and economic feasibility. A second objective was for them to define which practices should be included in a tool to facilitate discussions between producers and veterinarians. Expert opinions and consensus were determined using a modified Delphi approach. During two questionnaire rounds, participants scored the effectiveness, ease of implementation, and economic feasibility of each practice. Overall scores for each practice were calculated, and feedback reports were sent to participants between rounds showing the groups'' median responses. Consensus on which practices should be included in the tool was targeted during the workshops. Twelve veterinary experts participated. Administering clostridial vaccines and providing calves with colostrum in case they had not nursed were considered practices that were ''always useful for all herds''. However, most practices had intermediate levels of usefulness, and among these, antibiotics were considered the least useful. Nevertheless, all practices discussed during the workshops attained a consensus about being included in the future tool to facilitate on-farm discussions.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('08a019a7-a92c-4303-81c5-b26afc91cdbd', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', '“Heritage Rangeland” natural areas', 'Government of Alberta', 2018, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/heritage-rangeland-natural-areas', 'https://open.alberta.ca/dataset/d2006104-73fe-4f34-b413-543d9deb3d64/resource/fedd2b7e-aee8-4a27-bc70-009c16c340a9/download/comparison-between-natural-areas-and-heritage-rangelands-v2.pdf', NULL, NULL, 1, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet summarizes information about the background of Heritage Rangeland natural areas, the purpose of the heritage rangelands class and natural areas class, and the permitted uses and activities for Heritage Rangelands and Natural Areas classification at the Twin River site.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c0c85f46-6917-4cbf-ae57-9e5a8d0f84b8', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Beef cattle breeding for productive efficiency', 'Government of Alberta', 1986, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/beef-cattle-breeding-for-productive-efficiency', 'https://open.alberta.ca/dataset/c79416f4-d43c-4ed0-b945-81f061750320/resource/13cdb217-5465-4de3-ba46-51a7a7fbe0a9/download/163010401772-beef-cattle-breeding-for-productive-efficiency.pdf', NULL, NULL, 109, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This research used data from the University of Alberta Ranch at Kinsella and other sources to assess genetic gains and breeding traits in beef cattle. Dairy-beef crossbred cows outperformed straight beef breeds in maternally influenced traits such as weaning weight and milk production capacity. The study found that year, breed, calf sex, and dam age significantly affected preweaning traits, and that scrotal circumference and libido score were inadequate indicators of fertility. A recessive gene for double muscling was linked to altered metabolism and muscle distribution in carcasses. Crossbred mice lines selected for high body weight showed better growth and survival under cold stress than purebred lines, suggesting advantages in harsh environments.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b8ccfdc-f245-49bb-a9ad-1f16c087f5d9', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Beef cattle management decisions relating to drought in the Northern Great Plains', 'R.E. Kruse', 2002, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/8230', 'https://scholarworks.montana.edu/xmlui/handle/1/8230', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03145157-6726-4ebd-96ba-3b68c2368b74', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Breeding Bulls in Alberta: a cross-sectional descriptive survey of breeding bull herds and current management strategies', 'Daborn T, Pajor EA, Pearson JM', 2025, 'Translational animal science', '10.1093/tas/txaf082', 'https://doi.org/10.1093/tas/txaf082', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12207862.1/PMC12207862.1.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'cc by-nc-nd', 'Currently, there is very little known about bull demographics and how bulls are managed on cow-calf operations in Alberta. Identifying these knowledge gaps will provide valuable insights on producer practices and potentially influence future management protocols that will improve bull management and the productivity of cow-calf operations. The objectives of this study were to benchmark beef bull herd demographics and bull management strategies in Alberta, Canada and to investigate associations between herd demographics and management strategies. Cow-calf producers were surveyed between February and August 2022 by paper or electronic copies of the survey. Fifty-two of 72 respondents were enrolled. Forty-two percent of the respondents were seedstock producers. The median female herd size exposed for breeding was 160 cows (IQR: 57 to 275; range: 14 to 1600) as reported by 43 respondents. The most common breed of bull used was Angus, followed by Hereford. The median number of bulls kept was 9, (IQR: 4 to 15; range: 1 to 71). Roughly 1 in 6 bulls were culled with the majority of bulls being culled or treated for conditions due to musculoskeletal or infectious foot causes. The median bull:cow ratio was 1:21 (IQR: 1:11 to 1:25) for heifers and 1:23 (IQR 1:20 to 1:26) for cows. The top 3 selection considerations for replacement bulls for breeding heifers was bull birthweight, bull EPD for calving ease, and physical appearance. The selection criteria for cows were bull adjusted weaning weight, physical appearance, and foot and leg conformation. This study contributes novel information on the breeding bull demographics and management strategies of cow-calf producers in Alberta. In addition, it identifies musculoskeletal issues as the major causes of treatment, death, and culling in bulls and recommends further investigation into causes and management strategies to mitigate these issues and improve bull health and welfare.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad0b5158-526b-4777-9af4-80f246bd964c', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Breeding soundness evaluation of bulls', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2392721', 'https://open.alberta.ca/dataset/fdca7209-ea06-4013-b9b2-2cddc9229cf6/resource/4a088cf2-7c4e-4842-9096-ebd18cbffc51/download/1992-423-15-1.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Breeding success depends on the reproductive health of both the cow and the bull. Because a bull is expected to service a number of cows, determining the potential fertility of the bull is much more important than determining the fertility of any individual cow. It is essential to evaluate bulls every year before breeding starts because the fertility of an individual animal can vary from year to year. Surprisingly, only about 28 per cent of bulls in Alberta are evaluated for reproductive fitness.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9e43c80e-3f38-4c08-bc89-c2e03ed58312', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Calving', 'Government of Alberta', 2002, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2817778', 'https://open.alberta.ca/dataset/db46f1df-0eb7-4978-b85e-46acedad86e8/resource/5b32b0a4-3fdf-40a4-9946-9b192af9dbcf/download/28177782000agri-factscalving42022-11.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A description of the stages of labour for cattle and how to correct problems.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e74aee09-17f7-4075-84e0-99a91c516156', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Clinical impacts of administering a nonsteroidal anti-inflammatory drug to beef calves after assisted calving on pain and inflammation, passive immunity, health, and growth', 'Pearson JM, Pajor EA, Campbell JR, Caulkett NA, Levy M, Dorin C, Windeyer MC', 2019, 'Journal of animal science', '10.1093/jas/skz094', 'https://doi.org/10.1093/jas/skz094', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6488310.1/PMC6488310.1.pdf', NULL, NULL, 13, NULL, 'southern_alberta', 5, 'cc by-nc', 'Assisted calves are often born weak, injured, or oxygen deprived and have a higher risk of morbidity and mortality. The objective was to investigate the impact of using pain mitigation at birth in assisted beef calves on physiological indicators of pain and inflammation, passive immunity, health, and growth. Thirty-three primiparous cows and their calves requiring assistance at birth on two ranches located in southern Alberta were enrolled. Data collected at birth include date and time of calving, calf sex, meconium staining, presentation of calf, and calving difficulty (easy assist: one person manually delivered the calf; difficult assist: delivery by two or more people, or mechanical assistance). Within 10 min of birth, calves were stratified by calving difficulty, randomized to a medication group, and received a subcutaneous dose of meloxicam (0.5 mg/kg BW) or an equivalent volume of placebo. Cow-calf pairs were then placed in individual box stalls for observation and sampling. At birth, 1, 4, and 24 h after birth, heart rate, respiratory rate, and rectal temperature were assessed and blood samples collected to measure indicators of pain and inflammation (cortisol, corticosterone, substance P, and haptoglobin). Serum IgG concentration and failed transfer of passive immunity (serum IgG concentration 0.1). Although this was a small sample population, meloxicam given to assisted calves at birth improved ADG in the first week of life, which may indicate an important production management tool for improving well-being in assisted calves.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4c750b1d-5914-4d74-986a-4486923d82ae', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Comparison of natural service fertility of yearling and two-year old bulls', 'Government of Alberta', 1991, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/comparison-of-natural-service-fertility-of-yearling-and-two-year-old-bulls', 'https://open.alberta.ca/dataset/6fceda7c-0b28-4e77-a121-92615765eb33/resource/44b2aaf2-4f6f-41cc-9f3d-c300d9c582a7/download/163010363592-comparison-of-natural-service-fertility-of-yearling-and-two-year-old-bulls.pdf', NULL, NULL, 30, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study compared the reproductive performance of yearling bulls and two-year-old bulls in cow-calf operations. Researchers evaluated pregnancy rate, calving rate and calving date using data from 748 cows over three breeding seasons. The results showed that the age of the bull did not significantly influence reproductive performance, while cow age was consistently the most significant factor. The age structure of cows in the breeding herd had greater impact than bull age or any other variable. With appropriate management, yearling bulls could be effectively used for breeding about 25 cows each with reproductive outcomes comparable to those of older bulls.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f5aaa1be-0750-4c53-8c61-3f13428a5b31', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Determination of the efficacy of methods used to fertility test bulls used for multiple-sire breeding under range conditions', 'Government of Alberta', 1985, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/determination-of-the-efficacy-of-methods-used-to-fertility-test-bulls-used-for-multiple-sire-bre', 'https://open.alberta.ca/dataset/35a26a94-208d-4472-8e9b-4495f175626f/resource/640b7c1c-5330-44c6-b1d6-8bc0a7e9e103/download/163003217987-determination-efficacy-methods-used-fertility-test-bulls-used-multiple-sire-bre.pdf', NULL, NULL, 60, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project provided the necessary information to make concrete recommendations to veterinarians and cattlemen regarding the best criteria to use and their accuracy in predicting beef bull fertility. This will increase producers'' confidence in the use of these evaluation and selection criteria, extend their application, and result in substantial economic benefits to Alberta''s beef industry.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a286bcd1-7747-4e46-8e33-88f22e24cc3d', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'DNA-based Paternity Analysis in Multi-bull Breeding Programs on Beef Cattle Operations in Western Canada', 'S. J. Domolewski, Crystal Ketel, Kathy Larson, Leigh Marquess, Daalkhaijav Damiran, Mika Asai-Coakwell, H.A. Lardner', 2023, 'Sustainable Agriculture Research', '10.5539/sar.v12n2p1', 'https://doi.org/10.5539/sar.v12n2p1', 'https://ageconsearch.umn.edu/record/348319/files/64925698d8aa7.pdf', NULL, NULL, 15, NULL, 'prairies', 4, 'cc-by', 'A 3-yr study was conducted to evaluate deoxyribonucleic acid (DNA)-based paternity analysis on commercial beef ranches managing multi-bull breeding systems. Five commercial ranches in central Saskatchewan Canada participated in the study with a total of 22 breeding groups. All bulls (n = 75) and calves (n = 2243) were sampled to determine parentage. Number of calves sired per bull ranged from 1 to 87 (23 ± 15.9). The value of a calculated index of bull prolificacy (BPI) ranged from 0.05 to 3.83. Older bulls had a BPI averaging 1.10, 2-yr old bulls 1.00, and yearling bulls 0.76 (p > 0.05). Strong positive (r = 0.93, n = 74, p = 0.01) correlation was observed between total calves born per bull and calves born in the first 21 days BPI, between total calves born per bull and calves born in week-3 BPI (r = 0.69, n = 74, p = 0.01). Bull age was shown to play a significant role when determining prolificacy, with older bulls siring more calves than younger bulls. Bull number per breeding group influenced the number of calves sired. As number of bulls per breeding group increased so did the variation in the number of calves sired by each bull. Conducting DNA parentage testing only on calves born in the first 21 d or in week 3 of the calving season may provide an opportunity to decrease costs and turn-around time for laboratory results and decisions made, prior to the next breeding season.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('15504db8-10c7-444e-a894-64e43e33c906', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Effects of Heifer Calving Date on Longevity and Lifetime Productivity in Western Canada', 'Daalkhaijav Damiran, Kathy Larson, Leah Pearce, Nathan Erickson, H.A. Lardner', 2018, 'Sustainable Agriculture Research', '10.5539/sar.v7n4p11', 'https://doi.org/10.5539/sar.v7n4p11', 'https://ageconsearch.umn.edu/record/301836/files/Paper%202.pdf', NULL, NULL, 7, NULL, 'prairies', 4, 'cc-by', 'The objective of this study is to determine the effect of calving early as a heifer on lifetime production in western Canada. This study evaluated the longevity and life time production data on 211 individual heifers (data gathered for 16 years) at the Western Beef Development Centre (WBDC), Saskatchewan. Heifers were classified as calving in the first (period 1; n= 87), second (period 2; n = 66), or third (period 3; n = 58) 21-day period of the calving season. For each subsequent calf born to the cow, calving period was reassigned in the same manner. The current study showed that the average life time number of calves weaned for heifers that calved in the 1st, 2nd, and 3rd 21-day period was 5.4 ± 0.32, 4.5 ± 0.37, and 4.2 ± 0.39, respectively. Retaining percentage rate of period 1 cows was 4.3-17.8 and 2.1-19.1% units greater than those of period 2 and period 3 cows, respectively. Period 1 heifers had the greatest life time produced total cumulative weaning weight (p <0.01) value of 1157 kg/cow, followed by period 2 and period 3 heifers, 947 and 841 kg/cow, respectively. Period 1 cows generated an additional $718 to $1077 in weaned calf revenues over their lifetime. This study suggested that, in western Canada, heifers that calved earlier had greater pregnancy rates, remained in the herd longer, and produced one more calf in their lifetime than those that calved in the later periods.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9acc2e87-1145-4c63-9b34-353e069b4cd2', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Effects of prebreeding exposure to bulls on the reproductive performance of beef heifers', 'Government of Alberta', 1985, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/effects-of-prebreeding-exposure-to-bulls-on-the-reproductive-performance-of-beef-heifers', 'https://open.alberta.ca/dataset/47adf43b-efff-4641-b85d-28f2c25e677a/resource/b5da3ccd-e797-4998-93bf-26dbe01c0ba8/download/163010363964-effects-prebreeding-exposure-bulls-reproductive-performance-beef-heifers.pdf', NULL, NULL, 32, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated the effects of exposing yearling heifers from four breed groups (Hereford, Beef Synthetic, Dairy Synthetic and Crossbred Hereford) to teaser bulls. Researchers divided 172 heifers into two groups, one of which was exposed to three epididymectomized bulls for six weeks prior to the breeding season. Exposure did not affect pregnancy rates, but it advanced the average calving date by 5.5 days compared to the control group. Calving season among the exposed heifers was also two weeks shorter than in the control group. The findings suggested that six-week exposure to teaser bulls stimulated sexual activity in heifers, leading to earlier calving and a condensed calving season.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a15911a9-4fd5-445c-94ce-613d2c89e07c', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Escherichia coli O157[ratio ]H7 infection in cows and calves in a beef cattle herd in Alberta, Canada', 'Victor P. J. Gannon, Tavawn Graham, Robin K. King, Pascal Michel, Susan C. Read, Kim A. Ziebell, R. P. JOHNSON', 2002, 'Epidemiology and Infection', '10.1017/s0950268802007100', 'https://doi.org/10.1017/s0950268802007100', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/2778AE505107CEF7270020096B72A0FF/S0950268802007100a.pdf/div-class-title-span-class-italic-escherichia-coli-span-o157-ratio-h7-infection-in-cows-and-calves-in-a-beef-cattle-herd-in-alberta-canada-div.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('193bb9f8-adf1-4148-b8cf-1908708f1a5c', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Evaluation of 3 refractometers to determine transfer of passive immunity in neonatal beef calves', 'Gamsjäger L, Elsohaby I, Pearson JM, Levy M, Pajor EA, Windeyer MC', 2021, 'Journal of veterinary internal medicine', '10.1111/jvim.16016', 'https://doi.org/10.1111/jvim.16016', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7848313.1/PMC7848313.1.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'cc by-nc', 'BackgroundRefractometry is used to assess transfer of passive immunity (TPI), but studies evaluating different refractometers and appropriate thresholds for recommended target immunoglobulin G (IgG) concentrations for beef calves are limited.ObjectivesTo evaluate test performance of digital (DSTP) and optical (OSTP) serum total protein (STP) refractometers and a digital Brix (DBRIX) refractometer for assessment of passive immunity in beef calves.AnimalsA total of 398 beef calves from 6 herds, 1 to 7 days of age.MethodsSerum IgG concentration was estimated by DSTP, OSTP, and DBRIX, and measured by radial immunodiffusion (RID). Correlation coefficients (r) among results were calculated. Optimal STP and Brix thresholds for identification of IgG ResultsRefractometer results were highly correlated with RID (r = 0.82-0.91) and with each other (r = 0.91-0.95), and overall test performance was excellent (AUC = 0.93-0.99). The STP concentrations of ≤5.1, ≤5.1, and ≤5.7 g/dL and Brix percentages of ≤7.9%, ≤8.3%, and ≤8.7% indicated IgG concentrations Conclusions and clinical importanceAll refractometers showed good utility as monitoring tools for assessment of TPI in beef calves.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('216a8eee-363b-4c68-b336-611ff149275d', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Exploring industry perspectives and preferences about calf handling and restraint methods used during spring processing of calves in western Canada', 'Arkangel L, Windeyer C, Goldhawk C, Adams C, Pajor E', 2025, 'Translational animal science', '10.1093/tas/txaf014', 'https://doi.org/10.1093/tas/txaf014', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11842966.1/PMC11842966.1.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'cc by-nc-nd', 'Calf processing events have important animal health, management, and sociocultural roles in the beef cattle industry. In western Canada, the three most commonly used methods for spring processing are roping and wrestling (RW), roping and Nord fork (NF), and tilt table (TT). The objective of this study was to understand the preferences and perceptions of handling event participants about calf handling and restraint methods commonly used during western Canadian beef calf processing events during the spring season. Data were collected using a mixed-methods online questionnaire. Quantitative analysis was used to describe the study participants and determine preference rankings. Qualitative, thematic analysis was used to explore participants'' perceptions about the common handling and restraint methods and to identify values within and across participants. The majority of participants were farm hands or staff members (92.8%), followed by owners (4.9%), family members (1.4%), friends (0.5%), and others (0.4%). The most preferred method to use was RW, and TT was the least preferred (χ2 = 3239.1, df = 6, p < 0.001). Participants shared values regarding calf safety and stress, processing efficiency, convenience, human safety, and labor intensity when explaining their preference to use calf handling and restraint methods for spring processing. Responses highlighted the need for understanding and skill in low stress handling and processing tasks in order for any of the methods to be effective. These values identify aspects to address when developing best practice recommendations for calf handling and restraint. Furthermore, focusing communication through the lens of these shared values will likely positively engage participants in extension efforts and community discussions.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4bcc870c-0bf9-4bd3-ac41-40854208e1d7', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Bison Versus Cattle: Are They Ecologically Synonymous?', 'Michel T. Kohl, Paul R. Krausman, Kyran E. Kunkel, David M. Williams', 2013, 'Rangeland Ecology & Management', '10.2111/rem-d-12-00113.1', 'https://doi.org/10.2111/rem-d-12-00113.1', 'https://repository.arizona.edu/bitstream/10150/642759/1/23464-45245-1-PB.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b9a8f026-5b38-49d0-876a-f41e01aef7a0', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Factors affecting the accuracy of bull evaluation for gain at bull test station', 'Government of Alberta', 1990, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/factors-affecting-the-accuracy-of-bull-evaluation-for-gain-at-bull-test-station', 'https://open.alberta.ca/dataset/ae62b563-2798-4862-ba1b-ec3057026fb2/resource/6f900b7e-6850-450d-9cbd-4b1bf2f50717/download/0163010334247-factors-affecting-the-accuracy-of-bull-evaluation-for-gain-at-bull-test-station.pdf', NULL, NULL, 84, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study used performance test records of 2,445 bulls tested at the Ellerslie Bull Test Station from 1974 to 1987 to evaluate three objectives. The project examined the relative importance of factors such as age of dam, age of bull, and herd of origin on gain; the degree of influence of pre-test environment on growth rate; and the optimum period of adjustment and test. The results showed that age of dam was not a significant factor, and age of bull contributed only three to four per cent to variation in growth rate. Herd of origin was the most significant factor, accounting for 14.8 to 48.5 per cent of growth variation. The optimal test period for evaluating growth potential was between 28 to 112 days after the start of testing, during which average daily gain showed highest heritability and lowest environmental influence.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e0145af1-1ce0-4fc5-9731-ea8c104e2513', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Genetic architecture of quantitative traits in beef cattle revealed by genome wide association studies of imputed whole genome sequence variants: I: feed efficiency and component traits', 'Zhang F, Wang Y, Mukiibi R, Chen L, Vinsky M, Plastow G, Basarab J, Stothard P', 2020, 'BMC genomics', '10.1186/s12864-019-6362-1', 'https://doi.org/10.1186/s12864-019-6362-1', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6956504.1/PMC6956504.1.pdf', NULL, NULL, 22, NULL, 'alberta', 4, 'cc by', 'BackgroundGenome wide association studies (GWAS) on residual feed intake (RFI) and its component traits including daily dry matter intake (DMI), average daily gain (ADG), and metabolic body weight (MWT) were conducted in a population of 7573 animals from multiple beef cattle breeds based on 7,853,211 imputed whole genome sequence variants. The GWAS results were used to elucidate genetic architectures of the feed efficiency related traits in beef cattle.ResultsThe DNA variant allele substitution effects approximated a bell-shaped distribution for all the traits while the distribution of additive genetic variances explained by single DNA variants followed a scaled inverse chi-squared distribution to a greater extent. With a threshold of P-value ConclusionsRFI is controlled by many DNA variants with relatively small effects whereas DMI, ADG, and MWT are influenced by a few DNA variants with large effects and many DNA variants with small effects. Nucleotide polymorphisms in regulatory region and synonymous functional classes play a more important role per sequence variant in determining variation of the feed efficiency traits. The genetic architecture as revealed by the GWAS of the imputed 7,853,211 DNA variants will improve our understanding on the genetic control of feed efficiency traits in beef cattle.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('23a351a2-d653-4cda-a3fc-6bb7b4c26979', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Genome-wide association studies and genomic prediction of breeding values for calving performance and body conformation traits in Holstein cattle', 'Mohammed Kotb Abo-Ismail, Luiz F. Brito, Stephen Paul Miller, Mehdi Sargolzaei, Daniela A. Grossi, Steve S. Moore, Graham Stuart Plastow, Paul Stothard', 2017, 'Genetics Selection Evolution', '10.1186/s12711-017-0356-8', 'https://doi.org/10.1186/s12711-017-0356-8', 'https://gsejournal.biomedcentral.com/counter/pdf/10.1186/s12711-017-0356-8', NULL, NULL, 30, NULL, 'alberta', 4, 'cc-by', 'BACKGROUND: Our aim was to identify genomic regions via genome-wide association studies (GWAS) to improve the predictability of genetic merit in Holsteins for 10 calving and 28 body conformation traits. Animals were genotyped using the Illumina Bovine 50 K BeadChip and imputed to the Illumina BovineHD BeadChip (HD). GWAS were performed on 601,717 real and imputed single nucleotide polymorphism (SNP) genotypes using a single-SNP mixed linear model on 4841 Holstein bulls with breeding value predictions and followed by gene identification and in silico functional analyses. The association results were further validated using five scenarios with different numbers of SNPs. RESULTS: Seven hundred and eighty-two SNPs were significantly associated with calving performance at a genome-wise false discovery rate (FDR) of 5%. Most of these significant SNPs were on chromosomes 18 (71.9%), 17 (7.4%), 5 (6.8%) and 7 (2.4%) and mapped to 675 genes, among which 142 included at least one significant SNP and 532 were nearby one (100 kbp). For body conformation traits, 607 SNPs were significant at a genome-wise FDR of 5% and most of them were located on chromosomes 5 (30%), 18 (27%), 20 (13%), 6 (6%), 7 (5%), 14 (5%) and 13 (3%). SNP enrichment functional analyses for calving traits at a FDR of 1% suggested potential biological processes including musculoskeletal movement, meiotic cell cycle, oocyte maturation and skeletal muscle contraction. Furthermore, pathway analyses suggested potential pathways associated with calving performance traits including tight junction, oxytocin signaling, and MAPK signaling (P < 0.10). The prediction ability of the 1206 significant SNPs was between 78 and 83% of the prediction ability of the BovineSNP50 SNPs for calving performance traits and between 35 and 79% for body conformation traits. CONCLUSIONS: Various SNPs that are significantly associated with calving performance are located within or nearby genes with potential roles in tight junction, oxytocin signaling, and MAPK signaling. Combining the significant SNPs or SNPs within or nearby gene(s) from the HD panel with the BovineSNP50 panel yielded a marginal increase in the accuracy of prediction of genomic estimated breeding values for all traits compared to the use of the BovineSNP50 panel alone.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('94d4d5a5-6f35-4da9-9cce-b255e3144f32', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Investigating effective testing strategies for the control of Johne''s disease in western Canadian cow-calf herds using an agent-based simulation model', 'Johnson P, McLeod L, Qin Y, Osgood N, Rosengren L, Campbell J, Larson K, Waldner C', 2022, 'Frontiers in veterinary science', '10.3389/fvets.2022.1003143', 'https://doi.org/10.3389/fvets.2022.1003143', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9732103.1/PMC9732103.1.pdf', NULL, NULL, 28, NULL, 'prairies', 4, 'cc by', 'Johne''s disease is an insidious infectious disease of ruminants caused by Mycobacterium avium subspecies paratuberculosis (MAP). Johne''s disease can have important implications for animal welfare and risks causing economic losses in affected herds due to reduced productivity, premature culling and replacement, and veterinary costs. Despite the limited accuracy of diagnostic tools, testing and culling is the primary option for controlling Johne''s disease in beef herds. However, evidence to inform specific test and cull strategies is lacking. In this study, a stochastic, continuous-time agent-based model was developed to investigate Johne''s disease and potential control options in a typical western Canadian cow-calf herd. The objective of this study was to compare different testing and culling scenarios that included varying the testing method and frequency as well as the number and risk profile of animals targeted for testing using the model. The relative effectiveness of each testing scenario was determined by the simulated prevalence of cattle shedding MAP after a 10-year testing period. A second objective was to compare the direct testing costs of each scenario to identify least-cost options that are the most effective at reducing within-herd disease prevalence. Whole herd testing with individual PCR at frequencies of 6 or 12 months were the most effective options for reducing disease prevalence. Scenarios that were also effective at reducing prevalence but with the lowest total testing costs included testing the whole herd with individual PCR every 24 months and testing the whole herd with pooled PCR every 12 months. The most effective method with the lowest annual testing cost per unit of prevalence reduction was individual PCR on the whole herd every 24 months. Individual PCR testing only cows that had not already been tested 4 times also ranked well when considering both final estimated prevalence at 10 years and cost per unit of gain. A more in-depth economic analysis is needed to compare the cost of testing to the cost of disease, taking into account costs of culling, replacements and impacts on calf crops, and to determine if testing is an economically attractive option for commercial cow-calf operations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8529ce3-da4b-41a4-bc5f-fc60911e9ae4', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Market-based tools for accelerating cattle sustainability in Canada', 'Karen Haugen-Kozyra', 2021, 'Animal Frontiers', '10.1093/af/vfab038', 'https://doi.org/10.1093/af/vfab038', 'https://academic.oup.com/af/article-pdf/11/4/17/40316689/vfab038.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Canada provides a useful and interesting model for tools that can accelerate livestock sustainability, in particular, for the cattle sector. Globally, cattle are responsible for about 65% of livestock’s greenhouse gas emissions, with methane from enteric fermentation of feedstuffs and manure accounting for about 44% of the emissions. This represents a unique opportunity for livestock-based solutions, facilitated by effective market mechanisms and tools, contributing to lower environmental impacts. This paper discusses key drivers enabling the opportunity and uses case studies from Canada that are operational today to demonstrate what could be possible in other jurisdictions given similar circumstances and capabilities. As a country, Canada is an interesting microcosm of carbon pricing policies and sustainability tools. Carbon pricing is a tool that can accelerate decarbonization across sectors. Several provinces have had subnational carbon pricing schemes in place since the 2007 to 2008 timeframe (British Columbia, Quebec, and Alberta). Starting in 2016, the federal government under the Trudeau Administration worked with the provinces to establish the “Pan Canadian Framework”—a plan that strives to implement a pan-Canadian approach to pricing carbon pollution and measures to achieve reductions across all sectors of the economy. The road to harmonization has not been an easy or a popular one, with several provinces having since elected conservative governments currently challenging the constitutionality of the federal government’s imposition of backstop greenhouse gas regulations at the Supreme Court of Canada. Nevertheless, the carbon pricing systems remain in place, with the opportunity for the non-covered sectors such as agriculture, forestry, and waste treatment to voluntarily generate carbon offsets and sell to the regulated sectors for compliance-meeting purposes. It is this latter context—the ability to extend the price incentive to reduce the carbon intensity of agricultural production—that drove the development of tools to monetize activities for lower carbon beef production in Alberta, that is now extending to the Federal Offset System and beyond Canada’s borders. This paper will focus on the evolution of several market-based tools at play in Canada driven by subnational, national, sectoral certification systems, and global actions, policies, and pledges. As early as 2009, the Alberta Government approved three Carbon Offset Quantification Protocols incentivizing lower carbon beef production in the province—Feeding Edible Oils, Reducing greenhouse gas emissions (GHG) Intensity of Fed Cattle (Fed Cattle), and since 2012, Selection for Low Residual Feed Intake in Beef Cattle (Alberta Offset System 2021; https://www.alberta.ca/alberta-emission-offset-system.aspx). Alberta is the only jurisdiction in the world where project developers have been able to generate compliance-grade beef carbon offsets for sale to large final emitters in Alberta’s Carbon Pricing system. Trimble Corporation Canada has three projects listed on the Alberta Emissions Offset Registry under “The Reducing greenhouse gas Intensity of Fed Cattle Protocol” for practices implemented that increase feed efficiency of beef production. The projects generate over 49,000 tonnes of beef carbon offsets in four Alberta feedlots. In 2017, these tonnes were sold to a variety of buyers (Capital Power, Brightspot Climate, and TransAlta; https://alberta.csaregistries.ca/GHGR_Listing/AEOR_ListingDetail.aspx?ProjectId=229). Two more fed cattle projects are listed on the Registry by Trimble, generating carbon from 15 more feedlots in the 2017 project year, for an estimated total of over 90,000 tonnes of emission reductions altogether. Growsafe Beef Systems has one project listed for the “Selection for Low Residual Feed Intake in Beef Cattle protocol” on the Registry to date (https://www.csaregistries.ca/albertacarbonregistries/eor_project.cfm?id_prj=820). The Canadian gov', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('77b15238-84b1-4ccb-bfbb-bedef6114a8c', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'A review of the effects of forage condensed tannins on ruminal fermentation and bloat in grazing cattle', 'L. R. McMahon, Tim Angus McAllister, B. P. Berg, W. Majak, S. N. Acharya, J. D. Popp, Bruce E. Coulman, Y. Wang', 2000, 'Canadian Journal of Plant Science', '10.4141/p99-050', 'https://doi.org/10.4141/p99-050', 'https://cdnsciencepub.com/doi/pdf/10.4141/P99-050', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('057a9159-78d2-41af-9269-86924176050b', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Maternal recognition of pregnancy in cattle', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/maternal-recognition-of-pregnancy-in-cattle', 'https://open.alberta.ca/dataset/ac74d393-3a39-4640-9b06-200665240fa6/resource/2f003798-852a-44fe-930d-ecb495a669ce/download/163003217995-maternal-recognition-of-pregnancy-in-cattle.pdf', NULL, NULL, 52, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This research investigated the early biochemical communication between the embryo and the maternal uterus in cattle. It found that embryos produce hormonal signals within the first three weeks of pregnancy to alter the maternal hormonal environment and interrupt regular heat cycles. Frozen uterine tissue samples examined under light microscopy revealed changes in the uterine lining''s ability to respond to sex hormones, with cattle showing a delayed but similar response to sheep and goats. The study used sheep as a model due to the ease of tissue access and attempted to define the biochemical nature of the uterine response, although limited cell availability made consistent results difficult. Despite the challenges in identifying hormone-binding compounds in the uterus, the findings suggested potential for further research to improve reproductive efficiency through a better understanding of embryonic signalling.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e66cb5e7-004b-4da0-baa8-d87b692e4ae5', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'MGA for estrus synchronization and improvement of reproductive performance in beef cattle', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/mga-for-estrus-synchronization-and-improvement-of-reproductive-performance-in-beef-cattle', 'https://open.alberta.ca/dataset/bb68c074-c73e-4f34-8465-8dc34e3035aa/resource/3d2f82bf-ff8c-49bf-9c13-6a1a3ed0065e/download/163010147912-mga-estrus-synchronization-improvement-reproductive-performance-beef-cattle.pdf', NULL, NULL, 80, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study examined the use of estradiol and melengestrol acetate (MGA) to synchronize estrus in cattle across six experiments. In various trials, cattle received different combinations of MGA, estradiol valerate or estradiol 17β, prostaglandin F2α, progesterone, and cloprostenol to assess timing and effectiveness of induced estrus and pregnancy outcomes. Results indicated that MGA combined with hormone treatments increased synchronization and conception rates in some groups, but effects varied by protocol, reproductive status, and treatment timing. Cows treated with MGA and estradiol had significantly higher estrus and fall pregnancy rates than controls in several experiments. However, conception rates after artificial insemination were not consistently improved by feeding MGA or barley after estrus detection.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eefcb2c9-fba3-46c6-9430-07ff8f84d371', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Moldy feed and reproductive failure in cows', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2823972', 'https://open.alberta.ca/dataset/a3b0e622-0b2b-4c16-b1a6-86f6757b5172/resource/86bf96e4-6dab-4dae-9aa0-c84016d018d0/download/2003-666-5.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'All homegrown feeds contain some fungal spores. When the temperature and humidity are right, these spores will grow and multiply to create mold. Mycotoxins come from these fungal molds and can reduce animal health and productivity. Many molds found in feeds are not toxic, but some varieties produce substances that can result in disease when they are ingested. Of the thousands of molds that grow on stored grains and forages, only a few will produce mycotoxins.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('688c2345-25c4-4d98-bd01-ce0bca3c4f48', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Quantifying subclinical trauma associated with calving difficulty, vigour, and passive immunity in newborn beef calves', 'Pearson JM, Homerosky ER, Caulkett NA, Campbell JR, Levy M, Pajor EA, Windeyer MC', 2019, 'Veterinary record open', '10.1136/vetreco-2018-000325', 'https://doi.org/10.1136/vetreco-2018-000325', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6347876.1/PMC6347876.1.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'cc by-nc', 'This cross-sectional study quantifies subclinical trauma associated with calving difficulty, calf vigour, and passive immunity (PI) in newborn beef calves. The degree of calving difficulty was categorised as: unassisted, easy assist (one or two people manually pulling to deliver the calf) and difficult assist (more than two people pulling, a fetal extractor (ie, calf jack), or caesarean section). Vigour assessment occurred at 10 minutes and blood sampling at 24 hours after birth in 77 beef calves. The measured blood parameters associated with trauma were creatine kinase (CK), aspartate aminotransferase (AST), and haptoglobin. Serum IgG concentration was measured, and an IgG concentration at least 24 g/l was considered as adequate PI. Calving difficulty was associated with elevated levels of CK (P=0.002) and AST (P=0.01), weak suckle reflex (P=0.001), abnormal mucous membrane colour (P<0.0001), and decreased odds of adequate PI (P=0.004). Elevated levels of CK and AST were associated with abnormal mucous membrane colour, incomplete tongue withdrawal and weak suckle reflex at birth (P<0.001). An incomplete tongue withdrawal (P=0.005) and weak suckle reflex (P=0.02) were associated with decreased IgG concentrations. Abnormal mucous membrane colour, incomplete tongue withdrawal, and a weak suckle reflex were associated with decreased odds of having adequate PI (P<0.05). Haptoglobin was not associated with any of the parameters measured. Subclinical trauma was associated with calving difficulty, decreased vigour and decreased odds of having adequate PI. Understanding the impacts of a traumatic birth may aid the development of management strategies for compromised newborn beef calves.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('421063b5-6a67-4795-8ef8-c81e4806f8eb', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Quantifying the Forces Applied During Manually and Mechanically Assisted Calvings in Beef Cattle', 'Jennifer M. Pearson, Charmaine Thomsen, Kusler Ann, Edmund A. Pajor, Akshay Gurdita, Mark Ungrin, M. Claire Windeyer', 2020, 'Frontiers in Veterinary Science', '10.3389/fvets.2020.00459', 'https://doi.org/10.3389/fvets.2020.00459', 'https://www.frontiersin.org/articles/10.3389/fvets.2020.00459/pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'cc-by', 'Dystocia is a leading cause of calf mortality, yet there is little available information quantifying the duration and forces applied to assisted deliveries. Objectives of this study were to: (1) develop a method to measure the magnitude and duration of various forces applied to a calf during calving assistance, and (2) quantify the forces applied to beef calves during manual or mechanical calving assistance. Twenty-five primiparous dams requiring calving assistance were enrolled. Calvings were assisted by manual (1 or 2 people pulling) or mechanical (calf extractor) delivery. A set of modified obstetric chains with integrated force measuring devices (Calving Assistance Force Logger; CAF-Log) were applied to the calf for delivery. The CAF-Log system was calibrated using known masses ranging from 25 to 200 kg in increasing increments of 25 kg. Duration of the assisted delivery and force parameters (peak force applied to one leg, peak force applied to both legs, cumulative force, and maximum jerk force) were described and assessed for their associations with method of delivery and ranch. Median duration was 112.6 s (IQR: 88.4-149.7) for manual and 312.6 s (IQR: 221.6-462.3) for mechanical deliveries. Mean peak force applied to one leg was 56.9 kg (SD: 22.9) for manual and 126.8 kg (SD: 48.2) for mechanical deliveries. Mean peak force applied to both legs was 95.4 kg (SD: 34.1) for manual and 188.6 kg (SD: 83.9) for mechanical deliveries. Median cumulative force was 178.3 kg min (IQR: 21.1-38.8) for manual and 380.6 kg min (IQR: 252.1-581.3) for mechanical deliveries. The maximum jerk force for manual deliveries was 36.6 kg/s (IQR: 21.1-38.8) and 77.2 kg/s (IQR: 60.9-97.1) for mechanical deliveries. An interaction occurred between ranch and method of delivery for peak force applied to one leg, peak force applied to both legs, and cumulative force. The CAF-Log system demonstrated that significantly greater forces were applied to mechanically delivered calves compared to manually delivered calves and could be used in future studies to investigate forces applied to a calf during calving assistance and their impacts on cow and calf well-being.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04163192-2b3d-449c-94a8-c4a45634a169', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Relationships among scrotal and testicular characteristics, sperm production, seminal quality and fertility in beef bulls', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/relationships-among-scrotal-and-testicular-characteristics-sperm-production-seminal-quality-an', 'https://open.alberta.ca/dataset/f4a1e2cf-6284-4a97-b2c1-d4fd076d11cd/resource/d3210803-d7f6-41ee-b0d7-b6e1495a7111/download/163010130629-relationships-among-scrotal-testicular-characteristics-sperm-production-seminal.pdf', NULL, NULL, 45, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study evaluated fertility in beef bulls through two experiments using breeding soundness examinations and thermographic assessments. In Experiment 1, bulls with normal scrotal thermograms showed lower testicular tone, lower ultrasonic echotexture, and larger temperature gradients compared to bulls with abnormal thermograms, although most differences in scrotal circumference and spermatozoa proportions were not significant. In Experiment 2, significant correlations were observed between scrotal surface temperature and internal testicular temperature, sperm production, and epididymal reserves. Regression models revealed complex relationships, including both positive and negative associations with sperm traits. Assessment of testicular ultrasonic echotexture appeared promising, and thermography was found to be a useful tool, although caution was advised in interpreting results.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('429a1c58-0a24-4fe3-8944-02e17d80f3e9', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Relationships between beef heifer feed efficiency traits and Igenity panel scores in western Canada', 'Damiran D, Penner GB, Larson KA, Añez-Osuna F, Lardner HAB', 2018, 'Translational animal science', '10.1093/tas/txy022', 'https://doi.org/10.1093/tas/txy022', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7200480.1/PMC7200480.1.pdf', NULL, NULL, 5, NULL, 'prairies', 4, 'cc by-nc', NULL, '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('696b4dd8-6fa5-446a-bd66-1d5ddd54bfb6', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Salmonella spp. Shedding by Alberta Beef Cattle and the Detection of Salmonella spp. in Ground Beef', 'Ole Sorensen, Joyce Van Donkersgoed, Margaret E. McFall, Ken Manninen, Gary E. Gensler, Gerald Ollis', 2002, 'Journal of Food Protection', '10.4315/0362-028x-65.3.484', 'https://doi.org/10.4315/0362-028x-65.3.484', 'https://www.sciencedirect.com/science/article/pii/S0362028X22048645/pdf', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('253d2e9c-3721-4a04-aa08-283eeb6803a7', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'The economic analysis of delayed breeding of dairy cows', 'Government of Alberta', 1985, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/economic-analysis-of-delayed-breeding-of-dairy-cows', 'https://open.alberta.ca/dataset/5ad9db7b-cff8-4db0-8b41-7f6a1581f69f/resource/6f35fcd8-7dc6-4283-b146-bd4ee4cb8339/download/163003245418-the-economic-analysis-of-delayed-breeding-of-dairy-cows.pdf', NULL, NULL, 50, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study was conducted to determine the optimum calving interval for dairy cattle under current levels of milk production. The research involved herds from the University of Alberta, University of British Columbia, Colony Farm of the British Columbia Ministry of Agriculture, Agriculture Canada at Agassiz, and Olds College. Cows were assigned to either an early breeding group at 50 days post-calving or a late group at 90 days, with both groups bred at 70 days post-partum during second lactation. Results showed that while milk production increased with delayed breeding, profitability did not improve unless milk yield was exceptionally high. The findings support maintaining a 12 to 12.5 month calving interval for most dairy cows, though the recommendation may be revised with further analysis.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6e81885a-039f-45aa-bf63-24d33cd6033d', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'The influence of pre- and post-weaning growth rate on the reproductive performance of beef heifers', 'Government of Alberta', 1987, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/influence-of-pre-and-post-weaning-growth-rate-on-the-reproductive-performance-of-beef-heife', 'https://open.alberta.ca/dataset/2e35d109-cc1b-413b-9cfa-872fff1c0709/resource/8d0e1539-3271-4180-84c7-1cb9043f7124/download/163010334528-influence-pre-post-weaning-growth-rate-reproductive-performance-beef-heife.pdf', NULL, NULL, 90, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project studied the effects of age, body weight, and weight gain at different growth stages on pregnancy rate of heifers, the impact of post-weaning nutrition, and genetic-environment interactions on reproductive performance in two-year-old heifers. Analysis of over 2,500 breeding records and a field trial with 700 beef heifers fed three concentrate levels showed that weight gains and body weights had a greater influence on pregnancy rate than age when age variation was small. The average pregnancy rate was 84 per cent, with 79 per cent of calvings occurring in the first six weeks. Breed groups differed in sensitivity to underfeeding, but low post-weaning concentrate intake did not significantly affect calving performance. There was significant interaction between breed group and concentrate level on growth rate, but concentrate level did not significantly affect pregnancy rate, calving date, calf birth weight, or calving difficulty.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bce773fa-2e9b-4fa9-8087-2e06673640e8', '62d8f741-bc1d-452d-af19-eaa6ef237270', 'Update on copper and selenium in Canadian cow-calf herds: regional differences and estimation of serum reference values', 'Waldner C, McLeod L, Parker S, Campbell J', 2023, 'Translational animal science', '10.1093/tas/txad062', 'https://doi.org/10.1093/tas/txad062', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10358720.1/PMC10358720.1.pdf', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by-nc', 'Trace mineral supplementation of beef cattle is essential for efficient reproduction and herd health. Understanding regional differences in cow trace mineral status could inform decisions about risks of deficiencies and supplementation management. Cow-calf surveillance projects provided three opportunities to evaluate the trace mineral status of Canadian beef cow herds. Blood samples were collected at pregnancy testing in 2014 from 102 cow-calf herds and in 2016 from 86 cow-calf herds in Western Canada. In 2019, blood samples were collected at pregnancy testing from cows in 163 cow-calf herds from Eastern and Western Canada. Serum samples were analyzed for copper, selenium, and molybdenum concentrations using a plasma mass spectrometer. The prevalence of copper deficient cows sampled from the Western provinces ranged from 24% to 43% across the three periods, and was 20% from Eastern Canada in 2019. The prevalence of selenium deficient cows ranged from 0.2% to 0.4% across the three projects in Western Canada, but was higher in Eastern Canada at 4.6% in 2019. High serum molybdenum was identified in 9.4% to 14% of cows across the three periods in Western Canada and in 15% of cows sampled in Eastern Canada in 2019. Serum copper, selenium, and molybdenum concentrations varied by cow age and month of sample collection. Serum selenium and molybdenum concentrations, but not copper, varied by soil type associated with the location of the farm. A subsample of samples from cows from Western Canadian herds provided body condition score (BCS) data, pregnancy status, and calf survival data and were used to estimate updated serum reference values for adequate concentrations. Age-specific values were required for selenium and molybdenum. Reference intervals (80%) were estimated from 2,406 pregnant beef cows from 99 herds with each cow having a BCS ≥ 2.5/5 and a live calf at 3 wk with no retained placenta: copper for all cows (0.379 to 0.717 ppm), selenium for cows 0.104 ppm) and cows ≥4 yr (>0.110 ppm). The lower limits for the reference intervals for adequate copper and selenium are below those previously reported; nevertheless, they represent a large sample that was specifically applicable to extensively managed beef animals in western Canada.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7f8c3c7d-9843-4ae9-866c-3d107bc78739', '2efe208c-b268-49a9-bb9a-ff8976d0648f', '2018-2022 economic, productive and financial performance of Alberta cow/calf operations', 'Government of Alberta', 2022, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-economic-production-and-financial-performance-of-alberta-cow-calf-operations', 'https://open.alberta.ca/dataset/781f2072-bdb5-40be-a7df-a0a44a760017/resource/c214e679-f81d-4bca-adb7-ff2e072fcc48/download/agi-itrb-economic-productive-financial-performance-alberta-cow-beef-2018-2022.pdf', NULL, NULL, 14, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This AgriProfit$ cost and returns report presents a multi-year summary of the economic, productive, and financial performance of Alberta cow/calf producers. Participating cow/calf producers received a customized business analysis of their operations for comparison to this multi-year benchmark report. The benchmarks contained in the report summarize all sources of income and expenses related to cow/calf enterprises and covers all those activities to produce and raise calves until weaning in a given fiscal year.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ef74d43-9338-4038-a15d-3d8caeec2471', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'A Rapid Scoping Review of Nutritional Management of Beef Cows and Pre-Weaning Calves and the Occurrence of Bovine Respiratory Disease in Pre- and Post-Weaning Calves in North America', 'Wilhelm B, Sanguinetti M, Pollock C, Waldner CL', 2026, 'Animals : an open access journal from MDPI', '10.3390/ani16193116', 'https://doi.org/10.3390/ani16193116', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13663391.1/PMC13663391.1.pdf', NULL, NULL, 43, NULL, 'prairies', 4, 'cc by', 'Bovine respiratory disease (BRD) causes economic loss and antimicrobial use in North American beef production. This rapid scoping review examined whether nutritional management of beef cows and pre-weaning calves affects BRD morbidity or mortality before or after weaning. Eligible sources were English- or French-language North American studies published from 2000 onward that evaluated nutrition or colostrum management in beef cows or calves and reported BRD-specific, secondary, or tertiary outcomes. Six bibliographic databases and grey-literature sources were searched. One reviewer charted and verified data using a pre-tested form. Findings were synthesized narratively without formal critical appraisal. Forty-seven studies were included: 22 reported BRD-specific morbidity or mortality, 20 reported only secondary outcomes (e.g., crude mortality), and five reported only tertiary outcomes (e.g., vaccine antibody titres). Three of five controlled trials of maternal protein supplementation reported favourable offspring BRD outcomes, although incomplete comparisons, absent treatment effect estimates, and the absence of formal critical appraisal limited interpretation. Selected maternal trace mineral trials reported reduced post-weaning BRD morbidity or fewer aggregated sick incidents. Direct evidence for colostrum-management strategies was sparse; other findings were inconsistent or based on few or no BRD events. Evidence remains insufficient for specific recommendations. Adequately powered commercial trials should report prespecified BRD outcomes, effect sizes, and confidence intervals.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3fad4129-1ca1-4eb5-b563-df4a08e2d584', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'AgriProfit$ cost & returns profiles. Dryland tame grass pasture : Southern Alberta (Fescue Grassland, Mixed Grassland & MoistMixed Grassland)', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-cost-returns-profiles-dryland-tame-grass-pasture-southern-alberta', 'https://open.alberta.ca/dataset/2f82ea4c-ade1-4277-b522-e8aa0dfb934a/resource/0426440b-2f9d-4ac7-86ee-82aaca811f4c/download/2012-agriprofit-cost-returns-profiles-dryland-tame-grass-pasture-southern-alberta-2012-07-30.pdf', NULL, NULL, 2, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'AgriProfit$ cost and returns profiles give an insight into the productive and economic performance of Alberta cereal, oilseed, forage and grazing crops, reported by soil or grass-type zone. These benchmark include field observations from the period 2008 to 2010. Averaging over a three-year span smooths out extremes in prices, yields and expenses and gives a better reflection of the crops’ intermediate term costs and profit potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ba2edd7a-bd57-4030-bbc8-a33c99202fab', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Can cows and fish co-exist?', 'Lorne Fitch, Barry W. Adams', 1998, 'Canadian Journal of Plant Science', '10.4141/p97-141', 'https://doi.org/10.4141/p97-141', 'https://cdnsciencepub.com/doi/pdf/10.4141/P97-141', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29a087ea-0e96-44b9-bfd5-af688a486c55', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'An economic guide to range & pasture improvement in Alberta', 'Government of Alberta', 1971, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/economic-guide-to-range-pasture-improvement-in-alberta-0163003144660', 'https://open.alberta.ca/dataset/596bea0a-5fdd-420a-b53a-b8a023fb92c8/resource/c07f02e2-e3f4-4b84-8faf-2cdbcf3c162b/download/0163003144660-an-economic-guide-to-range-pasture-improvement-in-alberta.pdf', NULL, NULL, 66, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This guide presents an economic analysis of range and pasture improvement in Alberta, aiming to determine the financial viability of increasing beef production by enhancing grazing lands. It details a budgeting procedure to compare net returns from cow-calf enterprises on native versus improved pastures across four distinct regions: Prairie, Parkland, Grey-Wooded, and Peace River. The analysis considers various factors, including livestock prices, feed costs, carrying capacities, and labor, to identify maximum economically feasible expenditures for pasture improvement and the time required to recover these costs. It also offers general guidelines on the economic feasibility of fertilizing seeded pastures.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('deecfbff-732a-47b9-be0f-84083ba150ab', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Characterization of the hoof bacterial communities in feedlot cattle affected with digital dermatitis, foot rot or both using a surface swab technique', 'Wong NST, Malmuthge N, Gellatly D, Nordi WM, Alexander TW, Ortega Polo R, Janzen E, Schwartzkopf-Genswein K', 2024, 'Animal microbiome', '10.1186/s42523-023-00277-1', 'https://doi.org/10.1186/s42523-023-00277-1', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10804539.1/PMC10804539.1.pdf', NULL, NULL, 14, NULL, 'southern_alberta', 5, 'cc by', 'BackgroundLameness is defined as altered or abnormal gait due to dysfunction of the locomotor system, and is a health issue of feedlot cattle, having major economic, labour, and welfare implications. Digital dermatitis (DD-a lesion of the plantar surface of the foot) and foot rot (FR-affects the interdigital cleft) are common infectious causes of lameness in feedlots. These hoof lesions can occur alone or in combination (DD + FR) in the same hoof. A total of 208 hoof swabs were collected from three commercial feedlots located in southern Alberta. Every lesion sample was matched with a corresponding control skin sample taken from a healthy contralateral foot. Control skin samples were also collected from cattle with no lesion on any feet. Bacterial communities of three types of hoof lesions (DD, DD + FR, FR) and healthy skin were profiled using 16S amplicon sequencing.ResultsAlpha diversity analysis revealed a lower bacterial diversity on DD and FR lesions compared to control skin. Beta diversity analysis showed that bacterial communities of DD, FR, and DD + FR lesions were distinct from those of the control skin. While the impact of feedlot was minimal, lesion type contributed to 22% of the variation observed among bacterial communities (PERMANOVA-R = 0.22, P ConclusionsThe bacterial community description of a DD + FR lesion is a novel finding. Not only did lesions lead to altered bacterial communities when compared to healthy skin, but the composition of those communities also differed depending on the hoof lesion. The 16S amplicon sequencing of surface swabs has significant value as a research tool in separating different hoof lesions and can provide additional insights to the polybacterial etiology of DD and FR in feedlot cattle.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b07fe0b0-28f0-4401-9fe9-fa5c9dcbd48c', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'CHARACTERIZATION OF THE PREVALENCE AND FECAL EGG COUNT INTENSITY OF GASTROINTESTINAL NEMATODES AND THEIR MANAGEMENT IN WESTERN CANADIAN COW-CALF HERDS', 'Felicity Kaye Wills', 2017, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/8302', 'https://harvest.usask.ca/bitstreams/262f17e8-b7bb-49cc-b56f-b479bf6b9041/download', NULL, NULL, 176, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4154a71-60b1-4b5d-8eb3-5f73a80b6bd0', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Consensus of costs and returns for 200 cow-calf custom grazing enterprise in the Drayton Valley district', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/consensus-of-costs-and-returns-for-200-cow-calf-custom-grazing-enterprise-in-the-drayton-valley', 'https://open.alberta.ca/dataset/6b442b81-2234-43e6-a2bb-13a03b07db7a/resource/252ff4a6-751f-4650-b20c-c55a263d1114/download/0163003146855-consensus-costs-returns-200-cow-calf-custom-grazing-enterprise-drayton-valley.pdf', NULL, NULL, 16, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report provides an estimate of costs and returns for a 200 cow-calf custom grazing enterprise in the Drayton Valley district. It utilizes the Consensus Research Data (CRD) technique, which relies on group participation from local farmers to establish typical costs and returns rather than area averages. The analysis details the financial aspects of a custom grazing operation, including cash and non-cash costs, expected returns, and various interest charges. This information serves as a guide for producers in making management decisions regarding enterprise selection, operational cash flow, and investment planning.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('28ef7c6e-e521-421a-971d-4bdd36ac3fcf', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Direct marketing meats : selling freezer beef', 'Government of Alberta', 2005, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3353429', 'https://open.alberta.ca/dataset/46c22882-588d-449d-88e6-5d66fcaba64d/resource/3127776a-79d0-478d-ba8d-d163b2a88521/download/2005-420-845-1.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The basis of farm direct marketing is the trust relationship that develops between producers and consumers. Successful farm direct marketing depends on providing quality products in a clean and customer-friendly environment. Farm-direct marketing requires a substantial time commitment. Agripreneurs need to devote long hours, seven-days-a-week to produce and market their products. Considerable time is also needed to develop the close relationships with consumers. In addition, agripreneurs need to be able to manage their time very efficiently in order to sell their products at multiple locations, such as at the farm gate and at farmers'' markets.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8dfae985-674a-4059-b1c2-5299dd9bc39a', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Direct marketing profits : business performance tools in an Alberta direct market beef enterprise', 'Government of Alberta', 2002, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/direct-marketing-profits-business-performance-tools-in-alberta-direct-market-beef-enterprise', 'https://open.alberta.ca/dataset/3ce1e9b7-4d9d-4b53-ab96-a5b4a511a24a/resource/9b2e960e-7da7-4cba-b440-88d4cde5c1db/download/afrd-direct-marketing-profits-business-performance-tools-in-alberta-direct-market-beef.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet provides specialized economic information on establishing and operating a direct market beef enterprise. This information was generated by a group of producers/marketers who arrived at a consensus of opinion on investment, production, marketing requirements, costs and revenues associated with developing a viable direct market beef enterprise.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('73e9fbb8-dc08-480a-b2ff-bc0ea775bd92', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Drivers of wolf depredation reporting and compensation use intentions by livestock producers', 'Nickerson R, Niemiec RM, Few A, Hoag D, Evangelista PH, Breck SW', 2026, 'PeerJ', '10.7717/peerj.20732', 'https://doi.org/10.7717/peerj.20732', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12875219.1/PMC12875219.1.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc by', 'BackgroundAcross the western United States, compensation programs that pay livestock producers for losses seek to mitigate the impact of carnivore depredation on livestock. However, data suggest not all livestock producers report wolf depredations or utilize compensation programs. Understanding factors influencing producers to report depredations and to use compensation programs will be critical to program efficacy.MethodsWe designed a questionnaire expanding the Theory of Planned Behavior to explore which social-psychological and demographic factors most strongly correlate with compensation use and conflict reporting intentions. Our questionnaire was distributed across the inland western United States with confirmed wolf populations including Washington, Oregon, California, Idaho, Montana, Wyoming, Colorado, Arizona, and New Mexico, as well as Alberta, Canada.ResultsPerceptions of how commonly other producers were reporting wolf depredation (descriptive norms) and worry about future wolf depredation (perceptions of risk probability) were the strongest predictors of reporting intention. A lack of trust in state agencies, perceived financial risk without access to depredation compensation, descriptive norms, attitudes, age, and producer state of residence were the strongest predictors of compensation use intention. Our findings suggest that reducing operational financial vulnerability, building trust in agency personnel, and peer-to-peer knowledge sharing may be effective strategies for increasing reporting and compensation use. Though our sample size was relatively small, our results are informative and have important implications for compensation programs and reporting.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ed32c75f-e88a-4d94-985e-27ac7a455ac1', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Drylot backgrounding of feeder cattle : economic & productive performance', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/drylot-bbckgrounding-of-feeder-cattle-economic-productive-performance', 'https://open.alberta.ca/dataset/d3ebdf6a-09c4-4c89-96af-d068c10888fe/resource/0dcab519-d00b-4b36-8f26-39e9b8be9a98/download/2004-drylot-backgrounding-feeder-cattle-economic-productive-performance-2004-02-18.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Technical bulletins research specific areas of interest to provide a better understanding of cropping issues that may affect or influence Alberta producers. They also provide Alberta producers with an additional tool to evaluate business performance along with production, management, and technology options.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('807af878-55ff-40a6-b9ff-e5116e37b633', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Value-based marketing of cattle : more than just carcass quality', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2601362', 'https://open.alberta.ca/dataset/daea874c-845e-446a-8f87-75a1a147ca59/resource/857f2b13-8d14-49b4-8db9-d05f8c93a780/download/2002-420-40-2.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Beef producers must remain competitive in strong protein markets and knowing the costs of production is essential to being competitive. Value-based marketing (VBM) is a tool that allows beef operations to be paid based on the quality of product being produced, rather than a daily price average. Premiums and discounts vary from one packing plant to another and change depending on the time of year. They can even change on a daily basis. Pricing on the grid does not mean you can discard your marketing skills. You still need to be a knowledgeable, efficient and effective marketer of your cattle. Some substantial rewards and losses may occur with the use of grid-pricing. To reduce your risk, know your cattle before you jump into this game.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e213d0da-573c-4891-9fee-60093d26db52', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Economic guide to range pasture improvement in Alberta', 'Government of Alberta', 1971, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/economic-guide-to-range-pasture-improvement-in-alberta2', 'https://open.alberta.ca/dataset/d91e5b68-e280-41a3-8046-04385444c2d0/resource/87cfce66-027d-40d9-8f4d-2276b2b36c52/download/33286106598325-economic-guide-to-range-pasture-improvement-in-alberta-2.pdf', NULL, NULL, 66, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This guide examines the economic viability of range and pasture improvements in Alberta, focusing on cow-calf enterprises across four distinct regions: Prairie, Parkland, Grey-Wooded, and Peace River. It analyzes the impact of increased carrying capacity from improved pastures on net returns, considering factors such as interest rates, repayment periods, and varying improvement costs. The research provides maximum economically feasible expenditures for pasture improvement and calculates the years required to recover these costs. These findings offer practical guidance for farmers and ranchers considering range improvement and inform government policy decisions related to grazing land management.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('90fc1e0d-efc8-41e8-aa6f-d711ae47e4f0', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Economic replacement strategies for dairy cattle', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/economic-replacement-strategies-for-dairy-cattle', 'https://open.alberta.ca/dataset/927877b4-5878-4a2f-82d0-00ba067c3110/resource/9bcf1fad-8a70-4c2c-beaa-d4858b124799/download/0163003269681-economic-replacement-strategies-for-dairy-cattle.pdf', NULL, NULL, 51, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study developed an explanatory economic model to examine the economic life of dairy cows, focusing on replacement by genetically superior animals using data from four co-operating dairy producers. A finite Markov process was used to calculate net present values for various replacement patterns and identify an optimum strategy that maximized herd value over time. The model showed that despite sensitivity to parameter variations, the optimum replacement time consistently occurred at the lactation number three, with minimal economic penalty for deviation. Comparison with Alberta Dairy Herd Services data revealed no major differences between calculated optimum strategies and current industry practices. The study recommended further research on lactation curves, veterinary costs, and culling data to improve decision-making.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ae715a97-6be0-4a62-85aa-749b580a3c08', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Economics of change for beef operations', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/economics-of-change-for-beef-operations', 'https://open.alberta.ca/dataset/c6143e42-7592-494a-bc3b-66f1b630e82d/resource/a889d2cd-fa88-45bd-a3ea-c2110989b5ee/download/2009-economics-change-for-beef-operations-2009-01-30.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Highlights some of the key findings of an economic analysis of north and central Alberta beef operations over the past 10 years, including the durability of the industry and opportunities for profit driven change. Key drivers supporting the "economics of change" are farm-level financial strengths and potential for herd cost reductions through integrated herd and grazing systems.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ecac550-63cc-412b-8ad3-5f59f9200921', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Economics of feed storage and distribution systems for feeding cattle', 'Government of Alberta', 1980, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/684574', 'https://open.alberta.ca/dataset/273c718e-2e26-421d-b868-6f7a340f4d02/resource/b8eb97f2-6dc4-49a3-8628-e03195ae4d7d/download/1980-economics-feed-storage-distribution-systems-for-cattle-systems-400-827-1.pdf', NULL, NULL, 127, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'this publication will provide some guidelines to those individuals who are interestedin selecting the feed storage and distribution system that will best fulfill their own requirements. The report examines several feed storage and distribution systems and the level of investment, labor costs and operating costs of each.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5836c90b-ee73-4c58-8250-0a88de33e2ae', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Effects of supplementing crude protein to feedlot bison heifers using canola meal or wheat-based distillers'' grains with solubles on feed intake, performance and carcass traits', 'Alcivar de Lucca J, McKinnon JJ, Feist MS, Binetruy T, van Cleef E, Wright S', 2025, 'Translational animal science', '10.1093/tas/txaf158', 'https://doi.org/10.1093/tas/txaf158', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12721373.1/PMC12721373.1.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc by-nc-nd', 'This study evaluated how varying crude protein levels in rations that incorporated canola meal or wheat-based dried distillers'' grains with solubles as alternative protein sources affected growth performance, carcass traits, and liver mineral status in feedlot bison heifers. Ninety-six crossbred bison heifers (initial body weight; 215.5 ± 22.2 kg) were stratified by weight and randomly assigned to one of three dietary treatments: (i) a conventional control diet (CON), (ii) CON with canola meal (CM), or (iii) CON with wheat-based dried distillers'' grains with solubles (WDDGS). Diets were fed over a 302-d period, consisting of a 122-d backgrounding phase and a 180-d finishing phase. During the backgrounding phase, CM and WDDGS diets were formulated to 14.0% crude protein (CP) compared with 10.0% in the CON diet. In the finishing phase, CM and WDDGS diets were formulated to 14.0% CP compared to 12.5% in the CON diet. The dry matter intake (DMI) was lower (P = 0.04) in heifers fed CM and WDDGS (5.9 kg/d) compared to CON (6.2 kg/d) during backgrounding. However, average daily gain and gain-to-feed ratio did not differ among treatments in any phase (backgrounding, finishing, or overall; P ≥ 0.27). Final body weight, hot carcass weight, dressing percentage, ribeye area, backfat thickness, marbling occurrence, and liver abscess incidence were not affected by dietary treatment (P ≥ 0.20). Hepatic copper (P = 0.02) and zinc (P = 0.03) concentrations were greater in heifers fed by-product diets compared to CON. A pronounced seasonal pattern in DMI was observed with a peak occurring in summer and a nadir in the winter. These results indicate that bison heifers can achieve similar growth performance and carcass characteristics when fed diets formulated to 10.0% CP during backgrounding and 12.5% CP during finishing, and that increasing dietary CP to 14.0% through the inclusion of CM or WDDGS did not enhance productivity. These results indicate that CM or WDDGS can be fed as protein sources without compromising the performance of bison heifers.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7a9656a0-6f5d-4c12-bc43-8744a4752360', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Epidemiology of Digital Dermatitis in Western Canadian Feedlot Cattle', 'Sarah E. Erickson, Calvin W. Booker, Jiming Song, Eugene Janzen, Murray D. Jelinski, K. S. Schwartzkopf-Genswein', 2024, 'Animals', '10.3390/ani14071040', 'https://doi.org/10.3390/ani14071040', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11011063/pdf/animals-14-01040.pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 4, 'cc-by', 'Digital dermatitis (DD) is an emerging disease in feedlot cattle. Our objective was to identify animal- and feedlot-level risk factors for DD by analyzing individual animal health records (n = 1,209,883) and feedlot-level records from western Canadian feedlots (n = 28) between 2014 and 2018, inclusive. The risk of a DD diagnosis was higher (incidence rate ratio (IRR) = 2.08, 95% CI 1.52 to 2.86) in cattle sourced from confined background operations (CB) versus cattle sourced from auction markets (AM). Conversely, ranch direct (RD) cattle were (IRR = 0.02, 95% CI 0.04 to 0.30) lower risk than AM cattle of being diagnosed with DD. The risk of being diagnosed with DD was higher in females than in males. The magnitude of the risk in females over males was influenced by annual DD incidence in low morbidity years (2014, 2017, and 2018) (IRR = 2.02, 95% CI 1.27 to 3.19), medium morbidity years (2016) (IRR = 2.95, 95% CI 1.64 to 5.33), and high morbidity years (2015) (IRR = 5.41, 95% CI 3.27 to 8.95). At the feedlot-level, the risk of a diagnosis of DD was lower in small capacity (SCF) versus large capacity feedlots (LCF) (IRR = 0.24, 95% CI 0.05 to 0.76). Future research should focus on identifying factors that may propagate disease transmission between cattle of different sexes and from different acquisition sources.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7d62ab5b-78b5-49b2-b487-43b7c9b53c6a', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Evaluation of electrolyte therapy to improve carcass yield under commercial feedlot marketing procedures', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluation-of-electrolyte-therapy-to-improve-carcass-yield-under-commercial-feedlot-marketing-pr', 'https://open.alberta.ca/dataset/9d5e6789-d22e-45b3-b1b4-2b947f0d625a/resource/35bfe846-59dc-4ab5-96a3-ecebbdf752bb/download/163010362347-evaluation-electrolyte-therapy-improve-carcass-yield-under-commercial-feedlot-marke.pdf', NULL, NULL, 42, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This field trial in Alberta evaluated whether administering electrolyte therapy prior to transport could improve carcass yield under commercial feedlot marketing conditions. The study was conducted in two parts, with steers assigned to various groups that received electrolyte supplements either in water or feed for 24 hours prior to shipping, or no treatment as controls. Across both trials, no significant differences were observed among treatment groups in allocation weight, truck weight, off-truck weight, carcass weight, carcass yield, carcass grade, or carcass marbling score. Furthermore, no Canada B2 grades (dark cutters) were observed in any treatment group. The results indicated that under commercial conditions, pre-transport electrolyte therapy provided no measurable benefit to carcass characteristics.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('59cdbf6d-0715-4173-9b69-8d0eac63acd1', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Exploring Biological Impacts of Prenatal Nutrition and Selection for Residual Feed Intake on Beef Cattle Using Omics Technologies: A Review', 'Aidin Foroutan, David S. Wishart, David S. Wishart, Carolyn Fitzsimmons, Carolyn Fitzsimmons', 2021, 'Frontiers in Genetics', '10.3389/fgene.2021.720268', 'https://doi.org/10.3389/fgene.2021.720268', 'https://www.frontiersin.org/articles/10.3389/fgene.2021.720268/full', NULL, NULL, 14, NULL, 'alberta', 4, 'open access (DOAJ)', 'Approximately 70% of the cost of beef production is impacted by dietary intake. Maximizing production efficiency of beef cattle requires not only genetic selection to maximize feed efficiency (i.e., residual feed intake (RFI)), but also adequate nutrition throughout all stages of growth and development to maximize efficiency of growth and reproductive capacity, even during gestation. RFI as a measure of feed efficiency in cattle has been recently accepted and used in the beef industry, but the effect of selection for RFI upon the dynamics of gestation has not been extensively studied, especially in the context of fluctuating energy supply to the dam and fetus. Nutrient restriction during gestation has been shown to negatively affect postnatal growth and development as well as fertility of beef cattle offspring. This, when combined with the genetic potential for RFI, may significantly affect energy partitioning in the offspring and subsequently important performance traits. In this review, we discuss: 1) the importance of RFI as a measure of feed efficiency and how it can affect other economic traits in beef cattle; 2) the influence of prenatal nutrition on physiological phenotypes in calves; 3) the benefits of investigating the interaction of genetic selection for RFI and prenatal nutrition; 4) how metabolomics, transcriptomics, and epigenomics have been employed to investigate the underlying biology associated with prenatal nutrition, RFI, or their interactions in beef cattle; and 5) how the integration of omics information is adding a level of deeper understanding of the genetic architecture of phenotypic traits in cattle.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f07727c3-1d4a-4fb5-a2db-649192da192f', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Johne''s Disease Control in Beef Cattle: Balancing Test-and-Cull Strategies with Economic and Epidemiological Trade-Offs', 'Rosengren L, Roche SM, Larson K, Waldner CL', 2025, 'Veterinary sciences', '10.3390/vetsci12121210', 'https://doi.org/10.3390/vetsci12121210', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12737406.1/PMC12737406.1.pdf', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Johne''s disease (JD) is a chronic infection of cattle that undermines herd productivity and profitability. While test-and-cull programs are commonly proposed for control, their effectiveness and economic feasibility remain uncertain in beef production systems. This study used an updated agent-based model (ABM) to simulate JD transmission in a representative 300-cow Western Canadian beef herd, coupled with a partial budget model to evaluate net present value (NPV) over a 10-year time horizon. Seven diagnostic test-and-cull strategies were compared, varying in test type (ELISA, individual PCR, and pooled PCR), sampling frequency (6, 12, or 24 mo), and risk-based sampling protocols. Results showed that, under baseline assumptions (6% starting prevalence; 1% prevalence in purchased stock), all strategies reduced JD prevalence relative to no testing, and six of seven yielded higher NPVs. Annual individual PCR testing provided the best balance between prevalence reduction and profitability, whereas semi-annual PCR most effectively reduced prevalence but at greater economic cost. Failure to implement control measures resulted in increasing prevalence and long-term economic losses. Sensitivity analyses demonstrated that strategy performance was consistent across variations in market conditions, cost of production, and replacement female management, although profitability declined substantially when JD prevalence in externally sourced stock was high (i.e., 10%). Collectively, these findings indicate that JD can be controlled economically in beef herds, with long-term application of various test-and-cull strategies offering robust options adaptable to management preferences.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e74d6694-bedf-4e2d-ae55-67ec479a4ac0', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Jurisdictional Comparison in the Utilization and Valorization of Animal By-Products of Slaughterhouse-Origin: A Global Review', 'Bello IE, Tayengwa T, Roe J, Wu J, Soladoye OP', 2026, 'Foods (Basel, Switzerland)', '10.3390/foods15081324', 'https://doi.org/10.3390/foods15081324', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13114427.1/PMC13114427.1.pdf', NULL, NULL, 25, NULL, 'alberta', 4, 'cc by', 'Animal by-products (ABPs), comprising both edible and inedible components, offer significant nutritional, economic, and environmental value. However, their utilization differs markedly across global jurisdictions due to cultural preferences, regulatory frameworks, and technological capacities, which collectively shape consumption patterns and determine integration into food systems or diversion to industrial applications. While consumer reliance on offal remains high in the Global South, driven by tradition, affordability, and nutritional needs, its acceptance in the Global North is markedly lower, often limited by cultural aversion and perceived risks. Drawing from published evidence and primary survey data, this review examines regional consumption trends, industrial utilization pathways, and emerging valorization opportunities for ABPs. Globally, industrial use of ABPs is increasingly shifting toward advanced bioprocessing, integration within circular bioeconomy models, and high-value applications in nutraceutical, pharmaceutical, and bio-industrial sectors. An online cross-sectional survey (n = 358) conducted across Africa, North America, Europe, and Asia revealed strong regional disparities in offal consumption, with higher acceptance in parts of Africa and Asia and more selective use in Europe and North America. Respondents also indicated clear support for non-food valorization pathways, particularly animal feed, fertilizer, and energy production, alongside pharmaceutical and cosmetic applications. These findings align with the literature, where industrial valorization pathways such as collagen and gelatin extraction, rendering, and bioenergy production dominate. This review synthesized the jurisdictional disparities in consumption, regulation, technological capability, and industrial applications while highlighting emerging technological opportunities for high-value valorization. Recommendations emphasize consumer education, regulatory refinement, technological innovation, and sustainable practices to enhance the economic and environmental benefits of ABP utilization within a circular bioeconomy framework.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc472f7a-0797-4bea-be3f-57a84d94ef8b', '4468519e-45b7-42e3-a131-b2181808b714', 'Calf gate and creep gate opening dimensions that pass a calf and stop a cow (extension consensus)', 'University of Florida IFAS (AG193); University of Georgia Extension (B 1315); Hi-Hog; Tarter', 2023, 'University extension publications and manufacturer specifications, compiled', NULL, 'https://fieldreport.caes.uga.edu/publications/B1315/creep-feeding-beef-calves/', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Extension publications and manufacturer specifications, freely accessible (compiled; no single PDF)', 'The dimensional answer to the ranch''s calf-gate question, drawn from creep-feeder design because that is the same cow-exclusion geometry problem. WIDTH is consistent across sources at 16-18 inches (41-46 cm): University of Florida gives 17-18 in wide by 36-48 in high; University of Georgia gives 18 in entrance slots; a general extension guide gives 16-18 in wide by 36-40 in tall; Hi-Hog''s calf creep feeder panel has openings approximately 17.25 in wide; Tarter''s panel has six 17 in openings. For a wire rather than a gate, UGA states that a single strand 36-42 in above ground lets calves pass under while keeping cows out. For growing calves, a non-university source suggests starting at 18 in of opening height and raising it to 20-22 in once calves average 300-400 lb - treat as advice. HEIGHT FOR WEANING-WEIGHT CALVES IS NOT PUBLISHED ANYWHERE: Hi-Hog''s commercial Calf Sorting Gate (item 382) is a 12 ft wide, 8 ft high split gate, about 297 lb, with seven height settings, and the instruction is simply to set the bottom of the upper section at the calves'' shoulder height and readjust as they grow. No study has measured any calf-gate dimension against pass rate or cow exclusion. A ranch must measure its own calves'' shoulder height; software must not assert a number here.', '{sorting,calf-gate,creep-gate,dimensions,cow-exclusion,extension,not-measured,measure-your-own,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7acf21c2-9f8d-4fec-bf9a-e91bdb11c644', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Laboratory Testing to Inform Antimicrobial Use for Bovine Respiratory Disease: Perceptions of Canadian Feedlot Veterinarians', 'Adewusi OO, Nykiforuk CIJ, Waldner CL, Erickson NEN, Gow SP, Otto SJG', 2025, 'Veterinary sciences', '10.3390/vetsci12050409', 'https://doi.org/10.3390/vetsci12050409', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12115976.1/PMC12115976.1.pdf', NULL, NULL, 19, NULL, 'alberta', 4, 'cc by', 'Timely, accurate, and reliable laboratory tools are important for antimicrobial stewardship (AMS) in food animal production. The objectives of this study were to (1) identify factors that influence live animal respiratory sample collection for laboratory testing and (2) describe the potential for integration of laboratory testing of samples from live animals into an AMS strategy for bovine respiratory disease (BRD) management in Canadian feedlots. Utilizing focused ethnography, virtual key informant interviews were conducted with eight feedlot veterinarians from Alberta, Ontario, and Saskatchewan, Canada. Thematic analysis revealed four themes: (1) lived experience of feedlot veterinarians with laboratory testing for BRD pathogens and antimicrobial resistance (AMR), (2) evidence-informed BRD management that integrates multiple data sources and their components, (3) organizational factors that affect the uptake and use of laboratory tests, and (4) the role of laboratory testing to support AMS in BRD management. While sample collection and laboratory testing are commonly used for BRD and AMR research and surveillance, they are not routinely applied in everyday BRD management. Veterinarians identified key challenges with laboratory testing, including turnaround time, the need for clear benefits, practical implementation, and effective communication with feedlot managers. Laboratory testing must provide valuable, actionable insights to encourage its adoption in Canadian feedlot operations. If successful, such testing could support AMS and be used to justify antimicrobial use if this were to become a regulatory or market requirement.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0f06be1-f6de-43d5-9cfa-352e2d9eff08', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Live cattle marketing : options for the future', 'Government of Alberta', 1988, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/live-cattle-marketing-options-for-the-future', 'https://open.alberta.ca/dataset/2a3ca88c-52c8-4638-89e8-e670e7567b20/resource/86202a05-037d-448e-aaf1-8ed7f70905e4/download/163003304439-live-cattle-marketing-options-for-the-future.pdf', NULL, NULL, 58, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report explores various marketing strategies and challenges facing the live cattle industry in Alberta, Canada. It examines the shift in consumer demand towards leaner beef, the implications of this trend for producers and packers, and the evolution of marketing systems including auction markets, direct farm buying, and electronic marketing. The document also provides insights into the advantages and disadvantages of marketing cattle into the United States. It ultimately seeks to equip producers with knowledge to enhance profitability and adapt to changing market conditions.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b1d539b2-8a5a-4cfc-a5fb-7810efc7eb79', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Management practices to improve the sustainability and profitability of cow-calf operations across Canada', 'Aaron Knodel', 2025, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/38824', 'https://mspace.lib.umanitoba.ca/bitstreams/1d860788-5d8b-4d06-be22-e1904ba3591d/download', NULL, NULL, 118, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5119e3a5-2270-4dba-9523-d696b7f3375e', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Mitigation of greenhouse gas emissions from beef cattle production systems', 'Stine Samsonstuen, Bente Aspeholen Åby, P. Crosson, Karen Ann Beauchemin, L. Aass', 2020, 'Acta Agriculturae Scandinavica Section A – Animal Science', '10.1080/09064702.2020.1806349', 'https://doi.org/10.1080/09064702.2020.1806349', 'https://www.tandfonline.com/doi/pdf/10.1080/09064702.2020.1806349?needAccess=true', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by-nc-nd', 'The whole-farm model HolosNorBeef was used to estimate the efficiency of GHG emission mitigation strategies in Norwegian beef cattle herds. Various mitigation scenarios, involving female reproductive performance (i.e. calf mortality rate and the number of calves produced per cow per year), production efficiency of young bulls for slaughter (i.e. age at slaughter and carcass weight), and supplementation of an inhibitor currently reported as promising for enteric methane (CH4) inhibition (3-nitrooxypropanol; 3-NOP) was investigated in herds of British and Continental breeds. Reducing calf mortality and increasing the number of produced calves per cow per year both reduced emission intensities by 3% across breeds. Continental breeds showed greater potential of reducing emission intensities due to increased carcass production. Combining mitigation options in a best case scenario reduced the total emissions by 11.7% across breeds. The emission intensities could be further reduced by 8.3% with the use of 3-NOP.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c79e26e-b92d-4e74-876f-9a3f5e52eb05', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Multi-year economic, productive & financial performance of Alberta cow/calf operations (2012-2016)', 'Government of Alberta', 2016, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/multi-year-economic-productive-financial-performance-of-alberta-cow-calf-operations-2011-2015', 'https://open.alberta.ca/dataset/d74cf3b6-ec90-45e6-8a94-2621d90f7cb9/resource/5d0ca1d0-dd52-41e6-85c0-34f66e59ba8d/download/16aballperfgrpsoct26v2.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This AgriProfit$ Cost & Returns Report presents a multi-year summary of the economic, productive, and financial performance of Alberta cow/calf producers. The research was undertaken through the Alberta Ministry of Agriculture and Forestry AgriProfit$ Business Analysis & Research program with the cooperation of producers across the Province. The report consist of a series of tables and figures with average historic provincial data showing the sales, production costs, selected production and financial indicators for the past 5 years.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('800db08b-80ea-474a-94ec-f8be704fde2d', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Opportunities for Laboratory Testing to Inform Antimicrobial Use for Bovine Respiratory Disease: Application of Information Quality Value Stream Maps in Commercial Feedlots', 'Otto SJG, Pollock CM, Relf-Eckstein JA, McLeod L, Waldner CL', 2024, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics13090903', 'https://doi.org/10.3390/antibiotics13090903', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11428555.1/PMC11428555.1.pdf', NULL, NULL, 22, NULL, 'alberta', 4, 'cc by', 'Background/objectivesThe implementation of information quality value stream maps (IQ-VSMs) in food animal production systems can increase our understanding of the opportunities and challenges when using laboratory testing for antimicrobial resistance (AMR) to support antimicrobial stewardship (AMS). Our objectives were to (1) explore the implementation of information quality value stream mapping as a continuous improvement tool to inform decisions for bovine respiratory disease (BRD) management and AMS and (2) apply the information quality dimensions to identified Kaizen opportunities for the integration of laboratory data into BRD management systems to assess the appropriateness of BRD treatment plans in western Canadian feedlot production.MethodsA ''Current State'' IQ-VSM outlined the processes, available information, information processing steps, and control decisions contributing to BRD management and treatment in commercial western Canadian feedlots, recognizing that laboratory BRD pathogens and AMR data are typically not part of BRD management.ResultsThe ''Future State'' IQ-VSM incorporated Kaizen opportunities for improvement, including (i) the strategic collection of respiratory samples from representative samples of calves for laboratory analysis, regardless of clinical BRD status, (ii) compilation of laboratory data at the pen and feedlot levels, and (iii) analysis of pen- and feedlot-level laboratory data to inform the veterinarian''s assessment of the appropriateness of current BRD treatment plans.ConclusionsThe IQ-VSMs provided a valuable framework to visualize the integration of BRD pathogen and AMR laboratory data to support AMS and address any potential future testing requirements.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ccc1a79e-b13b-4ff8-bb51-be48efd13f41', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Policies Affecting the Efficiency of Beef Production in Alberta: A Supply Chain Analysis', 'Derek Brewin', 2024, 'The School of Public Policy Publications', '10.55016/ojs/sppp.v17i1.78295', 'https://doi.org/10.55016/ojs/sppp.v17i1.78295', 'https://dev.journalhosting.ucalgary.ca/index.php/sppp/article/view/78295', NULL, NULL, 21, NULL, 'alberta', 4, 'open access (DOAJ)', 'Shoppers face high beef prices at the supermarket, but those prices are not a reflection of what Canadian farmers and ranchers earn from their cow-calf herds. In the past 30 years, the average beef producer’s operating margin has never reached $50,000, despite the fact that the average beef farm’s asset base stands at more than $2 million. Better access to export markets, including the U.S., South Asia and North Africa, would help to remedy the producers poor returns. Export prices would need to cover production costs, the largest of which is feed for the producers’ cattle herds, accounting for 77 per cent of the average ranch’s cash costs. As of July 2023, Alberta’s herd consisted of 1.77 million beef and dairy cows. With demand for livestock-derived food expected to jump by 38 per cent in the next 30 years, Canadian cattle ranchers need to take advantage of this global increase through freer trade. Canadian beef can remain competitive globally if the supply chain accesses world markets beyond the U.S., especially in developing countries where consumer incomes are increasing. The industry also needs investments in research, farm extension and supply chain co-ordination from national and provincial self-funded producer groups. Producers must look outward to global trade but be ready to capture new innovations at home. The dominant economies of scale are available to beef processors and finding savings is difficult for farmers and ranchers. However, there is potential for the supply chain to see savings from new technology, which is why investment in continuing support for ranch-level production research is necessary. Producers also need to focus on national co-ordination aimed at protecting trade access and responding to trends in consumer demand for beef. Any new industry policies must also consider key factors that currently affect market demand and expansion including: changing consumer preferences globally, the welfare of animals raised for slaughter and the effects of greenhouse gas emissions on supply chain sustainability. As some of the output and byproducts of the grain production sector provide feed for cattle, policies meant to support the grain sector may be indirectly influencing the beef sector significantly — for good and bad. Infrastructure required for worker safety, animal welfare improvements or improved food safety also adds to the cost of the beef supply. Protectionist trends and increased tariffs pose a threat to the supply chain because they too can create new costs. This is why access to foreign markets is crucial for producers, along with continued investment in research, sector-wide co-ordination to support market access and reviewing crop support to ensure livestock producers are compensated if grain policy changes harm them. Although live animals and much processed Canadian beef are exported to the U.S., fostering good trade relations in Asia and Africa is vital, given the growth in incomes and consumer demand for beef that is predicted for those regions. Free trade is the basis of good agriculture policy and any move towards protectionist policies and higher tariffs is the biggest threat for new costs in the supply chain. Canada’s beef sector requires low-cost access to foreign markets, making free trade policy the single most important policy focus for the sector.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1cd2a27b-df13-4956-9129-0d47784d1892', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Policing Farm Animal Welfare in Federated Nations: The Problem of Dual Federalism in Canada and the USA', 'Whiting TL', 2013, 'Animals : an open access journal from MDPI', '10.3390/ani3041086', 'https://doi.org/10.3390/ani3041086', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC4494357.1/PMC4494357.1.pdf', NULL, NULL, 37, NULL, 'prairies', 4, 'cc by', 'In recent European animal welfare statutes, human actions injurious to animals are new "offences" articulated as an injury to societal norms in addition to property damage. A crime is foremost a violation of a community moral standard. Violating a societal norm puts society out of balance and justice is served when that balance is returned. Criminal law normally requires the presence of mens rea, or evil intent, a particular state of mind; however, dereliction of duties towards animals (or children) is usually described as being of varying levels of negligence but, rarely can be so egregious that it constitutes criminal societal injury. In instrumental justice, the "public goods" delivered by criminal law are commonly classified as retribution, incapacitation and general deterrence. Prevention is a small, if present, outcome of criminal justice. Quazi-criminal law intends to establish certain expected (moral) standards of human behavior where by statute, the obligations of one party to another are clearly articulated as strict liability. Although largely moral in nature, this class of laws focuses on achieving compliance, thereby resulting in prevention. For example, protecting the environment from degradation is a benefit to society; punishing non-compliance, as is the application of criminal law, will not prevent the injury. This paper will provide evidence that the integrated meat complex of Canada and the USA is not in a good position to make changes to implement a credible farm animal protection system.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9b3f306d-b072-46c0-8fb3-716e142b58c1', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Potential for a white fat cow meat market in Canada', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/potential-for-a-white-fat-cow-meat-market-in-canada', 'https://open.alberta.ca/dataset/b9727835-d7a8-44ee-a534-a88b373d5669/resource/9632c947-6653-4b37-a52c-8afbd53df594/download/0163010373187-potential-for-a-white-fat-cow-meat-market-in-canada.pdf', NULL, NULL, 46, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report investigates the potential for developing a white fat cow meat market in Canada. It examines the entire value chain, discussing both the benefits and challenges associated with establishing a competitive supply chain for these products. The analysis highlights the need for increased domestic over thirty month (OTM) beef consumption and explores how a white fat cow market could displace imported beef. It also details the necessary industry cooperation and increased slaughter capacity to achieve a successful market.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('902c6bc3-418e-4723-a3fc-937565f43bb4', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Production practices and economic progress of Ontario beef cow-calf producers', 'Gillian Greaves', 2019, 'The Atrium (University of Guelph)', NULL, 'http://hdl.handle.net/10214/17703', 'http://hdl.handle.net/10214/17703', NULL, NULL, 192, NULL, 'prairies', 4, 'cc-by', 'The objectives of this thesis were: (1) to describe the Ontario cow-calf beef industry production practices, various management decisions and veterinary procedures, (2) to identify opportunities, barriers or impediments faced by the industry, and (3) to investigate differences in production practices across the province and in Western Canada. A cross-sectional observational study of Ontario cow-calf producers was initiated in spring 2017 using an online survey platform (Qualtrics.com (Provo, Utah, May, 2017)). Producers were asked questions regarding their 2016 calf crop and management behaviours related to calving, weaning, nutrition, reproduction and animal health. Information was also collected on the economics of production, technology use on-farm, and sources of information accessed. Overall, this study provides the industry with a baseline level of production in the province and highlights additional elements including education, extension, management practices and aging producer demographics that would benefit from further attention in research in the years to come.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5f073d8c-9250-450e-b3ad-3f3e9737d663', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Retrospective analysis of antimicrobial resistance associated with bovine respiratory disease', 'Kos D, Jelinski M, Ruzzini A', 2025, 'Applied and environmental microbiology', '10.1128/aem.01909-24', 'https://doi.org/10.1128/aem.01909-24', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11921372.1/PMC11921372.1.pdf', NULL, NULL, 18, NULL, 'prairies', 4, 'cc by', 'The administration and utility of antibiotics to control and treat bovine respiratory disease (BRD) in beef cattle feedlots is a growing concern. Antimicrobial resistance (AMR) among BRD-associated bacterial pathogens has been the subject of cultivation-dependent and cultivation-independent surveillance. Bacterial genome sequencing and metagenomic approaches facilitate the characterization of AMR in the beef industry; however, the current collection of cattle-associated AMR research programs lack connections to each other. A more integrated view of how antimicrobial use (AMU) is related to resistance at a gene level is needed. We sought to establish a catalog of commonly observed AMR genes (ARGs) in opportunistic bacterial pathogens that contribute to BRD using publicly available data sets that were generated by the scientific community with and without AMU in mind. The presence of these clinically relevant ARGs appeared to differ by geography. Greater sampling in North America facilitated the generation of a list of ARGs often encoded by Mannheimia haemolytica and Pasteurella multocida. Detection of clinically relevant ARGs in shotgun metagenomes of cattle-associated and accessible feedlot samples such as water, soil, and feces was possible but limited by relative sequence read abundance. An exception was the tylosin esterase-encoding gene estT, which is among the most frequently observed ARGs in M. haemolytica and feedlot-related metagenomic data sets. Finally, by re-evaluating studies on the impact of AMU on AMR in beef production systems, we show that conventional practices, including in-feed antibiotic use, increase the relative abundance of ARGs in animal-derived samples.IMPORTANCEThis retrospective analysis delivers a list of ARGs found in opportunistic pathogens that contribute to BRD. The high incidence of BRD in North America is linked to the origin and implementation of metaphylaxis to mitigate detrimental animal losses at feedlots. Notably, ARGs commonly observed in these pathogens isolated in North America were not conserved across the globe, underscoring the relationship between regional AMU and AMR. A positive relationship was also observed between the relative abundance of ARGs in cattle-associated metagenomes with greater exposure to antibiotics. Overall, this analysis should help to guide future surveillance efforts and experimental designs to more directly evaluate the impacts of feedlot practices on AMR.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7ad04ba6-946e-4611-bbbf-17b162edc223', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Special edition : 22 year economic, productive, and financial performance of Alberta cow/calf operations (1995-2016)', 'Government of Alberta', 2016, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/22-year-economic-productive-and-financial-performance-of-alberta-cow-calf-operations-1995-2016', 'https://open.alberta.ca/dataset/04af90b8-3233-4d40-930d-a5042b5e5342/resource/6d953852-d500-4efe-819c-d230d14f9054/download/22yearccbenchmarks1995-2016.pdf', NULL, NULL, 27, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Economic surveying of cow-calf operations in Alberta has a 33-year long history that started in 1985 with just few participating producers. As the number of participating producers grew it became possible to generalize the collected information and produce the sample averages or benchmarks. The benchmarks delivered to the producers and public presented major economic and production performance measures such as unit costs, net returns, cow conception and calf crop rates, among others. This special edition compiles all available electronic information starting from 1995 – 22 years and present it in the uniform format for comparison reasons.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f808a794-f6d4-421a-ad75-f4429425aead', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Strategies to improve the efficiency of beef cattle production', 'Stephanie A. Terry, J. A. Basarab, Le Luo Guan, Tim Angus McAllister', 2020, 'Canadian Journal of Animal Science', '10.1139/cjas-2020-0022', 'https://doi.org/10.1139/cjas-2020-0022', 'https://utoronto.scholaris.ca/bitstreams/a37fbd2f-513b-46ef-8804-88c6a9df077b/download', NULL, NULL, 54, NULL, 'southern_alberta', 5, 'cc-by', 'Globally, there are approximately one billion beef cattle, and compared with poultry and swine, beef cattle have the poorest conversion efficiency of feed to meat. However, these metrics fail to consider that beef cattle produce high-quality protein from feeds that are unsuitable for other livestock species. Strategies to improve the efficiency of beef cattle are focusing on operational and breeding management, host genetics, functional efficiency of rumen and respiratory microbiomes, and the structure and composition of feed. These strategies must also consider the health and immunity of the herd as well as the need for beef cattle to thrive in a changing environment. Genotyping can identify hybrid vigor with positive consequences for animal health, productivity, and environmental adaptability. The role of microbiome–host interactions is key in efficient nutrient digestion and host health. Microbial markers and gene expression patterns within the rumen microbiome are being used to identify hosts that are efficient at fibre digestion. Plant breeding and processing are optimizing the feed value of both forages and concentrates. Strategies to improve the efficiency of cattle production are a prerequisite for the sustainable intensification needed to satisfy the future demand for beef.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('714397d7-aacb-49f7-87e7-9c99313413f9', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Structure of a dynamic simulation model for beef cattle production systems', 'H. Pang, M. Makarechian, J. A. Basarab, Roy T. Berg', 1999, 'Canadian Journal of Animal Science', '10.4141/a99-020', 'https://doi.org/10.4141/a99-020', 'https://cdnsciencepub.com/doi/pdf/10.4141/A99-020', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a01b7a50-178c-40e7-8ae4-b876fb79b5ae', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Sustainable Overwintering Systems for Beef Cows on the Canadian Prairies: Challenges and Solutions', 'Gwendolyn Donohoe', 2019, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/33678', 'https://mspace.lib.umanitoba.ca/xmlui/bitstream/1993/33678/1/Donohoe_Gwendolyn.pdf', NULL, NULL, 257, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('92d2b20d-0ff1-434e-8209-5a0293fc29a6', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'The carbon footprint of beef cattle systems in the Southeast United States', 'José Carlos Batista Dubeux, Liza Garcia, Luana M. D. Queiroz, Erick R. S. Santos, Kenneth Tembe Oduor, Igor L. Bretas', 2022, 'Carbon Footprints', '10.20517/cf.2022.16', 'https://doi.org/10.20517/cf.2022.16', 'https://www.oaepublish.com/cf/article/download/5322', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Grasslands in the Southeast United States (SE US) cover 15.8 million ha and most of this area is dedicated to beef production systems. This region holds 6.3 million beef cows and 12.1 million cattle, including calves. Beef cattle systems in the SE US are mostly cow-calf based, and most of the greenhouse gas emission from cattle occurs during this phase (cow-calf) because of their forage-based diet. This review assessed the carbon footprint (C footprint) of beef cattle systems in the SE US and indicates possible ways to reduce it. Major emissions in beef cattle systems come from livestock enteric fermentation and greenhouse gases from excreta. Cow-calf systems in the SE US are typically low input, although they use some industrial fertilizers, machinery, and fossil fuel, which adds to the C footprint of the sector. There are opportunities to reduce the beef C footprint in the SE US by adopting climate-smart practices, including preservation of natural ecosystems that have potentially high carbon sequestration, afforestation, integration of forage legumes (and reduction of nitrogen fertilizer), use of slow-release fertilizers, and dietary interventions. In fact, depending on the level of adoption of some of these practices, it is possible to establish climate-neutral beef at the farm gate in the SE US. Beef is a key food for humans and has large economic effects. Development of climate-smart beef could create opportunities for a niche market that recognizes the environmental footprint of agricultural production and could incentivize producers to pursue those systems.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5f37a16c-7b8b-4832-933f-6a1f58ae0f33', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'The Potential for Sample Testing at the Pen Level to Inform Prudent Antimicrobial Selection for Bovine Respiratory Disease Treatment: Investigations Using a Feedlot Simulation Tool', 'Ramsay DE, McDonald W, Gow SP, McLeod L, Otto SJG, Osgood ND, Waldner CL', 2025, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics14101009', 'https://doi.org/10.3390/antibiotics14101009', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12562166.1/PMC12562166.1.pdf', NULL, NULL, 37, NULL, 'prairies', 4, 'cc by', 'Background: Antimicrobial drugs are used to treat bacterial diseases in livestock production systems, including bovine respiratory disease (BRD) in feedlot cattle. It is recommended that therapeutic antimicrobial use (AMU) in food animals be informed by diagnostic tests to limit the emergence of antimicrobial resistance (AMR) and preserve the effectiveness of available drugs. Recent evidence demonstrates preliminary support for the pen as a prospective target for AMR testing-based interventions in higher-risk cattle. Methods: A previously reported agent-based model (ABM) was modified and then used in this study to investigate the potential for different pen-level sampling and laboratory testing-informed BRD treatment strategies to favorably impact selected antimicrobial stewardship and management outcomes in the western Canadian context. The incorporation of sample testing to guide treatment choice was hypothesized to reduce BRD relapses, subsequent AMU treatments and resultant AMR in sentinel pathogen Mannheimia haemolytica. The ABM was extended to include a discrete event simulation (DES) workflow that models the testing process, including the time at sample collection (0 or 13 days on feed) and the type of AMR diagnostic test (antimicrobial susceptibility testing or long-read metagenomic sequencing). Candidate testing scenarios were simulated for both a test-only control and testing-informed treatment (TI) setting (n = 52 total experiments). Key model outputs were generated for both the pen and feedlot levels and extracted to data repositories. Results: There was no effect of the TI strategy on the stewardship or economic outcomes of interest under baseline ecological and treatment conditions. Changes in the type and number of uses by antimicrobial class were observed when baseline AMR in M. haemolytica was assumed to be higher at feedlot arrival, but there was no corresponding impact on subsequent resistance or morbidity measures. The impacts of sample timing and diagnostic test accuracy on AMR test positivity and other outputs were subsequently explored with a theoretical "extreme" BRD treatment protocol that maximized selection pressure for AMR. Conclusions: The successful implementation of a pen-level sampling and diagnostic strategy would be critically dependent on many interrelated factors, including the BRD treatment protocol, the prevalences of resistance to the treatment classes, the accuracy of available AMR diagnostic tests, and the selected "treatment change" thresholds. This study demonstrates how the hybrid ABM-DES model can be used for future experimentation with interventions proposed to limit AMR risk in the context of BRD management.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('19477e04-d834-4f9d-9246-8a857bbe466e', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Understanding Farmers'' Behavior and Their Decision-Making Process in the Context of Cattle Diseases: A Review of Theories and Approaches', 'Biesheuvel MM, Santman-Berends IMGA, Barkema HW, Ritter C, Berezowski J, Guelbenzu M, Kaler J', 2021, 'Frontiers in veterinary science', '10.3389/fvets.2021.687699', 'https://doi.org/10.3389/fvets.2021.687699', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC8674677.1/PMC8674677.1.pdf', NULL, NULL, 14, NULL, 'alberta', 4, 'cc by', 'Understanding farmers'' behavior regarding disease control is essential to successfully implement behavior change interventions that improve uptake of best practices. A literature review was conducted to identify theoretical underpinnings, analytical methodologies, and key behavioral determinants that have been described to understand farmers'' behavior in disease control and prevention on cattle farms. Overall, 166 peer-reviewed manuscripts from studies conducted in 27 countries were identified. In the past decade, there were increasing reports on farmers'' motivators and barriers, but no indication of application of appropriate social science methods. Furthermore, the majority (58%) of reviewed studies lacked a theoretical framework in their study design. However, when a theoretical underpinning was applied, the Theory of Planned Behavior was most commonly used (14% of total). The complexity of factors impacting farmers'' behavior was illustrated when mapping all described key constructs of the reviewed papers in behavior change frameworks, such as the socioecological framework and the Capability, Opportunity and Motivation Behavior (COM-B) model. Constructs related to personal influences and relationships between farmers and veterinarians were overrepresented, whereas constructs related to other interpersonal and contextual environments were not extensively studied. There was a general lack of use of validated scales to measure constructs and empirically validated theoretical frameworks to understand and predict farmers'' behavior. Furthermore, studies mainly focused on measurements of intention of stakeholder behavior rather than actual behavior, although the former is a poor predictor of the latter. Finally, there is still a lack of robust evidence of behavior change interventions or techniques that result in a successful change in farmers'' behavior. We concluded that for a sustainable behavior change, studies should include wider constructs at individual, interpersonal, and contextual levels. Furthermore, the use of empirically validated constructs and theoretical frameworks is encouraged. By using coherent frameworks, researchers could link constructs to design interventions, and thereby take the first step toward theory-driven, evidence-based interventions to influence farmers'' behavior for disease control.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4006704e-ea15-487a-9975-2de108f70f77', '2efe208c-b268-49a9-bb9a-ff8976d0648f', 'Unraveling the microbial diversity of bovine liver abscesses: isolation, identification, and genomic characterization of the Bacteroides found in hepatic lesions', 'R. J. Gruninger, M. L. McCormack, N. C. Chomistek, R. Zaheer, T. A. McAllister', 2025, 'Microbiology Spectrum', '10.1128/spectrum.00423-25', 'https://doi.org/10.1128/spectrum.00423-25', 'https://journals.asm.org/doi/10.1128/spectrum.00423-25', NULL, NULL, NULL, NULL, 'southern_alberta', 4, 'open access (DOAJ)', 'ABSTRACT Liver abscesses in cattle reduce animal performance, increase the environmental footprint of beef production, and cause significant economic losses. The low pH of the rumen resulting from the consumption of high grain diets damages the rumen epithelium and facilitates the translocation of opportunistic pathogens from the gastrointestinal tract into the bloodstream where they can colonize the liver, causing infection. Recently, 16s rRNA sequencing has revealed that 25%–50% of liver abscess microbiomes have prominent levels of Bacteroides. Due to the inability to reliably classify amplicon sequences beyond the genus level, the identity of these microbes remains unknown. We have employed a combination of culture-independent and culture-based methods to isolate and identify the Bacteroides associated with liver abscesses in cattle. Shotgun metagenomic sequencing and assembly of metagenome-assembled genomes generated four high-quality genomes, two of which were putatively identified as Bacteroides. These microbes were subsequently isolated from the purulent material of liver abscesses. Whole-genome sequencing conclusively identified these isolates as Bacteroides pyogenes and a previously unknown species of Bacteroides, revealing distinct differences from Bacteroides typically found in the gut. Carbohydrate utilization assays revealed that both organisms metabolize glycogen and glycosaminoglycans found in the extracellular matrix of the liver but display differences in substrate specificity. These data not only identify Bacteroides found in bovine liver abscesses but also provide new insights into the potential role that these organisms may play in this production-limiting disease.IMPORTANCELiver abscesses (LAs) are commonly found in cattle raised in feedlots and result from a bacterial infection of the liver. Not only are LAs a concern for animal health, but they also impact growth efficiency, animal welfare, and cost the North American beef industry upwards of $120 million per annum. Recently, it has been found that 25%–50% of liver abscess microbiomes have prominent levels of Bacteroides; however, to date, the biological relevance in LA pathogenesis and the identity of these bacteria are unknown. This research describes the isolation, identification, and genomic characterization of the Bacteroides found in bovine liver abscesses. These data provide a critical foundation for expanding our knowledge of the potential role Bacteroides play in liver abscess development and could contribute to the identification of novel targets for developing treatments to prevent this important production-limiting disease.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b1e4002-59de-4908-9c44-263fc99f657e', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Antimicrobial resistance in Enterococcus isolated from western Canadian cow-calf herds', 'Fossen JD, Campbell JR, Gow SP, Erickson N, Waldner CL', 2024, 'BMC veterinary research', '10.1186/s12917-023-03843-6', 'https://doi.org/10.1186/s12917-023-03843-6', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10763084.1/PMC10763084.1.pdf', NULL, NULL, 17, NULL, 'prairies', 4, 'cc by', 'BackgroundData on antimicrobial resistance (AMR) in cow-calf herds is limited and there have been no Canadian studies examining AMR in Enterococcus in cow-calf herds. Enterococcus is a ubiquitous Gram-positive indicator of AMR for enteric organisms that is also important in human health. The objective of this study was to describe AMR in specific Enterococcus species of interest from cow-calf herds; highlighting differences in AMR among isolates from cows and calves and samples collected in the spring and fall. Isolates (n = 1505) were examined from 349 calves and 385 cows from 39 herds in the spring of 2021 and 413 calves from 39 herds and 358 cows from 36 herds in the fall of 2021. Enterococcus species were identified using Matrix-Assisted Laser Desorption Ionization Time-Of-Flight mass spectrometry (MALDI-TOF MS) and antimicrobial susceptibility testing was completed based on a prioritization scheme for importance to human health and using the National Antimicrobial Resistance Monitoring System (NARMS) Gram positive Sensititre broth microdilution panel.ResultsResistance was observed to at least one antimicrobial in 86% (630/734) of isolates from the spring and 84% (644/771) of isolates from the fall. The most common types of resistance across all species were: lincomycin, quinupristin/dalfopristin, daptomycin, ciprofloxacin, and tetracycline. However, the proportion of isolates with AMR varied substantially based on species. Multiclass resistance, defined as resistance to ≥3 antimicrobial classes after excluding intrinsic resistance, was highest in isolates from calves in the spring (6.9%) (24/349) and cows in the fall (6.7%) (24/357). Differences in resistance were seen between cows and calves in the spring and fall as well as across seasons, with no differences seen between cows and calves in the fall.ConclusionsWhile most Enterococcus isolates were resistant to at least one antimicrobial, questions remain regarding species differences in intrinsic resistance and the accuracy of certain antimicrobial breakpoints for specific Enterococcus spp. As a result, some species-specific AMR profiles should be interpreted with caution. Despite these constraints, Enterococcus species are important indicator organisms for AMR and resulting data can be used to inform stewardship initiatives.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('80bbfc34-5902-49e3-80aa-7096edb00379', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Antimicrobial Use in Canadian Cow-Calf Herds', 'Fossen JD, Campbell JR, Gow SP, Erickson N, Waldner CL', 2023, 'Veterinary sciences', '10.3390/vetsci10050366', 'https://doi.org/10.3390/vetsci10050366', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10223781.1/PMC10223781.1.pdf', NULL, NULL, 28, NULL, 'prairies', 4, 'cc by', 'Despite growing concern surrounding antimicrobial use (AMU) and the importance of cow-calf herds to the Canadian livestock industry, surveillance of AMU in cow-calf herds to inform antimicrobial stewardship programs has been sporadic. Producers from the Canadian Cow-Calf Surveillance Network (87%, 146/168) provided data and almost all reported AMU in at least one animal (99%, 145/146 herds) in 2019-2020. The most common reasons for AMU were treatment of respiratory disease in nursing calves in 78% of herds and neonatal diarrhea in 67% of herds, as well as for lameness in cows in 83% of herds. However, most herds treated 30% of nursing calves from one herd. Similarly, while 56% of herds used macrolides at least once, within-herd use was the highest in nursing calves where 30% of animals. Herds using artificial insemination and calving in the winter were more likely (p = 0.05) to treat >5% of nursing calves for respiratory disease, suggesting the importance of vaccination programs for herds at risk. Overall, AMU was similar to previous Canadian studies; however, the percentage of herds using macrolides had increased from a comparable study in 2014.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('36661738-7e9e-4973-9e58-3341a1c583d0', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Bovine Respiratory Disease: Conventional to Culture-Independent Approaches to Studying Antimicrobial Resistance in North America', 'Andrés-Lasheras S, Jelinski M, Zaheer R, McAllister TA', 2022, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics11040487', 'https://doi.org/10.3390/antibiotics11040487', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9025279.1/PMC9025279.1.pdf', NULL, NULL, 26, NULL, 'southern_alberta', 5, 'cc by', 'Numerous antimicrobial resistance (AMR) surveillance studies have been conducted in North American feedlot cattle to investigate the major bacterial pathogens of the bovine respiratory disease (BRD) complex, specifically: Mannheimia haemolytica, Pasteurella multocida, Histophilus somni, and Mycoplasma bovis. While most bacterial isolates recovered from healthy cattle are susceptible to a repertoire of antimicrobials, multidrug resistance is common in isolates recovered from cattle suffering from BRD. Integrative and conjugative elements (ICE) have gained increasing notoriety in BRD-Pasteurellaceae as they appear to play a key role in the concentration and dissemination of antimicrobial resistant genes. Likewise, low macrolide susceptibility has been described in feedlot isolates of M. bovis. Horizontal gene transfer has also been implicated in the spread of AMR within mycoplasmas, and in-vitro experiments have shown that exposure to antimicrobials can generate high levels of resistance in mycoplasmas via a single conjugative event. Consequently, antimicrobial use (AMU) could be accelerating AMR horizontal transfer within all members of the bacterial BRD complex. While metagenomics has been applied to the study of AMR in the microbiota of the respiratory tract, the potential role of the respiratory tract microbiome as an AMR reservoir remains uncertain. Current and prospective molecular tools to survey and characterize AMR need to be adapted as point-of-care technologies to enhance prudent AMU in the beef industry.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1756b9b4-45c6-4b41-b1e8-e2b435e90a39', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Check list for completing a Grazing Timber Agreement (GTA) (January 4, 2008)', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3594022', 'https://open.alberta.ca/dataset/09240702-f5f0-449a-9371-ed4632c3e41d/resource/ccbb7602-d639-4645-ad8b-d81e91707a05/download/3594022-grazing-timber-agreement-checklist-2008.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This manual contains the requirements to guide the beef industry, timber industry, and Sustainable Resource Development staff in the integration of grazing and timber activities regionally and on overlapping grazing and timber dispositions. The manual is in accordance with the Lands Division and Forestry Division Policy Directive on Integration of Grazing & Timber Activities. It discusses the objectives related to integration of grazing and timber operations, the role of Regional Grazing-Timber Integration Advisory Committees, regional grazing plans, the grazing disposition application process, standards for integration of grazing and timber operations, and the dispute resolution process.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('34a27183-c799-4f8e-a467-4773fdd97263', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'The effects of spring versus summer calving on beef cattle reproductive and growth performance in western Canada', 'Obioha N Durunna, Lynne C. Girardin, Shannon L. Scott, Clayton D. Robins, Hushton C. Block, A. D. Iwaasa, Mohammad Khakbazan, H.A. Lardner', 2014, 'Canadian Journal of Animal Science', '10.4141/cjas2013-180', 'https://doi.org/10.4141/cjas2013-180', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas2013-180', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9bb4d466-c255-479e-b0d9-1935f6079f6b', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Low-stress livestock handling protects cattle in a five-predator habitat', 'Louchouarn NX, Treves A', 2023, 'PeerJ', '10.7717/peerj.14788', 'https://doi.org/10.7717/peerj.14788', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9924134.1/PMC9924134.1.pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc by', 'Given the ecological importance of top predators, societies are turning to non-lethal methods for coexistence. Coexistence is challenging when livestock graze within wild predator habitats. We report a randomized, controlled experiment to evaluate low-stress livestock handling (L-SLH), a form of range riding, to deter grizzly (brown) bears, gray wolves, cougars, black bears, and coyotes in Southwestern Alberta. The treatment condition was supervision by two newly hired and trained range riders and an experienced L-SLH-practicing range rider. This treatment was compared against a baseline pseudo-control condition of the experienced range rider working alone. Cattle experienced zero injuries or deaths in either condition. We infer that inexperienced range riders trained and supervised by an experienced rider did not raise or lower the risk to cattle. Also, predators did not shift to the cattle herds protected by fewer range riders. We found a correlation suggesting grizzly bears avoided herds visited more frequently by range riders practicing L-SLH. More research is required to compare different forms of range riding. However, pending experimental evaluation of other designs, we recommend use of L-SLH. We discuss the cobenefits of this husbandry method.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e18c07c9-77a6-40e6-a0ba-60c812f9190c', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Co-management of grazing dispositions and forest reserve permits', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/comanagement-of-grazing-dispositions-and-forest-reserve-permits', 'https://open.alberta.ca/dataset/370457bf-e735-43bb-96e5-5b07de329b30/resource/b2d661bc-8a14-4664-b91b-503dc6c616e0/download/2012-comanagementgrazingforestpermits-jan2012.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Holders of grazing leases, grazing licenses and forest reserve permits may apply to co-manage their disposition with another disposition holder. This will enable disposition holders to trial a partnership arrangement before making a decision to finalize a long-term partnership through full or partial assignment. Disposition holders may only have one co-management agreement per disposition. The co-management agreement may include any combination of grazing leases, grazing licenses or forest reserve permits.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('27ce1b64-2f4d-4d23-86b0-fc2865b7c642', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Comparing grazing and resting electivity of beef cattle for BC bunchgrass communities using GPS collars', 'Don J. Thompson, B. J. Wheatley, John S. Church, R. Newman, J. Walker', 2015, 'Canadian Journal of Animal Science', '10.4141/cjas-2014-116', 'https://doi.org/10.4141/cjas-2014-116', 'https://www.nrcresearchpress.com/doi/pdf/10.4141/cjas-2014-116', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('066bfdc6-0944-4a5e-8bed-2e5d37285ad9', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Dryland tame/native mixed pasture : Central Alberta (Aspen Parkland & portions of Boreal Transition)', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-cost-returns-profiles-dryland-tame-native-mixed-pasture-central-alberta', 'https://open.alberta.ca/dataset/4559d571-ecfd-4e70-a218-fc1fb1b2ecfc/resource/dd718d7c-49d3-40ab-a698-c160b52a4e4c/download/2012-agriprofit-dryland-tame-native-mixed-pasture-central-alberta-2012-07-30.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'AgriProfit$ cost and returns profiles give an insight into the productive and economic performance of Alberta cereal, oilseed, forage and grazing crops, reported by soil or grass-type zone. These benchmark include field observations from the period 2008 to 2010. Averaging over a three-year span smooths out extremes in prices, yields and expenses and gives a better reflection of the crops’ intermediate term costs and profit potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9b4310e7-45d2-4f7a-b144-1565a1af3d00', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Economic analysis and stochastic simulation of alternative beef calving and feeding systems in western Canada', 'Mohammad Khakbazan, Richard Carew, Shannon L. Scott, Paul Chiang, Hushton C. Block, Clayton D. Robins, Obioha N Durunna, John Huang', 2014, 'Canadian Journal of Animal Science', '10.4141/cjas2013-185', 'https://doi.org/10.4141/cjas2013-185', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas2013-185', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fbb589fc-2047-41ca-9069-759ba9536b76', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Effects of resting perennial pastures during the sensitive pre-dormancy period in western Manitoba: Pasture productivity and beef cattle performance', 'Obioha N Durunna, Vern S. Baron, Shannon L. Scott, Clayton D. Robins, Mohammad Khakbazan, Hushton C. Block', 2014, 'Canadian Journal of Animal Science', '10.4141/cjas-2014-046', 'https://doi.org/10.4141/cjas-2014-046', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas-2014-046', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('af019b04-92c1-4d5e-bf5e-922701b95961', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Management plan : Bob Creek Wildland, Black Creek Heritage Rangeland', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9780778594291', 'https://open.alberta.ca/dataset/673aecb2-dc41-4e48-90ee-baafeff1746a/resource/c1ad3bed-0f17-422a-af7f-4bcd61c15b7b/download/2011-07-bcbc-final-web.pdf', NULL, NULL, 55, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The management plan for Bob Creek Wildand and Black Creek Heritage Rangeland provides a long-term vision and day-to-day guidance for management of these protected areas. The management plan was developed by the Bob Creek / Black Creek Management Planning Team made up of representatives of the MD of Ranchland, grazing leaseholders, representatives of key stakeholder groups and government staff. The significant contribution of the grazing leaseholders, MD of Ranchland and stakeholder group representatives to the development of this management plan is sincerely appreciated. The plan was completed with public input and will be reviewed and revised periodically to reflect the current thinking of Albertans on how the province’s natural heritage and ranching history will be preserved for the benefit of present and future generations.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('34b0137b-3f8d-4307-acb1-cfbf63757e31', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Evaluating livestock use of boreal grazing lands : Little Smoky River project', 'Government of Alberta', 2013, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluating-livestock-use-of-boreal-grazing-lands-little-smoky-river-project', 'https://open.alberta.ca/dataset/27fc794c-6e4a-488f-b505-c857468e9772/resource/0057808f-65dd-474b-b10f-25453e8b310b/download/2013-evaluatinglivestockuseboreal-revised-2013.pdf', NULL, NULL, 60, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project highlights the importance of considering livestock preferences for different community types when developing a range management plan for a grazing operation, especially when this includes creating tame pastures. any range management plan needs to be tailored to the specific ranching operation that is being developed for, giving consideration to the unique characteristics of the landbase, plant community types present, other resource values and the available resources, goals, time and commitment of the manager.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d670f83-08c2-4743-9c45-2e206388262b', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Farming autonomy: Canadian beef farmers reclaiming the grass through management-intensive grazing practices', 'Erika Joy Heiberg, Karen Lykke Syse', 2020, 'Organic Agriculture', '10.1007/s13165-020-00291-6', 'https://doi.org/10.1007/s13165-020-00291-6', 'https://link.springer.com/content/pdf/10.1007/s13165-020-00291-6.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Abstract This qualitative study asks farmers in Alberta, Canada,what are their motivations for using a practice in beef production called management-intensive grazing (MIG). By adopting this practice, these farmers engage in strategies of diversification and co-production that increase the autonomy and resilience of their farms. MIG allows farmers to defy conventional agricultural practice and engage in what can be labelled a repeasantization process, a process that contributes to the discussion about conventional farming versus agroecology.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df6398a9-5f97-47fb-8e75-7eed2e088b23', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Feeding Management Strategies to Mitigate Methane and Improve Production Efficiency in Feedlot Cattle', 'Galyean ML, Hales KE', 2023, 'Animals : an open access journal from MDPI', '10.3390/ani13040758', 'https://doi.org/10.3390/ani13040758', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9952615.1/PMC9952615.1.pdf', NULL, NULL, 11, NULL, 'prairies', 4, 'cc by', 'Mitigation of greenhouse gases and decreasing nutrient excretion have become increasingly important goals for the beef cattle industry. Because feed intake is a major driver of enteric CH4 production and nutrient excretion, feeding management systems could be important mitigation tools. Programmed feeding uses net energy equations to determine the feed required to yield a specific rate of gain, whereas restricted feeding typically involves decreasing intake relative to the expected or observed ad libitum intake. In the context of growing/finishing systems typical of those in the United States and Western Canada, experimental results with programmed and restricted feeding have often shown decreased overall feed intake and increased gain efficiency relative to ad libitum feeding, but too much restriction can negatively affect harvest weight and associated carcass quality. Slick feed bunk management is a time-based restriction that limits day-to-day variation in feed deliveries, but the effects on intake and performance are not well defined. Simulations to estimate enteric CH4 emission and nitrogen excretion indicated that programmed feeding of a high-grain diet could appreciably decrease CH4 emissions and nitrogen excretion compared with traditional growing programs based on high-forage diets. For feedlot finishing, programming gain for a portion of the feeding period will decrease CH4 emission and N excretion only if cattle perform better than expected during the programmed phase or if compensatory growth occurs when cattle are transitioned to ad libitum feeding. Optimal approaches to implement programmed or restricted feeding that will yield increased efficiency should be the subject of future research in this area.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('68384c47-5e14-4ee7-af77-3d634f3e0ffa', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Grazing and farm development lease information signs', 'Government of Alberta', 2016, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/grazing-farm-development-lease-information-signs', 'https://open.alberta.ca/dataset/c24e53f1-2da3-4260-86d3-bd92a2d5846b/resource/a6af37c4-920d-4311-b0c8-dc9cb558ac21/download/trans-grazing-farm-development-lease-information-signs-2016-07.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Provides guidance on the recommended placement of grazing and farm development lease information signs. Part of a series of recommended practices for traffic control measures, including roadway signs and signals, pavement markings, traffic operations, roadside development and at-grade rail crossings.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3c66998-ea10-4f12-9eff-6cce46e9047e', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Measuring rangeland health : the rangeland health assessment protocol : an ecological tool for land stewards', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9780778582090', 'https://open.alberta.ca/dataset/eed9e57c-b4a4-4dda-ad22-ebad90ec5fe7/resource/111cc713-284b-49ce-b579-b909867c975b/download/measuringrangelandhealth-may20-2009a.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This brochure provides an introduction to how range health is measured, and its application and benefits. More detailed information such as the range health assessment field work books for native grasslands and forests, and tame pasture can be found by viewing the Rangeland Health and Assessment menu.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('53b8cb28-9fe6-4486-9b69-82cb543c95db', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Grazing lease stewardship code of practice', 'Government of Alberta', 2007, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/grazing-lease-stewardship-code-of-practice', 'https://open.alberta.ca/dataset/021cef85-37dc-4181-95a4-a46c4264ca55/resource/0a6b3e61-710b-49f2-9f41-acc13522005a/download/2007-grazingleasestewardshipcodepractice-2007.pdf', NULL, NULL, 32, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The code describes overarching management principles, required practices that flow from these principles, tools for the measurement of range health and the responsibilities of grazing leaseholders. The focus is on promoting sustainable use of public grazing land for the long-term benefit of leaseholders, the environment, industry, recreational users and all Albertans. The Public Lands Act and associated regulations provide the requirements associated with grazing leases. This document seeks to describe the roles and responsibilities of leaseholders as they exist at this time.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('27326679-9031-4030-bdb0-bc19ac62a895', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Grazing management adjustments for healthy rangelands', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9780778570103', 'https://open.alberta.ca/dataset/88781d33-3869-46eb-9b7c-87ae86ce02af/resource/1fb7fdfe-2ea3-4ecc-a447-106da8aa822d/download/2008-grazingmanagementhealthyrangelands-2008.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'As a livestock producer, the number one stewardship practice you need to consider is balancing animal numbers with the available forage supply of your grazing lease. The combination of too many animals and not enough forage can create serious problems for animal performance and range health. When you adjust your animal units for an increased animal unit size, it creates a balance between animals performance and range health.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa433ef3-216a-48b7-b177-297185f74c74', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Heritage rangelands operational management directive', 'Government of Alberta', 2015, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/aep-public-land-management-2015-no-1', 'https://open.alberta.ca/dataset/95488d66-e908-4a51-8dcf-4c4d25830317/resource/18556d47-95eb-4e3c-894c-d808a91449f2/download/2015-heritage-rangelands-operational-directive-jun-15-2015.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Heritage rangelands and heritage rangeland natural areas are an important component of Alberta''s protected area network. This directive provides direction on the management of heritage rangelands across the province by the Government of Alberta through Alberta Environment and Parks. This includes planning, policy development and the issuance and management of non-energy resource dispositions under the Public Lands Act.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('85442226-02d3-48c1-a672-0ccc5f940a06', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'High levels of third-stage larvae (L3) overwinter survival for multiple cattle gastrointestinal nematode species on western Canadian pastures as revealed by ITS2 rDNA metabarcoding', 'Wang T, Avramenko RW, Redman EM, Wit J, Gilleard JS, Colwell DD', 2020, 'Parasites & vectors', '10.1186/s13071-020-04337-2', 'https://doi.org/10.1186/s13071-020-04337-2', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7488095.1/PMC7488095.1.pdf', NULL, NULL, 11, NULL, 'alberta', 4, 'cc by', 'BackgroundThe ability of infective larvae of cattle gastrointestinal nematode (GIN) species to overwinter on pastures in northerly climatic zones with very cold dry winters is poorly understood. This is an important knowledge gap with critical implications for parasite risk assessment and control.MethodsInfective third-stage larvae (L3) were quantified in samples of fecal pats, together with adjacent grass and soil, before and after winter on three farms in southern, central and northern Alberta. Nemabiome ITS2 metabarcoding was then performed on the harvested L3 populations to determine the species composition. Finally, parasite-free tracer calves were used to investigate if the L3 surviving the winter could infect calves and develop to adult worms in spring.ResultsFarm level monitoring, using solar powered weather stations, revealed that ground temperatures were consistently higher, and less variable, than the air temperatures; minimum winter air and ground temperatures were - 32.5 °C and - 24.7 °C respectively. In spite of the extremely low minimum temperatures reached, L3 were recovered from fecal pats and grass before and after winter with only a 38% and 61% overall reduction over the winter, respectively. Nemabiome ITS2 metabarcoding assay revealed that the proportion of L3 surviving the winter was high for both Cooperia oncophora and Ostertagia ostertagi although survival of the former species was statistically significantly higher than the latter. Nematodirus helvetinaus and Trichostrongylus axei could be detected after winter whereas Haemonchus placei L3 could not overwinter at all. Adult C. oncophora, O. ostertagi and N. helvetianus could be recovered from tracer calves grazing after the winter.ConclusionsThe largest proportion of L3 were recovered from fecal pats suggesting this is important refuge for L3 survival. Results also show that L3 of several GIN parasite species can survive relatively efficiently on pastures even in the extreme winter conditions in western Canada. Tracer calf experiments confirmed that overwintered L3 of both C. oncophora and O. ostertagi were capable of establishing a patent infection in the following spring. These results have important implications for the epidemiology, risk of production impact and the design of effective control strategies. The work also illustrates the value of applying ITS2 nemabiome metabarcoding to environmental samples.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e475ea7e-61a5-471d-83ef-5f6c4c9fef2d', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Impact of grazing on soil mesofauna diversity and community composition in deciduous forested rangelands of northwest Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/impact-of-grazing-on-soil-mesofauna-diversity', 'https://open.alberta.ca/dataset/303a7691-a457-4b7e-a32b-f39b034060ec/resource/1883d8df-abe6-4848-a1bb-ba6d46cc6f66/download/2011-soilmesofaunaforestedrangelands-feb2011a.pdf', NULL, NULL, 27, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'In an attempt to evaluate the ecological function of forested rangelands, the forested range health assessment protocol was developed. The protocol measures a number of key vegetation and soil parameters in order to estimate forested range health. Although certain soil parameters are indirectly assessed through measurements of LFH, there is limited knowledge about how these metrics relate to soil ecosystem health and the structure and composition of soil mesofaunal communities. In this study, the relationships between different range health gradients and soil mesofauna were evaluated.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3de886f8-6fc2-4262-ba08-b03f6524be45', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Improving beef calf health: frequency of disease syndromes, uptake of management practices following calving, and potential for antimicrobial use reduction in western Canadian herds', 'Waldner C, Wilhelm B, Windeyer MC, Parker S, Campbell J', 2022, 'Translational animal science', '10.1093/tas/txac151', 'https://doi.org/10.1093/tas/txac151', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9749396.1/PMC9749396.1.pdf', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by-nc', 'Bovine respiratory disease (BRD), calf diarrhea (CD), and navel infections are the most commonly reported diseases of western Canadian beef calves. The objectives of this study were to estimate the frequency of treatment for these diseases for specific age cohorts and identify potential opportunities for reducing antimicrobial use. Producers representing 89 western Canadian cow-calf herds completed a survey describing calfhood diseases and management. The most common reason for calf treatment before weaning was BRD (4.9%), and BRD treatment was described in 51% of reporting herds before 2 months of age. Calf diarrhea (2.9%) and navel infection (2.0%) were the second and third most common reasons for treatment. Most calves were treated for CD between 6 days and 1 month of age. Almost one in five herds reported routinely administering antimicrobials at birth. Calving heifers and cows together were all associated with an increased treatment risk for BRD in calves from birth to 2 months (OR 3.55, 95%CI 2.13-5.94, P P = 0.02), and navel infection (OR 4.55, 95%CI 1.78-11.6, P = 0.002). Failure to sort cow-calf pairs out of the calving area was also associated with an increased treatment risk for BRD from 4 months to weaning (OR 4.89, 95%CI 1.96-12.2, P = 0.0006) and CD from 24 h to 5 days (OR 2.82, 95%CI 1.03-7.75, P = 0.04), and not using the Sandhills system was associated with an increased treatment risk for navel infection (OR 4.55, 95%CI 1.78-11.6, P = 0.002). Other potentially modifiable factors associated with an increased risk of BRD in calves from birth to 2 months were winter feeding and calving in one area (P P = 0.01), and an increasing number of times cow-calf pairs were gathered before turn out to summer pasture (P = 0.0005). The purchase of any cows during the calving or prebreeding period was associated with an increased risk of BRD from birth to 2 months (P P P = 0.01). Cows calving in a higher density area was associated with an increased risk of CD from 1 month to weaning (P = 0.02). These practices present opportunities for investigation of approaches to disease management that could support the judicious use of antimicrobials.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e8245190-72c8-4d1f-a683-9ee41ceaf813', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Increased Nitrogen Retention and Reduced Methane Emissions of Beef Cattle Grazing Legume vs. Grass Irrigated Pastures in the Mountain West USA', 'Jennifer W. MacAdam, Lance R. Pitcher, Andrea I. Bolletta, Raúl David Guevara, Karen Ann Beauchemin, Xin Dai, Juan Jose Villalba', 2022, 'Agronomy', '10.3390/agronomy12020304', 'https://doi.org/10.3390/agronomy12020304', 'https://www.mdpi.com/2073-4395/12/2/304/pdf?version=1645666478', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by', 'Grazing studies were carried out over a 5-year period using pregnant cows, yearling calves and 2-year-old heifers to investigate the influence of diet on intake, methane (CH4) emissions and retention of nitrogen (N). Monoculture legume (birdsfoot trefoil, BFT and cicer milkvetch, CMV) or grass (meadow bromegrass, MBG) pastures were rotationally stocked, and during year 4 and year 5, treatments were contrasted with total mixed rations (TMR) fed in confinement. The sulfur hexafluoride (SF6) method was used to continuously measure enteric CH4 emissions. Intake was greater on legume pastures and on TMR than on grass pastures, and enteric CH4 emissions per unit of intake were lower on legumes compared with grass pastures. Legume pastures had elevated non-fiber carbohydrate (NFC) concentrations (400 g kg−1 dry matter; DM) typical of perennial legumes cultivated in the Mountain West. A N balance calculated in 2017–2018 demonstrated that N retention was greater for TMR and legume than grass pastures. Enteric CH4 emissions of grazing cow herds account for the majority of greenhouse gas (GHG) emissions from beef production and can be significantly reduced by using highly digestible forage legumes. The N retention of legumes can potentially enhance the efficiency of N use, thereby increasing the sustainability of grasslands.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.645588+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('25fa78eb-0182-4907-9add-af5adddbb203', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Integration of ITS-2 rDNA nemabiome metabarcoding with Fecal Egg Count Reduction Testing (FECRT) reveals ivermectin resistance in multiple gastrointestinal nematode species, including hypobiotic Ostertagia ostertagi, in western Canadian beef cattle', 'De Seram EL, Uehlinger FD, de Queiroz C, Redman EM, Campbell JR, Nooyen D, Morisetti A, Pollock CM', 2023, 'International journal for parasitology. Drugs and drug resistance', '10.1016/j.ijpddr.2023.04.002', 'https://doi.org/10.1016/j.ijpddr.2023.04.002', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10165142.1/PMC10165142.1.pdf', NULL, NULL, 9, NULL, 'prairies', 4, 'cc by-nc-nd', 'A large-scale Fecal Egg Count Reduction Test (FECRT) was integrated with ITS-2 rDNA nemabiome metabarcoding to investigate anthelmintic resistance in gastrointestinal nematode (GIN) parasites in western Canadian beef cattle. The study was designed to detect anthelmintic resistance with the low fecal egg counts that typically occur in cattle in northern temperate regions. Two hundred and thirty-four auction market-derived, fall-weaned steer calves coming off pasture were randomized into three groups in feedlot pens: an untreated control group, an injectable ivermectin treatment group, and an injectable ivermectin/oral fenbendazole combination treatment group. Each group was divided into six replicate pens with 13 calves per pen. Individual fecal samples were taken pre-treatment, day 14 post-treatment, and at monthly intervals for six months for strongyle egg counting and metabarcoding. Ivermectin treatment resulted in an 82.4% mean strongyle-type fecal egg count reduction (95% CI 67.8-90.4) at 14 days post-treatment, while the combination treatment was 100% effective, confirming the existence of ivermectin-resistant GIN. Nemabiome metabarcoding of third-stage larvae from coprocultures revealed an increase in the relative abundance of Cooperia oncophora, Cooperia punctata, and Haemonchus placei at 14 days post-ivermectin treatment indicating ivermectin resistance in adult worms. In contrast, Ostertagia ostertagi third-stage larvae were almost completely absent from day 14 coprocultures, indicating that adult worms of this species were not ivermectin resistant. However, there was a recrudescence of O. ostertagi third stage larvae in coprocultures at three to six months post-ivermectin treatment, which indicated ivermectin resistance in hypobiotic larvae. The calves were recruited from the auction market and, therefore, derived from multiple sources in western Canada, suggesting that ivermectin-resistant parasites, including hypobiotic O. ostertagi larvae, are likely widespread in western Canadian beef herds. This work demonstrates the value of integrating ITS-2 rDNA metabarcoding with the FECRT to enhance anthelmintic resistance detection and provide GIN species- and stage-specific information.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('94e1d69a-914a-4f5a-849f-8e3c15326842', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Invasive plants in Alberta. Native Rangeland', 'Government of Alberta', 2014, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/6740684', 'https://open.alberta.ca/dataset/8263f521-9b52-4dab-9e34-4d20840d32f2/resource/081d31e9-1801-434c-89b9-32cd723cac48/download/6740684-2014-invasive-plants-alberta-native-rangeland-640-21-2014-02.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Land owners and occupiers are responsible for controlling noxious weeds and destroying prohibited noxious weeds under the Alberta Weed Control Act. Listed plants in the Act cause problems for the environment, health or economy. Know your responsibilities under the Act. Regardless of where plants are located, prevention is always the most effective approach in dealing with invasive plants.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b4e55ef7-08dc-4108-9a08-b32c2577caf8', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Locking gates on grazing leases and farm development leases', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/apl-2012-001', 'https://open.alberta.ca/dataset/60b385f9-588a-4e4c-b5cf-e841d45d88a0/resource/45ea1538-fdfc-44d7-a73a-245452dd68ca/download/2012-lockinggatesgrazingfarmleases-nov19-2012.pdf', NULL, NULL, 1, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Provides information on when Licences of Occupation (LOCs) on grazing leases may be locked.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3c7f045e-55c4-4ca0-a048-82a6cf403b58', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Trapper access to grazing leases', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/trapper-access-to-grazing-leases', 'https://open.alberta.ca/dataset/f1b0b4e9-c67d-423d-9ac8-6b42ba00d644/resource/0b295b93-94b5-4a7c-b4e3-c60cf9e17fbb/download/trapperaccessgrazingleases-2011.pdf', NULL, NULL, 1, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This information letter outlines the issue resolution process for disputes involving trapper access to lands under grazing leases.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e04fc965-8fe3-48cc-9b2a-606d2c4bacb9', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Monitoring rangelands in the mixedgrass prairies of southern Alberta with rangeland enhanced Landsat imagery : a users guide', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/monitoring-rangelands-in-the-mixedgrass-prairies-of-southern-alberta-with-rangeland-enh', 'https://open.alberta.ca/dataset/931fee39-4573-4561-9afe-c7db942e938d/resource/0b307283-4712-4c08-b629-e506448f62da/download/monitoring-rangelands-mixedgrass-prairies-southern-alberta-with-rangeland.pdf', NULL, NULL, 24, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This document presented a revised 1984 users guide that described the purpose, methods and results of the Alberta Rangeland Study, which evaluated the use of rangeland enhanced Landsat imagery for monitoring grazing conditions in the Mixedgrass Prairie of southern Alberta. It outlined the study background, characteristics of the study area, field and image analysis methods, and interpretation techniques required to assess rangeland condition using satellite imagery. It summarized key findings that supported practical applications for range managers, including the ability to identify grazing patterns, vegetation condition and problem areas across large landscapes. It also explained ordering procedures for enhanced imagery and the availability of interpretation training. This document served as a practical reference for land managers who used remote sensing to support rangeland management planning.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff77684d-964e-4132-acd6-59302686422f', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Nutrient management on intensively managed pastures', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4416930', 'https://open.alberta.ca/dataset/c64449c7-e838-40a4-b528-b76e8be82e4f/resource/4a7b5697-da49-4d19-83c0-8f2a8936537b/download/2009-130-538-1.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Pastures are unique to agricultural production systems in that only a very small portion of the nutrients required for crop production are removed from the system. Up to 90 per cent of the nutrients ingested by grazing animals are returned to the land in manure (excreta), which is comprised of urine and dung. The rest is utilized in animal maintenance and growth or milk production. Nutrient cycling is faster on grazed than ungrazed grassland because most of the nutrients in manure have been converted from organic (plant material) to inorganic, plant-available forms during the digestive process.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dcd7276b-4558-4f28-9f18-0580a3e13921', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Operating standards for Alberta’s Crown land grazing dispositions', 'Government of Alberta', 2023, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/operating-standards-albertas-crown-land-grazing-dispositions', 'https://open.alberta.ca/dataset/2bdfb118-dc25-4f6c-a565-271728de126f/resource/24114670-3172-47e5-8ee5-92e615fc8ed8/download/fpt-operating-standards-albertas-crown-land-grazing-dispositions.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Describes the grazing dispositions available on Alberta''s Crown land and has been updated to reflect the Crown Land Vision and to include the grazing dispositions administered under the Provincial Parks Act. This document compliments the Stewardship for Rangeland Sustainability document.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('581dd279-78e5-4deb-a67f-47181aad9831', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Operating standards for Alberta’s public land grazing dispositions [2019]', 'Government of Alberta', 2019, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9781460143698', 'https://open.alberta.ca/dataset/53255d22-3f42-49e0-9677-8a0c07f0c3a5/resource/f1dd8a81-c90d-4246-bbde-e136a09296bf/download/aep-operating-standards-albertas-public-land-grazing-disposition-2019.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This publication provides information on the legislative and regulatory requirements of holding a public land grazing disposition in a convenient and accessible format.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f4323b15-68c5-460c-8f6c-8bb0f94d4536', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Pasture pipeline design [2023]', 'Government of Alberta', 2023, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/pasture-pipeline-design', 'https://open.alberta.ca/dataset/04bc2bb4-b3ec-4244-894d-47f7c33e7d9c/resource/31ed37fb-a03b-47d6-902f-7420d667186c/download/agi-pasture-pipeline-design-2023.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet provides information about pasture pipeline design. It provides information on how to design a system to supply water during the summer to livestock in a pasture.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('86ad4289-8208-4cad-a3fd-99a7828f9a40', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Perimeter fence line clearing on grazing leases', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/perimeter-fence-line-clearing-on-grazing-leases', 'https://open.alberta.ca/dataset/831557bd-c89c-4fca-b0f3-8ddbc426e141/resource/b6f7de0f-9c84-41df-867a-78de9f7055e0/download/fp-perimeter-fence-line-clearing-on-grazing-leases-2024.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A fact sheet about the importance of fence line clearing on public land grazing leases.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0d97e462-8100-44d0-aaa8-819efc30c473', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Potential of rangelands to sequester carbon in Alberta', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9780778582045', 'https://open.alberta.ca/dataset/eacfa19a-1b94-42e3-8d9b-a87c15399db4/resource/6de6a4de-ab60-4a9f-9e02-652512841e7f/download/2008-potentialrangelandssequestercarbon-2008.pdf', NULL, NULL, 11, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Large amounts of organic carbon are present in Alberta rangelands. One hectare of rangeland contains 50-200 tonnes of carbon in soil organic matter, 2-10 tonnes carbon in plant biomass and 1-2 tonnes carbon in litter. Total organic carbon levels in rangeland soils are considerably greater than the amount of carbon present in the atmosphere above these soils or exchanged with the atmosphere each year. Total organic carbon in the 7 million hectares of native pasture in Alberta is equivalent to about three times the current annual emissions of all greenhouse gases in Canada.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d88972c-5b98-4231-a2d2-9fb629e830de', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Range and pasture management when dealing with drought', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/range-and-pasture-management-when-dealing-with-drought', 'https://open.alberta.ca/dataset/b0367ede-8412-41c8-8cbc-b1101d260755/resource/84bd9e63-00f9-43c7-abe9-dcd0a179dbf6/download/zz-2813313-2009-agri-facts-range-pasture-management-when-dealing-drought-130-14-1-2009-06.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Every district or ranch has poor production years because of drought. One of the risks in farming or ranching is based on whether drought occurs often or as infrequently as once every 20 years. Good range and pasture management will minimize the effects of drought when it occurs.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5998e64b-5fc4-49da-a9bf-66092a433e45', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Range health assessment : field worksheet for Tame Pasture [May 2017]', 'Government of Alberta', 2017, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/range-health-assessment-field-worksheet-for-tame-pastures', 'https://open.alberta.ca/dataset/2d43720a-fa26-4be1-8838-c692c083e1d6/resource/bb00575e-48af-4551-a40b-1505411d4ce8/download/rangehealthworksheet-tamepasture-2017.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The term "rangeland health" is used to mean the ability of rangeland to perform certain key functions. The term health conveys the meaning that all parts that make up the whole, are present and working together. Recently, within the range scientific community, there has been a move to define rangeland health on a broader list of functions. For rangelands, the functions of healthy range include: * Net primary production. * Maintenance of soil/site stability. * Capture and beneficial release of water. * Nutrient and energy cycling. * Functional diversity of plant species.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad8b9d62-0cec-4c5d-81f0-3c462f060f06', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Range inventory manual for forest reserve allotments and grazing leases within rocky mountain, foothills, parkland and grassland natural regions', 'Government of Alberta', 2018, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9781460139486', 'https://open.alberta.ca/dataset/b5ef5c6d-e1ac-478e-a311-d30dd247f07f/resource/2e47e959-b7e5-4b5b-ac04-92ef084e6215/download/range-inventory-manual-2018.pdf', NULL, NULL, 78, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The Range Inventory Manual provides a structured methodology to complete a detailed survey of the rangeland resource. It sets out a methodology to stratify the landscape into management units and describe these units by standardized vegetation data collection. The purpose of an inventory is to quantify the landscape to provide a basis for management decisions that will maintain the natural ecological functions of each management unit.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0407dfd2-db69-48b4-8d02-f08847b335cb', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Rangeland sustainability program : project eligibility criteria', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/rangeland-sustainability-program-project-eligibility-criteria', 'https://open.alberta.ca/dataset/1abea7db-a676-47af-88ef-18735eaccc68/resource/f4d7c570-ef3d-45d4-ab5d-be9d8d31b3bb/download/fp-rangeland-sustainability-program-project-eligibility-criteria-2024-08.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The document includes a breakdown of how the grant applicants to the Rangeland Sustainability Program are scored.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bdd627ab-89b7-4da0-9dd2-a18690f45203', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Range management factsheet for northern Alberta''s boreal region : indicators of forest rangeland health', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9780778584711', 'https://open.alberta.ca/dataset/4590f220-0087-4f32-852e-cb4474c5e164/resource/a6fb53d4-a0f3-4ab4-a08b-82dd3492e8c8/download/2011-indicatorsrangelandhealth-factsheet-2011.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Rangeland health refers to the ability of a plant community to perform vital ecological functions. Healthy rangelands have a variety of plants, prevent soil erosion, store water and promote the cycling of nutrients and energy. To determine the health of your rangeland, start by asking questions.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8f9a280a-8814-429e-9e84-7d4363dd412e', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Rangeland grazing framework', 'Government of Alberta', 2023, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/rangeland-grazing-framework', 'https://open.alberta.ca/dataset/3bf2edc1-c51a-4806-b8f7-5d6cb766cbb5/resource/1208ac0a-493a-45cd-b678-d59f7213563b/download/fpt-rangeland-grazing-framework.pdf', NULL, NULL, 13, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Alberta has approximately 3.3 million hectares of Crown rangelands held under grazing dispositions. The Rangeland Grazing Framework recognizes that sustainable management of Alberta''s Crown rangelands relies on collaborative land management by the disposition holder and the province. The framework supports the province''s Crown land vision by outlining the essential role of grazing and rangeland stewardship by disposition holders in achieving the environmental objective and long-lasting economic and social outcomes on Crown rangelands that benefit all Albertans.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce13c004-8ba8-4604-bcb3-7af11cbb9345', '4468519e-45b7-42e3-a131-b2181808b714', 'Calf health and performance during receiving is not changed by fence-line preconditioning on Flint Hills range vs. drylot preconditioning', 'Bailey, E.A.; Jaeger, J.R.; Waggoner, J.W.; Preedy, G.W.; Pacheco, L.A.; Olson, K.C.', 2013, 'Kansas Agricultural Experiment Station Research Reports (Cattlemen''s Day), Kansas State University', '10.4148/2378-5977.1431', 'https://newprairiepress.org/kaesrr/vol0/iss1/28/', 'https://journals.newprairiepress.org/kaesrr/article/10249/galley/10151/download/', NULL, NULL, 8, NULL, 'northern_plains', 5, 'Free and open access (New Prairie Press); may be freely reproduced for educational purposes', 'The most important study for a prairie ranch, because it is the one that shows fenceline weaning onto fall native range can lose weight for a month. 460 Angus x Hereford calves, initial BW 496 +/- 77 lb, weaned at about 180 days, assigned to three 28-day ranch-of-origin programmes: drylot with full dam separation (earth pen, minimum 215 sq ft/calf, 18 in bunk space/calf, diet formulated for 2.2 lb ADG at 2.5% BW DMI); pasture with 7 days of fenceline contact; or pasture plus fenceline plus supplement in portable bunks at 1% BW three times a week. Fenceline specification is given in full: minimum pasture area 118 acres, minimum shared frontage 656 feet (200 m), four-strand barbed wire with the bottom two wires electrified, cows moved out of visual and auditory range after 7 days. 28-day preconditioning ADG was +0.68 lb/d for drylot vs -0.62 (pasture+supplement) and -0.75 lb/d (pasture) (P=0.08). All calves then shipped 4 h to a feedlot: drylot calves had greater ADG day 0-60 (3.13 vs 2.93 and 2.82 lb/d, P<0.01), greater day-60 BW (697 vs 655 and 644 lb, P<0.01), higher DMI and better feed:gain (5.49 vs 6.04), and a greater proportion came to the bunk at feeding during the first 4-5 days (P<0.05). Fever incidence did not differ during preconditioning (P=0.22) and was 0.9% overall during receiving, too low to test. The authors conclude that previous experience eating a concentrate diet from a bunk paid greater dividends during receiving than reducing maternal-separation stress through fenceline contact. The peer-reviewed version is Bailey et al. 2016, Professional Animal Scientist 32:220-228.', '{weaning,fenceline,drylot,preconditioning,fence-spec,paddock-size,bunk-space,weight-gain,receiving,null-result,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d3fcf5b2-f1a3-4127-a5a6-7b0eda0ce415', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Rangeland grazing framework : fostering the health and sustainability of Alberta’s Crown rangelands', 'Government of Alberta', 2023, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/rangeland-grazing-framework-fact-sheet', 'https://open.alberta.ca/dataset/c4edf197-59e6-4422-91c2-8de73a907115/resource/81423654-8813-487c-b9ad-3439fc628395/download/fpt-rangeland-grazing-framework-fact-sheet.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet provides an overview and outlines the intent of the Rangeland Grazing Framework. The framework supports the Crown land vision by outlining the essential role of grazing and rangeland stewardship by disposition holders in achieving the environmental objective and long-lasting economic and social outcomes on Crown rangelands that benefit all Albertans.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('954e4230-7f85-475e-9484-4c1397b1b146', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Rangeland health assessment for grassland, forest and tame pasture [2016]', 'Government of Alberta', 2016, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9781460127858', 'https://open.alberta.ca/dataset/51cad211-09f6-49bd-86ef-ca3162f2ea7a/resource/2cadf8f4-ef65-4e48-812e-10f8daf027a8/download/rangelandhealthassessment-2017.pdf', NULL, NULL, 156, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Rangelands are complex and diverse, but with practical field training, it is possible to consistently evaluate the condition or health of a range site. This workbook describes a visual methodology that allows users to readily see changes in range health and to provide some early warning when management changes are needed. Range health assessment is intended to help users "tune" their eyes to some key indicators of range health.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c208b632-39bd-4ed1-b087-106a8a3de2bb', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Regional heterogeneity and unexpectedly high abundance of Cooperia punctata in beef cattle at a northern latitude revealed by ITS-2 rDNA nemabiome metabarcoding', 'De Seram EL, Redman EM, Wills FK, de Queiroz C, Campbell JR, Waldner CL, Parker SE, Avramenko RW', 2022, 'Parasites & vectors', '10.1186/s13071-021-05137-y', 'https://doi.org/10.1186/s13071-021-05137-y', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC8734358.1/PMC8734358.1.pdf', NULL, NULL, 11, NULL, 'alberta', 4, 'cc by', 'BackgroundThe species composition of cattle gastrointestinal nematode (GIN) communities can vary greatly between regions. Despite this, there is remarkably little large-scale surveillance data for cattle GIN species which is due, at least in part, to a lack of scalable diagnostic tools. This lack of regional GIN species-level data represents a major knowledge gap for evidence-based parasite management and assessing the status and impact of factors such as climate change and anthelmintic drug resistance.MethodsThis paper presents a large-scale survey of GIN in beef herds across western Canada using ITS-2 rDNA nemabiome metabarcoding. Individual fecal samples were collected from 6 to 20 randomly selected heifers (n = 1665) from each of 85 herds between September 2016 and February 2017 and 10-25 first season calves (n = 824) from each of 42 herds between November 2016 and February 2017.ResultsGastrointestinal nematode communities in heifers and calves were similar in Alberta and Saskatchewan, with Ostertagia ostertagi and Cooperia oncophora being the predominant GIN species in all herds consistent with previous studies. However, in Manitoba, Cooperia punctata was the predominant species overall and the most abundant GIN species in calves from 4/8 beef herds.ConclusionsThis study revealed a marked regional heterogeneity of GIN species in grazing beef herds in western Canada. The predominance of C. punctata in Manitoba is unexpected, as although this parasite is often the predominant cattle GIN species in more southerly latitudes, it is generally only a minor component of cattle GIN communities in northern temperate regions. We hypothesize that the unexpected predominance of C. punctata at such a northerly latitude represents a range expansion, likely associated with changes in climate, anthelmintic use, management, and/or animal movement. Whatever the cause, these results are of practical concern since C. punctata is more pathogenic than C. oncophora, the Cooperia species that typically predominates in cooler temperate regions. Finally, this study illustrates the value of ITS-2 rDNA nemabiome metabarcoding as a surveillance tool for ruminant GIN parasites.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eafbb0a4-4945-4236-8750-558ae71dbc6e', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Remote pasture water systems for livestock', 'Government of Alberta', 2007, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4043288', 'https://open.alberta.ca/dataset/dd0b36c0-41ea-4187-981a-dc2880c30560/resource/0c811978-86b8-48d6-8560-b22ef0eeee7b/download/2007-400-716-c30.pdf', NULL, NULL, 20, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'No matter the size of a livestock watering system, proper planning and design play an important role in its effectiveness. Good installation cannot compensate for an inadequate water source. Good quality water and sufficient quantity are both vital to livestock. Dugout and off-stream livestock watering systems are an important tool in protecting water sources, riparian areas and livestock.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f2835df7-61f0-4472-8895-f3fe38764e8b', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Review: The composition and availability of straw and chaff from small grain cereals for beef cattle in western Canada', 'Duane H. McCartney, Hushton C. Block, P. L. Dubeski, A. Ohama', 2006, 'Canadian Journal of Animal Science', '10.4141/a05-092', 'https://doi.org/10.4141/a05-092', 'https://cdnsciencepub.com/doi/pdf/10.4141/A05-092', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d32409e-9d52-4a0e-b197-bca5531e3fe5', '96fe7066-ae23-4d8a-b6d9-37a45e3ca699', 'Nutritive value of maize silage in relation to dairy cow performance and milk quality', 'Nazir Ahmad Khan, Peiqiang Yu, Mubarak Ali, J.W. Cone, Wouter Hendrikus Hendriks', 2014, 'Journal of the Science of Food and Agriculture', '10.1002/jsfa.6703', 'https://doi.org/10.1002/jsfa.6703', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/jsfa.6703', NULL, NULL, 16, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.86438+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3df3e47f-afef-4173-8d41-a5f49a8fbf8c', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Stewardship assessment : rangeland audit process', 'Government of Alberta', 2019, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/stewardship-assessment-rangeland-audit-process', 'https://open.alberta.ca/dataset/37af8cc5-6818-4a8f-b211-46048988f852/resource/0ee1bc32-34d1-4b15-85b0-a2b7d75c5b76/download/aep-stewardship-assessment.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Government requires grazing disposition holders to employ appropriate range management principles and practices to ensure a healthy, functional rangeland ecosystem is maintained on public lands for present and future generations. To this end, a stewardship assessment is required for each grazing disposition, with stewardship defined as the degree to which the grazing disposition holder is aware of and understands the four principles of range management and applies them to the stewardship of their grazing disposition.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('81d19ab4-f283-4ce6-ac43-47eca42badf1', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Stewardship for rangeland sustainability', 'Government of Alberta', 2022, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/stewardship-for-rangeland-sustainability', 'https://open.alberta.ca/dataset/bbda1ee7-3ffc-442a-8438-e4089e7ce49c/resource/4eb4e525-c85c-4854-bea9-74a492868965/download/aep-stewardship-for-rangeland-sustainability-2021-12.pdf', NULL, NULL, 16, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document describes the basic principles of rangeland management that when applied enhance rangeland stewardship. It describes how rangeland stewardship is key to sustaining native rangelands. This document compliments the Operating Standards for Alberta''s Public Land Grazing Dispositions and supersedes the 2007 Grazing Lease Stewardship Code of Practice.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f986d40a-531a-410b-a96c-d39382b9fd28', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Stock Return Form and Recreational Access Form User Guide for Grazing Associations', 'Government of Alberta', 2018, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/stock-return-form-user-guide-for-grazing-associations', 'https://open.alberta.ca/dataset/66f7df3d-7e3c-48ba-9c7f-54dbecc01727/resource/3a5d83d3-2bd4-41bd-8198-c045c95cc1fb/download/stock-return-form-and-recreational-access-form-user-guide-for-grazing-associations.pdf', NULL, NULL, 33, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This user guide is to assist grazing disposition holders in completing their online stock return forms and recreational access contact and conditions form. This guide is for grazing associations and grazing cooperatives.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d1b0907c-777e-4084-ae3e-6c8215963e24', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'The Canadian Cow-Calf Surveillance Network - productivity and health summary 2018 to 2022', 'Waldner C, Windeyer MC, Rousseau M, Campbell J', 2024, 'Frontiers in veterinary science', '10.3389/fvets.2024.1392166', 'https://doi.org/10.3389/fvets.2024.1392166', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11040676.1/PMC11040676.1.pdf', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Cow-calf surveillance data provide critical information about changing herd demographics, productivity, health, and management as well as the opportunity to investigate the impact of differing management practices. A national cow-calf network was established to collect baseline information on herd health, production performance measures, and management. Questionnaires were used to collect information on herd attributes as well as data for the calving season, breeding, pregnancy testing, and weaning for herds from across Canada. From 2018 to 2022, a total of 565 calving record questionnaires, representing 110,658 calving female records from 171 herds were returned, along with 543 herd breeding to weaning questionnaires. Suggested benchmark values based on the 25th percentiles from Western and Eastern Canada were determined to be p p p p < 0.001). Timing of calving season and use of large pastures for calving were not associated with mortality at birth. Herds that started calving before April were more likely to have calves die before 30 d than those that started calving later; however, this difference was not observed between 30 d and weaning. Herds that started to calve earlier were also more likely to report treating more calves for bovine respiratory disease, diarrhea, and navel or joint infections as well as to calf deaths from respiratory disease. Calves from herds in the east were more likely to be treated or die from diarrhea than from the west. Females from herds that started calving later were less likely to be pregnant. The unique longitudinal productivity and health data resulting from this network established a national baseline to address region-specific needs for knowledge translation and solutions to enhance productivity and support sustainability.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9daa4787-d84b-4bfd-9e35-e2ec59ed4303', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'The effects of spring versus summer calving on beef cattle economic performance in western Canada', 'Mohammad Khakbazan, Obioha N Durunna, Tanis K. Sirski, Derek Gerald Brewin, John Huang, Nathan J. Berry, A. D. Iwaasa, Shannon L. Scott', 2015, 'Canadian Journal of Animal Science', '10.4141/cjas-2015-046', 'https://doi.org/10.4141/cjas-2015-046', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas-2015-046', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9546c0d7-20b7-4c68-9168-f1ccb176be0e', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Vaccine use in Canadian cow-calf herds and opportunities for improvement', 'Lazurko MM, Erickson NEN, Campbell JR, Gow S, Waldner CL', 2023, 'Frontiers in veterinary science', '10.3389/fvets.2023.1235942', 'https://doi.org/10.3389/fvets.2023.1235942', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10445165.1/PMC10445165.1.pdf', NULL, NULL, 17, NULL, 'prairies', 4, 'cc by', 'Vaccinations are one of the most impactful tools available to cow-calf producers to control within herd disease and later, in feedlots. While vaccine use has been studied across Canada, inconsistent and variable regional data makes analysis and interpretation difficult. The objective of this study was to describe vaccination protocols and factors associated with vaccine use in Canadian cow-calf herds and define associations between vaccine use and productivity outcomes. Surveys describing vaccine use in 2020 were collected from 131 cow-calf herds (40 eastern, 91 western), recruited through a national beef cattle surveillance program. Ninety-two percent of cows and replacement heifers, and 72% of bulls were vaccinated with Infectious Bovine Rhinotracheitis (IBR), Bovine Viral Diarrhea Virus (BVDV), Parainfluenza3 Virus (PI3), and Bovine Respiratory Syncytial Virus (BRSV). At least half of cows and bulls were vaccinated for clostridial pathogens and cows and heifers for viral calf scours. Clostridial vaccines were significantly more likely to be used in western Canada compared to eastern Canada. While 92% of producers vaccinated suckling calves against IBR/BRSV/PI3, only 47% provided a second vaccine prior to weaning; 78% of calves were also vaccinated at least once for BVDV before weaning. Producers who vaccinated calves against IBR/BRSV/PI3 before 3 months of age provided a second dose prior to weaning more often than producers who administer the first IBR/BRSV/PI3 vaccine later. Vaccine use has increased across Canada, particularly in calves, prior to weaning. Relative to label recommendations for annual vaccination, clostridial vaccines were generally underutilized in cows and bulls, and by producers in eastern Canada as compared to western Canada. Opportunities also exist to improve adherence to label recommendations for the booster dose of scours vaccine when used in bred replacement heifers. Protocols including product choices, the timing and boosting of respiratory vaccines in nursing calves vary widely across herds. Use of intranasal vaccines in neonatal calves less than 2 weeks old has increased in western Canada compared to previous reports. There is a need to better understand how timing of vaccination in nursing calves contributes to effectiveness, for respiratory disease in nursing and weaned calves.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6165a3b7-3560-4299-a390-6874db415a3f', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Where’s the risk? Landscape epidemiology of gastrointestinal parasitism in Alberta beef cattle', 'Melissa A. Beck, Douglas D. Colwell, Cameron P. Goater, Stefan W. Kienzle', 2015, 'Parasites & Vectors', '10.1186/s13071-015-1040-x', 'https://doi.org/10.1186/s13071-015-1040-x', 'https://parasitesandvectors.biomedcentral.com/counter/pdf/10.1186/s13071-015-1040-x', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by', 'BACKGROUND: Gastrointenstinal nematodes (GIN) present a serious challenge to the health and productivity of grazing stock around the globe. However, the epidemiology of GIN transmission remains poorly understood in northern climates. Combining use of serological diagnostics, GIS mapping technology, and geospatial statistics, we evaluated ecological covariates of spatial and temporal variability in GIN transmission among bovine calves pastured in Alberta, Canada. METHODS: Sera were collected from 1000 beef calves across Alberta, Canada over three consecutive years (2008-2010) and analyzed for presence of anti-GIN antibodies using the SVANOVIR Ostertagia osteragi-Ab ELISA kit. Using a GIS and Bayesian multivariate spatial statistics, we evaluated the degree to which variation in specific environmental covariates (e.g. moisture, humidity, temperature) was associated with variation in spatial and temporal heterogeneity in exposure to GIN (Nematodirus and other trichostrongyles, primarily Ostertagia and Cooperia). RESULTS: Variation in growing degree days above a base temperature of 5 °C, humidity, air temperature, and accumulated precipitation were found to be significant predictors of broad-scale spatial and temporal variation in serum antibody concentrations. Risk model projections identified that while transmission in cattle from southeastern and northwestern Alberta was relatively low in all years, rate of GIN transmission was generally higher in the central region of Alberta. CONCLUSIONS: The spatial variability in risk is attributed to higher average humidity, precipitation and moderate temperatures in the central region of Alberta in comparison with the hot, dry southeastern corner of the province and the cool, dry northwestern corner. Although more targeted sampling is needed to improve model accuracy, our projections represent an important step towards tying treatment recommendations to actual risk of infection.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f1621a11-0877-47e1-9916-885742a5b063', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Creep Feeding Calves (Agdex 400/50-4)', 'Alberta Agriculture, Food and Rural Development', 1998, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/bebedfee-1cea-4bc2-90d6-1a3ef893ffda', 'https://open.alberta.ca/dataset/bebedfee-1cea-4bc2-90d6-1a3ef893ffda/resource/7ce891f7-99bd-4853-a322-99d5ef95e4d0/download/1998-400-50-4.pdf', NULL, NULL, 5, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'Alberta''s creep feeding sheet: when it pays, what to feed and how to build and site a creep so calves can use it and cows cannot. Relevant because the 2025 NFACC Scientific Committee concludes that creep feeding and other pre-weaning supplementation buffer weaning stress - which makes the creep pen a layout element the designer should support.', '{extension,weaning}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c1b08995-827e-4652-b83e-528b88654951', 'f1ac7c7c-83be-4f1d-bdf0-c6237e652d41', 'Whitecourt - Edson regional grazing plan', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4138273', 'https://open.alberta.ca/dataset/4cf21370-170a-4e71-b401-e0ec984e77f3/resource/fdbc3236-8c84-45a8-a895-a7bcbf4f7acc/download/2007-regionalgrazingplanwhitecourtedson-2007.pdf', NULL, NULL, 139, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A team of government agrologists, foresters and biologists, with the cooperation and support of the grazing and timber industries in the area, have developed a regional grazing plan for the Whitecourt-Edson area of west central Alberta. The boundary of the planning area was determined by the planning team and endorsed by the timber and grazing industries through the Regional Grazing Timber Advisory Committee. The plan boundary recognizes the existing demand for new grazing opportunities and the potential for future demand, and it includes all public land contained within the planning area.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a82061cf-1a6c-4b34-91e4-47b46eb8043f', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'A sorting corral system for livestock production or research.', 'Richard H. Hart', 1983, 'UA Campus Repository (The University of Arizona)', NULL, 'http://hdl.handle.net/10150/638451', 'http://hdl.handle.net/10150/638451', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('053f2b24-d451-4934-930a-92a0da7aede3', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Animal Health, Welfare and Antimicrobial Resistance: Canadian beef research strategy summary', 'Beef Cattle Research Council', 2026, 'Beef Cattle Research Council (beefresearch.ca)', NULL, 'https://www.beefresearch.ca/categories/animal-health-welfare-antimicrobial-resistance/', 'https://www.beefresearch.ca/wp-content/uploads/2026/07/animal-health-antimicrobial-resistance-strategy-summary.pdf', NULL, NULL, 3, NULL, 'canada', 3, 'Publicly available; copyright Beef Cattle Research Council', 'The Beef Cattle Research Council''s current animal health, welfare and antimicrobial resistance research priorities under the Canadian Beef Research and Knowledge Mobilization Strategy - what the national check-off is funding, and therefore what the next round of Canadian handling and welfare evidence will be about. Note that almost all of BCRC''s practical handling, stockmanship, weaning and winter management material is published as web pages rather than PDFs, so this strategy summary is the only BCRC document that qualifies for a PDF-only library; the topic pages worth reading alongside it are beefresearch.ca/topics/weaning, /preconditioning, /transport, /pain-mitigation and /winter-management-of-beef-cattle.', '{extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('601e4ab0-838b-4e42-af91-6fc7d9b30b4e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Acclimation During the 7-Day CO-Synch + CIDR Protocol Improves Temperament and Pregnancy Rate to Timed Artificial Insemination in Bos taurus Beef Heifers', 'Flax S, Ellinghuysen DM, Schwartz AG, Lemmon J, Silva JVC, Hurtado SP, Machado AF, Gomez-Leon VE', 2026, 'Animals : an open access journal from MDPI', '10.3390/ani16131953', 'https://doi.org/10.3390/ani16131953', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13360252.1/PMC13360252.1.pdf', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Temperament has been associated with reproductive success in beef cattle, with excitable animals often exhibiting reduced fertility. This study evaluated whether acclimating heifers to human handling during an ovulation synchronization protocol improves temperament and pregnancy rates to timed artificial insemination (TAI). A total of 622 Bos taurus yearling beef heifers across five locations and two breeding seasons (eight herd-year observations) were stratified according to reproductive maturity and temperament and were assigned to either acclimation (TRT; n = 307) or control (CTRL; n = 315). Acclimated heifers were moved through handling facilities without restraint prior to each protocol event (days 0, 7, and 10). Temperament was assessed using chute score (CS) and exit velocity (EV), and plasma cortisol was measured in a subset of animals. Acclimated heifers had lower CS on days 7 and 10 (p = 0.011 and p = 0.010, respectively) and greater pregnancy rates to TAI compared with control heifers (54.5% vs. 45.2%; p = 0.018). Exit velocity and cortisol concentrations did not differ between treatments (p ≥ 0.13). These results indicate that acclimation during handling events can improve behavioral responses and pregnancy rates to TAI with modest additional handling time (a mean of 17 s per heifer; no more than 18 min per location/day), providing a practical and scalable strategy for beef producers.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a0c5b5ad-fd9b-46eb-9666-db6bfc79cb9e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Alberta Elk and Deer Farming Industry Guidelines for Harvest Preserves', 'Alberta Agriculture and Irrigation', 2026, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/b552b14d-6114-42b2-9c7b-b48e29796665', 'https://open.alberta.ca/dataset/b552b14d-6114-42b2-9c7b-b48e29796665/resource/8e0bc751-af97-4150-80e2-5df6f9c08e32/download/agi-alberta-elk-deer-farming-industry-guidelines-harvest-preserves-2026.pdf', NULL, NULL, 2, NULL, 'alberta', 1, 'Open Government Licence - Alberta', 'Companion guidelines to the Alberta diversified livestock fencing and handling facility standards, covering harvest preserve licensing. Included only because it is the administrative other half of the one Alberta facility rule that has statutory force.', '{standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('11f24ad7-f778-434c-822a-ee689e871609', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Analysis of the Characteristics of Traditional Rural Constructions for Animal Corrals in the Adriatic-Ionian Area', 'Cosimo Alessandro Picuno, Ivan Laković, Demetrios Roubis, Pietro Picuno, Aleksandra Kapetanović', 2017, 'Sustainability', '10.3390/su9081441', 'https://doi.org/10.3390/su9081441', 'https://www.mdpi.com/2071-1050/9/8/1441/pdf?version=1502803954', NULL, NULL, 15, NULL, 'other', 1, 'cc-by', 'The purpose of the present study is a comparative analysis of the characteristics of traditional rural constructions constituted by temporary settlements for animal corrals, employed for vertical transhumance or nomadic pastoralism, spread over the mountain regions of three different Countries of the Adriatic-Ionian area, i.e., Greece, Italy and Montenegro. The main methods applied in this research were the detection and typological survey of some examples of these rural constructions located in Southern Italy, whose typical dimensions, building material and constructive technologies were detected and analysed. Major findings of the research have been the identification of some similarities connecting architecture and building material of these constructions, which revealed common technologies applied by people from different countries that, despite different socio-economical and cultural traditions, have employed similar techniques, implementing simple but very effective constructive building principles. Main conclusions are connected to the possible restoration of these constructions that, designed over the centuries in order to fulfil their primary agricultural role, now constitute a widespread cultural heritage with a significant architectural value, influencing the agricultural environment and the visual perception of its landscape that, within the current re-discover of the agricultural heritage, may play a central role, even though new activities related to rural tourism.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1be5b154-6f90-4a2d-ba8b-6a71189aa497', '96fe7066-ae23-4d8a-b6d9-37a45e3ca699', 'Post-flowering forage potential of spring and winter cereal mixtures', 'Vern S. Baron, A. C. Dick, H. G. Najda, D. F. Salmon', 1992, 'Canadian Journal of Plant Science', '10.4141/cjps92-014', 'https://doi.org/10.4141/cjps92-014', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps92-014', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.86438+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e9ee21b-0d82-479d-bf66-c3326c40373a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Animal Welfare and Handling (Alberta Agriculture and Irrigation)', 'Alberta Agriculture and Irrigation', 2023, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/30a239fe-ff23-418e-ae93-0d82a302cbc2', 'https://open.alberta.ca/dataset/30a239fe-ff23-418e-ae93-0d82a302cbc2/resource/e755c140-784f-4458-a0ba-24e1d69fe64d/download/agi-animal-handling-welfare.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence - Alberta', 'The current provincial statement on animal welfare and handling: how Alberta''s Animal Protection Act works, the role of the NFACC Codes of Practice as the reference for generally accepted practice, and who enforces what. This is the document that explains why a voluntary national Code has practical legal weight in Alberta.', '{extension,code-of-practice,standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd692cff-9393-48b0-b1f0-03f694817e83', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Applying a dryland degradation framework for rangelands: the case of Mongolia', 'Chantsallkham Jamsranjav, Robin S. Reid, María E. Fernández‐Giménez, Altanzul Tsevlee, Baasandorj Yadamsuren, Michael Heiner', 2018, 'Ecological Applications', '10.1002/eap.1684', 'https://doi.org/10.1002/eap.1684', 'https://esajournals.onlinelibrary.wiley.com/doi/pdfdirect/10.1002/eap.1684', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Livestock-caused rangeland degradation remains a major policy concern globally and the subject of widespread scientific study. This concern persists in part because it is difficult to isolate the effects of livestock from climate and other factors that influence ecosystem conditions. Further, degradation studies seldom use multiple plant and soil indicators linked to a clear definition of and ecologically grounded framework for degradation assessment that distinguishes different levels of degradation. Here, we integrate two globally applicable rangeland degradation frameworks and apply them to a broad-scale empirical data set for the country of Mongolia. We compare our assessment results with two other recent national rangeland degradation assessments in Mongolia to gauge consistency of findings across assessments and evaluate the utility of our framework. We measured livestock-use impacts across Mongolia''s major ecological zones: mountain and forest steppe, eastern steppe, steppe, and desert steppe. At 143 sites in 36 counties, we measured livestock-use and degradation indicators at increasing distances from livestock corrals in winter-grazed pastures. At each site, we measured multiple indicators linked to our degradation framework, including plant cover, standing biomass, palatability, species richness, forage quality, vegetation gaps, and soil surface characteristics. Livestock use had no effect on soils, plant species richness, or standing crop biomass in any ecological zone, but subtly affected plant cover and palatable plant abundance. Livestock effects were strongest in the steppe zone, moderate in the desert steppe, and limited in the mountain/forest and eastern steppes. Our results aligned closely with those of two other recent country-wide assessments, suggesting that our framework may have widespread application. All three assessments found that very severe and irreversible degradation is rare in Mongolia (1-18% of land area), with most rangelands slightly (33-53%) or moderately (25-40%) degraded. We conclude that very severe livestock-induced rangeland degradation is overstated in Mongolia. However, targeted rangeland restoration coupled with monitoring, adaptive management and stronger rangeland governance are needed to prevent further degradation where heavy grazing could cause irreversible change. Given the broad applicability of our degradation framework for Mongolia, we suggest it be tested for application in other temperate grasslands throughout Central Asia and North America.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('98784022-c36e-4c34-aaa7-7b3474b23b90', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Assessing the use of a mechanical rump pusher in a commercial cattle slaughter plant', 'Eleanor E. Wigham, Megan French', 2025, 'Animal Welfare', '10.1017/awf.2025.10011', 'https://doi.org/10.1017/awf.2025.10011', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/2503389EDE9C0ED37586F0ED0E655DC8/S0962728625100110a.pdf/div-class-title-assessing-the-use-of-a-mechanical-rump-pusher-in-a-commercial-cattle-slaughter-plant-div.pdf', NULL, NULL, 10, NULL, 'other', 1, 'cc-by', 'Commercial cattle slaughter operations have shown an increasing trend towards automation, with the aim being to improve animal welfare, product quality and efficiency. Several cattle slaughter plants have introduced mechanical rump pushers (RP) prior to the entrance of the stun box to reduce human-animal interaction and facilitate a smoother transition from the raceway to stun box. Presently, there are no data regarding the use of RPs in commercial slaughter environments operating at 40 cattle per hour. Therefore, this study observed normal operations at a UK slaughter plant, which has an RP installed, and assessed the level of coercion required to enter the RP, the use of the RP, cattle behaviour inside the RP and carcase bruising. The RP was used on 267 of the 815 cattle observed (32.8%) and was more likely to be used on dairy cattle and those who received a higher coercion score when entering the RP. Overall, 60 cattle (7.4%) required the highest coercion score and four (0.49%) required the use of the electric goad. Inside the RP, eleven animals slipped (1.8%) and ten vocalised (1.6%) although no incidences were directly associated with RP use. However, increased time restrained in the RP was significantly associated with more gate slams into the RP entrance gate. The use of the RP was not significantly associated with carcase bruising. These results are encouraging, and although it cannot be concluded that the presence of an RP improves cattle welfare at slaughter, use of automation within cattle slaughter facilities warrants further investigation.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4a055ae-a3d8-4f89-b5ad-678e1876a479', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Assessment of Veterinary Antimicrobial Residues in Feedlot Soils in Argentina', 'Sánchez Bruni S, Galotta L, de Yaniz MG, Schofs L, Sparo M, Cantón L, Moreno L, Davies P', 2026, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics15090862', 'https://doi.org/10.3390/antibiotics15090862', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13603946.1/PMC13603946.1.pdf', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Background/Objectives: This prospective cross-sectional study quantified veterinary antimicrobial residues in soils from 27 commercial beef feedlots across multiple regions of Argentina and production scales. Methods: Using a validated Ultra-Fast Liquid Chromatography-tandem mass spectrometry (UFLC-MS/MS) method, we measured 15 target antimicrobials in pooled corral soil samples. Results: Monensin was detected in all feedlots and showed the highest detection frequency and widest concentration range; peak concentrations exceeded 15,000 ppb in some sites. Oxytetracycline presented pronounced, site-specific peaks (approaching 14,000 ppb), consistent with its strong adsorption to soil organic matter and limited biodegradation. These results indicate localised hotspots of antimicrobial loading in feedlot environments. These elevated concentrations signify substantial antimicrobial loading in confined animal environments and potential hotspots for environmental selection pressure. Compounds absent from farm treatment records were detected in 40.7% of feedlots, correlating with antimicrobial residues not matching available AMU records, including oxytetracycline, tulathromycin, cefquinome, enrofloxacin, and ciprofloxacin among others. Multiple non-exclusive explanations are plausible (historical persistence, manure redistribution, incomplete records, off-label use, or cross-contamination). The detection of critically important antimicrobials (e.g., fluoroquinolones and advanced cephalosporins) in soils raises One Health concerns about environmental selection pressure and the potential dissemination of resistance determinants. Conclusions: These findings underscore gaps in stewardship and the need for integrated environmental monitoring and improved antimicrobial usage traceability. These data provide a baseline for ecological risk assessment and resistome studies and can inform evidence-based policy and stewardship interventions in Argentine feedlot systems.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a9806878-6706-447c-aa49-2443a7128137', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Association between handling stress in the corral and rabies antibody titers in selenium-supplemented cattle', 'LSLS Reis, S. B. Chiacchio, Eunice Oba, PE Pardo, N. M. Frazatti‐Gallina', 2009, 'The Journal of venomous animals and toxins including tropical diseases', '10.1590/s1678-91992009000400015', 'https://doi.org/10.1590/s1678-91992009000400015', 'https://www.scielo.br/j/jvatitd/a/9jbHyrMx9yfdt9XCnqgDsdq/?lang=en&format=pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc-by-nc', 'This study determined the correlation between serum cortisol levels and rabies antibody titers in cattle primo-vaccinated against rabies and supplemented with dietary selenium (Se). Sixty Nelore male calves (10 to 12 months old) received daily and individual dietary supplementation with 0, 3.6, 5.4 and 6.4 mg Se (groups Gc, G3.6, G5.4 and G6.4, respectively). The animals were vaccinated against rabies (day 0) and subjected to handling stress in the corral for 120 days. Blood sampling procedures were performed on days 0, 15, 30, 60, 90 and 120. Cortisol levels increased until day 90, but had dropped significantly by day 120 (P < 0.01). Rabies antibody titers on days 30 and 90 were similar among Se-supplemented groups; in the control group, rabies antibodies decreased significantly from day 30 to 60, and 90 to 120. Serum cortisol levels and antibody titers were not correlated in most of the groups or blood sampling days. A positive correlation among these variables was found only in G6.4 on days 60 (R = 0.513; P = 0.05) and 120 (R = 0.644; P = 0.009). In conclusion, repeated handling in the corral stresses cattle, but without compromising rabies humoral immune response.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('16cb574f-fce0-4332-b8d7-134129334d42', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Barriers to the adoption of safe beef cattle handling practices, equipment, and facilities in Iowa', 'DeAnn Scott‐Harp, Corinne L. Peek-Asa, Brandi Janssen, Diane Schertler Rohlman', 2018, NULL, '10.17077/etd.uoo784cq', 'https://doi.org/10.17077/etd.uoo784cq', 'https://iro.uiowa.edu/view/delivery/01IOWA_INST/12730550690002771/13730799690002771', NULL, NULL, 151, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('64f8daa4-3378-4a01-8975-25d6fe8a047d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Beef Cattle At a Glance: top-of-mind survey results for the Code of Practice update', 'National Farm Animal Care Council', 2024, 'NFACC', NULL, 'https://www.nfacc.ca/codes-of-practice/beef-cattle', 'https://www.nfacc.ca/pdfs/reports/Beef%20Cattle%20At%20a%20Glance.pdf', NULL, NULL, 8, NULL, 'canada', 3, 'Publicly available; copyright NFACC', 'The preliminary stakeholder survey results that set the priority topics for the 2023 to 2027 beef Code revision. Shows what producers, veterinarians, processors and the public currently consider the pressing welfare issues in Canadian beef production, and therefore what the next edition of the Code is most likely to tighten.', '{code-of-practice,standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('86491843-677b-40f3-a23f-bb88e22e7feb', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Beef cattle behavior, handling and facilities design', 'Temple Grandin', 1998, 'Digital Collections of Colorado (Colorado State University)', NULL, 'http://hdl.handle.net/10217/1551', 'http://hdl.handle.net/10217/1551', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5bf0d1c2-52e9-456d-9fa5-a7137fb0a66e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Beef Cattle Corrals and Handling Facilities (ID-13)', 'Roy Burris, Charles Absher, Sam McNeill and Larry Turner', 1986, 'University of Kentucky Cooperative Extension Service', NULL, 'https://publications.mgcafe.uky.edu/sites/publications.ca.uky.edu/files/id13.htm', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Free HTML from University of Kentucky; PDF no longer served', 'The cleanest surviving rendering of the Midwest Plan Service dimension table, and the version that credits MWPS as the source, which is why it is worth recording even though only the HTML survives. Holding area 14/17/20 sq ft and crowding pen 6/10/12 sq ft per head by weight class; working chute vertical 18/22/26 in, sloping 15/15/16 in bottom and 20/24/26 in top, 20 ft minimum length, fence 45/50/50 in, posts 30 in deep; add 2 in for exotic breeds; corral fence 60 in to 1200 lb and 60-66 in over, posts no more than 8 ft apart and at least 30 in deep; holding pen fence 5 ft British and at least 5.5 ft Brahman-cross and exotic; catwalk about 18 in above ground; circular crowding pen with a 12 ft swinging gate, a quarter-circle handling up to 8 mature cows; gates should swing in the direction of cattle movement and may need to swing up to 270 degrees; loading chute 26-30 in wide, 12 ft minimum, maximum slope 30 percent or 3.5 in rise per foot, stepped ramps with steps at least 18 in wide and risers no more than 4 in, cleats 1 by 3 hardwood nailed 6 in on centre. Also states that a curved chute, or one with at least a 15 degree bend, reduces backing up - while giving no radius. Note its working-chute fence height for over 1200 lb is 50 in where Oklahoma gives 60 in: a genuine discrepancy within one table lineage.', '{design,dimension-tables,mwps-lineage,loading-ramp,discrepancy,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d29b4831-857c-4908-a33f-dcd537ae6834', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Beef Cattle Facilities: Handling Systems', 'Penn State Extension', 2023, 'Penn State Extension', NULL, 'https://extension.psu.edu/beef-cattle-facilities-handling-systems', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Free Penn State Extension web article; HTML only', 'Recorded for one sentence that captures the real difference between the two crowding-pen options better than any dimension does: Bud Box systems ''rely more on the handler''s relationship with, and ability to read, the cattle'' while tub-style systems ''rely more on the cattle''s instincts to avoid humans''. This is the correct framing for a corral designer, because it means the choice is a function of who will be working the cattle rather than of geometry, and it aligns with the one engineering authority (MLA 2016) that flags the Bud Box''s handler-safety disadvantage - the handler must be inside the box with the cattle with no easy escape route.', '{design,bud-box,tub,handler-skill,comparison,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c0c7c850-99b2-4266-9683-4f39b1669803', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Behavioral Principles of Livestock Handling (with 1999 and 2002 updates on vision, hearing, and handling methods in cattle and pigs)', 'Temple Grandin', 1989, 'The Professional Animal Scientist, December 1989, pp. 1-11 (American Registry of Professional Animal Scientists)', NULL, 'https://www.grandin.com/references/new.corral.html', 'https://pdfs.semanticscholar.org/fd1a/e826249abf0d1a262bc795c820325371fddd.pdf', NULL, NULL, 22, NULL, 'other', 5, 'Author-hosted copy; Semantic Scholar open PDF', 'Grandin''s core design review with a full bibliography, which is what makes the numbers traceable. Curved race inner radius 3.5-5 m (12-16 ft); if bends smaller than 3.5 m are used there must be a 3 m (10 ft) straight single-file section at the crowd-pen junction; short 1.5 m bends are possible per Grandin 1984b. Round crowd pen radius 3.5 m cattle, 1.83 m pigs, 2.4 m sheep, attributed explicitly to ''practical experience''. Straight crowd pen: one fence straight, the other at 30 degrees, cited to the UK Meat and Livestock Commission. Maximum stationary ramp steepness 20 degrees for market-weight animals. Flight zone 2-8 m for feedlot cattle and up to 50 m for extensively raised cows. Crucially, attributes the ''circular crowd pen and curved race reduced time moving cattle by up to 50 percent'' claim to Vowles and Hollier 1982, a one-page Australian conference abstract, letting the reader see how thin the evidence base is.', '{design,curved-race,crowd-pen,flight-zone,funnel-angle,bibliography,primary-source}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f0bf299-7950-4841-bc7f-5047c8730061', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Behavioural Principles of Handling Beef Cattle and the Design of Corrals, Lairages, Races and Loading Ramps (in Livestock Handling and Transport, 6th edition)', 'Temple Grandin (chapter); Temple Grandin (ed.)', 2024, 'CAB International (CABI), Livestock Handling and Transport', '10.1079/9781800625136.0005', 'https://www.cabidigitallibrary.org/doi/10.1079/9781800625136.0005', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Paywalled book chapter (CABI)', 'The current, most recent consolidated statement of Grandin''s beef corral, race and loading ramp design rules, superseding the 1997 Livestock Production Science paper as the citation of record. This is the chapter the corral designer should cite as the authoritative modern source for the geometry, and it carries the Vowles and Hollier 1982 and Vowles et al. 1984 citations forward, including the related 1984 follow-up on cattle movement through single-file races. Paywalled, so the free Grandin 1997 full text at grandin.com and the open-access Grandin 2021 Frontiers paper are the practical substitutes - but the library should record this as the current edition so the ranch knows the 2024 version exists.', '{design,book-chapter,current-edition,corral-geometry,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3d3da522-beaa-4e34-a53d-632ac5a81e6b', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Bovine Behavior: Key to Handling Cattle', 'Stanley E. Curtis', 1996, 'American Association of Bovine Practitioners Conference Proceedings', NULL, 'https://bovine-ojs-tamu.tdl.org/AABP/article/view/6196', 'https://bovine-ojs-tamu.tdl.org/AABP/article/download/6196/6704', NULL, NULL, NULL, NULL, 'other', 3, 'Open access AABP Proceedings', 'An independent behavioural-science treatment of cattle handling, written by a Penn State animal environment scientist rather than by Grandin, which makes it a useful check on whether the behavioural premises underlying the design rules (flight zone, following behaviour, vision, response to novelty) are accepted outside Grandin''s own body of work. Covers bovine sensory capabilities and behavioural responses relevant to facility design.', '{design,behaviour,flight-zone,independent-source,veterinary}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('630ae6fc-4172-4ca2-b054-edf6567d8f5a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Bud Box Bonanza: A rancher''s simple handling layout cuts costs and decreases stress', 'Boyd Kidwell', 2011, 'Angus Journal, February 2011', NULL, 'http://www.angusjournal.com/', 'http://www.angusjournal.com/articlepdf/bud%20box%2002-11%20aj.pdf', NULL, NULL, 2, NULL, 'other', 3, 'Free Angus Journal article PDF', 'Trade-press account of a working Bud Box on a commercial Angus operation, included because this ranch runs Red Angus and because the published Bud Box literature is thin. Describes the layout, build cost and the operator''s experience of cattle flow and reduced stress. It is journalism, not evidence, and should be tagged as such in the library - but it is one of the few free accounts of a Bud Box in an Angus cow-calf setting rather than a feedlot.', '{design,bud-box,angus,trade-press,case-study}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a41b7348-fdd5-46e7-b1f8-bda37cdcd214', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Bud Box vs. Round Tub Systems', 'South Dakota State University Extension', 2024, 'SDSU Extension', NULL, 'https://extension.sdstate.edu/bud-box-vs-round-tub-systems', NULL, NULL, NULL, NULL, NULL, 'northern_plains', 3, 'Free SDSU Extension web article; HTML only', 'A recent northern-plains extension comparison, recorded because it is one of the few published side-by-side treatments and because it independently confirms the Bud Box size most often built: ''a rectangular pen (usually 12x20 or 14x20 ft.)''. Its comparison table scores cost (box lower), handler skill required (box higher), cattle flow (box more natural if done right, tub guided by structure) and space required (box smaller footprint, tub larger). IMPORTANT: there is NO controlled trial behind any of these comparisons. I searched for a Journal of Animal Science or Applied Animal Behaviour Science head-to-head study of Bud Box versus tub and found none. Every published comparison, including this one, is qualitative extension opinion, so the corral designer must not score one layout above the other.', '{design,bud-box,tub,comparison,no-controlled-trial,recent,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('295924a0-76c6-46e1-90b1-f0ddabfa1a85', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1352: Calf Range Shelter (open front)', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1352/1352L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1352/1352L.pdf', NULL, NULL, 2, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'The Canada Plan Service open-front calf range shelter - the buildable shelter a southern Alberta cow-calf operation puts in a calving or weaning pen to satisfy the Code of Practice section 1.1 requirement for relief from weather and section 1.3 requirement for a safe, clean calving environment. Part of the 1350 series alongside M-1351 (rigid frame) and 1353 (portable pipe frame calving shelter).', '{plan,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5e67a8a5-9575-473c-ab3c-f51899cab24c', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1811: Corral and Feedlot Fencing', 'Canada Plan Service', 1975, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1811/1811L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1811/1811L.pdf', NULL, NULL, 3, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The Canadian corral and feedlot fence plan, with gate and latch details. Specifies a 4-rail fence and gate for a 5 ft 0 in feedlot fence and a 5-rail fence and gate for a 6 ft 0 in corral fence; minimum 6 in top diameter wood posts; 2 by 6 in horizontals with 1 by 6 in both sides and 1 by 6 in spacer blocking both sides; 2 in blocking between upright and brace boards; a brace dimension of 3 ft 0 in for a 12 ft 0 in gate and 4 ft 0 in for a 16 ft 0 in gate; gate hardware of quarter by 2 in iron strap both sides with seven-sixteenths machine bolts through the gate members, a five-eighths galvanised bolt hook with two nuts and two washers, half inch pipe welded to the strap, keepers of half inch plywood both sides and a 2 by 6 in latch board; and gate posts of minimum 8 in top diameter by 14 ft 0 in pressure-treated wood set with concrete backfill. Referenced by CPS 1835 and 1819 as the fencing standard for the whole corral.', '{plan,extension,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9261473b-e355-46f5-9b2e-21e91fd8b368', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1812: Crowding Gate', 'Canada Plan Service', 1983, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1812/1812L.pdf', 'https://web.archive.org/web/2007id_/http://www.cps.gov.on.ca/english/plans/E1000/1812/1812L.pdf', NULL, NULL, 4, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The Canadian crowding gate plan (revised 83:12) - the 12 ft gate used in the crowding tub of plans 1831 and 1835. Pivot post is 3 and a half inch by 12 ft long pipe set in concrete backfill 4 ft deep, with the note that in soft soils the post hole diameter and concrete should be increased. The hinge is a 4 inch pipe by 3 inch long sleeve that rotates on the post and is greased as necessary, with a three-eighths by 3 by 1 ft 4 in hinge strap welded to the sleeve and bolted to the gate members; a 4 inch pipe by 3 inch collar is drilled with the post for a three-eighths bolt, and additional holes are drilled in the post for vertical adjustment - which is how the gate is raised to clear snow, ice and manure build-up. The gate itself is 1 by 6 in uprights, 2 by 6 in rails, 1 by 6 in cross bracing, three-eighths sheathing plywood with the face grain vertical so cattle cannot see through, 1 by 6 in spacer blocking, and a 2 by 6 in latch board with a U-bolt handle.', '{plan,extension,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0858cb54-e731-4697-83fd-81748b112070', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1813: Working Chute', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1813/1813L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1813/1813L.pdf', NULL, NULL, 4, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The Canadian single-file working chute plan, revised July 1984, showing a straight chute section and an alternate tapered section. States that the chute dimensions are recommended for feeder cattle up to 1000 lb and that heavier cattle and some exotic breeds may need a wider chute. Components: commercial pipe-frame headgate and cattle squeeze; an access gate to close across the chute; 5 in top diameter or 4 by 6 by 12 ft 0 in CCA pressure-treated sawn poles; a blocking gate per leaflet 1814; a catwalk of three 2 by 6 in on 2 by 6 in each side of the pole with a 2 by 6 by 2 ft 0 in brace to the pole; three 2 by 8 in bottom rails and three 2 by 6 in top rails; 2 by 6 in cross-ties and 8 in carriage bolts; an optional filler for handling young cattle of 2 by 6 in at 2 ft 0 in on centre with 4 ft 0 in high plywood suspended from the top rails; three-eighths inch exterior select sheathing plywood with the face grain vertical; an optional rough-textured concrete base on compacted granular fill; and temporary cross-bracing to the pole pairs while locating and tamping them into position.', '{plan,extension,handling,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('359ddeeb-f1f3-4052-bb9e-2ea34cd92c9a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Livestock Handling Facilities Designs', 'USDA Natural Resources Conservation Service', 2022, 'USDA Natural Resources Conservation Service', NULL, 'https://www.nrcs.usda.gov/', 'https://nrcs-prod.azureedge.us/sites/default/files/2022-12/Livestock-handling-Facilities-Designs.pdf', NULL, NULL, 18, NULL, 'other', 4, 'US Government work, public domain', 'The standalone NRCS handling-facility design sheet, same content family as the Illinois Grazing Manual fact sheet, carrying the full set of component specifications (conditioning, holding, sorting and crowding pens; working and loading chutes; headgates; hospital area) plus the dimensional rules: 15 ft minimum curve radius, 20 ft minimum chute, 12 ft to 2 ft funnel taper, under 3 percent site slope, 4 in gap under the chute sides, and sloped chute sides that restrict the animal''s feet to a narrow path and prevent turning around. Includes reference layouts with circular crowding pen and curved working chute.', '{design,curve-radius,funnel-taper,usda,layout-plans}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc32ad90-53b6-4c3e-9169-0b38c2e84d4e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'CRSB Certified Sustainable Beef Processing Standard, version 2.0', 'Canadian Roundtable for Sustainable Beef', 2025, 'CRSB', NULL, 'https://www.crsbcertified.ca/standards/the-standards', 'https://cdn.prod.website-files.com/6855a700a8f899e81d9cec7b/68cc69f62b71e863996292cf_Processing%20Standard_v2.0_FINAL.pdf', NULL, NULL, 30, NULL, 'canada', 2, 'Publicly available programme standard; copyright CRSB', 'The processing-side companion to the CRSB production standard. Included for completeness because it sets the receiving-end handling and unloading expectations that the ranch''s load-out has to satisfy at the other end of the trip.', '{standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1831e27a-c413-4bfe-9ce4-81beef58aff9', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1814: Blocking Gates', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1814/1814L.pdf', 'https://web.archive.org/web/2007id_/http://www.cps.gov.on.ca/english/plans/E1000/1814/1814L.pdf', NULL, NULL, 3, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The blocking gate plan (rev. 84:01) for controlling cattle moving through a working chute such as Plan 1813, used wherever cattle must be stopped or prevented from backing up. Two interchangeable designs are drawn: a plywood-covered gate running on rollers and an inclined sliding-door track, which is self-closing, and a plank gate running on greased pipe. Callouts include a gate stop with rubber bumpers, a 2 by 6 by 8 ft track board with slide-door track and roller hardware, a control rope through a pulley and screw eye on a spacer block tied with a loop and bowline knot, 2 by 6 in members, three-quarter inch plywood, a 4 by 6 by 12 ft CCA pressure-treated post, a 6 in diameter by 9 ft CCA post, 2 in galvanised pipe 7 ft 6 in long, 2 by 4 in stop blocks, three-eighths carriage bolts with nuts and washers, one-eighth by one and a half inch strap iron, and concrete backfill. Plan M-1800 notes the design choice: an open gate where the cattle at the gate should see ahead, a solid one where they must be shut off, as in an A.I. chute.', '{plan,extension,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1f6ada05-e35c-4dc2-b513-c31ef26fd69c', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1816: Stationary Adjustable Loading Chute', 'Canada Plan Service', 2006, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1816/1816L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1816/1816L.pdf', NULL, NULL, 2, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The newest Canada Plan Service loading chute plan (new May 2006). The chute is 2 ft 9 in wide and consists of a 12 ft ramp section with an adjustable extension at the upper end, in plank construction on a pressure-treated post framework, with cleats for traction and a catwalk along the ramp. Details: 6 by 6 in pressure-treated posts; 2 by 6 in sidewalls and cross-ties; catwalk of 2 by 6 in with 1 by 2 in hardwood cleats at 6 in on centre, 2 by 4 in struts and brace and half inch plywood; ramp floor of two 2 by 6 in stringers bolted to the posts with 2 in cross planking and 1 by 2 in hardwood cleats at 6 in on centre; an alternate ramp floor of compacted earth with gravel topping behind a treated plank retaining wall; an adjustable deck pivoting on the 6 by 6 in support posts on a one and a half inch diameter pipe pivot shaft; a one and a half inch pipe support with two and a quarter by 9 by 1 ft 8 in adjustment plates bolted to the posts and slotted like a gun rack; and an optional three-quarter by 2 ft 0 in by 2 ft 8 in plywood extension on heavy-duty tee hinges. The plan that satisfies the Code of Practice section 5.3 requirement for no unprotected gap between the ramp and the vehicle.', '{plan,extension,loading}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bac3bc9b-1dd7-4e0b-9011-3249026195fb', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1817: Adjustable (portable) Loading Chute', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1817/1817L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1817/1817L.pdf', NULL, NULL, 3, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The portable, skid-mounted adjustable loading chute, revised July 1984, with a full cut list. Six 4 by 4 in posts - two at 4 ft 10 and a half in, two at 6 ft 2 and a half in and two at 7 ft 6 in; ten 2 by 8 by 12 ft 0 in planks; two 2 by 4 by 3 ft 7 in slip guards nailed to cleats; sixteen 1 by 2 by 3 ft 2 in cleats; sixteen 2 by 8 by 3 ft 2 in ramp planks, giving a nominal 3 ft 2 in ramp width; two 4 by 4 by 4 ft 2 in hinged ramp supports on quarter by 4 by 3 ft 0 in strap hinges; a 4 by 4 by 7 ft 2 in ramp support; 4 by 4 by 11 ft 0 in skids with both ends bevelled 45 degrees; 3 by 3 by five-sixteenths angle-iron adjustable ramp brackets 1 ft 0 in long; a half inch diameter pipe 4 ft 0 in long with one and a half inch washers welded on as stops; a 2 by 4 by 3 ft 2 in adjustable ramp stop; cross braces; and thirty three-eighths by 6 in and twenty three-eighths by 9 in bolts. The design to reach for where the ranch wants a load-out that can be towed to a different pen.', '{plan,extension,loading}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0adf5f3a-7205-4e07-9d6e-8978c74dcdbe', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1818: Pregnancy Testing and A.I. Chute', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1818/1818L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1818/1818L.pdf', NULL, NULL, 3, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'The dark box pregnancy testing and artificial insemination chute (revised 84:04), designed for beef cow herds. Three cows are brought into position at once by closing the blocking gates and placing a cross rail behind each animal; after servicing the gates open and the rails are removed, giving an even flow of cattle. The cross rails fit at three different places behind the solid blocking gate to suit animal size, and only the solid gate from Plan 1814 should be used. Dimensions stated: working chute 28 in clear width with optional catwalk per leaflet 1813; blocking gate sliding on greased one and a half inch pipe or sliding barn-door hardware; a 13 inch man opening that lets a handler enter safely behind the cow; 2 by 4 in cleats and a 2 by 4 in cross rail; a plywood-covered area over the head, top and sides, with a canvas or burlap curtain hanging at the back of the top to keep cows calm. The catwalk must be built on the side opposite the man openings. Any number of man openings and cow positions can be built in. Plan M-1800 adds the warning never to use the A.I. chute for branding, dehorning or injections, or the animals will associate it with pain.', '{plan,extension,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f956f8cb-ffad-43b7-9723-c7388fac32da', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1819: Herringbone A.I. Breeding Chute', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1819/1819L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1819/1819L.pdf', NULL, NULL, 3, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'A herringbone artificial insemination breeding chute for larger beef herds or for synchronised estrus, based on University of California leaflet 21029 and designed so one person can handle the cows. Cows are gathered in a holding pen, crowded quietly into a curved chute and fill the farthest stalls first; a short chain behind each cow stops her backing out; stall fronts, tops and front sides are solid plywood with a burlap flap over the back to isolate her; a rope control releases each stall exit door and a spring opens it. Stall width is adjusted by changing the angle of the side gates, which pivot on their rear posts, and the number of stalls can be changed without affecting the design. Dimensions stated: holding pen 27 sq ft per head; 6 by 6 in by 8 ft pressure-treated posts set 4 ft 0 in deep; 2 ft 8 in man gate. References corral and feedlot fencing 1811, crowding gate 1812, working chute 1813, loading chute 1816 or 1817 and blocking gate 1814.', '{plan,extension,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec886d4a-534c-4a91-b40d-a46edf076f1a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Sheep Pen Improvements at City Farm SLO', 'Ryan S. Bodmer', 2026, 'DigitalCommons - CalPoly (California State Polytechnic University)', NULL, 'https://digitalcommons.calpoly.edu/cmsp/967', 'https://digitalcommons.calpoly.edu/cgi/viewcontent.cgi?article=2120&context=cmsp', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3bbf46e0-e18a-4dfd-8eb3-dc80eabb9f99', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1820: Loading System for Large Trucks', 'Canada Plan Service; D. Darby (designed and drawn)', 1999, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1820/1820L.pdf', 'https://web.archive.org/web/2007id_/http://www.cps.gov.on.ca:80/english/plans/E1000/1820/1820L.pdf', NULL, NULL, 2, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The newest sheet in the Canada Plan Service beef handling set (new June 1999, designed and drawn by D. Darby of Alberta Agriculture Engineering Services), and the one most relevant to a modern ranch shipping on a liner. A corral system for efficient and orderly loading of large cattle liners, which typically hold about 50 finished steers in compartments, so an efficient loading system pre-sorts batches of animals for each section of the load. Worked example of one load of fat cattle: 8 head in the front compartment, 14 for the belly section, 18 head to the upper deck and 10 to finish the rear. The sheet states that assembling those batches by pre-sorting in a pen ahead of the chute is less stressful and preferred over crowding and cutting as cattle go up the chute. The holding pen should hold a truck load, typically up to 55 finished animals; the crowding tub conveniently holds over a dozen head, and a second crowding gate at the start of the loading alley helps handle larger batches and sort. Numbered components: handling alley, cutting gate, 12 ft crowding gate, tub with catwalk, holding and sorting pen, loading alley, loading chute with off-set sight lines, a second holding pen to aid multiple loadings, and a rugged man gate. Pen dimensions on the drawing run 32 to 40 ft, 24 to 32 ft, 18 to 24 ft and 12 to 14 ft. Its basic loading-chute rules: have a rugged chute, offset the truck from the chute entrance so cattle turn a corner before they see the truck, provide good access for the truck driver, and use solid sides to reduce spooking.', '{plan,extension,loading,handling,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('02728df1-4bc9-4d0a-b18a-b15f4314753d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1821 (beef cattle handling series)', 'Canada Plan Service', 1999, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1821/1821L.pdf', 'https://web.archive.org/web/2007id_/http://www.cps.gov.on.ca:80/english/plans/E1000/1821/1821L.pdf', NULL, NULL, 1, NULL, 'canada', 3, 'Free distribution; Canada Plan Service co-operative', 'A further sheet in the Canada Plan Service 1800-series beef cattle handling set, archived alongside plan 1820 Loading System for Large Trucks. Downloaded and verified as a valid PDF, but the leaflet is image-only with no extractable text, so its title block and dimensions must be read off the drawing. Included because the set is more useful complete than partial.', '{plan,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c1e2da4-57bf-478c-a661-1bdc699feb9d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1831: Minimum Working Corral', 'Canada Plan Service', 1975, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1831/1831L.pdf', 'https://web.archive.org/web/2007id_/http://www.cps.gov.on.ca/english/plans/E1000/1831/1831L.pdf', NULL, NULL, 3, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The smallest complete Canada Plan Service corral, described as a minimum handling facility for the cattleman with a few head who handles cattle infrequently during a year, or for a separate pasture facility remote from the central facilities of a cow-calf operation - which makes it the right starting point for a satellite corral on a southern Alberta ranch. It consists of a holding pen, a crowding area and a small working chute, with a semi-circular crowding pen and crowding gate per leaflet 1812 that helps squeeze animals into the chute with minimum effort; the same crowding unit can move animals into a loading chute placed adjacent to the working chute. The leaflet is candid that this corral has a short working chute and that longer is preferred, and notes that as the herd or the operator''s needs increase the layout can be readily expanded. It may be equipped with a home-made pipeframe headgate or a commercial squeeze with attached headgate. Dimensions stated: 10 ft gate per leaflet 1811; posts 6 ft on centre; optional man gate the same width as the chute. Reproduced as Corral Layout 1 in Alberta''s Corrals for Handling Beef Cattle, where it is the cost baseline at about 1200 to 1400 dollars of materials in January 1993.', '{plan,extension,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('131b8aef-ef9f-4bf3-9630-7e43f79acf8d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1835 leaflet (French): Grand corral de manutention', 'Service de plans canadiens / Canada Plan Service', 1985, 'Agri-Reseau (Quebec)', NULL, 'https://www.agrireseau.net/', 'https://www.agrireseau.net/references/17/Service%20de%20plans/1000/1835L.pdf', NULL, NULL, 2, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'The French edition of Canada Plan Service plan 1835, Large Working Corral, hosted by Agri-Reseau in Quebec. A second working free host for the plan, useful because the English copy is only available through the Internet Archive. Same content: a corral for a 100-cow breeding herd with calves plus young cattle, a semicircular service alley of at least 10 ft inner radius that should be enlarged where space permits, a crowding pen of about 80 head, holding pens of about 70, 60 and 30 head, 12 ft gates, a 5 ft sorting gate, maximum 8 ft post spacing, an optional 8 ft scale section and a waterer where animals are held more than a day.', '{plan,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('12a82803-422c-438f-bcdd-743e5a47c968', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1835: Large Working Corral', 'Canada Plan Service', 1985, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1835/1835L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1835/1835L.pdf', NULL, NULL, 2, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The Canada Plan Service large working corral, revised July 1985 - a compact, practical corral that easily holds a breeding herd of 100 cows and their calves plus young cattle, built around a very popular semicircular working alley whose inner radius is at least 10 ft, with the explicit recommendation to increase that radius if space allows. Numbered components: cattle alley with access from feedlot or pasture; 12 ft 0 in gate with open corral fencing per leaflet 1811; 12 ft 0 in crowding gate with closed fencing per leaflet 1812; crowding pen of approximately 80 head; working chute with catwalk per leaflet 1813; optional scale, subtract 8 ft 0 in from the overall length if it is not used; blocking gate per leaflet 1814; loading chute per leaflet 1816; man gate; cattle squeeze with headgate; 5 ft 0 in sorting gate; holding pens of approximately 70, 60 and 30 head; a waterer if animals are held more than a day; post spacing of 8 ft 0 in maximum; an optional scale layout and bypass gates for the scale. The plan advises placing the scale near the service alley but not in line with it, to limit wear and maintenance. Reproduced as Corral Layout 9 in Alberta''s Corrals for Handling Beef Cattle, with a relative material cost index of 2.1 against the minimum working corral.', '{plan,extension,facilities,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('42b623e7-bb27-427d-9c40-07053ac4f86d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan 1836: Cattle Working Corral', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1836/1836L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1836/1836L.pdf', NULL, NULL, 2, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'The Canada Plan Service cattle working corral, sitting between the minimum corral 1831 and the large working corral 1835 in the series and listed next to 1835 in both the CPS index and the 2004 Saskatchewan catalogue. Note that this leaflet is image-only - there is no extractable text, so its dimensions have to be read off the drawing itself rather than from a callout list. Built to the same conventions as the rest of the 1800 series: fencing and gates per 1811, crowding gate per 1812, working chute per 1813, blocking gate per 1814 and loading chute per 1816 or 1817.', '{plan,extension,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('427b0c01-a6e0-452f-b182-9712e6bcfd32', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan index (all series)', 'Canada Plan Service; hosted by the Canadian Society for Bioengineering (CSBE/SCGAB)', 2008, 'Canada Plan Service / CSBE', NULL, 'https://www.csbe-scgab.ca/', 'https://www.csbe-scgab.ca/images/cps/Plan-Index-EN.pdf', NULL, NULL, 4, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'The master index of every Canada Plan Service plan and leaflet, hosted by CSBE now that the CPS website is gone. Lists the beef cattle handling set - M(I) 1800 Cattle Handling Facilities, 1811 Corral and Feedlot Fencing, 1812 Crowding Gate, 1813 Working Chute (with 1813a Option Two), 1814 Blocking Gates, 1816 Stationary Adjustable Loading Chute, 1817 Adjustable Loading Chute, 1818 Pregnancy Testing and A.I. Chute, 1819 Herringbone A.I. Breeding Chute, 1831 Minimum Working Corral, 1832 Small Working Corral, 1833 Cattle Handling Corral, 1834 Corral for Cow-Calf Operations, 1835 Large Working Corral and 1836 Cattle Working Corral - together with the 1000-series beef housing, feeder and calf shelter plans. M means metric, I imperial and M(I) both. Start here when hunting a specific plan number.', '{plan,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b0f58407-5859-4373-b50e-3543141ee470', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan M-1000: Beef Cattle Housing and Equipment', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1000/M-1000L.pdf', 'https://web.archive.org/web/2007id_/http://www.cps.gov.on.ca:80/english/plans/E1000/1000/M-1000L.pdf', NULL, NULL, 2, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The parent sheet for beef cattle pens, yards and housing, and the source of Alberta''s Table 70 housing guidelines (84:07). Opens with the principle that governs a prairie yard: cattle suffer more from mud, wet weather and cold winter winds than from low temperatures alone. Siting: build on a well-drained site, ideally a south-facing slope on well-drained soil, near an adequate water supply but away from streams and population centres, with natural tree shelter. Drainage: where existing slopes give less than 1 in 25, move fill to increase effective slope and build earth mounds; shape pens so drainage runs away from resting, feeding and watering areas; slope barn roofs away from pens or fit eave troughs; pave around feeders and waterers, and pave the whole pen where annual rainfall exceeds 500 mm. Shelter: porous windbreak fences at 20 per cent open give the best protection, and in heavy snow country a snow fence should be erected about 45 m upwind of the windbreak with space between for a snow trap; open-front sheds should have a roof sloping away from the opening and the opening should face south in most areas. Ventilation by eave and ridge openings, with hinged panels or retractable curtains if the building doubles as a summer sunshade. Feeding: feeders high enough that lot drainage runs away from the feeding area, with concrete aprons at least as wide as the scraper and tractor wheels sloped 1 in 10 away from the bunk, or a step 100 to 150 mm high and 300 to 400 mm wide next to the bunk where the apron slope is less; run bunks north-south to reduce frozen manure build-up. Runoff control: runoff from cattle lots and manure storage must not enter any watercourse, so diversion dykes or ditches keep clean runoff out of the lots and settling and retention basins hold lot runoff through spring thaw and heavy rain - the engineering form of the AOPA interceptor requirement. An imperial companion is archived at the same path as 1000L.pdf.', '{plan,extension,facilities,windbreak,housing}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3d19d7b6-ef75-4d66-9df5-bf2bbdf70f6d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan M-1800: Cattle Handling Facilities (planning guide)', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1800/M-1800L.pdf', 'https://web.archive.org/web/2008id_/http://www.cps.gov.on.ca/english/plans/E1000/1800/M-1800L.pdf', NULL, NULL, NULL, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The parent Canada Plan Service planning guide for cattle handling facilities, and the origin of the dimension set every Canadian source repeats. Alberta''s Table 69, Recommended dimensions for beef cattle corrals and handling facilities, is explicitly adapted from CPS M-1800: holding area 14, 17 and 20 sq ft per animal worked immediately and 45, 50 and 60 held overnight by weight class; vertical-sided working chute 18, 22 and 28 in wide with a desirable length of 24 ft; sloping-sided chute 22 in at the bottom and 32 in at 5 ft height; working chute and feedlot line fences 5 ft high on posts 3 ft deep; corral and bull pen fences 5 ft high on posts 4 ft deep; loading chute 30-32 in wide, 12 ft minimum, slope 1 to 4; ramp heights of 15, 28, 40, 48 and 100 in for a gooseneck trailer, pickup, van-type truck, tractor trailer and double deck; and a 12 ft access or collecting alley. Served free from the Internet Archive copy of the original CPS site; the live host rate-limits, so fetch with retries.', '{plan,extension,facilities,loading}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4f65be4e-90c2-4b89-bf7e-9c35cb590ff3', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canada Plan Service plan M-1800: Cattle Handling Facilities (planning guide)', 'Canada Plan Service', 1984, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/english/plans/E1000/1800/M-1800L.pdf', 'https://web.archive.org/web/20031207092435id_/http://www.cps.gov.on.ca:80/english/plans/E1000/1800/M-1800L.pdf', NULL, NULL, 6, NULL, 'canada', 5, 'Free distribution; Canada Plan Service co-operative', 'The parent Canada Plan Service planning guide for cattle handling facilities (revised 86-01), and the origin of the dimension set every Canadian source repeats - Alberta''s Table 69 is explicitly adapted from it. Its behaviour section is based on work by Dr Temple Grandin. TABLE 1, with the note that cow-calf operations use the over 540 kg (1200 lb) column: holding area 1.3, 1.6 and 1.9 sq m (14, 17, 20 sq ft) per animal worked immediately and 4.2, 4.6 and 5.6 sq m (45, 50, 60 sq ft) held overnight; working chute with vertical sides 450, 550 and 700 mm (18, 22, 28 in) wide with a desirable minimum length of 7.2 m (24 ft); working chute with sloping sides 550 mm (22 in) at the bottom and 800 mm (32 in) at 1.5 m (5 ft) height; working chute and feedlot line fences 1.5 m (5 ft) high on posts 1.0 m (3 ft) deep; corral and bull pen fences 1.8 m (6 ft) high on posts 1.2 m (4 ft) deep; loading chute 650 mm (26 in) wide under 270 kg and 750-800 mm (30-32 in) above, minimum 3.4 m (12 ft) long, rise to run 1 to 4; ramp heights of 375, 700, 1000, 1200 and 2500 mm (15, 28, 40, 48 and 100 in) for a gooseneck trailer, pickup, van-type truck, tractor trailer and double deck; access or collecting alley 3.6 m (12 ft). It is the tiebreaker where the Alberta reprints disagree - it confirms 6 ft corral fences on 4 ft posts (Alberta''s table mis-sets both rows as 5 ft) and a 48 in tractor trailer ramp (Alberta prints 248 in). The narrative adds rules the reprints drop: choose a well-drained site with a slope of about 1 in 50 away from the headgate and squeeze; merge concrete paving into unpaved areas rather than ending it in a step; stake out a full-scale layout before digging postholes; plan so cattle can reach the facility from every pen; single-file chute at least 6 m (20 ft), 9-15 m (30-50 ft) in larger facilities, 6-15 m (20-50 ft) overall; run one wall of the crowd pen straight into the funnel and do not make the funnel entrance symmetrical; make blocking and sorting gates inside the chute from spaced planks, not solid panels; keep illumination uniform, use solid rather than slotted sunshades, and face loading and squeeze chutes north or south to minimise shadows; extend a single-file chute 3-5 m (10-16 ft) outside a building and never put the building wall where the crowd pen meets the chute; keep dogs out of the crowd pen and chute; flight zone up to 90 m (300 ft) for range cattle and 1.5-8 m (5-26 ft) for feedlot cattle; posts 2.5 m (8 ft) long for feedlot fences and 3 m (10 ft) for corral fences at no more than 2.4 m (8 ft) spacing, four rails at 1.5 m and five rails at 1.8 m, with curved fences to stop cattle bunching in corners; collection alley about 3.6 m (12 ft); at least one holding pen sized for the herd, two better; crowding gate on a 3 in galvanised pipe pivot in concrete with adjustable height and multiple latch stops; catwalk about 1 m (3 ft) below the top of the chute fence, outside the chute on the inner curve, never overhead; loading chute curved with solid sides on a 3.6-5.1 m (12-17 ft) radius, the larger the better, 750-875 mm (30-35 in) single file, 650 mm (26 in) for calves only, 1350-1800 mm (54-72 in) double width, and a straight 1.8-3 m (6-10 ft) chute where it is used only for unloading; level landing about 1.5 m (5 ft); fixed ramp no more than 20 degrees and adjustable no more than 25; height adjustment 650-1125 mm (26-45 in); cleats 19 by 38 mm at 200 mm apart edge to edge; concrete stepped ramps strongly recommended with 90-100 mm rise and 300 mm tread run; self-aligning dock bumpers and telescopic side panels to close the gap to the truck; V-squeeze bottom widths of 150, 200, 300 and 350-400 mm by class; a small access gate behind the squeeze; A.I. dark box with 325 mm (13 in) man openings and a cross rail at three positions; and a scale offset from the chute whose cage, floor and gates form one weighed unit touching nothing.', '{plan,extension,facilities,loading,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd5e24a3-cf60-41d6-9457-85e9d46d256e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canadian Beef Cattle On-Farm Biosecurity Standard: implementation manual', 'Canadian Food Inspection Agency; Canadian Cattlemen''s Association', 2013, 'CFIA / Publications du gouvernement du Canada', NULL, 'https://publications.gc.ca/site/eng/470946/publication.html', 'https://publications.gc.ca/collections/collection_2014/acia-cfia/A104-105-1-2013-eng.pdf', NULL, NULL, NULL, NULL, 'canada', 3, 'Crown copyright, free reproduction for non-commercial purposes', 'The national biosecurity standard''s implementation manual for beef producers. Matters to corral design because the Code of Practice section 1.2 recommends considering biosecurity when designing and managing cattle facilities, and this is the document that says what that means in practice: segregated receiving and isolation areas for introduced animals, controlled access points, routing of vehicles and visitors, and separate handling of new or sick stock. Note that publications.gc.ca serves an ''Information Archived on the Web'' interstitial to automated fetchers unless a Referer header is sent; it downloads normally from a browser click.', '{standard,code-of-practice}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f9d3305d-4914-4386-9812-573882afc4bb', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The development and evaluation of a radio frequency identification based cattle handling system.', 'Tendai Justin. Mutenje', 2013, 'ResearchSpace (University of KwaZulu-Natal)', NULL, 'http://hdl.handle.net/10413/9641', 'http://hdl.handle.net/10413/9641', NULL, NULL, 255, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29c4c122-b151-4c92-a95a-372ee2ee561e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Canadian Beef Code Update: What Producers Need to Know', 'Karen Schwartzkopf-Genswein, Agriculture and Agri-Food Canada Lethbridge', 2026, 'Saskatchewan Stock Growers Association 113th AGM', NULL, 'https://skstockgrowers.com/', 'https://skstockgrowers.com/wp-content/uploads/2026/06/Canadian-Beef-Codes-Update-What-Producers-Need-to-Know.pdf', NULL, NULL, 16, NULL, 'prairies', 5, 'Conference presentation, publicly posted', 'The Scientific Committee chair''s 9 June 2026 briefing on what is changing in the beef Code of Practice. The single best preview of the 2027 edition. Facility-relevant changes flagged: a new section on mud and moisture; a Facilities section addressing safe, low-stress cattle movement and housing for severely sick or injured cattle; a new Non-Ambulatory Cattle section requiring prompt care, safe handling, appropriate lifting tools and access to feed and water; the electric prod requirement rewritten to ''Electric prods must not be used except to assist movement of cattle when other humane alternatives have failed''; weaning expanded and subdivided into pre-weaning, weaning and post-weaning with a new Requirement for increased monitoring after weaning; the colostrum window tightened from 6 to 4 hours; pain control required for assisted difficult calvings, spaying, and branding calves under 6 months (all cattle from 1 January 2032); transport requirements aligned to the amended Health of Animals Regulations; euthanasia methods put in table form with firearm and ammunition specifics by class of cattle.', '{code-of-practice,extension,handling,weaning}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('917a7a2a-4d45-490e-b4d1-3150d2a5c6fb', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Cattle Behavior and Cattle Handling', 'Temple Grandin', 1993, 'American Association of Bovine Practitioners Conference Proceedings', NULL, 'https://bovine-ojs-tamu.tdl.org/AABP/article/view/7552', 'https://bovine-ojs-tamu.tdl.org/AABP/article/download/7552/6117', NULL, NULL, NULL, NULL, 'other', 4, 'Open access AABP Proceedings', 'Practitioner-facing summary of why a curved chute works, with figures for a curved cattle handling facility and a curved loading ramp. States that circular crowd pens and curved chutes can reduce handling time, that curved chutes must have a straight section where they join the crowd pen and must be built as a smooth continuous curve, and that if the curve is too sharp the chute looks like a dead end. Confirms solid sides for single-file chute, loading chute and crowding pen; recommends the catwalk along the inner radius; and notes that for unloading only a wide straight chute of 6 to 10 ft is appropriate. Useful because it states the design rules in the same voice a vet would use with a producer.', '{design,curved-race,dead-end,solid-sides,veterinary}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('33b79310-9eee-4931-a6d1-5f28310046f7', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Cattle Behavior During Handling and Corral Design for Beef Cow Herds (Extension Bulletin E-2296)', 'Temple Grandin', 1991, 'Michigan State University Cooperative Extension Service, Michigan Beef Production', NULL, 'https://archive.lib.msu.edu/DMC/extension_publications/e2296/E2296-1991.PDF', 'https://archive.lib.msu.edu/DMC/extension_publications/e2296/E2296-1991.PDF', NULL, NULL, 13, NULL, 'other', 4, 'Free MSU Extension Publication Archive (archive copy; not current recommendations)', 'Grandin writing specifically for beef COW herds rather than feedlots or packing plants, which is the right audience for a cow-calf corral designer. Covers cattle behaviour during handling, flight zone, point of balance, and corral design for cow-calf operations with layout drawings. Archived by MSU with the caveat that it is not current recommendations, so it should be used as a historical statement of Grandin''s cow-herd guidance and cross-checked against her 1997 and 2021 papers rather than cited as current.', '{design,cow-calf,flight-zone,corral-layout,archived}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('94bd44e3-9c25-47eb-a011-f58337f5c038', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Cattle Corral Design- Learning by Doing', 'Stephen L. Boyles', 2007, 'Journal of Extension', '10.66752/1077-5315.4307', 'https://doi.org/10.66752/1077-5315.4307', 'https://commons.joe.org/cgi/viewcontent.cgi?article=4307&context=joe', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-sa', 'Quality Assurance training for adults has placed little emphasis on human injury and carcass defects such as bruising. To reduce the incidence of human injury and carcass defects, people need to understand corral design and animal behavior. An interactive curricula was developed using fence panels big enough to be placed on a tabletop. Participants were able to use the panels to make corral designs. There have been 2,304 people who have participated in the corral design and animal handling programs offered by the author. Evaluations averaged a 9.2 ± 0.58 on a 10-point scale (1=terrible idea, 10=great idea).', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1251ff60-57dc-4000-bde9-5d414ab936e3', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Cattle Feedlot Waste Management Practices For Water and Air Pollution Control.', 'John M. Sweeten', 1990, 'OakTrust (Texas A&M University Libraries)', NULL, 'https://hdl.handle.net/1969.1/160213', 'https://hdl.handle.net/1969.1/160213', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8ec569f-3f86-4603-b330-0a0da8a2e456', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle-Related Injuries and Farm Management Practices on Kentucky Beef Cattle Farms', 'Steven R. Browning, Susan Westneat, Wayne T. Sanderson, Deborah B. Reed', 2013, 'Journal of Agricultural Safety and Health', '10.13031/2013.42541', 'https://doi.org/10.13031/2013.42541', 'https://uknowledge.uky.edu/epidemiology_facpub/6', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('97a9c017-fbf3-4c4d-8da7-448765839157', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Cattle handling systems for efficiency', 'W. Mark Hilton', 2026, 'American Association of Bovine Practitioners Conference Proceedings', '10.21423/aabppro20269488', 'https://doi.org/10.21423/aabppro20269488', 'https://bovine-ojs-tamu.tdl.org/aabp/article/download/9488/9090', NULL, NULL, 2, NULL, 'other', 1, 'other-oa', 'When beef producers are surveyed and asked why routine herd health procedures like pregnancy checking cows are not done, inadequate facilities generally rank first or second. This can range from no facilities to an attitude of “it’s just not worth it” due to anticipated stress on both animals and people when working cattle. Because we see both good and bad facilities, we are well-positioned to assist our producers in designing or im­proving their handling facilities.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4e67e0d-47e8-4e37-9ece-e4e40234e6a7', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Cattle vocalizations are associated with handling and equipment problems at beef slaughter plants', 'Temple Grandin', 2001, 'Applied Animal Behaviour Science 71(3):191-201', '10.1016/S0168-1591(00)00179-9', 'https://www.sciencedirect.com/science/article/abs/pii/S0168159100001799', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Paywalled at Elsevier', 'The before-and-after study behind the outcome-based numbers the designer can use to validate a built facility rather than a drawing. Collected data before and after facility modifications and showed simple changes reduced both vocalisation and electric prod use: adding a light at a stun box entrance cut prod-driven vocalisation from 8 percent of cattle to 0, and reducing the pressure a neck stanchion applied cut vocalisation from 23 percent to 0. Establishes vocalisation and prod use as practical, cheap, repeatable measures of whether a handling facility actually works - which is what the corral designer should encourage users to record after a build.', '{design,outcome-measures,vocalization,lighting,peer-reviewed,measured,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('244f2b4b-d1a4-4c87-939c-c4e502916f2d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Clinical trial to assess the impact of acclimation and low-stress cattle handling on bovine respiratory disease and performance during the feedyard finishing phase', 'Reneé D. Dewell, Suzanne T. Millman, Rebecca L. Parsons, Larry J. Sadler, Tom Noffsinger, W. Darrell Busby, Chong Wang, Grant A. Dewell', 2019, 'The Bovine Practitioner', '10.21423/bovine-vol53no1p71-80', 'https://doi.org/10.21423/bovine-vol53no1p71-80', 'https://bovine-ojs-tamu.tdl.org/bovine/article/download/4281/4195', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-sa', 'Acclimation and low-stress cattle handling techniques (ALSCH) are promoted to improve cattle welfare. The purpose of this clinical trial was to evaluate the impact of ALSCH in relation to conventional handling (CON) on bovine respiratory disease (BRD) and performance of cattle during the feedlot phase of production. Abruptly weaned calves (n=136; 6 to 9 months of age) were transported to a research feedyard, and randomly enrolled into 4 pens-2 replicates of CON and 2 replicates of ALSCH. Conventionally handled calves were processed through a tub and curved alleyway facility without being acclimated. ALSCH calves were systematically acclimated to the feedyard environment and an open-sided "Bud-box" design working facility prior to processing. There were no differences in respiratory morbidity between treatment groups (P=0.34). From day 19 to day 95, ADG of CON calves was 2.70 lb (1.23 kg)/day versus 2.92 lb (1.33 kg)/day for ALSCH (P=0.01). Calves in CON pens tended to have a lighter mean hot carcass weight that was approximately 29 lb (13.2 kg) lighter than calves in the ALSCH pens (P=0.07). This clinical trial provides preliminary evidence that ALSCH may result in short-term performance benefits when applied to abruptly weaned calves in a feedyard setting, and provides background information for further scientific investigation.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3457a829-3023-469a-a575-63f9f41d4c8f', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Code of Practice for the Care and Handling of Beef Cattle', 'National Farm Animal Care Council (NFACC) / Canadian Cattlemen''s Association', 2013, 'National Farm Animal Care Council', NULL, 'https://www.nfacc.ca/codes-of-practice/beef-cattle', 'https://www.nfacc.ca/pdfs/codes/beef_code_of_practice.pdf', NULL, NULL, NULL, NULL, 'canada', 5, 'Free download from NFACC', 'Canada''s national welfare code and the only quasi-regulatory document that applies to this ranch. Still the current version as of November 2026; a revision is under way with public comment 13 April to 12 June 2026 and completion projected for Q2 2027. IMPORTANT FINDING: the Code contains NO facility dimensions whatsoever. Its handling-facility Requirements are only that all beef operations must have access to equipment or facilities for safe handling, restraint, treatment, segregation, loading and unloading; that facilities provide well-drained comfortable resting areas; and that traction be provided in handling areas to minimise slips and falls. Section 4.1 lists outcome-based handling measures to watch (falling, stumbling after release, running or jumping when leaving the chute) and says increasing levels may indicate a need to change lighting, noise, equipment, handling methods or environment. Recommended Practice 1.2(e) notes high-pitched sounds are especially disturbing to cattle.', '{design,code-of-practice,canadian,regulatory,no-dimensions,outcome-measures}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dcc456e1-fe69-44bf-8c4b-3d6103aa0afc', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Code of Practice for the Care and Handling of Beef Cattle: Review of Scientific Research on Priority Issues (November 2012)', 'Beef Cattle Code of Practice Scientists'' Committee; K. Schwartzkopf-Genswein; J. M. Stookey; J. Berg; J. Campbell; D. B. Haley; E. Pajor', 2012, 'NFACC', NULL, 'https://www.nfacc.ca/codes-of-practice/beef-cattle', 'https://www.nfacc.ca/resources/codes-of-practice/beef-cattle/Beef_Cattle_Review_of_Priority_Welfare_Issues_Nov_2012.pdf', NULL, NULL, 69, NULL, 'canada', 5, 'Publicly available; copyright NFACC', 'The peer-reviewed literature review that underpins the 2013 Code, by the Scientists'' Committee. Four parts: painful procedures (dehorning, castration, branding and identification), feedlot health and morbidity (BRD, lameness, nutritional disease), weaning methods, and environmental and housing conditions (mud, extreme cold, extreme heat). The housing part is the only place a Canadian normative document gives a windbreak figure from the science: windbreak designs with 15 to 30 per cent porosity cause snow to build up in shallow rather than deep drifts and protect better than solid fences. Concludes that excessive mud is a risk factor for lameness, injury and hoof disease and that feed per pound of gain rose 25 per cent in muddy conditions, but that research is still needed to define what constitutes excessive mud - which is why the 2013 Code has no mud threshold. Explicitly makes no recommendations; it relays science to the Code Development Committee.', '{code-of-practice,review,windbreak,mud,weaning,housing}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('85a9ac02-abc4-4ae1-b891-aca0cf99a35f', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Compliance of large feedyards in the northern high plains with the Beef Quality Assurance Feedyard Assessment', 'Ruth Woiwode, Temple Grandin, Brett H. Kirch, J. Paterson', 2016, 'The Professional Animal Scientist', '10.15232/pas.2015-01472', 'https://doi.org/10.15232/pas.2015-01472', 'http://www.appliedanimalscience.org/article/S1080744616300833/pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'Despite increasing public scrutiny of practices used in raising animals for food, there is little readily available information about how cattle handling is managed in feedyards. The purpose of this study was to score cattle handling in commercial feedyards using the most widely adopted program for managing cattle handling, and to make these scores available as evidence of producer commitment to proper care and handling of cattle. Our objectives were to estimate compliance with the Beef Quality Assurance Feedyard Assessment (BQA FA) for cattle handling, to validate 6 cattle handling categories of the BQA FA, and to document management practices and elements of facility design. Categories scored were electric prod use; chute operation; rates of cattle vocalizing, stumbling, and falling; and rate of cattle jumping and running. This study compiles findings for cattle handling scores in commercial feedlots using the BQA FA. Of 28 sites, average scores were in compliance with BQA FA for the following 4 categories: electric prod use, vocalization, stumbling, and falling. For the following 2 categories, average scores were not in compliance: a score of 4.2% versus the target of 0% was recorded for cattle caught improperly in the squeeze chute; and a score of 52% versus the target of 25% was recorded for cattle that jumped or ran from the squeeze chute exit. All but one site exceeded this target. Curved crowd systems were recorded for 89% of feedyards, 11% used Bud Box systems, and 78.5% had rubber mats at the squeeze chute exit.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9be98810-e434-4f24-86cc-4878c61eef94', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Conservation Practice Standard 382: Fence', 'USDA Natural Resources Conservation Service', 2009, 'USDA NRCS Conservation Practice Standard', NULL, 'https://www.nrcs.usda.gov/resources/guides-and-instructions/conservation-practice-standards', 'https://efotg.sc.egov.usda.gov/references/Delete/2009-12-12/Fence.pdf', NULL, NULL, 8, NULL, 'other', 2, 'US Government work, public domain', 'Included because it is the closest thing to an engineering standard for corral fencing that is freely available, and because it demonstrates that no structural DESIGN LOAD is published. The standard is prescriptive, not load-based: wood fences in a corral situation must have a minimum of four nominal 2 by 6 boards, placed on the livestock side of the posts; steel post spacing is capped at 8 ft on centre; post material options and bracing requirements are specified. If the corral designer needs a load check it must refer the user to MWPS-6 and a licensed engineer rather than cite a number, because figures circulating online (1,500 lb impact, 1,200-2,000 lb from a leaning animal) are vendor marketing with no engineering basis.', '{design,fence,structural,no-design-load,usda}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('079058ba-34e7-48ad-8f5c-c1c1c3bd79ef', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Corral and Working Facilities for Beef Cattle (BAE-1219)', 'Raymond L. Huhnke', 2017, 'Oklahoma Cooperative Extension Service', NULL, 'https://extension.okstate.edu/fact-sheets/corral-and-working-facilities-for-beef-cattle.html', 'https://pods.okstate.edu/fact-sheets/BAE-1219pod.pdf', NULL, NULL, 4, NULL, 'other', 4, 'Free Oklahoma Cooperative Extension Service fact sheet', 'The canonical North American dimension table (Table 1, Corral and Working Facilities Dimensions), derived from the Midwest Plan Service Beef Housing and Equipment Handbook: holding area 14/17/20 sq ft per head and crowding pen 6/10/12 sq ft per head for to-600 lb, 600-1200 lb and over-1200 lb; working chute with vertical sides 18/24/28 in wide and 20 ft minimum length; sloping sides 13/15/16 in bottom and 20/24/26 in top; working chute fence 45/50/60 in minimum height with posts 30 in deep; corral fence 60 in; loading chute 26 in wide, 12 ft minimum, 3.5 in rise per foot, with ramp heights of 15 in stock trailer, 28 in pickup, 40 in stock truck, 48 in tractor-trailer and 100 in double-deck. Adds two rules not in the table: add width for exotic breeds over 1200 lb, and the maximum width for a common alleyway used to SORT cattle is 12 ft. A quarter-circle crowding area with a 12 ft crowding gate handles up to eight mature cows. Note: this table is reprinted by Kentucky, Tennessee, Mississippi and Kansas, so those are not independent confirmations.', '{design,dimension-tables,mwps-lineage,alley-width,loading-ramp}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ae6ec64-62c1-4b75-a371-2414bb1aac10', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Corrals for handling beef cattle', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/0773261265', 'https://open.alberta.ca/dataset/fab2caa3-98d4-4c7d-9c44-f593a3a6c708/resource/c178b765-9fc0-4109-ae8f-568d690395a4/download/2149582-1993-corrals-handling-beef-cattle-agdex-420-723-1.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This comprehensive guide features information on cattle behavior, handling techniques, corral design corral geometry and corral components. It''s packed with over 60 designs and corral plans. It has been reviewed by industry experts including Temple Grandin, the internationally recognized expert on cattle behavior from Colorado State University.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4353523a-7eb0-48c8-a7f2-1ca00093b20e', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Corrals for Working and Handling Beef Cattle', 'University of Idaho Cooperative Extension Service', 1971, 'University of Idaho Extension Bulletin', NULL, 'https://objects.lib.uidaho.edu/uiext/uiext20065.pdf', 'https://objects.lib.uidaho.edu/uiext/uiext20065.pdf', NULL, NULL, 16, NULL, 'northern_plains', 2, 'Free University of Idaho Extension archive', 'A 1971 bulletin with complete bills of materials and construction drawings for working corrals, retained because it documents the pre-Grandin design tradition and gives construction detail modern sheets omit: post depth varying from two and a half feet in heavy gravelly soil to four feet in light clay, posts with at least five-inch tops treated to 12 in above ground line, post spacing no more than six feet (extendable to ten with heavier rails), catwalk 36-40 in above ground, alleys always at least 12 ft wide, gates 10-12 ft long for crowding areas, crowding pens sloped about 2 percent (half an inch per foot) for drainage, and loading chutes up to 16 ft long. The scanned text is OCR-degraded, so individual figures should be confirmed against the page images before being coded into the designer.', '{design,historical,construction,post-depth,bill-of-materials}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cbe14dfd-736e-4d6e-9e2f-c4aea83a3f44', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Injuries among children and youth in farm households: Regional Rural Injury Study-I', 'Susan Goodwin Gerberich, Robert W. Gibson, Lindsey French, Colleen M. Renier, T-Y Lee, W P Carr, John M. Shutske', 2001, 'Injury Prevention', '10.1136/ip.7.2.117', 'https://doi.org/10.1136/ip.7.2.117', 'https://injuryprevention.bmj.com/content/injuryprev/7/2/117.full.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0dace169-3679-4c2b-8431-44df977bdb19', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'CRSB Certified Sustainable Beef Production Standard, version 2.0', 'Canadian Roundtable for Sustainable Beef', 2025, 'CRSB', NULL, 'https://www.crsbcertified.ca/standards/the-standards', 'https://cdn.prod.website-files.com/6855a700a8f899e81d9cec7b/68cc67481f0433e126e98037_Production%20Standard_v2.0_FINAL.pdf', NULL, NULL, 48, NULL, 'canada', 5, 'Publicly available programme standard; copyright CRSB', 'The audited Canadian sustainability standard for cow-calf, backgrounding and feedlot operations, scored 0 to 3 per indicator with certification requiring the Achievement level on every one. Its Animal Health and Welfare indicators AHW 1 to AHW 8 are explicitly aligned to the 2013 NFACC beef Code and cite it by section. AHW 7 Behaviour requires that ''Adequate space shall be provided for cattle to express normal behaviour (i.e. all cattle are able to lay down at the same time; cattle can move freely and access feed and water)''. AHW 8 Unnecessary Stress covers handling, loading and unloading, transportation, cattle facilities and environmental conditions, and its Achievement level restates verbatim the Code 4.1 handling and prod Requirements plus the Code 1.2 Requirements for access to safe handling, restraint, treatment, segregation, loading and unloading equipment and for providing traction in handling areas. This is the document that turns the Code''s facility clauses into something a southern Alberta ranch is actually audited against.', '{standard,code-of-practice,facilities,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35a78365-f292-4dfb-a2ca-aa034ed9325d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Design of loading facilities and holding pens', 'Temple Grandin', 1990, 'Applied Animal Behaviour Science 28(1-2):187-201', '10.1016/0168-1591(90)90052-F', 'https://www.grandin.com/references/design.loading.facilities.holding.pens.html', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Paywalled at Elsevier; full text posted by the author at grandin.com', 'The source behind the loading-ramp and holding-pen numbers, with each one attributed so the reader can see which are measured and which are not. Ramp slope maximum 25 degrees adjustable and 20 degrees fixed for cattle and sheep, both attributed to Grandin 1979 - a single recommendation, not a trial. Level dock at the ramp top a minimum of one animal body length (Stevens and Lyons 1977; Grandin 1979; Agriculture Canada 1984). Stair steps 30 cm minimum tread and 10 cm rise for cattle (USDA 1967; Grandin 1980c, 1982). Cleat spacing 20 cm start to start for large cattle (Mayes 1978). Ramp width 76 cm single file cattle, 2.5-3 m for unloading only. Curved ramp inside radius 5 m. Round crowd pen radius 3.5 m cattle. Cattle alley 3 m on foot, 3.5 m foot and horseback, 4.2 m horseback; cattle pen width 3.5-4.2 m driven on foot; maximum pen length 25 m without block gates; holding pen 1.6 sq m per hornless and 1.85 sq m per horned feedlot steer under 24 hours.', '{design,loading-ramp,holding-pens,alley-width,cleats,peer-reviewed,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd7b71fe-0d48-4f54-9e0c-b53ba359f357', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Design, Planning, and Evaluation of Upgraded Cattle Handling Facility', 'Lindsey Kaeli Tulloch', 2010, 'DigitalCommons - CalPoly (California State Polytechnic University)', NULL, 'https://digitalcommons.calpoly.edu/braesp/20', 'https://digitalcommons.calpoly.edu/cgi/viewcontent.cgi?article=1014&context=braesp', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('90d6adec-12cf-4fa1-9771-aad996326a33', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Designing a Bud Box', 'Ron Gill and Rick Machen', 2014, 'Texas A&M AgriLife Extension Service', NULL, 'https://agrilife.org/', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Free Texas A&M AgriLife Extension publication; original PDF URL now dead', 'THE PRIMARY SOURCE for Bud Box dimensions, and the correction to a widely mis-quoted figure. Its table sets box size by handler type, not by head count: handler ALWAYS ON FOOT 12 ft minimum width by 20 ft depth; AFOOT AND HORSEBACK 14 ft by 20-30 ft; ALWAYS HORSEBACK 16 ft maximum width by 30 ft maximum depth, with depth ''dictated by size of groups handled''. MLA reproduces exactly this table in metric (3.7 by 6 m, 4.3 by 6-9 m, 4.9 by 9 m) in its 2016 feedlot manual, and Kansas MF3349 cites Gill as its source. This means the commonly quoted range of ''about 14 by 20 ft to 20 by 30 ft'' is WRONG ON WIDTH: the published widths are 12-16 ft, never 20. The original agrilifecdn.tamu.edu PDF now 404s; the table is recoverable from the MLA manual and from Cornell''s hosted copy.', '{design,bud-box,primary-source,dimension-correction,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29b33d0e-8dc1-4970-8071-8cd505aa76b6', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Designing a Bud Box for Cattle Handling (MF3349)', 'Kansas State University Research and Extension; dimension table by Raymond L. Huhnke and Sam Harp', 2017, 'Kansas State University Agricultural Experiment Station and Cooperative Extension Service', NULL, 'https://bookstore.ksre.ksu.edu/pubs/designing-a-bud-box-for-cattle-handling_MF3349.pdf', 'https://bookstore.ksre.ksu.edu/pubs/designing-a-bud-box-for-cattle-handling_MF3349.pdf', NULL, NULL, 27, NULL, 'northern_plains', 5, 'Free K-State Research and Extension publication', 'The best free source of Bud Box geometry, with eleven scaled layout templates. Minimum box 12 ft wide by 20 ft deep processing 5-6 mature cows; 24 ft box works 6-8 head; load-out box for semis commonly 14 ft wide by 30 ft deep. Alleyway minimum 28 in wide; allow 5-6 ft of alleyway per mature cow; the box must always be big enough to fill the alley it leads into and must never be used as a holding pen. Drive alleys 12 ft minimum on foot, 16 ft if horses are used. Explicit corner guidance: the purpose of angled fences is to eliminate as many 90-degree turns as possible; a 45-degree angled fence section aids turning cattle around; a single-file alley at 60 degrees from the box improves flow over the common 90 degrees. Curved alleys must be long enough for the lead animal to stay visible, at minimum fitting two head. Converted round tubs: limit a 12 ft diameter half-tub to 4-5 head, a 10 ft diameter to 3-4 head. Loading ramp steps 12 in wide and 4 in high. Reprints the Midwest Plan Service corral dimension table.', '{design,bud-box,corner-angles,dimension-tables,layout-templates}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0a0e7867-c4d0-4fa2-b629-adc81675aebe', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The influence of cattle yard design on the movement of animals', 'W. J. Vowles and T. J. Hollier', 1982, 'Proceedings of the Australian Society of Animal Production 14:597', NULL, 'https://agris.fao.org/search/en/records/64735bd808fd68d546029e85', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Conference proceedings, not online', 'THE source of the single most-quoted number in cattle handling - that a circular crowd pen and curved race can cut the time spent moving cattle by up to 50 percent. Presented at the 14th Biennial Conference of the Australian Society of Animal Production, Brisbane, 15 May 1982, by authors at the Victorian Department of Agriculture and its Animal Research Institute. It is a ONE-PAGE ABSTRACT. The 50 percent figure is repeated by Grandin (1989, 1997), the Alberta Agdex and dozens of extension sheets, but the sample size, cattle class and methods cannot be checked by anyone citing it. The software must not present this as an established effect size. Also cited as a source for the 3.5-6 m race radius.', '{design,curved-race,crowd-pen,conference-abstract,weak-evidence,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35e3b6fa-ff5c-46a4-8bda-0669baa7dd7a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Designing or Reworking Your Cattle-handling Facilities: A Checklist for Success (AEN-145)', 'Morgan Hayes and Josh Jackson', 2021, 'University of Kentucky Cooperative Extension Service, Biosystems and Agricultural Engineering', NULL, 'https://publications.ca.uky.edu/sites/publications.ca.uky.edu/files/AEN145.pdf', 'https://publications.ca.uky.edu/sites/publications.ca.uky.edu/files/AEN145.pdf', NULL, NULL, 4, NULL, 'other', 4, 'Free University of Kentucky Cooperative Extension publication', 'A planning checklist rather than a dimension table, which makes it the closest published analogue to what a software corral designer should walk a user through: site selection, access from all pastures, drainage, group sizes used to size the holding and crowding pens, which components are needed for which operation type (cow-calf versus seedstock), and sequencing of a build or rework. Valuable for structuring the designer''s prompts and warnings rather than for numeric thresholds.', '{design,checklist,planning,siting,engineering}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f1eb1db1-ab9f-49ef-bf6a-91bade092808', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Development of Physiological Procedures to Objectively Measure Stress in Cattle', 'Alberta agricultural research report', 1999, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/960be90e-1204-4a29-81fb-69959714cdfb', 'https://open.alberta.ca/dataset/960be90e-1204-4a29-81fb-69959714cdfb/resource/329a350f-0488-4afb-89b5-1957d386481b/download/163010147961-development-of-physiological-procedures-to-objectively-measure-stress-in-cattle.pdf', NULL, NULL, 84, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'Alberta-funded research on objectively measuring handling stress in cattle. Background to the measurable handling outcomes the Code of Practice section 4.1 Recommended Practice d asks producers to score - falling, stumbling, prod use, running or jumping from the chute, and vocalisation under restraint - and to the idea that those scores should drive changes in lighting, noise, equipment or environment.', '{extension,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1a1f8b45-9070-4aad-8336-ec0bae9acfe7', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Effect of good handling on stress indicators and behaviour in beef cattle', 'Carla Comerlato Jardim, Isabella Dias Barbosa Silveira, João Restle, Fábio Souza Mendonça, Javier Alexander Bethancourt-Garcia, Róberson Macedo de Oliveira, Renata Moraes, Nathália Pasi Reis', 2022, 'Semina Ciências Agrárias', '10.5433/1679-0359.2022v43n6p2517', 'https://doi.org/10.5433/1679-0359.2022v43n6p2517', 'https://ojs.uel.br/revistas/uel/index.php/semagrarias/article/download/46103/48116', NULL, NULL, 14, NULL, 'other', 1, 'cc-by-nc', 'Aspects related to good handling practices have significant impacts on animal behaviour with positive effects on the productivity and profitability of production systems. This study investigated the impact of good handling practices on the modification of stress indicators and the behaviour of beef cattle. Thirty-six male castrated bovines at the growth stage were evaluated for 490 days and submitted to two different production systems in Southern Brazil: good handling practices (GHP) and a traditional handling system of beef-cattle farming (THS). Body weight, reactivity indicators (flight distance and composite behaviour score), and blood indicators of stress (glucose and cortisol) were measured. An analysis of variance was carried out with measurements repeated over time, and Pearson''s correlation applied between the variables mentioned above. No differences were found (P>0.05) for body weight in any of the evaluations, with initial weights of 196.2 and 196.3 kg and final weights of 431.0 and 413.8 kg for the GHP and THS steers, respectively. The GHP determined better values for the stress and behavioural indicators compared to THS (P<0.05). The flight distance of the GHP animals decreased from 11.33 to 5.22 metres from the first to the last evaluation, while in the THS animals the values were 10.17 and 11.89 metres, respectively. The behaviour composite score differed in the evaluations at 372 and 490 days, with values of 1.77 and 1.47 for GHP animals and values of 2.92 and 2.83 points for THS animals, respectively. Glucose and cortisol levels decreased with the advancing evaluations in GHP animals, with values from 94.80 to 74.22 mg/dL and from 6.08 to 3.68 µg/dL, respectively. In THS animals, glucose and cortisol levels were similar in the initial and final evaluations, with values of 89.30 and 91.28 mg/dL and 5.34 and 5.80 µg/dL, respectively. Regardless of the handling, the final body weight of the animals correlated negatively with the reactivity indicators and physiological stress indicators. The reactivity of the cattle is influenced by the quality of the human-animal interaction but has no effect on the performance of animals raised on pasture. Good handling practices reduce the reactivity and stress indicators of cattle.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0833cb32-aba4-40e8-b4ac-c89106ce1f70', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Effect of the angle of slope on the ease with which pigs negotiate loading ramps', 'P. A. Phillips, B. K. Thompson and D. Fraser', 1988, 'Canadian Agricultural Engineering / Applied Animal Behaviour Science', NULL, 'https://www.researchgate.net/publication/21301518', NULL, NULL, NULL, NULL, NULL, 'canada', 2, 'Paywalled', 'Recorded as the honest counterweight to the 20-degree cattle ramp rule. The only CONTROLLED ramp-angle work in livestock is in pigs, not cattle: this study and Fraser et al. 1986 found pigs preferred 20-24 degrees over 28-32 degrees, Warriss et al. 1991 found steep ramps stressful, and Garcia et al. 2019 found heart rate rises on steeper ramps, with ascent time increasing linearly above about 20 degrees. The cattle figures of 20 degrees fixed and 25 degrees adjustable trace to a single Grandin 1979 recommendation repeated for over forty years, with NO cattle trial behind them. The corral designer should state the 20-degree limit and say plainly that it is a convention supported by pig data, not by a cattle experiment.', '{design,loading-ramp,ramp-angle,pigs,measured,evidence-gap,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ee83c230-bd05-41f0-a008-49c39bce9b23', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Injuries and Fatalities Involving Loaders Operating Around Open Liquid and Agricultural Waste Storage Facilities', 'Corey Schmidt, Joseph E. Price, William E. Field, Noah Joel Haslett, Mahmoud M. Nour, Yuan-Hsin (Charlene) Cheng', 2026, 'Journal of Agricultural Safety and Health', '10.13031/jash.16700', 'https://doi.org/10.13031/jash.16700', 'http://elibrary.asabe.org/azdez.asp?JID=3&AID=56069&t=2&v=32&i=3&CID=j2026&downPDF=Y&directPDF=Y', NULL, NULL, 13, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd16074c-1186-484f-8f5d-a026a35868fd', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Effects of conditioning, source, and rest on indicators of stress in beef cattle transported by road', 'Daniela M Meléndez, Sònia Martí, Derek B. Haley, Timothy Damian Schwinghamer, K. S. Schwartzkopf-Genswein', 2021, 'PLoS ONE', '10.1371/journal.pone.0244854', 'https://doi.org/10.1371/journal.pone.0244854', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0244854&type=printable', NULL, NULL, 25, NULL, 'southern_alberta', 5, 'cc-by', 'Consumers are increasingly concerned about the welfare of farm animals, especially during transportation. The Canadian transport regulations state that weaned cattle require an 8 h rest after 36 h of transport. There are, however, only a few studies that assess the effect of rest on the welfare of beef cattle. The aim of this study was to assess the effect of conditioning, source and rest on indicators of welfare in 7-8-month-old beef calves during long-distance transport. Treatments consisted of a 2 × 2 × 2 factorial design where the main factors were conditioning: conditioned (C; n = 160) or non-conditioned (N; n = 160); source: auction market (A; n = 160) or ranch direct (R; n = 160); and rest: 0 h (0 h; n = 160) or 8 h (8 h; n = 160). Means of non-esterified fatty acids (NEFA), serum amyloid-A, haptoglobin, creatine kinase (CK), and percentage of time standing from N calves were greater than C calves (all p ≤ 0.05). Means of percentage of time standing and CK of R calves were greater than A calves (both p ≤ 0.05). The mean of NEFA of 0 h calves was greater than the 8 h calves (p < 0.01), while the percentage of time standing of 0 h calves was less than 8 h calves (p < 0.01). Statistically significant differences between means of NEFA and standing percentage, were observed between 0 h and 8h calves. Few and inconsistent indicators of reduced welfare were observed between auction market and ranch direct calves, while non-conditioning was associated with greater physiological and behavioural indicators of reduced welfare. Based on these results, conditioning should be implemented as a management practice to improve the welfare of transported calves.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44291b39-176c-4716-99d3-0480a7efdf4a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Effects of initial handling practices on behavior and average daily gain of fed steers', 'Ruth Woiwode, Temple Grandin, Brett H. Kirch, Paterson J', 2016, 'International Journal of Livestock Production', '10.5897/ijlp2015.0277', 'https://doi.org/10.5897/ijlp2015.0277', 'https://academicjournals.org/journal/IJLP/article-full-text-pdf/134C91758171.pdf', NULL, NULL, 7, NULL, 'northern_plains', 3, 'cc-by', 'The objective of this study was to investigate the relationship between handling methods, cattle behavior during handling, and average daily gain (ADG) of feed yard cattle. Hereford steers (n = 496; initial body weight [BW] = 304 ± 35.6 kg) of similar genetic background were enrolled in this study after arrival at a commercial feed yard in Southwest Kansas. Two handling conditions prior to the working barn and two conditions of release from the squeeze chute were imposed. When cattle were moved from home pens to the working area, handlers were required to quietly walk all steers (SLOW); or handlers were permitted to bring steers to the processing area in the normal manner (FAST), which included handlers running, yelling, and cracking whips. Individual steers were randomly assigned to one of the two conditions of release from the squeeze chute. The first was a delay not longer than 30 s following the completion of procedures to allow cattle to stop struggling (DELAY); the second was release immediately following the completion of procedures (NORM). Vocalization and behavioral agitation (chute score) were measured in the squeeze chute and exit speed and exit behavior scores were assigned to all steers as they exited the squeeze chute the first time they were worked after entering the feed yard. Paired t-tests determined that cattle exiting the chute at a walk or trot vs. a run tended to have higher (P=0.08) ADG. Cattle vocalizing during restraint had lower (P=0.04) ADG than those that did not vocalize. The FAST group showed a tendency to vocalize more frequently than the SLOW group. There was a significant positive correlation between exit speed and vocalization (P= 0.0021, r= 0.14256) and a significant negative correlation between exit speed and ADG (P=0.0036, r=-0.13542). Handling was correlated with both behavior and ADG. Cattle that vocalize during handling and restraint may have reduced weight gains. Key words: Average daily gain (ADG), cattle handling, feed yard, squeeze chute, weight gain.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4c779e29-fdbf-42d3-9a87-0bb3c1e93db0', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Effects of shade and sprinklers on performance, behavior, physiology, and the environment of heifers', 'N.M. Marcillac-Embertson, P.H. Robinson, James G. Fadel, Frank M. Mitloehner', 2009, 'Journal of Dairy Science', '10.3168/jds.2008-1012', 'https://doi.org/10.3168/jds.2008-1012', 'http://www.journalofdairyscience.org/article/S0022030209703558/pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('59cadc94-7ea8-435c-81a4-cab96e5a4e14', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Electric Fencing Manual for Alberta', 'Alberta Agriculture', 1998, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/664d0da9-3a45-4c15-9cd1-95a1f56492a4', 'https://open.alberta.ca/dataset/664d0da9-3a45-4c15-9cd1-95a1f56492a4/resource/23d2fa3e-f840-40e2-822c-601de0cbe067/download/0163010297568-electric-fencing-manual-for-alberta.pdf', NULL, NULL, 28, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'Alberta''s full electric fence design manual: energizers, grounding, wire spacing, post spacing, bracing, gates and maintenance. Useful for the temporary and weaning fences around a corral system, where the 2008 cow-calf manual gives only summary spacings.', '{extension,plan}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f7bd2515-d2c0-4dc7-a127-177a10e1260a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Engineering and design of holding yards, loading ramps and handling facilities for land and sea transport of livestock', 'Temple Grandin', 2008, 'Veterinaria Italiana 44(1):235-245', NULL, 'https://www.izs.it/vet_italiana/2008/44_1/235.pdf', 'https://www.izs.it/vet_italiana/2008/44_1/235.pdf', NULL, NULL, 11, NULL, 'other', 4, 'Free full text from Istituto Zooprofilattico Sperimentale dell''Abruzzo e del Molise', 'The citation behind Grandin''s flooring and cleat numbers, which later papers (including Grandin 2021) point to. Argues that stair steps beat grooves because ''steps are more effective than grooves and provide non-slip footing even when old and worn. Grooves wear down quickly and become slick.'' Concrete stair step dimensions for a cattle truck loading ramp: 10 cm rise with a 30 cm or longer tread, plus two grooves at least 2.5 cm deep in each step. Cleats 5 cm by 5 cm hardwood for cattle and other large livestock, 2.5 cm by 2.5 cm for smaller species, with concrete reinforcing rod suitable for steel ramps, and the governing rule that cleats must be spaced so a hoof fits between them. Also distinguishes facilities for intensively raised halter-trained animals from those for extensively raised cattle - directly relevant to a range cow herd.', '{design,loading-ramp,flooring,cleats,stair-steps,peer-reviewed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8515471-e886-4ec8-92b4-49d9713b76c3', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Estimating carbon retention in soils amended with composted beef cattle manure', 'Bobbi L. Helgason, Francis J. Larney, Henry H. Janzen', 2005, 'Canadian Journal of Soil Science', '10.4141/s04-049', 'https://doi.org/10.4141/s04-049', 'https://cdnsciencepub.com/doi/pdf/10.4141/S04-049', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by', 'Composted cattle manure is often used as a soil amendment to replenish nutrient pools and to supply a source of stable C. Compost composition affects the availability of nutrients and the stability of C following the addition of compost to soil. We investigated C mineralization in a loamy sand and a loam soil amended with nine composts, two fresh manures and alfalfa (Medicago sativa L.) hay at a target rate of 10 mg total C g-1 soil. Soils were incubated at 25°C for 168 d. There was a significant interaction between amendment and soil type on C mineralization but generally, the effect of soil texture on amendment decomposition was small. The composts were very dissimilar in composition and resulted in substantial differences in the amount of C retained in the soils (2-39% C added evolved as CO2). Total C evolved during the incubation period could be predicted from the NH4-N content and the NH4-N/NO3-N ratio of the composted manures (R2 = 0.91–0.93). Estimation of the C retained in soils amended with compost as a function of simple chemical properties of the compost provides an important tool for evaluating the effectiveness of compost as a soil amendment, helping to calculate net retention of C. Key words: Compost, mineralization, soil carbon, amendment', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('28a3f5b9-1178-4b58-a775-bd84c4dd2054', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Eye white percentage as a predictor of temperament in beef cattle', 'Sarah Core, Tina M. Widowski, Georgia J. Mason, Stephen Paul Miller', 2009, 'Journal of Animal Science', '10.2527/jas.2008-1554', 'https://doi.org/10.2527/jas.2008-1554', 'https://atrium.lib.uoguelph.ca/bitstreams/1652997d-dbd7-451c-899d-7818844e5e49/download', NULL, NULL, 9, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e1e11789-5b78-40ed-91e8-1d3a29029bef', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Feedlot Design and Construction, Section 23: Cattle processing facility', 'Rod Davis and Scott Janke', 2016, 'Meat & Livestock Australia (MLA), Feedlot Design and Construction manual', NULL, 'https://www.mla.com.au/research-and-development/Infrastructure-and-equipment/feedlot-design-manual/', 'https://www.mla.com.au/globalassets/mla-corporate/research-and-development/program-areas/feeding-finishing-and-nutrition/feedlot-design-manual/023-processing-facility-2016_04_01.pdf', NULL, NULL, 18, NULL, 'other', 4, 'Free MLA publication', 'The most engineering-literate free source, and the only one giving the Bud Box dimension table in metric alongside an explicit safety critique. Race clear width 660-760 mm with the trade-off stated (too wide lets small cattle turn around or all cattle put their heads down beside the animal in front; too narrow constrains large cattle); race length 1.6-2.4 m per adult beast; the race must be straight for at least two animal lengths at the start because an immediate curve would look like a dead end; drafting race 4000-4800 mm long at 760-820 mm single-animal width. Circular forcing yard sweep 180 to 270 degrees, with a funnel alternative of one straight side and the other entering the race at approximately 30 degrees. Catwalk minimum 600 mm wide with handrails required above 300 mm elevation. Bud Box Table 1: 3.7 m wide by 6 m minimum deep for a handler always on foot, 4.3 m by 6-9 m afoot and horseback, 4.9 m maximum by 9 m maximum always horseback; the race entry must be a SQUARE opening not V-shaped; the far end must not be enclosed so cattle see light; cattle must never be held in the box; 90-degree corners in a Bud Box are intentional and make construction simpler. Notably contradicts part of Grandin''s circling rationale: ''this circling can raise the arousal level of the cattle making them more difficult and dangerous to handle''.', '{design,bud-box,race-width,forcing-pen,catwalk,engineering,australian}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('727c1d8e-1b67-480d-854f-45f4297fb42b', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Fencing and Handling Facility Standards for Diversified Livestock Farms', 'Alberta Agriculture and Irrigation (Director, Livestock Industry Diversification Act)', 2026, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/publications/fencing-and-handling-facility-standards-for-diversified-livestock-farms', 'https://open.alberta.ca/dataset/304cfbcb-cdc1-42cf-840b-c75fbf6aeb99/resource/5680d452-e345-4f7e-9838-e3fc93a693bd/download/fencing-and-handling-facility-standards-for-diversified-livestock-farms.pdf', NULL, NULL, 2, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'The only legally binding handling-facility design standard in Alberta - but it applies to domestic cervids, not beef cattle. Made by the Director under section 14 of the Livestock Industry Diversification Act and revised June 2026. Requires a minimum enclosed area of not less than 10 acres; elk and moose perimeter fences of at least 2.5 m (8 ft) mesh wire, or 2.1 m (7 ft) mesh plus two high-tensile wires above, with wires no more than 15 cm (6 in) apart; deer fences of 2.8 m (9 ft) or 2.5 m plus two wires; horizontal wires 15 cm or less apart and verticals 30 cm or less; all new perimeter fence built as 20-96-6 high-tensile wire (20 horizontal wires at 2.5 m total height with 15 cm vertical spacing); gates the same height as the fence, closed and secured. Handling facilities must consist of a squeeze, crush or alley-way designed to hold animals securely and prevent injury to workers or animals; must be sited so all animals can be captured within one week of notice of inspection; should not form any part of the perimeter fence; and all loading and unloading must happen entirely inside the perimeter fence. Useful as a model of how a jurisdiction writes an enforceable facility rule.', '{standard,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7f837d60-617e-4e44-ab32-b93f230eb50c', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Flight distance in Merino sheep', 'G. D. Hutson', 1982, 'Animal Production 35(2):231-235', '10.1017/S0003356100000908', 'https://www.cambridge.org/core/journals/animal-science/article/abs/flight-distance-in-merino-sheep/797D9337104EBD2CC304029B0E0E0901', NULL, NULL, NULL, NULL, NULL, 'other', 2, 'Paywalled at Cambridge University Press', 'Included because it is one of the few MEASURED flight-zone results in the handling literature, and because the finding has a direct geometric consequence a designer can use: animals confined in a NARROW alley had a SMALLER flight zone than animals confined in a wider alley (cited by Grandin 1997). That supports the otherwise unsupported rule that an alley should be narrow enough that cattle cannot circle the handler. The work is in Merino sheep, so transfer to beef cattle is an assumption and should be flagged as such wherever the software leans on it.', '{design,flight-zone,alley-width,sheep,measured,peer-reviewed,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('db906c8f-c092-45be-8ae4-4d974853a21c', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Forces Exerted by Hydraulic Cattle Chutes', 'Louis J. Perino, David B. Parker, Renee Brown, Michael B. Jeter', 2019, 'The Bovine Practitioner', '10.21423/bovine-vol34no1p63-65', 'https://doi.org/10.21423/bovine-vol34no1p63-65', 'https://bovine-ojs-tamu.tdl.org/bovine/article/download/1772/7832', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-sa', 'To describe the magnitude and variability of forces generated, we measured peak forces at nine different locations in hydraulic chutes used for cattle restraint. The headgate, middle of the chute, and tailgate were each measured at 18, 34, and 48 inches from the chute floor using a 3,000 lb capacity, high accuracy S-beam load cell. Peak forces generated by hydraulic chutes ranged from a low of approximately 100 lb to a high of over 3000 lb. There were large variations in forces observed within and between facilities, with the coefficient of variation on chute forces across all chutes at approximately 50% for all positions assessed. At 34 inches from the floor, 43, 14, and 29% of chutes generated less than 600 lb of force at the headgate, middle, and tailgate, respectively, while 29, 50 and 21 % of chutes generated greater than 1000 lb of force at the headgate, middle, and tailgate, respectively. There is a large amount of variability in forces generated by hydraulic chutes used for cattle restraint. Some chutes generate forces potentially hazardous to cattle.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b5f3c317-0658-464a-9d6b-29a382e39a5c', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Habituation Protocols Improve Behavioral and Physiological Responses of Beef Cattle Exposed to Students in an Animal Handling Class', 'Aska Ujita, Zachary K Seekford, Michelle L Kott, Guillermo Goncherenko, Nicholas W Wege Dias, Erica N. Feuerbacher, Luciana Bergamasco, Leonie Jacobs', 2021, 'Animals', '10.3390/ani11082159', 'https://doi.org/10.3390/ani11082159', 'https://www.mdpi.com/2076-2615/11/8/2159/pdf?version=1627284932', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Our objective was to determine the impact of different habituation protocols on beef cattle behavior, physiology, and temperament in response to human handling. Beef heifers were exposed to three habituation strategies: (1) tactile stimulation (brushing) in the working chute for seven consecutive days (STI; n = 18); (2) passage through the working chute for seven consecutive days (CHU; n = 19) and; (3) no habituation (CON; n = 19). Individual heifer respiratory rate (RR; n/min), internal vaginal temperature (VAGT; °C), and blood cortisol were measured. Further, behavior parameters were observed to generate a behavior score, and heifer interaction with students and their behavioral responses were recorded. Habituation with STI and CHU resulted in improved numerical behavioral scores compared to CON, and greater (p ≤ 0.05) handling latencies. Vaginal temperature was decreased in STI compared to CHU and CONT (p ≤ 0.05). Cortisol concentration did not differ among treatments, but decreased (p ≤ 0.05) from the start of the experiment to 14 days after treatment initiation. Both habituation protocols showed benefits, but heifers that received the positive tactile stimulation in the chute had the greatest behavior improvements. Furthermore, these heifers responded more calmly during student-animal interactions in class, which is beneficial for the students’ and animals’ safety.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('24f5dc24-e63e-417f-b3bb-ab9b09920ce2', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Handling Facilities', 'Tom Ryan (Teagasc, Kildalton)', 2025, 'Teagasc (Irish Agriculture and Food Development Authority) / Irish Farmers Journal', NULL, 'https://www.teagasc.ie/', 'https://teagasc.ie/wp-content/uploads/2025/05/HandlingFacilities_Farmers-Journal.pdf', NULL, NULL, 4, NULL, 'other', 4, 'Free Teagasc publication', 'Short but contains the clearest published statement anywhere of the funnel angle that causes two cattle to wedge abreast: ''The angle of the funnel is critical and should not exceed 30 degrees. If the angles are wider, cattle may block or turn at the mouth of the race or two cattle may become jammed at the race entrance.'' One side of the funnel must be straight; widest point 3-4 m. Race length minimum 3.6 m and preferably over 5 m, with 9 m holding 5-6 cattle and long races above 12 cattle discouraged. Race internal width 650-700 mm adult, up to 900 mm for exceptionally large pedigree stock, about 500 mm for young stock; race height 1.4-1.5 m; uprights about 2 m apart; side bars 350-400 mm apart. Catwalk 300-450 mm high and 375-450 mm wide with a working area not less than 1.2 m. Safety passes 300-350 mm clear, at least one per pen and one every 7.5-8 m in handling passageways, with the warning not to place a pass where animal flow lines up with it because excited animals try to escape through it and become trapped. Collecting pen areas 0.9-1.1 sq m young, 1.4-1.7 finishing, 2.3-2.75 suckler cows with calves.', '{design,funnel-angle,jamming,race-width,safety-pass,catwalk,recent}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('81d1baca-f2b7-48f2-a341-e1d5d1735d00', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Handling, reactivity and price of beef cattle', 'Cínara da Cunha Siqueira Carvalho, Evileide Marques de Oliveira, Maria Dulcinéia da Costa, Camila Maida de Albuquerque Maranhão, Tatiany Carvalho Santos, Flávio Pinto Monção, Vicente Ribeiro Rocha Júnior, José Reinaldo Mendes Ruas', 2020, 'Journal of Animal Behaviour and Biometeorology', '10.31893/jabb.20015', 'https://doi.org/10.31893/jabb.20015', 'https://www.jabbnet.com/article/10.31893/jabb.20015/pdf/jabbnet-8-2-111.pdf', NULL, NULL, 9, NULL, 'other', 1, 'cc-by-nc-nd', 'Given the importance of cattle breeding for the Brazilian economy, as well as the growing concern with animal welfare, studies that clearly and objectively approach the way cattle are handled during auctions become necessary. This study aims, hence, at assessing the influence of cattle handling on the reactivity of animals at the time of arrival at the exhibition park. We also aimed to evaluate the impact of reactivity and visual aspects on the price for animals at auctions in the northern region of the state of Minas Gerais. We observed 241 lots of commercial and 43 lots of pedigree cattle in loco, assessing the type of handling and the cattle''s behavior when arriving at the exhibition park, accommodation in the corral and loading to the destination. Upon arrival, commercial animals were more reactive than pedigree cattle due to the change of environment – exhibition park as opposed to their original habitat, and also to the number of visitors who induce stress and cause the animals to retreat. Commercial and pedigree females were more reactive than males upon arrival and loading, particularly when close to their offspring. Commercial animals that scored high in aggressiveness had smaller flight zones, for they run toward fences when threatened. Young commercial animals entered the auction ring with no external help due to anxiety and restlessness. The visual aspect influences the price in virtual markets.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('522d4da0-4441-4361-bec5-6fdf01027014', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'High-tensile Smooth Wire Fencing Manual for Alberta', 'Alberta Agriculture', 1998, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/4257813e-3d4e-499e-bacf-97c5db3d86dc', 'https://open.alberta.ca/dataset/4257813e-3d4e-499e-bacf-97c5db3d86dc/resource/fab141d2-2e09-4f85-9728-579287b033d0/download/0163010297527-high-tensile-smooth-wire-fencing-manual-for-alberta.pdf', NULL, NULL, 24, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'The companion manual for high-tensile smooth wire fencing in Alberta: 12.5 gauge minimum, breaking load and tensile strength specifications, wire spacing tables by use, post and stay spacing, bracing, in-line strainers and tension springs. The full version of the summary tables in the Beef Cow-calf Manual, and the fence type most likely to be drawn around a weaning paddock.', '{extension,plan}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('842279cc-ebc0-4b52-9b25-cf40840a6af5', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Horse Handling Facilities (Agdex 460/722-1)', 'Alberta Agriculture and Rural Development', 2016, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/publications/horse-handling-facilities', 'https://open.alberta.ca/dataset/808ca330-589e-4fad-95b2-0dfac083c314/resource/4b98390c-5140-4ba3-9624-9821d7faa974/download/163010276893-horse-handling-facilities.pdf', NULL, NULL, 56, NULL, 'alberta', 2, 'Open Government Licence - Alberta', 'Alberta''s handling facility design sheet for horses, written in the same idiom and by the same engineering group as the cattle corral material: alleys, pens, chutes, gates and loading. Useful as a cross-check on the cattle dimensions and if the designer is ever extended to horse corrals.', '{plan,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('32095988-3aa1-430c-b66f-444a1d51825a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Human animal relationships in Bos indicus cattle breeds addressed from a Five Domains welfare framework', 'Daniel Mota‐Rojas, Alexandra Louise Whittaker, Ana Strappini, Agustı́n Orihuela, Adriana Domínguez-Oliva, Patricia Mora‐Medina, Adolfo Álvarez-Macías, Ismael Hernández-Ávalos', 2024, 'Frontiers in Veterinary Science', '10.3389/fvets.2024.1456120', 'https://doi.org/10.3389/fvets.2024.1456120', 'https://public-pages-files-2025.frontiersin.org/journals/veterinary-science/articles/10.3389/fvets.2024.1456120/pdf', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc-by', 'The present review has two objectives, the first is to investigate the differences in temperament between Bos indicus and Bos taurus breeds and determining the effects on production due to positive treatment and to compare this with negative HAR, by using the Five Domain Model as framework. The second objective is to discuss potential strategies to achieve better HAR when working with Bos indicus cattle. Bos indicus are more reactive and temperamental than Bos taurus cattle. When human animal relationships (HAR) are evaluated, Bos indicus cattle may react with greater intensity. They may be more likely to develop a negative emotional state, especially in extensively raised Bos indicus cattle that are handled only a few times each year. Bos indicus cattle can have positive emotional states when they have frequent positive interactions with people. Interactions with people, both positive and negative, would be in the fourth Domain of the Five Domains model. Cattle that are more reactive during handling may also have lower weight gain, even when they have abundant feed. This would be in the first Domain of Nutrition. When cattle are handled in races and corrals, injuries may be more likely to occur. Injuries and bruises would be in the third Domain of Health. Injuries could be caused by either poor handling practices by people or poor handling facilities. Yelling or electric prod use would be examples of poor HAR. Second Environmental Domain issues may be broken facilities or slick, slippery floors that are associated with falls.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb67b198-7878-43e3-8605-38c8a9abc5f8', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Illinois Grazing Manual Fact Sheet: Livestock Handling Facilities Designs', 'USDA Natural Resources Conservation Service, Illinois', 2008, 'USDA NRCS, Illinois Grazing Manual Part 4', NULL, 'https://www.nrcs.usda.gov/resources/guides-and-instructions/illinois-grazing-manual', 'https://nrcs-prod.azureedge.us/sites/default/files/2023-02/IGMpt4.pdf', NULL, NULL, 17, NULL, 'other', 4, 'US Government work, public domain', 'A USDA fact sheet that summarises the Midwest Plan Service MWPS-6 handling designs and is therefore a free route to numbers otherwise locked in that handbook. Gives several thresholds not found elsewhere: slope working facilities at less than 3 percent to reduce gate swing problems; taper the crowding or funnel pen from 12 ft to about 2 ft at the chute entrance; a minimum curve radius of 15 ft is recommended for a working chute; provide at least a 20 ft long chute to hold 3 or 4 head; chute sides should be about 4 in above the ground for manure removal and insect control; one crowding pen is sufficient for operations up to 250 cattle; conditioning pens for newly arrived stressed cattle at 100 sq ft per head; hospital area concrete roughened and sloped a quarter inch per foot. Also reproduces several complete corral layout plans.', '{design,curve-radius,funnel-taper,mwps-lineage,usda,layout-plans}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a3a6b162-e8d8-4c29-bcc9-31b17ffaa00d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Influence of handling in corrals on the temperament of different breeds of beef cattle raised in Brazil', 'Anielly de Paula Freitas, Maria Lúcia Pereira Lima, Flávia Fernanda Simili, João Alberto Negrão, Flávio Schramm Schenkel, Cláudia Cristina Paro de Paz', 2023, 'Journal of Animal Science', '10.1093/jas/skad300', 'https://doi.org/10.1093/jas/skad300', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10540815/pdf/skad300.pdf', NULL, NULL, NULL, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d2e444ae-e8a0-4b56-89a9-8f62f9dadfe2', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Laying out curved handling facilities for ranches and feedlots', 'Temple Grandin', 2015, 'grandin.com (author''s own design guidance pages)', NULL, 'https://www.grandin.com/design/curved.handling.facilities.html', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Free on the author''s website; HTML only', 'The most directly actionable layout page Grandin publishes, and the one a corral designer should encode first. Round crowd pen ideal radius 12 ft, with the reasoning spelled out: a crowd gate longer than 12 ft makes the pen too big and an 8 ft gate makes it too small. Cattle should make a 180 degree turn through a round crowd pen, and where that is not possible a turn of 90 degrees or more. Keep the crowd pen under half full, because cattle need room to turn. An animal standing in the crowd pen must be able to see a minimum of two body lengths up the chute before it turns, and the article elsewhere recommends two to three. The fix for a chute that bends too sharply at the crowd pen - and therefore looks like a dead end - is to add a 10 ft straight section of single-file chute. If a building does not cover the entire crowd pen and chute, at least two body lengths of chute should extend outside it. No PDF; HTML only.', '{design,curved-race,crowd-pen,sight-lines,dead-end,layout,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('876808c1-f428-449c-b69f-0711a968a981', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Livestock Control: Non-Electric Fence Designs (Order No. 307.260-1)', 'British Columbia Ministry of Agriculture', 2010, 'Government of British Columbia, Ministry of Agriculture', NULL, 'https://www2.gov.bc.ca/gov/content/industry/agriculture-seafood/agricultural-land-and-environment/strengthening-farming', 'https://www2.gov.bc.ca/assets/gov/farming-natural-resources-and-industry/agriculture-and-seafood/farm-management/structures-and-mechanization/300-series/307260-1_livestock_contol_-_non-electric_fence.pdf', NULL, NULL, 25, NULL, 'canada', 3, 'Province of British Columbia, free download', 'A Canadian government fence-construction reference covering post sizing, embedment, bracing, rail arrangements and corner and gate construction for livestock containment. Included for the fence and gate construction side of the corral designer, and because it confirms the pattern seen across the whole literature: Canadian and US agencies publish prescriptive material and spacing requirements rather than structural design loads for handling-yard fences.', '{design,fence,posts,canadian,construction}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b8065251-4bd8-4047-af55-600b33e647b1', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Livestock-Handling Related Injuries and Deaths', 'Kamil Hakan Doğan, Şerafettin Demirci', 2012, 'InTech eBooks', '10.5772/50834', 'https://doi.org/10.5772/50834', 'https://www.intechopen.com/citation-pdf-url/40418', NULL, NULL, 36, NULL, 'other', 1, 'cc-by', 'Handling livestock is a dangerous activity.Few farm people look upon their livestock as a source of danger.However, a number of serious injuries and deaths occur every year as a result of animal-related accidents.Livestock handlers are involved in a variety of activities such as feeding, moving animals to different locations, loading animals on trucks/trailers, artificial insemination, shearing, grooming, basic animal care such as hoof care, dehorning, and cleaning animals, roping animals, applying topical insecticides, giving vaccinations, applying topical or administering oral medications, castrating, pulling teeth, ear tagging, milking, branding, shoeing, assisting with delivery of newborns, and assisting veterinarians with treatment or handling of injured animals.Other activities involving animals may include work tasks such as plowing fields; pulling equipment such as wagons to transport farm goods; riding animals, primarily horses, for farm or ranch activities such as corralling cattle; teaching others to ride; butchering animals for food; and, rarely, euthanizing or destroying sick or aggressive animals (Langley & Morrow, 2010).The World Health Organization predicts that by the year 2020, injuries will be responsible for more death, morbidity, and disability than all communicable diseases combined (Murray & Lopez, 1998).Injuries account for 1 in 7 potential life-years lost worldwide, but by 2020 they will account for 1 in 5, with the developing countries bearing the brunt of this increase (Vilardo, 1988;Zwi et al., 1996;Murray & Lopez, 1998).Injury control has gained attention and enormous support with the infusion of funding for injury control in developed countries and particularly the creation of the National Center for Injury Control and Prevention within the Centers for Disease Control and Prevention in the United States (Myers, 1992;Myers, 1997).During the last decade of the 20th century, workers in the US agriculture industry received particular attention because of the high risk of fatal injuries and suspected risk for serious nonfatal injuries (Aherin et al., 1992;Myers, 1998).', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04b8dcb1-8104-4678-b1e7-2c0645e0452d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Managing Feedlot Pen Dust', 'Alberta Agriculture and Forestry', 2020, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/03089181-3df9-4928-a3d9-2fc58c536e82', 'https://open.alberta.ca/dataset/03089181-3df9-4928-a3d9-2fc58c536e82/resource/236ce3ef-8821-4d37-9bbf-5195e3473013/download/af-managing-feedlot-pen-dust-2020.pdf', NULL, NULL, 4, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'Pen surface moisture and dust management in Alberta feedlots: stocking density, manure pack depth, watering and cleaning schedules. The dry-season counterpart to the mud problem the 2027 Code draft is adding a section on, and directly relevant to pen surface specification in a designer.', '{extension,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('42cc4bb0-adc5-4861-bc59-9f61b293a1f6', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Manure Management Regulations for Cow/Calf Producers (Agdex 096-6)', 'Alberta Agriculture and Food', 2007, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/a1c06d45-54a9-4f7c-893b-079b3ba208b1', 'https://open.alberta.ca/dataset/a1c06d45-54a9-4f7c-893b-079b3ba208b1/resource/0b6ae29f-70bf-4041-b6a5-66e73cdd475f/download/2007-096-6.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence - Alberta', 'The cow-calf-specific companion to Agdex 096-4. Sets out which AOPA manure requirements apply to a cow-calf operation as opposed to a confined feeding operation: runoff control at corrals and wintering sites, short-term field storage limits, setbacks, soil testing and record keeping, and the exemption for manure deposited by grazing livestock.', '{extension,standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa2fd1ed-764c-4a27-b8b7-22be52f08704', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Minimum facilities for beef cattle production', 'Harvey James Hirning', 1990, 'NDSU Repository (North Dakota State University)', NULL, 'http://hdl.handle.net/10365/17447', 'http://hdl.handle.net/10365/17447', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-sa', 'AE-986; Interpreting the concept of minimum facilities for beef production can produce a lot of variation. One person''s idea of minimum could be considered quite a luxury by someone else. In the context of this publication, minimum will mean some protection from the weather, a corral setup that will facilitate vaccination and dehorning, an ice-free water supply and feeding equipment.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1b555783-e9f1-489a-8d2c-a309bdade6f5', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Molecular Characterization of Escherichia coli O157:H7 Hide Contamination Routes: Feedlot to Harvest', 'Kirby D. Childs, Catherine A. Simpson, W. Warren-Serna, G. Bellenger, R. A. Bowling, John R. Ruby, J. Stefanek, D. J. Vote', 2006, 'Journal of Food Protection', '10.4315/0362-028x-69.6.1240', 'https://doi.org/10.4315/0362-028x-69.6.1240', 'https://mountainscholar.org/bitstreams/62700764-f9eb-4b4b-88cd-fa0db79da892/download', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('27486832-0a95-47f0-95e6-e5239d32c4cf', '0f560872-ad61-42ba-ad48-39b8582a7dfb', 'Crop Yield and Water Requirement Relationships for Major Irrigated Crops in Southern Alberta', 'D. Rodney Bennett, Ted E. Harms', 2011, 'Canadian Water Resources Journal / Revue canadienne des ressources hydriques', '10.4296/cwrj3602853', 'https://doi.org/10.4296/cwrj3602853', 'https://www.tandfonline.com/doi/pdf/10.4296/cwrj3602853?needAccess=true', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2857ce2d-640a-4741-9ae7-f694bb24a269', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'New Zealand Stockyard Loading Facility Guidelines, Version 1.0', 'National Livestock Transport and Safety Council (New Zealand)', 2025, 'National Livestock Transport and Safety Council / Transporting New Zealand', NULL, 'https://www.transporting.nz/', 'https://www.transporting.nz/wp-content/uploads/2025/09/Loading-Facilities-Version-1.0.pdf', NULL, NULL, 12, NULL, 'other', 3, 'Free industry guideline', 'The most recent (2025) codified loading-facility specification found, useful because it independently reproduces several of Grandin''s numbers from a completely different tradition and adds truck-access requirements. Cattle yard fencing must be at least 1.7 m high with a backrub indicator cross bar above, with extra height for cattle over 1.4 m at the hip. Ramp height 1.1-1.2 m with slope not exceeding 20 degrees; maximum slope must not exceed 20 degrees for all animals except young animals, for which ramps are discouraged and the maximum should be no greater than 12 degrees. Ramp flooring must be solid and non-slip. Personnel gates at the top of ramps must be self-closing and open onto a flat unobstructed area. Independently recommends aligning ramps north-south to avoid sun, matching Alberta''s advice. Access-road clearance 4.5 m high by 4 m wide, with a level firm truck pad and a marked no-go zone between reversing trucks and ramps.', '{design,loading-ramp,fence-height,sun-orientation,transport,recent}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('13957bec-e194-460f-85d1-ee57d8ecd854', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Non-slip flooring for livestock handling', 'Temple Grandin', 2015, 'grandin.com (author''s own design guidance pages)', NULL, 'https://www.grandin.com/design/non.slip.flooring.html', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Free on the author''s website; HTML only', 'The only source giving flooring groove patterns at a dimension a designer could draw. For BEEF CATTLE, a deep square pattern of 20 by 20 cm (8 by 8 in) squares with V-grooves at least 2.5 cm (1 in) deep and 2.5 cm wide. For high-traffic beef areas, metal grating in 30 by 30 cm (12 by 12 in) squares with rod at least 2.5 cm diameter. Concrete stair steps for cattle at 10 cm rise and 30-45 cm run with 2.5 cm groove depth. Non-adjustable loading ramps 20 degrees or less. Cleats must be spaced to fit the animal''s stride so a hoof cannot slip between them, with no numeric spacing given on this page (the 20 cm figure comes from Grandin 2008). Separate, smaller patterns are given for pigs and dairy cows and must not be applied to beef. No studies are cited on the page, so this is the author''s engineering judgement.', '{design,flooring,grooving,non-slip,stair-steps,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5563384b-307a-45d4-a6c1-dc629e27f77b', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Observations of cattle behavior applied to the design of cattle handling facilities', 'Temple Grandin', 1980, 'Applied Animal Ethology 6(1):19-31', '10.1016/0304-3762(80)90091-7', 'https://www.sciencedirect.com/science/article/abs/pii/0304376280900917', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Paywalled at Elsevier', 'Grandin''s first paper and the origin of the curved-race rationale, the solid-sides recommendation, and the circling and light-seeking behaviours that the whole design tradition rests on. Cited as the source for the 3.5-6 m curved race radius and for the tendency of cattle to move back in the direction from which they came, which is the mechanism behind both the Bud Box and the tub. It is an OBSERVATIONAL study, not a controlled comparison, which matters for how confidently the software can assert its derived rules. No free PDF located.', '{design,curved-race,observational,foundational,peer-reviewed,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('299a382e-7b32-4027-a9c6-3ea75c289da6', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Physiological and behavioural responses to short-haul transport by stock trailer in finished steers', 'M. E. Booth-McLean, K. S. Schwartzkopf-Genswein, F. A. Brown, C. L. Holmes, A. L. Schaefer, Tim Angus McAllister, G. J. Mears', 2007, 'Canadian Journal of Animal Science', '10.4141/a06-033', 'https://doi.org/10.4141/a06-033', 'https://cdnsciencepub.com/doi/pdf/10.4141/A06-033', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff5a8b70-6635-4370-92ad-0bb7cce80951', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Planning and Building Fences on the Farm (PB1541)', 'University of Tennessee Extension', 2020, 'University of Tennessee Institute of Agriculture Extension', NULL, 'https://utbeef.tennessee.edu/', 'https://utbeef.tennessee.edu/wp-content/uploads/sites/127/2020/11/PB1541.pdf', NULL, NULL, 18, NULL, 'other', 2, 'Free University of Tennessee Extension publication', 'Comprehensive farm fence handbook covering post types and sizes, embedment depth, brace assemblies, wire and board fences, gate hanging and corner construction. Checked specifically for a published structural design load for a handling-yard fence and it does not give one, which supports flagging the absence as a genuine gap rather than a search failure. Useful to the corral designer for post and brace selection once a layout is fixed.', '{design,fence,posts,bracing,construction}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6786997c-ad6e-45b9-a8a2-12c60b21efaf', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Planning and Constructing Fences (Handling Beef Cattle, Section 3)', 'University of Kentucky / Eden Shale Farm', 2015, 'Kentucky Beef Network, Eden Shale Farm', NULL, 'https://www.edenshalefarm.com/', 'https://www.edenshalefarm.com/uploads/2/1/0/9/21097014/planning_and_constructing_fences.pdf', NULL, NULL, 6, NULL, 'other', 2, 'Free Kentucky Beef Network / Eden Shale Farm publication', 'Section 3 of a beef-cattle handling manual, dealing with fence planning and construction around handling facilities, drawing on Midwest Plan Service MWPS-6 for its high-tensile fence data. Included for the fence-construction detail the designer will need once pen and alley geometry is settled, and as a further confirmation that design loads are not published in the extension literature.', '{design,fence,handling-facilities,construction}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ef1a395-99e5-45cd-ab0f-afb91890524f', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Portable Windbreak Fences (Agdex 711-1)', 'Alberta Agriculture, Food and Rural Development', 2002, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/0dac395d-099e-490a-a343-1026a6b99a6d', 'https://open.alberta.ca/dataset/0dac395d-099e-490a-a343-1026a6b99a6d/resource/58c9e457-e539-4295-8324-efbc0eda494f/download/2002-711-1.pdf', NULL, NULL, 8, NULL, 'alberta', 5, 'Open Government Licence - Alberta', 'Eleven buildable portable windbreak designs with construction callouts, plus the quantified case for building one. Porosity should be 25 to 33 per cent: 6 inch boards spaced 2 inches apart give 25 per cent and spaced 3 inches apart give 33 per cent, and the protected area extends 8 to 10 times the height of the fence downwind. Typical frame: slatted fence 25-30 per cent porous, 2 by 6 rough rails at 24 to 32 in, 6 in pipe skids with sand fill for ballast welded 18 in high so they do not become embedded, sway bracing every 24 ft, a steel pipe sub-frame and a 4 in steel pipe main post, with an optional 8 ft wing extension. One slanted-wall unit is recorded as having overturned in a 90 km/h wind. Table 1 gives the digestible energy requirement of a 1300 lb large-frame cow at mid pregnancy under three wintering treatments: 20.7, 26.1 and 31.6 Mcal per day at 0 C and 26.9, 32.3 and 37.8 at minus 30 C, on an average December wind of 17.3 km/h reduced to 5.0 km/h behind the fence.', '{plan,extension,windbreak}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7febf50b-3e6a-4b9a-9451-a88b74ac9eb1', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'PREDICTING MATERNAL BEHAVIOUR OF BEEF CATTLE USING TEMPERAMENT TESTS', 'Brooke L Aitken', 2011, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-03162011-133916', 'https://harvest.usask.ca/bitstreams/74101a8c-b4dc-4e1b-a7f3-402a16da9705/download', NULL, NULL, 104, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8e7a121a-f043-4670-892d-fd0b052dab6f', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Race system for cattle slaughter plants with 1.5 m radius curves', 'Temple Grandin', 1984, 'Applied Animal Behaviour Science 13(3):295-299', '10.1016/0168-1591(84)90022-2', 'https://www.sciencedirect.com/science/article/abs/pii/0168159184900222', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Paywalled at Elsevier', 'The ONE peer-reviewed measured result behind the tight-radius and straight-entry rules, and therefore the highest-confidence geometry citation in the whole literature. Shows that a race with an inner radius as small as 1.5 m works IF it is built as a continuous smooth curve and IF there is a straight single-file section of at least 3 m joining the race to the crowd pen - without which the entrance looks like a dead end. Grandin 1997 adds the corollary that ''cattle will get stuck if it is built in a series of straight sections''. The work was done in slaughter plants, so transfer to a ranch corral is an assumption, but it is the only number in the corner-and-radius family with a methods section behind it.', '{design,curve-radius,straight-entry,dead-end,peer-reviewed,measured,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('47a07bc4-4f09-45db-9c7f-ba1ce6c9b619', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Review of Provincial Involvement in Livestock Welfare Protection in Alberta', 'Government of Alberta', 2008, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/14797a0c-2260-47a8-8696-fa90a678ef6b', 'https://open.alberta.ca/dataset/14797a0c-2260-47a8-8696-fa90a678ef6b/resource/b7fd37e9-2912-4f08-8556-cb4bf74b1766/download/0163210417883-review-of-provincial-involvement-in-livestock-welfare-protection-in-alberta.pdf', NULL, NULL, 88, NULL, 'alberta', 2, 'Open Government Licence - Alberta', 'A provincial review of how livestock welfare is protected and enforced in Alberta, and where the national Codes of Practice sit within that machinery. Background for anyone deciding how hard the software should assert a Code clause.', '{standard,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6583afa3-f334-40f1-a312-9e5e62a8ae1d', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Service de plans canadiens plan M-1800 (French): Installations de manutention des bovins', 'Service de plans canadiens / Canada Plan Service', 1986, 'Canada Plan Service (archived from cps.gov.on.ca)', NULL, 'http://www.cps.gov.on.ca/french/Plans/F1000/1800/M-1800L.pdf', 'https://web.archive.org/web/20061219033909id_/http://www.cps.gov.on.ca/french/Plans/F1000/1800/M-1800L.pdf', NULL, NULL, 7, NULL, 'canada', 4, 'Free distribution; Canada Plan Service co-operative', 'The French edition of Canada Plan Service plan M-1800, Cattle Handling Facilities - a second verified copy of the single most important dimension sheet in this collection, carrying the same Table 1 of recommended dimensions for beef cattle corrals and handling facilities.', '{plan,extension,facilities}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('50bedbb6-14b0-4e8c-b8a4-f849bc5c3a0a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Short communication-characterizing heart rate of beef cattle during stunning and exsanguination at slaughter', 'Edwards-Callaway L, Loh HY, Rimm-Kaufman D, Nair M, Engle T, Delmore R, Belk K', 2026, 'Journal of animal science', '10.1093/jas/skag207', 'https://doi.org/10.1093/jas/skag207', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13502966.1/PMC13502966.1.pdf', NULL, NULL, 7, NULL, 'northern_plains', 3, 'cc by-nc', 'The objective of this study was to evaluate the changes in heart rate (HR) during stunning and exsanguination in slaughter-weight cattle stunned one (Experiment 1) or two (Experiment 2; one initial and one security stun) times with a penetrating captive bolt gun. Data were collected between April 2025 and April 2026. In Experiment 1, 21 steers (n = 21; BW = 662 ± 65 kg) were used, and in Experiment 2, 5 steers and 4 heifers (n = 9; BW = 666 ± 72 kg) were used. All cattle were fitted with a HR monitor while restrained in a hydraulic squeeze chute and were transported to the university processing facility for slaughter. In both experiments, cattle were stunned (time 0 s) and rendered insensible with a pneumatic penetrating captive bolt stunner. Experiment 1 utilized one stun, and Experiment 2 implemented a secondary security stun (with a handheld captive bolt stunner) approximately 20 s after the first stun. HR was recorded from 60 s prior to stunning until 10-15 min post-stunning. Data were aggregated into 1-s intervals. Prior to stunning (-60 s - 0 s), HRs in both Experiments were elevated compared to typical resting HR in cattle, with an average of 141 beats per minute (bpm) in Experiment 1 and 120 bpm in Experiment 2. Immediately following captive bolt administration, HR increased rapidly, reaching an average peak of 165 bpm within approximately 12 s in both Experiments. After that, HR decreased, reaching a low near exsanguination and then peaked a second time (134 bpm at approximately 4 min post-stun and 120 bpm at approximately 2.7 min post-stun in Experiments 1 and 2, respectively). HR steadily declined as animals approached clinical death, reaching a plateau of 30-40 bpm at approximately 9 min post-stun, the bpm likely representing residual electrical impulse activity of the heart. Overall, the results provide a clear indication of HR in cattle under slaughter conditions and are relevant to discussions around the timing of cardiac death in cattle.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('af13ef6b-5376-4292-aeab-99c4fa6bd85a', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Subjective Measures of Temperament in Beef Heifers Are Reliable Indicators of Physiological Stress and Indicate Acclimation to Repeated Handling', 'Jamie T. Parham', 2018, 'Lincoln (University of Nebraska)', NULL, 'https://digitalcommons.unl.edu/animalscidiss/167', 'https://digitalcommons.unl.edu/cgi/viewcontent.cgi?article=1178&context=animalscidiss', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f0a87142-60c1-4fa7-b2fe-c2fd6fb40706', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Temperature and humidity index (THI) affects salivary cortisol (HC) and dehydroepiandrosterone (DHEA) concentrations in growing bulls following stress generated by performance test procedures', 'Giaretta E, Mongillo P, Da Dalt L, Gianesella M, Bortoletti M, Degano L, Vicario D, Gabai G', 2023, 'Frontiers in veterinary science', '10.3389/fvets.2023.1237634', 'https://doi.org/10.3389/fvets.2023.1237634', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10407106.1/PMC10407106.1.pdf', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'The hypothalamus-pituitary-adrenal axis response to a challenge was proposed for genetic selection of robust and resilient animals. As ACTH (adrenocorticotropic hormone) test and hormone measurements in blood may result impractical, it may be useful to measure salivary hormones in response to natural stressors, after an accurate biological validation, to control factors that could contribute to the response. We evaluated whether animal handling during performance test affects salivary HC and DHEA secretion and could be used for selection. We tested the effects of habituation to repeated handling and THI as putative bias. Bull calves (N = 273) undergoing performance test were sampled at 8-9 and 11-13 months (N = 101), 8-9 months (N = 131), or 11-13 months (N = 41). On each test day (D0), calves were isolated, conducted to a squeeze chute and immobilized for 6 min. Saliva samples were collected in the morning after feed administration (T0), and after 6 min immobilization in the squeeze chute (T1) for HC and DHEA measurement. Environmental temperature and relative humidity were recorded every hour from 1:00 h to 24:00 h during the 6 days before the performance test and on D0. Salivary HC and DHEA concentrations were higher in T1 (p p p p p ρ = 0.150, p ρ = 0.316, p ρ = 0.353, p < 0.001). Salivary HC and DHEA in response to handling procedures might identify subpopulations of subjects with sensitive HPA axis. Habituation to repeated handling played a role, as the hormone response was lower in older animals. Chronic exposure to high THI had a minor effect on salivary HC visible at T0. A more intense THI effect was observed on salivary DHEA concentrations at both T0 and T1, which should be worth of further investigations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2d4e1645-1561-49fe-8fe4-2a64f3875c29', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The Beef Cow-calf Manual (Agdex 420/10), Section 08: Handling Facilities and Fencing', 'Alberta Agriculture and Food', 2008, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/publications/the-beef-cow-calf-manual', 'https://open.alberta.ca/dataset/6840d8ec-4fe5-41a1-9b67-a5ca909f23cb/resource/d6bfc3bf-b1a3-4e17-8423-874c9ef4f600/download/4075690-2008-beef-cow-calf-manual-agdex-420-10.pdf', NULL, NULL, 302, NULL, 'alberta', 5, 'Open Government Licence - Alberta', 'Alberta''s cow-calf production manual. Section 08 (pp.249-272) is the most recent provincial statement of corral dimensions and the source the app should cite, because its tables are explicitly adapted from Canada Plan Service M-1800 and CPS 1000 and from Borg et al. (1993). Table 69, Recommended dimensions for beef cattle corrals and handling facilities, with the instruction that cow-calf operations should use the over-1200 lb column: holding area 14, 17, 20 sq ft per animal worked immediately and 45, 50, 60 held overnight; vertical-sided working chute width 18, 22, 28 in with a desirable length of 24 ft; sloping-sided chute 22 in at the bottom and 32 in at 5 ft; working chute and feedlot line fences 5 ft high on posts 3 ft deep; corrals and bull pen fences 5 ft high on posts 4 ft deep; loading chute 30-32 in wide, 12 ft minimum length, slope 1 to 4; ramp heights of 15 in for a gooseneck trailer, 28 in for a pickup, 40 in for a van-type truck, 48 in for a tractor trailer (printed as 248, a typesetting error) and 100 in for a double deck; access or collecting alley 12 ft. Table 70 gives housing guidelines adapted from CPS 1000: soil pen 300 sq ft per cow, paved 80 without a shed or 50 with, bedded mound 35, shed floor 30 sq ft with 10 ft clearance, maternity pens 10 by 10 ft one per 20 cows, water surface 4 sq ft per 100 head and 11 gallons per 1100 lb daily rising to 16 in hot weather, bunk length 26-30 in limit fed and 8 in self fed with a 22 in throat height and 34 in maximum reach, concrete slopes of 2-4 per cent and soil 4-8 per cent, mounds at 1 to 4. Tables 71 to 73 give the geometry for laying out circular working chutes (radius, post spacing, section count, inside width for 28 and 32 in chutes) and circular crowding tubs (tub radius for 8 to 16 ft gates at 4 ft and 6 ft post spacing). Table 74 is a 21-item corral design checklist including alleys no wider than 20 ft, at least two sorting corrals at 60 and 40 per cent of the holding corral area, no right-angle corners, no dead-end or unlit chute, a power outlet at the squeeze and yard lights out of cattle reach. Narrative additions: fences at least 6 ft high with 12 in of free space at the bottom; long narrow holding pen 18-20 ft wide; crowding gate usually 12 ft swinging 180 to 300 degrees; three sorting corrals for most cow-calf operations; chute catwalk minimum 18 in, 36-42 in below the top; chute 20-50 ft long on a 16-25 ft radius; loading alley no longer than two animal lengths with two or three 15 degree dog-leg curves about 2 ft in 8 ft; ramp 30-35 in single file or 54-72 in for groups and about 16 ft long with a 5 ft landing; a 2 ft veterinary access gate behind the squeeze; sick pens of 15-20 sq ft of shelter plus 40-60 sq ft of pen per head for 5 per cent of the herd; and windbreak fences 20-30 per cent open, at least 8 ft high, with pens 100-150 ft downwind.', '{plan,extension,facilities,handling,loading,weaning}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d47e0e62-119e-4ae6-a6e5-ea2b7f9ffed7', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The behaviour and movement of cattle through forcing yards', 'W. J. Vowles, G. A. Eldridge and T. J. Hollier', 1984, 'Proceedings of the Australian Society of Animal Production 15:766', NULL, 'http://livestocklibrary.com.au/handle/1234/5258', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Conference proceedings, not online', 'The measured basis for SOLID crowd pen sides - arguably better supported than the curve itself. Grandin (1997) reports: ''Cattle moved faster through a crowd pen with solid fences compared to one with a pipe fence or partially open-board fence (Vowles et al., 1984b)'', and separately that ''some types of cattle move more slowly when they walk straight through the crowd pen into the single-file race'', which is the measured argument for a round rather than straight-through forcing pen. A one-page conference abstract, so the same caveat applies, but this is the one crowd-pen recommendation with a measurement behind it rather than practical experience.', '{design,crowd-pen,solid-sides,conference-abstract,measured,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c7a1eae-070f-49b0-be15-458394f35557', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The behaviour and movement of cattle through single file handling races', 'W. J. Vowles, G. A. Eldridge and T. J. Hollier', 1984, 'Proceedings of the Australian Society of Animal Production 15:767', NULL, 'http://livestocklibrary.com.au/handle/1234/5258', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Conference proceedings, not online', 'THE CONTRARY EVIDENCE, and the reason the corral designer must not warn that a straight race is a design fault. Grandin (1997) reports it as follows: ''Experiments with continuously moving livestock indicated no significant difference between straight and curved races for run-through time (Vowles et al., 1984a).'' In other words the curved race advantage, as measured, applies only when cattle queue for a procedure - exactly the Vowles and Hollier 1982 condition - and vanishes when cattle move through continuously. Like the 1982 paper this is a one-page abstract and no replication of it was found. Together the two abstracts are the entire measured basis for the curved-race convention.', '{design,curved-race,no-difference,conference-abstract,contrary-evidence,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7ca94a6f-c68d-4b38-a836-85575b7c5f27', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The design and construction of facilities for handling cattle', 'Temple Grandin', 1997, 'Livestock Production Science 49(2):103-119', '10.1016/S0301-6226(97)00008-0', 'http://www.grandin.com/references/design.construction.facilities.handling.cattle.html', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Paywalled at Elsevier; full text posted by the author at grandin.com', 'THE single most important citation for the corral designer, and the source of nearly every number in the geometry rules. Race width 66-71 cm adult cows and 51 cm calves with only 2 cm clearance per side of the largest cow; V race 41-45 cm at the bottom and 81 cm at the 152 cm level; minimum race length 9 m; curved race inner radius 3.5-6 m with 6 m preferred for rapid in-race vaccination; a 3 m straight section required at the crowd-pen junction if the inner radius is under 3 m; crowd gate 3.5 m ideal and 3 m for smaller operations; funnel crowd pen one side straight and one at 30 degrees; fence height 152 cm English and tame breeds, 167-183 cm Brahman cross and excitable Continental lines; post spacing 1.2 m on wood or concrete curved races; walkway platform 100 cm below the top of the race fence; man gates 45 cm; ramp 76 cm single file for adult cows, 2.5-3 m for unloading only; stair steps 30 cm tread and 10 cm rise; floor grooves 2.5-5 cm deep in a 20 cm square or diamond pattern; belly rail 30-60 cm wide at cow eye height. Crucially for honest software, it reports the contrary evidence: ''Experiments with continuously moving livestock indicated no significant difference between straight and curved races for run-through time (Vowles et al., 1984a)''. It also states the corner rule qualitatively - curved lanes and diagonal pens ''eliminate square corners'', round pens have ''no square corners for cattle to bunch up in'', and diagonal gates 4.2 m on a 3.5 m lane work ''because gates opening on an angle eliminate sharp corners''. No maximum corner angle is given anywhere in it.', '{design,curved-race,corner-angles,race-width,crowd-pen,peer-reviewed,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5dc8cc31-22b1-435a-ab57-6a1b080d788f', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'The Visual, Auditory, and Physical Environment of Livestock Handling Facilities and Its Effect on Ease of Movement of Cattle, Pigs, and Sheep', 'Temple Grandin', 2021, 'Frontiers in Animal Science', '10.3389/fanim.2021.744207', 'https://doi.org/10.3389/fanim.2021.744207', 'https://www.frontiersin.org/articles/10.3389/fanim.2021.744207/pdf', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc-by', 'The visual, auditory, and physical environment livestock are handled in will have an effect on the ease of movement through races and corrals that are used for veterinary treatment, loading trucks or at slaughter houses. When livestock refuse to move easily through a handling facility, people are more likely to use electric goads (prods) or other aversive methods to move them forward. This is a major animal welfare concern. Modification of the environment can improve livestock movement and reduce aversive handling methods. In existing facilities used for handling cattle, pigs or sheep, simple changes such as, adding a light to a dark race entrance or reducing loud intermittent noise may improve livestock movement. Eliminating distractions such as, a noisy truck near a lairage can also facilitate cattle movement and reduce stopping or turning back. In an outdoor facility, sharp shadows on the floor were more likely to be associated with cattle stopping compared to no shadows or soft faint shadows. The installation of small solid walls to prevent approaching animals from seeing either moving equipment, vehicles or people in front of them may also improve forward livestock movement. Non-slip flooring is essential to prevent slipping and falling during handling. Rebuilding or completely redesigning an existing facility is often not required. Outcome based indicators should be used to assess continuous improvements in handling. Some of the commonly used measurable of handling are slipping and falling, stopping, turning back, vocalization during handling and electric prod use. Collecting data both before and after an environmental modification can be used to determine its effectiveness.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06951b0b-22d9-4160-a436-0781892ac0b3', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Time of onset, location, and duration of lameness in beef cattle in a commercial feedyard', 'T.M. Green, P. Timothy Guichon, Daniel U. Thomson, Benjamin W. Wileman, Christopher D. Reinhardt', 2012, 'Kansas Agricultural Experiment Station Research Reports', '10.4148/2378-5977.1410', 'https://doi.org/10.4148/2378-5977.1410', 'https://krex.k-state.edu/bitstreams/9e69e6f8-20c8-412f-ac9b-bcefe74cf078/download', NULL, NULL, 4, NULL, 'other', 1, 'cc-by', 'Bovine lameness presents itself in a variety of forms. A number of predisposing factors have been reported, such as increased amounts of wet feces and mud from high rainfall; limb trauma from rocks, sticks, or handling facilities; inappropriate animal handling; or improper facility design. Trauma causes lameness directly and often provides an avenue for bacterial agents to enter and colonize a wound. Performance of lame cattle is diminished due to impaired ambulation, resulting in decreased feed intake and decreased body weight. The objective of this study was to determine the timing of the onset of lameness in feeder cattle and to determine the association between lameness and feedlot performance.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('24888893-8bcf-46cc-819a-8c65517bde74', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Timeline for Codes of Practice Being Amended or Updated (May 2026)', 'National Farm Animal Care Council', 2026, 'NFACC', NULL, 'https://www.nfacc.ca/codes-of-practice/beef-cattle', 'https://www.nfacc.ca/pdfs/nfacc_code_development_timeline_may%202026_EN.pdf', NULL, NULL, 1, NULL, 'canada', 3, 'Publicly available; copyright NFACC', 'NFACC''s schedule for every Code of Practice under amendment or update as at May 2026. Confirms the beef cattle Code is in revision with an estimated completion in 2027, and sets out the process: stakeholder survey, Scientific Committee report, draft Code, 60-day public comment period, review of feedback, final approval and publication. New or updated Codes take at least two years; amendments generally a year or less. Use it to date-stamp anything the app quotes from the 2013 edition.', '{code-of-practice,standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('716bf08a-f5bd-485b-94bf-a2dd5b5ae8ca', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Traceability in Alberta: Best Practices for RFID Ear Tag Application (Agdex 420/26-1)', 'Alberta Agriculture and Forestry', 2016, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/bd20af58-aa4f-4ef9-8fca-5a03a57f8179', 'https://open.alberta.ca/dataset/bd20af58-aa4f-4ef9-8fca-5a03a57f8179/resource/d64fa5af-2c6c-4153-9f39-5301e83edbb7/download/agdex-420-26-1-revised-nov-2016.pdf', NULL, NULL, 3, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'What has to happen at the chute for mandatory traceability: correct RFID tag placement, retention, readers, and the restraint needed to tag safely. Directly informs the equipment and working-room allowance at a squeeze station, and connects to Code of Practice section 4.3 Identification.', '{extension,handling}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('89a993ce-1dc0-4981-83e6-b3773d54d4e5', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Understanding Flight Zone and Point of Balance for Low Stress Handling of Cattle, Sheep, and Pigs', 'Temple Grandin', 2022, 'grandin.com (author''s own behaviour pages, updated July 2022)', NULL, 'https://www.grandin.com/behaviour/principles/flight.zone.html', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Free on the author''s website; HTML only', 'The reference for the two behavioural quantities a corral designer needs in order to place catwalks, man gates and handler positions. The point of balance is at the SHOULDER for cattle confined in a single-file race, but may move forward to just behind the eye for cattle at liberty on pasture or in large pens - so the same diagram does not apply in both places. Behind the point of balance the animal moves forward; ahead of it, it backs up, and standing ahead of it while trying to drive an animal forward in a race is named as a common handler mistake. Groups in a race often move forward without prodding when the handler walks past each animal''s point of balance in the OPPOSITE direction of travel, which is the behavioural justification for a catwalk on the inner radius. Flight zone size varies with tameness, excitement and angle of approach, is larger on a head-on approach, and is zero in completely tame animals; Grandin''s published ranges elsewhere are 2-8 m for feedlot cattle and up to 50 m for extensively raised cows.', '{design,flight-zone,point-of-balance,catwalk-placement,handling-technique,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa32aa67-dc28-45fc-b15c-b9fa603ee725', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Validating the use of pen scores to capture behaviors expressed by cattle unrestrained in a pen', 'Parham JT, Schmidt JJ, Tanner AE, Wahlberg ML, Grandin T, Lewis RM', 2025, 'Journal of animal science', '10.1093/jas/skaf026', 'https://doi.org/10.1093/jas/skaf026', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11912831.1/PMC11912831.1.pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Many subjective methods exist to assist producers in evaluating temperament. Use of a pen test, which allows behavior to be observed in a nonrestrained setting, may be an effective method to evaluate temperament by allowing more variation among animals to be expressed as compared to a restrained test. The objective of this study was to analyze video recordings of penned calves to determine whether the repertoire of behaviors they expressed was adequately captured by their individual pen score (IPS) and group pen score (GPS). In each of 3 yr, 40 predominantly Angus commercial Bos taurus heifers, 2-wk postweaning , were assessed monthly in 3 consecutive months (recording periods). After routine handling through a weigh crate and squeeze chute, each heifer was released individually into a pen (12 × 6 m). Their response to 30 s of human presence within the pen was evaluated. They were then joined in groups of four in a larger (12 × 8 m) pen and re-evaluated for 30 s in a group setting. An IPS and GPS were assigned using an ethogram, with scores ranging from 1 (docile) to 6 (aggressive). This interaction was also video recorded. Using the videos, the explicit behaviors captured by each pen score were investigated using Noldus Observer software. Data were analyzed with ANOVA using SAS. Within each recording period, the concordance of pen scores with the repertoire of behaviors expressed was compared. In the group setting, heifers could not be clearly distinguished on video and were instead assigned the average GPS of the group. Heifers with higher IPS and average GPS categories had larger flight zone sizes and reached faster paces for longer periods of time. Furthermore, heifers with lower IPS appeared more neutral to the presence of a human and moved around less often. Ethograms for pen score successfully delineated the temperament of heifers. The use of such scores can provide a valuable on-farm assessment of cattle behavior during routine handling.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a34d1444-7088-45d6-b143-3c481c9f6693', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Welfare requirements of handling facilities', 'Temple Grandin', 1983, 'In: S. H. Baxter, M. R. Baxter and J. A. C. McCormack (eds), Farm Animal Housing and Welfare, Martinus Nijhoff', NULL, 'https://link.springer.com/book/10.1007/978-94-009-6834-6', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Paywalled book chapter', 'The citation Grandin gives for two rules a corral designer must enforce geometrically. First, the maximum recommended steepness for a stationary cattle ramp of 20 degrees for market-weight animals. Second, and less widely known, that a CROWD PEN MUST NEVER BE BUILT ON A RAMP - ''a sloped crowd pen will cause livestock to pile up against the crowd gate'' - with 10 degrees named as a slope to avoid. The crowd pen must be level except for a slight drainage slope. Both are design recommendations rather than measured results, but the crowd-pen-level rule is one of the few that is easy for software to check and expensive for a rancher to get wrong.', '{design,crowd-pen,slope,loading-ramp,book-chapter,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('404f628a-79ee-490f-91bb-451c6d70dc97', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'What Are My Fencing Obligations?', 'Alberta Agriculture and Irrigation, Farmers'' Advocate Office', 2025, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/publications/what-are-my-fencing-obligations', 'https://open.alberta.ca/dataset/5caf134a-78c5-4952-8a18-9da6bba06b61/resource/360bd35f-84dc-44d7-b325-a5f71a5c5fce/download/agi-fao-fencing-obligations-2025.pdf', NULL, NULL, 5, NULL, 'alberta', 3, 'Open Government Licence - Alberta', 'The Farmers'' Advocate Office guide to Alberta fencing law: the Line Fence Act, the Stray Animals Act, what counts as a lawful fence, who pays for a boundary fence and how disputes are resolved. Relevant whenever the designer puts a corral, a weaning fence or a holding pen on or near a property line.', '{extension,standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('09af6eda-5fa8-4fc7-b097-d6faa4fa10bf', '8292e9dc-456f-451e-bd90-7e6be6f2c8e1', 'Wintering sites and livestock corrals', 'Government of Alberta', 2007, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/wintering-sites-and-livestock-corrals', 'https://open.alberta.ca/dataset/9db997f1-880a-439e-b893-7483c5b30bdc/resource/72ce13e5-dbd2-40ca-9fb7-989c03fd24b7/download/0163040746311-wintering-sites-and-livestock-corrals.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document presented guidance on wintering sites and livestock corrals under the Agricultural Operation Practices Act (AOPA) and described requirements for manure management, setback distances, runoff reduction, short‑term solid manure storage, record keeping and enforcement. It outlined definitions, expectations for minimizing risks to common bodies of water, options when setback distances were not met and standards for managing manure on various land slopes. It also summarized obligations for soil testing, manure application limits, documentation and compliance monitoring by the Natural Resources Conservation Board. The document provided practical instructions to help producers operate in an environmentally sustainable manner while meeting provincial legislation.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('98a10c0c-07bb-4430-ab09-4d02dc07c38a', '0f560872-ad61-42ba-ad48-39b8582a7dfb', 'Culture-Based Assessment of Microbial Communities in Soil Suppressive to Potato Common Scab', 'Qingxiao Meng, Jingfang Yin, Noah Rosenzweig, David S. Douches, Jianjun J. Hao', 2011, 'Plant Disease', '10.1094/pdis-05-11-0441', 'https://doi.org/10.1094/pdis-05-11-0441', 'https://apsjournals.apsnet.org/doi/pdf/10.1094/PDIS-05-11-0441', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c1bcc62a-05e8-46d1-8123-dcf6f5f2c7f6', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'A Method to Quantify the Detailed Risk of Serious Injury in Agricultural Production', 'Noha Mahmoud, Allan Leck Jensen, K. Topp, Claus Aage Grøn Sørensen, Michael Nørremark, Vera Eory, Nicholas John Hutchings', 2021, 'Sustainability', '10.3390/su13073859', 'https://doi.org/10.3390/su13073859', 'https://www.mdpi.com/2071-1050/13/7/3859/pdf?version=1617938745', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Agricultural injuries are a valuable social sustainability indicator. However, current methods use sector-scale production data, so are unable to assess the impact of changes in individual farming practices. Here, we developed a method that adopts a life cycle approach to quantify the number of serious injuries during agricultural production processes and assess the potential impact of changes in agricultural practices. The method disaggregates agricultural production into operations and estimates the contribution each operation makes to the frequency of different types of injuries. The method was tested using data collected by survey during an expert workshop in which sixteen participants were asked to estimate the parameters related to typical dairy cattle and pig farms. Parameter estimates for specific operations varied considerably between participants, so normalized values were used to disaggregate sector-scale statistics to production operations. The results were in general agreement with the results from other studies. Participants found it challenging to quantify the potential effect of new technologies. Provided suitable empirical statistical data are available, the method can be used to quantify the risk of injury associated with individual products and provide an ex-ante assessment of future developments in farming practices.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('00af5a35-1bc5-4a6d-9e3d-9dbfdf0e5a99', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'A Review of Avian Influenza Virus Exposure Patterns and Risks Among Occupational Populations', 'Li H, Ren R, Bai W, Li Z, Zhang J, Liu Y, Sun R, Wang F', 2025, 'Veterinary sciences', '10.3390/vetsci12080704', 'https://doi.org/10.3390/vetsci12080704', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12390217.1/PMC12390217.1.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Avian influenza viruses (AIVs) pose significant risks to occupational populations engaged in poultry farming, livestock handling, and live poultry market operations due to frequent exposure to infected animals and contaminated environments. This review synthesizes evidence on AIV exposure patterns and risk factors through a comprehensive analysis of viral characteristics, host dynamics, environmental influences, and human behaviors. The main routes of transmission include direct animal contact, respiratory contact during slaughter/milking, and environmental contamination (aerosols, raw milk, shared equipment). Risks increase as the virus adapts between species, survives longer in cold/wet conditions, and spreads through wild bird migration (long-distance transmission) and live bird trade (local transmission). Recommended control measures include integrated animal-human-environment surveillance, stringent biosecurity measures, vaccination, and education. These findings underscore the urgent need for global ''One Health'' collaboration to assess risk and implement preventive measures against potentially pandemic strains of influenza A viruses, especially in light of undetected mild/asymptomatic cases and incomplete knowledge of viral evolution.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('524c3f63-8c76-4c92-985e-7abcf27358dd', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agricultural Fatalities and Hospitalizations in Ontario 1990–2004', 'Canadian Agricultural Injury Surveillance Program (CAISP) / Canadian Agricultural Safety Association', 2007, 'Canadian Agricultural Injury Reporting (CAIR), CASA', NULL, 'https://casa-acsa.ca/en/cair/reports/', 'https://www.casa-acsa.ca/wp-content/uploads/ontfull.pdf', NULL, NULL, 106, NULL, 'canada', 4, 'publisher PDF, free to read (© Canadian Agricultural Safety Association)', 'Provincial surveillance reporting fatalities and hospitalizations on the same population, which exposes how much fatality counts understate animal injury. Animal-related events caused 5.7% of Ontario agricultural fatalities (fourth-ranked) but 13.8% of hospitalized agricultural injuries, the second leading cause after machine entanglements. By age, animal events caused 12.0% of hospitalizations in children under 16, 14.2% in adults 16-64 and 14.0% in adults 65 and over. Among fatalities in adults 65+, being struck by an animal was the third leading cause at 10.1%.', '{safety,injury-epidemiology,hospitalization,canada,cair,fatal-vs-nonfatal}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('93cb91ff-0fe9-405e-90d8-0c901f4870c9', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agricultural health in The Gambia II: A systematic survey of safety and injuries in production agriculture.', 'Rex A. Kuye, Kelley J. Donham, Shannon P. Marquez, Wayne T. Sanderson, Laurence J. Fuortes, Risto Heikki Rautiainen, Martin L. Jones, Kennith R. Culp', 2006, 'PubMed', NULL, 'https://ir.uiowa.edu/nursing_pubs/224', 'https://ir.uiowa.edu/nursing_pubs/224', NULL, NULL, 10, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b67364bf-85f4-4045-9a78-73de8449d091', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agricultural injuries among central state region operators over a 5-year period: CS-CASH Farm and Ranch Health and Injury Survey 2011-2015', 'Anthony Johnson', 2020, 'DigitalCommons@UNMC', NULL, 'https://digitalcommons.unmc.edu/coph_slce/129', 'https://digitalcommons.unmc.edu/cgi/viewcontent.cgi?article=1128&context=coph_slce', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8d86e3dc-e276-4077-9c20-ae1e676510bd', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of weaning management strategies on performance and health of calves during feedlot receiving', 'Boyles, S.L.; Loerch, S.C.; Lowe, G.D.', 2007, 'The Professional Animal Scientist 23(6):637-641', NULL, 'https://www.appliedanimalscience.org/', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Subscription (American Registry of Professional Animal Scientists / Elsevier)', 'The source of the most widely quoted health claim for fenceline weaning: fence-line weaned calves were treated about half as often as abruptly weaned calves during feedlot receiving, with improved gains. Cited by the Beef Cattle Research Council for exactly that figure. Treat with care - the effect size is only available second-hand, and three more recent trials (Taylor 2020, Bailey/Olson, Gubbels 2023) all failed to detect health differences because their calves were too healthy. This remains the single best-cited morbidity number for fenceline weaning, which is itself a statement about how thin the health evidence is.', '{weaning,fenceline,BRD,morbidity,receiving,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa126522-9553-4580-bda1-38f9f514565b', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Low Stress Livestock Handling', 'Manitoba Agriculture (Manitoba Agriculture, Food and Rural Initiatives)', 2010, 'Government of Manitoba, Agriculture', NULL, 'https://www.gov.mb.ca/agriculture/livestock/beef/low-stress-livestock-handling.html', 'https://manitoba.ca/agriculture/livestock/beef/pubs/low-stress-livestock-handling.pdf', NULL, NULL, 8, NULL, 'prairies', 4, 'Government of Manitoba publication, free to read', 'A prairie-province extension guide built around a hazard table from the Institute of Agricultural Rural and Environmental Health in Saskatchewan. States that a cow sees nearly 90 percent of the area around her and that the only dead spot is directly behind her between the hips, and that the most common handler mistake is inadvertent entry into that blind spot, which makes cattle stop and ''hook''. Warns that aggression in cattle can be triggered by yelling, whistling, erratic movements and waving arms, and never to turn your back on an aggressive or anxious animal. Recommends filling a crowd pen only one-third to one-half full so cattle can find the exit, and lists seven causes of handling problems including too many animals in the crowding pen and handlers frightening the animals.', '{safety,flight-zone,crowd-pen,low-stress,handling-behaviour,prairies}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d39caf2-72c5-406d-b6cf-a01402bf44a4', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agricultural Injuries in Canada for 1990–2000 (National Report: fatalities and hospitalizations)', 'Canadian Agricultural Injury Surveillance Program / CAIR, Canadian Agricultural Safety Association', 2003, 'Canadian Agricultural Injury Reporting (CAIR), CASA', NULL, 'https://casa-acsa.ca/en/cair/reports/', 'https://www.casa-acsa.ca/wp-content/uploads/Agricultural-Injuries-in-Canada-for-1990-2000.pdf', NULL, NULL, 194, NULL, 'canada', 5, 'publisher PDF, free to read (© Canadian Agricultural Safety Association)', 'The richest Canadian source because it reports fatalities and hospitalizations side by side. 77 animal-related agricultural deaths (6.1% of all agricultural fatalities) in 1990-2000, of which 37.7% involved horses, 32.5% bulls and 19.5% cows; by task, 29.9% were working with a bull or with other animals near a bull and 9.1% were calving. Separately, 2,800 hospitalized non-machine agricultural injuries involved animals (April 1990-March 2000) against a farm population denominator of 842,595: cattle 1,136, horses 1,111, bulls 186, calves 143, with cattle and horses causing 92% of the total and 67.2% of animal hospitalizations in adults 60+ caused by cattle. Cattle injuries peaked March-May (calving) and bull injuries peaked in August. 18 of 20 (90%) corral/animal-pen fatalities occurred at the scene, the highest at-scene proportion of any farm location.', '{safety,injury-epidemiology,hospitalization,canada,cair,bull,calving,corral}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd9ebba8-0722-4ebc-a30c-a05f6f2b636b', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agricultural-related Fatalities in Canada, 2003–2012', 'Canadian Agricultural Injury Reporting (CAIR) / Canadian Agricultural Safety Association', 2016, 'Canadian Agricultural Injury Reporting (CAIR), CASA', NULL, 'https://casa-acsa.ca/en/cair/reports/', 'https://www.casa-acsa.ca/wp-content/uploads/CASA-CAIR-Report-English-FINAL-Web.pdf', NULL, NULL, 44, NULL, 'canada', 4, 'publisher PDF, free to read (© Canadian Agricultural Safety Association)', 'National Canadian fatality surveillance for 2003-2012 covering 843 agriculture-related deaths. Animal-related events caused 65 fatalities, 8% of the total: 54% (35) involved horses and 45% (29) involved cows, bulls, steers or calves. Of the 35 horse deaths only 22 (59%) were work-related and 14 (38%) were recreational riding, so the apparent horse dominance in Canadian animal-fatality data is partly a recreation artefact while the cattle share is essentially all occupational.', '{safety,injury-epidemiology,fatality,canada,cair}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cd556891-ed3c-476b-9fdd-dcc913de2bbc', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agricultural-Related Injuries in Alberta, 1990–2009', 'Canadian Agricultural Injury Surveillance Program (CAISP/CAIR) / Alberta Agriculture and Rural Development', 2012, 'Government of Alberta / Canadian Agricultural Injury Reporting', NULL, 'https://casa-acsa.ca/en/cair/reports/', 'https://www1.agric.gov.ab.ca/$Department/deptdocs.nsf/all/aet13518/$FILE/Alberta_CAISP_Deaths1990-2009_FINAL.pdf', NULL, NULL, 66, NULL, 'alberta', 5, 'Crown copyright (Government of Alberta), free to read', 'The Alberta-specific CAIR analysis: 355 Albertans killed in agricultural injury events 1990-2009 at a rate of 10.0 per 100,000 farm population, with animal-related events the fourth leading cause at 9% of fatalities. Of 31 Alberta animal-related deaths, 68% (21) involved horses and 32% (10) involved cows, steers or calves (7 male, 3 female victims). Among Albertans aged 60 and over, animal-related events caused 17 deaths, 13% of senior agricultural fatalities. The report also establishes the Alberta severity ratio: for every agricultural injury death there were 25 hospital admissions, 11 of them major trauma.', '{safety,injury-epidemiology,fatality,alberta,canada,cair}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c26e0e8-f33b-4b01-b9f2-76d809636039', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Agriculture-related Fatalities in Canada, 1990–2020', 'Canadian Agricultural Injury Reporting (CAIR) / Canadian Agricultural Safety Association', 2023, 'Canadian Agricultural Injury Reporting (CAIR), CASA', NULL, 'https://casa-acsa.ca/en/cair/reports/', 'https://www.casa-acsa.ca/wp-content/uploads/CAIR_Ag_Fatalities_1990-2020_en_V6.pdf', NULL, NULL, 35, NULL, 'canada', 5, 'publisher PDF, free to read (© Canadian Agricultural Safety Association)', 'National Canadian agricultural fatality surveillance covering 2,814 deaths from 1990 to 2020, with an overall rate of 10.7 per 100,000 farm population and an age-specific rate of 45.2 per 100,000 for farmers aged 80 and over. For 2011-2020 animal-related events caused 33 fatalities (5% of the decade''s deaths), tied with traffic collisions and falls from height; of the 32 animal-related deaths with animal type recorded, 53% (17) involved a horse and 47% (15) involved a cow or cattle. 66% of all agricultural fatalities were machine-related, leaving animals among the leading non-machine causes.', '{safety,injury-epidemiology,fatality,canada,cair,rate-per-100000}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('929c8a2f-80a8-44d9-b2af-ee7005813f73', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Alabama Beef Quality Assurance: Using Handling Facilities Correctly (ANR-1283)', 'Alabama Cooperative Extension System (Auburn University / Alabama A&M)', 2021, 'Alabama Cooperative Extension System', NULL, 'https://www.aces.edu/blog/topics/beef/alabama-beef-quality-assurance-using-handling-facilities-correctly/', 'https://www.aces.edu/wp-content/uploads/2021/04/ANR-1283-Alabama-Beef-Quality-Assurance-Using-Handling-Facilities-Correctly_042721L-A.pdf', NULL, NULL, 3, NULL, 'other', 4, 'publisher PDF, free to read (US land-grant extension)', 'A state Beef Quality Assurance facility-use guide that contains the clearest BQA-side statement of the design rule a corral-design tool needs: a catwalk built along the cattle-working chutes or loading chutes is a much better place from which to work cattle than standing behind them. Also advises staying out of kicking range rather than working close, warns that cattle become nervous or aggressive when alone, tells handlers to avoid electric prods wherever possible and to apply them only to the side or back, notes that cattle move forward when approached behind the shoulder and backward when approached ahead of it, and covers sweep tubs and the Bud Box as the two funnel options.', '{safety,catwalk,crowd-pen,electric-prod,bud-box,handling-behaviour}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('12dc17d0-27a1-4387-a880-d2b7b7739f0e', '0f560872-ad61-42ba-ad48-39b8582a7dfb', 'Deoxynivalenol-3-Glucoside Content Is Highly Associated with Deoxynivalenol Levels in Two-Row Barley Genotypes of Importance to Canadian Barley Breeding Programs', 'Tucker JR, Badea A, Blagden R, Pleskach K, Tittlemier SA, Fernando WGD', 2019, 'Toxins', '10.3390/toxins11060319', 'https://doi.org/10.3390/toxins11060319', 'https://europepmc.org/articles/PMC6628427?pdf=render', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc by', 'Barley (Hordeum vulgare L.) is a multipurpose crop that can be harvested as grain or cut prior to maturity for use as forage. Fusarium head blight (FHB) is a devastating disease of barley that reduces quality of grain. FHB can also result in the accumulation of mycotoxins such as deoxynivalenol (DON). Breeding FHB resistant varieties has been a long-term goal of many barley-producing countries, including Canada. While the genetic basis of DON detoxification via production of less-phytotoxic conjugates such as DON-3-glucoside (DON3G) is well documented in barley, little information exists in reference to varietal response. Over two years, 16 spring, two-row barley genotypes, of importance to western Canadian barley breeding programs, were grown as short-rows and inoculated following spike emergence with a Fusarium graminearum conidia suspension. Half of the plots were harvested at soft dough stage and then dissected into rachis and grain components, whereas the remainder was harvested at maturity. Multiple Fusarium-mycotoxins were assayed using liquid chromatography-mass spectrometry. Mycotoxin content was elevated at the earlier harvest point, especially in the rachis tissue. DON3G constituted a significant percentage (26%) of total trichothecene content and thus its co-occurrence with DON should be considered by barley industries. DON3G was highly correlated with DON and 3-acetyl-deoxynivalenol (3ADON). The ratio of D3G/DON exhibited consistency across genotypes, however more-resistant genotypes were characterized by a higher ratio at the soft-dough stage followed by a decrease at maturity. Plant breeding practices that use DON content as a biomarker for resistance would likely result in the development of barley cultivars with lower total DON-like compounds.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.020178+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e28746b9-be1d-42db-8d50-7b69943ceddf', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Are Animals Occupational Hazards? (US Census of Fatal Occupational Injuries, 1992–1997)', 'Drudi D (Bureau of Labor Statistics)', 2000, 'Compensation and Working Conditions, US Bureau of Labor Statistics (Fall 2000)', NULL, 'https://www.bls.gov/opub/mlr/cwc/are-animals-occupational-hazards.pdf', 'https://www.bls.gov/opub/mlr/cwc/are-animals-occupational-hazards.pdf', NULL, NULL, 8, NULL, 'other', 4, 'public domain (US government)', 'BLS analysis of 375 US animal-related work fatalities and the matching SOII nonfatal cases over 1992-1997. Cattle caused 141 deaths (38%), more than any other animal, but only 7% of nonfatal animal injuries (5,300 cases), so cattle are injury-light and death-heavy relative to other animals. Bulls, about 2% of the cattle population, caused about half the cattle-related fatalities (68 of 141); 5 deaths arose from birthing or maternal defensiveness by cows. Animal attacks accounted for 114 of the 141 cattle deaths, 14 were vehicle collisions, and 6 were cases of cattle knocking a gate or panel into the worker — the only published count of the swinging-gate mechanism. Agriculture accounted for three-quarters of cattle-related fatalities, over 9 in 10 cattle cases involved men, and fractures were one-sixth of nonfatal cattle cases versus under one-tenth of all nonfatal cases. Note: this PDF returns 403 to a curl HEAD request but downloads and parses correctly via a normal GET.', '{safety,injury-epidemiology,fatality,bls,usa,bull,gate-crush,calving}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5fc9ae91-3627-402f-8cf6-4f38f605818d', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Assessing Nonresponse Bias in Farm Injury Surveillance Data', 'Cheryl L. Beseler, Risto Heikki Rautiainen', 2021, 'Journal of Agricultural Safety and Health', '10.13031/jash.14554', 'https://doi.org/10.13031/jash.14554', 'http://elibrary.asabe.org/azdez.asp?JID=3&AID=52814&t=2&v=27&i=4&CID=j2021&downPDF=Y&directPDF=Y', NULL, NULL, 13, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ffc787f-d89c-4c7e-9175-9211939c0923', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Associations of Work-Related Injuries and Stress to Family and Youth Wellbeing among U.S. Latino/a Immigrant Cattle Feedyard Workers', 'Gustavo Carlo, Meredith M. McGinley, Sahitya Maiya, Athena K. Ramos', 2023, 'International Journal of Environmental Research and Public Health', '10.3390/ijerph20043361', 'https://doi.org/10.3390/ijerph20043361', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9962635/pdf/ijerph-20-03361.pdf', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc-by', 'Based on the Ecological Stress-Based Model of Immigrant Worker Safety and Health, we hypothesized that occupational stress and physical safety would be negatively linked to workers’ depression, which in turn, would increase family conflict and decrease youth prosocial behaviors. A total of 242 Latino immigrant cattle feedyard workers from Nebraska and Kansas (90.9% male; M age = 37.7 years) answered questions assessing depression, occupational stress, whether they had ever been injured at work, familial conflict, and youth prosocial behaviors. All four indirect relations among occupational stress and injury and the outcomes (family conflict and youth prosocial behaviors) via depressive symptomatology were significant. Additionally, ever injured was negatively related to youth prosocial behaviors and occupational stress was positively related to youth prosocial behaviors. The findings support our model and suggest that increased stress and work-related injuries on cattle feedyards are linked to mental health problems, which in turn, is linked to more conflict experienced at home and less youth prosocial behaviors. Feedyard employers should focus on improving safety culture including providing robust training in the workplace. Practical implications to improve availability and access to mental and behavioral health resources to mitigate negative family outcomes are provided.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('905d2d4d-1f44-4741-88cf-288f51b59c52', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Aversion learning techniques to evaluate dairy cattle handling practices', 'Edmond A. Pajor, Jeffrey Rushen, Anne Marie B. de Passille', 2003, 'Applied Animal Behaviour Science (Elsevier)', '10.1016/S0168-1591(02)00119-3', 'https://pubmed.ncbi.nlm.nih.gov/10906394/', NULL, NULL, NULL, NULL, NULL, 'canada', 4, 'unknown (publisher paywall)', 'Used a Y-maze choice test to rank how aversive cattle find common handling practices. In a second experiment 24 cows chose between paired treatments thought to be aversive: shout versus hit, shout versus cattle prod, and control versus tail twist. The reported conclusions are that shouting and the use of cattle prods are both aversive and that tail twisting is not aversive if done gently. A 2013 secondary review places the ordering as electric prod most aversive, shouting second, then tail twist and hitting. This is the primary source behind the extension claim that yelling is ''as stressful as an electric prod'', and it actually ranks the prod above shouting, so the claim should be stated carefully.', '{electric-prod,handling-behaviour,no-free-pdf,noise,safety}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c136289-d426-48a3-96ef-4de05c253869', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle Handling in Marts and Lairages: Information Sheet', 'Health and Safety Authority (Ireland)', 2010, 'Health and Safety Authority (Ireland)', NULL, 'https://www.hsa.ie/eng/publications_and_forms/publications/agriculture_and_forestry/', 'https://hsa.ie/eng/Publications_and_Forms/Publications/Agriculture_and_Forestry/Cattle_Handling_in_Marts_and_Lairages_Information_Sheet.pdf', NULL, NULL, 4, NULL, 'other', 3, '© Health and Safety Authority (Ireland); free to download', 'A four-page summary of the HSA''s Guidance on Safe Operation of Marts and Lairages, and the live equivalent of HSE''s apparently withdrawn livestock-markets publication; it credits New Zealand ACC for its cattle-arousal diagrams. Advisory. Its handler-protection content is unusually explicit for a welfare-adjacent document: there must be no chance of livestock escaping by slipping between vehicle and side railings; step aside behind the gate or to a refuge point when opening the rear door or ramp and do not walk down the pen in front of the cattle; always plan your escape route; work from above off a raised catwalk and never place arms or hands through the rails; use overhead walkways wherever possible; do not overload sorting pens because cattle must have somewhere to move; the ringman must not enter the weighing box and must have effective shelter and be able to open the exit gate without leaving it. It also covers cattle arousal signs, penning incompatible cattle separately, never mixing mature bulls, and excluding children from all cattle work.', '{safety,ireland-hsa,escape-routes,catwalks}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bcfca277-eead-4351-924d-83c7011b3687', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Investigation report : worker fatally injured by a steer while loading cattle', 'Government of Alberta', 2020, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/report-no-f-ohs-128002-a048e', 'https://open.alberta.ca/dataset/ee80e0b2-f419-42e2-988c-3f5dab31a0a4/resource/a603a0ff-a521-4756-bf6e-c569c583fb6f/download/lbr-2017-08-17-coro-view-farms-report-public.pdf', NULL, NULL, 28, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Presents findings of an investigation into a workplace fatality in the agriculture and forestry sector that occurred in August 2017. A worker was loading cattle into a cattle liner when one of the steers turned around and pinned the worker against a gate. The worker suffered fatal injuries.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2237dbeb-a6fc-42eb-bf93-c6e0bfd38ee2', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle Handling Safety in Working Facilities (OSU Extension Fact Sheet BAE-1738)', 'Hubert DJ, Huhnke RL, Harp SL', 2003, 'Oklahoma Cooperative Extension Service, Oklahoma State University', NULL, 'https://extension.okstate.edu/fact-sheets/cattle-handling-safety-in-working-facilities.html', 'https://pods.okstate.edu/fact-sheets/BAE-1738pod.pdf', NULL, NULL, 2, NULL, 'other', 5, 'publisher PDF, free to read (OSU Extension)', 'The single most useful extension document for a design-flagging tool. Gives numeric flight-zone radii (five to over 25 feet for feedlot cattle, as far as 300 feet for range cattle), the 45 to 60 degree working angle behind the shoulder, and the statement that cattle see in all directions except directly behind. Carries explicit facility-safety rules: do not enter a crowding area with animals if they become bunched; add a 14-inch wide pass-through for worker escape in pen corners; position the catwalk about 36 inches below the top of the fence so workers can move animals while avoiding direct animal contact; smallest pen dimension no less than 16 feet; at least 20 sq ft per mature animal; alley width 12 to 14 feet with a 10-foot minimum. Also reports a 1997 Oklahoma State study of 150 cattle-handling injury cases on 100 Oklahoma cow-calf operations in which more than 50 percent of injuries were due to human error and about 25 percent to equipment and facilities.', '{catwalk,cow-calf,crowd-pen,dimensions,facility-design,flight-zone,man-gate,mixed-advice-and-data,oklahoma,safety,usa}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce12d3a8-d9ae-45d3-850d-c8aeb0733b4e', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle Handling Safety: A Practical Guide', 'L Fragar and J Temperley, Australian Centre for Agricultural Health and Safety', 2016, 'Australian Centre for Agricultural Health and Safety, University of Sydney (RIRDC pub 16/024)', NULL, 'https://aghealth.sydney.edu.au/', 'https://aghealth.sydney.edu.au/wp-content/uploads/2019/05/Cattle-handling-Safety-Guide-A-Practical-Guide.pdf', NULL, NULL, 32, NULL, 'other', 4, '© Australian Centre for Agricultural Health and Safety; free to download', 'A 32-page hazard-and-control guide that treats absence of handler escape routes as a named hazard and preserves dimensional figures from New Zealand ACC''s withdrawn Better Yard Design (1999) and Stafford''s Cattle handling skills (1997). Advisory. Its Access and Escape Ways entry states that serious injury and deaths have occurred where there has been no escape for the handler from cattle in the drafting pound and forcing pen, controlled by escapeways built into both. Dimensions: minimum 1.5 square metres per adult animal in yards; top rail 1,600 mm adequate with 1,800 mm in forcing yards, pens and the drafting pound; forcing pen maximum width 3 m so cattle can be worked from the catwalk; forcing-to-race angle at least 30-35 degrees off a straight wall; race clear width 660-710 mm and about 1,600 mm of length per adult beast; loading ramp incline about 20 degrees maximum and width about 800-900 mm; catwalks at buckle height on forcing pens, race and loading ramp with non-slip surfacing, steps and handrails. Its crush-selection checklists include a Handler Safety column covering adequate escape routes, slam latches, break-away levers and kick-shut rear gate latches.', '{safety,dimensions,australia,escape-routes,catwalks}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0a550fb7-e48e-4814-9446-c2702f2d7b72', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle transporters'' attitudes, indigenous knowledge, and current practices towards animal welfare, occupational well-being, and operational challenges: A survey of five regions in Ghana', 'Joshua Mogre, Frederick Adzitey, Gabriel Ayum Teye, P. T Birteeb', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e27317', 'https://doi.org/10.1016/j.heliyon.2024.e27317', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10945195/pdf/main.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc-by', 'Ghana is a significant cattle producer in Africa with an estimated cattle population of 3 million in 2020 [1]. The role of transporters in linking farms to markets and slaughterhouses is crucial in the livestock value chain. However, cattle transportation subjects the animals to high levels of stress, compromising their welfare, and transporters face challenges such as long working hours and harsh conditions. The objective of this study was to explore current practices, indigenous knowledge, and operational risks pertaining to animal welfare among transporters. The study was conducted in five regions connected by the N16, N10, and N6 Highway, the primary route for cattle transportation from the Ghana-Burkina Faso border to the coastal capital of Accra. A total of 78 transporters participated in the study. Out of the 78 participants in this study, the majority of transporters were young adults (56.5%) with secondary school education (45.9%) and 0-5 years of experience (37.2%). The average distance and time for transporting cattle was 528 km and 18 h, respectively. The transporters highlighted significant challenges encountered during cattle transport, including feed and water shortage, particularly prominent during the dry season (32.1%), as well as the occurrence of diseases and mortality, particularly high during the rainy season (41%). Furthermore, vehicular breakdowns were a common issue reported by transporters, with a substantial majority (88.5%) experiencing breakdowns during their last 10 trips. The results showed that most transporters (84.7%) had limited knowledge of animal welfare and had not received any formal education on livestock transportation. Instead, they gained experience as assistants on other trucks before becoming drivers. The findings of this study highlight the need for improved welfare standards for cattle during transportation and formal training programs for transporters in animal welfare and livestock transportation.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2e430318-e1eb-4d2e-b5bb-397226ec7aee', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle yards: design, materials and construction, Third Edition (Information series QE94009)', 'Evan Powell and John Lapworth, Queensland Department of Primary Industries and Fisheries', 2006, 'Queensland Department of Primary Industries and Fisheries (hosted by FutureBeef)', NULL, 'https://futurebeef.com.au/', 'https://futurebeef.com.au/wp-content/uploads/Cattle_yards_third_edition.pdf', NULL, NULL, 74, NULL, 'other', 5, 'Crown copyright (Queensland); free to download', 'A 71-page government engineering manual and the richest dimensional source found, including the only explicit man-gate specification: manways preferably 400 mm wide with the opening not exceeding 500 mm, covered by a spring-loaded blank plate-steel door that opens into the working yard and butts the post so it cannot swing through, with a latch where stock are held in an adjoining yard. Advisory. Its safety section calls for easy operator escape avenues such as manways, foot holes and open rail construction, gates positioned to reduce the chance of workers getting stuck, strong positive self-latching gates, a walkway beside loading ramps, and in high-throughput yards plans that enable stock to be worked from outside forcing areas. Further dimensions cover top rail heights (1.7 m quiet to 2 m fractious), rail spacings (300 mm ground to bottom rail, then 250 and 250-280 mm), post diameters and embedment depths, race widths (680 mm vertical, up to 700 mm for large European breeds; V-race 450 mm at ground spreading to 690-700 mm at 1 m), race length by herd size from 3 m to 12 m, catwalks (1.1 m below top rail; loading-ramp catwalk minimum 500 mm wide), forcing pens (30-35 degree approach, rear gate 1.8-2.2 m, no wider than 3.5 m and 4-6 m long), yard space allowances (2, 1.8 and 2.5 square metres per head for holding, drafting and cooling yards) and loading ramps (1 in 4 slope, 1170 mm width, 400-500 mm tread with 100 mm rise, 5 m curve radius, 15 degree offset).', '{safety,dimensions,australia,man-gates,catwalks,yard-design}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0a039f56-d638-416e-b7a0-1766c9523096', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle-Related Injuries and Farm Management Practices on Kentucky Beef Cattle Farms', 'Browning SR, Westneat SC, Sanderson WT, Reed DB', 2013, 'Journal of Agricultural Safety and Health 19(1):37-49 (ASABE)', '10.13031/2013.42570', 'https://uknowledge.uky.edu/epidemiology_facpub/6', 'https://stacks.cdc.gov/view/cdc/194711/cdc_194711_DS1.pdf', NULL, NULL, 13, NULL, 'other', 5, 'NIOSH-deposited author manuscript, free to read', 'Mail survey of 2,500 Kentucky Cattlemen''s Association members yielding 1,149 complete responses from active beef cattle operators. 157 farms (13.7%, 95% CI 11.7-15.8) reported at least one cattle-related injury to the operator or a family member in the previous 12 months. Reports crude injury rates per 100 farms for each piece of handling equipment present: crowding pen OR 1.80 (1.27-2.55), palpation cage OR 1.65 (1.16-2.35), manual squeeze chute with head gate OR 1.55 (1.10-2.18), working chute or alley OR 1.32, loading chute OR 1.25; ATV/Gator herding was protective (adjusted OR 0.51, 0.30-0.86). Also records the Oklahoma location breakdown (pens 40%, alleyways 17%, squeeze chutes 16% of 150 injuries on 100 cow-calf operations) and injury detail: 33.6% needed medical care or caused over 4 hours lost work, leg/hip/knee 30.2%, cows 36% of injuries, calves 16.8%, bulls and steers 13.4%.', '{safety,injury-epidemiology,cow-calf,incidence-rate,facility-design,crowding-pen,squeeze-chute,usa}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe6e399f-953f-4590-b155-ee24daf1d9b1', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle-related occupational accidents in Japan', 'Iwai H, Yamamoto H', 2023, 'PloS one', '10.1371/journal.pone.0289210', 'https://doi.org/10.1371/journal.pone.0289210', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10381074.1/PMC10381074.1.pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Cattle-related injuries are a significant contributing factor in 84.3% of livestock-related incidents in Hokkaido Japan. The specific countermeasures to respond to its characteristics are needed because cattle move freely. This study examined the JA Kyosai mutual aid payment claim form data of the agricultural work-related incidents that occurred from 1st January 2013 to 31st December 2016. We extracted incidents coded ''Cattle'' term on the ''Causing Stuffs/Animals'' column as cattle-related injuries and analysed them. In four years, there were 227 cattle-related incidents and all were non-fatal cases. The most common age group of victims were in their 60s (37.9%). The Therapy duration was 1 to 243 days, with one day being the most common (10.1%); however, in 51.5% of the cases it required more than 30 days. The most common Activity at the moment of the incident was ''bringing the cattle'' (22.5%), of which ''leading the cattle by rope'' (56.9% of bringing) was most frequently mentioned. Even farmers with significant experience with cattle cannot control cattle proficiently. Neither can they predict cattle behaviour. Hence, cattle should be kept under protected contact. Since prevention of incidents has limits, harm reduction to farmers must be considered. In the short-term planning, isolated pathways and shock-absorbing lead rope are effective in preventing injuries. However, a more long-term perspective must consider, a fully automated system that reduces human contact with cattle on farms.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('17c1a643-792f-4570-95a1-52cca53486fb', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cattle-related trauma: a 10-year retrospective cohort study from a Swiss level 1 trauma centre', 'Ehrhard S, et al. (Inselspital, University Hospital Bern)', 2022, 'Swiss Medical Weekly 152:w30201', '10.4414/SMW.2022.w30201', 'https://smw.ch/article/doi/smw.2022.w30201', 'https://smw.ch/index.php/smw/article/download/3229/5423/17041', NULL, NULL, 6, NULL, 'other', 4, 'publisher PDF, free to read (open access)', 'Ten-year cohort of 94 cattle-related trauma patients at a Swiss level 1 trauma centre (101 of roughly 470,000 presentations, 0.02%). Median age 52, 75% male, 73% farmers; cows caused 86% of injuries, bulls 10% and calves 2%. Mechanisms were head-butt 36%, kick 35%, body contact 20% and trampling 12%, with all 10 penetrating injuries caused by head-butts. Injuries were contusions 82%, lacerations 46%, face fractures 28%, closed head trauma 19% and chest injuries 17%; head AIS 3 or more in 12%, chest in 9%, abdomen in 3%; 12% had an ISS of 16 or more and in-hospital mortality was 3%. Bull injuries required surgery in 90% of cases versus 49% for cow injuries (p = 0.023), quantifying the severity gap between bulls and cows.', '{safety,injury-epidemiology,mechanism,body-region,bull,switzerland,severity}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e5671988-5930-41af-9316-977e493aff5a', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Code of Practice for Preventing Injury and Occupational Ill Health in Agriculture (For Farms with Three or Less Employees)', 'Health and Safety Authority (Ireland)', 2017, 'Health and Safety Authority (Ireland)', NULL, 'https://www.hsa.ie/eng/publications_and_forms/publications/agriculture_and_forestry/', 'https://www.hsa.ie/eng/publications_and_forms/publications/agriculture_and_forestry/code_of_practice_for_preventing_injury_and_occupational_ill_health_in_agriculture.pdf', NULL, NULL, 110, NULL, 'other', 4, '© Health and Safety Authority (Ireland); free to download', 'Ireland''s farm safety code, issued by the HSA under section 60 of the Safety, Health and Welfare at Work Act 2005 after consultation with the Farm Safety Partnership and with ministerial consent, which makes failure to observe it admissible in evidence in criminal proceedings; this is the most nearly mandatory document in this collection. Section 7.0 ''Safety with Livestock'' and s.7.3 ''Design and use of handling facilities'' (p.32-33) list the elements to examine (collecting pen, race or chute, forcing pen, catwalk, crush gate, dispersal pen) and set work practices including ''Never enter a crush with livestock'' and standing aside while closing the restraining gate when enclosing a herd in a collecting pen, to prevent crushing if an animal charges. Section 7.3 delegates all dimensions to the Department of Agriculture, Food and the Marine standard S137 for cattle crush, race and enclosures. Section 7.4 reports that bulls cause 27% of farm livestock deaths, restricts bull handling to trained, fit handlers aged 18-65, requires two handlers every time, and illustrates the rule ''Have an escape route''.', '{safety,regulation,ireland-hsa,code-of-practice}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c9bbecab-69f6-4eb1-a3b0-0e74a93bf051', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Cow-Related Injuries in Wisconsin During 2017-2023', 'Modji KKS, McCoy K, Creswell PD, Collin MR, Tomasallo C, Bedno S', 2025, 'American journal of industrial medicine', '10.1002/ajim.70009', 'https://doi.org/10.1002/ajim.70009', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12421713.1/PMC12421713.1.pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'IntroductionThe dairy industry-a key industry for the economy-remains a potentially hazardous industry across the nation. The literature on animal-related injuries in the agriculture industry is sparse. This analysis aimed to describe cow-related injuries, the utilization of workers'' compensation, and the circumstances of the injuries.MethodsThis mixed methods analysis of agricultural injuries focused on cow-related injuries in hospital discharge and workers'' compensation data during 2017-2023. Cases, aged 12 or older, were identified in the hospital discharge data using ICD10-CM codes. Cow-related claim injury narratives and industry and occupation data were extracted from workers'' compensation data.ResultsDuring 2017-2023, cow-related injuries represented 13.1% (n = 2659) of agricultural injuries and were the second most predominant cause of work-related agricultural injuries. These injury figures were stable, compared to a downward trend of non-cow-related injuries (p = 0.01). Young workers (12-34 years) and Hispanic workers had the highest burden for cow-related injuries. The top five body parts affected by cow injuries were the upper (24%) and lower (23%) extremities, other head, face, and neck (22.1%), chest (15.2%), and traumatic brain injury (5.1%). Workers'' compensation was used in 28.5% of cases identified in the hospital discharge data. Animal handling, lack of farm worker safety measures, and equipment safety were identified as factors associated with cow-related injuries.ConclusionThis analysis identified a surprising number of cow-related injuries, including some life-threatening injuries. It is important to continue to promote safety measures and injury prevention best-practices to ensure worker well-being and farm productivity.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3c287f49-a681-4fce-a8f4-a494158402d5', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Low Stress Cattle Handling (APSC-167)', 'Jennifer Ligon, John Benner, Rachel Grosse, Laura Siegle', 2019, 'Virginia Cooperative Extension, Virginia Tech', NULL, 'https://www.pubs.ext.vt.edu/APSC/apsc-167/apsc-167.html', 'https://aaec.vt.edu/content/dam/pubs_ext_vt_edu/APSC/apsc-167/APSC-167.pdf', NULL, NULL, 8, NULL, 'other', 3, 'publisher PDF, free to read (US land-grant extension)', 'An extension review of low-stress handling built on pressure-and-release learning, the flight zone and the point of balance. Explicitly names improved safety for both handler and cattle as the first of two benefits, citing Grandin 1998, but gives no injury measurements, which makes it a clean example of the expert-advice-without-measurement category. Also summarises the measured production literature that low-stress handling draws on (immunity and vaccine response, clinical sign detection, weaning response, weight gain, milk yield and quality, feedlot performance and carcass quality) with citations, and notes that docility EPD selection gradually produces calmer temperaments.', '{safety,low-stress,handling-behaviour,flight-zone,temperament}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a2d6d6dc-bc67-432a-8576-d5759f81881f', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Death and injuries caused by cattle: A forensic overview', 'Roger W. Byard', 2024, 'Forensic Science Medicine and Pathology', '10.1007/s12024-024-00786-8', 'https://doi.org/10.1007/s12024-024-00786-8', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11953160/pdf/12024_2024_Article_786.pdf', NULL, NULL, 5, NULL, 'other', 1, 'cc-by', 'Lethal episodes arising from interactions with cattle may be the result of a response of the animals to simple handling and herding, or from reactions to deliberate provocation or goading intended to incite aggressive behavior for public entertainment purposes. Deaths may be considered to be unprovoked and unanticipated, or provoked and predictable. Cattle cause significant numbers of deaths globally and are considered the most dangerous large animal in Britain. Behavior may be unpredictable even in apparently docile domesticated animals, and attacks may be by a single animal or a herd and result in injuries from kicking, head/butting/charging, stomping, goring, and crushing. Craniofacial injuries may involve fractures of the spine or skull with cerebral contusions and lacerations associated with subarachnoid, subdural, and extradural hemorrhages. Chest injuries are also characterized by fractures which may be multiple with flail chest, hemo- and pneumothoraces, and organ disruption. Injuries to the abdomen and perineum include intestinal perforations, splenic rupture, perineal and vaginal tears, urethral lacerations and avulsions, and bladder and rectal perforations. Significant vascular injuries include complete and partial transections and lacerations. Males living in rural areas are most at risk of a fatal encounter.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dd9977b9-8f33-4ab8-96e7-5b1aec6b55db', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Developing measures to audit welfare of cattle and pigs at slaughter', 'Temple Grandin', 2012, 'Animal Welfare (Universities Federation for Animal Welfare / Cambridge University Press)', '10.7120/09627286.21.3.351', 'https://www.cambridge.org/core/journals/animal-welfare/article/developing-measures-to-audit-welfare-of-cattle-and-pigs-at-slaughter/3E43BB9DCE2DABE3E4B00B21C8890A80', 'https://resolve.cambridge.org/core/services/aop-cambridge-core/content/view/3E43BB9DCE2DABE3E4B00B21C8890A80/S0962728600003882a.pdf/developing-measures-to-audit-welfare-of-cattle-and-pigs-at-slaughter.pdf', NULL, NULL, 6, NULL, 'other', 4, 'publisher PDF, free to read (Creative Commons, per the paper''s own re-use notice)', 'Reports a decade of restaurant-chain welfare audit data from 30-49 beef and 22-28 pork plants against five numerically scored criteria: percentage falling, percentage moved with an electric prod, percentage vocalising, stunning efficacy and insensibility. Thresholds are stated: prod use 25% or less to pass with 5% ''excellent'', falling 1% or less, cattle vocalisation 3% or less. Measured results include beef plants achieving 5% or less prod use rising from 25% (1996) to 81% (2010), 0% falls in 30 of 32 plants in 2010, and mean prod use by line speed of 12.5-27%. Grandin also notes that after auditing began in 1999 most plants banned electric prods in the lairage and crowd pen.', '{safety,electric-prod,handling-behaviour,audit-thresholds,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('99b920da-369b-4272-9328-51646cd25a7b', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Exploring Swedish veterinarians'' awareness of non-accidental-injuries, animal abuse and the Link to domestic violence, and their role in addressing this societal issue', 'Lisa Oellig, Johan Lindsjö, Helena Röcklinsberg', 2024, 'Frontiers in Veterinary Science', '10.3389/fvets.2024.1439106', 'https://doi.org/10.3389/fvets.2024.1439106', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11688811/pdf/fvets-11-1439106.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc-by', 'Research has established a link between animal abuse and domestic violence (the Link), where the perpetrator uses the animal to control the human victim. Veterinarians are exposed to both vulnerable animals and humans, playing a crucial role in detecting and handling these cases. A study using an online survey was conducted in 2019, exploring the awareness of Swedish veterinarians regarding Non-accidental-injuries (NAI) in animals, the Link between animal abuse and domestic violence and how to handle such cases. The survey was distributed by the Swedish Veterinary Association to 2,627 licensed veterinarians and was answered by 362 respondents. One of ten had experienced the Link in their clinical work while 63% did not know if they had. The awareness of the Link was generally high (90%), whereas 68% of respondents answered that they did not know or were unsure about the concept of NAI. Almost half of the respondents (44%) felt that they were unsure about how NAI should be diagnosed, 56% did not know how NAI should be documented and a third (34%) did not know which authority should be contacted in case of suspicion of animal abuse. A minority, 17%, knew how to act when there was a reason to suspect domestic violence. The responses showed that support in the clinics is inadequate, with only 10% stating that information material and further education is offered about the Link and 17% knew of action plans or procedures for dealing with a suspected case of animal abuse. Only 16% stated that the Link was part of their education. Improving the ability of veterinarians to act appropriately requires more integrated theoretical and practical training during their university studies. At the clinic, further education, action plans and collaboration with competent authorities and organizations are crucial. It is important that resources, such as information material, guidelines, action plans and educational programs are identified and used to support veterinarians in their work to help vulnerable animals and, by extension, people, in line with the concept of One Welfare.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ffe36c93-30a7-4337-8e6e-04e4cc579080', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Farm Worker Injuries Associated with Cows', 'Gabrielle M. Casey, Alison M. Grant, Sue Roerig, Jane Boyd, Marylee Hill, Matthew A. London, Kitty H. Gelberg, Eric M. Hallman', 1997, 'AAOHN Journal', '10.1177/216507999704500905', 'https://doi.org/10.1177/216507999704500905', 'https://journals.sagepub.com/doi/pdf/10.1177/216507999704500905', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b334508e-f6d1-4836-b868-1ad6100e889c', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Farmers Views on the Implementation of On-Farm Emergency Slaughter for the Management of Acutely Injured Cattle in Ireland', 'Paul McDermott, Aideen I. McKevitt, Flavia Heloisa Santos, Alison J. Hanlon', 2023, 'Animals', '10.3390/ani13030450', 'https://doi.org/10.3390/ani13030450', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9913314/pdf/animals-13-00450.pdf', NULL, NULL, 13, NULL, 'other', 1, 'cc-by', 'Four management options for acutely injured cattle in Ireland exist: treatment, unless cattle are severely injured; on-farm emergency slaughter (OFES); casualty slaughter (CS) if the animal is certified fit for transport; or euthanasia. OFES is designed to prevent transport of welfare-compromised cattle. An online survey of farmers in Ireland was carried out between April and July 2021 and focused on events during 2020. A theoretical framework of capacity, willingness, and opportunity was used to explore farmers'' perceptions. Responses from 94 farmers (49 dairy and 45 beef) were analysed; not all respondents answered all questions. Respondents indicated that the incidence of acutely injured cattle in Ireland is low. A majority reported not having an acutely injured animal for greater than 36 months. Most respondents had a positive attitude towards OFES for animal welfare reasons and were aware of relevant regulations and guidelines. Barriers to OFES included a lack of availability of OFES, and dairy farmers indicated that it had a similar financial impact as euthanasia. A parallel study with veterinarians indicated a higher incidence of acutely injured cattle in Ireland; the current results may be due to the demographic or the sensitivity of the topic. Nationwide electronic data capture on the cause of mortality could support improvements in the management of acutely injured cattle and enable surveillance of the proportion of these cattle undergoing OFES, euthanasia, or CS.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e5fd4218-5983-4130-a946-f8badb554979', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Farmers, Forestry and First Aid (F3A) and farmers'' preparation for traumatic injury in the field', 'Wilkie FJM, Scott I, Allen I, Batting S, Passmore W', 2026, 'International journal of emergency medicine', '10.1186/s12245-026-01243-9', 'https://doi.org/10.1186/s12245-026-01243-9', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13495245.1/PMC13495245.1.pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundAgriculture is a high-risk industry in the United Kingdom, with disproportionate rates of fatal and serious traumatic injury. Farm workers face hazards from machinery, livestock, chemicals, and transport incidents, often in remote settings where emergency care is delayed. Existing first aid training is usually generic and does not reflect the specific risks of agriculture.ObjectiveTo describe the development of Farmers, Forestry and First Aid (F3A), a trauma-focused first aid training programme for agricultural workers, and to evaluate participant reactions to the course.MethodsF3A was developed by clinicians and farming professionals using experiential learning principles and scenario-based training. The course covers basic life support, cardiopulmonary resuscitation, automated external defibrillator use, and immediate management of severe trauma. Anonymous post-course feedback was collected from participants across 32 courses using a training evaluation form with Likert-scale and free-text responses.ResultsFeedback was received from 344 participants. Overall satisfaction was very high, with median scores at the top of the scale for all Likert items and 97% of respondents recommending the course. Free-text comments indicated that participants found the course practical, relevant to farm work, and effective in increasing confidence in responding to traumatic emergencies.ConclusionsF3A aims to address an important gap in rural trauma preparedness by providing agricultural workers with context-specific first aid training. Participant reactions were strongly positive, supporting wider delivery of the course and further longitudinal evaluation to assess skill retention and real-world impact.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('98b7bd78-6a9a-48f7-b6e3-8ca10370f6ad', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'FarmSafe Plan Manual (AgSafe Alberta)', 'AgSafe Alberta', 2023, 'AgSafe Alberta', NULL, 'https://agsafeab.ca/resources/', 'https://agsafeab.ca/wp-content/uploads/2023/09/AgSafeAB_FarmSafe_manual_August2023_FINAL2_web_withlinks_compressed.pdf', NULL, NULL, 244, NULL, 'alberta', 3, 'free to download', 'The August 2023 edition of Alberta''s industry farm safety management system, licensed by AgSafe Alberta from the Government of Alberta in 2019 and built around eight planning elements with hazard assessment as the first substantive module. It supplies the hazard-assessment machinery that OHS Code Part 2 would otherwise mandate but does not, because of the Code s.1.1 ranching exemption, and so is the practical route by which an Alberta ranch discharges the OHS Act s.3(1) general duty. Accompanying free downloads include Hazard Assessment Forms 1 and 2, a Hazard Identification Checklist and Hazard ID Cards, plus an Inspection Form and Report specifically for a Cattle Handling Facility (Word format, May 2025), which is the closest thing to an Alberta-sanctioned corral inspection template in existence. The manual specifies no dimensions and no facility design criteria.', '{safety,alberta,agsafe,hazard-assessment,no-dimensions}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.729821+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('64902cfa-ac76-4da9-95ad-58da59a00109', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Fatal Animal Related Incidents on Australian Farms — a 20-Year Review', 'Peachey K-L, Lower T, Rolfe M', 2023, 'Journal of Agromedicine 28(3):553-560', '10.1080/1059924X.2023.2171523', 'https://pubmed.ncbi.nlm.nih.gov/36691767/', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'unknown (paywalled; abstract free via Europe PMC)', 'Descriptive study of National Coronial Information System records for people fatally injured by an animal on an Australian farm, 2001-2020. The mean was 6.5 animal-related deaths per year, a 35% reduction on the 1989-92 mean of 10. Horses and cattle together accounted for 81% of incidents (horses n=75, cattle n=31); 46% of decedents were aged 60 or over, more than half of cases occurred during work, 85% of decedents fell from or were struck by an animal, and 40% sustained a head injury. The abstract''s male count (86, 66%) does not reconcile with the horse-plus-cattle totals, an inconsistency in the source. Full text is paywalled (publisher site returns 403); no free PDF found.', '{age-over-60,australia,fatality,head-injury,injury-epidemiology,no-free-pdf,safety}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3e9d5b68-7f05-4572-ba0e-5702f13c758b', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Fatal Farm Injuries in Saskatchewan 1990 to 2019 (30 years)', 'Karunanayake C, Ulmer K, Hagel L, Koehncke N (Canadian Centre for Health and Safety in Agriculture, University of Saskatchewan)', 2021, 'Canadian Centre for Health and Safety in Agriculture, University of Saskatchewan', NULL, 'https://cchsa-ccssma.usask.ca/', 'https://cchsa-ccssma.usask.ca/documents/fatal-farm-injuries-1990-2019-may-2021.pdf', NULL, NULL, 31, NULL, 'prairies', 5, 'publisher PDF, free to read (University of Saskatchewan)', 'Thirty-year Saskatchewan farm fatality surveillance. Among 109 work-related non-machine fatalities, animal-related injury was the single most common mechanism at 20.0% (n=19), and beef cattle accounted for 68% of those animal-related cases — the most cattle-specific and most prairie-relevant Canadian figure available. Males were 89% of non-machine fatality victims and the oldest age group made up the majority. Being struck by an object was the next most common non-machine mechanism (n=19), most often by a heavy non-machine object such as a gate or door.', '{safety,injury-epidemiology,fatality,prairies,saskatchewan,beef-cattle,gate}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ef2a7a1-7c62-4807-bf73-97ae6502c278', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Fatalities Caused by Cattle — Four States, 2003–2008', 'Kraemer MU, Leinenkugel K, Myers JR (Centers for Disease Control and Prevention)', 2009, 'MMWR (Morbidity and Mortality Weekly Report) 58(29):800-804', NULL, 'https://www.cdc.gov/mmwr/preview/mmwrhtml/mm5829a2.htm', 'https://stacks.cdc.gov/view/cdc/187722/cdc_187722_DS1.pdf', NULL, NULL, 2, NULL, 'northern_plains', 5, 'public domain (US government)', 'Surveillance review of 21 occupational cattle-caused deaths in Iowa, Kansas, Missouri and Nebraska, 2003-2008, drawn from Iowa FACE and the Great Plains Center for Agricultural Health. Gives the only published fatal task/location breakdown: 33% while tending or treating cattle in enclosed areas such as pens and chutes, 24% while herding/moving/sorting toward pens, 14% while loading onto trucks or trailers, 14% feeding, 14% in open pasture. Bulls caused 10 of 21 deaths, cows with calves 3, cows without calves 3, multiple cattle 5; 16 deaths were purposeful strikes and 5 were crushing against a stationary object or being struck by a gate. 67% of decedents were 60 or older (median age 65), 95% male, one third working alone, and all but one death was blunt force trauma to chest and/or head.', '{safety,injury-epidemiology,fatality,niosh,usa,location-breakdown,bull,gate-crush}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2147c0cf-c92f-4c44-887f-10e571f534cc', '4468519e-45b7-42e3-a131-b2181808b714', 'Evaluation of age, weaning weight, body condition score, and reproductive tract score in pre-selected beef heifers relative to reproductive potential', 'Sarah E. Moorey, Michelle F. Elmore, Lisa A. Kriese-Anderson, Joshua B. Elmore, Bailey N. Walker, Paul William Dyce, Soren P P Rodning, Fernando H. Biase', 2019, 'Journal of Animal Science and Biotechnology/Journal of animal science and biotechnology', '10.1186/s40104-019-0329-6', 'https://doi.org/10.1186/s40104-019-0329-6', 'https://jasbsci.biomedcentral.com/track/pdf/10.1186/s40104-019-0329-6', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Artificial insemination is a preferred breeding method for beef heifers as it advances the genetic background, produces a predictive and profitable calving season, and extends the heifer''s reproductive life span. As reproductive efficiency in heifers is key for the success of beef cattle production systems, following artificial insemination, heifers are exposed to a bull for the remainder of the breeding season. Altogether, up to 95% of heifers might become pregnant in their first breeding season. Heifers that do not become pregnant at the end of the breeding season represent an irreparable economical loss. Additionally, heifers conceiving late in the breeding season to natural service, although acceptable, poses serious losses to producers. To minimize losses due to reproductive failure, different phenotypic parameters can be assessed and utilized as selection tools. Here, we tested the hypothesis that in a group of pre-selected heifers, records of weaning weight, age at weaning, age at artificial insemination, and age of dam differ among heifers of varied reproductive outcomes during the first breeding season. RESULTS: None of the parameters tested presented predictive ability to discriminate the heifers based on the response variable (''pregnant to artificial insemination'', ''pregnant to natural service'', ''not pregnant''). Heifers categorized with body condition score = 6 and reproductive tract score ≥ 4 had the greatest proportion of pregnancy to artificial insemination (49% and 44%, respectively). Furthermore, it was notable that heifers presenting body condition score = 6 and reproductive tract score = 5 presented the greatest pregnancy rate at end of the breeding season (89%). Heifers younger than 368 d at the start of the breeding season did not become pregnant to artificial insemination. Those young heifers had 12.5% chance to become pregnant in their first breeding season, compared to 87.5% if the heifers were older than 368 days. CONCLUSION: Our results suggest that beef heifers with body condition score = 6 and reproductive tract score ≥ 4 are more likely to become pregnant to artificial insemination. Careful assessment should be undertaken when developing replacement heifers that will not reach 12 months of age by the beginning of the breeding season.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4fd401b9-b512-40e6-99e8-a9d9616c4ece', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Handling and housing cattle (Agriculture Information Sheet No 35, Revision 1)', 'Health and Safety Executive', 2012, 'UK Health and Safety Executive (HSE)', NULL, 'https://www.hse.gov.uk/pubns/ais35.htm', 'https://www.hse.gov.uk/pubns/ais35.pdf', NULL, NULL, 5, NULL, 'other', 5, 'Crown copyright (UK, OGL)', 'The UK safety regulator''s core guidance on handling adult cattle, stock bulls and bull beef, formally advisory but evidentially weighty: following it means ''you will normally be doing enough to comply with the law'' and inspectors may refer to it. It contains the clearest regulator statement of the separation principle a corral-design tool enforces: arrange race, crush and loading areas ''so that no one ever needs to be in them with the animals'', keeping fixed handling system or lorry tailboard gates between handler and animal at all times. It requires an adequate escape route where a downer or loose-box animal cannot be secured, forbids working on animals held by gates alone, forbids working on a crushed animal with an unsecured animal waiting behind, requires race doors operated from the working side, and forbids entering a bull-beef pen or letting a lone person handle bull beef. Concrete dimensions: bull pen walls of 215 mm reinforced concrete block; railings and bars minimum 48 mm outside diameter; bull pen outer walls, fences and gates at least 1.5 m high; vertical bar spacings no more than 100 mm; bull-beef pen divisions around 1.5 m above floor with the lower 1 m meshed or sheeted; group size no more than 15-20; and crush flooring of bolted hardwood, chequer-plate or rubber mat.', '{safety,hse,dimensions,regulation,escape-routes}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6fb555c9-d04c-4ae0-b3d8-0c26ad68c609', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Handling Livestock Safely (Agdex 086-4)', 'Alberta Agriculture and Forestry', 2004, 'Canadian Agricultural Safety Association (CASA) SafetyShop library', NULL, 'https://casa-acsa.ca/en/safetyshop-library/handling-livestock-safely/', 'https://casa-acsa.ca/wp-content/uploads/2004-03_Handling_Livestock_Safely.pdf', NULL, NULL, 2, NULL, 'alberta', 3, 'free to download', 'CASA''s livestock-handling factsheet, authored by Alberta Agriculture and Forestry in March 2004 and the national safety association''s only livestock-handling resource. Advisory and behaviour-based rather than facility-based, it supplies the quantified animal-behaviour parameters a corral-design tool needs for its flow model: the flight zone of a range cow may be as large as 90 metres (300 ft) against 1.5 to 7.5 metres (5 to 25 ft) for a feedlot animal; the point of balance sits at the shoulder; there is a blind spot directly behind where animals will usually kick; and a stressed animal takes 20 to 30 minutes to calm. Its facility-relevant notes are that solid sides on handling facilities prevent animals seeing distractions, that animals balk at changes in flooring surface or texture, and that shadows and bright spots should be minimised. It reports that on average half of all farm-related injuries in Alberta involve large animals. It specifies no dimensions and no handler escape provision.', '{safety,canada,alberta,animal-behaviour,no-dimensions}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3c23f9f4-fe16-4eef-9d28-5e0ae748ed49', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Horse and Cattle-Related Trauma: A Retrospective Review of Injuries and Management in a Regional Queensland Hospital', 'Gabriella Savage, Amanda G. Liesegang, Jakob Campbell, Matthew Lyon, Damian Fry', 2023, 'Cureus', '10.7759/cureus.35746', 'https://doi.org/10.7759/cureus.35746', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9988439/pdf/cureus-0015-00000035746.pdf', NULL, NULL, 7, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Horse and cattle-related trauma is a common presentation to regional hospitals in Australia. We review local incidence and patterns of injuries relating to horse and cattle trauma over a three-year period at the Toowoomba Base Hospital within the Darling Downs region in Queensland, an area rich in cattle farming and equestrian recreation. METHODS: We conducted a single-centre retrospective cohort study. The inclusion criteria were all patients presenting with injuries following cattle or horse-related incidents between January 2018 and April 2021. Primary outcomes were the mechanism of trauma, confirmed injuries, and the need for admission, operative intervention, or inter-hospital transfer. RESULTS: A total of 1002 individuals (55% female; mean age 34 years; median Injury Severity Score (ISS) 2) were identified during the study period. Presentations relating to horses (81%) were more frequent than cattle (19%). The most common mechanism of injury was "falling" for horse incidents (68%) and "trampling" for cattle incidents (40%). Horse incidents often resulted in soft tissue injury (55%), upper limb fracture (19%), or lower limb fracture (9%). Cattle incidents often resulted in soft tissue injury (57%), upper limb fracture (15%), and rib fracture (15%). Overall, 14% required admission, 13% required operative intervention, and 1% required inter-hospital transfer. CONCLUSIONS: This local series demonstrates a high volume of cattle and horse-related trauma in our region. Whilst most patients are managed locally without operative intervention, the high frequency of injuries observed necessitates further development of preventative measures and safety advocacy.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1ef233ae-2af1-4236-8699-667d59ea7395', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Human–Animal Interactions with Bos taurus Cattle and Their Impacts on On-Farm Safety: A Systematic Review', 'Frances Margaret Titterington, Rachel Knox, Stephanie Buijs, D.E. Lowe, Steven James Morrison, Francis Lively, Masoud Shirali', 2022, 'Animals', '10.3390/ani12060776', 'https://doi.org/10.3390/ani12060776', 'https://www.mdpi.com/2076-2615/12/6/776/pdf?version=1647674252', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Cattle production necessitates potentially dangerous human-animal interactions. Cattle are physically strong, large animals that can inflict injuries on humans accidentally or through aggressive behaviour. This study provides a systematic review of literature relating to farm management practices (including humans involved, facilities, and the individual animal) associated with cattle temperament and human''s on-farm safety. The Preferred Reporting Items for Systematic reviews and Meta-Analyses (PRISMA) was used to frame the review. Population, Exposure, and Outcomes (PEO) components of the research question are defined as "Bovine" (population), "Handling" (exposure), and outcomes of "Behaviour", and "Safety". The review included 17 papers and identified six main themes: actions of humans; human demographics, attitude, and experience; facilities and the environment; the animal involved; under-reporting and poor records; and mitigation of dangerous interactions. Cattle-related incidents were found to be underreported, with contradictory advice to prevent injury. The introduction of standardised reporting and recording of incidents to clearly identify the behaviours and facilities which increase injuries could inform policy to reduce injuries. Global differences in management systems and animal types mean that it would be impractical to impose global methods of best practice to reduce the chance of injury. Thus, any recommendations should be regionally specific, easily accessible, and practicable.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('811df614-9656-4f17-b24f-577e1e081477', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'IMPACT OF CLIMATE CHANGE ON OCCUPATIONAL HEALTH AND ITS POSSIBLE PREVENTIVE STRATEGIES (REVIEW ARTICLE)', 'Mona Abdallah Ramadan, Basma Hussein Mourad', 2022, 'Egyptian Journal of Occupational Medicine', '10.21608/ejom.2022.133585.1272', 'https://doi.org/10.21608/ejom.2022.133585.1272', 'https://ejom.journals.ekb.eg/article_257813_e984daac16730c96d2bc3c533fda781e.pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9edc1502-4b84-42a0-a9cc-038e9c97f3fa', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Livestock fatalities attributed to a massive attack of Psorophora columbiae following Hurricane Laura', 'Bianca Santana de Cecco, Emi Sasaki, Daniel B. Paulsen, Craig Fontenot, Christine B. Navarre, Kristen Healy, Ingeborg Maria Langohr', 2022, 'The Bovine Practitioner', '10.21423/bovine-vol56no1p14-18', 'https://doi.org/10.21423/bovine-vol56no1p14-18', 'https://bovine-ojs-tamu.tdl.org/bovine/article/download/8419/8284', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-sa', 'The objective of this case report is to characterize the sudden fatality of livestock associated with a massive attack of dark rice field mosquitoes (Psorophora columbiae) after the passage of Hurricane Laura in southwest Louisiana late August 2020. In 3 days, approximately 30 deer, 600 beef cattle, 100 sheep and 30 horses died following a brief history of weakness or, in most cases, no clinical signs prior to death. Several on-site visits were performed by veterinarians to evaluate animals and perform necropsies. Two deer were received for necropsy, and tissue samples from 1 bull and 1 horse were evaluated at the Louisiana Animal Diagnostic Disease Laboratory. In addition, postmortem examination was performed on another 15 animals by veterinarians. Similar gross alterations were observed in all necropsies. Lesions included multifocal petechiae and ecchymoses in the skin and the subcutaneous tissues. Both deer also had pale discoloration and accentuated lobular patterns in their livers. Histologically, the livers of the deer and the bull exhibited centrilobular degeneration and hepatocyte dissociation suggestive of severe anemia. The description of this animal fatality event associated with Psorophora colum- biae attack demonstrates the need to establish prevention and/or intervention protocols in areas prone to hurricanes and tropical depressions.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('507038e5-626d-4ed3-a78a-fbb777df209c', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Livestock handling guidelines', 'SafeWork SA (Government of South Australia)', 2021, 'SafeWork SA (Government of South Australia)', NULL, 'https://safework.sa.gov.au/industry/agriculture/livestock-transport/livestock-handling-guidelines', 'https://www.sheepconnectsa.com.au/business-management/Livestock-handling-guidelines.pdf', NULL, NULL, 2, NULL, 'other', 3, 'Crown copyright (South Australia); free to download', 'A South Australian work-health-and-safety guidance sheet that treats yard design itself as the hazard, listing poor design that hinders animal flow or causes bottlenecks and blockages, ramps without suitable walkways, gates and access points, uneven surfaces, and poor maintenance of yards, ramps, fences and gates. Advisory. Its key control states the correct hierarchy for a design tool: install escape gates, bottom rails no less than 300 mm above the ground, and safety barriers if the separation of people and animals cannot be achieved. Further controls forbid loading cattle from inside the ramp, require that a ramp not allow limbs to be placed through the bars, ask whether gates can be opened externally, specify positive bolt slam-shut spring-loaded latches especially in forcing yards, and require a safety gate at the interface between transport vehicle and loading ramp. It cites AS 5340:2020 Livestock loading/unloading ramps and forcing pens, the authoritative but paywalled Australian dimensional standard. NOTE: verified via a third-party mirror because the safework.sa.gov.au copy returns HTTP 403.', '{safety,australia,dimensions,escape-routes,regulation}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('64f42b3d-1e5a-481b-bbec-c41b9be90d0c', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Livestock-related injuries in the Midland region of New Zealand', 'Tosswill M, Roskruge M, Smith A, Christey G', 2018, 'New Zealand Medical Journal 131(1483):12-19', NULL, 'https://pubmed.ncbi.nlm.nih.gov/30286064/', 'https://sites.massey.ac.nz/teaurangahau/wp-content/uploads/sites/53/2020/07/Livestock-related-injuries-in-the-midland-region-of-new-zealand.pdf', NULL, NULL, 8, NULL, 'other', 5, 'publisher PDF, free to read (NZMA)', 'Midland Trauma System Registry study of 168 livestock injury admissions 2012-2015, of which 127 (75.6%) were cattle-related. Gives the clearest published location and task split for cattle handling: moving and loading stock caused 38% of injuries (moving 27%, loading 11%) and at least 29% of cattle-related injuries occurred near gates, poles or fences. Mechanisms: cattle caused 89.7% of all crush injuries (trapped between two animals or between animal and structure), 91.9% of kicks, 72.3% of hits and 100% of tramplings. Cattle were the only animal responsible for any head/neck, chest or abdominal injury in the series; body regions were upper/lower extremity 40% and external 34%. Cattle injuries peaked in September-October (calving) with daily peaks at 9-10am and 3-5pm, and age peaks at 20-29 and 50-59.', '{safety,injury-epidemiology,new-zealand,gate,crush,location-breakdown,loading,calving}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e48c6372-4a5e-4027-9d4a-2cd4104730ff', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Long-Term Epidemiological Trends and Risk Factors of Crimean-Congo Hemorrhagic Fever in Kazakhstan: An Integrated Epidemiological and Entomological Analysis', 'Abuova GN, Bukharbayev YB, Berdaliyeva FA, Pshenichnaya NY, Bektan BY', 2026, 'Viruses', '10.3390/v18080840', 'https://doi.org/10.3390/v18080840', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13517472.1/PMC13517472.1.pdf', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Crimean-Congo hemorrhagic fever (CCHF) remains a major tick-borne zoonotic infection and a persistent public health challenge in Central Asia. Kazakhstan is among the endemic countries, where natural foci of CCHF are concentrated predominantly in the southern regions. This study evaluated the long-term epidemiological trends, regional distribution, seasonality, and risk factors associated with CCHF in Kazakhstan. A retrospective analysis of national surveillance data from 1980 to 2023 was conducted, complemented by detailed epidemiological and entomological investigations in the Turkestan region and the city of Shymkent during 2011-2023. Laboratory-confirmed cases, tick bite-related healthcare visits, entomological surveillance data, demographic characteristics, and epidemiological risk factors were analyzed. The results demonstrated cyclic fluctuations in CCHF incidence, with epidemic peaks occurring every 4-6 years and pronounced spring-summer seasonality, with the highest incidence observed in June and July. Long-term average annual incidence in endemic southern regions exceeded the national average by 2.67-fold. A total of 50,671 tick bite-related healthcare visits were registered during 2011-2023, while their incidence declined over time. Analysis of 94 laboratory-confirmed cases identified adults aged 18-40 years as the most affected group. Tick bites and livestock-related activities were the principal risk factors. These findings support the strengthening of integrated surveillance, vector control, laboratory diagnostics, and One Health-based prevention strategies in endemic regions.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3840aa14-d35d-444e-9709-e644371e5b50', '4468519e-45b7-42e3-a131-b2181808b714', 'The effects of weaning beef calves in two stages on their behavior and growth rate', 'Haley, D.B.; Bailey, D.W.; Stookey, J.M.', 2005, 'Journal of Animal Science 83(9):2205-2214', '10.2527/2005.8392205x', 'https://doi.org/10.2527/2005.8392205x', NULL, NULL, NULL, NULL, NULL, 'prairies', 5, 'Subscription (American Society of Animal Science / Oxford University Press)', 'The canonical two-stage weaning paper and the source of the numbers quoted everywhere: 392 cow-calf pairs, four trials, nose flaps worn before separation. Calves weaned in two stages vocalised 96.6% less, walked 78.9% less, ate 23.0% more and rested 24.1% more than abruptly weaned calves after separation; walking was 5.8 km/d lower over the first 4 days. ADG fell while the flap was in and rose in the week after separation, with no net difference over the whole period. Paywalled, but the complete dataset and methods are in Haley''s freely downloadable 2006 University of Saskatchewan thesis, which should be used instead.', '{weaning,two-stage,nose-flap,behaviour,vocalisation,canadian,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4d084bf7-0614-48a7-865a-112424a83029', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'More Than Time and Money: A Mixed-Methods Study of the Barriers to Safer Cattle Handling Practices', 'Scott-Harp D, Peek-Asa C, Rohlman DS, Janssen B', 2019, 'American Journal of Industrial Medicine 62(11):978-985', '10.1002/ajim.23043', 'https://pubmed.ncbi.nlm.nih.gov/31436349/', 'https://stacks.cdc.gov/view/cdc/85860/cdc_85860_DS1.pdf', NULL, NULL, 14, NULL, 'northern_plains', 4, 'NIH/NIOSH author manuscript, free to read', 'Iowa survey (N=66) plus four beef-operation site visits documenting which handling-facility components farms actually have and why they do not change them. Over 50% of farms had an alley, manual head gate, sorting/diverter gate and manual squeeze chute; hydraulic head gates 24.5% and hydraulic chutes 10.2%. Of farmers naming desired changes, 40% wanted to redesign one element or the whole facility and 10% wanted designed worker escape routes. Its introduction assembles the key denominators: US farmer/rancher fatality rate 24 per 100,000 FTE, livestock-production nonfatal incidence 6.9 per 100 full-time workers versus 5.7 for crops, and the Hubert/Huhnke finding that pens, alleyways and squeeze chutes are the commonest injury locations with about 25% of cattle-handling injuries attributable to equipment used and working-facility design.', '{safety,facility-design,injury-epidemiology,usa,iowa,escape-routes}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('93fec276-c0b1-4e0b-a312-85d693248dce', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Non-fatal animal related injuries to youth occurring on farms in the United States, 1998', 'Kitty J. Hendricks, Nelson Adekoya', 2001, 'Injury Prevention', '10.1136/ip.7.4.307', 'https://doi.org/10.1136/ip.7.4.307', 'https://injuryprevention.bmj.com/content/injuryprev/7/4/307.full.pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d6800678-02bc-4880-8537-80f9c52547af', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Non-intentional farm-related incidents in Australia, January–December 2024', 'AgHealth Australia, University of Sydney (for AgriFutures Australia)', 2025, 'AgHealth Australia / AgriFutures Australia', NULL, 'https://aghealth.sydney.edu.au/?p=2389', 'https://aghealth.sydney.edu.au/wp-content/uploads/2025/03/25-006-non-intentional-farm-related-incidents.pdf', NULL, NULL, 3, NULL, 'other', 3, 'publisher PDF, free to read (AgriFutures Australia)', 'Annual media-surveillance report on Australian on-farm deaths and injuries. 72 on-farm deaths in calendar 2024 against 32 in the equivalent 2023 window, and 1,815 non-intentional on-farm deaths since 2001, of which 53% (n=971) were aged 50 or over, 88% (n=1,601) were male, and 14% (n=248) involved children under 15. Cattle and, separately, cattle yards appear as agents of fatal injury in the 2024 agent table. Of 133 non-fatal on-farm injury events reported in media in 2024, cattle accounted for 12, behind quads (46) and horses (14). Because the method is media monitoring, all counts are undercounts.', '{safety,injury-epidemiology,australia,fatality,cattle-yards,media-surveillance}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac12ce10-2111-4c29-9582-cb9df687306e', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational exposure and challenges in tackling M. bovis at human-animal interface: a narrative review', 'Devi KR, Lee LJ, Yan LT, Syafinaz AN, Rosnah I, Chin VK', 2021, 'International archives of occupational and environmental health', '10.1007/s00420-021-01677-z', 'https://doi.org/10.1007/s00420-021-01677-z', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7961320.1/PMC7961320.1.pdf', NULL, NULL, 25, NULL, 'other', 1, 'open access (Europe PMC)', 'Zoonotic tuberculosis caused by Mycobacterium bovis (M. bovis), a member of Mycobacterium tuberculosis complex (MTBC) has increasingly gathered attention as a public health risk, particularly in developing countries with higher disease prevalence. M. bovis is capable of infecting multiple hosts encompassing a number of domestic animals, in particular cattle as well as a broad range of wildlife reservoirs. Humans are the incidental hosts of M. bovis whereby its transmission to humans is primarily through the consumption of cattle products such as unpasteurized milk or raw meat products that have been contaminated with M. bovis or the transmission could be due to close contact with infected cattle. Also, the transmission could occur through aerosol inhalation of infective droplets or infected body fluids or tissues in the presence of wound from infected animals. The zoonotic risk of M. bovis in humans exemplified by miscellaneous studies across different countries suggested the risk of occupational exposure towards M. bovis infection, especially those animal handlers that have close and unreserved contact with cattle and wildlife populations These animal handlers comprising of livestock farmers, abattoir workers, veterinarians and their assistants, hunters, wildlife workers as well as other animal handlers are at different risk of contracting M. bovis infection, depending on the nature of their jobs and how close is their interaction with infected animals. It is crucial to identify the underlying transmission risk factors and probable transmission pathways involved in the zoonotic transmission of M. bovis from animals to humans for better designation and development of specific preventive measures and guidelines that could reduce the risk of transmission and to protect these different occupational-related/populations at risk. Effective control and disease management of zoonotic tuberculosis caused by M. bovis in humans are also hindered by various challenges and factors involved at animal-human interface. A closer look into factors affecting proper disease control and management of M. bovis are therefore warranted. Hence, in this narrative review, we have gathered a number of different studies to highlight the risk of occupational exposure to M. bovis infection and addressed the limitations and challenges underlying this context. This review also shed lights on various components and approaches in tackling M. bovis infection at animal-human interface.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e7d6218d-9b26-41a5-a2cf-911d3de96520', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Seroprevalence, Dual Seropositivity, and Associated Risk Factors of BVDV and BoHV-1 in Dual-Purpose Cattle from the Colombian Eastern Plains', 'Carvajal ES, Arango JLP, Ciuoderis K, Orjuela AG', 2026, 'Viruses', '10.3390/v18070723', 'https://doi.org/10.3390/v18070723', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13431480.1/PMC13431480.1.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Bovine viral diarrhea virus (BVDV) and bovine herpesvirus type 1 (BoHV-1) are major pathogens affecting cattle worldwide, leading to significant economic losses in livestock production systems. This study aimed to estimate the seroprevalence and dual seropositivity of both viruses in dual-purpose cattle in Villavicencio, Colombia. A total of 1000 serum samples were collected from cattle across 30 farms and analyzed using ELISA. Seroprevalence for BVDV ranged from 0.0% to 78.7%, while BoHV-1 ranged from 0.0% to 100.0%. Dual seropositivity with both viruses was observed at the farm level, ranging from 0.0% to 52.2%. At the herd level, 26.7% (8/30) of the farms were seronegative for BVDV (95% CI: 14.2-44.5%), whereas only 3.3% (1/30) were seronegative for BoHV-1 (95% CI: 0.6-16.7%). Additionally, seven farms (23.3%) were simultaneously seronegative for both BVDV and BoHV-1. Overall, the findings demonstrate widespread exposure and non-random concurrent seropositivity of both viruses, highlighting the importance of herd management, biosecurity, and animal movement in shaping infection dynamics in dual-purpose cattle systems. Management practices, animal movement, and environmental factors were significantly associated with seropositivity.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('08ca0c2a-511f-48cf-acee-06b80ea523cf', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational exposure to human Mycobacterium bovis infection: A systematic review', 'Flora Vayr, Guillaume Martin‐Blondel, F. Savall, Jean-Marc Soulat, Gaëtan Deffontaines, Fabrice Hérin', 2018, 'PLoS neglected tropical diseases', '10.1371/journal.pntd.0006208', 'https://doi.org/10.1371/journal.pntd.0006208', 'https://journals.plos.org/plosntds/article/file?id=10.1371/journal.pntd.0006208&type=printable', NULL, NULL, 14, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Mycobacterium bovis (M. bovis) is the main causative agent of bovine zoonotic tuberculosis. The aim of this systematic review is to highlight the occupational exposure to bovine tuberculosis due to M. bovis. METHODOLOGY/PRINCIPAL FINDINGS: A computer based literature search was carried out to identify papers published between January 2006 and March 2017. "PubMed, Cochrane Library and Science Direct" databases were searched systematically. Articles presenting the following properties were included: (i) focusing on M. bovis; (ii) concerning occupational exposure to bovine tuberculosis. A quality assessment was performed after selection of studies. Our search strategy identified a total of 3,264 papers of which 29 studies met the inclusion criteria. Of the 29 articles, 17 were cross-sectional studies (6 were of high quality and scored in the range of 6-7, 11 were of moderate quality and scored in the range 3-5), 10 were case reports, and 2 were reviews. Different occupational fields exposing to the disease were described: livestock sector, particularly in contact with dairy cattle (farmers, veterinaries and assistants, abattoir workers) and working in contact with wildlife (hunters, taxidermists). CONCLUSIONS: A specific guideline for occupational practitioners taking care of employees exposed to bovine tuberculosis is warranted and should be tailored to level of exposure. This review was intended to be the first step of such a project. Articles were identified from various continents and countries with different socio-economic situations, broadening our understanding of the worldwide situation. Published data on occupational exposure in developed countries are scarce. We had to extrapolate findings from countries with higher prevalence of the disease.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd2d4a67-78bd-4405-b18f-30d30176e9ed', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational Health and Safety Act, SA 2020 c O-2.2', 'Government of Alberta / Alberta King''s Printer', 2023, 'Alberta King''s Printer', NULL, 'https://open.alberta.ca/publications/o02p2', 'https://kings-printer.alberta.ca/documents/Acts/o02p2.pdf', NULL, NULL, 77, NULL, 'alberta', 5, 'Crown copyright (Alberta King''s Printer; reproduction permitted with acknowledgement)', 'The only Alberta occupational safety instrument that binds a farm or ranch employing waged non-family workers. Section 1(cc)(i) excludes from ''occupation'' those farming and ranching operations paying wages only to listed family members, and s.1(tt)(ii) correspondingly excludes those persons from ''worker'', so one waged non-family hire brings the whole Act into force. Section 3(1)(a) imposes the general duty to ensure worker health, safety and welfare ''as far as it is reasonably practicable'', with s.3(2)-(4) covering adequate training, competent performance of endangering work and keeping hazard information available; ss.13-14 set the 20+/5-19 worker thresholds for committees and representatives. Section 33(1)-(2) requires reporting worker deaths and hospital admissions to a Director as soon as possible and s.33(5)-(6) requires investigation of potentially serious incidents, but only where the injured person is a ''worker'', so owner and family injuries are not reportable.', '{safety,regulation,alberta-ohs,reporting}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f3775c87-25b7-417a-ac86-f9dce62f76c7', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational Health and Safety Code, Alberta Regulation 191/2021 (office consolidation current as of March 31, 2025)', 'Government of Alberta / Alberta King''s Printer', 2025, 'Alberta King''s Printer', NULL, 'https://www.alberta.ca/occupational-health-and-safety-code', 'https://kings-printer.alberta.ca/documents/Regs/2021_191.pdf', NULL, NULL, 522, NULL, 'alberta', 5, 'Crown copyright (Alberta King''s Printer; reproduction permitted with acknowledgement)', 'The complete Alberta OHS Code, containing every technical occupational safety standard in the province. Section 1.1(1) states the Code does not apply to farming and ranching operations including ''the raising and maintenance of animals or birds'', with only Part 13 (joint health and safety committees and representatives, ss.196-204) applying per s.1.1(4) and s.201 training limited to co-chairs and representatives per s.1.1(5). It therefore specifies no dimensions, man gates, escape routes, race widths or pen allowances for livestock handling facilities, and contains no provision about working with animals at all. Part 2 (ss.7-9 hazard assessment and the eliminate/engineer/administer/PPE control hierarchy) and Part 28 (ss.393-394 working alone, where s.393(2) declares working alone a hazard) are exempt for ranches but are the best available Alberta standard-of-care benchmarks.', '{safety,regulation,alberta-ohs,no-dimensions}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc5f7bdf-0467-40d5-9af6-8f4167fa5394', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational health and safety management systems in animal production agriculture', 'Dan Autenrieth, Brazile, William, Reynolds, Stephen, Douphrate, David, Román-Muñiz, Noa, Sandfort, Delvin', 2015, 'Digital Collections of Colorado (Colorado State University)', '10.25675/3.022654', 'https://doi.org/10.25675/3.022654', 'http://hdl.handle.net/10217/167127', NULL, NULL, 171, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2cf57b4-39b3-4c08-aea7-65944ab85aab', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational Injuries among Latino/a Immigrant Cattle Feedyard Workers in the Central States Region of the United States', 'Athena K. Ramos, Suraj Adhikari, Aaron Moses Yoder, Risto Heikki Rautiainen', 2021, 'International Journal of Environmental Research and Public Health', '10.3390/ijerph18168821', 'https://doi.org/10.3390/ijerph18168821', 'https://www.mdpi.com/1660-4601/18/16/8821/pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Agriculture is a dangerous industry with high rates of occupational injuries. Immigrants comprise the majority of the hired agricultural workforce in the United States, and these workers may be at a higher risk for job-related injuries. This study addressed the frequency, characteristics, and risk factors of occupational injuries among Latino immigrant cattle feedyard workers. Data were collected through structured interviews with Latino immigrant cattle feedyard workers in Kansas and Nebraska (n = 243; 90.9% male). Descriptive statistics and logistic regression were used to identify risk factors for injury. Nearly three-fourths of participants (71.2%) reported having experienced one or more injuries in the past while working on a cattle feedyard. The most frequent types of reported injuries, including those not requiring medical care, were bruises/contusions (40%), cuts/lacerations (21%), and sprains/strains (12%). These injuries were mainly caused by animals/livestock (33%), chemicals (23%), falls (12%), and tools (9%). Significant risk factors for injury included male gender (OR 5.9), being over age 35 (OR 2.6), working on a large or an extra-large feedyard (OR 5.4), having 11 or more employees on the feedyard (OR 3.6), and working more than eight hours a day (OR 4.7). Having received safety training was also associated with greater risk of injury in a univariable model (OR 2.6). Cattle feedyard workers are at high risk for injury and require more effective preventive measures.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a24c19ce-eac8-4d5d-a297-dcda09efd2dd', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occupational Safety and Health with Technological Developments in Livestock Farms: A Literature Review', 'Marie A. Hayden, Menekse Salar Barim, Darlene L. Weaver, K. C. Elliott, Michael A. Flynn, Jennifer M. Lincoln', 2022, 'International Journal of Environmental Research and Public Health', '10.3390/ijerph192416440', 'https://doi.org/10.3390/ijerph192416440', 'https://www.mdpi.com/1660-4601/19/24/16440/pdf?version=1670901731', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'In recent decades, there have been considerable technological developments in the agriculture sector to automate manual processes for many factors, including increased production demand and in response to labor shortages/costs. We conducted a review of the literature to summarize the key advances from installing emerging technology and studies on robotics and automation to improve agricultural practices. The main objective of this review was to survey the scientific literature to identify the uses of these new technologies in agricultural practices focusing on new or reduced occupational safety risks affecting agriculture workers. We screened 3248 articles with the following criteria: (1) relevance of the title and abstract with occupational safety and health; (2) agriculture technologies/applications that were available in the United States; (3) written in English; and (4) published 2015-2020. We found 624 articles on crops and harvesting and 80 articles on livestock farming related to robotics and automated systems. Within livestock farming, most (78%) articles identified were related to dairy farms, and 56% of the articles indicated these farms were using robotics routinely. However, our review revealed gaps in how the technology has been evaluated to show the benefits or potential hazards to the safety and well-being of livestock owners/operators and workers.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1100e4f5-d7ae-43ac-80f2-1b8dae5fe50a', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Occurrence and Risk Factors of Brucellosis in Commercial Cattle Farms from Selected Districts of the Eastern Coast Zone, Tanzania', 'Warioba JP, Karimuribo ED, Komba EVG, Kabululu ML, Minga GA, Nonga HE', 2023, 'Veterinary medicine international', '10.1155/2023/4904931', 'https://doi.org/10.1155/2023/4904931', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9940978.1/PMC9940978.1.pdf', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'Brucellosis is a disease of major socio-economic importance worldwide, particularly in low-income countries. This retrospective study aimed to estimate seroprevalence and risk factors associated with brucellosis in commercial cattle farms in the eastern coast zone of Tanzania (ECZT). A total of 1,052 serum samples collected from 20 commercial farms were subjected to rose bengal plate test (RBPT) and indirect enzyme-linked immunosorbent assay (i-ELISA). Descriptive analysis was employed to determine frequencies and proportions. To establish risk factors, a multivariate logistic regression analysis was carried out using a backward elimination procedure, following a univariate analysis, with 0.1 set as a cut-off point for the selection of putative risk factors. Agreement between RBPT and i-ELISA was determined using a Kappa coefficient (κ). The overall animal-level seroprevalence was 25.9% based on i-ELISA. Logistic regression analysis revealed that odds of infection were significantly higher in females (OR = 1.8, 95% CI: 1.2-2.5, p = 0.002) and in young animals than in adults (OR = 3.6, CI: 2.1-6.2, p p p p = 0.004), and in medium-sized farms (OR = 12.5, CI: 6.9-22.9, p < 0.001). These findings confirm that bovine brucellosis was prevalent among commercial cattle farms in the ECZT, posing a serious public health concern to the community living in these settings. The one health approach should be adopted for effective control of brucellosis.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48d913a3-5059-4dcd-8219-a49312ada1b5', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Prevalence and patterns of self-reported animal-related injury among veterinarians in metropolitan Kampala', 'Richard M. Kabuusu, Emmanuel O. Keku, Robert Kiyini, Theresa J. McCann', 2010, 'Journal of Veterinary Science', '10.4142/jvs.2010.11.4.363', 'https://doi.org/10.4142/jvs.2010.11.4.363', 'http://vetsci.org/Synapse/Data/PDFData/0118JVS/jvs-11-363.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-sa', 'To establish the prevalence, patterns and risk factors of animal-related injuries among veterinarians, self-administered questionnaires were given to 60 veterinarians practicing in metropolitan Kampala. The prevalence of animal-related injuries in metropolitan Kampala was 72% (95%CI, 57~84). Some veterinarians (34%) suffered multiple injuries with a mean and median of 2.1 and 2.0 injuries per veterinarian, respectively. Of a total of 70 self-reported animal related injuries, cattle accounted for 72%, cats for 25%, dogs for 23%, self inoculation for 15% and birds for 13%. Injuries associated with poultry did not require hospital treatment. The upper limb was the most the frequently (68%) injured anatomical body part of veterinarians, and vaccination of animals (25%) was the major activity associated with injury. Animal-related injuries are common among practicing veterinarians in metropolitan Kampala; however, they did not differ significantly based on the veterinarian''s gender, experience or risk awareness.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8aa7c420-c840-4bed-a79e-8233dd01a373', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Prevalence, risk factors, and main characteristics of bruises in cattle: A meta-analysis in the American continent', 'Jaime Noé Sánchez-Pérez, Briseyda J. Félix-Leyva, Diana Zuleika Velazquez, José R. Rosiles, Arnulfo Montero Pardo, Ana Strappini, Carmen Gallo, Juan Carlos Robles Estrada', 2022, 'Veterinaria México OA', '10.22201/fmvz.24486760e.2022.1088', 'https://doi.org/10.22201/fmvz.24486760e.2022.1088', 'https://veterinariamexico.fmvz.unam.mx/index.php/vet/article/download/1088/867', NULL, NULL, 27, NULL, 'other', 1, 'cc-by', 'Bruises threaten the welfare of cattle because they cause pain, suffering, and stress during the pre-slaughter stage. Thus, we used meta-analyses to estimate the prevalence of carcass bruising in cattle from the American continent, determined the characteristics of the bruises, and calculated the odds ratio (OR) of risk factor categories associated with bruising. We searched electronic databases to retrieve primary studies conducted in the American continent, which reported cattle carcass bruising, analyzed the size, location, shape, and age of the bruises, and assessed risk factors for bruising. We included 46 studies from nine countries comprising 928 447 cattle carcasses with an overall prevalence of 59.5 % (95 % CI: 51.9 – 66-9) and 2.9 (range 3.4 – 7.4) bruises per carcass in average. The prevalence doubled from 30.7 % during 1991 – 2000 to 64.2 % during 2011 – 2020. Fresh, small-sized bruises of the lowest severity and located mainly in the hindquarter were highly prevalent (37.5 – 66.4 %). The removed meat due to bruising ranged 0.11 – 1.12 kg/carcass with an accumulated weight of condemned meat between 15.6 – 647 kg. Among intrinsic factors, older cattle, dairy cattle, and female cattle had greater odds of bruising (OR=1.57 – 1.98). For extrinsic factors, the odds for bruising increased 1.4 – 2.2 in cattle sourced from auction markets and exposed to poor handling, suboptimal transportation conditions, and deficient facilities. In cattle from America, bruises are a concern because their prevalence is growing and 60 % of cattle assessed in the studies suffered a bruise. Improving facilities and transportation conditions together with proper training of the personnel during the handling and transportation of the cattle will reduce bruising incidence.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6ea3624a-65cf-49d0-8125-0c836904900d', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Surveillance of non-fatal agricultural injuries among farm operators in the Central States region of the United States', 'Ketki Patel', 2016, 'DigitalCommons@UNMC', NULL, 'https://digitalcommons.unmc.edu/etd/141', 'https://digitalcommons.unmc.edu/context/etd/article/1141/viewcontent/COMPLIANT_unmc_etd_1141.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ceb448f5-3803-403a-88cc-2de8e5118b1b', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'The effects of arthritis, mobility, and farm task on injury among older farmers', 'Karen L. Heaton, Andrés Azuero, Jennan Atkins Phillips, Herretta Pickens, Deborah B. Reed', 2012, 'Nursing Research and Reviews', '10.2147/nrr.s28122', 'https://doi.org/10.2147/nrr.s28122', 'https://www.dovepress.com/getfile.php?fileID=12720', NULL, NULL, 8, NULL, 'other', 1, 'cc-by-nc', 'The current study was conducted by performing secondary analysis of data drawn from a study of sustained work indicators of older farmers. The primary outcome variable was the reported occurrence or non-occurrence of injuries because of farm work in the past year. There were three explanatory variables of interest: (1) whether respondents reported ever having been diagnosed with arthritis/rheumatism by a medical doctor; (2) whether participants reported having mobility problems; and (3) a farm task injury risk index. Additional explanatory variables included the estimated number of days spent on farming activities in the past year, as well as demographic characteristics such as age, sex, and race. Institutional review board approvals were obtained for the original study prior to data collection, and for the current study prior to secondary analysis of data. Descriptive statistics were calculated for the outcome and explanatory variables. Initial multivariable longitudinal models for the occurrence of injuries were fitted with the explanatory variables. Odds ratios for the effects of interest were calculated using the final models. A longitudinal model was fitted using data in waves 1, 3, and 5, with a farm task injury risk index as outcome variable and wave, sex, age, race, and estimated number of days spent on farming activities in the past year as explanatory variables for exploration of the relationship between the farm task injury risk index and these variables. In this group of older farmers, aging was protective for injury, and was associated with decreased farm task injury risk index. Arthritis/rheumatism was associated in our study with occurrence of injury because of farm work across all four waves. Our results indicated that farmers with mobility problems were twice as likely to experience injuries because of farm work compared to farmers with no mobility problems. Increased farm task injury risk index was associated with a 40% increase in odds for the occurrence of injury due to farm work. In this study of older farmers, the type of work, and not the amount of work was significantly associated with injury risk. Implications for future studies of farm injury include the need for nurse researchers and others to incorporate objective validated measures of mobility and health care provider diagnoses of arthritis, and arthritis type. Nurse researchers should proceed with ongoing evaluation of the farm task injury risk index to determine its validity, reliability, and usefulness as a predictor of farm injuries. In the practice setting, nurses may apply findings from this study to provide injury prevention teaching to older farmers and their families. For example, discussions of the more risky farm tasks, injury prevention strategies, and treatment modalities including those that promote improved mobility should be targeted to older farmers with arthritis and actual or potential mobility issues. Ultimately, these nursing research and practice efforts may lead to preservation of function, and decreased injury risk and severity among older farmers.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4d22788-6314-44bf-aee1-bbb50ea61f40', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Preventing and Investigating Horse-Related Human Injury and Fatality in Work and Non-Work Equestrian Environments: A Consideration of the Workplace Health and Safety Framework', 'Meredith Chapman, Kirrilly R. Thompson', 2016, 'Animals', '10.3390/ani6050033', 'https://doi.org/10.3390/ani6050033', 'https://www.mdpi.com/2076-2615/6/5/33/pdf?version=1462521453', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'It has been suggested that one in five riders will be injured due to a fall from a horse, resulting in severe head or torso injuries. Attempts to reduce injury have primarily focussed on low level risk controls, such as helmets. In comparison, risk mitigation in high risk workplaces and sports is directed at more effective and preventative controls like training, consultation, safe work procedures, fit for purpose equipment and regular Workplace Health and Safety (WHS) monitoring. However, there has been no systematic consideration of the risk-reduction benefits of applying a WHS framework to reducing horse-related risks in workplaces, let alone competition or leisure contexts. In this article, we discuss the different dimensions of risk during human-horse interaction: the risk itself, animal, human and environmental factors and their combinations thereof. We consider the potential of the WHS framework as a tool for reducing (a) situation-specific hazards, and (b) the risks inherent in and arising from human-horse interactions. Whilst most-if not all-horses are unpredictable, the majority of horse-related injuries should be treated as preventable. The article concludes with a practical application of WHS to prevent horse-related injury by discussing effective evidence-based guidelines and regulatory monitoring for equestrian sectors. It suggests that the WHS framework has significant potential not only to reduce the occurrence and likelihood of horse-related human accident and injury, but to enable systematic accident analysis and investigation of horse-related adverse events.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5c4a0fe0-2c9a-44b3-8ecc-e8ee2a486104', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Recommendations for the design of new, safe and efficient cattle handling systems (Technical Note TN565)', 'Scottish Agricultural College (SAC) / SRUC', 2004, 'SRUC (Scotland''s Rural College)', NULL, 'https://www.sruc.ac.uk/', 'https://www.sruc.ac.uk/media/s4hiqino/tn565-cattle-handling-systems.pdf', NULL, NULL, 6, NULL, 'other', 4, '© SRUC; free to download', 'A six-page Scottish technical note written explicitly around maximising human and animal safety alongside movement efficiency, drawing on a survey of Scottish producers plus US and Australian research. Advisory. Its handler-protection rules include designating a cattle-free safe working area around the crush, enabling a handler to operate the head yoke while standing at the rear of the crush, fitting the forcing gate with an automatically catching non-return latch so it cannot be pressed back against the handler, controlling the sorting gate by a lever on a universal joint so the handler need not stand in front of the animal, and placing the raised walkway on the inside radius of a curved race. Dimensions: collecting pens of about 30 cows, roughly 15 m long by 3.5-4.0 m wide; forcing pens handling 8-10 cattle with a 3 m forcing gate and one wall converging at 30 degrees; race curve radius not below 5 m with a minimum 5 m section; race side height 1.52 m for British and 1.67-1.83 m for continental breeds; race width 40 mm wider than the largest animal, giving 660-710 mm for adult cows and 510 mm for calves, with 150 mm inserts for calves; at least 6 m of unobstructed space visible beyond the crush; sorting gates about 3 m long; and loading ramps limited by a 22 degree slip angle, remedied by a 0.5 m raised platform giving a maximum 15 degree (1 in 3.54) ramp, with 400 mm minimum stair tread width and a 1.5 m docking area.', '{safety,dimensions,scotland,catwalks,yard-design}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d11fe519-50f3-42c5-86c5-c03956c50aa4', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Risk factors for work-related injury among farm workers: a 1-year study', 'Ana Ines Molineri, Marcelo Lisandro Signorini, Héctor D. Tarabla', 2015, 'Rural and Remote Health', '10.22605/rrh2996', 'https://doi.org/10.22605/rrh2996', 'https://www.rrh.org.au/journal/download/pdf/2996/', NULL, NULL, 8, NULL, 'other', 1, 'cc-by', 'A 1-year prospective study was carried out to look for risk factors of farm-related injuries in Egusquiza, Santa Fe (Argentina).Information on demographic characteristics and occupational accidents was collected on (N=110, n=78) farm workers by means of personal interviews using a structured questionnaire.Monthly telephone contact was then maintained with the workers for 1 year to document all farm-related injuries.Data analysis included incidence rate, χ 2 and logistic regression.Sixty-nine farm-related injuries were reported during the study period, six injuries being the maximum number affecting one worker.A total of 46.3% of the workers suffered at least one injury during the year.The incidence rate was 7.5 injuries/100 individual-month at risk.Medical assistance was needed in 26.8% of the cases and 5.8% of the injuries caused at least 1 day off work.Hospitalization for at least 1 day was required for 2.9% of the injured workers.Previous work-related injury in the family (p=0.005)(odds ratio (OR)=4.6,95% confidence interval (CI)=1.6-13.3)and worker''s activity (p=0.021)(OR=3.7,95%CI=1.2-11.6)were associated with the dependent variable work injury.Agricultural and livestock farming are of great importance for the national economy.Workers'' training on farm safety may play a key role to prevent work-related injuries and diseases.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d42bc756-63c4-4188-bbfd-f5ae845b2143', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Safe and Low Stress Cattle Handling', 'Farm Safety Manitoba (Manitoba Farm Safety Program)', 2023, 'Farm Safety Manitoba', NULL, 'https://farmsafemanitoba.ca/', 'https://farmsafemanitoba.ca/wp-content/uploads/2023/02/Safe-and-Low-Stress-Cattle-Handling.pdf', NULL, NULL, 31, NULL, 'prairies', 3, 'industry/agency publication, free to read', 'A prairie farm-safety agency presentation that packages low-stress handling explicitly as an occupational-safety intervention rather than a welfare one, which is the framing a design-flagging tool is making. Useful as evidence that a Canadian safety association endorses the flight zone, point of balance and blind spot rules as injury-prevention measures, and as a plain-language source for operator-facing wording. Contains no original measurement.', '{safety,low-stress,handling-behaviour,prairies}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dea71f9d-3542-4e97-911b-04557183c26f', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Safe Cattle Handling (Information Sheet WSNZ_2284_JUN 16)', 'WorkSafe New Zealand', 2016, 'WorkSafe New Zealand', NULL, 'https://www.worksafe.govt.nz/topic-and-industry/agriculture/working-with-animals/working-with-cattle/safe-cattle-handling-fact-sheet/', 'https://www.worksafe.govt.nz/dmsdocument/1064-safe-cattle-handling-fact-sheet', NULL, NULL, 3, NULL, 'other', 4, 'Crown copyright (New Zealand); free to download', 'WorkSafe New Zealand''s surviving cattle-handling guidance; the fuller ''Safe cattle handling - good practice guidelines'' PDF (dmsdocument 194) has been WITHDRAWN and now redirects to a no-longer-available notice, with readers pointed to saferfarms.org.nz/guides. Advisory but formally accepted: ''WorkSafe NZ accepts these recommendations as current industry good practice'' in support of the Health and Safety at Work Act 2015 PCBU duty to ensure health and safety so far as reasonably practicable, a close analogue of Alberta OHS Act s.3(1). It contains no dimensions but several directly codable design and procedure rules: plan an escape route in advance when working cattle in the yards; never get in the race with large cattle and do not put arms, head or legs through the race walls; make sure cattle have room to move in the forcing pen; pack the race firmly; use a safe and well-maintained catwalk if there is one; install kick rails and stay behind them; never stand in front of a slip rail or hock bar; never dehorn large cattle alone in the race; work from above the head when ear-tagging; and if cornered by a bull with no escape route, step sideways out of his best vision.', '{safety,worksafe-nz,escape-routes,withdrawn-predecessor}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1737a289-4626-4e6e-8b48-ca0ae41ef785', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Seroprevalence and Risk Factors Related to Bovine Brucellosis in Continental Ecuador', 'Garrido-Haro A, Barrionuevo-Samaniego M, Moreno-Caballeros P, Burbano-Enriquez A, Sánchez-Vázquez MJ, Pompei J, Humblet MF, Ron-Román J', 2023, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens12091134', 'https://doi.org/10.3390/pathogens12091134', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10536672.1/PMC10536672.1.pdf', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Bovine brucellosis is a worldwide zoonotic contagious disease. According to World Animal Health Information System reports Ecuador has presented an increasing number of bovine brucellosis outbreaks in the continental territory over the past years (756 in 2018 versus 964 in 2021), generating economic losses for producers and causing a risk to public health. A cross-sectional study was conducted to investigate the seroprevalence of bovine brucellosis and associated risk or protective factors between May and June 2018. This stratified random study was implemented in 290 cattle herds located in the 23 provinces of continental Ecuador, which represents a total of 3737 cows aged 24 months or older. A competitive ELISA was used to detect Brucella antibodies. Simultaneously, an epidemiological survey was implemented to assess the brucellosis risk or protective factors. The apparent prevalence of bovine brucellosis at the herd level was 21.3% (95% CI: 16.8-26.6) and 6.2% (95% CI: 5.5-7) at the animal level. Univariate and multivariate logistic regression analyses were performed to determine the relationship between the potential factors associated with the presence of bovine brucellosis. The risk factors identified after multivariate analysis were a surface in ha per herd > 70 ha (OR = 2.73; 95% CI: 1.18-6.32) and the number of parturitions per animal (two or more with OR ≥ 1.8 and p-value ≤ 0.047). On the contrary, the protective factors were the region (farms located in the eastern region) and the absence of reported clinical signs. In addition, in herds where extensive production predominates, farmers have a low level of knowledge, and the farm biosecurity level is low. These results can guide the authorities in managing the risk factors identified, understanding the current epidemiological situation in Ecuador, improving the bovine brucellosis control program and food safety, as well as increase the one-health approach.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ed763a3-1cc3-4450-98af-c6e0204eba3b', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'The response of beef cattle to noise during handling', 'J. L. Waynert, J. M. Stookey, K. S. Schwartzkopf-Genswein, J. M. Watts, C. S. Waltz', 1999, 'Applied Animal Behaviour Science (Elsevier)', '10.1016/S0168-1591(98)00211-1', 'https://www.sciencedirect.com/science/article/abs/pii/S0168159198002111', NULL, NULL, NULL, NULL, NULL, 'prairies', 4, 'unknown (publisher paywall; University of Saskatchewan authors)', 'The study behind the widely repeated claim that human shouting is more stressful to cattle than equipment noise. Trial 1 assigned 29 treatment-naive heifers to pre-recorded handling noise consisting of humans shouting plus metal clanging (n=14) or to silence (n=15). Trial 2 split the noise into pre-recorded human shouting (n=15) or metal-on-metal clanging (n=15). Heart rate was recorded by remote telemetry. The reported conclusion is that the sound of humans shouting was more alarming than the sound of metal striking metal, judged by heart rate and movement. I could not obtain the full text, so no cortisol values or p-values are confirmed, and this study did not test an electric prod. Saskatchewan-authored, so directly relevant to a prairie operation.', '{handling-behaviour,low-stress,no-free-pdf,noise,safety}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c3295d0-1969-4209-b4a4-b1e50d9b9747', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Toolbox Talk: Loading and Unloading Livestock', 'AgSafe Alberta', 2023, 'AgSafe Alberta', NULL, 'https://agsafeab.ca/resources/', 'https://agsafeab.ca/wp-content/uploads/2023/08/Toolbox-Talk-Loading-and-Unloading-Livestock.pdf', NULL, NULL, 2, NULL, 'alberta', 3, 'free to download', 'An Alberta crew-briefing sheet covering the loading and unloading task, which every national source identifies as among the most dangerous activities in a yard. Advisory, with no dimensions. It is the Alberta-local counterpart to the ramp and loading-area guidance in HSE AIS35, the Irish HSA marts and lairages sheet and SafeWork SA, and is useful as the locally recognised reference when a corral-design tool flags a loading area that requires a person to stand between animal and vehicle.', '{safety,alberta,agsafe,loading}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('efe395d7-b434-4fc1-8e2d-7447daf456fa', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Toolbox Talk: Safer Animal Handling for People and Livestock (2022-ALL-0018)', 'AgSafe Alberta', 2022, 'AgSafe Alberta', NULL, 'https://agsafeab.ca/resources/', 'https://agsafeab.ca/wp-content/uploads/2022/10/Safer-Animal-Handling-for-People-and-Livestock.pdf', NULL, NULL, 2, NULL, 'alberta', 3, 'free to download', 'A two-page Alberta crew-briefing sheet, the most directly local advisory document on handling-facility condition. Advisory. Its facility content: non-slip flooring in holding and handling facilities keeps everyone on their feet, with grooved patterns in concrete preferred to rough broom finishes because broom finishes wear smooth over time; gates, fences and chutes should be checked for sharp edges, weaknesses and damage, since a protruding nail injures worker or animal and a gate that cannot close when needed can have severe consequences. It also covers the 20-30 minutes an excited animal needs to settle, restricting work to trained handlers familiar with livestock behaviour, staying out of the blind spot, not chasing escaped cattle, scheduling handling around heat and cold stress, and lighting and noise effects on movement including shadows causing refusal. It specifies no dimensions.', '{safety,alberta,agsafe,flooring,maintenance}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa53e374-7463-4c6d-801d-54162c69d925', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Tractor Driving Among Kentucky Farm Youth: Results from the Farm Family Health and Hazard Surveillance Project', 'Steven R. Browning, Susan Westneat, R. Szeluga', 2001, 'Journal of Agricultural Safety and Health', '10.13031/2013.5439', 'https://doi.org/10.13031/2013.5439', 'https://uknowledge.uky.edu/epidemiology_facpub/12', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df33b1c9-995a-4f5e-8b41-c88b9ecf5e5a', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Upper Limb’s Injuries in Agriculture: A Systematic Review', 'Nicola Mucci, Veronica Traversini, Lucrezia Ginevra Lulli, Antonio Baldassarre, Raymond Paul Galea, Giulio Arcangeli', 2020, 'International Journal of Environmental Research and Public Health', '10.3390/ijerph17124501', 'https://doi.org/10.3390/ijerph17124501', 'https://www.mdpi.com/1660-4601/17/12/4501/pdf?version=1592904008', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Agriculture is one of the most hazardous economic sectors, and it accounts for many accidents and occupational diseases every year. In Italy, about one-third of injuries involve the upper extremity, with long-term consequences for the workers and economic damage for agricultural companies and farms. This systematic review describes upper limb injuries among farmworkers, especially hand injuries, and highlights the main dangerous risk factors. Literature review included articles published in the major databases (PubMed, Cochrane Library, Scopus), using a combination of some relevant keywords. This online search yielded 951 references; after selection, the authors analyzed 53 articles (3 narrative reviews and 50 original articles). From this analysis, it appears that younger male farmers are mostly involved, especially in the harvesting season. The upper limb and hand are often the body parts that sustain most damage as these are mostly involved in driving tractors or tools. The most frequent type of lesions are open wounds, lacerations, fractures, strains, and overexertion lesions. Sometimes, a distracting element (such as mobile phone use, quarrels, working hours load) is present; poor use of protective devices and lack of safety design in tools can also increase the risk of accidents. For these reasons, in the agricultural sector, a system of health promotion and good practices is needed to promote workers'' awareness of the sources of risk, highlight more dangerous situations and apply organizational behavioral measures.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('499a8e4d-544e-424e-ae15-295223050b8a', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'VBP+ Standards (Verified Beef Production Plus), updated June 2026', 'Verified Beef Production Plus (Canadian Cattle Association)', 2026, 'Verified Beef Production Plus', NULL, 'https://verifiedbeef.ca/vbp-standard/', 'https://verifiedbeef.ca/wp-content/uploads/2026/08/VBP-Standards-Final-Version-06.29.2026.pdf', NULL, NULL, 38, NULL, 'canada', 4, 'free to download', 'The current publicly available standards document for Canada''s on-farm food safety, animal care and environmental stewardship certification, enforced contractually through Corrective Action Requests and Critical Control Points. Its Animal Care and Welfare handling expectation states methods should minimise stress ''through the use of appropriate equipment, minimal physical contact, trained personnel and appropriate footing and lighting'', with the rationale noting handling affects animal welfare, meat quality and human safety and that the intent is to ensure ''the safety of people and animals''. It names human safety more explicitly than the NFACC Code but attaches no design criterion, specifies no dimensions, and does not mention electric prods at all. Deeper handling detail sits in the VBP+ Animal Care Manual (Section 05), which is published only as an issuu embed and not as a downloadable PDF.', '{safety,canada,vbp-plus,certification,no-dimensions}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0de58d5e-5987-40ef-8852-69b675f8eb19', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'West Nile Virus Seroprevalence Among Outdoor Workers in Southern Italy: Unveiling Occupational Risks and Public Health Implications', 'Stufano A, Schino V, Sacino G, Ravallese R, Ravallese R, De Benedictis L, Morea A, Iatta R', 2025, 'Viruses', '10.3390/v17030310', 'https://doi.org/10.3390/v17030310', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11946618.1/PMC11946618.1.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'BackgroundWest Nile virus (WNV) is a mosquito-borne RNA virus, with birds as reservoirs and humans as incidental hosts. WNV often causes asymptomatic infections, but severe neuroinvasive disease occurs in fewer than 1% of human cases. Recent climatic changes and occupational exposure have increased its spread, particularly in Southern Italy. This study aimed to assess WNV seroprevalence and occupational risks among outdoor workers to guide targeted public health interventions.MethodsThis cross-sectional study was conducted in the Apulia region, southeastern Italy, from November 2023 to April 2024. Participants completed a detailed questionnaire on socio-demographics, occupational exposure, travel history, and health symptoms. Blood samples were analyzed using enzyme-linked immunosorbent assay (ELISA) and neutralization assays to detect WNV-specific antibodies.Results250 outdoor workers in southeastern Italy were recruited, including agricultural workers, veterinarians, forestry workers, and livestock breeders. The latter showed the highest WNV prevalence at 6.5%. Protective measures such as repellent use (β = -0.145, OR = 0.95, p = 0.019) and personal protective equipment (PPE) usage (β = -0.12, OR = 0.94, p = 0.04) significantly reduced the likelihood of WNV infection.ConclusionsThe study highlights the significant occupational risk posed by WNV to outdoor workers involved in livestock breeding in Southern Italy, likely due to their frequent exposure to mosquito-prone environments. Tailored public health strategies and education programs are needed to protect high-risk outdoor workers from WNV, amidst the backdrop of changing climatic conditions that favor increased transmission.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c1477060-48a5-4523-a738-e666925c2de6', '0b11fb78-9d7f-4f36-9cbf-2b0671987901', 'Alberta wheat [Japanese]', 'Government of Alberta', 2018, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/alberta-wheat-japanese', 'https://open.alberta.ca/dataset/b0959ed5-f0e9-490b-b603-f52454f09100/resource/1921c41c-ed25-494c-93b6-1f5c4278cc36/download/af-alberta-wheat-2018-japanese.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Alberta has established a reputation as a producer of high quality wheat. This brochure provides information for international importers and stakeholders on Alberta''s wheat sector.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('381e4c6b-7d0a-4799-93e8-6f0a1c6318d4', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Wolf presence in the ranch of origin: impacts on temperament and physiological responses of beef cattle following a simulated wolf encounter', 'R. F. Cooke, D. W. Bohnert, M. M. Reis, B. I. Cappellozza', 2013, 'Journal of Animal Science (American Society of Animal Science)', '10.2527/jas.2013-6777', 'https://academic.oup.com/jas/article/91/12/5905/4717343', 'https://entomology.oregonstate.edu/sites/agscid7/files/eoarc/attachments/792.pdf', NULL, NULL, 9, NULL, 'northern_plains', 3, 'author copy on an Oregon State University (EOARC) server, free to read', 'One hundred multiparous pregnant Angus-cross cows, 50 wolf-naive (Burns, Oregon) and 50 from a wolf-depredated Idaho herd, were commingled for 50 days then exposed for 20 minutes to a simulated predator encounter consisting of wolf-urine-soaked plugs on the fence, continuous wolf howls and three leashed dogs walked along the pen perimeter, followed by 20 seconds of dog exposure while restrained in a squeeze chute. Chute score, temperament score and plasma cortisol all increased (P <= 0.01) in the wolf-experienced cows but did not change in the naive cows (P >= 0.19); vaginal temperature rose more in the wolf-experienced group (P = 0.03). This is the only controlled cattle study I could verify that measures the effect of dogs on crush score and cortisol, and the effect was conditional on prior predator experience.', '{safety,dogs,handling-behaviour,temperament,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('86380284-e64a-47f3-8819-e4878fb3f53c', 'ed618f81-829a-4160-8785-dfe3c38c9985', 'Worker Injuries Involving the Interaction of Cattle, Cattle Handlers, and Farm Structures or Equipment', 'Shannon Fox, Mitch Ricketts, J. E. Minton', 2015, 'Journal of Agricultural Safety and Health', '10.13031/jash.21.10221', 'https://doi.org/10.13031/jash.21.10221', 'https://krex.k-state.edu/bitstreams/1088608c-c5df-4f94-aab6-c57f7576feec/download', NULL, NULL, 29, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e2f2d912-d496-45a1-9972-2d939b82eed8', 'd1af0758-6595-46af-9c93-b816db1bf60c', '3-Nitrooxypropanol Decreased Enteric Methane Production From Growing Beef Cattle in a Commercial Feedlot: Implications for Sustainable Beef Cattle Production', 'Aklilu W. Alemu, Liana K. D. Pekrul, Adam L. Shreck, Calvin W. Booker, Sean M. McGinn, Maik Kindermann, Karen Ann Beauchemin', 2021, 'Frontiers in Animal Science', '10.3389/fanim.2021.641590', 'https://doi.org/10.3389/fanim.2021.641590', 'https://www.frontiersin.org/articles/10.3389/fanim.2021.641590/pdf', NULL, NULL, 13, NULL, 'southern_alberta', 5, 'cc-by', 'Effects of the investigational methane (CH4) inhibitor 3-nitrooxypropanol (3-NOP) on animal performance, health and enteric CH4 production of beef cattle were evaluated in a commercial feedlot. Two concurrent studies were conducted: a large pen study (4,048 cattle, eight pen replicates per experimental group) to measure animal performance and health and a small pen study (a subset of 50 cattle from the large pen study, n = 25 per experimental group) to measure enteric CH4 emissions. Within the study, animals (body weight ± SD, 282 ± 8 kg) were assigned in a completely randomized design to one of two groups: control, fed a backgrounding diet (70% corn or barley silage, 30% steam-flaked barley grain concentrate; dry matter (DM) basis) and 3-NOP, fed the backgrounding diet containing 3-NOP. The treatment group in the large pen study was adapted to 3-NOP (12 ± 3 d) before receiving the final target level of 200 mg/kg of DM, which was fed for 108 ± 8 d. Animals in the small pen CH4 emissions study received a basal diet or a basal diet with 3-NOP, with the dose increased every 28 d: low (150 mg/kg DM; 1.27 g/d), medium (175 mg/kg DM; 2.25 g/d), and high (200 mg/kg DM; 2.75 g/d). Intake in the small pens was monitored by electronic feeding bunks and CH4 was measured using the GreenFeed system. In the large pen study, total weight gained, average daily gain, and animal health variables were not affected by 3-NOP, but DM intake (DMI) tended to decrease (P = 0.06) by 2.6% relative to control (8.07 kg/d), while gain:feed ratio tended to be improved (P = 0.06) by 2.5% relative to control (0.161 kg weight gain/kg DMI). In the small pen study, average daily consumption of 3-NOP increased with inclusion rate whereas average DMI was decreased by 5.4% (P = 0.02) compared with control (10.4 kg/d). On average, addition of 3-NOP decreased (P = 0.001) CH4 emissions (g/d) by 25.7% and yield (g CH4/kg DMI) by 21.7%. In conclusion, supplementing a backgrounding diet with 3-NOP decreased CH4 yield and tended to improve feed efficiency of beef cattle fed in a commercial feedlot with no negative impacts on animal health.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c5ff7ea-f226-414a-9187-f6db77fda24e', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'A cross-classified and multiple membership Cox model applied to calf mortality data', 'Elghafghuf A, Stryhn H, Waldner C', 2014, 'Preventive veterinary medicine', '10.1016/j.prevetmed.2014.03.012', 'https://doi.org/10.1016/j.prevetmed.2014.03.012', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7114250.1/PMC7114250.1.pdf', NULL, NULL, 11, NULL, 'prairies', 4, 'open access (Europe PMC)', 'A cross-classified and multiple membership Cox model was applied to calf mortality data from Western Canada, where 23,409 calves from 174 herds were followed for up to 180 days after calving. The herds were cross-classified by 49 veterinary clinics and 9 ecological regions and in a multiple membership relation to the veterinary clinics, resulting in a 3-level cross-classified and multiple membership data structure. The model was formulated in a mixed-effects Poisson model framework with normally distributed random effects, and was fitted to the data by Bayesian Markov Chain Monte Carlo (MCMC) estimation. Important fixed effects included whether the calf was a twin, calf gender, assistance at calving, cow age, average temperature the first week after calving, the percentage of the herd that had already calved, whether calf shelters were provided, whether cow-calf pairs were moved to a nursery area, and whether any animals were purchased into the herd at or near the time of calving. The analysis demonstrated a greater variation among herds than among both ecological regions and veterinary clinics. Further, a simulation study for a setting similar to the real data gave evidence that the used approach provides valid estimates.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a28714ab-a1d7-40e4-a125-b4d7bd64e09a', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'A proposal to investigate the economic impact of respiratory disease in the feedlot', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/proposal-to-investigate-the-economic-impact-of-respiratory-disease-in-the-feedlot', 'https://open.alberta.ca/dataset/20cf872c-d5f8-4fe2-a364-b06e5ae7249e/resource/26a09da5-518e-4060-946b-313b11127068/download/163010363477-a-proposal-to-investigate-the-economic-impact-of-respiratory-disease-in-the-feedlot.pdf', NULL, NULL, 70, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This trial involved 512 beef calves in a commercial research feedlot and compared 256 calves classified as sick with bovine respiratory disease (BRD) to 256 classified as well, measuring performance parameters such as average daily gain, dry matter intake, feed conversion, BRD treatment and death loss, carcass traits, and net profit per pen. The study partitioned data by time intervals and found no significant differences between sick and well groups in average daily gain, dry matter intake, feed efficiency, carcass characteristics or net profit per pen. The BRD treatment rates were 6.6 per cent in the sick group and 4.7 per cent in the well group, while mortality rates were 0.78 per cent and 0.39 per cent, with no deaths directly attributable to BRD. The results indicated that BRD did not significantly impact performance or economic outcomes in this trial. The study concluded that a stronger disease challenge may be needed to demonstrate economic impacts of BRD in future research.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4bb6507-8cc1-4d3e-b399-1d074e220049', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Antimicrobial Susceptibility of Bacteria That Cause Bovine Respiratory Disease Complex in Alberta, Canada', 'R. Michele Anholt, Cassidy L. Klima, Nick D. Allan, Heather Matheson-Bird, Crystal Schatz, Praseeda Ajitkumar, Simon J. G. Otto, Delores Peters', 2017, 'Frontiers in Veterinary Science', '10.3389/fvets.2017.00207', 'https://doi.org/10.3389/fvets.2017.00207', 'https://www.frontiersin.org/articles/10.3389/fvets.2017.00207/pdf', NULL, NULL, 11, NULL, 'alberta', 4, 'cc-by', 'Bovine respiratory disease (BRD) is the most important illness of feedlot cattle. Disease management targets the associated bacterial pathogens, Mannheimia haemolytica, Mycoplasma bovis, Pasteurella multocida, Histophilus somni, and Trueperella pyogenes. We conducted a cross-sectional study to measure the frequencies of antimicrobial-resistant BRD pathogens using a collaborative network of veterinarians, industry, government, and a diagnostic laboratory. Seven private veterinary practices in southern AB Alberta collected samples from both living and dead BRD-affected animals at commercial feedlots. Susceptibility testing of 745 isolates showed that 100% of the M. haemolytica, M. bovis, P. multocida, and T. pyogenes isolates and 66.7% of the H. somni isolates were resistant to at least one antimicrobial class. Resistance to macrolide antimicrobials (90.2% of all isolates) was notable for their importance to beef production and human medicine. Multi-drug resistance (MDR) was high in all target pathogens with 47.2% of the isolates resistant to four or five antimicrobial classes and 24.0% resistance to six to nine classes. We compared the MDR profiles of isolates from two feedlots serviced by different veterinary practices. Differences in the average number of resistant classes were found for M. haemolytica (p < 0.001) and P. multocida (p = 0.002). Compared to previous studies, this study suggests an increasing trend of resistance in BRD pathogens against the antimicrobials used to manage the disease in ABAlberta. For the veterinary clinician, Tthe results emphasize the importance of ongoing susceptibility testing of BRD pathogens to inform treatment protocols. and, the need for additional research to develop Surveillance studies that collect additional epidemiological information and manage sampling bias will be necessary to develop strategies to limit the spread of resistance.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05acfd99-4769-418d-9cfc-b14f7fb2d6b3', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Antimicrobial Use on 36 Beef Feedlots in Western Canada: 2008–2012', 'Stephanie A. Brault, Sherry J. Hannon, Sheryl Gow, Brian Nelson Warr, Jessica S. Withell, Jiming Song, Christina M. Williams, Simon J. G. Otto', 2019, 'Frontiers in Veterinary Science', '10.3389/fvets.2019.00329', 'https://doi.org/10.3389/fvets.2019.00329', 'https://www.frontiersin.org/articles/10.3389/fvets.2019.00329/pdf', NULL, NULL, 16, NULL, 'alberta', 4, 'cc-by', 'The accurate quantification of antimicrobial use (AMU) in production animals is critical for monitoring trends in exposure to antimicrobial drugs (AMD) over time and examining potential associations with antimicrobial resistance in bacteria. In this study, a census sample of cattle was used to quantify individually-dosed and in-feed AMU as both numbers of animal daily doses (nADD) and total grams of AMD (gAMD) used in cattle placed in 36 western Canadian feedlots between 1-November, 2008 and 31-October, 2012; representing about 21.5% of fed cattle in Canada during that time period. Of the ~2.6 million cattle placed during the 48-month period, 45% were calves, 63% were male, 62% arrived in the fall or winter, and 39% were assessed as high risk for developing bovine respiratory disease (BRD). The proportion of cattle categorized as high risk (HR) for developing BRD was consistent over the 4 years of placement cohorts. Both medically important AMU and ionophore use were summarized but presented separately. A decrease in AMU was observed over the study period, both as nADD and total gAMD, which was primarily driven by a decline in the in-feed administration of tetracyclines. Most in-feed AMU was directed toward prevention and control of liver abscesses. The majority of individually dosed AMU was administered as metaphylaxis to address BRD risks, with category III AMD (medium importance to human medicine as categorized by Health Canada Veterinary Drugs Directorate) used most frequently. Not surprisingly, risk level for developing BRD influenced parenteral AMD exposures, with 95% of cattle categorized as being HR for developing BRD receiving individually dosed AMD compared to 59% of cattle categorized as being low risk (LR) for developing BRD. Cattle categorized as HR for developing BRD were more likely to receive macrolides for BRD metaphylaxis compared to cattle categorized as LR for developing BRD, and cattle categorized as LR for developing BRD were more likely to receive tetracycline for the same purpose. In summary, these data provide an unprecedented representation of AMU in fed cattle in western Canada and direction for future monitoring of AMU in fed cattle.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e7e74b7-051f-4651-9715-2d201394b67e', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Assessing the value of Pasteurella haemolytica isolation from deep nasal swabs as a predictor of bovine respiratory disease in feedlot calves', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/assessing-the-value-of-pasteurella-haemolytica-isolation-from-deep-nasal-swabs-as-a-predictor-of', 'https://open.alberta.ca/dataset/40462b3e-6b2d-4ea1-8e02-143d0434878d/resource/85a13008-441e-4327-89cd-eb46cef1280c/download/163010413496-assessing-value-pasteurella-haemolytica-isolation-from-deep-nasal-swabs-predictor.pdf', NULL, NULL, 35, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study involved 512 recently weaned, auction market derived beef calves in a commercial research feedlot and investigated whether isolation of Pasteurella haemolytica from deep nasal swabs was associated with the development of bovine respiratory disease (BRD). There was no significant association between initial Pasteurella haemolytica isolation from nasal swabs upon arrival and later development of BRD, but calves that were culture positive for Pasteurella haemolytica four to six days after arrival were more likely to develop BRD. Specifically, calves positive for Pasteurella haemolytica serotype A1 at four to six days were 2.8 times more likely to have BRD than culture negative calves. The study found that the sensitivities and predictive values of nasal swabs were low, indicating this method was a poor predictor of BRD in individual animals. These findings indicate that deep nasal swab cultures are not useful for identifying calves at high risk of developing BRD using this methodology.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('57d87a54-ef5e-41ca-a655-7d590517c080', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Auction market placement and a rest stop during transportation affect the respiratory bacterial microbiota of beef cattle', 'Muhammed Salah Uddin, K. S. Schwartzkopf-Genswein, Matthew Waldner, Daniela M Meléndez, Yan Dong Niu, Trevor W. Alexander', 2023, 'Frontiers in Microbiology', '10.3389/fmicb.2023.1192763', 'https://doi.org/10.3389/fmicb.2023.1192763', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10556482/pdf/fmicb-14-1192763.pdf', NULL, NULL, 16, NULL, 'southern_alberta', 5, 'cc-by', 'Background Bovine respiratory disease (BRD) is a significant health problem in beef cattle production, resulting in considerable economic losses due to mortalities, cost of treatment, and reduced feed efficiency. The onset of BRD is multifactorial, with numerous stressors being implicated, including transportation from farms to feedlots. In relation to animal welfare, regulations or practices may require mandatory rest times during transportation. Despite this, there is limited information on how transportation and rest stops affect the respiratory microbiota. Results This study evaluated the effect of cattle source (ranch-direct or auction market-derived) and rest stop duration (0 or 8 h of rest) on the upper respiratory tract microbiota and its relationship to stress response indicators (blood cortisol and haptoglobin) of recently weaned cattle transported for 36 h. The community structure of bacteria was altered by feedlot placement. When cattle were off-loaded for a rest, several key bacterial genera associated with BRD ( Mannheimia , Histophilus , Pasteurella ) were increased for most sampling times after feedlot placement for the ranch-direct cattle group, compared to animals given no rest stop. Similarly, more sampling time points had elevated levels of BRD-associated genera when auction market cattle were compared to ranch-direct. When evaluated across time and treatments several genera including Mannheimia, Moraxella, Streptococcus and Corynebacterium were positively correlated with blood cortisol concentrations. Conclusion This is the first study to assess the effect of rest during transportation and cattle source on the respiratory microbiota in weaned beef calves. The results suggest that rest stops and auction market placement may be risk factors for BRD, based solely on increased abundance of BRD-associated genera in the upper respiratory tract. However, it was not possible to link these microbiota to disease outcome, due to low incidence of BRD in the study populations. Larger scale studies are needed to further define how transportation variables impact cattle health.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b6198acf-9307-4bd1-97fc-fc78e3ba08ff', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Bloat in cattle [2008]', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2797515', 'https://open.alberta.ca/dataset/638afe30-158e-43ac-85cc-bdfb79c50eb4/resource/b1c0c5ad-c36b-4f23-8408-0bed9ef0cfd7/download/2008-420-60-1.pdf', NULL, NULL, 32, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This publication provides information on the causes, control and treatment of bloat in cattle and is intended for livestock producers, veterinarians, and agrologists. The authors have observed bloat produced under experimental conditions by feeding fresh alfalfa and bloat-causing feedlot diets. Bloat has also been observed under grazing conditions on alfalfa pastures. Although the information in this publication is oriented around livestock production in western Canada, the general principles are widely applicable, and the publication should provide valuable information for other regions. Bloat is a complex disease that is difficult to predict under field conditions. As a result, field observations have led to varied and conflicting theories about its causes. This publication presents well-established facts and consistent field observations based on collective experience. Recommendations are made on this basis and on research reports, general observations and on the experience of cattle producers.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c0b75b4c-a390-430d-ac16-c99ada8276dd', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Bovine respiratory disease in Alberta feedlots', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/bovine-respiratory-disease-in-alberta-feedlots', 'https://open.alberta.ca/dataset/695be8d3-15c8-4c82-a2cc-6eb59f30f11e/resource/45b255ab-3ae5-4bc8-bf64-20b60932719f/download/163010404891-bovine-respiratory-disease-in-alberta-feedlots.pdf', NULL, NULL, 22, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project established a three-year surveillance system beginning in September 1981 to examine how stress and management practices contribute to the incidence of bovine respiratory disease in Alberta feedlots. Technicians collected data from over 1,100 lots of feeder cattle, with 1,122 completed lots representing 127,820 head by August 1983. The study reported overall morbidity and mortality rates of 14.8 per cent and 0.9 per cent respectively, with calf-lots showing higher rates than yearlings. The database, managed using OSIRIS, MIDAS, and SPSS software, aimed to identify specific risk factors associated with disease development. Future analysis will use the compiled database to evaluate which management or environmental variables are linked to respiratory conditions in cattle.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('24d0ed76-ae08-448d-9622-cabbe50e9dd6', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Canadian 2021 H-type Bovine Spongiform Encephalopathy case associated with a novel E211K polymorphism in prion protein gene', 'Tahir W, Dudas S, Anderson R, Yang J, Bogart S, Santiago-Mateo K, Fang Y, Quaghebeur R', 2025, 'Prion', '10.1080/19336896.2025.2511933', 'https://doi.org/10.1080/19336896.2025.2511933', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12323412.1/PMC12323412.1.pdf', NULL, NULL, 14, NULL, 'southern_alberta', 4, 'cc by-nc', 'Bovine Spongiform Encephalopathy (BSE) is a fatal neurodegenerative disease in cattle which can be either classical BSE (C-BSE) or atypical BSE (including H-BSE and L-BSE). Here, we report the results of our analyses of an H-BSE case found in Canada in 2021, indicating restriction of the pathological agent (PrPSc) mainly to the central nervous system with no or occasional weak involvement of peripheral tissues. Importantly, a non-synonymous mutation at codon 211 of the PRNP gene was detected and confirmed to be present as a germline mutation. This is the first case of BSE in Canada with a predisposing E211K mutation.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2d58244d-f606-4903-85ce-5ce46e190b11', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Characterization of Shiga toxin - producing Escherichia coli infections in beef feeder calves and the effectiveness of a prebiotic in alleviating Shiga toxin - producing Escherichia coli infections', 'Baines D, Erb S', 2013, 'Irish veterinary journal', '10.1186/2046-0481-66-17', 'https://doi.org/10.1186/2046-0481-66-17', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC3850653.1/PMC3850653.1.pdf', NULL, NULL, 8, NULL, 'southern_alberta', 5, 'cc by', 'BackgroundIn the less-sensitive mouse model, Shiga toxin-producing Escherichia coli (STEC) challenges result in shedding that reflect the amount of infection and the expression of virulence factors such as Shiga toxins (Stx). The purpose of this study was to characterize the contribution of STEC diversity and Stx expression to shedding in beef feeder calves and to evaluate the effectiveness of a prebiotic, Celmanax®, to alleviate STEC shedding. Fecal samples were collected from calves at entry and after 35 days in the feedlot in spring and summer. STECs were evaluated using selective media, biochemical profile, serotyping and Stx detection. Statistical analysis was performed using repeated measures ANOVA and logistic regression.ResultsAt entry, non-O157 STEC were dominant in shedding calves. In spring, 21%, 14% and 14% of calves acquired O157, non-O157 and mixed STEC infections, respectively. In contrast, 45%, 48% and 46% of calves in summer acquired O157, non-O157 and mixed STEC infections, respectively. Treatment with a prebiotic, Celmanax®, in spring significantly reduced 50% of the O157 STEC infections, 50% of the non-O157 STEC infections and 36% of the STEC co-infections (P = 0.037). In summer, there was no significant effect of the prebiotic on STEC infections. The amount of shedding at entry was significantly related to the number and type of STECs present and Stx expression (r2 = 0.82). The same relationship was found for shedding at day 35 (r2 = 0.85), but it was also related to the number and type of STECs present at entry. Stx - producing STEC infections resulted in 100 to 1000 × higher shedding in calves compared with Stx-negative STECs.ConclusionsSTEC infections in beef feeder calves reflect the number and type of STECs involved in the infection and STEC expression of Stx. Application of Celmanax® reduced O157 and non-O157 STEC shedding by calves but further research is required to determine appropriate dosages to manage STEC infections.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3e05e0df-5fe9-4908-97d0-0cdbf3f0dd16', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Development and testing of a calf scours coronavirus vaccine', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/development-and-testing-of-a-calf-scours-coronavirus-vaccine', 'https://open.alberta.ca/dataset/e59cdbd2-b39b-4826-8110-285170ddd85c/resource/ac6f20b5-aef3-4b71-a49b-449a8748971b/download/0163010413504-development-and-testing-of-a-calf-scours-coronavirus-vaccine.pdf', NULL, NULL, 108, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated the epidemiology of coronavirus-related diarrhea in calves and evaluated diagnostic methods and vaccine development to prevent infection. Researchers developed diagnostic procedures using enzyme-linked immunosorbent assay (ELISA) to detect coronavirus and studied shedding patterns in diarrheic calves and normal cows, finding that up to 70 per cent of cows carried and shed the virus. Experimental coronavirus vaccines were prepared and tested in cattle and mice, and significant increases in antibody titers were achieved when the antigen was combined with a suitable adjuvant. However, poor responses were observed after booster doses given 35 days apart, and available commercial vaccines did not significantly increase antibody levels. The study concluded that further work is needed to optimize vaccination protocols and manage carrier detection in herds.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a642686b-ab59-405c-8483-1cd2cc63b6c5', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Development of a spore-based mucosal vaccine against the bovine respiratory pathogen Mannheimia haemolytica', 'Uddin MS, Guluarte JO, Abbott DW, Inglis GD, Guan LL, Alexander TW', 2023, 'Scientific reports', '10.1038/s41598-023-29732-4', 'https://doi.org/10.1038/s41598-023-29732-4', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10415371.1/PMC10415371.1.pdf', NULL, NULL, 11, NULL, 'southern_alberta', 5, 'cc by', 'Bovine respiratory disease (BRD) is a significant health issue in the North American feedlot industry, causing substantial financial losses due to morbidity and mortality. A lack of effective vaccines against BRD pathogens has resulted in antibiotics primarily being used for BRD prevention. The aim of this study was to develop a mucosal vaccine against the BRD pathogen, Mannheimia haemolytica, using Bacillus subtilis spores as an adjuvant. A chimeric protein (MhCP) containing a tandem repeat of neutralizing epitopes from M. haemolytica leukotoxin A (NLKT) and outer membrane protein PlpE was expressed to produce antigen for adsorption to B. subtilis spores. Adsorption was optimized by comparing varying amounts of antigen and spores, as well as different buffer pH and reaction temperatures. Using the optimal adsorption parameters, spore-bound antigen (Spore-MhCP) was prepared and administered to mice via two mucosal routes (intranasal and intragastric), while intramuscular administration of free MhCP and unvaccinated mice were used as positive and negative control treatments, respectively. Intramuscular administration of MhCP elicited the strongest serum IgG response. However, intranasal immunization of Spore-MhCP generated the best secretory IgA-specific response against both PlpE and NLKT in all samples evaluated (bronchoalveolar lavage, saliva, and feces). Since proliferation of M. haemolytica in the respiratory tract is a prerequisite to lung infection, this spore-based vaccine may offer protection in cattle by limiting colonization and subsequent infection, and Spore-MhCP warrants further evaluation in cattle as a mucosal vaccine against M. haemolytica.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f138b31a-2bbd-4533-8de8-13ed4d652e10', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Economic impact of digital dermatitis, foot rot, and bovine respiratory disease in feedlot cattle', 'Julián A. Cortés, S. Hendrick, Eugene Janzen, Ed A. Pajor, Karin Orsel', 2021, 'Translational Animal Science', '10.1093/tas/txab076', 'https://doi.org/10.1093/tas/txab076', 'https://academic.oup.com/tas/article-pdf/5/2/txab076/38843219/txab076.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Abstract Digital dermatitis (DD) has emerged in North American feedlots, although production and economic impacts are not fully understood. Objectives of this study were to: (1) estimate the economic impact of a single case of DD, foot rot (FR), and bovine respiratory disease (BRD) in feedlot cattle and (2) determine its impact on average daily gain (ADG). Feedlot cattle health and production records were available from two feedlots for a 3-yr interval. The dataset consisted of 77,115 animal records, with 19.3% (14,900) diagnosed with a disease. Diseased animals were categorized into five groups: DD, FR, BRD, other diseases (OT), and two or more diseases (TM), with a treatment cumulative incidence of 6.0%, 59.1%, 10.7%, 12.7%, and 11.5%, respectively. FR was the disease with the highest cumulative incidence in both heifers and steers (58.8% and 59.6%, respectively). Of all fall-placed cattle diagnosed with any disease, 48.1% of the cases were FR. DD affected the partial budget in five out of the eight groups of cattle, with the highest impact of DD seen in grass yearling heifers and grass yearling steers: $-98 and $-96 CAD, respectively, relative to their healthier counterparts. Healthy cattle had a significantly higher ADG when compared with DD cattle in five of the eight categories, ranging from 0.11 kg/d in winter-placed heifers to 0.17 kg/d in fall-placed steers. In the economic analysis, it was concluded that on an individual animal basis, BRD was the most impactful of all analyzed diseases, whereas DD was second, marking the importance of controlling and mitigating this foot condition. Identifying differential effects of diseases on a partial budget analysis and ADG of the types of cattle stratified by sex enables feedlot producers to focus control and mitigation strategies on specific groups.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('10ac4596-81e4-49fb-a598-ce323b8fd618', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Efficacy of tilmicosin and tildipirosin for on-arrival treatment of bovine respiratory disease in fall-placed feedlot calves in western Canada', 'Joyce Van Donkersgoed, John K. Merrill', 2013, 'The Bovine Practitioner', '10.21423/bovine-vol47no2p146-151', 'https://doi.org/10.21423/bovine-vol47no2p146-151', 'https://bovine-ojs-tamu.tdl.org/bovine/article/download/78/7633', NULL, NULL, 6, NULL, 'southern_alberta', 5, 'cc-by-sa', 'A trial was conducted in a commercial finishing feedlot in southern Alberta, Canada using fall-placed steer calves to evaluate the comparative efficacy of metaphylactic treatment with tilmicosin or tildipirosin for control of bovine respiratory disease (BRD). First-pull treatment rates for BRD were significantly lower (P<0.01) in calves administered tildipirosin than those administered tilmicosin on arrival. There were no significant differences in BRD relapse rates, overall mortality, or BRD and histophilosis mortality. While calves treated with tildipirosin on feedlot entry had higher average daily gain (P=0.006) and lower dry-matter conversion (P=0.007) at 56 days-on-feed than those treated with tilmicosin, these performance differences were no longer significant (P>0.05) at 146 days-on-feed. Using current drug prices and based on differences in initial BRD treatment rates, tilmicosin had a net economic advantage of $6.85 CAN/head to those treated with tildipirosin on arrival.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('089aed78-ff64-465c-93bc-89940d2dd964', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Fatty Acid and Micronutrient Profile of Longissimus Lumborum from Red Angus and Red Angus x Akaushi Cattle Finished on Grass or Grain', 'Lucas Krusinski, Isabella Cristina de Faria Maciel, Selin Sergin, Travis Goeden, Jeannine P. Schweihofer, Sukhdeep Singh, Jason E. Rowntree, Jenifer I. Fenton', 2022, 'Foods', '10.3390/foods11213451', 'https://doi.org/10.3390/foods11213451', 'https://www.mdpi.com/2304-8158/11/21/3451/pdf?version=1667202258', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Cattle diet and breed modify the nutritional profile of beef. The objective of this study was to compare the fatty acid (FA) and micronutrient profiles of Red Angus (RA) and RA x Akaushi (AK) crossbreed steers fed either a grass or grain diet. This two-year study randomly assigned steers to the diets using a 2 × 2 factorial experiment. FAs and micronutrients were analyzed. Diet effect was the strongest with grass-finished beef being higher in n-3 polyunsaturated FAs (p < 0.001), conjugated linoleic acid (p < 0.05), vaccenic acid (p < 0.05), iron (p < 0.001), and vitamin E (p < 0.001) compared to grain-finished beef. Breed effects were observed for lauric and myristic acids (p < 0.05), selenium (p < 0.05), and zinc (p < 0.01) with AK containing more of these compounds than RA. Diet × breed effects were non-existent. These results indicate that diet has a stronger influence than breed on modifying the nutritional profile of beef. Because of a more favorable FA and antioxidant profile, consumption of grass-finished beef could benefit human health.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('95233453-653e-478e-bd1d-b5113703fa46', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Evaluation of a Computer-aided Lung Auscultation System for Diagnosis of Bovine Respiratory Disease in Feedlot Cattle', 'A.V. Mang, Sébastien Buczinski, Calvin W. Booker, Edouard Timsit', 2015, 'Journal of Veterinary Internal Medicine', '10.1111/jvim.12657', 'https://doi.org/10.1111/jvim.12657', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/jvim.12657', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by-nc', 'BACKGROUND: A computer-aided lung auscultation (CALA) system was recently developed to diagnose bovine respiratory disease (BRD) in feedlot cattle. OBJECTIVES: To determine, in a case-control study, the level of agreement between CALA and veterinary lung auscultation and to evaluate the sensitivity (Se) and specificity (Sp) of CALA to diagnose BRD in feedlot cattle. ANIMALS: A total of 561 Angus cross-steers (initial body weight = 246 ± 45 kg) were observed during the first 50 day after entry to a feedlot. METHODS: Case-control study. Steers with visual signs of BRD identified by pen checkers were examined by a veterinarian, including lung auscultation using a conventional stethoscope and CALA that produced a lung score from 1 (normal) to 5 (chronic). For each steer examined for BRD, 1 apparently healthy steer was selected as control and similarly examined. Agreement between CALA and veterinary auscultation was assessed by kappa statistic. CALA''s Se and Sp were estimated using Bayesian latent class analysis. RESULTS: Of the 561 steers, 35 were identified with visual signs of BRD and 35 were selected as controls. Comparison of veterinary auscultation and CALA (using a CALA score ≥2 as a cut off) revealed a substantial agreement (kappa = 0.77). Using latent class analysis, CALA had a relatively high Se (92.9%; 95% credible interval [CI] = 0.71-0.99) and Sp (89.6%; 95% CI = 0.64-0.99) for diagnosing BRD compared with pen checking. CONCLUSIONS: CALA had good diagnostic accuracy (albeit with a relatively wide CI). Its use in feedlots could increase the proportion of cattle accurately diagnosed with BRD.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a3148ce8-7f9f-4787-8b4e-b9f2cf34e7d6', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Gallic Acid Potentiates the Antimicrobial Activity of Tulathromycin Against Two Key Bovine Respiratory Disease (BRD) Causing-Pathogens', 'Karthic Rajamanickam, Jian Ping Yang, Meena Kishore Sakharkar', 2019, 'Frontiers in Pharmacology', '10.3389/fphar.2018.01486', 'https://doi.org/10.3389/fphar.2018.01486', 'https://www.frontiersin.org/articles/10.3389/fphar.2018.01486/pdf', NULL, NULL, 9, NULL, 'prairies', 4, 'cc-by', 'Bovine respiratory disease (BRD) is the most common infectious disease in dairy and beef cattle. It is associated with significant morbidity and mortality and causes a huge economic loss each year. In western Canada, a one-time injection of tulathromycin is commonly used as a metaphylactic procedure to reduce BRD incidence and eliminate potential BRD outbreak. With increased global concern on antibiotic usage in dairy and beef products and bacterial resistance to antibiotics, it is important to develop a novel strategy to eliminate the usage or decrease the dosage of antibiotics. In this study, we showed that gallic acid was active against both Mannheimia haemolytica and Pasteurella multocida, two key BRD causing-pathogens, with the minimum inhibitory concentration (MIC) measured at 250 g/mL and 500 g/mL, respectively. Co-administration of tulathromycin and gallic acid exhibited a strong additive or weak synergistic effect towards both M. haemolytic and P. multocida. Tulathromycin, gallic acid and their combination were also effective against the co-culture of M. haemolytic and P. multocida. Furthermore, we showed that pre-exposure to tulathromycin generated bacterial resistance to the antibiotic in M. haemolytica but not in P. multocida.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc6f0913-693d-4938-b384-9f8cdd38be37', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Insight into antimicrobial resistance at a new beef cattle feedlot in western Canada', 'Daniël Kos, Brittany Schreiner, Stuart Thiessen, Tim Angus McAllister, Murray D. Jelinski, Antonio C. Ruzzini', 2023, 'mSphere', '10.1128/msphere.00317-23', 'https://doi.org/10.1128/msphere.00317-23', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10732036/pdf/msphere.00317-23.pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by', 'ABSTRACT In North America, beef production relies on the administration of antimicrobials to manage disease. Bovine respiratory disease (BRD) is the most significant disease of beef cattle, and antimicrobial resistance (AMR) to conventional therapies presents an existential risk to animal welfare and food production. While AMR surveillance programs are poised to help facilitate antimicrobial stewardship and decision making at feedlots, monitoring strategies for large numbers of animals at an individual or group level are time consuming and costly. Accordingly, we completed a pilot investigation of feedlot water bowls, which is an understudied interface between cattle and bacteria. By performing cultivation-dependent and cultivation-independent studies, we demonstrate that water bowl-dwelling bacteria can act as sentinel organisms for clinically relevant antimicrobial resistance genes (ARGs) and that cattle have an impact on the microbial communities in the bowls. Moreover, by sampling water at a feedlot site before animal arrival, we detected resistance to two antibiotics: florfenicol and tulathromycin. After just 4 weeks of operation, multidrug-resistant bacteria were routinely found in most water bowls. A comparison of ARGs encoded by five water bowl bacterial isolates along with previously reported source and wastewater metagenomes to those found in BRD pathogens confirmed the utility of using water samples for AMR surveillance. IMPORTANCE A better understanding of how environmental reservoirs of ARGs in the feedlot relate to those found in animal pathogens will help inform and improve disease management, treatment strategies, and outcomes. Monitoring individual cattle or small groups is invasive, logistically challenging, expensive, and unlikely to gain adoption by the beef cattle industry. Wastewater surveillance has become standard in public health studies and has inspired similar work to better our understanding of AMR in feedlots. We derived our insights from sampling water bowls in a newly established feedlot: a unique opportunity to observe AMR prior to animal arrival and to monitor its development over 2 months. Importantly, the bacterial community of a single water bowl can be influenced by direct contact with hundreds of animals. Our results suggest that water bowl microbiomes are economical and pragmatic sentinels for monitoring relevant AMR mechanisms.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('311eb819-8190-43f5-bde7-1f8949190bbb', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Respiratory viruses identified in western Canadian beef cattle by metagenomic sequencing and their association with bovine respiratory disease', 'Maodong Zhang, Janet E. Hill, Champika Fernando, Trevor W. Alexander, Edouard Timsit, Frank J.U.M. van der Meer, Yanyun Huang', 2019, 'Transboundary and Emerging Diseases', '10.1111/tbed.13172', 'https://doi.org/10.1111/tbed.13172', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/tbed.13172', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('41883565-ac02-4c1d-a430-131334a28e4b', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Integrative and conjugative elements in Mycoplasmopsis bovis from Western Canadian feedlot cattle: characterization and conjugative transfer', 'Sara Andrés-Lasheras, Rahat Zaheer, Rodrigo Ortega Polo, Timothy Damian Schwinghamer, Sujeema Abeysekara, Athanasios Zovoilis, Sani-e-Zehra Zaidi, Murray D. Jelinski', 2026, 'Frontiers in Veterinary Science', '10.3389/fvets.2026.1719776', 'https://doi.org/10.3389/fvets.2026.1719776', 'https://public-pages-files-2025.frontiersin.org/journals/veterinary-science/articles/10.3389/fvets.2026.1719776/pdf', NULL, NULL, 13, NULL, 'southern_alberta', 4, 'cc-by', 'Introduction Bovine respiratory disease (BRD) is the most significant disease affecting North American feedlot cattle. It is a multifactorial disease influenced by bacterial and viral pathogens, as well as management and environmental factors. Mycoplasmopsis bovis is among the most pathogenic bovine mycoplasmas and is associated with chronic BRD that often fails to respond to antimicrobial therapy. Integrative and conjugative elements (ICE) facilitate horizontal gene transfer among mycoplasmas and may contribute to the spread of antimicrobial resistance in M. bovis . Methods We identified mycoplasma ICEs (MICE) in the genomes of sequenced M. bovis isolates from western Canadian feedlot cattle ( n = 124) and in vitro mating experiments to assess conjugation. Results and Discussion Of these isolates, 33.1% harbored the array of MICE genes required for conjugation. M. bovis isolates conjugated at frequencies of 10–7–10–8 when cultured in SP4 broth under orbital agitation. Since MICE circularization is the initial step in conjugation, the presence of circular MICE (cMICE) was used as a proxy for conjugation capability ( n = 451). Interestingly, 25.7% of the isolates were cMICE-positive, with a higher prevalence observed in M. bovis isolated from dairy as compared to beef feedlot cattle. Additionally, calves classified as high-risk for BRD were more likely to harbor cMICE-positive M. bovis in both cattle types. Backgrounded dairy cattle had a higher likelihood of carrying cMICE-positive M. bovis than those originating from ranches. These findings lay the groundwork for assessing cattle source as a determinant of cMICE-positive M. bovis and for developing targeted strategies to mitigate antimicrobial resistance.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('81d0681e-ea7c-44e4-96a9-047632b3b537', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Foot scores genetic parameters estimation in beef cattle', 'Hamad M Saad, R. M. Enns, Milton Thomas, Lee Leachman, Scott E Speidel', 2021, 'Translational Animal Science', '10.1093/tas/txab170', 'https://doi.org/10.1093/tas/txab170', 'https://academic.oup.com/tas/article-pdf/5/Supplement_S1/S180/41388276/txab170.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Foot and leg disorders can negatively influence longevity and therefore cause economic loss in both beef (McGuire et al., 2019) and dairy cattle (Enting et al., 1997; Boettcher et al., 1998). The type-trait evaluation has been long established in dairy industry. Even though the importance of phenotypic foot soundness traits is well established among beef cattle producers, the genetic evaluation for such traits was only introduced recently and improvements are ongoing (Jeyaruban et al., 2012; Australian Angus Association, 2016,, 2017; Vargas et al., 2017; Wang et al., 2017; Giess et al., 2018; BIF Guidelines Wiki, 2019). Foot angle (FA) and claw set (CS) are important foot soundness structural traits that can be collected on beef cattle. Phenotype for both traits is a subjective score from 1 to 9 with a score of 5 being an intermediate optimum (American Angus Association, 2017). Foot structural soundness scores are indicator traits for longevity and should not be considered as economically relevant traits (BIF Guidelines Wiki, 2019). Moderate heritability estimates for FA and CS indicate that genetic improvement of foot score can be achieved (Wang et al., 2017). Our objective was to estimate genetic parameters and predict expected progeny differences (EPD) for FA and CS scores using the data from Leachman Cattle of Colorado (LCoC). Animal Care and Use Committee approval was not required for this study as the data were obtained from LCoC database. Conforming to the American Angus Association (AAA) guidelines (American Angus Association, 2017), phenotypes of FA and CS were recorded using a nine-point scoring system. For FA, a score of one indicates extremely straight pasterns and short toes; a score of nine indicates extremely shallow heels, weak pasterns, and long toes; and a score of five is the intermediate optimum. For CS, a score of one corresponds to weak, open, divergent CS; a score of nine corresponds to extreme scissor claw; and a score of five is ideal. Raw data obtained from LCoC (n = 6,090 records) included animals with repeated measures of FA and CS. Most animals (n = 4,333) had one observation reported for each trait. There were 865 animals that had multiple records with most having two records per trait per animal. Only data on yearlings and 2-yr-old animals (i.e., measurement age ranged from 320 to 810 d) were kept. The Australian Angus Association collected structural soundness scores before hoof trimming to avoid mis-scoring animals. In the genetic evaluation of structural soundness scores in Australian Angus, only animals that are younger than 750 d (i.e., 25 mo) were included (Australian Angus Association, 2016). In a preliminary assessment of LCoC data, we decided to include data from animals younger than 810 d (i.e., 27 mo) for two reasons: 1) heritability using data from yearlings and 2-yr-old animals was higher than heritability with no age restriction based on preliminary analyses and 2) the majority of data were collected on yearlings and 2-yr-old animals. Following the AAA and Beef Improvement Federation (BIF) guidelines for foot score evaluation (American Angus Association, 2017; BIF Guidelines Wiki, 2019) for animals with multiple observations, only the most recent recorded observation (i.e., as a 2 yr old if available) was kept for further analysis. There were 285 and 99 animals with scores < 5 for FA and CS, respectively. Such observations were removed from data as recommended by BIF Guidelines Wiki (2019). Wang et al. (2017), in their study on American Angus, reported that analyzing FA and CS using scores ≥ 5 gave higher heritability estimates compared with using scores ≤ 5. Removing low scores also helps producers to easily understand and interpret EPD (i.e., lower EPD are favorable). Leachman Cattle of Colorado is a multi-breed breeding program. Hence, the retained hybrid vigor was calculated using the following breed percentage designations: 1) Angus (Black and Red Angus), 2) South Devon, 3) Bri', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('01c4d4a1-cc03-478b-a930-84a9e5a61d3c', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Frame Score, Grazing and Delayed Feedlot Entry Effect on Performance and Economics of Beef Steers from Small- and Large-Framed Cows in an Integrated Crop-Livestock System', 'Şentürklü S, Landblom D, Paisley S, Wachenheim C, Maddock R', 2021, 'Animals : an open access journal from MDPI', '10.3390/ani11113270', 'https://doi.org/10.3390/ani11113270', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC8614511.1/PMC8614511.1.pdf', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc by', 'When selling small-framed steers at weaning, profitability is diminished. The hypothesis is that by using a vertically integrated business model that includes retained ownership, extended grazing, abbreviated feedlot finishing, and selling at slaughter, profitability would increase. Crossbred yearling steers (n = 288) from small size Aberdeen Angus (Lowline) × Red Angus × Angus × Angus cows and moderate to large size Red Angus × Angus × Simmental × Gelbvieh cows calved May-June were randomly assigned (complete randomized design), in a 3 y study, to feedlot control (FLT) and extended grazing (GRZ) frame score treatment groups. Mean frame score for FLT were small frame (SF) 3.82 and large frame (LF) 5.63, and for GRZ, SF: 3.77 and LF: 5.53. Least-square means were utilized to identify levels of effects and to control family-wise error adjusted with Tukey test. The FLT control steers were housed in the feedlot and fed growing diets and subsequently high energy corn-based diets for 218 days. The GRZ steers grazed a sequence of forages (native range, field pea-barley mix, and unharvested corn) for 212 days and then were transferred to the feedlot and fed high energy corn-based finishing diets for 82 days. The SF GRZ steers grew more slowly grazing native range and annual forages compared to GRZ LF steers, but SF steer grazing cost per kg of gain was reduced 7.80%. Grazing steers did not grow to their full genetic potential. Slower growth during grazing allowed LF and SF steers to grow structurally before feedlot entry creating a compensatory feedlot finishing growth response. Overall, grazing steer performance exceeded steer performance of the FLT control treatment and LF grazing steers had the highest rate of gain, and lowest feed cost per kg of gain. The GRZ steer feedlot days on feed were reduced 136 days and total feed intake was reduced resulting in LF and SF grazing steer feed cost reductions of 175.9 and 165.3%, respectively. Extended grazing also resulted in LF and SF grazing steer hot carcass weights to be greater than control LF and SF steers and SF grazing steers had greater dressing percent, and marbling score. Carcass quality grade, meat tenderness, and cooking losses were similar. System net returns were highest for LF (USD 911.58), and SF (USD 866.61) grazing steers. Managerial modification combining retained ownership, extended grazing, and delayed feedlot entry increased profitability and eliminated market bias.', '{epmc,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49046abc-4b2f-44ce-bd26-dab568607977', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Mucosal Immunization with Spore-Based Vaccines against Mannheimia haemolytica Enhances Antigen-Specific Immunity', 'Muhammed Salah Uddin, Angelo Kaldis, Rima Menassa, José Ortiz Guluarte, Daniel R. Barreda, Le Luo Guan, Trevor W. Alexander', 2024, 'Vaccines', '10.3390/vaccines12040375', 'https://doi.org/10.3390/vaccines12040375', 'https://www.mdpi.com/2076-393X/12/4/375', NULL, NULL, NULL, NULL, 'southern_alberta', 4, 'open access (DOAJ)', 'Background: Mannheimia haemolytica is a bovine respiratory pathogen commonly associated with bacterial bronchopneumonia. Current vaccine strategies have shown variable efficacy in feedlot cattle, and therefore novel vaccines are needed. Bacillus subtilis spores have been investigated as a mucosal vaccine platform, due to their ability to bind and present antigens to the mucosa and act as an adjuvant. The aim of this study was to develop two spore-based mucosal vaccines targeting M. haemolytica and evaluate their immunogenicity in mice. Methods: Two antigen constructs composed of cholera toxin B subunit, M. haemolytica leukotoxin, and either the M. haemolytica outer membrane protein PlpE (MhCP1) or GS60 (MhCP2) were synthesized, purified and then bound to spores as vaccines. In two separate mice trials, the spore-bound vaccines (Spore-MhCP1 and Spore-MhCP2) were administered to mice through intranasal and intragastric routes, while free antigens were administered intranasally and intramuscularly. Unbound spores were also evaluated intranasally. Antigen-specific serum IgG and mucosal IgA from bronchoalveolar lavage, feces, and saliva were measured after vaccination. Mice sera from all treatment groups were assessed for their bactericidal activity against M. haemolytica. Results: In both mice experiments, intramuscular immunization induced the strongest serum IgG antibody response. However, the intranasal administration of Spore-MhCP1 and Spore-MhCP2 elicited the greatest secretory IgA-specific response against leukotoxin, PlpE, and GS60 in bronchoalveolar lavage, saliva, and feces (p M. haemolytica (p M. haemolytica colonization and proliferation in the respiratory tract. The efficacy of these mucosal spore-based vaccines merits further assessment against M. haemolytica in cattle.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('049b0742-bf25-481c-8836-8e4da283d2bd', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Multi-Year Persistence of Verotoxigenic Escherichia coli (VTEC) in a Closed Canadian Beef Herd: A Cohort Study', 'Lu Ya Ruth Wang, Cassandra C. Jokinen, Chad Laing, Roger Paul Johnson, Kim A. Ziebell, Victor P. J. Gannon', 2018, 'Frontiers in Microbiology', '10.3389/fmicb.2018.02040', 'https://doi.org/10.3389/fmicb.2018.02040', 'https://www.frontiersin.org/articles/10.3389/fmicb.2018.02040/pdf', NULL, NULL, 24, NULL, 'alberta', 4, 'cc-by', 'In this study, faecal samples were collected from a closed beef herd in Alberta, Canada from 2012 to 2015. To limit serotype bias, which was observed in enrichment broth cultures, Verotoxigenic Escherichia coli (VTEC) were isolated directly from samples using a hydrophobic grid-membrane filter verotoxin immunoblot assay. Overall VTEC isolation rates were similar for three different cohorts of yearling heifers on both an annual (68.5% to 71.8%) and seasonal basis (67.3% to 76.0%). Across all three cohorts, O139:H19 (37.1% of VTEC-positive samples), O22:H8 (15.8%) and O?(O108):H8 (15.4%) were among the most prevalent serotypes. However, isolation rates for serotypes O139:H19, O130:H38, O6:H34, O91:H21 and O113:H21 differed significantly between cohort-years, as did isolation rates for some serotypes within a single heifer cohort. There was a high level of VTEC serotype diversity with an average of 4.3 serotypes isolated per heifer and 65.8% of the heifers classified as “persistent shedders” of VTEC based on the criteria of > 50% of samples positive and ≥ 4 consecutive samples positive. Only 26.8% (90/336) of the VTEC isolates from yearling heifers belonged to the human disease-associated seropathotypes A (O157:H7), B (O26:H11, O111:NM), and C (O22:H8, O91:H21, O113:H21, O137:H41, O2:H6). Conversely, seropathotypes B (O26:NM, O111:NM) and C (O91:H21, O2:H29) strains were dominant (76.0%, 19/25) among VTEC isolates from month-old calves from this herd. Among VTEC from heifers, carriage rates of vt1, vt2, vt1+vt2 and hlyA were 10.7%, 20.8%, 68.5%, and 88.7%, respectively. The adhesin gene saa was present in 82.7% of heifer strains but absent from all of 13 eae+ve strains (from serotypes/intimin types O157:H7/γ1, O26:H11/ β1, and O111:NM/ θ, O84:H2/ζ and O182:H25/ζ). Phylogenetic relationships inferred from wgMLST and pan genome-derived core SNP analysis showed that strains clustered by phylotype and serotype. Further, VTEC strains of the same serotype usually shared the same suite of antibiotic resistance and virulence genes, suggesting the circulation of dominant clones within this distinct herd. This study provides insight into the diverse and dynamic nature of VTEC populations within groups of cattle and points to a broad spectrum of human health risks associated with these E. coli strains.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e1e29212-4370-41f6-9724-9c83fbbb7f7f', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Prevalence and Risk Factors Associated With Antimicrobial Resistance in Bacteria Related to Bovine Respiratory Disease—A Broad Cross-Sectional Study of Beef Cattle at Entry Into Canadian Feedlots', 'Sara Andrés-Lasheras, Reuben Ha, Rahat Zaheer, Catrione Lee, Calvin W. Booker, Craig Dorin, Joyce Van Donkersgoed, Rob Deardon', 2021, 'Frontiers in Veterinary Science', '10.3389/fvets.2021.692646', 'https://doi.org/10.3389/fvets.2021.692646', 'https://www.frontiersin.org/articles/10.3389/fvets.2021.692646/pdf', NULL, NULL, 19, NULL, 'southern_alberta', 5, 'cc-by', 'A broad, cross-sectional study of beef cattle at entry into Canadian feedlots investigated the prevalence and epidemiology of antimicrobial resistance (AMR) in Mannheimia haemolytica, Pasteurella multocida, Histophilus somni , and Mycoplasma bovis , bacterial members of the bovine respiratory disease (BRD) complex. Upon feedlot arrival and before antimicrobials were administered at the feedlot, deep nasopharyngeal swabs were collected from 2,824 feedlot cattle in southern and central Alberta, Canada. Data on the date of feedlot arrival, cattle type (beef, dairy), sex (heifer, bull, steer), weight (kg), age class (calf, yearling), source (ranch direct, auction barn, backgrounding operations), risk of developing BRD (high, low), and weather conditions at arrival (temperature, precipitation, and estimated wind speed) were obtained. Mannheimia haemolytica, P. multocida , and H. somni isolates with multidrug-resistant (MDR) profiles associated with the presence of integrative and conjugative elements were isolated more often from dairy-type than from beef-type cattle. Our results showed that beef-type cattle from backgrounding operations presented higher odds of AMR bacteria as compared to auction-derived calves. Oxytetracycline resistance was the most frequently observed resistance across all Pasteurellaceae species and cattle types. Mycoplasma bovis exhibited high macrolide minimum inhibitory concentrations in both cattle types. Whether these MDR isolates establish and persist within the feedlot environment, requires further evaluation.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04fba01f-e700-4fce-8a63-59aa44e2b028', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Reintroducing bison to Banff National Park – an ecocultural case study', 'Karsten Heuer, Jonathan Farr, Leroy Littlebear, Mark Hebblewhite', 2023, 'Frontiers in Conservation Science', '10.3389/fcosc.2023.1305932', 'https://doi.org/10.3389/fcosc.2023.1305932', 'https://www.frontiersin.org/articles/10.3389/fcosc.2023.1305932/full', NULL, NULL, 12, NULL, 'southern_alberta', 4, 'open access (DOAJ)', 'The reintroduction of extirpated species is a frequent tactic in rewilding projects because of the functional role species play in maintaining ecosystem health. Despite their potential to benefit both ecosystems and society, however, most well-known species reintroductions have adopted an eco-centric, “nature-in-people-out” approach. Rewilding theory and practitioners acknowledge that ignoring the role Indigenous people did and might once again play in shaping the distribution, abundance, movements, behavior, and health of wild species and ecosystems, is limiting. In this case study, we describe the technical steps we took and how Indigenous knowledge, ceremony, and cultural monitoring were woven into the recent reintroduction of plains bison to Canada’s Banff National Park. Six years later, the reintroduced bison herd has grown from 16 to >100 animals, ranges mostly within 30 km of the release site, and, if current growth continues, will likely be managed with Indigenous harvesting. Transboundary bison policy differences are shifting and may lead to bison being more sustainable. The ecocultural approach, therefore, has increased the resilience of our rewilding project.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('66fdfdeb-3400-4000-89bf-fa647a43e326', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Role of biofilms in antimicrobial resistance of the bacterial bovine respiratory disease complex', 'Andrés-Lasheras S, Zaheer R, Jelinski M, McAllister TA', 2024, 'Frontiers in veterinary science', '10.3389/fvets.2024.1353551', 'https://doi.org/10.3389/fvets.2024.1353551', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11199855.1/PMC11199855.1.pdf', NULL, NULL, 11, NULL, 'southern_alberta', 5, 'cc by', 'An increase in chronic, non-responsive bovine respiratory disease (BRD) infections in North American feedlot cattle is observed each fall, a time when cattle are administered multiple antimicrobial treatments for BRD. A number of factors are responsible for BRD antimicrobial treatment failure, with formation of biofilms possibly being one. It is widely accepted that biofilms play a role in chronic infections in humans and it has been hypothesized that they are the default lifestyle of most bacteria. However, research on bacterial biofilms associated with livestock is scarce and significant knowledge gaps exist in our understanding of their role in AMR of the bacterial BRD complex. The four main bacterial species of the BRD complex, Mannheimia haemolytica, Pasteurella multocida, Histophilus somni, and Mycoplasma bovis are able to form biofilms in vitro and there is evidence that at least H. somni retains this ability in vivo. However, there is a need to elucidate whether their biofilm-forming ability contributes to pathogenicity and antimicrobial treatment failure of BRD. Overall, a better understanding of the possible role of BRD bacterial biofilms in clinical disease and AMR could assist in the prevention and management of respiratory infections in feedlot cattle. We review and discuss the current knowledge of BRD bacteria biofilm biology, study methodologies, and their possible relationship to AMR.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd8d4c01-7e56-431c-98f9-d30977fbdc0b', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Rotavirus vaccine development for calf scours', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/rotavirus-vaccine-development-for-calf-scours', 'https://open.alberta.ca/dataset/f7e437fd-3cc9-4b93-8352-2b21ea05a523/resource/6081e820-e5ac-4271-8d3d-5b9c3731bbf0/download/163010401889-rotavirus-vaccine-development-for-calf-scours.pdf', NULL, NULL, 106, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated rotavirus as a major cause of diarrhea in calves under one month old, noting that maternal antibodies in colostrum protect calves only during the first few days of life before antibody levels decline to non-protective levels. The research aimed to develop vaccines that could protect calves until they are two to three weeks old and to evaluate two commercial rotavirus vaccines for their ability to increase antibody titers. Seven different rotavirus isolates were grown in tissue culture, and two distinct serotypes were selected for vaccine trials using various vaccine formulations and administration protocols. Results showed that vaccinating cows with a killed rotavirus vaccine before calving could produce protective antibody titers in milk, but the level of antibody depended on vaccine dose, route, adjuvant and timing. As of March 1984, commercial modified-live rotavirus vaccines did not significantly increase serum or milk antibody titers and may not provide adequate protection under field conditions.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('02e9a710-7027-4804-b063-f72e3699d951', 'd1af0758-6595-46af-9c93-b816db1bf60c', 'Whole-Blood Transcriptome Analysis of Feedlot Cattle With and Without Bovine Respiratory Disease', 'Janelle A. Jiminez, Edouard Timsit, Karin Orsel, Frank J.U.M. van der Meer, Le Luo Guan, Graham Stuart Plastow', 2021, 'Frontiers in Genetics', '10.3389/fgene.2021.627623', 'https://doi.org/10.3389/fgene.2021.627623', 'https://www.frontiersin.org/articles/10.3389/fgene.2021.627623/pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Bovine respiratory disease (BRD) is one of the main factors leading to morbidity and mortality in feedlot operations in North America. A complex of viral and bacterial pathogens can individually or collectively establish BRD in cattle, and to date, most disease characterization studies using transcriptomic techniques examine bronchoalveolar and transtracheal fluids, lymph node, and lung tissue as well as nasopharyngeal swabs, with limited studies investigating the whole-blood transcriptome. Here, we aimed to identify differentially expressed (DE) genes involved in the host immune response to BRD using whole blood and RNA sequencing. Samples were collected from heifers (average arrival weight = 215.0 ± 5.3 kg) with (n= 25) and without (n= 18) BRD at a commercial feedlot in Western Canada. RNAseq analysis showed a distinct whole-blood transcriptome profile between BRD and non-BRD heifers. Further examination of the DE genes revealed that those involved in the host inflammatory response and infectious disease pathways were enriched in the BRD animals, while gene networks associated with metabolism and cell growth and maintenance were downregulated. Overall, the transcriptome profile derived from whole blood provided evidence that a distinct antimicrobial peptide-driven host immune response was occurring in the animals with BRD. The blood transcriptome of the BRD animals shows similarities to the transcriptome profiles obtained from lung and bronchial lymph nodes in other studies. This suggests that the blood transcriptome is a potential diagnostic tool for the identification of biomarkers of BRD infection and can be measured in live animals and used to further understand infection and disease in cattle. It may also provide a useful tool to increase the understanding of the genes involved in establishing BRD in beef cattle and be used to investigate potential therapeutic applications.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7bd51025-fa3c-4232-a09a-c891226adca4', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'A novel analytical method, Birth Date Selection Mapping, detects response of the Angus (Bos taurus) genome to selection on complex traits', 'Jared E. Decker, Daniel A. Vasco, Stephanie McKay, Matthew Charles McClure, Megan M Rolf, JaeWoo Kim, Sally L Northcutt, Stewart W Bauck', 2012, 'BMC Genomics', '10.1186/1471-2164-13-606', 'https://doi.org/10.1186/1471-2164-13-606', 'https://bmcgenomics.biomedcentral.com/counter/pdf/10.1186/1471-2164-13-606', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Several methods have recently been developed to identify regions of the genome that have been exposed to strong selection. However, recent theoretical and empirical work suggests that polygenic models are required to identify the genomic regions that are more moderately responding to ongoing selection on complex traits. We examine the effects of multi-trait selection on the genome of a population of US registered Angus beef cattle born over a 50-year period representing approximately 10 generations of selection. We present results from the application of a quantitative genetic model, called Birth Date Selection Mapping, to identify signatures of recent ongoing selection. RESULTS: We show that US Angus cattle have been systematically selected to alter their mean additive genetic merit for most of the 16 production traits routinely recorded by breeders. Using Birth Date Selection Mapping, we estimate the time-dependency of allele frequency for 44,817 SNP loci using genomic best linear unbiased prediction, generalized least squares, and BayesCπ analyses. Finally, we reconstruct the primary phenotypes that have historically been exposed to selection from a genome-wide analysis of the 16 production traits and gene ontology enrichment analysis. CONCLUSIONS: We demonstrate that Birth Date Selection Mapping utilizing mixed models corrects for time-dependent pedigree sampling effects that lead to spurious SNP associations and reveals genomic signatures of ongoing selection on complex traits. Because multiple traits have historically been selected in concert and most quantitative trait loci have small effects, selection has incrementally altered allele frequencies throughout the genome. Two quantitative trait loci of large effect were not the most strongly selected of the loci due to their antagonistic pleiotropic effects on strongly selected phenotypes. Birth Date Selection Mapping may readily be extended to temporally-stratified human or model organism populations.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3e4ec90a-1f6c-4423-ae9b-cb024fe9bc5f', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Additive and non-additive, direct and maternal genetic effects for growth traits in a multibreed population of beef cattle', 'Hugo Horacio Montaldo, Brian P. Kinghorn', 2003, 'Archivos de medicina veterinaria', '10.4067/s0301-732x2003000200013', 'https://doi.org/10.4067/s0301-732x2003000200013', 'https://www.redalyc.org/articulo.oa?id=173013751013', NULL, NULL, 9, NULL, 'other', 1, 'cc-by-nc', '"Registros de pesos de 4319 bovinos, obtenidos entre 1989 y 1997 en un hato en New South Wales, Australia, fueron usados para estimar los efectos genéticos aditivos y no aditivos, directos y maternos para caracteres de crecimiento en una población que involucra animales de raza pura y cruzados de Angus, Gelbvieh, Polled Hereford, Red Angus y Santa Gertrudis. Los pesos ajustados para edad a 200 (W2), 400 (W4) y 600 días (W6), fueron analizados usando un modelo animal multicarácter incluyendo el efecto genético materno para W2. Se incluyeron en el modelo comocovariables fijas, los efectos genéticos directos de raza, aditivo materno (Santa Gertrudis vs. otras razas) y los efectos directos de dominancia (heterocigocidad individual del animal) para todos los caracteres estudiados. Los valores intermedios obtenidos para las heredabilidades directas para W2,W4 y W6, son suficientemente altos para obtener progreso genético en la población mediante la selección de los mejores animales usando un modelo animal. Diferentes énfasis para cadacaracterística pueden permitir cambios en la curva de crecimiento de los 200-600 días de edad. Laheredabilidad materna para W2 fue cercana a cero, indicando una baja interferencia con el progresogenético de los efectos directos de las características de crecimiento y un valor reducido para la selección de este efecto. El potencial de crecimiento en terneros Gelbvieh y Angus fue mayor que en las otras razas, el potencial de crecimiento de Santa Gertrudis fue el menor. Santa Gertrudis fuesuperior al promedio de las otras razas para los efectos maternos de raza. El estimado del efecto promedio de dominancia fue positivo para W2 y W6 y negativo para W4 y menor que la diferencia máxima entre los efectos directos de raza."', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4050c913-2959-4a79-a6e1-45999a932c9f', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'An examination of the association of serum IGF-I concentration, potential candidate genes, and fiber type composition with variation in residual feed intake in progeny of Red Angus sires divergent for maintenance energy EPD1', 'C. M. Welch, Kara J Thornton, Gordon K. Murdoch, Kalyan C. Chapalamadugu, C. S. Schneider, J. K. Ahola, J. B. Hall, William J. Price', 2013, 'Journal of Animal Science', '10.2527/jas.2013-6609', 'https://doi.org/10.2527/jas.2013-6609', 'https://researchoutput.csu.edu.au/files/12273386/11986260_Published_article_OA.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'other-oa', 'Investigating the genetic and physiological drivers of postweaning residual feed intake (RFI) and finishing phase feed efficiency (FE) may identify underlying mechanisms that are responsible for the variation in these complex FE traits. The objectives were 1) to evaluate the relationship of serum IGF-I concentration and muscle gene expression with postweaning RFI and sire maintenance energy (MEM) EPD and 2) to determine fiber type composition as it relates to postweaning RFI and finishing phase FE. Results indicate that RFI and serum IGF-I concentration were not associated (P > 0.05); however, negative correlations (P < 0.05) between sire MEM EPD and serum IGF-I concentration were observed. Gene expression differences between high- and low-RFI animals were observed in cohort 1, where IGFBP5 expression was greater (P < 0.05) in high-RFI animals. When animals were grouped according to sire MEM EPD, the low MEM EPD group of cohort 1 showed greater muscle mRNA expression (P < 0.01) of fatty acid synthase (FASN) and marginally (P < 0.10) greater expression of IGFBP5 and C/EBP alpha (C/EBPα) whereas the high MEM EPD group of cohort 2 had greater muscle mRNA expression of IGFBP2 (P < 0.05) and C/EBPα (P ≤ 0.01) and marginally (P < 0.10) greater expression of IGFBP3. Biopsy tissue samples collected at harvest revealed that the percentage of type IIa fibers was lower (P ≤ 0.05) in high-RFI steers, with a similar trend (P < 0.10) being observed in high finishing phase FE steers. The percentage of type IIb fibers was higher (P < 0.05) in high-RFI (and finishing phase FE) steers than in low-RFI (and finishing phase FE) steers. There was a marginal, negative correlation between RFI and type I (r = -0.36, P = 0.08) and IIa (r = -0.37, P = 0.07) fiber percentages and a positive correlation (r = 0.48, P = 0.01) between RFI and type IIb fiber percentage whereas finishing phase FE was negatively correlated (r = -0.43, P = 0.03) with type I fiber percentage and positively correlated (r = 0.44, P = 0.03) with type IIb fiber percentage. Therefore, our data indicate that 1) serum IGF-I (collected at weaning) is not an indicator of postweaning RFI, 2) the GH-IGF axis appears to have some involvement with RFI at the molecular level; however, muscle gene expression results were not consistent across cohorts, and 3) low-RFI animals may have the ability to more efficiently maintain and accrete muscle mass due to their fiber type composition, specifically a greater proportion of type I fibers.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aee424ed-e3ac-4f3d-a39e-e6afa2bc03ef', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Association analysis of adiponectin and somatostatin polymorphisms on BTA1 with growth and carcass traits in Angus cattle', 'Natalia S. Morsci, Robert D. Schnabel, Jeremy F. Taylor', 2006, 'Animal Genetics', '10.1111/j.1365-2052.2006.01528.x', 'https://doi.org/10.1111/j.1365-2052.2006.01528.x', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/j.1365-2052.2006.01528.x', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e602cef-25eb-4089-9ceb-fe0a07027eea', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genetic architecture of thermotolerance traits in beef cattle: a novel integration of SNP and breed-of-origin effects', 'Gabriel A Zayas, Camila Santos Rojas, Eduardo E Rodriguez, Aakilah S. Hernandez, Ashley Beard, Fahad Rafiq, Kaitlyn M. Sarlo Davila, Raluca G. Mateescu', 2025, 'Frontiers in Genetics', '10.3389/fgene.2025.1576966', 'https://doi.org/10.3389/fgene.2025.1576966', 'https://www.frontiersin.org/journals/genetics/articles/10.3389/fgene.2025.1576966/pdf', NULL, NULL, 14, NULL, 'other', 1, 'cc-by', 'Background: has emerged as a critical strategy to balance the production efficiency of taurine breeds with the superior thermotolerance of indicine breeds. Understanding the genetic architecture of thermotolerance traits is essential for improving heat resilience in beef cattle populations. Methods: Phenotypes for short hair length (SHL, undercoat) and long hair length (LHL, topcoat), sweat gland area (SGA), and thermal stress slope (TSS), a measure of body temperature fluctuations under heat stress, were collected from 3,962 crossbred Angus-Brahman heifers. Heifers were genotyped, and breed-of-origin (BOA) for each marker was determined using LAMP-LD. Genome-wide association studies were conducted using SNP-only, BOA-only, and integrated SNP + BOA models to identify quantitative trait loci (QTLs) associated with thermotolerance traits. Genes in QTL regions were used for functional enrichment analysis using Gene Ontology (GO) and KEGG pathways. Results: gene. A QTL on BTA19 for SHL and LHL was driven solely by BOA effects, with Brahman BOA associated with shorter hair lengths. For SGA, six suggestive QTLs were detected, predominantly linked to Angus-derived alleles associated with reduced sweat gland area. For TSS, a significant QTL on BTA1 exhibited a strong BOA effect, with Angus BOA associated with higher TSS values, indicative of reduced thermoregulatory efficiency. Integrated SNP + BOA models provided greater resolution and revealed novel QTLs compared to single-effect models. Functional enrichment using GO and KEGG identified MAPK and estrogen signaling pathways in both LHL and TSS, indicating potential overlap in the biological processes influencing hair length and thermoregulation. Conclusion: This study demonstrates the value of integrating BOA with SNP-based models to uncover the genetic architecture of thermotolerance traits in beef cattle. By better capturing breed-specific contributions, these findings enhance our understanding of thermoregulation and provide actionable insights for improving heat resilience in cattle.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b07db52-73b0-4e72-841f-e33ffe60401d', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Candidate lethal haplotypes and causal mutations in Angus cattle', 'Jesse L. Hoff, Jared E. Decker, Robert D. Schnabel, Jeremy F. Taylor', 2017, 'BMC Genomics', '10.1186/s12864-017-4196-2', 'https://doi.org/10.1186/s12864-017-4196-2', 'https://bmcgenomics.biomedcentral.com/track/pdf/10.1186/s12864-017-4196-2', NULL, NULL, 34, NULL, 'other', 1, 'cc-by', 'BACKGROUND: If unmanaged, high rates of inbreeding in livestock populations adversely impact their reproductive fitness. In beef cattle, historical selection strategies have increased the frequency of several segregating fatal autosomal recessive polymorphisms. Selective breeding has also decreased the extent of haplotypic diversity genome-wide. By identifying haplotypes for which homozygotes are not observed but would be expected based on their frequency, candidates for developmentally lethal recessive loci can be localized. This analysis comes without the need for observation of the loss-associated phenotype (e.g., failure to implant, first trimester abortion, deformity at birth). In this study, haplotypes were estimated for 3961 registered Angus individuals using 52,545 SNP loci using findhap v2, which exploited the complex pedigree among the individuals in this population. RESULTS: Seven loci were detected to possess haplotypes that were not observed in homozygous form despite a sufficiently high frequency and pedigree-based expectation of homozygote occurrence. These haplotypes were identified as candidates for harboring autosomal recessive lethal alleles. Of the genotyped individuals, 109 were resequenced to an average 27X depth of coverage to identify putative loss-of-function alleles genome-wide and had variants called using a custom in-house developed pipeline. For the candidate lethal-harboring haplotypes present in these bulls, sequence-called genotypes were used to identify concordant variants. In addition, whole-genome sequence imputation of variants was performed into the set of 3961 genotyped animals using the 109 resequenced animals to identify candidate lethal recessive variants at the seven loci. Following the imputation, no variants were identified that were fully concordant with the marker-based diplotypes. CONCLUSIONS: Selective breeding programs could utilize the predicted lethal haplotypes associated with SNP genotypes. Sequencing and other methods for identifying the causal variants underlying these haplotypes can allow for more efficient methods of management such as gene editing. These two methods in total will reduce the negative impacts of inbreeding on fertility and maximize overall genetic gains.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5dbfe8f0-b52e-45fd-9b7a-c1df7a71c644', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Carcass Characteristics and Beef Quality of Young Grass-Fed Angus x Salers Bovines', 'Jingjing Liu, Marie‐Pierre Ellies‐Oury, L. Pannier, Dominique Gruffat, D. Durand, Faustine Noel, Bernard Sepchat, Isabelle Legrand', 2022, 'Foods', '10.3390/foods11162493', 'https://doi.org/10.3390/foods11162493', 'https://www.mdpi.com/2304-8158/11/16/2493/pdf?version=1660812778', NULL, NULL, 17, NULL, 'other', 1, 'cc-by', 'To characterize carcass and meat attributes, such as beef eating quality in specific farming conditions, 31 young grass-fed crossbred Angus x Salers cattle in two farming systems (a mono-cattle system versus a mixed system with beef cattle and sheep) were used in this study. Three muscle cuts (striploin—m. longissimus dorsi et thoracis; bolar blade—m. triceps brachii caput longum; internal flank plate—m. obliquus internus abdominis) were used for consumer eating quality testing and striploin was used for panelist eating quality assessment, and objective measurements [Warner–Bratzler shear force (WBSF) and fatty acid (FA) and antioxidant contents]. Results indicated that the farming system had no impact on carcass characteristics or meat quality, but it tended to affect FA content, which is likely explained by between-system differences in animal maturity (assessed by ossification score). Animal gender had significant effects on three eating quality traits evaluated by untrained consumers, with higher flavor liking, overall liking, and overall meat eating quality (MQ4) scores in females than in males. Additionally, FA contents were correlated with sensory quality traits to varying extents: consumer-scored tenderness, flavor, and overall liking were mainly positively correlated with ω-3 and ω-6 polyunsaturated fatty acid (PUFA) contents, and panelist-evaluated tenderness and abnormal flavor were more positively correlated with total lipids, saturated fatty acid (SFA), and monounsaturated fatty acid (MUFA) contents. Overall, this study showed that specific grass-fed crossbred Angus x Salers cattle can produce lean meat rich in ω-3 PUFAs with a low ω-6/ω-3 ratio and with “better than average” beef eating quality.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('67f8858b-1ecc-4aec-9de0-3f92059dd7fe', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Evaluation of moderate to high elevation effects on pulmonary arterial pressure measures in Angus cattle1', 'Rachel C Pauling, Scott E Speidel, Milton Thomas, Timothy N. Holt, R. M. Enns', 2018, 'Journal of Animal Science', '10.1093/jas/sky262', 'https://doi.org/10.1093/jas/sky262', 'https://academic.oup.com/jas/article-pdf/96/9/3599/25694169/sky262.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('024f5230-2e2d-4d0c-af28-90950db95ad9', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Characterizing Foot and Leg Scores for Montana’s Registered Angus Cattle', 'Taylre Sitz, Hannah M. DelCurto-Wyffels, Megan L Van Emon, Samuel A. Wyffels, Jeremiah Peterson, Thomas Hamilton, Kelli Retallick, Esther Tarpoff', 2023, 'Animals', '10.3390/ani13182849', 'https://doi.org/10.3390/ani13182849', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10525743/pdf/animals-13-02849.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'The objective of this study was to characterize foot angle and claw set scores of Montana’s (USA) registered Angus cattle using a total of 4723 cattle scored: 1475 yearling bulls, 992 yearling heifers, 1044 2- and 3-year-old cows, and 1212 cows ≥ 4 years old. Yearling bulls had a 0.12 and 0.20 greater mean foot angle and claw set score, respectively, compared to yearling heifers (p < 0.01). Foot angle and claw set scores increased (p < 0.01) with advancing cow age. The combined worst foot changed quadratically with age (p < 0.01) with the majority of problem feet in cows aged 2 to 3 years and older being hind feet issues. The proportion of foot angle and claw set scores not equal to 5 increased quadratically with age (p < 0.01), with heifers having the lowest proportion of scores not equal to 5 (15.8 and 31.7%, respectively) compared to cows aged 4 years and older. Sire lines had an effect on progeny claw set (p < 0.05) and foot angle scores (p < 0.05), as well as variation of progeny foot scores. These data could potentially be used to refine expected progeny difference models.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('39795d27-24b9-411f-a116-406d7d48f05b', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Comparison of body measurements of beef cows of different breeds', 'Szabolcs Albin Bene, B. Nagy, L. Nagy, B. Kiss, József Péter Polgár, F. Szabó', 2007, 'Archives animal breeding/Archiv für Tierzucht', '10.5194/aab-50-363-2007', 'https://doi.org/10.5194/aab-50-363-2007', 'https://aab.copernicus.org/articles/50/363/2007/aab-50-363-2007.pdf', NULL, NULL, 11, NULL, 'other', 1, 'cc-by', 'Abstract. Body measurements of 110 beef cows of 9 breeds (Hungarian Simmental, Hereford, Aberdeen Angus, Red Angus, Lincoln Red, Shaver, Charolais, Limousin and Blonde d’Aquitaine) were taken in December 2004. The absolute, relative measurements and measurement indices moreover correlations between age, live weight and measurements were evaluated and compared for the mentioned breeds. Animals in study were born between 1989 and 2002, kept on the same condition on peat-bog soil pasture at Keszthely. Significant differences (P<0.05) were found among breeds in most of the body measurements. Blonde d’ Aquitaine was the heaviest in live weight (638 kg), highest as for the height at withers (142.5 cm), height at rump (146.6 cm) and length of the body (151.5 cm). Limousin had longest measurements as for the length of the rump (47.4 cm) and width of the rump (58.3 cm). Shaver had the longest width between shoulders (52.9 cm) and width of the head (25.1 cm) while Lincoln Red the longest length of the head (52.8 cm). The correlations between live weight and measurements were medium or strong positive (r = 0.40–0.83), between age and measurements slight positive (r = 0.01–0.46), among the different measurements medium or strong positive (r = 0.22–0.81).', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d2f61abf-58d2-4549-8e04-59ecc0258509', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Comparison of feeding behavior between black and red Angus feeder heifers', 'Barbara Wolfger, C. Quinn, G.W. Torres, Martha L. Taylor, Karin Orsel', 2016, 'Canadian Journal of Animal Science', '10.1139/cjas-2014-0161', 'https://doi.org/10.1139/cjas-2014-0161', 'https://www.nrcresearchpress.com/doi/pdf/10.1139/cjas-2014-0161', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c973f97a-1cd4-40d8-bf76-f65a014cb53b', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Comparison of molecular breeding values based on within- and across-breed training in beef cattle', 'Stephen D. Kachman, Matthew L Spangler, Gary L. Bennett, Kathryn J Hanford, L. A. Kuehn, W. M. Snelling, Richard Mark Thallman, Mahdi Saatchi', 2013, 'Genetics Selection Evolution', '10.1186/1297-9686-45-30', 'https://doi.org/10.1186/1297-9686-45-30', 'https://gsejournal.biomedcentral.com/counter/pdf/10.1186/1297-9686-45-30', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'BACKGROUND: Although the efficacy of genomic predictors based on within-breed training looks promising, it is necessary to develop and evaluate across-breed predictors for the technology to be fully applied in the beef industry. The efficacies of genomic predictors trained in one breed and utilized to predict genetic merit in differing breeds based on simulation studies have been reported, as have the efficacies of predictors trained using data from multiple breeds to predict the genetic merit of purebreds. However, comparable studies using beef cattle field data have not been reported. METHODS: Molecular breeding values for weaning and yearling weight were derived and evaluated using a database containing BovineSNP50 genotypes for 7294 animals from 13 breeds in the training set and 2277 animals from seven breeds (Angus, Red Angus, Hereford, Charolais, Gelbvieh, Limousin, and Simmental) in the evaluation set. Six single-breed and four across-breed genomic predictors were trained using pooled data from purebred animals. Molecular breeding values were evaluated using field data, including genotypes for 2227 animals and phenotypic records of animals born in 2008 or later. Accuracies of molecular breeding values were estimated based on the genetic correlation between the molecular breeding value and trait phenotype. RESULTS: With one exception, the estimated genetic correlations of within-breed molecular breeding values with trait phenotype were greater than 0.28 when evaluated in the breed used for training. Most estimated genetic correlations for the across-breed trained molecular breeding values were moderate (> 0.30). When molecular breeding values were evaluated in breeds that were not in the training set, estimated genetic correlations clustered around zero. CONCLUSIONS: Even for closely related breeds, within- or across-breed trained molecular breeding values have limited prediction accuracy for breeds that were not in the training set. For breeds in the training set, across- and within-breed trained molecular breeding values had similar accuracies. The benefit of adding data from other breeds to a within-breed training population is the ability to produce molecular breeding values that are more robust across breeds and these can be utilized until enough training data has been accumulated to allow for a within-breed training set.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d6d5cc9b-c2e6-4861-89de-3aea5b88ee5e', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Comparison of some economic traits by genetic cluster of Aberdeen Angus cattle', 'Judit Márton, Szabolcs Albin Bene, I. Anton, Attila Zsolnai, Ferenc Szabó', 2025, 'Archives animal breeding/Archiv für Tierzucht', '10.5194/aab-68-279-2025', 'https://doi.org/10.5194/aab-68-279-2025', 'https://aab.copernicus.org/articles/68/279/2025/aab-68-279-2025.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Abstract. The Angus cattle population of Hungary was categorized into four groups using 12 microsatellite markers exhibiting notable genetic variations. Moreover, some traits influencing the profitability and sustainability of beef cattle farming were compared between groups. Data were obtained from 5075 cows (born between 1990–2020) and 19 142 calves (born between 1997–2023), including 10 629 bull calves and 8513 heifer calves of different genetic backgrounds. Genetic groups were distinguished by origin, color, size, and type: blue group (BG), red group (RG), green group (GG), and yellow group (YG). The six investigated traits were age at first calving (AFC), productive lifespan (PL), number of calves born (NCB), culling age (AGE), birth weight (BW), and the 205 d adjusted weaning weight (WW). The averages of the six tested traits were as follows: AFC – 2.35 ± 0.54 years; NCB – 5.89 ± 3.69 heads; PL – 6.85 ± 4.13 years; AGE – 9.2 ± 4.26 years; BW – 29.4 ± 4.28 kg; and WW – 176.9 ± 44.07 kg. YG excelled in terms of NCB, PL, AGE, and WW traits, while RG performed best in terms of AFC and BW. BG displayed the lowest performance across NCB, PL, AGE, BW, and WW. The heavier Red Angus individuals were largely behind the performance of the traditional-type, smaller British-type Black and Red Angus individuals in the tested traits affecting sustainability and profitability. Significant reproduction and longevity trait differences exist among different genetic groups of Angus beef cattle genotyped by DNA microsatellite information. The results indicated significant differences in terms of the performance of different Angus types with regard to the tested traits. These findings could be useful in developing breeding concepts and making selection decisions, contributing to more efficient and sustainable breeding strategies.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('11584f02-5eb7-4bab-a730-f2a3af129ae4', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genetic prediction for first-service conception rate in Angus heifers using a random regression model', 'Miguel Angel Sanchez-Castro, Milton Thomas, R. M. Enns, Scott E Speidel', 2020, 'Translational Animal Science', '10.1093/tas/txaa094', 'https://doi.org/10.1093/tas/txaa094', 'https://academic.oup.com/tas/article-pdf/4/Supplement_1/S43/35057651/txaa094.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'First-service conception rate (FSCR) could be defined as the probability of a heifer to conceive in response to her first artificial insemination (AI) and maintain such pregnancy after the end of the breeding season. Economic implications of this trait in beef cattle heifers involve its relationship with their development costs, as well as costs of semen, synchronization protocols, estrus detection and AI services (Horan et al., 2005; Minick Bormann et al., 2006). Furthermore, FSCR is also related to differences in quality and value between AI-produced calves and natural service calves. Additionally, heifers conceiving on their first service, calve earlier within the calving season, have more chances to breed postpartum within a year, and have more time to nurse and wean heavier calves (Marshall et al., 1990). Given the binary nature of pregnancy outcomes after an AI, the method of choice to evaluate FSCR has been an animal threshold model (ATM). However, such method has a lack of ability to incorporate information of contemporary groups with no variation (e.g., extreme-category problem). When all observations within a categorical fixed effect fall in one of the binary classes, typically, these observations are deleted from the data in order to calculate expected progeny differences (EPD). This can lead to distorted genetic predictions because edited data do not appropriately represent the population’s true variability (Misztal et al., 1989). Random regression models (RRM) represent an alternative method to evaluate binary traits and can incorporate data from contemporary groups with no variation (Golden et al., 2018). Nonetheless, since they were originally conceptualized to analyze longitudinal traits, the efficacy of RRM to evaluate traits with phenotypes observed only once has not been deeply explored. Relative to heifer fertility, these models have only been applied in genetic evaluations for heifer pregnancy (HPG) in Red Angus cattle (Speidel et al., 2018). Therefore, objectives herein were to evaluate the efficacy of a RRM genetic prediction for heifer FSCR by comparing the resulting EPD to those obtained using a traditional ATM, as well as to compare genetic parameters obtained with each methodology in Angus cattle. The data used in the present study were obtained from an existing database; therefore, the study was not subjected to animal care and use committee approval. Breeding and ultrasound records of 4,334 Angus heifers (progeny of 354 sires and 1,626 dams) collected from 1992 to 2019 at the Colorado State University Beef Improvement Center (CSU-BIC) were used for the study. Within each breeding year, heifers were estrus synchronized and subjected to AI only once, before they were exposed to natural service sires approximately 3 wk after insemination. Observations for FSCR (1, successful; 0, unsuccessful) were defined by fetal age obtained from ultrasound pregnancy exams performed 130 d post-AI. Although FSCR in 12- to 15-mo-old heifers is a singly observed phenotype, its expression is likely to be dependent on age of onset of puberty. Consequently, age at AI was an important factor included in all statistical models, and it was calculated as the difference between an individual’s birthdate and the date when they were subjected to AI. Traditional EPD calculation for FSCR was performed using a univariate BLUP threshold animal model along with a probit link function to convert binary observations to an underlying normal distribution. The model equation was as follows: where y* corresponded to a vector of transformed observations of FSCR on the underlying scale, b was a vector of unknown solutions for fixed effects that included breeding contemporary group (defined as a combination between breeding year and semen type), AI technician and age of dam, individual’s age at AI was included as a linear covariate, u corresponded to a vector of unknown solutions of animal random effects, and m was a vector of unknown solutio', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a28fb882-933a-4dbe-b566-b744329e34b3', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Cow efficiency: modeling the biological and economic output of a Michigan beef herd', 'Logan R Thompson, Matthew R Beck, D. D. Buskirk, Jason E. Rowntree, Melissa G.S. McKendree', 2020, 'Translational Animal Science', '10.1093/tas/txaa166', 'https://doi.org/10.1093/tas/txaa166', 'https://academic.oup.com/tas/article-pdf/4/3/txaa166/34062559/txaa166.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Abstract In recent decades, beef cattle producers have selected cattle for biological traits (i.e., improved growth) to maximize revenue, leading to an increase in average cow body size. However, matching cow size to the production environment would allow producers to maximize productivity and economic returns per unit of land. This may help meet the goals of sustainable intensification, but environmental complexity and varying cow-calf production systems dictates a regional approach. The objective of this experiment was to examine the biological efficiency and economic returns of a Northern Michigan cow-calf system. We hypothesized that biological efficiency and economic returns would decrease with increasing cow body size. Data were collected from a Red Angus cow herd located at the Lake City AgBio Research Center in Lake City, MI from 2011 to 2018 on cow age, weight, and body condition score at weaning, and subsequent 205 d adjusted calf weaning weight (WW), sex, and yearling weight. Biological efficiency was defined as WW as a percentage of cow body weight (DBW). Enterprise budgeting techniques were used to calculate expected net returns from 2011 to 2018 after classifying cows into 11 BW tiers at 22.67 kg intervals beginning at 430.83 kg. Forward-looking net present value (NPV) was calculated using the same tier system, for a 10-yr production cycle with the baseline being a 200 d grazing season. Weaning weight increased with increasing DBW (P < 0.01), but the percentage of cow body weight weaned was reduced by −38.58 × Ln(DBW) (P < 0.01). This led to cows weaning 26.38 kg/ha more with every 100 kg drop in DBW. Expected net returns from 2011 to 2018 did not differ by DBW tier on a per cow basis but did on a per ha basis with a decrease in $10.27/ha with each increase in DBW tier (P < 0.01). Net present value was maximized in the baseline scenario at 453.51 kg DBW and decreased in value as DBW increased. These results suggest that for a Northern Midwestern cow-calf herd, comparatively lighter cows provide a higher economic value on a land basis.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('552e4684-f88a-426a-a020-f04efab9e3dd', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Development of a feet and leg scoring method and selection tool for improved soundness in Red Angus cattle', 'Lane K Giess', 2017, 'K-State Research Exchange (Kansas State University)', NULL, 'http://hdl.handle.net/2097/38258', 'http://hdl.handle.net/2097/38258', NULL, NULL, 101, NULL, 'other', 1, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29fcfa9b-500f-43ca-8a30-c8d5e9dddf5a', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genetic parameters for fertility and production traits in Red Angus cattle', 'Ryan J Boldt, Scott E Speidel, Milton Thomas, R. M. Enns', 2018, 'Journal of Animal Science', '10.1093/jas/sky294', 'https://doi.org/10.1093/jas/sky294', 'https://academic.oup.com/jas/article-pdf/96/10/4100/25863271/sky294.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ae9efc53-5553-40ad-9c57-38990fadf920', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Effects of a long-acting trace mineral rumen bolus upon range cow productivity', 'Sprinkle JE, Schafer DW, Cuneo SP, Tolleson DR, Enns RM', 2021, 'Translational animal science', '10.1093/tas/txaa232', 'https://doi.org/10.1093/tas/txaa232', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7810256.1/PMC7810256.1.pdf', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'The objectives were to determine if strategic supplementation of range cows in central Arizona with either two or four long acting (6 mo) trace mineral rumen boluses containing Cu, Se, and Co would: 1) decrease yearly calving interval; 2) increase cow body condition, milk production, or calf adjusted weaning weights; and 3) to see if any of the above traits varied by cow breed. There were 194 Hereford (H) and 132 Composite (CGC; 50% Red Angus, 25% Tarentaise, 25% Charolais) control cows, 173 H and 125 CGC 1X treated (2 boluses in late winter) cows, and 183 H and 117 CGC 2X treated (2 boluses in autumn and 2 in late winter) cows used over the 4-yr period. Cows were weighed and scored for body condition (1-9, 9 = fattest) in February, May, and September of each year. Milk production was determined by weigh-suckle-weigh on a subset of cows (n = 169) at an average of 50 d lactation. The outcomes were analyzed using a restricted maximum likelihood-based mixed-effects model that included the categorical, fixed effects of breed, bolus, and year with the interactions of breed × bolus, and breed × year. For adjusted weaning wt (WW), year × bolus was added. The random effect of cow was also included. Calving interval had only the breed × bolus interaction added to the main effects. Age of dam was added as a covariate to all models. Milk production used the same model as calving interval with the added covariate of postpartum interval. Cow body condition score and calf adjusted weaning weights differed by breed and treatment (P P P 0.0001) but did not differ by either breed or treatment (P > 0.05). Calving interval was 389 ± 2.7, 382 ± 3.2, and 378 ± 3.2 d for control, 1X, and 2X treatments, respectively and calving interval declined (P < 0.05) from the control to the 2X treatment group. Strategic supplementation via a long-acting trace mineral bolus was successful in decreasing calving interval and increasing calf-weaning weights from cattle grazed in an extensive rangeland environment.', '{epmc,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4d26e5a1-2489-4a19-a362-2aa799147d03', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Effects of Anabolic Implants and Breed Group on Carcass Traits and Palatability Characteristics of Bullock Beef', 'R.C. Johnson, D. H. Gee, W. J. Costello, C. W. Carlson', 1986, 'Journal of Animal Science', '10.2527/jas1986.622399x', 'https://doi.org/10.2527/jas1986.622399x', 'https://openprairie.sdstate.edu/etd/4213', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff5db547-1633-4fd9-9aad-137964e36b09', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Evaluation of a commercial genetic test for fescue toxicosis in pregnant Angus beef cattle1', 'Justine M. Galliou, Piush Khanal, Kyle Mayberry, Matt H Poore, Daniel H. Poole, Nick V. L. Serão', 2020, 'Translational Animal Science', '10.1093/tas/txaa181', 'https://doi.org/10.1093/tas/txaa181', 'https://academic.oup.com/tas/article-pdf/4/4/txaa181/35234307/txaa181.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Most tall fescue [Lolium arundinaceum (Schreb.) Darbysh] in the Southeastern United States contains an endophyte that causes fescue toxicosis (FT) in grazing animals, a serious disease that causes approximately $1 billion in economic losses to the animal industries in the United States. Recently, a genetic test called T-Snip (AgBotanica, LCC, Columbia, MO), was developed with the objective of identifying animals with genetic variation for FT tolerance. The aim of this study was to validate the use of this genetic test in mature, pregnant cows. Over 13 wk, weekly phenotypic data, including body weight, rectal temperatures, hair coat scores, hair shedding scores, and body condition scores, were collected on 148 pregnant purebred Angus cows at 2 locations in NC where infected fescue was the primary source of feed. Birth weights (cBW) and 205-d adjusted weaning weights (adjWW) from these cow’s calves were recorded. All cows were genotyped for T-Snip. At the end of the trial, each phenotypic trait was calculated as the slope of the linear regression of performance on weeks. The effect of T-Snip rating genotypes (4 levels) on slope traits was tested using a linear model also including the fixed-effects of location, parity, and the initial measurement for each trait (covariate). For cBW and adjWW, the model also included the sex of the calf and the month of birth as categorical effects. Associations of T-Snip genotypes were observed for body weight gain (aBWd) of pregnant cows (P = 0.15; interaction with location), change in body condition score (aBCSd; P = 0.13), and adjWW (P = 0.06; interaction with location). For aBWd and adjWW, associations were found just within one location (P = 0.017 and 0.047, respectively), which was the location with higher endophyte infection rate. For all associations, the direction of the T-Snip genotypes was the same and as expected: the greater the genotype score, the better performance. No associations were found for the other traits (P > 0.10). These results indicate that the T-Snip test may be predictive of cow performance (aBWd, aBCSd, and adjWW) in an endophyte-infected tall fescue environment.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a2c05c1-32fb-41f2-9a50-c80f0695aaef', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genome-wide association and genotype by environment interactions for growth traits in U.S. Red Angus cattle', 'Johanna L. Smith, Miranda L. Wilson, Sara M. Nilson, Troy N. Rowan, Robert D. Schnabel, Jared E. Decker, Christopher M. Seabury', 2022, 'BMC Genomics', '10.1186/s12864-022-08667-6', 'https://doi.org/10.1186/s12864-022-08667-6', 'https://bmcgenomics.biomedcentral.com/counter/pdf/10.1186/s12864-022-08667-6', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Genotypic information produced from single nucleotide polymorphism (SNP) arrays has routinely been used to identify genomic regions associated with complex traits in beef and dairy cattle. Herein, we assembled a dataset consisting of 15,815 Red Angus beef cattle distributed across the continental U.S. and a union set of 836,118 imputed SNPs to conduct genome-wide association analyses (GWAA) for growth traits using univariate linear mixed models (LMM); including birth weight, weaning weight, and yearling weight. Genomic relationship matrix heritability estimates were produced for all growth traits, and genotype-by-environment (GxE) interactions were investigated. RESULTS: Moderate to high heritabilities with small standard errors were estimated for birth weight (0.51 ± 0.01), weaning weight (0.25 ± 0.01), and yearling weight (0.42 ± 0.01). GWAA revealed 12 pleiotropic QTL (BTA6, BTA14, BTA20) influencing Red Angus birth weight, weaning weight, and yearling weight which met a nominal significance threshold (P ≤ 1e-05) for polygenic traits using 836K imputed SNPs. Moreover, positional candidate genes associated with Red Angus growth traits in this study (i.e., LCORL, LOC782905, NCAPG, HERC6, FAM184B, SLIT2, MMRN1, KCNIP4, CCSER1, GRID2, ARRDC3, PLAG1, IMPAD1, NSMAF, PENK, LOC112449660, MOS, SH3PXD2B, STC2, CPEB4) were also previously associated with feed efficiency, growth, and carcass traits in beef cattle. Collectively, 14 significant GxE interactions were also detected, but were less consistent among the investigated traits at a nominal significance threshold (P ≤ 1e-05); with one pleiotropic GxE interaction detected on BTA28 (24 Mb) for Red Angus weaning weight and yearling weight. CONCLUSIONS: Sixteen well-supported QTL regions detected from the GWAA and GxE GWAA for growth traits (birth weight, weaning weight, yearling weight) in U.S. Red Angus cattle were found to be pleiotropic. Twelve of these pleiotropic QTL were also identified in previous studies focusing on feed efficiency and growth traits in multiple beef breeds and/or their composites. In agreement with other beef cattle GxE studies our results implicate the role of vasodilation, metabolism, and the nervous system in the genetic sensitivity to environmental stress.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c0c01d41-9f8b-4f8f-b72d-c2f05f582267', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Evaluation of Resistance to Fescue Toxicosis in Purebred Angus Cattle Utilizing Animal Performance and Cytokine Response', 'Daniel H. Poole, Kyle Mayberry, McKayla A Newsome, Rebecca K Poole, Justine M. Galliou, Piush Khanal, Matthew H. Poore, Nick V. L. Serão', 2020, 'Toxins', '10.3390/toxins12120796', 'https://doi.org/10.3390/toxins12120796', 'https://www.mdpi.com/2072-6651/12/12/796/pdf?version=1608014924', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Fescue toxicosis is a multifaceted syndrome common in cattle grazing endophyte-infected tall fescue; however, varying symptomatic responses potentially imply genetic tolerance to the syndrome. It was hypothesized that a subpopulation of animals within a herd would develop tolerance to ergot alkaloid toxicity. Therefore, the goals of this study were to develop selection criteria to identify tolerant and susceptible animals within a herd based on animal performance, and then examine responsive phenotypic and cytokine profiles to fescue toxicosis. Angus cows grazed endophyte-infected tall fescue at two locations for 13 weeks starting in mid-April 2016. Forage measurements were collected to evaluate ergot alkaloid exposure during the study. A post hoc analysis of animal performance was utilized to designate cattle into either tolerant or susceptible groups, and weekly physiological measurements and blood samples were collected to evaluate responses to chronic exposure to endophyte-infected tall fescue. Findings from this study support the proposed fescue toxicosis selection method formulated herein, could accurately distinguish between tolerant and susceptible animals based on the performance parameters in cattle chronically exposed to ergot alkaloids, and provides evidence to warrant additional analysis to examine the impact of ergot alkaloids on immune responsiveness in cattle experiencing fescue toxicosis.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3205895-34d0-4027-b94b-b0a73ba7bd21', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Evaluation of the effect of alternative measurements of body weight gain and dry matter intake for the calculation of residual feed intake in growing purebred Charolais and Red Angus cattle1', 'William Christian Kayser, James B Glaze, C. M. Welch, M. S. Kerley, Rodney A. Hill', 2015, 'Journal of Animal Science', '10.2527/jas.2014-8337', 'https://doi.org/10.2527/jas.2014-8337', 'https://academic.oup.com/jas/article-pdf/93/7/3675/23775990/3675.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d73d014f-cdbd-4318-afc4-517d4aaaf978', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genomic Analysis of Purebred and Crossbred Angus Cows Quantifies Heterozygosity, Breed, and Additive Effects on Components of Reproduction', 'Wayne S. Pitchford, J. M. Pitchford, J. G. Alexopoulos, M. L. Hebart', 2021, 'Animals', '10.3390/ani12010061', 'https://doi.org/10.3390/ani12010061', 'https://www.mdpi.com/2076-2615/12/1/61/pdf?version=1641371647', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Multiple studies have quantified the production differences of Hereford Angus crossbreds compared to purebred Angus for a range of traits including growth, carcass, and reproductive traits. This study aims to quantify breed and heterosis effects on maternal performance using genomics. Thirty Hereford and thirty Angus sires were mated to 1100 Angus heifers and cows in a large commercial herd run on pasture at Musselroe Bay, Tasmania, Australia. Approximately 1650 calves were born. Heifers were weaned, scanned for attainment of puberty prior to joining at approximately 15 months of age, joined, and then recorded for status of pregnancy, calving, lactating, 2nd pregnancy, and weaning of second calf. Heterozygosity effects were significant for heifer pre-joining weight and height as well as proportion pubertal. Breed differences were significant for the same traits plus pregnancy rate at second joining and proportion rearing two calves. Genetic parameters were reported for 13 traits. On average, higher genetic merit (Estimated Breeding Value, EBV percentile) Hereford bulls were used than Angus for growth and puberty, but they were similar for fat and reproduction. Days to calving BREEDPLAN EBVs of the sires were related to puberty and reproduction. Scrotal size BREEDPLAN EBVs of the sires were related to attainment of puberty genomic EBVs calculated. In summary, breed differences in growth and puberty were due to heterosis, but there was an advantage of Hereford genes for reproductive performance. Ongoing emphasis on selection for reduced days to calving and estimation of multi-breed EBVs is important.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('da8d6b3f-ebde-4c8c-b714-691b0f9192a2', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genomic structure and selection history across Angus populations worldwide: insights from ROH, selection mapping, and functional analyses', 'Henrique A. Mulim, Gabriel Soares Campos, F. F. Cardoso, Victor Breno Pedrosa, Kajal Latimer, Lindsay R Upperman, A. J. Knowles, Andre Garcia', 2025, 'Mammalian Genome', '10.1007/s00335-025-10188-y', 'https://doi.org/10.1007/s00335-025-10188-y', 'https://link.springer.com/content/pdf/10.1007/s00335-025-10188-y.pdf', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by', 'Angus cattle, originally from Scotland, have been selectively bred for over 400 years, making them one of the most prominent beef breeds globally. Known for their adaptability, natural polled traits, and high-quality beef, Angus cattle have been intensively selected for growth, body size, and feed efficiency. This study investigates the genetic diversity, selection history, and key genomic regions across five Angus populations from the USA, Canada, Australia, Brazil, and Red Angus of America. Genomic data from 71,283 animals born between 1961 and 2024 were analyzed using Principal Component Analysis (PCA), phylogenetic tree construction, and Runs of Homozygosity (ROH), with the Generation Proxy Selection Mapping (GPSM) approach used to assess selection history. Functional annotation identified candidate genes and pathways related to selection. Our analysis revealed both similarities and differences across populations. The PCA and FST metrics showed minimal differentiation between the American, Canadian, Australian, and Brazilian populations, with greater differentiation observed in the Red Angus population. The ROH analysis revealed that the Brazilian population had the highest number of ROHs. The ROH islands identified on BTA8 and BTA13 in the American and Australian populations were linked to traits like body weight, marbling, and tenderness. The GPSM identified significant markers associated with body weight and growth in all populations, reflecting ongoing selection pressures. This study highlights the potential of genomics to improve our understanding of Angus cattle''s genetic architecture and selection history. It underscores the feasibility of integrating global populations for more accurate genomic evaluations, enhancing genetic predictions, and supporting sustainable beef production worldwide.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c57c8a66-9a59-4fd4-b75e-05a095bf9748', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Genotype by environment interactions for growth in Red Angus1', 'Dennis Fennewald, Robert L Weaber, William R. Lamberson', 2017, 'Journal of Animal Science', '10.2527/jas.2016.0846', 'https://doi.org/10.2527/jas.2016.0846', 'https://krex.k-state.edu/bitstreams/72483cd4-ef05-46d1-9a98-dff526d09ddb/download', NULL, NULL, 7, NULL, 'other', 1, NULL, NULL, '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('321af3a5-4105-4295-a18d-c236a17f06b6', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Influence of beef genotypes on animal performance, carcass traits, meat quality, and sensory characteristics in grazing or feedlot-finished steers', 'Isabella Cristina de Faria Maciel, Jeannine P. Schweihofer, Jenifer I. Fenton, Jennifer Hodbod, Melissa G.S. McKendree, Kimberly A. Cassida, Jason E. Rowntree', 2021, 'Translational Animal Science', '10.1093/tas/txab214', 'https://doi.org/10.1093/tas/txab214', 'https://eprints.whiterose.ac.uk/200298/1/txab214.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Abstract A 2-yr study was conducted to evaluate the effects of beef genotypes and feeding systems on performance, carcass traits, meat quality, and sensory attributes. A 2×2 factorial experiment was used to randomly allocate 60 steers in year 1 (YR1) and 44 steers in year 2 (YR2). The two beef genotypes evaluated were Red Angus (RA), and RA x Akaushi (AK) crossbreed. The steers were allotted to two finishing feeding systems: grazing, a multi-species forage mixture (GRASS) and feedlot finishing, conventional total mixed ration (GRAIN). All steers were slaughtered on the same day, at 26 and 18 mo of age (GRASS and GRAIN, respectively), and carcass data were collected 48 h postmortem. Growth and slaughter characteristics were significantly impacted by the finishing system (P < 0.01), with the best results presented by GRAIN. Beef genotype affected dressing percent (P < 0.01), ribeye area (P = 0.04), and marbling score (P = 0.01). The AK steers had a tendency (P = 0.09) for lower total gain; however, carcass quality scores were greater compared to RA. There was a genotype by system interaction for USDA yield grade (P < 0.01), where it was lower in GRASS compared to GRAIN in both genotypes, and no difference was observed between the two genotypes for any GRASS or GRAIN systems. There was no difference in meat quality or sensory attributes (P > 0.10) between the two genotypes, except that steaks from AK tended to be juicier than RA (P = 0.06). Thawing loss and color variables were impacted by the finishing system (P < 0.01). L* (lightness) and hue angle presented greater values while a* (redness), b* (yellowness), and chroma presented lower values in GRAIN compared to GRASS. Sensory attributes were scored better in GRAIN than GRASS beef (P < 0.01). There was a genotype by system interaction for flavor (P = 0.02), where beef from RA had a lower flavor rating in GRASS than in GRAIN, and no difference was observed for AK. Within each system, no difference was observed for flavor between RA and AK. Beef from steers in GRASS had greater (P < 0.01) WBSF than those from GRAIN. These results indicate that steers from GRAIN had superior performance and carcass merit and that AK enhanced these traits to a greater degree compared to RA. Furthermore, the beef finishing system had a marked impact on the steaks’ sensory attributes and consumer acceptability. The favorable results for texture and juiciness in GRAIN, which likely impacted overall acceptability, may be related to high marbling.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cd81c508-330d-4d06-8ba7-4b2a2e7ea8b9', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Meat and sensory quality of major muscles from Angus, Charolais, and Angus crossbred steers with high and low residual feed intake', 'Zhiqiang Jiu, Bimol C. Roy, Chamali Das, Wendy Victoria Wismer, Manuel M Juarez, Carolyn Fitzsimmons, Changxi Li, Graham Stuart Plastow', 2019, 'Canadian Journal of Animal Science', '10.1139/cjas-2019-0012', 'https://doi.org/10.1139/cjas-2019-0012', 'https://utoronto.scholaris.ca/bitstreams/956b19b5-107e-4320-8200-8ec934f5f18b/download', NULL, NULL, 34, NULL, 'alberta', 4, 'cc-by', 'Effects of residual feed intake (RFI) and genetic group on growth, carcass, and meat quality characteristics of bovine longissimus lumborum (LL), triceps brachii (TB), semimembranosus (SM), and gluteus medius (GM) muscles were investigated using 72 purebred Angus, purebred Charolais, and Angus crossbred steers (n = 24 per genetic group) classified as either high (inefficient) or low (efficient) RFI (n = 12 high and low RFI steers within genetic group). There was no RFI effect (P > 0.05) on growth, carcass, and meat quality measurements except high RFI steers had the highest dry matter intake (P < 0.05), and low RFI TB was rated as having reduced beef flavour intensity and sustained juiciness (P < 0.05). Purebred Angus and Charolais LL and GM had lower shear force values (P < 0.05) than Angus crossbreds and ageing reduced mean shear force values except in TB. For TB, SM, and GM, Angus crossbred steers had the highest mean beef flavour intensity scores, and Charolais SM and TB were less tender than those of Angus crossbred (P < 0.05). Overall, RFI did not influence most meat quality traits; therefore, low RFI animals may contribute to reducing feed costs or environmental impact without compromising meat quality and palatability.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3c82538a-3562-4a69-9642-579bea5dee01', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Methionine supplementation during late gestation in March calving Angus crossbred beef heifers and cows', 'Christenson DM, Tadich LF, Funston RN', 2026, 'Translational animal science', '10.1093/tas/txag129', 'https://doi.org/10.1093/tas/txag129', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13682610.1/PMC13682610.1.pdf', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'The objectives of these two studies were to evaluate the impact of excess Met (methionine) supplementation during late gestation on intake, body weight (BW), average daily gain (ADG), reproductive performance, and subsequent calf performance in artificially inseminated heifers and naturally bred cows. In Exp. 1, a 3-yr study used 38 pregnant Black Angus crossbred heifers/yr (n = 113) in a Calan gate feeding system. There was a 20-d acclimation period before the 93 ± 6-d trial began 161 ± 6 d after artificial insemination. Heifers were assigned to one of three treatments and fed ad libitum hay with either no supplement (HAY1), 0.9 kg/d dried distillers'' grain (DDG), or 0.9 kg/d dried distillers'' grain with 30 g/d of a methionine hydroxy analog (MET1). In Exp. 2, a 3-yr study used 145 pregnant Red Angus crossbred cows/yr (n = 436) on upland winter range fed one of five treatments: no supplement (NS), ad libitum hay (HAY2), 0.45 kg/d of a distillers''-based cube (CAKE1), 0.9 kg/d of a distillers-based cube (CAKE2), or 0.9 kg/d of a distillers''-based cube plus 30 g/d of a methionine hydroxy analog (MET2). In Exp. 1, hay dry matter intake during the trial period was not different (P = 0.38) but final BW and ADG were greater (P BCS) at the end of the trial period than other treatments (P P P P = 0.09) for calves from HAY2 cows to have greater marbling compared to NS. There were no other differences in calving performance or progeny carcass characteristics in either experiment. While late gestational protein supplementation impacted BW and ADG in heifers, and BW and BCS in cows, there were no significant differences in the dam or progeny due to Met supplementation.', '{epmc,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c4f63ba0-e588-4ba6-8982-6780015a4228', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Separation Behavior for Parturition of Red Angus Beef Cows', 'Cornelia Flörcke, Temple Grandin', 2014, 'Open Journal of Animal Sciences', '10.4236/ojas.2014.42007', 'https://doi.org/10.4236/ojas.2014.42007', 'http://www.scirp.org/journal/PaperDownload.aspx?paperID=44263', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc-by', 'Increased predation losses in beef cattle in the Northern Rocky Mountains raise the importance of research concerning maternal behavior around the time of parturition. Separation behavior of multiparous cows at parturition was studied by measuring the distance (m) between the birth place and the main herd with a GPS device. Age of cows and forehead hair whorl pattern (HW) were analyzed as possible factors affecting separation distance. A total of 333 cows (95% Red Angus and 5% Angus × Hereford commercial crossbreds; age range: 3 - 6 yrs) were studied. Separation distance was determined by approaching the cow-calf pair with a utility vehicle that gradually decreased the distance to the pair. The geographic coordinates per pair were recorded and the separation distance was calculated as a straight line between each pair and the main herd. The HW on the forehead of each animal was used as a measure of individual differences in temperament. Age and HW were collected when the animals were held in a squeeze chute. HW was classified into one of six groups: high, middle, low, abnormal, multiple HWs and no HW. The age of a cow influenced the separation distance for parturition (P < 0.001). Four-year-old cows were on average about 150 m further away than other aged cows when calving. Eighty-eight percent of cows separated more than 100 m from the herd. The hair whorl position had no influence on the separation distance (P = 0.405). Distinct separation behavior for parturition was observed in this herd which appears to be an innate behavior that is influenced by the individual temperament of the cow.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e8068c38-7ca9-4733-955d-7dbcf1e02e04', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'The effect of a commercial feed additive on the immune-metabolic axis, liver function and predicted carcass quality in purebred Angus steers', 'Shelby A Armstrong, D. J. McLean, Gerd Bobe', 2018, 'Livestock Science', '10.1016/j.livsci.2018.02.002', 'https://doi.org/10.1016/j.livsci.2018.02.002', 'https://www.sciencedirect.com/science/article/pii/S1871141318300301/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'To determine the effect of the commercial feed additive OmniGen-AF® on immune, physiological, and carcass ultrasound variables in steers during backgrounding, transition, and finishing phases, nine purebred Angus half-sibling steers were randomly assigned to one of two treatment groups: Control (n = 4) and OmniGen-AF (OG; n = 5). Cattle were offered 0 (Control) or 56 g daily of OG throughout a 28-d backgrounding period (limit-fed a predominantly forage diet), a 14-d transition period, and a 56-d finishing period on a high concentrate diet (104 days total). During the three feeding periods, whole blood and serum was collected to evaluate markers of immune function and physiology, respectively. Across basal diet phases, OG supplementation increased serum chloride (P = 0.02) and haptoglobin (P = 0.03) concentrations and decreased serum NEFA (P = 0.001) concentrations. At the end of the high-concentrate finishing period, OG supplementation vs. Control attenuated the decrease in serum paraoxonase and the increase in AST concentrations, a marker of liver cell necrosis. Carcass prediction measurements, collected in 30-day intervals during the finishing phase, indicated lower predicted numerical yield grades (P = 0.03) due to higher REA (P = 0.009) and a tendency for less 12th rib fat (P = 0.06) in Control vs. OG steers. Weight gain, feed intake, feed efficiency, and predicted quality grades did not differ between treatments. In conclusion, OG may act on the immune-metabolic axis across the three studied basal diet phases to support healthier livers and improved predicted yield grades in Angus steers by decreasing fat deposition and increasing REA.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e1f57b5c-00cd-4987-983a-11b60683dca9', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'The impact of sire breed on feedlot performance and carcass characteristics of beef × Holstein steers', 'Bailey L Basiel, Jonathan A Campbell, C.D. Dechow, T. L. Felix', 2024, 'Translational Animal Science', '10.1093/tas/txae043', 'https://doi.org/10.1093/tas/txae043', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11005759/pdf/txae043.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc', 'Abstract Dairy herds are mating a portion of cows to beef cattle semen to create a value-added calf. Objectives of this study were to compare the feedlot performance and carcass characteristics of beef × Holstein steers by breed when sires represented bulls with commercially available semen. Three groups of single-born, male calves (n = 262) born to Holstein dams on 10 Pennsylvania dairies were sourced during 3 yr. Steers were sired by seven beef breeds: Angus, Charolais, Limousin, Hereford, Red Angus, Simmental, and Wagyu. Steers were picked up within a week of age and raised at two preweaned calf facilities until weaning (8 ± 1 wk of age) under similar health and management protocols. Steers were then transported to a commercial calf growing facility where they were managed as a single group until 10 ± 2 mo of age when they were moved to be finished at the Pennsylvania Department of Agriculture’s Livestock Evaluation Center feedlot. Groups of steers were selected for slaughter based on body weight. Carcass characteristics were evaluated by trained personnel and a three-rib section of the longissimus muscle (LM) was collected from each carcass for Warner-Bratzler shear force (WBSF) evaluation and intramuscular fat determination. Steers sired by all sire breeds except for Limousin had greater average daily gain (ADG; 1.62 to 1.76 kg/d) than Wagyu × Holstein steers (1.39 kg/d; P < 0.05). Angus-sired steers had an 8.6% greater ADG than Red Angus-sired steers (P < 0.05). Angus, Charolais (1.73 kg/d), and Simmental-sired steers (1.68 kg/d) also had greater ADG than Limousin-sired steers (1.55 kg/d; P < 0.05). Wagyu × Holstein steers spent 5 to 26 more days on feed (P < 0.05) than Limousin × Holstein, Simmental × Holstein, Angus × Holstein, and Charolais × Holstein steers. Angus and Charolais-sired steers were also on feed for 19 and 21 d fewer, respectively, than Limousin-sired steers (P < 0.05). Red Angus-sired steers had greater marbling scores than Simmental and Limousin-sired steers and Angus and Charolais-sired steers had greater marbling scores than Limousin-sired steers (P < 0.05). Angus, Limousin, and Hereford-sired steers produced the most tender LM as evaluated by WBSF; Angus-sired carcasses (3.82 kg) were more tender than Charolais (4.30 kg) and Simmental-sired carcasses (4.51 kg; P < 0.05). Limousin and Hereford-sired steers (3.70 and 3.83 kg, respectively) also had more tender steaks than Simmental-sired steers.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d7087174-1fdd-4dd2-8377-00e696a05390', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Uncovering genomic diversity and signatures of selection in red Angus × Chinese red steppe crossbred cattle population', 'Elaheh Rostamzadeh Mahdabi, Rugang Tian, Jing Tian, Hojjat Asadollahpour Nanaie, Xiao Wang, Meng Zhao, Hui Li, Baolige Dalai', 2025, 'Scientific Reports', '10.1038/s41598-025-98346-9', 'https://doi.org/10.1038/s41598-025-98346-9', 'https://www.nature.com/articles/s41598-025-98346-9.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Crossbreeding is a cornerstone of modern livestock improvement, combining desirable traits to enhance productivity and environmental resilience. This study conducts the first comprehensive genomic analysis of Red Angus × Chinese Red Steppe (RACS) crossbred cattle, evaluating their genetic architecture, diversity, and selection signatures relative to founder breeds (Red Angus and Chinese Red Steppe) and global populations. A total of 119 cattle, comprising 104 RACS crossbreds and 15 Chinese Red Steppes cattle, were genotyped using the GGP Bovine 100k SNP array. Additionally, the public available genotypic data generated using the BovineSNP50 chip from 550 animals across eight beef breeds (Angus, Hereford, Limousin, Charolais, Mongolian, Shorthorn, Red Angus, and Simmental) and one dairy breed (Holstein) were incorporated into the analysis. We aimed to (1) define the population structure of RACS cattle, (2) quantify their genomic diversity and inbreeding levels, and (3) pinpoint regions under selection linked to adaptive and economic traits. We employed runs of homozygosity (ROH) and population differentiation (Fst) analyses to detect selection signals. The results revealed that the crossbred (RACS), Angus, and Red Angus breeds exhibited similar clustering patterns in principal component analysis (PCA), but the crossbred population showed the highest nucleotide diversity and lowest inbreeding coefficients compared to other breeds. Notably, candidate regions associated with immune response, cold adaptation, and carcass traits were identified within the RACS population. These findings enhance our understanding of the genetic makeup of crossbred beef cattle and highlight their potential for genetic improvement, informing future selection and breeding strategies aimed at optimizing beef production in challenging environments.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4fdc306-b0d7-4cb8-b355-d195cec774ae', '2c9fdaa9-f285-4484-ac79-fa71d5d3dc64', 'Water conservation methods to conserve the High Plains aquifer and Arikaree River Basin: a case study on the Arikaree River', 'Adam Prior, Oad, Ramchand Naraindas, Podmore, Terence H., James G. Pritchett', 2007, 'Digital Collections of Colorado (Colorado State University)', '10.25675/3.018343', 'https://doi.org/10.25675/3.018343', 'http://hdl.handle.net/10217/44948', NULL, NULL, 253, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('42835d8f-5dd3-4704-b283-a7280795cc3a', '6175c5a0-3ffc-49e4-acb8-2a25ff771567', 'Uncovering the architecture of selection in two Bos taurus cattle breeds', 'Troy N. Rowan, Robert D. Schnabel, Jared E. Decker', 2024, 'Evolutionary Applications', '10.1111/eva.13666', 'https://doi.org/10.1111/eva.13666', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10883790/pdf/EVA-17-e13666.pdf', NULL, NULL, 36, NULL, 'other', 1, 'cc-by', 'Directional selection alters the genome via hard sweeps, soft sweeps, and polygenic selection. However, mapping polygenic selection is difficult because it does not leave clear signatures on the genome like a selective sweep. In populations with temporally stratified genotypes, the Generation Proxy Selection Mapping (GPSM) method identifies variants associated with generation number (or appropriate proxy) and thus variants undergoing directional allele frequency changes. Here, we use GPSM on two large datasets of beef cattle to detect associations between an animal''s generation and 11 million imputed SNPs. Using these datasets with high power and dense mapping resolution, GPSM detected a total of 294 unique loci actively under selection in two cattle breeds. We observed that GPSM has a high power to detect selection in the very recent past (<10 years), even when allele frequency changes are small. Variants identified by GPSM reside in genomic regions associated with known breed-specific selection objectives, such as fertility and maternal ability in Red Angus, and carcass merit and coat color in Simmental. Over 60% of the selected loci reside in or near (<50 kb) annotated genes. Using haplotype-based and composite selective sweep statistics, we identify hundreds of putative selective sweeps that likely occurred earlier in the evolution of these breeds; however, these sweeps have little overlap with recent polygenic selection. This makes GPSM a complementary approach to sweep detection methods when temporal genotype data are available. The selected loci that we identify across methods demonstrate the complex architecture of selection in domesticated cattle.', '{openalex,breed}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f1702dd5-4549-44bd-b683-539f9a677882', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'An experimental model to induce digital dermatitis in beef calves', 'Thomas AD, Pajor EA, Caddey B, Goldhawk C, Martins L, Orsel K', 2022, 'BMC veterinary research', '10.1186/s12917-022-03345-x', 'https://doi.org/10.1186/s12917-022-03345-x', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9219410.1/PMC9219410.1.pdf', NULL, NULL, 11, NULL, 'alberta', 4, 'cc by', 'BackgroundDigital dermatitis (DD) is a multifactorial infectious disease affecting the skin on feet of cattle causing erosion and inflammation above the heel bulbs. Some cases of DD cause lameness and significantly impact animal welfare and productivity. While DD has emerged as a concern for the beef industry, key information regarding early detection and its impact on cattle behaviour is lacking. The primary objective of this study was to determine if an established DD experimental model for dairy calves could be used to induce DD lesions in beef calves. A secondary objective was to describe changes in behaviour and pain associated with induction of DD lesions. Eight beef calves acquired from a single cow-calf operator were enrolled in the study. Upon enrolment, calves were evaluated and determined to be free of foot lesions. Within the experimental environment, calves were housed in individual pens and assigned to two groups (mock-inoculated and inoculated). Both hind feet of each calf were enrolled. Within calf, inoculation protocol was consistent, and a 28-day experimental protocol was employed. Two days prior to inoculation, both hind feet of each calf were abraded (area above the heel bulbs and below the dewclaws), moistened, and wrapped to facilitate an anaerobic condition. Feet were inoculated with macerated DD lesion material or mock inoculum and remained wrapped until clinical signs of DD or protocol endpoint.ResultsAfter a period of 14 to 18 days post inoculation, three of five inoculated calves developed clinical signs (lameness), and upon close inspection, DD lesions were present on at least one hind foot. Two of five inoculated calves did not develop lesions within 28 days. Zero of three mock-inoculated calves developed DD. Treponema spp. were detected by quantitative polymerase chain reaction from biopsies of induced lesions. Measurements of behaviour prior to disease induction were numerically different between DD affected and mock-inoculated calves.ConclusionsAn experimental infection model established for dairy cattle was used to successfully induce acute DD lesions in three of five inoculated beef calves. This model can provide a framework to study intervention protocols and to evaluate the impact of DD on behaviour and pain.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2e8a5baa-64f5-4e74-8377-91d3dd49d4a6', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Assessment of microbiome changes after rumen transfaunation: implications on improving feed efficiency in beef cattle', 'Mi Zhou, Yongjia Peng, Yanhong Chen, Christen M. Klinger, M. Oba, Jianxin Liu, Le Luo Guan', 2018, 'Microbiome', '10.1186/s40168-018-0447-y', 'https://doi.org/10.1186/s40168-018-0447-y', 'https://microbiomejournal.biomedcentral.com/track/pdf/10.1186/s40168-018-0447-y', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'BACKGROUND: Understanding the host impact on its symbiotic microbiota is important in redirecting the rumen microbiota and thus improving animal performance. The current study aimed to understand how rumen microbiota were altered and re-established after being emptied and receiving content from donor, thus to understand the impact of such process on rumen microbial fermentation and to explore the microbial phylotypes with higher manipulation potentials. RESULTS: Individual animal had strong effect on the re-establishment of the bacterial community according to the observed profiles detected by both fingerprinting and pyrosequencing. Most of the bacterial profile recovery patterns and extents at genus level varied among steers; and each identified bacterial genus responded to transfaunation differently within each host. Coriobacteriaceae, Coprococcus, and Lactobacillus were found to be the most responsive and tunable genera by exchanging rumen content. Besides, the association of 18 bacterial phylotypes with host fermentation parameters suggest that these phylotypes should also be considered as the regulating targets in improving host feed efficiency. In addition, the archaeal community had different re-establishment patterns for each host as determined by fingerprint profiling: it was altered after receiving non-native microbiome in some animals, while it resumed its original status after the adaptation period in the other ones. CONCLUSIONS: The highly individualized microbial re-establishment process suggested the importance of considering host genetics, microbial functional genomics, and host fermentation/performance assessment when developing effective and selective microbial manipulation methods for improving animal feed efficiency.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f93d4df3-b4f8-4740-9d16-f045f662ccd8', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Automatic livestock waterers', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4332080', 'https://open.alberta.ca/dataset/4eb74666-8d0d-4512-bcba-806df32ba4f1/resource/712d2c5c-ec53-430e-86fb-682da51b81d7/download/2008-716c52.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A reliable, constant supply of good quality water is an essential part of any livestock enterprise. Automatic waterers are standard equipment on most farms because of their convenience and efficiency. They consist of an insulated base and a heated bowl that automatically fills with water from a pressurized line. A float-operated valve controls the level of the water in the bowl. A thermostat, set at 4 to 6° C, regulates the water temperature in the bowl.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e6653430-9d98-454f-a549-92c32bb4de1b', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Betting the Farm: Food Safety, Risk Society, and the Canadian Cattle and Beef Commodity Chain', 'Ian R. MacLachlan', 2004, 'Open ULeth Scholarship (OPUS) (University of Lethbridge)', NULL, 'http://hdl.handle.net/10133/335', 'http://hdl.handle.net/10133/335', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4559be6-7887-46a1-a518-3870d615cf11', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Comparison of short nasal swab and deep nasopharyngeal swab sampling methods to describe BRD-associated viruses and bacteria detected using a metagenomics approach optimized for virus recovery in fall-placed beef calves shortly after feedlot arrival', 'Donbraye E, McLeod L, Chai Z, Lacoste SR, McCarthy EL, Links MG, Waldner CL', 2026, 'Veterinary and animal science', '10.1016/j.vas.2026.100609', 'https://doi.org/10.1016/j.vas.2026.100609', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12993145.1/PMC12993145.1.pdf', NULL, NULL, 11, NULL, 'prairies', 4, 'cc by-nc', 'Short nasal swabs (SNS) have potential advantages of lower costs, collection time and training of personnel than deep nasopharyngeal swabs (DNPS) for detecting bovine respiratory disease (BRD) pathogens. This study examined differences between DNPS and SNS in BRD-associated pathogens detected using a nanopore metagenomic sequencing protocol, optimized for respiratory RNA viruses, collected from 150 calves in six feedlot pens. Short nasal swabs yielded higher viral read counts and prevalence than DNPS for BCoV (mean reads 75 versus 17; OR = 21.4, P = 0.001) and IDV (mean reads: 560 versus 192; OR = 2.60, P = 0.02). Agreement varied among viruses: IDV (κ=0.57), BRSV (κ=0.43), and BCoV at both ≥1 read (κ=0.35) and ≥30 reads (κ=0.10). No BoHV-1 and BAdV3 were detected. Mannheimia haemolytica was detected (≥14 reads) more frequently in SNS than DNPS (mean reads: 169 versus 57; OR = 5.73, P = 0.001), as was Pasteurella multocida (≥ 1 read) (mean reads: 4.0 versus 1.2; OR = 2.02, P = 0.02). Mesomycoplasma dispar was less prevalent in SNS (mean reads: 5.2 versus 29; OR = 0.27, P = 0.001). Detection of Histophilus somni, Bibersteinia trehalosi, and Mycoplasmopsis bovis did not differ between swab types. Agreement for detection of M. haemolytica (≥14 reads) was moderate (κ = 0.46, P = 0.001). For all other bacteria examined in this analysis, kappa values were very low. Short nasal swabs were a sensitive and practical alternative for BRD pathogen surveillance providing evidence of which viruses and bacteria are circulating, potentially informing vaccination and disease management.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ad250a7-bffc-456d-9e6f-515d4095c325', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Cyanobacterial toxins in Canadian freshwaters: A review', 'Brian G. Kotak, Ron W. Zurawell', 2007, 'Lake and Reservoir Management', '10.1080/07438140709353915', 'https://doi.org/10.1080/07438140709353915', 'https://www.tandfonline.com/doi/pdf/10.1080/07438140709353915?needAccess=true&role=button', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('187bf4d2-72ce-45e2-9bfc-f04869d407cc', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'DEVELOPMENTS IN LAKE RESTORATION IN WESTERN CANADA', 'Tom Murphy, P. Manning, Ellie E. Prepas, J. Babin, K. Hall', 1993, 'Canadian Water Resources Journal / Revue canadienne des ressources hydriques', '10.4296/cwrj1803299', 'https://doi.org/10.4296/cwrj1803299', 'https://www.tandfonline.com/doi/pdf/10.4296/cwrj1803299?needAccess=true', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18586071-3b97-4f03-98ea-034f4e0636c9', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Diagnostic sensitivity and specificity of metagenomic sequencing and qPCR for detection of viruses associated with bovine respiratory disease estimated using Bayesian latent class models', 'Donbraye E, McLeod L, Chai Z, Lacoste SR, McCarthy EL, Hill JE, Erickson NEN, Links MG', 2026, 'Frontiers in veterinary science', '10.3389/fvets.2026.1704414', 'https://doi.org/10.3389/fvets.2026.1704414', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12976743.1/PMC12976743.1.pdf', NULL, NULL, 19, NULL, 'prairies', 4, 'cc by', 'IntroductionVery few studies have examined the diagnostic sensitivity and specificity of currently available laboratory tests for detecting respiratory pathogens in cattle, and even fewer have examined test performance on samples from animals before the onset of clinical disease.MethodsIn this study, Bayesian latent class modeling (BLCM) was used to assess diagnostic test performance in the absence of a gold standard on nasal swabs collected from 19 western Canadian feedlots. Viruses associated with bovine respiratory disease (BRD) were identified using qPCR from a commercial diagnostic laboratory from 760 nasal swabs collected from fall-placed calves (FPC) and yearlings (YRL) at and shortly after feedlot arrival. Using BLCM, the qPCR results were compared to previously reported matching nanopore metagenomic sequencing data for these same samples. Based on BLCM, test sensitivities and specificities were estimated for the detection of bovine coronavirus (BCoV), bovine herpesvirus type 1 (BoHV-1), bovine parainfluenza virus type 3 (BPIV-3), bovine respiratory syncytial virus (BRSV), and influenza D virus (IDV). Estimates informed by BLCM were not available for the detection of bovine viral diarrheal virus (BVDV) because qPCR did not detect this virus in any samples.ResultsDiagnostic sensitivity of qPCR was higher than metagenomic sequencing for detecting BCoV (qPCR 0.90, 95% CrI 0.81-0.99; sequencing 0.35, 95% CrI 0.25-0.46) and BoHV-1 (qPCR 0.39, 95% CrI 0.19-0.99; sequencing 0.04, 95% CrI 0.01-0.15). However, the estimated diagnostic sensitivity of metagenomic sequencing was higher than qPCR for identifying BRSV (qPCR 0.32, 95% CrI 0.22-0.43; sequencing 0.60, 95% CrI 0.44-0.77). No significant difference among sensitivities was noted for the detection of BPIV-3 (qPCR 0.42, 95% CrI 0.21-0.66; sequencing 0.52, 95% CrI 0.19-0.87) and IDV (qPCR 0.65, 95% CrI 0.53-0.79; sequencing 0.60, 95% CrI 0.48-0.73). Diagnostic specificity was comparable for most viruses, except for BCoV, where metagenomic sequencing (BCoV 0.91, 95% CrI 0.88-0.95) outperformed qPCR (BCoV 0.59, 95% CrI 0.51-0.68). The specificity and sensitivity for detection of BRD-associated bacteria from the same metagenomic data were also similar to those estimated for culture and qPCR results for the same samples.DiscussionEstimated test sensitivities of both nanopore metagenomic sequencing and qPCR for the detection of BRD viruses of interest in nasal swab samples were moderate to very low for most viruses. While the tests varied in their ability to detect individual viruses, data from this study suggest nanopore metagenomic sequencing offers a potential alternative for diagnostic laboratories to identify three of six important BRD viruses as well as bacteria associated with BRD.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60981d09-32a8-48ce-9a95-c1969c749636', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Effect of undigestible neutral detergent fiber concentration in finishing diets containing dry-rolled or steam-rolled barley for feedlot steers', 'Terry SA, Yang W, Beauchemin KA, Schwartzkopf-Genswein KS, Penner GB, Wood KM, McAllister TA', 2025, 'Journal of animal science', '10.1093/jas/skae392', 'https://doi.org/10.1093/jas/skae392', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12080542.1/PMC12080542.1.pdf', NULL, NULL, 13, NULL, 'southern_alberta', 4, 'cc by', 'This study evaluated the impact of grain processing method (dry- vs. steam-rolling) and diet uNDF concentration (low vs. high; 5.7% vs. 6.6% on DM basis by replacing silage with straw) in finishing diets on feed intake, feeding behavior, growth performance, ruminal pH, fermentation parameters, inflammatory stress responses, and carcass traits of 376 intact (initial body weight (BW) ± SD, 440 ± 33.6 kg), and 24 ruminally cannulated steers (initial BW ± SD, 474 ± 30.5 kg). Steers were housed in 32 pens with 4 pens of 30 steers, and 28 pens of 10 steers. Eight of the pens with 10 steers, and all of the pens with 30 steers were equipped with GrowSafe to record individual feed intake and feeding behavior. Three cannulated and 7 intact steers were housed in the smaller GrowSafe pens. Diets included (1) dry-rolled barley and barley silage; (2) dry-rolled barley and barley straw; (3) steam-rolled barley and barley silage; and (4) steam-rolled barley and barley straw, formulated to contain 89% barley-grain, 6% roughage and 5% vitamin and mineral supplement (DM basis). Interactions between the processing method and uNDF concentration were observed for maximum ruminal pH, and concentrations of blood glucose and lipopolysaccharide-binding proteins. Compared to dry-rolling, steam-rolling did not improve growth performance, ruminal pH, fermentation parameters, or liver abscess scores, but did increase longissimus muscle (LM) area (P = 0.01) and decrease the proportion of AAA carcasses (P = 0.01). Steam-rolled barley decreased (P = 0.04) glucose and increased (P = 0.01) blood concentrations of insulin and acute phase proteins. Increasing uNDF did not affect feed intake, growth, carcass traits, or liver abscess scores, but did increase (P = 0.01) bunk attendance, meal duration, and to a lesser extent meal intervals (P = 0.04) and eating rate (P = 0.01). Increased uNDF raised (P = 0.04) mean ruminal pH and reduced the duration of pH below 6.0, 5.8, and 5.2, and tended (P = 0.06) to increase the acetate to propionate ratio. The lack of growth response to dietary uNDF concentration could be due to the small differences in uNDF intake, or that uNDF concentration was sufficient to prevent digestive disturbances. Increasing dietary uNDF altered eating behavior and ruminal pH in a manner that could reduce the risk of clinical and subclinical ruminal acidosis.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc8d4105-05ae-4210-b1b9-f4a4344a1b3a', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Effects of administering local anesthesia immediately before surgical castration on indicators of pain and discomfort of beef calves', 'Bernier AF, Erickson N, Campbell J, Moya D', 2025, 'Translational animal science', '10.1093/tas/txaf010', 'https://doi.org/10.1093/tas/txaf010', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11826336.1/PMC11826336.1.pdf', NULL, NULL, 9, NULL, 'alberta', 4, 'cc by-nc', 'Forty Hereford cross calves (mean and SD of 47.9 ± 10.43 d old) were used to assess the efficacy of lidocaine administered immediately before surgical castration on physiological and behavioral indicators of pain and discomfort. Calves were assigned by age to one of two treatments: surgical castration following subcutaneous injection of 2.5 mL/100 kg body weight of meloxicam (Metacam 20 mg/mL, Boehringer Ingelhein, Burlington, ON, Canada) per kg body weight (MEX, n = 19); or the same treatment preceded 90 s before by a nerve block of the spermatic cord using 8 mL of buffered (1 mL:10 mL of 8.4% sodium bicarbonate USP, Hospira Inc., Lake Forest, IL, USA) lidocaine (4 mL per cord; 20 mg/mL, LIDO-2 with epinephrine, Rafter Products, Calgary, AB, Canada) (LID, n = 21). During the castration procedure, two observers scored how much pain each animal was experiencing (visual analog score, VAS), number of body shakes and leg kicks for each calf. Blood samples and exit scores were collected the day of castration and on d 7, and 14 to assess the neutrophil-to-lymphocyte ratio (N:L) and calf temperament, respectively. Hair samples were collected the day of castration and on d 14 to determine cortisol levels. Scrotal circumference, swelling, and healing scores were determined on d 7 and 14 to assess healing. An accelerometer (HOBO Pendant® G Data Logger, Onset, Cape Cod, MA) was placed on the left hind leg to measure lying behavior until d 6 after castration. Calves were video recorded for 1 hour after the castration procedure to observe behaviors indicative of pain and discomfort. Surveillance cameras were also used to assess the mobility of the calves when cow-calf pairs were moved from the holding pen to the pasture. The VAS, number of tail flicks and foot stamps were greater (P P = 0.03) and less time standing (P = 0.01) than MEX calves. When moved from the holding pen, LID calves moved faster (P P P < 0.05) in LID than MEX calves on d 14. Results suggest that using lidocaine for local anesthesia immediately before surgical castration reduced behaviors indicative of pain and improved mobility post-castration.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9f2961b-5c88-4042-aaa7-0b26d63977ae', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Metagenomic characterization of the effect of feed additives on the gut microbiome and antibiotic resistome of feedlot cattle', 'Milton Thomas, M. J. Webb, Sudeep Ghimire, Amanda D. Blair, K. C. Olson, Gavin John Fenske, Alex Thomas Fonder, Jane Christopher‐Hennings', 2017, 'Scientific Reports', '10.1038/s41598-017-12481-6', 'https://doi.org/10.1038/s41598-017-12481-6', 'https://www.nature.com/articles/s41598-017-12481-6.pdf', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc-by', 'In North America, antibiotic feed additives such as monensin and tylosin are added to the finishing diets of feedlot cattle to counter the ill-effects of feeding diets with rapidly digestible carbohydrates. While these feed additives have been proven to improve feed efficiency and reduce liver abscess incidence, how these products impact the gastrointestinal microbiota is not completely understood. In this study, we analyzed the impact of providing antibiotic feed additives to feedlot cattle using metagenome sequencing of treated and control animals. Our results indicate that use of antibiotic feed additives does not produce discernable changes at the phylum level. However, treated cattle had reduced abundance of gram-positive bacteria at the genus level. The abundance of Ruminococcus, Erysipelotrichaceae and Lachnospiraceae in the gut of treated steers was reduced. Functional analysis of the data indicates that there was only minimal impact due to the treatment in the rumen. Genes involved in detoxification were significantly increased in the rumen of AB steers. But the relative abundance of these genes was < 0.3%. However, our results did not show any correlation between the presence of antimicrobial resistance genes in the gut microbiota and the administration of antibiotic feed additives.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('faeca567-ebd3-4a23-b3ce-588ebf9e41c1', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Effects of flavoring additives on feed intake, growth performance, temperament, and markers of immune function for newly received feedlot cattle', 'Ahmad M, Seddon YM, Blanch M, Penner GB, Moya D', 2024, 'Journal of animal science', '10.1093/jas/skae139', 'https://doi.org/10.1093/jas/skae139', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11161901.1/PMC11161901.1.pdf', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by-nc', 'Ninety Angus × Hereford steers (259.9 ± 36.18 kg body weight [BW]) were used in a 56-d experiment to assess the effects of flavoring additives on feed intake, and stress and immune response of newly received feedlot cattle. Steers were homogenously distributed by BW into six pens equipped with an individual feed intake monitoring system, and pen was randomly assigned to one of three treatments (15 heads per pen; 30 heads per treatment): a standard feedlot receiving diet (CT), or the same diet with a flavoring additive comprised of either sweeteners (Luctarom Feedlot, SW) or a mix of basic tastes (Luctarom Feedlot Mix, MX) at 1 kg/mT. Pens were equipped with a feed intake monitoring system, while BW, chute behavior, flight speed, blood and saliva samples were collected bi-weekly, and hair samples were collected at 4-wk intervals during the study. Data were analyzed using a mixed-effects model for a pen study using individual animal records with repeated measures. There was a treatment × week interaction (P < 0.01) where meal duration was greater in SW steers than MX and CT on week 3, and then CT on weeks 7 and 8. A trend for treatment × week interaction (P = 0.06) showed that the number of visits per day tended to be greater in SW than MX steers on weeks 4 and 5, and it tended to be greater in SW than MX and CT on week 5. The concentration of IL-6 was greater (P < 0.01) on days 1 and 28 than on day 14. The IgM concentration was greater (P < 0.01) on day 1 compared to days 14, 28, and 56. The concentration of haptoglobin was greater (P < 0.01) on 14 than days 28, 42, and 56, and it was greater (P < 0.01) on day 1 than days 42 and 56. The concentration of serum amyloid A was greater (P < 0.01) on day 1 compared to the rest of sampling days. Fibrinogen concentration was greater (P < 0.01) on day 1 compared to days 14 and 42. The neutrophil-to-lymphocyte ratio was greater (P < 0.01) on days 42 and 56 compared to days 1 and 28, and greater (P < 0.01) on day 14 compared to day 28. Hair and saliva cortisol concentrations were lower (P < 0.01) on day 56 compared to days 1 and 28, respectively. The use of flavoring additives, particularly when based on sweeteners (SW), caused some changes in the feeding pattern of newly received steers. These changes, however, were not consistent over the 56-d feeding period and were not accompanied by a change in growth performance, temperament, biomarkers of stress, inflammation, or immune function.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d1d7bcf4-6e16-470b-9efd-b650881e1c0b', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Effects of Heating, Pelleting, and Feed Matrix on Apparent Concentrations of Cereal Ergot Alkaloids in Relation to Growth Performance and Welfare Parameters of Backgrounding Beef Steers', 'Stanford K, Schwartzkopf-Genswein KS, Meléndez DM, Ngo S, Harding M, McAllister TA, Schatzmayr D, Swift ML', 2022, 'Toxins', '10.3390/toxins14090580', 'https://doi.org/10.3390/toxins14090580', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9500729.1/PMC9500729.1.pdf', NULL, NULL, 14, NULL, 'southern_alberta', 5, 'cc by', 'As the contamination of cereal grains with ergot has been increasing in Western Canada, studies were undertaken to evaluate the impacts of heating (60, 80, 120, or 190 °C) alone or in combination with pelleting on concentrations of ergot alkaloids. Fifteen samples of ergot-contaminated grain from Alberta and Saskatchewan were assayed for R and S epimers of six alkaloids (ergocryptine, ergocristine, ergocornine, ergometrine, ergosine, and ergotamine) using HPLC MS/MS. Five samples with distinct alkaloid profiles were then selected for heating and pelleting studies. Heating resulted in a linear increase (p < 0.05) of total R and total S epimers with increasing temperature, although some individual R epimers were stable (ergometrine, ergosine, ergotamine). Pelleting also increased (p < 0.05) concentrations of total R and total S epimers detected, although ergometrine concentration decreased (p < 0.05) after pelleting. A feeding study arranged in a 2 × 2 factorial structure used 48 backgrounding Angus-cross steers fed four different diets: (1) Control Mash (CM, no added ergot), (2) Control Pellet (CP), (3) Ergot Mash (EM), or (4) Ergot Pellet (EP). Pelleting heated the ergot to 90−100 °C under 4 bars pressure, but the ergot used in the feeding study was not otherwise heated. Alkaloid concentrations of EM and EP varied by up to 1.1 mg/kg depending on the feed matrix assayed. No differences among treatments were noted for growth performance, feed intake, feed conversion, concentrations of serum prolactin and haptoglobin, hair cortisol, or in temperatures of extremities measured by infrared thermography. The only negative impacts of ergot alkaloids were on blood parameters indicative of reduced immune function or chronic inflammation. Pelleting did not heighten the negative clinical outcomes of ergot, although alkaloid concentrations of pelleted feed increased depending on the matrix assayed. It was hypothesized that the heat and pressure associated with pelleting may enhance the recovery of alkaloids from pelleted feed.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5d4a99a3-7a2e-4db0-8331-6b319e00e74b', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Effects of water quality on cattle performance', 'Walter D. Willms, Orin R. Kenzie, Tim Angus McAllister, Society for Range Management', 2002, 'Journal of Range Management', '10.2458/azu_jrm_v55i5_willms', 'https://doi.org/10.2458/azu_jrm_v55i5_willms', 'https://repository.arizona.edu/bitstream/10150/643683/1/9741-9622-1-PB.pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('af84d8ab-87a7-450b-9027-76901577eeff', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Estimating water consumption and factors affecting intake in grazing cattle', 'Shaukat Ali, L. A. Goonewardene, J. A. Basarab', 1994, 'Canadian Journal of Animal Science', '10.4141/cjas94-077', 'https://doi.org/10.4141/cjas94-077', 'https://www.nrcresearchpress.com/doi/pdf/10.4141/cjas94-077', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8e747da-28b2-4675-b1c2-150f2c68e25b', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Evaluation of the red seaweed Mazzaella japonica as a feed additive for beef cattle', 'Stephanie A. Terry, Trevor Coates, Robert J. Gruninger, D. Wade Abbott, Karen Ann Beauchemin', 2023, 'Frontiers in Animal Science', '10.3389/fanim.2023.1181768', 'https://doi.org/10.3389/fanim.2023.1181768', 'https://www.frontiersin.org/articles/10.3389/fanim.2023.1181768/pdf', NULL, NULL, 10, NULL, 'southern_alberta', 5, 'cc-by', 'Supplementing ruminant diets with macroalgae is gaining interest globally because bromoform-containing seaweeds (e.g., Asparagopsis spp.) have been shown to be highly effective enteric methane (CH4) inhibitors. Some alternative seaweeds decrease in vitro CH4 production, but few have been evaluated in animals. This study examined the effects of including the red seaweed Mazzaella japonica in the diet of beef cattle on dry matter intake (DMI), rumen fermentation, digestibility, nitrogen (N) utilization, and enteric CH4 production. Six ruminally cannulated, mature beef heifers (824 ± 47.1 kg) were used in a double 3 × 3 Latin square with 35-d periods. The basal diet consisted of 52% barley silage, 44% barley straw, and 4% vitamin and mineral supplement [dry matter (DM) basis]. The treatments were (DM basis): 0% (control), 1%, and 2% M. japonica. The DMI increased quadratically (P = 0.025) with the inclusion of M. japonica, such that the DMI of heifers consuming 1% was greater (P < 0.05) than that of control heifers. The apparent total-tract digestibility of DM decreased linearly (P = 0.002) with the inclusion of M. japonica, but there were no treatment differences in the digestibility of organic matter, crude protein (CP), neutral detergent fiber, or starch. The level of M. japonica linearly (P < 0.001) increased the N intake of the heifers. Fecal N excretion linearly increased (P = 0.020) with M. japonica, but there were no differences in total urinary N excretion, N fractions (allantoin, uric acid), total purine derivatives, microbial purine derivatives absorbed, microbial N flow, or retained N. There were no treatment effects on rumen pH or total volatile fatty acids (VFAs); however, adding M. japonica to the diet quadratically (P = 0.023) decreased the proportion of acetate, whereas 1% inclusion decreased the acetate proportion. Methane production (g/day) decreased quadratically (P = 0.037), such that the heifers receiving 2% M. japonica produced 9.2% less CH4 than control animals; however, CH4 yield (g/kg DMI) did not differ among treatments. We conclude that supplementing a forage-based diet with up to 2% M. japonica failed to lower the enteric CH4 yield of beef heifers. M. japonica can be used in diets to help meet the CP requirements of cattle, but inclusion rates may be limited by high inorganic matter proportions. When comprising up to 2% of the diet, M. japonica cannot be recommended as a CH4 inhibitor for beef cattle fed on high-forage diets.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4f43381b-fa3b-4b0d-ac25-35626f9ca929', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Examining the water quantity and quality effects of land management practices in a Canadian Prairie Subwatershed using a GIS-Based distributed model', 'Ivana Lung', 2014, 'The Atrium (University of Guelph)', NULL, 'http://hdl.handle.net/10214/8430', 'http://hdl.handle.net/10214/8430', NULL, NULL, 230, NULL, 'prairies', 4, 'cc-by-nc-nd', 'Beneficial management practices (BMPs) were evaluated using the Integrated Modelling for Watershed Evaluation of BMPs (imWEBs) model in southern Manitoba. The hourly model was setup, calibrated (2005-06) and validated (2007-09) for the Steppler subwatershed using nine stream discharge and water quality monitoring station. After calibrating the model, three scenarios were evaluated: forage conversion, conventional tillage and small dams. A daily R2 and E outlet calibration of 0.269 and 0.155, respectively, and outlet validation of 0.108 and 0.077, respectively, was achieved. Sediment load results had a daily RMSE, CV and CORR outlet calibration of 0.607, 0.441 and 0.438, respectively, and validation of 0.392, 1.112 and -0.374, respectively. The evaluation of the three scenarios indicated beneficial reductions. However, the expected benefits were not as high; thus, suggesting a need to revisit the parameterization for the tillage management and the small dam reservoirs to achieve the correct magnitude reductions from BMP applications.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5fc13ae3-bd48-48b5-9f34-8fc543c7029c', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Forage Selection by Cattle on Fescue Prairie in Summer or Winter', 'Walter D. Willms, Lyle M. Rode', 1998, 'Journal of Range Management', '10.2307/4003364', 'https://doi.org/10.2307/4003364', 'https://repository.arizona.edu/bitstream/10150/643946/1/9345-9226-1-PB.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('231a6f4a-b4ca-4f89-96ab-08f40e4ff426', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Genomic Characterization of Enterococcus casseliflavus Isolated from Beef Cows and Calves', 'Zaidi SE, Zaheer R, Zovoilis A, Fossen J, Van Domselaar G, Waldner C, McAllister TA', 2025, 'Microorganisms', '10.3390/microorganisms13040907', 'https://doi.org/10.3390/microorganisms13040907', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12029791.1/PMC12029791.1.pdf', NULL, NULL, 14, NULL, 'prairies', 4, 'cc by', 'Enterococcus species are used as One Health indicators of antimicrobial resistance (AMR) in humans, animals, and the environment. A surveillance study in beef cows and calves isolated Enterococcus casseliflavus along with E. faecium, E. faecalis, and E. hirae. Given the high prevalence of E. casseliflavus, we elected to characterize this species to better understand its role in the antimicrobial resistance of enterococci in cows and calves. Almost 12% of E. casseliflavus isolates exhibited multidrug resistance with the majority being resistant to lincomycin (99%), followed by quinupristin-dalfopristin (34%), ciprofloxacin (9.6%), tylosin (4.5%), erythromycin (2.7%), tetracycline (1.8%), tigecycline (1.5%), daptomycin (0.6%), streptomycin (0.3%), and kanamycin (0.3%). All E. casseliflavus were susceptible to chloramphenicol, penicillin, streptomycin, nitrofurantoin, gentamicin, and linezolid. Whole genome antimicrobial resistance gene profiling identified vanC-type intrinsic vancomycin resistance genes in all E. casseliflavus, with the vanC4XYT gene cluster being dominant (67%) followed by vanC2XYT (31%) and vanC3XYT (1.5%). Resistance genes for erythromycin (ermB) and tetracycline (tetM) were rarely identified (2.1% and 1.2%, respectively) within E. casseliflavus genomes. No resistance genes were identified to explain either the quinupristin-dalfopristin or ciprofloxacin resistance in these isolates. A core genome phylogenetic tree revealed two clades that exhibited no distinct association with the age of the host, time of sample collection, or the farm sampled. The open nature of the E. casseliflavus pan-genome highlighted its intraspecies diversity. These findings suggest that E. casseliflavus is likely a low-risk species in terms of contributing to antimicrobial resistance in the cow-calf sector.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8cff902c-5482-4e31-85a0-791955a81327', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Guidance for baseline water well testing for coalbed methane operations', 'Government of Alberta', 2026, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/guidance-baseline-water-well-testing-coalbed-methane-operations', 'https://open.alberta.ca/dataset/5251c424-5c3d-4af1-8380-147d6c87ece7/resource/66e21dec-a647-4c31-a1a4-57d5ddb3da46/download/epa-guidance-baseline-water-well-testing-coalbed-methane-operations-2026.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This guidances provides advice, recommendations, and best management practices for conducting baseline water well testing on active water wells and observation wells located near coalbed methane development.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('183fc44a-b518-47ea-9567-97c72f7c8cb7', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'High deoxynivalenol and ergot alkaloid levels in wheat grain: effects on growth performance, carcass traits, rumen fermentation, and blood parameters of feedlot cattle', 'Bierworth RM, Ribeiro GO, Terry SA, Malmuthuge N, Penner GB, McKinnon JJ, Hucl P, Randhawa H', 2024, 'Mycotoxin research', '10.1007/s12550-024-00534-5', 'https://doi.org/10.1007/s12550-024-00534-5', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11258187.1/PMC11258187.1.pdf', NULL, NULL, 17, NULL, 'prairies', 4, 'cc by', 'This study was designed to assess the impacts of a mixture of deoxynivalenol (DON) and ergot alkaloids (EAs) on growth performance, rumen function, blood parameters, and carcass traits of feedlot cattle. Forty steers (450 ± 6.0 kg) were stratified by weight and randomly allocated to 1 of 4 treatments; control-low (CON-L), control-high (CON-H) which contained low or high wheat screenings that lacked mycotoxins at the same level as the mycotoxin-low (MYC-L; 5.0 mg/kg DON, 2.1 mg/kg EA), and mycotoxin-high (MYC-H: 10 mg/kg DON, 4.2 mg/kg EA) diets that included wheat screening with mycotoxins. Steers were housed in individual pens for a 112-day finishing trial. Intake was 24.8% lower (P < 0.001) for MYC steers compared to CON steers. As a result, average daily gains of MYC steers were 42.1% lower (P < 0.001) than CON steers. Gain to feed ratio was also lower (P < 0.001) for MYC steers compared to CON steers. Platelets, alanine aminotransferase, globulins, and blood urea nitrogen were lower (P ≤ 0.008), and lymphocytes, glutathione peroxidase activity (GPx), and interleukin-10 (IL-10) were elevated (P ≤ 0.002) in MYC steers compared to CON steers. Hot carcass weights and backfat thickness were reduced (P < 0.001) in MYC steers, resulting in leaner (P < 0.001) carcasses and higher (P < 0.007) meat yield compared to CON steers. Results suggest that a mixture of DON and EAs negatively impacted health, performance, and carcass traits of feedlot steers, with the majority of this response likely attributable to EAs. However, more research is needed to distinguish the relative contribution of each mycotoxin to the specific responses observed.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('26ae68e9-93af-4f8e-a56c-ba5e46e13d3b', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Impacts of Maternal Bovine Appeasing Substance Administered at Weaning on Behavioral and Physiological Adaptation of Beef Heifers to the Feedlot', 'Gellatly D, Lei Y, Neale A, Smith L, Edgar E, Bloomfield B, Elliot B, Wenger I', 2025, 'Animals : an open access journal from MDPI', '10.3390/ani15192788', 'https://doi.org/10.3390/ani15192788', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12523323.1/PMC12523323.1.pdf', NULL, NULL, 22, NULL, 'alberta', 4, 'cc by', 'The effects of administering 10 mL of maternal bovine appeasing substance (mBAS) or water (control; CT) at weaning (day 0) before transport on feedlot adaptation and efficiency were evaluated in twenty-two Angus-influenced heifers (n = 11/treatment) over 28 days. Body weight (BW), salivary cortisol, blood for complete blood cell count, rectal temperature, chute score and exit speed were collected on days 0, 14 and 27. Intake, feeding duration, frequency and rate, as well as activity and rumination were monitored daily using automated systems. Average daily gain (ADG) and gain-to-feed ratio (G:F) were calculated for each 14-day interval as well as for the entire feeding period. Treated heifers spent less time eating (p ≤ 0.06) on weeks 1 and 2, with greater feeding rate and activity (p p ≤ 0.05) in weeks 2, 3 and 4. Rumination was longer (p p ≤ 0.05) final BW, ADG0-27, ADG14-27, and G:F0-27, G:F14-27. Lymphocyte and hematocrit were lower (p p = 0.08) than CT for the entire period. Treated heifers achieved numerically greater profit margins than CT. Overall, mBAS enhanced feedlot adaptability post-weaning, improving production efficiency, which may translate into potential profitability; however, this interpretation should be viewed cautiously considering some design limitations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f17906d6-3d6d-4cf5-a7bf-40ec289750ad', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Impacts of shade on cattle well-being in the beef supply chain', 'Lily Edwards-Callaway, Catie Cramer, Caitlin N Cadaret, Elizabeth J Bigler, T. E. Engle, John J. Wagner, Daniel L Clark', 2020, 'Journal of Animal Science', '10.1093/jas/skaa375', 'https://doi.org/10.1093/jas/skaa375', 'https://academic.oup.com/jas/article-pdf/99/2/skaa375/36409254/skaa375.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Shade is a mechanism to reduce heat load providing cattle with an environment supportive of their welfare needs. Although heat stress has been extensively reviewed, researched, and addressed in dairy production systems, it has not been investigated in the same manner in the beef cattle supply chain. Like all animals, beef cattle are susceptible to heat stress if they are unable to dissipate heat during times of elevated ambient temperatures. There are many factors that impact heat stress susceptibility in beef cattle throughout the different supply chain sectors, many of which relate to the production system, that is, availability of shade, microclimate of environment, and nutrition management. The results from studies evaluating the effects of shade on production and welfare are difficult to compare due to variation in structural design, construction materials used, height, shape, and area of shade provided. Additionally, depending on operation location, shade may or may not be beneficial during all times of the year, which can influence the decision to make shade a permanent part of management systems. Shade has been shown to lessen the physiologic response of cattle to heat stress. Shaded cattle exhibit lower respiration rates, body temperatures, and panting scores compared with unshaded cattle in weather that increases the risk of heat stress. Results from studies investigating the provision of shade indicate that cattle seek shade in hot weather. The impact of shade on behavioral patterns is inconsistent in the current body of research, with some studies indicating that shade provision impacts behavior and other studies reporting no difference between shaded and unshaded groups. Analysis of performance and carcass characteristics across feedlot studies demonstrated that shaded cattle had increased ADG, improved feed efficiency, HCW, and dressing percentage when compared with cattle without shade. Despite the documented benefits of shade, current industry statistics, although severely limited in scope, indicate low shade implementation rates in feedlots and data in other supply chain sectors do not exist. Industry guidelines and third-party on-farm certification programs articulate the critical need for protection from extreme weather but are not consistent in providing specific recommendations and requirements. Future efforts should include: updated economic analyses of cost vs. benefit of shade implementation, exploration of producer perspectives and needs relative to shade, consideration of shade impacts in the cow-calf and slaughter plant segments of the supply chain, and integration of indicators of affective (mental) state and preference in research studies to enhance the holistic assessment of cattle welfare.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc1f7e78-76f4-4df6-8f6c-38beac4b3dd6', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Methane and ammonia emissions from a beef feedlot in western Canada for a twelve-day period in the fall', 'Ronald P. van Haarlem, R. L. Desjardins, Zhiling Gao, Thomas K. Flesch, Xuanyi Li', 2008, 'Canadian Journal of Animal Science', '10.4141/cjas08034', 'https://doi.org/10.4141/cjas08034', 'https://cdnsciencepub.com/doi/pdf/10.4141/CJAS08034', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec21405e-561c-4495-9dd2-a7733d4e475a', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Industrial heartland designated industrial zone : surface water supply and distribution operational guidance', 'Government of Alberta', 2022, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/industrial-heartland-diz-surface-water-supply-and-distribution-operational-guidance', 'https://open.alberta.ca/dataset/178ff02b-ee9a-475e-92ef-3e20b11a0300/resource/a26c3ea2-be29-4850-9b7e-49c3bfcb38ef/download/aep-industrial-heartland-diz-surface-water-supply-and-distribution-operational-guidance.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document provides guidance for applicants of new water intake works on the North Saskatchewan River to support developments in the Industrial Heartland Designated Industrial Zone. Alberta Environment and Parks recognizes that access to water from the North Saskatchewan River for expanding industrial development in the Industrial Heartland Designated Industrial Zone is necessary to supply projected demand for water given the insufficient volumes that can be drawn from alternative sources.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('42eaf443-0b3e-4a0c-8680-922427a90ad0', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Invited Review: Water consumption, and drinking behavior of beef cattle, and effects of water quality', 'John J. Wagner, T. E. Engle', 2021, 'Applied Animal Science', '10.15232/aas.2021-02136', 'https://doi.org/10.15232/aas.2021-02136', 'https://www.sciencedirect.com/science/article/pii/S2590286521001075/pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'This review describes water intake, drinking behavior, and water quality for beef cattle during the cow-calf, stocker, and feedlot phases of beef production. Results from published scientific literature investigating water quality and factors effecting water intake and drinking behavior in cattle are summarized in this manuscript. The authors relied on their beef cattle research and production experiences to interpret the results of this literature search and reach the conclusions described within this review. Water intake predictions of Winchester and Morris (1956) are likely adequate for water budgeting purposes for groups of cattle, provided DMI is estimated accurately. Factors that potentially limit water intake, such as limited water availability and excessive total dissolved solids should be avoided. Cattle can tolerate, although frequently with reduced performance, total dissolved solids concentrations in water up to 7,000 mg/L provided the salts in question do not include significant nitrates or sulfates. Ruminal water turnover rate, rumen bypass, frequency of water consumption, and environmental factors that influence water consumption likely contribute to the variation in the concentrations of nitrate and sulfate required to induce a toxicity. Providing cattle ad libitum access to clean fresh drinking water is imperative to optimize animal health and production efficiency. Routine water analysis in conjunction with feed analysis is critical for appropriate water quality management. When water contaminants exceed maximum tolerable concentrations, blending water from various sources to reduce the effect of contaminants or reducing the dietary concentration of the contaminant (e.g., sulfur) may be beneficial.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3da7b514-8848-4567-aecc-19f9d0e57fb5', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'LAND USE INFLUENCES ON CYANOTOXIN ABUNDANCE IN SMALL SOUTH-CENTRAL SASKATCHEWAN WATER BODIES', 'Ashley Katerine James', 2012, 'HARVEST (University of Saskatchewan)', NULL, 'https://hdl.handle.net/10388/ETD-2012-07-545', 'https://harvest.usask.ca/bitstreams/59bbf08f-b67c-43fe-a11f-346aff2dda38/download', NULL, NULL, 117, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('efe5c512-cb96-4c0c-8d3e-14da49d6c778', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Landscape and land use impacts on farm pond water quality in the Portage Plains of south-central Manitoba.', 'Jonathan Scott Kolochuk', 2008, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/3037', 'http://hdl.handle.net/1993/3037', NULL, NULL, 246, NULL, 'prairies', 3, 'other-oa', 'Growing intensification of agriculture in southern Manitoba has raised concern over the impacts of land use such as crop and livestock production on water quality in local surface waters. In this study 59 farm ponds across south-central Manitoba were sampled in three week rotations for nutrients, ions, total chlorophyll a, total microcystins, fecal coliforms and general chemistry and correlated with surrounding land-use and landscape factors. As well, nutrient diffusing substrata (NDS) containing the four treatments of nitrogen (N), phosphorus (P), combined N and P, or neither were deployed in a subset of ponds throughout the sampling period to examine nutrient limitation and compare to ambient N to P ratios in the water. Overall intensive agricultural land-use was associated with poor water quality conditions (i.e., high nutrients and turbidity) and ambient ratios of N to P concentrations were inconsistent in predicting nutrient limitation exhibited by algal growth on NDS.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ceabeefd-7f76-40a9-9fce-8df0dd062b7c', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Managing cow-calf operations to protect water quality', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2376324', 'https://open.alberta.ca/dataset/ff35fafb-159e-46ab-957a-7db4f9ba05f2/resource/b76726f1-0c78-4fd7-91da-7b975a6899f9/download/2000-576-4.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Manure is a valuable nutrient source to a farm. However, manure contains nutrients, organic matter and micro-organisms that can contaminate water supplies.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('08814ad3-2203-4c90-b0c9-990b275e40a9', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'The Economics of Riparian Management: A Literature Review', 'David O. Watson, Peter C. Boxall, Jamie Miller, Unterschultz, Jim', 2000, 'RePEc: Research Papers in Economics', '10.7939/r3513tx6t', 'https://doi.org/10.7939/r3513tx6t', 'https://era.library.ualberta.ca/items/48318b5b-145a-488e-a9b9-26c6132a20ea/view/19d9fb43-7688-4ad1-8a15-0d939973a368/pr-00-06.pdf', NULL, NULL, 16, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06283426-33fe-414f-b60a-cc6cb780330a', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Novel Recombinase Polymerase Amplification Assay Is Sensitive for Detection of Macrolide Resistance Genes Relevant to Bovine Respiratory Disease Management in Feedlot Calves', 'Funk T, McLeod L, Conrad CC, Zaheer R, Otto SJG, Waldner CL, McAllister TA', 2025, 'Veterinary sciences', '10.3390/vetsci12111079', 'https://doi.org/10.3390/vetsci12111079', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12656793.1/PMC12656793.1.pdf', NULL, NULL, 27, NULL, 'prairies', 4, 'cc by', 'Macrolides are crucial for the management and treatment of bovine respiratory disease (BRD). However, antimicrobial resistance (AMR) threatens the efficacy of these and other antimicrobials. We developed real-time recombinase polymerase amplification (RPA) assays targeting three clinically relevant macrolide antimicrobial resistance genes (ARGs)-msrE-mphE and erm42-in ≤30 min using extracted DNA. A set of 199 deep nasopharyngeal swabs (DNPS) collected from feedlot calves near the time of arrival were selected based on bacterial culture (BC) results for Mannheimia haemolytica, Pasteurella multocida, and Histophilus somni and antimicrobial susceptibility testing (AST) for tulathromycin, tilmicosin, tildipirosin, or gamithromycin. Samples were also tested for the same targets using RPA and polymerase chain reaction (PCR). In samples that were culture-positive for one or more macrolide-resistant BRD-associated bacteria (n = 101), msrE-mphE and/or erm42 were detected in 95% of cases using RPA. The remaining 98 samples were either culture-negative, or the recovered bacteria were macrolide-susceptible: 43% of these were RPA-positive for at least one macrolide ARG. Together with BC-AST and PCR, Bayesian latent class modelling estimated the clinical sensitivity of RPA for macrolide ARGs to be 95% and specificity to be 58%, with moderate agreement between RPA and BC-AST (κ = 0.52) or PCR (κ = 0.55). The estimated sensitivity of the RPA multiplex assay for the targeted macrolide ARGs was very good, although estimated specificity was limited. However, Sanger sequencing confirmed RPA detection of msrE-mphE in BC-AST/PCR-negative samples (n = 23), reflecting the presence of this locus in non-target bacteria, as well as potential ARG variants among BRD bacteria. These findings support the potential of RPA for rapid ARG detection from extracted DNA. Continued assay optimization and evaluation for detection of respiratory bacteria and ARGs will further enhance its diagnostic utility.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d9445e8d-36c9-4c40-a4f4-3de9f34eaeee', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Off-Source Watering Systems for Livestock', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/off-source-watering-systems-for-livestock', 'https://open.alberta.ca/dataset/a2ea8240-1132-45ef-a774-d3f7332d50e6/resource/0b9a4e5c-c262-4dcf-ac5d-92c2dddc19b8/download/agi-off-source-watering-systems-for-livestock-2024-01.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This information sheet looks at the benefits of using off-source watering systems for livestock, to protect both natural and constructed water sources from environmental damage and to address herd health problems.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9885c635-99f0-482c-a6b8-ec6b3924e4e7', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Off-Stream Watering Systems and Partial Barriers as a Strategy to Maximize Cattle Production and Minimize Time Spent in the Riparian Area', 'Ashley Rawluk, Gary H. Crow, Getahun Legesse, Douglas M. Veira, Paul Bullock, L. A. González, Melanie Dubois, Kim Ominski', 2014, 'Animals', '10.3390/ani4040670', 'https://doi.org/10.3390/ani4040670', 'https://www.mdpi.com/2076-2615/4/4/670/pdf?version=1414574280', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'A study was conducted in 2009 at two locations in Manitoba (Killarney and Souris), Canada to determine the impact of off-stream waterers (OSW) with or without natural barriers on (i) amount of time cattle spent in the 10 m buffer created within the riparian area, referred to as the riparian polygon (RP), (ii) watering location (OSW or stream), and (iii) animal performance measured as weight gain. This study was divided into three 28-day periods over the grazing season. At each location, the pasture-which ranged from 21.0 ha to 39.2 ha in size-was divided into three treatments: no OSW nor barriers (1CONT), OSW with barriers along the stream bank to deter cattle from watering at the stream (2BARR), and OSW without barriers (3NOBARR). Cattle in 2BARR spent less time in the RP in Periods 1 (p = 0.0002), 2 (p = 0.1116), and 3 (p < 0.0001) at the Killarney site compared to cattle in 3NOBARR at the same site. Cattle in 2BARR at the Souris site spent more time in the RP in Period 1 (p < 0.0001) and less time in Period 2 (p = 0.0002) compared to cattle in 3NOBARR. Cattle did use the OSW, but not exclusively, as watering at the stream was still observed. The observed inconsistency in the effectiveness of the natural barriers on deterring cattle from the riparian area between periods and locations may be partly attributable to the environmental conditions present during this field trial as well as difference in pasture size and the ability of the established barriers to deter cattle from using the stream as a water source. Treatment had no significant effect (p > 0.05) on cow and calf weights averaged over the summer period. These results indicate that the presence of an OSW does not create significant differences in animal performance when used in extensive pasture scenarios such as those studied within the present study. Whereas the barriers did not consistently discourage watering at the stream, the results provide some indication of the efficacy of the OSW as well as the natural barriers on deterring cattle from the riparian area.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37ce629a-a755-4e53-a8d2-bf55a22054f1', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'On-farm slaughter operation : potable water testing [2026]', 'Government of Alberta', 2026, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/ofso-potable-water-testing', 'https://open.alberta.ca/dataset/9fd5f2cf-1bbb-4fc1-9068-23fced1ac98e/resource/1167110d-115c-4065-96a9-1840ed2fa6ec/download/agi-ofso-potable-water-testing-2026-04.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Offers information for on-farm slaughter operations on potable water and water sources, laboratory testing and results, and water sampling and testing information, to help operators ensure they are using safe and potable water in their processing facilities. This information sheet is one of seven information sheets which are required reading for on-farm slaughter operation applicants planning on conducting slaughtering and/or processing of uninspected meat products.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('08834975-575f-4f2e-91d5-ff11557ebcc9', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'On-farm slaughter operation : water and ice safety', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/ofso-water-and-ice-safety', 'https://open.alberta.ca/dataset/edfa9759-fef2-4df6-aaee-6307f18974f2/resource/e110f5d7-87c3-4601-8e3f-9943fa093b8e/download/agi-ofso-water-and-ice-safety.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Describes the risks to water safety and the importance of reliable, potable and safe water and ice used in meat processing to prevent contamination of product or the processing facility. This information sheet is one of seven information sheets which are required reading for on-farm slaughter operation applicants planning on conducting slaughtering and/or processing of uninspected meat products.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4617a730-82d8-4ce9-9dde-cddc943772f1', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Phenotypic and genetic parameters of circadian rhythms from core body temperature profiles and their relationships with beef steers'' production efficiency profiles during successive winter feeding periods', 'Durunna O, Carroll JA, Dailey JW, Damiran D, Larson KA, Timsit E, Parsons R, Manafiazar G', 2023, 'Frontiers in genetics', '10.3389/fgene.2023.1026601', 'https://doi.org/10.3389/fgene.2023.1026601', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9893500.1/PMC9893500.1.pdf', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by', 'This 2-year study evaluated differences in circadian parameters obtained from measures of core body temperatures using telemetric reticulo-rumen and rectal devices during two winter feeding regimes in western Canada. The study also estimated phenotypic correlations and genetic parameters associated with circadian parameters and other production traits in each feeding regime. Each year, 80 weaned steer calves (initial age: 209 ± 11 days; BW: 264 ± 20 kg) from the same cohort were tested over two successive regimes, Fall-Winter (FW) and Winter-Spring (WS) at Lanigan, Saskatchewan, Canada. The steers received forage-based rations in both regimes where the individual feed intake was measured with automatic feeding units. During the trial, the reticulo-rumen (RTMP) and rectal (RCT) temperatures were simultaneously measured every 5 min using telemetric devices. These were used to calculate the circadian parameters (Midline Estimating Statistic Of Rhythms, amplitude, and acrophase/peak time) for both temperature measures. Growth and efficiency performance traits were also determined for all steers. Each steer was assigned into inefficient, neutral, and efficient classes based on the SD of the residual feed intake (RFI), residual gain (RG), and residual intake and gain (RIG) within each year and feeding regime. Higher (p p p > 0.10) with the production efficiency profiles. The heritability estimates were higher in FW (0.78 ± 0.18 vs. 0.56 ± 0.26) than WS (0.50 ± 0.18 vs. 0.47 ± 0.22) for the rumen and rectal MESORs, respectively. There were positive genetic correlations between the two regimes for the RTMP (0.69 ± 0.21) and RCT (0.32 ± 0.59). There was a negative correlation (p < 0.001) between body temperature and ambient temperature. The high heritability estimates and genetic correlations for rumen and rectal temperature parameters demonstrate their potential as beef genetic improvement tools of economic traits associated with the parameters. However, there are limited practical implications of using only the core-body temperature as a proxy for production efficiency traits for beef steers during winter.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc58bd12-2587-4b0e-8be5-cb038b098459', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Phenotypic relationship and repeatability of methane emissions and performance traits in beef cattle using a GreenFeed system', 'Clodagh V Ryan, T. Pabiou, Deirdre C. Purfield, Stephen B Conroy, Stuart F. Kirwan, John J. Crowley, Craig P. Murphy, R.D. Evans', 2022, 'Journal of Animal Science', '10.1093/jas/skac349', 'https://doi.org/10.1093/jas/skac349', 'https://academic.oup.com/jas/article-pdf/100/12/skac349/47762162/skac349.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Rumen methanogenesis results in the loss of 6% to 10% of gross energy intake in cattle and globally is the single most significant source of anthropogenic methane (CH4) emissions. The purpose of this study was to analyze greenhouse gas traits recorded in a commercial feedlot unit to gain an understanding into the relationships between greenhouse gas traits and production traits. Methane and carbon dioxide (CO2) data recorded via multiple GreenFeed Emission Monitoring (GEM), systems as well as feed intake, live weight, ultrasound scanning data, and slaughter data were available on 1,099 animals destined for beef production, of which 648 were steers, 361 were heifers, and 90 were bulls. Phenotypic relationships between GEM emission measurements with feed intake, weight traits, muscle ultrasound data, and carcass traits were estimated. Utilization of GEM systems, daily patterns of methane output, and repeatability of GEM system measurements across averaging periods were also assessed. Methane concentrations varied with visit number, duration, and time of day of visit to the GEM system. Mean CH4 and CO2 varied between sex, with mean CH4 of 256.1 g/day ± 64.23 for steers, 234.7 g/day ± 59.46 for heifers, and 156.9 g/day ± 55.98 for young bulls. A 10-d average period of GEM system measurements were required for steers and heifers to achieve a minimum repeatability of 0.60; however, higher levels of repeatability were observed in animals that attended the GEM system more frequently. In contrast, CO2 emissions reached repeatability estimates >0.6 for steers and heifers in all averaging periods greater than 2-d, suggesting that cattle have a moderately consistent CO2 emission pattern across time periods. Animals with heavier bodyweights were observed to have higher levels of CH4 (correlation = 0.30) and CO2 production (correlation = 0.61), and when assessing direct methane, higher levels of dry matter intake were associated with higher methane output (correlation = 0.31). Results suggest that reducing CH4 can have a negative impact on growth and body composition of cattle. Methane ratio traits, such as methane yield and intensity were also evaluated, and while easy to understand and compare across populations, ratio traits are undesirable in animal breeding, due to the unpredictable level of response. Methane adjusted for dry matter intake and liveweight (Residual CH4) should be considered as an alternative emission trait when selecting for reduced emissions within breeding goals.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d3b417b3-83ad-4f74-a0ee-4b40977db517', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Prevalences of respiratory viruses and bacteria in Western Canadian commercial feedlot calves detected using a single metagenomic sequencing protocol vary during the first two weeks of arrival and by age group', 'Donbraye E, McLeod L, Carson CN, Chai Z, Lacoste SR, Herman EK, McCarthy EL, Hill JE', 2025, 'Frontiers in veterinary science', '10.3389/fvets.2025.1704412', 'https://doi.org/10.3389/fvets.2025.1704412', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12917898.1/PMC12917898.1.pdf', NULL, NULL, 20, NULL, 'prairies', 4, 'cc by', 'IntroductionDetection of pathogens associated with bovine respiratory disease (BRD) typically involves several laboratory tools, with results limited to a defined list of targets. This study adapted a previously reported method for metagenomic sequencing of nasal swabs to describe sequencing data from BRD associated viruses. Changes in virus composition were identified between arrival to a feedlot and 14 days on feed (DOF). These data were also assessed for the simultaneous characterization of bacteria and antimicrobial resistance genes (ARGs).MethodsNasal swabs were obtained from fall-placed calves (FPC) and yearlings (YRL) from western Canadian commercial feedlots. Evidence of respiratory viruses were identified by sampling 380 animals during processing on arrival to the feedlot and again after 14 DOF using Nanopore metagenomic sequencing.ResultsTwenty-one distinct viruses from 12 viral families were identified, with multiple viruses detected in most samples. In FPC arrival samples, the most common BRD associated viruses were bovine rhinitis B virus (BRBV; 46%), bovine coronavirus (BCoV; 32%), influenza D virus (IDV; 17%), bovine respiratory syncytial virus (BRSV; 8.5%), and bovine parainfluenza virus 3 (BPIV-3; 4.2%). The prevalences of bovine herpesvirus type 1 (BoHV-1; 2.7%), BPIV-3 (12%), BRSV (26%), and IDV (51%) were higher in 14 DOF samples compared to arrival samples (p p p = 0.01). In 14 DOF samples, BPIV-3 (OR 4.9, 1.3-19, p = 0.02) and BVDV-2 (OR 13, 2.0-83, p = 0.01) were identified more frequently in YRL than FPC. These data allowed the identification of respiratory bacteria and 33 ARGs in parallel with assessment of the viral components. The most prevalent bacteria detected in FPC at arrival were Mannheimia haemolytica (35%), Histophilus somni (35%) and Pasteurella multocida (23%). Detection of M. haemolytica increased at 14 DOF (p = 0.02), while P. multocida detection decreased (p = 0.03). At both arrival and 14 DOF in YRL, M. haemolytica was the most prevalent bacterium, followed by P. multocida and H. somni with no significant differences between arrival and 14 DOF samples. ARGs were detected more frequently in the 14 DOF samples than at arrival for both FPC (p = 0.03) and YRL (p = 0.01). The most commonly detected ARGs were associated with resistance to lincosamides and aminoglycosides; however, ARGs associated with other antimicrobials used in cattle including tetracyclines were also identified.DiscussionChanges in the prevalence of BRD associated viruses early in the feeding period reflect transmission and the potential risk of developing the disease. Frequent detection of BCoV, BRSV, and BPIV-3 in newly arrived feedlot cattle suggests the need for improved vaccination before shipping or limitations in existing commercial vaccine preparations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0dfa7d00-9875-4ca2-8182-f38bd4117302', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Production and use of dry-rolled hybrid rye grain as a replacement for barley grain on growth performance and carcass quality of feedlot steers', 'Zhang F, Carey RE, Brattain RS, Wehrle H, Penner GB', 2024, 'Translational animal science', '10.1093/tas/txae059', 'https://doi.org/10.1093/tas/txae059', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11067788.1/PMC11067788.1.pdf', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by', 'The objectives were to compare cereal grain and straw yield between barley and hybrid rye (HR) and to evaluate whether the inclusion of dry-rolled HR grain as a replacement for barley grain affected feed intake and growth for growing cattle, and feed intake, growth, and carcass characteristics for finishing cattle. Crop yield was measured by directly weighing harvested grain and straw bales (n = 3 plots/grain type). Three-hundred sixty steers with an initial body weight (BW) of 348 ± 40 kg were stratified by BW and randomly assigned to 1 of the 24 pens during the growing phase (n = 8; 65 d). The control diet (BCON) included 60.22% barley grain with HR included by replacing 50 (BMID) or 100% (BHIGH) of the barley grain on a dry matter (DM) basis. Steers were re-randomized for the finishing phase (n = 6; 118 d) and treatments included a control diet containing 88.60% barley grain (FCON) with HR replacing 33 (FLOW), 67 (FMED), or 100% (FHIGH) of the barley grain (DM basis). The grain yield was greater (P = 0.04) and straw yield tended (P = 0.06) to be less for HR than barley. There were no effects of HR inclusion on DM intake (DMI) or G:F during the growing phase, but average daily gain (ADG) responded quadratically (P = 0.02) with cattle fed 50% HR having the greatest gain. During finishing, DMI decreased linearly as HR grain inclusion increased (P P P = 0.02). There was a linear increase in dressing percentage (P = 0.02) and a linear reduction in back fat thickness (P = 0.04) with increasing inclusion of HR. Increasing the inclusion of HR during finishing cubically (P < 0.01) affected the proportion of minor and severe liver abscesses with an average of 34.60% severely abscessed livers when HR was included compared to 11.11% for BCON. HR may have greater grain yield than barley, and partial replacement of barley grain with HR may improve ADG without affecting DMI or G:F during the growing phase. However, replacing barley grain in finishing diets with HR decreases DMI, and increases the risk of minor and severe liver abscesses, but does not affect feed conversion, suggesting HR should not replace more than 33% of the barley grain to maintain ADG.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('478aeaf5-f19b-41f2-8ebd-3535d57239b9', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Respiratory Bacteria and Antimicrobial Resistance Genes Detected by Long-Read Metagenomic Sequencing Following Feedlot Arrival, Subsequent Treatment Risk and Phenotypic Resistance in Feedlot Calves', 'Abi Younes JN, McLeod L, Lacoste SR, Chai Z, Herman EK, McCarthy EL, Campbell JR, Gow SP', 2025, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics14111098', 'https://doi.org/10.3390/antibiotics14111098', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12649505.1/PMC12649505.1.pdf', NULL, NULL, 25, NULL, 'prairies', 4, 'cc by', 'Background/Objectives: Long-read metagenomic sequencing can assign antimicrobial resistance genes (ARGs) to speciated bacterial reads. This study evaluated whether metagenomic data from respiratory bacteria derived from feedlot calves sampled in the early feeding period were associated with subsequent bovine respiratory disease (BRD) treatment and phenotypic antimicrobial resistance (AMR) at treatment. Methods: Deep nasopharyngeal swabs (DNPSs) obtained at arrival processing (1 day on feed; DOF), 13 DOF, and the time of BRD treatment were cultured and subjected to antimicrobial susceptibility testing (AST) and long-read metagenomic sequencing. Analyses focused on macrolide (mphE-msrE, EstT) and tetracycline (tet(H)) ARGs within reads assigned to Mannheimia haemolytica, Pasteurella multocida, Histophilus somni, or Bibersteinia trehalosi. Generalized estimating equations assessed associations between metagenomic results from 1 and 13 DOF and subsequent BRD treatment risk and AST outcomes at treatment, at both the individual animal (calf) and pen levels. Results: Calf-level detection of H. somni at 13 DOF was associated with a greater BRD treatment risk between 14 and 45 DOF. An increased pen prevalence of either M. haemolytica or P. multocida at 13 DOF was associated with a greater BRD treatment risk from 14 to 45 DOF. At 13 DOF, detections of mphE-msrE, EstT, or tet(H) in target bacteria were associated with corresponding phenotypic AMR at BRD treatment. Similarly, a higher pen-level prevalence of mphE-msrE or EstT at 13 DOF was also associated with increased macrolide resistance at BRD treatment. Conclusions: The results from long-read metagenomic sequencing of DNPSs collected at 13 DOF were associated with both BRD risk and AMR at treatment. These findings align with prior culture-based results and support the potential utility of pen-level metagenomic testing for AMR surveillance and informing antimicrobial selection in feedlots.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05e6b937-ae36-46d3-a822-cd61227ba0c4', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Sulfate Removal from Water', 'Ashref Darbi, Thiruvenkatachari Viraraghavan, Yee‐Chung Jin, Larry Braul, Darrell R. Corkal', 2003, 'Water Quality Research Journal', '10.2166/wqrj.2003.011', 'https://doi.org/10.2166/wqrj.2003.011', 'https://iwaponline.com/wqrj/article-pdf/38/1/169/229009/wqrjc0380169.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('38e7bf42-2218-45ec-83dd-21557bee87e6', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'The occurrence of microcystins in Alberta recreational waters', 'Vichaya Charoensuk, Dorothy Y. Huang, Birget Moe, Paige Demofsky, Xu Zhang, David W. Kinniburgh', 2026, 'Canadian Water Resources Journal / Revue canadienne des ressources hydriques', '10.1080/07011784.2026.2719470', 'https://doi.org/10.1080/07011784.2026.2719470', 'https://www.tandfonline.com/doi/pdf/10.1080/07011784.2026.2719470?needAccess=true', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'Cyanobacterial bloom occurrence and the presence of microcystins (MCs) in freshwater have been reported globally, posing significant public health concerns due to their hepatotoxicity and health consequences. As part of the Alberta Cyanobacteria Monitoring Program, 3,963 water samples (93% composite, 7% grab) were collected from recreational beach areas across Alberta during spring and summer from 2015 to 2025. All samples were analyzed for total MCs using the protein phosphatase inhibition assay (PPIA). PPIA-positive samples (n = 2,176) underwent quantitative analysis by liquid chromatography coupled with high-resolution mass spectrometry (LC-HRMS) for quantification of twelve MC congeners. Over the monitoring period, MC concentrations in Alberta lakes generally rose in mid-June and peaked in July and August. The PPIA results showed that 4.1% of composite and 19.6% of grab samples exceeded the Canadian Recreational Water Guideline of 10 µg/L total MCs, mostly in samples collected in July and August from lakes in the Alberta Health Services (AHS) North and Central zones. Differences in both the geographic and temporal distribution of MCs in Alberta recreational waters, exemplified by our results from Astotin and Thunder Lakes, were observed. These observations are consistent with the substantial variability in both the distribution and composition of cyanobacterial communities in Alberta water bodies previously reported. LC-HRMS results showed the presence of multiple MC congeners, with MC-LR being the most dominant and prevalent in samples tested, followed by MC-LA. Linear regression analysis of MC concentrations obtained from either PPIA or LC-HRMS showed a significant linear relationship (R2 = 0.9408, p < 0.0001, n = 1,534).', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('68d01646-1b40-42b8-ac87-30bb51378a70', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'THE WATER QUALITY OF THE WOOD RIVER AND THE EFFECTS OF LAND USE', 'Jennifer Holm', 2004, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-03292004-163601', 'http://hdl.handle.net/10388/etd-03292004-163601', NULL, NULL, 117, NULL, 'prairies', 3, 'other-oa', 'The Wood River, located in the Old Wives Lake watershed in southern Saskatchewan, is an important water resource for people living in this area. Agriculture dominates land use in the basin, while the river receives waste water effluent from the town of Gravelbourg twice yearly. Both land usage in the basin and the dumping of municipal waste water effluent have the potential to degrade water quality in the river. To date however, the water quality of the Wood River has been relatively unstudied. The purpose of this study was threefold. First, to evaluate the water quality of the Wood River and compare it to similar river systems. Then, to evaluate the effects of nutrients on the pelagic phytoplankton in the river to determine the biological responsiveness to nutrient additions which might occur as a result of agricultural land use and municipal waste water effluent. Lastly to propose mitigative measures that could help to reduce the potential threat of increased nutrients. To determine the effect that agricultural land use and municipal waste water effluent was having on river water quality, nutrient and chlorophyll a (a measure of algal biomass) levels in the river were examined. Five sites, having different land use patterns, were chosen for this purpose. These included a reference site at a regional park not directly affected by agriculture, a site where agricultural land use dominated, a site utilized by cattle, a reservoir within the river system used for drinking water and surrounded by agriculture and finally, a site just downstream from where Gravelbourg''s municipal waste is released. Nitrogen (N) and phosphorus (P) levels were high in the Wood River when compared to similar systems. The mean TP concentration for the Wood River over the two years of this study was 474 μg/L (± 246 STD) while the mean ammonia concentration was 223 μg/L (± 993 STD). These concentrations exceeded water quality guidelines. Algal biomass and nutrient concentrations were higher at sites where nonpoint source pollution from agriculture or point source pollution from sewage effluents was present. Nutrient enrichment bioassays also indicated that the algal population in the Wood River was responsive to additions of nutrients, therefore, increases in nutrients will increase algal biomass in the river. The bioassays also revealed that at the sites where agriculture and municipal waste water were present, the algal population was N limited indicating an excess of P in the river. The municipal point source of pollution had a great effect on algal biomass and these effects lasted for about three weeks after the release. Different land use patterns and municipal waste water effluent were potentially having a negative effect on the water quality of the Wood River. An examination of mitigative strategies available in the Old Wives Lake area revealed that land management tools including the implementation of soil conservation practices and riparian management could be useful in protecting the Wood River from degradation. Neither soil conservation practices nor riparian management are used extensively in the watershed, and both of these practices could help improve the water quality of the Wood River.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('22d37fb4-79d6-454e-98ed-faa00af67d54', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Tigers on the Prowl: Determining the Distribution and Habitat Requirements of Eastern Tiger Salamander (Ambystoma tigrinum) in Manitoba', 'Church, Carla', 2025, NULL, '10.36939/ir.202508281417', 'https://doi.org/10.36939/ir.202508281417', 'https://winnspace.uwinnipeg.ca/bitstream/10680/2222/1/Church_Carla_Thesis_2025.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5cf48e61-8b1e-49fd-abf2-d139ddb248ab', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Total dissolved solids in water high in naturally occurring sulfates impacts serum and liver copper and selenium concentrations but does not affect the growth of beef heifers', 'Koryn S Hare, Murillo Ceola Stefano Pereira, Catherine M Seidle, Dwayne Summach, Jordan A. Johnson, John Campbell, G.B. Penner', 2026, 'Canadian Journal of Animal Science', '10.1139/cjas-2024-0144', 'https://doi.org/10.1139/cjas-2024-0144', 'https://harvest.usask.ca/bitstreams/0cb72620-4e5e-4e19-aeea-fba8686261cb/download', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'This study evaluated whether water with high total dissolved solids (TDS) containing naturally occurring sulfates impacts feed and water intake, growth, and serum and liver minerals in crossbred Angus heifers (n = 48). Heifers were stratified by body weight into 12 pens and randomly assigned (n = 4 pens/treatment) to water with low (980 mg L-1), moderate (5,190 mg L-1), or high (9,720 mg L-1) TDS, resulting in sulfate concentrations of 350, 2,970, and 5,770 mg L-1. Body weight, average daily gain, dry matter and water intake, and the gain:feed ratio were not affected (P≥0.11) during the 100-d study. Serum Se increased (P<0.01) on d 50, 75, and 100 when heifers were provided water with high and moderate compared to low TDS water. High and moderate rather than low TDS water also reduced (P≤0.01) serum Cu and Mo. Liver Cu was reduced (P<0.01) by moderate and high TDS water, while liver Se was only reduced (P=0.01) by high TDS water. Providing high TDS water with sulfate concentration ≥2,970 mg L-1 can be used without impairing growth, but it may compromise Cu and Se reserves. Thus, mineral status should be monitored when cattle consume sulfate-rich water.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48a17351-573a-461b-baca-c60caf1ff245', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Toxic cyanobacteria in relation to sulfate, molybdenum, nitrogen and phosphorus in Alberta''s shallow prairie lakes', 'Susan Marie Anderson', 2018, 'Libraries and Cultural Resources (University of Calgary)', '10.11575/prism/33226', 'https://doi.org/10.11575/prism/33226', 'http://hdl.handle.net/1880/108919', NULL, NULL, 124, NULL, 'alberta', 4, 'cc-by-sa', 'Cyanobacteria are characteristic of poor global water quality. They create a public health concern and threaten biodiversity, particularly when they produce toxins such as microcystins. It is poorly understood why cyanobacteria produce microcystins, or how cyanobacteria in shallow prairie lakes will respond to increased salinity under changing climate. To study the effects of variable sulfate concentrations on cyanobacteria and to elucidate environmental patterns of microcystin production, I sampled 25 shallow lakes over four months for total nitrogen (TN), dissolved inorganic nitrogen (DIN), total phosphorus (TP), soluble reactive phosphorus (SRP), sulfate, molybdenum, microcystins, and the cyanobacteria-specific pigments canthaxanthin, myxoxanthophyll and echinenone. There was a negative relationship between cyanobacteria pigment and sulfate, and a positive relationship between cyanobacteria pigment and molybdenum and total nitrogen. Microcystins positively correlated with cyanobacteria pigment and turbidity. When microcystin samples above 10 µg·L-1 were removed, microcystins correlated with TN:TP in June and July. My results suggest that increasing sulfate leads to less cyanobacteria pigment. With the prairies expected to get hotter and dryer in the future, shallow prairie lakes are likely to see less cyanobacteria as they increase in salinity. My results also indicate that higher cyanobacteria pigments correlate with higher microcystins. Although low TN:TP can lead to high microcystins, low TN:TP is not enough to differentiate between high and low microcystins. No thresholds were found in either analysis, meaning there was no evidence for a tipping point where sulfate limits cyanobacteria nor the existence of environmental triggers associated with microcystin production over the season.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('964eba7f-eb45-4aa2-9fde-2124936be612', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Using Probabilistic Machine Learning Methods to Improve Beef Cattle Price Modeling and Promote Beef Production Efficiency and Sustainability in Canada', 'Elham Rahmani, Mohammad Khatami, Emma C. Stephens', 2024, 'Sustainability', '10.3390/su16051789', 'https://doi.org/10.3390/su16051789', 'https://www.mdpi.com/2071-1050/16/5/1789/pdf?version=1708582701', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by', 'Accurate agricultural commodity price models enable efficient allocation of limited natural resources, leading to improved sustainability in agriculture. Because of climate change, price volatility and uncertainty for the sector are expected to increase in the future, increasing the need for improved price modeling. With the emergence of machine learning (ML) algorithms, novel tools are now available to enhance the modeling of agricultural commodity prices. This research uses both univariate and multivariate ML techniques to perform probabilistic price prediction modelling for the Canadian beef industry, taking into account beef production, commodity market, and international trade features to enhance accuracy. We apply multivariate algorithms by using support vector regression (SVR), random forest (RF), and adaboost (AB) and univariate algorithms by using autoregressive integrated moving average (ARIMA), seasonal ARIMA (SARIMA), and the seasonal autoregressive integrated moving average with exogenous factors (SARIMAX). We apply these models to monthly fed steer price data between January 2005 and September 2023 and compare predicted prices with observed prices using several validation metrics. The outcomes indicate that both random forest (RF) and adaboost (AB) in multivariate modeling show superior performance in accurately predicting Alberta fed steer prices in comparison to other algorithms. To better account for the variance of the best model performance, we subsequently adopted a probabilistic approach by considering uncertainty in our best-selected ML model. The beef industry can use these improved price models to minimize resource waste and inefficiency in the sector and improve the long-term sustainability prospects for beef producers in Canada.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('717bd1f7-bc55-470e-a827-c571783c71ca', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Water analysis interpretation for livestock', 'Government of Alberta', 1987, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3910109', 'https://open.alberta.ca/dataset/03a8d218-9800-4bc5-866e-48a5bd3a5607/resource/e167aeff-c664-4ab0-a972-b2a479bdc011/download/2007-400-716-2.pdf', NULL, NULL, 9, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Water consists of two simple compounds: two hydrogen atoms and one oxygen atom bonded together (H2O). It is the most essential nutrient needed to sustain life. In most animals, water accounts for 50 to 70 per cent of body weight. Water contains many different elements and compounds besides hydrogen and oxygen. These elements exist in water in a variety of forms, entering and leaving the water depending on the surrounding environment. For example, the mineral composition of ground water is affected by the rock or soil type the water passes through or the amount of time it spends in an aquifer. Surface water can be affected by many of the same factors as ground water. In addition, surface water is influenced by airborne and soil pollutants, decaying organic matter and the removal of minerals by vegetative growth.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('537ff7cc-4af2-45fa-80cb-beada20309d3', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Water quality of an integrated crop–livestock system in the northern Great Plains', 'Derek R. Faust, Mark A. Liebig, TOLEDO P. DAVID, David Walter Archer, Scott L. Kronberg, John Hendrickson, Arun Bawa, Sandeep Kumar', 2020, 'Agrosystems Geosciences & Environment', '10.1002/agg2.20129', 'https://doi.org/10.1002/agg2.20129', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/agg2.20129', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'Abstract Impacts of integrated crop–livestock (ICL) systems on water quality have not been well studied. Water quality parameters were quantified for two 30‐min rainfall simulations in wheat (Triticum aestivum L.)–cover crop, cover crop, and rangeland grass control phases of a long‐term ICL study site in Mandan, ND, in 2017 and 2018. Both pre‐graze and post‐graze simulations were conducted. Nitrate‐N (NO3−–N), nitrite‐N (NO2−–N), ammonia‐N (NH4+–N), phosphate‐P (PO43−–P), and total suspended solid (TSS) concentrations and loads were evaluated in surface runoff water, along with concentrations of NO3−–N, NO2−–N, NH4+–N, and PO43−–P in infiltration water. Non‐parametric ranked two‐way analysis of variance was used to evaluate differences for vegetation type and grazing as fixed effects, with year as a random effect. Surface runoff concentrations of NO3−–N and NH4+–N were significantly different with cover crop and wheat phases being greater than grass. A grazing effect was also observed with pre‐graze significantly greater than post graze for NO2−–N, NH4+–N, PO43−–P, and TSS surface runoff concentrations. For infiltration water concentrations, similar significant effects of vegetation type were observed for NO3−–N and PO43−–P, while pre‐graze was also greater than post‐graze for NO2−–N and PO43−–P. Due to variable runoff volumes, no significant differences were observed for loads of any parameters. Minimal runoff volumes (0–6.7 L) and significant vegetation and grazing effects in nutrient infiltration water concentrations highlight the importance of infiltration in such studies, particularly at sites in the northern Great Plains.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e35fcd75-b126-4019-9458-77563b15b163', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Water requirements for livestock', 'Government of Alberta', 1982, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3124615', 'https://open.alberta.ca/dataset/50db2d54-3708-4efe-b0a3-e49f47a0fcbb/resource/f2eebe47-0eac-4099-b105-f787103c2d3b/download/2005-400-716-1.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Water is the main constituent of the animal’s body, constituting 50 to 80 percent of the liveweight, depending on age and degree of fatness. An animal can lose almost all of its fat and about 50 per cent of its body protein and survive. However, the loss of 10 per cent of its body water can be fatal. Therefore, a successful livestock enterprise requires a good water supply. A good water supply is defined both in terms of quantity and quality of the water. A good water supply is important to the livestock manager because total water intakes are positively related to feed dry matter (DM) intakes.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cfa1e9a4-2293-4fb9-b415-9a0710e47697', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Water well restoration or replacement program', 'Government of Alberta', 2019, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/well-water-restoration-or-replacement-program-wwrrp', 'https://open.alberta.ca/dataset/2fd18b9e-fe96-499a-9abf-1f1ef05556ba/resource/ce754225-6f9f-4072-b72a-36ad46a13d2a/download/agi-fao-wwrrp-2025.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This brochure by the Farmers'' Advocate Office describes The Water Well Replacement or Restoration Program (WWRRP). The purpose of the WWRRP is to mitigate impacts of energy activities on water wells in rural Alberta. The brochure includes information on how to apply for program funding.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b87cb41-b2b9-43cd-967c-a2f7321d4155', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Watershed resiliency and restoration program : improving Alberta’s natural watershed resiliency to flood and drought [2024]', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/9781460141311', 'https://open.alberta.ca/dataset/a9645805-e243-4707-b930-e6eb4c8a3b78/resource/1ab6babe-3e37-42e3-b203-fa0ed2b3dfd2/download/epa-wrrp-improving-albertas-watershed-resiliency-flood-drought-2024-10.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Report on the progress of the Watershed Resiliency and Restoration Program since its inception in 2014. The program aims to build long-term watershed resiliency to flood and drought by improving natural watershed functions and engaging Albertans in the conservation, restoration, enhancement and stewardship of critical watershed features including wetlands, riparian areas and floodplains.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7981fd4c-d3fa-4164-a005-ef79fb905e34', '4941fc5a-eb08-4f1b-80e7-7af183dc796e', 'Yield of hybrid rye silage and its use as a replacement for barley silage on feed intake, growth performance, and carcass quality of growing and finishing steers', 'Zhang F, Brattain RS, Wehrle H, Baron V, Ribeiro GO, Penner GB', 2025, 'Translational animal science', '10.1093/tas/txaf048', 'https://doi.org/10.1093/tas/txaf048', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12057561.1/PMC12057561.1.pdf', NULL, NULL, 13, NULL, 'prairies', 4, 'cc by', 'This study compared the yield of barley and hybrid rye when harvested for silage, and evaluated the effects of replacing barley silage (BARS) with hybrid rye silage (HRS) on dry matter intake (DMI), growth, and carcass characteristics of feedlot steers. The whole-plant hybrid rye (late milk) and barley (soft dough) were each harvested from 3 replicate 7.85-ha plots in 2022 and 2023 and ensiled (n = 3/treatment/yr). In each year, 192 steers were allocated to 1 of 16 pens in a completely randomized block design for growing (4 pens/treatment/yr) and finishing (5 or 6 pens/treatment/yr) phases. Treatments during the growing phase (84 d) included a control diet (GCON) that contained 60% BARS, and in the remaining treatments HRS replaced 33 (GLOW), 67 (GMED), or 100% (GHIGH) of the BARS (DM basis). Steers were then re-randomized and allocated to 1 of 16 pens for the finishing phase with diets that contained (DM basis) 10% BARS (FCON) or diets where HRS replaced 50% (FMED) or 100% (FHIGH) of the BARS. Steers were fed for 112 d. Forage DM yield did not differ between whole plant hybrid rye and barley (3.96 vs. 3.70 mT/ha). During the growing phase, increasing the HRS inclusion at the expense of BARS decreased DMI (quadratic, P = 0.02), average daily gain (ADG; quadratic, P P = 0.02) with the magnitude of the response increasing with increasing HRS inclusion. In addition, the gain:feed (G:F) ratio linearly decreased (P P = 0.06), ADG decreased and then increased (quadratic, P = 0.04) with the lowest ADG observed for FMED, while G:F was unaffected. Carcass weight for steers fed FMED and FHIGH did not differ but were lighter (quadratic, P = 0.02) than FCON, and dressing percentage decreased linearly from 58.81 to 58.34% (P = 0.03) as HRS inclusion increased. Carcass yield grade and marbling were unaffected. Increasing HRS inclusion at the expense of BARS linearly decreased the proportion of steers with minor (P = 0.02) and severe (P = 0.04) liver abscesses. In conclusion, while forage yield may not differ between hybrid rye and barley, increasing the inclusion rate of HRS in diets for growing steers reduced DMI and ADG. During finishing, increasing the inclusion of HRS may decrease DMI and resulted in lighter hot carcass weight without affecting carcass yield grade or marbling.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a5f83aeb-cb0f-417c-bbac-d81c26c83c57', '4468519e-45b7-42e3-a131-b2181808b714', '43. Pulmonary arterial pressure as a predictor of performance in beef calves across weaning and preconditioning strategies.', 'Emily R Barr, Lilly R Masopust, Gabriel D Denaeyer, Morgan K Weimer, Kelly L Woodruff, Cody Gifford, Hannah C Cunningham-Hollinger, Chase D Markel', 2026, 'Journal of Animal Science', '10.1093/jas/skag190.033', 'https://doi.org/10.1093/jas/skag190.033', 'https://academic.oup.com/jas/article-pdf/104/Supplement_4/skag190.033/68756215/skag190.033.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1ccf9cc3-14fc-4e7a-ab28-d1297543f459', '4468519e-45b7-42e3-a131-b2181808b714', 'Active dry yeast supplementation improves the growth performance, rumen fermentation, and immune response of weaned beef calves', 'Jian Ma, Cheng Wang, Zhisheng Wang, Guang Cao, Rui Hu, Xueying Wang, Huawei Zou, Kun Kang', 2021, 'Animal nutrition', '10.1016/j.aninu.2021.06.006', 'https://doi.org/10.1016/j.aninu.2021.06.006', 'https://www.sciencedirect.com/science/article/pii/S2405654521001499/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'The objective of this experiment was to investigate the potential benefits of active dry yeast (ADY) on the growth performance, rumen fermentation, nutrient digestibility, and serum parameters of weaned beef calves. Thirty Simmental crossbred male calves (body weight = 86.47 ± 4.41 kg and 70 ± 4 d of age) were randomly divided into 2 groups: control (CON) (fed basal ration) and ADY (fed basal ration and 5 g/d ADY per calf). The dietary concentrate-to-roughage ratio was 35:65. All the calves were regularly provided rations 3 times a day at 07:00, 13:00, and 19:00 and had free access to water. The experiment lasted for 60 d. The average daily gain of ADY group was higher (P = 0.007) than that of the CON group, and the ratio of feed intake to average daily gain in the ADY group was reduced (P = 0.022) as compared to the CON group. The concentration of ruminal ammonia-N was higher (P = 0.023) in the CON group than that in the ADY group, but an opposite trend of microbial protein was found between the 2 groups. Also, the ruminal concentrations of propionate and butyrate were higher (P < 0.05) in the ADY group than those in the CON group. Calves fed ADY exhibited higher (P < 0.05) crude protein and neutral detergent fiber digestibility. Supplementation of ADY increased (P < 0.05) the contents of glucose, glutathione peroxidase, superoxide dismutase, immunoglobulin A, immunoglobulin M, and interleukin 10 in the serum of calves, but an opposite trend was observed in malondialdehyde, interleukin 1 beta, and tumor necrosis factor alpha contents between the 2 groups. In conclusion, dietary supplementation with ADY could improve the growth performance, rumen fermentation, nutrient digestibility, antioxidant ability, and immune response of weaned beef calves.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f2bfaa8a-2556-4f0b-8119-2583039953d3', '4468519e-45b7-42e3-a131-b2181808b714', 'An evaluation of weaning strategies for Great Plains cow-calf producers', 'Eric Bailey', 2013, 'K-State Research Exchange (Kansas State University)', NULL, 'http://hdl.handle.net/2097/15681', 'https://krex.k-state.edu/bitstreams/7dd17620-dcbd-4ed0-8187-6e5f6cd1404f/download', NULL, NULL, 141, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b040ba2-ca02-4fae-9628-4df905464539', '4468519e-45b7-42e3-a131-b2181808b714', 'Assessing Natural Weaning in Suckler Beef Cattle: A Single-Farm Retrospective Data Analysis of Calf-Raising Success and Colostrum Antibody Uptake in the Absence or Presence of a Yearling Calf', 'Albertsen, D.; Plate, P.; Held, S.D.E.', 2026, 'Animals 16(1):34', '10.3390/ani16010034', 'https://www.mdpi.com/2076-2615/16/1/34', 'https://www.mdpi.com/2076-2615/16/1/34/pdf', NULL, NULL, NULL, NULL, 'other', 3, 'CC BY 4.0', 'A rare look at what happens when suckler beef cattle are NOT artificially weaned: retrospective single-farm data on calf-raising success and colostrum antibody uptake where a yearling calf is still present versus absent. Relevant as the practical counterpart to the textbook figure that natural weaning in domestic cattle occurs between 7 and 14 months (Reinhardt & Reinhardt 1981), and as a reference point for anyone asking what the welfare baseline actually is before any weaning method is applied. Recent, 2026.', '{weaning,natural-weaning,weaning-age,colostrum,suckler,recent}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6f0cb95a-1984-4645-a408-be8a17b841b9', '4468519e-45b7-42e3-a131-b2181808b714', 'Evaluation of the efficiency of weaned calf production in beef cattle', 'Government of Alberta', 1986, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluation-of-the-efficiency-of-weaned-calf-production-in-beef-cattle', 'https://open.alberta.ca/dataset/803dbf4a-1664-46a6-844f-9c4fc0b7aaaf/resource/4b2968f4-34fc-42da-a26a-f79aa9e69c58/download/163010363758-evaluation-of-the-efficiency-of-weaned-calf-production-in-beef-cattle.pdf', NULL, NULL, 60, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project compared feed energy conversion efficiency among four beef cow breed groups over three years during winter maintenance and summer nursing periods. The groups included Control and Selected Beef Shorthorns, Simmental, and Limousin cows, which were fed cereal silage, hay cubes, or rolled barley under controlled seasonal conditions. Simmental cows had the highest summer feed energy intake, while Control Shorthorns consumed the least, but calf weight gains did not differ significantly across groups. Selected Shorthorn and Simmental cows yielded more milk than the others, though milk yield differences did not lead to better overall energy efficiency. Despite large differences in cow weight, rib fat depth, feed energy intake and milk yield, these cow breed groups did not differ significantly in terms of the feed energy consumed by cow and calf per unit of cow and calf gain.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2f60bd8-a765-4b8b-ab54-9ad78c74c6dc', '4468519e-45b7-42e3-a131-b2181808b714', 'Behavioral and Morphological Traits of Nellore Cattle That Can Influence Calf Survival and Performance from Birth to Weaning', 'Mateus José Rodrigues Paranhos da Costa, João Vitor de Toledo Menezes, Luane da Silva Fernandes, Tiago S. Valente', 2023, 'Ruminants', '10.3390/ruminants3040029', 'https://doi.org/10.3390/ruminants3040029', 'https://www.mdpi.com/2673-933X/3/4/29/pdf?version=1698799157', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'This study aimed to identify behavioral and morphological traits of Nellore cattle that can influence calves’ survival and pre-weaning performance. It was performed in two units of a large-scale cow–calf operation farm located in the Central-West region of Brazil, with 975 cow–calf dyads, by scoring cows’ maternal protective behavior, body condition, horns, udder suspension (US), teat size (TS) and calves’ vigor. TS was used to determine teat symmetry (TSm). The production unit where calves were born, their birth date, sex, and birth (BW) and weaning weights were also recorded. Cow ages at calving and production units were used to categorize the cows into twelve classes (Cage). The Shapiro–Wilk test alongside tables of frequencies were used to determine if continuous and categorical variables followed a normal distribution, respectively. Two datasets were considered in statistical analyses: (i) 975 dyad records were used to identify potential factors influencing calf survivability and (ii) 936 records of weaned calves were used to assess pre-weaning performance. Generalized linear models were used to assess the effect of target traits on the calves’ weight adjusted for 210 days of age (W210, kg) and pre-weaning average daily gain (preADG, kg/day). Tukey’s test was used to compare W210 and preADG means. Pearson’s correlation coefficients were estimated between BW, W210 and preADG. Cage, US and the TSm significantly affected pre-weaning calf performance (p < 0.01). Older cows (independently of the production unit) and those with intermediate US and symmetrical teats weaned heavier calves. As expected, positive and significant correlation was observed between BW and preADG (r = 0.35), which, in turn, was highly correlated with W210 (r = 0.99). We concluded that none of the behavioral and morphological traits influenced calf survivability, but cow age, US and TSm impacted pre-weaning performance, with 8- to 11-year-old cows and those with intermediate US and symmetric teats leading to better calf performance at weaning.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('322f5019-8da2-4942-ba6e-2d0cb8e64bcf', '4468519e-45b7-42e3-a131-b2181808b714', 'Behavioral and physiological changes in early-weaned multiparous and primiparous beef cows', 'Rodolfo Ungerfeld, María José Hötzel, A. Scarsi, G. Quintans', 2011, 'animal', '10.1017/s1751731111000334', 'https://doi.org/10.1017/s1751731111000334', 'https://www.sciencedirect.com/science/article/pii/S1751731111000334/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Early weaning is used to advance postpartum ovulation in beef cows, but triggers a stress response, affecting cows'' and calves'' welfare. Our aim was to compare the response to early weaning in multiparous and primiparous cows. Seventy-one days after birth, calves from 14 primiparous and 11 multiparous cows were weaned. Since birth, cow''s body weight (BW), body condition (BC), milk yield and calves'' BW were recorded. Basophil/neutrophil relationship, total protein and albumin concentrations were measured before and after weaning. The distance between each cow and its calf before weaning, as well as main behaviors of the cows before and after weaning were recorded using 10 min scan sampling. BW and BC were greater in multiparous than in primiparous cows (P < 0.0001 for both). There was an interaction between parity (P = 0.004) and gender of the calf (P = 0.007): both BW and BC were greater in multiparous than primiparous cows, but multiparous cows with male calves had lower BW and BC than those with females (P < 0.001 for both variables). Milk yield was greater in multiparous than in primiparous cows (P = 0.02), and there was an interaction, with greatest milk yield in multiparous cows that calved males (P = 0.02). Total protein blood concentration increased with time (P < 0.0001), similarly in both groups. Albumin concentration profiles were similar despite parity, and decreased since 10 days after weaning (P < 0.0001). Basophil/neutrophil ratio was not affected by parity, and increased the day of weaning, remaining high until day 10 (P < 0.05). Frequency of standing decreased during the 2 days after weaning, with a greater decrease in multiparous than in primiparous cows (P < 0.0001). Pacing increased after weaning (P = 0.001), but increased significantly more in multiparous cows (P = 0.006), with a significant time after weaning by parity interaction (P = 0.01) reflected in greater frequencies in multiparous cows in the 2 days. Walking increased with time (P < 0.0001), and was more frequent in primiparous cows (P = 0.008). Ruminating, which was less frequent in multiparous cows (P = 0.014), decreased and remained low during the 3 days following weaning (P < 0.0001), but there was a significant time by parity interaction (P < 0.0001). The frequency of vocalizations increased dramatically after weaning (P < 0.0001), and was greater in multiparous cows (P = 0.006), and decreased more slowly during the 2nd and 3rd days after weaning (P = 0.005) in these animals. In conclusion, behavioral changes induced by weaning were greater in multiparous than primiparous cows, indicating a more intense response to cow-calf separation in the multiparous animals.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('58874fe0-1062-4a6a-849d-2a2c8ff0ed59', '4468519e-45b7-42e3-a131-b2181808b714', 'Behavioral and physiological responses of young horses to different weaning protocols: A pilot study', 'Regina Erber, Manuela Wulf, Sandra Rose-Meierhöfer, Mareike Becker-Birck, Erich Möstl, Jörg E Aurich, Gundula Hoffmann, Christine Aurich', 2011, 'Stress', '10.3109/10253890.2011.606855', 'https://doi.org/10.3109/10253890.2011.606855', 'https://www.tandfonline.com/doi/pdf/10.3109/10253890.2011.606855?needAccess=true&role=button', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7c8cafa9-15f4-4eaf-b5e2-a6711bffdb7b', '4468519e-45b7-42e3-a131-b2181808b714', 'Behaviour response to two-step weaning is diminished in beef calves previously submitted to temporary weaning', 'Hotzel, M.J.; Quintans, G.; Ungerfeld, R.', 2012, 'Livestock Science', '10.1016/j.livsci.2012.06.029', 'https://doi.org/10.1016/j.livsci.2012.06.029', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Subscription (Elsevier)', 'Uruguayan work showing that the behavioural benefit of two-step weaning is smaller in calves that have already been through a temporary weaning (suckling restriction earlier in lactation for cow rebreeding). Relevant if a herd already uses nose plates or temporary calf removal mid-season, because it means the second intervention has less left to improve.', '{weaning,two-stage,nose-flap,temporary-weaning,behaviour,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c04e938-10f0-4422-b9f4-2b6277055bbd', '4468519e-45b7-42e3-a131-b2181808b714', 'Behavioural responses of 6-month-old beef calves prevented from suckling: influence of dam''s milk yield', 'Hotzel, M.J.; Ungerfeld, R.; Quintans, G.', 2010, 'Animal Production Science 50:909-915', '10.1071/AN09136', 'https://doi.org/10.1071/AN09136', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Subscription (CSIRO Publishing)', 'Isolates the nutritional component of weaning stress by preventing suckling with nose flaps while leaving the pair together. Six-month-old beef calves prevented from nursing showed increased vocalisation and walking and reduced playing, ruminating and grazing, indicating that cessation of nursing contributes to weaning distress at this age independently of separation. Weaning distress appeared greater in calves suckling higher-yielding cows, but not when live weight was controlled. Relevant to the question of what stage 1 of two-stage weaning actually costs the calf.', '{weaning,two-stage,nose-flap,milk-yield,behaviour,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('208382ff-ab0e-4a2e-9cf1-71be2ddea7b2', '4468519e-45b7-42e3-a131-b2181808b714', 'Longitudinal study of humoral immunity to bovine coronavirus, virus shedding, and treatment for bovine respiratory disease in pre-weaned beef calves', 'Aspen M. Workman, L. A. Kuehn, T. G. McDaneld, Michael L. Clawson, John Dustin Loy', 2019, 'BMC Veterinary Research', '10.1186/s12917-019-1887-8', 'https://doi.org/10.1186/s12917-019-1887-8', 'https://bmcvetres.biomedcentral.com/counter/pdf/10.1186/s12917-019-1887-8', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'BACKGROUND: Bovine coronavirus (BCV) is associated with respiratory infections in cattle of all ages; however, a temporal study to evaluate the effect of BCV immunity on virus shedding and bovine respiratory disease (BRD) incidence in pre-weaned beef calves has not been reported. Thus, we report here a prospective study in three herds of crossbred beef calves (n = 817) with endemic BCV. Serial blood samples for measurement of serum anti-BCV antibody titers and nasal swabs for detection of BCV and other common viral and bacterial BRD pathogens were collected from all calves or subsets of calves at predetermined times from birth through weaning. The calves were monitored for BRD and those that developed signs of respiratory disease were sampled for diagnostic testing. To discover additional risk factors that could have influenced BRD development, sequence analysis of the BCV strain(s) circulating in each herd, and the prevalence of common opportunistic bacterial pathogens in the upper respiratory tract of sick and apparently healthy cattle were also evaluated. RESULTS: Two hundred forty-eight of the 817 study calves (30.4%) were treated for BRD prior to weaning; 246 of those were from a single herd involved in two outbreaks of BRD leading to mass treatment of all calves in that group. Molecular diagnostic testing found BCV and Histophilus somni in nasal swabs taken at the time of BRD treatment. Between herd analyses revealed anti-BCV serum antibody abundance did not associate with the incidence of BRD or BCV shedding, though these measurements may have been hindered by the long periods between sample collections. Analysis of the BCV spike gene hypervariable region revealed four polymorphisms in 15 isolates from the three herds, making strain variation unlikely to account for differences in treatment rates between herds. Persistent or recurrent shedding episodes of BCV occurred in some animals treated for BRD. CONCLUSION: Co-detection of BCV and H. somni at the time of the disease outbreak suggests that these pathogens contributed to disease pathogenesis. Developing appropriate control measures for respiratory BCV infections may help decrease the incidence of pre-weaning BRD. The role of antibodies in protection must still be further defined.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9f1edf55-5caa-4b1d-b33d-1497dc20f01e', '4468519e-45b7-42e3-a131-b2181808b714', 'Calf health from birth to weaning. I. General aspects of disease prevention', 'Ingrid Lorenz, John F. Mee, Bernadette Earley, Simon J. More', 2011, 'Irish Veterinary Journal', '10.1186/2046-0481-64-10', 'https://doi.org/10.1186/2046-0481-64-10', 'https://irishvetjournal.biomedcentral.com/counter/pdf/10.1186/2046-0481-64-10', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Calfhood diseases have a major impact on the economic viability of cattle operations. This is the first in a three part review series on calf health from birth to weaning, focusing on preventive measures. The review considers both pre- and periparturient management factors influencing calf health, colostrum management in beef and dairy calves and further nutrition and weaning in dairy calves.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0b02b85f-2f0d-498e-9e0c-09d95d974f0a', '4468519e-45b7-42e3-a131-b2181808b714', 'Calf health from birth to weaning. III. housing and management of calf pneumonia', 'Ingrid Lorenz, Bernadette Earley, John Gilmore, Ian Hogan, E. Kennedy, Simon J. More', 2011, 'Irish Veterinary Journal', '10.1186/2046-0481-64-14', 'https://doi.org/10.1186/2046-0481-64-14', 'https://irishvetjournal.biomedcentral.com/counter/pdf/10.1186/2046-0481-64-14', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Calfhood diseases have a major impact on the economic viability of cattle operations. A three part review series has been developed focusing on calf health from birth to weaning. In this paper, the last of the three part series, we review disease prevention and management with particular reference to pneumonia, focusing primarily on the pre-weaned calf. Pneumonia in recently weaned suckler calves is also considered, where the key risk factors are related to the time of weaning. Weaning of the suckler calf is often combined with additional stressors including a change in nutrition, environmental change, transport and painful husbandry procedures (castration, dehorning). The reduction of the cumulative effects of these multiple stressors around the time of weaning together with vaccination programmes (preconditioning) can reduce subsequent morbidity and mortality in the feedlot. In most studies, calves housed individually and calves housed outdoors with shelter, are associated with decreased risk of disease. Even though it poses greater management challenges, successful group housing of calves is possible. Special emphasis should be given to equal age groups and to keeping groups stable once they are formed. The management of pneumonia in calves is reliant on a sound understanding of aetiology, relevant risk factors, and of effective approaches to diagnosis and treatment. Early signs of pneumonia include increased respiratory rate and fever, followed by depression. The single most important factor determining the success of therapy in calves with pneumonia is early onset of treatment, and subsequent adequate duration of treatment. The efficacy and economical viability of vaccination against respiratory disease in calves remains unclear.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3894cfb6-e4a0-4a8b-807b-eabd396d82cf', '4468519e-45b7-42e3-a131-b2181808b714', 'Case study: effects of low-stress weaning on calf growth performance and carcass characteristics', 'Erin R Gubbels, John R. Jaeger, R. R. Salverson, K. M. Cammack, Judson Kyle Grubbs, K. R. Underwood, K. C. Olson, Amanda D. Blair', 2023, 'Translational Animal Science', '10.1093/tas/txad015', 'https://doi.org/10.1093/tas/txad015', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC9951182/pdf/txad015.pdf', NULL, NULL, 6, NULL, 'northern_plains', 3, 'cc-by', 'Abstract The objective of this study was to compare the influence of two low-stress weaning methods with conventional weaning on post-weaning performance and carcass characteristics of beef steers. Single-sourced steer calves (n = 89) were stratified by body weight (BW) and dam age into three groups in a completely randomized design (n = 29 or 30 steers/treatment): ABRUPT (calves isolated from dams on the day of weaning), FENCE (calves separated from dams via a fence for 7 d prior to completely weaning), and NOSE (nose-flap inserted and calves remained with dams for 7 d prior to completely weaning). At day +7 post-weaning, calves were transported to a commercial feedlot where they received standard step-up and finishing rations typical for a Northern Plains feedlot. BWs were recorded in study day −7 (PreTreat), 0 (Weaning), 7 (PostWean), 26 (Receiving), 175 (Ultrasound), and 238 or 268 (Final), and average daily gains (ADG) were calculated for each time period. Blood samples were collected via coccygeal venipuncture at d −7 (PreTreat), 0 (Weaning), and +7 (PostWean) from a subsample of calves (n = 10 per treatment) and analyzed for haptoglobin (acute-phase stress protein) concentrations using a bovine haptoglobin ELISA kit. On day 175, ultrasound fat thickness and intramuscular fat were determined and utilized to project marketing dates when steers reached 1.27 cm of backfat (day 238 or 268). Carcass measurements were recorded at the time of harvest. The weaning method interacted (P < 0.01) with a time period for ADG and BW. Calf ADG was greater (P < 0.01) in the NOSE treatment during PreTreat to Weaning than ABRUPT or FENCE. In the Weaning to PostWean period, the FENCE calves had greater (P < 0.01) ADG than ABRUPT and NOSE. During the Postwean to Receiving period ADG was greater (P < 0.04) for ABRUPT compared to FENCE and NOSE. Calf ADG was similar (P > 0.05) among treatments for the remainder of the feeding period. Calf BW did not differ among treatments (P > 0.05) at all times of weighing. Haptoglobin was undetectable in all samples except two samples collected on day −7. The weaning method did not influence (P > 0.05) carcass measurements. Collectively these data suggest low-stress weaning methods do not significantly improve post-weaning growth performance or carcass characteristics compared to using conventional methods despite minor, short-term alterations in ADG during the weaning period.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35b8e4f8-7245-4f27-af93-5d20c110627e', '4468519e-45b7-42e3-a131-b2181808b714', 'Characterisation of physiological and immunological responses in beef cows to abrupt weaning and subsequent housing', 'Lynch, E.M.; Earley, B.; McGee, M.; Doyle, S.', 2010, 'BMC Veterinary Research 6:37', '10.1186/1746-6148-6-37', 'https://bmcvetres.biomedcentral.com/articles/10.1186/1746-6148-6-37', 'https://bmcvetres.biomedcentral.com/counter/pdf/10.1186/1746-6148-6-37.pdf', NULL, NULL, 8, NULL, 'other', 3, 'CC BY 2.0', 'Irish Teagasc work on the COW side of abrupt weaning, measuring physiological and immunological responses to weaning followed by housing. Part of the small set of studies that document what abrupt weaning does to the dam rather than the calf - worth having because the economic case for weaning is usually made on cow body condition, and because Mac et al. 2024 found fenceline weaning cost cows weight. Free full text and PDF.', '{weaning,abrupt,cows,immunology,physiology,housing,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('019f276c-9494-4661-97dc-356d80cc542f', '4468519e-45b7-42e3-a131-b2181808b714', 'Comparison of behavioural indicators of acute pain and stress during and after three methods of handling and restraint for pre-weaned beef calves', 'Lindsey Arkangel, M. Claire Windeyer, Christy Goldhawk, Edmond Anthony Pajor', 2025, 'Applied Animal Behaviour Science', '10.1016/j.applanim.2025.106623', 'https://doi.org/10.1016/j.applanim.2025.106623', 'https://www.sciencedirect.com/science/article/pii/S0168159125001212/pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by-nc-nd', 'Beef calves in western Canada are processed at 6-12 weeks of age, when they are individually handled and restrained to conduct various husbandry procedures. Best practice recommendations for safeguarding animal welfare during husbandry procedures suggest using calm, quiet handling techniques and proper restraint, but little is known about methods of “proper restraint”. The most common methods for handling and restraining calves in western Canada are roping and wrestling (RW), roping and Nord fork (RNF), and using a tilt table (TT). Thus, the objective was to compare the effects of these 3 methods on behavioural indicators of pain and stress responses. A total of 117 beef bull calves were assigned to 3 groups (RW, RNF, or TT), consisting of 39 calves each (30 processed calves, 9 control calves). Control calves were handled and restrained according to their assigned group but did not undergo any processing procedures. Video recordings were used to quantify duration of handling and restraint, and behaviours associated with active stress or pain responses. Statistical analysis of these variables used the Kruskal-Wallis H-test, while a Fisher’s exact test was used to analyze visual eye white (VEW) and gait scores. All results are reported in the format of medians and interquartile range (i.e., [75th percentile – 25th percentile]). During processing, vocalization rate was highest for RNF calves (RNF: 11.7 [12.3]; RW: 5.0 [7.8]; TT: 1.6 [7.8] count/min; P < 0.05) and struggling rate was highest for TT calves (TT: 4.6 [4.0]; RW: 2.3 [2.6]; RNF: 1.9 [2.7]; count/min; P < 0.05). There was no relationship between VEW or handler score, and method of restraint. Both durations of handling and restraint were highest for TT calves (handling= TT: 23.4s [19.7]; RNF: 18.1s [3.6]; RW: 14.7s [3.5]; restraint = TT: 78.4s [7.4]; RW: 67.5s [16.8]; RNF: 64.8s [22.7]; P < 0.05). Upon release, RNF calves had a higher occurrence of running upon release from restraint compared to the other groups (P < 0.05). After processing, foot stomping rate differed among groups and was highest for RNF calves, followed by RW calves, then TT calves (RNF: 1.9 [2.3]; RW: 1.0 [0.9]; TT: 0.5 [0.5]; P < 0.01). No injuries were observed in any calves. While no method elicited consistent behavioural responses of active coping with pain and stress across multiple indicators to indicate a clearly preferable or detrimental method for animal welfare, variation in individual indicators supports further investigation into specific welfare considerations.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d93a53b-e8bf-48f6-a123-4ca9f4233842', '4468519e-45b7-42e3-a131-b2181808b714', 'Comparison of effects of four weaning methods on health and performance of beef calves', 'Jared D. Taylor, J.N. Gilliam, G.L. Mourer, C. Stansberry', 2019, 'animal', '10.1017/s1751731119001228', 'https://doi.org/10.1017/s1751731119001228', 'https://www.sciencedirect.com/science/article/pii/S1751731119001228/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Weaning of beef calves is a stressful event that negatively impacts health and performance. A variety of interventions have been proposed to reduce stress and improve gains following weaning. This study used 288 7- to 8-month-old calves from two separate locations, to examine four different weaning strategies, as well as the impact of shipment. Calves were blocked by weight and sex, and then randomly assigned to one of four treatments: abrupt weaning (AW), where calves were separated from the dam on day 0 (D0) and allowed no further contact with the dam; fence line (FL), where calves were weaned on D0 but had fence line contact with dams for 7 days; nose flap (NF), where on day -6 calves received a nose flap that interferes with suckling, then had the flap removed and were weaned from the dam on D0; and intermittent separation (SEP), where calves were removed from dams for 24-h intervals on day -13 and day -6, then weaned on D0, but allowed fence line contact with the dam for 7 days. Each treatment group was further divided into two subgroups, one of which was shipped early (D0 for AW, day 7 for others) or shipped later (day 28). Body weight and sickness were recorded for all groups. Results showed a negative impact on gain for early shipping compared to later shipping, and poorer gain in AW calves than most other treatments. Results of the analyses of morbidity were inconclusive. This study found that delayed shipment following FL weaning improves performance under common management conditions for the US cow-calf industry.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ec62be5-531e-4358-b187-e01a4d6884da', '4468519e-45b7-42e3-a131-b2181808b714', 'Creep Feeding Beef Calves (NebGuide G2077)', 'University of Nebraska-Lincoln Extension', 2024, 'Nebraska Extension', NULL, 'https://extensionpubs.unl.edu/publication/g2077', 'https://extensionpubs.unl.edu/publication/g2077/na/pdf/view', NULL, NULL, 4, NULL, 'northern_plains', 4, 'Nebraska Extension publication, freely distributed', 'The numbers needed to decide whether creep feeding before weaning is worth it, updated September 2024. Feed conversion for high-energy creep is about 8 pounds of creep dry matter per pound of added gain, with a range of 6.8:1 to 15:1; added average daily gain from high-energy creep is 0.20 to 0.30 lb/d; limit-fed (intake-restricted) creep converts at about 4 pounds of feed per pound of gain. Includes a worked partial budget using an 8:1 conversion, and the warning that lighter calves have a price-per-pound advantage so added weight is sold into a price slide. Nutrient framework: a 220 lb calf gaining 2.0 lb/d must consume about 7 lb of total dry matter (milk, forage and creep), and the ration needs to supply 1.32 lb protein and 5.0 lb TDN per day. Also covers creep feeding replacement heifers and the risk of impairing later milk production if heifers are fed high-energy creep before three months of age. The practical reading for a weaning programme: creep-feed for bunk familiarity, not for weaning weight.', '{weaning,creep-feeding,economics,feed-conversion,extension,bunk-training,weaning-weight}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.792335+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('17d221c7-5304-4859-87eb-a008fafe30d7', '4468519e-45b7-42e3-a131-b2181808b714', 'Development and application of a scoring system for septum injuries in beef calves with and without a nose flap', 'Kirk, A.A.; Tucker, C.B.', 2023, 'Translational Animal Science 7:txad075', '10.1093/tas/txad075', 'https://doi.org/10.1093/tas/txad075', 'https://escholarship.org/content/qt9zn20066/qt9zn20066.pdf?t=s0k0mw', NULL, NULL, NULL, NULL, 'other', 5, 'CC BY 4.0', 'The properly controlled study of nose-flap injury, and the reason a 2026 operation should not treat two-stage weaning as automatically low-stress. 82 Angus and Angus-Hereford crossbred calves at the UC Davis Sierra Foothill Research and Extension Center, 205 +/- 19 days old and 247 +/- 29 kg, randomly assigned to Flap (n=41, QuietWean plastic flaps from JDA Livestock Innovations, Saskatoon) or No Flap (n=41) and balanced for weight and sex. Critically, ALL calves were fenceline-weaned under identical rangeland conditions so that environmental injury risk was equalised - something earlier injury studies lacked. Nostrils were photographed before insertion, at removal after 7 days, and 6 days after removal, and scored for damage, impression and blood with 97%, 91% and 100% intra-observer agreement. Results: 32% of Flap calves lost the flap before day 7; no No-Flap calf was injured; every calf that kept a flap for 7 days had damage and impressions in at least one nostril and 86% had blood present immediately at removal (P<=0.001 vs No Flap); six days after removal 100% still had visible damage, 64% impressions and 29% blood. Measured septum width was 39 +/- 2 mm. The paper also tabulates flap loss across the literature: under 5% in Haley 2005 and Taylor 2020 versus 24% in Lambertz 2015 and 27% in Valente 2022.', '{weaning,two-stage,nose-flap,nasal-injury,welfare,retention,scoring-system,controlled,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf112fb3-523a-4570-9600-70c32dd02944', '4468519e-45b7-42e3-a131-b2181808b714', 'Early weaning in pregnant Nelore cows as a foetal programming strategy: 1. Effects on cow-calf and backgrounding offspring growth, and skeletal muscle gene expression in beef cattle', 'M.S.P. Carlis, G. Abitante, T.K. Nishimura, T.R.S. Gionbelli, J.M. Oliveira, C.R. Dahlen, G.D.R. Zamudio, S.L. Silva', 2026, 'Animal', '10.1016/j.animal.2025.101735', 'https://doi.org/10.1016/j.animal.2025.101735', 'http://www.sciencedirect.com/science/article/pii/S1751731125003180', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'In tropical beef systems, the dry season coincides with mid-to-late gestation, creating a nutritional conflict between lactation and foetal development. Early weaning (EW) mitigates this stress, but its impact on Bos indicus offspring muscle development via foetal programming remains unclear. This study evaluated the effects of weaning strategy and dam parity on maternal performance and offspring postnatal growth and skeletal muscle gene expression. A randomised 2 × 2 factorial design was utilised with 58 Nelore cow-calf pairs. The treatments were composed of early (EW; 150 d lactation) versus conventional weaning (CW; 240 d lactation) and dam parity (multiparous (MP) or secundiparous (SP)). The data were analysed considering the animal as an experimental unit by using the Mixed procedure, considering the WS, DP as a fixed effect, and the two-way interaction in the model. Maternal BW and body condition score (BCS) were monitored during gestation. Offspring growth was assessed from birth to 18 months, and Longissimus thoracis mRNA abundance was analysed at 5, 13, and 18 months. During gestation, MP dams had greater BCS (P = 0.01) and BW (P < 0.001) compared to SP dams. During the dam’s gestation, EW and MP dams had greater BCS (P < 0.001), BW (P < 0.001), non-pregnant empty BW (P = 0.002) and pregnant compound (P = 0.034) compared to CW and SP dams (P < 0.001). The EW calves increased birth BW (P = 0.054), weaning BW (P = 0.034), and average daily gain (ADG; P = 0.015) compared to CW calves. Calves born to MP dams increased weaning BW (P = 0.005) and ADG (P = 0.008) compared to SP calves. There was a WS × DP interaction for the mRNA abundance of MTOR (P = 0.011) and EIF4E (0.017), where EW-SP calves showed smaller mRNA abundance compared to CW-SP calves at 18 months. The CW calves showed greater mRNA abundance of PAX7 (P = 0.05) at weaning, TRIM63 (P = 0.006) at 13 months of age (P = 0.006), PAX7 (P = 0.04), NFB1 (P = 0.01) and IGRF1R (P = 0.05) at 18 months of age compared to EW calves. In conclusion, early weaning effectively improves maternal nutritional status during gestation, which positively programmes offspring’s prenatal and pre-weaning growth. Furthermore, this strategy induces long-term alterations in the expression of genes related to muscle hypertrophy and atrophy, indicating that alleviating maternal nutritional stress via early weaning can modulate the physiological potential of the progeny.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('805f7ef4-0e6c-42a4-9cb9-0327a54c3d5f', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of a trainer cow on health, behavior, and performance of newly weaned beef calves', 'Gibb, D.J.; Schwartzkopf-Genswein, K.S.; Stookey, J.M.; McKinnon, J.J.; Godson, D.L.; Wiedmeier, R.D.; McAllister, T.A.', 2000, 'Journal of Animal Science 78:1716-1725', '10.2527/2000.7871716x', 'https://doi.org/10.2527/2000.7871716x', NULL, NULL, NULL, NULL, NULL, 'prairies', 4, 'Subscription (American Society of Animal Science / Oxford University Press)', 'A Canadian prairie trial on the one weaning-period intervention the Kansas State work identified as mattering most: teaching freshly weaned calves to eat from a bunk. Measured health, behaviour and performance effects of putting a trainer cow with newly weaned beef calves. Read alongside Loerch & Fluharty (2000) on trainer animals in feedlots and the Enriquez et al. 2011 review''s caution that introducing unfamiliar animals may itself be a stressor and that the few trials found no health or growth benefit.', '{weaning,trainer-cow,bunk-training,health,behaviour,canadian,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('12f46f0c-8e74-429c-8b53-e7a08d232f37', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of abrupt weaning at housing on leukocyte distribution, functional activity of neutrophils, and acute phase protein response of beef calves', 'Lynch, E.M.; Earley, B.; McGee, M.; Doyle, S.', 2010, 'BMC Veterinary Research 6:39', '10.1186/1746-6148-6-39', 'https://bmcvetres.biomedcentral.com/articles/10.1186/1746-6148-6-39', 'https://bmcvetres.biomedcentral.com/counter/pdf/10.1186/1746-6148-6-39.pdf', NULL, NULL, 9, NULL, 'other', 3, 'CC BY 2.0', 'The companion calf study to Lynch et al. 6:37, documenting leukocyte redistribution, neutrophil function and the acute-phase protein response when calves are abruptly weaned at housing. Useful as the mechanistic baseline against which to read the repeated failures of cortisol and haptoglobin to separate weaning methods in North American field trials (Mac 2024, Gubbels 2023, Freeman 2020, Landa 2011): the response exists and is measurable under a strong challenge, but it is not a reliable discriminator between methods in a healthy pasture herd. Free full text and PDF.', '{weaning,abrupt,immunology,acute-phase-protein,neutrophil,physiology,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46202a97-7f39-457c-8f3d-3f152378448c', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of castration timing and weaning strategy on the taxonomic and functional profile of ruminal bacteria and archaea of beef calves', 'Gerardo R. Diaz, Tara N. Gaire, Peter Ferm, Lacey Case, L.S. Caixeta, Timothy Goldsmith, Joe Armstrong, Noelle Robertson Noyes', 2023, 'Animal Microbiome', '10.1186/s42523-023-00284-2', 'https://doi.org/10.1186/s42523-023-00284-2', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10691087/pdf/42523_2023_Article_284.pdf', NULL, NULL, 20, NULL, 'northern_plains', 3, 'cc-by', 'BACKGROUND: Beef cattle experience several management challenges across their lifecycle. Castration and weaning, two major interventions in the early life of beef cattle, can have a substantial impact on animal performance. Despite the key role of the rumen microbiome on productive traits of beef cattle, the effect of castration timing and weaning strategy on this microbial community has not been formally described. We assessed the effect of four castration time windows (at birth, turnout, pre-weaning and weaning) and two weaning strategies (fence-line and truck transportation) on the rumen microbiome in a randomized controlled study with 32 male calves across 3 collection days (i.e., time points). Ruminal fluid samples were submitted to shotgun metagenomic sequencing and changes in the taxonomic (microbiota) and functional profile (metagenome) of the rumen microbiome were described. RESULTS: Using a comprehensive yet stringent taxonomic classification approach, we identified 10,238 unique taxa classified under 40 bacterial and 7 archaeal phyla across all samples. Castration timing had a limited long-term impact on the rumen microbiota and was not associated with changes in alpha and beta diversity. The interaction of collection day and weaning strategy was associated with changes in the rumen microbiota, which experienced a significant decrease in alpha diversity and shifts in beta diversity within 48 h post-weaning, especially in calves abruptly weaned by truck transportation. Calves weaned using a fence-line weaning strategy had lower relative abundance of Bacteroides, Lachnospira, Fibrobacter and Ruminococcus genera compared to calves weaned by truck transportation. Some genes involved in the hydrogenotrophic methanogenesis pathway (fwdB and fwdF) had higher relative abundance in fence-line-weaned calves post-weaning. The antimicrobial resistance gene tetW consistently represented more than 50% of the resistome across time, weaning and castration groups, without significant changes in relative abundance. CONCLUSIONS: Within the context of this study, castration timing had limited long-term effects on the rumen microbiota, while weaning strategy had short-term effects on the rumen microbiota and methane-associated metagenome, but not on the rumen resistome.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('26a9d4c1-f6b0-4e62-b2fb-c1156e67faf4', '4468519e-45b7-42e3-a131-b2181808b714', 'Multiple administrations of bovine-appeasing substance during a 42-d preconditioning program followed by feedlot receiving and its effects on physiologic, health, and performance responses of feeder cattle', 'Kvamme K, Marques RS, Alves Cruz V, Limede Cintra A, Ogg MA, McCoski SR, Posbergh CJ, Bradbery AN', 2024, 'Journal of animal science', '10.1093/jas/skae151', 'https://doi.org/10.1093/jas/skae151', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11185958.1/PMC11185958.1.pdf', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'This experiment evaluated the effects of multiple bovine-appeasing substance (BAS) administration during a 42-d preconditioning program followed by a feedlot receiving period on productivity, health, and physiological variables of feeder cattle. Ninety calves were weaned, weighed, loaded into a livestock trailer, transported for 70 km, and unloaded at the Bozeman Agricultural Research and Teaching Farm for a 42-d preconditioning program. Upon arrival, calf body weight (BW) was recorded again, and both pre- and post-transport BWs were averaged and used as calf weaning initial BW. Calves were ranked by BW, sex, and age in a completely randomized design and assigned to receive 1) multiple administrations of BAS at weaning (day 0), days 14, 28, and before transport and feedlot entry (day 42; BAS; RSEA Group, Quartier Salignan, France; n = 9 pens/treatment), or 2) placebo (diethylene glycol monoethyl ether; CON; n = 9 pens/treatment). Treatments (5 mL) were applied to the nuchal skin area of each animal during the preconditioning period. Calves within treatment groups were ranked again by initial BW, sex, and age, in a manner that pens have similar initial BW, age, and three steers and two heifers and allocated to 1 of the18 drylot pens. On day 42, calves were combined within the treatment group, loaded into two different single double-deck commercial livestock trailers, and transported for 1,000 km (approximately 16 h). Upon arrival (day 43), calves were unloaded at the same feedyard. Blood samples were collected on days 0, 3, 7, 14, 21, 28, 42, 43, 46, 50, 57, 64, and 90. Average daily gain, final BW, and feed efficiency did not differ (P > 0.52) between BAS and CON calves in the preconditioning and receiving phases. A treatment × day interaction was detected (P < 0.001) for plasma haptoglobin concentrations, which was greater (P < 0.01) in CON on days 3 and 7 vs. BAS calves. During the preconditioning phase, serum NEFA concentration was reduced (P < 0.01) in BAS on day 3 compared with CON calves. A treatment × day interaction was detected (P = 0.001) for exit velocity, which was greater (P < 0.001) for CON vs. BAS calves on days 3, 7, 14, and 21 during the preconditioning phase and on day 46 of the receiving phase. Therefore, Applications of BAS reduced immunological responses and exit velocity associated with stress caused by management practices, but did not improve performance during the preconditioning and receiving phases.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e562e600-0737-4818-ac4f-b476cc101146', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of Feeding Selenium-Fertilized Alfalfa Hay on Performance of Weaned Beef Calves', 'Jean A. Hall, Gerd Bobe, Janice K. Hunter, William R. Vorachek, Whitney C. Stewart, Jorge A. Vanegas, Charles T. Estill, Wayne D. Mosher', 2013, 'PLoS ONE', '10.1371/journal.pone.0058188', 'https://doi.org/10.1371/journal.pone.0058188', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0058188&type=printable', NULL, NULL, 8, NULL, 'other', 1, 'cc-by', 'Selenium (Se) is an essential micronutrient in cattle, and Se-deficiency can affect morbidity and mortality. Calves may have greater Se requirements during periods of stress, such as during the transitional period between weaning and movement to a feedlot. Previously, we showed that feeding Se-fertilized forage increases whole-blood (WB) Se concentrations in mature beef cows. Our current objective was to test whether feeding Se-fertilized forage increases WB-Se concentrations and performance in weaned beef calves. Recently weaned beef calves (n = 60) were blocked by body weight, randomly assigned to 4 groups, and fed an alfalfa hay based diet for 7 wk, which was harvested from fields fertilized with sodium-selenate at a rate of 0, 22.5, 45.0, or 89.9 g Se/ha. Blood samples were collected weekly and analyzed for WB-Se concentrations. Body weight and health status of calves were monitored during the 7-wk feeding trial. Increasing application rates of Se fertilizer resulted in increased alfalfa hay Se content for that cutting of alfalfa (0.07, 0.95, 1.55, 3.26 mg Se/kg dry matter for Se application rates of 0, 22.5, 45.0, or 89.9 g Se/ha, respectively). Feeding Se-fertilized alfalfa hay during the 7-wk preconditioning period increased WB-Se concentrations (P Linear<0.001) and body weights (P Linear = 0.002) depending upon the Se-application rate. Based upon our results we suggest that soil-Se fertilization is a potential management tool to improve Se-status and performance in weaned calves in areas with low soil-Se concentrations.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('64ac7341-9531-460d-902c-e2fed1a5975a', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of fence-line or drylot weaning on the health and performance of beef calves during weaning, receiving, and finishing', 'Bailey, E.A.; Jaeger, J.R.; Waggoner, J.W.; Preedy, G.W.; Pacheco, L.A.; Olson, K.C.', 2016, 'The Professional Animal Scientist 32(2):220-228', '10.15232/pas.2015-01455', 'https://www.sciencedirect.com/science/article/pii/S1080744616000292', NULL, NULL, NULL, NULL, NULL, 'northern_plains', 4, 'Subscription (Elsevier)', 'The peer-reviewed version of the Kansas State fence-line versus drylot preconditioning work, carried through finishing. Drylot calves were heavier at the end of the 28-day weaning period and gained faster than pasture-weaned calves through day 60 in the feedlot, with no health difference. Carcass traits including yield grade, marbling score and the percentage grading USDA Choice or higher did not differ among treatments. This is the paper that reports the fenceline specification cited throughout: minimum frontage 200 m, four-strand barbed-wire fence with the bottom two wires electrified. The free Cattlemen''s Day report (Bailey et al. 2013) carries the same data for the weaning and receiving phases.', '{weaning,fenceline,drylot,preconditioning,fence-spec,carcass,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e22988c7-bbf8-4695-9531-b665566c2f87', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of post-weaning management practices on physiological and immunological responses of weaned beef calves', 'Eilish M Lynch, Mark McGee, Seán Doyle, Bernadette Earley', 2011, 'Maynooth University ePrints and eTheses Archive (Maynooth University)', NULL, 'http://hdl.handle.net/11019/65', 'http://hdl.handle.net/11019/65', NULL, NULL, 14, NULL, 'other', 1, 'cc-by-nc-sa', 'The objectives were: i) to investigate the physiological and immunological responses\nof previously grazed, abruptly weaned beef calves that were then either housed (H)\nand offered a diet of grass silage ad libitum plus concentrate or returned to familiar\npasture (P) (Phase I), and ii) to examine the effect of subsequent housing (35 days\npost-weaning) on these responses in P calves compared with the H calves, which were\nacclimated to housing (Phase II). Rectal temperature was recorded and jugular blood\nwas collected on days 0 (weaning), 2, 7, 14, 21, 28 and 35 (Phase I) and on days 0\n(housing of P), 2, 7, 14, and 21 (Phase II). There was a treatment × sampling time\ninteraction (P<0.05) for rectal temperature, fibrinogen concentration, total leukocyte\nand lymphocyte number, and phytohaemagglutinin-induced interferon-γ production\nduring Phase I, with H calves having higher (P<0.05) rectal temperature and fibrinogen\nconcentrations on day 7, lower total leukocyte and lymphocyte number on days\n7 to 35 and days 2 to 28, respectively, and reduced interferon-γ production on day\n7 compared with P calves. Neutrophilia (P<0.05) was present in P calves on days 2\nand 7 post-weaning. In Phase II, total leukocyte and neutrophil numbers increased\n(P<0.05), whereas lymphocyte number declined on day 2 relative to values on day 0\nof Phase II. In conclusion, deferring housing at the time of weaning resulted in a\nless marked stress response in beef calves compared with the traditional combined\npractice of weaning and simultaneous housing, however these changes were minimal suggesting that the overall health and welfare of beef calves was not compromised by\nabrupt weaning and simultaneous housing.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8420bd46-ab7c-4621-b282-c793da88ccae', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of pre-weaning concentrate supplementation on peripheral distribution of leukocytes, functional activity of neutrophils, acute phase protein and behavioural responses of abruptly weaned and housed beef calves', 'Eilish M Lynch, Mark McGee, Seán Doyle, Bernadette Earley', 2012, 'BMC Veterinary Research', '10.1186/1746-6148-8-1', 'https://doi.org/10.1186/1746-6148-8-1', 'https://bmcvetres.biomedcentral.com/counter/pdf/10.1186/1746-6148-8-1', NULL, NULL, 11, NULL, 'other', 1, 'cc-by', 'BACKGROUND: The effect of pre-weaning concentrate supplementation on peripheral distribution of leukocytes, functional activity of neutrophils, acute phase protein response, metabolic and behavioural response, and performance of abruptly weaned and housed beef calves was investigated. Calves were grazed with their dams until the end of the grazing season when they were weaned and housed (day (d) 0) in a concrete slatted floor shed, and offered grass silage ad libitum plus supplementary concentrates. Twenty-six days prior to weaning and housing, 20 singled suckled, pure-bred Simmental male (non-castrated), (n = 10, m) and female (n = 10, f) calves were assigned to one of two treatments (i) concentrate supplement (CS: n = 10 (5 m and 5 f), mean age (s.d.) 201 (12.8) d, mean weight (s.d.) 258 (20.2) kg) or (ii) no concentrate supplement (controls) (NCS: n = 10, (5 m and 5 f), mean age (s.d.) 201 (13.4) d, mean weight (s.d.) 257 (19.6) kg) pre-weaning. RESULTS: There was a treatment × sampling time interaction (P < 0.05) for percentage CD4+ and WC1+ (γδ T cells) lymphocytes and concentration of plasma globulin. On d 2, percentage CD4+ lymphocytes decreased (P < 0.001) in both treatments. Subsequently on d 7, percentage of CD4+ lymphocytes increased (P < 0.01) in CS compared with d 0, whereas percentage of CD4+ lymphocytes in NCS did not differ (P > 0.05) from d 0. On d 2, WC1+ lymphocytes decreased (P < 0.05) in both treatments but the decrease was greater (P <0.05) in NCS than CS. Subsequently, percentages did not differ (P > 0.05) from pre-weaning baseline. On d 2, the increase in concentration of globulin was greater (P < 0.05) in CS compared with NCS, and subsequently there was no difference between treatments. Pre-weaning ADG was 1.07 (s.e.m.) (0.26) kg and 0.99 (s.e.m.) (0.26) kg for CS and NCS, respectively. Post-weaning, CS calves spent more time lying compared with NCS calves. CONCLUSIONS: Calves supplemented with concentrate prior to weaning had a lesser reduction in WC1+ lymphocytes, increased percentage CD4+ lymphocytes and concentration of total protein, and spent more time lying post-weaning, compared with non-supplemented calves.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b001f3d-15d3-4788-a536-17c1b9ff78ad', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of temporary weaning and creep feeding on calf growth and the reproductive efficiency of their Hereford dams', 'Cruz, R.S.; Barbieri, I.; Olmos, V.M.; Montossi, F.; Vinoles, C.', 2022, 'Animal Bioscience', '10.5713/ab.21.0384', 'https://www.animbiosci.org/journal/view.php?doi=10.5713/ab.21.0384', 'https://www.animbiosci.org/upload/pdf/ab-21-0384.pdf', NULL, NULL, 11, NULL, 'other', 3, 'CC BY-NC 4.0', 'One of the few freely available papers that measures a weaning-type intervention against BOTH calf growth and dam reproductive efficiency, which is the real trade-off on a cow-calf operation. Temporary weaning (suckling interruption) and creep feeding in Hereford dams in Uruguay. Useful for the cow-condition-versus-weaning-weight question, where measured Canadian prairie data is essentially absent and the available evidence is US Great Plains early-weaning trials plus Alberta and Saskatchewan extension advice.', '{weaning,temporary-weaning,creep-feeding,cow-reproduction,dam-body-condition,weaning-weight,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3071ce83-c4b8-4cae-97a6-2532dd7451cc', '4468519e-45b7-42e3-a131-b2181808b714', 'Effect of Vaccination and Weaning Timing on Backgrounding Morbidity in Preconditioned Beef Feeder Calves', 'Brad J. White, Sara McReynolds, Dan R. Goehl, David G. Renter', 2008, 'The Bovine Practitioner', '10.21423/bovine-vol42no2p111-116', 'https://doi.org/10.21423/bovine-vol42no2p111-116', 'https://bovine-ojs-tamu.tdl.org/bovine/article/download/47/7650', NULL, NULL, 6, NULL, 'canada', 3, 'cc-by-sa', 'Bovine respiratory disease is the most common illness in post-weaned beef calves, and numerous pre-conditioning programs have been designed to mitigate the impact of this disease syndrome. Preconditioning programs rely on proper implementation of tools, including vaccination and weaning, to prepare the calf to successfully overcome disease challenges. Our objective was to determine whether backgrounding morbidity was associated with the timing of previous vaccinations and the number of days weaned prior to commingling of beef feeder calves. Data were procured over a six-year period from 85 producers that preconditioned calves and placed them in a commingled backgrounding lot for approximately three months. Generalized linear mixed models were utilized to assess the impact of the number of days between first and second viral vaccinations, number of days between the final viral vaccination and commingling and the number of days weaned prior to commingling. Hypothesis testing was performed using P <0.10 due to the relatively small sample size when year and origin farm were considered. Morbidity during the backgrounding phase was significantly higher ( P <0.10) when the time between initial and booster vaccination was less than 14 days. No morbidity differences were found based on weaning time or the proximity of the final vaccination to commingling. Our results illustrate that the timing of vaccinations influences health outcomes of preconditioning programs, and that further research is necessary to provide definitive recommendations regarding timing of vaccination and weaning.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37a06050-a445-4ddd-a73b-417d03ffe4f1', '4468519e-45b7-42e3-a131-b2181808b714', 'EFFECT OF VARYING PLANES OF WINTER NUTRITION OF BEEF COWS ON CALF PERFORMANCE TO WEANING', 'W. A. Jordan, E. E. LISTER, G. John Rowlands', 1968, 'Canadian Journal of Animal Science', '10.4141/cjas68-021', 'https://doi.org/10.4141/cjas68-021', 'https://www.nrcresearchpress.com/doi/pdf/10.4141/cjas68-021', NULL, NULL, NULL, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('41370aeb-fffc-448a-9df1-db060492dc38', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of alternate weaning methods on behavior, blood metabolites and performance of beef calves', 'Boland, H.T.; Scaglia, G.; Swecker, W.S. Jr.; Burke, N.C.', 2008, 'The Professional Animal Scientist 24:539-551', NULL, 'https://www.appliedanimalscience.org/', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Subscription (American Registry of Professional Animal Scientists / Elsevier)', 'The Virginia three-way comparison of conventional, fenceline and two-stage nose-flap weaning, summarised in NMSU Circular 648. Two-stage weaning reduced signs of behavioural stress relative to abrupt weaning, but fenceline weaning gave a similar reduction. Fenceline weaning produced over fivefold more vocalisations during the first week after remote physical separation yet still yielded improved weight gain, which the authors attributed to residual nose sensitivity reducing feed intake in flapped calves - an effect not seen in the Canadian or Montana studies. Weight gain was measured only for the first 7 days post-weaning, so no long-term fenceline-versus-flap comparison was possible.', '{weaning,fenceline,two-stage,nose-flap,behaviour,blood-metabolites,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6735f9d9-b16a-489d-b39c-44ea4e39cfa9', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of castration and weaning conducted concurrently or consecutively on behaviour, blood traits and performance in beef calves', 'Marti, S.; Velarde, A.; de la Torre, J.L.; Bach, A.; Aris, A.; Serrano, A.; Manteca, X.; Devant, M.', 2014, 'Animal 8(11)', '10.1017/S1751731114002080', 'https://doi.org/10.1017/S1751731114002080', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Open access per DOAJ, but no downloadable PDF could be verified', 'Directly relevant to the handling-count question a two-stage programme raises: is it better to stack procedures into one handling event or spread them out? Compares castration and weaning conducted concurrently versus consecutively, with behaviour, blood traits and performance endpoints. This is the closest the literature comes to measuring the cost of extra handling events around weaning - a cost that nose-flap weaning adds two of (insert and remove) and that no nose-flap study has measured. A companion paper by the same group appears in Applied Animal Behaviour Science (10.1016/j.applanim.2014.09.003).', '{weaning,castration,handling-events,extra-handling,behaviour,blood-traits,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1eb45ea3-d1ce-4b6f-980e-e1337e6810bf', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of commingling beef calves from different sources and weaning protocols during a forty-two-day receiving period on performance and bovine respiratory disease', 'Step, D.L.; Krehbiel, C.R.; DePra, H.A.; Cranston, J.J.; Fulton, R.W.; Kirkpatrick, J.G.; Gill, D.R.; Payton, M.E.; Montelongo, M.A.; Confer, A.W.', 2008, 'Journal of Animal Science 86(11):3146-3158', '10.2527/jas.2008-0883', 'https://doi.org/10.2527/jas.2008-0883', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Subscription (American Society of Animal Science / Oxford University Press)', 'The study that quantifies where BRD risk actually comes from, and the strongest argument for keeping calves on the ranch. Ranch-origin calves commingled with auction-market calves over a 42-day receiving period: total morbidity was about 11% for ranch-origin calves, 42% for auction-market calves and 23% for commingled calves (reported elsewhere as 11.1, 41.9 and 22.6%). Calves held on the ranch for 45 days after weaning were less likely to require treatment than calves shipped at weaning. The practical reading is that single-sourcing and 45 days of ranch retention are the measured morbidity levers; no controlled trial has shown that the weaning method itself reduces BRD in a healthy herd. A later study (Mijar et al. 2023) found no commingling effect in its setting, so the effect is not universal.', '{weaning,preconditioning,commingling,BRD,morbidity,receiving,shipping,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('de38cc94-d40f-41c9-98f6-6d8ae285c8fa', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of Low-Stress Weaning on Calf Growth Performance and Carcass Characteristics (SDSU Beef Day 2020 and Meat and Muscle Biology)', 'Gubbels, E.R.; Salverson, R.R.; Cammack, K.M.; Grubbs, J.K.; Underwood, K.R.; Olson, K.C.; Blair, A.D.', 2020, 'South Dakota State University Beef Day 2020 Summary Publication, pp. 117-124; also Meat and Muscle Biology', '10.22175/mmb.10713', 'https://openprairie.sdstate.edu/sd_beefday_2020/', NULL, NULL, NULL, 1, NULL, 'northern_plains', 3, 'Open access (Open PRAIRIE / Meat and Muscle Biology), but no PDF download could be verified', 'The earlier report of the South Dakota State low-stress weaning work that was later published in full as Gubbels et al. 2023 in Translational Animal Science. Angus x Simmental crossbred steers (n=90 in the Meat and Muscle Biology version, 89 in the 2023 paper), comparing two low-stress weaning methods with conventional weaning. Conclusion as stated in the proceedings: low-stress weaning methods do not significantly improve post-weaning growth performance or carcass merit compared with calves weaned using conventional methods. Use the 2023 Translational Animal Science paper for the full statistics; this entry is for provenance.', '{weaning,fenceline,nose-flap,abrupt,carcass,null-result,northern-plains,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('540f0425-73dc-4c40-af3c-3d5be2deb17a', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of Parenteral Supplementation with Minerals and Vitamins on Oxidative Stress and Humoral Immune Response of Weaning Calves', 'Guillermo Alberto Mattioli, Diana Esther Rosa, Esteban Turic, Sebastián Julio Picco, Santiago José Raggio, Antônio Humberto Hamad Minervino, Luis Emilio Fazzio', 2020, 'Animals', '10.3390/ani10081298', 'https://doi.org/10.3390/ani10081298', 'https://www.mdpi.com/2076-2615/10/8/1298/pdf', NULL, NULL, 9, NULL, 'other', 1, 'cc-by', 'We aimed to evaluate the effects of injectable mineral and vitamin supplementation on weaning calves subjected to a low-stress (fence-line) weaning system. Seven-month-old Aberdeen Angus female calves (n = 40, 152 ± 11 kg body weight) from a selenium-deficient area of extensive cattle production on natural grass were randomly assigned to two groups (n = 20 each). One group received subcutaneous supplementation with copper, zinc, selenium, manganese and vitamins A and E (SG), and the other was given sterile saline solution (CG). The animals were supplemented twice, seven days before weaning (day −7) and on the day of weaning (day 0), and they were evaluated 30 (+30) and 60 (+60) days after weaning. Total antioxidant status (TAS), selenium-dependent glutathione peroxidase (GPx) activity, body weight, and average daily gain (ADG) were evaluated. Additionally, antibody titers were assessed prior to and after each immunization with a vaccine containing bovine herpes virus type 1 (BoHV-1). On day +30, body weight (p = 0.03) was higher in SG, whereas TAS (p = 0.02) and GPx (p = 0.0038) activity were lower in CG and remained constant in SG. Antibody titers increased in SG and CG following immunization, being higher in SG on days +30 and +60 (p < 0.05). In conclusion, parenteral supplementation of minerals and vitamins with antioxidant effects in a low-stress weaning system prevented the decrease in TAS and GPx activity, improved antibody response and had positive effects on body weight.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e18fd9a2-d840-40d6-88f5-0ae3d00f867d', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of remote and contact weaning on behaviour and weight gain of beef calves', 'Stookey, J.M.; Schwartzkopf-Genswein, K.S.; Waltz, C.S.; Watts, J.M.', 1997, 'Journal of Animal Science 75(Suppl. 1):83 (abstract)', NULL, 'https://doi.org/10.2527/jas1997.75suppl_183x', NULL, NULL, NULL, NULL, NULL, 'prairies', 3, 'Subscription (abstract only)', 'The early Canadian fenceline result, from the same University of Saskatchewan group that later produced the two-stage work. Reported effects on calf behaviour similar to Price et al. 2003, plus a short-term benefit on weight gain. Published only as a conference abstract, so there is no full paper to retrieve; it is cited in Haley''s 2006 thesis as the precedent for fenceline contact in cattle. Included for provenance, not for numbers.', '{weaning,fenceline,behaviour,weight-gain,canadian,conference-abstract,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aac60606-eb0f-4d22-96e6-d30cc382049b', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of timing of weaning on energy utilization in primiparous beef cows and post-weaning performance of their progeny1', 'Aksel Wiseman, Miles D Redden, Adam McGee, C M Spencer, Ryan R Reuter, Gerald W. Horn, David Lalman', 2019, 'Journal of Animal Science', '10.1093/jas/skz019', 'https://doi.org/10.1093/jas/skz019', 'https://academic.oup.com/jas/article-pdf/97/3/1198/28000117/skz019.pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e41ecae-d2e6-4bb3-8fd3-c04e664cbda4', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of two-stage weaning with nose flap devices applied to calves on cow body condition, calf performance, and calf humoral immune response', 'Lippolis, K.D.; Ahola, J.K.; Mayo, C.E.; Fischer, M.C.; Callan, R.J.', 2016, 'Journal of Animal Science 94(2):816-823', '10.2527/jas.2015-9624', 'https://doi.org/10.2527/jas.2015-9624', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Subscription (American Society of Animal Science / Oxford University Press)', 'The study that established the immune cost of long nose-flap periods, and the reason flap wear should not overlap the pre-weaning vaccination window. Cow-calf pairs randomly assigned to a nose flap for 21 days before separation or no flap, with cow body condition scored at the start and day 56 and calves vaccinated and challenged with ovalbumin. Flaps did not change feed intake, feed efficiency or morbidity in the initial post-separation period, but pre-weaning ADG, serum BVDV-1 and BHV-1 titres and the humoral response to ovalbumin were all DECREASED in flapped calves. Control calves had higher BHV-1 titres on days 1 and 28 (P<0.05) and greater ovalbumin-specific IgM on day 28. Twenty-one days is roughly three times the longest flap period any behavioural study has shown a benefit for.', '{weaning,two-stage,nose-flap,vaccination,immune-response,antibody-titre,days-of-flap,cow-body-condition,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1afefe07-e7df-4cb7-8e3e-2650656344d0', '4468519e-45b7-42e3-a131-b2181808b714', 'Effects of weaning beef cattle in two stages or by abrupt separation on nasal abrasions, behaviour, and weight gain', 'Lambertz, C.; Farke-Rover, A.; Moors, E.; Gauly, M.', 2015, 'Animal Production Science', '10.1071/AN14097', 'https://www.publish.csiro.au/an/AN14097', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Subscription (CSIRO Publishing)', 'The first study to score nose-flap injuries systematically, in 89 German Angus, Simmental and crossbred calves wearing plastic and metal flaps for 7 days. Nasal abrasions were present in over 95% of calves at flap removal: about 27% slight irritation, 58% slight or heavy bleeding, about 7% pus and 4% deep purulent wounds. Flap retention was 76.4%, i.e. about 24% loss, consistent with the two most recent North American studies and well below Haley''s 95%. Cited by both Valente et al. 2022 and Kirk & Tucker 2023 as the baseline injury reference.', '{weaning,two-stage,nose-flap,nasal-injury,retention,behaviour,weight-gain,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b1ab751-3bca-4e57-96a0-c7b2962189cf', '2c9fdaa9-f285-4484-ac79-fa71d5d3dc64', 'Weighing in on the Heavy Psychological Tolls of Obesity∗', 'Carl J. Lavie, MD, Deepika R. Laddu, PhD, Ross Arena, PhD', 2024, 'JACC: Advances', '10.1016/j.jacadv.2024.101114', 'https://doi.org/10.1016/j.jacadv.2024.101114', 'http://www.sciencedirect.com/science/article/pii/S2772963X24003090', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', NULL, '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e747fe3-7847-4e0d-8226-b41e950af654', '4468519e-45b7-42e3-a131-b2181808b714', 'Evaluation of weaning stress in beef calves', 'Landa, C.E.', 2011, 'MSc thesis, Virginia Polytechnic Institute and State University (Biomedical and Veterinary Sciences)', NULL, 'https://vtechworks.lib.vt.edu/', 'https://vtechworks.lib.vt.edu/server/api/core/bitstreams/81b18a62-1213-45d1-a715-13a2a5d73362/content', NULL, NULL, 117, NULL, 'other', 4, 'Open access in Virginia Tech VTechWorks', 'A careful null result that is rarely cited, and a useful corrective. Study 3 of this thesis compared fenceline (described by the author as two-stage) with abrupt weaning, measuring calf weights, immune cell function, antibody production, blood glucose, faecal cortisol and gene expression for FAS, IL-4, IL-10 and interferon-gamma before and after weaning. The ONLY difference detected was higher blood glucose in abruptly weaned calves on the day after weaning. Faecal cortisol and expression of FAS and IL-4 rose in both groups after weaning with no treatment difference; IL-10 and IFN-gamma did not change; no date, treatment or interaction effect was found for total weight gain or interferon-gamma production. The thesis also validates handheld glucometers for chute-side bovine blood glucose (Precision Xtra more accurate and precise than ReliOn), which is a cheap practical stress measure a ranch could actually use.', '{weaning,fenceline,abrupt,cortisol,blood-glucose,gene-expression,null-result,thesis,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('36d439de-865d-4d8c-b1f1-5962cd448bab', '4468519e-45b7-42e3-a131-b2181808b714', 'Examination of the bovine leukocyte environment using immunogenetic biomarkers to assess immunocompetence following exposure to weaning stress', 'Aran O’Loughlin, Mark McGee, Sinéad M. Waters, Seán Doyle, Bernadette Earley', 2011, 'BMC Veterinary Research', '10.1186/1746-6148-7-45', 'https://doi.org/10.1186/1746-6148-7-45', 'https://bmcvetres.biomedcentral.com/counter/pdf/10.1186/1746-6148-7-45', NULL, NULL, 13, NULL, 'other', 1, 'cc-by', 'BACKGROUND: The molecular mechanisms by which stress induces the development of pathologies remains unclear, although it is recognised that one of the major factors affecting health as a consequence of stress is the involvement of the neuroendocrine system. In cattle, a number of necessary husbandry practices have been shown to activate the stress response, yet very little is known about the impact these have at the molecular level. The objectives of the study were to characterise, in male and female beef calves, the immune response to weaning stress in bovine leukocytes at the physiological and molecular levels and to assess the difference between calves weaned in the presence of the dam and those weaned and penned away from the dam. RESULTS: Following exposure to weaning stress, total neutrophil number and neutrophil:lymphocyte (N:L) ratio increased (P < 0.01) in calves. Additionally, expression of pro-inflammatory cytokine genes, including IL-1β, IL-8, IFN-γ and TNFα, were up-regulated (P < 0.01). Furthermore, there was increased (P < 0.001) expression of the glucocorticoid receptor, GRα, the pro-apoptotic gene, Fas and the Gram-negative pattern recognition receptor, TLR4. Calves penned away from the dam post-weaning had increased (P < 0.01) neutrophil number and N:L ratio compared with calves penned next to the dam, and female calves had higher (P < 0.05) expression levels of IL-2, IL-8, IFN-γ and TNFα than male calves. CONCLUSIONS: Weaning elicits an immediate and somewhat short-lived acute stress response in the calf. The effects serve to enhance, rather than suppress, the immune response by means of a heightened inflammatory response and cellular mobilization. The earlier and more profound increase in neutrophil number and N:L ratio together with reduced lymphocyte number in calves penned away compared with calves penned near their dams post-weaning suggests that the former may be more sensitive to weaning stress. The data also show a clear effect of gender in differential gene expression in response to stress with IFN-γ having increased expression in female calves compared with male calves over the course of the study. Additionally, this study has helped to characterise the inflammatory response to stress in calves and identify a number of novel candidate biomarkers suitable for investigation in future studies of stress.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('40c9811e-288e-4310-a7f7-b7174f02de6f', '4468519e-45b7-42e3-a131-b2181808b714', 'Feeding dried distillers grains with solubles to lactating beef cows: impact of excess protein and fat on cow performance, milk production and pre-weaning progeny growth', 'C.N. Shee, Ronald P. Lemenager, Jon Patrick Schoonmaker', 2015, 'animal', '10.1017/s1751731115001755', 'https://doi.org/10.1017/s1751731115001755', 'https://www.sciencedirect.com/science/article/pii/S1751731115001755/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Multiparous Angus×Simmental cows (n=54, 5.22±2.51 years) with male progeny were fed one of two diets supplemented with either dried distillers grains with solubles (DDGS) or soybean meal (CON), from calving until day 129 postpartum (PP) to determine effects of excess protein and fat on cow performance, milk composition and calf growth. Diets were formulated to be isocaloric and consisted of rye hay and DDGS (19.4% CP; 8.76% fat), or corn silage, rye hay and soybean meal (11.7% CP; 2.06% fat). Cow-calf pairs were allotted by cow and calf age, BW and breed. Cow BW and body condition score (BCS; P⩾0.13) were similar throughout the experiment. A weigh-suckle-weigh was performed on day 64 and day 110±10 PP to determine milk production. Milk was collected on day 68 and day 116±10 PP for analysis of milk components. Milk production was unaffected (P⩾0.75) by dietary treatments. Milk urea nitrogen was increased at both time points in DDGS compared with CON cows (P<0.01). Protein was decreased (P=0.01) and fat was increased (P=0.01) in milk from DDGS compared with CON cows on day 68 PP. Compared to CON, DDGS decreased medium chain FA (P<0.01) and increased long chain FA (P<0.01) at both time points. Saturated FA content of milk was decreased (P<0.01) at both time-points in DDGS compared with CON cows, which resulted in an increase (P<0.01) in monounsaturated and polyunsaturated FA, including cis-9, trans-11 conjugated linoleic acid. Daily gain of the DDGS calves was increased (P=0.01) compared with CON calves, resulting in heavier BW on day 129 (P=0.01). Heavier BW of DDGS calves was maintained through weaning (P=0.01). Timed-artificial insemination (TAI) rates were greater for cows fed DDGS compared with cows fed CON (P<0.02), but dietary treatment had no effect on overall pregnancy rates (P=0.64). In summary, feeding DDGS to lactating beef cows did not change cow BW or BCS, but did improve TAI rates and altered milk composition compared with CON. As a result, male progeny from cows fed DDGS during lactation had greater average daily gain and were heavier at day 129 and at weaning compared with male progeny from cows fed a control diet.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1aa19a03-9f81-4db3-80ba-d52eef7b2983', '4468519e-45b7-42e3-a131-b2181808b714', 'Feeding selenium-biofortified alfalfa hay during the preconditioning period improves growth, carcass weight, and nasal microbial diversity of beef calves', 'Jean A. Hall, Anitha Isaiah, Gerd Bobe, Charles T. Estill, Janell K. Bishop, T. Zane Davis, Jan S. Suchodolski, Gene J. Pirelli', 2020, 'PLoS ONE', '10.1371/journal.pone.0242771', 'https://doi.org/10.1371/journal.pone.0242771', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0242771&type=printable', NULL, NULL, 30, NULL, 'other', 1, 'public-domain', 'We previously reported that feeding Se-biofortified alfalfa hay to weaned beef calves in a preconditioning program decreases morbidity and mortality during the feedlot period. To understand the mode of action by which supranutritional Se supplementation supports calf health, we examined the effect of agronomic Se-biofortification on nasal microbiome and fecal parasites. Recently weaned Angus-cross beef calves (n = 30) were randomly assigned to two groups and fed an alfalfa hay-based diet for 9 weeks in a preconditioning program. Alfalfa hay was harvested from fields fertilized with sodium selenate at a rate of 0 or 90 g Se/ha. Calculated Se intake from dietary sources was 1.09 and 27.45 mg Se/calf per day for calves consuming alfalfa hay with Se concentrations of 0.06 and 3.47 mg Se/kg dry matter, respectively. Feeding Se-biofortified alfalfa hay for 9 weeks was effective at increasing whole-blood Se concentrations (556 ± 11 vs 140 ± 11 ng/mL; P < 0.001) and increasing body weight (PTreatment, = 0.03) in weaned beef calves. Slaughter yield grades were higher for calves that had been fed Se-enriched alfalfa hay during the preconditioning period (PTreatment = 0.008). No significant differences were observed in fecal parasite load, which remained low. The nasal microbiome and microbiota diversity within calves and across calves expanded from weaning (week 0) to the feedlot period (week 12), which was promoted by feeding Se-biofortified alfalfa hay. Especially concerning was the expansion of nasal Mycoplasmataceae in the feedlot, which reached over 50% of the total microbiota in some calves. In conclusion, we identified dietary Se-biofortified alfalfa hay as a potential promoter of nasal microbiome genome and microbiota diversity, which may explain in part high-Se benefits for prevention of bovine respiratory disease complex in beef calves.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('84e22b12-9314-4a3a-a531-35807cef161a', '4468519e-45b7-42e3-a131-b2181808b714', 'Fence Line Weaning Reduces Stress During Weaning of Beef Calves (Animal Science Info Series AS-B 312)', 'Lane, C. Jr.', 2020, 'University of Tennessee Extension', NULL, 'https://utbeef.tennessee.edu/', 'https://utbeef.tennessee.edu/wp-content/uploads/sites/127/2020/11/FencelineWeaningReducesStressDuringWeaningofBeefCalves-CDL-ASB312.pdf', NULL, NULL, NULL, NULL, 'other', 4, 'University of Tennessee Extension publication, freely distributed', 'A two-page extension sheet whose value is that it REPRODUCES the Price et al. 2003 behaviour table in full, with letters for significance at P<0.05 - the only free source for those numbers found. Percentage of observations over the first three days by method: eating 41.1 (non-weaned), 37.3 (fenceline), 23.7 (separated on pasture), 28.9 (drylot, hay-preconditioned), 21.5 (drylot, no hay); walking 8.6, 10.1, 28.1, 9.6, 14.8; lying down 22.9, 23.3, 16.0, 21.9, 20.6; vocalisation 0.1, 216.7, 434.6, 371.2, 518.2 per 10-calf group. Its management guidance: move cows and calves into the weaning pen a few days beforehand so calves learn from their dams where feed and water are; at weaning remove the COWS and leave the calves in place; the fence must stop the calf reaching through to nurse; usually 7 to 14 days are required; complete dehorning, castration and vaccination before weaning; combine weaning with at least a 45-day preconditioning programme.', '{weaning,fenceline,extension,price-2003-table,vocalisation,behaviour,sort-the-cows-off,days-of-contact}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a9e761c7-71e2-4d93-9f2d-26aa253cf1e4', '4468519e-45b7-42e3-a131-b2181808b714', 'Fenceline contact of beef calves with their dams at weaning reduces the negative effects of separation on behavior and growth rate', 'Price, E.O.; Harris, J.E.; Borgwardt, R.E.; Sween, M.L.; Connor, J.M.', 2003, 'Journal of Animal Science 81:116-121', '10.2527/2003.811116x', 'https://doi.org/10.2527/2003.811116x', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'Subscription (American Society of Animal Science / Oxford University Press)', 'The study that made fenceline weaning mainstream and still the only one to show a lasting production advantage. Three years, about 100 Angus/Hereford-cross calves, five treatments with 7 days of treatment each year and weekly weights for 10 weeks: fenceline separation on pasture, total separation on pasture, total separation in drylot with or without hay preconditioning, and non-weaned controls. Over the first 3 days, fenceline calves spent 37.3% of observations eating vs 23.7% (separated on pasture) and 21.5% (drylot, no hay), walked 10.1% vs 28.1%, and lay down 23.3% vs 16.0%; vocalisation was 216.7 vs 434.6-518.2 calls per 10-calf group, against 0.1 for unweaned controls. Cumulative gain: fenceline 47 lb at 2 weeks and 110 lb at 10 weeks vs 20-30 lb and 79-91 lb for the fully separated groups. In kg, fenceline vs remotely separated was 21.4 vs 11.0 kg at week 2 and 50.0 vs 38.2 kg at week 10, i.e. about 95% more gain in the first fortnight and a 22-24 lb advantage still present at 10 weeks. Except for vocalisation, fenceline calves behaved like unweaned controls. Design note that matters: the cows were moved and the calves stayed in their original pasture. Fence was barbed wire overlaid with woven wire. No free PDF; the behaviour table is reproduced in University of Tennessee Extension AS-B 312 and the growth table in Virginia Cooperative Extension''s Cow-Calf Manager, both of which are free.', '{weaning,fenceline,behaviour,vocalisation,weight-gain,drylot,creep-feeding,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e56dc47e-21bb-440f-9342-dd776ce1706a', '4468519e-45b7-42e3-a131-b2181808b714', 'Growth performance and hematological changes of weaned beef calves diagnosed with respiratory disease using respiratory scoring and thoracic ultrasonography', 'Inmaculada Cuevas-Gómez, Mark McGee, Matthew Sean McCabe, Paul Cormican, Edward G. O’Riordan, T. G. McDaneld, Bernadette Earley', 2020, 'Journal of Animal Science', '10.1093/jas/skaa345', 'https://doi.org/10.1093/jas/skaa345', 'https://academic.oup.com/jas/article-pdf/98/11/skaa345/34559287/skaa345.pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2acd65d-07ab-4294-a7da-ddd873976b64', '4468519e-45b7-42e3-a131-b2181808b714', 'Impact of Two-Stage Weaning and Bovine-Appeasing Substance on Growth, Temperament, Pasture Behavior, and Immune System of Nellore Calves', 'Santos, M.; Oliveira, D.M.; de Souza, M.R.; Almeida, G.B.; Santos, A.R.D.; Belmonte, J.C.C.; Melo-Sterza, F.A.; Ferraz, A.L.J.; Vedovatto, M.', 2025, 'Animals 15(11):1640', '10.3390/ani15111640', 'https://www.mdpi.com/2076-2615/15/11/1640', 'https://www.mdpi.com/2076-2615/15/11/1640/pdf', NULL, NULL, NULL, NULL, 'other', 3, 'CC BY 4.0', 'A recent two-stage weaning trial that also tests a bovine-appeasing pheromone analogue, with growth, temperament, pasture behaviour and immune endpoints. Useful for two reasons: it is one of the newest two-stage datasets available free, and it represents the current research direction - pharmacological or pheromonal stress mitigation layered on or substituted for mechanical methods like flaps and fences. Nellore cattle in Brazil, so extrapolate to Red Angus with care.', '{weaning,two-stage,nose-flap,appeasing-substance,temperament,immune-response,recent}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fbff89da-5ce8-4799-9751-760244b34932', '4468519e-45b7-42e3-a131-b2181808b714', 'Impacts of cow body condition score during gestation on weaning performance of the offspring', 'Rodrigo S Marques, Reinaldo Fernandes Cooke, M.C. Rodrigues, Philipe Moriel, David W. Bohnert', 2016, 'Livestock Science', '10.1016/j.livsci.2016.08.007', 'https://doi.org/10.1016/j.livsci.2016.08.007', 'https://www.sciencedirect.com/science/article/pii/S1871141316301780', NULL, NULL, 5, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7c8ce466-b742-4cce-aa18-270fa248970e', '4468519e-45b7-42e3-a131-b2181808b714', 'Influence of Heifer Post-Weaning Voluntary Feed Intake Classification on Lifetime Productivity in Black Angus Beef Females', 'Krista R. Wellnitz, Cory T. Parsons, Julia M. Dafoe, Darrin L. Boss, Samuel A. Wyffels, Timothy DelCurto, Megan L. Van Emon', 2022, 'Animals', '10.3390/ani12131687', 'https://doi.org/10.3390/ani12131687', 'https://www.mdpi.com/2076-2615/12/13/1687', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'This study evaluated heifer post-weaning voluntary feed intake (g/kg BW) classification on performance and reproductive measures, as well as impacts on lifetime productivity of 519 commercial Angus beef females. Heifer post-weaning voluntary feed intake (g/kg BW) was calculated over 80 test days following weaning using GrowSafe units. Heifers were categorized based on voluntary feed intake (g/kg BW) as either low (0.50 SD from the mean) within year. Cow body weight (BW) and body condition score (BCS) at breeding displayed an age effect (p p p p p p ≥ 0.22) pregnancy status or AI conception. In summary, heifer post-weaning feed intake classification had only minor impacts compared to age effects on lifetime productivity of Angus beef females.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('69161e62-ccdd-4b11-ab0a-92000fae366e', '4468519e-45b7-42e3-a131-b2181808b714', 'Influence of two-stage weaning with subsequent transport on body weight, plasma lipid peroxidation, plasma selenium, and on leukocyte glutathione peroxidase and glutathione reductase activity in beef calves', 'Burke, N.C.; Scaglia, G.; Boland, H.T.; Swecker, W.S. Jr.', 2009, 'Veterinary Immunology and Immunopathology 127:365-370', '10.1016/j.vetimm.2008.11.017', 'https://doi.org/10.1016/j.vetimm.2008.11.017', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Subscription (Elsevier)', 'Two-stage weaning combined with transport, measuring oxidative-stress markers as well as body weight. Cited by Valente et al. 2022 as showing that the nose-flap ADG penalty has only a short-term effect, recovered by compensatory gain after flap removal - the main counterargument to the stage-1 weight loss other studies report. One of the few papers to put weaning method and transport in the same design.', '{weaning,two-stage,nose-flap,transport,oxidative-stress,weight-gain,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4e79a914-0b2c-4598-92b2-d88e755419cb', '4468519e-45b7-42e3-a131-b2181808b714', 'Influence of weaning strategy on behavior, humoral indicators of stress, growth, and carcass characteristics', 'Freeman, S.; Poore, M.; Pickworth, C.; Alley, M.', 2020, 'Translational Animal Science 5(1):txaa231', '10.1093/tas/txaa231', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC8208429/', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'CC BY-NC 4.0 (publisher PDF asset not downloadable without a browser session)', 'A four-year North Carolina State trial that concludes against nose flaps on both welfare and performance grounds - the strongest published dissent. Angus and Angus x Senepol steers stratified by dam parity, hair coat and weight: abrupt at 7 months (A, n=39), weaning after a 7-day nose flap (N, n=40), or weaning delayed 49 days (D, n=39); weaned at 237 +/- 3 d of age at 254 +/- 6.7 kg, with accelerometer collars on a subsample and blood for cortisol and haptoglobin in the last two years. ADG over the 42 days after weaning was 0.69, 0.54 and 0.37 kg/d for D, A and N respectively (P<0.01) - the nose-flap arm was the worst. A and D calves were more active and more vocal than N for the first 2-3 days but settled to similar levels by day 4. Cortisol and haptoglobin remained within normal reference ranges in all groups. Twelve of 38 nose-flap steers (32%) had sores in their nostrils when the flaps were removed, and 2, 1, 2 and 7 non-observed steers lost flaps prematurely in 2013-2016. All groups graded Low Choice with similar efficiency of gain through finishing (P>0.2). The authors recommend delaying weaning where pasture and cow condition allow, and state that otherwise abrupt weaning may be the next viable option based on animal welfare concerns and increased handling to place and remove the flaps, adding that abrupt weaning under their conditions was less stressful than it is perceived to be.', '{weaning,nose-flap,abrupt,delayed-weaning,cortisol,haptoglobin,nasal-injury,carcass,accelerometer,counter-evidence,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('25dcee90-20e8-4b08-a4f4-a62a711e9655', '4468519e-45b7-42e3-a131-b2181808b714', 'Low-Stress Handling: How Bud Williams changed cattle handling', 'Hereford World / American Hereford Association', 2023, 'Hereford World, February 2023', NULL, 'https://hereford.org/', 'https://hereford.org/wp-content/uploads/2023/01/0223_Low-Stress-Handling.pdf', NULL, NULL, 2, NULL, 'other', 2, 'Breed-association magazine article, freely distributed', 'Included deliberately as an EXAMPLE OF UNMEASURED ADVOCACY, so the ranch''s software has a labelled specimen of the genre. A breed-magazine account of Bud Williams'' influence on cattle handling. The behavioural principles it describes (cattle want to go back the way they came, cattle want to move past the handler, release pressure as soon as the animal responds) are sound and appear in university extension material. The outcome claims circulating in this literature are not: a family ranch saving about $38,000 a year on 500 yearlings from reduced shrink, Williams cutting a Canadian feedlot''s doctoring from about 75 head a day to two or three, and an unsourced claim of 12% better weight gain and 15% better reproduction. These are case reports and assertions with no control group. Bud Williams'' methods have never been tested in a controlled weaning trial. Treat all of it as advice, never as evidence.', '{handling,stockmanship,bud-williams,low-stress-handling,not-measured,advocacy,unmeasured-claims}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3eba35d-dc04-4f20-b409-63737cb14264', '4468519e-45b7-42e3-a131-b2181808b714', 'Low-Stress Weaning (extension summary of SDSU weaning research)', 'DeHaan, E. (updated); originally Harty, A. and Olson, K.C.', 2025, 'South Dakota State University Extension', NULL, 'https://extension.sdstate.edu/low-stress-weaning', NULL, NULL, NULL, NULL, NULL, 'northern_plains', 4, 'SDSU Extension web resource, freely accessible (no PDF)', 'The Northern Plains extension summary of the SDSU low-stress weaning work, updated July 2025, and the free source for several figures the peer-reviewed papers bury in figures rather than tables. Reports that fenceline-weaned calves gained similarly to unseparated calves during nutritional separation and maintained weight for the first 7 days after physical separation while abruptly weaned calves lost about 2.4 lb per day, and that nose-tag calves gained almost 1.5 lb more per day than calves without them during stage 1. Note that this stage-1 nose-flap result has the OPPOSITE SIGN to Taylor et al. 2020 and Haley et al. 2005, which both found reduced gain while the flap was in - a real unresolved inconsistency in the literature. Practical guidance given: low-stress weaning means nutritional separation then physical separation at least 3 days later; fenceline nutritional separation takes about 3 to 7 days; nose tags are worn 4 to 7 days; example fence is 5-strand barbed wire or electric. Also cites Utah work (fenceline advantage lasting 10 weeks post-weaning) and Michigan work (advantage lasting 14 days, with lower serum haptoglobin at day 5).', '{weaning,fenceline,two-stage,nose-flap,extension,northern-plains,days-of-contact,fence-spec,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dde67402-e830-449a-93ae-00384d9840b1', '4468519e-45b7-42e3-a131-b2181808b714', 'Minimising the stress of weaning of beef calves: a review', 'Daniel Enríquez-Hidalgo, María José Hötzel, Rodolfo Ungerfeld', 2011, 'Acta veterinaria Scandinavica', '10.1186/1751-0147-53-28', 'https://doi.org/10.1186/1751-0147-53-28', 'https://actavetscand.biomedcentral.com/counter/pdf/10.1186/1751-0147-53-28', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Weaning of beef calves is usually done abruptly and early compared to the natural weaning of the species, and is associated with simultaneous exposure of calves to a range of social and environmental stressors. Behavioural and physiological responses to weaning indicate detrimental effects on the welfare of these animals. The development and assessment of weaning methods aiming at reducing or avoiding this problem must be supported by scientific knowledge of the morphological, physiological and psychological mechanisms involved in the establishment, maintenance and braking of the cow-calf bond. Solutions also depend on the understanding of the various stressors associated with weaning, among which are the change in diet, cessation of nursing, separation from the dam, the change to a new spatial environment and the need for social reorganization following removal of the adults from the group. This review discusses these issues and assesses the effectiveness of the methods so far proposed for improving the welfare of beef calves during the weaning period.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('31eb003e-0f03-41d3-bb63-49c89abccbf9', '4468519e-45b7-42e3-a131-b2181808b714', 'Minimizing cows’ stress when calves were early weaned using the two-step method with nose flaps', 'Rodolfo Ungerfeld, G. Quintans, María José Hötzel', 2016, 'animal', '10.1017/s1751731116000793', 'https://doi.org/10.1017/s1751731116000793', 'https://www.sciencedirect.com/science/article/pii/S1751731116000793/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Early weaning may be used in beef cattle production to improve reproduction rates in range conditions. However, weaning causes a stress response in cows, which may be especially strong in early weaning management, as the bond between the cow and the calf is still strong. We hypothesized that weaning calves in two steps, with the aid of anti-sucking devices (nose flaps) would reduce the behavioural stress response in the cows separated from their calves 2 months after parturition. We compared the behaviour frequency and weight change in cows that were weaned abruptly, by separation of the calf on day 0 of the study, or in two steps, consisting of the use of anti-sucking nose flaps for 5 days before permanent separation; a third group was not weaned to serve as control. Thirty-six crossbred multiparous Aberdeen Angus×Hereford cows and their calves (n=12/treatment) were managed in three paddocks with similar pasture availability, with four dyads from each treatment per paddock. Cows'' behaviour was observed by direct visual instantaneous sampling, at 10 min intervals from days -3 to 11. Weaning the calves in two steps clearly attenuated the behavioural stress response observed in abruptly weaned cows, which included reductions in grazing and lying, and increases in pacing, walking and vocalizing. Our results corroborate those previously shown for cows nursing older calves, and indicate that step weaning can reduce the behavioural stress response of cows at weaning, even when the calf is weaned shortly after birth, when the bond between the cow and calf is still very strong.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e2bac7cb-a409-4bf5-93c2-bb178eb9e00c', '4468519e-45b7-42e3-a131-b2181808b714', 'Minimizing Weaning Stress on Calves (Bulletin B221)', 'New Mexico State University Cooperative Extension Service', 2016, 'New Mexico State University Cooperative Extension Service', NULL, 'https://pubs.nmsu.edu/_b/B221/index.html', 'https://pubs.nmsu.edu/_b/B221.pdf', NULL, NULL, 8, NULL, 'other', 3, 'NMSU Extension publication; may be freely reproduced with citation for educational purposes', 'Extension overview of weaning stress reduction, and one of the clearest free descriptions of the Price et al. 2003 design: a three-year study comparing calves not weaned, fenceline weaned, abruptly weaned on pasture, or abruptly weaned in a drylot with or without hay preconditioning. Reports that apart from vocalisation fenceline calves behaved like non-weaned controls and spent more time eating than calves weaned by other methods, that fenceline calves gained at least 50% more weight during the first two weeks and kept the advantage through at least 10 weeks, and that fenceline visits decrease over the first five days with weaning complete within a week. Useful for the practical description of putting cows and calves on opposite sides of a strong fence with the cows moved and the calves left in the original pasture.', '{weaning,fenceline,extension,drylot,behaviour,weight-gain,days-of-contact}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2f0a16a4-4dd3-499b-83ec-a7279e651e37', '4468519e-45b7-42e3-a131-b2181808b714', 'Nose-Flap Devices Used for Two-Stage Weaning Produce Wounds in the Nostrils of Beef Calves: Case Report', 'Tiago S. Valente, Lucas Roberto Batista Ruiz, Fernanda Macitelli, Mateus José Rodrigues Paranhos da Costa', 2022, 'Animals', '10.3390/ani12111452', 'https://doi.org/10.3390/ani12111452', 'https://www.mdpi.com/2076-2615/12/11/1452/pdf?version=1654332981', NULL, NULL, NULL, NULL, 'alberta', 4, 'cc-by', 'This case report aims to describe the occurrence of negative impacts of wearing nose-flap devices on beef calves subjected to the two-stage weaning method. Forty-one calves, twenty-one pure Nellore and twenty F1 Angus-Nellore, were weaned on average at 236 days of age. Commercial nose-flap devices were fitted in the nostrils of the calves (d0) to prevent suckling and removed five days later (d5). Individual body weights were assessed at d0 and d5, and average daily gain (ADG) was calculated. At d5, during nose-flap device removal, it was noted that 26.8% of the calves lost the nose-flap device; however, all of them had wounds in their nostrils (no injuries in the nostrils had been observed on d0). To assess the severity of these injuries, an impairment score was assigned to each calf, ranging from 1 = no lesions to 5 = injured with purulent discharge. A logistic regression model was fitted to evaluate the effect of sex and genetic group on nose-flap retention (kept or lost). The retention rate did not differ (p > 0.05) between sex and genetic groups. All calves showed at least open wounds of the nasal septum (score 2), including those that lost the nose-flaps before d5. Almost half of the calves showed weight loss during this period. We conclude that there is a considerable risk of the two-stage weaning method compromising the physical integrity of the nostrils of beef calves through the use of these devices, and due to this, it should not be referred to as a low-stress weaning practice for beef calves.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c6535e2d-3700-4ee6-926a-22a4b2a633de', '4468519e-45b7-42e3-a131-b2181808b714', 'One-way gates, crowd pen and single-file chute placement guidance', 'Grandin, T.', 2020, 'grandin.com cattle handling facility design pages', NULL, 'https://www.grandin.com/design/design.html', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Author''s freely accessible web resource (HTML, no PDF)', 'The standard free reference for one-way (ratchet) gate placement, which matters for any sorting system that uses them. A one-way gate at the junction between the single-file chute and the crowd pen should be located at least one body length up the single-file chute, and gates placed too close to the crowd pen can stop movement, so at least two body lengths up the race is preferable; equipping the gate with a remote control rope operable from the crowd pen facilitates cattle entry; most gates can be tied open when cattle are calm, except the one nearest the squeeze chute, which keeps the leader from backing out. Engineering and behavioural guidance, not a measured comparison - no trial has tested one-way gate placement against flow rate or stress. Note also that Hibbard and Locatelli published a point-by-point critique of Grandin''s facility designs in the Stockmanship Journal; that is a position paper, not evidence either way.', '{sorting,one-way-gate,ratchet-gate,facility-design,grandin,not-measured,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ea14f55e-e9b1-4994-8001-2a3f39db046d', '4468519e-45b7-42e3-a131-b2181808b714', 'Plasma metabolomics reveals major changes in carbohydrate, lipid, and protein metabolism of abruptly weaned beef calves', 'L. A. González, Júlia Gleyci Soares de Carvalho, Bruno Castro Kuinchtner, Anthony C. Dona, Pietro Sampaio Baruselli, Michael J. D’Occhio', 2023, 'Scientific Reports', '10.1038/s41598-023-35383-2', 'https://doi.org/10.1038/s41598-023-35383-2', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC10199950/pdf/41598_2023_Article_35383.pdf', NULL, NULL, 15, NULL, 'other', 1, 'cc-by', 'H NMR-based metabolomics was used to study the effect of abrupt weaning on the blood metabolome of beef calves. Twenty Angus calves (258 ± 5 kg BW; 5 to 6 months old) were randomly assigned to a non-weaned (NW) group that remained grazing with their dam or a weaned (W) group that underwent abrupt separation from their dam to a separate paddock on d 0 of the study. Body weight, behaviour, and blood samples for cortisol and metabolomics were measured at d 0, 1, 2, 7, and 14 of the study. On d 1 and 2, W calves spent less time grazing and ruminating, and more time vocalising and walking, had a greater concentration of cortisol, NEFA, 3-hydroxybutyrate, betaine, creatine, and phenylalanine, and lesser abundance of tyrosine (P < 0.05) compared to NW calves. Compared to NW calves at d 14, W calves had greater (P < 0.01) relative abundance of acetate, glucose, allantoin, creatinine, creatine, creatine phosphate, glutamate, 3-hydroxybutyrate, 3-hydroxyisobutyrate, and seven AA (alanine, glutamate, leucine, lysine, phenylalanine, threonine and valine) but lesser (P < 0.05) relative abundance of low density and very low-density lipids, and unsaturated lipids. Both PCA and OPLS-DA showed no clustering or discrimination between groups at d 0 and increasing divergence to d 14. Blood metabolomics is a useful tool to quantify the acute effects of stress in calves during the first 2 days after abrupt weaning, and longer-term changes in carbohydrate, lipid and protein metabolism due to nutritional changes from cessation of milk intake and greater reliance on forage intake.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('77c55efa-2f7e-492d-b9ed-0a6dadd416c0', '4468519e-45b7-42e3-a131-b2181808b714', 'Preconditioning Beef Calves (Circular 637)', 'New Mexico State University Cooperative Extension Service', 2016, 'New Mexico State University Cooperative Extension Service', NULL, 'https://pubs.nmsu.edu/_circulars/CR637/', 'https://pubs.nmsu.edu/_circulars/CR637.pdf', NULL, NULL, 8, NULL, 'other', 3, 'NMSU Extension publication; may be freely reproduced with citation for educational purposes', 'Extension treatment of preconditioning programmes: the vaccination, weaning interval, nutrition and marketing components, and the case for holding calves on the ranch rather than selling at weaning. Relevant as the free companion to the measured preconditioning evidence (Step et al. 2008 on single-source versus commingled morbidity, Taylor et al. 2020 on the cost of early shipping) and to the 45-day requirement of value-added marketing programmes.', '{weaning,preconditioning,extension,vaccination,marketing,45-day}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e1f16cfc-2d91-4188-b7e8-49c3bab00a8b', '4468519e-45b7-42e3-a131-b2181808b714', 'The effects of alternative weaning methods on behaviour in beef calves', 'Enriquez, D.H.; Ungerfeld, R.; Quintans, G.; Guidoni, A.L.; Hotzel, M.J.', 2010, 'Livestock Science 128:20-27', '10.1016/j.livsci.2009.10.007', 'https://doi.org/10.1016/j.livsci.2009.10.007', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Subscription (Elsevier)', 'The study that produced the strongest negative finding for long fenceline periods and the clearest statement that these methods may not work. Calves weaned after 14 days of fenceline separation GREW LESS than abruptly weaned calves and vocalised more frequently and over more days during the partial-separation period; calves spent more than half their time near the dividing fence in the first days. The authors concluded that the two alternative weaning methods did not appear to provide any clear benefit in reducing weaning distress compared with abrupt weaning. This is the evidence behind the rule that 14 days of fenceline contact is harmful rather than merely unnecessary.', '{weaning,fenceline,two-stage,behaviour,days-of-contact,counter-evidence,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4036b1ca-31b9-4035-9901-42b2823e396d', '4468519e-45b7-42e3-a131-b2181808b714', 'Progesterone administration reduces the behavioural and physiological responses of ewes to abrupt weaning of lambs', 'Aline Freitas‐de‐Melo, Georgget Elizabeth Banchero, María José Hötzel, Juan Pablo Damián, Rodolfo Ungerfeld', 2013, 'animal', '10.1017/s1751731113000621', 'https://doi.org/10.1017/s1751731113000621', 'https://www.sciencedirect.com/science/article/pii/S1751731113000621/pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by-nc-nd', 'Abrupt weaning, a usual management in sheep productive systems, may provoke behavioural and physiological responses indicative of stress in ewes and lambs. Progesterone (P4) has anxiolytic and sedative effects through the union of its metabolites that contain 3α-hydroxyl group to the γ-aminobutyricacidA receptor. Our first aim was to determine whether P4 administration reduces the behavioural and physiological responses of ewes to abrupt weaning of lambs. A complementary aim was to determine whether P4 treatment affects the milk yield and composition of ewes, and the BW of their lambs. In experiment 1, seven ewes received P4 treatment for 32 days (group E1-P4), and eight ewes remained as an untreated control group (group E1-C). BW of the lambs was recorded during P4 treatment. Lambs were weaned at 59 days (Day 0 = weaning). The main behaviours of the ewes before and after weaning were recorded using 10 min scan sampling. The ewes'' serum total protein, albumin and globulin concentrations were measured before and after weaning of the lambs. In experiment 2, milk yield and composition were determined in two different groups of six ewes treated with P4 (group E2-P4) for 16 days and in five untreated controls (group E2-C). The BW of lambs increased with time (P = 0.001) in both groups and did not differ. The percentage of observations in which the ewes were seen pacing on Day 0 was greater in the E1-C group than in the E1-P4 group (P = 0.0007). Similarly, the percentage of observations in which the ewes were recorded vocalizing on Day 0 was greater in the E1-C group than in the E1-P4 group (P = 0.04). The percentage of observations in which E1-C ewes were recorded lying did not change from Days 0 to 1; however, it increased in E1-P4 ewes. Total serum protein concentration did not change in E1-P4 ewes from Days 0 to 3, although a decrease was seen in E1-C ewes (P = 0.04). Serum globulin concentration was greater in E1-P4 ewes on Day 3 than in E1-C ewes (P = 0.0008). In experiment 2, there were no differences between E2-P4 and E2-C ewes in terms of milk yield, protein, fat and lactose content. Progesterone administration reduced the behavioural and physiological responses of ewes to abrupt weaning of lambs, and this effect was not mediated by changes in milk yield and composition, or by lambs'' BW.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46fdab0b-2c7a-4151-9e97-9fe1906e3eac', '4468519e-45b7-42e3-a131-b2181808b714', 'PSII-1 Weaning as prenatal stress: preliminary study on indicators of calf resiliency', 'Christy Goldhawk, Karin Orsel, Edmond Anthony Pajor', 2024, 'Journal of Animal Science', '10.1093/jas/skae234.491', 'https://doi.org/10.1093/jas/skae234.491', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11400459/pdf/skae234.491.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5c5729bc-4cf2-4521-8107-24eae1ee026e', '4468519e-45b7-42e3-a131-b2181808b714', 'Sorting cow-calf pairs (Stookey method) and the Biggs calf-stripping technique', 'Stookey, J.M. (University of Saskatchewan); Biggs, D. (Alberta); as documented by Canadian Cattlemen, Hi-Hog, Grainews and Progressive Cattle', 2020, 'Canadian Cattlemen / Hi-Hog Farm and Ranch Equipment / Progressive Cattle (trade press and manufacturer documentation)', NULL, 'https://www.hi-hog.com/resources/livestock-handling-tips/sorting-calves/', NULL, NULL, NULL, NULL, NULL, 'prairies', 5, 'Trade press and manufacturer web resources, freely accessible (no PDF; no peer-reviewed publication exists)', 'The only named, documented method for the ranch''s actual problem - separating pairs with the fewest people and the least pushing - and it is UNMEASURED. Developed by Dylan Biggs, an Alberta rancher, and popularised by Joseph Stookey of the University of Saskatchewan, who credits Biggs. Method: precondition the herd to all the pens; bring the mixed herd into a cow-calf pen; as the herd passes, open and secure a cow sorting gate hung at an angle across the alley; at the group pen open the lower half of a split (Dutch-door) calf sorting gate whose upper section is set at the calves'' shoulder height; the sorter stands at the main alley exit with at most one helper walking the exit fence line; cows walk past the handler and out while calves, which respond to the handler sooner than cows do, duck under the rail into the adjacent calf pen, so both keep walking and nothing balls up at the gate; let strays go, because a second pass is designed in - at the end, close both sorting gates and open the gate between the cow pen and the calf pen. The stripper gate should sit where the cows are going out; the operator works mostly on the far or hinge side of the gate; rail height must be reset for each year''s calf size, and operations with creep feeders can add a vertical bar at creep-gate width. UNMEASURED CLAIMS to flag: that Biggs and Stookey both cut sorting time nearly in half, and that it needs very few boots on the ground. Stookey''s own caveat is the honest part: it works very well for gentle cattle but may not work for wild cattle with big flight zones. No peer-reviewed study of this or any other pair-sorting method exists.', '{sorting,calf-stripping,calf-gate,sort-gate,stookey,biggs,prairies,not-measured,named-method,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('903cff30-3765-4a7f-af0d-c4b18c69c925', '4468519e-45b7-42e3-a131-b2181808b714', 'Temperament and Performance of Beef Cattle (Beef Cattle Library BEEF021, publication 640)', 'Cooke, R.F.', 2013, 'Oregon State University Beef Cattle Sciences', NULL, 'https://extension.oregonstate.edu/animals-livestock/beef/how-temperament-affects-performance-quality-beef-cattle', 'https://agsci.oregonstate.edu/sites/agscid7/files/eoarc/attachments/640.pdf', NULL, NULL, 5, NULL, 'other', 4, 'Oregon State University Extension publication, freely distributed', 'The accessible version of the only measured evidence base for low-stress handling as applied to cattle, from the author of the 2014 Journal of Animal Science Kunkle symposium review (92:5325-5333). That review found that acclimating Bos indicus x Bos taurus or Bos taurus HEIFERS to human handling improved temperament (P<=0.02), reduced plasma cortisol (P<0.01) and hastened puberty (P<=0.02), but that NO benefit was observed when mature cows or feeder cattle were acclimated; a companion 2012 study found acclimation improved temperament without benefiting feedlot receiving performance. This is the honest boundary of the stockmanship evidence: temperament demonstrably affects production, reproduction and health independent of breed type, and acclimation demonstrably calms heifers, but the claim that handling acclimation improves weaning outcomes has not been tested. Enriquez et al. 2011 names it as an open question.', '{handling,stockmanship,temperament,acclimation,cortisol,extension,measured,evidence-boundary}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ab99a9d3-536f-4c2c-8784-45d8e87e0930', '4468519e-45b7-42e3-a131-b2181808b714', 'The behavioural response of cattle (Bos taurus) to artificial weaning in two stages', 'Haley, D.B.', 2006, 'PhD thesis, University of Saskatchewan (Large Animal Clinical Sciences)', NULL, 'https://harvest.usask.ca/items/6ae63ed0-a1c6-4d24-813a-bd63cd0c9543', 'https://harvest.usask.ca/bitstreams/829e3a26-0b8f-4c97-8dbc-0103144a3189/download', NULL, NULL, 200, NULL, 'prairies', 5, 'Open access in the University of Saskatchewan HARVEST repository; author retains copyright', 'The foundational Canadian work on two-stage weaning and the single most useful document in this literature, because it contains the full data behind Haley, Bailey & Stookey (2005) plus three more experiments that were never published separately. Chapter 5: 392 cow-calf pairs over 4 trials. After separation, two-stage calves vocalised 96.6% less (P=0.001), spent 78.9% less time walking (P=0.001), 23.0% more time eating (P=0.001) and 24.1% more time resting (P=0.001) than abruptly weaned controls. Pedometers (Trial 4) showed two-stage calves walked 1.3 km/d MORE while the flap was in and 5.8 km/d LESS in the 4 days after separation; day 1 after separation two-stage calves walked 5.2 +/- 0.5 km/d vs controls 16.7 +/- 3.1 km/d. ADG was lower during stage 1 and greater in the 7 days after separation, but similar over the whole study period (P>0.10); Trial 3 alone showed a 7-week growth advantage (P=0.05). Chapter 4: abruptly weaned cows called at 90 calls/h and calves at 56 calls/h; two-stage cows called 83% less and calves 88% less, walking down 60% and 61%, calves ate 30% more, cows ate 43.3 more min/d; 8 days of flap gave no benefit over 4 days. Chapter 6 is the only published head-to-head of two-stage vs fenceline: two-stage calves (n=36) vocalised 81.2% less than fenceline calves (n=30), whose rate of 14.9 calls/calf/h was more than 6x the two-stage rate; two-stage calves lay 23.1% more and stood 60.3% less. Chapter 7 repeats the effect in 5-week-old dairy calves. Practical detail found nowhere else: flaps cost $1.50 CAD, are reusable after disinfection, can be placed or removed in seconds in a squeeze chute, retention was 95% or better in the trials that worked (one trial was abandoned because devices would not stay in), and Haley explicitly recommends limiting flap wear to 4 or 5 days.', '{weaning,two-stage,nose-flap,fenceline,behaviour,vocalisation,pedometer,canadian,thesis,primary-data}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('127e1f35-1538-4f28-8c73-af2d68daa669', '0b11fb78-9d7f-4f36-9cbf-2b0671987901', 'Alberta wheat [Korean]', 'Government of Alberta', 2018, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/alberta-wheat-korean', 'https://open.alberta.ca/dataset/d881e71b-96db-46fc-b083-772c83a97099/resource/ddd043f5-0d5e-4ccd-b517-6644068dc54c/download/af-alberta-wheat-2018-korean.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Alberta has established a reputation as a producer of high quality wheat. This brochure provides information for international importers and stakeholders on Alberta''s wheat sector.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8d366ee-7162-4480-97cd-3076b64eab34', '4468519e-45b7-42e3-a131-b2181808b714', 'The bud box concept', 'Red Meat Producers Organisation (RPO) / Chemunique technical note', 2021, 'RPO technical note 11.6 (South Africa)', NULL, 'https://www.chemunique.co.za/', 'https://www.chemunique.co.za/wp-content/uploads/2021/05/RPO-11.6-The-bud-box-concept_AG.pdf', NULL, NULL, 4, NULL, 'other', 2, 'Industry technical note, freely distributed', 'A short industry note included only because it records Bud Williams'' own dimension recommendations in metric - between 3.7 and 4.2 m wide and between 6 and 9 m long - which bracket the imperial 12-14 ft by 20-30 ft range quoted in North American sources. Useful for reconciling the width disagreement between Kansas State (12 ft minimum), AgProud''s quotation of Williams (14 x 20 ft, and not wider because the handler ends up too far out in the middle), Arkansas (12 ft on foot, 16 ft mounted) and Hi-Hog. No measured outcomes.', '{sorting,bud-box,dimensions,industry,not-measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb3bddd2-30ea-4f46-87d4-268212d04087', '4468519e-45b7-42e3-a131-b2181808b714', 'The effect of abrupt weaning of suckler calves on the plasma concentrations of cortisol, catecholamines, leukocytes, acute-phase proteins and in vitro interferon-gamma production', 'Hickey, M.C.; Drennan, M.; Earley, B.', 2003, 'Journal of Animal Science 81(11):2847-2855', '10.2527/2003.81112847x', 'https://doi.org/10.2527/2003.81112847x', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Subscription (American Society of Animal Science / Oxford University Press)', 'The reference physiological description of abrupt weaning: increases in plasma cortisol, catecholamines, leukocyte redistribution and acute-phase proteins with altered interferon-gamma production. Also the source, via the Enriquez et al. 2011 review, of a result directly relevant to how pairs are gathered and sorted: separating a group of cows and their calves from the main herd five days before weaning was by itself sufficient to raise calf blood cortisol. Social disruption is a stressor independent of maternal separation.', '{weaning,abrupt,cortisol,acute-phase-protein,social-disruption,physiology,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('285a06bf-a3b6-49e3-a8b8-be8ddcd76da2', '4468519e-45b7-42e3-a131-b2181808b714', 'The effect of early weaning on feedlot performance and measures of stress in beef calves', 'Arthington, J.D.; Spears, J.W.; Miller, D.C.', 2005, 'Journal of Animal Science 83:933-939', '10.2527/2005.834933x', 'https://doi.org/10.2527/2005.834933x', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Subscription (American Society of Animal Science / Oxford University Press)', 'One of the reference studies on early weaning, measuring feedlot performance and stress markers in early-weaned beef calves. Relevant to the timing question on the prairies: early weaning (calves 1-5 months, or around 70-90 days of lactation in range systems) is the standard drought and thin-cow response, and the measured cow-side benefits come from US Great Plains work showing early-weaned cows end heavier and in better condition. Cited repeatedly in the acute-phase-protein weaning literature as the source of the early-weaning stress profile.', '{weaning,early-weaning,feedlot,stress-markers,timing,drought,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8bd1ddd-1e3e-45a0-9e61-987f05250c38', '4468519e-45b7-42e3-a131-b2181808b714', 'The effect of Lactobacillus helveticus supplementation on calf performance and gut health during the pre-weaning and post-weaning period', 'María Florencia Olmeda', 2023, 'The Atrium (University of Guelph)', NULL, 'https://hdl.handle.net/10214/27890', 'https://atrium.lib.uoguelph.ca/bitstreams/87dcc754-1ea6-4bc4-b729-b59dbfcfd382/download', NULL, NULL, 105, NULL, 'canada', 3, 'cc-by-nd', 'Promoting health, growth and well-being of dairy calves is vital to ensure the future of the lactating herd. Thus, preserving their health becomes essential, as it directly contributes to boosting their immune system and maximizing nutrient utilization. Therefore, the objectives of this research were to 1) evaluate the impact of tyndallized Lactobacillus helveticus (TLH) supplementation on growth and health metrics during the pre- and post-weaning period to Holstein calves, and 2) to evaluate if supplementing TLH can mitigate the adverse effects of an abrupt weaning model on gut barrier function and inflammation. Data from Chapter 2 demonstrates that TLH supplementation improves feed intake in the post-weaning period and tends to improve growth, whereas Chapter 3 suggests that TLH leads to a reduction in blood inflammatory-related markers. Based on these data, the use of TLH could enhance the recovery of calves exposed to abrupt weaning practices, promoting their health and performance.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('abb17e87-e8e9-464c-b293-1a2b415721dd', '4468519e-45b7-42e3-a131-b2181808b714', 'The effect of road and sea transport on inflammatory, adrenocortical, metabolic and behavioural responses of weanling heifers', 'Earley, B.; Murray, M.', 2010, 'BMC Veterinary Research 6:36', '10.1186/1746-6148-6-36', 'https://bmcvetres.biomedcentral.com/articles/10.1186/1746-6148-6-36', 'https://bmcvetres.biomedcentral.com/counter/pdf/10.1186/1746-6148-6-36.pdf', NULL, NULL, 13, NULL, 'other', 3, 'CC BY 2.0', 'Measures what transport does to freshly weaned heifers - inflammatory, adrenocortical, metabolic and behavioural responses to road and sea transport. Relevant to the truck-weaning question: Taylor et al. 2020 shows that shipping on the day of weaning or a week after costs 0.1-1.7 kg/d of gain, and this paper characterises the physiological side of why. Free full text and PDF.', '{weaning,transport,trucking,cortisol,inflammation,behaviour,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b13bc641-1012-47b4-a07f-992987eb0ddf', '4468519e-45b7-42e3-a131-b2181808b714', 'The Impact of Abrupt and Fenceline-Weaning Methods on Cattle Stress Response, Live Weight Gain, and Behaviour', 'Mac, S.E.; Lomax, S.; Doughty, A.K.; Thomson, P.C.; Clark, C.E.F.', 2024, 'Animals 14(11):1525', '10.3390/ani14111525', 'https://www.mdpi.com/2076-2615/14/11/1525', 'https://www.mdpi.com/2076-2615/14/11/1525/pdf', NULL, NULL, NULL, NULL, 'other', 5, 'CC BY 4.0', 'The best-instrumented fenceline study and the source of the 3-day recommendation. 32 Angus cow-calf pairs in Australia with ear-tag accelerometers recording behaviour minute by minute for 21 days, plus CCTV ethogram scoring, salivary cortisol and body weights at d0/7/14. Fenceline calves rested and ruminated more with less high activity across the first 3 days (ruminating 13% and 10% more on days 1-2); abrupt calves tripled baseline high activity on day 1 vs fenceline doubling it. Pacing was rare (<1% of time) but higher overall in abrupt calves (P<0.001). Vocalisation only trended higher in abrupt calves (P=0.052). Salivary cortisol did not differ between treatments at any timepoint. Fenceline calf ADG in week 1 was nearly 3x that of abrupt calves (P<0.001) yet body weight never differed at any weigh date; fenceline COWS gained less overall than abrupt cows (P<0.05) because their eating time fell on days 4-7. Fenceline calves were close to the barrier twice as often as abrupt calves on days 2-3 and then PEAKED on day 8 when the cows were finally trucked away (P<0.001) - the clearest evidence in the literature of a second stress spike from a long fenceline period. Fenceline calves made 37 suckling attempts through the fence over 7 days and 91 social contacts (47 calf-initiated, 44 cow-initiated). Authors recommend fenceline weaning for three days then total separation.', '{weaning,fenceline,abrupt,accelerometer,sensor,cortisol,behaviour,vocalisation,days-of-contact,measured}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('133a1d0b-e8a1-4ba2-8977-72204cf585e8', '4468519e-45b7-42e3-a131-b2181808b714', 'The influence of beef cow weaning weight ratio and cow size on feed intake behavior, milk production, and milk composition1', 'Alyson R Williams, Cory T Parsons, Julia M Dafoe, Darrin L Boss, Janice G. P. Bowman, Timothy DelCurto', 2018, 'Translational Animal Science', '10.1093/tas/txy044', 'https://doi.org/10.1093/tas/txy044', 'https://academic.oup.com/tas/article-pdf/2/suppl_1/S79/33234117/txy044.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Techniques that identify which beef cows in a production setting will produce more calf weight weaned per kilogram of feed consumed, often termed cow efficiency, has long been sought after in both beef cattle production settings and research (Dinkel and Brown, 1978; Scasta et al., 2015; Beck et al., 2016). Previous research and applied practice has suggested the ratio of calf weight weaned to cow weight, or weaning weight ratio (WWR), is a potential metric to estimate cow efficiency (Dinkel and Brown, 1978; Kress et al., 2001; Scasta et al., 2015). However, previous research either considered the direct ratio of calf weight weaned to cow weight or considered the additional effect of cow intake but utilized individual feed bunks with limited feeding times or fecal markers to estimate cow intake (Davis et al., 1983; Kirkpatrick et al., 1985; Kress et al., 2001). With modern technology (e.g., automated feed bunks and EID tags), it is easier to acquire accurate, individual feed intake data that may include feed intake behavior attributes (e.g., time spent feeding, number of feeding visits per day, and intake per visit), not previously reported in the literature. Milk yield and milk constituents have also been attributed to influence calf preweaning ADG but have not been revisited in recent years (Totusek et al., 1973; Mondragon et al., 1983; Beal et al., 1990). Furthermore, as defined by WWR, the effects milk production has on preweaning calf growth and the influence of cow feed intake on cow efficiency has not been jointly considered. Therefore, the purpose of this study was to evaluate cow–calf WWR, and within WWR, cow size influences on feed intake, milk production and composition, and subsequent calf preweaning performance. Protocols for this research were approved by the Montana State University Agricultural Animal Care and Use Committee (#2018-AA02). Lifetime production records from cows with a minimum of three calf crops and bred for the forth calf from the Montana State University Northern Agriculture Research Center Angus and Angus cross cow herd were used to identify high and low WWR groups. All calf data were corrected for age of dam, sex of calf and equalized to a 205-d adjusted weaning weight. Likewise, cow weights were adjusted to a standardized body condition before calculating WWR. All of the multiparous (minimum of three weaned calves), Angus cow–calf pairs (cow initial BW = 598 ± 55.7 kg) were stratified by WWR and randomly allotted to high and low WWR (whole plot; ± 0.75 SD from herd mean) and, within WWR classification groups, allotted to light and heavy weight groups. Because WWR was correlated to cow size with smaller cows typically having higher WWR, cow size was evaluated within WWR groups. This resulted in a randomized split-plot design with the following four classification groups: 1) high WWR–light BW (HL; 57% ± 3% WWR; 509 ± 8.6 kg), 2) high WWR–heavy BW (HH; 54% ± 1% WWR; 544 ± 16 kg), 3) low WWR–light BW (LL; 42% ± 4% WWR; 591 ± 9 kg), and 4) low WWR–heavy BW (LH; 43% ± 2% WWR; 632 ± 12 kg). Cow–calf pairs were contained in a dry-lot and fed ad libitum a commercially available pelleted grass/alfalfa diet designed to meet NRC requirements when consumed at 2.5% of BW (Table 1; CHS Nutrition, Sioux Falls, SD). Diets were provided in eight SmartFeedPro feeders, which were fully contained within two portable trailers (C-Lock Inc., Rapid City, SD). Cow–calf pairs had continuous access to water throughout the study period. BW were recorded for the cows and calves, and BCS were taken following a 16-h shrink prior to the start of the trial (Table 2). The trial consisted of a 14-d adaption period followed by a 7-d data collection period. Only cows that had calved within the first 3-wk of calving were used and mean calf age at trial initiation was 66.2 ± 2.8 d post partum (Table 2). As fed, individual cow average daily feed consumption (DFC), average daily feeding bout duration (FBD), number of visits per day (N', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8421fc5b-c5ad-4bab-b456-5a1feeaf3a99', '4468519e-45b7-42e3-a131-b2181808b714', 'The influence of beef cow weaning weight ratio and cow size on winter grazing and supplement intake behavior1', 'Alyson R Williams, Samuel A. Wyffels, Cory T Parsons, Julia M Dafoe, Darrin L Boss, Janice G. P. Bowman, Noah Davis, Timothy DelCurto', 2018, 'Translational Animal Science', '10.1093/tas/txy045', 'https://doi.org/10.1093/tas/txy045', 'https://academic.oup.com/tas/article-pdf/2/suppl_1/S84/33234502/txy045.pdf', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by-nc', 'An ongoing discussion in the beef cattle industry explores if small or large cows, based on BW and BCS, are more suited for arid, western environments, and production systems (Dickerson, 1978; Stewart and Martin, 1983; Scasta et al., 2015). The foundation to this discussion is what cow type is more efficient in western rangeland systems, converts forage consumed to more kilograms calf weaned, and optimizes use of extensive rangeland environments (Scasta et al., 2015; Beck et al., 2016). Previous research and applied practice have suggested the ratio of calf weight weaned to cow weight, or weaning weight ratio (WWR), is a potential metric to estimate cow efficiency (Dinkel and Brown, 1978; Kress et al., 2001; Scasta et al., 2015). However, few studies have examined the relationship between cow size, cow efficiency, and grazing behavior. Since extensive grazing systems are embedded in western rangeland beef cattle systems, attaining increased distribution across landscapes is vitally important for the success of these production systems. There has been considerable research on biotic and abiotic features that alter grazing distribution in beef cattle on rangeland environments (Ganskopp, 2001; Bailey, 2005; Stephenson et al., 2016). However, very little research has evaluated how cow type or cow characteristics influence grazing distribution on native landscapes (Bailey et al., 2006; VanWagoner et al., 2006; Walburger et al., 2009). Therefore, the purpose of this study was to assess whether cow efficiency as classified by cow WWR and cow size has an effect on grazing behavior and supplement consumption in a winter grazing environment. Protocols for this research were approved by the Montana State University Agricultural Animal Care and Use Committee (#2015-AA04). Lifetime production records from cows with a minimum of three calf crops and bred for the forth calf from the Montana State University Northern Agriculture Research Center Angus-based cow herd were used to identify high and low WWR groups. All calf data were corrected for age of dam, sex of calf and equalized to a 205-d adjusted weaning weight. Likewise, cow weights were adjusted to a standardized body condition (5 on a scale of 1–9) before calculating WWR. Forty multiparous (minimum of three weaned calves) Angus cows (cow initial BW = 598 ± 55.7 kg) were located in a 329-ha pasture at the Thackeray Ranch, 21-km south of Havre, MT (48.377236, −109.632802), for 45 d from December 1, 2016 to January 15, 2017 and 60 d from November 1 to December 31, 2017. Dominant vegetation in the pasture was Kentucky bluegrass (Poa pratensis), rough fescue (Festuca campestris), bluebunch wheatgrass (Pseudoroegneria spicata), and western wheatgrass (Pascopyrum smithii). Average forage production at study initiation was 2,456 and 3,156 kg/ha for 2016 and 2017, respectively. Prior to each grazing period, cows were stratified into a split-plot design by randomly allotting cows to high and low WWR groups (whole-plot; ±0.75 SD from herd mean) and, within WWR classification groups, allotted to light and heavy weight groups (subplots) using cow lifetime mean WWR and BW (Table 2), resulting in the following four classification groups: 1) high WWR-light BW (HL; 56% ± 2.4% WWR; 502 ± 21.4-kg BW), 2) high WWR-heavy BW (HH; 53% ± 1.6% WWR; 548 ± 21.2-kg BW), 3) low WWR-light BW (LL; 42% ± 2.9% WWR; 597 ± 18.7-kg BW), and 4) low WWR-heavy BW (LH; 42% ± 1.9% WWR; 642 ± 15-kg BW). Additionally, 20 cows, five from each group, were randomly assigned to wear a Lotek 3300LR GPS collar (Lotek Engineering, Newmarket, ON, Canada). Collars were programed to collect location iterations every 15 min, head position iterations every 5 min, and were placed on cows and removed at the time of cow weight and BCS data collection pre and post grazing period. A commercially available, fully fortified, 30% CP, salt-limited, pelleted supplement (CHS Nutrition, Sioux Falls, SD) was provided to the cowherd (Table 1). The suppl', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e3ccf1fb-ce65-4a06-a629-5a6d51e53dc2', '4468519e-45b7-42e3-a131-b2181808b714', 'The respiratory and fecal microbiota of beef calves from birth to weaning', 'Muhammed Salah Uddin, José Ortiz Guluarte, Matthew Waldner, Trevor W. Alexander', 2024, 'mSystems', '10.1128/msystems.00238-24', 'https://doi.org/10.1128/msystems.00238-24', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11264934/pdf/msystems.00238-24.pdf', NULL, NULL, 21, NULL, 'southern_alberta', 5, 'cc-by', 'ABSTRACT The development and growth of animals coincide with the establishment and maturation of their microbiotas. To evaluate the respiratory and fecal microbiotas of beef calves from birth to weaning, a total of 30 pregnant cows, and their calves at birth, were enrolled in this study. Deep nasal swabs and feces were collected from calves longitudinally, starting on the day of birth and ending on the day of weaning. Nasopharyngeal, vaginal, and fecal samples were also collected from cows, and the microbiotas of all samples were analyzed. The fecal microbiota of calves was enriched with Lactobacillus during the first 8 weeks of life, before being displaced by genera associated with fiber digestion, and then increasing in diversity across time. In contrast, the diversity of calf respiratory microbiota generally decreased with age. At birth, the calf and cow nasal microbiotas were highly similar, indicating colonization from dam contact. This was supported by microbial source-tracking analysis. The structure of the calf nasal microbiota remained similar to that of the cows, until weaning, when it diverged. The changes were driven by a decrease in Lactobacillus and an increase in genera typically associated with bovine respiratory disease, including Mannheimia , Pasteurella , and Mycoplasma . These three genera colonized calves early in life, though Mannheimia was initially transferred from the cow reproductive tract. Path analysis was used to model the interrelationships of calf respiratory and fecal microbiotas. It was observed that respiratory Lactobacillus and fecal Oscillospiraceae UCG-005 negatively affected the abundance of Mannheimia or Pasteurella . IMPORTANCE In beef cattle production, bovine respiratory disease (BRD) accounts for most of the feedlot morbidities and mortalities. Metaphylaxis is a common management tool to mitigate BRD, however its use has led to increased antimicrobial resistance. Novel methods to mitigate BRD are needed, including microbiota-based strategies. However, information on the respiratory bacteria of beef calves prior to weaning was limited. In this study, it was shown that the microbiota of cows influenced the initial composition of both respiratory and fecal microbiotas in calves. While colonization of the respiratory tract of calves by BRD-associated genera occurred early in life, their relative abundances increased at weaning, and were negatively correlated with respiratory and gut bacteria. Thus, microbiotas of both the respiratory and gastrointestinal tracts have important roles in antagonism of respiratory pathogens and are potential targets for enhancing calf respiratory health. Modulation may be most beneficial, if done prior to weaning, before opportunistic pathogens establish colonization.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f4e03095-12e8-4fcc-9abb-9627d7c17920', '4468519e-45b7-42e3-a131-b2181808b714', 'Trace mineral concentrations in Canadian beef calves at weaning.', 'Cheryl Waldner, John Campbell', 2024, 'PubMed Central', NULL, 'https://www.ncbi.nlm.nih.gov/pmc/articles/11132142', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11132142/pdf/cvj_06_565.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad68f5d3-4a33-432c-8671-1026cb4d1b2a', '4468519e-45b7-42e3-a131-b2181808b714', 'Transcriptomic analysis of the stress response to weaning at housing in bovine leukocytes using RNA-seq technology', 'Aran O’Loughlin, David John Lynn, Mark McGee, Seán Doyle, Matthew Sean McCabe, Bernadette Earley', 2012, 'BMC Genomics', '10.1186/1471-2164-13-250', 'https://doi.org/10.1186/1471-2164-13-250', 'https://bmcgenomics.biomedcentral.com/counter/pdf/10.1186/1471-2164-13-250', NULL, NULL, 18, NULL, 'other', 1, 'cc-by', 'BACKGROUND: Weaning of beef calves is a necessary husbandry practice and involves separating the calf from its mother, resulting in numerous stressful events including dietary change, social reorganisation and the cessation of the maternal-offspring bond and is often accompanied by housing. While much recent research has focused on the physiological response of the bovine immune system to stress in recent years, little is known about the molecular mechanisms modulating the immune response. Therefore, the objective of this study was to provide new insights into the molecular mechanisms underlying the physiological response to weaning at housing in beef calves using Illumina RNA-seq. RESULTS: The leukocyte transcriptome was significantly altered for at least 7 days following either housing or weaning at housing. Analysis of differentially expressed genes revealed that four main pathways, cytokine signalling, transmembrane transport, haemostasis and G-protein-coupled receptor (GPRC) signalling were differentially regulated between control and weaned calves and underwent significant transcriptomic alterations in response to weaning stress on day 1, 2 and 7. Of particular note, chemokines, cytokines and integrins were consistently found to be up-regulated on each day following weaning. Evidence for alternative splicing of genes was also detected, indicating a number of genes involved in the innate and adaptive immune response may be alternatively transcribed, including those responsible for toll receptor cascades and T cell receptor signalling. CONCLUSIONS: This study represents the first application of RNA-Seq technology for genomic studies in bovine leukocytes in response to weaning stress. Weaning stress induces the activation of a number of cytokine, chemokine and integrin transcripts and may alter the immune system whereby the ability of a number of cells of the innate and adaptive immune system to locate and destroy pathogens is transcriptionally enhanced. Stress alters the homeostasis of the transcriptomic environment of leukocytes for at least 7 days following weaning, indicating long term effects of stress exposure in the bovine. The identification of gene signature networks that are stress activated provides a mechanistic framework to characterise the multifaceted nature of weaning stress adaptation in beef calves. Thus, capturing subtle transcriptomic changes provides insight into the molecular mechanisms that underlie the physiological response to weaning stress.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e6464853-48f2-4b74-ab15-723503f32768', '4468519e-45b7-42e3-a131-b2181808b714', 'Two-step weaning in beef calves: permanence of nose flaps for 7 or 21 days does not influence the behaviour response', 'Alvez, P.; Quintans, G.; Hotzel, M.J.; Ungerfeld, R.', 2015, 'Animal Production Science', '10.1071/AN14643', 'https://www.publish.csiro.au/an/AN14643', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Subscription (CSIRO Publishing)', 'The direct test of how long a nose flap needs to stay in. Beef calves wore flaps for either 7 or 21 days before separation; the two treatments differed only on day 1 of the post-separation observation period, so tripling the flap period bought nothing behaviourally. Read together with Haley''s finding that 8 days gave no benefit over 4, and with Lippolis et al. 2016''s finding that 21 days depressed vaccine titres and pre-weaning ADG, this closes the case for short flap periods: 4-7 days, never 21.', '{weaning,two-stage,nose-flap,days-of-flap,behaviour,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('412dfe68-8934-4dea-beaa-3b3d685b731c', '4468519e-45b7-42e3-a131-b2181808b714', 'Weaning management of beef calves with implications for animal health and welfare', 'Lynch, E.M.; McGee, M.; Earley, B.', 2019, 'Journal of Applied Animal Research 47(1)', '10.1080/09712119.2019.1594825', 'https://doi.org/10.1080/09712119.2019.1594825', NULL, NULL, NULL, NULL, NULL, 'other', 4, 'Open access per DOAJ, but no downloadable PDF could be verified', 'The Teagasc review of weaning management with health and welfare implications, from the group that produced the Irish physiological and immunological weaning studies. Covers the methods, the stress markers and the health consequences, and is the most recent full review before the 2025 Animals review. Listed in DOAJ as open access; the publisher''s PDF could not be retrieved for verification.', '{weaning,review,welfare,immunology,health,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4ab4f944-d699-4714-82a9-d0f46186427d', '4468519e-45b7-42e3-a131-b2181808b714', 'Using Anti-suckling Devices to Wean Beef Calves (Circular 648)', 'Gifford, C. (revised); original authors Carter, B.; Mathis, C.; Loest, C.', 2019, 'New Mexico State University Cooperative Extension Service', NULL, 'https://pubs.nmsu.edu/_circulars/CR648/index.html', 'https://pubs.nmsu.edu/_circulars/CR648.pdf', NULL, NULL, 8, NULL, 'other', 4, 'NMSU Extension publication; may be freely reproduced with citation for educational purposes', 'The most practical free summary of nose-flap practice, and notable for recommending fenceline over flaps. Reports that conventionally weaned calves vocalised 20 times more often than two-stage calves at the same point of separation; that flapped calves walked about 15% MORE during stage 1 but conventionally weaned calves then took roughly twice as many steps after separation; and that calves generally gain less weight while the device is in and remained lighter or equal at 50 days post-weaning, so the stage-1 loss may not be fully compensated. Practical specifications: place flaps 4 to 7 days before separation (stage 1 may run up to 14 days to fit vaccination protocols); retention is reported at about 95%, and calves weighing less than 425 lb are more likely to lose the device; flaps cost approximately $2.00 each and can be reused; check for ridges that could irritate the nose; flaps can be placed at the same visit as pre-weaning vaccines about 2 weeks before weaning, but consult a veterinarian because 28 days of wear reduced antibody responses to vaccination. Conclusion: flaps and fenceline give similar behavioural benefit, fenceline calves may have a performance advantage, so use flaps only where fenceline is impractical.', '{weaning,two-stage,nose-flap,extension,retention,cost,days-of-flap,vaccination,calf-weight-threshold}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c7af6e0-8767-49d7-9c39-9db652b158a2', '4468519e-45b7-42e3-a131-b2181808b714', 'Weaned beef calves fed selenium-biofortified alfalfa hay have an enriched nasal microbiota compared with healthy controls', 'Jean A. Hall, Anitha Isaiah, Charles T. Estill, Gene J. Pirelli, Jan S. Suchodolski', 2017, 'PLoS ONE', '10.1371/journal.pone.0179215', 'https://doi.org/10.1371/journal.pone.0179215', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0179215&type=printable', NULL, NULL, 16, NULL, 'other', 1, 'cc-by', 'Selenium (Se) is an essential trace mineral important for immune function and overall health of cattle. The nasopharyngeal microbiota in cattle plays an important role in overall respiratory health, especially when stresses associated with weaning, transport, and adaptation to a feedlot affect the normal respiratory defenses. Recent evidence suggests that cattle diagnosed with bovine respiratory disease complex have significantly less bacterial diversity. The objective of this study was to determine whether feeding weaned beef calves Se-enriched alfalfa (Medicago sativa) hay for 9 weeks in a preconditioning program prior to entering the feedlot alters nasal microbiota. Recently weaned beef calves (n = 45) were blocked by sex and body weight, randomly assigned to 3 treatment groups with 3 pens of 5 calves per treatment group, and fed an alfalfa hay based diet for 9 weeks. Alfalfa hay was harvested from fields fertilized with sodium selenate at a rate of 0, 45.0 or 89.9 g Se/ha. Blood samples were collected biweekly and analyzed for whole-blood Se concentrations. Nasal swabs were collected during week 9 from one or two calves from each pen (total n = 16). Calculated Se intake from dietary sources was 3.0, 15.6, and 32.2 mg Se/head/day for calves consuming alfalfa hay with Se concentrations of 0.34 to 2.42 and 5.17 mg Se/kg dry matter, respectively. Whole-blood Se concentrations after 8 weeks of feeding Se-fertilized alfalfa hay were dependent upon Se-application rates (0, 45.0, or 89.9 g Se/ha) and were 155, 345, and 504 ng/mL (PLinear < 0.0001). Microbial DNA was extracted from nasal swabs and amplified and sequenced. Alpha rarefaction curves comparing the species richness (observed OTUs) and overall diversity (Chao1, Observed OTU, and Shannon index) between calves fed selenium-biofortified alfalfa hay compared with control calves showed that Se-supplementation tended to be associated with an enriched nasal microbiota. ANOSIM of unweighted UniFrac distances showed that calves fed high Se-biofortified alfalfa hay clustered separately when compared with control calves in the PCoA plot (R = 0.216, P = 0.04). The bacterial orders Lactobacillales and Flavobacteriales were increased in healthy control calves compared with Clostridiales and Bacteroidales being increased in calves fed Se-biofortified alfalfa hay. Although there were strong trends, no significant differences were noted for any of the bacterial taxa. Based upon these findings, we suggest that weaned beef calves fed Se-biofortified hay tend to have an enriched nasal microbiota. Feeding Se-biofortified alfalfa hay to weaned beef calves prior to entering the feedlot is a strategy for increasing nasopharyngeal microbial diversity.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('af42956a-63b8-4bd9-b47a-dbf26669a4bb', '4468519e-45b7-42e3-a131-b2181808b714', 'Weaning (topic page and 2023 Canadian Cow-Calf Survey adoption data)', 'Beef Cattle Research Council', 2024, 'Beef Cattle Research Council (beefresearch.ca)', NULL, 'https://www.beefresearch.ca/topics/weaning/', NULL, NULL, NULL, NULL, NULL, 'canada', 5, 'Beef Cattle Research Council web resource, freely accessible (no PDF)', 'The Canadian industry''s own synthesis, and the source of the adoption data and of the two Stookey videos that document the pair-sorting method. Reports the Haley et al. 2005 headline figures (two-stage calves vocalised 97% less, spent 23% more time eating and walked 5.8 km/day less over the four days after separation; their dams vocalised 84% less), recommends 4-5 days of nose paddle and at least 3-4 days of fenceline contact with sturdy fencing, and cites Boyles et al. 2007 for fence-line calves being treated about half as often as abruptly weaned calves. Also reports a Saskatchewan veterinarian''s producer-level figures of 5-10% treatment rates for low-stress weaned calves versus 25-30% for abruptly weaned calves - practitioner experience, not a study. Adoption, 2023 Canadian Cow-Calf Survey: over 32% of respondents used fence-line weaning and almost 12% used two-stage weaning, with fence-line use up more than 10 percentage points and two-stage use nearly doubled since the 2014 calf-crop survey; the main reason given for continuing abrupt weaning was that calves are marketed at weaning. Canadian weaning ages averaged 215 days (calves from cows) and 212 days (from heifers). Hosts Stookey''s 5-minute two-stage weaning video and 1.5-minute efficient cow-calf pair sorting video.', '{weaning,canada,adoption-survey,extension,sorting,fenceline,two-stage,weaning-age,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ab298d54-484b-4355-87cf-cc35af39d97e', '4468519e-45b7-42e3-a131-b2181808b714', 'Weaning and separation in two steps - A way to decrease stress in dairy calves suckled by foster cows', 'Loberg, J.M.; Hernandez, C.E.; Thierfelder, T.; Jensen, M.B.; Berg, C.; Lidfors, L.', 2008, 'Applied Animal Behaviour Science 111:222-234', '10.1016/j.applanim.2007.06.011', 'https://doi.org/10.1016/j.applanim.2007.06.011', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'Subscription (Elsevier)', 'The Swedish dairy counterpart to Haley''s work, and the paper whose sampling scheme Mac et al. 2024 adapted. Calves suckled by foster cows were weaned and separated in two steps rather than simultaneously; the two-step calves showed fewer behaviours indicative of distress such as vocalisation and locomotion. Useful as independent corroboration of the two-stage behavioural effect in a different production system and at a different age.', '{weaning,two-stage,dairy,foster-cow,behaviour,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf6badb0-a54f-44fc-b9ca-40cf31d04148', '4468519e-45b7-42e3-a131-b2181808b714', 'Weaning as Stressor for Calf Welfare', 'Guasco, C.; Moriconi, M.; Vitale, N.; Fusi, F.; Schleicherova, D.; Razzuoli, E.; Vevey, M.; Bergagna, S.', 2025, 'Animals 15(9):1272', '10.3390/ani15091272', 'https://www.mdpi.com/2076-2615/15/9/1272', 'https://www.mdpi.com/2076-2615/15/9/1272/pdf', NULL, NULL, NULL, NULL, 'other', 3, 'CC BY 4.0', 'A recent open-access review framing weaning as a welfare stressor, useful for an up-to-date reference list and for the current state of the behavioural and physiological indicator literature. Use it to check whether anything published since 2023 has changed the picture established by Price 2003, Haley 2005, Enriquez 2011 and the North American null results; it does not supply new field data.', '{weaning,review,welfare,stress-indicators,recent}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('92c1dc75-5506-47b2-803c-79b20abebeee', '4468519e-45b7-42e3-a131-b2181808b714', 'Welfare of beef cattle (EFSA Scientific Opinion)', 'EFSA Panel on Animal Health and Welfare (AHAW)', 2025, 'EFSA Journal 23', '10.2903/j.efsa.2025.9518', 'https://doi.org/10.2903/j.efsa.2025.9518', NULL, NULL, NULL, NULL, NULL, 'other', 3, 'CC BY-ND (PDF served as a forced download; could not be verified)', 'The current European scientific position on beef cattle welfare, covering husbandry practices including weaning. Included as the most recent authoritative welfare synthesis against which the Canadian Code update can be read, and because it reviews the same weaning literature from a regulatory-science standpoint rather than a production one. Published 2025.', '{weaning,welfare,review,regulation,EFSA,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a65ef780-883a-490a-b2ec-bb30dd483c5f', '4468519e-45b7-42e3-a131-b2181808b714', 'What Do We Know and Need to Know About Weaning in Sheep? An Overview of Weaning Practises, Stress and Welfare', 'Aline Freitas‐de‐Melo, Agustı́n Orihuela, María José Hötzel, Rodolfo Ungerfeld', 2022, 'Frontiers in Animal Science', '10.3389/fanim.2022.823188', 'https://doi.org/10.3389/fanim.2022.823188', 'https://www.frontiersin.org/articles/10.3389/fanim.2022.823188/pdf', NULL, NULL, 17, NULL, 'other', 1, 'cc-by', 'Artificial weaning is the separation of the mother and her lamb, involving the forced ending of suckling and milk supply by the ewes to their lambs. Artificial weaning time varies depending on the purpose of each sheep farm and the characteristics of the lambs, including age and weight of the lambs, and their ability to eat solid food. Artificial weaning is performed from 24 h postpartum until around the age of natural weaning (up to 12 mo of age). Artificial weaning results in the breaking of the ewe-lamb bond, the end of suckling and the complete replacement of milk by solid food, frequently added to changes in both the physical and social environment. It triggers behavioural, physiological and immunological changes that generate negative consequences on the health of both ewes and lambs, as well as on the growth of the lambs, rising animal welfare concerns. As artificial weaning is considered one of the most stressful situations in the life of farm mammals, it is important to consider the factors involved in those responses to develop adequate strategies and improve sheep welfare at weaning. The most frequently used method is the abrupt separation of the ewes and their lambs. However, the adaptation of the animals after weaning can be improved by alternative weaning methods (e.g., progressive, two-steps weaning and mixed regimes), hormonal treatments (e.g., administration of progesterone), and pre- and postweaning management (e.g., the use of creeping feeding, and the presence of conspecifics or humans after weaning). This review presents and summarises information on the stress response and animal welfare issues at artificial weaning in sheep and some management practises that can be used to reduce these problems. The major points included are the ewe-lamb bond at birth and during the lactation period; the stress response at weaning; the factors involved in the stress response at weaning; the different types and weaning methods and their repercussions on animal welfare; and some strategies that can be used to improve sheep welfare at weaning. Lastly, we propose directions for research needed to develop practical alternatives to minimise sheep''s stress response at weaning.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87b3af98-57cf-411c-884d-cb36a830835b', '765784df-ee6f-429e-88d6-02c0420dc217', 'A comparison of monensin and chlortetracycline when added to grain and forage based rations for implanted and non-implanted finishing steers and heifers', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/comparison-of-monensin-and-chlortetracyline-when-added-to-grain-and-forage-based-rations', 'https://open.alberta.ca/dataset/4c631a54-d7ac-43eb-9856-fa52ffc008e8/resource/f56c3d30-3aae-44eb-8770-2f712cdf7ef6/download/0163010273312-comparison-monensin-chlortetracyline-when-added-grain-forage-based-rations-for.pdf', NULL, NULL, 60, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This replicated experiment, conducted in the summers of 1982 and 1983, evaluated 452 steers and heifers fed ground hay or rolled barley diets supplemented with aureomycin or monensin, and implanted with Synovex S, Synovex H, or Ralgro. No significant differences were observed between aureomycin and monensin in animal performance, but monensin significantly reduced the acetic-to-propionic acid ratio. Implanted cattle fed grain diets had the best performance and leaner carcasses compared to forage-fed or non-implanted cattle. Replacing aureomycin with monensin reduced economic returns in most cases. The highest returns were achieved when aureomycin was used with Ralgro in grain-fed steers and Synovex in forage-fed steers and heifers.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('614aee7c-b120-49d8-aaf3-7c1bdc1e7b9d', '765784df-ee6f-429e-88d6-02c0420dc217', 'A social-ecological systems approach for the assessment of ecosystem services from beef production in the Canadian prairie', 'Sarah J. Pogue, Roland Kröbel, Henry H. Janzen, Aklilu W. Alemu, Karen Ann Beauchemin, Shannan M. Little, Majid Iravani, Danielle Maia de Souza', 2020, 'Ecosystem Services', '10.1016/j.ecoser.2020.101172', 'https://doi.org/10.1016/j.ecoser.2020.101172', 'https://www.sciencedirect.com/science/article/pii/S2212041620301145/pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by-nc-nd', 'Producing food to meet rising global demand requires a more thorough understanding of how farming systems can ensure food security without compromising economic, environmental, and social sustainability. This dilemma can be addressed through a social-ecological systems approach to ecosystem service assessment, which assesses the linkages between the different components of an agricultural social-ecological system – beef production in the Canadian Prairies. Using this framework, we documented the relationships between governance and management, social and ecological structures and processes, ecosystem services and human well-being for these systems. We also examined how this framework could aid in the greater integration of ecosystem services into decision-making and management practices for these systems. The framework was applied to all stages of the prairie beef production cycle, consisting of the cow-calf, backgrounding, finishing and feed production stages. The benefits, shortcomings and limitations of such an approach as well as the state of knowledge on relationships between the components of the system are discussed, and recommendations for future research directions, farm management strategies and policy are proposed. Overall, the high degree of heterogeneity in biophysical and socio-economic conditions across the prairie landscape underscores the need for more site-specific ecosystem service assessments and environmental stewardship policies that are tailored to these specific contexts.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7104a6ac-1a8a-4da2-9353-6003712e5d72', '765784df-ee6f-429e-88d6-02c0420dc217', 'Assessing supplementing strategies for beef cattle in a bale grazing system using grass hay during variable winter conditions', 'M. Undi, Kevin K K Sedivec, Jessalyn Juel Bachler', 2024, 'Frontiers in Animal Science', '10.3389/fanim.2024.1415622', 'https://doi.org/10.3389/fanim.2024.1415622', 'https://www.frontiersin.org/journals/animal-science/articles/10.3389/fanim.2024.1415622/pdf', NULL, NULL, 9, NULL, 'prairies', 4, 'cc-by', 'Introduction Beef cattle in the Northern Great Plains of the United States of America are normally kept in open dry lot pens in winter. Practices such as bale grazing, swath grazing, stockpiling, and corn residue grazing, can be used to extend the grazing season and minimize dry lot use. Extending the grazing season has several advantages over dry lot use but arguably the most important benefit is cost savings due to lower labor and input costs. Strategies selected to supplement cattle in extended grazing systems should maintain cost savings while providing required nutrients to cattle. This study was conducted to evaluate supplementing strategies for beef cattle in a bale grazing system using grass hay during variable winter conditions. The study was conducted across variable winter conditions that are encountered in winters in the US Northern Great Plains. Methods The study extended over four years. Each year, non-lactating pregnant beef cows (n = 64, year 1; n = 80, year 2, 3, 4) were divided into eight groups of similar average body weight and randomly assigned to one of four bale grazing treatments as follows: a) bale grazing grass hay, b) bale grazing grass hay treated with a liquid supplement, c) bale grazing grass hay and alfalfa hay, and d) bale grazing grass hay and plus 1.8 kg corn DDGS/head/day. Animal performance was assessed from two-day body weights and body condition scores taken at the start and end of the study. Data analysis considered the fixed effects of treatment, year, and treatment x year interaction. Results Final BW tended (P = 0.09) to be greatest following corn DDGS supplementation and lowest when grass hay was offered. The treatment strategy x year interaction (P = 0.026) for ADG showed that corn DDGS supplementation resulted in positive ADG across the years regardless of environmental conditions. Liquid or alfalfa hay supplementation resulted in positive ADG when environmental conditions were favorable. Final BCS (P = 0.005) and BCS change (P = 0.004) were greater following corn DDGS supplementation, intermediate following alfalfa hay or liquid supplementation and lowest when grass hay was fed. Supplementation costs ranged from $1.33 to $1.90/head/day, the highest cost occurred with corn DDGS supplementation mainly due to cost of corn DDGS and labor required to deliver corn DDGS to cattle on pasture. Discussion Alfalfa hay or molasses-based liquids increased diet CP content but did not supply adequate energy in severely cold winters. Despite relatively higher supplement costs, high energy supplements such as corn DDGS may be required in severely cold winters where cattle require extra energy. Supplement selection should consider supplement effectiveness to meet animal nutrient requirements particularly in adverse winter conditions such as those encountered in the US Northern Great Plains.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8d309e1-9b0a-4024-b6e6-81898e854571', '765784df-ee6f-429e-88d6-02c0420dc217', 'AgriProfit$ cost & returns profiles. Dryland swath grazing : Central Alberta (Aspen Parkland & portions of Boreal Transition)', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-cost-returns-profiles-dryland-swath-grazing-central-alberta', 'https://open.alberta.ca/dataset/c9cf40a2-94e3-459e-89f9-d6c76615d681/resource/8cebf912-dd3a-44c2-bcb3-6a84c904e751/download/2012-agriprofit-cost-returns-profiles-dryland-swath-grazing-central-alberta-2012-07-30.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'AgriProfit$ cost & returns profiles give an insight into the productive and economic performance of Alberta cereal, oilseed, forage and grazing crops, reported by soil or grass-type zone. These benchmark include AgriProfit$ field observations from the period of 2008 – 2010. Averaging over a 3 year span smooths out extremes in prices, yields and expenses. This gives a better reflection of the crops’ intermediate term costs and profit potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1a34b575-4563-41b9-a61e-caf80aa90b6e', '765784df-ee6f-429e-88d6-02c0420dc217', 'Agronomic management of swath grazed pastures', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4252352', 'https://open.alberta.ca/dataset/c68791b9-d574-41a7-bf43-dd4b82b65ea2/resource/4ddf55a5-5a61-48d9-96e3-c8db6765b21a/download/2008-420-56-3.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Feed, feeding, cow management and manure disposal can account for up to two-thirds of the total cost of production in a cow-calf operation. Systems that can extend the grazing season and reduce these costs are of great interest to cow-calf producers. One of these systems is swath grazing.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3d668a9-4666-4207-af9a-96344d2656ff', '765784df-ee6f-429e-88d6-02c0420dc217', 'An assessment of the environmental sustainability of beef production in Canada', 'Isaac Adjaye Aboagye, Gayathri Valappil, Baishali Dutta, Hugues Imbeault‐Tétreault, Kim Ominski, Marcos R. C. Cordeiro, Roland Kröbel, Sarah J. Pogue', 2024, 'Canadian Journal of Animal Science', '10.1139/cjas-2023-0077', 'https://doi.org/10.1139/cjas-2023-0077', 'https://utoronto.scholaris.ca/bitstreams/6b44afe4-68e2-4d53-bd77-942f33471bdc/download', NULL, NULL, 58, NULL, 'southern_alberta', 5, 'cc-by', 'This study assessed the environmental impacts of beef cattle production and their effects on the overall sustainability of Canadian beef production. Cradle to farm gate, cradle to processor’s gate, and cradle to consumer plate life cycle assessments were carried out to quantify greenhouse gases (GHG), resource use (i.e., water, land, and fuel), and potential water and air pollution (i.e., freshwater eutrophication, terrestrial acidification, and photochemical oxidants formation). Across the production chain, feed production had the greatest impact on most environmental indicators. The GHG intensity without dairy meat was estimated as 10.4 kg CO2-eq per kg of live weight (LW), corresponding to 32.8 kg CO2-eq per kg of consumed boneless beef. Including dairy meat reduced GHG intensity by 5.8% (0.6 kg CO2-eq kg LW–1) compared to when it was excluded. Other environmental metrics per kg of LW were 657 L, 38.7 m2 annual crop-eq, 0.4 kg oil-eq, 2.6 kg P-eq, 115.9 kg SO2-eq, and 8.7 kg NOx-eq for water use, land use, fossil fuel use, freshwater eutrophication, terrestrial acidification, and photochemical oxidants, respectively. Data provide benchmarks for use in future regional and national assessments that are designed to encourage the adoption of sustainable management practices that can lower the environmental footprint of Canadian beef production.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('483a0c7d-f7bf-43d1-a46a-044b7c23b374', '765784df-ee6f-429e-88d6-02c0420dc217', 'AN EVALUATION OF SEVERAL MEASUREMENTS OF BEEF COW SIZE AS RELATED TO PROGENY PERFORMANCE', 'H. B. JEFFERY, Roy T. Berg', 1972, 'Canadian Journal of Animal Science', '10.4141/cjas72-003', 'https://doi.org/10.4141/cjas72-003', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas72-003', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ed6b6c4a-97ba-47cd-9ee6-391634381a14', '765784df-ee6f-429e-88d6-02c0420dc217', 'An introduction to cattle feeding operations', 'Government of Alberta', 1970, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/introduction-to-cattle-feeding-operations-0163010352785', 'https://open.alberta.ca/dataset/0cda3145-6b1b-4810-ac2f-124663f1dbc9/resource/eb5d11fa-0cdd-449d-9c1d-0fc102c400a5/download/0163010352785-an-introduction-to-cattle-feeding-operations.pdf', NULL, NULL, 20, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A rapid increase in the number of cattle on feed in Alberta indicates that many farmers and ranchers are either venturing into the feedlot business for the first time or are expanding their feedlot operations. This publication is for the feeder who is relatively new to the business. It is intended to emphasize some of the important principles of feeding and husbandry.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b5aee765-bdb2-4725-96a1-71a250646706', '765784df-ee6f-429e-88d6-02c0420dc217', 'Assessing feed security for beef production within livestock-intensive regions', 'Marcos R. C. Cordeiro, Genet F. Mengistu, Sarah J. Pogue, Getahun Legesse, Kebebe E Gunte, Amanda M. Taylor, Kim Ominski, Karen Ann Beauchemin', 2021, 'Agricultural Systems', '10.1016/j.agsy.2021.103348', 'https://doi.org/10.1016/j.agsy.2021.103348', 'https://open-science.canada.ca/server/api/core/bitstreams/659042ac-88b2-4792-8464-f3e0e190d828/content', NULL, NULL, 14, NULL, 'southern_alberta', 5, 'cc-by-nc-nd', 'Feed insecurity caused by increases in animal inventories and variability in feed production due to climate change is an emerging issue in livestock production. Regional feed transfers are one strategy used to address local feed shortages and minimize feed insecurity. This study assessed the importance of regional feed transfers for beef production in Alberta, Canada, by estimating regional feed production and demand based on livestock (beef, dairy, poultry, swine, sheep, bison, and horses) numbers and categories, enabling calculation of regional deficits and surpluses. Transfers from crop-producing regions in Alberta were estimated to address potential feed shortages for beef production in 2001, 2006, 2011 and 2016. The analysis included feeds that could be cost-effectively transported, namely, barley grain, wheat grain, grass hay, and grass-legume hay. Feed demands of beef and other livestock were estimated at the county level and aggregated to seven land-use framework (LUF) regions. Feed balances available for beef production were estimated for the four feeds based on crop yields in each year. Feed transfers from surplus to deficit LUF regions were hierarchically estimated based on transport distance. Feed inputs from outside the province were not considered in the analysis due to the lack of data on cross-boundary imports. The average feed demand for beef production between 2001 and 2016 in Alberta was 2.71, 0.68, 2.21, and 1.95 M tonnes of dry matter (DM) for barley grain, wheat grain, grass hay, and grass-legume hay, respectively. The results indicated that the South Saskatchewan region of Alberta had the greatest feed deficit and required transfers from other regions in all years. Feed balances were consistently negative in this region between 2001 and 2016, with barley grain ranging from −97.2% to −34.2% (deficit), wheat grain from −31.4% (deficit) to 19.3% (surplus), grass hay from −147.2% (deficit) to 1.6% (surplus), and native grass-legume hay from −167.7% to −15.7% (deficit). Unmet demand of barley grain (2006), grass hay (2001) and grass-legume hay (2001, 2006) at the provincial level were likely met by importing these feedstuffs from outside of the province. The methodology presented here can be adapted to other intensive livestock producing regions to assess feed security issues associated with climate change and devise effective feed transfer strategies and provide information that can be used for future consideration of the regional impact of these practices on greenhouse gas emissions, biodiversity, as well as other environmental indices.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a41fba3b-7747-407d-99b0-ac49972a382c', '765784df-ee6f-429e-88d6-02c0420dc217', 'Beef cow body condition management', 'Government of Alberta', 2003, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2817858', 'https://open.alberta.ca/dataset/acf88b3d-707a-48f1-93fb-c17845a526f7/resource/6da0f79f-f27a-40a2-ab32-74b99063a1c5/download/2003-420-40-3.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Recognizing and managing the fall body condition of beef cows can add value to any operation. Winter feed costs can vary significantly depending on the body condition of the cows in the fall. Cows that are fatter in the fall will cost less to feed over winter than thin cows. When the winter feed costs for thin cows are compared to those for fat cows, the significance of body condition becomes clear. One body condition score on a cow going into the winter season can mean an extra cost or a saving of $35-60/cow, depending on feed costs and cow size.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6928f89f-2ead-493e-812e-837a36f813ee', '765784df-ee6f-429e-88d6-02c0420dc217', 'Beef ration rules of thumb', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3035887', 'https://open.alberta.ca/dataset/1ecf114e-04c5-42bf-a9f6-cb0a26888eb9/resource/13f4426e-75c1-411f-b127-0b059338e849/download/2004-420-52-4.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet can both guide producers through a feed test and help them understand the results. With a feed test in front of you, look at the following rules and compare them to the feed test. Remember, these are rules of thumb, which means they hold true most of the time, but variations in management and cow type will affect the end result. These rules of thumb should not be considered a replacement for balancing rations with proven software, but rather an aid to understand the feed and where it fits in the management.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('70731106-88c2-4790-8aae-eed9f8166d14', '765784df-ee6f-429e-88d6-02c0420dc217', 'Behavioral, cardiac and cortisol responses to brief peer separation and reunion in cattle', 'Boissy, Alain; Le Neindre, Pierre', 1997, 'Physiology & Behavior', '10.1016/S0031-9384(96)00521-5', 'https://www.sciencedirect.com/science/article/abs/pii/S0031938496005215', NULL, NULL, NULL, NULL, NULL, 'other', 5, 'unknown (Elsevier, closed access)', 'The controlled experiment that establishes social isolation as a major stressor in cattle, and the strongest measured finding in this entire review. Pen mates were removed from heifers WITHOUT the heifers themselves being handled, which isolates the stressor from any handling confound. All heifers responded with struggling and large increases in vocalization, heart rate and plasma cortisol, and the authors conclude that social deprivation is a very effective psychological stress in cattle. The finding with the most direct design consequence comes on reunion: behavioral responses, that is struggling and vocalization, decreased when conspecifics were brought back, INDEPENDENTLY of their familiarity to the subject. That means any companion animal relieves the stress, not only a familiar pen mate - so a corral''s lone-animal remedy can be any available animal, and the app should not require a specific companion. Cited by EFSA 2025 as primary evidence for social support and buffering effects. Caveat: the test isolated animals in confinement, so magnitudes may not transfer directly to a crowd pen.', '{behaviour,isolation,controlled-experiment,cortisol,heart-rate,vocalisation,struggling,companion-animal,familiarity-irrelevant,social-buffering,no-free-pdf}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('26c3a757-b25c-4c03-ab82-d9e0e2cf2ebc', '765784df-ee6f-429e-88d6-02c0420dc217', 'Benchmarking calving management practices on western Canada cow-calf operations', 'Pearson JM, Pajor EA, Caulkett NA, Levy M, Campbell JR, Windeyer MC', 2019, 'Translational animal science', '10.1093/tas/txz107', 'https://doi.org/10.1093/tas/txz107', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7200546.1/PMC7200546.1.pdf', NULL, NULL, 14, NULL, 'alberta', 4, 'cc by-nc', 'Benchmarking current calving management practices and herd demographics in the western Canadian cow-calf production system helps to fill the gap in knowledge and understanding of how this production system works. Further investigation into the relationships between management decisions and calf health may guide the development of management practices and protocols to improve calf health, especially in compromised calves after a difficult birth. Therefore, the objectives of this cross-sectional study were to describe current calving management practices on western Canadian cow-calf ranches and to investigate the association of herd demographics with herd-level incidence of calving assistance, morbidity, mortality, and use of calving and colostrum management practices. Cow-calf producers were surveyed in January 2017 regarding herd inventory and management practices during the 2016 calving season. Ninety-seven of 110 producers enrolled in the western Canadian Cow-Calf Surveillance Network responded. Average herd-level incidence of assisted calvings was 4.9% (13.5% heifers, 3.2% cows), stillbirths was 2.1% (3.3% heifers, 1.9% cows), preweaning mortality was 4.5%, and preweaning treatment for disease was 9.4% (3.0% neonatal calf diarrhea, 3.8% bovine respiratory disease, 2.6% other diseases). Greater than 90% of producers assisted calvings and would intervene with colostrum consumption if the calf did not appear to have nursed from its dam. Late calving herds (i.e., started calving in March or later) had significantly lower average herd-level incidence of assistance, treatment for disease, and mortality (P P P P > 0.05). This study suggests that in western Canada earlier calving herds are more intensively managed, whereas later calving herds are more extensively managed. Herd demographics may be important to consider when investigating factors associated with management strategies, health, and productivity in cow-calf herds.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('25d7c0f7-382e-4b9e-9f57-e2a34929c853', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Multiple evolutionary origins of glyphosate resistance in Lolium multiflorum', 'Brunharo CACG, Streisfeld MA', 2022, 'Evolutionary applications', '10.1111/eva.13344', 'https://doi.org/10.1111/eva.13344', 'https://europepmc.org/articles/PMC8867705?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The multitude of herbicide resistance patterns that have evolved in different weed species is a remarkable example of the rapid adaptation to anthropogenic-driven disturbance. Recently, resistance to glyphosate was identified in multiple populations of Lolium multiflorum in Oregon. We used phenotypic approaches, as well as population genomic and gene expression analyses, to determine whether known mechanisms were responsible for glyphosate resistance and whether resistance phenotypes evolved independently in different populations, and to identify potential loci contributing to resistance. We found no evidence of genetic alterations or expression changes at known target and non-target-site resistance mechanisms of glyphosate. Population genomic analyses indicated that resistant populations tended to have largely distinct ancestry from one another, suggesting that glyphosate resistance did not spread among populations by gene flow. Rather, resistance appears to have evolved independently on different genetic backgrounds. We also detected potential loci associated with the resistance phenotype, some of which encode proteins with potential effects on herbicide metabolism. Our results suggest that Oregon populations of L. multiflorum evolved resistance to glyphosate due to a novel mechanism. Future studies that characterize the gene or genes involved in resistance will be necessary to confirm this conclusion.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c9627327-6a66-4393-ab01-b135bb6de2f4', '765784df-ee6f-429e-88d6-02c0420dc217', 'Body condition : implications for managing beef cows', 'Government of Alberta', 1988, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2392247', 'https://open.alberta.ca/dataset/fcf26bae-dc99-4fae-b277-b0bafe025bad/resource/cacae2f9-c5e0-4a12-994d-de72618cf5d8/download/1988-420-40-1.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Body condition, or the amount of body fat an animal is carrying, is one management indicator that can be used to predict herd fertility and determine feeding programs. This fact sheet is intended to make producers aware of the condition scoring system, what effects various condition scores will have on herd fertility, and to offer some management strategies regarding feeding and when to condition score to optimize both fertility and economics.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ead4bb9b-be44-4c2c-9c8c-1495b7368a17', '765784df-ee6f-429e-88d6-02c0420dc217', 'Calculator for Determining Livestock Capacity of Operations as They Existed on January 1, 2002', 'Natural Resources Conservation Board (Alberta)', 2016, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/7bbdee77-f0d0-485b-8d9d-e573dadd6ad3', 'https://open.alberta.ca/dataset/7bbdee77-f0d0-485b-8d9d-e573dadd6ad3/resource/896613c6-f14b-4216-87e6-ade14c97c3a5/download/0163310438227-calculator-determining-livestock-capacity-operations-they-existed-january-1-2002.pdf', NULL, NULL, 4, NULL, 'alberta', 2, 'Open Government Licence - Alberta', 'The NRCB worksheet for establishing an operation''s grandfathered livestock capacity as at 1 January 2002, which determines whether expanding a pen or yard pushes the operation into confined feeding operation permitting. Worth having if the designer ever lets the ranch add pen capacity.', '{standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a70be4e-6527-407f-b88d-ed160682d665', '765784df-ee6f-429e-88d6-02c0420dc217', 'Cattle wintering sites : managing for good stewardship', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2448125', 'https://open.alberta.ca/dataset/6a274f94-cb31-4e7e-b26c-2c848efc590c/resource/b47db80c-0967-4fd3-ac2b-edfa4d3882fd/download/2001-420-580-2.pdf', NULL, NULL, 24, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'It''s up to you to keep your landscape healthy. Environmental issues are becoming paramount in how you manage your operation. By understanding how your operation fits into the bigger environmental picture, it becomes necessary to look for problems and apply common sense solutions. This publication gives you practical solutions to choosing those management practices that best suit your land, cattle and operating budget. It''s important to remember that no two wintering sites are the same. Manure management problems are different for every operation. The ultimate goal for any livestock operation is to improve the health of your landscape, and increase productivity. It all comes down to good stewardship for future generations.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d239cc4d-1afe-4ab7-bd14-bb79680d7f88', '765784df-ee6f-429e-88d6-02c0420dc217', 'Characterization of new sainfoin populations for mixed alfalfa pastures in western Canada', 'Edmund Tei Sottie', 2014, 'Open ULeth Scholarship (OPUS) (University of Lethbridge)', NULL, 'http://hdl.handle.net/10133/3417', 'http://hdl.handle.net/10133/3417', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8be6164-d9c0-4e9d-9653-83d54b085f60', '765784df-ee6f-429e-88d6-02c0420dc217', 'Development of an efficiency ranking system for beef cows and effects on feed intake, ruminal fermentation, NDF turnover, and apparent total tract digestibility', 'Justin J Delver, H.A. Lardner, J. J. McKinnon, Gabriel O Ribeiro, Mika Asai-Coakwell, G.B. Penner', 2023, 'Canadian Journal of Animal Science', '10.1139/cjas-2023-0004', 'https://doi.org/10.1139/cjas-2023-0004', 'https://cdnsciencepub.com/doi/pdf/10.1139/cjas-2023-0004', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'Beef cows ( n = 100) were ranked for efficiency based on cow rump fat thickness at calving, calving date, and calf weaning weight (% dam BW) over 2 years. The nine most (ME) and least efficient (LE) cows were used to compare feed intake and ruminal fermentation using four 26-day periods with decreasing dietary nutrient density. There were no phenotype × diet interactions for variables of primary interest. Rump fat and calf weaning weight were greater, and the calving date was earlier for ME cows than LE cows ( P ≤ 0.032). The ME cows were lighter ( P < 0.001) but had similar DMI ( P = 0.93) to the LE cows, resulting in greater dry matter intake (DMI) %BW ( P < 0.001). Ruminal contraction amplitude height and area ( P ≤ 0.015) and ruminal digesta weight were greater for LE than ME cows ( P = 0.043). Ruminal ash-free neutral detergent fiber (aNDFom) passage was greater for ME cows than LE cows ( P = 0.047), but the rate of aNDFom degradation did not differ ( P = 0.69). Total tract digestibility did not differ. Efficient cows had greater rump fat, weaned heavier calves, ate more relative to their BW, had a smaller ruminal digesta mass, and had greater ruminal passage of aNDFom without reducing digestibility.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('84128cbc-abea-46f8-81fd-3f0e833780f5', '765784df-ee6f-429e-88d6-02c0420dc217', 'Digestibility of western Canadian finishing beef cattle diets when short-season, high-moisture shelled corn and snaplage partially replace dry-rolled barley grain and barley silage', 'Rachel E Carey, Zachary D. Paddock, Gabriel O Ribeiro, Tim Angus McAllister, G.B. Penner', 2023, 'Canadian Journal of Animal Science', '10.1139/cjas-2022-0122', 'https://doi.org/10.1139/cjas-2022-0122', 'https://cdnsciencepub.com/doi/pdf/10.1139/cjas-2022-0122', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by', 'The objective of this study was to determine the effects of substituting barley grain with short-season, high-moisture shelled corn, and barley grain and barley silage with snaplage on ruminal fermentation and the site and extent of digestion in beef cattle fed finishing diets. Six ruminally and duodenally cannulated heifers (420 ± 16.4 kg body weight) were fed a barley grain and silage finishing diet (BG), a diet where half of the barley grain was replaced with high-moisture shelled corn (HC), or a diet where the barley silage and a portion of grain were replaced with snaplage (SN) in a replicated 3 × 3 Latin square design. While dry matter and starch intake were unaffected, feeding SN resulted in greater ( P = 0.02) ruminal but not total tract starch digestibility than BG. Ruminal pH did not differ between HC and BG, but SN reduced ( P = 0.02) minimum ruminal pH relative to BG. Feeding BG increased ( P = 0.04) ruminal ammonia concentrations over HC. In conclusion, high-moisture shelled corn can partially replace barley grain with minimal impact on nutrient digestibility or ruminal fermentation, but replacement of barley silage and some barley grain with snaplage may increase the risk of ruminal acidosis.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a30f8ca-4544-4075-8854-9ffed1c92b58', '765784df-ee6f-429e-88d6-02c0420dc217', 'Effect of rest, post-rest transport duration, and conditioning on performance, behavioural, and physiological welfare indicators of beef calves', 'Meléndez DM, Marti S, Haley DB, Schwinghamer TD, Yang X, Schwartzkopf-Genswein KS', 2022, 'PloS one', '10.1371/journal.pone.0278768', 'https://doi.org/10.1371/journal.pone.0278768', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9714911.1/PMC9714911.1.pdf', NULL, NULL, 27, NULL, 'southern_alberta', 5, 'cc by', 'The aim of this study was to assess the effects of conditioning, rest, and post-rest transport duration on welfare indicators of 6-7 mo old beef calves following a 20-h transport. Three hundred and twenty-eight weaned calves (237 ± 29.7 kg of BW) were randomly assigned to a 2 × 2 × 2 nested factorial design: conditioning, conditioned (C) or non-conditioned (N); rest, 0 (R0) or 8 (R8) h, and post-rest transport, 4 (T4) or 15 (T15) h. Calves were sampled before (LO1) and after (UN1) the initial 20-h journey, before (LO2) and after (UN2) the additional 4 or 15-h journey, and at 1, 2, 3, 5, 14, and 28 d after UN2. Data was analyzed using the GLIMMIX procedure of SAS. Fixed effects included conditioning, transport, and time nested within rest period, while random effects included animal and pen. Greater shrink (p < 0.01) was observed in C than N calves after the initial 20-h transport. During the first week after transportation, the mean ADG of N calves was greater than C calves (p < 0.01). From d 14 to d 28, however, the mean ADG of C calves was greater than N calves (p < 0.01). Flight speed, cortisol and L-lactate concentrations were greater (p ≤ 0.05) in C than N calves between LO1 and d 5, while greater (p ≤ 0.02) non-esterified fatty acids, creatine kinase, serum amyloid-A, and haptoglobin concentrations were observed in N than C calves between LO1 and d 3. The R8-T4 calves had greater (p < 0.01) ADG than R8-T15 calves between LO1 and d 5. The R0-T4 calves had greater L-lactate concentrations than R0-T15 and R8-T4 calves (both p = 0.02) on d 1. The R0 calves had greater (p < 0.01) ADG than R8 calves between 14 and 28 d. This study suggests that C calves are better fit for transport than N calves as evidenced by behavioural and physiological parameters. Fewer and inconsistent differences were observed for rest and post-rest transport treatments.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d039d0bf-1b95-4e6d-996d-66decf1a6475', '765784df-ee6f-429e-88d6-02c0420dc217', 'Effect of winter feeding systems on farm greenhouse gas emissions', 'Aklilu W. Alemu, Raquel R. Doce, A. C. Dick, J. A. Basarab, Roland Kröbel, Karen Haugen-Kozyra, Vern S. Baron', 2016, 'Agricultural Systems', '10.1016/j.agsy.2016.06.008', 'https://doi.org/10.1016/j.agsy.2016.06.008', 'https://www.sciencedirect.com/science/article/pii/S0308521X16302876/pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by-nc-nd', 'Overwintering beef cows is a major cost in Canadian cow-calf production systems and swath grazing is a potential alternative to reduce winter feeding cost relative to the traditional drylot feeding systems. The objective was to estimate and compare greenhouse gas (GHG) emissions from winter feeding systems: i) swath grazing on triticale, ii) swath grazing on corn, and iii) conventional drylot feeding systems (control). Data were obtained from a study conducted over three production cycles (2008/2009, 2009/2010, 2010/2011) at the Lacombe Research Center in western Canada. Greenhouse gas emissions were estimated by calculating methane (CH 4 ), nitrous oxide (N 2 O) and carbon dioxide (CO 2 ) emissions from different sources using Intergovernmental Panel on Climate Change (IPCC) Tier 2 approach. Methane emissions were estimated from enteric fermentation and manure, N 2 O emissions from fertilization and manure, and CO 2 emissions from energy use for farm activities related to feed production and processing, feed and bedding delivery and manure removal. Total emission expressed per kg of feed produced and fed were significantly ( P < 0.001) lower for both the swath grazing treatments relative to the control treatment. Emissions per cow varied among treatments ( P < 0.001), higher for control (12.3 kg CO 2 e cow-d − 1 ) than corn (9.4 kg CO 2 e cow-d − 1 ), with triticale (11.0 kg CO 2 e cow-d − 1 ) intermediate. In all the treatments, the largest fraction of emissions was enteric CH 4 (69–76%), followed by N 2 O (14–24%). The contribution of energy-derived CO 2 emissions for total GHG emissions was lower in swath grazing treatments (5–7%) compared to a traditional feeding system (11%) due to their minimal energy use. Farm activity related energy use was 9.4, 11.5 and 21.4 MJ cow-d − 1 for triticale, corn and conventional drylot feeding, respectively. This study indicated that swath grazing on triticale or corn can be an effective alternative winter feeding systems to reduce GHG emissions and increase energy use efficiency of Canadian beef cattle industry.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('efccb1d0-dfcd-4b08-8529-7697aa96003a', '765784df-ee6f-429e-88d6-02c0420dc217', 'Effects of a polycrop or oat monocrop on forage yield, nutritive value, utilization, and weaned steer performance for winter swath grazing', 'Somtochukwu N Obiora, Janet Nowosad, Oluwatobi Oyedeji, Carien Vandenberg, Kathy Larson, Breeanna Kelln, H.A. Lardner, Obioha N Durunna', 2026, 'Canadian Journal of Animal Science', '10.1139/cjas-2025-0065', 'https://doi.org/10.1139/cjas-2025-0065', 'https://harvest.usask.ca/bitstreams/e17874c2-8f2f-4745-abdf-baaa7f26e5a0/download', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'This 3-year study assessed winter beef cattle performance swath-grazing either (i) polycrop system (PC) comprising CDC-SO1 oat ( Avena sativa L.), Golden Globe turnip ( Brassica rapa L.), Hunter turnip ( Brassica rapa L.), Goliath forage rape ( Brassica napus L.), and 4010 forage pea ( Pisum sativum L.) or (ii) a monocrop system (oats monocrop system, OMC; CDC-SO1 oats). Other evaluations included dry matter (DM) yield at oat’s soft dough (SD) and hard dough (HD) stages, nutrient composition, estimated DM intake and economics. A 12 ha field was subdivided into six, 2 ha paddocks. Each paddock was assigned to PC or OMC treatment. Crossbred beef steers’ initial body weight (BW) averaged 267 ± 14.1 kg at allocation to each forage system. The OMC had a greater ( P < 0.01) DM yield than PC. Compared to the SD stage, neutral detergent fibre (NDF) at HD decreased ( P = 0.03) by 5.9%, starch increased ( P < 0.01) by 36.8%, and total digestible nutrients increased ( P = 0.01) by 2.5%. The average daily gains of steers grazing the OMC or PC were similar ( P = 0.47). Swath cost per kg steer gain was lower ( P = 0.04) for OMC ($0.62 kg −1 ) than PC ($0.91 kg −1 ). The PC retained higher post-graze swath crude protein and lower NDF than OMC.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8fd5ee6-2391-465f-80cb-11151e4a3b28', '765784df-ee6f-429e-88d6-02c0420dc217', 'Effects of nutrition on beef cow reproduction', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4563674', 'https://open.alberta.ca/dataset/2afbf9e4-173e-4898-9cee-546bcb7b5601/resource/7f294e60-1f68-4ef4-b386-3eb7add51245/download/2009-420-51-1.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The nutritional quality of feeds and forage can have a tremendous influence on the reproductive performance of cattle. This document describes the effect of deficiencies and imbalances of both macro and micro nutrients on reproductive performance.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6096f933-35ef-4910-ae75-763fdd695aed', '765784df-ee6f-429e-88d6-02c0420dc217', 'Short-season high-moisture shelled corn, snaplage, or corn silage as a partial replacement for dry-rolled barley grain or barley silage in western Canadian beef cattle finishing diets', 'Rachel E Carey, Gabriel O Ribeiro, Zachary D. Paddock, D. Moya, Tim Angus McAllister, G.B. Penner', 2023, 'Canadian Journal of Animal Science', '10.1139/cjas-2023-0032', 'https://doi.org/10.1139/cjas-2023-0032', 'https://cdnsciencepub.com/doi/pdf/10.1139/cjas-2023-0032', NULL, NULL, NULL, NULL, 'southern_alberta', 4, 'cc-by', 'The objective was to evaluate the replacement of barley-based ingredients with short-season high-moisture corn products on steer growth performance and carcass characteristics. Over 2 years, 320 beef steers (528 ± 36.2 kg initial body weight) were assigned to 32 pens (4 pens/treatment/year). Treatments were finishing diets that contained dry-rolled barley grain and barley silage (BGBS; control), barley grain and corn silage (BGCS), high-moisture shelled corn and barley grain with barley silage (HCBS), or snaplage (included as a silage and grain source) with barley grain (SNAP). Steers were fed for 99 days and 72 days in years 1 and 2, respectively. Steers fed BGCS did not differ ( P ≥ 0.13) from BGBS for dry matter intake, average daily gain, gain:feed, or carcass characteristics. Steers fed HCBS had greater ( P ≤ 0.05) hot carcass weight and dressing percentage than BGBS. A lesser ( P = 0.02) proportion of steers fed SNAP had severe liver abscesses than BGBS. We concluded that corn silage can replace barley silage, 50% replacement of barley grain with high-moisture shelled corn may improve hot carcass weight, and replacement of barley silage and some barley grain with snaplage decreases the proportion of cattle with severe liver abscesses at slaughter.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0898bd07-e497-472d-875e-38dee1449321', '765784df-ee6f-429e-88d6-02c0420dc217', 'Effects of supplemental dietary protein, sulfur and hormonal implants on growth performance and carcass quality of beef steers', 'Government of Alberta', 1987, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/effects-of-supplemental-dietary-protein-sulfur-and-hormonal-implants-on-growth-performance-and', 'https://open.alberta.ca/dataset/ad31ec83-6f64-40a4-a338-5d14a6133039/resource/a3b5500a-fe44-4c53-b598-3c9bbd9623e2/download/0163003260540-effects-supplemental-dietary-protein-sulfur-hormonal-implants-growth-performance.pdf', NULL, NULL, 84, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated the effects of supplementing barley-based diets with sulphur (as sodium sulfate), protein (as canola meal and urea), or their combination on the growth and carcass traits of 192 yearling Hereford steers, and also compared the impact of two hormonal implants (Ralgro and Compudose) with a non-implanted control. Over an 84-day feeding trial, dietary treatments had no significant effect on average daily gain (ADG), dry matter intake (DMI), or dry matter-to-gain ratio, though steers implanted with Ralgro and Compudose showed significantly improved feed efficiency and economic returns. Carcass traits were unaffected by diet but tended to be leaner with implants. The study concluded that implants, not dietary additions, were the primary contributors to improved performance and profitability, and recommended further large-scale trials to confirm these findings.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1414b4df-4413-40a6-a2ff-22946228d0ed', '765784df-ee6f-429e-88d6-02c0420dc217', 'Environmental Standards for Alberta''s Livestock Industry: 2008 Reference Guide, Agricultural Operation Practices Act (AOPA)', 'Alberta Agriculture and Rural Development; Natural Resources Conservation Board', 2014, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/77240ca8-a51d-4f5a-a162-ab3779294456', 'https://open.alberta.ca/dataset/77240ca8-a51d-4f5a-a162-ab3779294456/resource/70eb491e-a42f-4f6c-b152-3d2199b93aff/download/2014-referenceguide-may2014.pdf', NULL, NULL, 24, NULL, 'alberta', 5, 'Open Government Licence - Alberta', 'The consolidated AOPA reference guide (May 2014 printing of the 2008 guide). Gives the statutory citations behind the corral siting rules and two distinctions a corral designer must not blur. First, Standards and Administration Regulation section 4: seasonal feeding and bedding (wintering) sites and livestock corrals need no permit but must be sited at least 30 m from a common body of water, failing which runoff must be diverted or manure removed before a runoff event. Second, Act section 1: a manure collection area means the floor of a barn, under-floor pits, the floor of a feedlot pen and a catch basin, and expressly does not include the floor of a livestock corral - so a working corral floor is not subject to the manure storage construction standard but a feedlot pen floor is. Also covers confined feeding operation permits, Minimum Distance Separation, manure application setbacks (including 30 m from a water well), incorporation within 48 hours, nitrogen and salinity limits, and nutrient management plans.', '{standard,extension}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('502e6c23-8131-44b7-9df1-b6f97b784e36', '765784df-ee6f-429e-88d6-02c0420dc217', 'Evaluation of annual and perennial forages for late fall/early winter stockpile grazing of beef cattle in Manitoba', 'Brittainy Hewitt', 2018, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/33402', 'https://mspace.lib.umanitoba.ca/bitstreams/7dfce779-cd6a-4703-b967-c988785f0826/download', NULL, NULL, 188, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c0cab70-0986-4849-ab03-d399129f2528', '765784df-ee6f-429e-88d6-02c0420dc217', 'Evaluation of Forage Type Barley Varieties for Forage Yield and Nutritive Value in the Peace Region of Alberta', 'Kabal Singh Gill, Akim Tunde Omokanye, J.P. Pettyjohn, Meghan Elsen', 2013, 'Journal of Agricultural Science', '10.5539/jas.v5n2p24', 'https://doi.org/10.5539/jas.v5n2p24', 'https://ccsenet.org/journal/index.php/jas/article/download/22305/15170', NULL, NULL, 13, NULL, 'alberta', 4, 'cc-by', 'There is increasing use of barley (Hordeum vulgare L.) forage for swath grazing, bale grazing and silage for back grounding and finishing beef cattle in western Canada. Twelve barley varieties (6 two row and 6 six row) were compared in field trials in the Peace Region of Alberta, from 2009 to 2011, to identify the varieties with superior forage yield and nutritive value. Forage yield dry matter (DM) yield was greatest for Busby, followed by Ponoka, CDC Cowboy, Seebe, CDC Austenson, Vivar, Chigwell, Sundre, Xena, Trochu, AC Lacombe, and AC Ranger. Eight varieties had > 8.0 t ha-1 DM yield, five of which belonged to the two-row barley. The crude protein (CP) content varied from 8.70% for Busby to 10.4% for Seebe. Based on high CP content and low detergent fiber contents, CDC Austenson, Chigwell and Ponoka were the top three varieties. Two of the top three varieties for both forage yield and nutritive value were the two-row type, an indication that the two-row barley type may be better adapted for forage production in this environment. The top rated varieties may therefore be chosen for silage, green feed or swath grazing system in the Peace Region environs.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cad3a2f8-1ebe-4f5c-9aff-d87826bf61a2', '765784df-ee6f-429e-88d6-02c0420dc217', 'Evaluation of Swath Grazing Simple and Complex Polycrop Mixtures on Forage Biomass and Quality, Beef Cow Performance and Enteric Methane Emissions, System Economics and Soil Health Characteristics', 'Shelby M Robinson', 2025, 'HARVEST (University of Saskatchewan)', NULL, 'https://hdl.handle.net/10388/17673', 'https://harvest.usask.ca/bitstreams/2897682b-3956-4600-a6b2-fd942a7a20fc/download', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ddab88e5-6698-46c3-a3e4-4434ee11f067', '765784df-ee6f-429e-88d6-02c0420dc217', 'Exploration backgrounder', 'Government of Alberta', 2003, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/exploration-backgrounder', 'https://open.alberta.ca/dataset/288fbb06-8ecd-4738-a95e-dec1da82d066/resource/fa72af14-d0ff-4d75-b8d0-ab20b3e5e9cb/download/3062911-2003-exploration-backgrounder.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'In 2003, the Alberta Government clarified the rules for recreational and exploration access on agricultural dispositions issued under the Public Lands Act, including grazing leases and farm development leases. This backgrounder provides information on surface right compensation as a result of the passage of the Agricultural Dispositions Statues Amendment Act (Bill 16).', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('069f222b-b2b9-4c9e-a9d0-73f9d32aaff5', '765784df-ee6f-429e-88d6-02c0420dc217', 'Facilitating Crop–Livestock Reintegration in the Northern Great Plains', 'Sandeep Kumar, Heidi L. Sieverding, Liming Lai, Thandiwe Nleya, Brian J. Wienhold, Daren D. Redfearn, David Walter Archer, David A.N. Ussiri', 2019, 'Agronomy Journal', '10.2134/agronj2018.07.0441', 'https://doi.org/10.2134/agronj2018.07.0441', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.2134/agronj2018.07.0441', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'Integrated crop–livestock systems (ICLSs) can help increase food production while benefiting soils and the environment. This review summarizes recent impacts of ICLSs on crop and livestock production and rural economics and discusses lessons learned in the northern Great Plains (NGP). Research on ICLS conducted in the NGP indicates that the crop residue grazing, swath grazing, and annual forage grazing can positively influence crop production; whereas, livestock performance varies with season, forage nutritive value, and grazing management. Furthermore, ICLSs can reduce the costs and risks of agricultural production. The success of ICLSs in NGP region depends on trade‐offs, planning, economic benefits, policies, regulations, community acceptance, and management skills. The ICLSs could play a strategic role in future agricultural production. The lessons learned from adopting ICLSs in the NGP include the lack of available land for fertilizer (manure) management, that to implement ICLS practices skills and knowledge must be maintained, and ICLS provides an entry point for young farmers and ranchers however capital is needed. These experiences and lessons could be valuable references for producers to adopt ICLSs in the NGP or other regions. Core Ideas Integrated crop–livestock systems positively affect crop production by improving soil health. Common integrated crop–livestock system management techniques can enhance the northern Great Plains crop production. Integrated crop–livestock system livestock performance is impacted by season, forage selection, and management. Integrated crop–livestock systems can increase economic benefits and reduce economic risks. Experiences and lessons in the northern Great Plains could be valuable for other regions to adopt integrated crop–livestock systems.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ee406990-4a02-4505-ace7-a340508a2748', '765784df-ee6f-429e-88d6-02c0420dc217', 'Genomic retained heterosis effects on fertility and lifetime productivity in beef heifers', 'J. A. Basarab, John J. Crowley, Mohammed Kotb Abo-Ismail, Ghader Manafiazar, E. C. Akanno, Vern S. Baron, Graham Stuart Plastow', 2018, 'Canadian Journal of Animal Science', '10.1139/cjas-2017-0192', 'https://doi.org/10.1139/cjas-2017-0192', 'https://utoronto.scholaris.ca/bitstreams/c5c24459-fcff-45da-aa7a-87b79f6ede41/download', NULL, NULL, 40, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('882228b6-d4d3-4326-9a01-6a504c4d85c1', '765784df-ee6f-429e-88d6-02c0420dc217', 'Grazing aftermath straw & chaff buyer’s perspective', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/grazing-aftermath-straw-chaff-buyer-s-perspective', 'https://open.alberta.ca/dataset/d543eaa2-caa6-440b-af04-c479733cadec/resource/92e16176-2dbe-41b5-b16b-074260418e98/download/2009-grazing-aftermath-straw-chaff-byyers-perspective-2009-09-09.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Typically, the first reaction of cow/calf producers to a shortened grazing season is to purchase higher-priced feeds in anticipation of a longer feeding season. However, short term options do exist to acquire cereal aftermath that extends grazing into the fall, which will reduce the costs of wintering the cow herd. This information sheet explains how a partial budget can be a valuable tool in assessing these options.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2844353c-e454-49e6-8e32-5141e229f06a', '765784df-ee6f-429e-88d6-02c0420dc217', 'Impact of calving seasons and feeding systems in western Canada. I. Postweaning growth performance and carcass characteristics of crossbred steers', 'Obioha N Durunna, Hushton C. Block, A. D. Iwaasa, Leanne C. Thompson, Shannon L. Scott, Clayton D. Robins, Mohammad Khakbazan, H.A. Lardner', 2014, 'Canadian Journal of Animal Science', '10.4141/cjas-2014-033', 'https://doi.org/10.4141/cjas-2014-033', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjas-2014-033', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b959c270-f97f-40d5-a4a9-0c543c8c1c5f', '765784df-ee6f-429e-88d6-02c0420dc217', 'Optimizing feed intake recording and feed efficiency estimation to increase the rate of genetic gain for feed efficiency in beef cattle', 'Ghader Manafiazar, J. A. Basarab, Lisa McKeown, J. Stewart-Smith, Vern S. Baron, Michael D. MacNeil, Graham Stuart Plastow', 2017, 'Canadian Journal of Animal Science', '10.1139/cjas-2016-0118', 'https://doi.org/10.1139/cjas-2016-0118', 'https://utoronto.scholaris.ca/bitstreams/40aafa92-c7e7-4aac-b690-0e53fa5b6033/download', NULL, NULL, 29, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4dfb1734-f678-467a-8ae9-55e76a6a2ef2', '765784df-ee6f-429e-88d6-02c0420dc217', 'Short-term impacts of winter bale grazing beef cows on forage production and soil nutrient status in the eastern Canadian Prairies', 'G. Donohoe, Don Flaten, Faith A. Omonijo, Kim Ominski', 2021, 'Canadian Journal of Soil Science', '10.1139/cjss-2021-0028', 'https://doi.org/10.1139/cjss-2021-0028', 'https://utoronto.scholaris.ca/bitstreams/14fa0ff3-4d83-4b47-b226-e7c8527361fb/download', NULL, NULL, 45, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0896a056-a9a2-4848-90bb-2b9210e875c9', '765784df-ee6f-429e-88d6-02c0420dc217', 'Increasing cow/calf profitability using chaff and chaff/straw feedstuffs', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4049676', 'https://open.alberta.ca/dataset/d3409fd3-0125-4d1c-a686-446a2c13aa9c/resource/7a76ec52-1afd-413d-96f6-bd622adbfa2b/download/2008-420-50-2.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Over the years, many cost-conscious cow/calf producers across western Canada have recognized the potential for chaff residues to help reduce the winter feeding costs in mixed farm operations. Chaff that has often been considered a nuisance on the grain side of a mixed farm can prove to be a valuable low cost feed alternative on the cattle side. In fact, chaff may prove to work as a win-win solution for both operations, if some basic steps are followed. And nothing is more important than to first recognize that chaff is a low quality feed, suitable only for mature beef cows.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9323c774-9ad8-4855-a6e6-7fd12a25b5c9', '765784df-ee6f-429e-88d6-02c0420dc217', 'Insights into managing winter feed costs in Alberta cow/calf operations', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3539501', 'https://open.alberta.ca/dataset/f6eeb57b-a6db-4c73-bceb-cfafeec3f1bb/resource/b4d8ecb8-b6c0-47e2-a49d-8f0dc15fab51/download/2004-september-managing-winter-feed-costs.pdf', NULL, NULL, 33, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The largest single cost of maintaining a cow herd relates to feeds consumed. These costs vary from region-to-region, depending on climate and resources available. This report presents the results of research by the AgriProfit$ Business Analysis and Research team into managing winter feed costs for cow/calf enterprises in Alberta.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d59ba9e8-e2ab-4d97-a3ac-463632a8f5eb', '765784df-ee6f-429e-88d6-02c0420dc217', 'Interactions between nutrition and reproduction in postpartum beef cows', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/interactions-between-nutrition-and-reproduction-in-postpartum-beef-cows', 'https://open.alberta.ca/dataset/c495c0af-4f69-4ce9-ae7a-a6df83b187d3/resource/bf635828-2539-4ec7-b369-ce06c32dc8bf/download/163003308471-interactions-between-nutrition-and-reproduction-in-postpartum-beef-cows.pdf', NULL, NULL, 70, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated whether nutrition affected ovarian follicular function by altering insulin-like growth factor I (IGF-I) production in mature Hereford-cross cows. Cows were fed either 100 per cent or 50 per cent of the National Research Council recommendation for total digestible nutrients, then ovariectomized 20 or 35 days after calving. Dietary treatment did not affect the mean number of follicles, but restricted cows had more medium follicles producing large amounts of estrogen, with lower IGF-I levels in granulosa cells and culture media. Nutrient restriction prevented the development of seven to ten millimetre follicles into active pre-ovulatory follicles, possibly due to lower IGF-I content. No direct relationship was found between IGF-I and the ability of granulosa cells to produce progesterone.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fbc39535-5d1c-4fbf-b65a-1958a660cde1', '765784df-ee6f-429e-88d6-02c0420dc217', 'Mineral metabolism in cattle', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/mineral-metabolism-in-cattle', 'https://open.alberta.ca/dataset/f7c81514-012a-4900-a02a-2b580ca12b72/resource/2331ceb6-4382-4ed6-8813-f83db1a0a89c/download/163010402424-mineral-metabolism-in-cattle.pdf', NULL, NULL, 144, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This research involved five experiments examining dietary, environmental, and genetic factors affecting the copper and zinc status of beef cattle. Dietary copper intake below 30 milligrams per kilogram of dry matter did not maintain adequate liver copper in calves or heifers, and the true availability of dietary copper was consistently low across all trials. Ammoniated feeds and different copper-to-zinc ratios did not significantly affect liver copper or zinc status, and all treatment groups remained deficient. Injectable copper ethylenediaminetetraacetic acid (EDTA) given once or twice during the drylot period helped maintain plasma copper in pregnant cows but had no effect on their calves.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a22d6921-b8e6-4bed-a77b-3a0cf6c5961f', '765784df-ee6f-429e-88d6-02c0420dc217', 'Nutrient loading calculator for in-field or extensive livestock winter feeding systems. Version 2.1', 'Government of Alberta', 2013, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/nutrient-loading-calculator-for-in-field-or-extensive-livestock-winter-feeding-systems-version-2-1', 'https://open.alberta.ca/dataset/c8647e72-2771-463c-a8bf-1ced5ed40950/resource/5f106fef-e568-4bdc-933d-4bcc9d5ae189/download/af-nutrient-loading-calculator-for-infield-extensive-livestock-winter-feeding-systems-v-2-1-2013.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This calculator is designed to help land managers plan detailed feed and cow management strategies to achieve an acceptable or target animal unit density per acre based on appropriate nutrient additions to the landscape. It can also be used as a record keeping tool of feed and cow management, and nutrient additions on specific sites.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9aa4acef-a38f-48c0-80f9-8a3ec4d4544a', '765784df-ee6f-429e-88d6-02c0420dc217', 'Pathogens at the livestock-wildlife interface in Western Alberta: does transmission route matter?', 'Pruvot M, Kutz S, van der Meer F, Musiani M, Barkema HW, Orsel K', 2014, 'Veterinary research', '10.1186/1297-9716-45-18', 'https://doi.org/10.1186/1297-9716-45-18', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC3937035.1/PMC3937035.1.pdf', NULL, NULL, 13, NULL, 'southern_alberta', 5, 'cc by', 'In southwestern Alberta, interactions between beef cattle and free-ranging elk (Cervus elaphus) may provide opportunities for pathogen transmission. To assess the importance of the transmission route on the potential for interspecies transmission, we conducted a cross-sectional study on four endemic livestock pathogens with three different transmission routes: Bovine Viral Diarrhea Virus and Bovine Herpesvirus 1 (predominantly direct transmission), Mycobacterium avium subsp. paratuberculosis (MAP) (indirect fecal-oral transmission), Neospora caninum (indirect transmission with definitive host). We assessed the occurrence of these pathogens in 28 cow-calf operations exposed or non-exposed to elk, and in 10 elk herds exposed or not to cattle. We characterized the effect of species commingling as a risk factor of pathogen exposure and documented the perceived risk of pathogen transmission at this wildlife-livestock interface in the rural community. Herpesviruses found in elk were elk-specific gamma-herpesviruses unrelated to cattle viruses. Pestivirus exposure in elk could not be ascertained to be of livestock origin. Evidence of MAP circulation was found in both elk and cattle, but there was no statistical effect of the species commingling. Finally, N. caninum was more frequently detected in elk exposed to cattle and this association was still significant after adjustment for herd and sampling year clustering, and individual elk age and sex. Only indirectly transmitted pathogens co-occurred in cattle and elk, indicating the potential importance of the transmission route in assessing the risk of pathogen transmission in multi-species grazing systems.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3789a109-f934-45f5-b2ec-4508a7faa71c', '765784df-ee6f-429e-88d6-02c0420dc217', 'Performance and ruminal fermentation of second-trimester pregnant beef cows fed short-season high-moisture corn stover or barley greenfeed during winter in western Canada', 'Rachel E Carey, H.A. Lardner, Tim Angus McAllister, G.B. Penner', 2023, 'Canadian Journal of Animal Science', '10.1139/cjas-2023-0035', 'https://doi.org/10.1139/cjas-2023-0035', 'https://cdnsciencepub.com/doi/pdf/10.1139/cjas-2023-0035', NULL, NULL, NULL, NULL, 'southern_alberta', 4, 'cc-by', 'This study evaluated performance and ruminal fermentation for cows fed short-season high-moisture shelled corn stover with corn dried distillers’ grains with solubles (COR) or barley greenfeed (BAR) that was either swathed (S-COR; S-BAR; Experiment 1) or baled (B-COR; B-BAR; Experiment 2) as winter-feeding systems. In Experiment 1, cows were randomly assigned to S-COR or S-BAR and fed for 52 days in the fields where crops were grown. Body weight (BW), subcutaneous rib and rump fat, and body condition score (BCS) were measured, with no differences detected between treatments ( P > 0.05). However, S-COR had a lower estimated dry matter intake (DMI) than S-BAR ( P ≤ 0.03). In Experiment 2, cows were assigned to B-COR or B-BAR for 42 days and fed in field paddocks. Cows fed B-COR had less ( P ≤ 0.01) DMI, final BW, rib fat, rump fat, and BCS than B-BAR, with no differences ( P > 0.05) for ruminal pH. Total SCFA concentration was greater ( P ≤ 0.05) on day 21 for B-BAR than B-COR, but not on day 42. Under western Canadian conditions, COR may reduce DMI and the performance of pregnant cows, suggesting that additional preservation and supplementation strategies should be investigated.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c3a80f01-be35-4a13-b146-c324022bdb06', '765784df-ee6f-429e-88d6-02c0420dc217', 'Potential of Molecular Weight and Structure of Tannins to Reduce Methane Emissions from Ruminants: A Review', 'Aboagye IA, Beauchemin KA', 2019, 'Animals : an open access journal from MDPI', '10.3390/ani9110856', 'https://doi.org/10.3390/ani9110856', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6912696.1/PMC6912696.1.pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc by', 'There is a need to reduce enteric methane (CH4) to ensure the environmental sustainability of ruminant production systems. Tannins are naturally found in both tropical and temperate plants, and have been shown to consistently decrease urinary nitrogen (N) excretion when consumed by ruminants. However, the limited number of in vivo studies conducted indicates that the effects of tannins on intake, digestibility, rumen fermentation, CH4 production and animal performance vary depending on source, type, dose, and molecular weight (MW). There are two main types of tannin in terrestrial plants: condensed tannin (CT; high MW) and hydrolysable tannin (HT; low MW). Consumption of CT and HT by ruminants can reduce N excretion without negatively affecting animal performance. High MW tannins bind to dietary protein, while low MW tannins affect rumen microbes, and thus, irrespective of type of tannin, N excretion is affected. The structure of high MW tannin is more diverse compared with that of low MW tannin, which may partly explain the inconsistent effects of CT on CH4 production reported in in vivo studies. In contrast, the limited number of in vivo studies with low MW HT potentially shows a consistent decrease in CH4 production, possibly attributed to the gallic acid subunit. Further in vivo studies are needed to determine the effects of tannins, characterized by MW and structural composition, on reducing CH4 emissions and improving animal performance in ruminants.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0b1f0eae-493d-422f-bc7e-24a735f41363', '765784df-ee6f-429e-88d6-02c0420dc217', 'Potential of Spring Barley, Oat and Triticale Intercrops with Field Peas for Forage Production, Nutrition Quality and Beef Cattle Diet', 'Kabal Singh Gill, Akim Tunde Omokanye', 2018, 'Journal of Agricultural Science', '10.5539/jas.v10n4p1', 'https://doi.org/10.5539/jas.v10n4p1', 'http://www.ccsenet.org/journal/index.php/jas/article/download/72515/40692', NULL, NULL, 17, NULL, 'alberta', 4, 'cc-by', 'Spring barley (Hordeum vulgare L.), oat (Avena sativa L.) and triticale (x Triticosecale Wittmack) monocrops and their intercrops with two forage varieties (40-10 and Tucker) and one seed variety (Cooper) peas (Pisum sativum L.) were evaluated for forage production, nutrition quality and suitability in the beef cattle diet. Pea + cereal intercrops were compared to respective cereal monocrops in 2009, 2010 and 2011. Plant height of cereals tended to be reduced in intercrops compared to respective monocrops. Taller 40-10 forage type pea tended to cause lodging in 2009 and 2011, not observed with other pea varieties. Fresh forage of pea + cereal intercrops had higher moisture than respective cereal monocrops. Fourteen of the 18 intercrops had less dry matter yield (DMY) than respective cereal monocrops. Shorter Tucker pea had less negative impact on DMY than taller 40-10 pea. Treatments with barley had lower DMY than respective oat and triticale systems. Intercrops improved forage crude protein (CP) content over the respective monocrops, which was enough to overcome the DMY penalty and produce more CP yield than their monocrops. The forage Ca and Mg contents were improved by intercrops over their monocrops, and they were greater with 40-10 pea than other pea varieties and with barley than oat or triticale. The forage P content also tended to be higher in intercrops than corresponding monocrops, without a consistent effect of cereal type or pea variety. The forage K and S contents were not consistently influenced by the cereal types, pea varieties or intercrops. Forage Na content was greater from oat than respective barley and triticale treatments. The monocrops and intercrops had similar forage Cu content, and treatments with barley had more Cu than with oat or triticale. Forage Zn content tended to be intercrops > monocrops; and barley > triticale > oat. Treatments had no influence on the forage Fe and Mn contents. Levels of acid (ADF) and neutral (NDF) detergent fibres in the forage were similar for the corresponding intercrops and monocrops, and greater for oat than barley or triticale treatments. Some of the intercrops improved total digestible nutrients (TDN) content in forage over their monocrops. Monocrop of oat had less TDN than barley or triticale. Drought reduced the ADF, NDF and TDN contents. The forage NEL, NEM and NEG as well as RFV and NFC showed similar trend as the TDN. Overall, the tested pea + cereal intercrops did not increase DMY over the respective monocrops, but they indicated several nutritional quality benefits. These improvements present opportunities to substitute some grain or supplements in the beef cattle diet with better quality forage by intercrops.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fdfbcbec-9125-4661-8aea-45424e5a98a9', '765784df-ee6f-429e-88d6-02c0420dc217', 'Potential of Stockpiled Annual and Perennial Forage Species for Fall and Winter Grazing in the Canadian Great Plains Region', 'Xinhui Peng', 2017, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/8184', 'http://hdl.handle.net/10388/8184', NULL, NULL, 130, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e222df89-b745-4218-8d4a-49a34ebed7b7', '765784df-ee6f-429e-88d6-02c0420dc217', 'Prevalence and lameness-associated risk factors in Alberta feedlot cattle', 'Davis-Unger J, Schwartzkopf-Genswein KSG, Pajor EA, Hendrick S, Marti S, Dorin C, Orsel K', 2019, 'Translational animal science', '10.1093/tas/txz008', 'https://doi.org/10.1093/tas/txz008', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7200549.1/PMC7200549.1.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'cc by-nc', 'Lameness in cattle is a health and welfare concern; however, limited information is available on risk factors and the relationship between lameness and common diseases like bovine respiratory disease (BRD). Therefore, the objectives of this study were to: 1) identify prevalence of lameness in feedlot cattle and related risk factors of cattle diagnosed as lame; and 2) determine associations between BRD occurrence and lameness. Feedlot cattle health records were available from 28 feedlots for 10 yr. The data set consisted of 663,838 cattle records, with 13.9% (92,156) diagnosed with a disease, including 32.3%, 46.0%, and 22.0% with lameness, BRD, and other diagnoses, respectively. Lameness was classified into four categories: foot rot (FR), joint infections (JI), lame with no visible swelling (LNVS), and injuries (INJ), with a prevalence of 74.5%, 16.1%, 6.1%, and 3.1%, respectively. Lameness was compared across cattle types (arrival date and weight) as well as age classification (calf vs. yearling), gender (steer vs. heifer), and season of placement in the feedlot (spring, summer, fall, and winter). Within the disease-diagnosed population, lameness represented 28.5% of treated fall-placed calves, 38.5% of winter-placed calves, and 40.8% of treated yearlings. Foot rot was the most common diagnosis with 74.5% of all lameness diagnoses, with winter- and fall-placed calves more likely to be diagnosed with FR compared to yearlings (OR: 1.19, 95% CI: 1.10-1.30 and OR: 1.46, 95% CI: 1.38-1.55, respectively). Joint infections were the second most common diagnosis (16.1%). Compared to yearlings, fall-placed calves had a higher odds (OR: 3.64, 95% CI: 3.12-4.24) for JI. Injuries and LNVS were the least common but again fall-placed calves had higher odds of this diagnosis compared to yearlings (OR: 2.26, 95% CI: 1.70-2.99 and OR: 9.10, 95% CI: 6.26-13.2, respectively). Gender was significantly different for JI as steers were less likely affected compared to heifers (OR: 0.687, 95% CI: 0.545-0.867), and more likely affected by LNVS (OR: 2.46, 95% CI: 1.57-3.84). Of all lameness-associated deaths, JI accounted for almost 50%. Finally, cattle diagnosed with BRD were subsequently more likely to be diagnosed with INJ, JI, or LNVS (P < 0.001 for all comparisons). In conclusion, animal type and gender were associated with type of lameness diagnoses, allowing feedlots to allocate resources to groups at highest risk and focus on early intervention strategies.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f9e65a2-3e2d-4f8c-8aba-54209bcc62a7', '765784df-ee6f-429e-88d6-02c0420dc217', 'PSIX-24 The effects of camelina meal in western Canadian winter-feeding diets on feed intake and growth performance of replacement beef heifers.', 'Stephanie A. Terry, Melissa S Williams, Gabriel O Ribeiro, Gleise da Silva, Katharine M Wood', 2025, 'Journal of Animal Science', '10.1093/jas/skaf300.682', 'https://doi.org/10.1093/jas/skaf300.682', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC12497185/pdf/skaf300.682.pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6f52f02a-369f-4856-972d-0ca7771408d1', '765784df-ee6f-429e-88d6-02c0420dc217', 'Ration options for beef cows', 'Government of Alberta', 2002, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4007955', 'https://open.alberta.ca/dataset/fcc09957-b061-4e58-a8e0-a3bfce530d01/resource/02cbe349-a731-4f9c-913d-96437765c218/download/2007-420-52-2.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Producers are always encouraged to have their beef cow feed programs set well in advance of the winter. This is even more important when planning through a challenging time, one that may require extra feed for extra animals due to volatile or weak markets. In times of high feed prices, planning can also help producers manage and potentially reduce overall winter feed costs.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4ff2e728-5c04-4a57-a041-989413f21008', '765784df-ee6f-429e-88d6-02c0420dc217', 'Relationship between body size, body condition, and fat reserves in beef cows', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/relationship-between-body-size-body-condition-and-fat-reserves-in-beef-cows', 'https://open.alberta.ca/dataset/b9936e28-2530-4680-93d3-c09fb042823b/resource/4f78112e-5916-4f29-852c-63d9f619abca/download/163010146583-relationship-between-body-size-body-condition-and-fat-reserves-in-beef-cows.pdf', NULL, NULL, 26, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study aimed to determine if differences in body composition between Hereford-Angus and Simmental-Angus cows were sufficient to justify different winter feeding strategies for each breed. A second objective was to assess whether measuring cow condition by ultrasonic backfat measurement (UBF) or body condition scoring systems (BCS) offered advantages or differences. Results indicated that differences in fat deposition between breeds were small relative to total energy requirements, and UBF and BCS both provided reliable measures of body condition when used over a reasonable scoring range. Using body condition in late pregnancy to guide winter feeding costs was found to be feasible, allowing targeted feeding and grouping of pregnant beef cows to avoid over- or under-feeding.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('db25e608-6ddb-4123-a368-ffd44be34f78', '765784df-ee6f-429e-88d6-02c0420dc217', 'Seasonal metabolic and growth responses of grazing beef heifers divergent in residual feed intake', 'María Camila Londoño-Méndez, Sergio David Lasso-Ramirez, Carolyn Fitzsimmons, Graham Plastow, Edward William Bork, John Basarab, Ana Caroline Cerqueira de Melo Vasco, Aghata Elins Moreira Silva', 2026, 'PLoS ONE', '10.1371/journal.pone.0348184', 'https://doi.org/10.1371/journal.pone.0348184', 'https://scholarworks.montana.edu/bitstreams/98cf8530-b9ed-499e-af80-f21a974002bd/download', NULL, NULL, 22, NULL, 'alberta', 4, 'cc-by', 'This study involved 41 crossbred, black-hided beef heifers that were measured in a drylot for residual feed intake (RFI) at 11 ± 1 months of age and classified into more (LOW-RFI; n = 21; -0.96 ± 0.70 kg DM/day) or less efficient (HIGH-RFI; n = 20; 1.40 ± 1.00 kg DM/day) groups. Heifer metabolism and growth performance were evaluated from 14 ± 1 months of age (351 ± 40 kg initial body weight [BW]) across summer and winter in Western Canada. Weather conditions were characterized using the Comprehensive Climate Index (CCI). Rumen temperature (RT) was recorded every 10 minutes using an automated bolus device. Plasma and BW were collected every 18 ± 5 days from July to August and January to March to measure urea nitrogen, non-esterified fatty acids, insulin-like growth factor 1, β-hydroxybutyric acid, leptin, free triiodothyronine (fT3), haptoglobin, heat shock protein 70 (HSP70), gamma-aminobutyric acid, and serotonin, and growth performance. Data were analyzed as a completely randomized design using SAS 9.4. LOW-RFI tended to have greater fT3 and HSP70 (P = 0.08), while exhibiting lower haptoglobin concentrations (P = 0.02) in summer. Gamma-aminobutyric acid concentrations were greater in LOW-RFI during periods of no heat stress (P = 0.01) and tended to decrease in HIGH-RFI under severe risk of cold stress (P = 0.08) based on CCI. Comparatively, HIGH-RFI had higher leptin concentrations during winter (P = 0.04) than LOW-RFI. During summer, HIGH-RFI exhibited greater RT between 1:00-6:00, 10:00-12:00, and 20:00-22:00 (P = 0.002). In contrast, HIGH-RFI had lower RTs on the coldest winter days (P = 0.009). In both seasons, growth performance did not differ between RFI groups (P ≥ 0.24). In conclusion, feed efficiency measured in the drylot was associated with subsequent metabolic responses during grazing, and these responses were influenced by weather-related stress, with more efficient animals showing greater adaptability to weather fluctuations.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2cf12a39-4163-4861-bb04-78e5559dad19', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Advances in Microbial Exopolysaccharides: Present and Future Applications', 'Nguyen HT, Pham TT, Nguyen PT, Le-Buanec H, Rabetafika HN, Razafindralambo HL', 2024, 'Biomolecules', '10.3390/biom14091162', 'https://doi.org/10.3390/biom14091162', 'https://europepmc.org/articles/PMC11430787?pdf=render', NULL, NULL, 35, NULL, 'other', 1, 'cc by', 'Microbial exopolysaccharides (EPSs) are receiving growing interest today, owing to their diversity in chemical structure and source, multiple functions, and immense potential applications in many food and non-food industries. Their health-promoting benefits for humans deserve particular attention because of their various biological activities and physiological functions. The aim of this paper is to provide a comprehensive review of microbial EPSs, covering (1) their chemical and biochemical diversity, including composition, biosynthesis, and bacterial sources belonging mainly to lactic acid bacteria (LAB) or probiotics; (2) their technological and analytical aspects, especially their production mode and characterization; (3) their biological and physiological aspects based on their activities and functions; and (4) their current and future uses in medical and pharmaceutical fields, particularly for their prebiotic, anticancer, and immunobiotic properties, as well as their applications in other industrial and agricultural sectors.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('83d9d3af-132c-469f-a66c-6c01eb753b8c', '765784df-ee6f-429e-88d6-02c0420dc217', 'Swath grazing interesting concept, but does it pay?', 'Government of Alberta', 2002, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/swath-grazing-interesting-concept-but-does-it-pay', 'https://open.alberta.ca/dataset/82f7f8c2-b44e-4f95-ae6f-7c11b62cd30e/resource/2ca02a4b-9551-4f8d-a078-dfb15ce4b485/download/2002-swath-grazing-interesting-concept-but-does-it-pay-2002-12-02.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Reports the results of research and analysis by the AgriProfit$ Business Analysis and Research team on the value of swath grazing. The premise of swath grazing is to substitute a lower cost grazing system for higher cost drylot feeding the cow herd. Analysis of study results found that Swath grazing has potential as a cost-saving feeding strategy. Knowledge of production costs and risks, put into a budget analysis, will help determine if it''s the right strategy for a particular farm.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9f941386-bc71-4fe2-8772-9477e73c06a1', '765784df-ee6f-429e-88d6-02c0420dc217', 'Swath grazing triticale and corn compared to barley and a traditional winter feeding method in central Alberta', 'Vern S. Baron, Raquel R. Doce, J. A. Basarab, Campbell Dick', 2014, 'Canadian Journal of Plant Science', '10.4141/cjps2013-412', 'https://doi.org/10.4141/cjps2013-412', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps2013-412', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('059cbb8a-e1f3-4ece-9028-bb480a9ff946', '765784df-ee6f-429e-88d6-02c0420dc217', 'The scope for manipulating the polyunsaturated fatty acid content of beef: a review', 'Vahmani P, Mapiye C, Prieto N, Rolland DC, McAllister TA, Aalhus JL, Dugan ME', 2015, 'Journal of animal science and biotechnology', '10.1186/s40104-015-0026-z', 'https://doi.org/10.1186/s40104-015-0026-z', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC4509462.1/PMC4509462.1.pdf', NULL, NULL, 13, NULL, 'alberta', 4, 'cc by', 'Since 1950, links between intake of saturated fatty acids and heart disease have led to recommendations to limit consumption of saturated fatty acid-rich foods, including beef. Over this time, changes in food consumption patterns in several countries including Canada and the USA have not led to improvements in health. Instead, the incidence of obesity, type II diabetes and associated diseases have reached epidemic proportions owing in part to replacement of dietary fat with refined carbohydrates. Despite the content of saturated fatty acids in beef, it is also rich in heart healthy cis-monounsaturated fatty acids, and can be an important source of long-chain omega-3 (n-3) fatty acids in populations where little or no oily fish is consumed. Beef also contains polyunsaturated fatty acid biohydrogenation products, including vaccenic and rumenic acids, which have been shown to have anticarcinogenic and hypolipidemic properties in cell culture and animal models. Beef can be enriched with these beneficial fatty acids through manipulation of beef cattle diets, which is now more important than ever because of increasing public understanding of the relationships between diet and health. The present review examines recommendations for beef in human diets, the need to recognize the complex nature of beef fat, how cattle diets and management can alter the fatty acid composition of beef, and to what extent content claims are currently possible for beef fatty acids.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c23ee4c-e1d9-4571-b089-263dcefa999e', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Control of Glyphosate Resistant Canada Fleabane (Conyza canadensis (L.) Cronquist) with 2,4-D Choline/Glyphosate DMA in Corn (Zea mays L.)', 'Laura Ford', 2014, 'The Atrium (University of Guelph)', NULL, 'http://hdl.handle.net/10214/7884', 'https://atrium.lib.uoguelph.ca/bitstreams/d4ef9dfa-78d3-4c78-983c-16b7ae7bba26/download', NULL, NULL, 163, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('55023a85-5e4c-420b-9f57-64a16067f6cf', '765784df-ee6f-429e-88d6-02c0420dc217', 'Winter feeding programs for beef cows and calves', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4043281', 'https://open.alberta.ca/dataset/b6388959-4b1a-49fb-8e74-a77cf2b87ae0/resource/3e38a421-5e4a-48f2-bafd-c33359dcc058/download/2007-420-52-3.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Before making management decisions about feeding beef cattle and calves, producers need to answer the following questions: How much feed is available on the farm? What is the quality of the feed? What is the cost of purchasing feed and supplements? Do the cows need to gain weight during the winter? Are the calves going into a feedlot or back onto grass? What is the required weight gain from the calves? How will interest rates and overhead costs affect break-evens? Plan a winter feeding program well in advance. Use the tools available to sample feed, and obtain feed test results. A balanced ration minimizes costs and improves animal performance.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('902fbaf7-7483-4286-b227-949efe46e096', '765784df-ee6f-429e-88d6-02c0420dc217', 'Winter weathering effects on corn grown for grazing in a short-season area', 'Vern S. Baron, H. G. Najda, Duane H. McCartney, Myron Bjorge, Grant Lastiwka', 2003, 'Canadian Journal of Plant Science', '10.4141/p01-202', 'https://doi.org/10.4141/p01-202', 'https://cdnsciencepub.com/doi/pdf/10.4141/P01-202', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e1907502-4247-47e5-ae09-d99de20966da', '765784df-ee6f-429e-88d6-02c0420dc217', 'Wintering Site Assessment and Design Tool: a guide to selecting and managing a wintering site in Western Canada (Agdex 420/580-3)', 'Alberta Agriculture and Rural Development', 2013, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/bf93e3da-3bfc-4f07-b412-4a3ee031543e', 'https://open.alberta.ca/dataset/bf93e3da-3bfc-4f07-b412-4a3ee031543e/resource/8ef15838-5d8b-4708-9531-97ce8cdc53e6/download/2013-420-580-3.pdf', NULL, NULL, 56, NULL, 'prairies', 5, 'Open Government Licence - Alberta', 'A western Canadian methodology for choosing and managing a winter feeding and bedding site: slope, soil type and texture, depth to water table, distance to a common body of water, drainage and runoff pathways, natural shelter, snow catch and access. The closest thing in the Canadian literature to a scoreable siting tool, and the obvious model for a map-based siting check in corral design software - it pairs directly with the AOPA 30 m setback rule.', '{extension,plan}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2ec3335-31be-480a-b06d-980ca8bd86d1', '765784df-ee6f-429e-88d6-02c0420dc217', 'Wintering Sites and Livestock Corrals (Agdex 096-4), revised May 2007 printing', 'Alberta Agriculture and Food; Natural Resources Conservation Board', 2007, 'Government of Alberta (Open Alberta)', NULL, 'https://open.alberta.ca/dataset/9ba93a48-af39-4a37-9103-82d118411f83', 'https://open.alberta.ca/dataset/9ba93a48-af39-4a37-9103-82d118411f83/resource/d6de3559-a76f-4013-85ce-46639d31fc1c/download/3946140-standard-wintering-sites-livestock-corrals-agdex-096-4-revised-2007-05.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence - Alberta', 'The original May 2007 revision of the Agdex 096-4 standard on corral and wintering site siting under AOPA, kept here because it is the version most often cited by the NRCB and by Alberta beef specialists. Same 30 m setback to a common body of water, same slope-scaled manure storage setbacks, same two runoff mitigation options.', '{extension,standard}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('51a5a17b-6fdb-43b7-ba5f-75f60b66fdf5', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Droplet class and spray volume influence on spray characteristics and herbicide performance in a maize-Brachiaria grass intercropping system', 'Arthur Duarte Rodrigues Neto, Thais Regina Ramos Alves, Leandro Tropaldi, Daniel Nicodemo, Fernando Shintate Galindo, Paulo Humberto Pagliari, Ronaldo Cintra Lima, Vagner do Nascimento', 2026, 'Phytoparasitica', '10.1007/s12600-026-01419-2', 'https://doi.org/10.1007/s12600-026-01419-2', 'https://link.springer.com/content/pdf/10.1007/s12600-026-01419-2.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Optimizing maize–Brachiaria intercropping requires effective weed management with selective maize herbicides. This study evaluated the spray performance and efficacy of atrazine + nicosulfuron for weed management in maize–Brachiaria intercropping, focusing on how droplet classes and spray volumes affect maize growth and yield. The deposition experiment was conducted in a greenhouse in a completely randomized design with six replications. Field experiments were conducted during two seasons [2021 early season—ES (rainy season) and 2022 late season—LS (dry season) in a randomized block design and a 4 × 2 factorial (fine, medium, coarse, and very coarse droplet classes × spray volumes of 77 and 144 L ha −1 ) plus four controls treatments: Maize + Brachiaria without weed control, Maize + Brachiaria manually weeding, Brachiaria manually weeding, and Maize manually weeding. The study revealed that droplet class and spray volume significantly influence droplet deposition. Treatments spraying fine droplets at 144 L ha −1 exhibited higher coverage and droplet density levels. Intercropping maize with Brachiaria grass can be achieved without significant yield losses in the ES. However, the intercropping system reduced maize yield by approximately 17% in the LS. Applying the herbicides atrazine + nicosulfuron at 144 L ha −1 improved weed control and positively impacted maize yield during the LS.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c6d14889-261b-408f-9ffd-e8e341573a5a', '765784df-ee6f-429e-88d6-02c0420dc217', 'Wintering sites and livestock corrals (Revised September 2015)', 'Government of Alberta', 2015, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/7328771', 'https://open.alberta.ca/dataset/9ba93a48-af39-4a37-9103-82d118411f83/resource/14fff415-bb7c-4187-ac11-9b3bad886c4c/download/096-4-web.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The Agricultural Operation Practices Act (AOPA) and regulations include manure management requirements for all livestock operations in Alberta. Producers using seasonal feeding and bedding sites (wintering sites), where livestock are fed and sheltered over the winter, must follow these regulations. Livestock corrals must also be managed according to the same requirements. Under AOPA, all livestock producers are expected to follow the setbacks required from common bodies of water when locating wintering sites and livestock corrals. This practice will help minimize the risk of contaminated runoff potentially affecting the water quality of common water bodies.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('20cb19bd-258b-4851-bb05-88ea7af842e3', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Herbicide Programs for Control of Glyphosate-Resistant Volunteer Corn in Glufosinate-Resistant Soybean', 'Parminder S. Chahal, Amit J. Jhala', 2015, 'Weed Technology', '10.1614/wt-d-15-00001.1', 'https://doi.org/10.1614/wt-d-15-00001.1', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/73D72978766AF5B299AA5D0E7A236C0D/S0890037X00003869a.pdf/div-class-title-herbicide-programs-for-control-of-glyphosate-resistant-volunteer-corn-in-glufosinate-resistant-soybean-div.pdf', NULL, NULL, 13, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b9af9eb-02e3-46d9-92b2-5713b08762f8', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Advances in submerged liquid fermentation and formulation of entomopathogenic fungi', 'Mascarin GM, Golo PS, de Souza Ribeiro-Silva C, Muniz ER, de Oliveira Franco A, Kobori NN, Fernandes ÉKK', 2024, 'Applied microbiology and biotechnology', '10.1007/s00253-024-13287-z', 'https://doi.org/10.1007/s00253-024-13287-z', 'https://europepmc.org/articles/PMC11364594?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by-nc-nd', 'Entomopathogenic fungi (EPF) can be defined as beneficial multifunctional eukaryotic microorganisms that display pivotal ecological services in pest management, with some species possessing the special ability to establish mutualistic relationships with plants. Mass production of these fungi is critical to support affordable widespread commercialization and worldwide field application. Among the mass production methods explored mainly by industry, submerged liquid fermentation is a robust and versatile technology that allows the formation of different types of propagules designated for various applications in pest control. Many hypocrealean EPF are easily culturable on artificial substrates by producing single-celled structures (hyphal bodies, blastospores, and submerged conidia) or multicellular structures (mycelium and microsclerotia). Less frequently, some EPF may form environmentally resistant chlamydospores, but these structures have almost always been overlooked. A continued research pipeline encompassing screening fungal strains, media optimization, and proper formulation techniques aligned with the understanding of molecular cues involved in the formation and storage stability of these propagules is imperative to unlock the full potential and to fine-tune the development of robust and effective biocontrol agents against arthropod pests and vectors of diseases. Finally, we envision a bright future for the submerged liquid fermentation technology to supplement or replace the traditional solid substrate fermentation method for the mass production of many important EPF. KEY POINTS: • Submerged liquid fermentation (SLF) allows precise control of nutritional and environmental factors • SLF provides a scalable, robust, and cost-effective platform for mycopesticide production • Enhancing formulation, shelf life, and field efficacy of submerged propagules remain crucial • Understanding the molecular mechanisms behind submerged propagule formation is key to advancing SLF technology.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e2f615d-c995-4b63-8432-d93da3539037', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'An Evaluation of Four Glyphosate Formulations on Dormant Conifers', 'John Frederick Ahrens, Larry J. Kuhns, Tracey L. Harpster, Todd L. Mervosh', 1997, 'HortScience', '10.21273/hortsci.32.3.494a', 'https://doi.org/10.21273/hortsci.32.3.494a', 'https://journals.ashs.org/downloadpdf/journals/hortsci/32/3/article-p494A.pdf', NULL, NULL, NULL, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ca8edc34-3d38-4a86-8069-93dc468bdcc2', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'An Evaluation of Three Drift Reduction Adjuvants for Aerial Application of Pesticides', 'Ryan S. Henry, Bradley Keith Fritz, Wesley Clint Hoffmann, Greg Robert Kruger', 2016, 'GSTF Journal on Agricultural Engineering', '10.7603/s40872-015-0006-3', 'https://doi.org/10.7603/s40872-015-0006-3', 'https://link.springer.com/content/pdf/10.7603/s40872-015-0006-3.pdf', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Preventing pesticide drift from aerial applications is important for environmental and application efficiency reasons. Proper analysis of drift reduction technologies or techniques is an essential component of the drift prevention process. In the current study, three drift reduction adjuvants were tested with two herbicides under several application conditions used by rotary-wing and fixed-wing aircraft in the U.S. Data was collected using a high speed wind tunnel and laser diffraction equipment. The results of the study indicated application conditions, and not adjuvant inclusion, were the largest drivers of the droplet size distribution and drift potential. Data was further computed in the drift prediction program, AGDISP, where little differences were observed between the treatments. This study highlighted the importance of testing drift reduction technologies or techniques from multiple viewpoints.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eed2cab6-6c84-40c1-9037-e4c39b0656e3', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Avian Metapneumovirus: Current Knowledge, Critical Gaps, and Future Directions in Transmission, Pathogenesis, and Control Across Poultry Systems', 'Anil A, Ghimire B, Bhandari M, Yadav KK', 2026, 'Viruses', '10.3390/v18070781', 'https://doi.org/10.3390/v18070781', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13431517.1/PMC13431517.1.pdf', NULL, NULL, 34, NULL, 'northern_plains', 3, 'cc by', 'Avian metapneumovirus (aMPV) is an economically significant respiratory virus of poultry that causes major losses due to reduced egg production and increased susceptibility to secondary infections. It has global significance in poultry production systems and mainly affects turkeys, chickens, and ducks. It was first detected in South Africa in 1978 and is classified into four distinct subtypes (A-D) based upon sequence divergence of the glycoprotein (G) gene. Subtype C has historically been the dominant subtype in the US, first detected in the late 1990s, causing approximately $15 million economic loss per year in Minnesota alone. However, after a decade, aMPV re-emerged in the fall of 2023. Subtype A in California and B in North Carolina was detected for the very first time in the US, impacting multiple states, with an estimated $112 million loss in Minnesota alone. The most recent US Animal Health Association (USAHA) annual survey has now ranked aMPV as the most frequently reported issue in turkey production. Even after four decades of virus identification, areas such as transmission routes, host-virus interactions and tissue tropism within the host are not studied in detail. Addressing these gaps via current modernized research tools is crucial in minimizing the impact of aMPV on the poultry industry. Therefore, this review article summarizes current knowledge on aMPV while identifying critical research gaps and emphasizing future research directions for combating aMPV and supporting long-term sustainability of the turkey industry.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e42727c3-936e-4d93-948c-0961a18e41aa', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Effect of Class Act NG Adjuvant on Glyphosate Efficacy in Corn', 'Nader Soltani, Christian A. Willemse, Peter H. Sikkema', 2023, 'Journal of Agricultural Science', '10.5539/jas.v15n11p1', 'https://doi.org/10.5539/jas.v15n11p1', 'https://ccsenet.org/journal/index.php/jas/article/download/0/0/49344/53259', NULL, NULL, 9, NULL, 'canada', 3, 'cc-by', 'There is little information on the effect of the co-application of glyphosate with Class Act NG adjuvant on weed control efficacy and corn yield under Ontario environmental conditions. This study consisted of 6 field experiments that were conducted in Ontario during 2021 and 2022 to determine if the addition of Class Act NG (2.5% v/v) to glyphosate at 450, 900 and 1350 g ae ha-1 would improve weed control and result in a concomitant increase in corn yield. The co-application of glyphosate with Class Act NG resulted in no visible corn injury at 1 and 4 weeks after herbicide application (WAA). The addition of Class Act NG to glyphosate at 450 g ae ha-1 improved control of common lambsquarters, velvetleaf, Powell amaranth, common ragweed, and barnyardgrass as much as 20, 14, 9, 8, and 7%, respectively but there was no improvement in control of giant foxtail, or green foxtail and there was no increase in corn yield. The addition of Class Act NG to glyphosate at 900 g ae ha-1 improved common lambsquarters control 6 and 5% at 4 and 8 WAA, respectively and improved barnyardgrass control 4% at 4 WAA. The addition of Class Act NG to glyphosate at 1350 g ae ha-1 provided no improvement in control of velvetleaf, Powell amaranth, common ragweed, common lambsquarters, barnyardgrass, giant foxtail, or green foxtail and there was no increase in corn yield. Based on this data the co-application of glyphosate with Class Act NG results in improved control of some annual broadleaf and grass weeds (common lambsquarters, velvetleaf, Powell amaranth, common ragweed and barnyardgrass) when glyphosate is applied at 450 or 900 g ae ha-1; however, when glyphosate is applied at 1350 g ae ha-1 there was no improvement in weed control. The addition of Class Act NG to glyphosate at 450, 900 and 1350 g ae ha-1 did not result in an increase in corn yield.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe77bfc9-8619-4a77-9fd2-c79c0009d1d6', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Effect of Crimson® NG Adjuvant on Glyphosate Efficacy in Corn', 'Nader Soltani, Christian A. Willemse, Peter H. Sikkema', 2024, 'Journal of Agricultural Science', '10.5539/jas.v16n11p12', 'https://doi.org/10.5539/jas.v16n11p12', 'https://ccsenet.org/journal/index.php/jas/article/download/0/0/50776/55034', NULL, NULL, 10, NULL, 'canada', 3, 'cc-by', 'There is limited published data on the impact of the addition of Crimson® NG to glyphosate on weed control efficacy in corn under Ontario environmental conditions. Four field experiments were conducted at the University of Guelph, Ridgetown Campus, Ridgetown, Ontario during 2022 and 2023 with two water sources to evaluate weed control with glyphosate alone and in combination with Crimson® NG. Glyphosate was applied at rates of 900, 1029, or 1221 g ae ha-1, with and without Crimson® NG at 1.0 and 2.5% v/v, using water with 56 ppm (Ridgetown) and 1600 ppm (Plattsville) hardness. Results showed that glyphosate at 900 g ae ha-1 controlled velvetleaf, Powell amaranth, common ragweed, common lambsquarters, barnyardgrass, and giant foxtail 97-100%, independent of water hardness. Neither increased glyphosate rates nor the addition of Crimson® NG significantly improved weed control. No corn injury was observed with all herbicide/adjuvant treatments evaluated. These findings confirm that glyphosate at 900 g ae ha-1 is highly effective for the control of common annual grass and broadleaf weeds. Weed control efficacy with glyphosate was not influenced by water source and there was no improvement in weed control efficacy from increasing the rate of glyphosate or from the addition of Crimson® NG.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a6585246-d6eb-43bb-b1a7-854a04e4f37a', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'EMA and EFSA Joint Scientific Opinion on measures to reduce the need to use antimicrobial agents in animal husbandry in the European Union, and the resulting impacts on food safety (RONAFA)', 'Murphy D, Ricci A, Auce Z, Beechinor JG, Bergendahl H, Breathnach R, Bureš J, Duarte Da Silva JP', 2017, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2017.4666', 'https://doi.org/10.2903/j.efsa.2017.4666', 'https://europepmc.org/articles/PMC7010070?pdf=render', NULL, NULL, 245, NULL, 'other', 1, 'cc by-nd', 'EFSA and EMA have jointly reviewed measures taken in the EU to reduce the need for and use of antimicrobials in food-producing animals, and the resultant impacts on antimicrobial resistance (AMR). Reduction strategies have been implemented successfully in some Member States. Such strategies include national reduction targets, benchmarking of antimicrobial use, controls on prescribing and restrictions on use of specific critically important antimicrobials, together with improvements to animal husbandry and disease prevention and control measures. Due to the multiplicity of factors contributing to AMR, the impact of any single measure is difficult to quantify, although there is evidence of an association between reduction in antimicrobial use and reduced AMR. To minimise antimicrobial use, a multifaceted integrated approach should be implemented, adapted to local circumstances. Recommended options (non-prioritised) include: development of national strategies; harmonised systems for monitoring antimicrobial use and AMR development; establishing national targets for antimicrobial use reduction; use of on-farm health plans; increasing the responsibility of veterinarians for antimicrobial prescribing; training, education and raising public awareness; increasing the availability of rapid and reliable diagnostics; improving husbandry and management procedures for disease prevention and control; rethinking livestock production systems to reduce inherent disease risk. A limited number of studies provide robust evidence of alternatives to antimicrobials that positively influence health parameters. Possible alternatives include probiotics and prebiotics, competitive exclusion, bacteriophages, immunomodulators, organic acids and teat sealants. Development of a legislative framework that permits the use of specific products as alternatives should be considered. Further research to evaluate the potential of alternative farming systems on reducing AMR is also recommended. Animals suffering from bacterial infections should only be treated with antimicrobials based on veterinary diagnosis and prescription. Options should be reviewed to phase out most preventive use of antimicrobials and to reduce and refine metaphylaxis by applying recognised alternative measures.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('90deb923-26f9-4aea-a924-79ab29bed80e', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Impact of glyphosate and glyphosate-based herbicides on phyllospheric Methylobacterium', 'Palberg D, Kaszecki E, Dhanjal C, Kisiała A, Morrison EN, Stock N, Emery RJN', 2024, 'BMC plant biology', '10.1186/s12870-024-04818-x', 'https://doi.org/10.1186/s12870-024-04818-x', 'https://europepmc.org/articles/PMC10875822?pdf=render', NULL, NULL, 23, NULL, 'canada', 3, 'cc by', 'Symbiotic Methylobacterium comprise a significant portion of the phyllospheric microbiome, and are known to benefit host plant growth, development, and confer tolerance to stress factors. The near ubiquitous use of the broad-spectrum herbicide, glyphosate, in farming operations globally has necessitated a more expansive evaluation of the impacts of the agent itself and formulations containing glyphosate on important components of the plant phyllosphere, including Methylobacterium.This study provides an investigation of the sensitivity of 18 strains of Methylobacterium to glyphosate and two commercially available glyphosate-based herbicides (GBH). Nearly all strains of Methylobacterium showed signs of sensitivity to the popular GBH formulations WeatherMax® and Transorb® in a modified Kirby Bauer experiment. However, exposure to pure forms of glyphosate did not show a significant effect on growth for any strain in both the Kirby Bauer test and in liquid broth, until polysorbate-20 (Tween20) was added as a surfactant. Artificially increasing membrane permeability through the introduction of polysorbate-20 caused a 78-84% reduction in bacterial cell biomass relative to controls containing glyphosate or high levels of surfactant only (0-9% and 6-37% reduction respectively). Concentrations of glyphosate as low as 0.05% w/v (500 µg/L) from both commercial formulations tested, inhibited the culturability of Methylobacterium on fresh nutrient-rich medium.To better understand the compatibility of important phyllospheric bacteria with commercial glyphosate-based herbicides, this study endeavours to characterize sensitivity in multiple strains of Methylobacterium, and explore possible mechanisms by which toxicity may be induced.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('878b1975-08c4-4333-a172-be02d07b6374', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Improving the field efficacy of manuka oil using tank-mixes with surfactants and commercial organic herbicides', 'Sierra Harris, Zhenyi Li, Rachel N. Riddle, John O’Sullivan, Rene Van Acker', 2018, 'Canadian Journal of Plant Science', '10.1139/cjps-2018-0044', 'https://doi.org/10.1139/cjps-2018-0044', 'https://utoronto.scholaris.ca/bitstreams/3550b503-2ca4-4765-9292-c91f64dc21bc/download', NULL, NULL, 22, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb306386-24ad-4ef6-9ffb-bce75bb24ceb', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Influence of surfactant‐humectant adjuvants on physical properties, droplet size, and efficacy of glufosinate formulations', 'Estefania Gomiero Polli, Guilherme Sousa Alves, Jesaelen Gizotti de Moraes, Greg Robert Kruger', 2022, 'Agrosystems Geosciences & Environment', '10.1002/agg2.20230', 'https://doi.org/10.1002/agg2.20230', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/agg2.20230', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'Abstract Glufosinate efficacy is inconsistent among weed species and under environmental conditions that favor rapid droplet drying. Surfactant‐humectant adjuvants could maximize glufosinate efficacy by increasing wetting and penetration into the leaf surface while decreasing evaporation rate (ER). However, there is a lack of information in the literature about the interaction of surfactant‐humectants adjuvants with glufosinate. The objective of this study was to investigate the influence of surfactant‐humectant adjuvants on the physical properties, droplet size, and efficacy of two glufosinate formulations. Laboratory, greenhouse, and field studies were conducted at the Pesticide Application Technology Laboratory of the University of Nebraska‐Lincoln. Treatment design was a 2 × 5 factorial with two glufosinate formulations combined with five adjuvant treatments plus an untreated control. Density and viscosity of glufosinate solutions mostly increased with the addition of adjuvants. However, the influence of the adjuvants on dynamic surface tension (dST), static contact angle (sCA), and evaporation rate (ER) varied by glufosinate formulation, adjuvant, and relative humidity (RH). Under greenhouse conditions, an improvement in efficacy by adding adjuvants was mainly observed for Interline solutions. The addition of adjuvants to Interline solutions increased biomass reduction up to 19 and 35% for common lambsquarters (Chenopodium album L.) and kochia [Bassia scoparia (L.) A. J. Scott], respectively. Also, some of the adjuvants presented null or antagonistic influence on herbicide efficacy. No increase in control, biomass reduction, and mortality of horseweed (Erigeron canadensis L.) and Palmer amaranth (Amaranthus palmeri S. Watson) was observed with the use of adjuvants under field conditions. Herbicide‐adjuvant‐plant‐environment interaction is complex. Thus, the use of surfactant‐humectant adjuvants may not increase herbicide efficacy.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bb02bd43-7ee5-4ddc-8d27-bd4650d5a410', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Marine versus Non-Marine Bacterial Exopolysaccharides and Their Skincare Applications', 'Benhadda F, Zykwinska A, Colliec-Jouault S, Sinquin C, Thollas B, Courtois A, Fuzzati N, Toribio A', 2023, 'Marine drugs', '10.3390/md21110582', 'https://doi.org/10.3390/md21110582', 'https://europepmc.org/articles/PMC10672628?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Bacteria are well-known to synthesize high molecular weight polysaccharides excreted in extracellular domain, which constitute their protective microenvironment. Several bacterial exopolysaccharides (EPS) are commercially available for skincare applications in cosmetic products due to their unique structural features, conferring valuable biological and/or textural properties. This review aims to give an overview of bacterial EPS, an important group of macromolecules used in cosmetics as actives and functional ingredients. For this purpose, the main chemical characteristics of EPS are firstly described, followed by the basics of the development of cosmetic ingredients. Then, a focus on EPS production, including upstream and downstream processes, is provided. The diversity of EPS used in the cosmetic industry, and more specifically of marine-derived EPS is highlighted. Marine bacteria isolated from extreme environments are known to produce EPS. However, their production processes are highly challenging due to high or low temperatures; yield must be improved to reach economically viable ingredients. The biological properties of marine-derived EPS are then reviewed, resulting in the highlight of the challenges in this field.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1cd68839-29d1-4bd7-8ae6-35ab50c6d6b9', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Microbial Inoculants in Sustainable Agriculture: Advancements, Challenges, and Future Directions', 'Díaz-Rodríguez AM, Parra Cota FI, Cira Chávez LA, García Ortega LF, Estrada Alvarado MI, Santoyo G, de Los Santos-Villalobos S', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14020191', 'https://doi.org/10.3390/plants14020191', 'https://europepmc.org/articles/PMC11768969?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'The rapid growth of the human population has significantly increased the demand for food, leading to the intensification of agricultural practices that negatively impact the environment. Climate change poses a significant threat to global food production, as it can disrupt crop yields and modify the lifecycle stages of phytopathogens and pests. To address these challenges, the use of microbial inoculants, which are bioproducts containing beneficial microorganisms known as plant growth promotion microorganisms (PGPMs), has emerged as an innovative approach in sustainable agriculture. This review covers the isolation and identification of beneficial strains, the screening and selection process, the optimization of production techniques, and the importance of quality control and field testing. It also discusses the key points for the development and formulation of high-quality microbial inoculants, as well as highlights their advancements, current challenges, and future directions for research and application.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('004671e6-95e2-4599-9e1b-3326a2d909e6', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Microbial Surfactants: The Next Generation Multifunctional Biomolecules for Applications in the Petroleum Industry and Its Associated Environmental Remediation', 'Fenibo EO, Ijoma GN, Selvarajan R, Chikere CB', 2019, 'Microorganisms', '10.3390/microorganisms7110581', 'https://doi.org/10.3390/microorganisms7110581', 'https://europepmc.org/articles/PMC6920868?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Surfactants are a broad category of tensio-active biomolecules with multifunctional properties applications in diverse industrial sectors and processes. Surfactants are produced synthetically and biologically. The biologically derived surfactants (biosurfactants) are produced from microorganisms, with Pseudomonas aeruginosa, Bacillus subtilis Candida albicans, and Acinetobacter calcoaceticus as dominant species. Rhamnolipids, sophorolipids, mannosylerithritol lipids, surfactin, and emulsan are well known in terms of their biotechnological applications. Biosurfactants can compete with synthetic surfactants in terms of performance, with established advantages over synthetic ones, including eco-friendliness, biodegradability, low toxicity, and stability over a wide variability of environmental factors. However, at present, synthetic surfactants are a preferred option in different industrial applications because of their availability in commercial quantities, unlike biosurfactants. The usage of synthetic surfactants introduces new species of recalcitrant pollutants into the environment and leads to undesired results when a wrong selection of surfactants is made. Substituting synthetic surfactants with biosurfactants resolves these drawbacks, thus interest has been intensified in biosurfactant applications in a wide range of industries hitherto considered as experimental fields. This review, therefore, intends to offer an overview of diverse applications in which biosurfactants have been found to be useful, with emphases on petroleum biotechnology, environmental remediation, and the agriculture sector. The application of biosurfactants in these settings would lead to industrial growth and environmental sustainability.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff983611-d03a-426b-9948-0a922cc69717', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'The Importance of Selecting Appropriate Rotation and Tank-Mix Partners for Novel SDHIs to Enhance Botrytis Fruit Rot Control in Strawberry', 'Achour Amiri, Adrian I. Zuniga, Leandro G. Cordova, Natália A. Peres', 2018, 'Plant Disease', '10.1094/pdis-07-18-1276-re', 'https://doi.org/10.1094/pdis-07-18-1276-re', 'https://apsjournals.apsnet.org/doi/pdf/10.1094/PDIS-07-18-1276-RE', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f80f7a7f-1232-438a-9db5-06311655c47b', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Modern Approaches for the Development of New Herbicides Based on Natural Compounds', 'Berestetskiy A', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12020234', 'https://doi.org/10.3390/plants12020234', 'https://europepmc.org/articles/PMC9864389?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Weeds are a permanent component of anthropogenic ecosystems. They require strict control to avoid the accumulation of their long-lasting seeds in the soil. With high crop infestation, many elements of crop production technologies (fertilization, productive varieties, growth stimulators, etc.) turn out to be practically meaningless due to high yield losses. Intensive use of chemical herbicides (CHs) has led to undesirable consequences: contamination of soil and wastewater, accumulation of their residues in the crop, and the emergence of CH-resistant populations of weeds. In this regard, the development of environmentally friendly CHs with new mechanisms of action is relevant. The natural phytotoxins of plant or microbial origin may be explored directly in herbicidal formulations (biorational CHs) or indirectly as scaffolds for nature-derived CHs. This review considers (1) the main current trends in the development of CHs that may be important for the enhancement of biorational herbicides; (2) the advances in the development and practical application of natural compounds for weed control; (3) the use of phytotoxins as prototypes of synthetic herbicides. Some modern approaches, such as computational methods of virtual screening and design of herbicidal molecules, development of modern formulations, and determination of molecular targets, are stressed as crucial to make the exploration of natural compounds more effective.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4f76b9a8-1052-4f2e-9c8c-e35b7de92d63', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Nozzle Selection and Adjuvant Impact on the Efficacy of Glyphosate and PPO-Inhibiting Herbicide Tank-Mixtures', 'Jesaelen Gizotti de Moraes, Thomas R. Butts, Vitor Muller Anunciato, Joe D. Luck, Wesley Clint Hoffmann, Ulisses R. Antuniassi, Greg Robert Kruger', 2021, 'Agronomy', '10.3390/agronomy11040754', 'https://doi.org/10.3390/agronomy11040754', 'https://www.mdpi.com/2073-4395/11/4/754/pdf?version=1618398829', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'PPO-inhibiting herbicides in combination with glyphosate for postemergence applications is a common approach to manage glyphosate- and ALS-inhibitor-resistant weeds. PPO-inhibitors can reduce glyphosate translocation when applied in tank-mixtures, but adjuvants may be used to overcome this effect. Additionally, optimal droplet size may be affected by tank-mixtures of different herbicides and it can be crucial to herbicide efficacy. Field and greenhouse studies were conducted to investigate the impact of nozzle selection and adjuvants on weed control and interactions when applying PPO-inhibitors (fomesafen or lactofen) alone or in tank-mixture with glyphosate to five weed species using six nozzle types. Ultra-coarse droplets were just as effective as medium droplets regardless of the spray solution, but have a lower likelihood of off-target movement. Tank-mixtures applied were consistently antagonistic to common lambsquarters, horseweed, and Palmer amaranth. Only fomesafen was antagonistic to kochia whereas synergistic interactions were observed when glyphosate plus lactofen were applied in combination with COC, DRA + COC, or NIS. Separate applications are advisable with herbicide- and weed-specific situations to avoid antagonism, which is necessary to achieve optimum weed control and maintain the effectiveness of PPO-inhibitors. Future research should continue to look at these important interactions across a wide range of weed species.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e7845f78-62c1-4013-b03d-d6029c5f4ebd', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Physical–Chemical Properties, Droplet Size, and Efficacy of Dicamba Plus Glyphosate Tank Mixture Influenced by Adjuvants', 'Estefania Gomiero Polli, Guilherme Sousa Alves, João Victor de Oliveira, Greg Robert Kruger', 2021, 'Agronomy', '10.3390/agronomy11071321', 'https://doi.org/10.3390/agronomy11071321', 'https://www.mdpi.com/2073-4395/11/7/1321/pdf?version=1626171330', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Dicamba plus glyphosate tank mixture have been largely adopted for postemergence weed control after the development of dicamba-tolerant crops. Ammonium sulfate is commonly used as water conditioner (WC) to increase glyphosate efficacy, but its use is restricted for dicamba herbicides. The use of non-AMS water conditioner and other adjuvants could be a way to optimize efficacy of this tank mixture while mitigating herbicide off-target movement. The objective of this study was to determine the physical–chemical properties and droplet size distribution of dicamba and glyphosate solutions with and without non-AMS WC alone and tank mixed with other adjuvants and evaluate the response of weed species to these solutions under greenhouse and field conditions. The adjuvants mostly increased density and viscosity and decreased contact angle and surface tension of herbicide solutions. In presence of WC, except for the adjuvants containing drift reducing agent, Dv0.5 decreased with the addition of adjuvants. Under greenhouse conditions, biomass reduction increased up to 47 and 33 percentage points for velvetleaf and c. waterhemp when adjuvants were added to solutions without WC, respectively. No increase in control of horseweed and Palmer amaranth was observed with the use of adjuvants under field conditions.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0593a72-29c9-4807-a495-7435337694dc', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Predominance of Metabolic Resistance in a Six-Way-Resistant Palmer Amaranth (Amaranthus palmeri) Population', 'Shyam C, Borgato EA, Peterson DE, Dille JA, Jugulam M', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.614618', 'https://doi.org/10.3389/fpls.2020.614618', 'https://europepmc.org/articles/PMC7841332?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Evolution of multiple herbicide resistance in Palmer amaranth across the United States is a serious challenge for its management. Recently, a Palmer amaranth population (KCTR; Kansas Conservation Tillage Resistant) from a long-term conservation tillage research project in Kansas, United States, was found uncontrolled by several commonly used herbicides. Importantly, this field did not have a history of repeated use of some of the herbicides for which the KCTR Palmer amaranth population showed lack of control. The objectives of this study were to confirm the evolution of multiple resistances and determine possible mechanism(s) of resistance in KCTR Palmer amaranth plants. In response to post-emergence application, 28-100% of KCTR Palmer amaranth survived field recommended rates of 2,4-D, ALS-, PS II-, EPSPS-, PPO-, HPPD-inhibitor herbicides, or tank- or pre-mixture of PS II- and HPPD-inhibitor herbicides, confirming evolution of six-way resistance in this Palmer amaranth population. However, this population was found susceptible to the PS I- and glutamine synthetase inhibitor herbicides. Chlorsulfuron-, imazethapyr-, and atrazine-resistant plants did not show any previously reported mutation in ALS and psbA genes, the target sites of these herbicides, respectively. However, the survivors of glyphosate treatment showed amplification of EPSPS gene (up to 88 copies). The KCTR plants pretreated with cytochrome P450 or GST inhibitors along with atrazine, 2,4-D, lactofen, or mesotrione had significantly less biomass accumulation than those treated with herbicides alone. Plants treated with P450 inhibitor followed by imazethapyr showed moderate reduction of biomass in KCTR which was statistically similar to a susceptible Palmer amaranth population treated with imazethapyr. These results suggest predominance of metabolic resistance possibly mediated by cytochrome P450 and GST enzyme activity that may have predisposed the KCTR Palmer amaranth population to evolve resistance to multiple herbicides. This is the first report of evolution of six-way resistance in a single Palmer amaranth population. Appropriate management strategies, including integration of cultural, and mechanical, and herbicide mixtures, are warranted to control such Palmer amaranth populations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9332b88e-23e4-4d8a-bb12-5d9695a4a9ec', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Reduced adsorption of dicamba spray droplets on leaves as droplet size increases', 'Cody F. Creech, Greg Robert Kruger, Milena Oliveira, Amanda C. Easterly', 2024, 'Weed Technology', '10.1017/wet.2024.34', 'https://doi.org/10.1017/wet.2024.34', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/77E246A0F1EFC16BA73BDF16915E4711/S0890037X24000344a.pdf/div-class-title-reduced-adsorption-of-dicamba-spray-droplets-on-leaves-as-droplet-size-increases-div.pdf', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Off-target movement of growth regulator herbicides can cause severe injury to susceptible plants. Apart from not spraying on windy days or at excessive boom heights, making herbicide applications using nozzles that produce large droplets is the preferred method for reducing herbicide drift. Although large droplets maintain a higher velocity and are more likely to reach the leaf surface in windy conditions, their ability to remain on the leaf surface is poorly understood. Upon impact with the leaf surface, droplets may shatter, bounce, roll off, or be retained on the leaf surface. We examined how different nozzles, pressures, and adjuvants impact spray droplet adsorption on the leaf surface of common lambsquarters and soybean. Plants were grown in a greenhouse and sprayed in a spray chamber. Three nozzles (XR, AIXR, and TTI) were evaluated at 138, 259, and 379 kPa, respectively. Dicamba (0.14 kg ae ha−1) was applied alone and with methylated seed oil (MSO), a non-ionic surfactant, silicone-based adjuvant, crop oil concentrate, or a drift reduction adjuvant. A 1,3,6,8-pyrene tetra sulfonic acid tetra sodium salt was added as a tracer. Dicamba spray droplet adsorption when using the XR nozzle, which produced the smallest spray droplets, was 1.75 times greater than when applied with the TTI nozzle with the largest spray droplets. Applying dicamba with MSO increased adsorption on leaf surfaces nearly 4 times the amount achieved without an adjuvant. The lowest application pressure (138 kPa) increased dicamba spray volume adsorbed more than 10% compared to the higher pressures of 259 and 379 kPa. By understanding the impacts of these application parameters on dicamba spray droplet adsorption, applicators can select application parameters, equipment, and adjuvants that will maximize the amount of dicamba spray volume retained on the target leaf surface while minimizing dicamba spray drift.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('14f9aff9-36b6-4a39-b664-aafac0fb515e', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Reduced Translocation of Glyphosate and Dicamba in Combination Contributes to Poor Control of Kochia scoparia: Evidence of Herbicide Antagonism', 'Ou J, Thompson CR, Stahlman PW, Bloedow N, Jugulam M', 2018, 'Scientific reports', '10.1038/s41598-018-23742-3', 'https://doi.org/10.1038/s41598-018-23742-3', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC5871845.1/PMC5871845.1.pdf', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by', 'Kochia scoparia is a troublesome weed across the Great Plains of North America. Glyphosate and dicamba have been used for decades to control K. scoparia. Due to extensive selection, glyphosate- and dicamba-resistant (GDR) K. scoparia have evolved in the USA. Herbicide mixtures are routinely used to improve weed control. Herbicide interactions if result in an antagonistic effect can significantly affect the management of weeds, such as K. scoparia. To uncover the interaction of glyphosate and dicamba when applied in combination in K. scoparia management the efficacies of different doses of glyphosate plus dicamba were evaluated under greenhouse and field conditions using GDR and a known glyphosate- and dicamba-susceptible (GDS) K. scoparia. The results of greenhouse and field studies suggest that the combination of glyphosate and dicamba application controlled GDS, but glyphosate alone provided a better control of GDR K. scoparia compared to glyphosate plus dicamba combinations. Furthermore, investigation of the basis of this response suggested glyphosate and dicamba interact antagonistically and consequently, the translocation of both herbicides was significantly reduced resulting in poor control of K. scoparia. Therefore, a combination of glyphosate plus dicamba may not be a viable option to control GDR K. scoparia.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1ec0a288-5239-49a8-b2b5-c35659fef0bc', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Spray drift and droplet spectrum from dicamba sprayed alone or mixed with adjuvants using air-induction nozzles', 'Guilherme Sousa Alves, Greg Robert Kruger, João Paulo Arantes Rodrigues da Cunha', 2018, 'Pesquisa Agropecuária Brasileira', '10.1590/s0100-204x2018000600005', 'https://doi.org/10.1590/s0100-204x2018000600005', 'http://www.scielo.br/pdf/pab/v53n6/1678-3921-pab-53-06-693.pdf', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc-by', 'Abstract: The objective of this work was to evaluate the spray drift and droplet spectrum of dicamba applied alone or with potential drift-reducing adjuvants, using air-induction flat fan nozzles. Standard (XR and TT) and air-induction (AIXR and TTI) nozzles were evaluated in a wind tunnel. The adjuvants used were polymer, ammonium sulfate, vegetable oil, and phosphatidylcholine. The applications were conducted at 276 kPa pressure and 3.5 m s-1 wind speed. The droplet spectrum was measured using a laser diffraction system. Round strings were used as drift collectors, positioned perpendicularly to the wind direction, at 2, 3, 4, 5, 6, 7, and 12 m from the nozzle. Drift was calculated by quantifying, through fluorimetry, a fluorescent tracer added to each solution at 1 g L-1. Droplet spectrum and dicamba drift depend on the interaction between spray composition and nozzle type. Air-induction nozzles are more recommended for dicamba applications, especially the TTI nozzle. Polymer and ammonium sulfate increase droplet size in all nozzle types, which may reduce drift to nearby crops.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bccf1a47-6d51-4e73-b34a-06cbbffc79a8', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Spray water quality and herbicide performance: a review', 'Olumide Samuel Daramola, William G. Johnson, David L. Jordan, Gurinderbir S. Chahal, Pratap Devkota', 2022, 'Weed Technology', '10.1017/wet.2022.97', 'https://doi.org/10.1017/wet.2022.97', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/BDD446C6C1ECD0E961A4F9A021FD2D17/S0890037X22000975a.pdf/div-class-title-spray-water-quality-and-herbicide-performance-a-review-div.pdf', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Water is the primary carrier for herbicide applications. Spray water qualities such as pH, hardness, temperature, or turbidity can influence herbicide performance and may need to be amended for optimum weed control. Water quality factors can affect herbicide activity by reducing solubility, enhancing degradation in the spray tank, or forming herbicide-salt complexes with mineral cations, thereby reducing the absorption, translocation, and subsequent weed control. The available literature suggests that the effect of water quality varies with herbicide chemistry and weed species. The efficacy of weak-acid herbicides such as glyphosate, glufosinate, clethodim, sethoxydim, bentazon, and 2,4-D is improved with acidic water pH; however, the efficacy of sulfonylurea herbicides is negatively impacted. Hard-water antagonism is more prevalent with weak-acid herbicides, and trivalent cations are the most problematic. Spray solution temperature between 18 C and 44 C is optimum for some weak-acid herbicides; however, their efficacy can be reduced at relatively low (5 C) or high (56 C) water temperature. The effect of water turbidity is severe on cationic herbicides such as paraquat and diquat, and herbicides with low soil mobility such as glyphosate. Although adjuvants are recommended to overcome the negative effect of spray water hardness or pH, the response has been inconsistent with the herbicide chemistry and weed species. Moreover, information on the effect of spray water quality on various herbicide chemistries, weed species, and adjuvants is limited; therefore, it is difficult to develop guidelines for improving weed control efficacy. Further research is needed to determine the effect of spray water factors and develop specific recommendations for improving herbicide efficacy on problematic weed species.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b9b08878-ff5f-45b8-be82-0e1b5b9b7bc3', 'e3b084b5-19cd-4450-8a12-b56ac2f62228', 'Water-soluble polymers in agriculture: xanthan gum as eco-friendly alternative to synthetics', 'Berninger T, Dietz N, González López Ó', 2021, 'Microbial biotechnology', '10.1111/1751-7915.13867', 'https://doi.org/10.1111/1751-7915.13867', 'https://europepmc.org/articles/PMC8449660?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc-nd', 'Water-soluble polymers (WSPs) are a versatile group of chemicals used across industries for different purposes such as thickening, stabilizing, adhesion and gelation. Synthetic polymers have tailored characteristics and are chemically homogeneous, whereas plant-derived biopolymers vary more widely in their specifications and are chemically heterogeneous. Between both sources, microbial polysaccharides are an advantageous compromise. They combine naturalness with defined material properties, precisely controlled by optimizing strain selection, fermentation operational parameters and downstream processes. The relevance of such bio-based and biodegradable materials is rising due to increasing environmental awareness of consumers and a tightening regulatory framework, causing both solid and water-soluble synthetic polymers, also termed ''microplastics'', to have come under scrutiny. Xanthan gum is the most important microbial polysaccharide in terms of production volume and diversity of applications, and available as different grades with specific properties. In this review, we will focus on the applicability of xanthan gum in agriculture (drift control, encapsulation and soil improvement), considering its potential to replace traditionally used synthetic WSPs. As a spray adjuvant, xanthan gum prevents the formation of driftable fine droplets and shows particular resistance to mechanical shear. Xanthan gum as a component in encapsulated formulations modifies release properties or provides additional protection to encapsulated agents. In geotechnical engineering, soil amended with xanthan gum has proven to increase water retention, reduce water evaporation, percolation and soil erosion - topics of high relevance in the agriculture of the 21st century. Finally, hands-on formulation tips are provided to facilitate exploiting the full potential of xanthan gum in diverse agricultural applications and thus providing sustainable solutions.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('792ca23b-908a-460f-b660-07ca6ca3326d', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Abiotic Stress and Reactive Oxygen Species: Generation, Signaling, and Defense Mechanisms', 'Sachdev S, Ansari SA, Ansari MI, Fujita M, Hasanuzzaman M', 2021, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox10020277', 'https://doi.org/10.3390/antiox10020277', 'https://europepmc.org/articles/PMC7916865?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by', 'Climate change is an invisible, silent killer with calamitous effects on living organisms. As the sessile organism, plants experience a diverse array of abiotic stresses during ontogenesis. The relentless climatic changes amplify the intensity and duration of stresses, making plants dwindle to survive. Plants convert 1-2% of consumed oxygen into reactive oxygen species (ROS), in particular, singlet oxygen (1O2), superoxide radical (O2•-), hydrogen peroxide (H2O2), hydroxyl radical (•OH), etc. as a byproduct of aerobic metabolism in different cell organelles such as chloroplast, mitochondria, etc. The regulatory network comprising enzymatic and non-enzymatic antioxidant systems tends to keep the magnitude of ROS within plant cells to a non-damaging level. However, under stress conditions, the production rate of ROS increases exponentially, exceeding the potential of antioxidant scavengers instigating oxidative burst, which affects biomolecules and disturbs cellular redox homeostasis. ROS are similar to a double-edged sword; and, when present below the threshold level, mediate redox signaling pathways that actuate plant growth, development, and acclimatization against stresses. The production of ROS in plant cells displays both detrimental and beneficial effects. However, exact pathways of ROS mediated stress alleviation are yet to be fully elucidated. Therefore, the review deposits information about the status of known sites of production, signaling mechanisms/pathways, effects, and management of ROS within plant cells under stress. In addition, the role played by advancement in modern techniques such as molecular priming, systems biology, phenomics, and crop modeling in preventing oxidative stress, as well as diverting ROS into signaling pathways has been canvassed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06a8b3d8-aab2-4d52-b181-9822a9b92c33', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Allelopathy and its application as a weed management tool: A review', 'Khamare Y, Chen J, Marble SC', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.1034649', 'https://doi.org/10.3389/fpls.2022.1034649', 'https://europepmc.org/articles/PMC9742440?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Weeds are a serious threat to crop production as they interfere with the crop growth and development and result in significant crop losses. Weeds actually cause yield loss higher than any other pest in crop production. As a result, synthetic herbicides have been widely used for weed management. Heavy usage of synthetic herbicides, however, has resulted in public concerns over the impact of herbicides on human health and the environment. Due to various environmental and health issues associated with synthetic herbicides, researchers have been exploring alternative environmentally friendly means of controlling weed. Among them, incorporating allelopathy as a tool in an integrated weed management plan could meaningfully bring down herbicide application. Allelopathy is a biological phenomenon of chemical interaction between plants, and this phenomenon has great potential to be used as an effective and environmentally friendly tool for weed management in field crops. In field crops, allelopathy can be applied through intercropping, crop rotation, cover crops, mulching and allelopathic water extracts to manage weeds. Accumulating evidence indicates that some plant species possess potent allelochemicals that have great potential to be the ecofriendly natural herbicides. This review is intended to provide an overview of several allelopathic species that release some form of the potent allelochemical with the potential of being used in conventional or organic agriculture. Further, the review also highlights potential ways allelopathy could be utilized in conventional or organic agriculture and identify future research needs and prospects. It is anticipated that the phenomenon of allelopathy will be further explored as a weed management tool, and it can be a part of a sustainable, ecological, and integrated weed management system.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('083a5d18-3831-492a-bab4-283639e5d001', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Bioherbicides: An Eco-Friendly Tool for Sustainable Weed Management', 'Hasan M, Ahmad-Hamdani MS, Rosli AM, Hamdan H', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10061212', 'https://doi.org/10.3390/plants10061212', 'https://europepmc.org/articles/PMC8232089?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Weed management is an arduous undertaking in crop production. Integrated weed management, inclusive of the application of bioherbicides, is an emerging weed control strategy toward sustainable agriculture. In general, bioherbicides are derived either from plants containing phytotoxic allelochemicals or certain disease-carrying microbes that can suppress weed populations. While bioherbicides have exhibited great promise in deterring weed seed germination and growth, only a few in vitro studies have been conducted on the physiological responses they evoke in weeds. This review discusses bioherbicide products that are currently available on the market, bioherbicide impact on weed physiology, and potential factors influencing bioherbicide efficacy. A new promising bioherbicide product is introduced at the end of this paper. When absorbed, phytotoxic plant extracts or metabolites disrupt cell membrane integrity and important biochemical processes in weeds. The phytotoxic impact on weed growth is reflected in low levels of root cell division, nutrient absorption, and growth hormone and pigment synthesis, as well as in the development of reactive oxygen species (ROS), stress-related hormones, and abnormal antioxidant activity. The inconsistency of bioherbicide efficacy is a primary factor restricting their widespread use, which is influenced by factors such as bioactive compound content, weed control spectrum, formulation, and application method.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7faaa2ea-5cd4-4be8-97b8-75ee0f23ec26', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Biology, management and biochemical/genetic characterization of weed biotypes resistant to acetolactate synthase inhibitor herbicides', 'Patrícia Andrea Monquero, Pedro Jacob Christoffoleti, Helaine Carrer', 2003, 'Scientia Agricola', NULL, 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0103-90162003000300013&tlng=en', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0103-90162003000300013&tlng=en', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'Bidens pilosa and Amaranthus quitensis are major weeds infesting soybean [Glycine max L (Merrill)] fields in Brazil and Argentina. The repetitive use of acetolactate synthase (ALS EC 4.1.3.18) inhibiting herbicides in São Gabriel do Oeste, MS, Brazil and in the provinces of Córdoba and Tucumã, Argentina, has selected for resistant (R) biotypes of these weeds. Research work was developed to study the management, growth, biochemistry, and genetics of these R weed biotypes. In a field experiment it was found that chlorimuron-ethyl and imazethapyr at recommended rates (both ALS inhibitor herbicides), did not control R B. pilosa, but the alternative lactofen, fomesafen and bentazon were effective, either sprayed alone or mixed with the ALS inhibitor herbicides. Greenhouse studies confirmed the cross-resistance of both R biotypes to the imidazolinone and sulfonylurea herbicides, and these alternative herbicides, when sprayed alone or mixed with the ALS inhibitor, efficiently controlled both R and S populations. A growth analysis of the R and S biotypes of these weeds, under non-competitive conditions, indicated that there is no adaptive cost to the R biotypes (pleiotropic effect). A quick bioassay using ALS and ketoacid reductoisomerase (KARI) inhibitors showed that the resistance of the R biotypes to herbicides is related to a lack of sensitivity of the ALS enzyme to the herbicides. On the other hand, the sequencing of the gene that codifies the ALS resistance in R A. quitensis did not present any mutation in the A Domain region, suggesting that other positions of the gene that confer insensitivity of the ALS to sulfonylurea and imidazolinone herbicides could have mutated.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c7a76e36-4e20-4a84-8bbf-48ab509d2106', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Cell suspension culture-mediated incorporation of the rice bel gene into transgenic cotton.', 'Liping Ke, RuiE Liu, Bijue Chu, Xiushuang Yu, Jie Sun, Brian Jones, Gang Pan, Xiaofei Cheng', 2012, 'PLoS ONE', '10.1371/journal.pone.0039974', 'https://doi.org/10.1371/journal.pone.0039974', 'http://europepmc.org/articles/PMC3388058?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'Cotton plants engineered for resistance to the herbicides, glyphosate or glufosinate have made a considerable impact on the production of the crop worldwide. In this work, embryogenic cell cultures derived from Gossypium hirsutum L. cv Coker 312 hypocotyl callus were transformed via Agrobacterium tumefaciens with the rice cytochrome P450 gene, CYP81A6 (bel). In rice, bel has been shown to confer resistance to both bentazon and sulfanylurea herbicides. Transformed cells were selected on a liquid medium supplemented alternately or simultaneously with kanamycin (50mg/L) and bentazon (4.2 µmol). A total of 17 transgenic cotton lines were recovered, based on the initial resistance to bentazon and on PCR detection of the bel transgene. Bel integration into the cotton genome was confirmed by Southern blot and expression of the transgene was verified by RT-PCR. In greenhouse and experimental plot trials, herbicide (bentazon) tolerance of up to 1250 mg/L was demonstrated in the transgenic plants. Transgenic lines with a single copy of the bel gene showed normal Mendelian inheritance of the characteristic. Importantly, resistance to bentazon was shown to be stably incorporated in the T1, T2 and T3 generations of self-fertilised descendents and in plants outcrossed to another upland cotton cultivar. Engineering resistance to bentazon in cotton through the heterologous expression of bel opens the possibility of incorporating this trait into elite cultivars, a strategy that would give growers a more flexible alternative to weed management in cotton crops.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('52ae34a6-f863-4037-9a85-928c85f29d8e', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'CHEMICAL OPTIONS FOR THE CONTROL OF SILVERLEAF NIGHTSHADE (Solanum elaeagnifolium)', 'T.K. GITSOPOULOS, C.A. DAMALAS, I. GEORGOULAS', 2017, 'Planta Daninha', '10.1590/s0100-83582017350100064', 'https://doi.org/10.1590/s0100-83582017350100064', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-83582017000100262&tlng=en', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT Silverleaf nightshade is a difficult-to-control perennial weed. Field experiments were conducted in northern Greece to evaluate the control of silverleaf nightshade with POST applications of glufosinate (1,500 g a.i. ha-1), glyphosate (3,600 g a.i. ha-1), tembotrione (148.5 g a.i. ha-1), and a mixture of tembotrione plus bentazon (148.5 plus 1,440 g a.i. ha-1) at an early vegetative stage (plant height 10-15 cm) and at the beginning of flowering (plant height 30-50 cm). Glufosinate provided > 95% control of silverleaf nightshade from 7 to 39 days after treatment (DAT), regardless of the vegetative stage at herbicide application. Similarly, glyphosate provided up to 90% control around 39 DAT at either growth stage applied, exhibiting gradually increasing efficacy. Tembotrione alone controlled silverleaf nightshade 85% when applied at the early vegetative stage and 48% when applied at the beginning of flowering. The mixture of tembotrione plus bentazon applied at the beginning of flowering exhibited 74% control at 21 DAT; however, the control was decreased to 41% at 35 DAT. When the mixture was applied at the early vegetative stage, S. elaeagnifolium control was 61% at 23 DAT, which was decreased to 27% at 39 DAT. Glufosinate and glyphosate were found to be reliable options for control of silverleaf nightshade when applied at either weed growth stage; tembotrione could be also another reliable option, however, when applied only at an early vegetative stage. The results have significant implications for developing appropriate management practices for silverleaf nightshade, taking into account chemical options for preventing the evolution of herbicide resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e83382e-be0b-4cbc-92ea-f115f6d94b90', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Defenses Against ROS in Crops and Weeds: The Effects of Interference and Herbicides', 'Caverzan A, Piasecki C, Chavarria G, Stewart CN Jr, Vargas L', 2019, 'International journal of molecular sciences', '10.3390/ijms20051086', 'https://doi.org/10.3390/ijms20051086', 'https://europepmc.org/articles/PMC6429093?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'The antioxidant defense system acts to maintain the equilibrium between the production of reactive oxygen species (ROS) and the elimination of toxic levels of ROS in plants. Overproduction and accumulation of ROS results in metabolic disorders and can lead to the oxidative destruction of the cell. Several stress factors cause ROS overproduction and trigger oxidative stress in crops and weeds. Recently, the involvement of the antioxidant system in weed interference and herbicide treatment in crops and weeds has been the subject of investigation. In this review, we address ROS production and plant mechanisms of defense, alterations in the antioxidant system at transcriptional and enzymatic levels in crops induced by weed interference, and herbicide exposure in crops and weeds. We also describe the mechanisms of action in herbicides that lead to ROS generation in target plants. Lastly, we discuss the relations between antioxidant systems and weed biology and evolution, as well as the interactive effects of herbicide treatment on these factors.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fdef3e0e-c16d-4fb2-891f-1d957ccaa86a', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Effect of Weeds and Some Methods for their Control in Seed Production Stands of Sainfoin (Onobrychis viciifolia Scop.)', 'Tsvetanka Dimitrova', 2010, 'Pesticidi i Fitomedicina', NULL, 'http://www.pesting.org.rs/download.php/documents/25-2/25-2%20163-170.pdf', 'http://www.pesting.org.rs/download.php/documents/25-2/25-2%20163-170.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'During the 2007-2009 period in the experimental field of the Institute of Forage Cropsa study was conducted with the purpose of investigating the effect of weeds and somemethods for their control in seed production stands of sainfoin (Onobrychis viciifolia Scop.).The trial was carried out on a slightly leached chernozem on an area with a natural backgroundof weed infestation. As a result of the study it was found:Establishment of very uniform and productive seed production stands of sainfoinrequired effective weed control concentrated mainly in the first year when the degree ofweed infestation was the highest and reached to a number of 245 plants/m2 and the freshweed biomass to 1311 g/m2.The chemical control method showed the highest efficacy had the highest efficiencywhen, in the year of stand establishment at the stage of second-fourth true leaf of sainfoin,the treatment was conducted with imazamox 40g/l (Pulsar 40) at the dose of 48 g a.i./haor with the system of Bentazon 600 g/l (Basagran 600 SL) – 900 g a.i./ha – fluazifop-P-butylg/l (Fusilad Forte) – 120 g a.i./ha. In the years of seed production in spring at the beginningof vegetation, the treatment was conducted with imazamox 40 g/l (Pulsar 40) at the doseof 20 g a.i./ha + adjuvant DESH at the dose of 1000 ml/ha.An alternative to the chemical method is to sow sainfoin under cover of spring barleyachieving more complete use of the area in the first year, a weed suppressive and ecologicaleffect, but some negative residual effect on the crop was also observed;The pure stands of sainfoin with chemical control of weeds had the highest seed productivity,exceeding the zero check by 24 to 28%, followed by the stands with spring barleyas a cover crop with an increase of 12% and the mixed stands of sainfoin with crestedwheatgrass had the lowest productivity.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c9cbcd81-eed4-4699-a857-5bb8fdaaa78d', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Environmental impacts of genetically modified (GM) crop use 1996-2015: Impacts on pesticide use and carbon emissions', 'Brookes G, Barfoot P', 2017, 'GM crops & food', '10.1080/21645698.2017.1309490', 'https://doi.org/10.1080/21645698.2017.1309490', 'https://europepmc.org/articles/PMC5443613?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by-nc-nd', 'This paper updates previous assessments of important environmental impacts associated with using crop biotechnology in global agriculture. It focuses on the environmental impacts associated with changes in pesticide use and greenhouse gas emissions arising from the use of GM crops since their first widespread commercial use in the mid-1990s. The adoption of GM insect resistant and herbicide tolerant technology has reduced pesticide spraying by 618.7 million kg (-8.1%) and, as a result, decreased the environmental impact associated with herbicide and insecticide use on these crops (as measured by the indicator, the Environmental Impact Quotient (EIQ)) by18.6%. The technology has also facilitated important cuts in fuel use and tillage changes, resulting in a significant reduction in the release of greenhouse gas emissions from the GM cropping area. In 2015, this was equivalent to removing 11.9 million cars from the roads.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b6fa4ee5-bb1c-4c54-b554-a3035d66cd37', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Faba Bean Cultivation - Revealing Novel Managing Practices for More Sustainable and Competitive European Cropping Systems', 'Karkanis A, Ntatsi G, Lepse L, Fernández JA, Vågen IM, Rewald B, Alsiņa I, Kronberga A', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01115', 'https://doi.org/10.3389/fpls.2018.01115', 'https://europepmc.org/articles/PMC6083270?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Faba beans are highly nutritious because of their high protein content: they are a good source of mineral nutrients, vitamins, and numerous bioactive compounds. Equally important is the contribution of faba bean in maintaining the sustainability of agricultural systems, as it is highly efficient in the symbiotic fixation of atmospheric nitrogen. This article provides an overview of factors influencing faba bean yield and quality, and addresses the main biotic and abiotic constraints. It also reviews the factors relating to the availability of genetic material and the agronomic features of faba bean production that contribute to high yield and the improvement of European cropping systems. Emphasis is to the importance of using new high-yielding cultivars that are characterized by a high protein content, low antinutritional compound content, and resistance to biotic and abiotic stresses. New cultivars should combine several of these characteristics if an increased and more stable production of faba bean in specific agroecological zones is to be achieved. Considering that climate change is also gradually affecting many European regions, it is imperative to breed elite cultivars that feature a higher abiotic-biotic stress resistance and nutritional value than currently used cultivars. Improved agronomical practices for faba bean crops, such as crop establishment and plant density, fertilization and irrigation regime, weed, pest and disease management, harvesting time, and harvesting practices are also addressed, since they play a crucial role in both the production and quality of faba bean.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('45edf6da-a561-4090-8334-758781e7527b', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'From noncultivated areas to the field: a case of cut-leaved gipsywort (Lycopus exaltatus L.) and its response to herbicides in Balkan major crops', 'Milan Brankov, Theresa Piskackova, Miloš Rajković, Jelena Vukadinović, Miloš Zarić', 2025, 'Weed Technology', '10.1017/wet.2025.10040', 'https://doi.org/10.1017/wet.2025.10040', 'https://www.cambridge.org/core/product/identifier/S0890037X25100407/type/journal_article', NULL, NULL, 9, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Certain plant species have the potential to establish themselves in agricultural fields, especially when they are already present nearby. Their spread can be influenced by improper management or intentional and unintentional introduction. Recently, cut-leaved gipsywort (Lycopus exaltatus L.) has been increasingly present in some row crops, where it was previously found only along field edges and irrigation channels, with no data about their presence in crops. Currently, no effective control methods for this rhizomatous species have been reported. To address this, 11 herbicides commonly used for weed management in major crops were evaluated in greenhouse studies. These included bentazon, dicamba, foramsulfuron, glyphosate, halauxifen-methyl, imazamox, mesotrione, nicosulfuron, tembotrione, thifensulfuron-methyl, and tribenuron-methyl. A dose-response study was conducted to identify the most effective option for cut-leaved gipsywort control using existing crop protection products. The study evaluated percentage reductions in dry biomass and canopy cover. The results suggest that bentazon, as the only nonsystemic herbicide, was least effective in controlling cut-leaved gipsywort with an effective dose (ED90) estimated at 1.5 × of the recommended labeled rate, or 2,205 g ai ha−1. Plants exposed to dicamba exhibited no regrowth at the field-use rate. Cut-leaved gipsywort may regrow when foramsulfuron, mesotrione, nicosulfuron, and tembotrione are applied at the recommended field-use rates. Halauxifen-methyl and imazamox were most effective, with estimated ED90 values of 0.21 × (0.85 g ai ha−1) and 0.4 × (16.14 g ai ha−1), respectively, which are lower than the recommended labeled rates. Although reduced rates are not recommended because good herbicide stewardship practices should aim to prevent the development of herbicide resistance, with both halauxifen-methyl and imazamox, cut-leaved gipsywort exhibited no regrowth when one-half of the recommended labeled rates were applied.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8d4bdca6-5a33-4cf9-945e-c78553f38f2a', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Genome Editing in Rice: Recent Advances, Challenges, and Future Implications', 'Mishra R, Joshi RK, Zhao K', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01361', 'https://doi.org/10.3389/fpls.2018.01361', 'https://europepmc.org/articles/PMC6156261?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Rice (Oryza sativa L.) is the major food source for more than three billion people of the world. In the last few decades, the classical, mutational, and molecular breeding approaches have brought about tremendous increase in rice productivity with the development of novel rice varieties. However, stagnation in rice yield has been reported in recent decade owing to several factors including the emergence of pests and phyto pathogens, climate change, and other environmental issues posing great threat to global food security. There is an urgent need to produce more rice and associated cereals to satisfy the mammoth task of feeding a still growing population expected to reach 9.7 billion by 2050. Advances in genomics and emergence of multiple genome-editing technologies through use of engineered site-specific nucleases (SSNs) have revolutionized the field of plant science and agriculture. Among them, the CRISPR/Cas9 system is the most advanced and widely accepted because of its simplicity, robustness, and high efficiency. The availability of huge genomic resources together with a small genome size makes rice more suitable and feasible for genetic manipulation. As such, rice has been increasingly used to test the efficiency of different types of genome editing technologies to study the functions of various genes and demonstrate their potential in genetic improvement. Recently developed approaches including CRISPR/Cpf1 system and base editors have evolved as more efficient and accurate genome editing tools which might accelerate the pace of crop improvement. In the present review, we focus on the genome editing strategies for rice improvement, thereby highlighting the applications and advancements of CRISPR/Cas9 system. This review also sheds light on the role of CRISPR/Cpf1 and base editors in the field of genome editing highlighting major challenges and future implications of these tools in rice improvement.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b6bcd6d7-9f8a-44ec-9c8e-bc3e3081d2da', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Herbicide Resistance: Another Hot Agronomic Trait for Plant Genome Editing', 'Hussain A, Ding X, Alariqi M, Manghwar H, Hui F, Li Y, Cheng J, Wu C', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10040621', 'https://doi.org/10.3390/plants10040621', 'https://europepmc.org/articles/PMC8064318?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Weeds have continually interrupted crop plants since their domestication, leading to a greater yield loss compared to diseases and pests that necessitated the practice of weed control measures. The control of weeds is crucial to ensuring the availability of sufficient food for a rapidly increasing human population. Chemical weed control (herbicides) along with integrated weed management (IWM) practices can be the most effective and reliable method of weed management programs. The application of herbicides for weed control practices calls for the urgency to develop herbicide-resistant (HR) crops. Recently, genome editing tools, especially CRISPR-Cas9, have brought innovation in genome editing technology that opens up new possibilities to provide sustainable farming in modern agricultural industry. To date, several non-genetically modified (GM) HR crops have been developed through genome editing that can present a leading role to combat weed problems along with increasing crop productivity to meet increasing food demand around the world. Here, we present the chemical method of weed control, approaches for herbicide resistance development, and possible advantages and limitations of genome editing in herbicide resistance. We also discuss how genome editing would be effective in combating intensive weed problems and what would be the impact of genome-edited HR crops in agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('307ebc35-d646-4a97-8048-47cf3e286f35', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'High-Throughput UAV Image-Based Method Is More Precise Than Manual Rating of Herbicide Tolerance', 'Duddu HSN, Johnson EN, Willenborg CJ, Shirtliffe SJ', 2019, 'Plant phenomics (Washington, D.C.)', '10.34133/2019/6036453', 'https://doi.org/10.34133/2019/6036453', 'https://europepmc.org/articles/PMC7706330?pdf=render', NULL, NULL, 9, NULL, 'prairies', 4, 'cc by', 'The traditional visual rating system is labor-intensive, time-consuming, and prone to human error. Unmanned aerial vehicle (UAV) imagery-based vegetation indices (VI) have potential applications in high-throughput plant phenotyping. The study objective is to determine if UAV imagery provides accurate and consistent estimations of crop injury from herbicide application and its potential as an alternative to visual ratings. The study was conducted at the Kernen Crop Research Farm, University of Saskatchewan in 2016 and 2017. Fababean (Vicia faba L.) crop tolerance to nine herbicide tank mixtures was evaluated with 2 rates distributed in a randomized complete block design (RCBD) with 4 blocks. The trial was imaged using a multispectral camera with a ground sample distance (GSD) of 1.2 cm, one week after the treatment application. Visual ratings of growth reduction and physiological chlorosis were recorded simultaneously with imaging. The optimized soil-adjusted vegetation index (OSAVI) was calculated from the thresholded orthomosaics. The UAV-based vegetation index (OSAVI) produced more precise results compared to visual ratings for both years. The coefficient of variation (CV) of OSAVI was ~1% when compared to 18-43% for the visual ratings. Furthermore, Tukey''s honestly significance difference (HSD) test yielded a more precise mean separation for the UAV-based vegetation index than visual ratings. The significant correlations between OSAVI and the visual ratings from the study suggest that undesirable variability associated with visual assessments can be minimized with the UAV-based approach. UAV-based imagery methods had greater precision than the visual-based ratings for crop herbicide damage. These methods have the potential to replace visual ratings and aid in screening crops for herbicide tolerance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f0c5619b-de0e-42db-81c4-497d763267c7', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Honey Bee Exposure to Pesticides: A Four-Year Nationwide Study', 'Ostiguy N, Drummond FA, Aronstein K, Eitzer B, Ellis JD, Spivak M, Sheppard WS', 2019, 'Insects', '10.3390/insects10010013', 'https://doi.org/10.3390/insects10010013', 'https://europepmc.org/articles/PMC6359572?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Pollinators, including honey bees, are responsible for the successful reproduction of more than 87% of flowering plant species: they are thus vital to ecosystem health and agricultural services world-wide. To investigate honey bee exposure to pesticides, 168 pollen samples and 142 wax comb samples were collected from colonies within six stationary apiaries in six U.S. states. These samples were analyzed for evidence of pesticides. Samples were taken bi-weekly when each colony was active. Each apiary included thirty colonies, of which five randomly chosen colonies in each apiary were sampled for pollen. The pollen samples were separately pooled by apiary. There were a total of 714 detections in the collected pollen and 1008 detections in collected wax. A total of 91 different compounds were detected: of these, 79 different pesticides and metabolites were observed in the pollen and 56 were observed in the wax. In all years, insecticides were detected more frequently than were fungicides or herbicides: one third of the detected pesticides were found only in pollen. The mean (standard deviation (SD)) number of detections per pooled pollen sample varied by location from 1.1 (1.1) to 8.7 (2.1). Ten different modes of action were found across all four years and nine additional modes of action occurred in only one year. If synergy in toxicological response is a function of simultaneous occurrence of multiple distinct modes of action, then a high frequency of potential synergies was found in pollen and wax-comb samples. Because only pooled pollen samples were obtained from each apiary, and these from only five colonies per apiary per year, more data are needed to adequately evaluate the differences in pesticide exposure risk to honey bees among colonies in the same apiary and by year and location.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('16b59069-2fc4-4f7d-8af2-e95c97b63f0d', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Identities, concentrations, and sources of pesticide exposure in pollen collected by managed bees during blueberry pollination', 'Graham KK, Milbrath MO, Zhang Y, Soehnlen A, Baert N, McArt S, Isaacs R', 2021, 'Scientific reports', '10.1038/s41598-021-96249-z', 'https://doi.org/10.1038/s41598-021-96249-z', 'https://europepmc.org/articles/PMC8377133?pdf=render', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'Bees are critical for crop pollination, but there is limited information on levels and sources of pesticide exposure in commercial agriculture. We collected pollen from foraging honey bees and bumble bees returning to colonies placed in blooming blueberry fields with different management approaches (conventional, organic, unmanaged) and located across different landscape settings to determine how these factors affect pesticide exposure. We also identified the pollen and analyzed whether pesticide exposure was correlated with corbicular load composition. Across 188 samples collected in 2 years, we detected 80 of the 259 pesticide active ingredients (AIs) screened for using a modified QuEChERS method. Detections included 28 fungicides, 26 insecticides, and 21 herbicides. All samples contained pesticides (mean = 22 AIs per pollen sample), with pollen collected from bees on conventional fields having significantly higher average concentrations (2019 mean = 882.0 ppb) than those on unmanaged fields (2019 mean = 279.6 ppb). Pollen collected by honey bees had more AIs than pollen collected by bumble bees (mean = 35 vs. 19 AIs detected at each farm, respectively), whereas samples from bumble bees had higher average concentrations, likely reflecting differences in foraging behavior. Blueberry pollen was more common in pollen samples collected by bumble bees (25.9% per sample) than honey bees (1.8%), though pesticide concentrations were only correlated with blueberry pollen for honey bees. Pollen collected at farms with more blueberry in the surrounding landscape had higher pesticide concentrations, mostly AIs applied for control of blueberry pathogens and pests during bloom. However, for honey bees, the majority of AIs detected at each farm are not registered for use on blueberry at any time (55.2% of AIs detected), including several highly toxic insecticides. These AIs therefore came from outside the fields and farms they are expected to pollinate. For bumble bees, the majority of AIs detected in their pollen are registered for use on blueberry during bloom (56.9% of AIs detected), though far fewer AIs were sprayed at the focal farm (16.7%). Our results highlight the need for integrated farm and landscape-scale stewardship of pesticides to reduce exposure to pollinators during crop pollination.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e0dd928f-66e2-4c2c-bd85-3988849470d0', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Metal-Organic Frameworks in Agriculture', 'Rojas S, Rodríguez-Diéguez A, Horcajada P', 2022, 'ACS applied materials & interfaces', '10.1021/acsami.2c00615', 'https://doi.org/10.1021/acsami.2c00615', 'https://europepmc.org/articles/PMC9026272?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Agrochemicals, which are crucial to meet the world food qualitative and quantitative demand, are compounds used to kill pests (insects, fungi, rodents, or unwanted plants). Regrettably, there are some important issues associated with their widespread and extensive use (e.g., contamination, bioaccumulation, and development of pest resistance); thus, a reduced and more controlled use of agrochemicals and thorough detection in food, water, soil, and fields are necessary. In this regard, the development of new functional materials for the efficient application, detection, and removal of agrochemicals is a priority. Metal-organic frameworks (MOFs) with exceptional sorptive, recognition capabilities, and catalytical properties have very recently shown their potential in agriculture. This Review emphasizes the recent advances in the use of MOFs in agriculture through three main views: environmental remediation, controlled agrochemical release, and detection of agrochemicals.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('51597408-b275-4874-863f-a31ab58bb471', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Interaction of Cultural, Biological, and Varietal Controls for Management of Stalk Borers in Louisiana Sugarcane', 'Reagan TE, Mulcahy MM', 2019, 'Insects', '10.3390/insects10090305', 'https://doi.org/10.3390/insects10090305', 'https://europepmc.org/articles/PMC6780493?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Diatraea saccharalis F is considered the most important pest of sugarcane in the United States. This article focuses on the history of pest management as it relates to the control of this stem borer in Louisiana sugarcane, and how control practices have become more in tune with integrated pest management paradigms. Various pest management strategies are employed against D. saccharalis and the interactions between each of these provide farmers with the tools needed to curb damaging infestations. However, the invasion of the Mexican rice borer, Eoreuma loftini (Dyar), and other confounding environmental factors have presented farmers, consultants, and researchers with new pest management challenges. We address these challenges and provide an overview of ongoing developments, particularly in the Louisiana sugarcane pest management program.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3089dca9-33da-4b3b-8282-1de2c2bfbbf9', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'New weed control strategies in maize considering narrow crop rotations with maize, greater ALSresistance in common weeds and application restrictions with regard to active substance', 'Ewert, Katrin, Schröder, Gerhard, Meinlschmidt, Ewa, Bergmann, Elke', 2014, 'Julius-Kühn-Archiv', '10.5073/jka.2014.443.080', 'https://doi.org/10.5073/jka.2014.443.080', 'http://pub.jki.bund.de/index.php/JKA/article/view/2926/3125', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Many herbicides with different HRAC-groups are available for weed control in maize. Because of narrow maize crop rotation summer weeds and warmth loving weeds are encouraged. On the other hand the new confirmed cases of an ALS target site resistance in the weed species Echinochloa crus-galli and Amaranthus retroflexus in Brandenburg, Stellaria media in Saxony and Matricaria recutita and Tripleurospermum perforatum in Brandenburg and Thuringia, warn that in the future the sulfonylureas must be used only according to the management of herbicide resistance. In this way the selection of resistant weed biotypes will be prevented. Moreover in protected water areas it may be a requirement to reduce and to substitute the input of some active substances, for example terbuthylazine and bentazon. The control of E. crus-galli and P. convolvulus with non-sulfonylurea or/and non-terbuthylazine herbicides according to management of herbicide resistance will be discussed.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('159f7455-1b29-4939-957b-9e2cc88b6142', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Novel CRISPR-Cas Systems: An Updated Review of the Current Achievements, Applications, and Future Research Perspectives', 'Nidhi S, Anand U, Oleksak P, Tripathi P, Lal JA, Thomas G, Kuca K, Tripathi V', 2021, 'International journal of molecular sciences', '10.3390/ijms22073327', 'https://doi.org/10.3390/ijms22073327', 'https://europepmc.org/articles/PMC8036902?pdf=render', NULL, NULL, 42, NULL, 'other', 1, 'cc by', 'According to Darwin''s theory, endless evolution leads to a revolution. One such example is the Clustered Regularly Interspaced Palindromic Repeats (CRISPR)-Cas system, an adaptive immunity system in most archaea and many bacteria. Gene editing technology possesses a crucial potential to dramatically impact miscellaneous areas of life, and CRISPR-Cas represents the most suitable strategy. The system has ignited a revolution in the field of genetic engineering. The ease, precision, affordability of this system is akin to a Midas touch for researchers editing genomes. Undoubtedly, the applications of this system are endless. The CRISPR-Cas system is extensively employed in the treatment of infectious and genetic diseases, in metabolic disorders, in curing cancer, in developing sustainable methods for fuel production and chemicals, in improving the quality and quantity of food crops, and thus in catering to global food demands. Future applications of CRISPR-Cas will provide benefits for everyone and will save countless lives. The technology is evolving rapidly; therefore, an overview of continuous improvement is important. In this review, we aim to elucidate the current state of the CRISPR-Cas revolution in a tailor-made format from its discovery to exciting breakthroughs at the application level and further upcoming trends related to opportunities and challenges including ethical concerns.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6aa202a9-c65a-4db4-bb6f-f6f7595f0dbd', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Plant growth promoting rhizobia: challenges and opportunities', 'Gopalakrishnan S, Sathya A, Vijayabharathi R, Varshney RK, Gowda CL, Krishnamurthy L', 2015, '3 Biotech', '10.1007/s13205-014-0241-x', 'https://doi.org/10.1007/s13205-014-0241-x', 'https://europepmc.org/articles/PMC4522733?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Modern agriculture faces challenges, such as loss of soil fertility, fluctuating climatic factors and increasing pathogen and pest attacks. Sustainability and environmental safety of agricultural production relies on eco-friendly approaches like biofertilizers, biopesticides and crop residue return. The multiplicity of beneficial effects of microbial inoculants, particularly plant growth promoters (PGP), emphasizes the need for further strengthening the research and their use in modern agriculture. PGP inhabit the rhizosphere for nutrients from plant root exudates. By reaction, they help in (1) increased plant growth through soil nutrient enrichment by nitrogen fixation, phosphate solubilization, siderophore production and phytohormones production (2) increased plant protection by influencing cellulase, protease, lipase and β-1,3 glucanase productions and enhance plant defense by triggering induced systemic resistance through lipopolysaccharides, flagella, homoserine lactones, acetoin and butanediol against pests and pathogens. In addition, the PGP microbes contain useful variation for tolerating abiotic stresses like extremes of temperature, pH, salinity and drought; heavy metal and pesticide pollution. Seeking such tolerant PGP microbes is expected to offer enhanced plant growth and yield even under a combination of stresses. This review summarizes the PGP related research and its benefits, and highlights the benefits of PGP rhizobia belonging to the family Rhizobiaceae, Phyllobacteriaceae and Bradyrhizobiaceae.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9aea6d7-0c26-4f35-a826-a41764c036f3', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Potential applications of plant probiotic microorganisms in agriculture and forestry', 'de Souza Vandenberghe LP, Garcia LMB, Rodrigues C, Camara MC, de Melo Pereira GV, de Oliveira J, Soccol CR', 2017, 'AIMS microbiology', '10.3934/microbiol.2017.3.629', 'https://doi.org/10.3934/microbiol.2017.3.629', 'https://europepmc.org/articles/PMC6604986?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Agriculture producers, pushed by the need for high productivity, have stimulated the intensive use of pesticides and fertilizers. Unfortunately, negative effects on water, soil, and human and animal health have appeared as a consequence of this indiscriminate practice. Plant probiotic microorganisms (PPM), also known as bioprotectants, biocontrollers, biofertilizers, or biostimulants, are beneficial microorganisms that offer a promising alternative and reduce health and environmental problems. These microorganisms are involved in either a symbiotic or free-living association with plants and act in different ways, sometimes with specific functions, to achieve satisfactory plant development. This review deals with PPM presentation and their description and function in different applications. PPM includes the plant growth promoters (PGP) group, which contain bacteria and fungi that stimulate plant growth through different mechanisms. Soil microflora mediate many biogeochemical processes. The use of plant probiotics as an alternative soil fertilization source has been the focus of several studies; their use in agriculture improves nutrient supply and conserves field management and causes no adverse effects. The species related to organic matter and pollutant biodegradation in soil and abiotic stress tolerance are then presented. As an important way to understand not only the ecological role of PPM and their interaction with plants but also the biotechnological application of these cultures to crop management, two main approaches are elucidated: the culture-dependent approach where the microorganisms contained in the plant material are isolated by culturing and are identified by a combination of phenotypic and molecular methods; and the culture-independent approach where microorganisms are detected without cultivating them, based on extraction and analyses of DNA. These methods combine to give a thorough knowledge of the microbiology of the studied environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c7a8d270-fc85-455f-b7fa-e8f977cd3e58', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Mechanisms and Genetic Drivers of Resistance of Insect Pests to Insecticides and Approaches to Its Control', 'Al Naggar Y, Fahmy NM, Alkhaibari AM, Al-Akeel RK, Alharbi HM, Mohamed A, Eleftherianos I, El-Seedi HR', 2025, 'Toxics', '10.3390/toxics13080681', 'https://doi.org/10.3390/toxics13080681', 'https://europepmc.org/articles/PMC12390148?pdf=render', NULL, NULL, 45, NULL, 'other', 1, 'cc by', 'The escalating challenge of resistance to insecticides among agricultural and public health pests poses a significant threat to global food security and vector-borne disease control. This review synthesizes current understanding of the molecular mechanisms underpinning resistance, including well-characterized pathways such as target-site mutations affecting nicotinic acetylcholine receptors (nAChRs), acetylcholinesterase (AChE), voltage-gated sodium channels (VGSCs), and γ-aminobutyric acid (GABA) receptors, and metabolic detoxification mediated by cytochrome P450 monooxygenases (CYPs), esterases, and glutathione S-transferases (GSTs). Emerging resistance mechanisms are also explored, including protein sequestration by odorant-binding proteins and post-transcriptional regulation via non-coding RNAs, such as microRNAs (miRNAs) and long non-coding RNAs (lncRNAs). Focused case studies on Aedes aegypti and Spodoptera frugiperda illustrate the complex interplay of genetic and biochemical adaptations driving resistance. In Ae. aegypti, voltage-gated sodium channel (VGSCs) mutations (V410L, V1016I, F1534C) combined with metabolic enzyme amplification confer resistance to pyrethroids, accompanied by notable fitness costs and ecological impacts on vector populations. In S. frugiperda, multiple resistance mechanisms, including overexpression of cytochrome P450 genes (e.g., CYP6AE43, CYP321A8), target-site mutations in ryanodine receptors (e.g., I4790K), and behavioral avoidance, have rapidly evolved across global populations, undermining the efficacy of diamide, organophosphate, and pyrethroid insecticides. The review further evaluates integrated pest management (IPM) strategies, emphasizing the role of biopesticides, biological control agents, including entomopathogenic fungi and parasitoids, and molecular diagnostics for resistance management. Taken together, this analysis underscores the urgent need for continuous molecular surveillance, the development of resistance-breaking technologies, and the implementation of sustainable, multifaceted interventions to safeguard the long-term efficacy of insecticides in both agricultural and public health contexts.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dd054e7d-ae01-461f-900a-ee3c504df137', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Rhizosphere Bacteria in Plant Growth Promotion, Biocontrol, and Bioremediation of Contaminated Sites: A Comprehensive Review of Effects and Mechanisms', 'Saeed Q, Xiukang W, Haider FU, Kučerik J, Mumtaz MZ, Holatko J, Naseem M, Kintl A', 2021, 'International journal of molecular sciences', '10.3390/ijms221910529', 'https://doi.org/10.3390/ijms221910529', 'https://europepmc.org/articles/PMC8509026?pdf=render', NULL, NULL, 41, NULL, 'other', 1, 'cc by', 'Agriculture in the 21st century is facing multiple challenges, such as those related to soil fertility, climatic fluctuations, environmental degradation, urbanization, and the increase in food demand for the increasing world population. In the meanwhile, the scientific community is facing key challenges in increasing crop production from the existing land base. In this regard, traditional farming has witnessed enhanced per acre crop yields due to irregular and injudicious use of agrochemicals, including pesticides and synthetic fertilizers, but at a substantial environmental cost. Another major concern in modern agriculture is that crop pests are developing pesticide resistance. Therefore, the future of sustainable crop production requires the use of alternative strategies that can enhance crop yields in an environmentally sound manner. The application of rhizobacteria, specifically, plant growth-promoting rhizobacteria (PGPR), as an alternative to chemical pesticides has gained much attention from the scientific community. These rhizobacteria harbor a number of mechanisms through which they promote plant growth, control plant pests, and induce resistance to various abiotic stresses. This review presents a comprehensive overview of the mechanisms of rhizobacteria involved in plant growth promotion, biocontrol of pests, and bioremediation of contaminated soils. It also focuses on the effects of PGPR inoculation on plant growth survival under environmental stress. Furthermore, the pros and cons of rhizobacterial application along with future directions for the sustainable use of rhizobacteria in agriculture are discussed in depth.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('457d538f-1c79-48b0-ba64-5905dcfff82d', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Rhizosphere Microbiome Modulators: Contributions of Nitrogen Fixing Bacteria towards Sustainable Agriculture', 'Igiehon NO, Babalola OO', 2018, 'International journal of environmental research and public health', '10.3390/ijerph15040574', 'https://doi.org/10.3390/ijerph15040574', 'https://europepmc.org/articles/PMC5923616?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Rhizosphere microbiome which has been shown to enhance plant growth and yield are modulated or influenced by a few environmental factors such as soil type, plant cultivar, climate change and anthropogenic activities. In particular, anthropogenic activity, such as the use of nitrogen-based chemical fertilizers, is associated with environmental destruction and this calls for a more ecofriendly strategy to increase nitrogen levels in agricultural land. This feat is attainable by harnessing nitrogen-fixing endophytic and free-living rhizobacteria. Rhizobium, Pseudomonas, Azospirillum and Bacillus, have been found to have positive impacts on crops by enhancing both above and belowground biomass and could therefore play positive roles in achieving sustainable agriculture outcomes. Thus, it is necessary to study this rhizosphere microbiome with more sophisticated culture-independent techniques such as next generation sequencing (NGS) with the prospect of discovering novel bacteria with plant growth promoting traits. This review is therefore aimed at discussing factors that can modulate rhizosphere microbiome with focus on the contributions of nitrogen fixing bacteria towards sustainable agricultural development and the techniques that can be used for their study.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d483c5ea-84b5-4fbc-80de-374e20043eca', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Shoot and Root Traits Contribute to Drought Resistance in Recombinant Inbred Lines of MD 23-24 × SEA 5 of Common Bean', 'Polania J, Rao IM, Cajiao C, Grajales M, Rivera M, Velasquez F, Raatz B, Beebe SE', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.00296', 'https://doi.org/10.3389/fpls.2017.00296', 'https://europepmc.org/articles/PMC5334335?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Drought is the major abiotic stress factor limiting yield of common bean (Phaseolus vulgaris L.) in smallholder systems in Latin America and eastern and southern Africa; where it is a main source of protein in the daily diet. Identification of shoot and root traits associated with drought resistance contributes to improving the process of designing bean genotypes adapted to drought. Field and greenhouse studies were conducted at the International Center for Tropical Agriculture (CIAT), Palmira, Colombia to determine the relationship between grain yield and different shoot and root traits using a recombinant inbred lines (RILs) population (MD23-24 × SEA 5) of common bean. The main objectives of this study were to identify: (i) specific shoot and root morpho-physiological traits that contribute to improved resistance to drought and that could be useful as selection criteria in breeding beans for drought resistance; and (ii) superior genotypes with desirable shoot and root traits that could serve as parents in breeding programs that are aimed at improving drought resistance. A set of 121 bean genotypes (111 RILs, 2 parents, 8 checks) belonging to the Mesoamerican gene pool and one cowpea variety were evaluated under field conditions with two levels of water supply (irrigated and rainfed) over three seasons. To complement field studies, a greenhouse study was conducted using plastic cylinders with soil inserted into PVC pipes, to determine the relationship between grain yield obtained under field conditions with different root traits measured under greenhouse conditions. Resistance to drought stress was positively associated with a deeper and vigorous root system, better shoot growth, and superior mobilization of photosynthates to pod and seed production. The drought resistant lines differed in their root characteristics, some of them with a vigorous and deeper root system while others with a moderate to shallow root system. Among the shoot traits measured, pod harvest index, and seed number per area could serve as useful selection criteria for assessing sink strength and for genetic improvement of drought resistance in common bean.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b9c8b210-e61a-4f53-86da-b09c1d604ad9', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'The natural herbicide rhein targets photosystem I', 'Twitty A, Barnes H, Levy N, Mizrahi Y, Geva Y, Phillip Y, Dayan FE', 2024, 'Scientific reports', '10.1038/s41598-024-83891-6', 'https://doi.org/10.1038/s41598-024-83891-6', 'https://europepmc.org/articles/PMC11685900?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'The natural anthraquinone rhein has been identified as a novel herbicide with a potentially new mode of action using a generative AI system for functional molecules discovery. Its herbicidal activity was light-dependent and resulted in rapid burndown symptoms on leaves of treated plants. Rhein interferes with photosynthesis by acting as an electron diverter at the level of photosystem I (PSI). The redox potential of rhein suggests that it accepts electrons between P700 and NADP+ of PSI. This is consistent with the redox potential of rhein that enables it to accept electrons from flavoproteins. Ferredoxin-NAPD+ reductase is a flavoprotein with a redox potential near that of rhein. Thus, it is currently hypothesized that rhein acts as an electron acceptor at or near the PSI Ferredoxin-NAPD+ reductase to form a radical and generate reactive oxygen species that drive the light-dependent herbicidal effect which is observed in treated plants from greenhouse trials.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('181d00d2-5e1c-43ba-8295-8a844c81e5f2', 'e6df4d80-729a-447a-859d-72653a560793', 'Improved Methods for Treatment of Phytopathogenic Biofilms: Metallic Compounds as Anti-Bacterial Coatings and Fungicide Tank-Mix Partners', 'Harding M, Nadworny P, Buziak B, Omar A, Daniels G, Feng J', 2019, 'Molecules (Basel, Switzerland)', '10.3390/molecules24122312', 'https://doi.org/10.3390/molecules24122312', 'https://europepmc.org/articles/PMC6630349?pdf=render', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc by', 'Fungi and bacteria cause disease issues in cultivated plants world-wide. In most cases, the fungi and bacteria colonize plant tissues as biofilms, which can be very challenging to destroy or eradicate. In this experiment, we employed a novel (biofilm) approach to crop disease management by evaluating the efficacies of six fungicides, and four silver-based compounds, versus biofilms formed by fungi and bacteria, respectively. The aim was to identify combinations of fungicides and metallic cations that showed potential to improve the control of white mold (WM), caused by the ascomycete fungus Sclerotinia sclerotiorum, and to evaluate novel high valency silver compounds as seed coatings to prevent biofilm formation of four bacterial blight pathogens on dry bean seeds. Our results confirmed that mature fungal biofilms were recalcitrant to inactivation by fungicides. When metallic cations were added to the fungicides, their efficacies were improved. Some improvements were statistically significant, with one combination (fluazinam + Cu2+) showing a synergistic effect. Additionally, coatings with silver compounds could reduce bacterial blight biofilms on dry bean seeds and oxysilver nitrate was the most potent inhibitor of bacterial blight.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dac5e669-dcda-41d6-8632-ce184314409c', '2321ca3d-e2b9-4596-a337-9e4e95977f35', 'Unraveling the Role of P450 Reductase in Herbicide Metabolic Resistance Mechanism', 'Carlos Alberto Gonsiorkiewicz Rigon, Satoshi Iwakami, Todd A. Gaines, Franck E. Dayan', 2025, 'Plant Direct', '10.1002/pld3.70102', 'https://doi.org/10.1002/pld3.70102', 'https://doi.org/10.1002/pld3.70102', NULL, NULL, 39, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'ABSTRACT Plants require cytochrome P450 reductase (CPR) to supply two electrons for cytochrome P450 monooxygenase enzymes (P450) to react with an organic substrate. The transfer of electrons to the P450 active site in the P450 catalytic site relies on a robust and intricate CPR:P450 complex in the endoplasmic reticulum membrane. Transgenic Arabidopsis plants carrying CYP81A12 from Echinochloa phyllopogon, which metabolizes a broad spectrum of herbicides, were crossed with CPR knockout atr1 or atr2 mutant lines. Homozygous gene knockout was confirmed using PCR, and gene copy number of CYP81A12 was determined using ddPCR. Arabidopsis lines expressing CYP81A12 in combination with atr1 or atr2 knockout were used for herbicide dose–response and metabolism studies. Knocking out ATR1 in transgenic Arabidopsis CYP81A12 significantly reduced herbicide resistance. Transgenic mutant plants (CYP81A12 atr1‐b) had a 3.6‐, 5.6‐, 6.8‐, and at least 26‐fold reduction in resistance to mesotrione; 2,4‐D; penoxsulam; and chlorsulfuron, respectively, in the dose–response assay. Knockouts of ATR2 also decreased herbicide resistance but to a lower magnitude than ATR1. These results corroborate ½ MS medium assay, and herbicide resistance reduction was observed for additional herbicides including bensulfuron‐methyl, propoxycarbazone‐sodium, and bentazon. Our findings highlight the importance of CPRs in metabolic herbicide resistance in plants by identifying that a single CPR knockout can reverse herbicide resistance. The different CPRs found in weeds have potential as target genes to manage metabolic herbicide resistance evolution. We further provide an in‐depth exploration of the evolutionary implications in weed management arising from the results.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b61fa87d-8abc-4b27-9614-64b5e9a98e97', 'e6df4d80-729a-447a-859d-72653a560793', 'A Method Scope Extension for the Simultaneous Analysis of POPs, Current-Use and Banned Pesticides, Rodenticides, and Pharmaceuticals in Liver. Application to Food Safety and Biomonitoring', 'Rial-Berriel C, Acosta-Dacal A, Zumbado M, Henríquez-Hernández LA, Rodríguez-Hernández Á, Macías-Montes A, Boada LD, Travieso-Aja MDM', 2021, 'Toxics', '10.3390/toxics9100238', 'https://doi.org/10.3390/toxics9100238', 'https://europepmc.org/articles/PMC8539179?pdf=render', NULL, NULL, 62, NULL, 'other', 1, 'cc by', 'The screening of hundreds of substances belonging to multiple chemical classes in liver is required in areas such as food safety or biomonitoring. We adapted a previous QuEChERS-based method in blood to the liver matrix and applied to these fields of study. The validation of the method allowed the inclusion of 351 contaminants, 80% with a LOQ < 2 ng/g. In the analysis of 42 consumer liver samples, we detected trace levels of 29 different contaminants. The most frequent and concentrated was 4,4''-DDE. POPs accounted for 66% of the compounds detected. In no case was the MRL reached for any of the contaminants detected. We also applied the method to 151 livers of wild birds to perform a biomonitoring pilot study in the Canary Islands. We detected 52 contaminants in 15 bird species. These were also mostly POPs, although high frequencies and concentrations of anticoagulant rodenticides (AR) and some other agricultural pesticides also stand out. POPs and AR contamination levels were significantly higher in terrestrial birds, raptors and particularly in nocturnal birds. Pesticide contamination levels were also higher in terrestrial birds, as well as in non-raptors and diurnal birds. The validated method is simple, robust, and sensitive and performs well in a variety of practical scenarios, where it can be carried out relatively quickly and inexpensively.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37d1f3a9-11a2-444f-816c-8f9ce0cc32c5', 'e6df4d80-729a-447a-859d-72653a560793', 'An Effective Hybrid Fungicide Containing Tea Tree Oil and Difenoconazole for Grape Powdery Mildew Management', 'Moshe Reuveni, Cristobal J. Arroyo, Shmuel Ovadia', 2023, 'Agriculture', '10.3390/agriculture13050979', 'https://doi.org/10.3390/agriculture13050979', 'https://www.mdpi.com/2077-0472/13/5/979', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Grape powdery mildew caused by Erysiphe necator (Schw.) Burr. is a destructive disease in vineyards. Synthetic fungicides are the main tool to combat this disease. The search for new alternatives to reduce pesticide usage and tactical approaches for resistance management encouraged us to develop the novel strategy that we report here. We evaluated the efficacy of a new premixed hybrid fungicide containing the demethylation inhibitor (DMI) difenoconazole and essential tea tree oil (TTO), derived from the Melaleuca alternifolia plant, against grape powdery mildew in seven field trials and two large-scale demonstration trials conducted in two different regions in the world, including Chile and Israel. Foliar sprays of difenoconazole-TTO were applied as a preventive treatment in field trials at 40–80 up to 80–160 gr/ha active ingredient, and they were highly effective in controlling powdery mildew on the fruit clusters of both wine and table grapes in experimental and large-scale demonstration trials and provided up to 99% efficacy in disease incidence and severity compared with the untreated control. Difenoconazole-TTO was as or more effective than other DMI fungicides, including difenoconazole, a pre-mixed fungicide boscalid-pyraclostrobin, or treatments that included various fungicides applied in rotation or mixtures of fungicides. The results suggest that a combination of difenoconazole-TTO with a reduced synthetic chemical load can be included in powdery mildew control programs for grapevine as a strategic approach in fungicide resistance management in vineyards.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c906cd02-55f1-4cd0-80e4-6a5a8cab4270', 'e6df4d80-729a-447a-859d-72653a560793', 'Assessment of Alternaria Toxins and Pesticides in Organic and Conventional Tomato Products: Insights into Contamination Patterns and Food Safety Implications', 'Pacini T, D''Amore T, Sdogati S, Verdini E, Bibi R, Caporali A, Cristofani E, Maresca C', 2024, 'Toxins', '10.3390/toxins17010012', 'https://doi.org/10.3390/toxins17010012', 'https://europepmc.org/articles/PMC11769159?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Alternaria toxins (ATs) are a group of toxins produced by Alternaria fungi that frequently contaminate tomatoes and tomato products. Recently, the European Food Safety Authority evaluated ATs for their genotoxic and carcinogenic properties. Alternaria infestation is often controlled using ad hoc treatment strategies (fungicides). In this study, two analytical methods were developed, validated and applied for the determination of five ATs and 195 pesticides in tomato products collected from the Italian market. Two distinct groups, organic (n = 20) and conventional (n = 20) Italian tomato sauces, were characterized in depth. Tenuazonic acid, alternariol and alternariol monomethyl ether were found up to 517, 27 and 7.1 µg/kg, respectively, while pesticides were detected between 0.0026 and 0.0421 mg/kg in conventional products, and, interestingly, up to 0.0130 mg/kg in organic products. No correlation emerged between the detected levels of ATs and pesticides and the type of tomato cultivation, but the probability of pesticide contamination in conventional products was eight times higher than in organics. Some considerations about exposure assessment and risk characterization for ATs were also proposed in the overall population and in more sensitive and/or exposed subgroups, underlining the need for new focused toxicological and monitoring studies to establish reliable reference values. Moreover, these data highlight that fungicide treatments may not protect tomatoes from ATs contamination, although it may remove fungi infestation. As organic product consumption is increasing, it is important to lay down dedicated regulations for maximum permitted levels to ensure the food safety of these products that are often perceived by consumers as a healthier and environmentally friendlier choice.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3f4f6825-87e2-4ba4-89ff-2ed9eecde4ea', 'e6df4d80-729a-447a-859d-72653a560793', 'Bacterial Endophyte Community Dynamics in Apple (Malus domestica Borkh.) Germplasm and Their Evaluation for Scab Management Strategies', 'Padder SA, Mansoor S, Bhat SA, Baba TR, Rather RA, Wani SM, Popescu SM, Sofi S', 2021, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof7110923', 'https://doi.org/10.3390/jof7110923', 'https://europepmc.org/articles/PMC8623955?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'The large genetic evolution due to the sexual reproduction-mediated gene assortments and propensities has made Venturia inaequalis (causing apple scab) unique with respect to its management strategies. The resistance in apple germplasm against the scab, being controlled for by more than fifteen genes, has limited gene alteration-based investigations. Therefore, a biological approach of bacterial endophyte community dynamics was envisioned across the apple germplasm in context to the fungistatic behavior against V. inaequalis. A total of 155 colonies of bacterial endophytes were isolated from various plant parts of the apple, comprising 19 varieties, and after screening for antifungal behavior followed by morphological, ARDRA, and sequence analysis, a total of 71 isolates were selected for this study. The alpha diversity indices were seen to fluctuate greatly among the isolation samples in context to microflora with antifungal behavior. As all the isolates were screened for the presence of various metabolites and some relevant genes that directly or indirectly influence the fungistatic behavior of the isolated microflora, a huge variation among the isolated microflora was observed. The outstanding isolates showing highest percentage growth inhibition of V. inaequalis were exploited to raise a bio-formulation, which was tested against the scab prevalence in eight apple varieties under controlled growth conditions. The formulation at all the concentrations caused considerable reductions in both the disease severity and disease incidence in all the tested apple varieties. Red Delicious being most important cultivar of the northwestern Himalayas was further investigated for its biochemical behavior in formulation and the investigation revealed different levels of enzyme production, chlorophyll, and sugars against the non-inoculated control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.874925+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('346095f0-7a50-41e3-8559-47ac4299d45f', 'e6df4d80-729a-447a-859d-72653a560793', 'Comprehensive Review on Monitoring, Behavior, and Impact of Pesticide Residues during Beer-Making', 'Pérez-Lucas G, Navarro G, Navarro S', 2023, 'Journal of agricultural and food chemistry', '10.1021/acs.jafc.2c07830', 'https://doi.org/10.1021/acs.jafc.2c07830', 'https://europepmc.org/articles/PMC9896562?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'This paper reviews the impact of beer-making stages (malting, mashing, boiling, and fermentation) on the behavior of pesticide residues. The large use of pesticides on barley and hop could cause the occurrence of their residues in beer. The foremost factors influencing the stability of residues (pH, temperature, and water content) and the physical-chemical properties of pesticides (octanol-water partition coefficient, vapor pressure, and water solubility) are essential to know their final fate. Most pesticides show a decrease in the unhopped wort because they are adsorbed onto the spent grains after mashing. In addition, their concentrations decrease during boiling and fermentation. Generally, maltsters should dedicate particular attention to the residues of hydrophobic pesticides because they can remain on the malt. Contrarily, brewers should control residues of hydrophilic pesticides because they can be carried over into young beer, disturbing the quality and organoleptic properties (flavor, aroma, taste, or color) of the beer.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('180ebff6-dadb-4c02-abc1-1cac3e183988', 'e6df4d80-729a-447a-859d-72653a560793', 'Development of novel pesticides in the 21st century', 'Umetsu N, Shirai Y', 2020, 'Journal of pesticide science', '10.1584/jpestics.d20-201', 'https://doi.org/10.1584/jpestics.d20-201', 'https://europepmc.org/articles/PMC7581488?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by-nc-nd', 'General trends and strategies for novel pesticides are summarized. Global pesticide sales and pesticide discovery research are also briefly reviewed. At least 105 chemical pesticides have been launched during the past decade or are under development: 43 fungicides, 34 insecticides/acaricides, 6 nematicides, 21 herbicides, and 1 herbicide safener. Most of them are safe to humans and environmentally friendly. The most developed fungicides are SDHI (succinate dehydrogenase inhibitors), DMI (demethylation inhibitors), QoI (quinone outside inhibitors), and QiI (quinone inside inhibitors). Due to the development of resistance to fungicides with existing modes of action, many fungicides possessing various novel modes of action have been launched or are under development. The trend of insecticide development is changing from organophosphorus, carbamate, and synthetic pyrethroids to nicotinic and diamide insecticides. During the past decade, compounds possessing a variety of novel modes of action have also been launched or are under development. Flupyradifurone and flupyrimin, exhibiting extremely low honeybee toxicity, have been developed and subjected to practical use. Herbicides possessing varied modes of action, such as acetolactate synthase, p-hydroxyphenylpyruvate dioxygenase, protoporphyrinogen oxidase, and very-long-chain fatty acid elongase inhibition, have been developed, but no herbicides possessing a novel mode action have commercialized in nearly 30 years. It is of interest that cyclopyrimorate, which was recently launched, and tetflupyrolimet, which is under development, have novel modes action: homogentisate solanesyltransferase (HST) and dihydroorotate dehydrogenase (DHODH) inhibition, respectively. The development of useful acaricides and nematicides is also progressing. Some natural product origin pesticides are getting attention.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5fbd55af-3168-4807-a6f8-023bd5634c1f', 'e6df4d80-729a-447a-859d-72653a560793', 'Diverse role, structural trends, and applications of fluorinated sulphonamide compounds in agrochemical and pharmaceutical fields', 'Chaudhari SB, Kumar A, Mankar VH, Banerjee S, Kumar D, Mubarak NM, Dehghani MH', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e32434', 'https://doi.org/10.1016/j.heliyon.2024.e32434', 'https://europepmc.org/articles/PMC11226812?pdf=render', NULL, NULL, 48, NULL, 'other', 1, 'cc by-nc-nd', 'Our knowledge of fluorine''s unique and complex properties has significantly increased over the past 20 years. Consequently, more sophisticated and innovative techniques have emerged to incorporate this feature into the design of potential drug candidates. In recent years, researchers have become interested in synthesizing fluoro-sulphonamide compounds to discover new chemical entities with distinct and unexpected physical, chemical, and biological characteristics. The fluorinated sulphonamide molecules have shown significant biomedical importance. Their potential is not limited to biomedical applications but also includes crop protection. The discovery of novel fluorine and Sulfur compounds has highlighted their importance in the chemical sector, particularly in the agrochemical and medicinal fields. Recently, several fluorinated sulphonamide derivatives have been developed and frequently used by agriculturalists to produce food for the growing global population. These molecules have also exhibited their potential in health by inhibiting various human diseases. In today''s world, it is crucial to have a steady supply of innovative pharmaceutical and agrochemical molecules that are highly effective, less harmful to the environment, and affordable. This review summarizes the available information on the activity of Fluorine and Sulphonamide compounds, which have proven active in pharmaceuticals and agrochemicals with excellent environmental and human health approaches. Moreover, it focuses on the current literature on the chemical structures, the application of fluorinated sulphonamide compounds against various pathological conditions, and their effectiveness in crop protection.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b30218f-9e0b-49a9-9be9-63f676a5f82f', 'e6df4d80-729a-447a-859d-72653a560793', 'New Insights in the Detection and Management of Anthracnose Diseases in Strawberries', 'Aljawasim BD, Samtani JB, Rahman M', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12213704', 'https://doi.org/10.3390/plants12213704', 'https://europepmc.org/articles/PMC10650140?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Anthracnose diseases, caused by Colletotrichum spp., are considered to be among the most destructive diseases that have a significant impact on the global production of strawberries. These diseases alone can cause up to 70% yield loss in North America. Colletotrichum spp. causes several disease symptoms on strawberry plants, including root, fruit, and crown rot, lesions on petioles and runners, and irregular black spots on the leaf. In many cases, a lower level of infection on foliage remains non-symptomatic (quiescent), posing a challenge to growers as these plants can be a significant source of inoculum for the fruiting field. Reliable detection methods for quiescent infection should play an important role in preventing infected plants'' entry into the production system or guiding growers to take appropriate preventative measures to control the disease. This review aims to examine both conventional and emerging approaches for detecting anthracnose disease in the early stages of the disease cycle, with a focus on newly emerging techniques such as remote sensing, especially using unmanned aerial vehicles (UAV) equipped with multispectral sensors. Further, we focused on the acutatum species complex, including the latest taxonomy, the complex life cycle, and the epidemiology of the disease. Additionally, we highlighted the extensive spectrum of management techniques against anthracnose diseases on strawberries and their challenges, with a special focus on new emerging sustainable management techniques that can be utilized in organic strawberry systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4aa2ea83-544f-4131-8555-8a66ad2c9978', 'e6df4d80-729a-447a-859d-72653a560793', 'Dual-loaded nano pesticide system based on industrial grade scaleable carrier materials with combinatory efficacy and improved safety', 'Li N, Cui J, Zhao J, An C, Wei Z, Shen Y, Sun C, Wang C', 2024, 'Journal of nanobiotechnology', '10.1186/s12951-024-02628-9', 'https://doi.org/10.1186/s12951-024-02628-9', 'https://europepmc.org/articles/PMC11188194?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Repeated and widespread use of single chemical pesticides raises concerns about efficiency and safety, developing multi-component synergistic pesticides provides a new route for efficient control of diseases. Most commercial compound formulations are open systems with non-adjustable released rates, resulting in a high frequency of applications. Meanwhile, although nano pesticide delivery systems constructed with different carrier materials have been extensively studied, realizing their actual scale-up production still has important practical significance due to the large-scale field application. In this study, a boscalid and pyraclostrobin dual-loaded nano pesticide system (BPDN) was constructed with industrial-grade carrier materials to facilitate the realization of large-scale production. The optimal industrial-scale preparation mechanism of BPDN was studied with surfactants as key factors. When agricultural emulsifier No.600 and polycarboxylate are used as the ratio of 1:2 in the preparation process, the BPDN has a spherical structure with an average size of 270 nm and exhibits superior physical stability. Compared with commercial formulation, BPDN maintains rate-stabilized release up to 5 times longer, exhibits better dispersion and spreading performance on foliar, has more than 20% higher deposition amounts, and reduces loss. A single application of BPDN could efficiently control tomato gray mold during the growing period of tomatoes due to extended duration and combinatory effectiveness, reducing two application times and labor costs. Toxicology tests on various objects systematically demonstrated that BPDN has improved safety for HepG2 cells, and nontarget organism earthworms. This research provides insight into creating safe, efficient, and environmentally friendly pesticide production to reduce manual operation times and labor costs. Accompanied by production strategies that can be easily scaled up industrially, this contributes to the efficient use of resources for sustainable agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c3fffd6c-b9f9-46a9-a356-30459ac10a7b', 'e6df4d80-729a-447a-859d-72653a560793', 'Effectiveness of Different Classes of Fungicides on Botrytis cinerea Causing Gray Mold on Fruit and Vegetables', 'Joon-Oh Kim, Jong-Hwan Shin, Adiyantara Gumilang, Keun Chung, Ki Young Choi, Kyoung Su Kim', 2016, 'The Plant Pathology Journal', '10.5423/PPJ.NT.05.2016.0114', 'https://doi.org/10.5423/PPJ.NT.05.2016.0114', 'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC5117866', NULL, NULL, 5, NULL, 'other', 1, 'open access (DOAJ)', 'Botrytis cinerea is a necrotrophic pathogen causing a major problem in the export and post-harvest of strawberries. Inappropriate use of fungicides leads to resistance among fungal pathogens. Therefore, it is necessary to evaluate the sensitivity of B. cinerea to various classes of fungicide and to determine the effectiveness of different concentrations of commonly used fungicides. We thus evaluated the effectiveness of six classes of fungicide in inhibiting the growth and development of this pathogen, namely, fludioxonil, iprodione, pyrimethanil, tebuconazole, fenpyrazamine, and boscalid. Fludioxonil was the most effective (EC₅₀ < 0.1 μg/ml), and pyrimethanil was the least effective (EC₅₀ = 50 μg/ml), at inhibiting the mycelial growth of B. cinerea. Fenpyrazamine and pyrimethanil showed relatively low effectiveness in inhibiting the germination and conidial production of B. cinerea. Our results are useful for the management of B. cinerea and as a basis for monitoring the sensitivity of B. cinerea strains to fungicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('781772f5-9a32-4eac-a1ff-23ee2e508e03', 'e6df4d80-729a-447a-859d-72653a560793', 'Environmental pollution effect on honey bees and their derived products: a comprehensive analysis', 'Margaoan R, Papa G, Nicolescu A, Cornea-Cipcigan M, Kösoğlu M, Topal E, Negri I', 2025, 'Environmental science and pollution research international', '10.1007/s11356-024-33754-4', 'https://doi.org/10.1007/s11356-024-33754-4', 'https://europepmc.org/articles/PMC11996992?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Several factors, including environmental degradation, air pollution, intense urbanization, excessive agriculture, and climate change, endanger the well-being of animals and plants. One of the major issues with an increasingly negative impact is agricultural contamination with pesticides and antibiotics. Seed coatings with neonicotinoid insecticides used as a protective layer against pests are shown to exceed the permissible limits in most cases. Neonicotinoid compounds bind to nicotinic acetylcholine receptors, therefore affecting the honey bees'' brain. Heavy metals in higher concentrations are lethal for honey bees, and the residue in bee products might pose a threat to human health. Highly effective acaricides used to treat Varroa destructor infestations in honey bee colonies have negative effects on honey bee reproduction, olfaction, and honey production. Furthermore, amitraz and fluvalinate are mostly found in the highest amounts and lead to decreased honey production and reduced colony reproduction, along with decreased learning ability and memory. However, scientific studies have shown that honey bees act as a reliable bio-indicator of environmental pollution. In response to the growing demand for bee products, the effects of adulteration and improper storage conditions have gotten worse and represent a new risk factor. In light of the shifting global economy, it is important to analyze consumer expectations and adjust manufacturing accordingly. By ensuring the manufacture of high-quality, traceable products devoid of drug residues, consumers will be better protected from subsequent health problems. This review''s objectives are based on the necessity of identifying the risks associated with honey bees and bee products.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('02313a43-072f-40d4-960c-012defb0de28', 'e6df4d80-729a-447a-859d-72653a560793', 'Evaluating the Effects of Flavonoids on Insects: Implications for Managing Pests Without Harming Beneficials', 'Riddick EW', 2024, 'Insects', '10.3390/insects15120956', 'https://doi.org/10.3390/insects15120956', 'https://europepmc.org/articles/PMC11678172?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'Flavonoids have multiple functions, including host-plant defense against attacks from herbivorous insects. This manuscript reviewed and analyzed the scientific literature to test the hypothesis that flavonoids can be utilized to manage pests without causing significant harm to beneficials. The methodology involved using recognized literature databases, e.g., Web of Science, Scopus, and CAB Abstracts, via the USDA-ARS, National Agricultural Library, DigiTop literature retrieval system. Data were compiled in tables and subjected to statistical analysis, when appropriate. Flavonoids were generally harmful to true bugs and true flies but harmless to honey bees. Flavonoid glycosides showed a tendency to harm true bugs (Heteroptera) and true flies (Diptera). Flavonoid glycosides were harmless to sawflies. Flavonoids and flavonoid glycosides produced a mixture of harmful and harmless outcomes to herbivorous beetles, depending on the species. Flavonoid glycosides were harmless to butterflies. In conclusion, specific flavonoids could function as feeding stimulants or deterrents, oviposition stimulants or deterrents, chemical protectants from pesticides, mating attractants, less-toxic insecticides, and other functions. Flavonoids could manage some insect pests without causing significant harm to beneficials (e.g., honey bees). Flavonoid-based insecticides could serve as environmentally benign alternatives to broad-spectrum insecticides against some pests, but field testing is necessary.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('790c8f6b-6f26-4ea5-94de-9ff925f0ef20', 'e6df4d80-729a-447a-859d-72653a560793', 'Fungicide resistance in Botrytis cinerea and identification of Botrytis species associated with blueberry in Michigan', 'Abbey JA, Alzohairy SA, Neugebauer KA, Hatlen RJ, Miles TD', 2024, 'Frontiers in microbiology', '10.3389/fmicb.2024.1425392', 'https://doi.org/10.3389/fmicb.2024.1425392', 'https://europepmc.org/articles/PMC11298438?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'Botrytis blossom blight and fruit rot, caused by Botrytis cinerea, is a significant threat to blueberries, potentially resulting in substantial economic losses if not effectively managed. Despite the recommendation of various cultural and chemical practices to control this pathogen, there are widespread reports of fungicide resistance, leading to decreased efficacy. This study aimed to characterize the resistance profile of B. cinerea isolated from blighted blossoms and fruit in 2019, 2020 and 2022 (n = 131, 40, and 37 for the respective years). Eight fungicides (fludioxonil, thiabendazole, pyraclostrobin, boscalid, fluopyram, fenhexamid, iprodione, and cyprodinil) were tested using conidial germination at specific discriminatory doses. Additionally, 86 isolates were phylogenetically characterized using the internal transcribed spacer regions (ITS) and the protein coding genes: glyceraldehyde-3-phosphate dehydrogenase (G3PDH), heat-shock protein 60 (HSP60), and RNA polymerase II second largest subunit (RPB2). This revealed higher fungicide resistance frequencies in 2020 and 2022 compared to 2019. Over all 3 years, over 80% of the isolates were sensitive to fludioxonil, fluopyram, and fenhexamid. Pyraclostrobin and boscalid showed the lowest sensitivity frequencies (Botrytis cinerea was the most prevalent species among the isolates (74) with intraspecific diversity detected by the genes. Two isolates were found to be closely related to B. fabiopsis, B. galanthina, and B. caroliniana and 10 isolates appeared to be an undescribed species. This study reports the discovery of a potentially new species sympatric with B. cinerea on blueberries in Michigan.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4f1dcb90-2600-4ccc-8063-14cf82721886', 'e6df4d80-729a-447a-859d-72653a560793', 'Fungicide Resistance in Botrytis spp. and Regional Strategies for Its Management in Northern European Strawberry Production', 'Weber RWS, Petridis A', 2023, 'Biotech (Basel (Switzerland))', '10.3390/biotech12040064', 'https://doi.org/10.3390/biotech12040064', 'https://europepmc.org/articles/PMC10660734?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Grey mould, caused by Botrytis cinerea and other Botrytis spp., is a major cause of fruit rot in strawberries and other fruit crops worldwide. Repeated fungicide applications are essential in order to secure harvests. However, resistance to all currently registered single-site fungicides is widespread. The rising importance of strains with multiple resistance to most or all fungicides is of particular concern. These strains may be introduced into fields via contaminated nursery plants and/or by immigration from adjacent plots. On the basis of research conducted in northern German and Danish strawberry production, a concept to manage fungicide resistance under northern European conditions has been developed and put into regional strawberry production practice. This principally includes the testing of nursery plants for fungicide-resistant Botrytis strains prior to planting; the restricted and specific use of fungicides at flowering in the production fields, taking account of the resistance spectrum within the local Botrytis population; and crop sanitation measures such as the removal of rotting fruits at the beginning of harvest. Further options such as protected cultivation, reduced fertilisation and biological control are also discussed. The practical implementation of such a strategy in northern Germany and Denmark has been shown to reduce the occurrence of multi-resistant strains to a tolerable steady-state level.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b1b9a085-0a81-4239-aef6-ac55196b6156', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Fungal community profiles in agricultural soils of a long-term field trial under different tillage, fertilization and crop rotation conditions analyzed by high-throughput ITS-amplicon sequencing', 'Sommermann L, Geistlinger J, Wibberg D, Deubel A, Zwanzig J, Babin D, Schlüter A, Schellenberg I', 2018, 'PloS one', '10.1371/journal.pone.0195345', 'https://doi.org/10.1371/journal.pone.0195345', 'https://europepmc.org/articles/PMC5886558?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'Fungal communities in agricultural soils are assumed to be affected by soil and crop management. Our intention was to investigate the impact of different tillage and fertilization practices on fungal communities in a long-term crop rotation field trial established in 1992 in Central Germany. Two winter wheat fields in replicated strip-tillage design, comprising conventional vs. conservation tillage, intensive vs. extensive fertilization and different pre-crops (maize vs. rapeseed) were analyzed by a metabarcoding approach applying Illumina paired-end sequencing of amplicons generated by two recently developed primer pairs targeting the two fungal Internal Transcribed Spacer regions (ITS1, ITS2). Analysis of 5.1 million high-quality sequence reads uncovered a diverse fungal community in the two fields, composed of 296 fungal genera including 3,398 Operational Taxonomic Units (OTUs) at the 97% sequence similarity threshold. Both primer pairs detected the same fungal phyla (Basidio-, Asco-, Zygo-, Glomero- and Chytridiomycota), but in different relative abundances. OTU richness was higher in the ITS1 dataset, while ITS2 data were more diverse and of higher evenness. Effects of farming practice on fungal community structures were revealed. Almost two-thirds of the fungal genera were represented in all different soil treatments, whereas the remaining genera clearly responded to farming practice. Principal Component Analysis revealed four distinct clusters according to tillage practice and pre-crop. Analysis of Variance (ANOVA) substantiated the results and proved significant influences of tillage and pre-crop, while fertilization had the smallest and non-significant effect. In-depth analysis of putative phytopathogenic and plant beneficial fungal groups indicated distinct responses; for example Fusarium was significantly enriched in the intensively fertilized conservation tillage variants with the pre-crop maize, while Phoma displayed significant association with conventional tillage and pre-crop rapeseed. Many putative plant beneficial fungi also reacted differentially to farming practice with the most distinct responders identified among the Glomeromycota (arbuscular mycorrhizal fungi, AMF).', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad14e039-c5ca-4203-8934-a02902f3469f', 'e6df4d80-729a-447a-859d-72653a560793', 'Insights into Grape Ripe Rot: A Focus on the Colletotrichum gloeosporioides Species Complex and Its Management Strategies', 'Hsieh TF, Shen YM, Huang JH, Tsai JN, Lu MT, Lin CP', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12152873', 'https://doi.org/10.3390/plants12152873', 'https://europepmc.org/articles/PMC10421077?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Grape ripe rot, which is predominantly caused by the Colletotrichum species, presents a growing threat to global grape cultivation. This threat is amplified by the increasing populations of the Colletotrichum species in response to warmer climates. In this review, we investigate the wide-ranging spectrum of grape ripe rot, specifically highlighting the role and characteristics of the C. gloeosporioides species complex (CGSC). We incorporate this understanding as we explore the diverse symptoms that lead to infected grapevines, their intricate life cycle and epidemiology, and the escalating prevalence of C. viniferum in Asia and globally. Furthermore, we delve into numerous disease management strategies, both conventional and emerging, such as prevention and mitigation measures. These strategies include the examination of host resistances, beneficial cultivation practices, sanitation measures, microbiome health maintenance, fungicide choice and resistance, as well as integrated management approaches. This review seeks to enhance our understanding of this globally significant disease, aspiring to assist in the development and improvement of effective prevention and control strategies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd70973e-75c7-4619-a989-f76600096c94', 'e6df4d80-729a-447a-859d-72653a560793', 'Is the Biopesticide from Tea Tree Oil an Effective and Low-Risk Alternative to Chemical Pesticides? A Critical Review', 'Dziągwa-Becker M, Oleszek M', 2024, 'Molecules (Basel, Switzerland)', '10.3390/molecules29143248', 'https://doi.org/10.3390/molecules29143248', 'https://europepmc.org/articles/PMC11278977?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'The use of chemical pesticides in agriculture contributes to soil, water and air pollution, biodiversity loss, and injury to non-target species. The European Commission has already established a Harmonized Risk Indicator to quantify the progress in reducing the risks linked to pesticides. Therefore, there is an increasing need to promote biopesticides, or so-called low-risk pesticides (LRP). Tea tree oil (TTO) is known for its antiseptic, antimicrobial, antiviral, antifungal, and anti-inflammatory properties. TTO has been extensively studied in pest management as well as in the pharmaceutical and cosmetic industry; there are already products based on its active substances on the market. This review focuses on the overall evaluation of TTO in terms of effectiveness and safety as a biopesticide for the first time. The collected data can be an added value for further evaluation of TTO in terms of the authorization extension as a fungicide in 2026.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('41f79819-748b-4028-8f01-90b8ed1eaa2a', 'e6df4d80-729a-447a-859d-72653a560793', 'Managing fruit rot diseases of Vaccinium corymbosum', 'Neugebauer KA, Mattupalli C, Hu M, Oliver JE, VanderWeide J, Lu Y, Sullivan K, Stockwell VO', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1428769', 'https://doi.org/10.3389/fpls.2024.1428769', 'https://europepmc.org/articles/PMC11333449?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'Blueberry is an important perennial fruit crop with expanding consumption and production worldwide. Consumer demand for blueberries has grown due to the desirable flavor and numerous health benefits, and fresh market production in the U.S. has risen in turn. U.S. imports have also increased to satisfy year-round consumer demand for fresh blueberries. Pre- and post-harvest fruit diseases such as anthracnose (caused by Colletotrichum spp.) and botrytis fruit rot (caused by Botrytis spp.) have a significant impact on fruit quality and consumer acceptance. These are also among the most difficult diseases to control in the blueberry cropping system. These latent pathogens can cause significant losses both in the field, and especially during transport and marketplace storage. Although both diseases result in rotted fruit, the biology and infection strategies of the causal pathogens are very different, and the management strategies differ. Innovations for management, such as improved molecular detection assays for fungicide resistance, postharvest imaging, breeding resistant cultivars, and biopesticides have been developed for improved fruit quality. Development and integration of new strategies is critical for the long-term success of the blueberry industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d86d09b0-9cd6-4e72-88aa-b89c75fc472a', 'e6df4d80-729a-447a-859d-72653a560793', 'Modes of action and emerging strategies in next-generation fungicide development against phytopathogenic fungi', 'Woo J, Jung S, Park E', 2026, 'Frontiers in plant science', '10.3389/fpls.2026.1906086', 'https://doi.org/10.3389/fpls.2026.1906086', 'https://europepmc.org/articles/PMC13679547?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'Plant fungal diseases impose significant annual reductions of global crop yield and quality. Despite advances in our understanding of the etiology and molecular mechanisms of plant-fungus interactions, effective management of fungal diseases remains challenging due to climate-driven shifts in pathogen populations, the emergence of fungicide-resistant strains, globalization in agricultural supply chains, and postharvest vulnerabilities. To address these challenges, research in plant pathology has leveraged state-of-the-art technologies, with the development of novel fungicides serving as a major step forward in crop protection. This review highlights advances in fungicide development against pathogenic fungi, with an emphasis on the modes of action and regulatory mechanisms of commercial active ingredients that reflect current trends in efforts to secure global food resources. Furthermore, emerging technologies and innovative approaches for developing next-generation fungicides are discussed. By leveraging mechanistic insights and applied innovations, future research can be guided to enable the rational design of fungicides to mitigate both current and emerging agricultural challenges.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('880358f8-26c4-401c-863b-63cab6d445cd', 'e6df4d80-729a-447a-859d-72653a560793', 'Multidrug resistance of Botrytis cinerea associated with its adaptation to plant secondary metabolites', 'Zhaochen Wu, Yue Bi, Junting Zhang, Tuqiang Gao, Xueming Li, Jianjun Hao, Guihua Li, Pengfei Liu', 2024, 'mBio', '10.1128/mbio.02237-23', 'https://doi.org/10.1128/mbio.02237-23', 'https://journals.asm.org/doi/10.1128/mbio.02237-23', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT Fungicides are an effective way to control gray mold of grapes, but the pathogen Botrytis cinerea can develop resistance, overcoming the effectiveness of a fungicide that is repeatedly applied. More importantly, the emergence of multidrug resistance (MDR) in the field, where multiple fungicides with different modes of action simultaneously lose their efficacies, is a significant concern. MDR is associated with ATP-binding cassette (ABC) transporters of the pathogen, and certain plant secondary metabolites (PSMs) stimulate the upregulation of ABC transporters, we hypothesized that the pathogen’s preadaptation to PSMs might contribute to MDR development. To test this in B. cinerea, ten PSMs, namely, resveratrol, reserpine, chalcone, flavanone, eugenol, farnesol, anethene, camptothecin, salicylic acid, and psoralen, were selected based on their association with ABC transporters involved in fungicide resistance. B. cinerea strain B05.10 was continuously transferred for 15 generations on potato dextrose agar amended with a PSM (PDAP), and sensitivities to PSMs and fungicides were examined on the 5th, 10th, and 15th generations. RNA was extracted from B. cinerea from the selected generations. After 15 generations of culture transfers, an up-regulation was observed in the expression of ABC transporter-encoding genes BcatrB, BcatrD, and BcatrK using quantitative polymerase chain reaction (qPCR). This upregulation was found to contribute to MDR of B. cinerea against two or more fungicides, among azoxystrobin, boscalid, fludioxonil, difenoconazole, prochloraz, and pyrimethanil. This finding was confirmed through genetic transformation. The decreased sensitivity of B. cinerea to fungicides was confirmed as a subsequent MDR phenotype after exposure to camptothecin, flavanone, and resveratrol. Besides, transcriptome analysis also revealed the upregulation of transcription factors related to ABC expression following resveratrol exposure. This suggests that PSMs contributed to inducing preadaptation of B. cinerea, leading to subsequent MDR.IMPORTANCEThe emergence of MDR in plant pathogens is a threat to plant disease management and leads to the use of excessive fungicides. Botrytis cinerea is of particular concern because its MDR has widely emerged in the field. Understanding its genesis is the first step for controlling MDR. In this study, the contribution of PSMs to MDR has been examined. Effective management of this pathogen in agroecosystems relies on a better understanding of how it copes with phytochemicals or fungicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c38b55f-679b-451e-b235-362cb824f797', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Soil microbial communities and glyphosate decay in soils with different herbicide application history', 'Keren Hernández Guijarro, Virginia Aparicio, Eduardo De Gerónimo, Martín Alfredo Castellote, Eva L. M. Figuerola, José Luís Costa, Leonardo Erijman', 2018, 'The Science of The Total Environment', '10.1016/j.scitotenv.2018.03.393', 'https://doi.org/10.1016/j.scitotenv.2018.03.393', 'https://ars.els-cdn.com/content/image/1-s2.0-S0048969718311537-fx1_lrg.jpg', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7425ce46-420a-497e-a08c-f9c2f843f5e4', 'e6df4d80-729a-447a-859d-72653a560793', 'Pesticide residues alter taxonomic and functional biodiversity in soils', 'Köninger J, Labouyrie M, Ballabio C, Dulya O, Mikryukov V, Romero F, Franco A, Bahram M', 2026, 'Nature', '10.1038/s41586-025-09991-z', 'https://doi.org/10.1038/s41586-025-09991-z', 'https://europepmc.org/articles/PMC12965876?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Pesticides are widely distributed in soils1-3, yet their effects on soil biodiversity remain poorly understood4-7. Here we examined the effects of 63 pesticides on soil archaea, bacteria, fungi, protists, nematodes, arthropods and key functional gene groups across 373 sites spanning woodlands, grasslands and croplands in 26 European countries. Pesticide residues were detected in 70% of sites and emerged as the second strongest driver of soil biodiversity patterns after soil properties. Our analysis further revealed organism- and function-specific patterns, emphasizing complex and widespread non-target effects on soil biodiversity. Pesticides altered microbial functions, including phosphorus and nitrogen cycling, and suppressed beneficial taxa, including arbuscular mycorrhizal fungi and bacterivore nematodes. Our findings highlight the need to integrate functional and taxonomic characteristics into future risk assessment methodology to safeguard soil biodiversity, a cornerstone of ecosystem functioning.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('61cb2da2-c8e3-4902-a379-6c654af47f2e', 'e6df4d80-729a-447a-859d-72653a560793', 'Plant Antimicrobials for Food Quality and Safety: Recent Views and Future Challenges', 'Pinto L, Tapia-Rodríguez MR, Baruzzi F, Ayala-Zavala JF', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12122315', 'https://doi.org/10.3390/foods12122315', 'https://europepmc.org/articles/PMC10297530?pdf=render', NULL, NULL, 39, NULL, 'other', 1, 'cc by', 'The increasing demand for natural, safe, and sustainable food preservation methods drove research towards the use of plant antimicrobials as an alternative to synthetic preservatives. This review article comprehensively discussed the potential applications of plant extracts, essential oils, and their compounds as antimicrobial agents in the food industry. The antimicrobial properties of several plant-derived substances against foodborne pathogens and spoilage microorganisms, along with their modes of action, factors affecting their efficacy, and potential negative sensory impacts, were presented. The review highlighted the synergistic or additive effects displayed by combinations of plant antimicrobials, as well as the successful integration of plant extracts with food technologies ensuring an improved hurdle effect, which can enhance food safety and shelf life. The review likewise emphasized the need for further research in fields such as mode of action, optimized formulations, sensory properties, safety assessment, regulatory aspects, eco-friendly production methods, and consumer education. By addressing these gaps, plant antimicrobials can pave the way for more effective, safe, and sustainable food preservation strategies in the future.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('93727cd4-4e90-4692-bec7-e1c706660cc7', 'e6df4d80-729a-447a-859d-72653a560793', 'Quantification of 363 Pesticides in Leafy Vegetables (Dill, Rocket and Parsley) in the Turkey Market by Using QuEChERS with LC-MS/MS and GC-MS/MS', 'Deveci B, Golge O, Kabak B', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12051034', 'https://doi.org/10.3390/foods12051034', 'https://europepmc.org/articles/PMC10000932?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Contamination of agricultural products with pesticide residues is a growing concern due to their adverse health effects and increasing worldwide usage of pesticides. In 2021 a total of 200 samples of green leafy vegetables, including 80 dill, 80 rocket and 40 parsley, purchased from greengrocer shops, markets and bazaars in Corum Province, Turkey, were monitored for pesticide residues. In green leafy vegetables, 363 pesticides were analyzed using a quick, easy, cheap, effective, rugged, and safe (QuEChERS) sample preparation, followed by liquid chromatography coupled to mass spectrometry (LC-MS/MS) for 311 residues and gas chromatography coupled to mass spectrometry (GC-MS/MS) for 52 residues. The method was in-house validated at two fortification levels, and satisfactory recoveries and precisions were achieved for all residues. No quantifiable residues were found in 35% of the samples, whereas 43 residues belonging to 24 different chemical classes were detected in 130 green leafy vegetables. Among the green leafy vegetables, the highest occurrence frequency was recorded in the rocket, followed by dill and parsley. In 46% of the green leafy vegetables, the residue levels exceeded European Union Maximum Residue Levels (EU MRLs). The most frequently detected pesticides were pendimethalin (22.5%), diuron (38.7%) and pymetrozine (52.5%) in dill, rocket and parsley, respectively.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce45242e-fc70-4bb2-b279-1df9f7a89c45', 'e6df4d80-729a-447a-859d-72653a560793', 'Report from the 1st MYCOKEY International Conference Global Mycotoxin Reduction in the Food and Feed Chain Held in Ghent, Belgium, 11-14 September 2017', 'De Saeger S, Logrieco A', 2017, 'Toxins', '10.3390/toxins9090276', 'https://doi.org/10.3390/toxins9090276', 'https://europepmc.org/articles/PMC5618209?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'This conference is organized within the framework of the H2020-Research and Innovation Action-Societal Challenge 2-"Food security, sustainable agriculture and forestry, marine, maritime and inland water research and the bioeconomy challenge"-GA 678781 MycoKey "Integrated and innovative key actions for mycotoxin management in the food and feed chain" [...].', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46467b29-af2c-4b04-bfa3-087627eab7f0', 'e6df4d80-729a-447a-859d-72653a560793', 'Research on chemical control of peach shoot blight and the association between phloem volatile compounds and resistance', 'HU Zhu, WANG Li, ZHAO Hongyue', 2025, 'Guoshu xuebao', '10.13925/j.cnki.gsxb.20250423', 'https://doi.org/10.13925/j.cnki.gsxb.20250423', 'http://fruitsci.zzgss.cn/english/upload/down/month_2508/250820250812.pdf', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', '[Objective] Prunus persica (L.) Batsch, a member of the Rosaceae family, is native to China and has a cultivation and evolutionary history spanning thousands of years. In recent years, peach shoot blight caused by Diaporthe amygdali has been one of the most prevalent fungal diseases in major peachproducing regions of southern China. This study aimed to screen out highly effective chemical fungicides for controlling peach shoot blight, and investigated the relationship between volatile compounds in the phloem of peach shoots and resistance to the disease, providing a scientific basis for integrated disease management strategies and resistance breeding programs. [Methods] The inhibitory effects of 15 fungicides against D. amygdali were evaluated in vitro using the mycelial growth rate method. The active ingredient information was as follows: difenoconazole, pyraclostrobin, propiconazole, boscalid, carbendazim, hymexazol, flusilazole, fludioxonil, hexaconazole, prochloraz, azoxystrobin, trifloxystrobin, tebuconazole, lprodione, and dithianon. A series of concentrations were prepared for each fungicide. The effective medium concentration (EC50) values were calculated based on the correlation between fungicide concentration and mycelial growth inhibition rate by DPS in this study. At the same time, healthy and disease-free one-year-old shoot phloem tissues were collected from 22 peach varieties, which exhibited varying levels of resistance to D. amygdali. After rapid freezing within the liquid nitrogen, the samples were transported to the laboratory for volatile compound analysis. Volatile compounds were extracted and analyzed using Headspace Solid-Phase Microextraction coupled with Gas Chromatography-Mass Spectrometry (HS-SPME-GC-MS). The correlation between the relative content of each identified volatile compound and the resistance level of the corresponding variety was examined. In addition, two typical peach cultivars (Fenghua Pantao, susceptible; and Hakuho, highly susceptible) were selected for inoculation with D. amygdali. Phloem tissue around necrotic spots was collected 7 days after inoculation, flash-frozen, and used for volatile compound analysis. Key volatile compounds significantly correlated with resistance (identified in the correlation analysis) were quantified in these tissues to observe pathogen-induced changes. [Results] The toxicity test of fungicides showed that prochloraz had the strongest inhibitory effect, with an EC50 value of 0.004 2 mg·L-1. Difenoconazole, pyraclostrobin, propiconazole, fludioxonil, flusilazole, hexaconazole, and tebuconazole also showed strong activity. Boscalid showed the weakest inhibitory effect, with an EC50 value of 49.025 2 mg·L-1. Analysis of volatile compounds content showed that volatile compounds were identified in 22 peach samples. A total of 121 volatile compounds were identified, falling into 12 distinct categories: 30 terpenoids, 22 esters, 17 alcohols, 16 ketones, 13 aldehydes, 5 alkanes, 4 fatty acids, 3 phenolics, 3 furans, 2 acids, 1 lactone, and 5 other compounds. Among the samples, Richuan Baifeng and Reddomun had the highest number of volatile compounds, with 85 and 80, respectively. In contrast, the samples Baihua and Zhouxingshantao had the fewest, with 52 and 51 compounds, respectively. To identify volatile metabolites associated with resistance to D. amygdali, we conducted a correlation analysis between the volatile substance content and germplasm resistance to D. amygdali across 22 samples. Sixteen compounds were significantly and negatively correlated with resistance, and six were significantly and positively correlated. Negatively correlated compounds included one acid, one aldehyde, two alkanes, two esters, one fatty acid, four ketones, one phenolic compound, and four terpenoids. The ester compound icosyl oleate had the strongest negative correlation, with a coefficient of-0.676 5 (P<0.01). Positively correlated compounds included one alcohol, two aldehydes,', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e6c6317-83fc-4bfe-a7ee-dd6cc14d3bac', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Efficacy of broflanilide (VECTRON T500), a new meta-diamide insecticide, for indoor residual spraying against pyrethroid-resistant malaria vectors', 'Ngufor C, Govoetchan R, Fongnikin A, Vigninou E, Syme T, Akogbeto M, Rowland M', 2021, 'Scientific reports', '10.1038/s41598-021-86935-3', 'https://doi.org/10.1038/s41598-021-86935-3', 'https://europepmc.org/articles/PMC8042056?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The rotational use of insecticides with different modes of action for indoor residual spraying (IRS) is recommended for improving malaria vector control and managing insecticide resistance. Insecticides with new chemistries are urgently needed. Broflanilide is a newly discovered insecticide under consideration. We investigated the efficacy of a wettable powder (WP) formulation of broflanilide (VECTRON T500) for IRS on mud and cement wall substrates in laboratory and experimental hut studies against pyrethroid-resistant malaria vectors in Benin, in comparison with pirimiphos-methyl CS (Actellic 300CS). There was no evidence of cross-resistance to pyrethroids and broflanilide in CDC bottle bioassays. In laboratory cone bioassays, broflanilide WP-treated substrates killed > 80% of susceptible and pyrethroid-resistant An. gambiae sl for 6-14 months. At application rates of 100 mg/m2 and 150 mg/m2, mortality of wild pyrethroid-resistant An. gambiae sl entering experimental huts in Covè, Benin treated with VECTRON T500 was similar to pirimiphos-methyl CS (57-66% vs. 56%, P > 0.05). Throughout the 6-month hut trial, monthly wall cone bioassay mortality on VECTRON T500 treated hut walls remained > 80%. IRS with broflanilide shows potential to significantly improve the control of malaria transmitted by pyrethroid-resistant mosquito vectors and could thus be a crucial addition to the current portfolio of IRS insecticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd1a2524-41f2-4bd2-8910-880dc2fb5fa0', 'e6df4d80-729a-447a-859d-72653a560793', 'Resistance of Mulberry Fruit Sclerotiniosis Pathogens to Thiophanate-Methyl and Boscalid', 'Xiangmo Chen, Tao Chen, Qianqian Zhang, Chengxin Mao, Chuanqing Zhang', 2025, 'Horticulturae', '10.3390/horticulturae12010009', 'https://doi.org/10.3390/horticulturae12010009', 'https://www.mdpi.com/2311-7524/12/1/9', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Fruit sclerotiniosis (FS) is becoming the most important disease in recently transformed mulberry fruit gardens (TFMGs), where traditional production of mulberry leaves for sericulture takes place; FS has a long history as a secondary disease in Zhejiang province, China. Thiophanate-methyl and boscalid are the two main fungicides adopted for the management of FS in these gardens. A decrease in efficacy has been observed by growers and local technicians. For this new situation regarding TFMGs, however, the resistance status of them has not yet been investigated and reported. In the present study, pathogens were isolated from diseased fruits and identified through a combination of morphological characteristics with ITS sequence analysis. Results showed that the pathogens included Scleromitrula shiraiana and Sclerotinia sclerotiorum. All isolates of S. shiraiana (n = 12) and S. sclerotiorum (n = 12) were sensitive to boscalid, and no resistance was detected. The S. shiraiana sub-population was sensitive to thiophanate-methyl, whereas the S. sclerotiorum sub-population developed resistance with a frequency of 33.3%. Thiophanate-methyl-resistant (ThR) S. sclerotiorum grew faster at a low temperature (15 °C) than sensitive ones. These ThR exhibited negative cross-resistance to diethofencarb, as previously observed in Botrytis cinerea, and showed no cross-resistance to procymidone or boscalid. Further studies indicated that resistance to thiophanate-methyl is caused by a novel double mutation (E198V+V349I) in the β-tubulin of S. sclerotiorum. This E198V+V349I mutation produced structural alterations in the β-tubulin protein, the action target of thiophanate-methyl, leading to reorientation of the substrate binding site and conformational change in the active pocket. In conclusion, avoiding the sole use of thiophanate-methyl on TFMGs is necessary. Application of boscalid in combination or rotation with other fungicides without cross-resistance is recommended for the management of FS in TFMG practices.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0628862a-837d-4e8e-99aa-5e25dd5dd257', 'e6df4d80-729a-447a-859d-72653a560793', 'Resistance to Boscalid, Fluopyram and Fluxapyroxad in Blumeriella jaapii from Michigan (U.S.A.): Molecular Characterization and Assessment of Practical Resistance in Commercial Cherry Orchards', 'Jacqueline Gleason, Jingyu Peng, Tyre J. Proffer, Suzanne M. Slack, Cory A. Outwater, Nikki L. Rothwell, George W. Sundin', 2021, 'Microorganisms', '10.3390/microorganisms9112198', 'https://doi.org/10.3390/microorganisms9112198', 'https://www.mdpi.com/2076-2607/9/11/2198', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Management of cherry leaf spot disease, caused by the fungus Blumeriella jaapii, with succinate dehydrogenase inhibitor (SDHI) fungicides has been ongoing in Michigan tart cherry orchards for the past 17 years. After boscalid-resistant B. jaapii were first isolated from commercial orchards in 2010, premixes of SDHI fungicides fluopyram or fluxapyroxad with a quinone outside inhibitor were registered in 2012. Here, we report widespread resistance to fluopyram (FluoR), fluxapyroxad (FluxR), and boscalid (BoscR) in commercial orchard populations of B. jaapii in Michigan from surveys conducted between 2016 and 2019. A total of 26% of 1610 isolates from the 2016–2017 surveys exhibited the fully-resistant BoscR FluoR FluxR phenotype and only 7% were sensitive to all three SDHIs. Practical resistance to fluopyram and fluxapyroxad was detected in 29 of 35 and 14 of 35 commercial tart cherry orchards, respectively, in surveys conducted in 2018 and 2019. Sequencing of the SdhB, SdhC, and SdhD target genes from 22 isolates with varying resistance phenotypes showed that BoscS FluoR FluxS isolates harbored either an I262V substitution in SdhB or an S84L substitution in SdhC. BoscR FluoR FluxR isolates harbored an N86S substitution in SdhC, or contained the N86S substitution with the additional I262V substitution in SdhB. One BoscR FluoR FluxR isolate contained both the I262V substitution in SdhB and the S84L substitution in SdhC. These mutational analyses suggest that BoscR FluoR FluxR isolates evolved from fully sensitive BoscS, FluoS, FluxS isolates in the population and not from boscalid-resistant isolates that were prevalent in the 2010–2012 time period.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e36cf204-33bb-49de-a7ab-15a855f3c49a', 'e6df4d80-729a-447a-859d-72653a560793', 'Sensitivity of Botrytis cinerea Isolates Collected from Strawberry to SDHI Fungicide Boscalid', 'Y. M. Shabana, Al-Zahraa Ahmed, Mohamed Sobhy', 2022, 'Journal of Plant Protection and Pathology', '10.21608/jppp.2022.161968.1093', 'https://doi.org/10.21608/jppp.2022.161968.1093', 'https://jppp.journals.ekb.eg/article_263493_3809437f2b24a9f524699a08d56c1837.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Egypt is considered one of the main strawberry producer''s countries. Grey mould, caused by Botrytis cinerea, is a destructive disease resulting in significant losses in strawberry production worldwide. Fruits might be infected in the field, storage and transport. Management Approaches for the pathogen in strawberry depends mainly on using protective fungicides. Boscalid is a new broad-spectrum fungicide used to control B. cinerea in strawberry. Recently, lack of efficiency of the fungicide reported in many countries. The current study aims to detect Botrytis cinerea resistant isolates to boscalidin the main strawberry production governorates in Egypt (Beheira, Ismailia and Qalyubie) between 2019 and 2021. 269 isolates were collected and tested to distinguish resistant isolates. Sensitivity of a set of resistant and sensitive isolates was measured by determining the effective concentration that inhibits 50 % of mycelial growth. The results showed that, 225 (83.6%) isolates were resistant to boscalid while, only 47 (16.4%) isolates were sensitive. Monitoring of resistance frequency revealed that there were remarkably increasing in resistance frequencies to boscalid in B. cinerea isolates during 2019 and 2021 seasons as it was 84.03% in 2019 while it reached to 98.87% in 2021. 17 BosS sensitive isolates randomly selected were used to determine the EC50 for boscalid using mycelial growth inhibition assay and the EC50 values ranged from 0.0067 to 1.14 µg/ml with a mean of 0.29 µg/ml. While, the EC50 values for17 BosR resistant isolates randomly selected ranged from 2.1 to 16.2 µg/ml with a mean of 7.3 µg/ml.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('82e69e0a-a652-4cae-a221-3a34ddb22e07', 'e6df4d80-729a-447a-859d-72653a560793', 'Studies on the control of ascochyta blight in field peas (Pisum sativum L.) caused by Ascochyta pinodes in Zhejiang Province, China', 'Na eLiu, Shengchun eXu, Xiefeng eYao, Guwen eZhang, Weihua eMao, Qizan eHu, Zhijuan eFeng, Yaming eGong', 2016, 'Frontiers in Microbiology', '10.3389/fmicb.2016.00481', 'https://doi.org/10.3389/fmicb.2016.00481', 'http://journal.frontiersin.org/Journal/10.3389/fmicb.2016.00481/full', NULL, NULL, 14, NULL, 'other', 1, 'open access (DOAJ)', 'Ascochyta blight, an infection caused by a complex of Ascochyta pinodes, Ascochyta pinodella, Ascochyta pisi, and/or Phoma koolunga, is a destructive disease in many field peas (Pisum sativum L.)-growing regions, and it causes significant losses in grain yield. To understand the composition of fungi associated with this disease in Zhejiang Province, China, a total of 65 single-pycnidiospore fungal isolates were obtained from diseased pea samples collected from 5 locations in this region. These isolates were identified as Ascochyta pinodes by molecular techniques and their morphological and physiological characteristics. The mycelia of ZJ-1 could penetrate pea leaves across the stomas, and formed specific penetration structures and directly pierced leaves. The resistance level of 23 available pea cultivars was tested against their representative isolate A. pinodes ZJ-1 using the excised leaf-assay technique. The ZJ-1 mycelia could penetrate the leaves of all tested cultivars, and they developed typical symptoms, which suggested that all tested cultivars were susceptible to the fungus. Chemical fungicides and biological control agents were screened for management of this disease, and their efficacies were further determined. Most of the tested fungicides (11 out of 14) showed high activity towards ZJ-1 with EC50 < 5 μg/mL. Moreover, fungicides, including tebuconazole, boscalid, iprodione, carbendazim and fludioxonil, displayed more than 80% disease control efficacy under the recorded conditions. Three biocontrol strains of Bacillus sp. and one of Pantoea agglomerans were isolated from pea-related niches and significantly reduced the severity of disease under greenhouse and field conditions. To our knowledge, this is the first study on ascochyta blight in field peas, and results presented here will be useful for controlling the disease in this area.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5f6b8be8-cb92-49e2-b036-25225be4bd2c', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'A noninferiority cluster randomised evaluation of a broflanilide indoor residual spraying insecticide, VECTRON T500, for malaria vector control in Tanzania', 'Njelembo J. Mbewe, Patrick K. Tungu, Louisa A. Messenger, John Bradley, Peter E. Mangesho, Boniface Shirima, Oliver Moshi, Magreth F. Shayo', 2025, 'Scientific Reports', '10.1038/s41598-025-99809-9', 'https://doi.org/10.1038/s41598-025-99809-9', 'https://doi.org/10.1038/s41598-025-99809-9', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Effective malaria vector control is being undermined by the rapid spread of insecticide resistance. VECTRON T500, a new indoor residual spraying (IRS) product containing the active ingredient broflanilide as a 50% wettable powder (WP), was previously shown to be efficacious in experimental hut trials. A two-arm non-inferiority cluster randomized controlled community trial was conducted in Muheza District, Tanga Region, Tanzania. VECTRON T500 was compared to the IRS product Fludora Fusion (clothianidin 50% + deltamethrin 6.25% WP-SB). Sixteen village clusters were pair-matched on baseline vector densities and allocated to reference and intervention arms. Monthly CDC light trapping sampled mosquitoes to estimate vector density, indoor biting, sporozoite and entomological inoculation rate (EIR). The non-inferiority margin of mosquito density was defined as a density ratio of 1.5. Susceptibility to IRS active ingredients was assessed in one of the local vectors, Anopheles gambiae sensu lato (s.l.), using WHO/CDC bottle bioassays. The residual efficacy of both IRS products was monitored for 12 months using susceptible and pyrethroid resistant An. gambiae sensu stricto (s.s.) mosquitoes. This study is registered with ClinicalTrials.gov (NCT05150808). A total of 916 and 844 houses were sprayed with Fludora Fusion and VECTRON T500, respectively, with equitable spray coverage. An. gambiae s.l. was resistant to deltamethrin but susceptible to clothianidin and broflanilide. The density ratio adjusted for baseline Anopheline mosquito density was 0.77 (95% CI: 0.45–1.29). The baseline adjusted sporozoite rate and EIR differences between the two trial arms were 0.84% and 15.61%, respectively. The residual efficacy was > 80% mortality for VECTRON T500 and Fludora Fusion, on both mud and concrete walls, 12 months post spraying. VECTRON T500 was non-inferior to Fludora Fusion in terms of its ability to reduce vector density, sporozoite rate and EIR, providing an additional vector control tool with a new mode of action for malaria prevention and insecticide resistance management.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('09b393d9-ef8c-48eb-be39-205efc3f49c5', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Adult mosquitoes of the sibling species Anopheles gambiae and Anopheles coluzzii exhibit contrasting patterns of susceptibility to four neonicotinoid insecticides along an urban-to-rural gradient in Yaoundé, Cameroon', 'Ashu FA, Fouet C, Ambadiang MM, Penlap-Beng V, Kamdem C', 2024, 'Malaria journal', '10.1186/s12936-024-04876-4', 'https://doi.org/10.1186/s12936-024-04876-4', 'https://europepmc.org/articles/PMC10909279?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'BackgroundNeonicotinoids are potential alternatives for controlling pyrethroid-resistant mosquitoes, but their efficacy against malaria vector populations of sub-Saharan Africa has yet to be investigated. The aim of the present study was to test the efficacy of four neonicotinoids against adult populations of the sibling species Anopheles gambiae and Anopheles coluzzii sampled along an urban-to-rural gradient.MethodsThe lethal toxicity of three active ingredients for adults of two susceptible Anopheles strains was assessed using concentration-response assays, and their discriminating concentrations were calculated. The discriminating concentrations were then used to test the susceptibility of An. gambiae and An. coluzzii mosquitoes collected from urban, suburban and rural areas of Yaoundé, Cameroon, to acetamiprid, imidacloprid, clothianidin and thiamethoxam.ResultsLethal concentrations of neonicotinoids were relatively high suggesting that this class of insecticides has low toxicity against Anopheles mosquitoes. Reduced susceptibility to the four neonicotinoids tested was detected in An. gambiae populations collected from rural and suburban areas. By contrast, adults of An. coluzzii that occurred in urbanized settings were susceptible to neonicotinoids except acetamiprid for which 80% mortality was obtained within 72 h of insecticide exposure. The cytochrome inhibitor, piperonyl butoxide (PBO), significantly enhanced the activity of clothianidin and acetamiprid against An. gambiae mosquitoes.ConclusionsThese findings corroborate susceptibility profiles observed in larvae and highlight a significant variation in tolerance to neonicotinoids between An. gambiae and An. coluzzii populations from Yaoundé. Further studies are needed to disentangle the role of exposure to agricultural pesticides and of cross-resistance mechanisms in the development of neonicotinoid resistance in some Anopheles species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2cea2010-283c-4122-a366-8f226ec29fbb', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Baseline Susceptibility, Cross-Resistance, and Sublethal Effects of Broflanilide, a Novel Meta-Diamide Pesticide, in Spodoptera litura', 'Li Y, Qu C, Zhang Q, Zhang L, Luo C, Wang R', 2023, 'International journal of molecular sciences', '10.3390/ijms24065351', 'https://doi.org/10.3390/ijms24065351', 'https://europepmc.org/articles/PMC10048816?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Spodoptera litura is a damaging and notorious insect pest of agricultural crops that has developed resistance to various insecticides. Broflanilide is a novel pesticide with a unique mode of action that displays high efficiency against lepidopterous larvae. We here determined the baseline susceptibility of a laboratory strain of S. litura to broflanilide and 10 other popular insecticides. Furthermore, we measured susceptibility and cross-resistance using three common insecticides in 11 field-collected S. litura populations. Broflanilide caused the highest toxicity among all tested insecticides, with the laboratory strain and all field-collected populations showing high susceptibility. Moreover, no cross-resistance was detected between broflanilide and the other tested insecticides. We subsequently evaluated the sublethal effects of broflanilide and found that treatment with the 25% lethal concentration (LC25) prolonged the development duration in the larvae, reduced the pupation rate and pupae weight, and decreased egg hatchability. Finally, the activities of three detoxifying enzymes were measured in S. litura after treatment with the LC25 dose. The results suggested that enhanced cytochrome P450 monooxygenase (P450) activity could be involved in broflanilide detoxification. Overall, these findings demonstrate the strong toxicity and significant sublethal effects of broflanilide in S. litura and suggest that increased P450 activity may be associated with broflanilide detoxification.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('208d903b-eb97-4e76-b1ae-be5afbc699e2', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Community evaluation of VECTRON™ T500 (broflanilide) for indoor residual spraying for malaria vector control in Siaya county, Kenya', 'Celestine N. Wekesa, Brian Polo, Margaret Muchoki, Seline Omondi, Mathew Kipsum, Bernard Abong’o, Maxwell G. Machani, Teresa Bange', 2025, 'Malaria Journal', '10.1186/s12936-025-05688-w', 'https://doi.org/10.1186/s12936-025-05688-w', 'https://doi.org/10.1186/s12936-025-05688-w', NULL, NULL, 22, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Indoor residual spraying (IRS) remains a core malaria vector control intervention, but widespread insecticide resistance threatens its effectiveness. VECTRON™ T500, containing broflanilide, represents a novel IRS product with a new mode of action targeting GABA receptors. Methods A two-arm non-inferiority study was conducted in Bar Olengo, Siaya County, Kenya, between June and November 2024. Twenty-five structures per arm were sprayed with either VECTRON™ T500 (100 mg a.i/m2) or Actellic™ 300CS (1 g a.i/m2), with five water-sprayed controls. Residual efficacy was assessed using world health organization (WHO) cone bioassays with pyrethroid-resistant Anopheles gambiae sensu stricto (s.s.) Bungoma strain and susceptible Kisumu strain monthly for six months. Wild vector susceptibility to insecticides, community acceptability, and adverse events were evaluated. Results VECTRON™ T500 maintained significantly higher mortality than Actellic™ 300CS throughout six months on both wall types. Against resistant An. gambiae s.s. Bungoma strain, VECTRON™ T500 achieved 98.73 ± 3.51% mortality (95% CI 97.95–99.51%) compared to 80.22 ± 11.23% for Actellic™ 300CS (95% CI 77.72–82.72%; t₇₈ = − 10.15, p  95% effective throughout. Wild An. gambiae sensu lato (s.l.) and Anopheles funestus s.l. showed 100% susceptibility to broflanilide with no cross-resistance detected. No adverse events occurred in VECTRON™ T500 households versus 8% (12/150) in Actellic™ 300CS households. Community acceptance was 100% for VECTRON™ T500 versus 99.33% (149/150) for Actellic™ 300CS, though this difference was not statistically significant. Conclusions VECTRON™ T500 demonstrated superior residual efficacy, excellent safety profile, and high community acceptance compared to Actellic™ 300CS. Its novel mode of action and absence of cross-resistance to pirimiphos-methyl and pyrethroids make it valuable for insecticide resistance management in malaria vector control programmes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a5a2f25b-a971-4209-9b79-d6635786f1b9', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Community evaluation of VECTRON™ T500, a broflanilide insecticide, for indoor residual spraying for malaria vector control in central Benin; a two arm non-inferiority cluster randomised trial', 'Ngufor C, Govoetchan R, Fongnikin A, Hueha C, Ahoga J, Syme T, Agbevo A, Daleb A', 2023, 'Scientific reports', '10.1038/s41598-023-45047-w', 'https://doi.org/10.1038/s41598-023-45047-w', 'https://europepmc.org/articles/PMC10587144?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'VECTRON™ T500 is a wettable powder IRS formulation of broflanilide, a newly discovered insecticide. We performed a two-arm non-inferiority community randomised evaluation of VECTRON™ T500, compared to Fludora® Fusion against pyrethroid-resistant Anopheles gambiae s.l. in an area of high coverage with pyrethroid-only nets in the Za-Kpota District of central Benin. One round of IRS was applied in all consenting households in the study area. Sixteen clusters were randomised (1:1) to receive VECTRON™ T500 (100 mg/m2 for broflanilide) or Fludora® Fusion (200 mg/m2 for clothianidin and 25 mg/m2 for deltamethrin). Surveys were performed to assess adverse events and the operational feasibility and acceptability of VECTRON™ T500 among spray operators and household inhabitants. Human landing catches were conducted in 6 households every 1-2 months for up to 18 months post-intervention to assess the impact on vector densities, sporozoite rates and entomological inoculation rates. Bottle bioassays were performed to monitor vector susceptibility to pyrethroids, broflanilide and clothianidin. Monthly wall cone bioassays were conducted for 24 months to assess the residual efficacy of the IRS formulations using susceptible and pyrethroid-resistant An. gambiae s.l. A total of 26,562 female mosquitoes were collected during the study, of which 40% were An. gambiae s.l., the main malaria vector in the study area. The vector population showed high intensity pyrethroid resistance but was susceptible to broflanilide (6 µg/bottle) and clothianidin (90 µg/bottle). Using a non-inferiority margin of 50%, vector density indicated by the human biting rate (bites/person/night) was non-inferior in the VECTRON™ T500 arm compared to the Fludora® Fusion arm both indoors (0.846 bites/p/n in Fludora® Fusion arm vs. 0.741 bites/p/n in VECTRON™ T500 arm, IRR 0.54, 95% CI 0.22-1.35, p = 0.150) and outdoors (0.691 bites/p/n in Fludora® Fusion arm vs. 0.590 bites/p/n in VECTRON™ T500 clusters, IRR 0.75, 95% CI 0.41-1.38, p = 0.297). Sporozoite rates and entomological inoculation rates did not differ significantly between study arms (sporozoite rate: 0.9% vs 1.1%, p = 0. 0.746, EIR: 0.008 vs 0.006 infective bites per person per night, p = 0.589). Cone bioassay mortality with both VECTRON™ T500 and Fludora® Fusion was 100% for 24 months post-IRS application on both cement and mud treated house walls with both susceptible and pyrethroid-resistant strains of An. gambiae s.l. Perceived adverse events reported by spray operators and householders were generally very low (< 6%) in both study arms. VECTRON™ T500 was non-inferior to Fludora® Fusion in reducing the risk of malaria transmission by pyrethroid resistant vectors when applied for IRS in communities in central Benin. The insecticide showed prolonged residual efficacy on house walls, lasting over 24 months and had a high acceptability with homeowners. Community application of VECTRON™ T500 for IRS provides improved and prolonged control of pyrethroid resistant malaria vectors and enhances our capacity to manage insecticide resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('328c9272-5ae1-4f27-a45d-badf9381fb98', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Detection of ryanodine receptor G4911E and I4754M mutation sites and analysis of binding modes of diamide insecticides with RyR on Galeruca daurica (Coleoptera: Chrysomelidae)', 'Ren H, Zhang H, Ni R, Li Y, Li L, Wang W, Tian Y, Pang B', 2022, 'Frontiers in physiology', '10.3389/fphys.2022.1107045', 'https://doi.org/10.3389/fphys.2022.1107045', 'https://europepmc.org/articles/PMC9815114?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'In recent years, the leaf beetle Galeruca daurica has broken out in the northern grasslands of Inner Mongolia, its management still mainly depends on chemical control using traditional insecticides or with novel action. The study was aim to identify mutation locus associated with resistance to diamide insecticides in field population of G. daurica, to provide a reference for rational selection of insecticides and to avoid the rapid resistance development to diamide insecticides. We cloned the full length of the ryanodine receptor gene of G. daurica (GdRyR), constructed 3D model and transmembrane regions by homologous modeling based on deduced amino acid sequence. Two potential mutation loci (Gly4911Glu and Ile4754Met) and allelic mutation frequencies were detected in individuals of G. daurica. In addition, their binding patterns to two diamide insecticides (chlorantraniliprole, cyantraniliprole) were analyzed separately using a molecular docking method. The full-length cDNA sequence of GdRyR (GenBank accession number: OP828593) was obtained by splicing and assembling, which is 15,399 bp in length and encodes 5,133 amino acids. The amino acid similarity of GdRyR with that of other Coleopteran insects were 86.70%-91.33%, which possessed the typical structural characteristics. An individual resistance allelic mutation frequency test on fifty field leaf beetles has identified 12% and 32% heterozygous individuals at two potential mutation loci Gly4911Glu and Ile4754Met, respectively. The affinity of the I4754M mutant model of GdRyR for chlorantraniliprole and cyantraniliprole was not significantly different from that of the wild type, and all had non-covalent interactions such as hydrogen bonding, hydrophobic interactions and π-cation interactions. However, the G4911E mutant model showed reduced affinity and reduced mode of action with two diamide insecticides, thus affecting the binding stability of the ryanodine receptor to the diamide insecticides. In conclusion, the G4911E mutation in GdRyR may be a potential mechanism for the development of resistance to diamide insecticides on G. daurica and should be a key concern for resistance risk assessment and reasonable applications of diamide insecticides for control in future. Moreover, this study could provide a reference for ryanodine receptor structure-based insecticides design.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('accbd699-f25b-43b1-be80-8a5a374594ef', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Ecological Pest Control in Alpine Ecosystems: Monitoring Asteraceae Phytophages and Developing Integrated Management Protocols in the Three River Source Region', 'Li-Jun Zhang, Yu-Shou Ma, Ying Liu, Jun-Ling Wang', 2025, 'Insects', '10.3390/insects16080861', 'https://doi.org/10.3390/insects16080861', 'https://www.mdpi.com/2075-4450/16/8/861', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Aster spp., a key grass species for the ecological restoration of alpine degraded grasslands on the Qinghai–Tibet Plateau, often suffers from pest damage during its flowering and seed maturation stages, severely limiting the effectiveness of ecological restoration and the sustainable utilization of germplasm resources. This study focused on nine widely distributed species of Aster in the Three River Source Region of Qinghai Province, systematically investigated the structure of arthropod communities and the spatiotemporal dynamics of pests, and developed an integrated pest management (IPM) strategy. Through systematic surveys at multiple sites, a total of 109 arthropod species were identified (57 families of insects, 96 species; 7 families of spiders, 13 species). The Diptera (Tephritidae) and Hemiptera (Miridae) were identified as dominant groups. Tephritis angustipennis was determined to be the key pest, with its population density reaching a peak in mid-to-late August (p < 0.05). Based on the occurrence patterns of the pest, an IPM strategy integrating physical, chemical, and biological control methods was proposed: flower head bagging as a physical barrier significantly reduced plant damage but required balancing the risk of seed sterility. A combination lure (broad-spectrum fruit fly lure + a mixture of sugar and vinegar) showed a significant effect in attracting and killing adult flies. In chemical control, spraying a combination of insecticides (DB: 10% β-Cypermethrin aqueous emulsion (9 mL/acre) + 5% avermectin (20 mL/acre)) during the leaf expansion stage to early flowering stage achieved approximately 80% pest mortality within 24 h; additionally, supplementary spraying of 5% broflanilide (30 mL/acre) during the full flowering stage prolonged the efficacy and delayed the development of insecticide resistance. In terms of natural enemy utilization, Lycosidae and Thomisidae demonstrated significant potential for naturally regulating pest populations. Physiological mechanism studies showed that the difference in responses between plant catalase (CAT) activity and insect glutathione S-transferase (GST) activity was a key factor driving control efficacy (the cumulative explanation rate reached 94%). This IPM strategy, by integrating physical barriers, dynamic trapping, targeted spraying, and natural enemy control, significantly enhances control efficiency and ecological compatibility, providing a theoretical basis and technical paradigm for the ecological restoration of degraded alpine grasslands and the sustainable management of medicinal plants in cold regions.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('85fad45c-38cc-43ab-bc82-da1301a0771f', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Effectiveness of piperonyl butoxide and pyrethroid-treated long-lasting insecticidal nets (LLINs) versus pyrethroid-only LLINs with and without indoor residual spray against malaria infection: third year results of a cluster, randomised controlled, two-by-two factorial design trial in Tanzania', 'Protopopoff N, Mosha JF, Messenger LA, Lukole E, Charlwood JD, Wright A, Kessy E, Manjurano A', 2023, 'Malaria journal', '10.1186/s12936-023-04727-8', 'https://doi.org/10.1186/s12936-023-04727-8', 'https://europepmc.org/articles/PMC10548685?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'BackgroundAfter decades of success in reducing malaria through the scale-up of pyrethroid long-lasting insecticidal nets (LLINs), the decline in the malaria burden has stalled, coinciding with the rapid spread of pyrethroid resistance. In a previously reported study, nets treated with a pyrethroid and a synergist, piperonyl butoxide (PBO), demonstrated superior efficacy compared to standard pyrethroid LLINs (std-LLINs) against malaria. Evidence was used to support the public health recommendation of PBO-Pyrethroid-LLIN by the World Health Organization in 2018. This study looks at the third year of rollout of these nets in Muleba district, Tanzania to inform whether policy guidelines need to be updated.MethodsA four-group cluster randomized trial (CRT) using a two-by-two factorial design was carried out between January 2014 and December 2017. A total of 48 clusters, were randomized in a 1:1:1:1 ratio to the following treatment groups, each intervention being provided once in 2015: 1/std-LLIN; 2/PBO-pyrethroid LLIN; 3/std-LLIN + Indoor Residual Spraying (IRS) and 4/PBO-Pyrethroid-LLIN + IRS. During the third year follow-up, malaria infection prevalence in 80 children per cluster, aged 6 months to 14 years, was measured at 28- and 33-months post-intervention and analysed as intention-to-treat (ITT) and per protocol (PP). Mosquito collections were performed monthly in all clusters, using CDC light traps in 7 randomly selected houses per cluster.ResultsAt 28 and 33 months, study net usage among household participants was only 47% and 31%, respectively. In ITT analysis, after 28 months malaria infection prevalence among 7471 children was 80.9% in the two std-LLIN groups compared to 69.3% in the two PBO-Pyrethroid-LLIN (Odds Ratio: 0.45, 95% Confidence Interval: 0.21-0.95, p-value: 0.0364). After 33 months the effect was weaker in the ITT analysis (prevalence 59.6% versus 49.9%, OR: 0.60, 95%CI:0.32-1.13, p-value: 0.1131) but still evident in the PP analysis (57.2% versus 44.2%, OR: 0.34, 95%CI: 0.16-0.71, p-value: 0.0051). Mean number of Anopheles per night collected per house was similar between PBO-Pyrethroid-LLIN groups (5.48) and std-LLIN groups (5.24) during the third year.ConclusionsDespite low usage of PBO- Pyrethroid LLIN, a small impact of those nets on malaria infection prevalence was still observed in the 3rd year with the most protection offered to children still using them. To maximize impact, it is essential that net re-distribution cycles are aligned with this LLIN lifespan to maintain maximum coverage.Trial registrationThe trial was registered with ClinicalTrials.gov (registration number NCT02288637).', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dd157828-7a9f-4040-ae71-2ca0093ed68d', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Effects of RDL GABA Receptor Point Mutants on Susceptibility to Meta-Diamide and Isoxazoline Insecticides in Drosophila melanogaster', 'Zhou T, Wu W, Ma S, Chen J, Huang J, Qiao X', 2024, 'Insects', '10.3390/insects15050334', 'https://doi.org/10.3390/insects15050334', 'https://europepmc.org/articles/PMC11122182?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Ionotropic γ-aminobutyric acid (GABA) receptors in insects, specifically those composed of the RDL (resistant to dieldrin) subunit, serve as important targets for commonly used synthetic insecticides. These insecticides belong to various chemical classes, such as phenylpyrazoles, cyclodienes, meta-diamides, and isoxazolines, with the latter two potentially binding to the transmembrane inter-subunit pocket. However, the specific amino acid residues that contribute to the high sensitivity of insect RDL receptors to these novel insecticides remain elusive. In this study, we investigated the susceptibility of seven distinct Drosophila melanogaster Rdl point mutants against four meta-diamide and isoxazoline insecticides: isocycloseram, fluxametamide, fluralaner, and broflanilide. Our findings indicate that, despite exhibiting increased sensitivity to fluralaner in vitro, the RdlI276C mutant showed resistance to isocycloseram and fluxametamide. Similarly, the double-points mutant RdlI276F+G279S also showed decreased sensitivity to the tested isoxazolines. On the other hand, the RdlG335M mutant displayed high levels of resistance to all tested insecticides. Molecular modeling and docking simulations further supported these findings, highlighting similar binding poses for these insecticides. In summary, our research provides robust in vivo evidence supporting the idea that the inter-subunit amino acids within transmembrane M1 and M3 domains form the binding site crucial for meta-diamide and isoxazoline insecticide interactions. This study highlights the complex interplay between mutations and insecticide susceptibility, paving the way for more targeted pest control strategies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ee7c2b6-59cd-4738-81bc-801c3f6bddda', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Efficacy of indoor residual spraying with broflanilide (TENEBENAL), a novel meta-diamide insecticide, against pyrethroid-resistant anopheline vectors in northern Tanzania: An experimental hut trial.', 'Janneke Snetselaar, Mark W Rowland, Baltazari J Manunda, Ezekia M Kisengwa, Graham J Small, David J Malone, Franklin W Mosha, Matthew J Kirby', 2021, 'PLoS ONE', '10.1371/journal.pone.0248026', 'https://doi.org/10.1371/journal.pone.0248026', 'https://doi.org/10.1371/journal.pone.0248026', NULL, NULL, 17, NULL, 'other', 1, 'open access (DOAJ)', 'Novel chemistry for vector control is urgently needed to counter insecticide resistance in mosquitoes. Here a new meta-diamide insecticide, broflanilide (TENEBENALTM), was evaluated in East African experimental huts in Moshi, northern Tanzania. Two consecutive experimental hut trials with broflanilide 50WP were conducted; the first evaluating the efficacy of three concentrations, 50 mg/m2, 100 mg/m2, and 200 mg/m2 using a prototype formulation, and the second trial evaluating an improved formulation. The IRS treatments were applied on both mud and concrete surfaces and efficacy was monitored over time. The mortality, blood-feeding inhibition and exiting behaviour of free-flying wild mosquitoes was compared between treatment arms. Additionally, cone assays with pyrethroid-susceptible and resistant mosquito strains were conducted in the huts to determine residual efficacy. The first trial showed a dosage-mortality response of the prototype formulation and 3-8 months of residual activity, with longer activity on concrete than mud. The second trial with an improved formulation showed prolonged residual efficacy of the 100 mg/m2 concentration to 5-6 months on mud, and mosquito mortality on the concrete surface ranged between 94-100% for the full duration of the trial. In both trials, results with free-flying, wild Anopheles arabiensis echoed the mortality trend shown in cone assays, with the highest dose inducing the highest mortality and the improved formulation showing increased mortality rates. No blood-feeding inhibition or insecticide-induced exiting effects were observed with broflanilide. Broflanilide 50WP was effective against both susceptible and pyrethroid-resistant mosquito strains, demonstrating an absence of cross resistance between broflanilide and pyrethroids. The improved formulation, which has now been branded VECTRONTM T500, resulted in a prolonged residual efficacy. These results indicate the potential of this insecticide as an addition to the arsenal of IRS products needed to maintain both control of malaria and resistance management of malaria-transmitting mosquitoes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('811284d7-8fc3-4181-b895-2e226eb49af7', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Efficacy of targeted indoor residual spraying with the pyrrole insecticide chlorfenapyr against pyrethroid-resistant Aedes aegypti', 'Che-Mendoza A, González-Olvera G, Medina-Barreiro A, Arisqueta-Chablé C, Bibiano-Marin W, Correa-Morales F, Kirstein OD, Manrique-Saide P', 2021, 'PLoS neglected tropical diseases', '10.1371/journal.pntd.0009822', 'https://doi.org/10.1371/journal.pntd.0009822', 'https://europepmc.org/articles/PMC8516273?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'BackgroundThere is an increased need to mitigate the emergence of insecticide resistance and incorporate new formulations and modes of application to control the urban vector Aedes aegypti. Most research and development of insecticide formulations for the control of Ae. aegypti has focused on their peridomestic use as truck-mounted ULV-sprays or thermal fogs despite the widespread knowledge that most resting Ae. aegypti are found indoors. A recent modification of indoor residual spraying (IRS), termed targeted IRS (TIRS) works by restricting applications to 1.5 m down to the floor and on key Ae. aegypti resting sites (under furniture). TIRS also opens the possibility of evaluating novel residual insecticide formulations currently being developed for malaria IRS.MethodsWe evaluated the residual efficacy of chlorfenapyr, formulated as Sylando 240SC, for 12 months on free-flying field-derived pyrethroid-resistant Ae. aegypti using a novel experimental house design in Merida, Mexico. On a monthly basis, 600 female Ae. aegypti were released into the houses and left indoors with access to sugar solution for 24 hours. After the exposure period, dead and alive mosquitoes were counted in houses treated with chlorfenapyr as well as untreated control houses to calculate 24-h mortality. An evaluation for these exposed cohorts of surviving mosquitoes was extended up to seven days under laboratory conditions to quantify "delayed mortality".ResultsMean acute (24-h) mortality of pyrethroid-resistant Ae. aegypti ranged 80-97% over 5 months, dropping below 30% after 7 months post-TIRS. If delayed mortality was considered (quantifying mosquito mortality up to 7 days after exposure), residual efficacy was above 90% for up to 7 months post-TIRS application. Generalized Additive Mixed Models quantified a residual efficacy of chlorfenapyr of 225 days (ca. 7.5 months).ConclusionsChlorfenapyr represents a new option for TIRS control of Ae. aegypti in urban areas, providing a highly-effective time of protection against indoor Ae. aegypti females of up to 7 months.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f9317e15-0393-4a1c-b0fe-4ea7219b4c7e', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'First Insights into the Comparative Transcriptomic Response of Field and Laboratory Aedes aegypti Strains to Partial-Mortality Concentration (<50%) Imidacloprid and Broflanilide Exposure', 'Gerardo Trujillo-Rodríguez, Mariana Lizbeth Jiménez-Martínez, José Alfonso Flores Leal, Roberto Emmanuel Huerta García, María de Lourdes Ramírez Ahuja, Iram P. Rodríguez Sanchez, Margarita L. Martínez Fierro', 2026, 'Insects', '10.3390/insects17020217', 'https://doi.org/10.3390/insects17020217', 'https://www.mdpi.com/2075-4450/17/2/217', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Insecticide resistance in Aedes aegypti (Linnaeus, 1762), the primary vector of several arboviruses, threatens vector control efficacy and motivates evaluation of current and candidate public health insecticides, such as imidacloprid and broflanilide, and their molecular impacts. Here, we used RNA sequencing (RNA-seq) to characterize the transcriptomic response to one-hour acute exposure to an operational partial-mortality concentration (Ae. aegypti strains: a field-derived, pyrethroid-resistant population from San Nicolás and a susceptible laboratory strain (New Orleans). Adults were exposed for 1 h to partial-mortality concentration (Ae. aegypti.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b1a930b-7220-4ca0-8507-ca1b430a35ed', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'G3''MTMD3 in the insect GABA receptor subunit, RDL, confers resistance to broflanilide and fluralaner', 'Zhang Y, Huang Q, Sheng C, Liu G, Zhang K, Jia Z, Tang T, Mao X', 2023, 'PLoS genetics', '10.1371/journal.pgen.1010814', 'https://doi.org/10.1371/journal.pgen.1010814', 'https://europepmc.org/articles/PMC10337980?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Meta-diamides (e.g. broflanilide) and isoxazolines (e.g. fluralaner) are novel insecticides that target the resistant to dieldrin (RDL) subunit of insect γ-aminobutyric acid receptors (GABARs). In this study, we used in silico analysis to identify residues that are critical for the interaction between RDL and these insecticides. Substitution of glycine at the third position (G3'') in the third transmembrane domain (TMD3) with methionine (G3''M TMD3), which is present in vertebrate GABARs, had the strongest effect on fluralaner binding. This was confirmed by expression of RDL from the rice stem borer, Chilo suppressalis (CsRDL) in oocytes of the African clawed frog, Xenopus laevis, where the G3''MTMD3 mutation almost abolished the antagonistic action of fluralaner. Subsequently, G3''MTMD3 was introduced into the Rdl gene of the fruit fly, Drosophila melanogaster, using the CRISPR/Cas9 system. Larvae of heterozygous lines bearing G3''MTMD3 did not show significant resistance to avermectin, fipronil, broflanilide, and fluralaner. However, larvae homozygous for G3''MTMD3 were highly resistant to broflanilide and fluralaner whilst still being sensitive to fipronil and avermectin. Also, homozygous lines showed severely impaired locomotivity and did not survive to the pupal stage, indicating a significant fitness cost associated with G3''MTMD3. Moreover, the M3''GTMD3 mutation in the mouse Mus musculus α1β2 GABAR increased sensitivity to fluralaner. Taken together, these results provide convincing in vitro and in vivo evidence for both broflanilide and fluralaner acting on the same amino acid site, as well as insights into potential mechanisms leading to target-site resistance to these insecticides. In addition, our findings could guide further modification of isoxazolines to achieve higher selectivity for the control of insect pests with minimal effects on mammals.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0dbe777b-3b82-4121-8afd-535bb7ff1269', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Tolerance of Winter Canola (Brassica napus) Cultivars to Selected Residual Herbicides', 'B. Heath Sanders', 2010, 'SHAREOK (University of Oklahoma; Oklahoma State University; Central Oklahoma University)', NULL, 'http://hdl.handle.net/11244/9362', 'http://hdl.handle.net/11244/9362', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b054e418-518b-4f7f-9744-f35ae4016fa8', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Insect Pest Control from Chemical to Biotechnological Approach: Constrains and Challenges', 'Civolani S, Bariselli M, Osti R, Bernacchia G', 2025, 'Insects', '10.3390/insects16050528', 'https://doi.org/10.3390/insects16050528', 'https://europepmc.org/articles/PMC12112121?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'The large growth in the global population requires new solutions for the control of harmful insects that compete for our food. Changing regulatory requirements and public perception, together with the continuous evolution of resistance to conventional insecticides, also require, in addition to innovative molecules with different modes of action, new non-chemical control strategies that can help maintain efficient integrated pest management programs. The last 30 years have inaugurated a new era characterised by the discovery of new mechanisms of action and new chemical families. Although European programs also promote a green deal in the crop protection sector, the existing thorough regulations slow down its spread and the adoption of new products. In light of these changes, this review will describe in more detail the dynamics of discovery and registration of new conventional insecticides and the difficulties that the agrochemical industries encounter. Subsequently, the different innovative control strategies alternative to conventional insecticides based on natural substances of different origin, entomopathogenic microorganisms, semiochemical and semiophysical compounds, and classical and augmentative biological control will be described. The advantages of these green strategies will be illustrated and also the constrains to their diffusion and commercialisation. Finally, the main biotechnological discoveries will be described, from transgenic plants to symbiotic control, classical genetic control, and, more recently, control based on insect genomic transformation or on RNAi. These new biotechnologies can revolutionise the sector despite some constrains related to the regulatory restrictions present in different countries.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('570151cd-cbca-4499-b06d-47ab539bab43', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Integrated Pest Management of Wireworms (Coleoptera: Elateridae) and the Rhizosphere in Agroecosystems', 'Nikoukar A, Rashed A', 2022, 'Insects', '10.3390/insects13090769', 'https://doi.org/10.3390/insects13090769', 'https://europepmc.org/articles/PMC9501627?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'The rhizosphere is where plant roots, physical soil, and subterranean organisms interact to contribute to soil fertility and plant growth. In agroecosystems, the nature of the ecological interactions within the rhizosphere is highly dynamic due to constant disruptions from agricultural practices. The concept of integrated pest management (IPM) was developed in order to promote an approach which is complementary to the environment and non-target organisms, including natural enemies, by reducing the sole reliance on synthetic pesticides to control pests. However, some of the implemented integrated cultural and biological control practices may impact the rhizosphere, especially when targeting subterranean pests. Wireworms, the larval stage of click beetles (Coleoptera: Elateridae), are generalist herbivores and a voracious group of pests that are difficult to control. This paper introduces some existing challenges in wireworm IPM, and discusses the potential impacts of various control methods on the rhizosphere. The awareness of the potential implications of different pest management approaches on the rhizosphere will assist in decision-making and the selection of the control tactics with the least long-term adverse effects on the rhizosphere.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('665c1c4e-25e9-4ef6-ad6e-f71c0ee10d2f', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Investigating discriminating concentrations for monitoring susceptibility to broflanilide and cross resistance to other insecticide classes in Anopheles gambiae sensu lato, using the new WHO bottle bioassay method', 'Govoetchan R, Odjo A, Todjinou D, Small G, Fongnikin A, Ngufor C', 2023, 'PloS one', '10.1371/journal.pone.0276246', 'https://doi.org/10.1371/journal.pone.0276246', 'https://europepmc.org/articles/PMC10035854?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'BackgroundBroflanilide is a new insecticide being developed for malaria vector control. As new insecticide chemistries become available, strategies to preserve the susceptibility of local malaria vectors and extend their useful life need to be considered before large scale deployment. This requires the development of appropriate testing procedures and identification of suitable discriminating concentrations for monitoring susceptibility in wild vector populations to facilitate decision making by control programmes.MethodsDose-response WHO bottle bioassays were conducted using the insecticide-susceptible Anopheles gambiae s.s. Kisumu strain to determine a discriminating concentration of broflanilide. Bioassays were performed without the adjuvant Mero® and with two concentrations of Mero® (500 ppm and 800 ppm) to investigate its impact on the discriminating concentration of the insecticide. Probit analysis was used to determine the lethal doses at 50% (LC50) and 99% (LC99) at 24-, 48- and 72-hours post-exposure. Cross-resistance to broflanilide and pyrethroids, DDT, dieldrin and carbamates, was investigated using An. gambiae s.l. Covè and An. coluzzii Akron strains. The susceptibility of wild pyrethroid-resistant mosquitoes from communities in Southern Benin to broflanilide was assessed using the estimated discriminating concentrations.ResultsBroflanilide induced a dose-dependent and delayed mortality effect. Mortality rates in bottles treated without Mero® were ConclusionWe determined discriminating concentrations for monitoring susceptibility to broflanilide in bottle bioassays, using susceptible An. gambiae vectors. Using the estimated discriminating concentrations, we showed that wild pyrethroid-resistant populations of An. gambiae s.l. from southern Benin were fully susceptible to the insecticide. Broflanilide also shows potential to be highly effective against An. gambiae s.l. vector populations that have developed resistance to other public health insecticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2d3e4e3a-e58b-4206-918e-0c21be8b9f86', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Laboratory and experimental hut trial evaluation of VECTRON ™ T500 for indoor residual spraying (IRS) against insecticide resistant malaria vectors in Burkina Faso', 'Bayili K, Ki HD, Bayili B, Sow B, Ouattara A, Small G, Hien AS, Dabire RK', 2022, 'Gates open research', '10.12688/gatesopenres.13578.2', 'https://doi.org/10.12688/gatesopenres.13578.2', 'https://europepmc.org/articles/PMC9326088?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Background: Malaria cases in some areas could be attributed to vector resistant to the insecticide. World Health Organization recommended insecticides for vector control are limited in number. It is essential to find rotational partners for existing Indoor Residual Spraying (IRS) products. VECTRON ™ T500 is a novel insecticide with broflanilide as active ingredient. It has a mode of action on mosquitoes completely different to usually used. The aim of this study was to determine the optimum effective dose and efficacy of VECTRON TM T500 against susceptible and resistant strains of Anopheles in Burkina Faso. Methods: VECTRON™T500 was sprayed at 50, 100 and 200 mg/m² doses onto mud and concrete blocks using Potter Spray Tower. The residual activity of broflanilide was assessed through cone bioassays 1 week and then monthly up to 14 months post spraying. Its efficacy was evaluated at 100 and 150 mg/m² against wild free-flying mosquitoes in experimental huts on both substrates. Actellic 300CS was applied at 1000 mg/m² as reference product. Cone assays were conducted monthly, using susceptible and resistant mosquito strains. Results: In the laboratory, VECTRON ™ T500 showed residual efficacy (≥80% mortality) on An. gambiae Kisumu up to 12 and 14 months, respectively, on concrete and mud blocks. Similar results were found with 100 and 200 mg/m² using An. coluzzii pyrethroid resistant strain. In experimental huts, a total of 19,552 An. gambiae s.l. were collected. Deterrence, blood-feeding inhibition and exophily with VECTRON™ treated huts were very low. At 100 and 150 mg/m², mortality of wild An. gambiae s.l. ranged between 55% and 73%. Monthly cone bioassay mortality remained >80% up to 9 months. Conclusions: VECTRON™ T500 shows great potential as IRS formulation for malaria vector control. It can be added to the arsenal of IRS products for use in rotations to control malaria and manage mosquito insecticide resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('42d2e451-274f-4cd1-b2e6-88ffbec7933d', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Effect of Row Spacing and Seeding Rate on Russian Thistle (Salsola tragus) in Spring Barley and Spring Wheat', 'Barroso J, Genna NG', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10010126', 'https://doi.org/10.3390/plants10010126', 'https://europepmc.org/articles/PMC7826523?pdf=render', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc by', 'Russian thistle (Salsola tragus L.) is a persistent post-harvest issue in the Pacific Northwest (PNW). Farmers need more integrated management strategies to control it. Russian thistle emergence, mortality, plant biomass, seed production, and crop yield were evaluated in spring wheat and spring barley planted in 18- or 36-cm row spacing and seeded at 73 or 140 kg ha-1 in Pendleton and Moro, Oregon, during 2018 and 2019. Russian thistle emergence was lower and mortality was higher in spring barley than in spring wheat. However, little to no effect of row spacing or seeding rate was observed on Russian thistle emergence or mortality. Russian thistle seed production and plant biomass followed crop productivity; higher crop yield produced higher Russian thistle biomass and seed production and lower crop yield produced lower weed biomass and seed production. Crop yield with Russian thistle pressure was improved in 2018 with 18-cm rows or by seeding at 140 kg ha-1 while no effect was observed in 2019. Increasing seeding rates or planting spring crops in narrow rows may be effective at increasing yield in low rainfall years of the PNW, such as in 2018. No effect may be observed in years with higher rainfall than normal, such as in 2019.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8f1c5d2-7835-4232-af79-b9f32eef54ef', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Laboratory efficacy of selected synthetic insecticides against second instar invasive fall armyworm, Spodoptera frugiperda (Lepidoptera: Noctuidae) larvae', 'Idrees A, Qadir ZA, Afzal A, Ranran Q, Li J', 2022, 'PloS one', '10.1371/journal.pone.0265265', 'https://doi.org/10.1371/journal.pone.0265265', 'https://europepmc.org/articles/PMC9109910?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Maize is the most essential crop of China and its productivity has been recently endangered by the fall armyworm (FAW), Spodoptera frugiperda. Chemical pesticides are one of the most important strategies for managing FAW on a short-term basis. The seven synthetic insecticides including novel and conventional belong to four chemical group, spinetoram and spinosad (spinosyns), lambda-cyhalothrin, cypermethrin and bifenthrin (pyrethroids), abamectin (avermectins), broflinilide (diamides), were assessed for their efficiency in causing mortality to second instar S. frugiperda larvae at 24, 48 and 72 h post-treatment at five different serial concentrations (10 to 0.625 mg liter-1). The second instar S. frugiperda larvae were susceptible to the tested synthetic insecticides, however, the toxicity index of synthetic insecticides was estimated based on lethal concentration 50 (LC50), while, LC50 was calculated from the data of larval mortality. The broflanilide and abamectin proved to be the most toxic having the highest toxicity index of 100 and 78.29%, respectively, followed by cypermethrin and bifenthrin were showed toxicity index of 75.47 and 66.89%, respectively. The LC50 values were 0.606 and 0.774 mg liter-1 for broflanilide and abamectin, respectively, followed by cypermethrin and bifenthrin were showed LC50 values of 0.803 and 0.906 mg liter-1 at 72 h post-treatment. Rest of the other synthetic insecticides were showed moderate toxicity index of 42.11 to 62.09%, based on LC50 values were 1.439 to 0.976 mg liter-1 at 72 h post-treatment. The efficiency of synthetic insecticides was increased by increasing concentration level and exposure time. The screened synthetic insecticides among seven insecticides perhaps, provide basis for the development of novel insecticides for controlling S. frugiperda population after further research to evaluate and validate the laboratory results in the field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ec1f6ec-0c85-4f11-9c16-d2aa5d670fc8', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Lethal, Sublethal, and Offspring Effects of Fluralaner and Dinotefuran on Three Species of Bactrocera Fruit Flies', 'Li D, Cai X, Qi Y, Lu Y, Li X', 2024, 'Insects', '10.3390/insects15060440', 'https://doi.org/10.3390/insects15060440', 'https://europepmc.org/articles/PMC11203614?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Fruit flies cause substantial economic damage, and their management relies primarily on chemical insecticides. However, pesticide resistance has been reported in several fruit fly species, the mitigation of which is crucial to enhancing fruit fly control. Here, we assess the toxicity of a novel insecticide (fluralaner) and a common insecticide (dinotefuran) against three fruit fly species, Bactrocera dorsalis (Hendel), Bactrocera cucurbitae (Coquillett), and Bactrocera tau (Walker). Both pesticides exhibit robust lethal and sublethal effects against all three fruit fly species, with fluralaner being more potent. Fluralaner and dinotefuran suppress the reproductive capacities and survival rates of fruit flies. However, at the 50% lethal concentration, fluralaner stimulates the reproductive capacity of B. dorsalis and the survival rate of B. tau. Fluralaner also causes significant transgenerational effects, impacting the offspring hatching rate of B. cucurbitae and B. tau and reducing the proportion of female offspring. Thus, both pesticides exhibit high potential for controlling fruit flies. However, their application should be tailored according to species variations and the diverse effects they may induce. Collectively, the findings of this study outline the sublethal effects of two insecticides against fruit flies, helping to optimize their application to ensure the effective management of insecticide resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e2b54311-b0f3-4a8f-a0f3-7c9437638dfb', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Long-lasting residual efficacy of a new indoor residual spraying product, VECTRON™ T500 (broflanilide), against pyrethroid-resistant malaria vectors and its acceptance in a community trial in Burkina Faso', 'Hien AS, Bayili K, Maiga S, Oumbouke W, Birba J, Soma DD, Ouattara AY, Karama DO', 2024, 'Parasites & vectors', '10.1186/s13071-024-06577-y', 'https://doi.org/10.1186/s13071-024-06577-y', 'https://europepmc.org/articles/PMC11585240?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'BackgroundThe WHO Global Malaria Programme advocates for a comprehensive, strategic approach to managing insecticide resistance, highlighting the importance of using multiple insecticides with different modes of action through rotations and combinations. To slow the spread of resistance, it is essential to develop and evaluate new formulations that feature unique modes of action and extended residual effects. Addressing this need, Mitsui Chemicals Crop & Life Solutions, Inc., developed VECTRON™ T500, a new indoor residual spraying (IRS) formulation using broflanilide, applied at a dosage of 100 mg AI/m2. This formulation was tested in a Phase III community trial, alongside Actellic® 300CS, a commonly used IRS product containing pirimiphos-methyl, applied at the recommended dosage of 1000 mg AI/m2.MethodsMonthly WHO wall cone bioassays were performed to assess the efficacy of the interventions using three mosquito strains: the laboratory-bred, insecticide-susceptible Anopheles gambiae s.s. Kisumu strain, the insecticide-resistant Anopheles coluzzii VKPer strain, and wild Anopheles gambiae s.l. mosquitoes from the Vallée du Kou, where the study was conducted. Vector surveillance was carried out to compare the results between sites treated with VECTRON™ T500, Actellic® 300CS, and an untreated control site. In addition, any reported adverse effects were closely monitored to evaluate the community''s acceptance of VECTRON™ T500.ResultsVECTRON™ T500 consistently achieved 100% mortality across all wall types for both susceptible and resistant mosquito strains over the 12-month period. In comparison, Actellic® 300CS induced ® 300CS (VK1) and VECTRON™ T500 (VK3), a statistically significant difference was noted after a 72-h holding period compared to the control site (RR = 0.51, CI95% = [0.31-0.6], P = 0.0026). Additionally, no adverse events were reported in households sprayed with VECTRON™ T500.ConclusionsThe residual efficacy of VECTRON™ T500 extended for 12 months post-spraying, effectively covering the full malaria transmission season while maintaining high mortality rates in pyrethroid-resistant malaria vectors. VECTRON™ T500 demonstrated non-inferiority in performance compared to Actellic® 300CS, the standard reference product. This new IRS formulation has the potential to play a crucial role in managing insecticide resistance by being integrated into a rotational strategy alongside other IRS products containing insecticides with different modes of action.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ad3fd5b-b02e-4963-acc1-734f59ab58aa', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Mechanisms of insecticide resistance in mosquitoes and their implications for disease control', 'Rakesh Padhan, Rakesh Padhan, Jatin Kumar, Jatin Kumar, Bharti Goyal, Bharti Goyal, Ram Das, Ram Das', 2026, 'Frontiers in Malaria', '10.3389/fmala.2026.1890327', 'https://doi.org/10.3389/fmala.2026.1890327', 'https://www.frontiersin.org/articles/10.3389/fmala.2026.1890327/full', NULL, NULL, 26, NULL, 'other', 1, 'open access (DOAJ)', 'Insecticide resistance in mosquitoes has created a severe bottleneck, undermining global public health initiatives targeting vector-borne pathogens such as Plasmodium, dengue, and Zika viruses. Using a comprehensive narrative review methodology, this article maps the shifting evolutionary landscapes of vector control across four primary, universally recognized resistance mechanisms: target-site insensitivity (kdr, ace-1, and Rdl pore transformations), metabolic detoxification (cytochrome P450s, carboxylesterases, and glutathione S-transferases), cuticular thickening, and behavioral avoidance. Beyond these classical frameworks, this review addresses important contemporary discoveries, highlighting the functional role of the commensal midgut microbiota in the escalation of phenotypic pyrethroid resistance and underscoring novel extracellular metabolic markers such as the CSDIR protein. To counteract these adaptation networks, public health programs are undergoing a paradigm shift away from traditional neurotoxic monotherapies. The review touches upon the operational efficacy of next-generation, World Health Organization-prequalified interventions designed to circumvent legacy cross-resistance, focusing on neonicotinoids (clothianidin), pyrroles (chlorfenapyr), novel meta-diamides (broflanilide), and biorational insect growth regulators (pyriproxyfen). Finally, this review contextualizes these dynamics within the geographically and epidemiologically diverse landscape of India. The review points to specific Indian evidence, including the mapped multi-insecticide resistance profiles of primary rural (Anopheles culicifacies) and urban (Anopheles stephensi) vectors, PCR-based target-site genotyping (L1014F/S and V1010L alleles) from the national sentinel networks of the NCVBDC and ICMR-NIMR, and localized evaluations of novel allosteric chemistries. By bridging India’s field surveillance data with international resistance management frameworks, this review outlines integrated strategies to delay the selection of multi-resistant phenotypes and safeguard sustainable vector elimination targets worldwide.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ae69fe32-bbfe-42e1-9ba0-0602d32f897d', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Multi-centre discriminating concentration determination of broflanilide and potential for cross-resistance to other public health insecticides in Anopheles vector populations', 'Portwood NM, Shayo MF, Tungu PK, Mbewe NJ, Mlay G, Small G, Snetselaar J, Kristan M', 2022, 'Scientific reports', '10.1038/s41598-022-26990-6', 'https://doi.org/10.1038/s41598-022-26990-6', 'https://europepmc.org/articles/PMC9792579?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Novel insecticides are urgently needed to control insecticide-resistant populations of Anopheles malaria vectors. Broflanilide acts as a non-competitive antagonist of the gamma-aminobutyric acid receptor and has shown prolonged effectiveness as an indoor residual spraying product (VECTRON T500) in experimental hut trials against pyrethroid-resistant vector populations. This multi-centre study expanded upon initial discriminating concentration testing of broflanilide, using six Anopheles insectary colonies (An. gambiae Kisumu KCMUCo, An. gambiae Kisumu NIMR, An. arabiensis KGB, An. arabiensis SENN, An. coluzzii N''Gousso and An. stephensi SK), representing major malaria vector species, to facilitate prospective susceptibility monitoring of this new insecticide; and investigated the potential for cross-resistance to broflanilide via the A296S mutation associated with dieldrin resistance (rdl). Across all vector species tested, the discriminating concentration for broflanilide ranged between LC99 × 2 = 1.126-54.00 μg/ml or LC95 × 3 = 0.7437-17.82 μg/ml. Lower concentrations of broflanilide were required to induce complete mortality of An. arabiensis SENN (dieldrin-resistant), compared to its susceptible counterpart, An. arabiensis KGB, and there was no association between the presence of the rdl mechanism of resistance and survival in broflanilide bioassays, demonstrating a lack of cross-resistance to broflanilide. Study findings provide a benchmark for broflanilide susceptibility monitoring as part of ongoing VECTRON T500 community trials in Tanzania and Benin.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('457a101e-0e62-49d0-9a51-3a770c85c89e', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Multiple insecticide resistance in Anopheles funestus from Mopeia, Central Mozambique', 'Kiuru C, Constantino L, Cole G, Karisa J, Wanjiku C, Okoko M, Candrinho B, Saute F', 2025, 'Malaria journal', '10.1186/s12936-025-05321-w', 'https://doi.org/10.1186/s12936-025-05321-w', 'https://europepmc.org/articles/PMC11907927?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundThe main malaria vector control methods implemented in Mozambique are insecticide-treated nets (ITN''s) and indoor residual spraying (IRS). These insecticide-based interventions are currently threatened by the rapidly spreading insecticide resistance in several major malaria vectors. Monitoring of insecticide resistance is necessary to inform the selection of insecticides by control programmes. This study describes the insecticide resistance profiles of the main malaria vector, Anopheles funestus sensu lato. in Mopeia district, a malaria holoendemic area of the Zambezia province of Mozambique.MethodsAnopheles adults and larvae were collected from 15 sentinel sites across the district between October 2021 and September 2022. Wild-caught, unfed female adults were collected using CDC-light traps and pooled over three days before exposure to the test insecticide. For mosquitoes collected as larvae, F0 adults aged 3-5 days post-emergence were used for insecticide susceptibility testing. Resistance to bendiocarb, DDT, deltamethrin and pirimiphos-methyl was evaluated using the standard WHO tube bioassay. The mechanism of resistance was probed using the PBO (piperonyl butoxide) synergistic bioassay. The presence and frequency of different genetic mutations associated with insecticide resistance was assessed using polymerase chain reaction, including A296S-Rdl, L119F-GSTe2 and 6.5 kb SV (structural variation) insertion.ResultsA total of 1349 female Anopheles mosquitoes (controls included) were used for susceptibility tests with discriminating insecticide concentrations. Phenotypic resistance to bendiocarb, DDT, deltamethrin and pirimiphos-methyl was observed, with 37%, 79%, 14% and 67% mortality rate respectively. Pre-exposure to PBO partially restored susceptibility to deltamethrin to a mortality rate of 80%. The frequency of the insecticide resistance mutations was 0.49, 0.05 and 0.92, for A296S-Rdl, L119F-GSTe2 and 6.5 kb SV insertion, respectively.ConclusionMalaria vectors in Mopeia exhibit resistance to all four major public health insecticide classes: pyrethroids, organophosphates, organochlorides and carbamates. This highlights the urgent need to adopt new insecticide classes for vector control interventions. The partial restoration of susceptibility by PBO suggests resistance is being driven by various mechanisms including the involvement of metabolic resistance through cytochrome P450 monooxygenase enzymes and glutathione S-transferases.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8f5f4d49-a44d-48c0-9413-982ec57d35e5', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Functional Characterization of Cytochromes P450 Linked to Herbicide Detoxification and Selectivity in Winter Wheat and the Problem Competing Weed Blackgrass', 'Goldberg-Cavalleri A, Franco-Ortega S, Brown S, Walker A, Rougemont B, Sinclair J, Brazier-Hicks M, Dale R', 2025, 'ACS omega', '10.1021/acsomega.4c11069', 'https://doi.org/10.1021/acsomega.4c11069', 'https://europepmc.org/articles/PMC11966285?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The selective chemical control of wild grasses in wheat is primarily determined by the relative rates of herbicide metabolism, with the superfamily of cytochromes P450 (CYPs) playing a major role in catalyzing phase 1 detoxification reactions. This selectivity is enhanced by herbicide safeners, which induce CYP expression in cereals, or challenged by the evolution of nontarget site resistance (NTSR) in weeds such as blackgrass. Using transcriptomics, proteomics, and functional expression in recombinant yeast, CYPs linked to safener treatment and NTSR have been characterized in wheat and blackgrass. Safener treatment resulted in the induction of 13 families of CYPs in wheat and 5 in blackgrass, with CYP71, CYP72, CYP76, and CYP81 members active toward selective herbicides in the crop. Based on their expression and functional activities, three inducible TaCYP81s were shown to have major roles in safening in wheat. In contrast, a single AmCYP81 that was enhanced by NTSR, but not by safening, was found to dominate herbicide detoxification in blackgrass.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('07cadc05-76bc-4475-9562-a04b725674e5', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Parallel Evolution in Mosquito Vectors-A Duplicated Esterase Locus is Associated With Resistance to Pirimiphos-methyl in Anopheles gambiae', 'Nagi SC, Lucas ER, Egyir-Yawson A, Essandoh J, Dadzie S, Chabi J, Djogbénou LS, Medjigbodo AA', 2024, 'Molecular biology and evolution', '10.1093/molbev/msae140', 'https://doi.org/10.1093/molbev/msae140', 'https://europepmc.org/articles/PMC11267716?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'The primary control methods for the African malaria mosquito, Anopheles gambiae, are based on insecticidal interventions. Emerging resistance to these compounds is therefore of major concern to malaria control programs. The organophosphate (OP), pirimiphos-methyl, is a relatively new chemical in the vector control armory but is now widely used in indoor-residual spray campaigns. While generally effective, phenotypic resistance has developed in some areas in malaria vectors. Here, we used a population genomic approach to identify novel mechanisms of resistance to pirimiphos-methyl in A. gambiae s.l mosquitoes. In multiple populations, we found large and repeated signals of selection at a locus containing a cluster of detoxification enzymes, some of whose orthologs are known to confer resistance to OPs in Culex pipiens. Close examination revealed a pair of alpha-esterases, Coeae1f and Coeae2f, and a complex and diverse pattern of haplotypes under selection in A. gambiae, A. coluzzii and A. arabiensis. As in C. pipiens, copy number variants have arisen at this locus. We used diplotype clustering to examine whether these signals arise from parallel evolution or adaptive introgression. Using whole-genome sequenced phenotyped samples, we found that in West Africa, a copy number variant in A. gambiae is associated with resistance to pirimiphos-methyl. Overall, we demonstrate a striking example of contemporary parallel evolution which has important implications for malaria control programs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac52d5d4-1b53-438b-b9b1-e9791b0da18d', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Relationship between insecticide resistance profiles in Anopheles gambiae sensu lato and agricultural practices in Côte d''Ivoire', 'Kouadio FA, Wipf NC, Nygble AS, Fodjo BK, Sadia CG, Vontas J, Mavridis K, Müller P', 2023, 'Parasites & vectors', '10.1186/s13071-023-05876-0', 'https://doi.org/10.1186/s13071-023-05876-0', 'https://europepmc.org/articles/PMC10410919?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'BackgroundInsecticide-based malaria vector control is increasingly undermined due to the development of insecticide resistance in mosquitoes. Insecticide resistance may partially be related to the use of pesticides in agriculture, while the level and mechanisms of resistance might differ between agricultural practices. The current study aimed to assess whether phenotypic insecticide resistance and associated molecular resistance mechanisms in Anopheles gambiae sensu lato differ between agricultural practices.MethodsWe collected An. gambiae s.l. larvae in six sites with three different agricultural practices, including rice, vegetable and cocoa cultivation. We then exposed the emerging adult females to discriminating concentrations of bendiocarb (0.1%), deltamethrin (0.05%), DDT (4%) and malathion (5%) using the standard World Health Organization insecticide susceptibility test. To investigate underlying molecular mechanisms of resistance, we used multiplex TaqMan qPCR assays. We determined the frequency of target-site mutations, including Vgsc-L995F/S and Vgsc-N1570Y, and Ace1-G280S. In addition, we measured the expression levels of genes previously associated with insecticide resistance in An. gambiae s.l., including the cytochrome P450-dependent monooxygenases CYP4G16, CYP6M2, CYP6P1, CYP6P3, CYP6P4, CYP6Z1 and CYP9K1, and the glutathione S-transferase GSTe2.ResultsThe An. gambiae s.l. populations from all six agricultural sites were resistant to bendiocarb, deltamethrin and DDT, while the populations from the two vegetable cultivation sites were additionally resistant to malathion. Most tested mosquitoes carried at least one mutant Vgsc-L995F allele that is associated with pyrethroid and DDT resistance. In the cocoa cultivation sites, we observed the highest 995F frequencies (80-87%), including a majority of homozygous mutants and several in co-occurrence with the Vgsc-N1570Y mutation. We detected the Ace1 mutation most frequently in vegetable-growing sites (51-60%), at a moderate frequency in rice (20-22%) and rarely in cocoa-growing sites (3-4%). In contrast, CYP6M2, CYP6P3, CYP6P4, CYP6Z1 and CYP9K1, previously associated with metabolic insecticide resistance, showed the highest expression levels in the populations from rice-growing sites compared to the susceptible Kisumu reference strain.ConclusionIn our study, we observed intriguing associations between the type of agricultural practices and certain insecticide resistance profiles in the malaria vector An. gambiae s.l. which might arise from the use of pesticides deployed for protecting crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e2a2dc4b-429c-4a7f-b57b-578b0693e130', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Review on the impacts of indoor vector control on domiciliary pests: good intentions challenged by harsh realities', 'Hayes CC, Schal C', 2024, 'Proceedings. Biological sciences', '10.1098/rspb.2024.0609', 'https://doi.org/10.1098/rspb.2024.0609', 'https://europepmc.org/articles/PMC11265923?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Arthropod vectored diseases have been a major impediment to societal advancements globally. Strategies to mitigate transmission of these diseases include preventative care (e.g. vaccination), primary treatment and most notably, the suppression of vectors in both indoor and outdoor spaces. The outcomes of indoor vector control (IVC) strategies, such as long-lasting insecticide-treated nets (LLINs) and indoor residual sprays (IRSs), are heavily influenced by individual and community-level perceptions and acceptance. These perceptions, and therefore product acceptance, are largely influenced by the successful suppression of non-target nuisance pests such as bed bugs and cockroaches. Adoption and consistent use of LLINs and IRS is responsible for immense reductions in the prevalence and incidence of malaria. However, recent observations suggest that failed control of indoor pests, leading to product distrust and abandonment, may threaten vector control programme success and further derail already slowed progress towards malaria elimination. We review the evidence of the relationship between IVC and nuisance pests and discuss the dearth of research on this relationship. We make the case that the ancillary control of indoor nuisance and public health pests needs to be considered in the development and implementation of new technologies for malaria elimination.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc54e99d-cdc3-4724-a2ba-8cc79255ffdf', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Sublethal Broflanilide Exposure Induces Developmental and Reproductive Costs and Early Detoxification Responses in Tuta absoluta', 'Binbin Dong, Xiaoqian Yao, Yalan Sun, Chunmeng Huang', 2026, 'Horticulturae', '10.3390/horticulturae12030381', 'https://doi.org/10.3390/horticulturae12030381', 'https://www.mdpi.com/2311-7524/12/3/381', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The tomato leaf miner, Tuta absoluta (Meyrick) (Lepidoptera: Gelechiidae), poses a significant threat to global tomato production. However, environmentally sustainable management strategies for this pest, as well as its mechanisms of insecticide resistance, remain insufficiently understood. Broflanilide, a novel meta-diamide compound, can bind specifically to the transmembrane domain of the RDL subunit, causing prolonged opening of the chloride channel, disruption of neurotransmission, and ultimately insect paralysis and death. This study employed the leaf immersion method to conduct bioassays on the second-instar larvae of T. absoluta to evaluate physiological responses to sublethal concentrations of the novel amide insecticide broflanilide. Subsequently, high-throughput transcriptome sequencing was performed to investigate changes in gene expression and metabolic pathways. Bioassay results determined the larval sublethal concentrations of broflanilide to be 0.136 mg/L (LC10) and 0.210 mg/L (LC30). Sublethal exposure significantly prolonged the larval period, reduced pupal weight, and inhibited fecundity of female adults. Transcriptomic and qPCR analyses revealed that, compared with the control (CK), expression of the vitellogenin gene Vg decreased by 15.99% and 30.27% under LC10 and LC30 treatments, respectively, while its receptor gene VgR decreased by 11.56% and 24.49%. Similarly, expression of chitin synthase genes chs1 and chs2 declined by 13.56% and 30.17% (chs1), and 7.85% and 19.45% (chs2), respectively. Gene expression analysis elucidated how sublethal insecticides treatment impact larval development and fecundity. Furthermore, the study revealed upregulation of cytochrome P450-mediated detoxification pathways and Toll/Imd immune signaling pathways under broflanilide stress, indicating activation of a coordinated defense response in T. absoluta. Sublethal broflanilide exposure modulated larval gene expression to balance growth, development, and stress adaptation. Such exposure exerts selective pressure on susceptible populations, potentially driving adaptive shifts in detoxification metabolism and contributing to the development of field resistance. These findings advance our understanding of the sublethal effects of novel insecticides and provide valuable insights for insecticide deployment strategies and resistance management.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('97b87c21-5720-4548-ae9f-fb8054f84195', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Sublethal effects and reproductive hormesis of emamectin benzoate on Plutella xylostella', 'Liu KX, Guo Y, Zhang CX, Xue CB', 2022, 'Frontiers in physiology', '10.3389/fphys.2022.1025959', 'https://doi.org/10.3389/fphys.2022.1025959', 'https://europepmc.org/articles/PMC9627195?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'The diamondback moth (DBM), Plutella xylostella L., is an important pest of cruciferous vegetables, and population control mainly depends on chemical pesticides. Emamectin benzoate is a highly effective insecticide used for controlling DBM. However, it is unknown how the sublethal effects of low concentration residues of emamectin benzoate on DBM. So the population development sublethal effects of emamectin benzoate, at LC5, LC10, and LC20 with concentrations of 0.014 mg/L, 0.024 mg/L and 0.047 mg/L, respectively, on adult DBM and their progeny were investigated in this study. The pupal weight, pupal period, female fecundity, and vitellin content of the F0 DBM generation increased significantly compared to the control. And the single female oviposition number of DBM was increased by 20.21% with LC20 treatment. The pupation rate, adult longevity and ovariole length of the treatment groups decreased significantly. The fecundity of DBM in the treatment groups increased, and this increased the population by a presumptive 13.84%. Treatment also led to the shortening of ovarioles and the reduction of egg hatching, and increased pupal weight in the F1 generation. We concluded that the effects of sublethal/low concentration emamectin benzoate on the different life stages of DBM were variable, and the reproductive hormesis on DBM adults were attractive findings.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8998ef28-67b0-404b-9496-7899b4b589a2', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Tenebenal: a meta-diamide with potential for use as a novel mode of action insecticide for public health', 'Rosemary Susan Lees, Pauline Ambrose, Jessica Williams, John Morgan, Giorgio Praulins, Victoria A. Ingham, Chris T. Williams, Rhiannon Agnes Ellis Logan', 2020, 'Malaria Journal', '10.1186/s12936-020-03466-4', 'https://doi.org/10.1186/s12936-020-03466-4', 'http://link.springer.com/article/10.1186/s12936-020-03466-4', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background There is an urgent need for insecticides with novel modes of action against mosquito vectors. Broflanilide is a meta-diamide, discovered and named Tenebenal™ by Mitsui Chemicals Agro, Inc., which has been identified as a candidate insecticide for use in public health products. Methods To evaluate its potential for use in public health, Tenebenal™ was screened using an array of methodologies against Anopheles and Aedes strains. Initially it was assessed for intrinsic efficacy by topical application. Tarsal contact bioassays were then conducted to further investigate its efficacy, as well as its potency and speed of action. The potential of the compound for use in indoor residual spray (IRS) applications was investigated by testing the residual efficacy of a prototype IRS formulation on a range of typical house building substrates, and its potential for use in long-lasting insecticidal nets (LLIN) was tested using dipped net samples. Finally, bioassays using well-characterized insecticide-resistant mosquito strains and an in silico screen for mutations in the insecticide’s target site were performed to assess the risk of cross-resistance to Tenebenal™. Results Tenebenal™ was effective as a tarsal contact insecticide against both Aedes and Anopheles mosquitoes, with no apparent cross-resistance caused by mechanisms that have evolved to insecticides currently used in vector control. Topical application showed potent intrinsic activity against a Kisumu reference strain and an insecticide-resistant strain of Anopheles gambiae. Applied to filter paper in a WHO tube bioassay, Tenebenal™ was effective in killing 100% of susceptible and resistant strains of An. gambiae and Aedes aegypti at a concentration of 0.01%. The discriminating concentration of 11.91 µg/bottle shows it to be very potent relative to chemistries previously identified as having potential for vector control. Mortality occurs within 24 h of exposure, 80% of this mortality occurring within the first 10 h, a speed of kill somewhat slower than seen with pyrethroids due to the mode of action. The potential of Tenebenal™ for development in LLIN and IRS products was demonstrated. At least 12 months residual efficacy of a prototype IRS formulation applied at concentrations up to 200 mg of AI/sq m was demonstrated on a range of representative wall substrates, and up to 18 months on more inert substrates. A dipped net with an application rate of around 2 g/sq m Tenebenal™ killed 100% of exposed mosquitoes within a 3-min exposure in a WHO cone test. Conclusions Tenebenal™ is a potent insecticide against adult Aedes and Anopheles mosquitoes, including strains resistant to classes of insecticide currently used in vector control. The compound has shown great potential in laboratory assessment and warrants further investigation into development for the control of pyrethroid-resistant mosquitoes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a48d7faf-c4f1-4581-8576-dd71b30b06d4', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Toxicity and Sublethal Effects of Diamide Insecticides on Key Non-Target Natural Predators, the Larvae of Coccinella septempunctata L. (Coleoptera: Coccinellidae)', 'Cong Y, Chen J, Xie Y, Wang Y, Cheng C', 2023, 'Toxics', '10.3390/toxics11030270', 'https://doi.org/10.3390/toxics11030270', 'https://europepmc.org/articles/PMC10057643?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Coccinella septempunctata (ladybird) is an extremely important natural predator that feeds on aphids. An assessment of the toxicity of pesticides on environmental organisms is an essential component of Integrated Pest Management (IPM) strategies. This study evaluated diamide insecticides'' toxicity at lethal and 30% lethal doses (LR30) against C. septempunctata larvae. The pre-imaginal median lethal doses (LR50) of chlorantraniliprole 10% SC, tetrachlorantraniliprole 10% SC, and broflanilide 10% SC were calculated to be 42.078, 289.516, and 0.0943 g active ingredient (a.i.)/ha, respectively. The mortality tests demonstrated that chlorantraniliprole and tetrachlorantraniliprole are comparatively less toxic to C. septempunctata than broflanilide, which were detected to be highly toxic to C. septempunctata. The mortality rates of the groups treated with the three diamide insecticides tended to stabilize after 96 h, extending to the pre-imaginal stage. Furthermore, when compared to broflanilide, which had a much higher potential risk, the hazard quotient (HQ) values indicated that chlorantraniliprole and tetrachlorantraniliprole have a lower risk potential for C. septempunctata in farmland and off farmland. The LR30 dose induces abnormalities in the development phase 4th-instar larvae weight, pupal weight, and adult weight of treated C. septempunctata. The study emphasizes the importance of assessing the adverse effects of diamide insecticides on natural predator species that serve as biological control agents in agricultural IPM strategies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6bc77d7f-51a8-4986-8816-755ffd3f390e', '75c74ce5-5544-498b-9e65-c35e980c0d39', 'Vegetable oil-based surfactants are adjuvants that enhance the efficacy of neonicotinoid insecticides and can bias susceptibility testing in adult mosquitoes', 'Ashu FA, Fouet C, Ambadiang MM, Penlap-Beng V, Kamdem C', 2023, 'PLoS neglected tropical diseases', '10.1371/journal.pntd.0011737', 'https://doi.org/10.1371/journal.pntd.0011737', 'https://europepmc.org/articles/PMC10656025?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'BackgroundThe standard operating procedure for testing the susceptibility of adult mosquitoes to neonicotinoid or butenolide insecticides recommends using a vegetable oil ester (Mero) as a surfactant. However, there is growing evidence that this adjuvant contains surfactants that can enhance insecticide activity, mask resistance and bias the bioassay.Methodology/principal findingsUsing standard bioassays, we tested the effects of commercial formulations of vegetable oil-based surfactants similar to Mero on the activity of a spectrum of active ingredients including four neonicotinoids (acetamiprid, clothianidin, imidacloprid and thiamethoxam) and two pyrethroids (permethrin and deltamethrin). We found that three different brands of linseed oil soap used as cleaning products drastically enhanced neonicotinoid activity in Anopheles mosquitoes. At 1% (v/v), the surfactant reduced the median lethal concentration, LC50, of clothianidin more than 10-fold both in susceptible and in resistant populations of Anopheles gambiae. At 1% or 0.5% (v/v), linseed oil soap restored the susceptibility of adult mosquitoes fully to clothianidin, thiamethoxam and imidacloprid and partially to acetamiprid. By contrast, adding soap to the active ingredient did not significantly affect the level of resistance to permethrin or deltamethrin suggesting that vegetable oil-based surfactants specifically enhance the potency of some classes of insecticides.Conclusions/significanceOur findings indicate that surfactants are not inert ingredients, and their use in susceptibility testing may jeopardize the ability to detect resistance. Further research is needed to evaluate the potential, the limitations and the challenges of using some surfactants as adjuvants to enhance the potency of some chemicals applied in mosquito control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('92b2b009-ccbf-41ef-889f-005764e08100', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'A retrospective analysis of honey bee (Apis mellifera) pesticide toxicity data', 'Farruggia FT, Garber K, Hartless C, Jones K, Kyle L, Mastrota N, Milone JP, Sankula S', 2022, 'PloS one', '10.1371/journal.pone.0265962', 'https://doi.org/10.1371/journal.pone.0265962', 'https://europepmc.org/articles/PMC8989193?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc0', 'Current USEPA ecological risk assessments for pesticide registration include a determination of potential risks to bees. Toxicity data are submitted to support these assessments and the USEPA maintains a large database containing acute and chronic toxicity data on adult and larval honey bees (Apis mellifera), which USEPA considers a surrogate for Apis and non-Apis bees. We compared these toxicity data to explore possible trends. This analysis indicated a significant correlation between acute contact and oral median lethal dose (LD50) values for adult honey bees (ρ = 0.74, p <0.0001). Using default EPA modeling assumptions, where exposure for an individual bee is roughly 12x lower through contact than through ingestion, the analysis indicates that the oral LD50 is similarly if not more protective of the contact LD50 for the majority of pesticides and modes of action evaluated. The analysis also provided evidence that compounds with a lower acute toxicity for adults through contact and oral exposure pathways may still be acutely toxic for larvae. The acute toxicity of herbicides and fungicides was higher for larvae relative to oral and contact toxicity for adult honey bees for the same compounds and the no observed adverse effect level (NOAEL) from chronic toxicity studies were lower for larvae relative to adults, indicating increased sensitivity of larvae. When comparing 8-day LD50 values between single dose larval acute studies to those derived from repeat dose 22-day larval chronic toxicity studies, the LD50 values derived from chronic studies were significantly lower than those from acute toxicity tests (Z = -37, p = 0.03).', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('59b11c5b-b31e-4ce2-a27d-9ac357111f5a', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'A Review of the Unintentional Release of Feral Genetically Modified Rapeseed into the Environment', 'Sohn SI, Pandian S, Oh YJ, Kang HJ, Ryu TH, Cho WS, Shin EK, Shin KS', 2021, 'Biology', '10.3390/biology10121264', 'https://doi.org/10.3390/biology10121264', 'https://europepmc.org/articles/PMC8698283?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Globally, the cultivation area of genetically modified (GM) crops is increasing dramatically. Despite their well-known benefits, they may also pose many risks to agriculture and the environment. Among the various GM crops, GM rapeseed (Brassica napus L.) is widely cultivated, mainly for oil production. At the same time, B. napus possesses a number of characteristics, including the ability to form feral populations and act as small-seeded weeds, and has a high potential for hybridization with other species. In this review, we provide an overview of the commercialization, approval status, and cultivation of GM rapeseed, as well as the status of the feral rapeseed populations. In addition, we highlight the case studies on the unintentional environmental release of GM rapeseed during transportation in several countries. Previous studies suggest that the main reason for the unintentional release is seed spillage during transport/importing of rapeseed in both GM rapeseed-cultivating and -non-cultivating countries. Despite the fact that incidents of unintentional release have been recorded often, there have been no reports of serious detrimental consequences. However, since rapeseed has a high potential for hybridization, the possibilities of gene flow within the genus, especially with B. rapa, are relatively significant, and considering their weedy properties, effective management methods are needed. Hence, we recommend that specific programs be used for the effective monitoring of environmental releases of GM rapeseed as well as management to avoid environmental and agricultural perturbations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9a57481-d82e-4903-8763-031f9be7748c', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Agronomic, Physiological and Genetic Changes Associated With Evolution, Migration and Modern Breeding in Durum Wheat', 'Royo C, Ammar K, Villegas D, Soriano JM', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.674470', 'https://doi.org/10.3389/fpls.2021.674470', 'https://europepmc.org/articles/PMC8296143?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'A panel of 172 Mediterranean durum wheat landraces and 200 modern cultivars was phenotyped during three years for 21 agronomic and physiological traits and genotyped with 46,161 DArTseq markers. Modern cultivars showed greater yield, number of grains per spike (NGS) and harvest index (HI), but similar number of spikes per unit area (NS) and grain weight than the landraces. Modern cultivars had earlier heading but longer heading-anthesis and grain-filling periods than the landraces. They had greater RUE (Radiation Use Efficiency) up to anthesis and lower canopy temperature at anthesis than the landraces, but the opposite was true during the grain-filling period. Landraces produced more biomass at both anthesis and maturity. The 120 genotypes with a membership coefficient q > 0.8 to the five genetic subpopulations (SP) that structured the panel were related with the geographic distribution and evolutionary history of durum wheat. SP1 included landraces from eastern countries, the domestication region of the "Fertile Crescent." SP2 and SP3 consisted of landraces from the north and the south Mediterranean shores, where durum wheat spread during its migration westward. Decreases in NS, grain-filling duration and HI, but increases in early soil coverage, days to heading, biomass at anthesis, grain-filling rate, plant height and peduncle length occurred during this migration. SP4 grouped modern cultivars gathering the CIMMYT/ICARDA genetic background, and SP5 contained modern north-American cultivars. SP4 was agronomically distant from the landraces, but SP5 was genetically and agronomically close to SP1. GWAS identified 2,046 marker-trait associations (MTA) and 144 QTL hotspots integrating 1,927 MTAs. Thirty-nine haplotype blocks (HB) with allelic differences among SPs and associated with 16 agronomic traits were identified within 13 QTL hotspots. Alleles in chromosomes 5A and 7A detected in landraces were associated with decreased yield. The late heading and short grain-filling period of SP2 and SP3 were associated with a hotspot on chromosome 7B. The heavy grains of SP3 were associated with hotspots on chromosomes 2A and 7A. The greater NGS and HI of modern cultivars were associated with allelic variants on chromosome 7A. A hotspot on chromosome 3A was associated with the high NGS, earliness and short stature of SP4.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9dbe4647-d397-48f9-9e06-3e864d082929', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Assessing Genetic Diversity to Breed Competitive Biofortified Wheat With Enhanced Grain Zn and Fe Concentrations', 'Velu G, Crespo Herrera L, Guzman C, Huerta J, Payne T, Singh RP', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01971', 'https://doi.org/10.3389/fpls.2018.01971', 'https://europepmc.org/articles/PMC6335970?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Breeding wheat with enhanced levels of grain zinc (Zn) and iron (Fe) is a cost-effective, sustainable solution to malnutrition problems. Modern wheat varieties have limited variation in grain Zn and Fe, but large-scale screening has identified high levels of Zn and Fe in wild relatives and progenitors of cultivated wheat. The most promising sources of high Zn and Fe are einkorn (Triticum monococcum), wild emmer (T. dicoccoides), diploid progenitors of hexaploid wheat (such as Aegilops tauschii), T. spelta, T. polonicum, and landraces of T. aestivum. This study evaluate the effects of translocations from rye and different Aegilops species in a "Pavon-76" wheat genetic background and utilized in the wheat biofortification breeding program at CIMMYT that uses diverse genetic resources, including landraces, recreated synthetic hexaploids, T. spelta and pre-breeding lines. Four translocations were identified that resulted significantly higher Zn content in "Pavon 76" genetic background than the check varieties, and they had increased levels of grain Fe as well-compared to "Pavon 76." These lines were also included in the breeding program aimed to develop advanced high Zn breeding lines. Advanced lines derived from diverse crosses were screened under Zn-enriched soil conditions in Mexico during the 2017 and 2018 seasons. The Zn content of the grain was ranging from 35 to 69 mg/kg during 2017 and 38 to 72 mg/kg during 2018. Meanwhile grain Fe ranged from 30 to 43 mg/kg during 2017 and 32 to 52 mg/kg during 2018. A highly significant positive correlation was found between Zn and Fe (r = 0.54; P < 0.001) content of the breeding lines, therefore it was possible to breed for both properties in parallel. Yield testing of the advanced lines showed that 15% (2017) and 24% (2018) of the lines achieved 95-110% yield potential of the commercial checks and also had 12 mg/kg advantage in the Zn content suggesting that greater genetic gains and farmer-preferred wheat varieties were developed and deployed. A decade of research and breeding efforts led to the selection of "best-bet" breeding lines and the release of eight biofortified wheat varieties in target regions of South Asia and in Mexico.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b050f4ce-5770-4b83-8aca-cec07fb0866f', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Carbon Footprint Management by Agricultural Practices', 'Ozlu E, Arriaga FJ, Bilen S, Gozukara G, Babur E', 2022, 'Biology', '10.3390/biology11101453', 'https://doi.org/10.3390/biology11101453', 'https://europepmc.org/articles/PMC9598751?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Global attention to climate change issues, especially air temperature changes, has drastically increased over the last half-century. Along with population growth, greater surface temperature, and higher greenhouse gas (GHG) emissions, there are growing concerns for ecosystem sustainability and other human existence on earth. The contribution of agriculture to GHG emissions indicates a level of 18% of total GHGs, mainly from carbon dioxide (CO2), methane (CH4), and nitrous oxide (N2O). Thus, minimizing the effects of climate change by reducing GHG emissions is crucial and can be accomplished by truly understanding the carbon footprint (CF) phenomenon. Therefore, the purposes of this study were to improve understanding of CF alteration due to agricultural management and fertility practices. CF is a popular concept in agro-environmental sciences due to its role in the environmental impact assessments related to alternative solutions and global climate change. Soil moisture content, soil temperature, porosity, and water-filled pore space are some of the soil properties directly related to GHG emissions. These properties raise the role of soil structure and soil health in the CF approach. These properties and GHG emissions are also affected by different land-use changes, soil types, and agricultural management practices. Soil management practices globally have the potential to alter atmospheric GHG emissions. Therefore, the relations between photosynthesis and GHG emissions as impacted by agricultural management practices, especially focusing on soil and related systems, must be considered. We conclude that environmental factors, land use, and agricultural practices should be considered in the management of CF when maximizing crop productivity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e25f7a13-7be1-4696-ba5f-6f9418047f5a', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Combining the fractional order derivative and machine learning for leaf water content estimation of spring wheat using hyper-spectral indices', 'Zununjan Z, Turghan MA, Sattar M, Kasim N, Emin B, Abliz A', 2024, 'Plant methods', '10.1186/s13007-024-01224-0', 'https://doi.org/10.1186/s13007-024-01224-0', 'https://europepmc.org/articles/PMC11193302?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Leaf water content (LWC) is a vital indicator of crop growth and development. While visible and near-infrared (VIS-NIR) spectroscopy makes it possible to estimate crop leaf moisture, spectral preprocessing and multiband spectral indices have important significance in the quantitative analysis of LWC. In this work, the fractional order derivative (FOD) was used for leaf spectral processing, and multiband spectral indices were constructed based on the band-optimization algorithm. Eventually, an integrated index, namely, the multiband spectral index (MBSI) and moisture index (MI), is proposed to estimate the LWC in spring wheat around Fu-Kang City, Xinjiang, China. The MBSIs for LWC were calculated from two types of spectral data: raw reflectance (RR) and the spectrum based on FOD. The LWC was estimated by combining machine learning (K-nearest neighbor, KNN; support vector machine, SVM; and artificial neural network, ANN). The results showed that the fractional derivative pretreatment of spectral data enhances the implied information of the spectrum (the maximum correlation coefficient appeared using a 0.8-order differential) and increases the number of sensitive bands, especially in the near-infrared bands (700-1100 nm). The correlations between LWC and the two-band index (RVI1156, 1628 nm), three-band indices (3BI-3(766, 478, 1042 nm), 3BI-4(1129, 1175, 471 nm), 3BI-5(814, 929, 525 nm), 3BI-6(1156, 1214, 802 nm), 3BI-7(929, 851, 446 nm)) based on FOD were higher than that of moisture indices and single-band spectrum, with r of - 0.71**, 0.74**, 0.73**, - 0.72**, 0.75** and - 0.76** for the correlation. The prediction accuracy of the two-band spectral indices (DVI(698, 1274 nm) DVI(698, 1274 nm) DVI(698, 1274 nm)) was higher than that of the moisture spectral index, with R2 of 0.81 and R2 of 0.79 for the calibration and validation, respectively. Due to a large amount of spectral indices, the correlation coefficient method was used to select the characteristic spectral index from full three-band indices. Among twenty seven models, the FWBI-3BI- 0.8 order model performed the best predictive ability (with an R2 of 0.86, RMSE of 2.11%, and RPD of 2.65). These findings confirm that combining spectral index optimization with machine learning is a highly effective method for inverting the leaf water content in spring wheat.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9980a40b-8240-4a3e-9cc5-a7ef8223b96e', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Cultivating antimicrobial resistance: how intensive agriculture ploughs the way for antibiotic resistance', 'Kelbrick M, Hesse E, O'' Brien S', 2023, 'Microbiology (Reading, England)', '10.1099/mic.0.001384', 'https://doi.org/10.1099/mic.0.001384', 'https://europepmc.org/articles/PMC10482381?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Antimicrobial resistance (AMR) is a growing threat to public health, global food security and animal welfare. Despite efforts in antibiotic stewardship, AMR continues to rise worldwide. Anthropogenic activities, particularly intensive agriculture, play an integral role in the dissemination of AMR genes within natural microbial communities - which current antibiotic stewardship typically overlooks. In this review, we examine the impact of anthropogenically induced temperature fluctuations, increased soil salinity, soil fertility loss, and contaminants such as metals and pesticides on the de novo evolution and dissemination of AMR in the environment. These stressors can select for AMR - even in the absence of antibiotics - via mechanisms such as cross-resistance, co-resistance and co-regulation. Moreover, anthropogenic stressors can prime bacterial physiology against stress, potentially widening the window of opportunity for the de novo evolution of AMR. However, research to date is typically limited to the study of single isolated bacterial species - we lack data on how intensive agricultural practices drive AMR over evolutionary timescales in more complex microbial communities. Furthermore, a multidisciplinary approach to fighting AMR is urgently needed, as it is clear that the drivers of AMR extend far beyond the clinical environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('52d17f4c-51df-453a-904b-d220a935aa72', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Dryland Cropping Systems, Weed Communities, and Disease Status Modulate the Effect of Climate Conditions on Wheat Soil Bacterial Communities', 'Ishaq SL, Seipel T, Yeoman C, Menalled FD', 2020, 'mSphere', '10.1128/msphere.00340-20', 'https://doi.org/10.1128/msphere.00340-20', 'https://europepmc.org/articles/PMC7364210?pdf=render', NULL, NULL, 22, NULL, 'prairies', 4, 'cc by', 'Little knowledge exists on how soil bacteria in agricultural settings are impacted by management practices and environmental conditions in current and predicted climate scenarios. We assessed the impact of soil moisture, soil temperature, weed communities, and disease status on soil bacterial communities in three cropping systems: (i) conventional no-till (CNT) systems utilizing synthetic pesticides and herbicides, (ii) USDA-certified tilled organic (OT) systems, and (iii) USDA-certified organic systems with sheep grazing (OG). Sampling date within the growing season and associated soil temperature and moisture exerted the greatest effect on bacterial communities, followed by cropping system, Wheat streak mosaic virus (WSMV) infection status, and weed community. Soil temperature was negatively correlated with bacterial richness and evenness, while soil moisture was positively correlated with bacterial richness and evenness. Soil temperature and soil moisture independently altered soil bacterial community similarity between treatments. Inoculation of wheat with WSMV altered the associated soil bacteria, and there were interactions between disease status and cropping system, sampling date, and climate conditions, indicating the effect of multiple stressors on bacterial communities in soil. In May and July, cropping system altered the effect of climate change on the bacterial community composition in hotter conditions and in hotter and drier conditions compared to ambient conditions, in samples not treated with WSMV. Overall, this study indicates that predicted climate modifications as well as biological stressors play a fundamental role in the impact of cropping systems on soil bacterial communities.IMPORTANCE Climate change is affecting global moisture and temperature patterns, and its impacts are predicted to worsen over time, posing progressively larger threats to food production. In the Northern Great Plains of the United States, climate change is forecast to increase temperature and decrease precipitation during the summer, and it is expected to negatively affect cereal crop production and pest management. In this study, temperature, soil moisture, weed communities, and disease status had interactive effects with cropping system on bacterial communities. As local climates continue to shift, the dynamics of above- and belowground associated biodiversity will also shift, which will impact food production and increase the need for more sustainable practices.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4aeadc1a-dddd-4b4c-ba47-b3e7fd1e355c', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Genetic modifications associated with sustainability aspects for sustainable developments', 'Sharma P, Singh SP, Iqbal HMN, Parra-Saldivar R, Varjani S, Tong YW', 2022, 'Bioengineered', '10.1080/21655979.2022.2061146', 'https://doi.org/10.1080/21655979.2022.2061146', 'https://europepmc.org/articles/PMC9161841?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Sustainable development serves as the foundation for a range of international and national policymaking. Traditional breeding methods have been used to modify plant genomes and production. Genetic engineering is the practice of assisting agricultural systems in adapting to rapidly changing global growth by hastening the breeding of new varieties. On the other hand, the development of genetic engineering has enabled more precise control over the genomic alterations made in recent decades. Genetic changes from one species can now be introduced into a completely unrelated species, increasing agricultural output or making certain elements easier to manufacture. Harvest plants and soil microorganisms are just a few of the more well-known genetically modified creatures. Researchers assess current studies and illustrate the possibility of genetically modified organisms (GMOs) from the perspectives of various stakeholders. GMOs increase yields, reduce costs, and reduce agriculture''s terrestrial and ecological footprint. Modern technology benefits innovators, farmers, and consumers alike. Agricultural biotechnology has numerous applications, each with its own set of potential consequences. This will be able to reach its full potential if more people have access to technology and excessive regulation is avoided. This paper covers the regulations for genetically modified crops (GMCs) as well as the economic implications. It also includes sections on biodiversity and environmental impact, as well as GMCs applications. This recounts biotechnological interventions for long-term sustainability in the field of GMCs, as well as the challenges and opportunities in this field of research.Abbreviations: GMCs-Genetically modified crops; GMOs- Genetically modified organisms; GE- Genetic engineering; Bt- Bacillus thuringiensisNIH- National Institutes of Health; FDA- Food and Drug Administration; HGT- Horizontal gene transfer; GM- Genetically modified; rDNA- Ribosomal deoxyribonucleic acid; USDA- United States Department of Agriculture; NIH- National Institutes of Health.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d1585c3-f129-4f6e-b732-e31ce19c70f6', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Herbicide Efficacy of Spot Spraying Systems in Fallow and Postharvest in the Pacific Northwest Dryland Wheat Production Region', 'Nicholas G. Genna, Jennifer A. Gourlie, Judit Barroso', 2021, 'Plants', '10.3390/plants10122725', 'https://doi.org/10.3390/plants10122725', 'https://www.mdpi.com/2223-7747/10/12/2725', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Real-time spot spraying technology has the potential to reduce herbicide costs and slow herbicide resistance. However, few studies exist on the efficacy of this technology in the Pacific Northwest (PNW). This research compared the herbicide efficacy (reduction in weed density and cover) of WEED-IT and WeedSeeker spot spraying systems to uniform spraying in fallow and postharvest in 2019 and 2020. Weed community types included naturally occurring weeds, natural + Russian thistle (Salsola tragus L.), or natural + kochia (Bassia scoparia (L.) A. J. Scott). Herbicides included glyphosate or the pre-mix bromoxynil + pyrasulfotole. Additionally, herbicide efficacy was studied with short stubble (~10 cm), tall stubble (~25 cm), and normal stubble (~20 cm) with chaff and straw removed. In fallow, herbicide efficacy was 1.5 times higher for uniform applications than for WEED-IT or WeedSeeker in 2019 and 2020. Herbicide efficacy was also 1.9 times higher for uniform applications in postharvest in 2019 but no differences were found in 2020. The weed community impacted herbicide efficacy but herbicide efficacy did not differ between residue management treatments. Finally, WEED-IT and WeedSeeker used 53% less herbicide volume in comparison to uniform applications. This research demonstrated that spot spraying technology can be efficacious and economical for growers in the PNW.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a459e656-d7a6-4ecc-a897-a0f498c9754e', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Metabolic Pathway of Topramezone in Multiple-Resistant Waterhemp (Amaranthus tuberculatus) Differs From Naturally Tolerant Maize', 'Lygin AV, Kaundun SS, Morris JA, Mcindoe E, Hamilton AR, Riechers DE', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01644', 'https://doi.org/10.3389/fpls.2018.01644', 'https://europepmc.org/articles/PMC6258821?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Waterhemp [Amaranthus tuberculatus (Moq.) Sauer] is a problematic dicot weed in maize, soybean, and cotton production in the United States. Waterhemp has evolved resistance to several commercial herbicides that inhibit the 4-hydroxyphenylpyruvate-dioxygenase (HPPD) enzyme in sensitive dicots, and research to date has shown that HPPD-inhibitor resistance is conferred by rapid oxidative metabolism of the parent compound in resistant populations. Mesotrione and tembotrione (both triketones) have been used exclusively to study HPPD-inhibitor resistance mechanisms in waterhemp and a related species, A. palmeri (S. Wats.), but the commercial HPPD inhibitor topramezone (a pyrazolone) has not been investigated from a mechanistic standpoint despite numerous reports of cross-resistance in the field and greenhouse. The first objective of our research was to determine if two multiple herbicide-resistant (MHR) waterhemp populations (named NEB and SIR) metabolize topramezone more rapidly than two HPPD inhibitor-sensitive waterhemp populations (named SEN and ACR). Our second objective was to determine if initial topramezone metabolite(s) detected in MHR waterhemp are qualitatively different than those formed in maize. An excised leaf assay and whole-plant study investigated initial rates of topramezone metabolism (<24 h) and identified topramezone metabolites at 48 hours after treatment (HAT), respectively, in the four waterhemp populations and maize. Results indicated both MHR waterhemp populations metabolized more topramezone than the sensitive (SEN) population at 6 HAT, while only the SIR population metabolized more topramezone than SEN at 24 HAT. Maize metabolized more topramezone than any waterhemp population at each time point examined. LC-MS analysis of topramezone metabolites at 48 HAT showed maize primarily formed desmethyl and benzoic acid metabolites, as expected based on published reports, whereas SIR formed two putative hydroxylated metabolites. Subsequent LC-MS/MS analyses identified both hydroxytopramezone metabolites in SIR as different hydroxylation products of the isoxazole ring, which were also present in maize 48 HAT but at very low levels. These results indicate that SIR initially metabolizes and detoxifies topramezone in a different manner than tolerant maize.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4eba47f6-26eb-4483-961b-ebb60f9d5886', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Multiple Mechanisms Increase Levels of Resistance in Rapistrum rugosum to ALS Herbicides', 'Hatami ZM, Gherekhloo J, Rojano-Delgado AM, Osuna MD, Alcántara R, Fernández P, Sadeghipour HR, De Prado R', 2016, 'Frontiers in plant science', '10.3389/fpls.2016.00169', 'https://doi.org/10.3389/fpls.2016.00169', 'https://europepmc.org/articles/PMC4761845?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Rapistrum rugosum (turnip weed) is a common weed of wheat fields in Iran, which is most often controlled by tribenuron-methyl (TM), a sulfonylurea (SU) belonging to the acetolactate synthase (ALS) inhibiting herbicides group. Several cases of unexplained control failure of R. rugosum by TM have been seen, especially in Golestan province-Iran. Hence, there is lack of research in evaluation of the level of resistance of the R. rugosum populations to TM, using whole plant dose-response and enzyme assays, then investigating some potential resistance mechanisms Results revealed that the resistance factor (RF) for resistant (R) populations was 2.5-6.6 fold higher than susceptible (S) plant. Neither foliar retention, nor (14)C-TM absorption and translocation were the mechanisms responsible for resistance in turnip weed. Metabolism of TM was the second resistant mechanism in two populations (Ag-R5 and G-1), in which three metabolites were found. The concentration of TM for 50% inhibition of ALS enzyme activity in vitro showed a high level of resistance to the herbicide (RFs were from 28 to 38) and cross-resistance to sulfonyl-aminocarbonyl-triazolinone (SCT), pyrimidinyl-thiobenzoate (PTB) and triazolopyrimidine (TP), with no cross-resistance to imidazolinone (IMI). Substitution Pro 197 to Ser 197 provided resistance to four of five ALS-inhibiting herbicides including SU, TP, PTB, and SCT with no resistance to IMI. These results documented the first case of R. rugosum resistant population worldwide and demonstrated that both RST and NRST mechanisms are involved to the resistance level to TM.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('501c8332-81a5-4999-80e1-16524de53d0a', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Physiological and Molecular Characterization of Hydroxyphenylpyruvate Dioxygenase (HPPD)-inhibitor Resistance in Palmer Amaranth (Amaranthus palmeri S.Wats.)', 'Nakka S, Godar AS, Wani PS, Thompson CR, Peterson DE, Roelofs J, Jugulam M', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.00555', 'https://doi.org/10.3389/fpls.2017.00555', 'https://europepmc.org/articles/PMC5387043?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'Herbicides that inhibit hydroxyphenylpyruvate dioxygenase (HPPD) such as mesotrione are widely used to control a broad spectrum of weeds in agriculture. Amaranthus palmeri is an economically troublesome weed throughout the United States. The first case of evolution of resistance to HPPD-inhibiting herbicides in A. palmeri was documented in Kansas (KS) and later in Nebraska (NE). The objective of this study was to investigate the mechansim of HPPD-inhibitor (mesotrione) resistance in A. palmeri. Dose response analysis revealed that this population (KSR) was 10-18 times more resistant than their sensitive counterparts (MSS or KSS). Absorbtion and translocation analysis of [14C] mesotrione suggested that these mechanisms were not involved in the resistance in A. palmeri. Importantly, mesotrione (>90%) was detoxified markedly faster in the resistant populations (KSR and NER), within 24 hours after treatment (HAT) compared to sensitive plants (MSS, KSS, or NER). However, at 48 HAT all populations metabolized the mesotrione, suggesting additional factors may contribute to this resistance. Further evaluation of mesotrione-resistant A. palmeri did not reveal any specific resistance-conferring mutations nor amplification of HPPD gene, the molecular target of mesotrione. However, the resistant populations showed 4- to 12-fold increase in HPPD gene expression. This increase in HPPD transcript levels was accompanied by increased HPPD protein expression. The significant aspects of this research include: the mesotrione resistance in A. palmeri is conferred primarily by rapid detoxification (non-target-site based) of mesotrione; additionally, increased HPPD gene expression (target-site based) also contributes to the resistance mechanism in the evolution of herbicide resistance in this naturally occurring weed species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0cbb0681-a64f-45e2-8750-1d390da2ac7e', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Plant responses to environmental stresses-from gene to biotechnology', 'Ahanger MA, Akram NA, Ashraf M, Alyemeni MN, Wijaya L, Ahmad P', 2017, 'AoB PLANTS', '10.1093/aobpla/plx025', 'https://doi.org/10.1093/aobpla/plx025', 'https://europepmc.org/articles/PMC5534019?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Increasing global population, urbanization and industrialization are increasing the rate of conversion of arable land into wasteland. Supplying food to an ever-increasing population is one of the biggest challenges that agriculturalists and plant scientists are currently confronting. Environmental stresses make this situation even graver. Despite the induction of several tolerance mechanisms, sensitive plants often fail to survive under environmental extremes. New technological approaches are imperative. Conventional breeding methods have a limited potential to improve plant genomes against environmental stress. Recently, genetic engineering has contributed enormously to the development of genetically modified varieties of different crops such as cotton, maize, rice, canola and soybean. The identification of stress-responsive genes and their subsequent introgression or overexpression within sensitive crop species are now being widely carried out by plant scientists. Engineering of important tolerance pathways, like antioxidant enzymes, osmolyte accumulation, membrane-localized transporters for efficient compartmentation of deleterious ions and accumulation of essential elements and resistance against pests or pathogens is also an area that has been intensively researched. In this review, the role of biotechnology and its successes, prospects and challenges in developing stress-tolerant crop cultivars are discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b415729a-078f-46f8-bc76-c940cf4391e0', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Response of microorganisms and enzymes to soil contamination with a mixture of terbuthylazine, mesotrione, and S-metolachlor', 'Borowik A, Wyszkowska J, Kucharski J, Baćmaga M, Tomkiel M', 2017, 'Environmental science and pollution research international', '10.1007/s11356-016-7919-z', 'https://doi.org/10.1007/s11356-016-7919-z', 'https://europepmc.org/articles/PMC5306303?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The research objective has been to evaluate the effect, unexplored yet, of a mixture of three active ingredients of the herbicide Lumax 537.5 SE: terbuthylazine (T), mesotrione (M), and S-metolachlor (S) on counts of soil microorganisms, structure of microbial communities, activity of soil enzymes as well as the growth and development of maize. The research was based on a pot experiment established on sandy soil with pHKCl 7.0. The herbicide was applied to soil once, in the form of liquid emulsion dosed as follows: 0.67, 13.4, 26.9, 53.8, 108, 215, and 430 mg kg-1 of soil, converted per active substance (M + T + S). The control sample consisted of soil untreated with herbicide. The results showed that the mixture of the above active substances caused changes in values of the colony development (CD) indices of organotrophic bacteria, actinomycetes, and fungi and ecophysiological diversity (EP) indices of fungi. Changes in the ecophysiological diversity index of organotrophic bacteria and actinomycetes were small. The M + T + S mixture was a strong inhibitor of dehydrogenases, to a less degree catalase, urease, β-glucosidase, and arylsulfatase, while being a weak inhibitor of phosphatases. The actual impact was correlated with the dosage. The M + T + S mixture inhibited the growth and development of maize. The herbicide Lumax 537.5 SE should be applied strictly in line with the regime that defines its optimum dosage. Should its application adhere to the manufacturer''s instructions, the herbicide would not cause any serious disturbance in soil homeostasis. However, its excessive quantities (from 13.442 to 430.144 mg kg-1 DM of soil) proved to be harmful to the soil environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4690f0e8-56ba-4ce4-ba43-a5bcc6d01113', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Review: Allelochemicals as multi-kingdom plant defence compounds: towards an integrated approach', 'Hickman DT, Rasmussen A, Ritz K, Birkett MA, Neve P', 2021, 'Pest management science', '10.1002/ps.6076', 'https://doi.org/10.1002/ps.6076', 'https://europepmc.org/articles/PMC7891363?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'The capability of synthetic pesticides to manage weeds, insect pests and pathogens in crops has diminished due to evolved resistance. Sustainable management is thus becoming more challenging. Novel solutions are needed and, given the ubiquity of biologically active secondary metabolites in nature, such compounds require further exploration as leads for novel crop protection chemistry. Despite improving understanding of allelochemicals, particularly in terms of their potential for use in weed control, their interactions with multiple biotic kingdoms have to date largely been examined in individual compounds and not as a recurrent phenomenon. Here, multi-kingdom effects in allelochemicals are introduced by defining effects on various organisms, before exploring current understanding of the inducibility and possible ecological roles of these compounds with regard to the evolutionary arms race and dose-response relationships. Allelochemicals with functional benefits in multiple aspects of plant defence are described. Gathering these isolated areas of science under the unified umbrella of multi-kingdom allelopathy encourages the development of naturally-derived chemistries conferring defence to multiple discrete biotic stresses simultaneously, maximizing benefits in weed, insect and pathogen control, while potentially circumventing resistance. © 2020 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b13e04a6-ef90-4196-aef5-ce79fc6ae3b2', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Spatial variation of rodenticides and emerging contaminants in blood of raptor nestlings from Germany', 'Badry A, Schenke D, Brücher H, Chakarov N, Grünkorn T, Illner H, Krüger O, Marczak T', 2022, 'Environmental science and pollution research international', '10.1007/s11356-022-20089-1', 'https://doi.org/10.1007/s11356-022-20089-1', 'https://europepmc.org/articles/PMC9427910?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Wildlife exposures to pest controlling substances have resulted in population declines of many predatory species during the past decades. Many pesticides were subsequently classified as persistent, bioaccumulative, and toxic (PBT) and banned on national or global scales. However, despite their risks for non-target vertebrate wildlife, PBT substances such as anticoagulant rodenticides (ARs) are still permitted for use in Europe and have shown to threaten raptors. Whereas risks of ARs are known, much less information is available on emerging agrochemicals such as currently used PPPs and medicinal products (MPs) in higher trophic level species. We expect that currently used PPPs are relatively mobile (vs. lipophilic) as a consequence of the PBT criteria and thus more likely to be present in aqueous matrices. We therefore analyzed blood of 204 raptor nestlings of three terrestrial (red kite, common buzzard, Montagu''s harrier) and two aquatic species (white-tailed sea eagle, osprey) from Germany. In total, we detected ARs in 22.6% of the red kites and 8.6% of the buzzards, whereas no Montagu''s harriers or aquatic species were exposed prior to sampling. ΣAR concentration tended to be higher in North Rhine-Westphalia (vs. North-Eastern Germany) where population density is higher and intense livestock farming more frequent. Among the 90 targeted and currently used PPPs, we detected six substances from which bromoxynil (14.2%) was most frequent. Especially Montagu''s harrier (31%) and red kites (22.6%) were exposed and concentrations were higher in North Rhine-Westphalia as well. Among seven MPs, we detected ciprofloxacin (3.4%), which indicates that risk mitigation measures may be needed as resistance genes were already detected in wildlife from Germany. Taken together, our study demonstrates that raptors are exposed to various chemicals during an early life stage depending on their sampling location and underpins that red kites are at particular risk for multiple pesticide exposures in Germany.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3d1e2adc-79b0-4192-91c6-8f31320cab1f', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'Synthesis and herbicidal activities of aryloxyacetic acid derivatives as HPPD inhibitors', 'Wang MM, Huang H, Shu L, Liu JM, Zhang JQ, Yan YL, Zhang DY', 2020, 'Beilstein journal of organic chemistry', '10.3762/bjoc.16.25', 'https://doi.org/10.3762/bjoc.16.25', 'https://europepmc.org/articles/PMC7059547?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'A series of aryloxyacetic acid derivatives were designed and synthesized as 4-hydoxyphenylpyruvate dioxygenase (HPPD) inhibitors. Preliminary bioassay results reveal that these derivatives are promising Arabidopsis thaliana HPPD (AtHPPD) inhibitors, in particular compounds I12 (K i = 0.011 µM) and I23 (K i = 0.012 µM), which exhibit similar activities to that of mesotrione, a commercial HPPD herbicide (K i = 0.013 µM). Furthermore, the newly synthesized compounds show significant greenhouse herbicidal activities against tested weeds at dosages of 150 g ai/ha. In particular, II4 exhibited high herbicidal activity for pre-emergence treatment that was slightly better than that of mesotrione. In addition, compound II4 was safe for weed control in maize fields at a rate of 150 g ai/ha, and was identified as the most potent candidate for a novel HPPD inhibitor herbicide. The compounds described herein may provide useful guidance for the design of new HPPD inhibiting herbicides and their modification.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d65fddbe-f47f-4d8a-8f94-9b8434b6fd94', 'e2949dc0-5d2e-4b83-96bf-580ba6cf4415', 'The Metabolism of a Novel Cytochrome P450 (CYP77B34) in Tribenuron-Methyl-Resistant Descurainia sophia L. to Herbicides with Different Mode of Actions', 'Shen J, Yang Q, Hao L, Zhang L, Li X, Zheng M', 2022, 'International journal of molecular sciences', '10.3390/ijms23105812', 'https://doi.org/10.3390/ijms23105812', 'https://europepmc.org/articles/PMC9147942?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Descurainia sophia L. (flixweeds) is a noxious broad-leaf weed infesting winter wheat fields in China that has evolved high resistance to tribenuron-methyl. In this work, a brand new gene CYP77B34 was cloned from tribenuron-methyl-resistant (TR) D. sophia and transferred into Arabidopsis thaliana, and the sensitivities of Arabidopsis with or without the CYP77B34 transgene to herbicides with a different mode of actions (MoAs) were tested. Compared to Arabidopsis expressing pCAMBIA1302-GFP (empty plasmid), Arabidopsis transferring pCAMBIA1302-CYP77B34 (recombinant plasmid) became resistant to acetolactate synthase (ALS)-inhibiting herbicide tribenuron-methyl, protoporphyrinogen oxidase (PPO)-inhibiting herbicides carfentrazone-ethyl and oxyfluorfen. Cytochrome P450 inhibitor malathion could reverse the resistance to tribenuron-methyl, carfentrazone-ethyl and oxyfluorfen in transgenic Arabidopsis plants. In addition, the metabolic rates of tribenuron-methyl in Arabidopsis expressing CYP77B34 were significantly higher than those in Arabidopsis expressing pCAMBIA1302-GFP. Other than that, the transgenic plants showed some tolerance to very-long-chain fatty acid synthesis (VLCFAs)-inhibiting herbicide pretilachlor and photosystem (PS) II-inhibiting herbicide bromoxynil. Subcellular localization revealed that the CYP77B34 protein was located in the endoplasmic reticulum (ER). These results clearly indicated that CYP77B34 mediated D. sophia resistance to tribenuron-methyl and may have been involved in D. sophia cross-resistance to carfentrazone-ethyl, oxyfluorfen, pretilachlor and bromoxynil.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b59fedde-9354-476e-b858-a8bdf9e19388', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'A Review of Insect Pest Management in Vegetable Crop Production in Nigeria', 'Ofuya TI, Okunlola AI, Mbata GN', 2023, 'Insects', '10.3390/insects14020111', 'https://doi.org/10.3390/insects14020111', 'https://europepmc.org/articles/PMC9963591?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Insect pest infestations and damage can limit the production of vegetables in the farming systems in Nigeria. This review looks at integrated insect pest management as a possible panacea for resolving insect pest issues in vegetable crops. The main vegetable crops which include okra, tomatoes, chilli peppers, cucumbers, green amaranth, carrots and onions are highlighted. The major insect pests of the various vegetables which include foliage beetles, caterpillars, aphids, fruit flies, stink bugs, and grasshoppers are also mentioned. The various control measures that have been empirically verified for the mitigation of the impact of these insect pests, including the application of synthetic insecticides, modification of agronomic practices, use of resistant varieties, application of botanicals, biological and mechanical controls, are discussed. Studies which have been carried out attempting to integrate two or more of the control strategies for better insect pest control are also reviewed. Strategies that can be put in place for the integrated pest management of vegetable insect pests in Nigeria are considered. Among the IPM (Integrated Pest Management) practices instituted for the mitigation of pest infestations on vegetable crops in Nigeria, intercropping of suitable vegetables in combination with the application of aqueous extracts of Azadirachta indica and Piper guineense seeds under good farm hygiene and sanitation proved to be most successful.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('00bc23fb-0634-4dde-b692-b06c6596adaa', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Baseline Susceptibility of Eldana saccharina to Coragen® SC: Implications for Resistance Monitoring and Management in Sugarcane', 'Kwanele Phiwinhlanhla Msele, Caswell Munyai, Ewald Hendrik Albertse, Lawrence Nkosikhona Malinga', 2026, 'Biology and Life Sciences Forum', '10.3390/blsf2025054008', 'https://doi.org/10.3390/blsf2025054008', 'https://www.mdpi.com/2673-9976/54/1/8', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Eldana saccharina Walker is a major sugarcane pest in South Africa, primarily controlled with chemical insecticides, though resistance threatens their effectiveness. Laboratory bioassays at the South African Sugarcane Research Institute evaluated the baseline susceptibility of E. saccharina to six concentrations of Coragen® (chlorantraniliprole). Mortality and larval weight data were analysed using probit analysis to determine LC50 and LC95 values and assess growth inhibition. Mortality and weight reduction increased with concentration, with the highest concentration causing 79% mortality.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d16e3d73-46a3-4149-b8f5-7905483c3646', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Baseline Susceptibility of Spodoptera frugiperda Populations Collected in India towards Different Chemical Classes of Insecticides', 'Mahesh Kulye, Sonja Mehlhorn, Debora Boaventura, Nigel Godley, Sreedevi Kodikoppalu Venkatesh, Thimmaraju Rudrappa, Tara Charan, Dinesh Rathi', 2021, 'Insects', '10.3390/insects12080758', 'https://doi.org/10.3390/insects12080758', 'https://www.mdpi.com/2075-4450/12/8/758', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Fall armyworm (FAW), Spodoptera frugiperda, is a major pest of maize in the Americas and recently invaded the Eastern hemisphere. It was first detected in India in 2018 and is considered a major threat to maize production. FAW control largely relies on the application of chemical insecticides and transgenic crops expressing Bacillus thuringiensis insecticidal proteins. Assessing FAW resistance and insecticide susceptibility is a cornerstone to develop sustainable resistance management strategies. In this study, we conducted more than 400 bioassays to assess the efficacy of nine insecticides from seven mode-of-action classes against 47 FAW populations collected in 2019 and 2020 across various geographical areas in India. The resistance status of the field-collected populations was compared to an Indian population sampled in 2018, and an insecticide susceptible reference population collected in 2005 in Brazil. Low to moderate resistance levels were observed for thiodicarb, chlorpyriphos, deltamethrin, chlorantraniliprole and flubendiamide in several populations (including the reference population collected in 2018). The highest resistance ratios were observed for deltamethrin which likely compromises recommended label rates for pyrethroid insecticides in general. Our data provide a useful baseline for future FAW resistance monitoring initiatives and highlight the need to implement insecticide resistance management strategies.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4d750943-8fec-4558-94cc-04bb051f5312', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Biological Control of a Phytosanitary Pest (Thaumatotibia leucotreta): A Case Study', 'Moore SD', 2021, 'International journal of environmental research and public health', '10.3390/ijerph18031198', 'https://doi.org/10.3390/ijerph18031198', 'https://europepmc.org/articles/PMC7908599?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Thaumatotibia leucotreta, known as the false codling moth, is a pest of citrus and other crops in sub-Saharan Africa. As it is endemic to this region and as South Africa exports most of its citrus around the world, T. leucotreta has phytosanitary status for most markets. This means that there is zero tolerance for any infestation with live larvae in the market. Consequently, control measures prior to exporting must be exemplary. Certain markets require a standalone postharvest disinfestation treatment for T. leucotreta. However, the European Union accepts a systems approach, consisting of three measures and numerous components within these measures. Although effective preharvest control measures are important under all circumstances, they are most critical where a standalone postharvest disinfestation treatment is not applied, such as within a systems approach. Conventional wisdom may lead a belief that effective chemical control tools are imperative to achieve this end. However, we demonstrate that it is possible to effectively control T. leucotreta to a level acceptable for a phytosanitary market, using only biological control tools. This includes parasitoids, predators, microbial control, semiochemicals, and sterile insects. Simultaneously, on-farm and environmental safety is improved and compliance with the increasing stringency of chemical residue requirements imposed by markets is achieved.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c92b8663-5d89-4857-b7ae-e64f363ee4f0', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Characterization of cyantraniliprole resistance in Spodoptera frugiperda: Selection, inheritance pattern, and cross-resistance to other diamide insecticides', 'Thiesen LV, Gonçalves GC, Guidolin AS, Nascimento AR, Coutinho EF, Borba JP, Picelli EC, Omoto C', 2025, 'Pest management science', '10.1002/ps.8827', 'https://doi.org/10.1002/ps.8827', 'https://europepmc.org/articles/PMC12268807?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'BackgroundCyantraniliprole, a diamide insecticide, is widely used in Brazil to control sucking and defoliating pests, including the fall armyworm (Spodoptera frugiperda), a major agricultural pest. However, increasing resistance to diamides has raised concerns about the long-term effectiveness of cyantraniliprole. This study aimed to (i) assess the evolution of cyantraniliprole resistance in field populations of S. frugiperda, (ii) investigate cross-resistance to other diamides, and (iii) analyze the role of the I4790K mutation in resistance mechanisms.ResultsA significant decrease in the susceptibility to cyantraniliprole was observed in field populations of S. frugiperda in Brazil, particularly in regions with intensive agricultural systems, such as the Brazilian Cerrado, from 2017 to 2023. A cyantraniliprole-resistant strain of S. frugiperda was selected from a field-collected population in Bahia (BA) using the F2 screening method. The inheritance of resistance to cyantraniliprole in this strain was autosomal recessive and monogenic, with 3414-fold resistance ratio. High cross-resistance to the diamides flubendiamide, chlorantraniliprole, and cyclaniliprole was also detected. Molecular analysis confirmed the presence of the homozygous I4790K mutation in the ryanodine receptor gene as one of resistance mechanisms of this cyantraniliprole-resistant strain.ConclusionThese findings highlight the decreased susceptibility of field populations of S. frugiperda to cyantraniliprole and the role of the I4790K mutation in accelerating the evolution of resistance to diamide insecticides due to cross-resistance. These results underscore the urgent need for integrated pest management (IPM) strategies, including insecticide rotation and resistance monitoring, to preserve the efficacy of cyantraniliprole and other insecticides. © 2025 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2047162e-25bb-4098-86f8-6b57f23ea9a2', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Coffee Berry Borer (Hypothenemus hampei), a Global Pest of Coffee: Perspectives from Historical and Recent Invasions, and Future Priorities', 'Johnson MA, Ruiz-Diaz CP, Manoukis NC, Verle Rodrigues JC', 2020, 'Insects', '10.3390/insects11120882', 'https://doi.org/10.3390/insects11120882', 'https://europepmc.org/articles/PMC7763606?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Coffee berry borer (Hypothenemus hampei (Ferrari), CBB) has invaded nearly every coffee-producing country in the world, and it is commonly recognized as the most damaging insect pest of coffee. While research has been conducted on this pest in individual coffee-growing regions, new insights may be gained by comparing and contrasting patterns of invasion and response across its global distribution. In this review, we explore the existing literature and focus on common themes in the invasion biology of CBB by examining (1) how it was introduced into each particular region and the response to its invasion, (2) flight activity and infestation patterns, (3) economic impacts, and (4) management strategies. We highlight research conducted over the last ten years in Hawaii as a case study for the development and implementation of an effective integrated pest management (IPM) program for CBB, and also discuss biosecurity issues contributing to incursion and establishment. Potential areas for future research in each of the five major components of CBB IPM (monitoring and sampling, cultural, biological, chemical, and physical controls) are also presented. Finally, we emphasize that outreach efforts are crucial to the successful implementation of CBB IPM programs. Future research programs should strive to include coffee growers as much as possible to ensure that management options are feasible and cost-effective.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf3aa7ca-514c-49d0-a45f-0fc13dddb5f8', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Alberta barley [2026]', 'Government of Alberta', 2026, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/alberta-barley', 'https://open.alberta.ca/dataset/0d5b15ce-2dc5-44b6-9f41-c85e822d8949/resource/d69c98eb-dcab-4199-bf1c-39c05661e3d4/download/agi-alberta-barley-2026.pdf', NULL, NULL, 9, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Alberta accounts for over half of Canada''s annual barley production making it a reliable supplier of high-quality feed, malt and food barley. This promotional brochure highlights the attributes of barley and Alberta''s barley supply.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b3603f3-791c-4104-af03-423b6508a65b', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Combined PacBio Iso-Seq and Illumina RNA-Seq Analysis of the Tuta absoluta (Meyrick) Transcriptome and Cytochrome P450 Genes', 'Liu M, Xiao F, Zhu J, Fu D, Wang Z, Xiao R', 2023, 'Insects', '10.3390/insects14040363', 'https://doi.org/10.3390/insects14040363', 'https://europepmc.org/articles/PMC10146655?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Tuta absoluta (Meyrick) is a devastating invasive pest worldwide. The abamectin and chlorantraniliprole complex have become an alternative option for chemical control because they can enhance insecticidal activity and delay increased drug resistance. Notably, pests are inevitably resistant to various types of insecticides, and compound insecticides are no exception. To identify potential genes involved in the detoxification of abamectin and chlorantraniliprole complex in T. absoluta, PacBio SMRT-seq transcriptome sequencing and Illumina RNA-seq analysis of abamectin and chlorantraniliprole complex-treated T. absoluta were performed. We obtained 80,492 non-redundant transcripts, 62,762 (77.97%) transcripts that were successfully annotated, and 15,524 differentially expressed transcripts (DETs). GO annotation results showed that most of these DETs were involved in the biological processes of life-sustaining activities, such as cellular, metabolic, and single-organism processes. The KEGG pathway enrichment results showed that the pathways related to glutathione metabolism, fatty acid and amino acid synthesis, and metabolism were related to the response to abamectin and chlorantraniliprole complex in T. absoluta. Among these, 21 P450s were differentially expressed (11 upregulated and 10 downregulated). The qRT-PCR results for the eight upregulated P450 genes after abamectin and chlorantraniliprole complex treatment were consistent with the RNA-Seq data. Our findings provide new full-length transcriptional data and information for further studies on detoxification-related genes in T. absoluta.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('72004ce1-b232-4351-b970-ce9d2a92aa95', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Comparing simulated aerial and chemigation insecticide applications to manage western bean cutworm (Lepidoptera: Noctuidae) in corn', 'Rilaković A, da Silva Santana A, Zarić M, Manthena V, Golus JA, Kruger GR, Vélez AM, Peterson JA', 2025, 'Journal of economic entomology', '10.1093/jee/toae306', 'https://doi.org/10.1093/jee/toae306', 'https://europepmc.org/articles/PMC12034310?pdf=render', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc by', 'The efficacy of aerial application and chemigation of insecticides is not well explored for western bean cutworm, Striacosta albicosta (Smith), management in corn. In the short term, inadequate application of insecticides can lead to control failures when insect pests are not effectively targeted. In the longer term, exposure to sublethal insecticide concentrations can contribute to the evolution of insecticide resistance. The goal of this study was to compare aerial application and chemigation under simulated conditions to determine the most effective insecticide application method for managing S. albicosta. Three larval stages were exposed to the highest and lowest label rates of commercial formulations of bifenthrin (36.8 and 112.1 g a.i. ha-1) and chlorantraniliprole (52.7 and 75.1 g a.i. ha-1). Experiments were conducted in spray chambers, utilizing a carrier volume of 18.7 L ha-1 for aerial application and 1.57 cm ha-1 for chemigation. Mortality was recorded at 16, 24, and 41 h after infestation. The simulated aerial application was more effective than simulated chemigation in controlling S. albicosta, resulting in 100% mortality 24 h after infestation. Within the chemigation applications, chlorantraniliprole treatments were effective at both rates for all instars, while the high rate of bifenthrin exhibited greater efficacy than the lower rate. In conclusion, it was evidenced that the same insecticide active ingredients do not yield equivalent efficacy when applied via aerial application compared to chemigation. The present study highlights the importance of selecting appropriate insecticide application methods in controlling S. albicosta larvae.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bea84699-094e-49e0-a619-50f8d9a52f37', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'CRISPR/Cas Technology in Insect Insecticide Resistance', 'Xu Q, Wang M, Zeng J, Sun H, Wei X, Jiang H, Shentu X, Sun D', 2025, 'Insects', '10.3390/insects16040345', 'https://doi.org/10.3390/insects16040345', 'https://europepmc.org/articles/PMC12027801?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Chemicals and biological insecticides play a crucial role as pest management strategies in modern agriculture and forestry. However, their excessive and unreasonable use inevitably leads to varying degrees of resistance among insect populations, which seriously affects the sustainability of insecticide use. One primary reason for this resistance is alterations or mutations in insect gene expression. One class of genes encodes proteins that serve as critical targets for insecticides to exert their toxic effects in insects, while another class of genes encodes proteins involved in the detoxification process of insecticides within insects. Reverse genetics has become a vital research tool for studying the molecular mechanisms underlying changes and mutations in these target genes and their impact on insect resistance. The advent of CRISPR (Clustered Regularly Interspaced Short Palindromic Repeats) and the CRISPR-associated gene Cas as gene-editing technologies has significantly advanced our understanding of how insects adapt to and resist insecticides. This article aims to provide a comprehensive and objective review of the progress made using the CRISPR/Cas system in various arthropods within the field of pest control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ca05e598-66ca-4837-99a9-aa0960764e9c', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'dsABCC1 and dsABCC3 Enhance the Insecticidal Activity of Chlorantraniliprole in Rice Stem Borer Chilo suppressalis', 'Qiwen Pu, Xin Mao, Yichi Zhang, Ali Hasnain, Moxian Chen, Chunqing Zhao', 2026, 'Agronomy', '10.3390/agronomy16111080', 'https://doi.org/10.3390/agronomy16111080', 'https://www.mdpi.com/2073-4395/16/11/1080', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The rice stem borer (RSB), Chilo suppressalis, is one of the most destructive rice pests in China and chlorantraniliprole has been extensively used for its control over the past decade. However, the continuous and intensive application of chlorantraniliprole has accelerated the development of resistant RSB populations in field, thereby threatening sustainable rice production. In this study, a field resistant strain of RSB exhibited a 181.76-fold resistance level to chlorantraniliprole compared to a susceptible strain. To explore the potential involvement of ATP-binding cassette (ABC) transporters in chlorantraniliprole resistance, four candidate ABC transporter genes (CsABCC1, CsABCC3, CsABCA3 and CsABCD2) were analyzed in resistant and susceptible strains. Compared to the susceptible strain, the expressional levels of CsABCC1 and CsABCC3 were significantly upregulated by 1.58- and 1.38-fold, respectively, whereas of CsABCA3 and CsABCD2 showed non-significant differences in the resistant strain. RNA interference assays demonstrated that naked dsRNA induced only limited gene silencing, while chitosan-mediated dsRNA delivery significantly improved RNAi efficiency. Following feeding with chitosan-coated dsCsABCC1 and dsCsABCC3, the expression levels of both genes were reduced by 44.63% and 38.49%, respectively, relative to the control and the larval mortality increased following chlorantraniliprole treatment to 63.33% and 56.67%, respectively. In addition, silencing CsABCC1 caused a greater reduction in larval weight after insecticide treatment. These findings indicated that CsABCC1 and CsABCC3 are involved in chlorantraniliprole detoxification and may contribute to resistance. Overall, this study provides evidence for the functional involvement of ABC transporters in chlorantraniliprole resistance and highlights chitosan-mediated RNAi as a promising complementary approach for resistance management within integrated pest management programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f2c74e19-2708-4604-8c95-05e6fd6db9a6', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Integrating Soil Silicon Amendment into Management Programs for Insect Pests of Drill-Seeded Rice', 'Villegas JM, Way MO, Pearson RA, Stout MJ', 2017, 'Plants (Basel, Switzerland)', '10.3390/plants6030033', 'https://doi.org/10.3390/plants6030033', 'https://europepmc.org/articles/PMC5620589?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Silicon soil amendment has been shown to enhance plant defenses against insect pests. Rice is a silicon-accumulating graminaceous plant. In the southern United States, the rice water weevil and stem borers are important pests of rice. Current management tactics for these pests rely heavily on the use of insecticides. This study evaluated the effects of silicon amendment when combined with current management tactics for these rice insect pests in the field. Field experiments were conducted from 2013 to 2015. Rice was drill-planted in plots subjected to factorial combinations of variety (conventional and hybrid), chlorantraniliprole seed treatment (treated and untreated), and silicon amendment (treated and untreated). Silicon amendment reduced densities of weevil larvae on a single sampling date in 2014, but did not affect densities of whiteheads caused by stem borers. In contrast, insecticidal seed treatment strongly reduced densities of both weevil larvae and whiteheads. Higher densities of weevil larvae were also observed in the hybrid variety in 2014, while higher incidences of whiteheads were observed in the conventional variety in 2014 and 2015. Silicon amendment improved rice yields, as did chlorantraniliprole seed treatment and use of the hybrid variety.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a772d60d-5aa6-4870-86b7-31b55c63901b', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Dynamics of pesticide residues in soils during the growing season: a case study in peach orchards, east-central Portugal', 'Veloso A, Silva V, Osman R, Simões MP, do Carmo Horta M, Geissen V', 2025, 'Environmental monitoring and assessment', '10.1007/s10661-025-13698-z', 'https://doi.org/10.1007/s10661-025-13698-z', 'https://europepmc.org/articles/PMC11825562?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Permanent crops rely heavily on pesticides. Their short-term behaviour has already been characterised under laboratory conditions. However, their degradation in the field is still poorly understood. Furthermore, studies that relate pesticide residues in soil with their application history are still scarce, despite their relevance for inferring the historical and diffuse dimensions of pollution. This work explores the spatial and temporal dynamics of pesticide residues in soil under the light of their application records and the accuracy of the predicted environmental concentrations (PEC). To achieve these purposes, 270 soil samples were collected at 5 sampling times over the 2022 growing season, in 18 peach orchards from east-central Portugal. Moreover, the data extracted from the application records was used to obtain predicted levels which were compared with the measured results. A total of 37 residues were analysed. Overall, 32 of these were detected back in, at least, one sample. Glyphosate and AMPA were the most frequently found and had the highest median concentrations. The comparison between predicted and measured environmental concentrations (MEC) suggests that pesticide decay was generally slower than expected. Glyphosate, AMPA, fluopyram and tebuconazole showed a high potential for resulting in background concentrations in soil. Our results highlight the need for regular and comprehensive monitoring, being recommended long-term assessments of the persistence and fate of pesticides under realistic conditions. Furthermore, our results also stress the necessity of more studies on reasons for PEC-MEC mismatch, a factor of concern considering the regulatory relevance of PEC values.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('66b4526b-ad4c-4d8d-ad9b-3c87fb691657', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Entomopathogenic Fungi: An Eco-Friendly Synthesis of Sustainable Nanoparticles and Their Nanopesticide Properties', 'Bihal R, Al-Khayri JM, Banu AN, Kudesia N, Ahmed FK, Sarkar R, Arora A, Abd-Elsalam KA', 2023, 'Microorganisms', '10.3390/microorganisms11061617', 'https://doi.org/10.3390/microorganisms11061617', 'https://europepmc.org/articles/PMC10302739?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'The agricultural industry could undergo significant changes due to the revolutionary potential of nanotechnology. Nanotechnology has a broad range of possible applications and advantages, including insect pest management using treatments based on nanoparticle insecticides. Conventional techniques, such as integrated pest management, are inadequate, and using chemical pesticides has negative consequences. As a result, nanotechnology would provide ecologically beneficial and effective alternatives for insect pest control. Considering the remarkable traits they exhibit, silver nanoparticles (AgNPs) are recognized as potential prospects in agriculture. Due to their efficiency and great biocompatibility, the utilization of biologically synthesized nanosilver in insect pest control has significantly increased nowadays. Silver nanoparticles have been produced using a wide range of microbes and plants, which is considered an environmentally friendly method. However, among all, entomopathogenic fungi (EPF) have the most potential to be used in the biosynthesis of silver nanoparticles with a variety of properties. Therefore, in this review, different ways to get rid of agricultural pests have been discussed, with a focus on the importance and growing popularity of biosynthesized nanosilver, especially silver nanoparticles made from fungi that kill insects. Finally, the review highlights the need for further studies so that the efficiency of bio-nanosilver could be tested for field application and the exact mode of action of silver nanoparticles against pests can be elucidated, which will eventually be a boon to the agricultural industry for putting a check on pest populations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04c4edd0-3f45-4c29-aa8f-c102fcf037ce', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Exposure to Cyantraniliprole Adversely Impacts Fitness of Harmonia axyridis: Acute Toxicity and Sublethal Effects on Development, Fecundity and Antioxidant Responses', 'Zhang T, Yuan Y, Teng H, Wang D, Gu H', 2024, 'Insects', '10.3390/insects15100773', 'https://doi.org/10.3390/insects15100773', 'https://europepmc.org/articles/PMC11508540?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Extensive utilization of pesticides and their persistent residues inadvertently pose threats to the effectiveness and fitness of biocontrol agents in agroecosystems. However, these ecological consequences are generally disregarded when executing integrated pest management strategies (IPM). Cyantraniliprole (CNAP) serves as a wide-spectrum diamide insecticide and its sublethal effects have been well characterized on multiple insect pests, whereas its impacts on beneficial natural enemies remain unfathomed. Herein we exposed Harmonia axyridis, a predacious generalist, to lethal and sublethal concentrations of CNAP via dipping treatment (egg stage) and topical applications (1st-instar stage + adult stage). The acute toxicity tests revealed that LC50 of CNAP were 90.11, 86.11 and 240.50 mg/L against embryos, 1st instar nymphs and female adults, respectively, with safety factors ranging from 1.14 to 5.34, suggesting its medium toxicity for H. axyridis and larval stage was the most susceptible. The embryonic, larval and pupal durations of coccinellids ecdysed from CNAP-treated eggs and 1st instars were all elongated under sublethal concentrations, of which LC30 triggered more pronounced and significant retardations relative to control. Besides, exposed coccinellids displayed substantially diminished pupal mass and pupation rate, most notably for insects molted from the 1st-instar stage upon CNAP sublethal treatments. With respect to reproductive performance, LC10 and LC30 of CNAP all significantly suppressed female fecundity, as evidenced by reduced vitellin content, a prolonged pre-oviposition period (POP), mitigated laid eggs and the egg hatching rate. Specifically, there existed positive correlations between vitellin level (Vn) and number of eggs deposited by per female, indicative of CNAP affecting fecundity by regulation of Vn. In addition, the antioxidant system was also profoundly disrupted by CNAP, with compromised POD activity at different concentrations over time and induced hormesis of SOD/CAT activities post LC10 exposure. Activities of SOD and TAC were enhanced to exert protective functions during the first 48 h, while defense collapsed at 72 h following LC30 treatments that depleted all enzymatic activities. We speculated that fitness trade-offs may occur between reproductive capacity and antioxidant defenses to sustain physiological homeostasis in response to CNAP stress. Collectively, this study evaluated the ecological risk of CNAP and unmasked its adverse implications for overall fitness of H. axyridis, which highlighted rational application of agrochemicals to conserve biocontrol agents when implementing IPM strategies for sustainable pest control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c13a312-54bc-430e-a988-3eaa4d6fbf6d', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Expression and Functional Analysis of Two Cytochrome P450 Monooxygenase Genes and a UDP-Glycosyltransferase Gene Linked with Thiamethoxam Resistance in the Colorado Potato Beetle', 'Wang Y, Tian Y, Zhou D, Fang J, Cao J, Shi C, Lei Y, Fu K', 2024, 'Insects', '10.3390/insects15080559', 'https://doi.org/10.3390/insects15080559', 'https://europepmc.org/articles/PMC11354365?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'Cytochrome P450 monooxygenases (P450s) and UDP-glycosyltransferases (UGTs) are involved in the evolution of insecticide resistance. Leptinotarsa decemlineata (Say), the Colorado potato beetle (CPB), is a notorious insect that has developed resistance to various insecticides including neonicotinoids. This study investigated whether the differentially expressed P450 genes CYP9Z140 and CYP9AY1 and UGT gene UGT321AP1, found in our transcriptome results, conferred resistance to thiamethoxam in L. decemlineata. Resistance monitoring showed that the sampled field populations of L. decemlineata adults collected from Urumqi City and Qapqal, Jimsar, and Mulei Counties of Xinjiang in 2021-2023 developed low levels of resistance to thiamethoxam with resistance ratios ranging from 6.66- to 9.52-fold. Expression analyses indicated that CYP9Z140, CYP9AY1, and UGT321AP1 were significantly upregulated in thiamethoxam-resistant populations compared with susceptible populations. The expression of all three genes also increased significantly after thiamethoxam treatment compared with the control. Spatiotemporal expression patterns showed that the highest expression of CYP9Z140 and CYP9AY1 occurred in pupae and the midgut, whereas UGT321AP1 was highly expressed in adults and Malpighian tubules. Knocking down all three genes individually or simultaneously using RNA interference increased the sensitivity of adult L. decemlineata to thiamethoxam. These results suggest that overexpression of CYP9Z140, CYP9AY1, and UGT321AP1 contributes to the development of thiamethoxam resistance in L. decemlineata and provides a scientific basis for improving new resistance management of CPB.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79d17cec-edf8-4a37-b6b4-71bab8a874f3', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Field evaluation of synthetic and neem-derived alternative insecticides in developing action thresholds against cauliflower pests', 'Shah FM, Razaq M, Ali Q, Shad SA, Aslam M, Hardy ICW', 2019, 'Scientific reports', '10.1038/s41598-019-44080-y', 'https://doi.org/10.1038/s41598-019-44080-y', 'https://europepmc.org/articles/PMC6531477?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Synthetic chemical pesticides can enhance crop yields but also have undesired effects. Alternative ''botanical insecticides'' may also have non-target effects on pollinators and biocontrol services. Employing action thresholds (ATs) can reduce pesticide (whether synthetic or botanical) use compared to fixed-interval applications. Here the azadirachtin-based botanical formulation NeemAzal and a neem seed extract (NSE) were evaluated in field spraying trials alongside commonly-used synthetics (Voliam Flexi [chlorentraniliprole plus thiamethoxam] and imidacloprid) in developing ATs for the regular and cosmopolitan cauliflower pests Brevicoryne brassicae, Plutella xylostella and Spodoptera litura. We considered the size of the S. litura larvae infesting the crop in order to derive ATs. ATs per plant were higher for NeemAzal (0.55 larvae for P. xylostella and 3 larvae for large-sized S. litura) than for Voliam Flexi (0.30 larvae for P. xylostella and 0.80 larvae for S. litura) but were similar for B. brassicae (50 individuals). Higher ATs when using azadirachtin were associated with the diverse modes of action of botanicals, for instance NeemAzal and NSE deterred oviposition of S. litura. Although the exact values of ATs are likely to have regional limits, our approach can be applied for determining ATs against common lepidopteran and aphid pests in many other vegetable crop agro-ecosystems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c3f60cd-7b67-46dc-9944-9dfa717f5325', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'miRNA Dynamics for Pest Management: Implications in Insecticide Resistance', 'Mahalle RM, Mota-Sanchez D, Pittendrigh BR, Kim YH, Seong KM', 2024, 'Insects', '10.3390/insects15040238', 'https://doi.org/10.3390/insects15040238', 'https://europepmc.org/articles/PMC11049821?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Utilizing chemical agents in pest management in modern agricultural practices has been the predominant approach since the advent of synthetic insecticides. However, insecticide resistance is an emerging issue, as pest populations evolve to survive exposure to chemicals that were once effective in controlling them, underlining the need for advanced and innovative approaches to managing pests. In insects, microRNAs (miRNAs) serve as key regulators of a wide range of biological functions, characterized by their dynamic expression patterns and the ability to target genes. Recent studies are increasingly attributed to the significance of miRNAs in contributing to the evolution of insecticide resistance in numerous insect species. Abundant miRNAs have been discovered in insects using RNA sequencing and transcriptome analysis and are known to play vital roles in regulation at both the transcriptional and post-transcriptional levels. Globally, there is growing research interest in the characterization and application of miRNAs, especially for their potential role in managing insecticide resistance. This review focuses on how miRNAs contribute to regulating insecticide resistance across various insect species. Furthermore, we discuss the gain and loss of functions of miRNAs and the techniques for delivering miRNAs into the insect system. The review emphasizes the application of miRNA-based strategies to studying their role in diminishing insecticide resistance, offering a more efficient and lasting approach to insect management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0040cee8-ad6d-4afb-97d9-bfd7d1823b34', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Monarch Butterflies in Western North America: A Holistic Review of Population Trends, Ecology, Stressors, Resilience and Adaptation', 'James DG', 2024, 'Insects', '10.3390/insects15010040', 'https://doi.org/10.3390/insects15010040', 'https://europepmc.org/articles/PMC10817040?pdf=render', NULL, NULL, 29, NULL, 'northern_plains', 3, 'cc by', 'Monarch butterfly populations in western North America suffered a substantial decline, from millions of butterflies overwintering in California in the 1980s to less than 400,000 at the beginning of the 21st century. The introduction of neonicotinoid insecticides in the mid-1990s and their subsequent widespread use appears to be the most likely major factor behind this sudden decline. Habitat loss and unfavorable climates (high temperatures, aridity, and winter storms) have also played important and ongoing roles. These factors kept overwintering populations stable but below 300,000 during 2001-2017. Late winter storm mortality and consequent poor spring reproduction drove winter populations to less than 30,000 butterflies during 2018-2019. Record high temperatures in California during the fall of 2020 appeared to prematurely terminate monarch migration, resulting in the lowest overwintering population (1899) ever recorded. Many migrants formed winter-breeding populations in urban areas. Normal seasonal temperatures in the autumns of 2021 and 2022 enabled overwintering populations to return to around the 300,000 level, characteristic of the previous two decades. Natural enemies (predators, parasitoids, parasites, and pathogens) may be important regional or local drivers at times but they are a consistent and fundamental part of monarch ecology. Human interference (capture, rearing) likely has the least impact on monarch populations. The rearing of monarch caterpillars, particularly by children, is an important human link to nature that has positive ramifications for insect conservation beyond monarch butterflies and should be encouraged.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d145ad81-fee2-4c49-8a1a-73a78965645b', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Monarch Butterfly Ecology, Behavior, and Vulnerabilities in North Central United States Agricultural Landscapes', 'Grant TJ, Fisher KE, Krishnan N, Mullins AN, Hellmich RL, Sappington TW, Adelman JS, Coats JR', 2022, 'Bioscience', '10.1093/biosci/biac094', 'https://doi.org/10.1093/biosci/biac094', 'https://europepmc.org/articles/PMC9699720?pdf=render', NULL, NULL, 56, NULL, 'other', 1, 'cc by-nc', 'The North American monarch butterfly (Danaus plexippus) is a candidate species for listing under the Endangered Species Act. Multiple factors are associated with the decline in the eastern population, including the loss of breeding and foraging habitat and pesticide use. Establishing habitat in agricultural landscapes of the North Central region of the United States is critical to increasing reproduction during the summer. We integrated spatially explicit modeling with empirical movement ecology and pesticide toxicology studies to simulate population outcomes for different habitat establishment scenarios. Because of their mobility, we conclude that breeding monarchs in the North Central states should be resilient to pesticide use and habitat fragmentation. Consequently, we predict that adult monarch recruitment can be enhanced even if new habitat is established near pesticide-treated crop fields. Our research has improved the understanding of monarch population dynamics at the landscape scale by examining the interactions among monarch movement ecology, habitat fragmentation, and pesticide use.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4ba571ff-0f34-4ee4-b0f1-27c14b9ab87b', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Nano-Enabled Insecticides for Efficient Pest Management: Definition, Classification, Synergistic Mechanism, and Safety Assessment', 'Wei Y, Chen J, Dong M, Yin M, Shen J, Gao L, Yan S', 2025, 'Nanomaterials (Basel, Switzerland)', '10.3390/nano15131050', 'https://doi.org/10.3390/nano15131050', 'https://europepmc.org/articles/PMC12250691?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'The widespread use of pesticides plays a vital role in safeguarding crop yields and ensuring global food security. However, their improper application has led to serious challenges, including environmental pollution, pesticide residues, and increasing insect resistance. Traditional chemical pesticides are no longer sufficient to meet the demands for sustainable modern agriculture. Recent advances in nanotechnology offer innovative strategies for improving pesticide delivery, bioavailability, and selectivity. This review systematically summarizes the current progress in nano-insecticides, including their definitions, classification, preparation techniques, synergistic mechanisms, insecticidal performance, and safety evaluation. In addition, emerging strategies, such as multi-stimuli responsive systems, co-delivery with multiple agents or genetic materials, and integration with biological control, are discussed. Finally, future perspectives are proposed to guide the design/development of intelligent, efficient, and eco-friendly nano-insecticides for sustainable pest management in modern agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('93def904-1184-49ec-9c15-bd0c2f394548', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Physiological and Molecular Mechanisms of Lepidopteran Insects: Genomic Insights and Applications of Genome Editing for Future Research', 'Niu D, Zhao Q, Xu L, Lin K', 2024, 'International journal of molecular sciences', '10.3390/ijms252212360', 'https://doi.org/10.3390/ijms252212360', 'https://europepmc.org/articles/PMC11594828?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Lepidopteran insects are a major threat to global agriculture, causing significant crop losses and economic damage. Traditional pest control methods are becoming less effective due to the rapid evolution of insecticide resistance. This study explores the current status and genomic characteristics of 1315 Lepidopteran records, alongside an overview of relevant research, utilizing advanced functional genomics techniques, including RNA-seq and CRISPR/Cas9 gene-editing technologies to uncover the molecular mechanisms underlying insecticide resistance. Our genomic analysis revealed significant variability in genome size, assembly quality, and chromosome number, which may influence species'' biology and resistance mechanisms. We identified key resistance-associated genes and pathways, including detoxification and metabolic pathways, which help these insects evade chemical control. By employing CRISPR/Cas9 gene-editing techniques, we directly manipulated resistance-associated genes to confirm their roles in resistance, demonstrating their potential for targeted interventions in pest management. These findings emphasize the value of integrating genomic data into the development of effective and sustainable pest control strategies, reducing reliance on chemical insecticides and promoting environmentally friendly integrated pest management (IPM) approaches. Our study highlights the critical role of functional genomics in IPM and its potential to provide long-term solutions to the growing challenge of Lepidopteran resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc5c5842-3504-4211-97c6-3b67430cb86d', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Quantitative genetic analysis of diamide resistance in Australian Spodoptera litura (Fabricius) (Lepidoptera: Noctuidae)', 'L. J. Bird, N. M. Dunn', 2025, 'Scientific Reports', '10.1038/s41598-025-12292-0', 'https://doi.org/10.1038/s41598-025-12292-0', 'https://doi.org/10.1038/s41598-025-12292-0', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Spodoptera litura is a major insect pest of horticulture, cotton and legume crops which has developed resistance to insecticides from many chemical classes. Chlorantraniliprole is an important option for selective control of S. litura, and in 2023 a population established from grain legume fields in northwest Western Australia (BM28x) was found to have > 1000-fold resistance to chlorantraniliprole compared with laboratory reference strain (KSL). Following its establishment in the laboratory, the BM28x strain was found to be homozygous for resistance to chlorantraniliprole and subsequent characterisation by quantitative genetic analysis showed that resistance was autosomal, incompletely recessive (D LC = 0.185) and conferred by one or a few closely linked loci. Chlorantraniliprole resistance in the BM28x strain conferred major cross-resistance to cyantraniliprole (262-fold) and tetraniliprole (591-fold). However, there was minimal cross-resistance (≤ 3.3-fold) in the BM28x strain to broflanilide, emamectin benzoate, spinetoram, methoxyfenozide and the Vip3A protein expressed by the bacterium Bacillus thuringiensis, indicating that resistance could be managed effectively using chemical rotational strategies which incorporate transgenic technologies. Inhibition bioassays using the synergists piperonyl butoxide, triphenyl phosphate and diethyl maleate indicate that metabolic detoxification is not involved in resistance to chlorantraniliprole in the BM28x strain. The implications of high level diamide resistance for management of Australian S. litura is discussed.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c637351-d9ca-44fd-863d-bb383a797c23', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Recent Advances in Nanoparticle-Mediated Co-Delivery System: A Promising Strategy in Medical and Agricultural Field', 'Li M, Sun X, Yin M, Shen J, Yan S', 2023, 'International journal of molecular sciences', '10.3390/ijms24065121', 'https://doi.org/10.3390/ijms24065121', 'https://europepmc.org/articles/PMC10048901?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Drug and gene delivery systems mediated by nanoparticles have been widely studied for life science in the past decade. The application of nano-delivery systems can dramatically improve the stability and delivery efficiency of carried ingredients, overcoming the defects of administration routes in cancer therapy, and possibly maintaining the sustainability of agricultural systems. However, delivery of a drug or gene alone sometimes cannot achieve a satisfactory effect. The nanoparticle-mediated co-delivery system can load multiple drugs and genes simultaneously, and improve the effectiveness of each component, thus amplifying efficacy and exhibiting synergistic effects in cancer therapy and pest management. The co-delivery system has been widely reported in the medical field, and studies on its application in the agricultural field have recently begun to emerge. In this progress report, we summarize recent progress in the preparation and application of drug and gene co-delivery systems and discuss the remaining challenges and future perspectives in the design and fabrication.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec5ddee9-59d7-4112-b27a-55ee48a435e0', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Resistance Affects the Field Performance of Insecticides Used for Control of Choristoneura rosaceana in Michigan Apples and Cherries', 'Abdulwahab M. Hafez, David Mota-Sanchez, Christine Vandervoort, John C. Wise', 2021, 'Insects', '10.3390/insects12090846', 'https://doi.org/10.3390/insects12090846', 'https://www.mdpi.com/2075-4450/12/9/846', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Field-based residual bioassays and residue analysis were conducted to assess the field performance and toxicity longevity of different insecticides that had previously been associated with resistance of Choristoneura rosaceana populations collected from apple and cherry orchards. In this study, 12–24 h-old larvae of apple and cherry populations were exposed to apple and cherry leaf samples, respectively, at post-application intervals and a susceptible population served as a reference of each. In the apple and cherry trials, the order of residual longevity of insecticides that effectively controlled the tested populations was as follows: bifenthrin and spinetoram (apple: 14, cherry 21-day post-application), phosmet (apple: 7, cherry 14-day post-application), chlorantraniliprole (apple: 7-day post-application), and indoxacarb and emamectin benzoate (apple: 1, cherry 7-day post-application). Compared to the susceptible population, the resistant populations resulted in a measurable loss of field performance, or “practical resistance”, for the insecticides emamectin benzoate (at 7-day post-application), chlorantraniliprole (at 21-day post-application), and indoxacarb (at all post-application intervals) in the apple trials, while in cherry trial just indoxacarb at 7-day post-application showed a reduced efficacy. In terms of long-lasting residues, only chlorantraniliprole and indoxacarb maintained measurable leaf residues over all post-application intervals while the leaf residues of the other compounds had largely degraded within the first 7 days. These findings can help fruit growers make adjustments to their spray/re-application intervals and optimally utilize important chemical tools in their integrated pest management programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e3fe446e-d6f6-4faf-ad68-a18aa9919dbe', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Spraying Cry1A.105 + Cry2Ab2 Bt sweet corn has marginal benefit for Helicoverpa zea (Lepidoptera: Noctuidae) suppression', 'Huseth AS, Hamby KA, Ill S, Young A, Nault BA, Mahas JW, Kuhar T, Currin B', 2026, 'Journal of economic entomology', '10.1093/jee/toag132', 'https://doi.org/10.1093/jee/toag132', 'https://europepmc.org/articles/PMC13268527?pdf=render', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'Management of corn earworm, Helicoverpa zea Boddie (Lepidoptera: Noctuidae) in fresh-market sweet corn requires multiple, precisely timed applications of effective insecticides. An alternative method to manage H. zea is sweet corn hybrids that express Bacillus thuringiensis (Bt) toxins, but this approach has become limited because H. zea populations have developed resistance to multiple Bt toxins. We hypothesized that spraying a marginally performing Bt hybrid with an effective insecticide would provide a level of H. zea control that neither approach could achieve independently. To test this idea, we compared H. zea control using Cry1A.105+Cry2Ab2 Bt sweet corn treated with chlorantraniliprole following either a 7, 4, or 2-3 day silk-stage spray schedule with control following the same spray schedule and the non-Bt isoline. This study was conducted in high and low H. zea pressure environments in 2024 and 2025. Results showed that the combination of insecticidal sprays and the Bt hybrid provided minimal additional benefit relative to the sprays alone. We did find that weekly applications of chlorantraniliprole resulted in measurable reductions in H. zea damage, but the benefit of additional sprays dissipated with increasing frequency. This effect was most apparent where H. zea pressure was low and there was no statistical separation among spray interval treatments. Our results highlight the challenge of producing undamaged sweet corn, even when a Bt hybrid is treated intensively with an insecticide. Outcomes show that existing action thresholds may need revision to include additional variables that are sensitive to current input and damage costs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('809863d4-2916-4a45-98e1-b8c252ce09be', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Gibberellin Oxidase Gene Family in L. chinense: Genome-Wide Identification and Gene Expression Analysis', 'Hu L, Wang P, Hao Z, Lu Y, Xue G, Cao Z, Qu H, Cheng T', 2021, 'International journal of molecular sciences', '10.3390/ijms22137167', 'https://doi.org/10.3390/ijms22137167', 'https://europepmc.org/articles/PMC8268368?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'GAox is a key enzyme for the transformation of gibberellins, and belongs to the 2-ketoglutarate dependent dioxygenase gene family (2ODD). However, a systematic analysis of GAox in the angiosperm L. chinense has not yet been reported. Here, we identified all LcGAox gene family members in L. chinense, which were classified into the three subgroups of GA20ox, C19GA2ox, and C20GA2ox. Comparison of the gene structure, conserve motifs, phylogenetic relationships, and syntenic relationships of gibberellin oxidase gene families in different species indicated that the gene functional differences may be due to the partial deletion of their domains during evolution. Furthermore, evidence for purifying selection was detected between orthologous GAox genes in rice, grape, Arabidopsis, and L. chinense. Analysis of the codon usage patterns showed that mutation pressure and natural selection might have induced codon usage bias in angiosperms; however, the LcGAox genes in mosses, lycophytes, and ambarella plants exhibited no obvious codon usage preference. These results suggested that the gibberellin oxidase genes were more primitive. The gene expression pattern was analyzed in different organs subjected to multiple abiotic stresses, including GA, abscisic acid (ABA), and chlormequat (CCC) treatment, by RNA-seq and qRT-PCR, and the stress- and phytohormone-responsive cis-elements were counted. The results showed that the synthesis and decomposition of GA were regulated by different LcGAox genes in the vegetative and reproductive organs of L. chinense, and only LcGA2ox1,4, and 7 responded to the NaCl, polyethylene glycol, 4 °C, GA, ABA, and CCC treatment in the roots, stems, and leaves of seedlings at different time periods, revealing the potential role of LcGAox in stress resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('77b104b0-d582-42bd-bff7-d9404408b9be', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Structural and Functional Insights into Methuselah Genes of Plutella xylostella (Lepidoptera: Plutellidae): Evolutionary Adaptations and Their Responses to Chlorantraniliprole', 'Maryam Zolfaghari, Fei Yin, Samina Shabbir, Qichun Chen, Yong Xiao, Zhengke Peng, Zhen-Yu Li, Myron P. Zalucki', 2025, 'Insects', '10.3390/insects16111092', 'https://doi.org/10.3390/insects16111092', 'https://www.mdpi.com/2075-4450/16/11/1092', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'G protein-coupled receptors (GPCRs) are considered the largest and most variable family of transmembrane receptors regulating physiological processes such as toxicological responses and insecticide resistance development. The present study investigated the responses of Methuselah (Mth), belonging to GPCR family B in the Diamondback Moth (DBM), Plutella xylostella, to chlorantraniliprole (CAP). Genome-wide identification and phylogenetic analysis of Pxmth genes revealed their evolutionary relationships and functional classifications. Expression profiling demonstrated significant overexpression of Pxmth2 in the CAP-resistant strain. Additionally, the tertiary and secondary structures of Pxmth2 were characterized, providing insights into its functional role. Silencing Pxmth2 via RNA interference (RNAi) reduced resistance of DBM to CAP and suppressed downstream stress-associated genes (CYP6B6, CYP6B7, CYP6BF1), increasing susceptibility to the insecticide. The function of Pxmth2 was further explored using a transgenic line of Drosophila melanogaster engineered to overexpress the gene; flies overexpressing Pxmth2 exhibited a significantly increased resistance to CAP compared to controls. These findings indicate that Pxmth2 contributes to CAP resistance in DBM and highlights potential molecular targets for improving pest management strategies.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c74a4b77-7850-4e51-b015-a84bb6f2dcf9', 'd772c028-aaca-4843-9e95-4a1fec13baac', 'Transcriptome analysis of chlorantraniliprole resistance development in the diamondback moth Plutella xylostella.', 'Qingsheng Lin, Fengliang Jin, Zhendi Hu, Huanyu Chen, Fei Yin, Zhenyu Li, Xiaolin Dong, Deyong Zhang', 2013, 'PLoS ONE', '10.1371/journal.pone.0072314', 'https://doi.org/10.1371/journal.pone.0072314', 'http://europepmc.org/articles/PMC3748044?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'BACKGROUND: The diamondback moth Plutella xyllostella has developed a high level of resistance to the latest insecticide chlorantraniliprole. A better understanding of P. xylostella''s resistance mechanism to chlorantraniliprole is needed to develop effective approaches for insecticide resistance management. PRINCIPAL FINDINGS: To provide a comprehensive insight into the resistance mechanisms of P. xylostella to chlorantraniliprole, transcriptome assembly and tag-based digital gene expression (DGE) system were performed using Illumina HiSeq™ 2000. The transcriptome analysis of the susceptible strain (SS) provided 45,231 unigenes (with the size ranging from 200 bp to 13,799 bp), which would be efficient for analyzing the differences in different chlorantraniliprole-resistant P. xylostella stains. DGE analysis indicated that a total of 1215 genes (189 up-regulated and 1026 down-regulated) were gradient differentially expressed among the susceptible strain (SS) and different chlorantraniliprole-resistant P. xylostella strains, including low-level resistance (GXA), moderate resistance (LZA) and high resistance strains (HZA). A detailed analysis of gradient differentially expressed genes elucidated the existence of a phase-dependent divergence of biological investment at the molecular level. The genes related to insecticide resistance, such as P450, GST, the ryanodine receptor, and connectin, had different expression profiles in the different chlorantraniliprole-resistant DGE libraries, suggesting that the genes related to insecticide resistance are involved in P. xylostella resistance development against chlorantraniliprole. To confirm the results from the DGE, the expressional profiles of 4 genes related to insecticide resistance were further validated by qRT-PCR analysis. CONCLUSIONS: The obtained transcriptome information provides large gene resources available for further studying the resistance development of P. xylostella to pesticides. The DGE data provide comprehensive insights into the gene expression profiles of the different chlorantraniliprole-resistant stains. These genes are specifically related to insecticide resistance, with different expressional profiles facilitating the study of the role of each gene in chlorantraniliprole resistance development.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4cb653ae-d2df-44df-a606-132250ec099f', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Breeding Bread-Making Wheat Varieties for Organic Farming Systems: The Need to Target Productivity, Robustness, Resource Use Efficiency and Grain Quality Traits', 'Rempelos L, Wang J, Sufar EK, Almuayrifi MSB, Knutt D, Leifert H, Leifert A, Wilkinson A', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12061209', 'https://doi.org/10.3390/foods12061209', 'https://europepmc.org/articles/PMC10048768?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Agronomic protocols (rotation, tillage, fertilization and crop protection) commonly used in organic and conventional crop production differ significantly and there is evidence that modern varieties developed for conventional high-input farming systems do not have the combination of traits required for optimum performance in organic farming systems. Specifically, there is evidence that prohibition on the use of water-soluble, mineral N, P and K fertilizers and synthetic pesticide inputs in organic farming results in a need to revise both breeding and selection protocols. For organic production systems, the focus needs to be on the following: (i) traits prioritized by organic farmers such as high nutrient use efficiency from organic fertilizer inputs, competitiveness against weeds, and pest and disease resistance, (ii) processing quality parameters defined by millers and bakers and (iii) nutritional quality parameters demanded by organic consumers. In this article, we review evidence from variety trials and factorial field experiments that (i) studied to what extent there is a need for organic farming focused breeding programs, (ii) investigated which traits/trait combinations should be targeted in these breeding programs and/or (iii) compared the performance of modern varieties developed for the conventional sector with traditional/older varieties favored by organic farmers and/or new varieties developed in organic farming focused breeding programs. Our review focuses on wheat because there have been organic and/or low-input farming focused wheat breeding programs for more than 20 years in Europe, which has allowed the performance of varieties/genotypes from organic/low-input and conventional farming focused breeding programs to be compared.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0fe0b2c9-d9a4-4390-a6f1-c3d38f2d9ef7', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Cultivar × Management Interaction to Reduce Lodging and Improve Grain Yield of Irrigated Spring Wheat: Optimising Plant Growth Regulator Use, N Application Timing, Row Spacing and Sowing Date', 'Peake AS, Bell KL, Fischer RA, Gardner M, Das BT, Poole N, Mumford M', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00401', 'https://doi.org/10.3389/fpls.2020.00401', 'https://europepmc.org/articles/PMC7198859?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Severe lodging of irrigated spring-wheat in sub-tropical Australia has previously caused yield loss of between 1.7 and 4.6 t ha-1 (20-60% of potential yield). In response, agronomic management options were assessed for their ability to reduce lodging and increase grain yield, namely plant growth regulators (PGRs), timing of nitrogen (N) application, row spacing and sowing date, in combination with long and short duration cultivars across 15 irrigated environments from 2012 to 2016. Our study identified significant interaction between genotype, environment and agronomic management (G × E × M) for grain yield and lodging, although some combinations of agronomic techniques were broadly applicable across cultivars. PGR application improved grain yield of most cultivars in well-irrigated fields that had more than 120 kg ha-1 N (mineral N + fertiliser N) at sowing, with yield gains of up to 0.5 t ha-1 observed in both lodged and non-lodged fields. However, PGRs had little effect on grain yield when soil + fertiliser N at sowing was less than 80 kg ha-1 N. In-crop N application (compared to sowing N application) often improved grain yield of short duration, lodging resistant cultivars, but reduced the yield of long-duration, lodging susceptible cultivars in some environments. Narrow row spacing of 19 cm had the highest grain yield across cultivars in low lodging environments. At a severely lodged environment, narrow rows were the highest yielding for five out of six cultivars when PGRs were used, but was the highest yielding for only half of the tested cultivars when PGRs were not used. Cultivar × sowing date interaction for grain yield was also associated with the occurrence of lodging. Neither early nor late sowing had a consistent yield benefit across a range of cultivars, as lodging severity varied between sowing date depending on the timing of storm-induced lodging events. Lodging resistant long-duration cultivars had more stable grain yield across environments and increased grain yield in response to early sowing. Further research is needed to determine the optimum management strategy for new cultivars, because farmers do not always choose the most lodging resistant cultivars for reasons of cultivar disease resistance, grain quality and seed availability.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('809a0949-e6b1-44fc-af13-9316f059a201', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Enhanced Surveillance of >1100 Pesticides and Natural Toxins in Food: Harnessing the Capabilities of LC-HRMS for Reliable Identification and Quantification', 'Bessaire T, Savoy MC, Ernest M, Christinat N, Badoud F, Desmarchelier A, Carrères B, Chan WC', 2024, 'Foods (Basel, Switzerland)', '10.3390/foods13193040', 'https://doi.org/10.3390/foods13193040', 'https://europepmc.org/articles/PMC11476049?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'The consequences of climate change along with diverse food regulations and agricultural practices worldwide are complexifying the occurrence and management of chemical contaminants in food. In this context, we present an ultra-high-performance liquid chromatography high-resolution mass spectrometry (LC-HRMS) approach for the simultaneous identification and quantitation of over 1100 pesticide residues, mycotoxins, and plant toxins in cereals and fruits and vegetables. Analytical conditions were optimized to maximize the scope of the targeted molecules, the reliability of compound identification, and quantification performance within a single method. The method was further transferred and validated in another laboratory to assess its ruggedness. Validation according to the SANTE 11312/2021v2 guidelines showed that 92% and 98% of the molecules fulfill the quantification criteria at the lowest validated level in the cereals and fruits and vegetables groups, respectively. Analysis of fifteen certified reference materials led to a 96% satisfactory rate of z-scores confirming method''s competitiveness. Furthermore, the occurrence of these contaminants was studied in 205 cereals and grains samples collected worldwide. The low µg/kg quantification limits make this LC-HRMS method a valuable tool to ensure compliance toward regulations and to screen for non-regulated substances for which occurrence data are crucial for an appropriate risk evaluation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c857e405-c543-457a-8973-7f5112a2c257', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Growth changes of tomato seedlings responding to sodium salt of α-naphthalene acetic acid and potassium salt of fulvic acid', 'Ren M, Mao G, Zheng H, Wang W, Tang Q', 2023, 'Scientific reports', '10.1038/s41598-023-31023-x', 'https://doi.org/10.1038/s41598-023-31023-x', 'https://europepmc.org/articles/PMC10006168?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'In present study, sodium salt of α-naphthalene acetic acid (NA), potassium salt of fulvic acid (KF) and their combinations were applied to the growth substrates of tomato seedlings (Solanum lycopersicum L.) under chilling stress. The changes in aboveground biomass, root attributes, pigment contents, chlorophyll fluorescence, photosynthesis, osmotic regulation substances, and antioxidant enzymes activity of the tomato seedlings in response to NA and KF were investigated. The application of NA, KF and their combination could promote the growth of plant height and stem diameter of tomato seedlings under chilling stress to varying degrees, and improve root characteristics by increasing root volume, root length and root activity, and increase dry matter accumulation. In addition, the combined use of NA and KF improved the seedling leaf chlorophyll content, qP, Fv/Fm, ΦPSII , Pn and increased the activity of antioxidant enzymes in the tomato plants. The above results suggested a synergistic effect between NA and KF to stimulate the seedlings growth and to enhance the ROS scavenging ability of tomato, which has never been reported in previous research before. However, further researches are needed to explore the physiological and molecular mechanism underlying the synergistic effect between NA and KF.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0a68d00c-2f23-4739-98ba-308ed309fa5e', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Improving Lodging Resistance: Using Wheat and Rice as Classical Examples', 'Shah L, Yahya M, Shah SMA, Nadeem M, Ali A, Ali A, Wang J, Riaz MW', 2019, 'International journal of molecular sciences', '10.3390/ijms20174211', 'https://doi.org/10.3390/ijms20174211', 'https://europepmc.org/articles/PMC6747267?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'One of the most chronic constraints to crop production is the grain yield reduction near the crop harvest stage by lodging worldwide. This is more prevalent in cereal crops, particularly in wheat and rice. Major factors associated with lodging involve morphological and anatomical traits along with the chemical composition of the stem. These traits have built up the remarkable relationship in wheat and rice genotypes either prone to lodging or displaying lodging resistance. In this review, we have made a comparison of our conceptual perceptions with foregoing published reports and proposed the fundamental controlling techniques that could be practiced to control the devastating effects of lodging stress. The management of lodging stress is, however, reliant on chemical, agronomical, and genetic factors that are reducing the risk of lodging threat in wheat and rice. But, still, there are many questions remain to be answered to elucidate the complex lodging phenomenon, so agronomists, breeders, physiologists, and molecular biologists require further investigation to address this challenging problem.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a888f97-a291-4fda-a104-151616ac4dbf', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Insights into the recent advances in nano-bioremediation of pesticides from the contaminated soil', 'Singh Y, Saxena MK', 2022, 'Frontiers in microbiology', '10.3389/fmicb.2022.982611', 'https://doi.org/10.3389/fmicb.2022.982611', 'https://europepmc.org/articles/PMC9626991?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'In the present scenario, the uncontrolled and irrational use of pesticides is affecting the environment, agriculture and livelihood worldwide. The excessive application of pesticides for better production of crops and to maintain sufficient food production is leading to cause many serious environmental issues such as soil pollution, water pollution and also affecting the food chain. The efficient management of pesticide use and remediation of pesticide-contaminated soil is one of the most significant challenges to overcome. The efficiency of the current methods of biodegradation of pesticides using different microbes and enzymes depends on the various physical and chemical conditions of the soil and they have certain limitations. Hence, a novel strategy is the need of the hour to safeguard the ecosystem from the serious environmental hazard. In recent years, the application of nanomaterials has drawn attention in many areas due to their unique properties of small size and increased surface area. Nanotechnology is considered to be a promising and effective technology in various bioremediation processes and provides many significant benefits for improving the environmental technologies using nanomaterials with efficient performance. The present article focuses on and discusses the role, application and importance of nano-bioremediation of pesticides and toxic pollutants to explore the potential of nanomaterials in the bioremediation of hazardous compounds from the environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac7f30f8-d498-4213-96c4-96da5904352a', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Manipulating Gibberellin Control Over Growth and Fertility as a Possible Target for Managing Wild Radish Weed Populations in Cropping Systems', 'Groszmann M, Chandler PM, Ross JJ, Swain SM', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00190', 'https://doi.org/10.3389/fpls.2020.00190', 'https://europepmc.org/articles/PMC7096587?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'Wild radish is a major weed of Australian cereal crops. A rapid establishment, fast growth, and abundant seed production are fundamental to its success as an invasive species. Wild radish has developed resistance to a number of commonly used herbicides increasing the problem. New innovative approaches are needed to control wild radish populations. Here we explore the possibility of pursuing gibberellin (GA) biosynthesis as a novel molecular target for controlling wild radish, and in doing so contribute new insights into GA biology. By characterizing ga 3-oxidase (ga3ox) mutants in Arabidopsis, a close taxonomic relative to wild radish, we showed that even mild GA deficiencies cause considerable reductions in growth and fecundity. This includes an explicit requirement for GA biosynthesis in successful female fertility. Similar defects were reproducible in wild radish via chemical inhibition of GA biosynthesis, confirming GA action as a possible new target for controlling wild radish populations. Two possible targeting approaches are considered; the first would involve developing a species-specific inhibitor that selectively inhibits GA production in wild radish over cereal crops. The second, involves making crop species insensitive to GA repression, allowing the use of existing broad spectrum GA inhibitors to control wild radish populations. Toward the first concept, we cloned and characterized two wild radish GA3OX genes, identifying protein differences that appear sufficient for selective inhibition of dicot over monocot GA3OX activity. We developed a novel yeast-based approach to assay GA3OX activity as part of the molecular characterization, which could be useful for future screening of inhibitory compounds. For the second approach, we demonstrated that a subset of GA associated sln1/Rht-1 overgrowth mutants, recently generated in cereals, are insensitive to GA reductions brought on by the general GA biosynthesis inhibitor, paclobutrazol. The location of these mutations within sln1/Rht-1, offers additional insight into the functional domains of these important GA signaling proteins. Our early assessment suggests that targeting the GA pathway could be a viable inclusion into wild radish management programs that warrants further investigation. In drawing this conclusion, we provided new insights into GA regulated reproductive development and molecular characteristics of GA metabolic and signaling proteins.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a3152b42-0b25-4a71-8f77-93baaf2c4dcf', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Oxidative Stress in NAFLD: Role of Nutrients and Food Contaminants', 'Rives C, Fougerat A, Ellero-Simatos S, Loiseau N, Guillou H, Gamet-Payrastre L, Wahli W', 2020, 'Biomolecules', '10.3390/biom10121702', 'https://doi.org/10.3390/biom10121702', 'https://europepmc.org/articles/PMC7767499?pdf=render', NULL, NULL, 64, NULL, 'other', 1, 'cc by', 'Non-alcoholic fatty liver disease (NAFLD) is often the hepatic expression of metabolic syndrome and its comorbidities that comprise, among others, obesity and insulin-resistance. NAFLD involves a large spectrum of clinical conditions. These range from steatosis, a benign liver disorder characterized by the accumulation of fat in hepatocytes, to non-alcoholic steatohepatitis (NASH), which is characterized by inflammation, hepatocyte damage, and liver fibrosis. NASH can further progress to cirrhosis and hepatocellular carcinoma. The etiology of NAFLD involves both genetic and environmental factors, including an unhealthy lifestyle. Of note, unhealthy eating is clearly associated with NAFLD development and progression to NASH. Both macronutrients (sugars, lipids, proteins) and micronutrients (vitamins, phytoingredients, antioxidants) affect NAFLD pathogenesis. Furthermore, some evidence indicates disruption of metabolic homeostasis by food contaminants, some of which are risk factor candidates in NAFLD. At the molecular level, several models have been proposed for the pathogenesis of NAFLD. Most importantly, oxidative stress and mitochondrial damage have been reported to be causative in NAFLD initiation and progression. The aim of this review is to provide an overview of the contribution of nutrients and food contaminants, especially pesticides, to oxidative stress and how they may influence NAFLD pathogenesis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('400ef01a-b170-4274-98ba-6fbd0d9930c7', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Paclobutrazol Improves the Quality of Tomato Seedlings to Be Resistant to Alternaria solani Blight Disease: Biochemical and Histological Perspectives', 'Shalaby TA, Taha NA, Taher DI, Metwaly MM, El-Beltagi HS, Rezk AA, El-Ganainy SM, Shehata WF', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11030425', 'https://doi.org/10.3390/plants11030425', 'https://europepmc.org/articles/PMC8840709?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The production and quality of tomato seedlings needs many growth factors and production requirements besides controlling the phytopathogens. Paclobutrazol (PBZ) has benefit applications in improving crop productivity under biotic stress (Alternaria solani, the causal agent of early blight disease in tomatoes). In the current study, the foliar application of PBZ, at rates of 25, 50, and 100 mg L-1, was evaluated against early blight disease in tomatoes under greenhouse conditions. The roles of PBZ to extend tomato seedling lives and handling in nurseries were also investigated by measuring different the biochemical (leaf enzymes, including catalase and peroxidase) and histological attributes of tomato seedlings. Disease assessment confirmed that PBZ enhanced the quality of tomato seedlings and induced resistance to early blight disease post inoculation, at 7, 14, and 21 days. Higher values in chlorophyll content, enzyme activities, and anatomical features of stem (cuticle thickness) and stomata (numbers and thickness) were recorded, due to applied PBZ. This may support the delay of the transplanting of tomato seedlings without damage. The reason for this extending tomato seedling life may be due to the role of PBZ treatment in producing seedlings to be greener, more compact, and have a better root system. The most obvious finding to emerge from this study is that PBZ has a distinguished impact in ameliorating biotic stress, especially of the early blight disease under greenhouse conditions. Further studies, which consider molecular variables, will be conducted to explore the role of PBZ in more detail.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e507e032-ece3-4a45-a87e-a0e84d6c4457', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Pesticides Identification and Sustainable Viticulture Practices to Reduce Their Use: An Overview', 'Tucker S, Dumitriu Gabur GD, Teodosiu C', 2022, 'Molecules (Basel, Switzerland)', '10.3390/molecules27238205', 'https://doi.org/10.3390/molecules27238205', 'https://europepmc.org/articles/PMC9735622?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'The use of pesticides is a necessary practice in the modern era. Therefore, it is impossible to ignore the pesticide market, which has developed into one of the most lucrative in the world. Nowadays, humans are subjected to many potential risks, and significant amounts of toxic compounds enter their bodies through food, drink, and the air itself. Identification and quantification of these hazardous compounds is crucial for the sustainable development of an increasing world population which poses high climatic and political constraints on agricultural production systems. The maximum residue limits for pesticides have been regulated by the Codex Alimentarius Commission and European Union to protect human health. In this review, we have summarized and explained the analytical methods for pesticide extraction and determination. Also, sustainable viticulture practices like organic vineyards, tillage, biopesticides, nanobiopesticides, and precision viticulture are briefly discussed. These new techniques allow wine growers to be more profitable and efficient, while contributing to the reduction of pests and increasing the quality of wines.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('102dab4f-f19f-4db2-bb20-d7a726d84641', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Plant protection from virus: a review of different approaches', 'Anikina I, Kamarova A, Issayeva K, Issakhanova S, Mustafayeva N, Insebayeva M, Mukhamedzhanova A, Khan SM', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1163270', 'https://doi.org/10.3389/fpls.2023.1163270', 'https://europepmc.org/articles/PMC10291191?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'This review analyzes methods for controlling plant viral infection. The high harmfulness of viral diseases and the peculiarities of viral pathogenesis impose special requirements regarding developing methods to prevent phytoviruses. The control of viral infection is complicated by the rapid evolution, variability of viruses, and the peculiarities of their pathogenesis. Viral infection in plants is a complex interdependent process. The creation of transgenic varieties has caused much hope in the fight against viral pathogens. The disadvantages of genetically engineered approaches include the fact that the resistance gained is often highly specific and short-lived, and there are bans in many countries on the use of transgenic varieties. Modern prevention methods, diagnosis, and recovery of planting material are at the forefront of the fight against viral infection. The main techniques used for the healing of virus-infected plants include the apical meristem method, which is combined with thermotherapy and chemotherapy. These methods represent a single biotechnological complex method of plant recovery from viruses in vitro culture. It widely uses this method for obtaining non-virus planting material for various crops. The disadvantages of the tissue culture-based method of health improvement include the possibility of self-clonal variations resulting from the long-term cultivation of plants under in vitro conditions. The possibilities of increasing plant resistance by stimulating their immune system have expanded, which results from the in-depth study of the molecular and genetic bases of plant resistance toward viruses and the investigation of the mechanisms of induction of protective reactions in the plant organism. The existing methods of phytovirus control are ambiguous and require additional research. Further study of the genetic, biochemical, and physiological features of viral pathogenesis and the development of a strategy to increase plant resistance to viruses will allow a new level of phytovirus infection control to be reached.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('110ebd6a-815f-4470-adeb-339f012175ca', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Supramolecular chemistry for optical detection and delivery applications in living plants', 'Balli MV, Biedermann F, Prodi L, Picchetti P', 2025, 'Chemical Society reviews', '10.1039/d4cs00500g', 'https://doi.org/10.1039/d4cs00500g', 'https://europepmc.org/articles/PMC12268990?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Over the past century, modern agriculture, through the use of synthetic fertilisers, pesticides, and improved plant breeding, has greatly increased food production. However, this progress has brought serious environmental consequences, including excessive water use and harmful pesticide exposure. In addition, future farming must adapt to the growing challenges posed by climate change and natural disasters through more sustainable practices and resilient crop management. In this context, emerging supramolecular strategies offer promising alternatives through responsive molecular assemblies capable of precise sensing and controlled delivery. In this review, we thus discuss the application of supramolecular chemistry principles to plant science and agriculture, with a particular emphasis on the design and implementation of host-guest systems, chemosensors, and supramolecular (nano)delivery vehicles for use in living plants. We report and analyse recent advances in sensing and monitoring of plant processes, the detection of pesticides, the preparation of safer and more effective supramolecular pesticides, and nucleic acid-based crop protection strategies, highlighting key design principles specific to the plant biological context. Moreover, key challenges are discussed regarding the application of supramolecular systems to plants, and examples are highlighted to promote new interdisciplinary strategies for designing next-generation tools for real-time, in vivo plant studies and sustainable crop management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5f5200ea-f561-4585-8dd1-00f6bd1a1325', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Herbicide spray drift from ground and aerial applications: Implications for potential pollinator foraging sources', 'Butts TR, Fritz BK, Kouame KB, Norsworthy JK, Barber LT, Ross WJ, Lorenz GM, Thrash BC', 2022, 'Scientific reports', '10.1038/s41598-022-22916-4', 'https://doi.org/10.1038/s41598-022-22916-4', 'https://europepmc.org/articles/PMC9606278?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'A field spray drift experiment using florpyrauxifen-benzyl was conducted to measure drift from commercial ground and aerial applications, evaluate soybean [Glycine max (L.) Merr.] impacts, and compare to United States Environmental Protection Agency (US EPA) drift models. Collected field data were consistent with US EPA model predictions. Generally, with both systems applying a Coarse spray in a 13-kph average wind speed, the aerial application had a 5.0- to 8.6-fold increase in drift compared to the ground application, and subsequently, a 1.7- to 3.6-fold increase in downwind soybean injury. Soybean reproductive structures were severely reduced following herbicide exposure, potentially negatively impacting pollinator foraging sources. Approximately a 25% reduction of reproductive structures up to 30.5-m downwind and nearly a 100% reduction at 61-m downwind were observed for ground and aerial applications, respectively. Aerial applications would require three to five swath width adjustments upwind to reduce drift potential similar to ground applications.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a6271a2e-a51d-48d8-ad87-f90b9bdc6f4e', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'The Complex Roles of Plant Hormones During Clubroot Disease Development in the Brassicaceae', 'Jayasinghege CPA, Storfie ERM, Ozga JA, Strelkov SE', 2025, 'Journal of plant growth regulation', '10.1007/s00344-025-11790-9', 'https://doi.org/10.1007/s00344-025-11790-9', 'https://europepmc.org/articles/PMC12559101?pdf=render', NULL, NULL, 21, NULL, 'canada', 3, 'cc by', 'Clubroot, caused by the obligate parasite Plasmodiophora brassicae, is a serious soilborne disease that threatens many commercially valuable crops in the Brassicaceae family, including the oilseed crop canola (Brassica napus) and various vegetables. Evidence from studies analyzing hormonal profiles, transcriptomes, proteomes, mutants defective in hormone functions, and treatments of infected plants with growth regulators suggest that nearly all plant hormones are involved in or affected by the disease. However, the specific roles of individual hormones in clubroot development or resistance remain unclear. This knowledge gap is compounded by the complex regulation of hormone functions and inconsistencies across studies, likely due to variations caused by host-pathogen combinations and other factors such as environmental influences. Additionally, biotic and abiotic stress responses caused by the disease and, in some instances, pathogen proteins manipulating host hormonal metabolism add additional layers of complexity. Despite these challenges, emerging trends suggest regulatory roles for plant hormones in both disease development and host defense. In this review, we explore these patterns, aiming to elucidate the contributions of different hormones to clubroot development and associated stress responses.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4330b687-1a06-43ce-aefb-f21bb3323463', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'The effect of broadcast struvite fertilization on element soil content and microbial activity changes in winter wheat cultivation in southwest Poland', 'Ramut R, Jama-Rodzeńska A, Woźniak M, Siebielec S, Kamińska J, Szuba-Trznadel A, Gałka B', 2025, 'Scientific reports', '10.1038/s41598-025-90384-7', 'https://doi.org/10.1038/s41598-025-90384-7', 'https://europepmc.org/articles/PMC11846848?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by-nc-nd', 'This study aimed to evaluate the potential of struvite as a phosphorus fertilizer in winter wheat cultivation in southwest Poland. The field experiment was conducted at Wroclaw University of Environmental and Life Sciences in Swojec in 2022/2023. The studied factors were two cultivars of winter wheat (Activus and Chevignon) and two phosphorus fertilization methods (traditional superphosphate and struvite). Aditionally, the study attempted to develop a reasonable phosphorus testing method to analyze phosphorus content in soil. Three phosphorus extraction methods were used to determine P, Mg and K content where Mehlich 3 and Yanai seem to be most appropriate. The following traits in the study were estimated: grain yield, content of P, Mg and K in the grain, as well as soil microbial activity expressed as enzyme activity (acid and alkaline phosphatase, dehydrogenase), metabolic activity (Biolog EcoPlates™) and phosphate solubilizing bacteria (PSB) abundance. An increase in the Mg content of wheat grain under the influence of struvite application was found. Phosphorus content in the soil depended primarily on the date of soil sampling followed by fertilization method and varieties based on the Egner-Rhiem method as well as Mehlich 3. Soil enzymatic activity depended mainly on the sampling date and then on fertilization. In the case of PSB, the dominant factor was the wheat cultivars. Biolog EcoPlate analysis showed that the most metabolically active microbial communities were recorded in samples collected at the second time of sampling (end of winter wheat vegetation) To see how the phosphorus content develops after the application of struvite under field conditions as well as its fraction, a long-term experiment should be conducted.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b635b91-87b1-423e-b2c2-c9ff13e67a27', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'The optimization of crop response to climatic stress through modulation of plant stress response mechanisms. Opportunities for biostimulants and plant hormones to meet climate challenges', 'Li J, Forghieri G, Geelen D, du Jardin P, Brown PH', 2026, 'The New phytologist', '10.1111/nph.70701', 'https://doi.org/10.1111/nph.70701', 'https://europepmc.org/articles/PMC12676087?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'This review discusses the use of agronomic management practices to enhance crop stress resilience to climate stress through the modulation of natural plant growth regulatory pathways. The use of biostimulants or plant hormones to improve crop resilience is subject to strict regulatory oversight if changes in the regulation of plant growth are implied. Climate change is a major threat to crop potential and is characterized by both long-term shifts in temperature and precipitation patterns as well as increased occurrence of extreme weather events, posing an immediate threat to agriculture. Breeding and exogenous inputs have been used to enhance cropping system resilience, although these management practices are either too slow or constrained by cost and availability, to address rapidly emerging climate challenges. Exogenous biostimulants, microbials and plant hormones have shown great promise as novel mechanisms to optimize natural plant resilience, resulting in immediate but non-permanent improvements in plant responses to climate-induced stresses, representing a powerful but underexplored approach to enhance crop productivity under climate stress. The use of these exogenous inputs is, however, constrained by outdated and scientifically unsound regulations that consider any such modification as pesticidal in nature. The failure to modernize regulatory frameworks for the use of biostimulants in agriculture will constrain the development of safe effective tools and deprive growers of means to respond to climate change. Here, we discuss the scientific rationale for eliminating the regulatory barriers governing biostimulants or products that modulate plant regulatory networks and propose a framework for enabling legislation to strengthen cropping system resilience.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1a1da4d7-93fb-41bc-8d88-09addd98087b', 'b9da6f00-4471-4d99-a479-94a2fe1621b9', 'Validating the contributions of stem and root traits to barley lodging in western Canada', 'Taylor MW, Ferré CAM, Ye S, Yang X, Feurtado JA, Beattie AD', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1547207', 'https://doi.org/10.3389/fpls.2025.1547207', 'https://europepmc.org/articles/PMC12423630?pdf=render', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Lodging caused by stem buckling or root anchorage failure results in significant economic losses each year globally due to increased disease load, downgrading of quality, and yield loss. To increase lodging resistance in western Canadian barley, a study was undertaken to identify traits associated to lodging score. Mechanical and architectural traits encompassing whole plant, stem and root features of 13 spring barley genotypes, representing a diversity of classes, height, and lodging resistance, were evaluated at six field locations over three years. Correlation analysis identified plant height, internode length, crown root angle and root system solidity as traits with the largest influence on lodging (r = 0.37, 0.27, -0.32 and 0.62, respectively). A structural equation model (SEM) was created to further evaluate which traits had direct or indirect influence on barley lodging. The best fitting SEM included nine traits that captured aspects of the whole plant, stem and root system. Plant height (effect estimate = 0.46) and root system solidity (0.14) showed a direct influence on lodging, while root angle had both direct (-0.21) and indirect (via height) influence on lodging. Stem strength, stem outer diameter, and stem volume had indirect effects on lodging through height, while root network area, convex area and total root length had indirect effects on lodging through root system solidity. The three traits that directly influenced lodging in both correlation analysis and SEM, plant height, root angle, and root system solidity, displayed moderate to high heritability (0.85, 0.78 and 0.57, respectively), thus making them suitable for breeding selections. Collectively, this study confirmed the role of plant height and root angle in lodging, identified root system solidity as a novel trait associated to barley lodging resistance, and revealed root imaging as a new screening tool to help breeders select for, and improve, lodging resistance in the absence of observable field lodging.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4ff98f0a-b977-4d04-9dd1-08d78afb8fd7', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'A novel W1999S mutation and non-target site resistance impact on acetyl-CoA carboxylase inhibiting herbicides to varying degrees in a UK Lolium multiflorum population', 'Kaundun SS, Bailly GC, Dale RP, Hutchings SJ, McIndoe E', 2013, 'PloS one', '10.1371/journal.pone.0058012', 'https://doi.org/10.1371/journal.pone.0058012', 'https://europepmc.org/articles/PMC3585232?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'BackgroundAcetyl-CoA carboxylase (ACCase) inhibiting herbicides are important products for the post-emergence control of grass weed species in small grain cereal crops. However, the appearance of resistance to ACCase herbicides over time has resulted in limited options for effective weed control of key species such as Lolium spp. In this study, we have used an integrated biological and molecular biology approach to investigate the mechanism of resistance to ACCase herbicides in a Lolium multiflorum Lam. from the UK (UK21).Methodology/principal findingsThe study revealed a novel tryptophan to serine mutation at ACCase codon position 1999 impacting on ACCase inhibiting herbicides to varying degrees. The W1999S mutation confers dominant resistance to pinoxaden and partially recessive resistance to cycloxydim and sethoxydim. On the other hand, plants containing the W1999S mutation were sensitive to clethodim and tepraloxydim. Additionally population UK21 is characterised by other resistance mechanisms, very likely non non-target site based, affecting several aryloxyphenoxyproprionate (FOP) herbicides but not the practical field rate of pinoxaden. The positive identification of wild type tryptophan and mutant serine alleles at ACCase position 1999 could be readily achieved with an original DNA based derived cleaved amplified polymorphic sequence (dCAPS) assay that uses the same PCR product but two different enzymes for positively identifying the wild type tryptophan and mutant serine alleles identified here.Conclusion/significanceThis paper highlights intrinsic differences between ACCase inhibiting herbicides that could be exploited for controlling ryegrass populations such as UK21 characterised by compound-specific target site and non-target site resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf99c608-8bbc-4fe8-a01a-c37c05e7965c', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Acetyl-CoA carboxylase (ACCase)-inhibiting herbicides: Past, present, and future', 'Amit J. Jhala, Mandeep Singh, Debalin Sarangi, Lovreet Shergill, Aniruddha Maity, Zahoor A. Ganie, Chandrima Shyam, Mithila Jugulam', 2026, 'Weed Technology', '10.1017/wet.2025.10073', 'https://doi.org/10.1017/wet.2025.10073', 'https://www.cambridge.org/core/product/identifier/S0890037X25100730/type/journal_article', NULL, NULL, 17, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Acetyl-CoA carboxylase (ACCase)-inhibiting herbicides are primarily applied for controlling grass weeds in broadleaf crops. These herbicides are foliar-active, providing minimal residual weed control. This review aims to summarize 1) the history and use of ACCase-inhibiting herbicides in the United States; 2) ACCase-inhibitor-resistant weeds, their mechanisms of resistance, and management strategies; and 3) the future of ACCase-inhibiting herbicides. Herbicides that inhibit ACCase belong to three chemical families: aryloxyphenoxypropionates, cyclohexanediones, and phenylpyrazoles. They function by inhibiting the enzyme ACCase activity, thereby blocking the first step in de novo fatty acid biosynthesis and thus preventing the production of phospholipids and essential secondary metabolites in susceptible plants. Diclofop-methyl was the first ACCase inhibitor discovered in 1975, and commercialized in 1982 in the United States. Pinoxaden was the last herbicide to be commercialized in 2005. As of 2025, a total of 51 grass weed species have been documented as being resistant to ACCase-inhibiting herbicides worldwide, including 16 in the United States. The resistance in these weeds is attributed to both target-site and non–target site mechanisms. Mixing ACCase-inhibiting herbicides with auxinic herbicides can reduce grass weed control due to antagonistic interactions. Therefore, selecting an appropriate tank-mix partner with an ACCase inhibitor is crucial for achieving broad-spectrum weed control, or a dual-tank precision sprayer could be used. Clethodim is the most widely used ACCase-inhibiting herbicide, with 920,339 kg applied to approximately 16% of soybean crops planted in the United States in 2023, at an average application rate of 179 g ha‒1. A recent discovery, metproxybicyclone, will be the first carbocyclic aryl-dione herbicide from a new ACCase inhibitor family. This novel herbicide will be applied postemergence to control sensitive and ACCase inhibitor-resistant grass weeds in broadleaf crops. Continued research efforts are focused on discovering new ACCase-inhibiting herbicides capable of controlling ACCase inhibitor-resistant grass weeds.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3efe502-e060-4959-b1fa-8fa9687d5a48', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Achieving agricultural sustainability through soybean production in Iran: Potential and challenges', 'Majidian P, Ghorbani HR, Farajpour M', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e26389', 'https://doi.org/10.1016/j.heliyon.2024.e26389', 'https://europepmc.org/articles/PMC10884498?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The utilization of soybean as a key oil crop to enhance sustainable agriculture has garnered significant attention from researchers. Its lower water requirements compared to rice, along with its reduced environmental impact, including greenhouse gas emissions, improved water quality, enhanced biodiversity, and efficient resource utilization, make it an attractive option. Unfortunately, Iran, like many other developing countries, heavily relies on soybean imports (over 90%) to meet the demand for oil and protein in human and livestock food rations. The decline in soybean production, coupled with diminishing cultivation areas, yield rates, and increasing import needs, underscores the urgent need to address the challenges faced in Iran. The decline in soybean production in the country can be attributed to various factors, including environmental stresses (both biotic and abiotic), limited variation in soybean cultivars, inadequate mechanization for cultivation, and economic policies. Hence, this review provides a comprehensive overview of the current status of soybean production in Iran and highlights its potential to enhance sustainable agriculture. Additionally, it examines the challenges and constraints associated with soybean cultivation, such as environmental changes and unbalanced marketing, and explores potential solutions and management strategies to bridge the gap between small-scale and large-scale production. Given the increasing global demand for plant-based protein and the significance of the feed industry, studying the limitations faced by countries with slower soybean production growth can shed light on the issues and present opportunities to capitalize on novel soybean advancements in the future. By addressing these challenges and unlocking the potential of soybean cultivation, Iran can contribute to sustainable agricultural practices and attain a more resilient food system.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc6998f5-c81a-477f-9eee-36ce5b580728', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Broad resistance to ACCase inhibiting herbicides in a ryegrass population is due only to a cysteine to arginine mutation in the target enzyme.', 'Shiv Shankhar Kaundun, Sarah-Jane Hutchings, Richard Paul Dale, Eddie McIndoe', 2012, 'PLoS ONE', '10.1371/journal.pone.0039759', 'https://doi.org/10.1371/journal.pone.0039759', 'http://europepmc.org/articles/PMC3387263?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'BACKGROUND: The design of sustainable weed management strategies requires a good understanding of the mechanisms by which weeds evolve resistance to herbicides. Here we have conducted a study on the mechanism of resistance to ACCase inhibiting herbicides in a Lolium multiflorum population (RG3) from the UK. METHODOLOGY/PRINCIPAL FINDINGS: Analysis of plant phenotypes and genotypes showed that all the RG3 plants (72%) that contained the cysteine to arginine mutation at ACCase codon position 2088 were resistant to ACCase inhibiting herbicides. Whole plant dose response tests on predetermined wild and mutant 2088 genotypes from RG3 and a standard sensitive population indicated that the C2088R mutation is the only factor conferring resistance to all ten ACCase herbicides tested. The associated resistance indices ranged from 13 for clethodim to over 358 for diclofop-methyl. Clethodim, the most potent herbicide was significantly affected even when applied on small mutant plants at the peri-emergence and one leaf stages. CONCLUSION/SIGNIFICANCE: This study establishes the clear and unambiguous importance of the C2088R target site mutation in conferring broad resistance to ten commonly used ACCase inhibiting herbicides. It also demonstrates that low levels "creeping", multigenic, non target site resistance, is not always selected before single gene target site resistance appears in grass weed populations subjected to herbicide selection pressure.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4833c5ea-b7f5-41bf-a1c1-fd8bfdc63e0a', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Different Mutations Endowing Resistance to Acetyl-CoA Carboxylase Inhibitors Results in Changes in Ecological Fitness of Lolium rigidum Populations', 'Matzrafi M, Gerson O, Rubin B, Peleg Z', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.01078', 'https://doi.org/10.3389/fpls.2017.01078', 'https://europepmc.org/articles/PMC5479926?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Various mutations altering the herbicide target site (TS), can lead to structural modifications that decrease binding efficiency and results in herbicide resistant weed. In most cases, such a mutation will be associated with ecological fitness penalty under herbicide free environmental conditions. Here we describe the effect of various mutations, endowing resistance to acetyl-CoA carboxylase (ACCase) inhibitors, on the ecological fitness penalty of Lolium rigidum populations. The TS resistant populations, MH (substitution of isoleucine 1781 to leucine) and NO (cysteine 2088 to arginine), were examined and compared to a sensitive population (AL). Grain weight (GW) characterization of individual plants from both MH and NO populations, showed that resistant individuals had significantly lower GW compared with sensitive ones. Under high temperatures, both TS resistant populations exhibited lower germination rate as compared with the sensitive (AL) population. Likewise, early vigor of plants from both TS resistant populations was significantly lower than the one measured in plants of the sensitive population. Under crop-weed intra-species competition, we found an opposite trend in the response of plants from different populations. Relatively to inter-population competition conditions, plants of MH population were less affected and presented higher reproduction abilities compared to plants from both AL and NO populations. On the basis of our results, a non-chemical approach can be taken to favor the sensitive individuals, eventually leading to a decline in resistant individuals in the population.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60f8775a-cafc-4a78-994e-47257d2cda8f', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Efficacy of imazapic/imazapyr and other herbicides in mixtures for the control of Digitaria insularis prior to soybean sowing', 'Alfredo Junior Paiola Albrecht, Leandro Paiola Albrecht, André Felipe Moreira Silva, Romulo Augusto Ramos, Everson Pedro Zeny, Juliano Bortoluzzi Lorenzetti, Maikon Tiago Yamada Danilussi, Arthur Arrobas Martins Barroso', 2020, 'Agronomía Colombiana', '10.15446/agron.colomb.v38n3.83046', 'https://doi.org/10.15446/agron.colomb.v38n3.83046', 'https://revistas.unal.edu.co/index.php/agrocol/article/view/83046', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'Herbicide mixtures, use of multiple sites of action, and other weed management practices are necessary to avoid cases of biotype resistance. The aim of this study was to evaluate the efficiency of imazapic/imazapyr and other herbicides in mixtures to control Digitaria insularis at burndown before soybean sowing. This field research was conducted in Umuarama, State of Parana (PR), Brazil, in the 2018/19 soybean season. The experiment was conducted in a randomized block experimental design with four replications and 11 treatments composed of the application of glyphosate, clethodim, haloxyfop, imazapic/imazapyr, glufosinate, 2,4-dichlorophenoxyacetic acid (2,4-D), dicamba, triclopyr, and saflufenacil, in mixtures. Weed control was evaluated as well as soybean injury and yield. An analysis of variance and F-test were performed, and the treatment means were compared by the Scott-Knott test. All treatments showed great control over the weed and low crop injury rate while maintaining soybean yield. The application of imazapic/imazapyr in mixtures with other herbicides was effective in controlling glyphosate-resistant D. insularis in burndown before soybean sowing and with sequential application of haloxyfop + glyphosate at V3 stage of soybean. This chemical management was also selective for soybean.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bfe91e30-660e-4dff-8c2a-dda292e999a9', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Environmental impacts of genetically modified (GM) crop use 1996-2013: Impacts on pesticide use and carbon emissions', 'Brookes G, Barfoot P', 2015, 'GM crops & food', '10.1080/21645698.2015.1025193', 'https://doi.org/10.1080/21645698.2015.1025193', 'https://europepmc.org/articles/PMC5033196?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by-nc', 'This paper updates previous assessments of how crop biotechnology has changed the environmental impact of global agriculture. It focuses on the environmental impacts associated with changes in pesticide use and greenhouse gas emissions arising from the use of GM crops since their first widespread commercial use in the mid 1990s. The adoption of GM insect resistant and herbicide tolerant technology has reduced pesticide spraying by 553 million kg (-8.6%) and, as a result, decreased the environmental impact associated with herbicide and insecticide use on these crops (as measured by the indicator the Environmental Impact Quotient (EIQ)) by 19.1%. The technology has also facilitated important cuts in fuel use and tillage changes, resulting in a significant reduction in the release of greenhouse gas emissions from the GM cropping area. In 2013, this was equivalent to removing 12.4 million cars from the roads.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('65d34188-6626-4bb4-933c-2cb3bc52b5ec', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Evidence, Mechanism and Alternative Chemical Seedbank-Level Control of Glyphosate Resistance of a Rigid Ryegrass (Lolium rigidum) Biotype from Southern Spain', 'Fernández-Moreno PT, Bastida F, De Prado R', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.00450', 'https://doi.org/10.3389/fpls.2017.00450', 'https://europepmc.org/articles/PMC5372819?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Rigid ryegrass (Lolium rigidum) is one of the most troublesome weeds in different crops in the Mediterranean region. A rigid ryegrass biotype from an olive grove in Jaén province (Andalusía, southern Spain), potentially resistant to glyphosate (RG), was tested for its resistance level through dose-response assays using a susceptible biotype (SG). To test the hypothesis of a non-target-site-based resistance, as point mutations are far less common mechanisms of glyphosate resistance, studies were also conducted to elucidate whether resistance was associated with biochemical, metabolism, molecular and/or physiological mechanisms. Alternative herbicide-based control options, including single-herbicide or herbicide mixtures with glyphosate, applied at seedling, tillering or full heading stages, were tested in field experiments for 2 years for their efficacy against rigid ryegrass plants and their effects on the soil seed bank. Resistance levels of the RG biotype were 23- (LD50) and 7-fold (GR50) higher compared to the SG biotype. The SG biotype exhibited a significantly greater shikimic acid accumulation than the RG one. At 96 HAT, 58 and 89% of applied 14C-glyphosate was up taken by leaves of RG and SG biotype plants, respectively, and, at this time, a significantly higher proportion of the glyphosate taken up by the treated leaf remained in its tissue in RG plants compared to the SG ones. The RG biotype did not reveal any point mutation in the glyphosate target site EPSP synthase. Overall, results confirmed reduced glyphosate uptake and translocation as being the mechanism involved in glyphosate resistance in the RG biotype. RG biotype responses to the alternative treatments tested in situ indicated that herbicide applications at the later growth stage tended to be less effective in terms of immediate effects on population size than earlier applications, and that only in some cases, the removal of at least 85% of the RG biotype was achieved. However, with few exceptions, the alternative treatments tested appeared to be highly effective in reducing the seed bank irrespective of the growth stage. The frequency of the resistant phenotype in the progeny of surviving plants of the RG biotype was dependent on treatment. Results suggest that a potential exists for effective management of glyphosate-resistant rigid ryegrass in olive groves in southern Spain.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('374230d6-a466-4a05-ae77-0be7e304b6bf', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'First Asp-2078-Gly Mutation Conferring Resistance to Different ACCase Inhibitors in a Polypogon fugax Population from China', 'Mo B, Chen W, He S, Liu H, Bai L, Pan L', 2022, 'International journal of molecular sciences', '10.3390/ijms24010528', 'https://doi.org/10.3390/ijms24010528', 'https://europepmc.org/articles/PMC9820770?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Asia minor bluegrass (Polypogon fugax) is a common and problematic weed throughout China. P. fugax that is often controlled by acetyl-CoA carboxylase (ACCase) inhibitors in canola fields. Herein, we confirmed a P. fugax population (R) showing resistance to all ACCase inhibitors tested with resistance indexes ranging from 5.4-18.4. We further investigated the resistance mechanisms of this R population. Molecular analyses revealed that an amino acid mutation (Asp-2078-Gly) was present in the R population by comparing ACCase gene sequences of the sensitive population (S). In addition, differences in susceptibility between the R and S population were unlikely to be related to herbicide metabolism. Furthermore, a new derived cleaved amplified polymorphic sequence (dCAPS) method was developed for detecting the Asp-2078-Gly mutation in P. fugax efficiently. We found that 93.75% of plants in the R population carried the Asp-2078-Gly mutation, and all the herbicide-resistant phenotype of this R population is inseparable from this mutation. This is the first report of cross resistance to ACCase inhibitors conferred by the Asp-2078-Gly target-site mutation in P. fugax. The research suggested the urgent need to improve the diversity of weed management practices to prevent the widespread evolution of herbicide resistance in P. fugax in China.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('734c6528-3431-4431-9430-226bfeb8d8dd', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Molecular Targets of Herbicides and Fungicides─Are There Useful Overlaps for Fungicide Discovery?', 'Duke SO, Pan Z, Bajsa-Hirschel J, Tamang P, Hammerschmidt R, Lorsbach BA, Sparks TC', 2023, 'Journal of agricultural and food chemistry', '10.1021/acs.jafc.3c07166', 'https://doi.org/10.1021/acs.jafc.3c07166', 'https://europepmc.org/articles/PMC10755756?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by-nc-nd', 'New fungicide modes of action are needed for fungicide resistance management strategies. Several commercial herbicide targets found in fungi that are not utilized by commercial fungicides are discussed as possible fungicide molecular targets. These are acetyl CoA carboxylase, acetolactate synthase, 5-enolpyruvylshikimate-3-phosphate synthase, glutamine synthase, phytoene desaturase, protoporphyrinogen oxidase, long-chain fatty acid synthase, dihydropteroate synthase, hydroxyphenyl pyruvate dioxygenase, and Ser/Thr protein phosphatase. Some of the inhibitors of these herbicide targets appear to be either good fungicides or good leads for new fungicides. For example, some acetolactate synthase and dihydropteroate inhibitors are excellent fungicides. There is evidence that some herbicides have indirect benefits to certain crops due to their effects on fungal crop pathogens. Using a pesticide with both herbicide and fungicide activities based on the same molecular target could reduce the total amount of pesticide used. The limitations of such a product are discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('507a198d-c60c-436e-b490-520f674a9562', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Fitness costs associated with acetyl-coenzyme A carboxylase mutations endowing herbicide resistance in American sloughgrass (Beckmannia syzigachne Steud.)', 'Du L, Qu M, Jiang X, Li X, Ju Q, Lu X, Wang J', 2019, 'Ecology and evolution', '10.1002/ece3.4917', 'https://doi.org/10.1002/ece3.4917', 'https://europepmc.org/articles/PMC6392401?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Weed resistance to herbicide can be conferred by gene mutations, and some mutations can cause pleiotropic effects in some cases. We investigated the pleiotropic effects associated with five specific ACCase mutations (Ile1781Leu, Trp2027Cys, Ile2041Asn, Asp2078Gly, and Gly2096Ala) on the plant growth, seed production, and resource competitiveness in American sloughgrass.Resistant plants (M/M) homozygous for specific ACCase mutation and susceptible wild-type plants (W/W) were derived from single heterozygous mother plant (M/W) by genotyping. Plant growth assay and neighborhood experiments were performed to quantify variation between M/M plants and W/W plants.The Ile1781Leu mutation resulted in slight increases in plant growth in pure stands and improved resource competitiveness under low-competition conditions in pot experiments, but no clear variation was observed under high competitive pressure or field conditions. During competition with wheat plants under field conditions, American sloughgrass plants containing Ile2041Asn ACCase exhibited a significantly lower (12.5%) aboveground biomass but no distinct differences in seed production or resource competitiveness. No significant detrimental pleiotropic effects associated with Gly2096Ala were detected in American sloughgrass.The Trp2027Cys mutation distinctly reduced seed production, especially under high competitive pressure, but did not significantly alter plant growth. The Asp2078Gly mutation consistently reduced not only plant growth and seed production but also resource competitiveness. Synthesis. The Trp2027Cys and Asp2078Gly mutations led to significant fitness costs, which may reduce the frequency of resistance alleles and reduce the propagation speed of resistant weeds in the absence of ACCase inhibitor herbicides. The Ile1781Leu, Ile2041Asn, and Gly2096Ala mutations displayed no obvious fitness costs or displayed very small fitness penalties, which would likely have no effect on the establishment of resistant weeds in the field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b7d4682d-fd54-4e1b-925a-1d5fb7579338', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Genetically Modified (GM) Crop Use 1996-2020: Environmental Impacts Associated with Pesticide Use CHANGE', 'Brookes G', 2022, 'GM crops & food', '10.1080/21645698.2022.2118497', 'https://doi.org/10.1080/21645698.2022.2118497', 'https://europepmc.org/articles/PMC9578716?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'This paper assesses the environmental impacts associated with changes in pesticide use with GM crops at a global level. The main technologies impacting on pesticide use have been crops modified to be tolerant to specific herbicides so as to facilitate improved weed control and crops resistant to a range of crop insect pests that otherwise damage crops or typically require the application of insecticides to control them. Over the 24 year period examined to 2020, the widespread use of GM insect resistant and herbicide tolerant seed technology has reduced pesticide application by 748.6 million kg (-7.2%) of active ingredient and, as a result, decreased the environmental impact associated with insecticide and herbicide use on these crops (as measured by the indicator, the Environmental Impact Quotient (EIQ)) by a larger 17.3% between 1996 and 2020. The technology that has delivered the largest change in pesticide use has been insect resistant cotton, where a 339 million kg of active ingredient saving has occurred and the associated environmental impact (as measured by the EIQ indicator) has fallen by about a third.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e02423f2-0b26-4778-a26a-e10083a5d84c', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Glyphosate- and Imazapic-Resistant Chloris virgata Populations in the Southeastern Cropping Region of Australia', 'Bhagirath Singh Chauhan, Gulshan Mahajan', 2023, 'Agronomy', '10.3390/agronomy13010173', 'https://doi.org/10.3390/agronomy13010173', 'https://www.mdpi.com/2073-4395/13/1/173', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Chloris virgata is one of the most problematic summer grass species in southeastern Australia. A total of 40 populations of C. virgata were evaluated in the spring–summer season of 2021–2022 in an open environment at the Gatton Farms of the University of Queensland, Queensland, Australia, for their response to two acetyl-coenzyme-A carboxylase (ACCase) inhibitors (clethodim and haloxyfop), a 5-enolpyruvylshikimate-3-phosphate synthase (EPSPS) inhibitor (glyphosate), and an acetolactate synthase (ALS) inhibitor (imazapic). In the first experiment, all populations were screened at the field rate of each herbicide, and the second experiment evaluated the response of seven populations of C. virgata to different rates of glyphosate and imazapic. There were three replications of each treatment and both experiments were repeated over time. None of the populations survived the field rate of clethodim and haloxyfop, possibly suggesting a low exposure of the populations to these herbicides. Individuals in about 90% of populations survived (1% to 100% of individuals surviving) the field rates of glyphosate and individuals in all populations survived (1% to 100%) the imazapic field rate. The dose-response study revealed up to 14- and 5-fold glyphosate resistance in C. virgata populations based on survival and biomass values, respectively, compared to the most susceptible population. Imazapic resistance was up to 2.3- and 16-fold greater than the most susceptible population in terms of survival and biomass values, respectively. The increased cases of glyphosate- and imazapic-resistant C. virgata warrant a nationwide survey and diversified management strategies.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('298eb0c6-c31d-42cc-a02a-2d9bdefb019b', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Ile-1781-Leu and Asp-2078-Gly Mutations in ACCase Gene, Endow Cross-resistance to APP, CHD, and PPZ in Phalaris minor from Mexico', 'Cruz-Hipolito H, Fernandez P, Alcantara R, Gherekhloo J, Osuna MD, De Prado R', 2015, 'International journal of molecular sciences', '10.3390/ijms160921363', 'https://doi.org/10.3390/ijms160921363', 'https://europepmc.org/articles/PMC4613257?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Herbicides that inhibit acetyl coenzyme A carboxylase (ACCase) are commonly used in Mexico to control weedy grasses such as little seed canarygrass (Phalaris minor). These herbicides are classified into three major families (ariloxyphenoxypropionates (APP), cyclohexanodiones (CHD), and, recently, phenylpyrazolines (PPZ)). In this work, the resistance to ACCase (APP, CHD, and PPZ) inhibiting herbicides was studied in a biotype of Phalaris minor (P. minor) from Mexico, by carrying out bioassays at the whole-plant level and investigating the mechanism behind this resistance. Dose-response and ACCase in vitro activity assays showed cross-resistance to all ACCase herbicides used. There was no difference in the absorption, translocation, and metabolism of the (14)C-diclofop-methyl between the R and S biotypes. The PCR generated CT domain fragments of ACCase from the R biotype and an S reference were sequenced and compared. The Ile-1781-Leu and Asp-2078-Gly point mutations were identified. These mutations could explain the loss of affinity for ACCase by the ACCase-inhibing herbicides. This is the ﬁrst report showing that this substitution confers resistance to APP, CHD, and PPZ herbicides in P. minor from Mexico. The mutations have been described previously only in a few cases; however, this is the first study reporting on a pattern of cross-resistance with these mutations in P. minor. The findings could be useful for better management of resistant biotypes carrying similar mutations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('07799c52-9a8d-4bd2-8966-7dc0f98c4555', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Impact of a Novel W2027L Mutation and Non-Target Site Resistance on Acetyl-CoA Carboxylase-Inhibiting Herbicides in a French Lolium multiflorum Population', 'Kaundun SS, Downes J, Jackson LV, Hutchings SJ, Mcindoe E', 2021, 'Genes', '10.3390/genes12111838', 'https://doi.org/10.3390/genes12111838', 'https://europepmc.org/articles/PMC8620607?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Herbicides that inhibit acetyl-CoA carboxylase (ACCase) are among the few remaining options for the post-emergence control of Lolium species in small grain cereal crops. Here, we determined the mechanism of resistance to ACCase herbicides in a Lolium multiflorum population (HGR) from France. A combined biological and molecular approach detected a novel W2027L ACCase mutation that affects aryloxyphenoxypropionate (FOP) but not cyclohexanedione (DIM) or phenylpyraxoline (DEN) subclasses of ACCase herbicides. Both the wild-type tryptophan and mutant leucine 2027-ACCase alleles could be positively detected in a single DNA-based-derived polymorphic amplified cleaved sequence (dPACS) assay that contained the targeted PCR product and a cocktail of two discriminating restriction enzymes. Additionally, we identified three well-characterised I1781L, I2041T, and D2078G ACCase target site resistance mutations as well as non-target site resistance in HGR. The non-target site component endowed high levels of resistance to FOP herbicides whilst partially impacting on the efficacy of pinoxaden and cycloxydim. This study adequately assessed the contribution of the W2027L mutation and non-target site mechanism in conferring resistance to ACCase herbicides in HGR. It also highlights the versatility and robustness of the dPACS method to simultaneously identify different resistance-causing alleles at a single ACCase codon.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac432374-d9e3-4ba9-b009-4f3ac606a475', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Multiple Herbicide Resistance in Annual Ryegrass (Lolium rigidum Gaudin) in the Southeastern Cropping Region of Australia', 'Gulshan Mahajan, Bhagirath Singh Chauhan', 2024, 'Agronomy', '10.3390/agronomy14102206', 'https://doi.org/10.3390/agronomy14102206', 'https://www.mdpi.com/2073-4395/14/10/2206', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Annual ryegrass (Lolium rigidum) is a problematic weed in winter crops and fallows in the southeastern cropping region (SCR) of Australia. This weed has evolved resistance to multiple herbicide groups, globally. In Australia, L. rigidum is more prevalent in the western and southern regions than in SCR. To assess the herbicide resistance status of L. rigidum, the response of five L. rigidum populations (collected from the SCR) to glyphosate, glufosinate, paraquat, haloxyfop-P-ethyl, and clethodim is determined using dose–response curves. Three parametric logistic models are used to determine the herbicide dose required to achieve 50% survival (LD50) and 50% growth reduction (GR50). The LD50 values for 50% survival at 28 days after treatment range from 1702 g a.e. ha−1 to 8225 g a.e. ha−1 for glyphosate, 1637 g a.i. ha−1 to 1828 g a.i. ha−1 for glufosinate, 141 g a.i. ha−1 to 307 g a.i. ha−1 for paraquat, 11 g a.i. ha−1 to 107 g a.i. ha−1 for haloxyfop-P-ethyl, and 17 g a.i. ha−1 to 48 g a.i. ha−1 for clethodim. The resistance factor, based on GR50 value, is highest in the S7 population (2.2 times) for glyphosate, the S11 population (2.3 times) for glufosinate, the S11 population (2.0 time) for paraquat, the S7 population (3.9 times) for haloxyfop-P-ethyl, and the S3 population (3.1 times) for clethodim, compared with the susceptible or less tolerant population. The S11 population is found to be resistant to five tested herbicides, based on resistance factors. Similarly, the S3 population is highly resistant to glyphosate, haloxyfop-P-ethyl, and clethodim compared with the W4 population. These results suggest that L. rigidum populations in the SCR exhibit resistance to multiple herbicide groups at labelled field rates. The findings highlight the necessity of adopting an integrated management approach, including the use of residual herbicides, tank mixing herbicides with different modes of action, and rotating herbicides in conjunction with cultural and mechanical control methods.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('12700aae-9d5f-404c-8b76-55f8057bfea1', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'New Case of False-Star-Grass (Chloris distichophylla) Population Evolving Glyphosate Resistance', 'José  G. Vázquez-García, Sajedeh Golmohammadzadeh, Candelario Palma-Bautista, Antonia  M. Rojano-Delgado, José  A. Domínguez-Valenzuela, Hugo  E. Cruz-Hipólito, Rafael De Prado', 2020, 'Agronomy', '10.3390/agronomy10030377', 'https://doi.org/10.3390/agronomy10030377', 'https://www.mdpi.com/2073-4395/10/3/377', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Chloris distichophylla, suspected of glyphosate resistance (GR), was collected from areas of soybean cultivation in Rio Grande do Sul, Brazil. A comparison was made with a susceptible population (GS) to evaluate the resistance level, mechanisms involved, and control alternatives. Glyphosate doses required to reduce the dry weight (GR50) or cause a mortality rate of 50% (LD50) were around 5.1&#8722;3 times greater in the GR population than in the GS population. The shikimic acid accumulation was around 6.2-fold greater in GS plants than in GR plants. No metabolized glyphosate was found in either GR or GS plants. Both populations did not differ in the enzyme 5-enolpyruvylshikimate-3-phosphate synthase (EPSPS) basal activity or in vitro inhibition of EPSPS activity by glyphosate (I50). The maximum glyphosate absorption was observed at 96 hours after treatment (HAT), which was twofold higher in the GS plants than in the GR plants. This confirms the first case of glyphosate resistance in C. distichophylla. In addition, at 96 HAT, the GS plants translocated more 14C-glyphosate than the GR ones. The best options for the chemical control of both C. distichophylla populations were clethodim, quizalofop, paraquat, glufosinate, tembotrione, diuron, and atrazine. The first case of glyphosate resistance in C. distichophylla was due to impaired uptake and translocation. Chemical control using multiple herbicides with different modes of action (MOA) could be a tool used for integrated weed management (IWM) programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5e54cb7d-7633-403e-b3f6-4bd37e8e71f8', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Non-Target Site Resistance in Summer-Emerging Lolium rigidum and the Effect of Alternative Herbicides', 'Michael Thompson, Bhagirath S. Chauhan', 2023, 'Agronomy', '10.3390/agronomy13030698', 'https://doi.org/10.3390/agronomy13030698', 'https://www.mdpi.com/2073-4395/13/3/698', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Herbicide resistance is an important weed management issue. Glyphosate is the most dominant herbicide, which controls a broad spectrum of weeds, including grasses such as Lolium rigidum. Lolium rigidum is a major weed of winter crops in Australia that is developing glyphosate resistance in increasing numbers of populations and has been observed growing throughout summer in recent years. Three L. rigidum populations, one summer-emerging glyphosate-resistant (GR), one winter-emerging glyphosate-susceptible (GS), and one winter-emerging population with unknown resistance status (CC04), were analyzed for target-site resistance to glyphosate after confirming their resistance or susceptibility to glyphosate in a dose–response experiment. Population GR was obtained from plants that emerged in summer and contained plants that survived all rates of glyphosate applied (0 to 4560 g a.e. ha−1). It was found to be 6.1 and 4.4 times more resistant than population GS across two experiments. Population CC04 was identified as susceptible. Plants from each population were analyzed for the presence of target-site mutations in the conserved region of the EPSPS gene; however, no mutations were identified that could cause resistance, suggesting non-target-site resistance in population GR. The effectiveness of alternative herbicides was also analyzed for each population. Paraquat was the most effective herbicide, with 0% survival across all populations. The ACCase-inhibiting herbicide clethodim was also highly effective (0 to 8% survival across populations). Other ACCase-inhibiting herbicides, propaquizafop, haloxyfop, and pinoxaden, were effective at controlling the two susceptible populations, CC04 and GS (0 to 36% and 0 to 20% survival, respectively), but were only moderately effective for controlling GR (28 to 51% survival). Paraquat and clethodim may be alternative options for controlling GR populations of L. rigidum and could be effective for use in management programs to slow the development of GR populations.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('80bae0a2-a597-41e3-9dde-0cedb9d88ad2', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Non-target-Site Resistance in Lolium spp. Globally: A Review', 'Suzukawa AK, Bobadilla LK, Mallory-Smith C, Brunharo CACG', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.609209', 'https://doi.org/10.3389/fpls.2020.609209', 'https://europepmc.org/articles/PMC7862324?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The Lolium genus encompasses many species that colonize a variety of disturbed and non-disturbed environments. Lolium perenne L. spp. perenne, L. perenne L. spp. multiflorum, and L. rigidum are of particular interest to weed scientists because of their ability to thrive in agricultural and non-agricultural areas. Herbicides are the main tool to control these weeds; however, Lolium spp. populations have evolved multiple- and cross-resistance to at least 14 herbicide mechanisms of action in more than 21 countries, with reports of multiple herbicide resistance to at least seven mechanisms of action in a single population. In this review, we summarize what is currently known about non-target-site resistance in Lolium spp. to acetyl CoA carboxylase, acetohydroxyacid synthase, microtubule assembly, photosystem II, 5-enolpyruvylshikimate-3-phosphate synthase, glutamine synthetase, very-long chain fatty acids, and photosystem I inhibitors. We suggest research topics that need to be addressed, as well as strategies to further our knowledge and uncover the mechanisms of non-target-site resistance in Lolium spp.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7a270e05-66ae-4eed-b4bf-3d940a4a8981', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Molecular functions of nitric oxide and its potential applications in horticultural crops', 'Sun C, Zhang Y, Liu L, Liu X, Li B, Jin C, Lin X', 2021, 'Horticulture research', '10.1038/s41438-021-00500-7', 'https://doi.org/10.1038/s41438-021-00500-7', 'https://europepmc.org/articles/PMC8012625?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Nitric oxide (NO) regulates plant growth, enhances nutrient uptake, and activates disease and stress tolerance mechanisms in most plants, making NO a potential tool for use in improving the yield and quality of horticultural crop species. Although the use of NO in horticulture is still in its infancy, research on NO in model plant species has provided an abundance of valuable information on horticultural crop species. Emerging evidence implies that the bioactivity of NO can occur through many potential mechanisms but occurs mainly through S-nitrosation, the covalent and reversible attachment of NO to cysteine thiol. In this context, NO signaling specifically affects crop development, immunity, and environmental interactions. Moreover, NO can act as a fumigant against a wide range of postharvest diseases and pests. However, for effective use of NO in horticulture, both understanding and exploring the biological significance and potential mechanisms of NO in horticultural crop species are critical. This review provides a picture of our current understanding of how NO is synthesized and transduced in plants, and particular attention is given to the significance of NO in breaking seed dormancy, balancing root growth and development, enhancing nutrient acquisition, mediating stress responses, and guaranteeing food safety for horticultural production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a4ad62e4-afb4-49f7-adf8-8725d464d2b7', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Overexpression of Acetyl CoA Carboxylase 1 and 3 (ACCase1 and ACCase3), and CYP81A21 were related to cyhalofop resistance in a barnyardgrass accession from Arkansas', 'González-Torralva F, Norsworthy JK', 2023, 'Plant signaling & behavior', '10.1080/15592324.2023.2172517', 'https://doi.org/10.1080/15592324.2023.2172517', 'https://europepmc.org/articles/PMC9897766?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Barnyardgrass [Echinochloa crus-galli (L.) P. Beauv.] is the most difficult-to-control weed species of rice production systems worldwide. It has evolved resistance to different herbicide sites of action, including the acetyl-CoA carboxylase (ACCase)-inhibiting herbicides. Target-site mutations conferring resistance to ACCase-inhibiting herbicides are well documented; however, the role of the different ACCase genes in conferring resistance to cyhalofop-p-butyl (cyhalofop), an ACCase-inhibiting herbicide, remains poorly understood. This research assessed the contribution of gene amplification and expression of ACCase genes in a cyhalofop-resistant barnyardgrass accession. Additionally, the expression of glutathione-S-transferases (GSTs) and cytochrome P450 monooxygenases (P450s) genes as possible contributors to resistance to cyhalofop were investigated. Results demonstrated that ACCase gene amplification does not contribute to cyhalofop resistance. However, ACCase1 and ACCase3 were found to be overexpressed in the cyhalofop-resistant barnyardgrass accession. At 24 h after cyhalofop treatment, an overexpression of 2.0- and 2.8-fold was detected in ACCase1 and ACCase3, respectively. In addition, CYP81A21 (a P450 gene) was found to be 2.5-fold overexpressed compared to the susceptible accession in the same time period. These results suggest that ACCase1, ACCase3, and CYP81A21 are crucial genes in contributing cyhalofop resistance in this barnyardgrass accession.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18fa6ada-7b35-4f29-ab8e-68d1e35840af', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Phenomics-Assisted Selection for Herbage Accumulation in Alfalfa (Medicago sativa L.)', 'Biswas A, Andrade MHML, Acharya JP, de Souza CL, Lopez Y, de Assis G, Shirbhate S, Singh A', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.756768', 'https://doi.org/10.3389/fpls.2021.756768', 'https://europepmc.org/articles/PMC8689394?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'The application of remote sensing in plant breeding is becoming a routine method for fast and non-destructive high-throughput phenotyping (HTP) using unmanned aerial vehicles (UAVs) equipped with sensors. Alfalfa (Medicago sativa L.) is a perennial forage legume grown in more than 30 million hectares worldwide. Breeding alfalfa for herbage accumulation (HA) requires frequent and multiple phenotyping efforts, which is laborious and costly. The objective of this study was to assess the efficiency of UAV-based imagery and spatial analysis in the selection of alfalfa for HA. The alfalfa breeding population was composed of 145 full-sib and 34 half-sib families, and the experimental design was a row-column with augmented representation of controls. The experiment was established in November 2017, and HA was harvested four times between August 2018 and January 2019. A UAV equipped with a multispectral camera was used for HTP before each harvest. Four vegetation indices (VIs) were calculated from the UAV-based images: NDVI, NDRE, GNDVI, and GRVI. All VIs showed a high correlation with HA, and VIs predicted HA with moderate accuracy. HA and NDVI were used for further analyses to calculate the genetic parameters using linear mixed models. The spatial analysis had a significant effect in both dimensions (rows and columns) for HA and NDVI, resulting in improvements in the estimation of genetic parameters. Univariate models for NDVI and HA, and bivariate models, were fit to predict family performance for scenarios with various levels of HA data (simulated in silico by assigning missing values to full dataset). The bivariate models provided higher correlation among predicted values, higher coincidence for selection, and higher genetic gain even for scenarios with only 30% of HA data. Hence, HTP is a reliable and efficient method to aid alfalfa phenotyping to improve HA. Additionally, the use of spatial analysis can also improve the accuracy of selection in breeding trials.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cfe077eb-1fd1-416f-a666-94b90d62edf4', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Photosynthetic physiological response of Radix Isatidis (Isatis indigotica Fort.) seedlings to nicosulfuron', 'Yuan X, Zhang L, Ning N, Wen Y, Dong S, Yin M, Guo M, Wang B', 2014, 'PloS one', '10.1371/journal.pone.0105310', 'https://doi.org/10.1371/journal.pone.0105310', 'https://europepmc.org/articles/PMC4148306?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by', 'Radix Isatidis (Isatis indigotica Fort.) is one of the most important traditional Chinese medicine plants. However, there is no suitable herbicide used for weed control in Radix Isatidis field during postemergence stage. To explore the safety of sulfonylurea herbicide nicosulfuron on Radix Isatidis (Isatis indigotica Fort.) seedlings and the photosynthetic physiological response of the plant to the herbicide, biological mass, leaf area, photosynthetic pigment content, photosynthetic rate, chlorophyll fluorescence characteristics, and P700 parameters of Radix Isatidis seedlings were analyzed 10 d after nicosulfuron treatment at 5th leaf stage in this greenhouse research. The results showed that biological mass, total chlorophyll, chlorophyll a, and carotenoids content, photosynthetic rate, stomatal conductance, PS II maximum quantum yield, PS II effective quantum yield, PS II electron transport rate, photochemical quenching, maximal P700 change, photochemical quantum yield of PS I, and PS I electron transport rate decreased with increasing herbicide concentrations, whereas initial fluorescence, quantum yield of non-regulated energy dissipation in PS II and quantum yield of non-photochemical energy dissipation due to acceptor side limitation in PS I increased. It suggests that nicosulfuron ≥1 mg L-1 causes the damage of chloroplast, PS II and PS I structure. Electron transport limitations in PS I receptor side, and blocked dark reaction process may be the main cause of the significantly inhibited growth and decreased photosynthetic rate of Radix Isatidis seedlings.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aed8c4f4-3408-437d-93ff-db855926658b', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Poa annua becomes the first weed to evolve resistance to indaziflam applied preemergence and early-postemergence', 'Miranda JW, Gaines TA, Moretti ML', 2026, 'Pest management science', '10.1002/ps.70214', 'https://doi.org/10.1002/ps.70214', 'https://europepmc.org/articles/PMC12713700?pdf=render', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'BackgroundHerbicide resistance evolution is a major challenge in agriculture. Poa annua L., a globally distributed and genetically diverse weed, has repeatedly evolved resistance to multiple herbicide sites of action due to its genetic plasticity and rapid life cycle. Indaziflam is widely used for P. annua control in several agroecosystems, with reports of postemergence resistance and a few confirmed cases of resistance to preemergence application. This study investigated suspected resistance to indaziflam in P. annua accessions from Oregon hazelnut orchards.ResultsWhole-plant dose-response assays confirmed indaziflam resistance in eight accessions ranging from 2.5- to 51-fold relative to susceptible accessions, which had a lethal dose to 50% of the accession (LD50) of 1.0-3.4 g ha-1. Resistance increased with plant developmental stage and was most pronounced when indaziflam was applied early-postemergence, with some accessions surviving two- to four-fold the labeled rate in tree nut orchards (50-95 g ha-1). Field experiments confirmed reduced efficacy of preemergence and early-postemergence indaziflam treatments up to 195 g ha-1. Indaziflam efficacy declined significantly across all accessions at air temperatures 9 °C:1 °C (day/night), with LD50 values increasing up to eight-fold across accessions compared to 25 °C:12 °C (day/night). Enzyme inhibitor seed-based assays with cytochrome P450 and glutatione transferase inhibitors did not reverse resistance, suggesting resistance pathways other than enhanced metabolism may be involved.ConclusionThis study provides the first confirmed cases of field-evolved resistance to indaziflam applied both preemergence and early-postemergence in P. annua. Resistance was most severe under cooler temperatures and postemergence use, highlighting environmental and developmental effects on indaziflam activity. © 2025 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ec98fb5-f474-4223-a6e8-f9b01bce8a76', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Multiple Resistance Evolution in Bipyridylium-Resistant Epilobium ciliatum After Recurrent Selection', 'Berhoz K. Tahmasebi, Ricardo Alcántara-de la Cruz, Esteban Alcántara, Joel Torra, José A. Domínguez-Valenzuela, Hugo E. Cruz-Hipólito, Antonia M. Rojano-Delgado, Rafael De Prado', 2018, 'Frontiers in Plant Science', '10.3389/fpls.2018.00695', 'https://doi.org/10.3389/fpls.2018.00695', 'https://www.frontiersin.org/article/10.3389/fpls.2018.00695/full', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'The use of herbicides with different modes of action is the primary strategy used to control weeds possessing resistance to a single mechanism of action (MOA). However, this practice can lead to selection for generalist resistance mechanisms and may cause resistance to all MOAs. In this research, we characterized the resistance to diquat/paraquat (bipyridiliums) in an Epilobium ciliatum biotype (R1) collected in an olive orchard from Chile, where alternatives herbicides (2,4-D, glyphosate, glufosinate, flazasulfuron and pyraflufen-ethyl) with different MOAs were used, but they have also showed failure in controlling this species. Because the resistance/susceptibility patterns of the R1 biotype to glufosinate, 2,4-D and pyraflufen-ethyl were not clear, a recurrent resistance selection was carried out in field and greenhouse using these herbicides on R1 plants for three generations (R2 biotype). One biotype that was never treated with herbicides (S) was included as control. Results indicated that the S biotype was controlled at the field dose of all herbicides tested. The biotype R1 exhibited resistance to diquat, paraquat and flazasulfuron and natural tolerance to glyphosate. The R2 biotype displayed resistance to glufosinate, 2,4-D and pyraflufen-ethyl with LD50 (herbicide dose to kill 50% of plants) values higher than field doses in all assays. Physiological and biochemical studies determined the resistance to diquat of the R1 biotype, which was due to impaired translocation. The resistance to flazasulfuron in the R1 and R2 biotypes was confirmed by the low sensitivity of the acetolactate synthase (ALS) activity compared to the S biotype. The similar accumulation of shikimate in treated S, R1, and R2 plants with glyphosate supported the existence of innate tolerance to this herbicide in E. ciliatum. Resistance to glufosinate, 2,4-D and pyraflufen-ethyl in the R2 biotype, acquired after recurrent selection, was determined by low sensitivity of the glutamine synthetase, low accumulation of ethylene and protoporphyrinogen IX oxidase, respectively, in comparison to the S biotype. Epilobium ciliatum from Chilean olive orchards had resistance to only two MAOs (photosystem I and ALS inhibitors), but resistance to five MOAs could occur in the next cropping seasons, if alternatives to weed management, other than herbicides, are not included.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b110027-148c-4778-a158-0a3fa759198a', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Realizing the Potential of Camelina sativa as a Bioenergy Crop for a Changing Global Climate', 'Neupane D, Lohaus RH, Solomon JKQ, Cushman JC', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11060772', 'https://doi.org/10.3390/plants11060772', 'https://europepmc.org/articles/PMC8951600?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Camelina sativa (L.) Crantz. is an annual oilseed crop within the Brassicaceae family. C. sativa has been grown since as early as 4000 BCE. In recent years, C. sativa received increased attention as a climate-resilient oilseed, seed meal, and biofuel (biodiesel and renewable or green diesel) crop. This renewed interest is reflected in the rapid rise in the number of peer-reviewed publications (>2300) containing “camelina” from 1997 to 2021. An overview of the origins of this ancient crop and its genetic diversity and its yield potential under hot and dry growing conditions is provided. The major biotic barriers that limit C. sativa production are summarized, including weed control, insect pests, and fungal, bacterial, and viral pathogens. Ecosystem services provided by C. sativa are also discussed. The profiles of seed oil and fatty acid composition and the many uses of seed meal and oil are discussed, including food, fodder, fuel, industrial, and medical benefits. Lastly, we outline strategies for improving this important and versatile crop to enhance its production globally in the face of a rapidly changing climate using molecular breeding, rhizosphere microbiota, genetic engineering, and genome editing approaches.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dbbace81-5032-4f42-9195-5a1934a2f74f', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Review: evolutionary drivers of agricultural adaptation in Lolium spp', 'Matzrafi M, Preston C, Brunharo CA', 2021, 'Pest management science', '10.1002/ps.6219', 'https://doi.org/10.1002/ps.6219', 'https://europepmc.org/articles/PMC8048627?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc-nd', 'The genus Lolium comprises many species, of which L. perenne ssp. multiflorum, L. perenne ssp. perenne, and L. rigidum are of worldwide agricultural importance as both pasture crops and as weeds. These three species are inter-fertile, obligate out-crossers with a self-incompatible reproduction system. This combination contributes to high genetic diversity that supplies new variants during expansion to new natural areas and agricultural environments. Human dispersal, de-domestication and crop-weed hybridization events between Lolium spp., or with others such as Festuca spp., are likely associated with their distinct weediness abilities. Furthermore, new introductions followed by introgression may hasten adaptation to new environments. Most Lolium-related weed science studies have focused on adaptation leading to herbicide resistance, but other forms of adaptation may also occur. In this review, we explore how the wide genetic variation among Lolium species and hybridization with other species may contribute to range expansion, and adaptation to both new agricultural practices and future predicted climate change scenarios. © 2020 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44531ad8-b22e-471d-b7ce-6e2b0e2c7bb2', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Sourgrass phenological stage and efficacy of ACCase-inhibiting herbicides', 'Jéssica C. Presoto, Jeisiane F. Andrade, Laura A. Souza, Laura S. Teixeira, Saul J.P. Carvalho', 2020, 'Planta Daninha', '10.1590/s0100-83582020380100089', 'https://doi.org/10.1590/s0100-83582020380100089', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-83582020000100336&tlng=en', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background: Sourgrass (Digitaria insularis) is a highly disseminated weed in Brazil. It is a perennial grass weed that has high infesting capacity in agricultural areas and presents glyphosate-resistant biotypes. An effective post-emergence control of sourgrass plants depends on their phenological stage at the time of herbicide application. Objective: This work was developed with the objective of evaluating the effect of the sourgrass phenological stage at the time of herbicide application on the efficacy of ACCase-inhibiting herbicides. Methods: Two independent experiments were conducted under greenhouse conditions to evaluate two ACCase-inhibiting herbicides: clethodim, and haloxyfop. The treatments were applied using a completely randomized block design, with an 8×4 factorial arrangement consisted of 8 herbicide rates (4, 2, 1, 1/2, 1/4, 1/8, and 1/16 times the recommended rate, and a control plot without herbicide application) and four phenological stages of sourgrass. Results: The development of sourgrass plants after tillering decreased the efficacy of the herbicide molecules; however, clethodim and haloxyfop were efficient to control sourgrass at earlier developmental stages. Morphological, anatomical, and physiological changes in older plants may explain the lower susceptibility to herbicides. Conclusions: Other control techniques should be considered for sourgrass plants at later developmental stages, such as sequential application or herbicide mixtures, to increase the efficacy of ACCase herbicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d9a74400-0ff4-43f1-91ba-fc800e1896f1', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Target-Site and Non-target-Site Resistance Mechanisms Confer Multiple and Cross- Resistance to ALS and ACCase Inhibiting Herbicides in Lolium rigidum From Spain', 'Torra J, Montull JM, Taberner A, Onkokesung N, Boonham N, Edwards R', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.625138', 'https://doi.org/10.3389/fpls.2021.625138', 'https://europepmc.org/articles/PMC7889805?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Lolium rigidum is one the worst herbicide resistant (HR) weeds worldwide due to its proneness to evolve multiple and cross resistance to several sites of action (SoA). In winter cereals crops in Spain, resistance to acetolactate synthase (ALS)- and acetyl-CoA carboxylase (ACCase)-inhibiting herbicides has become widespread, with farmers having to rely on pre-emergence herbicides over the last two decades to maintain weed control. Recently, lack of control with very long-chain fatty acid synthesis (VLCFAS)-inhibiting herbicides has been reported in HR populations that are difficult to manage by chemical means. In this study, three Spanish populations of L. rigidum from winter cereals were confirmed as being resistant to ALS- and ACCase-inhibiting herbicides, with broad-ranging resistance toward the different chemistries tested. In addition, reduced sensitivity to photosystem II-, VLCFAS-, and phytoene desaturase-inhibiting herbicides were confirmed across the three populations. Resistance to ACCase-inhibiting herbicides was associated with point mutations in positions Trp-2027 and Asp-2078 of the enzyme conferring target site resistance (TSR), while none were detected in the ALS enzyme. Additionally, HR populations contained enhanced amounts of an ortholog of the glutathione transferase phi (F) class 1 (GSTF1) protein, a functional biomarker of non-target-site resistance (NTSR), as confirmed by enzyme-linked immunosorbent assays. Further evidence of NTSR was obtained in dose-response experiments with prosulfocarb applied post-emergence, following pre-treatment with the cytochrome P450 monooxygenase inhibitor malathion, which partially reversed resistance. This study confirms the evolution of multiple and cross resistance to ALS- and ACCase inhibiting herbicides in L. rigidum from Spain by mechanisms consistent with the presence of both TSR and NTSR. Moreover, the results suggest that NTSR, probably by means of enhanced metabolism involving more than one detoxifying enzyme family, confers cross resistance to other SoA. The study further demonstrates the urgent need to monitor and prevent the further evolution of herbicide resistance in L. rigidum in Mediterranean areas.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('16dee640-acef-4b9d-b4fe-2baa785c48ed', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Target-Site Mutations Conferring Herbicide Resistance', 'Murphy BP, Tranel PJ', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8100382', 'https://doi.org/10.3390/plants8100382', 'https://europepmc.org/articles/PMC6843678?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Mutations conferring evolved herbicide resistance in weeds are known in nine different herbicide sites of action. This review summarizes recently reported resistance-conferring mutations for each of these nine target sites. One emerging trend is an increase in reports of multiple mutations, including multiple amino acid changes at the glyphosate target site, as well as mutations involving two nucleotide changes at a single amino acid codon. Standard reference sequences are suggested for target sites for which standards do not already exist. We also discuss experimental approaches for investigating cross-resistance patterns and for investigating fitness costs of specific target-site mutations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8a2f4621-9251-4605-87c2-a06578b51c29', 'ff24ee3d-88a5-42a5-89a3-1fc9f96ea548', 'Transcriptome Analysis Reveals an Eicosapentaenoic Acid Accumulation Mechanism in a Schizochytrium sp. Mutant', 'Ou Y, Li Y, Feng S, Wang Q, Yang H', 2023, 'Microbiology spectrum', '10.1128/spectrum.00130-23', 'https://doi.org/10.1128/spectrum.00130-23', 'https://europepmc.org/articles/PMC10269799?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Eicosapentaenoic acid (EPA) is an omega-3 long-chain polyunsaturated fatty acid (PUFA) essential for human health. Schizochytrium is a marine eukaryote that has been widely utilized for the synthesis of PUFAs. The current low potency and performance of EPA production by fermentation of Schizochytrium spp. limits its prospect in commercial production of EPA. Since the synthesis pathway of EPA in Schizochytrium spp. is still unclear, mutagenesis combined with efficient screening methods are still desirable. In this study, a novel screening strategy was developed based on a two-step progressive mutagenesis method based on atmospheric and room temperature plasma (ARTP) and diethyl sulfate (DES) after multiple stresses (sethoxydim, triclosan and 2,2''-bipyridine) compound screening. Finally, the mutant strain DBT-64 with increased lipid (1.57-fold, 31.71 g/L) and EPA (5.64-fold, 1.86 g/L) production was screened from wild-type (W) strains; the docosahexaenoic acid (DHA) content of mutant DBT-64 (M) was 11.41% lower than that of wild-type strains. Comparative transcriptomic analysis showed that the expression of genes related to the polyketide synthase, fatty acid prolongation, and triglyceride synthesis pathways was significantly upregulated in the mutant strain, while the expression of genes involved in the β-oxidation pathway and fatty acid degradation pathway was downregulated in favor of EPA biosynthesis in Schizochytrium. This study provides an effective strain improvement method to enhance EPA accumulation in Schizochytrium spp. IMPORTANCE Schizochytrium, a marine eukaryotic microorganism, has emerged as a candidate for the commercial production of PUFAs. EPA is an omega-3 PUFA with preventive and therapeutic effects against cardiovascular diseases, schizophrenia, and other disorders. Currently, the low potency and performance of EPA production by Schizochytrium spp. limits its commercialization. In this study, we performed two-step progressive mutagenesis based on ARTP and DES and screened multiple stresses (sethoxydim, triclosan, and 2,2''-bipyridine) to obtain the EPA-high-yielding Schizochytrium mutant. In addition, high expression of the polyketide synthase pathway, fatty acid elongation pathway, and triglyceride synthesis pathway in the mutants was confirmed by transcriptomic analysis. Therefore, the multistress screening platform established in this study is important for breeding EPA-producing Schizochytrium spp. and provides valuable information for regulating the proportion of EPA in microalgal lipids by means of genetic engineering.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('670efc51-40b9-4912-a208-5ca83c22561f', '3b187d3e-3864-419a-92a7-971d1a27f044', 'A herbicide resistance risk assessment for weeds in wheat and barley crops in New Zealand', 'Ngow Z, Chynoweth RJ, Gunnarsson M, Rolston P, Buddenhagen CE', 2020, 'PloS one', '10.1371/journal.pone.0234771', 'https://doi.org/10.1371/journal.pone.0234771', 'https://europepmc.org/articles/PMC7316288?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'We estimated the risk of selecting for herbicide resistance in 101 weed species known to occur in wheat and barley crops on farms in New Zealand. A protocol was used that accounts for both the risk that different herbicides will select for resistance and each weed''s propensity to develop herbicide resistance based on the number of cases worldwide. To provide context we documented current herbicide use patterns. Most weeds (55) were low-risk, 30 were medium-risk and 16 high-risk. The top ten scored weeds were Echinochloa crus-galli, Poa annua, Lolium multiflorum, Erigeron sumatrensis, Raphanus raphanistrum, Lolium perenne, Erigeron bonariensis, Avena fatua, Avena sterilis and Digitaria sanguinalis. Seven out of ten high-risk weeds were grasses. The most used herbicides were synthetic auxins, an enolpyruvylshikimate-phosphate synthase inhibitor, acetolactate synthase (ALS) inhibitors, carotenoid biosynthesis inhibitors, and long-chain fatty acid inhibitors. ALS-inhibitors were assessed as posing the greatest risk for more species than other modes-of-action. Despite pre-emergence herbicides being known to delay resistance, New Zealand farmers only applied flufenacet and terbuthlazine with high frequency. Based on our analysis, surveys for herbicide-resistant species should focus on the high-risk species we identified. Farmer extension efforts in New Zealand should address resistance evolution in cropping weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8dda7574-045b-4919-97cf-e9fc77684eca', '3b187d3e-3864-419a-92a7-971d1a27f044', 'A LuALS Mutation with High Sulfonylurea Herbicide Resistance in Linum usitatissimum L', 'Liu C, Zhang T, Yang X, Wang L, Long Y, Hasi A, Pei X', 2023, 'International journal of molecular sciences', '10.3390/ijms24032820', 'https://doi.org/10.3390/ijms24032820', 'https://europepmc.org/articles/PMC9917167?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'The cultivation of herbicide-resistant crops is an effective tool for weed management in agriculture. Weed control in flax (Linum usitatissimum L.) remains challenging due to the lack of available herbicide-resistant cultivars. In this study, a mutant resistant to acetolactate synthase (ALS)-inhibiting herbicides was obtained by ethyl methanesulphonate (EMS) mutagenesis using an elite cultivar, Longya10. Whole-plant dose-response assays revealed that, compared to Longya10, the mutant was 11.57-fold more resistant to tribenuron-methyl (TBM) and slightly resistant to imazethapyr (resistance index (mutant/Longya10) Arabidopsis thaliana ALS sequence) substitution within the LuALS1, conferring high resistance to sulfonylurea herbicides in the mutant. Additionally, two cleaved amplified polymorphic sequence (CAPS) markers, BsaI-LuALS1 and EcoO109I-LuALS1, were developed based on the mutation site for marker assistant selection in breeding. Moreover, the mutant did not cause losses in natural field conditions. We find a mutant with ALS-inhibiting herbicide resistance chemically induced by EMS mutagenesis, providing a valuable germplasm for breeding herbicide-resistant flax varieties.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e76f2a5c-2f1d-4e9a-99e6-bf99f4e4b1f8', '3b187d3e-3864-419a-92a7-971d1a27f044', 'A novel mutation in SoIAA20 confers cross-resistance to 2,4-Dichlorophenoxyacetic acid and other auxinic herbicides in Sonchus oleraceus', 'Krishnan M, Petrovic T, Schwerdt JG, Merriam AB, Hereward JP, Preston C', 2025, 'Pest management science', '10.1002/ps.8413', 'https://doi.org/10.1002/ps.8413', 'https://europepmc.org/articles/PMC11632205?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'Background2,4-Dichlorophenoxyacetic acid (2,4-D) and other auxinic herbicides are important for weed control in cropping systems globally. Weeds with resistance to 2,4-D and other auxinic herbicides have evolved, including several populations of Sonchus oleraceus from multiple sites in Australia. We report the underlying mechanism in these populations that gives rise to auxinic herbicide resistance.ResultsWe studied a total of three susceptible and eight resistant Sonchus oleraceus populations. All resistant populations had a deletion of three amino acids flanking the degron sequence of an Aux/IAA gene, SoIAA20, which was not found in the three susceptible populations. The eight populations with the resistant allele were also resistant to dicamba, fluroxypyr and clopyralid. The resistant plants also had reduced movement of 2,4-D out of the treated tissues compared to susceptible plants.ConclusionThe paired deletion flanking the degron region of SoIAA20 likely provides resistance to 2,4-D by restricting the movement of 2,4-D from the treated tissue to the rest of the plant. We hypothesise that this deletion keeps the 2,4-D bound to the target site. © 2024 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('94355b75-95e1-4697-a7e9-da716d5f9bdb', '3b187d3e-3864-419a-92a7-971d1a27f044', 'A Proposal for Public and Private Partnership in Extension', 'Krell RK, Fisher ML, Steffey KL', 2016, 'Journal of integrated pest management', '10.1093/jipm/pmw001', 'https://doi.org/10.1093/jipm/pmw001', 'https://europepmc.org/articles/PMC4765505?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by-nc', 'Public funding for Extension in the United States has been decreasing for many years, but farmers'' need for robust information on which to make management decisions has not diminished. The current Extension funding challenges provide motivation to explore a different model for developing and delivering extension. The private sector has partnered with the public sector to fund and conduct agricultural research, but partnering on extension delivery has occurred far less frequently. The fundamental academic strength and established Extension network of the public sector combined with the ability of the private sector to encourage and deliver practical, implementable solutions has the potential to provide measurable benefits to farmers. This paper describes the current Extension climate, presents data from a survey about Extension and industry relationships, presents case studies of successful public- and private-sector extension partnerships, and proposes a framework for evaluating the state of effective partnerships. Synergistic public-private extension efforts could ensure that farmers receive the most current and balanced information available to help with their management decisions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5b358f4c-e73e-4341-9270-3b2902bcb1e3', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Agriculture Development, Pesticide Application and Its Impact on the Environment', 'Tudi M, Daniel Ruan H, Wang L, Lyu J, Sadler R, Connell D, Chu C, Phung DT', 2021, 'International journal of environmental research and public health', '10.3390/ijerph18031112', 'https://doi.org/10.3390/ijerph18031112', 'https://europepmc.org/articles/PMC7908628?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Pesticides are indispensable in agricultural production. They have been used by farmers to control weeds and insects, and their remarkable increases in agricultural products have been reported. The increase in the world''s population in the 20th century could not have been possible without a parallel increase in food production. About one-third of agricultural products are produced depending on the application of pesticides. Without the use of pesticides, there would be a 78% loss of fruit production, a 54% loss of vegetable production, and a 32% loss of cereal production. Therefore, pesticides play a critical role in reducing diseases and increasing crop yields worldwide. Thus, it is essential to discuss the agricultural development process; the historical perspective, types and specific uses of pesticides; and pesticide behavior, its contamination, and adverse effects on the natural environment. The review study indicates that agricultural development has a long history in many places around the world. The history of pesticide use can be divided into three periods of time. Pesticides are classified by different classification terms such as chemical classes, functional groups, modes of action, and toxicity. Pesticides are used to kill pests and control weeds using chemical ingredients; hence, they can also be toxic to other organisms, including birds, fish, beneficial insects, and non-target plants, as well as air, water, soil, and crops. Moreover, pesticide contamination moves away from the target plants, resulting in environmental pollution. Such chemical residues impact human health through environmental and food contamination. In addition, climate change-related factors also impact on pesticide application and result in increased pesticide usage and pesticide pollution. Therefore, this review will provide the scientific information necessary for pesticide application and management in the future.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('88cae40d-62b9-4c0a-aaea-76264055a09c', '3b187d3e-3864-419a-92a7-971d1a27f044', 'An Asp376Glu substitution in ALS gene and enhanced metabolism confers high tribenuron-methyl resistance in Sinapis alba', 'Palma-Bautista C, Vázquez-García JG, Osuna MD, Garcia-Garcia B, Torra J, Portugal J, De Prado R', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.1011596', 'https://doi.org/10.3389/fpls.2022.1011596', 'https://europepmc.org/articles/PMC9692003?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Acetolactate synthase (ALS) inhibiting herbicides (group 2) have been widely applied for the last 20 years to control Sinapis alba in cereal crops from southern Spain. In 2008, a tribenuron-methyl (TM) resistant (R) S. alba population was first reported in a cereal field in Malaga (southern Spain). In 2018, three suspected R S. alba populations (R1, R2 and R3) to TM were collected from three different fields in Granada (southern Spain, 100 km away from Malaga). The present work aims to confirm the putative resistance of these populations to TM and explore their resistance mechanisms. Dose-response assays showed that the R1, R2 and R3 populations ranging between 57.4, 44.4 and 57.1 times more resistance to TM than the susceptible population (S). A mutation in the ALS gene (Asp376Glu) was detected in the Rs S. alba populations. 14C-metabolism studies show that metabolites and TM were changing significantly faster in the R than in the S plants. Alternative chemical control trials showed that 2,4-D and MCPA (auxin mimics), glyphosate (enolpyruvyl shikimate phosphate synthase,EPSPS, inhibitor-group 9), metribuzin (PSII inhibitors/Serine 264 Binders, -group 5) and mesotrione (hydroxyphenyl pyruvate dioxygenase, HPPD, inhibitor-group 27) presented a high control of the four populations of S. alba tested, both S and R. Based on these results, it is the first case described where the Asp376Glu mutation and P450-mediated metabolism participates in resistance to TM in S. alba. Comparing these results with those found in the S. alba population in Malaga in 2008, where the resistance was TSR type (Pro197Ser), we can suggest that despite the geographical proximity (over 100 km), the resistance in these cases was due to different evolutionary events.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('00ac57d3-a326-4923-8dc8-35e7ba1b3f9c', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Arbuscular mycorrhizal fungi and their response to pesticides', 'Hage-Ahmed K, Rosner K, Steinkellner S', 2019, 'Pest management science', '10.1002/ps.5220', 'https://doi.org/10.1002/ps.5220', 'https://europepmc.org/articles/PMC6587947?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'Arbuscular mycorrhizal fungi (AMF) form symbioses with the majority of plant species and can provide multiple benefits to the host plant. In agro-ecosystems, the abundance and community structure of AMF are affected by agricultural management practices. This review describes and discusses current knowledge on the effects of inorganic and organic chemical pesticides on AMF in the conflicting area between agricultural use and environmental concerns. Variable effects have been reported following chemical pesticide use, ranging from neutral to positive and negative. Moreover, a species-specific reaction has been documented. The reported effects of pesticides on arbuscular mycorrhizal symbiosis are very diverse, and even when the same substance is investigated, the results are often contradictory. These effects depend on many parameters, such as the active substance, the mode of action, the mode of application and the dosage. In the field, determinants such as the physico-chemical behavior of the active substances, the soil type and other soil microorganisms contribute to the fate of pesticides and thus the amount of active substances to which AMF are exposed. This review highlights that the fate of AMF following pesticide use needs to be addressed in a broader agro-ecosystem context. © 2018 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('391fc0dd-93ac-4695-95c6-af4235fbb362', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Assessment of the ameliorative effect of curcumin on pendimethalin-induced genetic and biochemical toxicity', 'Acar A, Singh D, Srivastava AK', 2022, 'Scientific reports', '10.1038/s41598-022-06278-5', 'https://doi.org/10.1038/s41598-022-06278-5', 'https://europepmc.org/articles/PMC8828890?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The present study aimed to assess the toxic effects of pendimethalin herbicide and protective role of curcumin using the Allium test on cytological, biochemical and physiological parameters. The effective concentration (EC50) of pendimethalin was determined at 12 mg/L by the root growth inhibition test as the concentration reducing the root length by 50%. The roots of Allium cepa L. was treated with tap water (group I), 5 mg/L curcumin (group II), 10 mg/L curcumin (group III), 12 mg/L pendimethalin (group IV), 12 mg/L pendimethalin + 5 mg/L curcumin (group V) and 12 mg/L pendimethalin + 10 mg/L curcumin (group VI). The cytological (mitotic index, chromosomal abnormalities and DNA damage), physiological (rooting percentage, root length, growth rate and weight gain) and oxidative stress (malondialdehyde level, superoxide dismutase level, catalase level and glutathione reductase level) indicators were determined after 96 h of treatment. The results revealed that pendimethalin treatment reduced rooting percentage, root length, growth rate and weight gain whereas induced chromosomal abnormalities and DNA damage in roots of A. cepa L. Further, pendimethalin exposure elevated malondialdehyde level followed by antioxidant enzymes. The activities of superoxide dismutase and catalase were up-regulated and glutathione reductase was down-regulated. The molecular docking supported the antioxidant enzymes activities result. However, a dose-dependent reduction of pendimethalin toxicity was observed when curcumin was supplied with pendimethalin. The maximum recovery of cytological, physiological and oxidative stress parameters was recorded at 10 mg/L concentration of curcumin. The correlation studies also revealed positive relation of curcumin with rooting percentage, root length, weight gain, mitotic activity and glutathione reductase enzyme level while an inverse correlation was observed with chromosomal abnormalities, DNA damage, superoxide dismutase and catalase enzyme activities, and lipid peroxidation indicating its protective effect.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9984cc4-7a1a-4366-8559-15248ed6517d', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Beyond the Solvent: Engineering Ionic Liquids for Biomedical Applications-Advances, Challenges, and Future Directions', 'Elgharbawy AAM, Noor NM, Azmi NAN, Dewanti BSD', 2026, 'Molecules (Basel, Switzerland)', '10.3390/molecules31020305', 'https://doi.org/10.3390/molecules31020305', 'https://europepmc.org/articles/PMC12843688?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Ionic liquids (ILs) have emerged as multifunctional compounds with low volatility, high thermal stability, and tunable solvation capabilities, making them highly promising for biomedical applications. First explored in the late 1990s and early 2000s for enhancing the thermal stability of enzymes, antimicrobial agents, and controlled release systems, ILs have since gained significant attention in drug delivery, antimicrobial treatments, medical imaging, and biosensing. This review examines the diverse functions of ILs in contemporary therapeutics and diagnostics, highlighting their transformative capabilities in improving drug solubility, bioavailability, transdermal permeability, and pathogen inactivation. In drug delivery, ILs improve solubility of bioactive compounds, with several IL formulations achieving substantial solubility enhancements for poorly soluble drugs. Bio-ILs, in particular, show promise in enhancing drug delivery systems, such as improving transdermal permeability. ILs also exhibit significant antimicrobial and antiviral activity, offering new avenues for combating resistant pathogens. Despite their broad potential, challenges such as cytotoxicity, long-term metabolic effects, and the stability of ILs in physiological conditions persist. While much research has focused on their physicochemical properties, biological activity and in vivo studies are still underexplored. The future directions for ILs in biomedical applications include the development of bioengineered ILs and hybrid ILs, combining functional components like nanoparticles and polymers to create multifunctional materials. These ILs, derived from renewable resources, show great promise in personalized medicine and clinical applications. Further research is necessary to evaluate their pharmacokinetics, biodistribution, and long-term safety to fully realize their biomedical potential. This study emphasizes the potential of ILs to transform therapeutic and diagnostic technologies by highlighting present shortcomings and offering pathways for clinical translation, while also debating the need for continuous research to fully utilize their biomedical capabilities.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f8ae16db-0fe1-4685-beee-819843dbfbd8', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'A Critical Review: Gel-Based Edible Inks for 3D Food Printing: Materials, Rheology-Geometry Mapping, and Control', 'Qin Z, Yang Y, Zhang Z, Li F, Hou Z, Li Z, Shi J, Shen T', 2025, 'Gels (Basel, Switzerland)', '10.3390/gels11100780', 'https://doi.org/10.3390/gels11100780', 'https://europepmc.org/articles/PMC12563521?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Edible hydrogels are the central material class in 3D food printing because they reconcile two competing needs: (i) low resistance to flow under nozzle shear and (ii) fast recovery of elastic structure after deposition to preserve geometry. This review consolidates the recent years of progress on hydrogel formulations-gelatin, alginate, pectin, carrageenan, agar, starch-based gels, gellan, and cellulose derivatives, xanthan/konjac blends, protein-polysaccharide composites, and emulsion gels alongside a critical analysis of printing technologies relevant to food: extrusion, inkjet, binder jetting, and laser-based approaches. For each material, this review connects gelation triggers and compositional variables to rheology signatures that govern printability and then maps these to process windows and post-processing routes. This review consolidates a decision-oriented workflow for edible-hydrogel printability that links formulation variables, process parameters, and geometric fidelity through standardized test constructs (single line, bridge, thin wall) and rheology-anchored gates (e.g., yield stress and recovery). Building on these elements, a "printability map/window" is formalized to position inks within actionable operating regions, enabling recipe screening and process transfer. Compared with prior reviews, the emphasis is on decisions: what to measure, how to interpret it, and how to adjust inks and post-set enablers to meet target fidelity and texture. Reporting minima and a stability checklist are identified to close the loop from design to shelf.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d44a29eb-ad5d-487a-ade4-fc4dd4f5dc63', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Chitosan Effects on Plant Systems', 'Malerba M, Cerana R', 2016, 'International journal of molecular sciences', '10.3390/ijms17070996', 'https://doi.org/10.3390/ijms17070996', 'https://europepmc.org/articles/PMC4964372?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Chitosan (CHT) is a natural, safe, and cheap product of chitin deacetylation, widely used by several industries because of its interesting features. The availability of industrial quantities of CHT in the late 1980s enabled it to be tested in agriculture. CHT has been proven to stimulate plant growth, to protect the safety of edible products, and to induce abiotic and biotic stress tolerance in various horticultural commodities. The stimulating effect of different enzyme activities to detoxify reactive oxygen species suggests the involvement of hydrogen peroxide and nitric oxide in CHT signaling. CHT could also interact with chromatin and directly affect gene expression. Recent innovative uses of CHT include synthesis of CHT nanoparticles as a valuable delivery system for fertilizers, herbicides, pesticides, and micronutrients for crop growth promotion by a balanced and sustained nutrition. In addition, CHT nanoparticles can safely deliver genetic material for plant transformation. This review presents an overview on the status of the use of CHT in plant systems. Attention was given to the research that suggested the use of CHT for sustainable crop productivity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb1ec624-f698-416b-ba3a-a919e561606c', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Design, Synthesis, Herbicidal Activity, and Structure-Activity Relationship Study of Novel 6-(5-Aryl-Substituted-1-Pyrazolyl)-2-Picolinic Acid as Potential Herbicides', 'Feng T, Liu Q, Xu ZY, Li HT, Wei W, Shi RC, Zhang L, Cao YM', 2023, 'Molecules (Basel, Switzerland)', '10.3390/molecules28031431', 'https://doi.org/10.3390/molecules28031431', 'https://europepmc.org/articles/PMC9920234?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Picolinic acid and picolinate compounds are a remarkable class of synthetic auxin herbicides. In recent years, two new picolinate compounds, halauxifen-methyl (ArylexTM active) and florpyrauxifen-benzyl (RinskorTM active), have been launched as novel herbicides. Using their structural skeleton as a template, 33 4-amino-3,5-dicholor-6-(5-aryl-substituted-1-pytazolyl)-2-picolinic acid compounds were designed and synthesized for the discovery of compounds with potent herbicidal activity. The compounds were tested for inhibitory activity against the growth of Arabidopsis thaliana roots, and the results demonstrated that the IC50 value of compound V-7 was 45 times lower than that of the halauxifen-methyl commercial herbicide. Molecular docking analyses revealed that compound V-7 docked with the receptor auxin-signaling F-box protein 5 (AFB5) more intensively than picloram. An adaptive three-dimensional quantitative structure-activity relationship model was constructed from these IC50 values to guide the next step of the synthetic strategy. Herbicidal tests of the new compounds indicated that compound V-8 exhibited better post-emergence herbicidal activity than picloram at a dosage of 300 gha-1, and it was also safe for corn, wheat, and sorghum at this dosage. These results demonstrated that 6-(5-aryl-substituted-1-pyrazolyl)-2-picolinic acid compounds could be used as potential lead structures in the discovery of novel synthetic auxin herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5857c3d0-cc79-4098-875a-7a5a55b7b565', '3b187d3e-3864-419a-92a7-971d1a27f044', 'EPSPS Gene Copy Number and Whole-Plant Glyphosate Resistance Level in Kochia scoparia', 'Gaines TA, Barker AL, Patterson EL, Westra P, Westra EP, Wilson RG, Jha P, Kumar V', 2016, 'PloS one', '10.1371/journal.pone.0168295', 'https://doi.org/10.1371/journal.pone.0168295', 'https://europepmc.org/articles/PMC5161467?pdf=render', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by', 'Glyphosate-resistant (GR) Kochia scoparia has evolved in dryland chemical fallow systems throughout North America and the mechanism of resistance involves 5-enolpyruvylshikimate-3-phosphate synthase (EPSPS) gene duplication. Agricultural fields in four states were surveyed for K. scoparia in 2013 and tested for glyphosate-resistance level and EPSPS gene copy number. Glyphosate resistance was confirmed in K. scoparia populations collected from sugarbeet fields in Colorado, Wyoming, and Nebraska, and Montana. Glyphosate resistance was also confirmed in K. scoparia accessions collected from wheat-fallow fields in Montana. All GR samples had increased EPSPS gene copy number, with median population values up to 11 from sugarbeet fields and up to 13 in Montana wheat-fallow fields. The results indicate that glyphosate susceptibility can be accurately diagnosed using EPSPS gene copy number.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d9eb74f5-42e9-472a-bdad-ac4f1378bd40', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Evaluating digestibility and toxicity of native warm-season grasses for equines', 'Ghajar SM, McKenzie H, Fike J, McIntosh B, Tracy BF', 2021, 'Translational animal science', '10.1093/tas/txaa224', 'https://doi.org/10.1093/tas/txaa224', 'https://europepmc.org/articles/PMC7810257?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Introduced cool-season grasses are dominant in Virginia''s grasslands, but their high digestible energy and nonstructural carbohydrate (NSC) levels pose a risk for horses prone to obesity and laminitis. Native warm-season grasses (NWSGs) have lower digestible energy and NSC levels that may be more suitable for horses susceptible to laminitis. Although NWSGs have desirable characteristics, they are novel forages for horses. Little is known about NWSG intake or potential toxicity to horses or how grazing by horses may affect NWSG swards. The overall objectives of this research were to 1) assess voluntary intake, toxicological response, and apparent digestibility of NWSG hays fed to horses; and 2) evaluate the characteristics of three NWSG species under equine grazing. For the first objective, a hay feeding trial using indiangrass (IG) (Sorghastrum nutans) and big bluestem (BB) (Andropogon gerardii) was conducted with nine Thoroughbred geldings in a replicated 3 × 3 Latin square design. Voluntary dry matter intake of IG and BB hays by horses were 1.3% and 1.1% of BW/d, lower than orchardgrass (Dactylis glomerata), an introduced cool-season grass, at 1.7% of BW/d (P = 0.0020). Biomarkers for hepatotoxicity remained within acceptable ranges for all treatments. Apparent dry matter digestibility (DMD) did not differ among hays, ranging from 39% to 43%. NSC levels ranged from 4.4% to 5.4%, below maximum recommended concentrations for horses susceptible to laminitis. For the second objective, a grazing trial was conducted comparing IG, BB, and eastern gamagrass (EG) (Tripsacum dactyloides) yields, forage losses, changes in vegetative composition, and effects on equine bodyweight. Nine, 0.1-ha plots were seeded with one of the three native grass treatments, and each plot was grazed by one Thoroughbred gelding in two grazing bouts, one in July and another in September 2019. IG had the greatest available forage, at 4,340 kg/ha, compared with 3,590 kg/ha from BB (P < 0.0001). EG plots established poorly, and had only 650 kg/ha available forage during the experiment. Grazing reduced standing cover of native grasses in IG and BB treatments by about 30%. Horses lost 0.5-1.5 kg BW/d on all treatments. Findings suggest IG and BB merit further consideration as forages for horses susceptible to obesity and pasture-associated laminitis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a31e968c-8fe9-4596-a695-69dee32021e7', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Fertilizer and fungicide reduce herbicide efficacy and enhance growth of invasive common tansy (Tanacetum vulgare)', 'Bennett JA, Elshamy O, Trefiak M, Wasan JP', 2025, 'PloS one', '10.1371/journal.pone.0333818', 'https://doi.org/10.1371/journal.pone.0333818', 'https://europepmc.org/articles/PMC12543190?pdf=render', NULL, NULL, 15, NULL, 'prairies', 4, 'cc by', 'Common tansy (Tanacetum vulgare; Asteraceae) is a widespread invasive species in North America that threatens biodiversity and agricultural productivity by displacing resident vegetation. Combined with being unpalatable, it can be toxic and thus poses significant challenges for the livestock industry. Current tansy control strategies are largely chemical and rely on a suite of synthetic auxin herbicides. The need for reapplication may lead to resistance development in addition to significant biodiversity losses. Recent work suggests that invasive Asteraceae may rely on symbiotic arbuscular mycorrhizal fungi (AMF) to give them a competitive advantage. We hypothesized that suppressing AMF would reduce tansy growth and reduce reliance on more damaging herbicides. Fungicides and fertilizers, known to suppress AMF, may be potential tools for tansy suppression by reducing its competitive ability; however, both may also enhance invader growth and represent a significant risk. We conducted a two-year experiment crossing three herbicides, with varying degrees of residual control, with fungicide and fertilizer treatments to explore their effects on tansy. Despite initially reducing AMF abundances, both fertilizer and fungicide unexpectedly improved tansy growth, especially when applied with the non-residual herbicide (2,4-D), where strong control was eliminated by either treatment. This suggests that, at least at our study site, any suppression of AMF did not affect tansy strongly enough to overcome the benefits of increased nutrients and pathogen suppression. Independent of fungicide or fertilizer, all three herbicides reduced tansy biomass and increased community biomass by year two, driven by increases in grasses. The most effective herbicide (picloram), however, also caused the greatest declines in broadleaf plants, leading to significant species losses. Conversely, 2,4-D was only slightly less effective after two years, while having limited non-target effects. Non-residual herbicides, like 2-4D, may offer a better balance between tansy control and biodiversity conservation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d1ee88d-1d03-4b00-9feb-6eb2470caedd', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Alberta barley production survey', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/alberta-barley-production-survey', 'https://open.alberta.ca/dataset/2528e07f-0498-484c-b97c-e05238b7bd99/resource/01bcc14f-39ce-4c37-9ce9-3be288e0c3e1/download/0163010127484-alberta-barley-production-survey.pdf', NULL, NULL, 28, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report presents the findings of an extensive survey conducted during the fall of 1991 and early winter of 1992, covering barley production practices across Alberta. It details the methodologies and results from a 28-page questionnaire completed by 412 barley growers, categorized into eight agro-ecological areas and one irrigation area. The analysis focuses on management factors contributing to higher barley yields, comparing top producers'' techniques with provincial averages. The document provides detailed data on various aspects of barley cultivation, including tillage, seeding, fertilization, pest control, and harvesting.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1affa792-46e4-4002-b743-5bece6d4993a', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Field Survey and Resistance Occurrence to ALS-Inhibiting Herbicides in Glebionis coronaria L. in Tunisian Wheat Crops', 'Hada Z, Khammassi M, Jenfaoui H, Menchari Y, Torra J, Souissi T', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9091210', 'https://doi.org/10.3390/plants9091210', 'https://europepmc.org/articles/PMC7570124?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Glebionis coronaria (L.) Cass. ex Spach is a troublesome weed in cereal cropping systems in northern Tunisia. Recently, failures in controlling this weed have been reported by farmers. Field surveys and farmers interviews were conducted to highlight the potential causes of G. coronaria occurrence and the associated yield losses in wheat. Survey results revealed a significant correlation between farmers'' awareness of resistance occurrence and cultural practices, mainly sowing date and tillage, while G. coronaria abundance was related to the lack of herbicide rotation and the frequency of ALS-inhibiting herbicide use. High G. coronaria infestations (more than 20 plants/m2) caused a significant decrease in wheat grain yield, reaching almost 75% at a density of 100 plants/m2. Field and pot experiments showed low efficacies of ALS-inhibiting herbicides to control G. coronaria populations. The application of field rates of tribenuron-methyl and mesosulfuron + iodosulfuron failed to control the tested populations, and generally, G. coronaria dry weight increased compared to nontreated ones (potential hormetic effect). These findings were further investigated in two selected resistant populations through tribenuron dose-response experiments, plants from both populations exhibited high resistance factors (greater than 300), surviving up to 16-fold the recommended field dose. This is the first report for G. coronaria resistance occurrence to ALS-inhibiting herbicides in Tunisia and the second case worldwide.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac0763df-9fa6-4ea2-a4ac-c161694cc2a2', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Galium spurium and G. aparine Resistance to ALS-Inhibiting Herbicides in Northern Greece', 'A.P. PAPAPANAGIOTOU, C.A. DAMALAS, I. BOSMALI, P. MADESIS, G.C. MENEXES, I.G. ELEFTHEROHORINOS', 2019, 'Planta Daninha', '10.1590/s0100-83582019370100106', 'https://doi.org/10.1590/s0100-83582019370100106', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-83582019000100196&tlng=en', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT: Knowledge of the level of resistance of weed populations and the herbicides to which they survive is important for recommending suitable advice to farmers and allowing the selection of appropriate management strategies. Whole-plant dose response experiments were carried out to assess the resistance status of eight putative resistant Galium spurium L. populations and one G. aparine L. population, originating from northern Greece. High levels of resistance of both species to the ALS-inhibiting herbicides chlorsulfuron and tribenuron were found, while their susceptible populations were controlled. Three G. spurium (GS) populations showed additional cross-resistance to [florasulam + 2,4-D], whereas the remaining five resistant GS populations were controlled with [tribenuron + mecoprop-p], [florasulam + 2,4-D], and [florasulam + aminopyralid]. Also, [florasulam + fluroxypyr] was very effective against two resistant GS populations tested. DNA sequence alignment of the three GS populations (GS 1, GS 6, and GS 8) with cross-resistance to chlorsulfuron, tribenuron, and florasulam revealed a point mutation at Trp-574 (tryptophan-574), causing amino acid substitution by Leu (leucine). The G. aparine (GA) population showed cross-resistance to chlorsulfuron and tribenuron, but it was controlled with [tribenuron + mecoprop-p], [florasulam + aminopyralid], [florasulam + 2,4-D], and [florasulam + fluroxypyr]. The confirmed cross-resistance of both GS and GA species to chlorsulfuron and tribenuron in northern Greece is the first report of Galium spp. resistance to ALS-inhibiting herbicides in Europe. Finally, all populations (8 GS and 1 GA) that showed resistance to chlorsulfuron and tribenuron were controlled with the mixtures [tribenuron + mecoprop-p] and [florasulam + fluroxypyr].', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f7c284ce-0c35-4f55-b244-81a392120bbf', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Herbicides Have Minimal and Variable Effects on the Structure and Function of Bacterial Communities in Agricultural Soils', 'Gaylord M, Thompson A, Dayan FE, Kniss AR, Reichert D, Otto K, Larson R, Trivedi P', 2025, 'Environmental microbiology', '10.1111/1462-2920.70148', 'https://doi.org/10.1111/1462-2920.70148', 'https://europepmc.org/articles/PMC12260311?pdf=render', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'Synthetic herbicides are relied on for weed management in the United States, and non-chemical alternatives, such as tillage, can be inefficient and expensive at an agricultural scale. Previous research examining the influence of weed management strategies on soil microbial communities has shown variability and inconsistency in experimental design and results. This study investigates the impact of repeated applications of glyphosate, a mixture of selective herbicides, and tillage on soil bacterial communities in sugar beet production across two locations in the United States. Using next-generation sequencing and various assays, we explore the effects on bacterial community structure, composition, and function related to nutrient cycling and soil health. Although transient and minor differences in bacterial community structure could be observed for herbicides and tillage, these statistical differences do not appear to be biologically relevant as the soil function was equivalent for all applied treatments. Our findings provide evidence that repeated herbicide usage does not directly impact soil health and function in sugar beet production. This study emphasises the need for well-replicated, field-realistic, and long-term experiments to understand the ecological consequences of herbicides and tillage in agroecosystems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('02bb9dfe-edbe-49a3-b6f5-2431dc2092b3', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Identification of chromosomes in Triticum aestivum possessing genes that confer tolerance to the synthetic auxin herbicide halauxifen-methyl', 'Obenland OA, Riechers DE', 2020, 'Scientific reports', '10.1038/s41598-020-65434-x', 'https://doi.org/10.1038/s41598-020-65434-x', 'https://europepmc.org/articles/PMC7250930?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by', 'Natural tolerance in hexaploid bread wheat (Triticum aestivum L.) to synthetic auxin herbicides is primarily due to rapid metabolic detoxification, but genes encoding these herbicide-detoxifying enzymes have yet to be identified. Herbicide safeners are commonly applied in wheat to achieve herbicide tolerance by inducing the expression and activity of herbicide-detoxifying enzymes. While safeners have been utilized for decades, knowledge of mechanisms that induce gene expression is limited. Our objective was to identify wheat chromosomes possessing genes that endow natural or safener-induced tolerance to halauxifen-methyl (HM), a postemergence (POST) wheat-selective synthetic auxin herbicide, using alien substitution (the S genome of Aegilops searsii) and aneuploid lines. Two POST rates of HM were applied to seedlings with 1-2 leaves (Zadoks stages 11-12), and the highest HM rate was also applied with the safener cloquintocet-mexyl (CM). Wheat chromosomes possessing genes associated only with natural HM tolerance were identified because Ae. searsii is HM-sensitive but CM-responsive. Lines with substitutions for 5A and 5B displayed sensitivity to HM, and experiments with nullisomic-tetrasomic (NT) lines further indicated major genes associated with HM tolerance are present on 5A and 5B chromosomes. However, the genes on 5A appear to play a larger role because lines lacking 5A chromosomes displayed more sensitivity than lines lacking 5B. Overall, these results can be utilized to guide future transcriptome analyses to identify candidate genes that confer HM tolerance in wheat.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c9d9f77-c481-49d1-bc7c-330367a34531', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Improved Bioherbicidal Efficacy of Bipolaris eleusines through Herbicide Addition on Weed Control in Paddy Rice', 'Zhang J, Duan G, Yang S, Yu L, Lu Y, Tang W, Yang Y', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11192659', 'https://doi.org/10.3390/plants11192659', 'https://europepmc.org/articles/PMC9572137?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Bipolaris eleusines was mixed with herbicides to improve the control of barnyardgrass (Echinochloa crus-galli), a noxious weed in rice fields. The compatibility of B. eleusines with herbicides was evaluated for toxic effects on spore germination and mycelium growth in vitro tests, and varied effects were observed with different chemical products. Briefly, 25 g/L penoxsulam OD plus 10% bensulfuron-methyl WP were much more compatible with B. eleusines, and there was no inhibition of spore germination but the promotion of mycelium growth of B. eleusines at all treatment rates. Under greenhouse conditions, the coefficient of the specificity of B. eleusines conidial agent was determined as 3.91, closer to the herbicidal control of 2.89, showing it is highly specific between rice and barnyardgrass. Field experiments in 2011 and 2012 showed that B. eleusines conidial agent displayed good activity on barnyardgrass, monochoria [Monochoria vaginalis (Burm.f.) Presl. Ex Kunth.], and small-flower umbrella sedge (Cyperus difformis L.) and had no negative impact on the rice plant. It also reduced the loss of rice yield when compared with the non-treated control and could make this pathogen a conidial agent for commercial bioherbicidal development in the future.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('913d174b-67fd-4283-9d04-372ea55e7a7c', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Investigating the impacts of airborne dust on herbicide performance on Amaranthus retroflexus', 'Sharifi Kalyani F, Babaei S, Zafarsohrabpour Y, Nosratti I, Gage K, Sadeghpour A', 2024, 'Scientific reports', '10.1038/s41598-024-54134-5', 'https://doi.org/10.1038/s41598-024-54134-5', 'https://europepmc.org/articles/PMC10869696?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Dust pollution poses environmental hazards, affecting agriculture through reduced sunlight exposure, photosynthesis, crop yields, and food security. This study explores the interference of dust pollution on herbicide efficacy to control weeds in a semi-arid region. In a factorial experiment conducted in 2019 and replicated in 2020, the interaction of dust and various herbicide applications, including bentazon, sulfosulfuron, tribenuron-methyl, aminopyralid + florasulam, foramsulfuron + iodosulfuron + thiencarbazone, 2,4-D + MCPA, and acetochlor, in controlling Amaranthus retroflexus L. were assessed. Dust induced a 9.2% reduction in the total chlorophyll content of A. retroflexus, while herbicide application independently led to a 67.5% decrease. Contrary to expectations, herbicides performed better in dust, except bentazon, which caused a 28% drop in plant height and a 29% decrease in total biomass compared to non-dust conditions. Both herbicides and dust exerted suppressive effects on A. retroflexus''s leaf and stem weights and overall biomass. Despite dust presence, tribenuron-methyl (95.8%), aminopyralid + florasulam (95.7%), sulfosulfuron (96.5%), and foramsulfuron + iodosulfuron + thiencarbazone (97.8%) effectively controlled A. retroflexus. These findings indicate that dust''s effect on herbicide efficacy is herbicide-dependent but except bentazon, dust generally increased herbicide efficacy and amplified the control of A. retroflexus.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4b6a7f65-6920-477f-90bc-8d7cb3b3ebf9', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Management of Pyrenophora teres f. teres, the Causal Agent of Net Form Net Blotch of Barley, in A Two-Year Field Experiment in Central Italy', 'Tini F, Covarelli L, Ricci G, Balducci E, Orfei M, Beccari G', 2022, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens11030291', 'https://doi.org/10.3390/pathogens11030291', 'https://europepmc.org/articles/PMC8954409?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Pyrenophora teres is the causal agent of barley net blotch (NB), a disease that can be found in two different forms: net form (NFNB), caused by P. teres f. teres, and spot form (SFNB), caused by P. teres f. maculata. A two-year field experiment was carried out to evaluate the response to NB of six different barley cultivars for malt or feed/food production. In addition, the efficacy of several recently developed foliar fungicides with different modes of action (SDHI, DMI, and QoI) towards the disease was examined. After NB leaf symptom evaluation, the identification of P. teres forms was performed. Grain yield was determined, and pathogen biomass was quantified in the grain by qPCR. In the two experimental years characterized by different climatic conditions, only P. teres f. teres was detected. The tested cultivars showed different levels of NFNB susceptibility. In particular, the two-row cultivars for malt production showed the highest disease incidence. All applied fungicides exhibited a high efficacy in reducing disease symptoms on leaves and pathogen accumulation in grains. In fact, high levels of fungal biomass were detected only in the grain of the untreated malting barley cultivars. For some cultivars, grain yield was positively influenced by the application of fungicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0cfc254b-49f3-4086-a4c4-00d1faca212d', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Milestone – a selective herbicide for the control of important grasses and broadleaved weeds in winter oilseed rape', 'Zotz, Agnes, Bernhard, Ulrich, Koops, Anke, de Gaujac, Xavier', 2016, 'Julius-Kühn-Archiv', '10.5073/jka.2016.452.047', 'https://doi.org/10.5073/jka.2016.452.047', 'http://pub.jki.bund.de/index.php/JKA/article/view/6189/5871', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'MilestoneTM herbicide contains the active substance propyzamide (500 g/L) and aminopyralid (5.3 g a.e./L) and is formulated as a suspension concentrate (SC). Registration for Milestone for the use in winter oilseed rape was granted in Germany in July 2014. The active substance propyzamide is well known from the product KerbTM FLO (containing 500 g/L propyzamide, suspension concentrate, SC) which is widely used in winter oilseed rape (WITTROCK et al., 2008). Aminopyralid is formulated in the commercial product Runway (clopyralid + picloram + aminopyralid). Milestone is applied with a use rate of 1.5 L/ha as a post-emergence herbicide from growth stage BBCH 14 of the crop at the beginning of November until February. Kerb FLO is applied with a use rate of 1.875 L/ha at the same timing. The efficacy of Milestone and Kerb FLO was tested in randomised and replicated plot trials in Germany, France and the United Kingdom. Milestone and Kerb FLO showed comparable and very high control levels against monocotyledonous species such as Alopecurus myosuroides, Apera spica-venti, Bromus species and volunteer cereals. Milestone shows a broader spectrum of activity vs. Kerb FLO against dicotyledonous weeds such as Matricaria chamomilla, Papaver rhoeas and Centaurea cyanus. The use of Milestone in dense crops (as the situation was in autumn 2014 for many areas in Germany) shows very high efficacy levels as well. The comparison of various application timings between end of October until beginning of December confirms the application date early November for best results. Milestone controls herbicide-resistant weed populations and can be considered an important part of a resistance management program not only in winter oilseed rape but as a component of an integrated weed management strategy in cropping systems.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('59a04f3c-5267-488e-88bc-cbe5709f2a1d', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Peer review of the pesticide risk assessment of the active substance clopyralid', 'Arena M, Auteri D, Barmaz S, Brancato A, Brocca D, Bura L, Carrasco Cabrera L, Chiusolo A', 2018, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2018.5389', 'https://doi.org/10.2903/j.efsa.2018.5389', 'https://europepmc.org/articles/PMC7009737?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by-nd', 'The conclusions of EFSA following the peer review of the initial risk assessments carried out by the competent authorities of the rapporteur Member State, Finland, and co-rapporteur Member State, Poland, for the pesticide active substance clopyralid are reported. The context of the peer review was that required by Commission Implementing Regulation (EU) No 844/2012. The conclusions were reached on the basis of the evaluation of the representative uses of clopyralid as a herbicide on winter cereals and grassland. The reliable end points, appropriate for use in regulatory risk assessment, are presented. Missing information identified as being required by the regulatory framework is listed. Concerns are identified.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37850e31-0164-485d-b23c-e0fae39fd10d', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Poisonous Plants of the Genus Pimelea: A Menace for the Australian Livestock Industry', 'Saleem R, Bajwa AA, Campbell S, Fletcher MT, Kalaipandian S, Adkins SW', 2023, 'Toxins', '10.3390/toxins15060374', 'https://doi.org/10.3390/toxins15060374', 'https://europepmc.org/articles/PMC10303361?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Pimelea is a genus of about 140 plant species, some of which are well-known for causing animal poisoning resulting in significant economic losses to the Australian livestock industry. The main poisonous species/subspecies include Pimelea simplex (subsp. simplex and subsp. continua), P. trichostachya and P. elongata (generally referred to as Pimelea). These plants contain a diterpenoid orthoester toxin, called simplexin. Pimelea poisoning is known to cause the death of cattle (Bos taurus and B. indicus) or weaken surviving animals. Pimelea species are well-adapted native plants, and their diaspores (single seeded fruits) possess variable degrees of dormancy. Hence, the diaspores do not generally germinate in the same recruitment event, which makes management difficult, necessitating the development of integrated management strategies based on infestation circumstances (e.g., size and density). For example, the integration of herbicides with physical control techniques, competitive pasture establishment and tactical grazing could be effective in some situations. However, such options have not been widely adopted at the field level to mitigate ongoing management challenges. This systematic review provides a valuable synthesis of the current knowledge on the biology, ecology, and management of poisonous Pimelea species with a focus on the Australian livestock industry while identifying potential avenues for future research.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c9302e24-a6ff-462e-ac0e-675b6af353be', '3b187d3e-3864-419a-92a7-971d1a27f044', 'The effect of herbicides on morphological features of pollen grains in Prunus serotina Ehrh. in the context of elimination of this invasive species from European forests', 'Wrońska-Pilarek D, Maciejewska-Rutkowska I, Lechowicz K, Bocianowski J, Hauke-Kowalska M, Baranowska M, Korzeniewicz R', 2023, 'Scientific reports', '10.1038/s41598-023-31010-2', 'https://doi.org/10.1038/s41598-023-31010-2', 'https://europepmc.org/articles/PMC10033914?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Prunus serotina Ehrh. is an alien invasive neophyte widespread in European forests. So far, no effective methods of its elimination have been developed. For this reason, the aim of our study was to determine how herbicides affect the morphological characteristics of pollen grains. This knowledge may be crucial to control this invasive species. The current study was carried out in a research area of 2.7 ha located in the Zielonka Forest near Poznań, Poland (N 52°31''58.016″, E 17°05''55.588″). We tested morphological differences among ten features of P. serotina pollen, based on the samples collected from 15 control trees compared to the 50 trees treated with five different herbicides. In total 1950 pollen grains were measured. We confirmed the adopted hypotheses of long-term herbicide influence on P. serotina pollen. Pollen grains from the control trees had a longer equatorial axis, were more elongated in shape and had the largest range of exine thickness compared to the pollen from the herbicide-treated samples. Exine thickness in the control sample was on average 0.74 µm, ranging from 0.42 to 1.19 µm. The average values and the ranges of this trait in the samples treated with herbicides were larger (e.g. average exine thickness was from 0.90 to 0.95 µm). There were differences in the P/E ranges of variability between the control and herbicide-treated samples. In the control sample the P/E ratio was 1.32-2.04 and elongated forms of pollen shapes prevailed, while in the herbicide-treated samples it ranged from 1.03 to 1.47. The share of deformed pollen grains in the herbicide-treated samples was lower than expected, ranging from 8.7 to 25.3%, while in the control samples it was 6%. Logo and Mustang turned out to be the most effective among the herbicides used in the described research. The two used application methods were found to have an effect on pollen quality.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce234ab6-e86b-4298-8b51-5f52b9b736ef', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Using Post-Emergence Herbicides in Combination with the Sowing Date to Suppress Sinapis arvensis and Silybum marianum in Durum Wheat', 'Anestis Karkanis, Athanasios Angou, Despoina Athanasiadou, Kyriakos D. Giannoulis, Rodanthi Askianaki, Niki Kousi, Avgerinos Sarridis, Spyridon Souipas', 2022, 'Agronomy', '10.3390/agronomy12102583', 'https://doi.org/10.3390/agronomy12102583', 'https://www.mdpi.com/2073-4395/12/10/2583', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Wild mustard (Sinapis arvensis L.) and milk thistle (Silybum marianum (L.) Gaertn.) are two competitive broad-leaved weeds commonly found in cereals in Europe, while several weed species have developed resistance to the main herbicides that are applied on these crops. Thus, the implementation of integrated weed management (IWM) programs is of great importance. Field experiments were conducted based on a split-plot design with two factors (sowing date and herbicides). Our results showed that the density of wild mustard and milk thistle was higher in the early sowing compared to the late sowing, while the total weed density was up to 75% higher in early sowing. Moreover, the herbicides florasulam + 2.4-D and bromoxynil + 2.4-D exhibited high efficacy (>98%) against milk thistle and wild mustard, while tribenuron-methyl and florasulam + clopyralid provided greater efficacy in the late sowing compared to the early sowing. Among the four herbicides, the lowest dry biomass and grain yield of wheat were observed in tribenuron-methyl and florasulam + clopyralid, while in the weed-infested treatment, the highest values of both parameters were recorded in late sowing. Finally, the results showed that the sowing date is a cultural weed control method that should be implemented in IWM programs, since it can affect both weed density and herbicide efficacy.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37e347ef-9686-499c-a3f9-cf50d7558e9d', '3b187d3e-3864-419a-92a7-971d1a27f044', 'Weed resistance to synthetic auxin herbicides', 'Busi R, Goggin DE, Heap IM, Horak MJ, Jugulam M, Masters RA, Napier RM, Riar DS', 2018, 'Pest management science', '10.1002/ps.4823', 'https://doi.org/10.1002/ps.4823', 'https://europepmc.org/articles/PMC6175398?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Herbicides classified as synthetic auxins have been most commonly used to control broadleaf weeds in a variety of crops and in non-cropland areas since the first synthetic auxin herbicide (SAH), 2,4-D, was introduced to the market in the mid-1940s. The incidence of weed species resistant to SAHs is relatively low considering their long-term global application with 30 broadleaf, 5 grass, and 1 grass-like weed species confirmed resistant to date. An understanding of the context and mechanisms of SAH resistance evolution can inform management practices to sustain the longevity and utility of this important class of herbicides. A symposium was convened during the 2nd Global Herbicide Resistance Challenge (May 2017; Denver, CO, USA) to provide an overview of the current state of knowledge of SAH resistance mechanisms including case studies of weed species resistant to SAHs and perspectives on mitigating resistance development in SAH-tolerant crops. © 2017 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8eb2da87-df7a-43af-9175-961d5a5a5584', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'A field-based study of phyllosphere mycobiomes in apple orchards under varying agricultural management strategies', 'Boutin S, Rondeau-Leclaire J, Roy A, Laforest-Lapointe I', 2026, 'ISME communications', '10.1093/ismeco/ycag203', 'https://doi.org/10.1093/ismeco/ycag203', 'https://europepmc.org/articles/PMC13494798?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by', 'Microbial communities in the phyllosphere are key players in plant health and disease resistance, yet their response to agricultural management strategies remains poorly understood under field conditions. Here, we compare fungal community composition and diversity across conventional and organic apple orchards using ITS amplicon sequencing. Leaf samples were collected from six sites at three distinct time points during the 2023 growing season (in May, July, and August) corresponding approximately to monthly intervals throughout the summer. Flower samples were collected from the same trees in May. Our analyses reveal that agricultural management strategies are significantly associated with fungal community structure, with effects intensifying from May to July. Both types of management strategies showed enrichment for different genera known to include common apple tree pathogens: Alternaria and Podosphaera were associated with conventional sites, while Didymella and Ramularia were associated with organic sites. Although fungal alpha diversity was higher in May at conventional orchards compared to organic orchards, it declined over time at conventional sites while it remained stable at organic sites. Together, these patterns indicate that distinct management interventions impose contrasting selective pressures on the apple tree phyllosphere mycobiome, thus shaping both broad fungal community composition and the dominance dynamics of key fungal taxa. Our findings underscore the ecological relevance and inherent challenges of field-based microbiome research, and provide insights to inform the development of sustainable orchard management strategies grounded in fungal community dynamics.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cbecd32f-4380-4cd8-ba5d-5eecfd376a34', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'The Good, the Bad, and the Fungus: Insights into the Relationship Between Plants, Fungi, and Oomycetes in Hydroponics', 'Laevens GCS, Dolson WC, Drapeau MM, Telhig S, Ruffell SE, Rose DM, Glick BR, Stegelmeier AA', 2024, 'Biology', '10.3390/biology13121014', 'https://doi.org/10.3390/biology13121014', 'https://europepmc.org/articles/PMC11673877?pdf=render', NULL, NULL, 37, NULL, 'canada', 3, 'cc by', 'Hydroponic systems are examples of controlled environment agriculture (CEA) and present a promising alternative to traditional farming methods by increasing productivity, profitability, and sustainability. In hydroponic systems, crops are grown in the absence of soil and thus lack the native soil microbial community. This review focuses on fungi and oomycetes, both beneficial and pathogenic, that can colonize crops and persist in hydroponic systems. The symptomatology and mechanisms of pathogenesis for Botrytis, Colletotrichum, Fulvia, Fusarium, Phytophthora, Pythium, and Sclerotinia are explored for phytopathogenic fungi that target floral organs, leaves, roots, and vasculature of economically important hydroponic crops. Additionally, this review thoroughly explores the use of plant growth-promoting fungi (PGPF) to combat phytopathogens and increase hydroponic crop productivity; details of PGP strategies and mechanisms are discussed. The benefits of Aspergillus, Penicillium, Taloromyces, and Trichoderma to hydroponics systems are explored in detail. The culmination of these areas of research serves to improve the current understanding of the role of beneficial and pathogenic fungi, specifically in the hydroponic microbiome.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e3634d4-0274-47a3-be10-46dea8da3c86', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Additively manufactured 17–4 PH stainless steels for fracture management devices', 'Aruntapan Dash, Susmita Bose, Amit Bandyopadhyay', 2024, 'Virtual and Physical Prototyping', '10.1080/17452759.2024.2397698', 'https://doi.org/10.1080/17452759.2024.2397698', 'https://www.tandfonline.com/doi/10.1080/17452759.2024.2397698', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Stainless steel 316L (SS316L) is widely used in fracture management devices. However, SS316L does not offer any bacterial infection resistance and can cause metal-ion sensitivity due to Ni-ions’ presence. 17-4PH can emerge as a promising substitute due to the intrinsic antibacterial properties of copper, a 75% reduction in nickel content, and superior mechanical properties. SS316L and 17–4 PH were manufactured using laser-directed energy deposition (LDED). 17-4PH specimens surpassed the compressive strength of SS316L by over 150%. A static magnetic field was generated in 17–4 PH specimens to understand in vitro bone cell–material interactions. In vitro human fetal osteoblast cell culture and bacterial inhibition study using Staphylococcus aureus and Pseudomonas aeruginosa were carried out on these specimens with SS316L as control and as-processed and magnetised 17–4 PH as treatments. Results demonstrated that magnetised 17–4 PH exhibited 25% enhancement in hFOB proliferation and 70% reduction in bacterial colonisation compared to SS316L.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b263f52d-5f20-4a47-92a5-0d1a96a330a0', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Bacterial cell-free supernatants as metabolite-based biostimulants for alleviating salinity stress in plants', 'Alrasheed R, Naamala J, Subramanian S, Smith DL', 2026, 'Frontiers in plant science', '10.3389/fpls.2026.1824871', 'https://doi.org/10.3389/fpls.2026.1824871', 'https://europepmc.org/articles/PMC13261401?pdf=render', NULL, NULL, NULL, NULL, 'canada', 3, 'cc by', 'Soil salinity severely limits global crop productivity, affecting approximately 20% of irrigated land under changing climate conditions. It impairs water uptake, disrupts nutrient balance, and induces oxidative stress, leading to significant yield losses, particularly in salt-sensitive crops. This review evaluates the potential of metabolite-rich bacterial cell-free supernatants (CFS) derived from plant growth-promoting bacteria (PGPB) as biostimulants for mitigating salinity stress in crops including soybean, canola, and wheat. CFS contain diverse bioactive compounds, including phytohormones, osmolytes, antioxidants, microbe-to-plant signal compounds and nutrient-solubilizing agents, which enhance plant performance through mechanisms such as modulation of hormonal signaling, activation of antioxidant defenses, and regulation of ion homeostasis. Compared to living-cell microbial inoculants, CFS offer advantages in stability and regulatory acceptance. However, their practical application is constrained by variability in composition, lack of standardized protocols, and limited field validation. Addressing these challenges through targeted research and field studies will be critical to enable the adoption of CFS-based strategies for climate-resilient agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('07b861fc-fc2e-47f9-aa3b-108dab3bdd0d', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Biofortification-A Frontier Novel Approach to Enrich Micronutrients in Field Crops to Encounter the Nutritional Security', 'Dhaliwal SS, Sharma V, Shukla AK, Verma V, Kaur M, Shivay YS, Nisar S, Gaber A', 2022, 'Molecules (Basel, Switzerland)', '10.3390/molecules27041340', 'https://doi.org/10.3390/molecules27041340', 'https://europepmc.org/articles/PMC8877941?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by', 'Globally, many developing countries are facing silent epidemics of nutritional deficiencies in human beings and animals. The lack of diversity in diet, i.e., cereal-based crops deficient in mineral nutrients is an additional threat to nutritional quality. The present review accounts for the significance of biofortification as a process to enhance the productivity of crops and also an agricultural solution to address the issues of nutritional security. In this endeavor, different innovative and specific biofortification approaches have been discussed for nutrient enrichment of field crops including cereals, pulses, oilseeds and fodder crops. The agronomic approach increases the micronutrient density in crops with soil and foliar application of fertilizers including amendments. The biofortification through conventional breeding approach includes the selection of efficient genotypes, practicing crossing of plants with desirable nutritional traits without sacrificing agricultural and economic productivity. However, the transgenic/biotechnological approach involves the synthesis of transgenes for micronutrient re-translocation between tissues to enhance their bioavailability. Soil microorganisms enhance nutrient content in the rhizosphere through diverse mechanisms such as synthesis, mobilization, transformations and siderophore production which accumulate more minerals in plants. Different sources of micronutrients viz. mineral solutions, chelates and nanoparticles play a pivotal role in the process of biofortification as it regulates the absorption rates and mechanisms in plants. Apart from the quality parameters, biofortification also improved the crop yield to alleviate hidden hunger thus proving to be a sustainable and cost-effective approach. Thus, this review article conveys a message for researchers about the adequate potential of biofortification to increase crop productivity and nourish the crop with additional nutrient content to provide food security and nutritional quality to humans and livestock.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3be26c73-e199-4150-8f47-42c9b9ed7fe4', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Cannabis: a multifaceted plant with endless potentials', 'Fordjour E, Manful CF, Sey AA, Javed R, Pham TH, Thomas R, Cheema M', 2023, 'Frontiers in pharmacology', '10.3389/fphar.2023.1200269', 'https://doi.org/10.3389/fphar.2023.1200269', 'https://europepmc.org/articles/PMC10308385?pdf=render', NULL, NULL, 36, NULL, 'canada', 3, 'cc by', 'Cannabis sativa, also known as "hemp" or "weed," is a versatile plant with various uses in medicine, agriculture, food, and cosmetics. This review attempts to evaluate the available literature on the ecology, chemical composition, phytochemistry, pharmacology, traditional uses, industrial uses, and toxicology of Cannabis sativa. So far, 566 chemical compounds have been isolated from Cannabis, including 125 cannabinoids and 198 non-cannabinoids. The psychoactive and physiologically active part of the plant is a cannabinoid, mostly found in the flowers, but also present in smaller amounts in the leaves, stems, and seeds. Of all phytochemicals, terpenes form the largest composition in the plant. Pharmacological evidence reveals that the plants contain cannabinoids which exhibit potential as antioxidants, antibacterial agents, anticancer agents, and anti-inflammatory agents. Furthermore, the compounds in the plants have reported applications in the food and cosmetic industries. Significantly, Cannabis cultivation has a minimal negative impact on the environment in terms of cultivation. Most of the studies focused on the chemical make-up, phytochemistry, and pharmacological effects, but not much is known about the toxic effects. Overall, the Cannabis plant has enormous potential for biological and industrial uses, as well as traditional and other medicinal uses. However, further research is necessary to fully understand and explore the uses and beneficial properties of Cannabis sativa.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5e52e813-6d64-47d2-b94f-f3e4d073041f', '91954de4-db35-404f-a84b-6b58af71c69c', 'Quality and Shelf-life of Sweet Potato as Influenced by Storage and Postharvest Treatments', 'Issah Sugri, Bonaventure Kissinger Maalekuu, Francis Kusi, Eli Afetsi Gaveh', 2017, 'Trends in Horticultural Research', '10.3923/thr.2017.1.10', 'https://doi.org/10.3923/thr.2017.1.10', 'https://scialert.net/qredirect.php?doi=thr.2017.1.10&linkid=pdf', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3614222f-f2df-494d-9613-ef114fd91944', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Characterization of a Trichoderma asperellum Strain’s Ecophysiological Traits and Compatibility with Fungicides and Insecticides for Integrated Crop Protection', 'David Montes-Moreno, Verónica Alacid, Antonio V. Sanz-Ros, Pedro Palazón, Inmaculada Garrido-Jurado', 2026, 'Microbiology Research', '10.3390/microbiolres17080141', 'https://doi.org/10.3390/microbiolres17080141', 'https://www.mdpi.com/2036-7481/17/8/141', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The growing demand for sustainable crop protection has intensified interest in biological control agents. This study characterized a Trichoderma asperellum strain (IDE-10) to assess its suitability for integrated pest and disease management. Key ecophysiological traits, including temperature, pH, and ultraviolet (UV) tolerance, were evaluated, along with compatibility with commonly used fungicides and insecticides. The strain exhibited optimal growth at 28.28 °C and sustained high growth rates up to 35 °C, with a maximum threshold of 39.21 °C, indicating strong adaptation to warm climates. Sporulation was enhanced between 25 and 35 °C, with no growth at 5 °C, and soil viability remained stable from 7 to 21 °C. The IDE-10 strain demonstrated broad pH tolerance (3–7) and high resistance to UV-A and UV-B radiation, distinguishing it from commercial strains. Insecticides had no significant adverse effects, while fungicide compatibility varied, with IDE-10 being compatible with metalaxyl- and copper-based formulations. These findings highlight the robustness and adaptability of T. asperellum IDE-10, supporting its potential as a biocontrol agent for sustainable crop protection strategies, particularly in Mediterranean agricultural systems.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fb5fd854-d8f5-455f-bfd7-85964fdbec61', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Chitosan Upregulates the Genes of the ROS Pathway and Enhances the Antioxidant Potential of Grape (Vitis vinifera L. ''Touriga Franca'' and ''Tinto Cão'') Tissues', 'Singh RK, Soares B, Goufo P, Castro I, Cosme F, Pinto-Sintra AL, Inês A, Oliveira AA', 2019, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox8110525', 'https://doi.org/10.3390/antiox8110525', 'https://europepmc.org/articles/PMC6912504?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Chitosan is an environmentally-friendly active molecule that has been explored for numerous agricultural uses. Its use in crop protection is well-known, however, other properties, such as bioactivity, deserve attention. Moreover, the modes of actions of chitosan remain to be elucidated. The present study assessed the levels of total phenolic compounds, the antioxidant potential, and the expression of reactive oxygen species (ROS) scavenging genes in the berries (skins and seeds), leaves, cluster stems, and shoots upon chitosan application on two red grapevine varieties (Touriga Franca and Tinto Cão). The application of chitosan on the whole vine before and after veraison led to the increased levels of polyphenols, anthocyanins, and tannins in Tinto Cão berries, and polyphenols and tannins in Touriga Franca berries, respectively. CUPric Reducing Antioxidant Capacity (CUPRAC) and Ferric Reducing Antioxidant Power (FRAP) assays indicated an increase in the antioxidant potential of berries. With the exception of ascorbate peroxidase (APX), all the ROS pathway genes tested, i.e., iron-superoxide dismutase (Fe-SOD), copper-zinc-superoxide dismutase (Cu/Zn-SOD), catalase (CAT), glutathione reductase (GR), glutaredoxin (Grx), respiratory burst oxidase (Rboh), amine oxidase (AO), peroxidase (POD) and polyphenol oxidase (PPO), were found up-regulated in chitosan-treated berries. Results from the analyses of leaves, stems, and shoots revealed that chitosan not only induced the synthesis of phenolic compounds but also acted as a facilitator for the transfer of polyphenols from the leaves to the berries.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf3cd345-48e4-4f6f-ba78-8518c0cf1026', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Copper Radical Oxidases Contribute to Virulence in Sclerotinia sclerotiorum', 'Tan J, Fong JK, Brumer H, Li X', 2026, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens15090885', 'https://doi.org/10.3390/pathogens15090885', 'https://europepmc.org/articles/PMC13610856?pdf=render', NULL, NULL, 17, NULL, 'canada', 3, 'cc by', 'Sclerotinia sclerotiorum is a broad-spectrum soilborne fungal pathogen, causing substantial yield losses in crops worldwide. Auxiliary Activity Family 5 (AA5) copper radical oxidases (CROs) are members of the carbohydrate active enzymes (CAZymes), valued for their potential as biocatalysts. Although they were reported to contribute to fungal development and disease progression in some phytopathogenic fungi such as Colletotrichum graminicola, the roles of AA5 enzymes in S. sclerotiorum remain largely unexplored. Here, we systematically investigated S. sclerotiorum AA5 genes through reverse genetics and biochemical approaches. Phylogenetic analysis grouped the S. sclerotiorum AA5 proteins into two subfamilies, including three subfamily 1 (AA5_1) members and one subfamily 2 (AA5_2) member. Enzymatic characterization revealed that one AA5_1 enzyme, SsAA5c, exhibited the highest catalytic specificity towards D-glyceraldehyde compared with methylglyoxal and glycerol. In addition, a predicted peroxidase gene (SsPX1) was identified in tandem with the putative AA5_2 gene, SsAA5d. Phenotypic analysis of gene deletion mutants demonstrated that these genes differentially affect fungal development and virulence. While their exact physiological substrates await identification, our findings highlight important roles of AA5 oxidases and the associated peroxidase in the biology of S. sclerotiorum, providing insights that may contribute to future improved disease management strategies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9aba82ff-34ff-4d49-8ad5-85f95e4f1a46', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Emerging Trends in Advanced Translational Applications of Silver Nanoparticles: A Progressing Dawn of Nanotechnology', 'Husain S, Nandi A, Simnani FZ, Saha U, Ghosh A, Sinha A, Sahay A, Samal SK', 2023, 'Journal of functional biomaterials', '10.3390/jfb14010047', 'https://doi.org/10.3390/jfb14010047', 'https://europepmc.org/articles/PMC9863943?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Nanoscience has emerged as a fascinating field of science, with its implementation in multiple applications in the form of nanotechnology. Nanotechnology has recently been more impactful in diverse sectors such as the pharmaceutical industry, agriculture sector, and food market. The peculiar properties which make nanoparticles as an asset are their large surface area and their size, which ranges between 1 and 100 nanometers (nm). Various technologies, such as chemical and biological processes, are being used to synthesize nanoparticles. The green chemistry route has become extremely popular due to its use in the synthesis of nanoparticles. Nanomaterials are versatile and impactful in different day to day applications, resulting in their increased utilization and distribution in human cells, tissues, and organs. Owing to the deployment of nanoparticles at a high demand, the need to produce nanoparticles has raised concerns regarding environmentally friendly processes. These processes are meant to produce nanomaterials with improved physiochemical properties that can have significant uses in the fields of medicine, physics, and biochemistry. Among a plethora of nanomaterials, silver nanoparticles have emerged as the most investigated and used nanoparticle. Silver nanoparticles (AgNPs) have become vital entities of study due to their distinctive properties which the scientific society aims to investigate the uses of. The current review addresses the modern expansion of AgNP synthesis, characterization, and mechanism, as well as global applications of AgNPs and their limitations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df2fd5ef-2e71-41bd-9723-b782ff3de41c', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Exogenous application of salicylic acid to control coffee rust', 'Luciano Abi Rached  Tannuri, Everaldo Antônio Lopes, Willian Rodrigues  Macedo, Ellen Júnia   Canedo', 2021, 'Acta Scientiarum: Biological Sciences', '10.4025/actascibiolsci.v43i1.54495', 'https://doi.org/10.4025/actascibiolsci.v43i1.54495', 'https://periodicos.uem.br/ojs/index.php/ActaSciBiolSci/article/view/54495', NULL, NULL, 7, NULL, 'other', 1, 'open access (DOAJ)', 'The exogenous application of salicylic acid can induce plant resistance against pathogens. However, little is known about the potential uses of this bioregulator for controlling coffee diseases. In this study, we assessed the effect of applying salicylic acid (SA – 150 mg L-1) on the management of coffee rust (Hemileia vastatrix) in a 7-year-old coffee plantation with low crop load (651.6 kg ha-1 in 2017). For comparison, plants were sprayed with protectant fungicide (copper hydroxide – CH) and standard fungicides (SF) used by local farmers (boscalid, pyraclostrobin + epoxiconazole, and copper hydroxide). Non-treated plants were included as a negative control. Five monthly applications were performed from November 2016 to March 2017. Rust incidence and severity, defoliation, and growth of plagiotropic branches were evaluated monthly. The activity of catalase (CAT), ascorbate peroxidase (APX), superoxide dismutase (SOD) and total proteins was assessed one day after the first, third, and fifth product applications. Compared to untreated plants, SA reduced the severity and incidence of rust from 36.3 to 54.7%, while CH and SF reduced disease from 31.8 to 54.6% and from 83.8 to 88%, respectively. SA reduced defoliation by 54.1%. SA increased the concentration of CAT, APX, and SOD after the first application. However, this effect was not observed after subsequent applications. Foliar application of SA reduces the severity and incidence of coffee rust and defoliation in plants with a low crop load.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3597a67-2914-4981-baab-f2c36bacf897', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Fungal Endophytes as Mitigators against Biotic and Abiotic Stresses in Crop Plants', 'Gowtham HG, Hema P, Murali M, Shilpa N, Nataraj K, Basavaraj GL, Singh SB, Aiyaz M', 2024, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof10020116', 'https://doi.org/10.3390/jof10020116', 'https://europepmc.org/articles/PMC10890593?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'The escalating global food demand driven by a gradually expanding human population necessitates strategies to improve agricultural productivity favorably and mitigate crop yield loss caused by various stressors (biotic and abiotic). Biotic stresses are caused by phytopathogens, pests, and nematodes, along with abiotic stresses like salt, heat, drought, and heavy metals, which pose serious risks to food security and agricultural productivity. Presently, the traditional methods relying on synthetic chemicals have led to ecological damage through unintended impacts on non-target organisms and the emergence of microbes that are resistant to them. Therefore, addressing these challenges is essential for economic, environmental, and public health concerns. The present review supports sustainable alternatives, emphasizing the possible application of fungal endophytes as innovative and eco-friendly tools in plant stress management. Fungal endophytes demonstrate capabilities for managing plants against biotic and abiotic stresses via the direct or indirect enhancement of plants'' innate immunity. Moreover, they contribute to elevated photosynthesis rates, stimulate plant growth, facilitate nutrient mineralization, and produce bioactive compounds, hormones, and enzymes, ultimately improving overall productivity and plant stress resistance. In conclusion, harnessing the potentiality of fungal endophytes represents a promising approach toward the sustainability of agricultural practices, offering effective alternative solutions to reduce reliance on chemical treatments and address the challenges posed by biotic and abiotic stresses. This approach ensures long-term food security and promotes environmental health and economic viability in agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d5fec858-9381-4e13-83ae-7676839083c3', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Harnessing the Action Model of the Defense Responses Induced by UPSIDE® Against Plasmopara viticola in Grapevine', 'Giulia Scimone, Lorenzo D’Asaro, Zuzana Gelová, Lorenzo Cotrozzi, Lorenzo Mariotti, Lisa Milanollo, Claudia Pisuttu, Mariagrazia Tonelli', 2026, 'Plants', '10.3390/plants15091297', 'https://doi.org/10.3390/plants15091297', 'https://www.mdpi.com/2223-7747/15/9/1297', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Plasmopara viticola (Pv), the causal agent of downy mildew, is one of the most damaging pathogens affecting grapevine. Current control strategies largely depend on copper-based fungicides and synthetic chemicals, raising increasing concerns related to environmental sustainability and pathogen resistance. This study evaluated the efficacy of a novel Saccharomyces cerevisiae extract (U) as an inducer of resistance in the grapevine–Pv interaction. Microscopic observations revealed the ability of U to inhibit Pv spread over the leaf. Additionally, biochemical and molecular responses were analyzed in grapevine leaves subjected to four treatments: plants treated only with water (U−/Pv−; i.e., control) or U (U+/Pv−), inoculated with Pv (U−/Pv+), or both treated with U and then inoculated with Pv (U+/Pv+). Fully expanded leaves were sampled at 2-, 5-, 24-, and 72-h post inoculation (hpi). In U+/Pv− leaves, jasmonic, salicylic and abscisic acid (JA, SA, and ABA), as well as hydrogen peroxide (H2O2) increased at 2 hpi (+44, +33, +38%, and 3-fold, respectively), accompanied by upregulation of pr1 (2-fold higher than control, respectively), suggesting the capacity of U to trigger the plant alert system. In U−/Pv+ leaves, peaks of JA and H2O2 occurred at 24 hpi (+40% and 4-fold higher than control), followed by marked ethylene emissions and upregulation of pr1 and pr2 (i.e., genes associated with Pv defense; around 2-fold, averagely) at 72 hpi, confirming the progression of infection. In contrast, U+/Pv+ leaves showed stronger peaks of H2O2 at both 2 and 5 hpi (7-fold and +58%, respectively), together with SA accumulation and upregulation of pr1, pr2, eds1, and chit1b at 72 hpi (more than 2-fold), suggesting a priming effect of U. Overall, U effectively enhanced grapevine defense responses and limited Pv development, highlighting its potential as a sustainable disease management strategy.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:47.954526+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e5726a1c-2aea-4872-9cc1-1cf5d7753a33', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Laminarin Induces Defense Responses and Efficiently Controls Olive Leaf Spot Disease in Olive', 'George T. Tziros, Anastasios Samaras, George S. Karaoglanidis', 2021, 'Molecules', '10.3390/molecules26041043', 'https://doi.org/10.3390/molecules26041043', 'https://www.mdpi.com/1420-3049/26/4/1043', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Olive leaf spot (OLS) caused by Fusicladiumoleagineum is mainly controlled using copper fungicides. However, the replacement of copper-based products with eco-friendly alternatives is a priority. The use of plant resistance-inducers (PRIs) or biological control agents (BCAs) could contribute in this direction. In this study we investigated the potential use of three PRIs (laminarin, acibenzolar-S-methyl, harpin) and a BCA (Bacillus amyloliquefaciens FZB24) for the management of OLS. The tested products provided control efficacy higher than 68%. In most cases, dual applications provided higher (p p Pal, Lox, Cuao and Mpol were the genes with the higher inductions in laminarin-treated and artificially inoculated plants. The results of this study are expected to contribute towards a better understanding of PRIs in olive culture and the optimization of OLS control, while they provide evidence for potential contributions in the reduction of copper accumulation in the environment.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f2fd4f99-2aad-44a2-9ebb-8e24c88020e1', '96fe7066-ae23-4d8a-b6d9-37a45e3ca699', 'Production performance and metabolic characteristics of cows fed whole plant faba bean silage in comparison with barley and corn silage', 'Victor Hugo Guevara-Oquendo, David A. Christensen, Basim Refat, María E. Rodríguez‐Espinosa, Xin Lu Feng, Peiqiang Yu', 2021, 'Canadian Journal of Animal Science', '10.1139/cjas-2021-0048', 'https://doi.org/10.1139/cjas-2021-0048', 'https://utoronto.scholaris.ca/bitstreams/13869678-8e3b-41be-ade4-cae16b92164b/download', NULL, NULL, 28, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.86438+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('38fbfaee-73e8-48a0-8c7c-bac9fe01ab8c', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Mechanisms and Impact of Rhizosphere Microbial Metabolites on Crop Health, Traits, Functional Components: A Comprehensive Review', 'Chen Q, Song Y, An Y, Lu Y, Zhong G', 2024, 'Molecules (Basel, Switzerland)', '10.3390/molecules29245922', 'https://doi.org/10.3390/molecules29245922', 'https://europepmc.org/articles/PMC11679325?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'cc by', 'Current agricultural practices face numerous challenges, including declining soil fertility and heavy reliance on chemical inputs. Rhizosphere microbial metabolites have emerged as promising agents for enhancing crop health and yield in a sustainable manner. These metabolites, including phytohormones, antibiotics, and volatile organic compounds, play critical roles in promoting plant growth, boosting resistance to pathogens, and improving resilience to environmental stresses. This review comprehensively outlines the mechanisms through which rhizosphere microbial metabolites influence crop health, traits, functional components, and yield. It also discusses the potential applications of microbial secondary metabolites in biofertilizers and highlights the challenges associated with their production and practical use. Measures to overcome these challenges are proposed, alongside an exploration of the future development of the functional fertilizer industry. The findings presented here provide a scientific basis for utilizing rhizosphere microbial metabolites to enhance agricultural sustainability, offering new strategies for future crop management. Integrating these microbial strategies could lead to increased crop productivity, improved quality, and reduced dependence on synthetic chemical inputs, thereby supporting a more environmentally friendly and resilient agricultural system.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2c73f0a5-3b15-4803-b29e-1ecab5c1f91d', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Molecular Mechanisms of Plant Responses to Copper: From Deficiency to Excess', 'Xu E, Liu Y, Gu D, Zhan X, Li J, Zhou K, Zhang P, Zou Y', 2024, 'International journal of molecular sciences', '10.3390/ijms25136993', 'https://doi.org/10.3390/ijms25136993', 'https://europepmc.org/articles/PMC11240974?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Copper (Cu) is an essential nutrient for plant growth and development. This metal serves as a constituent element or enzyme cofactor that participates in many biochemical pathways and plays a key role in photosynthesis, respiration, ethylene sensing, and antioxidant systems. The physiological significance of Cu uptake and compartmentalization in plants has been underestimated, despite the importance of Cu in cellular metabolic processes. As a micronutrient, Cu has low cellular requirements in plants. However, its bioavailability may be significantly reduced in alkaline or organic matter-rich soils. Cu deficiency is a severe and widespread nutritional disorder that affects plants. In contrast, excessive levels of available Cu in soil can inhibit plant photosynthesis and induce cellular oxidative stress. This can affect plant productivity and potentially pose serious health risks to humans via bioaccumulation in the food chain. Plants have evolved mechanisms to strictly regulate Cu uptake, transport, and cellular homeostasis during long-term environmental adaptation. This review provides a comprehensive overview of the diverse functions of Cu chelators, chaperones, and transporters involved in Cu homeostasis and their regulatory mechanisms in plant responses to varying Cu availability conditions. Finally, we identified that future research needs to enhance our understanding of the mechanisms regulating Cu deficiency or stress in plants. This will pave the way for improving the Cu utilization efficiency and/or Cu tolerance of crops grown in alkaline or Cu-contaminated soils.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d22b5c47-7832-4d06-9733-348ad42063f6', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Multifunctional Nanoparticles for Integrated Management of Plant Fungal Pathogens: From Synthesis to Field Applications', 'Amber Malik, Fiza Liaquat, Muhammad Azam, Abdul Rehman, Liu Qunlu, Iftikhar Hussain Shah, Jun Qin, Yidong Zhang', 2026, 'Forest Science and Technology', '10.1080/21580103.2026.2679130', 'https://doi.org/10.1080/21580103.2026.2679130', 'https://www.tandfonline.com/doi/10.1080/21580103.2026.2679130', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The growing challenge of fungal diseases on world food security requires new technologies to ensure effective and sustainable control. This review discusses the disruptive nature of multifunctional nanoparticles (NPs) in the fight against plant fungal pathogens, their functioning, various uses, and environmental advantages. Nanotechnology opens the possibility of controlled fungal infections at the scale of a nanoparticle, and the technology will be a strong substitute for conventional fungicides, which will target fungal cell walls, membranes, DNA, and processes. Smallness of NPs will enable extensive infiltration into plant tissues, which will increase the effectiveness of fungicides and reduce environmental impact as well as the development of fungal resistance. Metal-based nanoparticles, including silver, copper, zinc, and iron oxide, and biogenic NPs produced by plant and microbial extracts show a wide spectrum of antifungal action, including not only spore germination prevention but also biofilm formation disruption. Also, synergistic relationships between NPs and biocontrol agents, including Trichoderma and Bacillus species, provide a two-fold system of control, a combination of short-term chemical control and long-term biological control, which improves the immunity and resilience of plants. Nonetheless, even with these developments, issues in the commercialization of nanoparticle-based technologies, such as toxicity issues, regulatory frameworks, and issues of perception by the people, still exist. The research of the future should aim at optimizing the production of NPs, providing their safety, and combining nanotechnology and precision farming with genome editing to establish more robust agricultural systems. The inclusion of intelligent nanomaterials in environmentally responsive systems offers a potential avenue to the accurate management of diseases, which in the long run will lead to greater yield and sustainability within global agriculture as a result of climate change and international agricultural demands.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4129ecf-d61a-4a3f-9fac-e7e7d11bfce1', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Nanotechnology in agri-food production: an overview', 'Sekhon BS', 2014, 'Nanotechnology, science and applications', '10.2147/nsa.s39406', 'https://doi.org/10.2147/nsa.s39406', 'https://europepmc.org/articles/PMC4038422?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by-nc', 'Nanotechnology is one of the most important tools in modern agriculture, and agri-food nanotechnology is anticipated to become a driving economic force in the near future. Agri-food themes focus on sustainability and protection of agriculturally produced foods, including crops for human consumption and animal feeding. Nanotechnology provides new agrochemical agents and new delivery mechanisms to improve crop productivity, and it promises to reduce pesticide use. Nanotechnology can boost agricultural production, and its applications include: 1) nanoformulations of agrochemicals for applying pesticides and fertilizers for crop improvement; 2) the application of nanosensors/nanobiosensors in crop protection for the identification of diseases and residues of agrochemicals; 3) nanodevices for the genetic manipulation of plants; 4) plant disease diagnostics; 5) animal health, animal breeding, poultry production; and 6) postharvest management. Precision farming techniques could be used to further improve crop yields but not damage soil and water, reduce nitrogen loss due to leaching and emissions, as well as enhance nutrients long-term incorporation by soil microorganisms. Nanotechnology uses include nanoparticle-mediated gene or DNA transfer in plants for the development of insect-resistant varieties, food processing and storage, nanofeed additives, and increased product shelf life. Nanotechnology promises to accelerate the development of biomass-to-fuels production technologies. Experts feel that the potential benefits of nanotechnology for agriculture, food, fisheries, and aquaculture need to be balanced against concerns for the soil, water, and environment and the occupational health of workers. Raising awareness of nanotechnology in the agri-food sector, including feed and food ingredients, intelligent packaging and quick-detection systems, is one of the keys to influencing consumer acceptance. On the basis of only a handful of toxicological studies, concerns have arisen regarding the safety of nanomaterials, and researchers and companies will need to prove that these nanotechnologies do not have more of a negative impact on the environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0766cbae-f694-4ae3-b3c8-49f0232f76a3', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Nonphytotoxic copper oxide nanoparticles are powerful “nanoweapons” that trigger resistance in tobacco against the soil-borne fungal pathogen Phytophthora nicotianae', 'Juan-ni CHEN, Lin-tong WU, Kun SONG, Yun-song ZHU, Wei DING', 2022, 'Journal of Integrative Agriculture', '10.1016/j.jia.2022.08.086', 'https://doi.org/10.1016/j.jia.2022.08.086', 'http://www.sciencedirect.com/science/article/pii/S2095311922001642', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Investigations into the potential application of nanoparticles acting as nanofungicides in sustainable agriculture are rapidly expanding due to the high antimicrobial properties of these compounds, which do not risk inducing pathogen resistance to fungicides. A detailed understanding of the impact of copper oxide nanoparticles (CuO NPs) on soil-borne phytopathogenic fungi is yet to be obtained. This study aimed to explore the in vitro antifungal activity and control efficacy of CuO NPs applied via irrigation with respect to tobacco black shank (TBS) disease caused by Phytophthoranicotianae. The results revealed that CuO NPs greatly interfered with the reproductive growth process of this fungus, repressing hyphal growth, spore germination and sporangium production. Additionally, morphological damage, intracellular ROS accumulation and increased SOD enzyme activity in hyphae were the antifungicidal mechanisms of these NPs. In pot experiments, treatment with CuO NPs at 100 mg L−1 significantly suppressed TBS development, compared with the effect on control plants, and the control efficacy reached 33.69% without inducing phytotoxicity. Exposure to CuO NPs significantly activated a series of defense enzymes, and resistance genes in tobacco can further explain the mechanisms by which CuO NPs suppressed fungal infection. The Cu content in both the leaves and roots of P. nicotianae-infested plants increased by 50.03 and 27.25%, respectively, after treatment with 100 mg L−1 CuO NPs, compared with that of healthy plants. In particular, a higher Cu content was observed in infected roots than in leaves. Therefore, this study showed the potential of CuO NPs applied as nanofungicides and as nanoinducers of fungus resistance genes for the management of TBS through inhibition of pathogen infection and stimulation of plant defenses.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2f110262-fa9d-4a25-95e6-df4a50bffce6', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Opportunistic Pathogens in Drinking Water Distribution Systems-A Review', 'LeChevallier MW, Prosser T, Stevens M', 2024, 'Microorganisms', '10.3390/microorganisms12050916', 'https://doi.org/10.3390/microorganisms12050916', 'https://europepmc.org/articles/PMC11124194?pdf=render', NULL, NULL, 58, NULL, 'other', 1, 'cc by', 'In contrast to "frank" pathogens, like Salmonella entrocolitica, Shigella dysenteriae, and Vibrio cholerae, that always have a probability of disease, "opportunistic" pathogens are organisms that cause an infectious disease in a host with a weakened immune system and rarely in a healthy host. Historically, drinking water treatment has focused on control of frank pathogens, particularly those from human or animal sources (like Giardia lamblia, Cryptosporidium parvum, or Hepatitis A virus), but in recent years outbreaks from drinking water have increasingly been due to opportunistic pathogens. Characteristics of opportunistic pathogens that make them problematic for water treatment include: (1) they are normally present in aquatic environments, (2) they grow in biofilms that protect the bacteria from disinfectants, and (3) under appropriate conditions in drinking water systems (e.g., warm water, stagnation, low disinfectant levels, etc.), these bacteria can amplify to levels that can pose a public health risk. The three most common opportunistic pathogens in drinking water systems are Legionella pneumophila, Mycobacterium avium, and Pseudomonas aeruginosa. This report focuses on these organisms to provide information on their public health risk, occurrence in drinking water systems, susceptibility to various disinfectants, and other operational practices (like flushing and cleaning of pipes and storage tanks). In addition, information is provided on a group of nine other opportunistic pathogens that are less commonly found in drinking water systems, including Aeromonas hydrophila, Klebsiella pneumoniae, Serratia marcescens, Burkholderia pseudomallei, Acinetobacter baumannii, Stenotrophomonas maltophilia, Arcobacter butzleri, and several free-living amoebae including Naegleria fowleri and species of Acanthamoeba. The public health risk for these microbes in drinking water is still unclear, but in most cases, efforts to manage Legionella, mycobacteria, and Pseudomonas risks will also be effective for these other opportunistic pathogens. The approach to managing opportunistic pathogens in drinking water supplies focuses on controlling the growth of these organisms. Many of these microbes are normal inhabitants in biofilms in water, so the attention is less on eliminating these organisms from entering the system and more on managing their occurrence and concentrations in the pipe network. With anticipated warming trends associated with climate change, the factors that drive the growth of opportunistic pathogens in drinking water systems will likely increase. It is important, therefore, to evaluate treatment barriers and management activities for control of opportunistic pathogen risks. Controls for primary treatment, particularly for turbidity management and disinfection, should be reviewed to ensure adequacy for opportunistic pathogen control. However, the major focus for the utility''s opportunistic pathogen risk reduction plan is the management of biological activity and biofilms in the distribution system. Factors that influence the growth of microbes (primarily in biofilms) in the distribution system include, temperature, disinfectant type and concentration, nutrient levels (measured as AOC or BDOC), stagnation, flushing of pipes and cleaning of storage tank sediments, and corrosion control. Pressure management and distribution system integrity are also important to the microbial quality of water but are related more to the intrusion of contaminants into the distribution system rather than directly related to microbial growth. Summarizing the identified risk from drinking water, the availability and quality of disinfection data for treatment, and guidelines or standards for control showed that adequate information is best available for management of L. pneumophila. For L. pneumophila, the risk for this organism has been clearly established from drinking water, cases have increased worldwide, and it is one of the most identified', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('660ca40f-9417-4f06-80da-d20eaf94b12c', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Drought and Salinity Stress Responses and Microbe-Induced Tolerance in Plants', 'Ma Y, Dias MC, Freitas H', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.591911', 'https://doi.org/10.3389/fpls.2020.591911', 'https://europepmc.org/articles/PMC7691295?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Drought and salinity are among the most important environmental factors that hampered agricultural productivity worldwide. Both stresses can induce several morphological, physiological, biochemical, and metabolic alterations through various mechanisms, eventually influencing plant growth, development, and productivity. The responses of plants to these stress conditions are highly complex and depend on other factors, such as the species and genotype, plant age and size, the rate of progression as well as the intensity and duration of the stresses. These factors have a strong effect on plant response and define whether mitigation processes related to acclimation will occur or not. In this review, we summarize how drought and salinity extensively affect plant growth in agriculture ecosystems. In particular, we focus on the morphological, physiological, biochemical, and metabolic responses of plants to these stresses. Moreover, we discuss mechanisms underlying plant-microbe interactions that confer abiotic stress tolerance.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fdb43d90-ef49-4b54-a7dc-0ff0b9d0bcbf', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Pathogen and Particle Associations in Wastewater: Significance and Implications for Treatment and Disinfection Processes', 'Chahal C, van den Akker B, Young F, Franco C, Blackbeard J, Monis P', 2016, 'Advances in applied microbiology', '10.1016/bs.aambs.2016.08.001', 'https://doi.org/10.1016/bs.aambs.2016.08.001', 'https://europepmc.org/articles/PMC7126130?pdf=render', NULL, NULL, 58, NULL, 'other', 1, 'open access (Europe PMC)', 'Disinfection guidelines exist for pathogen inactivation in potable water and recycled water, but wastewater with high numbers of particles can be more difficult to disinfect, making compliance with the guidelines problematic. Disinfection guidelines specify that drinking water with turbidity ≥1 Nephelometric Turbidity Units (NTU) is not suitable for disinfection and therefore not fit for purpose. Treated wastewater typically has higher concentrations of particles (1-10NTU for secondary treated effluent). Two processes widely used for disinfecting wastewater are chlorination and ultraviolet radiation. In both cases, particles in wastewater can interfere with disinfection and can significantly increase treatment costs by increasing operational expenditure (chemical demand, power consumption) or infrastructure costs by requiring additional treatment processes to achieve the required levels of pathogen inactivation. Many microorganisms (viruses, bacteria, protozoans) associate with particles, which can allow them to survive disinfection processes and cause a health hazard. Improved understanding of this association will enable development of cost-effective treatment, which will become increasingly important as indirect and direct potable reuse of wastewater becomes more widespread in both developed and developing countries. This review provides an overview of wastewater and associated treatment processes, the pathogens in wastewater, the nature of particles in wastewater and how they interact with pathogens, and how particles can impact disinfection processes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37bd3473-12f5-46e3-bb8f-db8fb942dc65', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Potential of Yeasts as Biocontrol Agents of the Phytopathogen Causing Cacao Witches’ Broom Disease: Is Microbial Warfare a Solution?', 'Pedro Ferraz, Pedro Ferraz, Fernanda Cássio, Fernanda Cássio, Cândida Lucas, Cândida Lucas', 2019, 'Frontiers in Microbiology', '10.3389/fmicb.2019.01766', 'https://doi.org/10.3389/fmicb.2019.01766', 'https://www.frontiersin.org/article/10.3389/fmicb.2019.01766/full', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Plant diseases caused by fungal pathogens are responsible for major crop losses worldwide, with a significant socio-economic impact on the life of millions of people who depend on agriculture-exclusive economy. This is the case of the Witches’ Broom Disease (WBD) affecting cacao plant and fruit in South and Central America. The severity and extent of this disease is prospected to impact the growing global chocolate market in a few decades. WBD is caused by the basidiomycete fungus Moniliophthora perniciosa. The methods used to contain the fungus mainly rely on chemical fungicides, such as copper-based compounds or azoles. Not only are these highly ineffective, but also their utilization is increasingly restricted by the cacao industry, in part because it promotes fungal resistance, in part related to consumers’ health concerns and environmental awareness. Therefore, the disease is being currently tentatively controlled through phytosanitary pruning, although the full removal of infected plant material is impossible and the fungus maintains persistent inoculum in the soil, or using an endophytic fungal parasite of Moniliophthora perniciosa which production is not sustainable. The growth of Moniliophthora perniciosa was reported as being antagonized in vitro by some yeasts, which suggests that they could be used as biological control agents, suppressing the fungus multiplication and containing its spread. Concurrently, some yeast-based products are used in the protection of fruits from postharvest fungal spoilage, and the extension of diverse food products shelf-life. These successful applications suggest that yeasts can be regarded a serious alternative also in the pre-harvest management of WBD and other fungal plant diseases. Yeasts’ GRAS (Generally Recognized as Safe) nature adds to their appropriateness for field application, not raising major ecological concerns as do the present more aggressive approaches. Importantly, mitigating WBD, in a sustainable manner, would predictably have a high socioeconomic impact, contributing to diminish poverty in the cacao-producing rural communities severely affected by the disease. This review discusses the importance/advantages and the challenges that such a strategy would have for WBD containment, and presents the available information on the molecular and cellular mechanisms underlying fungi antagonism by yeasts.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e1b692c4-12fb-495c-9a99-77ac8a732adb', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Research Progress on Heavy Metals Pollution in the Soil of Smelting Sites in China', 'Adnan M, Xiao B, Xiao P, Zhao P, Li R, Bibi S', 2022, 'Toxics', '10.3390/toxics10050231', 'https://doi.org/10.3390/toxics10050231', 'https://europepmc.org/articles/PMC9147308?pdf=render', NULL, NULL, 30, NULL, 'other', 1, 'cc by', 'Contamination by heavy metals is a significant issue worldwide. In recent decades, soil heavy metals pollutants in China had adverse impacts on soil quality and threatened food security and human health. Anthropogenic inputs mainly generate heavy metal contamination in China. In this review, the approaches were used in these investigations, focusing on geochemical strategies and metal isotope methods, particularly useful for determining the pathway of mining and smelting derived pollution in the soil. Our findings indicate that heavy metal distribution substantially impacts topsoils around mining and smelting sites, which release massive amounts of heavy metals into the environment. Furthermore, heavy metal contamination and related hazards posed by Pb, Cd, As, and Hg are more severe to plants, soil organisms, and humans. It''s worth observing that kids are particularly vulnerable to Pb toxicity. And this review also provides novel approaches to control and reduce the impacts of heavy metal pollution. Hydrometallurgy offers a potential method for extracting metals and removing potentially harmful heavy metals from waste to reduce pollution. However, environmentally friendly remediation of contaminated sites is a significant challenge. This paper also evaluates current technological advancements in the remediation of polluted soil, such as stabilization/solidification, natural attenuation, electrokinetic remediation, soil washing, and phytoremediation. The ability of biological approaches, especially phytoremediation, is cost-effective and favorable to the environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('972d73a9-a388-47f8-9946-7e46a3d27f4f', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Secondary Metabolites from Artemisia Genus as Biopesticides and Innovative Nano-Based Application Strategies', 'Ivănescu B, Burlec AF, Crivoi F, Roșu C, Corciovă A', 2021, 'Molecules (Basel, Switzerland)', '10.3390/molecules26103061', 'https://doi.org/10.3390/molecules26103061', 'https://europepmc.org/articles/PMC8160890?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'The Artemisia genus includes a large number of species with worldwide distribution and diverse chemical composition. The secondary metabolites of Artemisia species have numerous applications in the health, cosmetics, and food sectors. Moreover, many compounds of this genus are known for their antimicrobial, insecticidal, parasiticidal, and phytotoxic properties, which recommend them as possible biological control agents against plant pests. This paper aims to evaluate the latest available information related to the pesticidal properties of Artemisia compounds and extracts and their potential use in crop protection. Another aspect discussed in this review is the use of nanotechnology as a valuable trend for obtaining pesticides. Nanoparticles, nanoemulsions, and nanocapsules represent a more efficient method of biopesticide delivery with increased stability and potency, reduced toxicity, and extended duration of action. Given the negative impact of synthetic pesticides on human health and on the environment, Artemisia-derived biopesticides and their nanoformulations emerge as promising ecofriendly alternatives to pest management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('40a71f79-3f0c-4a7d-9336-d24d49905579', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'The Applications of Nanotechnology in Crop Production', 'Liu C, Zhou H, Zhou J', 2021, 'Molecules (Basel, Switzerland)', '10.3390/molecules26237070', 'https://doi.org/10.3390/molecules26237070', 'https://europepmc.org/articles/PMC8658860?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'With the frequent occurrence of extreme climate, global agriculture is confronted with unprecedented challenges, including increased food demand and a decline in crop production. Nanotechnology is a promising way to boost crop production, enhance crop tolerance and decrease the environmental pollution. In this review, we summarize the recent findings regarding innovative nanotechnology in crop production, which could help us respond to agricultural challenges. Nanotechnology, which involves the use of nanomaterials as carriers, has a number of diverse applications in plant growth and crop production, including in nanofertilizers, nanopesticides, nanosensors and nanobiotechnology. The unique structures of nanomaterials such as high specific surface area, centralized distribution size and excellent biocompatibility facilitate the efficacy and stability of agro-chemicals. Besides, using appropriate nanomaterials in plant growth stages or stress conditions effectively promote plant growth and increase tolerance to stresses. Moreover, emerging nanotools and nanobiotechnology provide a new platform to monitor and modify crops at the molecular level.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29851c7f-1fa6-4032-b06a-350a288dea0e', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Optimal efficacy of the essential nozzle characteristics and insecticide type for controlling cabbage aphid', 'Majid Hazim Alheidary, Dawood S. Hamed, Faisal N. Jaber', 2021, 'Journal of Crop Protection', NULL, 'http://jcp.modares.ac.ir/article-3-48645-en.html', 'http://jcp.modares.ac.ir/article-3-48645-en.html', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'The previous works have addressed selecting the nozzle to minimize the hazard of pesticide drift by producing large spray droplet sizes. However, this spray application with the largest sizes does not effectively impact insects either, as it needs many pesticides. Several studies have demonstrated that the small spray droplet sizes can affect the insects and be obtained by selecting the appropriate nozzle size and height. This study sheds light on the nozzle sizes and heights, and insecticide types for controlling the cabbage aphid to ensure efficient insect control. Different parameters including three sizes of flat fan nozzle 01, 02, and 03, two nozzle heights 35 and 70 cm above the plant top, and two insecticide types 20% wide plus WP and 90% methomyl SP were investigated to measure spray deposition, coverage percentage, and droplets density in different locations of the cabbage plant for improving control efficacy. The outcomes showed significant differences in the spray deposition and coverage percentage using different nozzle sizes, nozzle heights, and insecticide types. The best spray deposition, coverage percentage, and control efficacy (0.321 µm.cm-2, 15.05%, and 84.83%, respectively) were achieved using the 02 nozzle size, nozzle height of 35 cm methomyl SP insecticide type on the fourteenth day after spraying application in comparison to the others. The fourteenth day was the most effective to control aphids compared to the first and the seventh days.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ae7f6e0-bd19-4e2f-b68a-2ae3b275e506', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'The Roles of Plant-Growth-Promoting Rhizobacteria (PGPR)-Based Biostimulants for Agricultural Production Systems', 'Sun W, Shahrajabian MH, Soleymani A', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13050613', 'https://doi.org/10.3390/plants13050613', 'https://europepmc.org/articles/PMC10934396?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by', 'The application of biostimulants has been proven to be an advantageous tool and an appropriate form of management towards the effective use of natural resources, food security, and the beneficial effects on plant growth and yield. Plant-growth-promoting rhizobacteria (PGPR) are microbes connected with plant roots that can increase plant growth by different methods such as producing plant hormones and molecules to improve plant growth or providing increased mineral nutrition. They can colonize all ecological niches of roots to all stages of crop development, and they can affect plant growth and development directly by modulating plant hormone levels and enhancing nutrient acquisition such as of potassium, phosphorus, nitrogen, and essential minerals, or indirectly via reducing the inhibitory impacts of different pathogens in the forms of biocontrol parameters. Many plant-associated species such as Pseudomonas, Acinetobacter, Streptomyces, Serratia, Arthrobacter, and Rhodococcus can increase plant growth by improving plant disease resistance, synthesizing growth-stimulating plant hormones, and suppressing pathogenic microorganisms. The application of biostimulants is both an environmentally friendly practice and a promising method that can enhance the sustainability of horticultural and agricultural production systems as well as promote the quantity and quality of foods. They can also reduce the global dependence on hazardous agricultural chemicals. Science Direct, Google Scholar, Springer Link, CAB Direct, Scopus, Springer Link, Taylor and Francis, Web of Science, and Wiley Online Library were checked, and the search was conducted on all manuscript sections in accordance with the terms Acinetobacter, Arthrobacter, Enterobacter, Ochrobactrum, Pseudomonas, Rhodococcus, Serratia, Streptomyces, Biostimulants, Plant growth promoting rhizobactera, and Stenotrophomonas. The aim of this manuscript is to survey the effects of plant-growth-promoting rhizobacteria by presenting case studies and successful paradigms in various agricultural and horticultural crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('135406d9-d650-431b-94ea-ceee2f92a42f', '1eb0752d-2ef8-4b09-9f5f-0de7ed852c6d', 'Therapies with Antioxidant Potential in Psoriasis, Vitiligo, and Lichen Planus', 'Guarneri F, Bertino L, Pioggia G, Casciaro M, Gangemi S', 2021, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox10071087', 'https://doi.org/10.3390/antiox10071087', 'https://europepmc.org/articles/PMC8301010?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Oxidative stress plays an important pathogenetic role in many chronic inflammatory diseases, including those of dermatological interest. In particular, regarding psoriasis, vitiligo, and lichen planus, excess reactive oxygen species and a decline in endogenous antioxidant systems are observed. In this regard, treatments with antioxidant properties could be appropriate therapeutic options. To date, clinical trials in dermatology on these treatments are limited. We reviewed the available studies on the efficacy of antioxidant therapies in psoriasis, vitiligo, and lichen planus. The role of herbal derivatives, vitamins, and trace elements was analyzed. The antioxidant properties of conventional therapies were also evaluated. Data from the literature suggest that antioxidants might be useful, but available studies on this topic are limited, heterogeneous, not completely standardized, and on small populations. Furthermore, in most cases, antioxidants alone are unable to induce significant clinical changes, except perhaps in mild forms, and must be used in conjunction with standard drug treatments to achieve measurable results. Further studies need to be conducted, considering larger populations and using internationally validated scales, in order to compare the results and clinical efficacy.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8cb56060-692d-48c7-99b1-eabc3c97d9e1', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Accumulation of Proline in Plants under Contaminated Soils-Are We on the Same Page?', 'Spormann S, Nadais P, Sousa F, Pinto M, Martins M, Sousa B, Fidalgo F, Soares C', 2023, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox12030666', 'https://doi.org/10.3390/antiox12030666', 'https://europepmc.org/articles/PMC10045403?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Agricultural soil degradation is occurring at unprecedented rates, not only as an indirect effect of climate change (CC) but also due to intensified agricultural practices which affect soil properties and biodiversity. Therefore, understanding the impacts of CC and soil degradation on plant physiology is crucial for the sustainable development of mitigation strategies to prevent crop productivity losses. The amino acid proline has long been recognized for playing distinct roles in plant cells undergoing osmotic stress. Due to its osmoprotectant and redox-buffering ability, a positive correlation between proline accumulation and plants'' tolerance to abiotic stress has been pointed out in numerous reviews. Indeed, proline quantification is used systematically by plant physiologists as an indicator of the degree of tolerance and a measurement of the antioxidant potential in plants under stressful conditions. Moreover, the exogenous application of proline has been shown to increase resilience to several stress factors, including those related to soil degradation such as salinity and exposure to metals and xenobiotics. However, recent data from several studies often refer to proline accumulation as a signal of stress sensitivity with no clear correlation with improved antioxidant activity or higher stress tolerance, including when proline is used exogenously as a stress reliever. Nevertheless, endogenous proline levels are strongly modified by these stresses, proving its involvement in plant responses. Hence, one main question arises-is proline augmentation always a sign of improved stress resilience? From this perspective, the present review aims to provide a more comprehensive understanding of the implications of proline accumulation in plants under abiotic stress induced by soil degradation factors, reinforcing the idea that proline quantification should not be employed as a sole indicator of stress sensitivity or resilience but rather complemented with further biochemical and physiological endpoints.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('01b97757-706f-46cc-b9ff-3d103f94d8d8', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Advances in Biopolymeric Nanopesticides: A New Eco-Friendly/Eco-Protective Perspective in Precision Agriculture', 'Kumar R, Kumar N, Rajput VD, Mandzhieva S, Minkina T, Saharan BS, Kumar D, Sadh PK', 2022, 'Nanomaterials (Basel, Switzerland)', '10.3390/nano12223964', 'https://doi.org/10.3390/nano12223964', 'https://europepmc.org/articles/PMC9692690?pdf=render', NULL, NULL, 30, NULL, 'other', 1, 'cc by', 'Pesticides are essential to contemporary agriculture and are required to safeguard plants from hazardous pests, diseases, and weeds. In addition to harming the environment, overusing these pesticides causes pests to become resistant over time. Alternative methods and agrochemicals are therefore required to combat resistance. A potential solution to pesticide resistance and other issues may be found in nanotechnology. Due to their small size, high surface-area-to-volume ratio, and ability to offer novel crop protection techniques, nanoformulations, primarily biopolymer-based ones, can address specific agricultural concerns. Several biopolymers can be employed to load pesticides, including starch, cellulose, chitosan, pectin, agar, and alginate. Other biopolymeric nanomaterials can load pesticides for targeted delivery, including gums, carrageenan, galactomannans, and tamarind seed polysaccharide (TSP). Aside from presenting other benefits, such as reduced toxicity, increased stability/shelf life, and improved pesticide solubility, biopolymeric systems are also cost-effective; readily available; biocompatible; biodegradable; and biosafe (i.e., releasing associated active compounds gradually, without endangering the environment) and have a low carbon footprint. Additionally, biopolymeric nanoformulations support plant growth while improving soil aeration and microbial activity, which may favor the environment. The present review provides a thorough analysis of the toxicity and release behavior of biopolymeric nanopesticides for targeted delivery in precision crop protection.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ab973e22-9f2f-4e3c-bc4e-8d11610017e9', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'An update of the Worldwide Integrated Assessment (WIA) on systemic insecticides. Part 2: impacts on organisms and ecosystems', 'Pisa L, Goulson D, Yang EC, Gibbons D, Sánchez-Bayo F, Mitchell E, Aebi A, van der Sluijs J', 2021, 'Environmental science and pollution research international', '10.1007/s11356-017-0341-3', 'https://doi.org/10.1007/s11356-017-0341-3', 'https://europepmc.org/articles/PMC7921077?pdf=render', NULL, NULL, 49, NULL, 'other', 1, 'cc by', 'New information on the lethal and sublethal effects of neonicotinoids and fipronil on organisms is presented in this review, complementing the previous Worldwide Integrated Assessment (WIA) in 2015. The high toxicity of these systemic insecticides to invertebrates has been confirmed and expanded to include more species and compounds. Most of the recent research has focused on bees and the sublethal and ecological impacts these insecticides have on pollinators. Toxic effects on other invertebrate taxa also covered predatory and parasitoid natural enemies and aquatic arthropods. Little new information has been gathered on soil organisms. The impact on marine and coastal ecosystems is still largely uncharted. The chronic lethality of neonicotinoids to insects and crustaceans, and the strengthened evidence that these chemicals also impair the immune system and reproduction, highlights the dangers of this particular insecticidal class (neonicotinoids and fipronil), with the potential to greatly decrease populations of arthropods in both terrestrial and aquatic environments. Sublethal effects on fish, reptiles, frogs, birds, and mammals are also reported, showing a better understanding of the mechanisms of toxicity of these insecticides in vertebrates and their deleterious impacts on growth, reproduction, and neurobehaviour of most of the species tested. This review concludes with a summary of impacts on the ecosystem services and functioning, particularly on pollination, soil biota, and aquatic invertebrate communities, thus reinforcing the previous WIA conclusions (van der Sluijs et al. 2015).', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a3d82bcf-8481-4187-888d-ed85daab2b30', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Evaluating the Sustainability of Double-Cropping Rotations with Pennycress (Thlaspi arvense)', 'Sarah A. Moore', 2019, 'University of Minnesota Digital Conservancy (University of Minnesota)', NULL, 'http://hdl.handle.net/11299/211703', 'http://hdl.handle.net/11299/211703', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac94d9c9-2445-4715-8d6c-e5efd20703c1', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Anopheles funestus Populations across Africa Are Broadly Susceptible to Neonicotinoids but with Signals of Possible Cross-Resistance from the GSTe2 Gene', 'Assatse T, Tchouakui M, Mugenzi L, Menze B, Nguiffo-Nguete D, Tchapga W, Kekeunou S, Wondji CS', 2023, 'Tropical medicine and infectious disease', '10.3390/tropicalmed8050244', 'https://doi.org/10.3390/tropicalmed8050244', 'https://europepmc.org/articles/PMC10223671?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Evaluating the susceptibility of malaria vectors to the new WHO-recommended products is a key step before large-scale deployment. We mapped the susceptibility profile of Anopheles funestus to neonicotinoids across Africa and established the diagnostic doses of acetamiprid and imidacloprid with acetone + MERO as solvent. Indoor resting An. funestus were collected in 2021 in Cameroon, Malawi, Ghana and Uganda. Susceptibility to clothianidin, imidacloprid and acetamiprid was evaluated using CDC bottle assays and offsprings of the field-caught adults. The L119F-GSTe2 marker was genotyped to assess the potential cross-resistance between clothianidin and this DDT/pyrethroid-resistant marker. Mosquitoes were susceptible to the three neonicotinoids diluted in acetone + MERO, whereas low mortality was noticed with ethanol or acetone alone. The doses of 6 µg/mL and 4 µg/mL were established as diagnostic concentrations of imidacloprid and acetamiprid, respectively, with acetone + MERO. Pre-exposure to synergists significantly restored the susceptibility to clothianidin. A positive correlation was observed between L119F-GSTe2 mutation and clothianidin resistance with the homozygote resistant mosquitoes being more able to survive than heterozygote or susceptible. This study revealed that An. funestus populations across Africa are susceptible to neonicotinoids, and as such, this insecticide class could be effectively implemented to control this species using IRS. However, potential cross-resistance conferred by GSTe2 calls for regular resistance monitoring in the field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('26063326-39c7-4097-a2bd-755cd366b2e5', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Diatomaceous Earth for Arthropod Pest Control: Back to the Future', 'Zeni V, Baliota GV, Benelli G, Canale A, Athanassiou CG', 2021, 'Molecules (Basel, Switzerland)', '10.3390/molecules26247487', 'https://doi.org/10.3390/molecules26247487', 'https://europepmc.org/articles/PMC8706096?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Nowadays, we are tackling various issues related to the overuse of synthetic insecticides. Growing concerns about biodiversity, animal and human welfare, and food security are pushing agriculture toward a more sustainable approach, and research is moving in this direction, looking for environmentally friendly alternatives to be adopted in Integrated Pest Management (IPM) protocols. In this regard, inert dusts, especially diatomaceous earths (DEs), hold a significant promise to prevent and control a wide range of arthropod pests. DEs are a type of naturally occurring soft siliceous sedimentary rock, consisting of the fossilized exoskeleton of unicellular algae, which are called diatoms. Mainly adopted for the control of stored product pests, DEs have found also their use against some household insects living in a dry environment, such as bed bugs, or insects of agricultural interest. In this article, we reported a comprehensive review of the use of DEs against different arthropod pest taxa, such as Acarina, Blattodea, Coleoptera, Diptera, Hemiptera, Hymenoptera, Ixodida, Lepidoptera, when applied either alone or in combination with other techniques. The mechanisms of action of DEs, their real-world applications, and challenges related to their adoption in IPM programs are critically reported.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79c6bf78-44d9-4b6f-a1a8-74387d045e06', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Epigenetic regulations as drivers of insecticide resistance and resilience to climate change in arthropod pests', 'Mogilicherla K, Roy A', 2022, 'Frontiers in genetics', '10.3389/fgene.2022.1044980', 'https://doi.org/10.3389/fgene.2022.1044980', 'https://europepmc.org/articles/PMC9853188?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Arthropod pests are remarkably capable of rapidly adapting to novel forms of environmental stress, including insecticides and climate change. The dynamic interplay between epigenetics and genetics explains the largely unexplored reality underlying rapid climatic adaptation and the development of insecticide resistance in insects. Epigenetic regulation modulates gene expression by methylating DNA and acetylating histones that play an essential role in governing insecticide resistance and adaptation to climate change. This review summarises and discusses the significance of recent advances in epigenetic regulation that facilitate phenotypic plasticity in insects and their symbiotic microbes to cope with selection pressure implied by extensive insecticide applications and climate change. We also discuss how epigenetic changes are passed on to multiple generations through sexual recombination, which remains enigmatic. Finally, we explain how these epigenetic signatures can be utilized to manage insecticide resistance and pest resilience to climate change in Anthropocene.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a9842fc-a0ff-498a-aa17-2d75281ed7fd', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Evidence of carbamate resistance in urban populations of Anopheles gambiae s.s. mosquitoes resistant to DDT and deltamethrin insecticides in Lagos, South-Western Nigeria', 'Oduola Adedayo O, Idowu Emmanuel T, Oyebola Muyiwa K, Adeogun Adedapo O, Olojede Judith B, Otubanjo Olubunmi A, Awolola Taiwo S', 2012, 'Parasites & Vectors', '10.1186/1756-3305-5-116', 'https://doi.org/10.1186/1756-3305-5-116', 'http://www.parasitesandvectors.com/content/5/1/116', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Resistance monitoring is essential in ensuring the success of insecticide based vector control programmes. This study was carried out to assess the susceptibility status of urban populations of Anopheles gambiae to carbamate insecticide being considered for vector control in mosquito populations previously reported to be resistant to DDT and permethrin. Methods Two – three day old adult female Anopheles mosquitoes reared from larval collections in 11 study sites from Local Government Areas of Lagos were exposed to test papers impregnated with DDT 4%, deltamethrin 0.05% and propoxur 0.1% insecticides. Additional tests were carried out to determine the susceptibility status of the Anopheles gambiae population to bendiocarb insecticide. Members of the A. gambiae complex, the molecular forms, were identified by PCR assays. The involvement of metabolic enzymes in carbamate resistance was assessed using Piperonyl butoxide (PBO) synergist assays. The presence of kdr-w/e and ace-1R point mutations responsible for DDT-pyrethroid and carbamate resistance mechanisms was also investigated by PCR. Results Propoxur resistance was found in 10 out of the 11 study sites. Resistance to three classes of insecticides was observed in five urban localities. Mortality rates in mosquitoes exposed to deltamethrin and propoxur did not show any significant difference (P > 0.05) but was significantly higher (P A. gambiae s.s (M form). The kdr -w point mutation at allelic frequencies between 45%-77% was identified as one of the resistant mechanisms responsible for DDT and pyrethroid resistance. Ace-1R point mutation was absent in the carbamate resistant population. However, the possible involvement of metabolic resistance was confirmed by synergistic assays conducted. Conclusion Evidence of carbamate resistance in A. gambiae populations already harbouring resistance to DDT and permethrin is a clear indication that calls for the implementation of insecticide resistance management strategies to combat the multiple resistance identified.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b383667b-28e3-4752-b63a-6611e4db0646', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Cinnamic acid derivatives in agrochemicals: current use and future perspective', 'Lei Q, Zhang W, Geng W, Jin Z, Gan X', 2026, 'Journal of advanced research', '10.1016/j.jare.2025.11.043', 'https://doi.org/10.1016/j.jare.2025.11.043', 'https://europepmc.org/articles/PMC13453655?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundCinnamic acid (CA) and its derivatives are widely used in various fields because of their robust, broad-spectrum biological activities and eco-friendly properties. To date, their applications in food, cosmetics, and medicine have been extensively reviewed; however, the applications of CA derivatives in agrochemicals have not been comprehensively summarized.Aim of the reviewThis review aims to summarize the structures and bioactivities of CA and its derivatives used as pesticides. Furthermore, it highlights the need for greater attention to the development of novel, highly efficient, and low-cost structural scaffolds through AI-assisted molecular design.Key scientific concepts of the reviewBased on the available literature, this review summarizes the current structures and functions of CA and its derivatives in pesticides, including their plant growth-regulating, antiviral, bactericidal, fungicidal, herbicidal, insecticidal, and acaricidal activities. Furthermore, greater attention should be given to discovering novel structural scaffolds that are both effective and inexpensive through artificial intelligence-assisted molecular design. This review identifies future directions for advancing research on CA derivatives in agrochemicals and provides valuable references and fresh perspectives for researchers in pesticide chemistry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('96434e4e-8913-4e55-9632-912fc8540aef', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Fall-armyworm invasion, control practices and resistance breeding in Sub-Saharan Africa', 'Matova PM, Kamutando CN, Magorokosho C, Kutywayo D, Gutsa F, Labuschagne M', 2020, 'Crop Science.', '10.1002/csc2.20317', 'https://doi.org/10.1002/csc2.20317', 'https://europepmc.org/articles/PMC7702106?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Fall armyworm [Spodoptera frugiperda (J.E. Smith); FAW] invasion has exacerbated maize (Zea mays L.) crop yield losses in sub-Saharan Africa (SSA), already threatened by other stresses, especially those that are climate-change induced. The FAW is difficult to control, manage, or eradicate, because it is polyphagous and trans-boundary, multiplies fast, has a short life cycle and migrates easily, and lacks the diapause growth phase. In this study, FAW and its impact in Africa was reviewed, as well as past and present control strategies for this pest. Pesticides, cultural practices, natural enemies, host-plant resistance, integrated pest management (IPM), and plant breeding approaches were examined as possible control strategies. It was concluded that an IPM control strategy, guided by cultural approaches already being used by farmers, and what can be adopted from the Americas, coupled with an insect-resistance management strategy, is the best option to manage this pest in Africa. These strategies will be strengthened by breeding for multi-trait host-plant resistance through stacking of genes for different modes of control of the pest.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87d2a479-db1f-4c10-9cfa-714e6f96162b', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Field efficacy of insecticides for suppressing white mango scale insect (Aulacaspis tubercularis Newstead) (Hemiptera: Diaspididae) in southwest Ethiopia', 'Yassin Nurahmed Ebrahim', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e38156', 'https://doi.org/10.1016/j.heliyon.2024.e38156', 'http://www.sciencedirect.com/science/article/pii/S2405844024141874', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'White mango scale (WMS) Aulacaspis tubercularis Newstead (Hemiptera: Diaspididae) is a polyphagous armored scale insect which is considered one of the key pests of mango (Mangifera indica L.) around the world. Mango is widely grown in Ethiopia whereas its production is challenged by WMS in the last decade. Effective formulations that could help manage the scale as part of IPM practice were sought from field experiments at Seka mango farm, Ethiopia in 2019 and 2020 seasons. The study aimed to evaluate the efficacy of some formulations against WMS on mango trees. Randomized complete block designs with three replications were used for the experiments and each tree served as a plot. Allocation of each treatment within each replication was done randomly. The treatments were applied sequentially three times at 14 days interval using motorized Knapsack sprayer coinciding with peak period of natural infestation. Scale numbers before and after each spray were counted using a microscope with LCD. Sum of live crawler, female and male was registered as WMS count data. Results showed that dimethoate, diazinon, imidacloprid & λ-cyhalothrin sprayed alone; dimethoate rotated with imidacloprid & λ-cyhalothrin, chlorpyrifos-ethyl rotated with paraffin, and diazinon rotated with azadirachtin, caused total mortality of the scales. The results also showed that, chlorpyrifos-ethyl, deltamethrin, paraffin oil and λ-cyhalothrin sprayed alone caused percent reduction with range 83–95 % in both seasons. Hence, the study revealed that dimethoate, diazinon, imidacloprid & λ-cyhalothrin applied individually, dimethoate rotated with imidacloprid & λ-cyhalothrin, chlorpyrifos-ethyl rotated with paraffin and diazinon rotated with azadirachtin fully protect mango trees from WMS and significantly superior to other treatments. Therefore, chemical control of A. tubercularis may consider the use of these materials as foliar application and can be used as components for integrated pest management plans for WMS. However, application in the form of rotation is preferred to the alone spray as the former could substantially reduce the likelihood of inducing pesticide resistance. Cost implications and effects of the products on the natural enemy and residual toxicity in fruits need to be studied.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a7aa4aa8-6467-48cf-9d94-b479dd2d838f', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Health Benefits of Key Constituents in Cichorium intybus L', 'Birsa ML, Sarbu LG', 2023, 'Nutrients', '10.3390/nu15061322', 'https://doi.org/10.3390/nu15061322', 'https://europepmc.org/articles/PMC10058675?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The genus Cichorium (Asteraceae) that originates from the Mediterranean area consists of six species (Cichorium intybus, Cichorium frisee, Cichorium endivia, Cichorium grouse, Cichorium chico and Cichorium pumilum). Cichorium intybus L., commonly known as chicory, has a rich history of being known as a medicinal plant and coffee substitute. A variety of key constituents in chicory play important roles as antioxidant agents. The herb is also used as a forage plant for animals. This review highlights the bioactive composition of C. intybus L. and summarizes the antioxidant activity associated with the presence of inulin, caffeic acid derivatives, ferrulic acid, caftaric acid, chicoric acid, chlorogenic and isochlorogenic acids, dicaffeoyl tartaric acid, sugars, proteins, hydroxycoumarins, flavonoids and sesquiterpene lactones. It also covers the plant''s occurrence, agriculture improvement, natural biosynthesis, geographical distribution and waste valorization.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e7c93306-9d1e-4305-916e-7953290eab34', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'High pyrethroid/DDT resistance in major malaria vector Anopheles coluzzii from Niger-Delta of Nigeria is probably driven by metabolic resistance mechanisms.', 'Abdullahi Muhammad, Sulaiman S Ibrahim, Muhammad M Mukhtar, Helen Irving, Maduamaka C Abajue, Noutcha M A Edith, Sabitu S Da''u, Mark J I Paine', 2021, 'PLoS ONE', '10.1371/journal.pone.0247944', 'https://doi.org/10.1371/journal.pone.0247944', 'https://doi.org/10.1371/journal.pone.0247944', NULL, NULL, 16, NULL, 'other', 1, 'open access (DOAJ)', 'Entomological surveillance of local malaria vector populations is an important component of vector control and resistance management. In this study, the resistance profile and its possible mechanisms was characterised in a field population of the major malaria vector Anopheles coluzzii from Port Harcourt, the capital of Rivers state, in the Niger-Delta Region of Nigeria. Larvae collected in Port-Harcourt, were reared to adulthood and used for WHO bioassays. The population exhibited high resistance to permethrin, deltamethrin and DDT with mortalities of 6.7% ± 2.4, 37.5% ± 3.2 and 6.3% ± 4.1, respectively, but were fully susceptible to bendiocarb and malathion. Synergist bioassays with piperonylbutoxide (PBO) partially recovered susceptibility, with mortalities increasing to 53% ± 4, indicating probable role of CYP450s in permethrin resistance (χ2 = 29.48, P < 0.0001). Transcriptional profiling revealed five major resistance-associated genes overexpressed in the field samples compared to the fully susceptible laboratory colony, Ngoussou. Highest fold change (FC) was observed with GSTe2 (FC = 3.3 in permethrin exposed and 6.2 in unexposed) and CYP6Z3 (FC = 1.4 in exposed and 4.6 in unexposed). TaqMan genotyping of 32 F0 females detected the 1014F and 1575Y knockdown resistance (kdr) mutations with frequencies of 0.84 and 0.1, respectively, while 1014S mutation was not detected. Sequencing of a fragment of the voltage-gated sodium channel, spanning exon 20 from 13 deltamethrin-resistant and 9 susceptible females revealed only 2 distinct haplotypes with a low haplotype diversity of 0.33. The findings of high pyrethroid resistance but with a significant degree of recovery after PBO synergist assay suggests the need to move to PBO-based nets. This could be complemented with carbamate- or organophosphate-based indoor residual spraying in this area.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f068b019-88dd-4fb4-ba6f-d06e367d50ec', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Identification of Transcription Factors Regulating Detoxification Genes CYP9Z140, CYP9AY1, and UGT321AP1 Involved in Thiamethoxam Resistance in Leptinotarsa decemlineata', 'Tian Z, Liu L, Zhang Q, Zhou D, Fu K, Jia Z, Jiang W', 2026, 'Insects', '10.3390/insects17050525', 'https://doi.org/10.3390/insects17050525', 'https://europepmc.org/articles/PMC13207126?pdf=render', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc by', 'The Colorado potato beetle, Leptinotarsa decemlineata, is a major insect pest of potatoes. Our previous studies have demonstrated that two cytochrome P450 monooxygenase (P450s) genes, CYP9Z140 and CYP9AY1, and a uridine diphosphate-glycosyltransferase (UGT) gene, UGT321AP1, play important roles in thiamethoxam resistance to L. decemlineata. However, the related upstream regulatory mechanism remains unclear. In this study, we first monitored the resistance of L. decemlineata field populations to thiamethoxam in Xinjiang to determine the resistance ratios. The predicted results demonstrated that four transcription factors (TFs), CncC/Maf, Abd-B, FoxO, and Ptx1, may bind to the core regions of three gene promoters. The qRT-PCR results revealed that the TFs were significantly upregulated by thiamethoxam and exhibited specific spatiotemporal expression patterns. Dual-luciferase reporter assays indicated that the CncC pathway could regulate the expression of three detoxification genes, whereas Abd-B and FoxO only regulate CYP9Z140 and UGT321AP1 expressions, respectively. Ptx1 could regulate the expression of both CYP9AY1 and UGT321AP1. Furthermore, knockdown of several TFs through RNA interference significantly reduced expression of the corresponding detoxification genes, consistent with the dual-luciferase reporter assay results, and increased the thiamethoxam susceptibility of test adults. These findings aid in gaining a deeper understanding of the transcriptional regulation mechanisms of insecticide resistance in insects.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6cba7197-3d41-49f9-be82-fc18788322aa', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Impact of agriculture on the selection of insecticide resistance in the malaria vector Anopheles gambiae: a multigenerational study in controlled conditions', 'Theresia Estomih Nkya, Rodolphe Poupardin, Frederic Laporte, Idir Akhouayri, Franklin Mosha, Stephen Magesa, William Kisinza, Jean-Philippe David', 2014, 'Parasites & Vectors', '10.1186/s13071-014-0480-z', 'https://doi.org/10.1186/s13071-014-0480-z', 'https://doi.org/10.1186/s13071-014-0480-z', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Resistance of mosquitoes to insecticides is mainly attributed to their adaptation to vector control interventions. Although pesticides used in agriculture have been frequently mentioned as an additional force driving the selection of resistance, only a few studies were dedicated to validate this hypothesis and characterise the underlying mechanisms. While insecticide resistance is rising dramatically in Africa, deciphering how agriculture affects resistance is crucial for improving resistance management strategies. In this context, the multigenerational effect of agricultural pollutants on the selection of insecticide resistance was examined in Anopheles gambiae. Methods An urban Tanzanian An. gambiae population displaying a low resistance level was used as a parental strain for a selection experiment across 20 generations. At each generation larvae were selected with a mixture containing pesticides and herbicides classically used in agriculture in Africa. The resistance levels of adults to deltamethrin, DDT and bendiocarb were compared between the selected and non-selected strains across the selection process together with the frequency of kdr mutations. A microarray approach was used for pinpointing transcription level variations selected by the agricultural pesticide mixture at the adult stage. Results A gradual increase of adult resistance to all insecticides was observed across the selection process. The frequency of the L1014S kdr mutation rose from 1.6% to 12.5% after 20 generations of selection. Microarray analysis identified 90 transcripts over-transcribed in the selected strain as compared to the parental and the non-selected strains. Genes encoding cuticle proteins, detoxification enzymes, proteins linked to neurotransmitter activity and transcription regulators were mainly affected. RT-qPCR transcription profiling of candidate genes across multiple generations supported their link with insecticide resistance. Conclusions This study confirms the potency of agriculture in selecting for insecticide resistance in malaria vectors. We demonstrated that the recurrent exposure of larvae to agricultural pollutants can select for resistance mechanisms to vector control insecticides at the adult stage. Our data suggest that in addition to selected target-site resistance mutations, agricultural pollutants may also favor cuticle, metabolic and synaptic transmission-based resistance mechanisms. These results emphasize the need for integrated resistance management strategies taking into account agriculture activities.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ff2fd77-ec17-4d1e-b32c-74e9d94674ec', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Inheritance and Resistance Mechanisms of Field-Evolved Resistance to Pyrethroids in a Fall Armyworm (Spodoptera frugiperda J.E. Smith) (Lepidoptera: Noctuidae) Strain from Puerto Rico', 'Posos-Parra OA, Pittendrigh BR, Wise JC, DiFonzo C, Patterson E, Mota-Sanchez D', 2024, 'Insects', '10.3390/insects15120912', 'https://doi.org/10.3390/insects15120912', 'https://europepmc.org/articles/PMC11677101?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'This study examines resistance inheritance to the pyrethroid insecticides esfenvalerate and deltamethrin in a Puerto Rican strain of fall armyworm (FAW), Spodoptera frugiperda, a major global pest of corn. The resistant strain (PPR) showed significantly higher resistance compared to a susceptible strain (SUS), with a 62-fold X-linked and 15-fold autosomal-linked resistance ratio (RR50) for esfenvalerate and deltamethrin, respectively. Resistance was incompletely dominant for both insecticides. Synergist bioassays revealed that detoxification enzymes play a key role in resistance, with PPR exhibiting increased toxicity across all tested synergists, especially with a 12-fold increase when all were combined. Deltamethrin assays confirmed the importance of these enzymes, with a 17-fold increase in PPR toxicity when combined with esterase inhibitors. These findings highlight the complexity of pyrethroid resistance, involving multiple non-target site mechanisms, and suggest that heterozygous individuals could survive in treated crops due to incomplete dominance. The results emphasize the need for diversified pest management strategies, including insecticide rotation, to effectively control FAW populations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8106100e-98fe-45f5-8ab9-571581a39e39', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Insect Microbial Symbionts: Ecology, Interactions, and Biological Significance', 'Mondal S, Somani J, Roy S, Babu A, Pandey AK', 2023, 'Microorganisms', '10.3390/microorganisms11112665', 'https://doi.org/10.3390/microorganisms11112665', 'https://europepmc.org/articles/PMC10672782?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'The guts of insect pests are typical habitats for microbial colonization and the presence of bacterial species inside the gut confers several potential advantages to the insects. These gut bacteria are located symbiotically inside the digestive tracts of insects and help in food digestion, phytotoxin breakdown, and pesticide detoxification. Different shapes and chemical assets of insect gastrointestinal tracts have a significant impact on the structure and makeup of the microbial population. The number of microbial communities inside the gastrointestinal system differs owing to the varying shape and chemical composition of digestive tracts. Due to their short generation times and rapid evolutionary rates, insect gut bacteria can develop numerous metabolic pathways and can adapt to diverse ecological niches. In addition, despite hindering insecticide management programs, they still have several biotechnological uses, including industrial, clinical, and environmental uses. This review discusses the prevalent bacterial species associated with insect guts, their mode of symbiotic interaction, their role in insecticide resistance, and various other biological significance, along with knowledge gaps and future perspectives. The practical consequences of the gut microbiome and its interaction with the insect host may lead to encountering the mechanisms behind the evolution of pesticide resistance in insects.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ee64636-b1a6-4ef3-9013-13a741e92422', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Insights into the Effects of Insecticides on Aphids (Hemiptera: Aphididae): Resistance Mechanisms and Molecular Basis', 'Kaleem Ullah RM, Gao F, Sikandar A, Wu H', 2023, 'International journal of molecular sciences', '10.3390/ijms24076750', 'https://doi.org/10.3390/ijms24076750', 'https://europepmc.org/articles/PMC10094857?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'With the passage of time and indiscreet usage of insecticides on crops, aphids are becoming resistant to their effect. The different classes of insecticides, including organophosphates, carbamates, pyrethroids and neonicotinoids, have varied effects on insects. Furthermore, the molecular effects of these insecticides in aphids, including effects on the enzymatic machinery and gene mutation, are resulting in aphid resistance to the insecticides. In this review, we will discuss how aphids are affected by the overuse of pesticides, how resistance appears, and which mechanisms participate in the resistance mechanisms in various aphid species as significant crop pests. Gene expression studies were analyzed using the RNA-Seq technique. The stress-responsive genes were analyzed, and their expression in response to insecticide administration was determined. Putative insecticide resistance-related genes, cytochrome P450, glutathione S-transferase, carboxylesterase CarEs, ABC transporters, cuticle protein genes, and trypsin-related genes were studied. The review concluded that if insecticide-susceptible aphids interact with ample dosages of insecticides with sublethal effects, this will result in the upregulation of genes whose primary role is to detoxify insecticides. In the past decade, certain advancements have been observed regarding insecticide resistance on a molecular basis. Even so, not much is known about how aphids detoxify the insecticides at molecular level. Thus, to attain equilibrium, it is important to observe the manipulation of pest and insect species with the aim of restoring susceptibility to insecticides. For this purpose, this review has included critical insights into insecticide resistance in aphids.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('71914faf-ec6b-4960-92ff-52d66ae1c408', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Mapping malaria vectors and insecticide resistance in a high-endemic district of Haryana, India: implications for vector control strategies', 'Gaurav Kumar, Sanjeev Gupta, Jaspreet Kaur, Shweta Pasi, Rajendra Baharia, Ajeet Kumar Mohanty, Pawan Goel, Amit Sharma', 2024, 'Malaria Journal', '10.1186/s12936-023-04797-8', 'https://doi.org/10.1186/s12936-023-04797-8', 'https://doi.org/10.1186/s12936-023-04797-8', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Achieving effective control and elimination of malaria in endemic regions necessitates a comprehensive understanding of local mosquito species responsible for malaria transmission and their susceptibility to insecticides. Methods The study was conducted in the highly malaria prone Ujina Primary Health Center of Nuh (Mewat) district of Haryana state of India. Monthly entomological surveys were carried out for adult mosquito collections via indoor resting collections, light trap collections, and pyrethrum spray collections. Larvae were also collected from different breeding sites prevalent in the region. Insecticide resistance bioassay, vector incrimination, blood meal analysis was done with the collected vector mosquitoes. Results A total of 34,974 adult Anopheles mosquitoes were caught during the survey period, out of which Anopheles subpictus was predominant (54.7%). Among vectors, Anopheles stephensi was predominant (15.5%) followed by Anopheles culicifacies (10.1%). The Human Blood Index (HBI) in the case of An. culicifacies and An. stephensi was 6.66 and 9.09, respectively. Vector incrimination results revealed Plasmodium vivax positivity rate of 1.6% for An. culicifacies. Both the vector species were found resistant to DDT, malathion and deltamethrin. Conclusion The emergence of insecticide resistance in both vector species, compromises the effectiveness of commonly used public health insecticides. Consequently, the implementation of robust insecticide resistance management strategies becomes imperative. To effectively tackle the malaria transmission, a significant shift in vector control strategies is warranted, with careful consideration and adaptation to address specific challenges encountered in malaria elimination efforts.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4d83df58-9320-424e-b5b5-f8a63b66080a', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Cross-resistance in Alternaria brassicicola from naturally infested broccoli seeds against two succinate dehydrogenase inhibitor fungicides', 'Navjot Kaur, Anoop A. Malik, Daniel G. Cerritos-Garcia, Rachel A. Koch Bach, Sydney Everhart, Bhabesh Dutta', 2025, 'Applied and Environmental Microbiology', '10.1128/aem.01083-25', 'https://doi.org/10.1128/aem.01083-25', 'https://journals.asm.org/doi/10.1128/aem.01083-25', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT Seeds can serve as a vehicle for the dissemination of pests and pathogens around the world. We recently demonstrated the association of pathogenic Alternaria brassicicola isolates with reduced sensitivity to azoxystrobin (quinone-outside inhibitor [QoI]) in naturally infested commercial broccoli seeds. In this study, we further demonstrate that these isolates were also resistant to two succinate dehydrogenase inhibitor (SDHI) fungicides. Sensitivity of representative A. brassicicola isolates (n = 58) from naturally infested broccoli seedlots to QoI and SDHI fungicides was evaluated under in vitro conditions. Interestingly, 15% (n = 9/58) of the A. brassicicola isolates with reduced sensitivity to azoxystrobin also displayed reduced sensitivity to two commonly used SDHI fungicides (boscalid and penthiopyrad) in broccoli, indicating a potential case of cross-resistance to SDHI fungicides. Ninety-three percent of the isolates (n = 54/58) were resistant to both boscalid and penthiopyrad, while 100% isolates displayed sensitivity to fluopyram. Sequence analysis of sdh genes revealed the presence of only one point mutation (H134R) in the sdhC gene in isolates that displayed resistance to boscalid and penthiopyrad. We also developed and validated allele-specific primers targeting the H134R mutation for rapid screening of SDHI resistance in A. brassicicola. We also found that boscalid-resistant isolates exhibited significantly reduced mycelial growth. However, spore germination rates among different resistant isolates were not different, suggesting that resistant isolates remain competitive in natural populations. Overall, this study provides the first evidence of fungicide resistance to SDHI fungicides in A. brassicicola isolated from naturally infested broccoli seeds and underscores the importance of seeds as a potential source for introducing fungicide resistance across geographical locations.IMPORTANCEAlternaria brassicicola is a fungal seed-borne pathogen that can be disseminated via commercial seeds across transplant houses and commercial broccoli fields. Our study provides the first evidence that commercial broccoli seeds can harbor pathogenic A. brassicicola isolates with cross-resistance to two succinate dehydrogenase inhibitor (SDHI) fungicides. We observed that 93% of the A. brassicicola isolates from naturally infested commercial broccoli seeds contained a point mutation that conferred resistance to two SDHI fungicides (boscalid and penthiopyrad). Furthermore, we developed a PCR-based allele-specific assay for the rapid detection and monitoring of fungicide resistance. Our study highlights the importance of seed health testing and potential dissemination of fungicide-resistant isolates locally and globally, thus impacting disease management strategies.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2d4e1e21-f8b5-4667-a91a-75cdf3ed118a', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Determination of Pesticide Residues in Vine Leaves Using the QuEChERS Method and Liquid Chromatography-Tandem Mass Spectrometry', 'Keklik M, Golge O, González-Curbelo MÁ, Kabak B', 2024, 'Foods (Basel, Switzerland)', '10.3390/foods13060909', 'https://doi.org/10.3390/foods13060909', 'https://europepmc.org/articles/PMC10969690?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Commercial viticulture necessitates regular pesticide applications to manage diseases and pests, raising significant concerns regarding pesticide residues among stakeholders. Due to health risks associated with these residues in Turkish vine leaves, the European Commission has increased the frequency of official control from 20% to 50%. Thus, the aim of this study was to determine multi-class pesticide residues in brined vine leaves from Turkey. A total of 766 samples of vine leaves were collected between May 2022 and June 2023. More than 500 residues were analyzed using the quick, easy, cheap, effective, rugged, and safe (QuEChERS) method, followed by liquid chromatography-tandem mass spectrometry. In-house validation data demonstrated that the analytical method exhibits fit-for-purpose performance in terms of linearity, accuracy, precision, and measurement uncertainty. Out of 766 samples analyzed, 180 samples (23.5%) contained one (131, 17.1%) or multiple (49, 6.4%) pesticides. Both the frequencies of occurrence and the rate of maximum residue level (MRL) exceedance increased in 2023 compared to 2022, with the MRL exceedance rate rising from 9.5% to 25.2%. Forty-three different residues were found in quantifiable concentrations and eight of them were non-approved. Among the residues, the non-systemic pyrethroid insecticides, lambda-cyhalothrin (8.0%) and cypermethrin (7.2%), were the two most frequently detected, with concentrations ranging from 0.010 to 0.248 mg kg-1 and from 0.011 to 0.533 mg kg-1, respectively. Turkey is a major exporter of vine leaves and these results provide crucial information regarding pesticide occurrence and quality assessment of vine leaves. The significant increase in both pesticide occurrence and MRL exceedance rates between 2022 and 2023 underscores the urgency for regulatory bodies to reassess current pesticide usage and monitoring practices. The findings emphasize the importance of implementing more stringent rules and improving enforcement methods in order to reduce the spread of unapproved pesticides and ensure adherence to global food safety standards.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5a9e2eef-ebb5-4ff7-8a68-751c3545a723', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Microbial Detoxification of Residual Pesticides in Fermented Foods: Current Status and Prospects', 'Armenova N, Tsigoriyna L, Arsov A, Petrov K, Petrova P', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12061163', 'https://doi.org/10.3390/foods12061163', 'https://europepmc.org/articles/PMC10048192?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'The treatment of agricultural areas with pesticides is an indispensable approach to improve crop yields and cannot be avoided in the coming decades. At the same time, significant amounts of pesticides remain in food and their ingestion causes serious damage such as neurological, gastrointestinal, and allergic reactions; cancer; and even death. However, during the fermentation processing of foods, residual amounts of pesticides are significantly reduced thanks to enzymatic degradation by the starter and accompanying microflora. This review concentrates on foods with the highest levels of pesticide residues, such as milk, yogurt, fermented vegetables (pickles, kimchi, and olives), fruit juices, grains, sourdough, and wines. The focus is on the molecular mechanisms of pesticide degradation due to the presence of specific microbial species. They contain a unique genetic pool that confers an appropriate enzymological profile to act as pesticide detoxifiers. The prospects of developing more effective biodetoxification strategies by engaging probiotic lactic acid bacteria are also discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eddc2b2f-3fbc-4dd7-89d6-a7534c6a0ce4', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'North-South Gradients in Dengue Vector Ecology, Insecticide Resistance, and Community KAP in Laos: Implications for Site-Specific Vector Management', 'Vilayphone Keomany, Malivanh Bouapha, Phonesavanh Silivong, Nanthavong Khampasong', 2026, 'Journal of Public Health and Preventive Medicine', '10.64904/20260705', 'https://doi.org/10.64904/20260705', 'https://journal.physa.org/index.php/fpm/article/view/101', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'Objective: To clarify the species composition, biting rhythm, seasonal fluctuation, and insecticide resistance of dengue vectors in residential areas of northern (Luang Prabang), central (Vientiane), and southern (Attapeu) Laos, and to analyze residents'' knowledge, attitudes, and practices (KAP) regarding dengue prevention and their association with infection. Methods: From 2024 to 2025, human landing catches (HLC) with full personal protection and larval container indices were conducted in three sites. WHO adult contact tube bioassays were performed in Luang Prabang and Vientiane to determine resistance to five insecticides. Structured questionnaires were administered, and laboratory-confirmed dengue infection history was analyzed using multivariable logistic regression. Results: In Luang Prabang, 1,847 adult mosquitoes (2 subfamilies, 5 genera, 17 species) were collected; Aedes aegypti and Ae. albopictus accounted for 1.85% (34) and 2.38% (44), respectively. Biting peaks occurred at 09:00 and 18:00. BI/HI/CI peaked in August–September, with case peaks in October. In Vientiane, 2,156 adults (2 subfamilies, 6 genera, 18 species) were collected; Ae. aegypti and Ae. albopictus accounted for 2.89% (62) and 1.56% (34). Biting peaks were at 08:30–09:30 and 17:30–18:30; BI/HI/CI peaked in May–July, with case peaks in July–August. In Attapeu, 2,341 adults (2 subfamilies, 6 genera, 19 species) were collected; Ae. aegypti and Ae. albopictus accounted for 4.12% (96) and 2.86% (67). Biting peaks were at 08:00–09:00 and 17:00–18:00; BI/HI/CI peaked in April–May, with case peaks in June. In Luang Prabang, 24 h corrected mortality of Ae. aegypti to permethrin, lambda-cyhalothrin, and deltamethrin was 67.53%, 25.47%, and 72.63% (resistant); to fenitrothion and propoxur was 100% and 98.82% (susceptible). In Vientiane, mortality to permethrin and deltamethrin was 58.24% and 65.38% (resistant), with resistance more severe than in Luang Prabang. Multivariable analysis showed that children/adolescents (<18 years) had higher infection risk across all three sites (OR=2.15–2.78). Active larval source reduction significantly lowered infection risk (OR=0.35–0.48). Significant north-south gradients were observed in vector density, seasonal peaks, and pyrethroid resistance. Conclusion: Significant north-south gradients exist in vector ecology, seasonal peaks, and insecticide resistance in Laos. Larval source management remains key to effective prevention, and differentiated, site-specific integrated vector management is urgently needed.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e8434d6-3938-41e7-910e-b547f4b653c9', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Pesticide distribution and depletion kinetic determination in honey and beeswax: Model for pesticide occurrence and distribution in beehive products', 'Shimshoni JA, Sperling R, Massarwa M, Chen Y, Bommuraj V, Borisover M, Barel S', 2019, 'PloS one', '10.1371/journal.pone.0212631', 'https://doi.org/10.1371/journal.pone.0212631', 'https://europepmc.org/articles/PMC6382162?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Beehive products such as honey, beeswax and recently pollen have been regarded for many years as appropriate sentinels for environmental pesticide pollutions. However, despite yearly application of hundreds of approved pesticides in agricultural fields, only a minor fraction of these organic compounds were actually detected in honey and beeswax samples. This observation has led us to question the general suitability of beehive products as a sentinel for synthetic organic pesticides applied in the field. The aim of the present study was to experimentally determine the distribution (logarithmic ratio of beeswax to honey pesticide concentration, LogD) and depletion kinetics (half-life) of selected pesticides in honey and beeswax as a measure of the latter matrixes to serve as a pesticide sentinel. The obtained parameters were used to extrapolate to pesticide burden in honey and beeswax samples collected from German and Israeli apiaries. In addition, we aimed to establish a mathematical model, enabling us to predict distribution of selected pesticides between honey to beeswax, by utilizing simple substance descriptors, namely, octanol/water partitioning coefficient, molar weight and Henry coefficient. Based on the present results, it appears that pesticides with LogD values > 1 and half-life in beeswax > 1 day, were likely to accumulate and detected in beeswax samples, and less likely to be found in honey. On the other hand, pesticides with negative LogD values were highly likely to be found in honey and less so in beeswax samples. Finally, pesticides with LogD values between 0-1 were expected to be found in both matrixes. The developed model was successfully applied to predict LogD values, thereby identifying octanol/water partitioning and molar weight as the most prominent substance descriptors, which affect pesticide distribution between honey and beeswax.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6fd812cd-3c1c-4619-adea-e832ba1cfb5e', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Physiological and oxidative stress responses of Solanum lycopersicum (L.) (tomato) when exposed to different chemical pesticides', 'Hatamleh AA, Danish M, Al-Dosary MA, El-Zaidy M, El-Zaidy M, Ali S', 2022, 'RSC advances', '10.1039/d1ra09440h', 'https://doi.org/10.1039/d1ra09440h', 'https://europepmc.org/articles/PMC8982233?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc', 'Pesticide overuse can have negative effects on developmental processes of non-target host plants. By increasing reactive oxygen species (ROS) levels, pesticides negatively affect cellular metabolism, biochemistry and physiological machinery of plants. Considering these problems, the current study was planned to assess the effect of three different groups of pesticides, namely diazinon (DIZN), imidacloprid (IMID) and mancozeb (MNZB) on Solanum lycopersicum L. (tomato). In general, pesticides resulted in a progressive decrease in physiological and biometric parameters of S. lycopersicum (L.), which varies significantly among concentrations and species of pesticides. Among them, 200 μgMNZB mL-1 had the most severe negative impact and reduced germination rate, root biomass, chl a, chl b, total chlorophyll and carotenoids by 62, 87, 90, 88, 92 and 90%, respectively. In addition, higher doses of pesticides greatly reduced the flowering, fruit attributes and lycopene content. Furthermore, plants exposed to 200 μgDIZN mL-1 showed a progressive drop in root cell viability (54% decrease), total soluble sugar (TSS) (64% decrease) and total soluble protein (TSP) (67% decrease) content. Data analysis indicated that greater doses of pesticides dramatically raised ROS levels and induced membrane damage through production of thiobarbituric acid reactive substances (TBARS), as well as increased cell injury. To deal with pesticide-induced oxidative stress, plants subjected to greater pesticide dosages, showed a substantial increase in antioxidant levels. For instance, ascorbate peroxidase (APX), catalase (CAT), superoxide dismutase (SOD), peroxidase (POD) and guaiacol peroxidase (GPX) were maximally increased by 48, 93, 71, 52 and 94%, respectively following 200 μgMNZB mL-1 soil exposures. Additionally, under a confocal laser scanning microscope (CLSM), pesticide exposed S. lycopersicum (L.) roots stained with 2'',7''-dichlorodihydrofluorescein diacetate (2''7''-DCF) and 3,3''-diaminobenzidine, exhibited an increased ROS production in a concentration-dependent manner. Further, elevated pesticide concentrations resulted in alterations in mitochondrial membrane potential (ΔΨ m) and cellular death in roots, as evidenced by increased Rhodamine 123 (Rhd 123) and Evan''s blue fluorescence, respectively. These findings clearly showed that applying pesticides in excess of permissible amounts might induce oxidative stress and cause oxidative damage in non-target host plants. Overall, the current study indicates that a thorough and secure method be used before selecting pesticides for increasing production of agronomically important vegetable crops in various agro-climatic zones.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d6ede3b-a7b0-4244-9b69-3c939a2fae11', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'RaTexT®: a novel rapid tick exposure test for detecting acaricide resistance in Rhipicephalus microplus ticks in Brazil', 'Frans Jongejan, Laura Berger, José Reck, Priscila Teixeira Ferreira, Mariana Silveira de Jesus, Fabio Barbour Scott, Barbara Rauta de Avelar, Brena Gava Guimarães', 2024, 'Parasites & Vectors', '10.1186/s13071-024-06448-6', 'https://doi.org/10.1186/s13071-024-06448-6', 'https://doi.org/10.1186/s13071-024-06448-6', NULL, NULL, 25, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Acaricide resistance in cattle ticks is a significant concern in (sub)tropical regions, particularly Brazil. The Larval Packet Test (LPT) is the standard laboratory bioassay for resistance diagnosis, which requires triplicates of seven acaricidal dilutions plus controls to cover larval mortalities ranging between 0 and 100%. The value of the LPT lies in providing resistance ratios based on the ratio between the LC50 calculated with potentially resistant and susceptible ticks. However, LC50 ratios are difficult to translate into practical advice for farmers. Moreover, LPT requires laboratory facilities to maintain susceptible tick colonies, and it takes 6 weeks to obtain the larvae to be tested by LPT derived from engorged female ticks collected from cattle in the field. Our novel approach was twofold: first, we upgraded the LPT to the Resistance Intensity Test (RIT) by adopting the latest WHO guidelines for resistance detection in mosquitoes, which combines a 1 × recommended dose with 5 × and 10 × concentrated doses to reveal low, moderate and high resistance intensity, respectively. This reduced the number of test papers and tick larvae and, more importantly, provided relevant information on the resistance level. Our second innovative step was to abolish testing larvae entirely and expose partly engorged adult ticks to the same acaricidal doses immediately after removing them from cattle in the field. This resulted in the Rapid Tick exposure Test (RaTexT®), wherein partly engorged adult ticks were exposed to an acaricide-impregnated, specially designed matrix providing test results within 24 h. This approach directly compared resistance detection in tick larvae in the RIT with resistance in adult ticks in RaTexT®. Methods Laboratory validation was conducted in Brazil with resistant and susceptible colonies of Rhipicephalus microplus ticks. For field validation, adult R. microplus ticks collected from different cattle farms in Brazil were evaluated for resistance to RaTexT®, and the results regarding their larval progenies were compared with those for the RIT. Partly engorged adult ticks derived from cattle infested with laboratory and field strains of R. microplus were exposed to deltamethrin in RaTexT® containers, which contained six rows of four interconnected compartments, accommodating five to eight semi-engorged female ticks with a preferred size ranging between 5 and 8 mm. The corresponding larvae of each strain were exposed in the RIT to the same deltamethrin concentrations in filter papers. Results In RaTexT®, mortality in adult ticks from a resistant strain of R. microplus from Seropédica in Brazil was 38.4%, 54.2% and 75.0% at the 1 ×, 5 × and 10 × doses of deltamethrin, respectively. In RIT, mortality of larvae from the same resistant strain was 2.0%, 4.9% and 19.5% at 1 ×, 5 × and 10 × doses, respectively. The results of RaTexT® and RIT agreed since both tests identified a high level of resistance based on a cut-off of 90% mortality. In RaTexT®, mortality of adult ticks from a susceptible strain originating from Porto Alegre was 73.8%, 92.9% and 97.6% at the 1 ×, 5 × and 10 × doses, respectively. In RIT, mortality of larvae from the susceptible strain was 95.2%, 95.2% and 96.8% at the 1 ×, 5 × and 10 × doses, respectively. Interestingly, both tests identified a low number of unexpected resistant individuals in the susceptible strain since the mortality of neither larvae nor adults reached 100%. This effect remained unnoticed in the LPT, wherein a resistance ratio of 159.5 was found based on the LC50 of the resistant strain divided by the LC50 of the susceptible strain. Next, RaTexT® was compared with RIT using adult and larval ticks derived from three field strains of R. microplus in Brazil. RaTexT® detected high levels of resistance to deltamethrin in adult ticks in all strains, which was confirmed in larvae tested by the RIT. Both tests agreed on the same resistance level with significantly l', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d13d17fa-1d49-4334-8007-0bf299f3023a', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Role of gut symbionts of insect pests: A novel target for insect-pest control', 'Rupawate PS, Roylawar P, Khandagale K, Gawande S, Ade AB, Jaiswal DK, Borgave S', 2023, 'Frontiers in microbiology', '10.3389/fmicb.2023.1146390', 'https://doi.org/10.3389/fmicb.2023.1146390', 'https://europepmc.org/articles/PMC10042327?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Insects possess beneficial and nuisance values in the context of the agricultural sector and human life around them. An ensemble of gut symbionts assists insects to adapt to diverse and extreme environments and to occupy every available niche on earth. Microbial symbiosis helps host insects by supplementing necessary diet elements, providing protection from predators and parasitoids through camouflage, modulation of signaling pathway to attain homeostasis and to trigger immunity against pathogens, hijacking plant pathways to circumvent plant defence, acquiring the capability to degrade chemical pesticides, and degradation of harmful pesticides. Therefore, a microbial protection strategy can lead to overpopulation of insect pests, which can drastically reduce crop yield. Some studies have demonstrated increased insect mortality via the destruction of insect gut symbionts; through the use of antibiotics. The review summarizes various roles played by the gut microbiota of insect pests and some studies that have been conducted on pest control by targeting the symbionts. Manipulation or exploitation of the gut symbionts alters the growth and population of the host insects and is consequently a potential target for the development of better pest control strategies. Methods such as modulation of gut symbionts via CRISPR/Cas9, RNAi and the combining of IIT and SIT to increase the insect mortality are further discussed. In the ongoing insect pest management scenario, gut symbionts are proving to be the reliable, eco-friendly and novel approach in the integrated pest management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29611408-fd3e-4274-9a82-15ea0d08aa10', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Edeine B1 produced by Brevibacillus brevis reduces the virulence of a plant pathogenic fungus by inhibiting mitochondrial respiration', 'Kim B, Nguyen MV, Park J, Kim YS, Han JW, Lee J-Y, Jeon J, Son H', 2024, 'mBio', '10.1128/mbio.01351-24', 'https://doi.org/10.1128/mbio.01351-24', 'https://europepmc.org/articles/PMC11253638?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Plant pathogenic fungi cause serious diseases, which result in the loss of crop yields and reduce the quality of crops worldwide. To counteract the escalating risks of chemical fungicides, interest in biological control agents to manage plant diseases has significantly increased. In this study, we comprehensively screened microbial culture filtrates using a yeast screening system to find microbes exhibiting respiratory inhibition activity. Consequently, we found a soil-borne microbe Brevibacillus brevis HK544 strain exhibiting a respiration inhibitory activity and identified edeine B1 (EB1) from the culture filtrate of HK544 as the active compound of the respiration inhibition activity. Furthermore, against a plant pathogenic fungus Fusarium graminearum, our results showed that EB1 has effects on multiple aspects of respiration with the downregulation of most of the mitochondrial-related genes based on transcriptome analysis, differential EB1-sensitivity from targeted mutagenesis, and the synergistic effects of EB1 with electron transport chain complex inhibitors. With the promising plant disease control efficacy of B. brevis HK544 producing EB1, our results suggest that B. brevis HK544 has potential as a biocontrol agent for Fusarium head blight.IMPORTANCEAs a necrotrophic fungus, Fusarium graminearum is a highly destructive pathogen causing severe diseases in cereal crops and mycotoxin contamination in grains. Although chemical control is considered the primary approach to control plant disease caused by F. graminearum, fungicide-resistant strains have been detected in the field after long-term continuous application of fungicides. Moreover, applying chemical fungicides that trigger mycotoxin biosynthesis is a great concern for many researchers. Biocontrol of Fusarium head blight (FHB) by biological control agents (BCAs) represents an alternative approach and could be used as part of the integrated management of FHB and mycotoxin production. The most extensive studies on bacterial BCAs-fungal communications in agroecosystems have focused on antibiosis. Although many BCAs in agricultural ecology have already been used for fungal disease control, the molecular mechanisms of antibiotics produced by BCAs remain to be elucidated. Here, we found a potential BCA (Brevibacillus brevis HK544) with a strong antifungal activity based on the respiration inhibition activity with its active compound edeine B1 (EB1). Furthermore, our results showed that EB1 secreted by HK544 suppresses the expression of the mitochondria-related genes of F. graminearum, subsequently suppressing fungal development and the virulence of F. graminearum. In addition, EB1 exhibited a synergism with complex I inhibitors such as rotenone and fenazaquin. Our work extends our understanding of how B. brevis HK544 exhibits antifungal activity and suggests that the B. brevis HK544 strain could be a valuable source for developing new crop protectants to control F. graminearum.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('25d1d748-9b59-457c-84fb-70f6b3c3fc89', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Efficacy of Fluorinated Nematicides for Management of Root-knot Nematodes in California Processing Tomatoes', 'Ploeg Antoon T., Edwards Scott, Loffredo Angelo, Becker Jörn Ole', 2024, 'Journal of Nematology', '10.2478/jofnem-2024-0034', 'https://doi.org/10.2478/jofnem-2024-0034', 'https://doi.org/10.2478/jofnem-2024-0034', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'California is the primary US producer of processing tomatoes. After decades-long excellent protection against the common tropical Meloidogyne spp. M. incognita, M. javanica, and M. arenaria (root-knot nematode: RKN) by Mi-resistant tomato cultivars, resistance-breaking RKN populations are spreading throughout the San Joaquin Valley. For some time, nematicidal crop management tools have diminished under CA State regulatory pressure. In recent years, new non-volatile compounds have been developed with novel modes of action. In this project with susceptible processing tomato grown on an M. incognita-infested site, the efficacy of three fluorinated nematicides was evaluated in 10 field trials from 2011 to 2021. Seven trials included fluensulfone, six included fluazaindolizine, and five included fluopyram. On average, tomato root-galling (0 – 10 scale) at harvest was reduced by 3.2, 2.3, and 2.5 by fluazaindolizine, fluensulfone, and fluopyram, respectively, compared to the untreated control. These reductions in root-galling corresponded with estimated yield gains of approximately 21%, 14%, and 15%, respectively, over the untreated control. The reproduction of RKN during the tomato crop was not affected by the nematicides. The tested compounds have a very low acute mammalian toxicity and are more target-specific than previous generations of nematicides. However, there is considerable concern about the persistence of synthetic per- and polyfluoroalkyl substances (PFAS) in the environment, including pharmaceuticals and pesticides containing fluorine with the C-F3 functional group.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cec1f4ff-af6b-4051-b5e3-6ed92c93b689', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Sub-Lethal Effects of Pesticides on the DNA of Soil Organisms as Early Ecotoxicological Biomarkers', 'Vischetti C, Casucci C, De Bernardi A, Monaci E, Tiano L, Marcheggiani F, Ciani M, Comitini F', 2020, 'Frontiers in microbiology', '10.3389/fmicb.2020.01892', 'https://doi.org/10.3389/fmicb.2020.01892', 'https://europepmc.org/articles/PMC7461845?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'This review describes the researches performed in the last years to assess the impact of pesticide sub-lethal doses on soil microorganisms and non-target organisms in agricultural soil ecosystems. The overview was developed through the careful description and a critical analysis of three methodologies based on culture-independent approaches involving DNA extraction and sequencing (denaturing gradient gel electrophoresis, DGGE; next-generation sequencing, NGS) to characterize the microbial population and DNA damage assessment (comet assay) to determine the effect on soil invertebrates. The examination of the related published articles showed a continuous improvement of the possibility to detect the detrimental effect of the pesticides on soil microorganisms and non-target organisms at sub-lethal doses, i.e., doses which have no lethal effect on the organisms. Considering the overall critical discussion on microbial soil monitoring in the function of pesticide treatments, we can confirm the usefulness of PCR-DGGE as a screening technique to assess the genetic diversity of microbial communities. Nowadays, DGGE remains a preliminary technique to highlight rapidly the main differences in microbial community composition, which is able to give further information if coupled with culture-dependent microbiological approaches, while thorough assessments must be gained by high-throughput techniques such as NGS. The comet assay represents an elective technique for assessing genotoxicity in environmental biomonitoring, being mature after decades of implementation and widely used worldwide for its direct, simple, and affordable implementation. Nonetheless, in order to promote the consistency and reliability of results, regulatory bodies should provide guidelines on the optimal use of this tool, strongly indicating the most reliable indicators of DNA damage. This review may help the European Regulation Authority in deriving new ecotoxicological endpoints to be included in the Registration Procedure of new pesticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7983b1c5-6613-4e49-9762-9ac2f8f970ad', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Susceptibility of Anopheles maculipennis to different classes of insecticides in West Azarbaijan Province, Northwestern Iran', 'Ali Reza Chavshin, Farrokh Dabiri, Hassan Vatandoost, Mulood Mohammadi Bavani', 2015, 'Asian Pacific Journal of Tropical Biomedicine', '10.1016/S2221-1691(15)30376-2', 'https://doi.org/10.1016/S2221-1691(15)30376-2', 'http://www.sciencedirect.com/science/article/pii/S2221169115303762', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Objective: To determine the susceptibility status of Anopheles maculipennis (An. maculipennis) against the major insecticides used in the health sectors in West Azarbaijan Province, Northwestern Iran. Methods: Unfed 3-5 days old adult females of An. maculipennis were collected across the West Azarbaijan Province and were subjected to evaluation of their susceptibility following World Health Organization recommended protocol against six insecticides (permethrin, deltamethrin, propoxur, bendiocarb, malathion and dieldrin) belonging to four different classes. Results: In this study, 916 specimens of An. maculipennis were examined against the insecticides which indicated that An. maculipennis was tolerant to permethrin, deltamethrin and dielderin, but displayed resistance against propoxur, bendiocarb and malathion. Conclusions: The pattern of resistance in An. maculipennis could be attributed to the agricultural landscapes, agricultural pesticides used and the exposure of the mosquitoes to insecticides. Logical cooperation is needed between the agriculture and health sectors to ensure the judicious use of pesticides in each sector and the management of probable resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('245fe621-3db6-4f34-893b-bbe2f0b1d9e3', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Synthetic and Natural Insecticides: Gas, Liquid, Gel and Solid Formulations for Stored-Product and Food-Industry Pest Control', 'Stejskal V, Vendl T, Aulicky R, Athanassiou C', 2021, 'Insects', '10.3390/insects12070590', 'https://doi.org/10.3390/insects12070590', 'https://europepmc.org/articles/PMC8305526?pdf=render', NULL, NULL, 68, NULL, 'other', 1, 'cc by', 'The selective application of insecticides is one of the cornerstones of integrated pest management (IPM) and management strategies for pest resistance to insecticides. The present work provides a comprehensive overview of the traditional and new methods for the application of gas, liquid, gel, and solid physical insecticide formulations to control stored-product and food industry urban pests from the taxa Acarina, Blattodea, Coleoptera, Diptera, Hymenoptera, Lepidoptera, Psocoptera, and Zygentoma. Various definitions and concepts historically and currently used for various pesticide application formulations and methods are also described. This review demonstrates that new technological advances have sparked renewed research interest in the optimization of conventional methods such as insecticide aerosols, sprays, fumigants, and inert gases. Insect growth regulators/disruptors (IGRs/IGDs) are increasingly employed in baits, aerosols, residual treatments, and as spray-residual protectants for long-term stored-grain protection. Insecticide-impregnated hypoxic multilayer bags have been proven to be one of the most promising low-cost and safe methods for hermetic grain storage in developing countries. Insecticide-impregnated netting and food baits were originally developed for the control of urban/medical pests and have been recognized as an innovative technology for the protection of stored commodities. New biodegradable acaricide gel coatings and nets have been suggested for the protection of ham meat. Tablets and satchels represent a new approach for the application of botanicals. Many emerging technologies can be found in the form of impregnated protective packaging (insect growth regulators/disruptors (IGRs/IGDs), natural repellents), pheromone-based attracticides, electrostatic dust or sprays, nanoparticles, edible artificial sweeteners, hydrogels, inert baits with synthetic attractants, biodegradable encapsulations of active ingredients, and cyanogenic protective grain coatings. Smart pest control technologies based on RNA-based gene silencing compounds incorporated into food baits stand at the forefront of current strategic research. Inert gases and dust (diatomaceous earth) are positive examples of alternatives to synthetic pesticide products, for which methods of application and their integration with other methods have been proposed and implemented in practice. Although many promising laboratory studies have been conducted on the biological activity of natural botanical insecticides, published studies demonstrating their effective industrial field usage in grain stores and food production facilities are scarce. This review shows that the current problems associated with the application of some natural botanical insecticides (e.g., sorption, stability, field efficacy, and smell) to some extent echo problems that were frequently encountered and addressed almost 100 years ago during the transition from ancient to modern classical chemical pest control methods.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fbd1a794-d179-4674-9b3d-1fde5faa92a6', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'The environmental risks of neonicotinoid pesticides: a review of the evidence post 2013', 'Wood TJ, Goulson D', 2017, 'Environmental science and pollution research international', '10.1007/s11356-017-9240-x', 'https://doi.org/10.1007/s11356-017-9240-x', 'https://europepmc.org/articles/PMC5533829?pdf=render', NULL, NULL, 41, NULL, 'northern_plains', 3, 'cc by', 'Neonicotinoid pesticides were first introduced in the mid-1990s, and since then, their use has grown rapidly. They are now the most widely used class of insecticides in the world, with the majority of applications coming from seed dressings. Neonicotinoids are water-soluble, and so can be taken up by a developing plant and can be found inside vascular tissues and foliage, providing protection against herbivorous insects. However, only approximately 5% of the neonicotinoid active ingredient is taken up by crop plants and most instead disperses into the wider environment. Since the mid-2000s, several studies raised concerns that neonicotinoids may be having a negative effect on non-target organisms, in particular on honeybees and bumblebees. In response to these studies, the European Food Safety Authority (EFSA) was commissioned to produce risk assessments for the use of clothianidin, imidacloprid and thiamethoxam and their impact on bees. These risk assessments concluded that the use of these compounds on certain flowering crops poses a high risk to bees. On the basis of these findings, the European Union adopted a partial ban on these substances in May 2013. The purpose of the present paper is to collate and summarise scientific evidence published since 2013 that investigates the impact of neonicotinoids on non-target organisms. Whilst much of the recent work has focused on the impact of neonicotinoids on bees, a growing body of evidence demonstrates that persistent, low levels of neonicotinoids can have negative impacts on a wide range of free-living organisms.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8caa75d5-d3f3-4763-ba8d-22ecea579bf4', '3d7f453a-6b71-44df-9c69-d3b84c39933c', 'Xylella fastidiosa in Olive: A Review of Control Attempts and Current Management', 'Morelli M, García-Madero JM, Jos Á, Saldarelli P, Dongiovanni C, Kovacova M, Saponari M, Baños Arjona A', 2021, 'Microorganisms', '10.3390/microorganisms9081771', 'https://doi.org/10.3390/microorganisms9081771', 'https://europepmc.org/articles/PMC8397937?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Since 2013, Xylella fastidiosa Wells et al. has been reported to infect several hosts and to be present in different areas of Europe. The main damage has been inflicted on the olive orchards of southern Apulia (Italy), where a severe disease associated with X. fastidiosa subspecies pauca strain De Donno has led to the death of millions of trees. This dramatic and continuously evolving situation has led to European and national (Italian and Spanish) measures being implemented to reduce the spread of the pathogen and the associated olive quick decline syndrome (OQDS). Research has been also carried out to find solutions to better and directly fight the bacterium and its main insect vector, Philaenus spumarius L. In the course of this frantic effort, several treatments based on chemical or biological substances have been tested, in addition to plant breeding techniques and integrated pest management approaches. This review aims to summarize the attempts made so far and describe the prospects for better management of this serious threat, which poses alarming questions for the future of olive cultivation in the Mediterranean basin and beyond.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06c8f209-a71f-4a06-90a4-c2e559f002bd', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'A dicamba resistance-endowing IAA16 mutation leads to significant vegetative growth defects and impaired competitiveness in kochia (Bassia scoparia)†', 'Wu C, LeClere S, Liu K, Paciorek M, Perez-Jones A, Westra P, Sammons RD', 2021, 'Pest management science', '10.1002/ps.6080', 'https://doi.org/10.1002/ps.6080', 'https://europepmc.org/articles/PMC7821297?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc', 'BackgroundPrecise quantification of the fitness cost of synthetic auxin resistance has been impeded by lack of knowledge about the genetic basis of resistance in weeds. Recent elucidation of a resistance-endowing IAA16 mutation (G73N) in the key weed species kochia (Bassia scoparia), allows detailed characterization of the contribution of resistance alleles to weed fitness, both in the presence and absence of herbicides. Different G73N genotypes from a segregating resistant parental line (9425) were characterized for cross-resistance to dicamba, 2,4-d and fluroxypyr, and changes on stem/leaf morphology and plant architecture. Plant competitiveness and dominance of the fitness effects was quantified through measuring biomass and seed production of three F2 lines in two runs of glasshouse replacement series studies.ResultsG73N confers robust resistance to dicamba but only moderate to weak resistance to 2,4-D and fluroxypyr. G73N mutant plants displayed significant vegetative growth defects: (i) they were 30-50% shorter, with a more tumbling style plant architecture, and (ii) they had thicker and more ovate (versus lanceolate and linear) leaf blades with lower photosynthesis efficiency, and 40-60% smaller stems with less-developed vascular bundle systems. F2 mutant plants had impaired plant competitiveness, which can lead to 80-90% less biomass and seed production in the replacement series study. The pleiotropic effects of G73N were mostly semidominant (0.5) and fluctuated with the environments and traits measured.ConclusionG73N is associated with significant vegetative growth defects and reduced competitiveness in synthetic auxin-resistant kochia. Management practices should target resistant kochia''s high vulnerability to competition in order to effectively contain the spread of resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2a9019be-648e-4cf7-9eb1-5fa5d77c9646', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'An in-frame deletion mutation in the degron tail of auxin coreceptor IAA2 confers resistance to the herbicide 2,4-D in Sisymbrium orientale', 'Figueiredo MRA, Küpper A, Malone JM, Petrovic T, Figueiredo ABTB, Campagnola G, Peersen OB, Prasad KVSK', 2022, 'Proceedings of the National Academy of Sciences of the United States of America', '10.1073/pnas.2105819119', 'https://doi.org/10.1073/pnas.2105819119', 'https://europepmc.org/articles/PMC8892348?pdf=render', NULL, NULL, 9, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'The natural auxin indole-3-acetic acid (IAA) is a key regulator of many aspects of plant growth and development. Synthetic auxin herbicides such as 2,4-D mimic the effects of IAA by inducing strong auxinic-signaling responses in plants. To determine the mechanism of 2,4-D resistance in a Sisymbrium orientale (Indian hedge mustard) weed population, we performed a transcriptome analysis of 2,4-D-resistant (R) and -susceptible (S) genotypes that revealed an in-frame 27-nucleotide deletion removing nine amino acids in the degron tail (DT) of the auxin coreceptor Aux/IAA2 (SoIAA2). The deletion allele cosegregated with 2,4-D resistance in recombinant inbred lines. Further, this deletion was also detected in several 2,4-D-resistant field populations of this species. Arabidopsis transgenic lines expressing the SoIAA2 mutant allele were resistant to 2,4-D and dicamba. The IAA2-DT deletion reduced binding to TIR1 in vitro with both natural and synthetic auxins, causing reduced association and increased dissociation rates. This mechanism of synthetic auxin herbicide resistance assigns an in planta function to the DT region of this Aux/IAA coreceptor for its role in synthetic auxin binding kinetics and reveals a potential biotechnological approach to produce synthetic auxin-resistant crops using gene-editing.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a162f894-7f11-4917-a176-87e853459647', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Biology, Ecology, and Pest Management of the Tarnished Plant Bug, Lygus lineolaris (Palisot de Beauvois) in Southern Row Crops', 'George J, Glover JP, Gore J, Crow WD, Reddy GVP', 2021, 'Insects', '10.3390/insects12090807', 'https://doi.org/10.3390/insects12090807', 'https://europepmc.org/articles/PMC8465932?pdf=render', NULL, NULL, 30, NULL, 'canada', 3, 'cc by', 'The tarnished plant bug, Lygus lineolaris (Palisot de Beauvois), (Hemiptera: Miridae) is considered the most damaging pest of cotton (Gossypium hirsutum L.) in the mid-southern United States, although it is established throughout the United States, southern Canada, and northern Mexico. The introduction of transgenic crops for the control of moths in the Heliothine complex and eradication of the boll weevil, Anthonomus grandis, from much of the United States led to greatly reduced pesticide use in cotton fields, which allowed L. lineolaris to emerge as a new primary pest of cotton in the mid-southern United States. Since the publication of a review by Layton (2000) on damage caused by Lygus lineolaris, many new studies have been published on the changes in host range, population dynamics, sampling methods and thresholds, cultural practices, sex pheromones and attractant blends, novel pesticides and insecticide resistance mechanisms, olfactory and feeding behaviors, introduction of biological control agents, host-plant resistance mechanisms, and new molecular and genetic tools for integrated pest management of Lygus species in cotton and other important crops. Here, we review and discuss the latest developments in L. lineolaris research in the last two decades.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d9bdb97b-eba8-49de-93c9-aba426b328c9', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Characterization of clopyralid resistance in lawn burweed (Soliva sessilis).', 'Hossein Ghanizadeh, Fengshuo Li, Lulu He, Kerry C Harrington', 2021, 'PLoS ONE', '10.1371/journal.pone.0253934', 'https://doi.org/10.1371/journal.pone.0253934', 'https://doi.org/10.1371/journal.pone.0253934', NULL, NULL, 18, NULL, 'other', 1, 'open access (DOAJ)', 'Soliva sessilis is a troublesome annual weed species in New Zealand turfgrass. This weed has been controlled selectively in New Zealand turfgrass for many years using pyridine herbicides such as clopyralid. However, in some golf courses, the continuous application of pyridine herbicides has resulted in the selection of S. sessilis populations that are resistant to these herbicides. This study focuses on a clopyralid-resistant population of S. sessilis collected from a golf course with a long history of clopyralid applications. The resistant phenotype of S. sessilis was highly resistant to clopyralid (over 225-fold). It was also cross-resistant to dicamba, MCPA and picloram but not mecoprop. The level of resistance to dicamba was high (7-14-fold) but much lower (2-3-fold) for both MCPA and picloram. The phenotype was morphologically distinct from its susceptible counterpart. Individuals of the clopyralid-resistant phenotype had fewer lobes on their leaves and were slightly larger compared to the susceptible phenotype. Resistant individuals also had a larger leaf area and greater root dry weight than the susceptible plants. An evaluation of internal transcribed spacer (ITS) regions confirmed that clopyralid-resistant phenotypes are conspecific with S. sessilis. In summary, the cross-resistance to several auxinic herbicides in this S. sessilis phenotype greatly reduces chemical options for controlling it; thus, other integrated management practices may be needed such as using turfgrass competition to reduce weed germination. However, the morphological differences between resistant and susceptible plants make it easy to see, which will help with its management.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b4ee3ea-b982-4bee-8c8c-dd8c021e968e', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Co-selection for antibiotic resistance by environmental contaminants', 'Murray LM, Hayes A, Snape J, Kasprzyk-Hordern B, Gaze WH, Murray AK', 2024, 'npj antimicrobials and resistance', '10.1038/s44259-024-00026-7', 'https://doi.org/10.1038/s44259-024-00026-7', 'https://europepmc.org/articles/PMC11721650?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'The environment is increasingly recognised as a hotspot for the selection and dissemination of antibiotic resistant bacteria and antibiotic resistance genes. These can be selected for by antibiotics and non-antibiotic agents (such as metals and biocides), with the evidence to support this well established by observational and experimental studies. However, there is emerging evidence to suggest that plant protection products (such as herbicides), and non-antibiotic drugs (such as chemotherapeutic agents), can also co-select for antibiotic resistance. This review aims to provide an overview of four classes of non-antibiotic agents (metals, biocides, plant protection products, and non-antibiotic drugs) and how they may co-select for antibiotic resistance, with a particular focus on the environment. It also aims to identify key knowledge gaps that should be addressed in future work, to better understand these potential co-selective agents.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a3f0ef3-43c9-4ab0-b3bd-ba6d861911e9', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Confirmation and management of atrazine-resistant Palmer amaranth (Amaranthus palmeri) in North Carolina', 'Diego J. Contreras, Ronel J. Argueta, Eric A.L. Jones, Charles W. Cahoon, Wesley J. Everman', 2026, 'Weed Technology', '10.1017/wet.2026.10125', 'https://doi.org/10.1017/wet.2026.10125', 'https://www.cambridge.org/core/product/identifier/S0890037X26101250/type/journal_article', NULL, NULL, 8, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'North Carolina farmers rely extensively on applying atrazine to their corn crops to achieve effective control of Palmer amaranth. In 2016, a farmer in Washington County, North Carolina, reported a failure of atrazine to control Palmer amaranth in a corn field. Greenhouse studies were conducted to confirm whether the Washington County Palmer amaranth population was resistant to atrazine and to assess the effectiveness of other effective postemergence herbicides. Two atrazine-susceptible Palmer amaranth populations collected from Edgecombe and Johnston counties were used for comparison. Greenhouse response assays confirmed the Washington County population is resistant to atrazine, with a lethal dose of 1,253 g ai ha−1 causing 50% mortality (LD50). This population was 7-fold and 9-fold less susceptible to atrazine than the populations in Edgecombe County (LD50 208 g ai ha−1) and Johnston County (LD50 155 g ai ha−1), respectively. Additionally, the LD80 (the lethal dose of atrazine that would cause 80% mortality) of the Washington County population (12,107 ga ai ha−1) was more than five times greater than the maximum labeled rate for atrazine. A subsequent screening of Palmer amaranth with field-use rates suggested that 2,4-D, dicamba, fomesafen, glufosinate, and mesotrione provide at least 79% or greater control of the Washington County population. The Washington County population was not effectively controlled by thifensulfuron or glyphosate, both of which have faced widespread resistance throughout North Carolina. The results of these experiments provide evidence that the Washington County population of Palmer amaranth is resistant to atrazine, glyphosate, and thifensulfuron, and effective herbicides to manage this population were confirmed.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('70081647-1752-4dbb-ac12-a0f70152fafd', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Cover crop inclusion and residue retention improves soybean production and physiology in drought conditions', 'Whippo CW, Saliendra NZ, Liebig MA', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e29838', 'https://doi.org/10.1016/j.heliyon.2024.e29838', 'https://europepmc.org/articles/PMC11063448?pdf=render', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Soybean (Glycine max (L.) Merr.) planting has increased in central and western North Dakota despite frequent drought occurrences that limit productivity. Soybean plants need high photosynthetic and transpiration rates to be productive, but they also need high water use efficiency when water is limited. Crop residues and cover crops in crop rotations may improve soybean drought tolerance in northern Great Plains. We aimed to examine how a management practice that included cover crops and residue retention impacts agronomic, ecosystem water and carbon dioxide flux, and canopy-scale physiological attributes of soybeans in the northern Great Plains under drought conditions. The experiment consisted of two soybean fields over two years with business-as-usual (no-cover crops and spring wheat residue removal) and aspirational management (cover crops and spring wheat residue retention) during a drought year. We compared yield; aboveground biomass; green chromatic coordinates, and CO2 and H2O fluxes from eddy covariance, Phenocam images, and ancillary micrometeorological measurements. These measurements were used to derive ecosystem-scale physical, and physiological attributes with the ''big leaf'' framework to diagnose underlying processes. Soybean yields were 29 % higher under drought conditions in the field managed in a system that included cover crops and residue retention. This yield increase was associated with a 5 day increase in the green-chromatic-coordinate defined maturity phenophase, increasing agronomic and intrinsic water use efficiency by 27 % and 33 %, respectively, increasing water uptake, and increasing the rubisco-limited photosynthetic capacity (Vcmax25) by 42 %. The inclusion of cover crops and residue retention into a cropping system improved soybean productivity because of differences in water use, phenology timing, and photosynthetic capacity. These results suggest that farmers can improve soybean productivity and yield stability by incorporating cover crops and residue retention into their management suite because these practices to facilitate more aggressive water uptake.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8e22d762-3f09-456a-be80-487647d35c78', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'CRISPR/Cas9-mediated homology donor repair base editing confers glyphosate resistance to rice (Oryza sativa L.)', 'Sony SK, Kaul T, Motelb KFA, Thangaraj A, Bharti J, Kaul R, Verma R, Nehra M', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1122926', 'https://doi.org/10.3389/fpls.2023.1122926', 'https://europepmc.org/articles/PMC10027715?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Globally, CRISPR-Cas9-based genome editing has ushered in a novel era of crop advancements. Weeds pose serious a threat to rice crop productivity. Among the numerous herbicides, glyphosate [N-(phosphonomethyl)-glycine] has been employed as a post-emergent, broad-spectrum herbicide that represses the shikimate pathway via inhibition of EPSPS (5''-enolpyruvylshikimate-3-phosphate synthase) enzyme in chloroplasts. Here, we describe the development of glyphosate-resistant rice lines by site-specific amino acid substitutions (G172A, T173I, and P177S: GATIPS-mOsEPSPS) and modification of phosphoenolpyruvate-binding site in the native OsEPSPS gene employing fragment knockout and knock-in of homology donor repair (HDR) template harboring desired mutations through CRISPR-Cas9-based genome editing. The indigenously designed two-sgRNA OsEPSPS-NICTK-1_pCRISPR-Cas9 construct harboring rice codon-optimized SpCas9 along with OsEPSPS-HDR template was transformed into rice. Stable homozygous T2 edited rice lines revealed significantly high degree of glyphosate-resistance both in vitro (4 mM/L) and field conditions (6 ml/L; Roundup Ready) in contrast to wild type (WT). Edited T2 rice lines (ER1-6) with enhanced glyphosate resistance revealed lower levels of endogenous shikimate (14.5-fold) in contrast to treated WT but quite similar to WT. ER1-6 lines exhibited increased aromatic amino acid contents (Phe, two-fold; Trp, 2.5-fold; and Tyr, two-fold) than WT. Interestingly, glyphosate-resistant Cas9-free EL1-6 rice lines displayed a significant increment in grain yield (20%-22%) in comparison to WT. Together, results highlighted that the efficacy of GATIPS mutations in OsEPSPS has tremendously contributed in glyphosate resistance (foliar spray of 6 ml/L), enhanced aromatic amino acids, and improved grain yields in rice. These results ensure a novel strategy for weed management without yield penalties, with a higher probability of commercial release.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1670b8f1-a961-44cc-b6bd-2470e51c5eb6', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Cytochrome P450 Gene Families: Role in Plant Secondary Metabolites Production and Plant Defense', 'Chakraborty P, Biswas A, Dey S, Bhattacharjee T, Chakrabarty S', 2023, 'Journal of xenobiotics', '10.3390/jox13030026', 'https://doi.org/10.3390/jox13030026', 'https://europepmc.org/articles/PMC10443375?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Cytochrome P450s (CYPs) are the most prominent family of enzymes involved in NADPH- and O2-dependent hydroxylation processes throughout all spheres of life. CYPs are crucial for the detoxification of xenobiotics in plants, insects, and other organisms. In addition to performing this function, CYPs serve as flexible catalysts and are essential for producing secondary metabolites, antioxidants, and phytohormones in higher plants. Numerous biotic and abiotic stresses frequently affect the growth and development of plants. They cause a dramatic decrease in crop yield and a deterioration in crop quality. Plants protect themselves against these stresses through different mechanisms, which are accomplished by the active participation of CYPs in several biosynthetic and detoxifying pathways. There are immense potentialities for using CYPs as a candidate for developing agricultural crop species resistant to biotic and abiotic stressors. This review provides an overview of the plant CYP families and their functions to plant secondary metabolite production and defense against different biotic and abiotic stresses.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e242c0be-433f-43e8-876d-a7596a06787e', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Deciphering the role of glycine betaine in enhancing plant performance and defense mechanisms against environmental stresses', 'Basit F, Alyafei M, Hayat F, Al-Zayadneh W, El-Keblawy A, Sulieman S, Sheteiwy MS', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1582332', 'https://doi.org/10.3389/fpls.2025.1582332', 'https://europepmc.org/articles/PMC12325374?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'In the context of climate change, abiotic stresses are recognized as significant environmental challenges that limit agricultural productivity globally. These conditions disrupt normal plant growth and development processes. The ability of plants to tolerate these stressors is linked to their resilience mechanisms. Glycine betaine (GB), also known as betaine, is a derivative of methylated glycine identified in numerous plant species as a substance that mitigates the detrimental effects of stressful environments. GB is synthesized in the cytosol as an initial response to abiotic stress, and signaling molecules, such as jasmonic acid and methyl jasmonate, primarily initiate its production. Recent studies have highlighted their role in stimulating GB synthesis and its subsequent accumulation. The concentration of GB within a plant system can effectively indicate tolerance levels, ultimately contributing to the understanding of resilience mechanisms. GB plays a crucial role in reducing the accumulation and detoxification of reactive oxygen species (ROS), which aids in restoring photosynthesis and alleviating oxidative stress. It contributes to the stabilization of membranes and macromolecules and is essential for the protection and stabilization of photosynthetic components, such as ribulose-1,5-bisphosphate carboxylase/oxygenase, photosystem II, and quaternary enzyme and protein complex structures, under environmental stress conditions. Furthermore, GB can enhance stress tolerance even at minimal concentrations by activating the genes associated with stress defense mechanisms. Recent studies have demonstrated that the application of GB can protect against environmental challenges, thereby improving both crop yield and quality. This review concentrates on the role of GB in promoting abiotic stress tolerance and explores potential strategies for engineering GB biosynthesis in plants.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ddb0964-76b5-4e30-a2a6-c48eb5f43d98', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Developing a decision-making framework for insect pest management: a case study using Aphis glycines (Hemiptera: Aphididae)', 'Dean AN, Niemi JB, Tyndall JC, Hodgson EW, O''Neal ME', 2021, 'Pest management science', '10.1002/ps.6093', 'https://doi.org/10.1002/ps.6093', 'https://europepmc.org/articles/PMC7821323?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'BackgroundThe profitability of farming varies based on factors such as a crop''s market value, input costs and occurrence of resistant pests, all capable of altering the value of pest management tactics in an integrated pest management program. We provide a framework for calculating expected yield and expected net revenue of pest management scenarios, using the soybean aphid (Aphis glycines) as a case study. Foliar insecticide and host-plant resistance are effective management tactics for preventing yield loss from soybean aphid outbreaks; however, pyrethroid-resistant aphid populations pose a management challenge for farmers. We evaluated eight scenarios relevant to soybean aphid management in Iowa with varying probabilities of aphid outbreaks and insecticide-resistant aphids occurring.ResultsOur equation suggests that insecticide use is profitable when the probability of an aphid outbreak is ≥29%, and soybean production will become more costly with increasing probability of pyrethroid-resistant aphids. If farmers continue to use pyrethroids, they will not experience financial consequences from pyrethroid-resistant aphids until the chance of insecticide resistance is 48%. Aphid-resistant varieties provided consistent yield and offered the highest net revenue under all conditions.ConclusionThis framework can be used for other crop-pest systems to evaluate the profitability of management tactics and investigate how resistance impacts revenue for farmers. Including the cost of resistance in crop budgets can help farmers and agronomic consultants comprehend these impacts and enhance decision-making to increase revenue and curb resistance development.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('333563fb-4c39-46ba-8fcb-341f00181e28', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Dicamba-based preemergence herbicide tank mixtures improved residual weed control in dicamba-resistant soybean', 'Sachin Dhanda, Navjot Singh, Joseph T. Ikley, Ryan P. DeWerff, Rodrigo Werle, Debalin Sarangi', 2025, 'Frontiers in Agronomy', '10.3389/fagro.2025.1576547', 'https://doi.org/10.3389/fagro.2025.1576547', 'https://www.frontiersin.org/articles/10.3389/fagro.2025.1576547/full', NULL, NULL, 11, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'In February 2024, the United States Environmental Protection Agency (EPA) vacated the registrations of dicamba products for over-the-top applications on dicamba-resistant cotton and soybean following a court ruling. This decision has raised significant concerns among United States farmers, who now have limited chemical options to manage tough-to-control weeds. However, the risk of off-target dicamba movement to sensitive plants remains a critical issue. If permitted in the future, applying dicamba as a preemergence (PRE) treatment, tank-mixed with other soil residual herbicides, could help reduce off-target movement while preserving its utility for managing problem weeds. Field experiments were conducted in 2022 and 2023 in Minnesota and North Dakota, and in 2021 and 2022 in Wisconsin, to evaluate the effectiveness of dicamba-based PRE herbicide mixtures in soybean. Across all site-years, dicamba tank mixed with other soil residual herbicides provided better control of targeted weed species at 21 d after treatment (DAT) compared to applying the residual herbicides alone. In Minnesota, dicamba-based herbicide tank mixes provided an average waterhemp control of 72%, compared to 59% for treatments without dicamba at 21 DAT. Similarly, in North Dakota, waterhemp control at 21 DAT improved from 74% with residual herbicides alone to 97% when tank mixed with dicamba. In Wisconsin, dicamba-based tank mixes resulted in 96% control of common ragweed and 83% of velvetleaf, versus 83% and 73% for those species, respectively, without dicamba. At the Minnesota site, adding dicamba to residual herbicides improved common lambsquarters and giant ragweed control by 17% and 20%, respectively, and their densities were reduced by at least 50%. At the North Dakota site, kochia control was improved by 23% with dicamba PRE. The results from this research outlined the effectiveness of PRE application of dicamba tank mixed with other residual herbicides for effective weed management in the Upper Midwest.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a5c60c4-9e36-444d-990f-b503e948707d', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Effect of Seed Priming with Endophytic Bacillus subtilis on Some Physio-Biochemical Parameters of Two Wheat Varieties Exposed to Drought after Selective Herbicide Application', 'Lastochkina O, Yakupova A, Avtushenko I, Lastochkin A, Yuldashev R', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12081724', 'https://doi.org/10.3390/plants12081724', 'https://europepmc.org/articles/PMC10144775?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Wheat plants are frequently exposed to combined herbicide and drought stress (HDS) which induces complex responses negatively, affects productivity, and is becoming more exacerbated with current climate change. In this work, we studied the influence of seed priming with endophytic bacteria Bacillus subtilis (strains 104 and 26D) on growth and tolerance of two wheat (Triticum aestivum L.) varieties (E70-drought tolerant; SY-drought susceptible) exposed to soil drought after application of selective herbicide Sekator® Turbo in pot experiments under controlled conditions; 17-day-old plants sprayed with herbicide and after 3 days were subjected to soil drought by stopping irrigating the plants for 7 days with subsequent resumption of normal irrigation (recovery). Additionally, the growth of tested strains (104, 26D) in the presence of different concentrations of herbicide Sekator® Turbo and drought (PEG-6000) were evaluated. It was established that both strains are herbicide and drought tolerant and capable to improve seed germination and early seedlings'' growth under different herbicide and drought stress degrees. The results of pot experiments showed that HDS exposure declined growth (plant length, biomass), photosynthetic pigments (chlorophyll a and b), leaf area, and increased lipid peroxidation (LPO) and proline accumulation in plants, demonstrating higher damaging effects for SY variety. Strains 104 and 26D mitigated (in different levels) such negative impacts of HDS on growth of both varieties by increasing length of roots and shoots, biomass, photosynthetic pigments (chlorophyll a and b), and leaf area, reducing stress-caused LPO (i.e., malondialdehyde), and regulating proline biosynthesis, as well as contributing to a faster recovery of growth, photosynthetic pigments, and redox-status of plants in post-stress period in comparison with non-primed plants. These ultimately manifested in forming a better grain yield of both varieties primed with 104, 26D, and exposed to HDS. Thus, both strains 104 and 26D (which are herbicide and drought tolerant) may be used as seed priming agents to improve wheat HDS tolerance and grain yield; however, strain 104 more effectively protected plants of E70, while strain 26D-plants of SY. Further research should be focused on understanding the mechanisms that determine the strain and variety-specificity of endophytic symbiosis and the role of bacteria in the modulation of physiological states of primed plants under stress conditions, including HDS.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79b95379-7a33-43dd-867c-7e8c0d907fc0', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Effects of glyphosate on antibiotic resistance in soil bacteria and its potential significance: A review', 'Bearson BL, Douglass CH, Duke SO, Moorman TB, Tranel PJ', 2025, 'Journal of environmental quality', '10.1002/jeq2.20655', 'https://doi.org/10.1002/jeq2.20655', 'https://europepmc.org/articles/PMC11718153?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by-nc-nd', 'The evolution and spread of antibiotic resistance are problems with important consequences for bacterial disease treatment. Antibiotic use in animal production and the subsequent export of antibiotic resistance elements in animal manure to soil is a concern. Recent reports suggest that exposure of pathogenic bacteria to glyphosate increases antibiotic resistance. We review these reports and identify soil processes likely to affect the persistence of glyphosate, antibiotic resistance elements, and their interactions. The herbicide molecular target of glyphosate is not shared by antibiotics, indicating that target-site cross-resistance cannot account for increased antibiotic resistance. The mechanisms of bacterial resistance to glyphosate and antibiotics differ, and bacterial tolerance or resistance to glyphosate does not coincide with increased resistance to antibiotics. Glyphosate in the presence of antibiotics can increase the activity of efflux pumps, which confer tolerance to glyphosate, allowing for an increased frequency of mutation for antibiotic resistance. Such effects are not unique to glyphosate, as other herbicides and chemical pollutants can have the same effect, although glyphosate is used in much larger quantities on agricultural soils than most other chemicals. Most evidence indicates that glyphosate is not mutagenic in bacteria. Some studies suggest that glyphosate enhances genetic exchange of antibiotic-resistance elements through effects on membrane permeability. Glyphosate and antibiotics are often present together in manure-treated soil for at least part of the crop-growing season, and initial studies indicate that glyphosate may increase abundance of antibiotic resistance genes in soil, but longer term investigations under realistic field conditions are needed. Although there are demonstratable interactions among glyphosate, bacteria, and antibiotic resistance, there is limited evidence that normal use of glyphosate poses a substantial risk for increased occurrence of antibiotic-resistant, bacterial pathogens. Longer term field studies using environmentally relevant concentrations of glyphosate and antibiotics are needed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ef15ca4-1853-4642-bf0a-e71bfd1b134d', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Emerging Challenges for Weed Management in Herbicide-Resistant Crops', 'Karla  L. Gage, Ronald  F. Krausz, S.  Alan Walters', 2019, 'Agriculture', '10.3390/agriculture9080180', 'https://doi.org/10.3390/agriculture9080180', 'https://www.mdpi.com/2077-0472/9/8/180', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Since weed management is such a critical component of agronomic crop production systems, herbicides are widely used to provide weed control to ensure that yields are maximized. In the last few years, herbicide-resistant (HR) crops, particularly those that are glyphosate-resistant, and more recently, those with dicamba (3,6-dichloro-2-methoxybenzoic acid) and 2,4-D (2,4-dichlorophenoxyacetic acid) resistance are changing the way many growers manage weeds. However, past reliance on glyphosate and mistakes made in stewardship of the glyphosate-resistant cropping system have directly led to the current weed resistance problems that now occur in many agronomic cropping systems, and new technologies must be well-stewarded. New herbicide-resistant trait technologies in soybean, such as dicamba-, 2,4-D-, and isoxaflutole- ((5-cyclopropyl-4-isoxazolyl)[2-(methylsulfonyl)-4-(trifluoromethyl)phenyl]methanone) resistance, are being combined with glyphosate- and glufosinate-resistance traits to manage herbicide-resistant weed populations. In cropping systems with glyphosate-resistant weed species, these new trait options may provide effective weed management tools, although there may be increased risk of off-target movement and susceptible plant damage with the use of some of these technologies. The use of diverse weed management practices to reduce the selection pressure for herbicide-resistant weed evolution is essential to preserve the utility of new traits. The use of herbicides with differing sites of action (SOAs), ideally in combination as mixtures, but also in rotation as part of a weed management program may slow the evolution of resistance in some cases. Increased selection pressure from the effects of some herbicide mixtures may lead to more cases of metabolic herbicide resistance. The most effective long-term approach for weed resistance management is the use of Integrated Weed Management (IWM) which may build the ecological complexity of the cropping system. Given the challenges in management of herbicide-resistant weeds, IWM will likely play a critical role in enhancing future food security for a growing global population.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b92e1dcd-510e-4728-96dd-29c29abfbfe6', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Enhanced metabolic detoxification is associated with fluroxypyr resistance in Bassia scoparia', 'Todd OE, Patterson EL, Westra EP, Nissen SJ, Araujo ALS, Kramer WB, Dayan FE, Gaines TA', 2024, 'Plant direct', '10.1002/pld3.560', 'https://doi.org/10.1002/pld3.560', 'https://europepmc.org/articles/PMC10807189?pdf=render', NULL, NULL, 25, NULL, 'northern_plains', 3, 'cc by', 'Auxin-mimic herbicides chemically mimic the phytohormone indole-3-acetic-acid (IAA). Within the auxin-mimic herbicide class, the herbicide fluroxypyr has been extensively used to control kochia (Bassia scoparia). A 2014 field survey for herbicide resistance in kochia populations across Colorado identified a putative fluroxypyr-resistant (Flur-R) population that was assessed for response to fluroxypyr and dicamba (auxin-mimics), atrazine (photosystem II inhibitor), glyphosate (EPSPS inhibitor), and chlorsulfuron (acetolactate synthase inhibitor). This population was resistant to fluroxypyr and chlorsulfuron but sensitive to glyphosate, atrazine, and dicamba. Subsequent dose-response studies determined that Flur-R was 40 times more resistant to fluroxypyr than a susceptible population (J01-S) collected from the same field survey (LD50 720 and 20 g ae ha-1, respectively). Auxin-responsive gene expression increased following fluroxypyr treatment in Flur-R, J01-S, and in a dicamba-resistant, fluroxypyr-susceptible line 9,425 in an RNA-sequencing experiment. In Flur-R, several transcripts with molecular functions for conjugation and transport were constitutively higher expressed, such as glutathione S-transferases (GSTs), UDP-glucosyl transferase (GT), and ATP binding cassette transporters (ABC transporters). After analyzing metabolic profiles over time, both Flur-R and J01-S rapidly converted [14C]-fluroxypyr ester, the herbicide formulation applied to plants, to [14C]-fluroxypyr acid, the biologically active form of the herbicide, and three unknown metabolites. The formation and flux of these metabolites were faster in Flur-R than J01-S, reducing the concentration of phytotoxic fluroxypyr acid. One unique metabolite was present in Flur-R that was not present in the J01-S metabolic profile. Gene sequence variant analysis specifically for auxin receptor and signaling proteins revealed the absence of non-synonymous mutations affecting auxin signaling and binding in candidate auxin target site genes, further supporting our hypothesis that non-target site metabolic degradation is contributing to fluroxypyr resistance in Flur-R.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('596508f5-f96a-441b-a6d7-80e96da7188a', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Herbicides with natural and synthetic biostimulants in spring wheat', 'Kinga Matysiak, Wojciech Miziniak, Sylwia Kaczmarek, Roman Kierzek', 2018, 'Ciência Rural', '10.1590/0103-8478cr20180405', 'https://doi.org/10.1590/0103-8478cr20180405', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0103-84782018001100204&lng=en&tlng=en', NULL, NULL, 10, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT: Although the knowledge on agricultural using of biostimulants increases, there is still little information on their interactions with other chemicals i.e. herbicides. The aim of the study was to assess the influence of popular herbicides (MCPA + dicamba, dicamba + triasulfuron, florasulam+2,4-D) used with and without biostimulants based on seaweed extract (Kelpak) and nitrophenols (Asahi) on weed control efficiency, yield and quality of the crop. Field trial was carried out in the years 2014 and 2015 in the Institute of Plant Protection - National Research Institute in Poznan (Poland). The experiment was established on spring wheat cv.‘Torridon’, in 4 replications, using randomized block design. In the experiment two variants of application were tested. In the first variant preparations (herbicide and biostimulant) were applied as tank mixtures at the crop growth stage BBCH 30 and in the second variant in some combinations herbicide application was followed by biostimulant used alone. Weather conditions had a profound impact on tested preparations activity. Addition of biostimulants to herbicide had not affected weed control efficacy but application of herbicide and biostimulant mixture revealed its influence on yield parameters of wheat. Biostimulants influenced yield quality parameters e.g. by enhancing gluten amount in grains.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46e71f09-386a-4bb1-b93e-c74604b450aa', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'History of Herbicide-Resistant Traits in Cotton in the U.S. and the Importance of Integrated Weed Management for Technology Stewardship', 'Rohith Vulchi, Muthukumar Bagavathiannan, Scott A. Nolte', 2022, 'Plants', '10.3390/plants11091189', 'https://doi.org/10.3390/plants11091189', 'https://www.mdpi.com/2223-7747/11/9/1189', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'This paper reviews the history of herbicide-resistant (HR) traits in U.S. cotton since the beginning, highlighting the shortcomings of each trait over time that has led to the development of their successor and emphasizing the importance of integrated weed management (IWM) going forward to ensure their long-term sustainability. Introduction of glyphosate-resistant cropping systems has allowed for expansion of no-till systems more reliant on herbicides, favored less diverse crop rotations, and heavily relied on a single herbicide mode of action (MOA). With repeated applications of glyphosate over the years, biotypes of glyphosate-resistant (GR) A. palmeri and other weeds became economically damaging pests in cotton production systems throughout the U.S. Moreover, the reported cases of weeds resistant to different MOA across various parts of the United States has increased. The dicamba- (XtendFlex®) and 2,4-D-resistant (Enlist®) cotton traits (with stacks of glyphosate and glufosinate resistance) were introduced and have been highly adopted in the U.S. to manage HR weeds. Given the current rate of novel herbicide MOA discovery and increase in new HR weed cases, the future of sustainable weed management relies on an integrated approach that includes non-herbicidal methods with herbicides to ensure long-term success.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cbb80e2d-3203-4b9d-926b-7087bedba240', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Reduced Sensitivity to Fluopyram in Meloidogyne graminis following Long-Term Exposure in Golf Turf', 'Kammerer CL, Harmon PF, Crow WT', 2023, 'Journal of nematology', '10.2478/jofnem-2023-0048', 'https://doi.org/10.2478/jofnem-2023-0048', 'https://europepmc.org/articles/PMC10646960?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'In recent years, some golf course superintendents in Florida have reported that the turf health is no longer as great, and nematode responses to fluopyram have decreased. The objective of this research was to determine if the mechanism of the reported reduced efficacy was attributable to either: i) enhanced degradation accelerating its breakdown in the soil, or ii) reduced sensitivity to the nematicide in the nematode populations. In a field experiment, soil and nematodes were collected from small plots that had been treated multiple times over four years, for only one year, or never treated. Soil and nematodes were additionally collected from commercial turf sites where either multiple applications of fluopyram had been made for numerous years, or it had never been used. Bioassay experiments found no evidence of enhanced degradation. However, M. graminis collected from small field plots and commercial sites with long-term use of fluopyram were less sensitive to fluopyram in-vitro than those from small plots and commercial sites where fluopyram had not been used. These results indicate that nematicide resistance is a likely cause of reduced fluopyram efficacy on golf-course turf in Florida.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc96be59-7189-43b4-98ef-87b8484fbb07', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Hyperspectral imaging and machine learning for herbicide-resistant kochia identification in sugarbeet', 'Bright Mensah, Kelvin Betitame, Yu Zhang, Thomas Peters, Billy Graham Ram, Mian Jalal, Xin Sun', 2025, 'Journal of Agriculture and Food Research', '10.1016/j.jafr.2025.102284', 'https://doi.org/10.1016/j.jafr.2025.102284', 'http://www.sciencedirect.com/science/article/pii/S2666154325006556', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Weed infestation in sugarbeet fields can substantially affect crop yield and quality, posing a major challenge to the global sugar industry. Herbicides are commonly used to control invasive weeds such as kochia; however, kochia has developed resistance to multiple herbicide sites of action, creating additional management challenges. Effective detection and identification of herbicide-resistant kochia are therefore critical for site-specific management. In this study, hyperspectral imaging in the visible and near-infrared range was used to acquire spectral data from dicamba-resistant, glyphosate-resistant, glyphosate-susceptible kochia, and sugarbeet. Spectra data were acquired and preprocessed using standard normal variate transformation and Savitzky–Golay smoothing methods, followed by stepwise feature selection to identify wavelengths features for classification. The selected wavelengths were used to train supervised machine learning models, namely support vector machine (SVM), random forest (RF), linear discriminant analysis (LDA), and extreme gradient boost (XGBoost). SVM achieved the highest overall accuracy of 84.7 %, followed by RF, LDA, and XGBoost with accuracy of 81.1 %, 73.6 %, and 62.3 %, respectively. The results highlight the potential of hyperspectral imaging combined with machine learning for precise identification of herbicide-resistant weed for site-specific weed control and help reduce the evolution of resistance species in sugarbeet production.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a55c50c1-ec32-4b2c-82e1-838f5d4ed372', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Integrated genomic and transcriptomic approaches reveal oxidative stress adaptation mechanisms in a mesotrione-resistant Amaranthus tuberculatus biotype', 'Laforest M, Bessette M, Gagnon G, Flores-Mejia S, Soufiane B, Goulet MC, Michaud D', 2026, 'Pest management science', '10.1002/ps.70721', 'https://doi.org/10.1002/ps.70721', 'https://europepmc.org/articles/PMC13240694?pdf=render', NULL, NULL, 12, NULL, 'canada', 3, 'cc by', 'BackgroundAmaranthus tuberculatus (waterhemp) is a major agricultural weed known for its rapid evolution of resistance to multiple herbicide modes-of-action. Resistance to 4-hydroxyphenylpyruvate dioxygenase (HPPD) inhibitors such as mesotrione is particularly concerning, yet the underlying genetic and molecular mechanisms remain incompletely understood. This study investigated the basis of mesotrione resistance in a Canadian waterhemp population (biotype 714) using an integrated genomic and transcriptomic approach.ResultsA genome-wide association study (GWAS) on 152 individuals identified 11 unique single nucleotide polymorphisms (SNPs) significantly associated with resistance, with the most significant SNP located on chromosome 13 (P -26). Gene Ontology (GO) enrichment of genes proximal to these SNPs implicated pathways related to electron transport and oxidoreductase activity. Transcriptomic analysis of treated plants revealed 187 differentially expressed genes (DEGs) between resistant and susceptible phenotypes. GO enrichment of these genes highlighted significant upregulation of pathways related to redox homeostasis, glutathione metabolism, lipid signaling and secondary metabolism. Weighted Gene Co-expression Network Analysis (WGCNA) further corroborated these findings, identifying gene modules correlated with resistance that were enriched for functions in oxidative stress response and detoxification.ConclusionMesotrione resistance in this A. tuberculatus population is a complex, polygenic trait. Our findings indicate that resistance is not conferred by a single mechanism, but rather by an enhanced metabolic capacity to mitigate herbicide-induced oxidative stress. This multifaceted defense involves the coordinated regulation of numerous detoxification, signaling, and metabolic pathways. Understanding this complex form of nontarget-site resistance (NTSR) is critical for devising future management strategies to combat the spread of herbicide-resistant weeds. © 2026 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1b677bbd-a577-4c30-b59d-b225b877d3c0', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Iodosulfuron-Methyl-Based Herbicidal Ionic Liquids Comprising Alkyl Betainate Cation as Novel Active Ingredients with Reduced Environmental Impact and Excellent Efficacy', 'Niemczak M, Sobiech Ł, Grzanka M', 2020, 'Journal of agricultural and food chemistry', '10.1021/acs.jafc.0c05850', 'https://doi.org/10.1021/acs.jafc.0c05850', 'https://europepmc.org/articles/PMC7705962?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'open access (Europe PMC)', 'A new family of bio-based herbicidal ionic liquids (HILs) has been synthesized starting from the renewable resource glycine betaine (a derivative of natural amino acids). After esterification, the obtained alkyl betainate bromides containing straight alkyl chains varying from ethyl to octadecyl were combined with a herbicidal anion from the sulfonylurea group (iodosulfuron-methyl). The melting points of the iodosulfuron-methyl-based salts were in a range from 51 to 99 °C, which allows their classification as ionic liquids (ILs). In addition, the new HILs exhibited good affinity for polar and semipolar organic solvents, such as DMSO, methanol, acetonitrile, acetone, and chloroform, while the presence of bulky organic cations reduced their solubility in water. The synthesized products turned out to be stable during storage at 25 °C for over 6 months; however, at 75 °C they underwent fast, progressive degradation and released volatile byproducts. The values of the logarithm of the octanol-water partition coefficient of ILs with alkyls longer than hexyl occurred in the "safe zone" (between 0 and 3); hence, the risk of their migration into groundwater after application or the possibility of their bioaccumulation in the environment is lower in comparison with the currently available commercial form (iodosulfuron-methyl sodium salt). Greenhouse studies confirmed a very high herbicidal efficacy for the obtained salts toward tested plants of oilseed rape, indicating that they may become an attractive replacement for the currently available sulfonylurea-based formulations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a9803e99-4929-4f40-b2ec-97ee056ffe23', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Response of Amaranthus spp. following exposure to sublethal herbicide rates via spray particle drift.', 'Bruno C Vieira, Joe D Luck, Keenan L Amundsen, Todd A Gaines, Rodrigo Werle, Greg R Kruger', 2019, 'PLoS ONE', '10.1371/journal.pone.0220014', 'https://doi.org/10.1371/journal.pone.0220014', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0220014&type=printable', NULL, NULL, 19, NULL, 'other', 1, 'open access (DOAJ)', 'The adverse consequences of herbicide drift towards sensitive crops have been extensively reported in the literature. However, little to no information is available on the consequences of herbicide drift onto weed species inhabiting boundaries of agricultural fields. Exposure to herbicide drift could be detrimental to long-term weed management as several weed species have evolved herbicide-resistance after recurrent selection with sublethal herbicide rates This study investigated the deposition of glyphosate, 2,4-D, and dicamba spray particle drift from applications with two different nozzles in a low speed wind tunnel, and their impact on growth and development of Amaranthus spp. Herbicide drift resulted in biomass reduction or complete plant mortality. Inflection points (distance to 50% biomass reduction) for Amaranthus tuberculatus were 7.7, 4.0, and 4.1 m downwind distance for glyphosate, 2,4-D, and dicamba applications with the flat-fan nozzle, respectively, whereas these values corresponded to 2.8, 2.5, and 1.9 m for applications with the air-inclusion nozzle. Inflection points for Amaranthus palmeri biomass reduction were 16.3, 10.9, and 11.5 m for glyphosate, 2,4-D, and dicamba applications with the flat-fan nozzle, respectively, whereas these values corresponded to 7.6, 5.4, and 5.4 m for applications with the air-inclusion nozzle. Plants were more sensitive to glyphosate at higher exposure rates than other herbicides, whereas plants were more sensitive to 2,4-D and dicamba at lower exposure rates compared to glyphosate. Applications with the flat-fan nozzle resulted in 32.3 and 11.5% drift of the applied rate at 1.0 and 3.0 m downwind, respectively, whereas the air-inclusion nozzle decreased the dose exposure in the same distances (11.4 and 2.7%, respectively). Herbicide drift towards field boundaries was influenced by nozzle design and exposed weeds to herbicide rates previously reported to select for herbicide-resistant biotypes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('90a7cd73-4033-4175-8bb5-ff5bcd95dcb9', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Spraying Brassinolide improves Sigma Broad tolerance in foxtail millet (Setaria italica L.) through modulation of antioxidant activity and photosynthetic capacity', 'Yuan XY, Zhang LG, Huang L, Yang HJ, Zhong YT, Ning N, Wen YY, Dong SQ', 2017, 'Scientific reports', '10.1038/s41598-017-11867-w', 'https://doi.org/10.1038/s41598-017-11867-w', 'https://europepmc.org/articles/PMC5593917?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'To explore the role of Brassinolide (BR) in improving the tolerance of Sigma Broad in foxtail millet (Setaria italica L.), effects of 0.1 mg/L of BR foliar application 24 h before 3.37 g/ha of Sigma Broad treatment at five-leaf stage of foxtail millet on growth parameters, antioxidant enzymes, malondialdehyde (MDA), chlorophyll, net photosynthetic rate (P N), chlorophyll fluorescence and P700 parameters were studied 7 and 15 d after herbicide treatment, respectively. Results showed that Sigma Broad significantly decreased plant height, activities of superoxide dismutase (SOD), chlorophyll content, P N, PS II effective quantum yield (Y (II)), PS II electron transport rate (ETR (II)), photochemical quantum yield of PSI(Y (I)) and PS I electron transport rate ETR (I), but significantly increased MDA. Compared to herbicide treatment, BR dramatically increased plant height, activities of SOD, Y (II), ETR (II), Y (I) and ETR (I). This study showed BR pretreatment could improve the tolerance of Sigma Broad in foxtail millet through improving the activity of antioxidant enzymes, keeping electron transport smooth, and enhancing actual photochemical efficiency of PS II and PSI.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3980524c-a7c1-4d19-990c-26e4b8040621', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'The differential binding and biological efficacy of auxin herbicides', 'Prusinska J, Uzunova V, Schmitzer P, Weimer M, Bell J, Napier RM', 2023, 'Pest management science', '10.1002/ps.7294', 'https://doi.org/10.1002/ps.7294', 'https://europepmc.org/articles/PMC10952535?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'BackgroundAuxin herbicides have been used for selective weed control for 75 years and they continue to be amongst the most widely used weed control agents globally. The auxin herbicides fall into five chemical classes, with two herbicides not classified, and in all cases it is anticipated that recognition in the plant starts with binding to the Transport Inhibitor Response 1 (TIR1) family of auxin receptors. There is evidence that some classes of auxins act selectively with certain clades of receptors, although a comprehensive structure-activity relationship has not been available.ResultsUsing purified receptor proteins to measure binding efficacy we have conducted quantitative structure activity relationship (qSAR) assays using representative members of the three receptor clades in Arabidopsis, TIR1, AFB2 and AFB5. Complementary qSAR data for biological efficacy at the whole-plant level using root growth inhibition and foliar phytotoxicity assays have also been analyzed for each family of auxin herbicides, including for the afb5-1 receptor mutant line.ConclusionsComparisons of all these assays highlight differences in receptor selectivity and some systematic differences between results for binding in vitro and activity in vivo. The results could provide insights into weed spectrum differences between the different classes of auxin herbicides, as well as the potential resistance and cross-resistance implications for this herbicide class. © 2022 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2a1f692-4cd4-4dd0-aded-dc3ec6ab134e', '92d5366b-b4d6-4491-94cd-1d099b2c186f', 'Variability of CP4 EPSPS expression in genetically engineered soybean (Glycine max L. Merrill)', 'Chinnadurai P, Stojšin D, Liu K, Frierdich GE, Glenn KC, Geng T, Schapaugh A, Huang K', 2018, 'Transgenic research', '10.1007/s11248-018-0092-z', 'https://doi.org/10.1007/s11248-018-0092-z', 'https://europepmc.org/articles/PMC6267263?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The expression of the CP4 EPSPS protein in genetically engineered (GE) soybean confers tolerance to the Roundup® family of agricultural herbicides. This study evaluated the variability of CP4 EPSPS expression using an enzyme-linked immunosorbent assay in soybean tissues collected across diverse germplasm and 74 different environments in Argentina, Brazil and the USA. Evaluated material included single and combined (stacked) trait products with other GE traits in entries with cp4 epsps gene at one or two loci. The highest level of CP4 EPSPS was observed in leaf tissues, intermediate in forage and seed, and lowest in root tissues. Varieties with two loci had approximately twice the level of CP4 EPSPS expression compared to one locus entries. Variable and non-directional level of CP4 EPSPS was observed with other factors like genetic background, trait stacking, growing region or season. The maximum and average CP4 EPSPS expression levels in seed provided large margins of exposure (MOE of approximately 4000 and 11,000, respectively), mitigating concerns over exposure to this protein in food and feed from soybean varieties tolerant to Roundup® herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a9d93ccc-44fc-4b4c-a3b4-8a1a5c217c3e', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'A Re-Evaluation of Olive Fruit Fly Organophosphate-Resistant Ace Alleles in Iberia, and Field-Testing Population Effects after in-Practice Dimethoate Use', 'Tânia Nobre, Luis Gomes, Fernando Trindade Rei', 2019, 'Insects', '10.3390/insects10080232', 'https://doi.org/10.3390/insects10080232', 'https://www.mdpi.com/2075-4450/10/8/232', NULL, NULL, 10, NULL, 'other', 1, 'open access (DOAJ)', 'The management of the olive fruit fly (Bactrocera oleae) is traditionally based upon the use of organophosphate insecticides, mainly dimethoate. In this evolutionary arms race between man and pest, the flies have adapted a pesticide resistance, implying two point-mutations of the Ace gene -I214V and G488S- and a 9bp deletion -Δ3Q. We revisited 11 Iberian locations to evaluate this adaptation of organophosphate (OP)-resistant alleles through amplicon sequencing. Screening for populations where the wild type is prevalent allows an identification of hotspots for targeted mitigation measures; we have hence refined the scale to the region with the lowest OP-resistant alleles frequency 71 locations were sampled and individuals checked using a fast and low-cost allele-specific-primer polymerase chain reaction (ASP-PCR) method]. An increase in Ace gene point-mutations was observed, and the Δ3Q mutation remains undetected. The lowest frequencies of the OP-resistant alleles remain in the west, underlining the hypothesis of an introduction of resistance from eastern Mediterranean areas. A field test was performed by sampling the fly population before and after in-practice dimethoate application. A clear reduction in olive fruit fly numbers was observed, with no relevant changes in the genotypic frequencies of the resistance alleles. The findings are discussed in frame of the type and intensity of the selection pressure that has led to the adaptation to resistance and its consequences from the producer perspective.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('98a3715e-04a3-4a8a-9ffa-3d6047287d28', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Advances in Detection Technologies for Pesticide Residues and Heavy Metals in Rice: A Comprehensive Review of Spectroscopy, Chromatography, and Biosensors', 'Han Y, Tian Y, Li Q, Yao T, Yao J, Zhang Z, Wu L', 2025, 'Foods (Basel, Switzerland)', '10.3390/foods14061070', 'https://doi.org/10.3390/foods14061070', 'https://europepmc.org/articles/PMC11941943?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'Pesticide residues and heavy metals, originating from diverse sources such as agricultural practices and industrial activities, pose substantial risks to human health and the ecological environment. For instance, residues of organophosphorus pesticides may damage the human nervous system, while heavy metals such as mercury and cadmium accumulate in living organisms, potentially leading to severe organ damage. The contamination of rice with these pollutants has become a critical concern, necessitating the development of innovative detection techniques that are sensitive, accurate, rapid, portable, and intelligent. This review offers an in-depth analysis of the types, sources, health risks, and ecological impacts of pesticide residues and heavy metals in rice, providing a comprehensive understanding of the challenges and solutions associated with these contaminants. It further provides the fundamental principles, comparative advantages, and technical constraints of both conventional and emerging detection methodologies. These encompass traditional analytical techniques such as spectroscopy and chromatography, well-established immunoassay systems, as well as innovative biosensing technologies. This discussion is substantiated with representative case studies demonstrating their practical applications in rice quality assessment and safety testing. In addition, this review envisions future directions for the development of detection technologies, emphasizing the importance of miniaturization, multiplexed detection, integration with nanotechnology, and real-time monitoring systems. By providing a theoretical foundation for advancing food safety innovation, this review aims to contribute to the ongoing efforts to ensure rice quality and safety, protect public health, and preserve ecological balance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b423602a-f695-4579-8b9f-d7c6dfe4bded', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Agricultural Pest Management: The Role of Microorganisms in Biopesticides and Soil Bioremediation', 'Vermelho AB, Moreira JV, Akamine IT, Cardoso VS, Mansoldo FRP', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13192762', 'https://doi.org/10.3390/plants13192762', 'https://europepmc.org/articles/PMC11479090?pdf=render', NULL, NULL, 49, NULL, 'other', 1, 'cc by', 'Pesticide use in crops is a severe problem in some countries. Each country has its legislation for use, but they differ in the degree of tolerance for these broadly toxic products. Several synthetic pesticides can cause air, soil, and water pollution, contaminating the human food chain and other living beings. In addition, some of them can accumulate in the environment for an indeterminate amount of time. The agriculture sector must guarantee healthy food with sustainable production using environmentally friendly methods. In this context, biological biopesticides from microbes and plants are a growing green solution for this segment. Several pests attack crops worldwide, including weeds, insects, nematodes, and microorganisms such as fungi, bacteria, and viruses, causing diseases and economic losses. The use of bioproducts from microorganisms, such as microbial biopesticides (MBPs) or microorganisms alone, is a practice and is growing due to the intense research in the world. Mainly, bacteria, fungi, and baculoviruses have been used as sources of biomolecules and secondary metabolites for biopesticide use. Different methods, such as direct soil application, spraying techniques with microorganisms, endotherapy, and seed treatment, are used. Adjuvants like surfactants, protective agents, and carriers improve the system in different formulations. In addition, microorganisms are a tool for the bioremediation of pesticides in the environment. This review summarizes these topics, focusing on the biopesticides of microbial origin.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ada6a93-dcf8-4f74-b2cc-0f67e0f11a25', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Intensification of breeding barley varieties for the Peace River Region', 'Government of Alberta', 1985, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/intensification-of-breeding-barley-varieties-for-the-peace-river-region', 'https://open.alberta.ca/dataset/6383800b-d040-4574-98db-9b2088f6a641/resource/ffc0d2bb-2fde-419c-8cfa-3e02200554a5/download/0163040839744-intensification-of-breeding-barley-varieties-for-the-peace-river-region.pdf', NULL, NULL, 74, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project supported the release of two early-maturing barley cultivars, Otal and Jackson, adapted to northwestern Canada. These new cultivars showed a 14 to 15 per cent production increase over older ones and represent a major advance for northern agriculture. Continued support may lead to improved six-row and two-row feed and malting varieties with superior test weight and adaptation. Other developments include low-tillering barley for short seasons, forage cover crops, and special-purpose types like hulless and high-amylopectin barley. Some of these lines may serve as parental material for future breeding.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('45d833e4-7c1c-426e-ad94-3a711de6617a', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Alfalfa weevils (Coleoptera: Curculionidae) in the western United States are resistant to multiple type II pyrethroid insecticides', 'Rodbell EA, Caron CG, Rondon SI, Masood MU, Wanner KW', 2024, 'Journal of economic entomology', '10.1093/jee/toad218', 'https://doi.org/10.1093/jee/toad218', 'https://europepmc.org/articles/PMC10860156?pdf=render', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'The alfalfa weevil (Hypera postica Gyllenhal (Coleoptera: Curculionidae)), a key pest of alfalfa (Medicago sativa L. (Fabales: Fabacae)) across the US, has developed resistance to pyrethroids lambda-cyhalothrin and zeta-cypermethrin in at least 6 western US states. Unfortunately, 6 pyrethroid active ingredients represent most commercial insecticides registered for alfalfa weevil control in forage alfalfa systems. Thus, the loss of efficacy of this mode of action group due to multiple resistance represents a significant agricultural challenge because of a limited registered alternative mode of actions. To evaluate the extent and severity of resistance among pyrethroids around the United States, laboratory bioassays using larvae from Arizona, California, Montana, Oregon, Washington, and Wyoming, including both the Egyptian and western strains, were conducted. Results indicated that similar degrees of resistance among type II pyrethroids as determined by both laboratory bioassays and field trials exist. The LC50 values of alpha-cypermethrin, beta-cyfluthrin and zeta-cypermethrin produced significant correlations with the LC50 values of lambda-cyhalothrin. In contrast, resistance did not include type I pyrethroid, bifenthrin (registered for seed alfalfa production), whose LC50 values yielded a slope not significantly different from zero when correlated with lambda-cyhalothrin. Field trials conducted in Arizona, Montana, and Washington corroborated laboratory results, as commercial formulations with type II pyrethroid active ingredients failed to adequately control alfalfa weevils resistant to lambda-cyhalothrin. Integrated resistance management recommendations are discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a520b7a-8b94-4db6-946a-e644cc811bae', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Bacillus-based biocontrol beyond chemical control in central Africa: the challenge of turning myth into reality', 'Nihorimbere G, Korangi Alleluya V, Nimbeshaho F, Nihorimbere V, Legrève A, Ongena M', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1349357', 'https://doi.org/10.3389/fpls.2024.1349357', 'https://europepmc.org/articles/PMC10877027?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Agricultural productivity in the Great Lakes Countries of Central Africa, including Burundi, Rwanda, and the Democratic Republic of Congo, is affected by a wide range of diseases and pests which are mainly controlled by chemical pesticides. However, more than 30% of the pesticides used in the region are banned in European Union due to their high toxicity. Globally available safe and eco-friendly biological alternatives to chemicals are virtually non-existent in the region. Bacillus PGPR-based biocontrol products are the most dominant in the market and have proven their efficacy in controlling major plant diseases reported in the region. With this review, we present the current situation of disease and pest management and urge the need to utilize Bacillus-based control as a possible sustainable alternative to chemical pesticides. A repertoire of strains from the Bacillus subtilis group that have shown great potential to antagonize local pathogens is provided, and efforts to promote their use, as well as the search for indigenous and more adapted Bacillus strains to local agro-ecological conditions, should be undertaken to make sustainable agriculture a reality in the region.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('08038d9f-8dc4-4d82-816e-d139e151c791', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Balancing Health and Sustainability: Assessing the Benefits of Plant-Based Diets and the Risk of Pesticide Residues', 'Botnaru AA, Lupu A, Morariu PC, Pop OL, Nedelcu AH, Morariu BA, Cioancă O, Di Gioia ML', 2025, 'Nutrients', '10.3390/nu17040727', 'https://doi.org/10.3390/nu17040727', 'https://europepmc.org/articles/PMC11858420?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'The increased consumption of fruit and vegetables is essential for moving towards a healthier and more sustainable diet. Vegetarian diets are gaining in popularity due to their environmental and health implications; however, there is a need for additional research investigating pesticide residues in these foods. It is increasingly recognized that the global food system must prioritize nutritional quality, health, and environmental impact over quantity. Food contaminants, including pesticides, mycotoxins, and heavy metals, pose a substantial threat to food safety due to their persistent nature and harmful effects. We conducted a literature search utilizing four distinct databases (PubMed, Google Scholar, NIH, ScienceDirect) and several combinations of keywords (pesticides, food, vegetarian diet, toxicity, sustainable, removal). Consequently, we selected recent and relevant studies for the proposed topic. We have incorporated articles that discuss pesticide residues in food items, particularly in plant-based products. This study rigorously analyzes the harmful environmental impacts of pesticides and ultimately provides sustainable solutions for their elimination or reduction, along with environmentally sound alternatives to pesticide use. This study concludes that the transition towards sustainable agriculture and food production is essential for reducing pesticide residues in food, thereby protecting human health, wildlife populations, and the environment. This paper argues for the urgent need to transform global food systems to prioritize health and sustainability.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6ae37c45-1cb1-497d-8fc2-c93766b8775f', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Challenges and Perspectives for Integrating Quinoa into the Agri-Food System', 'Afzal I, Haq MZU, Ahmed S, Hirich A, Bazile D', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12193361', 'https://doi.org/10.3390/plants12193361', 'https://europepmc.org/articles/PMC10574050?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Quinoa is a highly nutritious and abiotic stress-tolerant crop that can be used to ensure food security for the rapidly growing world population under changing climate conditions. Various experiments, based on morphology, phenology, physiology, and yield-related attributes, are being conducted across the globe to check its adoptability under stressful environmental conditions. High weed infestation, early stand establishment, photoperiod sensitivity, loss of seed viability after harvest, and heat stress during its reproductive stage are major constraints to its cultivation. The presence of saponin on its outer surface is also a significant restriction to its local consumption. Scientists are using modern breeding programs, such as participatory approaches, to understand and define breeding goals to promote quinoa adaptation under marginalized conditions. Despite its rich nutritional value, there is still a need to create awareness among people and industries about its nutritional profile and potential for revenue generation. In the future, the breeding of the sweet and larger-grain quinoa varietals will be an option for avoiding the cleaning of saponins, but with the risk of having more pests in the field. There is also a need to focus on mechanized farming systems for the cultivation, harvesting, and processing of quinoa to facilitate and expand its cultivation and consumption across the globe, considering its high genetic diversity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('88a6fb41-bc9a-45a4-aa48-93d886cd9304', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Determination of 355 Pesticides in Lemon and Lemon Juice by LC-MS/MS and GC-MS/MS', 'Aslantas S, Golge O, González-Curbelo MÁ, Kabak B', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12091812', 'https://doi.org/10.3390/foods12091812', 'https://europepmc.org/articles/PMC10178108?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'While pesticides have become a primary tool in modern agriculture, these compounds remain a high priority on the list of consumer concerns regarding food safety. The use of pesticides in the production and post-harvesting of lemon fruits is widely used to ensure agricultural yield and fruit quality. Therefore, monitoring studies on citrus fruits to enforce regulatory compliance and ensure food safety is in great demand. The aim of this study was to monitor multi-class pesticide residues in lemon fruits commercialized in Turkey. The transmission of residues that existed on the outer surface of the fruit into its juice was also studied. Whole fruits and lemon juice samples were prepared using the quick, easy, cheap, effective, rugged and safe (QuEChERS) methodology prior to analysis. For the screening and quantification of 355 pesticide residues, liquid chromatography-tandem mass spectrometry (LC-MS/MS) and gas chromatography-tandem mass spectrometry (GC-MS/MS) were used. The analytical method has been shown to have a sufficiently low limit of quantification with respect to current maximum residue limits (MRLs) for all target analytes. The obtained recovery and precision parameters fulfilled the requirements in DG SANTE guidelines. The in-house validated analytical method was then applied for the determination of 355 pesticide substances in 100 whole fruit samples and their juices. Sixteen different residues were detected in 43% of lemon fruits, whereas 57 lemon samples were pesticide-free. The MRLs exceedances were recorded in 29 lemon samples. The most frequently detected (17%) pesticide in lemon fruits was chlorpyrifos-methyl, with a range of 0.013-0.098 mg kg-1. A lower frequency was detected for metamitron (10%, 0.027-0.118 mg kg-1), buprofezin (9%, 0.023-0.076 mg kg-1), pyriproxyfen (9%, 0.021-0.102 mg kg-1) and malathion (7%, 0.100-0.482 mg kg-1) in whole fruits. However, none of the pesticide residues were detected in lemon juice samples. These results showed that target analytes are unable to penetrate the lemon exocarp and/or endocarp.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('40958835-c8bc-4b87-85f0-f53bf7e76175', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Evaluation of the Effects of Agro Pesticides Use on Liver and Kidney Function in Farmers from Buea, Cameroon', 'Manfo FPT, Mboe SA, Nantia EA, Ngoula F, Telefo PB, Moundipa PF, Cho-Ngwa F', 2020, 'Journal of toxicology', '10.1155/2020/2305764', 'https://doi.org/10.1155/2020/2305764', 'https://europepmc.org/articles/PMC7204329?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Agro pesticides are increasingly used worldwide to increase crop production. However, health hazards resulting from human exposure to these chemicals, especially from agricultural areas of developing countries have been a growing concern. The objective of this study was to evaluate the impact of occupational exposure to agro pesticides on the health of farmers in the Buea subdivision, which is one of the major agrarian areas in Cameroon. The study was transversal and involved 90 participants including 58 farmers using pesticides and a reference population of 32 men not involved in occupational use of agro pesticides. The participants were interviewed on agro pesticide use and their health status. Thereafter, blood samples were collected from the participants and used for the assessment of biochemical markers of the liver (alanine aminotransferase and aspartate aminotransferase) and the kidney (creatinine and uric acid) function. Results revealed that farmers frequently used insecticides, fungicides, and herbicides in their farming activities. Farmers reported several acute health symptoms related to pesticides use with the common ones being skin rash, eye irritation, and face burn. When compared to the reference population, the farmers showed significantly elevated (p < 0.01) alanine aminotransferase activity. However, other parameters investigated were not affected significantly. These results suggested that farmers were exposed to 3 different classes of agro pesticides, which induced eye and skin affections. Pesticides exposure resulted in alterations of the liver function hence the increased serum alanine aminotransferase activity. Therefore, there is a need to sensitize the farmers on toxicity and liver alteration potential of agro pesticides and the importance of appropriate protective equipment that may minimize exposure.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b5a81953-480a-45f3-88e7-05bac47467ec', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Field evolved insecticide resistance in the cotton mealybug Phenacoccus solenopsis and its direct and indirect impacts on the endoparasitoid Aenasius arizonensis', 'Shankarganesh K, Ricupero M, Sabtharishi S', 2022, 'Scientific reports', '10.1038/s41598-022-20779-3', 'https://doi.org/10.1038/s41598-022-20779-3', 'https://europepmc.org/articles/PMC9537310?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Phenacoccus solenopsis Tinsley (Hemiptera: Pseudococcidae) an invasive mealybug on cotton is primarily controlled by conventional insecticides. An endoparasitoid Aenasius arizonenesis (Girault) (Hymenoptera: Encyrtidae) is a potential biocontrol agent of this pest. We assessed the susceptibility in field populations of P. solenopsis and A. arizonensis to commonly used insecticides: profenofos, imidacloprid and thiodicarb. Reproductive traits of the parasitoid and Environmental Risk Assessment (ERA) parameters viz., Reduction coefficient, Descriptive analysis, Risk Index (RI), Selectivity ratio and Hazard quotient were measured to assess the direct and indirect effects of these insecticides on the parasitoid. Probit analysis revealed heterogeneity in the insecticide resistance development for both the cotton mealybug and its parasitoid. The field populations of P. solenopsis exhibited resistance to profenofos (18.87-59.86 folds) and thiodicarb (20.07 folds) and susceptibility to imidacloprid. Development of resistance to profenofos was observed in field populations of A. arizonensis. Exposure to lethal doses of imidacloprid and profenofos caused a reduction in parasitization (19-23%) and adult emergence (62-69%) of the parasitoid. Profenofos, thiodicarb and imidacloprid were found to be hazardous, non-selective and harmful to the endoparasitoid, A. arizonensis. There is an urgent need for optimizing insecticide applications for sustainable management of this invasive mealybug in cotton.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa31549b-114d-403a-8af1-a6e5ccc3f816', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Integrated Pest Management Strategies for Asian Citrus Psyllid Diaphorina citri Kuwayama (Hemiptera: Psyllidae) and Huanglongbing in Citrus for Sarawak, East Malaysia, Borneo', 'Leong SS, Leong SCT, Beattie GAC', 2022, 'Insects', '10.3390/insects13100960', 'https://doi.org/10.3390/insects13100960', 'https://europepmc.org/articles/PMC9604280?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'The Asian citrus psyllid (ACP), Diaphorina citri Kuwayama, transmits ‘Candidatus Liberibacter asiaticus’ (CLas), a phloem-limited bacterium associated with the severe Asian form of huanglongbing (HLB), and the most destructive disease of citrus. The pathogen and the psyllid, both of South Asian origin, are now widespread in citrus regions of Asia and the Americas. There is no cure for the disease. Application of synthetic pesticides, in some instances more frequently than fortnightly, to minimise incidence of ACP in citrus orchards, has not prevented inevitable impacts of the disease in regions of Asia where CLas is present. Despite the inevitable spread of the disease, significant progress has been made in Sarawak since the mid-1990s towards effectively implementing integrated pest management (IPM) programs for stemming the impact of the disease and detrimental consequences of over-reliance on synthetic pesticides. Growers are encouraged to plant pathogen-free trees, remove diseased trees, monitor incidence of the psyllid, and to use pesticides judiciously to reduce their detrimental impacts on natural enemies. Knowledge has been enhanced through research on seasonal incidence of the psyllid, use of mineral oils, development of protocols and iodine−starch test kits for detecting infected trees, PCR for confirming the presence of CLas in symptomatic leaves, methods for monitoring incidence the psyllid, and training extension staff and growers. However, major impediments to increasing the average longevity of trees beyond 12 years in well-managed orchards, based on pathogen-free trees, still need to be addressed. These include grower knowledge, marcotting, aggressive marketing of synthetic pesticides, high prices of mineral oils, spray application procedures, and better reliance on natural enemies of the psyllid.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1d1b173d-1d7c-400b-ab81-89f5e72baf13', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Let''s Get Real: Are Wearable Plant Sensors Ready for Crop Monitoring?', 'Hoh D, Suh HK, Kaiser E', 2025, 'ACS sensors', '10.1021/acssensors.5c02510', 'https://doi.org/10.1021/acssensors.5c02510', 'https://europepmc.org/articles/PMC12671000?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'In recent years, the number of publications describing new and exciting developments in wearable plant sensors (WPSs) has skyrocketed. These small, lightweight sensors hold promise to assist precision agriculture and may thus help reduce crop losses, increase resource use efficiency, and automate crop production. However, WPSs are often not adequately tested in environments relevant for crop growth, and the majority of experimental WPS studies reveal a glaring lack of basic knowledge of plant biology. This review aims to bridge the communication gap between WPS developers and the wider plant research community by (1) providing essential physiological and environmental background information for engineers in relation to WPS sensing capabilities, (2) offering a step-by-step guide to conduct sensor tests on plants correctly, and (3) highlighting potential challenges and suggesting WPS applications in the open field, greenhouses, and vertical farming systems. We hope this review facilitates the development of WPSs and guides them to be truly "ready for the world".', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('13d5d485-5a07-4aeb-aa4e-c85c8bd08a18', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Microbial engineering for pesticide degradation: current insights and future directions for sustainable agriculture', 'Srivastava S, Mir RA, Hussain SJ, Mitra S, Srivastava S, Kumar P, Kaur H', 2026, 'Frontiers in microbiology', '10.3389/fmicb.2026.1751932', 'https://doi.org/10.3389/fmicb.2026.1751932', 'https://europepmc.org/articles/PMC12969878?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'Pesticides are synthetic agrochemicals widely used to protect crops from pests and diseases; however, their limited biodegradability and indiscriminate application pose serious risks to non-target organisms, soil fertility, human health, and overall environmental sustainability. Conventional physical and chemical remediation strategies often fall short in restoring contaminated ecosystems, highlighting the urgent need for effective and sustainable pesticide mitigation approaches. In recent years, in situ bioremediation has emerged as a promising, eco-friendly, and cost-effective strategy for pesticide degradation in agricultural soils. Under favourable conditions, microorganisms utilise pesticides as sources of carbon, sulphur, and electrons, facilitating their breakdown through diverse metabolic pathways, with enzymatic degradation playing a central role in chemical transformation. Microbial consortia exhibit enhanced degradation efficiency by leveraging functional diversity and synergistic interactions among their microbial members. For instance, a consortium comprising Azospirillum, Cloacibacterium, and Ochrobacterium achieved 100% degradation of 50 mg L-1 glyphosate within 36 h. Advances in microbiome engineering have further expanded the scope of bioremediation by enabling the targeted manipulation of microbial communities to improve degradation specificity and performance. Notably, the recombined genomes of Psathyrella candolleana and Pseudomonas putida, generated through protoplast fusion, degraded 78.98% of pentachlorophenol in contaminated water. Additionally, engineering the rhizosphere with plant growth-promoting microorganisms, combined with microbial genetic modification, has demonstrated significant potential in enhancing pesticide degradation while simultaneously improving crop growth and productivity. Such integrative approaches represent a sustainable pathway towards resilient agroecosystems. This review synthesises current knowledge on the impacts of pesticides on crop physiology and metabolism, explores conventional and advanced microbe-mediated degradation strategies, and highlights the role of microbial engineering and consortia-based systems. Furthermore, it discusses emerging technologies, environmental and economic benefits, and recent patentable innovations, underscoring their relevance for sustainable agriculture and ecological restoration.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bdeff607-4f1c-4419-ae4d-fe8766b44305', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Mixture effects of thiamethoxam and seven pesticides with different modes of action on honey bees (Aplis mellifera)', 'Li W, Lv L, Wang Y, Zhu YC', 2023, 'Scientific reports', '10.1038/s41598-023-29837-w', 'https://doi.org/10.1038/s41598-023-29837-w', 'https://europepmc.org/articles/PMC9932168?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Even though honey bees in the field are routinely exposed to a complex mixture of many different agrochemicals, few studies have surveyed toxic effects of pesticide mixtures on bees. To elucidate the interactive actions of pesticides on crop pollinators, we determined the individual and joint toxicities of thiamethoxam (THI) and other seven pesticides [dimethoate (DIM), methomyl (MET), zeta-cypermethrin (ZCY), cyfluthrin (CYF), permethrin (PER), esfenvalerate (ESF) and tetraconazole (TET)] to honey bees (Aplis mellifera) with feeding toxicity test. Results from the 7-days toxicity test implied that THI elicited the highest toxicity with a LC50 data of 0.25 (0.20-0.29) μg mL-1, followed by MET and DIM with LC50 data of 4.19 (3.58-4.88) and 5.30 (4.65-6.03) μg mL-1, respectively. By comparison, pyrethroids and TET possessed relatively low toxicities with their LC50 data from the range of 33.78 (29.12-38.39) to 1125 (922.4-1,442) μg mL-1. Among 98 evaluated THI-containing binary to octonary mixtures, 29.59% of combinations exhibited synergistic effects. In contrast, 18.37% of combinations exhibited antagonistic effects on A. mellifera. Moreover, 54.8% pesticide combinations incorporating THI and TET displayed synergistic toxicities to the insects. Our findings emphasized that the coexistence of several pesticides might induce enhanced toxicity to honey bees. Overall, our results afforded worthful toxicological information on the combined actions of neonicotinoids and current-use pesticides on honey bees, which could accelerate farther comprehend on the possible detriments of other pesticide mixtures in agro-environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e7b1b8e0-8067-4007-940d-2528b891d458', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Monitoring and Inference of Behavioral Resistance in Beneficial Insects to Insecticides in Two Pest Control Systems: IPM and Organic', 'José Alfonso Gómez-Guzmán, María Sainz-Pérez, Ramón González-Ruiz', 2022, 'Agronomy', '10.3390/agronomy12020538', 'https://doi.org/10.3390/agronomy12020538', 'https://www.mdpi.com/2073-4395/12/2/538', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Pyrethrins are the most widely used insecticide class in olive groves with organic management. Although there are data sets about insect pests of stored products and human parasites developing resistance to pyrethrins, there is no information on the long-term effect on olive agroecosystems. A field method based on the experimental induction of sublethal effects by means of insecticide application, and the monitoring of the response of insects through post-treatment sampling, has recently been developed. This method has allowed for the detection of populations behaviorally resistant to organophosphates in integrated pest management (IPM) and conventional crops. With the application of a similar methodology, this study aimed to verify the possible reaction of natural enemies in organic crops, using pyrethrins as an inducing insecticide. The study was carried out in 2019 in two olive groves in southern Spain (Jaén, Andalusia), one of them being IPM and the other being an organic production system. The results did not allow for verification of the behavioral resistance in populations of natural enemies of both IPM and organic management against pyrethrins, while against dimethoate, behavioral resistance was verified in IPM management. The possible causes involved in obtaining these results are discussed.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a10f7f9b-a7f2-4675-8966-02c62280fb0e', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Organophosphate Pesticides and Pyrethroids in Farmland of the Pearl River Delta, China: Regional Residue, Distributions and Risks', 'Yao R, Yao S, Ai T, Huang J, Liu Y, Sun J', 2023, 'International journal of environmental research and public health', '10.3390/ijerph20021017', 'https://doi.org/10.3390/ijerph20021017', 'https://europepmc.org/articles/PMC9858657?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'A regional-scale survey was conducted to assess the occurrence, distribution, and risk of two extensively used pesticides (organophosphate pesticides and pyrethroids) in agricultural soils from the Pearl River Delta (PRD), South China. All target organophosphate pesticides (OPPs) and pyrethroids (PYs) were detected in the soil samples and both with a detection rate of 100%. The residues of the sum of six OPPs and the sum of four PYs were in the range of LOD-991 ng/g and 8.76-2810 ng/g, respectively. Dimethoate was the dominant OPPs, and fenpropathrin was the predominant PYs in the soils of the PRD region. With intensive agricultural activities, higher residues of OPPs and PYs in soils were detected closer to the seaside, among which Zhuhai city and Huizhou city suffered more serious combined pesticide pollution. The vertical compositional profiles showed that dimethoate could be detected through each soil layer in the PRD region''s nine cities. The human exposure estimation of OPPs showed insignificant risks to the local population. In contrast, cypermethrin and fenpropathrin showed a potential ecological risk of 2.5% and 3.75% of the sampling sites, respectively. These results can facilitate those commonly used pesticide controls and promote sustainable soil management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('47a2ca08-7c80-4a2b-af62-58d541edf1c8', '7708283d-377a-4b89-98e4-5972c9419831', 'Biology and Management of the Mexican Rice Borer (Lepidoptera: Crambidae) in Rice in the United States', 'Beuzelin JM, Wilson BE, VanWeelden MT, Mészáros A, Way MO, Stout MJ, Reagan TE', 2016, 'Journal of integrated pest management', '10.1093/jipm/pmw006', 'https://doi.org/10.1093/jipm/pmw006', 'https://europepmc.org/articles/PMC5484547?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by-nc', 'The Mexican rice borer, Eoreuma loftini (Dyar), is an invasive pest of rice, Oryza sativa L., in the Gulf Coast region of the United States. This pest also damages sugarcane, Saccharum spp. hybrids; corn, Zea mays L.; and sorghum, Sorghum bicolor (L.) Moench, and feeds on weedy noncrop grasses. Multiple aspects of integrated pest management including use of pheromone traps, manipulation of planting dates, harvest cutting height, stubble management, noncrop host management, soil fertility management, host plant resistance, use of insecticides, and biological control have been studied for Mexican rice borer management. However, the current management strategy in rice primarily relies on the use of chlorantraniliprole insecticide seed treatments. This profile addresses Mexican rice borer biology and management in rice in the United States.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ea235e6d-cf74-41b2-972c-8f6c59849932', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Organophosphate pesticides: a review on classification, synthesis, toxicity, remediation and analysis', 'Saad H, Elfeky SA, El-Gamel NEA, Abo Dena AS', 2025, 'RSC advances', '10.1039/d5ra05552k', 'https://doi.org/10.1039/d5ra05552k', 'https://europepmc.org/articles/PMC12557714?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by-nc', 'Pesticides are toxic organic compounds extensively used in agriculture to control undesirable pests, enhance crop yields and extend shelf life of food crops. The widespread utilization of pesticides is a major contributor to pollution in soil, air and water. A class of artificial chemicals known as organophosphorus pesticides (OPPs) is predominantly employed in public health campaigns, agriculture, pest management, landscaping, and vector control (e.g., mosquito management). Although they were first promoted as safer alternatives for persistent organochlorine pesticides, their effects on human health, bioaccumulation potential, and environmental persistence have caused serious concerns. Due to their high toxicity and low persistence, many agriculturalists regularly use OPPs for various crops such as fruits and vegetables. The regular utilization of pesticides has led to deleterious influences to the ecosystem and neurological disorders to humans. The toxicity of OPPs arises from their capacity to block the enzyme acetylcholinesterase (AChE) at the cholinergic synapses inside the nervous system. The significant rise in the use of OPPs in agriculture necessitates precise assessment of their levels to safeguard food supplies and the ecology. Current studies on the history, classification, chemical characteristics, environmental behavior, health impacts, clinical manifestation and mitigation techniques of OPPs, as well as several approaches for their remediation and assessment are summarized in this review.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('54faccab-2731-4abf-8b2c-77961b783573', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Pesticide pollution in India: Environmental and health risks, and policy challenges', 'Kashyap U, Garg S, Arora P', 2024, 'Toxicology reports', '10.1016/j.toxrep.2024.101801', 'https://doi.org/10.1016/j.toxrep.2024.101801', 'https://europepmc.org/articles/PMC11615616?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Intensive agriculture practices in India to meet the food demand of the increasing population have led to the use of agrochemicals such as pesticides in higher quantities to increase productivity resulting in contamination of the environment. Pesticides control pests, weeds, and diseases in plants, animals, and humans. Despite bans on pesticides such as organochlorides (OC), organophosphate (OP), or synthetic pyrethroids ranging from minimal to excessive, are detected in soil, surface water, and groundwater often exceeding WHO and BIS safety limits. The predominantly found pesticides were DDT, HCH, Endosulfan, malathion, chlorpyrifos, atrazine, endrin, cypermethrin, dichlorvos, etc. Different ranges of pesticides were detected in different states (Kashmir, UP, Tamil Nadu, Kerala, Rajasthan, Haryana, Assam, Madhya Pradesh, etc.) of India, which demonstrate that pesticides can persist in the environment and later can show bioaccumulation in the food chain. The article explores the consequences of this pollution such as biomagnification, bioaccumulation, and risks to human health and ecological integrity. This article also covers the adverse effects of pesticides such as carcinogenic, teratogenic, mutagenic, and endocrine-disrupting properties along with the importance of developing new policies or strengthening the current policies and regulations to monitor the use of pesticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf76a3e4-5515-42c2-a097-3d483b019e39', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Phenotypic- and Genotypic-Resistance Detection for Adaptive Resistance Management in Tetranychus urticae Koch.', 'Deok Ho Kwon, Taek-Jun Kang, Young Ho Kim, Si Hyeock Lee', 2015, 'PLoS ONE', '10.1371/journal.pone.0139934', 'https://doi.org/10.1371/journal.pone.0139934', 'http://europepmc.org/articles/PMC4636269?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'open access (DOAJ)', 'Rapid resistance detection is necessary for the adaptive management of acaricide-resistant populations of Tetranychus urticae. Detection of phenotypic and genotypic resistance was conducted by employing residual contact vial bioassay (RCV) and quantitative sequencing (QS) methods, respectively. RCV was useful for detecting the acaricide resistance levels of T. urticae, particularly for on-site resistance detection; however, it was only applicable for rapid-acting acaricides (12 out of 19 tested acaricides). QS was effective for determining the frequencies of resistance alleles on a population basis, which corresponded to 12 nonsynonymous point mutations associated with target-site resistance to five types of acaricides [organophosphates (monocrotophos, pirimiphos-methyl, dimethoate and chlorpyrifos), pyrethroids (fenpropathrin and bifenthrin), abamectin, bifenazate and etoxazole]. Most field-collected mites exhibited high levels of multiple resistance, as determined by RCV and QS data, suggesting the seriousness of their current acaricide resistance status in rose cultivation areas in Korea. The correlation analyses revealed moderate to high levels of positive relationships between the resistance allele frequencies and the actual resistance levels in only five of the acaricides evaluated, which limits the general application of allele frequency as a direct indicator for estimating actual resistance levels. Nevertheless, the resistance allele frequency data alone allowed for the evaluation of the genetic resistance potential and background of test mite populations. The combined use of RCV and QS provides basic information on resistance levels, which is essential for choosing appropriate acaricides for the management of resistant T. urticae.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('63ddbd9e-2670-4abb-9ec1-935a2d885df7', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Reducing insecticide use in broad-acre grains production: an Australian study', 'Macfadyen S, Hardie DC, Fagan L, Stefanova K, Perry KD, DeGraaf HE, Holloway J, Spafford H', 2014, 'PloS one', '10.1371/journal.pone.0089119', 'https://doi.org/10.1371/journal.pone.0089119', 'https://europepmc.org/articles/PMC3929627?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Prophylactic use of broad-spectrum insecticides is a common feature of broad-acre grains production systems around the world. Efforts to reduce pesticide use in these systems have the potential to deliver environmental benefits to large areas of agricultural land. However, research and extension initiatives aimed at decoupling pest management decisions from the simple act of applying a cheap insecticide have languished. This places farmers in a vulnerable position of high reliance on a few products that may lose their efficacy due to pests developing resistance, or be lost from use due to regulatory changes. The first step towards developing Integrated Pest Management (IPM) strategies involves an increased efficiency of pesticide inputs. Especially challenging is an understanding of when and where an insecticide application can be withheld without risking yield loss. Here, we quantify the effect of different pest management strategies on the abundance of pest and beneficial arthropods, crop damage and yield, across five sites that span the diversity of contexts in which grains crops are grown in southern Australia. Our results show that while greater insecticide use did reduce the abundance of many pests, this was not coupled with higher yields. Feeding damage by arthropod pests was seen in plots with lower insecticide use but this did not translate into yield losses. For canola, we found that plots that used insecticide seed treatments were most likely to deliver a yield benefit; however other insecticides appear to be unnecessary and economically costly. When considering wheat, none of the insecticide inputs provided an economically justifiable yield gain. These results indicate that there are opportunities for Australian grain growers to reduce insecticide inputs without risking yield loss in some seasons. We see this as the critical first step towards developing IPM practices that will be widely adopted across intensive production systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0312dfdd-2f87-476a-936f-cf03e9d48ad8', '7708283d-377a-4b89-98e4-5972c9419831', 'Temporal Changes in Insecticide Susceptibility of Field-Collected Pollen Beetle (Brassicogethes aeneus) Populations in the Czech Republic', 'Tomáš Spitzer, Dominik Bleša', 2026, 'Agriculture', '10.3390/agriculture16202214', 'https://doi.org/10.3390/agriculture16202214', 'https://www.mdpi.com/2077-0472/16/20/2214', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The pollen beetle, Brassicogethes aeneus, is a major pest of winter oilseed rape in Europe, and the development of insecticide resistance remains a key challenge for its management. This study evaluated recent changes in susceptibility of B. aeneus populations to lambda-cyhalothrin, etofenprox, acetamiprid and thiacloprid in the Czech Republic during 2020–2025. Adult beetles were collected annually from 14 agricultural localities and tested using standardized IRAC vial bioassays. Dose–response parameters (LC50 and LC90), relative susceptibility ratios, and mortality at recommended field doses were analyzed using weighted linear mixed-effects models. Susceptibility-related responses differed markedly among insecticides and years. Absolute LC values occupied different numerical ranges among compounds, while mortality at the recommended field dose indicated the highest efficacy for acetamiprid and thiacloprid and the lowest for lambda-cyhalothrin. Several LC- and RSR-based endpoints showed elevated values around 2021–2022, followed by lower values in later years, although the magnitude and direction of temporal changes differed among insecticides. Significant insecticide × year interactions further demonstrated compound-specific temporal trajectories. Locality contributed to variability in LC-based endpoints but explained only a limited proportion of total variance. Long-term monitoring provides valuable information for resistance management and supports the need for diversified insecticide use in oilseed rape pest control.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a1c8dbf1-9253-4fef-b1e6-83efc4f6bcde', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Resistance Development to Abamectin and Cross-Resistance to Multiple Insecticides in Rhynchophorus ferrugineus (Olivier), with Emphasis on Biochemical Analysis', 'A. Ali', 2025, 'Journal of Plant Protection and Pathology', '10.21608/jppp.2025.397947.1356', 'https://doi.org/10.21608/jppp.2025.397947.1356', 'https://jppp.journals.ekb.eg/article_446832_9b02958fa504802605e29becc58a32ce.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'This study investigated the development and mechanisms of resistance to abamectin in Rhynchophorus ferrugineus larvae across eight generations (FS0-FS8) under laboratory selection. Abamectin resistance progressively developed, with the resistance ratio (RR) increasing from 1.06 in the initial field strain (FS0) to 51.18-fold by generation FS8. This significant escalation, coupled with decreasing probit slopes, indicated increased population heterogeneity and robust resistance development. Cross-resistance was also observed against other insecticide classes: hexaflumuron (RR = 105.91-fold), dimethoate (RR = 18.20-fold), and spinetoram (RR = 14.07-fold), highlighting broad-spectrum tolerance. Enzymatic analyses revealed significant up regulation of detoxification enzymes in resistant strains. Esterase activity increased 1.39-fold in RS5 and dramatically 6.09-fold in RS8 compared to the susceptible strain. Glutathione S-transferase (GST) activity increased 3.04-fold in RS5 and 2.84-fold in RS8, while oxidase activity (P450) showed the most consistent increase, reaching 1.84-fold in RS5 and over 3.9-fold in RS8. Acetyl cholinesterase (AChE) activity also increased, suggesting broader physiological adaptations. These findings strongly indicate that metabolic detoxification by esterases, GSTs, and oxidases are a primary mechanism driving abamectin resistance and cross-resistance in R. ferrugineus. Therefore, effective resistance management necessitates the implementation of diverse control strategies, including insecticide rotation, use of synergists, and integrated pest management approaches, to preserve the efficacy of current chemical controls and mitigate further resistance evolution.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f119fccf-0fb3-4497-916a-d7497b9715f4', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Resistance Management for Asian Citrus Psyllid, Diaphorina citri Kuwayama, in Florida', 'Xue Dong Chen, Lukasz L. Stelinski', 2017, 'Insects', '10.3390/insects8030103', 'https://doi.org/10.3390/insects8030103', 'https://www.mdpi.com/2075-4450/8/3/103', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The Asian citrus psyllid, Diaphorina citri Kuwayma, is one of the most important pests in citrus production. The objective of this study was to evaluate D. citri resistance management with three insecticide rotations and compare them with no rotation and an untreated check. The different insecticides (modes of action) tested were: dimethoate, imidacloprid, diflubenzuron, abamectin 3% + thiamethoxam 13.9%, and fenpropathrin. Eggs, nymph, and adult psyllids were counted weekly. Five insecticide applications were made in 2016. Insecticide susceptibility was determined by direct comparison with a laboratory susceptible population and field populations before and after all treatments were applied. Rankings of eggs, nymphs, and adults counted in treated plots were significantly lower than in the untreated control plots after each application. Initially, the resistance ratio (RR50) for each rotation model, as compared with laboratory susceptible strain and the field population before application, was less than 5.76 and 4.31, respectively. However, after five applications with dimethoate, the RR50 using the laboratory and pre-treatment field populations was 42.34 and 34.74, respectively. Our results indicate that effectively rotating modes of action can delay and/or prevent development of insecticide resistance in populations of D. citri.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48f9602b-2309-4475-baa6-23793d09a040', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Review on Performance of Aspergillus and Penicillium Species in Biodegradation of Organochlorine and Organophosphorus Pesticides', 'Matúš P, Littera P, Farkas B, Urík M', 2023, 'Microorganisms', '10.3390/microorganisms11061485', 'https://doi.org/10.3390/microorganisms11061485', 'https://europepmc.org/articles/PMC10305620?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'The use of pesticides in agricultural practices raises concerns considering the toxic effects they generate in the environment; thus, their sustainable application in crop production remains a challenge. One of the frequently addressed issues regarding their application includes the development of a sustainable and ecofriendly approach for their degradation. Since the filamentous fungi can bioremediate various xenobiotics owing to their efficient and versatile enzymatic machinery, this review has addressed their performance in the biodegradation of organochlorine and organophosphorus pesticides. It is focused particularly on fungal strains belonging to the genera Aspergillus and Penicillium, since both are ubiquitous in the environment, and often abundant in soils contaminated with xenobiotics. Most of the recent reviews on microbial biodegradation of pesticides focus primarily on bacteria, and the soil filamentous fungi are mentioned only marginally there. Therefore, in this review, we have attempted to demonstrate and highlight the exceptional potential of aspergilli and penicillia in degrading the organochlorine and organophosphorus pesticides (e.g., endosulfan, lindane, chlorpyrifos, and methyl parathion). These biologically active xenobiotics have been degraded by fungi into various metabolites efficaciously, or these are completely mineralized within a few days. Since they have demonstrated high rates of degradation activity, as well as high tolerance to pesticides, most of the Aspergillus and Penicillium species strains listed in this review are excellent candidates for the remediation of pesticide-contaminated soils.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5279a4fc-f7a2-4dd5-b90c-2da430106b63', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Target-site insensitivity to some acaricides in a field population of Tetranychus urticae Koch (Acari: Tetranychidae) from Egypt', 'Haggag Zein, Abdallah M.  Afifi, Fatma S.  Ali, El-Sayed Shaurub, Mahmoud  Ahmed', 2022, 'Persian Journal of Acarology', '10.22073/pja.v11i2.71694', 'https://doi.org/10.22073/pja.v11i2.71694', 'https://www.biotaxa.org/pja/article/view/71694', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The control of the two-spotted spider mite (TSSM), Tetranychus urticae Koch, a worldwide agricultural pest, is largely dependent on pesticides. However, their efficacy is often encountered by the development of resistance. The present study was conducted to evaluate resistance levels to five pesticides with different modes of action in field population of T. urticae collected from tomato plants grown in open fields at Bernasht village, El-Ayat, Giza Governorate, Egypt, using leaf-dip technique. These pesticides were dimethoate, chlorpyrifos, and ethion (organophosphates), etofenprox (pyrethroids), and abamectin (avermectins). Moreover, the common resistance mutations associated with different groups of pesticides in T. urticae was identified by quantitative sequencing. Very high resistance levels of TSSM to organophosphate pesticides were observed in Eg-Bernasht population. Also, the nucleotide sequences were aligned, megablasted, and compared for similarity with the corresponding genes in different databases such as NCBI nucleotide collection (nr/nt). Of the five common mutations associated with organophosphate and carbamate pesticides, three mutations were identified in Eg-Bernasht population: a threonine residue was replaced by alanine (T280A), glycine was replaced by alanine (G328A), and phenyl-alanine was replaced by tryptophan (F331W). One of the three common mutations associated with pyrethroid pesticides, alanine was replaced by aspartic acid (A1215D). Further two substitutions of amino acids, leucine to valine (L988V) and aspartic acid to glutamic acid (D1569E) were also identified. The common mutations associated with the target site of avermectins (glutamate-gated chloride channels, GluCl1, GluCl3) and etoxazole pesticide (chitin synthase, CHS1) were absent in Eg-Bernasht population. Also, with glutamate-gated chloride channel genes in one clone of Eg-Bernasht population, two substitutions of alanine to leucine (A308L) and valine to leucine (V309L) were identified. The results obtained from the current investigation indicated that four common mutations associated with pesticide resistance were present in the field population of T. urticae. These mutations were T280A, G328A, and F331W in the acetylcholinesterase (AChE) gene and A1215D in the voltage-gated sodium channel (VGSC) gene. An improved understanding of acaricides resistance in TSSM is important to maintain the efficacy of these chemicals for the control of this pest in tomato and other crops. We recommend focusing on the use of integrated pest management programs and pesticide alternatively to manage resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f174b8d6-1a41-43e7-95db-9c440cb6ca24', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'Wheat fertilization affects oviposition preference of wheat midge, Sitodiplosis mosellana (Géhin) (Diptera: Cecidomyiidae)', 'Weeraddana CS, Wijesundara R, Schmidt SA, de la Mata AP, McCartney C, Harynuk JJ, Costamagna AC', 2026, 'Pest management science', '10.1002/ps.70756', 'https://doi.org/10.1002/ps.70756', 'https://europepmc.org/articles/PMC13240697?pdf=render', NULL, NULL, 9, NULL, 'prairies', 4, 'cc by-nc-nd', 'BackgroundIn Canada, the orange wheat blossom midge (hereafter called wheat midge), Sitodiplosis mosellana (Géhin) (Diptera: Cecidomyiidae), causes millions of dollars of damage to wheat crops every year. Host plant nutrition directly or indirectly influences insect oviposition owing to their higher food quality. We tested the effect of fertilizer rates (0.5, 1.5, 2.5 g per pot) on plant growth parameters, tissue nitrogen (N) content, protein content, wheat midge oviposition, and larval performance using a susceptible wheat cultivar, ''Roblin''. We also examined the volatile organic compound (VOC) profile in plants grown under different fertilization regimes using thermal desorption comprehensive 2D gas chromatography time-of-flight mass spectrometry (TD-GC × GC-TOFMS) to test whether VOCs are influenced by plant fertilization.ResultsHigher fertilization rates increased plant fresh weight and number of spikes per plant. However, the highest percentage of nitrogen and protein content were observed in the moderate fertilization treatment, followed by the high and low treatments. Wheat midge laid proportionally more eggs in the moderate than in the high fertilization treatments, with intermediate numbers of eggs observed in the low fertilization treatment, in choice oviposition tests. Fertilizer treatments did not affect the total number of wheat midge eggs and larvae, and the average larval weight in no-choice tests. The VOC profile of plants in the moderate and high fertilization treatments differed from that of the low fertilization treatment.ConclusionsPlant fertilization increases plant growth, nitrogen, and protein levels, alters the VOC profile, and affects female wheat midge oviposition preference. Increased egg-laying may be affected by the observed changes in the VOC profile, which warrants further investigation comparing the effects of fertilization on the VOC profiles of susceptible and oviposition-deterrent wheat varieties. Under no-choice conditions we did not detect fertilization effects on wheat midge oviposition or early development, but future studies should focus on potential effects on adults and their reproduction. These findings provide a deeper understanding of how plant nutrients influence wheat midge-host plant interactions. © 2026 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1572bbd0-7422-442e-ba02-553d4129c536', '782c7b3e-ee8e-42de-871d-47b4efcecde0', 'With or Without You?-A Critical Review on Pesticides in Food', 'Lazarević-Pašti T, Milanković V, Tasić T, Petrović S, Leskovac A', 2025, 'Foods (Basel, Switzerland)', '10.3390/foods14071128', 'https://doi.org/10.3390/foods14071128', 'https://europepmc.org/articles/PMC11988313?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Pesticides are very important in modern agriculture, protecting crops against pests and diseases to ensure food safety. However, the use of pesticides in food production has raised significant concerns regarding their potential impacts on human health and the environment. This review provides comprehensive insights into the current status, future projections, and debates surrounding pesticides in food. Beginning with a historical overview of pesticide use in agriculture, the types of pesticides commonly used and the presence of their residues in food commodities are explored. The health and environmental impacts associated with pesticide exposure are examined, including both human health effects and ecological consequences. An analysis of the regulatory frameworks governing pesticide management at international and national levels is presented, along with emerging trends and future projections in pesticide technologies and agricultural practices. Strategies for mitigating pesticide risks, such as Integrated Pest Management and alternative approaches to conventional pesticide use, are discussed. Finally, the controversies surrounding pesticide use, including public perception, consumer concerns, and policy debates, are addressed. Through a critical examination of these issues, this review underscores a growing need for innovative solutions that can effectively balance agricultural demands with human health and the environment, enabling more resilient and sustainable food production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('26c16799-e59f-41bc-a23e-cade4d3a0fc8', '699c7577-eb88-4579-895f-df444934cf8f', 'Identification of Antibiotics in Surface-Groundwater. A Tool towards the Ecopharmacovigilance Approach: A Portuguese Case-Study', 'Viana P, Meisel L, Lopes A, de Jesus R, Sarmento G, Duarte S, Sepodes B, Fernandes A', 2021, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics10080888', 'https://doi.org/10.3390/antibiotics10080888', 'https://europepmc.org/articles/PMC8388677?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Environmental monitoring, particularly of water, is crucial to screen and preselect potential hazardous substances for policy guidance and risk minimisation strategies. In Portugal, extensive data are missing. This work aimed to perform a qualitative survey of antibiotics in surface- groundwater, reflecting demographic, spatial, consumption and drug profiles during an observational period of three years. A passive sampling technique (POCIS) and high-resolution chromatographic system were used to monitor and analyse the antibiotics. The most frequently detected antibiotics were enrofloxacin/ciprofloxacin and tetracycline in surface-groundwater, while clarithromycin/erythromycin and sulfamethoxazole were identified only in surface water. The detection of enzyme inhibitors (e.g., tazobactam/cilastatin) used exclusively in hospitals and abacavir, a specific human medicine was also noteworthy. North (Guimarães, Santo Tirso and Porto) and South (Faro, Olhão and Portimão) Portugal were the regions with the most significant frequency of substances in surface water. The relatively higher detection downstream of the effluent discharge points compared with a low detection upstream could be attributed to a low efficiency in urban wastewater treatment plants and an increased agricultural pressure. This screening approach is essential to identify substances in order to perform future quantitative risk assessment and establishing water quality standards. The greatest challenge of this survey data is to promote an ecopharmacovigilance framework, implement measures to avoid misuse/overuse of antibiotics and slow down emission and antibiotic resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d1cb64bf-5df1-4a11-984e-e2b0ad3fe1a8', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'A World of Gorse: Persistence of Ulex europaeus in Managed Landscapes', 'Broadfield N, McHenry MT', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8110523', 'https://doi.org/10.3390/plants8110523', 'https://europepmc.org/articles/PMC6918442?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Gorse (Ulex europeus L.) is a woody legume and invasive woody weed that has been introduced to temperate pastoral landscapes worldwide. Despite the apparent cosmopolitan distribution of gorse across much of the temperate agroecological landscapes of the world, research and practice pertaining to the management of gorse has been largely constrained to single-treatments, regions, or timeframes. Gorse eradication has been widely attempted, with limited success. Using the PRISMA (preferred reporting items for systematic reviews and meta-analysis) method and a quasi-metanalytical approach, we reviewed the seminal ~299 papers pertaining to gorse management. We identified (i) the ecological characteristics of the species that predispose gorse to behaving invasively, and (ii) the success of management actions (from a plant ecological life history perspective) in reducing weed vigour and impact. A broad ecological niche, high reproductive output, propagule persistence, and low vulnerability to pests allow for rapid landscape exploitation by gorse throughout much the world. Additionally, there are differences in flowering duration and season in the northern and southern hemisphere that make gorse particularly pernicious in the latter, as gorse flowers twice per year. The implications of these life history stages and resistance to environmental sieves after establishment are that activity and efficacy of control is more likely to be favourable in juvenile stages. Common approaches to gorse control, including herbicides, biological controls, and fire have not been ubiquitously successful, and may in fact target the very site resources-sward cover, soil stability, hydrological balance-that, when degraded, facilitate gorse invasion. Ongoing seedling regeneration presents difficulties if eradication is a goal, but facilitated competition may reduce costs via natural suppression. Mechanical methods of gorse removal, though highly successful, induce chronic soil erosion and land degradation and should hence be used sparingly.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f817d44c-d86e-475c-85bf-b6a7ef5fef38', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Control of Erigeron bonariensis with Thymbra capitata, Mentha piperita, Eucalyptus camaldulensis, and Santolina chamaecyparissus Essential Oils', 'Verdeguer M, Castañeda LG, Torres-Pagan N, Llorens-Molina JA, Carrubba A', 2020, 'Molecules (Basel, Switzerland)', '10.3390/molecules25030562', 'https://doi.org/10.3390/molecules25030562', 'https://europepmc.org/articles/PMC7037304?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'In the search of sustainable and environmentally friendly methods for weed control, there is increasing interest in essential oils (EOs) as an approach to reduce synthetic herbicide use. The phytotoxicity of Thymbra capitata, Mentha piperita, Eucalyptus camaldulensis, and Santolina chamaecyparissus EOs against the noxious weed Erigeron bonariensis were evaluated in pre- and post-emergence assays in greenhouse conditions. The EOs were applied at 2, 4, and 8 µL/mL, with Fitoil used as emulsifier. In post-emergence, two ways of application were tested, irrigation and spraying. Several germination parameters (germination %, mean germination time, and synchrony of the germination process) were evaluated in pre-emergence tests, and the phytotoxicity level was assessed in post-emergence. In pre-emergence, all EOs significantly reduced seed germination as compared to the controls, ranking: T. capitata > E. camaldulensis > S. chamaecyparissus > M. piperita. The effectiveness of all EOs varied with the tested dose, always following the rank 2 μL T. capitata EO showing full effectiveness even at the lowest dose. In post-emergence, T. capitata was the most effective EO, inducing a rather complete inhibition of plantlet growth at the highest two doses. These EOs demonstrated to have good potential for the formulation of natural herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('39d7c3e3-b3c3-4289-8237-55c4d7a76194', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Diquat Induces Cell Death and dopamine Neuron Loss via Reactive Oxygen Species Generation in Caenorhabditis elegans', 'Wang B, Yin Z, Liu J, Tang C, Zhang Y, Wang L, Li H, Luo Y', 2025, 'Environmental science & technology', '10.1021/acs.est.4c07783', 'https://doi.org/10.1021/acs.est.4c07783', 'https://europepmc.org/articles/PMC11740995?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'Diquat (DQ), a contact herbicide extensively utilized in both agricultural and nonagricultural domains, exhibits a high correlation with neuronal disorders. Nevertheless, the toxicity and underlying mechanisms associated with exposure to environmental concentrations of DQ remain ambiguous. Here, we report dose-dependent cellular neurotoxicity of DQ in Caenorhabditis elegans. First, DQ significantly compromised the development and brood size of worms, shortened the lifespan, and caused epidermal abnormalities. An unbiased transcriptomic analysis disclosed several pathways related to cell death and peroxisome homeostasis underlying this organismal-level toxicity. Moreover, exposure of DQ to C. elegans led to a notable increase of embryonic cell death. Concurrently, DQ exposure specifically caused the loss of dopamine neurons but not two other types of neurons in adulthood, which is in accordance with DQ-induced muscle-related defects such as pharyngeal pumping, body bends, and head thrashes. Mechanistically, DQ exposure induces the generation of reactive oxygen species (ROS) and enhances glutathione-related ROS scavenging pathway. Protein levels and activities of mitochondrial electron transport chain complexes were specifically impaired in the DQ-treated worms. Collectively, this study suggests an ROS-mediated cell death pathway involving the neuronal and behavioral toxicity of DQ, which offers a novel mitochondria-related perspective to elucidate the general toxicity caused by a widely distributed herbicide, DQ, at near-environment concentrations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('02e9ca86-3e6a-4cc1-9310-b6127a8c0712', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Effect of Diquat on gut health: molecular mechanisms, toxic effects, and protective strategies', 'He C, Cai G, Jia Y, Jiang R, Wei X, Tao N', 2025, 'Frontiers in pharmacology', '10.3389/fphar.2025.1562182', 'https://doi.org/10.3389/fphar.2025.1562182', 'https://europepmc.org/articles/PMC12104255?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Diquat is a widely used bipyridyl herbicide that is extensively applied in agricultural production and water management due to its high efficacy in weed control. However, its environmental persistence and the toxic effects it induces have raised widespread concern. Studies show that Diquat primarily enters the body through the digestive tract, leading to poisoning. The core mechanism of its toxicity involves reactive oxygen species (ROS)-induced oxidative stress, which not only directly damages the intestinal barrier function but also exacerbates inflammation and systemic toxicity by disrupting the balance of the gut microbiota and the normal production of metabolic products. This review systematically summarizes the physicochemical properties of Diquat, with a focus on analyzing the mechanisms by which it damages the gut tissue structure, barrier function, and microbiota after digestive tract exposure. The aim is to provide theoretical support for a deeper understanding of Diquat''s toxic mechanisms and its digestive tract-centered toxic characteristics, laying a scientific foundation for the development of effective interventions and protective strategies against its toxicity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ea3eec2-c38b-4030-a071-0ed206262cea', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Efficacy of the herbicide GF-2581 (penoxsulam + florasulam) against broadleaf weeds in olives', 'I.S. Travlos, M. Lysandrou, V. Apostolidis', 2014, 'Plant, Soil and Environment', '10.17221/710/2014-PSE', 'https://doi.org/10.17221/710/2014-PSE', 'https://pse.agriculturejournals.cz/artkey/pse-201412-0009_efficacy-of-the-herbicide-gf-2581-penoxsulam-florasulam-against-broadleaf-weeds-in-olives.php', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'Effective weed control in perennial crops is a challenge due to the limited availability of registered herbicides and herbicide resistance. The objective of the study was to evaluate the efficacy of the herbicide GF-2581 (penoxsulam + florasulam) on broadleaf weeds in comparison with other commonly used herbicides. Field trials were conducted in olives, in Etoloakarnania (Agrinio region) for two years (2012 and 2013). Efficacy assessments were made at 30, 60, 90 and 120 days after treatment. The GF-2581 formulation provided excellent control of a broad spectrum of broadleaf weed species. The long-term control of Sonchus oleraceous, Conyza canadensis and Stellaria media, provided by GF-2581 during the growing season was significantly greater than that using flumioxazin. When combined with glyphosate or diquat, the level of control of these three weeds was improved. The GF-2581 agent applied pre-emergence followed 14 days later by application of glyphosate provided 100% control in 2012. Lower efficacy levels were observed in 2013 and may have been the result of higher rainfall when compared to 2012. GF-2581 is an effective herbicide product to control broadleaf weeds, as a part of integrated weed control management strategies in olives.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e98aa53e-6e26-4b9b-9737-0aec19affdf4', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Herbicide-related health risks: key mechanisms and a guide to mitigation strategies', 'Hongoeb J, Tantimongcolwat T, Ayimbila F, Ruankham W, Phopin K', 2025, 'Journal of occupational medicine and toxicology (London, England)', '10.1186/s12995-025-00448-7', 'https://doi.org/10.1186/s12995-025-00448-7', 'https://europepmc.org/articles/PMC11863480?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundHerbicides are a group of substances used to control undesired vegetation in both agricultural and non-agricultural settings. They are recorded as the most consumed class among other pesticides, reaching nearly two million tons worldwide. Despite their effectiveness in weed control, the extensive utilization of herbicides has raised concerns regarding adverse effects on human health. However, comprehensive reviews addressing herbicide-related human health risks remain limited. This work aims to compile scientific evidence and possible underlying mechanisms to emphasize the hazards that need to be acknowledged, as well as to explore novel strategies for minimizing the impact on human health.MethodScientific data on herbicide-related human health risks, including human-related data and non-human experimental research, were retrieved from databases such as PubMed, Scopus, and Google Scholar. Pre-determined eligibility criteria were applied to select the final studies.ResultA narrative summary of evidence-based human incidence and laboratory experiments is presented to organize and highlight key findings. This indicates the life-threatening nature of herbicide exposure in humans, ranging from acute toxicity to the development of chronic diseases at any stage of life.ConclusionHerbicidal chemicals can harm individuals through various pathways, especially by inducing oxidative stress or directly disrupting molecular and cellular processes. Despite some conflicting findings, effective mitigation strategies are urgently needed to promote a safer society and protect human well-being.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d2224d66-6754-4ad0-ae5f-4f87f225778b', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Evaluation of water hyacinth (Eichhornia crassipes) response to herbicides using unmanned aerial system imagery', 'Amber E. Riner, Jonathan S. Glueckert, Corrina J. Vuillequez, James K. Leary, Benjamin P. Sperry, Gregory E. Macdonald', 2025, 'Weed Technology', '10.1017/wet.2025.28', 'https://doi.org/10.1017/wet.2025.28', 'https://www.cambridge.org/core/product/identifier/S0890037X25000284/type/journal_article', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'Water hyacinth is a highly invasive aquatic species in the southern United States that requires intensive management through frequent herbicide applications. Quantifying management success in large-scale operations is challenging with traditional survey methods that rely on boat-based teams and can be time-consuming and labor-intensive. In contrast, an unmanned aerial system (UAS) allows a single operator to survey a waterbody more efficiently and rapidly, enhancing both coverage and data collection. Therefore, the objective of this research was to develop remote sensing techniques to assess herbicide efficacy for water hyacinth control in an outdoor mesocosm study. Experiments were conducted in spring and summer 2023 to compare and correlate data from visual evaluations of herbicide efficacy against nine vegetation indices (VIs) derived from UAS-based red-green-blue imagery. Penoxsulam, carfentrazone, diquat, 2,4-D, florpyrauxifen-benzyl, and glyphosate were applied at two rates, and experimental units were evaluated for 6 wk. The carotenoid reflectance index (CRI) had the highest Spearman’s correlation coefficient with visually evaluated efficacy for 2,4-D, diquat, and florpyrauxifen benzyl (> −0.77). The visible atmospherically resistance index (VARI) had the highest correlation with carfentrazone and penoxsulam treatments (> −0.70), and the excess greenness minus redness index had the highest correlation for glyphosate treatments (> −0.83). CRI had the highest correlation coefficient with the most herbicide treatments, and it was the only VI tested that did not include the red band. These VIs were satisfactory predictors of mid-range visually evaluated herbicide efficacy values but were poorly correlated with extremely low and high values, corresponding to nontreated and necrotic plants. Future research should focus on applying findings to real-world (nonexperimental) field conditions and testing imagery with spectral bands beyond the visible range.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('640be469-41fc-4248-beba-4e479c745070', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Exposome and Metabolome Analysis of Sugarcane Workers Reveals Predictors of Kidney Injury', 'Stem AD, Brindley S, Rogers KL, Salih A, Roncal-Jimenez CA, Johnson RJ, Newman LS, Butler-Dawson J', 2024, 'Kidney international reports', '10.1016/j.ekir.2024.01.060', 'https://doi.org/10.1016/j.ekir.2024.01.060', 'https://europepmc.org/articles/PMC11069010?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'IntroductionSugarcane workers are exposed to potentially hazardous agrochemicals, including pesticides, heavy metals, and silica. Such occupational exposures present health risks and have been implicated in a high rate of kidney disease seen in these workers.MethodsTo investigate potential biomarkers and mechanisms that could explain chronic kidney disease (CKD) among this worker population, paired urine samples were collected from sugarcane cutters at the beginning and end of a harvest season in Guatemala. Workers were then separated into 2 groups, namely those with or without kidney function decline (KFD) across the harvest season. Urine samples from these 2 groups underwent elemental analysis and untargeted metabolomics.ResultsUrine profiles demonstrated increases in silicon, certain pesticides, and phosphorus levels in all workers, whereas heavy metals remained low. The KFD group had a reduction in estimated glomerular filtration rate (eGFR) across the harvest season; however, kidney injury marker 1 did not significantly change. Cross-harvest metabolomic analysis found trends of fatty acid accumulation, perturbed amino acid metabolism, presence of pesticides, and other known signs of impaired kidney function.ConclusionSilica and certain pesticides were significantly elevated in the urine of sugarcane workers with or without KFD. Future work should determine whether long-term occupational exposure to silica and pesticides across multiple seasons contributes to CKD in these workers. Overall, these results confirmed that multiple exposures are occurring in sugarcane workers and may provide insight into early warning signs of kidney injury and may help explain the increased incidence of CKD among agricultural workers.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a1c1d918-34bb-4ee6-93f2-321359617161', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Frequently asked questions about chlorophyll fluorescence, the sequel', 'Kalaji HM, Schansker G, Brestic M, Brestic M, Bussotti F, Calatayud A, Ferroni L, Goltsev V', 2017, 'Photosynthesis research', '10.1007/s11120-016-0318-y', 'https://doi.org/10.1007/s11120-016-0318-y', 'https://europepmc.org/articles/PMC5357263?pdf=render', NULL, NULL, 54, NULL, 'other', 1, 'cc by', 'Using chlorophyll (Chl) a fluorescence many aspects of the photosynthetic apparatus can be studied, both in vitro and, noninvasively, in vivo. Complementary techniques can help to interpret changes in the Chl a fluorescence kinetics. Kalaji et al. (Photosynth Res 122:121-158, 2014a) addressed several questions about instruments, methods and applications based on Chl a fluorescence. Here, additional Chl a fluorescence-related topics are discussed again in a question and answer format. Examples are the effect of connectivity on photochemical quenching, the correction of F V /F M values for PSI fluorescence, the energy partitioning concept, the interpretation of the complementary area, probing the donor side of PSII, the assignment of bands of 77 K fluorescence emission spectra to fluorescence emitters, the relationship between prompt and delayed fluorescence, potential problems when sampling tree canopies, the use of fluorescence parameters in QTL studies, the use of Chl a fluorescence in biosensor applications and the application of neural network approaches for the analysis of fluorescence measurements. The answers draw on knowledge from different Chl a fluorescence analysis domains, yielding in several cases new insights.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('57f7b63a-6710-4c3b-a778-d5b1f1de0d98', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Herbicide resistance management via fraise mowing', 'James T. Brosnan, Gregory K. Breeden', 2026, 'Weed Technology', '10.1017/wet.2026.10122', 'https://doi.org/10.1017/wet.2026.10122', 'https://www.cambridge.org/core/product/identifier/S0890037X26101225/type/journal_article', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'Fraise mowing is a turfgrass cultivation practice used to mechanically control annual bluegrass via a combination of physical removal and seedbank depletion. Research was conducted to determine whether fraise mowing could restore the efficacy of annual bluegrass control herbicides lost due to resistance. Herbicide treatments were applied to plots within separate fraise-mowed and non-fraise–mowed experiments conducted on a hybrid bermudagrass golf course fairway infested with annual bluegrass that became resistant to herbicides from Groups 2, 3, 5, and 29. Fraise mowing was performed on June 18, 2024, and June 23, 2025, to a 1.3-cm depth. Herbicides tested included diquat dibromide, flumioxazin, foramsulfuron, glufosinate, glyphosate, indaziflam, metribuzin, oxadiazon, prodiamine, pronamide, simazine, tetflupyrolimet, and thiencarbazone + foramsulfuron + halosulfuron. Herbicides were applied according to label directions at preemergence, early postemergence, mid-postemergence, or late postemergence timings during 2024 to 2026. In the fraise-mowed experiment, indaziflam, tetflupyrolimet, prodiamine, pronamide, simazine, and metribuzin provided 86% to 100% control of annual bluegrass by 12 wk after initial treatment (WAIT) and 61% to 88% by 24 WAIT. Without fraise mowing, these herbicides provided ≤53% and ≤73% control at 24 WAIT in 2024 and 2025, respectively. Increased efficacy may be related to a reduction in the annual bluegrass seedbank from fraise mowing because the practice reduced plant counts in nontreated check plots by 75% to 88% each year. Applications of diquat dibromide and flumioxazin mid-postemergence provided 18% to 34% control of annual bluegrass at 6 WAIT in the fraise-mowed experiment; whereas these same herbicides provided ≤10% control when they were applied to non-fraise–mowed hybrid bermudagrass. Mid-postemergence applications of glufosinate and glyphosate and late postemergence applications of foramsulfuron and thiencarbazone + foramsulfuron + halosulfuron performed similarly in both experiments. Restored use of residual herbicides lost due to resistance may remove barriers to adopting the practice of fraise mowing for annual bluegrass control.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60eef7cd-ecd6-4379-b06b-4c21f7ca647f', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Natural Products as Dietary Agents for the Prevention and Mitigation of Oxidative Damage and Inflammation in the Intestinal Barrier', 'Martins-Gomes C, Nunes FM, Silva AM', 2024, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox13010065', 'https://doi.org/10.3390/antiox13010065', 'https://europepmc.org/articles/PMC10812469?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'Food intake is a basic need to sustain life, but foodborne pathogens and food-related xenobiotics are also the main health concerns regarding intestinal barrier homeostasis. With a predominant role in the well-being of the entire human body, intestinal barrier homeostasis is strictly regulated by epithelial and immune cells. These cells are also the main intervenients in oxidative stress and inflammation-related diseases in the intestinal tract, triggered, for example, by genetic/epigenetic factors, food additives, pesticides, drugs, pathogens, and their metabolites. Nevertheless, the human diet can also be seen as a solution for the problem, mainly via the inclusion of functional foods or nutraceuticals that may act as antioxidant/anti-inflammatory agents to prevent and mitigate acute and chronic oxidative damage and inflammation. A literature analysis of recent advances in this topic highlights the significant role of Nrf2 (nuclear factor erythroid 2-related factor 2) and NF-kB (nuclear factor kappa-light-chain-enhancer of activated B cells) pathways in these biological processes, with many natural products and phytochemicals targeting endogenous antioxidant systems and cytokine production and balance. In this review, we summarized and discussed studies using in vitro and in vivo models of the intestinal tract used to reproduce oxidative damage and inflammatory events, as well as the role of natural products as modulators of Nrf2 and NK-kB pathways.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ec4dc56-31e5-439d-9c07-0d18fb7f0bf8', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Pesticides and parkinson''s disease: causal relationship at the population and individual level?', 'Höllerhage M', 2026, 'Journal of neural transmission (Vienna, Austria : 1996)', '10.1007/s00702-025-03054-3', 'https://doi.org/10.1007/s00702-025-03054-3', 'https://europepmc.org/articles/PMC12855454?pdf=render', NULL, NULL, 36, NULL, 'other', 1, 'cc by', 'Pesticide exposure has been associated with an increased risk of Parkinson''s disease (PD). As a result, PD has been recognized as an occupational disease among agricultural workers in France for over a decade. In March 2024, a similar recommendation for recognition was issued in Germany. Pesticides encompass a wide range of functional classes and chemical groups, making it challenging-evaluate their specific effects. Numerous epidemiological studies, including cohort and case-control studies, have investigated the association between pesticide exposure and PD risk. While some report statistically significant associations, others yield inconclusive results, partly due-the inherent difficulties in accurately quantifying pesticide exposure and overlap in the use of different pesticides. In addition, a large body of experimental research has examined the neurotoxicity of various pesticides on dopaminergic neurons using both in vitro and in vivo models of PD. This review summarizes the findings from epidemiological and experimental studies and discusses the current evidence linking pesticide exposure-risk for Parkinson''s disease.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c94b8ef4-99f3-449e-827b-46b224104b91', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Pesticides'' mode of action on aquatic life', 'Saha R, Dutta SM', 2024, 'Toxicology reports', '10.1016/j.toxrep.2024.101780', 'https://doi.org/10.1016/j.toxrep.2024.101780', 'https://europepmc.org/articles/PMC11570982?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by-nc-nd', 'Pesticides are chemical compounds or mixtures of hazardous substances that are used by humans to increase and protect crops from pests and control disease-carrying insects. Because of its wide use, it may be poisonous to helpful and non-targeting plants and animals. Spraying or spreading pesticides over whole fields of crops can cause runoff to transfer the chemicals into aquatic ecosystems, and wind can carry the chemicals to nearby grazing regions, farms, and populated areas, where they can endanger other animals. This review summarises recent studies on pesticide combination toxicity to aquatic biota and approaches used to anticipate toxic effects. When toxicants harm economically significant organisms that humans consume, the negative effects become more severe and can cause stress conditions, vital organ damage, biochemical damage as well as even the death of living things in both terrestrial and aquatic environments. Pesticides are highly toxic to aquatic organisms such as snails, fish, etc. By producing excessive ROS, pesticides can cause severe biochemical and histological changes as well as neurological dysfunction in freshwater organisms. So, it is therefore easy to understand the attention of the public on these substances. Because aquatic organisms play a major part in the food chain. However, through the biomagnification process, the quantity of pesticides increases in the higher organisms through the food chain, which results play a terrific role in the higher organism''s body. So, it''s essential to comprehend the way that insecticides work on aquatic organisms. In this review article, we are focusing on the way that pesticides work, which will help in the system of biomonitoring.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe94fd95-d426-4938-9fd4-5eac746d3080', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Malting barley', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4360611', 'https://open.alberta.ca/dataset/7b3fa30b-f731-48ba-84be-87914a28580d/resource/dcc8978a-7882-4c91-add5-a68a92e8a10a/download/2009-114-20-2.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Provides guidance for the successful production of malting barley, including choosing a variety, selecting a field, seeding, weed and disease control, harvesting, and preparing a representative sample of the harvested crop.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4429f6c4-9e30-446a-a84d-2f244b52bb14', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Potato Production in Northwestern Europe (Germany, France, the Netherlands, United Kingdom, Belgium): Characteristics, Issues, Challenges and Opportunities', 'Goffart JP, Haverkort A, Storey M, Haase N, Martin M, Lebrun P, Ryckmans D, Florins D', 2022, 'Potato research', '10.1007/s11540-021-09535-8', 'https://doi.org/10.1007/s11540-021-09535-8', 'https://europepmc.org/articles/PMC8795733?pdf=render', NULL, NULL, 45, NULL, 'other', 1, 'cc by', 'In Northwestern Europe, Germany, France, the Netherlands, the UK and Belgium constitute the biggest five potato producers, with total potato crop production around 60% of EU-28 production before Brexit. Soil and climate conditions are highly favourable for potato growth in this region. Production is under driving forces of (i) the potato processing industry, particularly in Belgium; (ii) the innovation for fresh potato in the UK, France and Germany; (iii) the leadership of Germany and the Netherlands for starch potato; and (iv) the dominance of the Netherlands for seed production. Based on an industrial agri-food production system, the region has the highest potato yield levels worldwide and developed relevant trade networks for export of seed, fresh and processed potato products in and outside Europe. Conventional and intensive potato production is widespread over the region, whilst organic production started to develop in Germany and France. Whether the coming decades will be as successful as the last ones for sustainable potato production will depend on how the sector and stakeholders of the whole potato value-chain will overcome new issues and challenges. These are mainly soil quality and health conservation, consequences of climate change, increasing bans on the use of plant protection products, tightening environmental standards, food waste reduction and increasing trade tensions hampering the flow of potatoes around the world. After a detailed description of the potato production in the region, this paper contains a SWOT analysis aiming to identify potential solutions to overcome environmental, technical, economic, political and societal issues in the region for sustainable potato production in the coming years and decades.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e7ba009-0145-4c6c-94c1-819bf3d2d5e6', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Research progress on anti-stress nutrition strategies in swine', 'Wang L, Wang C, Peng Y, Zhang Y, Liu Y, Liu Y, Yin Y', 2023, 'Animal nutrition (Zhongguo xu mu shou yi xue hui)', '10.1016/j.aninu.2023.03.006', 'https://doi.org/10.1016/j.aninu.2023.03.006', 'https://europepmc.org/articles/PMC10192683?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by-nc-nd', 'In swine production, stress is a common encounter that leads to serious bacterial infection and adverse effects on growth performance. Though antibiotics have been frequently used to control pathogen spread, sustained negative impacts from antibiotics have been found to affect intestinal integrity and the immune system. Multiple nutritional strategies have shown potential to counteract stress and replace antibiotics, including functional amino acids, low protein diet, plant extracts, organic acids, prebiotics, probiotics, minerals and vitamins. These additives relieve the stress response in swine via different mechanisms and signal transduction pathways. Based on the overview of signaling pathways and stress models, this review highlights the potential of nutritional strategies in swine for preventing or treating stress-related health problems. For wider application in the pig industry, the dose ranges measured require for further validation in different physiological contexts and formulations. In the future, microfluid devices and novel stress models are expected to enhance the efficiency of screening for new anti-stress candidates.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc95891e-696a-4217-b467-a596910fad85', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'The Role of Quercetin, a Flavonoid in the Management of Pathogenesis Through Regulation of Oxidative Stress, Inflammation, and Biological Activities', 'Alharbi HOA, Alshebremi M, Babiker AY, Rahmani AH', 2025, 'Biomolecules', '10.3390/biom15010151', 'https://doi.org/10.3390/biom15010151', 'https://europepmc.org/articles/PMC11763763?pdf=render', NULL, NULL, 56, NULL, 'other', 1, 'cc by', 'Quercetin, a flavonoid found in vegetables and fruits, has been extensively studied for its health benefits and disease management. Its role in the prevention of various pathogenesis has been well-documented, primarily through its ability to inhibit oxidative stress, inflammation, and enhance the endogenous antioxidant defense mechanisms. Electronic databases such as Google Scholar, Scopus, PubMed, Medline, and Web of Science were searched for information regarding quercetin and its role in various pathogeneses. The included literature comprised experimental studies, randomized controlled trials, and epidemiological studies related to quercetin, while editorials, case analyses, theses, and letters were excluded. It has been reported to have a wide range of health benefits including hepatoprotective, antidiabetic, anti-obesity, neuroprotective, cardioprotective, wound healing, antimicrobial, and immunomodulatory effects, achieved through the modulation of various biological activities. Additionally, numerous in vitro and in vivo studies have shown that quercetin''s efficacies in cancer management involve inhibiting cell signaling pathways, such as inflammation, cell cycle, and angiogenesis, activating cell signaling pathways including tumor suppressor genes, and inducing apoptosis. This review aims to provide a comprehensive understanding of the health benefits of quercetin in various pathogeneses. Additionally, this review outlines the sources of quercetin, nanoformulations, and its applications in health management, along with key findings from important clinical trial studies. Limited clinical data regarding quercetin''s safety and mechanism of action are available. It is important to conduct more clinical trials to gain a deeper understanding of the disease-preventive potential, mechanisms of action, safety, and optimal therapeutic dosages. Furthermore, more research based on nanoformulations should be performed to minimize/overcome the hindrance associated with bioavailability, rapid degradation, and toxicity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('26df6e76-9e9c-46be-8545-8cc77947ec8c', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Therapeutic Agents Targeting the Nrf2 Signaling Pathway to Combat Oxidative Stress and Intestinal Inflammation in Veterinary and Translational Medicine', 'Khan MZ, Li S, Ullah A, Li Y, Abohashrh M, Alzahrani FM, Alzahrani KJ, Alsharif KF', 2025, 'Veterinary sciences', '10.3390/vetsci13010025', 'https://doi.org/10.3390/vetsci13010025', 'https://europepmc.org/articles/PMC12846341?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'This review synthesizes research on nuclear factor erythroid 2-related factor 2 (Nrf2) in intestinal health across human, livestock, and mouse models. The Nrf2 signaling pathway serves as a master regulator of cellular antioxidant defenses and a key therapeutic target for intestinal inflammatory disorders, including ulcerative colitis and Crohn''s disease. The interplay between oxidative stress, Nrf2 signaling, and NF-κB inflammatory cascades represents a critical axis in the pathogenesis and resolution of intestinal inflammation. Under normal physiological conditions, Nrf2 remains sequestered in the cytoplasm by Kelch-like ECH-associated protein 1 (Keap1), which facilitates its ubiquitination and proteasomal degradation. However, during oxidative stress, reactive oxygen species (ROS) and electrophilic compounds modify critical cysteine residues on Keap1, disrupting the Keap1-Nrf2 interaction and enabling Nrf2 nuclear translocation. Once in the nucleus, Nrf2 binds to antioxidant response elements (ARE) in the promoter regions of genes encoding phase II detoxifying enzymes and antioxidant proteins, including heme oxygenase-1 (HO-1), NAD(P)H quinone oxidoreductase 1 (NQO1), and glutamate-cysteine ligase. This comprehensive review synthesizes current evidence demonstrating that activation of Nrf2 signaling confers protection against intestinal inflammation through multiple interconnected mechanisms: suppression of NF-κB-mediated pro-inflammatory cascades, enhancement of cellular antioxidant capacity, restoration of intestinal barrier integrity, modulation of immune cell function, and favorable alteration of gut microbiota composition. We systematically examine a diverse array of therapeutic agents targeting Nrf2 signaling, including bioactive peptides, natural polyphenols, flavonoids, terpenoids, alkaloids, polysaccharides, probiotics, and synthetic compounds. The mechanistic insights and therapeutic evidence presented underscore the translational potential of Nrf2 pathway modulation as a multi-targeted strategy for managing intestinal inflammatory conditions and restoring mucosal homeostasis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c6aa580f-4e8f-4668-8e6e-8d8185fb0429', '6d3e7e0b-e150-4c2a-ad9f-e3997eef7074', 'Tolerance of Transplastomic Tobacco Plants Overexpressing a Theta Class Glutathione Transferase to Abiotic and Oxidative Stresses', 'Stavridou E, Michailidis M, Gedeon S, Ioakeim A, Kostas S, Chronopoulou E, Labrou NE, Edwards R', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01861', 'https://doi.org/10.3389/fpls.2018.01861', 'https://europepmc.org/articles/PMC6337918?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Chloroplasts are organelles subjected to extreme oxidative stress conditions. Biomolecules produced in the chloroplasts act as signals guiding plant metabolism toward stress tolerance and play a major role in regulating gene expression in the nucleus. Herein, we used transplastomic plants as an alternative approach to expression of transgenes in the nucleus for conferring stress tolerance to abiotic stresses and herbicides. To investigate the morphophysiological and molecular mechanisms and the role of plastid expressed GSTs in tobacco stress detoxification and stress tolerance, we used transplastomic tobacco lines overexpressing a theta class glutathione transferase (GST) in chloroplasts. The transplastomic plants were tested under drought (0, 100, and 200 mM mannitol) and salinity (0, 150, and 300 mM NaCl) in vitro, and under herbicide stress (Diquat). Our results suggest that pt AtGSTT lines were tolerant to herbicide-induced oxidative and salinity stresses and showed enhanced response tolerance to mannitol-induced osmotic stress compared to WT plants. Overexpression of the Arabidopsis thaliana AtGSTT in the chloroplasts resulted in enhanced photo-tolerance and turgor maintenance under stress. Whole-genome transcriptome analysis revealed that genes related to stress tolerance, were upregulated in pt AtGSTT2a line under both control and high mannitol stress conditions. Transplastomic plants overexpressing the pt AtGSTT2a in the chloroplast showed a state of acclimation to stress, as only limited number of genes were upregulated in the pt AtGSTT2a transplastomic line compared to WT under stress conditions while at the same time genes related to stress tolerance were upregulated in pt AtGSTT2a plants compared to WT in stress-free conditions. In parallel, the metabolic profile indicated limited perturbations of the metabolic homeostasis in the transplastomic lines and greater accumulation of mannitol, and soluble sugars under high mannitol stress. Therefore, transplastomic lines seem to be in a state of acclimation to stress under stress-free conditions, which was maintained even under high mannitol stress. The results help to elucidate the role of GSTs in plant abiotic stress tolerance and the underlying mechanisms of the GSTs expressed in the chloroplast, toward environmental resilience of cultivated crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f86974e9-637b-45f1-bf70-955af7232c60', '91954de4-db35-404f-a84b-6b58af71c69c', 'Advances in the Modulation of Potato Tuber Dormancy and Sprouting', 'Xueni Di, Qiang Wang, Feng Zhang, Haojie Feng, Xiyao Wang, Chengcheng Cai', 2024, 'International Journal of Molecular Sciences', '10.3390/ijms25105078', 'https://doi.org/10.3390/ijms25105078', 'https://pmc.ncbi.nlm.nih.gov/articles/PMC11121589/pdf/ijms-25-05078.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'The post-harvest phase of potato tuber dormancy and sprouting are essential in determining the economic value. The intricate transition from dormancy to active growth is influenced by multiple factors, including environmental factors, carbohydrate metabolism, and hormonal regulation. Well-established environmental factors such as temperature, humidity, and light play pivotal roles in these processes. However, recent research has expanded our understanding to encompass other novel influences such as magnetic fields, cold plasma treatment, and UV-C irradiation. Hormones like abscisic acid (ABA), gibberellic acid (GA), cytokinins (CK), auxin, and ethylene (ETH) act as crucial messengers, while brassinosteroids (BRs) have emerged as key modulators of potato tuber sprouting. In addition, jasmonates (JAs), strigolactones (SLs), and salicylic acid (SA) also regulate potato dormancy and sprouting. This review article delves into the intricate study of potato dormancy and sprouting, emphasizing the impact of environmental conditions, carbohydrate metabolism, and hormonal regulation. It explores how various environmental factors affect dormancy and sprouting processes. Additionally, it highlights the role of carbohydrates in potato tuber sprouting and the intricate hormonal interplay, particularly the role of BRs. This review underscores the complexity of these interactions and their importance in optimizing potato dormancy and sprouting for agricultural practices.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('81511b3e-853e-482f-ba07-ea889f4e753d', '91954de4-db35-404f-a84b-6b58af71c69c', 'Assessment of pre- and post-harvest anti-sprouting treatments to replace CIPC for potato storage', 'Margot Visse‐Mansiaux, Maud Tallant, Yves Brostaux, Pierre Delaplace, Hervé Vanderschuren, Brice Dupuis', 2021, 'Postharvest Biology and Technology', '10.1016/j.postharvbio.2021.111540', 'https://doi.org/10.1016/j.postharvbio.2021.111540', 'https://lirias.kuleuven.be/retrieve/ea839de9-153c-43b0-a11b-3248ccd28ea6', NULL, NULL, 12, NULL, 'other', 1, 'cc-by', 'To avoid losses from sprouting during potato storage, the anti-sprouting agent chlorpropham [CIPC] has been widely used over the past few decades. However, the European Union recently decided not to authorize the renewal of CIPC, prompting the value chain to find alternative treatments. We assessed for three years the potential of pre- and post-harvest anti-sprouting treatments to replace CIPC using four potato-processing varieties. Pre-harvest application of maleic hydrazide [MH] and post-harvest applications of 3-decen-2-one, 1,4-dimethylnapthalene [1,4-DMN] and CIPC were performed following supplier’s recommendations. In addition, we evaluated the potential of 3-decen-2-one and 1,4-DMN to prolong the efficacy of pre-harvest MH treatment anti-sprouting activity during storage. All molecules significantly reduced sprouting after seven months of storage compared with the untreated control group. MH, 3-decen-2-one, 1,4-DMN and CIPC displayed respectively 86.9 %; 77.9 %, 73.6 % and 99.8 % of efficacy to control sprout weight and 79.4 %; 73.4 %, 68.4 % and 96.9 % of efficacy to control sprout length. Our results suggest that using 3-decen-2-one and 1,4-DMN in combination with MH do not bring additional benefit to control sprouting. Because differences in dormancies could be observed between varieties, we also showed that the efficacy of post-harvest treatments is genotype-dependent, while MH pre-harvest treatment is effective equally for all varieties. Applications of CIPC and MH led to detectable residues in tubers, while no residue of 1,4-DMN has been detected in tubers treated with this molecule (< LOQ). We concluded that treatments with MH, 1,4-DMN and 3-decen-2-one are valuable alternatives to CIPC to control sprouting of processing potatoes.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3a14f9e5-d340-4d2c-b8cf-df5ff69cc8c0', '91954de4-db35-404f-a84b-6b58af71c69c', 'Assuring Potato Tuber Quality during Storage: A Future Perspective', 'Alamar MC, Tosetti R, Landahl S, Bermejo A, Terry LA', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.02034', 'https://doi.org/10.3389/fpls.2017.02034', 'https://europepmc.org/articles/PMC5712419?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by', 'Potatoes represent an important staple food crop across the planet. Yet, to maintain tuber quality and extend availability, there is a necessity to store tubers for long periods often using industrial-scale facilities. In this context, preserving potato quality is pivotal for the seed, fresh and processing sectors. The industry has always innovated and invested in improved post-harvest storage. However, the pace of technological change has and will continue to increase. For instance, more stringent legislation and changing consumer attitudes have driven renewed interest in creating alternative or complementary post-harvest treatments to traditional chemically reliant sprout suppression and disease control. Herein, the current knowledge on biochemical factors governing dormancy, the use of chlorpropham (CIPC) as well as existing and chemical alternatives, and the effects of pre- and post-harvest factors to assure potato tuber quality is reviewed. Additionally, the role of genomics as a future approach to potato quality improvement is discussed. Critically, and through a more industry targeted research, a better mechanistic understanding of how the pre-harvest environment influences tuber quality and the factors which govern dormancy transition should lead to a paradigm shift in how sustainable storage can be achieved.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6ec7867b-0284-4562-a002-fa3319cd0d42', '91954de4-db35-404f-a84b-6b58af71c69c', 'Changes in gene expression in potato meristems treated with the sprout suppressor 1,4-dimethylnaphthalene are dependent on tuber age and dormancy status', 'Michael Campbell, Carley Gwin, Helen H. Tai, Rachael Adams', 2020, 'PLoS ONE', '10.1371/journal.pone.0235444', 'https://doi.org/10.1371/journal.pone.0235444', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0235444&type=printable', NULL, NULL, 13, NULL, 'canada', 3, 'cc-by', 'Commercial storage of potatoes often relies on the use of sprout inhibitors to prolong storage and reduce spoilage. The compound 1,4-dimethylnaphthalene (DMN) has seen increase application as a sprout inhibitor in the potato industry as older chemistries are being phased out. The mode of action of DMN is poorly understood as is the sensitivity of potato tissues to this new class of inhibitor. During storage potato tubers transition from a state of endo-dormant to eco-dormant and it is not known if the DMN response is consistent across this developmental transition. RNA-seq gene expression profiling was used to establish if stored potato tubers (Solanum tuberosum cv La Chipper) have differential sensitivity to DMN as tubers age. DMN was applied at three different times during storage; just after harvest when tubers are in endo-dormancy, midwinter at early eco-dormancy, and in spring during late eco-dormancy when sprouting was prevented via exposure to cold storage temperatures. Changes in gene expression were lowest during endo-dormancy while midwinter and spring treatments exhibited a greater and more diverse expression response. Functional analysis of differential gene expression demonstrated gene sets associated with DNA replication, cell division, and DNA methylation are suppressed after DMN treatment. However, gene sets associated with salicylic acid, jasmonic acid, abiotic and biotic stress responses are elevated by DMN only after endodormancy terminates. Gene clusters associated with pathogenesis related proteins PR-4 and PR-5 are also upregulated in response to DMN. These results indicate that DMN sensitivity changes as potato tubers age and transition from endo-dormant to eco-dormant in storage and the overall response is a shift in gene classes that regulate growth and response to stress.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7b152e6e-e46d-45cd-aff7-5caa63c355c8', '91954de4-db35-404f-a84b-6b58af71c69c', 'Historical Multi-Environment Analysis of Chlorpropham Sprout Control Programs for Phytosanitary Assurance in U.S. Fresh, Export Potato Markets', 'R. Hendricks, Nora L. Olsen, J. Piaskowski, H. Kaur, G. H. A. Teixeira, Albert T. Adjesiwor, J. Miller', 2026, 'American Journal of Potato Research', '10.1007/s12230-026-10089-z', 'https://doi.org/10.1007/s12230-026-10089-z', 'https://link.springer.com/content/pdf/10.1007/s12230-026-10089-z.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Expanding export markets may rely upon the ability to minimize phytosanitary risks associated with exported fresh market potatoes by ensuring potatoes will not sprout and develop plants. This study analyzed two historical data sets to evaluate the effect of chlorpropham (CIPC) sprout inhibition (1) on sprout development during storage and (2) on plant emergence in the field. To assess storage temperature impact on sprout development, data from 2001 to 2010 storage seasons were compared between nontreated and thermal CIPC-treated potatoes using 25 varieties stored at three temperatures (5.6 C, 7.2 C, or 8.9 C). Sprout development was evaluated approximately one month after harvest and subsequently evaluated each month for approximately seven months. Field trials, conducted in 2009, 2010, 2012, 2014 and 2015, compared emergence of (1) nontreated tubers, (2) thermal CIPC-treated (22 mg L − 1 application) tubers, (3) CIPC-spray treated tubers (various rates), and/or (4) a combination of both CIPC applications. After 150 days in storage, CIPC-treated tubers had a 1% probability of having a sprout greater than 5 mm in length compared to 41% probability of nontreated tubers. At 8.9 C, nontreated tubers rapidly developed sprouts compared to 5.6 and 7.2 C. When CIPC was applied, storage temperature had a minimal impact on sprout development and tubers remained at the peeping stage of sprout development for most of the storage duration. The probability of emergence from tubers treated with a combination of thermal and spray CIPC remained low (2%) up to 80 days after planting, compared to 98% probability of emergence from nontreated tubers. CIPC treatments significantly reduce sprout and plant development and are a critical tool as a sprout control agent and phytosanitary tool in the global trade of fresh market potatoes.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2aec943a-7ed9-47d3-aed5-f7677a79d041', '91954de4-db35-404f-a84b-6b58af71c69c', 'Marine biocatalysts: enzymatic features and applications', 'Trincone A', 2011, 'Marine drugs', '10.3390/md9040478', 'https://doi.org/10.3390/md9040478', 'https://europepmc.org/articles/PMC3124967?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'In several recent reports related to biocatalysis the enormous pool of biodiversity found in marine ecosystems is considered a profitable natural reservoir for acquiring an inventory of useful biocatalysts. These enzymes are characterized by well-known habitat-related features such as salt tolerance, hyperthermostability, barophilicity and cold adaptivity. In addition, their novel chemical and stereochemical characteristics increase the interest of biocatalysis practitioners both in academia and research industry. In this review, starting from the analysis of these featuring habitat-related properties, important examples of marine enzymes in biocatalysis will be reported. Completion of this report is devoted to the analysis of novel chemical and stereochemical biodiversity offered by marine biocatalysts with particular emphasis on current or potential applications of these enzymes in chemical and pharmaceutical fields. The analysis of literature cited here and the many published patent applications concerning the use of marine enzymes supports the view that these biocatalysts are just waiting to be discovered, reflecting the importance of the marine environment. The potential of this habitat should be thoroughly explored and possibly the way to access useful biocatalysts should avoid destructive large-scale collections of marine biomass for enzyme production. These two aspects are day by day increasing in interest and a future increase in the use of marine enzymes in biocatalysis should be expected.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('999cb768-3c68-4617-bc78-0f1ff754d016', '91954de4-db35-404f-a84b-6b58af71c69c', 'Nematicidal Activity of Alkyloxyalkanols Against Bursaphelenchus xylophilus', 'Joon Oh Park, Sujin Lee, Min-Jung Kim, Junheon Kim', 2025, 'Applied Sciences', '10.3390/app15189862', 'https://doi.org/10.3390/app15189862', 'https://www.mdpi.com/2076-3417/15/18/9862', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Pine wilt disease, caused by the pine wood nematode Bursaphelenchus xylophilus (Steiner & Bührer) Nickle, poses a major threat to pine forests worldwide. While avermectin-based pesticides are currently used for pine wilt disease management, alternative approaches are needed to mitigate the risk of resistance. This study evaluated the nematicidal activity of 24 synthetic alkyloxyalkanols (ROR′OH) against B. xylophilus. The compounds were synthesized by the etherification of diols with 1-bromoalkanes and tested in a microplate bioassay. Mortality was measured after 24 h, and LD50 values were calculated. Several compounds, including 2-(1-decyloxyl)-1-ethanol (C10OC2OH) and 8-(1-hexyloxy)-1-octanol (C6OC8OH), showed potent nematicidal effects, with LD50 values of less than 50 ppm. Structure–activity relationship analysis revealed that compounds with chains containing an even number of carbons in both the alkyl and alkyloxy groups tended to exhibit increased activity. Clustering analysis confirmed that carbon parity significantly affected efficacy (Mann–Whitney U = 15, p B. xylophilus.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e5162e52-489d-444c-967b-2d008c913b18', '91954de4-db35-404f-a84b-6b58af71c69c', 'Physiological and molecular mechanisms associated with potato tuber dormancy', 'Dogramaci M, Dobry EP, Fortini EA, Sarkar D, Eshel D, Campbell MA', 2024, 'Journal of experimental botany', '10.1093/jxb/erae182', 'https://doi.org/10.1093/jxb/erae182', 'https://europepmc.org/articles/PMC11480654?pdf=render', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc by', 'Tuber dormancy is an important physiological trait that impacts post-harvest storage and end-use qualities of potatoes. Overall, dormancy regulation of potato tubers is a complex process driven by genetic as well as environmental factors. Elucidation of the molecular and physiological mechanisms that influence different dormancy stages of tubers has wider potato breeding and industry-relevant implications. Therefore, the primary objective of this review is to present current knowledge of the diversity in tuber dormancy traits among wild relatives of potatoes and discuss how genetic and epigenetic factors contribute to tuber dormancy. Advancements in understanding of key physiological mechanisms involved in tuber dormancy regulation, such as apical dominance, phytohormone metabolism, and oxidative stress responses, are also discussed. This review highlights the impacts of common sprout suppressors on the molecular and physiological mechanisms associated with tuber dormancy and other storage qualities. Collectively, the literature suggests that significant changes in expression of genes associated with the cell cycle, phytohormone metabolism, and oxidative stress response influence initiation, maintenance, and termination of dormancy in potato tubers. Commercial sprout suppressors mainly alter the expression of genes associated with the cell cycle and stress responses and suppress sprout growth rather than prolonging tuber dormancy.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5345d0d2-9945-45d7-818b-95904aaa4cfd', '91954de4-db35-404f-a84b-6b58af71c69c', 'Potatoes dormancy release and sprouting commencement: A review on current and future prospects', 'Qiannan Hu, Caitian Tang, Xinyu Zhou, Xiangzheng Yang, Zisheng Luo, Lei Wang, Mingyi Yang, Dong Li', 2023, 'Food Frontiers', '10.1002/fft2.228', 'https://doi.org/10.1002/fft2.228', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/fft2.228', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Abstract The potato (Solanum tuberosum L.) is one of the most important food crops worldwide. Nevertheless, due to food safety concerns, substantial amounts of potatoes are not utilized, resulting in losses. Dormancy development is affected by potato variety, temperature, light, humidity, and so forth. Traditional and novel techniques to detect potato dormancy have been developed based on infrared spectroscopy, hyperspectral, and multispectral imaging systems in combination with simulation verification. This review describes the ability of novel approaches to address the uncertain hazardous issue and delay or inhibit potato dormancy incidence and development. Further, this review describes the role of carbohydrate metabolism and phytohormone regulation involved in potato dormancy, the mechanism of action to address dormancy, and challenges and recommendations moving forward. More work is needed to develop novel approaches toward addressing the problem of potato germination after harvest.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ef94c51-859e-43df-bc59-e76f62fde6f0', '91954de4-db35-404f-a84b-6b58af71c69c', 'Risk assessment of glycoalkaloids in feed and food, in particular in potatoes and potato-derived products', 'Schrenk D, Bignami M, Bodin L, Chipman JK, Del Mazo J, Hogstrand C, Hoogenboom LR, Leblanc JC', 2020, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2020.6222', 'https://doi.org/10.2903/j.efsa.2020.6222', 'https://europepmc.org/articles/PMC7417869?pdf=render', NULL, NULL, 190, NULL, 'other', 1, 'cc by-nd', 'The European Commission asked EFSA for a scientific opinion on the risks for animal and human health related to the presence of glycoalkaloids (GAs) in feed and food. This risk assessment covers edible parts of potato plants and other food plants containing GAs, in particular, tomato and aubergine. In humans, acute toxic effects of potato GAs (α-solanine and α-chaconine) include gastrointestinal symptoms such as nausea, vomiting and diarrhoea. For these effects, the CONTAM Panel identified a lowest-observed-adverse-effect level of 1 mg total potato GAs/kg body weight (bw) per day as a reference point for the risk characterisation following acute exposure. In humans, no evidence of health problems associated with repeated or long-term intake of GAs via potatoes has been identified. No reference point for chronic exposure could be identified from the experimental animal studies. Occurrence data were available only for α-solanine and α-chaconine, mostly for potatoes. The acute dietary exposure to potato GAs was estimated using a probabilistic approach and applying processing factors for food. Due to the limited data available, a margin of exposure (MOE) approach was applied. The MOEs for the younger age groups indicate a health concern for the food consumption surveys with the highest mean exposure, as well as for the P95 exposure in all surveys. For adult age groups, the MOEs indicate a health concern only for the food consumption surveys with the highest P95 exposures. For tomato and aubergine GAs, the risk to human health could not be characterised due to the lack of occurrence data and the limited toxicity data. For horses, farm and companion animals, no risk characterisation for potato GAs could be performed due to insufficient data on occurrence in feed and on potential adverse effects of GAs in these species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6757c094-a29a-43a8-867b-c657155f3f60', '91954de4-db35-404f-a84b-6b58af71c69c', 'Sprout Inhibitor, Ethylene, on Seed Tuber Storability and Crop Productivity', 'Jacob Michael Blauer, Michael K. Thornton', 2026, 'American Journal of Potato Research', '10.1007/s12230-025-10036-4', 'https://doi.org/10.1007/s12230-025-10036-4', 'https://link.springer.com/content/pdf/10.1007/s12230-025-10036-4.pdf', NULL, NULL, 5, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Effective sprout inhibitors are increasingly needed in potato production due to regulatory changes restricting widely used chemistries such as chlorpropham (CIPC), with direct implications for storage management and international trade. Ethylene has emerged as a potential alternative, since it is naturally occurring in plants and exhibits sprout suppressant activity, though commercial outcomes may vary. To evaluate its effectiveness in seed storage systems for both sprout control and potential impacts on tuber set and size distribution, this single-year study examined ethylene treatments on three cultivars: Caribou Russet, Teton Russet, and Dakota Russet. In this study, ethylene effectively reduced sprouting in stored seed potatoes, hastened emergence, increased stem numbers, and reduced average tuber size, however, also reduced total yield (ca. 13%) compared to the controls. These findings indicate that ethylene can be an effective sprout suppressant for seed potatoes, but its use should be carefully targeted to production systems where smaller tubers are advantageous, as yield reductions may offset economic value.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('028137ed-7d01-4413-8620-3e1612dc57ce', '91954de4-db35-404f-a84b-6b58af71c69c', 'Sprouting Control Treatment with LED Lights Does Not Affect the Biochemical Aspects of ‘Asterix’ Potatoes', 'Vanessa Maria Dantas Pedrosa, Maiqui Izidoro, Maryelle Barros da Silva, Francisco Ronaldo Cardoso da Silva, Arthur Bernardes Cecílio Filho, Rogério Falleiros Carvalho, Allan Lopes Bacha, Gustavo Henrique de Almeida Teixeira', 2025, 'Potato Research', '10.1007/s11540-024-09844-8', 'https://doi.org/10.1007/s11540-024-09844-8', 'https://link.springer.com/content/pdf/10.1007/s11540-024-09844-8.pdf', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Recently, it was observed that red, blue and far-red lights and different intensities (0.1 and 1.0 μmol m−2 s−1) of light-emitting diode (LED) reduced potato sprout growth but did not effectively inhibit sprouting in physiologically aged tubers. Therefore, this study aimed to identify the physiological and biochemical changes and sprout development in potatoes treated with LED lights or with 3-chlorophenyl carbamate (CIPC). To achieve this, ‘Asterix’ potatoes were harvested, cured at 15 °C (90–93% RH) for 15 days and treated with red (5 µmol m−2 s−1), far-red (5 µmol m−2 s−1) and blue (1 µmol m−2 s−1) LED lights, in addition to the negative control (dark) and positive control (0.022 g L−1 of CIPC) treatments. Potatoes from the light treatments were exposed to LED lights 24 h a day throughout the storage period, under optimal conditions for sprout development (16.7 ± 1 °C and 91.5 ± 1% RH). Tubers treated with blue and far-red LED light exhibited longer dormancy, fewer sprouts and smaller sprouts over the storage period. The carbohydrate content (starch and reducing sugars) was not affected by light treatments; however, total soluble sugar content was lower in tubers kept in the dark and higher in those treated with far-red LED light, which was not related to sprouting control. Therefore, it is suggested that other signalling mechanisms may be involved in sprout control using LED lights.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9abfac47-620d-4e46-9af7-94a55b471f20', '91954de4-db35-404f-a84b-6b58af71c69c', 'Suppression of the Vacuolar Invertase Gene Prevents Cold-Induced Sweetening in Potato', 'Pudota B. Bhaskar, Lei Wu, James S. Busse, Brett R. Whitty, Andy J. Hamernik, Shelley H. Jansky, C. Robin Buell, Paul C. Bethke', 2010, 'PLANT PHYSIOLOGY', '10.1104/pp.110.162545', 'https://doi.org/10.1104/pp.110.162545', 'https://academic.oup.com/plphys/article-pdf/154/2/939/48200705/plphys_v154_2_939.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Potato (Solanum tuberosum) is the third most important food crop in the world. Potato tubers must be stored at cold temperatures to prevent sprouting, minimize disease losses, and supply consumers and the processing industry with high-quality tubers throughout the year. Unfortunately, cold storage triggers an accumulation of reducing sugars in tubers. High-temperature processing of these tubers results in dark-colored, bitter-tasting products. Such products also have elevated amounts of acrylamide, a neurotoxin and potential carcinogen. We demonstrate that silencing the potato vacuolar acid invertase gene VInv prevents reducing sugar accumulation in cold-stored tubers. Potato chips processed from VInv silencing lines showed a 15-fold acrylamide reduction and were light in color even when tubers were stored at 4°C. Comparable, low levels of VInv gene expression were observed in cold-stored tubers from wild potato germplasm stocks that are resistant to cold-induced sweetening. Thus, both processing quality and acrylamide problems in potato can be controlled effectively by suppression of the VInv gene through biotechnology or targeted breeding.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35ab2853-5fa7-4dfc-affd-b53bbe56d44e', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Seed testing for blackleg of Canola', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/seed-testing-for-blackleg-of-canola', 'https://open.alberta.ca/dataset/bc22f632-e9da-441d-8732-72da4ca203b7/resource/f1493e34-a999-4fcb-8ea5-9aeb9f9ba94e/download/0163040079606-seed-testing-for-blackleg-of-canola.pdf', NULL, NULL, 56, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document provided a technical manual on seed testing for blackleg of canola caused by Leptosphaeria maculans. It explained the purpose and scope of laboratory methods used to detect the presence of the pathogen in canola seed and to distinguish between weakly virulent and virulent strains of Leptosphaeria maculans. The document described disease background, seed borne transmission, and standardized testing procedures including isolation, culturing, blotter tests, and virulence assessment. It also included visual references, flow charts, appendices on culture media and laboratory techniques, and reference material to support consistent application of testing methods.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3caa2e22-a921-4a1a-9ef4-b5899313968a', '91954de4-db35-404f-a84b-6b58af71c69c', 'Thai Hom Mali Rice: Origin and Breeding for Subsistence Rainfed Lowland Rice System', 'Vanavichit A, Kamolsukyeunyong W, Siangliw M, Siangliw JL, Traprab S, Ruengphayak S, Chaichoompu E, Saensuk C', 2018, 'Rice (New York, N.Y.)', '10.1186/s12284-018-0212-7', 'https://doi.org/10.1186/s12284-018-0212-7', 'https://europepmc.org/articles/PMC5891439?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'The world-renowned Thai Hom Mali Rice has been the most important aromatic rice originating in Thailand. The aromatic variety was collected from Chachoengsao, a central province, and after pure-line selection, it was officially named as Khao Dawk Mali 105, (KDML105). Because of its superb fragrance and cooking quality, KDML105 has been a model variety for studying genes controlling grain quality and aroma. The aromatic gene was cloned in KDML105, as an amino aldehyde dehydrogenase (AMADH) or better known as BADH2 located on chromosome 8. Later on, all other aromatic rice genes were discovered as allelic to the AMADH. As a selection of local landrace variety found in rainfed areas, the Thai Jasmine rice showed adaptive advantages over improved irrigated rice in less fertile lowland rainfed conditions. Because KDML105 was susceptible to most diseases and insect pests, marker-assisted backcross selection (MABC) was used for the genetic improvement since 2000. After nearly 17 years of MABC for integrating new traits into KDML105, a new generation of KDML105, designated HM84, was developed which maintains the cooking quality and fragrance, and has gained advantages during flash flooding, disease, and insect outbreak.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fb1edcea-e202-4e06-a3a8-f16d85e0a663', '91954de4-db35-404f-a84b-6b58af71c69c', 'The Potato of the Future: Opportunities and Challenges in Sustainable Agri-food Systems', 'Devaux A, Goffart JP, Kromann P, Andrade-Piedra J, Polar V, Hareau G', 2021, 'Potato research', '10.1007/s11540-021-09501-4', 'https://doi.org/10.1007/s11540-021-09501-4', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC8302968.1/PMC8302968.1.pdf', NULL, NULL, 40, NULL, 'other', 1, 'cc by', 'In the coming decades, feeding the expanded global population nutritiously and sustainably will require substantial improvements to the global food system worldwide. The main challenge will be how to produce more food with the same or fewer resources and waste less. Food security has four dimensions: food availability, food access, food use and quality, and food stability. Among several other food sources, the potato crop is one that can help match all these constraints worldwide due to its highly diverse distribution pattern, and its current cultivation and demand, particularly in developing countries with high levels of poverty, hunger, and malnutrition. After an overview of the current situation of global hunger, food security, and agricultural growth, followed by a review of the importance of the potato in the current global food system and its role played as a food security crop, this paper analyses and discusses how potato research and innovation can contribute to sustainable agri-food systems comparing rural and industrial agri-food systems with reference to food security indicators. It concludes with a discussion about the challenges for sustainable potato cropping enhancement considering the needs to increase productivity in rural-based potato food systems that predominate in low-income countries, while promoting better resource management and optimization in industrial-based agri-food systems considering factors such as quality, diversity of products, health impacts, and climate change effects. Research and innovation options and policies that could facilitate the requirements of both rural and industrial potato-based agri-food systems are described.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3f031c04-73d0-448c-9fe8-949228c798d6', '91954de4-db35-404f-a84b-6b58af71c69c', 'The Problem of Weed Infestation of Agricultural Plantations vs. the Assumptions of the European Biodiversity Strategy', 'Adrianna Kubiak, Agnieszka Wolna-Maruwka, Alicja Niewiadomska, Agnieszka Anna Pilarska', 2022, 'Agronomy', '10.3390/agronomy12081808', 'https://doi.org/10.3390/agronomy12081808', 'https://www.mdpi.com/2073-4395/12/8/1808/pdf?version=1660108950', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Meeting the nutritional needs of a dynamically developing global society is a major challenge. Despite the modernisation of agriculture, huge losses in the quality and quantity of crops occur each year, mainly due to weed species, which are the most important biotic limitation to agricultural production. Globally, approximately 1800 weed species cause a 31.5% reduction in plant production, which translates to USD 32 billion per year in economic losses. However, when the same herbicides are frequently applied, plants develop segetal immune mechanisms. There are currently around 380 herbicide-resistant weed biotypes worldwide. Due to the negative influence of herbicides on ecosystems and the legal regulations that limit the use of chemical crop protection products, it is necessary to develop a new method of weed control. Bioherbicides, based on living organisms or their secondary metabolites, seem to be an ideal solution. The biocontrol market is worth around EUR 550 million in Europe and EUR 1.6 billion worldwide, with an estimated 15% growth expected by 2025. Despite numerous studies that have demonstrated the effectiveness of microbial bioherbicides, only 25 mould-based bioherbicides are currently available to growers. Due to the high specificity and selectivity of biological crop protection products, as well as their low production costs and non-toxicity to the environment and human health, they would appear to be a safe alternative to chemical pesticides.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa35bc94-fcec-4a3a-aa74-e4f6f90bdef4', '91954de4-db35-404f-a84b-6b58af71c69c', 'Tissue specific mechanisms of tuber dormancy after 1,4-dimethylnaphthalene treatment in potato', 'Dogramaci M, Dos Reis de Oliveira T, Fortini EA, Sarkar D, Wyatt N, Leonard E, Tharayil N, Finger F', 2026, 'Food chemistry. Molecular sciences', '10.1016/j.fochms.2026.100376', 'https://doi.org/10.1016/j.fochms.2026.100376', 'https://europepmc.org/articles/PMC12950432?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by-nc-nd', '1,4-Dimethylnaphthalene (DMN) is gaining popularity as a postharvest sprout suppressant for potato storage. We hypothesized that DMN treatment impact critical phytohormone regulations in a tissue specific manner to suppress sprout growth of potato tubers. This study investigated transcriptional and hormonal responses in cv. ''Russet Burbank'' tubers subjected to single or multiple DMN treatments during long-term storage. Tuber sprout growth was monitored during storage, and primary and secondary meristems, as well as tuber flesh tissues were collected from DMN treated and untreated tubers at three-week intervals for molecular and phytohormone analyses. Multiple DMN treatments were most effective in suppressing sprout growth up to 18 weeks in storage. Molecular responses to DMN treatments were tissue specific. Treatment of tubers with DMN altered the levels of hormones and their precursors as lower content of active forms of gibberellic acid, cytokinin, and jasmonic acid were observed in meristem tissues particularly with multiple DMN treatments. Aligning with phytohormone analyses results, multiple DMN treatments also altered the abundance of transcripts associated with abscisic acid, gibberellin, cytokinin, auxin, jasmonic acid, salicylic acid, and ethylene biosynthesis and signaling. DMN treatment impacted transcription factor families including APETALA2/ETHYLENE RESPONSIVE FACTOR, MYELOBLASTOSIS TRANSCRIPTION FACTOR, and BASIC HELIX-LOOP-HELIX associated with dormancy maintenance. Results of this research elucidate multiple DMN applications are needed to suppress sprout growth during long-term storage, and the underlying molecular mechanisms of DMN involve tuber tissue specific alteration of phytohormone regulation related to dormancy maintenance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7ac4af4e-f172-4e6c-9eff-5219e5bd82a7', '61a86171-4f1c-4450-b6f2-b03b74254244', 'Effect of magnetized water and salinity stress on germination traits and seedling of bean (Phaseolus vulgaris L.)', 'morteza goldani, Maryam Javadi, Ahmad Nezami', 2016, 'پژوهش‌های حبوبات ایران', '10.22067/ijpr.v7i1.38695', 'https://doi.org/10.22067/ijpr.v7i1.38695', 'https://ijpr.um.ac.ir/article_31899_ab45bbe4f6ac4a210b7e8e451d7a3129.pdf', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Introduction Increasing world population is facing critically depletion of water resources, which will be along with increasing food demands to cover the human needs all over the world. Therefore, water scarcity is increasingly a major limitation for increased agricultural production and food security in this century. The scarcity of qualified water, has made farmers to consider the water of marginal quality for usage in agriculture. The Water’s molecular structure is affected by a magnetic field, so that a change in the water relations can affect the overall plant growth. One of the approaches that provides higher productivity and quality assurance is using static electromagnetic fields. The use of magnetically treated water for irrigation in agriculture is considered as one of the important environmental clean methods. The water treated in the magnetic field or pass through a magnetic device called magnetized water. The influence of magnetic field on various growth processes of plants such as seed germination, seedling growth, plant growth, yield and the properties of crop quality have been the object of several researches. Salinity is defined as the presence of excessive concentration of soluble salts in the soil or in the irrigation water that suppresses plant growth and eventually yield. Salt stress has been identified as one of the most serious environmental factors limiting the productivity of crop plants. The deleterious effects of salinity on plant growth are associated with 1) low osmotic potential, 2) nutritional imbalance, 3) specific ion effect, or 4) a combination of these factors. In addition, there is evidence that salt stress can induce oxidative stress due to generation of reactive oxygen species. Phaseolus vulgaris is an annual growing to 2 m height and is frost tender. Bean leaves are trifoliate (three-leaved), arranged in an alternate fashion on the stem and have oval or diamond-shaped leaflets. Leaf color can be green. The study was undertaken to evaluate the use of magnetically treated water in improving seed germination and early seedling growth (i.e., radical and plumule growth) of the bean (Phaseolus vulgaris L.) in the presence and absence of salt stress. The work was carried out at the germination stage because germination is known as a key process that allows the seed embryo to grow and evolve into photosynthetic organism, and it is also a critical stage for plant response to salinity. Materials and Methods In order to investigate the influence of magnetized water and salinity on germination characteristics and seedling of bean (Derakhshan variety), an experiment was conducted based on complete randomized design in factorial arrangement with four replications at laboratory of the Agricultural College of Ferdowsi University of Mashhad in 2014. Water types consisted of two levels (magnetized water and tap water) and five salinity levels: 0, 4, 6.5, 8.5 and 9.5 ds/m. The following indices were also measured: Final Germination Percentage (FGP) and Germination Rate (GR) was calculate base on the below equation FGP= (n / N) × 100 where n is the number of seed germination in per day and N is total number of seeds GR= where giis the number of seed germination in every count and di is the number of days till day n th. (Dere and et al., 1998) Chlorophyll concentration was calculated using the following formula Chla (μg/ml) =15.65 A666 - 7.340 A653 Chlb (μg/ml) =27.05 A653 - 11.21 A666 Cx+c=1000A470 – 2.270 Cha – 81.4Chb/227 Traits as length and dry weight of plumule and radical, biomass and seed vigor index were measured too. Data was analyzed using MSTAT-C software and means were compared using Dunkan multiple range test in 5 percent probability. Results and Discussion The results showed that germination percentage, mean germination time, length and dry weight of the plumule and radical, biomass and seed vigor index decreased with increasing salinity, but magnetized water improved them. Magnetic water incre', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.771417+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('30384c02-3db6-428c-9eac-313361b1d96e', '91954de4-db35-404f-a84b-6b58af71c69c', 'Vegetable Grafting: The Implications of a Growing Agronomic Imperative for Vegetable Fruit Quality and Nutritive Value', 'Kyriacou MC, Rouphael Y, Colla G, Zrenner R, Schwarz D', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.00741', 'https://doi.org/10.3389/fpls.2017.00741', 'https://europepmc.org/articles/PMC5427113?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Grafting has become an imperative for intensive vegetable production since chlorofluorocarbon-based soil fumigants were banned from use on grounds of environmental protection. Compelled by this development, research into rootstock-scion interaction has broadened the potential applications of grafting in the vegetable industry beyond aspects of soil phytopathology. Grafting has been increasingly tapped for cultivation under adverse environs posing abiotic and biotic stresses to vegetable crops, thus enabling expansion of commercial production onto otherwise under-exploited land. Vigorous rootstocks have been employed not only in the open field but also under protected cultivation where increase in productivity improves distribution of infrastructural and energy costs. Applications of grafting have expanded mainly in two families: the Cucurbitaceae and the Solanaceae, both of which comprise major vegetable crops. As the main drives behind the expansion of vegetable grafting have been the resistance to soilborne pathogens, tolerance to abiotic stresses and increase in yields, rootstock selection and breeding have accordingly conformed to the prevailing demand for improving productivity, arguably at the expense of fruit quality. It is, however, compelling to assess the qualitative implications of this growing agronomic practice for human nutrition. Problems of impaired vegetable fruit quality have not infrequently been associated with the practice of grafting. Accordingly, the aim of the current review is to reassess how the practice of grafting and the prevalence of particular types of commercial rootstocks influence vegetable fruit quality and, partly, storability. Physical, sensorial and bioactive aspects of quality are examined with respect to grafting for watermelon, melon, cucumber, tomato, eggplant, and pepper. The physiological mechanisms at play which mediate rootstock effects on scion performance are discussed in interpreting the implications of grafting for the configuration of vegetable fruit physicochemical quality and nutritive value.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d92e1812-c1cc-4ab7-b2aa-bc8b4507adf5', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'A study on droplet deposition of nano DAP using unmanned aerial hybrid sprayer on peanut (Arachis hypogaea) crop', 'RAJESH  P, A P  MOHANKUMAR, R  KAVITHA, B  SUTHAKAR, A  SURRENDRAKUMAR, K  GANESAN', 2025, 'The Indian Journal of Agricultural Sciences', '10.56093/ijas.v95i1.155906', 'https://doi.org/10.56093/ijas.v95i1.155906', 'https://epubs.icar.org.in/index.php/IJAgS/article/view/155906', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'The experiment was conducted during rainy (kharif) seasons of 2023 and 2024 at Tamil Nadu Agricultural University, Coimbatore, Tamil Nadu to study the application of nano DAP using a hybrid drone in groundnut (Arachis hypogaea L.) crops. The UAV, model DH-AG-H1, equipped with a 12 L sprayer tank and a 16,000 mAh battery. The UAV''s performance was assessed across multiple parameters, including spray droplet deposition rate, droplet size distribution, density, area coverage, uniformity and drift characteristics. The UAV operated at a spray height of 1 m and a forward speed of 3 m/s, achieved an operational efficiency of 4.11 ha/h. Results showed that in kharif 2023 season, droplet densities ranging from 35–76 drops/cm² in the target zone, with minimal horizontal drift (0–22 drops/cm²) and very low vertical drift (0–6 drops/cm²). The kharif 2024 season data indicated droplet densities from 31–70 drops/cm² in the target zone, with horizontal drift ranging from 0–20 drops/cm² and vertical drift from 0–14 drops/cm². The hybrid drone demonstrated VMD/NMD ratios from 1.02–1.66 and droplet densities between 31 and 76 drops/cm², indicating effective coverage with a diverse range of droplet sizes, from very fine to ultra-coarse. These results confirmed the UAV''s precision in reducing fertilizer use, soil compaction and chemical drift, highlighting its efficiency in promoting sustainable agriculture.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('095a3870-15c0-4a45-bf6e-0367bc826ce2', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'A sustainable crop protection through integrated technologies: UAV-based detection, real-time pesticide mixing, and adaptive spraying', 'Li W, Luo Y, Jiang P, Dong X, Tang K, Liang Z, Shi Y', 2025, 'Scientific reports', '10.1038/s41598-025-19473-x', 'https://doi.org/10.1038/s41598-025-19473-x', 'https://europepmc.org/articles/PMC12518555?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by-nc-nd', 'Chemical control using pesticides remains an essential component of crop pest and disease management, while precision pesticide application is a core element for achieving sustainable agriculture. Precision spraying technology-integrating UAV-based detection, real-time pesticide mixing, and adaptive variable-rate spraying-provides a critical pathway for sustainable crop protection by establishing a "perception-decision-execution" closed-loop framework.While previous reviews have predominantly focused on compartmentalized analyses of individual technologies (e.g., sensing or actuation), this study establishes a unified Perception-Decision-Execution (PDE) framework to, for the first time, quantitatively assess the synergistic interactions and systemic Bottlenecks across all three layers.This paper systematically reviews 168 core publications from 2013 to 2024, proposing for the first time and quantitatively assessing the synergistic effects of technologies within this closed-loop framework. The findings reveal that: (1) UAV-deep learning systems achieve pest identification accuracy rates of 89-94%, but this significantly declines to 60-70% under strong light or occlusion conditions; (2) Real-time mixing systems attain a mixing homogeneity coefficient (γ) > 85% for liquid pesticides, while for suspension concentrates (SCs), γ decreases to 70-75% due to particle sedimentation effects; (3) PWM-based variable-rate spraying reduces pesticide usage by 30-50% and off-target drift by > 30%, though sensor errors can cause positioning deviations of 0.3-0.8 m. Despite considerable promise, this integrated technology faces challenges in large-scale applications, including perception degradation under environmental disturbances, limitations in algorithm generalization, poor pesticide formulation adaptability in mixing, and system coordination issues. To overcome these barriers, this review proposes interdisciplinary solutions: (i) Deploying lightweight edge devices and pruned neural networks to address decision-making delays and enhance real-time responsiveness; (ii) Optimizing mixer structures (e.g., helical baffle angles) based on computational fluid dynamics (CFD) simulations to reduce dead zones and improve mixing homogeneity for SCs; (iii) Integrating multi-sensor technology for drift compensation to enhance UAV spraying stability. By integrating and optimizing these key technologies, the closed-loop framework holds significant potential to markedly improve pesticide utilization efficiency, minimize environmental impact, and offer a practical framework for achieving on-demand application, thereby advancing sustainable smart agriculture.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7a7305b4-24ce-4ce2-855c-4c0c2d439702', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Can a LiDAR-enhanced Air-blast Sprayer Improve Coverage on Tough Targets like Tree Trunks and Emerging Shoots?', 'Brent W. Warneke, Lloyd L. Nackley, Jay W. Pscheidt', 2024, 'HortTechnology', 'https://doi.org/10.21273/HORTTECH05494-24', 'https://doi.org/https://doi.org/10.21273/HORTTECH05494-24', 'https://journals.ashs.org/horttech/view/journals/horttech/34/6/article-p677.xml', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Eastern filbert blight (EFB) and pacific flatheaded borer (PFB) are two problems of Pacific Northwest orchard and nursery production. Fungicides and insecticides used to manage these issues are typically applied to plant tissues with minimal foliage present that can result in considerable spray waste or drift. The Intelligent Spray System (ISS) is a laser-guided, variable-rate sprayer that detects objects in the target zone and releases spray volumes proportional to the density of plant tissues, thereby increasing application efficiency and reducing waste. However, the ISS has not been tested when targeting low-foliage plant tissues such as emerging shoots and trunks. Three experiments were conducted from 2018 to 2021 to evaluate the potential use of the ISS for EFB and PFB management by assessing spray coverage on emerging hazelnut shoot tips, hazelnut tree trunks, and maple tree trunks. On hazelnut shoot tips, coverage was <10% of the shoot on both adaxial and abaxial sides, with the highest coverage on the adaxial side (9.5%) resulting from spraying in standard mode (no sensors) at 3.1 kph. On hazelnut trunks, application at the slowest tested speed (3.1 kph) in intelligent mode resulted in spray coverage greater than or equal to that applied in standard mode at 5.1 kph. In addition, coverage was significantly higher on cards placed on the ground between trees when the sprayer was used in standard mode, indicating higher amounts of wasted spray and drift over intelligent mode. On maple trunks, the slowest speed tested (3.1 kph) resulted in the highest coverage of tree trunks facing the sprayer that were two and three rows away from the sprayer, with the highest coverage levels on the row of trees closest to the sprayer occurring at the highest tested speed of 6.4 kph. On cards placed on trunk sides not facing the sprayer, the slowest tested speed of 3.2 kph resulted in significantly higher coverage than both treatments at 6.4 kph and intelligent mode at 4.8 kph in the tree row closest to the sprayer. This work has demonstrated a baseline of coverage that hazelnut buds receive when spraying for EFB, illustrates that the ISS was able to effectively target trunks, and could be an alternative to drenches for PFB control.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('746eee8d-6bd9-4d37-bc79-cad2aac4bbd5', '53c2d8d5-7a79-446a-af62-a54af1284742', 'Comparative analysis of bacterial populations in sulfonylurea-sensitive and -resistant weeds: insights into community composition and catabolic gene dynamics', 'Homa J, Wilms W, Marcinkowska K, Cyplik P, Ławniczak Ł, Woźniak-Karczewska M, Niemczak M, Chrzanowski Ł', 2024, 'Environmental science and pollution research international', '10.1007/s11356-024-34593-z', 'https://doi.org/10.1007/s11356-024-34593-z', 'https://europepmc.org/articles/PMC11374828?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'This study aimed to compare the impact of iodosulfuron-methyl-sodium and an iodosulfuron-based herbicidal ionic liquid (HIL) on the microbiomes constituting the epiphytes and endophytes of cornflower (Centaurea cyanus L.). The experiment involved biotypes of cornflower susceptible and resistant to acetolactate synthase inhibition, examining potential bacterial involvement in sulfonylurea herbicide detoxification. We focused on microbial communities present on the surface and in the plant tissues of roots and shoots. The research included the synthesis and physicochemical analysis of a novel HIL, evaluation of shifts in bacterial community composition, analysis of the presence of catabolic genes associated with sulfonylurea herbicide degradation and determination of their abundance in all experimental variants. Overall, for the susceptible biotype, the biodiversity of the root microbiome was higher compared to shoot microbiome; however, both decreased notably after herbicide or HIL applications. The herbicide-resistant biotype showed lower degree of biodiversity changes, but shifts in community composition occurred, particularly in case of HIL treatment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('19bd2b32-281f-4e9e-a19f-98ffe7e73786', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Characteristics of unmanned aerial spraying systems and related spray drift: A review', 'Chen P, Douzals JP, Lan Y, Cotteux E, Delpuech X, Pouxviel G, Zhan Y', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.870956', 'https://doi.org/10.3389/fpls.2022.870956', 'https://europepmc.org/articles/PMC9395147?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'Although drift is not a new issue, it deserves further attention for Unmanned Aerial Spraying Systems (UASS). The use of UASS as a spraying tool for Plant Protection Products is currently explored and applied worldwide. They boast different benefits such as reduced applicator exposure, high operating efficiency and are unconcerned by field-related constraints (ground slope, ground resistance). This review summarizes UASS characteristics, spray drift and the factors affecting UASS drift, and further research that still needs to be developed. The distinctive features of UASS comprise the existence of one or more rotors, relatively higher spraying altitude, faster-flying speed, and limited payload. This study highlights that due to most of these features, the drift of UASS may be inevitable. However, this drift could be effectively reduced by optimizing the structural layout of the rotor and spraying system, adjusting the operating parameters, and establishing a drift buffer zone. Further efforts are still necessary to better assess the drift characteristics of UASS, establish drift models from typical models, crops, and climate environments, and discuss standard methods for measuring UASS drift.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c6d76bae-849a-4999-b8d9-c38e2d73bea6', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Development of a spatial risk indicator for monitoring residential pesticide exposure in agricultural areas', 'Galimberti F, Bopp SK, Carletti A, Catarino R, Claverie M, Florio P, Ippolito A, Jones A', 2025, 'Scientific reports', '10.1038/s41598-025-96928-1', 'https://doi.org/10.1038/s41598-025-96928-1', 'https://europepmc.org/articles/PMC12116782?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'The global increase in pesticide use has raised concerns about its impact on biodiversity, ecosystems, and human health, in particular of people living near agricultural areas. This study explores the assessment of pesticide exposure and risks to residents at a high spatial granularity using plant protection product data. Our objective was to develop an indicator to monitor pesticide risk levels faced by residents in France by integrating spatial datasets and exposure assessment methodologies. Using spatialized pesticide sales data based on crop authorizations, we mapped potential pesticide loads at the parcel level. This map, combined with population distribution data, allowed us to develop an indicator for monitoring residential pesticide exposures. Our findings indicate that, on average, 13% of people in France may be exposed to various levels of pesticides due to their proximity to treated crops. This indicator demonstrates the usefulness of granular pesticide sales data in monitoring exposure and can support risk reduction strategies, helping to identify regions where efforts towards sustainable farming should concentrate.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2da35efc-321f-4487-b4a2-b17ed8d48ccb', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Development of Multi-Unit Orchard Centrifugal Spray System and Deposition Evaluation on Pear Trees', 'Shaoqing Xu, Yanfang Li, Ziqi Geng, Peng Qi, Jianli Song', 2026, 'Agronomy', '10.3390/agronomy16131251', 'https://doi.org/10.3390/agronomy16131251', 'https://www.mdpi.com/2073-4395/16/13/1251', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'An air-assisted sprayer is a primary tool for pest and disease control in orchards. However, conventional systems often suffer from insufficient deposition at the canopy top and poor coverage on the abaxial leaf surfaces, which are highly susceptible to pests and diseases. To address this limitation, a centrifugal air-assisted spraying system was developed to generate finer droplets and improve deposition distribution within tree canopies, particularly on the abaxial surfaces. Vertical deposition tests were conducted to characterize the droplet distribution pattern of the system. Single-unit spray tests were then performed under Foliage Area Volume Density (FAVD, the foliage area per unit canopy volume) of 3.3 and 1.4 m2·m−3, and three outlet air velocities (4, 8, and 11 m·s−1) to evaluate the effects of these variables on coverage and droplet density. Comparative experiments between the centrifugal and a conventional hydraulic system were also carried out at the same flow rate (3.6 L·min−1), as well as at a 30% reduced application rate for the centrifugal system. The results showed that the droplet distribution pattern followed a normal distribution and correlated well with the spindle-shaped pear tree canopy. At both FAVD levels, an air velocity of 8 m·s−1 produced superior leaf coverage compared with 4 and 11 m·s−1. At the same flow rate, the centrifugal system achieved significantly higher coverage on the abaxial surfaces of outer canopy leaves than the hydraulic system. Remarkably, even with a 30% reduction in application volume, the centrifugal system maintained coverage and droplet density comparable to those of the hydraulic system at its full rate. We conclude that the centrifugal air-assisted orchard spraying system effectively improves pesticide deposition distribution within pear tree canopies, with particular advantages in depositing droplets on the abaxial leaf surfaces. Future work will include a systematic assessment of spray drift potential to further evaluate its field applicability and environmental compatibility.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa488240-c89a-4dc5-9ab1-c584b8b3e601', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Development of Mycoinsecticides: Advances in Formulation, Regulatory Challenges and Market Trends for Entomopathogenic Fungi', 'Couceiro JC, Wood MJ, Papadopoulos A, Silva JJ, Vontas J, Dimopoulos G', 2025, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof12010007', 'https://doi.org/10.3390/jof12010007', 'https://europepmc.org/articles/PMC12843292?pdf=render', NULL, NULL, 38, NULL, 'other', 1, 'cc by', 'Bioinsecticides offer eco-friendly alternatives to chemical insecticides and thereby meet the need for sustainable pest control. Entomopathogenic fungi (EPF) represent one of the core classes of microbial insecticides, distinguished by their advantageous contact-based mode of action. Several products have been successfully commercialized, and with continuing improvements to the technology, the market size for EPF continues to grow. The translation of EPF into reliable field performers relies upon formulation technologies that ensure product quality, stability, virulence, and cost-effectiveness. Current formulations comprise diverse solid and liquid states (e.g., wettable powders, oil dispersions) that deliver a range of propagules (conidia, blastospores, microsclerotia). While advanced approaches like nanoparticle encapsulation show promise, some limitations hinder their widespread use. Major constraints include maintaining fungal viability during storage/transport and protecting propagules from harsh environmental factors post-application. Regulatory requirements also present significant barriers to widespread uptake. Addressing these formulation challenges through continued research is essential for advancing mycoinsecticide technology and increasing their contribution to integrated pest management. This review aims to present the latest scientific advances in EPF formulation technologies and application strategies, alongside an overview of current regulatory frameworks and an up-to-date analysis of registered microbial biopesticide products in some of the world''s largest markets.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf129e6f-c4ab-44bd-9ffe-a6eac5ab762b', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Drone-based herbicide application: opportunities and challenges', 'S. Olumide Daramola, Thomas R. Butts, Simerjeet Virk, Bholuram Gurjar, Ubaldo Torres, Muthukumar Bagavathiannan, J. Anita Dille, Augustine K. Obour', 2026, 'Weed Technology', '10.1017/wet.2026.10088', 'https://doi.org/10.1017/wet.2026.10088', 'https://www.cambridge.org/core/product/identifier/S0890037X26100888/type/journal_article', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Advancements in precision agriculture have driven the development of using drones to apply herbicides, offering the potential to address challenges associated with current application methods and improve weed management. This review synthesizes current research on spray drones to develop broad-use recommendations and identify challenges and knowledge gaps. Although spray drones cannot carry a heavy herbicide load compared with ground-based (high-volume backpack or tractor-mounted) sprayers, studies have reported comparable or superior weed control in addition to herbicide cost savings by using drones. However, spray drone performance is highly sensitive to operational parameters, because spray distribution and coverage/deposition are strongly affected by flight height and speed, carrier volume, nozzle design, crop growth stage, weed, and weather conditions. The bell-shaped curve of a single-pass spray pattern, which results in most spray deposition occurring directly under the drone, coupled with advances in imaging, remote sensing, and machine learning, demonstrate the strong potential of using drones for site-specific weed management purposes. Vegetation indices, multispectral imagery, canopy height models, and Light Detection And Ranging (LiDAR) technology have enabled crop-weed discrimination, though accuracy varies with species, growth stage, and image resolution. Deep-learning models such as You Only Look Once (YOLO), Residual Neural Network (ResNet), and Mask Region-based Convolutional Neural Network (Mask R-CNN) are good at weed detection, they remain limited by the quality of training data and their accuracy is reduced when they must detect small, overlapping, or dense weed populations. Spray drone–based offline mapping has enabled substantial herbicide savings by delineating weed patches, whereas real-time weed detection is constrained by onboard processing limits, battery life, and lower spatial resolution at operational flight heights. Ground-based smart sprayers offer higher real-time detection precision but they lack the field accessibility advantages of spray drones. Despite their potential, spray drones face challenges that include limited payload, off-target movement of herbicides, short battery life, regulatory challenges, and extensive license and complex software and calibration requirements. The downwind spray drift potential from drone applications is greater than ground applications but smaller than it is from piloted vehicles. An upwind swath offset is an ideal best management practice for reducing off-target herbicide movement to susceptible areas from both piloted and drone equipment. Future research should evaluate spray drones within integrated weed management systems, focusing on preemergence and foliar-applied contact herbicides, adjuvant use, and environmental and operational interactions to develop spray drone–specific guidelines and optimize spray performance.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7ec89754-1d82-4a45-af89-74cd370b5e4f', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Droplet Deposition and Control of Planthoppers of Different Nozzles in Two-Stage Rice with a Quadrotor Unmanned Aerial Vehicle', 'Pengchao Chen, Yubin Lan, Xiaoyu Huang, Haixia Qi, Guobin Wang, Juan Wang, Linlin Wang, Hanxiang Xiao', 2020, 'Agronomy', '10.3390/agronomy10020303', 'https://doi.org/10.3390/agronomy10020303', 'https://www.mdpi.com/2073-4395/10/2/303', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Previous studies have confirmed that choosing nozzles that produce coarser droplets could reduce the risk of pesticide spray drift, but this conclusion is based on a large volume of application, and it is easy to ignore how this impacts the control effect. The difference from the conventional spray is that the carrier volume of Unmanned Aerial Vehicle (UAV) is very limited. Little was known about how to choose suitable nozzles with UAV&#8217;s limited volume to ensure appropriate pest control. Droplet deposition with the addition of adjuvant and the LU110-010, LU110-015, and LU110-020 nozzles and control of planthoppers within nozzles treatments were studied by a quadrotor UAV in rice (Tillering and Flowering stages). Allura Red (10 g/L) was used as a tracer and Kromekote cards were used to collect droplet deposits. The results indicate that the density of the droplets covered by the LU110-01 nozzle is well above other treatments, while the differences in droplet deposition and coverage are not significant. The deposition and coverage were improved with the addition of adjuvant, especially in LU110-01 nozzles&#8217; treatment. The control effects of rice planthoppers treated by LU110-01 nozzle were 89.4% and 90.8% respectively, which were much higher than 67.6% and 58.5% of LU110-020 nozzle at 7 days in the Tillering and Flowering stage. The results suggest that selecting a nozzle with a small atomizing particle size for UAV could improve the control effect of planthoppers.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44dd90ed-e028-47ae-81cb-6825738ceee2', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Effect of Image Segmentation Thresholding on Droplet Size Measurement', 'Emanuele Cerruto, Giuseppe Manetto, Salvatore Privitera, Rita Papa, Domenico Longo', 2022, 'Agronomy', '10.3390/agronomy12071677', 'https://doi.org/10.3390/agronomy12071677', 'https://www.mdpi.com/2073-4395/12/7/1677', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Droplet size spectrum is a key factor in pesticide application because it affects the biological efficacy of a treatment in terms of target coverage, environmental impact in terms of evaporation, drift and run-off, and operator’s safety in terms of inhalation and dermal exposure. Droplet measurement methods based upon image analysis have to face the “binarization” or “segmentation” process, by which the objects of interest (the droplets) are extracted from the background. Segmentation is carried out by choosing appropriate threshold values, mostly based on the operator’s experience. In this study, images of droplets of an air induction nozzle TVI 8002 at four pressures (0.3, 0.5, 1.0, and 1.5 MPa) were obtained using the liquid immersion method. Each image was processed multiple times, firstly by using a “reference” threshold value based on the operator’s experience and then by using 11 different threshold values, chosen in the range of around ±5% of the reference threshold and based upon the average gray level of the image. For each threshold value, the corresponding spray parameters (volumetric diameters, mean diameters, Sauter diameters, and numeric diameters) were analyzed. The results showed that spray parameters had a statistically significant linear trend with respect to the threshold values in most cases. However, in absolute terms, variations were almost always less than 1.0% of reference values. This result allows considering the image acquisition system used in the present study as an automatic tool able to select the threshold according to the gray level of the image, making the whole segmentation process faster, more objective, and less dependent on the operator’s experience.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9f8b9907-5739-47e4-9812-2b585f37e713', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Effect of spraying drone flight parameters on vineyard canopy coverage and droplet deposition', 'Vasilis Psiroukis, Aikaterini Kasimati, Konstantinos Nychas, Konstantinos Dagres, George Papadopoulos, Evangelos Anastasiou, Spyros Fountas', 2026, 'Smart Agricultural Technology', '10.1016/j.atech.2025.101730', 'https://doi.org/10.1016/j.atech.2025.101730', 'http://www.sciencedirect.com/science/article/pii/S277237552500961X', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Unmanned Aerial Vehicles (UAVs) are increasingly promoted as alternatives to conventional plant protection product (PPP) spraying in vineyards, yet limited evidence exists on how flight parameters and application configurations influence spray deposition under real vineyard conditions, especially within Europe. This study evaluated the performance of a DJI Agras T16 spraying drone across eight operational configurations combining two flight altitudes (2.0 and 2.5 m AGL), two flight speeds (1.0 and 1.5 m/s), and two aircraft positioning strategies (over-row and inter-row). Spray deposition, canopy coverage, and ground losses were quantified using water-sensitive papers (WSPs) positioned at multiple canopy heights and ground locations, while meteorological conditions were monitored, following methodologies adapted from the ISO 22,866/22,522 protocols. Results showed strong interactions among altitude, speed, flight path, and wind parameters, with over-row treatments concentrating deposition in upper canopy layers and inter-row treatments producing more homogeneous profiles but higher sensitivity to wind direction. Lower altitude flights (2.0 m) combined with slower speed (1 m/s) substantially increased ground deposition regardless of UAV positioning, whereas higher altitude (2.5 m) and speed values (1.5 m/s) reduced spray losses to the ground. The increase in pump output associated with higher speed under a constant application rate is expected to produce finer droplets, which can enhance penetration but may also elevate in-field drift risk. These findings demonstrate that UAV spraying performance depends on integrated optimisation of operational settings and environmental conditions. The results provide practical guidance for improving drone-based vineyard spraying and highlight the need for updated EU regulatory frameworks tailored to UAV application characteristics.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c9918e7-75ac-4e4c-aa34-dde4ee38e49e', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Efficacy evaluation of pneumatic solid set canopy delivery system to control powdery mildew (Erysiphe necator) in Washington vineyards', 'Bhalekar DG, Mozzanini E, Sahni RK, Moyer MM, Khot LR', 2026, 'Pest management science', '10.1002/ps.70596', 'https://doi.org/10.1002/ps.70596', 'https://europepmc.org/articles/PMC13071192?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'BackgroundIn this study, a previously optimized pneumatic spray delivery (PSD)-based solid set canopy delivery system (SSCDS) was compared with an airblast sprayer (grower control [GC]) for the delivery of fungicides in the management of powdery mildew (Erysiphe necator) in vineyards. For 2023 and 2024 growing seasons, spray coverage was quantified for each application date and treatment. Visual disease severity on clusters and leaves was assessed five times per season. The accumulated area under the disease progression curve (AUDPC) was developed from these ratings.ResultsOver two seasons, spray coverage for PSD-SSCDS treatment ranged from 16.7% to 32.7%, whereas GC achieved coverage between 39.9% and 62.9%. The average difference in maximum cluster and foliar disease severity between GC and PSD-SSCDS was 5.5% and 14.2%, respectively.ConclusionsDespite lower spray coverage in PSD-SSCDS, the accumulated AUDPC for cluster disease severity was similar to GC treatments in both growing seasons. However, foliar disease severity differed significantly, with GC showing less disease than PSD-SSCDS. These study findings indicate that optimal emitter selection is crucial for achieving enhanced spray performance and effective disease control using the PSD-SSCDS technology in vineyards. Both fungicide spray treatments effectively protected clusters from powdery mildew, indicating PSD-SSCDS as an emergent alternative spray technology. © 2026 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fea92d83-b862-46c2-bcf2-09563c2947df', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Efficiency of a non-recycling postharvest fungicide drencher to enhance management of apple decay and food safety', 'Amiri A, Murphy CM, Hoheisel GA, Haskell CL, Critzer F', 2024, 'Frontiers in microbiology', '10.3389/fmicb.2024.1509368', 'https://doi.org/10.3389/fmicb.2024.1509368', 'https://europepmc.org/articles/PMC11693708?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'IntroductionRecycling drenchers used to apply postharvest fungicides in pome fruit may spread microorganisms, i.e., plant and foodborne pathogens, that increase fruit loss and impact food safety.MethodsA non-recycling field drencher (FD), which drenches unstacked bins of fruit, was compared to a commercial recycling packinghouse drencher (CPD) for fruit coverage, fungicide residues, postharvest diseases control and spread of plant pathogens, total coliforms and generic Escherichia coli. A mixture of fludioxonil (FDL) and thiabendazole (TBZ) was used in 2021, while pyrimethanil (PYR) was applied in 2022 to alternate fungicides.ResultsThe overall spray coverage assessed with pyranine was not significantly different between the FD and CPD. The residue levels of FDL and TBZ were similar between the two methods on Honeycrisp apples at the top, middle, and the bottom of the bins, whereas the residue levels of PYR were significantly lower at the bottom of the bins treated through the FD. The density of plant pathogens and overall disease incidence were similar on apples drenched through both systems in 2021 and significantly lower in FD-treated apples in 2022. The incidence of blue mold, the most important postharvest disease caused by Penicillium spp., was significantly lower in apples treated through the FD in both years. The levels of total coliforms and generic E. coli were significantly higher in fungicide solutions collected from the CPD compared to the FD. Total coliforms increased significantly on apples treated via the CPD but not on apples treated through the FD.DiscussionFindings from this study suggest that the new non-recycling drencher has potential as an alternative to recycling packinghouse drenchers in reducing the spread of plant and foodborne pathogens.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('61c8e02c-47e3-46f2-9ef6-4aa1903b30ea', '61a86171-4f1c-4450-b6f2-b03b74254244', 'Effect of Sowing Date, Planting Pattern and Foliar Application of Boron on Seed Yield of Local Beans (Pachbaghela) (Phaseolus vulgaris L.) in Guilan Province, Iran', 'Saleh Hassanzadeh, Masoud Esfahani, Ali Aalami', 2025, 'پژوهش‌های حبوبات ایران', '10.22067/ijpr.2025.92223.1107', 'https://doi.org/10.22067/ijpr.2025.92223.1107', 'https://ijpr.um.ac.ir/article_46847_eed2c82361d3923a13a3dba8d10e8715.pdf', NULL, NULL, 16, NULL, 'other', 1, 'open access (DOAJ)', 'IntroductionLegumes are the second most important source of human food after cereals and are considered the primary source of plant protein due to their high protein content. In addition to providing food for humans and livestock, legumes enhance the fertility of agricultural soils when grown in rotation with other crops, owing to their symbiosis with nitrogen-fixing bacteria. Common bean (Phaseolus vulgaris L.) is the most important legume used for direct human consumption. Achieving high seed yield is one of the main goals of cultivating this plant, and appropriate agronomic management practices-such as determining the sowing date, row spacing, plant spacing, and providing essential nutrients-result in high biological and economic performance. Therefore, in this experiment, to find solutions to increase the yield of local beans in Guilan province, the appropriate sowing date, sowing pattern, and the effect of boron foliar application on bean growth and yield were investigated. Materials and MethodsThis research was conducted as a factorial experiment in the form of a randomized complete block design (RCBD) with four replications during the spring and summer of 2023 in the Rudbaneh section of Lahijan, Iran. The factors examined in this experiment included sowing patterns at three levels: rectangle pattern (20×31 cm), rhombus pattern (23×27 cm), and square pattern (25×25 cm), with a constant density of approximately 16 plants per square meter. Additionally, foliar application of boron at a concentration of 0.1% was compared to no boron application. These factors were evaluated in two experiments conducted on April 25th (spring) and August 29th (summer). Results and DiscussionThe results of the combined variance analysis showed that the effect of the sowing date was significant on all tested traits except for seed protein content. These traits included plant height, number of secondary branches, number of pods per plant, percentage of fertile pods, 100-seed weight, biological yield, seed yield, seed formation rate, seed filling rate, yield formation rate, and vegetative growth rate. In contrast, sowing pattern treatments significantly affected only plant height, the number of secondary branches, and 100-seed weight, with no significant impact on the other measured traits. In comparison, boron foliar application had a significant effect on a wide range of traits, including plant height, number of pods per plant, percentage of fertile pods, 100-seed weight, biological yield, seed yield, seed formation rate, seed filling rate, yield formation rate, vegetative growth rate, and seed protein content. The results showed that seed yield at the spring sowing date averaged 348.3 g.m-2, which was significantly higher than the summer sowing date average of 204.0 g.m-2 (a 41% increase). Boron foliar application also significantly increased seed yield, with an average of 307.9 g.m-2 compared to 244.5 g.m-2 without boron (a 20% increase). However, sowing patterns had no significant effect on seed yield. The components of seed yield, including the number of pods per plant and 100-seed weight, were higher at the spring sowing date, with averages of 15.6 pods and 42.8 g, respectively. These values represented increases of 37% and 6%, respectively, compared to the summer sowing date. Boron foliar application also resulted in a 16% increase in the number of pods per plant and a 5% increase in 100-seed weight, with averages of 13.8 pods and 42.6 g, respectively, compared to no boron application. Additionally, the square sowing pattern achieved a higher 100-seed weight, averaging 41.8 g, compared to the rhombus and rectangle sowing patterns. ConclusionsBased on the results of this experiment, sowing local beans of Guilan in the spring season, using the square sowing pattern, and applying boron foliar application were superior in terms of seed yield and growth indices compared to the summer sowing date, rectangle, and rhombus planting patterns, and n', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.771417+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eb3815ac-8804-4054-9462-307187eb4003', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Evaluation of the deposition and distribution of spray droplets in citrus orchards by plant protection drones', 'Yan Y, Lan Y, Wang G, Hussain M, Wang H, Yu X, Shan C, Wang B', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1303669', 'https://doi.org/10.3389/fpls.2023.1303669', 'https://europepmc.org/articles/PMC10716228?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Plant protection drone spraying technology is widely used to prevent and control crop diseases and pests due to its advantages of being unaffected by crop growth patterns and terrain restrictions, high operational efficiency, and low labor requirements. The operational parameters of plant protection drones significantly impact the distribution of spray droplets, thereby affecting pesticide utilization. In this study, a field experiment was conducted to determine the working modes of two representative plant protection drones and an electric backpack sprayer as a control to explore the characteristics of droplet deposition with different spray volumes in the citrus canopy. The results showed that the spraying volume significantly affected the number of droplets and the spray coverage. The number of droplets and the spray coverage area on the leaf surface were significantly increased by increasing the spray volume from 60 L/ha to 120 L/ha in plant protection drones. Particularly for the DJI T30, the mid-lower canopy showed a spray coverage increase of 52.5%. The droplet density demonstrated the most significant variations in the lower inner canopy, ranging from 18.7 droplets/cm2 to 41.7 droplets/cm2 by XAG V40. From the deposition distribution on fruit trees, the plant protection drones exhibit good penetration ability, as the droplets can achieve a relatively even distribution in different canopy layers of citrus trees. The droplet distribution uniformity inside the canopy is similar for XAG V40 and DJI T30, with a variation coefficient of approximately 50%-100%. Compared to the plant protection drones, the knapsack electric sprayer is suitable for pest and disease control in the mid-lower canopy, but they face challenges of insufficient deposition capability in the upper canopy and overall poor spray uniformity. The distribution of deposition determined in this study provides data support for the selection of spraying agents for fruit trees by plant protection drones and for the control of different pests and diseases.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('409a7cae-9d53-41af-a86d-e7af27832028', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'HOW DO THE DROPLET SPECTRUM UNIFORMITY AND SPRAY VOLUME OF FLAT-FAN NOZZLES INFLUENCE FUNGICIDE SPRAY DISTRIBUTION QUALITY IN SOYBEANS?', 'Fabiano Griesang, Marcelo da C. Ferreira, Ana B. D. Spadoni, Jaqueline F. Della Vechia, Renata T. da S. Santos, Cícero A. M. dos Santos', 2022, 'Engenharia Agrícola', '10.1590/1809-4430-eng.agric.v42n2e20210122/2022', 'https://doi.org/10.1590/1809-4430-eng.agric.v42n2e20210122/2022', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-69162022000200211&tlng=en', NULL, NULL, 10, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT Droplet spectrum quality is essential to effectively control crop pests and diseases. This study aimed to characterize the droplet uniformity of the eight most popular flat-fan nozzles used by Brazilian farmers and relate it to their spraying quality. The method consisted of using a laser-diffraction-size analyser to determine droplet-size distribution for three fungicide spray solution compositions and at two flow rates. Our goal was to identify the nozzle models with the highest and lowest Span values for each fungicide spray solution. In the first stage, the results confirmed differences in uniformity and droplet size for both nozzle models and flow rates applied. However, these differences were not the same for both flow rates nor constant for all fungicide spray solution compositions. Through field experiments, we could understand how the combination of flow rate, nozzle model, and spray solution composition provides different results and application efficiencies. Based on our results, we can state that Span has an impact on the number of droplets prone to drift and quality of canopy coverage. Therefore, this droplet-quality parameter should be considered and displayed in nozzle catalogues to improve nozzle selection and sprayer configuration, thus enhancing application quality.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff05c994-d4c1-4727-a528-fac5726d86ca', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Navigating the future of nano-pesticides: A perspective on design, efficacy, mechanisms, and environmental stewardship', 'Deng X, Zhu F, Qiao H, Shangguan W, Yu Q, Sharma S, Shanmugam V, Deng Y', 2026, 'iMeta', '10.1002/imt2.70129', 'https://doi.org/10.1002/imt2.70129', 'https://europepmc.org/articles/PMC13377412?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'Nano-pesticides are driving a paradigm shift toward sustainable plant protection. This review systematically synthesizes recent advances across four interconnected domains: (i) intelligent formulation design for targeted delivery and controlled release; (ii) interfacial behavior regulation to enhance foliar deposition; (iii) multi-omics elucidation of synergistic efficacy and molecular interactions; and (iv) environmental fate management, including risk mitigation and microbiome remediation. By integrating these multiscale innovations, the field is advancing nano-enabled crop protection from laboratory research toward field application. Collectively, this convergence provides a scientific foundation and interdisciplinary roadmap needed to build next-generation agricultural systems that are resource-efficient and ecologically compatible.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f79e7801-785f-44c8-ada4-03e91f86c5ce', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Omics-driven plant breeding through phenomics-enviromics crosstalk', 'Li H, Gao S, Gebrewahid TW, Li WX, Wang J, Han Z, Reynolds MP, Araus JL', 2026, 'Nature communications', '10.1038/s41467-026-73097-x', 'https://doi.org/10.1038/s41467-026-73097-x', 'https://europepmc.org/articles/PMC13279992?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by-nc-nd', 'Genomics, including all molecular omics, is driven by molecular data, while phenomics and enviromics rely on phenotypic and environmental data. Yet phenotyping is often conducted under poorly characterized environments, limiting the interpretation of phenotypic variation and constraining genetic gain. Integrating high-throughput phenotyping with envirotyping is hence vital to resolve genomic effects. This perspective introduces phenomics-enviromics (PE) crosstalk as a framework for coordinated data collection and integration to advance omics and precision plant breeding. Satellites, unmanned aerial and ground vehicles, and controlled indoor facilities, combined with AI-assisted typing technologies and modeling, are establishing the basis for synchronous, high-throughput PE crosstalk to enhance interpretability, prediction, and crop resilience.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('969eb5bd-f231-4f8a-a0a8-e5fbaf2f71df', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Optimization of low-pressure solid cone nozzle parameters for pesticide application on trellised crops in plastic greenhouses', 'TANG Xiuying, SUN Zhongqing, CHENG Bin, LIU Zhenglin, WANG Pei, ZHANG Yonghua, CHEN Lichang', 2026, 'Guan''gai paishui xuebao', '10.13522/j.cnki.ggps.2025178', 'https://doi.org/10.13522/j.cnki.ggps.2025178', 'https://www.ggpsxb.com/jgpxxben/ch/reader/view_abstract.aspx?file_no=20260107&flag=1', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', '【Background and Objective】Pesticide spraying operations for trellised crops in plastic greenhouses are constrained by complex canopy structures and limited operational space, leading to uneven pesticide deposition, high drift loss, and reduced control efficacy. Focusing on low-pressure solid cone nozzle, this paper addresses these challenges and proposes a method to optimize its application and operation parameters.【Method】A combination of high-speed imaging and water-sensitive paper was used in the experiment to characterize the droplet morphology; a time-based collection method was employed to measure nozzle flow rate. Multiple regression analysis and analysis of variance (ANOVA) were applied to determine the significance of influencing factors (nozzle orifice diameter and spray pressure) on spray performance.【Result】①Spray angle increased with both nozzle orifice diameter and spray pressure. When the nozzle orifice diameter was 0.5-0.6 mm and the spray pressure was maintained at 0.55-0.75 MPa, the spray angle remained within the optimal range of 60°-80°, facilitating uniform canopy coverage and drift reduction. ②Analysis of droplet size parameters (volume median diameter, VMD; Dv10; Dv90; relative span, RS) showed that the interaction between nozzle orifice diameter and spray pressure had a statistically significant effect on VMD. When the nozzle orifice diameter was 0.3-0.6 mm and spray pressure was 0.65-0.85 MPa, VMD values fell within the biologically effective range of 30-150 μm, and RS values were consistently below 1.3, indicating a concentrated and uniform droplet size distribution that favours effective pesticide deposition. ③Flow rate tests revealed that when the orifice diameter was 0.5-0.6 mm and spray pressure was 0.65-0.85 MPa, the actual flow rate was highly consistent with the theoretical value; additionally, the effect of nozzle orifice diameter on flow rate was statistically significant. Our results indicated that optimal parameters were nozzle orifice diameter 0.5-0.6 mm and spray pressure 0.65-0.75 MPa.【Conclusion】Our analysis showed that the nozzle configuration with a 0.6 mm orifice diameter and 0.65 MPa spray pressure were optimal for pesticide spraying on trellised crops in plastic greenhouses.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe2b2326-ddd9-48a1-94b5-b3aeb33ad0b3', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Reducing environmental exposure to PPPs in super-high density olive orchards using UAV sprayers', 'Sánchez-Fernández L, Barrera-Báez M, Martínez-Guanter J, Pérez-Ruiz M', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1272372', 'https://doi.org/10.3389/fpls.2023.1272372', 'https://europepmc.org/articles/PMC10794436?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'The increasing demand for optimizing the use of agricultural resources will require the adoption of cutting-edge technologies and precision farming management. Unmanned Aerial Vehicle (UAV) sprayers seem promising due to their potential to perform precision or spot spraying, particularly in woody crop environments where total surface spraying is unnecessary. However, incorporating this technology is limited by the lack of scientific knowledge about the environmental risks associated with UAV sprayers and the strict legal framework. Nonetheless, these spraying systems'' characteristic downwash airflow and the limited swath width can potentially mitigate drift in hedgerow crops. During our study we performed comparative studies aimed to compare the airborne drift, soil, and crop depositions between a conventional orchard sprayer and a UAV sprayer in a commercial superhigh-density orchard in the South Iberian Peninsula in 2022. Our findings reveal that, in superhigh-density olive orchards, the UAV sprayer presents a substantial reduction in airborne drift, while soil depositions showed no significant differences compared to those of a conventional terrestrial orchard sprayer. Crop depositions were significantly lower when utilizing the UAV sprayer. These results suggest that introducing UAV spraying technology in Mediterranean agricultural systems, under specific scenarios, can effectively reduce the environmental impact of crop spraying and encourage the responsible use of plant protection products (PPPs).', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44b0e201-2be0-4376-ad03-1741e7b10dc4', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Remotely Piloted Aircraft Spraying in Coffee Cultivation: Effects of Two Spraying Systems on Drop Deposition', 'Aldir Carpes Marques Filho, Lucas Santos Santana, Gabriel Araújo e Silva Ferraz, Rafael de Oliveria Faria, Adisa Jamiu Saka, Josiane Maria da Silva, Mozart Santos Santana, Henrique Canestri Rafael', 2025, 'AgriEngineering', '10.3390/agriengineering7110379', 'https://doi.org/10.3390/agriengineering7110379', 'https://www.mdpi.com/2624-7402/7/11/379', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The use of Remotely Piloted Aircraft (RPA) for spraying coffee crops has expanded due to their practicality and cost reduction. This study aimed to evaluate spray rate effects on coffee crops using two RPA (T10 and T20). The study was conducted on a commercial farm with 10-year-old Coffea arabica Catucaí Amarelo. Two aircraft were used, T1 (hydraulic) and T2 (rotary nozzles). The application rates were established at 25 and 50 L ha−1. The application quality was obtained by attaching Water-Sensitive Papers (WSPs) to the upper, middle, and lower parts of coffee trees, inside and outside the plants, in addition to the inter-row areas. The statistical Nested Crossed Design was applied to analyze the dataset for the experimental field with three distinct factors (RPA, application rate, and WSP position) and four replications. WSP position was the most determinant factor across all design effects, followed by RPA. The external layers of leaves received more droplets than internal parts of coffee trees. The WSP position information indicated that no droplets reached the middle interior parts of the plants or underneath them. The inter-row positions (soil) received significantly more drops than the coffee plants, regardless of application rate or RPA. The potential for drift to the soil was high in both applications. The Potential Drift Risks were more significant for RPA T2. Future studies may deepen understanding of the relationship between coverage and specific application models for coffee farming, as traditional application methods require improvements.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9e265c13-e7f4-4d41-a60c-98b49fc520db', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Season Long Pest Management Efficacy and Spray Characteristics of a Solid Set Canopy Delivery System in High Density Apples', 'Paul Owen-Smith, John Wise, Matthew  J. Grieshop', 2019, 'Insects', '10.3390/insects10070193', 'https://doi.org/10.3390/insects10070193', 'https://www.mdpi.com/2075-4450/10/7/193', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Solid set canopy delivery systems (SSCDS) are a novel foliar agrochemical delivery system designed as an alternative for airblast sprayers in high density fruit production. This study tested the pest management potential, coverage, and chemical deposition of an SSCDS using commercially available microsprinkler components over the course of a growing season. Spray coverage and deposition for a representative airblast sprayer and SSCDS were evaluated using water sensitive paper and tartrazine dye, respectively. Foliar sprays for pest suppression were applied through both systems, and damage assessments were taken at the midpoint and end of the growing season. SSCDS sprays demonstrated similar levels of coverage on the adaxial leaf surface as airblast sprays, but significantly lower coverage on the abaxial surface. However, mean levels of foliar chemical deposition was generally higher in the SSCDS. Evaluations found minimal arthropod and fungal damage in both airblast and SSCDS treated plots compared to untreated trees. The SSCDS was shown to be a viable alternative to the airblast, with inherent advantages such as rapid application time and improved worker safety. Furthermore, higher deposition on SSCDS treated foliage supports the hypothesis that SSCDS provide a higher droplet capture rate in the canopy, with less off-target loss and drift than airblast sprayers.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c128e26-a2af-4cc5-bfb4-390dcd3f07ac', '38cd8d1c-5ea7-4769-a015-37060dce6d0c', 'Irrigation scheduling for barley in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5421622', 'https://open.alberta.ca/dataset/bf5edbf8-d63b-4dca-959a-ecc2cea4c50c/resource/0da7372d-6cb8-4185-b72e-32a0978fee73/download/5421622-2011-agri-facts-irrigation-scheduling-barley-southern-alberta-114-561-1-2011-04.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With good irrigation management, a barley crop can have high yield and quality potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('055bce91-7c77-4d59-9220-cd6f3dba8109', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Towards practical object detection for weed spraying in precision agriculture', 'Darbyshire M, Salazar-Gomez A, Gao J, Sklar EI, Parsons S', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1183277', 'https://doi.org/10.3389/fpls.2023.1183277', 'https://europepmc.org/articles/PMC10657197?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Weeds pose a persistent threat to farmers'' yields, but conventional methods for controlling weed populations, like herbicide spraying, pose a risk to the surrounding ecosystems. Precision spraying aims to reduce harms to the surrounding environment by targeting only the weeds rather than spraying the entire field with herbicide. Such an approach requires weeds to first be detected. With the advent of convolutional neural networks, there has been significant research trialing such technologies on datasets of weeds and crops. However, the evaluation of the performance of these approaches has often been limited to the standard machine learning metrics. This paper aims to assess the feasibility of precision spraying via a comprehensive evaluation of weed detection and spraying accuracy using two separate datasets, different image resolutions, and several state-of-the-art object detection algorithms. A simplified model of precision spraying is proposed to compare the performance of different detection algorithms while varying the precision of the spray nozzles. The key performance indicators in precision spraying that this study focuses on are a high weed hit rate and a reduction in herbicide usage. This paper introduces two metrics, namely, weed coverage rate and area sprayed, to capture these aspects of the real-world performance of precision spraying and demonstrates their utility through experimental results. Using these metrics to calculate the spraying performance, it was found that 93% of weeds could be sprayed by spraying just 30% of the area using state-of-the-art vision methods to identify weeds.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7c9f2ac0-88f7-4e9f-b666-359a3efed651', 'b9303e70-7c39-4be7-a261-2031eaa051be', 'Understanding real work situations to determine sprayer design occupational and environmental health criteria: a mixed methods study protocol', 'Jolly C, Aubert-Simard A, Burlet-Vienney D, Beauregard N, Feillou I, Godbout S, Albert M', 2026, 'BMC public health', '10.1186/s12889-026-26465-7', 'https://doi.org/10.1186/s12889-026-26465-7', 'https://europepmc.org/articles/PMC13005420?pdf=render', NULL, NULL, 10, NULL, 'canada', 3, 'cc by-nc-nd', 'BackgroundCanada''s agricultural sector included 189,874 farms in 2021, 15% of which were located in the province of Quebec. Farmers are exposed to a variety of hazards that can lead to acute or chronic health effects, particularly when it comes to pesticide use. Machinery is often implicated in occupational injury statistics. Studies point to shortcomings in the design of crop protection sprayers, impacting not only the health and safety of workers, but also the environment. Tree sprays are currently designed and manufactured outside Quebec in accordance with regulatory requirements developed in a context where occupational health and safety (OHS) criteria are not always given priority. Therefore, with a view to intrinsically preventing OHS risks, while considering production and environmental protection objectives, this project aims to determine design criteria for arboricultural sprayers based on the actual work experience of apple growers.Methods/designThis intervention research project will be conducted by an interdisciplinary team (e.g., ergonomics, engineering, agronomy) in collaboration with Les Producteurs de pommes du Québec [name of the provincial association representing Quebec apple growers], a provincial association representing apple growers. A mixed-method research design combining quantitative and qualitative methods will be deployed over three years. PHASE 1 aims to gather knowledge on sprayer design and use, relying on a variety of collection methods (e.g., literature review, semi-structured interviews, work activity observations, self-administered questionnaire) carried out iteratively. The data obtained will then be cross-referenced to prepare for PHASE 2. In this phase, exchange workshops will be held with apple growers and other stakeholders to target key points in the design of spraying systems for arboriculture.DiscussionThe expected results are design criteria for arboricultural sprayers, mainly guidelines which may be specific for certain points, to limit the exposure of agricultural workers to OHS risk, while considering environmental protection and production quality objectives. Knowledge gained from the project will inform apple growers, distributors, and manufacturers, whether for selection or modification of existing sprayers, or development of new products. Finally, design principles that could be transposed to other types of agricultural sprayers will be identified.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5035160d-0a85-49c0-b551-c63960b7d97b', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Afidopyropen, a novel insecticide originating from microbial secondary extracts', 'Horikoshi R, Goto K, Mitomi M, Oyama K, Hirose T, Sunazuka T, Ōmura S', 2022, 'Scientific reports', '10.1038/s41598-022-06729-z', 'https://doi.org/10.1038/s41598-022-06729-z', 'https://europepmc.org/articles/PMC8857236?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Afidopyropen, a novel insecticide, is a derivative of pyripyropene A, which is produced by the filamentous fungus Penicillium coprobium. Afidopyropen has strong insecticidal activity against aphids and is currently used as a control agent of sucking pests worldwide. In this study, we summarized the biological properties and field efficacies of its derivatives against agricultural pests using official field trials conducted in Japan. Afidopyropen showed good residual efficacies against a variety of aphids, whiteflies and other sucking pests under field conditions. Furthermore, toxicological studies revealed its safety profiles against nontarget organisms, such as the honeybee, natural enemies and other beneficial insects, as well as mammals. Thus, afidopyropen is a next-generation agrochemical for crop protection that has a low environmental impact.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e6c57101-883c-4f34-923a-bf855f7eb6dc', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Consumer Safety and Pesticide Residues: Evaluating Mitigation Protocols for Greengrocery', 'Popescu Stegarus DI, Oprita Cioara CM, Tamaian R, Niculescu VC', 2024, 'Journal of xenobiotics', '10.3390/jox14040088', 'https://doi.org/10.3390/jox14040088', 'https://europepmc.org/articles/PMC11587004?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'The application of pesticides remains a necessary measure for pest management in agriculture, particularly in the cultivation of fruits and vegetables. After harvest, the presence of pesticide residues in greengrocery (fruits and vegetables) is significantly influenced by various factors, including storage conditions, handling practices, and subsequent processing methods. The mitigation of these residues to levels compliant with regulated maximum thresholds ensures the safety of raw and processed fruits and vegetables for consumption. A contemporary survey of pesticide residues in greengrocery has gathered considerable attention from consumers, driven by concerns over the potential health risk of pesticide exposure. Consequently, consumers want to be extensively informed about household processing techniques to minimize associated risks. Meanwhile, a critical question arises: does household processing effectively eliminate pesticide residues? A comprehensive review of the literature reveals that conventional methods, such as washing and soaking, offer only limited reduction in residue levels, while emerging treatments, suitable both at household and industrial scale, demonstrate increased efficiency in residues mitigation. This study aims to emphasise the ubiquitous use of pesticides in crop cultivation while providing recommendations for the implementation of efficient treatment protocols to address residue concerns. Following upon available evidence and database mining, the worldwide purpose must be to outline agriculturally and economically viable strategies that prioritize both the health and safety of consumers, as well as the green cultivation and processing of fruits and vegetables.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c4b51c25-06f4-4b1d-9586-614000df4ccc', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Core and Differentially Abundant Bacterial Taxa in the Rhizosphere of Field Grown Brassica napus Genotypes: Implications for Canola Breeding', 'Taye ZM, Helgason BL, Bell JK, Norris CE, Vail S, Robinson SJ, Parkin IAP, Arcand M', 2019, 'Frontiers in microbiology', '10.3389/fmicb.2019.03007', 'https://doi.org/10.3389/fmicb.2019.03007', 'https://europepmc.org/articles/PMC6974584?pdf=render', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Modifying the rhizosphere microbiome through targeted plant breeding is key to harnessing positive plant-microbial interrelationships in cropping agroecosystems. Here, we examine the composition of rhizosphere bacterial communities of diverse Brassica napus genotypes to identify: (1) taxa that preferentially associate with genotypes, (2) core bacterial microbiota associated with B. napus, (3) heritable alpha diversity measures at flowering and whole growing season, and (4) correlation between microbial and plant genetic distance among canola genotypes at different growth stages. Our aim is to identify and describe signature microbiota with potential positive benefits that could be integrated in B. napus breeding and management strategies. Rhizosphere soils of 16 diverse genotypes sampled weekly over a 10-week period at single location as well as at three time points at two additional locations were analyzed using 16S rRNA gene amplicon sequencing. The B. napus rhizosphere microbiome was characterized by diverse bacterial communities with 32 named bacterial phyla. The most abundant phyla were Proteobacteria, Actinobacteria, and Acidobacteria. Overall microbial and plant genetic distances were highly correlated (R = 0.65). Alpha diversity heritability estimates were between 0.16 and 0.41 when evaluated across growth stage and between 0.24 and 0.59 at flowering. Compared with a reference B. napus genotype, a total of 81 genera were significantly more abundant and 71 were significantly less abundant in at least one B. napus genotype out of the total 558 bacterial genera. Most differentially abundant genera were Proteobacteria and Actinobacteria followed by Bacteroidetes and Firmicutes. Here, we also show that B. napus genotypes select an overall core bacterial microbiome with growth-stage-related patterns as to how taxa joined the core membership. In addition, we report that sets of B. napus core taxa were consistent across our three sites and 2 years. Both differential abundance and core analysis implicate numerous bacteria that have been reported to have beneficial effects on plant growth including disease suppression, antifungal properties, and plant growth promotion. Using a multi-site year, temporally intensive field sampling approach, we showed that small plant genetic differences cause predictable changes in canola microbiome and are potential target for direct and indirect selection within breeding programs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d61a025-8ec3-4677-9d15-2e1223c14270', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Deploying a Wireless Sensor Network to Track Pesticide Pollution in Kiu Wetland Wells: A Field Study', 'Mutunga T, Sinanovic S, Offiong FB, Harrison C', 2025, 'Sensors (Basel, Switzerland)', '10.3390/s25134149', 'https://doi.org/10.3390/s25134149', 'https://europepmc.org/articles/PMC12251821?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'Water pollution from pesticides is a major concern for regulatory agencies worldwide due to expensive detecting mechanisms, delays in the processing of results, and the complexity of the chemical analysis. However, the deployment of monitoring systems utilising the internet of things (IoT) and machine-to-machine communication technologies (M2M) holds promise in overcoming this major global challenge. In this current research, an IoT-based wireless sensor network (WSN) is successfully deployed in rural Kenya at the Kiu watershed, providing in situ pesticide detections and a real-time data visualisation of shallow wells. Kiu is an off-grid community located in an area of intensive agriculture, where residents face a high exposure to pesticides due to farming activities and a reliance on shallow wells for domestic water. The evaluation of path loss models utilising channel characteristics obtained from this study indicate a marked departure from the continuous signal decay with distance. Transmitted packets from deployed sensor nodes indicate minimal mutations of payloads, underscoring systems reliability and data transmission integrity. Additionally, the proposed design significantly reduces the time taken to deliver pesticide measurement results to relevant stakeholders. For the entire monitoring period, pesticide residues were not detected in the selected wells, an outcome validated with lab procedures. These results are attributed to prevailing dry weather conditions which limited the leaching of pesticides to lower layers reaching the water table.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8bfdb1ca-f7c6-49cf-a0b2-c03af03f0980', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Dinitroaniline Herbicide Resistance and Mechanisms in Weeds', 'Chen J, Yu Q, Patterson E, Sayer C, Powles S', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.634018', 'https://doi.org/10.3389/fpls.2021.634018', 'https://europepmc.org/articles/PMC8027333?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Dinitroanilines are microtubule inhibitors, targeting tubulin proteins in plants and protists. Dinitroaniline herbicides, such as trifluralin, pendimethalin and oryzalin, have been used as pre-emergence herbicides for weed control for decades. With widespread resistance to post-emergence herbicides in weeds, the use of pre-emergence herbicides such as dinitroanilines has increased, in part, due to relatively slow evolution of resistance in weeds to these herbicides. Target-site resistance (TSR) to dinitroaniline herbicides due to point mutations in α-tubulin genes has been confirmed in a few weedy plant species (e.g., Eleusine indica, Setaria viridis, and recently in Lolium rigidum). Of particular interest is the resistance mutation Arg-243-Met identified from dinitroaniline-resistant L. rigidum that causes helical growth when plants are homozygous for the mutation. The recessive nature of the TSR, plus possible fitness cost for some resistance mutations, likely slows resistance evolution. Furthermore, non-target-site resistance (NTSR) to dinitroanilines has been rarely reported and only confirmed in Lolium rigidum due to enhanced herbicide metabolism (metabolic resistance). A cytochrome P450 gene (CYP81A10) has been recently identified in L. rigidum that confers resistance to trifluralin. Moreover, TSR and NTSR have been shown to co-exist in the same weedy species, population, and plant. The implication of knowledge and information on TSR and NTSR in management of dinitroaniline resistance is discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c1bc6f8e-4a90-4168-8deb-00c9897c5ddd', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Emerging Invasive Weeds in Iran: Occurrence, Ecological Impacts, and Sustainable Management', 'Yousefi AR, Babaei S, Nosratti I, Zeidali E, Babaei M, Asadi Oskouei E, Saberi H, Redhu M', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14172611', 'https://doi.org/10.3390/plants14172611', 'https://europepmc.org/articles/PMC12430316?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Invasive weeds pose a growing threat to global biodiversity, ecosystem stability, and agricultural productivity with significant ecological and economic consequences. In Iran, the rapid spread of invasive species such as Boreava orientalis, Azolla spp., Ibicella lutea, Physalis divaricata, Picnomon acarna, Cynanchum acutum, Vicia hyrcanica, Eichhornia crassipes, and Ambrosia psilostachya has severely affected native ecosystems, disrupted ecological processes, and threatened food security. These species exhibit aggressive traits such as rapid maturity, high reproductive rates, seed dormancy, and allelopathy that enable them to outcompete native species and successfully invade and dominate delicate habitats. Despite their documented impacts, a critical gap remains in understanding their biology, ecology, and management, particularly in understudied regions like Iran. This review synthesizes current knowledge on major invasive weeds affecting Iranian agroecosystems, with a focus on their ecological impacts and the urgent need for sustainable management strategies. It presents an integrated framework that combines ecological, biological, and management perspectives to address invasiveness, particularly in highly adaptable species like B. orientalis and A. psilostachya. This review highlights the critical role of interdisciplinary collaboration, advanced technology, and community involvement in developing effective strategies. It offers practical guidance for researchers, policymakers, and agricultural stakeholders, serving as a model for managing invasive species in other vulnerable regions. Ultimately, it supports global efforts to safeguard biodiversity, improve crop productivity, and strengthen ecological resilience against the growing threat of invasive species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('873525f6-ce0e-49c8-b5ff-dea0eb17ff3e', '38cd8d1c-5ea7-4769-a015-37060dce6d0c', 'Irrigation scheduling for canola in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5421624', 'https://open.alberta.ca/dataset/6b8e19b1-d8a8-4977-aa37-bd39c98bd5fc/resource/02987f0c-b714-4522-b3c2-31807c7787db/download/5421624-2011-agri-facts-irrigation-scheduling-canola-southern-alberta-149-561-1-2011-04.pdf', NULL, NULL, 3, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With good irrigation management, a canola crop can have high yield and quality potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bbefc6b8-46df-48da-94f7-de7b97a70496', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Herbicide use and weed management strategies in hemp cultivation', 'Kaur N, Kumar A, Malik T, Girdhar M, Singh M, Singh R, Tariq M, Mohan A', 2025, 'Journal of cannabis research', '10.1186/s42238-025-00280-0', 'https://doi.org/10.1186/s42238-025-00280-0', 'https://europepmc.org/articles/PMC12083118?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Industrial hemp has experienced a resurgence in global cultivation due to its diverse applications in textiles, food, bioplastics, biofuels, and environmental benefits such as phytoremediation and carbon sequestration. However, optimizing hemp production remains challenging, particularly in weed management, where limited approved herbicides and varying regional weed pressures pose significant obstacles. Weed dynamics across different regions highlight the prevalence of problematic species like Chenopodium album and Amaranthus spp. While hemp''s rapid canopy closure and high planting densities can reduce herbicide dependence, early-season weed competition can significantly impact crop establishment and yield. This review explores the current state of weed management in hemp cultivation, highlighting cultural, mechanical, and chemical strategies. Additionally, it evaluates the efficacy and phytotoxicity of pre- and post-emergent herbicides. Recent trials indicate that pre-emergent pendimethalin is consistently safe across multiple studies, while post-emergent grass herbicides like quizalofop, clethodim, and fluazifop provide effective control with minimal crop injury. For broadleaf control, clopyralid and bromoxynil show relative safety, though varietal responses vary. The limited availability of registered herbicides underscores the need for continued research and regulatory advancements. The review identifies critical knowledge gaps, including limited understanding of variety-specific herbicide tolerance and regional weed dynamics. Current research priorities include systematic herbicide screening across varieties and regions, optimizing cultural practices, and developing herbicide-tolerant cultivars. By integrating these strategies, hemp can fulfil its potential as a sustainable and profitable crop, contributing to environmentally friendly agricultural systems. This review provides a foundation for future research and policy decisions to optimize weed management in hemp production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e71a7fc0-b8dc-48cf-a52c-dd618d21d27b', '46c98313-2d9c-4df7-b167-df13bc54d154', 'PEST-CHEMGRIDS, global gridded maps of the top 20 crop-specific pesticide application rates from 2015 to 2025', 'Maggi F, Tang FHM, la Cecilia D, McBratney A', 2019, 'Scientific data', '10.1038/s41597-019-0169-4', 'https://doi.org/10.1038/s41597-019-0169-4', 'https://europepmc.org/articles/PMC6761121?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Available georeferenced environmental layers are facilitating new insights into global environmental assets and their vulnerability to anthropogenic inputs. Geographically gridded data of agricultural pesticides are crucial to assess human and ecosystem exposure to potential and recognised toxicants. However, pesticides inventories are often sparse over time and by region, mostly report aggregated classes of active ingredients, and are generally fragmented across local or government authorities, thus hampering an integrated global analysis of pesticide risk. Here, we introduce PEST-CHEMGRIDS, a comprehensive database of the 20 most used pesticide active ingredients on 6 dominant crops and 4 aggregated crop classes at 5 arc-min resolution (about 10 km at the equator) projected from 2015 to 2025. To estimate the global application rates of specific active ingredients we use spatial statistical methods to re-analyse the USGS/PNSP and FAOSTAT pesticide databases along with other public inventories including global gridded data of soil physical properties, hydroclimatic variables, agricultural quantities, and socio-economic indices. PEST-CHEMGRIDS can be used in global environmental modelling, assessment of agrichemical contamination, and risk analysis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2a955874-50fb-42ac-a332-7cc4e45a8cba', '46c98313-2d9c-4df7-b167-df13bc54d154', 'Polyploidy and Mutagenic Germplasm Innovation in Minor Legumes: Paradigm Shift and Challenges from Model Crops to Mung Bean', 'Guo F, Ma C, Liu Y, Wang L, Li C', 2026, 'Plants (Basel, Switzerland)', '10.3390/plants15071051', 'https://doi.org/10.3390/plants15071051', 'https://europepmc.org/articles/PMC13074236?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Minor legume crops, including mung bean (Vigna radiata), cowpea, and adzuki bean, are crucial for global food security and sustainable agriculture, yet their genetic improvement has been hindered by narrow germplasm resources and lagging breeding technologies. This article systematically reviews the strategy of integrating polyploid breeding with mutagenic breeding as an innovative pathway to overcome the genetic bottlenecks of minor legumes. It focuses on insights gained from model plants and major legume crops like soybean and alfalfa regarding polyploid advantages and efficient mutagenesis techniques. Furthermore, it provides an in-depth analysis of the unique challenges and adaptation barriers encountered when transferring these paradigms to minor crops. Using mung bean as a representative case study, this review highlights specific challenges, including the creation of stable polyploid germplasm, the elucidation of complex regulatory mechanisms in polyploid genomes, and the technical bottlenecks in gene mapping and functional validation. The review also outlines future directions involving the integration of cutting-edge technologies-such as multi-omics, high-throughput phenomics, and gene editing-to establish a holistic research framework of "germplasm innovation-gene mapping-designer breeding". This integrated approach aims to advance the breeding practices of minor legumes into a new era of precision design.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fcabb37e-a10f-4bb0-bd46-cae868c041a8', '53c2d8d5-7a79-446a-af62-a54af1284742', 'Agronomic drivers of Tribenuron-methyl resistance in wild mustard (Sinapis arvensis) in dryland wheat fields of western Iran', 'Moradi F, Bagheri A, Mondani F, Nosratti I', 2026, 'PloS one', '10.1371/journal.pone.0358794', 'https://doi.org/10.1371/journal.pone.0358794', 'https://europepmc.org/articles/PMC13606969?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Understanding the impact of common agronomic practices on the evolution of herbicide resistance is essential for developing sustainable weed management strategies that incorporate non-chemical control methods. In this study, we investigated the frequency of Tribenuron-methyl (TBM) reduced-sensitivity in wild mustard (Sinapis arvensis L.) by analyzing survival patterns and their association with agronomic management across 313 dryland wheat fields in the Eslamabad-e-Gharb district, Kermanshah, Iran. The results showed that survival levels in the studied fields varied notably, with 47.3% exhibiting survival between 0% and 20%, 14.0% falling within the 20% to 30% range, and 38.7% showing survival above 30%, highlighting the diverse survival patterns across the region. Logistic regression analysis identified intensive TBM application as the strongest factor promoting survival proportion, with triennial applications (3×) over a five-year period increasing the risk of reduced-sensitivity in wild mustard more than tenfold (Exp(B)=10.651) compared to no use. The selection of wheat cultivar also played a significant role; using Azar-2 raised the survival by more than twofold (Exp(B)=2.218) relative to Sardari. Furthermore, field area significantly influenced survival dynamics, with larger farms (15 ha and more) showing higher mean survival proportions (42.1%) and greater frequencies of intensive TBM application. Conversely, incorporating chickpea into the crop rotation significantly reduced survival proportions. These findings highlight the necessity of adopting diversified agronomic practices-including herbicide rotation, crop rotation, and competitive cultivar selection-to mitigate herbicide resistance frequency. Furthermore, strengthening grower awareness regarding resistance mechanisms and improving the outreach of effective management protocols are critical.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b3cae75d-8bc1-41c5-ad58-f175020b2846', '53c2d8d5-7a79-446a-af62-a54af1284742', 'Functional Characterization and Genomic Analysis of the Chlorantraniliprole-Degrading Strain Pseudomonas Sp. GW13', 'Gao W, Li D, You H', 2019, 'Bioengineering (Basel, Switzerland)', '10.3390/bioengineering6040106', 'https://doi.org/10.3390/bioengineering6040106', 'https://europepmc.org/articles/PMC6955884?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Chlorantraniliprole (CAP) is a widely used insecticide in many areas due to its excellent insecticidal ability and mammalian safety, however, the removal of CAP has not been extensively studied. In this study, a bacterial strain GW13, which is capable of co-metabolizing CAP, was isolated from a vegetable field soil. The strain was identified as Pseudomonas sp. based on its physico-biochemical characteristics and 16S rRNA gene analysis. The bacterial strain GW13 could degrade CAP through co-metabolism, and glucose was the best additional carbon resource. In the presence of 1.0 g/L glucose, GW13 could co-metabolize over 80% of 200 mg/L CAP in 24 h. The degradation rate increased after 6 h and slowed again after 10 h. The GW13 genome analysis revealed many genes associated with metabolism, showing the degradation mechanism of GW13 from the genomic perspective. The EAWAG-BBD (Swiss Federal Institute of Aquatic Science and Technology Biocatalysis/Biodegradation Database) prediction results showed that the main pathway for CAP degradation is amide hydrolysis, which is consistent with many genes associated with amidase in the GW13 genome. This study may facilitate research on CAP biodegradation mechanisms in the environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ac9e0fe-d11d-49a3-ad97-2cac5bdb709e', '53c2d8d5-7a79-446a-af62-a54af1284742', 'Regulatory Effects of Different Doses of Penoxsulam on Endogenous Hormones and Antioxidant System in Foxtail Millet', 'Hu C, Chen T, Diao C, Dou B, Shang S, Li S, Wen Y, Song X', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14213254', 'https://doi.org/10.3390/plants14213254', 'https://europepmc.org/articles/PMC12610494?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The specific objectives include three points: (1) to clarify the dynamic change laws of the contents of three key endogenous hormones, namely, indole-3-acetic acid (IAA), gibberellin (GA), and abscisic acid (ABA), in foxtail millet leaves after penoxsulam treatment, and their correlations with drug dose and treatment time; (2) to analyze the effects of different doses of penoxsulam on the antioxidant system of foxtail millet, specifically including the change characteristics of hydrogen peroxide (H2O2), superoxide anion (O2-), reduced glutathione (GSH) content, and cell membrane permeability (MP); and (3) to reveal the correlation between endogenous hormone changes and antioxidant system indicators through correlation analysis so as to provide a direct experimental basis for the screening of safe doses of penoxsulam application in foxtail millet fields and the research on the herbicide stress resistance mechanism of foxtail millet. Using Jingu 21 as the test material, four penoxsulam dose levels were set through pot and field experiments. The changes in endogenous hormone content, antioxidant system indexes, and phenotypic indicators of foxtail millet were determined at different periods after treatment, and the correlation between endogenous hormones and antioxidant systems was analyzed. Compared with the control (P0), the contents of IAA and GA in foxtail millet showed a "first increasing and then decreasing" trend, while the content of ABA showed a continuous increasing trend. With the increase in penoxsulam concentration, the contents of H2O2, O2-, GSH, and MP in foxtail millet gradually increased. A correlation analysis showed that there was a significant correlation between leaf endogenous hormones and the defense capacity of the antioxidant system. After penoxsulam treatment, foxtail millet leaves showed dynamic changes of "first increasing and then decreasing" in IAA and GA contents, and a continuous increase in ABA contents. At the same time, H2O2, O2-, GSH content, and MP increased significantly with the increase in the drug dose. It is speculated that foxtail millet may indirectly regulate the defense ability of the antioxidant system by regulating the content of endogenous hormones to alleviate the damage of herbicide stress.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6dfec049-ff8c-47fb-9fd6-7a3da8061760', '4be077c1-3638-412a-9119-427fdf8946f6', 'A meta-analysis and systematic review of plant growth regulator use in blueberry production', 'Dick D, VanderWeide J', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1632855', 'https://doi.org/10.3389/fpls.2025.1632855', 'https://europepmc.org/articles/PMC12405187?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'Plant growth regulators (PGRs) include natural and synthetic plant phytohormones and other substances with the capacity to shape one or more aspects of plant growth and development at small concentrations. PGRs are commonly utilized in tree fruit and table grape production to reduce fruit set (thinning) and increase fruit size, coloration, and quality. However, use of PGRs in the production of berry crops, such as blueberry, is less common despite the abundance of production issues and the breadth of PGRs generally registered for fruit crops. This meta-analysis and systematic review discusses the past and current literature surrounding PGR use in blueberry production. First, we highlight the lack of PGRs registered and available to use in blueberry production relative to the increase in blueberry production value over the past decade. Next, we discuss the published literature on PGR use in blueberry species by production topic, including fruit set, berry mass and plant yield, ripening rate and harvest fruit quality, post-harvest fruit quality, and winter hardiness. Meta-analysis of qualifying PGR and production topic combinations revealed that gibberellic acid (GA3) and cytokinins (CKs) increase fruit set, CKs increase berry size, abscisic acid (ABA) and GA3 do not influence berry size, GA3 increases yield, and ABA does not enhance anthocyanin concentration. As global blueberry production continues to expand globally, PGR use will likely increase to address production issues and sustain production and fruit quality.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('62b85227-be03-4f9e-ab38-e27e54fe01a5', '4be077c1-3638-412a-9119-427fdf8946f6', 'A review of soil waterlogging impacts, mechanisms, and adaptive strategies', 'Zhang Y, Chen X, Geng S, Zhang X', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1545912', 'https://doi.org/10.3389/fpls.2025.1545912', 'https://europepmc.org/articles/PMC11866847?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Waterlogging is a major abiotic stress affecting plant growth and productivity. Regardless of rainfall or irrigated environments, plants frequently face waterlogging, which may range from short-term to prolonged durations. Excessive precipitation and soil moisture disrupt crop growth, not because of the water itself but due to oxygen deficiency caused by water saturation. This lack of oxygen triggers a cascade of detrimental effects. Once the soil becomes saturated, oxygen depletion leads to anaerobic respiration in plant roots, weakening their respiratory processes. Waterlogging impacts plant morphology, growth, and metabolism, often increasing ethylene production and impairing vital physiological functions. Plants respond to waterlogging stress by altering their morphological structures, energy metabolism, hormone synthesis, and signal transduction pathways. This paper synthesizes findings from previous studies to systematically analyze the effects of waterlogging on plant yield, hormone regulation, signal transduction, and adaptive responses while exploring the mechanisms underlying plant tolerance to waterlogging. For instance, waterlogging reduces crop yield and disrupts key physiological and biochemical processes, such as hormone synthesis and nutrient absorption, leading to deficiencies of essential nutrients like potassium and calcium. Under waterlogged conditions, plants exhibit morphological changes, including the formation of adventitious roots and the development of aeration tissues to enhance oxygen transport. This review also highlighted effective strategies to improve plant tolerance to waterlogging. Examples include strengthening field management practices, applying exogenous hormones such as 6-benzylaminopurine (6-BA) and γ-aminobutyric acid (GABA), overexpressing specific genes (e.g., ZmEREB180, HvERF2.11, and RAP2.6L), and modifying root architecture. Lastly, we discuss future challenges and propose directions for advancing research in this field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2f086b9-d46c-45b7-8b7b-6f6d64e9e1ac', '38cd8d1c-5ea7-4769-a015-37060dce6d0c', 'Irrigation scheduling for winter wheat in southern Alberta', 'Government of Alberta', 2011, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5332146', 'https://open.alberta.ca/dataset/a611fdcf-9188-42d0-9686-0cd28e8ffae7/resource/3caa08f5-7c29-42a4-9ce7-2c1266edb3fc/download/5332146-2011-agri-facts-irrigation-scheduling-winter-wheat-southern-ab-112-561-1.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Irrigation management is about controlling the rate, amount, and timing of applied irrigation water in a planned and efficient manner. With good irrigation management, a winter wheat crop can have high yield and quality potential.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60137be0-aa28-4290-9ed2-283c8659848f', '4be077c1-3638-412a-9119-427fdf8946f6', 'Abscisic Acid: Role in Fruit Development and Ripening', 'Gupta K, Wani SH, Razzaq A, Skalicky M, Samantara K, Gupta S, Pandita D, Goel S', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.817500', 'https://doi.org/10.3389/fpls.2022.817500', 'https://europepmc.org/articles/PMC9127668?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Abscisic acid (ABA) is a plant growth regulator known for its functions, especially in seed maturation, seed dormancy, adaptive responses to biotic and abiotic stresses, and leaf and bud abscission. ABA activity is governed by multiple regulatory pathways that control ABA biosynthesis, signal transduction, and transport. The transport of the ABA signaling molecule occurs from the shoot (site of synthesis) to the fruit (site of action), where ABA receptors decode information as fruit maturation begins and is significantly promoted. The maximum amount of ABA is exported by the phloem from developing fruits during seed formation and initiation of fruit expansion. In the later stages of fruit ripening, ABA export from the phloem decreases significantly, leading to an accumulation of ABA in ripening fruit. Fruit growth, ripening, and senescence are under the control of ABA, and the mechanisms governing these processes are still unfolding. During the fruit ripening phase, interactions between ABA and ethylene are found in both climacteric and non-climacteric fruits. It is clear that ABA regulates ethylene biosynthesis and signaling during fruit ripening, but the molecular mechanism controlling the interaction between ABA and ethylene has not yet been discovered. The effects of ABA and ethylene on fruit ripening are synergistic, and the interaction of ABA with other plant hormones is an essential determinant of fruit growth and ripening. Reaction and biosynthetic mechanisms, signal transduction, and recognition of ABA receptors in fruits need to be elucidated by a more thorough study to understand the role of ABA in fruit ripening. Genetic modifications of ABA signaling can be used in commercial applications to increase fruit yield and quality. This review discusses the mechanism of ABA biosynthesis, its translocation, and signaling pathways, as well as the recent findings on ABA function in fruit development and ripening.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2245edd2-ff22-45ea-8b73-bc4cf39ff102', '4be077c1-3638-412a-9119-427fdf8946f6', 'An Insight into Abiotic Stress and Influx Tolerance Mechanisms in Plants to Cope in Saline Environments', 'Gul Z, Tang ZH, Arif M, Ye Z', 2022, 'Biology', '10.3390/biology11040597', 'https://doi.org/10.3390/biology11040597', 'https://europepmc.org/articles/PMC9028878?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Salinity is significant abiotic stress that affects the majority of agricultural, irrigated, and cultivated land. It is an issue of global importance, causing many socio-economic problems. Salt stress mainly occurs due to two factors: (1) soil type and (2) irrigation water. It is a major environmental constraint, limiting crop growth, plant productivity, and agricultural yield. Soil salinity is a major problem that considerably distorts ecological habitats in arid and semi-arid regions. Excess salts in the soil affect plant nutrient uptake and osmotic balance, leading to osmotic and ionic stress. Plant adaptation or tolerance to salinity stress involves complex physiological traits, metabolic pathways, the production of enzymes, compatible solutes, metabolites, and molecular or genetic networks. Different plant species have different salt overly sensitive pathways and high-affinity K+ channel transporters that maintain ion homeostasis. However, little progress has been made in developing salt-tolerant crop varieties using different breeding approaches. This review highlights the interlinking of plant morpho-physiological, molecular, biochemical, and genetic approaches to produce salt-tolerant plant species. Most of the research emphasizes the significance of plant growth-promoting rhizobacteria in protecting plants from biotic and abiotic stressors. Plant growth, survival, and yield can be stabilized by utilizing this knowledge using different breeding and agronomical techniques. This information marks existing research areas and future gaps that require more attention to reveal new salt tolerance determinants in plants-in the future, creating genetically modified plants could help increase crop growth and the toleration of saline environments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('671ea59a-3e3f-46be-92e2-89c7a6d33233', '4be077c1-3638-412a-9119-427fdf8946f6', 'Arabidopsis as a model for translational research', 'Yaschenko AE, Alonso JM, Stepanova AN', 2025, 'The Plant cell', '10.1093/plcell/koae065', 'https://doi.org/10.1093/plcell/koae065', 'https://europepmc.org/articles/PMC12082644?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by-nc-nd', 'Arabidopsis thaliana is currently the most-studied plant species on earth, with an unprecedented number of genetic, genomic, and molecular resources having been generated in this plant model. In the era of translating foundational discoveries to crops and beyond, we aimed to highlight the utility and challenges of using Arabidopsis as a reference for applied plant biology research, agricultural innovation, biotechnology, and medicine. We hope that this review will inspire the next generation of plant biologists to continue leveraging Arabidopsis as a robust and convenient experimental system to address fundamental and applied questions in biology. We aim to encourage laboratory and field scientists alike to take advantage of the vast Arabidopsis datasets, annotations, germplasm, constructs, methods, and molecular and computational tools in our pursuit to advance understanding of plant biology and help feed the world''s growing population. We envision that the power of Arabidopsis-inspired biotechnologies and foundational discoveries will continue to fuel the development of resilient, high-yielding, nutritious plants for the betterment of plant and animal health and greater environmental sustainability.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe46e88f-2478-4105-976b-f93f110659a7', '4be077c1-3638-412a-9119-427fdf8946f6', 'bZIP Transcription Factors: Structure, Modification, Abiotic Stress Responses and Application in Plant Improvement', 'Guo Z, Dzinyela R, Yang L, Hwarari D', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13152058', 'https://doi.org/10.3390/plants13152058', 'https://europepmc.org/articles/PMC11313983?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Plant growth, yield, and distribution are significantly impacted by abiotic stresses, affecting global ecosystems and forestry practices. However, plants have evolved complex adaptation mechanisms governed by numerous genes and transcription factors (TFs) to manage these stresses. Among these, bZIP (basic leucine zipper) is a crucial regulator orchestrating morphological adaptations. This review aims to elucidate the multifaceted roles of bZIP TFs in plant species. We discuss the morphological changes induced by stress stimuli and the pivotal functions of bZIP TFs in mediating these responses. While several publications have explored the mechanisms of bZIP TFs in response to abiotic stresses, this review delves into the intricate regulatory networks, summarizing alternative splicing and post-translational modifications, signaling networks interacting with bZIP TFs, and genetic engineering of bZIP TFs. By synthesizing current research, this review provides an updated discussion on bZIP interactions with other proteins to regulate stresses such as cold, heat, drought, and salt. Additionally, it offers avenues for future research and applications of bZIP TFs to improve abiotic stress resilience in plants through genetic engineering.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e6c2360f-50cf-4af7-b4af-c103c82fc7bc', '4be077c1-3638-412a-9119-427fdf8946f6', 'Opportunities for Improving Waterlogging Tolerance in Cereal Crops-Physiological Traits and Genetic Mechanisms', 'Tong C, Hill CB, Zhou G, Zhang XQ, Jia Y, Li C', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10081560', 'https://doi.org/10.3390/plants10081560', 'https://europepmc.org/articles/PMC8401455?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Waterlogging occurs when soil is saturated with water, leading to anaerobic conditions in the root zone of plants. Climate change is increasing the frequency of waterlogging events, resulting in considerable crop losses. Plants respond to waterlogging stress by adventitious root growth, aerenchyma formation, energy metabolism, and phytohormone signalling. Genotypes differ in biomass reduction, photosynthesis rate, adventitious roots development, and aerenchyma formation in response to waterlogging. We reviewed the detrimental effects of waterlogging on physiological and genetic mechanisms in four major cereal crops (rice, maize, wheat, and barley). The review covers current knowledge on waterlogging tolerance mechanism, genes, and quantitative trait loci (QTL) associated with waterlogging tolerance-related traits, the conventional and modern breeding methods used in developing waterlogging tolerant germplasm. Lastly, we describe candidate genes controlling waterlogging tolerance identified in model plants Arabidopsis and rice to identify homologous genes in the less waterlogging-tolerant maize, wheat, and barley.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('255d7c54-1828-4808-a0b8-c13f6640ed6f', '4be077c1-3638-412a-9119-427fdf8946f6', 'Chemical priming enhances plant tolerance to salt stress', 'Zulfiqar F, Nafees M, Chen J, Darras A, Ferrante A, Hancock JT, Ashraf M, Zaid A', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.946922', 'https://doi.org/10.3389/fpls.2022.946922', 'https://europepmc.org/articles/PMC9490053?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Salt stress severely limits the productivity of crop plants worldwide and its detrimental effects are aggravated by climate change. Due to a significant world population growth, agriculture has expanded to marginal and salinized regions, which usually render low crop yield. In this context, finding methods and strategies to improve plant tolerance against salt stress is of utmost importance to fulfill food security challenges under the scenario of the ever-increasing human population. Plant priming, at different stages of plant development, such as seed or seedling, has gained significant attention for its marked implication in crop salt-stress management. It is a promising field relying on the applications of specific chemical agents which could effectively improve plant salt-stress tolerance. Currently, a variety of chemicals, both inorganic and organic, which can efficiently promote plant growth and crop yield are available in the market. This review summarizes our current knowledge of the promising roles of diverse molecules/compounds, such as hydrogen sulfide (H2S), molecular hydrogen, nitric oxide (NO), hydrogen peroxide (H2O2), melatonin, chitosan, silicon, ascorbic acid (AsA), tocopherols, and trehalose (Tre) as potential primers that enhance the salinity tolerance of crop plants.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('97b975f4-be4e-4cb7-91d2-1629009068cc', '4be077c1-3638-412a-9119-427fdf8946f6', 'Coping with the cold: unveiling cryoprotectants, molecular signaling pathways, and strategies for cold stress resilience', 'Jahed KR, Saini AK, Sherif SM', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1246093', 'https://doi.org/10.3389/fpls.2023.1246093', 'https://europepmc.org/articles/PMC10465183?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Low temperature stress significantly threatens crop productivity and economic sustainability. Plants counter this by deploying advanced molecular mechanisms to perceive and respond to cold stress. Transmembrane proteins initiate these responses, triggering a series of events involving secondary messengers such as calcium ions (Ca2+), reactive oxygen species (ROS), and inositol phosphates. Of these, calcium signaling is paramount, activating downstream phosphorylation cascades and the transcription of cold-responsive genes, including cold-regulated (COR) genes. This review focuses on how plants manage freeze-induced damage through dual strategies: cold tolerance and cold avoidance. Tolerance mechanisms involve acclimatization to decreasing temperatures, fostering gradual accumulation of cold resistance. In contrast, avoidance mechanisms rely on cryoprotectant molecules like potassium ions (K+), proline, glycerol, and antifreeze proteins (AFPs). Cryoprotectants modulate intracellular solute concentration, lower the freezing point, inhibit ice formation, and preserve plasma membrane fluidity. Additionally, these molecules demonstrate antioxidant activity, scavenging ROS, preventing protein denaturation, and subsequently mitigating cellular damage. By forming extensive hydrogen bonds with water molecules, cryoprotectants also limit intercellular water movement, minimizing extracellular ice crystal formation, and cell dehydration. The deployment of cryoprotectants is a key adaptive strategy that bolsters plant resilience to cold stress and promotes survival in freezing environments. However, the specific physiological and molecular mechanisms underlying these protective effects remain insufficiently understood. Therefore, this review underscores the need for further research to elucidate these mechanisms and assess their potential impact on crop productivity and sustainability, contributing to the progressive discourse in plant biology and environmental science.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad3365d3-ee5a-477a-b8e3-c94f7e05685f', '4be077c1-3638-412a-9119-427fdf8946f6', 'Enhancing Soil Phosphorus Availability in Intercropping Systems: Roles of Plant Growth Regulators', 'Chunhua Gao, Weilin Kong, Fengtao Zhao, Feiyan Ju, Ping Liu, Zongxin Li, Kaichang Liu, Haijun Zhao', 2025, 'Agronomy', '10.3390/agronomy15071748', 'https://doi.org/10.3390/agronomy15071748', 'https://www.mdpi.com/2073-4395/15/7/1748', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Plant growth regulators (PGRs) enhance crop stress resistance but their roles in microbial-mediated phosphorus cycling within intercropping systems are unclear. Thus, We conducted a two-year field study using corn (Zea mays L. cv. Denghai 605) and soybean (Glycine max L. cv. Hedou 22) in fluvisols and luvisols soil according to World Reference Base for Soil Resources (WRB) standard. Under a 4-row corn and 6-row soybean strip intercropping system, three treatments were applied: a water control (CK), and two plant growth regulators—T1 (EC: ethephon [300 mg/L] + cycocel [2 g/L]) and T2 (ED: ethephon [300 mg/L] + 2-Diethyl aminoethyl hexanoate [10 mg/L]). Foliar applications were administered at the V7 stage (seventh leaf) of intercropped corn plants to assess how foliar-applied PGRs (T1/T2) modulated the soil phosphorus availability, microbial communities, and functional genes in maize intercropping systems. PGRs increased the soil organic phosphorus and available phosphorus contents, and alkaline phosphatase activity, but not total phosphorus. PGRs declined the α-diversity in fluvisols soil but increased the α-diversity in luvisols soil. The major taxa changed from Actinobacteria (CK) to Proteobacteria (T1) and Saccharibacteria (T2) in fluvisols soil, and from Actinobacteria/Gemmatimonadetes (CK) to Saccharibacteria (T1) and Acidobacteria (T2) in luvisols soil. Functional gene dynamics indicated soil-specific regulation, where fluvisols soil harbored more phoD (organic phosphorus mineralization) and relA (polyphosphate degradation) genes, whereas phnP gene dominated in luvisols soil. T1 stimulated organic phosphorus mineralization and inorganic phosphorus solubilization in fluvisols soil, upregulating regulation genes, and T2 enhanced polyphosphate synthesis and transport gene expression in luvisols soil. Proteobacteria, Nitrospirae, and Chloroflexi were positively correlated with organic phosphorus mineralization and polyphosphate cycling genes, whereas Bacteroidetes and Verrucomicrobia correlated with available potassium (AP), total phosphorus (TP), and alkaline phosphatase (ALP) activity. Thus, PGRs activated soil phosphorus by restructuring soil type-dependent microbial functional networks, connecting PGRs-induced shifts with microbial phosphorus cycling mechanisms. These findings facilitate the targeted use of PGRs to optimize microbial-driven phosphorus efficiency in strategies for sustainable phosphorus management in diverse agricultural soils.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cdac11a2-1638-4a11-b20b-55d3381fd75f', '4be077c1-3638-412a-9119-427fdf8946f6', 'Ethephon role in maize yield and lodging through plants morphological and chemical changes', 'Dunđerski Dušan, Bekavac Goran, Purar Božana, Đurić Anja, Tanasković Maja', 2026, 'Ratarstvo i Povrtarstvo', '10.5937/ratpov63-62729', 'https://doi.org/10.5937/ratpov63-62729', 'https://scindeks-clanci.ceon.rs/data/pdf/1821-3944/2026/1821-39442601053D.pdf', NULL, NULL, 16, NULL, 'other', 1, 'open access (DOAJ)', 'Ethephon, a plant growth regulator that releases ethylene, has emerged as a pivotal tool for improving maize performance under diverse growing conditions. This review synthesizes existing findings on ethephon''s role in modulating maize architecture that strongly influence lodging resistance and yield as well as nitrogen uptake. When applied at strategic growth stages and optimal doses between 280 and 840 g ha⁻¹, ethephon consistently strengthens stalks, lowers the center of gravity, and mitigates lodging risks, particularly under high-density planting. Although some studies report yield reductions when lodging threats are minimal, others demonstrate considerable yield gains up to 200% under drought and stress conditions, largely by redirecting assimilates toward reproductive structures and enhancing physiological resilience. Ethephon also interacts synergistically with other growth regulators, augmenting stem diameter, lignin deposition, and root anchorage. However, responses vary with genotype, environmental factors, and cultural practices, underscoring the importance of tailored application protocols. Collectively, the evidence points that its integration into maize production systems, especially where lodging pressures and water limitations prevail, offers both agronomic and economic benefits. Although numerous studies have clarified above-ground changes, the impact of ethephon on maize root architecture and nutrient uptake remains largely underexplored. Further refinement of dose-response relationships across diverse germplasm, planting densities, and nitrogen management regimes is essential to develop precise, context-specific guidelines. Systematic screening of hybrids will clarify genotype-by-ethephon interactions, guiding breeders in selecting lines with stable yield and improved lodging tolerance. Combining ethephon with other PGRs besides mostly used diethyl aminoethyl hexanoate should be studied.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e1225ff-c95d-4c83-8407-ea6215f48461', '4be077c1-3638-412a-9119-427fdf8946f6', 'Ethylene and Jasmonates Signaling Network Mediating Secondary Metabolites under Abiotic Stress', 'Pérez-Llorca M, Pollmann S, Müller M', 2023, 'International journal of molecular sciences', '10.3390/ijms24065990', 'https://doi.org/10.3390/ijms24065990', 'https://europepmc.org/articles/PMC10051637?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Plants are sessile organisms that face environmental threats throughout their life cycle, but increasing global warming poses an even more existential threat. Despite these unfavorable circumstances, plants try to adapt by developing a variety of strategies coordinated by plant hormones, resulting in a stress-specific phenotype. In this context, ethylene and jasmonates (JAs) present a fascinating case of synergism and antagonism. Here, Ethylene Insensitive 3/Ethylene Insensitive-Like Protein1 (EIN3/EIL1) and Jasmonate-Zim Domain (JAZs)-MYC2 of the ethylene and JAs signaling pathways, respectively, appear to act as nodes connecting multiple networks to regulate stress responses, including secondary metabolites. Secondary metabolites are multifunctional organic compounds that play crucial roles in stress acclimation of plants. Plants that exhibit high plasticity in their secondary metabolism, which allows them to generate near-infinite chemical diversity through structural and chemical modifications, are likely to have a selective and adaptive advantage, especially in the face of climate change challenges. In contrast, domestication of crop plants has resulted in change or even loss in diversity of phytochemicals, making them significantly more vulnerable to environmental stresses over time. For this reason, there is a need to advance our understanding of the underlying mechanisms by which plant hormones and secondary metabolites respond to abiotic stress. This knowledge may help to improve the adaptability and resilience of plants to changing climatic conditions without compromising yield and productivity. Our aim in this review was to provide a detailed overview of abiotic stress responses mediated by ethylene and JAs and their impact on secondary metabolites.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ba1b4e2b-fc5d-45e3-9bc4-f4388c93c092', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Efficacy of Insecticides against the Invasive Apricot Aphid, Myzus mumecola', 'Tabet DH, Visentin E, Bonadio M, Bjeljac M, Reyes-Domínguez Y, Gallmetzer A, Spitaler U', 2023, 'Insects', '10.3390/insects14090746', 'https://doi.org/10.3390/insects14090746', 'https://europepmc.org/articles/PMC10531954?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The invasive apricot aphid (Myzus mumecola Matsumura) is an important pest of apricot trees (Prunus armeniaca L.). In the presented study, laboratory bioassays using treated leaf disks of apricot were conducted to test the efficacy of twelve insecticides according to the maximum field dose. Additionally, dose-response curves were established for selected insecticides, and the effects on colony development were evaluated. Furthermore, a field trial was conducted to investigate the effectiveness of commonly used insecticides in apricot cultivation. The dose-response curves showed LC50 values ranging from 0.08 mg/L for flupyradifurone, 0.15 mg/L for acetamiprid, 0.70 mg/L for etofenprox, 1.89 mg/L for sulfoxaflor, 2.64 mg/L for pirimicarb, 3.97 mg/L for deltamethrin, up to 6.79 mg/L for tau-fluvalinate. These aforementioned insecticides resulted in mortality rates ranging from 95 to 100% at the field dose. Azadirachtin, flonicamid, and pyrethrins showed mortality rates of 27 to 45%. Spirotetramat reduced the colony development and decreased the number of infested shoots by 86%. Spinosad, which is not recommended against aphids, showed minimal impact; reducing the number of exuviae in nymphs in the colony development bioassay. It can be concluded that the majority of the tested insecticides are effective against M. mumecola.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9489bbda-5ed6-4f14-a783-8e1c1c1b8bda', '4be077c1-3638-412a-9119-427fdf8946f6', 'Genomics, Proteomics, and Metabolomics Approaches to Improve Abiotic Stress Tolerance in Tomato Plant', 'Naik B, Kumar V, Rizwanuddin S, Chauhan M, Choudhary M, Gupta AK, Kumar P, Kumar V', 2023, 'International journal of molecular sciences', '10.3390/ijms24033025', 'https://doi.org/10.3390/ijms24033025', 'https://europepmc.org/articles/PMC9918255?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'To explore changes in proteins and metabolites under stress circumstances, genomics, proteomics, and metabolomics methods are used. In-depth research over the previous ten years has gradually revealed the fundamental processes of plants'' responses to environmental stress. Abiotic stresses, which include temperature extremes, water scarcity, and metal toxicity brought on by human activity and urbanization, are a major cause for concern, since they can result in unsustainable warming trends and drastically lower crop yields. Furthermore, there is an emerging reliance on agrochemicals. Stress is responsible for physiological transformations such as the formation of reactive oxygen, stomatal opening and closure, cytosolic calcium ion concentrations, metabolite profiles and their dynamic changes, expression of stress-responsive genes, activation of potassium channels, etc. Research regarding abiotic stresses is lacking because defense feedbacks to abiotic factors necessitate regulating the changes that activate multiple genes and pathways that are not properly explored. It is clear from the involvement of these genes that plant stress response and adaptation are complicated processes. Targeting the multigenicity of plant abiotic stress responses caused by genomic sequences, transcripts, protein organization and interactions, stress-specific and cellular transcriptome collections, and mutant screens can be the first step in an integrative approach. Therefore, in this review, we focused on the genomes, proteomics, and metabolomics of tomatoes under abiotic stress.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ea384fcf-9c5c-4327-b70e-1fc07e9a747d', '4be077c1-3638-412a-9119-427fdf8946f6', 'Hermaphroditism in Cannabis sativa L.: Impacts, Inducers, and Industry Implications', 'Richards CD, Ryu BR, Gim GJ, Park SH', 2026, 'Plants (Basel, Switzerland)', '10.3390/plants15111643', 'https://doi.org/10.3390/plants15111643', 'https://europepmc.org/articles/PMC13258890?pdf=render', NULL, NULL, 20, NULL, 'northern_plains', 3, 'cc by', 'Cannabis sativa L. is a predominantly dioecious species, but sex expression is highly plastic and can be modified by genetic, hormonal, developmental, and environmental factors. This plasticity has major implications for commercial production because hermaphroditic expression in female plants can cause unintended pollination, seed formation, reduced floral quality, and losses in cannabinoid yield. This review summarizes current understanding of sex determination and sex-expression instability in C. sativa, with emphasis on hermaphroditism and its agronomic significance. We examine the genomic architecture of sex determination, the roles of ethylene and gibberellin signaling, and the effects of exogenous chemical treatments used to alter sexual phenotype. Particular attention is given to silver-based ethylene inhibitors, especially silver thiosulfate, which remain the most effective tools for induced masculinization and feminized seed production. We also assess the role of environmental stressors in sex instability and review current approaches for early detection, including visual inspection, Raman spectroscopy, and sex-linked molecular markers. Overall, the available evidence supports a multilayered and context-dependent model in which genotype, treatment regime, developmental stage, and environmental conditions interact to shape sexual phenotype. Improved understanding of these processes will be essential for reducing hermaphroditic risk, improving breeding strategies, and supporting stable, high-value cannabis production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a704126f-899e-400f-bb3d-714fd9ecb462', '4be077c1-3638-412a-9119-427fdf8946f6', 'Impacts of Root Metabolites on Soil Nematodes', 'Sikder MM, Vestergård M', 2019, 'Frontiers in plant science', '10.3389/fpls.2019.01792', 'https://doi.org/10.3389/fpls.2019.01792', 'https://europepmc.org/articles/PMC7005220?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Plant parasitic nematodes cause significant crop damage globally. Currently, many nematicides have been banned or are being phased out in Europe and other parts of the world because of environmental and human health concerns. Therefore, we need to focus on sustainable and alternative methods of nematode control to protect crops. Plant roots contain and release a wide range of bioactive secondary metabolites, many of which are known defense compounds. Hence, profound understanding of the root mediated interactions between plants and plant parasitic nematodes may contribute to efficient control and management of pest nematodes. In this review, we have compiled literature that documents effects of root metabolites on plant parasitic nematodes. These chemical compounds act as either nematode attractants, repellents, hatching stimulants or inhibitors. We have summarized the few studies that describe how root metabolites regulate the expression of nematode genes. As non-herbivorous nematodes contribute to decomposition, nutrient mineralization, microbial community structuring and control of herbivorous insect larvae, we also review the impact of plant metabolites on these non-target organisms.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cee4a30d-e8de-430a-a718-b1b93926d2a1', '4be077c1-3638-412a-9119-427fdf8946f6', 'Insights into Salinity Tolerance in Wheat', 'Zhang Z, Xia Z, Zhou C, Wang G, Meng X, Yin P', 2024, 'Genes', '10.3390/genes15050573', 'https://doi.org/10.3390/genes15050573', 'https://europepmc.org/articles/PMC11121000?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Salt stress has a detrimental impact on food crop production, with its severity escalating due to both natural and man-made factors. As one of the most important food crops, wheat is susceptible to salt stress, resulting in abnormal plant growth and reduced yields; therefore, damage from salt stress should be of great concern. Additionally, the utilization of land in coastal areas warrants increased attention, given diminishing supplies of fresh water and arable land, and the escalating demand for wheat. A comprehensive understanding of the physiological and molecular changes in wheat under salt stress can offer insights into mitigating the adverse effects of salt stress on wheat. In this review, we summarized the genes and molecular mechanisms involved in ion transport, signal transduction, and enzyme and hormone regulation, in response to salt stress based on the physiological processes in wheat. Then, we surveyed the latest progress in improving the salt tolerance of wheat through breeding, exogenous applications, and microbial pathways. Breeding efficiency can be improved through a combination of gene editing and multiple omics techniques, which is the fundamental strategy for dealing with salt stress. Possible challenges and prospects in this process were also discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('474d6300-d2f0-41d9-ad1b-e196fe6d8ba1', '4be077c1-3638-412a-9119-427fdf8946f6', 'Instigating prevalent abiotic stress resilience in crop by exogenous application of phytohormones and nutrient', 'Swain R, Sahoo S, Behera M, Rout GR', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1104874', 'https://doi.org/10.3389/fpls.2023.1104874', 'https://europepmc.org/articles/PMC9947512?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'In recent times, the demand for food and feed for the ever-increasing population has achieved unparalleled importance, which cannot afford crop yield loss. Now-a-days, the unpleasant situation of abiotic stress triggers crop improvement by affecting the different metabolic pathways of yield and quality advances worldwide. Abiotic stress like drought, salinity, cold, heat, flood, etc. in plants diverts the energy required for growth to prevent the plant from shock and maintain regular homeostasis. Hence, the plant yield is drastically reduced as the energy is utilized for overcoming the stress in plants. The application of phytohormones like the classical auxins, cytokinins, ethylene, and gibberellins, as well as more recent members including brassinosteroids, jasmonic acids, etc., along with both macro and micronutrients, have enhanced significant attention in creating key benefits such as reduction of ionic toxicity, improving oxidative stress, maintaining water-related balance, and gaseous exchange modification during abiotic stress conditions. Majority of phytohormones maintain homeostasis inside the cell by detoxifying the ROS and enhancing the antioxidant enzyme activities which can enhance tolerance in plants. At the molecular level, phytohormones activate stress signaling pathways or genes regulated by abscisic acid (ABA), salicylic acid (SA), Jasmonic acid (JA), and ethylene. The various stresses primarily cause nutrient deficiency and reduce the nutrient uptake of plants. The application of plant nutrients like N, K, Ca, and Mg are also involved in ROS scavenging activities through elevating antioxidants properties and finally decreasing cell membrane leakage and increasing the photosynthetic ability by resynthesizing the chlorophyll pigment. This present review highlighted the alteration of metabolic activities caused by abiotic stress in various crops, the changes of vital functions through the application of exogenous phytohormones and nutrition, as well as their interaction.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('550dd860-57f7-4ccf-b9ae-fc7134d019e8', '4be077c1-3638-412a-9119-427fdf8946f6', 'Introducing melatonin to the horticultural industry: physiological roles, potential applications, and challenges', 'Gao T, Liu X, Tan K, Zhang D, Zhu B, Ma F, Li C', 2022, 'Horticulture research', '10.1093/hr/uhac094', 'https://doi.org/10.1093/hr/uhac094', 'https://europepmc.org/articles/PMC9297156?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Melatonin (N-acetyl-5-methoxytryptamine) is an emerging biomolecule that influences horticultural crop growth, flowering, fruit ripening, postharvest preservation, and stress protection. It functions as a plant growth regulator, preservative and antimicrobial agent to promote seed germination, regulate root system architecture, influence flowering and pollen germination, promote fruit production, ensure postharvest preservation, and increase resistance to abiotic and biotic stresses. Here, we highlight the potential applications of melatonin in multiple aspects of horticulture, including molecular breeding, vegetative reproduction, production of virus-free plants, food safety, and horticultural crop processing. We also discuss its effects on parthenocarpy, autophagy, and arbuscular mycorrhizal symbiosis. Together, these many features contribute to the promise of melatonin for improving horticultural crop production and food safety. Effective translation of melatonin to the horticultural industry requires an understanding of the challenges associated with its uses, including the development of economically viable sources.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a642be20-930c-4d85-9e0e-1e2dcac08489', '4be077c1-3638-412a-9119-427fdf8946f6', 'Microbial Biofungicides as a Substitute for Chemical Fungicides in the Control of Phytopathogens: Current Perspectives and Research Directions', 'Fenta L, Fenta L, Mekonnen H', 2024, 'Scientifica', '10.1155/2024/5322696', 'https://doi.org/10.1155/2024/5322696', 'https://europepmc.org/articles/PMC10917481?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'These days, two important issues are causing concern in the global community: the alarmingly growing trend of the human population and the issue of food security. To this end, people around the world have been searching for solutions that could feed the needy in a sustainable way. In response to this urgent call, scientists from around the world started working on increasing crop production and productivity by controlling crop pathogens that could harm the productivity of crops. Synthetic fungicides have been in use for controlling crop diseases for several decades, but later, due to the evidenced side effects of the fungicides, there have been attempts to shift towards a less cost-effective and eco-friendly method of controlling crop diseases, and so far, many remarkable results have been achieved. However, due to the less effective and shorter shelf life of microbial biofungicides, as well as the less accessibility of these microbial biofungicides to growers around the world, it became difficult to remove the fungicides totally from the market. To minimize this problem, researchers suggested an integrated approach: the combination of microbial biofungicides with a reduced dose of synthetic fungicides. Hence, this review explored the status as well as the merits and demerits of microbial biofungicides as compared to synthetic fungicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('148b0d9f-5bc3-4e54-9c3f-86dcc89da744', '4be077c1-3638-412a-9119-427fdf8946f6', 'Nitric Oxide Regulates Seed Germination by Integrating Multiple Signalling Pathways', 'Zhang Y, Wang R, Wang X, Zhao C, Shen H, Yang L', 2023, 'International journal of molecular sciences', '10.3390/ijms24109052', 'https://doi.org/10.3390/ijms24109052', 'https://europepmc.org/articles/PMC10219172?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Seed germination is of great significance for plant development and crop yield. Recently, nitric oxide (NO) has been shown to not only serve as an important nitrogen source during seed development but also to participate in a variety of stress responses in plants to high salt, drought, and high temperature. In addition, NO can affect the process of seed germination by integrating multiple signaling pathways. However, due to the instability of NO gas activity, the network mechanism for its fine regulation of seed germination remains unclear. Therefore, this review aims to summarize the complex anabolic processes of NO in plants, to analyze the interaction mechanisms between NO-triggered signaling pathways and different plant hormones such as abscisic acid (ABA) and gibberellic acid (GA), ethylene (ET) and reactive oxygen species (ROS) signaling molecules, and to discuss the physiological responses and molecular mechanisms of seeds during the involvement of NO in abiotic stress, so as to provide a reference for solving the problems of seed dormancy release and improving plant stress tolerance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5794d5f6-7179-4eef-aeff-6c0e02007fd6', '4be077c1-3638-412a-9119-427fdf8946f6', 'Plant hormones and neurotransmitter interactions mediate antioxidant defenses under induced oxidative stress in plants', 'Raza A, Salehi H, Rahman MA, Zahid Z, Madadkar Haghjou M, Najafi-Kakavand S, Charagh S, Osman HS', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.961872', 'https://doi.org/10.3389/fpls.2022.961872', 'https://europepmc.org/articles/PMC9514553?pdf=render', NULL, NULL, 40, NULL, 'other', 1, 'cc by', 'Due to global climate change, abiotic stresses are affecting plant growth, productivity, and the quality of cultivated crops. Stressful conditions disrupt physiological activities and suppress defensive mechanisms, resulting in stress-sensitive plants. Consequently, plants implement various endogenous strategies, including plant hormone biosynthesis (e.g., abscisic acid, jasmonic acid, salicylic acid, brassinosteroids, indole-3-acetic acid, cytokinins, ethylene, gibberellic acid, and strigolactones) to withstand stress conditions. Combined or single abiotic stress disrupts the normal transportation of solutes, causes electron leakage, and triggers reactive oxygen species (ROS) production, creating oxidative stress in plants. Several enzymatic and non-enzymatic defense systems marshal a plant''s antioxidant defenses. While stress responses and the protective role of the antioxidant defense system have been well-documented in recent investigations, the interrelationships among plant hormones, plant neurotransmitters (NTs, such as serotonin, melatonin, dopamine, acetylcholine, and γ-aminobutyric acid), and antioxidant defenses are not well explained. Thus, this review discusses recent advances in plant hormones, transgenic and metabolic developments, and the potential interaction of plant hormones with NTs in plant stress response and tolerance mechanisms. Furthermore, we discuss current challenges and future directions (transgenic breeding and genome editing) for metabolic improvement in plants using modern molecular tools. The interaction of plant hormones and NTs involved in regulating antioxidant defense systems, molecular hormone networks, and abiotic-induced oxidative stress tolerance in plants are also discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('688b495d-98bd-43b5-8c18-7de5672c4e76', '4be077c1-3638-412a-9119-427fdf8946f6', 'Sustaining nitrogen dynamics: A critical aspect for improving salt tolerance in plants', 'Nazir F, Mahajan M, Khatoon S, Albaqami M, Ashfaque F, Chhillar H, Chopra P, Khan MIR', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1087946', 'https://doi.org/10.3389/fpls.2023.1087946', 'https://europepmc.org/articles/PMC9996754?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'In the current changing environment, salt stress has become a major concern for plant growth and food production worldwide. Understanding the mechanisms of how plants function in saline environments is critical for initiating efforts to mitigate the detrimental effects of salt stress. Agricultural productivity is linked to nutrient availability, and it is expected that the judicious metabolism of mineral nutrients has a positive impact on alleviating salt-induced losses in crop plants. Nitrogen (N) is a macronutrient that contributes significantly to sustainable agriculture by maintaining productivity and plant growth in both optimal and stressful environments. Significant progress has been made in comprehending the fundamental physiological and molecular mechanisms associated with N-mediated plant responses to salt stress. This review provided an (a) overview of N-sensing, transportation, and assimilation in plants; (b) assess the salt stress-mediated regulation of N dynamics and nitrogen use- efficiency; (c) critically appraise the role of N in plants exposed to salt stress. Furthermore, the existing but less explored crosstalk between N and phytohormones has been discussed that may be utilized to gain a better understanding of plant adaptive responses to salt stress. In addition, the shade of a small beam of light on the manipulation of N dynamics through genetic engineering with an aim of developing salt-tolerant plants is also highlighted.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('da994f7f-9032-4e27-8a31-43065ca7fe81', '4be077c1-3638-412a-9119-427fdf8946f6', 'Postharvest senescence of green vegetables and the role of glutathione metabolism: current state of knowledge and future research opportunities', 'Bozzo GG, Sivakumar D, Yan Y, Beltrán Plascencia A', 2026, 'Frontiers in plant science', '10.3389/fpls.2026.1918891', 'https://doi.org/10.3389/fpls.2026.1918891', 'https://europepmc.org/articles/PMC13598967?pdf=render', NULL, NULL, 19, NULL, 'canada', 3, 'cc by', 'The rapid progression of senescence contributes to the postharvest perishability of green vegetables including Brassicaceae commodities. Tissue yellowing due to chlorophyll degradation is a hallmark feature of senescing green vegetables and is associated with the accumulation of reactive oxygen species. Moreover, oxidative stress metabolism in vegetables is exacerbated by postharvest temperature abuse and the senescence-related phytohormone ethylene. Glutathione is a primary antioxidant that detoxifies reactive oxygen species in plants. Glutathione status in postharvest vegetables is partially dependent upon the degree to which it is oxidized to glutathione disulfide, as well as whether glutathione is recycled from glutathione disulfide via the ascorbate-glutathione recycling pathway. Apart from reactive oxygen species management, the concentration of glutathione within Brassicaceae commodities is a consequence of its participation in non-antioxidant metabolism such as glucosinolate biosynthesis and protein glutathionylation. Although not well described for postharvest vegetables, glutathione status in postharvest vegetables is postulated to be impacted by catabolism to its constituent amino acids. In the model Brassicaceae plant Arabidopsis thaliana, glutathione is catabolized to the metabolic intermediates cysteinylglycine and 5-oxoproline, and finally to cysteine, glycine and glutamate. Improved knowledge of these metabolic events in commercially relevant Brassicaceae commodities could provide novel biochemical targets for offsetting postharvest senescence of their edible vegetables. In addition, we discuss the current state of knowledge on the application of exogenous glutathione prior to postharvest storage as a strategy to lessen the negative impact of oxidative stress mediated deterioration of highly perishable vegetables.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1936d6c8-5d20-4abb-9e1c-83e7c52cdfcd', '4be077c1-3638-412a-9119-427fdf8946f6', 'Regulation of Reactive Oxygen Species during Salt Stress in Plants and Their Crosstalk with Other Signaling Molecules-Current Perspectives and Future Directions', 'Kesawat MS, Satheesh N, Kherawat BS, Kumar A, Kim HU, Chung SM, Kumar M', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12040864', 'https://doi.org/10.3390/plants12040864', 'https://europepmc.org/articles/PMC9964777?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by', 'Salt stress is a severe type of environmental stress. It adversely affects agricultural production worldwide. The overproduction of reactive oxygen species (ROS) is the most frequent phenomenon during salt stress. ROS are extremely reactive and, in high amounts, noxious, leading to destructive processes and causing cellular damage. However, at lower concentrations, ROS function as secondary messengers, playing a critical role as signaling molecules, ensuring regulation of growth and adjustment to multifactorial stresses. Plants contain several enzymatic and non-enzymatic antioxidants that can detoxify ROS. The production of ROS and their scavenging are important aspects of the plant''s normal response to adverse conditions. Recently, this field has attracted immense attention from plant scientists; however, ROS-induced signaling pathways during salt stress remain largely unknown. In this review, we will discuss the critical role of different antioxidants in salt stress tolerance. We also summarize the recent advances on the detrimental effects of ROS, on the antioxidant machinery scavenging ROS under salt stress, and on the crosstalk between ROS and other various signaling molecules, including nitric oxide, hydrogen sulfide, calcium, and phytohormones. Moreover, the utilization of "-omic" approaches to improve the ROS-regulating antioxidant system during the adaptation process to salt stress is also described.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7832148b-e692-4d8f-a8f9-744f659070c4', '4be077c1-3638-412a-9119-427fdf8946f6', 'Research progress on the physiological response and molecular mechanism of cold response in plants', 'Wang Y, Wang J, Sarwar R, Zhang W, Geng R, Zhu KM, Tan XL', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1334913', 'https://doi.org/10.3389/fpls.2024.1334913', 'https://europepmc.org/articles/PMC10861734?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Low temperature is a critical environmental stress factor that restricts crop growth and geographical distribution, significantly impacting crop quality and yield. When plants are exposed to low temperatures, a series of changes occur in their external morphology and internal physiological and biochemical metabolism. This article comprehensively reviews the alterations and regulatory mechanisms of physiological and biochemical indices, such as membrane system stability, redox system, fatty acid content, photosynthesis, and osmoregulatory substances, in response to low-temperature stress in plants. Furthermore, we summarize recent research on signal transduction and regulatory pathways, phytohormones, epigenetic modifications, and other molecular mechanisms mediating the response to low temperatures in higher plants. In addition, we outline cultivation practices to improve plant cold resistance and highlight the cold-related genes used in molecular breeding. Last, we discuss future research directions, potential application prospects of plant cold resistance breeding, and recent significant breakthroughs in the research and application of cold resistance mechanisms.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5bd63315-5109-4e39-8fa9-41f08affb962', '4be077c1-3638-412a-9119-427fdf8946f6', 'Response of Lodging Resistance and Grain Yield to EDAH and Different Fertilization Combinations in Maize (Zea mays L.)', 'Yuru Wang, Yifei Wang, Chenyang Jiang, Yuwen Liang, Genji You, Jian Guo, Dalei Lu, Guanghao Li', 2025, 'Plants', '10.3390/plants14233707', 'https://doi.org/10.3390/plants14233707', 'https://www.mdpi.com/2223-7747/14/23/3707', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Stalk lodging is one of the major constraints limiting global maize yield. Chemical regulation and fertilization are essential agronomic practices that play critical roles in improving maize yield and lodging resistance. This study aimed to investigate the effects of different fertilization methods on maize plant morphology, stem mechanical properties and chemical composition, and yield under spraying chemical regulator (EDAH, consist of 27% ethephon and 3% DA-6). The experiment was conducted from 2023 to 2025, using Jiangyu668 (JY668) and Jiangyu877 (JY877) with different plant heights. Three fertilization methods (no fertilization, N0; conventional fertilization, N15; and slow-release fertilization, SN15) were set up. Chemical regulation and fertilization methods had significant effects on plant morphology, stem mechanical properties and chemical composition, lodging rate, and grain yield. The combination of spraying EDAH and slow-release fertilization optimized ear position coefficient and gravity center, decreased stem–leaf angle, and increased leaf orientation value, which was beneficial for improving leaf photosynthetic capacity. EDAH and slow-release fertilization also increased the stem internode diameter and aerial root layers; enhanced bending resistance and puncture strength; and increased cellulose, hemicellulose, and lignin contents and the lodging resistance index. These changes synergistically increased grain number and weight, ultimately increased maize yield, and decreased the lodging rate. CSN15 had highest yield and lowest lodging rate in different years and varieties. SN15 increased yield by 10.58% compared with N15, and CSN15 increased yield by 10.53% compared with CN15. JY877, as a medium- to high-stem maize variety, had better performance in plant morphology and yield than JY668 (dwarf maize variety) under EDAH and slow-release fertilization. These findings demonstrate that the strategy of combining chemical regulation and slow-release fertilization represents an optimal management approach for enhancing grain yield by optimizing plant morphology and improving stem mechanical properties and stem chemical composition in maize production. This strategy can increase agricultural productivity by enhancing yield and lodging resistance and provide significant environmental benefits and a scientific basis for agronomic practice recommendations.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0d9c0308-7725-465c-bf36-2c6428d30b20', '4be077c1-3638-412a-9119-427fdf8946f6', 'The Effect of Ethylene on the Color Change and Resistance to Botrytis cinerea Infection in ''Kyoho'' Grape Fruits', 'Dong T, Zheng T, Fu W, Guan L, Jia H, Fang J', 2020, 'Foods (Basel, Switzerland)', '10.3390/foods9070892', 'https://doi.org/10.3390/foods9070892', 'https://europepmc.org/articles/PMC7404975?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'The formation of grape quality and the mechanism of resistance against foreign pathogens affect the storage stability of fruits during post-harvest handling. Ethylene plays a crucial role in regulating the ripeness of fruits and can be used as an exogenous regulator to resist exogenous pathogens. In this study, we used different concentrations of ethephon for treatment of grape fruits before veraison, analyzed the anthocyanin content, soluble solids, titratable acid, and determined fruit firmness and cell wall metabolism-related enzymes during fruit development. Results showed that exogenous ethephon promoted the early coloration of grape fruits and increased the coloring-related genes myeloblastosis A1(MYBA1), myeloblastosis A2(MYBA2), chalcone isomerase (CHI), flavanone 3-hydroxylase (F3H), flavonoid 3''-hydroxylase gene (F3''H), flavonoid 3'', 5''hydroxylase (F3''5''H), 3-O-flavonoid glucosyltransferase (UFGT), and glutathione S-transferase (GST), softening related genes Polygalacturonase(PG), pectinate lyases(PL) and Pectin methylesterase( PME, as well as ethylene metabolism pathway-related genes 1-aminocyclopropane-1-carboxylic acid synthase 1(ACS1), 1-aminocyclopropane-1-carboxylic acid oxidase 2 (ACO2), ethylene receptor gene(ETR2), and ethylene-insensitive 3 (EIN3). Ethephon treatment also increased soluble solids and decreased titratable acid in grape fruit. Fruits pretreated with ethephon were inoculated with Botrytis cinerea, which led to resistance in grape fruit through activation of the antioxidant system. The expression levels of disease resistance-related genes including VvPAD4, VvPIP1, VvNAC26, VvDREB, VvAPX, Vvpgip, VvWRKY70, VvMYC2, VvNPR1 also increased in inoculated fruit with pathogen following ethephon pretreatment. Furthermore, we monitored ethylene response factor 1(ERF1) transcription factor, which could interact with protein EIN3 during ethylene signal transduction and mediate fruit resistance against B. cinerea infection. Meanwhile, overexpression of VvERF1 vectorin strawberry fruits reduced the susceptibility to B. cinerea infection. We suggest that ethylene can induce resistance in ripened fruits after B. cinerea infection and provide adequate postharvest care.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.052912+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('633dceca-9a88-4f06-b116-3e7dc62b8b51', '4be077c1-3638-412a-9119-427fdf8946f6', 'The Ethylene Biosynthetic Enzymes, 1-Aminocyclopropane-1-Carboxylate (ACC) Synthase (ACS) and ACC Oxidase (ACO): The Less Explored Players in Abiotic Stress Tolerance', 'Khan S, Alvi AF, Saify S, Iqbal N, Khan NA', 2024, 'Biomolecules', '10.3390/biom14010090', 'https://doi.org/10.3390/biom14010090', 'https://europepmc.org/articles/PMC10813531?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'Ethylene is an essential plant hormone, critical in various physiological processes. These processes include seed germination, leaf senescence, fruit ripening, and the plant''s response to environmental stressors. Ethylene biosynthesis is tightly regulated by two key enzymes, namely 1-aminocyclopropane-1-carboxylate synthase (ACS) and 1-aminocyclopropane-1-carboxylate oxidase (ACO). Initially, the prevailing hypothesis suggested that ACS is the limiting factor in the ethylene biosynthesis pathway. Nevertheless, accumulating evidence from various studies has demonstrated that ACO, under specific circumstances, acts as the rate-limiting enzyme in ethylene production. Under normal developmental processes, ACS and ACO collaborate to maintain balanced ethylene production, ensuring proper plant growth and physiology. However, under abiotic stress conditions, such as drought, salinity, extreme temperatures, or pathogen attack, the regulation of ethylene biosynthesis becomes critical for plants'' survival. This review highlights the structural characteristics and examines the transcriptional, post-transcriptional, and post-translational regulation of ACS and ACO and their role under abiotic stress conditions. Reviews on the role of ethylene signaling in abiotic stress adaptation are available. However, a review delineating the role of ACS and ACO in abiotic stress acclimation is unavailable. Exploring how particular ACS and ACO isoforms contribute to a specific plant''s response to various abiotic stresses and understanding how they are regulated can guide the development of focused strategies. These strategies aim to enhance a plant''s ability to cope with environmental challenges more effectively.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('11cd2af8-b456-4101-aaf6-e4aadd598b81', '4be077c1-3638-412a-9119-427fdf8946f6', 'Transcriptome analysis of Pará rubber tree (H. brasiliensis) seedlings under ethylene stimulation', 'Yoshimi Nakano, Nobutaka Mitsuda, Kohei Ide, Teppei Mori, Farida Rosana Mira, Syofi Rosmalawati, Norie Watanabe, Kaoru Suzuki', 2021, 'BMC Plant Biology', '10.1186/s12870-021-03196-y', 'https://doi.org/10.1186/s12870-021-03196-y', 'https://doi.org/10.1186/s12870-021-03196-y', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Natural rubber (cis-1,4-polyioprene, NR) is an indispensable industrial raw material obtained from the Pará rubber tree (H. brasiliensis). Natural rubber cannot be replaced by synthetic rubber compounds because of the superior resilience, elasticity, abrasion resistance, efficient heat dispersion, and impact resistance of NR. In NR production, latex is harvested by periodical tapping of the trunk bark. Ethylene enhances and prolongs latex flow and latex regeneration. Ethephon, which is an ethylene-releasing compound, applied to the trunk before tapping usually results in a 1.5- to 2-fold increase in latex yield. However, intense mechanical damage to bark tissues by excessive tapping and/or over-stimulation with ethephon induces severe oxidative stress in laticifer cells, which often causes tapping panel dryness (TPD) syndrome. To enhance NR production without causing TPD, an improved understanding of the molecular mechanism of the ethylene response in the Pará rubber tree is required. Therefore, we investigated gene expression in response to ethephon treatment using Pará rubber tree seedlings as a model system. Results After ethephon treatment, 3270 genes showed significant differences in expression compared with the mock treatment. Genes associated with carotenoids, flavonoids, and abscisic acid biosynthesis were significantly upregulated by ethephon treatment, which might contribute to an increase in latex flow. Genes associated with secondary cell wall formation were downregulated, which might be because of the reduced sugar supply. Given that sucrose is an important molecule for NR production, a trade-off may arise between NR production and cell wall formation for plant growth and for wound healing at the tapping panel. Conclusions Dynamic changes in gene expression occur specifically in response to ethephon treatment. Certain genes identified may potentially contribute to latex production or TPD suppression. These data provide valuable information to understand the mechanism of ethylene stimulation, and will contribute to improved management practices and/or molecular breeding to attain higher yields of latex from Pará rubber trees.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9b1b809b-f075-43a2-b4ff-9ac1b3892c07', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'A Comprehensive Review of Pesticide Residues in Peppers', 'Shim JH, Eun JB, Zaky AA, Hussein AS, Hacimüftüoğlu A, Abd El-Aty AM', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12050970', 'https://doi.org/10.3390/foods12050970', 'https://europepmc.org/articles/PMC10000673?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Pesticides are chemicals that are used to control pests such as insects, fungi, and weeds. Pesticide residues can remain on crops after application. Peppers are popular and versatile foods that are valued for their flavor, nutrition, and medicinal properties. The consumption of raw or fresh peppers (bell and chili) can have important health benefits due to their high levels of vitamins, minerals, and antioxidants. Therefore, it is crucial to consider factors such as pesticide use and preparation methods to fully realize these benefits. Ensuring that the levels of pesticide residues in peppers are not harmful to human health requires rigorous and continuous monitoring. Several analytical methods, such as gas chromatography (GC), liquid chromatography (LC), mass spectrometry (MS), infrared spectroscopy (IR), ultraviolet-visible spectroscopy (UV-Vis), and nuclear magnetic resonance spectroscopy (NMR), can detect and quantify pesticide residues in peppers. The choice of analytical method depends on the specific pesticide, that is being tested for and the type of sample being analyzed. The sample preparation method usually involves several processes. This includes extraction, which is used to separate the pesticides from the pepper matrix, and cleanup, which removes any interfering substances that could affect the accuracy of the analysis. Regulatory agencies or food safety organizations typically monitor pesticide residues in peppers by stipulating maximum residue limits (MRLs). Herein, we discuss various sample preparation, cleanup, and analytical techniques, as well as the dissipation patterns and application of monitoring strategies for analyzing pesticides in peppers to help safeguard against potential human health risks. From the authors'' perspective, several challenges and limitations exist in the analytical approach to monitoring pesticide residues in peppers. These include the complexity of the matrix, the limited sensitivity of some analytical methods, cost and time, a lack of standard methods, and limited sample size. Furthermore, developing new analytical methods, using machine learning and artificial intelligence, promoting sustainable and organic growing practices, improving sample preparation methods, and increasing standardization could assist efficiently in analyzing pesticide residues in peppers.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fed0606a-5007-487e-8b56-072faf2101a9', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Alpha-Cypermethrin Resistance in Musca domestica: Resistance Instability, Realized Heritability, Risk Assessment, and Insecticide Cross-Resistance', 'Abbas N, Hafez AM', 2023, 'Insects', '10.3390/insects14030233', 'https://doi.org/10.3390/insects14030233', 'https://europepmc.org/articles/PMC10058011?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Musca domestica L., the common house fly, is a cosmopolitan carrier of human and livestock disease pathogens. The species exhibits resistance to many insecticides; therefore, effective M. domestica insecticide resistance management programs are required worldwide. In the present study, the development of alpha-cypermethrin resistance, realized heritability (h2), instability of resistance trait (DR), and cross-resistance (CR) was investigated in an alpha-cypermethrin-selected M. domestica strain (Alpha-Sel) across 24 generations (Gs). Compared with an alpha-cypermethrin-unselected strain (Alpha-Unsel), resistance to alpha-cypermethrin increased from 46.4-fold (G5) to 474.2-fold (G24) in Alpha-Sel females and 41.0-fold (G5) to 253.2-fold (G24) in Alpha-Sel males. Alpha-cypermethrin resistance declined by between -0.10 (G5) and -0.05 (G24) in both M. domestica sexes without insecticide exposure for 24 generations. The h2 of alpha-cypermethrin resistance was 0.17 and 0.18 for males and females, respectively, in G1-G24. With selection intensities of 10-90%, the G values required for a tenfold increase in the LC50 of alpha-cypermethrin were 6.3-53.7, 4.1-33.8, and 3.0-24.7, given h2 values of 0.17, 0.27, and 0.37, respectively, and a constant slope of 2.1 for males and h2 values of 0.18, 0.28, and 0.38, respectively, and a constant slope of 2.0 for females. Compared with Alpha-Unsel, Alpha-Sel M. domestica exhibited moderate CR to bifenthrin (15.5-fold), deltamethrin (28.4-fold), and cyfluthrin (16.8-fold), low CR to two pyrethroids and five organophosphates, and no CR to insect growth regulators. The instability of resistance trait, low h2, and absent or low CR associated with alpha-cypermethrin resistance in M. domestica indicate resistance could be managed with rotational use of the insecticide.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('23d62932-c42a-42f3-a3d6-471c4cdd57ad', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Aphid-Resistant Plant Secondary Metabolites: Types, Insecticidal Mechanisms, and Prospects for Utilization', 'Farhan M, Pan J, Hussain H, Zhao J, Yang H, Ahmad I, Zhang S', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13162332', 'https://doi.org/10.3390/plants13162332', 'https://europepmc.org/articles/PMC11360209?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Aphids pose a significant threat to global agricultural crop production, leading to widespread pesticide use and resistance. This necessitates the use of alternative substances, like plant secondary metabolites (PSMs). Plants have developed protective compounds known as alkaloids, terpenoids, phenolics, sulfur- and nitrogen-containing metabolites. These compounds exhibit promising characteristics against aphids, such as antifeedant, aphicidal, and disrupting survival fitness. This review highlights the importance and application of secondary metabolites in combating aphid populations. Different insect-resistant substances have different mechanisms for managing aphids and other pests, including defensive signaling, inhibiting growth, and attracting natural predators by releasing herbivore-induced volatiles (HIPV). The application of plant secondary metabolites as biopesticides has proven to be an effective, economical, and eco-friendly alternative to synthetic pesticide chemicals. Furthermore, this review comprehensively discusses the principle role of plant secondary metabolites, encouraging sustainable agricultural practices and emphasizing the integrated management of the aphid population.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('38314921-27ca-4a10-9e8b-c0dc7964edc7', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Arthropod Pest Management in Strawberry', 'Lahiri S, Smith HA, Gireesh M, Kaur G, Montemayor JD', 2022, 'Insects', '10.3390/insects13050475', 'https://doi.org/10.3390/insects13050475', 'https://europepmc.org/articles/PMC9147324?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The strawberry crop endures economic losses due to feeding injury from a number of phytophagous arthropod pests. A number of invasive pests have posed challenges to crop protection techniques in the strawberry cropping system recently. It is increasingly evident that sole reliance on chemical control options is not sustainable. In this review, current challenges and advances in integrated pest management of various strawberry pests are presented. Key pests discussed include thrips, mites, lygus bug, spotted wing drosophila, seed bug, weevils, aphids, whiteflies, and armyworms. Several integrated pest management techniques that include use of intercropping, resistant cultivars, irradiation with gamma rays, use of spectral sensitivity of pests, biological control agents and natural enemies, and biorational pesticides have recently been reported to be useful in managing the various strawberry pests. With the increase in world production of strawberry, several techniques will be necessary to manage the pest complex of strawberry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('244f0c2a-4bef-4c52-b85c-1639bd5ec10b', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Association of voltage-gated sodium channel mutations with field-evolved pyrethroid resistant phenotypes in soybean aphid and genetic markers for their detection', 'Valmorbida I, Hohenstein JD, Coates BS, Bevilaqua JG, Menger J, Hodgson EW, Koch RL, O''Neal ME', 2022, 'Scientific reports', '10.1038/s41598-022-16366-1', 'https://doi.org/10.1038/s41598-022-16366-1', 'https://europepmc.org/articles/PMC9283502?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The frequent use of insecticides to manage soybean aphids, Aphis glycines (Hemiptera: Aphididae), in the United States has contributed to field-evolved resistance. Pyrethroid-resistant aphids have nonsynonymous mutations in the voltage-gated sodium channel (vgsc). We identified a leucine to phenylalanine mutation at position 1014 (L1014F) and a methionine to isoleucine mutation (M918I) of the A. glycines vgsc, both suspected of conferring knockdown resistance (kdr) to lambda-cyhalothrin. We developed molecular markers to identify these mutations in insecticide-resistant aphids. We determined that A. glycines which survived exposure to a diagnostic concentration of lambda-cyhalothrin and bifenthrin via glass-vial bioassays had these mutations, and showed significant changes in the resistance allele frequency between samples collected before and after field application of lambda-cyhalothrin. Thus, a strong association was revealed between aphids with L1014F and M918I vgsc mutations and survival following exposure to pyrethroids. Specifically, the highest survival was observed for aphids with the kdr (L1014F) and heterozygote super-kdr (L1014F + M918I) genotypes following laboratory bioassays and in-field application of lambda-cyhalothrin. These genetic markers could be used as a diagnostic tool for detecting insecticide-resistant A. glycines and monitoring the geographic distribution of pyrethroid resistance. We discuss how generating these types of data could improve our efforts to mitigate the effects of pyrethroid resistance on crop production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06d6419d-ec40-4102-a40c-175036897fab', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Determining Field Insecticide Efficacy on Whiteflies with Maximum Dose Bioassays', 'Cremonez PSG, Perier JD, Simmons AM, Riley DG', 2023, 'Insects', '10.3390/insects14060510', 'https://doi.org/10.3390/insects14060510', 'https://europepmc.org/articles/PMC10299426?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'We conducted a rapid bioassay method to assess insecticide efficacy for controlling adult sweetpotato whitefly Bemisia tabaci in squash and cucumber crops before insecticide applications. The study aimed to evaluate the accuracy of a 24-hour laboratory bioassay in determining maximum dose insecticide efficacy in the field. Ten insecticides were evaluated using leaf-dip bioassays, and their effectiveness was tested across eight cucurbit field experiments in Georgia, USA, during the 2021 and 2022 field seasons. The maximum dose, defined as the highest labeled rate of an insecticide diluted in the equivalent of 935 L ha-1 of water, was used for all bioassays. Adult survival observed in the bioassay was compared to adult field count-based survival 24 h after treatment. A low concentration (1/10 rate) was used for imidacloprid, flupyradifurone, pyriproxyfen, and cyantraniliprole to assess insecticide tolerance in the whitefly population. Overall, significant positive correlation between laboratory bioassay and field efficacy was reported, explaining 50-91% of the observed variation. The addition of the low dosage was helpful, indicating that no rate response was consistent with susceptibility to the tested insecticide, while a rate response was associated with a loss of susceptibility between 2021 and 2022.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1aea81a1-a2b3-4e8b-a978-3b0f16f4bc70', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Biochemical mechanisms of flonicamid resistance and its transgenerational effects in Bemisia tabaci mitotype Asia-II-1', 'Zafar Hussain, Shoaib Freed', 2025, 'Scientific Reports', '10.1038/s41598-025-18268-4', 'https://doi.org/10.1038/s41598-025-18268-4', 'https://doi.org/10.1038/s41598-025-18268-4', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Bemisia tabaci is amongst noxious pest of the cotton, vegetables and ornamentals. Insecticides, for instance neonicotinoids, carbamates, organophosphates and pyrethroids are employed to control B. tabaci. Owing to the excessive use of chemicals, high level of resistance has been developed in B. tabaci. Flonicamid, a systemic insecticide inhibits insect’s feeding and is potent against B. tabaci. The potential mechanisms underlying resistance to flonicamid in B. tabaci Asia-II-1 were investigated for 16 generations and biochemical assays were performed for the possible involvement of enzymes in the resistance development. In addition, the transgenerational effects were also assessed. Flonicamid resistant strain was developed with 161.5 folds increase in resistance at 16th generation (LC50 = 1376.8 mg/L) compared to the susceptible UNSEL population (LC50 = 8.52 mg/L). The biochemical analysis revealed substantial rise in the activities of glutathione S-transferases and esterases after exposure to flonicamid, while acetylcholinesterase, alkaline and acid phosphatase showed slight increase in activity. The increased activity may possibly favor flonicamid resistance. In the parental generation (F0), treatment with flonicamid at low (LC30) and high (LC50) concentrations reduced fecundity to 60.85 and 43.88 eggs per female, compared to 77.55 in the control. Female longevity decreased to 26.42 (LC30) and 23.12 (LC50) days, compared to 29.45 days in the control, while male longevity dropped to 25.81 (LC30) and 21.84 (LC50) days, compared to 27.47 days in F0. In the F1 generation, total longevity decreased to 23.73 (LC30) and 19.87 (LC50) days, compared to 27.02 days in the control. Female longevity was reduced to 26.35 (LC30) and 23.04 (LC50) days, compared to 29.32 days in the control, and male longevity was decreased to 25.69 (LC30) and 21.72 (LC50) days, compared to 27.38 days in the control. The mean generation time (T), intrinsic rate of increase (r), and net reproductive rate (R₀) were significantly reduced in both LC30 and LC50 treatments compared to the control, with more pronounced effects observed at LC50. The current study imparts a thorough analysis of the insecticide resistance development and changes in enzyme activities. Our findings provide detailed information about the general impact of flonicamid on B. tabaci, which might be helpful for its management.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e202d2c3-5ac5-4042-8b0c-363f9e88b69f', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'The Efficacy of Fungicides Against Cercospora beticola in Field Conditions', 'Hudec Kamil, Mihók Milan, Roháčik Tibor', 2023, 'Agriculture', '10.2478/agri-2023-0010', 'https://doi.org/10.2478/agri-2023-0010', 'https://doi.org/10.2478/agri-2023-0010', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'This study is focused on the evaluation of the efficacy of conventional fungicides against Cercospora leaf spot (CLS) on sugar beet. The results showed that the best protection against CLS was achieved by treatment with kresoxim-methyl + epoxiconazole (T1) and tetraconazole (T2). The second highest fungicide efficacy was detected after treatment with (kresoxim-methyl + epoxiconazole -T1) + difenoconazole -T2, followed by (azoxystrobin + cyproconazole) + difenoconazole, (prochloraz + propiconazole) + tetraconazole, Urtica dioica plant extracts + Salix spp. plant extracts, (trifloxystrobin + cyproconazole) + tetraconazole, and picoxystrobin + tetraconazole. The positive effect of fungicide protection on yield and sugar content was higher in the year with a higher occurrence of CLS. Good CLS management could increase the root yield by up to 19.34%, and sugar yield by up to 23.83% in comparison to the untreated check. The highest sugar yield was achieved in the treatment by (prochloraz + propiconazole) + tetraconazole, followed by (kresoxim-methyl + epoxiconazole) + difenoconazole, (azoxystrobin + cyproconazole) + difenoconazole, (trifloxystrobin + cyproconazole) + tetraconazole, picoxystrobin + tetraconazole, and Urtica dioica plant extracts + Salix spp. plant extracts. The results showed a strong relationship of root yield and sugar yield on fungicide treatment during the vegetation. The occurrence of fungicide resistance in Cercospora beticola population has an important impact on efficacy of applied fungicides in field conditions. The highest economic effectiveness coefficient was achieved at treatment by (prochloraz + propiconazole) + tetraconazole.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48adbdfb-76b8-45ac-9ad5-fe056f7e5f4c', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Classification, biology and entomopathogenic fungi-based management and their mode of action against Drosophila species (Diptera: Drosophilidae): a review', 'Vivekanandhan P, Swathy K, Sarayut P, Patcharin K', 2024, 'Frontiers in microbiology', '10.3389/fmicb.2024.1443651', 'https://doi.org/10.3389/fmicb.2024.1443651', 'https://europepmc.org/articles/PMC11493638?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'This review provides a comprehensive analysis of the classification, biology, and management of Drosophila species (Diptera: Drosophilidae) with a focus on entomopathogenic fungi (EPF) as a biocontrol strategy. Drosophila species, particularly Drosophila suzukii, and Drosophila melanogaster have emerged as significant pests in various agricultural systems, causing extensive damage to fruit crops. Understanding their taxonomic classification and biological traits is crucial for developing effective management strategies. This review delves into the life cycle, behavior, and ecological interactions of Drosophila species, highlighting the challenges posed by their rapid reproduction and adaptability. The review further explores the potential of EPF as an eco-friendly alternative to chemical pesticides. The mode of action of EPF against Drosophila species is examined, including spore adhesion, germination, and penetration of the insect cuticle, leading to host death. Factors influencing the efficacy of EPF, such as environmental conditions, fungal virulence, and host specificity, are discussed in detail. By synthesizing current research, this review aims to provide valuable insights into the application of EPF and to identify future research directions for enhancing the effectiveness of EPF-based control measures against Drosophila species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a7b5a2c2-3ce7-4cfb-8197-d3c81c8ab035', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Compatibility and synergistic interactions of fungi, Metarhizium anisopliae, and insecticide combinations against the cotton aphid, Aphis gossypii Glover (Hemiptera: Aphididae)', 'Nawaz A, Razzaq F, Razzaq A, Gogi MD, Fernández-Grandon GM, Tayib M, Ayub MA, Sufyan M', 2022, 'Scientific reports', '10.1038/s41598-022-08841-6', 'https://doi.org/10.1038/s41598-022-08841-6', 'https://europepmc.org/articles/PMC8941032?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Aphids are major pests affecting cereals, vegetables, fruit, forestry and horticultural produce. A multimodal approach may be an effective route to controlling this prolific pest. We assessed the individual and combined effect of eight insecticides and the entomopathogenic fungi, Metarhizium anisopliae (Metschin.) against the cotton aphid, Aphis gossypii Glover (Hemiptera: Aphididae), under laboratory conditions. Six of the insecticides tested were found to be highly compatible (flonicamid, imidacloprid, nitenpyram, dinotefuran, pyriproxyfen and spirotetramat), showing positive integration with the fungus and were selected for bioassays. The combination mixtures (1:1 ratio of M. anisopliae: insecticide) were significantly more toxic to A. gossypii than individual treatments. Maximum mortality (91.68%) of A. gossypii was recorded with combination of flonicamid and M. anisopliae (2.4 × 106 cfu/ml) 72 h after application. While minimum mortality (17.08%) was observed with the individual treatment of M. anisopliae (2.4 × 106 cfu/ml). The insecticides revealed toxicity consistent with their compatibility with M. anisopliae, ranking for efficacy exactly as they did for compatibility. In addition, the synergy factor (SF) and co-toxicity coefficient (CTC) values indicated synergistic interactions at different time intervals. The synergistic efficacy revealed the potential of fungus-insecticide integration against sucking insect pests.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bcdf084c-cfad-4643-ad70-7560c34e2e01', '1ac6f7be-9352-4aed-a714-2590e193c83f', 'Determination of historical changes in salinity', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/determination-of-historical-changes-in-salinity', 'https://open.alberta.ca/dataset/b5ec7295-5199-423d-b812-0f34bff85ef8/resource/18a60a9a-f35c-4968-b168-70c04d7d7374/download/afrd-aesa-determination-historical-changes-in-salinity.pdf', NULL, NULL, 6, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'The process of salinization is slow and variable. This underlines the need for long-term determination of changes in salinity and the need for appropriate methodologies. The most reliable historical data covering large areas is aerial photography. A series of air-photos were used to determine the extent of visible salinity for each decade since 1950 for 89 sites in the Brown, Dark Brown and Black soil zones in Alberta. Three ground water flow systems were looked at including: local, regional and irrigation. Paper presented to the 37th Annual Alberta Soil Science Workshop , February 22-24, 2000, Medicine Hat, Alberta.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0cfc8d95-b875-4967-8b0d-e1542d3e8613', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Effects of Aphicides on Pecan Aphids and Their Parasitoids in Pecan Orchards', 'Eddie K. Slusher, Ted Cottrell, Angelita L. Acebes-Doria', 2021, 'Insects', '10.3390/insects12030241', 'https://doi.org/10.3390/insects12030241', 'https://www.mdpi.com/2075-4450/12/3/241', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Aphids are important pests of pecans. Traditionally, insecticides have been the primary method of management. However, over-reliance and non-judicious use has led to resistance and damage to natural enemy populations. Therefore, frequent assessment of insecticides is necessary in order to monitor resistance development and non-target impacts. Aphicides, flonicamid, sulfoxaflor, and afidopyropen were assessed for their effects on pecan aphids and parasitoid, Aphelinus perpallidus, in a mature pecan orchard in 2019 and 2020. Post-application assessments were performed 7, 14, and 21 days post-application. Leaf samples from non-treated trees had greater aphid numbers than treated trees 7 days post-application with differences diminishing throughout the other two treatment periods in 2019. In 2020, aphid numbers were lower but leaf samples from non-treated trees had more aphids than treated trees 7 days post-application in the lower canopy. These differences again diminished 14 and 21 days post-application. There was no difference among treatments in number of parasitoid adults or mummies. These findings indicate that pecan growers have multiple potential options available for aphid management that do not negatively impact the primary pecan aphid parasitoid. Implications of the results on pecan aphid management are discussed.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('97a6c24d-6e03-4089-a504-e4371981bf12', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Efficacy of Conventional and Biorational Insecticides against the Invasive Pest Thrips parvispinus (Thysanoptera: Thripidae) under Containment Conditions', 'Ataide LMS, Vargas G, Velazquez-Hernandez Y, Reyes-Arauz I, Villamarin P, Canon MA, Yang X, Riley SS', 2024, 'Insects', '10.3390/insects15010048', 'https://doi.org/10.3390/insects15010048', 'https://europepmc.org/articles/PMC10816096?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'In 2020, the invasive Thrips parvispinus (Karny) was first detected in Florida, United States. In response to the implemented regulatory restrictions, we conducted laboratory experiments under containment conditions. Thrips larvae and adults were exposed to 32 products (conventional and biorational insecticides) either directly or indirectly. Direct exposure was performed using a Spray Potter Tower, while indirect exposure was conducted by evaluating residue toxicity against the thrips. Water served as a control. We assessed mortality and leaf-feeding damage 48 h post-treatment. Among the conventional insecticides, chlorfenapyr, sulfoxaflor-spinetoram, and spinosad caused high mortality across all stages in both direct and residue toxicity assays. Pyridalyl, acetamiprid, tolfenpyrad, cyclaniliprole-flonicamid, acephate, novaluron, abamectin, cyantraniliprole, imidacloprid, cyclaniliprole, spirotetramat, and carbaryl displayed moderate toxicity, affecting at least two stages in either exposure route. Additionally, chlorfenapyr, spinosad, sulfoxaflor-spinetoram, pyridalyl, acetamiprid, cyclaniliprole, cyclaniliprole-flonicamid, abamectin, and acephate inhibited larvae and adult''s leaf-feeding damage in both direct and residue toxicity assays. Regarding biorational insecticides, mineral oil (3%) and sesame oil caused the highest mortality and lowest leaf-feeding damage. Greenhouse evaluations of spinosad, chlorfenapyr, sulfoxaflor-spinetoram, and pyridalyl are recommended. Also, a rotation program incorporating these products, while considering different modes of action, is advised for ornamental growers to avoid resistance and to comply with regulations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('464643c5-1906-4044-967b-be5845905f80', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Evaluation of Insecticide Toxicity and Field Performance Against Myzus persicae (Hemiptera: Aphididae) in Laboratory and Greenhouse Conditions', 'Safwat G. Sabra, Naeem Abbas, Abdulwahab M. Hafez', 2025, 'Agronomy', '10.3390/agronomy15020280', 'https://doi.org/10.3390/agronomy15020280', 'https://www.mdpi.com/2073-4395/15/2/280', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Myzus persicae Sulzer (Hemiptera: Aphididae) is a pivotal pest affecting various vegetables, fruits, crops, and ornamentals. The primary M. persicae management strategy involves insecticide use. In this study, the toxicity and efficacy of bifenthrin, fenitrothion, fosthiazate, acetamiprid, spirotetramat, afidopyropen, and flonicamid against M. persicae were evaluated under laboratory and greenhouse conditions using the leaf dip method. Laboratory bioassay results revealed that M. persicae exhibited susceptibility to moderate resistance levels for bifenthrin [resistance ratio (RR): 3.00–21.50], fenitrothion (3.13–25.31), fosthiazate (3.00–20.00), and acetamiprid (2.00–14.50), as well as susceptibility to low resistance levels for spirotetramat (0.75 to 6.63). Additionally, M. persicae was susceptible to flonicamid (0.31–1.72) and afidopyropen (0.67–2.00). Furthermore, laboratory bioassays revealed that the Al-Dhabia M. persicae field population showed the highest resistance levels to all tested insecticides compared with other tested field populations, which guided the examination of insecticide field performance under greenhouse conditions. In the greenhouse, most insecticides demonstrated high efficacy (>90%) against M. persicae with enduring effects, except for bifenthrin, which began to lose effectiveness 10 days post-application. In conclusion, M. persicae displayed overall susceptibility to most tested chemical classes, and the prolonged efficacy of these insecticides in the field reinforces their effectiveness in controlling this pest species. To maintain this control level, the registration of novel insecticides such as flonicamid and afidopyropen in Saudi Arabia is imperative, expanding the repertoire of effective chemical tools for M. persicae control. Additionally, a rotational approach to using all effective chemical classes is crucial to preventing or delaying resistance development in M. persicae.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5df9e25d-aa89-48cf-8049-b55231de04c8', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Feeding Behavior and Virus-Transmission Ability of Insect Vectors Exposed to Systemic Insecticides', 'Garzo E, Moreno A, Plaza M, Fereres A', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9070895', 'https://doi.org/10.3390/plants9070895', 'https://europepmc.org/articles/PMC7411831?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The majority of plant viruses depend on Hemipteran vectors for their survival and spread. Effective management of these insect vectors is crucial to minimize the spread of vector-borne diseases, and to reduce crop damage. The aim of the present study was to evaluate the effect of various systemic insecticides on the feeding behavior of Bemisia tabaci and Myzus persicae, as well as their ability to interfere with the transmission of circulative viruses. The obtained results indicated that some systemic insecticides have antifeeding properties that disrupt virus transmission by their insect vectors. We found that some of the tested insecticides significantly reduced phloem contact and sap ingestion by aphids and whiteflies, activities that are closely linked to the transmission of phloem-limited viruses. These systemic insecticides may play an important role in reducing the primary and secondary spread of tomato yellow leaf curl virus (TYLCV) and turnip yellows virus (TuYV), transmitted by B. tabaci and M. persicae, respectively.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('53c0ca0c-4b72-4393-b54a-efb3224c0cf4', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'First transgenic trait for control of plant bugs and thrips in cotton', 'Akbar W, Gowda A, Ahrens JE, Stelzer JW, Brown RS, Bollman SL, Greenplate JT, Gore J', 2019, 'Pest management science', '10.1002/ps.5234', 'https://doi.org/10.1002/ps.5234', 'https://europepmc.org/articles/PMC6590345?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundPlant bugs (Lygus spp.) and thrips (Thrips spp.) are two of the most economically important insect pest groups impacting cotton production in the USA today, but are not controlled by current transgenic cotton varieties. Thus, seed or foliar-applied chemical insecticides are typically required to protect cotton from these pest groups. Currently, these pests are resistant to several insecticides, resulting in fewer options for economically viable management. Previous publications documented the efficacy of transgenic cotton event MON 88702 against plant bugs and thrips in limited laboratory and field studies. Here, we report results from multi-location and multi-year field studies demonstrating efficacy provided by MON 88702 against various levels of these pests.ResultsMON 88702 provided a significant reduction in numbers of Lygus nymphs and subsequent yield advantage. MON 88702 also had fewer thrips and minimal injury. The level of control demonstrated by this transgenic trait was significantly better compared with its non-transgenic near-isoline, DP393, receiving insecticides at current commercial rates.ConclusionThe level of efficacy demonstrated here suggests that MON 88702, when incorporated into existing IPM programs, could become a valuable additional tool for management of Lygus and thrips in cotton agroecosystems experiencing challenges of resistance to existing chemical control strategies. © 2018 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e230ebf3-b75e-426b-802d-70c674f9e26d', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Fitness costs of resistance to insecticides in insects', 'Gul H, Gadratagi BG, Güncan A, Tyagi S, Ullah F, Desneux N, Liu X', 2023, 'Frontiers in physiology', '10.3389/fphys.2023.1238111', 'https://doi.org/10.3389/fphys.2023.1238111', 'https://europepmc.org/articles/PMC10620942?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The chemical application is considered one of the most crucial methods for controlling insect pests, especially in intensive farming practices. Owing to the chemical application, insect pests are exposed to toxic chemical insecticides along with other stress factors in the environment. Insects require energy and resources for survival and adaptation to cope with these conditions. Also, insects use behavioral, physiological, and genetic mechanisms to combat stressors, like new environments, which may include chemicals insecticides. Sometimes, the continuous selection pressure of insecticides is metabolically costly, which leads to resistance development through constitutive upregulation of detoxification genes and/or target-site mutations. These actions are costly and can potentially affect the biological traits, including development and reproduction parameters and other key variables that ultimately affect the overall fitness of insects. This review synthesizes published in-depth information on fitness costs induced by insecticide resistance in insect pests in the past decade. It thereby highlights the insecticides resistant to insect populations that might help design integrated pest management (IPM) programs for controlling the spread of resistant populations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8ef92f4-8d58-4f9f-a70d-001262652008', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Huanglongbing Pandemic: Current Challenges and Emerging Management Strategies', 'Ghosh D, Kokane S, Savita BK, Kumar P, Sharma AK, Ozcan A, Kokane A, Santra S', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants12010160', 'https://doi.org/10.3390/plants12010160', 'https://europepmc.org/articles/PMC9824665?pdf=render', NULL, NULL, 57, NULL, 'other', 1, 'cc by', 'Huanglongbing (HLB, aka citrus greening), one of the most devastating diseases of citrus, has wreaked havoc on the global citrus industry in recent decades. The culprit behind such a gloomy scenario is the phloem-limited bacteria "Candidatus Liberibacter asiaticus" (CLas), which are transmitted via psyllid. To date, there are no effective long-termcommercialized control measures for HLB, making it increasingly difficult to prevent the disease spread. To combat HLB effectively, introduction of multipronged management strategies towards controlling CLas population within the phloem system is deemed necessary. This article presents a comprehensive review of up-to-date scientific information about HLB, including currently available management practices and unprecedented challenges associated with the disease control. Additionally, a triangular disease management approach has been introduced targeting pathogen, host, and vector. Pathogen-targeting approaches include (i) inhibition of important proteins of CLas, (ii) use of the most efficient antimicrobial or immunity-inducing compounds to suppress the growth of CLas, and (iii) use of tools to suppress or kill the CLas. Approaches for targeting the host include (i) improvement of the host immune system, (ii) effective use of transgenic variety to build the host''s resistance against CLas, and (iii) induction of systemic acquired resistance. Strategies for targeting the vector include (i) chemical and biological control and (ii) eradication of HLB-affected trees. Finally, a hypothetical model for integrated disease management has been discussed to mitigate the HLB pandemic.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9fd92df8-80b4-4432-9ea9-f7b11573eb69', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Status and outlook for acaricide and insecticide discovery', 'Jeschke P', 2021, 'Pest management science', '10.1002/ps.6084', 'https://doi.org/10.1002/ps.6084', 'https://europepmc.org/articles/PMC7756306?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'To guarantee sustainability and progress, the agrochemical industry is faced with several major challenges. Currently, loss of active ingredients due to consumer perception, changing grower needs and ever-changing regulatory requirements is far higher than the number being introduced into the market. Therefore, there is a need to develop new products that can provide improved efficacy, selectivity and favorable environmental profiles. Strategies to achieve these goals are the search for acaricides and insecticides with new modes of action, or the discovery of novel molecules with activity on the most attractive target sites having resistance breaking properties against pest species. In this context, the introduction of halogen atoms or asymmetric centers into an active ingredient remains an important tool to modulate their properties, but so too is the pro-pesticide concept. This review gives an overview of agrochemicals launched over the past 8 years, reflects new insights into known mechanisms of action, and describes the status and outlook for acaricide and insecticide discovery.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('381e2968-3db3-436d-af43-dc1d2dfe9ac0', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Inheritance Pattern and Cross-Resistance Assessment of Flonicamid Resistance in the Biological Control Agent Chrysoperla carnea (Neuroptera: Chrysopidae)', 'Arbaz Khan, Sarfraz Ali Shad', 2025, 'Jurnal Riset Perkebunan', '10.25077/jrp.6.2.92-103.2025', 'https://doi.org/10.25077/jrp.6.2.92-103.2025', 'https://jrp.faperta.unand.ac.id/index.php/jrp/article/view/131', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'A field-collected laboratory population of Chrysoperla carnea, a polyphagous predator important in integrated pest management, was subjected to flonicamid selection pressure for three generations using a micro-droplet topical bioassay. Following selection, the flonicamid-selected strain exhibited 6.83-fold resistance (LC50 = 260,730 ppm; 95% FL = 148,090–1,561,600 ppm) compared with the unselected strain (LC50 = 38,122 ppm; 95% FL = 23,259–138,440 ppm). Reciprocal crosses between resistant and susceptible parents produced overlapping 95% FLs, demonstrating autosomal inheritance with no detectable maternal or sex-linked effects. Dominance metrics indicated incomplete to partial dominance of resistance (DLC = 0.60 for F1; DLC = 0.55 for F2). Effective dominance estimates at four diagnostic doses (27,875; 62,500; 125,000; 272,000 ppm) yielded ED values of 0.53, 0.79, 0.91, and 0.88, respectively, showing increased dominance at higher doses. Chi-square goodness-of-fit tests rejected the null hypothesis of monogenic inheritance (p < 0.05), confirming a polygenic resistance model. Cross-resistance bioassays further revealed substantial co-selection effects, with resistance ratios of 24.35-fold for acetamiprid, 23.58-fold for triazophos, and 15.17-fold for deltamethrin, comparing initial and final LC50 values that showed non-overlapping 95% FLs. These results indicate that flonicamid resistance in C. carnea is a polygenic, autosomal, and incompletely to partially dominant trait. The findings provide genetic foresight for incorporating resistant predator populations into insecticide-compatible IPM programs and highlight the importance of mode-of-action-based chemical rotation to mitigate resistance co-selection in beneficial predator populations.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('374a956d-2c9f-4b61-8067-7873d87c36b3', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Insecticide Resistance Evolution Negatively Affects the Fitness of Aphis gossypii Glover During Selection on Cotton Plants Under Laboratory Conditions', 'Hina Gul, Ali Güncan, Arzlan Abbas, Zeeshan Ullah, Xie Yuqing, Farman Ullah, Nicolas Desneux, Xiaoxia Liu', 2025, 'Plants', '10.3390/plants14162527', 'https://doi.org/10.3390/plants14162527', 'https://www.mdpi.com/2223-7747/14/16/2527', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The cotton aphid, Aphis gossypii Glover, is among the most economically significant sap-sucking insect pests, inflicting substantial economic losses worldwide. Insecticides such as thiamethoxam, bifenthrin, and flonicamid are commonly used to manage this pest, despite the inherent risk of developing resistance. In this study, we investigated the evolution of insecticide resistance in A. gossypii after continuous selection with thiamethoxam, bifenthrin, and flonicamid over more than ten generations in a controlled laboratory environment. We assessed the fitness of resistant strains using an age-stage, two-sex life table approach, comparing them to a susceptible population. The results indicated that A. gossypii achieved resistance levels of 158.60-fold against thiamethoxam, 129.18-fold against bifenthrin, and 104.75-fold against flonicamid. Furthermore, life table analyses revealed that the developmental stages were significantly extended, while longevity decreased in all resistant strains compared to the susceptible population. Additionally, the net reproductive rate (R0), fecundity, and reproductive days were notably reduced in the resistant cohorts when compared to the susceptible strain. Overall, these findings provide valuable insights into the laboratory-induced evolution of insecticide resistance and the associated fitness costs in A. gossypii when feeding on cotton plants. This information could be instrumental in formulating effective resistance management strategies to control this significant pest.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4c98767b-4a11-4d34-8712-63677a90c181', '1ac6f7be-9352-4aed-a714-2590e193c83f', 'Dryland salinity in Alberta', 'Government of Alberta', 1982, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/dryland-salinity-in-alberta', 'https://open.alberta.ca/dataset/b6d28fff-6f2f-4469-b72f-74475314adfa/resource/8d84d2c6-a357-4dc1-b33b-d1d352b2b59e/download/dryland-salinity-in-alberta.pdf', NULL, NULL, 52, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This document reported on the Environment Council of Alberta''s investigation into the long term security of Alberta''s agricultural land base and outlined key pressures affecting agricultural land and productivity. It described how growth and competing land uses, resource extraction, farming practices, and other activities had created cumulative risks to agricultural land availability and capability. It identified three main areas of concern, including loss and fragmentation of agricultural land, impacts on the land''s ability to produce agricultural products, and impacts from other activities that affected agricultural efficiency. It explained that the investigation examined the types and magnitude of perceived threats and considered current and future responses. It also discussed dryland salinity in southern Alberta, including the problem, potential solutions, and measures to control its spread.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec766803-952a-4466-b1ed-eb12cf83f8ee', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Insecticide-contaminated honeydew: risks for beneficial insects', 'Calvo-Agudo M, Tooker JF, Dicke M, Tena A', 2022, 'Biological reviews of the Cambridge Philosophical Society', '10.1111/brv.12817', 'https://doi.org/10.1111/brv.12817', 'https://europepmc.org/articles/PMC9299500?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Honeydew is the sugar-rich excretion of phloem-feeding hemipteran insects such as aphids, mealybugs, whiteflies, and psyllids, and can be a main carbohydrate source for beneficial insects in some ecosystems. Recent research has revealed that water-soluble, systemic insecticides contaminate honeydew excreted by hemipterans that feed on plants treated with these insecticides. This contaminated honeydew can be toxic to beneficial insects, such as pollinators, parasitic wasps and generalist predators that feed on it. This route of exposure has now been demonstrated in three plant species, for five systemic insecticides and four hemipteran species; therefore, we expect this route to be widely available in some ecosystems. In this perspective paper, we highlight the importance of this route of exposure by exploring: (i) potential pathways through which honeydew might be contaminated with insecticides; (ii) hemipteran families that are more likely to excrete contaminated honeydew; and (iii) systemic insecticides with different modes of action that might contaminate honeydew through the plant. Furthermore, we analyse several model scenarios in Europe and/or the USA where contaminated honeydew could be problematic for beneficial organisms that feed on this ubiquitous carbohydrate source. Finally, we explain why this route of exposure might be important when exotic, invasive, honeydew-producing species are treated with systemic insecticides. Overall, this review opens a new area of research in the field of ecotoxicology to understand how insecticides can reach non-target beneficial insects. In addition, we aim to shed light on potential undescribed causes of insect declines in ecosystems where honeydew is an important carbohydrate source for insects, and advocate for this route of exposure to be included in future environmental risk assessments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a97be158-06c0-48ff-8769-4dc1bd97f197', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Monitoring insecticide resistance in cotton leafhopper in relation to enzymatic activity in major cotton growing areas of central India', 'V. Chinna Babu Naik, Lingutla Rajesh Chowdary, G. Nagaharish, V. S. Nagarare, Jasti Sri Vishnu Murthy, Gillesugur Sham Supreeth, T. N. Madhu, Sujit Kumbhare', 2026, 'Scientific Reports', '10.1038/s41598-026-36055-7', 'https://doi.org/10.1038/s41598-026-36055-7', 'https://doi.org/10.1038/s41598-026-36055-7', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Insecticide resistance complicates pest management by reducing chemical effectiveness and increasing environmental pollution from higher application rates. Monitoring resistance is essential before recommending chemicals in any agro-ecological region. The present study evaluated the extent and mechanisms of insecticide resistance in the cotton leafhopper, Amrasca biguttula biguttula (Ishida) (Hemiptera: Cicadellidae), across major cotton-growing regions of Maharashtra, India over five consecutive years, from 2015–16 to 2019–20 at ICAR-Central Institute for Cotton Research (CICR) in Nagpur. The bioassay studies using IRAC protocols revealed that populations collected from the Amravati district of Maharashtra exhibited higher LC50 values for all tested insecticides, including Flonicamid 50WG, Thiamethoxam 25WG, Acetamiprid 20SP, Imidacloprid 17.8SL, Monocrotophos 36SL, Acephate 75SP, Clothianidin 50WDG, and Spiromesifen 22.9SC. The tentative discriminating doses were established based on a susceptible population of A. biguttula at 1, 0.2, 0.05, 0.01, 0.001, 0.0001, and a control of 0 ppm. Using standardized IRAC bioassay protocols, we assessed resistance levels for eight insecticides and noted significant increases in LC50 values. Notably, the A. biguttula biguttula populations from Yavatmal, Chandrapur, and Amravati exhibited critical resistance to neonicotinoids and other classes of insecticides. Biochemical assays revealed elevated activities of detoxifying enzymes, including cytochrome P450 monooxygenases, carboxylesterases, and glutathione S-transferases (GST), indicating metabolic resistance as a key mechanism. Notably, Amravati populations displayed the highest enzyme activities (e.g., GST up to 555.56 pmol/min/mg protein), correlating with intense insecticide use. These findings emphasize the need for integrated pest management (IPM) strategies, including insecticide rotation, biological controls, and resistant cotton hybrids, to mitigate insecticide resistance and minimise environmental impact. Regular monitoring of resistance and enzyme activity is essential for sustainable pest control in cotton ecosystems.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8641a972-dd8d-493b-bced-f53c9789e9ab', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Synergistic boosting of insecticide efficacy by the phytochemical (−)-(S)-palasonin: A cross-class enhancement for aphid control with laboratory-field concordance', 'Jiyuan Liu, Pengyu Chang, Ran Yin, Dongliang Wang, Ruichi Li, Zhen Tian, Yifan Li, Yalin Zhang', 2026, 'Industrial Crops and Products', '10.1016/j.indcrop.2026.122772', 'https://doi.org/10.1016/j.indcrop.2026.122772', 'http://www.sciencedirect.com/science/article/pii/S0926669026001585', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Aphids impose chronic yield and quality losses in intensive production systems while escalating resistance erodes the reliability of conventional insecticides. Plant-derived actives from industrial crops offer renewable chemistry but often require formulation strategies to ensure robust field performance. Here we evaluate (−)-(S)-palasonin (PLN), a cantharidin analogue isolated from Butea monosperma (Lam.) Kuntze seeds, as a bioactive botanical insecticide and assess its synergistic effects when combined with multiple classes of insecticides against the cotton aphid Aphis gossypii Glover and green peach aphid Myzus persicae (Sulzer). Using a standardized leaf-dip assay, PLN showed high intrinsic activity (48 h LC₅₀ = 31.22 mg L⁻¹ for A. gossypii; 102.86 mg L⁻¹ for M. persicae). Preliminary LC₅₀-equivalent screens and fixed-ratio designs identified robust ratio-dependent enhancement with multiple chemistries. Quantitative co-toxicity coefficients (CTC) at empirically optimized ratios confirmed marked synergism in A. gossypii-notably with acetamiprid (CTC = 628.7) and imidacloprid (548.5)-and pronounced synergy in M. persicae with acetamiprid (272.2) and imidacloprid (265.1); λ-cyhalothrin was moderately synergistic (e.g., CTC = 203.5 in A. gossypii; 142.6 in M. persicae). The PLN-spirotetramat mixture was additive in M. persicae (CTC = 81.4), and PLN-flonicamid showed no synergistic optimum in that species. In a randomized complete block field trial conducted in Aksu, Xinjiang, China, the PLN co-formulations showed significantly higher Henderson-Tilton-corrected efficacy against A. gossypii than the single agents at 3–5 days after treatment(DAT). Collectively, these findings indicate that PLN is a bioactive botanical insecticide derived from an industrial crop that delivers robust dose-sparing benefits through synergistic interactions when combined with conventional insecticides, providing a practical route to strengthen aphid control while supporting integrated pest-management goals.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa9f4390-7911-471b-bb5a-54f1fc8ba692', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Pesticide use in integrated pest and pollinator management framework to protect pollinator health', 'Phan NT, Biddinger DJ, Rajotte EG, Smagghe G, Reddy GV, Ren ZX, Joshi NK', 2025, 'Pest management science', '10.1002/ps.8582', 'https://doi.org/10.1002/ps.8582', 'https://europepmc.org/articles/PMC11906915?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by-nc-nd', 'Agricultural pesticides have historically been a critical tool in controlling pests and diseases, preventing widespread suffering and crop losses that led to catastrophes such as the Great Irish Famine (1845-1852) and the Cotton Boll Weevil Infestation (1915-1916). However, their usage has brought challenges, including resistance development, secondary pest outbreaks, harm to non-target organisms like pollinators, and environmental contamination. In response to these concerns, integrated pest management (IPM) has emerged as a comprehensive approach, emphasizing non-chemical pest control methods such as cultural practices, biological control, and crop rotation, with pesticides as the last resort. IPM has evolved, influenced by regulations like the Food Quality Protection Act (FQPA), which prioritizes human health protection, especially for children. The development of systemic pesticides, particularly neonicotinoids, introduced a more efficient and targeted pest control method within the IPM framework. However, they have also raised concerns due to their potential adverse effects on pollinators. In recent years, integrated pest and pollinator management (IPPM) has emerged as an enhanced approach, integrating pollinator health considerations into pest management strategies. In this article, we discuss this new approach, and briefly present an example of a modifying pesticide program in Pennsylvania apple orchards to illustrate the application of IPPM, in order to highlight the importance of IPPM in sustaining agriculture, protecting vital pollinators, and maintaining effective pest control practices. © 2024 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf92f02e-b881-4646-8c7d-61ce9d712ecc', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Residues of Pesticides and Heavy Metals in Polish Varietal Honey', 'Kędzierska-Matysek M, Teter A, Skałecki P, Topyła B, Domaradzki P, Poleszak E, Florek M', 2022, 'Foods (Basel, Switzerland)', '10.3390/foods11152362', 'https://doi.org/10.3390/foods11152362', 'https://europepmc.org/articles/PMC9368611?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The levels of chemical pollutants were determined in 30 samples of varietal honey from southeastern Poland, including 223 pesticides (insecticides, herbicides, fungicides, acaricides, plant growth regulators, and veterinary drugs) and 5 heavy metals (Pb, Cd, Hg, Cu, and Zn). In 10% of the samples, no pesticide residues were found. The most frequently identified pesticides were thiacloprid (90% of the samples, max 0.337 mg/kg), acetamiprid (86.6%, max 0.061 mg/kg), carbendazim (60%, max 0.049 mg/kg), DMF (56.6%, max 0.038 mg/kg), total amitraz (53.3%, max 0.075 mg/kg), thiamethoxam (26.6%, max 0.004 mg/kg), thiacloprid-amide (13.3%, max 0.012 mg/kg), dimethoate (10%, max 0.003 mg/kg), azoxystrobin (10%, max 0.002 mg/kg), tebuconazole (6.66%, max 0.002 mg/kg), and boscalid (3.33%, max 0.001 mg/kg). The acceptable limits for the compounds were not exceeded in any sample. The Pb content ranged between 0.044 and 0.081 mg/kg. The concentration of Hg and Cd did not exceed 5.0 µg/kg and 0.02 mg/kg, respectively. The honey variety significantly (p 0.05) was observed for the Zn content, which ranged from 0.657 mg/kg (linden) to 2.694 mg/kg (buckwheat). Honey produced in southeastern Poland was shown to be safe for human consumption.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf20c189-1107-4d42-bd46-28a2d2e79864', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Resistance selection of triflumezopyrim in Laodelphax striatellus (fallén): Resistance risk, cross-resistance and metabolic mechanism', 'Shengfang Wen, Shengfang Wen, Chang Liu, Xueting Wang, Youwei Wang, Chao Liu, Jinhua Wang, Xiaoming Xia', 2022, 'Frontiers in Physiology', '10.3389/fphys.2022.1048208', 'https://doi.org/10.3389/fphys.2022.1048208', 'https://www.frontiersin.org/articles/10.3389/fphys.2022.1048208/full', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'The risk assessment and resistance mechanisms of insecticide resistance are critical for resistance management strategy before a new insecticide is widely used. Triflumezopyrim (TFM) is the first commercialized mesoionic insecticide, which can inhibit nicotinic acetylcholine receptor with high-performance against the small brown planthopper (SBPH), Laodelphax striatellus (Fallén). In our study, the resistance of SBPH to TFM increased 26.29-fold, and the actual heritability of resistance was 0.09 after 21 generations of continuous selection by TFM. After five generations of constant feeding under insecticide-free conditions from F16 generation, the resistance level decreased 2.05-fold, and the average resistance decline rate per generation was 0.01, but there were no statistical decline. The TFM resistant strains had no cross-resistance to imidacloprid, nitenpyram, thiamethoxam, dinotefuran, flonicamid, pymetrozine, and chlorfenapyr. The third and fifth nymphal stage duration, pre-adult stage, adult preoviposition period, longevity, emergence rate, and hatchability of the resistant strain were significantly lower than those of the susceptible strain, while the female-male ratio was considerably increased. The fitness cost was 0.89. Further, cytochrome P450 monooxygenase (P450) and carboxylesterase (CarE) activities were markedly increased, but only the enzyme inhibitor piperonyl butoxide (PBO) had a significant synergistic effect on the resistant strain. The expression of CYP303A1, CYP4CE2, and CYP419A1v2 of P450 genes was significantly increased. SBPH has a certain risk of resistance to TFM with continuous application. The TFM resistance may be due to the increased activity of P450 enzyme regulated by the overexpression of P450 genes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('624ce876-69ca-434a-905e-fdf778c5e025', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Spirotetramat resistance in Myzus persicae (Sulzer) (Hemiptera: Aphididae) and its association with the presence of the A2666V mutation', 'Umina PA, Bass C, van Rooyen A, Chirgwin E, Arthur AL, Pym A, Mackisack J, Mathews A', 2022, 'Pest management science', '10.1002/ps.7103', 'https://doi.org/10.1002/ps.7103', 'https://europepmc.org/articles/PMC9804573?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'BackgroundChemicals are widely used to protect field crops against aphid pests and aphid-borne viral diseases. One such species is Myzus persicae (Sulzer), a global pest that attacks a broad array of agricultural crops and transmits many economically damaging plant viruses. This species has evolved resistance to a large number of insecticide compounds as a result of widespread and repeated chemical use in many parts of the world. In this study, we investigated the evolution of resistance to a new plant protection product, spirotetramat, following reported chemical control failures.ResultsOur study provides clear phenotypic and genotypic evidence of spirotetramat resistance in populations of M. persicae from Australia. We show there is cross-resistance to other insecticides within the same chemical group, namely spiromesifen and spirodiclofen. We also demonstrate that resistance is associated with the previously reported mutation, A2226V in the target site of spirotetramat, acetyl-CoA carboxylase. Our genetic analysis found all resistant M. persicae populations belong to the same multi-locus clonal type and carry the A2226V mutation, which appears to be inherited as a dominant trait in this species.ConclusionOur findings provide new insight into the resistance conferred by A2226V and have implications for the control of M. persicae in Australia and worldwide. A diagnostic assay developed in this study should serve as a valuable tool for future resistance monitoring and to support the implementation of pest management strategies. © 2022 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7403f4bc-2649-4ee7-9ff5-4b46bc1cbe90', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Advancements in Plasma Agriculture: A Review of Recent Studies', 'Konchekov EM, Gusein-Zade N, Burmistrov DE, Kolik LV, Dorokhov AS, Izmailov AY, Shokri B, Gudkov SV', 2023, 'International journal of molecular sciences', '10.3390/ijms242015093', 'https://doi.org/10.3390/ijms242015093', 'https://europepmc.org/articles/PMC10606361?pdf=render', NULL, NULL, 38, NULL, 'other', 1, 'cc by', 'This review is devoted to a topic of high interest in recent times-the use of plasma technologies in agriculture. The increased attention to these studies is primarily due to the demand for the intensification of food production and, at the same time, the request to reduce the use of pesticides. We analyzed publications, focusing on research conducted in the last 3 years, to identify the main achievements of plasma agrotechnologies and key obstacles to their widespread implementation in practice. We considered the main types of plasma sources used in this area, their advantages and limitations, which determine the areas of application. We also considered the use of plasma-activated liquids and the efficiency of their production by various types of plasma sources.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0812005c-8631-4f4d-95bb-0e60612d3c84', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'The power of Drosophila genetics in studying insect toxicology and chemical ecology', 'Huang J, Lee Y', 2023, 'Crop health', '10.1007/s44297-023-00012-x', 'https://doi.org/10.1007/s44297-023-00012-x', 'https://europepmc.org/articles/PMC12825945?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Insect toxicology and chemical ecology are inherently interconnected disciplines, both dedicated to unraveling the intricate relationships between insects and the diverse array of chemical compounds that pervade their surroundings. Drosophila melanogaster, owing to its genetic and physiological similarities to other insects, serves as a robust model system in the study of insect toxicology. Moreover, state-of-the-art techniques in Drosophila neurobiology have extensively probed the chemosensory system of insects, providing significant insights into their adaptation to chemical environments. In this review, we emphasize the advancements achieved through the application of Drosophila genetics in investigations spanning both of these fields, significantly enhancing our understanding of the mode of action and resistance mechanisms of insecticides, as well as unraveling the molecular and cellular mechanisms underlying insect chemosensation and associated behaviors. The profound insights derived through this tiny fly not only enrich our understanding of the broader world of insects but also hold the potential to develop more effective and sustainable strategies for pest management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('68f06162-75d3-4775-8c37-4851affaac03', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Toxicity, baseline of susceptibility, detoxifying mechanism and sublethal effects of chlorogenic acid, a potential botanical insecticide, on Bemisia tabaci', 'Wang R, Zhang Q, Qu C, Wang Q, Wang J, Luo C', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1150853', 'https://doi.org/10.3389/fpls.2023.1150853', 'https://europepmc.org/articles/PMC9992418?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Bemisia tabaci is a threat to agriculture worldwide because of its potential to cause devastating damage to crops. Chlorogenic acid is a bioactive pesticidal phytochemical agent against various insect pests. We here determined the susceptibility of a laboratory strain of B. tabaci to chlorogenic acid and other popular insecticides, and the susceptibility of several field-collected populations to chlorogenic acid. Also, cross-resistance to four common insecticides was measured. Chlorogenic acid had the highest toxicity of all tested insecticides, and all the field-collected populations were susceptible to chlorogenic acid, and little cross-resistance was detected between chlorogenic acid and the other tested insecticides. Furthermore, analysis of enzyme activities and expression of P450 genes in B. tabaci after treatment with LC50 of chlorogenic acid suggested that enhanced P450 activity could be involved in chlorogenic acid detoxification. We subsequently evaluated sublethal effects of chlorogenic acid, and found that treatment with LC25 of chlorogenic acid prolonged duration of two developmental stages, reduced fecundity, and decreased survival rates of treated B. tabaci compared to untreated insects. Overall, these findings demonstrate strong toxicity and significant sublethal effects of chlorogenic acid on B. tabaci, and suggest that overexpression of P450 genes may be associated with chlorogenic acid detoxification.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d79283b5-b1d4-4a68-8c20-caccead6f340', '8a171ed6-0d50-4efe-92f7-6e11322162d8', 'Virus Diseases of Cereal and Oilseed Crops in Australia: Current Position and Future Challenges', 'Jones RAC, Sharman M, Trębicki P, Maina S, Congdon BS', 2021, 'Viruses', '10.3390/v13102051', 'https://doi.org/10.3390/v13102051', 'https://europepmc.org/articles/PMC8539440?pdf=render', NULL, NULL, 68, NULL, 'other', 1, 'cc by', 'This review summarizes research on virus diseases of cereals and oilseeds in Australia since the 1950s. All viruses known to infect the diverse range of cereal and oilseed crops grown in the continent''s temperate, Mediterranean, subtropical and tropical cropping regions are included. Viruses that occur commonly and have potential to cause the greatest seed yield and quality losses are described in detail, focusing on their biology, epidemiology and management. These are: barley yellow dwarf virus, cereal yellow dwarf virus and wheat streak mosaic virus in wheat, barley, oats, triticale and rye; Johnsongrass mosaic virus in sorghum, maize, sweet corn and pearl millet; turnip yellows virus and turnip mosaic virus in canola and Indian mustard; tobacco streak virus in sunflower; and cotton bunchy top virus in cotton. The currently less important viruses covered number nine infecting nine cereal crops and 14 infecting eight oilseed crops (none recorded for rice or linseed). Brief background information on the scope of the Australian cereal and oilseed industries, virus epidemiology and management and yield loss quantification is provided. Major future threats to managing virus diseases effectively include damaging viruses and virus vector species spreading from elsewhere, the increasing spectrum of insecticide resistance in insect and mite vectors, resistance-breaking virus strains, changes in epidemiology, virus and vectors impacts arising from climate instability and extreme weather events, and insufficient industry awareness of virus diseases. The pressing need for more resources to focus on addressing these threats is emphasized and recommendations over future research priorities provided.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5f0e6396-fe40-4508-b216-d74b4a999d32', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'A novel approach to control Botrytis cinerea fungal infections: uptake and biological activity of antifungals encapsulated in nanoparticle based vectors', 'De Angelis G, Simonetti G, Chronopoulou L, Orekhova A, Badiali C, Petruccelli V, Portoghesi F, D''Angeli S', 2022, 'Scientific reports', '10.1038/s41598-022-11533-w', 'https://doi.org/10.1038/s41598-022-11533-w', 'https://europepmc.org/articles/PMC9107473?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Botrytis cinerea, responsible for grey mold diseases, is a pathogen with a broad host range, affecting many important agricultural crops, in pre and post harvesting of fruits and vegetables. Commercial fungicides used to control this pathogen are often subjected to photolysis, volatilization, degradation, leaching, and runoff during application. In this context, the use of a delivery system, based on poly (lactic-co-glycolic acid) nanoparticles (PLGA NPs) represents an innovative approach to develop new pesticide formulations to successfully fight B. cinerea infections. In order to study NPs uptake, B. cinerea conidia and mycelium were treated with PLGA NPs loaded with the high fluorescent probe coumarin 6 (Cu6-PLGA NPs) and analyzed under ApoTome fluorescence microscopy. The observations revealed that 50 nm Cu6-PLGA NPs penetrated into B. cinerea conidia and hyphae, as early as 10 min after administration. Pterostilbene, a natural compound, and fluopyram, a synthetic antifungal, were entrapped in PLGA NPs, added to B. cinerea conidia and mycelium, and their antifungal activity was tested. The results revealed that the compounds loaded in NPs exhibited a higher activity against B. cinerea. These results lay the foundations for the use of PLGA NPs as a new strategy in plant pest management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('818a3dbf-2644-4fcf-8f88-1ce81cc972bd', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Endophytes in Cannabis sativa: Identifying and Characterizing Microbes with Beneficial and Detrimental Effects on Plant Health', 'Buirs L, Punja ZK', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14081247', 'https://doi.org/10.3390/plants14081247', 'https://europepmc.org/articles/PMC12030312?pdf=render', NULL, NULL, 39, NULL, 'canada', 3, 'cc by', 'The roles of endophytes in Cannabis sativa (cannabis, hemp) remain poorly explored. While in vitro studies suggest that there can be several benefits, such as plant growth promotion and protection against pathogens, more in planta studies are needed. This review summarizes the bacterial and fungal endophytes previously reported in tissues of C. sativa and discusses the factors influencing their presence, as well as their potential beneficial and detrimental effects. Using genome sequencing and culture-based approaches, we describe the microbial diversity in hydroponically cultivated cannabis plants at several developmental stages. These include mother plants, cuttings, vegetative and flowering plants, and tissue-cultured plantlets. Microbes that were present include fungal, yeast, and bacterial endophytes found in roots, stems, leaves, inflorescences, and seeds. These may have originated from the growing substrate or be transmitted through vegetative propagation. Notable endophytes included Rhizophagus irregularis (a mycorrhizal fungus), Penicillium chrysogenum (an antibiotic producer), and various endophytic yeast species not previously described in C. sativa. Endophytes representing potential plant pathogens, such as Fusarium oxysporum, are also present within cannabis tissues, which can negatively impact plant health. Using scanning electron microscopy, we observed that fungal propagules are present within pith parenchyma cells and xylem vessel elements in stem tissues, illustrating for the first time the in situ localization and distribution of endophytes in cannabis vascular tissues. The mechanism of spread through xylem vessels likely contributes to the spread of endophytes within cannabis and hemp plants. Further research is required to validate the roles of endophytes in cannabis and hemp plants grown under commercial production conditions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4975ffcb-01f1-4c85-9205-72411c9167f9', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Evaluation of the mechanism of action of Bacillus spp. to manage Meloidogyne incognita with split root assay, RT-qPCR and qPCR', 'Kaitlin M. Gattoni, Sang Wook Park, Kathy S. Lawrence', 2023, 'Frontiers in Plant Science', '10.3389/fpls.2022.1079109', 'https://doi.org/10.3389/fpls.2022.1079109', 'https://www.frontiersin.org/articles/10.3389/fpls.2022.1079109/full', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'The goal of this research is to determine the mechanism of action of two Bacillus spp. that can manage Meloidogyne incognita population density in cotton. The overall objectives are 1) determine the efficacy and direct antagonistic capabilities of the Bacillus spp. and 2) determine the systemic capabilities of the Bacillus spp. The greenhouse in planta assay indicated B. amyloliquefaciens QST713 and B. firmus I-1582 could manage M. incognita similarly to the chemical standard fluopyram. An in vitro assay determined that B. firmus I-1582 and its extracted metabolites were able to directly manage M. incognita second stage juveniles by increasing mortality rate above 75%. A split root assay, used to determine systemic capabilities of the bacteria, indicated B. amyloliquefaciens QST713 and B. firmus I-1582 could indirectly decrease the nematode population density. Another species, B. mojavensis strain 2, also demonstrated systemic capabilities but was not a successful biological control agent because it supported a high population density in greenhouse in planta assay and in the split root assay. A RT-qPCR assay was used to confirm any systemic activity observed in the split root assay. At 24 hours both B. amyloliquefaciens QST713 and B. firmus I-1582 upregulated one gene involved in the initial stages of JA synthesis pathway but not another gene involved in the later stages of JA synthesis. These results point to a JA intermediate molecule, most likely OPDA, stimulated by the bacteria rather than JA in a short-term systemic response. After 1 week, the Bacillus spp. stimulated a SA-responsive defense related gene. The long-term systemic response to the Bacillus spp. indicates salicylic acid also plays a role in defense conferred by these bacteria. The final assay was a qPCR to determine the concentration of the bacteria on the cotton roots after 24 days. Bacillus amyloliquefaciens QST713 and B. firmus I-43 1582 were able to colonize the root successfully, with the concentration after 24 days not significantly differing from the concentration at inoculation. This study identifies two bacteria that work via systemic resistance and will help aid in implementing these species in an integrated management system.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ac707e7-bc32-46f0-87c9-d6def5013d34', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Fluopyram activates systemic resistance in soybean', 'Leonardo F. Rocha, Arjun Subedi, Mirian F. Pimentel, Jason P. Bond, Ahmad M. Fakhoury', 2022, 'Frontiers in Plant Science', '10.3389/fpls.2022.1020167', 'https://doi.org/10.3389/fpls.2022.1020167', 'https://www.frontiersin.org/articles/10.3389/fpls.2022.1020167/full', NULL, NULL, 15, NULL, 'other', 1, 'open access (DOAJ)', 'The soybean cyst nematode (SCN) (Heterodera glycines Ichinohe) is a significant yield-limiting factor in soybean production in the Midwestern US. Several management practices are implemented to mitigate yield losses caused by SCN, including using SDHI (succinate dehydrogenase inhibitors) fungicides delivered as seed treatments. A set of studies was conducted to evaluate the effect of two seed-applied succinate dehydrogenase inhibitors (SDHI) compounds, fluopyram and pydiflumetofen, on SCN population densities, plant injury, and plant growth. Cyst counts in untreated control and pydiflumetofen treated plants were 3.44 and 3.59 times higher than fluopyram, respectively, while egg counts were 8.25 and 7.06 times higher in control and pydiflumetofen. Next-generation sequencing was later employed to identify transcriptomic shifts in gene expression profiles in fluopyram and pydiflumetofen -treated seedlings. RNA expression patterns of seed treatments clustered by sampling time (5 DAP vs. 10 DAP); therefore, downstream analysis was conducted by timepoint. At 5 DAP, 10,870 and 325 differentially expressed genes (DEG) were identified in fluopyram and pydiflumetofen, respectively. These same treatments generated 219 and 2 DEGs at 10 DAP. Multiple DEGs identified in soybean seedlings treated with fluopyram are linked to systemic resistance, suggesting a potential role of systemic resistance in the suppression of SCN by fluopyram, in addition to the known nematicidal activity. The non-target inhibition of soybean succinate dehydrogenase genes by fluopyram may be the origin of the phytotoxicity symptoms observed and potentially the source of the systemic resistance activation reported in the current study. This work helps to elucidate the mechanisms of suppression of SCN by fluopyram.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e859176-a645-4ad7-b0bc-3249894f7fc9', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Fluopyram in agricultural ecosystems: environmental fate, microbial transformation, ecotoxicity, and resistance risks of an SDHI fungicide', 'Chaoqun Zhang, Muhammad Zafar Ullah, Chengwei Guan, Mustansar Mubeen, Yongliang Ding, Yasir Iftikhar, Yasir Iftikhar, Wenmei Zhang', 2026, 'Frontiers in Microbiology', '10.3389/fmicb.2026.1890957', 'https://doi.org/10.3389/fmicb.2026.1890957', 'https://www.frontiersin.org/articles/10.3389/fmicb.2026.1890957/full', NULL, NULL, 18, NULL, 'other', 1, 'open access (DOAJ)', 'Fluopyram is a next-generation succinate dehydrogenase inhibitor (SDHI) fungicide, which is very popular in the management of economically significant fungal conditions in cereals, fruits, vegetables, and ornamental crops. It works by inhibiting the complex II present in the mitochondria by blocking succinate dehydrogenase, which electron transport and energy generation, eventually hindering fungal development leading to death of the pathogen. Besides having good fungicidal effects, fluopyram has also demonstrated a nematicidal effect, which has also enhanced its utility in various agricultural systems. Empirical studies indicate that SDHIs can induce mortality, mitochondrial dysfunction, oxidative stress, and developmental delays in non-target organisms. Additionally, the environmental persistence of these compounds raises concerns about their potential for ecological disruption. The extensive and growing use of SDHIs however has also given rise to the issue of resistance development with recorded resistance cases in a number of fungal populations and has placed a strong demand on the need to use crop rotation strategies, combination formulations and resistance monitoring initiatives. In addition to its agronomic advantages, the environmental fate of fluopyram such as its mobility, persistence and degradation characteristics in soil and water and the possibility of food system residues have been the subject of attention. Unlike previous studies focusing on isolated aspects, this review comprehensively links efficacy, environmental dynamics, and mechanistic toxicity of fluopyram across multiple biological systems. It highlights underexplored areas including metabolite toxicity, chronic ecological exposure, and resistance risks. This integrated approach offers valuable insights for safer pesticide management and future research directions.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('57d84c52-c676-4043-8db7-f9215ea641ad', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Fluopyram or Resistant Cultivars Manage Meloidogyne arenaria Infestation in Virginia-Type Peanut Production', 'Grabau Zane J., Budhathoki Sabina, Ruiz Rebeca Sandoval, Liu Chang', 2025, 'Journal of Nematology', '10.2478/jofnem-2025-0010', 'https://doi.org/10.2478/jofnem-2025-0010', 'https://doi.org/10.2478/jofnem-2025-0010', NULL, NULL, 15, NULL, 'other', 1, 'open access (DOAJ)', 'Meloidogyne arenaria (peanut root-knot nematode, PRKN) is an important pest in peanut (Arachis hypogea) production in the United States, including specialty Virginia-type peanuts. Cultivars resistant to PRKN and nematicide application are two available methods for managing PRKN. The objectives of this study were to determine the impacts of resistant Virginia-type peanut cultivars (Georgia-19HP and TifJumbo) on (1) management of PRKN abundances and damage and (2) total free-living nematode soil abundances. A common susceptible cultivar (Bailey II) with or without in-furrow fluopyram nematicide was compared to the resistant cultivars without nematicide in field trials in Florida (2022 and 2023). Resistant cultivars reduced midseason PRKN abundances from roots by 92–98% and final PRKN soil abundances by 81–93% relative to the untreated susceptible cultivar. Fluopyram reduced midseason PRKN root abundances by 65–74% and final PRKN soil abundances by 42–51% relative to untreated susceptible. Although PRKN reproduced on peanuts, no damage symptoms were observed, yield did not vary by treatment in 2022, and yield was significantly greater for fluopyram than either resistant cultivar in 2023. Impacts on total free-living nematode soil abundances were inconsistent. In summary, either fluopyram or resistant cultivars are effective tools for managing PRKN abundances in Virginia-type peanuts.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cd9844eb-b368-4114-ac97-cb562b18a08a', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Fungal Grapevine Trunk Diseases in Romanian Vineyards in the Context of the International Situation', 'Muntean MD, Drăgulinescu AM, Tomoiagă LL, Comșa M, Răcoare HS, Sîrbu AD, Chedea VS', 2022, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens11091006', 'https://doi.org/10.3390/pathogens11091006', 'https://europepmc.org/articles/PMC9503734?pdf=render', NULL, NULL, 43, NULL, 'other', 1, 'cc by', 'Vitis vinifera, known as the common grape vine, represents one of the most important fruit crops in the world. Romania is a wine-producing country with a rich and long tradition in viticulture. In the last decade, increasing reports of damage caused by grapevine trunk diseases (GTDs) have raised concerns in all wine producing countries. Up to now, no study was performed regarding the GTDs situation in Romania, an important grapevine grower in Europe. In this study, we aim, after a comprehensive presentation of the fungal GTDs worldwide, to review the scientific information related to these diseases in Romania in order to open a national platform in an international framework. In order to achieve this, we consulted over 500 references from different scientific databases and cited 309 of them. Our review concludes that, in Romania, there is little amount of available literature on this matter. Three out of six fungal GTDs are reported and well documented in all of the Romanian viticultural zones (except for viticultural zone 4). These are Eutypa dieback, Phomopsis dieback, and Esca disease. Of the fungal pathogens considered responsible Eutypa lata, Phomopsis viticola and Stereum hirsutum are the most studied and well documented in Romania. Management measures are quite limited, and they mostly include preventive measures to stop the GTDs spread and the removal of affected grapevines.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('600df1cc-037b-4bc2-a9c9-6bac9b2615b6', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Meloidogyne incognita management by nematicides in tomato production', 'Grabau ZJ, Liu C, Sandoval-Ruiz R', 2021, 'Journal of nematology', '10.21307/jofnem-2021-055', 'https://doi.org/10.21307/jofnem-2021-055', 'https://europepmc.org/articles/PMC8290502?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Meloidogyne incognita (southern root-knot nematode, SRKN) is a major pest in tomato (Solanum lycopersicum) production in the Southeastern United States. Management has relied on fumigant and carbamate non-fumigant nematicides. New non-fumigant nematicides, such as fluopyram, are available and field evaluation of new nematicides is needed. The objectives of this research were to assess the efficacy of new (fluopyram) and established (oxamyl) non-fumigant nematicides as well as fumigation (1,3-dichloropropene) for (1) SRKN management, and (2) impacts on total soil abundances of non-target, free-living nematodes in field tests in Florida. Fumigation with 1,3-D consistently managed SRKN and, in two of three trials, increased yield relative to untreated. Oxamyl and fluopyram also had efficacy in managing SRKN, but were inconsistent from year to year. Oxamyl provided better root galling control than fluopyram in one of two trials, but otherwise those nematicides provided similar SRKN management and yield response. Supplementing 1,3-D fumigation with fluopyram did not improve SRKN management or yield relative to fumigation alone. Fumigation consistently reduced free-living nematode abundances relative to untreated. Oxamyl and fluopyram were more inconsistent, but always reduced total free-living nematode abundances when effective against SRKN. In summary, while non-fumigant nematicides provided some management of SRKN, fumigation continued to be the most consistent option. All nematicides had deleterious effects on free-living nematodes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a7fd5472-f79c-400a-89be-810b28ac2673', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Phytochemical Volatiles as Potential Bionematicides with Safer Ecotoxicological Properties', 'Cavaco T, Faria JMS', 2024, 'Toxics', '10.3390/toxics12060406', 'https://doi.org/10.3390/toxics12060406', 'https://europepmc.org/articles/PMC11209200?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The management of plant-parasitic nematodes (PPNs) still relies on traditional nematicides that threaten the environment and human health. Novel solutions are urgently needed for PPN pest management that are effective while safeguarding non-target organisms. Volatile phytochemicals belong to a structurally diverse group of bioactive metabolites that are believed to hold safer environmental characteristics than synthetic pesticides. Nonetheless, not many studies have analysed the potential environmental benefits of shifting to these novel bionematicides. In the present study, 20 phytochemical volatiles with reported nematicidal activity were compared to traditional pesticides using specific parameters of environmental and human health safety available on applied online databases and predicted in silico through specialised software. Overall, the reviewed nematicidal phytochemicals were reportedly less toxic than synthetic nematicides. They were predicted to disperse to the air and soil environmental compartments and were reported to have a lower toxicity on aquatic organisms. On the contrary, the synthetic nematicides were reportedly toxic to aquatic organisms while showing a predicted high affinity to the water environmental compartment. As alternatives, β-keto or fatty acid derivatives, e.g., aliphatic alcohols or ketones, showed more adequate properties. This study highlights the importance of complementing studies on nematicidal activity with a risk assessment-based analysis to allow for a faster selection of nematicidal phytochemical volatiles and to leverage the development and implementation of bionematicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('769a899d-a2b2-4514-b001-bdb5484b4508', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Mode of action of fluopyram in plant-parasitic nematodes', 'Schleker ASS, Rist M, Matera C, Damijonaitis A, Collienne U, Matsuoka K, Habash SS, Twelker K', 2022, 'Scientific reports', '10.1038/s41598-022-15782-7', 'https://doi.org/10.1038/s41598-022-15782-7', 'https://europepmc.org/articles/PMC9279378?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Plant-parasitic nematodes (PPN) are responsible for severe yield losses in crop production. Management is challenging as effective and safe means are rare. Recently, it has been discovered that the succinate dehydrogenase (SDH) inhibitor fluopyram is highly effective against PPN while accompanying an excellent safety profile. Here we show that fluopyram is a potent inhibitor of SDH in nematodes but not in mammals, insects and earthworm, explaining the selectivity on molecular level. As a consequence of SDH inhibition, fluopyram impairs ATP generation and causes paralysis in PPN and Caenorhabditis elegans. Interestingly, efficacy differences of fluopyram amongst PPN species can be observed. Permanent exposure to micromolar to nanomolar amounts of fluopyram prevents Meloidogyne spp. and Heterodera schachtii infection and their development at the root. Preincubation of Meloidogyne incognita J2 with fluopyram followed by a recovery period effectively reduces gall formation. However, the same procedure does not inhibit H. schachtii infection and development. Sequence comparison of sites relevant for ligand binding identified amino acid differences in SDHC which likely mediate selectivity, coincidently revealing a unique amino acid difference within SDHC conserved among Heterodera spp. Docking and C. elegans mutant studies suggest that this minute difference mediates altered sensitivity of H. schachtii towards fluopyram.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('253419b2-d4e6-41e7-a50a-a17f7a3b28f4', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Modification of the existing maximum residue levels and setting of import tolerances for fluopyram in various crops', 'Bellisai G, Bernasconi G, Brancato A, Carrasco Cabrera L, Castellan I, Del Aguila M, Ferreira L, Santonja GG', 2023, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2023.8036', 'https://doi.org/10.2903/j.efsa.2023.8036', 'https://europepmc.org/articles/PMC10240403?pdf=render', NULL, NULL, 58, NULL, 'other', 1, 'cc by-nd', 'In accordance with Article 6 of Regulation (EC) No 396/2005, the applicant Bayer AG Crop Science Division submitted a request to the competent national authority in Italy to modify the existing maximum residue level (MRL) for the active substance fluopyram in kiwi. Additionally, the applicants Bayer Crop Science SA and Bayer SAS Crop Science Division submitted two applications to the competent national authority in Germany to modify the MRLs for fluopyram in certain stem vegetables, seed spices, apples and soyabeans based on intended EU uses as well as to lower the existing EU MRL in pome fruits and to raise the existing EU MRL in peanuts on the basis of authorised use of fluopyram in the USA. The data submitted in support of the request were found to be sufficient to derive MRL proposals for all the crops under assessment except for palm hearts and bamboo shoots. Adequate analytical methods for enforcement are available to control the residues of fluopyram in commodities under consideration at the validated limit of quantification (LOQ) of 0.01 mg/kg. Based on the risk assessment results, EFSA concluded that the short-term intake of residues resulting from the use of fluopyram according to the reported agricultural practices is unlikely to present a risk to consumer health. A long-term consumer intake concern is identified if the current MRL of 0.8 mg/kg in pome fruits is maintained and new MRLs for other commodities under consideration are supported, with apples being the highest contributing commodity to the diet for which exposure exceedances were noted. The chronic risk for consumers is unlikely if a lower MRL of 0.6 mg/kg in pome fruits proposed by the applicant is considered. Further risk manager considerations are required.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87f0286f-2367-4f3a-9415-62bf0bc31ef7', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Nematocidal Potential of Phenolic Acids: A Phytochemical Seed-Coating Approach to Soybean Cyst Nematode Management', 'Yates P, Janiol J, Li C, Song BH', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13020319', 'https://doi.org/10.3390/plants13020319', 'https://europepmc.org/articles/PMC10819391?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Soybeans, one of the most valuable crops worldwide, are annually decimated by the soybean cyst nematode (SCN), Heterodera glycines, resulting in massive losses in soybean yields and economic revenue. Conventional agricultural pesticides are generally effective in the short term; however, they pose growing threats to human and environmental health; therefore, alternative SCN management strategies are urgently needed. Preliminary findings show that phenolic acids are significantly induced during SCN infection and exhibit effective nematocidal activities in vitro. However, it is unclear whether these effects occur in planta or elicit any negative effects on plant growth traits. Here, we employed a phytochemical-based seed coating application on soybean seeds using phenolic acid derivatives (4HBD; 2,3DHBA) at variable concentrations and examined SCN inhibition against two SCN types. Moreover, we also examined plant growth traits under non-infected or SCN infected conditions. Notably, 2,3DHBA significantly inhibited SCN abundance in Race 2-infected plants with increasingly higher chemical doses. Interestingly, neither compound negatively affected soybean growth traits in control or SCN-infected plants. Our findings suggest that a phytochemical-based approach could offer an effective, more environmentally friendly solution to facilitate current SCN management strategies and fast-track the development of biopesticides to sustainably manage devastating pests such as SCN.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('905c1128-1dc8-4254-b06b-888f21e7922d', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'New reduced-risk agricultural nematicides - rationale and review', 'Desaeger J, Wram C, Zasada I', 2020, 'Journal of nematology', '10.21307/jofnem-2020-091', 'https://doi.org/10.21307/jofnem-2020-091', 'https://europepmc.org/articles/PMC8015323?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The last decade has seen a sharp increase in nematicide research in the agricultural industry. As a result, several new synthetic nematicides have become available to growers, and several more are expected in the near future. This new interest in nematicides is directly related to the growing demand for safer and more selective products, and the increasing regulatory pressure on many of the traditional nematicides. This has led to a ban of several widely used fumigant (e.g. methyl bromide) and non-fumigant (e.g. aldicarb) nematicides. The loss of traditional nematicides, combined with a lack of replacement products and awareness of the damage that nematodes can cause, has not only raised concern among growers, but has also created new opportunities for the crop protection industry. Nematicides have become a priority, and many companies are now allocating significant research dollars to discover new nematicides. The new nematicides are very different from previous products: (i) they are more selective, often only targeting nematodes, and (ii) they are less toxic, and safer to use. This review article describes these new developments by discussing the challenges that are associated with finding new nematicides, reviewing the nature, characteristics, and efficacy of new nematicides, and discussing the impact they could have on future nematode management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bc52265b-a36c-4e6c-87e0-3a5150a77c50', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Recent innovations in crop protection research', 'Maienfisch P, Koerber K', 2025, 'Pest management science', '10.1002/ps.8441', 'https://doi.org/10.1002/ps.8441', 'https://europepmc.org/articles/PMC11981984?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'As the world''s population continues to grow and demand for food increases, the agricultural industry faces the challenge of producing higher yields while ensuring the safety and quality of harvests, operators, and consumers. The emergence of resistance, pest shifts, and stricter regulatory requirements also urgently calls for further advances in crop protection and the discovery of new innovative products for sustainable crop protection. This study reviews recent highlights in innovation as presented at the 15th IUPAC International Congress of Crop Protection Chemistry held in New Delhi, in 2023. The following new products are discussed: the insecticides Indazapyroxamet, Dimpropyridaz and Fenmezoditiaz, the fungicides Mefentrifluconazole and Pyridachlomethyl, the nematicide Cyclobutrifluram, the herbicides Rimisoxafen, Dimesulfazet, and Epyrifenacil as well as the abiotic stress management product Anisiflupurin. In addition, the latest innovative research areas and discovery highlights in all areas of crop protection will be presented, including insecticidal alkyl sulfones and 1,3,4-trisubstituted pyrazoles, fungicidal picolinamides, herbicidal ketoenols, and trifluoromethylpyrazoles, as well as the latest advances in crop enhancement and green pest control research. © 2024 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('31b1ffe0-da42-4e4b-abed-b5a1fa6dd512', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Residual Dynamics of Fluopyram and Its Compound Formulations in Pinus massoniana and Their Efficacy in Preventing Pine Wilt Disease', 'Wanjun Zhang, Anshun Ni, Jiao Zhang, Guohong Sun, Fan Xiang, Hao Cheng, Tingting Chen, Jianren Ye', 2026, 'Plants', '10.3390/plants15020302', 'https://doi.org/10.3390/plants15020302', 'https://www.mdpi.com/2223-7747/15/2/302', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Injecting chemical agents into tree trunks is a key method for preventing pine wilt disease (PWD). However, the long-term use of conventional trunk injection agents such as emamectin benzoate (EB) and avermectin (AVM) may lead to nematode resistance. Therefore, it is crucial to evaluate the potential of new-generation nematicides, including fluopyram (FLU) and its compound formulations, as alternatives to EB and AVM in PWD prevention. In this study, four trunk injection agents, i.e., 5% FLU microemulsion (ME), 2% AVM + 6% FLU ME, 5% EB ME, and 5% AVM emulsifiable concentrate (EC), were injected into Pinus massoniana trunks, and their residual dynamics over time and preventive effects on PWD were compared. Results showed that all agents were transported to various parts of the trees within 90 days post-injection, with FLU showing significantly stronger translocation compared with EB and AVM. At 660 days post-injection, the active ingredient levels of 5% FLU ME in apical branches remained significantly higher than those of the other three agents at both tested doses (30 and 60 mL). Artificial inoculation with 10,000 Bursaphelenchus xylophilus nematodes per tree at 90 days post-injection showed that trees injected with 5% FLU ME and 2% AVM + 6% FLU ME had nearly 100% disease prevention rates at both doses, outperforming 5% EB ME and 5% AVM EC. A second nematode inoculation at 480 days post-injection showed that 2% AVM + 6% FLU ME showed 50% efficacy, outperforming 5% EB ME (25% efficacy). These findings offer a foundation for developing alternative trunk injection strategies for future PWD management in China.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('96652134-668a-4546-a206-e7352f4c1124', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Seed Treatments for Management of Soybean Cyst Nematode, Heterodera glycines, in Mid-Atlantic Soybean Production', 'Kessler AC, Koehler AM', 2023, 'Journal of nematology', '10.2478/jofnem-2023-0026', 'https://doi.org/10.2478/jofnem-2023-0026', 'https://europepmc.org/articles/PMC10390846?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Soybean Cyst Nematode (SCN), Heterodera glycines Ichinohe, is the most important pathogen of soybean in the Mid-Atlantic region. In recent decades, a decline in the effectiveness of genetic resistance has been observed and additional management approaches are needed. Seed treatments are of rising interest, but no local data on product response exists for the region. In 2020-2021, two experiments were conducted to observe the effects of chemical and biological seed treatment options. In one experiment, chemical seed treatments pydiflumetofen (Saltro®) and fluopyram (ILEVO®) were screened against nontreated plain seed for SCN suppression. In a second experiment, pydiflumetofen, fluopyram and four biological nematode-protectant seed treatments with a standard base insecticide and fungicide treatment were compared to nontreated plain seed and seed with only the standard base treatment to test product efficacy against SCN. Seed treatments increased the percent emergence over plain seed. Nematode reproductive factors and female counts from roots were collected, but did not statistically differ between seed treatments or plain seed. Yield differences were observed in one of the five trials, where pydiflumetofen + base seed treatment yielded the highest (p < 0.001) at 3813.1 kg/ha. Response from seed treatments varied, with no specific seed treatment consistently reducing SCN populations or increasing yield across trials. Seed treatments may have potential as an element of an integrated management approach for SCN.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c9c667e0-245a-42a6-9ff4-14e3b2a4f038', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Spatial and Temporal Aspects of Fungicide Resistance in Venturia inaequalis (Apple Scab) Populations in Northern Germany', 'Roland W. S. Weber, Rebekka Busch, Johanna Wesche', 2025, 'BioTech', '10.3390/biotech14020044', 'https://doi.org/10.3390/biotech14020044', 'https://www.mdpi.com/2673-6284/14/2/44', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Venturia inaequalis, the cause of apple scab, readily develops resistance to fungicides with specific modes of action. Knowledge of the spatial and temporal pattern of resistance development is therefore relevant to fruit producers and their consultants. In the Lower Elbe region of Northern Germany, a two-year survey based on a conidial germination test was conducted, examining fungicide resistance in 35 orchards under Integrated Pest Management (IPM), 16 orchards of susceptible cultivars as well as a further 12 orchards of scab-resistant (Vf) cultivars under organic management, and 34 abandoned or unmanaged sites. No evidence of resistance to SDHI compounds (fluopyram, fluxapyroxad) was found after >5 yr of their regular use. Resistance to anilinopyrimidines (cyprodinil, pyrimethanil) had disappeared 15 yr after its widespread occurrence. Isolates from a few IPM orchards showed a reduced sensitivity to dodine. Double resistance to the MBC compound thiophanate-methyl and the QoI trifloxystrobin was rare in V. inaequalis strains that had achieved breakage of Vf-resistance, but very common (>50%) on scab-susceptible cultivars in IPM, organic and abandoned orchards in the ‘Altes Land’ core area of the Lower Elbe region, and in IPM orchards in the periphery. We conclude that resistance to QoI and MBC fungicides is persistent even decades after their last use, and that the core area harbours a uniform population adapted to intensive crop protection, whereas isolated orchards in the periphery are colonised by discrete populations of V. inaequalis.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('47c6934c-c99b-4458-9fa2-ee81a86c3f22', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Biochemical Basis for the Time-of-Day Effect on Glufosinate Efficacy against Amaranthus palmeri', 'Takano HK, Dayan FE', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10102021', 'https://doi.org/10.3390/plants10102021', 'https://europepmc.org/articles/PMC8537983?pdf=render', NULL, NULL, 9, NULL, 'northern_plains', 3, 'cc by', 'Glufosinate, a glutamine synthetase (GS) inhibitor, often provides variable weed control depending on environmental conditions such as light, temperature and humidity at the time of application. Midday applications normally provide improved efficacy compared to applications at dawn or dusk. We investigated the biochemical basis for the time-of-day effect on glufosinate efficacy in Amaranthus palmeri. GS1/GS2 gene expression and GS1/GS2 protein abundance were assessed in different parts (young leaves, old leaves, and roots) of plants incubated in the dark compared to those in the light. The turnover of GS total activity was also evaluated overtime following glufosinate treatment at midday compared to dusk application. The results suggest that GS in A. palmeri is less expressed and less abundant in the dark compared to in the light. Midday application of glufosinate under intense light conditions following application provide full control of A. palmeri plants. Consequently, these plants are unable to recover GS activity by de novo protein synthesis. Full activity of GS is required for complete inhibition by the irreversible inhibitor glufosinate. Therefore, glufosinate applications should always be performed in the middle of the day when sunlight is intense, to prevent weed escapes from the herbicide treatment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e87ffddb-87f1-4beb-9dd5-69305ad4378d', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Synergistic Effects of Clonostachys rosea Isolates and Succinate Dehydrogenase Inhibitors Fungicides against Gray Mold on Tomato', 'Song J, Lei T, Hao X, Yuan H, Sun W, Chen S', 2022, 'Microorganisms', '10.3390/microorganisms11010020', 'https://doi.org/10.3390/microorganisms11010020', 'https://europepmc.org/articles/PMC9863555?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Gray mold caused by Botrytis cinerea is a devastating disease in tomatoes. Site-specific fungicide application is still key to disease management; however, chemical control has many drawbacks. Here, the combined application of a biological agent, Clonostachys rosea, with newly developed succinate dehydrogenase inhibitors (SDHI) fungicides showed stronger synergistic effects than the application of SDHI fungicides alone on tomato gray mold control. C. rosea 67-1 has been reported as an efficient biological control agent (BCA) for B. cinerea. Little information is currently available about the combination of C. rosea and fungicides in the control of gray mold. By testing the sensitivity to fungicides with different action mechanisms, C. rosea isolates showed high tolerance to SDHI fungicides (1000 μg mL-1) on PDA, and the conidial germination rate was almost not affected under 120 μg mL-1 of fluxapyroxad and fluopyram. In greenhouse experiments, the control effect of the combination of C. rosea and fluxapyroxad or fluopyram against tomato gray mold was significantly increased than the application of BCA or SDHI fungicides alone, and the combination allows a two-fold reduction of both the fungicide and BCA dose. Further, the biomass of B. cinerea and C. rosea on tomato plants was determined by qPCR. For B. cinerea, the trend of detection level for different treatments was consistent with that of the pot experiments, and the lowest biomass of B. cinerea was found when treated with C. rosea combined with fluxapyroxad and fluopyram, respectively. For C. rosea, qPCR assay confirmed its colonization on tomato plants when mixed with fluopyram and fluxapyroxad. These results indicated that combining C. rosea 67-1 with the SDHI fungicides could synergistically increase control efficacy against tomato gray mold.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2639d3c7-38d1-44cf-91c2-6c5a3d331366', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'The Genus Pratylenchus (Nematoda: Pratylenchidae) in Israel: From Taxonomy to Control Practices', 'Bucki P, Qing X, Castillo P, Gamliel A, Dobrinin S, Alon T, Braun Miyara S', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9111475', 'https://doi.org/10.3390/plants9111475', 'https://europepmc.org/articles/PMC7716202?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Due to Israel''s successful agricultural production and diverse climatic conditions, plant-parasitic nematodes are flourishing. The occurrence of new, previously unidentified species in Israel or of suggested new species worldwide is a consequence of the continuous withdrawal of efficient nematicides. Among plant-parasitic nematodes, migratory endoparasitic species of the genus Pratylenchus are widely distributed in vegetable and crop fields in Israel and are associated with major reductions in quality and yield. This review focuses on the occurrence, distribution, diagnosis, pathogenicity, and phylogeny of all Pratylenchus species recorded over the last few decades on different crops grown throughout Israel-covering early information from nematologists to recent reports involving the use of molecular phylogenetic methodologies. We explore the accepted distinction between Pratylenchus thornei and Pratylenchus mediterraneus isolated from Israel''s northern Negev region, and address the confusion concerning the findings related to these Pratylenchus species. Our recent sampling from the northern Negev revealed the occurrence of both P. thornei and P. mediterraneus on the basis of molecular identification, indicating P. mediterraneus as a sister species of P. thornei and their potential occurrence in a mixed infection. Finally, the efficiencies of common control measures taken to reduce Pratylenchus'' devastating damage in protected crops and field crops is discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('51e1448e-7958-4dba-b145-c8bd8b64584d', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'The New Nematicide Cyclobutrifluram Targets the Mitochondrial Succinate Dehydrogenase Complex in Caenorhabditis elegans', 'Heydari F, Rodriguez-Crespo D, Wicky C', 2023, 'Journal of developmental biology', '10.3390/jdb11040039', 'https://doi.org/10.3390/jdb11040039', 'https://europepmc.org/articles/PMC10594496?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Today, agriculture around the world is challenged by parasitic nematode infections. Plant-parasitic nematodes (PPNs) can cause significant damage and crop loss and are a threat to food security. For a long time, the management of PPN infection has relied on nematicides that impact not only parasitic nematodes but also other organisms. More recently, new nematicides have been developed that appear to specifically target PPN. Cyclobutrifluram belongs to this new category of nematicides. Using the nematode Caenorhabditis elegans as a model organism, we show here that cyclobutrifluram strongly impacts the survival and fertility rates of the worm by decreasing the number of germ cells. Furthermore, using a genetic approach, we demonstrate that cyclobutrifluram functions by inhibiting the mitochondrial succinate dehydrogenase (SDH) complex. Transcriptomic analysis revealed a strong response to cyclobutrifluram exposure. Among the deregulated genes, we found genes coding for detoxifying proteins, such as cytochrome P450s and UDP-glucuronosyl transferases (UGTs). Overall, our study contributes to the understanding of the molecular mode of action of cyclobutrifluram, to the finding of new approaches against nematicide resistance, and to the discovery of novel nematicides. Furthermore, this study confirms that C. elegans is a suitable model organism to study the mode of action of nematicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('85c2363f-a961-4c41-b92e-a2d7c16f0d0c', 'a9f1bfe4-848b-4941-a571-50fbae8037bf', 'Transcriptomic and functional analyses on a Botrytis cinerea multidrug-resistant (MDR) strain provides new insights into the potential molecular mechanisms of MDR and fitness', 'Sofianos G, Piombo E, Dubey M, Karlsson M, Karaoglanidis G, Tzelepis G', 2024, 'Molecular plant pathology', '10.1111/mpp.70004', 'https://doi.org/10.1111/mpp.70004', 'https://europepmc.org/articles/PMC11380696?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Botrytis cinerea is a notorious pathogen causing pre- and post-harvest spoilage in many economically important crops. Excessive application of site-specific fungicides to control the pathogen has led to the selection of strains possessing target site alterations associated with resistance to these fungicides and/or strains overexpressing efflux transporters associated with multidrug resistance (MDR). MDR in B. cinerea has been correlated with the overexpression of atrB and mfsM2, encoding an ATP-binding cassette (ABC) and a major facilitator superfamily (MFS) transporter, respectively. However, it remains unknown whether other transporters may also contribute to the MDR phenotype. In the current study, the transcriptome of a B. cinerea multidrug-resistant (MDR) field strain was analysed upon exposure to the fungicide fludioxonil, and compared to the B05.10 reference strain. The transcriptome of this field strain displayed significant differences as compared to B05.10, including genes involved in sugar membrane transport, toxin production and virulence. Among the induced genes in the field strain, even before exposure to fludioxonil, were several putatively encoding ABC and MFS transmembrane transporters. Overexpression of a highly induced MFS transporter gene in the B05.10 strain led to an increased tolerance to the fungicides fluopyram and boscalid, indicating an involvement in efflux transport of these compounds. Overall, the data from this study give insights towards better understanding the molecular mechanisms involved in MDR and fitness cost, contributing to the development of more efficient control strategies against this pathogen.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c45f1e3-e59b-4a27-a8cc-a1065d57c4b7', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Concurrent Overexpression of OsGS1;1 and OsGS2 Genes in Transgenic Rice (Oryza sativa L.): Impact on Tolerance to Abiotic Stresses', 'James D, Borphukan B, Fartyal D, Ram B, Singh J, Manna M, Sheri V, Panditi V', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00786', 'https://doi.org/10.3389/fpls.2018.00786', 'https://europepmc.org/articles/PMC6021690?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Glutamine synthetase (GS) is a key enzyme involved in the nitrogen metabolism of higher plants. Abiotic stresses have adverse effects on crop production and pose a serious threat to global food security. GS activity and expression is known to be significantly modulated by various abiotic stresses. However, very few transgenic overexpression studies of GS have studied its impact on abiotic stress tolerance. GS is also the target enzyme of the broad spectrum herbicide Glufosinate (active ingredient: phosphinothricin). In this study, we investigated the effect of concurrent overexpression of the rice cytosolic GS1 (OsGS1;1) and chloroplastic GS2 (OsGS2) genes in transgenic rice on its tolerance to abiotic stresses and the herbicide Glufosinate. Our results demonstrate that the co-overexpression of OsGS1;1 and OsGS2 isoforms in transgenic rice plants enhanced its tolerance to osmotic and salinity stress at the seedling stage. The transgenic lines maintained significantly higher fresh weight, chlorophyll content, and relative water content than wild type (wt) and null segregant (ns) controls, under both osmotic and salinity stress. The OsGS1;1/OsGS2 co-overexpressing transgenic plants accumulated higher levels of proline but showed lower electrolyte leakage and had lower malondialdehyde (MDA) content under the stress treatments. The transgenic lines showed considerably enhanced photosynthetic and agronomic performance under drought and salinity stress imposed during the reproductive stage, as compared to wt and ns control plants. The grain filling rates of the transgenic rice plants under reproductive stage drought stress (64.6 ± 4.7%) and salinity stress (58.2 ± 4.5%) were significantly higher than control plants, thereby leading to higher yields under these abiotic stress conditions. Preliminary analysis also revealed that the transgenic lines had improved tolerance to methyl viologen induced photo-oxidative stress. Taken together, our results demonstrate that the concurrent overexpression of OsGS1;1 and OsGS2 isoforms in rice enhanced physiological tolerance and agronomic performance under adverse abiotic stress conditions, apparently acting through multiple mechanistic routes. The transgenic rice plants also showed limited tolerance to the herbicide Glufosinate. The advantages and limitations of glutamine synthetase overexpression in crop plants, along with future strategies to overcome these limitations for utilization in crop improvement have also been discussed briefly.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5373d527-a2a8-4b8c-bc9f-70240de320c9', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Current knowledge in lentil genomics and its application for crop improvement', 'Kumar S, Rajendran K, Kumar J, Hamwieh A, Baum M', 2015, 'Frontiers in plant science', '10.3389/fpls.2015.00078', 'https://doi.org/10.3389/fpls.2015.00078', 'https://europepmc.org/articles/PMC4337236?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Most of the lentil growing countries face a certain set of abiotic and biotic stresses causing substantial reduction in crop growth, yield, and production. Until-to date, lentil breeders have used conventional plant breeding techniques of selection-recombination-selection cycle to develop improved cultivars.These techniques have been successful in mainstreaming some of the easy-to-manage monogenic traits. However, in case of complex quantitative traits, these conventional techniques are less precise. As most of the economic traits are complex, quantitative, and often influenced by environments and genotype-environment interaction, the genetic improvement of these traits becomes difficult. Genomics assisted breeding is relatively powerful and fast approach to develop high yielding varieties more suitable to adverse environmental conditions. New tools such as molecular markers and bioinformatics are expected to generate new knowledge and improve our understanding on the genetics of complex traits. In the past, the limited availability of genomic resources in lentil could not allow breeders to employ these tools in mainstream breeding program.The recent application of the next generation sequencing and genotyping by sequencing technologies has facilitated to speed up the lentil genome sequencing project and large discovery of genome-wide single nucleotide polymorphism (SNP) markers. Currently, several linkage maps have been developed in lentil through the use of expressed sequenced tag (EST) derived simple sequence repeat (SSR) and SNP markers.These maps have emerged as useful genomic resources to identify quantitative trait loci imparting tolerance to biotic and abiotic stresses in lentil. In this review, the current knowledge on available genomic resources and its application in lentil breeding program are discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3a49233c-814f-4c44-9269-8e7dc7b81711', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Enhanced Nitrogen Uptake and Early Flowering Mitigate Fitness Costs Associated With Glufosinate Resistance in Goosegrass (Eleusine indica)', 'Xinyu Cui, Hanxia Yu, Junjie You, Yinzhi Lv, Xingshan Tian, Chun Zhang', 2026, 'Food and Energy Security', '10.1002/fes3.70250', 'https://doi.org/10.1002/fes3.70250', 'https://doi.org/10.1002/fes3.70250', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT Herbicide resistance in weeds is frequently accompanied by fitness trade‐offs that compromise survival and reproductive success. In this study, we investigated a glufosinate‐resistant (R) population of Eleusine indica, in which the GS1‐1Ser59Gly mutation confers resistance to glufosinate, alongside a susceptible (S) population. Both R and S populations achieved 100% final germination under natural germination conditions, with no significant difference in germination rate. However, R plants displayed significantly earlier tillering and flowering in both monoculture and mixed growth conditions, approximately 15 days earlier than the S population, indicating accelerated reproductive timing. This precocity incurred a substantial fitness cost, manifested as a ~60% reduction in seed production per plant and reduced competitive suppression of rice growth. Transcriptomic analysis identified EiMADS56, a key‐flowering regulatory gene, that was significantly upregulated (2.2‐ to 3.1‐fold) in the R population, and its over‐expression of EiMADS56 in Arabidopsis thaliana advanced flowering by approximately 7 days. Moreover, the R population demonstrated enhanced ammonium nitrogen (NH4+) uptake and transport efficiency, suggesting a mechanistic link between improved nitrogen utilization and early reproduction. These results suggest that the GS1‐1Ser59Gly mutation may drive fitness trade‐offs in glufosinate‐resistant E. indica via nitrogen uptake‐mediated reproductive acceleration, thereby providing preliminary insights for refining herbicide resistance management and ecological risk evaluation.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('14e4c5a2-5992-4bb4-83b6-4e78d555ca7b', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Function of cytochrome P450 CYP72A1182 in metabolic herbicide resistance evolution in Amaranthus palmeri populations', 'Rigon CAG, Küpper A, Sparks C, Montgomery J, Peter F, Schepp S, Perez-Jones A, Tranel PJ', 2025, 'Journal of experimental botany', '10.1093/jxb/eraf114', 'https://doi.org/10.1093/jxb/eraf114', 'https://europepmc.org/articles/PMC12223498?pdf=render', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc by', 'Evolution of metabolic herbicide resistance is a major issue for weed management. Few genes and regulatory mechanisms have been identified, particularly in dicotyledonous weed species. We identified putative causal genes and regulatory mechanism for tembotrione resistance in Palmer amaranth (Amaranthus palmeri). Cytochrome P450 candidate genes were identified through RNA-seq analysis. We validated their functions using heterologous expression in Saccharomyces cerevisae. Promoters of the candidate P450 genes were analysed. We performed QTL mapping to identify genomic regions associated with resistance. CYP72A1182 metabolized tembotrione in a heterologous system. The CYP72A1182 gene had increased expression in other A. palmeri populations resistant to multiple herbicides, including tembotrione. Resistant plants exhibited polymorphisms in the promoter of CYP72A1182. We identified quantitative trait loci linked to herbicide resistance, including one on chromosome 4 approximately 3 Mb away from CYP72A1182. CYP72A1182 is likely involved in tembotrione resistance in A. palmeri. Increased expression of this gene could be due to cis-regulation in the promoter, as well as trans-regulation from transcription factors, and further studies are in progress to test this hypothesis. The elucidation of regulatory genes is crucial for developing innovative weed management approaches and target-based novel herbicide molecules.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a57bc75-7326-4b81-b99c-6a99a36016bf', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Genetically Engineered Crops: Importance of Diversified Integrated Pest Management for Agricultural Sustainability', 'Anderson JA, Ellsworth PC, Faria JC, Head GP, Owen MDK, Pilcher CD, Shelton AM, Meissle M', 2019, 'Frontiers in bioengineering and biotechnology', '10.3389/fbioe.2019.00024', 'https://doi.org/10.3389/fbioe.2019.00024', 'https://europepmc.org/articles/PMC6391707?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'As the global population continues to expand, utilizing an integrated approach to pest management will be critically important for food security, agricultural sustainability, and environmental protection. Genetically engineered (GE) crops that provide protection against insects and diseases, or tolerance to herbicides are important tools that complement a diversified integrated pest management (IPM) plan. However, despite the advantages that GE crops may bring for simplifying the approach and improving efficiency of pest and weed control, there are also challenges for successful implementation and sustainable use. This paper considers how several GE traits, including those that confer protection against insects by expression of proteins from Bacillus thuringiensis (Bt), traits that confer tolerance to herbicides, and RNAi-based traits that confer resistance to viral pathogens, can be key elements of a diversified IPM plan for several different crops in both developed and developing countries. Additionally, we highlight the importance of community engagement and extension, strong partnership between industry, regulators and farmers, and education and training programs, for achieving long-term success. By leveraging the experiences gained with these GE crops, understanding the limitations of the technology, and considering the successes and failures of GE traits in IPM plans for different crops and regions, we can improve the sustainability and versatility of IPM plans that incorporate these and future technologies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('db825708-eb31-4c7b-9731-64bf7388eaa2', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'USE OF ULTRA COARSE DROPLETS AT DIFFERENT SPRAY VOLUMES TO CONTROL WEEDS WITH DICAMBA AND GLYPHOSATE HERBICIDES', 'João P. A. R. da Cunha, Ulisses R. Antuniassi, Rodolfo G. Chechetto, Matheus G. Palhano, Ramiro F. L. Ovejero, Aline Deon', 2022, 'Engenharia Agrícola', '10.1590/1809-4430-eng.agric.v42n4e20220004/2022', 'https://doi.org/10.1590/1809-4430-eng.agric.v42n4e20220004/2022', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-69162022000400205&tlng=en', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT The use of ultra-coarse droplets for herbicide application reduces the risk of drift but may compromise the coverage and efficacy of the treatment. The objective of this work was to evaluate the use of ultra-coarse droplets, in different spray volumes, in the application of dicamba herbicide in association with glyphosate, for the control of weeds in two field trials. The first trial was conducted in a 5 x 2 factorial design, with five spray volumes (58, 72, 96, 144, and 177 L ha-1) and two air induction flat-fan spray tips (MUG 110015 - MagnoJet and TTI 110015 - Teejet). The control efficiency of Commelina benghalensis and the spray deposition on the target were evaluated by detecting a tracer using spectrophotometry. The second was conducted in a 2 x 2 factorial scheme, using two volumes (100 and 125 L ha-1) and two tips (MUG 11002 and TTI 11002). The control efficiency of Conyza spp. and fresh matter were evaluated. The different spray volumes and tips did not differ in relation to the deposition of the tracer. The use of ultra-coarse droplets was adequate for weed control. The TTI and MUG tips gave similar and adequate control performance starting at 96 L ha-1. Increasing the volume above 100 L ha-1 did not result in better control.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fc2c10e4-4f87-4308-aaf6-b5bcc2b96168', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Herbicide-resistant crops: utilities and limitations for herbicide-resistant weed management', 'Green JM, Owen MD', 2011, 'Journal of agricultural and food chemistry', '10.1021/jf101286h', 'https://doi.org/10.1021/jf101286h', 'https://europepmc.org/articles/PMC3105486?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'open access (Europe PMC)', 'Since 1996, genetically modified herbicide-resistant (HR) crops, particularly glyphosate-resistant (GR) crops, have transformed the tactics that corn, soybean, and cotton growers use to manage weeds. The use of GR crops continues to grow, but weeds are adapting to the common practice of using only glyphosate to control weeds. Growers using only a single mode of action to manage weeds need to change to a more diverse array of herbicidal, mechanical, and cultural practices to maintain the effectiveness of glyphosate. Unfortunately, the introduction of GR crops and the high initial efficacy of glyphosate often lead to a decline in the use of other herbicide options and less investment by industry to discover new herbicide active ingredients. With some exceptions, most growers can still manage their weed problems with currently available selective and HR crop-enabled herbicides. However, current crop management systems are in jeopardy given the pace at which weed populations are evolving glyphosate resistance. New HR crop technologies will expand the utility of currently available herbicides and enable new interim solutions for growers to manage HR weeds, but will not replace the long-term need to diversify weed management tactics and discover herbicides with new modes of action. This paper reviews the strengths and weaknesses of anticipated weed management options and the best management practices that growers need to implement in HR crops to maximize the long-term benefits of current technologies and reduce weed shifts to difficult-to-control and HR weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f405b40b-d2c7-4e6a-9549-fd255628dc8d', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Herbicides Harm Key Orchard Predatory Mites', 'Bergeron P, Schmidt-Jeffris R', 2023, 'Insects', '10.3390/insects14050480', 'https://doi.org/10.3390/insects14050480', 'https://europepmc.org/articles/PMC10231069?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'The phytoseiid mites Galendromus occidentalis and Amblydromella caudiglans are critical for conservation biological control of pest mites in Washington State, U.S.A. apples. While the non-target effects of insecticides on phytoseiids are well described, research on herbicide effects is limited. Using laboratory bioassays, we examined lethal (female mortality) and sublethal (fecundity, egg hatch, larval survival) effects of seven herbicides and five adjuvants on A. caudiglans and G. occidentalis. The effects of mixing herbicides with recommended adjuvants were also tested to determine if the addition of an adjuvant increased herbicide toxicity. Glufosinate was the least selective herbicide tested, causing 100% mortality in both species. Paraquat caused 100% mortality in A. caudiglans and 56% mortality in G. occidentalis. Sublethal effects were significant for both species when exposed to oxyfluorfen. Adjuvants did not cause non-target effects in A. caudiglans. The non-ionic surfactant and methylated seed oil increased mortality and decreased reproduction in G. occidentalis. The high toxicity of glufosinate and paraquat for both predators is concerning; these are the primary "burn down" herbicide alternatives to glyphosate, which is decreasing in use due to consumer toxicity concerns. Field studies are needed to determine the extent to which herbicides disrupt orchard biological control, focusing on glufosinate, paraquat, and oxyfluorfen. Consumer preferences will need to be balanced with natural enemy conservation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7ac2776d-652f-4fe4-9cb5-4fe67e15c83c', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Insights Into Genetic and Molecular Elements for Transgenic Crop Development', 'Basso MF, Arraes FBM, Grossi-de-Sa M, Moreira VJV, Alves-Ferreira M, Grossi-de-Sa MF', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00509', 'https://doi.org/10.3389/fpls.2020.00509', 'https://europepmc.org/articles/PMC7243915?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Climate change and the exploration of new areas of cultivation have impacted the yields of several economically important crops worldwide. Both conventional plant breeding based on planned crosses between parents with specific traits and genetic engineering to develop new biotechnological tools (NBTs) have allowed the development of elite cultivars with new features of agronomic interest. The use of these NBTs in the search for agricultural solutions has gained prominence in recent years due to their rapid generation of elite cultivars that meet the needs of crop producers, and the efficiency of these NBTs is closely related to the optimization or best use of their elements. Currently, several genetic engineering techniques are used in synthetic biotechnology to successfully improve desirable traits or remove undesirable traits in crops. However, the features, drawbacks, and advantages of each technique are still not well understood, and thus, these methods have not been fully exploited. Here, we provide a brief overview of the plant genetic engineering platforms that have been used for proof of concept and agronomic trait improvement, review the major elements and processes of synthetic biotechnology, and, finally, present the major NBTs used to improve agronomic traits in socioeconomically important crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05570489-1d8a-444d-8818-d5432ead89cc', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Maize transformation technology development for commercial event generation', 'Que Q, Elumalai S, Li X, Zhong H, Nalapalli S, Schweiner M, Fei X, Nuccio M', 2014, 'Frontiers in plant science', '10.3389/fpls.2014.00379', 'https://doi.org/10.3389/fpls.2014.00379', 'https://europepmc.org/articles/PMC4122164?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Maize is an important food and feed crop in many countries. It is also one of the most important target crops for the application of biotechnology. Currently, there are more biotech traits available on the market in maize than in any other crop. Generation of transgenic events is a crucial step in the development of biotech traits. For commercial applications, a high throughput transformation system producing a large number of high quality events in an elite genetic background is highly desirable. There has been tremendous progress in Agrobacterium-mediated maize transformation since the publication of the Ishida et al. (1996) paper and the technology has been widely adopted for transgenic event production by many labs around the world. We will review general efforts in establishing efficient maize transformation technologies useful for transgenic event production in trait research and development. The review will also discuss transformation systems used for generating commercial maize trait events currently on the market. As the number of traits is increasing steadily and two or more modes of action are used to control key pests, new tools are needed to efficiently transform vectors containing multiple trait genes. We will review general guidelines for assembling binary vectors for commercial transformation. Approaches to increase transformation efficiency and gene expression of large gene stack vectors will be discussed. Finally, recent studies of targeted genome modification and transgene insertion using different site-directed nuclease technologies will be reviewed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8db5af77-b49b-4bd5-99e1-99844b13e72c', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Multiplex CRISPR-Cas9 Gene-Editing Can Deliver Potato Cultivars with Reduced Browning and Acrylamide', 'Ly DNP, Iqbal S, Fosu-Nyarko J, Milroy S, Jones MGK', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12020379', 'https://doi.org/10.3390/plants12020379', 'https://europepmc.org/articles/PMC9864857?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Storing potato tubers at cold temperatures, either for transport or continuity of supply, is associated with the conversion of sucrose to reducing sugars. When cold-stored cut tubers are processed at high temperatures, with endogenous asparagine, acrylamide is formed. Acrylamide is classified as a carcinogen. Potato processors prefer cultivars which accumulate fewer reducing sugars and thus less acrylamide on processing, and suitable processing cultivars may not be available. We used CRISPR-Cas9 to disrupt the genes encoding vacuolar invertase (VInv) and asparagine synthetase 1 (AS1) of cultivars Atlantic and Desiree to reduce the accumulation of reducing sugars and the production of asparagine after cold storage. Three of the four guide RNAs employed induced mutation frequencies of 17-98%, which resulted in deletions, insertions and substitutions at the targeted gene sites. Eight of ten edited events had mutations in at least one allele of both genes; for two, only the VInv was edited. No wild-type allele was detected in both genes of events DSpco7, DSpFN4 and DSpco12, suggesting full allelic mutations. Tubers of two Atlantic and two Desiree events had reduced fructose and glucose concentrations after cold storage. Crisps from these and four other Desiree events were lighter in colour and included those with 85% less acrylamide. These results demonstrate that multiplex CRISPR-Cas9 technology can generate improved potato cultivars for healthier processed potato products.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3398f053-187e-4299-bd75-d895dbd80344', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Overexpression of AtNCED3 gene improved drought tolerance in soybean in greenhouse and field conditions', 'Molinari MDC, Fuganti-Pagliarini R, Marin SRR, Ferreira LC, Barbosa DA, Marcolino-Gomes J, Oliveira MCN, Mertz-Henning LM', 2020, 'Genetics and molecular biology', '10.1590/1678-4685-gmb-2019-0292', 'https://doi.org/10.1590/1678-4685-gmb-2019-0292', 'https://europepmc.org/articles/PMC7278712?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Water deficit is an important climatic problem that can impair agriculture yield and economy. Genetically modified soybean plants containing the AtNCED3 gene were obtained aiming drought-tolerance improvement. The NCED3 gene encodes a 9-cis-epoxycarotenoid dioxygenase (NCED, EC 1.13.11.51), an important enzyme in abscisic acid biosynthesis. ABA activates the expression of drought-responsive genes, in water-deficit conditions, targeting defense mechanisms and enabling plants to survive under low water availability. Results from greenhouse experiments showed that the transgene AtNCED3 and the endogenous genes GmAREB1, GmPP2C, GmSnRK2 and GmAAO3 presented higher expression under water deficit (WD) in the event 2Ha11 than in WT-plants. No significant correlation was observed between the plant materials and WD conditions for growth parameters; however, gas exchange measurements decreased in the GM event, which also showed 80% higher intrinsic water use when compared to WT plants. In crop season 2015/16, event 2Ha11 showed higher total number of pods, higher number of pods with seeds and yield than WT plants. ABA concentration was also higher in GM plants under WD. These results obtained in field screenings suggest that AtNCED3 soybean plants might outperform under drought, reducing economic and yield losses, thus being a good candidate line to be incorporated in the soybean-breeding program to develop drought-tolerant cultivars.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4a636aab-7499-4f31-b6b7-3db26d44e590', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Overlapping Residual Herbicides for Control of Photosystem (PS) II- and 4-Hydroxyphenylpyruvate Dioxygenase (HPPD)-Inhibitor-Resistant Palmer amaranth (Amaranthus palmeri S. Watson) in Glyphosate-Resistant Maize', 'Chahal PS, Ganie ZA, Jhala AJ', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.02231', 'https://doi.org/10.3389/fpls.2017.02231', 'https://europepmc.org/articles/PMC5767313?pdf=render', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by', 'A Palmer amaranth (Amaranthus palmeri S. Watson) biotype has evolved resistance to photosystem (PS) II- (atrazine) and 4-hydroxyphenylpyruvate dioxygenase (HPPD)-inhibiting herbicides (mesotrione, tembotrione, and topramezone) in maize seed production field in Nebraska, USA. The objectives of this study were to determine the effect of soil residual pre-emergence (PRE) herbicides followed by (fb) tank-mixture of residual and foliar active post-emergence (POST) herbicides on PS-II- and HPPD-inhibitor-resistant Palmer amaranth control, maize yield, and net economic returns. Field experiments were conducted in a grower''s field infested with PS II- and HPPD-inhibitor-resistant Palmer amaranth near Shickley in Fillmore County, Nebraska, USA in 2015 and 2016. The contrast analysis suggested that saflufenacil plus dimethenamid-P or pyroxasulfone plus saflufenacil applied PRE provided 80-82% Palmer amaranth control compared to 65 and 39% control with saflufenacil and pyroxasulfone applied alone at 3 weeks after PRE (WAPRE), respectively. Among the PRE fb POST herbicide programs, 95-98% Palmer amaranth control was achieved with pyroxasulfone plus safluefenacil, or saflufenacil plus dimethenamid-P applied PRE, fb glyphosate plus topramezone plus dimethenamid-P plus atrazine, glyphosate plus diflufenzopyr plus dicamba plus pyroxasulfone, glyphosate plus diflufenzopyr plus pendimethalin, or glyphosate plus diflufenzopyr plus dicamba plus atrazine applied POST at 3 weeks after POST (WAPOST) through maize harvest. Based on contrast analysis, PRE fb POST programs provided 77-83% Palmer amaranth control at 3 WAPOST through maize harvest compared to 12-15% control with PRE-only and 66-84% control with POST-only programs. Similarly, PRE fb POST programs provided 99% biomass reduction at 6 WAPOST compared to PRE-only (28%) and POST-only (87%) programs. PRE fb POST programs provided higher maize yield (13,617 kg ha-1) and net return (US $1,724 ha-1) compared to the PRE-only (2,656 kg ha-1; US $285 ha-1) and POST-only (11,429 kg ha-1; US $1,539 ha-1) programs. The results indicated that effective control of multiple herbicide-resistant Palmer amaranth can be achieved with PRE fb POST programs that include herbicides with overlapping residual activity to maintain season-long control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('73b5ec73-4cee-45df-9f90-7e8bfa188534', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Reduction of Ryegrass (Lolium multiflorum Lam.) Natural Re-Sowing with Herbicides and Plant Growth Regulators', 'Afonso Henrique Schaeffer, Otávio Augusto Schaeffer, Diógenes Cecchin Silveira, João Arthur Guareschi Bertol, Debora Kelli Rocha, Fernando Machado dos Santos, Leandro Vargas, Nadia Canali Lângaro', 2020, 'Agronomy', '10.3390/agronomy10121960', 'https://doi.org/10.3390/agronomy10121960', 'https://www.mdpi.com/2073-4395/10/12/1960', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Ryegrass (Lolium multiflorum Lam.) is the main winter weed of crops in Southern Brazil. High competitiveness, adaptability, widespread resistance to herbicides and seed dormancy make the plant a permanent problem. Herbicides, as well as plant growth regulators, can be used as a management option for ryegrass seed production, however there is no consensus among authors at which stage of the plant the application is most effective. Thus, this study aimed to evaluate the production and physiological quality of ryegrass seeds in response to the application of herbicides and plant growth regulators in three stages of plant development (inflorescence emergence, flowering and fruit development). Each treatment consisted of applying two different doses of each of the active ingredients: ammonium glufosinate, clethodim, glyphosate, iodosulfuron-methyl, paraquat and 2,4-D (herbicides); ethephon and trinexapac-ethyl (plant growth regulators), still an untreated control, totaling 17 treatments for each stage of development. The experimental design used was randomized blocks, with three replications. The variables evaluated were: seed production (kg ha−1), thousand seed weight (g), viability (%), germination (%), first germination count (%), dormant seeds (%) and dead seeds (%). The ryegrass seed production reduced 100% with clethodim, glyphosate, ammonium glufosinate or paraquat applied in the inflorescence emergence or flowering stages. In the fruit development stage, all treatments (herbicides and plant growth regulators) caused deleterious effects on seed production, the greatest effect occurred with paraquat (95%). Paraquat, ammonium glufosinate and clethodim affected the physiological quality of the seeds when applied in fruit development stage. This research demonstrated that the application of herbicides in the ryegrass reproductive stage decreases its seedbank replenishment (natural re-sowing), with the potential to harm its progeny.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b88e4993-d0b0-4e11-8095-dc9009550e8a', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Resistance to PPO-inhibiting herbicide in Palmer amaranth from Arkansas', 'Salas RA, Burgos NR, Tranel PJ, Singh S, Glasgow L, Scott RC, Nichols RL', 2016, 'Pest management science', '10.1002/ps.4241', 'https://doi.org/10.1002/ps.4241', 'https://europepmc.org/articles/PMC5069602?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundThe widespread occurrence of ALS inhibitor- and glyphosate-resistant Amaranthus palmeri has led to increasing use of protoporphyrinogen oxidase (PPO)-inhibiting herbicides in cotton and soybean. Studies were conducted to confirm resistance to fomesafen (a PPO inhibitor), determine the resistance frequency, examine the resistance profile to other foliar-applied herbicides and investigate the resistance mechanism of resistant plants in a population collected in 2011 (AR11-LAW B) and its progenies from two cycles of fomesafen selection (C1 and C2).ResultsThe frequency of fomesafen-resistant plants increased from 5% in the original AR11-LAW-B to 17% in the C2 population. The amounts of fomesafen that caused 50% growth reduction were 6-, 13- and 21-fold greater in AR11-LAW-B, C1 and C2 populations, respectively, than in the sensitive ecotype. The AR11-LAW-B population was sensitive to atrazine, dicamba, glufosinate, glyphosate and mesotrione but resistant to ALS-inhibiting herbicides pyrithiobac and trifloxysulfuron. Fomesafen survivors from C1 and C2 populations tested positive for the PPO glycine 210 deletion previously reported in waterhemp (Amaranthus tuberculatus).ConclusionThese studies confirmed that Palmer amaranth in Arkansas has evolved resistance to foliar-applied PPO-inhibiting herbicide.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('891ff797-56ec-4ba3-a31b-81629556b6dd', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'RNA-Seq transcriptome analysis of Amaranthus palmeri with differential tolerance to glufosinate herbicide', 'Salas-Perez RA, Saski CA, Noorai RE, Srivastava SK, Lawton-Rauh AL, Nichols RL, Roma-Burgos N', 2018, 'PloS one', '10.1371/journal.pone.0195488', 'https://doi.org/10.1371/journal.pone.0195488', 'https://europepmc.org/articles/PMC5908165?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'cc by', 'Amaranthus palmeri (Amaranthaceae) is a noxious weed in several agroecosystems and in some cases seriously threatens the sustainability of crop production in North America. Glyphosate-resistant Amaranthus species are widespread, prompting the use of alternatives to glyphosate such as glufosinate, in conjunction with glufosinate-resistant crop cultivars, to help control glyphosate-resistant weeds. An experiment was conducted to analyze the transcriptome of A. palmeri plants that survived exposure to 0.55 kg ha-1 glufosinate. Since there was no record of glufosinate use at the collection site, survival of plants within the population are likely due to genetic expression that pre-dates selection; in the formal parlance of weed science this is described as natural tolerance. Leaf tissues from glufosinate-treated and non-treated seedlings were harvested 24 h after treatment (HAT) for RNA-Seq analysis. Global gene expression was measured using Illumina DNA sequence reads from non-treated and treated surviving (presumably tolerant, T) and susceptible (S) plants. The same plants were used to determine the mechanisms conferring differential tolerance to glufosinate. The S plants accumulated twice as much ammonia as did the T plants, 24 HAT. The relative copy number of the glufosinate target gene GS2 did not differ between T and S plants, with 1 to 3 GS2 copies in both biotypes. A reference cDNA transcriptome consisting of 72,780 contigs was assembled, with 65,282 sequences putatively annotated. Sequences of GS2 from the transcriptome assembly did not have polymorphisms unique to the tolerant plants. Five hundred sixty-seven genes were differentially expressed between treated T and S plants. Of the upregulated genes in treated T plants, 210 were more highly induced than were the upregulated genes in the treated S plants. Glufosinate-tolerant plants had greater induction of ABC transporter, glutathione S-transferase (GST), NAC transcription factor, nitronate monooxygenase (NMO), chitin elicitor receptor kinase (CERK1), heat shock protein 83, ethylene transcription factor, heat stress transcription factor, NADH-ubiquinone oxidoreductase, ABA 8''-hydroxylase, and cytochrome P450 genes (CYP72A, CYP94A1). Seven candidate genes were selected for validation using quantitative real time-PCR. While GST was upregulated in treated tolerant plants in at least one population, CYP72A219 was consistently highly expressed in all treated tolerant biotypes. These genes are candidates for contributing tolerance to glufosinate. Taken together, these results show that differential induction of stress-protection genes in a population can enable some individuals to survive herbicide application. Elevated expression of detoxification-related genes can get fixed in a population with sustained selection pressure, leading to evolution of resistance. Alternatively, sustained selection pressure could select for mutation(s) in the GS2 gene with the same consequence.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('510f836d-c66b-4f9f-bd13-6a835545bff0', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Scientific Opinion on an application from Pioneer Hi-Bred International and Dow AgroSciences LLC (EFSA-GMO-NL-2005-23) for placing on the market of genetically modified maize 59122 for food and feed uses, import, processing and cultivation under Regulation (EC) No 1829/2003', 'EFSA Panel on Genetically Modified Organisms (GMO)', 2013, 'EFSA Journal', '10.2903/j.efsa.2013.3135', 'https://doi.org/10.2903/j.efsa.2013.3135', 'http://www.efsa.europa.eu/en/efsajournal/doc/3135.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'This Scientific Opinion reports on a risk assessment on an application for placing on the market of genetically modified maize 59122 for import and processing for food and feed uses and cultivation. The EFSA GMO Panel considers that maize 59122 is unlikely to have any adverse effect on the environment, except for the possible evolution of resistance to the Cry34Ab1/Cry35Ab1 proteins in coleopteran target pests. The Panel recommends the implementation of appropriate and diversified insect resistance management strategies and case-specific monitoring to delay and monitor the possible evolution of resistance to Cry34Ab1/Cry35Ab1 in coleopteran target pests, respectively. In addition, the Panel recommends revision of the applicants’ insect resistance management plan and the proposed post-market environmental monitoring plan. Although maize 59122 is tolerant to glufosinate-ammonium-based herbicides, the Panel did not assess the potential adverse effects associated with the use of such herbicides on maize 59122, as maize 59122 will not be marketed in the European Union as a herbicide-tolerant crop. This Scientific Opinion updates the previous Panel safety evaluation of the food and feed uses, and import and processing of maize 59122 and derived products. The Panel concludes that the information available for maize 59122 addresses the scientific comments raised by Member States and that maize 59122, as described in this application, is as safe as its conventional counterpart and commercial maize varieties with respect to potential adverse effects on human and animal health. If subjected to appropriate management measures, the cultivation of maize 59122 is unlikely to raise safety concerns for the environment.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0210605-fe0d-441e-b93a-563e2a6a3b0f', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Survey of glufosinate use in soybean production in Arkansas and Wisconsin', 'Nikola Arsenijevic, Thomas Richard Butts, Jed Colquhoun, Shawn Paul Conley, Bruno Canella Vieira, Rodrigo Werle', 2026, 'Weed Technology', '10.1017/wet.2026.10118', 'https://doi.org/10.1017/wet.2026.10118', 'https://www.cambridge.org/core/product/identifier/S0890037X26101183/type/journal_article', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Glufosinate is a key postemergence herbicide in U.S. soybean production, particularly where resistance to glyphosate and inhibitors of acetolactate synthase is widespread. A 25-question survey of soybean growers, agronomists, and industry professionals in Arkansas and Wisconsin was conducted in Fall 2022 to characterize glufosinate use patterns, weed management challenges, and stakeholder perceptions. Palmer amaranth was reported as the most problematic weed in Arkansas (97% of respondents), and waterhemp was most frequently reported in Wisconsin (92%). Suspected glyphosate resistance was widely reported (97% in Arkansas, 88% in Wisconsin), and suspected glufosinate resistance was reported by 37% of Arkansas respondents and by 3% of Wisconsin respondents. Eighty-four percent of Arkansas respondents reported integrating glufosinate into their weed management programs, as did 53% of Wisconsin respondents, and most respondents said they used it to target broadleaf weeds ≤15 cm tall. Carrier volumes were 103 to 140 L ha−1 (chosen by 75% of Arkansas respondents), and 150 to 187 L ha−1 (chosen by 86% of respondents from Wisconsin). Arkansas respondents most frequently reported using glufosinate in sequential first and second postemergence applications (62%). In Wisconsin, glufosinate use was reported mostly only as a first postemergence application (37%), followed closely by sequential use in the first and second postemergence applications (34%). Weed size, followed by carrier volume and air temperature, were ranked as the most important factors affecting glufosinate performance. Ammonium sulfate was the most used adjuvant (45% in Arkansas; 67% in Wisconsin), and spray water quality was rarely tested. Frequently reported tank-mix partners included glyphosate and inhibitors of protoporphyrinogen oxidase in Arkansas and synthetic auxins and clethodim in Wisconsin. Extension efforts should emphasize applying glufosinate to small weeds (<10 cm in height), optimizing application technology and spray solution characteristics (nozzle, carrier volume, water quality/adjuvant selection), and spraying under favorable environmental conditions. Improving application consistency can reduce weed escapes and repeat postemergence applications, thereby lowering selection pressure and preserving glufosinate as an important postemergence option.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('601dcb3d-64ef-4356-82d6-34c773fdee85', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'The Development of Macrophomina phaseolina (Fungus) Resistant and Glufosinate (Herbicide) Tolerant Transgenic Jute', 'Shuvobrata Majumder, Karabi Datta, Chirabrata Sarkar, Subhas C. Saha, Swapan K. Datta', 2018, 'Frontiers in Plant Science', '10.3389/fpls.2018.00920', 'https://doi.org/10.3389/fpls.2018.00920', 'https://www.frontiersin.org/article/10.3389/fpls.2018.00920/full', NULL, NULL, 19, NULL, 'other', 1, 'open access (DOAJ)', 'The worldwide demand for natural bast fibers is met aptly by the long, golden and silky fibers of jute. This highest bast fiber producing crop is of great applicability and is extensively used in paper and textile industry. Macrophomina phaseolina (Tassi) Goid is a severely devastating necrotrophic fungal pathogen causing stem rot, root rot, and charcoal rot diseases in both the cultivated species of jute – Corchorus capsularis and Corchorus olitorius. Another major problem faced in jute cultivation is profuse weed infestation in the fields. Huge losses in quality fiber production is caused by this pathogenic fungi and cultivation cost increases as well due to weed management expenditure during cropping season. To solve these long persisting jute cultivation challenges, the chitinase (chi11) gene (to provide fungus resistance) and the bar gene (to provide herbicide tolerance) have been incorporated in C. capsularis JRC-321 via Agrobacterium transformation and analyzed up to T2 generation. Stable integration and expression of these two genes in the jute genome was confirmed upon extensive analyses. Transgenic plants showed higher chitinase expression and chitin degrading activity than non-transgenic control plants. Antifungal activity significantly increased in transgenic plants as confirmed by detached leaf and whole plant M. phaseolina bioassay. Herbicide tolerance was analyzed by growing transgenic plants in 10 mg/l glufosinate ammonium containing media and by spraying 0.25% (v/v) glufosinate herbicide Basta® on them. Assessment of residual phytotoxicity effects of Basta® on soil confirmed no negative impact on growth of indicator plants corn and cucumber. Transgenic jute plants were at par with non-transgenic (control) jute plants in all phenotypic aspects. Non-transgenic (control) jute plants suffered significant losses in fiber yield and quality due to M. phaseolina infection whereas the transgenic lines maintained the quality of fiber even after the infection.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('403b9e92-01bf-413f-9e3f-461e8b72d2e2', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Thermo-responsive polysulfobetaine beads crosslinked with biodegradable alginates for controlled release of agricultural pesticide', 'Andrade-Gagnon B, Olszewski C, Bawa KK, Hemraz UD, Oh JK', 2026, 'RSC advances', '10.1039/d5ra08674d', 'https://doi.org/10.1039/d5ra08674d', 'https://europepmc.org/articles/PMC12814940?pdf=render', NULL, NULL, 8, NULL, 'canada', 3, 'cc by-nc', 'The rise in global food demand and the loss in crop production by pests highlight the need for efficient pesticide delivery systems. Stimuli-responsive degradation with thermoresponsive polymers is a promising platform that offers the controlled release of pesticides. Here, we report the development of millimeter-sized thermoresponsive beads (m-beads) composed of a zwitterionic polysulfobetaine exhibiting upper critical solution temperature (UCST) behavior, crosslinked with biodegradable alginate via supramolecular ionic interactions with calcium ions in water. The fabricated m-beads are capable of encapsulating fluorescein and glufosinate ammonium pesticide with encapsulation efficiency greater than 99%. Promisingly, they exhibit enhanced release with an increasing amount of alginate in m-beads as well as at a temperature above the UCST. This work highlights the potential of UCST-type polysulfobetaine-based m-beads as a smart delivery platform, offering environmentally-triggered release of pesticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('089c946a-0c46-49b9-b1cb-6ad11e34660e', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Transgenic maize event TC1507: Global status of food, feed, and environmental safety', 'Baktavachalam GB, Delaney B, Fisher TL, Ladics GS, Layton RJ, Locke ME, Schmidt J, Anderson JA', 2015, 'GM crops & food', '10.1080/21645698.2015.1054093', 'https://doi.org/10.1080/21645698.2015.1054093', 'https://europepmc.org/articles/PMC5033190?pdf=render', NULL, NULL, 23, NULL, 'canada', 3, 'cc by-nc', 'Maize (Zea mays) is a widely cultivated cereal that has been safely consumed by humans and animals for centuries. Transgenic or genetically engineered insect-resistant and herbicide-tolerant maize, are commercially grown on a broad scale. Event TC1507 (OECD unique identifier: DAS-Ø15Ø7-1) or the Herculex®(#) I trait, an insect-resistant and herbicide-tolerant maize expressing Cry1F and PAT proteins, has been registered for commercial cultivation in the US since 2001. A science-based safety assessment was conducted on TC1507 prior to commercialization. The safety assessment addressed allergenicity; acute oral toxicity; subchronic toxicity; substantial equivalence with conventional comparators, as well as environmental impact. Results from biochemical, physicochemical, and in silico investigations supported the conclusion that Cry1F and PAT proteins are unlikely to be either allergenic or toxic to humans. Also, findings from toxicological and animal feeding studies supported that maize with TC1507 is as safe and nutritious as conventional maize. Maize with TC1507 is not expected to behave differently than conventional maize in terms of its potential for invasiveness, gene flow to wild and weedy relatives, or impact on non-target organisms. These safety conclusions regarding TC1507 were acknowledged by over 20 regulatory agencies including United States Environment Protection Agency (US EPA), US Department of Agriculture (USDA), Canadian Food Inspection Agency (CFIA), and European Food Safety Authority (EFSA) before authorizing cultivation and/or food and feed uses. A comprehensive review of the safety studies on TC1507, as well as some benefits, are presented here to serve as a reference for regulatory agencies and decision makers in other countries where authorization of TC1507 is or will be pursued.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c591b9b3-242d-41e8-bf62-00ee1dc64223', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'Validation of the International Weed Genomics Consortium genome annotation pipeline through reannotation of the model species Arabidopsis thaliana', 'Cutti L, da Silva Filho DF, Guadir Lara GE, Matheson J, Johnson NA, Montgomery J, Hall N, Murphy B', 2026, 'The plant genome', '10.1002/tpg2.70270', 'https://doi.org/10.1002/tpg2.70270', 'https://europepmc.org/articles/PMC13316137?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'The International Weed Genomics Consortium (IWGC) has sequenced and annotated the genomes of over 30 weed species, generating genomic resources to understand their biology, evolution, and adaptation. The objective of this study was to evaluate the semi-automated, isoform sequencing (Iso-seq)-based, IWGC genome annotation pipeline by reannotating the genome of the model species Arabidopsis thaliana with various amounts and types of extrinsic data and to measure the impact that varying inputs had on the annotation completeness and quality. Annotations were run comparing the effects of (1) the quantity and source of Iso-seq reads, (2) annotated proteins from botanically closely related or distantly related species, and (3) the number of proteins provided to the annotation program "MAKER-P." Reannotations were compared to each other and to the published annotation of the A. thaliana genome. The IWGC annotation pipeline annotated almost all the genes without manual curation when informed with an Iso-seq dataset and proteins of related species. In general, the pipeline produced more accurate, annotated genes with more input proteins, especially from closely related species, in the gene model prediction step. Furthermore, the combination of proteins from several closely related species increased the number of annotated genes. The number or source of Iso-seq reads did not have a significant effect if many proteins from closely related species were utilized. The annotation pipeline annotated nearly 90% of genes from additional crop species genomes. The IWGC genome annotation pipeline is robust in reannotating the A. thaliana genome and therefore is most likely performing well in the several non-model weed species it has been used on so far.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('951b0a11-8485-48be-b0f9-f57345d30610', '516cb083-e2a5-4ea5-be3c-8c36d6d55366', 'ZmNF-YB16 Overexpression Improves Drought Resistance and Yield by Enhancing Photosynthesis and the Antioxidant Capacity of Maize Plants', 'Wang B, Li Z, Ran Q, Li P, Peng Z, Zhang J', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00709', 'https://doi.org/10.3389/fpls.2018.00709', 'https://europepmc.org/articles/PMC5986874?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'ZmNF-YB16 is a basic NF-YB superfamily member and a member of a transcription factor complex composed of NF-YA, NF-YB, and NF-YC in maize. ZmNF-YB16 was transformed into the inbred maize line B104 to produce homozygous overexpression lines. ZmNF-YB16 overexpression improves dehydration and drought stress resistance in maize plants during vegetative and reproductive stages by maintaining higher photosynthesis and increases the maize grain yield under normal and drought stress conditions. Based on the examination of differentially expressed genes between the wild-type (WT) and transgenic lines by quantitative real time PCR (qRT-PCR), ZmNF-YB16 overexpression increased the expression of genes encoding antioxidant enzymes, the antioxidant synthase, and molecular chaperones associated with the endoplasmic reticulum (ER) stress response, and improved protection mechanism for photosynthesis system II. Plants that overexpression ZmNF-YB16 showed a higher rate of photosynthesis and antioxidant enzyme activity, better membrane stability and lower electrolyte leakage under control and drought stress conditions. These results suggested that ZmNF-YB16 played an important role in drought resistance in maize by regulating the expression of a number of genes involved in photosynthesis, the cellular antioxidant capacity and the ER stress response.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('67123118-6fb4-4969-8109-94b09a0ef56c', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'A Gemini Virus-Derived Autonomously Replicating System for HDR-Mediated Genome Editing of the EPSP Synthase Gene in Indica Rice', 'Borphukan B, Khatun M, Fartyal D, James D, Reddy MK', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14030477', 'https://doi.org/10.3390/plants14030477', 'https://europepmc.org/articles/PMC11821261?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'CRISPR/Cas9-mediated homology-directed repair (HDR) is a powerful tool for precise genome editing in plants, but its efficiency remains low, particularly for targeted amino acid substitutions or gene knock-ins. Successful HDR requires the simultaneous presence of Cas9, guide RNA, and a repair template (RT) in the same cell nucleus. Among these, the timely availability of the RT at the double-strand break (DSB) site is a critical bottleneck. To address this, we developed a sequential transformation strategy incorporating a deconstructed wheat dwarf virus (dWDV)-based autonomously replicating delivery system, effectively simplifying the process into a two-component system. Using this approach, we successfully achieved the targeted editing of the OsEPSPS gene in rice with a 10 percent HDR efficiency, generating three lines (TIPS1, TIPS2, and TIPS3) with amino acid substitutions (T172I and P177S) in the native EPSPS protein. The modifications were confirmed through Sanger sequencing and restriction digestion assays, and the edited lines showed no yield penalties compared to wild-type plants. This study demonstrates the utility of viral replicons in delivering gene-editing tools for precise genome modification, offering a promising approach for efficient HDR in crop improvement programs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('034dfe5c-4f1a-4918-b51b-442640661ce4', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Resistance to scald in barley lines or cultivars', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/resistance-to-scald-in-barley-lines-or-cultivars', 'https://open.alberta.ca/dataset/29dd34d6-9bf1-4a62-8233-9ec3782d2659/resource/e48317d1-a836-4719-bef8-88fad09ae4aa/download/0163010146799-resistance-to-scald-in-barley-lines-or-cultivars.pdf', NULL, NULL, 110, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project assessed the severity of scald in barley across multiple regional testing sites in Alberta from 1992 to 1994. Researchers observed variation in scald incidence among sites, with Lacombe generally showing higher severity than others. Field and greenhouse screening trials evaluated advanced barley lines, including materials imported from the International Centre for Maize and Wheat Improvement (CIMMYT), for resistance to scald and net blotch. Several lines demonstrated adult resistance, although the genetic basis for resistance remains unclear. Attempts to assess resistance based on lesion shape and size did not reveal consistent differences among cultivars.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c65c2b1-d032-415e-ace1-194e49c32c5c', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'ABC transporters linked to multiple herbicide resistance in blackgrass (Alopecurus myosuroides)', 'Goldberg-Cavalleri A, Onkokesung N, Franco-Ortega S, Edwards R', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1082761', 'https://doi.org/10.3389/fpls.2023.1082761', 'https://europepmc.org/articles/PMC10063862?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Enhanced detoxification is a prominent mechanism protecting plants from toxic xenobiotics and endows resistance to diverse herbicide chemistries in grass weeds such as blackgrass (Alopecurus myosuroides). The roles of enzyme families which impart enhanced metabolic resistance (EMR) to herbicides through hydroxylation (phase 1 metabolism) and/or conjugation with glutathione or sugars (phase 2) have been well established. However, the functional importance of herbicide metabolite compartmentalisation into the vacuole as promoted by active transport (phase 3), has received little attention as an EMR mechanism. ATP-binding cassette (ABC) transporters are known to be important in drug detoxification in fungi and mammals. In this study, we identified three distinct C-class ABCCs transporters namely AmABCC1, AmABCC2 and AmABCC3 in populations of blackgrass exhibiting EMR and resistance to multiple herbicides. Uptake studies with monochlorobimane in root cells, showed that the EMR blackgrass had an enhanced capacity to compartmentalize fluorescent glutathione-bimane conjugated metabolites in an energy-dependent manner. Subcellular localisation analysis using transient expression of GFP-tagged AmABCC2 assays in Nicotiana demonstrated that the transporter was a membrane bound protein associated with the tonoplast. At the transcript level, as compared with herbicide sensitive plants, AmABCC1 and AmABCC2 were positively correlated with EMR in herbicide resistant blackgrass being co-expressed with AmGSTU2a, a glutathione transferase (GST) involved in herbicide detoxification linked to resistance. As the glutathione conjugates generated by GSTs are classic ligands for ABC proteins, this co-expression suggested AmGSTU2a and the two ABCC transporters delivered the coupled rapid phase 2/3 detoxification observed in EMR. A role for the transporters in resistance was further confirmed in transgenic yeast by demonstrating that the expression of either AmABCC1 or AmABCC2, promoted enhanced tolerance to the sulfonylurea herbicide, mesosulfuron-methyl. Our results link the expression of ABCC transporters to enhanced metabolic resistance in blackgrass through their ability to transport herbicides, and their metabolites, into the vacuole.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fea2a6e2-7f1f-4c55-8024-3c623fd20b0e', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Agriculture without paraquat is feasible without loss of productivity-lessons learned from phasing out a highly hazardous herbicide', 'Stuart AM, Merfield CN, Horgan FG, Willis S, Watts MA, Ramírez-Muñoz F, U JS, Utyasheva L', 2023, 'Environmental science and pollution research international', '10.1007/s11356-022-24951-0', 'https://doi.org/10.1007/s11356-022-24951-0', 'https://europepmc.org/articles/PMC9928820?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'A small proportion of the thousands of pesticides on the market today are associated with a disproportionately high incidence of severe acute pesticide poisoning and suicide. Paraquat stands out as one of the most lethal pesticides in common use, frequently involved in fatal incidents due to suicides or accidental exposure. Even though paraquat has been banned in over 67 countries, it is still widely used in many others, particularly in Asia and Latin America. Based on a literature review and consultations, this paper identifies options for replacing paraquat and distils practical lessons from numerous successes around the world. Our aim is to support regulators, policymakers, agronomists and the supply chain sector with practical information related to phasing out paraquat. Production data consistently failed to show any negative effects of banning paraquat on agricultural productivity. A wide range of alternative approaches to weed management and crop defoliation are available, many of which do not rely on herbicides. Over 1.25 million farmers in low- and middle-income countries (LMICs) successfully produce a range of crops for private voluntary standards (PVS) in food and fiber supply chains which prohibit paraquat use. We conclude from the findings of this study that eliminating paraquat will save lives without reducing agricultural productivity. Less hazardous and more sustainable alternatives exist. To enhance successful adoption and uptake of these methods on a wide scale, farmers require training and support within an enabling policy environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('15d1e0d2-2d6e-4027-bcfb-e07f2a687a92', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Bt maize can provide non-chemical pest control and enhance food safety in China', 'Yang X, Zhao S, Liu B, Gao Y, Hu C, Li W, Yang Y, Li G', 2023, 'Plant biotechnology journal', '10.1111/pbi.13960', 'https://doi.org/10.1111/pbi.13960', 'https://europepmc.org/articles/PMC9884019?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by-nc', 'China is the world''s second-largest maize producer and consumer. In recent years, the invasive fall armyworm Spodoptera frugiperda (J.E. Smith) has adversely affected maize productivity and compromised food security. To mitigate pest-inflicted food shortages, China''s Government issued biosafety certificates for two genetically modified (GM) Bt maize hybrids, Bt-Cry1Ab DBN9936 and Bt-Cry1Ab/Cry2Aj Ruifeng 125, in 2019. Here, we quantitatively assess the impact of both Bt maize hybrids on pest feeding damage, crop yield and food safety throughout China''s maize belt. Without a need to resort to synthetic insecticides, Bt maize could mitigate lepidopteran pest pressure by 61.9-97.3%, avoid yield loss by 16.4-21.3% (range -11.9-99.2%) and lower mycotoxin contamination by 85.5-95.5% as compared to the prevailing non-Bt hybrids. Yield loss avoidance varied considerably between experimental sites and years, as mediated by on-site infestation pressure and pest identity. For either seed mixtures or block refuge arrangements, pest pressure was kept below established thresholds at 90% Bt maize coverage in Yunnan (where S. frugiperda was the dominant species) and 70% Bt maize coverage in other sites dominated by Helicoverpa armigera (Hübner) and Ostrinia furnacalis (Guenée). Drawing on experiences from other crop/pest systems, Bt maize in se can provide area-wide pest management and thus, contribute to a progressive phase-down of chemical pesticide use. Hence, when consciously paired with agroecological and biodiversity-based measures, GM insecticidal crops can ensure food and nutrition security, contribute to the sustainable intensification of China''s agriculture and reduce food systems'' environmental footprint.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c1c84ba7-9a2f-449c-95a6-4fd1021f316f', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Confirmation of glyphosate-resistant waterhemp (Amaranthus tuberculatus) in New York', 'Vipan Kumar, Jatinder Aulakh, Mike Stanyard, Mike Hunter, Bryan Brown, Lynn Sosnoskie, Amit J. Jhala', 2025, 'Weed Technology', '10.1017/wet.2024.104', 'https://doi.org/10.1017/wet.2024.104', 'https://www.cambridge.org/core/product/identifier/S0890037X24001040/type/journal_article', NULL, NULL, 7, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Waterhemp has become a serious management challenge for field crop growers in New York. Two putative glyphosate-resistant (GR) waterhemp populations (NY1 and NY2) were collected in 2023 from two soybean fields in Seneca County, NY. The objectives of this research were to 1) confirm and characterize the level of glyphosate resistance in waterhemp populations from New York relative to a known glyphosate-susceptible population from Nebraska (NE_SUS), and 2) evaluate the efficacy of various postemergence herbicides for GR waterhemp control. Based on the shoot dry weight reductions (GR50 values) in a dose-response study, the NY1 and NY2 populations exhibited 5.6- to 8.3-fold resistance to glyphosate compared with the NE_SUS population. In a separate study, postemergence herbicides such as dicamba, glufosinate, lactofen, and 2,4-D applied alone or in a mixture with glyphosate or glufosinate had provided 89% to 99% control and ≥97% shoot dry weight reduction of NY1 and NY2 populations 21 d after treatment. Greater than 98% control of the NE_SUS population was achieved with tested postemergence herbicides, except mesotrione (62% control). Furthermore, atrazine, chlorimuron + thifensulfuron, and mesotrione were the least effective in controlling NY1 and NY2 populations (42% to 59% control and 50% to 67% shoot dry weight reductions, respectively). These results confirm the first report of GR waterhemp in New York. Growers should adopt effective alternative postemergence herbicides tested in this study to manage GR waterhemp.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2249d231-6ffa-4be7-9627-42b7556e2846', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Effectiveness of 2,4-D/dicamba/dichlorprop-p premixture for controlling glyphosate-resistant kochia (Bassia scoparia L.) in Central Great Plains', 'Sachin Dhanda, Vipan Kumar', NULL, 'Weed Technology', '10.1017/wet.2026.10098', 'https://doi.org/10.1017/wet.2026.10098', 'https://www.cambridge.org/core/product/identifier/S0890037X26100980/type/journal_article', NULL, NULL, 5, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Widespread evolution of glyphosate resistance among kochia populations is a serious challenge for growers across the North American Great Plains. Dicamba has historically been used to control glyphosate-resistant (Gly-R) kochia. However, the increasing spread of dicamba-resistant kochia and current restrictions on dicamba use (low volatile formulations) warrant alternative herbicide options to control Gly-R kochia. In this context, field-based dose response experiments were conducted in fallow at Kansas State University Agricultural Research Center, Hays, KS, during 2021 and 2022 to determine and compare the effectiveness of 2,4-D, dicamba, and dichlorprop-p applied alone, and in a premixture of 2,4-D/dicamba/dichlorprop-p for controlling Gly-R kochia. Averaged across two years, results indicated that substantially lower doses of 2,4-D, dicamba, and dichlorprop-p were required in a premixture to achieve effective control of Gly-R kochia compared with their standalone applications. Specifically, the ED90 values for Gly-R kochia control were reduced by 90-, 4-, and 6-times for 2,4-D, dicamba, and dichlorprop-p, respectively, when applied as a premixture. Similarly, achieving 90% biomass reduction required approximately 1021-, 3-, and 4-times lower doses of 2,4-D, dicamba, and dichlorprop-p, respectively, in the premixture than when applied alone. Altogether, these results demonstrated that the premixture of 2,4-D/dicamba/dichlorprop-p can be an effective alternative for managing Gly-R kochia in fallow. The reduced dose requirements in a premixture also suggested potential benefits for resistance management, cost efficiency, and environmental stewardship.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('edfb5be1-93f8-48f5-8b96-ae74be397143', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Genetic Engineering for Enhancing Sugarcane Tolerance to Biotic and Abiotic Stresses', 'Kumar T, Wang JG, Xu CH, Lu X, Mao J, Lin XQ, Kong CY, Li CJ', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13131739', 'https://doi.org/10.3390/plants13131739', 'https://europepmc.org/articles/PMC11244436?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Sugarcane, a vital cash crop, contributes significantly to the world''s sugar supply and raw materials for biofuel production, playing a significant role in the global sugar industry. However, sustainable productivity is severely hampered by biotic and abiotic stressors. Genetic engineering has been used to transfer useful genes into sugarcane plants to improve desirable traits and has emerged as a basic and applied research method to maintain growth and productivity under different adverse environmental conditions. However, the use of transgenic approaches remains contentious and requires rigorous experimental methods to address biosafety challenges. Clustered regularly interspaced short palindromic repeat (CRISPR) mediated genome editing technology is growing rapidly and may revolutionize sugarcane production. This review aims to explore innovative genetic engineering techniques and their successful application in developing sugarcane cultivars with enhanced resistance to biotic and abiotic stresses to produce superior sugarcane cultivars.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4eb0d7d8-566f-467d-a76c-6ecd4572b446', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Effects of nitrogen fertilization and a commercial arbuscular mycorrhizal fungal inoculant on root rot and agronomic production of pea and lentil crops', 'Hubbard M, Thomson M, Menun A, May WE, Peng G, Bainard LD', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1120435', 'https://doi.org/10.3389/fpls.2023.1120435', 'https://europepmc.org/articles/PMC10420092?pdf=render', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by', 'In the Canadian prairies, pulse crops such as field pea (Pisum sativum L.) and lentil (Lens culinaris L.) are economically important and widely grown. However, in recent years, root rot, caused by a variety of fungal and oomycete pathogens, including Aphanomyces euteiches, has become a limiting factor on yield. In this study, we examined the impacts of nitrogen (N) fertilization and a commercial arbuscular mycorrhizal fungal (AMF) inoculant on pea and lentil plant health and agronomic production at three locations in Saskatchewan: Swift Current, Indian Head and Melfort. The AMF inoculation had no impact on root rot severity, and therefore is not considered a reliable method to manage root rot in pea and lentil. In contrast, N fertilization led to reductions in root rot in Swift Current, but not the other two sites. However, N fertilization did reduce nodulation. When both pea and lentil are considered, the abundance of A. euteiches in soil increased from pre-seeding to mid-bloom. A negative correlation between soil pH and disease severity was also observed. The high between-site variability highlights the importance of testing root rot mitigation strategies under multiple soil conditions to develop site-specific recommendations. Use of N fertilizer as a root rot management strategy merits further exploration, including investigation into its interactions with other management strategies, soil properties, and costs and benefits.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa5fae88-696f-4b0b-8d2c-7ccd3e08ecc6', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Efficacy and cost of four plant-derived, natural herbicides for certified organic agriculture', 'Appleby AB, Reganold JP, Carpenter-Boggs LA', 2025, 'Pest management science', '10.1002/ps.8711', 'https://doi.org/10.1002/ps.8711', 'https://europepmc.org/articles/PMC12074622?pdf=render', NULL, NULL, 12, NULL, 'canada', 3, 'cc by-nc-nd', 'BackgroundWeed management is the greatest production challenge for most certified organic farmers, with few herbicides allowed on organic farms. Here, we compared the efficacy and cost of handhoeing (MECH) with a control (no weed management) and four commercially available registered organic herbicides under United States Department of Agriculture organic standards in managing Canada thistle (Cirsium arvense (L.) Scop.) and total vegetative cover in two apple (Malus domestica Borkh.) orchards. The four herbicide treatments had the following active ingredients: capric and caprylic acid (CAP), d-limonene (LIM), acetic and citric acid (ACET), and clove and cinnamon oil (CIN). In separate greenhouse trials, Canada thistle response to CAP (at two concentrations), LIM, glyphosate (GLY), and MECH were also studied.ResultsAll materials reduced weed cover by 48% or more 72 h after treatment in the orchard trials; CAP performed best, reducing weed cover by 88% in 1 h and 98% in 72 h. CAP and LIM reduced early season, perennial weed cover after 3 years of repeated applications in an organic orchard; a single application of CAP and LIM would cost on average US$769.50 ha-1 less and US$203.50 ha-1 less than MECH at US$12.00 h-1 wage respectively, with similar efficacies. In greenhouse trials, CAP mixed to 7.11% v/v and 4.74% v/v active ingredient were equally effective at removing weed cover compared with MECH, further reducing the cost of a single application of CAP by US$122.ConclusionAdding effective, next-generation, natural herbicides, such as CAP and LIM, to existing weed management strategies may allow organic producers to reduce weed pressure, till less, and improve profitability, while providing conventional producers options to combat herbicide-resistant weeds. © 2025 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('784b34cb-ccb4-4135-9808-2af26dbce686', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Evaluating weed control in dicamba, glyphosate, and glufosinate-resistant sugar beet in the western United States', 'Abraham Akuoko, Albert Adjesiwor, Joel Felix, Andrew Kniss, Nevin Lawrence', 2026, 'Weed Technology', '10.1017/wet.2025.10077', 'https://doi.org/10.1017/wet.2025.10077', 'https://www.cambridge.org/core/product/identifier/S0890037X25100778/type/journal_article', NULL, NULL, 8, NULL, 'canada', 3, 'open access (DOAJ)', 'Sugar beet with three-way resistance to dicamba, glufosinate, and glyphosate may provide sugar beet growers with additional herbicide options for management of glyphosate-resistant (GR) weed species such as Palmer amaranth and kochia. Field trials were conducted near Scottsbluff, Nebraska; Lingle, Wyoming; Kimberly, Idaho; and Ontario, Oregon in 2023, to compare the effectiveness of dicamba (549 g ae ha−1) + glyphosate (1,260 g ae ha−1) applied preemergence, and postemergence combinations of dicamba + glyphosate, glyphosate, and glufosinate (656 g ai ha−1) to manage weeds in sugar beet crops. Common lambsquarters, redroot pigweed, and GR kochia were present at the Idaho, Oregon, and Wyoming locations; and common lambsquarters and GR Palmer amaranth were present in Nebraska. Dicamba + glyphosate applied preemergence reduced common lambsquarters, redroot pigweed, and GR kochia compared with glyphosate applied alone. Common lambsquarters density was higher in plots where glufosinate had been applied early postemergence compared with dicamba + glyphosate and glyphosate applied alone. Glufosinate and dicamba + glyphosate applied early or late postemergence reduced GR Palmer amaranth density relative to glyphosate alone applied early or late postemergence. Postemergence applications had no significant effect on redroot pigweed or GR kochia density. Based on the findings of this research, sugar beet with three-way resistance to dicamba, glufosinate, and glyphosate will bring two additional sites of action to be used both preemergence and postemergence, providing improved weed control compared to currently available technology.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e120d75c-3f3c-4a23-ab97-d1576a62eb7d', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Expression of a Cytochrome P450 Gene from Bermuda Grass Cynodon dactylon in Soybean Confers Tolerance to Multiple Herbicides', 'Zheng T, Yu X, Sun Y, Zhang Q, Zhang X, Tang M, Lin C, Shen Z', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11070949', 'https://doi.org/10.3390/plants11070949', 'https://europepmc.org/articles/PMC9002376?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Bermuda grass (Cynodon dactylon) is notoriously difficult to control with some commonly used herbicides. We cloned a cytochrome P450 gene from Bermuda grass, named P450-N-Z1, which was found to confer tolerance to multiple herbicides in transgenic Arabidopsis. These herbicides include: (1) acetolactate synthase (ALS) inhibitor herbicides nicosulfuron and penoxsulam; (2) p-hydroxyphenylpyruvate dioxygenase (HPPD)-inhibiting herbicide mesotrione; (3) synthetic auxin herbicide dicamba; (4) photosynthesis inhibitor bentazon. We further generated transgenic soybean plants expressing P450-N-Z1, and found that these transgenic soybean plants gained robust tolerance to nicosulfuron, flazasulfuron, and 2,4-dichlorophenoxyacetic acid (2,4-D) in greenhouse assays. A field trial demonstrated that transgenic soybean is tolerant to flazasulfuron and 2,4-D at 4-fold and 2-fold the recommended rates, respectively. Furthermore, we also demonstrated that flazasulfuron and dicamba are much more rapidly degraded in vivo in the transgenic soybean than in non-transgenic soybean. Therefore, P450-N-Z1 may be utilized for engineering transgenic crops for herbicide tolerance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('641ce050-b73d-442f-b2d8-3b12621d98b6', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Functional synergy and genomic linkage of glyphosate resistance traits in Canada fleabane', 'Page ER, Martin SL, Meloche S, Thibodeau A, Laforest M', 2026, 'Pest management science', '10.1002/ps.70194', 'https://doi.org/10.1002/ps.70194', 'https://europepmc.org/articles/PMC12713706?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by', 'BackgroundGlyphosate resistance in Conyza canadensis (Canada fleabane) has been primarily attributed to non-target-site resistance (NTSR) mechanisms such as vacuolar sequestration, though these have not been formally elucidated. While a target-site mutation at EPSPS2 (P106S) was recently identified, it failed to account for many resistant cases. These findings underscore the need to re-evaluate the genetic basis of glyphosate resistance in this species.ResultsUsing an F2 population derived from glyphosate-resistant and susceptible biotypes, we disentangled the individual and combined effects of target-site resistance (TSR) and NTSR. Dose-response phenotyping and genotyping revealed that NTSR conferred broad protection across a wide range of glyphosate doses, while TSR provided a more limited, dose-dependent benefit. When both mechanisms were present, median lethal dose (LD50) values greatly exceeded additive expectations, indicating a synergistic interaction. Quantitative trait locus (QTL) mapping identified a major-effect locus associated with NTSR on chromosome 4, with candidate genes linked to membrane transport and subcellular compartmentalization processes. Segregation distortion and recombination frequency estimates suggest moderate genetic linkage between TSR and NTSR loci, facilitating co-inheritance of resistance alleles.ConclusionThis study provides the first explicit quantitative analysis of gene × gene interactions underlying herbicide resistance in C. canadensis. By disentangling TSR and NTSR, we show that single copies of the TSR and NTSR alleles confer approximately nine-fold and seven-fold glyphosate resistance, respectively. When combined, these mechanisms exhibit synergism, resulting in resistance levels that exceed additive LD50 expectations by more than two-fold. Both TSR and NTSR loci have been mapped to chromosome 4, and moderate genomic linkage (~27% recombination) between them will likely contribute to the persistence and spread of high-level resistance, even under low selection pressure. © 2025 His Majesty the King in Right of Canada. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry. Reproduced with the permission of the Minister of Agriculture and Agri-Food Canada.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cd22de73-98dc-4369-b8be-f38fe1319520', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Genetic Transformation of Sugarcane, Current Status and Future Prospects', 'Budeguer F, Enrique R, Perera MF, Racedo J, Castagnaro AP, Noguera AS, Welin B', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.768609', 'https://doi.org/10.3389/fpls.2021.768609', 'https://europepmc.org/articles/PMC8632530?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Sugarcane (Saccharum spp.) is a tropical and sub-tropical, vegetative-propagated crop that contributes to approximately 80% of the sugar and 40% of the world''s biofuel production. Modern sugarcane cultivars are highly polyploid and aneuploid hybrids with extremely large genomes (>10 Gigabases), that have originated from artificial crosses between the two species, Saccharum officinarum and S. spontaneum. The genetic complexity and low fertility of sugarcane under natural growing conditions make traditional breeding improvement extremely laborious, costly and time-consuming. This, together with its vegetative propagation, which allows for stable transfer and multiplication of transgenes, make sugarcane a good candidate for crop improvement through genetic engineering. Genetic transformation has the potential to improve economically important properties in sugarcane as well as diversify sugarcane beyond traditional applications, such as sucrose production. Traits such as herbicide, disease and insect resistance, improved tolerance to cold, salt and drought and accumulation of sugar and biomass have been some of the areas of interest as far as the application of transgenic sugarcane is concerned. Although there have been much interest in developing transgenic sugarcane there are only three officially approved varieties for commercialization, all of them expressing insect-resistance and recently released in Brazil. Since the early 1990''s, different genetic transformation systems have been successfully developed in sugarcane, including electroporation, Agrobacterium tumefaciens and biobalistics. However, genetic transformation of sugarcane is a very laborious process, which relies heavily on intensive and sophisticated tissue culture and plant generation procedures that must be optimized for each new genotype to be transformed. Therefore, it remains a great technical challenge to develop an efficient transformation protocol for any sugarcane variety that has not been previously transformed. Additionally, once a transgenic event is obtained, molecular studies required for a commercial release by regulatory authorities, which include transgene insertion site, number of transgenes and gene expression levels, are all hindered by the genomic complexity and the lack of a complete sequenced reference genome for this crop. The objective of this review is to summarize current techniques and state of the art in sugarcane transformation and provide information on existing and future sugarcane improvement by genetic engineering.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eeb2a4c8-ff0f-4951-acef-2cf9a25fedce', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Glyphosate effects on plant mineral nutrition, crop rhizosphere microbiota, and plant disease in glyphosate-resistant crops', 'Duke SO, Lydon J, Koskinen WC, Moorman TB, Chaney RL, Hammerschmidt R', 2012, 'Journal of agricultural and food chemistry', '10.1021/jf302436u', 'https://doi.org/10.1021/jf302436u', 'https://europepmc.org/articles/PMC3479986?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'open access (Europe PMC)', 'Claims have been made recently that glyphosate-resistant (GR) crops sometimes have mineral deficiencies and increased plant disease. This review evaluates the literature that is germane to these claims. Our conclusions are: (1) although there is conflicting literature on the effects of glyphosate on mineral nutrition on GR crops, most of the literature indicates that mineral nutrition in GR crops is not affected by either the GR trait or by application of glyphosate; (2) most of the available data support the view that neither the GR transgenes nor glyphosate use in GR crops increases crop disease; and (3) yield data on GR crops do not support the hypotheses that there are substantive mineral nutrition or disease problems that are specific to GR crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ef28eeeb-7ee1-40e8-9a8b-755ebada5138', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Glyphosate Separating and Sensing for Precision Agriculture and Environmental Protection in the Era of Smart Materials', 'Mazuryk J, Klepacka K, Kutner W, Sharma PS', 2023, 'Environmental science & technology', '10.1021/acs.est.3c01269', 'https://doi.org/10.1021/acs.est.3c01269', 'https://europepmc.org/articles/PMC10339735?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'The present article critically and comprehensively reviews the most recent reports on smart sensors for determining glyphosate (GLP), an active agent of GLP-based herbicides (GBHs) traditionally used in agriculture over the past decades. Commercialized in 1974, GBHs have now reached 350 million hectares of crops in over 140 countries with an annual turnover of 11 billion USD worldwide. However, rolling exploitation of GLP and GBHs in the last decades has led to environmental pollution, animal intoxication, bacterial resistance, and sustained occupational exposure of the herbicide of farm and companies'' workers. Intoxication with these herbicides dysregulates the microbiome-gut-brain axis, cholinergic neurotransmission, and endocrine system, causing paralytic ileus, hyperkalemia, oliguria, pulmonary edema, and cardiogenic shock. Precision agriculture, i.e., an (information technology)-enhanced approach to crop management, including a site-specific determination of agrochemicals, derives from the benefits of smart materials (SMs), data science, and nanosensors. Those typically feature fluorescent molecularly imprinted polymers or immunochemical aptamer artificial receptors integrated with electrochemical transducers. Fabricated as portable or wearable lab-on-chips, smartphones, and soft robotics and connected with SM-based devices that provide machine learning algorithms and online databases, they integrate, process, analyze, and interpret massive amounts of spatiotemporal data in a user-friendly and decision-making manner. Exploited for the ultrasensitive determination of toxins, including GLP, they will become practical tools in farmlands and point-of-care testing. Expectedly, smart sensors can be used for personalized diagnostics, real-time water, food, soil, and air quality monitoring, site-specific herbicide management, and crop control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b8a98fe2-9d6d-485e-8aec-c2adf6e81c01', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Glyphosate treatments for managing successional dynamics in beech bark disease-affected northern hardwood forests', 'Givelas M, Gorgolewski A, Duckett C, Martin AR', 2025, 'PloS one', '10.1371/journal.pone.0336126', 'https://doi.org/10.1371/journal.pone.0336126', 'https://europepmc.org/articles/PMC12617849?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by', 'The spread of beech bark disease (BBD) in northern tolerant hardwood forests poses a significant forest management challenge. Extensive aboveground mortality in BBD-affected stands often leads to the rapid formation of high-density American beech (Fagus grandifolia Ehrh.) thickets, primarily driven by vegetative regeneration through root sprouting. These thickets can outcompete desirable species such as sugar maple (Acer saccharum L.), and negatively impact long-term forest structure and functions. This study evaluated the efficacy of post-harvest herbicide treatments-specifically the application of glyphosate to recently cut stumps and the use of "hack-and-squirt" application techniques on standing beech-to suppress vegetative beech regeneration. Over five years, beech regeneration was significantly lower in treatment plots, averaging 904 stems ha ⁻ ¹ (95% CI: 433-1,378 stems ha ⁻ ¹), compared to 1,741 stems ha-¹ (95% CI: 1,286-2,193 stems ha ⁻ ¹) in untreated control plots. Additionally, by five years post-harvest, glyphosate-treated plots supported higher densities of desirable tree species such as sugar maple, indicating that the intervention shifted species composition by reducing beech dominance. However this method had no significant effect on overall tree species richness or diversity, so while these treatments effectively suppress beech regeneration and promote successional trajectories in hardwood forests, they do not reduce tree diversity. By alleviating the competitive dominance of beech thickets, this management strategy is likely to mitigate the ecological and economic impacts associated with BBD, while maintaining or enhancing desirable tree species diversity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2c723c10-d657-4cf4-a5a2-39a43a7586c4', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Herbicide Resistance Management: Recent Developments and Trends', 'Beckie HJ, Ashworth MB, Flower KC', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8060161', 'https://doi.org/10.3390/plants8060161', 'https://europepmc.org/articles/PMC6631825?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'This review covers recent developments and trends in herbicide-resistant (HR) weed management in agronomic field crops. In countries where input-intensive agriculture is practiced, these developments and trends over the past decade include renewed efforts by the agrichemical industry in herbicide discovery, cultivation of crops with combined (stacked) HR traits, increasing reliance on preemergence vs. postemergence herbicides, breeding for weed-competitive crop cultivars, expansion of harvest weed seed control practices, and advances in site-specific or precision weed management. The unifying framework or strategy underlying these developments and trends is mitigation of viable weed seeds into the soil seed bank and maintaining low weed seed banks to minimize population proliferation, evolution of resistance to additional herbicidal sites of action, and spread. A key question going forward is: how much weed control is enough to consistently achieve the goal of low weed seed banks? The vision for future HR weed management programs must be sustained crop production and profitability with reduced herbicide (particularly glyphosate) dependency.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a08ae6ae-502a-4ecc-a48b-154dfa3db4cc', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Increasing crop diversity mitigates weather variations and improves yield stability', 'Gaudin AC, Tolhurst TN, Ker AP, Janovicek K, Tortora C, Martin RC, Deen W', 2015, 'PloS one', '10.1371/journal.pone.0113261', 'https://doi.org/10.1371/journal.pone.0113261', 'https://europepmc.org/articles/PMC4320064?pdf=render', NULL, NULL, 20, NULL, 'canada', 3, 'cc by', 'Cropping sequence diversification provides a systems approach to reduce yield variations and improve resilience to multiple environmental stresses. Yield advantages of more diverse crop rotations and their synergistic effects with reduced tillage are well documented, but few studies have quantified the impact of these management practices on yields and their stability when soil moisture is limiting or in excess. Using yield and weather data obtained from a 31-year long term rotation and tillage trial in Ontario, we tested whether crop rotation diversity is associated with greater yield stability when abnormal weather conditions occur. We used parametric and non-parametric approaches to quantify the impact of rotation diversity (monocrop, 2-crops, 3-crops without or with one or two legume cover crops) and tillage (conventional or reduced tillage) on yield probabilities and the benefits of crop diversity under different soil moisture and temperature scenarios. Although the magnitude of rotation benefits varied with crops, weather patterns and tillage, yield stability significantly increased when corn and soybean were integrated into more diverse rotations. Introducing small grains into short corn-soybean rotation was enough to provide substantial benefits on long-term soybean yields and their stability while the effects on corn were mostly associated with the temporal niche provided by small grains for underseeded red clover or alfalfa. Crop diversification strategies increased the probability of harnessing favorable growing conditions while decreasing the risk of crop failure. In hot and dry years, diversification of corn-soybean rotations and reduced tillage increased yield by 7% and 22% for corn and soybean respectively. Given the additional advantages associated with cropping system diversification, such a strategy provides a more comprehensive approach to lowering yield variability and improving the resilience of cropping systems to multiple environmental stresses. This could help to sustain future yield levels in challenging production environments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe0f9d8e-ca53-4710-9374-fc43a161ada1', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Industrial hemp biomass negatively affected by herbicide drift from corn and soybean herbicides', 'Zaric M, Canella Vieira B, Houston B, Sousa Alves G, Wortman SE, Peterson J, Kruger GR', 2024, 'Scientific reports', '10.1038/s41598-024-78209-5', 'https://doi.org/10.1038/s41598-024-78209-5', 'https://europepmc.org/articles/PMC11568321?pdf=render', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by', 'The establishment of industrial hemp (Cannabis sativa L.) fields near row crops has raised concerns about the potential adverse effects of herbicide drift on hemp production. This study examined hemp susceptibility to drift of herbicides registered for use in corn and/or soybeans. Herbicide solutions (2,4-D, dicamba, glufosinate, glyphosate, imazethapyr, lactofen, mesotrione) were applied separately in the wind tunnel (3.6 m s-1 airspeed), simulating drift scenarios, with conventional TP95015EVS (TP) and air inclusion AI95015EVS (AI) flat fan nozzles calibrated to deliver 140 L ha-1 carrier volume at 230 kPa. Mylar cards and hemp plants (20-25 cm tall) were placed downwind up to 12 m. Spray deposition from mylar cards was quantified using fluorometry and hemp biomass was collected 21 post application. Results indicated the nozzle design influenced downwind deposition; 5% of spray deposits from the TP nozzle reached 5.9 m downwind versus 2.0 m for the AI nozzle. Glyphosate, glufosinate, and mesotrione caused the highest biomass reductions, with 50% reductions observed at 19.3 (inferred), 8.7, and 9.3 m downwind for TP nozzle, and 4.1, 4.0, and 2.9 m for AI nozzle. These findings suggest herbicide applications at airspeeds of 3.6 m s-1 or greater present a risk to nearby hemp fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('513f7a0c-01dc-494f-9101-6801ce05830c', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Insecticide application timing effects on alfalfa insect communities', 'McClure M, Herreid J, Jabbour R', 2023, 'Journal of economic entomology', '10.1093/jee/toad071', 'https://doi.org/10.1093/jee/toad071', 'https://europepmc.org/articles/PMC10263263?pdf=render', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc by', 'Timing of insecticide application can impact efficacy, given variation in both weather and development of the crop and its insect pests. Both target and nontarget insects may vary in life stage and abundance at the time of application. In alfalfa Medicago sativa L. cropping systems, producers have interest in early-season insecticide applications to eliminate last-minute decisions about preharvest applications for alfalfa weevil Hypera postica (Gyllenhal) (Coleoptera: Curculionidae). The standard recommendation is based on scouting larvae close to the first harvest time. We compared early and standard timing of application of a lambda-cyhalothrin pyrethroid on alfalfa pest and beneficial insects. Field trials at a university research farm were conducted in 2020 and 2021. In 2020, early application was as effective as the standard timing against alfalfa weevil, as compared to the untreated control, but less effective than the standard timing in 2021. Effects of timing against Lygus bugs (Hemiptera: Miridae), grasshoppers (Orthoptera: Acrididae), and aphids (Hemiptera: Aphididae) were inconsistent between years. We observed the potential for early application to reduce negative impacts on ladybird beetles (Coleoptera: Coccinellidae) and spiders (Araneae), however, damsel bugs (Hemiptera: Nabidae) were similarly reduced by insecticide application regardless of timing. Overall arthropod community composition differed by both year and treatment. Future research should explore potential trade-offs of spray timing at larger spatial scales.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('38a1e26a-b6bc-4f05-bad7-e3c801151068', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Interaction of 2,4-D or Dicamba with Glufosinate for Control of Glyphosate-Resistant Giant Ragweed (Ambrosia trifida L.) in Glufosinate-Resistant Maize (Zea mays L.)', 'Zahoor A. Ganie, Amit J. Jhala', 2017, 'Frontiers in Plant Science', '10.3389/fpls.2017.01207', 'https://doi.org/10.3389/fpls.2017.01207', 'http://journal.frontiersin.org/article/10.3389/fpls.2017.01207/full', NULL, NULL, 10, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Glyphosate-resistant (GR) giant ragweed is a problematic broadleaf weed in crops including maize and soybean in the Midwestern United States. Commercialization of crops with 2,4-D or dicamba and glufosinate resistance will allow post-emergence (POST) applications of these herbicides. Therefore, information is needed on how 2,4-D/dicamba will interact with glufosinate in various rate combinations. The objectives of this study were to evaluate the interaction of glufosinate plus 2,4-D and/or dicamba for control of GR giant ragweed, and to determine their effect on GR giant ragweed density, biomass, maize injury, and yield. Field experiments were conducted in 2013 and 2014 in a field infested with GR giant ragweed in Nebraska, United States. The treatments included POST applications of glufosinate (450 or 590 g ai ha-1), 2,4-D, or dicamba at 280 or 560 g ae ha-1 applied alone and in tank-mixtures in glufosinate-resistant maize. The results showed that dicamba applied alone resulted in 56 to 62% and 73 to 83% control at 14 and 28 days after treatment (DAT), respectively, and ≥95% control at 60 DAT or at harvest compared to 17 to 30% and 57 to 73% control with 2,4-D applied alone at 280 and 560 g ai ha-1, respectively. Glufosinate tank-mixed with 2,4-D and/or dicamba consistently provided ≥89% control of GR giant ragweed, except that control with glufosinate plus 2,4-D varied from 80 to 92% at 60 DAT and at harvest. The comparison between the observed and expected control (determined by Colby’s equation) suggested an additive interaction between glufosinate and 2,4-D or dicamba for control of GR giant ragweed. Contrast analysis also indicated that GR giant ragweed control with glufosinate plus 2,4-D or dicamba was either consistently higher or comparable with individual herbicides excluding 2,4-D applied alone. Herbicide programs, excluding 2,4-D at 280 g ae ha-1, resulted in ≥80% reduction in GR giant ragweed density. Tank-mixing glufosinate with 2,4-D or dicamba showed an additive effect and will be an additional tool with two effective modes of action for the management of GR giant ragweed in maize.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('045e262e-db83-4e6c-a8a4-d00a14ccb34e', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Screening and Selection for Herbicide Tolerance among Diverse Tomato Germplasms', 'Gourav Sharma, Swati Shrestha, Te-Ming Tseng, Sanju Shrestha', 2023, 'Horticulturae', '10.3390/horticulturae9121354', 'https://doi.org/10.3390/horticulturae9121354', 'https://www.mdpi.com/2311-7524/9/12/1354', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Solanum lycopersicum, the domesticated species of tomato, is produced and consumed globally. It is one of the most economically important vegetable crops worldwide. In the commercial production of tomatoes, tomatoes are extremely sensitive to herbicide drifts from row crops in the vicinity. Injury to tomatoes from auxin herbicides and glyphosate can occur at rates as low as 0.01×. This results in a substantial yield reduction, and at high drift rates, plants may not show signs of recovery. With the new herbicide-resistant crop technologies on the market, which include 2,4-D and dicamba-resistant crops, there is an increase in the usage of these herbicides, causing more serious drift problems. There is a diverse germplasm of tomatoes that includes wild relatives which are tolerant to numerous biotic and abiotic stresses. Herbicide/chemical stress is an abiotic stress, and wild tomato accessions may have a natural tolerance to herbicides and other abiotic stresses. In the current study, diverse tomato genotypes consisting of 110 accessions representing numerous species, Solanum habrochaites, S. cheesmaniae, S. pimpinellifolium, S. chilense, S. lycopersicum, S. pimpinellifolium, S. galapagense, S. chimelewskii, S. corneliomulleri, S. neorickii, and S. lycopersicoides, were used for screening drift rate herbicide tolerance. The herbicides tested included simulated drift rates of 2,4-D, dicamba, glyphosate, quinclorac, aminopyralid, aminocyclopyrachlor, and picloram. The visual injury rating of each accession for each herbicide treatment was taken 7, 14, 21, and 28 days after treatment (DAT) on a scale of 0–100%. Numerous accessions were found to have minimal injury (less than 20%) for each of the herbicides tested; nine accessions were found for both 2,4-D and glyphosate, eleven for dicamba, five for quinclorac, eight for aminocyclopyrachlor and two for both aminopyralid and picloram at 28 DAT. The identification of genotypes with a higher herbicide tolerance will provide valuable genetic resources for the development of elite tomato varieties that can resist herbicide injury and produce competitive yields.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ef55dbb-db39-4ce2-9c58-3e5cb5ceb8d9', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Inheritance of multiple herbicide resistance in wild oat (Avena fatua L.)', 'J. Karlowsky, Anita L. Brûlé‐Babel, Lyle F. Friesen, Rene C. Van Acker, Gary H. Crow', 2006, 'Canadian Journal of Plant Science', '10.4141/p05-008', 'https://doi.org/10.4141/p05-008', 'https://cdnsciencepub.com/doi/pdf/10.4141/P05-008', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8efc691-2f2f-44f7-9c2f-3d13ff63aa3d', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Soybean genetic engineering in Brazil and South America - A review', 'Fuganti-Pagliarini R, Molinari MDC, Kafer JM, Nepomuceno AL, Henning LMM, Brommonschenkel SH, Zanardo LG, Bodanese-Zanettini MH', 2026, 'Genetics and molecular biology', '10.1590/1678-4685-gmb-2025-0007', 'https://doi.org/10.1590/1678-4685-gmb-2025-0007', 'https://europepmc.org/articles/PMC12965416?pdf=render', NULL, NULL, 25, NULL, 'prairies', 4, 'cc by', 'Soybean like other commodities brings important income to producer countries. In Brazil, the picture is not different. Thus, due to its economic significance and considering all field challenges, that impose abiotic and biotic constraints to improve yield, research efforts have focused on solving problems by applying biotechnological tools. In this review, a description of genetic engineering being developed in Brazil for soybean crop is addressed, including research in tolerance to abiotic conditions such as drought; to biotic factors such as insects, nematodes and fungal among other categories; as well as the use of soybean as bio-factories. All commercially available soybean events in Brazil and South American countries, for insect resistance and herbicide tolerance are also discussed. An overview of the Brazilian regulatory framework and South American countries for Biotech products is presented as well as the future perspectives for soybean genetic engineering in Brazil. In addition, a list of papers, from 2008 to the present, showing the state of the art of genetic engineering of soybean and by-products in Brazil is made available. The same search on the literature for South American countries did not return papers published on the genetic engineering of soybean and by-products. Although South American countries did not develop science on GM soybean, a search on GM varieties being sowed indicated that these countries adopted GM technology, due to all the advantages that these lines offer.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('211c1eca-beb1-4367-bbf6-a8850f33dedb', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Testing plant growth promoting microorganisms in the field - a proposal for standards', 'Neuhoff D, Neumann G, Weinmann M', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1324665', 'https://doi.org/10.3389/fpls.2023.1324665', 'https://europepmc.org/articles/PMC10824932?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'In the European Union and worldwide there are a burgeoning markets for plant growth promoting microorganisms (PGPM) and other biological agents as soil improvers, bio-fertilizers, plant bio-stimulants, and biological control agents or bio-pesticides. Microbial agents have a major share in this development. The use of such products is often advertised with the promise of contributing to sustainable agricultural practices by increasing crop growth and yield and offering an alternative or substitute to decrease the dependency of agriculture on hazardeous agrochemicals. In contrast to registered microbial plant protection products, PGPM that are marketed in the EU as soil improvers or plant biostimulants, are not strictly required to have proven minimum efficacy levels under field conditions. Manufacturers only have to ensure that these products do not pose unacceptable risks to human, animal or plant health, safety or the environment. Uniform guidelines comparable to the EPPO - standards (European and Mediterranean Plant Protection Organisation) to test the efficacy in field trials are not available. This paper attempts to fill the gap. It proposes guidelines for PGPM field trial design and implementation, as well as recommendations for the type and scope of data collection and evaluation. Selected research papers from literature were evaluated to analyze, whether and to what extent the requirements are already met. The majority of the papers had a clear experimental design followed by proper data evaluation. Frequent deficiencies were the low number of tested environments and crop species, insufficient site and agronomic management description and missing data on soil humidity and temperature. Using the suggested standards is assumed to increase the expressive power of tested microbial products.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce71d3fc-ed9d-4469-8101-8537abb91814', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'The global scientific consensus on genetically modified crop risk assessments', 'Favaratto L, Gleim S, Smyth SJ', 2026, 'GM crops & food', '10.1080/21645698.2026.2704430', 'https://doi.org/10.1080/21645698.2026.2704430', 'https://europepmc.org/articles/PMC13471097?pdf=render', NULL, NULL, 23, NULL, 'prairies', 4, 'cc by', 'Initial risk assessments of genetically modified (GM) crops began in the early 1990 s, focusing on herbicide tolerance and insect resistance, with approvals by the mid-1990s. These assessments compare GM crops to non-GM equivalents, a framework unchanged for over 30 years. Since the first assessment in 1994, over 4,400 evaluations have been conducted across more than 70 countries for both cultivation and food/feed use. To date, none have identified increased risk relative to conventional varieties. This article analyzes three decades of GM crop approvals, highlighting the consistency of scientific assessment processes. Fourteen crops underwent 692 cultivation and 1,891 food-release assessments for herbicide tolerance, while insect resistance accounted for 523 cultivation and 1,396 food-release assessments, largely involving Bacillus thuringiensis (Bt). The findings underscore that GM crops are equivalent in risk to conventional varieties, supporting reliance on established international scientific expertise, particularly in resource-constrained regions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('834f8061-d314-4fcb-b26c-2d284de06b20', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Tolerance of azuki bean to herbicides applied preplant for weed control in a strip‐tillage cropping system', 'Nader Soltani, Lynette R. Brown, Peter H. Sikkema', 2022, 'Legume Science', '10.1002/leg3.140', 'https://doi.org/10.1002/leg3.140', 'https://doi.org/10.1002/leg3.140', NULL, NULL, NULL, NULL, 'canada', 3, 'open access (DOAJ)', 'Abstract Five field experiments were conducted at Huron Research Station near Exeter, Ontario, Canada, during 2018 to 2020 to assess the tolerance of strip‐till‐grown azuki bean to various preplant (PP) herbicides. The herbicides selected have activity on glyphosate‐resistant (GR) Canada fleabane, an emerging weed biotype in strip‐till azuki bean production. Saflufenacil, metribuzin, 2,4‐D ester, saflufenacil + metribuzin, saflufenacil + 2,4‐D ester, metribuzin + 2,4‐D ester, and saflufenacil + metribuzin + 2,4‐D ester, applied PP 1 week before seeding, at the proposed label rate (1X) and twice that rate (2X) caused as much as 6%, 5%, 6%, 7%, 8%, 10%, and 13% visible azuki bean injury. The herbicide‐induced azuki bean injury was transient and had no effect on plant density, aboveground dry biomass, height, maturity, and yield except for the dry biomass which was reduced by 28% with metribuzin + 2,4‐D ester and 36% with saflufenacil + metribuzin + 2,4‐D ester at the 2X rate and azuki bean height which was reduced 9% at the 2X rate with saflufenacil + metribuzin + 2,4‐D ester. Based on these results, saflufenacil, metribuzin, 2,4‐D ester, saflufenacil + metribuzin, saflufenacil + 2,4‐D ester, and metribuzin + 2,4‐D ester applied PP have potential for GR Canada fleabane control in strip‐till azuki beans. However, there is not enough crop safety for using a three‐way tankmix of saflufenacil + metribuzin + 2,4‐D ester, applied PP, in azuki bean production.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bb1def55-959f-45fc-8b52-6daac6bb9e39', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Unraveling Sorghum Allelopathy in Agriculture: Concepts and Implications', 'Hussain MI, Danish S, Sánchez-Moreiras AM, Vicente Ó, Jabran K, Chaudhry UK, Branca F, Reigosa MJ', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10091795', 'https://doi.org/10.3390/plants10091795', 'https://europepmc.org/articles/PMC8470078?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Allelopathy is an ecological phenomenon that involves the production and release of biomolecules from different crops, cultivated plants, and bacteria or fungi into the soil rhizosphere and impacts other organisms in the vicinity. Sorghum possesses vital allelopathic characteristics due to which it produces and releases different biomolecules from its root hairs, stems, and grains. Several studies have reported that sorghum acts as an allelopathic crop, decreasing the growth and eco-physiological attributes of surrounding plants and weeds growing simultaneously or subsequently in the field. Sorghum allelopathy has been exploited in the context of green manure, crop rotations, cover crops, and intercropping or mulching, whereas plant aqueous extracts or powder might be an alternate method of weed control. A diverse group of allelochemicals, including benzoic acid, p-hydroxybenzoic acid, vanillic acid, ferulic acid, chlorogenic acid, m-coumaric acid, p-coumaric acid, gallic acid, caffeic acid, p-hydroxibenzaldehyde, dhurrin, sorgoleone, m-hydroxybenzoic acid and protocatechuic acid, have been isolated and identified from different plant tissues of sorghum and root exudates. These allelochemicals, especially sorgoleone, have been investigated in terms of their mode(s) of action, specific activity and selectivity, release in the rhizosphere and uptake and translocation in sensitive species. The present review describes the importance of sorghum allelopathy as an ecological tool in managing weeds, highlighting the most recent advances in the allelochemicals present in sorghum, their modes of action, and their fate in the ecosystem. Further research should focus on the evaluation and selection of sorghum cultivars with high allelopathic potential, so that sorghum allelopathy can be better utilized for weed control and yield enhancement.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49d95141-756f-47e2-8517-9b39aea5e8e5', 'ed36df5a-8b69-4ce0-9614-efe30723c375', 'Weed Control Efficacy and Crop-Weed Selectivity of a New Bioherbicide WeedLock', 'Mahmudul Hasan, Anis Syahirah Mokhtar, Adam Mustafa Rosli, Hafizuddin Hamdan, Mst. Motmainna, Muhammad Saiful Ahmad-Hamdani', 2021, 'Agronomy', '10.3390/agronomy11081488', 'https://doi.org/10.3390/agronomy11081488', 'https://www.mdpi.com/2073-4395/11/8/1488', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Plant-based bioherbicides could be an effective alternative to current chemical herbicides for sustainable agriculture. Therefore, this research evaluated the weed control efficacy and crop-weed selectivity of the new plant-derived bioherbicide WeedLock compared to commercial herbicides in glasshouse and field conditions. In the glasshouse, the herbicides applied were WeedLock (672.75, 1345.50, 2691.00 L ha−1), glyphosate isopropyl-amine, and glufosinate-ammonium (1, 2, 4 L ha−1), over the untreated (control) on six weeds and four crops. In the field trial, typical weeds were allowed to grow at a uniform density across plots (2.5 × 2.5 m), and WeedLock (1345.50, 2691.00 L ha−1), glyphosate isopropyl-amine, and glufosinate-ammonium (2, 4 L ha−1) were applied along with untreated plot (control). A randomized complete block design was set with four replications for glasshouse and field experiments. WeedLock at 1345.50 L ha−1 showed efficacy similar to glyphosate isopropyl-amine and glufosinate-ammonium at 2 L ha−1 for Ageratum conyzoides L. in the glasshouse. Applied herbicides killed all tested crops except Zea mays L. at 1345.50 L ha−1 (WeedLock). WeedLock showed more than 50% efficacy at 35 days after spray, while 65% was produced by glyphosate isopropyl-amine and glufosinate-ammonium compared to the untreated plot (control). WeedLock has excellent potential to control weeds in both glasshouse and field conditions and showed a non-selective character.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a2f24dd-2075-42cf-b757-3f3bf4f1d706', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'ACCase-inhibiting herbicides: mechanism of action, resistance evolution and stewardship', 'Hudson Kagueyama Takano, R. F. Lopez Ovejero, Gustavo Gross Belchior, Gizella Potrich Leal Maymone, Franck Emmanuel Dayan', 2020, 'Scientia Agricola', '10.1590/1678-992x-2019-0102', 'https://doi.org/10.1590/1678-992x-2019-0102', 'https://www.scielo.br/j/sa/a/n6tBxRkLVt6FbqRSbvRVGhg/?lang=en&format=pdf', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc-by', 'Herbicides play an important role in preventing crop yield losses due to both their weed interference ability and their capacity for increasing soil conservation in no-till systems. Group A herbicides or acetyl-CoA carboxylase (ACCase) are essential tools the selective management of glyphosate resistance in grass weed species. In this review, we describe important aspects of ACCase biology and herbicides targeting this enzyme, along with a discussion on stewardship programs to delay the evolution of herbicide resistance which can evolve either through target site and/or non-target site mechanisms. Sixteen-point mutations have been reported to confer resistance to ACCase inhibitors. Each mutation confers cross resistance to a different group of herbicides. Metabolic resistance can result in resistance to multiple herbicides with different mechanisms of action (MoA), and herbicide detoxification is often conferred by cytochrome P450 monooxigenases and glutathione- S -transferases. Regardless of whether resistance mechanisms are target or non-target site, using herbicides with the same MoA will result in resistance evolution. Therefore, while field surveys and resistance mechanism studies are crucial for designing reactive management strategies, integrated weed management plays a central role in both reactive and proactive mitigation of herbicide resistance evolution.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c9bb878-b1ec-4ed9-8345-1ea07b56c353', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Alteration in yield and oil quality traits of winter rapeseed by lodging at different planting density and nitrogen rates', 'Khan S, Anwar S, Anwar S, Kuai J, Noman A, Shahid M, Din M, Ali A', 2018, 'Scientific reports', '10.1038/s41598-017-18734-8', 'https://doi.org/10.1038/s41598-017-18734-8', 'https://europepmc.org/articles/PMC5766575?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Lodging is a factor that negatively affects yield, seed quality, and harvest ability in winter rapeseed (Brassica napus L.). In this study, we quantified the lodging-induced yield losses, changes in fatty acid composition, and oil quality in rapeseed under different nitrogen application rates and planting densities. Field experiments were conducted in 2014-2017 for studying the effect of manually-induced lodging angles (0°, 30°, 60°, and 90°), 10, 20 and 30 d post-flowering at different densities and nitrogen application rates. The fertilization/planting density combination N270D45 produced the maximum observed yield and seed quality. Timing and angle of lodging had significant effects on yield. Lodging at 90° induced at 10 d post-flowering caused the maximum reduction in yield, biomass, and silique photosynthesis. Seed yield losses were higher at high N application rates, the maximum being at N360D45. Lodging decreased seed oil content and altered its fatty acid composition by increasing stearic and palmitic acid content, while decreasing linoleic and linolenic acid content, and deteriorating oil quality by increasing erucic acid and glucosinolate content. Therefore, lodging-induced yield loss and reduction in oil content might be reduced by selecting optimum N level and planting density.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc1ee966-bf83-4da3-b13f-ad26ea65e188', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'An extension program for ACCase inhibitor resistance in Manitoba : A case study', 'M. Goodwin', 2005, 'Phytoprotection', '10.7202/706077ar', 'https://doi.org/10.7202/706077ar', 'https://www.erudit.org/en/journals/phyto/1994-v75-n4-phyto3355/706077ar.pdf', NULL, NULL, 2, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('825e9a25-b8c7-4c1b-a028-659e76e9bbfb', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Chemically induced herbicide tolerance in rice by the safener metcamifen is associated with a phased stress response', 'Brazier-Hicks M, Howell A, Cohn J, Hawkes T, Hall G, Mcindoe E, Edwards R', 2020, 'Journal of experimental botany', '10.1093/jxb/erz438', 'https://doi.org/10.1093/jxb/erz438', 'https://europepmc.org/articles/PMC6913702?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc', 'The closely related sulphonamide safeners, metcamifen and cyprosulfamide, were tested for their ability to protect rice from clodinafop-propargyl, a herbicide normally used in wheat. While demonstrating that both compounds were equally bioavailable in planta, only metcamifen prevented clodinafop from damaging seedlings, and this was associated with the enhanced detoxification of the herbicide. Transcriptome studies in rice cultures demonstrated that whereas cyprosulfamide had a negligible effect on gene expression over a 4 h exposure, metcamifen perturbed the abundance of 590 transcripts. Changes in gene expression with metcamifen could be divided into three phases, corresponding to inductions occurring over 30 min, 1.5 h and 4 h. The first phase of gene induction was dominated by transcription factors and proteins of unknown function, the second by genes involved in herbicide detoxification, while the third was linked to cellular homeostasis. Analysis of the inducible genes suggested that safening elicited similar gene families to those associated with specific biotic and abiotic stresses, notably those elicited by abscisic acid, salicylic acid, and methyl jasmonate. Subsequent experiments with safener biomarker genes induced in phase 1 and 2 in rice cell cultures provided further evidence of similarities in signalling processes elicited by metcamifen and salicylic acid.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('750af79d-5c1d-47a8-a522-f03ef902bdf4', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Evaluating seedbank stimulants for wild oat and volunteer cereal management on the Canadian Prairies', 'Shaun M. Sharpe, Taylor Kaye, Breanne D. Tidemann', 2023, 'Canadian Journal of Plant Science', '10.1139/cjps-2022-0202', 'https://doi.org/10.1139/cjps-2022-0202', 'https://utoronto.scholaris.ca/bitstreams/942b5992-c5a6-4995-b249-d1bfaed89493/download', NULL, NULL, 30, NULL, 'alberta', 4, 'cc-by', 'Wild oat is a widespread threat to annual crop production on the Canadian Prairies. Infestations are difficult to manage due to a persistent seedbank, complex dormancy, a long emergence window, herbicide resistance, and seed shatter corresponding to crop harvest timings. The study objective was to evaluate the efficacy of potassium nitrate (KNO3) and pyroligneous acid for promoting germination and emergence of wild oat and volunteer wheat, barley, and oat. A total of 24 repeated experiments were conducted using freshly produced seeds to ensure adequate endodormancy. Wheat and barley demonstrated no endodormancy following seed formation and rapidly emerged with moisture. All species imbibed but did not germinate in Petri dishes within pyroligneous acid solutions of 5%–100%. Dormancy release was observed within 0.1% and 1% pyroligneous acid solutions. KNO3 did not stimulate germination or emergence for any species and was inhibitory at 125 kg N ha−1. Pyroligneous acid increased wild oat emergence with 50% and 100% solutions applied at 200 L ha−1 in the first study and with 10% solutions in the second study. Emergence inhibition was noted for oat, barley, and wheat with pyroligneous acid applications. This research further confirms that pyroligneous acid may stimulate wild oat emergence and confirms activity on freshly matured seed.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1850fc7d-4e42-41f0-94b8-cabb5891bae5', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Comparative Efficacy of Chondrosterum purpureum and Chemical Herbicides for Control of Resprouts in Tanoak and Bay Laurel', 'Shamoun SF, Elliott M', 2022, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens11050485', 'https://doi.org/10.3390/pathogens11050485', 'https://europepmc.org/articles/PMC9143336?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by', 'The invasive Oomycete pathogen Phytophthora ramorum has killed millions of susceptible oak and tanoak trees in California and southern Oregon forests and is responsible for losses in revenue to the nursery industry through mitigation activities. In addition, infestation of forests in the United Kingdom by this organism has resulted in the destruction of many hectares of larch plantations. Resprouting stumps can be a reservoir for the inoculum of P. ramorum persisting on a site. In areas where the application of herbicides is not permitted, a biocontrol treatment would be an indispensable alternative. Treatment of stumps with the sap-rotting fungus Chondrostereum purpureum (Pers.) Pouzar has been shown to be an effective tool for the suppression of resprouting on several species, most notably red alder. In this project, the ability of C. purpureum to suppress resprouting was evaluated on stumps of two host species, tanoak (Notholithocarpus densiflorus) and California bay laurel (Umbellularia californica). Laboratory testing of three California isolates of C. purpureum indicated that the fungus can colonize bay laurel stems. Field trials were established near Brookings, Oregon, on tanoak and on bay laurel near Soquel, California. Early results of field testing showed that C. purpureum was able to colonize the stumps of tanoak following treatment and was found to occur naturally on tanoak logs and stumps. Formulations of C. purpureum appear to have some effect on reducing sprout survival in tanoak, but the most effective and rapid treatment for this host is the hack and squirt method of applying the herbicide imazapyr. Sprayed herbicide prevents sprouting on bay laurel, and there was evidence that resprouting was inhibited on stumps treated with C. purpureum. Over time, applications of C. purpureum may be a more permanent solution as the stumps begin to decay.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7730edf6-3e84-466d-b3d1-d299aee425f0', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Differences in Germination of ACCase-Resistant Biotypes Containing Isoleucine-1781-Leucine Mutation and Susceptible Biotypes of Wild Oat (Avena sterilis ssp. ludoviciana)', 'Fatemeh Benakashani, Jose L. Gonzalez-Andujar, Elias Soltani', 2021, 'Plants', '10.3390/plants10112350', 'https://doi.org/10.3390/plants10112350', 'https://www.mdpi.com/2223-7747/10/11/2350', NULL, NULL, 14, NULL, 'other', 1, 'open access (DOAJ)', 'Herbicide resistance can affect seed germination and the optimal conditions required for seed germination, which in turn may impose a fitness cost in resistant populations. Winter wild oat [Avena sterilis L. ssp. ludoviciana (Durieu) Gillet and Magne] is a serious weed in cereal fields. In this study, the molecular basis of resistance to an ACCase herbicide, clodinafop-propargyl, in four A. ludoviciana biotypes was assessed. Germination differences between susceptible (S) and ACCase-resistant biotypes (WR1, WR2, WR3, WR4) and the effect of Isoleucine-1781-Leucine mutation on germination were also investigated through germination models. The results indicated that WR1 and WR4 were very highly resistant (RI > 214.22) to clodinafop-propargyl-contained Isoleucine to Leucine amino acid substitution. However, Isoleucine-1781-Leucine mutation was not detected in other very highly resistant biotypes. Germination studies indicated that resistant biotypes (in particular WR1 and WR4) had higher base water potentials than the susceptible one. This shows that resistant biotypes need more soil water to initiate their germination. However, the hydrotime constant for germination was higher in resistant biotypes than in the susceptible one in most cases, showing faster germination in susceptible biotypes. ACCase-resistant biotypes containing the Isoleucine-1781-Leucine mutation had lower seed weight but used more seed reserve to produce seedlings. Hence, integrated management practices such as stale seedbed and implementing it at the right time could be used to take advantage of the differential soil water requirement and relatively late germination characteristics of ACCase-resistant biotypes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('152c0cf8-b91c-4cc9-9975-02ab95323800', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Diversified Resistance Mechanisms in Multi-Resistant Lolium spp. in Three European Countries', 'Laura Scarabel, Silvia Panozzo, Donato Loddo, Solvejg K. Mathiassen, Michael Kristensen, Per Kudsk, Thomas Gitsopoulos, Ilias Travlos', 2020, 'Frontiers in Plant Science', '10.3389/fpls.2020.608845', 'https://doi.org/10.3389/fpls.2020.608845', 'https://www.frontiersin.org/articles/10.3389/fpls.2020.608845/full', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Annual ryegrass species (Lolium spp.) infest cereal crops worldwide. Ryegrass populations with multiple resistance to the acetyl coenzyme A carboxylase (ACCase) and acetolactate synthase (ALS) inhibitors are an increasing problem in several European countries. We investigated the resistance pattern and level of resistance in ryegrass populations collected in Denmark, Greece and Italy and studied the diversity of mechanisms endowing resistance, both target-site and metabolism based. All populations showed high resistance indexes (RI) to the ALS inhibitors, iodosufuron-methyl-sodium + mesosulfuron-methyl (RI from 8 to 70), whereas the responses to the two ACCase inhibitors, clodinafop-propargyl and pinoxaden, differed. The Greek and Italian populations were moderately to highly resistant to clodinafop (RI > 8) and showed low to moderate resistance to pinoxaden (RI ranged from 3 to 13) except for one Italian population. In contrast, the Danish Lolium populations showed low to moderate resistance to clodinafop (RI ranged from 2 to 7) and only one population was resistant to pinoxaden. Different mutant ACCase alleles (Leu1781, Cys2027, Asn2041, Val2041, Gly2078, Arg2088, Ala2096) and ALS alleles (Gly122, Ala197, Gln197, Leu197, Ser197, Thr197, Val205, Asn376, Glu376, Leu574) endowing resistance were detected in the Greek and Italian populations. In several plants, no mutated ALS and ACCase alleles were found showing a great heterogeneity within and among the Greek and Italian populations. Conversely, no mutant ACCase alleles were identified in the four Danish populations and only one mutant ALS allele (Leu574) was detected in two Danish populations. The expression level of nitronate monooxygenase (NMO), glutathione S-transferase (GST) and cytochrome P450s (CYP72A1 and CYP72A2) varied broadly among populations and individual plants within the populations. Constitutive up-regulation of GST, CYP72A1 and CYP72A2 was detected in resistant plants respect to susceptible plants in one Danish and one Italian population. It appears that the mechanisms underlying resistance are rather complex and diversified among Lolium spp. populations from the three countries, coevolution of both target-site resistance and metabolic based herbicide resistance appears to be a common feature in Denmark and Italy. This must be considered and carefully evaluated in adopting resistance management strategies to control Lolium spp. in cereal crops.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05804152-5d3a-4bf6-bc63-2de7b7c911e3', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Early Detection of Herbicide Resistance Evolution in Rigid Ryegrass (Lolium rigidum) Using Sensor-Based Smart Farming for Sustainable Weed Management', 'Aikaterini Kasimati, Ioannis Gazoulis, Dimitra Petraki, Panagiotis Kanatas, Metaxia Kokkini, Aggeliki Petraki, Kyriaki Maria Papapostolou, John Vontas', 2026, 'Agronomy', '10.3390/agronomy16090869', 'https://doi.org/10.3390/agronomy16090869', 'https://www.mdpi.com/2073-4395/16/9/869', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Lolium rigidum is among the most prevalent and noxious weeds in cereal and perennial cropping systems worldwide and has developed resistance to several herbicide modes of action. This study employed a sensor-based smart farming method for the early screening of herbicide resistance across three L. rigidum accessions in Greece, followed by dose–response experiments with clodinafop-propargyl, glyphosate, and mesosulfuron-methyl + iodosulfuron-methyl. In the preliminary screening, herbicides were applied at their highest recommended rates, whereas the dose–response experiments included five application rates (0, 1/4X, X, 2X, and 4X). The EM2 accession exhibited confirmed resistance to mesosulfuron-methyl + iodosulfuron-methyl, with a resistance index of 5.31 and a five-fold increase in the herbicide rate required compared to the susceptible EM1 accession. For clodinafop-propargyl, the GR50 value of the resistant EM3 accession (147.97 g a.i. ha−1) was approximately 2.5-fold higher than that of the susceptible EM2 accession (60.28 g a.i. ha−1). Glyphosate application provided only partial biomass reduction in resistant accessions, indicating reduced susceptibility. In parallel, TaqMan assays were developed and validated to detect target-site mutations linked to resistance against EPSPS-, ACCase-, and ALS-inhibiting herbicides, supporting the molecular interpretation of the observed resistance patterns. Overall, the results demonstrate that sensor-based smart farming approaches can provide a rapid and reliable tool for the early screening of herbicide resistance, enabling more informed crop protection strategies and supporting sustainable weed management. Further research across diverse soil types and climatic conditions is warranted to validate and extend the applicability of these approaches.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b7e9a0e2-fb6d-43b9-adf4-ee078efd9528', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Evaluating intercropped cover crops and their compatibility with canola and wheat herbicidal weed management strategies on the Canadian Prairies', 'Janelle Gawiak', 2026, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/39774', 'https://mspace.lib.umanitoba.ca/bitstreams/a88bfae2-7472-4468-a937-d16b1c622ec8/download', NULL, NULL, 219, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('273dc80f-6a72-434d-b5ec-87f6b9625d43', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Mapping risk areas for resistance to ACCase inhibitor herbicides in Manitoba', 'Luc Bourgeois, Ian N. Morrison', 1997, 'Canadian Journal of Plant Science', '10.4141/p96-083', 'https://doi.org/10.4141/p96-083', 'https://cdnsciencepub.com/doi/pdf/10.4141/P96-083', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4edea7d-8aa3-4bee-9d75-bd352184cd3f', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Optimizing Pyroxasulfone Efficacy on Wild Oat (Avena fatua L.)', 'Amy R. Mangin', 2016, 'ERA: Education and Research Archive (University of Alberta)', '10.7939/r3pv6bj1r', 'https://doi.org/10.7939/r3pv6bj1r', 'https://era.library.ualberta.ca/items/cffa3466-e841-4857-9dbb-6896698ee889/view/4a421459-8b8d-4e5e-9c0d-8359621c3849/mangin_amy_r_201607_msc.pdf', NULL, NULL, 150, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('57f2f38f-540d-48cc-809f-4b825404d9f7', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Evaluation of panicle removal methods and crop topping applications as supplemental tools for wild oat (Avena fatua) management', 'Breanne D. Tidemann, K. Neil Harker, Steven J. Shirtliffe, Christian J. Willenborg, Eric N. Johnson, Elizabeth Sroka, Jennifer Zuidhof, Hema Duddu', 2021, 'Weed Technology', '10.1017/wet.2021.54', 'https://doi.org/10.1017/wet.2021.54', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/56838205EDF5DA3365BFFE50D71D778A/S0890037X21000543a.pdf/div-class-title-evaluation-of-panicle-removal-methods-and-crop-topping-applications-as-supplemental-tools-for-wild-oat-span-class-italic-avena-fatua-span-management-div.pdf', NULL, NULL, 13, NULL, 'alberta', 4, 'cc-by', 'Abstract Increased frequency and occurrence of herbicide-resistant biotypes heightens the need for alternative wild oat management strategies. This study aimed to exploit the height differential between wild oat and crops by targeting wild oat between panicle emergence and seed shed timing. Two field studies were conducted either in Lacombe, AB, or Lacombe, AB and Saskatoon, SK, from 2015 to 2017. In the first study, we compared panicle removal methods: hand clipping, use of a hedge trimmer, and a selective herbicide crop topping application to a weedy check and an industry standard in-crop herbicide application in wheat. These treatments were tested early (at panicle emergence), late (at initiation of seed shed), or in combination at one location over 3 yr. In the second study, we investigated optimal timing of panicle removal via a hedge trimmer with weekly removals in comparison to a weedy check in wheat and lentil. This study was conducted at two locations, Lacombe, AB, and Saskatoon, SK, over 3 yr. Among all the tested methods, the early crop topping treatment consistently had the largest impact on wild oat density, dockage, seedbank, and subsequent year crop yield. The early (at panicle emergence) or combination of early and late (at initiation of seed shed) treatments tended to reduce wild oat populations the following season the most compared to the late treatments. Subsequent wild oat populations were not influenced by panicle removal timing, but only by crop and location interactions. Panicle removal timing did significantly affect wild oat dockage in the year of treatment, but no consistent optimal timing could be identified. However, the two studies together highlight additional questions to be investigated, as well as the opportunity to manage wild oat seedbank inputs at the panicle emergence stage of the wild oat lifecycle.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('187b13b0-ade9-42e5-81bf-51b13421b325', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Field and producer survey of ACCase resistant wild oat in Manitoba', 'Luc Bourgeois, Ian N. Morrison, David J. Kelner', 1997, 'Canadian Journal of Plant Science', '10.4141/p96-174', 'https://doi.org/10.4141/p96-174', 'https://cdnsciencepub.com/doi/pdf/10.4141/P96-174', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3d341d7e-859f-47a0-b8c9-b4c7188d4c56', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Herbicide resistance-endowing ACCase gene mutations in hexaploid wild oat (Avena fatua): insights into resistance evolution in a hexaploid species', 'Qin Ping Yu, Muhammad Saiful Ahmad Hamdani, H Han, Michael J. Christoffers, Stephen B. Powles', 2012, 'Heredity', '10.1038/hdy.2012.69', 'https://doi.org/10.1038/hdy.2012.69', 'http://psasir.upm.edu.my/id/eprint/29323/1/Herbicide%20resistance-endowing%20ACCase%20gene%20mutations%20in%20hexaploid%20wild%20oat%20%28Avena%20fatua%29%20insights%20into%20resistance%20evolution%20in%20a%20hexaploid%20species.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3de662ac-d0d3-4c6d-9398-64fcd1e63a17', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Impact of Biotic and Abiotic Stresses on the Competitive Ability of Multiple Herbicide Resistant Wild Oat (Avena fatua)', 'Erik A. Lehnhoff, Barbara K. Keith, William E. Dyer, Fabián D. Menalled', 2013, 'PLoS ONE', '10.1371/journal.pone.0064478', 'https://doi.org/10.1371/journal.pone.0064478', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0064478&type=printable', NULL, NULL, 6, NULL, 'prairies', 4, 'cc-by', 'Ecological theory predicts that fitness costs of herbicide resistance should lead to the reduced relative abundance of resistant populations upon the cessation of herbicide use. This greenhouse research investigated the potential fitness costs of two multiple herbicide resistant (MHR) wild oat (Avena fatua) populations, an economically important weed that affects cereal and pulse crop production in the Northern Great Plains of North America. We compared the competitive ability of two MHR and two herbicide susceptible (HS) A. fatua populations along a gradient of biotic and abiotic stresses The biotic stress was imposed by three levels of wheat (Triticum aestivum) competition (0, 4, and 8 individuals pot(-1)) and an abiotic stress by three nitrogen (N) fertilization rates (0, 50 and 100 kg N ha(-1)). Data were analyzed with linear mixed-effects models and results showed that the biomass of all A. fatua populations decreased with increasing T. aestivum competition at all N rates. Similarly, A. fatua relative growth rate (RGR) decreased with increasing T. aestivum competition at the medium and high N rates but there was no response with 0 N. There were no differences between the levels of biomass or RGR of HS and MHR populations in response to T. aestivum competition. Overall, the results indicate that MHR does not confer growth-related fitness costs in these A. fatua populations, and that their relative abundance will not be diminished with respect to HS populations in the absence of herbicide treatment.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0785f191-c8a3-4478-a775-1ddcf7f0bcb3', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Influence of annual forages on weed dynamics in a cropping system', 'Allison Schoofs, Martin H. Entz', 2000, 'Canadian Journal of Plant Science', '10.4141/p98-098', 'https://doi.org/10.4141/p98-098', 'https://cdnsciencepub.com/doi/pdf/10.4141/P98-098', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('68b6a20a-3f1d-424b-9f92-114efdc76ac4', '0037f418-c458-4fd4-98e4-292918e93b6e', 'A case of eagle fern (Pteridium aquilinum) poisoning on a pig farm', 'Waret-Szkuta A, Jégou L, Lucas MN, Gaide N, Morvan H, Martineau GP', 2021, 'Porcine health management', '10.1186/s40813-020-00185-9', 'https://doi.org/10.1186/s40813-020-00185-9', 'https://europepmc.org/articles/PMC7784350?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by', 'BackgroundFree-range pig farming represents a minor proportion of pig production in France but is attracting an increasing number of farmers because of societal expectations and the opportunity to use pasture-grazed forage. However, this type of farming faces several challenges, including biosecurity, parasitic management, and contact with wild fauna and pathogenic flora.Case presentationTwo Gascon pigs raised on an outdoor fattening farm in the Hautes-Pyrenees department of France were submitted after sudden death for necropsy at the National Veterinary School of Toulouse. The pigs were of two different breeds but from the same group of 85 animals that had grazed on a 4-ha plot of land being used for grazing for the first time. Based on an in-depth interview with the farmer, the epidemiological information available, and the necropsy and histology examinations, a hypothesis of great eagle fern intoxication was proposed. Although the sample of animals available for diagnosis was small, the success of the administered therapy confirmed our diagnosis. It was recommended that in the short term, the animals be prevented access to the eagle fern by changing their pasture or removing the plants. Vitamin B1 and vitamin B6 were administered via feed as Ultra B® at 1 mL per 10 kg body weight per day for 2 days (providing 9 mg thiamine (vitamin B1) and 0.66 mg pyridoxine (vitamin B6) per kg body weight per day). Marked remission was observed, with 6 of 10 intoxicated animals with symptoms surviving (yielding a therapeutic success rate over 50%), but the therapy did not compensate for the loss of initial body condition. In total, of the 85 animals in the group after intoxication, 6 died, and 6 recovered.ConclusionsThe significance of this report lies in the scarcity of eagle fern intoxication cases reported in the literature, though such intoxication may become a significant problem as the development of outdoor rearing continues. Thus, eagle fern intoxication should be included in the differential diagnosis of nervous system symptoms in swine. The case also emphasizes the importance of anamnesis and discussion with the farmer as an essential step to guide diagnosis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('610a2454-3dd6-4f34-a39b-7944beb8ae4c', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Pesticide-Induced Inflammation at a Glance', 'Lopes-Ferreira M, Farinha LRL, Costa YSO, Pinto FJ, Disner GR, da Rosa JGDS, Lima C', 2023, 'Toxics', '10.3390/toxics11110896', 'https://doi.org/10.3390/toxics11110896', 'https://europepmc.org/articles/PMC10675742?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The increasing number of studies reporting the risks of the exposure to pesticides aligned with the intensified use of such hazardous chemicals has emerged as a pressing contemporary issue, notably due to the potential effects to both the environment and human health. Pesticides, while broadly applied in modern agriculture for pest control and crop protection, have raised concerns due to their unintended effects on non-target organisms. The immune system exerts a key role in the protection against the exposome, which could result in cellular imbalances and tissue damage through the inflammatory response. Pesticides, which encompass a diverse array of chemicals, have been linked to inflammation in experimental models. Therefore, the aim of this review is to discuss the increasing concern over the risks of pesticide exposure focusing on the effects of various chemical classes on inflammation by covering, as broadly as possible, different experimental approaches as well as the multiple or co-exposure of pesticides. Overall, pesticides potentially induce inflammation in different experimental models, manifested through skin irritation, respiratory impairment, or systemic effects. The connection between pesticides and inflammation highlights the importance of proper handling and regulation of these substances and underscores the need for research into safer and sustainable practices to reduce our reliance on synthetic pesticides and fertilizers.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce82c83b-c11d-442c-9124-4c39f16e3a14', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Repeated evolution of herbicide resistance in Lolium multiflorum revealed by haplotype‐resolved analysis of acetyl‐CoA carboxylase', 'Caio A. C. G. Brunharo, Patrick J. Tranel', 2023, 'Evolutionary Applications', '10.1111/eva.13615', 'https://doi.org/10.1111/eva.13615', 'https://doi.org/10.1111/eva.13615', NULL, NULL, 39, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Herbicide resistance in weeds is one of the greatest challenges in modern food production. The grass species Lolium multiflorum is an excellent model species to investigate evolution under similar selection pressure because populations have repeatedly evolved resistance to many herbicides, utilizing a multitude of mechanisms to neutralize herbicide damage. In this work, we investigated the gene that encodes acetyl‐CoA carboxylase (ACCase), the target site of the most successful herbicide group available for grass weed control. We sampled L. multiflorum populations from agricultural fields with history of intense herbicide use, and studied their response to three ACCase‐inhibiting herbicides. To elucidate the mechanisms of herbicide resistance and the genetic relationship among populations, we resolved the haplotypes of 97 resistant and susceptible individuals by sequencing ACCase amplicons using long‐read DNA sequencing technologies. Our dose–response data indicated the existence of many, often unpredictable, resistance patterns to ACCase‐inhibiting herbicides, where populations exhibited as much as 37‐fold reduction in herbicide response. The majority of the populations exhibited resistance to all three herbicides studied. Phylogenetic and molecular genetic analyses revealed multiple evolutionary origins of resistance‐endowing ACCase haplotypes, as well as widespread admixture in the region regardless of cropping system. The amplicons generated were diverse, with haplotypes exhibiting 26–110 polymorphisms. Polymorphisms included insertions and deletions 1–31 bp in length, none of which were associated with the resistance phenotype based on an association analysis. We also found evidence that some populations have multiple mechanisms of resistance. Our results highlight the astounding genetic diversity in L. multiflorum populations, and the potential for repeated evolution of herbicide resistance across the landscape that challenges weed management approaches and jeopardizes sustainable weed control practices. We provide an in‐depth discussion of the evolutionary and practical implications of our results.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49cf08a5-566b-4aa3-8480-cbdf81a6ddbc', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Role of a novel I1781T mutation and other mechanisms in conferring resistance to acetyl-CoA carboxylase inhibiting herbicides in a black-grass population.', 'Shiv Shankhar Kaundun, Sarah-Jane Hutchings, Richard P Dale, Eddie McIndoe', 2013, 'PLoS ONE', '10.1371/journal.pone.0069568', 'https://doi.org/10.1371/journal.pone.0069568', 'http://europepmc.org/articles/PMC3723891?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'open access (DOAJ)', 'BACKGROUND: Knowledge of the mechanisms of herbicide resistance is important for designing long term sustainable weed management strategies. Here, we have used an integrated biology and molecular approach to investigate the mechanisms of resistance to acetyl-CoA carboxylase inhibiting herbicides in a UK black-grass population (BG2). METHODOLOGY/PRINCIPAL FINDINGS: Comparison between BG2 phenotypes using single discriminant rates of herbicides and genotypes based on ACCase gene sequencing showed that the I1781L, a novel I1781T, but not the W2027C mutations, were associated with resistance to cycloxydim. All plants were killed with clethodim and a few individuals containing the I1781L mutation were partially resistant to tepraloxydim. Whole plant dose response assays demonstrated that a single copy of the mutant T1781 allele conferred fourfold resistance levels to cycloxydim and clodinafop-propargyl. In contrast, the impact of the I1781T mutation was low (Rf = 1.6) and non-significant on pinoxaden. BG2 was also characterised by high levels of resistance, very likely non-target site based, to the two cereal selective herbicides clodinafop-propargyl and pinoxaden and not to the poorly metabolisable cyclohexanedione herbicides. Analysis of 480 plants from 40 cycloxydim resistant black grass populations from the UK using two very effective and high throughput dCAPS assays established for detecting any amino acid changes at the 1781 ACCase codon and for positively identifying the threonine residue, showed that the occurrence of the T1781 is extremely rare compared to the L1781 allele. CONCLUSION/SIGNIFICANCE: This study revealed a novel mutation at ACCase codon position 1781 and adequately assessed target site and non-target site mechanisms in conferring resistance to several ACCase herbicides in a black-grass population. It highlights that over time the level of suspected non-target site resistance to some cereal selective ACCase herbicides have in some instances surpassed that of target site resistance, including the one endowed by the most commonly encountered I1781L mutation.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aeab98ad-7bd9-4f42-bf3a-625ffb0d9f7d', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Year-Round Monitoring of Contaminants in Neal and Rogers Creeks, Hood River Basin, Oregon, 2011-12, and Assessment of Risks to Salmonids', 'Hapke WB, Morace JL, Nilsen EB, Alvarez DA, Masterson K', 2016, 'PloS one', '10.1371/journal.pone.0158175', 'https://doi.org/10.1371/journal.pone.0158175', 'https://europepmc.org/articles/PMC4922572?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc0', 'Pesticide presence in streams is a potential threat to Endangered Species Act listed salmonids in the Hood River basin, Oregon, a primarily forested and agricultural basin. Two types of passive samplers, polar organic chemical integrative samplers (POCIS) and semipermeable membrane devices (SPMDs), were simultaneously deployed at four sites in the basin during Mar. 2011-Mar. 2012 to measure the presence of pesticides, polybrominated diphenyl ethers (PBDEs), and polychlorinated biphenyls (PCBs). The year-round use of passive samplers is a novel approach and offers several new insights. Currently used pesticides and legacy contaminants, including many chlorinated pesticides and PBDEs, were present throughout the year in the basin''s streams. PCBs were not detected. Time-weighted average water concentrations for the 2-month deployment periods were estimated from concentrations of chemicals measured in the passive samplers. Currently used pesticide concentrations peaked during spring and were detected beyond their seasons of expected use. Summed concentrations of legacy contaminants in Neal Creek were highest during July-Sept., the period with the lowest streamflows. Endosulfan was the only pesticide detected in passive samplers at concentrations exceeding Oregon or U.S. Environmental Protection Agency water-quality thresholds. A Sensitive Pesticide Toxicity Index (SPTI) was used to estimate the relative acute potential toxicity among sample mixtures. The acute potential toxicity of the detected mixtures was likely greater for invertebrates than for fish and for all samples in Neal Creek compared to Rogers Creek, but the indices appear to be low overall (<0.1). Endosulfans and pyrethroid insecticides were the largest contributors to the SPTIs for both sites. SPTIs of some discrete (grab) samples from the basin that were used for comparison exceeded 0.1 when some insecticides (azinphos methyl, chlorpyrifos, malathion) were detected at concentrations near or exceeding acute water-quality thresholds. Early life stages and adults of several sensitive fish species, including salmonids, are present in surface waters of the basin throughout the year, including during periods of peak estimated potential toxicity. Based on these data, direct toxicity to salmonids from in-stream pesticide exposure is unlikely, but indirect impacts (reduced fitness due to cumulative exposures or negative impacts to invertebrate prey populations) are unknown.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('97d79425-10bd-4b04-982d-ab4a5c870d5e', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Selection of relatively exact reference genes for gene expression studies in goosegrass (Eleusine indica) under herbicide stress', 'Chen J, Huang Z, Huang H, Wei S, Liu Y, Jiang C, Zhang J, Zhang C', 2017, 'Scientific reports', '10.1038/srep46494', 'https://doi.org/10.1038/srep46494', 'https://europepmc.org/articles/PMC5399354?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Goosegrass (Eleusine indica) is one of the most serious annual grassy weeds worldwide, and its evolved herbicide-resistant populations are more difficult to control. Quantitative real-time PCR (qPCR) is a common technique for investigating the resistance mechanism; however, there is as yet no report on the systematic selection of stable reference genes for goosegrass. This study proposed to test the expression stability of 9 candidate reference genes in goosegrass in different tissues and developmental stages and under stress from three types of herbicide. The results show that for different developmental stages and organs (control), eukaryotic initiation factor 4 A (eIF-4) is the most stable reference gene. Chloroplast acetolactate synthase (ALS) is the most stable reference gene under glyphosate stress. Under glufosinate stress, eIF-4 is the best reference gene. Ubiquitin-conjugating enzyme (UCE) is the most stable reference gene under quizalofop-p-ethyl stress. The gene eIF-4 is the recommended reference gene for goosegrass under the stress of all three herbicides. Moreover, pairwise analysis showed that seven reference genes were sufficient to normalize the gene expression data under three herbicides treatment. This study provides a list of reliable reference genes for transcript normalization in goosegrass, which will facilitate resistance mechanism studies in this weed species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c702e173-c5cc-4c83-b844-bce7df00f1d4', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Sensitivity of littleseed canary grass populations from Punjab, India, to clodinafop‐propargyl and isoproturon', 'Gurpreet Kaur, Tarundeep Kaur, Makhan Singh, Priyanka Sharma, Vipan Kumar', 2024, 'Agrosystems, Geosciences & Environment', '10.1002/agg2.20458', 'https://doi.org/10.1002/agg2.20458', 'https://doi.org/10.1002/agg2.20458', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Littleseed canary grass (Phalaris minor Retz.) is one of the most prevalent and troublesome annual grass weed species in wheat across the Indo‐Gangetic plains (IGP) of India, including Punjab. Littleseed canary grass has evolved resistance to different herbicide sites of action in the IGP region. A targeted field survey was conducted in 2018 and 2019 for seed collection of littleseed canary grass populations (total 94) across different districts of Punjab state prior to wheat harvest. The main objective of this research was to characterize the sensitivity response of collected littleseed canary grass populations to clodinafop‐propargyl (CP) and isoproturon (IPU) herbicides in whole‐plant dose‐response assays. Among all tested populations, 68 were found to be highly sensitive to CP, whereas all 94 populations were sensitive to IPU. Based on a 50% reduction in shoot dry biomass (GR50 values) and estimated sensitivity index (SI), 26 populations exhibited reduced sensitivity (SI of 2.2–4.4) to CP herbicide. The results also revealed that the littleseed canary grass populations with reduced sensitivity (SI ≥ 2.2) to CP had high sensitivity to IPU herbicide. Overall, these results suggested a high prevalence of littleseed canary grass populations with reduced sensitivity to CP herbicide in Punjab state. Diversified weed management strategies, including the use of alternative herbicides (both preemergence and postemergence), cultural (no‐till drill for wheat sowing and narrow row spacing), and mechanical (cutting of littleseed canary grass panicles prior to wheat harvest) practices should be adopted to control littleseed canary grass populations with reduced sensitivity to CP.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d3ad71d8-9034-40c2-8804-e080f2fb3ee7', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Sequential herbicide application coupled with mulch enhances the productivity and quality of winter onion (Allium cepa L.) while effectively controlling the mixed weed flora', 'Ramanjit Kaur, R. S. Bana, Teekam Singh, S. L. Meena, Rishi Raj, Anchal Dass, Prabhu Govindasamy, Jasvir Singh Gill', 2024, 'Frontiers in Sustainable Food Systems', '10.3389/fsufs.2023.1271340', 'https://doi.org/10.3389/fsufs.2023.1271340', 'https://www.frontiersin.org/articles/10.3389/fsufs.2023.1271340/full', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'Weed control poses substantial difficulties for winter season onion (Allium cepa L.) cultivation in the north-western Indo-Gangetic Plains, primarily due to the constrained efficacy of the existing herbicides. To address this issue, a 2-year field study was conducted to assess the efficacy of pre- and post-emergence herbicides (pendimethalin, ethoxysulfuron, imazethapyr, and quizalofop-p-ethyl) individually and in combination with crop residue mulch for weed control in winter onion. The results revealed that using herbicides or mulches in isolation did not provide satisfactory weed control. However, the integration of natural mulch with pendimethalin followed by quizalofop-p-ethyl application proved to be the most effective weed control strategy, resulting in the least reduction in bulb yield (10.3%) compared to other treatments. On the contrary, combinations of pendimethalin with ethoxysulfuron or imazethapyr showed adverse effects on the onion crop and inflicted the highest yield losses among all treatments (78.6 and 83.4%, respectively). However, the combination of pendimethalin with quizalofop-p-ethyl coupled with crop mulch resulted in season-long weed control and over 80% bulb yield (36.58 t/ha) gains compared to the weed-free condition. These findings emphasize the efficacy of combining herbicides and mulches as an integrated weed management strategy for onions. By adopting such integrated approaches, farmers could improve weed control while maintaining bulb yield and quality, reducing the risks associated with herbicide resistance, and promoting sustainable onion production in the north-western Indo-Gangetic Plains.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c6e917b7-4cdf-481f-9b00-abafe0d020f7', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'StMADS11 Subfamily Gene PfMADS16 From Polypogon fugax Regulates Early Flowering and Seed Development', 'Feng-Yan Zhou, Qin Yu, Yong Zhang, Chuan-Chun Yao, Yun-Jing Han', 2020, 'Frontiers in Plant Science', '10.3389/fpls.2020.00525', 'https://doi.org/10.3389/fpls.2020.00525', 'https://www.frontiersin.org/article/10.3389/fpls.2020.00525/full', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The evolution of herbicide resistance in weedy plants leads to various adaptation traits including flowering time and seed germination. In our previous studies, we found an association of the early flowering phenotype with the ACCase inhibitor herbicide resistance genotype in a population of Polypogon fugax. MADS-box transcription factors are known to play pivotal roles in regulating plant flowering time. In this study, a SHORT VEGETATIVE PHASE (SVP)-like gene, belonging to the StMADS11 subfamily in the MADS-box family, was cloned from the early flowering P. fugax population (referred to as PfMADS16) and resistant to the herbicide clodinafop- propargyl. Overexpression of the SVP-like gene PfMADS16 in Arabidopsis thaliana resulted in early flowering and seed abortion. This is consistent with the phenotypic characters of resistant P. fugax plants, but contrary to the conventional role of SVP-like genes that usually suppress flowering. In addition, down regulation of the seed formation gene AtKTN1 in flowers of PfMADS16 transgenic Arabidopsis plants indicates that PfMADS16 may be indirectly associated with seed viability. Furthermore, one protein (PfMADS2) from the APETALA1 (AP1) subfamily interacting with PfMADS16 in P. fugax was identified with relevance to flowering time regulation. These results suggest that the PfMADS16 gene is an early flowering regulation gene associated with seed formation and viability in resistant P. fugax population. Our study provides potential application of PfMADS16 for integrated weed management (such as genetic-based weed control strategies) aiming to reduce the soil weed seedbank.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a4a8544f-2676-4632-9703-b1875fcca092', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Survey of herbicide-resistant wild oat (Avena fatua) in two townships in Saskatchewan', 'Hugh J. Beckie, A. G. Thomas, F. Craig Stevenson', 2002, 'Canadian Journal of Plant Science', '10.4141/p01-067', 'https://doi.org/10.4141/p01-067', 'https://cdnsciencepub.com/doi/pdf/10.4141/P01-067', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a0c228a6-a973-4eaf-9175-2d0019551cb0', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Unraveling genetic variation among white spruce families generated through different breeding strategies: Heritability, growth, physiology, hormones and gene expression', 'Galeano E, Thomas BR', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1052425', 'https://doi.org/10.3389/fpls.2023.1052425', 'https://europepmc.org/articles/PMC10106773?pdf=render', NULL, NULL, 20, NULL, 'alberta', 4, 'cc by', 'Tree improvement programs select genotypes for faster growth, at both early and late stages, to increase yields over unimproved material, and the improvement is frequently attributed to genetic control in growth parameters among genotypes. Underutilized genetic variability among genotypes also has the potential to ensure future gains are possible. However, the genetic variation in growth, physiology and hormone control among genotypes generated from different breeding strategies has not been well characterized in conifers. We assessed growth, biomass, gas exchange, gene expression and hormone levels in white spruce seedlings obtained from three different breeding strategies (controlled crosses, polymix pollination, open pollination) using parents grafted into a clonal seed orchard in Alberta, Canada. A pedigree-based best linear unbiased prediction (ABLUP) mixed model was implemented to quantify variability and narrow-sense heritability for target traits. The levels of several hormones and expression of gibberellin-related genes in apical internodes were also determined. Over the first two years of development, the estimated heritabilities for height, volume, total dry biomass, above ground dry biomass, root:shoot ratio and root length, varied between 0.10 and 0.21, with height having the highest value. The ABLUP values showed large genetic variability in growth and physiology traits both between families from different breeding strategies, and within families. The principal component analysis showed that developmental and hormonal traits explained 44.2% and 29.4% of the total phenotypic variation between the three different breeding strategies and two growth groups. In general, controlled crosses from the fast growth group showed the best apical growth, with more accumulation of indole-3-acetic acid, abscisic acid, phaseic acid, and a 4-fold greater gene expression of PgGA3ox1 in genotypes from controlled crosses versus those from open pollination. However, in some cases, open pollination from the fast and slow growth groups showed the best root development, higher water use efficiency (iWUE and δ13C) and more accumulation of zeatin and isopentenyladenosine. In conclusion, tree domestication can lead to trade-offs between growth, carbon allocation, photosynthesis, hormone levels and gene expression, and we encourage the use of this phenotypic variation identified in improved and unimproved trees to advance white spruce tree improvement programs.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7cba1c20-50e3-4674-9533-a3b59d2eca89', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Synthetic auxin herbicides: finding the lock and key to weed resistance', 'Olivia E. Todd, Marcelo Rodrigues Alves de Figueiredo, Sarah Morran, Neeta Soni, Christopher D. Preston, Martin Kubeš, Richard Napier, Todd Adam Gaines', 2020, 'Plant Science', '10.1016/j.plantsci.2020.110631', 'https://doi.org/10.1016/j.plantsci.2020.110631', 'http://wrap.warwick.ac.uk/140762/1/WRAP-synthetic-auxin-herbicides-finding-lock-key-weed-resistance-Napier-2020.pdf', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc-by', 'Synthetic auxin herbicides are designed to mimic indole-3-acetic acid (IAA), an integral plant hormone affecting cell growth, development, and tropism. In this review, we explore target site genes in the auxin signaling pathway including SCFTIR1/AFB, Aux/IAA, and ARFs that are confirmed or proposed mechanisms for weed resistance to synthetic auxin herbicides. Resistance to auxin herbicides by metabolism, either by enhanced cytochrome P450 detoxification or by loss of pro-herbicide activation, is a major non-target-site resistance pathway. We speculate about potential fitness costs of resistance due to effects of resistance-conferring mutations, provide insight into the role of polyploidy in synthetic auxin resistance evolution, and address the genetic resources available for weeds. This knowledge will be the key to unlock the long-standing questions as to which components of the auxin signaling pathway are most likely to have a role in resistance evolution. We propose that an ambitious research effort into synthetic auxin herbicide/target site interactions is needed to 1) explain why some synthetic auxin chemical families have activity on certain dicot plant families but not others and 2) fully elucidate target-site cross-resistance patterns among synthetic auxin chemical families to guide best practices for resistance management.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('560a7ff5-300d-452e-849c-7bfc5fd6edb2', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Target-site and non-target-site based resistance to the herbicide tribenuron-methyl in flixweed (Descurainia sophia L.)', 'Yang Q, Deng W, Li X, Yu Q, Bai L, Zheng M', 2016, 'BMC genomics', '10.1186/s12864-016-2915-8', 'https://doi.org/10.1186/s12864-016-2915-8', 'https://europepmc.org/articles/PMC4974779?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'BackgroundFlixweed (Descurainia sophia L.) is a troublesome and widespread broadleaf weed in winter fields in China, and has evolved high level resistance to acetolactate synthase (ALS)-inhibiting sulfonylurea herbicide tribenuron-methyl.ResultsWe identified a resistant flixweed population (N11) exhibiting 116.3-fold resistance to tribenuron-methyl relative to the susceptible population (SD8). Target-site ALS gene mutation Pro-197-Thr was identified in resistant plants. Moreover, the resistance can be reversed to 28.7-fold by the cytochrome P450 inhibitor malathion. The RNA-Sequencing was employed to identify candidate genes involved in non-target-site metabolic resistance in this population. Total 26 differentially expressed contigs were identified and eight of them (four P450s, one ABC transporter, three glycosyltransferase) verified by qRT-PCR. Consistent over-expression of the two contigs homology to CYP96A13 and ABCC1 transporter, respectively, were further qRT-PCR validated using additional plants from the resistant and susceptible populations.ConclusionsTribenuron-methyl resistance in flixweed is controlled by target-site ALS mutation and non-target-site based mechanisms. Two genes, CYP96A13 and ABCC1 transporter, could play an important role in metabolic resistance to tribenuron-methyl in the resistant flixweed population and justify further functional studies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2dda3f3-be20-4106-bb7c-f467d67238b0', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Trait Mapping Utilizing a Newly Constructed Genome for Allohexaploid Invasive Eurasian Watermilfoil (Myriophyllum spicatum) Reveals a Non-Target Site QTL Associated With Fluridone Resistance', 'Hannay D, Chorak GM, Harkess A, Clevenger J, Cuperus JT, Hale H, Aközbek L, Meharg Z', 2026, 'Evolutionary applications', '10.1111/eva.70193', 'https://doi.org/10.1111/eva.70193', 'https://europepmc.org/articles/PMC12789191?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'Herbicides are a valuable tool in agricultural ecosystems to manage nuisance species. Due to the reliance on herbicides for weed control, herbicide resistance is a growing concern. Herbicides are also used extensively in aquatic and natural systems, but the genetics and evolutionary dynamics of resistance are not as frequently incorporated into management plans in these systems. In Eurasian watermilfoil, a widespread and heavily managed invasive aquatic weed in the United States, clonal lineages have been characterized as resistant to fluridone, a commonly used phytoene desaturase (PDS)-inhibitor herbicide. In order to locate genomic loci associated with herbicide resistance, we created an F2 mapping population segregating for fluridone resistance. Using this population, we examined the pds gene for amino acid alterations in resistant individuals and performed bulk segregant analysis between the highly resistant and susceptible F2 individuals. Additionally, we compared pds gene expression between resistant and susceptible strains in control and treated environments using RT-qPCR. We found no evidence of amino acid alterations to the pds gene in fluridone resistant individuals or increased pds expression in the resistant strain, either in the presence or absence of fluridone. Our QTL mapping identified a putative QTL on chromosome seven, while the gene encoding fluridone''s target molecule, phytoene desaturase (PDS) is located on chromosomes 10-12. Our results indicate that fluridone resistance in the Eurasian watermilfoil strain isolated from Lake Lansing, MI, is due to at least one non-target site mechanism. Characterizing mechanisms of herbicide resistance within invasive plants enables effective and thoughtful herbicide usage, as well as the development of diagnostic biomarkers for resistance in unknown populations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f0cc5721-7d59-478b-9e37-858bcfd7719d', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Transfer of resistance alleles from herbicide-resistant to susceptible grass weeds via pollen-mediated gene flow', 'Amit J. Jhala, Hugh J. Beckie, Carol Ann Mallory-Smith, Marie Jasieniuk, Roberto Busi, Jason Keith Norsworthy, Muthukumar Bagavathiannan, Breanne D. Tidemann', 2021, 'Weed Technology', '10.1017/wet.2021.82', 'https://doi.org/10.1017/wet.2021.82', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/4791979BE60C1CAA9B4CFA9E8ADE2299/S0890037X21000828a.pdf/div-class-title-transfer-of-resistance-alleles-from-herbicide-resistant-to-susceptible-grass-weeds-via-pollen-mediated-gene-flow-div.pdf', NULL, NULL, 17, NULL, 'southern_alberta', 5, 'cc-by', 'Abstract The objective of this paper was to review the reproductive biology, herbicide-resistant (HR) biotypes, pollen-mediated gene flow (PMGF), and potential for transfer of alleles from HR to herbicide-susceptible grass weeds including barnyardgrass, creeping bentgrass, Italian ryegrass, johnsongrass, rigid (annual) ryegrass, and wild oats. The widespread occurrence of HR grass weeds is at least partly due to PMGF, particularly in obligate outcrossing species such as rigid ryegrass. Creeping bentgrass, a wind-pollinated turfgrass species, can efficiently disseminate herbicide resistance alleles via PMGF and movement of seeds and stolons. The genus Agrostis contains about 200 species, many of which are sexually compatible and produce naturally occurring hybrids and hybrids with species in the genus Polypogon . The self-incompatibility, extremely high outcrossing rate, and wind pollination in Italian ryegrass clearly point to PMGF as a major mechanism by which herbicide resistance alleles can spread across agricultural landscapes, resulting in abundant genetic variation within populations and low genetic differentiation among populations. Italian ryegrass can readily hybridize with perennial ryegrass and rigid ryegrass due to their similarity in chromosome numbers (2 n = 14), resulting in interspecific gene exchange. Johnsongrass, barnyardgrass, and wild oats are self-pollinated species, so the potential for PMGF is relatively low and limited to short distances; however, seeds can easily shatter upon maturity before crop harvest, leading to wider dispersal. The occurrence of PMGF in reviewed grass weed species, even at a low rate, is greater than that of spontaneous mutations conferring herbicide resistance in weeds and thus can contribute to the spread of herbicide resistance alleles. This review indicates that the transfer of herbicide resistance alleles occurs under field conditions at varying levels depending on the grass weed species.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ae138942-cce5-43aa-b452-631ff666733b', '8b12fc4f-ca5a-4aef-8583-d95caef5674f', 'Triallate-resistant wild oat (Avena fatua L.): Unexpected resistance to pyroxasulfone and sulfentrazone', 'Amy R. Mangin, Linda M. Hall, Hugh J. Beckie', 2016, 'Canadian Journal of Plant Science', '10.1139/cjps-2016-0029', 'https://doi.org/10.1139/cjps-2016-0029', 'https://cdnsciencepub.com/doi/pdf/10.1139/cjps-2016-0029', NULL, NULL, NULL, NULL, 'alberta', 4, NULL, NULL, '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4dc9219-72cb-4ba8-93d3-e315cbfed96f', '0037f418-c458-4fd4-98e4-292918e93b6e', 'A bibliometric review of triazine hybrids: synthesis, reactions, and applications spanning the last quarter-century (2000-2025)', 'Ali HA, Ismail MA, Ghaith EA', 2025, 'RSC advances', '10.1039/d5ra05849j', 'https://doi.org/10.1039/d5ra05849j', 'https://europepmc.org/articles/PMC12538292?pdf=render', NULL, NULL, 66, NULL, 'other', 1, 'cc by-nc', 'This comprehensive review delves into the intricate world of triazines, including their structures and the chemical diversity of their isomers. Additionally, this report encompasses a wide range of synthetic approaches, describing numerous reactions for attaining triazines, such as Bamberger, Bischler, inverse-electron-demand Diels-Alder, and Diels-Alder reactions. Moreover, this review describes the progress made in the chemistry of triazines, which is organized based on their reaction types, spotlighting the recent development. Accordingly, triazines stand out as a transformative strategy in the progress of synthetic chemistry due to their diverse applications in medicine, pharmacy, industry, and agriculture. Besides, triazine hybrids are important pharmacophores in the development of medications due to their captivating biological efficacy and biocompatibility. Consequently, this review presents a vast number of marketed drugs containing a triazine template while delineating their molecular mechanisms of action in disrupting disease pathways. Moreover, triazine cores are highlighted as flexible platforms for constructing and fine-tuning metal complexes and catalytic ligands in the period from 2000 to mid-2025. We anticipate that this review will be valuable to researchers focusing on the structural design and advancement of triazines.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('00b13059-132e-4e34-9948-7d360819ecdd', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Allelopathic Effects of Artemisia thuscula and Plocama pendula on the Invasive Plant Cenchrus setaceus and Crops', 'Fuvel A, Cosoveanu A, Sopena Lasala J, Ramón Arévalo J, Cabrera R', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14203159', 'https://doi.org/10.3390/plants14203159', 'https://europepmc.org/articles/PMC12567509?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Cenchrus setaceus is an alien invasive species with significant ecological impact on both natural ecosystems and agricultural areas across the Canary Islands. In this study, we evaluated the allelopathic effects of foliar lixiviates from two endemic species, Artemisia thuscula and Plocama pendula, on Cenchrus setaceus and a group of crop species to assess (i) germination inhibition of the invasive species and (ii) selectivity towards non-target crops. A preliminary trial tested undiluted and diluted forms (1%, 10%) of concentrated lixiviates prepared at a 1:3 (w:v) leaf-to-water ratio, using C. setaceus and Lactuca sativa under growth chamber conditions. In the validation trial, lixiviates prepared at a 1:6 (w:v) ratio were applied directly to C. setaceus and seven crops (Zea mays, Allium cepa, Hordeum vulgare, L. sativa, Solanum lycopersicum, Brassica oleracea, and Raphanus sativus) under both growth chamber and greenhouse conditions. Germination indices were calculated across assays, and plumule and radicle lengths were measured in growth chamber assays. In both trials, C. setaceus germination was inhibited by up to 60% by both ratios of lixiviates (Dunn p A. cepa and H. vulgare showed no significant inhibition; B. oleracea and R. sativus were affected by P. pendula (germination reduced 2.5-2.7×); and Z. mays, L. sativa, and S. lycopersicum exhibited delayed germination and reduced seedling growth under both treatments. These results support the selective use of native plant lixiviates for integrated management of Cenchrus setaceus in sensitive agroecosystems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('57ecc0db-7e97-4f6b-8d2a-fc503650de05', '699c7577-eb88-4579-895f-df444934cf8f', 'Cultivation-independent screening revealed hot spots of IncP-1, IncP-7 and IncP-9 plasmid occurrence in different environmental habitats', 'Dealtry S, Ding GC, Weichelt V, Dunon V, Schlüter A, Martini MC, Del Papa MF, Lagares A', 2014, 'PloS one', '10.1371/journal.pone.0089922', 'https://doi.org/10.1371/journal.pone.0089922', 'https://europepmc.org/articles/PMC3933701?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'IncP-1, IncP-7 and IncP-9 plasmids often carry genes encoding enzymes involved in the degradation of man-made and natural contaminants, thus contributing to bacterial survival in polluted environments. However, the lack of suitable molecular tools often limits the detection of these plasmids in the environment. In this study, PCR followed by Southern blot hybridization detected the presence of plasmid-specific sequences in total community (TC-) DNA or fosmid DNA from samples originating from different environments and geographic regions. A novel primer system targeting IncP-9 plasmids was developed and applied along with established primers for IncP-1 and IncP-7. Screening TC-DNA from biopurification systems (BPS) which are used on farms for the purification of pesticide-contaminated water revealed high abundances of IncP-1 plasmids belonging to different subgroups as well as IncP-7 and IncP-9. The novel IncP-9 primer-system targeting the rep gene of nine IncP-9 subgroups allowed the detection of a high diversity of IncP-9 plasmid specific sequences in environments with different sources of pollution. Thus polluted sites are "hot spots" of plasmids potentially carrying catabolic genes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('32a5a677-e380-477c-aeed-5729673ad904', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Alternative Biosorbents Based on Grape Pomace: Reducing Heavy Metals and Pesticides', 'Gabur GD, Dumitrașcu AI, Teodosiu C, Cotea VV, Gabur I', 2025, 'Toxics', '10.3390/toxics13050408', 'https://doi.org/10.3390/toxics13050408', 'https://europepmc.org/articles/PMC12116072?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Heavy metal and pesticide contaminations represent significant environmental and health hazards to humans and animals. Toxic heavy metals such as lead (Pb), cadmium (Cd), mercury (Hg), and copper (Cu) persist in the environment, bioaccumulating in beverages and food products from both natural and anthropogenic sources. Traditional remediation techniques, such as chemical precipitation and ion exchange, are effective but often costly and challenging to apply at a large scale. In recent years, grape pomace-a winemaking by-product rich in bioactive compounds-has emerged as a promising, low-cost biosorbent for the removal of such pollutants. Its high adsorption capacity, environmental friendliness, and availability make it a strong candidate for water and food decontamination processes. This study evaluates grape pomace and its biochar as sustainable biosorbents for heavy metal removal from water and soil, examining their adsorption efficiency, adsorption mechanisms, environmental benefits, advantages, limitations, and perspectives for future industrial-scale applications.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c11456c8-84d3-4de2-8edc-5db949533e7a', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Combined Pre- and Post-Emergence Herbicides for Effective Weed Control in Alfalfa (Medicago sativa L.)', 'Bao XR, Gao Y, Kim JW, Yook MJ, Kim DS, Zhang CJ', 2026, 'Plants (Basel, Switzerland)', '10.3390/plants15162461', 'https://doi.org/10.3390/plants15162461', 'https://europepmc.org/articles/PMC13516947?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'The scarcity of effective selective herbicides has made weed management a limiting factor for alfalfa yield and large-scale cultivation. This study aimed to preliminarily screen selective herbicides with acceptable safety to alfalfa and establish an effective weed management program based on sequential pre- and post-emergence herbicide applications through greenhouse screening and multi-year field trials. The greenhouse herbicide safety evaluation showed that, among the 22 herbicides tested, the post-application of 2 pre-emergence herbicides (s-metolachlor and prodiamine) and 5 post-emergence herbicides (benazolin, bentazon, fluazifop-p, imazethapyr, and nicosulfuron) showed a relatively higher survival rate (~4× the standard dose) on two alfalfa cultivars through assessing visual efficacy, plant height, and dry biomass per plant. However, even herbicides that result in relatively high plant survival can produce induce significant growth inhibition and biomass reduction when applied at high doses. Those herbicides were further tested under field conditions (2020-2023) for evaluation of weed control efficiency and alfalfa plant biomass yield potential and nutritive values. Among the herbicide application regimes, the pre-application of prodiamine followed by post-application of bentazon or fluazifop-p showed the most effective weed control efficacy (70-85% reduction of weed biomass in the alfalfa plot), which was greater than the reductions achieved with all single-herbicide applications (24-48%) and sequential application of s-metolachlor followed by the five post-emergence herbicides (25-46%). Additionally, the optimized combinations had no significant effect on the 1st and subsequent alfalfa plant height compared to that of alfalfa in weed-free control. No significant reductions in alfalfa yield or nutritive value were observed in the herbicide-treated plots treated with prodiamine followed by bentazon or fluazifop-p compared with the weed-free control. Collectively, sequential application combining pre- (prodiamine) and post-emergence (bentazon or fluazifop-p) herbicides shows effective weed control in alfalfa under the tested conditions, which provides a useful weed management program to enhance alfalfa forage production and nutritive values.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6ca71f14-2cc8-4670-9fc6-1650d8e1bb95', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Diuron, hexazinone, and sulfometuron-methyl applied alone and in mixture in soils: Distribution of extractable residue, bound residue, biodegradation, and mineralization', 'Cristina Dos Reis F, Mielke KC, Mendes KF, Nogueira de Sousa R, Heluany MH, Tornisielo VL, Filho RV', 2023, 'Heliyon', '10.1016/j.heliyon.2023.e17817', 'https://doi.org/10.1016/j.heliyon.2023.e17817', 'https://europepmc.org/articles/PMC10344761?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'Biodegradation studies of herbicides applied to the soil alone and in a mixture are required since herbicides are often used in combinations to control weeds. When herbicides are applied in mixtures, interactions may affect their environmental fate. Thus, the objective of this study was to evaluate the distribution of extractable residue, bound residue, biodegradation, and mineralization of diuron, hexazinone, and sulfometuron-methyl when applied alone and in a mixture in two agricultural soils. Biometric flasks filled with two types of soil (clay and sandy) collected from an area cultivated with sugarcane and treated with 14C-radiolabeled solutions of the herbicides were incubated for 70 d. More 14C-CO2 was released when sulfometuron-methyl and hexazinone were applied in a mixture compared to when applied alone. Being used in a combination did not affect the mineralization of diuron. The soil texture directly influenced the mineralization, bound residue, and extractable residue of the three herbicides. The percentage of extractable residue decreased over time for all herbicides. Hexazinone and sulfometuron-methyl had the highest residue extracted on sandy soil when applied alone. Diuron showed the highest percentage of bound residue. The degradation of the three herbicides was higher in the clay soil regardless of the mode of application, which is related to the higher potential of the bacterial community in the clay soil to mineralize the herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a15fa5d-663e-409a-8759-ea17809a0775', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Herbicide resistance distribution in Echinochloa colona in Texas rice production', 'Rui Liu, Prabhu Govindasamy, Vijay Singh, Muthukumar V. Bagavathiannan', 2025, 'Weed Technology', '10.1017/wet.2025.10048', 'https://doi.org/10.1017/wet.2025.10048', 'https://www.cambridge.org/core/product/identifier/S0890037X25100481/type/journal_article', NULL, NULL, 8, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Species in the genus Echinochloa present a major management challenge in rice production worldwide. Understanding the herbicide resistance status of Echinochloa is crucially necessary for raising awareness and developing effective management programs. This study investigated the status of herbicide resistance by junglerice, the predominant Echinochloa species in Texas rice fields. A total of 58 junglerice populations collected during a field survey (2015–2016) of Texas rice fields were screened with two preemergence herbicides; quinclorac (Group 4) and clomazone (Group 13); and four postemergence herbicides: fenoxaprop (Group 1), imazethapyr (Group 2), quinclorac (Group 4), and propanil (Group 5). At 21 d after application (DAA) of herbicide treatments, percent survival, and percent visible injury data were recorded. Based on the injury levels observed, the populations were categorized into being either putative resistant (≤50% injury), less sensitive (51% to 90% injury), or susceptible (≥91% injury). Results showed that herbicide resistance is widespread among the junglerice populations surveyed in Texas. About 5% of the populations showed multiple resistance to all four postemergence herbicides that were evaluated. Dose-response assays were conducted on the populations with the lowest injury ratings to determine the extent of resistance and revealed a >70-fold resistance to imazethapyr, a >15-fold resistance to propanil, and a 3-fold resistance to fenoxaprop, compared with a susceptible check. The results suggested that integrated management practices are needed to manage junglerice in Texas rice production.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec20218d-32f5-47dd-8fe5-34f585ef4a3a', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Natural Plant Extracts: An Update about Novel Spraying as an Alternative of Chemical Pesticides to Extend the Postharvest Shelf Life of Fruits and Vegetables', 'Shahbaz MU, Arshad M, Mukhtar K, Nabi BG, Goksen G, Starowicz M, Nawaz A, Ahmad I', 2022, 'Molecules (Basel, Switzerland)', '10.3390/molecules27165152', 'https://doi.org/10.3390/molecules27165152', 'https://europepmc.org/articles/PMC9416025?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Fresh fruits and vegetables, being the source of important vitamins, minerals, and other plant chemicals, are of boundless importance these days. Although in agriculture, the green revolution was a milestone, it was accompanied by the intensive utilization of chemical pesticides. However, chemical pesticides have hazardous effects on human health and the environment. Therefore, increasingly stimulating toward more eco-friendly and safer alternatives to prevent postharvest losses and lead to improving the shelf life of fresh fruits and vegetables. Proposed alternatives, natural plant extracts, are very promising due to their high efficacy. The plant-based extract is from a natural source and has no or few health concerns. Many researchers have elaborated on the harmful effects of synthetic chemicals on human life. People are now much more aware of safety and health concerns than ever before. In the present review, we discussed the latest research on natural alternatives for chemical synthetic pesticides. Considering that the use of plant-based extracts from aloe vera, lemongrass, or neem is non-chemical by-products of the fruits and vegetable industry, they are proved safe for human health and may be integrated with economic strategies. Such natural plant extracts can be a good alternative to chemical pesticides and preservatives.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a7d4e69-1ad8-484b-b828-3a080ffe45a2', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Ecological Integrity Impairment and Habitat Fragmentation for Neotropical Macroinvertebrate Communities in an Agricultural Stream', 'Echeverría-Sáenz S, Ugalde-Salazar R, Guevara-Mora M, Quesada-Alvarado F, Ruepert C', 2022, 'Toxics', '10.3390/toxics10070346', 'https://doi.org/10.3390/toxics10070346', 'https://europepmc.org/articles/PMC9316105?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The Volcán River watershed in the south Pacific of Costa Rica comprises forests, small urban settlements, cattle fields, and intensive agriculture (mostly pineapple and sugarcane). The ecological integrity and quality of its waters was assessed from 2011-2013 and 2018-2019 by means of physical-chemical parameters (pH, conductivity, temperature, DO, DBO, nitrate, total phosphorus, and pesticide residues) and benthic macroinvertebrate (MI) sampling in eight sites (Volcán, Cañas, and Ángel Rivers, and Peje and Maura streams), resulting in high ecological integrity in all sites except the Peje stream, which is polluted with nitrates and pesticides. Only in this stream was there a marked seasonal variation in the abundance of 16 MI families including Leptohyphidae, Leptophlebiidae, Philopotamidae, Glossossomatidae, and Corydalidae, among others, whose presence was limited exclusively to the dry season (December to April), disappearing from the stream in the rainy season, with corresponding peaks in nitrate (max 20.3 mg/L) and pesticides (mainly herbicides and organophosphate insecticides). The characteristics of the watershed, with large areas of forest and excellent water quality, allow for the re-colonization of organisms into the Peje stream; however, those organisms are incapable of development and growth, providing evidence of a contaminant-driven habitat fragmentation in this stream during the rainy season.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f534ec8e-e8cb-43b8-9245-2ee99ec2a81e', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Herbicidal weed management practices: History and future prospects of nanotechnology in an eco-friendly crop production system', 'Paul S, Mazumder S, Naidu R', 2024, 'Heliyon', NULL, 'https://europepmc.org/articles/PMC10912261?pdf=render', 'https://europepmc.org/articles/PMC10912261?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', NULL, '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c07d9187-25fd-4c3a-b7a5-ee0d1ca50210', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Influence of the agrochemicals used for rice and vegetable cultivation on insecticide resistance in malaria vectors in southern Côte d''Ivoire', 'Chouaïbou MS, Fodjo BK, Fokou G, Allassane OF, Koudou BG, David JP, Antonio-Nkondjio C, Ranson H', 2016, 'Malaria journal', '10.1186/s12936-016-1481-5', 'https://doi.org/10.1186/s12936-016-1481-5', 'https://europepmc.org/articles/PMC4995742?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'BackgroundVector control can contribute to the development of resistance to insecticides in malaria vectors. As the swamps and wetlands used for some agricultural activities constitute productive breeding sites for many mosquito species, agricultural pest control may increase the selection pressure for insecticide resistance in mosquitoes. Understanding the use of agrochemicals by farmers is important to plan and initiate effective integrated pest and vector management interventions.MethodsA knowledge-attitude-practice study, using questionnaires, was undertaken with 102 rice farmers in Tiassalé and 106 vegetable farmers in Dabou (South Côte d''Ivoire) in order to generate information on pesticide usage. In addition, insecticide susceptibility bioassays were conducted using adult mosquitoes obtained from larvae collected within farms, and the persistence of agricultural pesticides in the farming environment, including sediment and mosquito breeding site water, was investigated by HPLC.ResultsHerbicides and insecticides appeared to be the most frequently used pesticides for both crops. Amino phosphonates (mostly glyphosate) represented the most used herbicides (45 % for rice up to 89 % for vegetables). Pyrethroids appeared to be the most used insecticides (accounting for 90 % of all the insecticide use reported). Approximately 75 % of respondents had not been to school and do not understand product labels. Only about 45 % of farmers respect the recommended pesticide dosage and about 10-15 % of pesticides used for rice and vegetable, respectively, are not recommended for these crops. As per WHO criteria, the mosquito local populations from the two localities were resistant to three of the four insecticides tested, as mortalities were less than 35 % for deltamethrin, DDT and bendiocarb. Higher susceptibility was observed for malathion, although the population was considered resistant in Dabou (80 % mortality) and susceptible in Tiassalé (98 % mortality). With the exception of glyphosate, residues from each of six chemicals tested for were detected in each of the sites visited in the two localities.ConclusionThe study describes the use of insecticides and herbicides on crops and highlights the importance of considering agriculture practices when attempting to manage resistance in malaria vectors. Inter-sectoral collaboration between agriculture and public health is required to develop efficient integrated pest and vector management interventions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('462f5504-55fd-4499-a2f5-6ad51c60eaa4', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Marketable and Banned Pesticides in Agriculture: Categorization, Simulation, and Crystallography Review', 'Kyriakopoulos GL, Sebos I', 2024, 'International journal of molecular sciences', '10.3390/ijms252211885', 'https://doi.org/10.3390/ijms252211885', 'https://europepmc.org/articles/PMC11594467?pdf=render', NULL, NULL, 43, NULL, 'other', 1, 'cc by', 'Pesticides are playing a dominant role in modern cultivation practices to increase agricultural production but are also criticized for environmental depletion and soil and underground water degradation in field applications. An imperative need for greener pesticides has emerged in alignment with new innovations in agrarian and agricultural practices. This study provides a comprehensive review of marketable and banned pesticides that have been applied in past times or are still in use in agriculture. The collected literature production disclosed 35 distinct pesticides that were identified either isolated or in mixtures and residues. These pesticides are primarily applied in agricultural fields, but some of them were also criticized for human implications. Then, these 35 pesticides were grouped into four categories: insecticides (18), herbicides (9), fungicides (6), and acaricides (2). Furthermore, their molecular types, chemical structures, pKa or log Kow values were presented. Based on their chemical structure, the pesticides were also organized into two domains: "marketable simulated" and "banned simulated", representing 43% and 57% of total pesticides, respectively. The simulations were generated by linking the elemental composition of each pesticide in the corresponding category; therefore, three "marketable simulated" (the acaricides were not marketable representative) and four "banned simulated" were demonstrated. In addition, the calculation of "adjustment factors" (-0.33 up to +0.50) and the "as calculated/marketable (or banned) simulated pesticides" ratios (0.946 up to 1.013) enabled the identification of four clusters of homogeneous characteristics: cluster 1: "Insecticides, Fungicides, marketable", cluster 2: "Herbicides, marketable", cluster 3: "Insecticides, Fungicides, banned", and cluster 4: "Acaricides, Herbicides, banned". Subsequently, the composition of the elements of C and H enabled the crystallography characterization of only the "marketable" pesticides, not those that are "banned", with compounds that have been already registered in the "Crystallography Open Database". Conclusively, implications, challenges, and future research recommendations have been proposed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff05b024-e29f-44d6-99aa-20ce1a48e185', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Multidimensional characterization of heterogeneity in pesticide co-exposure patterns', 'Su H, Zhang L, Tian W, Lu B, Guo X, Liu Y', 2026, 'Frontiers in chemistry', '10.3389/fchem.2026.1890266', 'https://doi.org/10.3389/fchem.2026.1890266', 'https://europepmc.org/articles/PMC13522405?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'ObjectivesThis study analyzed clinical data from 1641 pesticide-exposed patients screened for a total of 159 pesticide compounds admitted to Shandong First Medical University Affiliated Provincial Hospital from 1 January 2023 to 31 December 2024, aiming to elucidate the multidimensional heterogeneity of pesticide co-exposure patterns.MethodsClinical information and biological samples were collected from all participants. Pesticide detection was performed using Agilent 7890B-7250 Q-TOF/MS and AB SCIEX Triple Quad 4500MD mass spectrometry systems. Seasonal, gender-specific, and age-group variations in pesticide exposure were assessed, and a co-occurrence network was constructed to evaluate concurrent exposure patterns and concentration distributions.ResultsHerbicides exhibited the highest exposure prevalence within their respective tested sub-cohorts. Specifically, glyphosate showed a targeted detection frequency of 49.32% (144/292) among the screened individuals. Concentration peaks for glyphosate and paraquat occurred between July and September, with median levels reaching 3.42 and 3.15 log10 μg/L, respectively. Pesticide exposure displayed a bimodal age distribution, with a secondary peak among individuals aged 15-20 years and a primary peak in those aged 55-60 years. In the 40-55 age group, male exposure prevalence was significantly higher than female (male-to-female ratio: 2.8:1). Network analysis identified 38 significant co-occurrence patterns (r > 0.5, P ConclusionThis study reveals distinct multidimensional heterogeneity in pesticide exposure, providing critical evidence for developing targeted intervention strategies. Tailored protective measures based on seasonal trends, gender-age subgroups, and prevalent co-exposure patterns may more effectively mitigate pesticide-related risks among agricultural populations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ba2e4f66-0fd1-4243-9560-db6e18173af0', '699c7577-eb88-4579-895f-df444934cf8f', 'Current Trends for Lavender (Lavandula angustifolia Mill.) Crops and Products with Emphasis on Essential Oil Quality', 'Crișan I, Ona A, Vârban D, Muntean L, Vârban R, Stoie A, Mihăiescu T, Morea A', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12020357', 'https://doi.org/10.3390/plants12020357', 'https://europepmc.org/articles/PMC9861439?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Lavender is in the research spotlight due to its increasing economic importance, while market demand is expected to continue to grow. Among the hundreds of essential-oil-bearing plants, Lavandula angustifolia Mill. remains one of the most valuable. This paper explores the lavender chain timeline from crop to products, examining the expanding knowledge on the characteristics, phytochemical profile and functional potential of lavender that could lead to new products and uses. Lavender crops can be expanded without competing for productive land, instead using marginal, contaminated or unproductive land. A novel cultivation trend proposes leveraging agri-background biodiversity, arbuscular mycorrhiza and the natural enemies of pests for healthy crops. Together with breeding efforts targeting highly performant genotypes with complex volatile profiles coupled with resistance to specific biotic (particularly Phytoplasma) and abiotic (salt, heavy metals) stressors, industry could have a steady supply of high-quality raw material. Besides the expansion of the uses of essential oil in cosmetics, pharmaceuticals, food and environmental and agri-applications, novel channels have appeared for the use of the solid by-product, which is rich in polyphenols and polysaccharides; these channels have the potential to create additional streams of value. The stabilization and optimization of techno-functional delivery systems through the encapsulation of essential oil can extend shelf-life and enhance biological activity efficiency.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('02328fee-9f27-4f16-843c-c3a20732d879', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Non-Targeted and Targeted Analysis of Organic Micropollutants in Agricultural Soils Across China: Occurrence and Risk Evaluation', 'Xu C, Qiu Y, Chen W, Liu N, Yang X', 2025, 'Toxics', '10.3390/toxics14010025', 'https://doi.org/10.3390/toxics14010025', 'https://europepmc.org/articles/PMC12845987?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Organic micropollutants in agricultural soils pose significant ecological and health risks. This study conducted the first large-scale, integrated non-targeted screening and targeted analysis across China''s major food-producing regions. Using high-resolution mass spectrometry, 498 micropollutants were identified, including pesticides, industrial chemicals, pharmaceuticals, personal care products, food additives, natural products, and emerging contaminants. Spatial analysis revealed strong correlations in pesticide detections between Henan and Hebei, as well as between Hebei and Shandong, indicating pronounced regional similarities in pesticide occurrence patterns. Concentrations of 50 quantified micropollutants showed clear spatial variability, which was associated with precipitation, water use, and agricultural output, reflecting climate-agriculture-socioeconomic synergies. Greenhouse soils accumulated higher micropollutant levels than open fields, driven by intensive agrochemical inputs, plastic-film confinement, and reduced phototransformation. Co-occurrence patterns indicated similar pathways for personal care products, industrial chemicals, and pesticides, whereas natural products and pharmaceuticals showed lower levels of co-occurrence due to crop-specific exudates, fertilization, and rainfall-driven leaching. Among cropping systems, orchard soils had the highest micropollutant accumulation, followed by paddy and vegetable soils, consistent with frequent pesticide use and minimal tillage. Risk quotients indicated moderate-to-high ecological risks at over half of the sites. These results reveal complex soil pollution patterns and highlight the need for dynamic inventories and spatially differentiated, crop- and system-specific mitigation strategies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a495d08-7d54-4209-8730-ee00d1717db2', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Plant Growth-Promoting Bacteria (PGPB) integrated phytotechnology: A sustainable approach for remediation of marginal lands', 'Poria V, Dębiec-Andrzejewska K, Fiodor A, Lyzohub M, Ajijah N, Singh S, Pranaw K', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.999866', 'https://doi.org/10.3389/fpls.2022.999866', 'https://europepmc.org/articles/PMC9634634?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Land that has little to no utility for agriculture or industry is considered marginal land. This kind of terrain is frequently found on the edge of deserts or other arid regions. The amount of land that can be used for agriculture continues to be constrained by increasing desertification, which is being caused by climate change and the deterioration of agriculturally marginal areas. Plants and associated microorganisms are used to remediate and enhance the soil quality of marginal land. They represent a low-cost and usually long-term solution for restoring soil fertility. Among various phytoremediation processes (viz., phytodegradation, phytoextraction, phytostabilization, phytovolatilization, phytofiltration, phytostimulation, and phytodesalination), the employment of a specific mechanism is determined by the state of the soil, the presence and concentration of contaminants, and the plant species involved. This review focuses on the key economically important plants used for phytoremediation, as well as the challenges to plant growth and phytoremediation capability with emphasis on the advantages and limits of plant growth in marginal land soil. Plant growth-promoting bacteria (PGPB) boost plant development and promote soil bioremediation by secreting a variety of metabolites and hormones, through nitrogen fixation, and by increasing other nutrients'' bioavailability through mineral solubilization. This review also emphasizes the role of PGPB under different abiotic stresses, including heavy-metal-contaminated land, high salinity environments, and organic contaminants. In our opinion, the improved soil fertility of marginal lands using PGPB with economically significant plants (e.g., Miscanthus) in dual precession technology will result in the reclamation of general agriculture as well as the restoration of native vegetation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec0590cf-c828-4e16-949b-73a7d523563c', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Probabilistic comparisons of grey water footprint models for herbicide mixtures in Brazilian sugarcane', 'Paraíba LC', 2026, 'Environmental science and pollution research international', '10.1007/s11356-026-38125-9', 'https://doi.org/10.1007/s11356-026-38125-9', 'https://europepmc.org/articles/PMC13503512?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The grey water footprint (GWF) quantifies freshwater pollution from pesticide use. The H-model relies on regulatory concentration limits, while the P-model uses ecotoxicological endpoints and concentration addition (CA); independent action (IA) across modes of action (MOA) remains underexplored. We present a fully re-verified probabilistic Monte Carlo comparison of CA and HRAC-based IA P-models for 17 herbicides applied to Brazilian sugarcane, built exclusively from traceable, source-cited inputs, including a soil attenuation factor recomputed from first principles and maximum acceptable concentrations compiled from five source tiers. Total grey water footprint is 2.3×1012 m 3 under both CA and IA, with HRAC group C1 dominating in 100% of Monte Carlo iterations. The P-model exceeds the H-model by a factor R of 7 to 20 depending on data quality. Carfentrazone''s score rises from 1.5 to 4.9 once group membership is considered, and group E2''s hazard is driven mainly by oxyfluorfen. We report this audit trail transparently, prioritising numerical traceability over a single headline figure.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('95a4cde2-80b6-4d88-bd26-977f04a281fc', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Pyrolysis Temperature vs. Application Rate of Biochar Amendments: Impacts on Soil Microbiota and Metribuzin Degradation', 'Mielke KC, Brochado MGDS, Laube AFS, Guimarães T, Medeiros BAP, Mendes KF', 2023, 'International journal of molecular sciences', '10.3390/ijms241311154', 'https://doi.org/10.3390/ijms241311154', 'https://europepmc.org/articles/PMC10342882?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Biochar-amended soils influence the degradation of herbicides depending on the pyrolysis temperature, application rate, and feedstock used. The objective of this study was to evaluate the influence of sugarcane straw biochar (BC) produced at different pyrolysis temperatures (350 °C, 550 °C, and 750 °C) and application rates in soil (0, 0.1, 0.5, 1, 1.5, 5, and 10% w/w) on metribuzin degradation and soil microbiota. Detection analysis of metribuzin in the soil to find time for 50% and 90% metribuzin degradation (DT50 and DT90) was performed using high-performance liquid chromatography (HPLC). Soil microbiota was analyzed by respiration rate (C-CO2), microbial biomass carbon (MBC), and metabolic quotient (qCO2). BC350 °C-amended soil at 10% increased the DT50 of metribuzin from 7.35 days to 17.32 days compared to the unamended soil. Lower application rates (0.1% to 1.5%) of BC550 °C and BC750 °C decreased the DT50 of metribuzin to ~4.05 and ~5.41 days, respectively. BC350 °C-amended soil at high application rates (5% and 10%) provided high C-CO2, low MBC fixation, and high qCO2. The addition of low application rates (0.1% to 1.5%) of sugarcane straw biochar produced at high temperatures (BC550 °C and BC750 °C) resulted in increased metribuzin degradation and may influence the residual effect of the herbicide and weed control efficiency.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('941d23ba-02a5-4f75-8ed5-6d515b224573', '0037f418-c458-4fd4-98e4-292918e93b6e', 'Toxicity of herbicides to the marine microalgae Tisochrysis lutea and Tetraselmis sp', 'Flores F, Stapp LS, van Dam J, Fisher R, Kaserzon S, Negri AP', 2024, 'Scientific reports', '10.1038/s41598-024-51401-3', 'https://doi.org/10.1038/s41598-024-51401-3', 'https://europepmc.org/articles/PMC10798944?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Pesticides are ubiquitous in the catchments of the Great Barrier Reef (GBR) and regularly discharge into the nearshore waters. Effective management of pesticides requires suitable water quality guideline values (WQGVs), and further ecotoxicological data for many pesticides are needed to improve the reliability of environmental risk assessments. To help address this issue, toxicity thresholds were determined to two species of tropical marine microalgae Tisochrysis lutea and Tetraselmis sp. for a suite of herbicides detected in the GBR. Photosystem II (PSII) herbicides significantly reduced growth with no effect concentration (NEC) and 10% effect concentration (EC10) values spanning two orders of magnitude from 0.60 µg L-1 for diuron to 60 µg L-1 for simazine across both species. However, growth was insensitive to the non-PSII herbicides. The NEC/EC10 thresholds for most herbicide-microalgae combinations were greater than recent WQGVs intended to protect 99% of species (PC99); however, metribuzin was toxic to T. lutea at concentrations lower than the current PC99 value, which may have to be revisited. The toxicity thresholds for alternative herbicides derived here further inform the development of national and GBR-specific WQGVs, but more toxicity data is needed to develop WQGVs for the > 50 additional pesticides detected in catchments of the GBR.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('65644011-26ad-4146-a01b-0e5129992abc', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'A New Ala-122-Asn Amino Acid Change Confers Decreased Fitness to ALS-Resistant Echinochloa crus-galli', 'Panozzo S, Scarabel L, Rosan V, Sattin M', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.02042', 'https://doi.org/10.3389/fpls.2017.02042', 'https://europepmc.org/articles/PMC5712356?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Gene mutations conferring herbicide resistance may cause pleiotropic effects on plant fitness. Knowledge of these effects is important for managing the evolution of herbicide-resistant weeds. An Echinochloa crus-galli population resistant to acetolactate synthase (ALS) herbicides was collected in a maize field in north-eastern Italy and the cross-resistance pattern, resistance mechanism and fitness costs associated to mutant-resistant plants under field conditions in the presence or absence of intra-specific competition were determined. The study reports for the first time the Ala-122-Asn amino-acid change in the ALS gene that confers high levels of cross-resistance to all ALS inhibitors tested. Results of 3-year growth analysis showed that mutant resistant E. crus-galli plants had a delayed development in comparison with susceptible plants and this was registered in both competitive (3, 7, and 20 plants m-2) and non-competitive (spaced plants) situations. The number of panicles produced by resistant plants was also lower (about 40% fewer panicles) than susceptible plants under no-intraspecific competition. Instead, with the increasing competition level, the difference in panicle production at harvest time decreased until it became negligible at 20 plants m-2. Evaluation of total dry biomass as well as biomass allocation in vegetative parts did not highlight any difference between resistant and susceptible plants. Instead, panicle dry weight was higher in susceptible plants indicating that they allocated more biomass than resistant ones to the reproductive organs, especially in no-competition and in competition situations at lower plant densities. The different fitness between resistant and susceptible phenotypes suggests that keeping the infestation density as low as possible can increase the reproduction success of the susceptible phenotype and therefore contribute to lowering the ratio between resistant and susceptible alleles. If adequately embedded in a medium or long-term integrated weed management strategy, the presence of R plants with a fitness penalty provides an opportunity to minimize or reverse herbicide resistance evolution through the implementation of integrated weed management, i.e., all possible control tools available.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('55431ad6-d08f-49b7-b9a5-bcb18b9a5927', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Application of CRISPR/Cas9-mediated gene editing for abiotic stress management in crop plants', 'Kumar M, Prusty MR, Pandey MK, Singh PK, Bohra A, Guo B, Varshney RK', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1157678', 'https://doi.org/10.3389/fpls.2023.1157678', 'https://europepmc.org/articles/PMC10153630?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Abiotic stresses, including drought, salinity, cold, heat, and heavy metals, extensively reducing global agricultural production. Traditional breeding approaches and transgenic technology have been widely used to mitigate the risks of these environmental stresses. The discovery of engineered nucleases as genetic scissors to carry out precise manipulation in crop stress-responsive genes and associated molecular network has paved the way for sustainable management of abiotic stress conditions. In this context, the clustered regularly interspaced short palindromic repeat-Cas (CRISPR/Cas)-based gene-editing tool has revolutionized due to its simplicity, accessibility, adaptability, flexibility, and wide applicability. This system has great potential to build up crop varieties with enhanced tolerance against abiotic stresses. In this review, we summarize the latest findings on understanding the mechanism of abiotic stress response in plants and the application of CRISPR/Cas-mediated gene-editing system towards enhanced tolerance to a multitude of stresses including drought, salinity, cold, heat, and heavy metals. We provide mechanistic insights on the CRISPR/Cas9-based genome editing technology. We also discuss applications of evolving genome editing techniques such as prime editing and base editing, mutant library production, transgene free and multiplexing to rapidly deliver modern crop cultivars adapted to abiotic stress conditions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cbed890c-d653-4bd2-8b1f-625ae2ba523e', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Assessment of genetic diversity among barley cultivars and breeding lines adapted to the US Pacific Northwest, and its implications in breeding barley for imidazolinone-resistance', 'Rustgi S, Matanguihan J, Mejías JH, Gemini R, Brew-Appiah RA, Wen N, Osorio C, Ankrah N', 2014, 'PloS one', '10.1371/journal.pone.0100998', 'https://doi.org/10.1371/journal.pone.0100998', 'https://europepmc.org/articles/PMC4072767?pdf=render', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'Extensive application of imidazolinone (IMI) herbicides had a significant impact on barley productivity contributing to a continuous decline in its acreage over the last two decades. A possible solution to this problem is to transfer IMI-resistance from a recently characterized mutation in the ''Bob'' barley AHAS (acetohydroxy acid synthase) gene to other food, feed and malting barley cultivars. We focused our efforts on transferring IMI-resistance to barley varieties adapted to the US Pacific Northwest (PNW), since it comprises ∼23% (335,000 ha) of the US agricultural land under barley production. To effectively breed for IMI-resistance, we studied the genetic diversity among 13 two-rowed spring barley cultivars/breeding-lines from the PNW using 61 microsatellite markers, and selected six barley genotypes that showed medium to high genetic dissimilarity with the ''Bob'' AHAS mutant. The six selected genotypes were used to make 29-53 crosses with the AHAS mutant and a range of 358-471 F1 seeds were obtained. To make informed selection for the recovery of the recipient parent genome, the genetic location of the AHAS gene was determined and its genetic nature assessed. Large F2 populations ranging in size from 2158-2846 individuals were evaluated for herbicide resistance and seedling vigor. Based on the results, F3 lines from the six most vigorous F2 genotypes per cross combination were evaluated for their genetic background. A range of 20%-90% recovery of the recipient parent genome for the carrier chromosome was observed. An effort was made to determine the critical dose of herbicide to distinguish between heterozygotes and homozygotes for the mutant allele. Results suggested that the mutant can survive up to the 10× field recommended dose of herbicide, and the 8× and 10× herbicide doses can distinguish between the two AHAS mutant genotypes. Finally, implications of this research in sustaining barley productivity in the PNW are discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('17f6920d-48ef-4849-85f5-aa31087e8f40', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Characterization of Cytochrome P450s with Key Roles in Determining Herbicide Selectivity in Maize', 'Brazier-Hicks M, Franco-Ortega S, Watson P, Rougemont B, Cohn J, Dale R, Hawkes TR, Goldberg-Cavalleri A', 2022, 'ACS omega', '10.1021/acsomega.2c01705', 'https://doi.org/10.1021/acsomega.2c01705', 'https://europepmc.org/articles/PMC9134415?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Safeners such as metcamifen and benoxacor are widely used in maize to enhance the selectivity of herbicides through the induction of key detoxifying enzymes, notably cytochrome P450 monooxygenases (CYPs). Using a combination of transcriptomics, proteomics, and functional assays, the safener-inducible CYPs responsible for herbicide metabolism in this globally important crop have been identified. A total of 18 CYPs belonging to clans 71, 72, 74, and 86 were safener-induced, with the respective enzymes expressed in yeast and screened for activity toward thiadiazine (bentazon), sulfonylurea (nicosulfuron), and triketone (mesotrione and tembotrione) chemistries. Herbicide metabolism was largely restricted to family CYP81A members from clan 71, notably CYP81A9, CYP81A16, and CYP81A2. Quantitative transcriptomics and proteomics showed that CYP81A9/CYP81A16 were dominant enzymes in safener-treated field maize, whereas only CYP81A9 was determined in sweet corn. The relationship between CYP81A sequence and activities were investigated by splicing CYP81A2 and CP81A9 together as a series of recombinant chimeras. CYP81A9 showed wide ranging activities toward the three herbicide chemistries, while CYP81A2 uniquely hydroxylated bentazon in multiple positions. The plasticity in substrate specificity of CYP81A9 toward multiple herbicides resided in the second quartile of its N terminal half. Further phylogenetic analysis of CYP81A9 showed that the maize enzyme was related to other CYP81As linked to agrochemical metabolism in cereals and wild grasses, suggesting this clan 71 CYP has a unique function in determining herbicide selectivity in arable crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('834fde00-4d49-4688-819d-482a17497daf', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Confirmation of Multiple Resistant Chloris radiata Population, Harvested in Colombian Rice Fields', 'Verónica Hoyos, Guido Plaza, José G. Vázquez-Garcia, Candelario Palma-Bautista, Antonia M. Rojano-Delgado, Rafael De Prado', 2021, 'Agronomy', '10.3390/agronomy11030496', 'https://doi.org/10.3390/agronomy11030496', 'https://www.mdpi.com/2073-4395/11/3/496', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'This paper reports the first C. radiata population with resistance to glyphosate and multiple resistance to the acetolactate synthase (ALS) inhibitor, imazamox. Two populations, one putative resistant (R) and one susceptible (S), were used in the studies. Dose–response experiments were performed to evaluate the resistance factor (RF). Shikimic acid accumulation, 5-enolpyruvylshikimate-3-phosphate synthase (EPSPS) and ALS enzyme activities were studied together with chemical integrated weed management (adjuvants and alternative herbicides). The resistance to glyphosate and imazamox was confirmed based on the dry weight reduction, visual evaluation and survival. The results of dose–response curve assays showed for the R population intermedium RF for glyphosate (5.1 and 9.7 for amount of herbicide needed to reduce the dry weight by 50% GR50 and lethal dose of 50% LD50, respectively) and high RF for imazamox (34.9 and 37.4, respectively). The low shikimic acid accumulation in R population confirmed the glyphosate resistance. The glyphosate concentration which inhibited the EPSPS enzyme in 50% (I50) was approximately 20 times higher for R population than the S population, while the imazamox I50 in ALS enzyme for the R plants was 89 times greater than the S plants. In the chemical integrated weed management, the foliar retention and effectivity assays showed that the use of adjuvants improves the retention of glyphosate and imazamox, and the reduction in dry weight of weeds. The alternative herbicides study showed that the acetyl-CoA carboxylase (ACCase) inhibitors, paraquat and glufosinate, had better results for control in this species. However, poor control was observed with bispyribac-sodium, metsulfuron-methyl and quinclorac, indicating possible cross-resistance for ALS-inhibitors and also multiple resistance for auxinic herbicides (quinclorac). Nevertheless dose–response experiments are required to confirm this assumption.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7bfeb376-09bc-4f38-a295-0df385ebcfba', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Differential expression of genes associated with non-target site resistance in Poa annua with target site resistance to acetolactate synthase inhibitors', 'Laforest M, Soufiane B, Patterson EL, Vargas JJ, Boggess SL, Houston LC, Trigiano RN, Brosnan JT', 2021, 'Pest management science', '10.1002/ps.6541', 'https://doi.org/10.1002/ps.6541', 'https://europepmc.org/articles/PMC8518846?pdf=render', NULL, NULL, 8, NULL, 'canada', 3, 'cc by-nc-nd', 'BackgroundPoa annua is a pervasive grassy, self-pollinating, weed that has evolved resistance to 10 different herbicide modes-of-action, third most of all weed species. We investigated constitutive overexpression of genes associated with non-target site resistance (NTSR) in POAAN-R3 and the response of those genes when treated with trifloxysulfuron despite the biotype having a known target site mutation in acetolactate synthase (ALS).ResultsDespite having an ALS target site mutation, POAAN-R3 still had a transcriptomic response to herbicide application that differed from a susceptible biotype. We observed differential expression of genes associated with transmembrane transport and oxidation-reduction activities, with differences being most pronounced prior to herbicide treatment.ConclusionsIn the P. annua biotype we studied with confirmed target site resistance to ALS inhibitors, we also observed constitutive expression of genes regulating transmembrane transport, as well as differential expression of genes associated with oxidative stress after treatment with trifloxysulfuron. This accumulation of mechanisms, in addition to the manifestation of target site resistance, could potentially increase the chance of survival when plants are challenged by different modes of action.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa3f71ae-55bd-4639-bbdf-c61ca8705e3c', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Diversity and Spread of Acetolactate Synthase Allelic Variants at Position 574 Endowing Resistance in Amaranthus hybridus in Italy', 'Andrea Milani, Silvia Panozzo, Samuele Pinton, Renato Antonio Danielis, Maurizio Sattin, Laura Scarabel', 2023, 'Plants', '10.3390/plants12020332', 'https://doi.org/10.3390/plants12020332', 'https://www.mdpi.com/2223-7747/12/2/332', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Poor control of Amaranthus spp. with herbicides inhibiting acetolactate synthase (ALS) has been observed for several years in soybean fields in north-eastern Italy, but to date only a few ALS-resistant populations have been confirmed. An extensive sampling of putatively resistant Amaranthus accessions was completed in the Friuli Venezia Giulia region, across an arable land area of about 3000 km2. In total, 58 accessions were tested to confirm their resistance status, recognize the Amaranthus species, identify the mutant ALS alleles endowing the resistance and determine the efficacy of 3 pre-emergence herbicides. Most accessions resulted in cross-resistance to thifensulfuron-methyl and imazamox. Genomic DNA were extracted from single seeds with a newly developed protocol; an allele-specific PCR assay revealed the presence of the 574-leucine in 20 accessions, of the 574-methionine in 22, and of both alleles in 9 accessions. The two variants showed a different spatial distribution. All resistant populations were ascribed to A. hybridus. A. hybridus resistant to ALS herbicides is well-established in this Italian region and its resistance is due to two ALS mutant alleles. Metribuzin, clomazone and metobromuron can be used as alternative herbicides to be applied in pre-emergence and they should be integrated into the management strategies to limit the spread of resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6291d346-160f-4346-ae6b-59a54370eb7c', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Draft Genomes of Amaranthus tuberculatus, Amaranthus hybridus, and Amaranthus palmeri', 'Montgomery JS, Giacomini D, Waithaka B, Lanz C, Murphy BP, Campe R, Lerchl J, Landes A', 2020, 'Genome biology and evolution', '10.1093/gbe/evaa177', 'https://doi.org/10.1093/gbe/evaa177', 'https://europepmc.org/articles/PMC7643611?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by', 'Amaranthus tuberculatus, Amaranthus hybridus, and Amaranthus palmeri are agronomically important weed species. Here, we present the most contiguous draft assemblies of these three species to date. We utilized a combination of Pacific Biosciences long-read sequencing and chromatin contact mapping information to assemble and order sequences of A. palmeri to near-chromosome-level resolution, with scaffold N50 of 20.1 Mb. To resolve the issues of heterozygosity and coassembly of alleles in diploid species, we adapted the trio binning approach to produce haplotype assemblies of A. tuberculatus and A. hybridus. This approach resulted in an improved assembly of A. tuberculatus, and the first genome assembly for A. hybridus, with contig N50s of 2.58 and 2.26 Mb, respectively. Species-specific transcriptomes and information from related species were used to predict transcripts within each assembly. Syntenic comparisons of these species and Amaranthus hypochondriacus identified sites of genomic rearrangement, including duplication and translocation, whereas genetic map construction within A. tuberculatus highlighted the need for further ordering of the A. hybridus and A. tuberculatus contigs. These multiple reference genomes will accelerate genomic studies in these species to further our understanding of weedy evolution within Amaranthus.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('db0634e5-495f-4df6-834b-8db785f87bf7', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Editorial: Multiple Herbicide-Resistant Weeds and Non-target Site Resistance Mechanisms: A Global Challenge for Food Production', 'Torra J, Osuna MD, Merotto A, Vila-Aiub M', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.763212', 'https://doi.org/10.3389/fpls.2021.763212', 'https://europepmc.org/articles/PMC8581628?pdf=render', NULL, NULL, 5, NULL, 'other', 1, 'cc by', NULL, '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9f5fac0d-4103-4ca5-ab6f-597dcc7c0a11', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Effect of stage of maturity at harvest for forage pea (Pisum sativum L.) on eating behavior, ruminal fermentation, and digestibility when fed as hay to yearling beef heifers', 'Pursley AA, Biligetu B, Warkentin T, Lardner HA, Penner GB', 2020, 'Translational animal science', '10.1093/tas/txz167', 'https://doi.org/10.1093/tas/txz167', 'https://europepmc.org/articles/PMC6994022?pdf=render', NULL, NULL, 10, NULL, 'prairies', 4, 'cc by-nc', 'The objective of this study was to evaluate the stage of maturity at harvest for pea hay (Pisum sativum L., c.v. CDC Horizon) on dry matter intake (DMI), eating behavior, ruminal fermentation, and digestibility when fed to beef heifers. Pea hay was cut at EARLY (defined to occur when flat pods were on one or more nodes), MID (when seeds filled the pods at one or more nodes and the leaves were changing from green to gold), and LATE (yellow dry seeds filled pods on most or all of the nodes and the pods and leaves had a yellow color) phases, and was cured in the field and baled. Six ruminally-cannulated Speckle Park heifers were used in a replicated 3 × 3 Latin square design with three 18-d periods including 12 d for adaptation, 2 d for measurement of ruminal pool sizes, and 4 d for the collection of eating behavior, ruminal pH, ruminal digesta, and feces. For all treatments, the respective pea hay was included at 40% of the dietary DM. Stage of maturity at harvest for pea hay did not affect total DMI, pea hay DMI, or the total short-chain fatty acid concentration in ruminal fluid with averages of 8.6 kg/d, 3.2 kg/d, and 96.55 mM, respectively. The duration of time spent ruminating decreased with advancing pea hay maturity when reported as min/d, min/kg DMI, and min/kg neutral detergent fiber (NDF) (P ≤ 0.01). Mean ruminal pH also decreased with advancing pea maturity (P P ≥ 0.55) nor was the rate of digestion for NDF. However, NDF passage rate decreased by 0.21%/h with advancing pea hay maturity (P = 0.02). Apparent total tract digestibility of NDF (average = 16.30%, P = 0.41) was not affected, but starch digestibility decreased from 96.10% to 93.08% with advancing pea hay maturity (P = 0.07). Overall, stage of maturity at harvest for pea hay does not appear to affect DMI or NDF digestibililty but decreases chewing activity, apparent total tract starch digestibility, ruminal pH, and ruminal NDF passage rate.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3a3f417f-6532-4f57-a1d3-1e3ce63df417', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Engineering Abiotic Stress Tolerance in Crop Plants through CRISPR Genome Editing', 'Rahman MU, Zulfiqar S, Raza MA, Ahmad N, Zhang B', 2022, 'Cells', '10.3390/cells11223590', 'https://doi.org/10.3390/cells11223590', 'https://europepmc.org/articles/PMC9688763?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Environmental abiotic stresses challenge food security by depressing crop yields often exceeding 50% of their annual production. Different methods, including conventional as well as genomic-assisted breeding, mutagenesis, and genetic engineering have been utilized to enhance stress resilience in several crop species. Plant breeding has been partly successful in developing crop varieties against abiotic stresses owning to the complex genetics of the traits as well as the narrow genetic base in the germplasm. Irrespective of the fact that genetic engineering can transfer gene(s) from any organism(s), transgenic crops have become controversial mainly due to the potential risk of transgene-outcrossing. Consequently, the cultivation of transgenic crops is banned in certain countries, particularly in European countries. In this scenario, the discovery of the CRISPR tool provides a platform for producing transgene-free genetically edited plants-similar to the mutagenized crops that are not extensively regulated such as genetically modified organisms (GMOs). Thus, the genome-edited plants without a transgene would likely go into the field without any restriction. Here, we focused on the deployment of CRISPR for the successful development of abiotic stress-tolerant crop plants for sustaining crop productivity under changing environments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('296280af-f936-4f3a-b358-e0144c0d2e71', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'First report of glyphosate-resistant downy brome (Bromus tectorum L.) in Canada', 'Geddes CM, Pittman MM', 2022, 'Scientific reports', '10.1038/s41598-022-21942-6', 'https://doi.org/10.1038/s41598-022-21942-6', 'https://europepmc.org/articles/PMC9640614?pdf=render', NULL, NULL, 9, NULL, 'southern_alberta', 5, 'cc by', 'Glyphosate is the most used herbicide worldwide, and is an important source of economical weed control in glyphosate-resistant crops, and conservation tillage systems, among other uses. Downy brome (Bromus tectorum L.), otherwise known as cheatgrass, is a highly invasive winter-annual grass weed in cropping systems, pastureland, and naturalized or ruderal areas in western North America. In 2021, a downy brome population remained uncontrolled following four applications of glyphosate in a glyphosate-resistant canola (Brassica napus L.) field located in Taber County, Alberta, Canada. All individuals from the subsequent generation of the population survived glyphosate treatment at the typical field rate (900 g ae ha-1). In dose-response bioassays, the putative glyphosate-resistant population exhibited 10.6- to 11.9-fold, 7.7- to 8.7-fold, 7.8- to 8.8-fold, and 8.3- to 9.5-fold resistance to glyphosate based on plant survival, visible control, and biomass fresh weight and dry weight, respectively, compared with two susceptible populations 21 days after treatment. Estimated glyphosate rates for 80% control of this population ranged from 2795 to 4511 g ae ha-1; well above common usage rates. This downy brome population represents the first glyphosate-resistant grass weed confirmed in Canada, and the second weed species exhibiting glyphosate resistance in the Canadian prairie region.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a3b4607-2a69-4d2a-98ba-6d6cce9487e3', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Health effects of herbicides and its current removal strategies', 'Mohd Ghazi R, Nik Yusoff NR, Abdul Halim NS, Wahab IRA, Ab Latif N, Hasmoni SH, Ahmad Zaini MA, Zakaria ZA', 2023, 'Bioengineered', '10.1080/21655979.2023.2259526', 'https://doi.org/10.1080/21655979.2023.2259526', 'https://europepmc.org/articles/PMC10761135?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'The continually expanding global population has necessitated increased food supply production. Thus, agricultural intensification has been required to keep up with food supply demand, resulting in a sharp rise in pesticide use. The pesticide aids in the prevention of potential losses caused by pests, plant pathogens, and weeds, but excessive use over time has accumulated its occurrence in the environment and subsequently rendered it one of the emerging contaminants of concern. This review highlights the sources and classification of herbicides and their fate in the environment, with a special focus on the effects on human health and methods to remove herbicides. The human health impacts discussion was in relation to toxic effects, cell disruption, carcinogenic impacts, negative fertility effects, and neurological impacts. The removal treatments described herein include physicochemical, biological, and chemical treatment approaches, and advanced oxidation processes (AOPs). Also, alternative, green, and sustainable treatment options were discussed to shed insight into effective treatment technologies for herbicides. To conclude, this review serves as a stepping stone to a better environment with herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e7b7edab-2da1-445d-967f-a75143a12940', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Use of Biostimulants as a New Approach for the Improvement of Phytoremediation Performance-A Review', 'Bartucca ML, Cerri M, Del Buono D, Forni C', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11151946', 'https://doi.org/10.3390/plants11151946', 'https://europepmc.org/articles/PMC9332818?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Environmental pollution is one of the most pressing global issues, and it requires priority attention. Environmental remediation techniques have been developed over the years and can be applied to polluted sites, but they can have limited effectiveness and high energy consumption and costs. Bioremediation techniques, on the other hand, represent a promising alternative. Among them, phytoremediation is attracting particular attention, a green methodology that relies on the use of plant species to remediate contaminated sites or prevent the dispersion of xenobiotics into the environment. In this review, after a brief introduction focused on pollution and phytoremediation, the use of plant biostimulants (PBs) in the improvement of the remediation effectiveness is proposed. PBs are substances widely used in agriculture to raise crop production and resistance to various types of stress. Recent studies have also documented their ability to counteract the deleterious effects of pollutants on plants, thus increasing the phytoremediation efficiency of some species. The works published to date, reviewed and discussed in the present work, reveal promising prospects in the remediation of polluted environments, especially for heavy metals, when PBs derived from humic substances, protein and amino acid hydrolysate, inorganic salts, microbes, seaweed, plant extracts, and fungi are employed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6ecc8a31-4218-4552-905b-2d08fa37afe2', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Integrated Pest Management: An Update on the Sustainability Approach to Crop Protection', 'Zhou W, Arcot Y, Medina RF, Bernal J, Cisneros-Zevallos L, Akbulut MES', 2024, 'ACS omega', '10.1021/acsomega.4c06628', 'https://doi.org/10.1021/acsomega.4c06628', 'https://europepmc.org/articles/PMC11465254?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Integrated Pest Management (IPM) emerged as a pest control framework promoting sustainable intensification of agriculture, by adopting a combined strategy to reduce reliance on chemical pesticides while improving crop productivity and ecosystem health. This critical review synthesizes the most recent advances in IPM research and practice, mostly focusing on studies published within the past five years. The Review discusses the key components of IPM, including cultural practices, biological control, genetic pest control, and targeted pesticide application, with a particular emphasis on the significant advancements made in biological control and targeted pesticide delivery systems. Recent findings highlight the growing importance of genetic control and conservation biological control, which involves the management of agricultural landscapes to promote natural enemy populations. Furthermore, the recent discovery of novel biopesticides, including microbial agents and plant-derived compounds, has expanded the arsenal of tools available for eco-friendly pest management. Substantial progress has recently also been made in the development of targeted pesticide delivery systems, such as nanoemulsions and controlled-release formulations, which can minimize the environmental impact of pesticides while maintaining their efficacy. The Review also analyzes the environmental, economic, and social dimensions of IPM adoption, showcasing its potential to promote biodiversity conservation and ensure food safety. Case studies from various agroecological contexts demonstrate the successful implementation of IPM programs, highlighting the importance of participatory approaches and effective knowledge exchange among stakeholders. The Review also identifies the main challenges and opportunities for the widespread adoption of IPM, including the need for transdisciplinary research, capacity building, and policy support. In conclusion, this critical review discusses the essential role of IPM components in achieving the sustainable intensification of agriculture, as it seeks to optimize crop production while minimizing adverse environmental impacts and enhancing the resilience of agricultural systems to global challenges such as climate change and biodiversity loss.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e81b14fb-9d8e-407a-9030-9bc02b28493e', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Management of Infection by Parasitic Weeds: A Review', 'Fernández-Aparicio M, Delavault P, Timko MP', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9091184', 'https://doi.org/10.3390/plants9091184', 'https://europepmc.org/articles/PMC7570238?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Parasitic plants rely on neighboring host plants to complete their life cycle, forming vascular connections through which they withdraw needed nutritive resources. In natural ecosystems, parasitic plants form one component of the plant community and parasitism contributes to overall community balance. In contrast, when parasitic plants become established in low biodiversified agroecosystems, their persistence causes tremendous yield losses rendering agricultural lands uncultivable. The control of parasitic weeds is challenging because there are few sources of crop resistance and it is difficult to apply controlling methods selective enough to kill the weeds without damaging the crop to which they are physically and biochemically attached. The management of parasitic weeds is also hindered by their high fecundity, dispersal efficiency, persistent seedbank, and rapid responses to changes in agricultural practices, which allow them to adapt to new hosts and manifest increased aggressiveness against new resistant cultivars. New understanding of the physiological and molecular mechanisms behind the processes of germination and haustorium development, and behind the crop resistant response, in addition to the discovery of new targets for herbicides and bioherbicides will guide researchers on the design of modern agricultural strategies for more effective, durable, and health compatible parasitic weed control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ac7e27d-9478-41f9-a9ef-39011c475cb1', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Monitoring and Management of Imidazolinone-Resistant Red Rice (Oryza sativa L., var. sylvatica) in Clearfield® Italian Paddy Rice', 'Laura Scarabel, Cesare Cenghialta, Dario Manuello, Maurizio Sattin', 2012, 'Agronomy', '10.3390/agronomy2040371', 'https://doi.org/10.3390/agronomy2040371', 'http://www.mdpi.com/2073-4395/2/4/371', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The introduction in Italy of Clearfield® rice cultivars carrying imidazolinone-resistant traits provides an efficient option to control red rice, a conspecific weed of cultivated rice. However, despite the promulgation of specific guidelines for Clearfield® technology management, imazamox red rice survivors have been reported by farmers. Forty-two fields were monitored in 2010 and 2011 throughout the Piedmont and Lombardy regions and field cases were recorded of herbicides use and agronomic practices. Whole-plant sensitivity to imazamox was assessed and the resistance mechanism was determined by molecular analysis. Twenty-six red rice populations out of 42 were imazamox-resistant and plants of all the resistant populations possess a Ser to Asn substitution at locus 653 of the ALS gene determining the target-site resistance. Farmers frequently grow Clearfield® varieties for more than two consecutive years so increasing the selection pressure exerted by imazamox and favoring the evolution of resistant red rice. To maintain the sustainability of this new technology, a proper management based on crop rotation, utilization of certified seeds and strict control of red rice escapes has to be implemented. More generally, all stakeholders must increase their awareness that the selection pressure exerted by ALS inhibitors in rice cropping system should be reduced.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79bf9954-5aeb-47f0-bf03-4c78b82fc08c', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Mutations in the acetolactate synthase (ALS) enzyme affect shattercane (Sorghum bicolor) response to ALS-inhibiting herbicides', 'Dweikat IM, Gelli M, Bernards M, Martin A, Jhala A', 2023, 'Hereditas', '10.1186/s41065-023-00291-y', 'https://doi.org/10.1186/s41065-023-00291-y', 'https://europepmc.org/articles/PMC10283220?pdf=render', NULL, NULL, 9, NULL, 'northern_plains', 3, 'cc by', 'BackgroundShattercane [Sorghum bicolor (L.) Moench ssp. Arundinaceum (Desv.)] is a competitive weed in North America''s corn, soybean, sorghum, and other agronomic crops. Control of shattercane with POST herbicides in corn became possible with the introduction of acetolactate synthase (ALS)-inhibiting herbicides in the 1980s, and their extensive use resulted in the evolution of ALS-inhibitors resistant shattercane.ResultsShattercane seeds were collected from 16 south-eastern and south-central Nebraska fields that were treated with primisulfuron for three consecutive years. Three resistant plants were found in greenhouse evaluations of more than 30,000 plants. Results from a greenhouse bioassay conducted to assess the response of each shattercane biotype to ALS-inhibiting herbicides showed a differential response to ALS inhibitors within and between chemical classes. Biotype P8-30 was resistant or partially resistant to all ALS-inhibiting herbicides applied and displayed a unique amino acid sequence substitution (Trp574 to Leu) relative to the other two resistant biotypes, P2-205 and P9-102. Whole plant dose-response studies confirmed a 4- to the 12-fold level of primisulfuron resistance in three shattercane biotypes compared with the known primisulfuron-susceptible shattercane biotype. The ALS gene was sequenced using primers designed from the corn ALS sequence to identify mutations in the ALS gene that confer resistance. A total of seven nucleotide substitutions were detected in the three herbicide-resistant biotypes P2-205, P8-30, and P9-102. These biotypes are being crossed to adapted sorghum lines (grain, sweet, and forage) to broaden germplasm with resistance to ALS-inhibiting herbicides.ConclusionThe discovery of these mutants should accelerate the development of sorghum genotypes that tolerate ALS-based herbicides, which provide additional choices for sorghum farmers to control weeds, especially grasses, in their fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6480d3d5-f580-4372-86b6-a7092dc990f5', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Novel amino acid substitutions in Protoporphyrinogen oxidase 1 endow resistance to PPO-inhibiting herbicides in Bassia scoparia', 'Porri A, Law QD, Geddes CM, Ikley J, Willingham S, Johnen P, Meiners I, Al-Sammarraie S', 2026, 'Frontiers in plant science', '10.3389/fpls.2026.1904705', 'https://doi.org/10.3389/fpls.2026.1904705', 'https://europepmc.org/articles/PMC13612512?pdf=render', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc by', 'PPO-inhibiting herbicides are widely used to manage weeds in different cropping systems, yet resistance evolution threatens their long-term efficacy. Here, we investigated the molecular basis of resistance to PPO-inhibiting herbicides in Bassia scoparia biotypes collected from four locations in North Dakota, USA. Greenhouse dose-response assays revealed high levels of resistance to saflufenacil and carfentrazone-ethyl, while fomesafen retained full efficacy across all biotypes. Resistant plants did not show increased copy number or elevated expression of PPX1 or PPX2. Sequencing of survivor plants revealed conserved PPO2 protein sequences, but consistent target-site substitutions at position F454 in PPO1, including F454I (Phenylalanine, to Isoleucine) F454L (Phenylalanine, to Leucine), and F454V (Phenylalanine, to Valine). In vitro enzyme assays demonstrated that these substitutions impair PPO1 enzyme sensitivity to saflufenacil and carfentrazone, but not to fomesafen. Ectopic expression of B. scoparia PPX1 encoding F454I, L and V variants in Arabidopsis thaliana conferred tolerance to saflufenacil and carfentrazone-ethyl, but not to fomesafen, supporting greenhouse and in vitro results. Molecular modeling indicated that the conformational flexibility and interaction profile of fomesafen enables it to maintain binding to mutated PPO1 enzyme variants, in contrast to the more rigid structures of saflufenacil and carfentrazone. A yeast-based complementation system further confirmed that F454 substitutions decrease herbicide sensitivity. In addition, developmental profiling showed distinct expression patterns of PPX1 and PPX2 during early growth stages in B. scoparia and Amaranthus palmeri, highlighting isoform-specific roles. Together, these findings represent the first reported PPO1 target-site amino acid substitutions in a broadleaf weed species as a key mechanism of resistance and highlight that fomesafen is effective to control resistant B. scoparia populations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('802d7a7c-a767-4c56-a2b0-5f9fbc6428df', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Point Mutations as Main Resistance Mechanism Together With P450-Based Metabolism Confer Broad Resistance to Different ALS-Inhibiting Herbicides in Glebionis coronaria From Tunisia', 'Zeineb Hada, Zeineb Hada, Yosra Menchari, Antonia M. Rojano-Delgado, Joel Torra, Julio Menéndez, Candelario Palma-Bautista, Rafael de Prado', 2021, 'Frontiers in Plant Science', '10.3389/fpls.2021.626702', 'https://doi.org/10.3389/fpls.2021.626702', 'https://www.frontiersin.org/articles/10.3389/fpls.2021.626702/full', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Resistance to acetolactate synthase (ALS) inhibiting herbicides has recently been reported in Glebionis coronaria from wheat fields in northern Tunisia, where the weed is widespread. However, potential resistance mechanisms conferring resistance in these populations are unknown. The aim of this research was to study target-site resistance (TSR) and non-target-site resistance (NTSR) mechanisms present in two putative resistant (R) populations. Dose–response experiments, ALS enzyme activity assays, ALS gene sequencing, absorption and translocation experiments with radiolabeled herbicides, and metabolism experiments were carried out for this purpose. Whole plant trials confirmed high resistance levels to tribenuron and cross-resistance to florasulam and imazamox. ALS enzyme activity further confirmed cross-resistance to these three herbicides and also to bispyribac, but not to flucarbazone. Sequence analysis revealed the presence of amino acid substitutions in positions 197, 376, and 574 of the target enzyme. Among the NTSR mechanisms investigated, absorption or translocation did not contribute to resistance, while evidences of the presence of enhanced metabolism were provided. A pretreatment with the cytochrome P450 monooxygenase (P450) inhibitor malathion partially synergized with imazamox in post-emergence but not with tribenuron in dose–response experiments. Additionally, an imazamox hydroxyl metabolite was detected in both R populations in metabolism experiments, which disappeared with the pretreatment with malathion. This study confirms the evolution of cross-resistance to ALS inhibiting herbicides in G. coronaria from Tunisia through TSR and NTSR mechanisms. The presence of enhanced metabolism involving P450 is threatening the chemical management of this weed in Tunisian wheat fields, since it might confer cross-resistance to other sites of action.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8296841-2277-4f91-9e10-f278a0a01dff', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Pre-breeding for diversification of primary gene pool and genetic enhancement of grain legumes', 'Sharma S, Upadhyaya HD, Varshney RK, Gowda CL', 2013, 'Frontiers in plant science', '10.3389/fpls.2013.00309', 'https://doi.org/10.3389/fpls.2013.00309', 'https://europepmc.org/articles/PMC3747629?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The narrow genetic base of cultivars coupled with low utilization of genetic resources are the major factors limiting grain legume production and productivity globally. Exploitation of new and diverse sources of variation is needed for the genetic enhancement of grain legumes. Wild relatives with enhanced levels of resistance/tolerance to multiple stresses provide important sources of genetic diversity for crop improvement. However, their exploitation for cultivar improvement is limited by cross-incompatibility barriers and linkage drags. Pre-breeding provides a unique opportunity, through the introgression of desirable genes from wild germplasm into genetic backgrounds readily used by the breeders with minimum linkage drag, to overcome this. Pre-breeding activities using promising landraces, wild relatives, and popular cultivars have been initiated at International Crops Research Institute for the Semi-Arid Tropics (ICRISAT) to develop new gene pools in chickpea, pigeonpea, and groundnut with a high frequency of useful genes, wider adaptability, and a broad genetic base. The availability of molecular markers will greatly assist in reducing linkage drags and increasing the efficiency of introgression in pre-breeding programs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9894c03b-6b6b-418a-bd9f-fe29570e5ca3', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Recent advances of CRISPR-based genome editing for enhancing staple crops', 'Chen F, Chen L, Yan Z, Xu J, Feng L, He N, Guo M, Zhao J', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1478398', 'https://doi.org/10.3389/fpls.2024.1478398', 'https://europepmc.org/articles/PMC11456538?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'An increasing population, climate change, and diminishing natural resources present severe threats to global food security, with traditional breeding and genetic engineering methods often falling short in addressing these rapidly evolving challenges. CRISPR/Cas systems have emerged as revolutionary tools for precise genetic modifications in crops, offering significant advancements in resilience, yield, and nutritional value, particularly in staple crops like rice and maize. This review highlights the transformative potential of CRISPR/Cas technology, emphasizing recent innovations such as prime and base editing, and the development of novel CRISPR-associated proteins, which have significantly improved the specificity, efficiency, and scope of genome editing in agriculture. These advancements enable targeted genetic modifications that enhance tolerance to abiotic stresses as well as biotic stresses. Additionally, CRISPR/Cas plays a crucial role in improving crop yield and quality by enhancing photosynthetic efficiency, nutrient uptake, and resistance to lodging, while also improving taste, texture, shelf life, and nutritional content through biofortification. Despite challenges such as off-target effects, the need for more efficient delivery methods, and ethical and regulatory concerns, the review underscores the importance of CRISPR/Cas in addressing global food security and sustainability challenges. It calls for continued research and integration of CRISPR with other emerging technologies like nanotechnology, synthetic biology, and machine learning to fully realize its potential in developing resilient, productive, and sustainable agricultural systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('947782f6-f68c-4aba-a1e9-e3faeb6d3603', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Resistance profile of glufosinate-resistant Palmer amaranth accessions and herbicide options', 'Pâmela Carvalho-Moore, Jason K. Norsworthy, Maria C. C. R. Souza, L. Tom Barber, Leonard Bonilha Piveta, Ingo Meiners, Aimone Porri', 2025, 'Weed Technology', '10.1017/wet.2025.8', 'https://doi.org/10.1017/wet.2025.8', 'https://www.cambridge.org/core/product/identifier/S0890037X25000089/type/journal_article', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Glufosinate resistance was previously confirmed in three Palmer amaranth accessions from Arkansas (MSR1, MSR2, and CCR). Greenhouse screening results suggested the presence of multiple herbicide resistance. Therefore, this study aimed to determine the postemergence resistance profile of these three glufosinate-resistant Palmer amaranth accessions. Field experiments were also conducted to assess preemergence and postemergence herbicide options to control the accession with the highest glufosinate resistance level (MSR2). A dose-response assay with the three resistant accessions and two susceptible standards was conducted with the herbicides 2,4-D, atrazine, dicamba, diuron, fomesafen, glyphosate, imazethapyr, and mesotrione. The preemergence and postemergence field experiments with MSR2 evaluated 15 and 16 single active ingredients, respectively. The Palmer amaranth accessions that carried glufosinate resistance were also confirmed to be resistant to six other postemergence herbicides: 2,4-D, diuron, fomesafen, glyphosate, imazethapyr, and mesotrione. CCR is also resistant to dicamba. Therefore, accessions MSR1, MSR2, and CCR have evolved resistance to postemergence herbicides pertaining to seven sites of action. A shift toward increased tolerance to atrazine has also been observed among all resistant accessions. Overall, field preemergence treatments with atrazine, pyroxasulfone, or trifludimoxazin obtained the highest MSR2 control levels at all evaluation times and the lowest number of seedlings emerging at 3 and 6 wk after treatment. In the postemergence experiment, only paraquat obtained MSR2 control levels above 90% at all ratings. The lowest number of alive MSR2 plants was observed after postemergence treatments with paraquat or trifludimoxazin. Fields near where glufosinate resistance has been confirmed in Palmer amaranth will likely demand a more diverse and proactive management strategy that relies on combinations of chemical, cultural, and mechanical control tactics. Future efforts should focus on sequential applications and mixture, the elucidation of all resistance mechanisms in the evaluated accessions, and soil-applied dose-response.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7af84962-604d-4bb7-82f1-8327a6b849ce', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Rice Cultivar Response to Florpyrauxifen-Benzyl When Applied with Imazethapyr and a Cytochrome P450 Inhibitor', 'Hannah E. Wright, Jason K. Norsworthy, Trenton L. Roberts, Robert C. Scott, Jarrod T. Hardke, Edward E. Gbur', 2020, 'International Journal of Agronomy', '10.1155/2020/2769610', 'https://doi.org/10.1155/2020/2769610', 'http://dx.doi.org/10.1155/2020/2769610', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Understanding cultivar responses to a new herbicide is crucial to determining appropriate herbicide use and management practices. Florpyrauxifen-benzyl is a new rice herbicide developed to control troublesome weeds in rice production. Little research has been conducted to characterize rice cultivar responses to florpyrauxifen-benzyl, and thus, a field experiment was conducted at the Pine Tree Research Station (PTRS) in 2017 and 2018 and at the Rice Research and Extension Center (RREC) in 2018 to determine rice cultivar tolerance to florpyrauxifen-benzyl as influenced by herbicide rate, the addition of imazethapyr, and rice growth stage. Another experiment was conducted in 2018 at PTRS and RREC to assess crop response when florpyrauxifen-benzyl at different rates is applied with and without malathion, a known cytochrome P450 inhibitor. Three cultivars were evaluated in both experiments: a long-grain variety “CL111,” a medium-grain variety “CL272,” and a long-grain hybrid “CLXL745.” Injury in the first experiment was higher when florpyrauxifen-benzyl was applied at 60 g ae ha−1 than at the labeled rate of 30 g ha−1, with the most injury being 10% when averaged over growth stage at the time of application. Generally, applications made at the 3-leaf growth stage resulted in the most injury; however, this injury was at most 14%. Additionally, there was no reduction in grain yield for any cultivar, indicating florpyrauxifen-benzyl can be used safely in conjunction with imazethapyr in imidazolinone-resistant rice. In the second experiment, there was no more than 10% injury and no reduction in grain yield, with the addition of malathion not causing an increase in rice injury. Results from these experiments indicate florpyrauxifen-benzyl can be mixed with imazethapyr and the addition of malathion will not lead to increased risk for injury to rice.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8ed4bcc-1d64-437f-89c1-56840fb42e70', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Survey of ACCase and ALS resistance in winter annual grasses identifies target-site and nontarget-site imazamox resistance in Secale cereale', 'Soni N, Westra EP, Allegretta G, Araujo ALS, de Pinho CF, Morran S, Lerchl J, Dayan FE', 2022, 'Pest management science', '10.1002/ps.7154', 'https://doi.org/10.1002/ps.7154', 'https://europepmc.org/articles/PMC9825914?pdf=render', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'BackgroundEarly detection of herbicide resistance in weeds is crucial for successful implementation of integrated weed management. We conducted a herbicide resistance survey of the winter annual grasses feral rye (Secale cereale), downy brome (Bromus tectorum), and jointed goatgrass (Aegilops cylindrica) from Colorado winter wheat production areas for resistance to imazamox and quizalofop.ResultsAll samples were susceptible to quizalofop. All downy brome and jointed goatgrass samples were susceptible to imazamox. Out of 314 field collected samples, we identified three feral rye populations (named A, B, and C) that were imazamox resistant. Populations B and C had a target-site mechanism with mutations in the Ser653 residue of the acetolactate synthase (ALS) gene to Asn in B and to Thr in C. Both populations B and C had greatly reduced ALS in vitro enzyme inhibition by imazamox. ALS feral rye protein modeling showed that steric interactions induced by the amino acid substitutions at Ser653 impaired imazamox binding. Individuals from population A had no mutations in the ALS gene. The ALS enzyme from population A was equally sensitive to imazamox as to known susceptible feral rye populations. Imazamox was degraded two times faster in population A compared with a susceptible control. An oxidized imazamox metabolite formed faster in population A and this detoxification reaction was inhibited by malathion.ConclusionPopulation A has a nontarget-site mechanism of enhanced imazamox metabolism that may be conferred by cytochrome P450 enzymes. This is the first report of both target-site and metabolism-based imazamox resistance in feral rye. © 2022 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ebec134-e67d-4a4b-8043-1045c582a501', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'Taxonomical loss for weed seedlings image classification', 'Fontaine HO, Foucher S, Fallon E, Simard MJ, Lord E', 2026, 'Scientific reports', '10.1038/s41598-025-33961-0', 'https://doi.org/10.1038/s41598-025-33961-0', 'https://europepmc.org/articles/PMC12852093?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by', 'Accurate classification of weed seedlings is a key challenge to address in order to advance precision weed management and reduce pesticide use. In this study, an original image dataset, the Weed Phenological Dataset (WPD), with annotated early growth stages is introduced. Furthermore, a novel deep learning taxonomic loss function for few-shot learning was evaluated. Using hierarchical structures to direct the classification process, this taxonomic loss function introduces dynamic margins during the computation. In experiments using the taxonomic loss using the ResNet-50 architectures across different plant image datasets, this taxonomic approach allowed better clustering according to the Silhouette scores when compared with triplet loss using 100 images per class. It also led to better identification of weed seedlings at early growth stages. Although the new taxonomic loss did not consistency improve classification results for all the deep learning model architectures, it open new research avenues for the robotization of agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0c124bc-0871-4b9d-a64f-efec2472f69d', 'f1e2db7a-c9d5-410f-8c5f-13e0484653bd', 'The nexus between reactive oxygen species and the mechanism of action of herbicides', 'Traxler C, Gaines TA, Küpper A, Luemmen P, Dayan FE', 2023, 'The Journal of biological chemistry', '10.1016/j.jbc.2023.105267', 'https://doi.org/10.1016/j.jbc.2023.105267', 'https://europepmc.org/articles/PMC10591016?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'Herbicides are small molecules that act by inhibiting specific molecular target sites within primary plant metabolic pathways resulting in catastrophic and lethal consequences. The stress induced by herbicides generates reactive oxygen species (ROS), but little is known about the nexus between each herbicide mode of action (MoA) and their respective ability to induce ROS formation. Indeed, some herbicides cause dramatic surges in ROS levels as part of their primary MoA, whereas other herbicides may generate some ROS as a secondary effect of the stress they imposed on plants. In this review, we discuss the types of ROS and their respective reactivity and describe their involvement for each known MoA based on the new Herbicide Resistance Action Committee classification.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.158892+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('43c842c6-c15d-462f-98c1-c858aa25e114', '7708283d-377a-4b89-98e4-5972c9419831', 'A Comprehensive Review of the Diversity of Fungal Secondary Metabolites and Their Emerging Applications in Healthcare and Environment', 'Wadhwa K, Kapoor N, Kaur H, Abu-Seer EA, Tariq M, Siddiqui S, Yadav VK, Niazi P', 2024, 'Mycobiology', '10.1080/12298093.2024.2416736', 'https://doi.org/10.1080/12298093.2024.2416736', 'https://europepmc.org/articles/PMC11749308?pdf=render', NULL, NULL, 53, NULL, 'other', 1, 'cc by-nc', 'Fungi and their natural products, like secondary metabolites, have gained a huge demand in the last decade due to their increasing applications in healthcare, environmental cleanup, and biotechnology-based industries. The fungi produce these secondary metabolites (SMs) during the different phases of their growth, which are categorized into terpenoids, alkaloids, polyketides, and non-ribosomal peptides. These SMs exhibit significant biological activity, which contributes to the formulation of novel pharmaceuticals, biopesticides, and environmental bioremediation agents. Nowadays, these fungal-derived SMs are widely used in food and beverages, for fermentation, preservatives, protein sources, and in dairy industries. In healthcare, it is being used as an antimicrobial, anticancer, anti-inflammatory, and immunosuppressive drug. The usage of modern tools of biotechnology can achieve an increase in demand for these SMs and large-scale production. The present review comprehensively analyses the diversity of fungal SMs along with their emerging applications in healthcare, agriculture, environmental sustainability, and nutraceuticals. Here, the authors have reviewed the recent advancements in genetic engineering, metabolic pathway manipulation, and synthetic biology to improve the production and yield of these SMs. Advancement in fermentation techniques, bioprocessing, and co-cultivation approaches for large-scale production of SMs. Investigators further highlighted the importance of omics technologies in understanding the regulation and biosynthesis of SMs, which offers an understanding of novel applications in drug discovery and sustainable agriculture. Finally, the authors have addressed the potential for genetic manipulation and biotechnological innovations for further exploitation of fungal SMs for commercial and environmental benefits.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c66f18ee-a19d-4fd8-9d92-2162d79fbae2', '7708283d-377a-4b89-98e4-5972c9419831', 'Assessment of Lambda-Cyhalothrin and Spinetoram Toxicity and Their Effects on the Activities of Antioxidant Enzymes and Acetylcholinesterase in Honey Bee (Apis mellifera) Larvae', 'Choi JY, Chon K, Kim J, Vasamsetti BMK, Kim BS, Yoon CY, Hwang S, Park KH', 2024, 'Insects', '10.3390/insects15080587', 'https://doi.org/10.3390/insects15080587', 'https://europepmc.org/articles/PMC11354917?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Honeybees play a crucial role as agricultural pollinators and are frequently exposed to various pollutants, including pesticides. In this study, we aimed to evaluate the toxicity of lambda-cyhalothrin (LCY) and spinetoram (SPI) in honey bee larvae reared in vitro through single (acute) and repeated (chronic) exposure. The acute LD50 values for LCY and SPI were 0.058 (0.051-0.066) and 0.026 (0.01-0.045) μg a.i./larva, respectively. In chronic exposure, the LD50 values of LCY and SPI were 0.040 (0.033-0.046) and 0.017 (0.014-0.019) μg a.i./larva, respectively. The chronic no-observed-effect dose of LCY and SPI was 0.0125 μg a.i./larva. Adult deformation rates exceeded 30% in all LCY treatment groups, showing statistically significant differences compared to the solvent control group (SCG). Similarly, SPI-treated bees exhibited significantly more deformities than SCG. Furthermore, we examined the activities of several enzymes, namely, acetylcholinesterase (AChE), glutathione-S-transferase (GST), catalase (CAT), and superoxide dismutase (SOD), in larvae, pupae, and newly emerged bees after chronic exposure at the larval stage (honey bee larval chronic LD50, LD50/10 (1/10th of LD50), and LD50/20 (1/20th of LD50)). LCY and SPI induced significant changes in detoxification (GST), antioxidative (SOD and CAT), and signaling enzymes (AChE) during the developmental stages (larvae, pupae, and adults) of honey bees at sublethal and residue levels. Our results indicate that LCY and SPI may affect the development of honey bees and alter the activity of enzymes associated with oxidative stress, detoxification, and neurotransmission. These results highlight the potential risks that LCY and SPI may pose to the health and normal development of honey bees.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f9e470e2-14f8-4649-a1ef-91ec9ad5e361', '7708283d-377a-4b89-98e4-5972c9419831', 'Can nanotechnology and genomics innovations trigger agricultural revolution and sustainable development?', 'Javaid A, Hameed S, Li L, Zhang Z, Zhang B, -Rahman MU', 2024, 'Functional & integrative genomics', '10.1007/s10142-024-01485-x', 'https://doi.org/10.1007/s10142-024-01485-x', 'https://europepmc.org/articles/PMC11569009?pdf=render', NULL, NULL, 38, NULL, 'other', 1, 'cc by', 'At the dawn of new millennium, policy makers and researchers focused on sustainable agricultural growth, aiming for food security and enhanced food quality. Several emerging scientific innovations hold the promise to meet the future challenges. Nanotechnology presents a promising avenue to tackle the diverse challenges in agriculture. By leveraging nanomaterials, including nano fertilizers, pesticides, and sensors, it provides targeted delivery methods, enhancing efficacy in both crop production and protection. This integration of nanotechnology with agriculture introduces innovations like disease diagnostics, improved nutrient uptake in plants, and advanced delivery systems for agrochemicals. These precision-based approaches not only optimize resource utilization but also reduce environmental impact, aligning well with sustainability objectives. Concurrently, genetic innovations, including genome editing and advanced breeding techniques, enable the development of crops with improved yield, resilience, and nutritional content. The emergence of precision gene-editing technologies, exemplified by CRISPR/Cas9, can transform the realm of genetic modification and enabled precise manipulation of plant genomes while avoiding the incorporation of external DNAs. Integration of nanotechnology and genetic innovations in agriculture presents a transformative approach. Leveraging nanoparticles for targeted genetic modifications, nanosensors for early plant health monitoring, and precision nanomaterials for controlled delivery of inputs offers a sustainable pathway towards enhanced crop productivity, resource efficiency, and food safety throughout the agricultural lifecycle. This comprehensive review outlines the pivotal role of nanotechnology in precision agriculture, emphasizing soil health improvement, stress resilience against biotic and abiotic factors, environmental sustainability, and genetic engineering.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b00a9aee-08c5-467c-ae97-cbbc9d14bba6', '7708283d-377a-4b89-98e4-5972c9419831', 'Comprehensive Detoxification Mechanism Assessment of Red Imported Fire Ant (Solenopsis invicta) against Indoxacarb', 'Siddiqui JA, Zhang Y, Luo Y, Bamisile BS, Rehman NU, Islam W, Qasim M, Jiang Q', 2022, 'Molecules (Basel, Switzerland)', '10.3390/molecules27030870', 'https://doi.org/10.3390/molecules27030870', 'https://europepmc.org/articles/PMC8839056?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The red imported fire ant (Solenopsis invicta) is one of the deadliest invasive ant species that threatens the world by disrupting biodiversity, important functions within a natural ecosystem, and community structure. They are responsible for huge economic losses in the infested countries every year. Synthetic insecticides, especially indoxacarb, have been broadly used to control S. invicta for many years. However, the biochemical response of S. invicta to indoxacarb remains largely undiscovered. Here, we used the sublethal doses of indoxacarb on the S. invicta collected from the eight different cities of Southern China. The alteration in the transcriptome profile of S. invicta following sublethal dosages of indoxacarb was characterized using high-throughput RNA-seq technology. We created 2 libraries, with 50.93 million and 47.44 million clean reads for indoxacarb treatment and control, respectively. A total of 2018 unigenes were regulated after insecticide treatment. Results indicated that a total of 158 differentially expressed genes (DEGs) were identified in the indoxacarb-treated group, of which 100 were significantly upregulated and 58 were downregulated, mostly belonging to the detoxification enzymes, such as AChE, CarE, and GSTs. Furthermore, results showed that most of these DEGs were found in several KEGG pathways, including steroid biosynthesis, other drug metabolizing enzymes, glycerolipid metabolism, chemical carcinogenesis, drug-metabolizing cytochrome P450, glutathione metabolism, glycerophospholipid metabolism, glycolysis/gluconeogenesis, and metabolism of xenobiotics. Together, these findings indicated that indoxacarb causes significant alteration in the transcriptome profile and signaling pathways of S. invicta, providing a foundation for further molecular inquiry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b94d39a7-ca73-4021-86b4-fdcaca8a44ab', '7708283d-377a-4b89-98e4-5972c9419831', 'Eco-Efficient Systems Based on Nanocarriers for the Controlled Release of Fertilizers and Pesticides: Toward Smart Agriculture', 'Fincheira P, Hoffmann N, Tortella G, Ruiz A, Cornejo P, Diez MC, Seabra AB, Benavides-Mendoza A', 2023, 'Nanomaterials (Basel, Switzerland)', '10.3390/nano13131978', 'https://doi.org/10.3390/nano13131978', 'https://europepmc.org/articles/PMC10343595?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'The excessive application of pesticides and fertilizers has generated losses in biological diversity, environmental pollution, and harmful effects on human health. Under this context, nanotechnology constitutes an innovative tool to alleviate these problems. Notably, applying nanocarriers as controlled release systems (CRSs) for agrochemicals can overcome the limitations of conventional products. A CRS for agrochemicals is an eco-friendly strategy for the ecosystem and human health. Nanopesticides based on synthetic and natural polymers, nanoemulsions, lipid nanoparticles, and nanofibers reduce phytopathogens and plant diseases. Nanoproducts designed with an environmentally responsive, controlled release offer great potential to create formulations that respond to specific environmental stimuli. The formulation of nanofertilizers is focused on enhancing the action of nutrients and growth stimulators, which show an improved nutrient release with site-specific action using nanohydroxyapatite, nanoclays, chitosan nanoparticles, mesoporous silica nanoparticles, and amorphous calcium phosphate. However, despite the noticeable results for nanopesticides and nanofertilizers, research still needs to be improved. Here, we review the relevant antecedents in this topic and discuss limitations and future challenges.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('baa7cb56-d290-47aa-8067-b0fde5179461', '7708283d-377a-4b89-98e4-5972c9419831', 'Effect of belt expert (Flubendiamide + Thiacloprid), Imidacloprid, Thiamethoxam seed treatment and economic impact on fall armyworm (Spodoptera frugiperda) infestation on Maize in Nigeria', 'Iliyasu Mohammed Utono, Rabiu Salisu Adamu', 2023, 'Cogent Food & Agriculture', '10.1080/23311932.2022.2164117', 'https://doi.org/10.1080/23311932.2022.2164117', 'https://www.tandfonline.com/doi/10.1080/23311932.2022.2164117', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Fall Armyworm (FAW) Spodoptera frugiperda infestation in Nigeria has reduced the yield of maize by over 40%, especially where control measures are not implemented adequately or effectively. The concealed feeding behavior of the larvae in the leaf whorl makes its control with insecticide difficult, especially for older larvae as a high volume of insecticide will be required to reach the hidden larvae. This can increase the potential of pest exposure to insecticide, selection pressure and consequent development of resistance. One of the new control strategies being developed for this pest is the use of new insecticides of a different mode of action; Belt Expert (Flubendiamide + Thiacloprid) applied at a threshold of 20% (11,000 plant samples/ha) infestation. Flubendiamide + Thiacloprid gave yields similar to conventional insecticides (Emamectin Benzoate and Lambda-cyhalothrin + Chlorantraniliprole) which were better than the untreated. Another approach is the use of seed treatments (Imidacloprid, Thiamethoxam, Apron plus) followed by 2 foliar sprays with Ampligo (Lambda-cyhalothrin + Chlorantraniliprole) at 2, 4, 6 and 8 weeks after planting (WAP). Treatment with imidacloprid or thiamethoxam seed treatment flowed with foliar application of Ampligo at 4WAP significantly had the lowest larval count and highest percentage maize grain yield with a significant yield increase of >15% over the untreated. The use of insecticide with a different mode of action in the targeted pest density and a seed management-based approach may be significant in the management of pest resistance. Future works should focus on integrating some of these approaches in the management of FAW in Nigeria.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87f0b961-6fe9-434b-ba56-d350cdd91c90', '7708283d-377a-4b89-98e4-5972c9419831', 'Efficacy of Soybean''s Event DAS-81419-2 Expressing Cry1F and Cry1Ac to Manage Key Tropical Lepidopteran Pests Under Field Conditions in Brazil', 'Marques LH, Castro BA, Rossetto J, Silva OA, Moscardini VF, Zobiole LH, Santos AC, Valverde-Garcia P', 2016, 'Journal of economic entomology', '10.1093/jee/tow153', 'https://doi.org/10.1093/jee/tow153', 'https://europepmc.org/articles/PMC5892136?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by-nc', 'Bacillus thuringiensis (Bt) event DAS-81419-2 (Conkesta technology) in soybean, Glycine max (L.) Merrill, expresses Cry1F and Cry1Ac proteins to provide protection from feeding by several lepidopteran pests. A total of 27 field experiments across nine locations were conducted from 2011 to 2015 in southern and central Brazil to characterize the efficacy of DAS-81419-2 soybean infested with Anticarsia gemmatalis Hübner (Lepidoptera: Erebidae), Chrysodeixis includens (Walker) (Lepidoptera: Noctuidae), Heliothis virescens (F.) (Lepidoptera: Noctuidae), and Spodoptera cosmioides (Walker) (Lepidoptera: Noctuidae) during vegetative (V4) and reproductive (R2 and R4) crop developmental stages. The efficacy of DAS-81419-2 was compared to that of a non-Bt isogenic variety managed with or without applications of commercial foliar insecticides for lepidopteran control. DAS-81419-2 soybean consistently experienced defoliation levels of 0.5% or less (compared with 20.05-56.74% in the non-Bt, nonsprayed treatment) and larval survival of < 0.1% in all four species across the vegetative and reproductive plant stages evaluated. The efficacy of DAS-81419-2 was significantly higher than commercial foliar insecticides applied to the non-Bt variety. DAS-81419-2 soybeans containing two highly effective Bt proteins are expected to be a more robust IRM tool compared to single-trait Bt technologies. The consistent efficacy of DAS-81419-2 soybeans across years, locations, and crop stages suggests that it will be a valuable product for management of hard-to-control key lepidopteran pests in South American soybean production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('422b983d-80c0-4e0d-8608-65291b4cf347', '7708283d-377a-4b89-98e4-5972c9419831', 'Evaluation of the efficacy of DDT indoor residual spraying and long-lasting insecticidal nets against insecticide resistant populations of Anopheles arabiensis Patton (Diptera: Culicidae) from Ethiopia using experimental huts', 'Abebe Asale, Yehenew Getachew, Weriessaw Hailesilassie, Niko Speybroeck, Luc Duchateau, Delenasaw Yewhalaw', 2014, 'Parasites & Vectors', '10.1186/1756-3305-7-131', 'https://doi.org/10.1186/1756-3305-7-131', 'https://doi.org/10.1186/1756-3305-7-131', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Indoor Residual Spraying (IRS) and Long-Lasting Insecticidal nets (LLINs) are major malaria vector control tools in Ethiopia. However, recent reports from different parts of the country showed that populations of Anopheles arabiensis, the principal malaria vector, have developed resistance to most families of insecticides recommended for public health use which may compromise the efficacy of both of these key vector control interventions. Thus, this study evaluated the efficacy of DDT IRS and LLINs against resistant populations of An. arabiensis using experimental huts in Asendabo area, southwestern Ethiopia. Methods The susceptibility status of populations of An. arabiensis was assessed using WHO test kits to DDT, deltamethrin, malathion, lambda-cyhalothrin, fenitrothion and bendiocarb. The efficacy of LLIN (PermaNet® 2.0), was evaluated using the WHO cone bioassay. Moreover, the effect of the observed resistance against malaria vector control interventions (DDT IRS and LLINs) were assessed using experimental huts. Results The findings of this study revealed that populations of An. arabiensis were resistant to DDT, deltamethrin, lambda-cyhalothrin and malathion with mortality rates of 1.3%, 18.8%, 36.3% and 72.5%, respectively but susceptible to fenitrothion and bendiocarb with mortality rates of 98.81% and 97.5%, respectively. The bio-efficacy test of LLIN (PermaNet® 2.0) against An. arabiensis revealed that the mosquito population showed moderate knockdown (64%) and mortality (78%). Moreover, mosquito mortalities in DDT sprayed huts and in huts with LLINs were not significantly different (p > 0.05) from their respective controls. Conclusion The evaluation of the efficacy of DDT IRS and LLINs using experimental huts showed that both vector control tools had only low to moderate efficacy against An. arabiensis populations from Ethiopia. Despite DDT being replaced by carbamates for IRS, the low efficacy of LLINs against the resistant population of An. arabiensis is still a problem. Thus, there is a need for alternative vector control tools and implementation of appropriate insecticide resistance management strategies as part of integrated vector management by the national malaria control program.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a1635ad0-4fbe-47e9-b500-b3068e74bc49', '7708283d-377a-4b89-98e4-5972c9419831', 'Extracts from Field Margin Weeds Provide Economically Viable and Environmentally Benign Pest Control Compared to Synthetic Pesticides', 'Mkenda P, Mwanauta R, Stevenson PC, Ndakidemi P, Mtei K, Belmain SR', 2015, 'PloS one', '10.1371/journal.pone.0143530', 'https://doi.org/10.1371/journal.pone.0143530', 'https://europepmc.org/articles/PMC4658159?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Plants with pesticidal properties have been investigated for decades as alternatives to synthetics, but most progress has been shown in the laboratory. Consequently, research on pesticidal plants is failing to address gaps in our knowledge that constrain their uptake. Some of these gaps are their evaluation of their efficacy under field conditions, their economic viability and impact on beneficial organisms. Extracts made from four abundant weed species found in northern Tanzania, Tithonia diversifolia, Tephrosia vogelii, Vernonia amygdalina and Lippia javanica offered effective control of key pest species on common bean plants (Phaseolus vulgaris) that was comparable to the pyrethroid synthetic, Karate. The plant pesticide treatments had significantly lower effects on natural enemies (lady beetles and spiders). Plant pesticide treatments were more cost effective to use than the synthetic pesticide where the marginal rate of return for the synthetic was no different from the untreated control, around 4USD/ha, compared to a rate of return of around 5.50USD/ha for plant pesticide treatments. Chemical analysis confirmed the presence of known insecticidal compounds in water extracts of T. vogelii (the rotenoid deguelin) and T. diversifolia (the sesquiterpene lactone tagitinin A). Sesquiterpene lactones and the saponin vernonioside C were also identified in organic extracts of V. amygdalina but only the saponin was recorded in water extracts which are similar to those used in the field trial. Pesticidal plants were better able to facilitate ecosystem services whilst effectively managing pests. The labour costs of collecting and processing abundant plants near farm land were less than the cost of purchasing synthetic pesticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e7aa154-b30a-4201-85f8-c12c79ac7416', '7708283d-377a-4b89-98e4-5972c9419831', 'First report of widespread kdr-L995F pyrethroid-resistant An. arabiensis and Temporal trends of pyrethroid resistance in urban Ilorin, Kwara State, Nigeria', 'Abiodun Obembe, Tolulope Oyeniyi, Adedayo Olatunbosun Oduola, Folashayo Asekun, Adedapo Adeogun, Samson Awolola', 2025, 'BMC Infectious Diseases', '10.1186/s12879-025-11789-3', 'https://doi.org/10.1186/s12879-025-11789-3', 'https://doi.org/10.1186/s12879-025-11789-3', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Effectiveness of currently deployed insecticide-based malaria vector control measures depends on continuous insecticide resistance monitoring and management. Urban malaria is becoming a serious health problem in Africa partly due to vector resistance in urban areas. To provide insecticide resistance trends information for effective resistance management, this study assessed insecticide susceptibility status and occurrence of knock down resistance mutation in Anopheles mosquitoes from urban Ilorin, Nigeria in two different years. Methods Malaria vectors in urban Ilorin were assayed for susceptibility to WHO-recommended insecticides in 2017 and 2020 using WHO test kits. Sub-sets of exposed An. gambiae s.l. mosquitoes were PCR-assayed for sibling species and knock down resistance (kdr) mutation detection. Results Full mosquito susceptibility (98–100% mortality; Niger and Baruba) and suspected resistance (95–97% mortality; Shao garage and Edun) to alphacypermethrin were recorded in 2017. Significantly (p ≤ 0.010) reduced mosquito mortalities indicating increased alphacypermethrin resistance were recorded in 2020. Permethrin, lambda-cyhalothrin and DDT resistance increased significantly (p ≤ 0.03) from 2017 (42–89%) to 2020 (5.8–58%) but not deltamethrin (p ≥ 0.086). Mosquitoes tested were mostly susceptible to bendiocarb and pirimiphos-methyl. The kdr-L995F detected increased from 15 to 20% for An. arabiensis, 24–36% for An. gambiae and 0–18% for An. coluzzii from 2017 to 2020. For both 2017 and 2020, most of the pyrethroid resistant (≥ 80%) and susceptible (≥ 75%) mosquitoes from each site were identified as An. arabiensis. Conclusions This study presents a first report on widespread occurrence of kdr-L995F mutation in An. arabiensis mosquito populations in urban Ilorin, Kwara State, Nigeria. The report of pyrethroid-resistant An. arabiensis prevalence in urban Ilorin triggered the switch from pyrethroid only to dual active ingredient ITN distribution in the city since 2020. Extension of dry season periods due to climate change may drive more preponderance of An. arabiensis in the study area. Therefore, the implementation of supplementary vector control measures targeted at An. arabiensis is required in this locality.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8fa38b2e-6f06-47f9-a140-71b0059670e4', '7708283d-377a-4b89-98e4-5972c9419831', 'Hemlock Woolly Adelgid (Hemiptera: Adelgidae) Management in Forest, Landscape, and Nursery Production', 'P McCarty E, Addesso KM', 2019, 'Journal of insect science (Online)', '10.1093/jisesa/iez031', 'https://doi.org/10.1093/jisesa/iez031', 'https://europepmc.org/articles/PMC6483940?pdf=render', NULL, NULL, 17, NULL, 'canada', 3, 'cc by-nc', 'Hemlock woolly adelgid, Adelges tsugae (Annand) (Hemiptera: Adelgidae), has caused significant damage to both eastern [Tsuga canadensis (L.) Carrière] and Carolina hemlock (Tsuga caroliniana Englemann) (Pinales: Pinaceae) since it was first reported in the eastern United States. This adelgid is particularly damaging to these hemlock species due to a lack of co-evolved plant defenses and natural enemies able to suppress hemlock woolly adelgid populations. Management of hemlock woolly adelgid relies heavily on insecticides to prevent death of vulnerable trees. Biological control programs have released natural enemies of hemlock woolly adelgid to aid in control at the landscape level. Quarantine restrictions on hemlock are in place in some regions of the United States and Canada. These quarantines impact sales and shipment of hemlock trees from nurseries as well as other hemlock products. A review of insect biology, description of life stages, damage, management options, and quarantine restrictions for hemlock woolly adelgid is presented.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e887ace4-c78e-42a7-9954-ef613a364790', '7708283d-377a-4b89-98e4-5972c9419831', 'How varying parameters impact insecticide resistance bioassay: An example on the worldwide invasive pest Drosophila suzukii', 'Blouquy L, Mottet C, Olivares J, Plantamp C, Siegwart M, Barrès B', 2021, 'PloS one', '10.1371/journal.pone.0247756', 'https://doi.org/10.1371/journal.pone.0247756', 'https://europepmc.org/articles/PMC7935283?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Monitoring pesticide resistance is essential for effective and sustainable agricultural practices. Bioassays are the basis for pesticide-resistance testing, but devising a reliable and reproducible method can be challenging because these tests are carried out on living organisms. Here, we investigated five critical parameters and how they affected the evaluation of resistance to the organophosphate phosmet or the pyrethroid lambda-cyhalothrin using a tarsal-contact protocol on Drosophila suzukii, a worldwide invasive pest. Three of the parameters were related to insect biology: (i) sex, (ii) age of the imago (adult stage) and (iii) genetic diversity of the tested population. The two remaining parameters were linked to the experimental setup: (iv) the number of individuals tested per dose and (v) the duration of exposure to the active ingredient. Results showed that response to insecticide differed depending on sex, males being twice as susceptible to phosmet as females. Age principally affected young females'' susceptibility to phosmet, because 0-24 hour-old flies were twice as susceptible as 24-48 hour-old and 72-96 hour-old females. Genetic diversity had no observable effect on resistance levels. The precision and accuracy of the median lethal dose (LD50) were greatly affected by the number of individuals tested per dose with a threshold effect. Finally, optimal duration of exposure to the active ingredient was 24 h, as we found an underestimation of mortality when assessed between 1 and 5 h after exposure to lambda-cyhalothrin. None of the main known point mutations on the para sodium channel gene associated with a knockdown effect were observed. Our study demonstrates the importance of calibrating the various parameters of a bioassay to develop a reliable method. It also provides a valuable and transferable protocol for monitoring D. suzukii resistance worldwide.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('be672cba-3a13-484e-9c30-08f363eb12b7', '7708283d-377a-4b89-98e4-5972c9419831', 'Influence of temperature on the toxicity and stability of insecticide resistance against Spodoptera littoralis (Lepidoptera: Noctuidae)', 'Seham Mansour Ismail', 2023, 'Bulletin of the National Research Centre', '10.1186/s42269-023-01061-6', 'https://doi.org/10.1186/s42269-023-01061-6', 'https://doi.org/10.1186/s42269-023-01061-6', NULL, NULL, 5, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Spodoptera littoralis Boisad. (Lepidoptera: Noctuidae) is an important pest causing significant losses to agricultural crops worldwide. Management practices for this insect pest rely on insecticides applications throughout the entire season over wide ranging temperature. However, studies involving the development of resistance in S. littoralis against these insecticides at different temperatures are limited. Methods Using leaf-dipping bioassay technique, the effect of temperature (range, 15–30 °C) on the toxicity of spinosad, lambda-cyhalothrin and methomyl, and resistance development was evaluated in larvae S. littoralis. Results Spinosad, lambda-cyhalothrin and methomyl exhibited increased toxicity with increasing temperature from 15 to 30 °C. The results indicated a successive decrease in insecticide resistance at the temperatures of 15, 20, 25 and 30 °C from 1st to 12th generations of S. littoralis to spinosad, lambda-cyhalothrin and methomyl. Conclusions This study suggests that spinosad, lambda-cyhalothrin, and methomyl can be included in the management of S. littoralis.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('45c0d698-4331-4330-a0c6-0099448da893', '7708283d-377a-4b89-98e4-5972c9419831', 'Influence of time of day and insecticide treatment on the abundance of Culiseta melanura (Diptera: Culicidae) in resting boxes', 'Brown N, Keven JB, Walker ED', 2026, 'Journal of medical entomology', '10.1093/jme/tjag076', 'https://doi.org/10.1093/jme/tjag076', 'https://europepmc.org/articles/PMC13211986?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'Frequent use of resting boxes by Culiseta melanura (Coquillett) during the day-time may offer the opportunity for use of these artificial resting sites as delivery substrates for insecticides to manage populations of this eastern equine encephalitis virus (EEEV) vector. In field studies at EEEV-endemic foci in southwestern Michigan, abundance in black-painted resting boxes of adult male and female Cs. melanura varied within the 24-h diel cycle, by whether the interiors of the boxes were treated with a microencapsulated formulation of lambda cyhalothrin (Demand CSTM), and from before to after treatment of boxes at field sites. Abundance was highest at noon, diminished to nil at midnight, and increased by noon the following day. Abundance of Cs. melanura was lower in insecticide-treated boxes compared to untreated boxes, and declined at field sites sampled after treatment of boxes with microencapsulated lambda cyhalothrin, compared to before treatment and to control sites. This population suppression effect lasted at least 30 days and exceeded 90% reduction. Field-caught Cs. melanura males and females experienced high mortality when exposed to lambda cyhalothrin-treated bottles in bottle bioassays and in overnight exposures to treated boxes set in the laboratory. Prolonged daily visits to resting boxes, resulting in exposure to residual insecticide, may explain the sustained, diminishing effect on abundance of field populations of Cs. melanura. Results support use of insecticide-treated boxes distributed into wooded upland edges of natural larval habitats as an intervention against EEEV transmission.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1885912b-65c8-4661-b361-4eb4f36550d6', '7708283d-377a-4b89-98e4-5972c9419831', 'Insecticide Resistance in Aedes aegypti from the National Capital Region of the Philippines', 'Richard Paul B. Malijan, Jason R. Angeles, Ariza Minelle A. Apilado, Mary Ann T. Ammugauan, Ferdinand V. Salazar', 2024, 'Insects', '10.3390/insects15100782', 'https://doi.org/10.3390/insects15100782', 'https://www.mdpi.com/2075-4450/15/10/782', NULL, NULL, 23, NULL, 'other', 1, 'open access (DOAJ)', 'Human arboviral diseases such as dengue, chikungunya, and Zika can be transmitted by the mosquito Aedes aegypti. The insecticide-based vector control strategy is critical in reducing transmission of these Aedes-borne diseases but is threatened mainly by the emergence of insecticide resistance. Adult Ae. aegypti from the National Capital Region (NCR), Philippines, were subjected to bioassays to determine their susceptibility to diagnostic doses of pyrethroid, organochlorine, and organophosphate insecticides following the standard World Health Organization insecticide susceptibility test. This study reports the detection of insecticide resistance to pyrethroids and organochlorine in Ae. aegypti from the Philippines for the first time. Most of the Ae. aegypti populations from NCR exhibited phenotypic resistance to permethrin, etofenprox, and DDT. Varying resistance levels to deltamethrin, cyfluthrin, and lambda-cyhalothrin were observed in the different mosquito populations, while all populations tested to malathion were susceptible to this organophosphate. This finding should alert public health authorities to consider modifying the existing vector management package for greater control efficacy. Best practices proven to prevent or delay the development of insecticide resistance, such as insecticide rotation, should also be implemented, while alternative chemicals with a different mode of action should be explored to ensure the continuing efficacy of program interventions.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35308201-a40f-49b2-a632-63ab208fcc46', '7708283d-377a-4b89-98e4-5972c9419831', 'Integrated Fruit Production and Pest Management in Europe: The Apple Case Study and How Far We Are From the Original Concept?', 'Damos P, Colomar LA, Ioriatti C', 2015, 'Insects', '10.3390/insects6030626', 'https://doi.org/10.3390/insects6030626', 'https://europepmc.org/articles/PMC4598656?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'This review focuses on the process of adapting the original concept of Integrated Pest Management (IPM) to the wider conception of the Integrated Fruit Production (IFP) implemented in Europe. Even though most of the pest management strategies still rely on the use of synthetic pesticides, a wide array of innovative and environmentally friendly tools are now available as possible alternative to the pesticides within the modern apple production system. We also highlight how recent pest management strategies and tools have created an opening for research towards IPM improvement, including the use of biorational pesticides, semiochemicals and biological control. Forecasting models, new tree training systems and innovative spray equipment have also been developed to improve treatment coverage, to mitigate pesticide drift and to reduce chemical residues on fruits. The possible threats that jeopardize the effective implementation of IPM and particularly the risks related to the development of the pesticide resistance and the introduction of new invasive pests are also reviewed. With the directive 128/09, the European legislation recognizes IPM as a strategic approach for the sustainable use of pesticides. Within this context, IPM and related guidelines is called to meet different areas of concern in relation to the worker and bystander safety. Beside the traditional economic criteria of the market-oriented agriculture, sustainable agriculture includes the assessment of the environmental impact of the agronomic practices within the societal context where they take place. As a consequence of the raising consumer concerns about environmental impacts generated by the fruit production, IFP certification over product standards, including process aspects, are frequently required by consumers and supermarket chains.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f26dbde-2273-4248-8fcf-d40577c2f814', '7708283d-377a-4b89-98e4-5972c9419831', 'IPM reduces insecticide applications by 95% while maintaining or enhancing crop yields through wild pollinator conservation', 'Pecenka JR, Ingwell LL, Foster RE, Krupke CH, Kaplan I', 2021, 'Proceedings of the National Academy of Sciences of the United States of America', '10.1073/pnas.2108429118', 'https://doi.org/10.1073/pnas.2108429118', 'https://europepmc.org/articles/PMC8612243?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Pest management practices in modern industrial agriculture have increasingly relied on insurance-based insecticides such as seed treatments that are poorly correlated with pest density or crop damage. This approach, combined with high invertebrate toxicity for newer products like neonicotinoids, makes it challenging to conserve beneficial insects and the services that they provide. We used a 4-y experiment using commercial-scale fields replicated across multiple sites in the midwestern United States to evaluate the consequences of adopting integrated pest management (IPM) using pest thresholds compared with standard conventional management (CM). To do so, we employed a systems approach that integrated coproduction of a regionally dominant row crop (corn) with a pollinator-dependent specialty crop (watermelon). Pest populations, pollination rates, crop yields, and system profitability were measured. Despite higher pest densities and/or damage in both crops, IPM-managed pests rarely reached economic thresholds, resulting in 95% lower insecticide use (97 versus 4 treatments in CM and IPM, respectively, across all sites, crops, and years). In IPM corn, the absence of a neonicotinoid seed treatment had no impact on yields, whereas IPM watermelon experienced a 129% increase in flower visitation rate by pollinators, resulting in 26% higher yields. The pollinator-enhancement effect under IPM management was mediated entirely by wild bees; foraging by managed honey bees was unaffected by treatments and, overall, did not correlate with crop yield. This proof-of-concept experiment mimicking on-farm practices illustrates that cropping systems in major agricultural commodities can be redesigned via IPM to exploit ecosystem services without compromising, and in some cases increasing, yields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f85ceec1-6649-409b-95e7-44e33f48e8a5', '699c7577-eb88-4579-895f-df444934cf8f', 'Functionalized Magnetic Nanomaterials in Agricultural Applications', 'Spanos A, Athanasiou K, Ioannou A, Fotopoulos V, Krasia-Christoforou T', 2021, 'Nanomaterials (Basel, Switzerland)', '10.3390/nano11113106', 'https://doi.org/10.3390/nano11113106', 'https://europepmc.org/articles/PMC8623625?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'The development of functional nanomaterials exhibiting cost-effectiveness, biocompatibility and biodegradability in the form of nanoadditives, nanofertilizers, nanosensors, nanopesticides and herbicides, etc., has attracted considerable attention in the field of agriculture. Such nanomaterials have demonstrated the ability to increase crop production, enable the efficient and targeted delivery of agrochemicals and nutrients, enhance plant resistance to various stress factors and act as nanosensors for the detection of various pollutants, plant diseases and insufficient plant nutrition. Among others, functional magnetic nanomaterials based on iron, iron oxide, cobalt, cobalt and nickel ferrite nanoparticles, etc., are currently being investigated in agricultural applications due to their unique and tunable magnetic properties, the existing versatility with regard to their (bio)functionalization, and in some cases, their inherent ability to increase crop yield. This review article provides an up-to-date appraisal of functionalized magnetic nanomaterials being explored in the agricultural sector.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('004a0b62-c66d-479f-bcf4-dbe23512a3e1', '7708283d-377a-4b89-98e4-5972c9419831', 'Microbial Symbiont-Based Detoxification of Different Phytotoxins and Synthetic Toxic Chemicals in Insect Pests and Pollinators', 'Kline O, Joshi NK', 2024, 'Journal of xenobiotics', '10.3390/jox14020043', 'https://doi.org/10.3390/jox14020043', 'https://europepmc.org/articles/PMC11204611?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Insects are the most diverse form of life, and as such, they interact closely with humans, impacting our health, economy, and agriculture. Beneficial insect species contribute to pollination, biological control of pests, decomposition, and nutrient cycling. Pest species can cause damage to agricultural crops and vector diseases to humans and livestock. Insects are often exposed to toxic xenobiotics in the environment, both naturally occurring toxins like plant secondary metabolites and synthetic chemicals like herbicides, fungicides, and insecticides. Because of this, insects have evolved several mechanisms of resistance to toxic xenobiotics, including sequestration, behavioral avoidance, and enzymatic degradation, and in many cases had developed symbiotic relationships with microbes that can aid in this detoxification. As research progresses, the important roles of these microbes in insect health and function have become more apparent. Bacterial symbionts that degrade plant phytotoxins allow host insects to feed on otherwise chemically defended plants. They can also confer pesticide resistance to their hosts, especially in frequently treated agricultural fields. It is important to study these interactions between insects and the toxic chemicals they are exposed to in order to further the understanding of pest insect resistance and to mitigate the negative effect of pesticides on nontarget insect species like Hymenopteran pollinators.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf4f5c81-c6dd-4584-89e8-27cff0b20861', '7708283d-377a-4b89-98e4-5972c9419831', 'Neurotoxic Effects of Pesticides: Implications for Neurodegenerative and Neurobehavioral Disorders', 'Botnaru AA, Lupu A, Morariu PC, Jităreanu A, Nedelcu AH, Morariu BA, Anton E, Di Gioia ML', 2025, 'Journal of xenobiotics', '10.3390/jox15030083', 'https://doi.org/10.3390/jox15030083', 'https://europepmc.org/articles/PMC12193934?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Pesticides play an essential role in modern agriculture, yet increasing evidence links their widespread use to neurotoxic effects that contribute to both neurodegenerative and neurodevelopmental disorders. In recent years, new classes of pesticides such as neonicotinoids and pyrethroids have garnered attention due to their potential to disrupt neurodevelopment, even at low exposure levels. Furthermore, emerging evidence underscores the involvement of the gut-brain axis, neuroinflammation, and epigenetic modulation in pesticide-induced neuropathology. This review aims to synthesize these latest advancements while highlighting underexplored mechanisms, thereby offering a comprehensive and current perspective on pesticide-related neurotoxicity. Data from the Rapid Alert System for Food and Feed (RASFF) indicate that several food products include residues of pesticides recognized for their neurotoxic properties. Although environmental exposure levels are lower than those in occupational contexts, the magnitude and persistence of food-based exposure demand thorough evaluation. This review integrates evidence coming from epidemiological, in vivo and in vitro investigations, emphasizing the correlations between pesticide exposure and conditions such as Alzheimer''s disease, Parkinson''s disease, and cognitive deficits in children. Neurodevelopmental toxicity is especially alarming since symptoms may manifest subtly and with a delayed onset after early-life exposure, indicating the significant neurotoxic potential of pesticide residues and emphasizing the need for their careful evaluation in food safety assessments. Improved regulatory procedures and public health efforts are essential to reducing long-term brain damage.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8960ffef-4b64-41f4-ba96-5c8d802a6b4c', '7708283d-377a-4b89-98e4-5972c9419831', 'Popillia japonica - Italian outbreak management', 'Gotta P, Ciampitti M, Cavagna B, Bosio G, Gilioli G, Alma A, Battisti A, Mori N', 2023, 'Frontiers in insect science', '10.3389/finsc.2023.1175138', 'https://doi.org/10.3389/finsc.2023.1175138', 'https://europepmc.org/articles/PMC10926379?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Popillia japonica, a priority pest for the EU, was first detected in Northern Italy in 2014. Since its discovery, the outbreak extended over an area of more than 16,000 square kilometers in Northern Italy and Southern Switzerland. In this review, we summarize the state-of-the-art of research conducted in Italy on both the spreading capacity and control measures of P. japonica. Chemical, physical, and biological control measures deployed since its detection are presented, by highlighting their strengths and weaknesses. An in-depth study of the ecosystems invaded by P. japonica disclosed the presence and pathogenicity of natural strains of entomopathogenic fungi and nematodes, some of which have shown to be particularly aggressive towards the larvae of this pest under laboratory conditions. The Plant Health authorities of the Lombardy and Piedmont regions, with the support of several research institutions, played a crucial role in the initial eradication attempt and subsequently in containing the spread of P. japonica. Control measures were performed in the infested area to suppress adult populations of P. japonica by installing several traps (e.g., for mass trapping, for auto-dissemination of the fungus Metarhizium anisopliae, and "attract & kill"). For larval control, the infested fields were treated with commercial strains of the entomopathogenic fungus M. anisopliae and nematode Heterorhabditis bacteriophora. Future studies will aim at integrating phenological and spread models developed with the most effective control measures, within an ecologically sustainable approach.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('882ec0dd-1dfe-40f8-8247-80a473b3d891', '7708283d-377a-4b89-98e4-5972c9419831', 'Rational Practices to Manage Boll Weevils Colonization and Population Growth on Family Farms in the Semiárido Region of Brazil', 'Neves RC, Colares F, Torres JB, Santos RL, Bastos CS', 2014, 'Insects', '10.3390/insects5040818', 'https://doi.org/10.3390/insects5040818', 'https://europepmc.org/articles/PMC4592620?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Because boll weevil, Anthonomus grandis Boh. develops partially protected inside cotton fruiting structures, once they become established in a field, they are difficult to control, even with nearly continuous insecticide spray. During two cotton-growing seasons in the Semiárido region of Pernambuco State, Brazil, we tested the use of kaolin sprays to disrupt plant colonization through visual cue interference, combined with removal of fallen fruiting bodies to restrain boll weevil population growth after colonization. Kaolin spray under non-choice trials resulted in 2.2×, 4.4×, and 8.6× fewer weevils, oviposition and feeding punctures on kaolin-treated plants, respectively, despite demonstrating no statistical differences for colonization and population growth. Early season sprays in 2010 occurred during a period of rainfall, and hence, under our fixed spraying schedule no significant differences in boll weevil colonization were detected. In 2011, when kaolin sprays were not washed out by rain, delayed boll weevil colonization and reduction on attacked fruiting bodies were observed in eight out of 12 evaluations, and kaolin-treated plots had 2.7× fewer damaged fruiting bodies compared to untreated plots. Adoption of simple measures such as removal of fallen fruiting bodies and prompt reapplication of kaolin sprays after rainfall show promise in reducing boll weevil infestation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('acb31892-9218-424f-aa36-622b13088c89', '7708283d-377a-4b89-98e4-5972c9419831', 'Seed treatment using methyl jasmonate induces resistance to rice water weevil but reduces plant growth in rice', 'Kraus EC, Stout MJ', 2019, 'PloS one', '10.1371/journal.pone.0222800', 'https://doi.org/10.1371/journal.pone.0222800', 'https://europepmc.org/articles/PMC6756538?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The jasmonic acid cascade plays a pivotal role in induced plant resistance to herbivores. There have been a number of investigations into the potential uses of derivatives of this hormone for pest management. Understanding the phenotypic plasticity of plant defense traits interactions in agricultural systems may facilitate the development of novel and improved management practices, which is desirable as management of insects in most agricultural systems is currently heavily reliant on insecticides. The rice water weevil (RWW), Lissorhoptrus oryzophilus Kuschel, is a pest of rice, Oryza sativa, in the southern U.S. and globally. The effects of the jasmonic acid derivative, methyl jasmonate (MJ), on induced defenses to RWW in rice, and the potential costs of MJ-induced resistance to plant growth and fitness, were tested in a series of field and greenhouse trials. It was hypothesized that seed treatments with MJ would reduce densities of larval RWW. A second hypothesis was that MJ seed treatments would alter emergence, biomass accumulation, and yield of rice. The final hypothesis was that induction of plant resistance to the RWW would diminish as the time from seed treatment increased. In order to investigate these hypotheses, RWW densities were determined in greenhouse and field trials. Plant growth was measured in the field by assessing plant emergence, root and shoot biomass, time of heading, and yield (grain mass). Results indicated that MJ seed treatments induced resistance to RWW, although this effect decayed over time. Additionally, there were costs to plant growth and fitness; emergence and heading were delayed and biomass was reduced. Importantly, however, yields on a per-plant were not significantly reduced by MJ treatment. Overall, these results are promising and show the potential for the use of jasmonate elicitors as part of a pest management program in rice.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('73e91036-6669-4be4-a404-009ecbd11e75', '7708283d-377a-4b89-98e4-5972c9419831', 'Temporal Variation in Insecticide Susceptibility of Field-Derived Drosophila suzukii from UK Soft-Fruit Farms', 'Bethan Shaw, Trisna D. Tungadi, Greg Deakin, Michelle T. Fountain', 2026, 'Agronomy', '10.3390/agronomy16181783', 'https://doi.org/10.3390/agronomy16181783', 'https://www.mdpi.com/2073-4395/16/18/1783', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Drosophila suzukii is a globally invasive pest that lays eggs in ripening fruit, causing degradation through larval feeding and significant economic losses. Control of D. suzukii relies on integrated pest management, combining cultural, biological and chemical methods, with insecticide applications serving as a final line of defence. This study investigated whether regular insecticide use in United Kingdom (UK) soft-fruit crops resulted in reduced between- and within-year susceptibility of D. suzukii to three commonly used insecticides. Field-collected D. suzukii were used to establish laboratory strains from summer collections in 2019, 2020 and 2021, and autumn collections in 2020. Strains were reared for 8–10 generations before exposure to a range of concentrations of cyantraniliprole, lambda-cyhalothrin and spinosad in mortality bioassays. No consistent directional increase in LC50 was observed across the three sampling years. However, more than half of the strains established from autumn 2020 collections showed reduced susceptibility to some insecticides compared with strains from the same locations collected four months earlier, with a 1.4–2.1-fold increase in LC50. These results indicate generally stable susceptibility in UK populations while highlighting the value of continued resistance monitoring.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('398ac0cd-e67f-42bc-9afa-eb849289d0d8', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'The Invasive Mechanisms of the Noxious Alien Plant Species Bidens pilosa', 'Kato-Noguchi H, Kurniadie D', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13030356', 'https://doi.org/10.3390/plants13030356', 'https://europepmc.org/articles/PMC10857670?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Bidens pilosa L. is native to tropical America and has widely naturized from tropical to warm temperate regions in Europe, Africa, Asia, Australia, and North and South America. The species has infested a wide range of habitats such as grasslands, forests, wetlands, streamlines, coastal areas, pasture, plantations, agricultural fields, roadsides, and railway sides and has become a noxious invasive weed species. B. pilosa forms thick monospecific stands, quickly expands, and threatens the indigenous plant species and crop production. It is also involved in pathogen transmission as a vector. The species was reported to have (1) a high growth ability, producing several generations in a year; (2) a high achene production rate; (3) different biotypes of cypselae, differently germinating given the time and condition; (4) a high adaptative ability to various environmental conditions; (5) an ability to alter the microbial community, including mutualism with arbuscular mycorrhizal fungi; and (6) defense functions against natural enemies and allelopathy. The species produces several potential allelochemicals such as palmitic acid, p-coumaric acid, caffeic acid, ferulic acid, p-hydroxybenzoic acid, vanillic acid, salycilic acid, quercetin, α-pinene, and limonene and compounds involved in the defense functions such as 1-phenylhepta-1,3,5-trine, 5-phenyl-2-(1-propynyl)-thiophene, 5-actoxy-2-phenylethinyl-thiophene, and icthyothereol acetate. These characteristics of B. pilosa may contribute to the naturalization and invasiveness of the species in the introduced ranges. This is the first review article focusing on the invasive mechanisms of the species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2f96d5d5-bde5-4921-8b27-60fc72c4b8ce', '7708283d-377a-4b89-98e4-5972c9419831', 'The control of malaria vectors in rice fields: a systematic review and meta-analysis', 'Chan K, Bottomley C, Saito K, Lines J, Tusting LS', 2022, 'Scientific reports', '10.1038/s41598-022-24055-2', 'https://doi.org/10.1038/s41598-022-24055-2', 'https://europepmc.org/articles/PMC9668837?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The relatively stable aquatic conditions of irrigated lowland and rainfed rice, which is grown across 145 million hectares in more than 100 countries, are capable of generating large numbers of mosquito vectors of malaria, which causes more than 400,000 deaths per year worldwide. Many methods can control these vectors, but a systematic review has not previously been conducted. This study assesses whether larviciding, fish or intermittent irrigation can significantly reduce malaria vectors in rice fields whilst increasing rice yield. After a literature search for studies reporting the effect of larval control and rice cultivation practices on malaria vector densities in rice fields, 33 studies were eligible for meta-analysis. Larviciding was effective at reducing rice-field malaria vectors. Pooled analysis of five controlled time-series (CTS) studies with chemical insecticides showed an overall combined reduction of larval densities of 77% compared to no larviciding. Eight CTSs with biological larvicides showed a pooled reduction of 60% compared to no larviciding. Cultivating rice and fish together provided good control too: a pooled analysis of three CTSs showed an overall 82% reduction in anopheline larvae compared to no fish. Pooled analysis of four studies suggested that intermittent irrigation (using various timings and frequencies of drainage) is effective at reducing the abundance of late-stage anopheline larvae (pooled reduction = - 35%), but not overall immature abundance, compared to continuous flooding. We conclude that many interventions such as larvicides, fish and intermittent irrigation can provide riceland malaria vector control, but the critical obstacle to wider use is farmer acceptability. Future research should be led by the agricultural sector, with inputs from entomologists, to investigate malaria control co-benefits within high-yielding rice cultivation practices.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('073044d3-3fdc-4f30-b90c-323718729374', '7708283d-377a-4b89-98e4-5972c9419831', 'The Efficacy of Alternative, Environmentally Friendly Plant Protection Measures for Control of Fall Armyworm, Spodoptera Frugiperda, in Maize', 'Babendreier D, Koku Agboyi L, Beseh P, Osae M, Nboyine J, Ofori SEK, Frimpong JO, Attuquaye Clottey V', 2020, 'Insects', '10.3390/insects11040240', 'https://doi.org/10.3390/insects11040240', 'https://europepmc.org/articles/PMC7240539?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'The invasive fall armyworm (FAW) is threatening maize production and the livelihoods of millions of smallholder farmers in the newly invaded areas in Africa and Asia. To control this new key pest and to overcome health, environmental, and resistance problems related to the indiscriminate use of insecticides, effective and sustainable alternative pest control approaches are needed. Here, we report on field trials that tested maltodextrin, neem-based products, ash, and soil, as well as the locally produced alata samina soap, in the Upper West and Greater Accra regions, Ghana. Significant reductions of larval numbers and crop damage, together with increased yields, were mostly achieved by applying the insecticide emamectin benzoate, which was considered the positive control in this set of trials. However, high efficiency and cost-benefit ratios were also achieved with two neem-based products. Maltodextrin was only efficient at one of the two sites, with a clear dose-dependent effect, while the higher dosage was nearly as effective as emamectin benzoate. Due to its relatively high product cost, maltodextrin is generally less cost-efficient. Ash and soil, as well as alata samina soap treatments, did not efficiently reduce FAW larval numbers or crop damage at the dosages tested; thus, they also did not significantly increase maize yields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('da286819-f14b-45d3-a355-a6ac67bc30a8', '7708283d-377a-4b89-98e4-5972c9419831', 'Upregulation of a cytochrome P450 gene, CYP6B50, confers multi-insecticide resistance in Spodoptera frugiperda', 'Guo Z, Tang J, Ling S, Zheng C, Bass C, He S, Wan H, Li J', 2026, 'Journal of advanced research', '10.1016/j.jare.2025.06.083', 'https://doi.org/10.1016/j.jare.2025.06.083', 'https://europepmc.org/articles/PMC13000958?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'IntroductionThe fall armyworm, Spodoptera frugiperda, is a globally invasive pest that has developed resistance to numerous insecticides. Cytochrome P450 enzymes have been commonly implicated in insecticide resistance in insect pests, including in S. frugiperda.ObjectiveOur previous study revealed that the P450 gene CYP6B50 was significantly overexpressed in a multi-insecticide resistant strain of S. frugiperda. However, the functional role of CYP6B50 in conferring multiple resistance remains unclear.MethodsHere we used reverse genetic (RNAi, CRISPR/Cas9, and transgenic Drosophila melanogaster) and computational modelling approaches to investigate the role of CYP6B50 in resistance to insecticides.ResultsFunctional analysis revealed that CYP6B50 is highly expressed during the larval stage of S. frugiperda, particularly in key tissues associated with detoxification such as the fat body, midgut, hemolymph, and Malpighian tubules. The expression of CYP6B50 was significantly upregulated after exposure to the insecticides indoxacarb, chlorantraniliprole, lambda-cyhalothrin, tetrachlorantraniliprole, and deltamethrin. Functional validation of CYP6B50 confirmed its contribution to resistance against the five tested insecticides. Molecular docking revealed a strong binding affinity of CYP6B50 to these insecticides.ConclusionsThese results identify CYP6B50 as a key generalist detoxification P450 in S. frugiperda and its role in mediating resistance to multiple insecticides. These findings provide insights into the role of cytochrome P450s in the evolution of insecticide resistance and will inform the development of strategies to manage or overcome resistance in a globally distributed crop pest.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18bc4aac-3eb7-4d4a-9b0c-ead06735b7ce', '699c7577-eb88-4579-895f-df444934cf8f', 'Application of filamentous phages in environment: A tectonic shift in the science and practice of ecorestoration', 'Sharma RS, Karmakar S, Kumar P, Mishra V', 2019, 'Ecology and evolution', '10.1002/ece3.4743', 'https://doi.org/10.1002/ece3.4743', 'https://europepmc.org/articles/PMC6392359?pdf=render', NULL, NULL, 42, NULL, 'other', 1, 'cc by', 'Theories in soil biology, such as plant-microbe interactions and microbial cooperation and antagonism, have guided the practice of ecological restoration (ecorestoration). Below-ground biodiversity (bacteria, fungi, invertebrates, etc.) influences the development of above-ground biodiversity (vegetation structure). The role of rhizosphere bacteria in plant growth has been largely investigated but the role of phages (bacterial viruses) has received a little attention. Below the ground, phages govern the ecology and evolution of microbial communities by affecting genetic diversity, host fitness, population dynamics, community composition, and nutrient cycling. However, few restoration efforts take into account the interactions between bacteria and phages. Unlike other phages, filamentous phages are highly specific, nonlethal, and influence host fitness in several ways, which make them useful as target bacterial inocula. Also, the ease with which filamentous phages can be genetically manipulated to express a desired peptide to track and control pathogens and contaminants makes them useful in biosensing. Based on ecology and biology of filamentous phages, we developed a hypothesis on the application of phages in environment to derive benefits at different levels of biological organization ranging from individual bacteria to ecosystem for ecorestoration. We examined the potential applications of filamentous phages in improving bacterial inocula to restore vegetation and to monitor changes in habitat during ecorestoration and, based on our results, recommend a reorientation of the existing framework of using microbial inocula for such restoration and monitoring. Because bacterial inocula and biomonitoring tools based on filamentous phages are likely to prove useful in developing cost-effective methods of restoring vegetation, we propose that filamentous phages be incorporated into nature-based restoration efforts and that the tripartite relationship between phages, bacteria, and plants be explored further. Possible impacts of filamentous phages on native microflora are discussed and future areas of research are suggested to preclude any potential risks associated with such an approach.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a5998732-fc7f-4343-b518-74b8a62280c4', '699c7577-eb88-4579-895f-df444934cf8f', 'Biology, Ecology, Distribution and Control of the Invasive Weed, Lactuca serriola L. (Wild Lettuce): A Global Review', 'Chadha A, Florentine S', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10102157', 'https://doi.org/10.3390/plants10102157', 'https://europepmc.org/articles/PMC8541585?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by', 'Lactuca serriola L. (wild lettuce) is a highly invasive C3 weed in many countries, including Australia, Canada, and the USA. This weed is a severe threat to agricultural systems, especially in crops grown with reduced or no-tillage approaches, which commonly include wheat, cereals and pulses. Owing to the vertical orientation of its leaves in the north-south plane and its root architecture, L. serriola can maintain high water use efficiency under drought conditions, giving it the ability to expand its range under a drying climate. Each plant can produce up to 100,000 seeds which have no primary dormancy and form a short-term seedbank lasting up to three years. Most seedlings emerge in autumn and overwinter as a rosette, with a small flush of emergence in spring depicting staggered germination. Research into control methods for this weed has been performed, and these methods include chemical herbicides applied alone and in combination, the establishment of plant competition, tillage, mowing and bioherbicide. Herbicides can provide effective control when applied in the seedling or rosette stage; however, spring germination is difficult to control, as it skips the rosette stage. Some biotypes are now resistant to ALS inhibitor and synthetic auxins, causing concern regarding using herbicides. A dedicated integrated management plan for 3-4 years is recommended for the control of this troublesome species. This review will explore the biology, ecology, distribution, current control techniques and previous research on this weed, allowing us to make recommendations for its future research and management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('62685f1d-d5a3-4518-82ad-62639bb19608', '699c7577-eb88-4579-895f-df444934cf8f', 'Biomarkers in Stress Related Diseases/Disorders: Diagnostic, Prognostic, and Therapeutic Values', 'Dhama K, Latheef SK, Dadar M, Samad HA, Munjal A, Khandia R, Karthik K, Tiwari R', 2019, 'Frontiers in molecular biosciences', '10.3389/fmolb.2019.00091', 'https://doi.org/10.3389/fmolb.2019.00091', 'https://europepmc.org/articles/PMC6843074?pdf=render', NULL, NULL, 50, NULL, 'other', 1, 'cc by', 'Various internal and external factors negatively affect the homeostatic equilibrium of organisms at the molecular to the whole-body level, inducing the so-called state of stress. Stress affects an organism''s welfare status and induces energy-consuming mechanisms to combat the subsequent ill effects; thus, the individual may be immunocompromised, making them vulnerable to pathogens. The information presented here has been extensively reviewed, compiled, and analyzed from authenticated published resources available on Medline, PubMed, PubMed Central, Science Direct, and other scientific databases. Stress levels can be monitored by the quantitative and qualitative measurement of biomarkers. Potential markers of stress include thermal stress markers, such as heat shock proteins (HSPs), innate immune markers, such as Acute Phase Proteins (APPs), oxidative stress markers, and chemical secretions in the saliva and urine. In addition, stress biomarkers also play critical roles in the prognosis of stress-related diseases and disorders, and therapy guidance. Moreover, different components have been identified as potent mediators of cardiovascular, central nervous system, hepatic, and nephrological disorders, which can also be employed to evaluate these conditions precisely, but with stringent validation and specificity. Considerable scientific advances have been made in the detection, quantitation, and application of these biomarkers. The present review describes the current progress of identifying biomarkers, their prognostic, and therapeutic values.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('20e9596f-65bb-4b0c-9d62-4b08762335e1', '699c7577-eb88-4579-895f-df444934cf8f', 'Genotype and Environment Effects on Prebiotic Carbohydrate Concentrations in Kabuli Chickpea Cultivars and Breeding Lines Grown in the U.S. Pacific Northwest', 'Vandemark G, Thavarajah S, Siva N, Thavarajah D', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00112', 'https://doi.org/10.3389/fpls.2020.00112', 'https://europepmc.org/articles/PMC7046681?pdf=render', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc by', 'Prebiotic carbohydrates are compounds that include simple sugars, sugar alcohols, and raffinose family oligosaccharides, which are fermented by gut bacteria and can influence the species profile of the gut microbiome to reduce obesity and weight gain. Prebiotic carbohydrates are also associated with several health benefits including reduced insulin dependence and incidence of colorectal cancer. Although pulse crops such as chickpea have been important sources of nutrition for human diets for thousands of years, relatively little is known about the profiles of prebiotic carbohydrates in pulse crops. The objectives of this study were to characterize the type and concentration of seed prebiotic carbohydrates in 18 kabuli chickpea genotypes grown in 2017 and 2018 in Idaho and Washington, and partition variance components conditioning these nutritional quality traits in chickpea. Genotype effects were significant for fructose, sucrose, raffinose, and kestose. Environment effects were also significant for several carbohydrates. However, year effects were the greatest sources of variance for all carbohydrates. Concentrations of most carbohydrates were significantly greater in 2017, when there was less precipitation during the growing season coupled with greater heat stress during grain filling than in 2018. This may reflect the role of many of these carbohydrates as osmoprotectants produced in response to heat and water stress. Overall, our results suggest that a survey of more genetically diverse plant materials, such as a chickpea ''mini-core'' collection, may reveal genotypes that produce significantly greater concentrations of selected prebiotic carbohydrates and could be used to introduce desirable nutritional traits into adapted chickpea cultivars.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('072e9936-94d3-4702-a83b-864498cce578', '699c7577-eb88-4579-895f-df444934cf8f', 'Involvement of Carnosic Acid in the Phytotoxicity of Rosmarinus officinalis Leaves', 'Appiah KS, Mardani HK, Omari RA, Eziah VY, Ofosu-Anim J, Onwona-Agyeman S, Amoatey CA, Kawada K', 2018, 'Toxins', '10.3390/toxins10120498', 'https://doi.org/10.3390/toxins10120498', 'https://europepmc.org/articles/PMC6316382?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Weeds are rapidly developing resistance to synthetic herbicides, and this can pose a threat to the ecosystem. Exploring allelopathic species as an alternative weed control measure can help minimize the ecological threat posed by herbicide-resistant weeds. In this study, we aimed to evaluate the contribution of some polyphenols to the allelopathy of rosemary (Rosmarinus officinalis L.). The phytotoxic effects of rosemary (leaves, roots, inflorescences, and stems) crude extracts were tested on lettuce (Lactuca sativa L.). Soils incorporated with dried rosemary leaves were also tested on test plants. Reversed-phase high-performance liquid chromatography (HPLC) analysis was used to determine the content of some polyphenols (caffeic, ferulic, gallic, rosmarinic, carnosic, and chlorogenic acids) in rosemary. The specific activity and total activity of crude extracts and individual compounds were evaluated using lettuce. The crude extract of rosemary leaves showed the highest growth inhibitory effect among the rosemary organs tested. Soil amended with rosemary leaf debris reduced the dry matter and seed emergence of lettuce. Carnosic acid was the main compound detected in rosemary leaves and had a high specific activity when tested on lettuce. During the seed germination period, there was observed filter paper coloration among the test plants treated with carnosic acid (250 μg/mL). The high concentration and strong inhibitory effect of carnosic acid could explain the inhibitory activity of the rosemary leaf extract. Hence, we conclude based on the total activity estimation that carnosic acid among the other tested compounds is the major allelochemical in rosemary leaves.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e47a8ba5-f29c-4f43-9d81-b010311a200e', '699c7577-eb88-4579-895f-df444934cf8f', 'Linking Soil Microbial Diversity to Modern Agriculture Practices: A Review', 'Gupta A, Singh UB, Sahu PK, Paul S, Kumar A, Malviya D, Singh S, Kuppusamy P', 2022, 'International journal of environmental research and public health', '10.3390/ijerph19053141', 'https://doi.org/10.3390/ijerph19053141', 'https://europepmc.org/articles/PMC8910389?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Agriculture is a multifarious interface between plants and associated microorganisms. In contemporary agriculture, emphasis is being given to environmentally friendly approaches, particularly in developing countries, to enhance sustainability of the system with the least negative effects on produce quality and quantity. Modern agricultural practices such as extensive tillage, the use of harmful agrochemicals, mono-cropping, etc. have been found to influence soil microbial community structure and soil sustainability. On the other hand, the question of feeding the ever-growing global population while ensuring system sustainability largely remains unanswered. Agriculturally important microorganisms are envisaged to play important roles in various measures to raise a healthy and remunerative crop, including integrated nutrient management, as well as disease and pest management to cut down agrochemicals without compromising the agricultural production. These beneficial microorganisms seem to have every potential to provide an alternative opportunity to overcome the ill effects of various components of traditional agriculture being practiced by and large. Despite an increased awareness of the importance of organically produced food, farmers in developing countries still tend to apply inorganic chemical fertilizers and toxic chemical pesticides beyond the recommended doses. Nutrient uptake enhancement, biocontrol of pests and diseases using microbial inoculants may replace/reduce agrochemicals in agricultural production system. The present review aims to examine and discuss the shift in microbial population structure due to current agricultural practices and focuses on the development of a sustainable agricultural system employing the tremendous untapped potential of the microbial world.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dd114cbc-f315-4cf6-a6be-7f0be7f59ffe', '699c7577-eb88-4579-895f-df444934cf8f', 'Long-term trends in the intensity and relative toxicity of herbicide use', 'Kniss AR', 2017, 'Nature communications', '10.1038/ncomms14865', 'https://doi.org/10.1038/ncomms14865', 'https://europepmc.org/articles/PMC5394230?pdf=render', NULL, NULL, 7, NULL, 'northern_plains', 3, 'cc by', 'Herbicide use is among the most criticized aspects of modern farming, especially as it relates to genetically engineered (GE) crops. Many previous analyses have used flawed metrics to evaluate herbicide intensity and toxicity trends. Here, I show that herbicide use intensity increased over the last 25 years in maize, cotton, rice and wheat. Although GE crops have been previously implicated in increasing herbicide use, herbicide increases were more rapid in non-GE crops. Even as herbicide use increased, chronic toxicity associated with herbicide use decreased in two out of six crops, while acute toxicity decreased in four out of six crops. In the final year for which data were available (2014 or 2015), glyphosate accounted for 26% of maize, 43% of soybean and 45% of cotton herbicide applications. However, due to relatively low chronic toxicity, glyphosate contributed only 0.1, 0.3 and 3.5% of the chronic toxicity hazard in those crops, respectively.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ce5c68b-6839-4c03-b1a9-c8468caa9890', '699c7577-eb88-4579-895f-df444934cf8f', 'Occurrence and Management of PSII-Inhibitor-Resistant Chenopodium album L. in Atlantic Canadian Potato Production', 'Andrew McKenzie-Gopsill, Gavin Graham, Martin Laforest, Sebastian Ibarra, Sheldon Hann, Cameron Wagg', 2020, 'Agronomy', '10.3390/agronomy10091369', 'https://doi.org/10.3390/agronomy10091369', 'https://www.mdpi.com/2073-4395/10/9/1369', NULL, NULL, 12, NULL, 'canada', 3, 'open access (DOAJ)', 'Potato producers in the Atlantic Canadian provinces of New Brunswick (NB) and Prince Edward Island (PE) rely on the photosystem II-inhibiting herbicide metribuzin for weed management. Recently, potato producers in the region have reported unacceptable common lambsquarters control following an application of metribuzin. Tissue and seed samples were collected from escaped common lambsquarters populations from across the potato producing regions of NB and PE and screened for the Ser264Gly mutation in psbA. Overall, 46% of sampled populations possessed the Ser264Gly mutation across the region. Cross-resistance testing to atrazine, metribuzin and linuron confirmed populations with the Ser264Gly were resistant to triazines and triazinones but remained susceptible to linuron. Dose response analysis determined a moderate level of resistance to metribuzin in common lambsquarters which would not be controlled in producers fields. A field experiment was conducted in Fredericton, NB and Harrington, PE, to determine if currently registered and unregistered products and tank-mixes would control PSII-inhibitor-resistant common lambsquarters in potato. All evaluated products, with the exception of S-metolachlor, provided control equivalent to the weed-free check without compromising potato yield or quality. This study demonstrates that PSII-inhibitor-resistant common lambsquarters are found in Atlantic Canadian potato production systems, but can be controlled with currently registered herbicides and rates with alternative modes of action.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e797dc9e-d47a-41c5-8b1f-4dc9df156c63', '699c7577-eb88-4579-895f-df444934cf8f', 'Perspectives of Microbial Inoculation for Sustainable Development and Environmental Management', 'Ahmad M, Pataczek L, Hilger TH, Zahir ZA, Hussain A, Rasche F, Schafleitner R, Solberg SØ', 2018, 'Frontiers in microbiology', '10.3389/fmicb.2018.02992', 'https://doi.org/10.3389/fmicb.2018.02992', 'https://europepmc.org/articles/PMC6289982?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'How to sustainably feed a growing global population is a question still without an answer. Particularly farmers, to increase production, tend to apply more fertilizers and pesticides, a trend especially predominant in developing countries. Another challenge is that industrialization and other human activities produce pollutants, which accumulate in soils or aquatic environments, contaminating them. Not only is human well-being at risk, but also environmental health. Currently, recycling, land-filling, incineration and pyrolysis are being used to reduce the concentration of toxic pollutants from contaminated sites, but too have adverse effects on the environment, producing even more resistant and highly toxic intermediate compounds. Moreover, these methods are expensive, and are difficult to execute for soil, water, and air decontamination. Alternatively, green technologies are currently being developed to degrade toxic pollutants. This review provides an overview of current research on microbial inoculation as a way to either replace or reduce the use of agrochemicals and clean environments heavily affected by pollution. Microorganism-based inoculants that enhance nutrient uptake, promote crop growth, or protect plants from pests and diseases can replace agrochemicals in food production. Several examples of how biofertilizers and biopesticides enhance crop production are discussed. Plant roots can be colonized by a variety of favorable species and genera that promote plant growth. Microbial interventions can also be used to clean contaminated sites from accumulated pesticides, heavy metals, polyaromatic hydrocarbons, and other industrial effluents. The potential of and key processes used by microorganisms for sustainable development and environmental management are discussed in this review, followed by their future prospects.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f684658d-c9da-4469-982a-34b29e52386e', '699c7577-eb88-4579-895f-df444934cf8f', 'Pervasive exposure of wild small mammals to legacy and currently used pesticide mixtures in arable landscapes', 'Fritsch C, Appenzeller B, Burkart L, Coeurdassier M, Scheifler R, Raoul F, Driget V, Powolny T', 2022, 'Scientific reports', '10.1038/s41598-022-19959-y', 'https://doi.org/10.1038/s41598-022-19959-y', 'https://europepmc.org/articles/PMC9508241?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Knowledge gaps regarding the potential role of pesticides in the loss of agricultural biodiversity worldwide and mixture-related issues hamper proper risk assessment of unintentional impacts of pesticides, rendering essential the monitoring of wildlife exposure to these compounds. Free-ranging mammal exposure to legacy (Banned and Restricted: BRPs) and currently used (CUPs) pesticides was investigated, testing the hypotheses of: (1) a background bioaccumulation for BRPs whereas a "hot-spot" pattern for CUPs, (2) different contamination profiles between carnivores and granivores/omnivores, and (3) the role of non-treated areas as refuges towards exposure to CUPs. Apodemus mice (omnivore) and Crocidura shrews (insectivore) were sampled over two French agricultural landscapes (n = 93). The concentrations of 140 parent chemicals and metabolites were screened in hair samples. A total of 112 compounds were detected, showing small mammal exposure to fungicides, herbicides and insecticides with 32 to 65 residues detected per individual (13-26 BRPs and 18-41 CUPs). Detection frequencies exceeded 75% of individuals for 13 BRPs and 25 CUPs. Concentrations above 10 ng/g were quantified for 7 BRPs and 29 CUPs (in 46% and 72% of individuals, respectively), and above 100 ng/g for 10 CUPs (in 22% of individuals). Contamination (number of compounds or concentrations) was overall higher in shrews than rodents and higher in animals captured in hedgerows and cereal crops than in grasslands, but did not differ significantly between conventional and organic farming. A general, ubiquitous contamination by legacy and current pesticides was shown, raising issues about exposure pathways and impacts on ecosystems. We propose a concept referred to as "biowidening", depicting an increase of compound diversity at higher trophic levels. This work suggests that wildlife exposure to pesticide mixtures is a rule rather than an exception, highlighting the need for consideration of the exposome concept and questioning appropriateness of current risk assessment and mitigation processes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('22ada3dd-5e64-458a-abdf-61afdcc9d24e', '699c7577-eb88-4579-895f-df444934cf8f', 'Phenotypic Variation and Genetic Architecture for Photosynthesis and Water Use Efficiency in Soybean (Glycine max L. Merr)', 'Lopez MA, Xavier A, Rainey KM', 2019, 'Frontiers in plant science', '10.3389/fpls.2019.00680', 'https://doi.org/10.3389/fpls.2019.00680', 'https://europepmc.org/articles/PMC6543851?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Photosynthesis (A) and intrinsic water use efficiency (WUE) are physiological traits directly influencing biomass production, conversion efficiency, and grain yield. Though the influence of physiological process on yield is widely known, studies assessing improvement strategies are rare due to laborious phenotyping and specialized equipment needs. This is one of the first studies to assess the genetic architecture underlying A and intrinsic WUE, as well as to evaluate the feasibility of implementing genomic prediction. A panel of 383 soybean recombinant inbred lines were evaluated in a multi-environment yield trial that included measurements of A and intrinsic WUE, using an infrared gas analyzer during R4-R5 growth stages. Genetic variability was found to support the possibility of genetic improvement through breeding. High genetic correlation between grain yield (GY) and A (0.80) was observed, suggesting increases in GY can be achieved through the improvement of A. Genome-wide association analysis revealed quantitative trait loci (QTLs) for these physiological traits. Cross-validation studies indicated high predictive ability (>0.65) for the implementation of genomic prediction as a viable strategy to improve physiological efficiency while reducing field phenotyping. This work provides core knowledge to develop new soybean cultivars with enhanced photosynthesis and water use efficiency through conventional breeding and genomic techniques.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2091d21f-f4b9-4be1-941d-b3572609f29d', '699c7577-eb88-4579-895f-df444934cf8f', 'Precision medicine in the era of artificial intelligence: implications in chronic disease management', 'Subramanian M, Wojtusciszyn A, Favre L, Boughorbel S, Shan J, Letaief KB, Pitteloud N, Chouchane L', 2020, 'Journal of translational medicine', '10.1186/s12967-020-02658-5', 'https://doi.org/10.1186/s12967-020-02658-5', 'https://europepmc.org/articles/PMC7725219?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Aberrant metabolism is the root cause of several serious health issues, creating a huge burden to health and leading to diminished life expectancy. A dysregulated metabolism induces the secretion of several molecules which in turn trigger the inflammatory pathway. Inflammation is the natural reaction of the immune system to a variety of stimuli, such as pathogens, damaged cells, and harmful substances. Metabolically triggered inflammation, also called metaflammation or low-grade chronic inflammation, is the consequence of a synergic interaction between the host and the exposome-a combination of environmental drivers, including diet, lifestyle, pollutants and other factors throughout the life span of an individual. Various levels of chronic inflammation are associated with several lifestyle-related diseases such as diabetes, obesity, metabolic associated fatty liver disease (MAFLD), cancers, cardiovascular disorders (CVDs), autoimmune diseases, and chronic lung diseases. Chronic diseases are a growing concern worldwide, placing a heavy burden on individuals, families, governments, and health-care systems. New strategies are needed to empower communities worldwide to prevent and treat these diseases. Precision medicine provides a model for the next generation of lifestyle modification. This will capitalize on the dynamic interaction between an individual''s biology, lifestyle, behavior, and environment. The aim of precision medicine is to design and improve diagnosis, therapeutics and prognostication through the use of large complex datasets that incorporate individual gene, function, and environmental variations. The implementation of high-performance computing (HPC) and artificial intelligence (AI) can predict risks with greater accuracy based on available multidimensional clinical and biological datasets. AI-powered precision medicine provides clinicians with an opportunity to specifically tailor early interventions to each individual. In this article, we discuss the strengths and limitations of existing and evolving recent, data-driven technologies, such as AI, in preventing, treating and reversing lifestyle-related diseases.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('131eba99-31ab-4766-84df-a67f9c459925', '699c7577-eb88-4579-895f-df444934cf8f', 'Recovery of resources from industrial wastewater employing electrochemical technologies: status, advancements and perspectives', 'Devda V, Chaudhary K, Varjani S, Pathak B, Patel AK, Singhania RR, Taherzadeh MJ, Ngo HH', 2021, 'Bioengineered', '10.1080/21655979.2021.1946631', 'https://doi.org/10.1080/21655979.2021.1946631', 'https://europepmc.org/articles/PMC8806852?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'In the last two decades, water use has increased at twice the rate of population growth. The freshwater resources are getting polluted by contaminants like heavy metals, pesticides, hydrocarbons, organic waste, pathogens, fertilizers, and emerging pollutants. Globally more than 80% of the wastewater is released into the environment without proper treatment. Rapid industrialization has a dramatic effect on developing countries leading to significant losses to economic and health well-being in terms of toxicological impacts on humans and the environment through air, water, and soil pollution. This article provides an overview of physical, chemical, and biological processes to remove wastewater contaminants. A physical and/or chemical technique alone appears ineffective for recovering useful resources from wastewater containing complex components. There is a requirement for more processes or processes combined with membrane and biological processes to enhance operational efficiency and quality. More processes or those that are combined with biological and membrane-based processes are required to enhance operational efficiencies and quality. This paper intends to provide an exhaustive review of electrochemical technologies including microbial electrochemical technologies. It provides comprehensive information for the recovery of metals, nutrients, sulfur, hydrogen, and heat from industrial effluents. This article aims to give detailed information into the advancements in electrochemical processes to energy use, improve restoration performance, and achieve commercialization. It also covers bottlenecks and perspectives of this research area.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f42bf9dd-9575-4dcc-b6cd-8ce640022a52', '699c7577-eb88-4579-895f-df444934cf8f', 'The Plant as Metaorganism and Research on Next-Generation Systemic Pesticides - Prospects and Challenges', 'Vryzas Z', 2016, 'Frontiers in microbiology', '10.3389/fmicb.2016.01968', 'https://doi.org/10.3389/fmicb.2016.01968', 'https://europepmc.org/articles/PMC5161002?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Systemic pesticides (SPs) are usually recommended for soil treatments and as seed coating agents and are taken up from the soil by involving various plant-mediated processes, physiological, and morphological attributes of the root systems. Microscopic insights and next-generation sequencing combined with bioinformatics allow us now to identify new functions and interactions of plant-associated bacteria and perceive plants as meta-organisms. Host symbiotic, rhizo-epiphytic, endophytic microorganisms and their functions on plants have not been studied yet in accordance with uptake, tanslocation and action of pesticides. Root tips exudates mediated by rhizobacteria could modify the uptake of specific pesticides while bacterial ligands and enzymes can affect metabolism and fate of pesticide within plant. Over expression of specific proteins in cell membrane can also modify pesticide influx in roots. Moreover, proteins and other membrane compartments are usually involved in pesticide modes of action and resistance development. In this article it is discussed what is known of the physiological attributes including apoplastic, symplastic, and trans-membrane transport of SPs in accordance with the intercommunication dictated by plant-microbe, cell to cell and intracellular signaling. Prospects and challenges for uptake, translocation, storage, exudation, metabolism, and action of SPs are given through the prism of new insights of plant microbiome. Interactions of soil applied pesticides with physiological processes, plant root exudates and plant microbiome are summarized to scrutinize challenges for the next-generation pesticides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a62f972f-1523-490b-a603-af0df47c97b6', '699c7577-eb88-4579-895f-df444934cf8f', 'Versatile Antagonistic Activities of Soil-Borne Bacillus spp. and Pseudomonas spp. against Phytophthora infestans and Other Potato Pathogens', 'Caulier S, Gillis A, Colau G, Licciardi F, Liépin M, Desoignies N, Modrie P, Legrève A', 2018, 'Frontiers in microbiology', '10.3389/fmicb.2018.00143', 'https://doi.org/10.3389/fmicb.2018.00143', 'https://europepmc.org/articles/PMC5816801?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The world potato is facing major economic losses due to disease pressure and environmental concerns regarding pesticides use. This work aims at addressing these two issues by isolating indigenous bacteria that can be integrated into pest management strategies. More than 2,800 strains of Bacillus-like and Pseudomonas-like were isolated from several soils and substrates associated with potato agro-systems in Belgium. Screenings for antagonistic activities against the potato pathogens Alternaria solani, Fusarium solani (BCCM-MUCL 5492), Pectobacterium carotovorum (ATCC 15713), Phytophthora infestans (CRA-W10022) and Rhizoctonia solani (BCCM-MUCL 51929) were performed, allowing the selection of 52 Bacillus spp. and eight Pseudomonas spp. displaying growth inhibition of at least 50% under in vitro conditions, particularly against P. infestans. All 60 bacterial isolates were identified based on 16S rRNA gene sequencing and further characterized for the production of potential bio-active secondary metabolites. The antagonistic activities displayed by the selected strains indicated that versatile metabolites can be produced by the strains. For instance, the detection of genes involved bacilysin biosynthesis was correlated with the strong antagonism of Bacillus pumilus strains toward P. infestans, whereas the production of both bio-surfactants and siderophores might explain the high antagonistic activities against late blight. Greenhouse assays with potato plants were performed with the most effective strains (seven Bacillus spp. and four Pseudomonas spp.) in order to evaluate their in vivo antagonistic effect against P. infestans. Based on these results, four strains (Bacillus amyloliquefaciens 17A-B3, Bacillus subtilis 30B-B6, Pseudomonas brenneri 43R-P1 and Pseudomonas protegens 44R-P8) were retained for further evaluation of their protection index against P. infestans in a pilot field trial. Interestingly, B. subtilis 30B-B6 was shown to significantly decrease late blight severity throughout the crop season. Overall, this study showed that antagonistic indigenous soil bacteria can offer an alternative to the indiscriminate use of pesticide in potato agro-systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5913a58c-d8cb-4616-8c08-7617b4297a70', '699c7577-eb88-4579-895f-df444934cf8f', 'What makes a molecule a pre- or a post-herbicide - how valuable are physicochemical parameters for their design?', 'Krähmer H, Walter H, Jeschke P, Haaf K, Baur P, Evans R', 2021, 'Pest management science', '10.1002/ps.6535', 'https://doi.org/10.1002/ps.6535', 'https://europepmc.org/articles/PMC8519102?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Pre-emergence herbicides are taken up by seeds before germination and by roots, hypocotyls, cotyledons, coleoptiles or leaves before emergence, whereas post-emergence herbicides are taken up primarily by foliage and stems. Most modern pre-emergence herbicides are lipophilic, but post-emergence herbicides may be lipophilic or hydrophilic. The metabolic conversion of herbicides to inactive or active metabolites after plant uptake is of major importance for some compound classes. Several herbicides are proherbicides as for example some acetyl-coenzyme A carboxylase (ACCase)-inhibitors. The physicochemical characteristics of proherbicides and herbicides are usually unrelated. A major role can be attributed to the site of action at a cellular level. A great number of herbicides such as photosystem II (PS II)-inhibitors, protoporphyrinogen oxidase (PPO)-inhibitors or carotenoid biosynthesis inhibitors require light for activity. Others, such as cellulose-biosynthesis and mitotic inhibitors seem to be primarily active in belowground organs. Several lipophilic barriers against the uptake of xenobiotics exist in aboveground and belowground plant parts. The relevance of these barriers needs, however, further clarification. Uptake and translocation models are valuable tools for the explanation of the potential movement of compounds. Many factors other than uptake and translocation have, however, to be considered for the design of herbicides. For post-emergence herbicides, ultraviolet (UV) light stability, stability in formulations, and mixability with other agrochemicals have to be kept in mind while, in addition to the aforementioned factors soil interaction plays a major role for pre-emergence herbicides. In our opinion, general physicochemical characteristics of pre- or post-emergence herbicides do, unfortunately not exist yet. © 2021 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d3f6fcb9-99e3-4bc4-a18b-7c8302a08ae5', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Adaptability and Stability of Faba Bean (Vicia faba L.) Accessions under Diverse Environments and Herbicide Treatments', 'Abou-Khater L, Maalouf F, Jighly A, Rubiales D, Kumar S, Kumar S', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11030251', 'https://doi.org/10.3390/plants11030251', 'https://europepmc.org/articles/PMC8839948?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'The adaptability and stability of 37 faba bean (Vicia faba L.) accessions with different levels of tolerance to metribuzin or imazethapyr was assessed across 12 season-location-herbicide experiments. Significant Genotype x environment (GE) interaction was found for the days to flowering (DFLR), plant height (PLHT) and grain yield (GY). Performance and stability of the accessions regarding PLHT and GY were assessed using four different stability parameters: cultivar superiority, static stability, Wricke''s eco-valence and Finlay and Wilkinson''s regression model. The stability parameters ranked these genotypes differently suggesting that PLHT and GY stability should be assessed not only on a single or a few stability parameters but on a combination of them. GGE biplot analysis indicated that the environments representing metribuzin treatment at Marchouch 2014-2015 and the non-treated treatment at Terbol 2018-2019 are the ideal environments for evaluating faba bean genotypes. GGE biplots showed herbicide tolerant accession IG12983 with simultaneous average PLHT, GY and stability across the environments. The performance of other tolerant accessions, namely IG13945, IG13906, IG106453, FB2648, and FB1216 was less stable but superior under specific mega environments. Therefore, utilizing these accessions in faba bean breeding programs would help broaden the adaptability to diverse locations-season-herbicide treatments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5a3cdb05-b84e-4044-b505-273e23d09378', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Characterisation of a 4A QTL for Metribuzin Resistance in Wheat by Developing Near-Isogenic Lines', 'Rudra Bhattarai, Hui Liu, Kadambot H. M. Siddique, Guijun Yan', 2021, 'Plants', '10.3390/plants10091856', 'https://doi.org/10.3390/plants10091856', 'https://www.mdpi.com/2223-7747/10/9/1856', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Wheat (Triticum aestivum L.) production is constantly affected by weeds in the farming system. Chemical-based weed management is widely practiced; broad-spectrum herbicides such as metribuzin have been successfully used to control weeds in Australia and elsewhere of the world. Breeding metribuzin-resistant wheat through genetic improvement is needed for effective control of weeds. Quantitative trait loci (QTLs) mapping efforts identified a major QTL on wheat chromosome 4A, explaining up to 20% of the phenotypic variance for metribuzin resistance. The quantitative nature of inheritance of this QTL signifies the importance of near-isogenic lines (NILs), which can convert a quantitative trait into a Mendelian factor for better resolution of the QTL. In the current study, NILs were developed using a heterogeneous inbred family method combined with a fast generation-cycling system in a population of Chuan Mai 25 (resistant) and Ritchie (susceptible). Seven pairs of NILs targeting the 4A QTL for metribuzin resistance were confirmed with a molecular marker and phenotyping. The resistant allele from the resistant parent increased metribuzin resistance by 63–85% (average 69%) compared with the susceptible allele from the susceptible parent. Segregation analysis in the NIL pairs for thousand grain weight (TGW) (g), biomass per plant (kg), tillers per plant, plant height (cm), yield per plant, and powdery mildew visual score (0–9) indicated that these traits were linked with metribuzin resistance. Similarly, TGW was observed to co-segregate with metribuzin resistance in most confirmed NILs, signifying that the two traits are controlled by closely linked genes. The most contrasting NILs can be further characterised by transcriptomic and proteomic analyses to identify the candidate genes responsible for metribuzin resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03ebdf3f-c3bf-48ee-a32a-dd3fb22deb1d', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Comprehensive insights into herbicide resistance mechanisms in weeds: a synergistic integration of transcriptomic and metabolomic analyses', 'Sen MK, Bhattacharya S, Bharati R, Hamouzová K, Soukup J', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1280118', 'https://doi.org/10.3389/fpls.2023.1280118', 'https://europepmc.org/articles/PMC10598704?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Omics techniques, including genomics, transcriptomics, proteomics, and metabolomics have smoothed the researcher''s ability to generate hypotheses and discover various agronomically relevant functions and mechanisms, as well as their implications and associations. With a significant increase in the number of cases with resistance to multiple herbicide modes of action, studies on herbicide resistance are currently one of the predominant areas of research within the field of weed science. High-throughput technologies have already started revolutionizing the current molecular weed biology studies. The evolution of herbicide resistance in weeds (particularly via non-target site resistance mechanism) is a perfect example of a complex, multi-pathway integration-induced response. To date, functional genomics, including transcriptomic and metabolomic studies have been used separately in herbicide resistance research, however there is a substantial lack of integrated approach. Hence, despite the ability of omics technologies to provide significant insights into the molecular functioning of weeds, using a single omics can sometimes be misleading. This mini-review will aim to discuss the current progress of transcriptome-based and metabolome-based approaches in herbicide resistance research, along with their systematic integration.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('65aa2fde-faf9-4128-9d42-3882fc031f64', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Early Identification of Herbicide Stress in Soybean (Glycine max (L.) Merr.) Using Chlorophyll Fluorescence Imaging Technology', 'Li H, Wang P, Weber JF, Gerhards R', 2017, 'Sensors (Basel, Switzerland)', '10.3390/s18010021', 'https://doi.org/10.3390/s18010021', 'https://europepmc.org/articles/PMC5795375?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Herbicides may damage soybean in conventional production systems. Chlorophyll fluorescence imaging technology has been applied to identify herbicide stress in weed species a few days after application. In this study, greenhouse experiments followed by field experiments at five sites were conducted to investigate if the chlorophyll fluorescence imaging is capable of identifying herbicide stress in soybean shortly after application. Measurements were carried out from emergence until the three-to-four-leaf stage of the soybean plants. Results showed that maximal photosystem II (PS II) quantum yield and shoot dry biomass was significantly reduced in soybean by herbicides compared to the untreated control plants. The stress of PS II inhibiting herbicides occurred on the cotyledons of soybean and plants recovered after one week. The stress induced by DOXP synthase-, microtubule assembly-, or cell division-inhibitors was measured from the two-leaf stage until four-leaf stage of soybean. We could demonstrate that the chlorophyll fluorescence imaging technology is capable for detecting herbicide stress in soybean. The system can be applied under both greenhouse and field conditions. This helps farmers to select weed control strategies with less phytotoxicity in soybean and avoid yield losses due to herbicide stress.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5dbefdb7-4d88-48ee-b48d-f08d08a2251f', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Enhancing plant resilience: Nanotech solutions for sustainable agriculture', 'Ahmad Z, Niyazi S, Firdoos A, Wang C, Manzoor MA, Ramakrishnan M, Upadhyay A, Ding Y', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e40735', 'https://doi.org/10.1016/j.heliyon.2024.e40735', 'https://europepmc.org/articles/PMC11665360?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by-nc-nd', 'The global population growth is driving up the demand for agricultural products, while traditional farming methods like those from the Green Revolution are becoming unsustainable due to climate change. To address these challenges and ensure agricultural sustainability, innovative techniques, such as nanotechnology, are essential to meet rising food demands and enhance agricultural sustainability. Nanotechnology, which promotes a more sustainable and resilient agricultural system while enhancing food security, is a key catalyst for the Agri-tech revolution. This review offers a progressive analysis of nanotechnology''s role in managing plant stress. It explores how precision agriculture, particularly via nanosensors, is enhancing our comprehension of plant stress conditions. The integration of nanotechnology with genetic engineering methods, notably CRISPR-Cas technology, is also examined. Furthermore, the review considers the potential toxicological effects of nanoparticles (NPs) on both the environment and plants. Our review has the potential to make a significant impact on human food security by enhancing food production and availability while promoting sustainable agricultural practices. By tackling these challenges, we can contribute to a more reliable and sustainable food supply for the global population.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('43b7bd52-89c1-4303-8258-e0f31a0b8434', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Evaluation of spring herbicide programs during a three-year sugarcane (Saccharum spp. hybrids) cropping cycle', 'Alice A. Wright, Douglas J. Spaunhorst, Eric Petrie', 2025, 'Weed Technology', '10.1017/wet.2025.7', 'https://doi.org/10.1017/wet.2025.7', 'https://www.cambridge.org/core/product/identifier/S0890037X25000077/type/journal_article', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'A limited number of herbicides and sites of action are registered for use on sugarcane in Louisiana. Repeated use of the same sites of action can lead to the evolution of herbicide resistance by weeds. Therefore, it is critically necessary to evaluate additional sites of action to provide growers with options for rotating herbicides to reduce the risk of resistance. Topramezone, indaziflam, and a formulation that includes mesotrione, bicyclopyrone, atrazine, and S-metolachlor, along with more common herbicides (pendimethalin, and metribuzin, clomazone, and diuron), were evaluated in the spring for injury to sugarcane, weed control, sugarcane yield, and sugar yield. Of these treatments, clomazone applied with diuron was the only herbicide combination to consistently injure the crop, with injury estimates ranging from 11% to 36%, which frequently resulted in reduced sugar yield with losses between 2.3% to 24.1% of the nontreated control. In most treatments, an increase in itchgrass counts was observed between harvests, indicating that additional control strategies will be needed in fields infested with this weed. However, topramezone alone and with triclopyr was well tolerated by sugarcane, with injuries ranging from 0% to 11% 2 wk after treatment. Indaziflam and combined application of mesotrione, bicyclopyrone, atrazine, and S-metolachlor injury was at or under 10% 2 wk after treatment. The tolerance of sugarcane for these herbicides suggests that they can be incorporated into weed management strategies in sugarcane production. These herbicides would increase the sites of action available to be applied to sugarcane and help mitigate the risk of herbicide-resistant weeds.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('28ce1427-957f-4455-9f06-6a915ce1d252', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Growth stage of Phalaris minor Retz. and wheat determines weed control and crop tolerance of four post-emergence herbicides', 'Rubia Rasool, Makhan S. Bhullar, Gurjeet S. Gill', 2017, 'Spanish Journal of Agricultural Research', '10.5424/sjar/2017151-9728', 'https://doi.org/10.5424/sjar/2017151-9728', 'http://revistas.inia.es/index.php/sjar/article/view/9728', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Phalaris minor Retz. has evolved multiple herbicide resistance in wheat growing areas in northwestern India. An understanding of the effect of growth stage on herbicide tolerance of wheat and control of P. minor will help in selecting the most appropriate herbicide for different situations. The weed control and crop safety of four commonly used wheat herbicides (sulfosulfuron, pinoxaden, fenoxaprop plus metribuzin and mesosulfuron plus iodosulfuron), each applied at four different wheat growth stages was investigated in field studies for two years. P. minor plants were at 1, 2-3, 3-4 and 7-8 leaf stages when the herbicides were applied at Zadok 12-Z12, Z13, Z21 and Z23 stages of wheat, respectively. Sulfosulfuron application at Z12 and Z13 wheat stages (before first irrigation), provided >80% control of P. minor and produced wheat grain yield (4.5-4.7 t/ha) similar to the weed-free check (4.9 t/ha) in both years. Pinoxaden, fenoxaprop plus metribuzin and mesosulfuron plus iodosulfuron application at Z12 and Z13 wheat stages recorded significantly lower wheat grain yield (3.62-3.95 t/ha) due to poor weed control, crop toxicity or both. All the four herbicides were equally effective on P. minor when applied at Z21 wheat stage. At Z23 wheat stage, pinoxaden gave >90% control of P. minor and the highest wheat grain yield (4.82 t/ha). The results are expected to allow changes in the current recommendation of the timing of post-emergence herbicides for the management of P. minor in wheat.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b90d9367-52f6-4bda-b83e-e1c3a205e5e2', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Health Risk of Potato Farmers Exposed to Overuse of Chemical Pesticides in Iran', 'Sookhtanlou M, Allahyari MS, Surujlal J', 2022, 'Safety and health at work', '10.1016/j.shaw.2021.09.004', 'https://doi.org/10.1016/j.shaw.2021.09.004', 'https://europepmc.org/articles/PMC9349003?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundPotato is the main crop of Ardabil Plain (accounting for one-fifth of potato production in Iran). Its health hazard risk to farmers is rising due to the increasing rate of pesticide use. The present study analyzes potato farmers'' health hazard risk in the use of chemical pesticides.MethodsThe rate of pesticide use by farmers (n = 370) was first compared with the recommended dosage (on pesticide label). Then, a composite index was employed to estimate the health hazard risk of farmers during pesticide use, and the variables accounting for pesticide overuse and nonoveruse were analyzed. Safety behavior was examined in four steps, namely of pesticide purchase and storage, preparation, application, and postapplication.ResultsIt was found that 74.6 percent of potato farmers used pesticides in higher concentrations than the recommended dosage. The higher average rate of pesticide use versus recommendation (label instruction) was related to Chlorpyrifos and Trifluralin, and the highest average health hazard risk among farmers was related to the use of Chlorpyrifos and Metribuzin. Farmers with a higher risk of health hazard displayed much lower safety behavior than the other farmers at all steps of pesticide use.ConclusionThe most important variables discriminating the health hazard risk of farmers'' overuse included health behavior identity, attitude, knowledge and awareness, and cues to action. Therefore, using social media, holding local exhibitions, and engaging local leaders and skilled farmers in the region to improve farmers'' attitudes and health behavior identity toward the dangers of chemical pesticides can play a significant role in motivating farmers'' display of overuse preventive behaviors.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('14b2550b-f369-4931-beb9-6d993774d5e8', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Herbicide and irrigation management options in conventionally-tilled wheat: deciphering water and energy budgeting, and grain and monetary output in north-Indian plains', 'S. K. Verma, Chandra Bhushan, Sudhir Kumar Rajpoot, Richa Chaudhary, Ramawatar Meena, Sanjeev K. Kashyap, Vijay Pratap, P K. Jaysawal', 2025, 'Scientific Reports', '10.1038/s41598-024-81578-6', 'https://doi.org/10.1038/s41598-024-81578-6', 'https://doi.org/10.1038/s41598-024-81578-6', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract In South Asia, declining water tables due to increased irrigation and labor shortages for manual weeding pose significant challenges for wheat production. Additionally, herbicide resistance, often resulting from poor management practices, further complicates weed problems. The objective of this study was to assess the impacts of traditional irrigation regimens (IRs) and herbicide application on wheat crops. The findings showed that when irrigation was applied at 100 mm CPE (IR4), and at 40 mm CPE (IR1), different combinations of herbicide to weed managment were tested. In comparison to the other treatments, application of irrigation at 40 mm cumulative pan evaporation (IR1) along with the Pendimethalin1000 g ha−1 (pre-em) in combination with clodinafop-propargyl 10% + metribuzin 22% + sulfosulfuron 4.2% at a rate of 1125 g ha−1 at 30 DAS (WM1) produced the best results in terms of crop yields, economic returns, relative water content, consumptive use, rate of water use, water use efficiency, water productivity, energy input–output, energy returns, energy productivity, energy intensity, specific energy, energy efficiency, maximum field capacity, available soil water, and soil profile moisture extraction pattern. The only exceptions were Pendimethalin1000g ha−1 (pre-em) combined with carfentrazone ethyl 20% + sulfosulfuron 25%WG), at the rate of 100 g ha−1 at 30 DAS (WM2) and the weed-free treatment (WM5), where the differences were not statistically significant. The yield of wheat grain (14.26 kg ha−1) and straw (14.41 kg ha−1) decreased as the unit dry matter production of weeds increased. The study recommends exploring additional weed control strategies and irrigation management options in future improve wheat yields in conventionally-tilled systems.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9164b95d-5f78-49d0-a71d-6ea9a26b4b64', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Investigation of the Persistence, Toxicological Effects, and Ecological Issues of S-Triazine Herbicides and Their Biodegradation Using Emerging Technologies: A Review', 'Ahmad S, Chandrasekaran M, Ahmad HW', 2023, 'Microorganisms', '10.3390/microorganisms11102558', 'https://doi.org/10.3390/microorganisms11102558', 'https://europepmc.org/articles/PMC10609637?pdf=render', NULL, NULL, 36, NULL, 'other', 1, 'cc by', 'S-triazines are a group of herbicides that are extensively applied to control broadleaf weeds and grasses in agricultural production. They are mainly taken up through plant roots and are transformed by xylem tissues throughout the plant system. They are highly persistent and have a long half-life in the environment. Due to imprudent use, their toxic residues have enormously increased in the last few years and are frequently detected in food commodities, which causes chronic diseases in humans and mammals. However, for the safety of the environment and the diversity of living organisms, the removal of s-triazine herbicides has received widespread attention. In this review, the degradation of s-triazine herbicides and their intermediates by indigenous microbial species, genes, enzymes, plants, and nanoparticles are systematically investigated. The hydrolytic degradation of substituents on the s-triazine ring is catalyzed by enzymes from the amidohydrolase superfamily and yields cyanuric acid as an intermediate. Cyanuric acid is further metabolized into ammonia and carbon dioxide. Microbial-free cells efficiently degrade s-triazine herbicides in laboratory as well as field trials. Additionally, the combinatorial approach of nanomaterials with indigenous microbes has vast potential and considered sustainable for removing toxic residues in the agroecosystem. Due to their smaller size and unique properties, they are equally distributed in sediments, soil, water bodies, and even small crevices. Finally, this paper highlights the implementation of bioinformatics and molecular tools, which provide a myriad of new methods to monitor the biodegradation of s-triazine herbicides and help to identify the diverse number of microbial communities that actively participate in the biodegradation process.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a11b42de-a3a7-433c-ac1e-7eec68fad2c9', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Meta-Analysis of Herbicide Non-Target Effects on Pest Natural Enemies', 'Zilnik G, Bergeron PE, Chuang A, Diepenbrock L, Hanel A, Middleton E, Moretti E, Schmidt-Jeffris R', 2023, 'Insects', '10.3390/insects14100787', 'https://doi.org/10.3390/insects14100787', 'https://europepmc.org/articles/PMC10607068?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'A critical component of integrated pest management is minimizing disruption of biological control by reducing the use of pesticides with significant non-target effects on natural enemies. Insecticide non-target effects testing for natural enemies has become increasingly common, but research examining the non-target effects of herbicides on natural enemies is scarce, and recommendations regarding herbicide selectivity are non-existent. We used meta-analysis to summarize laboratory bioassays testing non-target effects of herbicides on arthropod natural enemies and identify patterns in taxon susceptibility and active ingredient toxicity. Data were extracted from 78 papers representing 801 total observations. Herbicides increased natural enemy mortality and decreased longevity, reproduction, and predation. Mesostigmatan mites and hemipterans were the most sensitive to herbicides, and spiders, neuropterans, and hymenopterans were the least sensitive. Mortality was higher in juvenile predators versus parasitoids but did not differ between adults; parasitoid juveniles are likely better protected within the host. In terms of acute mortality, metribuzin, glufosinate, and oxyfluorfen were the most harmful herbicides. Only nicosulfuron, rimsulfuron, pendimethalin, phenmedipham, atrazine, and urea did not increase natural enemy mortality. The large effect size of glufosinate is particularly concerning, as it is the most likely replacement herbicide for glyphosate in many crops. Many active ingredients remain under-studied. Our analysis indicates that herbicides have a strong potential to disrupt biological control in cropping systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1b96bfe2-b8cb-4df1-b8e1-cd567e15098f', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Nano-Agrochemicals as Substitutes for Pesticides: Prospects and Risks', 'Ali S, Ahmad N, Dar MA, Manan S, Rani A, Alghanem SMS, Khan KA, Sethupathy S', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants13010109', 'https://doi.org/10.3390/plants13010109', 'https://europepmc.org/articles/PMC10780915?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'This review delves into the mesmerizing technology of nano-agrochemicals, specifically pesticides and herbicides, and their potential to aid in the achievement of UN SDG 17, which aims to reduce hunger and poverty globally. The global market for conventional pesticides and herbicides is expected to reach USD 82.9 billion by 2027, growing 2.7% annually, with North America, Europe, and the Asia-Pacific region being the biggest markets. However, the extensive use of chemical pesticides has proven adverse effects on human health as well as the ecosystem. Therefore, the efficacy, mechanisms, and environmental impacts of conventional pesticides require sustainable alternatives for effective pest management. Undoubtedly, nano-agrochemicals have the potential to completely transform agriculture by increasing crop yields with reduced environmental contamination. The present review discusses the effectiveness and environmental impact of nanopesticides as promising strategies for sustainable agriculture. It provides a concise overview of green nano-agrochemical synthesis and agricultural applications, and the efficacy of nano-agrochemicals against pests including insects and weeds. Nano-agrochemical pesticides are investigated due to their unique size and exceptional performance advantages over conventional ones. Here, we have focused on the environmental risks and current state of nano-agrochemicals, emphasizing the need for further investigations. The review also draws the attention of agriculturists and stakeholders to the current trends of nanomaterial use in agriculture especially for reducing plant diseases and pests. A discussion of the pros and cons of nano-agrochemicals is paramount for their application in sustainable agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f6c711fa-9a9b-4557-914d-10725a40cd86', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Nanoparticles as a Promising Strategy to Mitigate Biotic Stress in Agriculture', 'Tortella G, Rubilar O, Pieretti JC, Fincheira P, de Melo Santana B, Fernández-Baldo MA, Benavides-Mendoza A, Seabra AB', 2023, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics12020338', 'https://doi.org/10.3390/antibiotics12020338', 'https://europepmc.org/articles/PMC9951924?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Nanoparticles are recognized due to their particular physical and chemical properties, which are conferred due to their size, in the range of nanometers. Nanoparticles are recognized for their application in medicine, electronics, and the textile industry, among others, but also in agriculture. The application of nanoparticles as nanofertilizers and biostimulants can help improve growth and crop productivity, and it has therefore been mentioned as an essential tool to control the adverse effects of abiotic stress. However, nanoparticles have also been noted for their exceptional antimicrobial properties. Therefore, this work reviews the state of the art of different nanoparticles that have shown the capacity to control biotic stress in plants. In this regard, metal and metal oxide nanoparticles, polymeric nanoparticles, and others, such as silica nanoparticles, have been described. Moreover, uptake and translocation are covered. Finally, future remarks about the studies on nanoparticles and their beneficial role in biotic stress management are made.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06b6326f-f9b4-4724-8397-292dfb2c3c0b', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Performance of Pinoxaden on the Control of Diclofop-Resistant Italian Ryegrass (Lolium perenne L. ssp. multiflorum) in Winter Wheat', 'Taghi Bararpour, Nicholas  E. Korres, Nilda  R. Burgos, Ralph  R. Hale, Te-Ming  P. Tseng', 2018, 'Agriculture', '10.3390/agriculture8070114', 'https://doi.org/10.3390/agriculture8070114', 'http://www.mdpi.com/2077-0472/8/7/114', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Resistance to herbicides in Italian ryegrass (Lolium perenne L. ssp. multiflorum (Lam.) Husnot) is an economically important herbicide-resistance issue in world agriculture. Diclofop-resistant ryegrass is the number one weed problem in Arkansas wheat. Field studies were conducted from 2006 through 2008 at Bredlow corner and Fayetteville, Arkansas, USA to determine the effect of herbicide programs consisting of pinoxaden (Axial) alone or in mixtures with preemergence and postemergence herbicides, along with tillage systems, for managing diclofop-resistant Italian ryegrass. Italian ryegrass control, wheat injury, and grain yield were evaluated. A single treatment with pinoxaden alone resulted in 58% ryegrass control and 1488 kg ha&minus;1 grain yield. The best treatment was metribuzin followed by mesosulfuron, which resulted in 2793 kg grain yield ha&minus;1, a 47% increase compared to pinoxaden alone. In Fayetteville (2006&ndash;2007 and 2007&ndash;2008), the best treatment was two applications of metribuzin, which yielded about 3700 kg grain ha&minus;1. A single application of pinoxaden resulted in 40% loss of grain yield compared to a single application of flufenacet + metribuzin and almost 50% yield loss compared to sequential application of metribuzin. Yield loss was attributed due to insufficient control of Italian ryegrass. The effect of tillage on Italian ryegrass was inconsistent between years and treatments. In the first year, for example, tillage &times; herbicide treatments did not differ. In the second and third year, control of Italian ryegrass was better in no-till than in conventional till in both locations. In conclusion, pinoxaden alone could not control diclofop-resistant Italian ryegrass sufficiently. Other herbicide modes of action need to be added to the management program of diclofop-resistant Italian ryegrass, especially one with residual activity such as metribuzin.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2e8436da-52fe-457d-9d70-c2b72abfdc3e', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'QTL Mapping Using a High-Density Genetic Map to Identify Candidate Genes Associated With Metribuzin Tolerance in Hexaploid Wheat (Triticum aestivum L.)', 'Xu L, Liu H, Kilian A, Bhoite R, Liu G, Si P, Wang J, Zhou W', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.573439', 'https://doi.org/10.3389/fpls.2020.573439', 'https://europepmc.org/articles/PMC7527527?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Tolerance to metribuzin, a broad-spectrum herbicide, is an important trait for weed control in wheat breeding. However, the genetics of metribuzin tolerance in relation to the underlying quantitative trait loci (QTL) and genes is limited. This study developed F8 recombinant inbred lines (RILs) from a cross between a highly resistant genotype (Chuan Mai 25) and highly susceptible genotype (Ritchie), which were used for QTL mapping of metribuzin tolerance. Genotyping was done using a diversity arrays technology sequencing (DArTseq) platform, and phenotyping was done in controlled environments. Herbicide tolerance was measured using three traits, visual score (VS), reduction of chlorophyll content (RCC), and mean value of chlorophyll content for metribuzin-treated plants (MCC). A high-density genetic linkage map was constructed using 2,129 DArTseq markers. Inclusive composite interval mapping (ICIM) identified seven QTL, one each on chromosomes 2A, 2D, 3A, 3B, 4A, 5A, and 6A. Three major QTL-Qrcc.uwa.2AS, Qrcc.uwa.5AL, and Qrcc.uwa.6AL-explained 11.39%, 11.06%, and 11.45% of the phenotypic variation, respectively. The 5A QTL was further validated using kompetitive allele-specific PCR (KASP) assays in an F3 validation population developed from Chuan Mai 25 × Dagger. Blasting the single-nucleotide polymorphisms (SNPs) flanking the QTL in the wheat reference genome RefV1.0 revealed SNP markers within or very close to annotated genes which could be candidate genes responsible for metribuzin tolerance. Most of the candidate genes were related to metabolic detoxification, especially those of P450 pathway and xenobiotic transmembrane transporter activity, which are reportedly key molecules responsible for herbicide tolerance. This study is the first to use specially developed populations to conduct QTL mapping on the metribuzin tolerance trait. The three major QTL and candidate genes identified in this study could facilitate marker-assisted metribuzin breeding in wheat. The QTL could be fine-mapped to locate the genes responsible for metribuzin tolerance, which could be introgressed into elite wheat cultivars.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a9893e5c-eb0e-450a-8e5c-295c1b6654a5', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Recent Biotechnological Applications of Polyhydroxyalkanoates (PHA) in the Biomedical Sector-A Review', 'Diniz MSDF, Mourão MM, Xavier LP, Santos AV', 2023, 'Polymers', '10.3390/polym15224405', 'https://doi.org/10.3390/polym15224405', 'https://europepmc.org/articles/PMC10675258?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Petroleum-derived plastics are materials of great importance for the contemporary lifestyle, and are widely used commercially because they are low cost, resistant, malleable, and weightless, in addition to their hydrophobic character. However, some factors that confer the qualities of these materials also cause problems, mainly environmental, associated with their use. The COVID-19 pandemic aggravated these impacts due to the high demand for personal protective equipment and the packaging sector. In this scenario, bioplastics are environmentally positive alternatives to these plastics due to their applicability in several areas ranging from packaging, to biomedicine, to agriculture. Polyhydroxyalkanoates (PHAs) are biodegradable biopolymers usually produced by microorganisms as an energy reserve. Their structural variability provides a wide range of applications, making them a viable option to replace polluting materials. PHAs can be applied in various biotechnology sectors, such as producing drug carriers and scaffolds for tissue engineering. This review aimed to survey works published in the last five years on the study and biotechnological application of PHAs in the biomedical sector, exploring the versatility and advantages of their use and helping to understand how to enhance their application.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7a21d070-c572-4860-b879-c2d0df5b138a', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Risk Assessment of Pesticide Residues by GC-MSMS and UPLC-MSMS in Edible Vegetables', 'Selim MT, Almutari MM, Shehab HI, El-Saeid MH', 2023, 'Molecules (Basel, Switzerland)', '10.3390/molecules28031343', 'https://doi.org/10.3390/molecules28031343', 'https://europepmc.org/articles/PMC9921447?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'In recent years, there has been a significant increase related to pesticide residues in foods, which may increase the risks to the consumer of these foods with the different quality and concentrations of pesticide residues. Pesticides are used for controlling pests that reduce yields. On the other hand, it has become a major public health concern due to its toxic properties. Thus, the objective of the current study employed the application of Quick Easy Cheap Effective Rugged Safe (QuEChERS) method, in combination with gas and liquid chromatography-tandem mass spectrometric detection (GCMSMS, LCMSMS) in order to determine 137 pesticide residues (63 insecticides, 41 acaricides, 40 herbicide, 55 fungicide, nematicide, growth regulator, Chitin synthesis inhibitors, and Juvenile hormone mimics), in 801 vegetables such as 139 tomatoes, 185 peppers, 217 squash, 94 eggplants, and 166 cucumbers from different locations in Hail and Riyadh cities. The results showed that the majority of pesticide residues were detected for each of the following pesticides: acetaimpride, metalaxyl, imidaclopride, bifenthrin, pyridaben, difenoconazole, and azoxystrobien, which were repeated in the samples studied 39, 21, 11, 10, 8, 7, and 5, respectively. In addition, results observed that the tomato was the most contaminated with pesticide residues; it was contaminated with 19 compounds and was followed by pepper, cucumber, and squash, and the last commodity in the contaminated ranking was eggplant. The highest calculated estimated daily intakes (EDIs) were recorded for tomatoes which were estimated between 0.013 to 0.516 mg/kg of body weight per day (bw/day) while the lowest EDIs value was between 0.000002 to 0.0005 mg/kg of bw/day for cucumber. Results indicated that the EDIs values were lower than the acceptable daily intake (ADI) values. Results observed that the most of pesticide residues exposure in food consumption in Saudi Arabia were lower than ADIs. In addition, the highest value for health risk index (HRI) was recorded with Ethion residue in tomato, but in sweet pepper, the highest value for HRI was 127.5 in the form of fipronil residue. On the other hand, results found that the highest values of HRI were 1.54, 1.61, and 0.047 for difenoconazole, bifenthrin, and pyridaben residues in squash, eggplant, and cucumber.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('333c1f43-7522-445f-81c6-813aa45d162e', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Scientific and Regulatory Perspectives on Chemical Risk Assessment of Pesticides in the European Union', 'Buonsenso F', 2025, 'Journal of xenobiotics', '10.3390/jox15050173', 'https://doi.org/10.3390/jox15050173', 'https://europepmc.org/articles/PMC12565433?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'People are exposed to pesticides daily through food, drinking water, and the environment, both in urban and rural settings. These chemicals, while offering economic and agricultural benefits through pest control and increased productivity, may pose a growing risk to human health and ecosystem biodiversity. While the European regulatory framework offers a robust foundation for risk assessment, significant limitations persist, especially in addressing cumulative exposure, low-dose effects, and chemical mixtures. This review focuses on selected scientific and regulatory challenges by reviewing recent European Food Safety Authority (EFSA) conclusions, Organization for Economic Co-operation and Development (OECD) test guidelines updates, and current European legislative approaches. Particular attention is given to the regulation of endocrine-disrupting and reprotoxic substances, highlighting progress and remaining gaps in implementation. A brief mention will also be made of immuno-toxic substances, for which no specific hazard class has yet been established. Building on official reports and peer-reviewed literature, this review provides a structured evaluation of the scientific and regulatory landscape, including underexplored issues like the transition to animal-free toxicology and integration of biomonitoring with health data. The goal is to propose realistic, evidence-based improvements to current frameworks using integrated, interdisciplinary approaches that connect toxicology, policy, and implementation science. A shift to a holistic, systems-based, and precautionary paradigm is vital to address emerging challenges and ensure strong protection of health and environment, as well as supporting the needs of the agricultural sector.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a3459a1a-5382-45c8-ad1b-73dc90125492', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'SERS Sensors with Bio-Derived Substrates Under the Way to Agricultural Monitoring of Pesticide Residues', 'Serebrennikova KV, Komova NS, Zherdev AV, Dzantiev BB', 2024, 'Biosensors', '10.3390/bios14120573', 'https://doi.org/10.3390/bios14120573', 'https://europepmc.org/articles/PMC11674820?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Uncontrolled use of pesticides in agriculture leads to negative consequences for the environment, as well as for human and animal health. Therefore, timely detection of pesticides will allow application of measures to eliminate the excess of maximum residue limits and reduce possible negative consequences in advance. Common methods of pesticide analysis suffer from high costs, and are time consuming, and labor intensive. Currently, more attention is being paid to the development of surface-enhanced Raman scattering (SERS) sensors as a non-destructive and highly sensitive tool for detecting various chemicals in agricultural applications. This review focuses on the current developments of biocompatible SERS substrates based on natural materials with unique micro/nanostructures, flexible SERS substrates based on biopolymers, as well as functionalized SERS substrates, which are close to the current needs and requirements of agricultural product quality control and environmental safety assessment. The impact of herbicides on the process of photosynthesis is considered and the prospects for the application of Raman spectroscopy and SERS for the detection of herbicides are discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c46dbab9-5b11-4b65-ad0e-ae5ebd973aaf', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Soil Actinobacteria Exhibit Metabolic Capabilities for Degrading the Toxic and Persistent Herbicide Metribuzin', 'Rebai H, Sholkamy EN, Abdelhamid MAA, Prakasam Thanka P, Aly Hassan A, Pack SP, Ki MR, Boudemagh A', 2024, 'Toxics', '10.3390/toxics12100709', 'https://doi.org/10.3390/toxics12100709', 'https://europepmc.org/articles/PMC11511370?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Metribuzin, a widely used triazine herbicide, persists in agricultural soils and poses significant environmental pollution threats globally. The aim of this study was to investigate the biodegradation of metribuzin by actinobacterial strains in vitro at different environmental conditions. From an initial screen of 12 actinobacterial strains, four bacteria exhibited robust growth in the presence of the metribuzin as the sole carbon source at 50 mg/L concentration. The optimization of metribuzin biodegradation under different conditions (pH, temperature and inoculum size) using a spectrophotometric method revealed that maximum degradation of metribuzin occurred at a pH of 7.2, a temperature 30 °C, and at an inoculum volume of 4%. Subsequent GC-MS validation confirmed the remarkable biodegradation capabilities of the actinobacterial isolates, where the strain C1 showed the highest rate of metribuzin degradation of 83.12%. Detailed phylogenetic identified the active strains as Streptomyces toxytricini (CH), Streptomyces stelliscabiei (B2), and two Streptomyces heliomycini (C1, C3). Structural analysis by ATR-FTIR spectroscopy confirmed the extensive biotransformation of the herbicide molecule. Our findings highlight the immense untapped potential of soil actinobacteria, particularly the Streptomyces heliomycini C1 strain, as versatile bioremediation agents for removing persistent agrochemical pollutants.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b5feaab-8271-471b-84b0-ff6f956b7f91', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Soybean plant-back following an amicarbazone and metribuzin application for corn', 'Michael Dodde, Jason K. Norsworthy, Tom Barber, Ryan Henry', 2026, 'Weed Technology', '10.1017/wet.2026.10089', 'https://doi.org/10.1017/wet.2026.10089', 'https://www.cambridge.org/core/product/identifier/S0890037X2610089X/type/journal_article', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'The U.S. Environmental Protection Agency has proposed increased restrictions and lower application rates for atrazine. Corn growers need to have options for weed control, and increased scrutiny of atrazine may limit effective herbicides that inhibit the photosystem II within weeds. One alternative weed control option is the premixture of amicarbazone and metribuzin. The atrazine label prohibits planting soybean until the following year, limiting producers to replanting corn or grain sorghum after a failed stand. Amicarbazone allows a 4-mo soybean rotation interval, potentially enabling planting of the crop the same season as failed corn. Therefore, research was conducted in 2023 and 2024 in Fayetteville, Arkansas, to evaluate soybean tolerance to an amicarbazone and metribuzin premixture after a simulated failed corn stand. Amicarbazone was applied at 245, 490, and 735 g ai ha−1 alone and in combination with metribuzin at 140, 280, and 420 g ai ha−1. Soybean was planted following at least 1.3 cm of rain (19 to 20 d after application). The label allows amicarbazone and metribuzin to be applied to corn at 336 and 190 g ha−1, respectively, on silt loam soil with organic matter of 1.5% to 2%. The combination of amicarbazone and metribuzin at 735 and 420 g ha−1, respectively, more than twice the labeled rate for corn, induced 61% to 91% soybean injury 14 d after emergence (DAE). When amicarbazone and metribuzin rates were reduced to 245 and 140 g ha−1, respectively, the injury was 4% in both years at 14 DAE. Yield reductions were observed only after treatments with amicarbazone at 735 g ha−1 applied alone or in combination with metribuzin at 420 g ha−1. Overall, crop response and yield reductions should be expected with an amicarbazone and metribuzin premixture at the highest rates used in this study. However, the label for the premixture will not allow these rates to be applied.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a2019b8-4474-453a-a55a-c64b88e5affd', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Stability Phenomena Associated with the Development of Polymer-Based Nanopesticides', 'Del Prado-Audelo ML, Bernal-Chávez SA, Gutiérrez-Ruíz SC, Hernández-Parra H, Kerdan IG, Reyna-González JM, Sharifi-Rad J, Leyva-Gómez G', 2022, 'Oxidative medicine and cellular longevity', '10.1155/2022/5766199', 'https://doi.org/10.1155/2022/5766199', 'https://europepmc.org/articles/PMC9060970?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Pesticides have been used in agricultural activity for decades because they represent the first defense against pathogens, harmful insects, and parasitic weeds. Conventional pesticides are commonly employed at high dosages to prevent their loss and degradation, guaranteeing effectiveness; however, this results in a large waste of resources and significant environmental pollution. In this regard, the search for biocompatible, biodegradable, and responsive materials has received greater attention in the last years to achieve the obtention of an efficient and green pesticide formulation. Nanotechnology is a useful tool to design and develop "nanopesticides" that limit pest degradation and ensure a controlled release using a lower concentration than the conventional methods. Besides different types of nanoparticles, polymeric nanocarriers represent the most promising group of nanomaterials to improve the agrochemicals'' sustainability due to polymers'' intrinsic properties. Polymeric nanoparticles are biocompatible, biodegradable, and suitable for chemical surface modification, making them attractive for pesticide delivery. This review summarizes the current use of synthetic and natural polymer-based nanopesticides, discussing their characteristics and their most common design shapes. Furthermore, we approached the instability phenomena in polymer-based nanopesticides and strategies to avoid it. Finally, we discussed the environmental risks and future challenges of polymeric nanopesticides to present a comprehensive analysis of this type of nanosystem.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0ffbda8-27a7-41f3-aaea-63245a7de433', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Syngenta''s contribution to herbicide resistance research and management', 'Kaundun SS', 2021, 'Pest management science', '10.1002/ps.6072', 'https://doi.org/10.1002/ps.6072', 'https://europepmc.org/articles/PMC7984027?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'The evolution of weed resistance to herbicides is an ever-increasing problem that affects crop yield and food production. In Syngenta, we believe that this difficult and complex issue can be most efficiently addressed through a deep understanding of the evolutionary dynamics and mechanism of resistance. A profound knowledge of resistance is key to developing the next generation of resistance-breaking compounds with existing or novel herbicide sites of action. We use a multidisciplinary laboratory-based, glasshouse and field biology approach to study herbicide resistance and provide strong science-based solutions to delay the onset and manage resistance. We have developed and implemented simple early-season resistance detection methods to allow farmers make an informed decision for effective weed control. We have built mechanistic, individual-based computer models to design profitable, long-term sustainable weed management programs. Our zero tolerance approaches employ herbicides with different sites of action, applied in mixtures and sequences, to minimise the risk of resistance evolution. Weeds are targeted at the right growth stage with optimal herbicide formulation and spray technology for maximising weed control and depleting the seed bank. We are promoting the use of competitive crop varieties and other nonchemical methods for an integrated weed management strategy. We have a global web of external collaborations for studying and managing herbicide resistance. We are committed to farmers'' education and training on herbicide resistance, and regularly share our methods and findings via conferences and peer-reviewed scientific publications for the benefit of the wider weed science community and field practitioners. © 2020 Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d94b9dae-c05e-43ac-b66c-53a2a0a34172', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Triazine Herbicide and NPK Fertilizer Exposure: Accumulation of Heavy Metals and Rare Earth Elements, Effects on Cuticle Melanization, and Immunocompetence in the Model Species Tenebrio molitor', 'Naccarato A, Vommaro ML, Amico D, Sprovieri F, Pirrone N, Tagarelli A, Giglio A', 2023, 'Toxics', '10.3390/toxics11060499', 'https://doi.org/10.3390/toxics11060499', 'https://europepmc.org/articles/PMC10300948?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'The increasing use of agrochemicals, including fertilizers and herbicides, has led to worrying metal contamination of soils and waters and raises serious questions about the effects of their transfer to different levels of the trophic web. Accumulation and biomagnification of essential (K, Na, Mg, Zn, Ca), nonessential (Sr, Hg, Rb, Ba, Se, Cd, Cr, Pb, As), and rare earth elements (REEs) were investigated in newly emerged adults of Tenebrio molitor exposed to field-admitted concentrations of a metribuzin-based herbicide and an NPK blend fertilizer. Chemical analyses were performed using inductively coupled plasma tandem mass spectrometry (ICP-MS/MS) supported by unsupervised pattern recognition techniques. Physiological parameters such as cuticle melanization, cellular (circulating hemocytes), and humoral (phenoloxidase enzyme activity) immune responses and mass loss were tested as exposure markers in both sexes. The results showed that NPK fertilizer application is the main cause of REE accumulation in beetles over time, besides toxic elements (Sr, Hg, Cr, Rb, Ba, Ni, Al, V, U) also present in the herbicide-treated beetles. The biomagnification of Cu and Zn suggested a high potential for food web transfer in agroecosystems. Gender differences in element concentrations suggested that males and females differ in element uptake and excretion. Differences in phenotypic traits show that exposure affects metabolic pathways involving sequestration and detoxification during the transition phase from immature-to-mature beetles, triggering a redistribution of resources between sexual maturation and immune responses. Our findings highlight the importance of setting limits for metals and REEs in herbicides and fertilizers to avoid adverse effects on species that provide ecosystem services and contribute to soil health in agroecosystems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d1aceee8-863e-47f1-a0c9-31de3fbc25be', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'UV RESISTANCE LOCUS 8 signalling enhances photosynthetic resilience to herbicide-induced damage in Arabidopsis thaliana', 'Groves CL, Franklin KA', 2025, 'The New phytologist', '10.1111/nph.70303', 'https://doi.org/10.1111/nph.70303', 'https://europepmc.org/articles/PMC12267928?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Perception of low irradiance ultraviolet B (UV-B) light (280-315 nm) by the UV RESISTANCE LOCUS 8 (UVR8) photoreceptor initiates signalling pathways that enhance plant defences to UV-B damage, mitigating the effects of higher photon irradiances. We therefore questioned whether UVR8 signalling could also prime plants against herbicide-induced damage, promoting postspray survival. We assessed the effects of a 2 d, low irradiance UV-B pretreatment on the photosynthetic resilience and survival of Arabidopsis thaliana plants treated with herbicides promoting photosynthetic disruption and oxidative stress. UV-B acclimation increased leaf carotenoid production, antioxidant activity and nonphotochemical quenching (NPQ) and delayed herbicide-induced reductions in electron transport rate (ETR), facilitating postspray regrowth and enhancing plant survival. In the absence of UV-B, this protection declined within 4 d, suggesting that it is unlikely to result from structural modifications. UV-B-mediated enhancement of photosynthetic resilience was abolished in the uvr8-6 mutant and increased in the UV-B hyper-responsive repressor of UV-B photomorphogenesis1/2 (rup1rup2) mutant, highlighting the involvement of UVR8 signalling. UV-B filtering during daylight acclimation also increased herbicide efficacy in Chenopodium, suggesting similar responses in agricultural weeds. UV-B-induced photoprotection enhances the resilience of plant photosystems to herbicide damage, providing a key target for increasing product efficacy and reducing usage.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('223c6ee8-b0d6-4fa1-a0d7-b660b43c15c8', '8c38f59e-aa15-41fb-89f5-e58af620a424', 'Weed control in dormant alfalfa (Medicago sativa L.) with active ingredients’ metribuzin, imazetapyr and pronamide', 'Zvonko Pacanoski, Štefan Týr, Tomáš Vereš', 2017, 'Journal of Central European Agriculture', '10.5513/JCEA01/18.1.1865', 'https://doi.org/10.5513/JCEA01/18.1.1865', 'http://jcea.agr.hr/articles/773942_Weed_control_in_dormant_alfalfa_(Medicago_sativa_L_)_with_active_ingredients_metribuzin_imazetapyr_and_pronamide_en.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Field trials were conducted during 2008 – 2010 to evaluate weed control in dormant alfalfa (Medicago sativa L.) with metribuzin, imazetapyr and pronamide. The weed population in all experimental years was consisted mainly of annual winter and spring grass and broadleaf weeds, and some perennial weeds. The number of weed species and weed density increased with the years of alfalfa growing, from second to the fourth year. Weed density in the untreated control plots was 201.0, 217.2 and 240.5 plants per m2 in 2008, 2009 and 2010, respectively. The most dominant weeds were Anthemis cotula, Capsell bursa-pastoris and Taraxacum officinale in 2008, Alopecurus myosuroides and Poa pratensis in 2009 and Millium vernale and Arabidopsis thaliana in 2010. Efficacy of herbicides in control of weeds was ranged of 91.8% (pronamide) to 98.4% (metribuzin 1.0 kg*ha-1) in 2008, 93.1% (imazetapyr) to 97.3% (metribuzin 1.0 kg*ha-1) in 2009 and 92.1% (imazetapyr) to 97.3% (metribuzin 1.0 kg*ha-1) in 2010, respectively. Efficacy of herbicides in control of prevailing weeds during the 3 years field trial period was ranged of 48.5% to 100.0%. No visual alfalfa injured was determined by any rates during the experimental period, and consequently, none of the applied herbicides reduced first-harvest alfalfa yields. Alfalfa yield was markedly affected by herbicide efficacy in all experimental years, particularly in the second year, where yields of herbicide treatments were similar to that of the weed free control.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('83768e60-6d7d-47b7-8fa5-8d35e6bfdc20', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'An Evaluation of Targeted Spraying for Reducing Herbicide Use in Highbush Blueberry', 'Lynn M. Sosnoskie, Roger B. Batts, Thierry Besançon', 2025, 'HortTechnology', 'https://doi.org/10.21273/HORTTECH05555-24', 'https://doi.org/https://doi.org/10.21273/HORTTECH05555-24', 'https://journals.ashs.org/horttech/view/journals/horttech/35/2/article-p214.xml', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Herbicides are the most common method for weed control in berry crops, although the evolution of herbicide resistance, worker and crop safety concerns, and regulatory challenges associated with the prevention of off-target movement are driving interest in alternative weed management technologies. Optically guided, targeted spray systems show promise for reducing herbicide use, minimizing crop damage, and expanding weed control options in perennial crops. In 2021 and 2022, field trials were conducted in New Jersey to evaluate the impact of conventional banded and targeted (WEED-IT™ system) herbicide applications on weed control and crop outcomes. Control of common groundsel, horseweed, and common purslane was influenced by herbicide type and application strategy but not by their interaction. Fluroxypyr applied at 280 and 560 g a.e./ha provided similar or better control of common groundsel and common purslane (>90%) compared with the 2,4-D choline and glufosinate (71% to 92%) standards. Similarly, horseweed control with florpyrauxifen-benzyl applied at 30 and 60 g a.e./ha (80% to 91%) matched or exceeded the suppression provided by 2,4-D and glufosinate (62% to 87%). Herbicide applications using the WEED-IT™ system reduced herbicide use by approximately 50% but provided less weed control than the traditional banded method; results likely reflect the effects of crop size and density on spray coverage. Crop injury was primarily observed on new canes, with targeted applications causing slightly more damage than the banded treatments across all observation timings. Stunting of new blueberry canes exceeded 8% at 1 week after application and decreased to less than 1% by 4 weeks after application, compared with a maximum of 3% stunting from banded applications. The greater levels of observed crop damage probably result from the system’s inability to distinguish between crops and weeds. Despite the potential of targeted spraying technologies to reduce herbicide use, their effectiveness and safety in perennial crops warrant further research, particularly regarding integration into comprehensive weed-management programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('90448b70-80f3-47d7-af69-8a6ad7c723b9', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Bioremediation of Agricultural Soils Polluted with Pesticides: A Review', 'Raffa CM, Chiampo F', 2021, 'Bioengineering (Basel, Switzerland)', '10.3390/bioengineering8070092', 'https://doi.org/10.3390/bioengineering8070092', 'https://europepmc.org/articles/PMC8301097?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Pesticides are chemical compounds used to eliminate pests; among them, herbicides are compounds particularly toxic to weeds, and this property is exploited to protect the crops from unwanted plants. Pesticides are used to protect and maximize the yield and quality of crops. The excessive use of these chemicals and their persistence in the environment have generated serious problems, namely pollution of soil, water, and, to a lower extent, air, causing harmful effects to the ecosystem and along the food chain. About soil pollution, the residual concentration of pesticides is often over the limits allowed by the regulations. Where this occurs, the challenge is to reduce the amount of these chemicals and obtain agricultural soils suitable for growing ecofriendly crops. The microbial metabolism of indigenous microorganisms can be exploited for degradation since bioremediation is an ecofriendly, cost-effective, rather efficient method compared to the physical and chemical ones. Several biodegradation techniques are available, based on bacterial, fungal, or enzymatic degradation. The removal efficiencies of these processes depend on the type of pollutant and the chemical and physical conditions of the soil. The regulation on the use of pesticides is strictly connected to their environmental impacts. Nowadays, every country can adopt regulations to restrict the consumption of pesticides, prohibit the most harmful ones, and define the admissible concentrations in the soil. However, this variability implies that each country has a different perception of the toxicology of these compounds, inducing different market values of the grown crops. This review aims to give a picture of the bioremediation of soils polluted with commercial pesticides, considering the features that characterize the main and most used ones, namely their classification and their toxicity, together with some elements of legislation into force around the world.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05efd771-8e5f-40f6-8417-a655af02b7fa', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Controlling weeds with fungi, bacteria and viruses: a review', 'Harding DP, Raizada MN', 2015, 'Frontiers in plant science', '10.3389/fpls.2015.00659', 'https://doi.org/10.3389/fpls.2015.00659', 'https://europepmc.org/articles/PMC4551831?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by', 'Weeds are a nuisance in a variety of land uses. The increasing prevalence of both herbicide resistant weeds and bans on cosmetic pesticide use has created a strong impetus to develop novel strategies for controlling weeds. The application of bacteria, fungi and viruses to achieving this goal has received increasingly great attention over the last three decades. Proposed benefits to this strategy include reduced environmental impact, increased target specificity, reduced development costs compared to conventional herbicides and the identification of novel herbicidal mechanisms. This review focuses on examples from North America. Among fungi, the prominent genera to receive attention as bioherbicide candidates include Colletotrichum, Phoma, and Sclerotinia. Among bacteria, Xanthomonas and Pseudomonas share this distinction. The available reports on the application of viruses to controlling weeds are also reviewed. Focus is given to the phytotoxic mechanisms associated with bioherbicide candidates. Achieving consistent suppression of weeds in field conditions is a common challenge to this control strategy, as the efficacy of a bioherbicide candidate is generally more sensitive to environmental variation than a conventional herbicide. Common themes and lessons emerging from the available literature in regard to this challenge are presented. Additionally, future directions for this crop protection strategy are suggested.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('32074f0b-92e1-49f7-9d7f-d5d230be7988', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Differences in Germination, Growth, and Fecundity Characteristics of Dicamba-Fluroxypyr-Resistant and Susceptible Kochia scoparia', 'Kumar V, Jha P', 2016, 'PloS one', '10.1371/journal.pone.0161533', 'https://doi.org/10.1371/journal.pone.0161533', 'https://europepmc.org/articles/PMC4990274?pdf=render', NULL, NULL, 16, NULL, 'canada', 3, 'cc by', 'The widespread occurrence of herbicide-resistant (HR) Kochia scoparia is an increasing concern for growers in the US Great Plains and Canada. K. scoparia populations resistant to dicamba have been reported in six US states. Populations cross-resistant to dicamba and fluroxypyr have been reported from wheat fields in Montana, USA. It is unclear whether resistance to the auxinic herbicides (dicamba and/or fluroxypyr), can alter the fitness traits of K. scoparia. The objectives of this research were to compare the germination dynamics in response to thermal environment, vegetative growth and fecundity characteristics, and the relative competitive ability of dicamba-fluroxypyr-susceptible (S) vs.-resistant (R) K. scoparia selected from within a single segregating population (collected from wheat-fallow field in MT). S and R selected lines were developed after three generations of recurrent group selection. Compared to the S selected line, the R selected line had lower cumulative germination at all constant temperatures except 25°C, and at all alternating temperatures except 30/35°C. Also, the R selected line had delayed germination relative to the S selected line. The R had lower plant height, plant width, primary branches, total leaf area, stem diameter, and shoot dry weight compared with the S plants in the absence of competition. The reduction in seed production per plant resulted in a 39% fitness cost. The 1000-seed weight of R (1.6 g) was also less than that of S (2.6 g). When grown in an intraspecific competition at different mixture proportions, replacement series indices for the growth parameters further indicated that the R was less competitive than the S. Evident from this research, the dicamba-fluroxypyr-resistant R selected line is less likely to persist in a field population in the absence of the auxinic herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2ea8312-e094-42e0-b320-e583cdc6edda', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Direct Comparison of Herbicidal or Biological Treatment on Myriophyllum spicatum Control and Biochemistry', 'Michelle D. Marko, Jason C. White', 2018, 'Frontiers in Plant Science', '10.3389/fpls.2018.01814', 'https://doi.org/10.3389/fpls.2018.01814', 'https://www.frontiersin.org/article/10.3389/fpls.2018.01814/full', NULL, NULL, 10, NULL, 'other', 1, 'open access (DOAJ)', 'Myriophyllum spicatum or Eurasian watermilfoil (hereafter, milfoil) is among the most problematic invasive aquatic plant species throughout much of North America. M. spicatum infestations can result in reduced diversity and abundance of native plant populations. Control of the invader is essential to promoting healthy ecosystems. Several treatment alternatives are available for milfoil control, although cost and efficacy vary significantly, with some treatments resulting in more harm to the native population than no treatment at all. A series of field-based microcosms containing actively growing milfoil were constructed in order to directly compare the impact of two herbicides (2,4-dichlorophenoxyacetic acid and fluridone) and the milfoil weevil (Euhrychiopsis lecontei) on weed control and plant biochemistry. Herbicide concentrations in water, plants, and sediments were monitored, as were weevil population dynamics and resulting invertebrate damage to milfoil stems. The impact of the different treatments on levels of polyphenols, carbohydrates, ash, and overall carbon and nitrogen levels in the milfoil were determined. Total biomass of the untreated milfoil increased by more than 2.7-fold during the 53-day experimental period. Conversely, the biomass of milfoil subjected to chemical or biological treatment either remained constant or decreased significantly during the experiment. The herbicide 2,4-D resulted in nearly 100% milfoil mortality by day 20, whereas fluridone toxicity was significantly slower but reached 75% by the end of the trial. Similarly, milfoil growth in the weevil-amended tanks was somewhat erratic but by the end of the trial, the total plant biomass was 71% less than that of un-amended controls. Although the total biomass remaining at the end of the fluridone and weevil treatments was similar, the carbohydrate and starch content of the shoots in the insect treatment were nearly 4.6- and 4.8-fold greater, respectively, than that of the herbicide treated plants. The higher starch content in insect-treated plants could lead to increased autofragmentation and spread of M. spicatum. However, herbicide treatments are frequently required for several years. Therefore, integrated pest management, which combines the long-term benefits of biological controls with the short-term benefits of herbicides may provide the best solution to the control of M. spicatum and the conservation of native plants.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('09e6787e-6f9a-4a40-add7-9dcab28b7429', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Effects and Management of Parthenium hysterophorus: A Weed of Global Significance', 'Kaur M, Aggarwal NK, Kumar V, Dhiman R', 2014, 'International scholarly research notices', '10.1155/2014/368647', 'https://doi.org/10.1155/2014/368647', 'https://europepmc.org/articles/PMC4897546?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Congress grass, Parthenium hysterophorus L., of the family Asteraceae (tribe: Heliantheae), is an erect and much branched annual or ephermeral herb, known for its notorious role as environmental, medical, and agricultural hazards. It is believed to have been introduced into India and Australia from North America and in the last few years the weed has emerged as the seventh most devastating weed in Africa, Asia, and Australia. The aim of this review is to provide general information about the physiology, distribution, ill effects, and management of parthenium. Control of parthenium has been tried by various methods, but no single management option would be adequate to manage parthenium, and there is a need to integrate various management options. Successful management of this weed can only be achieved by an integrated approach with biological control as the key element.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('917a30b1-aafd-4181-b78c-f385d494a80b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Pollination of legumes', 'Government of Alberta', 1964, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/pollination-of-legumes', 'https://open.alberta.ca/dataset/5197ec59-31c1-4bfb-84e6-aa955759996f/resource/5f0170ba-66d2-4263-b612-fcebbfa29a1a/download/0163010342778-pollination-of-legumes.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report examines the critical role of pollinating insects, primarily bees, in the commercial seed production of various legume crops such as alfalfa, alsike clover, red clover, and yellow blossom sweet clover. It details the specific pollination requirements for each legume, highlighting the effectiveness of different bee species and the challenges associated with particular crop-pollinator interactions. The resource emphasizes the importance of isolating crops from competitors and suggests a community-based approach for seed production to maximize pollination efficiency and yields. It also discusses compensation models for beekeepers providing pollination services, including crop share and cash rental agreements, to ensure mutually beneficial arrangements between seed growers and beekeepers.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c0ebe38-983a-45bd-8a23-3f8cc0092446', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Enhanced 2,4-D Metabolism in Two Resistant Papaver rhoeas Populations from Spain', 'Torra J, Rojano-Delgado AM, Rey-Caballero J, Royo-Esnal A, Salas ML, De Prado R', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.01584', 'https://doi.org/10.3389/fpls.2017.01584', 'https://europepmc.org/articles/PMC5602352?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Corn poppy (Papaver rhoeas), the most problematic broadleaf weed in winter cereals in Southern Europe, has developed resistance to the widely-used herbicide, 2,4-D. The first reported resistance mechanism in this species to 2,4-D was reduced translocation from treated leaves to the rest of the plant. However, the presence of other non-target site resistance (NTSR) mechanisms has not been investigated up to date. Therefore, the main objective of this research was to reveal if enhanced 2,4-D metabolism is also present in two Spanish resistant (R) populations to synthetic auxins. With this aim, HPLC experiments at two 2,4-D rates (600 and 2,400 g ai ha-1) were conducted to identify and quantify the metabolites produced and evaluate possible differences in 2,4-D degradation between resistant (R) and susceptible (S) plants. Secondarily, to determine the role of cytochrome P450 in the resistance response, dose-response experiments were performed using malathion as its inhibitor. Three populations were used: S, only 2,4-D R (R-703) and multiple R to 2,4-D and ALS inhibitors (R-213). HPLC studies indicated the presence of two hydroxy metabolites in these R populations in shoots and roots, which were not detected in S plants, at both rates. Therefore, enhanced metabolism becomes a new NTSR mechanism in these two P. rhoeas populations from Spain. Results from the dose-response experiments also showed that pre-treatment of R plants with the cytochrome P450 (P450) inhibitor malathion reversed the phenotype to 2,4-D from resistant to susceptible in both R populations. Therefore, it could be hypothesized that a malathion inhibited P450 is responsible of the formation of the hydroxy metabolites detected in the metabolism studies. This and previous research indicate that two resistant mechanisms to 2,4-D could be present in populations R-703 and R-213: reduced translocation and enhanced metabolism. Future experiments are required to confirm these hypotheses, understand the role of P450, and the relationship between both NTSR mechanisms. On this basis, selection pressure with synthetic auxins bears the risk of promoting the evolution enhanced metabolism in Papaver rhoeas.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dbd1f778-ea66-48df-9274-186bec1b7767', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'First Report of Amaranthus palmeri S. Wats. in Cotton, Maize and Sorghum in Greece and Problems with Its Management', 'Panagiotis Kanatas, Alexandros Tataridas, Vyronas Dellaportas, Ilias Travlos', 2021, 'Agronomy', '10.3390/agronomy11091721', 'https://doi.org/10.3390/agronomy11091721', 'https://www.mdpi.com/2073-4395/11/9/1721', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Amaranthus palmeri S. Wats., or commonly Palmer amaranth, is an invasive plant species that has invaded many countries worldwide and causes significant yield losses to annual spring crops. Palmer amaranth biotypes were detected in maize and sorghum fields in Western Greece and cotton fields in Central Greece in 2020. The infestations were recorded both inside the crops and in the margins of the fields, indicating that Palmer amaranth could be characterized as an invasive weed for these regions and, thus, must be urgently managed. Four biotypes were screened for resistance to 2,4-D and nicosulfuron by using NDVI, canopy cover, photochemical efficiency, plant height and fresh weight values. All biotypes showed resistance to nicosulfuron. Resistance cases to important herbicides (i.e., ALS and synthetic auxins) in spring crops, such as maize and cotton, indicate that management could become even more challenging if farmers do not adopt integrated strategies and tools to manage this weed. The eradication of Palmer amaranth plants is imperative, since it has yet to be dispersed in several agricultural areas of Greece. Palmer amaranth is recommended to be enlisted as quarantine pest for regulation in Greece.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6f37eb77-a506-465a-9b9d-8f02d392f52f', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Health Effects of Pesticide Exposure in Latin American and the Caribbean Populations: A Scoping Review', 'Zúñiga-Venegas LA, Hyland C, Muñoz-Quezada MT, Muñoz-Quezada MT, Quirós-Alcalá L, Butinof M, Buralli R, Cardenas A', 2022, 'Environmental health perspectives', '10.1289/ehp9934', 'https://doi.org/10.1289/ehp9934', 'https://europepmc.org/articles/PMC9521041?pdf=render', NULL, NULL, 57, NULL, 'other', 1, 'cc0', 'BackgroundMultiple epidemiological studies have shown that exposure to pesticides is associated with adverse health outcomes. However, the literature on pesticide-related health effects in the Latin American and the Caribbean (LAC) region, an area of intensive agricultural and residential pesticide use, is sparse. We conducted a scoping review to describe the current state of research on the health effects of pesticide exposure in LAC populations with the goal of identifying knowledge gaps and research capacity building needs.MethodsWe searched PubMed and SciELO for epidemiological studies on pesticide exposure and human health in LAC populations published between January 2007 and December 2021. We identified 233 publications from 16 countries that met our inclusion criteria and grouped them by health outcome (genotoxicity, neurobehavioral outcomes, placental outcomes and teratogenicity, cancer, thyroid function, reproductive outcomes, birth outcomes and child growth, and others).ResultsMost published studies were conducted in Brazil (37%, n=88) and Mexico (20%, n=46), were cross-sectional in design (72%, n=167), and focused on farmworkers (45%, n=105) or children (21%, n=48). The most frequently studied health effects included genotoxicity (24%, n=62) and neurobehavioral outcomes (21%, n=54), and organophosphate (OP) pesticides were the most frequently examined (26%, n=81). Forty-seven percent (n=112) of the studies relied only on indirect pesticide exposure assessment methods. Exposure to OP pesticides, carbamates, or to multiple pesticide classes was consistently associated with markers of genotoxicity and adverse neurobehavioral outcomes, particularly among children and farmworkers.DiscussionOur scoping review provides some evidence that exposure to pesticides may adversely impact the health of LAC populations, but methodological limitations and inconsistencies undermine the strength of the conclusions. It is critical to increase capacity building, integrate research initiatives, and conduct more rigorous epidemiological studies in the region to address these limitations, better inform public health surveillance systems, and maximize the impact of research on public policies. https://doi.org/10.1289/EHP9934.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d6f142cf-07e0-494a-b6e9-c86f8f44de61', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'High-resolution DNA methylome reveals that demethylation enhances adaptability to continuous cropping comprehensive stress in soybean', 'Liang X, Hou X, Li J, Han Y, Zhang Y, Feng N, Du J, Zhang W', 2019, 'BMC plant biology', '10.1186/s12870-019-1670-9', 'https://doi.org/10.1186/s12870-019-1670-9', 'https://europepmc.org/articles/PMC6380062?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'BackgroundContinuous cropping stress involves such factors as biological barriers, allelopathic autotoxicity, deterioration of soil physicochemical properties, and soil fertility imbalance and is regarded as a kind of comprehensive stress limiting soybean yield and quality. Genomic DNA methylation is an important regulatory mechanism for plants to resist various environmental stresses. Therefore, it is especially worthwhile to reveal genomic methylation characteristics under stress and clarify the relationship between DNA methylation status and continuous cropping stress adaptability in soybean.ResultsWe generated a genome-wide map of cytosine methylation induced by this kind of comprehensive stress in a tolerant soybean variety (Kang Xian 2, KX2) and a sensitive variety (He Feng, HF55) using whole-genome bisulfite sequencing (WGBS) technology. The expression of DNA demethylase genes was detected using real-time quantitative PCR (qRT-PCR). The functions of differentially methylated genes (DMGs) involved in stress response in biochemical metabolism and genetic information transmission were further assessed based on Gene Ontology (GO) annotation and Kyoto Encyclopedia of Genes and Genomes (KEGG) pathway analysis. The results showed that genomic DNA demethylation was closely related to continuous cropping comprehensive stress adaptability in soybean, which was further verified by the increasing expression of DNA demethylases ROS1 and DML. The demethylation of mCpG and mCpHpG (mCpApG preferred) contexts was more critical, which mainly occurred in gene-regulatory regions at the whole-chromosome scale. Moreover, this kind of stress adaptability may be related to various stress responders generated through strengthened glucose catabolism and amino acid and fatty acid anabolism, as well as fidelity transmission of genetic information.ConclusionsGenomic DNA demethylation was closely associated with continuous cropping comprehensive stress adaptability, highlighting the promising potential of screening continuous cropping-tolerant cultivars by DNA methylation index and further exploring the application of DNA demethylases in soybean breeding.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('24ff0f0a-8893-45eb-bd3a-fa4dde5bb65a', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Integrated Pest Management for Sustainable Intensification of Agriculture in Asia and Africa', 'Pretty J, Bharucha ZP', 2015, 'Insects', '10.3390/insects6010152', 'https://doi.org/10.3390/insects6010152', 'https://europepmc.org/articles/PMC4553536?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Integrated Pest Management (IPM) is a leading complement and alternative to synthetic pesticides and a form of sustainable intensification with particular importance for tropical smallholders. Global pesticide use has grown over the past 20 years to 3.5 billion kg/year, amounting to a global market worth $45 billion. The external costs of pesticides are $4-$19 (€3-15) per kg of active ingredient applied, suggesting that IPM approaches that result in lower pesticide use will benefit, not only farmers, but also wider environments and human health. Evidence for IPM''s impacts on pesticide use and yields remains patchy. We contribute an evaluation using data from 85 IPM projects from 24 countries of Asia and Africa implemented over the past twenty years. Analysing outcomes on productivity and reliance on pesticides, we find a mean yield increase across projects and crops of 40.9% (SD 72.3), combined with a decline in pesticide use to 30.7% (SD 34.9) compared with baseline. A total of 35 of 115 (30%) crop combinations resulted in a transition to zero pesticide use. We assess successes in four types of IPM projects, and find that at least 50% of pesticide use is not needed in most agroecosystems. Nonetheless, policy support for IPM is relatively rare, counter-interventions from pesticide industry common, and the IPM challenge never done as pests, diseases and weeds evolve and move.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18675d79-3290-4d60-a028-a03bbdcec629', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Kyleo ® - mode of action under examination', 'Heibertshausen, Dagmar, Konradt, Manfred, Diehl, Tobias', 2014, 'Julius-Kühn-Archiv', '10.5073/jka.2014.443.076', 'https://doi.org/10.5073/jka.2014.443.076', 'http://pub.jki.bund.de/index.php/JKA/article/view/2922/3121', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Kyleo® with two known active substances (ai) is an innovative, modern herbicide for resistance management. Kyleo® contains 160 g/l 2,4-D and 240 g/l glyphosate. With an application rate of 5,0 l/ha, it shows a far better, faster effect on weeds such as field horsetail (Equisetum arvense), volunteer oilseed rape (Brassica napus) and couch grass (Agropyron repens) compared to a tank mix or the reference products (RP). This is explained by an unique new formulation technology that for the first time combines 2,4-D as acid and glyphosate as MIPA salt together with FHS. The new form of 2,4-D is lipophilic with better leaf absorption and greater photolytic degradation in the upper layers of soil. Tests with radioactive marked substances have verified the systemic properties of both ai compared to RP. The displacement of 2,4-D into the plant roots was demonstrated 48 h after application (hpt). 98% glyphosate absorption was observed in rape and couch grass – 10% (rape) respectively 25% (couch grass) greater than with RP. Higher absorption of the ai is characterised by a swifter effect, with stronger, visible symptoms after 24 h in rape and 96 h in couch grass. The rainfastness of Kyleo® was tested in greenhouse (GH) trials with rape. Comparability of the test objects was simulated with a uniform glyphosate quantity of 360 g/ha and 10 l/m² simulated precipitation. 24% improved effect compared to RP was verified for 1 hpt rainfall, while 4% improved effect was recorded for rain simulation after 6 hpt. GH trials with wheat and a comparable glyphosate application quantity of 290 g/ha revealed differences of 23% and 22% compared to RP for rain simulation of 1 hpt and 6 hpt. Kyleo® stands out with a swift effect and better rainfastness. The results presented here prove a systemic mode of action, good rainfastness and swift effect of Kyleo.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a32de944-e78c-4a4b-b850-7d1d4da7c95c', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Managing auxin-resistant Palmer amaranth (Amaranthus palmeri) from West Tennessee with sequential applications of 2,4-D with and without glufosinate', 'Colton Fuller, Thomas Mueller, Lawrence E. Steckel', 2026, 'Weed Technology', '10.1017/wet.2026.10115', 'https://doi.org/10.1017/wet.2026.10115', 'https://www.cambridge.org/core/product/identifier/S0890037X26101158/type/journal_article', NULL, NULL, 5, NULL, 'other', 1, 'open access (DOAJ)', 'Auxinic herbicides are crucially necessary for maintaining effective weed management in modern agronomic systems. Palmer amaranth has evolved resistance to multiple herbicides, including auxinic herbicides. Since auxin resistance has been determined in Palmer amaranth, new strategies should be implemented to improve the weed’s management. Field studies were conducted in Tennessee during the summers of 2024 and 2025 to evaluate the efficacy of various herbicide application methods for managing auxin-resistant Palmer amaranth. The research compared tank-mixed applications of 2,4-D and glufosinate with split-boom applications (herbicides applied simultaneously through separate spray booms as independent solutions) to multiple Palmer amaranth populations. Results demonstrated that in populations that exhibited high resistance to auxinic herbicides, the split-boom application method was more effective than the conventional tank-mix method. However, control levels were still below those typically considered acceptable for effective Palmer amaranth control. Sequential split-boom applications were required to achieve acceptable levels of control in these populations. A second study evaluated whether carrier volume influenced the performance of these applications by comparing mixtures of 140 L ha−1 and 280 L ha−1. The results indicated that carrier volume did not significantly affect Palmer amaranth control at these volumes.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ae41027-83aa-4781-bc72-25324da231ac', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Occupational pesticide exposures and respiratory health', 'Ye M, Beach J, Martin JW, Senthilselvan A', 2013, 'International journal of environmental research and public health', '10.3390/ijerph10126442', 'https://doi.org/10.3390/ijerph10126442', 'https://europepmc.org/articles/PMC3881124?pdf=render', NULL, NULL, 30, NULL, 'alberta', 4, 'cc by', 'Pesticides have been widely used to control pest and pest-related diseases in agriculture, fishery, forestry and the food industry. In this review, we identify a number of respiratory symptoms and diseases that have been associated with occupational pesticide exposures. Impaired lung function has also been observed among people occupationally exposed to pesticides. There was strong evidence for an association between occupational pesticide exposure and asthma, especially in agricultural occupations. In addition, we found suggestive evidence for a link between occupational pesticide exposure and chronic bronchitis or COPD. There was inconclusive evidence for the association between occupational pesticide exposure and lung cancer. Better control of pesticide uses and enforcement of safety behaviors, such as using personal protection equipment (PPE) in the workplace, are critical for reducing the risk of developing pesticide-related symptoms and diseases. Educational training programs focusing on basic safety precautions and proper uses of personal protection equipment (PPE) are possible interventions that could be used to control the respiratory diseases associated with pesticide exposure in occupational setting.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('62a3062c-45d2-4aa7-82cd-b1dbaa4fc12f', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Plant-Microbiome Crosstalk: Dawning from Composition and Assembly of Microbial Community to Improvement of Disease Resilience in Plants', 'Noman M, Ahmed T, Ijaz U, Shahid M, Shahid M, Azizullah, Li D, Manzoor I', 2021, 'International journal of molecular sciences', '10.3390/ijms22136852', 'https://doi.org/10.3390/ijms22136852', 'https://europepmc.org/articles/PMC8269294?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Plants host diverse but taxonomically structured communities of microorganisms, called microbiome, which colonize various parts of host plants. Plant-associated microbial communities have been shown to confer multiple beneficial advantages to their host plants, such as nutrient acquisition, growth promotion, pathogen resistance, and environmental stress tolerance. Systematic studies have provided new insights into the economically and ecologically important microbial communities as hubs of core microbiota and revealed their beneficial impacts on the host plants. Microbiome engineering, which can improve the functional capabilities of native microbial species under challenging agricultural ambiance, is an emerging biotechnological strategy to improve crop yield and resilience against variety of environmental constraints of both biotic and abiotic nature. This review highlights the importance of indigenous microbial communities in improving plant health under pathogen-induced stress. Moreover, the potential solutions leading towards commercialization of proficient bioformulations for sustainable and improved crop production are also described.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('42ee4e5e-f1d7-4d1a-b0c9-ee08fcfb980b', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Removal of micropollutants through a biological wastewater treatment plant in a subtropical climate, Queensland-Australia', 'Cardenas MA, Ali I, Lai FY, Dawes L, Thier R, Rajapakse J', 2016, 'Journal of environmental health science & engineering', '10.1186/s40201-016-0257-8', 'https://doi.org/10.1186/s40201-016-0257-8', 'https://europepmc.org/articles/PMC5093989?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'BackgroundMunicipal wastewaters contain a multitude of organic compounds derived from domestic and industrial sources including active components of pharmaceutical and personal care products and compounds used in agriculture, such as pesticides, or food processing such as artificial sweeteners often referred to as micropollutants. Some of these compounds or their degradation products may have detrimental effects on the environment, wildlife and humans. Acesuflame is one of the most popular artificial sweeteners to date used in foodstuffs. The main objectives of this descriptive study were to evaluate the presence of micropollutants in both the influent and effluent of a large-scale conventional biological wastewater treatment plant (WWTP) in South-East Queensland receiving wastewater from households, hospitals and various industries.MethodsBased on USEPA Method 1694: Filtered samples were spiked with mass-labelled chemical standards and then analysed for the micropollutants using liquid chromatography coupled with tandem mass spectrometry.ResultsThe presence of thirty-eight compounds were detected in the wastewater influent to the treatment plant while nine of the compounds in the categories of analgesic, anti-inflammatory, alkaloid and lipid/cholesterol lowering drugs were undetectable (100 % removed) in the effluent. They were: Analgesic: Paracetamol, Salicylic acid, Oxycodone; Anti-inflammatory: Naproxen + ve, Atorvastatin, Indomethacin, Naproxen; Alkaloid: Caffeine; Lipid/cholesterol lowering: Gemfibrozol.ConclusionsThe study results revealed that the micropollutants removal through this biological treatment process was similar to previous research reported from other countries including Europe the Americas and Asia, except for acesulfame, a highly persistent artificial sweetener. Surprisingly, acesulfame was diminished to a much greater extent (>90 %) than previously reported research for this type of WWTPs (45-65 %) that only include physical removal of objects and solids and a biodegradation step.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c49e60ab-b9a0-4dc1-8cc5-54740599acfb', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Varietal description of Manley two-row spring barley', 'Government of Alberta', 1991, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/varietal-description-of-manley-two-row-spring-barley', 'https://open.alberta.ca/dataset/8ad3121a-0002-4970-913a-08120bcd1251/resource/75c4cba9-c97b-4548-8acd-67ba69afda67/download/2386299-2002-varietal-description-of-manley-two-row-spring-barley.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document described the origin, breeding process, agronomic traits, malting quality, disease resistance, and performance of the Manley two-row spring barley variety, developed at the University of Saskatchewan. Manley was selected for height, maturity, yield, and resistance to root rot (Cochliobolus sativus), stem rust (Puccinia graminis), and smuts (Ustilago nigra, U. hordei). It showed good malting quality, intermediate protein content, and better lodging resistance than Harrington. Comparative trial data from 1984 to 1986 across multiple soil zones in western Canada were included, showing Manley''s superior yield and acceptable disease resistance.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a48dc4f2-72ae-433e-b47c-462a0822400e', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Rhizoxin and 2,4-diacetylphloroglucinol contribute to biocontrol of Pseudomonas protegens Pf-5 against pea Ascochyta blight pathogen Didymella pinodes', 'Priyanto JA, Mwanza C, Purnamasari M, Wu X, Huang L, Yan Q', 2026, 'Microbiology spectrum', '10.1128/spectrum.01325-26', 'https://doi.org/10.1128/spectrum.01325-26', 'https://europepmc.org/articles/PMC13532272?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'Biological control using beneficial bacteria is a promising strategy for managing pea Ascochyta blight (AB), yet the underlying mechanisms remain poorly understood. In this study, we identified 10 bacterial strains from 4 genera, including Bacillus, Paenibacillus, Peribacillus, and Pseudomonas, that significantly reduced the severity of AB caused by Didymella pinodes under greenhouse conditions. Most strains inhibited D. pinodes in cultures, indicating a production of antimicrobial metabolite(s) by these bacteria. To identify the antimicrobial compounds responsible for inhibition of D. pinodes and investigate the biocontrol mechanisms, we used Pseudomonas protegens Pf-5, which produces eight known antimicrobial compounds, as a model. While wild-type Pf-5 strongly inhibited D. pinodes in cultures and controlled AB in planta, a derivative (Δ8-fold mutant) lacking all eight compounds showed significantly compromised biocontrol efficacy. Individual complementation of biosynthetic genes for rhizoxin, 2,4-diacetylphloroglucinol (DAPG), pyrrolnitrin, or hydrogen cyanide partially restored inhibitory activity, confirming their roles in inhibition of D. pinodes. Notably, restoring rhizoxin and DAPG biosynthesis recovered the disease control capability of the Δ8-fold mutant in greenhouse trials. These results demonstrate that rhizoxin and DAPG are key metabolites driving the biocontrol activity of P. protegens Pf-5 against D. pinodes.IMPORTANCEAn advanced understanding of how beneficial bacteria control plant diseases can help us better use these microorganisms in agriculture. In this study, beneficial bacteria were identified to mitigate damages of pea Ascochyta blight (AB) caused by the fungal pathogen Didymella pinodes. Most of the identified beneficial bacteria inhibited the fungal pathogen in cultures. Using the soil beneficial bacterium Pseudomonas protegens Pf-5 as a model, we demonstrated that four bacteria-derived antimicrobial compounds, rhizoxin and 2,4-diacetylphloroglucinol (DAPG), pyrrolnitrin, and hydrogen cyanide, play important roles in inhibiting D. pinodes growth. This study also showed that rhizoxin and DAPG produced by Pf-5 contribute to the suppression of AB disease development. These findings provided new insights into the molecular basis of beneficial bacteria-mediated disease suppression of pea Ascochyta blight.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cefa5b9f-5d58-4cb5-86f4-777d3a29e7ba', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Rice husk-biochar nano-carrier based 2, 4-D herbicide for efficient management of broad leaf weeds and sedges', 'Lisha Jose Kappen, V.S. Susha, M. Ameena, P. Shalini Pillai, T. Anuradha, K. Jayasankar, K.N. Anith', 2025, 'Plant Nano Biology', '10.1016/j.plana.2025.100203', 'https://doi.org/10.1016/j.plana.2025.100203', 'http://www.sciencedirect.com/science/article/pii/S2773111125000701', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Rice husk (RHNC) and rice husk biochar (RHBNC) nano-carriers were evaluated for enhancing the bio-efficacy of 2,4-D herbicide. Nano-carriers were synthesized by planetary ball milling and loaded with 2,4-D at two weight ratios (1:0.25 and 1:0.10). Structural characterization was carried out using SEM, FT-IR, XRD, BET surface area, and BJH pore volume analysis. SEM images of ball-milled rice husk biochar revealed a porous structure with cracks and shrinkage, while FT-IR confirmed the presence of aromatic, carbonyl, and siloxane groups. XRD spectra of RHBNC displayed a broadened peak at 45° (2θ). BET analysis indicated reduced surface area (9.85 m² g⁻¹) and pore volume (0.043 cm³ g⁻¹) after herbicide loading. Bio-efficacy was assessed against Limnocharis flava and Cyperus rotundus in pots, followed by a field trial in upland rice. RHBNC (1:0.25) at 0.8 kg ha⁻¹ exhibited the highest weed control efficiency (95.33 % in purple nutsedge and 98.74 % in water cabbage) and significantly improved rice yield (2840 kg ha⁻¹), representing a 21 % increase over conventional 2,4-D. Enhanced soil biological activity was also observed, with higher dehydrogenase activity (31.70 µg TPF g⁻¹ soil d⁻¹) and bacterial counts (52.00 × 10⁶ CFU g⁻¹ wet soil) compared to conventional treatments. These results prove the efficacy of rice husk biochar as a good and ecofriendly nano-carrier of 2,4-D, providing enhanced weed control, crop yields, and soil microbial well-being.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('82284071-4ae2-486f-b943-570b566fc9b9', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'The Response of Iranian Melon (Cucumis melo L.) Accessions to 2,4-D Drift', 'Rouzbeh Zangoueinejad, Behnaz Sirooeinejad, Mohammad Taghi Alebrahim, Ali Ahsan Bajwa', 2021, 'Plants', '10.3390/plants10112442', 'https://doi.org/10.3390/plants10112442', 'https://www.mdpi.com/2223-7747/10/11/2442', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'One of the most widely used auxinic herbicides in southern Iran’s cereal crop fields is 2,4-D; however, the concurrent growing season of off-season melons in this region potentially leads to herbicide drift from cereal fields to the melon fields. To study the response of some Iranian wild melon accessions to three simulated drift rates of 2,4-D, including 112.1, 11.2, and 3.7 g ae ha−1, a field experiment was conducted during 2019 and 2020 growing seasons. It was found that by increasing the herbicide rate from 3.7 to 112.1 g ae ha−1, the level of visual injury increased in all accessions. However, significant variation in herbicide tolerance was observed among different melon accessions. The MEL-R1 was the most tolerant accession with only 20% injury, while MEL-D8 displayed very high injury rate (ca. 90%) as assessed at 6 weeks after treatment during 2019. The accession MEL-S3 was the most tolerant to 2,4-D drift rates (20% injury) at 6 weeks after treatment during 2020. There was no significant difference between the accessions MEL-R1 and MEL-S3 in terms of their response to 2,4-D treatment during both years of the study, as these accessions fully recovered from injury over 6 weeks after herbicide treatment. In addition, only these two accessions were able to produce yield after the application of 2,4-D at the highest rate tested (112.1 g ae ha−1). Therefore, the melon accessions MEL-R1 and MEL-S3 could be recommended for cultivation and even for breeding programs in order to develop 2,4-D-tolerant commercial cultivars in regions where this herbicide is commonly used in cereal crop production adjacent to the melon fields.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('342acea6-c193-45d2-bff1-9face2615e34', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Tracing Resistance of Weeds to Aryloxyphenoxypropionate (ACCase), Acetolactate Synthase (ALS) and Synthetic Auxcins Herbicides in Shoushtar Wheat Fields', 'E. Elahifard, A. Derakhshan, H. Zarrinjoob', 2017, 'Majallah-i ḥifāẓat-i giyāhān', '10.22067/jpp.v0i0.56555', 'https://doi.org/10.22067/jpp.v0i0.56555', 'https://jpp.um.ac.ir/index.php/jpp/article/view/56555', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Introduction: Since the first compilation of herbicide-resistant weeds in 1982, the number of reported herbicide-resistant species has increased significantly. Iudosulfuron-methyl-sodium + mesosulfuron-methyl+ mefenpyr diethyl, sulfosulfuron and tribenuron-methyl, acetolactate synthase (ALS) inhibiting herbicides, clodinafoppropargyl, aryloxyphenoxypropionate (ACCase) inhibiting herbicides and 2,4-D+MCPA, synthetic auxcins herbicides are registered in Iran for post emergence control of broadleaf and some grass weeds in wheat (Triticumaestivum L.). In southwest Iran, Khouzestan province, the appearance of wild oat (AvenaludovicianaDurieu), littleseedcanarygrass (Phalaris minor Retz) and wild mustard (SinapisarvensisL.) populations with different degrees of resistance to mentioned herbicides has been reported previously in last decade. A reliable seedling bioassay was developed and tested for the rapid screening for resistance to aryloxyphenoxypropionic (APP) herbicides in some.populationsspecialy grass weed. This paper describes a rapid and reliable seedling test to detect APP-resistant A. ludoviciana,Phalaris minor and Sinapisarvensisbiotypes in order to determine their frequency within a population. This test has also been developed in order to discriminate between APP, ALS and synthetic auxcin -resistant biotypes. Materials and Methods: Suspected resistant and susceptible seeds of wild oat, littleseedcanarygrass and wild mustard to iodosulfuron-methyl -sodium+ mesosulfuron-methyl+ mefenpyr diethyl, sulfosulfuron and tribenuron-methyl, clodinafoppropargyl and 2,4-D+MCPA were collected from wheat fields, Shoushtar, southwestern of Iran in 2014 – 2015 growing season. The wild oat and littleseedcanarygrass seedspregerminated in petri dishes. Single doses of clodinafop (1.25 and 0.080 mg ai L-1) were used for the R- and S- populations of wild oat and littleseedcanarygrass, respectively. These experiments were carried out by placing 5 pre-germinated seeds in a 7-cm-diam petri dish containing one piece of filter paper and 5 ml of distilled water or solutions having concentration of clodinafop. The petri dishes were placed in the germinator. The coleoptiles length of seedlings was measured 7 days after treatment (DAT). The pregerminated seeds of wild mustard were sown in pots and irrigated regularly to avoid any moisture stress. Ten days after planting (DAP), they were thinned to two seedlings per pot. Twenty days after weed emergence, seedlings of the pots were subjected to iodosulfuron-methyl-sodium + mesosulfuron-methyl+ mefenpyr diethyl (18 g ai ha-1), sulfosulfuron (19.95 g ai ha-1) and tribenuron-methyl (15 g ai ha-1) and 2,4-D+MCPA (200 g ai ha-1) application. The sprayer was calibrated to deliver 338 L ha-1 at pressure of 2 atm. The aboveground biomass was harvested 28 days after treatment (DAT) and weighed. Then, distribution map of resistant and susceptible populations in fields was drawn using GIS 9.3 software. Results and Discussion: The results showed that eleven, eight, two and one wild mustard populations were confirmed resistant (RRR), probably resistant (RR), possibly resistant (R?) and susceptible (S) to sulfosulfuron based on “R” ratings system. In addition, three, twelve, three and four wild mustard populations were confirmed resistant, probably resistant, possibly resistant and susceptible to iodosulfuron-methyl-sodium + mesosulfuron-methyl+ mefenpyr diethyl. For tribenuron-methyl, seven, twele and three populations were confirmed resistant, probably resistant, possibly resistant and other populations were susceptible. Meanwhile, whole populations were susceptible to 2,4-D+ MCPA. Seven days after clodinafop treatment, a clear difference in symptoms was observed between the R- and S- populations. Clodinafop affected the cleoptile length of S- and R-populations of wild oat and littleseedcanarygrass differentially. As, thirty three, fifteen and one wild oat populations were confirmed resistant, probably resistant,', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('526e91cd-44f6-49ef-ac0c-986b5be6673b', '19b64a68-f4ef-4f01-9fb8-ba34a30ee3b0', 'Weed responses to fallow management in Pacific Northwest dryland cropping systems', 'San Martín C, Long DS, Gourlie JA, Barroso J', 2018, 'PloS one', '10.1371/journal.pone.0204200', 'https://doi.org/10.1371/journal.pone.0204200', 'https://europepmc.org/articles/PMC6147650?pdf=render', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc0', 'A two-year rotation of summer fallow (SF)/winter wheat (WW) is the most common cropping system in low precipitation areas of the U.S. Pacific Northwest (PNW). In SF, multiple tillage operations are used to manage weeds and maximize soil water storage and potential WW yield. Reduced tillage fallow (RTF) is an alternative to SF that leaves >30% of the previous crop''s residue on the surface. A four-year (2014-18) field study was conducted to evaluate the influence of SF and RTF on weed species density, cover and composition in dryland WW; determine if changes in these weed infestation attributes have any influence on crop density and yield; and evaluate economic costs of each type of fallow management. The experimental design was randomized complete block with four replications where each phase of SF/WW and RTF/WW rotations was present every year. Individual plots of WW were divided into a weedy sub-plot with no weed control, general area with chemical weed control, and weed-free sub-plot where weeds were manually removed. Infestations of annual grass and other weeds in weedy sub-plots increased throughout the study. Grass weed cover, consisting mainly of downy brome (Bromus tectorum L.), and total weed cover were significantly lower in WW following RTF than following SF in all years except 2018. Densities of grass and total weeds were similar in both fallow managements indicating that weed plants were larger in WW following SF than following RTF due to earlier or faster emergence. Grass cover differences were not found in general areas likely because of a reduced seedbank. When weeds were present, mean yield of WW was higher following RTF than SF indicating that weeds were less competitive in RTF. Reduced tillage fallow could improve weed management in fallow/WW cropping systems of the PNW compared to SF/WW, particularly if the most problematic species are grasses.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b96592c8-3225-448d-a543-8f63d6ad4914', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Agrochemicals against malaria, sleeping sickness, leishmaniasis and Chagas disease', 'Witschel M, Rottmann M, Kaiser M, Brun R', 2012, 'PLoS neglected tropical diseases', '10.1371/journal.pntd.0001805', 'https://doi.org/10.1371/journal.pntd.0001805', 'https://europepmc.org/articles/PMC3493374?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'In tropical regions, protozoan parasites can cause severe diseases with malaria, leishmaniasis, sleeping sickness, and Chagas disease standing in the forefront. Many of the drugs currently being used to treat these diseases have been developed more than 50 years ago and can cause severe adverse effects. Above all, resistance to existing drugs is widespread and has become a serious problem threatening the success of control measures. In order to identify new antiprotozoal agents, more than 600 commercial agrochemicals have been tested on the pathogens causing the above mentioned diseases. For all of the pathogens, compounds were identified with similar or even higher activities than the currently used drugs in applied in vitro assays. Furthermore, in vivo activity was observed for the fungicide/oomyceticide azoxystrobin, and the insecticide hydramethylnon in the Plasmodium berghei mouse model, and for the oomyceticide zoxamide in the Trypanosoma brucei rhodesiense STIB900 mouse model, respectively.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('16a5d9bd-786e-41b2-b1fe-9432224e6429', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Analysis of Fungicide Sensitivity and Genetic Diversity among Colletotrichum Species in Sweet Persimmon', 'Gang GH, Cho HJ, Kim HS, Kwack YB, Kwak YS', 2015, 'The plant pathology journal', '10.5423/ppj.oa.03.2015.0033', 'https://doi.org/10.5423/ppj.oa.03.2015.0033', 'https://europepmc.org/articles/PMC4453992?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'open access (Europe PMC)', 'Anthracnose, caused by Colletotrichum gloeosporioides (C. gloeosporioides; Teleomorph: Glomerella cingulata), is the most destructive disease that affects sweet persimmon production worldwide. However, the biology, ecology, and genetic variations of C. gloeosporioides remain largely unknown. Therefore, in this study, the development of fungicide resistance and genetic diversity among an anthracnose pathogen population with different geographical origins and the exposure of this population to different cultivation strategies were investigated. A total of 150 pathogen isolates were tested in fungicide sensitivity assays. Five of the tested fungicides suppressed mycelial pathogen growth effectively. However, there were significant differences in the sensitivities exhibited by the pathogen isolates examined. Interestingly, the isolates obtained from practical management orchards versus organic cultivation orchards showed no differences in sensitivity to the same fungicide. PCR-restriction fragment length polymorphism (RFLP) analyses were performed to detect internal transcribed spacer regions and the β-tubulin and glutamine synthetase genes of the pathogens examined. Both the glutamine synthetase and β-tubulin genes contained a complex set of polymorphisms. Based on these results, the pathogens isolated from organic cultivation orchards were found to have more diversity than the isolates obtained from the practical management orchards.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('56cca5e8-375e-4721-b1f0-630489da4044', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Association of hydrogen peroxide with commercial fungicide formulations in the control of Asian soybean rust', 'Paulo Henrique Nascimento de Souza, Lilian Maria Arruda Bacchi, Walber Luiz Gavassoni, Wagner da Paz Andrade', 2021, 'Ciência Rural', '10.1590/0103-8478cr20200196', 'https://doi.org/10.1590/0103-8478cr20200196', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0103-84782022000300151&tlng=en', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'ABSTRACT: In recent years, there have been reductions in the efficacy of the fungicidal control of Phakopsora pachyrhizi, thereby hindering the management of soybean rust and compromising crop yield. This study evaluated the effects of incorporating hydrogen peroxide (H2O2) in commercial fungicide formulations on the control of soybean rust. We conducted two experiments, one of which was performed in a greenhouse environment and the other under field conditions. In both environments, we examined the following four control programs using commercial fungicide formulations: (I) azoxystrobin + cyproconazole (quinone outside inhibitor [QoI] + demethylation inhibitor [DMI]); (II) picoxystrobin + cyproconazole (QoI + DMI); (III) pyraclostrobin + epoxiconazole + fluxapyroxad (QoI + DMI + succinate dehydrogenase inhibitor); and (IV) water (H2O) (program without fungicide application), combined with the incorporation of (i) H2O2; (ii) mancozeb (positive control I); (iii) chlorothalonil (positive control II); or (iv) water (H2O) alone. Analyses of infected leaf area and grain yield revealed that the addition of H2O2 to the formulations of DMI and QoI fungicides led to a reduction in disease severity of between 33% and 44% relative to the effects of these products used alone, as well as an increase in yield and SPAD values. The use of H2O2 and multi-site fungicides alone failed to provide effective control of soybean rust. In addition to enhancing the efficacy of disease control, the use of H2O2 associated with commercial fungicide mixtures was shown to be a potential tool for the management of fungicide resistance and reduction in losses from Asian soybean rust.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb5282bb-43ba-46f7-92b3-67ea8c896a83', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Biocontrol Potential of Sclerotinia sclerotiorum and Physiological Changes in Soybean in Response to Butia archeri Palm Rhizobacteria', 'Vitorino LC, Silva FOD, Cruvinel BG, Bessa LA, Rosa M, Souchie EL, Silva FG', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9010064', 'https://doi.org/10.3390/plants9010064', 'https://europepmc.org/articles/PMC7020477?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Sclerotinia sclerotiorum is a necrotrophic parasitic fungus that causes Sclerotinia stem rot (SSR), which is currently one of the most difficult agronomic crop diseases to control. A number of plants of the Brazilian Cerrado biome have been shown to be important sources of symbiotic microorganisms with biotechnological potential, so we decided to test the potential of bacteria isolated from the dwarf jelly palm, Butia archeri (Arecaceae) for the control of the pathogenic effects provoked by S. sclerotiorum. For this, we bioprimed seeds and evaluated the effects of this biopriming on the OJIP transient patterns prior to and following infection by the phytopathogen. Plants treated with the BA48R strain of Enterobacter sp., and in particular, those treated with the BA88R strain of Bacillus cereus presented the best results in terms of the loss/gain of the physiological and symptomatological variables evaluated. The plants bioprimed with BA88R presented high post-infection levels of total chlorophyll (33.35 FCIs) and chlorophyll a (26.39 FCIs), maintained a high Nitrogen Balance Index (NBI = 18.87), and synthesized low concentrations of flavonoids (1.39). These plants also maintained high levels of PIABS (1.111) and PITOTAL (1.300) following infection, and low levels of Di0/RC (0.602), which indicates that, in the presence S. sclerotiorum, the efficiency of the photosynthesis in the plants treated with these bacteria was less affected in the reaction centers, as confirmed by the negative amplitude recorded in the L band. The present study reconfirms the importance of the use of chlorophyll fluorescence for the diagnosis of disease and conditions of stress in crop plants, in addition to demonstrating the effectivenesss of the BA48R bacterial strain and, in particular, the BA88R strain on systemic resistance induction and suppression of S. sclerotiorum in Glycine max plants, with enormous potential for the development of more sustainable agricultural processes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35a62799-03fd-4a65-9b18-8817d2da34ae', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Changes in the Phenotype of Winter Wheat Varieties Released Between 1920 and 2016 in Response to In-Furrow Fertilizer: Biomass Allocation, Yield, and Grain Protein Concentration', 'Maeoka RE, Sadras VO, Ciampitti IA, Diaz DR, Fritz AK, Lollato RP', 2019, 'Frontiers in plant science', '10.3389/fpls.2019.01786', 'https://doi.org/10.3389/fpls.2019.01786', 'https://europepmc.org/articles/PMC7002544?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Plant breeding has increased the yield of winter wheat (Triticum aestivum L.) over decades, and the rate of genetic gain has been faster under high fertility in some countries. However, this response is not universal, and limited information exists on the physiological traits underlying the interaction between varieties and fertilization. Thus, our objectives were to identify the key shifts in crop phenotype in response to selection for yield and quality, and to determine whether historical and modern winter wheat varieties respond differently to in-furrow fertilizer. Factorial field experiments combined eight winter wheat varieties released between 1920 and 2016, and two fertilizer practices [control versus 112 kg ha-1 in-furrow 12 -40-0-10-1 (N-P-K-S-Zn)] in four Kansas environments. Grain yield and grain N-removal increased nonlinearly with year of release, with greater increases between 1966 and 2000. In-furrow fertilizer increased yield by ~300 kg ha-1 with no variety × fertility interaction. Grain protein concentration related negatively to yield, and the residuals of this relationship were unrelated to year of release. Yield increase was associated with changes in thermal time to critical growth stages, as modern varieties had shorter vegetative period and longer grain filling period. Yield gains also derived from more kernels m-2 resultant from more kernels head-1. Historical varieties were taller, had thinner stems, and allocated more biomass to the stem than semidwarf varieties. Yield gains resulted from increases in harvest index and not in biomass accumulation at grain filling and maturity, as shoot biomass was similar among varieties. The allometric exponent (i.e., the slope between log of organ biomass and log of shoot biomass) for grain increased with, and for leaves was unrelated to, year of release. The ability of modern varieties to allocate more biomass to the kernels coupled to an early maturity increased grain yield and grain N-removal over time. However, increases in grain yield were greater than increases in grain N-removal, reducing grain protein concentration in modern varieties.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('456969ea-ed8f-4f52-8026-d133768e2fb8', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Potential role of pollen and pollinators in the spread of blossom blight of seed alfalfa caused byBotrytis cinerea', 'Jonathan Reich, Syama Chatterton, Dan Johnson', 2015, 'Canadian Journal of Plant Pathology', '10.1080/07060661.2015.1119734', 'https://doi.org/10.1080/07060661.2015.1119734', 'https://www.tandfonline.com/doi/pdf/10.1080/07060661.2015.1119734?download=true', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('01ceafc2-9786-4502-b96e-fbc57257e738', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Combining Desirable Traits for a Good Biocontrol Strategy against Sclerotinia sclerotiorum', 'Albert D, Dumonceaux T, Carisse O, Beaulieu C, Filion M', 2022, 'Microorganisms', '10.3390/microorganisms10061189', 'https://doi.org/10.3390/microorganisms10061189', 'https://europepmc.org/articles/PMC9228387?pdf=render', NULL, NULL, 18, NULL, 'canada', 3, 'cc by', 'The fungal pathogen Sclerotinia sclerotiorum (Helotiales: Sclerotiniaceae) causes white mold, a disease that leads to substantial losses on a wide variety of hosts throughout the world. This economically important fungus affects yield and seed quality, and its control mostly relies on the use of environmentally damaging fungicides. This review aimed to present the latest discoveries on microorganisms and the biocontrol mechanisms used against white mold. A special focus is put on the identification of biocontrol desirable traits required for efficient disease control. A better understanding of the mechanisms involved and the conditions required for their action is also essential to ensure a successful implementation of biocontrol under commercial field conditions. In this review, a brief introduction on the pathogen, its disease cycle, and its main pathogenicity factors is presented, followed by a thorough description of the microorganisms that have so far demonstrated biocontrol potential against white mold and the mechanisms they use to achieve control. Antibiosis, induced systemic resistance, mycoparasitism, and hypovirulence are discussed. Finally, based on our actual knowledge, the best control strategies against S. sclerotiorum that are likely to succeed commercially are discussed, including combining biocontrol desirable traits of particular interest.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e32833f1-c8f5-4499-95dd-eb8b627353e4', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Development and Evaluation of Glycine max Germplasm Lines with Quantitative Resistance to Sclerotinia sclerotiorum', 'McCaghey M, Willbur J, Ranjan A, Grau CR, Chapman S, Diers B, Groves C, Kabbage M', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.01495', 'https://doi.org/10.3389/fpls.2017.01495', 'https://europepmc.org/articles/PMC5584390?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Sclerotinia sclerotiorum, the causal agent of Sclerotinia stem rot, is a devastating fungal pathogen of soybean that can cause significant yield losses to growers when environmental conditions are favorable for the disease. The development of resistant varieties has proven difficult. However, poor resistance in commercial cultivars can be improved through additional breeding efforts and understanding the genetic basis of resistance. The objective of this project was to develop soybean germplasm lines that have a high level of Sclerotinia stem rot resistance to be used directly as cultivars or in breeding programs as a source of improved Sclerotinia stem rot resistance. Sclerotinia stem rot-resistant soybean germplasm was developed by crossing two sources of resistance, W04-1002 and AxN-1-55, with lines exhibiting resistance to Heterodera glycines and Cadophora gregata in addition to favorable agronomic traits. Following greenhouse evaluations of 1,076 inbred lines derived from these crosses, 31 lines were evaluated for resistance in field tests during the 2014 field season. Subsequently, 11 Sclerotinia stem rot resistant breeding lines were moved forward for field evaluation in 2015, and seven elite breeding lines were selected and evaluated in the 2016 field season. To better understand resistance mechanisms, a marker analysis was conducted to identify quantitative trait loci linked to resistance. Thirteen markers associated with Sclerotinia stem rot resistance were identified on chromosomes 15, 16, 17, 18, and 19. Our markers confirm previously reported chromosomal regions associated with Sclerotinia stem rot resistance as well as a novel region of chromosome 16. The seven elite germplasm lines were also re-evaluated within a greenhouse setting using a cut petiole technique with multiple S. sclerotiorum isolates to test the durability of physiological resistance of the lines in a controlled environment. This work presents a novel and comprehensive classical breeding method for selecting lines with physiological resistance to Sclerotinia stem rot and a range of agronomic traits. In these studies, we identify four germplasm lines; 91-38, 51-23, SSR51-70, and 52-82B exhibiting a high level of Sclerotinia stem rot resistance combined with desirable agronomic traits, including high protein and oil contents. The germplasm identified in this study will serve as a valuable source of physiological resistance to Sclerotinia stem rot that could be improved through further breeding to generate high-yielding commercial soybean cultivars.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a9021ea0-c1d4-4f03-adee-11f00a38dc0c', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Evaluating the Potential Value of Natural Product Cuminic Acid against Plant Pathogenic Fungi in Cucumber', 'Wang Y, Zhang J, Sun Y, Feng J, Zhang X', 2017, 'Molecules (Basel, Switzerland)', '10.3390/molecules22111914', 'https://doi.org/10.3390/molecules22111914', 'https://europepmc.org/articles/PMC6150400?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Fusarium wilt and anthracnose are two major diseases which limit the yield and quality of cucumber worldwide. Cuminic acid was extracted from the seed of Cuminum cyminum L. The mean EC50 values of cuminic acid for inhibiting mycelial growth and zoospore germination of five Fusarium oxysporum f. sp. cucumerinum strains were 25.66 ± 3.02 μg/mL and 15.99 ± 2.19 μg/mL, and of four Colletotrichum lagenarium (Pass.) Ellis and Halsted strains were 29.53 ± 3.18 μg/mL and 18.41 ± 2.78 μg/mL, respectively. In greenhouse experiments, cuminic acid at 2000 μg/mL exhibited 70.77% protective and 62.63% curative efficacies against F. oxysporum, and 65.43% protective and 55.46% curative efficacies against C. lagenarium. Moreover, the translocation behavior of cuminic acid, determined by high performance liquid chromatography (HPLC), showed that it could be readily absorbed and transported upward and downward in cucumber. Importantly, superoxide dismutase (SOD) and pyphenol oxidase (PPO) activities of cucumber leaves treated with cuminic acid increased significantly. All results indicated that cuminic acid showed antifungal activity, and could be used as a botanical fungicide in disease management. This study encourages further investigation on the mechanism of action of cuminic acid and the development of alternative antifungal drugs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f828e7ac-c771-4554-a0ab-c3109c8247e9', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Fungicide effects on fungal community composition in the wheat phyllosphere', 'Karlsson I, Friberg H, Steinberg C, Persson P', 2014, 'PloS one', '10.1371/journal.pone.0111786', 'https://doi.org/10.1371/journal.pone.0111786', 'https://europepmc.org/articles/PMC4219778?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'The fungicides used to control diseases in cereal production can have adverse effects on non-target fungi, with possible consequences for plant health and productivity. This study examined fungicide effects on fungal communities on winter wheat leaves in two areas of Sweden. High-throughput 454 sequencing of the fungal ITS2 region yielded 235 operational taxonomic units (OTUs) at the species level from the 18 fields studied. It was found that commonly used fungicides had moderate but significant effect on fungal community composition in the wheat phyllosphere. The relative abundance of several saprotrophs was altered by fungicide use, while the effect on common wheat pathogens was mixed. The fungal community on wheat leaves consisted mainly of basidiomycete yeasts, saprotrophic ascomycetes and plant pathogens. A core set of six fungal OTUs representing saprotrophic species was identified. These were present across all fields, although overall the difference in OTU richness was large between the two areas studied.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c7cfb876-3b48-4ad5-b78e-911d687e229d', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Fungicide Resistance in Powdery Mildew Fungi', 'Vielba-Fernández A, Polonio Á, Ruiz-Jiménez L, de Vicente A, Pérez-García A, Fernández-Ortuño D', 2020, 'Microorganisms', '10.3390/microorganisms8091431', 'https://doi.org/10.3390/microorganisms8091431', 'https://europepmc.org/articles/PMC7564317?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'Powdery mildew fungi (Erysiphales) are among the most common and important plant fungal pathogens. These fungi are obligate biotrophic parasites that attack nearly 10,000 species of angiosperms, including major crops, such as cereals and grapes. Although cultural and biological practices may reduce the risk of infection by powdery mildew, they do not provide sufficient protection. Therefore, in practice, chemical control, including the use of fungicides from multiple chemical groups, is the most effective tool for managing powdery mildew. Unfortunately, the risk of resistance development is high because typical spray programs include multiple applications per season. In addition, some of the most economically destructive species of powdery mildew fungi are considered to be high-risk pathogens and are able to develop resistance to several chemical classes within a few years. This situation has decreased the efficacy of the major fungicide classes, such as sterol demethylation inhibitors, quinone outside inhibitors and succinate dehydrogenase inhibitors, that are employed against powdery mildews. In this review, we present cases of reduction in sensitivity, development of resistance and failure of control by fungicides that have been or are being used to manage powdery mildew. In addition, the molecular mechanisms underlying resistance to fungicides are also outlined. Finally, a number of recommendations are provided to decrease the probability of resistance development when fungicides are employed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e804e945-5d6a-4f23-b5fa-dce2942eb5fc', 'e674c556-4770-485c-ba28-262e36c330bf', 'TUC 510: nueva variedad de poroto negro (Phaseolus vulgaris L.) con alta tolerancia a las virosis presentes en el noroeste argentino TUC 510: New variety of black bean (Phaseolus vulgaris L.) with high tolerance to viruses in Northwestern Argentina', 'Oscar N. Vizgarra, L. Daniel Ploper, Ana C. Ghio, Andrea Pérez', 2006, 'Revista Industrial y Agrícola de Tucumán', NULL, 'http://www.scielo.org.ar/scielo.php?script=sci_arttext&pid=S1851-30182006000100005', 'http://www.scielo.org.ar/scielo.php?script=sci_arttext&pid=S1851-30182006000100005', NULL, NULL, 9, NULL, 'other', 1, 'open access (DOAJ)', 'Las virosis del mosaico dorado (Bean golden mosaic virus, BGMV) y mosaico enano (Bean dwarf mosaic virus, BDMV) constituyen las principales limitantes sanitarias a la producción de poroto en la región del noroeste argentino (NOA). El objetivo del presente trabajo es presentar una nueva variedad de poroto negro, con alto nivel de tolerancia a estas virosis y capaz de reemplazar a las variedades comerciales difundidas en el NOA. En 1995 se introdujeron ocho líneas avanzadas de poroto negro desde el Centro Internacional de Agricultura Tropical (CIAT), que se probaron con los testigos comerciales NAG 12, Camilo, TUC 390 y TUC 500. Entre 1997 y 2000, estas líneas fueron evaluadas en ensayos comparativos de rendimientos (ECR) en las localidades de Monte Redondo y La Cocha (Tucumán), y Campichuelo (Salta). El diseño experimental en todos los ensayos de campo fue el de bloques completos al azar. Se hicieron test de análisis de varianza individual y pruebas de homogeneidad de varianzas mediante el test de Levenne. Cada parcela estuvo formada por cuatro líneas de 6 m de largo, distanciadas a 0,70 m y con una densidad comercial de 16 semillas/m. Los parámetros de evaluación fueron: a) durante el ciclo: tolerancia a las virosis y adaptación, tanto vegetativa como reproductiva (escala 1 a 9, CIAT) y b) en cosecha: rendimientos (kg grano limpio/ha) y calidad comercial. El genotipo TUC 510 produjo los mayores rendimientos (media=1470 kg/ha) generales y particulares por localidad evaluada. Además se destacó por su tolerancia (3,0) a las virosis del mosaico dorado y mosaico enano del poroto y capacidad de adaptación (3,0) a las condiciones ambientales evaluadas. Estas características fundamentaron la inscripción ante el Instituto Nacional de Semillas (INASE) de TUC 510, como una nueva variedad de poroto negro.In the warmer areas of Northwestern Argentina, Bean golden mosaic virus (BGMV) and Bean dwarf mosaic virus (BDMV) constitute the main sanitary constraints to production. The objective of this work is to present a new cultivar of black dry edible bean that has high levels of tolerance to these viruses and that could replace commercial varieties already grown in Northwestern Argentina. In 1995, eight advanced lines of black dry edible bean from the International Center for Tropical Agriculture (CIAT) were introduced. These were tested in comparison with commercial controls NAG 12, Camilo, TUC 390 and TUC 500. From 1997 to 2000, the lines were evaluated in yield comparative trials in Monte Redondo and La Cocha (Tucuman) and Campichuelo (Salta). In every trial, a randomized complete block design was applied, and tests of individual variance and homogeneity of variance (Levenne''s test) were conducted. Each plot consisted of four six-meter-long lines, set at 0,70 m away from each other, with a plant density of 16 plants per meter. Assessment parameters were: a) during the whole cycle: virus complex tolerance and vegetative and reproductive adaptation, and b) during harvest: yield (kg/ ha) and commercial quality. Genotype TUC 510 was found to exhibit the highest yield levels, both general and particular in each location, with an average rate of 1470 kg/ha. Moreover, this cultivar was outstanding for its tolerance to BGMV and BDMV (3.0) and its capacity of adaptation (3.0) to the evaluated environmental conditions. These features justify the official registration of TUC 500 as a new variety of black dry edible bean.', '{doaj,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9d61731b-3612-4ff4-b23e-62486c51ad1c', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Identification of Fungicide Combinations for Overcoming Plasmopara viticola and Botrytis cinerea Fungicide Resistance', 'Zhang J, Gelain J, Schnabel G, Mallawarachchi S, Wang H, Mulgaonkar N, Karthikeyan R, Fernando S', 2023, 'Microorganisms', '10.3390/microorganisms11122966', 'https://doi.org/10.3390/microorganisms11122966', 'https://europepmc.org/articles/PMC10746041?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Fungal diseases, including downy mildew (caused by Plasmopara viticola) and gray mold (caused by Botrytis cinerea), significantly impact the marketable yield of grapes produced worldwide. Cytochrome b of the mitochondrial respiratory chain of these two fungi is a key target for Quinone outside inhibitor (QoI)-based fungicide development. Since the mode of action (MOA) of QoI fungicides is restricted to a single site, the extensive usage of these fungicides has resulted in fungicide resistance. The use of fungicide combinations with multiple targets is an effective way to counter and slow down the development of fungicide resistance. Due to the high cost of in planta trials, in silico techniques can be used for the rapid screening of potential fungicides. In this study, a combination of in silico simulations that include Schrödinger Glide docking, molecular dynamics, and Molecular Mechanism-Generalized Born Surface Area calculation were used to screen the most potent QoI and non-QoI-based fungicide combinations to wild-type, G143A-mutated, F129L-mutated, and double-mutated versions that had both G143A and F129L mutations of fungal cytochrome b. In silico docking studies indicated that mandestrobin, famoxadone, captan, and thiram have a high affinity toward WT cytochrome b of Botrytis cinerea. Although the QoIs mandestrobin and famoxadone were effective for WT based on in vitro results, they were not broadly effective against G143A-mutated isolates. Famoxadone was only effective against one isolate with G143A-mutated cytochrome b. The non-QoI fungicides thiram and captan were effective against both WT and isolates with G143A-mutated cytochrome b. Follow-up in silico docking and molecular dynamics studies suggested that fungicide combinations consisting of famoxadone, mandestrobin, fenamidone, and thiram should be considered in field testing targeting Plasmopara viticola and Botrytis cinerea fungicide resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a6da5b6a-ecb3-433c-bdfd-8499dee66827', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Identification of Fungicide Combinations Targeting Plasmopara viticola and Botrytis cinerea Fungicide Resistance Using Machine Learning', 'Zhang J, Fernando SD', 2023, 'Microorganisms', '10.3390/microorganisms11051341', 'https://doi.org/10.3390/microorganisms11051341', 'https://europepmc.org/articles/PMC10221559?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Downy mildew (caused by Plasmopara viticola) and gray mold (caused by Botrytis cinerea) are fungal diseases that significantly impact grape production globally. Cytochrome b plays a significant role in the mitochondrial respiratory chain of the two fungi that cause these diseases and is a key target for quinone outside inhibitor (QoI)-based fungicide development. Since the mode of action (MOA) of QoI fungicides is restricted to a single active site, the risk of developing resistance to these fungicides is deemed high. Consequently, using a combination of fungicides is considered an effective way to reduce the development of QoI resistance. Currently, there is little information available to help in the selection of appropriate fungicides. This study used a combination of in silico simulations and quantitative structure-activity relationship (QSAR) machine learning algorithms to screen the most potent QoI-based fungicide combinations for wild-type (WT) and the G143A mutation of fungal cytochrome b. Based on in silico studies, mandestrobin emerged as the top binder for both WT Plasmopara viticola and WT Botrytis cinerea cytochrome b. Famoxadone appeared to be a versatile binder for G143A-mutated cytochrome b of both Plasmopara viticola and Botrytis cinerea. Thiram emerged as a reasonable, low-risk non-QoI fungicide that works on WT and G143A-mutated versions of both fungi. QSAR analysis revealed fenpropidin, fenoxanil, and ethaboxam non-QoIs to have a high affinity for G143A-mutated cytochrome b of Plasmopara viticola and Botrytis cinerea. Above-QoI and non-QoI fungicides can be considered for field studies in a fungicide management program against Plasmopara viticola- and Botrytis cinerea-based fungal infections.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c3d5bbbc-285a-44e8-8775-b5d78fcf7a74', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Importance of chemical polymorphism in modern crop protection', 'Olenik B, Keil B, Jeschke P', 2022, 'Pest management science', '10.1002/ps.6919', 'https://doi.org/10.1002/ps.6919', 'https://europepmc.org/articles/PMC9321084?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'The development of agrochemical products faces many scientific challenges. After selection of an agrochemical candidate its properties will have to be optimized to guarantee best bioavailability and stability under many different conditions in various formulation types. These challenges are influenced by the solid-state properties of the active ingredient and this makes the selection of an optimized solid-state form of modern agrochemicals at early development stages very valuable. The increasing awareness of the solid state of agrochemicals is reflected in the importance of polymorphism patent applications, which may enhance the risk of litigations. This review aims to present strategies for the solid-form selection process of agrochemical development candidates. It introduces the different techniques for crystallization and analytics and demonstrates the influence of the solid state on different formulation types. © 2022 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d26bbcb1-bc61-41fb-b51d-875f114618eb', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Important wheat diseases in the US and their management in the 21st century', 'Singh J, Chhabra B, Raza A, Yang SH, Sandhu KS', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.1010191', 'https://doi.org/10.3389/fpls.2022.1010191', 'https://europepmc.org/articles/PMC9877539?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Wheat is a crop of historical significance, as it marks the turning point of human civilization 10,000 years ago with its domestication. Due to the rapid increase in population, wheat production needs to be increased by 50% by 2050 and this growth will be mainly based on yield increases, as there is strong competition for scarce productive arable land from other sectors. This increasing demand can be further achieved using sustainable approaches including integrated disease pest management, adaption to warmer climates, less use of water resources and increased frequency of abiotic stress tolerances. Out of 200 diseases of wheat, 50 cause economic losses and are widely distributed. Each year, about 20% of wheat is lost due to diseases. Some major wheat diseases are rusts, smut, tan spot, spot blotch, fusarium head blight, common root rot, septoria blotch, powdery mildew, blast, and several viral, nematode, and bacterial diseases. These diseases badly impact the yield and cause mortality of the plants. This review focuses on important diseases of the wheat present in the United States, with comprehensive information of causal organism, economic damage, symptoms and host range, favorable conditions, and disease management strategies. Furthermore, major genetic and breeding efforts to control and manage these diseases are discussed. A detailed description of all the QTLs, genes reported and cloned for these diseases are provided in this review. This study will be of utmost importance to wheat breeding programs throughout the world to breed for resistance under changing environmental conditions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8f4cbd2f-ec36-48cb-a997-05f0593e43c9', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Inhibitory Effect and Control Efficacy of Picoxystrobin against Neopestalotiopsis clavispora, Causing Vine Tea Leaf Blight', 'Zehua Zhou, Yicai Wang, Yabing Duan, Yannan He, Shuang Liu, Yan Chen, Wucheng Deng, Chunping Li', 2023, 'Agronomy', '10.3390/agronomy13051340', 'https://doi.org/10.3390/agronomy13051340', 'https://www.mdpi.com/2073-4395/13/5/1340', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Vine tea (Ampelopsis grossedentata) is a traditional herb widely consumed in southwestern China that possesses paramount potential for human health. In 2021, the outbreak of typical leaf blight disease was observed in almost all vine tea plantations in Zhangjiajie of Hunan province, resulting in significant economic losses of vine tea production. In this study, we identified Neopestalotiopsis clavispora as the causal agent of vine tea leaf blight via its morphological characteristics and molecular identification. The sensitivity distribution of N. clavispora isolates to picoxystrobin were determined based on mycelial growth and spore germination inhibition assays. The EC50 values for mycelial growth ranged from 0.0062 to 0.0658 µg/mL, with a mean of 0.0282 ± 0.0148 µg/mL. The EC50 values for spore germination ranged from 0.0014 to 0.0099 µg/mL, and the mean value was 0.0048 ± 0.0022 µg/mL. Picoxystrobin increased fungal cell membrane permeability, but inhibited fungal ATP biosynthesis. Moreover, picoxystrobin exhibited good in planta control efficacy on vine tea leaves. Three picoxystrobin-resistant mutants were obtained in the current study, but no mutations were detected in the N. clavispora Cytb gene. Competitive ability assays showed that the conidium production and pathogenicity of all picoxystrobin-resistant mutants decreased as compared to their progenitors, indicating that picoxystrobin-resistant mutants suffer fitness penalty. These findings provide important evidence for picoxystrobin in vine tea leaf blight management and increase understanding of the resistance mechanism of picoxystrobin against N. clavispora.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4a6fd03c-ec8f-42f8-93fc-88806a0b5eb0', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'How Melatonin Affects Plant Growth and the Associated Microbiota', 'Gamalero E, Glick BR', 2025, 'Biology', '10.3390/biology14040371', 'https://doi.org/10.3390/biology14040371', 'https://europepmc.org/articles/PMC12025164?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Melatonin is found in all classes of living organisms. In particular, in plants melatonin acts as an antioxidant that helps plants deal with both biotic and abiotic stress. In plants, melatonin improves seed germination, fruit ripening, photosynthesis, biomass production, circadian rhythm, membrane integrity, root development, leaf senescence, osmoregulation, and stress modulation. Melatonin concentrations vary enormously in different plants, different plant growth stages, different plant organs, and both the season and time of day that a plant is harvested. In addition, melatonin promotes root growth and development, prevents leaf senescence, promotes flowering and fruit ripening, promotes lateral root formation, stimulates gene expression of enzymes involved in photosynthesis, and protects plants from phytopathogen attack. Moreover, melatonin produced by soil bacteria can affect plant tolerance and health; in turn, melatonin synthesized by plants can influence the soil and rhizosphere microbiome. Finally, very recent literature indicates that melatonin can directly and positively affect the functioning of other soil bacteria.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5578eb26-48b7-423e-b1d7-182b207d3b92', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Modeling the relationship between estimated fungicide use and disease-associated yield losses of soybean in the United States I: Foliar fungicides vs foliar diseases', 'Bandara AY, Weerasooriya DK, Conley SP, Bradley CA, Allen TW, Esker PD', 2020, 'PloS one', '10.1371/journal.pone.0234390', 'https://doi.org/10.1371/journal.pone.0234390', 'https://europepmc.org/articles/PMC7289349?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Fungicide use in the United States to manage soybean diseases has increased in recent years. The ability of fungicides to reduce disease-associated yield losses varies greatly depending on multiple factors. Nonetheless, historical data are useful to understand the broad sense and long-term trends related to fungicide use practices. In the current study, the relationship between estimated soybean yield losses due to selected foliar diseases and foliar fungicide use was investigated using annual data from 28 soybean growing states over the period of 2005 to 2015. For national and regional (southern and northern United States) scale data, mixed effects modeling was performed considering fungicide use as a fixed and state and year as random factors to generate generalized R2 values for marginal (R2GLMM(m); contains only fixed effects) and conditional (R2GLMM(c); contains fixed and random effects) models. Similar analyses were performed considering soybean production data to see how fungicide use affected production. Analyses at both national and regional scales showed that R2GLMM(m) values were significantly smaller compared to R2GLMM(c) values. The large difference between R2 values for conditional and marginal models indicated that the variation of yield loss as well as production were predominantly explained by the state and year rather than the fungicide use, revealing the general lack of fit between fungicide use and yield loss/production at national and regional scales. Therefore, regression models were fitted across states and years to examine their importance in combination with fungicide use on yield loss or yield. In the majority of cases, the relationship was nonsignificant. However, the relationship between soybean yield and fungicide use was significant and positive for majority of the years in the study. Results suggest that foliar fungicides conferred yield benefits in most of the years in the study. Furthermore, the year-dependent usefulness of foliar fungicides in mitigating soybean yield losses suggested the possible influence of temporally fluctuating abiotic factors on the effectiveness of foliar fungicides and/or target disease occurrence and associated loss magnitudes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('274ef432-cd11-43f9-813f-872a321d14cb', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Overcoming Global Antifungal Challenges: Medical and Agricultural Aspects', 'Galgóczy L', 2025, 'ACS bio & med chem Au', '10.1021/acsbiomedchemau.5c00103', 'https://doi.org/10.1021/acsbiomedchemau.5c00103', 'https://europepmc.org/articles/PMC12371507?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'The prevalence of fungal infections and contamination has increased alarmingly over the past decade, posing a significant threat to human health and the food supply and negatively affecting welfare. This escalating concern is primarily attributed to the lack of safe, effective, and widely available antifungal agents; the increasing spread of (multi)-drug resistance to conventional antifungal treatments; and substantial epidemiological shifts in fungal pathogens. Decision-making bodies have recognized the urgency of this situation and prioritized efforts to address and mitigate the spread of drug-resistant fungal infections by developing and implementing innovative antifungal strategies, including using drug combinations, designing fundamentally new antifungal compounds with fungus-specific mechanisms of action and a minimal risk of resistance development, drug repurposing, and exploring alternative approaches, such as biomolecules, nanotechnology, and biological control. This review aims to provide a comprehensive overview of the current challenges associated with fungal infections in medicine and agriculture as well as the latest advancements and potential solutions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b4c4b44b-cb5f-45cd-8ad5-ee3caf2ed2fe', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Overview and Management of the Most Common Eukaryotic Diseases of Flax (Linum usitatissimum)', 'Moyse J, Lecomte S, Marcou S, Mongelard G, Gutierrez L, Höfte M', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12152811', 'https://doi.org/10.3390/plants12152811', 'https://europepmc.org/articles/PMC10420651?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Flax is an important crop cultivated for its seeds and fibers. It is widely grown in temperate regions, with an increase in cultivation areas for seed production (linseed) in the past 50 years and for fiber production (fiber flax) in the last decade. Among fiber-producing crops, fiber flax is the most valuable species. Linseed is the highest omega-3 oleaginous crop, and its consumption provides several benefits for animal and human health. However, flax production is impacted by various abiotic and biotic factors that affect yield and quality. Among biotic factors, eukaryotic diseases pose a significant threat to both seed production and fiber quality, which highlights the economic importance of controlling these diseases. This review focuses on the major eukaryotic diseases that affect flax in the field, describing the pathogens, their transmission modes and the associated plant symptoms. Moreover, this article aims to identify the challenges in disease management and provide future perspectives to overcome these biotic stresses in flax cultivation. By emphasizing the key diseases and their management, this review can aid in promoting sustainable and profitable flax production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8a8246f6-442e-494e-a463-5d1844ac7fb9', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Physiological Effects of Microbial Biocontrol Agents in the Maize Phyllosphere', 'Vanacore MFG, Sartori M, Giordanino F, Barros G, Nesci A, García D', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12244082', 'https://doi.org/10.3390/plants12244082', 'https://europepmc.org/articles/PMC10747270?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'In a world with constant population growth, and in the context of climate change, the need to supply the demand of safe crops has stimulated an interest in ecological products that can increase agricultural productivity. This implies the use of beneficial organisms and natural products to improve crop performance and control pests and diseases, replacing chemical compounds that can affect the environment and human health. Microbial biological control agents (MBCAs) interact with pathogens directly or by inducing a physiological state of resistance in the plant. This involves several mechanisms, like interference with phytohormone pathways and priming defensive compounds. In Argentina, one of the world''s main maize exporters, yield is restricted by several limitations, including foliar diseases such as common rust and northern corn leaf blight (NCLB). Here, we discuss the impact of pathogen infection on important food crops and MBCA interactions with the plant''s immune system, and its biochemical indicators such as phytohormones, reactive oxygen species, phenolic compounds and lytic enzymes, focused mainly on the maize-NCLB pathosystem. MBCA could be integrated into disease management as a mechanism to improve the plant''s inducible defences against foliar diseases. However, there is still much to elucidate regarding plant responses when exposed to hemibiotrophic pathogens.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ce54d2b-c88e-427f-9f74-47612e26f3b2', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Factors Impacting the Use of an Allelochemical Lure in Pome Fruit for Cydia pomonella (L.) Monitoring', 'Knight AL, Preti M, Basoalto E', 2025, 'Insects', '10.3390/insects16020172', 'https://doi.org/10.3390/insects16020172', 'https://europepmc.org/articles/PMC11856869?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'A four-component blend comprising pear ester, DMNT, linalool oxide, and acetic acid (CM4K) was identified as a potent allelochemical lure for both sexes of codling moth (CM), Cydia pomonella (L.). Studies conducted from 2020 to 2022 in Washington State (USA) examined factors which could impact the lure''s relative performance. The CM4K lure was effective across a range of mating disruption programs and was equally attractive in monitoring wild and sterile CM. The lure remained attractive for at least 10 weeks. Total catch in traps baited with the CM4K was significantly less impacted than a sex pheromone lure located near mating disruption dispensers and female catches were largely unaffected. Traps with the CM4K lure caught significantly more females and fewer males when placed near clusters of fruits in a trellised orchard. Two factors were found to significantly impact the relative performance of the CM4K to sex pheromone lures: the CM4K lure was only equivalent to sex pheromone lures in pear MD orchards, and apple and pear orchards with vigorous weed growth. This is the first report of a monitoring lure for a tortricid moth being negatively impacted by the background odor of non-host weed species present within an orchard.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bb1ea2cc-eb3c-4609-a83b-0ae2daee7a64', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Pyrenophora teres: Taxonomy, Morphology, Interaction With Barley, and Mode of Control', 'Backes A, Guerriero G, Ait Barka E, Jacquard C', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.614951', 'https://doi.org/10.3389/fpls.2021.614951', 'https://europepmc.org/articles/PMC8055952?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Net blotch, induced by the ascomycete Pyrenophora teres, has become among the most important disease of barley (Hordeum vulgare L.). Easily recognizable by brown reticulated stripes on the sensitive barley leaves, net blotch reduces the yield by up to 40% and decreases seed quality. The life cycle, the mode of dispersion and the development of the pathogen, allow a quick contamination of the host. Crop residues, seeds, and wild grass species are the inoculum sources to spread the disease. The interaction between the barley plant and the fungus is complex and involves physiological changes with the emergence of symptoms on barley and genetic changes including the modulation of different genes involved in the defense pathways. The genes of net blotch resistance have been identified and their localizations are distributed on seven barley chromosomes. Considering the importance of this disease, several management approaches have been performed to control net blotch. One of them is the use of beneficial bacteria colonizing the rhizosphere, collectively referred to as Plant Growth Promoting Rhizobacteria. Several studies have reported the protective role of these bacteria and their metabolites against potential pathogens. Based on the available data, we expose a comprehensive review of Pyrenophora teres including its morphology, interaction with the host plant and means of control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c99dda00-a4f3-45fe-8f75-c3fca998546c', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Resistance risk and molecular mechanism associated with resistance to picoxystrobin in Colletotrichum truncatum and Colletotrichum gloeosporioides', 'Niu-niu SHI, Jin-pan LIAN, De-zhu QIU, Fu-ru CHEN, Yi-xin DU', 2023, 'Journal of Integrative Agriculture', '10.1016/j.jia.2023.07.037', 'https://doi.org/10.1016/j.jia.2023.07.037', 'http://www.sciencedirect.com/science/article/pii/S2095311923002605', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Anthracnose, caused by Colletotrichum truncatum and C. gloeosporioides, is amongst the most serious diseases of soybean in China. Picoxystrobin, a quinone outside inhibitor fungicide, is commonly used for the control of anthracnose. Its resistance risk and mechanism in C. truncatum and C. gloeosporioides are unclear. In this study, the sensitivities of 128 C. truncatum and 121 C. gloeosporioides isolates to picoxystrobin were investigated, and unimodal distributions were observed with average EC50 values of 0.7740 and 1.1561 μg mL−1, respectively. Eleven picoxystrobin-resistant mutants of C. truncatum and six mutants of C. gloeosporioides were acquired, with EC50 values varying from 5.40–152.96 and 13.53–28.30 μg mL−1, respectively. Compared to the parental isolates, mutants showed similar or higher relative fitness in conidial production and germination, and pathogenicity. Collectively, the resistance risk of C. truncatum and C. gloeosporioides to picoxystrobin is moderate to high. There was positive cross-resistance between picoxystrobin and pyraclostrobin, but not between picoxystrobin and fluazinam, difenoconazole, or propiconazole. The G143S mutation in Cyt b protein was detected in seven high-resistant mutants of C. truncatum (RF>100), and G137R occurred in four moderate-resistant mutants (RF<50). Contrastingly, there were no point mutations in Cyt b of any C. gloeosporioides mutants. Molecular docking confirmed that two mutations conferred different resistance levels to picoxystrobin. Under greenhouse trials, picoxystrobin did not control mutants with the G143S mutation, those bearing G137R or no point mutation were somewhat controlled, but at a lower level compared to wild-type isolates. These results showed that integrated management strategies should be implemented to preserve fungicide effectiveness.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('70b780f9-62b6-4078-80ae-02e8eb080999', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Role of Fungicide Applications on the Integrated Management of Wheat Stripe Rust', 'Carmona M, Sautua F, Pérez-Hérnandez O, Reis EM', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00733', 'https://doi.org/10.3389/fpls.2020.00733', 'https://europepmc.org/articles/PMC7296138?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'First described in Europe in 1777, stripe rust (SR) caused by Puccinia striiformis Westend. f. sp. tritici Erikss (Pst) is one of the most important and destructive diseases of wheat worldwide. Until 2000, SR was mainly endemic to cooler regions, but since then, new aggressive strains have emerged, spread intercontinentally, and caused severe epidemics in warmer regions across the world. This has put SR as a disease that poses a threat to the world food security. At present, the preferred strategy for control of SR is the access to wheat cultivars with adequate levels of SR resistance. However, wheat breeding programs are not sufficiently advanced to cope with the recently emerged Pst strains. Under this scenario, foliar fungicide applications have become an important component of SR management, but information on the effects of fungicide applications on SR control and wheat cultivar yield response is scarce. This review seeks to provide an overview of the impact and role of fungicides on SR management. With focus on wheat management in the major wheat-growing regions of the world, the review addresses: (a) the efficacy of different fungicide active ingredients, optimal fungicide timing and number of applications in controlling SR, and (b) the impact of fungicide on wheat grain yield response. Inclusion of fungicides in an integrated crop management approach is discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('10ebd716-988c-427a-974d-9831edb63015', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'The continuing significance of chiral agrochemicals', 'Jeschke P', 2025, 'Pest management science', '10.1002/ps.8655', 'https://doi.org/10.1002/ps.8655', 'https://europepmc.org/articles/PMC11906909?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Chemical crop protection is one of the most cost-effective methods for agriculture, as crop failures can be prevented, and sustainable growth can be enabled regardless of the seasons. Agricultural production must be significantly increased in the future to meet the food needs of a growing world population. However, the continued loss of established active ingredients due to consumer perceptions, changing needs of farmers and ever-changing regulatory requirements is higher than annually new active ingredients introduced to the market. The development of innovative active ingredients is therefore essential to continuously improve the selectivity, efficacy and favorable environmental profile of agrochemicals. Molecules with stereogenic centers can be considered here, as they often have different properties than non-chiral molecules. Natural products and their congeners are still a valuable source of inspiration for chiral agrochemicals. However, only a few novel chiral agrochemicals are currently produced on an industrial scale as pure stereoisomers or in enriched form. As of 2018, around 43% of the 35 chiral products introduced to the market (herbicides, fungicides, insecticides, acaricides, and nematicides) contain one or more stereogenic centers in the molecule, and almost 69% of them have been marketed as racemic mixtures of enantiomers or stereoisomers. Surprisingly, the proportion of chiral agrochemicals is in the same order of magnitude as in the time frame from 2007 to 2017 with around 42%, respectively. This report therefore provides an overview of the continued importance of chiral agrochemicals brought to market in the last 6 years and describes the inherent related challenges of modern agrochemicals through the management of key aspects arising from innovative crop protection products. © 2025 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('090dc936-77e5-44fa-8a21-4912eb3062a4', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Integrative genomic analyses reveal candidate genes for the Ur-3 and Ur-7 rust resistance loci in common bean', 'Soler-Garzón A, Valentini G, Pastor-Corrales M, He R, Miklas PN', 2026, 'The plant genome', '10.1002/tpg2.70253', 'https://doi.org/10.1002/tpg2.70253', 'https://europepmc.org/articles/PMC13492622?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'Bean rust, caused by Uromyces appendiculatus, severely limits the productivity of common bean (Phaseolus vulgaris L.), an essential source of protein and micronutrients in human diets worldwide. Durable disease management relies primarily on host resistance; however, the molecular architecture of several key rust resistance loci remains unresolved. We sought to characterize the genomic structure of the Ur-3 and Ur-7 loci and develop associated molecular markers. An integrative genomic framework combining high-resolution long-read genome assemblies, recombinant inbred line populations, and single-nucleotide polymorphism-based and k-mer-based genome-wide association studies was used to fine-map both loci. Extensive structural variation was revealed for the Ur-3 locus at the distal end of chromosome Pv11, whereas Ur-7 localized to a low-recombination pericentromeric region of the same chromosome. A coiled-coil nucleotide-binding leucine-rich repeat gene embedded within an NB-ARC-rich cluster was identified as the most likely candidate underlying Ur-3 (Pv11: 50,205,868-50,209,452 bases; USDA Rattler reference). In contrast, the refined Ur-7 interval contained a toll/interleukin-1 receptor NLR gene as the leading candidate (Pv11: 36,604,755-36,611,252; UI 111 reference). Gene-based markers developed from these candidates showed complete correspondence with rust phenotypes. Marker-assisted selection for Ur-3 and Ur-7 will contribute to the development of durable rust resistance against the highly variable bean rust pathogen U. appendiculatus.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('405ab2ac-bd22-4d93-b1ca-c6b52661f0f3', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'White Mold: A Global Threat to Crops and Key Strategies for Its Sustainable Management', 'Hossain MM, Sultana F, Rubayet MT, Khan S, Mostafa M, Mishu NJ, Sabbir MAA, Akter N', 2024, 'Microorganisms', '10.3390/microorganisms13010004', 'https://doi.org/10.3390/microorganisms13010004', 'https://europepmc.org/articles/PMC11767943?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'White mold, caused by the fungal pathogen Sclerotinia sclerotiorum (Lib.) de Bary, is a significant biotic stress impacting horticultural and field crops worldwide. This disease causes plants to wilt and ultimately die, resulting in considerable yield losses. This monocyclic disease progresses through a single infection cycle involving basal infections from myceliogenically germinated sclerotia or aerial infections initiated by ascospores from carpogenically germinated sclerotia. The pathogen has a homothallic mating system with a weak population structure. Relatively cool temperatures and extended wetness are typical conditions for spreading the disease. Each stage of infection triggers a cascade of molecular and physiological events that underpin defense responses against S. sclerotiorum. Molecular markers can help rapid diagnosis of this disease in plants. Effective management strategies encompass altering the crop microclimate, applying fungicides, reducing inoculum sources, and developing resistant plant varieties. Integrated approaches combining those strategies often yield the best results. This review discusses the latest insights into the biology, epidemiology, infection mechanisms, and early detection of white mold. This review also aims to provide comprehensive guidelines for sustainable management of this destructive disease while reducing the use of excessive pesticides in crop fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b970aaca-c6d1-430c-9afd-b28d7bf87bb0', 'b2a7b5cd-1326-473f-b21c-f72448672845', 'Winter Wheat Yield Response to Plant Density as a Function of Yield Environment and Tillering Potential: A Review and Field Studies', 'Bastos LM, Carciochi W, Lollato RP, Jaenisch BR, Rezende CR, Schwalbert R, Vara Prasad PV, Zhang G', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00054', 'https://doi.org/10.3389/fpls.2020.00054', 'https://europepmc.org/articles/PMC7066254?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Wheat (Triticum aestivum L.) grain yield response to plant density is inconsistent, and the mechanisms driving this response are unclear. A better understanding of the factors governing this relationship could improve plant density recommendations according to specific environmental and genetics characteristics. Therefore, the aims of this paper were to: i) execute a synthesis-analysis of existing literature related to yield-plant density relationship to provide an indication of the need for different agronomic optimum plant density (AOPD) in different yield environments (YEs), and ii) explore a data set of field research studies conducted in Kansas (USA) on yield response to plant density to determine the AOPD at different YEs, evaluate the effect of tillering potential (TP) on the AOPD, and explain changes in AOPD via variations in wheat yield components. Major findings of this study are: i) the synthesis-analysis portrayed new insights of differences in AOPD at varying YEs, reducing the AOPD as the attainable yield increases (with AOPD moving from 397 pl m-2 for the low YE to 191 pl m-2 for the high YE); ii) the field dataset confirmed the trend observed in the synthesis-analysis but expanded on the physiological mechanisms underpinning the yield response to plant density for wheat, mainly highlighting the following points: a) high TP reduces the AOPD mainly in high and low YEs, b) at canopy-scale, both final number of heads and kernels per square meter were the main factors improving yield response to plant density under high TP, c) under varying YEs, at per-plant-scale, a compensation between heads per plant and kernels per head was the main factor contributing to yield with different TP.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('deb12c89-9976-4b60-b0ba-b4d3a338e1fa', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'A comprehensive review of new pesticides developed between 2015 and 2025', 'Umetsu N, Shirai Y', 2026, 'Journal of pesticide science', '10.1584/jpestics.d25-078', 'https://doi.org/10.1584/jpestics.d25-078', 'https://europepmc.org/articles/PMC13021355?pdf=render', NULL, NULL, 43, NULL, 'other', 1, 'cc by-nc-nd', 'General trends and strategies for the development of new pesticides are summarized. From 2015 to 2025, 156 chemical pesticides were launched or are under development: 47 fungicides, 54 insecticides/acaricides, 9 nematicides, and 46 herbicides. Most are safe to humans and environmentally friendly. The most developed fungicides are succinate dehydrogenase inhibitors, quinone outside inhibitors, quinone inside inhibitors, and demethylation inhibitors. The general trend of insecticide development is in the progress of four major classes of insecticides: nicotinic insecticides, diamide insecticides, GABA-gated chloride channel allosteric modulators, and insect behavior or growth regulators. Due to the development of resistance to fungicides and insecticides with existing modes of action, many compounds possessing various novel modes of action have been developed. Peptide pesticides and RNAi-based insecticides have been put into practical use. Although no herbicides with novel modes of action appeared for approximately 30 years before 2018, since then eight herbicides with five novel modes of action have emerged, including those for existing herbicides. The development of useful acaricides and nematicides is also progressing.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('71847f91-8ed5-480d-bee7-978b3ca9b43f', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'A Microplate-Based Assay to Determine DMI Fungicide Sensitivity of Cercospora beticola', 'Austin K. Lien, Ashok K. Chanda', 2026, 'PhytoFrontiers', '10.1094/PHYTOFR-07-25-0063-R', 'https://doi.org/10.1094/PHYTOFR-07-25-0063-R', 'https://apsjournals.apsnet.org/doi/10.1094/PHYTOFR-07-25-0063-R', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Cercospora beticola, the causal agent of Cercospora leaf spot in sugar beet, is a major pathogen that significantly impacts crop productivity. The emergence and spread of resistance to demethylation inhibitor (DMI) fungicides further complicate effective disease management. Current methods for monitoring DMI sensitivity, such as radial growth and molecular assays, are limited by low-throughput or binary detection of known resistance alleles, respectively. In this study, we developed and validated a high-throughput microplate-based assay to determine DMI fungicide sensitivity in C. beticola using optical density measurements. The assay was optimized for media type, inoculum preparation, wavelength, fungicide concentration gradients, and incubation time. Relative effective fungicide concentrations that inhibit 50% of growth (EC50) were determined to provide quantitative assessment of fungicide sensitivity to tetraconazole, prothioconazole, difenoconazole, and mefentrifluconazole. The assay demonstrated consistency across two microplate brands and strong correlation with CbCyp51 haplotypes associated with DMI resistance. Our results show that the microplate assay is an efficient tool for monitoring quantitative fungicide sensitivity in C. beticola, offering improved throughput compared with the conventional Petri plate method. [Figure: see text] Copyright © 2026 The Author(s). This is an open access article distributed under the CC BY-NC-ND 4.0 International license.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b8267f0a-71a9-474f-b8fd-7de94d6d8daf', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Air seeding forage crops', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-733', 'https://open.alberta.ca/dataset/243db447-1492-460e-8250-ca324b673d37/resource/13a432d4-9c90-40b4-bd30-785fcf2d0e14/download/733-airseeding-forage-crops-afmrc.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Presents research results assessing the effectiveness of three air seeders when seeding grasses and to determine what, if any, modifications should be made to improve their performance.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e85caf65-f8c5-4ae2-9d33-72cc3d96418e', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Algae and Cyanobacteria Fatty Acids and Bioactive Metabolites: Natural Antifungal Alternative Against Fusarium sp', 'López-Arellanes ME, López-Pacheco LD, Elizondo-Luevano JH, González-Meza GM', 2025, 'Microorganisms', '10.3390/microorganisms13020439', 'https://doi.org/10.3390/microorganisms13020439', 'https://europepmc.org/articles/PMC11858688?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'Fungal diseases caused by Fusarium spp. significantly threaten food security and sustainable agriculture. One of the traditional strategies for eradicating Fusarium spp. incidents is the use of chemical and synthetic fungicides. The excessive use of these products generates environmental damage and has negative effects on crop yield. It puts plants in stressful conditions, kills the natural soil microbiome, and makes phytopathogenic fungi resistant. Finally, it also causes health problems in farmers. This drives the search for and selection of natural alternatives, such as bio-fungicides. Among natural products, algae and cyanobacteria are promising sources of antifungal bio-compounds. These organisms can synthesize different bioactive molecules, such as fatty acids, phenolic acids, and some volatile organic compounds with antifungal activity, which can damage the fungal cell membrane that surrounds the hyphae and spores, either by solubilization or by making them porous and disrupted. Research in this area is still developing, but significant progress has been made in the identification of the compounds with potential for controlling this important pathogen. Therefore, this review focuses on the knowledge about the mechanisms of action of the fatty acids from macroalgae, microalgae, and cyanobacteria as principal biomolecules with antifungal activity, as well as on the benefits and challenges of applying these natural metabolites against Fusarium spp. to achieve sustainable agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b753883c-ab94-4f39-93d8-27c94f65f125', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Antifungal alternation can be beneficial for durability but at the cost of generalist resistance', 'Ballu A, Despréaux P, Duplaix C, Dérédec A, Carpentier F, Walker AS', 2023, 'Communications biology', '10.1038/s42003-023-04550-6', 'https://doi.org/10.1038/s42003-023-04550-6', 'https://europepmc.org/articles/PMC9935548?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'The evolution of resistance to pesticides is a major burden in agriculture. Resistance management involves maximizing selection pressure heterogeneity, particularly by combining active ingredients with different modes of action. We tested the hypothesis that alternation may delay the build-up of resistance not only by spreading selection pressure over longer periods, but also by decreasing the rate of evolution of resistance to alternated fungicides, by applying an experimental evolution approach to the economically important crop pathogen Zymoseptoria tritici. Our results show that alternation is either neutral or slows the overall resistance evolution rate, relative to continuous fungicide use, but results in higher levels of generalism in evolved lines. We demonstrate that the nature of the fungicides, and therefore their relative intrinsic risk of resistance may underly this trade-off, more so than the number of fungicides and the rhythm of alternation. This trade-off is also dynamic over the course of resistance evolution. These findings open up new possibilities for tailoring resistance management effectively while optimizing interplay between alternation components.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0573b7b-506c-4668-b805-15abf22031e6', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Ascochyta blight in North Dakota field pea: the pathogen complex and its fungicide sensitivity', 'Dimitri L. Fonseka, Samuel G. Markell, Marcio L. Zaccaron, Malaika K. Ebert, Julie S. Pasche', 2023, 'Frontiers in Plant Science', '10.3389/fpls.2023.1165269', 'https://doi.org/10.3389/fpls.2023.1165269', 'https://www.frontiersin.org/articles/10.3389/fpls.2023.1165269/full', NULL, NULL, 16, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Worldwide, Ascochyta blight is caused by a complex of host-specific fungal pathogens, including Ascochyta pisi, Didymella pinodes, and Didymella pinodella. The application of foliar fungicides is often necessary for disease management, but a better understanding of pathogen prevalence, aggressiveness, and fungicide sensitivity is needed to optimize control. Leaf and stem samples were obtained from 56 field pea production fields in 14 counties in North Dakota from 2017 to 2020 and isolates were collected from lesions characteristic of Ascochyta blight. Based on fungal characteristics and sequencing the ITS1-5.8S-ITS2 region, 73% of isolates were confirmed to be D. pinodes (n = 177) and 27% were A. pisi (n = 65). Across pathogens, aggressiveness was similar among some isolates in greenhouse assays. The in vitro pyraclostrobin sensitivity of all D. pinodes isolates collected from 2017 to 2020 was lower than that of the three baseline isolates. Sensitivity of 91% of A. pisi isolates collected in 2019 and 2020 was lower than the sensitivity of two known sensitive isolates. Resistance factors (Rf) from mean EC50 values of pyraclostrobin baseline/known sensitive isolates to isolates collected from 2017 to 2020 ranged from 2 to 1,429 for D. pinodes and 1 to 209 for A. pisi. In vitro prothioconazole sensitivity of 91% of D. pinodes isolates collected from 2017 to 2020 was lower than the sensitivity of the baseline isolates and 98% of A. pisi isolates collected from 2019 to 2020 was lower than the sensitivity of the known sensitive isolates. Prothioconazole Rf ranged from 1 to 338 for D. pinodes and 1 to 127 for A. pisi. Based on in vitro results, 92% of D. pinodes and 98% of A. pisi isolates collected displayed reduced-sensitivity/resistance to both fungicides when compared to baseline/known sensitive isolates. Disease control under greenhouse conditions of both pathogens provided by both fungicides was significantly lower in isolates determined to be reduced-sensitive or resistant in in vitro assays when compared to sensitive. Results reported here reinforce growers desperate need of alternative fungicides and/or management tools to fight Ascochyta blight in North Dakota and neighboring regions.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d51c5cb2-2da0-48b0-9354-9680a7007619', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Biocontrol Potential of Trichoderma asperellum Strain 576 against Exserohilum turcicum in Zea mays', 'Ma Y, Li Y, Yang S, Li Y, Zhu Z', 2023, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof9090936', 'https://doi.org/10.3390/jof9090936', 'https://europepmc.org/articles/PMC10532967?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Maize is a crucial cereal crop in China, serving both as a staple food and an essential industrial resource. Northern corn leaf blight (NCLB) is a disease of corn caused by a fungus, Exserohilum turcicum (sexual stage Setosphaeria turcica). This study aimed to assess the biocontrol potential of various Trichoderma strains against Exserohilum turcicum 101 in Jilin, China. Through dual culture tests, the Trichoderma strains were categorized into four groups based on their antagonistic abilities. Eleven Trichoderma strains exhibited strong antagonistic behavior, with comparable or faster growth rates than E. turcicum 101. Microscopic observations confirmed that T. asperellum 576 hyphae effectively encircled E. turcicum 101 hyphae, reinforcing their antagonistic behavior. The production of non-volatile and volatile substances by the Trichoderma strains was evaluated, with T. asperellum 576 showing the highest potency in producing non-volatile and volatile substances, leading to an impressive 80.81% and 65.86% inhibition of E. turcicum 101 growth. Remarkably, co-culture suspensions of T. asperellum 576 + E. turcicum 101 and T. atroviride 393 + E. turcicum 101 exhibited strong antifungal activity. Furthermore, the activities of chitinase, β-1.3-glucanase, and cellulase were evaluated using the 3, 5-dinitrosalicylic acid (DNS) method. T. asperellum 576 + E. turcicum 101 displayed stronger cell wall degradation enzyme activity compared to T. atroviride 393 + E. turcicum 101, with values of 8.34 U/mL, 3.42 U/mL, and 7.75 U/mL, respectively. In greenhouse conditions, the application of a 107 spores/mL conidia suspension of T. asperellum 576 significantly enhanced maize seed germination and plant growth while effectively suppressing E. turcicum 101 infection. Maize seedlings inoculated/treated with both E. turcicum 101 and T. asperellum 576 demonstrated substantial improvements compared to those inoculated solely with E. turcicum 101. The T. asperellum 576 treatment involved a 107 spores/mL conidia suspension applied through a combination of foliar spray and soil drench. These findings highlight T. asperellum 576 as a promising biocontrol candidate against northern leaf blight in maize. Its antagonistic behavior, production of inhibitory compounds, and promotion of plant growth all contribute to its potential as an effective biocontrol agent for disease management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0449213e-f26a-4184-9f31-54f8fda3a0c8', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'The role of pangenomics in orphan crop improvement', 'Hu H, Zhao J, Thomas WJW, Batley J, Edwards D', 2025, 'Nature communications', '10.1038/s41467-024-55260-4', 'https://doi.org/10.1038/s41467-024-55260-4', 'https://europepmc.org/articles/PMC11696220?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by-nc-nd', 'Global food security depends heavily on a few staple crops, while orphan crops, despite being less studied, offer the potential benefits of environmental adaptation and enhanced nutritional traits, especially in a changing climate. Major crops have benefited from genomics-based breeding, initially using single genomes and later pangenomes. Recent advances in DNA sequencing have enabled pangenome construction for several orphan crops, offering a more comprehensive understanding of genetic diversity. Orphan crop research has now entered the pangenomics era and applying these pangenomes with advanced selection methods and genome editing technologies can transform these neglected species into crops of broader agricultural significance.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7122883d-8fd6-43e8-8424-4a9038544a9d', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Bixafen, Prothioconazole, and Trifloxystrobin Alone or in Combination Have a Greater Effect on Health Related Gene Expression in Honey Bees from Nutritionally Deprived than from Protein Supplemented Colonies', 'Kato AY, Freitas TAL, Gomes CRA, Alves TRR, Ferraz YMM, Trivellato MF, De Jong D, Biller JD', 2024, 'Insects', '10.3390/insects15070523', 'https://doi.org/10.3390/insects15070523', 'https://europepmc.org/articles/PMC11277445?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'The aim of this study was to evaluate whether alterations in food availability compromise the metabolic homeostasis of honey bees exposed to three fungicides alone or together. Ten honey bee colonies were used, with half receiving carbohydrate-protein supplementation for 15 weeks while another five colonies had their protein supply reduced with pollen traps. Subsequently, forager bees were collected and exposed by contact to 1 or 7 µg of bixafen, prothioconazole, or trifloxystrobin, either individually or in combination. After 48 h, bee abdomens without the intestine were used for the analysis of expression of antioxidant genes (SOD-1, CAT, and GPX-1), detoxification genes (GST-1 and CYP306A1), the storage protein gene vitellogenin, and immune system antimicrobial peptide genes (defensin-1, abaecin, hymenoptaecin, and apidaecin), through real-time PCR. All fungicide treatments induced changes in gene expression, with bixafen showing the most prominent upregulation. Exposure to 1 µg of each of the three pesticides resulted in upregulation of genes associated with detoxification and nutrition processes, and downregulation of immune system genes. When the three pesticides were combined at a dose of 7 µg each, there was a pronounced downregulation of all genes. Food availability in the colonies affected the impact of fungicides on the expression of the studied genes in forager bees.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('65f3b247-ef04-4f8a-911a-fff2bcd73ef0', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Characterization of Fungicide Resistance in Cercospora beticola Populations from Sugarbeet (Beta vulgaris) in Michigan', 'Alexandra P. Hernandez, Sarah Ruth, Mio Satoh-Cruz, Daniel Bublitz, Linda E. Hanson, Jaime F. Willbur', 2025, 'PhytoFrontiers', '10.1094/PHYTOFR-03-25-0028-R', 'https://doi.org/10.1094/PHYTOFR-03-25-0028-R', 'https://apsjournals.apsnet.org/doi/10.1094/PHYTOFR-03-25-0028-R', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Sugarbeets produce over half of domestic sugar in the United States, and Michigan is the fourth-highest U.S. producer. Cercospora beticola causes one of the most impactful foliar diseases in sugarbeet, Cercospora leaf spot (CLS). CLS management relies heavily on timely and repeated fungicide applications, and resistance to several fungicide groups has been observed. In 2021 and 2022, the in vitro fungicide sensitivity of Michigan C. beticola isolates was tested for five demethylation inhibitors (DMIs; difenoconazole, fenbuconazole, mefentrifluconazole, prothioconazole, and tetraconazole), a quinone outside inhibitor (QoI; pyraclostrobin), a methyl benzimidazole carbamate (MBC; thiophanate-methyl), and triphenyltin hydroxide. Cross-resistance was confirmed among most DMIs, with the strongest correlations between difenoconazole and mefentrifluconazole (r = 0.58, P < 0.0001) and fenbuconazole and prothioconazole or tetraconazole (r = 0.51 or 0.54, P < 0.0001). Sensitivity to thiophanate-methyl and prothioconazole was affected by the number of MBC and DMI applications, respectively (P < 0.05). Mutations associated with QoI, MBC, and DMI resistance were evaluated using polymerase chain reaction–restriction fragment length polymorphism. Whereas the E198A mutation was significantly associated with C. beticola responses to thiophanate-methyl (P < 0.0001), G143A was not as strongly associated with responses to pyraclostrobin, nor was Glu169 strongly associated with responses to prothioconazole or tetraconazole. Overall, in vitro insensitivity (based on k-means cluster analyses) was observed for all tested active ingredients; however, elevated frequencies were observed for thiophanate-methyl (72 to 86%), tetraconazole (28 to 56%), prothioconazole (78 to 92%), and pyraclostrobin (9 to 33%). Identifying more explanatory resistance mutations for DMI and QoI fungicides in C. beticola populations would improve timely monitoring efforts. [Figure: see text] Copyright © 2025 The Author(s). This is an open access article distributed under the CC BY-NC-ND 4.0 International license.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('883cd732-a343-45a3-85dc-d35cb1ce0887', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Effect of novel botanical synergist on the effectiveness and residue behavior of prothioconazole in wheat field', 'Wu Y, Yin Y, Chen X, Zhou Y, Jiang S, Zhang M, Cai G, Gao Q', 2023, 'Scientific reports', '10.1038/s41598-023-47797-z', 'https://doi.org/10.1038/s41598-023-47797-z', 'https://europepmc.org/articles/PMC10663447?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Fusarium head blight (FHB) is a critical fungal disease causes serious grain yield losses and mycotoxin contaminations. Currently, utilization of chemical fungicides is the main control method which has led to serious resistance. Development of novel synergist is an important strategy to reduce the usage of chemical fungicides and postpone the development of resistance, while natural components are interesting resources. In this study, the synergistic effect of Taxodium ''zhongshansha'' essential oil (TZEO) was determined and the best synergistic ratio (SR) of 3.96 in laboratory which was observed when the weight ratio of TZEO and prothioconazole was 1 : 1 with the corresponding EC50 (half maximal effective concentration) value of Fusarium graminearum was 0.280 mg L-1. Subsequently, an increase of 6.31% on the control effect to FHB index in field test was observed when compared to the treatment with prothioconazole alone, though there was no significant difference between these treatments. Furthermore, we established an effective method to detect the mycotoxin contaminations in wheat grain with the limits of quantifications (LOQs) value of 5 µg kg-1 (DON, ZEN, 3-DON, and 15-DON) and 1 µg kg-1 (OTA) and the contents were less to the maximum residue limit (MRL) values. It was also shown that the application of 20% TZEO EW led to a 20% reduction in the use of prothioconazole, which was calculated based on the control effect values of 86.41% and 90.20% between the treatments of 30% prothioconazole OD (225 g a.i ha-1, recommend dosage) and 30% prothioconazole OD (180 g a.i ha-1) + 20% TZEO EW (225 mL ha-1), significantly. The initial residue of prothioconazole and prothioconazole-desthio was increased in the treatment with TZEO, which may play an important role in the synergistic effect on FHB. Moreover, none of the treatments posed a prothioconazole residue risk in the wheat grain and the environment. In addition, the essential oil has no any negative influence on wheat growth, which was revealed by a study of the chlorophyll content. These results provide an important botanical synergist for use with prothioconazole to control Fusarium head blight, and in-depth study to the synergistic mechanism of this oil is necessary in our future research.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4b972681-a300-4c12-b665-60cd14e96a98', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Environmental Hot Spots and Resistance-Associated Application Practices for Azole-Resistant Aspergillus fumigatus, Denmark, 2020-2023', 'Arendrup MC, Hare RK, Jørgensen KM, Bollmann UE, Bech TB, Hansen CC, Heick TM, Jørgensen LN', 2024, 'Emerging infectious diseases', '10.3201/eid3008.240096', 'https://doi.org/10.3201/eid3008.240096', 'https://europepmc.org/articles/PMC11286046?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Azole-resistant Aspergillus fumigatus (ARAf) fungi have been found inconsistently in the environment in Denmark since 2010. During 2018-2020, nationwide surveillance of clinical A. fumigatus fungi reported environmental TR34/L98H or TR46/Y121F/T289A resistance mutations in 3.6% of isolates, prompting environmental sampling for ARAf and azole fungicides and investigation for selection of ARAf in field and microcosmos experiments. ARAf was ubiquitous (20% of 366 samples; 16% TR34/L98H- and 4% TR46/Y121F/T289A-related mechanisms), constituting 4.2% of 4,538 A. fumigatus isolates. The highest proportions were in flower- and compost-related samples but were not correlated with azole-fungicide application concentrations. Genotyping showed clustering of tandem repeat-related ARAf and overlaps with clinical isolates in Denmark. A. fumigatus fungi grew poorly in the field experiment with no postapplication change in ARAf proportions. However, in microcosmos experiments, a sustained complete (tebuconazole) or partial (prothioconazole) inhibition against wild-type A. fumigatus but not ARAf indicated that, under some conditions, azole fungicides may favor growth of ARAf in soil.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d7a45f5-1c49-41c5-9a67-e80da06ec8a3', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Establishing the extent of pesticide contamination in Irish agricultural soils', 'Vickneswaran M, Carolan JC, Saunders M, White B', 2023, 'Heliyon', '10.1016/j.heliyon.2023.e19416', 'https://doi.org/10.1016/j.heliyon.2023.e19416', 'https://europepmc.org/articles/PMC10478240?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'To establish meaningful and sustainable policy directives for sustainable pesticide use in agriculture, baseline knowledge of pesticide levels in soils is required. To address this, five pesticides and one metabolite widely used in Irish agriculture and five neonicotinoid compounds pesticides were screened from soils from 25 fields. These sites represented a diversity of soil and land use types. Prothioconazole was detected in 16 of the 18 sites where it had been recently applied, with the highest maximum concentration quantified of 46 μg/kg. However, a week after application only four fields had prothioconazole concentrations above the limit of quantification (LOQ). Fluroxypyr was applied in 11 sites but was not detected above LOQ. Glyphosate and AMPA were not detected. Interestingly, neonicotinoids were detected in 96% of all sampling sites, even though they were not reported as recently applied. Excluding neonicotinoids, 60% of sites were found to contain pesticide residues of compounds that were not previously applied, with boscalid and azoxystrobin detected in 15 of the 25 sites sampled. The total number of pesticides detected in Irish soils were significantly negatively correlated with clay fraction, while average pesticide concentrations were significantly positively correlated with log Kow values. 17 fields were found to have total pesticide concentrations in excess of 0.5 μg/kg, even when recently applied pesticides were removed from calculations. Theoretical consideration of quantified pesticides determined that azoxystrobin has high leaching risk, while boscalid, which was detected but not applied, has an accumulation risk. This information provides insight into the current level of pesticide contamination in Irish agricultural soil and contributes to the European-level effort to understand potential impacts of pesticide contamination in soil.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a95e6a38-f7ac-4a60-b8b1-be3c88b84079', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Exploring the Potential Mechanism of Prothioconazole Resistance in Fusarium graminearum in China', 'Zhou F, Han A, Jiao Y, Cao Y, Wang L, Hu H, Liu R, Li C', 2023, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof9101001', 'https://doi.org/10.3390/jof9101001', 'https://europepmc.org/articles/PMC10607755?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The Fusarium head blight (FHB) caused by Fusarium graminearum is one of the most important diseases threatening wheat production in China. However, the triazole sterol 14α-demethylation inhibitor (DMI), prothioconazole, is known to exhibit high activity against F. graminearum. The current study indicated that three highly resistant laboratory mutants exhibited significantly (p p p F. graminearum has three homologues (FgCYP51A, FgCYP51B, and FgCYP51C), identified three mutations in the FgCYP51B sequence with a high likelihood of being associated with the observed resistance, as well as another three mutations in the FgCYP51B sequence, and two in the FgCYP51A sequence that are worthy of further investigation. Two of the prothioconazole-resistant mutants were also found to have several amino acid substitutions in their FgCYP51C sequences, and it was interesting to note that these two mutants exhibited significantly (p FgCYP51 target genes, and that expression was also altered in the prothioconazole-resistant mutants compared to their wild-type parental isolates. Meanwhile, no evidence was found of any cross-resistance between prothioconazole and other commonly used fungicides, including carbendazim, pyraclostrobin, and fluazinam, as well as the triazole tebuconazole and the imidazole DMI prochloraz. Taken together, these results not only provide new insight into potential resistance mechanism in F. graminearum, and the biological characteristics associated with them, but also convincing evidence that prothioconazole can offer effective control of FHB.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29450bcc-e5b8-4aff-8539-e0b4389a25d5', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Exposure of Cryptococcus neoformans to Seven Commonly Used Agricultural Azole Fungicides Induces Resistance to Fluconazole as Well as Cross-Resistance to Voriconazole, Posaconazole, Itraconazole and Isavuconazole', 'Drakulovski P, Krasteva D, Bellet V, Randazzo S, Roger F, Pottier C, Bertout S', 2023, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens12050662', 'https://doi.org/10.3390/pathogens12050662', 'https://europepmc.org/articles/PMC10224184?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'BackgroundCross-resistance to medical azoles by exposure to azole pesticides is well documented for Aspergillus family fungi but is poorly evaluated for other environmental pathogen fungi, particularly for yeasts belonging to the Cryptococcus neoformans/Cryptococcus gattii species complexes.MethodsOne thousand C. neoformans yeast were exposed to various concentrations of seven different commonly used azole pesticides. Clones surviving exposure were picked randomly, and their minimal inhibitory concentrations (MICs) of fluconazole, voriconazole, posaconazole, itraconazole and isavuconazole were assessed.ResultsDepending on the pesticide used for exposure, up to 13.3% of selected Cryptococcus colonies showed a phenotype of resistance to fluconazole, and among them, several showed cross-resistance to another or several other medical azoles. Molecular mechanisms involved in the resistance setups seem to be dependent on ERG11 and AFR1 gene overexpression.ConclusionExposure to any of the seven azole pesticides tested is capable of increasing the MIC of fluconazole in C. neoformans, including up to the level of the fluconazole-resistant phenotype, as well as generating cross-resistance to other medical azoles in some cases.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7931d16f-4ffc-40fc-9329-14aa8289dcbf', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Field-Crop Soils in Eastern France: Coldspots of Azole-Resistant Aspergillus fumigatus', 'Godeau C, Morin-Crini N, Crini G, Guillemin JP, Voisin AS, Dousset S, Rocchi S', 2023, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof9060618', 'https://doi.org/10.3390/jof9060618', 'https://europepmc.org/articles/PMC10301667?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Triazole fungicides are widely used to treat fungal pathogens in field crops, but very few studies have investigated whether fields of these crops constitute hotspots of azole resistance in Aspergillus fumigatus. Soil samples were collected from 22 fields in two regions of eastern France and screened for triazole residues and azole-resistant A. fumigatus (ARAf). Real-time quantitative PCR (qPCR) was used to quantify A. fumigatus in these soil samples. All the plots contained tebuconazole at concentrations from 5.5 to 19.1 ng/g of soil, and 5 of the 22 plots also contained epoxiconazole. Only a few fungal isolates were obtained, and no ARAf was detected. A. fumigatus qPCR showed that this fungal species was, on average, 5000 times more common in soil from flowerbeds containing ARAf than in soil from field crops. Thus, field-crop soils do not appear to promote A. fumigatus development, even if treated with azole fungicides, and cannot be considered hotspots of resistance. Indeed, our results suggest that they are instead a coldspot of resistance and highlight how little is known about the ecological niche of this species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b38c7484-e83c-4899-824c-24bcc4692f95', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'From Morphology to Multi-Omics: A New Age of Fusarium Research', 'Bugingo C, Infantino A, Okello P, Perez-Hernandez O, Petrović K, Turatsinze AN, Moparthi S', 2025, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens14080762', 'https://doi.org/10.3390/pathogens14080762', 'https://europepmc.org/articles/PMC12389138?pdf=render', NULL, NULL, 46, NULL, 'other', 1, 'cc by', 'The Fusarium genus includes some of the most economically and ecologically impactful fungal pathogens affecting global agriculture and human health. Over the past 15 years, rapid advances in molecular biology, genomics, and diagnostic technologies have reshaped our understanding of Fusarium taxonomy, host-pathogen dynamics, mycotoxin biosynthesis, and disease management. This review synthesizes key developments in these areas, focusing on agriculturally important Fusarium species complexes such as the Fusarium oxysporum species complex (FOSC), Fusarium graminearum species complex (FGSC), and a discussion on emerging lineages such as Neocosmospora. We explore recent shifts in species delimitation, functional genomics, and the molecular architecture of pathogenicity. In addition, we examine the global burden of Fusarium-induced mycotoxins by examining their prevalence in three of the world''s most widely consumed staple crops: maize, wheat, and rice. Last, we also evaluate contemporary management strategies, including molecular diagnostics, host resistance, and integrated disease control, positioning this review as a roadmap for future research and practical solutions in Fusarium-related disease and mycotoxin management. By weaving together morphological insights and cutting-edge multi-omics tools, this review captures the transition into a new era of Fusarium research where integrated, high-resolution approaches are transforming diagnosis, classification, and management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('352c07dd-606f-43ea-aabc-4815969a7a7a', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Fungicide Sensitivity Profile of Pyrenophora teres f. teres in Field Population', 'Pütsepp R, Mäe A, Mäe A, Põllumaa L, Andresen L, Kiiker R', 2024, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof10040260', 'https://doi.org/10.3390/jof10040260', 'https://europepmc.org/articles/PMC11051325?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Pyrenophora teres f. teres (Ptt) is a severe pathogen to spring barley in Northern Europe. Ptt with relevant mutations in fungicide target proteins, sterol 14α-demethylase (CYP51A), cytochrome b (Cyt b), and succinate dehydrogenase (SDH) would put efficient disease control at risk. In the growing seasons of 2021 and 2022, 193 Ptt isolates from Estonia were analysed. In this study, mutation detection and in vitro fungicide sensitivity assays of single-spore isolates were carried out. Reduced sensitivity phenotype to mefentrifluconazole was evident in Ptt isolates with a F489L mutation in CYP51A or with 129 bp insert in the Cyp51A gene-promoter region. However, sensitivity to a prothioconazole-desthio remained high regardless of these molecular changes. The Ptt population was mostly sensitive to bixafen, fluxapyroxad, pyraclostrobin, and azoxystrobin. The sensitivity of fluxapyroxad and bixafen has been affected by two mutations, C-S135R and D-H134R, found in SDH subunits. The F129L mutation in Cyt b influenced azoxystrobin but not pyraclostrobin sensitivity. In total, 30 isolates from five fields had relevant mutations in three target protein genes simultaneously. Most of these isolates had a reduced sensitivity phenotype to mefentrifluconazole, fluxapyroxad, and azoxystrobin, while sensitivity to other tested fungicides remained high. Furthermore, possible sexual reproduction may enhance the pathogen''s fitness and help it adapt to fungicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('01c51c5d-adff-461a-a58d-c50c437ea03f', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Fusarium graminearum in Wheat-Management Strategies in Central Europe', 'Giedrojć W, Pluskota WE, Wachowska U', 2025, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens14030265', 'https://doi.org/10.3390/pathogens14030265', 'https://europepmc.org/articles/PMC11945457?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The main aim of this study was to discuss and compare the threats associated with F. graminearum in wheat production in Poland and in other Central European countries. Wheat is one of the most widely cultivated crops in the world, and pathogens causing Fusarium head blight (FHB) pose the greatest threat to wheat production. Our knowledge of FHB has to be regularly expanded in order to explore the impacts of climate change, new wheat cultivars, and new fungicides on the prevalence of this disease. The pathogen''s resistance to fungicides was analyzed in a global context due to the relative scarcity of studies examining this problem in Central Europe (excluding Germany). This is an interesting research perspective because, despite a relatively large number of Polish studies on FHB, F. graminearum genotypes and the pathogen''s resistance to fungicides remain insufficiently investigated. The hemibiotrophic pathogen Fusarium graminearum causes particularly high losses in wheat cultivation due to its ability to produce mycotoxins that are dangerous to human health (mainly deoxynivalenol, DON), colonize plant residues in soil in the saprotrophic phase, and produce spores that infect the stem base and spikes throughout the growing season. The infection process is highly dynamic, and it is facilitated by DON. The synthesis of DON (trichothecene) is encoded by Tri genes located in four loci. In Poland, the F. graminearum population is mainly composed of the 15ADON genotype, and the spread of FHB cannot effectively be managed with fungicides during epidemic years. Dynamic gene flows in field populations enable the pathogen to rapidly adapt to environmental changes and overcome wheat resistance to FHB. The emergence of fungicide-resistant F. graminearum strains significantly compromises the quality of wheat crops, but the associated mechanisms have not been sufficiently investigated to date. In addition, although some biopreparations are promising and effective in small-scale field trials, very few have been commercialized. Extensive research into pathogen populations, the development of new resistant wheat varieties, and the use of effective fungicides and biopreparations are required to produce wheat grain that is free of mycotoxins.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3afb868c-fe92-42d5-9da2-d90b83b9ac14', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Fusarium Toxins in Cereals: Occurrence, Legislation, Factors Promoting the Appearance and Their Management', 'Ferrigo D, Raiola A, Causin R', 2016, 'Molecules (Basel, Switzerland)', '10.3390/molecules21050627', 'https://doi.org/10.3390/molecules21050627', 'https://europepmc.org/articles/PMC6274039?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Fusarium diseases of small grain cereals and maize cause significant yield losses worldwide. Fusarium infections result in reduced grain yield and contamination with mycotoxins, some of which have a notable impact on human and animal health. Regulations on maximum limits have been established in various countries to protect consumers from the harmful effects of these mycotoxins. Several factors are involved in Fusarium disease and mycotoxin occurrence and among them environmental factors and the agronomic practices have been shown to deeply affect mycotoxin contamination in the field. In the present review particular emphasis will be placed on how environmental conditions and stress factors for the crops can affect Fusarium infection and mycotoxin production, with the aim to provide useful knowledge to develop strategies to prevent mycotoxin accumulation in cereals.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ca7952fc-b200-41de-a291-a54b9effb7cf', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'In Vitro Sensitivity Test of Fusarium Species from Weeds and Non-Gramineous Plants to Triazole Fungicides', 'Neringa Matelionienė, Renata Žvirdauskienė, Gražina Kadžienė, Evelina Zavtrikovienė, Skaidrė Supronienė', 2024, 'Pathogens', '10.3390/pathogens13020160', 'https://doi.org/10.3390/pathogens13020160', 'https://www.mdpi.com/2076-0817/13/2/160', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Fusarium species are common plant pathogens that cause serious crop losses worldwide. Fusarium spp. colonize not only the main host plants, crops, but also alternative hosts. The effectiveness of fungicide use in disease management ranges from very successful to possibly promoting the growth of the pathogen. Triazole fungicides are widely used to control these pathogens due to their broad-spectrum activity and systemic nature. This paper reviews the sensitivity of 40 Fusarium strains isolated from weeds, non-gramineous plants, and spring wheat to metconazole, prothioconazole, and tebuconazole. The effect of fungicides was determined by the percentage inhibition of F. graminearum, F. culmorum, F. sporotrichioides, and F. avenaceum fungal mycelial growth. The 50% effective concentration (EC50) values of all isolates on metconazole were lower than 2.9 mg L−1, prothioconazole EC50 ranged from 0.12 to 23.6 mg L−1, and tebuconazole ranged from 0.09 to 15.6 mg L−1. At 0.00025–0.025 mg L−1, the fungicides were ineffective, except for the growth of the F. avenaceum species. It was observed that isolates from weeds were more sensitive to low concentrations of fungicide than isolates from crop plants. In general, information is scarce regarding the comparison of fungicide resistance in Fusarium isolates from weed and crop plants, making this study an additional contribution to the existing knowledge base.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fc7b620a-8a4a-404b-9398-c736dfc955ee', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Antifungal activity of metyltetraprole against the existing QoI-resistant isolates of various plant pathogenic fungi: Metyltetraprole against QoI-R isolates', 'Matsuzaki Y, Kiguchi S, Suemoto H, Iwahashi F', 2020, 'Pest management science', '10.1002/ps.5697', 'https://doi.org/10.1002/ps.5697', 'https://europepmc.org/articles/PMC7204873?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by-nc', 'BackgroundMetyltetraprole is a novel quinol oxidation site of Complex III inhibitor (QoI) fungicide that inhibits mitochondrial electron transport at the Qo site of the cytochrome bc1 complex. Previous reports have demonstrated that it is also active against the QoI-resistant (QoI-R) isolates of Zymoseptoria tritici and Pyrenophora teres with the mutations G143A and F129L in their cytochrome b gene, respectively. Further studies on cross-resistance between metyltetraprole and existing QoIs were performed using an increased number of isolates of Z. tritici, P. teres, Ramularia collo-cygni, Pyrenophora tritici-repentis, and several other plant pathogenic fungi.ResultsDifferences in the EC50 values between the wild-type and QoI-R isolates with the mutations G143A or F129L were always smaller for metyltetraprole compared to those for the existing QoIs, and they were never greater than five in terms of resistance factor. The 2-year field experiments showed that the metyltetraprole treatment did not increase the percentage of QoI-R isolates likely to harbor the G143A mutation in a Z. tritici population.ConclusionThe unique behavior of metyltetraprole against the existing QoI-R isolates was confirmed for all tested pathogen species. Our results provide important information to establish a fungicide resistance management strategy using metyltetraprole in combination or alternation with other fungicides. © 2019 Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ee7e15d0-5dd1-4455-89e8-28f00294ee6e', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Meta-analysis of yield response of foliar fungicide-treated hybrid corn in the United States and Ontario, Canada', 'Wise KA, Smith D, Freije A, Mueller DS, Kandel Y, Allen T, Bradley CA, Byamukama E', 2019, 'PloS one', '10.1371/journal.pone.0217510', 'https://doi.org/10.1371/journal.pone.0217510', 'https://europepmc.org/articles/PMC6550426?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by', 'BackgroundFoliar fungicide applications to corn (Zea mays L.) occur at one or more application timings ranging from early vegetative growth stages to mid-reproductive stages. Previous studies indicated that fungicide applications are profitable under high disease pressure when applied during the tasseling to silking growth stages. Few comprehensive studies in corn have examined the impact of fungicide applications at an early vegetative growth stage (V6) compared to late application timings (VT) for yield response and return on fungicide investment (ROI) across multiple locations.ObjectiveCompare yield response of fungicide application timing across multiple fungicide classes and calculate the probability of positive ROI.MethodsData were collected specifically for this analysis using a uniform protocol conducted in 13 states in the United States and one province in Canada from 2014-2015. Data were subjected to a primary mixed-model analysis of variance. Subsequent univariate meta-analyses, with and without moderator variables, were performed using standard meta-analytic procedures. Follow-up power and prediction analyses were performed to aid interpretation and development of management recommendations.ResultsFungicide application resulted in a range of yield responses from -2,683.0 to 3,230.9 kg/ha relative to the non-treated control, with 68.2% of these responses being positive. Evidence suggests that all three moderator variables tested (application timing, fungicide class, and disease base level), had some effect (α = 0.05) on the absolute difference in yield between fungicide treated and non-treated plots ([Formula: see text]). Application timing influenced [Formula: see text], with V6 + VT and the VT application timings resulting in greater yield responses than the V6 application timing alone. Fungicide formulations that combined demethylation inhibitor and quinone outside inhibitor fungicides significantly increased yield response.ConclusionFoliar fungicide applications can increase corn grain yield. To ensure the likelihood of a positive ROI, farmers should focus on applications at VT and use fungicides that include a mix of demethylation inhibitor and quinone outside inhibitor active ingredients.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1ab46e65-4e30-4a94-9243-69837f99e3a5', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Prevalence and spatial distribution of cranberry fruit rot pathogens in British Columbia, Canada and potential fungicides for fruit rot management', 'Wood B, McBride E, Nabetani K, Griffin T, Sabaratnam S', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1274094', 'https://doi.org/10.3389/fpls.2023.1274094', 'https://europepmc.org/articles/PMC10667600?pdf=render', NULL, NULL, 17, NULL, 'canada', 3, 'cc by', 'Twenty-eight cranberry farms in southwestern British Columbia were investigated for the prevalence and spatial distribution of fungal pathogens that contribute to fruit rot incidence. Farms were selected from six regions where most cranberry production is concentrated. Flowers, and green and ripe fruit (var. ''Stevens'') samples, collected during two consecutive crop seasons, were analyzed for fruit rot pathogens. The most frequently isolated pathogens were identified as Allantophomopsis cytisporea, Botrytis cinerea, Coleophoma empetri, Colletotrichum fioriniae, Colletotrichum gloeosporioides, Fusicoccum putrefaciens, Glomerella sp., Phomopsis vaccinii, Phyllosticta elongata, Phyllosticta vaccinii and Physalospora vaccinii. The pathogens Allantophomopsis cytisporea, Phyllosticta spp., and Physalospora vaccinii were found at high incidence. These pathogens were present in all cranberry growing regions, although their mean percentage incidence varied from farm-to-farm and region-to-region. Amongst the pathogens from three phenological stages of cranberry crop examined, ripe fruit had the highest percentage incidence of fruit rot pathogens compared to that of flowers or green fruit; thus, indicating their presence at the early stages of crop development. The efficacy to inhibit the mycelial growth and spore germination of the fruit rot pathogens by twenty six fungicides, belonging to nine different modes of actions, were evaluated in vitro. The copper-based fungicides and captan of group M, flutriafol, triforine, difenoconazole, prothioconazole and propiconazole of group 3, benzovindiflupyr of group 7, and fosetyl-Al of group 33 demonstrated a high degree of efficacy in inhibiting the mycelial growth of all fruit rot pathogens. The fungicides chlorothalonil of group M, fenbuconazole of group 3, pyrimethanil and cyprodinil of group 9, and fludioxonil of group 12 also demonstrated activity against most fruit rot pathogens. The copper-based fungicides, chlorothalonil, captan, flutriafol, triforine, difenoconazole, prothioconazole, propiconazole, benzovindiflupyr, and fosetyl-Al effectively prevented the spore germination of most fruit rot pathogens. This demonstrated activity of the fungicides towards cranberry fruit rot pathogens should be assessed for efficacy in planta under field conditions. The current study identified the most critical fungal pathogens causing fruit rot of cranberry in British Columbia and potential fungicides that could be used in the management of fruit rot and to improve fruit quality and yield.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('926c3c4a-feea-4502-98c1-82009e595d70', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Resistance Mechanisms of Plant Pathogenic Fungi to Fungicide, Environmental Impacts of Fungicides, and Sustainable Solutions', 'Islam T, Danishuddin, Tamanna NT, Matin MN, Barai HR, Haque MA', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13192737', 'https://doi.org/10.3390/plants13192737', 'https://europepmc.org/articles/PMC11478979?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'The significant reduction in agricultural output and the decline in product quality are two of the most glaring negative impacts caused by plant pathogenic fungi (PPF). Furthermore, contaminated food or transit might introduce mycotoxins produced by PPF directly into the food chain. Eating food tainted with mycotoxin is extremely dangerous for both human and animal health. Using fungicides is the first choice to control PPF or their toxins in food. Fungicide resistance and its effects on the environment and public health are becoming more and more of a concern, despite the fact that chemical fungicides are used to limit PPF toxicity and control growth in crops. Fungicides induce target site alteration and efflux pump activation, and mutations in PPF result in resistance. As a result, global trends are shifting away from chemically manufactured pesticides and toward managing fungal plant diseases using various biocontrol techniques, tactics, and approaches. However, surveillance programs to monitor fungicide resistance and their environmental impact are much fewer compared to bacterial antibiotic resistance surveillance programs. In this review, we discuss the PPF that contributes to disease development in plants, the fungicides used against them, factors causing the spread of PPF and the emergence of new strains, the antifungal resistance mechanisms of PPF, health, the environmental impacts of fungicides, and the use of biocontrol agents (BCAs), antimicrobial peptides (AMPs), and nanotechnologies to control PPF as a safe and eco-friendly alternative to fungicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f3495e55-13e9-4a3f-b771-8ec2eab4564e', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Sensitivity Analysis of Pyrenophora tritici-repentis to Quinone-Outside Inhibitor and 14α-Demethylase Inhibitor Fungicides in Latvia', 'Jānis Kaņeps, Biruta Bankina, Inga Moročko-Bičevska, Katrīna Apsīte, Ance Roga, Dāvids Fridmanis', 2024, 'Pathogens', '10.3390/pathogens13121060', 'https://doi.org/10.3390/pathogens13121060', 'https://www.mdpi.com/2076-0817/13/12/1060', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Tan spot caused by Pyrenophora tritici-repentis is a severe threat to wheat production in all major wheat-growing regions. Sustainable tan spot control can be achieved by an integrated approach, including responsible management of fungicide sprays. The data about the sensitivity of P. tritici-repentis to various fungicides in the Baltic Sea region are rare. In this study, we described the variation of P. tritici-repentis sensitivity to four fungicide active ingredients to detect the formation of resistance to the most commonly used quinone-outside inhibitor (QoI) and 14α-demethylase inhibitor (DMI) fungicides in the pathogen’s population in Latvia. The effect of prothioconazole, mefentrifluconazole, pyraclostrobin, and azoxystrobin on 93 P. tritici-repentis strains from various hosts was tested in vitro by assessing mycelium linear growth inhibition at three different active ingredient concentrations (0 0.01, 0.1 and 0.5 mg L−1). Pathogen sensitivity significantly (p −1) had the most significant effect, with a median mycelial growth inhibition of 70.34%, followed by pyraclostrobin (47.02%), azoxystrobin (24.24%), and mefentrifluconazole (11.11%). Mutation G143A was detected in cytb gene sequences and confirmed the resistance formation in Latvia’s P. tritici-repentis population, while F129L and G137R mutations were absent. This study provided insight into P. tritici-repentis population’s sensitivity to active ingredients of DMI and OoI fungicide groups, helping to fill the knowledge gap about the pathogen fungicide sensitivity in this region.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('628fc99d-3700-4f27-817c-05c195fcc522', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Sensitivity of Alternaria alternata to Four DMI Fungicides and Resistance Risk Assessment to Mefentrifluconazole', 'Jinming Li, Dongmei Liu, Yan Ge, Ruikai Zhang, Jiale Zhang, Xiaoming Xia', 2026, 'Agronomy', '10.3390/agronomy16151447', 'https://doi.org/10.3390/agronomy16151447', 'https://www.mdpi.com/2073-4395/16/15/1447', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Alternaria alternata often causes preharvest potato early blight and postharvest tuber rot, which can result in substantial yield losses. Demethylation inhibitors (DMIs) are widely used to control Alternaria diseases. However, the underlying resistance risk remains poorly understood. In this study, 114 A. alternata isolates from five major potato-producing regions in Shandong, China, were evaluated for sensitivity to four DMIs (mefentrifluconazole, prothioconazole, tebuconazole, and difenoconazole). The mean EC50 values were 0.622, 6.053, 4.763, and 0.651 mg·L−1, respectively. The Shapiro–Wilk test confirmed unimodal sensitivity distributions, allowing these mean EC50 values to serve as baseline sensitivities. Two-year, two-location field trials demonstrated good control efficacy for all fungicides, with mefentrifluconazole exhibiting the highest efficacy. Three resistant mutants produced by artificial selection in the laboratory exhibited 3.78-, 28.06-, and 15.73-fold higher EC50 values and showed fitness costs, including reduced or comparable mycelial growth, sporulation, and spore germination, pathogenicity similar to that of the parental strain, and lower temperature adaptability. By establishing the first baseline sensitivity of A. alternata from potato to these four DMI fungicides and assessing the resistance risk of mefentrifluconazole, this study provides a basis for rational fungicide application, resistance management, and future field resistance monitoring.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bdc6de39-4f59-4865-96f6-a6c0972f2465', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Strategies for the Preparation of Chitosan Derivatives for Antimicrobial, Drug Delivery, and Agricultural Applications: A Review', 'Shrestha R, Thenissery A, Khupse R, Rajashekara G', 2023, 'Molecules (Basel, Switzerland)', '10.3390/molecules28227659', 'https://doi.org/10.3390/molecules28227659', 'https://europepmc.org/articles/PMC10674490?pdf=render', NULL, NULL, 39, NULL, 'other', 1, 'cc by', 'Chitosan has received much attention for its role in designing and developing novel derivatives as well as its applications across a broad spectrum of biological and physiological activities, owing to its desirable characteristics such as being biodegradable, being a biopolymer, and its overall eco-friendliness. The main objective of this review is to explore the recent chemical modifications of chitosan that have been achieved through various synthetic methods. These chitosan derivatives are categorized based on their synthetic pathways or the presence of common functional groups, which include alkylated, acylated, Schiff base, quaternary ammonia, guanidine, and heterocyclic rings. We have also described the recent applications of chitosan and its derivatives, along with nanomaterials, their mechanisms, and prospective challenges, especially in areas such as antimicrobial activities, targeted drug delivery for various diseases, and plant agricultural domains. The accumulation of these recent findings has the potential to offer insight not only into innovative approaches for the preparation of chitosan derivatives but also into their diverse applications. These insights may spark novel ideas for drug development or drug carriers, particularly in the antimicrobial, medicinal, and plant agricultural fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2209f47f-7c43-42b2-b3cb-94983f7a3c81', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'Synergistic Control of Bacterial Fruit Blotch Using Bacillus velezensis ZY1 and Chemical Bactericides', 'Haoyu Wei, Sheng Han, Maihemuti Mijiti, Tingchang Zhao, Wei Guan, Yuwen Yang', 2024, 'Agronomy', '10.3390/agronomy14122797', 'https://doi.org/10.3390/agronomy14122797', 'https://www.mdpi.com/2073-4395/14/12/2797', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Bacterial fruit blotch (BFB) is a devastating disease caused by Acidovorax citrulli, severely impacting the watermelon and melon industries and leading to significant economic losses. Currently, researchers have not identified any commercial melon varieties with high resistance to BFB, and farmers primarily rely on chemical agents for prevention and control. However, the extensive use of these agents contributes to increased drug resistance among pathogenic bacteria, making it essential to develop environmentally friendly control methods. To explore the feasibility of combining the Bacillus velezensis ZY1 strain with chemical agents for BFB management, we assessed the efficacy of 10 bactericides and the ZY1 strain against Acidovorax citrulli. The results show that Prothioconazole, Zhongsheng Tetramycin Solution, Streptomycin Sesquisulfate, Tetramycin, Zhongshengmycin, and ZY1 exhibited significant inhibitory effects on the growth of Acidovorax citrulli. We determined the biocompatibility of the bactericides with the ZY1 strain using the plate confrontation method and the flat counting method. Zhongsheng Tetramycin Solution, Zhongshengmycin, and Kasugamycin exhibited good compatibility with the ZY1 strain. Additionally, we established the optimal compounding ratio of the bactericide and ZY1 using the Horsfall method. Among these, Zhongshengmycin demonstrated the best performance when combining its efficacy against Acidovorax citrulli with its biocompatibility with the ZY1 strain. The combination of Zhongshengmycin and ZY1 at a volume ratio of 5:5 significantly inhibited Acidovorax citrulli, exhibiting a clear synergistic effect with a synergy index (IR) value of 1.542. Field tests conducted over 21 days in Beijing greenhouses, Hainan Field facility greenhouses, and Xinjiang showed that the control efficacy of the Zhongshengmycin and ZY1 combination (89.23%) significantly surpassed that of the single agent Zhongshengmycin (80.35%) and the biocontrol bacterium ZY1 (72.12%). Notably, the application rate of Zhongshengmycin in the mixture was only half that of the single agent, resulting in a significant reduction in chemical usage. The combination of Bacillus velezensis ZY1 and Zhongshengmycin not only decreases chemical usage but also significantly enhances control efficacy compared to using Zhongshengmycin alone.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87fb5cd7-3f56-4c78-aea5-25ca45d1ec74', '6c813450-8f88-42bf-85d9-f85dbf4410ea', 'The Mechanisms of Developing Fungicide Resistance in Fusarium graminearum Causing Fusarium Head Blight and Fungicide Resistance Management', 'Jayawardana MA, Fernando WGD', 2024, 'Pathogens (Basel, Switzerland)', '10.3390/pathogens13111012', 'https://doi.org/10.3390/pathogens13111012', 'https://europepmc.org/articles/PMC11597361?pdf=render', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Fusarium head blight (FHB), primarily caused by Fusarium graminearum, is one of the economically significant diseases in small grains. FHB causes severe damage to wheat production and grain quality. Several management strategies have been developed to control FHB, and chemical control through fungicides plays a significant role. Although fungicides have effectively controlled F. graminearum in the field, the continuous exposure causes a selection pressure in the pathogen population towards fungicide resistance. Several studies have identified fungicide-resistant F. graminearum isolates and fungicide-resistance mechanisms. Although new fungicides with a new mode of action can be introduced into the market, developing a new fungicide is time-consuming, and extra efforts are needed for testing, approvals, and registrations. Therefore, it is essential to strategize the methods to delay the fungicide resistance. This review focuses on the impact of several fungicide applications currently used on FHB, focusing on Fusarium graminearum, the status of the fungicide sensitivity for fungicide classes, the resistance mechanisms against fungicides, and the mitigation strategies to delay the development of fungicide resistance in the pathogen population. Studying the fungicide resistance mechanisms and the mitigation strategies will be helpful in the future to use the available fungicides against F. graminearum without losing its effectiveness.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3264ef09-35c9-4998-b3d1-30b82e8ebed5', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'A Scientific Review of Pesticides: Classification, Toxicity, Health Effects, Sustainability, and Environmental Impact', 'Garud A, Pawar S, Patil MS, Kale SR, Patil S', 2024, 'Cureus', '10.7759/cureus.67945', 'https://doi.org/10.7759/cureus.67945', 'https://europepmc.org/articles/PMC11426366?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Over the years, the use of pesticides has risen significantly, primarily to combat undesirable organisms that threaten crucial crops. A variety of pesticides are available, each designed to protect crops from specific threats like fungi, bacteria, and other pests. Other than crop protection, pesticides are also used in controlling insect vector-borne diseases like malaria and Lyme disease in humans. However, the application of these pesticides must be carefully measured and managed to prevent adverse effects on humans, non-target animals, and the environment. This review delves into the detailed classification of pesticides, exploring their mechanisms of action, applications, benefits, and potential side effects. Understanding the different categories of pesticides, such as herbicides, insecticides, fungicides, rodenticides, and biopesticides, helps us comprehend how each function to control pests. Additionally, we discuss the advantages of pesticide use, including increased crop yields and the prevention of crop diseases, which contribute to food security and agricultural productivity. This review also addresses the significant concerns related to pesticide usage, such as the development of pest resistance, health risks to humans through exposure and residues in food, as well as the impact on biodiversity and ecosystems. The review emphasizes the importance of using pesticides responsibly and implementing integrated pest management strategies to mitigate this risk of exposure. By providing a comprehensive overview of pesticide classification, mechanisms of action, and implications, this review aims to inform and guide us to the safe and effective use of pesticides for daily agricultural practices.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ab8a004-9f85-4250-b7e4-e7c30a96e1db', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Ascochyta rabiei: A threat to global chickpea production', 'Singh R, Kumar K, Purayannur S, Chen W, Verma PK', 2022, 'Molecular plant pathology', '10.1111/mpp.13235', 'https://doi.org/10.1111/mpp.13235', 'https://europepmc.org/articles/PMC9366070?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'The necrotrophic fungus Ascochyta rabiei causes Ascochyta blight (AB) disease in chickpea. A. rabiei infects all aerial parts of the plant, which results in severe yield loss. At present, AB disease occurs in most chickpea-growing countries. Globally increased incidences of A. rabiei infection and the emergence of new aggressive isolates directed the interest of researchers toward understanding the evolution of pathogenic determinants in this fungus. In this review, we summarize the molecular and genetic studies of the pathogen along with approaches that are helping in combating the disease. Possible areas of future research are also suggested.Taxonomykingdom Mycota, phylum Ascomycota, class Dothideomycetes, subclass Coelomycetes, order Pleosporales, family Didymellaceae, genus Ascochyta, species rabiei.Primary hostA. rabiei survives primarily on Cicer species.Disease symptomsA. rabiei infects aboveground parts of the plant including leaves, petioles, stems, pods, and seeds. The disease symptoms first appear as watersoaked lesions on the leaves and stems, which turn brown or dark brown. Early symptoms include small circular necrotic lesions visible on the leaves and oval brown lesions on the stem. At later stages of infection, the lesions may girdle the stem and the region above the girdle falls off. The disease severity increases at the reproductive stage and rounded lesions with concentric rings, due to asexual structures called pycnidia, appear on leaves, stems, and pods. The infected pod becomes blighted and often results in shrivelled and infected seeds.Disease management strategiesCrop failures may be avoided by judicious practices of integrated disease management based on the use of resistant or tolerant cultivars and growing chickpea in areas where conditions are least favourable for AB disease development. Use of healthy seeds free of A. rabiei, seed treatments with fungicides, and proper destruction of diseased stubbles can also reduce the fungal inoculum load. Crop rotation with nonhost crops is critical for controlling the disease. Planting moderately resistant cultivars and prudent application of fungicides is also a way to combat AB disease. However, the scarcity of AB-resistant accessions and the continuous evolution of the pathogen challenges the disease management process.Useful websiteshttps://www.ndsu.edu/pubweb/pulse-info/resourcespdf/Ascochyta%20blight%20of%20chickpea.pdf https://saskpulse.com/files/newsletters/180531_ascochyta_in_chickpeas-compressed.pdf http://www.pulseaus.com.au/growing-pulses/bmp/chickpea/ascochyta-blight http://agriculture.vic.gov.au/agriculture/pests-diseases-and-weeds/plant-diseases/grains-pulses-and-cereals/ascochyta-blight-of-chickpea http://www.croppro.com.au/crop_disease_manual/ch05s02.php https://www.northernpulse.com/uploads/resources/722/handout-chickpeaascochyta-nov13-2011.pdf http://oar.icrisat.org/184/1/24_2010_IB_no_82_Host_Plant https://www.crop.bayer.com.au/find-crop-solutions/by-pest/diseases/ascochyta-blight.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('328d6713-cb2f-4205-999a-606d1212e92e', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Biological characterization of fenpicoxamid, a new fungicide with utility in cereals and other crops', 'Owen WJ, Yao C, Myung K, Kemmitt G, Leader A, Meyer KG, Bowling AJ, Slanec T', 2017, 'Pest management science', '10.1002/ps.4588', 'https://doi.org/10.1002/ps.4588', 'https://europepmc.org/articles/PMC5599960?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by-nc', 'BackgroundThe development of novel highly efficacious fungicides that lack cross-resistance is extremely desirable. Fenpicoxamid (Inatreq™ active) possesses these characteristics and is a member of a novel picolinamide class of fungicides derived from the antifungal natural product UK-2A.ResultsFenpicoxamid strongly inhibited in vitro growth of several ascomycete fungi, including Zymoseptoria tritici (EC50 , 0.051 mg L-1 ). Fenpicoxamid is converted by Z. tritici to UK-2A, a 15-fold stronger inhibitor of Z. tritici growth (EC50 , 0.0033 mg L-1 ). Strong fungicidal activity of fenpicoxamid against driver cereal diseases was confirmed in greenhouse tests, where activity on Z. tritici and Puccinia triticina matched that of fluxapyroxad. Due to its novel target site (Qi site of the respiratory cyt bc1 complex) for the cereals market, fenpicoxamid is not cross-resistant to Z. tritici isolates resistant to strobilurin and/or azole fungicides. Across multiple European field trials Z. tritici was strongly controlled (mean, 82%) by 100 g as ha-1 applications of fenpicoxamid, which demonstrated excellent residual activity.ConclusionsThe novel chemistry and biochemical target site of fenpicoxamid as well as its lack of cross-resistance and strong efficacy against Z. tritici and other pathogens highlight the importance of fenpicoxamid as a new tool for controlling plant pathogenic fungi. © 2017 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('371a0380-b728-49de-8063-3ca0ec748c95', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Changes in DMI, SDHI, and QoI Fungicide Sensitivity in the Estonian Zymoseptoria tritici Population between 2019 and 2020', 'Kiiker R, Juurik M, Heick TM, Mäe A', 2021, 'Microorganisms', '10.3390/microorganisms9040814', 'https://doi.org/10.3390/microorganisms9040814', 'https://europepmc.org/articles/PMC8070593?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Zymoseptoria tritici (Zt) populations adapt under the selection pressure of fungicides applied for disease control. The primary objective of this study was to assess fungicide sensitivity in the Estonian Zt population. A total of 282 Zt isolates from 2019 and 2020 were tested for sensitivity to azoles (DMIs; prothioconazole-desthio, epoxiconazole, mefentrifluconazole) and succinate dehydrogenase inhibitors (SDHIs; boscalid, fluxapyroxad). The efficacy of the tested fungicides varied considerably between the Estonian counties, but the Zt population is mainly sensitive to DMIs. Additionally, the frequencies of CYP51 gene alterations varied; D134G, V136C, A379G, and S524T had increased, but V136A and I381V showed a moderate decrease in 2020 in comparison to 2019. Sensitivity to SDHIs was stable, but boscalid was less effective than fluxapyroxad. SdhC gene mutations C-T33N, C-T34N, and C-N86S were common, but not linked with SDHI fungicide sensitivity assay results. Otherwise, mutation B-N225I in the SdhB subunit occurred in isolates with reduced sensitivity to SDHIs. Sensitivity to strobilurins was evaluated by the mutation G143A in the CytB gene, which was present in nearly half of the population. The data presented confirm the ongoing evolution of fungicide sensitivity in the Zt population in Estonia and highlight the importance of knowledge-based decisions for optimizing anti-resistance strategies in the field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('77240e80-9bf6-4f74-a156-7b277a04a8c9', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Combination of Strobilurin and Triazole Chemicals for the Management of Blast Disease in Mushk Budji -Aromatic Rice', 'Mohiddin FA, Bhat NA, Wani SH, Bhat AH, Ahanger MA, Shikari AB, Sofi NR, Parveen S', 2021, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof7121060', 'https://doi.org/10.3390/jof7121060', 'https://europepmc.org/articles/PMC8707660?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Rice blast is considered one of the most important fungal diseases of rice. Although diseases can be managed by using resistant cultivars, the blast pathogen has successfully overcome the single gene resistance in a short period and rendered several varieties susceptible to blast which were otherwise intended to be resistant. As such, chemical control is still the most efficient method of disease control for reducing the losses caused due to diseases. Field experiments were conducted over two successive years, 2018 and 2019, in temperate rice growing areas in northern India. All the fungicides effectively reduced leaf blast incidence and intensity, and neck blast incidence under field conditions. Tricyclazole proved most effective against rice blast and recorded a leaf blast incidence of only 8.41%. Among the combinations of fungicides, azoxystrobin + difenoconazole and azoxystrobin + tebuconazole were highly effective, recording a leaf blast incidence of 9.19 and 10.40%, respectively. The chemical combination mancozeb + carbendazim proved less effective in controlling the blast and it recorded a disease incidence of 27.61%. A similar trend was followed in neck blast incidence with tricyclazole, azoxystrobin + difenoconazole, and azoxystrobin + tebuconazole showing the highest levels of blast reductions. It is evident from the current study that the tested fungicide combinations can be used as alternatives to tricyclazole which is facing the challenges of fungicide resistance development and other environmental concerns and has been banned from use in India and other countries. The manuscript may provide a guideline of fungicide application to farmers cultivating susceptible varieties of rice.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec82d93d-0cdd-4c47-b208-d0a39e111cfe', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Comparative Performance of Fungicides in Management of Phytophthora Root Rot on Boxwood', 'Madhav Parajuli, Sandhya Neupane, Prabha Liyanapathiranage, Fulya Baysal-Gurel', 2023, 'HortScience', 'https://doi.org/10.21273/HORTSCI17227-23', 'https://doi.org/https://doi.org/10.21273/HORTSCI17227-23', 'https://journals.ashs.org/hortsci/view/journals/hortsci/58/8/article-p893.xml', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Nursery growers rely on fungicides to manage root rot disease of boxwood caused by Phytophthora nicotianae and P. cinnamomi. Repeated use of the same fungicide may lead to the fungicide resistance. In this study, fungicides pyraclostrobin + cyazofamid (Empress + Segway), ametoctradin + dimethomorph (Orvego), ametoctradin + dimethomorph alternated with pyraclostrobin (Orvego alt Empress), ametoctradin + dimethomorph alternated with fluxapyroxad + pyraclostrobin (Orvego alt Orkestra), and oxathiapiprolin (Segovis) were evaluated for their efficacy in managing Phytophthora root rot under greenhouse conditions in Tennessee. One-year-old container-grown boxwood ‘Green Velvet’ plants were inoculated with P. nicotianae or P. cinnamomi. The first applications of fungicide treatments were made preventatively as a drench 48 h before pathogen inoculation. Following inoculation, four applications of fungicide treatments were performed on a 14-day intervals. Initial and final plant height and width were measured. Total plant fresh weight and root fresh weight were measured at the end of the trials, and plants were evaluated for root rot severity (0% to 100% roots affected) and pathogen recovery. All fungicides significantly reduced root rot severity and pathogen recovery of P. nicotianae and P. cinnamomi. Ametoctradin + dimethomorph alternated with pyraclostrobin (Orvego alt Empress) provided similar protection against P. cinnamomi to that of a single application of ametoctradin + dimethomorph (Orvego) or oxathiapiprolin (Segovis). For P. nicotianae, ametoctradin + dimethomorph alternated with pyraclostrobin + fluzapyroxad (Orvego alt Orkestra) was found to be as effective as a single application of either ametoctradin + dimethomorph (Orvego) or oxathiapiprolin (Segovis) in one of the two trials. Effects of fungicides on plant growth such as height, width, total, and root fresh weight were not significant. These findings will be useful to nursery growers in selecting the right fungicide program for the management of root rot disease of boxwood caused by P. nicotianae and P. cinnamomi.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9b94cea7-0255-4a45-9da7-8e1711d3f083', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Control Effects of Several Fungicides on Jujube Anthracnose and Fungicide Resistance Monitoring', 'Kyeong Hee Lee, Jiyoung Choi, Subin Park, Heung Tae Kim', 2019, 'Research in Plant Disease', '10.5423/RPD.2019.25.4.188', 'https://doi.org/10.5423/RPD.2019.25.4.188', 'http://www.online-rpd.org/journal/view.html?doi=10.5423/RPD.2019.25.4.188', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'Among 6 fungicides, fluazinam, which had an excellent inhibitory effect on mycelial growth and spore germination, was also effective in controlling jujube anthracnose in the field. While EC50 values of metconazole and tebuconazole ranged from 0.2 to 0.9 μg/ml and from 0.4 to 1.1 μg/ml against the mycelial growth, respectively, each inhibitory effect on spore germination was low by 7.4% and 11.1% at 50.0 μg/ml. In the field test, they showed the control value of 80.5% and 77.0%, respectively. The protective fungicides, as mancozeb and folpet, which had a low inhibitory effect on the mycelial growth, but had a high inhibitory effect of spore germination, showed excellent disease control activities by 87.6% and 92.0% in the field. Showing a result of resistance monitoring conducted with the isolates of Colletotricum gloeosporioides, the resistance against carbendazim was already generated in the field, but it was thought that there was no resistance to pyraclostrobin, fluazinam and tebuconazole. However, if the resistance factor value of the population of C. gloeosporioides isolates to pyraclostrobin was high by 160.4, the diversity of the response to the fungicide in the population was high, so it should be taken more attention to the resistance management.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad1adfd7-10ce-4493-8b07-bfe4599510c6', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Cross-resistance of the pathogenic fungus Alternaria alternata to fungicides with different modes of action', 'Yang LN, He MH, Ouyang HB, Zhu W, Pan ZC, Sui QJ, Shang LP, Zhan J', 2019, 'BMC microbiology', '10.1186/s12866-019-1574-8', 'https://doi.org/10.1186/s12866-019-1574-8', 'https://europepmc.org/articles/PMC6720428?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'BackgroundCross-resistance, a phenomenon that a pathogen resists to one antimicrobial compound also resists to one or several other compounds, is one of major threats to human health and sustainable food production. It usually occurs among antimicrobial compounds sharing the mode of action. In this study, we determined the sensitivity profiles of Alternaria alternata, a fungal pathogen which can cause diseases in many crops to two fungicides (mancozeb and difenoconazole) with different mode of action using a large number of isolates (234) collected from seven potato fields across China.ResultsWe found that pathogens could also develop cross resistance to fungicides with different modes of action as indicated by a strong positive correlation between mancozeb and difenoconazole tolerances to A. alternata. We also found a positive association between mancozeb tolerance and aggressiveness of A. alternata, suggesting no fitness penalty of developing mancozeb resistance in the pathogen and hypothesize that mechanisms such as antimicrobial compound efflux and detoxification that limit intercellular accumulation of natural/synthetic chemicals in pathogens might account for the cross-resistance and the positive association between pathogen aggressiveness and mancozeb tolerance.ConclusionsThe detection of cross-resistance among different classes of fungicides suggests that the mode of action alone may not be an adequate sole criterion to determine what components to use in the mixture and/or rotation of fungicides in agricultural and medical sects. Similarly, the observation of a positive association between the pathogen''s aggressiveness and tolerance to mancozeb suggests that intensive application of site non-specific fungicides might simultaneously lead to reduced fungicide resistance and enhanced ability to cause diseases in pathogen populations, thereby posing a greater threat to agricultural production and human health. In this case, the use of evolutionary principles in closely monitoring populations and the use of appropriate fungicide applications are important for effective use of the fungicides and durable infectious disease management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('14d3bbd0-6cd0-40eb-aa48-fa918a1fcd2f', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Evaluation of the Potential of Pyrimidine Nucleoside Antibiotics Against Alternaria spp. Resistant to QoIs Fungicides: Insights for the Management of Ginseng Alternaria Leaf and Stem Blight Disease', 'Shuai Shao, Mingyuan Hu, Xiaolin Chen, Ming’en Jiang, Changqing Chen, Baohui Lu, Jie Gao', 2025, 'Agriculture', '10.3390/agriculture15080875', 'https://doi.org/10.3390/agriculture15080875', 'https://www.mdpi.com/2077-0472/15/8/875', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'To manage the developing resistance of Alternaria spp. [the causal fungi of ginseng Alternaria leaf and stem blight (GALSB)] to QoIs fungicides, the toxicity and biochemical activity of pyrimidine nucleoside antibiotics (PNA) against Alternaria spp., cross-resistance between PNA and eight other fungicides currently used to control GALSB disease, and the efficacy of PNA for controlling GALSB in vitro and in vivo were investigated. The distributions of EC50 values of PNA against the mycelial growth (115 isolates) and conidia germination (89 isolates) of A. alternata were unimodal, with mean EC50 values of 10.192 ± 4.961 μg/mL and 0.828 ± 0.101 μg/mL, respectively. There were no significant correlations between the sensitivity of A. alternata to PNA and eight other fungicides (p A. alternata mycelia and germ tubes, increased cell membrane permeability, and reduced intracellular DNA and protein levels. On detached ginseng leaves, 300 μg/mL PNA achieved mean protective and curative effects of 87.93% and 94.77% against A. alternata 7 days post-inoculation, outperforming that of 300 μg/mL kresoxim-methyl. Field trial results showed that PNA (180 g a.i./hm2) achieved mean efficacies of 85.63%, 84.07%, and 72.55% at three sites 7, 15, and 30 days after the last spray, which were 5.28–37.74% higher than those of control fungicides pyraclostrobin, azoxystrobin, and kresoxim-methyl at corresponding time points. Overall, our findings indicate that PNA are effective agents for the management of Alternaria spp. resistance to QoIs fungicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('788b9570-55d4-40d2-8be6-883a8685c9a8', '803905f3-9270-42c3-886f-742ece7e1135', 'The Remarkable Journey of a Weed: Biology and Management of Annual Ryegrass (Lolium rigidum) in Conservation Cropping Systems of Australia', 'Bajwa AA, Latif S, Borger C, Iqbal N, Asaduzzaman M, Wu H, Walsh M', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10081505', 'https://doi.org/10.3390/plants10081505', 'https://europepmc.org/articles/PMC8400064?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Annual ryegrass (Lolium rigidum Gaud.), traditionally utilised as a pasture species, has become the most problematic and difficult-to-control weed across grain production regions in Australia. Annual ryegrass has been favoured by the adoption of conservation tillage systems due to its genetic diversity, prolific seed production, widespread dispersal, flexible germination requirements and competitive growth habit. The widespread evolution of herbicide resistance in annual ryegrass has made its management within these systems extremely difficult. The negative impacts of this weed on grain production systems result in annual revenue losses exceeding $93 million (AUD) for Australian grain growers. No single method of management provides effective and enduring control hence the need of integrated weed management programs is widely accepted and practiced in Australian cropping. Although annual ryegrass is an extensively researched weed, a comprehensive review of the biology and management of this weed in conservation cropping systems has not been conducted. This review presents an up-to-date account of knowledge on the biology, ecology and management of annual ryegrass in an Australian context. This comprehensive account provides pragmatic information for further research and suitable management of annual ryegrass.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('804e413d-ba3e-4ce7-ac5e-5ac4b5cce67d', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Fungicide Sensitivity Shifting of Zymoseptoria tritici in the Finnish-Baltic Region and a Novel Insertion in the MFS1 Promoter', 'Mäe A, Fillinger S, Sooväli P, Heick TM', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00385', 'https://doi.org/10.3389/fpls.2020.00385', 'https://europepmc.org/articles/PMC7174668?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Septoria tritici blotch (STB) is caused by the ascomycete Zymoseptoria tritici and one of the predominating diseases in wheat (Triticum aestivum) in Europe. The control of STB is highly reliant on frequent fungicide applications. The primary objective of this study was to assess sensitivity levels of Z. tritici to different fungicide groups. The fungicides included in this study were epoxiconazole, prothioconazole-desthio, tebuconazole, and fluxapyroxad. A panel of 63 isolates from Estonia, Latvia, and Lithuania, and 10 isolates from Finland were tested. Fungicide sensitivity testing was carried out as a bioassay analyzing single pycnidium isolates on different fungicide concentrations. The average EC50 value in Baltic countries and Finland to epoxiconazole was high ranging from 1.04 to 2.19 ppm. For prothioconazole-desthio and tebuconazole, EC50 varied from 0.01 to 0.24 ppm, and 1.25 to 18.23 ppm, respectively. The average EC50 value for fluxapyroxad varied from 0.07 to 0.33 ppm. To explain the range of sensitivity, the samples were analyzed for CYP51 and Sdh mutations, as well as cytb G143A, CYP51 overexpression, and multidrug resistance (MDR). Frequencies of ZtCYP51 mutations D134G, V136A/C, A379G, I381V, and S524T in the Finnish-Baltic region were lower than in other European countries, but have increased compared to previous years. The frequency of cytb G143A conferring strobilurin resistance also augmented to 50-70% in the Z. tritici populations from Estonia, Finland, Latvia, and Lithuania. No Sdh mutations were found in this study, and neither strains of MDR phenotypes. However, we found a strain harboring a previously unknown transposon insertion in the promoter of the MFS1 gene, involved in drug efflux and multi-drug resistance. This new insert, however, does not confer an MDR phenotype to the strain.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9782fcfe-07e8-4994-aa5f-23e2d89b9e6a', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Multiple and multidrug resistance in Botrytis cinerea: molecular mechanisms of MLR/MDR strains in Greece and effects of co-existence of different resistance mechanisms on fungicide sensitivity', 'Georgios Sofianos, Anastasios Samaras, Georgios Karaoglanidis', 2023, 'Frontiers in Plant Science', '10.3389/fpls.2023.1273193', 'https://doi.org/10.3389/fpls.2023.1273193', 'https://www.frontiersin.org/articles/10.3389/fpls.2023.1273193/full', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'Botrytis cinerea is a high-risk pathogen for fungicide resistance development. Within the fungal populations, strains have developed multiple mutations in different target genes leading to multiple resistance (MLR) or mutations associated with overexpression of efflux transporters leading to multidrug resistance (MDR). These types of resistance are a major threat, and their successful management is a major challenge. The current study was initiated to a) determine frequencies of MLR/MDR strains in populations originating from several crops, b) identify the types of MDR that occur in Greece, and c) determine interactions between MLR and MDR at the level of sensitivity to botryticides. The frequencies of MLR/MDR phenotypes were determined in 515 isolates subjected to bioassays using discriminatory concentrations of thiophanate-methyl, iprodione, cyprodinil, fenhexamid, boscalid, fluopyram, fludioxonil, pyraclostrobin, and tolnaftate. Interestingly, 7.8% and 31.3% of isolates from strawberry and rootstock seedlings were resistant to every single fungicide class, while MDR phenotypes from strawberries, rootstocks, and tomatoes accounted for 26%, 87%, and 13.4%, respectively. The MLR and MDR isolates were further molecularly analyzed regarding genes erg27, sdhB, Bcpos5, and Mrr1, responsible for resistance to fenhexamid, boscalid and fluopyram, cyprodinil, and MDR, respectively. The different mutations’ presence was determined along with a new mutation in Mrr1 leading to MDR. MDR isolates were characterized as MDR1 or MDR1h based on the presence of a 3-bp deletion in Mrr1. MDR1h was predominant in isolates from rootstocks and MDR1 from tomatoes and strawberries, whereas the most frequent target-site mutations were F412S (erg27), H272R (sdhB), and L412F (Bcpos5). To determine whether the accumulation of target-site mutations along with MDR mutations exhibits an additive effect concerning fungicide resistance, the sensitivity of isolates possessing the predominant target-site mutations was calculated in both the presence and the absence of MDR-associated mutations. EC50 in cyprodinil and boscalid increased to about twofold in the presence of MDR mutations, while there was no difference for fenhexamid. In conclusion, MLR/MDR frequencies are notably high in heavily treated crops in Greece, and the combination of MLR and MDR mutations leads to even higher fungicide resistance levels, highlighting the importance of resistance management.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5c9edc7e-6fa2-4fe6-8355-9fd69a79adfa', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Grapevine Powdery Mildew: Fungicides for Its Management and Advances in Molecular Detection of Markers Associated with Resistance', 'Kunova A, Pizzatti C, Saracchi M, Pasquali M, Cortesi P', 2021, 'Microorganisms', '10.3390/microorganisms9071541', 'https://doi.org/10.3390/microorganisms9071541', 'https://europepmc.org/articles/PMC8307186?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Grapevine powdery mildew is a principal fungal disease of grapevine worldwide. Even though it usually does not cause plant death directly, heavy infections can lead to extensive yield losses, and even low levels of the disease can negatively affect the quality of the wine. Therefore, intensive spraying programs are commonly applied to control the disease, which often leads to the emergence and spread of powdery mildew strains resistant to different fungicides. In this review, we describe major fungicide classes used for grapevine powdery mildew management and the most common single nucleotide mutations in target genes known to confer resistance to different classes of fungicides. We searched the current literature to review the development of novel molecular methods for quick detection and monitoring of resistance to commonly used single-site fungicides against Erysiphe necator. We analyze and compare the developed methods. From our investigation it became evident that this research topic has been strongly neglected and we hope that effective molecular methods will be developed also for resistance monitoring in biotroph pathogens.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b83fbe8e-ac5c-4131-8244-14b7aa725ac5', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Green Synthesized Silver Nanoparticles: A Novel Approach for the Enhanced Growth and Yield of Tomato against Early Blight Disease', 'Ansari M, Ahmed S, Abbasi A, Hamad NA, Ali HM, Khan MT, Haq IU, Zaman QU', 2023, 'Microorganisms', '10.3390/microorganisms11040886', 'https://doi.org/10.3390/microorganisms11040886', 'https://europepmc.org/articles/PMC10145257?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Tomato plants are among the most widely cultivated and economically important crops worldwide. Farmers'' major challenge when growing tomatoes is early blight disease caused by Alternaria solani, which results in significant yield losses. Silver nanoparticles (AgNPs) have gained popularity recently due to their potential antifungal activity. The present study investigated the potential of green synthesized silver nanoparticles (AgNPs) for enhancing the growth and yield of tomato plants and their resistance against early blight disease. AgNPs were synthesized using leaf extract of the neem tree. Tomato plants treated with AgNPs showed a significant increase in plant height (30%), number of leaves, fresh weight (45%), and dry weight (40%) compared to the control plants. Moreover, the AgNP-treated plants exhibited a significant reduction in disease severity index (DSI) (73%) and disease incidence (DI) (69%) compared to the control plants. Tomato plants treated with 5 and 10 ppm AgNPs reached their maximum levels of photosynthetic pigments and increased the accumulation of certain secondary metabolites compared to the control group. AgNP treatment improved stress tolerance in tomato plants as indicated by higher activities of antioxidant enzymes such as PO (60%), PPO (65%), PAL (65.5%), SOD (65.3%), CAT (53.8%), and APX (73%). These results suggest that using green synthesized AgNPs is a promising approach for enhancing the growth and yield of tomato plants and protecting them against early blight disease. Overall, the findings demonstrate the potential of nanotechnology-based solutions for sustainable agriculture and food security.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d844add1-1c99-4412-b32f-c84695525036', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Integrated Management Strategies for Blackleg Disease of Canola Amidst Climate Change Challenges', 'Razzaq K, Del Río Mendoza LE, Babakhani B, Azizi A, Razzaq H, Rahman M', 2025, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof11070514', 'https://doi.org/10.3390/jof11070514', 'https://europepmc.org/articles/PMC12295924?pdf=render', NULL, NULL, 24, NULL, 'northern_plains', 3, 'cc by', 'Blackleg caused by a hemi-biotrophic fungus Plenodomus lingam (syn. Leptosphaeria maculans) poses a significant threat to global canola production. Changing climatic conditions further exacerbate the intensity and prevalence of blackleg epidemics. Shifts in temperature, humidity, and precipitation patterns can enhance pathogen virulence and disease spread. This review synthesizes the knowledge on integrated disease management (IDM) approaches for blackleg, including crop rotation, resistant cultivars, and chemical and biological controls, with an emphasis on advanced strategies such as disease forecasting models, remote sensing, and climate-adapted breeding. Notably, bibliometric analysis reveals an increasing research focus on the intersection of blackleg, climate change, and sustainable disease management. However, critical research gaps remain, which include the lack of region-specific forecasting models, the limited availability of effective biological control agents, and underexplored socio-economic factors limiting farmer adoption of IDM. Additionally, the review identifies an urgent need for policy support and investment in breeding programs using emerging tools like AI-driven decision support systems, CRISPR/Cas9, and gene stacking to optimize fungicide use and resistance deployment. Overall, this review highlights the importance of coordinated, multidisciplinary efforts, integrating plant pathology, breeding, climate modeling, and socio-economic analysis to develop climate-resilient, locally adapted, and economically viable IDM strategies for sustainable canola production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('62f6cc84-ac59-4ac0-96c3-a63cb108719d', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Metyltetraprole, a novel putative complex III inhibitor, targets known QoI-resistant strains of Zymoseptoria tritici and Pyrenophora teres', 'Suemoto H, Matsuzaki Y, Iwahashi F', 2019, 'Pest management science', '10.1002/ps.5288', 'https://doi.org/10.1002/ps.5288', 'https://europepmc.org/articles/PMC6590148?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'BackgroundMetyltetraprole is a new fungicide with a unique tetrazolinone-moiety and a similar side chain to a known quinone outside inhibitor (QoI), pyraclostrobin. In this study we describe a unique bioactivity of metyltetraprole on QoI-resistant strains of Zymoseptoria tritici and Pyrenophora teres.ResultsMetyltetraprole exhibited potent antifungal activity against Ascomycetes; it was especially effective against Z. tritici and P. teres in seedling pot tests. Metyltetraprole was also effective in field tests with QoI-resistant mutants. Antifungal activity tests using field strains of Z. tritici and P. teres showed that the performance of metyltetraprole was unaltered by QoI, succinate dehydrogenase inhibitor (SDHI), and sterol 14α-demethylation inhibitor (DMI) resistance. However, the mitochondrial activity test indicated that the compound inhibits the respiratory chain via complex III.ConclusionMetyltetraprole is a novel fungicide that is highly effective against a wide range of fungal diseases, including important cereal diseases. Although metyltetraprole most likely inhibits the respiratory chain via complex III, it remains effective against QoI resistant strains. Therefore, metyltetraprole is considered as a novel fungicidal agent for controlling diseases affecting cereal crops and overcoming pathogen resistance to existing fungicides. © 2018 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf811aed-9dce-4749-a846-7a60d058b30e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', '2011 North Dakota Weed Control Guide', 'Richard K. Zollinger', 2011, 'NDSU Repository (North Dakota State University)', NULL, 'http://hdl.handle.net/10365/14266', 'http://hdl.handle.net/10365/14266', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6e7bdd8e-45b7-4f45-984a-b2a5444765ac', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Molecular characterization and overexpression of the difenoconazole resistance gene CYP51 in Lasiodiplodia theobromae field isolates', 'Chenguang Wang, Luxi Xu, Xiaoyu Liang, Jing Wang, Xinwei Xian, Yu Zhang, Ye Yang', 2021, 'Scientific Reports', '10.1038/s41598-021-03601-4', 'https://doi.org/10.1038/s41598-021-03601-4', 'https://doi.org/10.1038/s41598-021-03601-4', NULL, NULL, 10, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Stem-end rot (SER) caused by Lasiodiplodia theobromae is an important disease of mango in China. Demethylation inhibitor (DMI) fungicides are widely used for disease control in mango orchards. The baseline sensitivity to difenoconazole of 138 L. theobromae isolates collected from mango in the field in 2019 was established by the mycelial growth rate method. The cross-resistance to six site-specific fungicides with different modes of action were investigated using 20 isolates randomly selected. The possible mechanism for L. theobromae resistance to difenoconazole was preliminarily determined through gene sequence alignment and quantitative real-time PCR analysis. The results showed that the EC50 values of 138 L. theobromae isolates to difenoconazole ranged from 0.01 to 13.72 µg/mL. The frequency of difenoconazole sensitivity formed a normal distribution curve when the outliers were excluded. Difenoconazole showed positive cross-resistance only with the DMI tebuconazole but not with non-DMI fungicides carbendazim, pyraclostrobin, fludioxonil, bromothalonil, or iprodione. Some multifungicide-resistant isolates of L. theobromae were found. Two amino acid substitutions (E209k and G207A) were found in the CYP51 protein, but they were unlikely to be related to the resistance phenotype. There was no alteration in the promoter region of the CYP51 gene. However, difenoconazole significantly increased the expression of the CYP51 gene in the resistant isolates compared to the susceptible isolates. These results are vital to develop effective mango disease management strategies to avoid the development of further resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('083aa874-1eb5-4e6e-9283-0d691117cf93', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Novel Alleles from Cicer reticulatum L. for Genetic Improvement of Cultivated Chickpeas Identified through Genome Wide Association Analysis', 'Rahman MW, Deokar AA, Lindsay D, Tar''an B', 2024, 'International journal of molecular sciences', '10.3390/ijms25010648', 'https://doi.org/10.3390/ijms25010648', 'https://europepmc.org/articles/PMC10779240?pdf=render', NULL, NULL, 28, NULL, 'prairies', 4, 'cc by', 'The availability of wild chickpea (Cicer reticulatum L.) accessions has the potential to be used for the improvement of important traits in cultivated chickpeas. The main objectives of this study were to evaluate the phenotypic and genetic variations of chickpea progeny derived from interspecific crosses between C. arietinum and C. reticulatum, and to establish the association between single nucleotide polymorphism (SNP) markers and a series of important agronomic traits in chickpea. A total of 486 lines derived from interspecific crosses between C. arietinum (CDC Leader) and 20 accessions of C. reticulatum were evaluated at different locations in Saskatchewan, Canada in 2017 and 2018. Significant variations were observed for seed weight per plant, number of seeds per plant, thousand seed weight, and plant biomass. Path coefficient analysis showed significant positive direct effects of the number of seeds per plant, thousand seed weight, and biomass on the total seed weight. Cluster analysis based on the agronomic traits generated six groups that allowed the identification of potential heterotic groups within the interspecific lines for yield improvement and resistance to ascochyta blight disease. Genotyping of the 381 interspecific lines using a modified genotyping by sequencing (tGBS) generated a total of 14,591 SNPs. Neighbour-joining cluster analysis using the SNP data grouped the lines into 20 clusters. The genome wide association analysis identified 51 SNPs that had significant associations with different traits. Several candidate genes associated with early flowering and yield components were identified. The candidate genes and the significant SNP markers associated with different traits have a potential to aid the trait introgression in the breeding program.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4b673a28-6cff-4b93-807d-d951235e9e1b', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Physiological Basis of Genotypic Response to Management in Dryland Wheat', 'de Oliveira Silva A, Slafer GA, Fritz AK, Lollato RP', 2019, 'Frontiers in plant science', '10.3389/fpls.2019.01644', 'https://doi.org/10.3389/fpls.2019.01644', 'https://europepmc.org/articles/PMC6967739?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'A great majority of dryland wheat producers are reluctant to intensify management due to the assumption that lack of water availability is the most critical factor limiting yield and thus, the response to management intensification would be limited. We conducted on-farm field experiments across three locations and two growing seasons in Kansas using 21 modern winter wheat genotypes grown under either standard (SM) or intensified management (IM) systems. The goals of this study were to (i) determine whether the SM adopted is adequate to reach achievable yields by farmers in the region and (ii) identify differences in responsiveness to IM among a range of modern genotypes. Across all sites-years and genotypes, the IM increased yield by 0.9 Mg ha-1, outyielding the SM system even in the lowest yielding conditions. As expected, the yield response to IM increased with the achievable yield of the environment and genotype. Across all sources of variation, the yield responsiveness to IM was related to increased biomass rather than harvest index, strongly driven by improvements in grain number (and independent of changes in grain weight), and by improvements in N uptake which resulted from greater biomass and shoot N concentration. The IM system generally also increased grain N concentration and decreased the grain N dilution effect from increased yield. Genotypes varied in their response to IM, with major response patterns resulting from the combination of response magnitude (large vs. small) and consistency (variable vs. consistent). Genotypes with high mean response and high variability in the response to IM across years could offer greater opportunities for producers to maximize yield as those genotypes showed greater yield gain from IM when conditions favored their response. For the background conditions evaluated, intensifying management could improve wheat yield in between c. 0.2 and 1.5 Mg ha-1 depending on genotype.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('798d9fed-fed6-456f-9d99-29dc820c8cd7', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Residual and Systemic Efficacy of Chlorantraniliprole and Flubendiamide Against Corn Earworm (Lepidoptera: Noctuidae) in Soybean', 'Adams A, Gore J, Catchot A, Musser F, Cook D, Krishnan N, Irby T', 2016, 'Journal of economic entomology', '10.1093/jee/tow210', 'https://doi.org/10.1093/jee/tow210', 'https://europepmc.org/articles/PMC5225962?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by-nc', 'Experiments were conducted in Mississippi from 2013 to 2015 to determine the systemic and residual efficacy of chlorantraniliprole and flubendiamide against corn earworm, Helicoverpa zea (Boddie), in soybean. Both insecticides were applied at V4 and R3. Ten leaves that were present at the time of application and 10 newly emerged leaves that were not present at the time of application were collected to measure residual and systemic efficacy, respectively. Ten pods were removed from each plot at R5.5. For all assays, corn earworm larvae were placed on plant material. Chlorantraniliprole appeared to provide systemic control of H. zea, but was dependent on soybean growth stage at the time of application. In the V4 experiment, chlorantraniliprole resulted in greater mortality than the control on new leaves at 7 d after treatment, but not at 14 d. In the R3 experiment, chlorantraniliprole resulted in greater than 90% mortality on new leaves at all evaluation intervals. Mortality of H. zea on new leaves was <17% for flubendiamide and was not different than the control. Both insecticides resulted in significant mortality of H. zea on leaves that were present at the time of application for at least 31 d after application. Chlorantraniliprole resulted in greater mortality than flubendiamide at 24 and 31 d. Neither insecticide resulted in mortality of H. zea feeding on reproductive structures. These results suggest that chlorantraniliprole moves to new vegetative structures but not to reproductive structures of soybean, and that flubendiamide does not move systemically.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b4ee615f-4ad8-4a23-9167-bcef0bab99a5', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Resistance of Black Aspergilli Species from Grape Vineyards to SDHI, QoI, DMI, and Phenylpyrrole Fungicides', 'Stefanos I. Testempasis, George S. Karaoglanidis', 2023, 'Journal of Fungi', '10.3390/jof9020221', 'https://doi.org/10.3390/jof9020221', 'https://www.mdpi.com/2309-608X/9/2/221', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Fungicide applications constitute a management practice that reduces the size of fungal populations and by acting as a genetic drift factor, may affect pathogen evolution. In a previous study, we showed that the farming system influenced the population structure of the Aspergillus section Nigri species in Greek vineyards. The current study aimed to test the hypothesis that the differences in the population structure may be associated with the selection of fungicide-resistant strains within the black aspergilli populations. To achieve this, we determined the sensitivity of 102, 151, 19, and 22 for the A. uvarum, A. tubingensis, A. niger, and A. carbonarious isolates, respectively, originating either from conventionally-treated or organic vineyards to the fungicides fluxapyroxad-SDHIs, pyraclostrobin-QoIs, tebuconazole-DMIs, and fludioxonil-phenylpyrroles. The results showed widespread resistance to all four fungicides tested in the A. uvarum isolates originating mostly from conventional vineyards. In contrast, all the A. tubingensis isolates tested were sensitive to pyraclostrobin, while moderate frequencies of only lowly resistant isolates were identified for tebuconazole, fludioxonil, and fluxapyroxad. Sequencing analysis of the corresponding fungicide target encoding genes revealed the presence of H270Y, H65Q/S66P, and G143A mutations in the sdhB, sdhD, and cytb genes of A. uvarum resistant isolates, respectively. No mutations in the Cyp51A and Cyp51B genes were detected in either the A. uvarum or A. tubingensis isolates exhibiting high or low resistance levels to DMIs, suggesting that other resistance mechanisms are responsible for the observed phenotype. Our results support the initial hypothesis for the contribution of fungicide resistance in the black aspergilli population structure in conventional and organic vineyards, while this is the first report of A. uvarum resistance to SDHIs and the first documentation of H270Y or H65Q/S66P mutations in sdhB, sdhD, and of the G143A mutation in the cytb gene of this fungal species.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b1b469b-5ee2-4db6-9848-e02dec55cd5a', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'The role of ROS signaling in cross-tolerance: from model to crop', 'Perez IB, Brown PJ', 2014, 'Frontiers in plant science', '10.3389/fpls.2014.00754', 'https://doi.org/10.3389/fpls.2014.00754', 'https://europepmc.org/articles/PMC4274871?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by', 'Reactive oxygen species (ROS) are key signaling molecules produced in response to biotic and abiotic stresses that trigger a variety of plant defense responses. Cross-tolerance, the enhanced ability of a plant to tolerate multiple stresses, has been suggested to result partly from overlap between ROS signaling mechanisms. Cross-tolerance can manifest itself both as a positive genetic correlation between tolerance to different stresses (inherent cross-tolerance), and as the priming of systemic plant tolerance through previous exposure to another type of stress (induced cross-tolerance). Research in model organisms suggests that cross-tolerance could be used to benefit the agronomy and breeding of crop plants. However, research under field conditions has been scarce and critical issues including the timing, duration, and intensity of a stressor, as well as its interactions with other biotic and abiotic factors, remain to be addressed. Potential applications include the use of chemical stressors to screen for stress-resistant genotypes in breeding programs and the agronomic use of chemical inducers of plant defense for plant protection. Success of these applications will rely on improving our understanding of how ROS signals travel systemically and persist over time, and of how genetic correlations between resistance to ROS, biotic, and abiotic stresses are shaped by cooperative and antagonistic interactions within the underlying signaling pathways.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f6629bc5-3757-46e9-8f29-63297476b338', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Rhizoctonia solani Kühn Pathophysiology: Status and Prospects of Sheath Blight Disease Management in Rice', 'Senapati M, Tiwari A, Sharma N, Chandra P, Bashyal BM, Ellur RK, Bhowmick PK, Bollinedi H', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.881116', 'https://doi.org/10.3389/fpls.2022.881116', 'https://europepmc.org/articles/PMC9111526?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Sheath blight caused by necrotrophic fungus Rhizoctonia solani Kühn is one of the most serious diseases of rice. Use of high yielding semi dwarf cultivars with dense planting and high dose of nitrogenous fertilizers accentuates the incidence of sheath blight in rice. Its diverse host range and ability to remain dormant under unfavorable conditions make the pathogen more difficult to manage. As there are no sources of complete resistance, management through chemical control has been the most adopted method for sheath blight management. In this review, we provide an up-to-date comprehensive description of host-pathogen interactions, various control measures such as cultural, chemical, and biological as well as utilizing host plant resistance. The section on utilizing host plant resistance includes identification of resistant sources, mapping QTLs and their validation, identification of candidate gene(s) and their introgression through marker-assisted selection. Advances and prospects of sheath blight management through biotechnological approaches such as overexpression of genes and gene silencing for transgenic development against R. solani are also discussed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3a523391-4de9-47da-a73d-9532531baa99', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Scientific evidence of sustainable plant disease protection strategies for oilseed rape (Brassica napus) in Sweden: a systematic map', 'Wallenhammar AC, Vilvert E, Bergqvist S, Olson Å, Berlin A', 2022, 'Environmental evidence', '10.1186/s13750-022-00277-9', 'https://doi.org/10.1186/s13750-022-00277-9', 'https://europepmc.org/articles/PMC11378781?pdf=render', NULL, NULL, 20, NULL, 'canada', 3, 'cc by', 'BackgroundOilseed rape (OSR; Brassica napus L.) is a highly valued crop for food, feed and industrial use. It is primarily grown in temperate climates, and over recent decades, its area of production and profitability have increased. Concurrently, several diseases negatively impact OSR production. Diseases caused by soil-borne pathogens, pose a risk of substantial yield loss since crop rotation schemes have become narrow as the time lapse between OSR crops in a field has been shortened. The aims of this paper were to provide an overview of plant protection measures available for OSR production and to identify knowledge gaps and areas where more research is needed.MethodsThis systematic map builds on a previously published protocol and follows the ROSES reporting standard. The search strategy was developed in collaboration with stakeholders and designed to cover available scientific evidence for OSR disease management in climate zones relevant for Scandinavian crop production (Dfc, Dfb, Cfb and Cfa in the Köppen-Geiger climate classification). Five scientific databases were used to identify peer-reviewed literature, complemented by additional searches performed in grey literature. Articles were screened at three stages: the title, abstract and full text. The eligible publications included studies of OSR crops, and all measures to control crop disease in agricultural fields were considered eligible interventions. The comparator was intervention and no intervention, and the yield per unit area, disease suppression or an increase in crop quality were determined to be outcomes of interventions. A basic assessment of the experimental design of each study was performed to assess its eligibility. All articles were coded based on the following categories: the location and climate zone, disease, pathogen, intervention and management method, outcome and study design. Articles not reporting original data but judged to be relevant (i.e., review papers, books and notes of registration of cultivars) were saved in a separate category called "books, reviews and reports".Review findingsA total of 4633 articles were collected through systematic searches. After duplicates were removed, 3513 articles were included in the screening process. After screening at the title and abstract levels, 897 articles were evaluated at the full text level, and 118 articles comprised the studies that met the eligibility criteria of the systematic map. The country (Canada) and region (Europe) with the largest OSR crop production areas also contributed the highest number of articles. In total, 17 different diseases were reported, with black leg (syn. Phoma stem canker) being the most studied disease. Nineteen different intervention methods or management types were examined. Cultivar resistance and pesticide application were the most studied control measures.ConclusionWe report scientific studies on plant disease protection measures for OSR based on field trials where the results are intended to be directly implemented in crop production management. The map clearly provides an overview of research progress throughout the time period chosen, and it identifies knowledge gaps regarding important diseases where only a few studies have been published, for example, diseases caused by viruses.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2f54a277-cb5d-4754-8d6e-917e968b6bdb', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Seed Treatment With Systemic Fungicides: Time for Review', 'Ayesha MS, Suryanarayanan TS, Nataraja KN, Prasad SR, Shaanker RU', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.654512', 'https://doi.org/10.3389/fpls.2021.654512', 'https://europepmc.org/articles/PMC8365024?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Pre-sowing seed treatment with systemic fungicides is a firmly entrenched practice for most agricultural crops worldwide. The treatment is intended to protect the crop against seed- and soil-borne diseases. In recent years, there is increasing evidence that fungicidal applications to manage diseases might inadvertently also affect non-target organisms, such as endophytes. Endophytes are ubiquitously present in plants and contribute to plant growth and development besides offering resistance to biotic and abiotic stresses. In seeds, endophytes may play a role in seed development, seed germination, seedling establishment and crop performance. In this paper, we review the recent literature on non-target effects of fungicidal applications on endophytic fungal community and discuss the possible consequences of indiscriminate seed treatment with systemic fungicide on seed endophytes. It is now well recognized that endophytes are ubiquitously present in all parts of the plant, including the seeds. They may be transmitted vertically from seed to seed as in many grasses and/or acquired horizontally from the soil and the environment. Though the origins and evolution of these organisms in plants are a matter of conjecture, numerous studies have shown that they symbiotically aid in plant growth and development, in nutrient acquisition as well in protecting the plants from abiotic and biotic stresses. Against this background, it is reasonable to assume that the use of systemic fungicides in seed treatment may not only affect the seed endophytes but also their attendant benefits to seedling growth and establishment. While there is evidence to indicate that fungicidal applications to manage plant diseases also affect foliar endophytes, there are only few studies that have documented the effect of seed treatment on seed-borne endophytes. Some of the convincing examples of the latter come from studies on the effect of fungicide application on rye grass seed endophyte AR37. More recently, experiments have shown that removal of seed endophytes by treatment with systemic fungicides leads to significant loss of seedling vigour and that such losses could be partially restored by enriching the seedlings with the lost endophytes. Put together, these studies reinforce the importance of seed endophytes to seedling growth and establishment and draw attention on how to trade the balance between the benefits of seed treatments and the direct and indirect costs incurred due to loss of endophytes. Among several approaches, use of reduced-risk fungicides and identifying fungicide-resistant endophytes are suggested to sustain the endophyte contribution to early seedling growth.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('73e86bef-4e2f-4bc9-8072-eaa3c8fdff40', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Sensitivity of Lithuanian Zymoseptoria tritici to Quinone Outside Inhibitor and Succinate Dehydrogenase Inhibitor Fungicides', 'Karolina Lavrukaitė, Mohammad Almogdad, Jūratė Ramanauskienė, Aurimas Sabeckis', 2024, 'Agronomy', '10.3390/agronomy14040813', 'https://doi.org/10.3390/agronomy14040813', 'https://www.mdpi.com/2073-4395/14/4/813', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Septoria tritici blotch (STB) ais one of the most damaging winter wheat diseases worldwide, presenting a significant threat to its yields. The causal STB agent, Zymoseptoria tritici, also presents a challenge to control due to its rapid adaptation to fungicides. This requires researchers to continuously monitor the pathogen and investigate and explore strategies to manage the spread of the disease and the development of resistance in the pathogen. Therefore, this study presents the current situation and describes changes in the sensitivity of Z. tritici isolates from Lithuania to quinone outside inhibitors (QoIs) and succinate dehydrogenase inhibitors (SDHIs) for the years 2019–2022. The isolates were tested at five different concentrations of two QoI fungicides (azoxystrobin and pyraclostrobin) and three SDHI fungicides (fluxapyroxad, benzovindiflupyr, and bixafen). During the test period, the EC50 values of the tested QoIs increased, while no clear changes were observed in the SDHIs. The most pronounced shift was observed for the active QoI substance pyraclostrobin. The distribution of the EC50 values of the SDHI fungicides showcased one isolate with an outstandingly high EC50 value of 2.6 mg L−1. The results of this study did not reveal any strong patterns of cross-resistance between the fungicides tested. However, a significant positive, moderate correlation (r = 0.55) was found between fluxapyroxad and benzovindiflupyr. Overall, the results of this study contribute to the understanding of the fungicide-resistance situation of Z. tritici in Lithuania and may complement management strategies for the pathogen and its fungicide resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46af6ad7-b052-459e-8915-ca4b1d1324dc', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'The Arabidopsis non-host defence-associated coumarin scopoletin protects soybean from Asian soybean rust', 'Beyer SF, Beesley A, Rohmann PFW, Schultheiss H, Conrath U, Langenbach CJG', 2019, 'The Plant journal : for cell and molecular biology', '10.1111/tpj.14426', 'https://doi.org/10.1111/tpj.14426', 'https://europepmc.org/articles/PMC6852345?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The fungus Phakopsora pachyrhizi (Pp) causes Asian soybean rust (SBR) disease which provokes tremendous losses in global soybean production. Pp is mainly controlled with synthetic fungicides to which the fungus swiftly develops fungicide resistance. To substitute or complement synthetic fungicides in Asian soybean rust control, we aimed to identify antifungal metabolites in Arabidopsis which is not a host for Pp. Comparative transcriptional and metabolic profiling of the Pp-inoculated Arabidopsis non-host and the soybean host revealed induction of phenylpropanoid metabolism-associated genes in both species but activation of scopoletin biosynthesis only in the resistant non-host. Scopoletin is a coumarin and an antioxidant. In vitro experiments disclosed fungistatic activity of scopoletin against Pp, associated with reduced accumulation of reactive oxygen species (ROS) in fungal pre-infection structures. Non-antioxidant and antioxidant molecules including coumarins with a similar structure to scopoletin were inactive or much less effective at inhibiting fungal accumulation of ROS and germination of Pp spores. When sprayed onto Arabidopsis leaves, scopoletin also suppressed the formation of Pp pre-infection structures and penetration of the plant. However, scopoletin neither directly activated defence nor did it prime Arabidopsis for enhanced defence, therefore emphasizing fungistatic activity as the exclusive mode of action of scopoletin against Pp. Because scopletin also protected soybean from Pp infection, the coumarin may serve as a natural fungicide or as a lead for the development of near-to-nature fungicides against Asian soybean rust.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce593c9c-e7db-418c-8c21-dda985b6e7ee', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'The Detection and Characterization of QoI-Resistant Didymella rabiei Causing Ascochyta Blight of Chickpea in Montana', 'Ayodeji S. Owati, Bright Agindotan, Julie S. Pasche, Mary Burrows', 2017, 'Frontiers in Plant Science', '10.3389/fpls.2017.01165', 'https://doi.org/10.3389/fpls.2017.01165', 'http://journal.frontiersin.org/article/10.3389/fpls.2017.01165/full', NULL, NULL, 11, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Ascochyta blight (AB) of pulse crops (chickpea, field pea, and lentils) causes yield loss in Montana, where 1.2 million acres was planted to pulses in 2016. Pyraclostrobin and azoxystrobin, quinone outside inhibitor (QoI) fungicides, have been the choice of farmers for the management of AB in pulses. However, a G143A mutation in the cytochrome b gene has been reported to confer resistance to QoI fungicides. A total of 990 isolates of AB-causing fungi were isolated and screened for QoI resistance. Out of these, 10% were isolated from chickpea, 81% were isolated from field peas, and 9% isolated from lentil. These were from a survey of grower’s fields and seed lots (chickpea = 17, field pea = 131, and lentil = 21) from 23 counties in Montana sent to the Regional Pulse Crop Diagnostic Laboratory, Bozeman, MT, United States for testing. Fungicide-resistant Didymella rabiei isolates were found in one chickpea seed lot each sent from Daniels, McCone and Valley Counties, MT, from seed produced in 2015 and 2016. Multiple alignment analysis of amino acid sequences showed a missense mutation that replaced the codon for amino acid 143 from GGT to GCT, introducing an amino acid change from glycine to alanine (G143A), which is reported to be associated with QoI resistance. Under greenhouse conditions, disease severity was significantly higher on pyraclostrobin-treated chickpea plants inoculated with QoI-resistant isolates of D. rabiei than sensitive isolates (p-value = 0.001). This indicates that where resistant isolates are located, fungicide failures may be observed in the field. D. rabiei-specific polymerase chain reaction primer sets and hydrolysis probes were developed to efficiently discriminate QoI- sensitive and - resistant isolates.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2023b578-334e-4610-8f57-6d2b85e532fb', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Transport of Nanoparticles into Plants and Their Detection Methods', 'Sembada AA, Lenggoro IW', 2024, 'Nanomaterials (Basel, Switzerland)', '10.3390/nano14020131', 'https://doi.org/10.3390/nano14020131', 'https://europepmc.org/articles/PMC10819755?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Nanoparticle transport into plants is an evolving field of research with diverse applications in agriculture and biotechnology. This article provides an overview of the challenges and prospects associated with the transport of nanoparticles in plants, focusing on delivery methods and the detection of nanoparticles within plant tissues. Passive and assisted delivery methods, including the use of roots and leaves as introduction sites, are discussed, along with their respective advantages and limitations. The barriers encountered in nanoparticle delivery to plants are highlighted, emphasizing the need for innovative approaches (e.g., the stem as a new recognition site) to optimize transport efficiency. In recent years, research efforts have intensified, leading to an evendeeper understanding of the intricate mechanisms governing the interaction of nanomaterials with plant tissues and cells. Investigations into the uptake pathways and translocation mechanisms within plants have revealed nuanced responses to different types of nanoparticles. Additionally, this article delves into the importance of detection methods for studying nanoparticle localization and quantification within plant tissues. Various techniques are presented as valuable tools for comprehensively understanding nanoparticle-plant interactions. The reliance on multiple detection methods for data validation is emphasized to enhance the reliability of the research findings. The future outlooks of this field are explored, including the potential use of alternative introduction sites, such as stems, and the continued development of nanoparticle formulations that improve adhesion and penetration. By addressing these challenges and fostering multidisciplinary research, the field of nanoparticle transport in plants is poised to make significant contributions to sustainable agriculture and environmental management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa25c5f7-364b-419f-a6bb-c44841ea5316', '385d5df8-25fd-4eb4-8440-46de98d3bbc3', 'Wheat blast: from its origins in South America to its emergence as a global threat', 'Ceresini PC, Castroagudín VL, Rodrigues FÁ, Rios JA, Aucique-Pérez CE, Moreira SI, Croll D, Alves E', 2019, 'Molecular plant pathology', '10.1111/mpp.12747', 'https://doi.org/10.1111/mpp.12747', 'https://europepmc.org/articles/PMC6637873?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Wheat blast was first reported in Brazil in 1985. It spread rapidly across the wheat cropping areas of Brazil to become the most important biotic constraint on wheat production in the region. The alarming appearance of wheat blast in Bangladesh in 2016 greatly increased the urgency to understand this disease, including its causes and consequences. Here, we summarize the current state of knowledge of wheat blast and aim to identify the most important gaps in our understanding of the disease. We also propose a research agenda that aims to improve the management of wheat blast and limit its threat to global wheat production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ee89501c-c9d8-48c6-8152-2dc59de1e2af', '803905f3-9270-42c3-886f-742ece7e1135', 'Advances and Hotspots in Research on Verrucomicrobiota: Focus on Agroecosystems', 'Naziębło A, Pytlak A, Furtak A, Dobrzyński J', 2025, 'Microbial ecology', '10.1007/s00248-025-02657-3', 'https://doi.org/10.1007/s00248-025-02657-3', 'https://europepmc.org/articles/PMC12714770?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Members of the phylum Verrucomicrobiota are abundant yet relatively understudied soil bacteria that play key roles in biogeochemical cycling and plant–microbe interactions. They participate in the carbon (C) and nitrogen (N) cycles through the degradation of complex organic polymers such as cellulose, pectin, and starch – via the production of hydrolytic enzymes (e.g., cellulases, xylanases, chitinases), and through nitrogen transformations including denitrification, ammonification, and nitrogen fixation. Methanotrophic representatives (Methylacidiphilum, Methylacidimicrobium) oxidise methane under acidic or thermophilic conditions, thereby contributing to greenhouse gas mitigation. The ecological distribution and activity of Verrucomicrobiota are strongly influenced by nutrient availability, particularly of C, N, phosphorus (P), and potassium (K). Their variable responses to these elements reflect diverse life-history strategies, encompassing both copiotrophic (r-strategist) and oligotrophic (K-strategist) taxa. While Spartobacteria (e.g., Ca. Udaeobacter) are typically oligotrophic, classes such as Opitutia and Verrucomicrobiae exhibit mixed strategies. Beyond nutrient cycling, several members of the phylum function as plant growth-promoting and stress mitigating bacteria. They produce phytohormones (e.g., indole-3-acetic acid) and siderophores, increase the availability of nitrogen and solubilise phosphate. Some taxa exhibit antioxidant activity and can suppress phytopathogens such as Fusarium oxysporum through secondary metabolite production. These traits suggest a significant potential in soil health improvement. Overall, Verrucomicrobiota represent a functionally diverse and ecologically significant bacterial phylum whose metabolic versatility, adaptive life strategies, and plant-associated traits underscore their central role in sustainable agricultural ecosystems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7fc11590-1a69-4416-af38-06d999e45498', '803905f3-9270-42c3-886f-742ece7e1135', 'Agricultural Weed Assessment Calculator: An Australian Evaluation', 'Beckie HJ, Owen MJ, Borger CPD, Gill GS, Widderick MJ', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9121737', 'https://doi.org/10.3390/plants9121737', 'https://europepmc.org/articles/PMC7763356?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Weed risk assessment systems are used to estimate the potential weediness or invasiveness of introduced species in non-agricultural habitats. However, an equivalent system has not been developed for weed species that occur in agronomic cropland. Therefore, the Agricultural Weed Assessment Calculator (AWAC) was developed to quantify the present and potential future adverse impact of a weed species on crop production and profitability (threat analysis), thereby informing or directing research, development, and extension (RDE) investments or activities. AWAC comprises 10 questions related primarily to a weed''s abundance and economic impact. Twenty weed species from across Australia were evaluated by AWAC using existing information and expert opinion, and rated as high, medium, or low for RDE prioritization based on total scores of 70 to 100, 40 to Lolium rigidum Gaud.), eight were rated as medium (e.g., Conyza spp.), and seven were rated as low (e.g., Rapistrum rugosum L.). Scores were consistent with the current state of knowledge of the species'' impact on grain crop production in Australia. AWAC estimated the economic or agronomic threat of 20 major or minor agricultural weeds from across Australia. The next phase of development is the testing of AWAC by weed practitioners (e.g., agronomists, consultants, farmers) to verify its utility and robustness in accurately assessing these and additional weed species.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('360b5d9b-74c5-4547-b101-b6270a152fdd', '803905f3-9270-42c3-886f-742ece7e1135', 'Biology and Management of Vulpia myuros-An Emerging Weed Problem in No-Till Cropping Systems in Europe', 'Akhter MJ, Jensen PK, Mathiassen SK, Melander B, Kudsk P', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9060715', 'https://doi.org/10.3390/plants9060715', 'https://europepmc.org/articles/PMC7356498?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Recently, Vulpia myuros has become a problematic grass weed species in parts of Europe. It is most common in no-till cropping systems. The inherent tolerance to several selective grass weed herbicides is of serious concern to the successful management of V. myuros in arable farming. Here, we reviewed the available knowledge about the biology of V. myuros to identify knowledge gaps and assess management efforts to identify best practices for control. V. myuros is a winter-annual species producing seeds with a short dormancy that can germinate at a wide range of conditions. Seed longevity in the soil is short. Little information is available on the influence of V. myuros on crop yield but some results suggest that yield losses can be significant. The findings provide a better understanding of the weedy characteristics of V. myuros and highlight that management strategies in Europe need to be diversified and integrate preventive and cultural control methods. Finally, we identify some of the management tools that should be considered to minimize the impact of V. myuros on European farming and future needs for research to develop sustainable integrated weed management strategies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b63149fa-a630-4923-9edb-d2ae1950369d', '803905f3-9270-42c3-886f-742ece7e1135', 'Common agricultural weeds among alien invasive plants in China: Species lists and their practical managing strategies', 'Huang Z, Lin M, Chen G', 2025, 'Heliyon', '10.1016/j.heliyon.2025.e41772', 'https://doi.org/10.1016/j.heliyon.2025.e41772', 'https://europepmc.org/articles/PMC11774770?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Plant invasion is a big challenge to weed management of agricultural lands. In order to reveal the list of common weed species among alien invasive plants, and reveal practical management strategies, we extracted the species lists of common alien agricultural weeds (CAAWs) of various arable lands and plantations, by comparing the lists of alien invasive plant species and common weed species published in China. Totally 88 species from 18 families were recognized as CAAWs, among which 43.0 % are native to North America, followed by South America (34.4 %), Europe (29.0 %), Asia (23.7 %) and Africa (17.2 %); 62.4 % were introduced into China from 1840 to 1949. CAAWs such as Aegilops tauschii Coss., Alopecurus myosuroides Huds., Lolium multiflorum Lamk, Avena fatua L., Phalaris minor Retz, Phalaris paradoxa L., Veronica persica Poir., Geranium carolinianum L., Ranunculus muricatus L., and Cerastium glomeratum Thuill. frequently infest highlands with summer-ripe crops such as wheat and oilseed rape; Alternanthera spp., Panicum repens L., Paspalum conjugatum Bergius, and Ageratum conyzoides L. frequently infest highlands with autumn-ripe crops; and Paspalum distichum L., Alternanthera philoxeroides, and Ammannia coccinea Rott. occasionally infest rice fields. Troublesome CAAWs in plantations in China mainly consist of tall herbs, and climbing or spiny plants, such as Mikania micrantha Kunth, Ipomoea spp., Solidago canadensis L., Erigeron spp. and Bidens spp. Management strategies against CAAWs in current China mainly rely on chemical control, tillage, soil mulching, and manual removing of weeds. Next, effective risk assessing models targeting to different sorts of arable lands or plantations are urgently needed; as well, effective, feasible and sustainable integrated management strategies against troublesome CAAWs should be developed and applied.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5350ca76-ff1d-40aa-8339-ae17e8f11898', '803905f3-9270-42c3-886f-742ece7e1135', 'Development of a rice herbicide, fenoxasulfone', 'Fujinami M, Takahashi Y, Tanetani Y, Ito M, Nasu M', 2019, 'Journal of pesticide science', '10.1584/jpestics.j19-04', 'https://doi.org/10.1584/jpestics.j19-04', 'https://europepmc.org/articles/PMC6861544?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by-nc-nd', 'Fenoxasulfone is a novel rice herbicide that was discovered and developed by Kumiai Chemical Industry Co., Ltd. It displays excellent herbicidal activity against Echinochloa spp. and other annual weeds at 150-200 g a.i./ha with long residual activity and has a favorable toxicological, ecotoxicological, and environmental profile. Fenoxasulfone''s mode of action was investigated, and it has been shown to inhibit the biosynthesis of very-long-chain fatty acids in plants. Fenoxasulfone was registered in Japan in 2014, and various products containing fenoxasulfone have been launched. With its high efficacy and long residual activity, we believe that fenoxasulfone will contribute to efficient food production in the future.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ef96ff5-aed4-450b-a5b3-a64e0e42dcc5', '803905f3-9270-42c3-886f-742ece7e1135', 'Efficacy of sequential application of herbicide mixture for management of multiple herbicide resistant in Phalaris minor in wheat (Triticum aestivum)', 'SUSHIL  KUMAR, R S  DADARWAL, TODAR  MAL, AKSHIT, PRIYANKA  DEVI, ANNU  KUMARI, GOURAV  CHAHAL', 2024, 'The Indian Journal of Agricultural Sciences', '10.56093/ijas.v94i4.144137', 'https://doi.org/10.56093/ijas.v94i4.144137', 'https://epubs.icar.org.in/index.php/IJAgS/article/view/144137', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'The emergence of multiple herbicide resistance in Phalaris minor is a major threat to wheat (Triticum aestivum L.) production in north-western Indo-Gangetic Plains of India. The present study was carried out during winter (rabi) seasons of 2020–21 and 2021–22 at research farm of Chaudhary Charan Singh Haryana Agricultural University, Hisar, Haryana for management of herbicide resistance in Phalaris minor Retz. in wheat using pre and post-emergence herbicide mixtures with different mode of action. The experiment was laid out in randomized block design (RBD) with 15 treatments, replicated thrice. Sequential application of flumioxazin 125 g/ha with pendimethalin (tank mix) 1500 g/ha fb clodinafop + metribuzin 174 g/ha resulted in significantly lowest weed density, dry matter of P. minor and broad-leaf weeds, and it was statistically comparable to application of flumioxazin alone or as mixture with pendimethalin as pre-emergence; pyraxosulfone + pendimethalin 127.5 + 1500 g/ha fb PoE (post-emergence) application of either mesosulfuron + iodosulfuron 14.4 g/ha; sulfosulfuron + metsulfuron, pinoxaden + metsulfuron 50 + 4 g/ha, clodinafop + metribuzin 174 g/ha, respectively. Phytotoxicity of flumioxazin was observed on wheat after 2–3 days of 1st irrigation i.e. 25 DAS (days after sowing). Application of pyroxasulfone + pendimethalin pre fb PoE mesosulfuron + iodosulfuron resulted in significantly higher grain yield (5847 and 5369 kg/ha, during 2021 and 2022, respectively) as compared to other herbicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf836b63-eeed-4917-b480-e31fe67a21e1', '803905f3-9270-42c3-886f-742ece7e1135', 'Digitaria genome analyses indicate introgression may drive local adaptation and herbicide resistance', 'Huang Y, Li J, Li Z, Zhang S, Gao X, Xie L, Zhou R, Yang K', 2026, 'Nature communications', '10.1038/s41467-026-69076-x', 'https://doi.org/10.1038/s41467-026-69076-x', 'https://europepmc.org/articles/PMC13009277?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by-nc-nd', 'Crabgrasses (Digitaria spp.) rank among the most invasive upland weeds globally, exhibiting remarkable ecological plasticity. To uncover the genomic basis underlying their weediness and environmental adaptability, we generate a telomere-to-telomere (T2T) reference genome of Digitaria sanguinalis, along with its diploid progenitor D. radicosa and tetraploid progenitor D. milanjiana. In addition, we re-sequence 579 accessions collected from fields of 24 grain-producing provinces in China. A phenotypic classification system for Digitaria species is developed by integrating genome-scale data with detailed morphological observations. Phylogenomic and comparative genomic analyses resolve the evolutionary history of Digitaria and reveal lineage-specific expansions in herbicide-associated gene families. Extensive sympatric introgression is observed within Digitaria, correlated with environmental selection. Through dose-response assay of 196 accessions, we identify 19 candidate genes associated with herbicide resistance, including DsSOH1. Haplotype analysis indicates that the resistant allele at DsSOH1 locus originated from D. ciliaris, suggesting a possible evolutionary contribution of introgression to the distribution of resistance-associated alleles. Together, our findings provide genomic insights into the evolutionary success of D. sanguinalis and offer resources for studying polyploid evolution and environmental adaptation as well as precision weed management in agroecosystems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6e823a63-bcc2-430f-9013-a977f05546ba', '803905f3-9270-42c3-886f-742ece7e1135', 'Non-Target-Site Resistance to Herbicides: Recent Developments', 'Jugulam M, Shyam C', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8100417', 'https://doi.org/10.3390/plants8100417', 'https://europepmc.org/articles/PMC6843234?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Non-target-site resistance (NTSR) to herbicides in weeds can be conferred as a result of the alteration of one or more physiological processes, including herbicide absorption, translocation, sequestration, and metabolism. The mechanisms of NTSR are generally more complex to decipher than target-site resistance (TSR) and can impart cross-resistance to herbicides with different modes of action. Metabolism-based NTSR has been reported in many agriculturally important weeds, although reduced translocation and sequestration of herbicides has also been found in some weeds. This review focuses on summarizing the recent advances in our understanding of the physiological, biochemical, and molecular basis of NTSR mechanisms found in weed species. Further, the importance of examining the co-existence of TSR and NTSR for the same herbicide in the same weed species and influence of environmental conditions in the altering and selection of NTSR is also discussed. Knowledge of the prevalence of NTSR mechanisms and co-existing TSR and NTSR in weeds is crucial for designing sustainable weed management strategies to discourage the further evolution and selection of herbicide resistance in weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3e8a92a8-591e-4d6e-9e1b-eb233d8a276e', '803905f3-9270-42c3-886f-742ece7e1135', 'Discovering the mechanism of enhanced metabolism in flufenacet resistant grass weeds', 'Dücker, Rebecca, Lorentz, Lothar, Hull, Richard, Anderson, Monte, Moss, Stephen, Beffa, Roland', 2016, 'Julius-Kühn-Archiv', '10.5073/jka.2016.452.005', 'https://doi.org/10.5073/jka.2016.452.005', 'http://pub.jki.bund.de/index.php/JKA/article/view/6141/5826', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Inhibitors of very long chain fatty acid synthesis (VLCFAs, HRAC group K3) including flufenacet-based products are key herbicides in weed management strategies in particular of Western European cereal growing areas. They offer an alternative mode of action to those of frequently applied post-emergence active ingredients e.g. ACCase and ALS chemistries. In comparison, herbicide resistance to VLCFAs inhibitors develops considerably slower. Yet, resistance to the ‘low-risk’ herbicide flufenacet was documented in multi-resistant ryegrass (Lolium spp.) in the northwestern United States. A 46-fold resistance shift in a population from Washington State was observed in a dose-response bioassay. The resistance levels described in black-grass (Alopecurus myosuroides Huds.) field populations are lower and generally within the range of environmentally caused inconsistency in efficacy. An artificial selection of two UK multi-resistant black-grass populations with flufenacet applied annually for eight successive years resulted in resistant progeny surviving the field rate. Besides characterizing the degree of resistance in black-grass and ryegrass populations, we demonstrated that flufenacet resistance in these populations was caused by enhanced metabolism. No cross-resistance between flufenacet and pyroxasulfone, the newest VLCFAs-inhibiting herbicide, occurred in the ryegrass population. A good understanding of the resistance mechanism and early diagnostics can help preserve the efficacy of flufenacet.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d2d54ba9-754b-40ff-8881-9343b3a682ed', '803905f3-9270-42c3-886f-742ece7e1135', 'Distribution and Control of Herbicide-Resistant Italian Ryegrass [Lolium perenne L. ssp. multiflorum (Lam.) Husnot] in Winter Wheat (Triticum aestivum L.) in North Carolina', 'Eric A. L. Jones, Zachary R. Taylor, Wesley J. Everman', 2021, 'Frontiers in Agronomy', '10.3389/fagro.2020.601917', 'https://doi.org/10.3389/fagro.2020.601917', 'https://www.frontiersin.org/articles/10.3389/fagro.2020.601917/full', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'Italian ryegrass is consistently ranked as one of the most problematic weeds of winter wheat in the Southeastern United States. To determine the distribution of resistant Italian ryegrass biotypes, seed was collected from locations throughout North Carolina and screened with diclofop, pinoxaden, mesosulfuron, and pyroxsulam. Results identified evidence of resistance to diclofop at all locations sampled throughout the state. Resistance to mesosulfuron, pyroxsulam, and pinoxaden were confirmed in 11, 19, and five percent of sampled locations, respectively. Additionally, Italian ryegrass biotypes resistant to multiple and all herbicides tested were identified, eliminating POST herbicide application as an option for control. Adjusting tillage practices may be an option for sustainable weed management to maintain effective control and maximize crop yield. Companion studies were established in the Coastal Plain and Piedmont regions of North Carolina in 2013 and 2014 to evaluate the effect of tillage on Italian ryegrass efficacy with herbicides. Herbicide treatments consisted of pyroxasulfone PRE only, mesosulfuron, or pinoxaden and POST only applications of mesosulfuron plus pyroxasulfone or pinoxaden plus pyroxasulfone. Tillage treatments included no-till and conservation tillage. Treatments containing pinoxaden provided the greatest Italian ryegrass control, regardless of tillage system. The use of pyroxasulfone PRE controlled a higher percentage of Italian ryegrass in the Piedmont when compared to the Coastal Plain, which is believed to be due to multiple flushes during the growing season in the Coastal Plain. Herbicide treatment was still a significant factor in Italian ryegrass control, but Italian ryegrass seed head density was consistently lower in the no-till system. Tillage may be stimulating germination, allowing greater control with PRE herbicides. An integrated system of herbicides and tillage may allow for greater yield and reduce selection pressure on POST herbicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a13a6bd-b16f-4c2f-bf24-42370b6a7f0f', '803905f3-9270-42c3-886f-742ece7e1135', 'Effects of sorghum residue in presence of pre-emergence herbicides on emergence and biomass of Echinochloa colona and Chloris virgata', 'Mobli A, Rinwa A, Sahil, Chauhan BS', 2020, 'PloS one', '10.1371/journal.pone.0229817', 'https://doi.org/10.1371/journal.pone.0229817', 'https://europepmc.org/articles/PMC7051094?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'In conservation agriculture systems, farmers gain many advantages from retaining crop residue on the soil surface, but crop residue retention in these systems may intervene with the activity of pre-emergence herbicides. A pot study was conducted to evaluate the effect of different rates of pre-emergence herbicides [imazethapyr (100 and 150 g a. i. ha-1), isoxaflutole (100 and 200 g a. i. ha-1), metolachlor (1.5 and 2.25 kg a. i. ha-1), pendimethalin (2.25 and 3.38 kg a. i. ha-1) and prosulfocarb + metolachlor (2.5 and 3.75 kg a. i. ha-1)] on seedling emergence and biomass of Echinochloa colona and Chloris virgata when applied in the presence of sorghum residue at rates equivalent to (0, 3 and 6 t ha-1). When seeds of E. colona and C. virgata were not covered with sorghum residue, the seedling emergence and biomass of both weeds was inhibited by 93-100% and 56-100%, respectively, with the application (both rates) of isoxaflutole, metolachlor, pendimethalin and prosulfocarb + metolachlor. Using sorghum residue resulted in lower herbicide efficacy on both weeds. At 3 t ha-1 sorghum residue, E. colona emergence and biomass reduced by 38-100% and 30-100%, respectively, with application of isoxaflutole, metolachlor and pendimethalin (both rates) in comparison with the no-herbicide treatment. Similarly, the emergence and biomass of C. virgata was also reduced by 92-100% and 25-100%, respectively. The results of this study suggest that crop residue may influence efficacy of commonly used pre-emergence herbicides and that the amount of crop residue on the soil surface should be adjusted according to the nature of the pre-emergence herbicides to achieve adequate weed control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.251994+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('251e080b-9e84-4453-934c-c5b94e6ac102', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Adsorption and degradation of phenoxyalkanoic acid herbicides in soils: A review', 'Tadeusz Paszko, Paweł Muszyński, Małgorzata Materska, Monika Bojanowska, Małgorzata Kostecka, I. Jackowska', 2015, 'Environmental Toxicology and Chemistry', '10.1002/etc.3212', 'https://doi.org/10.1002/etc.3212', 'https://setac.onlinelibrary.wiley.com/doi/pdfdirect/10.1002/etc.3212', NULL, NULL, NULL, NULL, 'other', 1, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('058d3f8c-f4c8-4229-8d23-e244a544c188', '803905f3-9270-42c3-886f-742ece7e1135', 'Emerging Issues and Potential Opportunities in the Rice-Wheat Cropping System of North-Western India', 'Dhanda S, Yadav A, Yadav DB, Chauhan BS', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.832683', 'https://doi.org/10.3389/fpls.2022.832683', 'https://europepmc.org/articles/PMC8902641?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'The rice-wheat cropping system (RWCS) is the backbone of Indian farming, especially in the north-western region. But continuous adoption of the RWCS in northwest India has resulted in major challenges and stagnation in the productivity of this system. Additionally, the Indo-Gangetic Plains of Pakistan, Nepal, and Bangladesh are also facing similar challenges for sustainable production of the RWCS. Several emerging problems, such as the exhausting nutrient pool in soil, deteriorating soil health, groundwater depletion, escalating production cost, labor scarcity, environmental pollution due to crop residue burning and enhanced greenhouse gas emissions, climatic vulnerabilities, and herbicide resistance in weed species, are a few major threats to its sustainability. To address these challenges, a wide range of sustainable intensification technologies have been developed to reduce the irrigation and labor requirements, tillage intensity, and straw burning. Awareness and capacity building of the stakeholders and policy matching/advocacy need to be prioritized to adopt time- and need-based strategies at the ground level to combat these challenges. This review summarizes the current status and challenges of the RWCS in the northwest region of the country and also focuses on the precision management options for achieving high productivity, profitability, and sustainability.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('abfcb230-eaa2-47bf-9754-721ec2f99fd9', '803905f3-9270-42c3-886f-742ece7e1135', 'Enhanced production of water-soluble cinmethylin metabolites by Lolium rigidum populations with reduced cinmethylin sensitivity', 'Goggin DE, Cawthray GR, Busi R, Porri A, Beckie HJ', 2022, 'Pest management science', '10.1002/ps.6947', 'https://doi.org/10.1002/ps.6947', 'https://europepmc.org/articles/PMC9325456?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundCinmethylin, a pre-emergence herbicide inhibiting fatty acid thioesterase activity, has recently been introduced to Australian cereal cropping for the control of Lolium rigidum Gaud. (annual ryegrass). To date, there have been no confirmed cases of cinmethylin resistance identified in this species, but some populations exhibit reduced sensitivity to this herbicide. To explore the mechanism which contributes to reduced sensitivity of annual ryegrass to cinmethylin, the extent and nature of cinmethylin metabolism, using carbon-14 (14 C)-labelled herbicide, were analysed in three reduced-sensitivity annual ryegrass populations, alongside a susceptible population and cinmethylin-tolerant wheat as controls.ResultsAll samples showed the same metabolite profile, with the extent of production of a specific water-soluble metabolite being correlated to the level of herbicide sensitivity. Application of the cytochrome P450 inhibitor phorate caused a decrease in water-soluble metabolite production as well as seedling growth in the presence of cinmethylin, indicating that reduced cinmethylin sensitivity in annual ryegrass could be wholly or partially due to oxidative modification of cinmethylin.ConclusionBecause annual ryegrass has the potential to metabolize cinmethylin in the same way as wheat, careful stewardship is required to ensure the longevity of this herbicide. © 2022 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('09a3a95e-05f9-4ca8-8dcd-790e0eb28634', '803905f3-9270-42c3-886f-742ece7e1135', 'Epyrifenacil, a new systemic PPO-inhibiting herbicide for broad-spectrum weed control', 'Sada Y, Jin Y, Hikosaka M, Ido K', 2025, 'Pest management science', '10.1002/ps.8244', 'https://doi.org/10.1002/ps.8244', 'https://europepmc.org/articles/PMC11981982?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by-nc-nd', 'Epyrifenacil is a novel PPO-inhibiting herbicide discovered and developed by Sumitomo Chemical. Epyrifenacil belongs to the pyrimidinedione chemical class and has a unique three-ring structure. It is systemically active on a broad range of weeds including grass weeds and some target-site-based PPO-inhibitor resistant broadleaf weeds. Its systemic action is mediated by a phloem movement of the active form of epyrifenacil. In addition, epyrifenacil''s vapor action is sufficiently low to not cause an off-target movement to nontarget sensitive crops. It is expected that epyrifenacil will contribute to global food production in the near future. © 2024 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('43aaeea7-32e3-4740-9ed5-9eb1c75b86e5', '803905f3-9270-42c3-886f-742ece7e1135', 'Evaluation of Preemergent Herbicides for Chloris virgata Control in Mungbean', 'Mahajan G, Chauhan BS', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10081632', 'https://doi.org/10.3390/plants10081632', 'https://europepmc.org/articles/PMC8398657?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Chloris virgata is a problematic weed in mungbean crops due to its high seed production, resistance to glyphosate and high dispersal ability. Pot and field experiments were conducted in 2020 and 2021 to evaluate a range of preemergent (PRE) herbicides for C. virgata control in mungbean. In the field and pot studies, isoxaflutole 75 g ai ha-1 caused crop injury, and in the field experiment, it reduced mungbean yield by 61% compared with the best treatment (pyroxasulfone 100 g ai ha-1). In the field and pot experiments, dimethenamid-P 720 g ai ha-1, pyroxasulfone 100 g ai ha-1 and S-metolachlor 1400 g ai ha-1 provided >88% control of C. virgata (for reduced biomass) and in the field experiment, these herbicides resulted in improved yield by 230%, 270% and 170%, respectively, compared with nontreated control (250 kg ha-1). Similarly, pendimethalin 1000 g ai ha-1 and trifluralin 600 g ai ha-1 provided >89% control (biomass) of C. virgata, and in the field experiment, these resulted in improved yields of 230% and 160%, respectively, compared with the nontreated control. PRE herbicides such as diuron 750 g ai ha-1, linuron 1100 g ai ha-1, metribuzin 360 g ha-1, terbuthylazine 750 g ai ha-1, imazapic 48 g ai ha-1 and imazethapyr 70 g ha-1 although did not cause crop injury; however, these herbicides did not control C. virgata. Flumioxazin 90 g ai ha-1 caused reduced biomass of C. virgata by 80% compared with the nontreated control, and in the field experiment, it resulted in improved yield by 140% compared with the nontreated control. This study suggests the potential use of herbicides, such as dimethenamid-P, pyroxasulfone and S-metolachlor in addition to pendimethalin and trifluralin, for C. virgata control in mungbean. Further studies are needed to determine the efficacy of dimethenamid-P, S-metolachlor and pyroxasulfone for controlling other troublesome weeds in mungbean.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ae0f859-6cd4-48c2-8ee4-6bdad43f68d0', '803905f3-9270-42c3-886f-742ece7e1135', 'Evaluation of Pyroxasulfone Crop Safety and Weed Control for California Tree Nut Orchards', 'Andres Contreras Jr, Guelta Laguerre, Bradley D. Hanson', 2024, 'HortScience', 'https://doi.org/10.21273/HORTSCI17963-24', 'https://doi.org/https://doi.org/10.21273/HORTSCI17963-24', 'https://journals.ashs.org/hortsci/view/journals/hortsci/59/9/article-p1422.xml', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Pyroxasulfone is a very long chain fatty acid (VLCFA) inhibitor (group 15) with potential for preemergence weed control in orchard crops and would be beneficial for reducing selection pressure for resistance to more commonly used herbicides, such as glyphosate. Pyroxasulfone is registered and widely used in corn and soybeans in the United States as a solo product and in several premix formulations. However, there is limited published information on the performance and safety of pyroxasulfone in tree nut orchard systems. To assess the potential fit for pyroxasulfone in this crop sector, a series of crop safety and weed control efficacy experiments were carried out in key California orchard crops and in fallow fields with common orchard weeds. The non-crop studies were conducted near Davis, CA, to evaluate winter annual weed control with pyroxasulfone in comparison with pendimethalin and indaziflam. In addition, an irrigation incorporation experiment was conducted in summer to evaluate the effects of incorporation timing on pyroxasulfone, pendimethalin, and indaziflam efficacy as a measure of relative stability. Orchard weed control experiments were conducted in spring in an almond orchard near Arbuckle, CA, and a walnut orchard near Davis, CA. The orchard experiments included pyroxasulfone, pendimethalin, and indaziflam in various rate combinations with glufosinate. To evaluate crop safety, 2-year experiments were conducted to evaluate repeated applications of above-label rates of pyroxasulfone at 1199 g·ha−1 and S-metolachlor at 14,010 g·ha−1 on 1- to 2-year-old almond, pistachio, and walnut trees near Davis. Pyroxasulfone performed similarly to commercial standards with up to 95% control of broadleaf and grass weeds with pyroxasulfone and indaziflam providing 96% to 100% control of annual bluegrass, and pyroxasulfone (293 g·ha−1) being the only herbicide to suppress (>70%) common lambsquarters at 60 days after treatment (DAT). Other weeds controlled by pyroxasulfone include swinecress, redroot pigweed, yellow nutsedge, and Italian ryegrass. No differences were found among treatments in the incorporation timing study indicating adequate stability on the soil surface under summer conditions. Crop injury was not observed in the established orchards or the young orchard studies and there were no treatment effects on tree trunk diameter of almond, pistachio, and walnut in the 2-year crop safety experiments. These results indicate a potential for pyroxasulfone in California tree nut orchard systems that would be an additional site of action and beneficial for management of herbicide-resistant weeds in these crops.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('74486bd2-326d-441a-ae7b-485341c43553', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Can circularity support net-zero agriculture: an exploratory case', 'McAllister T, Ellert B, Janzen H', 2025, 'Animal frontiers : the review magazine of animal agriculture', '10.1093/af/vfaf019', 'https://doi.org/10.1093/af/vfaf019', 'https://europepmc.org/articles/PMC12449127?pdf=render', NULL, NULL, 11, NULL, 'southern_alberta', 4, 'cc by', NULL, '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b03b5b18-e6ef-4da9-8761-510badd3d36d', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Correlation of Bioassay Crop Growth with Cinmethylin and Chlorimuron Application Rates for Two Soils', 'T.G. Boucounis, Ted Whitwell, Joe E. Toler', 1990, 'HortScience', '10.21273/hortsci.25.5.536', 'https://doi.org/10.21273/hortsci.25.5.536', 'https://journals.ashs.org/downloadpdf/journals/hortsci/25/5/article-p536.pdf', NULL, NULL, NULL, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ef55b61a-5643-40ed-9f5c-f0aa05fe41f9', '803905f3-9270-42c3-886f-742ece7e1135', 'Evaluation of soybean [Glycine max (L.) Merr.] genotypes for yield, water use efficiency, and root traits', 'Fried HG, Narayanan S, Fallen B', 2019, 'PloS one', '10.1371/journal.pone.0212700', 'https://doi.org/10.1371/journal.pone.0212700', 'https://europepmc.org/articles/PMC6386299?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Drought stress has been identified as the major environmental factor limiting soybean [Glycine max (L.) Merr.] yield worldwide. Current breeding efforts in soybean largely focus on identifying genotypes with high seed yield and drought tolerance. Water use efficiency (WUE) that results in greater yield per unit rainfall is an important parameter in determining crop yields in many production systems, and is often related with crop drought tolerance. Even though roots are major plant organs that perceive and respond to drought stress, their utility in improving soybean yield and WUE under different environmental and management conditions are largely unclear. The objectives of this research was to evaluate soybean cultivars and breeding and germplasm lines for yield, WUE, root penetrability of hardpan, and root morphology. Field experiments were conducted at two locations in South Carolina (southeastern United States) during the 2017 cropping season to test the genotypes for yield and root morphology under irrigated and non-irrigated conditions. Two independent controlled-environmental experiments were conducted to test the genotypes for WUE and root penetrability of synthetic hardpans. The slow wilting lines NTCPR94-5157 and N09-13890 had equal or greater yield than the checks- cultivar NC-Raleigh and the elite South Carolina breeding line SC07-1518RR, under irrigated and non-irrigated conditions. The high yielding genotypes NTCPR94-5157, N09-13890, and SC07-1518RR exhibited root parsimony (reduced root development). This supported the recent hypothesis in literature that root parsimony would have adaptational advantage to improve yield under high input field conditions. The high yielding genotypes NTCPR94-5157, N09-13890, NC-Raleigh, and SC07-1518RR and a cultivar Boggs (intermediate in yield) possessed high WUE and had increased root penetrability of hardpans. These genotypes offer useful genetic materials for soybean breeding programs for improving yield, drought tolerance, and/or hardpan penetrability.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c9be26c0-a5e0-40d1-9aca-9c5d473bec30', '803905f3-9270-42c3-886f-742ece7e1135', 'Farming without Glyphosate?', 'Beckie HJ, Flower KC, Ashworth MB', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9010096', 'https://doi.org/10.3390/plants9010096', 'https://europepmc.org/articles/PMC7020467?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Recent statements from scientific organisations and court decisions have resulted in widespread public interest and concern over the safety of glyphosate, the most popular and effective herbicide used worldwide. Consequently, glyphosate-based products are under intense scrutiny from governments at all levels. Some jurisdictions have already banned or restricted its use, which will adversely impact international trade in bulk grain commmodities if glyphosate residues are detected. The possibility of farming without glyphosate is becoming an important issue facing the agri-food research and development sector. Contingency plans need to be formulated if that scenario becomes a reality. In this review, we briefly summarize international events that have led to this possible situation, describe current glyphosate usage in major agronomic field crops worldwide, outline possible alternatives to glyphosate in two agroregions and perform bioeconomic model scenarios of southern Australian broadacre cropping systems without the herbicide. Model predictions suggest that we can farm profitably without glyphosate by consistently utilizing key non-herbicidal weed management practices combined with robust pre-emergence soil residual herbicide treatments. However, maintaining low weed seed banks will be challenging. If the social license to use glyphosate is revoked, what other pesticides will soon follow?', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('deab6f80-676a-4101-95f5-3a7b7d01a1df', '803905f3-9270-42c3-886f-742ece7e1135', 'Herbicide dose-response thresholds in sands to assess the risk of non-target damage to winter grain crops', 'Pyone WW, Bell RW, Rose MT, McGrath GS', 2025, 'PloS one', '10.1371/journal.pone.0330225', 'https://doi.org/10.1371/journal.pone.0330225', 'https://europepmc.org/articles/PMC12370053?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Herbicide residues in soil from previous crops or from pre-emergent treatments can have unintended toxicity on the next crop. Despite this there is limited published information on toxicity thresholds for many crops or herbicides. This study aimed to quantify shoot and root responses of six common winter grains crops (canola, chickpea, fieldpea, lentil, lupin and wheat) to increasing concentration of four common herbicides (clopyralid, pyroxasulfone, propyzamide and trifluralin) in soil. Lentil emergence was highly sensitive to clopyralid (29 μg kg-1 for a 50% reduction, ED50) while wheat emergence was sensitive to propyzamide and trifluralin, with complete inhibition at 100 μg kg-1 and 375 μg kg-1, respectively. Shoot and root parameters of the legumes, except lupin, were significantly reduced by clopyralid, with ED50 values ranging between 3-27 μg kg-1. Canola was sensitive to pyroxasulfone, with shoot and root biomass ED50 at 21 and 8 μg kg-1, respectively. Pyroxasulfone also severely reduced root length of all tested crops (ED50 values 6-53 μg kg-1). Root and shoot growth in wheat was most susceptible to propyzamide followed by trifluralin. This study found that one or more herbicides had the potential to cause significant phytotoxic effects in all crops at concentrations below recommended application rates and below those detected in a recent field survey of pre-sowing herbicide residues in field soils around Australia. These results suggest the risk of early crop damage residual herbicides in very light-textured soils. More effort is now required to determine potential effects on different soil types and crop yields, to enable better spatial and economic risk assessment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad1bed94-c6eb-4a3b-874c-9a97a898c4e4', '803905f3-9270-42c3-886f-742ece7e1135', 'Herbicide drift exposure leads to reduced herbicide sensitivity in Amaranthus spp', 'Vieira BC, Luck JD, Amundsen KL, Werle R, Gaines TA, Kruger GR', 2020, 'Scientific reports', '10.1038/s41598-020-59126-9', 'https://doi.org/10.1038/s41598-020-59126-9', 'https://europepmc.org/articles/PMC7005892?pdf=render', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by', 'While the introduction of herbicide tolerant crops provided growers new options to manage weeds, the widespread adoption of these herbicides increased the risk for herbicide spray drift to surrounding vegetation. The impact of herbicide drift in sensitive crops is extensively investigated, whereas scarce information is available on the consequences of herbicide drift in non-target plants. Weeds are often abundant in field margins and ditches surrounding agricultural landscapes. Repeated herbicide drift exposure to weeds could be detrimental to long-term management as numerous weeds evolved herbicide resistance following recurrent-selection with low herbicide rates. The objective of this study was to evaluate if glyphosate, 2,4-D, and dicamba spray drift could select Amaranthus spp. biotypes with reduced herbicide sensitivity. Palmer amaranth and waterhemp populations were recurrently exposed to herbicide drift in a wind tunnel study over two generations. Seeds from survival plants were used for the subsequent rounds of herbicide drift exposure. Progenies were subjected to herbicide dose-response studies following drift selection. Herbicide drift exposure rapidly selected for Amaranthus spp. biotypes with reduced herbicide sensitivity over two generations. Weed management programs should consider strategies to mitigate near-field spray drift and suppress the establishment of resistance-prone weeds on field borders and ditches in agricultural landscapes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d91f3f83-5158-47e1-9435-d3c4a9e4548c', '803905f3-9270-42c3-886f-742ece7e1135', 'Herbicide Resistance in Phalaris Species: A Review', 'Gherekhloo J, Hassanpour-Bourkheili S, Hejazirad P, Golmohammadzadeh S, Vazquez-Garcia JG, De Prado R', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10112248', 'https://doi.org/10.3390/plants10112248', 'https://europepmc.org/articles/PMC8621942?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Weeds, such as Phalaris spp., can drastically reduce the yield of crops, and the evolution of resistance to herbicides has further exacerbated this issue. Thus far, 23 cases of herbicide resistance in 11 countries have been reported in Phalaris spp., including Phalaris minor Retz., Phalaris paradoxa L., and Phalaris brachystachys L., for photosystem II (PS-II), acetyl-CoA carboxylase (ACCase), and acetolactate synthase (ALS)-inhibiting herbicides. This paper will first review the cases of herbicide resistance reported in P. minor, P. paradoxa, and P. brachystachys. Then, the mechanisms of resistance in Phalaris spp. are discussed in detail. Finally, the fitness cost of herbicide resistance and the literature on the management of herbicide-resistant weeds from these species are reviewed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2f77d6d2-0d46-4437-9365-394902fe97fd', '803905f3-9270-42c3-886f-742ece7e1135', 'Increasing cassava root yield on farmers'' fields in Nigeria through appropriate weed management', 'Ekeleme F, Dixon A, Atser G, Hauser S, Chikoye D, Korie S, Olojede A, Agada M', 2021, 'Crop Protection', '10.1016/j.cropro.2021.105810', 'https://doi.org/10.1016/j.cropro.2021.105810', 'https://europepmc.org/articles/PMC8505754?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Weed competition is the major biological stress affecting cassava production in smallholder farms in West and Central Africa, where yields are low compared with those in Asia and Latin America. Options for improved weed management are crucial in increasing productivity. Selected pre- and post-emergence herbicides, integrated with appropriate tillage and plant spacing, were tested in 96 sites in four locations in Nigeria, 24 in 2016 and 72 in 2017. Trials were split plots with six pre-emergence herbicides and no post-emergence treatment as main plots. Subplot treatments were four post-emergence herbicides, weeding with a motorized rotary weeder, short- and long-handled hoes, and no post-emergence weed control, i.e., regardless of pre-emergence treatments. Indaziflam-based treatments, irrespective of post-emergence treatment, and flumioxazin + pyroxasulfone applied pre-emergence followed by one weeding with a long-handled hoe provided >80% control of major broadleaf and grass weeds. Compared with herbicide use, farmer control practices (53%) were not efficient in controlling weeds. The highest root yield was produced where (1) s-metolachlor was combined with atrazine, and one weeding with a long-handled hoe or clethodim with lactofen, and (2) indaziflam + isoxaflutole was combined with glyphosate. An increase in root yield from 3.41 to 14.2 t ha-1 and from 3.0 to 11.99 t ha-1 was obtained where herbicides were used compared with farmers'' practice and manual hoe weeding. Our results showed that integrating good agronomic practices with safe and effective use of appropriate herbicides can result in root yield >20 t ha-1. i.e., twice the national average root yield of 8-12 t ha-1, with >50% net profit. The use of appropriate herbicides can reduce the amount of manual labor required and improve livelihoods, specifically for women and children. Smallholder cassava farmers would require continuous training on the safe use and handling of herbicides to improve efficiency and prevent adverse effects on humans and the environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48465c43-f812-4295-923c-3da493c7195f', '803905f3-9270-42c3-886f-742ece7e1135', 'Inheritance of Mesotrione Resistance in an Amaranthus tuberculatus (var. rudis) Population from Nebraska, USA', 'Oliveira MC, Gaines TA, Jhala AJ, Knezevic SZ', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00060', 'https://doi.org/10.3389/fpls.2018.00060', 'https://europepmc.org/articles/PMC5801304?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'A population of Amaranthus tuberculatus (var. rudis) evolved resistance to 4-hydroxyphenylpyruvate dioxygenase (HPPD) inhibitor herbicides (mesotrione, tembotrione, and topramezone) in Nebraska. The level of resistance was the highest to mesotrione, and the mechanism of resistance in this population is metabolism-based likely via cytochrome P450 enzymes. The increasing number of weeds resistant to herbicides warrants studies on the ecology and evolutionary factors contributing for resistance evolution, including inheritance of resistance traits. In this study, we investigated the genetic control of mesotrione resistance in an A. tuberculatus population from Nebraska, USA. Results showed that reciprocal crosses in the F1 families exhibited nuclear inheritance, which allows pollen movement carrying herbicide resistance alleles. The mode of inheritance varied from incomplete recessive to incomplete dominance depending upon the F1 family. Observed segregation patterns for the majority of the F2 and back-cross susceptible (BC/S) families did not fit to a single major gene model. Therefore, multiple genes are likely to confer metabolism-based mesotrione resistance in this A. tuberculatus population from Nebraska. The results of this study aid to understand the genetics and inheritance of a non-target-site based mesotrione resistant A. tuberculatus population from Nebraska, USA.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff82a905-3b75-4d28-99fe-978dcf3097c2', '803905f3-9270-42c3-886f-742ece7e1135', 'Mechanism of Resistance to S-metolachlor in Palmer amaranth', 'Rangani G, Noguera M, Salas-Perez R, Benedetti L, Roma-Burgos N', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.652581', 'https://doi.org/10.3389/fpls.2021.652581', 'https://europepmc.org/articles/PMC7994610?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Herbicides are major tools for effective weed management. The evolution of resistance to herbicides in weedy species, especially contributed by non-target-site-based resistance (NTSR) is a worrisome issue in crop production globally. Glyphosate-resistant Palmer amaranth (Amaranthus palmeri) is one of the extremely difficult weeds in southern US crop production. In this study, we present the level and molecular basis of resistance to the chloroacetamide herbicide, S-metolachlor, in six field-evolved A. palmeri populations that had survivors at the recommended field-dose (1.1 kg ai ha-1). These samples were collected in 2014 and 2015. The level of resistance was determined in dose-response assays. The effective dose for 50% control (ED50) of the susceptible population was 27 g ai ha-1, whereas the ED50 of the resistant populations ranged from 88 to 785 g ai ha-1. Therefore, A. palmeri resistance to S-metolachlor evolved in Arkansas as early as 2014. Metabolic-inhibitor and molecular assays indicated NTSR in these populations, mainly driven by GSTs. To understand the mechanism of resistance, selected candidate genes were analyzed in leaves and roots of survivors (with 1 × S-metolachlor). Expression analysis of the candidate genes showed that the primary site of S-metolachlor detoxification in A. palmeri is in the roots. Two GST genes, ApGSTU19 and ApGSTF8 were constitutively highly expressed in roots of all plants across all resistant populations tested. The expression of both GSTs increased further in survivors after treatment with S-metolachlor. The induction level of ApGSTF2 and ApGSTF2like by S-metolachlor differed among resistant populations. Overall, higher expression of ApGSTU19, ApGSTF8, ApGSTF2, and ApGSTF2like, which would lead to higher GST activity in roots, was strongly associated with the resistant phenotype. Phylogenetic relationship and analysis of substrate binding site of candidate genes suggested functional similarities with known metolachlor-detoxifying GSTs, effecting metabolic resistance to S-metolachlor in A. palmeri. Resistance is achieved by elevated baseline expression of these genes and further induction by S-metolachlor in resistant plants.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bd419189-ad89-4180-802c-a7ec79506984', '803905f3-9270-42c3-886f-742ece7e1135', 'Metabolic Pathways for S-Metolachlor Detoxification Differ Between Tolerant Corn and Multiple-Resistant Waterhemp', 'Strom SA, Hager AG, Concepcion JCT, Seiter NJ, Davis AS, Morris JA, Kaundun SS, Riechers DE', 2021, 'Plant & cell physiology', '10.1093/pcp/pcab132', 'https://doi.org/10.1093/pcp/pcab132', 'https://europepmc.org/articles/PMC8664635?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc', 'Herbicide resistance in weeds can be conferred by target-site and/or non-target-site mechanisms, such as rapid metabolic detoxification. Resistance to the very-long-chain fatty acid-inhibiting herbicide, S-metolachlor, in multiple herbicide-resistant populations (CHR and SIR) of waterhemp (Amaranthus tuberculatus) is conferred by rapid metabolism compared with sensitive populations. However, enzymatic pathways for S-metolachlor metabolism in waterhemp are unknown. Enzyme assays using S-metolachlor were developed to determine the specific activities of glutathione S-transferases (GSTs) and cytochrome P450 monooxygenases (P450s) from CHR and SIR seedlings to compare with tolerant corn and sensitive waterhemp (WUS). GST activities were greater (∼2-fold) in CHR and SIR compared to WUS but much less than corn. In contrast, P450s in microsomal extracts from CHR and SIR formed O-demethylated S-metolachlor, and their NADPH-dependent specific activities were greater (>20-fold) than corn or WUS. Metabolite profiles of S-metolachlor generated via untargeted and targeted liquid chromatography-mass spectrometry from CHR and SIR differed from WUS, with greater relative abundances of O-demethylated S-metolachlor and O-demethylated S-metolachlor-glutathione conjugates formed by CHR and SIR. In summary, our results demonstrate that S-metolachlor metabolism in resistant waterhemp involves Phase I and Phase II metabolic activities acting in concert, but the initial O-demethylation reaction confers resistance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('823b6666-36c4-4ba1-8ffa-6b2aea8520e7', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Enhanced herbicide degradation and dissipation of clomazone in two Montana soils', 'Eric R. Gallandt', 1988, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/7037', 'https://scholarworks.montana.edu/xmlui/handle/1/7037', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7057c95d-27a4-417b-9fbd-ee360f8748b0', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Factors Affecting Chlorsulfuron Injury to Rotational Crops', 'Mark A. Peterson', 1985, 'Open PRAIRIE (South Dakota State University)', NULL, 'https://openprairie.sdstate.edu/etd/4301', 'https://openprairie.sdstate.edu/etd/4301', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d749ba28-26a4-46e7-b29c-c7e43cd2f4fd', '803905f3-9270-42c3-886f-742ece7e1135', 'Metabolic resistance to pre-emergence herbicides in grasses', 'Duecker, Rebecka , Parcharidou, Evlampia , Brabetz, Veronika , Zoellner, Peter , Ries, Susanne , Collavo, Alberto , Luemmen, Peter , Beffa, Roland ', 2020, 'Julius-Kühn-Archiv', '10.5073/jka.2020.464.076', 'https://doi.org/10.5073/jka.2020.464.076', 'https://www.openagrar.de/receive/openagrar_mods_00093131', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Black-grass (Alopecurus myosuroides Huds.) and rye-grass (Lolium spp) are very competitive grass weeds. During the last decades, they have evolved resistance to post-emergence herbicides, in particular ACCase- and ALS- inhibitors. This requires more complex weed management strategies. To ensure good control of both weeds, pre-emergence treatments become increasingly important. Particularly flufenacet has become a key herbicide for the control of multiple-resistant black-grass and rye-grass. Yet, in some of those populations, reduced flufenacet efficacy start to be observed. In a screening with black-grass and rye-grass populations of worldwide origins, most populations could be controlled with the registered field rate of flufenacet, however differences in the level of flufenacet efficacy were observed and were in correlation with enhanced flufenacet metabolism. This was particularly the case for rye-grass populations. The use of flufenacet in mixtures with diflufenican, particularly in combination with flurtamone or metribuzin or aclonifen, improved the efficacy significantly. In decreased flufenacet sensitive populations, the efficacy of other pre-emergence herbicides like pendimethalin, prosulfocarb, S-metolachlor, dimethenamid-P and pethoxamid, was also significantly decreased whereas other herbicides like pyroxasulfone or diflufenican remained highly active. This decreased efficacy of flufenacet as well as S-metolachlor was associated with higher metabolism involving glutathione-s-transferases. Although differences between populations were sometimes relatively small, best weed management practices (e.g. application of full dose rates and mixtures) should be applied to reduce selection pressure and prevent the development of resistance. This is particularly important as flufenacet is one of the few still active herbicides suitable for the control of multiple-resistant grass weeds. Use of mixtures associated with agronomic solutions in an Integrated Weed Management approach has to be the main approach.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fdf5f651-3fe5-40ad-b357-14be235e1f81', '803905f3-9270-42c3-886f-742ece7e1135', 'PfGSTF2 endows resistance to quizalofop-p-ethyl in Polypogon fugax by GSH conjugation', 'Chen W, Bai D, Liao Y, Yu Q, Bai L, Pan L', 2025, 'Plant biotechnology journal', '10.1111/pbi.14491', 'https://doi.org/10.1111/pbi.14491', 'https://europepmc.org/articles/PMC11672750?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Populations of Polypogon fugax have developed resistance to many acetyl-CoA carboxylase (ACCase)-inhibiting herbicides. This resistance threats the effectiveness and sustainability of herbicide use. In our previous research, a field P. fugax population exhibited GST-based metabolic resistance to the widely used ACCase-inhibiting herbicide quizalofop-p-ethyl. Here, in this current study, we identified and characterized two GST genes (named as PfGSTF2 and PfGSTF58) that showed higher expression levels in the resistant than the susceptible population. Transgenic rice calli overexpressing PfGSTF2, but not PfGSTF58, became resistant to quizalofop-p-ethyl and haloxyfop-R-methyl. This reflects similar cross-resistance pattern to what was observed in the resistant P. fugax population. Transgenic rice seedlings overexpressing PfGSTF2 also exhibited resistance to quizalofop-p-ethyl. In contrast, CRISPR/Cas9 knockout of the orthologue gene in rice seedlings increased their sensitivity to quizalofop-p-ethyl. LC-MS analysis of in vitro herbicide metabolism by Escherichia coli-expressed recombinant PfGSTF2 revealed that quizalofop (but not haloxyfop) was detoxified at the ether bond, generating the GSH-quizalofop conjugate and a propanoic acid derivative with greatly reduced herbicidal activity. Equally, these two metabolites accumulated at higher levels in the resistant population than the susceptible population. In addition, both recombinant PfGSTF2 and PfGSTF58 can attenuate cytotoxicity by reactive oxygen species (ROS), suggesting a role in plant defence against ROS generated by herbicides. Furthermore, the GST inhibitor (NBD-Cl) reversed resistance in the resistant population, and PfGSTF2 (but not PfGSTF58) responded to NBD-Cl inhibition. All these suggest that PfGSTF2 plays a significant role in the evolution of quizalofop resistance through enhanced herbicide metabolism in P. fugax.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a53ae027-e304-4de6-a586-bc81290b0341', '803905f3-9270-42c3-886f-742ece7e1135', 'Rapid On-Farm Testing of Resistance in Lolium rigidum to Key Pre- and Post-Emergence Herbicides', 'Perez MB, Beckie HJ, Cawthray GR, Goggin DE, Busi R', 2021, 'Plants (Basel, Switzerland)', '10.3390/plants10091879', 'https://doi.org/10.3390/plants10091879', 'https://europepmc.org/articles/PMC8467281?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Overreliance on herbicides for weed control is conducive to the evolution of herbicide resistance. Lolium rigidum (annual ryegrass) is a species that is prone to evolve resistance to a wide range of herbicide modes of action. Rapid detection of herbicide-resistant weed populations in the field can aid farmers to optimize the use of effective herbicides for their control. The feasibility and utility of a rapid 7-d agar-based assay to reliably detect L. rigidum resistant to key pre- and post-emergence herbicides including clethodim, glyphosate, pyroxasulfone and trifluralin were investigated in three phases: correlation with traditional pot-based dose-response assays, effect of seed dormancy, and stability of herbicides in agar. Easy-to-interpret results were obtained using non-dormant seeds from susceptible and resistant populations, and resistance was detected similarly as pot-based assays. However, the test is not suitable for trifluralin because of instability in agar as measured over a 10-d period, as well as freshly-harvested seeds due to primary dormancy. This study demonstrates the utility of a portable and rapid assay that allows for on-farm testing of clethodim, glyphosate, and pyroxasulfone resistance in L. rigidum, thereby aiding the identification and implementation of effective herbicide control options.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49198e18-b9bb-455c-900d-af7bfdffad22', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'PREDICTION OF THE PERSISTENCE OF THE TRIAZINE HERBICIDES ATRAZINE, CYANAZINE, AND METRIBUZIN IN REGINA HEAVY CLAY', 'Allan E. Smith, Allan Walker', 1989, 'Canadian Journal of Soil Science', '10.4141/cjss89-059', 'https://doi.org/10.4141/cjss89-059', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjss89-059', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fcfeff8f-aa17-4d6c-88ef-c8b246a4135b', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Advancing Nutrient Management Strategies for Sustainable Crop Productivity in a Changing Climate: A Systematic Review', 'Yimer AH, Tarnawa A', 2025, 'TheScientificWorldJournal', '10.1155/tswj/7101060', 'https://doi.org/10.1155/tswj/7101060', 'https://europepmc.org/articles/PMC12638156?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Climate change poses significant challenges to global food security by disrupting agricultural nutrient dynamics through increased temperatures, altered precipitation patterns, and extreme weather events. These changes threaten crop productivity, soil health, and environmental sustainability. Traditional nutrient management practices, often reliant on excessive chemical fertilizer use, contribute to nutrient losses, soil degradation, and greenhouse gas emissions. This review systematically analyzes 65 peer-reviewed studies (1998-2024) selected using PRISMA guidelines, supplemented by bibliometric tools, to evaluate nutrient management strategies under climate change. The results highlight climate change''s multifaceted impacts on soil nutrient cycles, microbial activity, crop physiology, and crop yield. Elevated temperatures and CO2 levels alter nutrient availability and reduce grain quality, while erratic rainfall patterns exacerbate nutrient losses through leaching and runoff. Conventional fertilizer practices are shown to be inefficient and environmentally harmful, prompting a shift toward integrated nutrient management, precision agriculture, and biofertilizers. Emerging strategies such as slow- and controlled-release fertilizers, site-specific nutrient management, and decision support systems significantly improve nutrient use efficiency and reduce greenhouse gas emissions. Conservation agriculture and organic amendments further enhance soil health and resilience. The discussion highlights that integrated and adaptive nutrient management frameworks, supported by technology and agroecological practices, are critical for maintaining high productivity while minimizing environmental impacts under climate change. These approaches collectively support sustainable crop production, mitigate climate impacts, and promote long-term soil fertility. The review concludes that nutrient management is central to climate-smart agriculture and offers actionable insights for researchers, farmers, and policymakers aiming to secure food systems in a changing climate.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9e22f883-3ec2-4ad2-b266-74b9c7c84c88', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Agricultural practices can threaten soil resilience through changing feedback loops', 'Carswell AM, Willcock S, Blackwell MSA, Upadhayay HR, Harris P, McAuliffe G, Neal AL, Rivero MJ', 2025, 'NPJ sustainable agriculture', '10.1038/s44264-025-00098-6', 'https://doi.org/10.1038/s44264-025-00098-6', 'https://europepmc.org/articles/PMC12488477?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Soil has supported terrestrial food production for millennia; however, agricultural intensification may affect its resilience. Using a systems-thinking approach, we reviewed the impacts of conventional-agriculture practices on soil resilience and identified alternative practices that could mitigate these effects. We found that many practices only affect soil resilience with their long-term repeated use. Lastly, we ranked the impacts that pose the greatest threats to soil resilience and, consequently, food and feed security.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e152232e-68c5-4144-b816-e71a7a2a1d61', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Analysis of the Differences in Rhizosphere Microbial Communities and Pathogen Adaptability in Chili Root Rot Disease Between Continuous Cropping and Rotation Cropping Systems', 'Zhao Q, Cao X, Zhang L, Hu X, Zeng X, Wei Y, Zhang D, Xiao X', 2025, 'Microorganisms', '10.3390/microorganisms13081806', 'https://doi.org/10.3390/microorganisms13081806', 'https://europepmc.org/articles/PMC12388425?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'In chili cultivation, obstacles to continuous cropping significantly compromise crop yield and soil health, whereas crop rotation can enhance the microbial environment of the soil and reduce disease incidence. However, its effects on the diversity of rhizosphere soil microbial communities are not clear. In this study, we analyzed the composition and characteristics of rhizosphere soil microbial communities under chili continuous cropping (CC) and chili-cotton crop rotation (CR) using high-throughput sequencing technology. CR treatment reduced the alpha diversity indices (including Chao1, Observed_species, and Shannon index) of bacterial communities and had less of an effect on fungal community diversity. Principal component analysis (PCA) revealed distinct compositional differences in bacterial and fungal communities between the treatments. Compared with CC, CR treatment has altered the structure of the soil microbial community. In terms of bacterial communities, the relative abundance of Firmicutes increased from 12.89% to 17.97%, while the Proteobacteria increased by 6.8%. At the genus level, CR treatment significantly enriched beneficial genera such as RB41 (8.19%), Lactobacillus (4.56%), and Bacillus (1.50%) (p Alternaria and Fusarium in the fungal community decreased by 6.62% and 5.34%, respectively (p Bacillus, whereas CC favored enrichment of pathogens, such as Firmicutes. Fusarium solani MG6 and F. oxysporum LG2 are the primary chili root-rot pathogens. Optimal growth occurs at 25 °C, pH 6: after 5 days, MG6 colonies reach 6.42 ± 0.04 cm, and LG2 5.33 ± 0.02 cm, peaking in sporulation (p < 0.05). In addition, there are significant differences in the utilization spectra of carbon and nitrogen sources between the two strains of fungi, suggesting their different ecological adaptability. Integrated analyses revealed that CR enhanced soil health and reduced the root rot incidence by optimizing the structure of soil microbial communities, increasing the proportion of beneficial bacteria, and suppressing pathogens, providing a scientific basis for microbial-based soil management strategies in chili cultivation.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e94211db-9079-41c4-aa10-1f553758e8a2', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Application of a Laboratory Bioassay for Assessment of Bioactivity of ALS-Inhibiting Herbicides in Soil', 'Anna M. Szmigielski, Bryce G. L. Geisel, Frederick A. Holm, Eric N. Johnson, J.J. Schoenau', 2011, 'InTech eBooks', '10.5772/12955', 'https://doi.org/10.5772/12955', 'https://www.intechopen.com/citation-pdf-url/12588', NULL, NULL, 14, NULL, 'prairies', 4, 'cc-by-nc-sa', 'Application of a Laboratory Bioassay for Assessment of Bioactivity of ALS-Inhibiting Herbicides in Soil', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc4e6798-fa20-40f5-966f-890ab2c59657', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Biostimulation for the Enhanced Degradation of Herbicides in Soil', 'Ramdas Gopinath Kanissery, Gerald K. Sims', 2011, 'Applied and Environmental Soil Science', '10.1155/2011/843450', 'https://doi.org/10.1155/2011/843450', 'https://downloads.hindawi.com/journals/aess/2011/843450.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'cc-by', 'Cleanup of herbicide-contaminated soils has been a dire environmental concern since the advent of industrial era. Although microorganisms are excellent degraders of herbicide compounds in the soil, some reparation may need to be brought about, in order to stimulate them to degrade the herbicide at a faster rate in a confined time frame. “Biostimulation” through the appropriate utilization of organic amendments and nutrients can accelerate the degradation of herbicides in the soil. However, effective use of biostimulants requires thorough comprehension of the global redox cycle during the microbial degradation of the herbicide molecules in the soil. In this paper, we present the prospects of using biostimulation as a powerful remediation strategy for the rapid cleanup of herbicide-polluted soils.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b95212b3-5ce7-44a9-b480-98529d976cda', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Cover Crops: A Component of an Integrated Weed Management Strategy for Ontario Field Crops', 'Taïga B. Cholette', 2017, 'The Atrium (University of Guelph)', NULL, 'http://hdl.handle.net/10214/10343', 'http://hdl.handle.net/10214/10343', NULL, NULL, 175, NULL, 'canada', 3, 'cc-by-nd', 'Cover crops have many desirable attributes including reduced soil erosion, increased soil organic matter and reduced weed density. However, cover crops can be injured by residues from herbicides used for weed control in the previous crop and cover crops can negatively impact the main cash-generating crop through resource competition. Three field studies were conducted to determine the impact of winter wheat and soybean herbicides on the establishment and growth of oilseed radish, the suppression of glyphosate-resistant Canada fleabane in corn with cover crops seeded the previous summer/fall after winter wheat harvest and the suppression of annual ryegrass in corn with nicosulfuron to prevent grain corn yield losses due to cover crop interference. Winter wheat herbicides applied in the spring caused <5% oilseed radish injury and there was no reduction in oilseed radish density and biomass. Imazethapyr, applied preemergence and postemergence to soybean caused 48 and 59% oilseed radish injury 28 days after emergence, respectively. Imazethapyr did not reduce oilseed radish density; however, when applied postemergence it reduced oilseed radish biomass by 65%. All 17 cover crops seeded after winter wheat combining suppressed glyphosate-resistant Canada fleabane from May to September in corn grown the year after winter wheat. Crimson clover plus annual ryegrass was the only cover crop that resulted in a glyphosate-resistant Canada fleabane density similar to the weed-free control. Grain corn yields were not affected by the cover crops evaluated. There was no difference between nicosulfuron (0.8, 1.6, 3.1, 6.3, 12.5, 25 and 50 g ai ha-1) applied at either the 2-3 leaf stage or the 4-5 leaf/1-tiller stage of annual ryegrass that was planted at the same time as corn for all parameters evaluated. Grain corn yield ranged from 14.5 to 15.0 t ha-1 when annual ryegrass was treated with nicosulfuron at 0.8 and 25 g ai ha-1 while the weed-free control had yield of 15.5 t ha-1.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9b200575-fe49-478d-b70f-741be7a816e9', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Development of a Real-Time Quantitative PCR Assay for Direct Detection and Quantification of the Root-Lesion Nematode Pratylenchus penetrans in Potato Roots', 'Poudel D, Yan G', 2025, 'International journal of molecular sciences', '10.3390/ijms26167711', 'https://doi.org/10.3390/ijms26167711', 'https://europepmc.org/articles/PMC12386274?pdf=render', NULL, NULL, 21, NULL, 'northern_plains', 3, 'cc by', 'The root-lesion nematode, Pratylenchus penetrans, is a migratory endoparasite that attacks potato roots, causing necrotic lesions and yield losses of up to 73%. Traditional detection and quantification methods are labor-intensive, time-consuming, and require prior nematode extraction and taxonomic expertise. This study aimed to develop a SYBR Green-based real-time quantitative PCR (qPCR) assay for detecting and quantifying P. penetrans directly from potato root DNA extracts. Bovine serum albumin (BSA) was tested to neutralize qPCR inhibitors in root DNA extracts. The assay showed high specificity and sensitivity to P. penetrans, detecting 1.56 × 10-2 of a single nematode in 0.2 g of roots. A standard curve based on artificial nematode inoculations demonstrated a strong linear relationship between Cq values and log-transformed nematode numbers (R2 = 0.993) with high amplification efficiency. Assessment using root samples from two greenhouse experiments involving five potato cultivars showed strong correlations (r = 0.902 and 0.887) between qPCR estimates and microscopic nematode counts. This study presents a new qPCR assay specifically optimized for direct detection and quantification of P. penetrans within potato root tissues, offering enhanced sensitivity and applicability for rapid in planta diagnostics to facilitate effective management strategies.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18f970bc-c647-4b06-9cf8-485bd80ed45f', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Effects of Different Crop Rotations on Microbial Diversity and Enzyme Activities in Brassica napus Rhizosphere Soil', 'Tian X, Duan J, Huo H, Huangfu J, Yan M, Lu H, Li Z, Song P', 2025, 'Microorganisms', '10.3390/microorganisms14010091', 'https://doi.org/10.3390/microorganisms14010091', 'https://europepmc.org/articles/PMC12844264?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Continuous cropping of Brassica napus impairs sustainable production via soil nutrient imbalance and microecological degradation. We evaluated rhizosphere soil properties and microbial communities under rotations crops (Triticum aestivum [TaBn], Beta vulgaris [BvBn], Glycine max [GmBn], Sorghum bicolor [SbBn], Hordeum vulgare [HvBn], and Brassica napus [BnBn]). BvBn had the highest total nitrogen, total potassium, available potassium, and organic matter contents. TaBn exhibited the highest soil enzyme activities, and its bacterial/fungal Chao1/Simpson indices and unique operational taxonomic units (OTUs; bacteria: 333, fungi: 37) exceeded other patterns. Principal coordinate analysis showed distinct microbial community separation in BvBn/TaBn versus BnBn. TaBn enriched dominant bacterial phyla Pseudomonadota and Actinomycetota; all preceding crops increased fungal phylum Ascomycota while reducing Mucoromycota. Comprehensive assessment confirmed all preceding crops, except oilseed rape altered rhizosphere microbial structure, with TaBn as the optimal preceding crops.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cbde6201-561c-42fc-9021-49fb8eb56006', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Efficacy, Fruit Residues, and Soil Dissipation of the Herbicide Metolachlor in Processing Tomato', 'J. D. Gaynor, Allan S. Hamill, D. C. MacTavish', 1993, 'Journal of the American Society for Horticultural Science', '10.21273/jashs.118.1.68', 'https://doi.org/10.21273/jashs.118.1.68', 'https://journals.ashs.org/downloadpdf/journals/jashs/118/1/article-p68.pdf', NULL, NULL, NULL, NULL, 'canada', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a3619c1b-322a-4319-b064-935227882af4', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Family farming | the path not taken', 'Thomas Joseph Antonick', 1997, 'The Mathematics Enthusiast', NULL, 'https://scholarworks.umt.edu/etd/2321', 'https://scholarworks.umt.edu/etd/2321', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'public-domain', 'Family farming had been an integral component of United States agricultural policy from the Revolutionary period through the latter part of the twentieth century.The role of the U,S, government increased tremendously following the Great Depression.However. the family farm began to be replaced by industrial agribusiness by the late 1370s,In 1981 the Department of Agriculture published a report stating that government policies v/ould have to be revamped in order to reverse the trend tov/ards industrial agribusiness.By the end of the 1980s it had become apparent that family farming occupied a diminished role in overall agricultural production.Thus, a choice had been made to replace family farms with industrial agribusiness as the major component in terms of overall U.S. agricultural production The 199 5 farm bill made tremendous changes in U.S. farm policy.The stated intent is to end government involvement in agricultural policy.There are many implications associated with this action.The transition from family farming to industrial agribusiness has led to tremendous concentration in both production and marketing.Additionally, agribusiness farming practices have far greater ecological impacts than the methods employed by family farmers, As a result of these developments at the federal level, state governments, and elements in the private sector, have intervened.Consequently, there have been attempts to bolster opportunities for potential family farmers.However, entry into farming still requires an enormous amount of capital.This is a situation that is quite a contrast to the predicament faced by farmers of previous generat ions.Family farmers, and the opportunity to be one, have become almost non-existent.This development ushers in a new era in agriculture.Many of the consequences have been predicted, and others will evolve as the end of government involvement in agriculture moves closer.Regardless, for present and future generations, a freedom has been lost which dates back to the Revolutionary Period, the freedom to farm, CHAPTER ONE', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5b8e8abd-7365-4a7e-b3a9-7997a0041c7e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Fungal endophytes influence soil organic carbon and nitrogen fractions promoting carbon sequestration and improving grain yield in soybean', 'Singh V, Gamage H, Jones A, Wood HV, Bruning B, James A, Van Drie P, Purushotham N', 2025, 'Scientific reports', '10.1038/s41598-025-94982-3', 'https://doi.org/10.1038/s41598-025-94982-3', 'https://europepmc.org/articles/PMC11968937?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by-nc-nd', 'Fungal endophyte inoculants present a promising avenue for enhancing carbon sequestration in agricultural systems. These endophytes can significantly influence soil organic carbon (SOC) and nitrogen (N) fractions by modulating root exudation, soil aggregation, and organic matter decomposition. We investigated the effectiveness of commercial-stage fungal endophyte seed inoculants in an Australian soybean field trial to increase yield, total SOC, stable SOC fractions, and soil N. After one growing season, specific inoculants (Thozetella sp. and Leptodontidium sp.) and dosages increased soybean grain yield and stocks of soil organic matter (SOM) as aggregate occluded particulate organic matter (oPOM) C and N, and mineral-associated organic matter (MAOM) C and N in the topsoil layer (0-15 cm). Furthermore, positive correlations were established between grain yield and the stocks of oPOM (C and N) and MAOM (C and N) in the topsoil layer (0-15 cm). Importantly, increasing grain yield was significantly and positively associated with the proportion of oPOM-C and N stocks to total SOM stock, providing evidence of significant carbon sequestration in oPOM. However, the proportion of MAOM-C and N stock to total SOM stock decreased significantly with increasing grain yield, indicating higher proportion of MAOM is being turned over relative to other SOM fractions although the absolute amounts of MAOM-C and N remained stable. These findings suggest that fungal endophytes and dosages may have variable but potentially beneficial impacts on crop growth, yield and play a crucial role in altering SOM fractions. This alteration potentially leads to changed carbon sequestration strategies, emphasising the need for further research into fungal endophyte-mediated carbon sequestration mechanisms.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a064960d-2ac6-44e1-a286-fcfd752cd58f', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Glyphosate use in agricultural production: it''s contribution to global carbon dioxide emissions', 'Brookes G', 2026, 'GM crops & food', '10.1080/21645698.2025.2594217', 'https://doi.org/10.1080/21645698.2025.2594217', 'https://europepmc.org/articles/PMC12721089?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'This paper estimates the annual global carbon dioxide equivalent (CO2e) emissions from the manufacture, distribution and farm level use of glyphosate and estimates the annual contribution of glyphosate to reducing CO2e emissions through its role in facilitating a shift in farming production practices that are tillage-based into conservation tillage systems based on reduced and no tillage. Total annual global use of glyphosate is 749.27 million kg of active ingredient, applied to 646.11 million (spray) hectares. The CO2e emission generated from the manufacture, distribution and application of glyphosate in global agriculture is annually 9.76 billion kg. The total global combined annual fuel and soil carbon retention-related CO2e emissions of conservation tillage are a net reduction of -138.2 billion kg CO2e. This compares with +41.47 billion kg CO2e emissions if this area had been plowed with conventional tillage practices. Therefore, conservation tillage practices provide a net reduction in combined annual fuel and increased soil carbon retention-related emissions of -179.67 billion kg CO2e relative to a conventional plow-based alternative production system. The total global combined annual fuel and soil carbon retention-related CO2e emissions of conservation tillage attributable to glyphosate is estimated at a net reduction of -41.93 billion kg CO2e. This compares with +13.01 billion CO2e emissions if this area had been plowed, providing a net reduction in combined fuel and soil carbon-related emissions attributable to glyphosate of -54.94 billion kg CO2e annually or the equivalent of taking 21.8 million cars off the road each year.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3a7ef324-020e-4244-aa49-a2bb91ecab98', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Green manures and crop residues for soil fertility restoration in paddy-based cropping systems of monsoon Asia: balancing carbon sequestration and greenhouse gas emissions', 'Hiroyuki Daimon', 2026, 'Plant Production Science', '10.1080/1343943X.2026.2751623', 'https://doi.org/10.1080/1343943X.2026.2751623', 'https://www.tandfonline.com/doi/10.1080/1343943X.2026.2751623', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Paddy-based cropping systems are the foundation of crop production in monsoon Asia, but their long-term sustainability is increasingly compromised by soil organic carbon depletion and declining soil nitrogen fertility, particularly where paddy fields are converted to upland use for wheat, soybean, and other crops. Green manures have long been used as on-farm sources of organic matter and biologically fixed nitrogen, but their role is being re-evaluated in the context of reduced fertilizer dependence, soil fertility restoration, and climate change mitigation. This review summarizes studies since the 1970s on the agronomic characteristics and utilization of green manure crops in paddy-based systems of monsoon Asia, with particular attention to Chinese milk vetch, hairy vetch, Sesbania, Crotalaria, green manure soybean, and Azolla. The integrated use of green manures with rice straw and other crop residues is examined as a strategy for maintaining soil organic carbon, enhancing nitrogen self-support capacity, and improving the resilience of rice-upland rotations. Finally, greenhouse gas trade-offs associated with organic matter incorporation, especially methane emissions under flooded conditions and nitrous oxide emissions under aerobic or intermittently aerobic conditions, are discussed. Although low-C/N leguminous green manures can partially replace synthetic nitrogen fertilizers and synchronize nitrogen release with crop demand, high-C/N residues such as rice straw are essential for long-term carbon maintenance. Future paddy-based cropping systems should therefore integrate green manures and crop residues in region-specific ways that balance soil fertility restoration, crop productivity, carbon sequestration, and greenhouse gas mitigation.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('70ad3d5f-fbc3-4611-90d3-3f6f92a393e1', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Effect of Chemical Management on Weed Diversity and Community Structure in Soybean–Corn Succession in Brazil’s Triângulo Mineiro Region', 'Júlia Resende Oliveira Silva, Décio Karam, Kassio Ferreira Mendes', 2026, 'Ecologies', '10.3390/ecologies7010012', 'https://doi.org/10.3390/ecologies7010012', 'https://www.mdpi.com/2673-4133/7/1/12', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Knowledge of weed community structure in agricultural systems is important for sustainable management, especially for evaluating the effects of different herbicides on soybean–corn succession crops. This study evaluated, over two crop seasons, weed community structure in response to chemical weed management strategies for soybean–corn succession in Brazil’s Triângulo Mineiro region. Phytosociological surveys of the weed community were conducted during harvest periods throughout the experimental phase, with referenced data for generating spatial distribution maps of biomass and density of the main present species. The survey identified 33 weed species, predominantly from the Poaceae and Asteraceae families. Regardless of the management system, the total weed biomass was lower in corn crops compared to soybean crops. In management systems using six different herbicides, the IVI of Commelina benghalensis was the lowest due to greater diversification of herbicide mechanisms of action. The results demonstrate that chemical weed management strategies strongly influence weed community structure, with significant effects on weed community structure and evenness in intensive agricultural regions. These changes also have implications for resistance management.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0e705d62-3ce5-4082-b807-bf1bce9a3b90', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Guidance on the assessment of pesticide residues in rotational crops', 'Greco L, Janossy J, Jarrah S, Kazocina A, Magrans JO, Reich H', 2023, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2023.8225', 'https://doi.org/10.2903/j.efsa.2023.8225', 'https://europepmc.org/articles/PMC10686009?pdf=render', NULL, NULL, 86, NULL, 'other', 1, 'cc by-nd', 'EFSA has prepared a guidance document on the assessment of studies on the nature and magnitude of pesticide residues in rotational crop studies as defined in Section 6.6 of the Annex to Regulation (EU) No 283/2013. This guidance document supports the practical implementation of the relevant OECD Test Guidelines (TGs) and OECD Guidance Documents in a harmonised way, respecting the EU regulatory framework for the pesticide assessments. The individual steps of the assessment are illustrated by examples, figures and flow charts. Sources of uncertainty in these assessments are identified and recommendations for further work are provided.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0d4b34e6-8922-4e5b-b6f0-a916c14de855', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Influence of residual flucarbazone-sodium on inoculation success measured by growth parameters, nitrogen fixation, and nodule occupancy of field pea', 'Kuni Niina', 2008, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-09182008-171944', 'http://hdl.handle.net/10388/etd-09182008-171944', NULL, NULL, 126, NULL, 'prairies', 4, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c41954ac-db82-4387-9036-68800021bf6e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Long-term application of FYM and fertilizer N improve soil fertility and enzyme activity in 51st wheat cycle under pearl millet-wheat', 'Sheoran S, Prakash D, Yadav PK, Gupta RK, Al-Ansari N, El-Hendawy S, Mattar MA', 2024, 'Scientific reports', '10.1038/s41598-024-72076-w', 'https://doi.org/10.1038/s41598-024-72076-w', 'https://europepmc.org/articles/PMC11408662?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Our study from an ongoing research experiment initiated in Rabi 1967 at the Research Farm of CCS Haryana Agricultural University, Haryana, India, reports that during the 51st wheat cycle in pearl millet-wheat sequence, adding FYM in both seasons significantly impacted various soil parameters at different wheat growth stages compared to the rabi season. The application of 15 t of FYM ha-1 resulted in a considerable increase in dissolved organic carbon content (9.1-11.2%), available P (9.7-12.1%), and available S (12.6-17.1%), DHA levels by 7.3-22.0%, urease activity (10.1 and 17.0%), β-Glucosidase activity (6.2-8.4%), and APA activity (5.2-10.6%), compared to 10 t FYM ha-1. Application of N120 exhibited a considerable improvement in DHA (11.0-23.2%), β-Glucosidase (9.4-19.2%), urease (13.3-28.3%), and APA (3.3-6.2%) activity compared to control (N0). At stage 3, the box plot revealed that 50% of the available N, P, and S values varied from 223.1 to 287.9 kg ha-1, 53.0 to 98.2 kg ha-1, and 50.0 to 97.6 kg ha-1, respectively. Principal component analysis, with PC1 explaining 94.7% and PC2 explaining 3.15% of the overall variability, and SOC had a polynomial relationship with soil characteristics (R2 = 0.89 to 0.99). Applying FYM15 × N120 treatment during both seasons proved beneficial in sustaining the health of sandy loam soil in North-West India.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1a84a01c-71ab-4f6c-90c8-37e7f93beb9f', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Low carryover risk of corn and soybean herbicides across soil management practices and environments', 'Kolby R. Grint, Christopher A. Proctor, Ryan P. DeWerff, Daniel H. Smith, Nicholas John Arneson, Francisco J. Arriaga, David E. Stoltenberg, Rodrigo Werle', 2021, 'Weed Technology', '10.1017/wet.2021.97', 'https://doi.org/10.1017/wet.2021.97', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/39DBCCEE60BE2EF9A71E89FE47534A59/S0890037X2100097Xa.pdf/div-class-title-low-carryover-risk-of-corn-and-soybean-herbicides-across-soil-management-practices-and-environments-div.pdf', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Herbicides with soil-residual activity have the potential for carryover into subsequent crops, resulting in injury to sensitive crops and limiting productivity if severe. The increased use of soil-residual herbicides in the United States for management of troublesome weeds in corn- and soybean-cropping systems has potential to result in more cases of carryover. Soil management practices have different effects on the soil environment, potentially influencing herbicide degradation and likelihood of carryover. Field experiments were conducted at three sites in 2019 and 2020 to determine the effects of corn (clopyralid and mesotrione) and soybean (fomesafen and imazethapyr) herbicides applied in the fall at reduced rates (25% and 50% of labeled rates) and three soil management practices (tillage, no-tillage, and a fall-established cereal rye cover crop) on subsequent growth and productivity of the cereal rye cover crop and the soybean and corn crops, respectively. Most response variables (cereal rye biomass and crop canopy cover at cover crop termination in the spring, early-season crop stand and herbicide injury ratings, and crop yield) were not affected by herbicide carryover. Corn yield was lower when soil was managed with a cereal rye cover crop compared with tillage at all three sites, while yield was lower for no-till compared with tillage at two sites. Soybean yield was lower when managed with a cereal rye cover crop compared with tillage and no-till at one site. Findings from this research indicate a low carryover risk for these herbicides across site-years when label rotational restrictions are followed and environmental conditions favorable for herbicide degradation exist, regardless of soil management practice on silt loam or silty clay loam soil types in the U.S. Midwest region.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ec326ee3-307f-4be7-9414-94870aae7c8f', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Herbicide Resistance in Plants', 'Beckie HJ', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9040435', 'https://doi.org/10.3390/plants9040435', 'https://europepmc.org/articles/PMC7238419?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Herbicide resistance in weeds is perhaps the most prominent research area within the discipline of weed science today. Incidence, management challenges, and the cost of multiple-resistant weed populations are continually increasing worldwide. Crop cultivars with multiple herbicide-resistance traits are being rapidly adopted by growers and land managers to keep ahead of the weed resistance tsunami. This Special Issue of Plants comprises papers that describe the current status and future outlook of herbicide resistance research and development in weedy and domestic plants, with topics covering the full spectrum from resistance mechanisms to resistance management. The unifying framework for this Special issue, is the challenge initially posed to all of the contributors: what are the (potential) implications for herbicide resistance management?', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3482a70f-cc64-4c15-a7e9-b2a9b3e649be', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Machine Learning Approaches to Assess Soil Microbiome Dynamics and Bio-Sustainability', 'Pace R, Monti MM, Cuomo S, Affinito A, Ruocco M', 2026, 'Physiologia plantarum', '10.1111/ppl.70719', 'https://doi.org/10.1111/ppl.70719', 'https://europepmc.org/articles/PMC12766673?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Understanding soil microbiota dynamics is essential for enhancing bio-sustainability in agriculture, yet the complexity of microbial communities hampers the prediction of their functional roles. Artificial intelligence (AI) and machine learning (ML) offer powerful tools to analyse high-dimensional microbiome data generated by high-throughput sequencing. Here, we apply unsupervised AI-based algorithms to uncover microbial patterns that are not immediately recognisable but are crucial for characterising the biological status of agricultural soils. Soil samples were collected from a site in Northern Italy managed under four strategies: conventional farming without organic matter (C), with organic matter (C + O), with beneficial microorganisms but without organic matter (M), and with both beneficial microorganisms and organic matter (M + O). Metagenomic amplicon sequencing of the 16S ribosomal RNA (rRNA) gene and the internal transcribed spacer (ITS) region was used to profile bacterial and fungal communities. Principal component analysis (PCA), k-means clustering, and t-distributed stochastic neighbour embedding (t-SNE) revealed coherent temporal trajectories in both datasets, with sampling time and crop presence emerging as dominant drivers of community assembly and only subtle compositional shifts attributable to treatments. Fungal communities exhibited higher plasticity and a stronger response to management than bacterial communities, which converged towards a stable oligotrophic core. Our findings highlight the complementary roles of fungal and bacterial guilds and show that unsupervised ML-based workflows provide an effective framework to disentangle temporal and treatment effects in complex microbiome datasets. This exploratory study lays the groundwork for future predictive models aimed at identifying microbial indicators of soil biological status and supporting bio-sustainable agronomic decisions.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('58896664-3105-47d8-84b9-ea0082483c66', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Metagenomic analysis reveal the phytoremediation effects of monocropping and intercropping of halophytes Halogeton glomeratus and Suaeda glauca in saline soil of Northwestern China', 'Wang J, Song M, Yao L, Li P, Si E, Li B, Meng Y, Ma X', 2025, 'BMC plant biology', '10.1186/s12870-025-06225-2', 'https://doi.org/10.1186/s12870-025-06225-2', 'https://europepmc.org/articles/PMC11834545?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc-nd', 'AimsPlanting halophytes is a widely used method of phytoremediation for saline soils. The succulent halophytes Halogeton glomeratus and Suaeda glauca are widely used for remediation of saline soil in the arid region of Northwestern China. However, whether intercropping of H. glomeratus and S. glauca can increase the improvement effect for saline soil is yet to be proved.Materials and methodsTherefore, this study analyzed three phytoremediation planting modes: monocropping of H. glomeratus (Hg), monocropping of S. glauca (Sg), and H. glomeratus and S. glauca intercropping (Hg||Sg). These were applied in field experiments, with biomass and soil physicochemical properties measured for each treatment, and the mechanism was analyzed using macrogenomics.ResultsAfter harvesting the halophytes after one season, the Hg treatment had the highest dry biomass and soil total dissolved salt content was reduced; correspondingly, soil pH were decreased and soil organic matter content were increased. The results showed that Actinobacteria, Acidobacteria and Proteobacteria were the dominant phylum under the four treatments. This suggests that Hg treatment was more capable of producing microorganisms favorable to saline soil remediation.ConclusionsThus, H. glomeratus monocropping is a more effective phytoremediation strategy for saline soil in the dry zone of Northwestern China.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e645cef9-62ee-4faa-918c-43fe372bc4e8', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Relating soil herbicide residue levels to sugar beet stand and growth reduction', 'Adam R. Kennedy, Sushmita Sharma, Clarke G. Alder, Albert T. Adjesiwor', 2025, 'Agrosystems Geosciences & Environment', '10.1002/agg2.70131', 'https://doi.org/10.1002/agg2.70131', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/agg2.70131', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Abstract One common recommendation given to farmers who suspect herbicide carryover to sugar beet ( Beta vulgaris L.) is to conduct laboratory tests to assess herbicide residue levels in the soil. While this is often a good practice, there are currently no guidelines on how these laboratory test results relate to sugar beet damage or yield loss. Greenhouse studies were conducted in 2022 and 2023 to assess the relationship between soil residue levels of six herbicides (flumioxazin, imazamox, mesotrione, metribuzin, rimsulfuron, and terbacil) and sugar beet stand and growth reduction. At levels below the limit of detection in the laboratory, rimsulfuron reduced sugar beet stand density by more than 50% and biomass by 25%. Sugar beet stand density and biomass were reduced by about 40% and 25%, respectively, at metribuzin residue levels below the limit of detection. Similarly, flumioxazin reduced stand density and biomass by 50% at residue levels below the limit of detection. Stand density and biomass reduction due to mesotrione exceeded 50% even at residue levels below the limit of detection. Imazamox and terbacil caused minimal sugar beet stand and biomass reduction at residue levels below the limit of detection. These results demonstrate that laboratory analysis of herbicide residue levels in the soil must be accompanied by a bioassay to determine the potential crop damage from herbicide carryover.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ede4caa-2eee-4133-b462-fa8c5df4ad20', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Minirhizotron measurements can supplement deep soil coring to evaluate root growth of winter wheat when certain pitfalls are avoided', 'Arnhold J, Ispizua Yamati FR, Kage H, Mahlein AK, Koch HJ, Grunwald D', 2024, 'Plant methods', '10.1186/s13007-024-01313-0', 'https://doi.org/10.1186/s13007-024-01313-0', 'https://europepmc.org/articles/PMC11650824?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'BackgroundRoot growth is most commonly determined with the destructive soil core method, which is very labor-intensive and destroys the plants at the sampling spots. The alternative minirhizotron technique allows for root growth observation throughout the growing season at the same spot but necessitates a high-throughput image analysis for being labor- and cost-efficient. In this study, wheat root development in agronomically varied situations was monitored with minirhizotrons over the growing period in two years, paralleled by destructive samplings at two dates. The aims of this study were to (i) adapt an existing CNN-based segmentation method for wheat minirhizotron images, (ii) verify the results of minirhizotron measurements with root growth data obtained by the destructive soil core method, and (iii) investigate the effect of the presence of the minirhizotron tubes on root growth.ResultsThe previously existing CNN could successfully be adapted for wheat root images. The minirhizotron technique seems to be more suitable for root growth observation in the subsoil, where a good agreement with destructively gathered data was found, while root length results in the topsoil were dissatisfactory in comparison to the soil core method in both years. The tube presence was found to affect root growth only if not installed with a good soil-tube contact which can be achieved by slurrying, i.e. filling gaps with a soil/water suspension.ConclusionsOverall, the minirhizotron technique in combination with high-throughput image analysis seems to be an alternative and valuable technique for suitable research questions in root research targeting the subsoil.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad2ad990-7124-40ad-84b0-bd0b9187e441', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Modeling pollen-mediated gene flow from glyphosate-resistant to -susceptible giant ragweed (Ambrosia trifida L.) under field conditions', 'Ganie ZA, Jhala AJ', 2017, 'Scientific reports', '10.1038/s41598-017-16737-z', 'https://doi.org/10.1038/s41598-017-16737-z', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC5719015.1/PMC5719015.1.pdf', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'A field experiment was conducted to quantify pollen mediated gene flow (PMGF) from glyphosate-resistant (GR) to glyphosate-susceptible (GS) giant ragweed under simulated field conditions using glyphosate resistance as a selective marker. Field experiments were conducted in a concentric design with the GR giant ragweed pollen source planted in the center and GS giant ragweed pollen receptors surrounding the center in eight directional blocks at specified distances (between 0.1 and 35 m in cardinal and ordinal directions; and additional 50 m for ordinal directions). Seeds of GS giant ragweed were harvested from the pollen receptor blocks and a total of 100,938 giant ragweed plants were screened with glyphosate applied at 2,520 g ae ha-1 and 16,813 plants confirmed resistant. The frequency of PMGF was fit to a double exponential decay model selected by information-theoretic criteria. The highest frequency of gene flow (0.43 to 0.60) was observed at ≤0.5 m from the pollen source and reduced rapidly with increasing distances; however, gene flow (0.03 to 0.04) was detected up to 50 m. The correlation between PMGF and wind parameters was inconsistent in magnitude, direction, and years.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46372007-8b44-4393-a052-a1f0c40cb41a', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Soil health improvements under cover crops are associated with enhanced soil content of cytokinins', 'Perera I, Kisiala A, Thompson KA, Emery RJN', 2025, 'Plant biology (Stuttgart, Germany)', '10.1111/plb.13743', 'https://doi.org/10.1111/plb.13743', 'https://europepmc.org/articles/PMC11846634?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by', 'Cytokinins (CKs) are phytohormones produced by plants and other soil life. including bacteria, fungi, insects, and earthworms. These organisms can release CKs to the soil, which may have positive implications for soil health and plant growth. However, no studies have examined phytohormones as soil health indicators. In custom-designed rhizo-pots that separated rhizosphere and bulk soils, the cover crops tillage radish and cereal rye were used to manipulate soil health parameters: soil pH, soil organic matter, soil active carbon, soil microbial community diversity, and extracellular enzyme activities involved in C, N and P cycling. Data were compared to impacts of cover crops on CKs that were purified from the complex soil and measured with HPLC-HRMS/MS. From soil we detected free base-CKs (trans-zeatin (tZ), isopentenyladenine (iP)), riboside-CKs (RB-CKs), cis-zeatin riboside (cZR), isopentenyladenosine (iPR) and four methylthiolated CKs: 2-methylthio-zeatin (2MeSZ), 2-methylthio-zeatin ribosides (2MeSZR), 2-methylthio-isopentenyladenine (2MeSiP), and 2-methylthio-isopentenyladenine riboside (2MeSiPR). These CK levels were significantly enhanced in cover cropped soil compared to uncultivated soil, and reflect a positive relationship between soil CK profiles and other soil health parameters - notably, between total CK and active C levels and soil microbial community diversity. This is the first detailed soil CK analysis and assessment of its potential use as a novel, reliable, short-term soil health parameter. The increased CK concentrations in cover cropped soils likely reflects the activity levels of soil life (plants, microbes, animals) and provides a rationale to use CKs as tools to evaluate soil health as influenced by agricultural management strategies.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b243d64a-2e9a-40d5-864f-6e65ee3fd26e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Nitrogen Management in Crop-Soil-Environment Systems: Pathways Toward Sustainable and Climate-Resilient Agriculture', 'Veres S, Elhawat N, Rengel Z, Alshaal T', 2026, 'International journal of molecular sciences', '10.3390/ijms27052477', 'https://doi.org/10.3390/ijms27052477', 'https://europepmc.org/articles/PMC12985628?pdf=render', NULL, NULL, 48, NULL, 'other', 1, 'cc by', 'Abiotic stresses including drought, salinity, heat, cold, and heavy metal toxicity severely constrain plant productivity worldwide. Nitrogen (N), beyond its fundamental nutritional role, has emerged as a central regulator of plant stress responses through its involvement in metabolic reprogramming, osmotic adjustment, antioxidant defense, and hormonal signaling. This review synthesizes current advances in understanding how nitrogen availability and form influence plant tolerance to major abiotic stresses. Particular emphasis is placed on nitrogen-mediated modulation of reactive oxygen species (ROS) scavenging systems, nitrogen-carbon metabolic coordination, phytohormonal crosstalk, osmoprotectant biosynthesis, and regulation of stress-responsive gene expression. Recent molecular insights highlight the role of nitrogen transporters, nitrate signaling pathways, and nitrogen-use efficiency in stress adaptation mechanisms. Furthermore, agronomic and biotechnological strategies aimed at optimizing nitrogen management to enhance stress resilience are discussed, including precision fertilization, integrated nutrient management, and genetic approaches targeting nitrogen-responsive regulatory networks. By integrating physiological, biochemical, and molecular perspectives, this review provides a comprehensive framework for understanding nitrogen-driven mitigation strategies under abiotic stress conditions and outlines future research directions for sustainable crop production in changing environments.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('58bb2b08-88cb-47b8-9c95-79c780b1e684', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'West River Ag Center Crops and Soils Research Annual Progress Report, 2009', 'Agricultural Experiment Station', 2010, 'Open PRAIRIE (South Dakota State University)', NULL, 'https://openprairie.sdstate.edu/agexperimentsta_rsp/202', 'https://openprairie.sdstate.edu/agexperimentsta_rsp/202', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3548157a-406e-4f12-9568-787738c43c6e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'On-farm corn stover and cover crop residue recycling with biostimulant Re-Gen increases corn yields and resultant milk yields in multi-year dairy cattle farm trials', 'William S. Gibson, Amy S. Ziobron, Noah E. Olson, Deborah A. Neher, Charles F. Smith, Victoria I. Holden', 2024, 'Frontiers in Agronomy', '10.3389/fagro.2024.1420311', 'https://doi.org/10.3389/fagro.2024.1420311', 'https://www.frontiersin.org/articles/10.3389/fagro.2024.1420311/full', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'IntroductionThere is a need to rebuild soil health by implementing regenerative agricultural practices across cropping systems dependent on agrochemicals, such as in United States corn production. One increasingly utilized regenerative practice is the application of biostimulants, or microbial inoculants that can rebuild soil health and productivity. In this study, we describe results from a multi-year corn trial conducted to quantify the impact of Re-Gen, a biostimulant invented to recycle plant biomass and increase nutrient bioavailability in the soil.MethodsRe-Gen was applied across four fields (VA01, BH01, VA04, and LA05) at a dairy cattle farm in Ferrisburgh, VT.ResultsOver the two consecutive years (2022-2023) of the trial, Re-Gen application on corn stover and cover crop residues increased ear corn yield by 24% and corn silage yield by 12.5-30%, depending on the field. Analysis of soil nutrients and plant tissues showed increased nutrients, particularly in field LA-05. Multi-year Re-Gen application increased yield and generated additional economic value, indicating that the effects of Re-Gen do not diminish with multiple applications. The increased corn silage yield correlated to increased potential milk yield from cows fed silage grown in Re-Gen-treated fields. Further investigation into the mechanism suggests that increased phosphatase production Re-Gen could contribute to increased phosphorus bioavailability in the soil and uptake in the tissue, potentially increasing yields.DiscussionThese results highlight the potential for Re-Gen to foster regenerative agriculture processes on cropland and livestock farms while also increasing corn and milk yield and, therefore, revenue for corn farmers in the United States and for similar cropping systems worldwide.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0cfa9938-ac68-48d0-b7da-b7720712f779', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Organic manure and fertilizer N management strategies improve soil health at different growth stages of pearl millet under pearl millet-wheat sequence', 'Sheoran S, Prakash D, Raj D, Yadav PK, Singh R, Gupta RK, Alamri S, Siddiqui MH', 2025, 'BMC plant biology', '10.1186/s12870-025-06128-2', 'https://doi.org/10.1186/s12870-025-06128-2', 'https://europepmc.org/articles/PMC11770997?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundIncorporating organic manure improves soil properties and crop productivity. A long-term study started in October 1967 examined the effects of farmyard manure and nitrogen fertilization on the soil at key growth stages of pearl millet in a pearl millet-wheat cropping system over its 51st cycle.ResultsApplying 15 Mg of farmyard manure (FYM) per hectare in both growing seasons significantly boosted soil organic carbon (SOC), dissolved organic carbon (DOC), and key nutrients compared to one-season application. SOC levels reached 9.1-11.0% with FYM15, outperforming FYM10 and FYM5. The effectiveness order was FYM15 > FYM10 > FYM5 > FYM0. Chemical nitrogen fertilization also enhanced soil properties, with FYM15 improving DOC, available nitrogen, and enzyme activities during various growth stages.ConclusionsPrincipal component analysis (PCA) effectively distinguished soil variables and treatments, with β-glucosidase and arylsulfatase activity (ARA) showing the highest loading (0.294) in the first principal component (PC1), followed by dissolved organic carbon (DOC) at 0.292 and dehydrogenase activity (DHA) at 0.291. A strong polynomial relationship was noted between soil organic carbon (SOC) and various soil properties, with R² values between 0.93 and 0.99. The FYM15 x N120 treatment improved soil health in North-West India''s sandy loam soils during both seasons.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2059d1b9-3a9a-43a5-b162-3aa4b1e0f8b1', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Pest categorisation of Fusarium pseudograminearum', 'Bragard C, Baptista P, Chatzivassiliou E, Di Serio F, Gonthier P, Jaques Miret JA, Justesen AF, MacLeod A', 2022, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2022.7399', 'https://doi.org/10.2903/j.efsa.2022.7399', 'https://europepmc.org/articles/PMC9241552?pdf=render', NULL, NULL, 35, NULL, 'other', 1, 'cc by-nd', 'The EFSA Plant Health Panel performed a pest categorisation of Fusarium pseudograminearum O''Donnell & T. Aoki. F. pseudograminearum is a soil-borne fungal pathogen, able to cause a disease known as Fusarium crown rot (FCR, also known as foot and root rot) and occasionally Fusarium head blight on small grain cereals, particularly Triticum aestivum L., Triticum turgidum L. spp. durum (Dest.), Hordeum vulgare L. and triticale (xTriticosecale). In addition, F. pseudograminearum has been isolated from soybean (Glycine max L.) and from some grass genera, such as Phalaris, Agropyron and Bromus, which represent potentially important inoculum reservoirs. This pathogen has been reported in arid and semi-arid cropping regions in Australia, New Zealand, North and South America, northern Africa and South Africa, the Middle East and Asia. In the EU, it has been reported in Italy since 1994 and later in Spain on field-grown durum wheat, but uncertainty remains regarding the actual distribution of the pathogen in the EU. The pathogen is not included in the EU Commission Implementing Regulation 2019/2072. Seeds of host plants and soil and other substrates are the main pathways for the entry and spread of the pathogen into the EU. There are no reports of interceptions of F. pseudograminearum in the EU. Host availability and climate suitability occurring in the EU favour establishment of the pathogen and allow it to establish in areas from which it has not been reported. Phytosanitary measures are available to prevent the introduction of the pathogen into the EU, and additional measures are available to mitigate the risk of spread. In the non-EU areas of its present distribution, the pathogen has a direct impact on cultivated hosts (e.g. wheat, barley, triticale and soybean) that are also relevant for the EU. However, no crop losses have been reported so far in the EU. The Panel concludes that F. pseudograminearum satisfies all the criteria to be regarded as a potential Union quarantine pest.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d8c4f1f7-55b4-4409-9777-02b6d793af65', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Plastic mulch productivity-sustainability tradeoffs and pathways toward an eco-friendly framework: insights from a global meta-analysis', 'Wang L, Guo S, Ge T, Mancl KM, Hijri M, Iseri Y, Lee SJ, Feng S', 2026, 'Nature communications', '10.1038/s41467-026-68798-2', 'https://doi.org/10.1038/s41467-026-68798-2', 'https://europepmc.org/articles/PMC12923545?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'Meeting global food demands by 2050 requires a 45-60% increase in agricultural production. Plasticulture has emerged as a pivotal yet controversial solution. Here we perform a meta-analysis synthesizing the findings of global studies and reveal that plastic mulch enhances crop yields by 28.7% and water use efficiency by 48.9% under diversified systems. In China (2015-2024), plasticulture contributed an additional 189 million tons (Mt) of staple food, conserved 33.5 million hectares of arable land, and reduced emissions by 438 Mt CO₂-equivalent. However, persistent plastic residues degrade soils, and nanoplastics infiltrate food chains, posing ecological and health risks. Despite global negotiations (2024-2025), a binding UN treaty on plastic pollution remains stalled due to disparities among players. To reconcile productivity with sustainability, we propose six evidence-based priorities: (1) scaling integrated eco-farming systems with AI-driven precise application of soil mulches; (2) accelerating material innovation, focusing on biodegradable films and organic-based alternatives; (3) deploying blockchain-enabled circular economies for plastic waste; (4) improving reuse and recycling infrastructure; (5) implementing localized incentive mechanisms to support plastic-free farming; and (6) integrating plastic management into UN carbon trading frameworks. These strategies can pivot plasticulture toward a climate-resilient, ecologically sustainable model-balancing food security with environmental stewardship in an era of climate uncertainty.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('36e06bd1-5408-4d81-8c47-641a1e308046', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Reduced irrigation impact on soil-applied herbicide dissipation and rotational crop response', 'Daniel M. Adamson, Gustavo M. Sbatella, Andrew R. Kniss, Franck Emmanuel Dayan', 2023, 'Weed Technology', '10.1017/wet.2023.85', 'https://doi.org/10.1017/wet.2023.85', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/F6C3C53B8A63A611B78436483D8D11C7/S0890037X23000854a.pdf/div-class-title-reduced-irrigation-impact-on-soil-applied-herbicide-dissipation-and-rotational-crop-response-div.pdf', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc-by', 'Abstract Soil-applied herbicides are important for controlling weeds in many crops but risk damage to susceptible rotational crops if they persist. Field studies were conducted in Powell, WY, from 2015 through 2017 to evaluate the effect of reduced water availability on soil-applied herbicide dissipation. Eight soil-applied herbicides, applied to dry bean or corn, were exposed to three season-long irrigation treatments (100%, 85%, and 70% of estimated crop evapotranspiration [ETc]) by overhead sprinkler. Soil samples were collected to a depth of 10 cm from 0 to 140 d after application, and soil herbicide concentrations were quantified using gas or liquid chromatography and mass spectrometry. Herbicide concentrations were regressed over time to produce a soil half-life estimate for each herbicide and irrigation treatment. Reduced irrigation decreased dry bean yield by up to 77% and corn yield by up to 50%. After adjusting for precipitation, the lowest irrigation treatment received 78% and 76% as much water as the full irrigation treatment in 2015 and 2016, respectively. This significantly increased the soil half-life of imazethapyr but did not increase the soil half-life of atrazine, pyroxasulfone, saflufenacil, ethalfluralin, trifluralin, or pendimethalin. Reduced irrigation did not increase carryover injury to rotational crops from these herbicides 1 yr after application. Instead, carryover response was determined by the inherent persistence of individual herbicides. Imazethapyr (0.1 kg ai ha−1) injured rotational sugar beet, and isoxaflutole (0.1 kg ai ha−1) injured rotational dry bean. Pyroxasulfone (0.2 kg ai ha−1), atrazine (2.0 kg ai ha−1), saflufenacil (0.1 kg ai ha−1) + dimethenamid-P (0.6 kg ai ha−1), ethalfluralin (0.8 kg ai ha−1), trifluralin (0.6 kg ai ha−1), and pendimethalin (1.1 kg ai ha−1) did not injure rotational crops regardless of irrigation treatment. Drought stress sufficient to cause up to 77% crop yield loss did not increase soil-applied herbicide carryover.', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0dd83029-9b6c-41b8-a067-5e9af6d20e6e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Role of the Plant-Microbiome Partnership in Environmentally Harmonious 21st Century Agriculture', 'Sharma SB, Raverkar KP, Wani SP, Bagyaraj DJ, Kannepalli A, Kandula DRW, Mikaelyan A, Ansari MA', 2025, 'Microorganisms', '10.3390/microorganisms13122839', 'https://doi.org/10.3390/microorganisms13122839', 'https://europepmc.org/articles/PMC12735955?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'The 21st century calls for a paradigm shift in agricultural practices to address the pressing issues of regeneration of soil health, climate change, environmental degradation, sustainability under growing population pressures, and food security challenges. This article reviews the potential of the plant-microbiome approach as a key driver for eco-conscious green farming. The focus is on the diverse roles of microbial communities in close association with plants in improving plant health, crop productivity, and soil ecosystem functions, and in enhancing environmental sustainability, with focus on four key areas: (1) Soil health and fertility through microbial partnerships; (2) Ecosystem sustainability through microbial functions; (3) Plant health, productivity and food security through microbial innovations emphasising the potential of microbial applications (biofertilisers, bioprotectants, and biostimulants) in sustainable agriculture; (4) Standardisation and stewardship in microbial agriculture highlighting the need for standardisation and quality control in microbial product development and use, and the concept of microbial stewardship and its importance in long-term agricultural sustainability. By synthesising current knowledge and identifying future challenges, this review underscores the transformative potential of the plant-associated microbiome approach in creating resilient, productive, and environmentally harmonious agricultural systems. We highlight current research gaps and future directions, arguing that embracing microbial solutions is not just an option but a necessity for ensuring food security and environmentally benign sustainability in the face of global challenges.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9d8d6973-5036-47aa-be3f-5aa88f227ec5', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Select Cover Crop Residue and Soil Microbiomes Contribute to Suppression of Fusarium Root and Crown Rot in Barley and Soybean', 'Aiyer HS, McKenzie-Gopsill A, Mills A, Foster AJ', 2024, 'Microorganisms', '10.3390/microorganisms12020404', 'https://doi.org/10.3390/microorganisms12020404', 'https://europepmc.org/articles/PMC10891762?pdf=render', NULL, NULL, 19, NULL, 'canada', 3, 'cc by', 'Fusarium root and crown rot (FRCR) negatively impact several economically important plant species. Cover crops host different soil and residue microbiomes, thereby potentially influencing pathogen load and disease severity. The carryover effect of cover crops on FRCR in barley and soybean was investigated. Field trials were conducted in Prince Edward Island, Canada. Two cover crops from each plant group, including forbs, brassicas, legumes, and grasses, were grown in a randomized complete block design with barley and soybean planted in split plots the following year. Barley and soybean roots were assessed for FRCR through visual disease rating and Fusarium spp. were isolated from diseased tissue. Fungal and bacterial communities in cover crop residues were quantified using amplicon sequencing. The disease-suppressive effects of soil were tested in greenhouse studies. The results indicated that sorghum-sudangrass-associated microbiomes suppress Fusarium spp., leading to reduced FRCR in both barley and soybean. The oilseed radish microbiome had the opposite effect, consequently increasing FRCR incidence in barley and soybean. The results from this study indicate that cover crop residue and the associated soil microbiome influence the incidence and severity of FRCR in subsequent crops. This information can be used to determine cover cropping strategies in barley and soybean production systems.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('89f5a3bf-cea1-4668-a36c-f57322786a81', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Soil amendment and rhizobacterial inoculation improved Cu phytostabilization, plant growth and microbial activity in a bench-scale experiment', 'Romero-Estonllo M, Ramos-Castro J, San Miguel Del Río Y, Rodríguez-Garrido B, Prieto-Fernández Á, Kidd PS, Monterroso C', 2023, 'Frontiers in microbiology', '10.3389/fmicb.2023.1184070', 'https://doi.org/10.3389/fmicb.2023.1184070', 'https://europepmc.org/articles/PMC10346841?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Mine driven trace elements'' pollution entails environmental risks and causes soil infertility. In the last decades, in situ techniques such as phytostabilization have become increasingly important as ways to tackle these negative impacts. The aim of this study was to test the individual and combined effects of different aided phytostabilization techniques using substrate from barren tailings of a Cu mine, characterized by extreme infertility (high acidity and deficiency of organic matter and nutrients). The experiment analyzed the growth of Populus nigra L. planted alone (P) or in co-cropping with Trifolium repens L. (PT), in pots containing mine soil amended with compost (1, 10, compost, soil, w/w) non inoculated (NI) or inoculated with plant growth promoting rhizobacteria (PGP), mycorrhizae (MYC) or a combination of bacterial and fungal inocula (PGPMYC). Non-amended, non-planted and non-inoculated reference ports were also prepared. Plants were harvested after 110 days of plant development and several biometric and phytopathological parameters (stem height, aerial biomass, root biomass, wilting, chlorosis, pest and death) and macro and micronutrient composition were determined. The growth substrate was analyzed for several physicochemical (pH, CECe, and exchangeable cations, total C and N, P Olsen and availability of trace elements) and microbiological (community level physiological profiles: activity, richness and diversity) parameters. The use of the amendment, P. nigra plantation, and inoculation with rhizobacteria were the best techniques to reduce toxicity and improve soil fertility, as well as to increase the plant survival and growth. Soil bacterial functional diversity was markedly influenced by the presence of plants and the inoculation with bacteria, which suggests that the presence of plant regulated the configuration of a microbial community in which the inoculated bacteria thrive comparatively better. The results of this study support the use of organic amendments, tolerant plants, and plant growth promoting rhizobacteria to reduce environmental risk and improve fertility of soils impacted by mining.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd09664b-227e-47a1-bb60-0a66401a4fbb', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Toward Low-Emission Agriculture: Synergistic Contribution of Inorganic Nitrogen and Organic Fertilizers to GHG Emissions and Strategies for Mitigation', 'Haider S, Song J, Bai J, Wang X, Ren G, Bai Y, Huang Y, Shah T', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14101551', 'https://doi.org/10.3390/plants14101551', 'https://europepmc.org/articles/PMC12115026?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'Nitrogen (N) and organic-source fertilizers in agriculture are important to sustain crop production for feeding the growing global population. However, their use can result in significant greenhouse gas (GHG) emissions, particularly carbon dioxide (CO2), methane (CH4), and nitrous oxide (N2O), which are important climate drivers. This review discusses the interactive effects, uncovering both additive and suppressive outcomes of emissions under various soil and climatic conditions. In addition to examining the effects of nitrogen and the nitrogen use efficiency (NUE), it is crucial to comprehend the mechanisms and contributions of organic fertilizers to GHG emissions. This understanding is vital for developing mitigation strategies that effectively reduce emissions while maintaining agricultural productivity. In this review, the current knowledge is utilized for the management of nitrogen practices, such as the optimization of fertilization rates, timing, and methods of application, in terms of the nitrogen use efficiency and the related GHG emissions. Moreover, we discuss the role of organic fertilizers, including straw, manure, and biochar, as a mitigation strategy in relation to GHG emissions through soil carbon sequestration and enhanced nutrient cycling. Important strategies such as crop rotation, tillage, irrigation, organic fertilizers, and legume crops are considered as suitable approaches for minimizing emissions. Even with the progress made in mitigating fertilizer-related emissions, research gaps remain, specifically concerning the long-term effect of organic fertilizers and the interactions between microbial communities in the soil and fertilization practices. Furthermore, the differences in application practices and environmental conditions present considerable obstacles to accurate emission quantification. This review underlines the importance of conducting more thorough research on the combined application of N and organic fertilizers in multiple cropping systems to evolve region-specific mitigation strategies.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c682b474-a617-47e4-ad8c-c117ca8d8c13', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Use of Sugar Beet as a Bioindicator Plant for Detection of Flucarbazone and Sulfentrazone Herbicides in Soil', 'Anna M., J Gilbert Jeff, Nduwarugira Eric', 2012, 'InTech eBooks', '10.5772/33018', 'https://doi.org/10.5772/33018', 'https://www.intechopen.com/citation-pdf-url/25991', NULL, NULL, 16, NULL, 'prairies', 4, 'cc-by', 'Use of Sugar Beet as a Bioindicator Plant for Detection of Flucarbazone and Sulfentrazone Herbicides in Soil', '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b6dde0d5-820e-460a-92ed-36e54c94a715', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'Water stress in Montana cropping systems: effects of cultivar, management, and environment on crop production in dryland systems', 'Michael Linn Bestwick', 2016, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/14317', 'https://scholarworks.montana.edu/xmlui/handle/1/14317', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e3a263ff-fce5-41f7-8fe9-5cbfac37a53e', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'West River Ag Center Crops and Soils Research Annual Progress Report, 2008', 'Agricultural Experiment Station', 2009, 'Open PRAIRIE (South Dakota State University)', NULL, 'https://openprairie.sdstate.edu/agexperimentsta_rsp/201', 'https://openprairie.sdstate.edu/cgi/viewcontent.cgi?article=1200&context=agexperimentsta_rsp', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('982f6a79-153f-4939-8688-0b439112711b', '06e004eb-20d1-407c-ae18-dbe1e75e0573', 'White Leaf Spot Caused by Neopseudocercosporella capsellae: A Re-emerging Disease of Brassicaceae', 'Gunasinghe N, Barbetti MJ, You MP, Burrell D, Neate S', 2020, 'Frontiers in cellular and infection microbiology', '10.3389/fcimb.2020.588090', 'https://doi.org/10.3389/fcimb.2020.588090', 'https://europepmc.org/articles/PMC7655544?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'White leaf spot can cause significant damage to many economically important Brassicaceae crops, including oilseed rape, vegetable, condiment, and fodder Brassica species, and recently has been identified as a re-emerging disease. The causal agent, Neopseudocercosporella capsellae, produces foliar, stem, and pod lesions under favorable weather conditions. N. capsellae secretes cercosporin, a non-host specific, photo-activated toxin, into the host tissue during the early infection process. The pathogen has an active parasitic stage on the living host and a sexual or asexual saprobic stage on the dead host. Where the sexual stage exists, ascospores initiate the new disease cycle, while in the absence of the sexual stage, conidia produced by the asexual stage initiate new disease cycles. Distribution of the pathogen is worldwide; however, epidemiology and disease severity differ between countries or continents, with it being more destructive in Subtropical, Mediterranean, or Temperate climate regions with cool and wet climates. The pathogen has a wide host range within Brassicaceae. Brassica germplasm show varied responses from highly susceptible to completely resistant to pathogen invasion and significant susceptibility differences are observed among major crop species. Cultural practices only provide effective disease control when the climate is not conducive. An increase in the susceptible host population and favorable weather conditions have together favored the recent rise in white leaf spot disease occurrence and spread. The lack of understanding of variation in pathogen virulence and associated resistant gene sources within brassicas critically limits the potential to develop efficient control measures.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('24018785-f633-4db6-a121-9ce6bd9b1346', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Nanotechnology: The new perspective in precision agriculture', 'Duhan JS, Kumar R, Kumar N, Kaur P, Nehra K, Duhan S', 2017, 'Biotechnology reports (Amsterdam, Netherlands)', '10.1016/j.btre.2017.03.002', 'https://doi.org/10.1016/j.btre.2017.03.002', 'https://europepmc.org/articles/PMC5454086?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'Nanotechnology is an interdisciplinary research field. In recent past efforts have been made to improve agricultural yield through exhaustive research in nanotechnology. The green revolution resulted in blind usage of pesticides and chemical fertilizers which caused loss of soil biodiversity and developed resistance against pathogens and pests as well. Nanoparticle-mediated material delivery to plants and advanced biosensors for precision farming are possible only by nanoparticles or nanochips. Nanoencapsulated conventional fertilizers, pesticides and herbicides helps in slow and sustained release of nutrients and agrochemicals resulting in precise dosage to the plants. Nanotechnology based plant viral disease detection kits are also becoming popular and are useful in speedy and early detection of viral diseases. In this article, the potential uses and benefits of nanotechnology in precision agriculture are discussed. The modern nanotechnology based tools and techniques have the potential to address the various problems of conventional agriculture and can revolutionize this sector.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d3ec2e71-646d-4043-aa48-f372837e66c5', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'A Case of One Step Forward and Two Steps Back? An Examination of Herbicide-Resistant Weed Management Using a Simple Agroecosystem Dynamics Model', 'Srinadh Kodali, Chris Flores-Lopez, Isabelle Lobdell, Branson Kim, James C. Russell, Lane Michna, Benjamin L. Turner', 2024, 'Systems', '10.3390/systems12120587', 'https://doi.org/10.3390/systems12120587', 'https://www.mdpi.com/2079-8954/12/12/587', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Global herbicide-resistant weed populations continue rising due to selection pressures exerted by herbicides. Despite this, herbicides continue to be farmers’ preferred weed-control method due to cost and efficiency relative to physical or biological methods. However, weeds developing resistance to herbicides not only challenges crop production but also threatens ecosystem services by disrupting biodiversity, reducing soil health, and impacting water quality. Our objective was to develop a simulation model that captures the feedback between weed population dynamics, agricultural management, profitability, and farmer decision-making processes that interact in unique ways to reinforce herbicide resistance in weeds. After calibration to observed data and evaluation by subject matter experts, we tested alternative agronomic, mechanical, or intensive management strategies to evaluate their impact on weed population dynamics. Results indicated that standalone practices enhanced farm profitability in the short term but lead to substantial adverse ecological outcomes in the long term, indicated by elevated herbicide resistance (e.g., harm to non-target species, disrupting natural ecosystem functions). The most management-intensive test yielded the greatest weed control and farm profit, albeit with elevated residual resistant seed bank levels. We discuss these findings in both developed and developing-nation contexts. Future work requires greater connectivity of farm management and genetic-resistance models that currently remain disconnected mechanistically.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('785bc707-aca1-46f8-b666-1049962312f4', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Adaptive and maladaptive expression plasticity underlying herbicide resistance in an agricultural weed', 'Josephs EB, Van Etten ML, Harkess A, Platts A, Baucom RS', 2021, 'Evolution letters', '10.1002/evl3.241', 'https://doi.org/10.1002/evl3.241', 'https://europepmc.org/articles/PMC8327940?pdf=render', NULL, NULL, 9, NULL, 'northern_plains', 3, 'cc by', 'Plastic phenotypic responses to environmental change are common, yet we lack a clear understanding of the fitness consequences of these plastic responses. Here, we use the evolution of herbicide resistance in the common morning glory (Ipomoea purpurea) as a model for understanding the relative importance of adaptive and maladaptive gene expression responses to herbicide. Specifically, we compare leaf gene expression changes caused by herbicide to the expression changes that evolve in response to artificial selection for herbicide resistance. We identify a number of genes that show plastic and evolved responses to herbicide and find that for the majority of genes with both plastic and evolved responses, plastic responses appear to be adaptive. We also find that selection for herbicide response increases gene expression plasticity. Overall, these results show the importance of adaptive plasticity for herbicide resistance in a common weed and that expression changes in response to strong environmental change can be adaptive.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c17bacaa-8215-4012-927f-838c269ba41a', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'An EU Perspective on Biosafety Considerations for Plants Developed by Genome Editing and Other New Genetic Modification Techniques (nGMs)', 'Michael F. Eckerstorfer, Marion Dolezel, Andreas Heissenberger, Marianne Miklau, Wolfram Reichenbecher, Ricarda A. Steinbrecher, Friedrich Waßmann', 2019, 'Frontiers in Bioengineering and Biotechnology', '10.3389/fbioe.2019.00031', 'https://doi.org/10.3389/fbioe.2019.00031', 'https://www.frontiersin.org/article/10.3389/fbioe.2019.00031/full', NULL, NULL, 21, NULL, 'other', 1, 'open access (DOAJ)', 'The question whether new genetic modification techniques (nGM) in plant development might result in non-negligible negative effects for the environment and/or health is significant for the discussion concerning their regulation. However, current knowledge to address this issue is limited for most nGMs, particularly for recently developed nGMs, like genome editing, and their newly emerging variations, e.g., base editing. This leads to uncertainties regarding the risk/safety-status of plants which are developed with a broad range of different nGMs, especially genome editing, and other nGMs such as cisgenesis, transgrafting, haploid induction or reverse breeding. A literature survey was conducted to identify plants developed by nGMs which are relevant for future agricultural use. Such nGM plants were analyzed for hazards associated either (i) with their developed traits and their use or (ii) with unintended changes resulting from the nGMs or other methods applied during breeding. Several traits are likely to become particularly relevant in the future for nGM plants, namely herbicide resistance (HR), resistance to different plant pathogens as well as modified composition, morphology, fitness (e.g., increased resistance to cold/frost, drought, or salinity) or modified reproductive characteristics. Some traits such as resistance to certain herbicides are already known from existing GM crops and their previous assessments identified issues of concern and/or risks, such as the development of herbicide resistant weeds. Other traits in nGM plants are novel; meaning they are not present in agricultural plants currently cultivated with a history of safe use, and their underlying physiological mechanisms are not yet sufficiently elucidated. Characteristics of some genome editing applications, e.g., the small extent of genomic sequence change and their higher targeting efficiency, i.e., precision, cannot be considered an indication of safety per se, especially in relation to novel traits created by such modifications. All nGMs considered here can result in unintended changes of different types and frequencies. However, the rapid development of nGM plants can compromise the detection and elimination of unintended effects. Thus, a case-specific premarket risk assessment should be conducted for nGM plants, including an appropriate molecular characterization to identify unintended changes and/or confirm the absence of unwanted transgenic sequences.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d6c92aaa-8a20-4e39-b060-d30e0080eac1', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Assessment of genomic prediction and genetic gain in multi‑population half-sib families in the perennial grass crop intermediate wheatgrass', 'Bajgain P, Jungers JM, Anderson JA', 2026, 'PloS one', '10.1371/journal.pone.0357452', 'https://doi.org/10.1371/journal.pone.0357452', 'https://europepmc.org/articles/PMC13537581?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'open access (Europe PMC)', 'The University of Minnesota has been domesticating the perennial forage intermediate wheatgrass (IWG) since 2011 using a combination of conventional methods and modern breeding tools such as genomic selection. Globally, most IWG selection nurseries are spaced-planted individuals of several hundred genotypes whereas commercial fields established for grain production are row-planted panmictic populations. This study evaluated genomic prediction models and estimated genetic gain in yield and agronomic performance of row-planted IWG half-sib families assessed over 3 years and 2 locations, Lamberton and St. Paul, MN, USA. The strongest trait correlation was negative (r = -0.49) between 2023 St. Paul height and 2022 St. Paul seed size. The three St. Paul environments were more similar for plant height and seed size and so were the Lamberton environments yet no specific trend was observed for grain yield. Evaluation of different univariate and multivariate genomic prediction models showed that multivariate models outperformed the best univariate models by 23 percentage points, yet no single multivariate model was the best predictor of all traits. Cross-environment predictions were the best among St. Paul environments and no single environment was the best predictor of the remaining environments. Genetic gain estimates indicated a 20 kg ha-1 increase in grain yield and 3 cm reduction in plant height per breeding cycle. While no single model predicted all traits with high accuracy, results obtained in this study suggest that evaluating IWG sibs in row plots followed by genomic trait predictions could lead to desired breeding progress for desired traits.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('66710ffd-c300-4802-a73f-994c232408a1', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Tolerance of common buckwheat (Fagopyrum esculentum) to low rates of 2,4-D and MCPA', 'David A. Wall, Marjorie A. H. Smith', 2000, 'Canadian Journal of Plant Science', '10.4141/p99-017', 'https://doi.org/10.4141/p99-017', 'https://cdnsciencepub.com/doi/pdf/10.4141/P99-017', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ceba93c-9a23-4a1f-a003-5b71c34fda0a', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Changes in the proteome of the problem weed blackgrass correlating with multiple-herbicide resistance', 'Tétard-Jones C, Sabbadin F, Moss S, Hull R, Neve P, Edwards R', 2018, 'The Plant journal : for cell and molecular biology', '10.1111/tpj.13892', 'https://doi.org/10.1111/tpj.13892', 'https://europepmc.org/articles/PMC5969246?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Herbicide resistance in grass weeds is now one of the greatest threats to sustainable cereal production in Northern Europe. Multiple-herbicide resistance (MHR), a poorly understood multigenic and quantitative trait, is particularly problematic as it provides tolerance to most classes of chemistries currently used for post-emergence weed control. Using a combination of transcriptomics and proteomics, the evolution of MHR in populations of the weed blackgrass (Alopecurus myosuroides) has been investigated. While over 4500 genes showed perturbation in their expression in MHR versus herbicide sensitive (HS) plants, only a small group of proteins showed >2-fold changes in abundance, with a mere eight proteins consistently associated with this class of resistance. Of the eight, orthologues of three of these proteins are also known to be associated with multiple drug resistance (MDR) in humans, suggesting a cross-phyla conservation in evolved tolerance to chemical agents. Proteomics revealed that MHR could be classified into three sub-types based on the association with resistance to herbicides with differing modes of action (MoA), being either global, specific to diverse chemistries acting on one MoA, or herbicide specific. Furthermore, the proteome of MHR plants were distinct from that of HS plants exposed to a range of biotic (insect feeding, plant-microbe interaction) and abiotic (N-limitation, osmotic, heat, herbicide safening) challenges commonly encountered in the field. It was concluded that MHR in blackgrass is a uniquely evolving trait(s), associated with changes in the proteome that are distinct from responses to conventional plant stresses, but sharing common features with MDR in humans.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('91e37fa3-0462-409d-93d1-178907b9159a', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Coexpression Clusters and Allele-Specific Expression in Metabolism-Based Herbicide Resistance', 'Giacomini DA, Patterson EL, Küpper A, Beffa R, Gaines TA, Tranel PJ', 2020, 'Genome biology and evolution', '10.1093/gbe/evaa191', 'https://doi.org/10.1093/gbe/evaa191', 'https://europepmc.org/articles/PMC7738748?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'In the last decade, Amaranthus tuberculatus has evolved resistance to 2,4-dichlorophenoxyacetic acid (2,4-D) and 4-hydroxyphenylpyruvate dioxygenase inhibitors in multiple states across the midwestern United States. Two populations resistant to both mode-of-action groups, one from Nebraska (NEB) and one from Illinois (CHR), were studied using an RNA-seq approach on F2 mapping populations to identify the genes responsible for resistance. Using both an A. tuberculatus transcriptome assembly and a high-quality grain amaranth (A. hypochondriacus) genome as references, differential transcript and gene expression analyses were conducted to identify genes that were significantly over- or underexpressed in resistant plants. When these differentially expressed genes (DEGs) were mapped on the A. hypochondriacus genome, physical clustering of the DEGs was apparent along several of the 16 A. hypochondriacus scaffolds. Furthermore, single-nucleotide polymorphism calling to look for resistant-specific (R) variants, and subsequent mapping of these variants, also found similar patterns of clustering. Specifically, regions biased toward R alleles overlapped with the DEG clusters. Within one of these clusters, allele-specific expression of cytochrome P450 81E8 was observed for 2,4-D resistance in both the CHR and NEB populations, and phylogenetic analysis indicated a common evolutionary origin of this R allele in the two populations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d0447be9-22f8-4e41-bd73-323db9c10156', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Defining Integrated Weed Management: A Novel Conceptual Framework for Models', 'Jonathan Storkey, Joseph Helps, Richard Hull, Alice E. Milne, Helen Metcalfe', 2021, 'Agronomy', '10.3390/agronomy11040747', 'https://doi.org/10.3390/agronomy11040747', 'https://www.mdpi.com/2073-4395/11/4/747', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Weed population dynamics models are an important tool for predicting the outcome of alternative Integrated Weed Management (IWM) scenarios. The growing problem of herbicide resistance has increased the urgency for these tools in the design of sustainable IWM solutions. We developed a conceptual framework for defining IWM as a standardised input template to allow output from different models to be compared and to design IWM scenarios. The framework could also be used as a quantitative metric to determine whether more diverse systems are more sustainable and less vulnerable to herbicide resistance using empirical data. Using the logic of object-oriented programming, we defined four classes of weed management options based on the stage in the weed life cycle that they impact and processes that mediate their effects. Objects in the same class share a common set of properties that determine their behaviour in weed population dynamics models. Any weed control “event” in a system is associated with an object, meaning alternative management scenarios can be built by systematically adding events to a model either to compare existing systems or design novel approaches. Our framework is designed to be generic, allowing IWM systems from different cropping systems and countries to be compared.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('441e0aae-9f9d-41e5-983e-c3788d4869ba', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Effects of bacillin 20 on microbial community structure and cross-domain networks in the soybean root-rhizosphere interface', 'Ahmed B, Nazari M, Elfermi R, Kabir AH, Hijri M, Smith DL', 2026, 'BMC microbiology', '10.1186/s12866-026-05135-z', 'https://doi.org/10.1186/s12866-026-05135-z', 'https://europepmc.org/articles/PMC13366860?pdf=render', NULL, NULL, 17, NULL, 'canada', 3, 'cc by-nc-nd', 'BackgroundUnderstanding how biostimulants modulate plant-associated microbiomes is critical for advancing sustainable agriculture. Here, we investigated the effects of Bacillus-derived bacillin 20 on the root and rhizosphere microbiomes of soybean (Glycine max) using amplicon-based profiling, community ecology, and network analysis.ResultsMicrobial community assembly was driven primarily by plant compartmentalization, with higher bacterial richness in the rhizosphere and stronger host filtering in root-associated microbiomes. PERMANOVA analysis indicated that compartment explained most of the variation in community structure, whereas bacillin 20 treatment had no statistically significant effect. Despite no meaningful shifts in alpha diversity, bacillin 20 was associated with subtle, non-significant compositional trends in specific taxa across treatments. Indicator species and core microbiome analyses revealed compartment-specific taxa with potential roles in nutrient cycling, stress tolerance, and plant growth promotion.ConclusionBacillin 20 was associated with changes in cross-domain microbial co-occurrence patterns, including differences in network connectivity, particularly in the rhizosphere, where several fungal ASVs (e.g., ASV33, ASV5, ASV8, and ASV88) exhibited high centrality. These findings indicate that bacillin 20 is associated with changes in microbial interaction patterns while maintaining overall community diversity. Overall, treatment effects were minor relative to compartment-driven structuring of the microbiome. Together, our results suggest that microbiome-informed approaches, including the use of targeted biostimulants, may contribute to the management of plant-microbe interactions in agricultural systems. Future studies integrating multi-omics approaches will be required to elucidate the underlying mechanisms of these interactions.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('50691763-2b61-4d8d-9fcd-2b449f35da77', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Engineering herbicide resistance via prime editing in rice', 'Butt H, Rao GS, Sedeek K, Aman R, Kamel R, Mahfouz M', 2020, 'Plant biotechnology journal', '10.1111/pbi.13399', 'https://doi.org/10.1111/pbi.13399', 'https://europepmc.org/articles/PMC7680537?pdf=render', NULL, NULL, 3, NULL, 'other', 1, 'cc by', NULL, '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8a73e972-fec0-43d5-816f-5d63b6120eb3', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Evaluation of the Impact of Genetically Modified Cotton After 20 Years of Cultivation in Mexico', 'Martha G. Rocha-Munive, Mario Soberón, Saúl Castañeda, Esteban Niaves, Enrique Scheinvar, Luis E. Eguiarte, David Mota-Sánchez, Enrique Rosales-Robles', 2018, 'Frontiers in Bioengineering and Biotechnology', '10.3389/fbioe.2018.00082', 'https://doi.org/10.3389/fbioe.2018.00082', 'https://www.frontiersin.org/article/10.3389/fbioe.2018.00082/full', NULL, NULL, 12, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'For more than 20 years cotton has been the most widely sown genetically modified (GM) crop in Mexico. Its cultivation has fulfilled all requirements and has gone through the different regulatory stages. During the last 20 years, both research-institutions and biotech-companies have generated scientific and technical information regarding GM cotton cultivation in Mexico. In this work, we collected data in order to analyze the environmental and agronomic effects of the use of GM cotton in Mexico. In 1996, the introduction of Bt cotton made it possible to reactivate this crop, which in previous years was greatly reduced due to pest problems, production costs and environmental concerns. Bt cotton is a widely accepted tool for cotton producers and has proven to be efficient for the control of lepidopteran pests. The economic benefits of its use are variable, and depend on factors such as the international cotton-prices and other costs associated with its inputs. So far, the management strategies used to prevent development of insect resistance to GM cotton has been successful, and there are no reports of insect resistance development to Bt cotton in Mexico. In addition, no effects have been observed on non-target organisms. For herbicide tolerant cotton, the prevention of herbicide resistance has also been successful since unlike other countries, the onset of resistance weeds is still slow, apparently due to cultural practices and rotation of different herbicides. Environmental benefits have been achieved with a reduction in chemical insecticide applications and the subsequent decrease in primary pest populations, so that the inclusion of other technologies—e.g., use of non-Bt cotton- can be explored. Nevertheless, control measures need to be implemented during transport of the bolls and fiber to prevent dispersal of volunteer plants and subsequent gene flow to wild relatives distributed outside the GM cotton growing areas. It is still necessary to implement national research programs, so that biotechnology and plant breeding advances can be used in the development of cotton varieties adapted to the Mexican particular environmental conditions and to control insect pests of regional importance.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df52aa49-3c72-4cc9-ad70-ae1fe34535eb', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Evolution of the Canadian regulatory system for plant biotechnology', 'Luque L, Hubert J', 2026, 'Frontiers in bioengineering and biotechnology', '10.3389/fbioe.2026.1912331', 'https://doi.org/10.3389/fbioe.2026.1912331', 'https://europepmc.org/articles/PMC13631052?pdf=render', NULL, NULL, 20, NULL, 'canada', 3, 'cc by', 'Canada was one of the first countries to adopt agricultural biotechnology products. This has served Canada well as it is constantly ranked among the world''s top agriculture commodities exporters with its products reaching markets in all continents. However, the speed at which regulations enabling the commercialization and adoption of the latest agricultural biotechnologies did not match the pace with advancements in the field. As the years went by, a lack of clarity about regulatory interpretation created an unlevel playing field for Canadian plant breeders and companies. This started to change in 2022 when new policy changes were announced by the Canadian government, paving the way for the adoption of the latest technologies. The aim of this document is to bring together the key pieces of legislation and policy elements governing plant breeding innovations in Canada into a single consolidated reference. The paper reflects perspectives and interpretations by Canadian industry regulatory experts on the 38-year history and evolution of the regulatory landscape in Canada to support clarity and consistent application for future developers and innovators in this sector.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2054a531-bd89-44c2-8f1c-c7387459bd39', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'First Case of Glufosinate-Resistant Rigid Ryegrass (Lolium rigidum Gaud.) in Greece', 'Ilias S. Travlos, Nikolina Cheimona, Rafael De Prado, Amit J. Jhala, Demosthenis Chachalis, Eleni Tani', 2018, 'Agronomy', '10.3390/agronomy8040035', 'https://doi.org/10.3390/agronomy8040035', 'http://www.mdpi.com/2073-4395/8/4/35', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Repeated applications of the same herbicide(s), which are characterized by the same mode of action, increase selection pressure, which in turn favours the evolution of herbicide-resistant weeds. Glufosinate is a broad-spectrum non-selective herbicide being used for weed control for many years around the world. Rigid ryegrass (Lolium rigidum Gaud.) is an economically important grass weed in Greece. Recent complaints by growers about control failure of rigid ryegrass with glufosinate require further investigation and have been the basis of this study. The objectives of this study were to confirm the existence of glufosinate-resistant L. rigidum in Greece and evaluate the effect of L. rigidum growth stage on glufosinate efficacy. Twenty populations of rigid ryegrass from Greece were sampled from five regions, and whole plant dose–response studies were conducted for five populations under controlled conditions with eight rates of glufosinate (0.0, 0.098, 0.187, 0.375, 0.75, 1.5, 3.0, and 6.0 kg a.i. ha−1). Glufosinate resistance was confirmed in three out of five populations with the level of resistance ranging from three-to seven-fold compared with the susceptible populations based on above-ground biomass reduction. Results also revealed that the level of glufosinate-resistance of rigid ryegrass was dependent on the growth stage at which it was applied.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6533a580-b804-4f09-9131-97267612668f', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Genes encoding cytochrome P450 monooxygenases and glutathione S-transferases associated with herbicide resistance evolved before the origin of land plants', 'Casey A, Dolan L', 2023, 'PloS one', '10.1371/journal.pone.0273594', 'https://doi.org/10.1371/journal.pone.0273594', 'https://europepmc.org/articles/PMC9937507?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'Cytochrome P450 (CYP) monooxygenases and glutathione S-transferases (GST) are enzymes that catalyse chemical modifications of a range of organic compounds. Herbicide resistance has been associated with higher levels of CYP and GST gene expression in some herbicide-resistant weed populations compared to sensitive populations of the same species. By comparing the protein sequences of 9 representative species of the Archaeplastida-the lineage which includes red algae, glaucophyte algae, chlorophyte algae, and streptophytes-and generating phylogenetic trees, we identified the CYP and GST proteins that existed in the common ancestor of the Archaeplastida. All CYP clans and all but one land plant GST classes present in land plants evolved before the divergence of streptophyte algae and land plants from their last common ancestor. We also demonstrate that there are more genes encoding CYP and GST proteins in land plants than in algae. The larger numbers of genes among land plants largely results from gene duplications in CYP clans 71, 72, and 85 and in the GST phi and tau classes [1,2]. Enzymes that either metabolise herbicides or confer herbicide resistance belong to CYP clans 71 and 72 and the GST phi and tau classes. Most CYP proteins that have been shown to confer herbicide resistance are members of the CYP81 family from clan 71. These results demonstrate that the clan and class diversity in extant plant CYP and GST proteins had evolved before the divergence of land plants and streptophyte algae from a last common ancestor estimated to be between 515 and 474 million years ago. Then, early in embryophyte evolution during the Palaeozoic, gene duplication in four of the twelve CYP clans, and in two of the fourteen GST classes, led to the large numbers of CYP and GST proteins found in extant land plants. It is among the genes of CYP clans 71 and 72 and GST classes phi and tau that alleles conferring herbicide resistance evolved in the last fifty years.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('570fcff3-9c95-41e5-bb47-cf93e74f338f', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Herbicide Resistance Traits in Maize and Soybean: Current Status and Future Outlook', 'Nandula VK', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8090337', 'https://doi.org/10.3390/plants8090337', 'https://europepmc.org/articles/PMC6784167?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'This article reviews, focusing on maize and soybean, previous efforts to develop nontransgenic herbicide-resistant crops (HRCs), currently available transgenic HRC traits and technologies, as well as future chemical weed management options over the horizon. Since the mid twentieth century, herbicides rapidly replaced all other means of weed management. Overreliance on ''herbicide-only'' weed control strategies hastened evolution of HR weed species. Glyphosate-resistant (GR) crop technology revolutionized weed management in agronomic crops, but GR weeds, led by Palmer amaranth, severely reduced returns from various cropping systems and affected the bottom line of growers across the world. An additional problem was the lack of commercialization of a new herbicide mode of action since the 1990s. Auxinic HRCs offer a short-term alternative for management of GR Palmer amaranth and other weed species. New HRCs stacked with multiple herbicide resistance traits and at least two new herbicide modes of action expected to be available in the mid-2020s provide new chemical options for weed management in row crops in the next decade.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('387cbcc0-2036-40de-a801-3d7b60aa20b3', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Imidazolinone resistance, yield potential and agronomic performance of the irrigated rice cultivar BRS A706 CL', 'Paulo  Hideo Nakano Rangel, José Manoel Colombari-Filho, Marcio Elias Ferreira, Ariano Martins de Magalhães Junior, Guilherme Barbosa Abreu, José Almeida Pereira, Antônio Carlos Centeno Cordeiro, Daniel Brito Fragoso', 2022, 'Crop Breeding and Applied Biotechnology', NULL, 'https://periodicos.ufv.br/CBAB/article/view/16926', 'https://periodicos.ufv.br/CBAB/article/view/16926', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'Cultivar BRS A706 CL is a new rice cultivar, resistant to herbicides of the chemical group of imidazolinones, with a yield potential of 15,635 kg ha-1. It has intermediate maturation, lodging tolerance, the stay green trait, moderate rice blast resistance, a high milling yield and premium grain quality.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('242012b4-7ee7-40ec-a463-4bb2cf7eaead', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Invasive plants in Alberta. Herbicide resistance', 'Government of Alberta', 2014, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/6740642', 'https://open.alberta.ca/dataset/de0eabd8-d3ac-4677-b835-221b2d7b0561/resource/6fd7ce43-8d9b-4de7-9033-e656b4646473/download/6740642-2014-invasive-plants-alberta-herbicide-resistance-640-13-2014-02.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Land owners and occupiers are responsible for controlling noxious weeds and destroying prohibited noxious weeds under the Alberta Weed Control Act. Listed plants in the Act cause problems for the environment, health or economy. Know your responsibilities under the Act. Regardless of where plants are located, prevention is always the most effective approach in dealing with invasive plants.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('34711687-5384-472c-8bab-5225ad3987fd', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Low level resistance of wild poinsettia biotypes to glyphosate and alternative chemical control', 'Dirceu Agostinetto, André da Rosa Ulguim, Renan Ricardo Zandoná, Jéssica Dias Gomes da Silva, Bruno Moncks da Silva, Leandro Várgas', 2019, 'Bioscience Journal', '10.14393/BJ-v35n4a2019-42118', 'https://doi.org/10.14393/BJ-v35n4a2019-42118', 'http://www.seer.ufu.br/index.php/biosciencejournal/article/view/42118', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'In the State of Rio Grande do Sul (RS), Southern Brazil, glyphosate has not been capable of controlling wild poinsettia (Euphorbia heterophylla L.) in soybean fields, thus, suggesting resistance to this herbicide. Therefore, this study aimed at evaluating sensitivity of wild poinsettia biotypes to glyphosate, identifying the occurrence of resistance of wild poinsettia to the herbicide in RS state and determining the resistance factor of wild poinsettia biotypes under suspicion, besides assessing other herbicides as alternative controls. Two greenhouse experiments, which lasted two years, were conducted by a completely randomized design with four replications. Six biotypes (Factor A) and eight doses of glyphosate (Factor B) were used for getting the dose-response curve. Regarding the alternative control, post-emergence herbicides for soybean and corn crops were tested. Control and dry mass of the shoot were analyzed as variables. Resistance factors of resistant biotypes 20.2 and 21.1 were 4.83 and 5.29, respectively, by comparison with the susceptible biotype (11.4). In RS state, there has currently been high selection pressure due to the intensive use of glyphosate against wild poinsettia plants, as the result of the occurrence of biotypes 20.2 and 21.1 which have low levels of resistance to glyphosate and very little control by ALS-inhibiting herbicides. Therefore, an alternative to mitigate the problem is the use of herbicides with different mechanisms of action.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4095b169-1c52-4bee-b4d0-6e753a8470a1', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Molecular Mechanisms of Herbicide Resistance in Weeds', 'Torra J, Alcántara-de la Cruz R', 2022, 'Genes', '10.3390/genes13112025', 'https://doi.org/10.3390/genes13112025', 'https://europepmc.org/articles/PMC9690762?pdf=render', NULL, NULL, 5, NULL, 'other', 1, 'cc by', 'Herbicides have become one of the most widespread weed-control tools in the world since their advent in the mid-20th century [...].', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f7baab7d-f522-4c85-b058-01f58a51a8ab', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Non-target Site Herbicide Resistance Is Conferred by Two Distinct Mechanisms in Black-Grass (Alopecurus myosuroides)', 'Franco-Ortega S, Goldberg-Cavalleri A, Walker A, Brazier-Hicks M, Onkokesung N, Edwards R', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.636652', 'https://doi.org/10.3389/fpls.2021.636652', 'https://europepmc.org/articles/PMC7966817?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Non-target site resistance (NTSR) to herbicides in black-grass (Alopecurus myosuroides) results in enhanced tolerance to multiple chemistries and is widespread in Northern Europe. To help define the underpinning mechanisms of resistance, global transcriptome and biochemical analysis have been used to phenotype three NTSR black-grass populations. These comprised NTSR1 black-grass from the classic Peldon field population, which shows broad-ranging resistance to post-emergence herbicides; NTSR2 derived from herbicide-sensitive (HS) plants repeatedly selected for tolerance to pendimethalin; and NTSR3 selected from HS plants for resistance to fenoxaprop-P-ethyl. NTSR in weeds is commonly associated with enhanced herbicide metabolism catalyzed by glutathione transferases (GSTs) and cytochromes P450 (CYPs). As such, the NTSR populations were assessed for their ability to detoxify chlorotoluron, which is detoxified by CYPs and fenoxaprop-P-ethyl, which is acted on by GSTs. As compared with HS plants, enhanced metabolism toward both herbicides was determined in the NTSR1 and NTSR2 populations. In contrast, the NTSR3 plants showed no increased detoxification capacity, demonstrating that resistance in this population was not due to enhanced metabolism. All resistant populations showed increased levels of AmGSTF1, a protein functionally linked to NTSR and enhanced herbicide metabolism. Enhanced AmGSTF1 was associated with increased levels of the associated transcripts in the NTSR1 and NTSR2 plants, but not in NTSR3, suggestive of both pre- and post-transcriptional regulation. The related HS, NTSR2, and NTSR3 plants were subject to global transcriptome sequencing and weighted gene co-expression network analysis to identify modules of genes with coupled regulatory functions. In the NTSR2 plants, modules linked to detoxification were identified, with many similarities to the transcriptome of NTSR1 black-grass. Critical detoxification genes included members of the CYP81A family and tau and phi class GSTs. The NTSR2 transcriptome also showed network similarities to other (a)biotic stresses of plants and multidrug resistance in humans. In contrast, completely different gene networks were activated in the NTSR3 plants, showing similarity to the responses to cold, osmotic shock and fungal infection determined in cereals. Our results demonstrate that NTSR in black-grass can arise from at least two distinct mechanisms, each involving complex changes in gene regulatory networks.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3e0e6211-a6f9-49cf-9569-3473f44f4fab', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'North American wetlands and mosquito control', 'Rey JR, Walton WE, Wolfe RJ, Connelly CR, O''Connell SM, Berg J, Sakolsky-Hoopes GE, Laderman AD', 2012, 'International journal of environmental research and public health', '10.3390/ijerph9124537', 'https://doi.org/10.3390/ijerph9124537', 'https://europepmc.org/articles/PMC3546777?pdf=render', NULL, NULL, 69, NULL, 'other', 1, 'cc by', 'Wetlands are valuable habitats that provide important social, economic, and ecological services such as flood control, water quality improvement, carbon sequestration, pollutant removal, and primary/secondary production export to terrestrial and aquatic food chains. There is disagreement about the need for mosquito control in wetlands and about the techniques utilized for mosquito abatement and their impacts upon wetlands ecosystems. Mosquito control in wetlands is a complex issue influenced by numerous factors, including many hard to quantify elements such as human perceptions, cultural predispositions, and political climate. In spite of considerable progress during the last decades, habitat protection and environmentally sound habitat management still remain inextricably tied to politics and economics. Furthermore, the connections are often complex, and occur at several levels, ranging from local businesses and politicians, to national governments and multinational institutions. Education is the key to lasting wetlands conservation. Integrated mosquito abatement strategies incorporate many approaches and practicable options, as described herein, and need to be well-defined, effective, and ecologically and economically sound for the wetland type and for the mosquito species of concern. The approach will certainly differ in response to disease outbreaks caused by mosquito-vectored pathogens versus quality of life issues caused by nuisance-biting mosquitoes. In this contribution, we provide an overview of the ecological setting and context for mosquito control in wetlands, present pertinent information on wetlands mosquitoes, review the mosquito abatement options available for current wetlands managers and mosquito control professionals, and outline some necessary considerations when devising mosquito control strategies. Although the emphasis is on North American wetlands, most of the material is applicable to wetlands everywhere.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7a48303d-f1b7-4d52-a2c3-519a03bcfe4d', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Parallel and nonparallel genomic responses contribute to herbicide resistance in Ipomoea purpurea, a common agricultural weed', 'Van Etten M, Lee KM, Chang SM, Baucom RS', 2020, 'PLoS genetics', '10.1371/journal.pgen.1008593', 'https://doi.org/10.1371/journal.pgen.1008593', 'https://europepmc.org/articles/PMC7018220?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'The repeated evolution of herbicide resistance has been cited as an example of genetic parallelism, wherein separate species or genetic lineages utilize the same genetic solution in response to selection. However, most studies that investigate the genetic basis of herbicide resistance examine the potential for changes in the protein targeted by the herbicide rather than considering genome-wide changes. We used a population genomics screen and targeted exome re-sequencing to uncover the potential genetic basis of glyphosate resistance in the common morning glory, Ipomoea purpurea, and to determine if genetic parallelism underlies the repeated evolution of resistance across replicate resistant populations. We found no evidence for changes in 5-enolpyruvylshikimate-3-phosphate synthase (EPSPS), glyphosate''s target protein, that were associated with resistance, and instead identified five genomic regions that showed evidence of selection. Within these regions, genes involved in herbicide detoxification-cytochrome P450s, ABC transporters, and glycosyltransferases-are enriched and exhibit signs of selective sweeps. One region under selection shows parallel changes across all assayed resistant populations whereas other regions exhibit signs of divergence. Thus, while it appears that the physiological mechanism of resistance in this species is likely the same among resistant populations, we find patterns of both similar and divergent selection across separate resistant populations at particular loci.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e401e22-c384-447d-9674-df23c06264f1', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Real‐time monitoring of root dielectric properties for assessing crop plant damage caused by foliar application of glyphosate', 'Imre Cseresnyés, Anna Füzy, Tünde Takács', 2026, 'Applications in Plant Sciences', '10.1002/aps3.70057', 'https://doi.org/10.1002/aps3.70057', 'https://doi.org/10.1002/aps3.70057', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Premise There is a knowledge gap regarding how foliar injury and restricted water uptake can be detected by measuring root dielectric response. This pot study nondestructively evaluated the efficiency of real‐time dielectric measurement to monitor the effects of glyphosate spraying. Methods Root dielectric properties were recorded on a minute scale in control and glyphosate‐treated maize, cucumber, and pea. Chlorophyll, stomatal conductance, and biomass measurements were taken to interpret the dielectric changes. Results Electrical capacitance and conductance varied diurnally due to the circadian regulation of water uptake and hydraulic conductance. Glyphosate application reduced capacitance, indicating the impeded root growth and activity caused by impaired amino acid synthesis, foliar damage, and restricted transpiration. The dissipation factor decreased in response to glyphosate due to impeded apoplastic water flow, suppressed root lignification, and hampered water absorption. The enhanced leaf and root hydraulic resistance caused by glyphosate was manifested in sharply reduced electrical conductance. Changes in the species’ dielectric response were consistent with physiological symptoms and biomass loss. Discussion Real‐time dielectric measurement proved suitable for the nondestructive monitoring of plant responses to foliar stress through altered root traits. This method could be employed to evaluate herbicide tolerance in crops and to develop and determine dosage of herbicide ingredients.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c6aa085-3463-4c53-8d60-764bace6600b', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Repeated origins, widespread gene flow, and allelic interactions of target-site herbicide resistance mutations', 'Kreiner JM, Sandler G, Stern AJ, Tranel PJ, Weigel D, Stinchcombe JR, Wright SI', 2022, 'eLife', '10.7554/elife.70242', 'https://doi.org/10.7554/elife.70242', 'https://europepmc.org/articles/PMC8798060?pdf=render', NULL, NULL, 25, NULL, 'canada', 3, 'cc by', 'Causal mutations and their frequency in agricultural fields are well-characterized for herbicide resistance. However, we still lack understanding of their evolutionary history: the extent of parallelism in the origins of target-site resistance (TSR), how long these mutations persist, how quickly they spread, and allelic interactions that mediate their selective advantage. We addressed these questions with genomic data from 19 agricultural populations of common waterhemp (Amaranthus tuberculatus), which we show to have undergone a massive expansion over the past century, with a contemporary effective population size estimate of 8 x 107. We found variation at seven characterized TSR loci, two of which had multiple amino acid substitutions, and three of which were common. These three common resistance variants show extreme parallelism in their mutational origins, with gene flow having shaped their distribution across the landscape. Allele age estimates supported a strong role of adaptation from de novo mutations, with a median age of 30 suggesting that most resistance alleles arose soon after the onset of herbicide use. However, resistant lineages varied in both their age and evidence for selection over two different timescales, implying considerable heterogeneity in the forces that govern their persistence. Two such forces are intra- and inter-locus allelic interactions; we report a signal of extended haplotype competition between two common TSR alleles, and extreme linkage with genome-wide alleles with known functions in resistance adaptation. Together, this work reveals a remarkable example of spatial parallel evolution in a metapopulation, with important implications for the management of herbicide resistance.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dbac6ae4-99cf-412a-aedd-e9bdb97da32f', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Agronomic and fertilizer management of barley in Alberta', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4252075', 'https://open.alberta.ca/dataset/b79aaeb1-81a5-42d7-b39a-d21998e074c2/resource/144d845a-9e2d-4acf-9567-47c010eb575b/download/2008-114-540-2.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Barley production in Canada is focused primarily in the prairie provinces of Alberta, Saskatchewan and Manitoba (Table 1). Approximately 94 per cent of barley of production in Canada is in the prairie provinces, with Alberta generally producing the most. Barley is the third most commonly grown crop on the prairies, after wheat and canola.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('30fc4cf3-8607-45cb-a71f-f52e034fcd78', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Standing genetic variation fuels rapid evolution of herbicide resistance in blackgrass', 'Kersten S, Chang J, Huber CD, Voichek Y, Lanz C, Hagmaier T, Lang P, Lutz U', 2023, 'Proceedings of the National Academy of Sciences of the United States of America', '10.1073/pnas.2206808120', 'https://doi.org/10.1073/pnas.2206808120', 'https://europepmc.org/articles/PMC10120058?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Repeated herbicide applications in agricultural fields exert strong selection on weeds such as blackgrass (Alopecurus myosuroides), which is a major threat for temperate climate cereal crops. This inadvertent selection pressure provides an opportunity for investigating the underlying genetic mechanisms and evolutionary processes of rapid adaptation, which can occur both through mutations in the direct targets of herbicides and through changes in other, often metabolic, pathways, known as non-target-site resistance. How much target-site resistance (TSR) relies on de novo mutations vs. standing variation is important for developing strategies to manage herbicide resistance. We first generated a chromosome-level reference genome for A. myosuroides for population genomic studies of herbicide resistance and genome-wide diversity across Europe in this species. Next, through empirical data in the form of highly accurate long-read amplicons of alleles encoding acetyl-CoA carboxylase (ACCase) and acetolactate synthase (ALS) variants, we showed that most populations with resistance due to TSR mutations-23 out of 27 and six out of nine populations for ACCase and ALS, respectively-contained at least two TSR haplotypes, indicating that soft sweeps are the norm. Finally, through forward-in-time simulations, we inferred that TSR is likely to mainly result from standing genetic variation, with only a minor role for de novo mutations.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('142e3fb6-657d-46f7-a8d5-c126b8311213', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Synthetic evolution of herbicide resistance using a T7 RNAP-based random DNA base editor', 'Butt H, Ramirez JLM, Mahfouz M', 2022, 'Life science alliance', '10.26508/lsa.202201538', 'https://doi.org/10.26508/lsa.202201538', 'https://europepmc.org/articles/PMC9526444?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Synthetic directed evolution via localized sequence diversification and the simultaneous application of selection pressure is a promising method for producing new, beneficial alleles that affect traits of interest in diverse species; however, this technique has rarely been applied in plants. Here, we designed, built, and tested a chimeric fusion of T7 RNA Polymerase (RNAP) and deaminase to enable the localized sequence diversification of a target sequence of interest. We tested our T7 RNAP-DNA base editor in Nicotiana benthamiana transient assays to target a transgene expressing GFP under the control of the T7 promoter and observed C-to-T conversions. We then targeted the T7 promoter-driven acetolactate synthase sequence that had been stably integrated in the rice genome and generated C-to-T and G-to-A transitions. We used herbicide treatment as selection pressure for the evolution of the acetolactate synthase sequence, resulting in the enrichment of herbicide-responsive residues. We then validated these herbicide-responsive regions in the transgenic rice plants. Thus, our system could be used for the continuous synthetic evolution of gene functions to produce variants with improved herbicide resistance.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('98a89168-2e71-40f7-abdb-fe0db57eb1fa', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'The ancestral karyotype of the Heliantheae Alliance, herbicide resistance, and human allergens: Insights from the genomes of common and giant ragweed', 'Laforest M, Martin SL, Bisaillon K, Soufiane B, Meloche S, Tardif FJ, Page E', 2024, 'The plant genome', '10.1002/tpg2.20442', 'https://doi.org/10.1002/tpg2.20442', 'https://europepmc.org/articles/PMC12807018?pdf=render', NULL, NULL, 28, NULL, 'canada', 3, 'cc by-nc-nd', 'Ambrosia artemisiifolia and Ambrosia trifida (Asteraceae) are important pest species and the two greatest sources of aeroallergens globally. Here, we took advantage of a hybrid to simplify genome assembly and present chromosome-level assemblies for both species. These assemblies show high levels of completeness with Benchmarking Universal Single-Copy Ortholog (BUSCO) scores of 94.5% for A. artemisiifolia and 96.1% for A. trifida and long terminal repeat (LTR) Assembly Index values of 26.6 and 23.6, respectively. The genomes were annotated using RNA data identifying 41,642 genes in A. artemisiifolia and 50,203 in A. trifida. More than half of the genome is composed of repetitive elements, with 62% in A. artemisiifolia and 69% in A. trifida. Single copies of herbicide resistance-associated genes PPX2L, HPPD, and ALS were found, while two copies of the EPSPS gene were identified; this latter observation may reveal a possible mechanism of resistance to the herbicide glyphosate. Ten of the 12 main allergenicity genes were also localized, some forming clusters with several copies, especially in A. artemisiifolia. The evolution of genome structure has differed among these two species. The genome of A. trifida has undergone greater rearrangement, possibly the result of chromoplexy. In contrast, the genome of A. artemisiifolia retains a structure that makes the allotetraploidization of the most recent common ancestor of the Heliantheae Alliance the clearest feature of its genome. When compared to other Heliantheae Alliance species, this allowed us to reconstruct the common ancestor''s karyotype-a key step for furthering of our understanding of the evolution and diversification of this economically and allergenically important group.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('de678be9-d1e2-4fef-b9c8-54d7af928dfa', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'The blackgrass genome reveals patterns of non-parallel evolution of polygenic herbicide resistance', 'Cai L, Comont D, MacGregor D, Lowe C, Beffa R, Neve P, Saski C', 2023, 'The New phytologist', '10.1111/nph.18655', 'https://doi.org/10.1111/nph.18655', 'https://europepmc.org/articles/PMC10108218?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Globally, weedy plants are a major constraint to sustainable crop production. Much of the success of weeds rests with their ability to rapidly adapt in the face of human-mediated management of agroecosystems. Alopecurus myosuroides (blackgrass) is a widespread and impactful weed affecting agriculture in Europe. Here we report a chromosome-scale genome assembly of blackgrass and use this reference genome to explore the genomic/genetic basis of non-target site herbicide resistance (NTSR). Based on our analysis of F2 seed families derived from two distinct blackgrass populations with the same NTSR phenotype, we demonstrate that the trait is polygenic and evolves from standing genetic variation. We present evidence that selection for NTSR has signatures of both parallel and non-parallel evolution. There are parallel and non-parallel changes at the transcriptional level of several stress- and defence-responsive gene families. At the genomic level, however, the genetic loci underpinning NTSR are different (non-parallel) between seed families. We speculate that variation in the number, regulation and function of stress- and defence-related gene families enable weedy species to rapidly evolve NTSR via exaptation of genes within large multi-functional gene families. These results provide novel insights into the potential for, and nature of plant adaptation in rapidly changing environments.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('19b2cd6b-fed5-480a-a76a-6239ed80ad43', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Unravelling the effect of two herbicide resistance mutations on acetolactate synthase kinetics and growth traits', 'Zhao N, Yan Y, Du L, Zhang X, Liu W, Wang J', 2020, 'Journal of experimental botany', '10.1093/jxb/eraa120', 'https://doi.org/10.1093/jxb/eraa120', 'https://europepmc.org/articles/PMC7475246?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'Gene mutations conferring herbicide resistance are hypothesized to have negative pleiotropic effects on plant growth and fitness, which may in turn determine the evolutionary dynamics of herbicide resistance alleles. We used the widespread, annual, diploid grass weed Alopecurus aequalis as a model species to investigate the effect of two resistance mutations-the rare Pro-197-Tyr mutation and the most common mutation, Trp-574-Leu-on acetolactate synthase (ALS) functionality and plant growth. We characterized the enzyme kinetics of ALS from two purified A. aequalis populations, each homozygous for the resistance mutation 197-Tyr or 574-Leu, and assessed the pleiotropic effects of these mutations on plant growth. Both mutations reduced sensitivity of ALS to ALS-inhibiting herbicides without significant changes in extractable ALS activity. The 197-Tyr mutation slightly decreased the substrate affinity (corresponding to an increased Km for pyruvate) and maximum reaction velocity (Vmax) of ALS, whereas the 574-Leu mutation significantly increased these kinetics. Significant decrease or increase in plant growth associated, respectively, with the 197-Tyr and 574-Leu resistance mutations was highly correlated with their impact on ALS kinetics, suggesting more likely persistence of the 574-Leu mutation than the 197-Tyr mutation if herbicide application is discontinued.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('991df17a-9642-4754-9eb2-5c691b84c455', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'The Development of Herbicide Resistance Crop Plants Using CRISPR/Cas9-Mediated Gene Editing', 'Dong H, Huang Y, Wang K', 2021, 'Genes', '10.3390/genes12060912', 'https://doi.org/10.3390/genes12060912', 'https://europepmc.org/articles/PMC8231513?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'The rapid increase in herbicide-resistant weeds creates a huge challenge to global food security because it can reduce crop production, causing considerable losses. Combined with a lack of novel herbicides, cultivating herbicide-resistant crops becomes an effective strategy to control weeds because of reduced crop phytotoxicity, and it expands the herbicidal spectrum. Recently developed clustered regularly interspaced short palindromic repeat/CRISPR-associated protein (CRISPR/Cas)-mediated genome editing techniques enable efficiently targeted modification and hold great potential in creating desired plants with herbicide resistance. In the present review, we briefly summarize the mechanism responsible for herbicide resistance in plants and then discuss the applications of traditional mutagenesis and transgenic breeding in cultivating herbicide-resistant crops. We mainly emphasize the development and use of CRISPR/Cas technology in herbicide-resistant crop improvement. Finally, we discuss the future applications of the CRISPR/Cas system for developing herbicide-resistant crops.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6743f0f0-e536-4d80-8801-1c0959fd9726', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'The role of population and quantitative genetics and modern sequencing technologies to understand evolved herbicide resistance and weed fitness', 'Leon RG, Dunne JC, Gould F', 2021, 'Pest management science', '10.1002/ps.5988', 'https://doi.org/10.1002/ps.5988', 'https://europepmc.org/articles/PMC7754128?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc', 'Evolution of resistance to multiple herbicides with different sites of action and of nontarget site resistance (NTSR) often involves multiple genes. Thus, single-gene analyses, typical in studies of target site resistance, are not sufficient for understanding the genetic architecture and dynamics of NTSR and multiple resistance. The genetics of weed adaptation to varied agricultural environments is also generally expected to be polygenic. Recent advances in whole-genome sequencing as well as bioinformatic and statistical tools have made it possible to use population and quantitative genetics methods to expand our understanding of how resistance and other traits important for weed adaptation are genetically controlled at the individual and population levels, and to predict responses to selection pressure by herbicides and other environmental factors. The use of tools such as quantitative trait loci mapping, genome-wide association studies, and genomic prediction will allow pest management scientists to better explain how pests adapt to control tools and how specific genotypes thrive and spread across agroecosystems and other human-disturbed systems. The challenge will be to use this knowledge in developing integrated weed management systems that inhibit broad resistance to current and future weed-control methods. © 2020 The Authors. Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c961b5e9-5916-4214-bd28-6cab3aa78509', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Tolerance of Hymenaea stigonocarpa mart. Ex Hayne. To glyphosate', 'G. S. Faria, L. Carlos, S. C. Vasconcelos-Filho, S. T. F. Freitas, L. L. Lourenço, A. C. D. Sousa, L. A. Bessa, L. C. Vitorino', 2024, 'Brazilian Journal of Biology', '10.1590/1519-6984.279984', 'https://doi.org/10.1590/1519-6984.279984', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S1519-69842024000101286&lng=en&tlng=en', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Hymenaea stigonocarpa Mart. ex Hayne has leaves with adaxial and abaxial epidermis covered by a very thick cuticle, in addition to anatomical structures involved in reducing the amount of herbicide absorbed by plants. Thus, we tested the hypothesis that H. stigonocarpa is potentially resistant to the herbicide glyphosate, exposing the plants to different doses (0, 96, 240, 480, and 960 g a.e ha-1). We carried out assessments of the symptoms, anatomy, growth and physiology of the plants and found that exposure to glyphosate negatively affected the height and number of leaves of the plants. Leaf fall resulted in a reduction in the photosynthetic capacity of plants, which responded by investing in stem diameter. Despite this, no visual symptoms of glyphosate toxicity were observed at the concentrations evaluated and histochemical tests did not detect signs of oxidative stress in the leaves, nor starch accumulation, indicating that carbohydrate translocation was not impaired. These results confirm our hypothesis of tolerance of H. stigonocarpa to glyphosate. Furthermore, plants exposed to the lowest doses of glyphosate (96 and 240 g ha-1) showed good growth, photosynthesis, transpiration and photochemical potential responses, indicating a hormetic effect in this application range.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d6da290d-d99f-4123-b680-535b36ae5f86', 'e39bfed0-e15c-4dda-9a7b-4add071baeb3', 'Transcriptionally linked simultaneous overexpression of P450 genes for broad-spectrum herbicide resistance', 'Suda H, Kubo T, Yoshimoto Y, Tanaka K, Tanaka S, Uchino A, Azuma S, Hattori M', 2023, 'Plant physiology', '10.1093/plphys/kiad286', 'https://doi.org/10.1093/plphys/kiad286', 'https://europepmc.org/articles/PMC10400030?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'Broad-spectrum herbicide resistance (BSHR), often linked to weeds with metabolism-based herbicide resistance, poses a threat to food production. Past studies have revealed that overexpression of catalytically promiscuous enzymes explains BSHR in some weeds; however, the mechanism of BSHR expression remains poorly understood. Here, we investigated the molecular basis of high-level resistance to diclofop-methyl in BSHR late watergrass (Echinochloa phyllopogon) found in the United States, which cannot be solely explained by the overexpression of promiscuous cytochrome P450 monooxygenases CYP81A12/21. The BSHR late watergrass line rapidly produced 2 distinct hydroxylated diclofop acids, only 1 of which was the major metabolite produced by CYP81A12/21. RNA-seq and subsequent reverse transcription quantitative PCR (RT-qPCR)-based segregation screening identified the transcriptionally linked overexpression of a gene, CYP709C69, with CYP81A12/21 in the BSHR line. The gene conferred diclofop-methyl resistance in plants and produced another hydroxylated diclofop acid in yeast (Saccharomyces cerevisiae). Unlike CYP81A12/21, CYP709C69 showed no other herbicide-metabolizing function except for a presumed clomazone-activating function. The overexpression of the 3 herbicide-metabolizing genes was also identified in another BSHR late watergrass in Japan, suggesting a convergence of BSHR evolution at the molecular level. Synteny analysis of the P450 genes implied that they are located at mutually independent loci, which supports the idea that a single trans-element regulates the 3 genes. We propose that transcriptionally linked simultaneous overexpression of herbicide-metabolizing genes enhances and broadens the metabolic resistance in weeds. The convergence of the complex mechanism in BSHR late watergrass from 2 countries suggests that BSHR evolved through co-opting a conserved gene regulatory system in late watergrass.', '{epmc,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03b9ef0b-8d1f-4159-9119-8deccaf720ab', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Detection of Leptosphaeria maculans and Leptosphaeria biglobosa Causing Blackleg Disease in Canola from Canadian Canola Seed Lots and Dockage', 'Fernando WG, Zhang X, Amarasinghe CC', 2016, 'Plants (Basel, Switzerland)', '10.3390/plants5010012', 'https://doi.org/10.3390/plants5010012', 'https://europepmc.org/articles/PMC4844414?pdf=render', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc by', 'Blackleg, caused by Leptosphaeria maculans, is a major threat to canola production in Canada. With the exception of China, L. maculans is present in areas around the world where cruciferous crops are grown. The pathogen can cause trade barriers in international canola seed export due to its potential risk as a seed contaminant. The most recent example is China restricting canola seeds imported from Canada and Australia in 2009. Therefore, it is important to assess the level of Blackleg infection in Canadian canola seed lots and dockage (seeds and admixture). In this study, canola seed lots and dockage samples collected from Western Canada were tested for the presence of the aggressive L. maculans and the less aggressive L. biglobosa. Results showed that both L. maculans and L. biglobosa were present in seed lots and dockage samples, with L. biglobosa being predominant in infected seeds. Admixture separated from dockage had higher levels of L. maculans and L. biglobosa infection than samples from seed lots. Admixture appears to harbour higher levels of L. maculans infection compared to seeds and is more likely to be a major source of inoculum for the spread of the disease than infected seeds.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7ebc8991-5844-420d-b806-8d889a53f9e2', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Agronomic strategies to enhance the early vigor and yield of maize part II: the role of seed applied biostimulant, hybrid, and starter fertilization on crop performance', 'Capo L, Sopegno A, Reyneri A, Ujvári G, Agnolucci M, Blandino M', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1240313', 'https://doi.org/10.3389/fpls.2023.1240313', 'https://europepmc.org/articles/PMC10656683?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Maize cropping systems need to be re-designed, within a sustainable intensification context, by focusing on the application of high-use efficiency crop practices, such as those that are able to enhance an early plant vigor in the first critical growth stages; such practices could lead to significant agronomic and yield benefits. The aim of this study has been to evaluate the effects of the cultivation of hybrids with superior early vigor, of the distribution of starter fertilizers at sowing, and of the seed application of biostimulants on promoting plant growth and grain yield in full factorial experiments carried out in both a growth chamber and in open fields. The greatest benefits, in terms of plant growth enhancement (plant height, biomass, leaf area) and cold stress mitigation, were detected for the starter fertilization, followed by the use of an early vigor hybrid and a biostimulant seed treatment. The starter fertilization and the early vigor hybrid led to earlier flowering dates, that is, of 2.1 and 2.8 days, respectively, and significantly reduced grain moisture at harvest. Moreover, the early vigor hybrid, the starter NP fertilization, and the biostimulant treatment increased grain yield by 8.5%, 6.0%, and 5.1%, respectively, compared to the standard hybrid and the untreated controls. The combination of all the considered factors resulted in the maximum benefits, compared to the control cropping system, with an increase in the plant growth of 124%, a reduction of the sowing-flowering period of 5 days, and a gain in grain yield of 14%. When choosing the most suitable crop practice, the diversity of each cropping system should be considered, according to the pedo-climatic conditions, the agronomic background, the yield potential, and the supply chain requirements.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f61c1e4-6d4b-45a2-bcf8-681b15b8d4e0', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Broomrape Weeds. Underground Mechanisms of Parasitism and Associated Strategies for their Control: A Review', 'Fernández-Aparicio M, Reboud X, Gibot-Leclerc S', 2016, 'Frontiers in plant science', '10.3389/fpls.2016.00135', 'https://doi.org/10.3389/fpls.2016.00135', 'https://europepmc.org/articles/PMC4759268?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Broomrapes are plant-parasitic weeds which constitute one of the most difficult-to-control of all biotic constraints that affect crops in Mediterranean, central and eastern Europe, and Asia. Due to their physical and metabolic overlap with the crop, their underground parasitism, their achlorophyllous nature, and hardly destructible seed bank, broomrape weeds are usually not controlled by management strategies designed for non-parasitic weeds. Instead, broomrapes are in current state of intensification and spread due to lack of broomrape-specific control programs, unconscious introduction to new areas and may be decline of herbicide use and global warming to a lesser degree. We reviewed relevant facts about the biology and physiology of broomrape weeds and the major feasible control strategies. The points of vulnerability of some underground events, key for their parasitism such as crop-induced germination or haustorial development are reviewed as inhibition targets of the broomrape-crop association. Among the reviewed strategies are those aimed (1) to reduce broomrape seed bank viability, such as fumigation, herbigation, solarization and use of broomrape-specific pathogens; (2) diversion strategies to reduce the broomrape ability to timely detect the host such as those based on promotion of suicidal germination, on introduction of allelochemical interference, or on down-regulating host exudation of germination-inducing factors; (3) strategies to inhibit the capacity of the broomrape seedling to penetrate the crop and connect with the vascular system, such as biotic or abiotic inhibition of broomrape radicle growth and crop resistance to broomrape penetration either natural, genetically engineered or elicited by biotic- or abiotic-resistance-inducing agents; and (4) strategies acting once broomrape seedling has bridged its vascular system with that of the host, aimed to impede or to endure the parasitic sink such as those based on the delivery of herbicides via haustoria, use of resistant or tolerant varieties and implementation of cultural practices improving crop competitiveness.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('339b6c55-e71a-4a20-ba5e-a0640cb3a910', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Broomrapes in Major Mediterranean Crops: From Management Strategies to Novel Approaches for Next-Generation Control', 'Chachalis D, Tani E, Kapazoglou A, Gerakari M, Petraki A, Pérez-Alfocea F, Martínez-Melgarejo PA, Albert M', 2025, 'Biotech (Basel (Switzerland))', '10.3390/biotech14020040', 'https://doi.org/10.3390/biotech14020040', 'https://europepmc.org/articles/PMC12190798?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'Broomrapes (Orobanche and Phelipanche spp.) are parasitic weeds that significantly impact the productivity of major crops in the Mediterranean region, like tomato (Solanum spp.) and faba bean (Vicia faba) species. This review article extensively discusses management strategies to control broomrapes, which range from preventive measures to curative approaches. Additionally, it includes meaningful information on the intricate molecular mechanisms underlying the broomrape-host interaction, focusing on the host recognition of parasitic plant molecular patterns and the hormonal crosstalk that regulates the establishment of parasitism. Moreover, this article highlights the potential of breeding for resistance in cultivated crops, such as tomato and faba bean, as a sustainable, long-term solution to combat broomrape infestation. This review serves as a valuable resource for both researchers and farmers, offering insights for developing, implementing, and adapting effective and environmentally sustainable management practices for broomrape in Mediterranean agricultural systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8600c66b-8dc1-4841-a6db-3a4485e10548', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Characterization of the Giant Foxtail''s (Setaria faberi) ALS Gene and Its Enhanced Metabolism-Based Cross-Resistance to Nicosulfuron and Rimsulfuron', 'Papapanagiotou AP, Alvanou MV, Giantsis IA, Vasilakoglou I, Eleftherohorinos IG', 2025, 'Genes', '10.3390/genes16050505', 'https://doi.org/10.3390/genes16050505', 'https://europepmc.org/articles/PMC12111008?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'BackgroundWeed herbicide resistance is a serious problem in crop protection globally. Giant foxtail (Setaria faberi R.A.N. Herrm.) populations cannot be controlled by acetolactate synthase (ALS)-inhibiting herbicides in a few corn (Zea mays L.) monoculture fields.MethodsFive putative resistant giant foxtail populations, originating from corn monoculture fields in northeastern Greece, were evaluated for possible evolution of ALS-inhibitor resistance (nicosulfuron, rimsulfuron). The resistance ratio, the underlying resistance mechanism, and its impact on competitive ability against corn were studied.ResultsThe whole-plant rate-response assays showed that these populations were resistant (R) to the sulfonylureas nicosulfuron and rimsulfuron, but susceptible (S) to imidazolinone imazamox, triketone 4-hydroxyphenylpyruvate dioxygenase inhibitor tembotrione, and acetyl-CoA carboxylase inhibitor cycloxydim. The sequencing of the ALS gene did not reveal the presence of resistance-associated point mutations, indicating that the resistance was probably not target-site mediated. This was confirmed by the application of piperonyl butoxide two hours before nicosulfuron application, which reversed the resistance in all R giant foxtail populations, supporting the evidence of enhanced metabolism-mediated resistance. The competition study between corn and R or S giant foxtail populations indicated no stable trend reduction in corn traits, suggesting that the resistance mechanism was not associated with the competitive ability of the R populations. The novel ALS genotype in S. faberi, characterized for the first time and submitted to the GenBank database with accession number PV016837, indicated a closer genetic relationship with the S. viridis ALS gene than with S. italica.ConclusionsFive giant foxtail populations have evolved metabolism-based resistance to the ALS-inhibiting herbicides nicosulfuron and rimsulfuron.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ff79a0ba-b0c4-42fb-a719-abc578262f8f', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Chemical Control of the Invasive Weed Trianthema portulacastrum: Nethouse Studies', 'Goldwasser Y, Rabinowitz O, Abu-Nasser J, Smirnov E, Achdary G, Eizenberg H', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants14010019', 'https://doi.org/10.3390/plants14010019', 'https://europepmc.org/articles/PMC11723401?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Trianthema portulacastrum L. (Aizoaceae), commonly known as desert horse purslane or black pigweed, is a C4 dicot succulent invasive annual plant that is widespread in agricultural fields in Southeast Asia, tropical America, Africa, and Australia. In Israel, Trianthema portulacastrum is an invasive weed of increasing importance in agricultural fields, including mainly corn, tomato, alfalfa watermelon, and groundnut crops. The significance of this weed in crops has been recently reported in neighboring countries of Jordan and Egypt. In previous studies, we have examined and described the spread, biology, and germination requirements of Trianthema portulacastrum in Israel. The present study aimed to investigate the efficiency of single pre- and post-emergence herbicides and the combination of pre-applied herbicides for the control of this invasive weed in pots in a nethouse. We conducted three sequential experiments in a nethouse: (1) screening of pre-emergence herbicides, (2) screening of post-emergence herbicides, and (3) assessment of residual activity of combined pre-emergence herbicides in three distinct Hula Valley soil types. Efficacy was evaluated through weekly assessments of seedling emergence and vigor, with the final shoot fresh weight determined upon the experiment''s completion. In all experiments, weekly counts and vigor estimation of T. portulacastrum seedlings were conducted, and shoot fresh weights were determined at the end of the experiments. The results of pre-emergence herbicide screening showed that Fomesafen, Terbutryne, Flurochloridon, Sulfosulfuron, Cyrosulfamid + Izoxaflutole, and Dimethenamid were the most effective herbicides, leading to complete eradication of T. portulacastrum plants. Results of the post-emergence screening revealed that Saflufenacil, Foramsulfuron, Tembotrione + Isoxdifen-ethyl, and Rimsulfurom Methyl completely controlled the weed. In the soil residual study, three herbicide combinations (Fomesafen + Terbutryn, Sulfosulfuron + Fomesafen, and Dimethenamid + Flurochloridon) provided effective control across all soil types. These findings provide a foundation for future field trials investigating integrated pre- and post-emergence herbicide programs for T. portulacastrum management in various crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d646c0eb-5f04-4102-b110-7509d180af9b', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Cycloheximide in the nanomolar range inhibits seed germination of Orobanche minor', 'Nogami R, Nagata M, Imada R, Kai K, Kawaguchi T, Tani S', 2024, 'Journal of pesticide science', '10.1584/jpestics.d23-038', 'https://doi.org/10.1584/jpestics.d23-038', 'https://europepmc.org/articles/PMC10912901?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by-nc-nd', 'From the 992 samples of culture extracts of microorganisms isolated from soil in Japan, we found that the extract of Streptomyces sp. no. 226 inhibited Orobanche minor seed germination without significantly affecting the seed germination of Trifolium pratense and the growth of Aspergillus oryzae and Escherichia coli. Using ESI-MS, 1H-NMR, and 13C-NMR, we identified the active compound as cycloheximide. Cycloheximide had half-maximum inhibitory concentrations of 2.6 ng/mL for the inhibition of seed germination of O. minor and 2.5 µg/mL for that of the conidial germination of A. oryzae. Since cycloheximide is known to inhibit translation by interacting with ribosomal protein L28 (RPL28) in yeast, we investigated whether RPL protein of O. minor plays a critical role in the inhibition of O. minor seed germination. Our data suggested that O. minor RPL27A was not sensitive to cycloheximide by comparing it to the strain expressing S. cerevisiae RPL28. These findings suggest the presence of an unidentified mechanism by which cycloheximide hinders O. minor seed germination.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('482cae79-31ee-47d8-8196-399b39107b4f', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Cytochrome P450s-Involved Enhanced Metabolism Contributes to the High Level of Nicosulfuron Resistance in Digitaria sanguinalis from China', 'Wang X, Hu W, Li Y, Jiang M, Zhao N, Cao H, Liao M', 2023, 'Biology', '10.3390/biology12091192', 'https://doi.org/10.3390/biology12091192', 'https://europepmc.org/articles/PMC10525941?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Large crabgrass (Digitaria sanguinalis (L.) Scop.) is one of the major malignant grass weeds in Chinese maize (Zea mays L.) fields, and it has recently developed resistance to the acetolactate synthase (ALS)-inhibiting herbicide nicosulfuron. This study focused on a suspected nicosulfuron-resistant (R) population (LJ-01) of D. sanguinalis, collected from Lujiang County in Anhui Province, China, to explore the resistance level and potential resistance mechanism. Whole-plant dose-response testing confirmed that the LJ-01 population evolved a high level of resistance to nicosulfuron (11.5-fold) compared to the susceptible (S) population, DY-02. The ALS gene sequencing and relative expression assay of the R plants indicated that target gene mutation and overexpression were not responsible for the resistance phenotype. However, pretreatment with malathion, a known cytochrome P450 monooxygenase (P450) inhibitor, alleviated the resistance of the R population to nicosulfuron by approximately 36%. High-performance liquid chromatography (HPLC) analysis revealed that the R plants metabolized nicosulfuron faster than the S plants. Moreover, cross-resistance testing suggested that the R population exhibited low levels of resistance to thifensulfuron-methyl and pyrazosulfuron-ethyl, but it remained susceptible to rimsulfuron. Multiple resistance patterns showed that the R population evolved low resistance to the photosystem inhibitors bromoxynil octanoate and atrazine and sensitivity to the acetyl-CoA carboxylase (ACCase) inhibitor cyhalofop-butyl and the 4-hydroxyphenylpyruvate dioxygenase (HPPD) inhibitors tembotrione, mesotrione, and topramezone. This study reports, for the first time, the simultaneous resistance to ALS and different photosystem inhibitors in D. sanguinalis. The nicosulfuron resistance observed in the R population could primarily be attributed to an enhanced metabolism involving P450 enzymes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60af9103-f3c4-4792-a266-1769a588f123', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Effects of foliar-sprayed bio-fertilizer with N-fixing Methylobacterium symbioticum on morpho-physiological traits of maize under varying N fertilization rates', 'Bolla PK, Panozzo A, Minozzi E, Valente F, Potestio S, Visioli G, Martinez-Sañudo I, Vamerali T', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1661290', 'https://doi.org/10.3389/fpls.2025.1661290', 'https://europepmc.org/articles/PMC12444665?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Nitrogen (N) fertilization remains a critical challenge in sustainable agriculture. Plant growth-promoting bacteria offer a promising strategy to enhance nitrogen use efficiency and improve cereal crop productivity while reducing reliance on synthetic inputs. This open-field study evaluated the morpho-physiological effects of foliar application of Methylobacterium symbioticum (MS) on maize in NE Italy. Following a baseline application of liquid digestate (300 kg N ha-¹) to all plots, four treatments were compared: N300 (digestate only, serving as the control); N300 + MS (digestate with MS); N350 (digestate with 50 kg ha-¹ chemical N); and N320 + MS (digestate with 20 kg ha-¹ chemical N and MS). ESEM imaging confirmed colonization of leaf surfaces by M. symbioticum. Its application significantly promoted aboveground growth and delayed leaf senescence by improving chlorophyll retention, increasing seasonal average SPAD from 46.9 in control to 49.4 (+5.3%, N300 + MS) and 48.8 (+4.1%, N320 + MS), likely mediated by the ascertained ACC-deaminase activity of MS. Root electrical capacitance showed treatment-specific effects, with the highest readings under the N320 + MS treatment (+54% vs. control at flowering). Yield responses were non-linear with respect to N dose, with N300 + MS showing a 12% (1,364 g/m²) and N320 + MS a 6% non-significant increase vs. control. MS-treated plants also exhibited a non-significant 5% increase in grain protein content, but significantly higher aboveground N accumulation. It is concluded that, this microbial inoculation strategy can enhance N use efficiency, particularly under reduced synthetic fertilization, presenting an environmentally-friendly and sustainable agricultural strategy for maize cultivation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4ee9cad-76fc-4c82-9674-ed36ca94e2de', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Evaluating Branched Broomrape (Phelipanche ramosa) Management Strategies in California Processing Tomato (Solanum lycopersicum)', 'Fatino MJ, Hanson BD', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11030438', 'https://doi.org/10.3390/plants11030438', 'https://europepmc.org/articles/PMC8839415?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Detections of the regulated noxious parasitic weed branched broomrape (Phelipanche ramosa) in California tomato fields have led to interest in eradication, sanitation, and management practices. Researchers in Israel developed a decision-support system and herbicide treatment regime for management of Egyptian broomrape (P. aegyptiaca) in tomato. Research was conducted in 2019 and 2020 to evaluate whether similar treatments could be used to manage branched broomrape in California processing tomatoes and to provide registration support data for the herbicide use pattern. Treatment programs based on preplant incorporated (PPI) sulfosulfuron and chemigated imazapic were evaluated in 2019 and 2020 to determine safety on the processing tomato crop and on common rotational crops. Three single-season tomato safety experiments were conducted and a single rotational crop study was conducted in which a tomato crop received herbicide treatments in 2019 and several common rotational crops were planted and evaluated in 2020 in a site without branched broomrape. In 2020, an efficacy study was conducted in a commercial tomato field known to be infested with branched broomrape to evaluate the efficacy of PPI sulfosulfuron and chemigated imazapic, imazapyr, imazethapyr, and imazamox. After two field seasons, sulfosulfuron and imazapic appeared to have reasonable crop safety on tomato in California; however, rotational crop restrictions will need to be considered if sulfosulfuron is used to manage branched broomrape. In the efficacy study, there was a trend in which the sulfosulfuron and imidazolinone treatments had fewer broomrape shoots per plot than the grower standard treatments, however, none were fully effective and there were no significant differences among the various sulfosulfuron and imidazolinone treatment combinations. Additional research is needed to optimize the treatment timing for management of branched broomrape in this cropping system. Because of registration barriers with imazapic in the California market, future research will focus on treatment combinations of PPI sulfosulfuron and chemigated imazamox rather than imazapic.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('793543ca-dcf9-40d2-9244-97e875fc5b3d', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Evaluating the effects of manual hoeing and selective herbicides on maize (Zea mays L.) productivity and profitability', 'Bin Lukangila MA, Tabu HI, Mugisho DB, Lubobo AK, Mbuyi Wa Mbombo AK', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e33294', 'https://doi.org/10.1016/j.heliyon.2024.e33294', 'https://europepmc.org/articles/PMC11255669?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by-nc-nd', 'The objective of this study was to evaluate maize production and the economic profitability of weed management techniques. Field trials were conducted at the Kasapa farm during the 2021/22 growing seasons using a split-plot design with three repetitions. The main factor was the herbicides applied in pre-emergence alone (2L ha-1: acetochlor, bentazon, imazethapyr and 60 g ha-1 chlorimuron-ethyl), then mixed (1L ha-1: acetochlor plus bentazon plus imazethapyr plus 30g ha-1chlorimuron-ethyl), manual hoeing (3-5WAS) including the non-weeding. The secondary factor: maize varieties (GV672A, GV673A, GV664A and Sam4vita). The highest maize dry grain yield (7.66 t ha-1) was associated with imazethapyr, while those of acetochlor and chlorimuron-ethyl (6.86 and 6.92 t ha-1) compared to manual hoeing (7.62 t ha-1, respectively) were low, but much higher than no weeding (1.21 t ha-1). The yields of varieties GV672A and GV664A were higher (6.87 and 6.77 t ha-1), compared to Sam4vita (5.64 t ha-1). The total dry weight of weeds was negatively correlated with all crop parameters, with its maximum value (127.56 g m-2) characterizing non-weeding, and the minimum for manual hoeing (18.83 g m-2). The Ratio Cost Value showed that all treatments were profitable: imazethapyr > bentazon > chlorimuron-ethyl > combination > acetochlor > manual hoeing. However, imazethapyr was economically more profitable and could replace manual hoeing when the field to be weeded increases and labor is scarce.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c4fddf25-b98d-454d-8f16-abe23bac360d', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Evaluation of data concerning the necessity of isoxaflutole as a herbicide to control a serious danger to plant health which cannot be contained by other available means, including non-chemical methods', 'European Food Safety Authority (EFSA).', 2017, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2017.4894', 'https://doi.org/10.2903/j.efsa.2017.4894', 'https://europepmc.org/articles/PMC7010041?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'cc by-nd', 'The European Food Safety Authority was requested by the European Commission to provide scientific assistance under Article 31 of Regulation (EC) No 178/2002 regarding the evaluation of data concerning the necessity of isoxaflutole as a herbicide to control a serious danger to plant health which cannot be contained by other available means including non-chemical methods, in accordance with Article 4(7) of Regulation (EC) No 1107/2009. In this context, EFSA organised a commenting phase with Member States in order to collect and validate the data submitted by the applicant. The current scientific report summarises the outcome of the evaluation of three different uses (maize, sweetcorn and poppy) in 10 Member States. The evaluation demonstrated that for two uses (maize and sweetcorn) insufficient or sufficient chemical alternatives are available, and for one use (poppy) insufficient chemical alternatives to isoxaflutole are available. The evaluation included an assessment of non-chemical methods for the presented uses. A wide range of non-chemical methods are available, however, often these methods do not have the same efficacy as chemical methods or have economic limitations. A combination of both chemical and non-chemical methods seems often possible.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('782ab709-9744-44ef-bc0e-0288afff25a1', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Herbicide Resistance Is Increasing in Spain: Concomitant Management and Prevention', 'Montull JM, Torra J', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12030469', 'https://doi.org/10.3390/plants12030469', 'https://europepmc.org/articles/PMC9920091?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Herbicide-resistant weeds currently challenge sustainable food production in almost all cropping systems in Europe. Herbicide resistance is increasing, and some European countries are among the most affected globally, such as Spain and France. This situation is worsening not only due to herbicide use restrictions but also due to climate change, rendering Mediterranean countries such as Spain particularly susceptible. Therefore, focus should be aimed at preventive measures, which include those not only based on integrated weed management strategies but also based on a very good knowledge of the biology and ecology of each weed species. The main objective of this review is to provide an overview of potential future herbicide-resistant cases that can evolve in the near future in Europe. We use Spain as the case study, as it is the most affected country in Europe and because it is at risk due to global warming. For different resistant cases detailed on a crop basis, adequate prevention and management measures will be provided in order to avoid resistance evolution relative to the sites of action that are most likely to generate resistant biotypes due to expected high selection pressures.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('745ed653-039f-4028-b33a-d0e2dbb67eb1', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Herbicides in Use: Current Status and Perspectives in the Different Biogeographic Regions of Europe', 'Synowiec A, Czekaj M, Verdeguer M, De Barreda DG, Campillo-Cora C, Vieites-Álvarez Y, López-González D, Sánchez-Moreiras AM', 2025, 'Journal of agricultural and food chemistry', '10.1021/acs.jafc.5c03867', 'https://doi.org/10.1021/acs.jafc.5c03867', 'https://europepmc.org/articles/PMC12426928?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'This review examines the use of herbicides across Europe''s biogeographical regions, focusing on their historical development, regulatory framework, and environmental impacts. Since the 20th century, the use of herbicides has significantly increased agricultural productivity. However, the continuous use of herbicides with the same mode of action can lead to the development of resistant weeds, especially when low-diversity weed management strategies are employed. The European Union has established a strict approval process for herbicidal substances to safeguard environmental and human health. Consequently, the number of authorized active ingredients has declined due to concerns over their adverse effects. This review highlights the need for new sustainable tools for weed control and advocates reassessing Europe''s dependence on chemical herbicides, encouraging integrated weed management approaches and policies that balance productivity with environmental protection for a sustainable agricultural future.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c8eb50c-49a7-4ca9-a7a0-3222aecfbdb9', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Integrated Transcriptomic and Metabolomic Analysis Reveals the Meat Production Features in Hybrid Sheep', 'Chen Z, Dong S, Zhang L, An X, Li Q, Xu Z, Geng Z, Shi H', 2026, 'Animals : an open access journal from MDPI', '10.3390/ani16010137', 'https://doi.org/10.3390/ani16010137', 'https://europepmc.org/articles/PMC12784912?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'This study was conducted to investigate potential regulatory mechanisms of hybridization increased the meat production performance in sheep. Thirty-six 3-month-old male lambs of Suffolk sheep (SFK, n = 12), Hu sheep (HH, n = 12), and their F1 hybrids (SH, n = 12) were selected and raised in individual pens under identical nutritional supply and husbandry management regimes over a 95-day (including a 15-day pre-trial period) experimental period. At the end of the feeding trial, six sheep closest to the average body weight were selected from each group for the subsequent trial, involving the collection of Longissimus dorsi samples and the determination of production performance, muscle fiber characteristic and transcriptomic and metabolomic analysis. The results showed that the SH sheep had significantly higher pre-slaughter live weight and carcass weight than the HH sheep, while lower than those of the SFK sheep (p p p SESN3 and metabolites (malate, testosterone) enhance energy supply capacity through AMPK pathway, thereby promoting muscle fiber proliferation and increasing meat yield in the hybrid sheep. In conclusion, the heterosis of the SH group originates from the remodeling of muscle fiber structure and the synergistic regulation of related pathways, which provides a theoretical basis for sheep crossbreeding.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f455944f-25e3-4e23-acb7-6d0e2928e9eb', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Maize Yield Response, Root Distribution and Soil Desiccation Crack Features as Affected by Row Spacing', 'Lacolla G, Caranfa D, De Corato U, Cucci G, Mastro MA, Stellacci AM', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12061380', 'https://doi.org/10.3390/plants12061380', 'https://europepmc.org/articles/PMC10057019?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Plant density is among the most critical factors affecting plant yields and resource use efficiency since it drives the exploitation of the available resources per unit area, root distribution and soil water losses by direct evaporation from the soil. Consequently, in fine-textured soils, it can also affect the formation and development of desiccation cracks. The aim of this study, carried out on a sandy clay loam soil in a typical Mediterranean environment, was to investigate the effects of different row spacings of maize (Zea mais L.) on yield response, root distribution and the main features of desiccation cracks. The field experiment compared bare soil and soil cropped with maize using three plant densities (6, 4 and 3 plants m-2), obtained by keeping the number of plants in a row constant and varying the distance between the rows (0.5-0.75-1.0 m). The highest kernel yield (16.57 Mg ha-1) was obtained with the greatest planting density (6 plants m-2) with a row spacing of 0.5 m; significantly lower yields were recorded with spacings of 0.75 and 1 m, with a decrease of 8.09% and 18.24%, respectively. At the end of the growing season, soil moisture in the bare soil was on average 4% greater in comparison to the cropped soil and was also affected by row spacing, decreasing with the decrease in the inter-row distance. An inverse behaviour was observed between soil moisture and both root density and desiccation crack size. Root density decreased to the increase in soil depth and to the increase in distance from the row. The pluviometric regime occurred during the growing season (total rainfall of 343 mm)-resulted in the formation of cracks of reduced size and with an isotropic behaviour in the bare soil, whereas in the cultivated soil, the cracks were parallel to the maize rows and increased in size with decreasing inter-row distance. The total volume of the soil cracks reached a value of 135.65 m3 ha-1 in the soil cropped with a row distance of 0.5 m, and was about ten times greater in comparison to the bare soil and three times greater in comparison to a row spacing of 1 m. Such a volume would allow a recharge of 14 mm in the case of intense rainy events on soil characterised by low permeability.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79373f5f-428e-4252-86e4-aaf8dcaa855b', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Methods of Control of Parasitic Weeds of the Genus Cuscuta-Current Status and Future Perspectives', 'Zagorchev L, Zagorcheva T, Teofanova D, Odjakova M', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14152321', 'https://doi.org/10.3390/plants14152321', 'https://europepmc.org/articles/PMC12348958?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Dodders (Cuscuta spp.; Convolvulaceae) are parasitic weeds that pose major challenges to agriculture due to their ability to infect a wide range of host plants, extract nutrients, and transmit pathogens. Their control is especially challenging because of the seed longevity, resistance to herbicides, and the capacity for vegetative regeneration. Mechanical methods such as hand-pulling or mowing are labour-intensive and often ineffective for large infestations. Chemical control is limited, as systemic herbicides often affect the host species equally, or even worse than the parasite. Current research is exploring biological control methods, including allelopathic compounds, host-specific fungal pathogens, and epiparasitic insects, though these methods remain largely experimental. An integrated approach that combines prevention, targeted mechanical removal, and biological methods offers the most promising path for long-term management. Continued research is essential to develop effective, sustainable control strategies while exploring possible beneficial uses of these complex parasitic plants. The present review aims to thoroughly summarise the existing literature, emphasising the most recent advances and discussing future perspectives.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('09888100-5d8e-4945-942e-0d99c7577b23', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Molecular and phenotypic characterization of Als1 and Als2 mutations conferring tolerance to acetolactate synthase herbicides in soybean', 'Walter KL, Strachan SD, Ferry NM, Albert HH, Castle LA, Sebastian SA', 2014, 'Pest management science', '10.1002/ps.3725', 'https://doi.org/10.1002/ps.3725', 'https://europepmc.org/articles/PMC4282486?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'BackgroundSulfonylurea (SU) herbicides are effective because they inhibit acetolactate synthase (ALS), a key enzyme in branched-chain amino acid synthesis required for plant growth. A soybean line known as W4-4 was developed through rounds of seed mutagenesis and was demonstrated to have a high degree of ALS-based resistance to both post-emergence and pre-emergence applications of a variety of SU herbicides. This report describes the molecular and phenotypic characterization of the Als1 and Als2 mutations that confer herbicide resistance to SUs and other ALS inhibitors.ResultsThe mutations are shown to occur in two different ALS genes that reside on different chromosomes: Als1 (P178S) on chromosome 4 and Als2 (W560L) on chromosome 6 (P197S and W574L in Arabidopsis thaliana).ConclusionAlthough the Als1 and Als2 genes are unlinked, the combination of these two mutations is synergistic for improved tolerance of soybeans to ALS-inhibiting herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37ce0d5c-2847-46f4-9f66-0b4562d83788', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Monitoring for a new I3 resistance gene-breaking race of F. oxysporum f. sp. lycopersici (Fusarium wilt) in California processing tomatoes following recent widespread adoption of resistant (F3) cultivars: Challenges with race 3 and 4 differentiation methods', 'Swett CL, Del Castillo Múnera J, Hellman E, Helpio E, Gastelum M, Lopez Raymundo E, Johnson H, Oguchi R', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1088044', 'https://doi.org/10.3389/fpls.2023.1088044', 'https://europepmc.org/articles/PMC10102640?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Fusarium wilt, caused by Fusarium oxysporum f. sp. lycopersici (Fol), causes losses in tomato production worldwide, with major impacts on Californian tomato processing. Single-gene resistance is the primary management tool, but its efficacy has been compromised following the emergence of two successive resistance-breaking races, which, in California, emerged within 12 years of resistance deployment. Fol race 3-resistant (F3) processing tomato cultivars (containing the I3 resistance gene) were deployed in the state starting in approximately 2009. The emergence of a new resistance-breaking race (which would be called race 4) is imminent, and early detection will be critical to delay the spread while new resistance is sought. The detection of Fol race 4 is challenged by the lack of validated, rapid, and accurate diagnostic tools. In evaluating in planta phenotyping methods, this study found that rapid seedling phenotyping is not reliable and generates false positives for nonpathogens. Longer (10 weeks) mature plant assays are the most reliable, but may not be sufficiently timely. As an additional challenge, based on field and greenhouse studies, Fol race 3 can cause symptoms in resistant F3 cultivars at frequencies greater (30%) than expected for off-types (in planta assay to overcome the challenges this posed to differentiating Fol race 3 and Fol race 4. Using the assay, we determined that all putative resistance-breaking cases were Fol race 3; Fol race 4 was not detected in these early survey efforts. These results highlight the need for developing rapid Fol race 4 detection tools and a better understanding of the factors underlying inconsistent I3 gene expression in Fol race 3.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48ae3985-fadf-4a33-afb9-c6e556ff1dfa', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Naphthalic anhydride decreases persistence of alachlor and atrazine and elevates tolerance of maize', 'Nemat Alla MM, Hassan NM', 2020, 'Heliyon', '10.1016/j.heliyon.2020.e05172', 'https://doi.org/10.1016/j.heliyon.2020.e05172', 'https://europepmc.org/articles/PMC7553984?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by-nc-nd', 'The present study aimed at alleviating the impacts of alachlor (Ala) or atrazine (Atr) on maize growth by seed-dressing with naphthalic anhydride (NA, 0.4% w/w by seed weight). The dressed and undressed seeds were germinated for 10 days and treated with Ala or Atr at 3.2 or 1.8 kg ha-1, respectively, then the herbicide residues were determined in shoots one day after treatment. Atr residues were higher than Ala and remained in the same level for the 2nd day then retracted consistently up to 12 days. Meanwhile, GSH and GST were significantly induced while growth parameters were reduced; the effect of Atr was higher than Ala. Nonetheless, ABA, phenolics and anthocyanins as well as PAL, TAL and CI were increased but IAA was decreased coincidently with enhanced IAA-O and peroxidase. The immediate detection of the herbicide residues could conclude that growth reduction as elucidated from the decreased IAA concomitant with elevating ABA, phenolics and anthocyanin contents and enzyme activities are consequences of the herbicide persistence. The drop of IAA was preceded by the stimulation of IAA-O and peroxidase while the increased phenolics and anthocyanins followed PAL, TAL and CI stimulation confirming the regulatory roles of these enzymes. The application of NA greatly lowered the herbicide residues concurrently with ameliorations in growth parameters, GSH, GST, and maintained the balancing of secondary metabolites and plant growth regulators. Lowering Ala and Atr residues by NA in synchronization with enhanced GSH and GST could conclude that NA encouraged the detoxification of the herbicide. Moreover, the balances of IAA, ABA, phenolics and anthocyanins were mostly maintained in normal levels concomitantly with growth ameliorations suggesting that phytohormones and secondary metabolites are involved in the elevation of maize tolerance to Ala and Atr.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('73081555-b999-41d7-a0be-be2f75f81c68', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Non-target effects on soil microbial parameters of the synthetic pesticide carbendazim with the biopesticides cantharidin and norcantharidin', 'Shao H, Zhang Y', 2017, 'Scientific reports', '10.1038/s41598-017-05923-8', 'https://doi.org/10.1038/s41598-017-05923-8', 'https://europepmc.org/articles/PMC5514074?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Considering the fact that biopesticides are increasingly used to replace synthetic pesticides in pest control, it is necessary to assess their ecotoxicity and especially their non-target effects on soil microorganisms, which is largely unknown. In this study, the effects of the synthetic pesticide carbendazim and the biopesticides (cantharidin and norcantharidin) on soil microbial parameters in a silt loam soil were evaluated. By using commercial formulations at the recommended and higher rates, both cantharidin and norcantharidin induced adverse effects on soil invertase, phosphatase activities and fungal gene structure, but these changes were transient. After about two weeks, the harmful effects owing to the application of pesticides phased out and eventually became comparable with non-treated samples. The degradation of cantharidin and norcantharidin was rapid and can be completed within a few days in the soil. None of the three pesticides caused significant shifts in urease activity. This study provides a comprehensive assessment of the soil microbial toxicity of these biopesticides for reasonable and efficient usage.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7dece603-b66c-4da2-939a-efc1a605da28', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Smart delivery of herbicide for safe and effective control of Egyptian broomrape parasitizing Indian mustard', 'Jat RS, Agrawal A, Kala S, Choudhary RL, Singh HV, Kumar J, Singh VV', 2026, 'Scientific reports', '10.1038/s41598-026-44367-x', 'https://doi.org/10.1038/s41598-026-44367-x', 'https://europepmc.org/articles/PMC13061932?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'Oilseed Brassica, an important edible oilseed crop of the world, is facing severe threat from the parasitic weed ''Egyptian broomrape'' [Phelipanche aegyptiaca (Pers.) Pomel] with yield penalty of 0-100%. The problem is more severe due to its physico-biochemical connection with the hosts, where, general weed control measures are not effective to control this parasitic weed. Since, there is no absolute measure to control Egyptian broomrape. The present study was aimed to identify and develop the most effective herbicide formulation and deliver the herbicide to the targeted underground parasite weed for effective and safe control in Indian mustard. Simple (single) and complex (combinational) smart herbicide formulations (NE, ME, SE, SC & ZC) were developed and evaluated under hot-spot conditions. Among all the smart formulations, metsulfuron methyl 5% SC @ 4 ml a.i./ha applied at pre-emergence stage was found most effective in controlling Egyptian broomrape with no phytotoxicity, and recorded higher seed yield of Indian mustard (48-74%) over weedy check plots. Residue analysis using LC-MS/MS revealed that metsulfuron methyl was not detected in soil as well as plant samples thus, it was environmentally safe also. This research successfully demonstrated that metsulfuron methyl-based smart formulations (5% SC) can safely and effectively control Egyptian broomrape in Indian mustard.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cb7e4fcb-f707-4f0e-9a78-d642a137a3a5', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Photosystem II Subunit S overexpression increases the efficiency of water use in a field-grown crop', 'Głowacka K, Kromdijk J, Kucera K, Xie J, Cavanagh AP, Leonelli L, Leakey ADB, Ort DR', 2018, 'Nature communications', '10.1038/s41467-018-03231-x', 'https://doi.org/10.1038/s41467-018-03231-x', 'https://europepmc.org/articles/PMC5840416?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Insufficient water availability for crop production is a mounting barrier to achieving the 70% increase in food production that will be needed by 2050. One solution is to develop crops that require less water per unit mass of production. Water vapor transpires from leaves through stomata, which also facilitate the influx of CO2 during photosynthetic assimilation. Here, we hypothesize that Photosystem II Subunit S (PsbS) expression affects a chloroplast-derived signal for stomatal opening in response to light, which can be used to improve water-use efficiency. Transgenic tobacco plants with a range of PsbS expression, from undetectable to 3.7 times wild-type are generated. Plants with increased PsbS expression show less stomatal opening in response to light, resulting in a 25% reduction in water loss per CO2 assimilated under field conditions. Since the role of PsbS is universal across higher plants, this manipulation should be effective across all crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('af5ae791-ebbd-4a97-81c3-4ec5fa53c9ca', '230dcb00-b5bb-415a-b919-b3ccab4d7e15', 'Suggested policy and legislation reforms to reduce deleterious effect of pesticides in Lebanon', 'Abou Zeid MI, Jammoul AM, Melki KC, Jawdah YA, Awad MK', 2020, 'Heliyon', '10.1016/j.heliyon.2020.e05524', 'https://doi.org/10.1016/j.heliyon.2020.e05524', 'https://europepmc.org/articles/PMC7725726?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by-nc-nd', 'Countrywide pesticide management activities are resource draining, even for developed countries, which sometimes fall short in achieving the optimum protection against pesticides deleterious effects on humans and environment. Additionally, in Lebanon, basic flaws exist at different levels of pesticide management cycle. In this study, through an extensive review of relevant literature regarding the pesticides impact on humans and environment in Lebanon and adopted policies in existing legislation, several gaps have been identified. Accordingly, recommendations to reduce pesticide risk through a combination of reforms at the policy level and its tools, particularly legislation, are proposed. In our opinion, the starting point is to adopt a minimum list of lower risk pesticides supported by a combination of: "prescriptions" based on a comprehensive registration and an effective implementation systems, a suitable IPM/ICM government-supported credit system, traceability systems of agricultural commodities and pesticides containers, Pesticide stock management system to reduce the quantity of obsolete pesticides, and containers recycling system. For a global sustainability of pesticides risk reduction, a binding global intervention fostered by the UN, based on human rights for safe food, is called upon to ban hazardous pesticides-except those of WHO class IV- trafficking in developing countries scoring low in an international official assessment of their pesticides lifecycle management. At the same time, global funds should support pesticides alternatives and the enhancement of the developing countries capacities for pesticides lifecycle management, which is a part of a larger global matrix in risk reduction.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dfc70992-a552-4454-83b1-fea25dd6544b', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'A Novel Single-Site Mutation in the Catalytic Domain of Protoporphyrinogen Oxidase IX (PPO) Confers Resistance to PPO-Inhibiting Herbicides', 'Rangani G, Salas-Perez RA, Aponte RA, Knapp M, Craig IR, Mietzner T, Langaro AC, Noguera MM', 2019, 'Frontiers in plant science', '10.3389/fpls.2019.00568', 'https://doi.org/10.3389/fpls.2019.00568', 'https://europepmc.org/articles/PMC6530635?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Protoporphyrinogen oxidase (PPO)-inhibiting herbicides are used to control weeds in a variety of crops. These herbicides inhibit heme and photosynthesis in plants. PPO-inhibiting herbicides are used to control Amaranthus palmeri (Palmer amaranth) especially those with resistance to glyphosate and acetolactate synthase (ALS) inhibiting herbicides. While investigating the basis of high fomesafen-resistance in A. palmeri, we identified a new amino acid substitution of glycine to alanine in the catalytic domain of PPO2 at position 399 (G399A) (numbered according to the protein sequence of A. palmeri). G399 is highly conserved in the PPO protein family across eukaryotic species. Through combined molecular, computational, and biochemical approaches, we established that PPO2 with G399A mutation has reduced affinity for several PPO-inhibiting herbicides, possibly due to steric hindrance induced by the mutation. This is the first report of a PPO2 amino acid substitution at G399 position in a field-selected weed population of A. palmeri. The mutant A. palmeri PPO2 showed high-level in vitro resistance to different PPO inhibitors relative to the wild type. The G399A mutation is very likely to confer resistance to other weed species under selection imposed by the extensive agricultural use of PPO-inhibiting herbicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('59dd98ed-31a4-458b-b298-42e186322fe0', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Acetolactate Synthase-Inhibitor Resistance in Monochoria vaginalis (Burm. f.) C. Presl from Indonesia', 'Widianto R, Kurniadie D, Widayat D, Umiyati U, Nasahi C, Sari S, Juraimi AS, Kato-Noguchi H', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11030400', 'https://doi.org/10.3390/plants11030400', 'https://europepmc.org/articles/PMC8838510?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Monochoria vaginalis (Burm. f.) C. Presl, belonging to the family Pontederiaceae, is an aquatic herbaceous plant, native to temperate and tropical Asia. The species often occurs in paddy fields as a noxious weed in East Asia, and in the USA, and causes a significant reduction in rice production. The objective of the present research was the evaluation of the resistance levels of M. vaginalis against three chemical groups of acetolactate synthase (ALS)-inhibitor herbicides and other two different groups of herbicides, and the investigation of the mutations in the ALS gene of the resistant biotype of M. vaginalis. Herbicide dose-response experiments showed that the resistant biotype of M. vaginalis was highly resistant to bensulfuron-methyl, moderately resistant to bispyribac-sodium, had low resistance to penoxsulam and 2,4-D dimethyl ammonium, and was susceptible to sulfentrazone. The nucleotide sequences of the ALS gene of resistant and susceptible biotypes showed 14 base substitutions, which caused two amino acid substitutions: Val-143-Ile and Val-148-Ile. It is the first report of the substitutions of amino acids Val-143-Ile and Val-148-Ile in ALS protein. Those mutations may give different resistance spectra against three ALS-inhibitor herbicides: bensulfuron-methyl, bispyribac-sodium, and penoxsulam. Further research is needed to elucidate the molecular basis of target-site resistance mechanisms such as the transformation of the ALS gene of M. vaginalis. It is also necessary to evaluate herbicide mixtures and/or the rotation of herbicide sites of action to control the resistant biotype of M. vaginalis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4730f2dc-6d3f-46e4-9016-922223f9aff4', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Adaptations of the Genus Bradyrhizobium to Selected Elements, Heavy Metals and Pesticides Present in the Soil Environment', 'Banasiewicz J, Gumowska A, Hołubek A, Orzechowski S', 2025, 'Current issues in molecular biology', '10.3390/cimb47030205', 'https://doi.org/10.3390/cimb47030205', 'https://europepmc.org/articles/PMC11941057?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Rhizobial bacteria perform a number of extremely important functions in the soil environment. In addition to fixing molecular nitrogen and transforming it into a form available to plants, they participate in the circulation of elements and the decomposition of complex compounds present in the soil, sometimes toxic to other organisms. This review article describes the molecular mechanisms occurring in the most diverse group of rhizobia, the genus Bradyrhizobium, allowing these bacteria to adapt to selected substances found in the soil. Firstly, the adaptation of bradyrhizobia to low and high concentrations of elements such as iron, phosphorus, sulfur, calcium and manganese was shown. Secondly, the processes activated in their cells in the presence of heavy metals such as lead, mercury and arsenic, as well as radionuclides, were described. Additionally, due to the potential use of Bradyrhziobium as biofertilizers, their response to pesticides commonly used in agriculture, such as glyphosate, sulfentrazone, chlorophenoxy herbicides, flumioxazine, imidazolinone, atrazine, and insecticides and fungicides, was also discussed. The paper shows the great genetic diversity of bradyrhizobia in terms of adapting to variable environmental conditions present in the soil.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fcecf9c5-b6ff-46b6-86b1-3b092156990a', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'An update of the Worldwide Integrated Assessment (WIA) on systemic insecticides. Part 1: new molecules, metabolism, fate, and transport', 'Giorio C, Safer A, Sánchez-Bayo F, Tapparo A, Lentola A, Girolami V, van Lexmond MB, Bonmatin JM', 2021, 'Environmental science and pollution research international', '10.1007/s11356-017-0394-3', 'https://doi.org/10.1007/s11356-017-0394-3', 'https://europepmc.org/articles/PMC7920890?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'cc by', 'With the exponential number of published data on neonicotinoids and fipronil during the last decade, an updated review of literature has been conducted in three parts. The present part focuses on gaps of knowledge that have been addressed after publication of the Worldwide Integrated Assessment (WIA) on systemic insecticides in 2015. More specifically, new data on the mode of action and metabolism of neonicotinoids and fipronil, and their toxicity to invertebrates and vertebrates, were obtained. We included the newly detected synergistic effects and/or interactions of these systemic insecticides with other insecticides, fungicides, herbicides, adjuvants, honeybee viruses, and parasites of honeybees. New studies have also investigated the contamination of all environmental compartments (air and dust, soil, water, sediments, and plants) as well as bees and apicultural products, food and beverages, and the exposure of invertebrates and vertebrates to such contaminants. Finally, we review new publications on remediation of neonicotinoids and fipronil, especially in water systems. Conclusions of the previous WIA in 2015 are reinforced; neonicotinoids and fipronil represent a major threat worldwide for biodiversity, ecosystems, and all the services the latter provide.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('69c4118c-b44b-4ac3-97d7-b7a4e0ced68e', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Carfentrazone-ethyl resistance in an Amaranthus tuberculatus population is not mediated by amino acid alterations in the PPO2 protein', 'Obenland OA, Ma R, O''Brien SR, Lygin AV, Riechers DE', 2019, 'PloS one', '10.1371/journal.pone.0215431', 'https://doi.org/10.1371/journal.pone.0215431', 'https://europepmc.org/articles/PMC6464220?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'To date, the only known mechanism conferring protoporphyrinogen IX oxidase (PPO)-inhibitor resistance in waterhemp (Amaranthus tuberculatus) is a glycine deletion in PPO2 (ΔG210), which results in cross-resistance to foliar PPO-inhibiting herbicides. However, a metabolism-based, HPPD-inhibitor resistant waterhemp population from Illinois (named SIR) was suspected of having a non-target site resistance (NTSR) mechanism due to its resistance to carfentrazone-ethyl (CE) but sensitivity to diphenylethers (DPEs). In greenhouse experiments, SIR sustained less injury than two PPO inhibitor-sensitive populations (WCS and SEN) after applying a field-use rate of CE, and after initial rapid necrosis, regrowth of SIR plants was comparable to a known PPO inhibitor-resistant population (ACR) possessing the ΔG210 mutation. Dose-response analysis determined 50% growth reduction rates in CE-resistant (SIR and ACR) and sensitive (SEN) waterhemp populations, which showed SIR was 30-fold resistant compared to SEN and two-fold more resistant than ACR. Deduced amino acid sequences derived from SIR PPX2 partial cDNAs did not contain the ΔG210 mutation found in ACR or other target-site mutations that confer PPO-inhibitor resistance previously reported in Palmer amaranth (Amaranthus palmeri). Although several SIR cDNAs contained amino acid substitutions, none were uniform among samples. Additionally, SIR plants treated with malathion and CE showed a significant reduction in biomass accumulation compared to CE alone. These results indicate robust CE resistance in SIR is not mediated by amino acid changes in the PPO2 protein, but instead resistance may be conferred through a NTSR mechanism such as enhanced herbicide metabolism.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8e04088c-d3ee-48e8-a4a2-6c2269c1fe31', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Confirmation of herbicide resistance mutations Trp574Leu, ΔG210, and EPSPS gene amplification and control of multiple herbicide-resistant Palmer amaranth (Amaranthus palmeri) with chlorimuron-ethyl, fomesafen, and glyphosate', 'Spaunhorst DJ, Nie H, Todd JR, Young JM, Young BG, Johnson WG', 2019, 'PloS one', '10.1371/journal.pone.0214458', 'https://doi.org/10.1371/journal.pone.0214458', 'https://europepmc.org/articles/PMC6435131?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc0', 'Herbicide-resistant weeds, especially Palmer amaranth (Amaranthus palmeri S. Watson), are problematic in row-crop producing areas of the United States. The objectives of this study were to determine if chlorimuron-ethyl, fomesafen, and glyphosate applied separately and in mixtures control A. palmeri and confirm the presence of various genotypes surviving two- and three-way herbicide mixtures. Fifteen percent of A. palmeri treated with the three-way herbicide mixture survived. Mixing fomesafen with chlorimuron-ethyl or fomesafen with glyphosate to create a two-way mixture reduced A. palmeri survival 22 to 24% and 60 to 62% more than glyphosate and chlorimuron-ethyl alone, respectively. Previously characterized mutations associated with A. palmeri survival to chlorimuron-ethyl, fomesafen, and glyphosate Trp574Leu, a missing glycine codon at position 210 of the PPX2L gene (ΔG210), and 5-enolpyruvylshikimate-3-phosphase synthase (EPSPS) gene amplification; respectively, were present in surviving plants. However, 37% of plants treated with chlorimuron-ethyl did not contain heterozygous or homozygous alleles for the Trp574Leu mutation, suggesting alternative genotypes contributed to plant survival. All surviving A. palmeri treated with fomesafen or glyphosate possessed genotypes previously documented to confer resistance. Indiana soybean [Glycine max (L.) Merr] fields infested with A. palmeri possessed diverse genotypes and herbicide surviving plants are likely to produce seed and spread if alternative control measures are not implemented.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ccae9c8-cd78-412d-92d1-9ec7a51ae128', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Control of Glyphosate-Resistant Common Ragweed (Ambrosia artemisiifolia L.) in Glufosinate-Resistant Soybean [Glycine max (L.) Merr]', 'Barnes ER, Knezevic SZ, Sikkema PH, Lindquist JL, Jhala AJ', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.01455', 'https://doi.org/10.3389/fpls.2017.01455', 'https://europepmc.org/articles/PMC5563374?pdf=render', NULL, NULL, 11, NULL, 'northern_plains', 3, 'cc by', 'Common ragweed emerges early in the season in Nebraska, USA and is competitive with soybean; therefore, preplant herbicides are important for effective control. Glyphosate has been used as a preplant control option; however, confirmation of glyphosate-resistant (GR) common ragweed in Nebraska necessitates evaluating other herbicide options. The objectives of this study were to (1) evaluate the efficacy of preplant (PP) herbicides followed by (fb) glufosinate alone or in tank-mixture with imazethapyr, acetochlor, or S-metolachlor applied post-emergence (POST) for control of GR common ragweed in glufosinate-resistant soybean; (2) their effect on common ragweed density, biomass, and soybean yield; and (3) the partial economics of herbicide programs. A field experiment was conducted in a grower''s field infested with GR common ragweed in Gage County, Nebraska, USA in 2015 and 2016. Preplant herbicide programs containing glufosinate, paraquat, 2,4-D, dimethenamid-P, cloransulam-methyl, or high rates of flumioxazin plus chlorimuron-ethyl provided 90-99% control of common ragweed at 21 d after treatment (DAT). The aforementioned PP herbicides fb a POST application of glufosinate alone or in tank-mixture with imazethapyr, acetochlor, or S-metolachlor controlled GR common ragweed 84-98% at soybean harvest, reduced common ragweed density (≤20 plants m-2) and biomass by ≥93%, and secured soybean yield 1,819-2,158 kg ha-1. The PP fb POST herbicide programs resulted in the highest gross profit margins (US$373-US$506) compared to PP alone (US$91) or PRE fb POST programs (US$158). The results of this study conclude that effective and economical control of GR common ragweed in glufosinate-resistant soybean is achievable with PP fb POST herbicide programs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('829bba69-0ba2-46fc-a009-adce479aa468', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Do Traits Travel? Multiple-Herbicide-Resistant A. tuberculatus, an Alien Weed Species in Israel', 'Roth IS, Singer A, Yadid I, Sibony M, Peleg Z, Rubin B', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12234002', 'https://doi.org/10.3390/plants12234002', 'https://europepmc.org/articles/PMC10708328?pdf=render', NULL, NULL, 17, NULL, 'canada', 3, 'cc by', 'Amaranthus tuberculatus is the most common weed in soybean and corn in the USA and Canada. In Israel, it has been a minor riverbank weed. However, in recent years, growing densities of this plant have been observed in field crops, orchards, and roadsides. Between 2017 and 2022, we surveyed the distribution of A. tuberculatus and collected seeds for further study. We identified three main distribution zones in Israel: the Jezreel Valley, Hula Valley, and Coastal Plain. Most of the populations were found near water sources, fishponds, barns, dairies, or bird-feeding sites, suggesting the involvement of imported grain in introducing A. tuberculatus to Israel. Populations were screened for their responses to various post-emergence herbicides (i.e., ALS, EPSPS, PPO, HPPD, and PSII inhibitors). Several populations from the Jezreel Valley were found to be putatively resistant to ALS, EPSPS, and PPO inhibitors. The responses of those populations to trifloxysulfuron, glyphosate, and carfentrazone-ethyl were also studied. A single ALS-, EPSPS- and PPO-resistant plant was vegetatively propagated to create a clonal population, which was treated with foramsulfuron, glyphosate, and carfentrazone-ethyl. No resistance to PSII or HPPD inhibitors was observed, but resistance to herbicides that inhibit ALS, EPSPS, and PPO was observed. A clonal propagation assay revealed the existence of a population that was resistant to ALS, EPSPS, and PPO inhibitors. Since the local A. tuberculatus populations have not been exposed to herbicide selection pressure, these traits probably reached Israel through seed-mediated gene flow via imported grain.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e269dbb1-901a-4d0f-9773-ddb6d327d572', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Fungicides: An Overlooked Pesticide Class?', 'Zubrod JP, Bundschuh M, Arts G, Brühl CA, Imfeld G, Knäbel A, Payraudeau S, Rasmussen JJ', 2019, 'Environmental science & technology', '10.1021/acs.est.8b04392', 'https://doi.org/10.1021/acs.est.8b04392', 'https://europepmc.org/articles/PMC6536136?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'open access (Europe PMC)', 'Fungicides are indispensable to global food security and their use is forecasted to intensify. Fungicides can reach aquatic ecosystems and occur in surface water bodies in agricultural catchments throughout the entire growing season due to their frequent, prophylactic application. However, in comparison to herbicides and insecticides, the exposure to and effects of fungicides have received less attention. We provide an overview of the risk of fungicides to aquatic ecosystems covering fungicide exposure (i.e., environmental fate, exposure modeling, and mitigation measures) as well as direct and indirect effects of fungicides on microorganisms, macrophytes, invertebrates, and vertebrates. We show that fungicides occur widely in aquatic systems, that the accuracy of predicted environmental concentrations is debatable, and that fungicide exposure can be effectively mitigated. We additionally demonstrate that fungicides can be highly toxic to a broad range of organisms and can pose a risk to aquatic biota. Finally, we outline central research gaps that currently challenge our ability to predict fungicide exposure and effects, promising research avenues, and shortcomings of the current environmental risk assessment for fungicides.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bc269ee3-1d81-422b-8020-d872b74e2f00', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Does exposure to PPO-inhibiting herbicides alter the male-to-female sex ratio of Palmer amaranth?', 'Mafia M. Rumpa, Sirwan Babaei, Ronald F. Krausz, David J. Gibson, Eric J. Miller, Karla L. Gage', 2025, 'Weed Technology', '10.1017/wet.2025.24', 'https://doi.org/10.1017/wet.2025.24', 'https://www.cambridge.org/core/product/identifier/S0890037X25000247/type/journal_article', NULL, NULL, 12, NULL, 'other', 1, 'open access (DOAJ)', 'Palmer amaranth, a competitive weed in cotton and soybeans, poses challenges due to its rapid growth, high fertility, and herbicide resistance. Effective management strategies targeting sex ratios could reduce seed production by female plants. Protoporphyrinogen oxidase (PPO-) inhibiting herbicides play a role in the evolving resistance of Amaranthus spp. in the US Midwest. These herbicides may also affect the male-to-female ratio of Palmer amaranth. A 2-yr field experiment (2015 and 2016) was conducted in a soybean field in Collinsville, IL, evaluating various preemergence and postemergence PPO-inhibiting herbicide treatments. Untreated Palmer amaranth populations exhibited a bias toward females. Preemergence application of sulfentrazone and flumioxazin effectively reduced Palmer amaranth density (1.66 plants m–2) throughout the season, whereas postemergence applications of fomesafen and lactofen provided limited control (27 and 31 plants m–2, respectively). Early-season mortality was high (96%) among Palmer amaranth seedlings, especially with pyroxasulfone + fluthiacet-methyl treatment. Fomesafen increased female biomass (28.8%) while reducing male biomass compared to the nontreated control. In 2015, pyroxasulfone + fluthiacet-methyl and acetochlor altered the male-to-female sex ratio compared to the nontreated control, with pyroxasulfone + fluthiacet-methyl reducing the proportion of females (–0.11 M/F) and acetochlor slightly increasing the proportion of males (0.03 M/F), though not different from a 1:1 ratio. In 2016, pendimethalin and flumioxazin (71 g ai ha–1) resulted in a strong female-biased sex ratio, with an almost exclusively female population. In both years, the nontreated control plots (–0.58 and –0.55 M/F) maintained a naturally female-biased sex ratio, deviating significantly from a 1:1 ratio. These findings suggest that specific herbicide treatments can alter the sex ratio. Understanding sex determination in Palmer amaranth holds promise for developing more effective control strategies in the future.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f647c7ad-28c2-45a4-a01d-95ef1ebcea84', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Environmental impacts of genetically modified (GM) crop use 1996-2014: Impacts on pesticide use and carbon emissions', 'Brookes G, Barfoot P', 2016, 'GM crops & food', '10.1080/21645698.2016.1192754', 'https://doi.org/10.1080/21645698.2016.1192754', 'https://europepmc.org/articles/PMC5033163?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'cc by-nc', 'This paper updates previous assessments of important environmental impacts associated with using crop biotechnology in global agriculture. It focuses on the environmental impacts associated with changes in pesticide use and greenhouse gas emissions arising from the use of GM crops since their first widespread commercial use in the mid 1990s. The adoption of GM insect resistant and herbicide tolerant technology has reduced pesticide spraying by 581.4 million kg (-8.2%) and, as a result, decreased the environmental impact associated with herbicide and insecticide use on these crops (as measured by the indicator, the Environmental Impact Quotient [EIQ]) by18.5%. The technology has also facilitated important cuts in fuel use and tillage changes, resulting in a significant reduction in the release of greenhouse gas emissions from the GM cropping area. In 2014, this was equivalent to removing nearly 10 million cars from the roads.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b67e4255-1488-40a1-b5d5-c619f426001a', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Fendioxypyracil, a new and systemic PPO-inhibiting herbicide for X-spectrum weed control', 'Seiser T, Porri A, Johnen P, Zeyer S, Wahrheit J, Betz M, Vandenberghe B, Asher S', 2026, 'Pest management science', '10.1002/ps.70763', 'https://doi.org/10.1002/ps.70763', 'https://europepmc.org/articles/PMC13240683?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'BackgroundFendioxypyracil is a new protoporphyrinogen oxidase (PPO; HRAC Group 14)-inhibiting herbicide developed to expand post-emergence weed control options. The compound combines a pyridine-based core with an aryloxy side chain, resulting in high biological activity. Physiological profiling and enzyme assays confirmed PPO inhibition as its mode of action, with strong inhibition of both PPO1 and PPO2 from Amaranthus tuberculatus and higher potency than saflufenacil, particularly against PPO2. Greenhouse and field studies demonstrated broad-spectrum efficacy against major broadleaf and grass weeds at low use rates. These results indicate that fendioxypyracil represents a valuable new PPO inhibitor for integrated weed management.ResultsGreenhouse evaluations demonstrated high efficacy of fendioxypyracil against key grass weeds, including wild oat (Avena fatua), crabrass (Digitaria Sanginalis), goosegrass (Eleusina indica) and barnyard grass (Echinochloa crus-galli), as well as strong control of major broadleaf species. Physiological characterization and enzyme inhibition assays confirmed PPO as the primary site and mode of action, with IC₅₀ values lower than those of the commercial standard saflufenacil for both PPO isoforms.ConclusionFendioxypyracil represents a next-generation PPO inhibitor with broad-spectrum and systemic activity, offering a valuable new tool for integrated weed management. Its high biological activity and efficacy across multiple weed taxa supports its potential to enhance on-farm weed control strategies and contributes to resistance management programs. © 2026 The Author(s). Pest Management Science published by John Wiley & Sons Ltd on behalf of Society of Chemical Industry.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e8900ba8-258d-4aa3-bc07-cb0864bf691d', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Field-Evolved ΔG210-ppo2 from Palmer Amaranth Confers Pre-emergence Tolerance to PPO-Inhibitors in Rice and Arabidopsis', 'Carvalho-Moore P, Rangani G, Langaro AC, Srivastava V, Porri A, Bowe SJ, Lerchl J, Roma-Burgos N', 2022, 'Genes', '10.3390/genes13061044', 'https://doi.org/10.3390/genes13061044', 'https://europepmc.org/articles/PMC9222656?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Resistance to protoporphyrinogen IX oxidase (PPO)-inhibitors in Amaranthus palmeri and Amaranthus tuberculatus is mainly contributed by mutations in the PPO enzyme, which renders herbicide molecules ineffective. The deletion of glycine210 (ΔG210) is the most predominant PPO mutation. ΔG210-ppo2 is overexpressed in rice (Oryza sativa c. ‘Nipponbare’) and Arabidopsis thaliana (Col-0). A foliar assay was conducted on transgenic T1 rice plants with 2× dose of fomesafen (780 g ha−1), showing less injury than the non-transgenic (WT) plants. A soil-based assay conducted with T2 rice seeds confirmed tolerance to fomesafen applied pre-emergence. In agar medium, root growth of WT rice seedlings was inhibited >90% at 5 µM fomesafen, while root growth of T2 seedlings was inhibited by 50% at 45 µM fomesafen. The presence and expression of the transgene were confirmed in the T2 rice survivors of soil-applied fomesafen. A soil-based assay was also conducted with transgenic A. thaliana expressing ΔG210-ppo2 which confirmed tolerance to the pre-emergence application of fomesafen and saflufenacil. The expression of A. palmeri ΔG210-ppo2 successfully conferred tolerance to soil-applied fomesafen in rice and Arabidopsis. This mutant also confers cross-tolerance to saflufenacil in Arabidopsis. This trait could be introduced into high-value crops that lack chemical options for weed management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f459f0e-d39c-4d2f-b604-e4b4130823ee', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Genetic variation associated with PPO-inhibiting herbicide tolerance in sorghum', 'Adhikari P, Goodrich E, Fernandes SB, Lipka AE, Tranel P, Brown P, Jamann TM', 2020, 'PloS one', '10.1371/journal.pone.0233254', 'https://doi.org/10.1371/journal.pone.0233254', 'https://europepmc.org/articles/PMC7556536?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Herbicide application is crucial for weed management in most crop production systems, but for sorghum herbicide options are limited. Sorghum is sensitive to residual protoporphyrinogen oxidase (PPO)-inhibiting herbicides, such as fomesafen, and a long re-entry period is required before sorghum can be planted after its application. Improving sorghum for tolerance to such residual herbicides would allow for increased sorghum production and the expansion of herbicide options for growers. In this study, we observed sorghum tolerance to residual fomesafen. To investigate the underlying tolerance mechanism a genome-wide association mapping study was conducted using field-collected sorghum biomass panel (SBP) data, and a greenhouse assay was developed to confirm the field phenotypes. A total of 26 significant SNPs (FDR<0.05), spanning a 215.3 kb region on chromosome 3, were detected. The ten most significant SNPs included two in genic regions (Sobic.003G136800, and Sobic.003G136900) and eight SNPs in the intergenic region encompassing the genes Sobic.003G136700, Sobic.003G136800, Sobic.003G137000, Sobic.003G136900, and Sobic.003G137100. The gene Sobic.003G137100 (PPXI), which encodes the PPO1 enzyme, one of the targets of PPO-inhibiting herbicides, was located 12kb downstream of the significant SNP S03_13152838. We found that PPXI is highly conserved in sorghum and expression does not significantly differ between tolerant and sensitive sorghum lines. Our results suggest that PPXI most likely does not underlie the observed herbicide tolerance. Instead, the mechanism underlying herbicide tolerance in the SBP is likely metabolism-based resistance, possibly regulated by the action of multiple genes. Further research is necessary to confirm candidate genes and their functions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c0bca19-9baf-4bc6-a84f-4f4410a97b1a', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Guard-cell-targeted overexpression of Arabidopsis Hexokinase 1 can improve water use efficiency in field-grown tobacco plants', 'Acevedo-Siaca LG, Głowacka K, Driever SM, Salesse-Smith CE, Lugassi N, Granot D, Long SP, Kromdijk J', 2022, 'Journal of experimental botany', '10.1093/jxb/erac218', 'https://doi.org/10.1093/jxb/erac218', 'https://europepmc.org/articles/PMC9467653?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Water deficit currently acts as one of the largest limiting factors for agricultural productivity worldwide. Additionally, limitation by water scarcity is projected to continue in the future with the further onset of effects of global climate change. As a result, it is critical to develop or breed for crops that have increased water use efficiency and that are more capable of coping with water scarce conditions. However, increased intrinsic water use efficiency (iWUE) typically brings a trade-off with CO2 assimilation as all gas exchange is mediated by stomata, through which CO2 enters the leaf while water vapor exits. Previously, promising results were shown using guard-cell-targeted overexpression of hexokinase to increase iWUE without incurring a penalty in photosynthetic rates or biomass production. Here, two homozygous transgenic tobacco (Nicotiana tabacum) lines expressing Arabidopsis Hexokinase 1 (AtHXK1) constitutively (35SHXK2 and 35SHXK5) and a line that had guard-cell-targeted overexpression of AtHXK1 (GCHXK2) were evaluated relative to wild type for traits related to photosynthesis and yield. In this study, iWUE was significantly higher in GCHXK2 compared with wild type without negatively impacting CO2 assimilation, although results were dependent upon leaf age and proximity of precipitation event to gas exchange measurement.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7d08b7a2-1f05-4d9e-9712-a718989fe103', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'High Add Valued Application of Turpentine in Crop Production through Structural Modification and QSAR Analysis', 'Gao Y, Li J, Li J, Song Z, Shang S, Rao X', 2018, 'Molecules (Basel, Switzerland)', '10.3390/molecules23020356', 'https://doi.org/10.3390/molecules23020356', 'https://europepmc.org/articles/PMC6017721?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Turpentine is a volatile component of resin, which is an abundant forest resource in Southern China. As one of the most important components, the integrated application of β-pinene has been studied. The broad-spectrum evaluation of β-pinene and its analogues has, therefore, been necessary. In an attempt to expand the scope of agro-activity trials, the preparation and the evaluation of the herbicidal activity of a series of β-pinene analogues against three agricultural herbs were carried out. In accordance with the overall herbicidal activity, it is noteworthy that compounds 6k, 6l, and 6m demonstrated extreme activity with IC50 values of 0.065, 0.065, and 0.052 mol active ingredients/hectare against E. crus-galli. The preliminary structure-activity relationship (SAR) was analyzed and the compounds with the appropriate volatility and substituent type that had beneficial herbicidal activity were analyzed. Simultaneously, the quantitative structure-activity relationship (QSAR) model was built and the most important structural features were indicated, which was, to a certain extent, in line with the SAR study. The study aimed to study the application of the forest resource turpentine in agriculture as a potential and alternative approach for comprehensive utilization.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5d160b5d-9546-4bca-b4b7-671ca32c8740', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Meta-GWAS for quantitative trait loci identification in soybean', 'Shook JM, Zhang J, Jones SE, Singh A, Diers BW, Singh AK', 2021, 'G3 (Bethesda, Md.)', '10.1093/g3journal/jkab117', 'https://doi.org/10.1093/g3journal/jkab117', 'https://europepmc.org/articles/PMC8495947?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by-nc-nd', 'We report a meta-Genome Wide Association Study involving 73 published studies in soybean [Glycine max L. (Merr.)] covering 17,556 unique accessions, with improved statistical power for robust detection of loci associated with a broad range of traits. De novo GWAS and meta-analysis were conducted for composition traits including fatty acid and amino acid composition traits, disease resistance traits, and agronomic traits including seed yield, plant height, stem lodging, seed weight, seed mottling, seed quality, flowering timing, and pod shattering. To examine differences in detectability and test statistical power between single- and multi-environment GWAS, comparison of meta-GWAS results to those from the constituent experiments were performed. Using meta-GWAS analysis and the analysis of individual studies, we report 483 peaks at 393 unique loci. Using stringent criteria to detect significant marker-trait associations, 59 candidate genes were identified, including 17 agronomic traits loci, 19 for seed-related traits, and 33 for disease reaction traits. This study identified potentially valuable candidate genes that affect multiple traits. The success in narrowing down the genomic region for some loci through overlapping mapping results of multiple studies is a promising avenue for community-based studies and plant breeding applications.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ab01d62b-6eb7-4464-a8e3-9a34f3ff9b1c', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Multiple Genomic Regions Govern Tolerance to Sulfentrazone in Snap Bean (Phaseolus Vulgaris L.)', 'Ana Saballos, Alvaro Soler-Garzón, Matthew Brooks, John Patrick Hart, Alexander Edward Lipka, Philip Miklas, Ronald Edward Peachey, Patrick J. Tranel', 2022, 'Frontiers in Agronomy', '10.3389/fagro.2022.869770', 'https://doi.org/10.3389/fagro.2022.869770', 'https://www.frontiersin.org/articles/10.3389/fagro.2022.869770/full', NULL, NULL, 15, NULL, 'other', 1, 'open access (DOAJ)', 'The availability of effective weed management tools against waterhemp (Amaranthus tuberculatus) is crucial to maintain profitable production of snap bean (Phaseolus vulgaris L.). Preemergence herbicides enable the crop to gain a size advantage over the weed, but the few preemergence herbicides registered in snap bean have poor control of waterhemp. Sulfentrazone, a protoporphyrinogen oxidase (PPO) -inhibiting herbicide, provides significant control of waterhemp and other problematic weeds. However, crop tolerance to the herbicide is poorly known. To quantify snap bean tolerance to sulfentrazone and investigate the underlying tolerance mechanism(s), a genome-wide association mapping study was conducted using field-collected data on a snap bean diversity panel. Response to a preemergence application of sulfentrazone was measured using plant population density and shoot biomass variables. High levels of crop tolerance were found in several entries including Bush Romano 71, Navarro, and Flamata. Snap bean tolerance to sulfentrazone is associated with multiple genomic regions, indicating the trait is likely a non-target site resistance (NTSR). Seed size is partially responsible for the tolerance, thus the genetic factors conditioning sulfentrazone tolerance are likely a combination of those driven indirectly by seed size/weight and those acting directly on the metabolism of the herbicide or ameliorating its damage. In this study, several cytochrome P450 and ABC transporter genes were localized in associated genomic regions. Alleles conditioning snap bean tolerance to sulfentrazone identified in the diversity panel shed light on herbicide metabolism and could be used in snap bean improvement.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('22f09dfb-c0ea-4d72-8f61-f0fcf7eb2a63', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Persistence of sulfentrazone in soil under soybean and its carryover effect on bioindicators', 'R. Rama Praba Nalini, P. Janaki, M. Balusamy, C. Chinnusamy', 2017, 'Acta Agriculturae Scandinavica. Section B, Soil and Plant Science', '10.1080/09064710.2016.1246670', 'https://doi.org/10.1080/09064710.2016.1246670', 'http://dx.doi.org/10.1080/09064710.2016.1246670', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'To assess the persistence and dissipation kinetics of sulfentrazone in soil, terminal residues in soybean and carryover effect on bioindicator species, field experiment was carried out under Indian tropical conditions. The sulfentrazone was applied at 360, 480 and 720 g a.i. ha−1 rates as pre-emergence herbicide. Its residues in soil and in soybean at harvest were analyzed by high pressure liquid chromatography. Results showed that the sulfentrazone dissipation in soil followed first-order reaction kinetics with the half-lives of 5.5 to 14.8 days. Terminal residue in shoot and grain showed that sulfentazone at 360 g ha−1 can be safely applied for weed control in soybean since there was no phytotoxicity injury to the crop. The residue in soybean grain was within the safe limits (0.05 µg g−1) as proposed by US. However, the detection of sulfentrazone residue in soil at harvest and carryover injury to bioindicator signified the risk for crops in succession. Hence the use of this herbicide in soil with low organic matter and coarse texture is questionable as it is highly mobile. Further biomagnifications of sulfentrazone residue in soil and crop produce under continuous use and interaction of climatic variables and soil properties on its persistence, sorption and leaching behavior need to be investigated.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa6273a9-4ceb-4d28-8c02-c3a26d53627b', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Rainfall affects leaching of pre-emergent herbicide from wheat residue into the soil', 'Khalil Y, Flower K, Siddique KHM, Ward P', 2019, 'PloS one', '10.1371/journal.pone.0210219', 'https://doi.org/10.1371/journal.pone.0210219', 'https://europepmc.org/articles/PMC6358059?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'No-tillage with stubble retention is a widely used cropping system for its conservation and yield benefits. The no-tillage farming system in southern Australia relies heavily on herbicides for weed management, but heavy crop residues may have a negative impact on the activity of pre-emergent herbicides applied. Any herbicide intercepted by the crop residue may not reach the soil surface without timely rainfall and may dissipate due to volatilisation, photo-degradation and/or microbial activity. Two experiments were carried out to investigate the interception of prosulfocarb, pyroxasulfone, and trifluralin herbicides by wheat residue and retention following simulated rainfall. For the first experiment, there were four simulated rainfall amounts (0, 5, 10, and 20 mm), three intensities (5, 10, and 20 mm h-1) and five application times (immediately after spraying herbicide, 6 h, 1, 7, and 14 days after spraying). In the second experiment, 20 mm of rainfall was applied at 10 mm h-1 in either 4 × 5 mm rainfall events over two days, 2 × 10 mm rainfall events over one day, or a single 20 mm rainfall event, with a no-rainfall control treatment. Bioassays were used to assess the herbicide activity/availability in the soil and remaining on the residue, using cucumber (Cucumis sativus L.) and Italian ryegrass (Lolium multiflorum Lam.) as indicator plants. At higher rainfall amounts, most of the herbicide leached from the stubble into the soil soon after application; more so with rain in one event rather than multiple events. However, the intensity of rainfall had no effect. Pyroxasulfone leached easily from the residue to the soil to potentially offer good weed control, prosulfocarb had an intermediary leaching effect, while only a small amount of trifluralin leached from stubble after rain. Therefore, in no-tillage situations with large amounts of crop residue present on the soil surface, herbicides that leach easily from the residue should be considered, like pyroxasulfone.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9f289dc1-63ef-46f0-ab19-5aed252ed8f8', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Rapid Resistance Detection of Amaranthus retroflexus to Fomesafen via Kompetitive Allele-Specific PCR (KASP)', 'Zhang Z, Ban Y, Wei J, Wu Q, Dong L, Feng Z', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14040515', 'https://doi.org/10.3390/plants14040515', 'https://europepmc.org/articles/PMC11858902?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Amaranthus retroflexus is a highly invasive annual broadleaf weed in soybean fields, significantly reducing soybean yield and quality. Diphenyl ether herbicides, particularly fomesafen, are extensively applied to control A. retroflexus. Fomesafen resistance of A. retroflexus is emerging in Northeast China, and rapid resistance detection is urgent for managing these resistant weeds. An Arg-128-Gly mutation in the ppo2 gene of A. retroflexus has been shown to confer fomesafen resistance. In current study, we developed a rapid detection method based on Kompetitive Allele-Specific PCR (KASP) technology to detect the Arg-128-Gly mutation in the ppo2 gene of A. retroflexus. Initially, we developed this KASP detection method using cDNA as the template; however, the entire process requires significant costs and considerable operational time. To mitigate these expenses and simplify the workflow, we subsequently optimized this KASP rapid detection method by utilizing genomic DNA as the template. This new resistance detection technique directly utilizes A. retroflexus genomic DNA as the template, and, by adding specific labelled primers, probes, and enzymes, it can determine whether the ppo2 gene harbors an Arg-128-Gly mutation, thereby rapidly identifying fomesafen resistance in A. retroflexus. Furthermore, we compared the detection efficiency of the new KASP assay, whole plant dose-response assay, and DNA sequencing, all of which produced consistent outcomes, supporting the accuracy and reliability of the KASP rapid detection method. Collectively, we established a rapid resistance detection method based on KASP technology, which is of high reliability and time-saving, and will significantly advance precise management of resistant weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c5db2443-ab3a-455e-bc18-5d06d0cb8cba', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Residual herbicides in weed management for glyphosate-resistant soybean in Brazil', 'R.F. Lopes Ovejero, D.J. Soares, W.S. Oliveira, L.B. Fonseca, G.U. Berger, J.K. Soteres, P.J. Christoffoleti', 2013, 'Planta Daninha', NULL, 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-83582013000400021&tlng=en', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-83582013000400021&tlng=en', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'In agricultural production systems where the glyphosate-resistant soybean crop (Glycine max) is grown and the practice of crop rotation with alternative herbicides is not adopted, the exclusive and continuous use of glyphosate has led to the occurrence of resistant weed populations that may limit or compromise the benefits of this technology. Thus, the efficacy of weed management programs, including the use of residual herbicides (sulfentrazone, flumioxazin, imazethapyr, diclosulan, chlorimuron and s-metolachlor) applied in preemergence and followed by in-crop postemergence applications of glyphosate (PRE-POST) were compared to glyphosate postemergence only programs - POST. The study was conducted across nine locations during the 2009/2010 and 2010/2011 growing seasons. PRE-POST programs were efficient in the control of Amaranthus viridis, Brachiaria plantaginea, Bidens pilosa, Commelina benghalensis, Eleusine indica, Euphorbia heterophylla and Raphanus raphanistrum, with the level of control being similar when comparing the program with two applications of glyphosate POST. Some PRE-POST programs were not efficient in controlling Cenchrus echinatus, Ipomoea hederifolia and Ipomoea triloba. Sulfentrazone and diclosulam PRE-POST programs improved the control of Ipomoea triloba compared to sequential applications of glyphosate alone. No significant differences in soybean yield were observed between any of the herbicide treatments or study locations. The use of residual herbicides in preemergence followed by glyphosate in-crop postemergence provides consistent weed control and reducing early season weed competition. Furthermore, these programs utilize at least two herbicide modes of action for herbicide use diversity, which will be needed to stay ahead of resistance build-up, regardless of when weeds may appear.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ba560983-613e-49dd-9190-ea714303465d', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Response of seven turfgrass species to pyridate', 'Bret Corbett, Samuel E. Crawford, Navdeep Godara, Shawn Dale Askew', 2026, 'Weed Technology', '10.1017/wet.2026.10112', 'https://doi.org/10.1017/wet.2026.10112', 'https://www.cambridge.org/core/product/identifier/S0890037X26101122/type/journal_article', NULL, NULL, 5, NULL, 'other', 1, 'open access (DOAJ)', 'Pyridate, a photosystem II–inhibiting herbicide used since the 1980s on corn, cereal, and sorghum crops, shows promise for controlling weeds of turfgrass; however, whether it is safe to use it on turfgrass species remains untested. This study evaluated pyridate’s effects on visible injury, green cover, and dark green color index (DGCI) for eight weekly assessments on seven turfgrass species, including hybrid bermudagrass, creeping bentgrass, fine fescue, Kentucky bluegrass, perennial ryegrass, tall fescue, and zoysiagrass. Fourteen field experiments were conducted in 2024 using a randomized complete block design with four replications, testing pyridate at 350, 700, and 1,400 g ae ha−1 alone or combined with sulfentrazone (280 or 560 g ae ha−1). Results showed significant injury at 7 d after treatment (DAT) to all turf species (P ≤ 0.0163), peaking at 35% for bermudagrass with the high pyridate–sulfentrazone mix under warm, moist conditions, but dissipating by 14 DAT. Green cover decreased most (52%) with the high mix in Trial 2 with bermudagrass, while plots treated with pyridate at ≤700 g ha−1 matched that of nontreated cover. The DGCI mirrored injury trends, with minimal impact from pyridate at 350 g ha−1. Pyridate’s safety aligns with its metabolic detoxification by grasses, unlike broadleaf plants, while sulfentrazone exacerbated damage, which is consistent with prior turfgrass studies. At ≤700 g ha−1, pyridate proved to be safe to all species, suggesting its potential use for selective weed control in turfgrass systems. Higher rates or sulfentrazone mixes require caution due to transient injury to favorable plants. Further research should optimize application conditions and target turfgrass weeds to refine pyridate’s role in integrated management amid rising herbicide resistance in turfgrass systems.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1b2b1fc9-bf8d-4823-8652-1b2aac2b711d', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Sugarcane (Saccharum X officinarum): A Reference Study for the Regulation of Genetically Modified Cultivars in Brazil', 'Cheavegatti-Gianotto A, de Abreu HM, Arruda P, Bespalhok Filho JC, Burnquist WL, Creste S, di Ciero L, Ferro JA', 2011, 'Tropical plant biology', '10.1007/s12042-011-9068-3', 'https://doi.org/10.1007/s12042-011-9068-3', 'https://europepmc.org/articles/PMC3075403?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by-nc', 'Global interest in sugarcane has increased significantly in recent years due to its economic impact on sustainable energy production. Sugarcane breeding and better agronomic practices have contributed to a huge increase in sugarcane yield in the last 30 years. Additional increases in sugarcane yield are expected to result from the use of biotechnology tools in the near future. Genetically modified (GM) sugarcane that incorporates genes to increase resistance to biotic and abiotic stresses could play a major role in achieving this goal. However, to bring GM sugarcane to the market, it is necessary to follow a regulatory process that will evaluate the environmental and health impacts of this crop. The regulatory review process is usually accomplished through a comparison of the biology and composition of the GM cultivar and a non-GM counterpart. This review intends to provide information on non-GM sugarcane biology, genetics, breeding, agronomic management, processing, products and byproducts, as well as the current technologies used to develop GM sugarcane, with the aim of assisting regulators in the decision-making process regarding the commercial release of GM sugarcane cultivars.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('39b7366d-a546-4c3d-802d-b906e71ed0e8', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'Technological Progress Toward Peanut Disease Management: A Review', 'Asif M, Rayamajhi A, Mahmud MS', 2025, 'Sensors (Basel, Switzerland)', '10.3390/s25041255', 'https://doi.org/10.3390/s25041255', 'https://europepmc.org/articles/PMC11860622?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Peanut (Arachis hypogea L.) crops in the southeastern U.S. suffer significant yield losses from diseases like leaf spot, southern blight, and stem rot. Traditionally, growers use conventional boom sprayers, which often leads to overuse and wastage of agrochemicals. However, advances in computer technologies have enabled the development of precision or variable-rate sprayers, both ground-based and drone-based, that apply agrochemicals more accurately. Historically, crop disease scouting has been labor-intensive and costly. Recent innovations in computer vision, artificial intelligence (AI), and remote sensing have transformed disease identification and scouting, making the process more efficient and economical. Over the past decade, numerous studies have focused on developing technologies for peanut disease scouting and sprayer technology. The current research trend shows significant advancements in precision spraying technologies, facilitating smart spraying capabilities. These advancements include the use of various platforms, such as ground-based and unmanned aerial vehicle (UAV)-based systems, equipped with sensors like RGB (red-blue-green), multispectral, thermal, hyperspectral, light detection and ranging (LiDAR), and other innovative detection technologies, as highlighted in this review. However, despite the availability of some commercial precision sprayers, their effectiveness is limited in managing certain peanut diseases, such as white mold, because the disease affects the roots, and the chemicals often remain in the canopy, failing to reach the soil where treatment is needed. The review concludes that further advances are necessary to develop more precise sprayers that can meet the needs of large-scale farmers and significantly enhance production outcomes. Overall, this review paper aims to provide a review of smart spraying techniques, estimating the required agrochemicals and applying them precisely in peanut fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4599c720-5636-43b7-9449-9eccf0d84ad2', '9cb79f57-fd44-40f6-acb3-0979a9e8246b', 'The validation of an analytical method for sulfentrazone residue determination in soil using liquid chromatography and a comparison of chromatographic sensitivity to millet as a bioindicator species', 'de Oliveira MA, Pires FR, Ferraço M, Belo AF', 2014, 'Molecules (Basel, Switzerland)', '10.3390/molecules190810982', 'https://doi.org/10.3390/molecules190810982', 'https://europepmc.org/articles/PMC6271746?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Commonly used herbicides, such as sulfentrazone, pose the risk of soil contamination due to their persistence, bioaccumulation and toxicity. Phytoremediation by green manure species has been tested using biomarkers, but analytical data are now required to confirm the extraction of sulfentrazone from soil. Thus, the present work was carried out to analyze sulfentrazone residues in soil based on liquid chromatography with a comparison of these values to the sensitivity of the bioindicator Pennisetum glaucum. The soil samples were obtained after cultivation of Crotalaria juncea and Canavalia ensiformis at four seeding densities and with three doses of sulfentrazone. The seedlings were collected into pots, at two different depths, after 75 days of phytoremediator sowing and then were used to determine the herbicide persistence in the soil. A bioassay with P. glaucum was carried out in the same pot. High-performance liquid chromatography (HPLC), using UV-diode array detection (HPLC/UV-DAD), was used to determine the herbicide residues. The HPLC determination was optimized and validated according to the parameters of precision, accuracy, linearity, limit of detection and quantification, robustness and specificity. The bioindicator P. glaucum was more sensitive to sulfentrazone than residue determination by HPLC. Changes in sulfentrazone concentration caused by green manure phytoremediation were accurately identified by the bioindicator. However, a true correlation between the size of the species and the analyte content was not identified.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9424a4e-86b3-495b-a4fb-f315a9f7de5d', '35083f56-3855-4792-8594-c7a405b120ba', 'Discovery and structure optimization of a novel corn herbicide, tolpyralate', 'Tsukamoto M, Kikugawa H, Nagayama S, Suganuma T, Okita T, Miyamoto H', 2021, 'Journal of pesticide science', '10.1584/jpestics.d20-031', 'https://doi.org/10.1584/jpestics.d20-031', 'https://europepmc.org/articles/PMC8175215?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by-nc-nd', 'Tolpyralate, a new selective postemergence herbicide developed for the weed control in corn, possesses a unique chemical structure with a 1-alkoxyethyl methyl carbonate group on the N-ethyl pyrazole moiety. This compound shows high herbicidal activity against many weed species, including glyphosate-resistant Amaranthus tuberculatus. Tolpyralate targets 4-hydroxyphenylpyruvate dioxygenase (4-HPPD), which is involved in the tyrosine degradation pathway. Inhibition of the enzyme destroys the chlorophyll, thereby killing the susceptible weeds. Details of tolpyralate discovery, structure optimization, and biological activities are described.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('99d612bd-6ed7-407c-92ce-37148cd9e844', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Assessing the Risk for Resistance and Elucidating the Genetics of Colletotrichum truncatum That Is Only Sensitive to Some DMI Fungicides', 'Can Zhang, Yongzhao Diao, Weizhen Wang, Jianjun Hao, Muhammad Imran, Hongxia Duan, Xili Liu', 2017, 'Frontiers in Microbiology', '10.3389/fmicb.2017.01779', 'https://doi.org/10.3389/fmicb.2017.01779', 'http://journal.frontiersin.org/article/10.3389/fmicb.2017.01779/full', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'The genus Colletotrichum contains a wide variety of important plant pathogens, and Colletotrichum truncatum is one of the most prevalent species of Colletotrichum on chili in China. Demethylation-inhibitor fungicides (DMIs) are currently registered chemical agents for the management of the anthracnose disease caused by Colletotrichum spp. To assess the risk for DMI resistance development, 112 C. truncatum isolates were collected from infected pepper in 13 regions of China. The sensitivity of C. truncatum isolates to five DMI fungicides was determined based on mycelial growth inhibition assay. C. truncatum was sensitive to prochloraz, epoxiconazole, and difenoconazole, but not to tebuconazole or myclobutanil. Baseline sensitivity using the 112 C. truncatum isolates was established for the first three effective DMIs. Prochloraz, epoxiconazole, and difenoconazole EC50 values were 0.053 ± 0.023, 1.956 ± 0.815, and 1.027 ± 0.644 μg/ml, respectively. Eleven stable DMI-resistant mutants all exhibited lower fitness levels than their wild-type parents, suggesting a low risk of DMI resistance in C. truncatum. By inducing gene expression, CtCYP51 expression increased slightly in the resistant mutants as compared to wild-types when exposed to DMI fungicides and thus contributed at least partially to resistance. Molecular docking with CYP51 structure models was used to explain differential sensitivity of the DMI fungicides in C. truncatum. Our results suggest that the M376L/H373N mutations in CYP51 changed the conformation of DMIs in the binding pocket. These changes prevented the formation of the Fe – N coordinate bond between the heme iron active site and tebuconazole or myclobutanil, and apparently contributed to tebuconazole and myclobutanil insensitivity of C. truncatum.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d7d4d3de-7249-4728-93d3-e161f1280500', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Azole Resistance in Aspergillus fumigatus: A Consequence of Antifungal Use in Agriculture?', 'Berger S, El Chazli Y, Babu AF, Coste AT', 2017, 'Frontiers in microbiology', '10.3389/fmicb.2017.01024', 'https://doi.org/10.3389/fmicb.2017.01024', 'https://europepmc.org/articles/PMC5461301?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'cc by', 'Agricultural industry uses pesticides to optimize food production for the growing human population. A major issue for crops is fungal phytopathogens, which are treated mainly with azole fungicides. Azoles are also the main medical treatment in the management of Aspergillus diseases caused by ubiquitous fungi, such as Aspergillus fumigatus. However, epidemiological research demonstrated an increasing prevalence of azole-resistant strains in A. fumigatus. The main resistance mechanism is a combination of alterations in the gene cyp51A (TR34/L98H). Surprisingly, this mutation is not only found in patients receiving long-term azole therapy for chronic aspergillosis but also in azole naïve patients. This suggests an environmental route of resistance through the exposure of azole fungicides in agriculture. In this review, we report data from several studies that strongly suggest that agricultural azoles are responsible for medical treatment failure in azole-naïve patients in clinical settings.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b5359e73-31d1-4d56-bbae-83411815f086', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Clonal expansion and emergence of environmental multiple-triazole-resistant Aspergillus fumigatus strains carrying the TR₃₄/L98H mutations in the cyp51A gene in India', 'Chowdhary A, Kathuria S, Xu J, Sharma C, Sundar G, Singh PK, Gaur SN, Hagen F', 2012, 'PloS one', '10.1371/journal.pone.0052871', 'https://doi.org/10.1371/journal.pone.0052871', 'https://europepmc.org/articles/PMC3532406?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Azole resistance is an emerging problem in Aspergillus which impacts the management of aspergillosis. Here in we report the emergence and clonal spread of resistance to triazoles in environmental Aspergillus fumigatus isolates in India. A total of 44 (7%) A. fumigatus isolates from 24 environmental samples were found to be triazole resistant. The isolation rate of resistant A. fumigatus was highest (33%) from soil of tea gardens followed by soil from flower pots of the hospital garden (20%), soil beneath cotton trees (20%), rice paddy fields (12.3%), air samples of hospital wards (7.6%) and from soil admixed with bird droppings (3.8%). These strains showed cross-resistance to voriconazole, posaconazole, itraconazole and to six triazole fungicides used extensively in agriculture. Our analyses identified that all triazole-resistant strains from India shared the same TR(34)/L98H mutation in the cyp51 gene. In contrast to the genetic uniformity of azole-resistant strains the azole-susceptible isolates from patients and environments in India were genetically very diverse. All nine loci were highly polymorphic in populations of azole-susceptible isolates from both clinical and environmental samples. Furthermore, all Indian environmental and clinical azole resistant isolates shared the same multilocus microsatellite genotype not found in any other analyzed samples, either from within India or from the Netherlands, France, Germany or China. Our population genetic analyses suggest that the Indian azole-resistant A. fumigatus genotype was likely an extremely adaptive recombinant progeny derived from a cross between an azole-resistant strain migrated from outside of India and a native azole-susceptible strain from within India, followed by mutation and then rapid dispersal through many parts of India. Our results are consistent with the hypothesis that exposure of A. fumigatus to azole fungicides in the environment causes cross-resistance to medical triazoles. The study emphasises the need of continued surveillance of resistance in environmental and clinical A. fumigatus strains.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e5147782-1201-4c8b-93a7-1d9af518dde2', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Context-Dependent Fitness Trade-Offs in Penicillium expansum Isolates Resistant to Multiple Postharvest Fungicides', 'Puglisi JT, Amiri A', 2025, 'Microorganisms', '10.3390/microorganisms13081846', 'https://doi.org/10.3390/microorganisms13081846', 'https://europepmc.org/articles/PMC12388313?pdf=render', NULL, NULL, 21, NULL, 'northern_plains', 3, 'cc by', 'Blue mold of pome fruit, caused by Penicillium expansum, is controlled through postharvest applications of thiabendazole (TBZ), pyrimethanil (PYR), and fludioxonil (FDL). However, multi-fungicide-resistant isolates have emerged in the U.S. Pacific Northwest and their impact on decay control in long-term storage is unknown. This study evaluated the fitness of P. expansum isolates sensitive to all three postharvest fungicides (wild-types) and those resistant to TBZ (single-resistant), TBZ and PYR, or PYR and FDL (dual-resistant), and triple-resistant to the three fungicides. On nutrient-poor media, resistant isolates showed reduced conidial germination, whereas no significant differences were observed in germination, mycelial growth, or sporulation between phenotypes on nutrient-rich media at 1.5 and 20 °C. Regardless of their sensitivity phenotype, FDL-resistant isolates showed increased sensitivity to osmotic and oxidative stresses. Pathogenicity and virulence were not affected by the sensitivity phenotype on apples after six months of storage at 1.5 °C. Analysis of cumulative fitness changes indicated fitness loss under low-temperature in vitro and increased fitness under fungicide selection pressure on fruit in most resistant phenotypes. Gene expression analysis showed differential regulation of fitness-related genes, with most being up-regulated by TBZ. Overall, the results suggest that resistance in P. expansum may carry context-dependent fitness penalties, especially under high-stress conditions.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('968aac06-ccb3-49a5-8603-c4cc2fca644e', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Demethylase Inhibitor Fungicide Resistance in Pyrenophora teres f. sp. teres Associated with Target Site Modification and Inducible Overexpression of Cyp51', 'Mair WJ, Deng W, Mullins JG, West S, Wang P, Besharat N, Ellwood SR, Oliver RP', 2016, 'Frontiers in microbiology', '10.3389/fmicb.2016.01279', 'https://doi.org/10.3389/fmicb.2016.01279', 'https://europepmc.org/articles/PMC4990540?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Pyrenophora teres f. sp. teres is the cause of net form of net blotch (NFNB), an economically important foliar disease in barley (Hordeum vulgare). Net and spot forms of net blotch are widely controlled using site-specific systemic fungicides. Although resistance to succinate dehydrogenase inhibitors and quinone outside inhibitors has been addressed before in net blotches, mechanisms controlling demethylation inhibitor resistance have not yet been reported at the molecular level. Here we report the isolation of strains of NFNB in Australia since 2013 resistant to a range of demethylase inhibitor fungicides. Cyp51A:KO103-A1, an allele with the mutation F489L, corresponding to the archetype F495I in Aspergillus fumigatus, was only present in resistant strains and was correlated with resistance factors to various demethylase inhibitors ranging from 1.1 for epoxiconazole to 31.7 for prochloraz. Structural in silico modeling of the sensitive and resistant CYP51A proteins docked with different demethylase inhibitor fungicides showed how the interaction of F489L within the heme cavity produced a localized constriction of the region adjacent to the docking site that is predicted to result in lower binding affinities. Resistant strains also displayed enhanced induced expression of the two Cyp51A paralogs and of Cyp51B genes. While Cyp51B was found to be constitutively expressed in the absence of fungicide, Cyp51A was only detected at extremely low levels. Under fungicide induction, expression of Cyp51B, Cyp51A2, and Cyp51A1 was shown to be 1.6-, 3,- and 5.3-fold higher, respectively in the resistant isolate compared to the wild type. These increased levels of expression were not supported by changes in the promoters of any of the three genes. The implications of these findings on demethylase inhibitor activity will require current net blotch management strategies to be reconsidered in order to avoid the development of further resistance and preserve the lifespan of fungicides in use.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9947c19e-3105-4623-9565-01afe3c6320b', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Effects of foliar fungicide on yield, micronutrients, and cadmium in grains from historical and modern hard winter wheat genotypes', 'Motta-Romero H, Niyongira F, Boehm JD Jr, Rose DJ', 2021, 'PloS one', '10.1371/journal.pone.0247809', 'https://doi.org/10.1371/journal.pone.0247809', 'https://europepmc.org/articles/PMC7932086?pdf=render', NULL, NULL, 22, NULL, 'northern_plains', 3, 'cc0', 'Plant breeding and disease management practices have increased the grain yield of hard winter wheat (Triticum aestivum L.) adapted to the Great Plains of the United States during the last century. However, the effect of genetic gains for seed yield and the application of fungicide on the micronutrient and cadmium (Cd) concentration in wheat grains is still unclear. The objectives of this study were to evaluate the effects of fungicide application on the productivity and nutritional quality of wheat cultivars representing 80 years of plant breeding efforts. Field experiments were conducted over two crop years (2017 and 2018) with eighteen hard winter wheat genotypes released between 1933 and 2013 in the presence or absence of fungicide application. For each growing season, the treatments were arranged in a split-plot design with the fungicide levels (treated and untreated) as the whole plot treatments and the genotypes as split-plot treatments in triplicate. The effects on seed yield, grain protein concentration (GPC), micronutrients, phytic acid, and Cd in grains were measured. While the yield of wheat was found to increase at annualized rates of 26.5 and 13.0 kg ha-1 yr-1 in the presence and absence of fungicide (P < 0.001), respectively, GPC (-190 and -180 mg kg-1 yr-1, P < 0.001), Fe (-35.0 and -44.0 μg kg-1 yr-1, P < 0.05), and Zn (-68.0 and -57.0 μg kg-1 yr-1, P < 0.01) significantly decreased during the period studied. In contrast to the other mineral elements, grain Cd significantly increased over time (0.4 μg kg-1 yr-1, P < 0.01) in the absence of fungicide. The results from this study are of great concern, as many mineral elements essential for human nutrition have decreased over time while the toxic heavy metal, Cd, has increased, indicating modern wheats are becoming a better vector of dietary Cd.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('10f3f24d-432d-4f83-9124-9d478dae1972', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Environmental Hotspots for Azole Resistance Selection of Aspergillus fumigatus, the Netherlands', 'Schoustra SE, Debets AJM, Rijs AJMM, Zhang J, Snelders E, Leendertse PC, Melchers WJG, Rietveld AG', 2019, 'Emerging infectious diseases', '10.3201/eid2507.181625', 'https://doi.org/10.3201/eid2507.181625', 'https://europepmc.org/articles/PMC6590754?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by', 'Azole resistance is a major concern for treatment of infections with Aspergillus fumigatus. Environmental resistance selection is a main route for Aspergillus spp. to acquire azole resistance. We investigated the presence of environmental hotspots for resistance selection in the Netherlands on the basis of the ability of A. fumigatus to grow and reproduce in the presence of azole fungicide residues. We identified 3 hotspots: flower bulb waste, green waste material, and wood chippings. We recovered azole-resistant A. fumigatus from these sites; all fungi contained cyp51A tandem repeat-mediated resistance mechanisms identical to those found in clinical isolates. Tebuconazole, epoxiconazole, and prothioconazole were the most frequently found fungicide residues. Stockpiles of plant waste contained the highest levels of azole-resistant A. fumigatus, and active aerobic composting reduced Aspergillus colony counts. Preventing plant waste stockpiling or creating unfavorable conditions for A. fumigatus to grow in stockpiles might reduce environmental resistance burden.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b475284-2172-4ec5-91a5-0da02b742047', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Evaluation of organic vinegar treatments and black gram [Vigna mungo (L.) Hepper] genotypes for the management of pod rot disease caused by Fusarium humuli', 'Rajshree Verma, Rajshree Verma, Kailash Pati Singh Kushwaha, Satya Kumar, Shilpi Rawat', 2026, 'Frontiers in Plant Science', '10.3389/fpls.2026.1647478', 'https://doi.org/10.3389/fpls.2026.1647478', 'https://www.frontiersin.org/articles/10.3389/fpls.2026.1647478/full', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'Black gram (Vigna mungo (L.) Hepper) is an important pulse crop valued for its nutritional benefits, soil-enriching nitrogen fixation, and use as animal feed. However, new diseases threaten its productivity, notably pod rot caused by Fusarium humuli, recently reported from Pantnagar, India. This study evaluated the efficacy of vinegars and pongamia oil under in-vitro and field conditions, and screened genotypes for resistance. In-vitro assays showed that Tebuconazole 25.9% EC achieved 100% mycelial inhibition at all concentrations. Among organic treatments, apple vinegar provided complete inhibition (100%) at 1.0% concentration and above, while sugarcane vinegar also maintained high efficacy across doses. Field trials revealed disease control ranging from 2.25% (Jamun vinegar 2.5% + hot water at 55°C for 10 min) to 52.83% (Seed treatment with Tebuconazole 1 g/kg + foliar spray of Tebuconazole 25.9% EC at 0.2%). Apple vinegar and sugarcane vinegar, used as seed and foliar treatments, recorded 42.70% and 41.56% disease control, respectively, along with enhanced plant growth, indicating their dual role in management and crop health. Screening of 50 genotypes during 2022–2023 identified 32 moderately resistant and 15 moderately susceptible lines, but none showed complete resistance. Apple and sugarcane vinegar thus emerged as the most effective organic options, with apple vinegar showing strong potential as a cost-effective, eco-friendly alternative. Overall, integrated approaches combining moderately resistant genotypes and organic treatments are essential for sustainable pod rot management in black gram.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e5ff6666-757b-4f46-8039-631596b516c9', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Factors influencing deoxynivalenol accumulation in small grain cereals', 'Wegulo SN', 2012, 'Toxins', '10.3390/toxins4111157', 'https://doi.org/10.3390/toxins4111157', 'https://europepmc.org/articles/PMC3509702?pdf=render', NULL, NULL, 24, NULL, 'northern_plains', 3, 'cc by', 'Deoxynivalenol (DON) is a mycotoxin produced by the plant pathogenic fungi Fusarium graminearum and F. culmorum. These and other closely related fungi cause a disease known as Fusarium head blight (FHB) in small grain cereals. Other mycotoxins produced by FHB-causing fungi include nivalenol, T-2 toxin, and zearalenone. Ingestion of mycotoxin-contaminated food and feed can lead to toxicosis in humans and animals, respectively. DON is the predominant and most economically important of these mycotoxins in the majority of small grain-producing regions of the world. This review examines the factors that influence DON accumulation in small grain cereals from an agricultural perspective. The occurrence and economic importance of FHB and DON in small grain cereals, epidemiological factors and cereal production practices that favor FHB development and DON accumulation in grain under field conditions, and regulatory/advisory standards for DON in food and feed are discussed. This information can be used to develop strategies that reduce DON accumulation in grain before harvest and to mitigate the human and animal health risks associated with DON contamination of food and feed.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('73c33e00-59ea-4545-a9c5-8942a8644570', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Fusarium Head Blight on Wheat: Biology, Modern Detection and Diagnosis and Integrated Disease Management', 'Alisaac E, Mahlein AK', 2023, 'Toxins', '10.3390/toxins15030192', 'https://doi.org/10.3390/toxins15030192', 'https://europepmc.org/articles/PMC10053988?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Fusarium head blight (FHB) is a major threat for wheat production worldwide. Most reviews focus on Fusarium graminearum as a main causal agent of FHB. However, different Fusarium species are involved in this disease complex. These species differ in their geographic adaptation and mycotoxin profile. The incidence of FHB epidemics is highly correlated with weather conditions, especially rainy days with warm temperatures at anthesis and an abundance of primary inoculum. Yield losses due to the disease can reach up to 80% of the crop. This review summarizes the Fusarium species involved in the FHB disease complex with the corresponding mycotoxin profiles, disease cycle, diagnostic methods, the history of FHB epidemics, and the management strategy of the disease. In addition, it discusses the role of remote sensing technology in the integrated management of the disease. This technology can accelerate the phenotyping process in the breeding programs aiming at FHB-resistant varieties. Moreover, it can support the decision-making strategies to apply fungicides via monitoring and early detection of the diseases under field conditions. It can also be used for selective harvest to avoid mycotoxin-contaminated plots in the field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4b33a758-f770-405b-b03f-f7fdcd730d89', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Oligosaccharins Used Together with Tebuconazole Enhances Resistance of Kiwifruit against Soft Rot Disease and Improves Its Yield and Quality', 'Qiuping Wang, Youhua Long, Qiang Ai, Yue Su, Yang Lei', 2022, 'Horticulturae', '10.3390/horticulturae8070624', 'https://doi.org/10.3390/horticulturae8070624', 'https://www.mdpi.com/2311-7524/8/7/624', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Botryosphaeria dothidea is one of the most frequent pathogens of soft rot disease in kiwifruit. The aim of this study was to investigate the role of oligosaccharins used together with tebuconazole to control soft rot and their influences on kiwifruit’s disease resistance, growth and quality. The results show that tebuconazole displayed a toxicity against B. dothidea RF-1 with 0.87 mg kg−1 of EC50 value. Oligosaccharins used together with tebuconazole effectively managed soft rot with 84.83% of the field management effect by spraying tebuconazole + oligosaccharins (0.5:0.5, m/v) as a 5000-fold dilution liquid, which significantly (p < 0.01) exceeded the 72.05%, 52.59%, 62.17% and 33.52% effect of tebuconazole 2500-, oligosaccharins 2500-, tebuconazole 5000- and oligosaccharins 5000-fold liquids, respectively. Simultaneously, co-application of tebuconazole and oligosaccharins was more effective for enhancing the resistance, growth and quality of kiwifruit compared with tebuconazole or oligosaccharins alone. This work highlights that oligosaccharins used together with tebuconazole can be proposed as a practicable measure for managing kiwifruit soft rot and reducing the application of chemical synthetic fungicides.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aace4f78-2a75-4f62-a3df-a3075bf98de3', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Identification of ABC transporter genes of Fusarium graminearum with roles in azole tolerance and/or virulence', 'Abou Ammar G, Tryono R, Döll K, Karlovsky P, Deising HB, Wirsel SG', 2013, 'PloS one', '10.1371/journal.pone.0079042', 'https://doi.org/10.1371/journal.pone.0079042', 'https://europepmc.org/articles/PMC3823976?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Fusarium graminearum is a plant pathogen infecting several important cereals, resulting in substantial yield losses and mycotoxin contamination of the grain. Triazole fungicides are used to control diseases caused by this fungus on a worldwide scale. Our previous microarray study indicated that 15 ABC transporter genes were transcriptionally upregulated in response to tebuconazole treatment. Here, we deleted four ABC transporter genes in two genetic backgrounds of F. graminearum representing the DON (deoxynivalenol) and the NIV (nivalenol) trichothecene chemotypes. Deletion of FgABC3 and FgABC4 belonging to group I of ABC-G and to group V of ABC-C subfamilies of ABC transporters, respectively, considerably increased the sensitivity to the class I sterol biosynthesis inhibitors triazoles and fenarimol. Such effects were specific since they did not occur with any other fungicide class tested. Assessing the contribution of the four ABC transporters to virulence of F. graminearum revealed that, irrespective of their chemotypes, deletion mutants of FgABC1 (ABC-C subfamily group V) and FgABC3 were impeded in virulence on wheat, barley and maize. Phylogenetic context and analyses of mycotoxin production suggests that FgABC3 may encode a transporter protecting the fungus from host-derived antifungal molecules. In contrast, FgABC1 may encode a transporter responsible for the secretion of fungal secondary metabolites alleviating defence of the host. Our results show that ABC transporters play important and diverse roles in both fungicide resistance and pathogenesis of F. graminearum.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('626f68e8-ca70-450c-9634-fe978e95fdb5', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Increasing the tolerance of Trichoderma harzianum T-22 to DMI fungicides enables the combined utilization of biological and chemical control strategies against plant diseases', 'Weizhen Wang, Guanxing Peng, Yanting Sun, Xiang Chen', 2024, 'Biological Control', '10.1016/j.biocontrol.2024.105479', 'https://doi.org/10.1016/j.biocontrol.2024.105479', 'http://www.sciencedirect.com/science/article/pii/S1049964424000446', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Demethylase inhibitors (DMIs) targeting CYP51 proteins in fungi are often used for plant disease management. Trichoderma harzianum, a widely used biocontrol agent, however, is sensitive to DMIs. This negates their combined use as a strategy in practices. Increasing the tolerance of T. harzianum to DMIs represents a feasible solution to this problem. In this regard, the overexpression of a CYP51B variant in Mycosphaerella graminicola (MgCYP51B-v) conveys increased tolerance to DMIs. Molecular docking indicated a distinct decrease in the affinity of MgCYP51B-v with DMIs. Since CYP51B proteins are conserved in M. graminicola and T. harzianum, we attempted to increase DMI tolerance in T. harzianum by heterologously expressing MgCYP51B-v. A series of T. harzianum mutants were obtained that were able to develop colonies on tebuconazole-amended medium. Two representative mutants were selected for further studies that confirmed that they were resistant to tebuconazole with resistance factors (RFs) of approximately 10.0. The mutants maintained a similar level of resistance after ten rounds of subculture without fungicide, indicating that the fungicide resistance was stably inherited. The mutants also exhibited increased tolerance to other DMIs, including metconazole, ipconazole, hexaconazole, and prochloraz. Further assessment indicated that the DMI resistance in the mutants did not have any impact on their fitness. The improved compatibility between T. harzianum and DMIs enables the utilization of a combined strategy in which these disease control agents are used together. Such a strategy has the potential to provide synergistic disease control and prevent or delay the development of fungicide resistance.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4990a4df-7697-4af7-8d07-20a5a0e5bd56', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Inhibitory, biochemical activity of pyraclostrobin·tebuconazole against Alternaria spp. and its potential for resistance management of Alternaria spp. to fungicides used for control of ginseng Alternaria leaf and stem blight', 'Hui Yu, Jie Bai, Shuai Shao, Kaixin Zhang, Ming''en Jiang, Changqing Chen, Ronglin He, Baohui Lu', 2025, 'Journal of Agriculture and Food Research', '10.1016/j.jafr.2025.102368', 'https://doi.org/10.1016/j.jafr.2025.102368', 'http://www.sciencedirect.com/science/article/pii/S2666154325007392', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Ginseng Alternaria leaf and stem blight (GALSB), caused by Alternaria spp., poses a serious threat to ginseng production. Alternaria spp. has developed resistance to currently used fungicides. To evaluate the efficacy of pyraclostrobin·tebuconazole (PT) 30 % SC for the control of GALSB disease, and lay the foundation for the management of resistance of Alternaria spp., the study was conducted to evaluate the effectiveness of PT in controlling GALSB on detached ginseng leaves and in one-year field experiments, based on its inhibitory and biochemical activities against A. alternata, A. panax, and A. tenuissima. The cross-resistance of PT with eight widely used fungicides was ascertained using Spearman''s correlation analysis. PT has a better inhibitory effect on the mycelium growth and conidial germination of Alternaria spp., while having no observable effect on mycelium deformity. However, PT significantly shortened the germ tube, reduced the DNA and soluble protein contents, and decreased the permeability of the cell membrane of Alternaria spp. PT displayed significant protective (66.26 %–98.92 %) and curative (60.08 %–99.31 %) effects against GALSB on detached leaves at 50–150 μg/mL, outperforming tebuconazole (p < 0.05). Field trials confirmed that PT had a superior control efficacy at medium to high doses compared to difenoconazole, propiconazole, tebuconazole, and iprodione at seven, 15, and 30 days following the last application. Crucially, PT had no cross-resistance with the other evaluated fungicides. These findings highlight that PT provides effective protection and treatment against GALSB and, importantly, is a candidate for mitigating fungicide resistance development in Alternaria spp. associated with GALSB control, with potential as a rotation or replacement fungicide in resistance management programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('91ff4f1c-7e8e-40dd-8ba8-ee09b3f3a796', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Integrated application programmes for jujube black spot management: Effects on defence-related enzyme activities and fruit quality', 'Jiangming Kou, Zheng Wang, Wuerkaixi Yali, Zhirui Kang, Yisirefuli Yasheng, Yusufjon Gafforov, Chengming Tian, Rong Ma', 2026, 'Journal of Agriculture and Food Research', '10.1016/j.jafr.2026.103234', 'https://doi.org/10.1016/j.jafr.2026.103234', 'http://www.sciencedirect.com/science/article/pii/S2666154326006058', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Jujube black spot disease, mainly associated with Alternaria alternata , threatens fruit marketability and quality in major production areas of Xinjiang, China. This study evaluated whether stage-specific integration of resistance inducers, biocontrol agents, and fungicides could improve disease suppression while maintaining fruit quality. Individual and mixed treatments were screened in a randomised complete block experiment, and selected programmes were applied at flowering, fruit expansion, white-ripe and full-ripe stages. Field efficacy, defence-related enzyme activities, estimated yield, fruit quality, and pesticide input cost were assessed. Resistance inducers and mixtures produced distinct temporal defence responses; disease control and estimated yield did not always vary in parallel. Among individual treatments, amino-oligosaccharide combined disease suppression, estimated yield, and defence activation. The stage-specific A-MPT programme—two early amino-oligosaccharide applications followed by two applications of polyoxin plus tebuconazole—maintained disease control and produced a favourable sugar–acid profile. Entropy-weighted TOPSIS analysis ranked A-MPT as the most balanced programme across disease control, fruit quality, estimated yield, and pesticide cost indicators. These findings support stage-specific integration of resistance induction and later direct pathogen suppression as a promising strategy for jujube black spot management. Multi-season and multi-site validation, direct measurement of marketable yield, and full cost–benefit analysis are needed before broad commercial recommendation.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3cc4621e-a119-47b1-9056-a1d992b1500a', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Plant Growth-Promoting Rhizobacteria for Sustainable Agricultural Production', 'de Andrade LA, Santos CHB, Frezarin ET, Sales LR, Rigobelo EC', 2023, 'Microorganisms', '10.3390/microorganisms11041088', 'https://doi.org/10.3390/microorganisms11041088', 'https://europepmc.org/articles/PMC10146397?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Rhizosheric bacteria with several abilities related to plant growth and health have been denominated Plant Growth-Promoting Rhizobacteria (PGPR). PGPR promote plant growth through several modes of action, be it directly or indirectly. The benefits provided by these bacteria can include increased nutrient availability, phytohormone production, shoot and root development, protection against several phytopathogens, and reduced diseases. Additionally, PGPR can help plants to withstand abiotic stresses such as salinity and drought and produce enzymes that detoxify plants from heavy metals. PGPR have become an important strategy in sustainable agriculture due to the possibility of reducing synthetic fertilizers and pesticides, promoting plant growth and health, and enhancing soil quality. There are many studies related to PGPR in the literature. However, this review highlights the studies that used PGPR for sustainable production in a practical way, making it possible to reduce the use of fertilizers such as phosphorus and nitrogen and fungicides, and to improve nutrient uptake. This review addresses topics such as unconventional fertilizers, seed microbiome for rhizospheric colonization, rhizospheric microorganisms, nitrogen fixation for reducing chemical fertilizers, phosphorus solubilizing and mineralizing, and siderophore and phytohormone production for reducing the use of fungicides and pesticides for sustainable agriculture.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6483277b-966e-4ccc-b7a6-f1390678345c', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Prevalence and mechanism of triazole resistance in Aspergillus fumigatus in a referral chest hospital in Delhi, India and an update of the situation in Asia', 'Chowdhary A, Sharma C, Kathuria S, Hagen F, Meis JF', 2015, 'Frontiers in microbiology', '10.3389/fmicb.2015.00428', 'https://doi.org/10.3389/fmicb.2015.00428', 'https://europepmc.org/articles/PMC4424976?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Aspergillus fumigatus causes varied clinical syndromes ranging from colonization to deep infections. The mainstay of therapy of Aspergillus diseases is triazoles but several studies globally highlighted variable prevalence of triazole resistance, which hampers the management of aspergillosis. We studied the prevalence of resistance in clinical A. fumigatus isolates during 4 years in a referral Chest Hospital in Delhi, India and reviewed the scenario in Asia and the Middle East. Aspergillus species (n = 2117) were screened with selective plates for azole resistance. The isolates included 45.4% A. flavus, followed by 32.4% A. fumigatus, 15.6% Aspergillus species and 6.6% A. terreus. Azole resistance was found in only 12 (1.7%) A. fumigatus isolates. These triazole resistant A. fumigatus (TRAF) isolates were subjected to (a) calmodulin and β tubulin gene sequencing (b) in vitro antifungal susceptibility testing against triazoles using CLSI M38-A2 (c) sequencing of cyp51A gene and real-time PCR assay for detection of mutations and (d) microsatellite typing of the resistant isolates. TRAF harbored TR34/L98H mutation in 10 (83.3%) isolates with a pan-azole resistant phenotype. Among the remaining two TRAF isolates, one had G54E and the other had three non-synonymous point mutations. The majority of patients were diagnosed as invasive aspergillosis followed by allergic bronchopulmonary aspergillosis and chronic pulmonary aspergillosis. The Indian TR34/L98H isolates had a unique genotype and were distinct from the Chinese, Middle East, and European TR34/L98H strains. This resistance mechanism has been linked to the use of fungicide azoles in agricultural practices in Europe as it has been mainly reported from azole naïve patients. Reports published from Asia demonstrate the same environmental resistance mechanism in A. fumigatus isolates from two highly populated countries in Asia, i.e., China and India and also from the neighboring Middle East.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b889bf21-b70b-4c72-9f67-f218b325fa19', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Role of fungicides, application of nozzle types, and the resistance level of wheat varieties in the control of Fusarium head blight and deoxynivalenol', 'Mesterházy A, Tóth B, Varga M, Bartók T, Szabó-Hevér A, Farády L, Lehoczki-Krsjak S', 2011, 'Toxins', '10.3390/toxins3111453', 'https://doi.org/10.3390/toxins3111453', 'https://europepmc.org/articles/PMC3237006?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Fungicide application is a key factor in the control of mycotoxin contamination in the harvested wheat grain. However, the practical results are often disappointing. In 2000-2004, 2006-2008 and 2007 and 2008, three experiments were made to test the efficacy of fungicide control on Fusarium Head Blight (FHB) in wheat and to find ways to improve control of the disease and toxin contamination. In a testing system we have used for 20 years, tebuconazole and tebuconazole + prothioconazole fungicides regularly reduced symptoms by about 80% with a correlating reduction in toxin contamination. Averages across the years normally show a correlation of r = 0.90 or higher. The stability differences (measured by the stability index) between the poorest and the best fungicides are about 10 or more times, differing slightly in mycotoxin accumulation, FHB index (severity) and Fusarium damaged kernels (FDK). The weak fungicides, like carbendazim, were effective only when no epidemic occurred or epidemic severity was at a very low level. Similar fungicide effects were seen on wheat cultivars which varied in FHB resistance. In this study, we found three fold differences in susceptibility to FHB between highly susceptible and moderately resistant cultivars when treated with fungicides. In the moderately resistant cultivars, about 50% of the fungicide treatments lowered the DON level below the regulatory limit. In the most susceptible cultivars, all fungicides failed to reduce mycotoxin levels low enough for grain acceptance, in spite of the fact that disease was significantly reduced. The results correlated well with the results of the large-scale field tests of fungicide application at the time of natural infection. The Turbo FloodJet nozzle reduced FHB incidence and DON contamination when compared to the TeeJet XR nozzle. Overall, the data suggest that significant decreases in FHB incidence and deoxynivalenol contamination in field situations are possible with proper fungicide applications. Additionally, small plot tests can be used to evaluate the quality of the field disease and toxin production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0c7f4f9b-aa54-46c6-80fc-4439c76028b6', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Sensitivity, Resistance Risk Assessment of Bipolaris oryzae to Three DMI Fungicides and Their Control Efficacy Against Banana Eyespot Disease in Hainan Island, China', 'Yanxiang Qi, Zhaojing Zhang, Hong Zhao, Xuelian Xu, Xin Zhang', 2026, 'Journal of Fungi', '10.3390/jof12080546', 'https://doi.org/10.3390/jof12080546', 'https://www.mdpi.com/2309-608X/12/8/546', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Bipolaris oryzae was recently identified as a new species causing eyespot disease of banana in China. Propiconazole, flusilazole and tebuconazole, belonging to demethylation inhibitor (DMI) fungicides, are commonly used for controlling this disease in China. In this study, the propiconazole, flusilazole and tebuconazole sensitivity of 108 B. oryzae isolates collected from banana leaf samples in different locations of Hainan Island, China, in 2021–2023 was determined by mycelial growth inhibition, and the control efficacy of the three DMI fungicides against B. oryzae was assayed in pot experiments. The sensitivity frequency distributions of 108 B. oryzae isolates to propiconazole, flusilazole and tebuconazole indicated the emergence of subpopulations with reduced sensitivity, with EC50 values ranging from 0.029 to 3.495 μg/mL, 0.008 to 3.665 μg/mL, and 0.022 to 8.288 μg/mL, with means and standard errors of 0.826 ± 0.059 μg/mL, 0.204 ± 0.036 μg/mL and 0.952 ± 0.113 μg/mL, respectively. However, the sensitivity distributions of 82.41%, 82.41%, and 80.56% of B. oryzae isolates at the main peak, respectively, to the three fungicides fitted to a normal distribution. Thus, the mean EC50 values of 0.594 ± 0.032 μg/mL, 0.118 ± 0.007 μg/mL and 0.574 ± 0.033 μg/mL of these isolates could be used as the baseline for testing the sensitivity of B. oryzae to propiconazole, flusilazole and tebuconazole, respectively. No significant sensitivity differences to each fungicide among different geographical populations were observed, but a statistically significant and positive association in sensitivity between all three fungicides existed. Seven unstably inherited DMI-resistant isolates all exhibited lower fitness levels than those of the sensitive isolates, suggesting a low risk of resistance to the three DMI fungicides in B. oryzae. Three fungicides applied separately exhibited 100% protective control efficacy against B. oryzae and less than 40% curative control efficacy in pot experiments. Therefore, propiconazole, flusilazole and tebuconazole should be used as protective rather than curative fungicides. These results provide essential information on the evolution of DMI resistance in B. oryzae in Hainan Island, China, and may serve as a reference point in the management of B. oryzae and future DMI resistance monitoring programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2c75236f-2095-43cb-8dc2-aa744f653364', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Soybean anthracnose caused by Colletotrichum species: Current status and future prospects', 'Boufleur TR, Ciampi-Guillardi M, Tikami Í, Rogério F, Thon MR, Sukno SA, Massola Júnior NS, Baroncelli R', 2021, 'Molecular plant pathology', '10.1111/mpp.13036', 'https://doi.org/10.1111/mpp.13036', 'https://europepmc.org/articles/PMC7938629?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Soybean (Glycine max) is one of the most important cultivated plants worldwide as a source of protein-rich foods and animal feeds. Anthracnose, caused by different lineages of the hemibiotrophic fungus Colletotrichum, is one of the main limiting factors to soybean production. Losses due to anthracnose have been neglected, but their impact may threaten up to 50% of the grain production.TaxonomyWhile C. truncatum is considered the main species associated with soybean anthracnose, recently other species have been reported as pathogenic on this host. Until now, it has not been clear whether the association of new Colletotrichum species with the disease is related to emerging species or whether it is due to the undergoing changes in the taxonomy of the genus.Disease symptomsTypical anthracnose symptoms are pre- and postemergence damping-off; dark, depressed, and irregular spots on cotyledons, stems, petioles, and pods; and necrotic laminar veins on leaves that can result in premature defoliation. Symptoms may evolve to pod rot, immature opening of pods, and premature germination of grains.ChallengesAs accurate species identification of the causal agent is decisive for disease control and prevention, in this work we review the taxonomic designation of Colletotrichum isolated from soybean to understand which lineages are pathogenic on this host. We also present a comprehensive literature review of soybean anthracnose, focusing on distribution, symptomatology, epidemiology, disease management, identification, and diagnosis. We consider the knowledge emerging from population studies and comparative genomics of Colletotrichum spp. associated with soybean providing future perspectives in the identification of molecular factors involved in the pathogenicity process.Useful websiteUpdates on Colletotrichum can be found at http://www.colletotrichum.org/. All available Colletotrichum genomes on GenBank can be viewed at http://www.colletotrichum.org/genomics/.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dc891dd7-b1ac-4f8a-87a8-b81587ba0c69', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Transgenic expression of lactoferrin imparts enhanced resistance to head blight of wheat caused by Fusarium graminearum', 'Han J, Lakshman DK, Galvez LC, Mitra S, Baenziger PS, Mitra A', 2012, 'BMC plant biology', '10.1186/1471-2229-12-33', 'https://doi.org/10.1186/1471-2229-12-33', 'https://europepmc.org/articles/PMC3364854?pdf=render', NULL, NULL, 9, NULL, 'northern_plains', 3, 'cc by', 'BackgroundThe development of plant gene transfer systems has allowed for the introgression of alien genes into plant genomes for novel disease control strategies, thus providing a mechanism for broadening the genetic resources available to plant breeders. Using the tools of plant genetic engineering, a broad-spectrum antimicrobial gene was tested for resistance against head blight caused by Fusarium graminearum Schwabe, a devastating disease of wheat (Triticum aestivum L.) and barley (Hordeum vulgare L.) that reduces both grain yield and quality.ResultsA construct containing a bovine lactoferrin cDNA was used to transform wheat using an Agrobacterium-mediated DNA transfer system to express this antimicrobial protein in transgenic wheat. Transformants were analyzed by Northern and Western blots to determine lactoferrin gene expression levels and were inoculated with the head blight disease fungus F. graminearum. Transgenic wheat showed a significant reduction of disease incidence caused by F. graminearum compared to control wheat plants. The level of resistance in the highly susceptible wheat cultivar Bobwhite was significantly higher in transgenic plants compared to control Bobwhite and two untransformed commercial wheat cultivars, susceptible Wheaton and tolerant ND 2710. Quantification of the expressed lactoferrin protein by ELISA in transgenic wheat indicated a positive correlation between the lactoferrin gene expression levels and the levels of disease resistance.ConclusionsIntrogression of the lactoferrin gene into elite commercial wheat, barley and other susceptible cereals may enhance resistance to F. graminearum.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa81ffcb-22de-4833-b8a3-0a4c30144301', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Trends in Agricultural Triazole Fungicide Use in the United States, 1992-2016 and Possible Implications for Antifungal-Resistant Fungi in Human Disease', 'Toda M, Beer KD, Kuivila KM, Chiller TM, Jackson BR', 2021, 'Environmental health perspectives', '10.1289/ehp7484', 'https://doi.org/10.1289/ehp7484', 'https://europepmc.org/articles/PMC8098123?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc0', 'BackgroundThe fungus Aspergillus fumigatus (A. fumigatus) is the leading cause of invasive mold infections, which cause severe disease and death in immunocompromised people. Use of triazole antifungal medications in recent decades has improved patient survival; however, triazole-resistant infections have become common in parts of Europe and are emerging in the United States. Triazoles are also a class of fungicides used in plant agriculture, and certain triazole-resistant A. fumigatus strains found causing disease in humans have been linked to environmental fungicide use.ObjectivesWe examined U.S. temporal and geographic trends in the use of triazole fungicides using U.S. Geological Survey agricultural pesticide use estimates.DiscussionBased on our analysis, overall tonnage of triazole fungicide use nationwide was relatively constant during 1992-2005 but increased >4-fold during 2006-2016 to 2.9 million kg in 2016. During 1992-2005, triazole fungicide use occurred mostly in orchards and grapes, wheat, and other crops, but recent increases in use have occurred primarily in wheat, corn, soybeans, and other crops, particularly in Midwest and Southeast states. We conclude that, given the chemical similarities between triazole fungicides and triazole antifungal drugs used in human medicine, increased monitoring for environmental and clinical triazole resistance in A. fumigatus would improve overall understanding of these interactions, as well as help identify strategies to mitigate development and spread of resistance. https://doi.org/10.1289/EHP7484.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5a01c543-5d21-4908-bd8e-38e4f8a10943', 'ab720fd2-a76f-4cdb-a384-81d478401156', 'Triazole fungicides can induce cross-resistance to medical triazoles in Aspergillus fumigatus', 'Snelders E, Camps SM, Karawajczyk A, Schaftenaar G, Kema GH, van der Lee HA, Klaassen CH, Melchers WJ', 2012, 'PloS one', '10.1371/journal.pone.0031801', 'https://doi.org/10.1371/journal.pone.0031801', 'https://europepmc.org/articles/PMC3291550?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'BackgroundAzoles play an important role in the management of Aspergillus diseases. Azole resistance is an emerging global problem in Aspergillus fumigatus, and may develop through patient therapy. In addition, an environmental route of resistance development has been suggested through exposure to 14α-demethylase inhibitors (DMIs). The main resistance mechanism associated with this putative fungicide-driven route is a combination of alterations in the Cyp51A-gene (TR(34)/L98H). We investigated if TR(34)/L98H could have developed through exposure to DMIs.Methods and findingsThirty-one compounds that have been authorized for use as fungicides, herbicides, herbicide safeners and plant growth regulators in The Netherlands between 1970 and 2005, were investigated for cross-resistance to medical triazoles. Furthermore, CYP51-protein homology modeling and molecule alignment studies were performed to identify similarity in molecule structure and docking modes. Five triazole DMIs, propiconazole, bromuconazole, tebuconazole, epoxiconazole and difenoconazole, showed very similar molecule structures to the medical triazoles and adopted similar poses while docking the protein. These DMIs also showed the greatest cross-resistance and, importantly, were authorized for use between 1990 and 1996, directly preceding the recovery of the first clinical TR(34)/L98H isolate in 1998. Through microsatellite genotyping of TR(34)/L98H isolates we were able to calculate that the first isolate would have arisen in 1997, confirming the results of the abovementioned experiments. Finally, we performed induction experiments to investigate if TR(34)/L98H could be induced under laboratory conditions. One isolate evolved from two copies of the tandem repeat to three, indicating that fungicide pressure can indeed result in these genomic changes.ConclusionsOur findings support a fungicide-driven route of TR(34)/L98H development in A. fumigatus. Similar molecule structure characteristics of five triazole DMIs and the three medical triazoles appear the underlying mechanism of cross resistance development. Our findings have major implications for the assessment of health risks associated with the use of triazole DMIs.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0dc0197f-f382-4156-96a1-049f0ba3102a', '35083f56-3855-4792-8594-c7a405b120ba', 'A first survey for herbicide resistant weeds across major maize growing areas in the North Island of New Zealand', 'Ngow Z, James TK, Harvey B, Buddenhagen CE', 2024, 'PloS one', '10.1371/journal.pone.0299539', 'https://doi.org/10.1371/journal.pone.0299539', 'https://europepmc.org/articles/PMC10919694?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Weeds are increasingly documented with evolved resistance to herbicides globally. Three species have been reported as resistant in maize crops in New Zealand: Chenopodium album to atrazine and dicamba, Persicaria maculosa to atrazine and Digitaria sanguinalis to nicosulfuron. Despite knowledge of these cases, the distribution of these resistant biotypes is unknown. This study aimed to determine the prevalence of known resistant weeds in major maize growing areas in New Zealand, and to pro-actively screen other species for resistance. Weed seeds of broadleaf and grass species were collected from 70 randomly selected maize growing farms in the North Island in 2021-2022. Seeds were grown and treated with herbicides at recommended field rates. Atrazine-resistant C. album were recorded in a third of surveyed farms and nicosulfuron-resistant D. sanguinalis in a sixth. Half of Waikato farms and a quarter of Bay of Plenty farms (no Hawkes Bay or Wellington farms) had atrazine-resistant C. album. Dicamba-resistant C. album were not detected, nor were atrazine-resistant P. maculosa. Nicosulfuron resistant D. sanguinalis was recorded in 19% of Waikato farms, 6% of Bay of Plenty farms and 9% of Hawkes Bay farms (no Wellington farms). Amaranthus spp., Fallopia convolvulus, Persicaria spp., Solanum spp., Echinochloa crus-galli, Panicum spp. and Setaria spp. were not resistant to any of the herbicides tested. Twenty-nine to 52% of maize farms in the North Island are estimated to have herbicide resistant weeds. Resistance is common in maize farms in Waikato and western Bay of Plenty. Resistance is rare in southern regions, with only one instance of nicosulfuron-resistant D. sanguinalis and no resistant C. album. Most annual weeds in maize are not resistant to herbicides; although atrazine resistant C. album is widespread, it is currently controlled with alternative herbicides. Resistant D. sanguinalis appears to be an emerging problem.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ee070795-c135-4be5-8e1e-77a85a09fd82', '35083f56-3855-4792-8594-c7a405b120ba', 'An artificially evolved gene for herbicide-resistant rice breeding', 'Dong J, Yu XH, Dong J, Wang GH, Wang XL, Wang DW, Yan YC, Xiao H', 2024, 'Proceedings of the National Academy of Sciences of the United States of America', '10.1073/pnas.2407285121', 'https://doi.org/10.1073/pnas.2407285121', 'https://europepmc.org/articles/PMC11348328?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by-nc-nd', 'Discovering and engineering herbicide-resistant genes is a crucial challenge in crop breeding. This study focuses on the 4-hydroxyphenylpyruvate dioxygenase Inhibitor Sensitive 1-Like (HSL) protein, prevalent in higher plants and exhibiting weak catalytic activity against many β-triketone herbicides (β-THs). The crystal structures of maize HSL1A complexed with β-THs were elucidated, identifying four essential herbicide-binding residues and explaining the weak activity of HSL1A against the herbicides. Utilizing an artificial evolution approach, we developed a series of rice HSL1 mutants targeting the four residues. Then, these mutants were systematically evaluated, identifying the M10 variant as the most effective in modifying β-THs. The initial active conformation of substrate binding in HSL1 was also revealed from these mutants. Furthermore, overexpression of M10 in rice significantly enhanced resistance to β-THs, resulting in a notable 32-fold increase in resistance to methyl-benquitrione. In conclusion, the artificially evolved M10 gene shows great potential for the development of herbicide-resistant crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1a963287-19cf-483d-8afb-b3f4e2f93466', '35083f56-3855-4792-8594-c7a405b120ba', 'Bipyrazone: a new HPPD-inhibiting herbicide in wheat', 'Wang H, Liu W, Jin T, Peng X, Zhang L, Wang J', 2020, 'Scientific reports', '10.1038/s41598-020-62116-6', 'https://doi.org/10.1038/s41598-020-62116-6', 'https://europepmc.org/articles/PMC7098957?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Bipyrazone, 1,3-dimethyl-4-(2-(methylsulfonyl)-4-(trifluoromethyl) benzoyl)-1H-pyrazol-5-yl 1,3-dimethyl-1H-pyrazole- 4-carboxylate, is a 4-hydroxyphenylpyaunate dioxygenase (HPPD)-inhibiting herbicide. Greenhouse and field experiments were conducted to explore the potential of post-emergence (POST) application of bipyrazone in wheat fields in China. In the greenhouse study, bipyrazone at 10 and 20 g active ingredient (a.i.) ha-1 effectively controlled Descurainia sophia L., Capsella bursa-pastoris (L.) Medic., Lithospermum arvense L. and Myosoton aquaticum L. Whereas, all tested 16 wheat cultivars showed high degree of tolerance to bipyrazone at 375 and 750 g a.i. ha-1. In a dose-response experiment carried on the Shannong 6 wheat cultivar and five weed biotypes, bipyrazone was safe to the wheat cultivar, and C. bursa-pastoris, M. aquaticum and D. sophia were sensitive to this herbicide. The selectivity index (SI) between the Shannong 6 and weeds ranged from 34 to 39. The field experiments confirmed that a mixture of bipyrazone and fluroxypyr-mepthyl is practical for controlling broadleaf weeds, and bipyrazone applied alone at 30 to 40 g a.i. ha-1 can also provide satisfactory control of sensitive broadleaf weeds. These findings suggest that bipyrazone POST application has good potential for broadleaf weed management in wheat fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2506456-5dea-40ee-98e9-3da636c56afb', '35083f56-3855-4792-8594-c7a405b120ba', 'Characterization of a Topramezone-Resistant Rice Mutant TZR1: Insights into GST-Mediated Detoxification and Antioxidant Responses', 'Shiyuan Hu, Kai Luo, Tao Tang, Guolan Ma, Yajun Peng, Yuzhu Zhang, Yang Liu, Lang Pan', 2025, 'Plants', '10.3390/plants14030425', 'https://doi.org/10.3390/plants14030425', 'https://www.mdpi.com/2223-7747/14/3/425', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Mutagenesis breeding, combined with the application of corresponding herbicides to develop herbicide-resistant rice germplasm, provides great promise for the management of weeds and weedy rice. In this study, a topramezone-resistant rice mutant, TZR1, was developed from the indica rice line Chuangyu 9H (CY9H) through radiation mutagenesis and topramezone selection. Dose–response curves revealed that the resistance index of TZR1 to topramezone was 1.94-fold compared to that of CY9H. The resistance mechanism of TZR1 was not due to target-site resistance. This resistance could be reversed by a specific inhibitor of glutathione S-transferase (GST). The activity of antioxidant enzymes was analyzed. SNPs and Indels were detected using whole-genome resequencing; differentially expressed genes were identified through RNA sequencing. Then, they underwent Gene Ontology and Kyoto Encyclopedia of Genes and Genomes enrichment analyses. Key candidate genes associated with topramezone resistance were validated via a real-time quantitative PCR assay. Five GST genes, two UDP-glycosyltransferase genes, and three ATP-binding cassette transporter genes were identified as potential contributors to topramezone detoxification in TZR1. Overall, these findings suggest that GST enzymes possibly play an important role in TZR1 resistance to topramezone. This study will provide valuable information for the scientific application of 4-hydroxyphenylpyruvate dioxygenase inhibitors in paddy fields in future.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('618b28d1-8df9-4d89-9a53-a185157242dd', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Rice false smut pathogen: implications for mycotoxin contamination, current status, and future perspectives', 'Zhou L, Mubeen M, Iftikhar Y, Zheng H, Zhang Z, Wen J, Khan RAA, Sajid A', 2024, 'Frontiers in microbiology', '10.3389/fmicb.2024.1344831', 'https://doi.org/10.3389/fmicb.2024.1344831', 'https://europepmc.org/articles/PMC10996400?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Rice serves as a staple food across various continents worldwide. The rice plant faces significant threats from a range of fungal, bacterial, and viral pathogens. Among these, rice false smut disease (RFS) caused by Villosiclava virens is one of the devastating diseases in rice fields. This disease is widespread in major rice-growing regions such as China, Pakistan, Bangladesh, India, and others, leading to significant losses in rice plantations. Various toxins are produced during the infection of this disease in rice plants, impacting the fertilization process as well. This review paper lightens the disease cycle, plant immunity, and infection process during RFS. Mycotoxin production in RFS affects rice plants in multiple ways, although the exact phenomena are still unknown.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1c5b6b52-c484-482a-90d8-8ce9c6ee329c', '35083f56-3855-4792-8594-c7a405b120ba', 'Characterization, Genetic Analyses, and Identification of QTLs Conferring Metabolic Resistance to a 4-Hydroxyphenylpyruvate Dioxygenase Inhibitor in Sorghum (Sorghum bicolor)', 'Pandian BA, Varanasi A, Vennapusa AR, Sathishraj R, Lin G, Zhao M, Tunnell M, Tesso T', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.596581', 'https://doi.org/10.3389/fpls.2020.596581', 'https://europepmc.org/articles/PMC7756693?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Postemergence grass weed control continues to be a major challenge in grain sorghum [Sorghum bicolor (L.) Moench], primarily due to lack of herbicide options registered for use in this crop. The development of herbicide-resistant sorghum technology to facilitate broad-spectrum postemergence weed control can be an economical and viable solution. The 4-hydroxyphenylpyruvate dioxygenase-inhibitor herbicides (e.g., mesotrione or tembotrione) can control a broad spectrum of weeds including grasses, which, however, are not registered for postemergence application in sorghum due to crop injury. In this study, we identified two tembotrione-resistant sorghum genotypes (G-200, G-350) and one susceptible genotype (S-1) by screening 317 sorghum lines from a sorghum association panel (SAP). These tembotrione-resistant and tembotrione-susceptible genotypes were evaluated in a tembotrione dose-response [0, 5.75, 11.5, 23, 46, 92 (label recommended dose), 184, 368, and 736 g ai ha-1] assay. Compared with S-1, the genotypes G-200 and G-350 exhibited 10- and seven fold more resistance to tembotrione, respectively. To understand the inheritance of tembotrione-resistant trait, crosses were performed using S-1 and G-200 or G-350 to generate F1 and F2 progeny. The F1 and F2 progeny were assessed for their response to tembotrione treatment. Genetic analyses of the F1 and F2 progeny demonstrated that the tembotrione resistance in G-200 and G-350 is a partially dominant polygenic trait. Furthermore, cytochrome P450 (CYP)-inhibitor assay using malathion and piperonyl butoxide suggested possible CYP-mediated metabolism of tembotrione in G-200 and G-350. Genotype-by-sequencing based quantitative trait loci (QTL) mapping revealed QTLs associated with tembotrione resistance in G-200 and G-350 genotypes. Overall, the genotypes G-200 and G-350 confer a high level of metabolic resistance to tembotrione and controlled by a polygenic trait. There is an enormous potential to introgress the tembotrione resistance into breeding lines to develop agronomically desirable sorghum hybrids.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aa09d5e9-5d79-4f51-b1b4-83e32f512946', '35083f56-3855-4792-8594-c7a405b120ba', 'Cytochrome P450 Inhibitors Reduce Creeping Bentgrass (Agrostis stolonifera) Tolerance to Topramezone', 'Elmore MT, Brosnan JT, Armel GR, Kopsell DA, Best MD, Mueller TC, Sorochan JC', 2015, 'PloS one', '10.1371/journal.pone.0130947', 'https://doi.org/10.1371/journal.pone.0130947', 'https://europepmc.org/articles/PMC4506071?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Creeping bentgrass (Agrostis stolonifera L.) is moderately tolerant to the p-hydroxyphenylpyruvate dioxygenase-inhibiting herbicide topramezone. However, the contribution of plant metabolism of topramezone to this tolerance is unknown. Experiments were conducted to determine if known cytochrome P450 monooxygenase inhibitors 1-aminobenzotriazole (ABT) and malathion alone or in combination with the herbicide safener cloquintocet-mexyl influence creeping bentgrass tolerance to topramezone. Creeping bentgrass in hydroponic culture was treated with ABT (70 μM), malathion (70 μm and 1000 g ha(-1)), or cloquintocet-mexyl (70 μM and 1000 g ha(-1)) prior to topramezone (8 g ha(-1)) application. Topramezone-induced injury to creeping bentgrass increased from 22% when applied alone to 79 and 41% when applied with malathion or ABT, respectively. Cloquintocet-mexyl (70 μM and 1000 g ha(-1)) reduced topramezone injury to 1% and increased creeping bentgrass biomass and PSII quantum yield. Cloquintocet-mexyl mitigated the synergistic effects of ABT more than those of malathion. The effects of malathion on topramezone injury were supported by creeping bentgrass biomass responses. Responses to ABT and malathion suggest that creeping bentgrass tolerance to topramezone is influenced by cytochrome P450-catalyzed metabolism. Future research should elucidate primary topramezone metabolites and determine the contribution of cytochrome P450 monooxygenases and glutathione S-transferases to metabolite formation in safened and non-safened creeping bentgrass.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f842becb-265a-44d8-9184-58eda40d85e2', '35083f56-3855-4792-8594-c7a405b120ba', 'Development of a rice herbicide, fenquinotrione', 'Nagamatsu A, Ueda K, Tamai R, Tani S, Yamamoto S', 2022, 'Journal of pesticide science', '10.1584/jpestics.j22-02', 'https://doi.org/10.1584/jpestics.j22-02', 'https://europepmc.org/articles/PMC9706282?pdf=render', NULL, NULL, 7, NULL, 'other', 1, 'cc by-nc-nd', 'Fenquinotrione is a novel rice herbicide that was discovered and developed by Kumiai Chemical Industry Co., Ltd. It can control a wide range of broadleaf and sedge weeds with excellent rice selectivity at 30 g a.i./10 a and is as effective as the wild type on acetolactate synthase inhibitor-resistant weeds. Our metabolic and molecular biological studies showed that CYP81A6-mediated demethylation and subsequent glucose conjugation are responsible for the safety of fenquinotrione in rice. Fenquinotrione was registered in Japan in 2018, and various products containing fenquinotrione have been launched. With its high efficacy and excellent rice selectivity, we believe that fenquinotrione will contribute to efficient food production in the future.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d61d32a3-70fd-4e2f-9b74-bc530ce6df05', '35083f56-3855-4792-8594-c7a405b120ba', 'Enhanced Herbicide Metabolism and Target-Site Mutations Confer Multiple Resistance to Fomesafen and Nicosulfuron in Amaranthus retroflexus L', 'Yang C, Wang H, Duan Y, Bei F, Jia S, Wang J, Wang H, Liu W', 2023, 'Biology', '10.3390/biology12040592', 'https://doi.org/10.3390/biology12040592', 'https://europepmc.org/articles/PMC10135446?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Amaranthus retroflexus L. is a highly competitive broadleaf weed of corn-soybean rotation in northeastern China. In recent years, the herbicide(s) resistance evolution has been threatening its effective management in crop fields. One resistant A. retroflexus (HW-01) population that survived the protoporphyrinogen oxidase (PPO) inhibitor fomesafen and acetolactate synthase (ALS) inhibitor nicosulfuron applied at their field-recommended rate was collected from a soybean field in Wudalianchi City, Heilongjiang Province. This study aimed to investigate the resistance mechanisms of fomesafen and nicosulfuron and determine the resistance profile of HW-01 to other herbicides. Whole plant dose-response bioassays revealed that HW-01 had evolved resistance to fomesafen (50.7-fold) and nicosulfuron (5.2-fold). Gene sequencing showed that the HW-01 population has a mutation in PPX2 (Arg-128-Gly) and a rare mutation in ALS (Ala-205-Val, eight/twenty mutations/total plants). In vitro enzyme activity assays showed that ALS extracted from the HW-01 plants was less sensitive to nicosulfuron (3.2-fold) than ST-1 plants. Pre-treatment with the cytochrome P450 inhibitors malathion, piperonyl butoxide (PBO), 3-amino-1,2,4-triazole (amitrole), and the GSTs inhibitor 4-chloro-7-nitrobenzofurazan (NBD-Cl) significantly increased fomesafen and nicosulfuron sensitivity in the HW-01 population compared with that of the sensitive (S) population ST-1. Moreover, the rapid fomesafen and nicosulfuron metabolism in the HW-01 plants was also confirmed via HPLC-MS/MS analysis. Furthermore, the HW-01 population showed multiple resistance (MR) to PPO, ALS, and PSII inhibitors, with resistance index (RI) values ranging from 3.8 to 9.6. This study confirmed MR to PPO-, ALS-, and PSII-inhibiting herbicides in the A. retroflexus population HW-01, as well as confirming that the cytochrome P450- and GST-based herbicide metabolic along with TSR mechanisms contribute to their multiple resistance to fomesafen and nicosulfuron.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49eb19f2-4948-40fa-86da-737e7b99818b', '35083f56-3855-4792-8594-c7a405b120ba', 'Environmental Antimicrobial Resistance: Implications for Food Safety and Public Health', 'Ifedinezi OV, Nnaji ND, Anumudu CK, Ekwueme CT, Uhegwu CC, Ihenetu FC, Obioha P, Simon BO', 2024, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics13111087', 'https://doi.org/10.3390/antibiotics13111087', 'https://europepmc.org/articles/PMC11591122?pdf=render', NULL, NULL, 40, NULL, 'other', 1, 'cc by', 'Antimicrobial resistance (AMR) is a serious global health issue, aggravated by antibiotic overuse and misuse in human medicine, animal care, and agriculture. This study looks at the different mechanisms that drive AMR, such as environmental contamination, horizontal gene transfer, and selective pressure, as well as the severe implications of AMR for human and animal health. This study demonstrates the need for concerted efforts across the scientific, healthcare, agricultural, and policy sectors to control the emergence of AMR. Some crucial strategies discussed include developing antimicrobial stewardship (AMS) programs, encouraging targeted narrow-spectrum antibiotic use, and emphasizing the significance of strict regulatory frameworks and surveillance systems, like the Global Antimicrobial Resistance and Use Surveillance System (GLASS) and the Access, Watch, and Reserve (AWaRe) classification. This study also emphasizes the need for national and international action plans in combating AMR and promotes the One Health strategy, which unifies environmental, animal, and human health. This study concludes that preventing the spread of AMR and maintaining the effectiveness of antibiotics for future generations requires a comprehensive, multidisciplinary, and internationally coordinated strategy.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05896e8c-637f-41ac-910a-3d0761524876', '35083f56-3855-4792-8594-c7a405b120ba', 'Environmental effects on efficacy of herbicides for postemergence goosegrass (Eleusine indica) control', 'Shekoofa A, Brosnan JT, Vargas JJ, Tuck DP, Elmore MT', 2020, 'Scientific reports', '10.1038/s41598-020-77570-5', 'https://doi.org/10.1038/s41598-020-77570-5', 'https://europepmc.org/articles/PMC7689523?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Experiments were conducted to understand environmental effects on efficacy of herbicides used to control goosegrass (Eleusine indica L. Gaertn.). Herbicides were applied to goosegrass maintained at soil moisture contents (VMC) of 20%. Herbicides included fenoxaprop-p-ethyl (140 g ha-1), topramezone (25 g ha-1), foramsulfuron (44 g ha-1), 2,4-D + dicamba + MCPP + carfentrazone (860 + 80 + 270 + 28 g ha-1), and thiencarbazone-methyl + foramsulfuron + halosulfuron-methyl (22 + 45 + 69 g ha-1). Goosegrass control increased as VMC increased. Vapor pressure deficit (VPD) and air temperature were manipulated to determine effects of evaporative demand on foramsulfuron. Effects of soil drying were also studied following foramsulfuron application. Reductions in transpiration rate (TR) and leaf area were greatest with foramsulfuron applications to goosegrass in silt-loam under high evaporative demand (3 kPa VPD, 38 °C). Foramsulfuron had no effect on goosegrass in silica-sand regardless of evaporative demand. TR dropped to 0.2 mmh-1 within eight days after application to goosegrass in silt-loam compared to 18 days in silica-sand. Overall, foramsulfuron efficacy on goosegrass was maximized under conditions of high soil moisture and evaporative demand, and may be reduced in sandy soils that hold less water.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('07a5ab0f-4cd6-42d1-b4af-4fed50019957', '35083f56-3855-4792-8594-c7a405b120ba', 'Evaluating Biochar Impact on Topramezone Adsorption Behavior on Soil under No-Tillage and Rotary Tillage Treatments: Isotherms and Kinetics', 'Uwamungu JY, Nartey OD, Uwimpaye F, Dong W, Hu C', 2019, 'International journal of environmental research and public health', '10.3390/ijerph16245034', 'https://doi.org/10.3390/ijerph16245034', 'https://europepmc.org/articles/PMC6950680?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The evaluation of biochar application on the adsorption behavior of topramezone on soil under no-tillage (NT) and rotary tillage treatments (RT) has been assessed. Fourier Transform Infra-Red Spectrometry (FTIR), scanning electron microscopy (SEM), and Brunauer-Emmett-Teller) (BET) were used for the biochar characterization. Batch experiments were carried out in a laboratory to assess the adsorption of topramezone on soil through equilibrium and kinetic modeling under biochar addition. The clay content has been found to be higher under NT (18.24 ± 0.01) than under RT (15.91 ± 0.02). The total organic carbon was higher under NT. The topramezone adsorption equilibrium reached after 8 and 12 h, for NT and RT, respectively. The kinetic and thermodynamic analyses showed the adsorption under both treatments matched with pseudo-second-order kinetic and Langmuir models, respectively. After biochar addition, the pesticide adsorption capacity (40 -1; for the soil under NT and RT at 25 °C, respectively, indicated spontaneous adsorption. Negative entropy values (ΔS); -21.92 and -78.296 J mol-1K-1, for NT and RT, respectively, explained a decreased randomness process. The enthalpy was higher (p -1) than under NT (-1313.73 J mol-1). Conclusively, it was shown that the topramezone adsorption capacity was higher under NT, and biochar addition increased more pesticide adsorption under NT than under RT.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('155d8aab-2e7f-4a82-824d-27949fc21ce7', '35083f56-3855-4792-8594-c7a405b120ba', 'Mechanism of Herbicidal Action and Rice Selectivity of Iptriazopyrid: A Novel Azole Carboxamide-Based Inhibitor of 4-Hydroxyphenylpyruvate Dioxygenase', 'Nishio T, Nishijima N, Kubota T, Furuhata Y, Nanao Y, Permana H, Furuhashi T, Kato Y', 2025, 'Journal of agricultural and food chemistry', '10.1021/acs.jafc.4c11831', 'https://doi.org/10.1021/acs.jafc.4c11831', 'https://europepmc.org/articles/PMC12203613?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by-nc-nd', '4-hydroxyphenylpyruvate dioxygenase (HPPD) inhibitors are widely used as herbicides. However, the emergence of herbicide-resistant weeds necessitates the development of new herbicides with more diverse chemical structures. Therefore, we evaluated the herbicidal and HPPD inhibitory activities of iptriazopyrid, a novel azole carboxamide compound. Phytotoxic tests on Echinochloa crus-galli demonstrated that iptriazopyrid caused chlorosis at a concentration approximately 10 times lower than that required for the common commercial HPPD inhibitor mesotrione. Furthermore, iptriazopyrid showed strong selectivity for Oryza sativa over the weed in the greenhouse-scale experiment. X-ray crystallography and in vitro inhibitory assays revealed that iptriazopyrid was bound to the enzyme active pocket of HPPD and worked as a slow-binding inhibitor. These findings indicate that this inhibitor has potent herbicidal activity with a chemical structure different from those of existing HPPD inhibitors. Thus, it has potential applications as a novel scaffold in herbicide development.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6c5e43ec-83d9-436a-aed1-67926a086d52', '35083f56-3855-4792-8594-c7a405b120ba', 'Evaluation of weed control efficacy and crop safety of the new HPPD-inhibiting herbicide-QYR301', 'Wang H, Liu W, Zhao K, Yu H, Zhang J, Wang J', 2018, 'Scientific reports', '10.1038/s41598-018-26223-9', 'https://doi.org/10.1038/s41598-018-26223-9', 'https://europepmc.org/articles/PMC5962607?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'QYR301, 1,3-Dimethyl-1H-pyrazole-4-carboxylic acid 4-[2-chloro-3-(3,5-dimethyl-pyrazol-1-ylmethyl)-4-methanesulfonyl-benzoyl]-2,5-dimethyl-2H-pyrazol-3-yl ester, is a novel HPPD-inhibiting herbicide and was evaluated to provide a reference for post-emergence (POST) application under greenhouse and field conditions. The crop safety (180 and 360 g active ingredient (a.i.) ha-1 treatments) experiment revealed that wheat, paddy, garlic and corn were the only four crops without injury at both examined herbicide rates. The weed control efficacy (60 and 120 g a.i. ha-1) experiment showed that QYR301 exhibited high efficacy against many weeds, especially weeds infesting paddy fields. Furthermore, it is interesting that both susceptible and multiple herbicide resistant Echinochloa crus-galli (L.) Beauv. and Echinochloa phyllopogon (Stapf) Koss, two notorious weed species in paddy field, remained susceptible to QYR301. Further crop tolerance results indicated that 20 tested paddy hybrids displayed different levels of tolerance to QYR301, with the japonica paddy hybrids having more tolerance than indica paddy hybrids under greenhouse conditions. Results obtained from field experiments showed that QYR301 POST at 135 to 180 g a.i. ha-1 was recommended to provide satisfactory full-season control of E. crus-galli and Leptochloa chinensis (L.) Nees and to maximize rice yields. These findings indicate that QYR301 possesses great potential for the management of weeds in paddy fields.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('61a6028f-a6e7-4128-af3f-f73406ae2731', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Agro-Techniques for Lodging Stress Management in Maize-Soybean Intercropping System-A Review', 'Raza A, Asghar MA, Ahmad B, Bin C, Iftikhar Hussain M, Li W, Iqbal T, Yaseen M', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9111592', 'https://doi.org/10.3390/plants9111592', 'https://europepmc.org/articles/PMC7698466?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Lodging is one of the most chronic restraints of the maize-soybean intercropping system, which causes a serious threat to agriculture development and sustainability. In the maize-soybean intercropping system, shade is a major causative agent that is triggered by the higher stem length of a maize plant. Many morphological and anatomical characteristics are involved in the lodging phenomenon, along with the chemical configuration of the stem. Due to maize shading, soybean stem evolves the shade avoidance response and resulting in the stem elongation that leads to severe lodging stress. However, the major agro-techniques that are required to explore the lodging stress in the maize-soybean intercropping system for sustainable agriculture have not been precisely elucidated yet. Therefore, the present review is tempted to compare the conceptual insights with preceding published researches and proposed the important techniques which could be applied to overcome the devastating effects of lodging. We further explored that, lodging stress management is dependent on multiple approaches such as agronomical, chemical and genetics which could be helpful to reduce the lodging threats in the maize-soybean intercropping system. Nonetheless, many queries needed to explicate the complex phenomenon of lodging. Henceforth, the agronomists, physiologists, molecular actors and breeders require further exploration to fix this challenging problem.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc61e972-2aed-4241-87a9-612312d12d36', '35083f56-3855-4792-8594-c7a405b120ba', 'Greenhouse and field evaluation of a novel HPPD-inhibiting herbicide, QYM201, for weed control in wheat', 'Zhang F, Bai S, Wang H, Liu W, Wang J', 2019, 'Scientific reports', '10.1038/s41598-018-38221-y', 'https://doi.org/10.1038/s41598-018-38221-y', 'https://europepmc.org/articles/PMC6367507?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'QYM201, 1-(2-chloro-3-(3-cyclopropyl-5-hydroxy-1-methyl-1H-pyrazole-4-carbonyl)-6-(trifluoromethyl)phenyl)piperidin-2-one), is a newly developed HPPD- (4-hydroxyphenylpyruvate dioxygenase; EC 1.13.11.27) inhibiting herbicide for weed control. Experiments were carried out to determine the effect of QYM201 on weeds and its safety for wheat in the glasshouse and field. The results indicated that at doses of 90 and 135 g active ingredient (a.i.) ha-1 QYM201 was highly effective against both grass and broadleaf weeds, such as Alopecurus aequalis Sobol., Alopecurus japonicus Steud, and Capsella bursa-pastoris Medic. In a wheat hybrid tolerance experiment, QYM201 showed a high level of safety for most of the 17 tested wheat hybrids, and the SI values reached ≥5.7 in the selectivity index study. To determine application rules for QYM201, field experiments were conducted in 2016 and 2017. During this time, 90 to 270 g a.i. ha-1 post-emergence herbicide application (POST) was sufficient to supply satisfactory all-season control of Alopecurus aequalis Sobol., Descurainia sophia [L.] Schur., and Malachium aquaticum (L.) Fires. No damage to wheat plants was observed. In order to increase wheat yield and deliver effective weed control, a dosage of 90 to 180 g a.i. ha-1 is suggested. In conclusion, the herbicide QYM201 is safe to use in wheat fields to control winter weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9021d849-5717-4e4d-ad04-74ce1bb9e02f', '35083f56-3855-4792-8594-c7a405b120ba', 'Herbicide Resistance Genes in Crops: Mechanisms, Progress, and Future Perspectives', 'Guo Y, Ma X, Li Z, Liu C, Chu C, Wang J, Wang Z, Jiao Z', 2026, 'Plants (Basel, Switzerland)', '10.3390/plants15172718', 'https://doi.org/10.3390/plants15172718', 'https://europepmc.org/articles/PMC13567415?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'While previous reviews have largely focused on individual crops or single target-site mechanisms, the full-chain comparative landscape across major cereal crops remains unexplored. Here, we fill this critical gap by providing the first systematic, cross-crop comparative review that spans herbicide targets, resistance mechanisms, and breeding applications across four major cereals-rice, maize, wheat, and sorghum. Weed infestation is a serious constraint on crop production. Chemical weed control faces challenges such as herbicide resistance evolution and ecological risks. Developing herbicide-resistant varieties is a fundamental approach to achieve green and sustainable weed management. This review systematically summarizes research progress on herbicide resistance genes from three aspects: herbicide classification, resistance mechanisms, and crop breeding applications. It highlights key differences among four major cereal crops (rice, maize, wheat, and sorghum) in resistance-gene discovery and translational progress. Rice has the richest target-site resistance-gene resources. Maize leads in commercialization of transgenic herbicide resistance. Wheat focuses on endogenous precise editing due to genome complexity and regulatory constraints. Sorghum relies on specific mutations to serve cereal-legume intercropping systems. Based on this comparison, this review identifies the core trends in resistance breeding: from single-gene to multi-gene stacking, and from exogenous gene introduction to endogenous gene editing. It also points out common bottlenecks, including insufficient systematic mining of resistance-gene resources, lagging elucidation of non-target-site resistance regulatory networks, and strong genotype dependence in genetic transformation. Future efforts should focus on exploring broad-spectrum resistance genes, optimizing precise editing technologies, and developing sustainable resistance management strategies. This review provides a theoretical framework and practical references for molecular breeding of herbicide-resistant crops.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('339a0de3-d9d6-4c86-a48b-75e0a3da8e74', '35083f56-3855-4792-8594-c7a405b120ba', 'Impact of Overhead Irrigation Timing on Ornamental Plant Phytotoxicity Following Preemergence Herbicide Applications', 'Yin C, Marble C, Chen J, Dale A', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14111710', 'https://doi.org/10.3390/plants14111710', 'https://europepmc.org/articles/PMC12157852?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'The use of preemergence herbicides is the primary method of controlling weeds in container-grown ornamental plants, but it may cause injury to common popular ornamentals. The objective of this research was to evaluate the use of overhead irrigation to reduce phytotoxicity in ornamental plants. Dimethenamid-P and flumioxazin were applied at standard label rates to container-grown coneflower (Echinacea purpurea), lady fern (Anthyrium filix-femina), and blue plumbago (Plumbago auriculata). Plants were subjected to one of four irrigation regimes at the time of herbicide treatment, including receiving 1.3 cm of overhead irrigation before treatment, immediately after treatment, both immediately before and after treatment, and no irrigation until the next irrigation cycle resumed at 4 h after treatment. For all three species, irrigation timing had minimal effect on visual injury ratings following treatment with dimethenamid-P, as injury was minimal overall. Severe injury was observed following treatment with flumioxazin, but significant recovery was noted in both lady ferns and echinacea when irrigation was applied immediately after treatment. The results indicate that irrigating plants immediately after treatment could improve crop tolerance to preemergence herbicide applications and should be further investigated as an injury management strategy for container-grown ornamental plants.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.440522+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4e9552aa-5444-4f22-9c55-1d42d0ce456a', '35083f56-3855-4792-8594-c7a405b120ba', 'Metabolism of the 4-Hydroxyphenylpyruvate Dioxygenase Inhibitor, Mesotrione, in Multiple-Herbicide-Resistant Palmer amaranth (Amaranthus palmeri)', 'Concepcion JCT, Kaundun SS, Morris JA, Brandenburg AN, Riechers DE', 2024, 'Journal of agricultural and food chemistry', '10.1021/acs.jafc.3c06903', 'https://doi.org/10.1021/acs.jafc.3c06903', 'https://europepmc.org/articles/PMC10959109?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by-nc-nd', 'Metabolic resistance to the maize-selective, HPPD-inhibiting herbicide, mesotrione, occurs via Phase I ring hydroxylation in resistant waterhemp and Palmer amaranth; however, mesotrione detoxification pathways post-Phase I are unknown. This research aims to (1) evaluate Palmer amaranth populations for mesotrione resistance via survivorship, foliar injury, and aboveground biomass, (2) determine mesotrione metabolism rates in Palmer amaranth populations during a time course, and (3) identify mesotrione metabolites including and beyond Phase I oxidation. The Palmer amaranth populations, SYNR1 and SYNR2, exhibited higher survival rates (100%), aboveground biomass (c.a. 50%), and lower injury (25-30%) following mesotrione treatment than other populations studied. These two populations also metabolized mesotrione 2-fold faster than sensitive populations, PPI1 and PPI2, and rapidly formed 4-OH-mesotrione. Additionally, SYNR1 and SYNR2 formed 5-OH-mesotrione, which is not produced in high abundance in waterhemp or naturally tolerant maize. Metabolite features derived from 4/5-OH-mesotrione and potential Phase II mesotrione-conjugates were detected and characterized by liquid chromatography-mass spectrometry (LCMS).', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cddfb238-d9ab-4120-a445-10cec4b27100', '35083f56-3855-4792-8594-c7a405b120ba', 'Multilevel synergistic mechanisms of a nanocarrier-enabled topramezone herbicide against invasive weeds', 'Chen J, Qiao H, Ran X, Xia J, Dong H, Wang H, Peng H, Yin M', 2026, 'Journal of nanobiotechnology', '10.1186/s12951-026-04472-5', 'https://doi.org/10.1186/s12951-026-04472-5', 'https://europepmc.org/articles/PMC13251031?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'The rapid proliferation of invasive weeds has emerged as an escalating "major threat", and the inefficient utilization and environmental dispersion of conventional herbicides pose persistent challenges in agricultural production. Herein, an amphiphilic hydrophilic-lipophilic diblock polymer (HLDP) was constructed to develop a nano-enabled topramezone (TOP) with excellent herbicidal performance toward invasive weed Cyclachaena xanthiifolia while reducing ecological risk. The HLDP displayed a high loading content of 46.22% toward TOP, and the dynamic self-assembly was spontaneously driven by hydrophobic association and hydrogen bonding, characterized by isothermal titration calorimetry, molecular docking/dynamics simulation and Fourier transform infrared spectroscopy. The encapsulation within HLDP decreased the particle size of TOP down to 102 nm to form stable spherical particles with the zeta potential of 30.13 mV, and the thermal stability of TOP was significantly improved by forming a hybrid nanostructure. Compared to free TOP, the TOP@HLDP exhibited excellent foliar behavior with reduced contact angle (1.4-fold), enhanced spray retention (2.3-fold), and increased systemic uptake (2-fold), as well as altered soil transport behavior. Notably, both laboratory and field trials demonstrated significantly enhanced herbicidal activity of TOP@HLDP compared with free and commercial formulations, resulting in stronger growth inhibition and reduced chlorophyll and nitrogen contents. Integrated transcriptomic and metabolomic analyses revealed that the complexation with HLDP further induced amplified oxidative and hormonal stress, characterized by suppressed photosynthetic electron transport, impaired NADPH generation, redirected carbon allocation, and enhanced jasmonic acid biosynthesis, which was consistent with the physiological responses in invasive weeds. Moreover, biosafety assessments confirmed the superior biocompatibility of TOP@HLDP toward non-target organisms, including fruit flies, S2 cells and maize seeds. Collectively, our study extensively elucidated the multiple synergistic mechanisms underlying the HLDP-based delivery system from dynamic self-assembly to multi-omics basis, offering a reliable strategy for designing/developing nano-herbicides with high bioactivity and excellent biocompatibility toward invasive weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6702e171-e2fc-4df0-af95-e4c96a3a436b', '35083f56-3855-4792-8594-c7a405b120ba', 'Overcoming weeds: breeding herbicide-resistant crops via directed evolution', 'Ma L, Guo Y', 2024, 'Journal of experimental botany', '10.1093/jxb/erae445', 'https://doi.org/10.1093/jxb/erae445', 'https://europepmc.org/articles/PMC11630303?pdf=render', NULL, NULL, 4, NULL, 'other', 1, 'cc by', NULL, '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2e6aafeb-a251-4089-b9ab-3271117b4a66', '35083f56-3855-4792-8594-c7a405b120ba', 'Physiological basis for isoxadifen-ethyl induction of nicosulfuron detoxification in maize hybrids', 'Sun L, Wu R, Su W, Gao Z, Lu C', 2017, 'PloS one', '10.1371/journal.pone.0173502', 'https://doi.org/10.1371/journal.pone.0173502', 'https://europepmc.org/articles/PMC5340377?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Isoxadifen-ethyl can effectively alleviate nicosulfuron injury in the maize. However, the effects of safener isoxadifen-ethyl on detoxifying enzymes in maize is unknown. The individual and combined effects of the sulfonylurea herbicide nicosulfuron and the safener isoxadifen-ethyl on the growth and selected physiological processes of maize were evaluated. Bioassays showed that the EC50 values of nicosulfuron and nicosulfuron plus isoxadifen-ethyl for maize cultivar Zhengdan958 were 18.87 and 249.28 mg kg-1, respectively, and were 24.8 and 275.51 mg kg-1, respectively, for Zhenghuangnuo No. 2 cultivar. Evaluations of the target enzyme of acetolactate synthase showed that the I50 values of nicosulfuron and nicosulfuron plus isoxadifen-ethyl for the ALS of Zhengdan958 were 15.46 and 28.56 μmol L-1, respectively, and were 0.57 and 2.17 μmol L-1, respectively, for the acetolactate synthase of Zhenghuangnuo No. 2. The safener isoxadifen-ethyl significantly enhanced tolerance of maize to nicosulfuron. The enhanced tolerance of maize to nicosulfuron in the presence of the safener, coupled with the enhanced injury observed in the presence of piperonyl butoxide, 1-aminobenzotriazole, and malathion, suggested cytochrome P450 monooxygenases may be involved in metabolism of nicosulfuron. We proposed that isoxadifen-ethyl increases plant metabolism of nicosulfuron through non-P450-catalyzed routes or through P450 monooxygenases not inhibited by piperonyl butoxide, 1-aminobenzotriazole, and malathion. Isoxadifen-ethyl, at a rate of 33 mg kg-1, completely reversed the effects of all doses (37.5-300 mg kg-1) of nicosulfuron on both of the maize cultivars. When the two compounds were given simultaneously, isoxadifen-ethyl enhanced activity of glutathione S-transferases (GSTs) and acetolactate synthase activity in maize. The free acid 4,5-dihydro-5,5-diphenyl-1,2-oxazole-3-carboxylic was equally effective at inducing GSTs as the parent ester and appeared to be the active safener. GST induction in the maize Zhenghuangnuo No. 2 was faster than in Zhengdan 958.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2c83ca07-92b9-449d-b27e-df9a86dabb07', '35083f56-3855-4792-8594-c7a405b120ba', 'The mechanism of methylated seed oil on enhancing biological efficacy of topramezone on weeds', 'Zhang J, Jaeck O, Menegat A, Zhang Z, Gerhards R, Ni H', 2013, 'PloS one', '10.1371/journal.pone.0074280', 'https://doi.org/10.1371/journal.pone.0074280', 'https://europepmc.org/articles/PMC3782475?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Methylated seed oil (MSO) is a recommended adjuvant for the newly registered herbicide topramezone in China and also in other countries of the world, but the mechanism of MSO enhancing topramezone efficacy is still not clear. Greenhouse and laboratory experiments were conducted to determine the effects of MSO on efficacy, solution property, droplet spread and evaporation, active ingredient deposition, foliar absorption and translocation of topramezone applied to giant foxtail (Setaria faberi Herrm.) and velvetleaf (Abutilon theophrasti Medic.). Experimental results showed that 0.3% MSO enhanced the efficacy of topramezone by 1.5-fold on giant foxtail and by 1.0-fold on velvetleaf. When this herbicide was mixed with MSO, its solution surface tension and leaf contact angle decreased significantly, its spread areas on weed leaf surfaces increased significantly, its wetting time was shortened on giant foxtail but not changed on velvetleaf, and less of its active ingredient crystal was observed on the treated weed leaf surfaces. MSO increased the absorption of topramezone by 68.9% for giant foxtail and by 45.9% for velvetleaf 24 hours after treatment. It also apparently promoted the translocation of this herbicide in these two weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b564f264-3db8-4920-a212-7eccab9bba18', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'An ABC-B Transporter Helps Protect Fusarium graminearum Against Enniatin Toxicity', 'Harris LJ, Bosnich W, Johnston A, Schneiderman D, Kwan R, Thapa I, Witte TE, Sproule A', 2026, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof12070524', 'https://doi.org/10.3390/jof12070524', 'https://europepmc.org/articles/PMC13412724?pdf=render', NULL, NULL, 22, NULL, 'canada', 3, 'cc by', 'Fusarium graminearum and F. avenaceum often co-contaminate Canadian durum wheat grain, resulting in the co-deposition of species-specific mycotoxins, including trichothecenes produced by F. graminearum and enniatins produced by F. avenaceum. These mycotoxins pose significant risks to human and animal health. Although these fungi commonly co-occur in infected wheat, relatively little is known about how they interact during host infection. Interactions between the two species were examined using co-inoculation experiments on durum wheat spikes. In pathology trials, co-inoculations often reduced both disease severity and trichothecene accumulation compared with inoculations of F. graminearum alone, despite F. graminearum greatly out-competing F. avenaceum in total fungal biomass. Transcriptomic profiling identified strong induction of the F. graminearum ABC transporter gene FgABCB8 during co-inoculation with an enniatin-producing F. avenaceum strain. When F. graminearum was grown in vitro, FgABCB8 was induced upon exposure to F. avenaceum culture filtrate, or the related cyclohexadepsipeptides enniatin B1 or beauvericin. Heterologous expression of FgABCB8 in yeast provided partial protection against enniatin and beauvericin toxicity. Gene disruption of FgABCB8 increased F. graminearum sensitivity to enniatins. These findings demonstrate that FgABCB8 expression enhances the ability of F. graminearum to tolerate enniatin-producing fungi.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('65c5d340-cd65-4721-b129-2e96a8b397ba', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'An integrated approach to improve plant protection against olive anthracnose caused by the Colletotrichum acutatum species complex', 'Kolainis S, Koletti A, Lykogianni M, Karamanou D, Gkizi D, Tjamos SE, Paraskeuopoulos A, Aliferis KA', 2020, 'PloS one', '10.1371/journal.pone.0233916', 'https://doi.org/10.1371/journal.pone.0233916', 'https://europepmc.org/articles/PMC7259717?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'The olive tree (Olea europaea L.) is the most important oil-producing crop of the Mediterranean basin. However, although plant protection measures are regularly applied, disease outbreaks represent an obstacle towards the further development of the sector. Therefore, there is an urge for the improvement of plant protection strategies based on information acquired by the implementation of advanced methodologies. Recently, heavy fungal infections of olive fruits have been recorded in major olive-producing areas of Greece causing devastating yield losses. Thus, initially, we have undertaken the task to identify their causal agent(s) and assess their pathogenicity and sensitivity to fungicides. The disease was identified as the olive anthracnose, and although Colletotrichum gloeosporioides and Colletotrichum acutatum species complexes are the two major causes, the obtained results confirmed that in Southern Greece the latter is the main causal agent. The obtained isolates were grouped into eight morphotypes based on their phenotypes, which differ in their sensitivities to fungicides and pathogenicity. The triazoles difenoconazole and tebuconazole were more toxic than the strobilurins being tested. Furthermore, a GC/EI/MS metabolomics model was developed for the robust chemotaxonomy of the isolates and the dissection of differences between their endo-metabolomes, which could explain the obtained phenotypes. The corresponding metabolites-biomarkers for the discrimination between morphotypes were discovered, with the most important ones being the amino acids L-tyrosine, L-phenylalanine, and L-proline, the disaccharide α,α-trehalose, and the phytotoxic pathogenesis-related metabolite hydroxyphenylacetate. These metabolites play important roles in fungal metabolism, pathogenesis, and stress responses. The study adds critical information that could be further exploited to combat olive anthracnose through its monitoring and the design of improved, customized plant protection strategies. Also, results suggest the necessity for the comprehensive mapping of the C. acutatum species complex morphotypes in order to avoid issues such as the development of fungicide-resistant genotypes.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b221d5f-a67e-43cb-b8fb-7b7eaea1bfc0', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Biochemical and Molecular Basis of Chemically Induced Defense Activation in Maize against Banded Leaf and Sheath Blight Disease', 'Shah Mahmood Hamidi, Shweta Meshram, Aundy Kumar, Archana Singh, Rajbir Yadav, Robin Gogoi', 2024, 'Current Issues in Molecular Biology', '10.3390/cimb46040192', 'https://doi.org/10.3390/cimb46040192', 'https://www.mdpi.com/1467-3045/46/4/192', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Maize is the third most vital global cereal, playing a key role in the world economy and plant genetics research. Despite its leadership in production, maize faces a severe threat from banded leaf and sheath blight, necessitating the urgent development of eco-friendly management strategies. This study aimed to understand the resistance mechanisms against banded leaf and sheath blight (BLSB) in maize hybrid “Vivek QPM-9”. Seven fungicides at recommended doses (1000 and 500 ppm) and two plant defense inducers, salicylic acid (SA) and jasmonic acid (JA) at concentrations of 50 and 100 ppm, were applied. Fungicides, notably Azoxystrobin and Trifloxystrobin + Tebuconazole, demonstrated superior efficacy against BLSB, while Pencycuron showed limited effectiveness. Field-sprayed Azoxystrobin exhibited the lowest BLSB infection, correlating with heightened antioxidant enzyme activity (SOD, CAT, POX, β-1,3-glucanase, PPO, PAL), similar to the Validamycin-treated plants. The expression of defense-related genes after seed priming with SA and JA was assessed via qRT-PCR. Lower SA concentrations down-regulated SOD, PPO, and APX genes but up-regulated CAT and β-1,3-glucanase genes. JA at lower doses up-regulated CAT and APX genes, while higher doses up-regulated PPO and β-1,3-glucanase genes; SOD gene expression was suppressed at both JA doses. This investigation elucidates the effectiveness of certain fungicides and plant defense inducers in mitigating BLSB in maize hybrids and sheds light on the intricate gene expression mechanisms governing defense responses against this pathogen.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('78c4f0a7-00a4-4f89-8961-dd8331cf93c0', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Cytochrome b gene heteroplasmy associated with QoI fungicide resistance in Venturia inaequalis populations from Northwestern Himalayas', 'Mahreena Farooq, Mushtaq A. Bhat, Najmu Sakib, Khalid Z. Masoodi, Zahoor A. Bhat, Aflaq Hamid, Fouzia Shafi, Zarka Nabi', 2026, 'Scientific Reports', '10.1038/s41598-026-62779-7', 'https://doi.org/10.1038/s41598-026-62779-7', 'https://doi.org/10.1038/s41598-026-62779-7', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Apple scab caused by the fungal pathogen Venturia inaequalis (Cke.) Wint. is one of the most destructive diseases of apple worldwide. To manage this disease and minimize economic losses, growers typically rely on multiple fungicide applications throughout the year. In the northwestern Himalayan region of India, particularly in Kashmir, the extensive and indiscriminate use of quinone outside inhibitor (QoI) fungicides has contributed to the emergence of V. inaequalis resistant strains. To assess this resistance, the baseline populations of V. inaequalis obtained from Anantnag and Srinagar districts were tested at seven different concentrations of QoI fungicides (0.001, 0.01, 0.05, 0.10, 0.50, 1.0, and 2.0 µg/ml) along with the control (0.001 µg/ml) to evaluate their mycelial growth response. The mean ED50 values for Kresoxim-methyl 44.3% SC and Trifloxystrobin (25%) + Tebuconazole (50%) 75 WG were 0.122 and 0.042 µg/ml, respectively, with corresponding resistance factor of 4.16 and 5.13 and discriminatory dose of 0.13 and 0.050 µg/ml. The evaluation of exposed and baseline populations of V. inaequalis at these discriminatory concentrations revealed a significant shift in sensitivity. The most pronounced shift was observed in district Baramulla against Trifloxystrobin (25%) + Tebuconazole (50%) 75 WG, with a growth response of 21.77 per cent to 79.12 per cent against a baseline growth response of 28.87 per cent to 67.66%. In the case of Kresoxim-methyl 44.3% SC, the major shift was observed in Shopian with a growth response of 21.33 per cent to 79.77 per cent against the baseline growth response of 31.88 per cent to 60.28 per cent. The chemical-wise analysis unveiled that the highest frequency of resistant isolates was recorded against Kresoxim-methyl 44.3% SC (18.66%), followed by Trifloxystrobin (25%) + Tebuconazole (50%) 75 WG (18.00%). Although the mycelial growth assay was effective for detecting resistance, it did not elucidate the underlying molecular mechanism. To confirm this resistance, allele-specific polymerase chain reaction was employed by using single nucleotide polymorphism primer pair, viz., VictybF (GAGTAGACGGTAGTTAATGTATTC) and VictybR (CAAACCTTATGAGTGCTATACCGT). This amplification successfully yielded a 216 bp targeted fragment in all V. inaequalis isolates showing resistance to QoI fungicides. The sequencing of the amplified product revealed heteroplasmy at codon G143A, explaining the variability in resistance among isolates. This research confirms the first report of QoI fungicide resistance in V. inaequalis from Kashmir valley and highlights the rapid emergence of resistant populations and emphasizing the urgent need for the adoption of integrated fungicide resistance management strategies to sustain effective disease control.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c633449d-f3ba-4838-a217-3b44536917e5', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Defending rice crop from blast disease in the context of climate change for food security in Nepal', 'Khadka RB, Manandhar HK, Shrestha S, Acharya B, Sharma P, Baidya S, Luu VS, Joshi KD', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1511945', 'https://doi.org/10.3389/fpls.2025.1511945', 'https://europepmc.org/articles/PMC12238087?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Blast, caused by Pyricularia oryzae (teleomorph Magnaporthe oryzae), is one of the most devastating diseases in rice, causing 10-30% yield losses and threatening Nepal''s food and nutritional security. The Himalayan foothills are hotspots for blast fungus diversity, leading to the rapid emergence of pathotypes that overcome resistance in mega rice varieties. In 2022, a neck blast epidemic devastated 5,000 hectares of Hardinath-1, a dry winter/spring rice variety in Chitwan, causing nearly 100% yield loss. The changing climate, especially during panicle initiation stages, has become more favourable for neck blast development. We reviewed 40 years of research and development on rice blast in Nepal, analysing historical weather patterns and mapping the incidence and severity of the disease across the country based on empirical observations and field experiments. Using historical data on rice blast incidence and climate information, we show that rice blast pressure is increasing intensively and changing weather patterns are becoming more favourable for rice blast epidemics. We identify emerging issues in rice blast and propose integrated strategies for effective management in Nepal. Key approaches include developing durable blast-resistant and climate-resilient rice varieties using molecular markers and genomic tools and speed breeding, forecasting disease and pathotype emergence, and combining these with careful use of modern fungicides, plant defence activators, and biological control. Additionally, adjusting planting times, managing weeds, optimising agronomic practices, and ensuring proper water and nutrient management are essential for sustainable blast management.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e54c09ea-1a15-4a4e-b245-80c2b03c445b', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Detection of Venturia inaequalis Isolates with Multiple Resistance in Greece', 'Chatzidimopoulos M, Zambounis A, Lioliopoulou F, Vellios E', 2022, 'Microorganisms', '10.3390/microorganisms10122354', 'https://doi.org/10.3390/microorganisms10122354', 'https://europepmc.org/articles/PMC9780820?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The excessive use of fungicides against Venturia inaequalis, the causal agent of apple scab, has led to the emergence of resistant populations to multiple fungicides over the years. In Greece, there is no available information on fungicide resistance, despite the fact that control failures have been reported on certain areas. An amount of 418 single-spore isolates were collected from three major apple production areas and tested for their sensitivity to eight commonly used fungicides from unrelated chemical groups. The isolates were tested on malt extract agar media enriched with the discriminatory dose of each fungicide using the point inoculation method. To define the discriminatory dose for assessing the levels of resistance, EC50 values on both spore germination and mycelial growth assays were previously determined. Isolates exhibiting high resistance to trifloxystrobin (92% in total) and difenoconazole (3%); and moderate resistance to cyprodinil (75%), dodine (28%), difenoconazole (36%), boscalid (5%), and fludioxonil (7%) were found for the first time in Greece. A small percentage of the isolates were also found less sensitive to captan (8%) and dithianon (6%). Two isolates showed various levels of resistance to all eight fungicides. Despite the occurrence of strains with multiple resistances to many fungicides, we concluded that this practical resistance in the field arose mainly due to the poor control of apple scab with trifloxystrobin and difenoconazole.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('908cce3a-c0a5-44b7-89cd-001c321647d5', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Editorial: Current advancements in real-time plant pathogen diagnostics: from lab assays to in-field detection', 'Kumar R, Kumar Lal M, Prasad P, Tiwari RK', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1255654', 'https://doi.org/10.3389/fpls.2023.1255654', 'https://europepmc.org/articles/PMC10436612?pdf=render', NULL, NULL, 3, NULL, 'other', 1, 'cc by', NULL, '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f4a78e49-a7a7-4654-8366-5fab971daeb5', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Effect of Combining Wuyiencin and Pyrimethanil on Controlling Grape Gray Mold and Delaying Resistance Development in Botrytis cinerea', 'Xie J, Li B, Li J, Zhang K, Ran L, Ge B', 2024, 'Microorganisms', '10.3390/microorganisms12071383', 'https://doi.org/10.3390/microorganisms12071383', 'https://europepmc.org/articles/PMC11279109?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'By screening the compounding combination of Wuyiencin and chemical agents, this study aims to delay the emergence of chemical agent resistance, and provide a technical reference for scientific and rational fungicides technology. This study investigated the impacts of the antibiotic wuyiencin derived from Streptomyces albulus var. wuyiensis and its combination with pyrimethanil on the inhibition of Botrytis cinerea. Treatment with wuyiencin (≥80 µg mL-1) strongly inhibited the pathogenicity of B. cinerea and activated the plant defense response against B. cinerea. Application of 80-100 µg mL-1 wuyiencin effectively controlled grape gray mold (by 57.6-88.1% on leaves and 46.7-96.6% on fruits). Consequently, the application of 80-100 µg mL-1 wuyiencin effectively mitigated grape gray mold incidence, leading to a substantial reduction in disease symptoms to nearly imperceptible levels. When wuyiencin (at the median effective concentration [EC50]) was combined with pyrimethanil (EC50) at a ratio of 7:3, it exhibited the highest efficacy in inhibiting B. cinerea growth. This combination was significantly more potent (p < 0.05) than using wuyiencin or pyrimethanil alone in controlling gray mold on grape leaves and fruits. Furthermore, the combination effectively delayed resistance development in gray mold. The experimental results show that wuyiencin can delay resistance development by affecting the expression of methionine biosynthesis genes and reducing the activity of the cell wall-degrading enzyme activity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a578e8b7-a774-4ec9-afa3-b91f96487ca5', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Evaluation of fungicides to manage rice false smut (Ustilaginoidea virens) in the hills of Nepal', 'Sharma P, Khadka RB, Baidya S', 2024, 'Heliyon', '10.1016/j.heliyon.2024.e34151', 'https://doi.org/10.1016/j.heliyon.2024.e34151', 'https://europepmc.org/articles/PMC11305170?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc', 'Rice False Smut (RFS) caused by Ustilaginoidea virens is a major emerging disease of rice due to expanded area of hybrid rice cultivars, increasing use of nitrogenous fertilizers and change in climate. Due to the increasing incidences of this disease across the globe, there is a pressing need to develop techniques for false smut management. The application of fungicides with high efficiency, low toxicity, and low residue is currently the best option to control RFS. Therefore, current research was conducted to determine the effectiveness of fungicides to manage RFS. The experiments were conducted in a completely randomized block design with three replications of seven treatments at RFS-prone subtropical hills of Nepal in the main rice growing season, during 2020 and 2021. The fungicides include trifloxystrobin 25 % + tebuconazole 50 %, chlorothalonil 75 %, carbendazim 12 % + mancozeb 63 %, propiconazole 25 %, azoxystrobin 50 %, carbendazim 50 % and untreated control. Fungicides were applied as two foliar sprays, one at booting and the other at flowering. Fungicide spray significantly increased number of tillers per plant (P ≤ 0.01) and reduced the number of false smut-infected tillers per plant (P ≤ 0.05), false smut severity (P ≤ 0.05), and incidence (P ≤ 0.05). False smut incidence percentages were significantly reduced by all the fungicides except mancozeb + carbendazim compared to the non-treated control. The reduction in RFS incidence was 70 % in propiconazole, 71 % in trifloxystrobin + tebuconazole sprayed plots compared to the non-treated control plots. Thus, the application of suitable fungicide at the appropriate stage would give the satisfactory suppression of RFS in a farmers'' field in Nepal.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a8c53f0a-bcb4-49b6-9f3c-d3c86ccf7790', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Evidence of Resistance to QoI Fungicides in Contemporary Populations of Mycosphaerella fijiensis, M. musicola and M. thailandica from Banana Plantations in Southeastern Brazil', 'Tamiris Y. K. Oliveira, Tatiane C. Silva, Silvino I. Moreira, Felix S. Christiano, Maria C. G. Gasparoto, Bart A. Fraaije, Paulo C. Ceresini', 2022, 'Agronomy', '10.3390/agronomy12122952', 'https://doi.org/10.3390/agronomy12122952', 'https://www.mdpi.com/2073-4395/12/12/2952', NULL, NULL, 19, NULL, 'other', 1, 'open access (DOAJ)', 'Yellow and black Sigatoka, caused by Mycosphaerella fijiensis and M. musicola, respectively, are the most important worldwide foliar diseases of bananas. Disease control is heavily dependent on intensive fungicide sprays, which increase selection pressure for fungicide resistance in pathogen populations. The primary objective of this study was to assess the level and spread of resistance to quinone-outside inhibitors (QoI—strobilurin) fungicides in populations of both pathogens sampled from banana fields under different fungicide spray regimes in Southeastern Brazil. Secondly, we aimed to investigate when QoI resistance was confirmed if this was associated with the target-site alteration G143A caused by a mutation in the mitochondrial encoded cytochrome b gene. QoI resistance was detected in fungicide treated banana fields, while no resistance was detected in the organic banana field. A total of 18.5% of the isolates sampled from the pathogens’ populations were resistant to QoI. The newly described M. thailandica was also found. It was the second most abundant Mycosphaerella species associated with Sigatoka-like leaf spot symptoms in the Ribeira Valley and the highest level of QoI resistance was found for this pathogen. The G143A cytochrome b alteration was associated with the resistance to the QoI fungicides azoxystrobin and trifloxystrobin in M. fijiensis, M. musicola and M. thailandica strains. In order to reduce resistance development and maintain the efficacy of QoI fungicides, anti-resistance management strategies based on integrated disease management practices should be implemented to control the Sigatoka disease complex.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0a3bbdbe-c3d7-45f0-bdff-91e6a6b91cd1', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Exogenous Tebuconazole and Trifloxystrobin Regulates Reactive Oxygen Species Metabolism Toward Mitigating Salt-Induced Damages in Cucumber Seedling', 'Mohsin SM, Hasanuzzaman M, Bhuyan MHMB, Parvin K, Fujita M', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8100428', 'https://doi.org/10.3390/plants8100428', 'https://europepmc.org/articles/PMC6843131?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'The present study investigated the role of tebuconazole (TEB) and trifloxystrobin (TRI) on cucumber plants (Cucumis sativus L. cv. Tokiwa) under salt stress (60 mM NaCl). The cucumber plants were grown semi-hydroponically in a glasshouse. Plants were exposed to two different doses of fungicides (1.375 µM TEB + 0.5 µM TRI and 2.75 µM TEB + 1.0 µM TRI) solely and in combination with NaCl (60 mM) for six days. The application of salt phenotypically deteriorated the cucumber plant growth that caused yellowing of the whole plant and significantly destructed the contents of chlorophyll and carotenoids. The oxidative damage was created under salinity by increasing the contents of malondialdehyde (MDA), hydrogen peroxide (H2O2), and electrolytic leakage (EL) resulting in the disruption of the antioxidant defense system. Furthermore, in the leaves, stems, and roots of cucumber plants increased Na+ content was observed under salt stress, whereas the K+/Na+ ratio and contents of K+, Ca2+, and Mg2+ decreased. In contrast, the exogenous application of TEB and TRI reduced the contents of MDA, H2O2, and EL by improving the activities of enzymatic and non-enzymatic antioxidants. In addition, ion homeostasis was regulated by reducing Na+ uptake and enhanced K+ accumulation and the K+/Na+ ratio after application of TEB and TRI. Therefore, this study indicates that the exogenous application of TEB and TRI enhanced salt tolerance in cucumber plants by regulating reactive oxygen speciesproduction and antioxidant defense systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ef19249-c0a0-42f4-b1a9-b0a587c0fb09', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Research to Fungicide Sensitivity of Colletotrichum spp. Isolated from Apple Fruits in Cheongsong, Korea', 'Jungyeon Kim, Heung Tae Kim, Yongho Jeon', 2023, 'Research in Plant Disease', '10.5423/RPD.2023.29.2.145', 'https://doi.org/10.5423/RPD.2023.29.2.145', 'http://online-rpd.org/upload/pdf/RPD-2023-29-2-145.pdf', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'Apple grower in the Cheongsong region, Korea has reported the increased loss of apple yield due to severe bitter rot incidence. We noticed that this indience is because the Colletotrichum population has developed resistance to commonly used fungicides. We isolated 39 Colletotrichum isolates from 13 orchards in Cheongsong, and all the isolated Colletotrichum species were identified as C. siamense or C. fructicola. These 39 strains were tested for mycelial growth and conidial germination against 12 fungicides. trifloxystrobin (30–55% in recommended concentrations) was shown lower inhibitory effect on mycelial growth. However, the inhibition of conidial germination was shown higher than mycelial growth (62–100%). Kresoxim-methyl was shown lower inhibitory effect on mycelial growth (29–55%). conidial germination inhibitory effect was shown 51% to 96%. dithianon was shown diversity response to inhibition of mycelial growth (43–100%). tebuconazole was shown high inhibitory effect on mycelial growth (84–100%) and conidial germination inhibitory effect was shown to be 64 to 100%. metconazole has been found to display with high inhibitory effect on mycelial growth (79–100%) and conidial germination (70–80%). fluazinam was shown to possess high inhibitory effect on mycelial growth (87–100%) and conidial germination (94–100%). This study provides basic information for the effective management of apple bitter rot.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ef1b3bf8-4f26-436f-a73f-0bff36e9390f', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Farmers'' perceptions on tomato early blight, fungicide use factors and awareness of fungicide resistance: Insights from a field survey in Kenya', 'Nuwamanya AM, Runo S, Mwangi M', 2023, 'PloS one', '10.1371/journal.pone.0269035', 'https://doi.org/10.1371/journal.pone.0269035', 'https://europepmc.org/articles/PMC9870120?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Early blight (EB) caused by Alternaria solani is one of the most devastating tomato diseases in Kenya and is most often managed by application of synthetic fungicides. However, there have been reports from farmers about the declining efficacy of some fungicides. These reports suggest that A. solani populations in Kenya could be developing resistance to some of the commonly used fungicides. In this study, we surveyed 175 tomato fields, sampled in 3 major tomato producing counties in Kenya, to determine the status of EB, management practices, and fungicide use factors that could contribute to development of resistance to fungicides among A. solani populations in Kenya. Data was recorded on farm characteristics, EB prevalence, fungicide usage, and farmers'' perceptions on fungicide efficacy. EB was prevalent in 85% of the fields and 90% of the farmers identified it as a major cause of yield loss. Tomato was grown all year round on 60% of the fields with only short fallow periods. All farmers reported that they were relying on fungicides for EB control and none among the cultivars grown was resistant to the disease. A total of 40 fungicide products, representing 20 active compounds with varying FRAC resistance risk levels were in use against EB. Majority (83%) of the farmers were applying fungicides at dosages and frequencies higher than those indicated on labels. Most farmers (81%) indicated that they had observed declines in effectiveness of at least one fungicide, used at EB control. This observation was more with fungicides in the strobilurin and triazole groups. These findings demonstrate that the current tomato production systems in Kenya do not take into account the risk of A. solani developing resistance to fungicides. Enhancing farmers'' knowledge of the disease and their ability to properly select and apply fungicides is therefore crucial for effective control of EB and mitigating the high risk of fungicide resistance build up.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03341e2d-4ef3-4485-afc1-4ba96278e282', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Analysis of the Free Amino Acid Profile of Barley Grain from Organic Fertilisation with Ash from Biomass Combustion', 'Czernicka M, Puchalski C, Pawlak R, Szostek M, Szpunar-Krok E', 2023, 'Molecules (Basel, Switzerland)', '10.3390/molecules29010095', 'https://doi.org/10.3390/molecules29010095', 'https://europepmc.org/articles/PMC10779924?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Fertilisation with ash from biomass combustion has a positive effect on the quality of nutrients in agrifood raw materials, improving their chemical composition and bioavailability. In the experiments carried out, the protein content and the profile of free amino acids in barley flour were examined from cultivation fertilised with biomass ash at various doses. Barley flour from Haplic Luvisol soil was characterised by a significantly higher (by 13.8% on average) total protein content compared to flour obtained from grains from Gleyic Chernozem soil. The highest protein content but a low content of free amino acids were found in the grains of plants fertilised with the mineral NPK (D1). An increase in the total pool of free amino acids in flour was observed, especially in the case of Haplic Luvisol soil. On average, after fertilising, significantly more ASP, ASN, GLU, GLY, ALA, and CYS were obtained in variant D4 (1.5 t·ha-1), and there were also significantly more TAU and GABA than in the control, up by 30.2% and 23%, respectively. A beneficial effect of fertilisation on the essential amino acid content in barley flour was found, but only up to the dose of D4, when it was significantly higher than in the control and under mineral fertilising (D1), up by 23.7% and 9.2%, respectively. High ash doses reduced the content of free amino acids in the tested barley flour. This study confirmed that using an alternative method of fertilising with plant biomass ash has a beneficial effect on protein quality and nutritional value.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0fe03813-2739-47fb-b4f4-28dcc116c006', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Impact of Biological and Chemical Seed Treatments on Wilt of Castor (Ricinus communis L.) Caused by Fusarium oxysporum f. sp. ricini', 'A. Chandini, R. D. Prasad, K. Sakthivel, P. Duraimurugan, K. S. V. P. Chandrika, Ch. Sarada, M. Suresh', 2025, 'International Journal of Economic Plants', '10.23910/2/2025.6352a', 'https://doi.org/10.23910/2/2025.6352a', 'https://ojs.pphouse.org/index.php/IJEP/article/view/6717', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'The experiment was conducted during January, 2024-March, 2025 at ICAR-IIOR, plant pathology unit to study the impact of various biological and chemical treatments on controlling the most important wilt disease caused by Fusarium oxysporum f. sp. ricini in castor crop. The biocontrol agent Trichoderma harzianum, Th4d strain and castor wilt virulent pathogen, Fusarium oxysporum f. sp. ricini were sourced from the ICAR-IIOR Pathology Unit. The impact of chemical and biological seed treatments i.e., Vitavax (carboxin 37.5%+thiram 37.5% WS at 3.0 g kg-1), T. harzianum Triguard Th-WP (Th4d 1.5% WP at 10.0 g kg-1) and Evergol xtend (penflufen 13.28% w/w+trifloxystrobin 13.28% w/w FS at 1.0 ml kg-1) against castor wilt through poisoned food technique under in vitro and pot culture study under in vivo conditions. Among the different treatments tested, Th4d was effective in reducing disease incidence by 26.1% and 28.1% respectively under in vitro and in vivo conditions. The results suggest that seed treatment with chemical fungicides and the biological control agent can be effective in management of the wilt pathogens. The concerns over environmental impacts of chemicals, their toxicity and possibility of development pathogen resistance have led to a shift towards more sustainable solutions. In this context, the biological seed treatment with Trichoderma Th4d strain has emerged as a promising method for managing the wilt pathogen in castor.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('50bcffa8-cac9-4f79-ae50-05c6d19dcd01', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Improving Soybean Development and Grain Yield by Complementary Inoculation with Growth-Promoting Bacteria Azospirillum, Pseudomonas, Priestia, and Bacillus', 'Marchão RL, Silva GCD, Andrade SRM, Junior FBDR, Júnior MPB, Haphonsso RH, Carvalho AM', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14030402', 'https://doi.org/10.3390/plants14030402', 'https://europepmc.org/articles/PMC11821028?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Bioinputs are natural products applied to crops that contribute to more sustainable agriculture by boosting yields and reducing environmental impacts. In Brazil, the use of bioinputs such as Bradyrhizobium in soybean has been consolidated, but the expansion of on-farm bioinput production is currently initiating a new revolution. Furthermore, applications of bioinputs to cash crops in Brazil have shed light on the great potential of such growth-promoting microorganisms (GMPs) to improve nutrient uptake and increase productivity. This study explores the effect of the complementary inoculation with growth-promoting bacteria of post-emergence soybean, previously inoculated with Bradyrhizobium spp. Five treatments with growth-promoting bacteria were evaluated: T1-Control (no inoculation); T2-Azospirillum brasilense; T3-Pseudomonas fluorescens and Azospirillum brasilense; T4-Priestia aryabhattai, Bacillus haynesii, and Bacillus circulans; and T5-Priestia megaterium and Bacillus subtilis. In comparison with the control, all treatments with growth-promoting bacteria of the genera Azospirillum, Pseudomonas, Priestia, and Bacillus, applied after soybean emergence, induced 4-7% higher grain yields. Co-inoculation with Priestia megaterium and Bacillus subtilis (treatment T5) resulted in a higher 1000-grain weight, while Priestia aryabhattai, Bacillus haynesii, and Bacillus circulans (treatment T4) increased the number of pods and shoot dry weight. Our conclusion is that bioinputs increase soybean productivity and make agriculture more sustainable and efficient.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3a192c28-1ae1-4cbe-bc8b-76e43860de89', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Investigating the impact of fungicides and mungbean genotypes on the management of pod rot disease caused by Fusarium equiseti and Fusarium chlamydosporum', 'Harwinder Singh Buttar, Amarjit Singh, Asmita Sirari,  Anupam, Komalpreet Kaur, Abhishek Kumar, Milan Kumar Lal, Rahul Kumar Tiwari', 2023, 'Frontiers in Plant Science', '10.3389/fpls.2023.1164245', 'https://doi.org/10.3389/fpls.2023.1164245', 'https://www.frontiersin.org/articles/10.3389/fpls.2023.1164245/full', NULL, NULL, 15, NULL, 'other', 1, 'open access (DOAJ)', 'IntroductionMungbean is a vital pulse crop in India that can thrive in dry-land conditions and is grown in three seasons, with the added benefit of being used as green manure due to its ability to fix atmospheric nitrogen. Recently, pod rot disease has emerged as a serious threat to mungbean cultivation in India.MethodsIn this study, morpho-molecular identification of associated pathogens and the bio-efficacy of systemic and non-systemic fungicides as well as genotype screening was performed during the years 2019 and 2020. The pathogens associated with this disease were confirmed on the basis of morphological and molecular characterization. For the molecular characterization, the translation elongation factor 1-alpha (tef-1) gene sequences were amplified by using primers (EF1 and EF2).ResultsUnder in vitro conditions, trifloxystrobin + tebuconazole 75% WG was found to be the most effective against Fusarium equiseti (ED50 2.39 μg ml−1) and Fusarium chlamydosporum (ED50 4.23 μg ml−1) causal agents of pod rot of mungbean. Under field conditions, three applications of trifloxystrobin + tebuconazole 75% WG at 0.07% as a foliar application at fortnightly intervals starting from the last week of July proved to be the most effective against pod rot disease on mungbean cultivars, i.e., ML 2056 and SML 668. To identify the potential resistance sources, 75 interspecific derivative and mutant lines of mungbean were screened for disease reaction to pod rot under natural epiphytotic conditions for the years 2019 and 2020. Genotypic differences were observed for resistance to pod rot disease. The study revealed that among the tested genotypes, ML 2524 exhibited resistance to pod rot disease, with a disease incidence of 15.62% and disease severity of 7.69%. In addition, 41 other genotypes were found to be moderately resistant (MR) to the disease.ConclusionAltogether, the identified management options will offer an immediate solution to manage this disease under recent outbreak conditions and pave a path for futuristic disease management using identified resistant sources in breeding programs.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6ad67999-9dfd-4485-8c0c-7b7dd5394729', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Management of Panonychus ulmi with Various Miticides and Insecticides and Their Toxicity to Predatory Mites Conserved for Biological Mite Control in Eastern U.S. Apple Orchards', 'Joshi NK, Phan NT, Biddinger DJ', 2023, 'Insects', '10.3390/insects14030228', 'https://doi.org/10.3390/insects14030228', 'https://europepmc.org/articles/PMC10052967?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Panonychus ulmi (Koch) (Acari: Tetranychidae), commonly known as European red mite, is a polyphagous pest of various tree and small fruit crops, including apples. A field study was conducted to evaluate different pesticide options available for the management of P. ulmi, and their impact on the population of non-target predatory mite species complex consisting of Neoseiulus fallacis, Typhlodromus pyri, and Zetzellia mali in apple orchards. Pesticides were applied using a commercial airblast sprayer at the 3-5 mite/leaf recommended economic Integrated Pest Management (IPM) threshold or prophylactically in the spring ignoring IPM practices such as monitoring, reliance on biological control and economic thresholds. Effects on the motile and egg stages of P. ulmi were evaluated as were effects on the populations of predatory mites through frequent leaf counts during the season. We also recorded the subsequent overwintering eggs of P. ulmi from each pesticide treatment. The two prophylactic treatments containing a mixture of zeta-cypermethrin + avermectin B1 + 1% horticultural oil and abamectin + 1% horticultural oil provided effective control of P. ulmi population throughout the season without reducing predatory mite populations. In contrast, eight treatments applied at the recommended economic threshold of 3-5 mites/leaf were not effective in suppressing P. ulmi populations and most reduced predatory mites. Etoxazole had significantly higher number of overwintering P. ulmi eggs compared to all other treatments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('25ad591a-b4ff-49dc-b429-d613889c4bad', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Management of Root Rot (Rhizoctonia solani Kühn) of Common Bean Using Host Resistance and Consortia of Chemicals and Biocontrol Agents', 'Parajuli P, Yadav RK, Manandhar HK, Parajulee MN', 2025, 'Biology', '10.3390/biology14030235', 'https://doi.org/10.3390/biology14030235', 'https://europepmc.org/articles/PMC11939670?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Rhizoctonia root rot and web blight caused by Rhizoctonia solani Kühn is one of the destructive diseases of the common bean (Phaseolus vulgaris L.). A two-year study was conducted (2019-2021) to evaluate the common bean landraces and genotype, biocontrol agents, and chemical fungicides against the pathogen. Nine landraces from high-altitude agriculture in the Jumla district in western Nepal (29.27443900, 82.19332200; 2540 m msl) and one genotype of commercial common bean from the sub-tropical Chitwan district in central Nepal (27.65186564, 84.34869288; 256 m masl) were evaluated for resistance against the pathogen under screenhouse and field conditions. All were found highly susceptible to the pathogen and the highest lesion length (3.02 cm) was measured in the Rato Male Simi followed by Rato Sano Chhirke Simi (2.40 cm) in Chitwan conditions. Three chemical fungicides-SAAF™ (carbendazim 12% + mancozeb 63% WP), Vitavax® (carboxin 37.5% + thiram 37.5% DS), and Nativo® (tebuconazole 50% + trifloxystrobin 25% w/w (75 WG)-and three biocontrol agents-Trichoderma viride (109 cfu/mL), Pseudomonas fluorescens (109 cfu/mL), and Bacillus subtilis (108 cfu/mL)-were evaluated as seed and soil treatments in fourteen different combinations against R. solani. SAAF™ and Vitavax® were found highly effective as they completely suppressed the incidence of pre-emergence damping off. SAAF™ was equally effective followed by Vitavax® and Nativo® in suppressing post-emergence damping off. On the other hand, the highest disease incidence (26.63%) was recorded in treatment where seed treatment with Pseudomonas fluorescens formulation at the rate of 10 g per kg of FYM slurry along with soil application with Pseudomonas fluorescens formulation at the rate of 10 kg per ha with 50 kg FYM was applied, whereas the lowest disease incidence (4.96%) occurred in SAAF™ for both seed and soil applications. Highest grain yield (4125 kg/ha) was recorded on Nativo® where seed treatment at the rate of 1.5 g per kg along with soil drenching at the rate of 1.5 g per liter was used. Thus, it can be concluded that the best control for pre-emergence damping off was achieved by SAAF™ where seed treatment at the rate of 2 g per kg along with soil drenching at the rate of 2 g per liter and Vitavax® as seed treatment at the rate of 2 g per kg along with soil drenching at the rate of 2 g per liter was used, while the best control of post-emergence damping off was achieved with combined seed treatment and soil treatment with SAAF™. There was no incidence of web blight throughout the growing period. Our findings could be useful in devising strategies for the integrated management of R. solani causing root rot disease in common beans.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('60182ded-ef65-4412-824d-9f42c62473f1', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Modification of the existing maximum residue levels in various plant commodities resulting from the use of potassium phosphonates', 'Bellisai G, Bernasconi G, Carrasco Cabrera L, Castellan I, Del Aguila M, Ferreira L, Greco L, Jarrah S', 2024, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2024.8842', 'https://doi.org/10.2903/j.efsa.2024.8842', 'https://europepmc.org/articles/PMC11181129?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by-nd', 'In accordance with Article 6 of Regulation (EC) No 396/2005, the applicants De Sangosse SAS and Tilco-Alginure submitted two requests, respectively, to the competent national authorities in France and Germany to modify the existing maximum residue levels (MRLs) for the active substance potassium phosphonates in various plant commodities. The data submitted in support of the requests were found to be sufficient to derive MRL proposals for the commodities under assessment. For the derived MRL on baby leaf crops, further risk manager consideration is required to decide between two MRL options. Adequate analytical methods for enforcement are available to control the residues of potassium phosphonates in accordance with the residue definition ''phosphonic acid and its salts expressed as phosphonic acid'' in the commodities under consideration. Based on the risk assessment results and assuming that the existing MRLs will be amended as proposed by EFSA in previous outputs, EFSA concluded that the long-term intake of residues resulting from the existing uses of fosetyl and phosphonates (previously assessed in a joint MRL review) and new proposed uses of potassium phosphonates is unlikely to present a risk to consumer health. Considering the toxicological profile of the active substance, a short-term dietary risk assessment was not required. The risk assessment shall be regarded as indicative because some MRL proposals derived by EFSA in the framework of the MRL review according to Articles 12 and 43 of Regulation (EC) No 396/2005 require further consideration by risk managers.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('27f8709c-505e-42be-96d0-bcf35eabfbb6', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Multi-model risk assessment of pesticide residues in seasonal fruits based on integrated targeted/non-targeted screening: Implications for vulnerable populations', 'Si W, Song Y, Guo C, Huang Z, Chen L, Xu F, Bai B, Huo K', 2025, 'Food chemistry: X', '10.1016/j.fochx.2025.102599', 'https://doi.org/10.1016/j.fochx.2025.102599', 'https://europepmc.org/articles/PMC12167114?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by-nc-nd', 'This study comprehensively analyzed multiple pesticide residues and their characteristics in commercially available fruits using integrated targeted and non-targeted techniques, with a focus on assessing health risks for children and pregnant women based on cumulative dietary risk models. Results showed 745 samples (7 categories) identified 54 pesticides (88.6 % detection rate; 1.1 % exceeding legal limits), with strawberries and peaches of the highest detection rates (98 %), and grapes the most diverse residues (avg. 6/sample). Risk ranking analysis flagged difenoconazole and indoxacarb as high-risk. Chronic cumulative exposure risks were dominated by hepatotoxic triazole fungicides. Acute risk assessments revealed potential hepatotoxicity concerns for children (3-6 years) and pregnant women consuming grapes/peaches. The Relative Potency Factor (RPF) model, accounting for synergism, showed 4-7 times higher neuro/hepatotoxicity risks than the Hazard Index (HI) model. This first integration of non-targeted screening with multi-model risk assessment provides evidence for strengthening pesticide regulation and protecting sensitive subpopulations.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('659352bb-321c-430f-b876-43528a16e045', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'New Insights into Leaf Physiological Responses to Ozone for Use in Crop Modelling', 'Osborne S, Pandey D, Mills G, Hayes F, Harmens H, Gillies D, Büker P, Emberson L', 2019, 'Plants (Basel, Switzerland)', '10.3390/plants8040084', 'https://doi.org/10.3390/plants8040084', 'https://europepmc.org/articles/PMC6524376?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Estimating food production under future air pollution and climate conditions in scenario analysis depends on accurately modelling ozone (O₃) effects on yield. This study tests several assumptions that form part of published approaches for modelling O₃ effects on photosynthesis and leaf duration against experimental data. In 2015 and 2016, two wheat cultivars were exposed in eight hemispherical glasshouses to O₃ ranging from 22 to 57 ppb (24 h mean), with profiles ranging from raised background to high peak treatments. The stomatal O₃ flux (Phytotoxic Ozone Dose, POD) to leaves was simulated using a multiplicative stomatal conductance model. Leaf senescence occurred earlier as average POD increased according to a linear relationship, and the two cultivars showed very different senescence responses. Negative effects of O₃ on photosynthesis were only observed alongside O₃-induced leaf senescence, suggesting that O₃ does not impair photosynthesis in un-senesced flag leaves at the realistic O₃ concentrations applied here. Accelerated senescence is therefore likely to be the dominant O₃ effect influencing yield in most agricultural environments. POD was better than 24 h mean concentration and AOT40 (accumulated O₃ exceeding 40 ppb, daylight hours) at predicting physiological response to O₃, and flux also accounted for the difference in exposure resulting from peak and high background treatments.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8bd25062-a72b-4271-8352-20bc2e353978', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Proteomic Strategies on the Management of Phytopathogenic Fungi', 'Corrêa ANR, Ritter AC, Brandelli A', 2025, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof11040306', 'https://doi.org/10.3390/jof11040306', 'https://europepmc.org/articles/PMC12028383?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Phytopathogenic fungi are important causative agents of many plant diseases, resulting in substantial economic losses in agriculture. Proteomics has become one of the most relevant high-throughput technologies, and current advances in proteomic methodologies have been helpful in obtaining massive biological information about several organisms. This review outlines recent advances in mass spectrometry-based proteomics applied to the study of phytopathogenic fungi, including analytical platforms such as LC-MS/MS and MALDI-TOF, as well as quantitative strategies including TMT, iTRAQ, and label-free quantification. Key findings are presented from studies exploring infection-related protein expression, virulence-associated factors, post-translational modifications, and fungal adaptation to chemical fungicides, antimicrobial peptides, and biological control agents. Proteomic analyses have also elucidated mechanisms of resistance, oxidative stress response, and metabolic disruption following exposure to natural products, including essential oils and volatile organic compounds. The proteomic approach enables a comprehensive understanding of fungal biology by identifying proteins related to pathogenicity, stress adaptation, and antifungal resistance, while also facilitating the discovery of molecular targets and natural compounds for the development of sustainable antifungal strategies that reduce risks to human health and the environment.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cc12a1cf-7e5b-45a9-a74e-d3e86f299946', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Recent advances in targeted fungicides and immune elicitors for rice blast management', 'Shi H, Naqvi NI, Kou Y', 2024, 'Plant communications', '10.1016/j.xplc.2024.101032', 'https://doi.org/10.1016/j.xplc.2024.101032', 'https://europepmc.org/articles/PMC11412917?pdf=render', NULL, NULL, 3, NULL, 'other', 1, 'cc by-nc-nd', NULL, '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0df4483f-a507-4e76-91d8-47f85ea95def', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Response of Soil Microbiota, Enzymes, and Plants to the Fungicide Azoxystrobin', 'Baćmaga M, Wyszkowska J, Kucharski J', 2024, 'International journal of molecular sciences', '10.3390/ijms25158104', 'https://doi.org/10.3390/ijms25158104', 'https://europepmc.org/articles/PMC11311602?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'The present study was aimed at assessing the impact of azoxystrobin-a fungicide commonly used in plant protection against pathogens (Amistar 250 SC)-on the soil microbiota and enzymes, as well as plant growth and development. The laboratory experiment was conducted in three analytical terms (30, 60, and 90 days) on sandy clay (pH-7.0). Azoxystrobin was applied to soil in doses of 0.00 (C), 0.110 (F) and 32.92 (P) mg kg-1 d.m. of soil. Its 0.110 mg kg-1 dose stimulated the proliferation of organotrophic bacteria and actinobacteria but inhibited that of fungi. It also contributed to an increase in the colony development index (CD) and a decrease in the ecophysiological diversity index (EP) of all analyzed groups of microorganisms. Azoxystrobin applied at 32.92 mg kg-1 reduced the number and EP of microorganisms and increased their CD. PP952051.1 Bacillus mycoides strain (P), PP952052.1 Prestia megaterium strain (P) bacteria, as well as PP952052.1 Kreatinophyton terreum isolate (P) fungi were identified in the soil contaminated with azoxystrobin, all of which may exhibit resistance to its effects. The azoxystrobin dose of 0.110 mg kg-1 stimulated the activity of all enzymes, whereas its 32.92 mg kg-1 dose inhibited activities of dehydrogenases, alkaline phosphatase, acid phosphatase, and urease and stimulated the activity of catalase. The analyzed fungicide added to the soil at both 0.110 and 32.92 mg kg-1 doses inhibited seed germination and elongation of shoots of Lepidium sativum L., Sinapsis alba L., and Sorgum saccharatum L.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d01988b7-10bc-4a57-9909-93ed326ddacb', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Safe Application of 75% Trifloxystrobin-Tebuconazole as Water-Dispersible Granules in Paddy Based on Residue and Dietary Risk Assessment', 'Wang S, Liu Y, Zhu M', 2023, 'Molecules (Basel, Switzerland)', '10.3390/molecules29010163', 'https://doi.org/10.3390/molecules29010163', 'https://europepmc.org/articles/PMC10779798?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'The present study describes the development of a highly effective approach for determining the residue distribution and dissipation of trifloxystrobin and tebuconazole, and their risk assessment in brown rice, husk, straw, and grain using high-performance liquid chromatography-tandem mass spectrometry (HPLC-MS/MS). The current study provides considerable novel information regarding the safe utilization of a mixture of trifloxystrobin and tebuconazole in paddy production. The samples demonstrated a range of mean recoveries between 72% and 86%, with a 1.1-9.2% relative standard deviation (RSD). The limits of quantification (LOQ) and half-lives (t1/2) for brown rice, husk, straw, and grain were, respectively, established to be 0.001-0.01 mg/kg and 4.1-7.7 days. The concentrations of terminal residues in the brown rice, husk, straw, and grain were, respectively, found to be 0.02-0.05, 0.03-0.11, 0.02-0.07, and 0.02-0.05 mg/kg after being treated twice at 168.75 g a.i./ha with 21 and 28 days of pre-harvest intervals (PHIs). Trifloxystrobin and tebuconazole presented a non-negligible chronic risk to human subjects, as evidenced by a risk quotient (RQ) value of less than 1.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d21c78d5-3784-48c5-9cc8-d0b53e12f177', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Sensitivity of Colletotrichum gloeosporioides species complex (CGSC) isolated from strawberry in Taiwan to benzimidazole and strobilurin', 'Chu SC, Lin KH, Lin TC, Thanarut C, Chung WH', 2022, 'Journal of pesticide science', '10.1584/jpestics.d22-030', 'https://doi.org/10.1584/jpestics.d22-030', 'https://europepmc.org/articles/PMC9716047?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by-nc-nd', 'Colletotrichum gloeosporioides species complex (CGSC) is the major pathogen causing strawberry anthracnose in Taiwan. Benzimidazoles and strobilurins are common fungicides used to control strawberry anthracnose. A total of 108 CGSC isolates were collected from five major strawberry-producing areas in Taiwan. The half-maximal effective concentration (EC50) values of most CGSC isolates for benomyl (59 isolates), carbendazim (70 isolates), and thiabendazole (63 isolates) were higher than 500 µg a.i./mL. Strobilurin tests showed that the EC50 values of most CGSC isolates for azoxystrobin (66 isolates), kresoxim-methyl (42 isolates), and trifloxystrobin (56 isolates) were higher than 500 µg a.i./mL. However, most CGSC isolates were sensitive to pyraclostrobin at 100 µg a.i./mL. Fungicide tests indicated that CGSC isolates show multi-resistance to benzimidazoles and strobilurins. Benzimidazole-resistant isolates were associated with a point mutation in codon 198 of the β-tubulin gene, and strobilurin-resistant isolates did not correspond with mutation in the cyt b gene or alternative oxidase activity.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a62ad871-7e0e-4a17-9c0e-27ee1db23a09', '5b6b6727-a783-46f1-8b94-8c552ac3284f', 'Sub-lethal dose exposure of cyflufenamid, flutianil, quinoxyfen, trifloxystrobin and metrafenone effects on conidial germination and gene expression in the grape powdery mildew pathogen', 'Nancy Sharma, Mohit Mahey, Rachel P. Naegele, Timothy D. Miles', 2026, 'Frontiers in Microbiology', '10.3389/fmicb.2026.1944688', 'https://doi.org/10.3389/fmicb.2026.1944688', 'https://www.frontiersin.org/articles/10.3389/fmicb.2026.1944688/full', NULL, NULL, 12, NULL, 'canada', 3, 'open access (DOAJ)', 'Erysiphe necator is a destructive obligate plant pathogen that infects grapevines worldwide. Recently, specialized fungicides have been widely employed to control grape powdery mildew. However, for some fungicides their modes of action and the transcriptome changes caused in E. necator upon application remain unclear. In this study, a conidial germination assay was conducted on E. necator conidia to determine if cyflufenamid (FRAC U06), flutianil (FRAC U13), quinoxyfen (FRAC 13), trifloxystrobin (FRAC 11) and metrafenone (FRAC 50) inhibit conidial germination. Further a transcriptomic analyses of E. necator conidia treated with sub-lethal doses of flutianil, quinoxyfen, and trifloxystrobin were conducted at 3 and 6 h. The results showed that cyflufenamid and metrafenone did not consistently inhibit conidial germination, even at chemical concentrations as high as 100 ppm. In contrast, flutianil, trifloxystrobin and quinoxyfen effectively suppressed conidial germination. The differential gene expression analysis revealed limited overlap in differentially expressed genes compared to the control group at their respective time frames, though all fungicide applications resulted in upregulated genes involved in cellular respiration. Quinoxyfen exposure led to reduced expression of protein kinase genes, suggesting a disruption in signal transduction, while flutianil treatment showed increased expression of sugar transporters and chitinases, possibly reflecting enhanced energy demand and cell wall remodeling. Additionally, in samples treated with quinoxyfen and flutianil, there was an overexpression of major facilitator superfamily (MFS) and adenosine triphosphate-binding cassette (ABC) multidrug transporters. Overall, these findings highlight that while flutianil, trifloxystrobin and quinoxyfen effectively inhibit conidial germination, their mode of action may also trigger altered gene expression of various gene families. This knowledge is valuable for developing improved fungicide resistance management strategies for managing E. necator.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7b7b8a06-b2a1-46a0-beff-ce39c3f537b6', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'A Pesticide Decision Support Tool to guide the selection of less environmentally harmful pesticides for the sugar cane industry', 'St John Warne M, Neale PA, Macpherson MJ', 2023, 'Environmental science and pollution research international', '10.1007/s11356-023-29814-w', 'https://doi.org/10.1007/s11356-023-29814-w', 'https://europepmc.org/articles/PMC10611884?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Pesticides applied to agricultural land have been shown to decrease the quality of water entering the Great Barrier Reef lagoon. This issue is addressed by the Reef 2050 Water Quality Improvement Plan which includes a pesticide reduction target. As part of a wider educational strategy, one method that could help meet the target is to provide stakeholders with information that assists in the selection and use of pesticide active ingredients (PAIs) that pose a lower risk to aquatic environments compared to those currently used. This study developed a Pesticide Decision Support Tool (PDST) in collaboration with stakeholders for the sugar cane industry. The PDST covers all PAIs registered and applied to sugar cane in Australia and four additional PAIs registered for use on crops grown in rotation with sugar cane. The PDST incorporates both the measure of mobility and persistence of a PAI and the measure of effect, which is based on the PAI application rate and ecotoxicity threshold value. The aquatic risk, which is the product of the measure of effect and the measure of mobility and persistence, is a measure of the likelihood that a PAI will reach the aquatic environment and cause harmful effects. Insecticide active ingredients (e.g., cadusafos, chlorpyrifos) posed the greatest aquatic risk, followed by herbicide active ingredients (e.g., MSMA, metolachlor), while fungicide AIs typically had a lower aquatic risk. An interactive spreadsheet allows characteristics, including application rate and tank mixes, to be considered when assessing the potential risk. While focusing on sugar cane, the results are equally appropriate to other crops that use the same PAIs provided the application rates are corrected to the new crop. In addition, the approach used in the PDST can be applied internationally and to any PAIs with sufficient toxicity, mobility, and persistence data.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('343fe68e-0a8d-4a1d-91ac-7a156e70254f', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Effects of salt stress on root morphology, carbon and nitrogen metabolism, and yield of Tartary buckwheat', 'Zhang X, He P, Guo R, Huang K, Huang X', 2023, 'Scientific reports', '10.1038/s41598-023-39634-0', 'https://doi.org/10.1038/s41598-023-39634-0', 'https://europepmc.org/articles/PMC10393950?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'This study aims to clarify the effects of different concentrations of sodium chloride on the carbon and nitrogen metabolism and yield of Tartary buckwheat. The salt-sensitive cultivar Yunqiao 2 was pot-grown and treated with four salt concentrations including 0, 2, 4, and 6 g kg-1. The root morphology index increased from seedling stage to maturate stage. The content of soluble protein in the leaves reached the maximum at the anthesis stage, and the other substances content and the enzymes activity related to carbon and nitrogen metabolism reached the maximum at the grain filling stage. The root morphology index, root activity; invertase, amylase, sucrose synthase, and sucrose phosphate synthase activities; nitrate-nitrogen, ammonium nitrogen, and soluble protein content; and nitrate reductase and glutamate synthase activities increased first and reached the maximum at 2 g kg-1 treatment and then decreased with increasing salt stress concentration. The content of soluble sugars and sucrose and the activity of glutamate dehydrogenase increased continuously with increasing salt concentration, and reached the maximum in the 6 g kg-1 treatment. The grain number per plant, 100-grain weight, and yield per plant increased first and reached the maximum at 2 g kg-1 treatment and then decreased with increasing salt stress concentration. In summary, moderate salt stress (2 g kg-1) can promote the root growth, increase the content of carbon and nitrogen metabolism-related substances and enzyme activity, and increase the yield per plant of Tartary buckwheat.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3fd399ba-ad08-4426-946b-abffaec77568', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Effects of thiamethoxam insecticide on sugarcane plant growth under chemical ripening at early and late harvest', 'Silva DP, Viveiros J, Jacomassi LM, Pacola M, Momesso L, de Siqueira GF, Martello JM, Foltran R', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1558071', 'https://doi.org/10.3389/fpls.2025.1558071', 'https://europepmc.org/articles/PMC12210020?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Chemical ripeners are applied to ensure the quality of the final product in sugarcane production, especially under unfavorable conditions for sucrose accumulation. In addition, bioactivators such as the insecticide thiamethoxam can stimulate plant development. Thus, the application of thiamethoxam to sugarcane regrowth associated with ripener may have phytotonic effects and improve sugarcane quality and yield. The aim of this study was to understand the effects of thiamethoxam foliar application to sugarcane ratoon treated with trinexapac-ethyl as a ripener. Four management strategies (treatments) were introduced and tested in six field experiments conducted across the early and late harvest seasons: no chemical application (control), application of 250 g a.i ha-1 trinexapac-ethyl (0.4 L ha-1 of commercial product) as a ripener, application of thiamethoxam 100 g a.i ha-1 (0.4 kg ha-1 of commercial product) as a bioactivator, and application of ripener and bioactivator. Thiamethoxam application increased stalk yield by 14 Mg ha-1 compared with the control, and joint application with ripener increased sugar yield by up to 3 Mg ha-1 due to an increase in total recoverable sugar (TRS) of up to 11% compared with the control (139.9 kg Mg-1). The increases in biomass in response to thiamethoxam application increased potential energy production (MWh) by 16.8% compared with the treatments without insecticide. The integration of thiamethoxam into sugarcane management enhanced yield, biomass, and energy-related traits without compromising technological quality. When combined with trinexapac-ethyl, it increased sugar yield per hectare. These benefits point to improved land-use efficiency. However, given its classification as a neonicotinoid, further studies are needed to assess long-term safety. Such research is key to aligning productivity with sustainability in sugarcane systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5e0bda86-93ad-47b6-b870-1c1355ab1d53', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Environmentally Friendly Wheat Farming: Biological and Economic Efficiency of Three Treatments to Control Fungal Diseases in Winter Wheat (Triticum aestivum L.) under Field Conditions', 'Rebouh NY, Aliat T, Polityko PM, Kherchouche D, Boulelouah N, Temirbekova SK, Afanasyeva YV, Kucher DE', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11121566', 'https://doi.org/10.3390/plants11121566', 'https://europepmc.org/articles/PMC9228977?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The control of wheat diseases using bioagents is not well studied under field conditions. The present study was aimed at investigating, during four consecutive growing seasons (2017-2020), the efficacy of two integrated crop protection (ICP) systems to control the common wheat diseases for enhancing the productivity and profitability of winter wheat crops and ensuring nutritional and food security. Two environmental-friendly treatments were tested, biological (T1), which contained bioagents and fertilizers, and combined (T2), which included fertilizers and bioagents coupled with lower doses of fungicides. The chemical treatment (T3) was used for comparison with (T1) and (T2). Furthermore, two Russian winter wheat varieties (Nemchinovskaya 17 (V1) and Moscovskaya 40 (V2)) were studied. A randomized complete block design was used with four replicates. Diseases infestation rates for snow mold (SM), root rot (RR), powdery mildew (PM), and Fusarium (Fus), yield performances, and grain quality (measured through protein content) were determined according to the tested treatments, and the economic efficiency was calculated for each treatment. The combined treatment (T2) was the most effective against fungal diseases with 1.8% (SM), 1.2% (RR), 0.9% (PM), and 0.9% (Fus). The highest grain yield (6.8 t·ha-1), protein content (15.2%), and 1000-grain weight (43.7%) were observed for winter wheat variety Moscovskaya 40 with the combined treatment (T2). The highest number of productive stems (N.P.S) (556 stems/m2) was attained for combined treatment (T2), followed by biological treatment (T1) (552 stems/m2) with the variety Nemchinovskaya 17. The profitability (cost-benefit ratio) of the combined treatment (T2) was 2.38 with the Moscovskaya 40 variety (V2), while 2.03 was recorded for the biological treatment. Applying environmentally friendly combined and biological treatments resulted in high wheat yield and net income, as well as healthy products.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2314df7f-ba37-49f5-8e7a-7f949ee10e84', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Foliar Application of Chitosan (CTS), γ-Aminobutyric Acid (GABA), or Sodium Chloride (NaCl) Mitigates Summer Bentgrass Decline in the Subtropical Zone', 'Cheng B, Zhou Q, Li L, Hassan MJ, Zeng W, Peng Y, Li Z', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13131773', 'https://doi.org/10.3390/plants13131773', 'https://europepmc.org/articles/PMC11244376?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Creeping bentgrass (Agrostis stolonifera) is an excellent cool-season turfgrass that is widely used in urban gardening, landscaping, and golf turf. Triennial field experiments from 2017 to 2019 were conducted to investigate effects of the foliar application of chitosan (CTS), γ-aminobutyric acid (GABA), or sodium chloride (NaCl) on mitigating summer bentgrass decline (SBD) and exploring the CTS, GABA, or NaCl regulatory mechanism of tolerance to summer heat stress associated with changes in chlorophyll (Chl) loss and photosynthetic capacity, osmotic adjustment (OA), oxidative damage, and cell membrane stability. The findings demonstrated that persistent ambient high temperatures above 30 °C during the summer months of 2017, 2018, and 2019 significantly reduced the turf quality (TQ), Chl content, photochemical efficiency of PSII (Fv/Fm and PIABS), leaf relative water content, and osmotic potential (OP) but significantly increased electrolyte leakage (EL) and the accumulations of free proline, water-soluble carbohydrate (WSC), hydrogen peroxide (H2O2), and malondialdehyde (MDA). The foliar application of CTS, GABA, or NaCl could significantly alleviate SBD, as reflected by improved TQ and delayed Chl loss during hot summer months. Heat-induced declines in Fv/Fm, PIABS, the net photosynthetic rate (Pn), the transpiration rate (Tr), and water use efficiency (WUE) could be significantly mitigated by the exogenous application of CTS, GABA, or NaCl. In addition, the foliar application of CTS, GABA, or NaCl also significantly improved the accumulations of free proline and WSC but reduced the EL, OP, and H2O2 content and the MDA content in leaves of creeping bentgrass in favor of water and redox homeostasis in summer. Based on the comprehensive evaluation of the subordinate function value analysis (SFVA), the CTS had the best effect on the mitigation of SBD, followed by GABA and NaCl in 2017, 2018, and 2019. The current study indicates that the foliar application of an appropriate dose of GABA, CTS, or NaCl provides a cost-effective strategy for mitigating SBD.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1b09f4eb-c3aa-4421-983f-454b90819738', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Gaining Insight into Exclusive and Common Transcriptomic Features Linked with Biotic Stress Responses in Malus', 'Balan B, Caruso T, Martinelli F', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.01569', 'https://doi.org/10.3389/fpls.2017.01569', 'https://europepmc.org/articles/PMC5601412?pdf=render', NULL, NULL, 11, NULL, 'other', 1, 'cc by', 'Identifying key information in transcriptomic data is very important, especially when the "omic" study deals with plant responses to stresses in field conditions where a high number of variables and disturbing factors may affect the analysis. In this meta-analysis we collected 12 transcriptomic works in Malus in order to identify which key genes, proteins, gene categories are involved in general plant pathological conditions and those features linked with exclusive biotic stress responses. Those genes that are only related with molecular responses to pathogen attacks and those linked with other plant physiological processes were identified. A pipeline composed by pathway and gene set enrichment analysis, protein-protein interaction networks and gene visualization tools was employed. A total of 13,230 genes of the 12 studies were analyzed with functional data mining tools: 5,215 were upregulated, 8,015 were downregulated. Gene set enrichment analysis pointed out that photosynthesis was inhibited by Erwinia amylovora and fungal pathogens. Different hormonal crosstalk was linked with responses to different pathogens. Gibberellin-related pathways, ABA-related were mostly repressed by fungal pathogens. Relating to transcription factors, genes encoding MYBs and WRKY2 were downregulated by fungal pathogens and 12 WRKYs were commonly regulated by different biotic stresses The protein-protein interaction analysis discovered the presence of several proteins affected by more than one biotic stress including a WRKY40 and some highly interactive proteins such as heat shock proteins. This study represents a first preliminary curated meta-analysis of apple transcriptomic responses to biotic stresses.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fccf04e4-4856-4485-ae0a-419e514da13f', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Heuchera Creme Brulee and Mahogany Medicinal Value under Water Stress and Oligosaccharide (COS) Treatment', 'Elansary HO, Abdel-Hamid AME, Mahmoud EA, Al-Mana FA, El-Ansary DO, Zin El-Abedin TK', 2019, 'Evidence-based complementary and alternative medicine : eCAM', '10.1155/2019/4242359', 'https://doi.org/10.1155/2019/4242359', 'https://europepmc.org/articles/PMC6398046?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Food borne pathogens cause serious human illnesses and diseases and their control using natural bioactive compounds becomes essential for the progress of agricultural and food industries. Developing novel tools to enhance the medicinal values of traditional horticultural medicinal crops is one of the promising methods for achieving food borne pathogens control. In this study, oligosaccharide water solutions were applied to Heuchera Creme Brulee and Mahogany subjected to a normal irrigation interval (2 days) or to prolonged irrigation intervals (6 days) for 6 weeks. Plant morphological, physiological, and metabolic markers associated with the bioactivity of leaf extracts against selected microbes. Oligosaccharide-treated plants showed significant increases in all morphological parameters during normal and prolonged irrigation intervals as compared to those of the controls. Morphological improvement associated with a significant increase in chlorophyll, carbohydrates, proline, K, Ca, phenols, and free and total ascorbate and antioxidants. Superoxide dismutase, catalase, and ascorbate peroxidase activities were higher, while H2O2 accumulated to a lower extent in oligosaccharide-treated plants. These morphological and metabolic changes associated with increased antibacterial and antifungal activities of leaf extracts and their activities were comparable to antibiotics and antifungal agents (minimum inhibitory concentrations values were 0.5 -0.20 mg-1mL for bacteria and 0.08 -0.20 mg-1mL for fungi in Mahogany). The application of oligosaccharide and/or water stress might be of great value for producing natural bioactive compounds for food borne pathogens control.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1fd19959-8fec-4baa-9606-38e85362b3be', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Impact of Harvest Delay and Barley Variety on Grain Nutritional Composition and Mycotoxin Contamination', 'Venslovas E, Kochiieru Y, Janavičienė S, Merkevičiūtė-Venslovė L, Almogdad M, Bartkevics V, Bērziņa Z, Pavlenko R', 2024, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof10110738', 'https://doi.org/10.3390/jof10110738', 'https://europepmc.org/articles/PMC11595418?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'This study investigated the effects of delayed harvesting, varying meteorological conditions, and barley variety on Fusarium spp. infection rates, nutritional composition, and mycotoxin contamination in barley grains. Field experiments were conducted from 2020 to 2022 and involved two barley varieties: ''Laureate'' for malting and ''Luokė'' for feed. The results indicated that the dominant Fusarium species isolated were F. avenaceum, F. culmorum, F. poae, F. sporotrichioides, F. tricinctum, and F. equiseti. These tended to increase in number with delayed harvest times and were more prevalent during harvest periods of higher precipitation (p p p p > 0.05). The strongest correlations between mycotoxins and nutritional value indicators were observed with less-studied mycotoxins, such as nivalenol and enniatins, which exhibited negative correlations with crude protein (p p p p p < 0.01).', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8689cb13-5e9f-4e4d-8e11-0f562307b099', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Microbial resistance and resilience to drought under organic and conventional farming', 'Kost E, Kundel D, Conz RF, Mäder P, Krause H, Six J, Mayer J, Hartmann M', 2024, NULL, '10.1101/2024.04.17.589021', 'https://doi.org/10.1101/2024.04.17.589021', 'https://europepmc.org/api/fulltextRepo?pprId=PPR838969&type=FILE&fileName=EMS195608-pdf.pdf&mimeType=application/pdf', NULL, NULL, 46, NULL, 'other', 1, 'cc by-nc-nd', 'The impacts of climate change, such as drought, can affect soil microbial communities. These communities are crucial for soil functioning and crop production. Organic and conventional cropping systems promote distinct soil microbiomes and soil organic carbon contents, which might maintain different capacities to mitigate drought effects on cropping systems. A field-scale drought simulation was performed in long-term organically and conventionally managed cropping systems differing in fertilization and pesticide application. The soil microbiome was assessed during and after drought in bulk soil, rhizosphere, and roots of wheat. We found that drought shifted microbial community structures, affecting fungi more strongly than prokaryotes. Microbial communities associated with crops (i.e. rhizosphere and root) were more strongly influenced by drought compared to bulk soil communities. A drought legacy effect was observed in the bulk soil after harvesting and rewetting. The resistance and resilience of the soil microbiome to severe drought did not significantly differ across the organic and conventional cropping systems, although few individual genera (e.g. Streptomyces , Rhizophagus, Actinomadura , and Aneurinibacillus ) showed system-specific drought responses. All cropping systems showed relative increases in potential plant growth-promoting genera under drought. This agricultural field study indicated that fungal communities might be less resistant to drought than prokaryotic communities in cropping systems and these effects get more pronounced in closer association with plants. Organic fertilization or the reduction in pesticide application might not have the ability to buffer severe drought stress and additional farming practices might have to be incorporated to improve drought tolerance in cropping systems.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c51cf080-705f-4044-b7bd-fa9ea9680dd6', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'Plant growth regulator applications and mechanisms for boosting rice productivity', 'Mohammed YZ, Sackey OK, Khan A, Issah AK, Iliasu F, Feng N, Zheng D', 2026, 'PeerJ', '10.7717/peerj.21457', 'https://doi.org/10.7717/peerj.21457', 'https://europepmc.org/articles/PMC13332734?pdf=render', NULL, NULL, 35, NULL, 'other', 1, 'cc by', 'Plant growth regulators (PGRs) have emerged as an important tool for improving crop productivity and adaptation to intensifying environmental challenges, especially in rice. This review summarizes 209 publications (2000-2025) on the current developments in exogenous PGR applications across major growth phases from germination to grain filling. It reveals the principal findings on hormonal crosstalk, including abscisic acid-gibberellin (ABA-GA) antagonism, stress balancing, and genotype-specific multi-hormonal strategies. It outlines 10-40% yield improvements in conjunction with precision agronomy. We elucidate how PGRs regulate growth, development, stress tolerance, and yield through molecular and physiological pathways. Nano-formulations and genome-editing methods offer revolutionary potential, combining hormonal modification with genetic improvement and digital technologies for sustainable intensification. While emphasizing the important role PGRs play, this review also highlights context-specific effects and application risks, and emphasizes variety-specific, evidence-based protocols. Ultimately, this work charts a course for future research and precision application, and it marks a shift in paradigm to create a stronger, more sustainable rice production system.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('40137bdc-533a-456e-be2b-fc461677b4d3', '0c731c9d-0544-4d9b-9bb1-8b22a3beb7df', 'The increase of salinity tolerance in three turf grass species using trinexapac-ethyl', 'Mehrdad Rasouli, Abdollah Hatamzadeh, Mahmood Ghasemnezhad, Habibollah Samizadeh Lahiji', 2017, 'یافته‌های نوین در علوم زیستی', NULL, 'http://nbr.khu.ac.ir/browse.php?a_code=A-10-81-55&slc_lang=en&sid=1', 'http://nbr.khu.ac.ir/browse.php?a_code=A-10-81-55&slc_lang=en&sid=1', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'In most parts of Iran, the presence of water and soil salinity in urban area results in problems for grass growth. One way to solve this problem is the use of plant growth retardant, such as trinexapac-ethyl (TE), which is common and routine in turf management. This study was performed to investigate the response of Agrostis stolonifera L., Agropyron desertorum L. and Festuca ovina L., grown in sandy loam soil, to TE and irrigation water salinity. Resu-lts showed that spraying turf grass with TE increased most of the vegetative growth characteristics and content of chlo-rophylls, carotenoids and proline in clipping leaves, whereas increasing the NaCl concentration in irrigation water resu-lted in steady reduction in the values of these parameters, except carotenoids and proline content, compared with the co-ntrol group. Both TE and salinity treatments decreased the plant heights, as well as the fresh and dry weight of clip-pings. In the species which were studied, Agrostis stolonifera turned out to be the most tolerant turfgrass. Results also indicated that the application of TE enhances salinity resistance by improving the percentage of green leaf, chlorophyll concentration and proline content and reduce clipping in the species studied', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf3a18d4-e04e-4b77-9a36-77b82207dd08', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Bioresponsive drug delivery systems for the treatment of inflammatory diseases', 'Dou Y, Li C, Li L, Guo J, Zhang J', 2020, 'Journal of controlled release : official journal of the Controlled Release Society', '10.1016/j.jconrel.2020.09.008', 'https://doi.org/10.1016/j.jconrel.2020.09.008', 'https://europepmc.org/articles/PMC7476894?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'open access (Europe PMC)', 'Inflammation is intimately related to the pathogenesis of numerous acute and chronic diseases like cardiovascular disease, inflammatory bowel disease, rheumatoid arthritis, and neurodegenerative diseases. Therefore anti-inflammatory therapy is a very promising strategy for the prevention and treatment of these inflammatory diseases. To overcome the shortcomings of existing anti-inflammatory agents and their traditional formulations, such as nonspecific tissue distribution and uncontrolled drug release, bioresponsive drug delivery systems have received much attention in recent years. In this review, we first provide a brief introduction of the pathogenesis of inflammation, with an emphasis on representative inflammatory cells and mediators in inflammatory microenvironments that serve as pathological fundamentals for rational design of bioresponsive carriers. Then we discuss different materials and delivery systems responsive to inflammation-associated biochemical signals, such as pH, reactive oxygen species, and specific enzymes. Also, applications of various bioresponsive drug delivery systems in the treatment of typical acute and chronic inflammatory diseases are described. Finally, crucial challenges in the future development and clinical translation of bioresponsive anti-inflammatory drug delivery systems are highlighted.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2b9b299-29ad-4411-a6d8-1bc998a7f434', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'A Comprehensive Review of Pea (Pisum sativum L.): Chemical Composition, Processing, Health Benefits, and Food Applications', 'Wu DT, Li WX, Wan JJ, Hu YC, Gan RY, Zou L', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12132527', 'https://doi.org/10.3390/foods12132527', 'https://europepmc.org/articles/PMC10341148?pdf=render', NULL, NULL, 40, NULL, 'other', 1, 'cc by', 'Pisum sativum L., commonly referred to as dry, green, or field pea, is one of the most common legumes that is popular and economically important. Due to its richness in a variety of nutritional and bioactive ingredients, the consumption of pea has been suggested to be associated with a wide range of health benefits, and there has been increasing focus on its potential as a functional food. However, there have been limited literature reviews concerning the bioactive compounds, health-promoting effects, and potential applications of pea up to now. This review, therefore, summarizes the literature from the last ten years regarding the chemical composition, physicochemical properties, processing, health benefits, and potential applications of pea. Whole peas are rich in macronutrients, including proteins, starches, dietary fiber, and non-starch polysaccharides. In addition, polyphenols, especially flavonoids and phenolic acids, are important bioactive ingredients that are mainly distributed in the pea coats. Anti-nutritional factors, such as phytic acid, lectin, and trypsin inhibitors, may hinder nutrient absorption. Whole pea seeds can be processed by different techniques such as drying, milling, soaking, and cooking to improve their functional properties. In addition, physicochemical and functional properties of pea starches and pea proteins can be improved by chemical, physical, enzymatic, and combined modification methods. Owing to the multiple bioactive ingredients in peas, the pea and its products exhibit various health benefits, such as antioxidant, anti-inflammatory, antimicrobial, anti-renal fibrosis, and regulation of metabolic syndrome effects. Peas have been processed into various products such as pea beverages, germinated pea products, pea flour-incorporated products, pea-based meat alternatives, and encapsulation and packing materials. Furthermore, recommendations are also provided on how to better utilize peas to promote their development as a sustainable and functional grain. Pea and its components can be further developed into more valuable and nutritious products.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('527116c5-a6e8-4df1-9bfd-51ce006a8b0c', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Adaptation to flooding during emergence and seedling growth in rice and weeds, and implications for crop establishment', 'Ismail AM, Johnson DE, Ella ES, Vergara GV, Baltazar AM', 2012, 'AoB PLANTS', '10.1093/aobpla/pls019', 'https://doi.org/10.1093/aobpla/pls019', 'https://europepmc.org/articles/PMC3434364?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by-nc', 'Background and aimsDirect seeding of rice is being adopted in rainfed and irrigated lowland ecosystems because it reduces labour costs in addition to other benefits. However, early flooding due to uneven fields or rainfall slows down seed germination and hinders crop establishment. Conversely, early flooding helps suppress weeds and reduces the costs of manual weeding and/or dependence on herbicides; however, numerous weed species are adapted to lowlands and present challenges for the use of flooding to control weeds. Advancing knowledge on the mechanisms of tolerance of flooding during germination and early growth in rice and weeds could facilitate the development of improved rice varieties and effective weed management practices for direct-seeded rice.Principal resultsRice genotypes with a greater ability to germinate and establish in flooded soils were identified, providing opportunities to develop varieties suitable for direct seeding in flooded soils. Tolerance of flooding in these genotypes was mostly attributed to traits associated with better ability to mobilize stored carbohydrates and anaerobic metabolism. Limited studies were undertaken in weeds associated with lowland rice systems. Remaining studies compared rice and weeds and related weed species such as Echinochloa crus-galli and E. colona or compared ecotypes of the same species of Cyperus rotundus adapted to either aerobic or flooded soils.ConclusionsTolerant weeds and rice genotypes mostly developed similar adaptive traits that allow them to establish in flooded fields, including the ability to germinate and elongate faster under hypoxia, mobilize stored starch reserves and generate energy through fermentation pathways. Remarkably, some weeds developed additional traits such as larger storage tubers that enlarge further in deeper flooded soils (C. rotundus). Unravelling the mechanisms involved in adaptation to flooding will help design management options that will allow tolerant rice genotypes to adequately establish in flooded soils while simultaneously suppressing weeds.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03dc6a01-c9a3-49ea-b199-fef4bcdb9d78', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Advances in the Synthesis of Biologically Active Quaternary Ammonium Compounds', 'Fedorowicz J, Sączewski J', 2024, 'International journal of molecular sciences', '10.3390/ijms25094649', 'https://doi.org/10.3390/ijms25094649', 'https://europepmc.org/articles/PMC11083083?pdf=render', NULL, NULL, 69, NULL, 'other', 1, 'cc by', 'This review provides a comprehensive overview of recent advancements in the design and synthesis of biologically active quaternary ammonium compounds (QACs). The covered scope extends beyond commonly reviewed antimicrobial derivatives to include synthetic agents with antifungal, anticancer, and antiviral properties. Additionally, this review highlights examples of quaternary ammonium compounds exhibiting activity against protozoa and herbicidal effects, as well as analgesic and anesthetic derivatives. The article also embraces the quaternary-ammonium-containing cholinesterase inhibitors and muscle relaxants. QACs, marked by their inherent permanent charge, also find widespread usage across diverse domains such as fabric softeners, hair conditioners, detergents, and disinfectants. The effectiveness of QACs hinges greatly on finding the right equilibrium between hydrophilicity and lipophilicity. The ideal length of the alkyl chain varies according to the unique structure of each QAC and its biological settings. It is expected that this review will provide comprehensive data for medicinal and industrial chemists to design and develop novel QAC-based products.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3eb9951d-1f3e-46a7-963b-70123ccac272', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Assessment of multiple herbicide protection seed treatments for seed-based restoration of native perennial bunchgrasses and sagebrush across multiple sites and years', 'Baughman OW, Eshleman M, Griffen J, Rios R, Boyd C, Kildisheva OA, Olsen A, Cahill M', 2023, 'PloS one', '10.1371/journal.pone.0283678', 'https://doi.org/10.1371/journal.pone.0283678', 'https://europepmc.org/articles/PMC10062626?pdf=render', NULL, NULL, 25, NULL, 'northern_plains', 3, 'cc0', 'The invasion of exotic, annual plant species is a leading contributor to ecological degradation in drylands globally, and the use of pre-emergent herbicide to control these species is common. Pre-emergent herbicides pose challenges for seed-based restoration due to toxicity to the seeds of desired species. Herbicide protection (HP) technologies pose a potential solution by using activated carbon seed treatments to protect desirable seeds from herbicide exposure. In the sagebrush steppe ecosystem of North America, we used an adaptive small plot design over three planting years to test for effects on seeding outcomes (seedling density and size) of large and small multi-seed HP pellets, several single-seed HP coatings, and carbon banding treatments at geographically dispersed sites for several perennial bunchgrasses and the keystone perennial shrub, Wyoming big sagebrush. We also compared different methods of seed delivery and litter pre-seeding management. Seeding success was low overall, especially for sagebrush, and it was clear that other, often less predictable barriers to establishment than herbicide exposure, such as inadequate spring moisture, were strong drivers of seeding outcomes. Despite this, HP treatments were associated with higher seedling density than bare seed in multiple instances, most notably for grasses. The large HP pellet occasionally outperformed the small HP pellet, and several HP coatings performed similarly to the small pellet. Surprisingly, we did not see consistent negative effects of pre-emergent herbicide on unprotected bare seed. We conclude that HP seed treatments show some promise to improve seeding success in the presence of herbicide, but that consistent success will require further improvements to HP treatments as well as integration with other innovations and approaches.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ce73def7-0499-4c30-a1a0-7a9b1f9fd83e', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Challenges in the Application of Circular Economy Models to Agricultural By-Products: Pesticides in Spain as a Case Study', 'Otero P, Echave J, Chamorro F, Soria-Lopez A, Cassani L, Simal-Gandara J, Prieto MA, Fraga-Corral M', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12163054', 'https://doi.org/10.3390/foods12163054', 'https://europepmc.org/articles/PMC10453233?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'The income and residue production from agriculture has a strong impact in Spain. A circular economy and a bioeconomy are two alternative sustainable models that include the revalorization of agri-food by-products to recover healthy biomolecules. However, most crops are conventional, implying the use of pesticides. Hence, the reutilization of agri-food by-products may involve the accumulation of pesticides. Even though the waste-to-bioproducts trend has been widely studied, the potential accumulation of pesticides during by-product revalorization has been scarcely assessed. Therefore, in this study, the most common pesticides found in eight highly productive crops in Spain are evaluated according to the available published data, mainly from EFSA reports. Among these, oranges, berries and peppers showed an increasing tendency regarding pesticide exceedances. In addition, the adverse effects of pesticides on human and animal health and the environment were considered. Finally, a safety assessment was developed to understand if the reutilization of citrus peels to recover ascorbic acid (AA) would represent a risk to human health. The results obtained seem to indicate the safety of this by-product to recover AA concentrations to avoid scurvy (45 mg/day) and improve health (200 mg/day). Therefore, this work evaluates the potential risk of pesticide exposure through the revalorization of agri-food by-products using peels from citruses, one of the major agricultural crops in Spain, as a case study.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ad3cf17e-4908-4db1-9618-53bbbb900edd', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Evaluation of Fruit Bagging as a Pest Management Option for Direct Pests of Apple', 'Frank DL', 2018, 'Insects', '10.3390/insects9040178', 'https://doi.org/10.3390/insects9040178', 'https://europepmc.org/articles/PMC6316256?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Bagging fruit with plastic, paper, and two-layer commercial bags was evaluated for control of insect pests and diseases in an experimental apple orchard planted with ''Red Delicious'' trees. Results from fruit damage evaluations at harvest showed that bagging significantly reduced fruit damage from direct apple pests compared with non-bagged control plots, and generally provided similar levels of fruit protection when compared with a conventional pesticide spray program. Of the three bagging materials evaluated, plastic bags provided numerically higher levels of fruit protection from insect pests, and two-layer commercial bags provided numerically higher levels of fruit protection from fruit diseases. Fruit quality as measured by percentage Brix was higher in non-bagged control plots than all other treatment plots. Fruit quality as measured by fruit diameter was not significantly different among treatments. Plastic and two-layer commercial bags generally required less time to secure around apple fruit than paper bags. The proportion of bags that remained on fruit until harvest ranged from 0.54⁻0.71 (commercial bags), 0.64⁻0.82 (plastic bags), and 0.32⁻0.60 (paper bags), depending on the year.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29653b2f-0acb-482d-bf65-2dbcaddaf648', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Evolution of Resistance to Auxinic Herbicides: Historical Perspectives, Mechanisms of Resistance, and Implications for Broadleaf Weed Management in Agronomic Crops', 'J. Mithila, J. Christopher Hall, William G. Johnson, Kevin B. Kelley, Dean E. Riechers', 2011, 'Weed Science', '10.1614/ws-d-11-00062.1', 'https://doi.org/10.1614/ws-d-11-00062.1', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/4C9DD251A13E2F0356940BEA1F5BA5DE/S0043174500020658a.pdf/div-class-title-evolution-of-resistance-to-auxinic-herbicides-historical-perspectives-mechanisms-of-resistance-and-implications-for-broadleaf-weed-management-in-agronomic-crops-div.pdf', NULL, NULL, 13, NULL, 'canada', 3, 'cc-by', 'Auxinic herbicides are widely used for control of broadleaf weeds in cereal crops and turfgrass. These herbicides are structurally similar to the natural plant hormone auxin, and induce several of the same physiological and biochemical responses at low concentrations. After several decades of research to understand the auxin signal transduction pathway, the receptors for auxin binding and resultant biochemical and physiological responses have recently been discovered in plants. However, the precise mode of action for the auxinic herbicides is not completely understood despite their extensive use in agriculture for over six decades. Auxinic herbicide-resistant weed biotypes offer excellent model species for uncovering the mode of action as well as resistance to these compounds. Compared with other herbicide families, the incidence of resistance to auxinic herbicides is relatively low, with only 29 auxinic herbicide-resistant weed species discovered to date. The relatively low incidence of resistance to auxinic herbicides has been attributed to the presence of rare alleles imparting resistance in natural weed populations, the potential for fitness penalties due to mutations conferring resistance in weeds, and the complex mode of action of auxinic herbicides in sensitive dicot plants. This review discusses recent advances in the auxin signal transduction pathway and its relation to auxinic herbicide mode of action. Furthermore, comprehensive information about the genetics and inheritance of auxinic herbicide resistance and case studies examining mechanisms of resistance in auxinic herbicide-resistant broadleaf weed biotypes are provided. Within the context of recent findings pertaining to auxin biology and mechanisms of resistance to auxinic herbicides, agronomic implications of the evolution of resistance to these herbicides are discussed in light of new auxinic herbicide-resistant crops that will be commercialized in the near future.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ecd91d5e-1808-4a82-8c8b-f79560a60394', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'A Machine Learning Approach for the Estimation of Alfalfa Hay Crop Yield in Northern Nevada', 'Diego Quintero, Manuel A. Andrade, Uriel Cholula, Juan K. Q. Solomon', 2023, 'AgriEngineering', '10.3390/agriengineering5040119', 'https://doi.org/10.3390/agriengineering5040119', 'https://www.mdpi.com/2624-7402/5/4/119', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Increasing pressure over water resources in the western U.S. is currently forcing alfalfa (Medicago sativa L.) producers to adopt water-saving irrigation techniques. Crop yield forecasting tools can be used to develop smart irrigation scheduling methods that can be used to estimate the future effects of a given irrigation amount applied during a current irrigation event on yield. In this work, a linear model and a random forest model were used to estimate the yield of irrigated alfalfa crops in northern Nevada. It was found that water (rain + irrigation), the occurrence of extreme temperatures, and wind have a greater effect on crop yield. Other variables that accounted for the photoperiod and the dormant period were also included in the model and are also important. The linear model had the best performance with an R2 of 0.854. On the other hand, the R2 value for the random forest was 0.793. The linear model showed a good response to water variability; therefore, it is a good model to consider for use as an irrigation decision support system. However, unlike the linear model, the random forest model can capture non-linear relationships occurring between the crop, water, and the atmosphere, and its results may be enhanced by including more data for its training.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05468f94-4136-4809-aece-8977826638ce', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Exposure to sublethal doses of fipronil and thiacloprid highly increases mortality of honeybees previously infected by Nosema ceranae', 'Vidau C, Diogon M, Aufauvre J, Fontbonne R, Viguès B, Brunet JL, Texier C, Biron DG', 2011, 'PloS one', '10.1371/journal.pone.0021550', 'https://doi.org/10.1371/journal.pone.0021550', 'https://europepmc.org/articles/PMC3125288?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'BackgroundThe honeybee, Apis mellifera, is undergoing a worldwide decline whose origin is still in debate. Studies performed for twenty years suggest that this decline may involve both infectious diseases and exposure to pesticides. Joint action of pathogens and chemicals are known to threaten several organisms but the combined effects of these stressors were poorly investigated in honeybees. Our study was designed to explore the effect of Nosema ceranae infection on honeybee sensitivity to sublethal doses of the insecticides fipronil and thiacloprid.Methodology/findingFive days after their emergence, honeybees were divided in 6 experimental groups: (i) uninfected controls, (ii) infected with N. ceranae, (iii) uninfected and exposed to fipronil, (iv) uninfected and exposed to thiacloprid, (v) infected with N. ceranae and exposed 10 days post-infection (p.i.) to fipronil, and (vi) infected with N. ceranae and exposed 10 days p.i. to thiacloprid. Honeybee mortality and insecticide consumption were analyzed daily and the intestinal spore content was evaluated 20 days after infection. A significant increase in honeybee mortality was observed when N. ceranae-infected honeybees were exposed to sublethal doses of insecticides. Surprisingly, exposures to fipronil and thiacloprid had opposite effects on microsporidian spore production. Analysis of the honeybee detoxification system 10 days p.i. showed that N. ceranae infection induced an increase in glutathione-S-transferase activity in midgut and fat body but not in 7-ethoxycoumarin-O-deethylase activity.Conclusions/significanceAfter exposure to sublethal doses of fipronil or thiacloprid a higher mortality was observed in N. ceranae-infected honeybees than in uninfected ones. The synergistic effect of N. ceranae and insecticide on honeybee mortality, however, did not appear strongly linked to a decrease of the insect detoxification system. These data support the hypothesis that the combination of the increasing prevalence of N. ceranae with high pesticide content in beehives may contribute to colony depopulation.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('71bc2f61-effd-4bd3-8673-313cab72b36d', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Hydrogen Gas Is Involved in Auxin-Induced Lateral Root Formation by Modulating Nitric Oxide Synthesis', 'Cao Z, Duan X, Yao P, Cui W, Cheng D, Zhang J, Jin Q, Chen J', 2017, 'International journal of molecular sciences', '10.3390/ijms18102084', 'https://doi.org/10.3390/ijms18102084', 'https://europepmc.org/articles/PMC5666766?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Metabolism of molecular hydrogen (H₂) in bacteria and algae has been widely studied, and it has attracted increasing attention in the context of animals and plants. However, the role of endogenous H₂ in lateral root (LR) formation is still unclear. Here, our results showed that H₂-induced lateral root formation is a universal event. Naphthalene-1-acetic acid (NAA; the auxin analog) was able to trigger endogenous H₂ production in tomato seedlings, and a contrasting response was observed in the presence of N-1-naphthyphthalamic acid (NPA), an auxin transport inhibitor. NPA-triggered the inhibition of H₂ production and thereafter lateral root development was rescued by exogenously applied H₂. Detection of endogenous nitric oxide (NO) by the specific probe 4-amino-5-methylamino-2'',7''-difluorofluorescein diacetate (DAF-FM DA) and electron paramagnetic resonance (EPR) analyses revealed that the NO level was increased in both NAA- and H₂-treated tomato seedlings. Furthermore, NO production and thereafter LR formation induced by auxin and H₂ were prevented by 2-4-carboxyphenyl-4,4,5,5-tetramethylimidazoline-1-oxyl-3-oxide (cPTIO; a specific scavenger of NO) and the inhibitor of nitrate reductase (NR; an important NO synthetic enzyme). Molecular evidence confirmed that some representative NO-targeted cell cycle regulatory genes were also induced by H₂, but was impaired by the removal of endogenous NO. Genetic evidence suggested that in the presence of H₂, Arabidopsis mutants nia2 (in particular) and nia1 (two nitrate reductases (NR)-defective mutants) exhibited defects in lateral root length. Together, these results demonstrated that auxin-induced H₂ production was associated with lateral root formation, at least partially via a NR-dependent NO synthesis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5ae683a0-115f-470f-a836-a97d87a971b9', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Hydrogen Sulfide, Ethylene, and Nitric Oxide Regulate Redox Homeostasis and Protect Photosynthetic Metabolism under High Temperature Stress in Rice Plants', 'Gautam H, Fatma M, Sehar Z, Mir IR, Khan NA', 2022, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox11081478', 'https://doi.org/10.3390/antiox11081478', 'https://europepmc.org/articles/PMC9405544?pdf=render', NULL, NULL, 31, NULL, 'other', 1, 'cc by', 'Rising temperatures worldwide due to global climate change are a major scientific issue at present. The present study reports the effects of gaseous signaling molecules, ethylene (200 µL L-1; 2-chloroethylphosphonic acid; ethephon, Eth), nitric oxide (NO; 100 µM sodium nitroprusside; SNP), and hydrogen sulfide (H2S; 200 µM sodium hydrosulfide, NaHS) in high temperature stress (HS) tolerance, and whether or not H2S contributes to ethylene or NO-induced thermo-tolerance and photosynthetic protection in rice (Oryza sativa L.) cultivars, i.e., Taipei-309, and Rasi. Plants exposed to an HS of 40 °C for six h per day for 15 days caused a reduction in rice biomass, associated with decreased photosynthesis and leaf water status. High temperature stress increased oxidative stress by increasing the content of hydrogen peroxide (H2O2) and thiobarbituric acid reactive substance (TBARS) in rice leaves. These signaling molecules increased biomass, leaf water status, osmolytes, antioxidants, and photosynthesis of plants under non-stress and high temperature stress. However, the effect was more conspicuous with ethylene than NO and H2S. The application of H2S scavenger hypotaurine (HT) reversed the effect of ethylene or NO on photosynthesis under HS. This supports the findings that the ameliorating effects of Eth or SNP involved H2S. Thus, the presence of H2S with ethylene or NO can enhance thermo-tolerance while also protecting plant photosynthesis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('de590e4b-7c10-41c3-b389-4bd57a5fbd7a', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Identification and Confirmation of Virulence Factor Production from Fusarium avenaceum, a Causal Agent of Root Rot in Pulses', 'Witte TE, Hermans A, Sproule A, Hicks C, Talhouni T, Schneiderman D, Harris LJ, Eranthodi A', 2024, 'Journal of fungi (Basel, Switzerland)', '10.3390/jof10120821', 'https://doi.org/10.3390/jof10120821', 'https://europepmc.org/articles/PMC11677700?pdf=render', NULL, NULL, 17, NULL, 'canada', 3, 'cc by', 'Fusarium avenaceum is an aggressive pathogen of pulse crops and a causal agent in root rot disease that negatively impacts Canadian agriculture. This study reports the results of a targeted metabolomics-based profiling of secondary metabolism in an 18-strain panel of Fusarium avenaceum cultured axenically in multiple media conditions, in addition to an in planta infection assay involving four strains inoculated on two pea cultivars. Multiple secondary metabolites with known roles as virulence factors were detected which have not been previously associated with F. avenaceum, including fungal decalin-containing diterpenoid pyrones (FDDPs), fusaoctaxins, sambutoxin and fusahexin, in addition to confirmation of previously reported secondary metabolites including enniatins, fusarins, chlamydosporols, JM-47 and others. Targeted genomic analysis of secondary metabolite biosynthetic gene clusters was used to confirm the presence/absence of the profiled secondary metabolites. The detection of secondary metabolites with diverse bioactivities is discussed in the context of virulence factor networks potentially coordinating the disruption of plant defenses during disease onset by this generalist plant pathogen.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('948e33d8-aa86-43e0-b2af-aaa15f5119d9', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'A probabilistic approach to predicting alfalfa''s winter survival using local conditions, weather and management factors', 'Saifuzzaman M, Adamchuk VI, Leduc M, Chokmani K, Etezadi H, Seguin P', 2026, 'Scientific reports', '10.1038/s41598-026-37585-w', 'https://doi.org/10.1038/s41598-026-37585-w', 'https://europepmc.org/articles/PMC13057243?pdf=render', NULL, NULL, 18, NULL, 'prairies', 4, 'cc by-nc-nd', 'Alfalfa (Medicago sativa L.) produce relatively high yields of high-quality forage and contributes to carbon sequestration. Still, its winter survival is often lower than that of grasses, reducing plant density and field productivity. Winterkill is influenced by environmental factors (e.g., snow cover, temperature fluctuations, hardening period) and management practices (e.g., cutting time, fertilization, drainage). To assess these factors and improve persistence, this study developed a quantitative assessment tool for Canadian forage producers. A numerical simulation framework integrated soil, weather, and field management variables to evaluate yield variability and winterkill risk. Data were collected from 225 farms across Nova Scotia, Quebec, Ontario, and Manitoba using a randomized hierarchical sampling design. Soil samples were analyzed in commercial laboratories, and stem density was measured each spring and fall over three years. Descriptive statistics linking stem characteristics with soil and topographic features, weather conditions, and management practices, including soil nutrient levels, revealed a decline in mean stem counts from 49 in spring 2021 to 37 in spring 2023. To illustrate performance, weighted scores and persistence analyses were used to define model parameters across three distinct scenarios: optimal, average, and worst-case. The risk-assessment tool offers decision support to Canadian forage growers, enhancing productivity through informed management, species selection, and soil recommendations.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('997b2d4b-7c34-4e46-9e76-66361ab6b4b2', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Integrative approaches for mustard improvement: Bridging conventional breeding, genetics and biotechnological advances', 'G R Prasanth, S. Utharasu, R. Ravikesavan, N Sakthivel, Panneerselvam Sivasakthivelan, M. Sudha', 2025, 'Plant Science Today', '10.14719/pst.5231', 'https://doi.org/10.14719/pst.5231', 'https://horizonepublishing.com/journals/index.php/PST/article/download/5231/5309', NULL, NULL, 15, NULL, 'canada', 3, 'cc-by', 'Mustard is globally an oilseed crop that provides essential edible oil and industrial raw materials, particularly in regions like South Asia, Europe, and Canada, where it plays a critical role in agricultural economies and food industries. However, worldwide biotic and abiotic stresses pose major challenges to mustard production. Advances in conventional breeding techniques, genetics, and biotechnological tools hold immense potential for developing improved mustard varieties. This review elucidates the evolution of mustard breeding, moving from conventional approaches to advanced molecular tools that allow for precise genetic modifications, enhancing mustard resilience and yield. It highlights the roles of phenotypic and genotypic selection, molecular markers, transgenics, and genomicsassisted breeding in augmenting mustard improvement endeavours. The promise of emerging technologies like genome editing and systems biology is discussed for mustard genetic enhancement and climate-resilient varietal development. The review emphasizes the need of collaboration among research institutions, public-private partnerships, and international networks to accelerate, sustainable mustard improvement efforts.', '{openalex,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('201072f0-5631-4c2c-a96b-f55d4e7fb63b', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Interactions between population density of the Colorado potato beetle, Leptinotarsa decemlineata, and herbicide rate for suppression of solanaceous weeds', 'Metzger C, Boydston R, Ferguson H, Williams MM 2nd, Zack R, Walsh D', 2008, 'Journal of insect science (Online)', '10.1673/031.008.3801', 'https://doi.org/10.1673/031.008.3801', 'https://europepmc.org/articles/PMC3127376?pdf=render', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc by', 'The presence of volunteer potato Solanum tuberosum L., cutleaf nightshade, S. triflorum N., and hairy nightshade, S. physalifolium Rusby (Solanales: Solanaceae), throughout potato crop rotations can diminish the effectiveness of crop rotations designed to control disease and pest problems associated with growing potatoes. In greenhouse bioassays, larvae of the Colorado potato beetle, Leptinotarsa decemlineata Say (Coleoptera: Chrysomelidae) were placed in population densities of 0, 5, 10, and 40 per potato (cv. Russet Burbank) plant and 0, 5, 10, and 15 per cutleaf nightshade and hairy nightshade plant. Plants were treated with different rates of herbicides including fluroxypyr, prometryn, and mesotrione rates, and the physiological response on the potato plants was assessed by weighing shoot biomass 14 days after treatment. Consistently, across all bioassays, rate response functions were shifted as L. decemlineata density increased, such that less herbicide was required to achieve control. For instance, the herbicide rate needed to achieve 90% reduction in potato biomass was reduced from 62 to 0 g fluroxypyr per hectare and 711 to 0 g prometryn per hectare as L. decemlineata density was increased to 40 larvae per plant. Herbivory at higher L. decemlineata population densities and herbicides above certain rates resulted in large reductions in cutleaf and hairy nightshade biomass. Differences in rate response functions among L. decemlineata population densities indicated that L. decemlineata contributed to weed suppression in combination with herbicides. These data suggest that integrated weed management systems targeting volunteer potato, cutleaf nightshade, and hairy nightshade can be more effective when herbicide applications are combined with herbivory by naturally occurring Colorado potato beetles.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('589a7619-7209-4fd5-adc1-b542aa80c68d', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Mechanistic Concept of Physiological, Biochemical, and Molecular Responses of the Potato Crop to Heat and Drought Stress', 'Lal MK, Tiwari RK, Kumar A, Dey A, Kumar R, Kumar D, Jaiswal A, Changan SS', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11212857', 'https://doi.org/10.3390/plants11212857', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC9654185.1/PMC9654185.1.pdf', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Most cultivated potatoes are tetraploid, and the tuber is the main economic part that is consumed due to its calorific and nutritional values. Recent trends in climate change led to the frequent occurrence of heat and drought stress in major potato-growing regions worldwide. The optimum temperature for tuber production is 15-20 °C. High-temperature and water-deficient conditions during the growing season result in several morphological, physiological, biochemical, and molecular alterations. The morphological changes under stress conditions may affect the process of stolon formation, tuberization, and bulking, ultimately affecting the tuber yield. This condition also affects the physiological responses, including an imbalance in the allocation of photoassimilates, respiration, water use efficiency, transpiration, carbon partitioning, and the source-sink relationship. The biochemical responses under stress conditions involve maintaining ionic homeostasis, synthesizing heat shock proteins, achieving osmolyte balance, and generating reactive oxygen species, ultimately affecting various biochemical pathways. Different networks that include both gene regulation and transcription factors are involved at the molecular level due to the combination of hot and water-deficient conditions. This article attempts to present an integrative content of physio-biochemical and molecular responses under the combined effects of heat and drought, prominent factors in climate change. Taking into account all of these aspects and responses, there is an immediate need for comprehensive screening of germplasm and the application of appropriate approaches and tactics to produce potato cultivars that perform well under drought and in heat-affected areas.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('38db582d-09e8-40f3-b543-dbd6bb07ccd8', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Metabolic Responses to Low Temperature of Three Peach Fruit Cultivars Differently Sensitive to Cold Storage', 'Brizzolara S, Hertog M, Tosetti R, Nicolai B, Tonutti P', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00706', 'https://doi.org/10.3389/fpls.2018.00706', 'https://europepmc.org/articles/PMC5985494?pdf=render', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'Refrigerated storage is widely applied in order to maintain peach quality but it can also induce chilling injuries (CIs) such as flesh browning and bleeding, and mealiness. Peach fruit from three cultivars (''Red Haven'', RH, ''Regina di Londa'', RL, and ''Flaminia'', FL) were stored for 4 weeks under low temperatures (0.5 and 5.5°C). GC-MS was employed to study changes in both metabolome and volatilome induced by cold storage in the mesocarp. CIs were assessed both at the end of each week of storage and after subsequent shelf-life (SL) at 20°C. Flesh browning and mealiness appeared to be more related to 5.5°C storage, while flesh bleeding revealed high incidence following 0.5°C storage. Compared to RL and FL, RH showed a marked lower incidence of CIs. Multivariate statistical analyses indicate that RH peaches indeed differ from RL and FL in particular when considering data from samples collected at the end of the cold storage. Common and divergent responses have been identified in terms of metabolic responses to the applied low temperatures. In all three cultivars raffinose, glucose-6P, fucose, xylose, sorbitol, GABA, epicatechin, catechin, and putrescine markedly increased during cold storage, while citramalic, glucuronic, mucic and shikimic acids decreased. Among volatile organic compounds (VOCs), aldehydes and alcohols generally accumulated more under low temperature conditions while esters and lactones evolved during subsequent SL. The main cultivar differences developed after cold storage during SL although some common responses (e.g., an increased production of ethyl acetate) were observed. The lower levels of flesh browning and bleeding displayed by RH peaches were related to compounds with antioxidant activity, or acting as osmotic protectants and membrane stabilizer. Indeed, RH showed higher levels of amino acids and urea, together with a marked increase in putrescine, sorbitol, maltitol, myoinositol and sucrose detected during storage and SL.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7520497f-36d2-48ae-b38b-8642705610bf', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Microbial and molecular approaches for PFAS transformation in soils: prospects and limitations', 'Shahid M, Shafi Z', 2026, 'RSC advances', '10.1039/d5ra07508d', 'https://doi.org/10.1039/d5ra07508d', 'https://europepmc.org/articles/PMC12814939?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by-nc', 'Microbial and enzymatic strategies for per- and polyfluoroalkyl substance (PFAS) transformation are receiving increasing attention, but remain at an early stage of scientific development. This review evaluates the limited but emerging evidence for microbially mediated PFAS transformation, the putative enzymes implicated through multi-omics investigations, and the prospects and constraints of molecular engineering and synthetic biology. While computational modelling and omics approaches have proposed candidate mechanisms, no enzyme has yet been experimentally validated to catalyse efficient cleavage of perfluorinated C-F bonds, and most reported bio-transformations involve precursor compounds rather than terminal PFAS. Environmental factors, slow kinetics, and uncertain mechanisms further limit the practical application. Comparative analysis with established physicochemical technologies highlights that microbial strategies are best viewed as long-term, complementary tools rather than near-term solutions. Future work requires enzyme discovery, mechanistic elucidation, and careful integration of biological, computational, and engineering methodologies.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03ada7d2-b283-4e84-b3d5-d904fe79323a', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Molecular Mechanism of Functional Ingredients in Barley to Combat Human Chronic Diseases', 'Zeng Y, Pu X, Du J, Yang X, Li X, Mandal MSN, Yang T, Yang J', 2020, 'Oxidative medicine and cellular longevity', '10.1155/2020/3836172', 'https://doi.org/10.1155/2020/3836172', 'https://europepmc.org/articles/PMC7149453?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Barley plays an important role in health and civilization of human migration from Africa to Asia, later to Eurasia. We demonstrated the systematic mechanism of functional ingredients in barley to combat chronic diseases, based on PubMed, CNKI, and ISI Web of Science databases from 2004 to 2020. Barley and its extracts are rich in 30 ingredients to combat more than 20 chronic diseases, which include the 14 similar and 9 different chronic diseases between grains and grass, due to the major molecular mechanism of six functional ingredients of barley grass (GABA, flavonoids, SOD, K-Ca, vitamins, and tryptophan) and grains (β-glucans, polyphenols, arabinoxylan, phytosterols, tocols, and resistant starch). The antioxidant activity of barley grass and grain has the same and different functional components. These results support findings that barley grain and its grass are the best functional food, promoting ancient Babylonian and Egyptian civilizations, and further show the depending functional ingredients for diet from Pliocene hominids in Africa and Neanderthals in Europe to modern humans in the world. This review paper not only reveals the formation and action mechanism of barley diet overcoming human chronic diseases, but also provides scientific basis for the development of health products and drugs for the prevention and treatment of human chronic diseases.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('415c7458-89fe-4c11-b5ec-957d6a2825c8', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Mung Bean (Vigna radiata L.): Bioactive Polyphenols, Polysaccharides, Peptides, and Health Benefits', 'Hou D, Yousaf L, Xue Y, Hu J, Wu J, Hu X, Feng N, Shen Q', 2019, 'Nutrients', '10.3390/nu11061238', 'https://doi.org/10.3390/nu11061238', 'https://europepmc.org/articles/PMC6627095?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'Mung bean (Vigna radiata L.) is an important pulse consumed all over the world, especially in Asian countries, and has a long history of usage as traditional medicine. It has been known to be an excellent source of protein, dietary fiber, minerals, vitamins, and significant amounts of bioactive compounds, including polyphenols, polysaccharides, and peptides, therefore, becoming a popular functional food in promoting good health. The mung bean has been documented to ameliorate hyperglycemia, hyperlipemia, and hypertension, and prevent cancer and melanogenesis, as well as possess hepatoprotective and immunomodulatory activities. These health benefits derive primarily from the concentration and properties of those active compounds present in the mung bean. Vitexin and isovitexin are identified as the major polyphenols, and peptides containing hydrophobic amino acid residues with small molecular weight show higher bioactivity in the mung bean. Considering the recent surge in interest in the use of grain legumes, we hope this review will provide a blueprint to better utilize the mung bean in food products to improve human nutrition and further encourage advancement in this field.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06d87466-864d-4e65-ae69-95990899eadf', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Narrow Bandgap Metal Halide Perovskites for All-Perovskite Tandem Photovoltaics', 'Hu S, Thiesbrummel J, Pascual J, Stolterfoht M, Wakamiya A, Snaith HJ', 2024, 'Chemical reviews', '10.1021/acs.chemrev.3c00667', 'https://doi.org/10.1021/acs.chemrev.3c00667', 'https://europepmc.org/articles/PMC11009966?pdf=render', NULL, NULL, 45, NULL, 'other', 1, 'cc by', 'All-perovskite tandem solar cells are attracting considerable interest in photovoltaics research, owing to their potential to surpass the theoretical efficiency limit of single-junction cells, in a cost-effective sustainable manner. Thanks to the bandgap-bowing effect, mixed tin-lead (Sn-Pb) perovskites possess a close to ideal narrow bandgap for constructing tandem cells, matched with wide-bandgap neat lead-based counterparts. The performance of all-perovskite tandems, however, has yet to reach its efficiency potential. One of the main obstacles that need to be overcome is the─oftentimes─low quality of the mixed Sn-Pb perovskite films, largely caused by the facile oxidation of Sn(II) to Sn(IV), as well as the difficult-to-control film crystallization dynamics. Additional detrimental imperfections are introduced in the perovskite thin film, particularly at its vulnerable surfaces, including the top and bottom interfaces as well as the grain boundaries. Due to these issues, the resultant device performance is distinctly far lower than their theoretically achievable maximum efficiency. Robust modifications and improvements to the surfaces of mixed Sn-Pb perovskite films are therefore critical for the advancement of the field. This Review describes the origins of imperfections in thin films and covers efforts made so far toward reaching a better understanding of mixed Sn-Pb perovskites, in particular with respect to surface modifications that improved the efficiency and stability of the narrow bandgap solar cells. In addition, we also outline the important issues of integrating the narrow bandgap subcells for achieving reliable and efficient all-perovskite double- and multi-junction tandems. Future work should focus on the characterization and visualization of the specific surface defects, as well as tracking their evolution under different external stimuli, guiding in turn the processing for efficient and stable single-junction and tandem solar cell devices.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0755e441-792d-4478-869d-25be3cc6a301', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'An indicator of maturity to maximize seed yields of alfalfa', 'Government of Alberta', 1996, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/indicator-of-maturity-to-maximize-seed-yields-of-alfalfa', 'https://open.alberta.ca/dataset/a1f7c8e2-f649-4d1e-8b59-53ad347429ef/resource/e73e9fde-4bd6-4a77-922a-b8ce4c35c1c3/download/0163010144976-an-indicator-of-maturity-to-maximize-seed-yields-of-alfalfa.pdf', NULL, NULL, 67, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document presented research conducted in 1993 and 1994 to evaluate potential plant maturity indicators that could help producers optimize seed yield and quality in alfalfa. It examined pod colour, seed colour, pod moisture content, seed yields and germination responses across multiple cultivars and sites in Alberta, and assessed the effects of desiccation timing and harvest timing on yield and hard seed content. It concluded that although pod and seed colour reflected crop maturity, they were not reliable indicators for maximizing seed yield or minimizing hard seed content because yields were not linearly related to maturity and hard seeds formed early in development. It also showed that desiccation and cutting were equally effective in wet years, whereas desiccation was more effective for drying in typical dry years, and that harvest timing after desiccation did not significantly influence yield or germination.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4c83534f-ad5e-4317-9040-240979ac2a50', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Olfactory cues from plants infected by powdery mildew guide foraging by a mycophagous ladybird beetle.', 'Jun Tabata, Consuelo M De Moraes, Mark C Mescher', 2011, 'PLoS ONE', '10.1371/journal.pone.0023799', 'https://doi.org/10.1371/journal.pone.0023799', 'http://europepmc.org/articles/PMC3158101?pdf=render', NULL, NULL, 6, NULL, 'other', 1, 'open access (DOAJ)', 'Powdery mildews (Erysiphales) are economically important plant pathogens that attack many agricultural crops. Conventional management strategies involving fungicide application face challenges, including the evolution of resistance and concerns over impacts on non-target organisms, that call for investigation of more sustainable alternatives. Mycophagous ladybird beetles (Coleoptera: Coccinellidae) feed on powdery mildew and have considerable potential as biological control agents; however, the foraging ecology and behavior of these beetles is not well understood. Here we document the olfactory cues presented by squash plants (Cucurbita moschata) infected by powdery mildew (Podosphaera sp.) and the behavioral responses of twenty-spotted ladybird beetles (Psyllobora vigintimaculata) to these cues. Volatile analyses through gas chromatography revealed a number of volatile compounds characteristic of infected plants, including 3-octanol and its analogues 1-octen-3-ol and 3-octanone. These compounds are typical "moldy" odorants previously reported in volatiles collected from other fungi. In addition, infected plants exhibited elevated emissions of several compounds also observed in collections from healthy leaves, including linalool and benzyl alcohol, which are reported to have anti-fungal properties. In Y-tube choice assays, P. vigintimaculata beetles displayed a significant preference for the odors of infected plants compared to those of healthy plants. Moreover, beetles exhibited strong attraction to one individual compound, 1-octen-3-ol, which was the most abundant of the characteristic fungal compounds identified. These results enhance our understanding of the olfactory cues that guide foraging by mycophagous insects and may facilitate the development of integrated disease-management strategies informed by an understanding of underlying ecological mechanisms.', '{doaj,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1049d48e-00b3-4707-a1a4-cc760e19f735', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Participatory Ecological Assessment of Farmer Perspectives on Management of Invasive Ageratina adenophora in Eastern Bhutan', 'Bajgai RC, Bajgai Y, Johnson SB, Wong CYS', 2026, 'Plant-environment interactions (Hoboken, N.J.)', '10.1002/pei3.70110', 'https://doi.org/10.1002/pei3.70110', 'https://europepmc.org/articles/PMC12766076?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by', 'Ageratina adenophora, a native plant to Mexico, has rapidly invaded Bhutan''s landscapes from subtropical foothills to subalpine zones. This has resulted in suppressed native plant biodiversity, impacts on economically important plants, altered soil properties, and crop yield losses. Although impacted farmers managing this weed possess deep, experiential knowledge, their insights remain under-quantified and under-utilized. We aimed to assess farmers'' perspectives on the impacts and management of A. adenophora in eastern Bhutan. A focus group discussion with village leaders was held in Kanglung to refine nine literature-derived themes into five farmer-relevant priority areas: (1) weedy characteristics, (2) growth habit, (3) competitive effects, (4) control methods, and (5) awareness. A structured questionnaire was administered to 91 randomly selected farmers to rank five sub-themes under each priority area on a five-point scale. Responses were analyzed using Kruskal-Wallis rank tests and weighted-average calculations. Farmers assigned the greatest weight to characterizing A. adenophora as a weed (weedy characteristics) (28%), followed by control methods (24%), competition (20%), growth habit (16%), and awareness (12%). Sub-theme rankings differed significantly within each priority area (χ 2 ≥ 78.95, p A. adenophora as both ecologically damaging and economically harmful, prioritizing management via uprooting, burning, and burying over slashing or herbicide application. By bridging the gap in quantified farmer-perspective data through focus group discussion, structured ranking questionnaires, and non-parametric analysis, this study uses a participatory approach for integrated invasive-weed management. It is replicable to similar agroecological landscapes, aligning scientific strategies with local knowledge to enhance sustainable control of A. adenophora to protect productivity of the farming lands.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('59ef8943-2cbf-428f-a9db-9330f853b47a', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Plant community composition and dominant species drive stability in aboveground production of biofuel agroecosystems', 'Stahlheber KA, Gross KL', 2025, 'Ecological applications : a publication of the Ecological Society of America', '10.1002/eap.70085', 'https://doi.org/10.1002/eap.70085', 'https://europepmc.org/articles/PMC12509788?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'The relationship between diversity and stability remains a key question in ecology and has important consequences for understanding the sustainability (and profitability) of bioenergy cropping systems; yet to date, little work has been done to examine these relationships in agricultural systems directly. In this study, we evaluated the relationship between biodiversity (in number of planted species) and the stability of biomass production in four experimental bioenergy cropping systems established in Wisconsin and Michigan. Species composition and aboveground production were monitored at all sites for 8-10 years (2010-2019) allowing us to evaluate the temporal stability of biomass yield (defined as the temporal mean divided by the temporal SD) in these cropping systems. A major regional drought in 2012 also allowed us to evaluate resistance and resilience. Although three of the cropping systems were established with the same seed mixtures and were managed in the same way, species composition differed markedly between sites. This limited our ability to attribute differences within cropping systems across sites to the abundance of specific species. Overall, there was no clear relationship between planted species richness and yield stability in biomass production at these sites. At both sites, the lowest diversity system (switchgrass monoculture) had the highest interannual stability in production and was equivalent to that of the highest diversity treatment (prairie). Resilience to the drought was high in all treatments and did not differ among the four cropping systems; however, resistance to drought differed among systems and was highest in the switchgrass monocultures at both sites. The abundance of perennial C4 grasses increased over time in all cropping systems, except for the successional plots. The persistence of annual species in the successional treatments at both sites likely contributed to low stability and high interannual turnover in this system. We found no evidence that increasing the diversity of planted species in bioenergy cropping systems enhances stability in aboveground biomass production; nor was there any difference in resistance or resilience to drought. The higher costs of establishing more diverse bioenergy cropping systems may be warranted if other ecosystem services, such as supporting diverse pollinator and predator insect species at the landscape scale, are desired from bioenergy crops in addition to biomass production.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac4244f8-7056-461e-8c9d-47bd9e58e977', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Plant genetic transformation: achievements, current status and future prospects', 'Wang P, Si H, Li C, Xu Z, Guo H, Jin S, Cheng H', 2025, 'Plant biotechnology journal', '10.1111/pbi.70028', 'https://doi.org/10.1111/pbi.70028', 'https://europepmc.org/articles/PMC12120897?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Regeneration represents a fundamental biological process wherein an organism''s tissues or organs repair and replace themselves following damage or environmental stress. In plant systems, injured tree branches can regenerate adventitious buds and develop new crowns through propagation techniques like cuttings and canopy pruning, while transgenic plants emerge via tissue culture in genetic engineering processes intimately connected to plant regeneration mechanisms. The advancement of plant regeneration technology is critical for addressing complex and dynamic climate challenges, ultimately ensuring global agricultural sustainability. This review comprehensively synthesizes the latest genetic transformation technologies, including transformation systems across woody, herbaceous and algal species, organellar genetic modifications, crucial regeneration factors facilitating Agrobacterium-mediated transformations, the intricate hormonal networks regulating plant regeneration, comparative analyses of transient transformation approaches and marker gene dynamics throughout transformation processes. Ultimately, the review offers novel perspectives on current transformation bottlenecks and proposes future research trajectories.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('699ebb3e-5314-4e3a-994d-30f57873a0b7', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Potential and challenges for application of microbiomes in agriculture', 'Copeland C, Schulze-Lefert P, Ma KW', 2025, 'The Plant cell', '10.1093/plcell/koaf185', 'https://doi.org/10.1093/plcell/koaf185', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12379898.1/PMC12379898.1.pdf', NULL, NULL, 20, NULL, 'other', 1, 'cc by-nc-nd', 'The plant microbiome can promote plant health and productivity through a multitude of mechanisms. Our understanding of plant-microbiome interaction relies on descriptive natural surveys and experiments performed under simplified laboratory environments. While reductionist approaches are essential to understand mechanisms of plant-microbiome interactions, they risk missing emergent community properties seen in nature. To bridge the gap between basic research and real-world deployment of the microbiome for translational application, one has to consider functional association as well as ecologic principles governing interspecies and interkingdom interactions. In this review, we discuss the beneficial potential of plant microbiomes to enhance plant growth, nutrition, stress tolerance, pathogen protection, and commercial value through the modulation of taste and flavors, using examples from model plants and agriculturally important crops. We then discuss how microbial invasion and persistence in standing communities, trade-offs under multiple stressors, and community instability under host- and environment-imposed modulation should be considered in the rational design of microbial inocula, followed by a scrutiny of the method of microbial delivery. We synthesize ideas on how multiomic data, including genomics, transcriptomes, and metabolomics, can be leveraged to identify strains or target genes of interest for functional studies and how machine learning algorithms can be incorporated to enable prediction of plant-microbiome interactions. Microbiome-based strategies hold promise for improvements in agriculture. Despite the intrinsic complexity of the underlying interactions, interdisciplinary approaches are constantly providing insight into microbiome functioning and assembly principles, which is key toward knowledge-based engineering of the microbiome for increased and sustainable crop performance.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('15daf8c8-86ff-458e-b16d-a0a91bc71473', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Recent Advances in Chitosan-Based Applications-A Review', 'Thambiliyagodage C, Jayanetti M, Mendis A, Ekanayake G, Liyanaarachchi H, Vigneswaran S', 2023, 'Materials (Basel, Switzerland)', '10.3390/ma16052073', 'https://doi.org/10.3390/ma16052073', 'https://europepmc.org/articles/PMC10004736?pdf=render', NULL, NULL, 58, NULL, 'other', 1, 'cc by', 'Chitosan derived from chitin gas gathered much interest as a biopolymer due to its known and possible broad applications. Chitin is a nitrogen-enriched polymer abundantly present in the exoskeletons of arthropods, cell walls of fungi, green algae, and microorganisms, radulae and beaks of molluscs and cephalopods, etc. Chitosan is a promising candidate for a wide variety of applications due to its macromolecular structure and its unique biological and physiological properties, including solubility, biocompatibility, biodegradability, and reactivity. Chitosan and its derivatives have been known to be applicable in medicine, pharmaceuticals, food, cosmetics, agriculture, the textile and paper industries, the energy industry, and industrial sustainability. More specifically, their use in drug delivery, dentistry, ophthalmology, wound dressing, cell encapsulation, bioimaging, tissue engineering, food packaging, gelling and coating, food additives and preservatives, active biopolymeric nanofilms, nutraceuticals, skin and hair care, preventing abiotic stress in flora, increasing water availability in plants, controlled release fertilizers, dye-sensitised solar cells, wastewater and sludge treatment, and metal extraction. The merits and demerits associated with the use of chitosan derivatives in the above applications are elucidated, and finally, the key challenges and future perspectives are discussed in detail.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d5e446ae-9dc1-4004-8b8f-da516a4e5a5e', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Recent research progress on the synthesis and biological effects of selenium nanoparticles', 'Zhang T, Qi M, Wu Q, Xiang P, Tang D, Li Q', 2023, 'Frontiers in nutrition', '10.3389/fnut.2023.1183487', 'https://doi.org/10.3389/fnut.2023.1183487', 'https://europepmc.org/articles/PMC10227571?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Selenium is an essential trace element for the human body, with the chemical and physical characteristics of both metals and nonmetals. Selenium has bioactivities related to the immune system, antioxidation, anti-virus, and anti-cancer. At the same time, it also plays a role in reducing and alleviating the toxicity of heavy metals. Compared with inorganic selenium, organic selenium is less toxic and has greater bioavailability. Selenium nanoparticles (SeNPs) have the advantages of high absorption rate, high biological activity, and low toxicity, and can be directly absorbed by the human body and converted to organic selenium. Selenium nanoparticles have gradually replaced the traditional selenium supplement and has broad prospects in the food and medical industries. In this paper, the chemical, physical, and biological methods for the synthesis of selenium nanoparticles are reviewed, and the microbial synthesis methods of selenium nanoparticles, the effects of selenium nanoparticles on crop growth, and the antibacterial, antioxidant, anticancer, and anti-tumor effects of selenium nanoparticles are also systematically summarized. In addition, we evaluate the application of selenium nanoparticles in selenium nutrition enhancement, providing support for the application of selenium nanoparticles in animals, plants, and humans.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5a2042c7-fc60-49e5-8460-076d79f5c475', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Signaling Molecule Hydrogen Sulfide Improves Seed Germination and Seedling Growth of Maize (Zea mays L.) Under High Temperature by Inducing Antioxidant System and Osmolyte Biosynthesis', 'Zhou ZH, Wang Y, Ye XY, Li ZG', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01288', 'https://doi.org/10.3389/fpls.2018.01288', 'https://europepmc.org/articles/PMC6131983?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Hydrogen sulfide (H2S) is a novel type signaling molecule in plants. Seed germination is a key stage of life cycle of plants, which is vulnerable to environmental stress including high temperature. However, under high temperature stress, whether pre-soaking of maize seeds with NaHS (a H2S donor) could improve seed germination and seedling growth and the possible mechanisms are not completely clear. In this study, maize seeds pre-soaked with NaHS enhanced germination percentage, sprout length, root length, and fresh weight compared with the control without NaHS treatment, illustrating that H2S could improve maize seed germination and seedling growth under high temperature. In addition, in comparison to the control, NaHS pre-soaking stimulated antioxidant enzymes [ascorbate peroxidase (APX), glutathione reductase (GR), guaiacol peroxidase (GPX), superoxide dismutase (SOD), and catalase (CAT)] activities and the contents of water soluble non-enzymatic antioxidants [ascorbic acid (AsA) and glutathione (GSH)], as well as the ratio of reduced antioxidant to oxidized antioxidant. Moreover, pre-soaking with NaHS activated Δ1-pyrroline-5-carboxylate synthetase (P5CS) and ornithine aminotransferase [OAT; both are rate-limiting enzymes in proline (Pro) synthesis], betaine aldehyde dehydrogenase [BADH; a key enzyme in glycine betaine (GB)], and trehalose (Tre)-6-phosphate phosphatase (a key step in Tre synthesis), which in turn accumulated Pro, GB, and Tre in germinating seeds compared with the control. Also, an improved germination by NaHS under high temperature was reinforced by the above osmotic adjustment substances (osmolytes) alone, while deteriorated by the inhibitors of osmolyte biosynthesis [gabaculine (GAB), disulfiram (DSF), and sodium citrate (SC)]. These results imply that H2S could improve maize seed germination and seedling growth under high temperature by inducing antioxidant system and osmolyte biosynthesis.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('69cc165c-da27-45c4-9d70-844a73e7ce5a', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'TERMINAL FLOWER-1/CENTRORADIALIS inhibits tuberisation via protein interaction with the tuberigen activation complex', 'Zhang X, Campbell R, Ducreux LJM, Morris J, Hedley PE, Mellado-Ortega E, Roberts AG, Stephens J', 2020, 'The Plant journal : for cell and molecular biology', '10.1111/tpj.14898', 'https://doi.org/10.1111/tpj.14898', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7540344.1/PMC7540344.1.pdf', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Potato tuber formation is a secondary developmental programme by which cells in the subapical stolon region divide and radially expand to further differentiate into starch-accumulating parenchyma. Although some details of the molecular pathway that signals tuberisation are known, important gaps in our knowledge persist. Here, the role of a member of the TERMINAL FLOWER 1/CENTRORADIALIS gene family (termed StCEN) in the negative control of tuberisation is demonstrated for what is thought to be the first time. It is shown that reduced expression of StCEN accelerates tuber formation whereas transgenic lines overexpressing this gene display delayed tuberisation and reduced tuber yield. Protein-protein interaction studies (yeast two-hybrid and bimolecular fluorescence complementation) demonstrate that StCEN binds components of the recently described tuberigen activation complex. Using transient transactivation assays, we show that the StSP6A tuberisation signal is an activation target of the tuberigen activation complex, and that co-expression of StCEN blocks activation of the StSP6A gene by StFD-Like-1. Transcriptomic analysis of transgenic lines misexpressing StCEN identifies early transcriptional events in tuber formation. These results demonstrate that StCEN suppresses tuberisation by directly antagonising the function of StSP6A in stolons, identifying StCEN as a breeding marker to improve tuber initiation and yield through the selection of genotypes with reduced StCEN expression.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('66c6b6f3-0082-4f19-8595-96c1d01420f9', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Sprouted Grains: A Comprehensive Review', 'Benincasa P, Falcinelli B, Lutts S, Stagnari F, Galieni A', 2019, 'Nutrients', '10.3390/nu11020421', 'https://doi.org/10.3390/nu11020421', 'https://europepmc.org/articles/PMC6413227?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'In the last decade, there has been an increase in the use of sprouted grains in human diet and a parallel increase in the scientific literature dealing with their nutritional traits and phytochemical contents. This review examines the physiological and biochemical changes during the germination process, and the effects on final sprout composition in terms of macro- and micro-nutrients and bioactive compounds. The main factors affecting sprout composition are taken into consideration: genotype, environmental conditions experimented by the mother plant, germination conditions. In particular, the review deepens the recent knowledge on the possible elicitation factors useful for increasing the phytochemical contents. Microbiological risks and post-harvest technologies are also evaluated, and a brief summary is given of some important in vivo studies matching with the use of grain sprouts in the diet. All the species belonging to Poaceae (Gramineae) family as well as pseudocereals species are included.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8ea49f29-e2bd-4c28-a02b-dc2afaab50e5', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'The potential spatiotemporal distribution patterns of Avena nuda and Avena sativa from global perspective provide new insights for the cultivation of commonly cultivated oats', 'Lu H, Zheng Y, Zhao T, Tang L, Zhang F, Xie W', 2025, 'BMC plant biology', '10.1186/s12870-025-06590-y', 'https://doi.org/10.1186/s12870-025-06590-y', 'https://europepmc.org/articles/PMC12337537?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'BackgroundCommonly cultivated oats (Avena nuda and Avena sativa) play an important role in agricultural planting structure adjustment, ecological environment protection and grassland animal husbandry development, and their effective cultivation is conducive to food security and grassland degradation restoration. This study comprehensively collected the geographic distribution and environmental data of A. nuda and A. sativa from global regions, the ensembled niche and Marxan model were used to predict the potential spatiotemporal distribution and planting pattern of commonly cultivated oats, and further explore the environmental factors that affected the spatial distribution and genetic diversity pattern.ResultsThe results showed that: (1) The potential suitability regions of A. nuda and A. sativa were concentrated in the plateau (spanning 25°~45°N, 90°~125°E; and 40°~60°N, 10°W ~ 35°E) and plain (spanning 35°~65°N, 10°W ~ 55°E; and 30°~50°N, 65°W ~ 100°E), respectively. (2) Over time, the suitability regions of A. nuda and A. sativa showed an expanding trend. (3) The potential planting regions of A. nuda were widely distributed in the Qinghai-Tibet Plateau, Mongolia Plateau, West Siberian Plain, Iran Plateau, Bavaria Plateau and Yukon Plateau; that of A. sativa were concentrated in Central Great Plains of North America, Mississippi River Plain, Midland Plain, Bode Plain, Western Europe Plain, Eastern Europe Plain, West Siberia Plain, Central Australia Plain and Qinghai-Tibet Plateau. (4) The spatial distribution pattern of commonly cultivated oats in the current period was responsive to temperature and habitat conditions. In addition, the genetic distance of A. nuda was responsive to mean diurnal air temperature range (bio02), temperature seasonality (bio04), precipitation amount of the driest month (bio14), precipitation seasonality (bio15), and mean monthly precipitation amount of the coldest quarter (bio19), while the genetic distance of A. sativa was only affected by mean annual air temperature (bio01).ConclusionsThis study aims to explore the potential spatiotemporal and planting patterns of commonly cultivated oats in global regions, to clarify their potential distribution and planting regions, and provide an effective theoretical basis for the collection, preservation and utilization of global commonly cultivated oat population resources.Clinical trial numberNot applicable.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('23e58684-ba23-411f-8916-a1cb2bd1511f', '5e96cf25-d22f-497c-a70a-db32f77d5015', 'Would the control of invasive alien plants reduce malaria transmission? A review', 'Stone CM, Witt ABR, Walsh GC, Foster WA, Murphy ST', 2018, 'Parasites & vectors', '10.1186/s13071-018-2644-8', 'https://doi.org/10.1186/s13071-018-2644-8', 'https://europepmc.org/articles/PMC5793375?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Vector control has been the most effective preventive measure against malaria and other vector-borne diseases. However, due to concerns such as insecticide resistance and budget shortfalls, an integrated control approach will be required to ensure sustainable, long-term effectiveness. An integrated management strategy should entail some aspects of environmental management, relying on coordination between various scientific disciplines. Here, we review one such environmental control tactic: invasive alien plant management. This covers salient plant-mosquito interactions for both terrestrial and aquatic invasive plants and how these affect a vector''s ability to transmit malaria. Invasive plants tend to have longer flowering durations, more vigorous growth, and their spread can result in an increase in biomass, particularly in areas where previously little vegetation existed. Some invasive alien plants provide shelter or resting sites for adult mosquitoes and are also attractive nectar-producing hosts, enhancing their vectorial capacity. We conclude that these plants may increase malaria transmission rates in certain environments, though many questions still need to be answered, to determine how often this conclusion holds. However, in the case of aquatic invasive plants, available evidence suggests that the management of these plants would contribute to malaria control. We also examine and review the opportunities for large-scale invasive alien plant management, including options for biological control. Finally, we highlight the research priorities that must be addressed in order to ensure that integrated vector and invasive alien plant management operate in a synergistic fashion.', '{epmc,chemical}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ef07ae76-7723-4bef-b9e2-6eb747bcac5a', 'da735d67-df11-4cc5-8605-74103906bda4', 'Acme 400 ST potato planter', 'Government of Alberta', 1979, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-163', 'https://open.alberta.ca/dataset/e939e8df-3304-4cd8-926a-edf68cf1b254/resource/390d014d-42e9-4765-9eaa-6255ccd29944/download/163-afmrc.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Presents the results of an evaluation of the Acme 400 ST potato planter. Includes a general description of the potato planter, outlines the scope of the evaluation and discusses results of the testing. Also provides a brief summary and conclusions, lists recommendations made to the manufacturer to improve the product and presents the manufacturer’s response to the recommendations.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.86438+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a2cf3715-09a2-47d5-941a-1b29df42967d', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', '"We are stewards and caretakers of the land, not exploiters of resources": A qualitative study exploring Canadian farmers'' perceptions of environmental sustainability in agriculture', 'Carmichael J, Cran A, Hrvatin F, Matthews J', 2023, 'PloS one', '10.1371/journal.pone.0290114', 'https://doi.org/10.1371/journal.pone.0290114', 'https://europepmc.org/articles/PMC10427016?pdf=render', NULL, NULL, 20, NULL, 'canada', 3, 'cc by', 'Environmental sustainability in agriculture is a key component of discussions to address the current climate crisis; unfortunately, many people (including researchers) presume that only certain types of agriculture (e.g., organic, local) are environmentally sustainable. Non-farmers also fail to acknowledge that many farm practices, including grazing animals, mitigate climate change. Farmers'' perceptions about environmental sustainability are important because their livelihoods, and those of future generations, depend on their commitment to sustainable environmental practices. The purpose of this qualitative research was to understand Canadian farmers'' perceptions of environmental sustainability, how they are implementing strategies that contribute to sustainable food production, and the challenges they face. Fifty-two farmers, representing 48 farms and over 1000 years of farming experience, participated in comprehensive in-depth interviews. Four farms were in British Columbia; 13 in the Prairies; 26 in Central Canada; and five in Eastern Canada. A wide variety of farm types (e.g., fruit/vegetables, livestock, grains) and sizes (2 to 6500 acres) were included in the study. Farmers'' perceptions of environmental sustainability coalesced into four main themes: (1) definitions of sustainability and environmental sustainability, (2) current practices, (3) farming as an identity, and (4) challenges. Many participants explained that they already use sustainable practices and technology, contrary to prevailing opinion that entire food systems need to be transformed to be sustainable. As new agricultural policies and educational curricula are developed, information provided to students, policy makers, and the public must be accurate, balanced, evidence-based, and respectfully consider all perspectives, especially those of farmers.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d24a6d07-afc2-4c8d-ab46-cff7661ee8ee', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', '2024 cost and return benchmarks for crops and forages : black soil zone', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-cost-and-return-benchmarks-for-crops-and-forages-black-soil-zone', 'https://open.alberta.ca/dataset/32bfb43c-6d2f-4a5c-8629-4f1a3f5c1958/resource/c5e7b4cc-bcff-4683-8219-02625d1c41a5/download/agi-tedab-cost-and-return-benchmarks-for-crops-and-forages-black-soil-2024.pdf', NULL, NULL, 22, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The AgriProfit$ Business Analysis and Research Program collects information that is used to generate key cropping benchmarks for the major soil zones of Alberta. Annual benchmark reports enable producers to compare their productive, economic and financial performance to similar farming operations locally and provincially. Benchmark analysis is the first step in identifying cropping strengths and weaknesses. These reports contain cost and return information, and farm level financial performance.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7dc748a7-82c2-40fa-b919-b497b881690b', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', '2024 cost and return benchmarks forcrops and forages : irrigated', 'Government of Alberta', 2024, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-cost-and-return-benchmarks-for-crops-and-forages-irrigated-soil-zone', 'https://open.alberta.ca/dataset/8eba3fe4-cbc6-4a75-a092-c83f8e3adaac/resource/1d608b30-8f00-4f9b-9b5d-96c2267ace46/download/agi-tedab-cost-and-return-benchmarks-for-crops-and-forages-irrigated-2024.pdf', NULL, NULL, 20, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'The AgriProfit$ Business Analysis and Research Program collects information that is used to generate key cropping benchmarks for the major soil zones of Alberta. Annual benchmark reports enable producers to compare their productive, economic and financial performance to similar farming operations locally and provincially. Benchmark analysis is the first step in identifying cropping strengths and weaknesses. These reports contain cost and return information, and farm level financial performance.dry', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a190d1d5-cac5-4ef0-b3b8-420fb203ba82', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'A consensus of costs and returns for an 80 acre leafcutter bee and alfalfa seed enterprise in the eastern irrigation district of Alberta, June, 1992', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/consensus-of-costs-and-returns-for-80-acre-leafcutter-bee-alfalfa-seed-enterprise', 'https://open.alberta.ca/dataset/49c47e06-f1e7-4d07-9309-c08e7b497c41/resource/7146eeb6-87c9-441a-88a4-1a7d7ca05582/download/0163003146764-consensus-costs-returns-80-acre-leafcutter-bee-alfalfa-seed-enterprise-t.pdf', NULL, NULL, 29, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This report provides an estimate of the costs and returns for an 80-acre leafcutter bee and alfalfa seed enterprise in the Eastern Irrigation District of Alberta, based on a consensus of local farmers. It details investment and operational costs, revenue, and gross margins for both the leafcutter bee and alfalfa seed components. The report serves as a guide for management decisions, helping producers evaluate profitability, cash flow, and resource allocation within this specialized agricultural sector.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9460a5e0-73ab-48f0-8082-7d4bb01673c8', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'AgriProfit$ cost & returns profiles. Dryland legume/grass establishment underseeded to annual forage : Alberta total', 'Government of Alberta', 2012, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriprofit-cost-returns-profiles-dryland-legume-grass-establishment-underseeded-to-annual-forage', 'https://open.alberta.ca/dataset/e0d8fe28-8259-41fb-afbe-0c24f639fe1a/resource/b2bf9bdf-e2e4-419d-98dc-f59c7b79516a/download/2012-dryland-legume-grass-establishment-underseeded-to-annual-forage-alberta-total-2012-07-30.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'AgriProfit$ cost and returns profiles give an insight into the productive and economic performance of Alberta cereal, oilseed, forage and grazing crops, reported by soil or grass-type zone. These benchmark include field observations from the period 2008 to 2010. Averaging over a three-year span smooths out extremes in prices, yields and expenses and gives a better reflection of the crops’ intermediate term costs and profit potential.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d92dcd9a-dbbc-4dbe-bc9a-7ed5e2e21403', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Alberta forage manual (2nd Edition)', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/077326082x', 'https://open.alberta.ca/dataset/3c314aac-a373-424f-9636-eb69b40f416e/resource/17d48b63-90bd-49b4-ad88-78a618febcd9/download/120-20-1-2009.pdf', NULL, NULL, 354, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The Alberta Forage Manual, 2nd Edition, offers producers comprehensive information on a range of forage topics: adaptation, legumes and grasses, annuals, mixtures, establishment, fertility, pasture management, harvesting and rejuvenation. In addition, sections on forage pest insects and diseases present detailed discussion of these problems in forage crops, helping producers diagnose damage. The extensive descriptions of forage species and their growth habits will help in planning forage management programs. Fully illustrated with colour images, line drawings, tables, charts and graphs, this forage reference work provides a wealth of information.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('20db1d79-8c0c-49e7-9553-5619dd4de908', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Alfalfa insect survey (2014F)62R : comprehensive report on Alberta Alfalfa Survey , 2014-2016', 'Government of Alberta', 2016, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/alfalfa-insect-survey', 'https://open.alberta.ca/dataset/12153161-bf45-4e0e-9283-855598d1de59/resource/821b9557-0aef-4fd5-aace-83dd0e8f75ce/download/alfalfa-final-report.pdf', NULL, NULL, NULL, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The insect survey underway will allow the establishment of baseline population numbers for alfalfa insects, document population range expansion by known pest species, and identify the presence and range of any potential new risk species. The benefits of the insect survey will help inform ongoing and future surveillance work, allowing for informed integrated pest management practices.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8b404303-eb26-4c1d-b982-dbea7622c98e', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'An analysis report on the role of livestock and forage in soil and water conservation', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/analysis-report-on-the-role-of-livestock-and-forage-in-soil-and-water-conservation', 'https://open.alberta.ca/dataset/f74345bb-3a9d-457b-9bb7-287f13844f7c/resource/376031dc-5300-43ee-9f58-cb935abe6c59/download/0163040836062-analysis-report-role-livestock-forage-soil-water-conservation.pdf', NULL, NULL, 48, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report analyzes the role of livestock and forage in soil and water conservation, summarizing a scientific monograph on the topic. It examines the characteristics of forage lands, forage plants, and livestock, along with their integrated and self-sustaining systems. The document also investigates the impacts of these systems on soil fertility, water quality and quantity, greenhouse gas emissions, and wildlife habitat. Furthermore, it identifies research gaps and outlines a framework for future multi-disciplinary research, including economic and educational requirements, to enhance conservation efforts and public understanding.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aabfa71f-92f6-4a2d-80c9-dc9fcd70d5fb', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Attitudes and opportunities: comparing climate change adaptation intentions and decisions of agricultural producers in Shaanxi, China, and British Columbia, Canada', 'Mu L, Janmaat J, Taylor J, Arnold L', 2023, 'Mitigation and adaptation strategies for global change', '10.1007/s11027-022-10040-7', 'https://doi.org/10.1007/s11027-022-10040-7', 'https://europepmc.org/articles/PMC9755003?pdf=render', NULL, NULL, 27, NULL, 'canada', 3, 'open access (Europe PMC)', 'Climate change poses a major challenge for agricultural producers. There are a variety of adaptation strategies producers can use to enhance their resilience to the changing climate. The theory of planned behavior is applied as a framework to compare the adaptation intentions and choices of producers in Cariboo and Okanagan regions of the province of British Columbia (BC), Canada, and Baoji and Xi''an city prefectures of Shaanxi (SX) province, China. In BC, producers are more likely to explore the use of new crop varieties, and BC producers also seem to have a stronger intention to invest in irrigation efficiency. In contrast, producers in SX are far more likely to use online marketing methods to connect directly with consumers. Based on transcripts from a set of focus groups, community meetings, and interviews, differences in attitudes, social norms, and perceived behavioral control between SX and BC producers are identified that may contribute to their different adaptation choices. Multiple barriers to adaptation existed in both areas. Limited technical knowledge and doubts about adaptation effectiveness were more serious in BC, while limited support from local government and normative expectations were notable in SX. Education, targeted research, and public investments in irrigation and marketing may contribute to addressing some of these differences, improving the resilience of agricultural climate adaptation in both provinces.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a19f15af-426a-46ef-a148-17d3e321612a', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Application of Machine Learning Algorithms in Plant Breeding: Predicting Yield From Hyperspectral Reflectance in Soybean', 'Yoosefzadeh-Najafabadi M, Earl HJ, Tulpan D, Sulik J, Eskandari M', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.624273', 'https://doi.org/10.3389/fpls.2020.624273', 'https://europepmc.org/articles/PMC7835636?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by', 'Recent substantial advances in high-throughput field phenotyping have provided plant breeders with affordable and efficient tools for evaluating a large number of genotypes for important agronomic traits at early growth stages. Nevertheless, the implementation of large datasets generated by high-throughput phenotyping tools such as hyperspectral reflectance in cultivar development programs is still challenging due to the essential need for intensive knowledge in computational and statistical analyses. In this study, the robustness of three common machine learning (ML) algorithms, multilayer perceptron (MLP), support vector machine (SVM), and random forest (RF), were evaluated for predicting soybean (Glycine max) seed yield using hyperspectral reflectance. For this aim, the hyperspectral reflectance data for the whole spectra ranged from 395 to 1005 nm, which were collected at the R4 and R5 growth stages on 250 soybean genotypes grown in four environments. The recursive feature elimination (RFE) approach was performed to reduce the dimensionality of the hyperspectral reflectance data and select variables with the largest importance values. The results indicated that R5 is more informative stage for measuring hyperspectral reflectance to predict seed yields. The 395 nm reflectance band was also identified as the high ranked band in predicting the soybean seed yield. By considering either full or selected variables as the input variables, the ML algorithms were evaluated individually and combined-version using the ensemble-stacking (E-S) method to predict the soybean yield. The RF algorithm had the highest performance with a value of 84% yield classification accuracy among all the individual tested algorithms. Therefore, by selecting RF as the metaClassifier for E-S method, the prediction accuracy increased to 0.93, using all variables, and 0.87, using selected variables showing the success of using E-S as one of the ensemble techniques. This study demonstrated that soybean breeders could implement E-S algorithm using either the full or selected spectra reflectance to select the high-yielding soybean genotypes, among a large number of genotypes, at early growth stages.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c8c19c71-1740-4752-9b24-d96c9a60f7f1', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Application of machine learning and genetic optimization algorithms for modeling and optimizing soybean yield using its component traits', 'Yoosefzadeh-Najafabadi M, Tulpan D, Eskandari M', 2021, 'PloS one', '10.1371/journal.pone.0250665', 'https://doi.org/10.1371/journal.pone.0250665', 'https://europepmc.org/articles/PMC8087002?pdf=render', NULL, NULL, 18, NULL, 'canada', 3, 'cc by', 'Improving genetic yield potential in major food grade crops such as soybean (Glycine max L.) is the most sustainable way to address the growing global food demand and its security concerns. Yield is a complex trait and reliant on various related variables called yield components. In this study, the five most important yield component traits in soybean were measured using a panel of 250 genotypes grown in four environments. These traits were the number of nodes per plant (NP), number of non-reproductive nodes per plant (NRNP), number of reproductive nodes per plant (RNP), number of pods per plant (PP), and the ratio of number of pods to number of nodes per plant (P/N). These data were used for predicting the total soybean seed yield using the Multilayer Perceptron (MLP), Radial Basis Function (RBF), and Random Forest (RF), machine learning (ML) algorithms, individually and collectively through an ensemble method based on bagging strategy (E-B). The RBF algorithm with highest Coefficient of Determination (R2) value of 0.81 and the lowest Mean Absolute Errors (MAE) and Root Mean Square Error (RMSE) values of 148.61 kg.ha-1, and 185.31 kg.ha-1, respectively, was the most accurate algorithm and, therefore, selected as the metaClassifier for the E-B algorithm. Using the E-B algorithm, we were able to increase the prediction accuracy by improving the values of R2, MAE, and RMSE by 0.1, 0.24 kg.ha-1, and 0.96 kg.ha-1, respectively. Furthermore, for the first time in this study, we allied the E-B with the genetic algorithm (GA) to model the optimum values of yield components in an ideotype genotype in which the yield is maximized. The results revealed a better understanding of the relationships between soybean yield and its components, which can be used for selecting parental lines and designing promising crosses for developing cultivars with improved genetic yield potential.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1005134c-3137-4cb1-811e-ee50aceea1b3', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Applying manure on perennial forage', 'Government of Alberta', 2006, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3483975', 'https://open.alberta.ca/dataset/e2bcf4de-b51f-4c1d-88e6-06b1654f80ed/resource/b62452a1-d864-42c8-8a33-2db4d79d8714/download/2006-538-120-2.pdf', NULL, NULL, 32, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This manual’s objective is to provide livestock and perennial forage crop producers with the information and tools to make decisions about applying manure on perennial forage crops. It also contains information on the regulations for applying manure on forage crops, and resources for more in-depth information or assistance.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a27f4d20-2854-4ed8-a674-bd8fb82e9d5c', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Fertilizer requirements of irrigated alfalfa', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2473227', 'https://open.alberta.ca/dataset/d9df3070-58bf-43d2-9b62-99c11dcf6f33/resource/73b3fc9c-e5c2-4992-b638-69a577e3b380/download/2001-561-18.pdf', NULL, NULL, 4, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Ensuring soil fertility levels are adequate is a major factor to consider when growing irrigated alfalfa in southern Alberta. Irrigated alfalfa will produce 5 to 6 tons of dry matter per acre if it receives sufficient amounts of water and nutrients. Climate, soil type and management will all affect the yield a producer can expect from an alfalfa crop. Alfalfa has a high demand for nutrients compared to other crops.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d610a36a-f0f6-4b09-86fa-7757819be564', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Applying manure on perennial forage : a summary', 'Government of Alberta', 2006, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3499979', 'https://open.alberta.ca/dataset/dfa907b8-bdaf-4e3b-a584-1866747b593a/resource/6a875f6c-ead0-49ce-9efe-8dab7ef5a3e6/download/2006-538-120-1.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Alberta has about 25 million acres of forage land (native and tame hay and pasture). In some cases, applying manure to forage land may be the best option to make use of the nutrients in manure in an environmentally sustainable way. As well, applying manure can increase forage productivity and reduce commercial fertilizer costs. Manure is a valuable nutrient source for forage crops as it contains all the major plant nutrients and a number of essential micronutrients. Manure may also enhance soil physical properties such as water infiltration rate and aggregate size and stability, leading to better tilth and improved yields.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('07b2364f-bc0c-42f4-bc6d-6cce3600f4a0', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Forage growers guide to round baling', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-717', 'https://open.alberta.ca/dataset/43430fe6-385d-441b-8895-e5836abddb66/resource/d3fd6cf4-2733-42da-8a2e-82304e1b96cf/download/717-afmrc.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The Prairie Agricultural Machinery Institute has evaluated many round balers. This Research Update summarizes their experience and gives useful tips on how to round bale better.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8da49816-02a5-4aff-9101-4f2f6d9d4a8f', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Branching Out: Rabbit Models Provide Evidence for the Use of a Willow Cultivar (Salix miyabeana) as a Suitable Forage Material for Monogastric Herbivores in Zoos', 'Martin B, Shoveller AK, Kosmal PAL', 2025, 'Journal of animal physiology and animal nutrition', '10.1111/jpn.14130', 'https://doi.org/10.1111/jpn.14130', 'https://europepmc.org/articles/PMC12451416?pdf=render', NULL, NULL, 10, NULL, 'canada', 3, 'cc by-nc-nd', 'We assessed the suitability of a willow cultivar for monogastric herbivores in zoos using a rabbit model. Thirty-six male New Zealand White × Californian rabbits at 5 weeks of age were provided with bark and leaf material from a willow cultivar, Salix miyabeana (SX61), in one of four treatments for 6 weeks: UC (unrestricted control of pelleted diet); RC (restricted control of pelleted diet); TL (restricted pellets + fresh willow leaf material); and TB (restricted pellets + fresh willow bark material). Daily feed intake and weekly weights were recorded. Fasted blood samples were taken between 8:00 and 11:00 h, and blood biochemistry and acute phase protein (APP) were quantified at the start and end of the study. After the 6-week study period, rabbits were euthanized, and liver and kidney weights were obtained to assess hepatocellular damage. Blood biochemistry results were mainly within reference ranges and suggest a lack of toxicity or cellular damage due to feeding different amounts of willow ingredients. Greater weight gain was observed in the UC group when compared to the RC (p < 0.01), TB, and TL (p < 0.05) groups at the end of the treatment period. Total dry matter (DM) intake was greater in both TB and TL treatment groups when compared to the RC group but lower than the UC group (p < 0.05) across the treatment period. At the end of the study, phosphorus, magnesium, glucose, and AST were lower in the RC group when compared to all other treatment groups (p < 0.05) with a greater blood urea nitrogen than the TL and TB groups (p < 0.01). The TL group had greater blood potassium concentrations and a lower Na:K ratio than the UC and TB groups (p < 0.01). No differences were observed in the APP response over time and among groups; only fibrinogen was greater in the RC compared to the TB group (p < 0.05). The relative liver weight was higher in the UC group when compared to TB (p < 0.05). Given these results, willow bark and leaves at a high dietary inclusion can be considered safe and effective forage materials for monogastric herbivores in zoos.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('69092ab1-2bb7-4a5a-8a06-d17238f21af3', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Buteo Nesting Ecology: Evaluating Nesting of Swainson''s Hawks in the Northern Great Plains', 'Inselman WM, Datta S, Jenks JA, Jensen KC, Grovenburg TW', 2015, 'PloS one', '10.1371/journal.pone.0137045', 'https://doi.org/10.1371/journal.pone.0137045', 'https://europepmc.org/articles/PMC4556518?pdf=render', NULL, NULL, 12, NULL, 'prairies', 4, 'cc by', 'Swainson''s hawks (Buteo swainsoni) are long-distance migratory raptors that nest primarily in isolated trees located in areas of high grassland density. In recent years, anthropogenic conversion of grassland habitat has raised concerns about the status of the breeding population in the northern Great Plains. In 2013, we initiated a study to investigate the influence of extrinsic factors influencing Swainson''s hawk nesting ecology in north-central South Dakota and south-central North Dakota. Using ground and aerial surveys, we located and monitored nesting Swainson''s hawk pairs: 73 in 2013 and 120 in 2014. We documented 98 successful breeding attempts that fledged 163 chicks; 1.52 and 1.72 fledglings per successful nest in 2013 and 2014, respectively. We used Program MARK to evaluate the influence of land cover on nest survival. The top model, SDist2Farm+%Hay, indicated that nest survival (fledging at least one chick) decreased as nests were located farther from farm sites and as the percent of hay cover increased within 1200-m of the nest site (34.4%; 95% CI = 27.6%-42.3%). We used logistic regression analysis to evaluate the influence of landscape variables on nest-site selection; Swainson''s hawks selected for nest sites located closer to roads. We suggest that tree belts associated with farm sites, whether occupied or not, provide critical breeding sites for Swainson''s hawks. Additionally, poor breeding success may be related to the late migratory behavior of this species which requires them to occupy marginal habitat due to other raptors occupying the most suitable habitat prior to Swainson''s hawks arriving to the breeding grounds.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('282ba232-4631-44ce-9a2f-e9152ec8f962', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Can Agro-Industrial By-Products Rich in Polyphenols be Advantageously Used in the Feeding and Nutrition of Dairy Small Ruminants?', 'Correddu F, Lunesu MF, Buffa G, Atzori AS, Nudda A, Battacone G, Pulina G', 2020, 'Animals : an open access journal from MDPI', '10.3390/ani10010131', 'https://doi.org/10.3390/ani10010131', 'https://europepmc.org/articles/PMC7022336?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'Recently, the interest in industrial by-products produced at the local level in Mediterranean areas, resulting from fruit and vegetable processes, has increased because of their considerable amounts of bioactive compounds, including polyphenols. In this review, we analyze the most recent scientific results concerning the use of agro-industrial by-products, naturally rich in polyphenols (BPRP), in the diets of small dairy ruminants. Effects on milk production, milk and rumen liquor fatty acid profile, metabolic parameters, and methane production are reviewed. The feed intake and digestibility coefficients were generally depressed by BPRP, even though they were not always reflected in the milk yield. The main observed positive effects of BPRP were on quality of the milk''s FA profile, antioxidant activity in milk and blood, a reduction of rumen ammonia, and, consequently, a reduction of milk and blood urea. The expected beneficial effects of dietary polyphenols in small ruminants were not always observed because of their complex and variable matrices. However, owing to the large quantities of these products available at low prices, the use of BPRB in small ruminant nutrition offers a convenient solution to the valorization of residues arising from agricultural activities, reducing feed costs for farmers and conferring added value to dairy products at the local level, in a sustainable way.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2a74cbf2-e5be-4bd2-9eef-bacd6967468f', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Coating of forage legume seeds with rhizobium inoculants', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/coating-of-forage-legume-seeds-with-rhizobium-inoculants', 'https://open.alberta.ca/dataset/ca2f7062-4183-4fd9-be1e-1768e0c1c857/resource/021d5a45-225f-4249-9b7d-5dcc6e5f4d50/download/0163003280779-coating-of-forage-legume-seeds-with-rhizobium-inoculants.pdf', NULL, NULL, 104, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated whether the natural slime layer produced by Rhizobium could serve as a coating and protective agent to improve the viability of rhizobia on precoated legume seeds. Commercial inoculants for alfalfa and clover are often applied before planting, but rhizobia viability may decline during storage. Seeds precoated with the slime were stored for up to 6 months at refrigerated and room temperatures. Results showed that the slime helped extend rhizobial viability under certain conditions, although it was not a complete solution for long-term preservation.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a6707df8-bab3-407c-ab9d-c309cbfc3379', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Influence of crop rotation, tillage, and management inputs on weed seed production', 'George O. Kegode, Frank Forcella, Sharon A. Clay', 1999, 'Weed Science', '10.1017/s0043174500091591', 'https://doi.org/10.1017/s0043174500091591', 'https://openprairie.sdstate.edu/plant_faculty_pubs/231', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b279d9bb-613b-4b3a-bae9-118970696815', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Complete genome sequences of Streptomyces spp. isolated from disease-suppressive soils', 'Heinsch SC, Hsu SY, Otto-Hanson L, Kinkel L, Smanski MJ', 2019, 'BMC genomics', '10.1186/s12864-019-6279-8', 'https://doi.org/10.1186/s12864-019-6279-8', 'https://europepmc.org/articles/PMC6923854?pdf=render', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc by', 'BackgroundBacteria within the genus Streptomyces remain a major source of new natural product discovery and as soil inoculants in agriculture where they promote plant growth and protect from disease. Recently, Streptomyces spp. have been implicated as important members of naturally disease-suppressive soils. To shine more light on the ecology and evolution of disease-suppressive microbial communities, we have sequenced the genome of three Streptomyces strains isolated from disease-suppressive soils and compared them to previously sequenced isolates. Strains selected for sequencing had previously showed strong phenotypes in competition or signaling assays.ResultsHere we present the de novo sequencing of three strains of the genus Streptomyces isolated from disease-suppressive soils to produce high-quality complete genomes. Streptomyces sp. GS93-23, Streptomyces sp. 3211-3, and Streptomyces sp. S3-4 were found to have linear chromosomes of 8.24 Mb, 8.23 Mb, and greater than 7.5 Mb, respectively. In addition, two of the strains were found to have large, linear plasmids. Each strain harbors between 26 and 38 natural product biosynthetic gene clusters, on par with previously sequenced Streptomyces spp. We compared these newly sequenced genomes with those of previously sequenced organisms. We see substantial natural product biosynthetic diversity between closely related strains, with the gain/loss of episomal DNA elements being a primary driver of genome evolution.ConclusionsLong read sequencing data facilitates large contig assembly for high-GC Streptomyces genomes. While the sample number is too small for a definitive conclusion, we do not see evidence that disease suppressive soil isolates are particularly privileged in terms of numbers of biosynthetic gene clusters. The strong sequence similarity between GS93-23 and previously isolated Streptomyces lydicus suggests that species recruitment may contribute to the evolution of disease-suppressive microbial communities.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e00307e0-1b3a-4a9b-a74b-be59ddd208bf', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Crop diversification in Idaho''s Magic Valley: the present and the imaginary', 'Spangler K, Burchfield EK, Radel C, Jackson-Smith D, Johnson R', 2022, 'Agronomy for sustainable development', '10.1007/s13593-022-00833-0', 'https://doi.org/10.1007/s13593-022-00833-0', 'https://europepmc.org/articles/PMC9557999?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'open access (Europe PMC)', 'The simplification of agricultural landscapes, particularly in the United States (US), has contributed to alarming rates of environmental degradation. As such, increasing agrobiodiversity throughout the US agri-food system is a crucial goal toward mitigating these harmful impacts, and crop diversification is one short-term mechanism to begin this process. However, despite mounting evidence of its benefits, crop diversification strategies have yet to be widely adopted in the US. Thus, we explore barriers and bridges to crop diversification for current farmers, focused on the Magic Valley of southern Idaho-a region with higher crop diversity relative to the US norm. We address two main research questions: (1) how and why do farmers in this region enact temporal and/or spatial strategies to manage crop diversity (the present) and (2) what are the barriers and bridges to alternative diversification strategies (the imaginary)? Through a political agroecology and spatial imaginaries lens, we conducted and analyzed 15 farmer and 14 key informant interviews between 2019 and 2021 to gauge what farmers are doing to manage crop diversity (the present) and how they imagine alternative landscapes (the imaginary). We show that farmers in this region have established a regionally diversified landscape by relying primarily on temporal diversification strategies-crop rotations and cover cropping-but do not necessarily pair these with other spatial diversification strategies that align with an agroecological approach. Furthermore, experimenting with and imagining new landscapes is possible (and we found evidence of such), but daily challenges and structural constraints make these processes not only difficult but unlikely and even "dangerous" to dream of. Therein, we demonstrate the importance of centering who is farming and why they make certain decisions as much as how they farm to support agroecological transformation and reckoning with past and present land use paradigms to re-imagine what is possible.Supplementary informationThe online version contains supplementary material available at 10.1007/s13593-022-00833-0.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('926bcf2a-b730-409d-8ea2-eb7dda499e20', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Effects of microbial inoculants on the fermentation characteristics and feeding value of alfalfa silage', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/effects-of-microbial-inoculants-on-the-fermentation-characteristics-and-feeding-value-of-alfalf', 'https://open.alberta.ca/dataset/dd1af2f3-b2d8-4bae-af5a-765ceb4ca7a2/resource/2a871842-dfac-4274-8502-2e5718d4e7d5/download/0163010303812-effects-microbial-inoculants-fermentation-characteristics-feeding-value-alfalf.pdf', NULL, NULL, 38, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study evaluated the effects of two commercial silage inoculants, Silogen and Sila-Bac, on the fermentation characteristics of field-wilted, second-cut alfalfa (Medicago sativa L.) ensiled for 124 days and fed to Charolais cross Hereford steers. Application of Sila-Bac significantly reduced silage pH and propionic acid content, while both inoculants resulted in lower total nitrogen compared to the control. Steers fed silage treated with Silogen or Sila-Bac tended to have slightly higher average daily gain and heavier final bodyweights, along with small improvements in dry matter-to-gain ratio, though these effects were not statistically significant. Use of silage inoculants improved net economic returns, primarily due to minor increases in average daily gain and feed efficiency.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('85af763e-2144-4348-9aff-1b988e3ccd50', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Data-driven and machine learning framework for Alfalfa yield response to long-term climate variability in the Kansas High Plains (USA)', 'Nazrul F, Kim J, Dey S, Whitaker B, Sihi D, Min D, Jha G', 2026, 'Scientific reports', '10.1038/s41598-026-55545-2', 'https://doi.org/10.1038/s41598-026-55545-2', 'https://europepmc.org/articles/PMC13478387?pdf=render', NULL, NULL, 21, NULL, 'northern_plains', 3, 'cc by', 'Climate extremes and declining water availability in the U.S. High Plains threaten the long-term sustainability of alfalfa production. This study presents a machine learning (ML) based modeling framework to identify and evaluate key agro-climatic predictors of alfalfa (Medicago sativa L.) yield across nine agricultural districts in Kansas from 1981 to 2018. A novel contribution of this study is the integration of a high-dimensional climate predictor space, long-term historical records, and district-level stratification of irrigated and rainfed systems to systematically assess spatially varying climate-yield relationships. Using a high-dimensional feature space of 117 climate-derived variables from PRISM and yield data from USDA-NASS, a Minimum Redundancy Maximum Relevance (mRMR) algorithm was applied to rank predictors, followed by forward feature selection with three non-parametric regression models. Four spatial configurations were evaluated-statewide, district-specific, irrigated, and rainfed datasets. The Kansas High Plains region, with its strong west-to-east precipitation gradient, groundwater-dependent irrigation systems, and recurrent drought exposure, offers a globally relevant testbed for understanding crop-climate interactions in semi-arid environments. Model evaluation RMSE during feature selection ranged from 0.52 to 1.14 tons/acre. Dew point temperature in August and seasonal VPD metrics emerged as dominant predictors, indicating these variables are strongly associated with late-summer yield variability. Rainfed districts prioritized drought indicators (e.g., no precipitation days, VPD), while irrigated districts showed stronger associations with thermal and humidity metrics. By explicitly accounting for climate sensitivities across management regimes and spatial scales, this framework provides a transferable approach for identifying robust, region-specific climate drivers in high-dimensional agricultural datasets.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b26add8-370d-4e1e-b0f9-481e9c870c8e', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Decoding dark septate endophyte symbiosis: a functional and ecological perspective', 'Mandyam K, Jumpponen A', 2026, 'FEMS microbiology reviews', '10.1093/femsre/fuag035', 'https://doi.org/10.1093/femsre/fuag035', 'https://europepmc.org/articles/PMC13495795?pdf=render', NULL, NULL, 39, NULL, 'northern_plains', 3, 'cc by-nc', 'Plant root microbial symbioses influence plant performance and ecosystem processes. Among these, dark septate endophyte (DSE) fungi are ubiquitous, non-mycorrhizal root endophytes with broad host ranges that facilitate nutrient acquisition, mitigate biotic and abiotic stress, and elicit positive, neutral, or negative plant growth responses depending on host and environmental context. Comparative genomic and transcriptomic analyses provide a robust framework for evaluating DSE lifestyles. Beyond their direct effects on plants, fungal endophytes contribute to soil microbiome networks, soil health, regenerative agriculture, and One Health. Integrating comparative genomics, transcriptomics, microbiome ecology, soil health, and agricultural studies, we present a systems-level synthesis of DSE biology that identifies key knowledge gaps and advances our understanding of DSE ecology and function. Comparative genomic, transcriptomic, and ecological evidence indicates that DSE share molecular and functional characteristics with ericoid mycorrhizal fungi, consistent with a hypothesized transition from saprotrophic toward specialized root-associated lifestyles. Their melanin production, extensive CAZyme repertoires, and broad ecological distribution suggest important roles in microbiome assembly, nutrient cycling, carbon dynamics, soil aggregation, and plant stress tolerance. We conclude by presenting an integrated framework linking plant-soil-fungus-environment interactions that defines core DSE competencies and highlights their importance for ecosystem functioning and sustainable agriculture.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('05e435a7-b64f-44a7-a1cc-438c653a6cd2', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Differential Reductions in Total and Compositional PM2.5 Exposure across Socioeconomic and Demographic Groups from Emission Source Mitigation in Canada (2007-2016)', 'Delic A, Kunarac K, Chen L, Pappin A, van Donkelaar A, Martin R, Chen H', 2026, 'Environmental science & technology', '10.1021/acs.est.5c17598', 'https://doi.org/10.1021/acs.est.5c17598', 'https://europepmc.org/articles/PMC13130957?pdf=render', NULL, NULL, 13, NULL, 'canada', 3, 'cc by', 'Fine particulate matter (PM2.5) is a leading risk factor for morbidity and mortality worldwide. Recent studies have shown substantial heterogeneity in exposure to PM2.5 within populations, with socially disadvantaged subgroups exhibiting disproportionally higher exposure. However, the extent to which reductions in PM2.5 and its components may differentially affect these subgroups remains unclear. Leveraging state-of-the-art exposure surfaces that simulate annual reductions in total and compositional PM2.5 from major emission sectors under two policy scenarios (20% and 100%), based on satellite observations and a global chemical transport model, we characterized the expected reductions in total and compositional population-weighted PM2.5 exposure by selected subgroups for 2007 and 2016. Under both scenarios, we found that certain subgroups, particularly low-income people, immigrants, and racialized groups, would experience larger reductions in exposure to total and compositional PM2.5. The largest decreases were associated with nitrates, sulfates, and ammonia from agriculture, nitrates and black carbon from transportation, and organic matter from residential wood combustion. These findings have important implications for PM2.5 mitigation strategies aimed at reducing population exposure and associated disparities in Canada.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06834ca6-842a-405a-9d32-f7d6622c0fbd', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Disease and predation: sorting out causes of a bighorn sheep (Ovis canadensis) decline', 'Smith JB, Jenks JA, Grovenburg TW, Klaver RW', 2014, 'PloS one', '10.1371/journal.pone.0088271', 'https://doi.org/10.1371/journal.pone.0088271', 'https://europepmc.org/articles/PMC3917862?pdf=render', NULL, NULL, 9, NULL, 'northern_plains', 3, 'cc0', 'Estimating survival and documenting causes and timing of mortality events in neonate bighorn sheep (Ovis canadensis) improves understanding of population ecology and factors influencing recruitment. During 2010-2012, we captured and radiocollared 74 neonates in the Black Hills, South Dakota, of which 95% (70) died before 52 weeks of age. Pneumonia (36%) was the leading cause of mortality followed by predation (30%). We used known fate analysis in Program MARK to estimate weekly survival rates and investigate the influence of intrinsic variables on 52-week survival. Model {S1 wk, 2-8 wks, >8 wks} had the lowest AIC c (Akaike''s Information Criterion corrected for small sample size) value, indicating that age (3-stage age-interval: 1 week, 2-8 weeks, and >8 weeks) best explained survival. Weekly survival estimates for 1 week, 2-8 weeks, and >8 weeks were 0.81 (95% CI = 0.70-0.88), 0.86 (95% CI = 0.81-0.90), and 0.94 (95% CI = 0.91-0.96), respectively. Overall probability of surviving 52 weeks was 0.02 (95% CI = 0.01-0.07). Of 70 documented mortalities, 21% occurred during the first week, 55% during weeks 2-8, and 23% occurred >8 weeks of age. We found pneumonia and predation were temporally heterogeneous with lambs most susceptible to predation during the first 2-3 weeks of life, while the greatest risk from pneumonia occurred from weeks 4-8. Our results indicated pneumonia was the major factor limiting recruitment followed by predation. Mortality from predation may have been partly compensatory to pneumonia and its effects were less pronounced as alternative prey became available. Given the high rates of pneumonia-caused mortality we observed, and the apparent lack of pneumonia-causing pathogens in bighorn populations in the western Black Hills, management activities should be geared towards eliminating contact between diseased and healthy populations.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('298a1dd0-fe78-4633-8d4f-113a56a22b86', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Dissecting Vegetative Period Into Its Phenotypic and Genotypic Components Allows Environment-Specific Breeding in Lentil (Lens culinaris Medik)', 'Osuna-Caballero S, Heidecker T, Weller JL, Bett KE', 2026, 'Physiologia plantarum', '10.1111/ppl.70729', 'https://doi.org/10.1111/ppl.70729', 'https://europepmc.org/articles/PMC12746221?pdf=render', NULL, NULL, 17, NULL, 'prairies', 4, 'cc by', 'In legumes, flowering time is regulated by genes responsive to temperature and photoperiod, presenting challenges for high-latitude lentil producers who must adapt cultivars to short growing seasons and extended daylight hours. Therefore, prolonged vegetative periods are favored in those areas. To address this, we studied a recombinant inbred line (RIL) population, derived from a cross between the adapted cultivar CDC-Milestone and the non-adapted line ILL8006, to investigate phenology-related traits under long-day conditions in western Canada. Significant variation in days to emergence (DTE), days to flowering (DTF), and days to pod maturity (DTM) enabled analysis of the vegetative (VegP) and reproductive (RepP) periods within the population. We constructed a high-density genetic linkage map using molecular markers linked to genes in the Lcu.2RBY reference genome, identifying quantitative trait loci (QTLs) for those traits across four site-years in Saskatchewan. Differential expression analysis of known flowering time genes enhanced interpretation of the QTL results for flowering time. Three major DTE QTLs (qDTE2/3.II, qDTE2/3.III, and qDTE2/3.IV) on chromosome 2 explained 16%-28% phenotypic variability, depending on the environment, with in silico analysis identifying six curated genes as putative candidates within that region. A key DTF QTL (qDTF6.I) on chromosome 6 accounted for 23%-56% of phenotypic variability, harboring a homolog of the FLOWERING LOCUS T gene, whose role was explored alongside other candidate genes. Dissecting the vegetative period into DTE and DTF revealed distinct genetic controls for each trait, enabling breeders to combine early or late emergence and flowering to optimize adaptation and yield in diverse agroclimatic conditions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('843f0831-9f7e-405a-9ddc-d9dd185856f1', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Drivers of seasonal space use and movements of mule deer in agriculturally modified landscapes of the Great Plains', 'Asmus KA, Dougherty KD, Meduna L, Nordeen TD, Cherry MJ, Stephenson TR, Benson JF', 2026, 'Movement ecology', '10.1186/s40462-026-00639-9', 'https://doi.org/10.1186/s40462-026-00639-9', 'https://europepmc.org/articles/PMC13020411?pdf=render', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'BACKGROUND: Understanding how key resources and anthropogenic disturbance influence animal space use and movement is essential for informing management of declining populations. Mule deer are studied extensively in mountainous and desert regions of North American. Yet, little is known about mule deer spatial ecology along the eastern periphery of their geographic range in prairie and agricultural landscapes in the Great Plains of Nebraska, where some populations appear to be declining. METHODS: We tracked 240 adult female mule deer with GPS telemetry to estimate seasonal home range size and movements in four study units in western Nebraska with highly variable natural and anthropogenic landscape characteristics. RESULTS: Females used smaller home ranges in areas with greater forage and woody cover and more evenly distributed habitat types. Females used larger home ranges with increasing croplands and human development in most study units but used smaller home ranges relative to these features within the unit with the lowest human presence. Migration between distinct summer and winter home ranges was rare (n = 18 females) and mostly involved relatively short distances (3–14 km). Interestingly, one female migrated approximately 100 km to establish a winter range in Wyoming before migrating back to her summer range in Nebraska. Migration occurred most frequently by females in the unit with the lowest proportion of croplands, whereas no females migrated in the unit with the most croplands, suggesting that abundant croplands may promote residency. CONCLUSIONS: Remaining natural habitat providing forage and cover is important to mule deer at the eastern periphery of their range in agriculturally modified landscapes. Agriculture provides costs and benefits to mule deer as it fragments the landscape resulting in larger home ranges, while also serving as a supplementary food source that likely contributed to the superior nutritional condition of mule deer in southwest Nebraska. Our work establishes the basic spatial ecology of mule deer in Nebraska and highlights the context specific nature of responses by ungulates to human landscape modification.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9dc37bf7-8264-44a8-8b81-caf0a27e993f', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Economic and Sustainability Impacts of Yield and Composition Variation in Bioenergy Crops: Switchgrass (Panicum virgatum L.)', 'Happs RM, Hanes RJ, Bartling AW, Field JL, Harman-Ware AE, Clark RJ, Pendergast TH 4th, Devos KM', 2024, 'ACS sustainable chemistry & engineering', '10.1021/acssuschemeng.3c05770', 'https://doi.org/10.1021/acssuschemeng.3c05770', 'https://europepmc.org/articles/PMC10848292?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'Economically viable production of biobased products and fuels requires high-yielding, high-quality, sustainable process-advantaged crops, developed using bioengineering or advanced breeding approaches. Understanding which crop phenotypic traits have the largest impact on biofuel economics and sustainability outcomes is important for the targeted feedstock crop development. Here, we evaluated biomass yield and cell-wall composition traits across a large natural variant population of switchgrass (Panicum virgatum L.) grown across three common garden sites. Samples from 331 switchgrass genotypes were collected and analyzed for carbohydrate and lignin components. Considering plant survival and biomass after multiple years of growth, we found that 84 of the genotypes analyzed may be suited for commercial production in the southeastern U.S. These genotypes show a range of growth and compositional traits across the population that are apparently independent of each other. We used these data to conduct techno-economic analyses and life cycle assessments evaluating the performance of each switchgrass genotype under a standard cellulosic ethanol process model with pretreatment, added enzymes, and fermentation. We find that switchgrass yield per area is the largest economic driver of the minimum fuel selling price (MSFP), ethanol yield per hectare, global warming potential (GWP), and cumulative energy demand (CED). At any yield, the carbohydrate content is significant but of secondary importance. Water use follows similar trends but has more variability due to an increased dependence on the biorefinery model. Analyses presented here highlight the primary importance of plant yield and the secondary importance of carbohydrate content when selecting a feedstock that is both economical and sustainable.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d4670f2b-5d94-48c4-b15e-77c981635287', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Effect of growth-promoting implants and revaccination timing on stress physiology and growth performance in male beef calves', 'Lasso-Ramirez S, Londono-Mendez M, Ramirez-Sepulveda V, Silva AEM, Macias Franco A, Lardner HA, Silva GM', 2026, 'Translational animal science', '10.1093/tas/txag098', 'https://doi.org/10.1093/tas/txag098', 'https://europepmc.org/articles/PMC13455977?pdf=render', NULL, NULL, 16, NULL, 'alberta', 4, 'cc by-nc', 'Hormonal growth-promoting implants are known to enhance growth performance in beef cattle, but their influence on vaccine response has not been studied extensively. Herein, we evaluated the growth performance and immunity of beef steers under different hormonal implant treatments and timing of booster vaccination. Fifty-nine crossbred beef calves were stratified by body weight (BW) and age (109 ± 18.9 kg and 70 ± 8 d of age) and randomly distributed into a completely randomized design with a 3 × 2 factorial arrangement to one of three implant treatments: (i) no implant (CON); (ii) short-term payout period implant (Synovex C; ST); or (iii) long-term payout period implant (Synovex One Grower; LT), and to one of the booster vaccination groups; at weaning (WV) or 7 days post-weaning (PWV). From implantation, and initial vaccination (d 0) until weaning (d 114), calves were raised with their dams in a single pasture. After weaning, calves were allocated to a single pen until d 63 post-weaning (d 177). Body weight was recorded, and blood samples were collected to analyze insulin-like growth factor, cortisol, β-hydroxybutyric acid, non-esterified fatty acids, leptin, serum antibody titers, and complete blood cell count. Peripheral blood lymphocyte concentration was greater in CON compared with ST and LT (P P = 0.01) in ST compared to LT, while CON was intermediate. A treatment × timing of booster vaccination (P P = 0.01) was observed for plasma cortisol with smaller concentration in WV compared with PWV at booster vaccination and d 28 post-booster vaccination. No main effects of treatments or treatment interactions were observed for serum antibody titers (P > 0.20). Implant treatment did not affect weaning weights; however, calves implanted with LT were the heaviest on d 142 (P = 0.03) and tended to have greater final body weights at the end of the study (P = 0.07). In summary, implant strategy and booster vaccination timing affected metabolic and immune parameters in beef calves but did not influence serum antibody titers. Growth performance was not affected at weaning; however, long-term-implanted calves were heavier post-weaning and tended to have greater final BW, indicating improved growth without compromising antibody-mediated immune responses.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e6f99046-3227-4af9-b76c-ad2993c22365', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Effects of agronomic factors on yield and quality of whole corn plants and the impact of feeding high concentrations of corn silage in diets containing distillers grains to finishing cattle', 'Burken DB, Nuttelman BL, Gramkow JL, McGee AL, Sudbeck KM, Gardine SE, Hoegemeyer TC, Klopfenstein TJ', 2017, 'Translational animal science', '10.2527/tas2017.0045', 'https://doi.org/10.2527/tas2017.0045', 'https://europepmc.org/articles/PMC7205347?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'Corn plants were sampled over 2 consecutive years to assess the effects of corn hybrid maturity class, plant population, and harvest time on whole corn plant quality and yield in Nebraska. A finishing experiment evaluated the substitution of corn with corn silage in diets with corn modified distillers grains with solubles (MDGS). The first 2 harvest dates were at the mid- and late-silage harvest times whereas the final harvest was at the grain harvest stage of plant maturity. Whole plant yields increased as harvest time progressed (yr 1 quadratic P P P ≤ 0.01), with the steers on the 15% corn silage treatment being 1.5%, 5.0%, and 7.7% more efficient than steers on treatments containing 30, 45, and 55% corn silage, respectively. Calculated dietary NEm and NEg decreased linearly as corn silage inclusion increased indicating that net energy values were greater for corn grain than for corn silage. In addition, dressing percentage decreased linearly (P P P < 0.04) than when 45% silage was fed with just grain implying a greater energy value for MDGS than for corn grain. Substituting corn silage for corn grain in finishing diets decreased ADG and G:F which would increase days to finish to an equal carcass weight; however, in this experiment, increasing corn silage levels with MDGS present reduced carcass fat thickness without significantly decreasing marbling score.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ca7ae3f7-62b6-4513-9d83-a8f70aa61b09', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Enhancing consistency in arbuscular mycorrhizal trait-based research to improve predictions of function', 'Antunes PM, Stürmer SL, Bever JD, Chagnon PL, Chaudhary VB, Deveautour C, Fahey C, Kokkoris V', 2025, 'Mycorrhiza', '10.1007/s00572-025-01187-7', 'https://doi.org/10.1007/s00572-025-01187-7', 'https://europepmc.org/articles/PMC11865136?pdf=render', NULL, NULL, 25, NULL, 'canada', 3, 'cc by-nc-nd', 'Arbuscular mycorrhizal (AM) fungi (phylum Glomeromycota) are obligate symbionts with plants influencing plant health, soil a(biotic) processes, and ecosystem functioning. Despite advancements in molecular techniques, understanding the role of AM fungal communities on a(biotic) processes based on AM fungal taxonomy remains challenging. This review advocates for a standardized trait-based framework to elucidate the life-history traits of AM fungi, focusing on their roles in three dimensions: host plants, soil, and AM fungal ecology. We define morphological, physiological, and genetic key traits, explore their functional roles and propose methodologies for their consistent measurement, enabling cross-study comparisons towards improved predictability of ecological function. We aim for this review to lay the groundwork for establishing a baseline of AM fungal trait responses under varying environmental conditions. Furthermore, we emphasize the need to include underrepresented taxa in research and utilize advances in machine learning and microphotography for data standardization.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cf06ba90-f472-4a38-a056-0b6d513ebb53', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Evaluation of the effects of wood-sourced biochar as a feedlot pen surface amendment on manure nutrient capture', 'Sperber JL, Erickson GE, Watson AK', 2022, 'Translational animal science', '10.1093/tas/txac127', 'https://doi.org/10.1093/tas/txac127', 'https://europepmc.org/articles/PMC9558872?pdf=render', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc by', 'Feedstuffs utilized in U.S. feedlot finishing rations incorporate high concentrations of N and P, with less than 15% of fed N and P retained by the animal. The remaining N and P are excreted in the manure, where the opportunity for manure N loss via ammonia (NH3) volatilization from the feedlot pen surface is a risk to the environment and lowers the value of manure as a fertilizer. Two nutrient mass balance experiments were conducted during the winter and summer seasons to evaluate the effects of spreading unprocessed Eastern red cedar biochar onto the feedlot pen surface on manure nutrient capture and cattle performance. A 186-d feedlot finishing experiment was conducted from December to June (WINTER) and a subsequent 153-d finishing experiment was conducted from June to November (SUMMER). The WINTER experiment evaluated three treatments (5 pens per treatment; 10 steers per pen), including biochar spread on pen surface during the feeding period (1.40 kg biochar/m2; 17.6 m2/steer soil surface of the pen), hydrated lime spread on pen surface at end of feeding period (1.75 kg/m2) and control (no treatment applied). The SUMMER experiment evaluated biochar treatment (1.40 kg biochar/m2; 5 pens per treatment; 8 steers per pen; and 22 m2/steer soil surface of the pen) against control. There were no differences in N and P intake, retention, or excretion (P ≥ 0.38) between WINTER treatments. Steer performance (P ≥ 0.10) and carcass characteristics (P ≥ 0.50) were not impacted by pen treatment in WINTER. Nitrogen and P intake and excretion (P ≥ 0.35) were not different between treatments in SUMMER and retention of N and P was significantly greater for the biochar treatment (P ≤0.04) due to greater ADG (P = 0.05). There was no difference in DMI (P = 0.48) in SUMMER, steers on biochar pen treatment had heavier HCW (P = 0.05) and greater ADG, resulting in a tendency for greater feed efficiency (P = 0.08). In both experiments, biochar addition to the pen surface tended (P = 0.07) to increase manure N as a percent of manure DM, but this increase in N concentration did not impact kg of N removed from the feedlot pens (P ≥ 0.15) or N losses (P ≥ 0.68). The addition of red cedar biochar to the feedlot pen surface did not increase manure nutrient capture of N or P and did not reduce N losses associated with soil-based feedlot pens.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c7443644-2565-45f0-b38d-e140dbed004f', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Evaluation of the influence of soil salinity on the yield of barley and alfalfa, 1979', 'Government of Alberta', 1979, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluation-of-the-influence-of-soil-salinity-on-the-yield-of-barley-and-alfalfa-1979', 'https://open.alberta.ca/dataset/36a39cdc-f1ca-43a6-a99e-5abd9f7e67c6/resource/94be1ee7-dae9-486a-b448-1bb46f0f13e0/download/0163010342448-evaluation-influence-soil-salinity-yield-barley-alfalfa-1979.pdf', NULL, NULL, 16, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Saline soil is a common issue in Southern Alberta, affecting irrigated farmland and crop productivity. Understanding soil salinity and its impact on crops is essential for effective land use. To assess this, irrigation researchers in Brooks, Alberta, conducted a field salinity survey on barley, a salt-tolerant crop, to measure salinity''s effect on yield.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35defc66-e5c5-46e3-bcd8-95ab64fcbb25', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Exploring management and environment effects on edge-of-field phosphorus losses with linear mixed models', 'Kruger KM, Thompson AM, Li Q, Radatz AM, Cooley ET, Stuntebeck TD, Winslow CJ, Oldfield EE', 2025, 'Journal of environmental quality', '10.1002/jeq2.20662', 'https://doi.org/10.1002/jeq2.20662', 'https://europepmc.org/articles/PMC11893287?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by', 'Evaluating how weather, farm management, and soil conditions impact phosphorus (P) loss from agricultural sites is essential for improving our waterways in agricultural watersheds. In this study, rainfall characteristics, manure application timing, tillage, surface condition, and soil test phosphorus (STP) were analyzed to determine their effects on total phosphorus (TP) and dissolved phosphorus (DP) loss using 125 site-years of runoff data collected by the University of Wisconsin Discovery Farms and Discovery Farms Minnesota. Three linear mixed models (LMMs) were then used to evaluate the influence of those factors on TP and DP losses: (1) a model that included all runoff events, (2) manured sites only, and (3) precipitation events only. Results show that the timing of manure application relative to the timing of a runoff event only had a marginal association with P loads and concentrations, although the majority of the runoff events were collected after 10 days of manure application. Tillage was as influential factor, with greater DP loads and concentrations associated with no-till, especially during frozen conditions. Fields in this study had high STP values, but the model results only showed positive associations between DP load and DP flow-weighted mean concentration (FWMC) loss at the 0- to 15-cm depth. The precipitation event LMM (which included precipitation characteristics) was the model that resulted in the largest R2 value. While the predictive capacity of the LMMs was low, they did illuminate the relative importance of management and environmental variables on P loss, and can be used to guide future research on P loss in this region.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ea45201-58d9-4b9e-9053-42bb07e6bf05', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Flood irrigation management of seed alfalfa', 'Government of Alberta', 1984, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/1984-research-report-flood-irrigation-management-of-seed-alfalfa', 'https://open.alberta.ca/dataset/46680c3c-4ab9-4dc7-8934-307f5d59eb9e/resource/15f5eec2-9f6b-44e2-8f81-ff17d4bb26e4/download/0163010364798-1984-research-report-flood-irrigation-management-of-seed-alfalfa.pdf', NULL, NULL, 10, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This research investigates the impact of different flood irrigation regimes on the consumptive use and yield of seed alfalfa in southern Alberta. It details an experiment conducted on clay loam soil, comparing various irrigation timings such as no irrigation, early flood, early plus midseason flood, early long flood, and midseason flood. The report analyzes soil properties, water holding capacity, and the effects of these treatments on seed and straw yields. Findings indicate that the amount and timing of water supplied are crucial for optimal alfalfa seed production, with a single midseason irrigation proving unsatisfactory.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('84792d66-7efa-4bcb-92d4-38e6868d1afb', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Forage growth and nutrient cycle of aspen forest communities in Alberta''s lower foothills subregion', 'Government of Alberta', 2004, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/forage-growth-and-nutrient-cycle-of-aspen-forest-communities-in-albertas-lower-foothills-subregion', 'https://open.alberta.ca/dataset/d60667ab-4b7b-4eca-9590-4a9cf6c4e3a3/resource/6ecbaac6-8aac-4871-935b-453744a8de80/download/srd-forage-growth-and-nutrient-cycle-of-aspen-forest-communities-in-alberta-lower-foothills-subr.pdf', NULL, NULL, 34, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'To enhance our knowledge about the effects of continuous and rotational grazing on forage productivity in deciduous communities, a clipping trial was established at two sites near Edson. The specific objectives included: to determine the forage growth and nutrient cycle of grasses, forbs and shrubs in an Aspen/Rose/Tall forb and an Aspen/Rose/Clover community type; to correlate growth with precipitation and air temperature; and to determine the effect of continuous versus rotational grazing on the forage and nutrient productivity of grasses, forbs and shrubs in the two community types.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7432462e-8e35-40bc-a996-7fa7b330f276', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Genome-Wide Association and Genomic Prediction of Alfalfa (Medicago sativa L.) Biomass Yield Under Drought Stress', 'Medina CA, Hansen J, Crawford J, Viands D, Sapkota M, Xu Z, Peel MD, Yu LX', 2025, 'International journal of molecular sciences', '10.3390/ijms26020608', 'https://doi.org/10.3390/ijms26020608', 'https://europepmc.org/articles/PMC11765341?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'Developing drought-resistant alfalfa (Medicago sativa L.) that maintains high biomass yield is a key breeding goal to enhance productivity in water-limited areas. In this study, 424 alfalfa breeding families were analyzed to identify molecular markers associated with biomass yield under drought stress and to predict high-merit plants. Biomass yield was measured from 18 harvests from 2020 to 2023 in a field trial with deficit irrigation. A total of 131 significant markers were associated with biomass yield, with 80 markers specifically linked to yield under drought stress; among these, 19 markers were associated with multiple harvests. Finally, genomic best linear unbiased prediction (GBLUP) was employed to obtain predictive accuracies (PAs) and genomic estimated breeding values (GEBVs). Removing low-informative SNPs [SNPs with p-values > 0.05 from the additive Genome-Wide Association (GWAS) model] for GBLUP increased PA by 47.3%. The high number of markers associated with yield under drought stress and the highest PA (0.9) represent a significant achievement in improving yield under drought stress in alfalfa.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f872e6f7-fecd-414a-8e03-28770a238d8d', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Greenhouse gas emissions in US beef production can be reduced by up to 30% with the adoption of selected mitigation measures', 'Pelton REO, Kazanski CE, Keerthi S, Racette KA, Gennet S, Springer N, Yacobson E, Wironen M', 2024, 'Nature food', '10.1038/s43016-024-01031-9', 'https://doi.org/10.1038/s43016-024-01031-9', 'https://europepmc.org/articles/PMC11420059?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'Greenhouse gas (GHG) emissions from beef production in the United States are unevenly distributed across the supply chain and production regions, complicating where and how to reduce emissions most effectively. Using spatially explicit life cycle assessment methods, we quantify the baseline GHG emissions and mitigation opportunities of 42 practices spanning the supply chain from crop and livestock production to processing. We find that the potential to reduce GHGs across the beef sector ranges up to 30% (20 million tonnes CO2e reduced and 58 million tonnes CO2 sequestered each year relative to the baseline) under ubiquitous adoption assumptions, largely driven by opportunities in the grazing stage. Opportunities to reduce GHGs in the feed, grazing and feedlot stages vary across regions, yet large-scale adoption across the entire beef supply chain is important. These findings reveal promising locations and practices to invest in to advance mitigation goals and an upper-end theoretical potential for mitigation in the beef industry.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ac52d3c9-b8ec-4a97-8b24-5594998dcedd', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Guide to requirements for forage drying facilities', 'Government of Alberta', 2007, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/guide-to-requirements-for-forage-drying-facilities', 'https://open.alberta.ca/dataset/b7258845-475d-4bd9-8ae7-dfbbced736f7/resource/c051f8b3-6cb4-4758-8e8e-3cd0e053cab4/download/aenv-guide-to-requirements-for-forage-drying-facilities-7817.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Forage drying facilities are regulated through a registration under the Environmental Protection and Enhancement Act rather than by approval. Individuals receiving a registration must follow conditions stipulated in the Code of Practice for Forage Drying Facilities. Alberta Environment has developed this guidance document to help applicants obtain a registration and to help them understand the Code of Practice.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a4d79b47-80fd-4a92-a0e2-3fe9412bd41e', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Hay and forage moisture meters', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-700', 'https://open.alberta.ca/dataset/92634408-2710-4fa8-8686-fe73d6c8a380/resource/b3f0dd57-8646-417c-84a3-fb11daa14c04/download/700-afmrc.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Presents the results of an evaluation of several hay and forage moisture meters. Includes a general description of the moisture meters, outlines the scope of the evaluation and discusses results of the testing. Also provides a brief summary and conclusions, lists recommendations made to the manufacturer to improve the product and presents the manufacturer’s response to the recommendations.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('46ea2d17-b19a-4aab-b40c-45b6cb61a003', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Impacts of Phosphogypsum, Soluble Fertilizer and Lime Amendment of Acid Soils on the Bioavailability of Phosphorus and Sulphur under Lucerne (Medicago sativa)', 'Moussa Bouray, Jim Moir, Leo Condron, Niklas Lehto', 2020, 'Plants', '10.3390/plants9070883', 'https://doi.org/10.3390/plants9070883', 'https://www.mdpi.com/2223-7747/9/7/883', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Legumes play critical dual roles in grazed grassland ecosystems; providing nitrogen inputs and high-quality feed for grazing livestock. However, many species fail to persist in acidic, low fertility soils. A glasshouse study was conducted to investigate the response of lucerne (Medicago sativa) to phosphogypsum (PG), lime and soluble P + S fertilizer (PS) application to two soils. Phosphorus and sulphur were applied through either PG (0, 1, 3 and 9 t ha−1) or P + S fertilizer at equivalent rates to PG. Both PG and PS were applied with or without lime, which was applied at 2 t ha−1. Yield and nutrient uptake of the lucerne was measured, while the soil was analyzed for pH, Olsen P and exchangeable aluminum. Yield responses were significantly different between the two soils. Maximum yields and P and S uptakes were obtained under PG 9 t ha−1 combined with lime. Exchangeable Al decreased in both soils under 1 ha−1 of PG compared with the control. At the highest rate, Olsen P increased by 8 and 6 mg kg−1 for PG and by 6 and 11 mg kg−1 for PS compared with the control for Glenmore and Molesworth soils respectively. Phosphogypsum showed positive effects on P and S bioavailability.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('211bd9dc-42f7-4fba-91b8-de1fbcf609f3', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Improving late season forage regrowth in spring and winter cereal intercrops', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/improving-late-season-forage-regrowth-in-spring-and-winter-cereal-intercrops', 'https://open.alberta.ca/dataset/0742becf-409d-448b-8456-086f56a23cf7/resource/a5198b56-064f-490c-a93e-364622ea0e1f/download/0163010008437-improving-late-season-forage-regrowth-in-spring-and-winter-cereal-intercrops.pdf', NULL, NULL, 118, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study evaluated regrowth and survival of winter cereals in spring-planted mixtures with barley for forage in Lacombe, Alberta from 1990 to 1992. Winter wheat, triticale, and rye were grown as monocrops and in binary mixtures, with initial cuts at heading or up to six weeks later. Regrowth declined with later cuts, more than with species differences. Triticale and rye had greater shoot size, while wheat showed higher photosynthetic efficiency. Triticale produced more stable three-week regrowth yields, though not consistently highest. Cutting within two weeks after barley heading was optimal for yield. Mixtures had lower water-soluble carbohydrate levels than monocrops.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5de7394c-4851-4e36-9cba-5a346e996774', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Integrated control of snow mold disease in forage grass cultivars', 'Government of Alberta', 1999, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/integrated-control-of-snow-mold-disease-in-forage-grass-cultivars', 'https://open.alberta.ca/dataset/5854bd0c-9c3e-4d9c-bcee-ccf8ffb27329/resource/46b42242-efb8-46ec-b7e5-7440d833cf4c/download/0163010176879-integrated-control-of-snow-mold-disease-in-forage-grass-cultivars.pdf', NULL, NULL, 80, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported the results of a research project that examined integrated control of snow mould disease in forage grass cultivars in Alberta. It evaluated the effects of snow mould caused by the Low Temperature Basidiomycete (LTB), seeding date, plant age, and cultivar selection on winter survival and productivity of several forage grass species under field and controlled environment conditions. It compared the resistance of common forage grasses and cultivars and assessed how agronomic practices influenced susceptibility to winter injury and yield loss. The document presented experimental methods, results, and analysis to support improved forage management and cultivar selection in regions with prolonged snow cover. It also discussed implications for Alberta''s agriculture industry with respect to reducing winterkill and productivity losses.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9e62d4a-af1c-457f-961f-cb507a6401f2', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Invasive plants in Alberta. Forages and hay land', 'Government of Alberta', 2014, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/6740639', 'https://open.alberta.ca/dataset/3e125e2b-c63d-4e07-a2a4-65f7b1a28733/resource/372431c0-dde3-4e59-9cf0-451a53034b2b/download/6740639-2014-invasive-plants-alberta-forages-hay-land-640-15-2014-02.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Land owners and occupiers are responsible for controlling noxious weeds and destroying prohibited noxious weeds under the Alberta Weed Control Act. Listed plants in the Act cause problems for the environment, health or economy. Know your responsibilities under the Act. Regardless of where plants are located, prevention is always the most effective approach in dealing with invasive plants.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3af25afa-53dd-4804-bf12-5538a88d4838', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Irrigation of alfalfa grown for seed 1979', 'Government of Alberta', 1979, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/irrigation-of-alfalfa-grown-for-seed-1979', 'https://open.alberta.ca/dataset/6247f4db-0f8a-45b1-af30-d5182aaca9d5/resource/31fbcaad-d8ee-480e-9a7f-975d4a06b26f/download/0163010342992-irrigation-of-alfalfa-grown-for-seed-1979.pdf', NULL, NULL, 28, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This guide provides comprehensive information on irrigating alfalfa grown for seed in Southern Alberta, focusing on methods that maximize seed yield. It outlines the specific water requirements of alfalfa at different growth stages and details effective irrigation scheduling practices. The resource also discusses various irrigation systems suitable for alfalfa seed production, including their advantages and limitations. Additionally, it offers practical advice on managing water resources to optimize crop health and productivity.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bfe3f9f1-6b0c-4cc1-815a-ec98c75a2ede', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Is swine manure injection into alfalfa stands a good idea?', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-751', 'https://open.alberta.ca/dataset/3c720c2e-01c8-4941-92ec-f25c19c42f9a/resource/7516de01-8db6-4b93-841a-9b88948f1d83/download/751-afmrc.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The hog industry is growing on the Canadian prairies as demand for pork increases worldwide. As the industry grows, the application of hog manure is not only a logistical problem that must be addressed, but also an opportunity for producers to utilize a valuable fertilizer resource. Research was undertaken on the injection of swine manure into alfalfa produced for dehydration (pelleting) as both a research and demonstration initiative. It was found that shallow injected swine manure can increase the forage yield of alfalfa if the soil is nutrient-deficient. Injection of swine manure is particularly effective when phosphorus, potassium, and sulfur are deficient. Yield increases up to 45 per cent occurred on the test plots and forage protein levels also increased. In contrast, yield decreases can occur due to crop damage by injection when soil nutrient levels are adequate. Farmers who have liquid manure to utilize should soil test their alfalfa fields prior to low disturbance swine manure injection to ensure that the manure application will be beneficial.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('695ed315-2de2-4f50-8168-23e436df9213', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Little millet genome reveals evolutionary insights into tetraploid structure and genetic basis of micronutrient density', 'Gali KK, Koh KC, Satyavathi TC, Nanaiah GK, Palanna KB, Kirzinger MW, Nanjundappa S, Perumal S', 2025, 'Nature communications', '10.1038/s41467-025-66716-6', 'https://doi.org/10.1038/s41467-025-66716-6', 'https://europepmc.org/articles/PMC12769566?pdf=render', NULL, NULL, 20, NULL, 'prairies', 4, 'cc by', 'Little millet is a hardy and nutrient-rich cereal which improves food and nutritional security in marginal environments. Despite its importance, genomic resources for this orphan crop have been limited. Here, we report a high quality, chromosome-scale genome assembly of little millet comprising 18 chromosomes and 59,045 genes. Eleven chromosomes are assembled from telomere to telomere, revealing an 850 Mb tetraploid genome that closely resembles broomcorn millet. Comparative analyses indicate early stages of diploidization, characterized by gene loss and subgenome-specific expression biases that vary across genes and tissues. Resequencing of 300 accessions uncovers extensive genetic diversity, including single-nucleotide polymorphism and structural variants. Genome-wide association studies identify genetic loci linked to grain micronutrient traits, including several associated with high iron content. These genomic and phenotypic resources provide a foundation for molecular breeding and marker-assisted selection, enabling the improvement of little millet as a climate-resilient crop to support global food and nutritional security.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c340fd1b-0744-41e0-a027-5f2612767559', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Long-Term Noninvasive Genetic Monitoring Guides Recovery of the Endangered Columbia Basin Pygmy Rabbits (Brachylagus idahoensis)', 'Nerkowski SA, Hohenlohe PA, Rachlow JL, Warheit KI, Gallie JA, Waits LP', 2025, 'Genes', '10.3390/genes16080956', 'https://doi.org/10.3390/genes16080956', 'https://europepmc.org/articles/PMC12386180?pdf=render', NULL, NULL, 36, NULL, 'northern_plains', 3, 'cc by', 'Background/Objectives: Loss and fragmentation of habitat from agricultural conversion led to the near extirpation of the pygmy rabbit (Brachylagus idahoensis Merriam, 1891) population in the Columbia Basin (CB) of Washington, USA. Recovery efforts began in 2002 and included captive breeding, translocations from other regions for genetic rescue, and reintroduction into native habitat in three sites: Sagebrush Flat (SBF), Beezley Hills (BH), and Chester Butte (CHB). Methods: We used noninvasive and invasive genetic sampling to evaluate demographic and population genetic parameters on three translocated populations of pygmy rabbits over eight years (2011-2020). For each population, our goal was to use fecal DNA sampling and 19 microsatellite loci to monitor spatial distribution, apparent survival rates, genetic diversity, reproduction, effective population size, and the persistence of CB ancestry. Over the course of this study, 1978 rabbits were reintroduced as part of a cooperative conservation effort between state and federal agencies. Results: Through winter and summer monitoring surveys, we detected 168 released rabbits and 420 wild-born rabbits in SBF, 13 released rabbits and 2 wild-born in BH, and 16 released rabbits in CHB. Observed heterozygosity (Ho) values ranged from 0.62-0.84 (SBF), 0.59-0.80 (BH), and 0.73-0.77 (CHB). Allelic richness (AR) ranged from 4.67-5.35 (SBF), 3.71-5.41 (BH), and 3.69-4.65 (CHB). Effective population (Ne) within SBF varied from 12.3 (2012) to 44.3 (2017). CB ancestry persisted in all three wild populations, ranging from 15 to 27%. CB ancestry persisted in 99% of wild-born juveniles identified in SBF. Apparent survival of juvenile rabbits differed across years (1-39%) and was positively associated with release date, release weight, and genetic diversity. Survival of adults (0-43%) was positively influenced by release day, with some evidence that genetic diversity also positively influenced adult apparent survival. Conclusions: Noninvasive genetic sampling has proven to be an effective and efficient tool in monitoring this reintroduced population, assessing both demographic and genetic factors. This data has helped managers address the goals of the Columbia Basin recovery program of establishing multiple sustainable wild populations within the sagebrush steppe habitat of Washington.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2c44b381-0e08-4e0e-bbf7-94f8819a265b', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Low temperature nitrogen fixation for alfalfa', 'Government of Alberta', 1990, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/low-temperature-nitrogen-fixation-for-alfalfa', 'https://open.alberta.ca/dataset/b464c53f-da41-47b0-9d1b-aaf47fbb8b93/resource/c57caa0e-8801-4ac7-9e87-89a14984e455/download/0163010335632-low-temperature-nitrogen-fixation-for-alfalfa.pdf', NULL, NULL, 48, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Researchers conducted laboratory, growth chamber, and field experiments to identify Rhizobium meliloti strains capable of nodulating alfalfa and fixing nitrogen at temperatures of 12 degrees Celsius and below. They observed significant variation among strains in their ability to grow and form nodules at 10 degrees Celsius, and found no clear correlation between culture doubling time and nodulation performance. Five selected strains increased the shoot dry weight of alfalfa at root temperatures between 9 and 12 degrees Celsius compared to uninoculated controls. One strain, NRG-34, consistently formed more and heavier nodules and achieved greater nodule occupancy than the commercial strain NRG-185. These results suggest that selecting strains under low-temperature conditions can improve inoculant performance, although further research is needed to evaluate their adaptability across diverse environments.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b26aba7e-ba7a-4d35-9193-14a3aab4116e', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Match forage supplies to livestock needs calculator', 'Government of Alberta', 2009, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/match-forage-supplies-to-livestock-needs-calculator', 'https://open.alberta.ca/dataset/cf5e5b29-cb8d-4982-80ce-75eb2af4b15e/resource/95e98517-c423-4842-98f6-3cc5d7cfeea9/download/2009-match-forage-supplies-livestock-need-calculator-2009-07-15.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Technical bulletins research specific areas of interest to provide a better understanding of cropping issues that may affect or influence Alberta producers. They also provide Alberta producers with an additional tool to evaluate business performance along with production, management, and technology options.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7c0ae5a0-67c4-4d2a-afab-faf59a70570b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Insecticidal control of late-season plant bug (Hemiptera: Miridae) infestations in Manitoba has no effect on alfalfa seed quantity and quality', 'Ayman Mostafa, Neil J. Holliday', 2008, 'Canadian Journal of Plant Science', '10.4141/cjps07181', 'https://doi.org/10.4141/cjps07181', 'https://cdnsciencepub.com/doi/pdf/10.4141/CJPS07181', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('de823483-d07d-4dea-8567-5baaeb89a0d3', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Merging rigor and relevance in grazingland research: a comprehensive social-ecological monitoring approach', 'Stanley PL, Kuhl AS, Maciel ICF, Cotrufo MF, Goodwin DJ, Hodbod J, Anderson MC, Scasta JD', 2026, 'Carbon balance and management', '10.1186/s13021-026-00431-7', 'https://doi.org/10.1186/s13021-026-00431-7', 'https://europepmc.org/articles/PMC13094286?pdf=render', NULL, NULL, 30, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'BACKGROUND: Despite decades of study, current research on grazing management’s impacts on ecosystem health and its socioeconomic drivers remains too limited in scope and scale to enable adaptive, evidence-based decision making by producers. There is a pressing need for interdisciplinary research that collects ecosystem data at broader spatial and temporal scales while incorporating working farms and ranches. Such efforts are critical for informing grazing decisions and understanding grazinglands’ potential to deliver ecosystem services, including climate mitigation, water cycling, resilience, and rural livelihoods. RESULTS: The Metrics, Management, and Monitoring (3M) project addresses this need through a novel social-ecological framework that integrates biophysical, socioeconomic, and management data across U.S. grazinglands. The project combines controlled experiments at four intensively monitored “hubs” with data from 59 producer-managed farms and ranches. Its core objectives are to: (1) assess the social-ecological health of grazinglands across diverse ecoregions, (2) refine monitoring approaches to improve scalability and accuracy, and (3) integrate producer-led data to balance experimental rigor with real-world relevance. Over 50 scientists collaborate on 3M to evaluate how grazing strategies affect soil carbon, water dynamics, CO₂ fluxes, plant communities, productivity, social wellbeing, and producer economics. CONCLUSIONS: These insights support the development of ecosystem models and decision-support tools to help producers make evidence-based choices. Beyond data generation, 3M offers a scalable research model that bridges ecological and social sciences to support adaptive, informed grazing management. This integrated framework provides a transferable template for studying any working landscape where human and ecological systems are deeply interconnected.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1fdd7625-a5bf-4e86-a727-e03ffb1267d8', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Metabarcoding Reveals Cover Crop Functional Type as Primary Driver of Soil Nematode Community Composition in a Carrot Production System', 'Naqvi SAH, Akanwari J, Sultana T', 2026, 'Biology', '10.3390/biology15151226', 'https://doi.org/10.3390/biology15151226', 'https://europepmc.org/articles/PMC13464887?pdf=render', NULL, NULL, 22, NULL, 'canada', 3, 'cc by', 'The influence of cover crop functional type on soil nematode feeding group structure, food web condition, and crop productivity in horticultural systems remains poorly understood. Using DNA metabarcoding targeting the V6-V8 region of the 18S rRNA gene, we characterized nematode community responses in soil samples collected from a carrot (Daucus carota L.) production system in Ontario, Canada. We evaluated the effects of alfalfa (Medicago sativa L.), sorghum (Sorghum bicolor), and their mixture under two nitrogen regimes. Bacterivores dominated all treatments (60.8%), whereby sampling time and cover crop identity jointly explained 33.5% of community variance. Nematode community ecological indices revealed highly significant temporal shifts in food web condition, including seasonal decline in maturity and structure indices and a rise in the channel index, indicating food web restructuring regardless of cover crop type. Individual cover-crop exhibited distinct trade-offs between nematode suppression and crop productivity, while sorghum drove a pronounced bacterivore-to-fungivore transition. The alfalfa-sorghum (legume-non-legume) mixture emerged as the most agronomically balanced treatment, uniquely combining plant-parasitic nematode suppression with the highest individual carrot weight and the most balanced soil food web structure. This study provides important insights into how cover crop functional type influences soil nematode communities and crop performance in carrot production systems. Future studies repeating this experiment across multiple locations and growing seasons would help determine the consistency of these responses under a broader range of environmental conditions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ed0ab8d-786f-458c-a49e-79b172ce588d', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Methane emissions in beef cattle: A review of measurements and mitigation strategies', 'Taiwo E, Silva GM, Manafiazar G, Fitzsimmons C, Li C', 2026, 'Veterinary and animal science', '10.1016/j.vas.2026.100801', 'https://doi.org/10.1016/j.vas.2026.100801', 'https://europepmc.org/articles/PMC13524546?pdf=render', NULL, NULL, 19, NULL, 'alberta', 4, 'cc by', 'Methane emissions from beef cattle make a considerable contribution to global greenhouse gas (GHG) emissions, leading to environmental, economic, and production challenges. This review presents the current understanding on enteric methane emissions in cattle, and evaluates the measurement techniques, bioindicators, and a range of management strategies to mitigate methane emissions, including dietary modifications, feed additives, vaccination, grazing strategies, and microbial manipulation, describing their respective benefits and limitations. The review also examines methane mitigation through genetic selection and breeding, including the applications of genome-wide association studies (GWAS) and genomic selection to identify and incorporate methane-reducing traits into the breeding programs. To facilitate genetic selection and breeding programs, more research is needed to link methane traits, gut microbes, and genetics to improve predictions of genetic merit of methane emissions on individual animals. While numerous mitigation strategies show promise, achieving lasting reductions in methane emissions requires an integrated approach that combines management practices with selective breeding and balances productivity, animal welfare, and both environmental and economic sustainability.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('afd5261a-5eb0-48f3-a4be-2f0c9017568e', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'New Holland 900 forage harvester', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-587', 'https://open.alberta.ca/dataset/a842329e-8c57-4c2e-8acb-4131623e7e2e/resource/da262ab8-cec5-49f8-8eca-dc1018720191/download/587-afmrc.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Presents the results of an evaluation of the New Holland 900 forage harvester. Includes a general description of the forage harvester, outlines the scope of the evaluation and discusses results of the testing. Also provides a brief summary and conclusions, lists recommendations made to the manufacturer to improve the product and presents the manufacturer’s response to the recommendations.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bc3313ba-c4a4-49c7-a27d-28892c1b7817', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'New methods of forage evaluation', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/new-methods-of-forage-evaluation', 'https://open.alberta.ca/dataset/9740d450-3ecd-4c32-a550-61c1f0097627/resource/6fbe5cf3-a72b-4ab2-957b-fd79cc6e7e3c/download/0163010303903-new-methods-of-forage-evaluation.pdf', NULL, NULL, 71, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study evaluated various analytical techniques to predict the chemical composition, digestibility, and energy value of forages fed to ruminants using four experiments. Thermogravimetric analysis (TGA) of hay samples showed strong correlations with crude protein and acid detergent fiber, and potential for predicting feed value. Spin lock cross polarization (SLCP) nuclear magnetic resonance (NMR) was used to assess carbohydrate rigidity, revealing that nonrigid carbohydrates were preferentially digested and that feed cellulose rigidity had limited value in predicting digestibility. Near infrared reflectance spectroscopy (NIRS) provided reliable predictions of intake and digestibility. Enzyme procedures using cellulase offered limited improvement in accuracy over existing methods. The study concluded that NIRS and TGA are valuable tools for predicting forage nutritive value, while cellulase enzyme digestion is unlikely to become a routine feed analysis method.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('558b07e7-ec96-47b2-94af-3f855e78ec5a', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Nutrient Utilization and Requirements in Sheep and Goats Raised Under Different Systems and Fed Low Nutritional Novel Feeds for Meat Production', 'Mahgoub O, Osman NEHIE, Lu CD', 2025, 'Animals : an open access journal from MDPI', '10.3390/ani15182658', 'https://doi.org/10.3390/ani15182658', 'https://europepmc.org/articles/PMC12466701?pdf=render', NULL, NULL, 24, NULL, 'canada', 3, 'cc by', 'Sheep and goats are essential in many parts of the world, providing meat, milk, and fiber while also aiding rural and low-income communities. The cost of feeding is a major factor in the overall expenses of animal production. Therefore, it is crucial to improve nutrient utilization and accurately assess nutrient needs. Sheep and goats in different parts of the world are raised under different systems influenced by variations in environmental conditions. In tropical areas, sheep and goats often consume low-quality diets that do not meet their production requirements. These substandard diets, which include high-fiber feeds like straw or hay, are commonly provided to small ruminants and can adversely impact their feed intake, digestion, and nutrient absorption. To address these shortcomings, these feeds are usually supplemented with high-energy and protein-rich ingredients. This is achieved by enhancing low-quality feeds and employing strategies such as enriched feed blocks. However, the feeding practices and utilization of sheep and goats are influenced by various factors, including climate, breed, and production system, all of which are critical to consider when assessing their feeding needs. For example, animals that are mobile, such as those in nomadic or grazing systems, expend considerable energy on movement, which requires supplementation. Additionally, an animal''s body size, shaped by genetics, affects chewing rate, rumen pH, and bacterial composition. Meat production factors may be improved with proper use of NFs in small ruminants. This review explores the dietary needs of sheep and goats in relation to different production factors.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('faaed3dd-e4e0-4c89-be5f-1095b7830863', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Optimizing Lucerne Productivity and Resource Efficiency in China’s Yellow River Irrigated Region: Synergistic Effects of Ridge-Film Mulching and Controlled-Release Nitrogen Fertilization', 'Minhua Yin, Yuanbo Jiang, Yi Ling, Yanlin Ma, Guangping Qi, Yanxia Kang, Yayu Wang, Qiang Lu', 2025, 'Agriculture', '10.3390/agriculture15080845', 'https://doi.org/10.3390/agriculture15080845', 'https://www.mdpi.com/2077-0472/15/8/845', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'To address low productivity and water constraints in lucerne fields of China’s Gansu Yellow River Irrigation Region, this study optimized lucerne (Medicago sativa L.) cultivation through synergistic planting nitrogen regimes. A two-year field trial (2021–2022) evaluated three systems: ridge-furrow with ordinary mulch (PM), ridge-furrow with biodegradable mulch (BM), and conventional flat planting (FP), under four controlled-release N rates (0, 80, 160, 240 kg ha−1). Multidimensional assessments included growth dynamics, dry matter yield, forage quality (crude protein [CP], acid/neutral detergent fiber [ADF/NDF], relative feed value [RFV]), and resource efficiency metrics (water use efficiency [WUE], irrigation WUE [IWUE], partial factor productivity of N [PFPN], agronomic N use efficiency [ANUE]). The results showed the following: (1) Compared with conventional flat planting, ridge planting with film mulching significantly promoted lucerne growth, with ordinary plastic film providing a stronger effect than biodegradable film. Plant height and stem diameter exhibited a quadratic response to elevated nitrogen (N) application rates under identical planting patterns, peaking at intermediate N levels before declining with further increases. (2) Ridge planting with both ordinary plastic film and biodegradable film combined with an appropriate N rate improved lucerne yield and quality. In particular, the PMN2 treatment reached the highest value of yield (14,600 kg ha−1), CP (19.19%) and RFV (124.18), and the lowest value of ADF (29.63%) and NDF (48.86%), and all of them were significantly better than the other treatments (p  BM > FP. With increasing N application rates, WUE, IWUE, and ANUE initially rose and then declined, peaking under N2, whereas PFPN showed a decreasing trend and reached its maximum under N1. Principal component analysis revealed that ridge planting with ordinary plastic film combined with 160 kg·ha−1 N (PMN2) optimized lucerne performance, achieving balanced improvements in yield, forage quality, and water–nitrogen use efficiency. This regimen is recommended as the optimal strategy for lucerne cultivation in the Gansu Yellow River Irrigation Region and analogous ecoregions.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ab010173-c16b-4e0a-b8de-a77bb81ff609', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Optimizing nitrogen and phosphorus application to improve soil organic carbon and alfalfa hay yield in alfalfa fields', 'Kongqin Wei, Junwei Zhao, Yanliang Sun, Ignacio F. López, Chunhui Ma, Qianbing Zhang', 2024, 'Frontiers in Plant Science', '10.3389/fpls.2023.1276580', 'https://doi.org/10.3389/fpls.2023.1276580', 'https://www.frontiersin.org/articles/10.3389/fpls.2023.1276580/full', NULL, NULL, 18, NULL, 'other', 1, 'open access (DOAJ)', 'Soil organic carbon (SOC) is the principal factor contributing to enhanced soil fertility and also functions as the major carbon sink within terrestrial ecosystems. Applying fertilizer is a crucial agricultural practice that enhances SOC and promotes crop yields. Nevertheless, the response of SOC, active organic carbon fraction and hay yield to nitrogen and phosphorus application is still unclear. The objective of this study was to investigate the impact of nitrogen-phosphorus interactions on SOC, active organic carbon fractions and hay yield in alfalfa fields. A two-factor randomized group design was employed in this study, with two nitrogen levels of 0 kg·ha-1 (N0) and 120 kg·ha-1 (N1) and four phosphorus levels of 0 kg·ha-1 (P0), 50 kg·ha-1 (P1), 100 kg·ha-1 (P2) and 150 kg·ha-1 (P3). The results showed that the nitrogen and phosphorus treatments increased SOC, easily oxidized organic carbon (EOC), dissolved organic carbon (DOC), particulate organic carbon (POC), microbial biomass carbon (MBC) and hay yield in alfalfa fields, and increased with the duration of fertilizer application, reaching a maximum under N1P2 or N1P3 treatments. The increases in SOC, EOC, DOC, POC, MBC content and hay yield in the 0–60 cm soil layer of the alfalfa field were 9.11%-21.85%, 1.07%-25.01%, 6.94%-22.03%, 10.36%-44.15%, 26.46%-62.61% and 5.51%-23.25% for the nitrogen and phosphorus treatments, respectively. The vertical distribution of SOC, EOC, DOC and POC contents under all nitrogen and phosphorus treatments was highest in the 0–20 cm soil layer and tended to decrease with increasing depth of the soil layer. The MBC content was highest in the 10–30 cm soil layer. DOC/SOC, MBC/SOC (excluding N0P1 treatment) and POC/SOC were all higher in the 0–40 cm soil layer of the alfalfa field compared to the N0P0 treatment, indicating that the nitrogen and phosphorus treatments effectively improved soil fertility, while EOC/SOC and DOC/SOC were both lower in the 40–60 cm soil layer than in the N0P0 treatment, indicating that the nitrogen and phosphorus treatments improved soil carbon sequestration potential. The soil layer between 0-30 cm exhibited the highest sensitivity index for MBC, whereas the soil layer between 30-60 cm had the highest sensitivity index for POC. This suggests that the indication for changes in SOC due to nitrogen and phosphorus treatment shifted from MBC to POC as the soil depth increased. Meanwhile, except the 20–30 cm layer of soil in the N0P1 treatment and the 20–50 cm layer in the N1P0 treatment, all fertilizers enhanced the soil Carbon management index (CMI) to varying degrees. Structural equation modeling shows that nitrogen and phosphorus indirectly affect SOC content by changing the content of the active organic carbon fraction, and that SOC is primarily impacted by POC and MBC. The comprehensive assessment indicated that the N1P2 treatment was the optimal fertilizer application pattern. In summary, the nitrogen and phosphorus treatments improved soil fertility in the 0–40 cm soil layer and soil carbon sequestration potential in the 40–60 cm soil layer of alfalfa fields. In agroecosystems, a recommended application rate of 120 kg·ha-1 for nitrogen and 100 kg·ha-1 for phosphorus is the most effective in increasing SOC content, soil carbon pool potential and alfalfa hay yield.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e01b316d-e39a-4840-9da8-5974c8e6503a', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Perennial forage establishment in Alberta', 'Government of Alberta', 2005, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3057493', 'https://open.alberta.ca/dataset/c0992bfe-b2c6-48f3-8fab-74e83196839c/resource/2046a7c2-2186-4c73-8719-99e09f61941d/download/2005-120-22-3.pdf', NULL, NULL, 14, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'The first step to a productive perennial forage stand is strong seedling establishment. Before the seeding equipment enters the field, several factors must be considered.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('69eac036-e7b8-4bd1-9897-7386d738b4f1', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Physical and chemical factors regulating forage intake and digestibility by ruminants', 'Government of Alberta', 1994, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/physical-and-chemical-factors-regulating-forage-intake-and-digestibility-by-ruminants', 'https://open.alberta.ca/dataset/741369d6-e47c-4f82-8c61-b127ce47254e/resource/134db800-bb63-4784-aed8-06f8af72d493/download/0163010087878-physical-chemical-factors-regulating-forage-intake-digestibility-ruminants.pdf', NULL, NULL, 88, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study found that neutral detergent fibre (NDF) and acid detergent fibre (ADF) contents were poor predictors of forage nutritive value. NDF explained 40 per cent of the variation in dry matter intake and ADF explained 30 per cent of the variation in dry matter digestibility across a range of forages. Researchers observed that forage particle shape, specifically circularity, accounted for 10 to 20 per cent of the variation in dry matter intake. Both the rate and extent of in sacco dry matter digestion correlated positively with intake and digestibility. A multiple regression using kinetic digestion parameters and NDF content explained 77 per cent of the variation in dry matter intake among forages.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8096768d-81c6-4cc7-a01e-0a533a18c003', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Processed forage export synopsis', 'Government of Alberta', 1990, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/processed-forage-export-synopsis', 'https://open.alberta.ca/dataset/5a0ce19e-a48c-4a29-b40e-ab09ae78be60/resource/2eb894be-e8eb-427f-aba7-ca92f4d69821/download/0163010273197-processed-forage-export-synopsis.pdf', NULL, NULL, 70, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report reviews Alberta''s processed forage industry, analyzing its economic importance, trade prospects in Asia, Europe, and North America, and key industry development issues. It examines trends in processed forage markets, factors influencing demand, and competition from other regions. The report also addresses production aspects, transportation issues, market access challenges, capital costs, and resources available from Alberta Agriculture. These findings aim to support decisions for enhancing the industry''s growth and market access.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1432d7de-356c-4cc9-8bfb-9c53ed12bcca', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'LAND USE LEGACY REGULATES MICROBIAL COMMUNITY STRUCTURE AND FUNCTION IN TRANSPLANTED CHERNOZEMS', 'Panchali Katulanda', 2018, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/8347', 'https://harvest.usask.ca/bitstreams/28004855-d0dc-45f5-bd4c-c14b6ae7977a/download', NULL, NULL, 229, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('31d0da47-007d-4c39-a261-69e4061c200b', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Production of Rhizobium meliloti inoculants for alfalfa and Rhizobium trifolii inoculants for clover by process-controlled fermentations', 'Government of Alberta', 1988, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/production-rhizobium-meliloti-inoculants-for-alfalfa-and-rhizobium-trifolii-inoculants-for-clover', 'https://open.alberta.ca/dataset/08e77f02-a684-451a-8973-9e1d97b5d8b2/resource/d69672d6-acf4-49fa-8975-984f1e4587e4/download/0163010413421-production-rhizobium-meliloti-inoculants-alfalfa-rhizobium-trifolii-inoculants-c.pdf', NULL, NULL, 106, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Building on earlier research conducted in 1987, this 1988 study continues to investigate improved production methods for Rhizobium inoculants used in Alberta''s alfalfa and clover crops. These legume species obtain nitrogen through symbiosis with Rhizobium bacteria, reducing the need for fertilizer. While the United States had developed an inoculant industry since the 1940s, Canada still lacked domestic producers in the 1980s. The project focused on overcoming the low biomass yields typical of traditional fermentation by adjusting medium composition, applying pH control, and implementing fed-batch fermentation techniques.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f057556c-d50c-4885-9152-a13396bb29ca', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Profit by performance with Canadian alfalfa varieties', 'Government of Alberta', 1989, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/profit-by-performance-with-canadian-alfalfa-varieties', 'https://open.alberta.ca/dataset/85a6b271-fa15-418c-bd20-b3098fd35fbd/resource/5d35ec74-8f4f-4254-95a2-bcb781782dfc/download/0163010232177-profit-by-performance-with-canadian-alfalfa-varieties.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Discusses Canadian alfalfa varieties which have been developed by Agriculture Canada and have been bred to meet modern forage production standards. These varieties are well-adapted and widely grown in Western Canada, where they are recommended for use.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a443511f-0a5b-41b3-bb1b-c5f01e5aa841', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Recommendation of nitrogen, phosphorus and potassium balanced fertilizer based on soil status/soil availability and economic benefits of alfalfa in salt-affected soils of North China plain', 'Yaqi Chen, Muhammad Kamran, Qingsong Liu, Mingqiang Yue, Xinyue Qu, Jiating Han, Zhongxiang Zhao, Yi Zhang', 2026, 'BMC Plant Biology', '10.1186/s12870-025-07786-y', 'https://doi.org/10.1186/s12870-025-07786-y', 'https://doi.org/10.1186/s12870-025-07786-y', NULL, NULL, 21, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Improving alfalfa forage yieldis closely associated to the use of fertilizers. Generally, with the increase of fertilizer, alfalfa yield also increases correspondingly. However, in saline-alkaline areas, balancing the amount of nitrogen, phosphorus and potassium and achieving a high alfalfa yield is of great importance. In this study, we assumed that the alfalfa yield would reach the maximum at a moderate proportion of multiple fertilizers. A five-year continuous multi-fertilizer experiment with different ratios was carried out in the North China Plain. The experiment used randomized complete block design, tested three fertilizers and four fertilization levels (N0 0 kg ha− 1, N1 5 kg ha− 1, N2 10 kg ha− 1, N3 15 kg ha− 1; P0 0 kg ha− 1, P1 30 kg ha− 1, P2 60 kg ha− 1, P3 90 kg ha− 1; K0 0 kg ha− 1, K1 90 kg ha− 1, K2 180 kg ha− 1, K3 270 kg ha− 1), resulting in a total of 14 different treatments, N0P0K0, N0P2K2, N1P2K2, N1P1K2, N1P2K1, N2P1K1, N2P0K2, N2P1K2, N2P2K2, N2P3K2, N2P2K0, N2P2K1, N2P2K3, N3P2K2. All fertilizers applied twice a year. Results indicated that N2P1K2, N1P2K1 and N2P2K1 treatments had significant effects on increasing alfalfa dry matter and dry to fresh biomass; N2P2K2 treatment had a significant effect on alfalfa crude protein, but crude protein under N3P2K2 and N2P2K2 treatments showed no significant differences. In addition, the relative feed value (RFV) was significantly affected by potassium fertilizer. Under low potassium application, RFV showed a significant increase. N2 (10 kg ha− 1), P2 (60 kg ha− 1), and K2 (180 kg ha− 1) significantly increased the utilization efficiency of fertilizers, agronomic efficiency, and economic benefits, which were associated with decrease in fertilizer expenditure and increase in alfalfa income. The N3 (15 kg ha− 1), P3 (90 kg ha− 1), and K3 (270 kg ha− 1) significantly increased soil fertility, while had no significant effect on hay yield, nutritional quality and utilization efficiency. Therefore, N1P2K1 (5 kg ha− 1 N, 60 kg ha P− 1, 90 kg ha P− 1) treatment in the saline-alkali areas of the North China Plain is recommended for achieving high alfalfa yield, forage nutritional content, and improving the utilization rate of fertilizers by plants, increasing the farmers’ income without compromising soil fertility.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d5eeff65-cc7c-4e5d-bae7-38314cd80d99', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Removing forages from the rotation in a direct seeding system (Revised July 2018)', 'Government of Alberta', 2018, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4007949', 'https://open.alberta.ca/dataset/3ffd8c91-a444-40c7-800f-0c4765482e5b/resource/6d02b7ab-4694-41bc-a5d7-4fb722d25d47/download/519-17.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Using herbicides and direct seeding equipment can be an effective way to remove forages from a rotation. Each producer needs to design his or her own program for removing forages, considering the type of forage to be removed and the crop that will be seeded.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('234feebd-e551-49d3-b372-2c2b7345b7eb', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Salinity tolerance of turf and forage grasses', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/salinity-tolerance-of-turf-and-forage-grasses-0163010303911', 'https://open.alberta.ca/dataset/011ebbb8-5c26-486d-91b2-c45a721531b4/resource/8ff54543-f296-4c2a-9912-808083237819/download/0163010303911-salinity-tolerance-of-turf-and-forage-grasses.pdf', NULL, NULL, 24, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This study evaluated the salinity tolerance of 28 turf and forage grass species across irrigated and dryland sites in Alberta, Canada. Researchers established test sites at Brooks, Hanna and Oyen using a randomized block design and used the EM38 salinity meter to measure soil salinity efficiently. Results showed that Arthur Dahurian wildrye and Orbit tall wheatgrass performed well under irrigation, while Greenleaf pubescent wheatgrass and Fults weeping alkaligrass were most tolerant under dryland conditions. Turfgrass species like tall fescue and creeping red fescue exhibited moderate salt tolerance. The findings support improved species selection for forage and recreational use on over 1.2 million hectares of saline land.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c5fe4b65-fdee-453a-95d8-1b6d190dba15', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Nectar sugar production in alfalfa fields treated with several herbicides', 'P. S. Curry, J. Waddington, Najib Malik, Garry G. Bowes', 1995, 'Canadian Journal of Plant Science', '10.4141/cjps95-091', 'https://doi.org/10.4141/cjps95-091', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps95-091', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c4e9c7c4-5555-4b86-bdb1-5eab446caf17', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Soil and nutrient management of alfalfa', 'Government of Alberta', 2005, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3446389', 'https://open.alberta.ca/dataset/74e1ea44-3747-4369-ac01-39a6de0d3abe/resource/8c205ac4-4a2c-4b49-a33d-2b8df0adeeca/download/2005-121-531-5.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Ensuring adequate soil fertility levels and effectively managing nutrients are two keys to growing alfalfa successfully in Alberta. Alfalfa can produce from 2 to 7 tons of dry matter per acre depending on water and nutrients levels. Climate, soil type and management will also affect alfalfa’s potential yield. Alfalfa has a high demand for nutrients compared to other crops. Table 1 gives the approximate amount of each nutrient removed per ton of dry matter alfalfa. Alfalfa also requires 4 to 5 inches of water for each ton of dry matter produced.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('862745e3-c578-44c5-a113-ca74e83b3a4d', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Sources and contamination routes of microbial pathogens to fresh produce during field cultivation: A review', 'Alegbeleye OO, Singleton I, Sant''Ana AS', 2018, 'Food microbiology', '10.1016/j.fm.2018.01.003', 'https://doi.org/10.1016/j.fm.2018.01.003', 'https://europepmc.org/articles/PMC7127387?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'open access (Europe PMC)', 'Foodborne illness resulting from the consumption of contaminated fresh produce is a common phenomenon and has severe effects on human health together with severe economic and social impacts. The implications of foodborne diseases associated with fresh produce have urged research into the numerous ways and mechanisms through which pathogens may gain access to produce, thereby compromising microbiological safety. This review provides a background on the various sources and pathways through which pathogenic bacteria contaminate fresh produce; the survival and proliferation of pathogens on fresh produce while growing and potential methods to reduce microbial contamination before harvest. Some of the established bacterial contamination sources include contaminated manure, irrigation water, soil, livestock/ wildlife, and numerous factors influence the incidence, fate, transport, survival and proliferation of pathogens in the wide variety of sources where they are found. Once pathogenic bacteria have been introduced into the growing environment, they can colonize and persist on fresh produce using a variety of mechanisms. Overall, microbiological hazards are significant; therefore, ways to reduce sources of contamination and a deeper understanding of pathogen survival and growth on fresh produce in the field are required to reduce risk to human health and the associated economic consequences.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c55d657a-eb20-4014-afdf-0f91d1fd9be8', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Spotted alfalfa aphid (Revised January 2017 )', 'Government of Alberta', 2017, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2398176', 'https://open.alberta.ca/dataset/e1d58d97-7b4d-4805-bf1c-292146372df5/resource/d7fb43d4-166c-4de6-8762-94c7882ae946/download/622-17.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Presents a description of the spotted alfalfa aphid, describes the type of damage it can cause to alfalfa crops, and looks at biological and chemical methods of controlling the insect. This species of aphid can be more serious on alfalfa than the pea aphid because it not only sucks out the juice of the plant, but it also injects a toxin into it.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9432e989-7db2-40b7-a358-c78bfe6ad0b8', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Spread and survival of toadflax (Linaria vulgaris) growing with alfalfa or on fallow land', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/spread-and-survival-of-toadflax-linaria-vulgaris-growing-with-alfalfa-or-on-fallow-land', 'https://open.alberta.ca/dataset/844885b3-369c-4623-9fbc-dd23b9e29923/resource/4cd29e2a-49ad-4653-9a0b-a9bb6f8105a7/download/0163010090781-spread-survival-toadflax-linaria-vulgaris-growing-with-alfalfa-or-fallow-land.pdf', NULL, NULL, 44, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported that a vigorous alfalfa crop significantly limited the spread and density of common toadflax (Linaria vulgaris), with alfalfa yield losses up to ten per cent per year under moderate infestation. Twice-yearly harvesting prevented toadflax seed set, and rapid regrowth alfalfa cultivars outcompeted the weed better than creeping-rooted types. Barley cover crops reduced alfalfa vigour in the first year, allowing faster toadflax expansion, but did not affect later yields. Toadflax persisted and could threaten future crops if alfalfa vigour declined.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a740deac-83bd-4152-b6b4-3c95663d0c41', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Tetracycline and Sulfonamide Antibiotic Resistance Genes in Soils From Nebraska Organic Farming Operations', 'Cadena M, Durso LM, Miller DN, Waldrip HM, Castleberry BL, Drijber RA, Wortmann C', 2018, 'Frontiers in microbiology', '10.3389/fmicb.2018.01283', 'https://doi.org/10.3389/fmicb.2018.01283', 'https://europepmc.org/articles/PMC6033193?pdf=render', NULL, NULL, 10, NULL, 'northern_plains', 3, 'cc by', 'There is widespread agreement that agricultural antibiotic resistance should be reduced, however, it is unclear from the available literature what an appropriate target for reduction would be. Organic farms provide a unique opportunity to disentangle questions of agricultural antibiotic drug use from questions of antibiotic resistance in the soil. In this study, soil was collected from 12 certified organic farms in Nebraska, evaluated for the presence of tetracycline and sulfonamide resistance genes (n = 15 targets), and correlated to soil physical, chemical, and biological parameters. Tetracycline and sulfonamide antibiotic resistance genes (ARGs) were found in soils from all 12 farms, and 182 of the 196 soil samples (93%). The most frequently detected gene was tetG (55% of samples), followed by tet(Q) (49%), tet(S) (46%), tet(X) (30%), and tetA(P) (29%). Soil was collected from two depths. No differences in ARGs were observed based on soil depth. Positive correlations were noted between ARG presence and soil electrical conductivity, and concentrations of Ca, Na, and Mehlich-3 phosphorus. Data from this study point to possible relationships between selected soil properties and individual tetracycline resistance genes, including tet(O) which is a common target for environmental samples. We compared organic farm results to previously published data from prairie soils and found significant differences in detection frequency for 12 genes, eight of which were more commonly detected in prairie soils. Of interest, when tetracycline ARG results were sorted by gene mechanism, the efflux genes were generally present in higher frequency in the prairie soils, while the ribosomal protection and enzymatic genes were more frequently detected in organic farm soils, suggesting a possible ecological role for specific tetracycline resistance mechanisms. By comparing soil from organic farms with prairie soils, we can start to determine baseline effects of low-chemical input agricultural production practices on multiple measures of resistance.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2da06a6-efdc-43ec-b739-78d3a372b67f', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'The down-regulation of MsWOX13-2 promotes enhanced waterlogging resilience in alfalfa', 'Subedi U, Hughes KB, Lehmann M, Chen G, Acharya S, Hannoufa A, Nguyen CV, Singer SD', 2025, 'The Plant journal : for cell and molecular biology', '10.1111/tpj.70411', 'https://doi.org/10.1111/tpj.70411', 'https://europepmc.org/articles/PMC12368323?pdf=render', NULL, NULL, 22, NULL, 'southern_alberta', 5, 'cc by', 'Soil waterlogging events are predicted to escalate globally as a result of climate change, threatening the sustainability of alfalfa (Medicago sativa L.) and livestock production in the future. WUSCHEL-related homeobox (WOX) transcription factors are known to play a role in numerous developmental processes and abiotic stress responses; however, their function in waterlogging resilience has not been investigated as of yet. In the present study, we functionally characterized the alfalfa MsWOX13-2 gene, which we found to be differentially expressed in response to waterlogging. Although the RNAi-mediated silencing of MsWOX13-2 in alfalfa did not affect growth or morphology under normally watered conditions, MsWOX13-2 RNAi plants exhibited higher chlorophyll retention and maximum quantum efficiency of photosystem II, as well as greater survivability, compared to empty vector genotypes under waterlogging. Subsequent analyses indicated that MsWOX13-2 RNAi leaves accumulated less H2O2 and displayed a greater increase in superoxide dismutase activity under waterlogging, resulting in reduced oxidative damage, which may have contributed to the enhanced waterlogging tolerance in these genotypes. RNA-Seq analysis confirmed alterations in the transcript levels of genes related to antioxidants, as well as those involved in photosynthesis, anaerobic fermentation, phytohormone-related pathways, and transcriptional regulation in the leaves of WOX13-2 RNAi genotypes compared to wild type following waterlogging stress. Bi-allelic mutation of MsWOX13-2 in alfalfa using CRISPR/Cas9 confirmed its function in waterlogging response. Overall, our findings suggest that MsWOX13-2 acts as a negative regulator of waterlogging response in alfalfa, providing a novel candidate for downstream breeding endeavors in this important species.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('03b40814-d467-4f90-a590-5b4a59c912a8', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'The evaluation of spring and winter triticale varieties (and novel lines) for forage quality', 'Government of Alberta', 1999, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluation-of-spring-and-winter-triticale-varieties-and-novel-lines-for-forage-quality', 'https://open.alberta.ca/dataset/c58c7cf3-378f-48dd-a2d5-43680b1ad741/resource/94892376-3bdb-401a-bcb8-a64af1e81677/download/0163010183099-evaluation-spring-winter-triticale-varieties-novel-lines-forage-quality.pdf', NULL, NULL, 62, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document evaluated the forage yield and nutritive value of spring and winter triticale varieties and novel lines compared to barley, oat, wheat, and rye across multiple sites in Alberta and Saskatchewan during 1995 and 1996. The study included historical, current, and experimental triticale lines, and assessed silage quality at different harvest stages. Results showed that spring triticale generally had higher forage yield than barley and similar or better nutritive value than oat. Winter triticale had lower nutritive value than barley but was superior to fall rye. While newer triticale lines were agronomically improved, their forage quality was not consistently superior to older cultivars. The findings support triticale as a viable forage option in black and brown soil zones.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1ddaeb1d-c786-4b39-8763-d9ea28797315', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Use of cover crops as fall ungulate forage deterrents and subsequent spring livestock forage', 'Yelich JV, Ellison MJ', 2026, 'Translational animal science', '10.1093/tas/txag050', 'https://doi.org/10.1093/tas/txag050', 'https://europepmc.org/articles/PMC13242288?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'In the western United States, high quality forages like alfalfa (Medicao sativa L.) and perennial fall grass pastures containing cereal grains, legumes (Fabaceae spp.), and brassica (Brassica spp.) are commonly utilized by wild ungulates like elk (Cervus) and deer (Cervidae), resulting in negative economic impacts to livestock producers. Cover crops typically include combinations of cereals, legumes, and brassica while providing agronomic benefits to the soil, and alternative forages for either grazing or storage. Some species of brassicas like forage rape and turnips may limit voluntary feed intake in livestock and deer. Objectives of this study were to evaluate wild ungulate activity on fall planted cover crops and, forage quality and yield the subsequent summer. The experiment was conducted near Carmen, ID in the fall of 2016 and summer of 2017. On September 1, 2016, approximately 3 ha under sprinkler irrigation, were divided into three 1 ha plots, which were further divided into three 0.33 ha plots with three cover crops randomly and equally assigned to the smallest plots. Cover crops contained winter triticale (Triticosecale), Austrian winter peas (Pisum sativus subsp. arvense), and hairy vetch (Vicia villosa), and each treatment included canola (Brassica napus), crimson clover (Trifolium incarnatum), or purple top turnip (Brassica rapa). Game cameras were placed at the corners of each small plot to record ungulate activity from October 19 to December 7. In the summer of 2017, three fenced exclosures (0.80 m2) were randomly placed in each of the nine plots to determine cover crop yield and quality. Exclosure harvest was based on growth stage of triticale with initial harvest on June 12, a second on June 28, and a third on July 10. In the fall of 2016, deer and elk had an aversion (P ≤ 0.05) to grazing turnips but not canola and clover. Starting November 18, an increase (P ≤ 0.05) increase in elk detected/grazing turnips compared to canola and clover was observed. As temperatures decreased below 0°C for 5 of 7 days before November 18 we hypothesized that turnip leaves became more palatable and more tender, and elk started to graze them more frequently. In summer 2017, cover crop quantity across harvest periods was similar at 15.9 metric tons DM/ha. Crude protein decreased (P ≤ 0.05; 4.9, 11.4, 7.8%, respectively) and TDN increased (P ≤ 0.05; 54.9, 55.9, 57.3%; respectively) between harvest 1, 2, and 3. Results suggest that cover crops can be manipulated to encourage or deter wild ungulate species as a management tool and still provide adequate quality forage for livestock the following year.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3dcaa7fd-abad-4b3b-84c6-b77c7b6c70eb', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Water–Fertilizer Synergistic Effects and Resource Optimization for Alfalfa Production: A Central Composite Design and Response Surface Methodology Approach', 'Gaiya Mu, Yuanbo Jiang, Haiyan Li, Sinan Wei, Guangping Qi, Yanxia Kang, Minhua Yin, Yanlin Ma', 2025, 'Plants', '10.3390/plants14050731', 'https://doi.org/10.3390/plants14050731', 'https://www.mdpi.com/2223-7747/14/5/731', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'This study posits that strategically optimizing irrigation and fertilization regimes can enhance the productivity and water use efficiency (WUE) of alfalfa (Medicago sativa L.), thereby mitigating the constraints imposed by soil impoverishment and water scarcity in forage production systems of arid and semi-arid regions. Conducted over two years, the outdoor pot experiment investigated the effects of water regulation during the branching and bud stages (each at 60–100% θ0.85, where θ0.85 = 0.85θfc) and different levels of nitrogen and phosphorus fertilization (0–280 kg/ha each) on alfalfa yield and WUE. Using Response Surface Methodology (RSM) with a Central Composite Design (CCD), we modeled the relationships between input variables and key response parameters: total yield, evapotranspiration (ET), and WUE. The response surface models exhibited high reliability, with coefficients of determination R2, adjusted R2, predicted R2, and adequate precision exceeding 0.94, 0.90, 0.86, and 13.6, respectively. Sensitivity analysis indicated that water regulation during critical growth stages, particularly the branching stage, had the most significant impact on yield and ET, while nitrogen and phosphorus fertilization positively influenced WUE. Within the appropriate range of water management, judicious fertilization significantly enhanced alfalfa production performance, although excessive inputs resulted in diminishing returns. This study identified the optimal conditions for sustainable production: branching stage water regulation (82.26–83.12% θ0.85) and bud stage water regulation (78.11–88.47% θ0.85), along with nitrogen application (110.59–128.88 kg/ha) and phosphorus application (203.86–210 kg/ha). These findings provide practical guidelines for improving the sustainability and efficiency of alfalfa production in resource-limited environments.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b504a25-4624-48c6-9354-6f8b71144104', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Weed control in forage crops', 'Government of Alberta', 1990, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/weed-control-in-forage-crops', 'https://open.alberta.ca/dataset/a6a7ba27-55b7-4c6d-bf67-27b5be57bd63/resource/9570cb82-0e00-4f9c-b966-2807b61b4341/download/2385503-2002-weed-control-in-forage-crops.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report examines weed control strategies in forage crops in Alberta, highlighting the significant impact weeds have on both seed and livestock feed production. It outlines various cultural control methods, emphasizing the importance of establishing and maintaining vigorous crop stands through practices like seeding into clean fields, using weed-free seed, and proper fertilization. The report also discusses biological control using living organisms and details chemical control options, providing tables of herbicides effective against specific weeds in different forage crops and outlining crucial cropping, grazing, and feeding restrictions.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('675c6ebf-29ae-4427-ac12-e60edabec9c4', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Will injection of swine manure into grasslands increase forage yield?', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/afmrc-753', 'https://open.alberta.ca/dataset/f8cef3cc-697f-41c7-acf1-25f2f56df385/resource/0bcc5bde-365a-4656-8184-580516e4fe35/download/753-afmrc.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A project was conducted to assess the effects of swine manure injection on forages. The objective of the project was to demonstrate the effect of shallow hog manure injection on forage yield, quality, nitrate levels, and to assess the effects on soil nutrient levels at various application rates. It was found that shallow injection of liquid hog manure is a low-cost fertilizer alternative for grasslands. Tests showed that there were large seed and forage yield increases in grassland forages injected with liquid hog manure. But it was also found that there should be some concern about nitrate levels in forages used to feed livestock, and farmers should have their feed tested for nitrates after manure injection.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('edbcf129-c9c2-4bca-b672-b0504dc9f799', 'a7d8a8cc-aadc-4e3c-8b4a-8e3e2a1c375c', 'Yield and quality of alfalfa (Medicago sativa L.) in response to fertilizer application in China: A meta-analysis', 'Weifan Wan, Yuejin Li, Haigang Li', 2022, 'Frontiers in Plant Science', '10.3389/fpls.2022.1051725', 'https://doi.org/10.3389/fpls.2022.1051725', 'https://www.frontiersin.org/articles/10.3389/fpls.2022.1051725/full', NULL, NULL, 11, NULL, 'other', 1, 'open access (DOAJ)', 'IntroductionIn China, alfalfa (Medicago sativa L.) often grows in marginal land with poor soil fertility and suboptimal climate conditions. Alfalfa production cannot meet demands both in yield and quality. It is necessary to apply fertilizers to achieve high yields and produce high-quality alfalfa in China. However, there is no understanding on the impact of fertilizer application on alfalfa production and the possible optimal application rates across China.MethodsWe conducted a meta-analysis to explore the contribution of fertilizer application to the yield and quality of alfalfa based on a dataset from 86 studies published between 2004 and 2022.Results and DiscussionThe results showed that fertilizer application not only increased alfalfa yield by 19.2% but also improved alfalfa quality by increasing crude protein (CP) by 7.7% and decreasing acid detergent fibre by 2.9% and neutral detergent fibre by 1.8% overall compared to the non-fertilizer control levels. The combined nitrogen (N), phosphorus (P) and potassium (K) and combined NP fertilizer applications achieved the greatest yield and CP concentration increases of 27.0% and 13.5%, respectively. Considering both yield and quality, the optimal rate of fertilizer application ranged from 30 to 60 kg ha-1 for N, 120 to 150 kg ha-1 for P and less than 120 kg ha-1 for K. Meta-analysis further showed that the effect of fertilizer application on yield was greater in low soil organic matter (SOM) soils than in high SOM soils. In conclusion, fertilizer application is an effective strategy to improve the yield and quality of alfalfa in China, especially that grown in low SOM soils. This study is helpful for optimizing fertilization schedules of alfalfa in China.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a9a7ce1-5906-48b9-8e67-567329c3c721', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'A Comprehensive Review of Microalgae and Cyanobacteria-Based Biostimulants for Agriculture Uses', 'Chabili A, Minaoui F, Hakkoum Z, Douma M, Meddich A, Loudiki M', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13020159', 'https://doi.org/10.3390/plants13020159', 'https://europepmc.org/articles/PMC10820584?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Significant progress has been achieved in the use of biostimulants in sustainable agricultural practices. These new products can improve plant growth, nutrient uptake, crop yield and quality, stress adaptation and soil fertility, while reducing agriculture''s environmental footprint. Although it is an emerging market, the biostimulant sector is very promising, hence the increasing attention of the scientific community and agro-industry stakeholders in finding new sources of plant biostimulants. Recently, pro- and eucaryotic microalgae have gained prominence and can be exploited as biostimulants due to their ability to produce high-value-added metabolites. Several works revealed the potential of microalgae- and cyanobacteria-based biostimulants (MCBs) as plant growth promoters and stress alleviators, as well as encouraging results pointing out that their use can address current and future agricultural challenges. In contrast to macroalgae biostimulants, the targeted applications of MBs in agriculture are still in their earlier stages and their commercial implementation is constrained by the lack of research and cost of production. The purpose of this paper is to provide a comprehensive overview on the use of this promising new category of plant biostimulants in agriculture and to highlight the current knowledge on their application prospects. Based on the prevailing state of the art, we aimed to roadmap MCB formulations from microalgae and cyanobacteria strain selection, algal biomass production, extraction techniques and application type to product commercialization and farmer and consumer acceptance. Moreover, we provide examples of successful trials demonstrating the beneficial applications of microalgal biostimulants as well as point out bottlenecks and constraints regarding their successful commercialization and input in sustainable agricultural practices.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('31d21626-e33a-4fbb-bcf8-752f9b57f8a0', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'A study of the influence of management practices of alfalfa seed production in Manitoba', 'Kenneth W. Plews', 1973, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/3516', 'http://hdl.handle.net/1993/3516', NULL, NULL, 115, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('adb9bbc1-db97-4cd7-baa8-8fcc8f37455a', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Advances in Crop Improvement and Delivery Research for Nutritional Quality and Health Benefits of Groundnut (Arachis hypogaea L.)', 'Ojiewo CO, Janila P, Bhatnagar-Mathur P, Pandey MK, Desmae H, Okori P, Mwololo J, Ajeigbe H', 2020, 'Frontiers in plant science', '10.3389/fpls.2020.00029', 'https://doi.org/10.3389/fpls.2020.00029', 'https://europepmc.org/articles/PMC7046547?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Groundnut is an important global food and oil crop that underpins agriculture-dependent livelihood strategies meeting food, nutrition, and income security. Aflatoxins, pose a major challenge to increased competitiveness of groundnut limiting access to lucrative markets and affecting populations that consume it. Other drivers of low competitiveness include allergens and limited shelf life occasioned by low oleic acid profile in the oil. Thus grain off-takers such as consumers, domestic, and export markets as well as processors need solutions to increase profitability of the grain. There are some technological solutions to these challenges and this review paper highlights advances in crop improvement to enhance groundnut grain quality and nutrient profile for food, nutrition, and economic benefits. Significant advances have been made in setting the stage for marker-assisted allele pyramiding for different aflatoxin resistance mechanisms-in vitro seed colonization, pre-harvest aflatoxin contamination, and aflatoxin production-which, together with pre- and post-harvest management practices, will go a long way in mitigating the aflatoxin menace. A breakthrough in aflatoxin control is in sight with overexpression of antifungal plant defensins, and through host-induced gene silencing in the aflatoxin biosynthetic pathway. Similarly, genomic and biochemical approaches to allergen control are in good progress, with the identification of homologs of the allergen encoding genes and development of monoclonal antibody based ELISA protocol to screen for and quantify major allergens. Double mutation of the allotetraploid homeologous genes, FAD2A and FAD2B, has shown potential for achieving >75% oleic acid as demonstrated among introgression lines. Significant advances have been made in seed systems research to bridge the gap between trait discovery, deployment, and delivery through innovative partnerships and action learning.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3ef45075-b02f-48f3-bc58-3112c8fc1ab7', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'An economic analysis of interseeding of pasture and feeding legume forages to dairy cows in an organic system', 'Mumford ME, Hadrich JC, Brito AF, Heins BJ', 2026, 'JDS communications', '10.3168/jdsc.2025-0968', 'https://doi.org/10.3168/jdsc.2025-0968', 'https://europepmc.org/articles/PMC13464206?pdf=render', NULL, NULL, 7, NULL, 'northern_plains', 3, 'cc by', 'This study assessed the economic viability of interseeding a legume-grass mixture in an existing organic pasture system, focusing on the implications for milk yield, milk composition, and profitability. Using net present value analysis, financial and production data were analyzed from the University of Minnesota Farm Financial FINBIN database and university feeding trials (University of Minnesota and University of New Hampshire). The analysis modeled a baseline 88-cow organic dairy herd with an average milk yield of 7,185 kg. A 10-yr net present value analysis was used to account for the time value of money at a discount rate of 7% and fluctuating pasture productivity, with interseeding occurring in years 1, 5, and 10. The analysis found a positive net present value of $394,274, which indicated that the investment was financially feasible for organic dairy farms. Sensitivity testing found that although the modeled farm was resilient to increased seed costs, profitability was more dependent on milk price and production. Specifically, an 18.7% decrease in milk price or a reduction in annual milk yield to 5,844 kg/cow would be required to reduce the net present value to zero. In conclusion, integrating legume-grass mixtures into organic rotational grazing systems was economically feasible and could support long-term profitability.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('23e30f3e-a036-4da7-9ef5-369a815dd168', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Biostimulant Substances for Sustainable Agriculture: Origin, Operating Mechanisms and Effects on Cucurbits, Leafy Greens, and Nightshade Vegetables Species', 'Cristofano F, El-Nakhel C, Rouphael Y', 2021, 'Biomolecules', '10.3390/biom11081103', 'https://doi.org/10.3390/biom11081103', 'https://europepmc.org/articles/PMC8392623?pdf=render', NULL, NULL, 36, NULL, 'other', 1, 'cc by', 'Climate change is a pressing matter of anthropogenic nature to which agriculture contributes by abusing production inputs such as inorganic fertilizers and fertigation water, thus degrading land and water sources. Moreover, as the increase in the demand of food in 2050 is estimated to be 25 to 70% more than what is currently produced today, a sustainable intensification of agriculture is needed. Biostimulant substances are products that the EU states work by promoting growth, resistance to plant abiotic stress, and increasing produce quality, and may be a valid strategy to enhance sustainable agricultural practice. Presented in this review is a comprehensive look at the scientific literature regarding the widely used and EU-sanctioned biostimulant substances categories of silicon, seaweed extracts, protein hydrolysates, and humic substances. Starting from their origin, the modulation of plants'' hormonal networks, physiology, and stress defense systems, their in vivo effects are discussed on some of the most prominent vegetable species of the popular plant groupings of cucurbits, leafy greens, and nightshades. The review concludes by identifying several research areas relevant to biostimulant substances to exploit and enhance the biostimulant action of these substances and signaling molecules in horticulture.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2fe8e15a-1f85-426b-957b-d9d8673bf641', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Boron Fertilization of Irrigated Alfalfa in Montana', 'Anish Sapkota, Emily C.G. Meccage, Robert N. Stougaard, John P. Tanner, Danielle M. Peterson, Jessica A. Torrion', 2018, 'Crop Forage & Turfgrass Management', '10.2134/cftm2017.11.0085', 'https://doi.org/10.2134/cftm2017.11.0085', 'https://acsess.onlinelibrary.wiley.com/doi/pdfdirect/10.2134/cftm2017.11.0085', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'Core Ideas Boron (B) application increased petiole B in irrigated alfalfa but did not impact yield and quality. Low initial soil B is not a reliable measure of the need to amend with B using foliar application of irrigated alfalfa in Montana. Diagnosing signs of B deficiency coupled with in‐season petiole B analysis may be of better value to the producers. A boron (B) deficient soil may negatively impact irrigated alfalfa (Medicago sativa L.) plant tissue sufficiency, thereby compromising yield and quality in a short‐season environment such as Montana. The objective was to determine the impacts of B fertilization on irrigated alfalfa yield and quality in 2015 and 2016 at Creston and Dillon, MT on fine sandy loam and silt loam soils, respectively. The initial soil B levels at the Creston and Dillon sites were 0.2 and 0.8 ppm, respectively. The study was conducted as a randomized complete block design with five B levels: (1) 0; split applications of (2) 0.50, (3) 1.00, (4) 2.00; and a one‐time application of (5) 2.00 lb/ac in four replications. Full doses of Treatment 5 and half the dose of Treatments 2–4 were applied in early spring at a 3‐inch regrowth height. The other half dosage of Treatments 2–4 was re‐applied at a 3‐inch plant height after the first cutting. A liquid 10% B AgriSolutions was foliar‐applied as B fertilizer. All the cuttings were performed at 10% bloom. Application of B increased (P < 0.05) plant B concentration at both locations. Boron fertilization increased (P < 0.05) crop yield for the second cutting in 2015 at Dillon but did not influence all of the other seasonal cuttings nor total yields for either year or location. No significant effect of B on forage quality was observed. This research suggests foliar B fertilization based on a low B soil test is not beneficial for irrigated alfalfa producers in Montana.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e3031474-9dd9-415d-92b5-6766bb04cac1', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Candidate Genes Associated with Abiotic Stress Response in Plants as Tools to Engineer Tolerance to Drought, Salinity and Extreme Temperatures in Wheat: An Overview', 'Trono D, Pecchioni N', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11233358', 'https://doi.org/10.3390/plants11233358', 'https://europepmc.org/articles/PMC9737347?pdf=render', NULL, NULL, 35, NULL, 'other', 1, 'cc by', 'Wheat represents one of the most important staple food crops worldwide and its genetic improvement is fundamental to meeting the global demand of the growing population. However, the environmental stresses, worsened by climate change, and the increasing deterioration of arable land make it very difficult to fulfil this demand. In light of this, the tolerance of wheat to abiotic stresses has become a key objective of genetic improvement, as an effective strategy to ensure high yields without increasing the cultivated land. Genetic erosion related to modern agriculture, whereby elite, high-yielding wheat varieties are the product of high selection pressure, has reduced the overall genetic diversity, including the allelic diversity of genes that could be advantageous for adaptation to adverse environmental conditions. This makes traditional breeding a less effective or slower approach to generating new stress-tolerant wheat varieties. Either mining for the diversity of not-adapted large germplasm pools, or generating new diversity, are the mainstream approaches to be pursued. The advent of genetic engineering has opened the possibility to create new plant variability and its application has provided a strong complement to traditional breeding. Genetic engineering strategies such as transgenesis and genome editing have then provided the opportunity to improve environmental tolerance traits of agronomic importance in cultivated species. As for wheat, several laboratories worldwide have successfully produced transgenic wheat lines with enhanced tolerance to abiotic stresses, and, more recently, significant improvements in the CRISPR/Cas9 tools available for targeted variations within the wheat genome have been achieved. In light of this, the present review aims to provide successful examples of genetic engineering applications for the improvement of wheat adaptation to drought, salinity and extreme temperatures, which represent the most frequent and most severe events causing the greatest losses in wheat production worldwide.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3130c637-9994-43f6-a0d0-043c0df8f300', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Climate change challenges, plant science solutions', 'Eckardt NA, Ainsworth EA, Bahuguna RN, Broadley MR, Busch W, Carpita NC, Castrillo G, Chory J', 2023, 'The Plant cell', '10.1093/plcell/koac303', 'https://doi.org/10.1093/plcell/koac303', 'https://europepmc.org/articles/PMC9806663?pdf=render', NULL, NULL, 43, NULL, 'other', 1, 'cc by', 'Climate change is a defining challenge of the 21st century, and this decade is a critical time for action to mitigate the worst effects on human populations and ecosystems. Plant science can play an important role in developing crops with enhanced resilience to harsh conditions (e.g. heat, drought, salt stress, flooding, disease outbreaks) and engineering efficient carbon-capturing and carbon-sequestering plants. Here, we present examples of research being conducted in these areas and discuss challenges and open questions as a call to action for the plant science community.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('244dedb5-ef98-4be5-b87c-da4e1340e15f', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Insects associated with alfalfa seed production', 'Government of Alberta', 1986, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2473219', 'https://open.alberta.ca/dataset/9345152b-5fb1-4acd-9e3c-3f86c0f17b6f/resource/4e5a71cd-7524-4731-929c-00bb5747c7bf/download/2001-121-620-1.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This field guide was prepared to enable growers of seed alfalfa to quickly identify their pest and beneficial insects. The important distinguishing features are indicated on the plates by arrows. These features can be readily seen with a hand lens or magnifying glass. Economic thresholds are based on the average number of insects captured in five 90° sweeps.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('58387cc8-b427-4282-bd07-f8f50dcf7e9b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Comparative Study between Exogenously Applied Plant Growth Hormones versus Metabolites of Microbial Endophytes as Plant Growth-Promoting for Phaseolus vulgaris L', 'Ismail MA, Amin MA, Eid AM, Hassan SE, Mahgoub HAM, Lashin I, Abdelwahab AT, Azab E', 2021, 'Cells', '10.3390/cells10051059', 'https://doi.org/10.3390/cells10051059', 'https://europepmc.org/articles/PMC8146795?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Microbial endophytes organize symbiotic relationships with the host plant, and their excretions contain diverse plant beneficial matter such as phytohormones and bioactive compounds. In the present investigation, six bacterial and four fungal strains were isolated from the common bean (Phaseolus vulgaris L.) root plant, identified using molecular techniques, and their growth-promoting properties were reviewed. All microbial isolates showed varying activities to produce indole-3-acetic acid (IAA) and different hydrolytic enzymes such as amylase, cellulase, protease, pectinase, and xylanase. Six bacterial endophytic isolates displayed phosphate-solubilizing capacity and ammonia production. We conducted a field experiment to evaluate the promotion activity of the metabolites of the most potent endophytic bacterial (Bacillus thuringiensis PB2 and Brevibacillus agri PB5) and fungal (Alternaria sorghi PF2 and, Penicillium commune PF3) strains in comparison to two exogenously applied hormone, IAA, and benzyl adenine (BA), on the growth and biochemical characteristics of the P. vulgaris L. Interestingly, our investigations showed that bacterial and fungal endophytic metabolites surpassed the exogenously applied hormones in increasing the plant biomass, photosynthetic pigments, carbohydrate and protein contents, antioxidant enzyme activity, endogenous hormones and yield traits. Our findings illustrate that the endophyte Brevibacillus agri (PB5) provides high potential as a stimulator for the growth and productivity of common bean plants.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('487e04ae-281a-4e9b-8395-f11bb329f647', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Comparison of Honey Bee (Hymenoptera: Apidae) Colony Units of Different Sizes as Pollinators of Hybrid Seed Canola', 'Ovinge LP, Hoover SE', 2018, 'Journal of economic entomology', '10.1093/jee/toy155', 'https://doi.org/10.1093/jee/toy155', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC6075627.1/PMC6075627.1.pdf', NULL, NULL, 7, NULL, 'southern_alberta', 4, 'cc by-nc', 'We compare two different sizes of honey bee colony units: singles (one brood chamber) and doubles (two brood chambers) in hybrid seed canola pollination in southern Alberta in 2014 and 2015. Currently, canola seed production companies only contract double-brood chamber units to pollinate canola in southern Alberta, but it may be advantageous to the industry if singles could also be contracted for pollination, as they are in many other crops. To evaluate the differences between the colony units, we measured population size, nectar and pollen foraging, nectar and pollen load weights, pollen collection, and honey production. The colony populations of both the single- and double-brood chamber hives in this study were highly variable. In 2015, there was no difference between the single- and the double-brood chamber colonies in adult bee populations, and the singles had more sealed brood than did the double-brood chamber colonies. Our findings indicate that in comparison to doubles, on a per-frame basis, singles yield more pollen, more nectar foragers, similar or more pollen foragers, and similar amounts of honey. Therefore, we conclude that singles could be used to provide the same level of pollination services as doubles currently do in hybrid seed canola pollination, and growers should focus on receiving healthy populous colonies, regardless of the number of brood boxes.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18484b94-a445-4b3d-925d-b4dd0d415ba9', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Contrasting Pollinators and Pollination in Native and Non-Native Regions of Highbush Blueberry Production', 'Jason Gibbs, Elizabeth Elle, Kyle Bobiwash, Tiia Haapalainen, Rufus Isaacs', 2016, 'PLoS ONE', '10.1371/journal.pone.0158937', 'https://doi.org/10.1371/journal.pone.0158937', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0158937&type=printable', NULL, NULL, 24, NULL, 'canada', 3, 'cc-by', 'Highbush blueberry yields are dependent on pollination by bees, and introduction of managed honey bees is the primary strategy used for pollination of this crop. Complementary pollination services are also provided by wild bees, yet highbush blueberry is increasingly grown in regions outside its native range where wild bee communities may be less adapted to the crop and growers may still be testing appropriate honey bee stocking densities. To contrast crop pollination in native and non-native production regions, we sampled commercial ''Bluecrop'' blueberry fields in British Columbia and Michigan with grower-selected honey bee stocking rates (0-39.5 hives per ha) to compare bee visitors to blueberry flowers, pollination and yield deficits, and how those vary with local- and landscape-scale factors. Observed and Chao-1 estimated species richness, as well as Shannon diversity of wild bees visiting blueberries were significantly higher in Michigan where the crop is within its native range. The regional bee communities were also significantly different, with Michigan farms having greater dissimilarity than British Columbia. Blueberry fields in British Columbia had fewer visits by honey bees than those in Michigan, irrespective of stocking rate, and they also had lower berry weights and a significant pollination deficit. In British Columbia, pollination service increased with abundance of wild bumble bees, whereas in Michigan the abundance of honey bees was the primary predictor of pollination. The proportion of semi-natural habitat at local and landscape scales was positively correlated with wild bee abundance in both regions. Wild bee abundance declined significantly with distance from natural borders in Michigan, but not in British Columbia where large-bodied bumble bees dominated the wild bee community. Our results highlight the varying dependence of crop production on different types of bees and reveal that strategies for pollination improvement in the same crop can vary greatly across production regions.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d35baf7-a7fe-4c3b-8923-68f9c0dcdac2', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Crop production and nitrogen use in European cropland and grassland 1961-2019', 'Einarsson R, Sanz-Cobena A, Aguilera E, Billen G, Garnier J, van Grinsven HJM, Lassaletta L', 2021, 'Scientific data', '10.1038/s41597-021-01061-z', 'https://doi.org/10.1038/s41597-021-01061-z', 'https://europepmc.org/articles/PMC8556239?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'This paper presents EuropeAgriDB v1.0, a dataset of crop production and nitrogen (N) flows in European cropland 1961-2019. The dataset covers 26 present-day countries, detailing the cropland N harvests in 17 crop categories as well as cropland N inputs in synthetic fertilizers, manure, symbiotic fixation, and atmospheric deposition. The study builds on established methods but goes beyond previous research by combining data from FAOSTAT, Eurostat, and a range of national data sources. The result is a detailed, complete, and consistent dataset, intended as a basis for further analyses of past and present agricultural production patterns, as well as construction of scenarios for the future.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('107ef02d-989a-4774-88e8-eb0f11868d5a', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Current Scenario and Future Prospects of Endophytic Microbes: Promising Candidates for Abiotic and Biotic Stress Management for Agricultural and Environmental Sustainability', 'Anand U, Pal T, Yadav N, Singh VK, Tripathi V, Choudhary KK, Shukla AK, Sunita K', 2023, 'Microbial ecology', '10.1007/s00248-023-02190-1', 'https://doi.org/10.1007/s00248-023-02190-1', 'https://europepmc.org/articles/PMC10497456?pdf=render', NULL, NULL, 32, NULL, 'other', 1, 'cc by', 'Globally, substantial research into endophytic microbes is being conducted to increase agricultural and environmental sustainability. Endophytic microbes such as bacteria, actinomycetes, and fungi inhabit ubiquitously within the tissues of all plant species without causing any harm or disease. Endophytes form symbiotic relationships with diverse plant species and can regulate numerous host functions, including resistance to abiotic and biotic stresses, growth and development, and stimulating immune systems. Moreover, plant endophytes play a dominant role in nutrient cycling, biodegradation, and bioremediation, and are widely used in many industries. Endophytes have a stronger predisposition for enhancing mineral and metal solubility by cells through the secretion of organic acids with low molecular weight and metal-specific ligands (such as siderophores) that alter soil pH and boost binding activity. Finally, endophytes synthesize various bioactive compounds with high competence that are promising candidates for new drugs, antibiotics, and medicines. Bioprospecting of endophytic novel secondary metabolites has given momentum to sustainable agriculture for combating environmental stresses. Biotechnological interventions with the aid of endophytes played a pivotal role in crop improvement to mitigate biotic and abiotic stress conditions like drought, salinity, xenobiotic compounds, and heavy metals. Identification of putative genes from endophytes conferring resistance and tolerance to crop diseases, apart from those involved in the accumulation and degradation of contaminants, could open new avenues in agricultural research and development. Furthermore, a detailed molecular and biochemical understanding of endophyte entry and colonization strategy in the host would better help in manipulating crop productivity under changing climatic conditions. Therefore, the present review highlights current research trends based on the SCOPUS database, potential biotechnological interventions of endophytic microorganisms in combating environmental stresses influencing crop productivity, future opportunities of endophytes in improving plant stress tolerance, and their contribution to sustainable remediation of hazardous environmental contaminants.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2c5b427-4030-4d91-8b6a-1071094bb3ef', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Current Status and Potential of Moringa oleifera Leaf as an Alternative Protein Source for Animal Feeds', 'Su B, Chen X', 2020, 'Frontiers in veterinary science', '10.3389/fvets.2020.00053', 'https://doi.org/10.3389/fvets.2020.00053', 'https://europepmc.org/articles/PMC7054280?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'The increased consumption of livestock, poultry, and fish products in people''s diet threatens to drive production toward the use of more and more conventional crops in animal feeds. In this context, alleviating the tightening grain crop supply and ensuring the healthy development of animal husbandry through innovations in protein feedstuff production remain considerable challenges. Moringa oleifera is a miracle tree species with abundant nutrients, high protein biological value, and good feeding effect. As a new protein feedstuff, M. oleifera has great potential in alleviating the feeding crisis. Here, we review available literature regarding the characterization of M. oleifera in the field of animal husbandry in terms of nutrient content, digestion, and absorption characteristics, and feeding effects and present current challenges in using M. oleifera as animal feed.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b0e6a5cb-b6f7-4196-adaa-fc2c83a6257d', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'De novo Transcriptome Sequencing to Dissect Candidate Genes Associated with Pearl Millet-Downy Mildew (Sclerospora graminicola Sacc.) Interaction', 'Kulkarni KS, Zala HN, Bosamia TC, Shukla YM, Kumar S, Fougat RS, Patel MS, Narayanan S', 2016, 'Frontiers in plant science', '10.3389/fpls.2016.00847', 'https://doi.org/10.3389/fpls.2016.00847', 'https://europepmc.org/articles/PMC4916200?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Understanding the plant-pathogen interactions is of utmost importance to design strategies for minimizing the economic deficits caused by pathogens in crops. With an aim to identify genes underlying resistance to downy mildew, a major disease responsible for productivity loss in pearl millet, transcriptome analysis was performed in downy mildew resistant and susceptible genotypes upon infection and control on 454 Roche NGS platform. A total of ~685 Mb data was obtained with 1 575 290 raw reads. The raw reads were pre-processed into high-quality (HQ) reads making to ~82% with an average of 427 bases. The assembly was optimized using four assemblers viz. Newbler, MIRA, CLC and Trinity, out of which MIRA with a total of 14.10 Mb and 90118 transcripts proved to be the best for assembling reads. Differential expression analysis depicted 1396 and 936 and 1000 and 1591 transcripts up and down regulated in resistant inoculated/resistant control and susceptible inoculated/susceptible control respectively with a common of 3644 transcripts. The pathways for secondary metabolism, specifically the phenylpropanoid pathway was up-regulated in resistant genotype. Transcripts up-regulated as a part of defense response included classes of R genes, PR proteins, HR induced proteins and plant hormonal signaling transduction proteins. The transcripts for skp1 protein, purothionin, V type proton ATPase were found to have the highest expression in resistant genotype. Ten transcripts, selected on the basis of their involvement in defense mechanism were validated with qRT-PCR and showed positive co-relation with transcriptome data. Transcriptome analysis evoked potentials of hypersensitive response and systemic acquired resistance as possible mechanism operating in defense mechanism in pearl millet against downy mildew infection.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ef68c7e4-ef0c-43a1-973f-6b672e396768', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Diversity, Relative Abundance, Movement, and Fitness of Insect Predators in Winter Canola Agricultural Landscapes in the United States Southern Plains', 'Casi N. Jessie', 2017, 'SHAREOK (University of Oklahoma; Oklahoma State University; Central Oklahoma University)', NULL, 'https://hdl.handle.net/11244/54544', 'https://hdl.handle.net/11244/54544', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('787b06bd-872e-4e95-8ade-4b7bfc1788d9', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Effect of fertilizer on seed yield of alfalfa under irrigation in Saskatchewan', 'B. D. Gossen, H. Ukrainetz, Juliana J. Soroka', 2004, 'Canadian Journal of Plant Science', '10.4141/p03-136', 'https://doi.org/10.4141/p03-136', 'https://cdnsciencepub.com/doi/pdf/10.4141/P03-136', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('00c56df7-4e70-48d6-8317-083d78f2ae35', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Effects of alternative management practices on the abundance of arthropods in a mixed-crop agroecosystem', 'Paramjit Gill', 2013, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/2649', 'https://scholarworks.montana.edu/xmlui/handle/1/2649', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b6064f36-9365-412d-9b8e-433d0b49226e', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'EFFECTS OF ESTABLISHMENT METHOD AND A RAPESEED COMPANION CROP ON ALFALFA SEED YIELD', 'J. Waddington, Najib Malik', 1987, 'Canadian Journal of Plant Science', '10.4141/cjps87-037', 'https://doi.org/10.4141/cjps87-037', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps87-037', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2242fae7-d459-4055-8677-173b47de294a', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Effects of Extended Prepupal Storage Duration on Adult Flight Physiology of the Alfalfa Leafcutting Bee (Hymenoptera: Megachilidae)', 'Meghan M. Bennett, Kelsey Petersen, George D. Yocum, Joseph P. Rinehart, William Kemp, Kendra J. Greenlee', 2013, 'Journal of Economic Entomology', '10.1603/ec12487', 'https://doi.org/10.1603/ec12487', 'https://academic.oup.com/jee/article-pdf/106/3/1089/19246848/jee106-1089.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'The alfalfa leafcutting bee, Megachile rotundata (F.), is a solitary, cavity-nesting bee and is the primary pollinator for alfalfa seed production. Bee management practices include cold storage during the prepupal stage. Fluctuating thermal regimes during cold storage increases survival of cold storage and allows a doubling of the cold storage period with no decrease in survival. However, survival, characterized as successful adult emergence, is not qualitative. In this study, we determined whether extended storage affects adult bee respiration or flight physiology. We overwintered bees for a single winter (current management protocol) or for 12 mo longer (extended storage). We used resting and tethered flight metabolic rates and resting critical PO2 (the oxygen partial pressure below which metabolism can no longer be sustained) as indices of adult bee quality. We found no significant differences in body mass, resting or flight metabolic rates, or critical PO2 between the two groups. Together these data indicate that extended storage of M. rotundata produces bees of similar respiratory capacity and flight ability. These findings could increase the use of M. rotundata as an alternative pollinator, allowing for extended storage to time adult emergence with early blooming crops.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4c2a66f5-a4ab-472f-92a5-f974ae4425ba', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Effects of LED lighting on the nutritional properties and microbial safety of microgreens', 'Guragain A, Topalcengiz Z, Moreira J', 2026, 'Frontiers in nutrition', '10.3389/fnut.2026.1869208', 'https://doi.org/10.3389/fnut.2026.1869208', 'https://europepmc.org/articles/PMC13341295?pdf=render', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc by', 'Microgreens are immature and nutritious seedlings, rich in micronutrients and bioactive compounds these crops are commonly grown in controlled environments. Various light sources are used during indoor growth of microgreens depending on the specific light spectrum requirements of the crop, the energy efficiency of the lighting system, and budget-oriented market availability of production systems. Light Emitting Diode (LED) treatments offer a promising opportunity for microgreen production. This review synthesizes current literature on the effects of various treatments/conditions, emphasizing LED light spectra (wavelength), intensity, and photo period on microgreen characteristics including yield and growth, nutrient composition, and microbial safety. Currently, research on lighting effect on nutritional properties focus on Brassicaceae family which could be further expanded to other plant groups. Also, limited research on photoperiod (LED lighting duration) represents a research gap. Influence of the light quality, intensity and photoperiod have been reported on microgreen growth, yield and nutritional properties which vary with microgreen type. Although foodborne pathogens are known to persist and proliferate in microgreens under poor production and handling conditions, there remains a critical research gap regarding microbial survival, proliferation, and antimicrobial efficacy during production and storage under LED lighting systems. This highlights a need for comprehensive research to develop food safety protocols for microgreen production with LED light treatment holding significant potential.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a149ba9c-ba29-47de-bdfe-aeb7e7e895dd', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Effects of the Insect Growth Regulator, Novaluron on Immature Alfalfa Leafcutting Bees,Megachile rotundata', 'Erin W. Hodgson, Theresa L. Pitts‐Singer, James D. Barbour', 2011, 'Journal of Insect Science', '10.1673/031.011.0143', 'https://doi.org/10.1673/031.011.0143', 'https://academic.oup.com/jinsectscience/article-pdf/11/1/43/18170599/jis11-0043.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Alfalfa leafcutting bees, Megachile rotundata F. (Hymenoptera: Megachilidae), are the most common pollinators of alfalfa in the Pacific Northwest. Reports from users of M. rotundata in Idaho, Utah and Colorado have indicated exceptionally poor bee return from fields treated with novaluron to control Lygus spp. Our goal was to evaluate novaluron toxicity to immature M. rotundata using two different possible mechanisms of exposure. One goal was to assess immature mortality via treating nectar-pollen provisions and adults with novaluron. Immature M. rotundata mortality in all novaluron provision dosing treatments was significantly higher than the water or blank controls, providing evidence that novaluron is toxic to progeny in nest cells. The mean cumulative frequency showed that more eggs and 1st-2nd instars died compared to older instars. Female M. rotundata nested similarly in field cages during the field cage experiment; however, there was greater immature mortality in cages where females were fed sugar-water + novaluron compared to sugar-water only. Although females provided adequate provisions, there was a low percentage of egg hatch and larval development when females ingested novaluron before mating and nesting. Novaluron was also present in egg provision of bees collecting resources from novaluron-sprayed plants. At least 84% of progeny died when the females were allowed to mate and nest 24 hours after a novaluron application. Novaluron could be contributing to poor bee return in alfalfa grown for seed. Timely insecticide applications to suppress Lygus spp. is an important consideration to improve ongoing bee health.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d627ffa5-f589-4e45-9e28-b1d1f36d21bf', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Enteric methane mitigation interventions', 'Fouts JQ, Honan MC, Roque BM, Tricarico JM, Kebreab E', 2022, 'Translational animal science', '10.1093/tas/txac041', 'https://doi.org/10.1093/tas/txac041', 'https://europepmc.org/articles/PMC9071062?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'Mitigation of enteric methane (CH4) presents a feasible approach to curbing agriculture''s contribution to climate change. One intervention for reduction is dietary reformulation, which manipulates the composition of feedstuffs in ruminant diets to redirect fermentation processes toward low CH4 emissions. Examples include reducing the relative proportion of forages to concentrates, determining the rate of digestibility and passage rate from the rumen, and dietary lipid inclusion. Feed additives present another intervention for CH4 abatement and are classified based on their mode of action. Through inhibition of key enzymes, 3-nitrooxypropanol (3-NOP) and halogenated compounds directly target the methanogenesis pathway. Rumen environment modifiers, including nitrates, essential oils, and tannins, act on the conditions that affect methanogens and remove the accessibility of fermentation products needed for CH4 formation. Low CH4-emitting animals can also be directly or indirectly selected through breeding interventions, and genome-wide association studies are expected to provide efficient selection decisions. Overall, dietary reformulation and feed additive inclusion provide immediate and reversible effects, while selective breeding produces lasting, cumulative CH4 emission reductions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9ff6a672-362a-43a2-8223-f2d0f3ad61ac', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Evaluation of the Yield and Agronomic Traits of Tropical alfalfa Cultivars in Sistan\''s Warm and Dry Climate', 'Ahmad Ghasemi, Mohammad Reza Narouierad, Mahmoud Mohammad ghasemi, Behnam Bakhshi', 2024, 'پژوهشنامه اصلاح گیاهان زراعی', NULL, 'http://jcb.sanru.ac.ir/article-1-1529-en.pdf', 'http://jcb.sanru.ac.ir/article-1-1529-en.pdf', NULL, NULL, 24, NULL, 'other', 1, 'open access (DOAJ)', 'Extended Abstract Background: Alfalfa is one of the key fodder plants due to its species diversity and high stress-tolerance range. In addition to producing significant palatable fodder, this plant stabilizes air nitrogen through symbiosis with rhizobium and causes soil fertility in addition to meeting its own needs. For fodder production in the hot and dry region of Sistan as the hub of animal husbandry in the province, it is inevitable to investigate and introduce high-yielding alfalfa cultivars. Therefore, the present research aimed to evaluate tropical alfalfa cultivars and identify high-yielding and more compatible cultivars in terms of yield production and selection of stands with suitable potential for selection. Methods: The phenological, morphological, and functional traits of 10 tropical alfalfa genotypes (Zabol local purified alfalfa, Zabol local mass, Baghdadi, two Afghani masses, Nikshahri, Omid, and lines 473, 472, and 471) were investigated in the Zahak Agricultural and Natural Resources Research Station, located 20 km from Zabol city. An experiment was conducted in a statistical design of randomized complete blocks with three replications during 2017-2018. The bed preparation, including plowing, disk, and leveling, was operated exactly the same for the replications. The distance between the plots in each block was 75 cm, and the distance between the blocks in each replication was 1 m. After preparing the bed on November 15, 2016, furrows were created at a distance of 30 cm (four lines of 6 m) in the plots, and seeds with 95-100% germination capacity were planted at a rate of 15 kg per hectare. Seeds were sown in a row manually by opening grooves to a depth of 1 cm using the method of Hiramkari. During the experiment, the operation consisted of irrigation every 15 days in winter, spring, and summer (once a week) according to the needs. Weeds were mechanically weeded in the early stages of growth. In each year, eight plants were harvested at the 20% flowering stage. Days to greening, days to flowering, plant height, leaf-to-stem percentage, stem diameter, stem number, dry matter percentage, and wet and dry fodder yields were the traits measured during the experiment. At the end of the experiment, data on the fodder yield and morphological and phenological traits of alfalfa cultivars were analyzed using MSTAT-C software. The correlation was calculated using SPSS 16 software. Analysis into principal components and the biplot were done using the Past software. The means of traits were compared with Duncan''s test at the probability level of 5%. Results: The fodder yields were significant among the genotypes at the 1% probability level. The highest average fodder yield (107.589 tons per hectare) was obtained in the Omid cultivar, with greater fodder yield than the other cultivars due to the number of stems, plant height, and stem diameter. Baghdadi alfalfa and Zabul purified alfalfa cultivars ranked next in terms of producing more fodder yield with averages of 103.513 and 102.463 tons per hectare, respectively. The lowest fodder yield was observed in the native mass of Zabul alfalfa with an average of 86.511 tons per hectare. The purified local alfalfa of Zabul showed an increase in yield by 18.43% compared to the native mass. The cultivars were significantly different in dry fodder yield at the probability level of 1%. The highest average dry fodder yield (28.323 tons per hectare) was obtained in the Omid variety. Baghdadi alfalfa and purified Zabul alfalfa ranked next with average yields of 26.419 and 27.322 tons per hectare, respectively. The increased dry fodder yield in alfalfa is considered an advantage because farmers store excess alfalfa in the form of dry fodder for their livestock in winter. The relationship between the examined traits showed that most of the traits were significantly correlated with each other. Fodder yield had a positive and significant correlation with the number of stems per plant and pl', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9851595d-3a55-4a18-a2f1-35acd83bec5d', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Fall harvest management for irrigated alfalfa in southern Saskatchewan', 'Paul G. Jefferson, B. D. Gossen', 1992, 'Canadian Journal of Plant Science', '10.4141/cjps92-144', 'https://doi.org/10.4141/cjps92-144', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps92-144', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('853986ea-d52f-4f38-8f8e-76800196184e', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Gene co-expression analysis of tomato seed maturation reveals tissue-specific regulatory networks and hubs associated with the acquisition of desiccation tolerance and seed vigour', 'Bizouerne E, Buitink J, Vu BL, Vu JL, Esteban E, Pasha A, Provart N, Verdier J', 2021, 'BMC plant biology', '10.1186/s12870-021-02889-8', 'https://doi.org/10.1186/s12870-021-02889-8', 'https://europepmc.org/articles/PMC7923611?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'BackgroundDuring maturation seeds acquire several physiological traits to enable them to survive drying and disseminate the species. Few studies have addressed the regulatory networks controlling acquisition of these traits at the tissue level particularly in endospermic seeds such as tomato, which matures in a fully hydrated environment and does not undergo maturation drying. Using temporal RNA-seq analyses of the different seed tissues during maturation, gene network and trait-based correlations were used to explore the transcriptome signatures associated with desiccation tolerance, longevity, germination under water stress and dormancy.ResultsDuring maturation, 15,173 differentially expressed genes were detected, forming a gene network representing 21 expression modules, with 3 being specific to seed coat and embryo and 5 to the endosperm. A gene-trait significance measure identified a common gene module between endosperm and embryo associated with desiccation tolerance and conserved with non-endospermic seeds. In addition to genes involved in protection such LEA and HSP and ABA response, the module included antioxidant and repair genes. Dormancy was released concomitantly with the increase in longevity throughout fruit ripening until 14 days after the red fruit stage. This was paralleled by an increase in SlDOG1-2 and PROCERA transcripts. The progressive increase in seed vigour was captured by three gene modules, one in common between embryo and endosperm and two tissue-specific. The common module was enriched with genes associated with mRNA processing in chloroplast and mitochondria (including penta- and tetratricopeptide repeat-containing proteins) and post-transcriptional regulation, as well several flowering genes. The embryo-specific module contained homologues of ABI4 and CHOTTO1 as hub genes associated with seed vigour, whereas the endosperm-specific module revealed a diverse set of processes that were related to genome stability, defence against pathogens and ABA/GA response genes.ConclusionThe spatio-temporal co-expression atlas of tomato seed maturation will serve as a valuable resource for the in-depth understanding of the dynamics of gene expression associated with the acquisition of seed vigour at the tissue level.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a13b7ef9-334e-49bc-98fb-4d9917602ccd', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Gene flow in commercial alfalfa (Medicago sativa subsp. sativa L.) seed production fields: Distance is the primary but not the sole influence on adventitious presence', 'Kesoju SR, Kramer M, Brunet J, Greene SL, Jordan A, Martin RC', 2021, 'PloS one', '10.1371/journal.pone.0248746', 'https://doi.org/10.1371/journal.pone.0248746', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7993763.1/PMC7993763.1.pdf', NULL, NULL, 20, NULL, 'northern_plains', 3, 'cc0', 'In insect-pollinated crops, gene flow is affected by numerous factors including crop characteristics, mating system, life history, pollinators, and planting management practices. Previous studies have concentrated on the impact of distance between genetically engineered (GE) and conventional fields on adventitious presence (AP) which represents the unwanted presence of a GE gene. Variables other than distance, however, may affect AP. In addition, some AP is often present in the parent seed lots used to establish conventional fields. To identify variables that influence the proportion of AP in conventional alfalfa fields, we performed variable selection regression analyses. Analyses based on a sample-level and a field-level analysis gave similar, though not identical results. For the sample-level model, distance from the GE field explained 66% of the variance in AP, confirming its importance in affecting AP. The area of GE fields within the pollinator foraging range explained an additional 30% of the variation in AP in the model. The density of alfalfa leafcutting bee domiciles influenced AP in both models. To minimize AP in conventional alfalfa seed fields, management practices should focus on optimizing isolation distances while also considering the size of the GE pollen pool within the pollinator foraging range, and the foraging behavior of pollinators.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4b4de112-5208-45cd-8da9-fbe42141ae4c', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Integrated management of the wheat stem sawfly by exploiting semiochemicals to enhance trap crops', 'Micaela Buteler', 2008, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/1025', 'https://scholarworks.montana.edu/bitstreams/83e77861-c142-447f-827c-83e6d070a0ac/download', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d2fe7e59-5f9c-4e68-8bd4-b948a922aad7', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Genetic Engineering and Genome Editing for Improving Nitrogen Use Efficiency in Plants', 'Lebedev VG, Popova AA, Shestibratov KA', 2021, 'Cells', '10.3390/cells10123303', 'https://doi.org/10.3390/cells10123303', 'https://europepmc.org/articles/PMC8699818?pdf=render', NULL, NULL, 40, NULL, 'other', 1, 'cc by', 'Low nitrogen availability is one of the main limiting factors for plant growth and development, and high doses of N fertilizers are necessary to achieve high yields in agriculture. However, most N is not used by plants and pollutes the environment. This situation can be improved by enhancing the nitrogen use efficiency (NUE) in plants. NUE is a complex trait driven by multiple interactions between genetic and environmental factors, and its improvement requires a fundamental understanding of the key steps in plant N metabolism-uptake, assimilation, and remobilization. This review summarizes two decades of research into bioengineering modification of N metabolism to increase the biomass accumulation and yield in crops. The expression of structural and regulatory genes was most often altered using overexpression strategies, although RNAi and genome editing techniques were also used. Particular attention was paid to woody plants, which have great economic importance, play a crucial role in the ecosystems and have fundamental differences from herbaceous species. The review also considers the issue of unintended effects of transgenic plants with modified N metabolism, e.g., early flowering-a research topic which is currently receiving little attention. The future prospects of improving NUE in crops, essential for the development of sustainable agriculture, using various approaches and in the context of global climate change, are discussed.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('395a8987-f6bd-4d55-89a9-01c2fa3f5588', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Genome-Wide Association Study Reveals Candidate Genes for Flowering Time in Cowpea (Vigna unguiculata [L.] Walp.)', 'Paudel D, Dareus R, Rosenwald J, Muñoz-Amatriaín M, Rios EF', 2021, 'Frontiers in genetics', '10.3389/fgene.2021.667038', 'https://doi.org/10.3389/fgene.2021.667038', 'https://europepmc.org/articles/PMC8242349?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Cowpea (Vigna unguiculata [L.] Walp., diploid, 2n = 22) is a major crop used as a protein source for human consumption as well as a quality feed for livestock. It is drought and heat tolerant and has been bred to develop varieties that are resilient to changing climates. Plant adaptation to new climates and their yield are strongly affected by flowering time. Therefore, understanding the genetic basis of flowering time is critical to advance cowpea breeding. The aim of this study was to perform genome-wide association studies (GWAS) to identify marker trait associations for flowering time in cowpea using single nucleotide polymorphism (SNP) markers. A total of 368 accessions from a cowpea mini-core collection were evaluated in Ft. Collins, CO in 2019 and 2020, and 292 accessions were evaluated in Citra, FL in 2018. These accessions were genotyped using the Cowpea iSelect Consortium Array that contained 51,128 SNPs. GWAS revealed seven reliable SNPs for flowering time that explained 8-12% of the phenotypic variance. Candidate genes including FT, GI, CRY2, LSH3, UGT87A2, LIF2, and HTA9 that are associated with flowering time were identified for the significant SNP markers. Further efforts to validate these loci will help to understand their role in flowering time in cowpea, and it could facilitate the transfer of some of this knowledge to other closely related legume species.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('822a4a96-5f5e-432e-b5c0-52005608e66a', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Genomics-assisted breeding for designing salinity-smart future crops', 'Raza A, Zaman QU, Shabala S, Tester M, Munns R, Hu Z, Varshney RK', 2025, 'Plant biotechnology journal', '10.1111/pbi.70104', 'https://doi.org/10.1111/pbi.70104', 'https://europepmc.org/articles/PMC12310839?pdf=render', NULL, NULL, 33, NULL, 'other', 1, 'cc by', 'Climate change induces many abiotic stresses, including soil salinity, significantly challenging global agriculture. Salinity stress tolerance (SST) is a complex trait, both physiologically and genetically, and is conferred at various levels of plant functional organization. As both the sustainability and profitability of agricultural production systems are critically dependent on SST, plant breeders are trying to design and develop salinity-smart crop plants capable of thriving under high salinity conditions. The accessibility of extreme-quality reference genomes for cultivated crops, naturally salinity-smart plants, and crop wild relatives has fast-tracked the discovery of key genes and quantitative trait loci (QTLs), marker development, genotyping assays and molecular breeding products with improved SST. Employing fast-forward breeding tools, namely genomic selection (GS), haplotype-based breeding (HBB), artificial intelligence (AI) and high-throughput phenotyping (HTP), has shown influence not only for fast-tracking genetic gains but also for reducing the time and cost of developing commercial cultivars with enhanced SST and yield stability. This review discusses the advancement and prospects of various genomics-assisted breeding (GAB) tools, including genome sequencing, QTL mapping, GWAS, GS, HBB, pan-genomics, single-cell/tissue genomics and phenotyping, epigenomics and transgenomics, to exploit the genetic landscape for improving SST. Additionally, we explore the integration of HTP and AI, which demonstrates how these innovative approaches can optimize breeding efficiency and guide large-scale breeding efforts for designing salinity-smart crops to ensure sustainable agriculture and global food security. The collective adoption of these tools suggests bridging the gap between research and field application to deliver stress-smart varieties designed for saline-affected regions worldwide.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.523529+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9651be6-026f-4395-a771-41902588df48', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Green seed coat colour retention in lentil (lens culinaris)', 'Blaine Frederic Davey', 2007, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-12122007-185254', 'https://harvest.usask.ca/bitstreams/edf91c18-a6ed-41a0-b924-eb9de7ba77c4/download', NULL, NULL, 102, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6761505e-4459-4924-86ac-b15d95d3bff8', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Harvest Time Optimization of Pennycress for use Within the Corn-Soybean Rotation', 'Julija A. Cubins', 2019, 'University of Minnesota Digital Conservancy (University of Minnesota)', NULL, 'http://hdl.handle.net/11299/202901', 'http://hdl.handle.net/11299/202901', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eb7565b8-2c47-4803-b0d8-b9313afcf327', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'HARVESTING IRRIGATED ALFALFA IN THE ESTABLISHMENT YEAR IN SOUTHWESTERN SASKATCHEWAN', 'Paul G. Jefferson, R. Byron Irvine, J. D. McELGUNN', 1985, 'Canadian Journal of Plant Science', '10.4141/cjps85-045', 'https://doi.org/10.4141/cjps85-045', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps85-045', NULL, NULL, NULL, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3bfa713c-467c-4c5a-a08c-7d091b4465c3', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Historical agroeconomic analysis of the relationship between commercial pollinator use and Vaccinium angustifolium (Ericales: Ericaceae) yield in Quebec, Canada (2015-2021)', 'Levesque M, McCune F, Fournier V, Giovenazzo P', 2025, 'Journal of economic entomology', '10.1093/jee/toaf242', 'https://doi.org/10.1093/jee/toaf242', 'https://europepmc.org/articles/PMC12698221?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by-nc-nd', 'Lowbush blueberry (Vaccinium angustifolium Ait.) production has the highest export value among all fruit crops in Canada. As blueberry flowers require insect pollination, blueberry farms rely on commercial pollinators to ensure productivity of their fields. Our study aimed to assess the impact of commercial pollinator density and diversity on lowbush blueberry yield using historical data, from 2015 to 2021, across various production contexts. The analysis included 178 blueberry fields, representing approximately 3,000 ha and 11% of Québec''s total crop production area. Data on field size, berry yield, commercial pollinator density/diversity (honey bees; Apis mellifera L. [Hymenoptera: Apidae]), bumble bees; Bombus impatiens Cresson [Hymenoptera: Apidae], and alfalfa leafcutter bees; Megachile rotundata Fabr. [Hymenoptera: Megachilidae]), establishment year, and management system were collected for each field. Additionally, we examined data on honey bee hive strength, landscape structure, and meteorological factors influencing yield. Results showed significant yield increase at certain densities of honey bee hives and frames, bumble bee hives and alfalfa leafcutter bee gallons. The diversity of commercial pollinators used in the fields also increased crop yield. Other key factors influencing lowbush blueberry yield included the year, snow cover during winter, field age, and frost events during pollination. This study clarifies the relationship between commercial pollinators and lowbush blueberry productivity while accounting for several other agroeconomic variables, and demonstrates that increasing managed pollinator density and diversity lead to higher yields for lowbush blueberry growers.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d16087a0-ffc5-46dc-bc38-82d09ed44825', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Identification of Lygus hesperus by DNA barcoding reveals insignificant levels of genetic structure among distant and habitat diverse populations', 'Zhou C, Kandemir I, Walsh DB, Zalom FG, Lavine LC', 2012, 'PloS one', '10.1371/journal.pone.0034528', 'https://doi.org/10.1371/journal.pone.0034528', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC3316671.1/PMC3316671.1.pdf', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc by', 'BackgroundThe western tarnished plant bug Lygus hesperus is an economically important pest that belongs to a complex of morphologically similar species that makes identification problematic. The present study provides evidence for the use of DNA barcodes from populations of L. hesperus from the western United States of America for accurate identification.Methodology/principal findingsThis study reports DNA barcodes for 134 individuals of the western tarnished plant bug from alfalfa and strawberry agricultural fields in the western United States of America. Sequence divergence estimates of Conclusions/significanceThis study reveals that despite wide host plant usage and phenotypically plastic morphological traits, the commonly recognized western tarnished plant bug belongs to a single species, Lygus hesperus. In addition, no significant genetic structure was found for the geographically diverse populations of western tarnished plant bug used in this study.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('941dd2ce-816b-408c-9795-ff12223f2528', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Impact of Seed Maturation on the Morphology, Nutrition, Microbiome Composition and Germinability of Subterranean Clover ( Trifolium subterraneum ) Seeds', 'Sunzid Ahmed, Pankaj Kumar Singh, Jen A. Middleton, David J. Merritt, Sasha Jenkins, Phillip G. H. Nichols', 2025, 'Grass and Forage Science', '10.1111/gfs.12725', 'https://doi.org/10.1111/gfs.12725', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1111/gfs.12725', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by-nc-nd', 'ABSTRACT The annual pasture legume subterranean clover ( Trifolium subterraneum L.; sub clover) plays a crucial role in the agricultural systems of southern Australia and other regions with Mediterranean climates by enhancing pasture quality, nitrogen fixation and biodiversity, contributing to sustainable farming. Sub clover, uniquely characterised by its below‐ground seed development in burrs, has been insufficiently studied regarding the effects of seed maturation on key physiological factors, despite its agricultural significance. This study aimed to explore the effects of seed maturation on morphology, nutrition, microbiome community composition, and germinability in sub clover seeds. Three cultivars, one each from the three sub clover subspecies, were grown in a paddock using a randomised block design. Seed‐bearing burrs were collected at defined developmental and maturity stages, as determined by microscopic analysis and measurements of seed fresh weight and length. Seed nutritional composition was assessed using a macro elemental analyser. Seed microbiome community composition was characterised by sequencing the bacterial 16S rRNA gene and the fungal ITS2 region. Seed germinability was evaluated based on radicle emergence and length following 14 days of incubation. Across all cultivars, seed maturation was characterised by progressive increases in seed length and weight, accompanied by dynamic changes in nutrient composition. While some nutrients showed consistent declines, others exhibited increasing trends as seeds matured. The seed microbiome community compositions were influenced by both developmental stage and cultivar type. Seed germinability decreased from 37 to 43 days post‐anthesis, as hardseededness increased. This study provides insights into the dynamic interplay of morphological traits, nutritional composition, microbial community composition, and germinability during the maturation of sub clover seeds.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6e9b53a6-8d41-479c-9732-ce41379023a7', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Improving nutrition through biofortification-A systematic review', 'Ofori KF, Antoniello S, English MM, Aryee ANA', 2022, 'Frontiers in nutrition', '10.3389/fnut.2022.1043655', 'https://doi.org/10.3389/fnut.2022.1043655', 'https://europepmc.org/articles/PMC9784929?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Nutritious foods are essential for human health and development. However, malnutrition and hidden hunger continue to be a challenge globally. In most developing countries, access to adequate and nutritious food continues to be a challenge. Although hidden hunger is less prevalent in developed countries compared to developing countries where iron (Fe) and zinc (Zn) deficiencies are common. The United Nations (UN) 2nd Sustainable Development Goal was set to eradicate malnutrition and hidden hunger. Hidden hunger has led to numerous cases of infant and maternal mortalities, and has greatly impacted growth, development, cognitive ability, and physical working capacity. This has influenced several countries to develop interventions that could help combat malnutrition and hidden hunger. Interventions such as dietary diversification and food supplementation are being adopted. However, fortification but mainly biofortification has been projected to be the most sustainable solution to malnutrition and hidden hunger. Plant-based foods (PBFs) form a greater proportion of diets in certain populations; hence, fortification of PBFs is relevant in combating malnutrition and hidden hunger. Agronomic biofortification, plant breeding, and transgenic approaches are some currently used strategies in food crops. Crops such as cereals, legumes, oilseeds, vegetables, and fruits have been biofortified through all these three strategies. The transgenic approach is sustainable, efficient, and rapid, making it suitable for biofortification programs. Omics technology has also been introduced to improve the efficiency of the transgenic approach.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5b37e75b-0e99-4e0c-ad96-597e4f9ccdc7', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Improving the Yield and Nutritional Quality of Forage Crops', 'Capstaff NM, Miller AJ', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00535', 'https://doi.org/10.3389/fpls.2018.00535', 'https://europepmc.org/articles/PMC5928394?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Despite being some of the most important crops globally, there has been limited research on forages when compared with cereals, fruits, and vegetables. This review summarizes the literature highlighting the significance of forage crops, the current improvements and some of future directions for improving yield and nutritional quality. We make the point that the knowledge obtained from model plant and grain crops can be applied to forage crops. The timely development of genomics and bioinformatics together with genome editing techniques offer great scope to improve forage crops. Given the social, environmental and economic importance of forage across the globe and especially in poorer countries, this opportunity has enormous potential to improve food security and political stability.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fab81573-1b6d-43ae-ba4d-0ddaa004f0a5', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Integration of Plant Defense Traits with Biological Control of Arthropod Pests: Challenges and Opportunities', 'Peterson JA, Ode PJ, Oliveira-Hofman C, Harwood JD', 2016, 'Frontiers in plant science', '10.3389/fpls.2016.01794', 'https://doi.org/10.3389/fpls.2016.01794', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC5129739.1/PMC5129739.1.pdf', NULL, NULL, 24, NULL, 'northern_plains', 3, 'cc by', 'Crop plants exhibit a wide diversity of defensive traits and strategies to protect themselves from damage by herbivorous pests and disease. These defensive traits may be naturally occurring or artificially selected through crop breeding, including introduction via genetic engineering. While these traits can have obvious and direct impacts on herbivorous pests, many have profound effects on higher trophic levels, including the natural enemies of herbivores. Multi-trophic effects of host plant resistance have the potential to influence, both positively and negatively, biological control. Plant defense traits can influence both the numerical and functional responses of natural enemies; these interactions can be semiochemically, plant toxin-, plant nutrient-, and/or physically mediated. Case studies involving predators, parasitoids, and pathogens of crop pests will be presented and discussed. These diverse groups of natural enemies may respond differently to crop plant traits based on their own unique biology and the ecological niches they fill. Genetically modified crop plants that have been engineered to express transgenic products affecting herbivorous pests are an additional consideration. For the most part, transgenic plant incorporated protectant (PIP) traits are compatible with biological control due to their selective toxicity to targeted pests and relatively low non-target impacts, although transgenic crops may have indirect effects on higher trophic levels and arthropod communities mediated by lower host or prey number and/or quality. Host plant resistance and biological control are two of the key pillars of integrated pest management; their potential interactions, whether they are synergistic, complementary, or disruptive, are key in understanding and achieving sustainable and effective pest management.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('45533d4c-d11a-45ac-b8d8-e36397b35cae', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'IRRIGATION MANAGEMENT OF ALFALFA FOR SEED', 'K. K. Krogman, E. H. Hobbs', 1977, 'Canadian Journal of Plant Science', '10.4141/cjps77-128', 'https://doi.org/10.4141/cjps77-128', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps77-128', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bde90fba-7614-4762-9cda-d074bd67de61', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Isolation Distances for Transgenic Alfalfa Seed Production in the Pacific Northwest', 'Sandya R. Kesoju, Stephanie L. Greene, Ruth C. Martin, Matthew Kramer, Douglas B. Walsh, Rick A. Boydston', 2019, 'Crop Science', '10.2135/cropsci2018.07.0414', 'https://doi.org/10.2135/cropsci2018.07.0414', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.2135/cropsci2018.07.0414', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'ABSTRACT Alfalfa (Medicago sativa L.) was the first perennial crop genetically engineered (GE) to resist glyphosate herbicide. Since alfalfa is insect pollinated, the potential for transgene flow and occurrence of adventitious presence (AP) in conventional varieties is a concern, especially for organic and export producers. In response, the industry developed seed production isolation distances. However, no landscape‐scale studies have been conducted to validate industry standards. Our objective was to quantify the extent of gene movement from GE seed fields to commercial conventional seed fields on a landscape level to provide the industry with information to support coexistence strategies. Alfalfa seed fields were mapped in the Touchet area, Walla Walla Valley, Washington, during spring 2013. Fourteen conventional seed fields located at various distances from GE sources were identified, harvested, and tested for the presence of the GE trait. Although other variables affect gene flow, this article focuses on geographic distance, since this variable can be easily controlled by growers and industry. Using distance as the predictor variable, we modeled the relationship between AP proportion and distance to GE source fields at 0.1, 0.5, and 0.9% AP threshold levels using quadratic regression. As distance increased, transgene flow generally decreased. At a threshold level of 0.9% AP, an isolation distance of 330 m between conventional and GE fields is needed to ensure that at least 95% of the samples fall below this threshold level. Spatial prediction maps were consistent with our statistical analysis. At an average distance of 2.2 km, AP was 0.05%, and this decreased to 0.03% at an average distance of 8.8 km from GE seed fields.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44e0b2a5-8a64-41cb-90a0-5e0577096628', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Key Global Actions for Mycotoxin Management in Wheat and Other Small Grains', 'Leslie JF, Moretti A, Mesterházy Á, Ameye M, Audenaert K, Singh PK, Richard-Forget F, Chulze SN', 2021, 'Toxins', '10.3390/toxins13100725', 'https://doi.org/10.3390/toxins13100725', 'https://europepmc.org/articles/PMC8541216?pdf=render', NULL, NULL, 48, NULL, 'other', 1, 'cc by', 'Mycotoxins in small grains are a significant and long-standing problem. These contaminants may be produced by members of several fungal genera, including Alternaria, Aspergillus, Fusarium, Claviceps, and Penicillium. Interventions that limit contamination can be made both pre-harvest and post-harvest. Many problems and strategies to control them and the toxins they produce are similar regardless of the location at which they are employed, while others are more common in some areas than in others. Increased knowledge of host-plant resistance, better agronomic methods, improved fungicide management, and better storage strategies all have application on a global basis. We summarize the major pre- and post-harvest control strategies currently in use. In the area of pre-harvest, these include resistant host lines, fungicides and their application guided by epidemiological models, and multiple cultural practices. In the area of post-harvest, drying, storage, cleaning and sorting, and some end-product processes were the most important at the global level. We also employed the Nominal Group discussion technique to identify and prioritize potential steps forward and to reduce problems associated with human and animal consumption of these grains. Identifying existing and potentially novel mechanisms to effectively manage mycotoxin problems in these grains is essential to ensure the safety of humans and domesticated animals that consume these grains.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a138eeb7-793a-4537-a753-2d4bfe4fbc82', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Managing Floral Resources in Apple Orchards for Pest Control: Ideas, Experiences and Future Directions', 'Herz A, Cahenzli F, Penvern S, Pfiffner L, Tasin M, Sigsgaard L', 2019, 'Insects', '10.3390/insects10080247', 'https://doi.org/10.3390/insects10080247', 'https://europepmc.org/articles/PMC6723448?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Functional biodiversity is of fundamental importance for pest control. Many natural enemies rely on floral resources to complete their life cycle. Farmers need to ensure the availability of suitable and sufficient floral biodiversity. This review summarizes 66 studies on the management of floral biodiversity in apple orchards, published since 1986. Approaches followed different degrees of intervention: short-term practices (mowing regime and weed maintenance, cover crops), establishment of durable ecological infrastructures (perennial flower strips, hedgerows) and re-design of the crop system (intercropping, agroforestry). Although short-term practices did not always target the nutrition of natural enemies by flowering plants, living conditions for them (alternative prey, provision of habitat) were often improved. Perennial flower strips reliably enhanced natural enemies and techniques for their introduction continuously developed. Resident natural enemies and their impact in pest control reacted positively to the introduction of a more diversified vegetation, whereas the response of very mobile organisms was often not directly linked to the measures taken. A careful selection and management of plants with particular traits exploitable by most natural enemies emerged as a key-point for success. Now the elaborated design of such measures needs to be adopted by stakeholders and policy makers to encourage farmers to implement these measures in their orchards.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('509089c3-91a0-4efe-aa8e-70e2476f4921', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Metagenomic Studies of Viruses in Weeds and Wild Plants: A Powerful Approach to Characterise Variable Virus Communities', 'Hasiów-Jaroszewska B, Boezen D, Zwart MP', 2021, 'Viruses', '10.3390/v13101939', 'https://doi.org/10.3390/v13101939', 'https://europepmc.org/articles/PMC8539035?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'High throughput sequencing (HTS) has revolutionised virus detection and discovery, allowing for the untargeted characterisation of whole viromes. Viral metagenomics studies have demonstrated the ubiquity of virus infection - often in the absence of disease symptoms - and tend to discover many novel viruses, highlighting the small fraction of virus biodiversity described to date. The majority of the studies using high-throughput sequencing to characterise plant viromes have focused on economically important crops, and only a small number of studies have considered weeds and wild plants. Characterising the viromes of wild plants is highly relevant, as these plants can affect disease dynamics in crops, often by acting as viral reservoirs. Moreover, the viruses in unmanaged systems may also have important effects on wild plant populations and communities. Here, we review metagenomic studies on weeds and wild plants to show the benefits and limitations of this approach and identify knowledge gaps. We consider key genomics developments that are likely to benefit the field in the near future. Although only a small number of HTS studies have been performed on weeds and wild plants, these studies have already discovered many novel viruses, demonstrated unexpected trends in virus distributions, and highlighted the potential of metagenomics as an approach.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f36116c7-71b8-4f01-84bd-aa33b01b69a9', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Mitigating tradeoffs in plant breeding', 'Dwivedi SL, Reynolds MP, Ortiz R', 2021, 'iScience', '10.1016/j.isci.2021.102965', 'https://doi.org/10.1016/j.isci.2021.102965', 'https://europepmc.org/articles/PMC8384922?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Tradeoffs among plant traits help maintain relative fitness under unpredictable conditions and maximize reproductive success. However, modifying tradeoffs is a breeding challenge since many genes of minor effect are involved. The intensive crosstalk and fine-tuning between growth and defense responsive phytohormones via transcription factors optimizes growth, reproduction, and stress tolerance. There are regulating genes in grain crops that deploy diverse functions to overcome tradeoffs, e.g., miR-156-IPA1 regulates crosstalk between growth and defense to achieve high disease resistance and yield, while OsALDH2B1 loss of function causes imbalance among defense, growth, and reproduction in rice. GNI-A1 regulates seed number and weight in wheat by suppressing distal florets and altering assimilate distribution of proximal seeds in spikelets. Knocking out ABA-induced transcription repressors (AITRs) enhances abiotic stress adaptation without fitness cost in Arabidopsis. Deploying AITRs homologs in grain crops may facilitate breeding. This knowledge suggests overcoming tradeoffs through breeding may expose new ones.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87eb8a9f-47dd-499c-a1f3-0c921450849c', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Multifaceted impacts of nanoparticles on plant nutrient absorption and soil microbial communities', 'Zhang H, Zheng T, Wang Y, Li T, Chi Q', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1497006', 'https://doi.org/10.3389/fpls.2024.1497006', 'https://europepmc.org/articles/PMC11600800?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'With the growth of the global population and the increasing scarcity of resources, the sustainability and efficiency improvement of agricultural production have become urgent needs. The rapid development of nanotechnology provides new solutions to this challenge, especially the application of nanoparticles in agriculture, which is gradually demonstrating its unique advantages and broad prospects. Nonetheless, various nanoparticles can influence plant growth in diverse manners, often through distinct mechanisms of action. Beyond their direct effects on the plant itself, they frequently alter the physicochemical properties of the soil and modulate the structure of microbial communities in the rhizosphere. This review focuses intently on the diverse methods through which nanoparticles can modulate plant growth, delving deeply into the interactions between nanoparticles and plants, as well as nanoparticles with soil and microbial communities. The aim is to offer a comprehensive reference for the utilization of functionalized nanoparticles in the agricultural sector.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e5bb10f-4f62-4d77-8826-e745a049037c', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Neonicotinoid-contaminated pollinator strips adjacent to cropland reduce honey bee nutritional status', 'Mogren CL, Lundgren JG', 2016, 'Scientific reports', '10.1038/srep29608', 'https://doi.org/10.1038/srep29608', 'https://europepmc.org/articles/PMC4944152?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Worldwide pollinator declines are attributed to a number of factors, including pesticide exposures. Neonicotinoid insecticides specifically have been detected in surface waters, non-target vegetation, and bee products, but the risks posed by environmental exposures are still not well understood. Pollinator strips were tested for clothianidin contamination in plant tissues, and the risks to honey bees assessed. An enzyme-linked immunosorbent assay (ELISA) quantified clothianidin in leaf, nectar, honey, and bee bread at organic and seed-treated farms. Total glycogen, lipids, and protein from honey bee workers were quantified. The proportion of plants testing positive for clothianidin were the same between treatments. Leaf tissue and honey had similar concentrations of clothianidin between organic and seed-treated farms. Honey (mean±SE: 6.61 ± 0.88 ppb clothianidin per hive) had seven times greater concentrations than nectar collected by bees (0.94 ± 0.09 ppb). Bee bread collected from organic sites (25.8 ± 3.0 ppb) had significantly less clothianidin than those at seed treated locations (41.6 ± 2.9 ppb). Increasing concentrations of clothianidin in bee bread were correlated with decreased glycogen, lipid, and protein in workers. This study shows that small, isolated areas set aside for conservation do not provide spatial or temporal relief from neonicotinoid exposures in agricultural regions where their use is largely prophylactic.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('52dcab84-d9e2-4c0c-a9b9-e566afd62471', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Nesting cavity diameter has implications for management of the alfalfa leafcutting bee (Hymenoptera: Megachilidae)', 'Joshua D Rinehart, Courtney C. Grula, Joseph P. Rinehart, Julia H. Bowsher', 2023, 'Journal of Economic Entomology', '10.1093/jee/toad207', 'https://doi.org/10.1093/jee/toad207', 'https://academic.oup.com/jee/advance-article-pdf/doi/10.1093/jee/toad207/53478078/toad207.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Body size influences performance in many bee species and may be influenced by nesting cavity diameter in cavity-nesting bees. Megachile rotundata (Fabricius) (Hymenoptera: Megachilidae) is a commercially-managed, solitary cavity-nesting bee. In M. rotundata body size has low heritability and is strongly influenced by the size of the larval provision and the diameter of the nesting cavity. Commercial nesting boxes have cavities that are 7 mm in diameter. Our goal was to examine the effects that nesting cavity diameter has on M. rotundata body size and performance by manipulating the size of cavities that are available for nesting. We provided bees with nesting cavities that ranged in size from 4 to 9 millimeters in 1 mm increments. To assess body size we measured mass and intertegular span. To assess performance we measured wing area, wing loading, sex, overwintering survival, pollen ball occurrence, and diapause status in the offspring. We also examined the reproductive output from the different nest cavity diameters. We found that the 8 mm cavities reared bees with the largest mass, and 4 mm cavities reared bees with the smallest mass. We determined that the 7 mm nesting cavity is optimal for offspring yield, the 8 mm nesting cavity is optimal for performance, and the 5 mm nesting cavity may be optimal for conservation efforts of other cavity-nesting bees. Based on the desired outcome of the bee managers, nest sizes differing from the standard may provide an advantage.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3bb7cd02-5a71-4f59-9102-50ef0dc3690d', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Niger Response to Nitrogen and Seeding Depth in the Northern Great Plains', 'William Earl May, M. Wood, Karelia Del Piero', 2019, 'Agronomy Journal', '10.2134/agronj2018.08.0541', 'https://doi.org/10.2134/agronj2018.08.0541', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.2134/agronj2018.08.0541', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by-nc-nd', 'Core Ideas Determine the effect of nitrogen fertilizer and seeding depth on the development and yield of niger. There was a linear increase in grain yield, 76 kg ha–1 as the N rate increased from to 10 to 110 kg N ha–1. Seeding depth impacted plant density and visible row, but the niger compensated and grain yield was not affected by seeding depth. A niger (Guizotia abyssinica (L.f.) Cass.) cultivar has been selected to grow on the Northern Great Plains of North America; however, agronomic management practices in a no‐till cropping system regarding seeding depth and nitrogen (N) fertilization have yet to be developed for this region. Two experiments were conducted at Indian Head, SK, Canada from 2011 to 2017 to determine the response of niger to varying N fertilizer rates and seeding depths. Five rates of N (10, 35, 60, 85, and 110 kg N ha−1) and four seeding depths (surface, 0.6, 1.27, and 2.5 cm below soil surface) were applied in separate single factor experiments. Nitrogen fertilizer rate affected niger development. As N rate increased, there was a linear delay in the appearance of visible rows. Plant height and kernel weight were affected by N rate and year, grain yield was affected by year, and there was a linear increase of 18% in grain yield as the N rate increased from 10 to 110 kg N ha−1. Niger plant density was affected by seeding depth, where plant density increased linearly with decreasing seeding depth in 2014, 2015, and 2017, while there was a negative quadratic relationship in 2016. This effect on plant density did not impact grain yield. In conclusion, niger grain yield benefitted from increased levels of N fertilizer and that growers can use a wide range of seeding depths to place niger seed in soil moist enough to support germination and emergence.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f9e22a9a-40a2-4c02-beb5-f5065f323e79', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Nitrate Uptake and Use Efficiency: Pros and Cons of Chloride Interference in the Vegetable Crops', 'Carillo P, Rouphael Y', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.899522', 'https://doi.org/10.3389/fpls.2022.899522', 'https://europepmc.org/articles/PMC9244799?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Over the past five decades, nitrogen (N) fertilization has been an essential tool for boosting crop productivity in agricultural systems. To avoid N pollution while preserving the crop yields and profit margins for farmers, the scientific community is searching for eco-sustainable strategies aimed at increasing plants'' nitrogen use efficiency (NUE). The present article provides a refined definition of the NUE based on the two important physiological factors (N-uptake and N-utilization efficiency). The diverse molecular and physiological mechanisms underlying the processes of N assimilation, translocation, transport, accumulation, and reallocation are revisited and critically discussed. The review concludes by examining the N uptake and NUE in tandem with chloride stress and eustress, the latter being a new approach toward enhancing productivity and functional quality of the horticultural crops, particularly facilitated by soilless cultivation.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fb7150df-1027-4c83-a8ed-b2df0369deca', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Nutritional Aspects of Ecologically Relevant Phytochemicals in Ruminant Production', 'Tedeschi LO, Muir JP, Naumann HD, Norris AB, Ramírez-Restrepo CA, Mertens-Talcott SU', 2021, 'Frontiers in veterinary science', '10.3389/fvets.2021.628445', 'https://doi.org/10.3389/fvets.2021.628445', 'https://europepmc.org/articles/PMC7973208?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'This review provides an update of ecologically relevant phytochemicals for ruminant production, focusing on their contribution to advancing nutrition. Phytochemicals embody a broad spectrum of chemical components that influence resource competence and biological advantage in determining plant species'' distribution and density in different ecosystems. These natural compounds also often act as plant defensive chemicals against predatorial microbes, insects, and herbivores. They may modulate or exacerbate microbial transactions in the gastrointestinal tract and physiological responses in ruminant microbiomes. To harness their production-enhancing characteristics, phytochemicals have been actively researched as feed additives to manipulate ruminal fermentation and establish other phytochemoprophylactic (prevent animal diseases) and phytochemotherapeutic (treat animal diseases) roles. However, phytochemical-host interactions, the exact mechanism of action, and their effects require more profound elucidation to provide definitive recommendations for ruminant production. The majority of phytochemicals of nutritional and pharmacological interest are typically classified as flavonoids (9%), terpenoids (55%), and alkaloids (36%). Within flavonoids, polyphenolics (e.g., hydrolyzable and condensed tannins) have many benefits to ruminants, including reducing methane (CH4) emission, gastrointestinal nematode parasitism, and ruminal proteolysis. Within terpenoids, saponins and essential oils also mitigate CH4 emission, but triterpenoid saponins have rich biochemical structures with many clinical benefits in humans. The anti-methanogenic property in ruminants is variable because of the simultaneous targeting of several physiological pathways. This may explain saponin-containing forages'' relative safety for long-term use and describe associated molecular interactions on all ruminant metabolism phases. Alkaloids are N-containing compounds with vast pharmacological properties currently used to treat humans, but their phytochemical usage as feed additives in ruminants has yet to be exploited as they may act as ghost compounds alongside other phytochemicals of known importance. We discussed strategic recommendations for phytochemicals to support sustainable ruminant production, such as replacements for antibiotics and anthelmintics. Topics that merit further examination are discussed and include the role of fresh forages vis-à-vis processed feeds in confined ruminant operations. Applications and benefits of phytochemicals to humankind are yet to be fully understood or utilized. Scientific explorations have provided promising results, pending thorough vetting before primetime use, such that academic and commercial interests in the technology are fully adopted.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6a68f175-ef56-4906-8ee8-ebd2caa67490', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Phytobeneficial and salt stress mitigating efficacy of IAA producing salt tolerant strains in Gossypium hirsutum', 'Saleem S, Iqbal A, Ahmed F, Ahmad M', 2021, 'Saudi journal of biological sciences', '10.1016/j.sjbs.2021.05.056', 'https://doi.org/10.1016/j.sjbs.2021.05.056', 'https://europepmc.org/articles/PMC8381066?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by-nc-nd', 'Salinity is one of the major agricultural concern that significantly limits the crop productivity. The plant growth promoting rhizobacteria (PGPR) may contribute in sustainable crop production under salt stress. The current study was designed to isolate the Indole Acetic Acid (IAA) producing salt tolerant PGPR to promote the growth of cotton (Gossypium hirsutum, FH-142) and induce its salt stress tolerance. Ten Salt Tolerant (ST) bacterial strains were screened for their PGP trait in vitro and evaluated for their beneficial effect on cotton plants growth by plant-microbe interaction assay in lab and under natural condition. GC-MS analysis of the metabolites of the selected bacterial strains confirmed the presence of indolic compounds like indole, indole-3-butyramide, benzylmalonic acid and 4-methyl-2-pyrrolidinone. The bacterial isolates ST4, ST5, ST6, ST15, ST16, ST17, ST18, ST20, ST22 and ST25 were identified as Bacillus sp., B. sonorensis, B. cereus, B. subtilis, Brevibacillus sp. B. safensis, B. paramycoides, Bacillus sp., B. cereus and B. tequilensis respectively on the basis of 16S rDNA sequencing. Bacteria inoculated plants had a significant (P + (28%) and decreased the uptake of Na+ (58%) from soil in plants under salt stress over control in pot experiment. These ST PGPR have the potential to act as plant defense agents by enhancing plant growth, productivity, and tolerance in saline environment.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fc048d49-0eef-4def-bb1c-738e10f22f96', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Plant Breeding for Intercropping in Temperate Field Crop Systems: A Review', 'Moore VM, Schlautman B, Fei SZ, Roberts LM, Wolfe M, Ryan MR, Wells S, Lorenz AJ', 2022, 'Frontiers in plant science', '10.3389/fpls.2022.843065', 'https://doi.org/10.3389/fpls.2022.843065', 'https://europepmc.org/articles/PMC9009171?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Monoculture cropping systems currently dominate temperate agroecosystems. However, intercropping can provide valuable benefits, including greater yield stability, increased total productivity, and resilience in the face of pest and disease outbreaks. Plant breeding efforts in temperate field crops are largely focused on monoculture production, but as intercropping becomes more widespread, there is a need for cultivars adapted to these cropping systems. Cultivar development for intercropping systems requires a systems approach, from the decision to breed for intercropping systems through the final stages of variety testing and release. Design of a breeding scheme should include information about species variation for performance in intercropping, presence of genotype × management interaction, observation of key traits conferring success in intercropping systems, and the specificity of intercropping performance. Together this information can help to identify an optimal selection scheme. Agronomic and ecological knowledge are critical in the design of selection schemes in cropping systems with greater complexity, and interaction with other researchers and key stakeholders inform breeding decisions throughout the process. This review explores the above considerations through three case studies: (1) forage mixtures, (2) perennial groundcover systems (PGC), and (3) soybean-pennycress intercropping. We provide an overview of each cropping system, identify relevant considerations for plant breeding efforts, describe previous breeding focused on the cropping system, examine the extent to which proposed theoretical approaches have been implemented in breeding programs, and identify areas for future development.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('acc96146-013d-4e26-b4f5-ed5f905b9989', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'UV reflectance in crop remote sensing: Assessing the current state of knowledge and extending research with strawberry cultivars', 'Heath M, St-Onge D, Hausler R', 2024, 'PloS one', '10.1371/journal.pone.0285912', 'https://doi.org/10.1371/journal.pone.0285912', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10962828.1/PMC10962828.1.pdf', NULL, NULL, 19, NULL, 'canada', 3, 'cc by', 'Remote sensing of spectral reflectance is a crucial parameter in precision agriculture. In particular, the visual color produced from reflected light can be used to determine plant health (VIS-IR) or attract pollinators (Near-UV). However, the UV spectral reflectance studies largely focus on non-crop plants, even though they provide essential information for plant-pollinator interactions. This literature review presents an overview of UV-reflectance in crops, identifies gaps in the literature, and contributes new data based on strawberry cultivars. The study found that most crop spectral reflectance studies relied on lab-based methodologies and examined a wide spectral range (Near UV to IR). Moreover, the plant family distribution largely mirrored global food market trends. Through a spectral comparison of white flowering strawberry cultivars, this study discovered visual differences for pollinators in the Near UV and Blue ranges. The variation in pollinator visibility within strawberry cultivars underscores the importance of considering UV spectral reflectance when developing new crop breeding lines and managing pollinator preferences in agricultural fields.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa4bbc6d-23b7-4001-af72-4c8f4f55ca68', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Plant Coping with Cold Stress: Molecular and Physiological Adaptive Mechanisms with Future Perspectives', 'Feng Y, Li Z, Kong X, Khan A, Ullah N, Zhang X', 2025, 'Cells', '10.3390/cells14020110', 'https://doi.org/10.3390/cells14020110', 'https://europepmc.org/articles/PMC11764090?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'Cold stress strongly hinders plant growth and development. However, the molecular and physiological adaptive mechanisms of cold stress tolerance in plants are not well understood. Plants adopt several morpho-physiological changes to withstand cold stress. Plants have evolved various strategies to cope with cold stress. These strategies included changes in cellular membranes and chloroplast structure, regulating cold signals related to phytohormones and plant growth regulators (ABA, JA, GA, IAA, SA, BR, ET, CTK, and MET), reactive oxygen species (ROS), protein kinases, and inorganic ions. This review summarizes the mechanisms of how plants respond to cold stress, covering four main signal transduction pathways, including the abscisic acid (ABA) signal transduction pathway, Ca2+ signal transduction pathway, ROS signal transduction pathway, and mitogen-activated protein kinase (MAPK/MPK) cascade pathway. Some transcription factors, such as AP2/ERF, MYB, WRKY, NAC, and bZIP, not only act as calmodulin-binding proteins during cold perception but can also play important roles in the downstream chilling-signaling pathway. This review also highlights the analysis of those transcription factors such as bHLH, especially bHLH-type transcription factors ICE, and discusses their functions as phytohormone-responsive elements binding proteins in the promoter region under cold stress. In addition, a theoretical framework outlining plant responses to cold stress tolerance has been proposed. This theory aims to guide future research directions and inform agricultural production practices, ultimately enhancing crop resilience to cold stress.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('88e39cc0-4604-454f-85fb-2c6314edb794', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Pod Shattering: A Homologous Series of Variation Underlying Domestication and an Avenue for Crop Improvement', 'Ezgi Ogutcen, Anamika Pandey, Mohd. Kamran Khan, Edward Marques, Ramachandra Varma Penmetsa, Abdullah Kahraman, Eric von Wettberg', 2018, 'Agronomy', '10.3390/agronomy8080137', 'https://doi.org/10.3390/agronomy8080137', 'https://www.mdpi.com/2073-4395/8/8/137/pdf?version=1533535598', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'In wild habitats, fruit dehiscence is a critical strategy for seed dispersal; however, in cultivated crops it is one of the major sources of yield loss. Therefore, indehiscence of fruits, pods, etc., was likely to be one of the first traits strongly selected in crop domestication. Even with the historical selection against dehiscence in early domesticates, it is a trait still targeted in many breeding programs, particularly in minor or underutilized crops. Here, we review dehiscence in pulse (grain legume) crops, which are of growing importance as a source of protein in human and livestock diets, and which have received less attention than cereal crops and the model plant Arabidopsis thaliana. We specifically focus on the (i) history of indehiscence in domestication across legumes, (ii) structures and the mechanisms involved in shattering, (iii) the molecular pathways underlying this important trait, (iv) an overview of the extent of crop losses due to shattering, and the effects of environmental factors on shattering, and, (v) efforts to reduce shattering in crops. While our focus is mainly pulse crops, we also included comparisons to crucifers and cereals because there is extensive research on shattering in these taxa.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('821d1751-28c3-4339-843c-105fc09be1cd', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Recruitment of the rhizo-microbiome army: assembly determinants and engineering of the rhizosphere microbiome as a key to unlocking plant potential', 'Park I, Seo YS, Mannaa M', 2023, 'Frontiers in microbiology', '10.3389/fmicb.2023.1163832', 'https://doi.org/10.3389/fmicb.2023.1163832', 'https://europepmc.org/articles/PMC10196466?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'The viable community of microorganisms in the rhizosphere significantly impacts the physiological development and vitality of plants. The assembly and functional capacity of the rhizosphere microbiome are greatly influenced by various factors within the rhizosphere. The primary factors are the host plant genotype, developmental stage and status, soil properties, and resident microbiota. These factors drive the composition, dynamics, and activity of the rhizosphere microbiome. This review addresses the intricate interplay between these factors and how it facilitates the recruitment of specific microbes by the host plant to support plant growth and resilience under stress. This review also explores current methods for engineering and manipulating the rhizosphere microbiome, including host plant-mediated manipulation, soil-related methods, and microbe-mediated methods. Advanced techniques to harness the plant''s ability to recruit useful microbes and the promising use of rhizo-microbiome transplantation are highlighted. The goal of this review is to provide valuable insights into the current knowledge, which will facilitate the development of cutting-edge strategies for manipulating the rhizosphere microbiome for enhanced plant growth and stress tolerance. The article also indicates promising avenues for future research in this field.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a7dd25cb-d597-4dea-96f6-3d1c9dcbfe12', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Reduced tillage in organic cropping systems on the Canadian prairies', 'Clare Sullivan', 2012, 'HARVEST (University of Saskatchewan)', NULL, 'https://hdl.handle.net/10388/ETD-2012-02-376', 'https://harvest.usask.ca/bitstreams/d955a33c-477f-45b5-bee4-5ae732314b85/download', NULL, NULL, 153, NULL, 'alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('adfcd0ac-186b-4919-bc26-cf4ba31acb3d', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Reducing Drought Stress in Plants by Encapsulating Plant Growth-Promoting Bacteria with Polysaccharides', 'Saberi Riseh R, Ebrahimi-Zarandi M, Gholizadeh Vazvani M, Skorik YA', 2021, 'International journal of molecular sciences', '10.3390/ijms222312979', 'https://doi.org/10.3390/ijms222312979', 'https://europepmc.org/articles/PMC8657635?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Drought is a major abiotic stress imposed by climate change that affects crop production and soil microbial functions. Plants respond to water deficits at the morphological, biochemical, and physiological levels, and invoke different adaptation mechanisms to tolerate drought stress. Plant growth-promoting bacteria (PGPB) can help to alleviate drought stress in plants through various strategies, including phytohormone production, the solubilization of mineral nutrients, and the production of 1-aminocyclopropane-1-carboxylate deaminase and osmolytes. However, PGPB populations and functions are influenced by adverse soil factors, such as drought. Therefore, maintaining the viability and stability of PGPB applied to arid soils requires that the PGPB have to be protected by suitable coatings. The encapsulation of PGPB is one of the newest and most efficient techniques for protecting beneficial bacteria against unfavorable soil conditions. Coatings made from polysaccharides, such as sodium alginate, chitosan, starch, cellulose, and their derivatives, can absorb and retain substantial amounts of water in the interstitial sites of their structures, thereby promoting bacterial survival and better plant growth.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('99799ee1-c476-4e8e-8ba9-988541ac2902', '034f2e0c-466b-4b66-b649-a70d2a2f40af', 'Vitamin E Is Essential for Seed Longevity and for Preventing Lipid Peroxidation during Germination', 'Scott E. Sattler, Laura U. Gilliland, Maria Magallanes‐Lundback, Mike Pollard, Dean DellaPenna', 2004, 'The Plant Cell', '10.1105/tpc.021360', 'https://doi.org/10.1105/tpc.021360', 'https://academic.oup.com/plcell/article-pdf/16/6/1419/35430574/plcell_v16_6_1419.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.945525+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('991fa6e8-886c-4691-b399-441871526b1b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Role of alfalfa leafcutter bee associated microflora in chalkbrood disease', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/role-of-alfalfa-leafcutter-bee-associated-microflora-in-chalkbrood-disease', 'https://open.alberta.ca/dataset/6e3ae97c-1bb4-4e3a-8401-1171a6d5fb73/resource/b897e9fc-946d-455e-8605-1923c7df972f/download/163003316151-role-of-alfalfa-leafcutter-bee-associated-microflora-in-chalkbrood-disease.pdf', NULL, NULL, 118, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study examined the role of microorganisms in the alimentary tract of alfalfa leafcutter bee (Megachile rotundata) larvae and their association with chalkbrood disease caused by Ascosphaera aggregata. Researchers found that while microflora diversity decreased after larval ingestion, bacteria and filamentous fungi populations were higher in larvae developing chalkbrood than in healthy larvae. Experimental results showed that indigenous microflora did not reduce chalkbrood incidence and may even slightly stimulate it, with Bacillus brevis and Streptomyces sp. increasing disease incidence significantly. Gamma irradiation effectively sterilized provisions and reduced bacteria, but the elimination of microflora had no detrimental effect on larval health. Overall, microorganisms associated with alfalfa leafcutter bees had no or minimal impact on chalkbrood, and removing them should not harm the bees.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3c521e6d-041e-4f29-aeb4-2257908edd88', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Water Content of Plant Tissues: So Simple That Almost Forgotten?', 'Ievinsh G', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12061238', 'https://doi.org/10.3390/plants12061238', 'https://europepmc.org/articles/PMC10058729?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'The aim of the present review was to reconsider basic information about various functional aspects related to plant water content and provide evidence that the usefulness of measuring absolute water content in plant sciences is undervalued. First, general questions about water status in plants as well as methods for determining water content and their associated problems were discussed. After a brief overview of the structural organization of water in plant tissues, attention was paid to the water content of different parts of plants. Looking at the influence of environmental factors on plant water status, the differences caused by air humidity, mineral supply, biotic effects, salinity, and specific life forms (clonal and succulent plants) were analyzed. Finally, it was concluded that the expression of absolute water content on a dry biomass basis makes easily noticeable functional sense, but the physiological meaning and ecological significance of the drastic differences in plant water content need to be further elucidated.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('87d21f3c-fdcb-4bec-af83-cef3455a577b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Seasonal abundance of key alfalfa (Fabaceae) seed production pests and their natural enemies in southern Alberta, Canada', 'Aldo F. Ríos Martínez, Michelle Reid, Carol M. Frost, Héctor A. Cárcamo, Boyd A. Mori', 2024, 'The Canadian Entomologist', '10.4039/tce.2024.21', 'https://doi.org/10.4039/tce.2024.21', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/B1D956EDB4D635F220F33964CDA8B020/S0008347X2400021Xa.pdf/div-class-title-seasonal-abundance-of-key-alfalfa-fabaceae-seed-production-pests-and-their-natural-enemies-in-southern-alberta-canada-div.pdf', NULL, NULL, 19, NULL, 'southern_alberta', 4, 'cc-by', 'Abstract The economic importance of insect pests in agricultural fields and the potential biological control by their natural enemies warrant foundational studies for the development of integrated pest management strategies. An insect survey was conducted in alfalfa (Fabaceae) seed production fields in southern Alberta, Canada, during the bud, flowering, and seed crop stages in 2020 and 2021. We examined the seasonal abundance of Hypera postica (Gyllenhal) (Coleoptera: Curculionidae), Adelphocoris lineolatus (Goeze) (Hemiptera: Miridae), Lygus spp. Hahn (Hemiptera: Miridae), and 12 natural enemy taxa. We also examined the seasonal abundance, richness, and diversity of generalist predators and the seasonality of the two H. postica parasitoids, Bathyplectes curculionis (Thomson) (Hymenoptera: Ichneumonidae) and Oomyzus incertus (Ratzeburg) (Hymenoptera: Eulophidae). The seasonality of pests and natural enemies was inconsistent between years. Hypera postica larvae, B. curculionis, and O. incertus were present from mid-June to mid-August. However, we detected no correlations between H. postica larvae and its two parasitoids in either year. A number of generalist predators were correlated with A. lineolatus and Lygus spp. Further research is needed to understand the effects of environmental and biotic factors on the seasonality of pests and natural enemies in alfalfa seed production fields, and the insects’ trophic interactions.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('955457dc-96c2-4464-bc2c-9543751a92b0', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Secondary seed dormancy and the seedbank ecology of Brassica napus L. in western Canada', 'Robert H. Gulden', 2003, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-09052003-101649', 'http://hdl.handle.net/10388/etd-09052003-101649', NULL, NULL, 132, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e2274959-6919-4a85-b6be-209b9c22dc7b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Self-Fertilization, Inbreeding, and Yield in Alfalfa Seed Production', 'Molly E. Dieterich Mabin, Johanne Brunet, Heathcliffe Riday, Lauren Lehmann', 2021, 'Frontiers in Plant Science', '10.3389/fpls.2021.700708', 'https://doi.org/10.3389/fpls.2021.700708', 'https://www.frontiersin.org/articles/10.3389/fpls.2021.700708/pdf', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc-by', 'L.), we quantified the selfing rate of 32 alfalfa seed production fields located in three regions, namely, the Pacific Northwest (PNW), the Central Valley of California (CEV), and the Imperial Valley of California (IMP). Selfing rates (the proportion of selfed seeds) varied between 5.3 and 30% with an average of 12.2% over the 32 seed production fields. In both the parents and their progeny, we observed an excess of heterozygotes relative to Hardy-Weinberg expectations. We detected notable levels of inbreeding in parents (0.231 ± 0.007 parental inbreeding coefficient) and progeny (0.229 ± 0.005). There were a 15% decrease in the number of seeds per stem (seed set) and a 13% decline in the number of seeds per pod in selfed relative to outcrossed stems, but negligible inbreeding depression for pods per raceme and seed weight. The number of racemes on selfed stems increased significantly in fields with greater selfing rates, supporting the presence of geitonogamous or among flower selfing. Despite the significant level of inbreeding depression, seed set did not decrease in fields with higher selfing rates, where the greater number of racemes on the selfed stems increased the seed set. The effects of the field selfing rate on the seed yield metrics were mostly indirect with direct effects of the number of racemes per stem. Available data indicate that the majority of selfing in alfalfa is pollinator-mediated, and thus, eliminating selfing in alfalfa seed production would require the selection of self-incompatible varieties, which, by eliminating inbreeding depression, would provide a 15% potential increase in seed yield and an increase in future hay yield.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b8c98228-d352-4c87-baba-ef0814eb3eac', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Silage maize as a potent candidate for sustainable animal husbandry development-perspectives and strategies for genetic enhancement', 'Karnatam KS, Mythri B, Un Nisa W, Sharma H, Meena TK, Rana P, Vikal Y, Gowda M', 2023, 'Frontiers in genetics', '10.3389/fgene.2023.1150132', 'https://doi.org/10.3389/fgene.2023.1150132', 'https://europepmc.org/articles/PMC10250641?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Maize is recognized as the queen of cereals, with an ability to adapt to diverse agroecologies (from 58oN to 55oS latitude) and the highest genetic yield potential among cereals. Under contemporary conditions of global climate change, C4 maize crops offer resilience and sustainability to ensure food, nutritional security, and farmer livelihood. In the northwestern plains of India, maize is an important alternative to paddy for crop diversification in the wake of depleting water resources, reduced farm diversity, nutrient mining, and environmental pollution due to paddy straw burning. Owing to its quick growth, high biomass, good palatability, and absence of anti-nutritional components, maize is also one of the most nutritious non-legume green fodders. It is a high-energy, low-protein forage commonly used for dairy animals like cows and buffalos, often in combination with a complementary high-protein forage such as alfalfa. Maize is also preferred for silage over other fodders due to its softness, high starch content, and sufficient soluble sugars required for proper ensiling. With a rapid population increase in developing countries like China and India, there is an upsurge in meat consumption and, hence, the requirement for animal feed, which entails high usage of maize. The global maize silage market is projected to grow at a compound annual growth rate of 7.84% from 2021 to 2030. Factors such as increasing demand for sustainable and environment-friendly food sources coupled with rising health awareness are fueling this growth. With the dairy sector growing at about 4%-5% and the increasing shortage faced for fodder, demand for silage maize is expected to increase worldwide. The progress in improved mechanization for the provision of silage maize, reduced labor demand, lack of moisture-related marketing issues as associated with grain maize, early vacancy of farms for next crops, and easy and economical form of feed to sustain household dairy sector make maize silage a profitable venture. However, sustaining the profitability of this enterprise requires the development of hybrids specific for silage production. Little attention has yet been paid to breeding for a plant ideotype for silage with specific consideration of traits such as dry matter yield, nutrient yield, energy in organic matter, genetic architecture of cell wall components determining their digestibility, stalk standability, maturity span, and losses during ensiling. This review explores the available information on the underlying genetic mechanisms and gene/gene families impacting silage yield and quality. The trade-offs between yield and nutritive value in relation to crop duration are also discussed. Based on available genetic information on inheritance and molecular aspects, breeding strategies are proposed to develop maize ideotypes for silage for the development of sustainable animal husbandry.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9a8c8d39-dd1c-40b7-a5bb-6324f73dfa19', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Silage review: Unique challenges of silages made in hot and cold regions', 'Thiago Fernandes Bernardes, João Luiz Pratti Daniel, Adegbola Tolulope Adesogan, Tim Angus McAllister, Pascal Drouin, Luiz Gustavo Nussio, Pekka J Huhtanen, Gaëtan F. Tremblay', 2018, 'Journal of Dairy Science', '10.3168/jds.2017-13703', 'https://doi.org/10.3168/jds.2017-13703', 'http://www.journalofdairyscience.org/article/S0022030218303230/pdf', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by', 'Silage making can be conveniently divided into field, ensiling, storage, and feed-out phases. In all of these stages, controllable and uncontrollable components can affect silage quality. For instance, silages produced in hot or cold regions are strongly influenced by uncontrollable climate-related factors. In hot regions, crops for silage are influenced by (1) high temperatures negatively affecting corn yield (whole-crop and grain) and nutritive value, (2) butyric and alcoholic fermentations in warm-season grasses (Panicum, Brachiaria, and Pennisetum genera) and sugarcane, respectively, and (3) accelerated aerobic deterioration of silages. Ensiling expertise and economic factors that limit mechanization also impair silage production and utilization in hot environments. In cold regions, a short and cool growing season often limits the use of crops sensitive to cool temperature, such as corn. The fermentation triggered by epiphytic and inoculated microorganisms can also be functionally impaired at lower temperature. Although the use of silage inoculants has increased in Northern Europe, acid-based additives are still a good option in difficult weather conditions to ensure good fermentation quality, nutritive value, and high intake potential of silages. Acid-based additives have enhanced the quality of round bale silage, which has become a common method of forage preservation in Northern Europe. Although all abiotic factors can affect silage quality, the ambient temperature is a factor that influences all stages of silage making from production in the field to utilization at the feed bunk. This review identifies challenges and obstacles to producing silages under hot and cold conditions and discusses strategies for addressing these challenges.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('80abb574-e310-4cbc-ab0a-60cb44b5b919', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Soybean crop coefficients under different seeding rates and full and limited irrigation and rainfed management', 'Suat Irmak, Rupinder Sandhu', 2023, 'Irrigation and Drainage', '10.1002/ird.2854', 'https://doi.org/10.1002/ird.2854', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/ird.2854', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'Abstract The effects of soybean seeding rates on evapotranspiration (ETc) and grass‐ and alfalfa‐reference crop coefficients (Kco and Kcr) were investigated under five seeding rates (185,250, 247,000, 308,750, 370,500 and 432,250 seeds ha−1) (62, 82, 103, 124 and 144% of the recommended seeding rate of 300,000 seeds ha−1 in the experimental region) and different irrigation strategies (i.e. full irrigation treatment [FIT], limited irrigation of 75% FIT and 50% FIT and rainfed treatment). Kco and Kcr values were developed for each soybean growth stage. The seasonal ETc ranged from 460 mm for rainfed to 489 mm for FIT in 2014 under the same seeding rate of 247,000 seeds ha−1. In 2015, ETc ranged from 308 mm for rainfed conditions under the highest seeding rate (432,250 seeds ha−1) to 395 mm for FIT conditions under 308,750 seeds ha−1. Greater differences in weekly ETc were observed across irrigation levels than seeding rates, indicating that water availability has a greater impact on ETc than seeding rates. Kc values were strongly correlated with days after emergence (DAE) and growing degree days (GDD). The seasonal maximum Kco varied among seeding rates and was observed between GDDs of 924 and 1200°C, corresponding to the R5 (beginning seed) and R6 (full seed) growth stages.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d45aa3d6-270a-4842-a4f5-2d72dcdc88f3', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Tackling Control of a Cosmopolitan Phytopathogen: Sclerotinia', 'O''Sullivan CA, Belt K, Thatcher LF', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.707509', 'https://doi.org/10.3389/fpls.2021.707509', 'https://europepmc.org/articles/PMC8417578?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Phytopathogenic members of the Sclerotinia genus cause widespread disease across a broad range of economically important crops. In particular, Sclerotinia sclerotiorum is considered one of the most destructive and cosmopolitan of plant pathogens. Here, were review the epidemiology of the pathogen, its economic impact on agricultural production, and measures employed toward control of disease. We review the broad approaches required to tackle Sclerotinia diseases and include cultural practices, crop genetic resistance, chemical fungicides, and biological controls. We highlight the benefits and drawbacks of each approach along with recent advances within these controls and future strategies.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4a6c32f6-5ac0-447b-9579-956aa44b94d1', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'The diversity of citrus endophytic bacteria and their interactions with Xylella fastidiosa and host plants', 'Azevedo JL, Araújo WL, Lacava PT', 2016, 'Genetics and molecular biology', '10.1590/1678-4685-gmb-2016-0056', 'https://doi.org/10.1590/1678-4685-gmb-2016-0056', 'https://europepmc.org/articles/PMC5127157?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by', 'The bacterium Xylella fastidiosa is the causal agent of citrus variegated chlorosis (CVC) and has been associated with important losses in commercial orchards of all sweet orange [Citrus sinensis (L.)] cultivars. The development of this disease depends on the environmental conditions, including the endophytic microbial community associated with the host plant. Previous studies have shown that X. fastidiosa interacts with the endophytic community in xylem vessels as well as in the insect vector, resulting in a lower bacterial population and reduced CVC symptoms. The citrus endophytic bacterium Methylobacterium mesophilicum can trigger X. fastidiosa response in vitro, which results in reduced growth and induction of genes associated with energy production, stress, transport, and motility, indicating that X. fastidiosa has an adaptive response to M. mesophilicum. Although this response may result in reduced CVC symptoms, the colonization rate of the endophytic bacteria should be considered in studies that intend to use this endophyte to suppress CVC disease. Symbiotic control is a new strategy that uses symbiotic endophytes as biological control agents to antagonize or displace pathogens. Candidate endophytes for symbiotic control of CVC must occupy the xylem of host plants and attach to the precibarium of sharpshooter insects to access the pathogen. In the present review, we focus on interactions between endophytic bacteria from sweet orange plants and X. fastidiosa, especially those that may be candidates for control of CVC.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('696af057-e154-42a8-a0b9-41d7442f9111', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'The effects of increasing crop diversity on populations of wheat stem sawfly (Cephus cinctus) and associated braconid parasitoids', 'Benjamin Vernon Fischer', 2019, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/xmlui/handle/1/16184', 'https://scholarworks.montana.edu/xmlui/handle/1/16184', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0140a803-125c-43d2-9cae-639ac86f0bbc', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'The Photosynthetic Efficiency and Carbohydrates Responses of Six Edamame (Glycine max. L. Merrill) Cultivars under Drought Stress', 'Hlahla JM, Mafa MS, van der Merwe R, Alexander O, Duvenhage MM, Kemp G, Moloi MJ', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11030394', 'https://doi.org/10.3390/plants11030394', 'https://europepmc.org/articles/PMC8840725?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Vegetable-type soybean, also known as edamame, was recently introduced to South Africa. However, there is lack of information on its responses to drought. The aim of this study was to investigate the photosynthetic efficiency and carbohydrates responses of six edamame cultivars under drought stress. Photosynthetic efficiency parameters, including chlorophyll fluorescence and stomatal conductance, were determined using non-invasive methods, while pigments were quantified spectrophotometrically. Non-structural carbohydrates were quantified using Megazyme kits. Structural carbohydrates were determined using Fourier-transform infrared spectroscopy (FTIR) and X-ray diffraction (XRD). Drought stress significantly increased the Fv/Fm and PIabs of AGS429 and UVE17 at pod filling stage. Chlorophyll-a, which was most sensitive to drought, was significantly reduced in AGS429 and UVE17, but chlorophyll-b was relatively stable in all cultivars, except UVE17, which showed a significant decline at flowering stage. AGS354 and AGS429 also showed reduced chlorophyll-b at pod filling. UVE17 showed a significant reduction in carotenoid content and a substantial reduction in stomatal conductance during pod filling. Drought stress during pod filling resulted in a significant increase in the contents of trehalose, sucrose and starch, but glucose was decreased. Chlorophyll-a positively correlated with starch. The FTIR and XRD results suggest that the cell wall of UVE14, followed by UVE8 and AGS429, was the most intact during drought stress. It was concluded that carotenoids, stomatal conductance, starch and hemicellulose could be used as physiological/biochemical indicators of drought tolerance in edamame. This information expands our knowledge of the drought defense responses in edamame, and it is essential for the physiological and biochemical screening of drought tolerance.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b836e8e5-06c2-46b1-bf6e-36073f57c295', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Weed management in irrigated fenugreek grown for forage in rotation with other annual crops', 'JAMES R. MOYER, S. N. Acharya, Zahir Mir, Ray C. Doram', 2003, 'Canadian Journal of Plant Science', '10.4141/p02-030', 'https://doi.org/10.4141/p02-030', 'https://cdnsciencepub.com/doi/pdf/10.4141/P02-030', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('699326c1-4b68-494e-a2fb-4cfd0502b9c0', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'The role of trehalose metabolism in plant stress tolerance', 'Eh TJ, Jiang Y, Jiang M, Li J, Lei P, Ji X, Kim HI, Zhao X', 2025, 'Journal of advanced research', '10.1016/j.jare.2024.12.025', 'https://doi.org/10.1016/j.jare.2024.12.025', 'https://europepmc.org/articles/PMC12793763?pdf=render', NULL, NULL, 16, NULL, 'other', 1, 'cc by-nc-nd', 'BackgroundTrehalose is a nonreducing disaccharide containing two glucose molecules linked through an α,α-1,1-glycosidic bond. This unique chemical structure causes trehalose levels to fluctuate significantly in plants under stress, where it functions as an osmoprotectant, enhancing plant resistance to stress. Previous studies have confirmed that the trehalose synthesis pathway is widely conserved across most plants. However, the protective role of trehalose is limited only to organelles or tissues where the concentration is sufficiently high.Aim of reviewIn this review, we summarize previous reports on improving plant stress tolerance (drought, cold, heat, salt, pathogen, etc.) by applying trehalose-6-phosphate (T6P) or trehalose and manipulating the expression of trehalose metabolism-related genes. The molecular mechanisms underlying T6P, trehalose, and their related genes that regulate plant stress resistance are reviewed. More progressive studies on the spatiotemporal control of trehalose metabolism will provide a novel tool that allows for the simultaneous enhancement of crop yield and stress tolerance.Key scientific concepts of reviewWe introduce the history of trehalose and discuss the possibility of trehalose and its metabolity-related genes binding to T6P to participate in stress response through unknown signaling pathways. In addition, the effects of trehalose metabolism regulation on plant growth and stress resistance were reviewed, and the molecular mechanism was fully discussed. In particular, we came up with new insights that the molecular mechanism of trehalose metabolism to enhance plant stress resistance in the future and we propose the need to use biotechnology methods to cultivate crops with stress resistance and high yield potential.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('86831b0e-f792-4d0d-9f0a-f501ca3bfecd', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Thermoperiodism Synchronizes Emergence in the Alfalfa Leafcutting Bee (Hymenoptera: Megachilidae)', 'George D. Yocum, Joseph P. Rinehart, Ian Yocum, William P. Kemp, Kendra J. Greenlee', 2015, 'Environmental Entomology', '10.1093/ee/nvv152', 'https://doi.org/10.1093/ee/nvv152', 'https://academic.oup.com/ee/article-pdf/45/1/245/7467085/nvv152.pdf', NULL, NULL, NULL, NULL, 'prairies', 4, 'public-domain', 'Alfalfa seed production in the northwestern United States and western Canada is heavily dependent upon the pollinating services of Megachile rotundata (F.) (Hymenoptera: Megachilidae). M. rotundata females nest in cavities either naturally occurring or in artificial nesting blocks. Because of the physical nature of the nest, M. rotundata brood may have limited to no exposure to photoperiodic cues in order to regulate important circadian functions. Therefore, various thermoperiod regimes were used to characterize the possible role of thermoperiodism in synchronizing M. rotundata adult emergence. Adult emergence was monitored using a microprocessor-controlled event logger. Incubating bees under constant 29°C and darkness resulted in an arhythmic adult emergence pattern. Exposing developing M. rotundata to a thermoperiod synchronized emergence to the beginning of the thermophase and decreased the total number of days required for all adults to emerge. The amplitude of the thermoperiod regulated the timing of peak emergence in relationship to the increase in temperature. A thermoperiod amplitude of only 2°C was sufficient to synchronize peak adult emergence to take place during the rise in temperature. Increasing the amplitude of the thermoperiod to 4 or 8°C caused a positively correlated shift in peak emergence to later in the thermophase. Brood stored under constant 29°C and darkness for different durations (May or June early in the growing season or July or August late in the growing season) or under a fluctuating thermal regime (base temperature of 6°C and daily 1-h pulse of 20°C until September or November) maintained their capacity for entraining emergence timing by thermoperiodism.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d3e79cf3-9fba-474a-8957-a2243d7b526b', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Unmanned aerial systems-based remote sensing for monitoring sorghum growth and development', 'Shafian S, Rajan N, Schnell R, Bagavathiannan M, Valasek J, Shi Y, Olsenholler J', 2018, 'PloS one', '10.1371/journal.pone.0196605', 'https://doi.org/10.1371/journal.pone.0196605', 'https://europepmc.org/articles/PMC5929499?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Unmanned Aerial Vehicles and Systems (UAV or UAS) have become increasingly popular in recent years for agricultural research applications. UAS are capable of acquiring images with high spatial and temporal resolutions that are ideal for applications in agriculture. The objective of this study was to evaluate the performance of a UAS-based remote sensing system for quantification of crop growth parameters of sorghum (Sorghum bicolor L.) including leaf area index (LAI), fractional vegetation cover (fc) and yield. The study was conducted at the Texas A&M Research Farm near College Station, Texas, United States. A fixed-wing UAS equipped with a multispectral sensor was used to collect image data during the 2016 growing season (April-October). Flight missions were successfully carried out at 50 days after planting (DAP; 25 May), 66 DAP (10 June) and 74 DAP (18 June). These flight missions provided image data covering the middle growth period of sorghum with a spatial resolution of approximately 6.5 cm. Field measurements of LAI and fc were also collected. Four vegetation indices were calculated using the UAS images. Among those indices, the normalized difference vegetation index (NDVI) showed the highest correlation with LAI, fc and yield with R2 values of 0.91, 0.89 and 0.58 respectively. Empirical relationships between NDVI and LAI and between NDVI and fc were validated and proved to be accurate for estimating LAI and fc from UAS-derived NDVI values. NDVI determined from UAS imagery acquired during the flowering stage (74 DAP) was found to be the most highly correlated with final grain yield. The observed high correlations between UAS-derived NDVI and the crop growth parameters (fc, LAI and grain yield) suggests the applicability of UAS for within-season data collection of agricultural crops such as sorghum.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8df3d6eb-9637-44ec-bb5c-d1e859a268fb', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Variation in seed longevity among diverse Indica rice varieties', 'Lee JS, Velasco-Punzalan M, Pacleb M, Valdez R, Kretzschmar T, McNally KL, Ismail AM, Cruz PCS', 2019, 'Annals of botany', '10.1093/aob/mcz093', 'https://doi.org/10.1093/aob/mcz093', 'https://europepmc.org/articles/PMC6798842?pdf=render', NULL, NULL, 14, NULL, 'other', 1, 'cc by', 'Background and aimsUnderstanding variation in seed longevity, especially within closely related germplasm, will lead to better understanding of the molecular basis of this trait, which is particularly important for seed genebanks, but is also relevant to anyone handling seeds. We therefore set out to determine the relative seed longevity of diverse Indica rice accessions through storage experiments. Since antioxidants are purported to play a role in seed storability, the antioxidant activity and phenolic content of caryopses were determined.MethodsSeeds of 299 Indica rice accessions harvested at 31, 38 and 45 d after heading (DAH) between March and May 2015 and differing in harvest moisture content (MC) were subsequently stored at 10.9 % MC and 45 °C. Samples were taken at regular intervals and sown for germination. Germination data were subjected to probit analysis and the resulting parameters that describe the loss of viability during storage were used for genome-wide association (GWA) analysis.Key resultsThe seed longevity parameters, Ki [initial viability in normal equivalent deviates (NED)], -σ-1 (σ is the time for viability to fall by 1 NED in experimental storage) and p50 [time for viability to fall to 50 % (0 NED)], varied considerably across the 299 Indica accessions. Seed longevity tended to increase as harvest MC decreased and to decrease as harvest MC increased. Eight major loci associated with seed longevity parameters were identified through GWA analysis. The favourable haplotypes on chromosomes 1, 3, 4, 9 and 11 enhanced p50 by ratios of 0.22-1.86.ConclusionsThis is the first study to describe the extent of variation in σ within a species'' variety group. A priori candidate genes selected based on rice genome annotation and gene network ontology databases suggested that the mechanisms conferring high seed longevity might be related to DNA repair and transcription, sugar metabolism, reactive oxygen species scavenging and embryonic/root development.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd21e994-96dd-4e1a-b1ad-0d1945b21d7f', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'What''s in a pollen provision? Using larval provisions to quantify pesticide exposure in Megachile rotundata (Hymenoptera: Megachilidae)', 'MacInnis CI, Ovinge LP, Thompson TS, Hoover SER', 2026, 'Environmental entomology', '10.1093/ee/nvag023', 'https://doi.org/10.1093/ee/nvag023', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC13017921.1/PMC13017921.1.pdf', NULL, NULL, 9, NULL, 'southern_alberta', 4, 'cc by', 'The alfalfa leafcutting bee (LCB) (Megachile rotundata Fabricius) is a solitary, managed pollinator widely used in North American agriculture to produce alfalfa and hybrid canola seed. Despite its economic importance, and known sensitivity to certain pesticides, little is known about the specific pesticide residues LCBs encounter during pollination, and toxicity data for this species remains limited. To determine what residues LCBs are commonly exposed to, we screened larval LCB provisions from nine alfalfa sites during pollination in southern Alberta for 69 pesticide residues. Eight residues amongst three classes of pesticides were detected including four fungicides (boscalid, cyprodinil, fludioxonil, and pyraclostrobin), three insecticides (chlorpyrifos, cyhalothrin lambda, and deltamethrin), and the herbicide Velpar (hexazinone). Using the residue data, we calculated site-specific hazard quotients (HQ) using Apis mellifera L. LD50s to provide context for exposure risk. Sites with residues from multiple pesticide classes tended to have higher-though not always significantly higher-HQs than sites with residues from only one class. These findings provide a regional profile for pesticide exposure for LCBs in southern Alberta and identifies compounds of potential concern for future toxicological testing and pollinator management.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1af36a49-43e6-49a3-a86d-f29a0407df47', 'ef664e33-68f3-4476-8e38-7d11b828270d', 'Wyoming Producer Priorities and Perceptions of Alfalfa Insect Pests', 'Randa Jabbour, Shiri Noy', 2017, 'Journal of Integrated Pest Management', '10.1093/jipm/pmx017', 'https://doi.org/10.1093/jipm/pmx017', 'https://academic.oup.com/jipm/article-pdf/8/1/26/33049660/pmx017.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc', 'Abstract Although insect pest management in alfalfa (Medicago sativa L. [Fabales: Fabaceae]) hay remains a major challenge in the Western United States, we know comparatively little about the producer priorities and perceptions of alfalfa insect pests. Given the importance of alfalfa to Wyoming agriculture, we sought to better understand producer priorities regarding insect pest management in alfalfa. We developed a survey instrument that was mailed to 3,141 individuals by the National Agricultural Statistics Service (NASS). We received 634 returned surveys, a response rate of 20.7% of all Wyoming alfalfa producers. Respondents were asked to list all insect pests they had encountered in their experience growing alfalfa, and then to select the most problematic from the list they generated. Sixty-six percent of respondents named alfalfa weevil Hypera postica (Gyllenhal; Coleoptera: Curculionidae) as the most problematic insect pest they had encountered. Eighteen percent of respondents named grasshoppers (Orthoptera) as most problematic, and 8% of respondents named aphids (Hemiptera: Aphididae). Producers indicated a variety of agronomic, economic, biological, and weather-related reasons that rendered these insects as problematic pests. For each of the three most problematic pests, insecticide application and early harvest of hay were practiced by the largest number of Wyoming producers according to our survey results. For all three of these pests, insecticides are both used most often and considered most effective by the most respondents. These findings suggest an important opportunity for future research on integrated insect pest management.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('027c4016-1f6d-4298-b9fa-5e6e921e3686', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'A barley pan-transcriptome reveals layers of genotype-dependent transcriptional complexity', 'Guo W, Schreiber M, Marosi VB, Bagnaresi P, Jørgensen ME, Braune KB, Chalmers K, Chapman B', 2025, 'Nature genetics', '10.1038/s41588-024-02069-y', 'https://doi.org/10.1038/s41588-024-02069-y', 'https://europepmc.org/articles/PMC11821519?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'A pan-transcriptome describes the transcriptional and post-transcriptional consequences of genome diversity from multiple individuals within a species. We developed a barley pan-transcriptome using 20 inbred genotypes representing domesticated barley diversity by generating and analyzing short- and long-read RNA-sequencing datasets from multiple tissues. To overcome single reference bias in transcript quantification, we constructed genotype-specific reference transcript datasets (RTDs) and integrated these into a linear pan-genome framework to create a pan-RTD, allowing transcript categorization as core, shell or cloud. Focusing on the core (expressed in all genotypes), we observed significant transcript abundance variation among tissues and between genotypes driven partly by RNA processing, gene copy number, structural rearrangements and conservation of promotor motifs. Network analyses revealed conserved co-expression module::tissue correlations and frequent functional diversification. To complement the pan-transcriptome, we constructed a comprehensive cultivar (cv.) Morex gene-expression atlas and illustrate how these combined datasets can be used to guide biological inquiry.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('29edba0d-3003-4fad-bd2b-667c03771d14', '79e6ef68-5add-4e8f-861f-8837068b8bc9', 'An evaluation of the effects of subsoiling with a Howard paraplow on root rot, soil water relations and yields of pulse crops in southern Alberta', 'Government of Alberta', 1985, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluation-of-the-effects-of-subsoiling-with-a-howard-paraplow-on-root-rot-soil-water-relati', 'https://open.alberta.ca/dataset/0d0683e8-8666-4e88-b3b3-5bc99046bdb1/resource/e5346c78-b62c-40d7-8d83-09391f54aeaa/download/0163010234827-evaluation-effects-subsoiling-with-howard-paraplow-root-rot-soil-water-relati.pdf', NULL, NULL, 54, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'Presents the findings of a study to assess the impact of soil loosening on root rot, soil moisture and yields in affected regions.', '{open-alberta,extension,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3baffa0e-56f1-414c-a574-f1b1255ced26', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'A Comprehensive Review: Current Strategies for Detoxification of Deoxynivalenol in Feedstuffs for Pigs', 'Yu C, Plaizier P, Gong J, Yang C, Liu S', 2025, 'Animals : an open access journal from MDPI', '10.3390/ani15182739', 'https://doi.org/10.3390/ani15182739', 'https://europepmc.org/articles/PMC12466796?pdf=render', NULL, NULL, 60, NULL, 'prairies', 4, 'cc by', 'Deoxynivalenol (DON) is a mycotoxin produced by Fusarium graminearum and Fusarium culmorum, primarily contaminating wheat, corn, and their derivatives. Although less toxic than some other mycotoxins, DON is significant due to its abundance, particularly in wheat, and its resistance to in vitro detoxification. Compared to other livestock, pigs are the most susceptible animals to DON''s presence due to its interaction with wheat-heavy diets. The best way to attenuate the effects of DON is to prevent its presence on cultivated land; however, given that it is difficult to prevent the occurrence of DON in freshly harvested cereals completely, other strategies must be applied. For pigs, chronic consumption of feed with DON concentrations below even the regulated limits can still negatively impact growth. Thus, DON-detoxifying agents including antidotes, DON binding agents, and exogenous in vivo enzyme additives, have been added to feed in an attempt to detoxify DON. This comprehensive review highlights the most recently developed DON-detoxification techniques and assesses each treatment''s viability and efficacy, with an emphasis on chemical and biochemical techniques and the rapid development of artificial intelligence (AI) technologies. Herein we explore the unmet needs and future directions of current technologies while discussing promising strategies that can advance the DON-detoxification field.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('042cb664-a701-4ace-a1d4-f331ec99d604', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'A new method for assessing plant lodging and the impact of management options on lodging in canola crop production', 'Wu W, Ma BL', 2016, 'Scientific reports', '10.1038/srep31890', 'https://doi.org/10.1038/srep31890', 'https://europepmc.org/articles/PMC4995411?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Lodging, defined as the permanent displacement of aboveground parts, is a common problem to cause yield loss, deterioration in seed quality and difficult to harvest in canola (Brassica napus L.) crop production. This study aimed to develop a method for assessing crop lodging, to examine how agronomic practices affected the relationships between root lodging and electrical capacitance traits. Canola plants were more susceptible to root lodging than stem lodging. The electrical measurements were more closely related with anchorage strength (Sp) than stem bending strength (Ss). Among the three electrical measurements, the root capacitance (C) displayed the most consistent and significant relationships with Sp in all three field experiments (R(2) = 0.88-0.56; P ≤ 0.01). This study indicates that the risk of lodging can be reduced by using appropriate management practices and variety selection. Enhancing root Sp was advocated as a priority over enhancing stem Ss in cultivar improvement. Electrical measurements, especially of root C, can be considered as a non-invasive technique that could partially replace the intrusive methods used for the in situ assessment of lodging resistance among various agronomic practices or can be applied in breeding programs for selecting genotypes with high yield potentials and strong Sp values.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('14d9785b-3965-4c0c-979d-c53e86525ce5', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'A proposal for a North American continental market for barley', 'Government of Alberta', 1991, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/proposal-for-a-north-american-continental-market-for-barley', 'https://open.alberta.ca/dataset/6b9f32f6-944c-40d1-b424-184d817011bc/resource/b9429687-bf83-4cc5-86fb-41809e0bcacd/download/0163010000574-a-proposal-for-a-north-american-continental-market-for-barley.pdf', NULL, NULL, 66, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report proposes implementing a North American continental market for Canadian barley, allowing farmers and their agents equal jurisdiction in marketing within this region. It highlights the benefits of a continental market, such as increased farm income, improved price efficiency, and reduced marketing costs, by providing direct access to the United States market. The proposal seeks to achieve these changes by amending Canadian Wheat Board Act regulations to authorize equal opportunity for barley marketing across North America. This approach aims to strengthen the barley industry''s competitiveness and reduce reliance on publicly funded programs.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f35826f9-97cd-4955-99e4-b8de54a5c107', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Abscisic and Jasmonic Acids Contribute to Soybean Tolerance to the Soybean Aphid (Aphis glycines Matsumura)', 'Chapman KM, Marchi-Werle L, Hunt TE, Heng-Moss TM, Louis J', 2018, 'Scientific reports', '10.1038/s41598-018-33477-w', 'https://doi.org/10.1038/s41598-018-33477-w', 'https://europepmc.org/articles/PMC6181993?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by', 'Plant resistance can provide effective, economical, and sustainable pest control. Tolerance to the soybean aphid has been identified and confirmed in the soybean KS4202. Although its resistance mechanisms are not fully understood, evidence suggests that enhanced detoxification of reactive oxygen species (ROS) is an active system under high aphid infestation. We further explored tolerance by evaluating the differences in constitutive and aphid-induced defenses in KS4202 through the expression of selected defense-related transcripts and the levels of the phytohormones abscisic acid (ABA), jasmonic acid (JA), JA-isoleucine (JA-Ile), cis-(+)-12-oxo-phytodienoic acid (OPDA), and salicylic acid (SA) over several time points. Higher constitutive levels of ABA and JA, and basal expression of ABA- and JA-related transcripts were found in the tolerant genotype. Conversely, aphid-induced defenses in KS4202 were expressed as an upregulation of peroxidases under prolonged aphid infestation (>7 days). Our results point at the importance of phytohormones in constitutive defense in KS4202 tolerance to the soybean aphid. Understanding the underlying mechanisms of tolerance will assist breeding for soybean with these traits, and perhaps help extend the durability of Rag (Resistance to Aphis glycines)-mediated resistance genes.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7f150af2-c959-4755-b9df-6367ad546b6a', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Agriculture surfs the Internet with Project Barley', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/agriculture-surfs-the-internet-with-project-barley', 'https://open.alberta.ca/dataset/7899df2c-5e75-4a97-9915-73f95e45e0cd/resource/397ae137-a057-4b55-9605-39db3fdbe8b1/download/0163010214860-agriculture-surfs-the-internet-with-project-barley.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This pamphlet introduces Alberta barley farmers to the Internet allowing participants to discover the agricultural information and services available electronically from Alberta Agriculture, Food and Rural Development and the rest of the world. The Project Barley pilot project aims to assess the usefulness of the Internet in delivering agricultural information, test its ability to support various types of data, and gauge user interest and satisfaction.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c02cbd62-c69c-4f46-8591-37a421cde29c', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Antixenosis, Antibiosis, and Potential Yield Compensatory Response in Barley Cultivars Exposed to Wheat Stem Sawfly (Hymenoptera: Cephidae) Under Field Conditions', 'Achhami BB, Reddy GVP, Sherman JD, Peterson RKD, Weaver DK', 2020, 'Journal of insect science (Online)', '10.1093/jisesa/ieaa091', 'https://doi.org/10.1093/jisesa/ieaa091', 'https://europepmc.org/articles/PMC7508298?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by-nc', 'Wheat stem sawfly, Cephus cinctus Norton, is an economically serious pest of cereals grown in North America. Barley cultivars were previously planted as resistant crops in rotations to manage C. cinctus, but due to increasing levels of injury to this crop, this is no longer a valid management tactic in Montana. Therefore, we aimed to understand antixenosis (behavioral preference), antibiosis (mortality), and potential yield compensation (increased productivity in response to stem injuries) in barley exposed to C. cinctus. We examined these traits in eight barley cultivars. Antixenosis was assessed by counting number of eggs per stem and antibiosis was assessed by counting infested stems, dead larvae, and stems cut by mature larvae. Potential yield compensation was evaluated by comparing grain yield from three categories of stem infestation: 1) uninfested, 2) infested with dead larva, and 3) infested cut by mature larva at crop maturity. We found the greatest number of eggs per infested stem (1.80 ± 0.04), the highest proportion of infested stems (0.63 ± 0.01), and the highest proportion of cut stems (0.33 ± 0.01) in ''Hockett''. Seven out of eight cultivars had greater grain weight for infested stems than for uninfested stems. These cultivars may have compensatory responses to larval feeding injury. Overall, these barley cultivars contain varying levels of antixenosis, antibiosis, and differing levels of yield compensation. Our results provide foundational knowledge on barley traits that will provide a framework to further develop C. cinctus resistant or tolerant barley cultivars.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9d46063c-fda7-4bdb-ad71-1d0604465bbc', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Application of haploid technique to barley breeding', 'Government of Alberta', 1982, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/application-of-haploid-technique-to-barley-breeding', 'https://open.alberta.ca/dataset/ff761bc0-0386-4072-a0ec-28087787ce59/resource/0a56db8b-a576-4e43-a9ef-e68623555bec/download/0163010363162-application-of-haploid-technique-to-barley-breeding.pdf', NULL, NULL, 10, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project applied haploid techniques to barley breeding to isolate dihaploid lines from selected F2 populations. After resolving earlier technical issues, researchers successfully isolated 61 lines by May 1982 and tracked the progress of 75 haploid plants through different developmental stages. By the project''s end, they had isolated an additional 25 dihaploid lines and germinated 9 new haploid plants from embryos. Although compatibility issues limited progress with some varieties, two of Dr. K. May''s lines produced 14 haploid seedlings, 11 of which were successfully treated. The team recommended establishing a permanent haploidy program in Alberta due to the promising results and ongoing need for genetic tools in barley breeding.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7bd7ecd7-36c5-4097-a732-66779a632c50', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Applying microbial biostimulants and drought-tolerant genotypes to enhance barley growth and yield under drought stress', 'Ferioun M, Zouitane I, Bouhraoua S, Elouattassi Y, Belahcen D, Errabbani A, Louahlia S, Sayyed R', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1494987', 'https://doi.org/10.3389/fpls.2024.1494987', 'https://europepmc.org/articles/PMC11747827?pdf=render', NULL, NULL, 25, NULL, 'other', 1, 'cc by', 'With climate change, the frequency of regions experiencing water scarcity is increasing annually, posing a significant challenge to crop yield. Barley, a staple crop consumed and cultivated globally, is particularly susceptible to the detrimental effects of drought stress, leading to reduced yield production. Water scarcity adversely affects multiple aspects of barley growth, including seed germination, biomass production, shoot and root characteristics, water and osmotic status, photosynthesis, and induces oxidative stress, resulting in considerable losses in grain yield and its components. In this context, the present review aims to underscore the importance of selecting drought-tolerant barley genotypes and utilizing bio-inoculants constructed from beneficial microorganisms as an agroecological approach to enhance barley growth and production resilience under varying environmental conditions. Selecting barley genotypes with robust physiological and agronomic tolerance can mitigate losses under diverse environmental conditions. Plant Growth Promoting Rhizobacteria (PGPR) play a crucial role in promoting plant growth through nutrient solubilization, nitrogen fixation, phytohormone production, exopolysaccharide secretion, enzyme activity enhancement, and many other mechanisms. Applying drought-tolerant genotypes with bio-inoculants containing PGPR, improves barley''s drought tolerance thereby minimizing losses caused by water scarcity.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a42714d5-543e-41c9-85c5-585cd3ecc6fd', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Association mapping for hop cone chemistry and morphology identifies natural beneficial allele stacks', 'Clare SJ, Schmuker P, Altendorf K', 2026, 'The plant genome', '10.1002/tpg2.70238', 'https://doi.org/10.1002/tpg2.70238', 'https://europepmc.org/articles/PMC13125966?pdf=render', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc by', 'Efforts are underway to increase the efficiency and precision of selection hop (Humulus lupulus L.) breeding using genomics. Little is known, however, about the genetic control of important traits like α-and β-acids contents, oil content, and cone morphological characteristics, all of which play an important role in determining the utility and harvestability of a hop and are targets of selection. In this study, we utilized association mapping with a collection of 529 female hop plants evaluated in Prosser, WA USA in 2023 and 2024, single nucleotide polymorphism data derived from genotyping-by-sequencing with 20,861 markers, and phenotype data generated from near-infrared (NIR) spectroscopy and image analyses of hop cones. A total of 49 significant marker trait associations were detected across five traits with 43 unique loci. High correlation estimates between wet lab and near-infrared spectroscopy data (R = 0.54-0.94), high broad-sense heritability estimates (H2 = 0.32-0.71), and logical associated candidate genes illustrate the validity of the methods used in detecting meaningful associations. Furthermore, existing germplasm in our study containing increasing stacks of favorable alleles showed improvement in all traits, demonstrating the potential for utilizing the markers identified herein in a genomic prediction pipeline to improve hop germplasm for key end-use traits.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('de86ff86-8c93-41e8-946d-4f321d27969f', '79e6ef68-5add-4e8f-861f-8837068b8bc9', 'The effect of precipitation-induced advective heat on permafrost in the Tibetan PlateauFigshare', 'Qingxue Dong, Siqiong Luo, Zihang Chen, Tonghua Wu, Zhaoguo Li, Lunyu Shang, Jingyuan Wang, Yao Xiao', 2025, 'Journal of Hydrology: Regional Studies', '10.1016/j.ejrh.2025.102981', 'https://doi.org/10.1016/j.ejrh.2025.102981', 'http://www.sciencedirect.com/science/article/pii/S2214581825008109', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Study region: The Tibetan Plateau (TP), China, contains the world’s largest permafrost area outside the Polar Regions. Study focus: This study investigates the precipitation-induced advective heat flux (EPre), which represents the energy transfer resulting from the temperature difference between rainfall and soil. Observational data from three permafrost monitoring sites (Qumalai, Xidatan, and Tanggula) were combined with simulations from the Community Land Model version 5.0 (CLM5.0) to quantify EPre precipitation infiltration depth, and the probability of infiltration reaching the frozen soil layer. The analysis further examines how precipitation amount, soil texture, soil moisture, and freeze–thaw state jointly control infiltration processes and influence the soil thermal regime. New hydrological insights for the region: Infiltration depth varies with initial soil moisture and precipitation duration, from shallow retention to deep percolation. EPre is generally negative, with maximum cooling of −84.14 W m⁻² at QML, −73.24 W m⁻² at XDT, and −56.63 W m⁻² at TGL, but becomes positive during prolonged summer rainfall, reaching 45.43 W m⁻² at QML. Diurnal soil temperature variations shift EPre from cooling by day to reduced cooling or warming at night. Across the TP, mean infiltration depth is ∼5 cm, higher in southeastern Tibet, with a regional mean EPre of −0.08 W m⁻². Warming effects are concentrated in the southeastern and central TP, while cooling dominates the arid west and high-elevation north.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5bedd93b-1da7-46e0-ace1-4bff517b4efb', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Barley food products intervention trial for non-insulin-dependent (NIDDM) diabetic subjects', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/barley-food-products-intervention-trial-for-non-insulin-dependent-niddm-diabetic-subjects', 'https://open.alberta.ca/dataset/c6e1680f-fee6-4b03-ac7a-4f328434026f/resource/3cc646d6-f2a5-400f-8c18-f99dd967265b/download/0163010148258-barley-food-products-intervention-trial-non-insulin-dependent-niddm-diabetic-subje.pdf', NULL, NULL, 143, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document evaluated the long-term effects of incorporating high fibre barley bread products, made from waxy hulless barley containing 5.2 per cent β-glucan, into the usual dietary pattern of non-insulin-dependent diabetic (NIDDM) subjects. 56 NIDDM adults (27 males, 29 females) participated in a six-month intervention trial, with dietary, clinical and biochemical assessments at baseline, three and six months. The study found that barley bread products increased total and soluble dietary fibre intake, improved glycemic control (notably reducing glycated haemoglobin in females), lowered fasting insulin in males, and favourably altered blood lipid profiles and blood pressure in both sexes. Significant negative correlations were observed between dietary fibre intake and key metabolic parameters. The barley bread products were well accepted, and their incorporation proved practical and beneficial for the overall health of NIDDM individuals.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6fdf8b62-b359-4256-a981-84277585e065', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Barley production in Alberta', 'Government of Alberta', 1986, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/barley-production-in-alberta-0163010474779', 'https://open.alberta.ca/dataset/7a64928d-bb1b-4b81-9ce9-6ab7a023ad72/resource/84dbe5c0-d321-45a7-9f06-0b8d7f9390a1/download/0163010474779-barley-production-in-alberta.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report details the significance of barley production within Alberta''s agricultural industry. It outlines barley''s diverse uses, including livestock feed, malting, and minor food products, and describes its agronomic characteristics, such as soil preferences and adaptability to various climates. The report also highlights Alberta''s role as a major exporter of barley, detailing its market presence and potential for future processing within Western Canada.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04b50744-b94e-448e-b541-cb5b55143cbc', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Biological evaluation of advanced selections of high-lysine barley produced in Alberta Agriculture feed grain breeding program', 'Government of Alberta', 1983, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/biological-evaluation-of-advanced-selections-of-high-lysine-barley-produced-in-alberta-agricult', 'https://open.alberta.ca/dataset/9e771f32-2862-49f1-abb4-7a4862d06ea2/resource/34b4c79f-b366-4e9c-9e0e-b2e8b4c33061/download/0163010335160-biological-evaluation-advanced-selections-high-lysine-barley-produced-alberta-agri.pdf', NULL, NULL, 86, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project supported the development of high-lysine barley for swine feed through collaboration with Alberta Agriculture. Early selections showed promising nutritional quality but poor agronomic traits, which led to a temporary decline in lysine content in later cultivars. Animal feeding trials confirmed this decline and highlighted the importance of biological testing alongside laboratory methods. Later field trials confirmed that lysine content increased with protein level, but there was no clear relationship between yield and either protein or lysine content. This lack of correlation suggests that breeders can improve nutritional quality without reducing yield.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1cb14648-732c-4606-88cd-c5ea67724665', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Characterization of Resistance to Cephus cinctus (Hymenoptera: Cephidae) in Barley Germplasm', 'Varella AC, Talbert LE, Achhami BB, Blake NK, Hofland ML, Sherman JD, Lamb PF, Reddy GVP', 2018, 'Journal of economic entomology', '10.1093/jee/toy025', 'https://doi.org/10.1093/jee/toy025', 'https://europepmc.org/articles/PMC6019026?pdf=render', NULL, NULL, 8, NULL, 'prairies', 4, 'cc by-nc', 'Most barley cultivars have some degree of resistance to the wheat stem sawfly (WSS), Cephus cinctus Norton (Hymenoptera: Cephidae). Damage caused by WSS is currently observed in fields of barley grown in the Northern Great Plains, but the impact of WSS damage among cultivars due to genetic differences within the barley germplasm is not known. Specifically, little is known about the mechanisms underlying WSS resistance in barley. We characterized WSS resistance in a subset of the spring barley CAP (Coordinated Agricultural Project) germplasm panel containing 193 current and historically important breeding lines from six North American breeding programs. Panel lines were grown in WSS infested fields for two consecutive years. Lines were characterized for stem solidness, stem cutting, WSS infestation (antixenosis), larval mortality (antibiosis), and parasitism (indirect plant defense). Variation in resistance to WSS in barley was compared to observations made for solid-stemmed resistant and hollow-stemmed susceptible wheat lines. Results indicate that both antibiosis and antixenosis are involved in the resistance of barley to the WSS, but antibiosis seems to be more prevalent. Almost all of the barley lines had greater larval mortality than the hollow-stemmed wheat lines, and only a few barley lines had mortality as low as that observed in the solid-stemmed wheat line. Since barley lines lack solid stems, it is apparent that barley has a different form of antibiosis. Our results provide information for use of barley in rotation to control the WSS and may provide a basis for identification of new approaches for improving WSS resistance in wheat.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18cdb5db-7c80-4110-a364-ceb3eace656d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Disease resistance selection in early maturing barley, rapeseed (canola), and wheat', 'Government of Alberta', 1985, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/disease-resistance-selection-in-early-maturing-barley-rapeseed-canola-and-wheat', 'https://open.alberta.ca/dataset/e1623ee2-81cd-49ba-a32d-aa717da33aea/resource/1688da0a-b8b6-48b4-80fe-6a563f4925cf/download/0163010362966-disease-resistance-selection-in-early-maturing-barley-rapeseed-canola-and-wheat.pdf', NULL, NULL, 110, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study investigated the resistance reactions of thousands of lines and varieties of barley, wheat, and rapeseed to agriculturally important diseases in the Peace River Region. It tested and adapted methods, and in some cases developed screening lines for resistance under northern conditions. A major achievement was the development and application of a barley leaf scald screening system, which enabled resistance profiling and identification of 35 superior cultivars. The system was also applied to assess resistance to speckled leaf blotch in wheat. Additional research addressed barley leaf stripe, barley net blotch, common root rot, wheat smuts and bunts, and snow mould, with testing of screening methods and fungicide use. Seed treatments in canola rapeseed under heavy disease pressure improved establishment slightly but did not control root rot.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1af218c1-9d91-40aa-82d7-462df751d7a6', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Clustering Field-Based Maize Phenotyping of Plant-Height Growth and Canopy Spectral Dynamics Using a UAV Remote-Sensing Approach', 'Han L, Yang G, Yang H, Xu B, Li Z, Yang X', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01638', 'https://doi.org/10.3389/fpls.2018.01638', 'https://europepmc.org/articles/PMC6244040?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Phenotyping under field environmental conditions is often considered as a bottleneck in crop breeding. Unmanned aerial vehicle high throughput phenotypic platform (UAV-HTPP) mounted with multi-sensors offers an efficiency, non-invasive, flexible and low-cost solution in large-scale breeding programs compared to ground investigation, especially where measurements are time-sensitive. This study was conducted at the research station of the Xiao Tangshan National Precision Agriculture Research Center of China. Using the UAV-HTPP, RGB and multispectral images were acquired during four critical growth stages of maize. We present a method of extracting plant height (PH) at the plot scale using UAV-HTPP based on the spatial structure of the maize canopy. The core steps of this method are segmentation and spatial Kriging interpolation based on multiple neighboring maximum pixels from multiple plants in a plot. Then, the relationships between the PH extracted from imagery collected using UAV-HTPP and the ground truth were examined. We developed a semi-automated pipeline for extracting, analyzing and evaluating multiple phenotypic traits: canopy cover (CC), normalized vegetation index (NDVI), PH, average growth rate of plant height (AGRPH), and contribution rate of plant height (CRPH). For these traits, we identify genotypic differences and analyze and evaluate dynamics and development trends during different maize growth stages. Furthermore, we introduce a time series data clustering analysis method into breeding programs as a tool to obtain a novel representative trait: typical curve. We classified and named nine types of typical curves of these traits based on curve morphological features. We found that typical curves can detect differences in the genetic background of traits. For the best results, the recognition rate of an NDVI typical curve is 59%, far less than the 82.3% of the CRPH typical curve. Our study provides evidence that the PH trait is among the most heritable and the NDVI trait is among the most easily affected by the external environment in maize.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('123b61d1-fbe7-4002-9364-f1a743165cd9', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Consensus of costs and returns for fababeans, barley, canola and wheat in the Morinville district', 'Government of Alberta', 1986, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/consensus-of-costs-and-returns-for-fababeans-barley-canola-and-wheat-in-the-morinville-district', 'https://open.alberta.ca/dataset/982035b6-440a-4aa1-99ed-ab080fada3a6/resource/e4751689-34c0-4dc9-9e41-fa09598de66c/download/0163010253082-consensus-costs-returns-fababeans-barley-canola-wheat-morinville-district.pdf', NULL, NULL, 26, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report presents a consensus of costs and returns for producing fababeans, barley, canola, and wheat on a 1000-acre farm in the Morinville District. It details the Consensus Research Data (CRD) technique, which relies on group participation from local farmers to establish typical cost and return figures for specific agricultural practices. The report provides estimated operational and investment costs, along with expected returns, to assist producers in making informed management decisions regarding crop selection, cash requirements, labor allocation, new investments, and rental arrangements. This information serves as a guide for planning future production and comparing actual farm costs.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79b3d569-216d-469f-9e3d-9478612d6962', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Construction of a large-scale semi-field facility to study genotypic differences in deep root growth and resources acquisition', 'Simon Fiil Svane, Christian Sig Jensen, Kristian Thorup-Kristensen', 2019, 'Plant Methods', '10.1186/s13007-019-0409-9', 'https://doi.org/10.1186/s13007-019-0409-9', 'http://link.springer.com/article/10.1186/s13007-019-0409-9', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Background Roots are vital organs for plants, and the effective use of resources from the soil is important for yield stability. However, phenotypic variation in root traits among crop genotypes is mostly unknown and field screening of root development is costly and labour demanding. As a consequence, new methods are needed to investigate root traits of fully grown crops under field conditions, particularly roots in the deeper soil horizons. Results We developed a new phenotyping facility (RadiMax) for the study of root growth and soil resource acquisition under semi-field conditions. The facility consists of 4 units each covering 400 m2 and containing 150 minirhizotrons, allowing root observation in the 0.4 m–1.8 m or 0.7 m–2.8 m soil depth interval. Roots are observed through minirhizotrons using a multispectral imaging system. Plants are grown in rows perpendicular to a water stress gradient created by a multi-depth sub-irrigation system and movable rainout shelters. The water stress gradient allows for a direct link between root observations and the development of stress response in the canopy. Conclusion To test the concept and technical features, selected spring barley (Hordeum vulgare L.) cultivars were grown in the system for two seasons. The system enabled genotypic differences for deep root growth to be observed, and clear aboveground physiological response was also visible along the water stress gradient. Although further technical development and field validation are ongoing, the semi-field facility concept offers novel possibilities for characterising genotypic differences in the effective use of soil resources in deeper soil layers.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fc846d06-4b49-4b52-9718-b84e130a2e2d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Controlling barley diseases in direct seeding systems', 'Government of Alberta', 1996, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2374555', 'https://open.alberta.ca/dataset/20a35786-09d3-4b5a-ba28-210c146cbe54/resource/6fe87aa4-17e8-4d6d-8f05-f2931b1d209c/download/1999-519-13.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Disease control in barley requires proper management and sound agronomic practices no matter which tillage system is used. Weather conditions and crop rotations are usually much more influential than the tillage system in determining disease intensity in barley.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('23e51165-26e4-44f5-88a1-e937a59069c6', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Differential ABA sensitivity of superior and inferior rice grains is linked to cell cycle entry into endoreduplication', 'Chandran AKN, Irvin L, Dhatt BK, Chopra Y, McArtney S, Surpin MA, Reddy SK, Walia H', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1585022', 'https://doi.org/10.3389/fpls.2025.1585022', 'https://europepmc.org/articles/PMC12129772?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by', 'Suboptimal grain filling in rice (Oryza sativa) inferior spikelets poses a constraint to maximizing the yield potential. The differential grain filling between superior and inferior spikelets has been primarily attributed to differences in endogenous phytohormone levels that determine grain sink capacity. In this study, we aimed to gain molecular insights into the role of two phytohormones, abscisic acid (S-ABA or ABA) and cytokinin (6-benzyladenine or BA) through exogenous applications on superior and inferior grains in rice. We found that ABA and a combination of ABA and BA (ABA+BA) applications increased the grain yield in field studies, primarily by improving the grain weight of both superior and inferior grains. Transcriptomic analysis of developing grains shows differences in the expression of core cell cycle genes between the superior and inferior grains at four days after fertilization between the control and phytohormone applications. ABA and ABA+BA applications induce DNA replication genes and cell cycle inhibitory genes in superior grains only, likely promoting endoreduplication for increased cell storage capacity. ABA and BA applications suppressed the expression of cytokinin signaling genes in superior grains but induced them in inferior grains emphasizing the key roles for cytokinins and ABA in superior and inferior grains, respectively. An early induction of several grain storage-related genes in inferior grains is associated with accelerated entry into the grain storage stage, thus limiting sink capacity and poor grain fill. Our results indicate that ABA alone promotes photosynthate remobilization into both superior and inferior grains while ABA + BA regulates grain filling via cell cycle-related transcriptomic changes. Overall, our study reveals an intrinsic difference in ABA+BA sensitivity between inferior and superior grains that is linked to regulation of cell cycle checkpoints and entry into endoreduplication in the endosperm.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04d79988-e82d-4f58-a7e9-c25ba7facc0c', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Cost and returns budget for certified timothy seed production underseeded to barley', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2553294', 'https://open.alberta.ca/dataset/b9b668a7-5ef1-481f-8606-0cf26932e988/resource/f25110b0-41e2-407b-b293-6e360825fdc3/download/2001-127-821-4.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This budget estimates the direct income and expenses over a five-year life of a timothy stand on one acre. These numbers are only intended to assist producers in evaluating the basic financial requirements over this five year period. The budget margin must provide funds for interest, overhead and other indirect expenses as well as a return for living, loan repayment and investment. A total farm financial analysis should be completed to determine the affect of this enterprise on the total farm business.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c466c44b-538b-497c-b102-a1dbb5e9a1bb', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Cuticular wax biosynthesis in blueberries (Vaccinium corymbosum L.): Transcript and metabolite changes during ripening and storage affect key fruit quality traits', 'Yan Y, Gagalova KK, Gerbrandt EM, Castellarin SD', 2024, 'Horticulture research', '10.1093/hr/uhae004', 'https://doi.org/10.1093/hr/uhae004', 'https://europepmc.org/articles/PMC10923646?pdf=render', NULL, NULL, 16, NULL, 'canada', 3, 'cc by', 'In fruits, cuticular waxes affect fruit quality traits such as surface color at harvest and water loss during postharvest storage. This study investigated the transcriptional regulation of cuticular wax deposition in northern highbush blueberries (Vaccinium corymbosum L.) in relation to fruit water loss and surface color during ripening and postharvest storage, as well as the effects of abscisic acid (ABA)-mediated changes in cuticular wax deposition on these fruit quality traits. Total cuticular wax content (μg∙cm-2) decreased during fruit ripening and increased during postharvest storage. Transcriptome analysis revealed a transcript network for cuticular wax deposition in blueberries. Particularly, five OSC-Likes were identified as putative genes for triterpene alcohol production, with OSC-Like1 and OSC-Like2 encoding mixed amyrin synthases, OSC-Like3 encoding a lupeol synthase, and OSC-Like4 and OSC-Like5 encoding cycloartenol synthases. The expression of three CYP716A-like genes correlated to the accumulation of two triterpene acids oleanolic acid and ursolic acid, the major wax compounds in blueberries. Exogenous ABA application induced the expression of triterpenoid biosynthetic genes and the accumulation of β-amyrin and oleanolic acid, as well as increased the ratio of oleanolic acid to ursolic acid. These changes were associated with reduced fruit water loss. The content of β-diketones was also increased by ABA application, and this increase was associated with increased fruit lightness (measured as L* using CIELAB Color Space by a colorimeter). This study provided key insights on the molecular basis of cuticular wax deposition and its implications on fruit quality traits in blueberries.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9c4dc22e-52e5-49e1-8044-06324d49504d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Determination of optimum nitrogen fertilizer and seed rates on yield and quality of malt barley in North Eastern, Ethiopia', 'Amare Aleminew, Abirha Alemu, Kedir Endris', 2026, 'Discover Plants', '10.1007/s44372-026-00612-1', 'https://doi.org/10.1007/s44372-026-00612-1', 'https://doi.org/10.1007/s44372-026-00612-1', NULL, NULL, 18, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Low soil fertility and inappropriate plant populations were the major factors affecting malt barley production in high land areas of North Eastern Ethiopia. To adders these issues the experiment was conducted in major malt barley growing areas of North Eastern Ethiopia at Kone, Estayish and Legambo in two cropping seasons of 2019 and 2020. The objective was to determine optimum and economical nitrogen rate for yield and quality of malt barley; and to determine optimum seed rate for yield and quality of malt barley. The experiment was designed in factorial arrangement of randomized complete block consisting of four nitrogen fertilizer rates (0, 60, 120 & 180 kg N ha−1) and four seed rates (75, 100, 125 & 150 kg ha−1) were used. Basal applications of phosphorus fertilizer of 69 kg ha−1 as P2O5 were applied. Results revealed that N fertilizer rates had a significant effect on growth, yield and grain quality of malt barley. Generally, the highest grain yield (3.28 ton ha−1) of malt barley positively responded with application of 180 kg ha−1 N fertilizer. Highest grain yield of malt barley was obtained from 100–150 kg ha−1 seed rates. Therefore, seeding rates of 100 kg ha−1 was economically feasible for malt barley production. Grain protein contents were acceptable ranges from 9.3 to 11.2%. Hence, N fertilizer rates of 180 kg N ha−1 and 100 kg ha−1 seeding rates of malt barley were economically optimum and recommendable rates for malting barley production in Kone, Estayish and Legambo areas and in similar agro-ecologies.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9cf3042b-77c0-48f5-92f5-df106a51675d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Development of a phenotyping platform for high throughput screening of nodal root angle in sorghum', 'Joshi DC, Singh V, Hunt C, Mace E, van Oosterom E, Sulman R, Jordan D, Hammer G', 2017, 'Plant methods', '10.1186/s13007-017-0206-2', 'https://doi.org/10.1186/s13007-017-0206-2', 'https://europepmc.org/articles/PMC5504982?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'BackgroundIn sorghum, the growth angle of nodal roots is a major component of root system architecture. It strongly influences the spatial distribution of roots of mature plants in the soil profile, which can impact drought adaptation. However, selection for nodal root angle in sorghum breeding programs has been restricted by the absence of a suitable high throughput phenotyping platform. The aim of this study was to develop a phenotyping platform for the rapid, non-destructive and digital measurement of nodal root angle of sorghum at the seedling stage.ResultsThe phenotyping platform comprises of 500 soil filled root chambers (50 × 45 × 0.3 cm in size), made of transparent perspex sheets that were placed in metal tubs and covered with polycarbonate sheets. Around 3 weeks after sowing, once the first flush of nodal roots was visible, roots were imaged in situ using an imaging box that included two digital cameras that were remotely controlled by two android tablets. Free software (openGelPhoto.tcl) allowed precise measurement of nodal root angle from the digital images. The reliability and efficiency of the platform was evaluated by screening a large nested association mapping population of sorghum and a set of hybrids in six independent experimental runs that included up to 500 plants each. The platform revealed extensive genetic variation and high heritability (repeatability) for nodal root angle. High genetic correlations and consistent ranking of genotypes across experimental runs confirmed the reproducibility of the platform.ConclusionThis low cost, high throughput root phenotyping platform requires no sophisticated equipment, is adaptable to most glasshouse environments and is well suited to dissect the genetic control of nodal root angle of sorghum. The platform is suitable for use in sorghum breeding programs aiming to improve drought adaptation through root system architecture manipulation.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cde1ec7c-2bf2-4cc8-8eee-47eef4686c42', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Effects of total crop straw return on soil fertility and field ecological environment', 'HONG Chun-lai, WEI You-zhang, HUANG Jin-fa, WANG Run-yi, YANG Xiao-e', 2003, '浙江大学学报. 农业与生命科学版', '10.3785/1008-9209.2003.06.0627', 'https://doi.org/10.3785/1008-9209.2003.06.0627', 'https://www.academax.com/doi/10.3785/1008-9209.2003.06.0627', NULL, NULL, 7, NULL, 'other', 1, 'open access (DOAJ)', 'Two years field experiments on application of total crop straw return were carried out. Results showed that rice tillering and barley seeding ratio was not apparently influenced by application of total crop straw return combined with normal fertilization. The level of soil fertility was increased, the organic matter content was increased from the previous 4.23% to 4.38%, readily available P and K from 83 mg/kg and 6.9 mg/kg to 110.2 mg/kg and 11.7 mg/kg respectively, total nitrogen from 0.205% to 0.229%, whereas the net increase of available nitrogen was 25.5 mg/kg. Field ecological environment was considerably improved. Weed incidence rate was decreased by 2/3 or so. In winter, the gap between maximum temperature to minimum temperature in 0-20 cm depth of soil was lessened effectively. Under the condition of total crop straw return treatment the minimum soil temperature was 1-2.5℃ higher than that of the control and the maximum temperature was 1-3℃ lower. The water content in silt loam soil for the total crop straw return treatment was 1.5%-3% higher than that for the control. The crop yield was enhanced by application of total crop straw return.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('48bdebbd-f5ba-43a3-a9ac-d3528804b00f', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Diversity and structure of the rhizosphere microbial communities of wild and cultivated ginseng', 'Fang X, Wang H, Zhao L, Wang M, Sun M', 2022, 'BMC microbiology', '10.1186/s12866-021-02421-w', 'https://doi.org/10.1186/s12866-021-02421-w', 'https://europepmc.org/articles/PMC8721995?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'BackgroundThe resources of wild ginseng have been reducing sharply, and it is mainly dependent on artificial cultivation in China, Korea and Japan. Based on cultivation modes, cultivated ginseng include understory wild ginseng (the seeds or seedlings of cultivated ginseng were planted under the theropencedrymion without human intervention) and farmland cultivated ginseng (grown in farmland with human intervention). Cultivated ginseng, can only be planted on the same plot of land consecutively for several years owing to soilborne diseases, which is mainly because of the variation in the soil microbial community. In contrast, wild ginseng can grow for hundreds of years. However, the knowledge of rhizosphere microbe communities of the wild ginseng is limited.ResultIn the present study, the microbial communities in rhizosphere soils of the three types of ginseng were analyzed by high-throughput sequencing of 16 S rRNA for bacteria and internal transcribed spacer (ITS) region for fungi. In total, 4,381 bacterial operational taxonomic units (OTUs) and 2,679 fungal OTUs were identified in rhizosphere soils of the three types of ginseng. Among them, the shared bacterial OTUs was more than fungal OTUs by the three types of ginseng, revealing fungal communities were to be more affected than bacterial communities. In addition, the composition of rhizosphere microbial communities and bacterial diversity were similar between understory wild ginseng and wild ginseng. However, higher bacterial diversity and lower fungal diversity were found in rhizosphere soils of wild ginseng compared with farmland cultivated ginseng. Furthermore, the relative abundance of Chloroflexi, Fusarium and Alternaria were higher in farmland cultivated ginseng compared to wild ginseng and understory wild ginseng.ConclusionsOur results showed that composition and diversity of rhizosphere microbial communities were significantly different in three types of ginseng. This study extended the knowledge pedigree of the microbial diversity populating rhizospheres, and provided insights into resolving the limiting bottleneck on the sustainable development of P. ginseng crops, and even the other crops of Panax.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b374fd53-579e-4633-a2f9-4539d87463f7', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Drought response of water-conserving and non-conserving spring barley cultivars', 'Mercy Appiah, Issaka Abdulai, Alan H. Schulman, Alan H. Schulman, Menachem Moshelion, Elvira S. Dewi, Elvira S. Dewi, Agata Daszkowska-Golec', 2023, 'Frontiers in Plant Science', '10.3389/fpls.2023.1247853', 'https://doi.org/10.3389/fpls.2023.1247853', 'https://www.frontiersin.org/articles/10.3389/fpls.2023.1247853/full', NULL, NULL, 13, NULL, 'other', 1, 'open access (DOAJ)', 'IntroductionBreeding barley cultivars adapted to drought requires in-depth knowledge on physiological drought responses.MethodsWe used a high-throughput functional phenotyping platform to examine the response of four high-yielding European spring barley cultivars to a standardized drought treatment imposed around flowering.ResultsCv. Chanell showed a non-conserving water-use behavior with high transpiration and maximum productivity under well-watered conditions but rapid transpiration decrease under drought. The poor recovery upon re-irrigation translated to large yield losses. Cv. Baronesse showed the most water-conserving behavior, with the lowest pre-drought transpiration and the most gradual transpiration reduction under drought. Its good recovery (resilience) prevented large yield losses. Cv. Formula was less conserving than cv. Baronesse and produced low yet stable yields. Cv. RGT’s dynamic water use with high transpiration under ample water supply and moderate transpiration decrease under drought combined with high resilience secured the highest and most stable yields.DiscussionSuch a dynamic water-use behavior combined with higher drought resilience and favorable root traits could potentially create an ideotype for intermediate drought. Prospective studies will examine these results in field experiments and will use the newly gained understanding on water use in barley to improve process descriptions in crop simulation models to support crop model–aided ideotype design.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f3886d93-e1e4-458e-bd20-bf1790f9db36', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Duke''s lessons learned : Project Barley evaluation report', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/dukes-lessons-learned-project-barley-evaluation-report', 'https://open.alberta.ca/dataset/eb1f7d0e-f456-42b3-968f-54f3161331eb/resource/1325bd2e-7d6f-488f-8485-e9c9fcc389cc/download/0163010070254-dukes-lessons-learned-project-barley-evaluation-report.pdf', NULL, NULL, 125, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document presented a comprehensive evaluation of Project Barley, a 1995 pilot initiative by Alberta Agriculture, Food and Rural Development to deliver agricultural information and services electronically through the Internet. It documented the project''s objectives, implementation approach, training programs, kiosk deployment, technical infrastructure, content development processes, producer participation, and multi‑stakeholder feedback. It detailed challenges such as technology limitations, varying service provider support, staff readiness and timing, along with successful outcomes including strong producer interest, high post‑pilot Internet adoption and recognition of the department''s leadership in digital service delivery. It also outlined future vision elements, critical success factors and a recommended organizational structure for scaling Internet‑based agricultural information services.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f7f938c0-a358-4fbb-b8da-2293fce82569', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Fusarium head blight of barley and wheat [2020]', 'Government of Alberta', 2020, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/fusarium-head-blight-of-barley-and-wheat', 'https://open.alberta.ca/dataset/107529dc-b4fd-4950-9fbf-e963f5af988c/resource/c3ff2518-471d-4709-b753-88efb4d3ae41/download/af-fusarium-head-blight-barley-and-wheat.pdf', NULL, NULL, 27, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Fusarium head blight is a fungal disease of wheat, barley, oats and other small cereal grains and corn. This publication provides information on the disease, including its history in Canada and Alberta, symptoms and effects of the disease, and steps that can be taken to manage fusarium head blight.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4851bf05-9754-4a80-a3a1-40867ddebe85', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'EFFECT OF BIO AND MINERAL FERTILIZATION ON NAKED BARLEY UNDER RAINFED AND SUPPLEMENTAL IRRIGATION CONDITIONS AT MATROUH AREA, EGYPT', 'M. Abd El-Aziz, E. Esmael, N. Moselhy, El-M. El-Metwally', 2010, 'Journal of Plant Production', '10.21608/jpp.2010.86586', 'https://doi.org/10.21608/jpp.2010.86586', 'https://jpp.journals.ekb.eg/article_86586_d55073f3ea897ae9c2b394a702fe05cc.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Two experiments were carried out during the 2006/07 and 2007/08 winter seasons at El- Hammam area, Matrouh, Egypt to investigate the influences of supplemental irrigation (SI) and fertilization package (FP) under rainfed conditions on productivity of naked barley (Hordeum vulgare L.). Each experiment included 28 treatments which were; four amounts of supplemental irrigation (SI) i.e. SI0): rainfed only; SI1): 60 mm/ fad; SI2): 90 mm/ fad and SI3): 120 mm/ Fad. and seven fertilization packages (FP) treatments i.e. FP0): without fertilization; FP1): Bio-N; FP2): 20 Kg N/ Fad. + 7.5 Kg P2 O5/ Fad. + 12 Kg K2O/ Fad.; FP3): 20 Kg N/ Fad. + 7.5 Kg P2 O5/ Fad. + 12 Kg K2O/ Fad. + Bio-N; FP4): 40 Kg N/ Fad. + 15 Kg P2O5/ Fad. + 24 Kg K2 O/ fad; FP5): 40 Kg N/ Fad. + 15 Kg P2O5/ Fad. + 24 Kg K2O/ Fad. +Bio-N; and FP6): 80 Kg N/ Fad. +30 Kg P2O5/ Fad. + 48 Kg K2O/ Fad.). Results showed significant differences among supplemental irrigation treatments in all the studied traits in both seasons. Also, results clearly showed that grain, straw and biological yields were increased by each increment in amount of water supply from 60 to 90 then to 120 mm/ Fad. in the two seasons. It is evident that grain yield increased by 23.0, 82.7 and 111.1 % and by 22.9, 81.7 and 110.8 % in the first and the second seasons, respectively, due to increase of the added water supply amounts from 60 to 90 then to 120 mm/ Fad. in respective order. Results indicated that FP3 treatment application which included 20 Kg N + 7.5 Kg P2O5 + 12 Kg K2O / Fad. + Bio-N gave the tallest plants, longest spikes, heaviest 1000-grain weight, as well as, the highest values of grain, straw and biological yields, as well as, water use efficiency compared to the other tried fertilization packages here in both seasons. It is evident that the positive response of naked barley plants was only to add 20, 7.5 and 12 Kg of N, P2O5 and K2O/ Fad. in respective order, in addition to bio-N fertilizer as a package i.e. FP3. Ultimately, to gain high productivity of naked barley economically, it could be adding SI by amount of 120 mm/ Fad. with applying FP i.e. 20 kg N/ Fad. +7.5 kg P2O5/ Fad. +12 kg K2O + Bio-N/ Fad. could be recommended under rainfed conditions at El-Hammam area, NWC of Egypt.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a6eee6d1-9880-4d4e-a0cd-0cf8c873991b', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Effect of Endophytic Microorganisms on Growth Rate of Crops', 'Elizaveta R. Faskhutdinova, Natalia N. Bogacheva, Ekaterina E. Borodina, Anna V. Pozdnyakova, Sergey L. Luzyanin', 2024, 'Техника и технология пищевых производств', '10.21603/2074-9414-2024-4-2548', 'https://doi.org/10.21603/2074-9414-2024-4-2548', 'https://fptt.ru/en/issues/23109/23155/', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Increasing the yield of wheat, barley, and oats is a pressing issue. It largely depends on soil fertility. Mineral fertilizers, however, may be ineffective and unsustainable. As a result, microorganisms seem to be a promising alternative. The authors isolated endophytic microorganisms with growth-stimulating properties and assessed their effect on the growth rate of wheat, barley, and oats in laboratory conditions. The research involved spring soft wheat of the Sibirsky Alyans variety, spring oats of the Maruchak variety, spring barley of the Nikita variety, and standard bacterial strains (Azospirillum brasilense B-11094, Azotobacter chrococcum B-8739). The isolated bacteria were identified using a Vitex 2 Compact automatic microbiological analyzer. The production potential for indole-3-acetic and gibberellic acids was assessed spectrophotometrically. The nitrogen fixation potential was determined using a Rapid N Cube. The phosphate-solubilizing potential was tested on a calcium phosphate medium. The effect of the most promising strains on the growth rate was assessed in laboratory conditions. Seven isolates of endophytic microorganisms were identified as Pantoea allii Tri, Bacillus subtilis Tri 2, Bacillus subtilis Ave 1, Pantoea allii Ave 2, Bacillus subtilis Hor 1, Bacillus subtilis Hor 2, and Bacillus subtilis Hor 3. The most promising growth promoters ranged as follows. Bacillus subtilis Ave 1 fixed 790 μg/mL nitrogen, solubilized phosphates with index 1.60, and produced 7100 μg/mL indolyl-3-acetic acid and 343 μg/mL gibberellic acid. Bacillus subtilis Hor 1 fixed 760 μg/mL nitrogen, solubilized phosphates with index 1.44, and synthesized 4490 μg/mL indolyl-3-acetic acid and 409 μg/mL gibberellic acid. Bacillus subtilis Ave 1 demonstrated the greatest growth-stimulating activity. Bacillus subtilis Ave 1 could synthesize phytohormones, fix atmospheric nitrogen, and solubilize phosphates, which indicated good agricultural prospects. The strain increased the length of shoots and roots in wheat and barley, as well as boosted germination and shoot length in oats.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8a03b513-7830-45aa-9861-396e9f358336', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'EFFECT OF IRRIGATION MANAGEMENT ON CROP PRODUCTION FOR A DROUGHT-TOLERANT GENOTYPE OF BARLEY', 'I. H. El-Sheikh, E. M. Hokam', 2007, 'Journal of Soil Sciences and Agricultural Engineering', '10.21608/jssae.2007.201561', 'https://doi.org/10.21608/jssae.2007.201561', 'https://jssae.journals.ekb.eg/article_201561_6eb795a4a694f6719260281760831a84.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'The effect of sprinkler irrigation management on barley yield, soil moisture distribution and water use efficiency was studied under field conditions. A field experiment was conducted in 2005/2006 growing season in sandy loam soil, at Wadii-Ghepeen (Bani-Waleid Governorate, Libya),. A drought-tolerant genotype of barley (Hordeum vulgare L.: AKSAD 67) was irrigated by semi-portable sprinkler irrigation system with a local well-water (electrical conductivity of 2.7 dS m-1). The experiment included two factors: The frist factor was two levels of sprinkler distance: 12 and 6 m, and the second factor was two levels of working hours: 2 and 3 h. The control treatment was that recomended in the region (i. e. 12 m sprinkler distance and 5 working hours). So, the experiment consisted of five treatments, namely: 12 m × 3 h.; 6 m × 3 h.; 12 m × 2 h.; 6 m × 2 h. and 12 m × 5 h., labeled as A, B, C, D and Co, respectively. To evaluate the performance of the sprinkler system and yield response to different treatments, many field measurements were achieved: local rainfall; sprinkler discharge (under working pressure of 2 bar); uniformity coefficient; total dry matter ; grain yield and water use efficiency. Also, change of soil moisture contents; seed germination percent and crude protin- were determined. The main results can be summarized as follows: in general, the results indicated that both total dry and grain yields were increased as irrigation water amount decreased. The lowest water ammount was consumed under C treatment, therefore, appeared the highest water use efficiency.The statistic analsys shown that, there was no significant effect between sprinkler distances, while significant and high significant effect were found in both working hours and the interaction of sprinkler distance and working hours, respectively. The results indicate that maximum uniformity coefficient was found under 6 m treatments (i. e. B and D treatments). Germination test showed that, there was no observed effect as difference among all treatments. Following of soil moisture changes after irrigation, indicated that, it is not necessary to bring up soil moisture content to 100% of soil field capacity, while 50% of soil field capacity was found to be optimum amount for high yield production. Such irrigation water quality can be safely used, where the precipitation can prevents salt accumulation hazard.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b0ade54a-21cd-4686-acf6-f1fe2fa9ae75', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'EFFECT OF IRRIGATION SCHEDULING AND NITROGEN FERTILIZATION ON BARLEY YIELD AND WATER USE EFFICIENCY', 'N. A. Anton, F. A. F. Khalil, M. F. S. Abd El-Rahman', 2012, 'Journal of Soil Sciences and Agricultural Engineering', '10.21608/jssae.2012.54336', 'https://doi.org/10.21608/jssae.2012.54336', 'https://jssae.journals.ekb.eg/article_54336_ebcea19acab52ca11f06474e37e18520.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'A field trial was conducted at Giza Agricultural Research Station during the two successive seasons 2009/2010 and 2010/2011 to study the response of barley to different irrigation regimes induced due to irrigating according to 1.1 (wet irrigation regime), 0.9 (medium irrigation regime) and 0.7(dry irrigation regime) coefficients for the accumulative pan evaporation (APE) records in combination with nitrogen fertilization rates of 0, 15, 30 and 45 kg Nfed-1. Results of combined analysis could be summarized as follows:- 1. The assessed irrigation regimes had a significant effect on plant height, spike length, number of spikes m-2, number of grains spike-1, 1000 kernels weight, biological yield fed-1., harvest index, grain and straw yields. The highest values of such characters were obtained for wet irrigation regime (1.1 APE) followed by medium (0.9 APE) and dry (0.7APE) ones, respectively. Protein content of barley grains increased as plants were imposed to severe water stress (dry irrigation regime, 0.7 APE). 2. Seasonal water consumptive use (WCU) was increased under wet irrigation regime (1.1 APE coefficient). Whereas, water use efficiency (WUE) increased under medium irrigation regime (0.9 APE coefficient). 3. Appling 45 kg N fed-1 significantly increased plant height, spike length, number of spikes m-2, number of grains spike-1, 1000 kernels weight, biological yield, harvest index, grain and straw yields. Furthermore, protein content of grains, seasonal water consumptive use (WCU) and water use efficiency (WUE) tended to increase due to the highest N- rate. 4. The interaction effect between irrigation regimes and nitrogen fertilization rates was found to be significant for growth, yield and its components characters. The maximum values of plant height, spike length, number of spikes m-2, number of grains spike-1, 1000- kernel weight, biological yield, harvest index, grain and straw yields were obtained as barley irrigated at 1.1 APE coefficient under 45 kg N fed-1 rate. Higher water consumptive use (WCU) values resulted from interaction of wet irrigation regime (1.1APE) and 45 kg N fed-1 rate. Whereas, the highest values of water use efficiency (WUE) were recorded as barley plants were irrigated at medium irrigation regime (0.9 APE) under 45 kg N fed-1. The maximum values of protein content in barley grains were obtained due to irrigating at the dry irrigation regime (0.7 APE) in combination with 45 kg Nfed-1 rate.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3599b4ee-91c2-436d-986b-534008f807d2', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Effect of lactic acid bacterial inoculant on the fermentation characteristics of barley silage', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/effect-of-lactic-acid-bacterial-inoculant-on-the-fermentation-characteristics-of-barley-silage', 'https://open.alberta.ca/dataset/45c6eb91-498d-4b44-b4e1-d0b60b3a81e3/resource/7e1f27b8-79bf-43d0-99e1-313574471b49/download/0163010393342-effect-lactic-acid-bacterial-inoculant-fermentation-characteristics-barley-silage.pdf', NULL, NULL, 100, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported the findings of a research project that evaluated the effect of a lactic acid bacterial inoculant on the fermentation characteristics and digestibility of whole crop barley silage. It described the study objectives, experimental design, and methods used to compare inoculated and untreated silage under practical ensiling conditions in Alberta. The scope included measurements of fermentation parameters, chemical composition, temperature changes, and in situ ruminal degradation of dry matter and fibre components. The document presented results and discussion for two related study components and summarized conclusions on the effectiveness of the inoculant. It also outlined the implications of the findings for agricultural knowledge and forage management in Alberta.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9d743b6e-e81c-4b2e-8d56-5fdc5628afdb', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'EFFICIENCY OF FERTILIZER APPLICATION IN GROUPS OF AGRICULTURAL CROPS DEPENDING ON THE LEVEL OF WATER REGIME IN THE ROSTOV REGION', 'I. N. Ilinskaya, V. A. Kulygin', 2020, 'Научный журнал Российского НИИ проблем мелиорации', '10.31774/2222-1816-2020-4-71-87', 'https://doi.org/10.31774/2222-1816-2020-4-71-87', 'http://www.rosniipm-sm.ru/article?n=1160', NULL, NULL, 17, NULL, 'other', 1, 'open access (DOAJ)', 'Purpose: to determine the efficiency of mineral fertilizers and the agricultural crops response degree for the main groups (cereals, fodder, legumes and industrial crops, potatoes and vegetables) during irrigation in the aspect of resource saving. Materials and methods: the research was carried out in the Central irrigated zone of Rostov region (FSUE “Semikarakorskoe”). The object of research is different groups of agricultural crops, their reaction to the nutrient status at different levels of moisture supply. The soils of the experimental site are represented by ordinary chernozems. Field observations, research and data processing were carried out according to generally accepted methods: B. A. Dospekhov, A. N. Kostyakov, M. M. Goryanskiy. Results: as a result of the research, it was revealed that regardless the fertilizer status, the calculated water regime contributes to the agricultural crops yield increase by an average of 1.6–3.2 times in comparison with dry conditions. The calculated soil water regime contributed to a significant increase in the efficiency of fertilizers relative to rainfed growing conditions. Under different mineral fertilizers backgrounds, the maximum effect from their use increased: in the group of grain crops (spring barley) by 3.09 times, fodder (alfalfa of previous years) by 2.93 times, legumes (peas) by 2.86 times and potatoes by 4.25 times. Conclusions: the greatest effect from the fertilizers application under irrigation conditions was shown by potatoes, vegetables and grain crops. The highest return on fertilizers by an increase in yield was noted in the cultivation of alfalfa (12.67–13.83 kg) and Sudanese grass (22.00–23.44 kg), as well as potatoes (26.37–24.22 kg) and vegetable crops (22.6–33.4 kg). A severe water regime with a slight decrease in the yield of agricultural crops contributes to the irrigation water saving up to 1050–1580 m3/ha, which is very urgent under conditions of water scarcity.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d6f34060-ec87-4ad0-8095-586c4ed2cc25', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Enhanced grain quality of malt barley (Hordeum distichon L.) in response to mixed use of organic compost and mineral nitrogen rates.', 'Arega Wole, Amsalu Nebiyu, Getachew Agegnehu, Yenus Ousman', 2026, 'PLoS ONE', '10.1371/journal.pone.0343009', 'https://doi.org/10.1371/journal.pone.0343009', 'https://doi.org/10.1371/journal.pone.0343009', NULL, NULL, 27, NULL, 'other', 1, 'open access (DOAJ)', 'Declining soil fertility status and poor agronomic management practices are major factors of declining quality for malt barley in the Ethiopian highland area, particularly in the study area. To address these major challenges, a two-year (2022-2023) field experiment was conducted in experimental fields in the Welmera district to evaluate the effects of mixed-use mineral N fertilization and compost rates on malt barley quality parameters. A randomized complete block design with factorial arrangements of five N rates (0, 23, 46, 69, and 92 kg ha-1) and four compost rates (0, 2.5, 5, and 7.5 t ha-1) was tested in three replications. According to the results, both compost and mineral nitrogen fertilizer were significantly influenced thousand-seed weight, protein content, malt extract, beta-glucan content, malt friability and germination energy of malt barley grain, with seasonal variations. Increased mineral N levels enhanced seed weight and grain protein content but reduced malt extract yield and malt friability, while compost improved grain protein content and malt beta-glucan. These influences were improved by organic compost and mineral fertilization, which enhanced multiple quality parameters. The results clearly demonstrated that application of 69 kg N ha-1 and 5 t ha-1 of compost rate in moderation, which optimized the malt quality parameters, met industry standards without increasing protein concentration or diminishing malt extract yield of malt barley grain. These mixed management approaches not only enhance the quality of malt barley grain for the beer industry but also help soil fertility restoration and guarantee long-term production sustainability for smallholder farmers in the Ethiopian highlands. For robust and wide applicability, subsequent multiple-seasons and multiple-locations studies with additional quality assessments are recommended.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d93426df-3320-4870-b880-62c8600f9394', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Evaluation of full-fat canola and barley in commercial broiler diets', 'Government of Alberta', 1991, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/evaluation-of-full-fat-canola-and-barley-in-commercial-broiler-diets', 'https://open.alberta.ca/dataset/d1713cfa-a8e8-4c4a-8dd0-e496c5b1e811/resource/8714889e-62cc-48b4-b117-fd467392517b/download/0163010361851-evaluation-of-full-fat-canola-and-barley-in-commercial-broiler-diets.pdf', NULL, NULL, 23, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study conducted two experiments with a total of 22,848 broilers to evaluate the use of barley with full-fat canola seed (barlcan) as an alternative to traditional cereal and protein sources in broiler diets, using both high and low energy densities. The results showed that dietary energy source had little or no effect on final weights or feed conversions, although increased energy density improved both measures in the first experiment but not in the second. Diets containing barlcan reduced feed costs per marketed bird compared to wheat-soybean meal diets, though returns per bird were slightly higher with wheat-soybean meal due to heavier bird weights. The study concluded that barlcan is a practical and economical component of broiler diets; however, it noted that increasing energy density might not have been economically advantageous given the feedstuff cost relationships in September 1991.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c248e6d4-18e9-414b-85b0-3d0bcb4def9f', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Evaluation of phytotoxicity of three organic amendments to collard greens using the seed germination bioassay', 'Kebrom TH, Woldesenbet S, Bayabil HK, Garcia M, Gao M, Ampim P, Awal R, Fares A', 2019, 'Environmental science and pollution research international', '10.1007/s11356-018-3928-4', 'https://doi.org/10.1007/s11356-018-3928-4', 'https://europepmc.org/articles/PMC6407736?pdf=render', NULL, NULL, 9, NULL, 'other', 1, 'cc by', 'Small-scale vegetable and fruit crop producers in the USA use locally available commercial organic fertilizers and soil amendments recycled from municipal and agricultural wastes. Organic soil amendments provide crops with their nutrient needs and maintain soil health by modifying its physical, chemical, and biological properties. However, organic soil amendments might add unwanted elements such as toxic heavy metals or salts, which might inhibit crop growth and reduce yield. Therefore, the objective of this study was to evaluate phytotoxicity of three commercial organic amendments, chicken manure, milorganite, and dairy manure, to collard greens using the seed germination bioassay and chemical analysis of the organic amendments. The seed germination bioassay was conducted by incubating collard greens seeds to germinate in 1:10 (w/v) organic amendment aqueous extracts. Results of this work identified phytotoxic effects of chicken manure and milorganite, but not dairy manure, to collard greens. Potentially phytotoxic chemicals such as copper, zinc, nickel, and salts were also higher in chicken manure and milorganite compared to dairy manure. In particular, nickel in chicken manure and milorganite aqueous extracts was 28-fold and 21-fold, respectively, higher than previously reported toxic levels to wheat seedlings. The results demonstrate the need for more research on phytotoxicity of commercial organic soil amendments to ensure their safe use in vegetable and fruit crop production systems.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eaace36a-3b4a-42d0-ad6a-addc2b8f7c4e', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Exploring the potential of naked barley to manage deoxynivalenol accumulation from Fusarium head blight', 'Ige AD, Hawkins J, Dong Y, Meints B, Smith K', 2026, 'TAG. Theoretical and applied genetics. Theoretische und angewandte Genetik', '10.1007/s00122-025-05118-0', 'https://doi.org/10.1007/s00122-025-05118-0', 'https://europepmc.org/articles/PMC12909475?pdf=render', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc by', 'Developing and deploying multi-use naked barley varieties that accumulate lower levels of deoxynivalenol (DON) resulting from Fusarium head blight (FHB) disease could help farmers mitigate economic risks and expand market possibilities. Previous work established that a substantial amount of DON in covered barley accumulates in the hull and can be removed by pearling. We studied a diverse panel of 244 naked barley lines to determine if there is a genetic variation for the distribution of DON in Fusarium-infected spikes. We evaluated the panel genotyped with a 50K Barley SNP array for disease severity, toxin accumulation, and other agronomic traits in two FHB disease nurseries from 2020 to 2021. Harvested naked barley spikes separated into hull and kernel fractions revealed that 11.92-70.02% of the total toxins were localized in the hull. Single-SNP and haplotype-based genome-wide association studies (GWAS) were carried out using mixed linear models. Based on the single-SNP GWAS, 132 marker-trait associations, localized into 13 quantitative trait loci, were identified for all the traits except FHB severity. Haplotype-based GWAS found two haplotype-trait associations each for DON in hull and plant height, three for DON in rachis, and five for heading date. Notably, markers and haplotypes associated with later heading were also linked to higher levels of the toxin in the hull but not the kernel. Moderate-to-high predictive abilities suggest that genomic selection could be used to develop improved naked barley cultivars with a lower risk of DON contamination.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0fe874ad-814b-47f2-a815-f4884da61fa7', 'e674c556-4770-485c-ba28-262e36c330bf', 'Understanding the Influence of Secondary Metabolites in Plant Invasion Strategies: A Comprehensive Review', 'Akbar R, Sun J, Bo Y, Khattak WA, Khan AA, Jin C, Zeb U, Ullah N', 2024, 'Plants (Basel, Switzerland)', '10.3390/plants13223162', 'https://doi.org/10.3390/plants13223162', 'https://europepmc.org/articles/PMC11597624?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'The invasion of non-native plant species presents a significant ecological challenge worldwide, impacting native ecosystems and biodiversity. These invasive plant species significantly affect the native ecosystem. The threat of invasive plant species having harmful effects on the natural ecosystem is a serious concern. Invasive plant species produce secondary metabolites, which not only help in growth and development but are also essential for the spread of these plant species. This review highlights the important functions of secondary metabolites in plant invasion, particularly their effect on allelopathy, defense system, interaction with micro soil biota, and competitive advantages. Secondary metabolites produced by invasive plant species play an important role by affecting allelopathic interactions and herbivory. They sometimes change the soil chemistry to make a viable condition for their proliferation. The secondary metabolites of invasive plant species inhibit the growth of native plant species by changing the resources available to them. Therefore, it is necessary to understand this complicated interaction between secondary metabolites and plant invasion. This review mainly summarizes all the known secondary metabolites of non-native plant species, emphasizing their significance for integrated weed management and research.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2655f48d-ddfd-414a-b684-fc4b76ec67b1', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Foxtail barley control in direct seeding systems', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4007953', 'https://open.alberta.ca/dataset/fb14756e-33e0-4347-b25a-70e4fa97d01f/resource/73a31f26-b2e5-44e3-b1d0-9b27611369b7/download/2007-519-15.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Foxtail barley is a tough-to-control perennial weed in zero tillage systems. Herbicides containing glyphosate can effectively control seedlings at relatively low rates with much higher rates required for control of mature plants. Cultural practices that encourage a competitive crop, such as high seeding rates and banding of nitrogen fertilizer, help to reduce yield losses and slow the spread of foxtail barley.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35179c31-1f8c-4675-880d-12c9a6d3dd62', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Functional properties and potential food applications of barley beta-glucan concentrate', 'Government of Alberta', 1996, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/functional-properties-and-potential-food-applications-of-barley-beta-glucan-concentrate', 'https://open.alberta.ca/dataset/5547a9a6-ec84-4cb9-bcfb-ac50adbc496e/resource/fd2ce5ce-3ae7-4e1a-bf9c-14f11cc88ece/download/0163010144927-functional-properties-potential-food-applications-barley-beta-glucan-concentrate.pdf', NULL, NULL, 66, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document examined the functional properties of β-glucan concentrates (BGC) extracted from waxy and non-waxy (Condor) barley varieties using milling, sieving, and solvent extraction techniques. The resulting products contained approximately 15 per cent and more than 70 per cent β-glucans, respectively. Extracts with higher β-glucan content demonstrated superior whippability, foam stability, emulsion stability, solubility, and viscosity compared to sieved products and conventional gums such as guar and arabic. Optimal extraction conditions were identified at 55 degrees Celsius and pH seven to eight, and heat treatment was found essential to inactivate endogenous β-glucanase enzymes. The study also evaluated the impact of various food ingredients on BGC viscosity and observed protein precipitation when BGC was added to milk or whey. Low-viscosity extracts formed gels at concentrations above 5 per cent. The findings support the use of BGC as a thickener, stabilizer, or gelling agent in food products and highlight its potential for value-added barley processing in Alberta.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2f94b356-1600-4dff-8109-41ffc8ca93cd', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Fusarium head blight of barley and wheat [2003]', 'Government of Alberta', 2003, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2673600', 'https://open.alberta.ca/dataset/508567a6-14d2-4018-91e1-e708dafd8d6c/resource/38c0632b-aa1b-4c49-8a40-13af2b0a62fa/download/2003-110-632-1.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Fusarium head blight (FHB), also known as scab or tombstone, is a disease of wheat, barley, oats and other small cereal grains and corn (Figure 1). It is caused by several species of Fusarium; however, Fusarium graminearum is the primary species involved. In 1999, Fusarium graminearum was declared a pest under the Alberta Agricultural Pests Act.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7761876e-358d-413e-828a-430bbc717a39', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Genome-Wide Association Study of Waterlogging Tolerance in Barley (Hordeum vulgare L.) Under Controlled Field Conditions', 'Borrego-Benjumea A, Carter A, Zhu M, Tucker JR, Zhou M, Badea A', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.711654', 'https://doi.org/10.3389/fpls.2021.711654', 'https://europepmc.org/articles/PMC8427447?pdf=render', NULL, NULL, 24, NULL, 'prairies', 4, 'cc by', 'Waterlogging is one of the main abiotic stresses severely reducing barley grain yield. Barley breeding programs focusing on waterlogging tolerance require an understanding of genetic loci and alleles in the current germplasm. In this study, 247 worldwide spring barley genotypes grown under controlled field conditions were genotyped with 35,926 SNPs with minor allele frequency (MAF) > 0.05. Significant phenotypic variation in each trait, including biomass, spikes per plant, grains per plant, kernel weight per plant, plant height and chlorophyll content, was observed. A genome-wide association study (GWAS) based on linkage disequilibrium (LD) for waterlogging tolerance was conducted. Population structure analysis divided the population into three subgroups. A mixed linkage model using both population structure and kinship matrix (Q+K) was performed. We identified 17 genomic regions containing 51 significant waterlogging-tolerance-associated markers for waterlogging tolerance response, accounting for 5.8-11.5% of the phenotypic variation, with a majority of them localized on chromosomes 1H, 2H, 4H, and 5H. Six novel QTL were identified and eight potential candidate genes mediating responses to abiotic stresses were located at QTL associated with waterlogging tolerance. To our awareness, this is the first GWAS for waterlogging tolerance in a worldwide barley collection under controlled field conditions. The marker-trait associations could be used in the marker-assisted selection of waterlogging tolerance and will facilitate barley breeding.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e9b34721-c500-490f-a1c2-f9340ff5423b', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Phenolic compounds, antioxidant enzymes, and oxidative stress in barley (Hordeum vulgare L.) genotypes under field drought-stress conditions', 'Mohagheghian B, Saeidi G, Arzani A', 2025, 'BMC plant biology', '10.1186/s12870-025-06750-0', 'https://doi.org/10.1186/s12870-025-06750-0', 'https://europepmc.org/articles/PMC12108047?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by-nc-nd', 'Climate change has exacerbated drought, making water scarcity a significant constraint on crop production. This study aimed to evaluate drought stress responses of 21 barley cultivars and breeding lines, using various traits of leaf oxidative stress [DPPH radical scavenging, malondialdehyde (MDA), and hydrogen peroxide (H2O2)], antioxidants (enzymes and polyphenols), photosynthetic pigments and chlorophyll fluorescence (F) [carotenoid (Car), chlorophyll (Chl), Fm, F0, and Fv/Fm], relative water content (RWC), electrolyte leakage (EL), proline (Pro), protein content (PC), and grain yield. Field experiments were conducted under both normal and drought stress conditions. Significant effects of moisture conditions were observed for most of the traits, except for Chla/b, carotenoids, and EL. Syringic acid, gallic acid, chlorogenic acid, ferulic acid, ellagic acid, caffeic acid, vanillic acid, and p-coumaric acid were the prominent phenolic acids in barley genotypes. The predominant leaf flavonoids were luteolin, apigenin, and rutin. There was significant genetic variation among genotypes for all traits except Chla/b. Drought stress caused significant increases in DPPH, MDA, H2O2, total phenolic content, total flavonoid content, peroxidase, and Pro. While catalase, ascorbate peroxidase, Chla, Chlb, Tchl, Fv/Fm, F0, Fm, RWC, PC, and grain yield were significantly decreased due to water stress. These findings offer key insights into barley genotypes'' drought stress response, aiding breeders in identifying key physiological and biochemical traits as markers for developing drought-tolerant cultivars.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0fa26919-37ba-4451-8f52-c906d26cdddb', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Genome-Wide Identification of Wheat ZIP Gene Family and Functional Characterization of the TaZIP13-B in Plants', 'Li S, Liu Z, Guo L, Li H, Nie X, Chai S, Zheng W', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.748146', 'https://doi.org/10.3389/fpls.2021.748146', 'https://europepmc.org/articles/PMC8595109?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'The ZIP (Zn-regulated, iron-regulated transporter-like protein) transporter plays an important role in regulating the uptake, transport, and accumulation of microelements in plants. Although some studies have identified ZIP genes in wheat, the significance of this family is not well understood, particularly its involvement under Fe and Zn stresses. In this study, we comprehensively characterized the wheat ZIP family at the genomic level and performed functional verification of three TaZIP genes by yeast complementary analysis and of TaZIP13-B by transgenic Arabidopsis. Totally, 58 TaZIP genes were identified based on the genome-wide search against the latest wheat reference (IWGSC_V1.1). They were then classified into three groups, based on phylogenetic analysis, and the members within the same group shared the similar exon-intron structures and conserved motif compositions. Expression pattern analysis revealed that the most of TaZIP genes were highly expressed in the roots, and nine TaZIP genes displayed high expression at grain filling stage. When exposed to ZnSO4 and FeCl3 solutions, the TaZIP genes showed differential expression patterns. Additionally, six ZIP genes responded to zinc-iron deficiency. A total of 57 miRNA-TaZIP interactions were constructed based on the target relationship, and three miRNAs were downregulated when exposed to the ZnSO4 and FeCl3 stresses. Yeast complementation analysis proved that TaZIP14-B, TaZIP13-B, and TaIRT2-A could transport Zn and Fe. Finally, overexpression of TaZIP13-B in Arabidopsis showed that the transgenic plants displayed better tolerance to Fe/Zn stresses and could enrich more metallic elements in their seeds than wild-type Arabidopsis. This study systematically analyzed the genomic organization, gene structure, expression profiles, regulatory network, and the biological function of the ZIP family in wheat, providing better understanding of the regulatory roles of TaZIPs and contributing to improve nutrient quality in wheat crops.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a1660146-419a-4672-9214-4ea6981d021c', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Harvesting hulless barley', 'Government of Alberta', 1999, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2377190', 'https://open.alberta.ca/dataset/78f16439-dc77-4b9f-94d6-83182b863389/resource/eb30b3e7-d495-4d9f-b587-d9293ff18668/download/1999-114-50-1.pdf', NULL, NULL, 1, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Hulless barley is a specialty crop that can generate price premiums when marketed, but to do so, it must be harvested properly. Little research information is available about harvesting hulless barley. What is known comes from several years of experience gained with the crop by farmers, researchers and agricultural engineers.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df0c6e8a-abc5-4bf4-9e75-7a107324817a', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'High moisture barley', 'Government of Alberta', 1970, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/high-moisture-barley-0163010347934', 'https://open.alberta.ca/dataset/11344073-fa22-4136-b9b6-b9aa7f463441/resource/cfc5a4d7-f07b-45dc-806a-0c7b8f5aafea/download/0163010347934-high-moisture-barley.pdf', NULL, NULL, 12, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Discusses the preparation and storage of high-moisture barley.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bead8464-0e47-4d9b-98df-980dbc5aa525', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Hulless barley potential opportunities', 'Government of Alberta', 2015, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/hulless-barley-potential-opportunities', 'https://open.alberta.ca/dataset/29111542-ab25-45f5-9b30-c96734539d24/resource/1aa72322-cabc-46f9-9e82-6e159720ee58/download/sarah-hulless-barley-sept28-2015.pdf', NULL, NULL, 22, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Barley is a multi-purpose crop grown for food, malting and general purposes (feed) across the Canadian Prairies. Barley is the second largest cereal crop in Alberta. The purpose of this report was to research the potential of hulless barley as malt, feed and food.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eb5bd675-216e-47c5-bec6-67d27ac291fb', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Identification of stable QTLs and candidate genes involved in anaerobic germination tolerance in rice via high-density genetic mapping and RNA-Seq', 'Yang J, Sun K, Li D, Luo L, Liu Y, Huang M, Yang G, Liu H', 2019, 'BMC genomics', '10.1186/s12864-019-5741-y', 'https://doi.org/10.1186/s12864-019-5741-y', 'https://europepmc.org/articles/PMC6506967?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'BackgroundAnaerobic germination tolerance is an important trait for direct-seeded rice varieties. Understanding the genetic basis of anaerobic germination is a key for breeding direct-seeded rice varieties.ResultsIn this study, a recombinant inbred line (RIL) population derived from a cross between YZX and 02428 exhibited obvious coleoptile phenotypic differences. Mapping analysis using a high-density bin map indicated that a total of 25 loci were detected across two cropping seasons, including 10 previously detected loci and a total of 13 stable loci. Analysis of the 13 stable loci demonstrated that the more elite alleles that were pyramided in an individual, the higher the values of these traits were in the two cropping seasons. Furthermore, some anaerobic germination-tolerant recombinant inbred lines, namely G9, G10, G16, and G151, were identified. A total of 84 differentially expressed genes were obtained from the 13 stable loci via genome-wide expression analysis of the two parents at three key periods. Among them, Os06g0110200, Os07g0638300, Os07g0638400, Os09g0532900, Os09g0531701 and Os12g0539751 constitute the best candidates associated with anaerobic germination.ConclusionsBoth the anaerobic germination-tolerant recombinant inbred lines and the loci identified in this study will provide new genetic resources for improving the anaerobic germination tolerance of rice using molecular breeding strategies, as well as will broaden our understanding of the genetic control of germination tolerance under anaerobic conditions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bfd580f4-e554-4db8-bd2e-078d9b305b4c', '978e45ab-ccab-499d-93c3-105541378309', 'A robust SNP-haplotype assay for Bct gene region conferring resistance to beet curly top virus in common bean (Phaseolus vulgaris L.)', 'Soler-Garzón A, Goldoff D, Thornton A, Swisher Grimm KD, Hart JP, Song Q, Strausbaugh CA, Miklas PN', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1215950', 'https://doi.org/10.3389/fpls.2023.1215950', 'https://europepmc.org/articles/PMC10382175?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by', 'Beet curly top virus (BCTV), which is synonymous with curly top virus (CTV), causes significant yield loss in common bean (snap and dry beans) cultivars and several other important crops. Common bean cultivars have been found to be resistant to CTV, but screening for resistance is challenging due to the cyclical nature of epidemics and spotty feeding by the leafhopper that vectors the virus. We used an SNP dataset for the Snap Bean Association Panel (SnAP) agro-inoculated with CTV-Logan (CA/Logan) strain to locate the Bct gene region to a 1.7-Mb interval on chromosome Pv07 using genome-wide association study (GWAS) analysis. Recombinant lines from the SnAP were used to further narrow the Bct region to a 58.0-kb interval. A missense SNP (S07_2970381) in candidate gene Phvul.007G036300 Exonuclease V (EXO5) was identified as the most likely causal mutation, and it was the most significant SNP detected by GWAS in a dry bean population (DBP) naturally infected by the CTV-Worland (Wor) strain. Tm-shift assay markers developed for SNP S07_2970381 and two linked SNPs, S07_2970276 and S07_2966197, were useful for tracking different origins of the Bct EXO5 candidate gene resistance to CTV in common bean. The three SNPs identified four haplotypes, with haplotype 3-1 (Haplo3-1) of Middle American origin associated with the highest levels of CTV resistance. This SNP-haplotype assay will enable breeders to track resistance sources and to develop cultivars with better CTV resistance.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('721d281b-4c35-48d0-9c3b-65bbc503d6a9', '978e45ab-ccab-499d-93c3-105541378309', 'Biological nitrogen fixation and prospects for ecological intensification in cereal-based cropping systems', 'Ladha JK, Peoples MB, Reddy PM, Biswas JC, Bennett A, Jat ML, Krupnik TJ', 2022, 'Field Crops Research.', '10.1016/j.fcr.2022.108541', 'https://doi.org/10.1016/j.fcr.2022.108541', 'https://europepmc.org/articles/PMC9133800?pdf=render', NULL, NULL, 34, NULL, 'other', 1, 'cc by', 'The demand for nitrogen (N) for crop production increased rapidly from the middle of the twentieth century and is predicted to at least double by 2050 to satisfy the on-going improvements in productivity of major food crops such as wheat, rice and maize that underpin the staple diet of most of the world''s population. The increased demand will need to be fulfilled by the two main sources of N supply - biological nitrogen (gas) (N2) fixation (BNF) and fertilizer N supplied through the Haber-Bosch processes. BNF provides many functional benefits for agroecosystems. It is a vital mechanism for replenishing the reservoirs of soil organic N and improving the availability of soil N to support crop growth while also assisting in efforts to lower negative environmental externalities than fertilizer N. In cereal-based cropping systems, legumes in symbiosis with rhizobia contribute the largest BNF input; however, diazotrophs involved in non-symbiotic associations with plants or present as free-living N2-fixers are ubiquitous and also provide an additional source of fixed N. This review presents the current knowledge of BNF by free-living, non-symbiotic and symbiotic diazotrophs in the global N cycle, examines global and regional estimates of contributions of BNF, and discusses possible strategies to enhance BNF for the prospective benefit of cereal N nutrition. We conclude by considering the challenges of introducing in planta BNF into cereals and reflect on the potential for BNF in both conventional and alternative crop management systems to encourage the ecological intensification of cereal and legume production.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('448ffbee-b42e-4f23-9823-f4acf202b367', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Impact of Climate Change on Dryland Agricultural Systems: A Review of Current Status, Potentials, and Further Work Need', 'Ahmed M, Hayat R, Ahmad M, Ul-Hassan M, Kheir AMS, Ul-Hassan F, Ur-Rehman MH, Shaheen FA', 2022, 'International journal of plant production', '10.1007/s42106-022-00197-1', 'https://doi.org/10.1007/s42106-022-00197-1', 'https://europepmc.org/articles/PMC9122557?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'open access (Europe PMC)', 'Dryland agricultural system is under threat due to climate extremes and unsustainable management. Understanding of climate change impact is important to design adaptation options for dry land agricultural systems. Thus, the present review was conducted with the objectives to identify gaps and suggest technology-based intervention that can support dry land farming under changing climate. Careful management of the available agricultural resources in the region is a current need, as it will play crucial role in the coming decades to ensure food security, reduce poverty, hunger, and malnutrition. Technology based regional collaborative interventions among Universities, Institutions, Growers, Companies etc. for water conservation, supplemental irrigation, foliar sprays, integrated nutrient management, resilient crops-based cropping systems, artificial intelligence, and precision agriculture (modeling and remote sensing) are needed to support agriculture of the region. Different process-based models have been used in different regions around the world to quantify the impacts of climate change at field, regional, and national scales to design management options for dryland cropping systems. Modeling include water and nutrient management, ideotype designing, modification in tillage practices, application of cover crops, insect, and disease management. However, diversification in the mixed and integrated crop and livestock farming system is needed to have profitable, sustainable business. The main focus in this work is to recommend different agro-adaptation measures to be part of policies for sustainable agricultural production systems in future.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e83b87f-6824-4aab-8b17-dfc2f52d6888', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Impact of Raised without Antibiotics Measures on Antimicrobial Resistance and Prevalence of Pathogens in Sow Barns', 'Alvarado AC, Chekabab SM, Predicala BZ, Korber DR', 2022, 'Antibiotics (Basel, Switzerland)', '10.3390/antibiotics11091221', 'https://doi.org/10.3390/antibiotics11091221', 'https://europepmc.org/articles/PMC9495050?pdf=render', NULL, NULL, 13, NULL, 'prairies', 4, 'cc by', 'The growing concern over the emergence of antimicrobial resistance (AMR) in animal production as a result of extensive and inappropriate antibiotic use has prompted many swine farmers to raise their animals without antibiotics (RWA). In this study, the impact of implementing an RWA production approach in sow barns on actual on-farm antibiotic use, the emergence of AMR, and the abundance of pathogens was investigated. Over a 13-month period, fecal and nasopharynx samples were collected at 3-month intervals from sows raised in RWA barns and sows in conventional barns using antibiotics in accordance with the new regulations (non-RWA). Whole genome sequencing (WGS) was used to determine the prevalence of AMR and the presence of pathogens in those samples. Records of all drug use from the 13-month longitudinal study indicated a significant reduction in antimicrobial usage in sows from RWA barns compared to conventional non-RWA barns. Antifolates were commonly administered to non-RWA sows, whereas β-lactams were widely used to treat sows in RWA barns. Metagenomic analyses demonstrated an increased abundance of pathogenic Actinobacteria, Firmicutes, and Proteobacteria in the nasopharynx microbiome of RWA sows relative to non-RWA sows. However, WGS analyses revealed that the nasal microbiome of sows raised under RWA production exhibited a significant increase in the frequency of resistance genes coding for β-lactams, MDR, and tetracycline.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('76e6f6e6-4bde-4127-91a4-f4a4409f4df3', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Impact of Wheat Resistance Genes on Wheat Curl Mite Fitness and Wheat Streak Mosaic Dynamics Under Single and Mixed Infections', 'Gautam S, Gadhave KR', 2025, 'Viruses', '10.3390/v17071010', 'https://doi.org/10.3390/v17071010', 'https://europepmc.org/articles/PMC12299356?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'The wheat curl mite (WCM, Aceria tosichella Keifer), a complex of eriophyid mite species, transmits wheat streak mosaic virus (WSMV) and Triticum mosaic virus (TriMV), which in single or mixed infections cause wheat streak mosaic (WSM) disease-a major threat to wheat production across the U.S. Great Plains. Resistant wheat cultivars bearing Cmc3 and Cmc4 (targeting WCM), Wsm1 and Wsm2 (targeting WSMV), and Wsm1 (targeting TriMV) are widely used to manage this pest-pathogen complex. However, comprehensive studies investigating how these resistance mechanisms influence both vector biology and virus transmission remain scarce. To address this gap, we evaluated disease development and WCM fitness across nine wheat cultivars with differential resistance profiles under single and mixed infections of WSMV and TriMV. We found strong viral synergy in co-infected plants, with TriMV accumulation markedly enhanced during mixed infections, irrespective of host genotype. Symptom severity and virus titers (both WSMV and TriMV) were highest in the cultivars carrying Wsm2, suggesting a potential trade-off in resistance effectiveness under mixed infection pressure. While mite development time (egg to adult) was unaffected by host genotype or infection status, mite fecundity was significantly reduced on infected plants carrying Wsm1 or Wsm2, but not on those with Cmc3 and Cmc4. Notably, virus accumulation in mites was reduced on the cultivars with Cmc3 and Cmc4, correlating with virus titers in the host tissues. Our findings highlight the complex interplay between host resistance, virus dynamics, and vector performance. Cultivars harboring Cmc3 and Cmc4 may offer robust field-level protection by simultaneously suppressing mite reproduction and limiting virus accumulation in both plant and vector.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('34bb533e-ae74-4399-a280-10cc926d52aa', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Improvement of barley feed quality in Alberta [1993]', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/improvement-of-barley-feed-quality-in-alberta-0163010024517', 'https://open.alberta.ca/dataset/3a87e215-c021-4eda-8b94-a4abc56e7a51/resource/5c2f6b71-51f8-458a-ae77-6ecff0509038/download/0163010024517-improvement-of-barley-feed-quality-in-alberta.pdf', NULL, NULL, 88, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This updated report is part of a national study evaluating 73 registered Canadian barley varieties for feed quality. It builds on earlier trials conducted in 1991 and 1992, with expanded field tests to strengthen data reliability and better compare eastern and western varieties. Results confirmed that eastern feed varieties generally outperformed western ones in quality traits, while some western six-row types produced higher yields but had lower test and kernel weights. Top varieties from both regions delivered equivalent overall performance. These findings will support region-specific breeding improvements and help maintain Alberta''s competitiveness in barley production.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f82db993-694a-4311-87c8-cd44cc14c7ba', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Land conversion from forest to agriculture redistributes but does not reduce soil organic carbon stores in northeastern Ontario, Canada', 'Murray B, Diochon A', 2026, 'Discover soil', '10.1007/s44378-026-00207-y', 'https://doi.org/10.1007/s44378-026-00207-y', 'https://europepmc.org/articles/PMC13098991?pdf=render', NULL, NULL, 15, NULL, 'canada', 3, 'cc by-nc-nd', 'Climate change is creating conditions for agriculture to expand northward. For conventional large-scale operations, this will require the conversion of forests to agricultural land in most areas, which has historically been associated with large (30%) losses of soil organic carbon (SOC) and soil degradation. To potentially mitigate these losses, farmers in Northern Ontario, Canada, are incorporating woody residues into their soils during conversion to retain more organic matter on-site, while bringing the land into production faster than conventional conversion approaches. The current study examines the effects of converting forest to agricultural land on soil by comparing SOC storage in the top 45 cm of mineral soil in forests, old (> 50 year) and young (p > 0.05) of land conversion on SOC storage but there was a redistribution of SOC with depth consistent with soil tillage. Observed trends in mean SOC storage suggest that incorporating woody mulch residues into the soil at the time of conversion may warrant further study as a SOC conservation strategy.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('68776de0-f19b-4b0a-b276-563c105dbf8d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Larval Frass of Hermetia illucens as Organic Fertilizer: Composition and Beneficial Effects on Different Crops', 'Lomonaco G, Franco A, De Smet J, Scieuzo C, Salvia R, Falabella P', 2024, 'Insects', '10.3390/insects15040293', 'https://doi.org/10.3390/insects15040293', 'https://europepmc.org/articles/PMC11050032?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Hermetia illucens has received a lot of attention as its larval stage can grow on organic substrates, even those that are decomposing. Black soldier fly breeding provides a variety of valuable products, including frass, a mixture of larval excrements, larval exuviae, and leftover feedstock, that can be used as a fertilizer in agriculture. Organic fertilizers, such as frass, bringing beneficial bacteria and organic materials into the soil, improves its health and fertility. This comprehensive review delves into a comparative analysis of frass derived from larvae fed on different substrates. The composition of micro- and macro-nutrients, pH levels, organic matter content, electrical conductivity, moisture levels, and the proportion of dry matter are under consideration. The effect of different feeding substrates on the presence of potentially beneficial bacteria for plant growth within the frass is also reported. A critical feature examined in this review is the post-application beneficial impacts of frass on crops, highlighting the agricultural benefits and drawbacks of introducing Hermetia illucens frass into cultivation operations. One notable feature of this review is the categorization of the crops studied into distinct groups, which is useful to simplify comparisons in future research.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4fa0f8c-d4a8-49e7-b99f-10e1708e4cf8', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Long-term use of cover crops and no-till shift soil microbial community life strategies in agricultural soil', 'Schmidt R, Gravuer K, Bossange AV, Mitchell J, Scow K', 2018, 'PloS one', '10.1371/journal.pone.0192953', 'https://doi.org/10.1371/journal.pone.0192953', 'https://europepmc.org/articles/PMC5814021?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'Reducing tillage and growing cover crops, widely recommended practices for boosting soil health, have major impacts on soil communities. Surprisingly little is known about their impacts on soil microbial functional diversity, and especially so in irrigated Mediterranean ecosystems. In long-term experimental plots at the West Side Research and Extension Center in California''s Central Valley, we characterized soil microbial communities in the presence or absence of physical disturbance due to tillage, in the presence or absence of cover crops, and at three depths: 0-5, 5-15 and 15-30 cm. This characterization included qPCR for bacterial and archaeal abundances, DNA sequencing of the 16S rRNA gene, and phylogenetic estimation of two ecologically important microbial traits (rRNA gene copy number and genome size). Total (bacterial + archaeal) diversity was higher in no-till than standard till; diversity increased with depth in no-till but decreased with depth in standard till. Total bacterial numbers were higher in cover cropped plots at all depths, while no-till treatments showed higher numbers in 0-5 cm but lower numbers at lower depths compared to standard tillage. Trait estimates suggested that different farming practices and depths favored distinctly different microbial life strategies. Tillage in the absence of cover crops shifted microbial communities towards fast growing competitors, while no-till shifted them toward slow growing stress tolerators. Across all treatment combinations, increasing depth resulted in a shift towards stress tolerators. Cover crops shifted the communities towards ruderals-organisms with wider metabolic capacities and moderate rates of growth. Overall, our results are consistent with decreasing nutrient availability with soil depth and under no-till treatments, bursts of nutrient availability and niche homogenization under standard tillage, and increases in C supply and variety provided by cover crops. Understanding how agricultural practices shift microbial abundance, diversity and life strategies, such as presented here, can assist with designing farming systems that can support high yields, while enhancing C sequestration and increasing resilience to climate change.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('597cce0d-e30d-45f8-8de5-b7468ec5bbbc', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Malt Barley Yield and Quality Response to Crop Water Stress Index', 'Bradley King, Christopher Rogers, David Tarkalson, David Bjorneberg', 2024, 'Agronomy', '10.3390/agronomy14122897', 'https://doi.org/10.3390/agronomy14122897', 'https://www.mdpi.com/2073-4395/14/12/2897', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'open access (DOAJ)', 'Malt barley is a crucial irrigated crop in the semi-arid Western United States, where the states of Idaho, Colorado, Wyoming, and Utah account for 92% of the irrigated production acreage and 30% of total U.S. production. In this region, spring malt barley’s seasonal evapotranspiration ranges from 400 to 650 mm, and competition for limited water supplies, coupled with drought, is straining regional water resources. This study aimed to investigate the use of canopy temperature for deficit irrigation scheduling of malt barley. Specifically, the objectives were to use data-driven models to estimate well-watered (TLL) and non-transpiring (TUL) canopy temperatures, correlate the crop water stress index (CWSI) with malt barley yield and quality measures, and assess the applicability of CWSI for malt barley irrigation scheduling in a semi-arid climate. A 3-year field study was conducted with five irrigation treatments relative to estimated crop evapotranspiration (full, 75%, 50%, 25%, and no irrigation) and four replicates each. Continuous canopy temperature measurements and meteorological data were collected, and a feedforward neural network model was used to predict TLL, while a physical model was used to estimate TUL. The neural network model accurately predicted TLL, with a strong correlation (R2 = 0.99), a root mean square error of 0.89 °C, and a mean absolute error of 0.70 °C. Significant differences in calculated season-average CWSI were observed between the irrigation treatments, and relative evapotranspiration, malt barley relative yield, test weight, and plump kernels were negatively correlated with the season-average CWSI, while seed protein was positively correlated. The relationship between daily CWSI and fraction of available soil water was well described by an exponential decay function (R2 = 0.72). These results demonstrate the applicability of data-driven models for computing CWSI of irrigated spring malt barley in a semi-arid environment and their ability to assess plant water stress and predict crop yield and quality response from CWSI.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1bc5b1f9-7d9b-480d-b9da-05b3e6ed0f95', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Molecular Mapping of QTLs Associated with Lodging Resistance in Dry Direct-Seeded Rice (Oryza sativa L.)', 'Yadav S, Singh UM, Naik SM, Venkateshwarlu C, Ramayya PJ, Raman KA, Sandhu N, Kumar A', 2017, 'Frontiers in plant science', '10.3389/fpls.2017.01431', 'https://doi.org/10.3389/fpls.2017.01431', 'https://europepmc.org/articles/PMC5567065?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Dry direct-seeded rice (DSR) is an alternative crop establishment method with less water and labor requirement through mechanization. It provides better opportunities for a second crop during the cropping season and therefore, a feasible alternative system to transplanted lowland rice. However, lodging is one of the major constraints in attaining high yield in DSR. Identification of QTLs for lodging resistance and their subsequent use in improving varieties under DSR will be an efficient breeding strategy to address the problem. In order to map the QTLs associated with lodging resistance, a set of 253 BC3F4 lines derived from a backcross between Swarna and Moroberekan were evaluated in two consecutive years. A total of 12 QTLs associated with lodging resistance traits [culm length (qCL), culm diameter (qCD), and culm strength (qCS)] were mapped on chromosomes 1, 2, 6, and 7 using 193 polymorphic SNP markers. Two major and consistent effect QTLs, namely qCD1.1 (with R2 of 10%) and qCS1.1 (with R2 of 14%) on chromosome 1 with id1003559 being the peak SNP marker (flanking markers; id1001973-id1006772) were identified as a common genomic region associated with important lodging resistance traits. In silico analysis revealed the presence of Gibberellic Acid 3 beta-hydroxylase along with 34 other putative candidate genes in the marker interval region of id1001973-id1006772. The positive alleles for culm length, culm diameter, and culm strength were contributed by the upland adaptive parent Moroberekan. Our results identified significant positive correlation between lodging related traits (culm length diameter and strength) and grain yield under DSR, indicating the role of lodging resistant traits in grain yield improvement under DSR. Deployment of the identified alleles influencing the culm strength and culm diameter in marker assisted introgression program may facilitate the lodging resistance under DSR.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('de7f6328-135a-4113-b7fa-d3e615e26c02', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Ancient Grains as Functional Foods: Integrating Traditional Knowledge with Contemporary Nutritional Science', 'Aweya JJ, Sharma D, Bajwa RK, Earnest B, Krache H, Moghadasian MH', 2025, 'Foods (Basel, Switzerland)', '10.3390/foods14142529', 'https://doi.org/10.3390/foods14142529', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC12294667.1/PMC12294667.1.pdf', NULL, NULL, 17, NULL, 'prairies', 4, 'cc by', 'Ancient grains, including wild rice, millet, fonio, teff, quinoa, amaranth, and sorghum, are re-emerging as vital components of modern diets due to their dense nutritional profiles and diverse health-promoting bioactive compounds. Rich in high-quality proteins, dietary fiber, essential micronutrients, and a broad spectrum of bioactive compounds such as phenolic acids, flavonoids, carotenoids, phytosterols, and betalains, these grains exhibit antioxidant, anti-inflammatory, antidiabetic, cardioprotective, and immunomodulatory properties. Their health-promoting effects are underpinned by multiple interconnected mechanisms, including the reduction in oxidative stress, modulation of inflammatory pathways, regulation of glucose and lipid metabolism, support for mitochondrial function, and enhancement of gut microbiota composition. This review provides a comprehensive synthesis of the essential nutrients, phytochemicals, and functional properties of ancient grains, with particular emphasis on the nutritional and molecular mechanisms through which they contribute to the prevention and management of chronic diseases such as cardiovascular disease, type 2 diabetes, obesity, and metabolic syndrome. Additionally, it highlights the growing application of ancient grains in functional foods and nutrition-sensitive dietary strategies, alongside the technological, agronomic, and consumer-related challenges limiting their broader adoption. Future research priorities include well-designed human clinical trials, standardization of compositional data, innovations in processing for nutrient retention, and sustainable cultivation to fully harness the health, environmental, and cultural benefits of ancient grains within global food systems.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ebae2e5c-fe49-4a29-bd8c-c6892ca20099', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Multiple decrement life tables of Cephus cinctus Norton (Hymenoptera: Cephidae) across a set of barley cultivars: The importance of plant defense versus cannibalism', 'Achhami BB, Peterson RKD, Sherman JD, Reddy GVP, Weaver DK', 2020, 'PloS one', '10.1371/journal.pone.0238527', 'https://doi.org/10.1371/journal.pone.0238527', 'https://europepmc.org/articles/PMC7485797?pdf=render', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc0', 'Accurately estimating cause-specific mortality for immature insect herbivores is usually difficult. The insects are exposed to abiotic and biotic mortality factors, causing cadavers to simply disappear before cause of mortality can be recorded. Also, insect herbivores are often highly mobile on hosts, making it difficult to follow patterns for individuals through time. In contrast, the wheat stem sawfly, Cephus cinctus Norton, spends its entire egg, larval, and pupal period inside a host stem. Therefore, with periodic sampling stage-specific causes of mortality can be ascertained. Consequently, we examined C. cinctus mortality in eight barley, Hordeum vulgare L., cultivars in two locations in Montana from 2016 to 2018 by collecting stem samples from stem elongation to crop maturity at weekly intervals, and collecting overwintered barley stubs the following spring and summer from the same plots. If larvae were present, we examined larval status-dead or alive-and categorized dead individuals into one of 5 mortality categories: plant defense, cannibalism, parasitism, pathogens, and unknown factors. We used multiple decrement life tables to estimate cause-specific mortality and irreplaceable mortality (the proportion of mortality from a given cause that cannot be replaced by other causes of mortality). Plant defense (antibiosis) caused 85.7 ± 3.6%, cannibalism (governed by antixenosis) caused 70.1 ± 7.6%, parasitism caused 13.8 ± 5.9%, unknown factors caused 38.5 ± 7.6%, and pathogens caused 14.7 ± 8.5% mortality in the presence of all causes of mortality. Similarly, irreplaceable mortality due to plant defense was 22.3 ± 6.4%, cannibalism was 29.1± 4.2%, unknown factors was 6.2 ± 1.8%, pathogens was 0.9 ± 0.5%, and parasitism was 1. 5 ± 0. 6%. Antibiosis traits primarily killed newly emerged larvae, while other traits supported more favorable oviposition decisions by females, increasing mortality by obligate cannibalism. Our results suggest that breeding barley for resistance to C. cinctus targeting both categories of traits (antibiosis and antixenosis) is a highly valuable tactic for management of this important pest.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6fc82297-7e82-4423-a5a4-d53b0fc282ec', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Natural Genetic Variation Underlying Tiller Development in Barley (Hordeum vulgare L)', 'Haaning AM, Smith KP, Brown-Guedira GL, Chao S, Tyagi P, Muehlbauer GJ', 2020, 'G3 (Bethesda, Md.)', '10.1534/g3.119.400612', 'https://doi.org/10.1534/g3.119.400612', 'https://europepmc.org/articles/PMC7144072?pdf=render', NULL, NULL, 16, NULL, 'northern_plains', 3, 'cc by', 'In barley (Hordeum vulgare L.), lateral branches called tillers contribute to grain yield and define shoot architecture, but genetic control of tiller number and developmental rate are not well characterized. The primary objectives of this work were to examine relationships between tiller number and other agronomic and morphological traits and identify natural genetic variation associated with tiller number and rate, and related traits. We grew 768 lines from the USDA National Small Grain Collection in the field and collected data over two years for tiller number and rate, and agronomic and morphological traits. Our results confirmed that spike row-type and days to heading are correlated with tiller number, and as much as 28% of tiller number variance was associated with these traits. In addition, negative correlations between tiller number and leaf width and stem diameter were observed, indicating trade-offs between tiller development and other vegetative growth. Thirty-three quantitative trait loci (QTL) were associated with tiller number or rate. Of these, 40% overlapped QTL associated with days to heading and 22% overlapped QTL associated with spike row-type, further supporting that tiller development is associated with these traits. Some QTL associated with tiller number or rate, including the major QTL on chromosome 3H, were not associated with other traits, suggesting that some QTL may be directly related to rate of tiller development or axillary bud number. These results enhance our knowledge of the genetic control of tiller development in barley, which is important for optimizing tiller number and rate for yield improvement.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('df9fc389-f431-45e6-ad65-5cb2f0210522', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Nutritional status of honey bee (Apis mellifera L.) workers across an agricultural land-use gradient', 'Smart MD, Otto CRV, Lundgren JG', 2019, 'Scientific reports', '10.1038/s41598-019-52485-y', 'https://doi.org/10.1038/s41598-019-52485-y', 'https://europepmc.org/articles/PMC6838345?pdf=render', NULL, NULL, 10, NULL, 'other', 1, 'cc by', 'Land use, habitat, and forage quality have emerged as critical factors influencing the health, productivity, and survival of honey bee colonies. However, characterization of the mechanistic relationship between differential land-use conditions and ultimate outcomes for honey bee colonies has been elusive. We assessed the physiological health of individual worker honey bees in colonies stationed across a gradient of agricultural land use to ask whether indicators of nutritional physiology including glycogen, total sugar, lipids, and protein were associated with land-use conditions over the growing season and colony population size the subsequent spring during almond pollination. Across the observed land-use gradient, we found that September lipid levels related to growing-season land use, with honey bees from apiaries surrounded by more favorable land covers such as grassland, pasture, conservation land, and fallow fields having greater lipid reserves. Further, we observed a significant relationship between total protein during September and population size of colonies during almond pollination the following February. We demonstrate and discuss the utility of quantifying nutritional biomarkers to infer land-use quality and predict colony population size.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('469896a9-e220-499b-a8d1-24f8f8af7a59', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Overcoming physiological trade-offs between flowering time and crop yield: strategies for a changing climate', 'Wingler A, Soualiou S', 2025, 'Journal of experimental botany', '10.1093/jxb/eraf110', 'https://doi.org/10.1093/jxb/eraf110', 'https://europepmc.org/articles/PMC12223507?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Early flowering of annual plants can lead to resource limitation owing to reduced uptake of nitrogen during the reproductive phase and declining foliar photosynthesis as a result of monocarpic senescence. Low availability of accumulated resources can therefore result in a trade-off between early flowering and reproductive fitness. However, green inflorescence organs (such as siliques, pods, bracts, or awns) can make considerable contributions to photosynthetic carbon gain, and in some cases provide more carbon to seed formation than the leaves. Inflorescence photosynthesis may thereby overcome the flowering time trade-off. In addition to providing photosynthates, inflorescence organs can contribute to seed nitrogen through senescence-dependent nitrogen recycling. In annual crops, breeding has resulted in increased carbon allocation to the grain and higher harvest index, but in some cases this had led to reduced grain protein content. We discuss different breeding targets to address carbon and nitrogen limitation, dependent on the climatic environment. For environments that are prone to drought, we propose a combination of early flowering with enhanced inflorescence photosynthesis or, alternatively, delayed senescence (stay-green) associated with improved water balance. For optimized yield and grain protein content under favourable conditions, enhanced sink strength and extended nitrogen uptake are suggested as breeding targets.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5f2ea76f-8f08-4629-956b-9804d570aa18', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Pathways to sustainable land use and food systems in Canada', 'Zerriffi H, Reyes R, Maloney A', 2023, 'Sustainability science', '10.1007/s11625-022-01213-z', 'https://doi.org/10.1007/s11625-022-01213-z', 'https://europepmc.org/articles/PMC9575642?pdf=render', NULL, NULL, 18, NULL, 'canada', 3, 'open access (Europe PMC)', 'Meeting global sustainability targets under the United Nations Sustainable Development Goals and the Paris Agreement requires paying attention to major land-use sectors such as forestry and agriculture. These sectors play a large role in national emissions, biodiversity conservation, and human well-being. There are numerous possible pathways to sustainability in these sectors and potential synergies and trade-offs along those pathways. This paper reports on the use of a model for Canada''s land use to 2050 to assess three different pathways (one based on current trends and two with differing levels of ambition for meeting sustainability targets). This was done as part of a large international consortium, Food, Agriculture, Biodiversity, Land and Energy (FABLE), which allows for incorporating international trade in meeting both national and global sustainability targets. The results show not only the importance of increasingly stringent policies in meeting the targets, but also the role that population and consumption (e.g., diets) play in meeting the targets. Both the medium and high ambition sustainability pathways can drastically reduce greenhouse gas emissions while protecting forestland.Supplementary informationThe online version contains supplementary material available at 10.1007/s11625-022-01213-z.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('37d9dfcc-01e2-4c52-9d2c-6c0dd585fade', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Plant Water Stress Affects Interactions Between an Invasive and a Naturalized Aphid Species on Cereal Crops', 'Foote NE, Davis TS, Crowder DW, Bosque-Pérez NA, Eigenbrode SD', 2017, 'Environmental entomology', '10.1093/ee/nvx071', 'https://doi.org/10.1093/ee/nvx071', 'https://europepmc.org/articles/PMC5452433?pdf=render', NULL, NULL, 8, NULL, 'northern_plains', 3, 'cc by-nc', 'In cereal cropping systems of the Pacific Northwestern United States (PNW), climate change is projected to increase the frequency of drought during summer months, which could increase water stress for crop plants. Yet, it remains uncertain how interactions between herbivore species are affected by drought stress. Here, interactions between two cereal aphids present in PNW cereal systems, Metopolophium festucae (Theobald) subsp. cerealium (a newly invasive species) and Rhopalosiphum padi L. (a naturalized species), were tested relative to wheat water stress. When aphids were confined in leaf cages on wheat, asymmetrical facilitation occurred; per capita fecundity of R. padi was increased by 46% when M. festucae cerealium was also present, compared to when only R. padi was present. Imposed water stress did not influence this interaction. When aphids were confined on whole wheat plants, asymmetrical competition occurred; cocolonization inhibited M. festucae cerealium population growth but did not affect R. padi population growth. Under conditions of plant water stress, however, the inhibitory effect of R. padi on M. festucae cerealium was not observed. We conclude that beneficial effects of cocolonization on R. padi are due to a localized plant response to M. festucae cerealium feeding, and that cocolonization of plants is likely to suppress M. festucae cerealium populations under ample water conditions, but not when plants are water stressed. This suggests that plant responses to water stress alter the outcome of competition between herbivore species, with implications for the structure of pest communities on wheat during periods of drought.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd93a4e3-5ab3-4caf-a2b5-24b60e55e006', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Potassium chloride as a means of reducing root rot in barley : report on a project', 'Government of Alberta', 1987, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/potassium-chloride-as-a-means-of-reducing-root-rot-in-barley-report-on-a-project', 'https://open.alberta.ca/dataset/5aaf1273-3dfa-4586-a0e9-1922061e8d26/resource/1d8ce17e-94fa-4c0f-8204-7fe8ea3f3dd6/download/0163010413561-potassium-chloride-as-a-means-of-reducing-root-rot-in-barley-report-on-a-project.pdf', NULL, NULL, 118, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This study evaluated the effects of chloride fertilization on crop yield, disease severity and plant nutrient balance, particularly in barley and irrigated soft white wheat. Field trials demonstrated that chloride application indirectly benefited crops by reducing stress and possibly alleviating root or leaf diseases. Chloride also improved grain quality parameters such as kernel plumpness and thousand kernel weight, and slightly reduced barley protein content, aiding malting quality. Plant tissue analysis indicated that chloride reduced plant nitrate levels and susceptibility to root rot infection. These findings supported the beneficial but indirect role of chloride in plant health and yield enhancement.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('401f517d-e21d-48f0-b665-84358ac55616', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Potential food applications of barley B-glucan concentrate', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/potential-food-applications-of-barley-b-glucan-concentrate', 'https://open.alberta.ca/dataset/ed4f7542-f5da-4012-8963-45aebcea26fb/resource/05db2aad-43f9-4b61-acd0-21cd61770b0e/download/0163010382170-potential-food-applications-of-barley-b-glucan-concentrate.pdf', NULL, NULL, 69, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document investigated the incorporation of barley β-glucan concentrate into functional food products to enhance health and textural properties. Barley β-glucan, a soluble fiber found in barley and oats, was shown to lower cholesterol and regulate blood glucose levels. The study developed two products, a beverage containing a dairy ingredient and a low fat breakfast sausage, initially formulated in the laboratory and later scaled up to pilot plant production. Sensory, chemical and instrumental evaluations, including trained and consumer panels, demonstrated that both products were well accepted. The interaction between barley β-glucan and whey protein isolate was critical for achieving beverage stability over eight week refrigerated storage.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('aff3d232-8b43-417a-941c-6fd54047e51e', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Reduced Growth and Nitrogen Uptake During Waterlogging at Tillering Permanently Affect Yield Components in Late Sown Oats', 'Iduna Arduini, Marco Baldanzi, Silvia Pampana', 2019, 'Frontiers in Plant Science', '10.3389/fpls.2019.01087', 'https://doi.org/10.3389/fpls.2019.01087', 'https://www.frontiersin.org/article/10.3389/fpls.2019.01087/full', NULL, NULL, 18, NULL, 'other', 1, 'open access (DOAJ)', 'In Mediterranean Europe, winter cereals can experience soil waterlogging starting from crop establishment up to stem elongation and, in late sowings, this stress is combined with temperatures favorable to plant metabolism. Oats response to waterlogging has been rarely investigated, but these species seems to recover better than other cereals. In a 2-year experiment, Avena sativa and Avena byzantina were sown at the end of winter in pots placed outdoors. At the two-tiller stage, plants were exposed to waterlogging for periods ranging from 0 to 35 days. The dry weight and the N-concentration of shoots and roots were determined on waterlogged plants and drained controls at the start and the end of each waterlogging period, and at maturity. At maturity, the grain yield and its components were determined. To relate oat response to its specific morphological and developmental traits, results were compared to the published results in wheat and barley. Both oat species suffered severe damage during waterlogging: the uptake of nitrogen and the N-concentration of shoots were reduced after 7 days, tiller initiation and root growth after 14 days, and shoot growth after 21 days. All plants survived waterlogging, and the relative growth rates of roots and shoots and the net uptake rate of nitrogen were resumed during recovery. Nevertheless, at maturity, the straw and root biomass were markedly lower with all waterlogging durations, and grain yield decreased by 42% up to approximately 81% following an asymptotic equation. The most affected yield components were the number of panicles per plant and the number of kernels per panicle, but their relative sensitivity changed according to waterlogging duration. The slight increase in tiller fertility in response to short waterlogging and the small and irregular decrease in the number of kernels per spikelet suggest that the two oats could recover the initiation and size of inflorescences better than other winter cereals. Despite this, waterlogging in spring was highly detrimental to these oats because of severe damage under waterlogging and because of the inability to initiate new tillers and adequately resume root growth during recovery, once plants had achieved the phase of stem elongation.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('49fda849-b461-41df-acf8-f4a81bac982d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Storage of high moisture barley', 'Government of Alberta', 2008, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/4252350', 'https://open.alberta.ca/dataset/71caa0b4-e91e-4b78-aedc-66f2f92c2325/resource/d0da48c5-f92c-48b9-8859-104b2a4223a9/download/2008-114-61-1.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Grains reach maturity several days before harvest. To prevent spoilage, harvesting is normally delayed to allow the grain drying time in the field. If barley could be harvested when it reached maturity, rather than having to let it dry in the field, then harvests could be completed earlier with reduced field losses. Tough grain with a moisture content of 15.5 to 17.0 per cent when bin stored may rot. Damp grain with a moisture content greater than 17.1 per cent will rot quickly, often producing enough heat to start a fire. Spoiled grain is useless as feed since there is a risk of toxic chemical build-up during spoilage from aflatoxins, which are produced by soil micro-organisms. Aflatoxins endanger the health of both people and animals. Micro-organic contamination occurs during both the growing season and harvest when dust becomes mixed with the grain. If damp grain is to be stored successfully, you must prevent microorganic growth or kill micro-organisms before growth begins.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2fa0ccac-c3d2-4b29-8247-1c3b2c169aff', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Regulating Effect of Mixed Cropping of Green Manure Varieties on Greenhouse Gas Emissions in a Green Manure–Wheat Rotation System Under Reduced Nitrogen Conditions', 'Xingjian Jin, Ke Xu, Zhengpeng Li, Xiaojun Wang, Qingbiao Yan, Kaibin Qi, Falong Hu, Tianlong Chen', 2026, 'Plants', '10.3390/plants15142194', 'https://doi.org/10.3390/plants15142194', 'https://www.mdpi.com/2223-7747/15/14/2194', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'To explore low-carbon spring wheat production strategies for the ecologically fragile Qinghai Plateau, a two-year field experiment was conducted using a split-plot design. The main plots were set with three nitrogen (N) application levels: N0 (0 kg·ha−1, no N input), N1 (157.5 kg·ha−1, 30% N reduction relative to conventional rate), and N2 (225 kg·ha−1, the conventional rate). The subplots comprised four green manure mixed cropping patterns: sole cropped common vetch (CK), common vetch mixed with hull-less barley (HB), common vetch mixed with hairy vetch (HV), and common vetch mixed with rapeseed (RS). Averaged across green manure treatments, N1 reduced global warming potential (GWP) by 14.56% and greenhouse gas intensity (GHGI) by 16.89% compared with N2. Under the N1 treatment, compared with CK, RS reduced cumulative CO2 emissions by 7.77% and GWP by 7.45%, maintained wheat grain yield comparable to those under N2, and obtained the minimum GHGI which was 2.92% lower than CK. Regarding soil properties, all green manure patterns significantly increased soil available phosphorus (AP) and available potassium (AK) compared with CK. Specifically, HB increased AP by 12.81% and AK by 16.38%, and RS also increased AP by 4.37% and AK by 2.36%. In addition, HB enhanced soil organic matter (SOM) by 5.85%, ammonium nitrogen (NH4–N) by 8.13%, and nitrate nitrogen (NO3–N) by 4.34%. Soil NH4–N and NO3–N were identified as key drivers of GHGI across treatments. On the Qinghai–Tibet Plateau, a 30% N reduction combined with target-oriented green manure mixtures—RS for emission mitigation and HB for high yield and fertility—offers a viable low-carbon strategy for spring wheat production.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a18a3360-f14b-46ba-b2e4-f7664be1a3f3', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Resistance and resilience of root fungal communities to water limitation in a temperate agroecosystem', 'Furze JR, Martin AR, Nasielski J, Thevathasan NV, Gordon AM, Isaac ME', 2017, 'Ecology and evolution', '10.1002/ece3.2900', 'https://doi.org/10.1002/ece3.2900', 'https://europepmc.org/articles/PMC5433968?pdf=render', NULL, NULL, 12, NULL, 'canada', 3, 'cc by', 'Understanding crop resilience to environmental stress is critical in predicting the consequences of global climate change for agricultural systems worldwide, but to date studies addressing crop resiliency have focused primarily on plant physiological and molecular responses. Arbuscular mycorrhizal fungi (AMF) form mutualisms with many crop species, and these relationships are key in mitigating the effects of abiotic stress in many agricultural systems. However, to date there is little research examining whether (1) fungal community structure in agroecosystems is resistant to changing environmental conditions, specifically water limitation and (2) resilience of fungal community structure is moderated by agricultural management systems, namely the integration of trees into cropping systems. Here, we address these uncertainties through a rainfall reduction field experiment that manipulated short-term water availability in a soybean-based (Glycine max L. Merr.) agroforest in Southern Ontario, Canada. We employed terminal restriction fragment length polymorphism analysis to determine the molecular diversity of both general fungal and AMF communities in soybean roots under no stress, stress (rainfall shelters added), and poststress (rainfall shelters removed). We found that general fungal and AMF communities sampled from soybean roots were resistant to rainfall reduction in a monoculture, but not in an agroforest. While AMF communities were unchanged after stress removal, general fungal communities were significantly different poststress in the agroforest, indicating a capacity for resiliency. Our study indicates that generalist fungi and AMF are responsive to changes in environmental conditions and that agroecosystem management plays a key role in the resistance and resilience of fungal communities to water limitation.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6d54086b-4e35-4361-9ea7-e5633fd4736c', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Role of Soil Microbiota Enzymes in Soil Health and Activity Changes Depending on Climate Change and the Type of Soil Ecosystem', 'Daunoras J, Kačergius A, Gudiukaitė R', 2024, 'Biology', '10.3390/biology13020085', 'https://doi.org/10.3390/biology13020085', 'https://europepmc.org/articles/PMC10886310?pdf=render', NULL, NULL, 39, NULL, 'other', 1, 'cc by', 'The extracellular enzymes secreted by soil microorganisms play a pivotal role in the decomposition of organic matter and the global cycles of carbon (C), phosphorus (P), and nitrogen (N), also serving as indicators of soil health and fertility. Current research is extensively analyzing these microbial populations and enzyme activities in diverse soil ecosystems and climatic regions, such as forests, grasslands, tropics, arctic regions and deserts. Climate change, global warming, and intensive agriculture are altering soil enzyme activities. Yet, few reviews have thoroughly explored the key enzymes required for soil fertility and the effects of abiotic factors on their functionality. A comprehensive review is thus essential to better understand the role of soil microbial enzymes in C, P, and N cycles, and their response to climate changes, soil ecosystems, organic farming, and fertilization. Studies indicate that the soil temperature, moisture, water content, pH, substrate availability, and average annual temperature and precipitation significantly impact enzyme activities. Additionally, climate change has shown ambiguous effects on these activities, causing both reductions and enhancements in enzyme catalytic functions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7e60d5aa-fdc8-43ac-8623-800a9a2c7d1f', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Sprinkler irrigation on clay soils in southern Finland IV. The effect of repeated applications of water and nitrogen fertilization on spring cereals', 'Paavo Elonen, Osmo Kara', 1972, 'Agricultural and Food Science', NULL, 'https://journal.fi/afs/article/view/71820', 'https://journal.fi/afs/article/view/71820', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'In 1967 and 1968, in the month of June, irrigation of silty clay soil in southern Finland by a single sprinkling, which involved the application of 30 mm of water, increased the yields of spring wheat by an average of between 880 and 970 kg per ha, or 37—51 %, and the yields of barley by 1140—1340 kg per ha, or 37—42 %. Repeating the irrigation after about one week further increased the wheat yields on the average by from 670 to 800 kg per ha and the barley yields between 810 and 860 kg per ha. The effect of the irrigation on the size of the yields was virtually of the same magnitude both years in spite of the fact that in 1967 both June and July were extremely dry months, whereas in 1968 the dry June was followed by a rainy July. The sprinkling affected the ripening of the grain, on the other hand, differently each year: slightly retarding the ripening in 1967 but considerably hastening it in 1968. In the latter year, the irrigation prevented detrimental late tillering and thereby augmented the hectoliter weight and 1000-grain weight of the crops. In response to the one-time sprinkling, the protein content of the grains decreased in the case of the wheat by an average of 1.0—1.3 and of the barley by 0.1—0.7 %-units. The effect of two sprinklings was corresponding decreases of 1.9—3.1 and 0.8—1.0 %-units. The application to the seedlings as surface dressing immediately before irrigation of calcium nitrate containing 60 kg/ha of nitrogen increased the protein content of the wheat on the average by 1.6 and of the barley by 1.9 %-units. The nitrogen fertilization thus prevented excessive lowering of the protein content by irrigation and, furthermore, considerably intensified the salutary effect of the irrigation in augmenting the yield. A disadvantage of abundant nitrogen fertilization was a slight retardation of ripening. The placement of basal dressing with a fertilizer drill at a depth of 9 cm proved effective, particularly in 1967, when both the wheat and the barley yields increased 22 per cent in comparison with the effect of surface dressing. Use of the fertilizer drill, moreover, promoted the ripening process. Sprinkling did not appear to reduce the placement effect of the fertilizer; rather did these two methods form an exceedingly favorable combination.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('acad5e4e-efb2-449d-ab49-7680ec6f6336', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Effect of preharvest management on yield, process quality, and disease development in Russet Burbank potatoes', 'A. Ronald', 2005, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/119', 'https://mspace.lib.umanitoba.ca/bitstreams/8cf1045b-6f93-42d2-845d-e4dcda39390b/download', NULL, NULL, 189, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a214f852-82a6-4418-b221-3899f1c21f6a', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Structural variation in the pangenome of wild and domesticated barley', 'Jayakodi M, Lu Q, Pidon H, Rabanus-Wallace MT, Bayer M, Lux T, Guo Y, Jaegle B', 2024, 'Nature', '10.1038/s41586-024-08187-1', 'https://doi.org/10.1038/s41586-024-08187-1', 'https://europepmc.org/articles/PMC11655362?pdf=render', NULL, NULL, 38, NULL, 'other', 1, 'cc by-nc-nd', 'Pangenomes are collections of annotated genome sequences of multiple individuals of a species1. The structural variants uncovered by these datasets are a major asset to genetic analysis in crop plants2. Here we report a pangenome of barley comprising long-read sequence assemblies of 76 wild and domesticated genomes and short-read sequence data of 1,315 genotypes. An expanded catalogue of sequence variation in the crop includes structurally complex loci that are rich in gene copy number variation. To demonstrate the utility of the pangenome, we focus on four loci involved in disease resistance, plant architecture, nutrient release and trichome development. Novel allelic variation at a powdery mildew resistance locus and population-specific copy number gains in a regulator of vegetative branching were found. Expansion of a family of starch-cleaving enzymes in elite malting barleys was linked to shifts in enzymatic activity in micro-malting trials. Deletion of an enhancer motif is likely to change the developmental trajectory of the hairy appendages on barley grains. Our findings indicate that allelic diversity at structurally complex loci may have helped crop plants to adapt to new selective regimes in agricultural ecosystems.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2ee6660f-823e-4b1c-8519-d60283e69e3e', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Does canola compensate for lygus bug damage? : crop years 2000, 2001', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/does-canola-compensate-for-lygus-bug-damage-crop-years-2000-2001', 'https://open.alberta.ca/dataset/3f790a06-0f33-4347-b7c6-711d54ceed05/resource/0d4a07d4-cc24-4884-aed4-5941f18adb0e/download/0163010216717-does-canola-compensate-for-lygus-bug-damage-crop-years-2000-2001.pdf', NULL, NULL, 152, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported the final research findings on whether canola compensated for damage caused by lygus bugs during the 2000 and 2001 crop years. It presented field experiments that examined the effects of lygus bug density and duration of infestation, as well as sulphur fertility, on canola plant growth, damage, and yield components. The scope included experimental design, methods, statistical analyses, and results from multiple sites in Alberta. It assessed implications for crop productivity and integrated pest management, particularly the appropriateness of insecticide use during early growth stages.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('625f483f-d871-47c4-b350-ccaac3373d34', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Studies of barley feed quality', 'Government of Alberta', 1999, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/studies-of-barley-feed-quality', 'https://open.alberta.ca/dataset/5c825922-c02c-4da4-a4b9-19c1eda2f80c/resource/b4c8806b-ba1a-4231-974e-12f8f2c8f34b/download/0163010207401-studies-of-barley-feed-quality.pdf', NULL, NULL, 194, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported the results of a multi‑year research project that examined barley feed quality for ruminant livestock. It documented a series of controlled experiments evaluating genetic variation among barley cultivars, particle size effects, and comparative performance of barley and corn on rumen digestion, feed intake, milk yield, and milk composition. The report presented detailed analyses of starch and protein degradation, rumen fermentation characteristics, nutrient digestibility, and animal production responses in dairy and beef cattle. The study assessed how barley variety selection and diet formulation could improve feed efficiency and nutrient utilization under Alberta production conditions. The document concluded with implications for breeding, feed evaluation, and the use of barley as an effective alternative to corn in ruminant diets.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b67db59-8631-430a-9b3d-a9a0956d8fd5', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Studies of extreme straw strength in semidwarf six-row barley', 'Government of Alberta', 1988, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/studies-of-extreme-straw-strength-in-semidwarf-six-row-barley', 'https://open.alberta.ca/dataset/e6da7817-f173-4d31-a88d-44cdaeb276f1/resource/f8350142-2670-4f62-b60e-0076646fd8f6/download/0163010335236-studies-of-extreme-straw-strength-in-semidwarf-six-row-barley.pdf', NULL, NULL, 158, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project compared multiple barley cultivars with varying straw strengths under different fertilizer treatments and environmental conditions. Researchers found that Samson (BT521) had strong lodging resistance but inconsistent yield response, while Duke (BT469) showed better overall performance despite later maturity. Lodging during early growth reduced yields most, and stem anatomy, particularly sclerenchyma thickness, was closely linked to lodging resistance. The best yields came from the application of 90 kilograms of nitrogen and 90 kilograms of phosphorus pentoxide per hectare. Studies on drought tolerance and tillering showed no significant differences among cultivars.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('04ad1606-2c88-4c9c-8203-6a264589d3ba', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'TAMFT-3A and TAMFT-3B2 homeologs are associated with wheat preharvest sprouting', 'Vetch JM, Tillett BJ, Bruckner P, Martin JM, Marlowe K, Hooker MA, See DR, Giroux MJ', 2022, 'The plant genome', '10.1002/tpg2.20250', 'https://doi.org/10.1002/tpg2.20250', 'https://europepmc.org/articles/PMC12807268?pdf=render', NULL, NULL, 12, NULL, 'northern_plains', 3, 'cc by-nc-nd', 'The phenomenon of preharvest sprouting (PHS), caused by rain after physiological maturity and prior to harvest, negatively affects wheat (Triticum aestivum L.) production and end use. Investigating the genetics that control PHS resistance may result in increased control of seed dormancy. Multiple genes involved in the development of seed dormancy are associated with PHS. In this study, the TaMFT (3A, 3B1, 3B2, 3D), TaMKK3-4A, and TaVP1-3B genes were assessed for association with PHS in a double-haploid line (DHL) hard red winter wheat population derived from a BC1 cross between the cultivars Loma and Warhorse, where Loma was the recurrent and PHS susceptible parent. The 162 BC1 DHL lines were grown over two field seasons and PHS susceptibility was assessed by measuring PHS resistance in physiologically mature heads. The PHS variation was associated with the TaMFT-A and the B2 homeolog with Loma carrying mutant forms of each gene. No sequence variation between Loma and Warhorse was detected in the exons of the TaMFT-B1 and D homeologs. No association between PHS resistance and TaMKK3-4A or TaVp1-3B variation was observed, though Loma and Warhorse vary for TaMKK3-4A and TaVp1-3B mutations reported to be PHS associated. Previous research has shown TaMFT-3A as having a large impact on PHS resistance. In the current study, the TaMFT-3A and TaMFT-3B2 alleles each explained 14% of observed PHS variation. Markers for both TaMFT-3A and TaMFT-3B2 should be used in selecting for increased wheat dormancy and PHS resistance.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fe53b9cb-d1d8-421b-bcbf-5b34762584b1', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Effects of a fall rye cover crop on weeds and productivity of Phaseolus beans', 'Heather E. Flood, Martin H. Entz', 2018, 'Canadian Journal of Plant Science', '10.1139/cjps-2018-0161', 'https://doi.org/10.1139/cjps-2018-0161', 'https://utoronto.scholaris.ca/bitstreams/6cf52371-7d02-4593-8a5f-bdd7444791c7/download', NULL, NULL, 44, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('723e16ca-5971-48a0-a57e-d0aa59faace5', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'The anatomy of the Canadian barley market', 'Government of Alberta', 1980, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/anatomy-of-the-canadian-barley-market', 'https://open.alberta.ca/dataset/622dd2a2-1b1d-44d6-80e7-18355f68b7e7/resource/88e8190b-ac0e-45fd-980f-8be914417369/download/0163003003254-the-anatomy-of-the-canadian-barley-market.pdf', NULL, NULL, 76, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report analyzes the Canadian barley market, focusing on its price-setting mechanisms and the impact of supply and demand dynamics. It examines how U.S. corn prices and carryover stocks influence world feed grain prices, including Canadian barley, and investigates the relationship between Canadian Wheat Board factors, stocks-use ratios, and Alberta non-board barley prices. The report also addresses the efficiency of arbitrage in the Canadian feed grain market and explores the policy implications of freight rate changes on barley prices and producer profitability.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b5c06919-5409-4c99-9b2a-e8a31376fa7d', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'The barley pan-genome reveals the hidden legacy of mutation breeding', 'Jayakodi M, Padmarasu S, Haberer G, Bonthala VS, Gundlach H, Monat C, Lux T, Kamal N', 2020, 'Nature', '10.1038/s41586-020-2947-8', 'https://doi.org/10.1038/s41586-020-2947-8', 'https://europepmc.org/articles/PMC7759462?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'Genetic diversity is key to crop improvement. Owing to pervasive genomic structural variation, a single reference genome assembly cannot capture the full complement of sequence diversity of a crop species (known as the ''pan-genome''1). Multiple high-quality sequence assemblies are an indispensable component of a pan-genome infrastructure. Barley (Hordeum vulgare L.) is an important cereal crop with a long history of cultivation that is adapted to a wide range of agro-climatic conditions2. Here we report the construction of chromosome-scale sequence assemblies for the genotypes of 20 varieties of barley-comprising landraces, cultivars and a wild barley-that were selected as representatives of global barley diversity. We catalogued genomic presence/absence variants and explored the use of structural variants for quantitative genetic analysis through whole-genome shotgun sequencing of 300 gene bank accessions. We discovered abundant large inversion polymorphisms and analysed in detail two inversions that are frequently found in current elite barley germplasm; one is probably the product of mutation breeding and the other is tightly linked to a locus that is involved in the expansion of geographical range. This first-generation barley pan-genome makes previously hidden genetic variation accessible to genetic studies and breeding.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4c8aedde-03e3-47d9-8f3a-1093c888fcdc', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'The effects of bread products containing barley in the diet of non-insulin-dependent diabetics', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/effects-of-bread-products-containing-barley-in-the-diet-of-non-insulin-dependent-diabetics', 'https://open.alberta.ca/dataset/9b71b698-54f2-4678-b4b0-3e089e08ac8f/resource/9c13e199-84a6-45b0-bc54-28a74c51887b/download/0163010090716-effects-bread-products-containing-barley-diet-non-insulin-dependent-diabetics.pdf', NULL, NULL, 99, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document evaluated the long-term effects of incorporating barley bread products made from waxy hulless Alberta barley (containing approximately seven per cent β-glucan) into the usual dietary pattern of non-insulin-dependent diabetic (NIDDM) subjects. Eleven NIDDM men participated in a 24-week crossover study, comparing barley bread and control white bread periods. The barley bread period resulted in higher dietary fibre intake, improved glycemic and lipidemic responses, and a nine per cent lower mean low-density lipoprotein cholesterol/high-density lipoprotein cholesterol ratio. Insulinemic responses improved, and some subjects reduced their dose of oral hypoglycemics. The barley bread products were well accepted, indicating that their incorporation could greatly benefit the overall health of NIDDM individuals.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('71d57da4-d36b-462f-9fd5-68a4adad7d3a', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'The influence of seed treatment on hulless barley emergence and productivity', 'Government of Alberta', 2002, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/influence-of-seed-treatment-on-hulless-barley-emergence-and-productivity', 'https://open.alberta.ca/dataset/60f81a5f-ebfe-4d78-80a8-d99902b4ff8d/resource/91e52709-5736-46ff-87c3-5f50d36c45c7/download/0163010208839-the-influence-of-seed-treatment-on-hulless-barley-emergence-and-productivity.pdf', NULL, NULL, 105, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document evaluated the impact of six seed treatments: Baytan 30, Charter, Dividend XL Ready to Apply (RTA), ProSeed, Vitaflo 280, and Vitavax Single on the emergence and productivity of hulless barley varieties during the 1998 and 1999 growing seasons at five sites in central and northern Alberta. An experimental compound was added in 1999. Four hulless barley varieties, including CDC Dawn, CDC Gainer, Falcon, and Phoenix, and two hulled varieties, Kasota and Harrington, were tested. A second experiment in 1999 assessed the effect of seed density (plump, non plump, and bulk) on emergence and yield. Baytan and ProSeed were found to negatively affect emergence, while other treatments showed no consistent impact. Seed density influenced emergence but did not consistently improve thousand kernel weight or test weight. Environmental factors and varietal differences were the primary drivers of variability in emergence and productivity.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b4a81df8-fa37-488c-be2e-9de6d3a92a2f', '1ac6f7be-9352-4aed-a714-2590e193c83f', 'Concentração salina e fases de exposição à salinidade do meloeiro cultivado em substrato de fibra de coco Salt concentration and phases of exposure tosalinity of melon grown in coconut fiber substrate', 'Nildo da Silva Dias, André Moreira de Oliveira, Osvaldo Nogueira de Sousa Neto, Flávio Favaro Blanco, Jonatas Rafael Lacerda Rebolças', 2011, 'Revista Brasileira de Fruticultura', NULL, 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-29452011000300027', 'http://www.scielo.br/scielo.php?script=sci_arttext&pid=S0100-29452011000300027', NULL, NULL, 7, NULL, 'other', 1, 'open access (DOAJ)', 'No semiárido, a escassez de água de boa qualidade faz com que os produtores utilizem água salobra para preparar a solução nutritiva. Com o objetivo de investigar a utilização de água salobra na irrigação de meloeiro (Cucumis melo L., cv. AF 015) cultivado em substrato de fibra de coco em casa de vegetação, plantas foram nutridas com soluções salinas de condutividades elétricas (CEs) 1,1 (testemunha); 2,5; 4,0 e 5,5 dS m-1 aplicadas durante as fases: crescimento vegetativo (10-30 dias após o transplantio-DAT); florescimento (31-50 DAT) e frutificação e maturação (51-70 DAT). O delineamento experimental foi o inteiramente casualizado, com 12 tratamentos arranjados em um esquema fatorial 4x3 (níveis de salinidade x tempo de exposição dos sais), com três repetições. Houve correlação na perda relativa por incremento de CEs das variáveis de crescimento e de produção do meloeiro em função da salinidade da solução nutritiva para cada fase de exposição. As soluções nutritivas preparadas com água salobra podem ser utilizadas no cultivo do meloeiro em substrato de fibra de coco com o mínimo de perdas relativas de massa média de frutos por incremento de CEs, quando aplicadas na fase de florescimento.Scarcity of good water quality in semiarid region causes producers to use brackish water to prepare the nutrient solution. In order to investigate the use of brackish water in irrigation of greenhouse-melon (Cucumis melo L., cv. AF 015) grown in coconut fiber substrate, plants were irrigated with saltine nutrient solutions of electrical conductivities (ECs) of 1.1 (control), 2.5, 4.0 and 5.5 dS m-1, applied during the phases of vegetative growth (10-30 days after transplanting, DAT), flowering (31-50 DAT) and fruiting and ripening (51-70 DAT). The design was completely randomized, with 12 treatments arranged in a 4x3 factorial design (salinity levels x exposure time of the salts), with three replications. There was a correlation in the reduction relative to each increased de ECs of the growth and yield variables of melon in function of ECs for each phase of exposure. The nutrient solutions prepared with brackish water can be used to grow melons in coconut fiber substrate with minimal reduction relative of mean fruit weight with increasing ECs applied during flowering.', '{doaj,topic}', 'link_only', NULL, NULL, '2026-11-19 05:15:49.205119+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3d536d46-fa5a-4d49-9aca-af23f7ea3991', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'The preceding root system drives the composition and function of the rhizosphere microbiome', 'Zhou Y, Coventry DR, Gupta VVSR, Fuentes D, Merchant A, Kaiser BN, Li J, Wei Y', 2020, 'Genome biology', '10.1186/s13059-020-01999-0', 'https://doi.org/10.1186/s13059-020-01999-0', 'https://europepmc.org/articles/PMC7137527?pdf=render', NULL, NULL, 19, NULL, 'other', 1, 'cc by', 'BackgroundThe soil environment is responsible for sustaining most terrestrial plant life, yet we know surprisingly little about the important functions carried out by diverse microbial communities in soil. Soil microbes that inhabit the channels of decaying root systems, the detritusphere, are likely to be essential for plant growth and health, as these channels are the preferred locations of new root growth. Understanding the microbial metagenome of the detritusphere, and how it responds to agricultural management such as crop rotations and soil tillage, is vital for improving global food production.ResultsThis study establishes an in-depth soil microbial gene catalogue based on the living-decaying rhizosphere niches in a cropping soil. The detritusphere microbiome regulates the composition and function of the rhizosphere microbiome to a greater extent than plant type: rhizosphere microbiomes of wheat and chickpea were homogenous (65-87% similarity) in the presence of decaying root (DR) systems but were heterogeneous (3-24% similarity) where DR was disrupted by tillage. When the microbiomes of the rhizosphere and the detritusphere interact in the presence of DR, there is significant degradation of plant root exudates by the rhizosphere microbiome, and genes associated with membrane transporters, carbohydrate and amino acid metabolism are enriched.ConclusionsThe study describes the diversity and functional capacity of a high-quality soil microbial metagenome. The results demonstrate the contribution of the detritusphere microbiome in determining the metagenome of developing root systems. Modifications in root microbial function through soil management can ultimately govern plant health, productivity and food security.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('77546846-d4cd-4d98-84f9-d85327433bbf', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'The yield of spring barley in the brown soils of the Nizhnee Povolzh''e region', 'A V Shuravilin, V V Borodachev, A E Novikov, A A Poddubsky', 2016, 'RUDN Journal of Agronomy and Animal Industries', '10.22363/2312-797X-2016-2-7-14', 'https://doi.org/10.22363/2312-797X-2016-2-7-14', 'http://journals.rudn.ru/agronomy/article/view/1407', NULL, NULL, 8, NULL, 'other', 1, 'open access (DOAJ)', 'The results of small (20-22 cm) and relatively deep main processing of the soil (27-30 cm) and variable rate application depth of arable horizon of doses of mineral nutrition (N and P2O5) on yield of spring barley. It is established that ploughing soil up to 30 cm (pillars of Cibima) with in-corporation at the same depth easy phosphorus-rhenium increases the biological activity of the soil microflora involved in the proposal of cellulose substrates is a means of increasing the fertility of light chestnut soil, which is especially important for rainfed conditions. The average crop capacity in the shallow plowing is 2 t/ha and was lower at 15% compared to Varian, where he held a deep subsurface tillage. By years of research sum-total biological activity in the deep subsurface treat-ment amounted to 930 mg of amino acids per gram of leaf, which is higher by 26% the variant with shallow plowing. Compared to shallow ploughing (option 1) at subsurface relatively deep processing of crude soil (option 2) there is greater accumulation of productive moisture in a meter layer. In the period of tillering of plants at average moisture reserves in option 2 is higher by 16% than in option 1 and constitute a 147 mm. In phase trubavina-earing and full maturity of the spring-barley the difference between the productive moisture content increases to between 20 and 33% in the direction of no-till deep processing. Relatively high soil moisture (a consequence of the method of tillage) contributed to a more rapid transition of phosphates in the horizon of 25-30 cm and nitrate in the layer 10-15 cm in available forms of nutrients for soil microorganisms. It is revealed that the application rate of nitrogen and phosphorus should be linked with the main processing of the soil, and the peculiarities of development of the root system of cultivated crops.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('14adfb36-d7c7-451a-b34c-f117263d8966', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Trace Mineral Nutrition of Grazing Beef Cattle', 'Arthington JD, Ranches J', 2021, 'Animals : an open access journal from MDPI', '10.3390/ani11102767', 'https://doi.org/10.3390/ani11102767', 'https://europepmc.org/articles/PMC8532955?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'The trace mineral requirements of grazing beef cattle are often complicated by different environmental factors, such as the lack of specific trace minerals or the presence of trace mineral antagonists in forage. Nearly every region of the world has specific implications related to trace mineral nutrition of grazing cattle. Since forage is the most significant contributor to trace mineral nutrition, it is important to consider the concentrations of trace minerals and antagonists and how they may impact the performance of cattle consuming them. This review attempts to provide an update on the trace minerals commonly found to be inadequate in forage, supplementation strategies to address deficiency including a discussion on supplemental trace mineral source, and the complications presented by mineral antagonists. Although the review focuses on beef cattle grazing systems of the United States, the information herein is derived from both extensive native range and intensive planted pasture.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('656e103b-010c-42c3-bb64-722e00de1924', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Use of barley/annual ryegrass intercrop system to optimize barley-based diets for beef cattle', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/use-of-barleyannual-ryegrass-intercrop-system-to-optimize-barley-based-diets-for-beef-cattle', 'https://open.alberta.ca/dataset/791b11c0-1a8f-4b9b-86c5-e74758c69043/resource/e7bc3451-d5f2-48df-b2e5-813c06f2ab73/download/0163010145114-use-barleyannual-ryegrass-intercrop-system-optimize-barley-based-diets-beef-cattle.pdf', NULL, NULL, 39, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported the results of a research project that evaluated a barley and annual ryegrass intercrop system for optimizing barley based diets for beef cattle. It described the cultivation of intercropped barley and annual ryegrass, silage preparation, and controlled backgrounding and finishing feeding trials comparing intercrop silage with conventional barley silage. The report presented analyses of forage yield, silage quality, diet composition, animal performance, carcass characteristics, rumen fermentation, and in vitro digestibility. The study assessed the nutritional and production implications of using intercrop silage within feedlot systems under Alberta conditions. The document concluded by examining the relevance of this feeding system to Alberta agriculture and its potential to improve beef production efficiency.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a4fef51b-cebe-4392-a257-22a7e526cec3', '7b5a72e9-5169-4611-9d35-bdd8000a187e', 'Utilization of a Wheat55K SNP Array for Mapping of Major QTL for Temporal Expression of the Tiller Number', 'Ren T, Hu Y, Tang Y, Li C, Yan B, Ren Z, Tan F, Tang Z', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00333', 'https://doi.org/10.3389/fpls.2018.00333', 'https://europepmc.org/articles/PMC5862827?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Maximum tiller number and productive tiller number are important traits for wheat grain yield, but research involving the temporal expression of tiller number at different quantitative trait loci (QTL) levels is limited. In the present study, a population set of 371 recombined inbred lines derived from a cross between Chuan-Nong18 and T1208 was used to construct a high-density genetic map using a Wheat55K SNP Array and to perform dynamic QTL analysis of the tiller number at four growth stages. A high-density genetic map containing 11,583 SNP markers and 59 SSR markers that spanned 4,513.95 cM and was distributed across 21 wheat chromosomes was constructed. A total of 28 single environmental QTL were identified in the recombined inbred lines population, and among these, seven QTL were stable and used for multi-environmental and dynamic analysis. These QTL were mapped to chromosomes 2D, 4A, 4D, 5A, 5D, and 7D, respectively. Each QTL explained 1.63-21.22% of the observed phenotypic variation, with an additive effect from -20.51 to 11.59. Dynamic analysis showed that cqTN-2D.2 can be detected at four growth stages of tillering, explaining 4.92-17.16% of the observed phenotypic variations and spanning 13.71 Mb (AX-109283238-AX-110544009: 82189047-95895626) according to the physical location of the flanking markers. The effects of the stable QTL were validated in the recombined inbred lines population, and the beneficial alleles could be utilized in future marker-assisted selection. Several candidate genes for MTN and PTN were predicted. The results provide a better understanding of the QTL selectively expressing the control of tiller number and will facilitate future map-based cloning. 9.17% SNP markers showed best hits to the Chinese Spring contigs. It was indicated that Wheat55K Array was efficient and valid to construct a high-density wheat genetic map.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('324ce3b3-8327-493d-8b3a-24bd6fabac85', 'e674c556-4770-485c-ba28-262e36c330bf', 'Biochemical and Physiological Plant Processes Affected by Seed Treatment with Non-Thermal Plasma', 'Mildaziene V, Ivankov A, Sera B, Baniulis D', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11070856', 'https://doi.org/10.3390/plants11070856', 'https://europepmc.org/articles/PMC9003542?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by', 'Among the innovative technologies being elaborated for sustainable agriculture, one of the most rapidly developing fields relies on the positive effects of non-thermal plasma (NTP) treatment on the agronomic performance of plants. A large number of recent publications have indicated that NTP effects are far more persistent and complex than it was supposed before. Knowledge of the molecular basis and the resulting outcomes of seed treatment with NTP is rapidly accumulating and requires to be analyzed and presented in a systematic way. This review focuses on the biochemical and physiological processes in seeds and plants affected by seed treatment with NTP and the resulting impact on plant metabolism, growth, adaptability and productivity. Wide-scale changes evolving at the epigenomic, transcriptomic, proteomic and metabolic levels are triggered by seed irradiation with NTP and contribute to changes in germination, early seedling growth, phytohormone amounts, metabolic and defense enzyme activity, secondary metabolism, photosynthesis, adaptability to biotic and abiotic stress, microbiome composition, and increased plant fitness, productivity and growth on a longer time scale. This review highlights the importance of these novel findings, as well as unresolved issues that remain to be investigated.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4eac427a-d927-4bb6-847a-edbc45e23e3c', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'A Systematic Review on the Continuous Cropping Obstacles and Control Strategies in Medicinal Plants', 'Zeeshan Ul Haq M, Yu J, Yao G, Yang H, Iqbal HA, Tahir H, Cui H, Liu Y', 2023, 'International journal of molecular sciences', '10.3390/ijms241512470', 'https://doi.org/10.3390/ijms241512470', 'https://europepmc.org/articles/PMC10419402?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Continuous cropping (CC) is a common practice in agriculture, and usually causes serious economic losses due to soil degeneration, decreased crop yield and quality, and increased disease incidence, especially in medicinal plants. Continuous cropping obstacles (CCOs) are mainly due to changes in soil microbial communities, nutrient availability, and allelopathic effects. Recently, progressive studies have illustrated the molecular mechanisms of CCOs, and valid strategies to overcome them. Transcriptomic and metabolomics analyses revealed that identified DEGs (differently expressed genes) and metabolites involved in the response to CCOs are involved in various biological processes, including photosynthesis, carbon metabolism, secondary metabolite biosynthesis, and bioactive compounds. Soil improvement is an effective strategy to overcome this problem. Soil amendments can improve the microbial community by increasing the abundance of beneficial microorganisms, soil fertility, and nutrient availability. In this review, we sum up the recent status of the research on CCOs in medicinal plants, the combination of transcriptomic and metabolomics studies, and related control strategies, including uses of soil amendments, crop rotation, and intercropping. Finally, we propose future research trends for understanding CCOs, and strategies to overcome these obstacles and promote sustainable agriculture practices in medicinal plants.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('155830b4-2ac5-4f20-85d1-05dc488975c5', 'e674c556-4770-485c-ba28-262e36c330bf', 'Breeding Beyond Monoculture: Putting the "Intercrop" Into Crops', 'Bourke PM, Evers JB, Bijma P, van Apeldoorn DF, Smulders MJM, Kuyper TW, Mommer L, Bonnema G', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.734167', 'https://doi.org/10.3389/fpls.2021.734167', 'https://europepmc.org/articles/PMC8636715?pdf=render', NULL, NULL, 18, NULL, 'other', 1, 'cc by', 'Intercropping is both a well-established and yet novel agricultural practice, depending on one''s perspective. Such perspectives are principally governed by geographic location and whether monocultural practices predominate. Given the negative environmental effects of monoculture agriculture (loss of biodiversity, reliance on non-renewable inputs, soil degradation, etc.), there has been a renewed interest in cropping systems that can reduce the impact of modern agriculture while maintaining (or even increasing) yields. Intercropping is one of the most promising practices in this regard, yet faces a multitude of challenges if it is to compete with and ultimately replace the prevailing monocultural norm. These challenges include the necessity for more complex agricultural designs in space and time, bespoke machinery, and adapted crop cultivars. Plant breeding for monocultures has focused on maximizing yield in single-species stands, leading to highly productive yet specialized genotypes. However, indications suggest that these genotypes are not the best adapted to intercropping systems. Re-designing breeding programs to accommodate inter-specific interactions and compatibilities, with potentially multiple different intercropping partners, is certainly challenging, but recent technological advances offer novel solutions. We identify a number of such technology-driven directions, either ideotype-driven (i.e., "trait-based" breeding) or quantitative genetics-driven (i.e., "product-based" breeding). For ideotype breeding, plant growth modeling can help predict plant traits that affect both inter- and intraspecific interactions and their influence on crop performance. Quantitative breeding approaches, on the other hand, estimate breeding values of component crops without necessarily understanding the underlying mechanisms. We argue that a combined approach, for example, integrating plant growth modeling with genomic-assisted selection and indirect genetic effects, may offer the best chance to bridge the gap between current monoculture breeding programs and the more integrated and diverse breeding programs of the future.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5d8a4c9e-ac90-4042-82aa-ef72b2e4f340', 'e674c556-4770-485c-ba28-262e36c330bf', 'Defense Strategies of Rice in Response to the Attack of the Herbivorous Insect, Chilo suppressalis', 'Xiang X, Liu S, Li H, Danso Ofori A, Yi X, Zheng A', 2023, 'International journal of molecular sciences', '10.3390/ijms241814361', 'https://doi.org/10.3390/ijms241814361', 'https://europepmc.org/articles/PMC10531896?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Chilo suppressalis is a notorious pest that attacks rice, feeding throughout the entire growth period of rice and posing a serious threat to rice production worldwide. Due to the boring behavior and overlapping generations of C. suppressalis, the pest is difficult to control. Moreover, no rice variety with high resistance to the striped stem borer (SSB) has been found in the available rice germplasm, which also poses a challenge to controlling the SSB. At present, chemical control is widely used in agricultural production to manage the problem, but its effect is limited and it also pollutes the environment. Therefore, developing genetic resistance is the only way to avoid the use of chemical insecticides. This article primarily focuses on the research status of the induced defense of rice against the SSB from the perspective of immunity, in which plant hormones (such as jasmonic acid and ethylene) and mitogen-activated protein kinases (MAPKs) play an important role in the immune response of rice to the SSB. The article also reviews progress in using transgenic technology to study the relationship between rice and the SSB as well as exploring the resistance genes. Lastly, the article discusses prospects for future research on rice''s resistance to the SSB.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2850e93b-e87a-4104-8154-e2de4ab64665', 'e674c556-4770-485c-ba28-262e36c330bf', 'Inoculation of black turtle beans (Phaseolus vulgaris) with mycorrhizal fungi increases the nutritional quality of seeds', 'Joseph E. Carrara, Lavanya Reddivari, Wade P. Heller', 2024, 'Plant-Environment Interactions', '10.1002/pei3.10128', 'https://doi.org/10.1002/pei3.10128', 'https://doi.org/10.1002/pei3.10128', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract The use of arbuscular mycorrhizal fungi (AMF) as biofertilizers has proven successful in boosting the yield and nutritional quality of a variety of crops. AMF associate with plant roots and exchange soil nutrients for photosynthetically derived C in the form of sugars and lipids. Past research has shown that not all AMF species are equal in their benefit to nutrient uptake and crop health, and that the most beneficial AMF species appear to vary by host species. Although an important human food staple, especially in developing regions where nutrient deficiency is a prevalent threat to public health, little work has been done to test the effectiveness of AMF in enhancing the nutritional quality of common bean (Phaseolus vulgaris L.). Therefore, our objective was to determine the most beneficial AMF species for inoculation of this important crop. We inoculated black beans (Phaseolus vulgaris black turtle beans) with eight individual AMF species and one mixed species inoculum in an outdoor pot trial over 3 months and assessed the extent to which they altered yield, mineral nutrient and anthocyanin concentration of seeds and leaf tissues. Despite seeing no yield effects from inoculation, we found that across treatments percent root length colonized by AMF was positively correlated with plant tissue P, Cu, and Zn concentration. Underlying these broad benefits, seeds from plants inoculated with three AMF species, Claroideoglomus claroideum (+15%), Funneliformis mosseae (+13%), and Gigaspora rosea (+11%) had higher P concentration than non‐mycorrhizal plants. C. claroideum also increased seed potassium (K) and copper (Cu), as well as leaf aluminum (Al) concentration making it a promising candidate to further test the benefit of individual AMF species on black bean growth in field trials.', '{doaj,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c2ab7243-790e-4f3b-a191-a86ece5689a9', 'e674c556-4770-485c-ba28-262e36c330bf', 'Potential of Thuja occidentalis L. Essential Oil and Water Extracts against Field Crop Pests', 'Gospodarek J, Krajewska A, Paśmionka IB, Bruździńska J, Tamiru G', 2024, 'Molecules (Basel, Switzerland)', '10.3390/molecules29071457', 'https://doi.org/10.3390/molecules29071457', 'https://europepmc.org/articles/PMC11013141?pdf=render', NULL, NULL, 25, NULL, 'northern_plains', 3, 'cc by', 'Thuja occidentalis L. essential oil (EOTO) and its compounds, such as terpinyl acetate, bornyl acetate, and β-thujone, are claimed to be highly effective against some storage pests, sanitary insects, or pests of fruit trees, while data about its use in protecting field crops are very scarce. There is also a lack of information in the literature about the insecticidal value of water extracts from T. occidentalis (WETOs). Both essential oils (EOs) and water extracts (WEs) from various plants have advantages and disadvantages in terms of their use as insecticides. EOs are generally more effective, but their preparation is more complicated and quite expensive. In turn, WEs are simple to prepare and cheap, but they often have limited effectiveness. Moreover, significant differences in responses exist depending on the species of the donor plant, the method of preparing the extract, its concentration, the species of the pest being controlled, the developmental stage, and even the gender of the pest. The goals of the research were to assess the effect of EOTO and WETOs prepared from dry and fresh matter on the mortality, feeding, and body mass changes of important crop pests, i.e., the black bean aphid, pea leaf weevil, and Colorado potato beetle (CPB), respectively, as well as on the mortality and voracity of non-target organism Asian lady beetle young larvae. EOTO showed significant aphicidal activity with LC50 = 0.8267% and 0.2453% after 42 h of the experiment for nymphs and wingless females of black bean aphid, respectively. Adults of CPB were more resistant to EOTO than aphids, with LC50 values for females equal to 1.5327% and 1.3113% after 48 h and after 72 h of the experiment. There was no significant effect of EOTO on CPB foraging. Calculated LC50 values for pea leaf weevil adults were lower than those for CPB (0.9638% and 0.8573% for males after 12 h and 24 h, respectively). In the case of this pest, a clear reduction in foraging was obtained, with higher concentrations of EOTO resulting in more pronounced reductions in foraging behavior. Concentrations of EOTO above 0.5%, which showed efficacy against the aphid, were lethal to 3-day-old larvae of the Asian lady beetle. WETOs, in turn, showed significant potential in inhibiting adult pea leaf weevil feeding, with very low or no effectiveness in reducing A. fabae and CPB, respectively.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fd50202e-1cd1-41b0-a009-5db4f7eb3530', 'e674c556-4770-485c-ba28-262e36c330bf', 'Prioritization of deleterious mutations informs genomic prediction and increases the rate of gain in common bean (Phaseolus vulgaris L.), a simulation study', 'Cordoba-Novoa H, Hoyos-Villegas V', 2026, 'TAG. Theoretical and applied genetics. Theoretische und angewandte Genetik', '10.1007/s00122-026-05329-z', 'https://doi.org/10.1007/s00122-026-05329-z', 'https://europepmc.org/articles/PMC13433502?pdf=render', NULL, NULL, 21, NULL, 'canada', 3, 'cc by', 'Key messagePredicted deleterious mutations (SNPs) have different distributions of effects compared to random SNPs based on population composition. Variant prioritization of markers based on deleterious scores can improve the prediction of yield. Favoring mating schemes between parents with fewer highly deleterious mutations can increase the rate of genetic gain. The study of mutations is fundamental to understanding evolution, domestication, and genetics. Characterizing mutations has potential to accelerate breeding programs through selection and purging deleterious mutations (DelMut). We investigated how predicting DelMut in breeding populations informs genomic prediction (GP) increasing the rate of genetic gain. DelMut were annotated in three independent common bean populations using a previously developed random forest (RF) model for common bean incorporating phylogenetic and protein information. Deleterious scores from the RF model were around 0.25, with the top 1% (highly DelMut) of variants scoring between 0.78 and 0.82 among populations. All populations showed variation in the number of highly DelMut per line (max. 13-197) and in genetic load. We assessed the impact of incorporating a priori information on DelMut for variant prioritization and weighting in GP models for yield and flowering time. Stochastic simulations were conducted to evaluate how designing mating schemes based on variable numbers of DelMut per parent can affect genetic gain. Variants with higher predicted scores had significantly different effect distributions compared to random or lower-scored markers. Simulated breeding cycles showed that selecting parents with fewer highly DelMut consistently increases the rate of genetic gain, and depending on the population, can be superior to phenotypic selection. These results highlight the potential of DelMut information for variant prioritization and the optimization of common bean breeding programs. The approaches we developed can be applied to other species to improve the efficacy of crop improvement.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4a0c133-0d75-451c-a5b4-73340d8a3d6b', 'e674c556-4770-485c-ba28-262e36c330bf', 'Redox-Epigenetic Crosstalk in Plant Stress Responses: The Roles of Reactive Oxygen and Nitrogen Species in Modulating Chromatin Dynamics', 'Kaya C, Adamakis IS', 2025, 'International journal of molecular sciences', '10.3390/ijms26157167', 'https://doi.org/10.3390/ijms26157167', 'https://europepmc.org/articles/PMC12345703?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by', 'Plants are constantly exposed to environmental stressors such as drought, salinity, and extreme temperatures, which threaten their growth and productivity. To counter these challenges, they employ complex molecular defense systems, including epigenetic modifications that regulate gene expression without altering the underlying DNA sequence. This review comprehensively examines the emerging roles of reactive oxygen species (ROS) and reactive nitrogen species (RNS) as central signaling molecules orchestrating epigenetic changes in response to abiotic stress. In addition, biotic factors such as pathogen infection and microbial interactions are considered for their ability to trigger ROS/RNS generation and epigenetic remodeling. It explores how ROS and RNS influence DNA methylation, histone modifications, and small RNA pathways, thereby modulating chromatin structure and stress-responsive gene expression. Mechanistic insights into redox-mediated regulation of DNA methyltransferases, histone acetyltransferases, and microRNA expression are discussed in the context of plant stress resilience. The review also highlights cutting-edge epigenomic technologies such as whole-genome bisulfite sequencing (WGBS), chromatin immunoprecipitation sequencing (ChIP-seq), and small RNA sequencing, which are enabling precise mapping of stress-induced epigenetic landscapes. By integrating redox biology with epigenetics, this work provides a novel framework for engineering climate-resilient crops through the targeted manipulation of stress-responsive epigenomic signatures.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c5289d7f-fb97-421d-a2d7-f85af77e3f5e', 'e674c556-4770-485c-ba28-262e36c330bf', 'The challenge of breeding for reduced off-flavor in faba bean ingredients', 'Lippolis A, Roland WSU, Bocova O, Pouvreau L, Trindade LM', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1286803', 'https://doi.org/10.3389/fpls.2023.1286803', 'https://europepmc.org/articles/PMC10642941?pdf=render', NULL, NULL, 22, NULL, 'other', 1, 'cc by', 'The growing interest in plant protein sources, such as pulses, is driven by the necessity for sustainable food production and climate change mitigation strategies. Faba bean (Vicia faba L.) is a promising protein crop for temperate climates, owing to its remarkable yield potential (up to 8 tonnes ha-1 in favourable growing conditions) and high protein content (~29% dry matter basis). Nevertheless, the adoption of faba bean protein in plant-based products that aim to resemble animal-derived counterparts is hindered by its distinctive taste and aroma, regarded as "off-flavors". In this review, we propose to introduce off-flavor as a trait in breeding programs by identifying molecules involved in sensory perception and defining key breeding targets. We discuss the role of lipid oxidation in producing volatile and non-volatile compounds responsible for the beany aroma and bitter taste, respectively. We further investigate the contribution of saponin, tannin, and other polyphenols to bitterness and astringency. To develop faba bean varieties with diminished off-flavors, we suggest targeting genes to reduce lipid oxidation, such as lipoxygenases (lox) and fatty acid desaturases (fad), and genes involved in phenylpropanoid and saponin biosynthesis, such as zero-tannin (zt), chalcone isomerase (chi), chalcone synthase (chs), β-amyrin (bas1). Additionally, we address potential challenges, including the need for high-throughput phenotyping and possible limitations that could arise during the genetic improvement process. The breeding approach can facilitate the use of faba bean protein in plant-based food such as meat and dairy analogues more extensively, fostering a transition toward more sustainable and climate-resilient diets.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dccad1c2-70a7-4f32-b961-dab75453c289', 'e674c556-4770-485c-ba28-262e36c330bf', 'The potential of Paraburkholderia species to enhance crop growth', 'Rojas-Rojas FU, Gómez-Vázquez IM, Estrada-de Los Santos P, Shimada-Beltrán H, Vega-Arreguín JC', 2025, 'World journal of microbiology & biotechnology', '10.1007/s11274-025-04256-3', 'https://doi.org/10.1007/s11274-025-04256-3', 'https://europepmc.org/articles/PMC11794353?pdf=render', NULL, NULL, 38, NULL, 'other', 1, 'cc by', 'Agrochemicals are the primary alternative for maintaining the high yields necessary to produce sufficient plant-based foods to supply the world population. In recent decades, one of the most extensively explored alternatives to replace agrochemicals and reduce their environmental impact has been the use of microorganism-based products to boost crop yields with less environmental impact. This review focuses on the results of studies that have demonstrated the potential of the genus Paraburkholderia to increase crop yields and be utilized in biofertilizers and biocontrol products. A literature search was performed electronically considering articles and books published until August 19, 2024. We identified 24 species of Paraburkholderia with the ability to improve crop yields after their inoculation by different methods on seeds, seedlings, plantlets, adult crops, or fruits. The effects of these bacteria have been tested under laboratory, greenhouse, or field conditions. These Paraburkholderia species mediate their positive impact on crop growth by direct and indirect plant growth-promoting mechanisms, which include improving nutrient uptake, stimulating growth by phytohormone production, regulation and stimulation of metabolic pathways, induction of abiotic stress tolerance, and disease control by direct pathogen inhibition or induction of systemic resistance in plants. The literature reviewed here supports the use of Paraburkholderia in bio-inputs under the actual panorama of climate change and the necessity to increase sustainable agriculture worldwide.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('933a0904-fc8c-4830-83c1-a72d5a6c6c0c', '978e45ab-ccab-499d-93c3-105541378309', 'Developing Climate-Resilient Chickpea Involving Physiological and Molecular Approaches With a Focus on Temperature and Drought Stresses', 'Rani A, Devi P, Jha UC, Sharma KD, Siddique KHM, Nayyar H', 2019, 'Frontiers in plant science', '10.3389/fpls.2019.01759', 'https://doi.org/10.3389/fpls.2019.01759', 'https://europepmc.org/articles/PMC7052492?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Chickpea is one of the most economically important food legumes, and a significant source of proteins. It is cultivated in more than 50 countries across Asia, Africa, Europe, Australia, North America, and South America. Chickpea production is limited by various abiotic stresses (cold, heat, drought, salt, etc.). Being a winter-season crop in northern south Asia and some parts of the Australia, chickpea faces low-temperature stress (0-15°C) during the reproductive stage that causes substantial loss of flowers, and thus pods, to inhibit its yield potential by 30-40%. The winter-sown chickpea in the Mediterranean, however, faces cold stress at vegetative stage. In late-sown environments, chickpea faces high-temperature stress during reproductive and pod filling stages, causing considerable yield losses. Both the low and the high temperatures reduce pollen viability, pollen germination on the stigma, and pollen tube growth resulting in poor pod set. Chickpea also experiences drought stress at various growth stages; terminal drought, along with heat stress at flowering and seed filling can reduce yields by 40-45%. In southern Australia and northern regions of south Asia, lack of chilling tolerance in cultivars delays flowering and pod set, and the crop is usually exposed to terminal drought. The incidences of temperature extremes (cold and heat) as well as inconsistent rainfall patterns are expected to increase in near future owing to climate change thereby necessitating the development of stress-tolerant and climate-resilient chickpea cultivars having region specific traits, which perform well under drought, heat, and/or low-temperature stress. Different approaches, such as genetic variability, genomic selection, molecular markers involving quantitative trait loci (QTLs), whole genome sequencing, and transcriptomics analysis have been exploited to improve chickpea production in extreme environments. Biotechnological tools have broadened our understanding of genetic basis as well as plants'' responses to abiotic stresses in chickpea, and have opened opportunities to develop stress tolerant chickpea.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ebee147-ce25-43f2-a4a7-88da88d83607', '978e45ab-ccab-499d-93c3-105541378309', 'Evaluation of soybean germplasm conserved in NIAS genebank and development of mini core collections', 'Kaga A, Shimizu T, Watanabe S, Tsubokura Y, Katayose Y, Harada K, Vaughan DA, Tomooka N', 2012, 'Breeding science', '10.1270/jsbbs.61.566', 'https://doi.org/10.1270/jsbbs.61.566', 'https://europepmc.org/articles/PMC3406788?pdf=render', NULL, NULL, 27, NULL, 'other', 1, 'cc by-nc-nd', 'Genetic variation and population structure among 1603 soybean accessions, consisted of 832 Japanese landraces, 109 old and 57 recent Japanese varieties, 341 landrace from 16 Asian countries and 264 wild soybean accessions, were characterized using 191 SNP markers. Although gene diversity of Japanese soybean germplasm was slight lower than that of exotic soybean germplasm, population differentiation and clustering analyses indicated clear genetic differentiation among Japanese cultivated soybeans, exotic cultivated soybeans and wild soybeans. Nine hundred ninety eight Japanese accessions were separated to a certain extent into groups corresponding to their agro-morphologic characteristics such as photosensitivity and seed characteristics rather than their geographical origin. Based on the assessment of the SNP markers and several agro-morphologic traits, accessions that retain gene diversity of the whole collection were selected to develop several soybean sets of different sizes using an heuristic approach; a minimum of 12 accessions can represent the observed gene diversity; a mini-core collection of 96 accession can represent a major proportion of both geographic origin and agro-morphologic trait variation. These selected sets of germplasm will provide an effective platform for enhancing soybean diversity studies and assist in finding novel traits for crop improvement.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('dfcba50a-7947-4bb3-9f1b-a96c441d450e', '978e45ab-ccab-499d-93c3-105541378309', 'Genetic Associations in Four Decades of Multienvironment Trials Reveal Agronomic Trait Evolution in Common Bean', 'MacQueen AH, White JW, Lee R, Osorno JM, Schmutz J, Miklas PN, Myers J, McClean PE', 2020, 'Genetics', '10.1534/genetics.120.303038', 'https://doi.org/10.1534/genetics.120.303038', 'https://europepmc.org/articles/PMC7198278?pdf=render', NULL, NULL, 18, NULL, 'canada', 3, 'cc by', 'Multienvironment trials (METs) are widely used to assess the performance of promising crop germplasm. Though seldom designed to elucidate genetic mechanisms, MET data sets are often much larger than could be duplicated for genetic research and, given proper interpretation, may offer valuable insights into the genetics of adaptation across time and space. The Cooperative Dry Bean Nursery (CDBN) is a MET for common bean (Phaseolus vulgaris) grown for > 70 years in the United States and Canada, consisting of 20-50 entries each year at 10-20 locations. The CDBN provides a rich source of phenotypic data across entries, years, and locations that is amenable to genetic analysis. To study stable genetic effects segregating in this MET, we conducted genome-wide association studies (GWAS) using best linear unbiased predictions derived across years and locations for 21 CDBN phenotypes and genotypic data (1.2 million SNPs) for 327 CDBN genotypes. The value of this approach was confirmed by the discovery of three candidate genes and genomic regions previously identified in balanced GWAS. Multivariate adaptive shrinkage (mash) analysis, which increased our power to detect significant correlated effects, found significant effects for all phenotypes. Mash found two large genomic regions with effects on multiple phenotypes, supporting a hypothesis of pleiotropic or linked effects that were likely selected on in pursuit of a crop ideotype. Overall, our results demonstrate that statistical genomics approaches can be used on MET phenotypic data to discover significant genetic effects and to define genomic regions associated with crop improvement.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('efb32574-5836-45d1-9482-44547bf977a5', '978e45ab-ccab-499d-93c3-105541378309', 'Machine Learning in Agriculture: A Comprehensive Updated Review', 'Benos L, Tagarakis AC, Dolias G, Berruto R, Kateris D, Bochtis D', 2021, 'Sensors (Basel, Switzerland)', '10.3390/s21113758', 'https://doi.org/10.3390/s21113758', 'https://europepmc.org/articles/PMC8198852?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'The digital transformation of agriculture has evolved various aspects of management into artificial intelligent systems for the sake of making value from the ever-increasing data originated from numerous sources. A subset of artificial intelligence, namely machine learning, has a considerable potential to handle numerous challenges in the establishment of knowledge-based farming systems. The present study aims at shedding light on machine learning in agriculture by thoroughly reviewing the recent scholarly literature based on keywords'' combinations of "machine learning" along with "crop management", "water management", "soil management", and "livestock management", and in accordance with PRISMA guidelines. Only journal papers were considered eligible that were published within 2018-2020. The results indicated that this topic pertains to different disciplines that favour convergence research at the international level. Furthermore, crop management was observed to be at the centre of attention. A plethora of machine learning algorithms were used, with those belonging to Artificial Neural Networks being more efficient. In addition, maize and wheat as well as cattle and sheep were the most investigated crops and animals, respectively. Finally, a variety of sensors, attached on satellites and unmanned ground and aerial vehicles, have been utilized as a means of getting reliable input data for the data analyses. It is anticipated that this study will constitute a beneficial guide to all stakeholders towards enhancing awareness of the potential advantages of using machine learning in agriculture and contributing to a more systematic research on this topic.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f4ef127a-e7a2-4925-806c-0010d0025b0b', '978e45ab-ccab-499d-93c3-105541378309', 'Optimal Contribution Selection Improves the Rate of Genetic Gain in Grain Yield and Yield Stability in Spring Canola in Australia and Canada', 'Cowling WA, Castro-Urrea FA, Stefanova KT, Li L, Banks RG, Saradadevi R, Sass O, Kinghorn BP', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12020383', 'https://doi.org/10.3390/plants12020383', 'https://europepmc.org/articles/PMC9863350?pdf=render', NULL, NULL, 27, NULL, 'canada', 3, 'cc by', 'Crop breeding must achieve higher rates of genetic gain in grain yield (GY) and yield stability to meet future food demands in a changing climate. Optimal contributions selection (OCS) based on an index of key economic traits should increase the rate of genetic gain while minimising population inbreeding. Here we apply OCS in a global spring oilseed rape (canola) breeding program during three cycles of S0,1 family selection in 2016, 2018, and 2020, with several field trials per cycle in Australia and Canada. Economic weights in the index promoted high GY, seed oil, protein in meal, and Phoma stem canker (blackleg) disease resistance while maintaining plant height, flowering time, oleic acid, and seed size and decreasing glucosinolate content. After factor analytic modelling of the genotype-by-environment interaction for the additive effects, the linear rate of genetic gain in GY across cycles was 0.059 or 0.087 t ha-1 y-1 (2.9% or 4.3% y-1) based on genotype scores for the first factor (f1) expressed in trait units or average predicted breeding values across environments, respectively. Both GY and yield stability, defined as the root-mean-square deviation from the regression line associated with f1, were predicted to improve in the next cycle with a low achieved mean parental coancestry (0.087). These methods achieved rapid genetic gain in GY and other traits and are predicted to improve yield stability across global spring canola environments.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('33a03e13-c9de-40ec-8618-9b932a5588f6', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Bacillus spp. as Bioagents: Uses and Application for Sustainable Agriculture', 'Khan AR, Mustafa A, Hyder S, Valipour M, Rizvi ZF, Gondal AS, Yousuf Z, Iqbal R', 2022, 'Biology', '10.3390/biology11121763', 'https://doi.org/10.3390/biology11121763', 'https://europepmc.org/articles/PMC9775066?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'Food security will be a substantial issue in the near future due to the expeditiously growing global population. The current trend in the agriculture industry entails the extravagant use of synthesized pesticides and fertilizers, making sustainability a difficult challenge. Land degradation, lower production, and vulnerability to both abiotic and biotic stresses are problems caused by the usage of these pesticides and fertilizers. The major goal of sustainable agriculture is to ameliorate productivity and reduce pests and disease prevalence to such a degree that prevents large-scale damage to crops. Agriculture is a composite interrelation among plants, microbes, and soil. Plant microbes play a major role in growth promotion and improve soil fertility as well. Bacillus spp. produces an extensive range of bio-chemicals that assist in plant disease control, promote plant development, and make them suitable for agricultural uses. Bacillus spp. support plant growth by N fixation, P and K solubilization, and phytohormone synthesis, in addition to being the most propitious biocontrol agent. Moreover, Bacilli excrete extracellular metabolites, including antibiotics, lytic enzymes, and siderophores, and demonstrate antagonistic activity against phytopathogens. Bacillus spp. boosts plant resistance toward pathogens by inducing systemic resistance (ISR). The most effective microbial insecticide against insects and pests in agriculture is Bacillus thuringiensis (Bt). Additionally, the incorporation of toxin genes in genetically modified crops increases resistance to insects and pests. There is a constant increase in the identified Bacillus species as potential biocontrol agents. Moreover, they have been involved in the biosynthesis of metallic nanoparticles. The main objective of this review article is to display the uses and application of Bacillus specie as a promising biopesticide in sustainable agriculture. Bacillus spp. strains that are antagonistic and promote plant yield attributes could be valuable in developing novel formulations to lead the way toward sustainable agriculture.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('adbed1fe-4875-4139-9f04-20632114de8b', '978e45ab-ccab-499d-93c3-105541378309', 'Risks to human and animal health related to the presence of deoxynivalenol and its acetylated and modified forms in food and feed', 'Knutsen HK, Alexander J, Barregård L, Bignami M, Brüschweiler B, Ceccatelli S, Cottrill B, Dinovi M', 2017, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2017.4718', 'https://doi.org/10.2903/j.efsa.2017.4718', 'https://europepmc.org/articles/PMC7010102?pdf=render', NULL, NULL, 345, NULL, 'other', 1, 'cc by-nd', 'Deoxynivalenol (DON) is a mycotoxin primarily produced by Fusarium fungi, occurring predominantly in cereal grains. Following the request of the European Commission, the CONTAM Panel assessed the risk to animal and human health related to DON, 3-acetyl-DON (3-Ac-DON), 15-acetyl-DON (15-Ac-DON) and DON-3-glucoside in food and feed. A total of 27,537, 13,892, 7,270 and 2,266 analytical data for DON, 3-Ac-DON, 15-Ac-DON and DON-3-glucoside, respectively, in food, feed and unprocessed grains collected from 2007 to 2014 were used. For human exposure, grains and grain-based products were main sources, whereas in farm and companion animals, cereal grains, cereal by-products and forage maize contributed most. DON is rapidly absorbed, distributed, and excreted. Since 3-Ac-DON and 15-Ac-DON are largely deacetylated and DON-3-glucoside cleaved in the intestines the same toxic effects as DON can be expected. The TDI of 1 μg/kg bw per day, that was established for DON based on reduced body weight gain in mice, was therefore used as a group-TDI for the sum of DON, 3-Ac-DON, 15-Ac-DON and DON-3-glucoside. In order to assess acute human health risk, epidemiological data from mycotoxicoses were assessed and a group-ARfD of 8 μg/kg bw per eating occasion was calculated. Estimates of acute dietary exposures were below this dose and did not raise a health concern in humans. The estimated mean chronic dietary exposure was above the group-TDI in infants, toddlers and other children, and at high exposure also in adolescents and adults, indicating a potential health concern. Based on estimated mean dietary concentrations in ruminants, poultry, rabbits, dogs and cats, most farmed fish species and horses, adverse effects are not expected. At the high dietary concentrations, there is a potential risk for chronic adverse effects in pigs and fish and for acute adverse effects in cats and farmed mink.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f1fad977-102b-4815-8c2e-95679b79c74a', 'ba8025fb-168a-4780-bcd4-711d205283f5', 'Biocontrol Potential of a Novel Endophytic Bacterium From Mulberry (Morus) Tree', 'Xie S, Vallet M, Sun C, Kunert M, David A, Zhang X, Chen B, Lu X', 2019, 'Frontiers in bioengineering and biotechnology', '10.3389/fbioe.2019.00488', 'https://doi.org/10.3389/fbioe.2019.00488', 'https://europepmc.org/articles/PMC6990687?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Mulberry (Morus) is an economically important woody tree that is suitable for use in sericulture as forage and in medicine. However, this broad-leaved tree is facing multiple threats ranging from phytopathogens to insect pests. Here, a Gram-positive, endospore-forming bacterium (ZJU1) was frequently isolated from healthy mulberry plants by screening for foliar endophytes showing antagonism against pathogens and pests. Whole-genome sequencing and annotation resulted in a genome size of 4.06 Mb and classified the bacterium as a novel strain of Bacillus amyloliquefaciens that has rarely been identified from tree leaves. An integrative approach combining traditional natural product chemistry, activity bioassays, and high-resolution mass spectrometry confirmed that strain ZJU1 uses a blend of antimicrobials including peptides and volatile organic compounds to oppose Botrytis cinerea, a major phytopathogenic fungus causing mulberry gray mold disease. We showed that the inoculation of endophyte-free plants with ZJU1 significantly decreased both leaf necrosis and mortality under field conditions. In addition to the direct interactions of endophytes with foliar pathogens, in planta studies suggested that the inoculation of endophytes also induced plant systemic defense, including high expression levels of mulberry disease resistance genes. Moreover, when applied to the generalist herbivore Spodoptera litura, ZJU1 was sufficient to reduce the pest survival rate below 50%. A previously undiscovered crystal toxin (Cry10Aa) could contribute to this insecticidal effect against notorious lepidopteran pests. These unique traits clearly demonstrate that B. amyloliquefaciens ZJU1 is promising for the development of successful strategies for biocontrol applications. The search for new plant-beneficial microbes and engineering microbiomes is therefore of great significance for sustainably improving plant performance.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fa585198-37e2-485e-93e6-a0a74550b1d1', 'ba8025fb-168a-4780-bcd4-711d205283f5', 'Effect of blending Jersey and Holstein-Friesian milk on Cheddar cheese processing, composition, and quality', 'Bland JH, Grandison AS, Fagan CC', 2015, 'Journal of dairy science', '10.3168/jds.2014-8433', 'https://doi.org/10.3168/jds.2014-8433', 'https://europepmc.org/articles/PMC7522615?pdf=render', NULL, NULL, 959, NULL, 'other', 1, 'open access (Europe PMC)', 'The effect of Jersey milk use solely or at different inclusion rates in Holstein-Friesian milk on Cheddar cheese production was investigated. Cheese was produced every month over a year using nonstandardized milk consisting of 0, 25, 50, 75, and 100% Jersey milk in Holstein-Friesian milk in a 100-L vat. Actual, theoretical, and moisture-adjusted yield increased linearly with percentage of Jersey milk. This was also associated with increased fat and protein recoveries and lower yield of whey. The composition of whey was also affected by the percentage of Jersey milk, with lower whey protein and higher whey lactose and solids. Cutting time was lower when Jersey milk was used, but the cutting to milling time was higher because of slower acidity development. Hence, overall cheesemaking time was not affected by the use of Jersey milk. Using Jersey milk increased cheese fat content in autumn, winter, and spring and decreased cheese moisture in spring and summer. Cheese protein, salt, and pH levels were not affected. Cheese was analyzed for texture and color, and it was professionally graded at 3 and 8mo. The effect of Jersey on cheese sensory quality was an increase in cheese yellowness during summer and a higher total grading score at 3mo in winter; no other difference in cheese quality was found. The study indicates that using Jersey milk is a valid method of improving Cheddar cheese yield.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3c95c0da-2db6-4884-8b06-ac048101355a', 'ba8025fb-168a-4780-bcd4-711d205283f5', 'Fine mapping and identification of causal alleles at the Ur-11 locus controlling rust resistance in common bean (Phaseolus vulgaris L.)', 'Erfatpour M, Simons KJ, Roy J, Figueroa-Cerna JC, Lee R, Beaver J, McClean PE, Osorno JM', 2025, 'TAG. Theoretical and applied genetics. Theoretische und angewandte Genetik', '10.1007/s00122-025-04836-9', 'https://doi.org/10.1007/s00122-025-04836-9', 'https://europepmc.org/articles/PMC11850475?pdf=render', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc by', 'The Middle American rust resistance gene Ur-11 present in common bean (Phaseolus vulgaris L.) confers resistance to all but one known race of the pathogen Uromyces appendiculatus (Pers.) Unger. Even though progress has been made in understanding the host-pathogen interactions between common bean and U. appendiculatus, the causal alleles of the majority of rust resistance loci, including Ur-11, remain unknown. A genome-wide association study (GWAS) was conducted to identify genomic regions associated with resistance to the U. appendiculatus race 31-22, which is avirulent to Ur-11 but virulent to other Middle American rust resistance genes. GWAS using genotypic data consisting of approximately 70,959 SNP markers and phenotypic data based on the median reaction type (1-9 scale) of a panel of 357 Middle American breeding lines and cultivars, plus 5 germplasm lines with the Ur-11 locus derived from PI 181996, located Ur-11 on chromosome Pv11. Twenty-seven SNP markers clustered in the 55.16-55.56 Mb region of the P. vulgaris UI111 reference. Multiple DNA sequence alignments detected a missense mutation [c.1,328A > G] in the PvUI111.11G202400 gene model that encodes a leucine-rich repeat-containing protein in response to race 31-22. A PCR allele competitive extension marker (PACE) was developed and tested across a panel of ~ 700 Middle American dry bean genotypes. No recombination event was observed for the PACE marker among the tested genotypes; suggesting that the polymorphism on which it is based is very close to or in the Ur-11 gene. This PACE marker will be a useful and reliable marker for marker-assisted selection of Ur-11-based resistance to bean rust.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9896ec73-f2ba-4627-a66c-ffc66da86c37', 'ba8025fb-168a-4780-bcd4-711d205283f5', 'Genetic Diversity, Nitrogen Fixation, and Water Use Efficiency in a Panel of Honduran Common Bean (Phaseolus vulgaris L.) Landraces and Modern Genotypes', 'Wilker J, Humphries S, Rosas-Sotomayor JC, Cerna MG, Torkamaneh D, Edwards M, Navabi A, Pauls KP', 2020, 'Plants (Basel, Switzerland)', '10.3390/plants9091238', 'https://doi.org/10.3390/plants9091238', 'https://europepmc.org/articles/PMC7569834?pdf=render', NULL, NULL, 42, NULL, 'canada', 3, 'cc by', 'Common bean (Phaseolus vulgaris L.) provides critical nutrition and a livelihood for millions of smallholder farmers worldwide. Beans engage in symbiotic nitrogen fixation (SNF) with Rhizobia. Honduran hillside farmers farm marginal land and utilize few production inputs; therefore, bean varieties with high SNF capacity and environmental resiliency would be of benefit to them. We explored the diversity for SNF, agronomic traits, and water use efficiency (WUE) among 70 Honduran landrace, participatory bred (PPB), and conventionally bred bean varieties (HON panel) and 6 North American check varieties in 3 low-N field trials in Ontario, Canada and Honduras. Genetic diversity was measured with a 6K single nucleotide polymorphism (SNP) array, and phenotyping for agronomic, SNF, and WUE traits was carried out. STRUCTURE analysis revealed two subpopulations with admixture between the subpopulations. Nucleotide diversity was greater in the landraces than the PPB varieties across the genome, and multiple genomic regions were identified where population genetic differentiation between the landraces and PPB varieties was evident. Significant differences were found between varieties and breeding categories for agronomic traits, SNF, and WUE. Landraces had above average SNF capacity, conventional varieties showed higher yields, and PPB varieties performed well for WUE. Varieties with the best SNF capacity could be used in further participatory breeding efforts.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('130e3cf8-2568-4fbd-b4b9-1cd159c0fc92', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Below-ground-above-ground Plant-microbial Interactions: Focusing on Soybean, Rhizobacteria and Mycorrhizal Fungi', 'Igiehon NO, Babalola OO', 2018, 'The open microbiology journal', '10.2174/1874285801812010261', 'https://doi.org/10.2174/1874285801812010261', 'https://europepmc.org/articles/PMC6110075?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'IntroductionOrganisms seldom exist in isolation and are usually involved in interactions with several hosts and these interactions in conjunction with the physicochemical parameters of the soil affect plant growth and development. Researches into below and aboveground microbial community are unveiling a myriad of intriguing interactions within the rhizosphere, and many of the interactions are facilitated by exudates that are secreted by plants roots. These interactions can be harnessed for beneficial use in agriculture to enhance crop productivity especially in semi-arid and arid environments.The rhizosphereThe rhizosphere is the region of soil close to plants roots that contain large number of diverse organisms. Examples of microbial candidates that are found in the rhizosphere include the Arbuscular Mycorrhizal Fungi (AMF) and rhizobacteria. These rhizosphere microorganisms use plant root secretions such as mucilage and flavonoids which are able to influence their diversity and function and also enhance their potential to colonize plants root.Natural interactions between microorganisms and plantIn the natural environments, plants live in interactions with different microorganisms, which thrive belowground in the rhizosphere and aboveground in the phyllosphere. Some of the plant-microbial interactions (which can be in the form of antagonism, amensalism, parasitism and symbiosis) protect the host plants against detrimental microbial and non-microbial invaders and provide nutrients for plants while others negatively affect plants. These interactions can influence below-ground-above-ground plants'' biomass development thereby playing significant role in sustaining plants. Therefore, understanding microbial interactions within the rhizosphere and phyllosphere is urgent towards farming practices that are less dependent on conventional chemical fertilizers, which have known negative impacts on the environments.Below ground rhizobacteria interactions alleviate drought stressDrought stress is one of the major factors militating against agricultural productivity globally and is likely to further increase. Belowground rhizobacteria interactions could play important role in alleviating drought stress in plants. These beneficial rhizobacterial colonize the rhizosphere of plants and impart drought tolerance by up regulation or down regulation of drought responsive genes such as ascorbate peroxidase, S-adenosyl-methionine synthetase, and heat shock protein.Insights into below and above the ground microbial interactions via omic studiesInvestigating complex microbial community in the environment is a big challenge. Therefore, omic studies of microorganisms that inhabit the rhizosphere are important since this is where most plant-microbial interactions occur. One of the aims of this review is not to give detailed account of all the present omic techniques, but instead to highlight the current omic techniques that can possibly lead to detection of novel genes and their respective proteins within the rhizosphere which may be of significance in enhancing crop plants (such as soybean) productivity especially in semi-arid and arid environments.Future prospects and conclusionsPlant-microbial interactions are not totally understood, and there is, therefore, the need for further studies on these interactions in order to get more insights that may be useful in sustainable agricultural development. With the emergence of omic techniques, it is now possible to effectively monitor transformations in rhizosphere microbial community together with their effects on plant development. This may pave way for scientists to discover new microbial species that will interact effectively with plants. Such microbial species can be used as biofertilizers and/or bio-pesticides to increase crop yield and enhance global food security.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('18fc75c1-3433-46ba-b4a0-b05e8ccbf464', 'ba8025fb-168a-4780-bcd4-711d205283f5', 'Public health risks associated with food-borne parasites', 'Koutsoumanis K, Allende A, Alvarez-Ordóñez A, Bolton D, Bover-Cid S, Chemaly M, Davies R, De Cesare A', 2018, 'EFSA journal. European Food Safety Authority', '10.2903/j.efsa.2018.5495', 'https://doi.org/10.2903/j.efsa.2018.5495', 'https://europepmc.org/articles/PMC7009631?pdf=render', NULL, NULL, 113, NULL, 'other', 1, 'cc by-nd', 'Parasites are important food-borne pathogens. Their complex lifecycles, varied transmission routes, and prolonged periods between infection and symptoms mean that the public health burden and relative importance of different transmission routes are often difficult to assess. Furthermore, there are challenges in detection and diagnostics, and variations in reporting. A Europe-focused ranking exercise, using multicriteria decision analysis, identified potentially food-borne parasites of importance, and that are currently not routinely controlled in food. These are Cryptosporidium spp., Toxoplasma gondii and Echinococcus spp. Infection with these parasites in humans and animals, or their occurrence in food, is not notifiable in all Member States. This Opinion reviews current methods for detection, identification and tracing of these parasites in relevant foods, reviews literature on food-borne pathways, examines information on their occurrence and persistence in foods, and investigates possible control measures along the food chain. The differences between these three parasites are substantial, but for all there is a paucity of well-established, standardised, validated methods that can be applied across the range of relevant foods. Furthermore, the prolonged period between infection and clinical symptoms (from several days for Cryptosporidium to years for Echinococcus spp.) means that source attribution studies are very difficult. Nevertheless, our knowledge of the domestic animal lifecycle (involving dogs and livestock) for Echinoccocus granulosus means that this parasite is controllable. For Echinococcus multilocularis, for which the lifecycle involves wildlife (foxes and rodents), control would be expensive and complicated, but could be achieved in targeted areas with sufficient commitment and resources. Quantitative risk assessments have been described for Toxoplasma in meat. However, for T. gondii and Cryptosporidium as faecal contaminants, development of validated detection methods, including survival/infectivity assays and consensus molecular typing protocols, are required for the development of quantitative risk assessments and efficient control measures.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('06762ddf-8bed-48f3-8cdd-31cb9b90b2ef', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'A classification system for describing N-fertilizer performance in dryland wheat crops of the inland Pacific Northwest', 'Casanova JJ, Huggins DR, Phillips CL', 2025, 'Journal of environmental quality', '10.1002/jeq2.70017', 'https://doi.org/10.1002/jeq2.70017', 'https://europepmc.org/articles/PMC12065068?pdf=render', NULL, NULL, 15, NULL, 'northern_plains', 3, 'cc by', 'Wheat (Triticum aestivum L.) crops in the inland Pacific Northwest demand nitrogen (N) fertilizers at high levels to achieve yield and grain protein objectives. Inefficiencies in N use can accelerate soil acidification, contribute to N2O emissions, and result in unnecessary input costs. Reducing N losses is a complicated problem, as producers have to consider grain protein and yield targets, co-limitations of water and other nutrients, longer term soil health goals, and variability in crop performance across fields. However, past work in the region has established that there are at least four prevalent N performance syndromes, each of which have different environmental effects and lend themselves to different actions for adapting N management. In this paper, we build on this work to develop a discrete six-class evaluation system that simplifies assessment of wheat N performance. We use over 20 years of harvest data from the Cook Agronomy Farm Long-Term Agroecosystem Research site to assess spatial and temporal patterns in wheat N performance. While some areas had durable high or low nitrogen performance, there was year-to-year variation due to weather, management, and cultivar-specific factors. For wheat management decisions, the categorical system narrows the range of possible problems, potential environmental effects, and solutions to poor wheat performance.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('86370293-4cf1-4037-b853-eecbcb2e904d', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Advancing crop improvement through GWAS and beyond in mung bean', 'Ahmed SR, Asghar MJ, Hameed A, Ghaffar M, Shahid M', 2024, 'Frontiers in plant science', '10.3389/fpls.2024.1436532', 'https://doi.org/10.3389/fpls.2024.1436532', 'https://europepmc.org/articles/PMC11688477?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'Accessing the underlying genetics of complex traits, especially in small grain pulses is an important breeding objective for crop improvement. Genome-wide association studies (GWAS) analyze thousands of genetic variants across several genomes to identify links with specific traits. This approach has discovered many strong associations between genes and traits, and the number of associated variants is expected to continue to increase as GWAS sample sizes increase. GWAS has a range of applications like understanding the genetic architecture associated with phenotype, estimating genetic correlation and heritability, developing genetic maps based on novel identified quantitative trait loci (QTLs)/genes, and developing hypotheses related to specific traits in the next generation. So far, several causative alleles have been identified using GWAS which had not been previously detected using QTL mapping. GWAS has already been successfully applied in mung bean (Vigna radiata) to identify SNPs/alleles that are used in breeding programs for enhancing yield and improvement against biotic and abiotic factors. In this review, we summarize the recently used advanced genetic tools, the concept of GWAS and its improvement in combination with structural variants, the significance of combining high-throughput phenotyping and genome editing with GWAS, and also highlights the genetic discoveries made with GWAS. Overall, this review explains the significance of GWAS with other advanced tools in the future, concluding with an overview of the current and future applications of GWAS with some recommendations.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('89f19b2c-c420-47dc-8dab-3a27adfb32ec', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Bifidobacterium animalis subsp. lactis Probio-M8 enhances chondroitin efficacy for knee osteoarthritis in postmenopausal women via the gut-joint axis', 'Wang K, Wang H, Zhao Z, Shen X, Zhao J, Zhang H', 2025, 'mSystems', '10.1128/msystems.00862-25', 'https://doi.org/10.1128/msystems.00862-25', 'https://europepmc.org/articles/PMC12710372?pdf=render', NULL, NULL, 18, NULL, 'canada', 3, 'cc by', 'Knee osteoarthritis (KOA) is a chronic joint disease marked by cartilage degradation and inflammation. Probiotics exhibit anti-inflammatory properties and may influence the gut-joint axis. Thus, a 4-month human trial was conducted to assess the adjunctive effects of Bifidobacterium animalis subsp. lactis Probio-M8 on KOA in postmenopausal women. Sixty-five KOA patients were randomly allocated to the probiotic group (n = 37; Probio-M8 and chondroitin sulfate) or placebo group (n = 28; placebo and chondroitin sulfate). Following a 3-month intervention, participants from both groups entered a 1-month observation without probiotic supplementation. Our findings revealed that Probio-M8 co-administration significantly reduced Western Ontario and McMaster Universities Osteoarthritis Index (WOMAC) scores at months 1, 3, and 4 compared to the placebo group (P P Agathobaculum butyriciproducens, Bacteroides stercoris, B. animalis, Roseburia hominis, and Ruminococcus bromii, while Dorea formicigenerans decreased (P B. animalis were strongly associated with WOMAC scores. The gut metabolic potential analysis showed elevated levels of N-oleoylethanolamine and decreased levels of cholesterol and hypoxanthine in probiotic receivers (P P ImportanceThe pathogenesis of knee osteoarthritis (KOA) and its phenotypic expression have been associated with the human gut microbiota. Our study demonstrated that the co-administration of Probio-M8 with chondroitin sulfate significantly alleviates KOA symptoms. This probiotic intervention enhances therapeutic efficacy through modulation of the gut microbiota and associated metabolic pathways, reducing inflammation and improving clinical outcomes. Our results underscore the potential of probiotic-driven therapies as an adjunctive treatment strategy and underscore the importance of the gut-joint axis in KOA management.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e4ad033f-6e55-48e4-8a99-56702e14fbc7', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Cover crop mixture diversity and function', 'A. M. Florence', 2016, 'Lincoln (University of Nebraska)', NULL, 'https://digitalcommons.unl.edu/agronhortdiss/100', 'https://digitalcommons.unl.edu/context/agronhortdiss/article/1105/viewcontent/COMPLIANT_unl_agronhortdiss_1105.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f78cccb-164e-44bd-9cf5-a8de9449f6a7', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Conventional and Molecular Breeding Tools for Accelerating Genetic Gain in Faba Bean (Vicia Faba L.)', 'Adhikari KN, Khazaei H, Ghaouti L, Maalouf F, Vandenberg A, Link W, O''Sullivan DM', 2021, 'Frontiers in plant science', '10.3389/fpls.2021.744259', 'https://doi.org/10.3389/fpls.2021.744259', 'https://europepmc.org/articles/PMC8548637?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Faba bean is a cool-season grain legume crop, which is grown worldwide for food and feed. Despite a decrease in area under faba bean in the past, the interest in growing faba bean is increasing globally due to its high seed protein content and its excellent ecological service. The crop is, however, exposed to diverse biotic and abiotic stresses causing unstable, low grain yield. Although, sources of resistance to main diseases, such as ascochyta blight (Ascochyta fabae Speg.), rust (Uromyces viciae-fabae (Pers.) Schroet.), chocolate spot (Botrytis fabae Sard.) and gall disease (Physioderma viciae), have been identified, their resistance is only partial and cannot prevent grain yield losses without agronomical practices. Tightly associated DNA markers for host plant resistance genes are needed to enhance the level of resistance. Less progress has been made for abiotic stresses. Different breeding methods are proposed, but until now line breeding, based on the pedigree method, is the dominant practice in breeding programs. Nonetheless, the low seed multiplication coefficient and the requirement for growing under insect-proof enclosures to avoid outcrossing hampers breeding, along with the lack of tools such as double haploid system and cytoplasmic male sterility. This reduces breeding population size and speed of breeding hence the chances of capturing rare combinations of favorable alleles. Availability and use of the DNA markers such as vicine-convicine (vc -) and herbicide tolerance in breeding programs have encouraged breeders and given confidence in marker assisted selection. Closely linked QTL for several biotic and abiotic stress tolerance are available and their verification and conversion in breeder friendly platform will enhance the selection process. Recently, genomic selection and speed breeding techniques together with genomics have come within reach to accelerate the genetic gains in faba bean. Advancements in genomic resources with other breeding tools, methods and platforms will enable to accelerate the breeding process for enhancing genetic gain in this species.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('710f6f85-3284-4b09-b3ed-f6264be25e82', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Drone-Based Digital Phenotyping to Evaluating Relative Maturity, Stand Count, and Plant Height in Dry Beans (Phaseolus vulgaris L.)', 'Volpato L, Wright EM, Gomez FE', 2024, 'Plant phenomics (Washington, D.C.)', '10.34133/plantphenomics.0278', 'https://doi.org/10.34133/plantphenomics.0278', 'https://europepmc.org/articles/PMC11602537?pdf=render', NULL, NULL, 22, NULL, 'northern_plains', 3, 'cc by', 'Substantial effort has been made in manually tracking plant maturity and to measure early-stage plant density and crop height in experimental fields. In this study, RGB drone imagery and deep learning (DL) approaches are explored to measure relative maturity (RM), stand count (SC), and plant height (PH), potentially offering higher throughput, accuracy, and cost-effectiveness than traditional methods. A time series of drone images was utilized to estimate dry bean RM employing a hybrid convolutional neural network (CNN) and long short-term memory (LSTM) model. For early-stage SC assessment, Faster RCNN object detection algorithm was evaluated. Flight frequencies, image resolution, and data augmentation techniques were investigated to enhance DL model performance. PH was obtained using a quantile method from digital surface model (DSM) and point cloud (PC) data sources. The CNN-LSTM model showed high accuracy in RM prediction across various conditions, outperforming traditional image preprocessing approaches. The inclusion of growing degree days (GDD) data improved the model''s performance under specific environmental stresses. The Faster R-CNN model effectively identified early-stage bean plants, demonstrating superior accuracy over traditional methods and consistency across different flight altitudes. For PH estimation, moderate correlations with ground-truth data were observed across both datasets analyzed. The choice between PC and DSM source data may depend on specific environmental and flight conditions. Overall, the CNN-LSTM and Faster R-CNN models proved more effective than conventional techniques in quantifying RM and SC. The subtraction method proposed for estimating PH without accurate ground elevation data yielded results comparable to the difference-based method. Additionally, the pipeline and open-source software developed hold potential to significantly benefit the phenotyping community.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('623e0111-2e96-4518-811d-7c5025a1f95e', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Feeding Value of Lupins, Field Peas, Faba Beans and Chickpeas for Poultry: An Overview', 'David LS, Nalle CL, Abdollahi MR, Ravindran V', 2024, 'Animals : an open access journal from MDPI', '10.3390/ani14040619', 'https://doi.org/10.3390/ani14040619', 'https://europepmc.org/articles/PMC10886283?pdf=render', NULL, NULL, 40, NULL, 'other', 1, 'cc by', 'Grain legumes are fair sources of protein, amino acids and energy, and can be used as a replacement for soybean meal in poultry feed formulations as the soybean meal becomes short in supply and costly. However, a concern associated with the use of grain legumes in poultry feeding is the presence of antinutritional factors. The effective processing and utilisation of these grain legumes in poultry feeding are well documented. The current review focuses on four selected grain legumes (lupins [Lupinus albus and Lupinus angustifolius], field peas [Phaseolus vulgaris], faba beans [Vicia faba] and chickpeas [Cicer arietinum]) and their nutrient content, the presence of antinutritional factors, processing methods and feeding value, including updated data based on recent research findings.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('321984de-1846-4d55-83ee-a69b9ab0ea41', '3695a745-ddaf-4ab2-b648-9cf1de5d783b', 'Harnessing Transient Expression Systems with Plant Viral Vectors for the Production of Biopharmaceuticals in Nicotiana benthamiana', 'Akher SA, Wang KY, Hall K, Hunpatin OS, Shan M, Zhang Z, Guo Y', 2025, 'International journal of molecular sciences', '10.3390/ijms26125510', 'https://doi.org/10.3390/ijms26125510', 'https://europepmc.org/articles/PMC12193647?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Plant Molecular Farming (PMF) capitalizes on the unique properties of plants as bioreactors to efficiently produce valuable proteins, pharmaceuticals, and enzymes. This review emphasizes the critical role of transient expression systems, particularly in Nicotiana benthamiana, due to its susceptibility to various pathogens. Viral vector-based transient expression has proven essential during health emergencies like COVID-19, enabling rapid recombinant protein production. The review also evaluates different transient expression platforms and highlights their applications in biopharmaceutical production, education, synthetic biology, and gene editing. Advances in viral vector modification, hydroponics, and Controlled Environment Agriculture (CEA) are presented as transformative innovations enhancing scalability and regulatory compliance. Furthermore, glycoengineering advancements broaden the range of producible biopharmaceuticals, improving global medication access. By exploring these advancements, this review underscores the vast potential of transient expression systems to meet dynamic scientific and market demands, positioning PMF as a vital component in modern biotechnology.', '{epmc,variety}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.604988+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b31ef72-8b15-448e-a386-4650149a1681', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Bemisia tabaci on Vegetables in the Southern United States: Incidence, Impact, and Management', 'Li Y, Mbata GN, Punnuri S, Simmons AM, Shapiro-Ilan DI', 2021, 'Insects', '10.3390/insects12030198', 'https://doi.org/10.3390/insects12030198', 'https://europepmc.org/articles/PMC7996905?pdf=render', NULL, NULL, 29, NULL, 'other', 1, 'cc by', 'Bemisia tabaci Gennadius (Hemiptera: Aleyrodidae) is among the most economically important insect pests of various vegetable crops in the Southern United States. This insect is considered a complex of at least 40 morphologically indistinguishable cryptic species. Bemisia tabaci Middle East-Asia Minor 1 (MEAM1) was initially introduced in the United States around 1985 and has since rapidly spread across the Southern United States to Texas, Arizona, and California, where extreme field outbreaks have occurred on vegetable and other crops. This pest creates extensive plant damage through direct feeding on vegetables, secreting honeydew, causing plant physiological disorders, and vectoring plant viruses. The direct and indirect plant damage in vegetable crops has resulted in enormous economic losses in the Southern United States, especially in Florida, Georgia, and Texas. Effective management of B. tabaci on vegetables relies mainly on the utilization of chemical insecticides, particularly neonicotinoids. However, B. tabaci has developed considerable resistance to most insecticides. Therefore, alternative integrated pest management (IPM) strategies are required, such as cultural control by manipulation of production practices, resistant vegetable varieties, and biological control using a suite of natural enemies for the management of the pest.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b9600c01-5cef-4ca5-bfab-151d8a2669f7', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Beyond a reference genome: pangenomes and population genomics of underutilized and orphan crops for future food and nutrition security', 'Chapman MA, He Y, Zhou M', 2022, 'The New phytologist', '10.1111/nph.18021', 'https://doi.org/10.1111/nph.18021', 'https://europepmc.org/articles/PMC9994440?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Underutilized crops are, by definition, under-researched compared to staple crops yet come with traits that may be especially important given climate change and the need to feed a globally increasing population. These crops are often stress-tolerant, and this combined with unique and beneficial nutritional profiles. Whilst progress is being made by generating reference genome sequences, in this Tansley Review, we show how this is only the very first step. We advocate that going ''beyond a reference genome'' should be a priority, as it is only at this stage one can identify the specific genes and the adaptive alleles that underpin the valuable traits. We sum up how population genomic and pangenomic approaches have led to the identification of stress- and disease-tolerant alleles in staple crops and compare this to the small number of examples from underutilized crops. We also demonstrate how previously underutilized crops have benefitted from genomic advances and that many breeding targets in underutilized crops are often well studied in staple crops. This cross-crop population-level resequencing could lead to an understanding of the genetic basis of adaptive traits in underutilized crops. This level of investment may be crucial for fully understanding the value of these crops before they are lost.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5579fad9-9e51-444e-8b3b-747f3ec7b63f', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Buckwheat (Fagopyrum esculentum): its impact on wireworm development and survival', 'Christine Noronha, Suqi Liu, Md Habibullah Bahar, Natasha Mosher-Gallant', 2023, 'Arthropod-Plant Interactions', '10.1007/s11829-023-09982-9', 'https://doi.org/10.1007/s11829-023-09982-9', 'https://open-science.canada.ca/server/api/core/bitstreams/9eae8dba-1609-4e78-9c42-9b2bdb4fd098/content', NULL, NULL, 12, NULL, 'canada', 3, 'cc-by', 'Abstract Buckwheat (Fagopyrum esculentum) is a member of the Polygonaceae family, cultivated as a cover crop to suppress or reduce weeds and improve soil health. In our field studies, buckwheat gave significant potato tuber protection from wireworm damage after two consecutive years of cropping. In this study, we identified the mechanism underlying the beneficial effect of buckwheat on wireworm suppression. Results show high wireworm numbers in buckwheat than other host plants in bioassays conducted under greenhouse and field conditions which reject the hypothesis that buckwheat has antifeedant activity. We found that newly hatched neonate wireworms feeding on either barley or buckwheat plants for 120 days, showed reduced body weight and head capsule size. The larvae feeding on buckwheat were 60% and 30% smaller than the ones feeding on barley. Survival was also impacted with 44% of the neonate larvae surviving on barley plants, and only 15% when feeding on buckwheat roots over 120 days. A similar bioassay with small to medium-sized wireworms showed higher mortality, lower weight gain and smaller head capsule size. Wireworms feeding on buckwheat were deformed and demonstrated irregular growth. In conclusion, this study revealed that buckwheat did not repel wireworms and they chose to feed on the roots despite it not being a good host. Long-term feeding on buckwheat roots caused reduced weight gain, abnormal growth, and reduced survival. This study provided a better understanding of how buckwheat functions as a biopesticide for wireworm control and its potential for use in an IPM program.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b472b5a-3eb3-4322-8b95-f227df21e9ec', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Canadian buckwheat: A unique, useful and under-utilized crop', 'Marta S. Izydorczyk, Tricia McMillan, Sharon Bazin, Jerry Kletke, L.G. Dushnicky, James Dexter', 2013, 'Canadian Journal of Plant Science', '10.4141/cjps2013-075', 'https://doi.org/10.4141/cjps2013-075', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps2013-075', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('cef6667f-c970-403f-b274-3a01521de893', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Challenges and Opportunities of Light-Emitting Diode (LED) as Key to Modulate Antioxidant Compounds in Plants. A Review', 'Loi M, Villani A, Paciolla F, Mulè G, Paciolla C', 2020, 'Antioxidants (Basel, Switzerland)', '10.3390/antiox10010042', 'https://doi.org/10.3390/antiox10010042', 'https://europepmc.org/articles/PMC7824119?pdf=render', NULL, NULL, 35, NULL, 'other', 1, 'cc by', 'Plant antioxidants are important compounds involved in plant defense, signaling, growth, and development. The quantity and quality of such compounds is genetically driven; nonetheless, light is one of the factors that strongly influence their synthesis and accumulation in plant tissues. Indeed, light quality affects the fitness of the plant, modulating its antioxidative profile, a key element to counteract the biotic and abiotic stresses. With this regard, light-emitting diodes (LEDs) are emerging as a powerful technology which allows the selection of specific wavelengths and intensities, and therefore the targeted accumulation of plant antioxidant compounds. Despite the unique advantages of such technology, LED application in the horticultural field is still at its early days and several aspects still need to be investigated. This review focused on the most recent outcomes of LED application to modulate the antioxidant compounds of plants, with particular regard to vitamin C, phenols, chlorophyll, carotenoids, and glucosinolates. Additionally, future challenges and opportunities in the use of LED technology in the growth and postharvest storage of fruits and vegetables were also addressed to give a comprehensive overview of the future applications and trends of research.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0f467a13-81fa-4eac-b42a-045e0efad158', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Characterization of Selenium Accumulation, Localization and Speciation in Buckwheat–Implications for Biofortification', 'Ying Jiang, Ali F. El Mehdawi, Tripti Tripti, Leonardo Warzea Lima, Gavin C. Stonehouse, Sirine C. Fakra, Yuegao Hu, Hua Qi', 2018, 'Frontiers in Plant Science', '10.3389/fpls.2018.01583', 'https://doi.org/10.3389/fpls.2018.01583', 'https://www.frontiersin.org/articles/10.3389/fpls.2018.01583/pdf', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc-by', 'Buckwheat is an important crop species in areas of selenium (Se) deficiency. To obtain better insight into their Se metabolic properties, common buckwheat (Fagopyrum esculentum) and tartary buckwheat (F. tataricum) were supplied with different concentrations of Se, supplied as selenate, selenite, or Astragalus bisulcatus plant extract (methyl-selenocysteine). Se was supplied at different developmental stages, with different durations, and in the presence or absence of potentially competing ions, sulfate and phosphate. The plants were analyzed for growth, Se uptake, translocation, accumulation, as well as for Se localization and chemical speciation in the seed. Plants of both buckwheat species were supplied with 20 μM of either of the three forms of Se twice over their growth period. Both species accumulated 15-40 mg Se kg-1 DW in seeds, leaves and stems, from all three selenocompounds. X-ray microprobe analysis showed that the Se in seeds was localized in the embryo, in organic C-Se-C form(s) resembling selenomethionine, methyl-selenocysteine and -glutamyl-methylselenocysteine standards. In short-term (2h and 24h) Se uptake studies, both buckwheat species showed higher Se uptake rate and shoot Se accumulation when supplied with plant extract (methyl-selenocysteine), compared to selenite or selenate. In long-term (7d) uptake studies, both species were resistant to selenite up to 50 μM. Tartary buckwheat was also resistant to selenate up to 75 μM Se, but >30 μM selenate inhibited common buckwheat growth. Selenium accumulation was similar in both species. When selenite was supplied, Se levels were 10-20-fold higher in root (up to 900 mg Se kg-1 DW) than shoot, but 4-fold higher in shoot (up to 1,200 mg Se kg-1 DW) than root for selenate-supplied plants. Additionally, sulfate and phosphate supply affected Se uptake, and conversely selenate enhanced S and P accumulation in both species. These findings have relevance for crop Se biofortification applications.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf9e5030-aea9-4062-bf7c-9e5d2bba28d1', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Citric Acid-Mediated Abiotic Stress Tolerance in Plants', 'Tahjib-Ul-Arif M, Zahan MI, Karim MM, Imran S, Hunter CT, Islam MS, Mia MA, Hannan MA', 2021, 'International journal of molecular sciences', '10.3390/ijms22137235', 'https://doi.org/10.3390/ijms22137235', 'https://europepmc.org/articles/PMC8268203?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Several recent studies have shown that citric acid/citrate (CA) can confer abiotic stress tolerance to plants. Exogenous CA application leads to improved growth and yield in crop plants under various abiotic stress conditions. Improved physiological outcomes are associated with higher photosynthetic rates, reduced reactive oxygen species, and better osmoregulation. Application of CA also induces antioxidant defense systems, promotes increased chlorophyll content, and affects secondary metabolism to limit plant growth restrictions under stress. In particular, CA has a major impact on relieving heavy metal stress by promoting precipitation, chelation, and sequestration of metal ions. This review summarizes the mechanisms that mediate CA-regulated changes in plants, primarily CA''s involvement in the control of physiological and molecular processes in plants under abiotic stress conditions. We also review genetic engineering strategies for CA-mediated abiotic stress tolerance. Finally, we propose a model to explain how CA''s position in complex metabolic networks involving the biosynthesis of phytohormones, amino acids, signaling molecules, and other secondary metabolites could explain some of its abiotic stress-ameliorating properties. This review summarizes our current understanding of CA-mediated abiotic stress tolerance and highlights areas where additional research is needed.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0fb8b02d-d5c2-48ac-a029-63285fccdbc3', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Common buckwheat', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2551720', 'https://open.alberta.ca/dataset/3907417b-ab00-471c-97a1-b4325ca1a0bd/resource/024dd01c-81ae-48de-9cd8-e172a2cf996f/download/2001-118-20-2.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Common buckwheat (Fagopyrum esculentum) is thought to have originated in central and western China from a wild Asian species Fagropyrum cymosum. It has been cultivated in China for over 1,000 years, and was brought to Europe during the Middle Ages. Buckwheat, as well as other grain species, accompanied the colonists to the New World. The Scots coined the word ìbuckwheatî from two AngloSaxon terms, boc(beech) and whoet(wheat). The word beech was used since the fruit of the plant was similar to that of beechnut. It was called wheat because the grain of buckwheat was used in the same way as wheat. This term is somewhat ironic since buckwheat does not belong to the grass family and is not considered a "true" cereal.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b203a914-976f-413b-95f0-bbabc2479c40', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Companion Plants for Aphid Pest Management', 'Ben-Issa R, Gomez L, Gautier H', 2017, 'Insects', '10.3390/insects8040112', 'https://doi.org/10.3390/insects8040112', 'https://europepmc.org/articles/PMC5746795?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'A potential strategy for controlling pests is through the use of "companion plants" within a crop system. This strategy has been used in several trials to fight against a major crop insect pest: the aphid. We reviewed the literature to highlight the major mechanisms by which a companion plant may act. Trials carried out under laboratory or field conditions revealed that companion plants operate through several mechanisms. A companion plant may be associated with a target crop for various reasons. Firstly, it can attract aphids and draw them away from their host plants. Secondly, it can alter the recognition of the host plant. This effect is mostly attributed to companion plant volatiles since they disturb the aphid host plant location, and additionally they may react chemically and physiologically with the host plant, making it an unsuitable host for aphids. Thirdly, it can attract natural enemies by providing shelter and food resources. In this review, the feasibility of using companion plants is discussed. We conclude that many factors need to be taken into account for a successful companion plant strategy. For the best long-term results, companion plant strategies have to be combined with other alternative approaches against aphids.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c25b172e-9eaa-4d7a-abeb-14bf77d33a88', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Contribution of insect pollinators to crop yield and quality varies with agricultural intensification', 'Bartomeus I, Potts SG, Steffan-Dewenter I, Vaissière BE, Woyciechowski M, Krewenka KM, Tscheulin T, Roberts SP', 2014, 'PeerJ', '10.7717/peerj.328', 'https://doi.org/10.7717/peerj.328', 'https://europepmc.org/articles/PMC3976118?pdf=render', NULL, NULL, 20, NULL, 'other', 1, 'cc by', 'Background. Up to 75% of crop species benefit at least to some degree from animal pollination for fruit or seed set and yield. However, basic information on the level of pollinator dependence and pollinator contribution to yield is lacking for many crops. Even less is known about how insect pollination affects crop quality. Given that habitat loss and agricultural intensification are known to decrease pollinator richness and abundance, there is a need to assess the consequences for different components of crop production. Methods. We used pollination exclusion on flowers or inflorescences on a whole plant basis to assess the contribution of insect pollination to crop yield and quality in four flowering crops (spring oilseed rape, field bean, strawberry, and buckwheat) located in four regions of Europe. For each crop, we recorded abundance and species richness of flower visiting insects in ten fields located along a gradient from simple to heterogeneous landscapes. Results. Insect pollination enhanced average crop yield between 18 and 71% depending on the crop. Yield quality was also enhanced in most crops. For instance, oilseed rape had higher oil and lower chlorophyll contents when adequately pollinated, the proportion of empty seeds decreased in buckwheat, and strawberries'' commercial grade improved; however, we did not find higher nitrogen content in open pollinated field beans. Complex landscapes had a higher overall species richness of wild pollinators across crops, but visitation rates were only higher in complex landscapes for some crops. On the contrary, the overall yield was consistently enhanced by higher visitation rates, but not by higher pollinator richness. Discussion. For the four crops in this study, there is clear benefit delivered by pollinators on yield quantity and/or quality, but it is not maximized under current agricultural intensification. Honeybees, the most abundant pollinator, might partially compensate the loss of wild pollinators in some areas, but our results suggest the need of landscape-scale actions to enhance wild pollinator populations.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a1c4655a-39ad-4b3e-981a-d59fd8e280f7', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Cover crop mixture diversity, biomass productivity, weed suppression, and stability', 'A. M. Florence, Leon George Higley, Rhae A. Drijber, Clive Francis, John L. Lindquist', 2019, 'PLoS ONE', '10.1371/journal.pone.0206195', 'https://doi.org/10.1371/journal.pone.0206195', 'https://journals.plos.org/plosone/article/file?id=10.1371/journal.pone.0206195&type=printable', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc-by', 'The diversity-productivity, diversity-invasibility, and diversity-stability hypotheses propose that increasing species diversity should lead, respectively, to increased average biomass productivity, invasion resistance, and stability. We tested these three hypotheses in the context of cover crop mixtures, evaluating the effects of increasing cover crop mixture diversity on aboveground biomass, weed suppression, and biomass stability. Twenty to forty cover crop treatments were replicated three or four times at eleven sites using eighteen species representing three cover crop species each from six pre-defined functional groups: cool-season grasses, cool-season legumes, cool-season brassicas, warm-season grasses, warm-season legumes, and warm-season broadleaves. Each species was seeded as a pure stand, and the most diverse treatment contained all eighteen species. Remaining treatments included treatments representing intermediate levels of cover crop species and functional richness and a no cover crop control. Cover crop seeding dates ranged from late July to late September with both cover crop and weed aboveground biomass being sampled prior to winterkill. Stability was assessed by evaluating the variability in cover crop biomass for each treatment across plots within each site. While increasing cover crop mixture diversity was associated with increased average aboveground biomass, we assert that this was the result of the average biomass of the pure stands being drawn down by low biomass species rather than due to niche complementarity or increased resource use efficiency. At no site did the highest biomass mixture produce more than the highest biomass pure stand. Furthermore, while increases in cover crop mixture diversity were correlated with increases in weed suppression and biomass stability, we argue that this was largely the result of diversity co-varying with aboveground biomass, and that differences in aboveground biomass rather than differences in diversity drove the differences observed in weed suppression and stability.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ee84df37-69b5-4960-83f6-babca06d7038', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Defensive Mechanisms of Mikania micrantha Likely Enhance Its Invasiveness as One of the World''s Worst Alien Species', 'Clements DR, Kato-Noguchi H', 2025, 'Plants (Basel, Switzerland)', '10.3390/plants14020269', 'https://doi.org/10.3390/plants14020269', 'https://europepmc.org/articles/PMC11768483?pdf=render', NULL, NULL, 21, NULL, 'canada', 3, 'cc by', 'Mikania micrantha Kunth is native to tropical America and has invaded tropical and subtropical Asia and numerous Pacific Islands. It forms dense thickets and reduces native species diversity and populations in its introduced range. This invasive vine also seriously impacts many agricultural crops and is listed as one of the world''s 100 worst invasive alien species. Its life history characteristics, such as the production of large numbers of wind-dispersed seeds, vegetative reproduction, rapid growth, and genetic diversity all contribute to its invasiveness. In this review, we focus on how mechanisms to defend against its natural enemies boost the invasiveness of M. micrantha. It possesses potent defenses against natural enemies such as pathogenic fungi, herbivorous insects, and parasitic nematodes, and exhibits allelopathic potential against plant competitors. These defensive abilities, in concert with its formidable life history characteristics, contribute to the invasiveness of M. micrantha, potentially leading to further naturalization. Several other reviews have summarized the biology and management of the species, but ours is the first review to focus on how the defensive mechanisms of M. micrantha likely enhance its invasiveness. Relatively little is known about the array of defensive capabilities of M. micrantha; therefore, there is considerable scope for further research on its chemical defenses.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b9c21c2d-15b5-4ccd-9f4e-47b2b1110d4f', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Disease Pandemics and Major Epidemics Arising from New Encounters between Indigenous Viruses and Introduced Crops', 'Jones RAC', 2020, 'Viruses', '10.3390/v12121388', 'https://doi.org/10.3390/v12121388', 'https://europepmc.org/articles/PMC7761969?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Virus disease pandemics and epidemics that occur in the world''s staple food crops pose a major threat to global food security, especially in developing countries with tropical or subtropical climates. Moreover, this threat is escalating rapidly due to increasing difficulties in controlling virus diseases as climate change accelerates and the need to feed the burgeoning global population escalates. One of the main causes of these pandemics and epidemics is the introduction to a new continent of food crops domesticated elsewhere, and their subsequent invasion by damaging virus diseases they never encountered before. This review focusses on providing historical and up-to-date information about pandemics and major epidemics initiated by spillover of indigenous viruses from infected alternative hosts into introduced crops. This spillover requires new encounters at the managed and natural vegetation interface. The principal virus disease pandemic examples described are two (cassava mosaic, cassava brown streak) that threaten food security in sub-Saharan Africa (SSA), and one (tomato yellow leaf curl) doing so globally. A further example describes a virus disease pandemic threatening a major plantation crop producing a vital food export for West Africa (cacao swollen shoot). Also described are two examples of major virus disease epidemics that threaten SSA''s food security (rice yellow mottle, groundnut rosette). In addition, brief accounts are provided of two major maize virus disease epidemics (maize streak in SSA, maize rough dwarf in Mediterranean and Middle Eastern regions), a major rice disease epidemic (rice hoja blanca in the Americas), and damaging tomato tospovirus and begomovirus disease epidemics of tomato that impair food security in different world regions. For each pandemic or major epidemic, the factors involved in driving its initial emergence, and its subsequent increase in importance and geographical distribution, are explained. Finally, clarification is provided over what needs to be done globally to achieve effective management of severe virus disease pandemics and epidemics initiated by spillover events.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('44574334-75bd-407e-b1c2-a16004e7f7cd', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Does Cover Crop Management Affect Arthropods in the Subsequent Corn and Soybean Crops in the United States? A Systematic Review', 'Gabriela Inveninato Carmona, Leslie M. Delserone, Julia Nogueira Duarte Campos, Tauana Ferreira de Almeida, Dânia Vieira Branco Ozório, Juan Betancurt Cardona, Robert Wright, Anthony Justin McMechan', 2020, 'Annals of the Entomological Society of America', '10.1093/aesa/saaa049', 'https://doi.org/10.1093/aesa/saaa049', 'https://academic.oup.com/aesa/article-pdf/114/2/151/36579772/saaa049.pdf', NULL, NULL, NULL, NULL, 'northern_plains', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf238db9-d9c1-455e-8372-95b331846614', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Drought stress enhances nutritional and bioactive compounds, phenolic acids and antioxidant capacity of Amaranthus leafy vegetable', 'Sarker U, Oba S', 2018, 'BMC plant biology', '10.1186/s12870-018-1484-1', 'https://doi.org/10.1186/s12870-018-1484-1', 'https://europepmc.org/articles/PMC6203965?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'BackgroundBioactive compounds, vitamins, phenolic acids, flavonoids of A. tricolor are the sources of natural antioxidant that had a great importance for the food industry as these detoxify ROS in the human body. These natural antioxidants protect human from many diseases such as cancer, arthritis, emphysema, retinopathy, neuro-degenerative cardiovascular diseases, atherosclerosis and cataracts. Moreover, previous literature has shown that drought stress elevated bioactive compounds, vitamins, phenolics, flavonoids and antioxidant activity in many leafy vegetables. Hence, we study the nutritional and bioactive compounds, phenolic acids, flavonoids and antioxidant capacity of amaranth under drought stress for evaluation of the significant contribution of these compounds in the human diet.ResultsThe genotype VA3 was assessed at four drought stress levels that significantly affected nutritional and bioactive compounds, phenolic acids, flavonoids and antioxidant capacity. Protein, ash, energy, dietary fiber, Ca, K, Cu, S, Mg, Mn, Mo, Na, B content, total carotenoids, TFC, vitamin C, TPC, TAC (DPPH), betacarotene, TAC (ABTS+), sixteen phenolic acids and flavonoids were remarkably increased with the severity of drought stress. At moderate and severe drought stress conditions, the increments of all these components were more preponderant. Trans-cinnamic acid was newly identified phenolic acid in A. tricolor. Salicylic acid, vanilic acid, gallic acid, chlorogenic acid, Trans-cinnamic acid, rutin, isoquercetin, m-coumaric acid and p-hydroxybenzoic acid were the most abundant phenolic compounds in this genotype.ConclusionsIn A. tricolor, drought stress enhanced the quantitative and qualitative improvement of nutritional and bioactive compounds, phenolic acids, flavonoids and antioxidants. Hence, farmers of semi-arid and dry areas of the world could be able to grow amaranth as a substitute crop.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2cb6a060-fca3-4c63-8b91-7570a66236a7', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Enhancing Biological Control Efficacy: Insights into the Feeding Behavior and Fitness of the Omnivorous Pest Lygus lineolaris', 'Solà Cassi M, Dumont F, Provost C, Lucas E', 2024, 'Insects', '10.3390/insects15090665', 'https://doi.org/10.3390/insects15090665', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC11431852.1/PMC11431852.1.pdf', NULL, NULL, 13, NULL, 'canada', 3, 'cc by', 'Lygus lineolaris (Palisot de Beauvois) (Hemiptera: Miridae), a true omnivorous insect, poses a significant threat to agriculture in the Neartic region. Understanding the feeding behavior of L. lineolaris is crucial for developing integrated pest management strategies. This study aimed to evaluate the effects of different diets on the fitness of L. lineolaris, with a focus on the diet source, feeding regime (phytophagy, zoophagy, and phytozoophagy), and number of diet items. The experimental design in the laboratory investigated the impacts of strawberry, canola and buckwheat flowers, as well as spider mites and aphids to explore relationships found in a conventional strawberry field. Results reveal that diet source, feeding regime, and the number of diet items influence L. lineolaris performance (i.e., survivorship rate, developmental time, and adult weight and length). Improvements in fitness are indicated by higher nymphal survival, shorter developmental time, and larger adults. Immature stages of L. lineolaris show improved fitness when provided with diets rich in canola compared to strawberry flowers and spider mites. Furthermore, the inclusion of multiple diet items in phytozoophagous regimes enhances insect performance. The findings emphasize the significance of understanding L. lineolaris'' nutritional requirements and the biodiversity of target ecosystems for modeling energy flows and designing effective IPM strategies against this pest. This research contributes to the knowledge base for biological control programs targeting L. lineolaris in agricultural systems.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d8066acb-cd95-4688-8aeb-8368238f1ac8', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Enhancing Salt Tolerance of Plants: From Metabolic Reprogramming to Exogenous Chemical Treatments and Molecular Approaches', 'Patel MK, Kumar M, Li W, Luo Y, Burritt DJ, Alkan N, Tran LP', 2020, 'Cells', '10.3390/cells9112492', 'https://doi.org/10.3390/cells9112492', 'https://europepmc.org/articles/PMC7697626?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Plants grow on soils that not only provide support for root anchorage but also act as a reservoir of water and nutrients important for plant growth and development. However, environmental factors, such as high salinity, hinder the uptake of nutrients and water from the soil and reduce the quality and productivity of plants. Under high salinity, plants attempt to maintain cellular homeostasis through the production of numerous stress-associated endogenous metabolites that can help mitigate the stress. Both primary and secondary metabolites can significantly contribute to survival and the maintenance of growth and development of plants on saline soils. Existing studies have suggested that seed/plant-priming with exogenous metabolites is a promising approach to increase crop tolerance to salt stress without manipulation of the genome. Recent advancements have also been made in genetic engineering of various metabolic genes involved in regulation of plant responses and protection of the cells during salinity, which have therefore resulted in many more basic and applied studies in both model and crop plants. In this review, we discuss the recent findings of metabolic reprogramming, exogenous treatments with metabolites and genetic engineering of metabolic genes for the improvement of plant salt tolerance.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('719a9cd0-9d6c-47ba-b3a5-23afc7e4dcc3', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Evaluating Seed Shatter of Economically Important Prairie Weed Species', 'Nikki Burton', 2016, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/7542', 'http://hdl.handle.net/10388/7542', NULL, NULL, 120, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b5ca3d50-ea3b-4c1c-af85-3803f90b2f84', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Food for Pollinators: Quantifying the Nectar and Pollen Resources of Urban Flower Meadows', 'Hicks DM, Ouvrard P, Baldock KC, Baude M, Goddard MA, Kunin WE, Mitschunas N, Memmott J', 2016, 'PloS one', '10.1371/journal.pone.0158117', 'https://doi.org/10.1371/journal.pone.0158117', 'https://europepmc.org/articles/PMC4920406?pdf=render', NULL, NULL, 37, NULL, 'other', 1, 'cc by', 'Planted meadows are increasingly used to improve the biodiversity and aesthetic amenity value of urban areas. Although many ''pollinator-friendly'' seed mixes are available, the floral resources these provide to flower-visiting insects, and how these change through time, are largely unknown. Such data are necessary to compare the resources provided by alternative meadow seed mixes to each other and to other flowering habitats. We used quantitative surveys of over 2 million flowers to estimate the nectar and pollen resources offered by two exemplar commercial seed mixes (one annual, one perennial) and associated weeds grown as 300m2 meadows across four UK cities, sampled at six time points between May and September 2013. Nectar sugar and pollen rewards per flower varied widely across 65 species surveyed, with native British weed species (including dandelion, Taraxacum agg.) contributing the top five nectar producers and two of the top ten pollen producers. Seed mix species yielding the highest rewards per flower included Leontodon hispidus, Centaurea cyanus and C. nigra for nectar, and Papaver rhoeas, Eschscholzia californica and Malva moschata for pollen. Perennial meadows produced up to 20x more nectar and up to 6x more pollen than annual meadows, which in turn produced far more than amenity grassland controls. Perennial meadows produced resources earlier in the year than annual meadows, but both seed mixes delivered very low resource levels early in the year and these were provided almost entirely by native weeds. Pollen volume per flower is well predicted statistically by floral morphology, and nectar sugar mass and pollen volume per unit area are correlated with flower counts, raising the possibility that resource levels can be estimated for species or habitats where they cannot be measured directly. Our approach does not incorporate resource quality information (for example, pollen protein or essential amino acid content), but can easily do so when suitable data exist. Our approach should inform the design of new seed mixes to ensure continuity in floral resource availability throughout the year, and to identify suitable species to fill resource gaps in established mixes.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5323142c-d3c4-4092-9e8a-5604c3b09887', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Full-Season Cover Crops and Their Traits That Promote Agroecosystem Services', 'Cameron Wagg, Aafke van Erk, Erica Fava, Louis‐Pierre Comeau, T. Fatima Mitterboeck, Claudia Goyer, Sheng Li, Andrew McKenzie‐Gopsill', 2021, 'Agriculture', '10.3390/agriculture11090830', 'https://doi.org/10.3390/agriculture11090830', 'https://www.mdpi.com/2077-0472/11/9/830/pdf?version=1631003129', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by', 'Non-marketable crops are increasingly being used as a tool to promote agroecosystem services and sustainable agriculture. Nevertheless, crops vary greatly in the traits by which they capture resources and influence the local ecosystem. Here we report on the traits and associated soil microbial communities that relate to aboveground biomass production, nutrient capture, weed suppression, erosion control and building particulate organic matter of 22 different full-season cover crops. All agroecosystem services were positively correlated with maximum canopy height and leaf area. Rooting density was positively associated with indices of bacterial diversity. While some legumes produced the greatest standing N and P in aboveground biomass, they were also poor at capturing soil nitrate and promoted high levels of potential plant fungal pathogens. Conversely, Brassicaceae crops had the lowest levels of potential plant fungal pathogens, but also suppressed saprophytic fungi and rhizobia. Thus, not all crops are equal in their ability to promote all agroecosystem services, and while some crops may be ideal for promoting a specific agroecosystem service, this could result in a trade-off with another. Nonetheless, our study demonstrates that plant functional traits are informative for the selection of crops for promoting agroecosystem services.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('47a4dc70-856d-4058-b7fb-9147f5dfb3c6', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Gene Silencing via Ingestion of Double-Stranded RNA in Wireworm of Agriotes Species', 'Joshi J, Coffin R, Barrett R, Wang-Pruski G', 2024, 'Insects', '10.3390/insects15120983', 'https://doi.org/10.3390/insects15120983', 'https://europepmc.org/articles/PMC11679789?pdf=render', NULL, NULL, 18, NULL, 'canada', 3, 'cc by', 'Wireworms are the most destructive soil insect pests affecting horticultural crops. The damage often renders them unsuitable for commercial purposes, resulting in substantial economic losses. RNA interference (RNAi) has been broadly used to inhibit gene functions to control insect populations. It employs double-stranded RNA (dsRNA) to knockdown essential genes in target organisms, rendering them incapable of development or survival. Although it is a robust approach, the primary challenges are identifying effective target genes and delivering their dsRNA into wireworms. Thus, the present study established a liquid ingestion methodology that efficiently delivers dsRNA into wireworms. We then investigated the effects of four target genes on wireworm mortality. The highest mortality rate reached 50% when the gene encoding vacuolar ATPase subunit A was targeted. Its transcript content in the fed wireworms was also significantly reduced. The mortality rates of the other three target genes of vacuolar ATPase subunit E, beta-actin, and chitin synthase 1 were 28%, 33%, and 35%, respectively. This is the first report demonstrating an efficient feeding methodology and the silencing of target genes in wireworms. Our findings indicate that RNAi is an effective alternative method for controlling the wireworm pest, and can be used to develop field treatment strategies.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('78fe77c7-7b03-44d7-af05-b2b45e598ced', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Global Synthesis of Drought Effects on Maize and Wheat Production', 'Daryanto S, Wang L, Jacinthe PA', 2016, 'PloS one', '10.1371/journal.pone.0156362', 'https://doi.org/10.1371/journal.pone.0156362', 'https://europepmc.org/articles/PMC4880198?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Drought has been a major cause of agricultural disaster, yet how it affects the vulnerability of maize and wheat production in combination with several co-varying factors (i.e., phenological phases, agro-climatic regions, soil texture) remains unclear. Using a data synthesis approach, this study aims to better characterize the effects of those co-varying factors with drought and to provide critical information on minimizing yield loss. We collected data from peer-reviewed publications between 1980 and 2015 which examined maize and wheat yield responses to drought using field experiments. We performed unweighted analysis using the log response ratio to calculate the bootstrapped confidence limits of yield responses and calculated drought sensitivities with regards to those co-varying factors. Our results showed that yield reduction varied with species, with wheat having lower yield reduction (20.6%) compared to maize (39.3%) at approximately 40% water reduction. Maize was also more sensitive to drought than wheat, particularly during reproductive phase and equally sensitive in the dryland and non-dryland regions. While no yield difference was observed among regions or different soil texture, wheat cultivation in the dryland was more prone to yield loss than in the non-dryland region. Informed by these results, we discuss potential causes and possible approaches that may minimize drought impacts.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c3839ef5-b12d-4b53-b46d-0c7efe03907f', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Grain yield and nutritional properties of buckwheat (Fagopyrum esculentum M.) grown with varying nitrogen doses and irrigation levels', 'Beyza Ciftci, Sevim Akcura, İhsan Serkan Varol, Yusuf Murat Kardes, Ismail Tas, Mahmut Kaplan', 2025, 'BMC Plant Biology', '10.1186/s12870-025-06921-z', 'https://doi.org/10.1186/s12870-025-06921-z', 'https://doi.org/10.1186/s12870-025-06921-z', NULL, NULL, 14, NULL, 'other', 1, 'open access (DOAJ)', 'Abstract Buckwheat has gained high demand and popularity worldwide in recent years. There are very few studies on the combined use of irrigation and nitrogen applications for the plant. In this study, the effects of different nitrogen dose (0, 30, 60, 90 kg ha−1) and irrigation levels (50%, 75%, 100% of ETo value calculated with the use of evaporations from Class-A pan) applied via fertigation on water use, yield and grain nutritional properties in buckwheat were investigated. The study was carried out in 2020–2021 according to the randomized block design with 3 replications for two years. The highest grain yield was obtained with 100% irrigation level and 90 kg ha−1 nitrogen dose. The increase in nitrogen doses caused significant increases in crop water productivity (CWP) and irrigation water productivity (IWP) values. Plant water consumption (ET) varied between 339 (I0×N50) − 617 (I100×N90) mm. Yield response factor (ky) was determined to be between 1.32 for N0 and 1.49 for N30 according to nitrogen doses, and it was determined that the buckwheat plant was sensitive to water stress. The concentrations of significant constituents, including protein, resistant starch, and fatty acids (oleic acid, linoleic acid), were augmented with elevated irrigation levels and nitrogen fertilization. In addition, mineral contents (Ca, Mg, Fe, Zn, P) increased significantly with increasing irrigation and nitrogen doses. As a result, 100% irrigation level and 90 kg ha−1 nitrogen dose are recommended in buckwheat cultivation for optimum grain yield and nutrient content. It was determined that these applications provided the most suitable results in terms of both quality and yield.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0fe0ac26-f39f-4066-81bc-47b9e879dc97', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'HERBICIDES FOR WEED CONTROL IN SAFFLOWER (Carthamus tinctorius)', 'Robert E. Blackshaw, H.-H. Muendel, Doug A. Derksen', 1990, 'Canadian Journal of Plant Science', '10.4141/cjps90-026', 'https://doi.org/10.4141/cjps90-026', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjps90-026', NULL, NULL, NULL, NULL, 'southern_alberta', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('184bbdab-a9ea-4977-8099-ca3831a4f270', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'High-throughput phenotyping of buckwheat (Fagopyrum esculentum Moench.) genotypes under water stress: exploring drought resistance for sustainable agriculture', 'Antala M, Kovar M, Sporinová L, Filacek A, Juszczak R, Zivcak M, Shomali A, Prasad R', 2025, 'BMC plant biology', '10.1186/s12870-025-06429-6', 'https://doi.org/10.1186/s12870-025-06429-6', 'https://europepmc.org/articles/PMC11978128?pdf=render', NULL, NULL, 14, NULL, 'canada', 3, 'cc by', 'BackgroundAs global agriculture faces the challenge of climate change, characterized by longer and more severe drought episodes, there is an increasing need for crop diversification and improved plant breeding. Buckwheat is one of the climate-resilient candidates for future important crops with remarkable adaptability to various biotic and abiotic stresses. As an underbred crop, a large number of genotypes should be assessed for the breeding of superior plants. Therefore, this study investigates the response of various buckwheat genotypes to water stress by high-throughput phenotyping and auxiliary plant physiology measurements.ResultsWe assessed six buckwheat genotypes from different regions under mild and severe water stress, focusing on morphological and physiological changes to understand drought tolerance mechanisms. Our findings revealed that reallocation of assimilated carbon from growth to secondary metabolite production is a common response to drought stress. Among the genotypes tested, Panda emerged as the most drought-resistant, with its morphology remaining the most stable under mild water stress and its ability to rapidly accumulate protective pigments in response to drought. Silver Hull also demonstrated resilience, maintaining its aboveground biomass under mild water stress at levels comparable to the control group. Additionally, the response magnitude to drought stress was linked to the biomass production potential of the genotypes, which was higher for those from warmer regions (Bhutan, Zimbabwe) and lower for those from colder regions (Poland, Canada).ConclusionThe diversity in genotypic responses highlights the significant role of genetic variability in shaping drought resistance strategies in buckwheat. This research not only enhances our understanding of buckwheat''s physiological responses to water stress but also holds promise for developing drought-resistant buckwheat varieties. These advancements are crucial for promoting sustainable agriculture in the face of climate change.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3b747bb0-e927-42aa-84fc-c1464b907bdd', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Himalayan ecosystem services and climate change driven agricultural frontiers: a scoping review', 'Kc KB, Tzadok E, Pant L', 2022, 'Discover sustainability', '10.1007/s43621-022-00103-9', 'https://doi.org/10.1007/s43621-022-00103-9', 'https://europepmc.org/articles/PMC9579111?pdf=render', NULL, NULL, 12, NULL, 'canada', 3, 'cc by', 'Climate change, rising temperatures, snow melts and more frequent droughts and floods are disproportionately affecting food and water security, habitat health, and agricultural productivity in the Himalayan region. These climatic changes are negatively impacting productivity of staple crops including wheat, maize, and rice at lower altitudes, but may provide opportunities to utilize Climate Change Driven Agricultural Frontiers [CCDAFs] at higher altitudes. Agricultural expansion into CCDAFs paired with behavioural shifts such as replacing traditional crop systems with commercial crops will predominantly affect forests, water resources, and soil health, which are already negatively affected by climate change unless adaptation options are directed to just and sustainable agroecological transitions. By trading regulating, supporting, and cultural services for food and water provisioning services, as are evident in land sparing strategy, the utilization of CCDAFs will have long-term implications for the sustainability of mountain farming systems. Climate change is affecting Himalayan agriculture, food security, and ecosystem services, and scientific literature predominantly focus on one of these topics in isolation, occasionally connecting results to another topic. By classifying literature as predominantly agriculture, food security, or ecosystem service themed, this scoping review identifies sources with multiple dominant themes and explores how the relationships between these topics are represented in literature to provide research based evidence to promote the future expansion of agriculture that is low-carbon, just and sustainable. Gaps in the literature reveal that research is needed on the extent of CCDAFs in the Himalayas and the potential trade-offs on utilizing the frontier areas.Supplementary informationThe online version contains supplementary material available at 10.1007/s43621-022-00103-9.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('61e55a47-62ff-4d11-ac4e-6d1756247156', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Humic Substances: Determining Potential Molecular Regulatory Processes in Plants', 'Shah ZH, Rehman HM, Akhtar T, Alsamadany H, Hamooh BT, Mujtaba T, Daur I, Al Zahrani Y', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.00263', 'https://doi.org/10.3389/fpls.2018.00263', 'https://europepmc.org/articles/PMC5861677?pdf=render', NULL, NULL, 12, NULL, 'other', 1, 'cc by', 'Humic substances (HSs) have considerable effects on soil fertility and crop productivity owing to their unique physiochemical and biochemical properties, and play a vital role in establishing biotic and abiotic interactions within the plant rhizosphere. A comprehensive understanding of the mode of action and tissue distribution of HS is, however, required, as this knowledge could be useful for devising advanced rhizospheric management practices. These substances trigger various molecular processes in plant cells, and can strengthen the plant''s tolerance to various kinds of abiotic stresses. HS manifest their effects in cells through genetic, post-transcriptional, and post-translational modifications of signaling entities that trigger different molecular, biochemical, and physiological processes. Understanding of such fundamental mechanisms will provide a better perspective for defining the cues and signaling crosstalk of HS that mediate various metabolic and hormonal networks operating in plant systems. Various regulatory activities and distribution strategies of HS have been discussed in this review.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('0ac70ed2-30f9-472e-b8f8-1f1db2705125', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Ideotype breeding for crop adaptation to low phosphorus availability on extensive organic farms', 'Carkner MK, Gao X, Entz MH', 2023, 'Frontiers in plant science', '10.3389/fpls.2023.1225174', 'https://doi.org/10.3389/fpls.2023.1225174', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10390776.1/PMC10390776.1.pdf', NULL, NULL, 14, NULL, 'prairies', 4, 'cc by', 'Organic farming in extensive production regions, such as the Canadian prairies have a particularly difficult challenge of replenishing soil reserves of phosphorus (P). Organic grains are exported off the farm while resupply of lost P is difficult due to limited availability of animal manures and low solubility of rock organic fertilizers. As a result, many organic farms on the prairies are deficient in plant-available P, leading to productivity breakdown. A portion of the solution may involve crop genetic improvement. A hypothetical ''catch and release'' wheat ideotype for organic production systems is proposed to (i) enhance P uptake and use efficiency but (ii) translocate less P from the vegetative biomass into the grain. Root traits that would improve P uptake efficiency from less-available P pools under organic production are explored. The need to understand and classify ''phosphorus use efficiency'' using appropriate indices for organic production is considered, as well as the appropriate efficiency indices for use if genetically selecting for the proposed ideotype. The implications for low seed P and high vegetative P are considered from a crop physiology, environmental, and human nutrition standpoint; considerations that are imperative for future feasibility of the ideotype.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('28f3ad5e-09a7-4cbe-9305-e283a2e5ec78', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Impact of integrated sheep grazing for cover crop termination on weed and ground beetle (Coleoptera:Carabidae) communities', 'Sean C. McKenzie, Hayes B. Goosey, Kevin M. O''neill, Fabián D. Menalled', 2015, 'Agriculture Ecosystems & Environment', '10.1016/j.agee.2015.11.018', 'https://doi.org/10.1016/j.agee.2015.11.018', 'https://scholarworks.montana.edu/bitstreams/2c785910-753c-401f-8820-6f0bc67925ad/download', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'Cover crops are a suite of non-marketable plant species grown to improve soil quality. They may have additional benefits including reduced weed pressure and enhanced habitat for beneficial arthropods, but they do not provide direct revenue. Integrating sheep grazing for cover crop termination could make the use of cover crops more economically feasible. However, if grazing shifts biological communities to assemblages of less desired species, producers are unlikely to use this method of cover crop termination. We compared weed and carabid beetle (Coleoptera:Carabidae) communities between cover crops terminated by sheep grazing and those terminated by mowing. Our study consisted of two trials of a two-phase experiment. In the first phase (cover crop phase), we seeded a four-species cover crop to enhance nutrient cycling and prevent erosion. The cover crop consisted of buckwheat (Fagopyrum esculentum), sweetclover (Melilotus officinalis), beets (Beta vulgaris), and peas (Pisum sativum). The cover crop grew to anthesis, and was terminated by either sheep grazing or mowing. In the second phase (cash crop phase), we sowed three cash crops through the previously grazed or mowed plots to assess legacy impacts of cover crop termination strategies on weed community structure. Both years, weed species richness and biomass were greater prior to than after cover crop termination, but overall weed diversity, species richness, and biomass did not differ between grazed and mowed plots. We found no difference in weed diversity, species richness, biomass, or density in the cash-crop phase between previously grazed and mowed plots. Despite temporal differences in species richness and activity–density, carabid diversity, species richness, and activity–density did not differ between grazed and mowed plots. Overall, our results suggest that grazing and mowing act as similar ecological filters of both weed and carabid beetle communities.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('e37655d9-2928-4319-bc7b-62a487e90687', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Determination of the potential to increase freezing tolerance in canola through biotechnology', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/determination-of-the-potential-to-increase-freezing-tolerance-in-canola-through-biotechnology', 'https://open.alberta.ca/dataset/b25cc910-33ea-4bae-89d1-c6142e2f0ae4/resource/1bc594ef-8b1d-4497-851e-bdd07816817f/download/0163010071948-determination-potential-increase-freezing-tolerance-canola-through-biotechnology.pdf', NULL, NULL, 94, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project investigated freezing stress tolerance in Brassica by evaluating gene dosage effects in doubled haploids and by identifying genetic markers and transgenes related to freezing resistance. Haploid embryos were used to study both winter cultivar freezing tolerance and spring cultivar seed maturation stress. The research also tested whether over-expression of alanine-rich proteins, including those encoded by BN28 cDNA, could enhance freezing tolerance in spring and winter types. Short-term expression was tracked using carbon-14-labelled alanine, followed by biochemical and developmental analysis of protein expression. Inheritance of bn28 in the Brassicaceae was also examined.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5950219e-d55c-4909-bb9b-6f6b640663e3', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Implication of allergy and atopy in IgG4-related disease', 'D''Astous-Gauthier K, Ebbo M, Chanez P, Schleinitz N', 2023, 'The World Allergy Organization journal', '10.1016/j.waojou.2023.100765', 'https://doi.org/10.1016/j.waojou.2023.100765', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC10172607.1/PMC10172607.1.pdf', NULL, NULL, 18, NULL, 'canada', 3, 'cc by-nc-nd', 'Immunoglobulin G4-related disease (IgG4-RD) is a chronic multi-organic immune fibrosing disease. It affects preferentially men around middle age and almost any organs can be involved; however, lymph nodes, submandibular and lacrimal glands, pancreas, and retroperitoneum are the most affected. The mainstay treatment is corticosteroids, sometimes adjuncts with DMARDs or rituximab as steroid sparing agents. Th2 inflammation is implicated in the pathophysiology of the disease. Several reports indicate that allergy and/or atopy often affect patients with IgG4-RD. The frequency varies greatly between studies with allergies/allergic diseases reported in 18-76% while atopy is reported in 14-46%. In studies including both, they affect 42 and 62% of patients. Rhinitis and asthma are the most frequent allergic diseases. IgE and blood eosinophiles are often elevated and few studies report that basophils and mast cells could participate in the disease pathogenesis; however, the implication of allergy and atopy remain unclear. No common allergen has been identified and IgG4 production seems to be polyclonal. Although a direct causal effect is unlikely, they could potentially shape the clinical phenotype. Allergies/allergic diseases and/or atopy are reported to be more frequent in IgG4-RD patients presenting head, neck, and thoracic involvement, with higher IgE and eosinophils and less frequent in retroperitoneal fibrosis; however, studies regarding allergy and atopy in IgG4-RD are highly heterogenous. The aim of this article is to review what is currently known about the allergy and atopy in the context of Ig4-RD.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('01cf8b08-ef64-40f3-a404-b962b3535aac', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Increased productivity of a cover crop mixture is not associated with enhanced agroecosystem services', 'Smith RG, Atwood LW, Warren ND', 2014, 'PloS one', '10.1371/journal.pone.0097351', 'https://doi.org/10.1371/journal.pone.0097351', 'https://europepmc.org/articles/PMC4029995?pdf=render', NULL, NULL, 8, NULL, 'other', 1, 'cc by', 'Cover crops provide a variety of important agroecological services within cropping systems. Typically these crops are grown as monocultures or simple graminoid-legume bicultures; however, ecological theory and empirical evidence suggest that agroecosystem services could be enhanced by growing cover crops in species-rich mixtures. We examined cover crop productivity, weed suppression, stability, and carryover effects to a subsequent cash crop in an experiment involving a five-species annual cover crop mixture and the component species grown as monocultures in SE New Hampshire, USA in 2011 and 2012. The mean land equivalent ratio (LER) for the mixture exceeded 1.0 in both years, indicating that the mixture over-yielded relative to the monocultures. Despite the apparent over-yielding in the mixture, we observed no enhancement in weed suppression, biomass stability, or productivity of a subsequent oat (Avena sativa L.) cash crop when compared to the best monoculture component crop. These data are some of the first to include application of the LER to an analysis of a cover crop mixture and contribute to the growing literature on the agroecological effects of cover crop diversity in cropping systems.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b537b96a-d150-4cf5-a350-d68fdc0265cd', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Industrial hemp seed: from the field to value-added food ingredients', 'Burton RA, Andres M, Cole M, Cowley JM, Augustin MA', 2022, 'Journal of cannabis research', '10.1186/s42238-022-00156-7', 'https://doi.org/10.1186/s42238-022-00156-7', 'https://europepmc.org/articles/PMC9338676?pdf=render', NULL, NULL, 13, NULL, 'other', 1, 'cc by', 'Industrial hemp, with low levels of the intoxicating cannabinoid tetrahydrocannabinol (THC), is grown for fibre and seeds. The industrial hemp industry is poised for expansion. The legalisation of industrial hemp as an agricultural commodity and the inclusion of hemp seed in foods is helping to drive the expansion of the hemp food ingredients industry. This paper discusses the opportunity to build an industrial hemp industry, with a focus on the prospects of hemp seed and its components in food applications. The market opportunities for industrial hemp products are examined. Various aspects of the science that underpins the development of an industrial hemp industry through the food supply chain are presented. This includes a discussion on the agronomy, on-farm and post-harvest considerations and the various types of food ingredients that can be made from hemp seed. The characteristics of hemp seed meal, hemp seed protein and hemp seed oil are reviewed. Different processes for production of value-added ingredients from hemp seed, hemp seed oil and hemp seed protein, are examined. The applicability of hemp seed ingredients in food applications is reviewed. The design of hemp seed ingredients that are fit-for-purpose for target food applications, through the selection of varieties and processing methods for production of various hemp seed ingredients, needs to consider market-led opportunities. This will require an integrated through chain approach, combined with the development of on-farm and post-farm strategies, to ensure that the hemp seed ingredients and foods containing hemp seed are acceptable to the consumer.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('ca7edb97-87b0-4665-9e13-0d80122e82c8', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Influence of cover crops at the four spheres: A review of ecosystem services, potential barriers, and future directions for North America', 'Laura L. Van Eerd, Inderjot Chahal, Yajun Peng, Jessica C. Awrey', 2022, 'The Science of The Total Environment', '10.1016/j.scitotenv.2022.159990', 'https://doi.org/10.1016/j.scitotenv.2022.159990', 'https://www.sciencedirect.com/science/article/pii/S0048969722070905/pdf', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by-nc-nd', 'Cover crops have been studied for over a century, but the recognition of a complex interaction of cover crop on the Earth''s biosphere, lithosphere, hydrosphere, and atmosphere is relatively recent. Furthermore, previously published cover crop research has largely focused on evaluating cover crop impacts on subsequent crop yield. Understanding the cover crop-induced benefits on soil organic carbon (SOC) sequestration, nitrous oxide (N 2 O) emissions, wind and water erosion, weed control, and soil microbial communities has gained considerable attention in the last few decades, which is crucial to make progress towards developing sustainable agricultural production systems. New research is continuously published to gain a comprehensive understanding of the multiple ecosystem services provided by cover crops. Here, in this review, we aimed to (a) summarize current knowledge related to cover crop impacts on agroecosystem functioning and explore the potential mechanisms responsible for those effects, and (b) identify the key factors limiting the adoption of cover crops into agroecosystems and the conspicuous knowledge gaps in cover crop research. Overall, the review results suggest that cover crops increased subsequent crop yield, increased SOC storage, increased weed suppression, mitigated N 2 O emissions, reduced wind and water erosion, suppressed plant pathogens, and increased soil microbial activity and wildlife biodiversity. However, the magnitude of benefits observed with cover crops varied with cover crop type, location, and the duration of cover cropping. Notably, cover crop termination methods, designing crop rotations to fit cover crops, additional costs associated with cover crop integration, and uncertainty related to economic returns with cover crops are some of the major barriers limiting the adoption of cover crops into production systems, particularly in North America. In addition to long-term effects, future research on cover crop agronomy, breeding cover crop cultivars, and interactive effects of cover crops with other sustainable land management practices is needed.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('971b30e4-dd1b-48b6-8adf-1530b7fbb3e9', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Recent Developments in Microbe-Plant-Based Bioremediation for Tackling Heavy Metal-Polluted Soils', 'Saha L, Tiwari J, Bauddh K, Ma Y', 2021, 'Frontiers in microbiology', '10.3389/fmicb.2021.731723', 'https://doi.org/10.3389/fmicb.2021.731723', 'https://europepmc.org/articles/PMC8733405?pdf=render', NULL, NULL, 24, NULL, 'other', 1, 'cc by', 'Soil contamination with heavy metals (HMs) is a serious concern for the developing world due to its non-biodegradability and significant potential to damage the ecosystem and associated services. Rapid industrialization and activities such as mining, manufacturing, and construction are generating a huge quantity of toxic waste which causes environmental hazards. There are various traditional physicochemical techniques such as electro-remediation, immobilization, stabilization, and chemical reduction to clean the contaminants from the soil. However, these methods require high energy, trained manpower, and hazardous chemicals make these techniques costly and non-environment friendly. Bioremediation, which includes microorganism-based, plant-based, microorganism-plant associated, and other innovative methods, is employed to restore the contaminated soils. This review covers some new aspects and dimensions of bioremediation of heavy metal-polluted soils. The bioremediation potential of bacteria and fungi individually and in association with plants has been reviewed and critically examined. It is reported that microbes such as Pseudomonas spp., Bacillus spp., and Aspergillus spp., have high metal tolerance, and bioremediation potential up to 98% both individually and when associated with plants such as Trifolium repens, Helianthus annuus, and Vallisneria denseserrulata. The mechanism of microbe''s detoxification of metals depends upon various aspects which include the internal structure, cell surface properties of microorganisms, and the surrounding environmental conditions have been covered. Further, factors affecting the bioremediation efficiency and their possible solution, along with challenges and future prospects, are also discussed.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d17c8c23-8f25-4a26-9762-942800684e7e', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Integrating cover crops for weed management in the semiarid U.S. Great Plains: opportunities and challenges', 'Vipan Kumar, Augustine K. Obour, Prashant Jha, Rui Liu, Misha R. Manuchehri, Johanna Anita Dille, Johnathon D. Holman, Phillip W. Stahlman', 2020, 'Weed Science', '10.1017/wsc.2020.29', 'https://doi.org/10.1017/wsc.2020.29', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/220DC4C8163E614B56E86CFE08BCDB05/S0043174520000296a.pdf/div-class-title-integrating-cover-crops-for-weed-management-in-the-semiarid-u-s-great-plains-opportunities-and-challenges-div.pdf', NULL, NULL, 13, NULL, 'northern_plains', 3, 'cc-by', 'Abstract The widespread evolution of herbicide resistance in weed populations has become an increasing concern for no-tillage (NT) growers in semiarid regions of the U.S. Great Plains. Lack of cost-effective and alternative new herbicide sites of action further exacerbates the problem of herbicide-resistant (HR) weeds and threatens the long-term sustainability of prevailing cropping systems in the region. A recent decline in commodity prices and increasing herbicide costs to manage HR weeds has spurred research efforts to build a strong rationale for developing ecologically based integrated weed management (IWM) strategies in the U.S. Great Plains. Integration of cover crops (CCs) in NT dryland production systems potentially offers several ecosystem services, including weed control, soil health improvement, decline in selective pest pressure, and overall reduction in pest management inputs. This review article aims to document the role of CCs for IWM, with emphasis on exploring emerging weed issues; ecological, economic, and agronomic benefits of growing CCs; and constraints preventing adoption of CCs in NT cropping systems in the semiarid Great Plains. We attempt to focus on changes in weed management practices, their long-term impacts on weed seedbanks, weed shifts, and herbicide-resistance evolution in the most common weed species in the region. We also highlight current knowledge gaps and propose new research priorities based on an improved understanding of CC management strategies that will ultimately aid in achieving sustainable weed management goals and preserving natural resources in water-limited environments.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('fcf2ab2c-b530-4766-9dee-af20a5b6a6d8', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Integration of sheep grazing for cover crop termination into market gardens: Agronomic consequences of an ecologically based management strategy', 'Sean C. McKenzie, Hayes B. Goosey, Kevin M. O''neill, Fabián D. Menalled', 2016, 'Renewable Agriculture and Food Systems', '10.1017/s1742170516000326', 'https://doi.org/10.1017/s1742170516000326', 'https://scholarworks.montana.edu/bitstreams/0a61f483-ec5c-433e-8f2a-b773fec60f5a/download', NULL, NULL, 14, NULL, 'northern_plains', 3, 'cc-by-nc-nd', 'Abstract Cover crops are suites of non-marketable plants grown to improve soil tilth and reduce erosion. Despite these agronomic benefits, the use of cover crops is often limited because they do not provide a direct source of revenue for producers. Integrating livestock to graze cover crops could provide both an expeditious method for cover crop termination and an alternative source of revenue. However, there has been little research on the agronomic impacts of grazing for cover crop termination, especially in horticultural market-gardens. We conducted a 3-year study comparing the effects of sheep grazing to terminate a four species cover crop (buckwheat, sweetclover, peas and beets) with those of mowing on soil quality indicators, cover crop termination efficacy, and subsequent cash-crop yields. In addition, we tested the nutritional quality of the cover crop as forage. Compared with mowing, sheep grazing did not affect soil chemistry, temperature or moisture. Our study demonstrates that sheep grazing removed more cover crop biomass than mowing at termination. The assessment of nutritional indices suggests that the four-species cover crop mixture could provide high-quality forage with a potential value of US$144.00–481.80 ha−1of direct revenue as a grazing lease. Cash-crop yields did not differ between previously grazed and previously mowed plots in the subsequent growing season. We conclude that integrating sheep grazing into market vegetable garden operations could make cover crops more economically viable without having adverse effects on subsequent cash crops.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b56697f7-daa2-488d-8950-b899899112aa', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Microbial seed coating: An attractive tool for sustainable agriculture', 'Paravar A, Piri R, Balouchi H, Ma Y', 2023, 'Biotechnology reports (Amsterdam, Netherlands)', '10.1016/j.btre.2023.e00781', 'https://doi.org/10.1016/j.btre.2023.e00781', 'https://europepmc.org/articles/PMC9841043?pdf=render', NULL, NULL, 15, NULL, 'other', 1, 'cc by', 'Seed coating is considered one of the best methods to promote sustainable agriculture where the physical and physiological properties of seeds can be improved to facilitate planting, increase growth indices and alleviate abiotic and biotic stresses. Several methods of seed coating are used to attain good application uniformity and adherence in the seed coating process. Seed coating has been tested in seeds of various plant species with different dimensions, forms, textures, and germination types. Plant beneficial microorganisms (PBM), such as rhizobia, bacteria, and fungi inoculated via seed inoculation can increase seed germination, plant performance and tolerance across biotic (e.g., pathogens and pests) and abiotic stress (e.g., salt, drought, and heavy metals) while reducing the use of agrochemical inputs. In this review, the microbial seed coating process and their ability to increase seed performance and protect plants from biotic and abiotic stresses are well discussed and highlighted in sustainable agricultural systems.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('abae43a6-832f-4ff6-b1ea-c4289a91695a', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Non-Chemical Weed Management in Vegetables by Using Cover Crops: A Review', 'Hüsrev Mennan, Khawar Jabran, Bernard H. Zandstra, Fırat Pala', 2020, 'Agronomy', '10.3390/agronomy10020257', 'https://doi.org/10.3390/agronomy10020257', 'https://www.mdpi.com/2073-4395/10/2/257/pdf?version=1582952538', NULL, NULL, NULL, NULL, 'northern_plains', 3, 'cc-by', 'Vegetables are a substantial part of our lives and possess great commercial and nutritional value. Weeds not only decrease vegetable yield but also reduce their quality. Non-chemical weed control is important both for the organic production of vegetables and achieving ecologically sustainable weed management. Estimates have shown that the yield of vegetables may be decreased by 45%–95% in the case of weed–vegetable competition. Non-chemical weed control in vegetables is desired for several reasons. For example, there are greater chances of contamination of vegetables by herbicide residue compared to cereals or pulse crops. Non-chemical weed control in vegetables is also needed due to environmental pollution, the evolution of herbicide resistance in weeds and a strong desire for organic vegetable cultivation. Although there are several ways to control weeds without the use of herbicides, cover crops are an attractive choice because these have a number of additional benefits (such as soil and water conservation) along with the provision of satisfactory and sustainable weed control. Several cover crops are available that may provide excellent weed control in vegetable production systems. Cover crops such as rye, vetch, or Brassicaceae plants can suppress weeds in rotations, including vegetables crops such as tomato, cabbage, or pumpkin. Growers should also consider the negative effects of using cover crops for weed control, such as the negative allelopathic effects of some cover crop residues on the main vegetable crop.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2d816963-9b71-460c-8815-655dbcffff85', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Optimizing weed control in lentil', 'L. K. Fedoruk', 2010, 'University Library - University of Saskatchewan (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/etd-04142010-090417', 'http://hdl.handle.net/10388/etd-04142010-090417', NULL, NULL, 86, NULL, 'prairies', 3, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d5923863-cd9f-411b-8572-921a353a3e33', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Physical characteristics of soil-biodegradable and nonbiodegradable plastic mulches impact conidial splash dispersal of Botrytis cinerea', 'Wang X, Mattupalli C, Chastagner G, Tymon L, Wu Z, Jung S, Liu H, DeVetter LW', 2023, 'PloS one', '10.1371/journal.pone.0285094', 'https://doi.org/10.1371/journal.pone.0285094', 'https://europepmc.org/articles/PMC10166481?pdf=render', NULL, NULL, 18, NULL, 'northern_plains', 3, 'cc by', 'Botrytis cinerea causes gray mold disease of strawberry (Fragaria ×ananassa) and is a globally important pathogen that causes fruit rot both in the field and after harvest. Commercial strawberry production involves the use of plastic mulches made from non-degradable polyethylene (PE), with weedmat made from woven PE and soil-biodegradable plastic mulch (BDM) as emerging mulch technologies that may enhance sustainable production. Little is known regarding how these plastic mulches impact splash dispersal of B. cinerea conidia. The objective of this study was to investigate splash dispersal dynamics of B. cinerea when exposed to various plastic mulch surfaces. Mulch surface physical characteristics and conidial splash dispersal patterns were evaluated for the three mulches. Micrographs revealed different surface characteristics that have the potential to influence splash dispersal: PE had a flat, smooth surface, whereas weedmat had large ridges and BDM had an embossed surface. Both PE mulch and BDM were impermeable to water whereas weedmat was semi-permeable. Results generated using an enclosed rain simulator system showed that as the horizontal distance from the inoculum source increased, the number of splash dispersed B. cinerea conidia captured per plate decreased for all mulch treatments. More than 50% and approximately 80% of the total number of dispersed conidia were found on plates 10 and 16 cm away from the inoculum source across all treatments, respectively. A significant correlation between the total and germinated conidia on plates across all mulch treatments was detected (P<0.01). Irrespective of distance from the inoculum source, embossed BDM facilitated higher total and germinated splashed conidia (P<0.001) compared to PE mulch and weedmat (P = 0.43 and P = 0.23, respectively), indicating BDM''s or embossed film''s potential for enhancing B. cinerea inoculum availability in strawberry production under plasticulture. However, differences in conidial concentrations observed among treatments were low and may not be pathologically relevant.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('25a7bb07-0797-41aa-aa53-84ddce572a91', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Phytoremediation of Cadmium: Physiological, Biochemical, and Molecular Mechanisms', 'Raza A, Habib M, Kakavand SN, Zahid Z, Zahra N, Sharif R, Hasanuzzaman M', 2020, 'Biology', '10.3390/biology9070177', 'https://doi.org/10.3390/biology9070177', 'https://europepmc.org/articles/PMC7407403?pdf=render', NULL, NULL, NULL, NULL, 'other', 1, 'cc by', 'Cadmium (Cd) is one of the most toxic metals in the environment, and has noxious effects on plant growth and production. Cd-accumulating plants showed reduced growth and productivity. Therefore, remediation of this non-essential and toxic pollutant is a prerequisite. Plant-based phytoremediation methodology is considered as one a secure, environmentally friendly, and cost-effective approach for toxic metal remediation. Phytoremediating plants transport and accumulate Cd inside their roots, shoots, leaves, and vacuoles. Phytoremediation of Cd-contaminated sites through hyperaccumulator plants proves a ground-breaking and profitable choice to combat the contaminants. Moreover, the efficiency of Cd phytoremediation and Cd bioavailability can be improved by using plant growth-promoting bacteria (PGPB). Emerging modern molecular technologies have augmented our insight into the metabolic processes involved in Cd tolerance in regular cultivated crops and hyperaccumulator plants. Plants'' development via genetic engineering tools, like enhanced metal uptake, metal transport, Cd accumulation, and the overall Cd tolerance, unlocks new directions for phytoremediation. In this review, we outline the physiological, biochemical, and molecular mechanisms involved in Cd phytoremediation. Further, a focus on the potential of omics and genetic engineering strategies has been documented for the efficient remediation of a Cd-contaminated environment.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('517f32a6-5f7d-47da-9e4c-bb146b6640c1', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Plant Allelochemicals as Sources of Insecticides', 'Tlak Gajger I, Dar SA', 2021, 'Insects', '10.3390/insects12030189', 'https://doi.org/10.3390/insects12030189', 'https://europepmc.org/articles/PMC7996276?pdf=render', NULL, NULL, 21, NULL, 'other', 1, 'cc by', 'In this review, we describe the role of plant-derived biochemicals that are toxic to insect pests. Biotic stress in plants caused by insect pests is one of the most significant problems, leading to yield losses. Synthetic pesticides still play a significant role in crop protection. However, the environmental side effects and health issues caused by the overuse or inappropriate application of synthetic pesticides forced authorities to ban some problematic ones. Consequently, there is a strong necessity for novel and alternative insect pest control methods. An interesting source of ecological pesticides are biocidal compounds, naturally occurring in plants as allelochemicals (secondary metabolites), helping plants to resist, tolerate or compensate the stress caused by insect pests. The abovementioned bioactive natural products are the first line of defense in plants against insect herbivores. The large group of secondary plant metabolites, including alkaloids, saponins, phenols and terpenes, are the most promising compounds in the management of insect pests. Secondary metabolites offer sustainable pest control, therefore we can conclude that certain plant species provide numerous promising possibilities for discovering novel and ecologically friendly methods for the control of numerous insect pests.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('78335e32-8874-476f-8b69-f05d85f0b009', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Rangeland dynamics: investigating vegetation composition and structure of urban and exurban prairie dog habitat', 'Hopson R, Meiman P, Shannon G', 2015, 'PeerJ', '10.7717/peerj.736', 'https://doi.org/10.7717/peerj.736', 'https://europepmc.org/articles/PMC4314087?pdf=render', NULL, NULL, 17, NULL, 'northern_plains', 3, 'cc by', 'Rapid human population growth and habitat modification in the western United States has led to the formation of urban and exurban rangelands. Many of these rangelands are also home to populations of black-tailed prairie dogs (Cynomys ludovicianus). Our study aimed to compare the vegetation composition of an urban and exurban rangeland, and explore the role that prairie dogs play in these systems. The percent absolute canopy cover of graminoids (grasses and grass-likes), forbs, shrubs, litter, and bare ground were estimated at sampling areas located on and off prairie dog colonies at an urban and an exurban site. Herbaceous forage quality and quantity were determined on plant material collected from exclosure cages located on the colony during the entire growing season, while a relative estimate of prairie dog density was calculated using maximum counts. The exurban site had more litter and plant cover and less bare ground than the urban site. Graminoids were the dominant vegetation at the exurban plots. In contrast, mostly introduced forbs were found on the urban prairie dog colony. However, the forage quality and quantity tests demonstrated no difference between the two colonies. The relative prairie dog density was greater at the urban colony, which has the potential to drive greater vegetation utilization and reduced cover. Exurban rangeland showed lower levels of impact and retained all of the plant functional groups both on- and off-colony. These results suggest that activities of prairie dogs might further exacerbate the impacts of humans in fragmented urban rangeland habitats. Greater understanding of the drivers of these impacts and the spatial scales at which they occur are likely to prove valuable in the management and conservation of rangelands in and around urban areas.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('9b1fcad7-3b1b-4f08-9efe-9cd789e53011', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Reduced canopy cover and development compromises weed suppression by buckwheat in cover crop mixtures', 'Maya Worthing, Aaron A. S. Mills, Andrew McKenzie‐Gopsill', 2024, 'Canadian Journal of Plant Science', '10.1139/cjps-2024-0117', 'https://doi.org/10.1139/cjps-2024-0117', 'https://cdnsciencepub.com/doi/pdf/10.1139/cjps-2024-0117', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by', 'Buckwheat ( Fagopyrum esculentum Moench) is a common cover crop typically grown for its rapid establishment and superior weed suppression. One challenge of incorporating buckwheat into crop rotations, however, is its short generation time, which requires in-season management to prevent viable seed production and volunteers in subsequent crops. Mixing buckwheat at reduced seeding rates with other cover crop species is one way for producers to reduce volunteer potential; however, this may compromise weed suppression. To investigate mechanisms behind buckwheat weed suppression and how using buckwheat in mixtures can affect suppression, we collected a series of morphological measurements in buckwheat monocultures and in three, two-way and four, three-way cover crop species mixtures and modeled their response over the growing season. We found that while buckwheat height and relative growth rate were unaffected with increasing species richness, there was a significant reduction in maximum leaf area index (3.75 vs. 2.85 vs. 2.82 cm2 cm−2) in mixture. Buckwheat monocultures provided superior season-long weed suppression compared to mixtures (85% vs. 53% vs. 50%). Principal component analysis showed that increased height and leaf area index values were associated with greater weed suppression. The link between reduced leaf area index and weed suppression in mixtures compared to buckwheat monocultures suggests that the rapid leaf development and canopy cover associated with buckwheat is a key mechanism behind weed suppression. In practice, producers should expect a dilution effect and weed suppression to be compromised when the buckwheat seeding rate is reduced in mixtures.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('930583a9-6b83-4d30-ad72-0ea695b458f3', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Research Progress on the use of Plant Allelopathy in Agriculture and the Physiological and Ecological Mechanisms of Allelopathy', 'Cheng F, Cheng Z', 2015, 'Frontiers in plant science', '10.3389/fpls.2015.01020', 'https://doi.org/10.3389/fpls.2015.01020', 'https://europepmc.org/articles/PMC4647110?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Allelopathy is a common biological phenomenon by which one organism produces biochemicals that influence the growth, survival, development, and reproduction of other organisms. These biochemicals are known as allelochemicals and have beneficial or detrimental effects on target organisms. Plant allelopathy is one of the modes of interaction between receptor and donor plants and may exert either positive effects (e.g., for agricultural management, such as weed control, crop protection, or crop re-establishment) or negative effects (e.g., autotoxicity, soil sickness, or biological invasion). To ensure sustainable agricultural development, it is important to exploit cultivation systems that take advantage of the stimulatory/inhibitory influence of allelopathic plants to regulate plant growth and development and to avoid allelopathic autotoxicity. Allelochemicals can potentially be used as growth regulators, herbicides, insecticides, and antimicrobial crop protection products. Here, we reviewed the plant allelopathy management practices applied in agriculture and the underlying allelopathic mechanisms described in the literature. The major points addressed are as follows: (1) Description of management practices related to allelopathy and allelochemicals in agriculture. (2) Discussion of the progress regarding the mode of action of allelochemicals and the physiological mechanisms of allelopathy, consisting of the influence on cell micro- and ultra-structure, cell division and elongation, membrane permeability, oxidative and antioxidant systems, growth regulation systems, respiration, enzyme synthesis and metabolism, photosynthesis, mineral ion uptake, protein and nucleic acid synthesis. (3) Evaluation of the effect of ecological mechanisms exerted by allelopathy on microorganisms and the ecological environment. (4) Discussion of existing problems and proposal for future research directions in this field to provide a useful reference for future studies on plant allelopathy.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('68cdc495-9146-4599-8810-2f925daa6aff', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Frying performance of canola fats and their effects on convenience food quality', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/frying-performance-of-canola-fats-and-their-effects-on-convenience-food-quality', 'https://open.alberta.ca/dataset/5f3b46f4-2aae-4f6d-95b3-543a9850eb00/resource/1a00563b-9ad9-49d2-9714-484c8a00f315/download/163010361836-frying-performance-of-canola-fats-and-their-effects-on-convenience-food-quality.pdf', NULL, NULL, 50, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This study evaluated the effects of finish frying frozen parfried French fries in several fats, including partially hydrogenated canola, hydrogenated canola, partially hydrogenated soy, hydrogenated soy, and tallow, on French fry quality and fat stability. Sensory and instrumental analyses showed that hydrogenated canola produced fries with the lowest oil flavor, while partially hydrogenated soy resulted in the most intense oil flavor and the highest p-Anisidine and volatile compound levels. All treatments produced similar crispness and internal texture. Fat deterioration was minimal over four days of frying. Overall, the quality of French fries and the frying performance of canola, soy, and tallow fats were similar.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b398b29-d23b-4f1f-9aa0-362fcb7cbf07', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Response of Plant Secondary Metabolites to Environmental Factors', 'Yang L, Wen KS, Ruan X, Zhao YX, Wei F, Wang Q', 2018, 'Molecules (Basel, Switzerland)', '10.3390/molecules23040762', 'https://doi.org/10.3390/molecules23040762', 'https://europepmc.org/articles/PMC6017249?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'Plant secondary metabolites (SMs) are not only a useful array of natural products but also an important part of plant defense system against pathogenic attacks and environmental stresses. With remarkable biological activities, plant SMs are increasingly used as medicine ingredients and food additives for therapeutic, aromatic and culinary purposes. Various genetic, ontogenic, morphogenetic and environmental factors can influence the biosynthesis and accumulation of SMs. According to the literature reports, for example, SMs accumulation is strongly dependent on a variety of environmental factors such as light, temperature, soil water, soil fertility and salinity, and for most plants, a change in an individual factor may alter the content of SMs even if other factors remain constant. Here, we review with emphasis how each of single factors to affect the accumulation of plant secondary metabolites, and conduct a comparative analysis of relevant natural products in the stressed and unstressed plants. Expectantly, this documentary review will outline a general picture of environmental factors responsible for fluctuation in plant SMs, provide a practical way to obtain consistent quality and high quantity of bioactive compounds in vegetation, and present some suggestions for future research and development.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('495cf08b-72d3-4c77-b992-157709945bf6', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Seeking sustainability for organic cropping systems in the northern Great Plains : legume green manure management strategies', 'Erica Jean. Izard', 2007, 'Montana State University ScholarWorks (Montana State University)', NULL, 'https://scholarworks.montana.edu/bitstreams/c7347e4a-76a4-49ac-9898-a5ba6c6246ff/download', 'https://scholarworks.montana.edu/xmlui/handle/1/1541', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('95512ef0-b095-493a-9ff3-65807f7a140e', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Sprouts and Microgreens-Novel Food Sources for Healthy Diets', 'Ebert AW', 2022, 'Plants (Basel, Switzerland)', '10.3390/plants11040571', 'https://doi.org/10.3390/plants11040571', 'https://europepmc.org/articles/PMC8877763?pdf=render', NULL, NULL, 35, NULL, 'other', 1, 'cc by', 'With the growing interest of society in healthy eating, the interest in fresh, ready-to-eat, functional food, such as microscale vegetables (sprouted seeds and microgreens), has been on the rise in recent years globally. This review briefly describes the crops commonly used for microscale vegetable production, highlights Brassica vegetables because of their health-promoting secondary metabolites (polyphenols, glucosinolates), and looks at consumer acceptance of sprouts and microgreens. Apart from the main crops used for microscale vegetable production, landraces, wild food plants, and crops'' wild relatives often have high phytonutrient density and exciting flavors and tastes, thus providing the scope to widen the range of crops and species used for this purpose. Moreover, the nutritional value and content of phytochemicals often vary with plant growth and development within the same crop. Sprouted seeds and microgreens are often more nutrient-dense than ungerminated seeds or mature vegetables. This review also describes the environmental and priming factors that may impact the nutritional value and content of phytochemicals of microscale vegetables. These factors include the growth environment, growing substrates, imposed environmental stresses, seed priming and biostimulants, biofortification, and the effect of light in controlled environments. This review also touches on microgreen market trends. Due to their short growth cycle, nutrient-dense sprouts and microgreens can be produced with minimal input; without pesticides, they can even be home-grown and harvested as needed, hence having low environmental impacts and a broad acceptance among health-conscious consumers.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1de8f5ab-d8c5-4493-8ce1-c3ea0c010528', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Summer cover crops impact weed biomass and C and N acquisition', 'Francis J. Larney, Haley A. Catton, Charles M. Geddes, Newton Z. Lupwayi, Thomas A. Forge, Henry Wai Chau, Bobbi L. Helgason, Ekene Mark‐Anthony Iheshiulo', 2026, 'Agronomy Journal', '10.1002/agj2.70286', 'https://doi.org/10.1002/agj2.70286', 'https://onlinelibrary.wiley.com/doi/pdfdirect/10.1002/agj2.70286', NULL, NULL, NULL, NULL, 'southern_alberta', 4, 'cc-by', 'Abstract Despite the potential to improve nutrient cycling, weed suppression, and system resilience, mixed‐species cover crops remain underutilized in organic irrigated systems. This study evaluated the influence of cover crop diversity and associated weeds on biomass production (both cover crops and weeds), as well as carbon (C) and nitrogen (N) acquisition, and weed suppression. Three summer cover crop–carrot rotation cycles (2018–2019, 2019–2020, and 2021–2022) were established on a clay‐textured soil in a 50‐ha organic pivot‐irrigated field in Alberta. Cover crops included a polyculture (POLY) and monoculture of mustard (MUST; white [ Sinapsis alba L.] and brown [ Brassica juncea (L.) Czern.]), buckwheat (BWHT, Fagopyrum esculentum Moench), faba bean (FABA; Vicia faba L.), and a no‐cover control (CONT). Cover crop performance varied by species and year. POLY consistently produced the highest biomass (up to 2.79 Mg ha −1 ) and, along with BWHT, achieved the greatest weed suppression (62%–72%), while FABA and MUST were least effective. FABA had the highest N concentration (27–32 g kg −1 ) and lowest C:N ratios (13–16), whereas BWHT had the highest C:N ratios (21–36). C and N uptake were generally greater in POLY (up to 1.20 Mg C ha −1 ; 74 kg N ha −1 ) and lowest in FABA or MUST, with POLY and BWHT accounting for the largest share of total biomass nutrient uptake (53%–69%). Overall, these findings demonstrate that cover crop performance is highly context‐dependent, with POLY and BWHT offering more consistent benefits in biomass production, weed suppression, and nutrient acquisition, and highlight the complementary role of weeds in nutrient cycling.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2b8fbb2b-8959-4c45-ad5f-9c603c460c20', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Teosinte (Zea mays ssp parviglumis) growth and transcriptomic response to weed stress identifies similarities and differences between varieties and with modern maize varieties', 'Bruggeman SA, Horvath DP, Fennell AY, Gonzalez-Hernandez JL, Clay SA', 2020, 'PloS one', '10.1371/journal.pone.0237715', 'https://doi.org/10.1371/journal.pone.0237715', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7444550.1/PMC7444550.1.pdf', NULL, NULL, 19, NULL, 'northern_plains', 3, 'cc0', 'Transcriptomic responses of plants to weed presence gives insight on the physiological and molecular mechanisms involved in the stress response. This study evaluated transcriptomic and morphological responses of two teosinte (Zea mays ssp parviglumis) (an ancestor of domesticated maize) lines (Ames 21812 and Ames 21789) to weed presence and absence during two growing seasons. Responses were compared after 6 weeks of growth in Aurora, South Dakota, USA. Plant heights between treatments were similar in Ames 21812, whereas branch number decreased when weeds were present. Ames 21789 was 45% shorter in weedy vs weed-free plots, but branch numbers were similar between treatments. Season-long biomass was reduced in response to weed stress in both lines. Common down-regulated subnetworks in weed-stressed plants were related to light, photosynthesis, and carbon cycles. Several unique response networks (e.g. aging, response to chitin) and gene sets were present in each line. Comparing transcriptomic responses of maize (determined in an adjacent study) and teosinte lines indicated three common gene ontologies up-regulated when weed-stressed: jasmonic acid response/signaling, UDP-glucosyl and glucuronyltransferases, and quercetin glucosyltransferase (3-O and 7-O). Overall, morphologic and transcriptomic differences suggest a greater varietal (rather than a conserved) response to weed stress, and implies multiple responses are possible. These findings offer insights into opportunities to define and manipulate gene expression of several different pathways of modern maize varieties to improve performance under weedy conditions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c3540279-2e63-44bf-9519-c8c9421a69ee', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The Current State and Future Directions of Organic No-Till Farming with Cover Crops in Canada, with Case Study Support', 'Heather Beach, Ken Laing, Morris Walle, Ralph C. Martin', 2018, 'Sustainability', '10.3390/su10020373', 'https://doi.org/10.3390/su10020373', 'https://www.mdpi.com/2071-1050/10/2/373/pdf?version=1517409454', NULL, NULL, NULL, NULL, 'canada', 3, 'cc-by', 'Eliminating regular tillage practices in agriculture has numerous ecological benefits that correspond to the intentions of organic agriculture; yet, more tillage is conducted in organic agriculture than in conventional agriculture. Organic systems face more management challenges to avoid tillage. This paper identifies factors to consider when implementing no-till practices particularly in organic agronomic and vegetable crop agriculture and describes techniques to address these factors. In some cases, future research is recommended to effectively address the current limitations. The format includes a literature review of organic no-till (OrgNT) research and two case studies of Ontario organic farmers that highlight no-till challenges and practices to overcome these challenges. Cover crops require significant consideration because they are the alternative to herbicides and fertilizers to manage weeds and provide nutrients in the OrgNT system. Equipment requirements have also proven to be unique in OrgNT systems. In the future, it is recommended that researchers involve organic farmers closely in studies on no-till implementation, so that the farmers’ concerns are effectively addressed, and research is guided by possibilities recognized by the practitioners.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('db3ba7d9-80e9-4817-8416-35586469afb8', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'THE EFFECT OF FARM AND GREEN MANURES ON THE FERTILITY OF BLACKEARTH-MEADOW CLAY SOILS', 'Edward A. Poyser, R. A. Hedlin, A. O. Ridley', 1957, 'Canadian Journal of Soil Science', '10.4141/cjss57-007', 'https://doi.org/10.4141/cjss57-007', 'https://cdnsciencepub.com/doi/pdf/10.4141/cjss57-007', NULL, NULL, NULL, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f73b4806-a9eb-4693-9eec-403438a459ac', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The effect of integrated crop management (ICM) on crop-weed competition, weed phenology and weed seed dormancy', 'Uthpala Ekanayake', 2026, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/39562', 'https://mspace.lib.umanitoba.ca/bitstreams/286b51ec-48eb-4f33-8598-bd3fe9d11221/download', NULL, NULL, 152, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a192fbf2-1f2c-433b-aca0-8f2a6c891ca1', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The evaluation of new harvest aid herbicides for dry bean (Phaseolus vulgaris L.) production in Manitoba', 'Kristine A. Waddell', 2014, 'Mspace (University of Manitoba)', NULL, 'http://hdl.handle.net/1993/23239', 'http://hdl.handle.net/1993/23239', NULL, NULL, 137, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2685794c-c7f0-409f-9a9a-62dedd88aac0', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The hidden land use cost of upscaling cover crops', 'Runck BC, Khoury CK, Ewing PM, Kantar M', 2020, 'Communications biology', '10.1038/s42003-020-1022-1', 'https://doi.org/10.1038/s42003-020-1022-1', 'https://pmc-oa-opendata.s3.amazonaws.com/PMC7289881.1/PMC7289881.1.pdf', NULL, NULL, 4, NULL, 'northern_plains', 3, 'cc by', 'Cover cropping is considered a cornerstone practice in sustainable agriculture; however, little attention has been paid to the cover crop production supply chain. In this Perspective, we estimate land use requirements to supply the United States maize production area with cover crop seed, finding that across 18 cover crops, on average 3.8% (median 2.0%) of current production area would be required, with the popular cover crops rye and hairy vetch requiring as much as 4.5% and 11.9%, respectively. The latter land requirement is comparable to the annual amount of maize grain lost to disease in the U.S. We highlight avenues for reducing these high land use costs.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7edae91b-ec49-4dcf-aa7f-6069cb53ee7e', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The Impact of Ellagitannins and Their Metabolites through Gut Microbiome on the Gut Health and Brain Wellness within the Gut-Brain Axis', 'Banc R, Rusu ME, Filip L, Popa DS', 2023, 'Foods (Basel, Switzerland)', '10.3390/foods12020270', 'https://doi.org/10.3390/foods12020270', 'https://europepmc.org/articles/PMC9858309?pdf=render', NULL, NULL, 41, NULL, 'other', 1, 'cc by', 'Ellagitannins (ETs) are a large group of bioactive compounds found in plant-source foods, such as pomegranates, berries, and nuts. The consumption of ETs has often been associated with positive effects on many pathologies, including cardiovascular diseases, neurodegenerative syndromes, and cancer. Although multiple biological activities (antioxidant, anti-inflammatory, chemopreventive) have been discussed for ETs, their limited bioavailability prevents reaching significant concentrations in systemic circulation. Instead, urolithins, ET gut microbiota-derived metabolites, are better absorbed and could be the bioactive molecules responsible for the antioxidant and anti-inflammatory activities or anti-tumor cell progression. In this review, we examined the dietary sources, metabolism, and bioavailability of ETs, and analyzed the last recent findings on ETs, ellagic acid, and urolithins, their intestinal and brain activities, the potential mechanisms of action, and the connection between the ET microbiota metabolism and the consequences detected on the gut-brain axis. The current in vitro, in vivo, and clinical studies indicate that ET-rich foods, individual gut microbiomes, or urolithin types could modulate signaling pathways and promote beneficial health effects. A better understanding of the role of these metabolites in disease pathogenesis may assist in the prevention or treatment of pathologies targeting the gut-brain axis.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('399aba13-248f-4b16-b30a-8961e9ff3cbe', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The importance of species selection in cover crop mixture design', 'Andrew McKenzie‐Gopsill, Aaron A. S. Mills, Ashley Nicolle MacDonald, Sylvia Wyand', 2022, 'Weed Science', '10.1017/wsc.2022.28', 'https://doi.org/10.1017/wsc.2022.28', 'https://www.cambridge.org/core/services/aop-cambridge-core/content/view/EBDAE1B3F1AEECF43A3F800B9579CBFE/S0043174522000285a.pdf/div-class-title-the-importance-of-species-selection-in-cover-crop-mixture-design-div.pdf', NULL, NULL, 12, NULL, 'canada', 3, 'cc-by', 'Abstract Cover crops are increasingly being included in crop rotations as a mechanism to promote diversity and provide agroecosystem services, including weed suppression. Recently, cover crop mixtures have increased in popularity in an attempt to provide a greater diversity in ecological services as compared with monocultures. Several recent studies, however, have failed to detect a positive effect of cover crop diversity on biomass production or weed suppression. Here we assessed biomass productivity and weed suppression in 19 cover crops seeded as monocultures and 19 mixtures of varying species composition and functional richness (two- and three-species mixtures) of full-season cover crops in Atlantic Canada. Cover crop biomass production and weed suppression varied by species identity, functional diversity, and species richness. As cover crop biomass increased regardless of diversity, weed biomass declined. Highly productive forbs and grasses provided the greatest weed suppression in monoculture. In line with previous observations, mixtures were not more productive or weed suppressive on average than the most productive monocultures. We observed that the inclusion of the highly productive species buckwheat (Fagopyrum esculentum Moench) and sorghum–sudangrass [Sorghum × drummondi (Nees ex Steud.) Millsp. & Chase] in a mixture increased stand evenness, productivity, weed suppression, and spatiotemporal stability. Taken together, our results suggest that effects of diversity on mixture productivity and weed suppression are species specific. This further demonstrates the importance of species selection in cover crop mixture design.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c43a3f77-8b9f-49a4-985d-8f5477f0d8bf', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'THE NATURE OF COPPER, ZINC AND BORON IN PRAIRIE SOILS AND CROP RESPONSES TO FERTILIZATION', 'Md. Noabur Rahman', 2019, 'HARVEST (University of Saskatchewan)', NULL, 'http://hdl.handle.net/10388/12078', 'https://harvest.usask.ca/bitstreams/eb8500f8-6de6-4f8a-a45d-bf48f616af9e/download', NULL, NULL, 255, NULL, 'prairies', 4, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf4ef444-bfb1-43d7-bdd3-d9ef3a3c8685', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The Role of Nanoparticles in Response of Plants to Abiotic Stress at Physiological, Biochemical, and Molecular Levels', 'Al-Khayri JM, Rashmi R, Surya Ulhas R, Sudheer WN, Banadka A, Nagella P, Aldaej MI, Rezk AA', 2023, 'Plants (Basel, Switzerland)', '10.3390/plants12020292', 'https://doi.org/10.3390/plants12020292', 'https://europepmc.org/articles/PMC9865530?pdf=render', NULL, NULL, 26, NULL, 'other', 1, 'cc by', 'In recent years, the global agricultural system has been unfavorably impacted by adverse environmental changes. These changes in the climate, in turn, have altered the abiotic conditions of plants, affecting plant growth, physiology and production. Abiotic stress in plants is one of the main obstacles to global agricultural production and food security. Therefore, there is a need for the development of novel approaches to overcome these problems and achieve sustainability. Nanotechnology has emerged as one such novel approach to improve crop production, through the utilization of nanoscale products, such as nanofertilizer, nanofungicides, nanoherbicides and nanopesticides. Their ability to cross cellular barriers makes nanoparticles suitable for their application in agriculture. Since they are easily soluble, smaller, and effective for uptake by plants, nanoparticles are widely used as a modern agricultural tool. The implementation of nanoparticles has been found to be effective in improving the qualitative and quantitative aspects of crop production under various biotic and abiotic stress conditions. This review discusses various abiotic stresses to which plants are susceptible and highlights the importance of the application of nanoparticles in combating abiotic stress, in addition to the major physiological, biochemical and molecular-induced changes that can help plants tolerate stress conditions. It also addresses the potential environmental and health impacts as a result of the extensive use of nanoparticles.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('204134ff-ee9d-483e-b617-f383fea25968', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'The role of plant growth promoting rhizobacteria in plant drought stress responses', 'Chieb M, Gachomo EW', 2023, 'BMC plant biology', '10.1186/s12870-023-04403-8', 'https://doi.org/10.1186/s12870-023-04403-8', 'https://europepmc.org/articles/PMC10464363?pdf=render', NULL, NULL, 23, NULL, 'other', 1, 'cc by', 'Climate change has exacerbated the effects of abiotic stresses on plant growth and productivity. Drought is one of the most important abiotic stress factors that interfere with plant growth and development. Plant selection and breeding as well as genetic engineering methods used to improve crop drought tolerance are expensive and time consuming. Plants use a myriad of adaptative mechanisms to cope with the adverse effects of drought stress including the association with beneficial microorganisms such as plant growth promoting rhizobacteria (PGPR). Inoculation of plant roots with different PGPR species has been shown to promote drought tolerance through a variety of interconnected physiological, biochemical, molecular, nutritional, metabolic, and cellular processes, which include enhanced plant growth, root elongation, phytohormone production or inhibition, and production of volatile organic compounds. Therefore, plant colonization by PGPR is an eco-friendly agricultural method to improve plant growth and productivity. Notably, the processes regulated and enhanced by PGPR can promote plant growth as well as enhance drought tolerance. This review addresses the current knowledge on how drought stress affects plant growth and development and describes how PGPR can trigger plant drought stress responses at the physiological, morphological, and molecular levels.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('24e43237-fd4c-4155-ae46-13001e871714', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Tillage intensity and crop rotation affect weed community dynamics in a winter wheat cropping system', 'Robert E. Blackshaw, Francis J. Larney, C. W. Lindwall, Paris R. Watson, Doug A. Derksen', 2001, 'Canadian Journal of Plant Science', '10.4141/p01-023', 'https://doi.org/10.4141/p01-023', 'https://cdnsciencepub.com/doi/pdf/10.4141/P01-023', NULL, NULL, NULL, NULL, 'southern_alberta', 5, NULL, NULL, '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6b830f16-149a-4606-9cc1-5165644f0b7e', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Toxicity across food webs: effects of karanja oil on greenhouse whitefly on tomato and two commercial biocontrol agents', 'Cabra-Arias C, Carrillo J', 2026, 'Frontiers in insect science', '10.3389/finsc.2026.1711812', 'https://doi.org/10.3389/finsc.2026.1711812', 'https://europepmc.org/articles/PMC12914566?pdf=render', NULL, NULL, 13, NULL, 'canada', 3, 'cc by', 'Integrated pest management programs often incorporate insect natural enemies for biological control alongside the application of pesticides. However, pesticides can directly affect the survival and performance of beneficial predaceous insects, decreasing their efficacy. Conversely, pesticides may also increase the susceptibility of insect pests to biological control, promoting the predatory performance of their natural enemies. Pest management can be improved by understanding the ecological interaction among plants, pests, and predators, as well as the influence of pesticide application on higher trophic levels. We conducted bioassays on tomato plants (Solanum lycopersicum L.) to evaluate the effects of karanja oil, a presumed insecticidal botanical extract obtained from the seeds of the tree Pongamia pinnata L, on the greenhouse whitefly Trialeurodes vaporariorum (Westwood) and two of its natural enemies: the parasitic wasp Encarsia formosa (Gahan) and the lady beetle Delphastus catalinae (Horn). Our findings revealed a strong negative correlation between increasing concentrations of karanja oil and the survival of both adult and nymphal stages of greenhouse whiteflies. In whole plant trials, the highest concentration of karanja oil solution (5% v/v%) killed 80% of the whitefly adults and 84% of nymphs, while the lowest concentration (1.25% v/v%) killed 45% of adults and 53% of nymphs. Karanja oil also exhibited a residual negative effect on immature whiteflies and did not affect the parasitism rate of E. formosa. The direct application of karanja oil to non-pest predators and parasitoids was lethal, indicating that in integrated pest management programs for greenhouse whitefly in tomatoes, natural enemies should be introduced after the application of botanical extracts or used exclusively without pesticides.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('237f1e28-1164-41b7-be0e-fc9ee518fd61', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Traditional Foods From Maize (Zea mays L.) in Europe', 'Revilla P, Alves ML, Andelković V, Balconi C, Dinis I, Mendes-Moreira P, Redaelli R, Ruiz de Galarreta JI', 2021, 'Frontiers in nutrition', '10.3389/fnut.2021.683399', 'https://doi.org/10.3389/fnut.2021.683399', 'https://europepmc.org/articles/PMC8780548?pdf=render', NULL, NULL, 17, NULL, 'other', 1, 'cc by', 'Maize (Zea mays L.) is one of the major crops of the world for feed, food, and industrial uses. It was originated in Central America and introduced into Europe and other continents after Columbus trips at the end of the 15th century. Due to the large adaptability of maize, farmers have originated a wide variability of genetic resources with wide diversity of adaptation, characteristics, and uses. Nowadays, in Europe, maize is mainly used for feed, but several food specialties were originated during these five centuries of maize history and became traditional food specialties. This review summarizes the state of the art of traditional foodstuffs made with maize in Southern, South-Western and South-Eastern Europe, from an historic evolution to the last research activities that focus on improving sustainability, quality and safety of food production.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('4149216e-1295-476d-a022-2a0e48ab172e', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Trap cropping for insect pests in the Canadian Prairies: a review and a case study', 'Héctor A. Cárcamo, James A. Tansey, Brian L. Beres, Haley A. Catton, Breanne D. Tidemann, Peter E. Reid, Meghan A. Vankosky', 2024, 'Arthropod-Plant Interactions', '10.1007/s11829-024-10103-3', 'https://doi.org/10.1007/s11829-024-10103-3', 'https://link.springer.com/content/pdf/10.1007/s11829-024-10103-3.pdf', NULL, NULL, 18, NULL, 'southern_alberta', 5, 'cc-by', 'Abstract The Canadian Prairies are one of the major agricultural regions of the world in terms of cereal, oilseed and pulse crop production. With few exceptions, major insect pests like grasshoppers, flea beetles, Lygus bugs, wireworms and pea leaf weevils are controlled with insecticides. Wheat stem sawfly is managed through host plant resistance and endemic natural enemies, whereas cereal leaf beetle is managed through classical biological control. Large farms and short growing seasons in the region present logistical challenges to adopt time intensive pest management systems such as trap crops. Therefore, there is no adoption of trap crops even though some research has demonstrated their potential. In this article we present a brief overview of the pest status and management, and we summarize research on trap crops in the Prairies Ecozone and adjacent ecoregions. We conclude the review with some innovative research ideas to make trap cropping a more appealing pest management system in our quest to reduce dependency on chemical insecticides and increase the environmental resilience of Canadian agroecosystems.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b533841d-cdf3-4af1-8391-6d84010f2350', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Unraveling the Initial Plant Hormone Signaling, Metabolic Mechanisms and Plant Defense Triggering the Endomycorrhizal Symbiosis Behavior', 'Bedini A, Mercy L, Schneider C, Franken P, Lucic-Mercy E', 2018, 'Frontiers in plant science', '10.3389/fpls.2018.01800', 'https://doi.org/10.3389/fpls.2018.01800', 'https://europepmc.org/articles/PMC6304697?pdf=render', NULL, NULL, 28, NULL, 'other', 1, 'cc by', 'Arbuscular mycorrhizal (AM) fungi establish probably one of the oldest mutualistic relationships with the roots of most plants on earth. The wide distribution of these fungi in almost all soil ecotypes and the broad range of host plant species demonstrate their strong plasticity to cope with various environmental conditions. AM fungi elaborate fine-tuned molecular interactions with plants that determine their spread within root cortical tissues. Interactions with endomycorrhizal fungi can bring various benefits to plants, such as improved nutritional status, higher photosynthesis, protection against biotic and abiotic stresses based on regulation of many physiological processes which participate in promoting plant performances. In turn, host plants provide a specific habitat as physical support and a favorable metabolic frame, allowing uptake and assimilation of compounds required for the life cycle completion of these obligate biotrophic fungi. The search for formal and direct evidences of fungal energetic needs raised strong motivated projects since decades, but the impossibility to produce AM fungi under axenic conditions remains a deep enigma and still feeds numerous debates. Here, we review and discuss the initial favorable and non-favorable metabolic plant context that may fate the mycorrhizal behavior, with a focus on hormone interplays and their links with mitochondrial respiration, carbon partitioning and plant defense system, structured according to the action of phosphorus as a main limiting factor for mycorrhizal symbiosis. Then, we provide with models and discuss their significances to propose metabolic targets that could allow to develop innovations for the production and application of AM fungal inocula.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('7605a255-2b16-46c9-9af4-bae35f79b399', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'We stand on guard for thee: A brief history of pest surveillance on the Canadian Prairies', 'BRENT D. McCALLUM, Charles M. Geddes, Syama Chatterton, Gary Peng, Odile Carisse, Thomas Kelly Turkington, O. Olfert, Julia Y. Leeson', 2021, 'Crop Protection', '10.1016/j.cropro.2021.105748', 'https://doi.org/10.1016/j.cropro.2021.105748', 'https://www.sciencedirect.com/science/article/pii/S0261219421002180/pdf', NULL, NULL, NULL, NULL, 'southern_alberta', 5, 'cc-by-nc-nd', 'Crop production had dominated the Canadian Prairies for the past century, and has been constantly challenged by various pathogens, insects, and weeds. An effective biovigilance program to manage these crop pests requires continuous, timely, and detailed pest surveillance, to understand how pest populations are changing over time. Many of these pests have been managed through surveillance and various mitigation strategies, combined with follow-up analyses. Pest surveillance activities have been documented in the Canadian Prairies for over 100 years and analysis has progressed from determining the pest species involved, to understanding the damage they cause, their biology, spread, over-wintering strategies, reproduction, pesticide resistance, and genetic diversity. This research has generated a continuous history of the pest populations for crops in western Canada. Detailed virulence analysis has revealed pathogen evolution and adaptation to overcome some of the deployed host resistance genes. Some weed, insect, and plant pathogenic fungal species have evolved to become resistant to pesticides. Integration of pest surveillance activities will help to build a more responsive, robust, and reliable biovigilance program to manage crop pests in the Canadian Prairies.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('986f08f0-a722-462a-b5b5-667fd0fac786', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Weed Control with Cover Crops in Irrigated Potatoes', 'Grant H. Mehring, John E. Stenger, Harlene Hatterman‐Valenti', 2016, 'Agronomy', '10.3390/agronomy6010003', 'https://doi.org/10.3390/agronomy6010003', 'https://www.mdpi.com/2073-4395/6/1/3/pdf?version=1451997315', NULL, NULL, NULL, NULL, 'prairies', 4, 'cc-by', 'Field experiments at Oakes, ND, USA in 2010 and Carrington, ND, USA in 2011 were conducted to evaluate the potential for cover crops grown in the Northern Great Plains, USA in order to reduce weed emergence and density in irrigated potatoes. Treatments included five cover crop treatments and three cover crop termination treatments. Termination of cover crops was done with glyphosate, disk-till, and roto-till. Cover crop biomass accumulation was greatest for rye/canola and triticale at Oakes, and hairy vetch and hairy vetch/rye at Carrington. Cover crop and termination affected weed control 14, 29, and 51 days after planting (DAP) at Oakes. Weed control at Carrington was at least 90% for all cover crop and termination treatments at all three evaluation timings. Marketable yield at Oakes was greater when roto-till was used to terminate the cover crops compared with disk-till or herbicide, which is beneficial for organic systems where herbicides are not used. Marketable yield at Carrington was not affected by cover crop or termination treatments. Results suggest that cover crops can successfully be integrated into irrigated potato production for weed control with yields equal to no cover crop, and with attention to potential mechanical difficulties.', '{openalex,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('79b7436b-fcc5-46e2-8b17-23a4b0c96857', 'e4d9bd04-653e-4555-8961-d17d52149cfc', 'Yields of Buckwheat and Alfalfa in an Intercropping System Inoculated with Dark Septate Endophytes in a Coal Mining Subsidence Dryland Area', 'Yakun Gao, Yinli Bi, Shaopeng Ma, Yanxu Zhang, Yun Guo, Yang Zhou, Shihao Xu, Peter Christie', 2022, 'Agronomy', '10.3390/agronomy12112860', 'https://doi.org/10.3390/agronomy12112860', 'https://www.mdpi.com/2073-4395/12/11/2860', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Coal mining subsidence areas in north Shaanxi province in north China are commonly low-fertility drylands, and intercropping is a popular method locally of maximizing crop yields. Inoculation with dark septate endophytes (DSE) can increase the yields of conventional crops grown in monoculture, but the effects of DSE on the growth and yield of intercropped plants are unknown. Here, a field experiment was conducted in a coal mining subsidence area on the loess plateau in 2020 and 2021. The two crops were buckwheat and alfalfa, with four treatments for each crop: sole cropping control, sole cropping with DSE inoculation, intercropping control, and intercropping with DSE inoculation. The yields, land equivalent ratios, DSE colonization rates, and yield components of buckwheat and alfalfa were compared in the different treatments. Stepwise regression and path analysis was conducted to identify the factors that determined crop yields. Yields of intercropped buckwheat and alfalfa with DSE inoculation increased in two consecutive years compared with sole cropping control, with yields increasing in 2020 by 117 and 86%, respectively. In 2021, the yield of buckwheat in intercropping with DSE inoculation did not increase significantly, but the yield of alfalfa increased by 120% compared with the sole cropping control. Buckwheat-alfalfa intercropping has the advantage of increasing the yield. DSE inoculation significantly increased the yield of buckwheat-alfalfa intercropping in 2020, but there was no yield advantage in 2021. The yield components of buckwheat and alfalfa showed inconsistent differences among experimental treatments. Stepwise regression and path analysis shows that the DSE colonization rate played an important role in the yield, which was an increased in buckwheat and alfalfa in 2020 and 2021. DSE affected the buckwheat yield indirectly by increasing the grain weight per plant, plant phosphorus uptake, and plant nitrogen content. DSE indirectly affected alfalfa yields by increasing plant nitrogen uptake and plant height. DSE may therefore have some potential to increase yields in buckwheat-alfalfa intercropping systems in coal mining subsidence areas.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('69646a30-5af1-412d-8455-3f1224afa1d2', '9cb41128-a672-4e16-a128-a17adc65c5cb', '"Making a comeback" : blackleg on canola', 'Government of Alberta', 2013, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/making-a-comback-blackleg-on-canola', 'https://open.alberta.ca/dataset/8e2a14e8-f5e2-4066-8c99-79444a3fff44/resource/f76887dd-cde4-4c7f-a622-2dcc9a4cc9db/download/blackleg-on-canola.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This information sheet discusses the return of blackleg as a threat to canola crops. Blackleg is a disease of the cabbage family which had a significant impact on canola crops in the province in the 1980s and 1990s. The fact sheet provides some "quick facts" about blackleg and what steps can be taken to mitigate the spread and impact of the disease on canola crops.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b2c89871-a5b8-46c1-b606-0b5f3fe84b18', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'A consensus of costs and returns for peas, barley, canola, wheat and oats in the Lamont and Andrew Districts', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/consensus-of-costs-and-returns-peas-barley-canola-wheat-oats-in-lamont-and-andrew-districts', 'https://open.alberta.ca/dataset/79556564-8e64-4482-9719-dcd45a74d142/resource/d61bb1f1-ef48-4f4b-b9aa-f86ff34b9d01/download/0163010021620-consensus-costs-returns-peas-barley-canola-wheat-oats-lamont-andrew.pdf', NULL, NULL, 26, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This report provides an estimate of the costs and returns for growing peas, barley, canola, wheat, and oats in the Lamont and Andrew Districts of Alberta. It utilizes a Consensus Research Data (C.R.D.) technique, gathering information from local farmers regarding machinery, cultural practices, and associated expenses. The report defines key financial metrics such as variable, fixed, total cash, and total costs per acre, along with gross revenue, gross margin, and return to investment and management. This information helps farmers with management decisions, including enterprise selection, cash flow planning, and evaluating new investments.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('64dbb8e1-c21e-422e-94c4-eb5960529d84', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'A molecular approach for increasing oil content in canola', 'Government of Alberta', 1995, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/molecular-approach-for-increasing-oil-content-in-canola', 'https://open.alberta.ca/dataset/50fe46f2-ea2e-4cc9-abc7-e21c9b616b2d/resource/484eaf47-163f-4f90-8078-7b08b01dc171/download/0163210415028-a-molecular-approach-for-increasing-oil-content-in-canola.pdf', NULL, NULL, 112, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This research project focused on increasing canola seed oil content by isolating and characterizing key enzymes involved in the oil formation pathway, including phosphatidate (PA) phosphatase and diacylglycerol acyltransferase (DGAT). The enzymes were solubilized from microsperms of canola and characterized through differential centrifugation, gel filtration chromatography, and activity assays. DGAT showed maximal activity during rapid oil accumulation and responded to specific chemical stimuli, suggesting its regulatory role. Additional analysis involving radiolabeled analogs and differential gene expression revealed potential strategies for enzyme purification and gene identification. The project partially fulfilled its objectives and informed new initiatives addressed in another Farming for the Future Project.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('db75d143-b762-4da3-a8f3-6f3ef1070e44', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'A target enzyme for increasing oil content in oilseed rape', 'Government of Alberta', 1994, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/target-enzyme-for-increasing-oil-content-in-oilseed-rape', 'https://open.alberta.ca/dataset/aa5bc00f-56ce-4f33-94bf-fe8087329eeb/resource/03139b0f-5d2f-440f-a79a-5a63c22ce2ac/download/0163003023773-a-target-enzyme-for-increasing-oil-content-in-oilseed-rape.pdf', NULL, NULL, 138, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document examined diacylglycerol acyltransferase (DGAT) as a target enzyme for increasing oil content in oilseed rape. It described the problem context, objectives, and scope of purifying and partially characterizing DGAT from microspore-derived cultures and developing seeds of Brassica napus. It documented experimental methods including enzyme solubilization, partial purification, photoaffinity labeling, lipid analysis, immunological approaches, and developmental studies of DGAT activity. It presented results relating DGAT activity to triacylglycerol biosynthesis and seed oil accumulation, and it assessed progress toward identifying a complementary deoxyribonucleic acid (cDNA) clone encoding DGAT. This document concluded with implications for Alberta''s agricultural industry and agricultural knowledge, and it outlined future research directions.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('bf8ceca9-b726-4cb8-a915-675402326232', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Advances in Pulse and Oil Seed Industry Coproduct-Derived Sustainable Food Packaging: Biopolymers, Additives, Processing Technologies, and Functional Applications', 'Dissanayake T, Abeysinghe V, Chairez-Jimenez C, Ravichandran S, Bandara N', 2026, 'Comprehensive reviews in food science and food safety', '10.1111/1541-4337.70583', 'https://doi.org/10.1111/1541-4337.70583', 'https://europepmc.org/articles/PMC13402766?pdf=render', NULL, NULL, 20, NULL, 'prairies', 4, 'cc by-nc-nd', 'The demand for sustainable, functional food packaging from agricultural coproducts such as hulls, meals, fibers, gums, and press residues from pulse and oilseed industries is increasing. These secondary streams from crops such as soybean, canola, hemp, sunflower, lentils, peas, beans, and chickpeas are rich in proteins, polysaccharides, lignin, and bioactive compounds, making them promising sources for biopolymers and functional additives. The objective of this review is to discuss the potential of pulse and oilseed coproducts for biodegradable and active packaging, highlight the impact of extraction, modification, and fabrication techniques, examine packaging functionality reported in the literature, and identify research gaps. The literature indicates a need for systematic studies correlating coproduct composition with functional performance and sustainable modification strategies. Protein, polysaccharides, and cellulose fibers can be tailored to produce films, coatings, and molded packaging structures with desirable mechanical, thermal, and barrier properties. Additives from coproducts, including natural plasticizers, nanocellulose reinforcements, antioxidants, emulsifiers, and antimicrobials, enhance packaging performance and enable the development of active, edible, and smart packaging systems. Fabrication methods, such as solvent casting, extrusion, injection molding, compression molding, blow molding, electrospinning, and 3D printing, enable the customization of packaging properties and structures based on the final application. Despite these advancements, challenges remain in industrial adoption, inconsistency in results between published literature, compatibility issues between additives and polymer matrices, high purification costs, and scalability constraints. Effective utilization of agricultural coproducts supports circular bioeconomy principles, reduces reliance on petroleum-based plastics, and paves the way for next-generation, eco-friendly food packaging solutions.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('3e60421e-4311-4717-ac16-01c29d1c4751', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'AI-driven advances in plant biotechnology: sharpening the edge of plant tissue culture and genome editing', 'Narra M, Ray A, Polley B, Yang H, Bhowmik PK', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1718810', 'https://doi.org/10.3389/fpls.2025.1718810', 'https://europepmc.org/articles/PMC12727986?pdf=render', NULL, NULL, 34, NULL, 'prairies', 4, 'cc by', 'The advent of artificial intelligence (AI) holds great promise for revolutionizing the fields of plant tissue culture and genome editing. Plant tissue culture is recognized as a powerful tool for rapid multiplication and crop improvement. However, the complex interactions between genetic and environmental factors generate large volumes of data, posing challenges for traditional statistical analysis methods. To address this, researchers are now employing machine learning (ML)-based and artificial neural networks (ANN) approaches to predict and optimize in vitro culture protocols thereby improving precision, sustainability, and efficiency. Integrating AI technologies such as machine learning (ML), artificial neural networks (ANN), and deep learning (DL) can significantly advance the development of data-driven models for CRISPR/Cas9 genome editing. Today, AI-driven methods are routinely applied to enhance precision in predicting on- and off-target sequence locations and editing outcomes. Additionally, predicting protein structures can provide a directed evolution framework that facilitates the creation of improved gene editing tools. However, the application of AI-based CRISPR modeling in plants is not yet fully explored. In this context, we aim to examine representative ML/DL/ANN models of CRISPR/Cas based editing employed in various organisms. This review significantly compiles a diverse set of studies and provides a clear overview of how AI is transforming the fields of plant tissue culture and genome editing. It emphasizes AI''s potential to increase the efficiency and precision of biotechnological practices, making them more accessible and cost-effective. While outlining current findings, the paper sets the stage for future research, encouraging further exploration into the integration of AI with plant biotechnology.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('644db202-6053-4136-90fc-9352b200c7ac', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Alberta canola [2026]', 'Government of Alberta', 2026, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/alberta-canola', 'https://open.alberta.ca/dataset/672b08be-090e-4959-b17b-4137fbf47e07/resource/dcf1ea77-5697-4f72-bedd-8a585e1d1fbb/download/agi-alberta-canola-2026.pdf', NULL, NULL, 7, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Alberta is one of Canada’s key canola exporters. This promotional brochure highlights the attributes of canola and Alberta''s canola supply.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('16e06f81-8936-460c-afbb-62b47a05ef77', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'All roads lead to Rome: QTL analysis for vernalization requirement and dissection of allelic variation uncovered unexpected diversity of FLC loci in Camelina sativa', 'Roslinsky V, Chaudhary R, Zatylny A, Parkin IAP, Eynck C', 2025, 'Frontiers in plant science', '10.3389/fpls.2025.1639872', 'https://doi.org/10.3389/fpls.2025.1639872', 'https://europepmc.org/articles/PMC12331742?pdf=render', NULL, NULL, 32, NULL, 'prairies', 4, 'cc by', 'Winter camelina (Camelina sativa) is a climate-resilient oilseed crop that has received attention as a feedstock crop for advanced, low-carbon-intensity biofuels. Breeding programs working on winter camelina improvement have to contend with heterogeneous germplasm, oftentimes erroneously identified as winter biotypes, and a gene pool that is much smaller than that of spring-type camelina, the latter having motivated crosses between winter and spring biotypes. For the unequivocal differentiation of winter from spring types at an early stage, breeders require a tool to track the vernalization requirement trait in segregating breeding populations as well as in putative winter cultivars, breeding lines, and accessions to be used as parental lines. Linkage mapping in a winter (''Joelle'') × spring (''SES0787LS'') C. sativa biparental F2 population identified two major quantitative trait loci (QTLs) for vernalization requirement on chromosomes 8 and 13. Both regions contained orthologs of Flowering Locus C (FLC), a gene known to have a significant effect on flowering time and vernalization requirement in plants. Based on the FLC gene sequences, allele-specific PCR-based markers were developed, suitable for the routine screening of C. sativa germplasm for the presence of the winter and spring alleles of all three C. sativa FLC orthologs, including a chromosome 20 locus. The analysis of the winter cultivar ''Joelle'' and a diverse C. sativa germplasm panel uncovered greater than expected variability for the FLC alleles, with most lines possessing several different allele combinations and still undergoing genetic segregation. Contrary to previous reports, spring camelina lines can carry the spring and/or winter alleles of Csa.FLC.C20, indicating that this gene by itself only plays a subordinate role in the regulation of flowering and vernalization requirement. In winter C. sativa germplasm, combinations of Csa.FLC.C08 winter alleles with the winter alleles of one or both of Csa.FLC.C13 and Csa.FLC.C20 result in vernalization requirement, while winter Csa.FLC.C08 by itself leads to a semi-winter type. The results of this study and the tools developed herein are a first step to orchestrating the genes underlying vernalization requirement in C. sativa and developing winter camelina cultivars optimized for different winter environments.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d38864a4-8dc5-48eb-965d-11b986b84ace', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Alternative date seeding of spring canola', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2406234', 'https://open.alberta.ca/dataset/3791fbfa-1e25-4831-b5a7-25b40ccb5490/resource/fac6e0d2-9f7b-4ab5-8bdc-7f8aea5da9ec/download/2000-149-22-1.pdf', NULL, NULL, 5, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Seeding canola very early in the spring or before fall freeze up has several advantages. It spreads out farming operations. It may also minimize the impact of devastating diseases, insects, frosts or periods of extreme heat. These seeding dates also advance maturity and harvest. Alternative date seeding, however, requires careful management. Studies and practical experience on these seeding concepts have led to the recommendations in this fact sheet.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('51af0871-75b4-4b97-a6ed-82e81d5b28ca', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'An evaluation of the N2O emission reduction potential of enhanced efficiency nitrogen fertilizers and application timing in a semi-arid cereal cropping system', 'Daly E, Ogilvie C, Lemke RL, Farrell RE', 2026, 'Journal of environmental quality', '10.1002/jeq2.70251', 'https://doi.org/10.1002/jeq2.70251', 'https://europepmc.org/articles/PMC13550706?pdf=render', NULL, NULL, 17, NULL, 'prairies', 4, 'cc by', 'Efforts to cut fertilizer-related nitrous oxide (N2O) emissions require sustainable nitrogen (N) management that maintains crop productivity while reducing emissions. Technologies such as enhanced efficiency N fertilizers (EENFs) have potential to support best management practices by improving N use efficiency and lowering N2O emissions. This study (i) evaluated the effects of spring versus fall application of conventional urea and EENFs, including a polymer-coated urea (PCU; ESN), a nitrification inhibitor (NI; eNtrench), a dual urease inhibitor (Limus), and a urease and nitrification inhibitor (UNI; SuperU), on N2O emissions from spring wheat over two growing seasons in central Saskatchewan and (ii) compared soil nutrient supply rates among conventional urea and the EENFs to determine whether soil N dynamics reflected their differing modes of action. Results indicate that significant N2O emissions reductions can be achieved in rainfed cropping systems by using a urea-based EENF without crop yield penalties. In general, the greatest emissions reductions were achieved using EENF products that employ an NI; both the NI and the UNI reduced annual cumulative N2O emissions relative to urea by 8%-54% and 36%-64%, respectively (p 2O emissions relative to urea. Across all treatments, spring N fertilizer applications led to the greatest N2O emissions reductions with EENFs compared to fall N fertilizer applications. Overall, NI-based EENFs show potential for reducing N2O emissions while maintaining wheat yields in Saskatchewan.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b7c2f3f5-b6a3-4ffc-b1d8-a313a02d6fa2', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Artificial Attractants: Implications for Disease Management in Deer', 'Gritter K, Pybus M, Lewis MA, Merrill E', 2025, 'Ecology and evolution', '10.1002/ece3.71013', 'https://doi.org/10.1002/ece3.71013', 'https://europepmc.org/articles/PMC11840243?pdf=render', NULL, NULL, 11, NULL, 'alberta', 4, 'cc by', 'Chronic wasting disease (CWD) is a prion disease that infects cervid species by direct and environmental transmission and is invariably fatal. CWD spread can be promoted by the attraction of animals to "hotspots" such as hay bales and grain bags stored in fields and at farm sites. The density and location of hotspots may impact contact rates. We used an individual-based movement model of mule deer (Odocoileus hemionus) to investigate the effects of density and configuration of hotspots (hereafter artificial attractants, AA) on contact rates at a constant density of 1 deer/km2 during winter. The model tracks when two deer from the same or different groups come into contact under 6 AA densities (0-1 AA/km2) and 6 AA configurations. We compared placing AA randomly versus clustered around farms, and removing them randomly versus biased by proximity to preferred habitat. Overall, the number of unique contacts per individual and the number of unique deer visiting an AA increased, and the number of AAs used by each deer decreased as AA density declined. Selectively removing field attractants near preferred habitat resulted in a larger increase in contacts per deer, with deer contacting more and different individuals, fewer deer using the remaining AA, and fewer visits per AA than random removal. There was a greater increase in contact rates when reducing AA density at farms by randomly removing all AA at a farm compared to randomly removing individual AA across farms. Deer responses to AA removal may not be as straightforward as originally believed. Deer contacts may increase, not decrease, with AA removal because deer are attracted to the remaining AA. Under moderate deer densities, AA removal may require a broad-scale, "all or nothing" approach to prevent deer from concentrating at remaining AA, but concomitantly lowering deer density needs further assessment.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('35c9ff64-a055-412e-b449-7406335ef063', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Automatic Microplot Localization Using UAV Images and a Hierarchical Image-Based Optimization Method', 'Mardanisamani S, Ayalew TW, Badhon MA, Khan NA, Hasnat G, Duddu H, Shirtliffe S, Vail S', 2021, 'Plant phenomics (Washington, D.C.)', '10.34133/2021/9764514', 'https://doi.org/10.34133/2021/9764514', 'https://europepmc.org/articles/PMC8678615?pdf=render', NULL, NULL, 16, NULL, 'prairies', 4, 'cc by', 'To develop new crop varieties and monitor plant growth, health, and traits, automated analysis of aerial crop images is an attractive alternative to time-consuming manual inspection. To perform per-microplot phenotypic analysis, localizing and detecting individual microplots in an orthomosaic image of a field are major steps. Our algorithm uses an automatic initialization of the known field layout over the orthomosaic images in roughly the right position. Since the orthomosaic images are stitched from a large number of smaller images, there can be distortion causing microplot rows not to be entirely straight and the automatic initialization to not correctly position every microplot. To overcome this, we have developed a three-level hierarchical optimization method. First, the initial bounding box position is optimized using an objective function that maximizes the level of vegetation inside the area. Then, columns of microplots are repositioned, constrained by their expected spacing. Finally, the position of microplots is adjusted individually using an objective function that simultaneously maximizes the area of the microplot overlapping vegetation, minimizes spacing variance between microplots, and maximizes each microplot''s alignment relative to other microplots in the same row and column. The orthomosaics used in this study were obtained from multiple dates of canola and wheat breeding trials. The algorithm was able to detect 99.7% of microplots for canola and 99% for wheat. The automatically segmented microplots were compared to ground truth segmentations, resulting in an average DSC of 91.2% and 89.6% across all microplots and orthomosaics in the canola and wheat datasets.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('98b82978-b4b3-4426-afcb-eaa6b2858c3d', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Biological control of Lygus lineolaris infestations by Beauveria bassiana delvered by Apis mellifera to canola', 'Government of Alberta', 2000, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/biological-control-of-lygus-lineolaris-infestations-by-beauveria-bassiana-delvered-by-apis-mell', 'https://open.alberta.ca/dataset/e5e9b72d-a98f-4dc4-a6fb-de79f4b5ef8e/resource/26ca2f26-3094-46e6-a924-4da51a0e3a05/download/0163010201487-biological-control-lygus-lineolaris-infestations-beauveria-bassiana-delvered-apis.pdf', NULL, NULL, 64, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Researchers at the University of Guelph and Agriculture and Agri-Food Canada conducted a study using Apis mellifera to deliver Beauveria bassiana to canola flowers to control Lygus lineolaris. They developed a method to dilute and dispense the fungus through hive dispensers. Lab and cage experiments showed the fungus killed nymph-stage pests effectively with minimal harm to honeybees. Results suggest this method could reduce pesticide use, boost pollination, and improve crop yield.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('d448d55a-6f4f-4b67-9ac0-55f240d28eb6', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Biology and control of the cabbage seedpod weevil, a new pest of canola in Alberta', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/biology-and-control-of-the-cabbage-seedpod-weevil-a-new-pest-of-canola-in-alberta', 'https://open.alberta.ca/dataset/5af7dabb-6720-4a0c-8dee-82a081d9755b/resource/c4e6840e-efda-4ecb-a2d7-4a7342870b37/download/0163010382717-biology-and-control-of-the-cabbage-seedpod-weevil-a-new-pest-of-canola-in-alberta.pdf', NULL, NULL, 154, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document presented the research report on the biology, distribution, and control of the cabbage seedpod weevil (Ceutorhynchus obstrictus), a newly established and economically important pest of canola in Alberta. It documented the pest''s life cycle, host plant relationships, seasonal dynamics, and patterns of spread across southern and central Alberta, as well as into parts of western Canada. The report evaluated monitoring methods, varietal susceptibility, cultural practices, natural enemies, and the effectiveness of insecticides under field conditions. It provided evidence-based recommendations to support the development of an integrated pest management strategy for canola production in Alberta. The study highlighted the implications of this pest for crop yield, quality, and long-term industry sustainability.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b4a3f344-1220-4ef9-8ce5-a4a15c70e62a', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Blackleg of canola', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2306536', 'https://open.alberta.ca/dataset/21d4a6a7-6ab5-459a-9e95-146c147a25ff/resource/1f43feb8-dfbb-47bc-9056-b489990cd307/download/1997-149-632-3.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Virulent blackleg of canola/rapeseed is a fungal canker or dry rot disease of the actively growing crop that causes stem girdling and lodging. In heavily infested crops, up to 100 per cent of the stems may be infected, resulting in major yield loss. Two types of blackleg fungus infect canola - weakly virulent and virulent. The weakly virulent, or mild type, has always been common in canola fields. The disease appears on leaves and stems in August but does not usually cause significant damage.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('a341442c-fbe0-4e47-963e-7e51446796cf', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Blackleg of canola in Alberta : investigations on biology, epidemiology and management', 'Government of Alberta', 1993, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/blackleg-of-canola-in-alberta-investigations-on-biology-epidemiology-and-management', 'https://open.alberta.ca/dataset/56ecc3cc-964d-4ace-afd5-0f7903eff994/resource/d68a0704-141e-48a9-83f6-58fcb5916541/download/0163040079895-blackleg-canola-alberta-investigations-biology-epidemiology-management.pdf', NULL, NULL, 106, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document investigated the biology, epidemiology, and management of blackleg disease in canola, caused by the highly virulent strain of Leptosphaeria maculans (conidial state: Phoma lingam), which spread across Alberta since its first detection in 1983. Researchers found that infected seed and wind-borne ascospores were the main sources of disease, and that all commonly grown Brassica cultivars were highly susceptible, while some weeds developed resistance soon after emergence. Field trials showed that cultivars Cyclone and Legend provided better yield and resistance than Westar under heavy disease pressure, and that fungicidal seed treatments and foliar sprays, especially prochloraz, offered limited control depending on timing and disease severity. Biological control using Penicillium verrucosum and its metabolite citrinin inhibited the pathogen but was unsuitable due to nephrotoxicity.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('5798884a-a13a-47d3-bc07-4a384b83e1fe', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Blackleg of canola response plan', 'Government of Alberta', 1998, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/blackleg-of-canola-response-plan', 'https://open.alberta.ca/dataset/e138dbc8-3a9a-4e34-97f4-77c7933099e6/resource/fb197a1c-a318-4a4f-ba08-474a4840613b/download/0163010135495-blackleg-of-canola-response-plan.pdf', NULL, NULL, 61, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This 1998 document outlined Alberta''s coordinated response plan for managing virulent blackleg of canola, a serious fungal disease caused by Leptosphaeria maculans. It described the biology of the pathogen, pathways of disease spread, and the legislative framework under the Agricultural Pests Act that supports prevention and control measures. The plan detailed province wide survey programs, field inspection and sampling procedures, seed testing standards, and recommended management practices for both disease free and infested areas. It was prepared to guide municipal authorities, industry, and growers in preventing the introduction, spread, and economic impact of virulent blackleg in Alberta.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b19da20d-80ea-46c8-b504-7213eae03bf3', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Canola and direct seeding', 'Government of Alberta', 1996, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/canola-and-direct-seeding', 'https://open.alberta.ca/dataset/0615040f-e692-4590-83b9-3a00772272e8/resource/e909d4cf-0ee3-4abd-914f-7a44c704ccda/download/0163010119069-canola-and-direct-seeding.pdf', NULL, NULL, 46, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document presented a one year field study comparing direct seeding of canola with conventional seeding in two Alberta soil zones, examining weed control, plant growth, yield performance, soil moisture and economic returns. It evaluated multiple herbicide systems including fall applied granular Edge, post emergent Pursuit, Poast plus Muster, and a new Cyanamid herbicide (AC 299,263), and assessed their suitability for direct seeding systems. Results showed that direct seeding produced canola yields comparable to conventional tillage, that AC 299,263 performed well across sites, and that surface applied Edge was economically effective but less reliable for weed control in first year direct seeding. Economic analysis indicated varying cost effectiveness by cultivar, herbicide and tillage system.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('446dc53c-3638-4639-b6da-aa4e4435b518', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Canola co-products for feeding pigs', 'Government of Alberta', 2014, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/7199403', 'https://open.alberta.ca/dataset/dae2d311-6506-4b83-8795-56845e6737a9/resource/a0c2bd7a-ba4b-47ad-bba1-27f0df88cd80/download/2014-440-68-2.pdf', NULL, NULL, 3, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Canola cold-pressed, expeller-pressed or solvent extracted. What is the difference among these products, and why should it matter to pork producers? After more than 30 years, pork producers have become familiar with feeding conventional canola meal. But in recent years, new terms have emerged that refer to novel canola co-products for animal feeding. Producers may wonder what these terms mean and what the differences are among co-products. And for the bottom line, excellent buying opportunities exist when shopping for canola co-products to increase profit margins and reduce feed costs.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('f5d15f59-4d71-413b-8160-03ec5a9ec25e', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Canola mustard and rapeseed development for southern Alberta', 'Government of Alberta', 1997, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/canola-mustard-and-rapeseed-development-for-southern-alberta', 'https://open.alberta.ca/dataset/d2527f8d-0450-4b45-aba9-03c219095088/resource/d4997ec6-d05e-4dde-ac1c-c1efb25c5262/download/0163010146591-canola-mustard-and-rapeseed-development-for-southern-alberta.pdf', NULL, NULL, 141, NULL, 'southern_alberta', 5, 'Open Government Licence – Alberta', 'This project continued a breeding-related Farming for the Future Project to develop canola-quality Brassica juncea and Brassica napus lines, with early testing focused on yield, maturity, shatter resistance, and drought tolerance for southern Alberta. Field trials from 1992 to 1996 tested 67 entries, including B. juncea for dryland adaptation and high-oil B. napus for irrigated use, alongside disease screening and stand establishment studies. The revised canola definition restricted erucic acid and glucosinolate content, preventing most breeding lines from advancing, though two B. juncea lines were used in crosses. Official registration trials under irrigation and long-season zones led to the release of 57 new B. napus canola varieties. Results also showed that seed weight affected optimum seeding rates and that none of the lines tested showed clear resistance to sclerotinia under irrigation.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('2045d068-660b-438a-b496-b72203aa6360', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Clubroot disease of canola and mustard', 'Government of Alberta', 2015, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/clubroot-disease-of-canola-and-mustard', 'https://open.alberta.ca/dataset/98e74cd8-ff65-4c0a-b781-320c25600c9c/resource/91002f8e-8e37-4348-a3c4-4a2108ff0df3/download/0163310439159-clubroot-disease-of-canola-and-mustard.pdf', NULL, NULL, 8, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This factsheet provides current information about clubroot, a serious soil-borne disease affecting canola and mustard crops in Alberta. It details the disease cycle of Plasmodiophora brassicae, outlining how resting spores infect roots and cause gall formation. The document describes clubroot symptoms, including wilting, stunting, yellowing, and premature ripening, and explains how these can lead to significant yield and quality reductions. It offers comprehensive prevention and management strategies for Canadian canola growers, emphasizing long crop rotations, the use of resistant varieties, and strict sanitation practices to limit the disease''s spread.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('eca9fc0c-be1f-4216-ad97-551294d3c336', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Clubroot disease of canola and mustard (Revised September 2015)', 'Government of Alberta', 2015, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/5420474', 'https://open.alberta.ca/dataset/849d770e-37e7-4a71-976e-a0143fc13d5b/resource/46d4382f-c08d-4ed9-83be-04394269cf11/download/5420474-2015-09-agri-facts-clubroot-disease-canola-mustard.pdf', NULL, NULL, 6, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This fact sheet contains current information about clubroot in canola and describes options for Canadian canola growers to prevent this disease from being introduced and becoming well established in their fields. Clubroot disease is a serious concern in Alberta. Understanding the disease cycle, recognizing the symptoms and adopting good prevention and management practices can assist in its control.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('230dc011-2bfb-45d6-80dd-5be563c90bdf', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Controlling canola insect pests in direct seeding systems', 'Government of Alberta', 1998, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2375942', 'https://open.alberta.ca/dataset/2a1823b9-9ffb-419c-a944-c2cbd2a07415/resource/4d7b236e-1fef-4276-8579-d37a40a6d181/download/1999-519-19.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'Insect pest management in canola requires field scouting and accurate, frequent monitoring regardless of whether conventional or direct seeding systems are used.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('c648f654-6d08-4cba-a99c-bb6c6cdf6980', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Cost and returns budget for creeping red fescue - underseeded to canola', 'Government of Alberta', 2001, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/2553284', 'https://open.alberta.ca/dataset/7e4182f8-b153-40ed-9fef-b8b02e447241/resource/639623e8-7587-46e5-a2a3-6c915eed392b/download/2001-127-821-2.pdf', NULL, NULL, 2, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This budget estimates the direct income and expenses over the life of a creeping red fescue stand, on one acre of creeping red fescue underseeded to canola. These numbers are intended to assist producers in evaluating the basic financial requirements over this period. The Budget Margin must provide funds for interest, overhead and other indirect expenses as well as a return for living, loan repayment and investment. A total farm financial analysis should be completed to determine the impact of this enterprise on the total farm business.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('96de8ffe-be73-4876-8b29-61baafcc5c58', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Crop diversification with high-value perennial seed crops drives profitability in crop rotations in northwestern Canada', 'Keshav Bhattarai, Keshav Bhattarai, Nityananda Khanal, Malinda S. Thilakarathna, Newton Z. Lupwayi, Noabur Rahman, Jennifer Otani, Bharat Shrestha', 2026, 'Frontiers in Agronomy', '10.3389/fagro.2025.1732922', 'https://doi.org/10.3389/fagro.2025.1732922', 'https://www.frontiersin.org/articles/10.3389/fagro.2025.1732922/full', NULL, NULL, 15, NULL, 'southern_alberta', 4, 'open access (DOAJ)', 'Cropping system diversification is considered a rational management practice for improving resource-use efficiency, enhancing productivity, and optimizing farm returns in the face of climate change. However, few studies have concurrently explored the productivity, profitability, and nitrogen use efficiency (NUE) of cropping systems diversified with perennial forage seed crops. This study, conducted on dark gray Luvisolic soil in the Peace River region of northwestern Canada from 2013 to 2024, sought to address this gap. A field experiment, arranged in a split-plot design, comprised eight cropping sequences as main plots and three nitrogen (N) levels (0, 45, and 90 kg N ha-1) as sub-plots. The cropping sequences included two perennial legumes (red clover and alsike clover), three perennial grasses (creeping red fescue, meadow bromegrass, and timothy), and four annual field crops (wheat, canola, pea, and barley). Productivity was evaluated based on seed yield and expressed as canola equivalent yield (CEY), while gross revenue and gross margin were used as profitability metrics. Based on CEY and aboveground biomass yield, NUE was also assessed for uniform comparison among cropping sequences. Intermittent inclusion of red clover (a perennial legume) and meadow bromegrass (a perennial vernalizing grass) in the cropping sequence increased CEY, gross revenue, gross margin, and agronomic NUE by 95-108%, 118-174%, 191-255%, and 21–77%, respectively, compared with alternating annual wheat-canola sequences across three N fertility levels. The higher seed price of red clover and greater seed yield and price of meadow bromegrass during their production phases provided opportunities to capitalize on local market demands. The N fertilization at 45 kg N ha-1 improved the yield and profitability across all cropping sequences, whereas the 90 kg N ha-1 rate did not result in significant economic benefits in comparison. Our results provide evidence that forage seed crop-based cropping systems have the potential to reduce reliance on external N inputs and enhance the economic efficiency of production systems.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('89eb5930-cd4c-4700-87ab-ef86d167c542', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Development of processing methods to enhance the utilization of full-fat canola in ruminant diets', 'Government of Alberta', 1996, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/development-of-processing-methods-to-enhance-the-utilization-of-full-fat-canola-in-ruminant-die', 'https://open.alberta.ca/dataset/32773861-c3bc-43d7-90cb-0b4ee1f2f328/resource/4dbe59ac-cc5e-4184-a448-3c7d45ac5bc2/download/0163010148100-development-processing-methods-enhance-utilization-full-fat-canola-ruminant-die.pdf', NULL, NULL, 83, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This document reported the findings of a research project that examined processing methods to enhance the utilization of full fat canola seed in ruminant diets. It described the objectives, scope, and methods of a series of in vitro, in situ, and total tract digestion studies that evaluated the effects of micronization and mechanical processing on dry matter and protein utilization. The scope included laboratory fermentation tests, ruminal and intestinal disappearance measurements using cannulated cattle, and microscopic examination of structural changes in canola seed. The document presented results, discussion, and conclusions on how micronization altered ruminal degradability and shifted protein digestion toward the intestine. It also discussed the significance of the findings for improving the value of full fat canola as a protein and energy source for ruminant livestock in Alberta.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('1e494e84-782a-43bf-a4bf-e87760beed68', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Development of specific probes for an important oil formation enzyme in canola', 'Government of Alberta', 1992, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/development-of-specific-probes-for-an-important-oil-formation-enzyme-in-canola', 'https://open.alberta.ca/dataset/31a5a076-4331-4d33-b752-025f96809553/resource/4ac8e11f-87c7-4e92-840d-60d52adaa2ab/download/0163003023963-development-of-specific-probes-for-an-important-oil-formation-enzyme-in-canola.pdf', NULL, NULL, 64, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'This project investigated the purification and characterization of diacylglycerol acyltransferase (DGAT), an enzyme responsible for the final step in seed oil biosynthesis, from Brassica napus microspore-derived embryos and embryogenic cell suspension cultures. Researchers developed purification protocols using membrane dispersion, anion exchange chromatography, and detergent extraction to isolate various DGAT forms. Specific activity assays and immunological approaches, including polyclonal and monoclonal antibody production, were used to probe the enzyme and assess cross-species reactivity. While monoclonal antibodies showed limited inhibition of DGAT, the study suggested further potential in using embryogenic cell cultures and denatured DGAT as sources for scale-up and probe development. Overall, the findings contributed valuable tools for identifying and manipulating DGAT to improve seed oil content in canola.', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('867c36ca-be13-42fe-819f-48cf29b7966a', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Diet medication and beta-glucanase affect ileal digesta soluble beta-glucan molecular weight, carbohydrate fermentation, and performance of coccidiosis vaccinated broiler chickens given wheat-based diets', 'Karunaratne ND, Classen HL, van Kessel AG, Bedford MR, Ames NP, Newkirk RW', 2023, 'Animal nutrition (Zhongguo xu mu shou yi xue hui)', '10.1016/j.aninu.2023.03.013', 'https://doi.org/10.1016/j.aninu.2023.03.013', 'https://europepmc.org/articles/PMC10684992?pdf=render', NULL, NULL, 9, NULL, 'prairies', 4, 'cc by-nc-nd', 'Exogenous enzymes as alternatives to feed antibiotics in poultry has become an emerging research area with the emergence of antibiotic resistance. The objective was to evaluate the effects of diet medication (antibiotics) and β-glucanase (BGase) on digesta soluble β-glucan depolymerization, carbohydrate fermentation, and performance of coccidiosis-vaccinated broiler chickens fed wheat-based diets. A total of 1,782 broilers were raised on litter floor pens, and each treatment was assigned to 1 pen in each of the 9 rooms. The 3 dietary treatments were based on wheat as the sole grain (control, control + medication and control + 0.1% BGase), and the birds were fed the respective treatments ad libitum from 0 to 33 d. Treatments were arranged in a randomized complete block design and analyzed as a one-way ANOVA. Beta-glucanase reduced the peak molecular weight, weight average molecular weight (Mw) and maximum molecular weight for the smallest 10% β-glucan molecules (MW-10%) in ileal digesta at d 11 and 33, whereas diet medication reduced Mw and MW-10% at d 33 compared to the control (P P = 0.010). Ileal propionic acid concentration at d 11 and caecal total SCFA, acetic, and butyric acid concentrations at d 33 were lower in the BGase-supplemented diet than in the control (P P = 0.026). The effect of medication on carbohydrate fermentation was minimal. Diet medication increased weight gain after d 11, whereas BGase increased the gain for the total trial period compared to the control (P P P < 0.001). In conclusion, diet medication and BGase depolymerized high molecular weight ileal soluble β-glucan and increased overall bird performance. Dietary BGase may benefit bird health in broilers fed wheat-based diets without medication.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8cc88466-b198-47a6-987b-df896bfa5d34', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Disease forecasting for Sclerotinia white stem rot in canola', 'Government of Alberta', 2007, 'Alberta Agriculture and Irrigation', NULL, 'https://open.alberta.ca/publications/3989716', 'https://open.alberta.ca/dataset/cfca3e34-a7ca-4953-9f71-0cf196e0b8db/resource/48de1922-69a0-4a33-9da7-6544344cb2f0/download/2007-149-632-4.pdf', NULL, NULL, 4, NULL, 'alberta', 4, 'Open Government Licence – Alberta', 'A round five million acres of canola are now grown annually in Alberta. Sclerotinia white stem rot is one of the most destructive diseases of this crop. To help canola growers predict outbreaks of sclerotinia white stem rot, a disease forecast system was developed. The forecast system is a checklist that assists growers to make a decision on the need for applying a foliar fungicide. The check list came into being as a consequence of disease control trials carried out in 1981 and 1982', '{open-alberta,extension,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('6e40fead-1c28-45be-be7c-3be391285308', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Evaluating the potential for snowmelt phosphorus losses from perennial forage crops', 'Wilson H, Elliott J, Macrae M, Kokulan V, Glenn A', 2025, 'Journal of environmental quality', '10.1002/jeq2.70022', 'https://doi.org/10.1002/jeq2.70022', 'https://europepmc.org/articles/PMC12431946?pdf=render', NULL, NULL, 11, NULL, 'prairies', 4, 'cc by-nc', 'In cold regions, there is concern that losses of P with snowmelt runoff following freeze and thaw of vegetation may be greater from perennial forages relative to annual crops. We evaluate the drivers of P losses with snowmelt runoff over a network of field-scale small watersheds in Manitoba, Canada, following annual crops (59 site-years), perennial forage (19 site-years), or tillage to terminate a forage (4 site-years). Vegetation type was not significantly related to concentrations of P lost in snowmelt or load (p > 0.05), and 0-5 cm Olsen-P in soil was the best predictor of flow-weighted mean concentrations of total dissolved P (r2 = 0.46, p 2 = 0.45, p < 0.001) across the 82 site-years of data. Sites having a recent (10-year) land use history without tillage had greater P stratification in the top 5 cm of soil than those with tillage, irrespective of vegetation type (p < 0.001). Residual variation in snowmelt P concentration and loads were negatively related to water yield and positively related to proportion of soil surface area covered by crop residue (independent of type of residue). Loads of P exported with snowmelt were primarily a function of water yield, and at a similar level of snow water equivalent, perennial forages exhibit lower water yield than annual crop sites. These results suggest that with careful management of soil P, adding perennial plants to crop rotations will not increase losses of P with snowmelt and through impacts on hydrology, reductions in overall loading may occur.', '{epmc,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('8d7d2959-cc99-4c33-8b85-fff360fd22ed', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'Earlier crop flowering caused by global warming alleviated by irrigation', 'Albert Muleke, Matthew Tom Harrison, Peter de Voil, Ian Hunt, Ke Liu, Maria Yanotti, Rowan Eisner', 2022, 'Environmental Research Letters', '10.1088/1748-9326/ac5a66', 'https://doi.org/10.1088/1748-9326/ac5a66', 'https://doi.org/10.1088/1748-9326/ac5a66', NULL, NULL, 17, NULL, 'other', 1, 'open access (DOAJ)', 'Enabling crop flowering within an optimal calendar window minimises long-term risk of abiotic stress exposure, improving prospects for attaining potential yield. Here, we define the optimal flowering period (OFP) as the calendar time in which long-term risk of frost, water and heat stress are collectively minimised. Using the internationally-renowned farming systems model Agricultural Systems Production Systems sIMulator, we characterised combined effects of climate change and extreme climatic events on the OFPs of barley, durum wheat, canola, chickpeas, fababean and maize from 1910 to 2021. We generate response surfaces for irrigated and dryland conditions using a range of representative sowing times for early and late maturity genotypes. Global warming truncated crop lifecycles, shifting forward flowering of winter crops by 2–43 d in dryland environments, and by −6–19 d in environments with irrigation. Alleviation of water stress by irrigation delayed OFPs by 3–25 d or 11–30 d for early and late maturity winter crops, respectively, raising average yields of irrigated crops by 44%. Even so, irrigation was unable to completely negate the long-term yield penalty caused by the climate crisis; peak yields respectively declined by 24% and 13% for rainfed and irrigated crops over the 111 years simulation duration. We conclude with two important insights: (a) use of irrigation broadens OFPs, providing greater sowing time flexibility and likelihood of realising potential yields compared with dryland conditions and (b), the most preferable maturity durations for irrigated winter and summer crops to maximise potential yields are early-sown long-season (late) and later-sown short-season (early) maturity types, respectively.', '{doaj,crop}', 'link_only', NULL, NULL, '2026-11-19 05:15:48.68967+00', 'pending', NULL, NULL, NULL, NULL);
INSERT INTO public.research_papers (id, folder_id, title, authors, year, source, doi, source_url, pdf_url, storage_path, file_bytes, pages, sha256, region, relevance, licence, abstract, tags, status, fetch_note, added_by, created_at, text_status, text_chars, text_chunks, text_note, text_read_at) VALUES ('b23ac2a6-f56c-428e-9479-52a829d9f606', '9cb41128-a672-4e16-a128-a17adc65c5cb', 'ECONOMIC EVALUATION OF RESPONSE TO SOME OF THE CANOLA VARIETIES USING MODERN IRRIGATION SYSTEMS AT SHALATEEN AREA. A CASE STUDY OF THE EXPERIENCE OF GROWING CANOLA RESEARCH STATION SHALATEEN))', 'Fekry Mohamed El-Said El-Boray, Rafat Hassan Mostafa', 2011, 'Fayoum Journal of Agricultural Research and Development', '10.21608/fjard.2011.195495', 'https://doi.org/10.21608/fjard.2011.195495', 'https://fjard.journals.ekb.eg/article_195495_2c34fa06a9958156b5b2f6ff6e52ddfd.pdf', NULL, NULL, NULL, NULL, 'other', 1, 'open access (DOAJ)', 'Respect to this research study the response of some types of canola tomodern irrigation systems (trickle-Sprinkler) and using the densities ofvarious plant is in the distance between the injustice (10 - 20-30 cm) in thedesert lands in the new Research Station Shalatin of the Desert Research Center during the two seasons 2008/2009 and 2009/2010, it became clear thatthe soil which made it look as sandy limestone (93.3% sand) and water usedfor irrigation of the third degree where the proportion of salinity (1184 ppm)that have been carried out the experiment in the winter season. It should benoted that the amount of water disposal system for each of the irrigationsystems were based on measuring the difference between soil moisture. Andinclude all the experience of two variables, one species, where he studied twotypes, one local, sero 4 and the second Imported from France, Bactul and thesecond variable is the distance between the injustice on the same line which is10.20, 30 cm and summarized the results obtained from this study are asfollows:1- A seed yield and oil /