INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('3914b1e2-396c-4c1c-afa1-9aa757ebd9f9', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 120, 'sandy clay', 206, 82, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('c0fc80d9-c161-4883-bc88-3bf02bb01edb', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 120, 'silty clay', 254, 101, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('da4f8bdc-fca3-42e5-866c-1b9aa70a17a4', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 120, 'clay', 230, 92, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('330ec791-0786-48d8-b539-80055401a436', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'loamy sand', 57, 23, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('f5495bdd-b344-4461-8e0d-f7614384f2b9', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'sandy loam', 70, 28, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('374b1739-e79b-447f-80a8-fc076ba0dabe', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'loam', 90, 36, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('e44a7ac1-9a10-4547-a4b9-5a982b785567', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'sandy clay loam', 76, 30, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('3ec8aff2-23f7-447b-822f-060418820f86', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'silt loam', 100, 40, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('654de859-6b73-4a0f-a42f-ca9876ae27ab', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'clay loam', 100, 40, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('b6489aff-4632-461c-8ee2-964aae3c5bde', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'silty clay loam', 110, 44, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('5284145e-b996-40fe-a3d8-25d1cf4e6a33', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'sandy clay', 86, 35, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('5e1b739b-2d4e-471b-a362-de463c24a8fc', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'silty clay', 106, 43, 40.0);
INSERT INTO public.crop_irrigation_refill (id, sheet_id, depth_cm, texture, taw_mm, refill_mm, depletion_pct) VALUES ('292e20e7-dfd2-402e-b0c2-1fd837706d08', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 50, 'clay', 96, 39, 40.0);
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('35be6a80-d97d-4676-ab83-a079765f9a6a', '369b5512-d1d0-4372-bd2b-08b00f8bf4d9', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'The 0-50 cm should be above 60 per cent at planting. Seeded dry in late April, give light 15 mm passes as soon as water is available to stop the surface crusting.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('53e287b5-c4fb-43d1-8ba4-a7464cae18bb', '369b5512-d1d0-4372-bd2b-08b00f8bf4d9', 'dev', 2, 'Tillering to late boot', 50, 65.0, 60.0, 'Start near 65 per cent so it never falls below 60. Light and frequent, while building the 50-100 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('c4658fb3-ab32-4734-b045-22ece05e8050', '369b5512-d1d0-4372-bd2b-08b00f8bf4d9', 'mid', 3, 'Early heading to fruit formation', 100, 60.0, 60.0, 'Step the reading depth to 100 cm at early heading. Fill the whole 100 cm to field capacity at late boot whether or not the trigger has been reached -- that keeps the canopy dry through flowering, when fusarium head blight strikes. Next pass about 10 days after first flower.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('34f2ad3b-c73b-47ca-a940-8b4f66801832', '369b5512-d1d0-4372-bd2b-08b00f8bf4d9', 'late', 4, 'Soft dough to maturity', 100, NULL, 60.0, 'About 80 mm of water carries barley from soft dough to physiologic maturity.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('ff76cd19-b97d-47e2-9da3-8be75f62a29e', '31b9cc41-a210-401f-803d-b50f99f90aa6', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'The 0-50 cm should be above 60 per cent at planting. Seeded dry in late April, give light 15 mm passes as soon as water is available.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('80c4f71d-e376-4bd8-9c3c-e28d4ac863fb', '31b9cc41-a210-401f-803d-b50f99f90aa6', 'dev', 2, 'Tillering to late boot', 50, 65.0, 60.0, 'Start near 65 per cent so it never falls below 60, and build the 50-100 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('a13f08c6-8f86-4192-82bf-d575cd4ec5fa', '31b9cc41-a210-401f-803d-b50f99f90aa6', 'mid', 3, 'Early heading to fruit formation', 100, 60.0, 60.0, 'Step the reading depth to 100 cm at late boot to early heading, and fill the whole zone to field capacity then whether or not the trigger has been reached -- fusarium head blight follows a wet canopy at flowering. Next pass about 10 days after first flower.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('4680af0e-b4e5-4e51-a2aa-95d9807b019c', '31b9cc41-a210-401f-803d-b50f99f90aa6', 'late', 4, 'Soft dough to maturity', 100, NULL, 60.0, 'About 80 mm of water carries spring wheat from soft dough to physiologic maturity.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('03cab67e-f656-4215-adfb-3427fffbee86', '993a450a-b019-49e3-bb4c-d6c9a2117f2d', 'ini', 1, 'Seeding to freeze-up', 30, NULL, 60.0, 'Irrigate before seeding rather than after: the seedbed wants to be near 80 per cent of field capacity, and a pass on a seeded field crusts it.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('9e78ae28-2ead-4c72-bfc3-82c2213e2d9b', '993a450a-b019-49e3-bb4c-d6c9a2117f2d', 'dev', 2, 'Tillering to late boot', 50, 60.0, 50.0, 'Winter wheat is the one crop Alberta lets run to 50 per cent before heading -- start near 60. Its shallow refill table is quoted at 50 per cent depletion for that reason.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('b1312a01-1ad9-439b-94e2-732f95793676', '993a450a-b019-49e3-bb4c-d6c9a2117f2d', 'mid', 3, 'Early heading to fruit formation', 100, 60.0, 60.0, 'From early heading the floor rises to 60 per cent over the full 100 cm. Fill the whole zone at late boot to early heading whether or not the trigger has been reached, to keep the canopy dry through flowering (fusarium head blight).');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('8c5228d7-5fb8-4502-9039-cafc709c3c8c', '993a450a-b019-49e3-bb4c-d6c9a2117f2d', 'late', 4, 'Soft dough to maturity', 100, NULL, 60.0, 'About 80 mm of water carries winter wheat from soft dough to physiologic maturity.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('d1d523ec-aad0-4fec-a90d-6e917dff8e5b', 'b3b696ab-c721-4cee-ab97-d7265fe63201', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'The 0-50 cm should be above 60 per cent at planting. Seeded into moist soil, do not irrigate before emergence -- the crust costs plants.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('e4b1c7c4-315d-45da-a49b-c7b616eded43', 'b3b696ab-c721-4cee-ab97-d7265fe63201', 'dev', 2, 'Seedling, rosette and elongation', 50, NULL, 60.0, 'Keep the upper 50 cm above 60 per cent and build the 50-100 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('bb10a4a5-d311-49fb-a4d4-6a8a27e377e4', 'b3b696ab-c721-4cee-ab97-d7265fe63201', 'mid', 3, 'Flowering and pod set', 100, NULL, 60.0, 'Step the reading depth to 100 cm at flowering: fewer, larger passes keep the canopy dry, which discourages sclerotinia. Flowering lasts about 30 days and is where water stress costs the most yield. Fungicide at 20 to 30 per cent bloom; stop irrigating if sclerotinia is severe.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('50abc0e0-1b99-4324-b162-73af6b1563ee', 'b3b696ab-c721-4cee-ab97-d7265fe63201', 'late', 4, 'Pod development and ripening', 100, NULL, 60.0, 'Depletion below 60 per cent at any stage costs seed yield and oil content.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('99e81c45-7d9a-44ed-9199-e3e1fe5bc3f7', '1d19d47c-654a-46ec-ac7a-1c3e4ebbc50c', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'Seed into soil warmer than 10 degrees with the 0-50 cm above 60 per cent. Seeded dry in early May, light 15 mm passes as soon as water is available.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('5fd5ce7b-90ea-4441-b608-3fb24091b979', '1d19d47c-654a-46ec-ac7a-1c3e4ebbc50c', 'dev', 2, 'Leaf production (pre-tasseling)', 50, 65.0, 60.0, 'Start near 65 per cent so the upper 50 cm never falls below 60, and build the 50-100 cm zone for the late-June to mid-August peak.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('56f68ec2-785d-44bf-b451-8cb6ac333c1e', '1d19d47c-654a-46ec-ac7a-1c3e4ebbc50c', 'mid', 3, 'Tasseling and silking', 50, 65.0, 60.0, 'The reading depth stays at 50 cm through silking. This is where stress hurts most: dry silks and pollen mean poor pollination and barren ear tips.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('a8700540-07f2-4d1b-b1fc-237b053d0dc9', '1d19d47c-654a-46ec-ac7a-1c3e4ebbc50c', 'late', 4, 'Blister kernel to dent', 100, NULL, 60.0, 'Step the reading depth to 100 cm at blister kernel -- fewer, larger passes from there on.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('1fa602ce-5b19-43b5-8fc9-48fa547bc59d', '9cd8b33f-c238-4e2f-a378-a998161b7a96', 'ini', 1, 'Seedbed and emergence', 50, NULL, 60.0, 'Best is a 0-50 cm near 80 per cent at planting -- the seed goes in 2.5 cm deep, so a dry surface costs the stand. Seeded dry in late April, light 15 mm passes from early May.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('d7a7a7a4-ea4f-4f57-a7de-3c3b7543cab7', '9cd8b33f-c238-4e2f-a378-a998161b7a96', 'dev', 2, 'Emergence to canopy closure (16-leaf)', 50, 65.0, 60.0, 'Keep the upper 50 cm above 60 per cent and the crop closes canopy early. Build the 50-100 cm zone for the July peak.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('cb306489-fb4a-42df-a8a5-d4e228131b5b', '9cd8b33f-c238-4e2f-a378-a998161b7a96', 'mid', 3, 'Full canopy closure and root enlargement', 100, 65.0, 60.0, 'Step the reading depth to 100 cm at full canopy closure: fewer, larger passes, reaching the mature roots.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('696caacf-c74a-4325-a0f9-304891a5b0fc', '9cd8b33f-c238-4e2f-a378-a998161b7a96', 'late', 4, 'Leaf die-back to harvest', 100, 65.0, 60.0, 'Demand falls as the old leaves die and the weather cools.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('53cf099f-3ff1-495e-85e8-5c698124be0d', '2c067854-1bb3-4dfd-88ce-3fb522283a42', 'ini', 1, 'Planting to emergence', 30, NULL, 65.0, 'Do not irrigate between planting and emergence: a wet seed piece invites soil disease organisms.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('14ed9f47-bb74-4c73-b75a-faf9b5520fa6', '2c067854-1bb3-4dfd-88ce-3fb522283a42', 'dev', 2, 'Tuber initiation', 30, 70.0, 70.0, 'The one stage with a 70 per cent floor rather than 65. Potato is most sensitive to stress here, and starting at 70 raises the number of tubers per plant. Reservoir tillage (dammer dyking) evens the water out across the field.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('9f3a0220-2bf6-4b75-9a7d-f6644dd6fa3b', '2c067854-1bb3-4dfd-88ce-3fb522283a42', 'mid', 3, 'Tuber bulking', 60, 65.0, 65.0, 'Hold between 65 and 100 per cent. Outside that band costs marketable yield and brings hollow heart, knobbiness and cracks.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('8711ff04-b2aa-4fbf-b5a8-af2200c6b17d', '2c067854-1bb3-4dfd-88ce-3fb522283a42', 'late', 4, 'Maturation and harvest', 60, 65.0, 65.0, 'Keep near 65 per cent for digging -- drier than that and the tubers bruise.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('174c5cc5-4400-4ee0-ab82-c94031b2c414', '38f91e7b-a6e7-4127-b7cf-0f2e61da8ffd', 'ini', 1, 'Seedbed and emergence', 40, NULL, 60.0, 'The 0-40 cm should be above 60 per cent at planting. Seed early so the crop flowers before the summer heat.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('7aa127f5-3cb8-4718-aa22-0ab551738c64', '38f91e7b-a6e7-4127-b7cf-0f2e61da8ffd', 'dev', 2, 'Vegetative', 40, NULL, 60.0, 'Manage the 40 cm zone -- light and frequent -- while building the 40-70 cm zone towards field capacity for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('b8268425-6ed9-42f0-b54d-71e3a11ce1de', '38f91e7b-a6e7-4127-b7cf-0f2e61da8ffd', 'mid', 3, 'Flowering and pod set', 70, NULL, 60.0, 'Step the reading depth from 40 to 70 cm at first flower. Stress here aborts flowers and pods; water now sets the number of pods and seeds per pod.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('807bb563-ecc2-4a1f-b411-409c23b668f5', '38f91e7b-a6e7-4127-b7cf-0f2e61da8ffd', 'late', 4, 'Pod development and pod fill', 70, NULL, 60.0, 'Water at pod development puts weight into the pods and seeds. Fewer, larger passes keep the soil surface dry, which discourages fungal disease.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('491d44bf-af4d-4333-8441-14be811e2d88', 'e6232619-25b0-4328-97cc-06941b8f5cde', 'ini', 1, 'Seedbed and emergence', 30, NULL, 60.0, 'Best is a 0-60 cm profile near field capacity at planting. If the top 10 cm is dry, a 15 mm pass BEFORE seeding; never just after, which crusts the soil and costs plants.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('931cfe67-da38-4cdb-91c3-cfd9e0c087db', 'e6232619-25b0-4328-97cc-06941b8f5cde', 'dev', 2, 'Vegetative (pre-flowering)', 30, NULL, 60.0, 'Manage the 30 cm zone, not the 60 -- light and frequent passes close the canopy faster and mature the crop earlier. Build the 30-60 cm zone for flowering.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('19eeb806-eb9d-4705-bc96-9ba11cf1dfe0', 'e6232619-25b0-4328-97cc-06941b8f5cde', 'mid', 3, 'Flowering and pod set', 60, NULL, 60.0, 'Step the reading depth from 30 to 60 cm at flowering. Stress here aborts flowers and pods.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('a3696dcb-a513-4e1c-9346-c20839967a69', 'e6232619-25b0-4328-97cc-06941b8f5cde', 'late', 4, 'Pod fill and maturation', 60, NULL, 60.0, 'Fill the whole 60 cm zone at the start of pod fill so the crop needs few passes through the white-mould window. If mould weather sets in (cloudy and humid), soil water may go to near 50 per cent during pod fill without a significant yield loss.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('63b1ad35-d83c-48b4-8e9b-a969a5ff8921', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 'ini', 1, 'Regrowth after cutting', 120, NULL, 60.0, 'A full pass goes on immediately after the first and second cut -- water to the roots is what lets the stand recover from defoliation.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('50b72fca-f2e8-400f-82d9-3e85a1641197', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 'dev', 2, 'Vegetative', 120, NULL, 60.0, 'Keep the 120 cm zone above 60 per cent. Peak use is nearly 9 mm a day for the first cut, 8 for the second, 7 for the third.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('9904c428-6410-4508-b09e-b95918f48d03', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 'mid', 3, 'Bud to early bloom', 120, NULL, 60.0, 'Fill the whole root zone to 100 per cent of available, especially through a hot, dry July.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('5580fad2-275d-40f4-8b6c-2f10248b5ee9', 'd4b8db0e-be48-4d73-ac2f-988ed7bf78af', 'late', 4, 'Cutting and after', 120, NULL, 60.0, 'Aim for about 70 per cent at harvest, and again when the third cut is off after the first killing frost -- the taproots are storing carbohydrates for winter and spring.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('eeb1682d-5612-40c5-ae5b-6721ce1bf4d3', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 'ini', 1, 'Emergence and regrowth', 30, NULL, 60.0, 'Hold the 0-30 cm above 60 per cent. Light 12 mm passes recharge that zone without runoff.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('48b2c35f-506c-402e-bbcc-eaa44738ca84', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 'dev', 2, 'Tillering to boot', 30, 65.0, 60.0, 'Start near 65 per cent so the 30 cm zone never falls below 60.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('2dda87e0-3d58-4b03-92bc-9e40395ed964', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 'mid', 3, 'Full head and flowering', 50, 65.0, 60.0, 'Step the reading depth from 30 to 50 cm at the full head stage, and fill the 0-50 cm to field capacity at early heading. Peak use is nearly 8 mm a day for the first cut and 6 for the second.');
INSERT INTO public.crop_irrigation_stages (id, sheet_id, phase, seq, stage_label, monitor_depth_cm, start_pct, floor_pct, note) VALUES ('5a2b1513-9b2d-47ec-a9d3-29198f9f100f', 'a3292ed8-3689-4bf2-bfac-af15bab54d05', 'late', 4, 'After cutting', 50, 65.0, 60.0, 'A full pass goes on right after the first cut in early July, with about 60 per cent of the spring nitrogen rate, and again after the second cut.');
